INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-1', 'en', 'Bài 1: Giáo dục & Trường học (1) - CEFR B2', 'CEFR B2', 'B2 · Giáo dục', '28 từ vựng Tiếng Anh CEFR B2 chủ đề giáo dục & trường học kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4001, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_motivate', 'en-b2-1', 'motivate', '/ˈmoʊtɪveɪt/', 'B2', 'thúc đẩy; truyền động lực; làm động cơ cho; thúc đẩy hành động', 'v.', 'motivation (n.), motivated (adj.), motivating (adj.), motivational (adj.)', 'Đồng nghĩa: inspire, encourage · Trái nghĩa: discourage, demotivate', 'Thường dùng motivate sb to do; từ by có thể được nối tiếp theo sau để chỉ động cơ.', 'Training with a friend motivates me to exercise regularly.', NULL, 'Tập luyện cùng một người bạn thúc đẩy tôi chăm chỉ tập thể dục đều đặn.', '{"wordId":"motivate","ukIpa":"/ˈməʊtɪveɪt/","usIpa":"/ˈmoʊtɪveɪt/","cefr":"B2","topic":"education","senses":[{"pos":"v.","en":"to make someone eager to do something","vi":"thúc đẩy; truyền động lực"},{"pos":"v.","en":"to provide the reason for someone''s actions","vi":"làm động cơ cho; thúc đẩy hành động"}],"examples":[{"en":"Training with a friend motivates me to exercise regularly.","vi":"Tập luyện cùng một người bạn thúc đẩy tôi chăm chỉ tập thể dục đều đặn.","audioKind":"ex"},{"en":"Teachers can motivate students to explore difficult subjects by connecting classroom lessons with everyday experiences.","vi":"Giáo viên có thể truyền động lực cho học sinh khám phá các môn học khó bằng cách kết nối bài học trên lớp với những trải nghiệm hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"motivate someone to do something","vi":"thúc đẩy ai đó làm điều gì"},{"en":"highly motivated","vi":"có động lực cao"},{"en":"be motivated by","vi":"bắt nguồn từ; được thúc đẩy bởi"}],"wordFamily":["motivation (n.)","motivated (adj.)","motivating (adj.)","motivational (adj.)"],"synonyms":["inspire","encourage"],"antonyms":["discourage","demotivate"],"tipVi":"Thường dùng motivate sb to do; từ by có thể được nối tiếp theo sau để chỉ động cơ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_novice', 'en-b2-1', 'novice', '/ˈnɑːvɪs/', 'B2', 'người mới bắt đầu; người có ít kinh nghiệm', 'n.', NULL, 'Đồng nghĩa: beginner, newcomer · Trái nghĩa: expert, veteran', 'Để chỉ người mới trong một lĩnh vực cụ thể, thường dùng cấu trúc a novice at hoặc a novice in.', 'As a gardening novice, I often forget to water seedlings.', NULL, 'Là một người mới tập tọe làm vườn, tôi thường quên tưới nước cho cây con.', '{"wordId":"novice","ukIpa":"/ˈnɒvɪs/","usIpa":"/ˈnɑːvɪs/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"someone with little experience in a particular activity","vi":"người mới bắt đầu; người có ít kinh nghiệm"}],"examples":[{"en":"As a gardening novice, I often forget to water seedlings.","vi":"Là một người mới tập tọe làm vườn, tôi thường quên tưới nước cho cây con.","audioKind":"ex"},{"en":"Structured mentoring can help a novice develop the confidence needed to manage a classroom effectively.","vi":"Việc cố vấn có bài bản có thể giúp một giáo viên mới vào nghề xây dựng sự tự tin cần thiết để quản lý lớp học hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"a complete novice","vi":"một người hoàn toàn mới bắt đầu"},{"en":"a novice driver","vi":"tài xế mới"},{"en":"a novice at","vi":"kẻ ngoại đạo trong lĩnh vực gì"}],"wordFamily":[],"synonyms":["beginner","newcomer"],"antonyms":["expert","veteran"],"tipVi":"Để chỉ người mới trong một lĩnh vực cụ thể, thường dùng cấu trúc a novice at hoặc a novice in.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nursery', 'en-b2-1', 'nursery', '/ˈnɝːsəri/', 'B2', 'nhà trẻ; trường mẫu giáo; vườn ươm cây giống; phòng trẻ em', 'n.', NULL, NULL, 'Trong tiếng Anh Anh, at nursery thường mang nghĩa ở nhà trẻ.', 'My daughter painted a bright yellow duck at nursery.', NULL, 'Con gái tôi đã vẽ một chú vịt màu vàng tươi ở nhà trẻ.', '{"wordId":"nursery","ukIpa":"/ˈnɜːsəri/","usIpa":"/ˈnɝːsəri/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"a place where young children are cared for","vi":"nhà trẻ; trường mẫu giáo"},{"pos":"n.","en":"a place where young plants are grown for sale","vi":"vườn ươm cây giống"},{"pos":"n.","en":"a room in a home for a baby or young child","vi":"phòng trẻ em"}],"examples":[{"en":"My daughter painted a bright yellow duck at nursery.","vi":"Con gái tôi đã vẽ một chú vịt màu vàng tươi ở nhà trẻ.","audioKind":"ex"},{"en":"Affordable nursery places allow more parents to return to work while their children receive professional care.","vi":"Các cơ sở nhà trẻ với mức giá phải chăng giúp nhiều phụ huynh có thể quay lại làm việc trong khi con cái họ được chăm sóc chuyên nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"nursery school","vi":"trường mẫu giáo"},{"en":"nursery staff","vi":"nhân viên nhà trẻ"},{"en":"plant nursery","vi":"vườn ươm cây"},{"en":"nursery rhyme","vi":"bài thơ thiếu nhi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh Anh, at nursery thường mang nghĩa ở nhà trẻ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scholar', 'en-b2-1', 'scholar', '/ˈskɑːlər/', 'B2', 'học giả; nhà nghiên cứu; người nhận học bổng', 'n.', 'scholarly (adj.), scholarship (n.)', 'Đồng nghĩa: academic', 'scholar thường chỉ học giả, không dùng cho học sinh thông thường.', 'The scholar carefully examined an old book in the library.', NULL, 'Vị học giả cẩn thận nghiên cứu một cuốn sách cổ trong thư viện.', '{"wordId":"scholar","ukIpa":"/ˈskɒlə/","usIpa":"/ˈskɑːlər/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"A person with deep knowledge of an academic subject.","vi":"học giả; nhà nghiên cứu"},{"pos":"n.","en":"A student awarded money to study because of their abilities.","vi":"người nhận học bổng"}],"examples":[{"en":"The scholar carefully examined an old book in the library.","vi":"Vị học giả cẩn thận nghiên cứu một cuốn sách cổ trong thư viện.","audioKind":"ex"},{"en":"Scholars increasingly argue that access to early education can reduce social inequality over the long term.","vi":"Các học giả ngày càng lập luận rằng việc tiếp cận giáo dục sớm có thể làm giảm bất bình đẳng xã hội về lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"a leading scholar","vi":"một học giả hàng đầu"},{"en":"a visiting scholar","vi":"một học giả thỉnh giảng"},{"en":"a distinguished scholar","vi":"một học giả nổi tiếng"}],"wordFamily":["scholarly (adj.)","scholarship (n.)"],"synonyms":["academic"],"antonyms":[],"tipVi":"scholar thường chỉ học giả, không dùng cho học sinh thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reference', 'en-b2-1', 'reference', '/ˈrefərəns/', 'B2', 'sự nhắc đến; ý nhắc tới; tài liệu tham khảo; sự tra cứu; thư giới thiệu; người giới thiệu', 'n.', 'refer (v.)', NULL, 'reference to dùng để chỉ việc nhắc đến; for reference có nghĩa là để tham khảo.', 'Her speech included a warm reference to her grandmother.', NULL, 'Bài phát biểu của cô ấy có chứa một lời nhắc đến đầy tình cảm dành cho người bà của mình.', '{"wordId":"reference","ukIpa":"/ˈrefrəns/","usIpa":"/ˈrefərəns/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"a mention of someone or something","vi":"sự nhắc đến; ý nhắc tới"},{"pos":"n.","en":"consultation for information, or a source used in writing","vi":"tài liệu tham khảo; sự tra cứu"},{"pos":"n.","en":"a recommendation or someone who recommends you for work","vi":"thư giới thiệu; người giới thiệu"}],"examples":[{"en":"Her speech included a warm reference to her grandmother.","vi":"Bài phát biểu của cô ấy có chứa một lời nhắc đến đầy tình cảm dành cho người bà của mình.","audioKind":"ex"},{"en":"Academic essays should include accurate references so readers can locate the original sources of information.","vi":"Các bài luận học thuật nên bao gồm các tài liệu tham khảo chính xác để người đọc có thể tìm ra nguồn gốc của thông tin.","audioKind":"ex2"}],"collocations":[{"en":"make reference to","vi":"nhắc đến; có liên quan đến"},{"en":"for future reference","vi":"để tham khảo sau này"},{"en":"provide a reference","vi":"cung cấp thư giới thiệu"}],"wordFamily":["refer (v.)"],"synonyms":[],"antonyms":[],"tipVi":"reference to dùng để chỉ việc nhắc đến; for reference có nghĩa là để tham khảo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_subheading', 'en-b2-1', 'subheading', '/ˈsʌbhedɪŋ/', 'B2', 'tiêu đề phụ; đề mục nhỏ', 'n.', 'heading (n.), head (v.)', NULL, 'Chỉ tiêu đề nhỏ bên trong bài viết, không dùng để chỉ phụ đề phim.', 'This subheading helps me find the recipe''s cooking instructions.', NULL, 'Tiêu đề phụ này giúp tôi tìm thấy hướng dẫn nấu ăn trong công thức.', '{"wordId":"subheading","ukIpa":"/ˈsʌbhedɪŋ/","usIpa":"/ˈsʌbhedɪŋ/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"a title introducing a section within a longer piece","vi":"tiêu đề phụ; đề mục nhỏ"}],"examples":[{"en":"This subheading helps me find the recipe''s cooking instructions.","vi":"Tiêu đề phụ này giúp tôi tìm thấy hướng dẫn nấu ăn trong công thức.","audioKind":"ex"},{"en":"Each subheading in a research report should clearly indicate the focus of the following section.","vi":"Mỗi tiêu đề phụ trong một báo cáo nghiên cứu cần chỉ rõ trọng tâm của phần tiếp theo.","audioKind":"ex2"}],"collocations":[{"en":"clear subheading","vi":"tiêu đề phụ rõ ràng"},{"en":"descriptive subheading","vi":"tiêu đề phụ mang tính mô tả"},{"en":"add a subheading","vi":"thêm tiêu đề phụ"}],"wordFamily":["heading (n.)","head (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ tiêu đề nhỏ bên trong bài viết, không dùng để chỉ phụ đề phim.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_comprehension', 'en-b2-1', 'comprehension', '/ˌkɑːmprɪˈhenʃən/', 'B2', 'sự hiểu; khả năng hiểu', 'n.', 'comprehend (v.), comprehensible (adj.), incomprehensible (adj.)', 'Đồng nghĩa: understanding, grasp · Trái nghĩa: incomprehension', 'Thường là danh từ không đếm được; tính từ "comprehensive" có nghĩa là toàn diện.', 'Drawing a simple diagram helped my comprehension of the instructions.', NULL, 'Việc vẽ một sơ đồ đơn giản đã giúp tôi hiểu rõ hơn các hướng dẫn.', '{"wordId":"comprehension","ukIpa":"/ˌkɒmprɪˈhenʃən/","usIpa":"/ˌkɑːmprɪˈhenʃən/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"The ability to understand something, especially language or ideas.","vi":"sự hiểu; khả năng hiểu"}],"examples":[{"en":"Drawing a simple diagram helped my comprehension of the instructions.","vi":"Việc vẽ một sơ đồ đơn giản đã giúp tôi hiểu rõ hơn các hướng dẫn.","audioKind":"ex"},{"en":"Regular exposure to varied reading materials can improve students'' comprehension and expand their academic vocabulary.","vi":"Việc thường xuyên tiếp xúc với nhiều loại tài liệu đọc khác nhau có thể cải thiện khả năng đọc hiểu của học sinh và mở rộng vốn từ vựng học thuật.","audioKind":"ex2"}],"collocations":[{"en":"reading comprehension","vi":"đọc hiểu"},{"en":"listening comprehension","vi":"nghe hiểu"},{"en":"beyond comprehension","vi":"vượt quá sự hiểu biết"}],"wordFamily":["comprehend (v.)","comprehensible (adj.)","incomprehensible (adj.)"],"synonyms":["understanding","grasp"],"antonyms":["incomprehension"],"tipVi":"Thường là danh từ không đếm được; tính từ \"comprehensive\" có nghĩa là toàn diện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_boarding-school', 'en-b2-1', 'boarding school', '/ˈbɔːrdɪŋ skuːl/', 'B2', 'trường nội trú', 'n.', 'board (v.), boarder (n.)', NULL, 'boarding chỉ việc ăn ở; trường nội trú vừa cung cấp việc học tập vừa cung cấp chỗ ở.', 'Amir shares a room with two friends at boarding school.', NULL, 'Amir ở chung phòng với hai người bạn tại trường nội trú.', '{"wordId":"boarding-school","ukIpa":"/ˈbɔːdɪŋ skuːl/","usIpa":"/ˈbɔːrdɪŋ skuːl/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"a school where students live as well as study","vi":"trường nội trú"}],"examples":[{"en":"Amir shares a room with two friends at boarding school.","vi":"Amir ở chung phòng với hai người bạn tại trường nội trú.","audioKind":"ex"},{"en":"Attending boarding school can foster independence, although some children find prolonged separation from their families difficult.","vi":"Việc theo học trường nội trú có thể thúc đẩy tính tự lập, mặc dù một số trẻ cảm thấy khó khăn khi phải xa gia đình trong thời gian dài.","audioKind":"ex2"}],"collocations":[{"en":"attend boarding school","vi":"theo học trường nội trú"},{"en":"send a child to boarding school","vi":"gửi con vào trường nội trú"}],"wordFamily":["board (v.)","boarder (n.)"],"synonyms":[],"antonyms":[],"tipVi":"boarding chỉ việc ăn ở; trường nội trú vừa cung cấp việc học tập vừa cung cấp chỗ ở.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ignorance', 'en-b2-1', 'ignorance', '/ˈɪɡnərəns/', 'B2', 'sự thiếu hiểu biết; sự ngu dốt; sự không biết', 'n.', 'ignorant (adj.), ignorantly (adv.)', 'Trái nghĩa: knowledge, awareness', 'Đây là danh từ không đếm được; thường dùng ignorance of hoặc ignorance about để chỉ sự thiếu hiểu biết về một việc gì đó.', 'My ignorance of local customs led to an awkward moment.', NULL, 'Việc tôi không hiểu biết về phong tục tập quán địa phương đã dẫn đến một khoảnh khắc khó xử.', '{"wordId":"ignorance","ukIpa":"/ˈɪɡnərəns/","usIpa":"/ˈɪɡnərəns/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"a lack of knowledge or awareness about something","vi":"sự thiếu hiểu biết; sự ngu dốt; sự không biết"}],"examples":[{"en":"My ignorance of local customs led to an awkward moment.","vi":"Việc tôi không hiểu biết về phong tục tập quán địa phương đã dẫn đến một khoảnh khắc khó xử.","audioKind":"ex"},{"en":"Public education can reduce ignorance about nutrition and help families make healthier choices on limited budgets.","vi":"Giáo dục cộng đồng có thể giảm bớt sự thiếu hiểu biết về dinh dưỡng và giúp các gia đình đưa ra những lựa chọn lành mạnh hơn với nguồn ngân sách hạn hẹp.","audioKind":"ex2"}],"collocations":[{"en":"ignorance of","vi":"sự thiếu hiểu biết về"},{"en":"in ignorance of","vi":"trong tình trạng không biết về"},{"en":"admit ignorance","vi":"thừa nhận sự thiếu hiểu biết"}],"wordFamily":["ignorant (adj.)","ignorantly (adv.)"],"synonyms":[],"antonyms":["knowledge","awareness"],"tipVi":"Đây là danh từ không đếm được; thường dùng ignorance of hoặc ignorance about để chỉ sự thiếu hiểu biết về một việc gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_omit', 'en-b2-1', 'omit', '/oʊˈmɪt/', 'B2', 'bỏ sót; lược bỏ; bỏ qua', 'v.', 'omission (n.)', 'Đồng nghĩa: leave out, exclude · Trái nghĩa: include', 'Các dạng quá khứ omitted và phân từ/tiếp diễn omitting đều được gấp đôi chữ t.', 'You can omit the chilli if you prefer milder soup.', NULL, 'Bạn có thể bỏ ớt ra nếu thích ăn canh nhạt hơn.', '{"wordId":"omit","ukIpa":"/əˈmɪt/","usIpa":"/oʊˈmɪt/","cefr":"B2","topic":"education","senses":[{"pos":"v.","en":"to leave something out, deliberately or accidentally","vi":"bỏ sót; lược bỏ; bỏ qua"}],"examples":[{"en":"You can omit the chilli if you prefer milder soup.","vi":"Bạn có thể bỏ ớt ra nếu thích ăn canh nhạt hơn.","audioKind":"ex"},{"en":"Reports that omit important evidence may give policymakers an inaccurate picture of the challenges facing local communities.","vi":"Các báo cáo bỏ sót những bằng chứng quan trọng có thể cung cấp cho các nhà hoạch định chính sách cái nhìn không chính xác về những thách thức mà cộng đồng địa phương đang đối mặt.","audioKind":"ex2"}],"collocations":[{"en":"omit details","vi":"bỏ qua chi tiết"},{"en":"omit information","vi":"bỏ sót thông tin"},{"en":"omit something from a report","vi":"lược bỏ một phần khỏi báo cáo"}],"wordFamily":["omission (n.)"],"synonyms":["leave out","exclude"],"antonyms":["include"],"tipVi":"Các dạng quá khứ omitted và phân từ/tiếp diễn omitting đều được gấp đôi chữ t.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_literacy', 'en-b2-1', 'literacy', '/ˈlɪtərəsi/', 'B2', 'khả năng đọc viết; kiến thức nền tảng; năng lực cơ bản', 'n.', 'literate (adj.), illiterate (adj.), illiteracy (n.)', 'Trái nghĩa: illiteracy', 'Là danh từ không đếm được; digital literacy chỉ năng lực số, không chỉ đơn thuần là biết chữ.', 'The library offers free literacy classes for local adults.', NULL, 'Thư viện cung cấp các lớp học đọc viết miễn phí cho người lớn địa phương.', '{"wordId":"literacy","ukIpa":"/ˈlɪtərəsi/","usIpa":"/ˈlɪtərəsi/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"The ability to read and write.","vi":"khả năng đọc viết"},{"pos":"n.","en":"Basic knowledge and skills needed in a particular area.","vi":"kiến thức nền tảng; năng lực cơ bản"}],"examples":[{"en":"The library offers free literacy classes for local adults.","vi":"Thư viện cung cấp các lớp học đọc viết miễn phí cho người lớn địa phương.","audioKind":"ex"},{"en":"Improving digital literacy helps older adults access essential services and participate more fully in modern society.","vi":"Việc nâng cao năng lực số giúp người cao tuổi tiếp cận các dịch vụ thiết yếu và tham gia đầy đủ hơn vào xã hội hiện đại.","audioKind":"ex2"}],"collocations":[{"en":"adult literacy","vi":"trình độ đọc viết của người lớn"},{"en":"literacy rates","vi":"tỷ lệ biết chữ"},{"en":"digital literacy","vi":"năng lực số"},{"en":"financial literacy","vi":"hiểu biết về tài chính"}],"wordFamily":["literate (adj.)","illiterate (adj.)","illiteracy (n.)"],"synonyms":[],"antonyms":["illiteracy"],"tipVi":"Là danh từ không đếm được; digital literacy chỉ năng lực số, không chỉ đơn thuần là biết chữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_oral', 'en-b2-1', 'oral', '/ˈɔːrəl/', 'B2', 'bằng lời nói; khẩu thề / khẩu ngữ; thuộc về miệng; dùng qua đường uống', 'adj.', 'orally (adv.)', 'Đồng nghĩa: spoken · Trái nghĩa: written', 'oral vừa chỉ tính chất miệng/lời nói, vừa chỉ bộ phận cơ thể hoặc đường uống (oral medication là thuốc uống).', 'Our teacher gave us oral feedback after each presentation.', NULL, 'Giáo viên của chúng tôi đã đưa ra phản hồi bằng lời sau mỗi bài thuyết trình.', '{"wordId":"oral","ukIpa":"/ˈɔːrəl/","usIpa":"/ˈɔːrəl/","cefr":"B2","topic":"education","senses":[{"pos":"adj.","en":"spoken rather than written","vi":"bằng lời nói; khẩu thề / khẩu ngữ"},{"pos":"adj.","en":"relating to the mouth or taken through the mouth","vi":"thuộc về miệng; dùng qua đường uống"}],"examples":[{"en":"Our teacher gave us oral feedback after each presentation.","vi":"Giáo viên của chúng tôi đã đưa ra phản hồi bằng lời sau mỗi bài thuyết trình.","audioKind":"ex"},{"en":"Oral traditions preserve cultural knowledge in communities where historical events have rarely been recorded in writing.","vi":"Truyền thống khẩu sử lưu giữ tri thức văn hóa trong các cộng đồng nơi các sự kiện lịch sử hiếm khi được ghi chép bằng văn bản.","audioKind":"ex2"}],"collocations":[{"en":"oral examination","vi":"kỳ thi vấn đáp"},{"en":"oral tradition","vi":"truyền thống khẩu sử"},{"en":"oral health","vi":"sức khỏe răng miệng"},{"en":"oral medication","vi":"thuốc uống"}],"wordFamily":["orally (adv.)"],"synonyms":["spoken"],"antonyms":["written"],"tipVi":"oral vừa chỉ tính chất miệng/lời nói, vừa chỉ bộ phận cơ thể hoặc đường uống (oral medication là thuốc uống).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_audio-visual', 'en-b2-1', 'audio-visual', '/ˌɔːdioʊ ˈvɪʒuəl/', 'B2', 'thuộc về nghe nhìn', 'adj.', 'audio (adj.), visual (adj.), visually (adv.)', NULL, 'Cũng có thể viết là audiovisual, thường được viết tắt là AV.', 'We tested the audio-visual equipment before the film started.', NULL, 'Chúng tôi đã kiểm tra thiết bị nghe nhìn trước khi bộ phim bắt đầu.', '{"wordId":"audio-visual","ukIpa":"/ˌɔːdiəʊ ˈvɪʒuəl/","usIpa":"/ˌɔːdioʊ ˈvɪʒuəl/","cefr":"B2","topic":"education","senses":[{"pos":"adj.","en":"Using both sound and images to communicate information","vi":"thuộc về nghe nhìn"}],"examples":[{"en":"We tested the audio-visual equipment before the film started.","vi":"Chúng tôi đã kiểm tra thiết bị nghe nhìn trước khi bộ phim bắt đầu.","audioKind":"ex"},{"en":"Audio-visual materials can support language learning by connecting spoken words with meaningful images and situations.","vi":"Tài liệu nghe nhìn có thể hỗ trợ việc học ngôn ngữ bằng cách kết nối các từ ngữ được nói với hình ảnh và tình huống có ý nghĩa.","audioKind":"ex2"}],"collocations":[{"en":"audio-visual equipment","vi":"thiết bị nghe nhìn"},{"en":"audio-visual aids","vi":"đồ dùng dạy học nghe nhìn"},{"en":"audio-visual materials","vi":"tài liệu nghe nhìn"}],"wordFamily":["audio (adj.)","visual (adj.)","visually (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Cũng có thể viết là audiovisual, thường được viết tắt là AV.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_catalogue', 'en-b2-1', 'catalogue', '/ˈkætəlɔːɡ/', 'B2', 'danh mục; sách giới thiệu sản phẩm; lập danh mục; phân loại và ghi chép; một chuỗi sự việc tồi tệ; một loạt rắc rối', 'n.', 'cataloguing (n.)', NULL, 'Cách viết theo Anh-Anh là catalogue; tiếng Anh-Mỹ thường viết là catalog.', 'I found the perfect desk in a furniture catalogue.', NULL, 'Tôi tìm thấy chiếc bàn làm việc hoàn hảo trong một cuốn catalog đồ nội thất.', '{"wordId":"catalogue","ukIpa":"/ˈkætəlɒɡ/","usIpa":"/ˈkætəlɔːɡ/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"An organised list of items, often with descriptions or pictures","vi":"danh mục; sách giới thiệu sản phẩm"},{"pos":"v.","en":"Make an organised record of items and their details","vi":"lập danh mục; phân loại và ghi chép"},{"pos":"n.","en":"A series of unpleasant events or failures","vi":"một chuỗi sự việc tồi tệ; một loạt rắc rối"}],"examples":[{"en":"I found the perfect desk in a furniture catalogue.","vi":"Tôi tìm thấy chiếc bàn làm việc hoàn hảo trong một cuốn catalog đồ nội thất.","audioKind":"ex"},{"en":"A digital catalogue enables researchers to locate historical documents without visiting the archive in person.","vi":"Danh mục số hóa giúp các nhà nghiên cứu tìm kiếm tài liệu lịch sử mà không cần phải trực tiếp đến thư viện lưu trữ.","audioKind":"ex2"}],"collocations":[{"en":"library catalogue","vi":"thư mục thư viện"},{"en":"product catalogue","vi":"danh mục sản phẩm"},{"en":"catalogue a collection","vi":"lập danh mục cho một bộ sưu tập"},{"en":"a catalogue of errors","vi":"một chuỗi những sai lầm"}],"wordFamily":["cataloguing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cách viết theo Anh-Anh là catalogue; tiếng Anh-Mỹ thường viết là catalog.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_globe', 'en-b2-1', 'globe', '/ɡloʊb/', 'B2', 'quả địa cầu; trái đất; thế giới; vật hình cầu; quả cầu', 'n.', 'global (adj.), globally (adv.), globalisation (n.)', 'Đồng nghĩa: world, sphere', 'Từ ''a globe'' thường ám chỉ quả địa cầu, trong khi ''the globe'' thường chỉ toàn thế giới.', 'She spun the globe and pointed to a tiny island.', NULL, 'Cô ấy xoay quả địa cầu và chỉ tay vào một hòn đảo nhỏ.', '{"wordId":"globe","ukIpa":"/ɡləʊb/","usIpa":"/ɡloʊb/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"A ball-shaped model of Earth showing its land and oceans.","vi":"quả địa cầu"},{"pos":"n.","en":"The Earth, especially when considering all its regions.","vi":"trái đất; thế giới"},{"pos":"n.","en":"An object shaped like a ball.","vi":"vật hình cầu; quả cầu"}],"examples":[{"en":"She spun the globe and pointed to a tiny island.","vi":"Cô ấy xoay quả địa cầu và chỉ tay vào một hòn đảo nhỏ.","audioKind":"ex"},{"en":"Researchers across the globe are sharing climate data to improve predictions of extreme weather events.","vi":"Các nhà nghiên cứu trên khắp thế giới đang chia sẻ dữ liệu khí hậu để nâng cao khả năng dự báo các hiện tượng thời tiết cực đoan.","audioKind":"ex2"}],"collocations":[{"en":"across the globe","vi":"trên toàn cầu"},{"en":"around the globe","vi":"khắp nơi trên thế giới"},{"en":"a glass globe","vi":"quả cầu thủy tinh"}],"wordFamily":["global (adj.)","globally (adv.)","globalisation (n.)"],"synonyms":["world","sphere"],"antonyms":[],"tipVi":"Từ ''a globe'' thường ám chỉ quả địa cầu, trong khi ''the globe'' thường chỉ toàn thế giới.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_assessment', 'en-b2-1', 'assessment', '/əˈsesmənt/', 'B2', 'sự đánh giá; sự nhận định; sự kiểm tra; bài đánh giá năng lực', 'n.', 'assess (v.), assessor (n.)', 'Đồng nghĩa: evaluation, appraisal', 'Đánh giá mượn dùng assessment of; động từ của nó là assess.', 'The mechanic''s assessment was that the brakes needed replacing.', NULL, 'Thợ máy nhận định rằng hệ thống phanh cần phải được thay thế.', '{"wordId":"assessment","ukIpa":"/əˈsesmənt/","usIpa":"/əˈsesmənt/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"A judgement about something based on careful examination.","vi":"sự đánh giá; sự nhận định"},{"pos":"n.","en":"A task or process used to measure a learner''s progress.","vi":"sự kiểm tra; bài đánh giá năng lực"}],"examples":[{"en":"The mechanic''s assessment was that the brakes needed replacing.","vi":"Thợ máy nhận định rằng hệ thống phanh cần phải được thay thế.","audioKind":"ex"},{"en":"Continuous assessment can provide a broader picture of student progress than a single final examination.","vi":"Việc đánh giá liên tục có thể mang lại cái nhìn toàn diện hơn về sự tiến bộ của học sinh so với một bài thi cuối kỳ duy nhất.","audioKind":"ex2"}],"collocations":[{"en":"risk assessment","vi":"đánh giá rủi ro"},{"en":"continuous assessment","vi":"đánh giá quá trình"},{"en":"carry out an assessment","vi":"tiến hành đánh giá"}],"wordFamily":["assess (v.)","assessor (n.)"],"synonyms":["evaluation","appraisal"],"antonyms":[],"tipVi":"Đánh giá mượn dùng assessment of; động từ của nó là assess.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_encyclopedia', 'en-b2-1', 'encyclopedia', '/ɪnˌsaɪkləˈpiːdiə/', 'B2', 'bách khoa toàn thư', 'n.', 'encyclopedic (adj.)', NULL, 'Trong tiếng Anh-Anh, từ này cũng thường được viết là encyclopaedia.', 'I found a fascinating dinosaur picture in this encyclopedia.', NULL, 'Tôi tìm thấy bức ảnh khủng long rất thú vị trong cuốn bách khoa toàn thư này.', '{"wordId":"encyclopedia","ukIpa":"/ɪnˌsaɪkləˈpiːdiə/","usIpa":"/ɪnˌsaɪkləˈpiːdiə/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"A book or website explaining many subjects or one field.","vi":"bách khoa toàn thư"}],"examples":[{"en":"I found a fascinating dinosaur picture in this encyclopedia.","vi":"Tôi tìm thấy bức ảnh khủng long rất thú vị trong cuốn bách khoa toàn thư này.","audioKind":"ex"},{"en":"An online encyclopedia offers convenient background information, but students should verify important claims using reliable academic sources.","vi":"Bách khoa toàn thư trực tuyến cung cấp thông tin nền tảng tiện lợi, nhưng học sinh nên xác thực các luận điểm quan trọng bằng các nguồn học thuật đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"online encyclopedia","vi":"bách khoa toàn thư trực tuyến"},{"en":"encyclopedia entry","vi":"mục từ bách khoa toàn thư"},{"en":"consult an encyclopedia","vi":"tra cứu bách khoa toàn thư"}],"wordFamily":["encyclopedic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh, từ này cũng thường được viết là encyclopaedia.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_academic', 'en-b2-1', 'academic', '/ˌækəˈdemɪk/', 'B2', 'thuộc học tập; thuộc học thuật; giảng viên đại học; học giả; thuộc lý thuyết; mang tính hàn lâm', 'adj.', 'academically (adv.), academia (n.)', 'Đồng nghĩa: scholarly', 'Khi dùng làm danh từ, từ này chỉ giảng viên hoặc nhà nghiên cứu đại học, thường không dùng cho sinh viên.', 'The school praised her academic progress this year.', NULL, 'Nhà trường đã biểu dương tiến bộ học tập của cô ấy trong năm nay.', '{"wordId":"academic","ukIpa":"/ˌækəˈdemɪk/","usIpa":"/ˌækəˈdemɪk/","cefr":"B2","topic":"education","senses":[{"pos":"adj.","en":"related to education, study, or research","vi":"thuộc học tập; thuộc học thuật"},{"pos":"n.","en":"someone who teaches or researches at a university","vi":"giảng viên đại học; học giả"},{"pos":"adj.","en":"theoretical rather than useful in a practical situation","vi":"thuộc lý thuyết; mang tính hàn lâm"}],"examples":[{"en":"The school praised her academic progress this year.","vi":"Nhà trường đã biểu dương tiến bộ học tập của cô ấy trong năm nay.","audioKind":"ex"},{"en":"Universities should support students'' emotional wellbeing rather than focusing exclusively on academic achievement and examination results.","vi":"Các trường đại học nên quan tâm đến sức khỏe tinh thần của sinh viên thay vì chỉ chú trọng vào thành tích học tập và kết quả thi cử.","audioKind":"ex2"}],"collocations":[{"en":"academic achievement","vi":"thành tích học tập"},{"en":"academic research","vi":"nghiên cứu học thuật"},{"en":"academic year","vi":"năm học"},{"en":"academic qualifications","vi":"bằng cấp học thuật"}],"wordFamily":["academically (adv.)","academia (n.)"],"synonyms":["scholarly"],"antonyms":[],"tipVi":"Khi dùng làm danh từ, từ này chỉ giảng viên hoặc nhà nghiên cứu đại học, thường không dùng cho sinh viên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_discipline', 'en-b2-1', 'discipline', '/ˈdɪsəplɪn/', 'B2', 'kỷ luật; tính tự giác; ngành học; môn học; rèn luyện', 'n.', 'disciplined (adj.), disciplinary (adj.), self-discipline (n.), undisciplined (adj.)', NULL, 'Chỉ kỷ luật thường là danh từ không đếm được; chỉ ngành học thì đếm được.', 'Practising the piano every morning takes patience and discipline.', NULL, 'Việc tập piano mỗi sáng đòi hỏi sự kiên nhẫn và tính kỷ luật.', '{"wordId":"discipline","ukIpa":"/ˈdɪsəplɪn/","usIpa":"/ˈdɪsəplɪn/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"Controlled behaviour achieved by following rules or managing yourself.","vi":"kỷ luật; tính tự giác"},{"pos":"n.","en":"A particular field of study or knowledge.","vi":"ngành học; môn học"},{"pos":"v.","en":"To punish misconduct or train someone to follow rules.","vi":"kỷ luật; rèn luyện"}],"examples":[{"en":"Practising the piano every morning takes patience and discipline.","vi":"Việc tập piano mỗi sáng đòi hỏi sự kiên nhẫn và tính kỷ luật.","audioKind":"ex"},{"en":"Universities increasingly encourage collaboration between researchers from different disciplines to address complex environmental challenges.","vi":"Các trường đại học ngày càng khuyến khích sự hợp tác giữa các nhà nghiên cứu từ các ngành học khác nhau để giải quyết những thách thức phức tạp về môi trường.","audioKind":"ex2"}],"collocations":[{"en":"self-discipline","vi":"tự kỷ luật"},{"en":"maintain discipline","vi":"Duy trì kỷ luật"},{"en":"academic discipline","vi":"ngành học thuật"},{"en":"discipline yourself to do something","vi":"rèn luyện bản thân làm gì đó"}],"wordFamily":["disciplined (adj.)","disciplinary (adj.)","self-discipline (n.)","undisciplined (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ kỷ luật thường là danh từ không đếm được; chỉ ngành học thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_guidance', 'en-b2-1', 'guidance', '/ˈɡaɪdəns/', 'B2', 'sự hướng dẫn; lời chỉ bảo', 'n.', 'guide (v.), guide (n.)', 'Đồng nghĩa: advice, direction', 'Là danh từ không đếm được; chỉ nói some guidance, không dùng a guidance.', 'With your guidance, I finally planted the seeds correctly.', NULL, 'Nhờ có sự hướng dẫn của bạn, cuối cùng tôi đã gieo hạt đúng cách.', '{"wordId":"guidance","ukIpa":"/ˈɡaɪdəns/","usIpa":"/ˈɡaɪdəns/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"help or advice about what to do or how to proceed","vi":"sự hướng dẫn; lời chỉ bảo"}],"examples":[{"en":"With your guidance, I finally planted the seeds correctly.","vi":"Nhờ có sự hướng dẫn của bạn, cuối cùng tôi đã gieo hạt đúng cách.","audioKind":"ex"},{"en":"Schools should provide career guidance to help students make informed decisions about further education and employment.","vi":"Các trường học nên cung cấp dịch vụ định hướng nghề nghiệp để giúp học sinh đưa ra các quyết định sáng suốt về học vấn nâng cao và việc làm.","audioKind":"ex2"}],"collocations":[{"en":"career guidance","vi":"định hướng nghề nghiệp"},{"en":"provide guidance","vi":"cung cấp sự hướng dẫn"},{"en":"seek guidance","vi":"tìm kiếm lời khuyên"},{"en":"under someone''s guidance","vi":"dưới sự hướng dẫn của ai đó"}],"wordFamily":["guide (v.)","guide (n.)"],"synonyms":["advice","direction"],"antonyms":[],"tipVi":"Là danh từ không đếm được; chỉ nói some guidance, không dùng a guidance.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_marking', 'en-b2-1', 'marking', '/ˈmɑːrkɪŋ/', 'B2', 'việc chấm bài; việc chấm điểm; vết vằn; vạch dấu', 'n.', 'mark (n.), mark (v.), marker (n.)', 'Đồng nghĩa: grading', 'Nghĩa chấm bài thường không đếm được; nghĩa vết vằn và vạch đường thường dùng số nhiều.', 'The teacher finished her marking before cooking dinner.', NULL, 'Cô giáo đã hoàn thành việc chấm bài trước khi nấu bữa tối.', '{"wordId":"marking","ukIpa":"/ˈmɑːkɪŋ/","usIpa":"/ˈmɑːrkɪŋ/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"The work of checking and grading students'' answers.","vi":"việc chấm bài; việc chấm điểm"},{"pos":"n.","en":"A visible pattern or line on an animal or surface.","vi":"vết vằn; vạch dấu"}],"examples":[{"en":"The teacher finished her marking before cooking dinner.","vi":"Cô giáo đã hoàn thành việc chấm bài trước khi nấu bữa tối.","audioKind":"ex"},{"en":"Clear marking guidelines help ensure that students receive fair grades regardless of who assesses their work.","vi":"Hướng dẫn chấm điểm rõ ràng giúp đảm bảo học sinh nhận được điểm số công bằng bất kể ai là người chấm bài.","audioKind":"ex2"}],"collocations":[{"en":"marking scheme","vi":"biểu điểm; hướng dẫn chấm điểm"},{"en":"road markings","vi":"vạch kẻ đường"},{"en":"distinctive markings","vi":"vết vằn đặc trưng"}],"wordFamily":["mark (n.)","mark (v.)","marker (n.)"],"synonyms":["grading"],"antonyms":[],"tipVi":"Nghĩa chấm bài thường không đếm được; nghĩa vết vằn và vạch đường thường dùng số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_admission', 'en-b2-1', 'admission', '/ədˈmɪʃən/', 'B2', 'sự cho vào; sự nhận vào; sự trúng tuyển; tiền vào cửa; giá vé vào cổng; sự thừa nhận; sự thú nhận', 'n.', 'admit (v.), admissible (adj.), inadmissible (adj.)', 'Đồng nghĩa: entry, acknowledgement', 'Quyền vào một nơi dùng admission to; sự thừa nhận việc gì dùng admission of.', 'Admission to the museum is free on Sundays.', NULL, 'Vào cửa bảo tàng miễn phí vào các ngày Chủ nhật.', '{"wordId":"admission","ukIpa":"/ədˈmɪʃən/","usIpa":"/ədˈmɪʃən/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"Permission to enter a place or join an institution","vi":"sự cho vào; sự nhận vào; sự trúng tuyển"},{"pos":"n.","en":"The money paid to enter a place","vi":"tiền vào cửa; giá vé vào cổng"},{"pos":"n.","en":"A statement accepting that something is true, often something unpleasant","vi":"sự thừa nhận; sự thú nhận"}],"examples":[{"en":"Admission to the museum is free on Sundays.","vi":"Vào cửa bảo tàng miễn phí vào các ngày Chủ nhật.","audioKind":"ex"},{"en":"University admission should reflect academic potential rather than simply rewarding access to expensive private education.","vi":"Việc tuyển sinh đại học nên phản ánh năng lực học thuật thay vì chỉ đơn thuần là tạo lợi thế cho những ai có điều kiện theo học nền giáo dục tư thục đắt đỏ.","audioKind":"ex2"}],"collocations":[{"en":"admission to university","vi":"trúng tuyển đại học"},{"en":"admission fee","vi":"phí vào cổng"},{"en":"free admission","vi":"miễn phí vào cửa"},{"en":"admission of guilt","vi":"sự thừa nhận tội lỗi"}],"wordFamily":["admit (v.)","admissible (adj.)","inadmissible (adj.)"],"synonyms":["entry","acknowledgement"],"antonyms":[],"tipVi":"Quyền vào một nơi dùng admission to; sự thừa nhận việc gì dùng admission of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_introductory', 'en-b2-1', 'introductory', '/ˌɪntrəˈdʌktəri/', 'B2', 'tính từ: vỡ lòng; nhập môn; giới thiệu; tính từ: ưu đãi khi mới ra mắt', 'adj.', 'introduce (v.), introduction (n.)', NULL, 'introductory course chỉ khóa học nhập môn, thường dành cho người mới bắt đầu.', 'I joined an introductory pottery class last weekend.', NULL, 'Tôi đã tham gia một lớp học gốm vỡ lòng vào cuối tuần qua.', '{"wordId":"introductory","ukIpa":"/ˌɪntrəˈdʌktəri/","usIpa":"/ˌɪntrəˈdʌktəri/","cefr":"B2","topic":"education","senses":[{"pos":"adj.","en":"Providing basic information or presenting something for the first time.","vi":"tính từ: vỡ lòng; nhập môn; giới thiệu"},{"pos":"adj.","en":"Offered at a special price when something first becomes available.","vi":"tính từ: ưu đãi khi mới ra mắt"}],"examples":[{"en":"I joined an introductory pottery class last weekend.","vi":"Tôi đã tham gia một lớp học gốm vỡ lòng vào cuối tuần qua.","audioKind":"ex"},{"en":"Universities should offer introductory courses in data analysis to students from all academic disciplines.","vi":"Các trường đại học nên cung cấp các khóa học nhập môn về phân tích dữ liệu cho sinh viên từ mọi chuyên ngành.","audioKind":"ex2"}],"collocations":[{"en":"introductory course","vi":"khóa học nhập môn"},{"en":"introductory remarks","vi":"lời mở đầu; phát biểu mở màn"},{"en":"introductory offer","vi":"giá ưu đãi khi ra mắt"}],"wordFamily":["introduce (v.)","introduction (n.)"],"synonyms":[],"antonyms":[],"tipVi":"introductory course chỉ khóa học nhập môn, thường dành cho người mới bắt đầu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_principal', 'en-b2-1', 'principal', '/ˈprɪnsəpəl/', 'B2', 'tính từ: chính; chủ yếu; quan trọng nhất; danh từ: hiệu trưởng; danh từ: tiền vốn; tiền gốc', 'adj.', 'principally (adv.)', 'Đồng nghĩa: main, chief, primary · Trái nghĩa: secondary', 'principal chỉ ''chính'' hoặc ''hiệu trưởng''; còn principle có nghĩa là ''nguyên tắc''.', 'Our principal reason for moving was the noisy traffic.', NULL, 'Lý do chính khiến chúng tôi chuyển nhà là tiếng ồn từ giao thông quá lớn.', '{"wordId":"principal","ukIpa":"/ˈprɪnsəpəl/","usIpa":"/ˈprɪnsəpəl/","cefr":"B2","topic":"education","senses":[{"pos":"adj.","en":"most important among several things","vi":"tính từ: chính; chủ yếu; quan trọng nhất"},{"pos":"n.","en":"the person in charge of a school or college","vi":"danh từ: hiệu trưởng"},{"pos":"n.","en":"money borrowed or invested, excluding interest","vi":"danh từ: tiền vốn; tiền gốc"}],"examples":[{"en":"Our principal reason for moving was the noisy traffic.","vi":"Lý do chính khiến chúng tôi chuyển nhà là tiếng ồn từ giao thông quá lớn.","audioKind":"ex"},{"en":"The principal challenge facing urban planners is providing affordable housing without reducing access to green spaces.","vi":"Thách thức chính mà các nhà quy hoạch đô thị phải đối mặt là cung cấp nhà ở giá rẻ mà không làm giảm không gian xanh.","audioKind":"ex2"}],"collocations":[{"en":"the principal reason","vi":"lý do chính"},{"en":"a principal aim","vi":"mục tiêu chính"},{"en":"a school principal","vi":"hiệu trưởng trường học"},{"en":"repay the principal","vi":"trả tiền gốc"}],"wordFamily":["principally (adv.)"],"synonyms":["main","chief","primary"],"antonyms":["secondary"],"tipVi":"principal chỉ ''chính'' hoặc ''hiệu trưởng''; còn principle có nghĩa là ''nguyên tắc''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_consonant', 'en-b2-1', 'consonant', '/ˈkɑːnsənənt/', 'B2', 'phụ âm; ký tự phụ âm; phù hợp với; tương hợp', 'n.', NULL, NULL, 'Tính từ dùng khá trang trọng, thường dùng consonant with để chỉ sự tương hợp.', 'Try saying the final consonant slowly and clearly.', NULL, 'Hãy thử phát âm phụ âm cuối một cách từ từ và rõ ràng.', '{"wordId":"consonant","ukIpa":"/ˈkɒnsənənt/","usIpa":"/ˈkɑːnsənənt/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"a speech sound involving blocked airflow, or its written symbol","vi":"phụ âm; ký tự phụ âm"},{"pos":"adj.","en":"agreeing with or matching something","vi":"phù hợp với; tương hợp"}],"examples":[{"en":"Try saying the final consonant slowly and clearly.","vi":"Hãy thử phát âm phụ âm cuối một cách từ từ và rõ ràng.","audioKind":"ex"},{"en":"Learners may struggle to pronounce consonant clusters that do not occur in their first language.","vi":"Người học có thể gặp khó khăn khi phát âm các cụm phụ âm không xuất hiện trong tiếng mẹ đẻ của họ.","audioKind":"ex2"}],"collocations":[{"en":"consonant sound","vi":"âm phụ âm"},{"en":"consonant cluster","vi":"cụm phụ âm"},{"en":"final consonant","vi":"phụ âm cuối"},{"en":"consonant with","vi":"phù hợp với"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tính từ dùng khá trang trọng, thường dùng consonant with để chỉ sự tương hợp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_intellectual', 'en-b2-1', 'intellectual', '/ˌɪntəˈlektʃuəl/', 'B2', 'thuộc về trí tuệ; thuộc về tư duy; trí thức', 'adj.', 'intellect (n.), intellectually (adv.)', 'Đồng nghĩa: mental', 'Intellectual nhấn mạnh hoạt động tư duy; intelligent nhấn mạnh sự thông minh.', 'She enjoys the intellectual challenge of learning a new language.', NULL, 'Cô ấy thích thử thách trí tuệ khi học một ngôn ngữ mới.', '{"wordId":"intellectual","ukIpa":"/ˌɪntəˈlektʃuəl/","usIpa":"/ˌɪntəˈlektʃuəl/","cefr":"B2","topic":"education","senses":[{"pos":"adj.","en":"Relating to thinking, reasoning, and understanding complex ideas","vi":"thuộc về trí tuệ; thuộc về tư duy"},{"pos":"n.","en":"Someone who studies and discusses complex ideas seriously","vi":"trí thức"}],"examples":[{"en":"She enjoys the intellectual challenge of learning a new language.","vi":"Cô ấy thích thử thách trí tuệ khi học một ngôn ngữ mới.","audioKind":"ex"},{"en":"Schools should support intellectual development through activities that encourage students to question assumptions and evaluate evidence.","vi":"Các nhà trường nên hỗ trợ sự phát triển trí tuệ thông qua các hoạt động khuyến khích học sinh đặt câu hỏi về các giả định và đánh giá các bằng chứng.","audioKind":"ex2"}],"collocations":[{"en":"intellectual development","vi":"sự phát triển trí tuệ"},{"en":"intellectual challenge","vi":"thử thách trí tuệ"},{"en":"intellectual property","vi":"sở hữu trí tuệ"},{"en":"intellectual curiosity","vi":"niềm khao khát tri thức"}],"wordFamily":["intellect (n.)","intellectually (adv.)"],"synonyms":["mental"],"antonyms":[],"tipVi":"Intellectual nhấn mạnh hoạt động tư duy; intelligent nhấn mạnh sự thông minh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conjunction', 'en-b2-1', 'conjunction', '/kənˈdʒʌŋkʃən/', 'B2', 'từ nối; liên từ; sự kết hợp; sự đồng thời xảy ra', 'n.', NULL, NULL, 'in conjunction with thường biểu thị ý nghĩa "cùng với hoặc kết hợp với".', 'Our teacher used coloured cards to explain conjunctions.', NULL, 'Giáo viên của chúng tôi đã dùng các tấm thẻ màu để giải thích về các liên từ.', '{"wordId":"conjunction","ukIpa":"/kənˈdʒʌŋkʃən/","usIpa":"/kənˈdʒʌŋkʃən/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"a word that connects words, phrases, or clauses","vi":"từ nối; liên từ"},{"pos":"n.","en":"a combination of things or events occurring together","vi":"sự kết hợp; sự đồng thời xảy ra"}],"examples":[{"en":"Our teacher used coloured cards to explain conjunctions.","vi":"Giáo viên của chúng tôi đã dùng các tấm thẻ màu để giải thích về các liên từ.","audioKind":"ex"},{"en":"Public transport improvements work best in conjunction with policies that discourage unnecessary car journeys.","vi":"Việc cải thiện giao thông công cộng mang lại hiệu quả tốt nhất khi kết hợp với các chính sách hạn chế những chuyến đi xe hơi không cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"in conjunction with","vi":"kết hợp với"},{"en":"coordinating conjunction","vi":"liên từ kết hợp"},{"en":"subordinating conjunction","vi":"liên từ phụ thuộc"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"in conjunction with thường biểu thị ý nghĩa \"cùng với hoặc kết hợp với\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bibliography', 'en-b2-1', 'bibliography', '/ˌbɪbliˈɑːɡrəfi/', 'B2', 'thư mục tham khảo; danh mục tài liệu tham khảo', 'n.', 'bibliographic (adj.), bibliographical (adj.)', NULL, '"bibliography" là danh mục tài liệu tham khảo; còn "biography" là tiểu sử nhân vật.', 'I added the missing book to my essay''s bibliography.', NULL, 'Tôi đã thêm cuốn sách bị thiếu vào danh mục tài liệu tham khảo của bài luận.', '{"wordId":"bibliography","ukIpa":"/ˌbɪbliˈɒɡrəfi/","usIpa":"/ˌbɪbliˈɑːɡrəfi/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"a list of sources used or relevant to a subject","vi":"thư mục tham khảo; danh mục tài liệu tham khảo"}],"examples":[{"en":"I added the missing book to my essay''s bibliography.","vi":"Tôi đã thêm cuốn sách bị thiếu vào danh mục tài liệu tham khảo của bài luận.","audioKind":"ex"},{"en":"A carefully prepared bibliography allows readers to locate sources and examine the evidence supporting an academic argument.","vi":"Một danh mục tài liệu tham khảo được biên soạn cẩn thận giúp người đọc tìm ra nguồn tài liệu và kiểm chứng các bằng chứng hỗ trợ cho lập luận học thuật.","audioKind":"ex2"}],"collocations":[{"en":"compile a bibliography","vi":"biên soạn thư mục tham khảo"},{"en":"annotated bibliography","vi":"thư mục tham khảo có chú giải"},{"en":"extensive bibliography","vi":"thư mục tham khảo chi tiết"}],"wordFamily":["bibliographic (adj.)","bibliographical (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"\"bibliography\" là danh mục tài liệu tham khảo; còn \"biography\" là tiểu sử nhân vật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 28, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_1_1', 'en-b2-1', 'Cách dùng “ignorance” (n.) — sự thiếu hiểu biết; sự ngu dốt; sự không biết', 'ignorance of  ·  in ignorance of  ·  admit ignorance', 'Đây là danh từ không đếm được; thường dùng ignorance of hoặc ignorance about để chỉ sự thiếu hiểu biết về một việc gì đó.', 'Họ từ (Word Family): ignorant (adj.), ignorantly (adv.) | Trái nghĩa: knowledge, awareness', '[{"hanzi":"My ignorance of local customs led to an awkward moment.","pinyin":"","meaning":"Việc tôi không hiểu biết về phong tục tập quán địa phương đã dẫn đến một khoảnh khắc khó xử."},{"hanzi":"Public education can reduce ignorance about nutrition and help families make healthier choices on limited budgets.","pinyin":"","meaning":"Giáo dục cộng đồng có thể giảm bớt sự thiếu hiểu biết về dinh dưỡng và giúp các gia đình đưa ra những lựa chọn lành mạnh hơn với nguồn ngân sách hạn hẹp."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_1_2', 'en-b2-1', 'Cách dùng “oral” (adj.) — bằng lời nói; khẩu thề / khẩu ngữ', 'oral examination  ·  oral tradition  ·  oral health', 'oral vừa chỉ tính chất miệng/lời nói, vừa chỉ bộ phận cơ thể hoặc đường uống (oral medication là thuốc uống).', 'Họ từ (Word Family): orally (adv.) | Đồng nghĩa: spoken · Trái nghĩa: written', '[{"hanzi":"Our teacher gave us oral feedback after each presentation.","pinyin":"","meaning":"Giáo viên của chúng tôi đã đưa ra phản hồi bằng lời sau mỗi bài thuyết trình."},{"hanzi":"Oral traditions preserve cultural knowledge in communities where historical events have rarely been recorded in writing.","pinyin":"","meaning":"Truyền thống khẩu sử lưu giữ tri thức văn hóa trong các cộng đồng nơi các sự kiện lịch sử hiếm khi được ghi chép bằng văn bản."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_1_3', 'en-b2-1', 'Cách dùng “academic” (adj.) — thuộc học tập; thuộc học thuật', 'academic achievement  ·  academic research  ·  academic year', 'Khi dùng làm danh từ, từ này chỉ giảng viên hoặc nhà nghiên cứu đại học, thường không dùng cho sinh viên.', 'Họ từ (Word Family): academically (adv.), academia (n.) | Đồng nghĩa: scholarly', '[{"hanzi":"The school praised her academic progress this year.","pinyin":"","meaning":"Nhà trường đã biểu dương tiến bộ học tập của cô ấy trong năm nay."},{"hanzi":"Universities should support students'' emotional wellbeing rather than focusing exclusively on academic achievement and examination results.","pinyin":"","meaning":"Các trường đại học nên quan tâm đến sức khỏe tinh thần của sinh viên thay vì chỉ chú trọng vào thành tích học tập và kết quả thi cử."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_1_4', 'en-b2-1', 'Cách dùng “novice” (n.) — người mới bắt đầu; người có ít kinh nghiệm', 'a complete novice  ·  a novice driver  ·  a novice at', 'Để chỉ người mới trong một lĩnh vực cụ thể, thường dùng cấu trúc a novice at hoặc a novice in.', 'Đồng nghĩa: beginner, newcomer · Trái nghĩa: expert, veteran', '[{"hanzi":"As a gardening novice, I often forget to water seedlings.","pinyin":"","meaning":"Là một người mới tập tọe làm vườn, tôi thường quên tưới nước cho cây con."},{"hanzi":"Structured mentoring can help a novice develop the confidence needed to manage a classroom effectively.","pinyin":"","meaning":"Việc cố vấn có bài bản có thể giúp một giáo viên mới vào nghề xây dựng sự tự tin cần thiết để quản lý lớp học hiệu quả."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_1_1', 'en-b2-1', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_1_1_1', 'ten_b2_1_1', 'motivate', 'Training with a friend motivates me to exercise regularly.', 'Training with a friend motivates me to exercise regularly.', '/ˈmoʊtɪveɪt/', 'Tập luyện cùng một người bạn thúc đẩy tôi chăm chỉ tập thể dục đều đặn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_1_1_2', 'ten_b2_1_1', 'novice', 'As a gardening novice, I often forget to water seedlings.', 'As a gardening novice, I often forget to water seedlings.', '/ˈnɑːvɪs/', 'Là một người mới tập tọe làm vườn, tôi thường quên tưới nước cho cây con.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_1_1_3', 'ten_b2_1_1', 'nursery', 'My daughter painted a bright yellow duck at nursery.', 'My daughter painted a bright yellow duck at nursery.', '/ˈnɝːsəri/', 'Con gái tôi đã vẽ một chú vịt màu vàng tươi ở nhà trẻ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_1_1_4', 'ten_b2_1_1', 'scholar', 'The scholar carefully examined an old book in the library.', 'The scholar carefully examined an old book in the library.', '/ˈskɑːlər/', 'Vị học giả cẩn thận nghiên cứu một cuốn sách cổ trong thư viện.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_1_1_5', 'ten_b2_1_1', 'reference', 'Her speech included a warm reference to her grandmother.', 'Her speech included a warm reference to her grandmother.', '/ˈrefərəns/', 'Bài phát biểu của cô ấy có chứa một lời nhắc đến đầy tình cảm dành cho người bà của mình.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_1_1_6', 'ten_b2_1_1', 'subheading', 'This subheading helps me find the recipe''s cooking instructions.', 'This subheading helps me find the recipe''s cooking instructions.', '/ˈsʌbhedɪŋ/', 'Tiêu đề phụ này giúp tôi tìm thấy hướng dẫn nấu ăn trong công thức.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_1_1_7', 'ten_b2_1_1', 'comprehension', 'Drawing a simple diagram helped my comprehension of the instructions.', 'Drawing a simple diagram helped my comprehension of the instructions.', '/ˌkɑːmprɪˈhenʃən/', 'Việc vẽ một sơ đồ đơn giản đã giúp tôi hiểu rõ hơn các hướng dẫn.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_1_1_8', 'ten_b2_1_1', 'boarding school', 'Amir shares a room with two friends at boarding school.', 'Amir shares a room with two friends at boarding school.', '/ˈbɔːrdɪŋ skuːl/', 'Amir ở chung phòng với hai người bạn tại trường nội trú.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_1_1_1', 'en-b2-1', 'ten_b2_1_1', 'listening', 'listening', 'Training with a friend motivates me to exercise regularly.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Thợ máy nhận định rằng hệ thống phanh cần phải được thay thế.","Tôi đã tham gia một lớp học gốm vỡ lòng vào cuối tuần qua.","Tập luyện cùng một người bạn thúc đẩy tôi chăm chỉ tập thể dục đều đặn.","Cô ấy xoay quả địa cầu và chỉ tay vào một hòn đảo nhỏ."]'::jsonb, 2, 'Training with a friend motivates me to exercise regularly. → Tập luyện cùng một người bạn thúc đẩy tôi chăm chỉ tập thể dục đều đặn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_1_1_2', 'en-b2-1', 'ten_b2_1_1', 'listening', 'listening', 'As a gardening novice, I often forget to water seedlings.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Là một người mới tập tọe làm vườn, tôi thường quên tưới nước cho cây con.","Amir ở chung phòng với hai người bạn tại trường nội trú.","Tôi đã tham gia một lớp học gốm vỡ lòng vào cuối tuần qua.","Tập luyện cùng một người bạn thúc đẩy tôi chăm chỉ tập thể dục đều đặn."]'::jsonb, 0, 'As a gardening novice, I often forget to water seedlings. → Là một người mới tập tọe làm vườn, tôi thường quên tưới nước cho cây con.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_1_1_3', 'en-b2-1', 'ten_b2_1_1', 'listening', 'listening', 'My daughter painted a bright yellow duck at nursery.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã kiểm tra thiết bị nghe nhìn trước khi bộ phim bắt đầu.","Con gái tôi đã vẽ một chú vịt màu vàng tươi ở nhà trẻ.","Vào cửa bảo tàng miễn phí vào các ngày Chủ nhật.","Lý do chính khiến chúng tôi chuyển nhà là tiếng ồn từ giao thông quá lớn."]'::jsonb, 1, 'My daughter painted a bright yellow duck at nursery. → Con gái tôi đã vẽ một chú vịt màu vàng tươi ở nhà trẻ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_1_2', 'en-b2-1', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_1_2_1', 'ten_b2_1_2', 'motivate', 'Teachers can motivate students to explore difficult subjects by connecting classroom lessons with everyday experiences.', 'Teachers can motivate students to explore difficult subjects by connecting classroom lessons with everyday experiences.', '/ˈmoʊtɪveɪt/', 'Giáo viên có thể truyền động lực cho học sinh khám phá các môn học khó bằng cách kết nối bài học trên lớp với những trải nghiệm hàng ngày.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_1_2_2', 'ten_b2_1_2', 'novice', 'Structured mentoring can help a novice develop the confidence needed to manage a classroom effectively.', 'Structured mentoring can help a novice develop the confidence needed to manage a classroom effectively.', '/ˈnɑːvɪs/', 'Việc cố vấn có bài bản có thể giúp một giáo viên mới vào nghề xây dựng sự tự tin cần thiết để quản lý lớp học hiệu quả.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_1_2_3', 'ten_b2_1_2', 'nursery', 'Affordable nursery places allow more parents to return to work while their children receive professional care.', 'Affordable nursery places allow more parents to return to work while their children receive professional care.', '/ˈnɝːsəri/', 'Các cơ sở nhà trẻ với mức giá phải chăng giúp nhiều phụ huynh có thể quay lại làm việc trong khi con cái họ được chăm sóc chuyên nghiệp.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_1_2_4', 'ten_b2_1_2', 'scholar', 'Scholars increasingly argue that access to early education can reduce social inequality over the long term.', 'Scholars increasingly argue that access to early education can reduce social inequality over the long term.', '/ˈskɑːlər/', 'Các học giả ngày càng lập luận rằng việc tiếp cận giáo dục sớm có thể làm giảm bất bình đẳng xã hội về lâu dài.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_1_2_5', 'ten_b2_1_2', 'reference', 'Academic essays should include accurate references so readers can locate the original sources of information.', 'Academic essays should include accurate references so readers can locate the original sources of information.', '/ˈrefərəns/', 'Các bài luận học thuật nên bao gồm các tài liệu tham khảo chính xác để người đọc có thể tìm ra nguồn gốc của thông tin.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_1_2_6', 'ten_b2_1_2', 'subheading', 'Each subheading in a research report should clearly indicate the focus of the following section.', 'Each subheading in a research report should clearly indicate the focus of the following section.', '/ˈsʌbhedɪŋ/', 'Mỗi tiêu đề phụ trong một báo cáo nghiên cứu cần chỉ rõ trọng tâm của phần tiếp theo.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_1_2_1', 'en-b2-1', 'ten_b2_1_2', 'listening', 'listening', 'Teachers can motivate students to explore difficult subjects by connecting classroom lessons with everyday experiences.', NULL, 'Trong câu vừa nghe, từ “motivate” mang nghĩa nào sau đây?', '["số thập phân","thúc đẩy; truyền động lực","có hoài bão; đầy tham vọng","xả nước; rửa sạch"]'::jsonb, 1, '“motivate” (/ˈmoʊtɪveɪt/): thúc đẩy; truyền động lực. Câu đầy đủ: Teachers can motivate students to explore difficult subjects by connecting classroom lessons with everyday experiences.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_1_2_2', 'en-b2-1', 'ten_b2_1_2', 'listening', 'listening', 'Structured mentoring can help a novice develop the confidence needed to manage a classroom effectively.', NULL, 'Trong câu vừa nghe, từ “novice” mang nghĩa nào sau đây?', '["có hại; gây tổn hại","điều khoản; điều mục trong văn bản pháp lý","sự thấu hiểu; cái nhìn sâu sắc","người mới bắt đầu; người có ít kinh nghiệm"]'::jsonb, 3, '“novice” (/ˈnɑːvɪs/): người mới bắt đầu; người có ít kinh nghiệm. Câu đầy đủ: Structured mentoring can help a novice develop the confidence needed to manage a classroom effectively.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
