INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_1_2', 'en-b2-1', NULL, 'comprehensive_test', 'listening', 'As a gardening novice, I often forget to water seedlings.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Giáo viên của chúng tôi đã dùng các tấm thẻ màu để giải thích về các liên từ.","Tiêu đề phụ này giúp tôi tìm thấy hướng dẫn nấu ăn trong công thức.","Chúng tôi đã kiểm tra thiết bị nghe nhìn trước khi bộ phim bắt đầu.","Là một người mới tập tọe làm vườn, tôi thường quên tưới nước cho cây con."]'::jsonb, 3, 'As a gardening novice, I often forget to water seedlings. → Là một người mới tập tọe làm vườn, tôi thường quên tưới nước cho cây con.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_1_3', 'en-b2-1', NULL, 'comprehensive_test', 'listening', 'nursery', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cố vấn; giáo viên hướng dẫn","thảm kịch; tai họa; tai nạn đau lòng","đều đặn; liên tục và ổn định (không có sự thay đổi hay ngắt quãng đột ngột)","nhà trẻ; trường mẫu giáo"]'::jsonb, 3, 'nursery (/ˈnɝːsəri/) → nhà trẻ; trường mẫu giáo; vườn ươm cây giống; phòng trẻ em', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_1_4', 'en-b2-1', NULL, 'comprehensive_test', 'listening', 'The scholar carefully examined an old book in the library.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Việc tôi không hiểu biết về phong tục tập quán địa phương đã dẫn đến một khoảnh khắc khó xử.","Tôi tìm thấy bức ảnh khủng long rất thú vị trong cuốn bách khoa toàn thư này.","Tôi đã tham gia một lớp học gốm vỡ lòng vào cuối tuần qua.","Vị học giả cẩn thận nghiên cứu một cuốn sách cổ trong thư viện."]'::jsonb, 3, 'The scholar carefully examined an old book in the library. → Vị học giả cẩn thận nghiên cứu một cuốn sách cổ trong thư viện.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_1_5', 'en-b2-1', NULL, 'comprehensive_test', 'listening', 'reference', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự nhắc đến; ý nhắc tới","bất chấp; mặc dù; bất kể","chủ yếu; phần lớn","chỉ trích; phê bình; chê bai"]'::jsonb, 0, 'reference (/ˈrefərəns/) → sự nhắc đến; ý nhắc tới; tài liệu tham khảo; sự tra cứu; thư giới thiệu; người giới thiệu', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_1_6', 'en-b2-1', NULL, 'comprehensive_test', 'listening', 'This subheading helps me find the recipe''s cooking instructions.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Việc tập piano mỗi sáng đòi hỏi sự kiên nhẫn và tính kỷ luật.","Tiêu đề phụ này giúp tôi tìm thấy hướng dẫn nấu ăn trong công thức.","Nhờ có sự hướng dẫn của bạn, cuối cùng tôi đã gieo hạt đúng cách.","Con gái tôi đã vẽ một chú vịt màu vàng tươi ở nhà trẻ."]'::jsonb, 1, 'This subheading helps me find the recipe''s cooking instructions. → Tiêu đề phụ này giúp tôi tìm thấy hướng dẫn nấu ăn trong công thức.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_1_7', 'en-b2-1', NULL, 'comprehensive_test', 'listening', 'comprehension', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự hiểu; khả năng hiểu","ra-đa; hệ thống định vị bằng sóng vô tuyến","đảm nhận; đảm nhiệm; tiến hành","sự tận tụy; tinh thần cống hiến"]'::jsonb, 0, 'comprehension (/ˌkɑːmprɪˈhenʃən/) → sự hiểu; khả năng hiểu', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_1_8', 'en-b2-1', NULL, 'comprehensive_test', 'listening', 'Amir shares a room with two friends at boarding school.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Amir ở chung phòng với hai người bạn tại trường nội trú.","Cô ấy thích thử thách trí tuệ khi học một ngôn ngữ mới.","Tôi tìm thấy bức ảnh khủng long rất thú vị trong cuốn bách khoa toàn thư này.","Việc tập piano mỗi sáng đòi hỏi sự kiên nhẫn và tính kỷ luật."]'::jsonb, 0, 'Amir shares a room with two friends at boarding school. → Amir ở chung phòng với hai người bạn tại trường nội trú.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
