INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_1_18', 'en-b2-1', NULL, 'comprehensive_test', 'reading', NULL, 'Teachers can motivate students to explore difficult subjects by connecting classroom lessons with everyday experiences.', 'Dựa vào câu trên, từ “motivate” có nghĩa phù hợp nhất là gì?', '["sao Kim","giấu tên; vô danh","thúc đẩy; truyền động lực","tiêm chủng; việc tiêm vắc-xin"]'::jsonb, 2, 'motivate: thúc đẩy; truyền động lực; làm động cơ cho; thúc đẩy hành động. Dịch cả câu: Giáo viên có thể truyền động lực cho học sinh khám phá các môn học khó bằng cách kết nối bài học trên lớp với những trải nghiệm hàng ngày.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_1_19', 'en-b2-1', NULL, 'comprehensive_test', 'reading', NULL, 'Structured mentoring can help a novice develop the confidence needed to manage a classroom effectively.', 'Dựa vào câu trên, từ “novice” có nghĩa phù hợp nhất là gì?', '["chạm trổ; khắc gỗ hoặc đá","tràn ra; ngập","người mới bắt đầu; người có ít kinh nghiệm","gốc cây; gốc cội"]'::jsonb, 2, 'novice: người mới bắt đầu; người có ít kinh nghiệm. Dịch cả câu: Việc cố vấn có bài bản có thể giúp một giáo viên mới vào nghề xây dựng sự tự tin cần thiết để quản lý lớp học hiệu quả.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_1_20', 'en-b2-1', NULL, 'comprehensive_test', 'reading', NULL, 'Affordable nursery places allow more parents to return to work while their children receive professional care.', 'Dựa vào câu trên, từ “nursery” có nghĩa phù hợp nhất là gì?', '["lưu huỳnh","sự vứt bỏ; sự xử lý","trích dẫn; dẫn chứng","nhà trẻ; trường mẫu giáo"]'::jsonb, 3, 'nursery: nhà trẻ; trường mẫu giáo; vườn ươm cây giống; phòng trẻ em. Dịch cả câu: Các cơ sở nhà trẻ với mức giá phải chăng giúp nhiều phụ huynh có thể quay lại làm việc trong khi con cái họ được chăm sóc chuyên nghiệp.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_1_21', 'en-b2-1', NULL, 'comprehensive_test', 'reading', NULL, 'Scholars increasingly argue that access to early education can reduce social inequality over the long term.', 'Dựa vào câu trên, từ “scholar” có nghĩa phù hợp nhất là gì?', '["học giả; nhà nghiên cứu","rìa; vùng ngoại vi","sự số ruột; sự bực bội do chờ đợi","nghị sĩ quốc hội; hạ nghị sĩ Mỹ"]'::jsonb, 0, 'scholar: học giả; nhà nghiên cứu; người nhận học bổng. Dịch cả câu: Các học giả ngày càng lập luận rằng việc tiếp cận giáo dục sớm có thể làm giảm bất bình đẳng xã hội về lâu dài.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
