INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-2', 'en', 'Bài 2: Giáo dục & Trường học (2) - CEFR B2', 'CEFR B2', 'B2 · Giáo dục', '28 từ vựng Tiếng Anh CEFR B2 chủ đề giáo dục & trường học kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4002, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_decimal', 'en-b2-2', 'decimal', '/ˈdesɪməl/', 'B2', 'số thập phân; thập phân; hệ thập phân', 'n.', NULL, NULL, 'Cụm từ "to two decimal places" dùng để chỉ việc làm tròn đến hai chữ số thập phân.', 'Our teacher showed us how to multiply two decimals.', NULL, 'Giáo viên của chúng tôi đã chỉ cho chúng tôi cách nhân hai số thập phân với nhau.', '{"wordId":"decimal","ukIpa":"/ˈdesɪməl/","usIpa":"/ˈdesɪməl/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"A number with a fractional part shown after a point.","vi":"số thập phân"},{"pos":"adj.","en":"Using a system based on ten or involving decimal fractions.","vi":"thập phân; hệ thập phân"}],"examples":[{"en":"Our teacher showed us how to multiply two decimals.","vi":"Giáo viên của chúng tôi đã chỉ cho chúng tôi cách nhân hai số thập phân với nhau.","audioKind":"ex"},{"en":"Students should understand decimal notation before they interpret statistical data in science and economics lessons.","vi":"Học sinh nên nắm vững ký hiệu thập phân trước khi diễn giải dữ liệu thống kê trong các bài học khoa học và kinh tế.","audioKind":"ex2"}],"collocations":[{"en":"decimal point","vi":"dấu phẩy thập phân"},{"en":"decimal place","vi":"chữ số thập phân"},{"en":"decimal system","vi":"hệ thập phân"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ \"to two decimal places\" dùng để chỉ việc làm tròn đến hai chữ số thập phân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tutorial', 'en-b2-2', 'tutorial', '/tuːˈtɔːriəl/', 'B2', 'buổi hướng dẫn; buổi học kèm nhỏ; bài hướng dẫn; tài liệu hướng dẫn', 'n.', 'tutor (n.), tutor (v.), tutoring (n.)', NULL, 'Có thể chỉ buổi học kèm nhóm nhỏ hoặc tài liệu, video hướng dẫn.', 'I watched a short tutorial before editing my holiday photos.', NULL, 'Tôi đã xem một đoạn video hướng dẫn ngắn trước khi chỉnh sửa ảnh kỳ nghỉ của mình.', '{"wordId":"tutorial","ukIpa":"/tjuːˈtɔːriəl/","usIpa":"/tuːˈtɔːriəl/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"A lesson where a tutor teaches individuals or small groups.","vi":"buổi hướng dẫn; buổi học kèm nhỏ"},{"pos":"n.","en":"A guide that teaches a skill through clear steps.","vi":"bài hướng dẫn; tài liệu hướng dẫn"}],"examples":[{"en":"I watched a short tutorial before editing my holiday photos.","vi":"Tôi đã xem một đoạn video hướng dẫn ngắn trước khi chỉnh sửa ảnh kỳ nghỉ của mình.","audioKind":"ex"},{"en":"Small tutorial groups allow university students to discuss complex ideas and receive detailed feedback from their tutors.","vi":"Các buổi thảo luận nhóm nhỏ giúp sinh viên đại học thảo luận về các ý tưởng phức tạp và nhận phản hồi chi tiết từ giảng viên của họ.","audioKind":"ex2"}],"collocations":[{"en":"attend a tutorial","vi":"tham gia buổi hướng dẫn"},{"en":"video tutorial","vi":"video hướng dẫn"},{"en":"step-by-step tutorial","vi":"hướng dẫn từng bước"}],"wordFamily":["tutor (n.)","tutor (v.)","tutoring (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể chỉ buổi học kèm nhóm nhỏ hoặc tài liệu, video hướng dẫn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_optional', 'en-b2-2', 'optional', '/ˈɑːpʃənəl/', 'B2', 'tùy chọn; tự nguyện; không bắt buộc', 'adj.', 'option (n.), optionally (adv.)', 'Đồng nghĩa: elective, non-compulsory · Trái nghĩa: compulsory, mandatory', 'optional có nghĩa là không bắt buộc, không phải là ngẫu nhiên hay bừa bãi.', 'The museum tour is optional, so we stayed outside.', NULL, 'Chuyến tham quan bảo tàng là tự nguyện, vì vậy chúng tôi đã ở bên ngoài.', '{"wordId":"optional","ukIpa":"/ˈɒpʃənəl/","usIpa":"/ˈɑːpʃənəl/","cefr":"B2","topic":"education","senses":[{"pos":"adj.","en":"available to choose but not required","vi":"tùy chọn; tự nguyện; không bắt buộc"}],"examples":[{"en":"The museum tour is optional, so we stayed outside.","vi":"Chuyến tham quan bảo tàng là tự nguyện, vì vậy chúng tôi đã ở bên ngoài.","audioKind":"ex"},{"en":"Schools should offer optional practical courses that allow students to explore interests beyond traditional academic subjects.","vi":"Các trường học nên cung cấp các khóa học thực hành tự chọn cho phép học sinh khám phá các sở thích ngoài các môn học hàn lâm truyền thống.","audioKind":"ex2"}],"collocations":[{"en":"optional course","vi":"khóa học tự chọn"},{"en":"optional extra","vi":"phần bổ sung tùy chọn"},{"en":"entirely optional","vi":"hoàn toàn tự nguyện"}],"wordFamily":["option (n.)","optionally (adv.)"],"synonyms":["elective","non-compulsory"],"antonyms":["compulsory","mandatory"],"tipVi":"optional có nghĩa là không bắt buộc, không phải là ngẫu nhiên hay bừa bãi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_curriculum', 'en-b2-2', 'curriculum', '/kəˈrɪkjələm/', 'B2', 'chương trình giảng dạy; chương trình học', 'n.', 'curricular (adj.), extracurricular (adj.)', NULL, 'Số nhiều là curricula hoặc curriculums; không đồng nghĩa với một môn học đơn lẻ.', 'Our school has added cooking to the curriculum.', NULL, 'Trường chúng tôi đã đưa môn nấu ăn vào chương trình học.', '{"wordId":"curriculum","ukIpa":"/kəˈrɪkjələm/","usIpa":"/kəˈrɪkjələm/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"the subjects and content included in a programme of study","vi":"chương trình giảng dạy; chương trình học"}],"examples":[{"en":"Our school has added cooking to the curriculum.","vi":"Trường chúng tôi đã đưa môn nấu ăn vào chương trình học.","audioKind":"ex"},{"en":"A balanced curriculum should develop practical skills alongside academic knowledge to prepare students for adult life.","vi":"Một chương trình giảng dạy cân đối nên phát triển các kỹ năng thực tế song song với kiến thức hàn lâm để chuẩn bị cho học sinh bước vào đời.","audioKind":"ex2"}],"collocations":[{"en":"school curriculum","vi":"chương trình học của trường"},{"en":"national curriculum","vi":"chương trình giáo dục quốc gia"},{"en":"core curriculum","vi":"chương trình cốt lõi"},{"en":"curriculum reform","vi":"cải cách giáo dục; cải cách chương trình học"}],"wordFamily":["curricular (adj.)","extracurricular (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Số nhiều là curricula hoặc curriculums; không đồng nghĩa với một môn học đơn lẻ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_submission', 'en-b2-2', 'submission', '/səbˈmɪʃən/', 'B2', 'sự nộp; tài liệu nộp; sự quy phục; sự phục tùng', 'n.', 'submit (v.), submissive (adj.), submissively (adv.)', NULL, 'Chỉ hành động nộp thường không đếm được; một tài liệu nộp là đếm được.', 'Please check your application carefully before submission tomorrow morning.', NULL, 'Xin vui lòng kiểm tra kỹ đơn đăng ký của bạn trước khi nộp vào sáng mai.', '{"wordId":"submission","ukIpa":"/səbˈmɪʃən/","usIpa":"/səbˈmɪʃən/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"the act of presenting something, or the material presented","vi":"sự nộp; tài liệu nộp"},{"pos":"n.","en":"accepting another person''s authority or control","vi":"sự quy phục; sự phục tùng"}],"examples":[{"en":"Please check your application carefully before submission tomorrow morning.","vi":"Xin vui lòng kiểm tra kỹ đơn đăng ký của bạn trước khi nộp vào sáng mai.","audioKind":"ex"},{"en":"Online submission of assignments can reduce paper consumption and allow teachers to provide feedback more efficiently.","vi":"Việc nộp bài tập trực tuyến có thể làm giảm lượng giấy tiêu thụ và giúp giáo viên đưa ra phản hồi hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"submission deadline","vi":"hạn chót nộp bài"},{"en":"submission of an application","vi":"việc nộp đơn"},{"en":"a written submission","vi":"bản thảo nộp"},{"en":"submission to authority","vi":"sự phục tùng quyền lực"}],"wordFamily":["submit (v.)","submissive (adj.)","submissively (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ hành động nộp thường không đếm được; một tài liệu nộp là đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vocational', 'en-b2-2', 'vocational', '/voʊˈkeɪʃənəl/', 'B2', 'thuộc về giáo dục nghề nghiệp; mang tính dạy nghề', 'adj.', 'vocation (n.), vocationally (adv.)', NULL, 'Thường đi kèm với "education" hoặc "training", nhấn mạnh vào các kỹ năng thực hành nghề nghiệp cụ thể.', 'My cousin chose a vocational course in plumbing.', NULL, 'Anh họ tôi đã chọn một khóa học nghề lắp đặt ống nước.', '{"wordId":"vocational","ukIpa":"/vəʊˈkeɪʃənəl/","usIpa":"/voʊˈkeɪʃənəl/","cefr":"B2","topic":"education","senses":[{"pos":"adj.","en":"Relating to practical skills and training for a particular job","vi":"thuộc về giáo dục nghề nghiệp; mang tính dạy nghề"}],"examples":[{"en":"My cousin chose a vocational course in plumbing.","vi":"Anh họ tôi đã chọn một khóa học nghề lắp đặt ống nước.","audioKind":"ex"},{"en":"Expanding vocational education can help young people develop practical skills that match the needs of local employers.","vi":"Việc mở rộng giáo dục nghề nghiệp có thể giúp người trẻ phát triển các kỹ năng thực tế phù hợp với nhu cầu của nhà tuyển dụng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"vocational training","vi":"đào tạo nghề"},{"en":"vocational education","vi":"giáo dục nghề nghiệp"},{"en":"vocational qualifications","vi":"chứng chỉ nghề"},{"en":"vocational course","vi":"khóa học nghề"}],"wordFamily":["vocation (n.)","vocationally (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường đi kèm với \"education\" hoặc \"training\", nhấn mạnh vào các kỹ năng thực hành nghề nghiệp cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_master', 'en-b2-2', 'master', '/ˈmæstɚ/', 'B2', 'nắm vững; tinh thông; bậc thầy; chuyên gia; chủ đạo; tổng thể', 'v.', 'mastery (n.), masterful (adj.), masterfully (adv.)', NULL, 'Động từ đi thẳng với tân ngữ; bằng thạc sĩ viết là master''s degree.', 'After weeks of practice, Hana finally mastered the dance.', NULL, 'Sau nhiều tuần luyện tập, Hana cuối cùng cũng thành thạo điệu nhảy này.', '{"wordId":"master","ukIpa":"/ˈmɑːstə/","usIpa":"/ˈmæstɚ/","cefr":"B2","topic":"education","senses":[{"pos":"v.","en":"To learn to do something very well.","vi":"nắm vững; tinh thông"},{"pos":"n.","en":"A person with exceptional skill in a particular activity.","vi":"bậc thầy; chuyên gia"},{"pos":"adj.","en":"Main or controlling all other related parts.","vi":"chủ đạo; tổng thể"}],"examples":[{"en":"After weeks of practice, Hana finally mastered the dance.","vi":"Sau nhiều tuần luyện tập, Hana cuối cùng cũng thành thạo điệu nhảy này.","audioKind":"ex"},{"en":"Students need opportunities to master practical skills rather than simply memorise information for examinations.","vi":"Học sinh cần có cơ hội nắm vững các kỹ năng thực tế thay vì chỉ học thuộc lòng thông tin để đi thi.","audioKind":"ex2"}],"collocations":[{"en":"master a skill","vi":"làm chủ một kỹ năng"},{"en":"a master of","vi":"bậc thầy về"},{"en":"master plan","vi":"bản quy hoạch tổng thể"},{"en":"master''s degree","vi":"bằng thạc sĩ"}],"wordFamily":["mastery (n.)","masterful (adj.)","masterfully (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ đi thẳng với tân ngữ; bằng thạc sĩ viết là master''s degree.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_moreover', 'en-b2-2', 'moreover', '/mɔːrˈoʊvɚ/', 'B2', 'hơn nữa; ngoài ra', 'adv.', NULL, 'Đồng nghĩa: furthermore, besides, additionally', 'Trạng từ chỉ sự bổ sung mang tính trang trọng; khi nối hai mệnh đề độc lập, thường đứng sau dấu chấm hoặc dấu chấm phẩy.', 'The flat is spacious; moreover, it has a balcony.', NULL, 'Căn hộ rất rộng rãi; hơn nữa, nó còn có một ban công.', '{"wordId":"moreover","ukIpa":"/mɔːrˈəʊvə/","usIpa":"/mɔːrˈoʊvɚ/","cefr":"B2","topic":"education","senses":[{"pos":"adv.","en":"Used to add another fact supporting what was just said.","vi":"hơn nữa; ngoài ra"}],"examples":[{"en":"The flat is spacious; moreover, it has a balcony.","vi":"Căn hộ rất rộng rãi; hơn nữa, nó còn có một ban công.","audioKind":"ex"},{"en":"Public parks provide space for exercise; moreover, they can strengthen community ties by encouraging informal social interaction.","vi":"Các công viên công cộng cung cấp không gian để tập thể dục; ngoài ra, chúng còn có thể củng cố mối liên kết cộng đồng bằng cách khuyến khích các hoạt động giao lưu xã hội thân mật.","audioKind":"ex2"}],"collocations":[{"en":"moreover, it is important to","vi":"hơn nữa, điều quan trọng là"},{"en":"moreover, there is evidence that","vi":"hơn nữa, có bằng chứng cho thấy"}],"wordFamily":[],"synonyms":["furthermore","besides","additionally"],"antonyms":[],"tipVi":"Trạng từ chỉ sự bổ sung mang tính trang trọng; khi nối hai mệnh đề độc lập, thường đứng sau dấu chấm hoặc dấu chấm phẩy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_proverb', 'en-b2-2', 'proverb', '/ˈprɑːvɝːb/', 'B2', 'tục ngữ; ngạn ngữ', 'n.', 'proverbial (adj.), proverbially (adv.)', 'Đồng nghĩa: saying, adage', '"proverb" là câu tục ngữ hoàn chỉnh lưu truyền trong dân gian; "idiom" thường là cụm từ cố định (thành ngữ).', 'My grandmother often quotes a proverb about being patient.', NULL, 'Bà tôi thường trích dẫn một câu tục ngữ khuyên về sự kiên nhẫn.', '{"wordId":"proverb","ukIpa":"/ˈprɒvɜːb/","usIpa":"/ˈprɑːvɝːb/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"a familiar short saying expressing advice or a general truth","vi":"tục ngữ; ngạn ngữ"}],"examples":[{"en":"My grandmother often quotes a proverb about being patient.","vi":"Bà tôi thường trích dẫn một câu tục ngữ khuyên về sự kiên nhẫn.","audioKind":"ex"},{"en":"A traditional proverb can reveal the values that a community passes down through successive generations.","vi":"Một câu tục ngữ truyền thống có thể bộc lộ những giá trị mà một cộng đồng truyền lại qua nhiều thế hệ nối tiếp nhau.","audioKind":"ex2"}],"collocations":[{"en":"traditional proverb","vi":"tục ngữ truyền thống"},{"en":"quote a proverb","vi":"trích dẫn một câu tục ngữ"},{"en":"as the proverb goes","vi":"như tục ngữ có câu"}],"wordFamily":["proverbial (adj.)","proverbially (adv.)"],"synonyms":["saying","adage"],"antonyms":[],"tipVi":"\"proverb\" là câu tục ngữ hoàn chỉnh lưu truyền trong dân gian; \"idiom\" thường là cụm từ cố định (thành ngữ).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_motivated', 'en-b2-2', 'motivated', '/ˈmoʊtɪveɪtɪd/', 'B2', 'có động lực; có tinh thần chủ động; được thúc đẩy bởi một động cơ cụ thể', 'adj.', 'motivate (v.), motivation (n.), motivational (adj.)', 'Đồng nghĩa: driven · Trái nghĩa: unmotivated', 'Cấu trúc motivated to do thể hiện có động lực làm việc gì; từ by dùng để dẫn dắt nguyên nhân động lực.', 'I feel more motivated after exercising in the morning.', NULL, 'Tôi cảm thấy có nhiều năng lượng và hứng khởi hơn sau khi tập thể dục vào buổi sáng.', '{"wordId":"motivated","ukIpa":"/ˈməʊtɪveɪtɪd/","usIpa":"/ˈmoʊtɪveɪtɪd/","cefr":"B2","topic":"education","senses":[{"pos":"adj.","en":"Eager and willing to work towards a goal.","vi":"có động lực; có tinh thần chủ động"},{"pos":"adj.","en":"Driven by a particular reason or purpose.","vi":"được thúc đẩy bởi một động cơ cụ thể"}],"examples":[{"en":"I feel more motivated after exercising in the morning.","vi":"Tôi cảm thấy có nhiều năng lượng và hứng khởi hơn sau khi tập thể dục vào buổi sáng.","audioKind":"ex"},{"en":"Students are more likely to remain motivated when teachers provide constructive feedback and achievable goals.","vi":"Học sinh có nhiều khả năng duy trì được động lực học tập hơn khi giáo viên đưa ra những lời góp ý mang tính xây dựng và các mục tiêu có thể đạt được.","audioKind":"ex2"}],"collocations":[{"en":"highly motivated","vi":"có động lực cao; rất có chí hướng"},{"en":"stay motivated","vi":"giữ vững động lực"},{"en":"motivated by profit","vi":"vì vụ lợi; xuất phát từ động cơ lợi nhuận"}],"wordFamily":["motivate (v.)","motivation (n.)","motivational (adj.)"],"synonyms":["driven"],"antonyms":["unmotivated"],"tipVi":"Cấu trúc motivated to do thể hiện có động lực làm việc gì; từ by dùng để dẫn dắt nguyên nhân động lực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_praise', 'en-b2-2', 'praise', '/preɪz/', 'B2', 'tán dương; ca ngợi; lời ca ngợi; lời tán dương', 'v.', 'praiseworthy (adj.)', 'Đồng nghĩa: commend, applaud · Trái nghĩa: criticise, criticism', 'Cấu trúc praise sb for sth; danh từ thường không đếm được.', 'Our coach praised us for helping the new players.', NULL, 'Huấn luyện viên đã khen ngợi chúng tôi vì đã giúp đỡ các cầu thủ mới.', '{"wordId":"praise","ukIpa":"/preɪz/","usIpa":"/preɪz/","cefr":"B2","topic":"education","senses":[{"pos":"v.","en":"To express approval or admiration for someone or something.","vi":"tán dương; ca ngợi"},{"pos":"n.","en":"Words expressing approval or admiration.","vi":"lời ca ngợi; lời tán dương"}],"examples":[{"en":"Our coach praised us for helping the new players.","vi":"Huấn luyện viên đã khen ngợi chúng tôi vì đã giúp đỡ các cầu thủ mới.","audioKind":"ex"},{"en":"Teachers who praise effort rather than natural ability may encourage students to persist when facing academic challenges.","vi":"Những giáo viên khen ngợi sự nỗ lực thay vì năng lực bẩm sinh có thể khuyến khích học sinh kiên trì hơn khi đối mặt với các thử thách học tập.","audioKind":"ex2"}],"collocations":[{"en":"praise someone for something","vi":"khen ngợi ai vì điều gì"},{"en":"win praise","vi":"giành được lời ca ngợi"},{"en":"high praise","vi":"sự ca ngợi cao"},{"en":"lavish praise on","vi":"tán dương nồng nhiệt"}],"wordFamily":["praiseworthy (adj.)"],"synonyms":["commend","applaud"],"antonyms":["criticise","criticism"],"tipVi":"Cấu trúc praise sb for sth; danh từ thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_faculty', 'en-b2-2', 'faculty', '/ˈfæklti/', 'B2', 'khoa (trong trường đại học); ban giảng huấn; đội ngũ giảng viên; năng lực (tâm lý hoặc thể chất); quan năng', 'n.', NULL, NULL, 'Trong tiếng Anh-Anh, faculty thường chỉ khoa trong đại học, còn tiếng Anh-Mỹ thường chỉ toàn thể giảng viên.', 'The science faculty has moved into a new building.', NULL, 'Khoa khoa học tự nhiên đã chuyển sang một tòa nhà mới.', '{"wordId":"faculty","ukIpa":"/ˈfæklti/","usIpa":"/ˈfæklti/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"A university division covering a particular group of subjects.","vi":"khoa (trong trường đại học)"},{"pos":"n.","en":"The teaching staff of a university, college, or school.","vi":"ban giảng huấn; đội ngũ giảng viên"},{"pos":"n.","en":"A natural mental or physical ability.","vi":"năng lực (tâm lý hoặc thể chất); quan năng"}],"examples":[{"en":"The science faculty has moved into a new building.","vi":"Khoa khoa học tự nhiên đã chuyển sang một tòa nhà mới.","audioKind":"ex"},{"en":"Cooperation between the faculty of engineering and local industries can help students develop skills relevant to employment.","vi":"Sự hợp tác giữa khoa kỹ thuật và các ngành công nghiệp địa phương có thể giúp sinh viên phát triển các kỹ năng phù hợp với nhu cầu việc làm.","audioKind":"ex2"}],"collocations":[{"en":"the faculty of science","vi":"khoa khoa học"},{"en":"faculty members","vi":"các thành viên giảng dạy"},{"en":"mental faculties","vi":"năng lực tư duy"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh, faculty thường chỉ khoa trong đại học, còn tiếng Anh-Mỹ thường chỉ toàn thể giảng viên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_motivation', 'en-b2-2', 'motivation', '/ˌmoʊtɪˈveɪʃən/', 'B2', 'động lực; sự nhiệt huyết; động cơ; lý do', 'n.', 'motivate (v.), motivated (adj.), motivational (adj.), motive (n.)', 'Đồng nghĩa: drive, incentive · Trái nghĩa: apathy', 'Động lực nói chung thường không đếm được; động cơ cụ thể thì đếm được, thường đi với for hoặc behind.', 'Training with a friend gives me motivation to keep running.', NULL, 'Tập luyện cùng một người bạn mang lại cho tôi động lực để tiếp tục chạy bộ.', '{"wordId":"motivation","ukIpa":"/ˌməʊtɪˈveɪʃən/","usIpa":"/ˌmoʊtɪˈveɪʃən/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"The desire and energy that make you want to act.","vi":"động lực; sự nhiệt huyết"},{"pos":"n.","en":"A reason for doing something or behaving in a particular way.","vi":"động cơ; lý do"}],"examples":[{"en":"Training with a friend gives me motivation to keep running.","vi":"Tập luyện cùng một người bạn mang lại cho tôi động lực để tiếp tục chạy bộ.","audioKind":"ex"},{"en":"Giving students meaningful choices can increase their motivation and encourage them to take responsibility for learning.","vi":"Việc trao cho học sinh những sự lựa chọn ý nghĩa có thể nâng cao động lực của các em và khuyến khích các em chịu trách nhiệm về việc học của mình.","audioKind":"ex2"}],"collocations":[{"en":"lack of motivation","vi":"thiếu động lực"},{"en":"intrinsic motivation","vi":"động lực bên trong"},{"en":"motivation to learn","vi":"động lực học tập"},{"en":"motivation behind a decision","vi":"động cơ đằng sau một quyết định"}],"wordFamily":["motivate (v.)","motivated (adj.)","motivational (adj.)","motive (n.)"],"synonyms":["drive","incentive"],"antonyms":["apathy"],"tipVi":"Động lực nói chung thường không đếm được; động cơ cụ thể thì đếm được, thường đi với for hoặc behind.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inspire', 'en-b2-2', 'inspire', '/ɪnˈspaɪr/', 'B2', 'truyền cảm hứng; khích lệ; gợi cảm hứng; khơi nguồn sáng tạo; khơi dậy; tạo ra (cảm xúc)', 'v.', 'inspiration (n.), inspiring (adj.), inspired (adj.)', 'Đồng nghĩa: motivate, encourage · Trái nghĩa: discourage', 'Thường dùng cấu trúc "inspire sb to do sth" để diễn tả việc truyền cảm hứng, khích lệ ai đó làm gì.', 'Our coach inspired us to try again after losing.', NULL, 'Huấn luyện viên đã khích lệ chúng tôi thử lại sau khi thua cuộc.', '{"wordId":"inspire","ukIpa":"/ɪnˈspaɪə/","usIpa":"/ɪnˈspaɪr/","cefr":"B2","topic":"education","senses":[{"pos":"v.","en":"to make someone feel eager and able to do something","vi":"truyền cảm hứng; khích lệ"},{"pos":"v.","en":"to give someone an idea for something creative","vi":"gợi cảm hứng; khơi nguồn sáng tạo"},{"pos":"v.","en":"to cause a particular feeling in someone","vi":"khơi dậy; tạo ra (cảm xúc)"}],"examples":[{"en":"Our coach inspired us to try again after losing.","vi":"Huấn luyện viên đã khích lệ chúng tôi thử lại sau khi thua cuộc.","audioKind":"ex"},{"en":"Teachers who connect lessons with real problems can inspire students to pursue careers in science.","vi":"Những giáo viên biết gắn kết bài học với các vấn đề thực tế có thể truyền cảm hứng cho học sinh theo đuổi sự nghiệp khoa học.","audioKind":"ex2"}],"collocations":[{"en":"inspire someone to act","vi":"khích lệ ai đó hành động"},{"en":"inspire confidence","vi":"tạo dựng niềm tin"},{"en":"inspire creativity","vi":"khơi dậy sự sáng tạo"},{"en":"be inspired by nature","vi":"lấy cảm hứng từ thiên nhiên"}],"wordFamily":["inspiration (n.)","inspiring (adj.)","inspired (adj.)"],"synonyms":["motivate","encourage"],"antonyms":["discourage"],"tipVi":"Thường dùng cấu trúc \"inspire sb to do sth\" để diễn tả việc truyền cảm hứng, khích lệ ai đó làm gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_seminar', 'en-b2-2', 'seminar', '/ˈsemɪnɑːr/', 'B2', 'buổi seminar; hội thảo chuyên đề', 'n.', NULL, NULL, 'seminar nhấn mạnh thảo luận giao lưu; lecture thường do giáo viên giảng dạy là chính.', 'We discussed our research ideas during the afternoon seminar.', NULL, 'Chúng tôi đã thảo luận về các ý tưởng nghiên cứu của mình trong buổi hội thảo chuyên đề buổi chiều.', '{"wordId":"seminar","ukIpa":"/ˈsemɪnɑː/","usIpa":"/ˈsemɪnɑːr/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"A meeting where a group studies or discusses a subject.","vi":"buổi seminar; hội thảo chuyên đề"}],"examples":[{"en":"We discussed our research ideas during the afternoon seminar.","vi":"Chúng tôi đã thảo luận về các ý tưởng nghiên cứu của mình trong buổi hội thảo chuyên đề buổi chiều.","audioKind":"ex"},{"en":"University seminars encourage students to evaluate different perspectives rather than simply memorise information presented by lecturers.","vi":"Các buổi hội thảo ở trường đại học khuyến khích sinh viên đánh giá các góc nhìn khác nhau thay vì chỉ đơn thuần ghi nhớ thông tin do giảng viên cung cấp.","audioKind":"ex2"}],"collocations":[{"en":"attend a seminar","vi":"tham gia hội thảo"},{"en":"lead a seminar","vi":"chủ trì buổi seminar"},{"en":"a seminar on education","vi":"một hội thảo về giáo dục"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"seminar nhấn mạnh thảo luận giao lưu; lecture thường do giáo viên giảng dạy là chính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_acquire', 'en-b2-2', 'acquire', '/əˈkwaɪr/', 'B2', 'đạt được; mua lại; sắm được; thu được; lĩnh hội; tiếp thu kiến thức hoặc kỹ năng', 'v.', 'acquisition (n.), acquired (adj.)', 'Đồng nghĩa: obtain, gain · Trái nghĩa: lose', 'Trang trọng hơn get; có thể kết hợp với tài sản, hoặc kiến thức và kỹ năng.', 'We acquired a secondhand table for our tiny kitchen.', NULL, 'Chúng tôi đã mua lại một chiếc bàn cũ cho căn bếp nhỏ xíu của mình.', '{"wordId":"acquire","ukIpa":"/əˈkwaɪə/","usIpa":"/əˈkwaɪr/","cefr":"B2","topic":"education","senses":[{"pos":"v.","en":"Get or become the owner of something.","vi":"đạt được; mua lại; sắm được"},{"pos":"v.","en":"Develop knowledge or skills through learning or experience.","vi":"thu được; lĩnh hội; tiếp thu kiến thức hoặc kỹ năng"}],"examples":[{"en":"We acquired a secondhand table for our tiny kitchen.","vi":"Chúng tôi đã mua lại một chiếc bàn cũ cho căn bếp nhỏ xíu của mình.","audioKind":"ex"},{"en":"Work placements allow students to acquire practical skills that are difficult to develop through classroom learning alone.","vi":"Các đợt thực tập giúp sinh viên tích lũy các kỹ năng thực tế vốn rất khó phát triển nếu chỉ học qua sách vở trên lớp.","audioKind":"ex2"}],"collocations":[{"en":"acquire skills","vi":"lĩnh hội kỹ năng"},{"en":"acquire knowledge","vi":"tiếp thu kiến thức"},{"en":"acquire a company","vi":"thâu tóm một công ty"},{"en":"an acquired taste","vi":"gu thưởng thức phải qua trải nghiệm mới có"}],"wordFamily":["acquisition (n.)","acquired (adj.)"],"synonyms":["obtain","gain"],"antonyms":["lose"],"tipVi":"Trang trọng hơn get; có thể kết hợp với tài sản, hoặc kiến thức và kỹ năng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bullying', 'en-b2-2', 'bullying', '/ˈbʊliɪŋ/', 'B2', 'hành vi bắt nạt; nạn bạo lực học đường; hành vi đe dọa; sự uy hiếp', 'n.', 'bully (v.), bully (n.)', NULL, 'Được dùng như danh từ không đếm được; cũng có thể là dạng phân từ của bully.', 'She reported the bullying to her teacher after lunch.', NULL, 'Cô bé đã báo cáo vụ bắt nạt với giáo viên của mình sau giờ ăn trưa.', '{"wordId":"bullying","ukIpa":"/ˈbʊliɪŋ/","usIpa":"/ˈbʊliɪŋ/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"Repeated behaviour intended to hurt, frighten, or control someone","vi":"hành vi bắt nạt; nạn bạo lực học đường"},{"pos":"v.","en":"Repeatedly hurting or frightening someone with less power","vi":"hành vi đe dọa; sự uy hiếp"}],"examples":[{"en":"She reported the bullying to her teacher after lunch.","vi":"Cô bé đã báo cáo vụ bắt nạt với giáo viên của mình sau giờ ăn trưa.","audioKind":"ex"},{"en":"Schools should address bullying through clear reporting procedures and consistent support for affected students.","vi":"Các trường học nên giải quyết tình trạng bắt nạt thông qua các quy trình báo cáo rõ ràng và sự hỗ trợ kiên trì dành cho những học sinh bị ảnh hưởng.","audioKind":"ex2"}],"collocations":[{"en":"school bullying","vi":"bắt nạt học đường"},{"en":"online bullying","vi":"bắt nạt trên mạng"},{"en":"prevent bullying","vi":"phòng ngừa nạn bắt nạt"}],"wordFamily":["bully (v.)","bully (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Được dùng như danh từ không đếm được; cũng có thể là dạng phân từ của bully.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_handbook', 'en-b2-2', 'handbook', '/ˈhændbʊk/', 'B2', 'sổ tay; cẩm nang', 'n.', NULL, 'Đồng nghĩa: manual, guide', 'Chỉ hướng dẫn thực tế dễ tra cứu, không phải sách giáo khoa thông thường.', 'I checked the gardening handbook before pruning the rose.', NULL, 'Tôi đã tra cứu cuốn sổ tay làm vườn trước khi cắt tỉa cây hoa hồng.', '{"wordId":"handbook","ukIpa":"/ˈhændbʊk/","usIpa":"/ˈhændbʊk/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"A book giving practical information or instructions about a subject","vi":"sổ tay; cẩm nang"}],"examples":[{"en":"I checked the gardening handbook before pruning the rose.","vi":"Tôi đã tra cứu cuốn sổ tay làm vườn trước khi cắt tỉa cây hoa hồng.","audioKind":"ex"},{"en":"A comprehensive employee handbook helps new staff understand workplace procedures and reduces confusion about their responsibilities.","vi":"Một cuốn sổ tay nhân viên toàn diện giúp nhân viên mới hiểu rõ các quy trình làm việc và giảm bớt sự bối rối về trách nhiệm của họ.","audioKind":"ex2"}],"collocations":[{"en":"employee handbook","vi":"sổ tay nhân viên"},{"en":"student handbook","vi":"sổ tay sinh viên"},{"en":"practical handbook","vi":"cẩm nang thực tế"}],"wordFamily":[],"synonyms":["manual","guide"],"antonyms":[],"tipVi":"Chỉ hướng dẫn thực tế dễ tra cứu, không phải sách giáo khoa thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mathematical', 'en-b2-2', 'mathematical', '/ˌmæθəˈmætɪkəl/', 'B2', 'thuộc về toán học; có tính toán học', 'adj.', 'mathematics (n.), mathematically (adv.), mathematician (n.)', NULL, 'mathematics là tên môn học, mặc dù có tận cùng bằng chữ s nhưng đi với động từ số ít.', 'This puzzle really puts your mathematical skills to work.', NULL, 'Trò chơi trí tuệ này thực sự giúp bạn vận dụng các kỹ năng toán học của mình.', '{"wordId":"mathematical","ukIpa":"/ˌmæθəˈmætɪkəl/","usIpa":"/ˌmæθəˈmætɪkəl/","cefr":"B2","topic":"education","senses":[{"pos":"adj.","en":"relating to mathematics","vi":"thuộc về toán học; có tính toán học"}],"examples":[{"en":"This puzzle really puts your mathematical skills to work.","vi":"Trò chơi trí tuệ này thực sự giúp bạn vận dụng các kỹ năng toán học của mình.","audioKind":"ex"},{"en":"Mathematical models help researchers predict how rising temperatures may affect coastal communities over time.","vi":"Các mô hình toán học giúp các nhà nghiên cứu dự đoán nhiệt độ tăng cao có thể tác động dần theo thời gian đến các cộng đồng ven biển như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"mathematical model","vi":"mô hình toán học"},{"en":"mathematical skills","vi":"kỹ năng toán học"},{"en":"mathematical calculation","vi":"phép tính toán học"}],"wordFamily":["mathematics (n.)","mathematically (adv.)","mathematician (n.)"],"synonyms":[],"antonyms":[],"tipVi":"mathematics là tên môn học, mặc dù có tận cùng bằng chữ s nhưng đi với động từ số ít.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_intensive', 'en-b2-2', 'intensive', '/ɪnˈtensɪv/', 'B2', 'chuyên sâu; cấp tốc; cường độ cao; thâm canh; tập trung đầu tư', 'adj.', 'intense (adj.), intensively (adv.), intensity (n.), intensify (v.)', NULL, 'intensive nhấn mạnh sự tập trung đầu tư (tài nguyên, thời gian, công sức); intense nhấn mạnh cảm xúc hoặc mức độ vô cùng mạnh mẽ.', 'I took an intensive swimming course during the holidays.', NULL, 'Tôi đã tham gia một khóa học bơi cấp tốc trong kỳ nghỉ.', '{"wordId":"intensive","ukIpa":"/ɪnˈtensɪv/","usIpa":"/ɪnˈtensɪv/","cefr":"B2","topic":"education","senses":[{"pos":"adj.","en":"involving much work or effort within a short period","vi":"chuyên sâu; cấp tốc; cường độ cao"},{"pos":"adj.","en":"using large amounts of resources to produce high output","vi":"thâm canh; tập trung đầu tư"}],"examples":[{"en":"I took an intensive swimming course during the holidays.","vi":"Tôi đã tham gia một khóa học bơi cấp tốc trong kỳ nghỉ.","audioKind":"ex"},{"en":"Intensive farming can increase food production, but it may also damage soil quality and reduce biodiversity.","vi":"Nông nghiệp thâm canh có thể nâng cao sản lượng lương thực, nhưng đồng thời cũng có thể làm suy thoái chất lượng đất và làm giảm đa dạng sinh học.","audioKind":"ex2"}],"collocations":[{"en":"an intensive course","vi":"khóa học cấp tốc"},{"en":"intensive care","vi":"chăm sóc tích cực"},{"en":"intensive farming","vi":"nông nghiệp thâm canh"},{"en":"labour-intensive production","vi":"sản xuất thâm dụng lao động"}],"wordFamily":["intense (adj.)","intensively (adv.)","intensity (n.)","intensify (v.)"],"synonyms":[],"antonyms":[],"tipVi":"intensive nhấn mạnh sự tập trung đầu tư (tài nguyên, thời gian, công sức); intense nhấn mạnh cảm xúc hoặc mức độ vô cùng mạnh mẽ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_independently', 'en-b2-2', 'independently', '/ˌɪndɪˈpendəntli/', 'B2', 'độc lập; không cần sự giúp đỡ; riêng biệt; tách biệt', 'adv.', 'independent (adj.), independence (n.), dependent (adj.), dependently (adv.)', 'Đồng nghĩa: autonomously, separately · Trái nghĩa: dependently', 'Để diễn tả ý "không phụ thuộc vào...", hãy dùng "independently of".', 'My grandmother still lives independently in her own flat.', NULL, 'Bà tôi vẫn sống độc lập trong căn hộ riêng của mình.', '{"wordId":"independently","ukIpa":"/ˌɪndɪˈpendəntli/","usIpa":"/ˌɪndɪˈpendəntli/","cefr":"B2","topic":"education","senses":[{"pos":"adv.","en":"Without needing help or support from others.","vi":"độc lập; không cần sự giúp đỡ"},{"pos":"adv.","en":"Separately, without being connected to or influenced by something else.","vi":"riêng biệt; tách biệt"}],"examples":[{"en":"My grandmother still lives independently in her own flat.","vi":"Bà tôi vẫn sống độc lập trong căn hộ riêng của mình.","audioKind":"ex"},{"en":"Students who learn to work independently are often better prepared for the demands of higher education.","vi":"Những học sinh học cách làm việc độc lập thường chuẩn bị tốt hơn cho các yêu cầu của giáo dục đại học.","audioKind":"ex2"}],"collocations":[{"en":"live independently","vi":"sống độc lập"},{"en":"work independently","vi":"làm việc độc lập"},{"en":"independently of","vi":"độc lập khỏi"},{"en":"independently verified","vi":"được kiểm chứng độc lập"}],"wordFamily":["independent (adj.)","independence (n.)","dependent (adj.)","dependently (adv.)"],"synonyms":["autonomously","separately"],"antonyms":["dependently"],"tipVi":"Để diễn tả ý \"không phụ thuộc vào...\", hãy dùng \"independently of\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fluency', 'en-b2-2', 'fluency', '/ˈfluːənsi/', 'B2', 'sự lưu loát (ngoại ngữ); sự trôi chảy; sự thành thạo', 'n.', 'fluent (adj.), fluently (adv.)', 'Trái nghĩa: hesitancy', 'Thường là danh từ không đếm được; dùng "fluency in" để chỉ mức độ lưu loát một ngôn ngữ nào đó.', 'Daily chats with friends have improved my fluency in English.', NULL, 'Những cuộc trò chuyện hàng ngày với bạn bè đã cải thiện sự lưu loát tiếng Anh của tôi.', '{"wordId":"fluency","ukIpa":"/ˈfluːənsi/","usIpa":"/ˈfluːənsi/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"The ability to use a language easily and smoothly.","vi":"sự lưu loát (ngoại ngữ)"},{"pos":"n.","en":"The quality of performing an activity smoothly and confidently.","vi":"sự trôi chảy; sự thành thạo"}],"examples":[{"en":"Daily chats with friends have improved my fluency in English.","vi":"Những cuộc trò chuyện hàng ngày với bạn bè đã cải thiện sự lưu loát tiếng Anh của tôi.","audioKind":"ex"},{"en":"Language courses should develop fluency alongside accuracy so that learners can communicate confidently in unfamiliar situations.","vi":"Các khóa học ngôn ngữ nên phát triển cả sự trôi chảy lẫn tính chính xác để người học có thể tự tin giao tiếp trong các tình huống lạ.","audioKind":"ex2"}],"collocations":[{"en":"fluency in English","vi":"sự lưu loát tiếng Anh"},{"en":"oral fluency","vi":"độ trôi chảy khi nói"},{"en":"develop fluency","vi":"nâng cao sự lưu loát"}],"wordFamily":["fluent (adj.)","fluently (adv.)"],"synonyms":[],"antonyms":["hesitancy"],"tipVi":"Thường là danh từ không đếm được; dùng \"fluency in\" để chỉ mức độ lưu loát một ngôn ngữ nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_engage', 'en-b2-2', 'engage', '/ɪnˈɡeɪdʒ/', 'B2', 'thu hút; làm say mê; giữ chân; tham gia; dấn thân; thuê; tuyển dụng', 'v.', 'engagement (n.), engaging (adj.), engaged (adj.)', 'Đồng nghĩa: involve, attract, hire · Trái nghĩa: disengage', 'Tham gia vào hoạt động dùng engage in; tương tác với mọi người dùng engage with.', 'The puppet show engaged even the youngest children.', NULL, 'Buổi biểu diễn múa rối đã thu hút ngay cả những đứa trẻ nhỏ tuổi nhất.', '{"wordId":"engage","ukIpa":"/ɪnˈɡeɪdʒ/","usIpa":"/ɪnˈɡeɪdʒ/","cefr":"B2","topic":"education","senses":[{"pos":"v.","en":"To attract someone''s attention and keep them interested or involved.","vi":"thu hút; làm say mê; giữ chân"},{"pos":"v.","en":"To take part in an activity.","vi":"tham gia; dấn thân"},{"pos":"v.","en":"To hire someone to perform a particular job.","vi":"thuê; tuyển dụng"}],"examples":[{"en":"The puppet show engaged even the youngest children.","vi":"Buổi biểu diễn múa rối đã thu hút ngay cả những đứa trẻ nhỏ tuổi nhất.","audioKind":"ex"},{"en":"Schools should encourage students to engage in community activities that develop cooperation and a sense of responsibility.","vi":"Nhà trường nên khuyến khích học sinh tham gia các hoạt động cộng đồng nhằm phát triển kỹ năng hợp tác và tinh thần trách nhiệm.","audioKind":"ex2"}],"collocations":[{"en":"engage in discussion","vi":"tham gia thảo luận"},{"en":"engage with an audience","vi":"tương tác với khán giả"},{"en":"engage someone''s attention","vi":"thu hút sự chú ý của ai đó"},{"en":"engage a consultant","vi":"thuê một chuyên gia tư vấn"}],"wordFamily":["engagement (n.)","engaging (adj.)","engaged (adj.)"],"synonyms":["involve","attract","hire"],"antonyms":["disengage"],"tipVi":"Tham gia vào hoạt động dùng engage in; tương tác với mọi người dùng engage with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_demonstration', 'en-b2-2', 'demonstration', '/ˌdemənˈstreɪʃən/', 'B2', 'sự thuyết trình; sự biểu diễn; sự minh họa; cuộc biểu tình; sự chứng minh; sự biểu lộ', 'n.', 'demonstrate (v.), demonstrator (n.), demonstrable (adj.)', NULL, 'Dùng cụm ''demonstration of'' khi muốn nói đến việc biểu diễn cách làm một việc gì đó.', 'The chef gave a demonstration of bread making.', NULL, 'Đầu bếp đã thực hiện màn trình diễn cách làm bánh mì.', '{"wordId":"demonstration","ukIpa":"/ˌdemənˈstreɪʃən/","usIpa":"/ˌdemənˈstreɪʃən/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"An act of showing how something works or is done","vi":"sự thuyết trình; sự biểu diễn; sự minh họa"},{"pos":"n.","en":"A public gathering expressing strong opinions about an issue","vi":"cuộc biểu tình"},{"pos":"n.","en":"An action or event that clearly shows something","vi":"sự chứng minh; sự biểu lộ"}],"examples":[{"en":"The chef gave a demonstration of bread making.","vi":"Đầu bếp đã thực hiện màn trình diễn cách làm bánh mì.","audioKind":"ex"},{"en":"A practical demonstration can help students understand scientific principles more effectively than a written explanation alone.","vi":"Một buổi biểu diễn thực tế có thể giúp học sinh hiểu các nguyên tắc khoa học hiệu quả hơn so với việc chỉ giải thích bằng văn bản.","audioKind":"ex2"}],"collocations":[{"en":"give a demonstration","vi":"thực hiện màn biểu diễn"},{"en":"a peaceful demonstration","vi":"một cuộc biểu tình hòa bình"},{"en":"a demonstration of support","vi":"sự thể hiện sự ủng hộ"}],"wordFamily":["demonstrate (v.)","demonstrator (n.)","demonstrable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng cụm ''demonstration of'' khi muốn nói đến việc biểu diễn cách làm một việc gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_linguist', 'en-b2-2', 'linguist', '/ˈlɪŋɡwɪst/', 'B2', 'nhà ngôn ngữ học; người giỏi ngoại ngữ', 'n.', 'linguistics (n.), linguistic (adj.), linguistically (adv.)', NULL, '"linguist" chỉ người; "linguistics" là tên môn học ngôn ngữ học (dạng số ít).', 'The linguist recorded my grandmother telling an old story.', NULL, 'Nhà ngôn ngữ học đã ghi âm bà tôi kể lại một câu chuyện cổ.', '{"wordId":"linguist","ukIpa":"/ˈlɪŋɡwɪst/","usIpa":"/ˈlɪŋɡwɪst/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"a person who studies how language works","vi":"nhà ngôn ngữ học"},{"pos":"n.","en":"a person skilled at speaking or learning several languages","vi":"người giỏi ngoại ngữ"}],"examples":[{"en":"The linguist recorded my grandmother telling an old story.","vi":"Nhà ngôn ngữ học đã ghi âm bà tôi kể lại một câu chuyện cổ.","audioKind":"ex"},{"en":"Linguists can support endangered languages by documenting local speech and helping communities develop teaching materials.","vi":"Các nhà ngôn ngữ học có thể hỗ trợ bảo tồn các ngôn ngữ đang có nguy cơ tuyệt chủng bằng cách ghi chép lại lời ăn tiếng nói địa phương và giúp cộng đồng phát triển tài liệu giảng dạy.","audioKind":"ex2"}],"collocations":[{"en":"applied linguist","vi":"nhà ngôn ngữ học ứng dụng"},{"en":"trained linguist","vi":"nhà ngôn ngữ học được đào tạo chuyên nghiệp"},{"en":"gifted linguist","vi":"người có năng khiếu ngoại ngữ"}],"wordFamily":["linguistics (n.)","linguistic (adj.)","linguistically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"\"linguist\" chỉ người; \"linguistics\" là tên môn học ngôn ngữ học (dạng số ít).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_evaluation', 'en-b2-2', 'evaluation', '/ɪˌvæljuˈeɪʃən/', 'B2', 'sự đánh giá; sự thẩm định', 'n.', 'evaluate (v.), evaluative (adj.), evaluator (n.)', 'Đồng nghĩa: assessment, appraisal', 'Thường đi với of; nhấn mạnh về chất lượng hoặc hiệu quả, trong khi định giá tiền bạc thường dùng valuation.', 'The coach''s evaluation helped me improve my swimming technique.', NULL, 'Lời nhận xét đánh giá của huấn luyện viên đã giúp tôi cải thiện kỹ thuật bơi của mình.', '{"wordId":"evaluation","ukIpa":"/ɪˌvæljuˈeɪʃən/","usIpa":"/ɪˌvæljuˈeɪʃən/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"the process of judging something''s quality, value, or effectiveness","vi":"sự đánh giá; sự thẩm định"}],"examples":[{"en":"The coach''s evaluation helped me improve my swimming technique.","vi":"Lời nhận xét đánh giá của huấn luyện viên đã giúp tôi cải thiện kỹ thuật bơi của mình.","audioKind":"ex"},{"en":"Regular evaluation of educational programmes allows schools to identify weaknesses and allocate resources more effectively.","vi":"Việc đánh giá thường xuyên các chương trình giáo dục giúp các nhà trường nhận ra những điểm yếu và phân bổ nguồn lực hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"carry out an evaluation","vi":"tiến hành đánh giá"},{"en":"performance evaluation","vi":"đánh giá năng lực"},{"en":"critical evaluation","vi":"đánh giá phản biện"},{"en":"evaluation criteria","vi":"tiêu chí đánh giá"}],"wordFamily":["evaluate (v.)","evaluative (adj.)","evaluator (n.)"],"synonyms":["assessment","appraisal"],"antonyms":[],"tipVi":"Thường đi với of; nhấn mạnh về chất lượng hoặc hiệu quả, trong khi định giá tiền bạc thường dùng valuation.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_imitation', 'en-b2-2', 'imitation', '/ˌɪmɪˈteɪʃən/', 'B2', 'sự bắt chước; sự mô phỏng; hàng giả; vật sao chép; giả; nhân tạo', 'n.', 'imitate (v.), imitative (adj.), imitator (n.)', 'Đồng nghĩa: copying', 'Hành vi bắt chước thường là danh từ không đếm được; một món đồ giả dùng là an imitation.', 'His imitation of a sleepy cat made us laugh.', NULL, 'Hành động bắt chước một chú mèo đang buồn ngủ của anh ấy khiến chúng tôi cười lớn.', '{"wordId":"imitation","ukIpa":"/ˌɪmɪˈteɪʃən/","usIpa":"/ˌɪmɪˈteɪʃən/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"The act of copying someone''s behaviour or something''s appearance.","vi":"sự bắt chước; sự mô phỏng"},{"pos":"n.","en":"An object made to look like another, often more valuable, object.","vi":"hàng giả; vật sao chép"},{"pos":"adj.","en":"Made to resemble a natural or more expensive material.","vi":"giả; nhân tạo"}],"examples":[{"en":"His imitation of a sleepy cat made us laugh.","vi":"Hành động bắt chước một chú mèo đang buồn ngủ của anh ấy khiến chúng tôi cười lớn.","audioKind":"ex"},{"en":"Young children acquire many social skills through imitation, making positive adult behaviour especially important in early education.","vi":"Trẻ nhỏ tiếp thu nhiều kỹ năng xã hội thông qua việc bắt chước, điều này khiến cho hành vi tích cực của người lớn trở nên đặc biệt quan trọng trong giáo dục mầm non.","audioKind":"ex2"}],"collocations":[{"en":"learn by imitation","vi":"học thông qua việc bắt chước"},{"en":"a poor imitation","vi":"một bản sao kém chất lượng; hàng nhái kém"},{"en":"imitation leather","vi":"da nhân tạo"},{"en":"in imitation of","vi":"bắt chước theo..."}],"wordFamily":["imitate (v.)","imitative (adj.)","imitator (n.)"],"synonyms":["copying"],"antonyms":[],"tipVi":"Hành vi bắt chước thường là danh từ không đếm được; một món đồ giả dùng là an imitation.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_broaden', 'en-b2-2', 'broaden', '/ˈbrɔːdən/', 'B2', 'mở rộng; làm phong phú; làm rộng ra', 'v.', 'broad (adj.), broadly (adv.), breadth (n.)', 'Đồng nghĩa: widen, expand · Trái nghĩa: narrow, restrict', 'Thường dùng cho phạm vi trừu tượng; broaden your horizons có nghĩa là mở rộng tầm nhìn.', 'Trying new recipes has broadened my knowledge of different cuisines.', NULL, 'Việc thử nghiệm các công thức nấu ăn mới đã mở rộng hiểu biết của tôi về các nền ẩm thực khác nhau.', '{"wordId":"broaden","ukIpa":"/ˈbrɔːdən/","usIpa":"/ˈbrɔːdən/","cefr":"B2","topic":"education","senses":[{"pos":"v.","en":"Increase the range of knowledge, experience, or available choices.","vi":"mở rộng; làm phong phú"},{"pos":"v.","en":"Become wider, or make something wider.","vi":"làm rộng ra; mở rộng"}],"examples":[{"en":"Trying new recipes has broadened my knowledge of different cuisines.","vi":"Việc thử nghiệm các công thức nấu ăn mới đã mở rộng hiểu biết của tôi về các nền ẩm thực khác nhau.","audioKind":"ex"},{"en":"Schools should broaden access to arts education so that students from all backgrounds can develop their creative abilities.","vi":"Các trường học nên mở rộng quyền tiếp cận giáo dục nghệ thuật để học sinh từ mọi hoàn cảnh đều có thể phát triển năng lực sáng tạo của mình.","audioKind":"ex2"}],"collocations":[{"en":"broaden your horizons","vi":"mở rộng tầm nhìn"},{"en":"broaden your knowledge","vi":"mở rộng kiến thức"},{"en":"broaden access to","vi":"mở rộng cơ hội tiếp cận..."},{"en":"broaden the scope","vi":"mở rộng phạm vi"}],"wordFamily":["broad (adj.)","broadly (adv.)","breadth (n.)"],"synonyms":["widen","expand"],"antonyms":["narrow","restrict"],"tipVi":"Thường dùng cho phạm vi trừu tượng; broaden your horizons có nghĩa là mở rộng tầm nhìn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 28, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_2_1', 'en-b2-2', 'Cách dùng “intensive” (adj.) — chuyên sâu; cấp tốc; cường độ cao', 'an intensive course  ·  intensive care  ·  intensive farming', 'intensive nhấn mạnh sự tập trung đầu tư (tài nguyên, thời gian, công sức); intense nhấn mạnh cảm xúc hoặc mức độ vô cùng mạnh mẽ.', 'Họ từ (Word Family): intense (adj.), intensively (adv.), intensity (n.), intensify (v.)', '[{"hanzi":"I took an intensive swimming course during the holidays.","pinyin":"","meaning":"Tôi đã tham gia một khóa học bơi cấp tốc trong kỳ nghỉ."},{"hanzi":"Intensive farming can increase food production, but it may also damage soil quality and reduce biodiversity.","pinyin":"","meaning":"Nông nghiệp thâm canh có thể nâng cao sản lượng lương thực, nhưng đồng thời cũng có thể làm suy thoái chất lượng đất và làm giảm đa dạng sinh học."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_2_2', 'en-b2-2', 'Cách dùng “moreover” (adv.) — hơn nữa; ngoài ra', 'moreover, it is important to  ·  moreover, there is evidence that', 'Trạng từ chỉ sự bổ sung mang tính trang trọng; khi nối hai mệnh đề độc lập, thường đứng sau dấu chấm hoặc dấu chấm phẩy.', 'Đồng nghĩa: furthermore, besides, additionally', '[{"hanzi":"The flat is spacious; moreover, it has a balcony.","pinyin":"","meaning":"Căn hộ rất rộng rãi; hơn nữa, nó còn có một ban công."},{"hanzi":"Public parks provide space for exercise; moreover, they can strengthen community ties by encouraging informal social interaction.","pinyin":"","meaning":"Các công viên công cộng cung cấp không gian để tập thể dục; ngoài ra, chúng còn có thể củng cố mối liên kết cộng đồng bằng cách khuyến khích các hoạt động giao lưu xã hội thân mật."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_2_3', 'en-b2-2', 'Cách dùng “proverb” (n.) — tục ngữ; ngạn ngữ', 'traditional proverb  ·  quote a proverb  ·  as the proverb goes', '"proverb" là câu tục ngữ hoàn chỉnh lưu truyền trong dân gian; "idiom" thường là cụm từ cố định (thành ngữ).', 'Họ từ (Word Family): proverbial (adj.), proverbially (adv.) | Đồng nghĩa: saying, adage', '[{"hanzi":"My grandmother often quotes a proverb about being patient.","pinyin":"","meaning":"Bà tôi thường trích dẫn một câu tục ngữ khuyên về sự kiên nhẫn."},{"hanzi":"A traditional proverb can reveal the values that a community passes down through successive generations.","pinyin":"","meaning":"Một câu tục ngữ truyền thống có thể bộc lộ những giá trị mà một cộng đồng truyền lại qua nhiều thế hệ nối tiếp nhau."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_2_4', 'en-b2-2', 'Cách dùng “faculty” (n.) — khoa (trong trường đại học)', 'the faculty of science  ·  faculty members  ·  mental faculties', 'Trong tiếng Anh-Anh, faculty thường chỉ khoa trong đại học, còn tiếng Anh-Mỹ thường chỉ toàn thể giảng viên.', NULL, '[{"hanzi":"The science faculty has moved into a new building.","pinyin":"","meaning":"Khoa khoa học tự nhiên đã chuyển sang một tòa nhà mới."},{"hanzi":"Cooperation between the faculty of engineering and local industries can help students develop skills relevant to employment.","pinyin":"","meaning":"Sự hợp tác giữa khoa kỹ thuật và các ngành công nghiệp địa phương có thể giúp sinh viên phát triển các kỹ năng phù hợp với nhu cầu việc làm."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_2_1', 'en-b2-2', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_2_1_1', 'ten_b2_2_1', 'decimal', 'Our teacher showed us how to multiply two decimals.', 'Our teacher showed us how to multiply two decimals.', '/ˈdesɪməl/', 'Giáo viên của chúng tôi đã chỉ cho chúng tôi cách nhân hai số thập phân với nhau.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_2_1_2', 'ten_b2_2_1', 'tutorial', 'I watched a short tutorial before editing my holiday photos.', 'I watched a short tutorial before editing my holiday photos.', '/tuːˈtɔːriəl/', 'Tôi đã xem một đoạn video hướng dẫn ngắn trước khi chỉnh sửa ảnh kỳ nghỉ của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_2_1_3', 'ten_b2_2_1', 'optional', 'The museum tour is optional, so we stayed outside.', 'The museum tour is optional, so we stayed outside.', '/ˈɑːpʃənəl/', 'Chuyến tham quan bảo tàng là tự nguyện, vì vậy chúng tôi đã ở bên ngoài.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_2_1_4', 'ten_b2_2_1', 'curriculum', 'Our school has added cooking to the curriculum.', 'Our school has added cooking to the curriculum.', '/kəˈrɪkjələm/', 'Trường chúng tôi đã đưa môn nấu ăn vào chương trình học.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_2_1_5', 'ten_b2_2_1', 'submission', 'Please check your application carefully before submission tomorrow morning.', 'Please check your application carefully before submission tomorrow morning.', '/səbˈmɪʃən/', 'Xin vui lòng kiểm tra kỹ đơn đăng ký của bạn trước khi nộp vào sáng mai.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_2_1_6', 'ten_b2_2_1', 'vocational', 'My cousin chose a vocational course in plumbing.', 'My cousin chose a vocational course in plumbing.', '/voʊˈkeɪʃənəl/', 'Anh họ tôi đã chọn một khóa học nghề lắp đặt ống nước.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_2_1_7', 'ten_b2_2_1', 'master', 'After weeks of practice, Hana finally mastered the dance.', 'After weeks of practice, Hana finally mastered the dance.', '/ˈmæstɚ/', 'Sau nhiều tuần luyện tập, Hana cuối cùng cũng thành thạo điệu nhảy này.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_2_1_8', 'ten_b2_2_1', 'moreover', 'The flat is spacious; moreover, it has a balcony.', 'The flat is spacious; moreover, it has a balcony.', '/mɔːrˈoʊvɚ/', 'Căn hộ rất rộng rãi; hơn nữa, nó còn có một ban công.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_2_1_1', 'en-b2-2', 'ten_b2_2_1', 'listening', 'listening', 'Our teacher showed us how to multiply two decimals.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Buổi biểu diễn múa rối đã thu hút ngay cả những đứa trẻ nhỏ tuổi nhất.","Trường chúng tôi đã đưa môn nấu ăn vào chương trình học.","Giáo viên của chúng tôi đã chỉ cho chúng tôi cách nhân hai số thập phân với nhau.","Căn hộ rất rộng rãi; hơn nữa, nó còn có một ban công."]'::jsonb, 2, 'Our teacher showed us how to multiply two decimals. → Giáo viên của chúng tôi đã chỉ cho chúng tôi cách nhân hai số thập phân với nhau.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_2_1_2', 'en-b2-2', 'ten_b2_2_1', 'listening', 'listening', 'I watched a short tutorial before editing my holiday photos.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hành động bắt chước một chú mèo đang buồn ngủ của anh ấy khiến chúng tôi cười lớn.","Trò chơi trí tuệ này thực sự giúp bạn vận dụng các kỹ năng toán học của mình.","Tôi đã xem một đoạn video hướng dẫn ngắn trước khi chỉnh sửa ảnh kỳ nghỉ của mình.","Chúng tôi đã thảo luận về các ý tưởng nghiên cứu của mình trong buổi hội thảo chuyên đề buổi chiều."]'::jsonb, 2, 'I watched a short tutorial before editing my holiday photos. → Tôi đã xem một đoạn video hướng dẫn ngắn trước khi chỉnh sửa ảnh kỳ nghỉ của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_2_1_3', 'en-b2-2', 'ten_b2_2_1', 'listening', 'listening', 'The museum tour is optional, so we stayed outside.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Huấn luyện viên đã khích lệ chúng tôi thử lại sau khi thua cuộc.","Khoa khoa học tự nhiên đã chuyển sang một tòa nhà mới.","Chuyến tham quan bảo tàng là tự nguyện, vì vậy chúng tôi đã ở bên ngoài.","Trường chúng tôi đã đưa môn nấu ăn vào chương trình học."]'::jsonb, 2, 'The museum tour is optional, so we stayed outside. → Chuyến tham quan bảo tàng là tự nguyện, vì vậy chúng tôi đã ở bên ngoài.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_2_2', 'en-b2-2', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_2_2_1', 'ten_b2_2_2', 'decimal', 'Students should understand decimal notation before they interpret statistical data in science and economics lessons.', 'Students should understand decimal notation before they interpret statistical data in science and economics lessons.', '/ˈdesɪməl/', 'Học sinh nên nắm vững ký hiệu thập phân trước khi diễn giải dữ liệu thống kê trong các bài học khoa học và kinh tế.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_2_2_2', 'ten_b2_2_2', 'tutorial', 'Small tutorial groups allow university students to discuss complex ideas and receive detailed feedback from their tutors.', 'Small tutorial groups allow university students to discuss complex ideas and receive detailed feedback from their tutors.', '/tuːˈtɔːriəl/', 'Các buổi thảo luận nhóm nhỏ giúp sinh viên đại học thảo luận về các ý tưởng phức tạp và nhận phản hồi chi tiết từ giảng viên của họ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_2_2_3', 'ten_b2_2_2', 'optional', 'Schools should offer optional practical courses that allow students to explore interests beyond traditional academic subjects.', 'Schools should offer optional practical courses that allow students to explore interests beyond traditional academic subjects.', '/ˈɑːpʃənəl/', 'Các trường học nên cung cấp các khóa học thực hành tự chọn cho phép học sinh khám phá các sở thích ngoài các môn học hàn lâm truyền thống.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_2_2_4', 'ten_b2_2_2', 'curriculum', 'A balanced curriculum should develop practical skills alongside academic knowledge to prepare students for adult life.', 'A balanced curriculum should develop practical skills alongside academic knowledge to prepare students for adult life.', '/kəˈrɪkjələm/', 'Một chương trình giảng dạy cân đối nên phát triển các kỹ năng thực tế song song với kiến thức hàn lâm để chuẩn bị cho học sinh bước vào đời.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_2_2_5', 'ten_b2_2_2', 'submission', 'Online submission of assignments can reduce paper consumption and allow teachers to provide feedback more efficiently.', 'Online submission of assignments can reduce paper consumption and allow teachers to provide feedback more efficiently.', '/səbˈmɪʃən/', 'Việc nộp bài tập trực tuyến có thể làm giảm lượng giấy tiêu thụ và giúp giáo viên đưa ra phản hồi hiệu quả hơn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_2_2_6', 'ten_b2_2_2', 'vocational', 'Expanding vocational education can help young people develop practical skills that match the needs of local employers.', 'Expanding vocational education can help young people develop practical skills that match the needs of local employers.', '/voʊˈkeɪʃənəl/', 'Việc mở rộng giáo dục nghề nghiệp có thể giúp người trẻ phát triển các kỹ năng thực tế phù hợp với nhu cầu của nhà tuyển dụng địa phương.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_2_2_1', 'en-b2-2', 'ten_b2_2_2', 'listening', 'listening', 'Students should understand decimal notation before they interpret statistical data in science and economics lessons.', NULL, 'Trong câu vừa nghe, từ “decimal” mang nghĩa nào sau đây?', '["loại bỏ; xóa bỏ hoàn toàn","số thập phân","kê đơn (thuốc); chỉ định điều trị","thay đổi; biến đổi"]'::jsonb, 1, '“decimal” (/ˈdesɪməl/): số thập phân. Câu đầy đủ: Students should understand decimal notation before they interpret statistical data in science and economics lessons.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_2_2_2', 'en-b2-2', 'ten_b2_2_2', 'listening', 'listening', 'Small tutorial groups allow university students to discuss complex ideas and receive detailed feedback from their tutors.', NULL, 'Trong câu vừa nghe, từ “tutorial” mang nghĩa nào sau đây?', '["làm mờ; trở nên mờ đi","củ cải; củ cải đỏ nhỏ","buổi hướng dẫn; buổi học kèm nhỏ","gạt bỏ; xem nhẹ; không màng tới"]'::jsonb, 2, '“tutorial” (/tuːˈtɔːriəl/): buổi hướng dẫn; buổi học kèm nhỏ. Câu đầy đủ: Small tutorial groups allow university students to discuss complex ideas and receive detailed feedback from their tutors.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
