INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_2_6', 'en-b2-2', 'My cousin chose a vocational course in plumbing', 'Anh họ tôi đã chọn một khóa học nghề lắp đặt ống nước.', 'vocational /voʊˈkeɪʃənəl/', '["My","chose","vocational","in","a","plumbing","course","cousin"]'::jsonb, NULL, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_2_7', 'en-b2-2', 'After weeks of practice, Hana finally mastered the dance', 'Sau nhiều tuần luyện tập, Hana cuối cùng cũng thành thạo điệu nhảy này.', 'master /ˈmæstɚ/', '["mastered","of","finally","weeks","the","Hana","After","dance","practice"]'::jsonb, NULL, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
