INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_2_1', 'en-b2-2', NULL, 'comprehensive_test', 'listening', 'decimal', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["vừa phải; trung bình; điều độ","số thập phân","sự đặt mua; sự đăng ký dài hạn","gãy bẻ bộp; đứt phựt"]'::jsonb, 1, 'decimal (/ˈdesɪməl/) → số thập phân; thập phân; hệ thập phân', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_2_2', 'en-b2-2', NULL, 'comprehensive_test', 'listening', 'I watched a short tutorial before editing my holiday photos.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã xem một đoạn video hướng dẫn ngắn trước khi chỉnh sửa ảnh kỳ nghỉ của mình.","Sau nhiều tuần luyện tập, Hana cuối cùng cũng thành thạo điệu nhảy này.","Huấn luyện viên đã khích lệ chúng tôi thử lại sau khi thua cuộc.","Anh họ tôi đã chọn một khóa học nghề lắp đặt ống nước."]'::jsonb, 0, 'I watched a short tutorial before editing my holiday photos. → Tôi đã xem một đoạn video hướng dẫn ngắn trước khi chỉnh sửa ảnh kỳ nghỉ của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_2_3', 'en-b2-2', NULL, 'comprehensive_test', 'listening', 'optional', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tùy chọn; tự nguyện; không bắt buộc","bắt cóc; cướp giữ người trái phép","có thể đoán trước; dự đoán được","xấu xa; độc ác"]'::jsonb, 0, 'optional (/ˈɑːpʃənəl/) → tùy chọn; tự nguyện; không bắt buộc', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_2_4', 'en-b2-2', NULL, 'comprehensive_test', 'listening', 'Our school has added cooking to the curriculum.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Trường chúng tôi đã đưa môn nấu ăn vào chương trình học.","Tôi cảm thấy có nhiều năng lượng và hứng khởi hơn sau khi tập thể dục vào buổi sáng.","Giáo viên của chúng tôi đã chỉ cho chúng tôi cách nhân hai số thập phân với nhau.","Đầu bếp đã thực hiện màn trình diễn cách làm bánh mì."]'::jsonb, 0, 'Our school has added cooking to the curriculum. → Trường chúng tôi đã đưa môn nấu ăn vào chương trình học.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_2_5', 'en-b2-2', NULL, 'comprehensive_test', 'listening', 'submission', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["làm cho sai lạc; đánh lừa; dẫn dắt sai đường","tội phạm; hành vi phạm pháp","cuộn lại; uốn xoăn; làm cong","sự nộp; tài liệu nộp"]'::jsonb, 3, 'submission (/səbˈmɪʃən/) → sự nộp; tài liệu nộp; sự quy phục; sự phục tùng', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_2_6', 'en-b2-2', NULL, 'comprehensive_test', 'listening', 'My cousin chose a vocational course in plumbing.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Xin vui lòng kiểm tra kỹ đơn đăng ký của bạn trước khi nộp vào sáng mai.","Đầu bếp đã thực hiện màn trình diễn cách làm bánh mì.","Tôi đã tra cứu cuốn sổ tay làm vườn trước khi cắt tỉa cây hoa hồng.","Anh họ tôi đã chọn một khóa học nghề lắp đặt ống nước."]'::jsonb, 3, 'My cousin chose a vocational course in plumbing. → Anh họ tôi đã chọn một khóa học nghề lắp đặt ống nước.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_2_7', 'en-b2-2', NULL, 'comprehensive_test', 'listening', 'master', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chăm sóc da; việc dưỡng da","liên tục; luôn luôn; thường xuyên","nắm vững; tinh thông","trên (thường dùng trong văn phong trang trọng hoặc văn chương)"]'::jsonb, 2, 'master (/ˈmæstɚ/) → nắm vững; tinh thông; bậc thầy; chuyên gia; chủ đạo; tổng thể', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_2_8', 'en-b2-2', NULL, 'comprehensive_test', 'listening', 'The flat is spacious; moreover, it has a balcony.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Việc thử nghiệm các công thức nấu ăn mới đã mở rộng hiểu biết của tôi về các nền ẩm thực khác nhau.","Trò chơi trí tuệ này thực sự giúp bạn vận dụng các kỹ năng toán học của mình.","Căn hộ rất rộng rãi; hơn nữa, nó còn có một ban công.","Những cuộc trò chuyện hàng ngày với bạn bè đã cải thiện sự lưu loát tiếng Anh của tôi."]'::jsonb, 2, 'The flat is spacious; moreover, it has a balcony. → Căn hộ rất rộng rãi; hơn nữa, nó còn có một ban công.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_2_9', 'en-b2-2', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “the act of presenting something, or the material presented”?', '["broaden","optional","submission","faculty"]'::jsonb, 2, 'submission (/səbˈmɪʃən/) → sự nộp; tài liệu nộp', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
