INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_2_18', 'en-b2-2', NULL, 'comprehensive_test', 'reading', NULL, 'Students should understand decimal notation before they interpret statistical data in science and economics lessons.', 'Dựa vào câu trên, từ “decimal” có nghĩa phù hợp nhất là gì?', '["chắc chắn; không nghi ngờ gì; rõ ràng là","số thập phân","rủi ro thấp","luồng (khí, khói, hơi nước); làn (gió nhẹ)"]'::jsonb, 1, 'decimal: số thập phân; thập phân; hệ thập phân. Dịch cả câu: Học sinh nên nắm vững ký hiệu thập phân trước khi diễn giải dữ liệu thống kê trong các bài học khoa học và kinh tế.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_2_19', 'en-b2-2', NULL, 'comprehensive_test', 'reading', NULL, 'Small tutorial groups allow university students to discuss complex ideas and receive detailed feedback from their tutors.', 'Dựa vào câu trên, từ “tutorial” có nghĩa phù hợp nhất là gì?', '["thủ công; bằng tay","làm say mê; thu hút sâu sắc","buổi hướng dẫn; buổi học kèm nhỏ","phòng suite (phòng khách sạn gồm nhiều phòng thông nhau); phòng thượng hạng"]'::jsonb, 2, 'tutorial: buổi hướng dẫn; buổi học kèm nhỏ; bài hướng dẫn; tài liệu hướng dẫn. Dịch cả câu: Các buổi thảo luận nhóm nhỏ giúp sinh viên đại học thảo luận về các ý tưởng phức tạp và nhận phản hồi chi tiết từ giảng viên của họ.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_2_20', 'en-b2-2', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should offer optional practical courses that allow students to explore interests beyond traditional academic subjects.', 'Dựa vào câu trên, từ “optional” có nghĩa phù hợp nhất là gì?', '["vi khuẩn","có thể xảy ra; có khả năng cao","tùy chọn; tự nguyện; không bắt buộc","sâu bọ; loài gây hại"]'::jsonb, 2, 'optional: tùy chọn; tự nguyện; không bắt buộc. Dịch cả câu: Các trường học nên cung cấp các khóa học thực hành tự chọn cho phép học sinh khám phá các sở thích ngoài các môn học hàn lâm truyền thống.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_2_21', 'en-b2-2', NULL, 'comprehensive_test', 'reading', NULL, 'A balanced curriculum should develop practical skills alongside academic knowledge to prepare students for adult life.', 'Dựa vào câu trên, từ “curriculum” có nghĩa phù hợp nhất là gì?', '["buổi thử vai; buổi thử giọng","lâu dài; bền vững; kéo dài","sự thuyết trình; sự biểu diễn; sự minh họa","chương trình giảng dạy; chương trình học"]'::jsonb, 3, 'curriculum: chương trình giảng dạy; chương trình học. Dịch cả câu: Một chương trình giảng dạy cân đối nên phát triển các kỹ năng thực tế song song với kiến thức hàn lâm để chuẩn bị cho học sinh bước vào đời.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_2_22', 'en-b2-2', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự đánh giá; sự thẩm định”', '["democratic","dealer","publicly","evaluation"]'::jsonb, 3, 'sự đánh giá; sự thẩm định → evaluation (/ɪˌvæljuˈeɪʃən/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_2_23', 'en-b2-2', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự bắt chước; sự mô phỏng”', '["rot","alongside","imitation","executive"]'::jsonb, 2, 'sự bắt chước; sự mô phỏng → imitation (/ˌɪmɪˈteɪʃən/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_2_24', 'en-b2-2', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “mở rộng; làm phong phú”', '["objection","bark","broaden","likewise"]'::jsonb, 2, 'mở rộng; làm phong phú → broaden (/ˈbrɔːdən/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-3', 'en', 'Bài 3: Giáo dục & Trường học (3) - CEFR B2', 'CEFR B2', 'B2 · Giáo dục', '27 từ vựng Tiếng Anh CEFR B2 chủ đề giáo dục & trường học kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4003, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_enrol', 'en-b2-3', 'enrol', '/ɪnˈroʊl/', 'B2', 'ghi danh; đăng ký; tuyển sinh', 'v.', 'enrolment (n.)', 'Đồng nghĩa: register, sign up', 'Cách viết enrol là tiếng Anh-Anh, enroll là tiếng Anh-Mỹ; dạng quá khứ đều là enrolled.', 'I plan to enrol on a cooking course next month.', NULL, 'Tôi dự định đăng ký một khóa học nấu ăn vào tháng tới.', '{"wordId":"enrol","ukIpa":"/ɪnˈrəʊl/","usIpa":"/ɪnˈroʊl/","cefr":"B2","topic":"education","senses":[{"pos":"v.","en":"Officially join, or register someone for, a course or organisation.","vi":"ghi danh; đăng ký; tuyển sinh"}],"examples":[{"en":"I plan to enrol on a cooking course next month.","vi":"Tôi dự định đăng ký một khóa học nấu ăn vào tháng tới.","audioKind":"ex"},{"en":"Governments can encourage adults to enrol in vocational training by offering flexible schedules and financial support.","vi":"Chính phủ có thể khuyến khích người lớn tham gia đào tạo nghề bằng cách cung cấp lịch học linh hoạt và hỗ trợ tài chính.","audioKind":"ex2"}],"collocations":[{"en":"enrol on a course","vi":"đăng ký một khóa học"},{"en":"enrol in a programme","vi":"đăng ký tham gia một chương trình"},{"en":"enrol students","vi":"tuyển sinh học viên"}],"wordFamily":["enrolment (n.)"],"synonyms":["register","sign up"],"antonyms":[],"tipVi":"Cách viết enrol là tiếng Anh-Anh, enroll là tiếng Anh-Mỹ; dạng quá khứ đều là enrolled.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_undergraduate', 'en-b2-3', 'undergraduate', '/ˌʌndərˈɡrædʒuət/', 'B2', 'sinh viên đại học chưa tốt nghiệp; sinh viên bậc cử nhân; thuộc về bậc đại học; dành cho sinh viên bậc cử nhân', 'n.', 'graduate (n.), postgraduate (n.), graduation (n.)', NULL, 'Chỉ sinh viên đang theo học tấm bằng đại học đầu tiên, không đồng nghĩa với sinh viên bỏ học hay sinh viên dự bị.', 'My sister is an undergraduate studying chemistry nearby.', NULL, 'Chị gái tôi là sinh viên năm nhất đại học đang học ngành hóa học ở gần đây.', '{"wordId":"undergraduate","ukIpa":"/ˌʌndəˈɡrædʒuət/","usIpa":"/ˌʌndərˈɡrædʒuət/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"a university student studying for a first degree","vi":"sinh viên đại học chưa tốt nghiệp; sinh viên bậc cử nhân"},{"pos":"adj.","en":"relating to study for a first university degree","vi":"thuộc về bậc đại học; dành cho sinh viên bậc cử nhân"}],"examples":[{"en":"My sister is an undergraduate studying chemistry nearby.","vi":"Chị gái tôi là sinh viên năm nhất đại học đang học ngành hóa học ở gần đây.","audioKind":"ex"},{"en":"Many undergraduate courses now include practical placements to help students prepare for their future careers.","vi":"Nhiều chương trình đào tạo bậc cử nhân hiện nay bao gồm các đợt thực tập thực tế để giúp sinh viên chuẩn bị cho sự nghiệp tương lai.","audioKind":"ex2"}],"collocations":[{"en":"undergraduate student","vi":"sinh viên đại học"},{"en":"undergraduate degree","vi":"bằng cử nhân đại học"},{"en":"undergraduate course","vi":"chương trình đào tạo đại học"}],"wordFamily":["graduate (n.)","postgraduate (n.)","graduation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ sinh viên đang theo học tấm bằng đại học đầu tiên, không đồng nghĩa với sinh viên bỏ học hay sinh viên dự bị.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_knowledgeable', 'en-b2-3', 'knowledgeable', '/ˈnɑːlɪdʒəbəl/', 'B2', 'am hiểu; uyên bác; có kiến thức sâu rộng', 'adj.', 'knowledge (n.), know (v.)', 'Đồng nghĩa: well-informed · Trái nghĩa: ignorant', 'Thường dùng cấu trúc knowledgeable about để diễn tả sự am hiểu sâu về một lĩnh vực nào đó.', 'Our knowledgeable guide explained how each garden plant grows.', NULL, 'Hướng dẫn viên am hiểu của chúng tôi đã giải thích cách từng loại cây trong vườn phát triển.', '{"wordId":"knowledgeable","ukIpa":"/ˈnɒlɪdʒəbəl/","usIpa":"/ˈnɑːlɪdʒəbəl/","cefr":"B2","topic":"education","senses":[{"pos":"adj.","en":"knowing a lot about a particular subject","vi":"am hiểu; uyên bác; có kiến thức sâu rộng"}],"examples":[{"en":"Our knowledgeable guide explained how each garden plant grows.","vi":"Hướng dẫn viên am hiểu của chúng tôi đã giải thích cách từng loại cây trong vườn phát triển.","audioKind":"ex"},{"en":"Knowledgeable teachers can help students evaluate online information rather than accept every claim they encounter.","vi":"Những giáo viên am hiểu có thể giúp học sinh đánh giá thông tin trên mạng thay vì tiếp nhận mọi tuyên bố mà các em bắt gặp.","audioKind":"ex2"}],"collocations":[{"en":"knowledgeable about","vi":"am hiểu về..."},{"en":"knowledgeable staff","vi":"đội ngũ nhân viên am hiểu chuyên môn"},{"en":"a knowledgeable guide","vi":"hướng dẫn viên giàu kiến thức"}],"wordFamily":["knowledge (n.)","know (v.)"],"synonyms":["well-informed"],"antonyms":["ignorant"],"tipVi":"Thường dùng cấu trúc knowledgeable about để diễn tả sự am hiểu sâu về một lĩnh vực nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_detailed', 'en-b2-3', 'detailed', '/dɪˈteɪld/', 'B2', 'chi tiết; tỉ mỉ; tường tận', 'adj.', 'detail (n.), detail (v.)', 'Đồng nghĩa: thorough, comprehensive · Trái nghĩa: vague', 'Diễn đạt ý "một cách chi tiết" dùng "in detail", không dùng "in detailed".', 'She gave me detailed instructions for baking the cake.', NULL, 'Cô ấy đưa cho tôi hướng dẫn chi tiết để làm bánh ngọt.', '{"wordId":"detailed","ukIpa":"/ˈdiːteɪld/","usIpa":"/dɪˈteɪld/","cefr":"B2","topic":"education","senses":[{"pos":"adj.","en":"Including many facts or specific pieces of information.","vi":"chi tiết; tỉ mỉ; tường tận"}],"examples":[{"en":"She gave me detailed instructions for baking the cake.","vi":"Cô ấy đưa cho tôi hướng dẫn chi tiết để làm bánh ngọt.","audioKind":"ex"},{"en":"Detailed research into commuting patterns can help cities design more efficient public transport systems.","vi":"Nghiên cứu chi tiết về các mô hình đi lại có thể giúp các thành phố thiết kế hệ thống giao thông công cộng hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"detailed description","vi":"mô tả chi tiết"},{"en":"detailed analysis","vi":"phân tích chi tiết"},{"en":"detailed instructions","vi":"hướng dẫn chi tiết"}],"wordFamily":["detail (n.)","detail (v.)"],"synonyms":["thorough","comprehensive"],"antonyms":["vague"],"tipVi":"Diễn đạt ý \"một cách chi tiết\" dùng \"in detail\", không dùng \"in detailed\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_qualify', 'en-b2-3', 'qualify', '/ˈkwɑːlɪfaɪ/', 'B2', 'đạt điều kiện; đủ tiêu chuẩn; đạt văn bằng chuyên môn; đủ năng lực hành nghề; làm cho rõ nghĩa hơn; hạn chế', 'v.', 'qualification (n.), qualified (adj.), unqualified (adj.), disqualify (v.)', 'Trái nghĩa: disqualify', 'qualify for đi với cơ hội hoặc quyền lợi; qualify as đi với nghề nghiệp.', 'Our team needs another win to qualify for the final.', NULL, 'Đội của chúng tôi cần chiến thắng thêm một trận nữa để lọt vào vòng chung kết.', '{"wordId":"qualify","ukIpa":"/ˈkwɒlɪfaɪ/","usIpa":"/ˈkwɑːlɪfaɪ/","cefr":"B2","topic":"education","senses":[{"pos":"v.","en":"To meet requirements, or make someone suitable for something.","vi":"đạt điều kiện; đủ tiêu chuẩn"},{"pos":"v.","en":"To complete the training needed for a profession.","vi":"đạt văn bằng chuyên môn; đủ năng lực hành nghề"},{"pos":"v.","en":"To limit a statement so it is more accurate.","vi":"làm cho rõ nghĩa hơn; hạn chế"}],"examples":[{"en":"Our team needs another win to qualify for the final.","vi":"Đội của chúng tôi cần chiến thắng thêm một trận nữa để lọt vào vòng chung kết.","audioKind":"ex"},{"en":"Students from low-income households may qualify for financial support that covers tuition fees and essential living costs.","vi":"Học sinh từ các hộ gia đình thu nhập thấp có thể đủ điều kiện nhận hỗ trợ tài chính để chi trả học phí và các chi phí sinh hoạt thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"qualify for assistance","vi":"đủ điều kiện nhận trợ cấp"},{"en":"qualify as a teacher","vi":"đạt chứng chỉ giáo viên"},{"en":"qualify a statement","vi":"giới hạn một phát ngôn"}],"wordFamily":["qualification (n.)","qualified (adj.)","unqualified (adj.)","disqualify (v.)"],"synonyms":[],"antonyms":["disqualify"],"tipVi":"qualify for đi với cơ hội hoặc quyền lợi; qualify as đi với nghề nghiệp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_adequately', 'en-b2-3', 'adequately', '/ˈædɪkwətli/', 'B2', 'đầy đủ; thỏa đáng; tương xứng', 'adv.', 'adequate (adj.), adequacy (n.), inadequate (adj.), inadequately (adv.)', 'Đồng nghĩa: sufficiently, satisfactorily · Trái nghĩa: inadequately, insufficiently', 'Nhấn mạnh việc đạt đến tiêu chuẩn cần thiết, không nhất thiết mang ý nghĩa là xuất sắc.', 'This small heater adequately warms our entire bedroom.', NULL, 'Chiếc lò sưởi nhỏ này sưởi ấm đủ cho toàn bộ phòng ngủ của chúng tôi.', '{"wordId":"adequately","ukIpa":"/ˈædɪkwətli/","usIpa":"/ˈædɪkwətli/","cefr":"B2","topic":"education","senses":[{"pos":"adv.","en":"well enough or in sufficient amounts for a particular purpose","vi":"đầy đủ; thỏa đáng; tương xứng"}],"examples":[{"en":"This small heater adequately warms our entire bedroom.","vi":"Chiếc lò sưởi nhỏ này sưởi ấm đủ cho toàn bộ phòng ngủ của chúng tôi.","audioKind":"ex"},{"en":"Schools must be adequately funded to provide all children with equal opportunities to learn.","vi":"Các trường học cần được cấp kinh phí đầy đủ để cung cấp cho mọi trẻ em cơ hội học tập bình đẳng.","audioKind":"ex2"}],"collocations":[{"en":"adequately funded","vi":"được tài trợ đầy đủ"},{"en":"adequately prepared","vi":"được chuẩn bị chu đáo"},{"en":"adequately address","vi":"giải quyết thỏa đáng"}],"wordFamily":["adequate (adj.)","adequacy (n.)","inadequate (adj.)","inadequately (adv.)"],"synonyms":["sufficiently","satisfactorily"],"antonyms":["inadequately","insufficiently"],"tipVi":"Nhấn mạnh việc đạt đến tiêu chuẩn cần thiết, không nhất thiết mang ý nghĩa là xuất sắc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_verbal', 'en-b2-3', 'verbal', '/ˈvɝːbəl/', 'B2', 'bằng lời nói; dạng nói (thay vì dạng viết); thuộc về từ ngữ; liên quan đến ngôn từ', 'adj.', 'verbally (adv.), verbalise (v.), non-verbal (adj.)', 'Đồng nghĩa: oral, spoken · Trái nghĩa: non-verbal', 'verbal cũng dùng để chỉ việc diễn đạt bằng từ ngữ, không phải lúc nào cũng đối lập hoàn toàn với written.', 'We made a verbal agreement to share the garden.', NULL, 'Chúng tôi đã đạt được thỏa thuận miệng về việc dùng chung khu vườn.', '{"wordId":"verbal","ukIpa":"/ˈvɜːbəl/","usIpa":"/ˈvɝːbəl/","cefr":"B2","topic":"education","senses":[{"pos":"adj.","en":"spoken rather than written","vi":"bằng lời nói; dạng nói (thay vì dạng viết)"},{"pos":"adj.","en":"relating to words or the use of language","vi":"thuộc về từ ngữ; liên quan đến ngôn từ"}],"examples":[{"en":"We made a verbal agreement to share the garden.","vi":"Chúng tôi đã đạt được thỏa thuận miệng về việc dùng chung khu vườn.","audioKind":"ex"},{"en":"Employers should confirm verbal agreements in writing to prevent misunderstandings about working hours and responsibilities.","vi":"Người sử dụng lao động nên xác nhận các thỏa thuận miệng bằng văn bản để tránh những hiểu lầm về thời gian làm việc và trách nhiệm.","audioKind":"ex2"}],"collocations":[{"en":"a verbal agreement","vi":"thỏa thuận miệng"},{"en":"verbal communication","vi":"giao tiếp bằng lời nói"},{"en":"verbal skills","vi":"kỹ năng ngôn ngữ"},{"en":"a verbal warning","vi":"lời cảnh cáo bằng miệng"}],"wordFamily":["verbally (adv.)","verbalise (v.)","non-verbal (adj.)"],"synonyms":["oral","spoken"],"antonyms":["non-verbal"],"tipVi":"verbal cũng dùng để chỉ việc diễn đạt bằng từ ngữ, không phải lúc nào cũng đối lập hoàn toàn với written.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_comprehensive', 'en-b2-3', 'comprehensive', '/ˌkɑːmprɪˈhensɪv/', 'B2', 'toàn diện; bao quát; chi tiết', 'adj.', 'comprehensively (adv.), comprehensiveness (n.)', 'Đồng nghĩa: thorough, wide-ranging · Trái nghĩa: partial, limited', 'Nhấn mạnh phạm vi bao quát rộng lớn, không mang nghĩa là dễ hiểu.', 'This comprehensive guide covers every trail in the park.', NULL, 'Cẩm nang chi tiết này bao trùm mọi tuyến đường mòn trong công viên.', '{"wordId":"comprehensive","ukIpa":"/ˌkɒmprɪˈhensɪv/","usIpa":"/ˌkɑːmprɪˈhensɪv/","cefr":"B2","topic":"education","senses":[{"pos":"adj.","en":"Covering all or nearly all important parts of something.","vi":"toàn diện; bao quát; chi tiết"}],"examples":[{"en":"This comprehensive guide covers every trail in the park.","vi":"Cẩm nang chi tiết này bao trùm mọi tuyến đường mòn trong công viên.","audioKind":"ex"},{"en":"Schools should provide comprehensive health education to help students make informed decisions about their lifestyles.","vi":"Nhà trường nên cung cấp giáo dục sức khỏe toàn diện để giúp học sinh đưa ra những quyết định sáng suốt về lối sống của mình.","audioKind":"ex2"}],"collocations":[{"en":"comprehensive guide","vi":"hướng dẫn toàn diện"},{"en":"comprehensive review","vi":"đánh giá toàn diện"},{"en":"comprehensive assessment","vi":"thẩm định tổng thể"}],"wordFamily":["comprehensively (adv.)","comprehensiveness (n.)"],"synonyms":["thorough","wide-ranging"],"antonyms":["partial","limited"],"tipVi":"Nhấn mạnh phạm vi bao quát rộng lớn, không mang nghĩa là dễ hiểu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_antonym', 'en-b2-3', 'antonym', '/ˈæntənɪm/', 'B2', 'từ trái nghĩa', 'n.', 'antonymous (adj.), antonymy (n.)', 'Trái nghĩa: synonym', 'Thường dùng cấu trúc an antonym of; trong khi synonym dùng để chỉ từ đồng nghĩa.', 'Our teacher asked us for an antonym of generous.', NULL, 'Giáo viên yêu cầu chúng tôi nêu một từ trái nghĩa của từ generous.', '{"wordId":"antonym","ukIpa":"/ˈæntənɪm/","usIpa":"/ˈæntənɪm/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"a word whose meaning is opposite to another word''s","vi":"từ trái nghĩa"}],"examples":[{"en":"Our teacher asked us for an antonym of generous.","vi":"Giáo viên yêu cầu chúng tôi nêu một từ trái nghĩa của từ generous.","audioKind":"ex"},{"en":"Learning an antonym alongside each new adjective can help language students understand contrasts and expand their vocabulary.","vi":"Việc học từ trái nghĩa đi kèm với mỗi tính từ mới giúp học viên ngoại ngữ hiểu rõ các mối tương phản và mở rộng vốn từ vựng.","audioKind":"ex2"}],"collocations":[{"en":"an antonym of","vi":"từ trái nghĩa của"},{"en":"a pair of antonyms","vi":"một cặp từ trái nghĩa"}],"wordFamily":["antonymous (adj.)","antonymy (n.)"],"synonyms":[],"antonyms":["synonym"],"tipVi":"Thường dùng cấu trúc an antonym of; trong khi synonym dùng để chỉ từ đồng nghĩa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scope', 'en-b2-3', 'scope', '/skoʊp/', 'B2', 'phạm vi; tầm vực; cơ hội; dư địa phát triển', 'n.', NULL, 'Đồng nghĩa: range, extent', 'Phạm vi của cái gì dùng scope of; cơ hội làm gì dùng scope for.', 'Kitchen repairs fall outside the scope of this job.', NULL, 'Việc sửa chữa nhà bếp nằm ngoài phạm vi công việc này.', '{"wordId":"scope","ukIpa":"/skəʊp/","usIpa":"/skoʊp/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"The range of subjects or activities that something covers.","vi":"phạm vi; tầm vực"},{"pos":"n.","en":"The opportunity or freedom to do or develop something.","vi":"cơ hội; dư địa phát triển"}],"examples":[{"en":"Kitchen repairs fall outside the scope of this job.","vi":"Việc sửa chữa nhà bếp nằm ngoài phạm vi công việc này.","audioKind":"ex"},{"en":"The scope of the study was limited to urban schools, so its findings may not apply to rural communities.","vi":"Phạm vi của nghiên cứu chỉ giới hạn ở các trường học thành thị, vì vậy các phát hiện của nó có thể không áp dụng được cho các cộng đồng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"scope of the study","vi":"phạm vi nghiên cứu"},{"en":"beyond the scope of","vi":"nằm ngoài phạm vi của"},{"en":"scope for improvement","vi":"dư địa để cải thiện"},{"en":"broaden the scope","vi":"mở rộng phạm vi"}],"wordFamily":[],"synonyms":["range","extent"],"antonyms":[],"tipVi":"Phạm vi của cái gì dùng scope of; cơ hội làm gì dùng scope for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bachelor', 'en-b2-3', 'bachelor', '/ˈbætʃələr/', 'B2', 'cử nhân; trai tân; người đàn ông độc thân', 'n.', NULL, NULL, 'Cụm học thuật viết là bachelor''s degree, lưu ý dùng dạng sở hữu cách.', 'My cousin earned a bachelor''s degree in engineering.', NULL, 'Anh họ tôi đã đạt bằng cử nhân ngành kỹ thuật.', '{"wordId":"bachelor","ukIpa":"/ˈbætʃələ/","usIpa":"/ˈbætʃələr/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"Someone awarded a first university degree","vi":"cử nhân"},{"pos":"n.","en":"A man who has never married","vi":"trai tân; người đàn ông độc thân"}],"examples":[{"en":"My cousin earned a bachelor''s degree in engineering.","vi":"Anh họ tôi đã đạt bằng cử nhân ngành kỹ thuật.","audioKind":"ex"},{"en":"A bachelor''s degree can improve employment prospects, although practical experience remains important in many industries.","vi":"Bằng cử nhân có thể cải thiện triển vọng việc làm, mặc dù kinh nghiệm thực tế vẫn rất quan trọng trong nhiều ngành nghề.","audioKind":"ex2"}],"collocations":[{"en":"bachelor''s degree","vi":"bằng cử nhân"},{"en":"Bachelor of Arts","vi":"cử nhân nghệ thuật"},{"en":"Bachelor of Science","vi":"cử nhân khoa học"},{"en":"eligible bachelor","vi":"chàng trai độc thân có điều kiện tốt"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm học thuật viết là bachelor''s degree, lưu ý dùng dạng sở hữu cách.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_note-taking', 'en-b2-3', 'note-taking', '/ˈnoʊt ˌteɪkɪŋ/', 'B2', 'việc ghi chép', 'n.', 'note (n.), note-taker (n.)', NULL, 'Thường không đếm được; động từ diễn tả hành động này là take notes.', 'Note-taking helps me remember what happens during meetings.', NULL, 'Việc ghi chép giúp tôi nhớ lại những gì diễn ra trong các cuộc họp.', '{"wordId":"note-taking","ukIpa":"/ˈnəʊt ˌteɪkɪŋ/","usIpa":"/ˈnoʊt ˌteɪkɪŋ/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"the activity of writing down important information while listening or reading","vi":"việc ghi chép"}],"examples":[{"en":"Note-taking helps me remember what happens during meetings.","vi":"Việc ghi chép giúp tôi nhớ lại những gì diễn ra trong các cuộc họp.","audioKind":"ex"},{"en":"Effective note-taking allows students to identify key arguments and review complex material more efficiently after lectures.","vi":"Việc ghi chép hiệu quả giúp học sinh xác định các luận điểm chính và ôn tập tài liệu phức tạp hiệu quả hơn sau giờ học.","audioKind":"ex2"}],"collocations":[{"en":"note-taking skills","vi":"kỹ năng ghi chép"},{"en":"effective note-taking","vi":"ghi chép hiệu quả"},{"en":"note-taking strategies","vi":"chiến lược ghi chép"}],"wordFamily":["note (n.)","note-taker (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường không đếm được; động từ diễn tả hành động này là take notes.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mid-term', 'en-b2-3', 'mid-term', '/ˌmɪdˈtɝːm/', 'B2', 'giữa học kỳ; giữa nhiệm kỳ; bài thi giữa kỳ', 'adj.', 'term (n.)', NULL, 'Cũng thường được viết là midterm; đóng vai trò là danh từ chỉ kỳ thi giữa kỳ, phổ biến hơn trong tiếng Anh - Mỹ.', 'Our mid-term exams start after the spring holiday.', NULL, 'Các bài thi giữa kỳ của chúng tôi bắt đầu sau kỳ nghỉ xuân.', '{"wordId":"mid-term","ukIpa":"/ˌmɪdˈtɜːm/","usIpa":"/ˌmɪdˈtɝːm/","cefr":"B2","topic":"education","senses":[{"pos":"adj.","en":"Happening halfway through an academic term or period in office.","vi":"giữa học kỳ; giữa nhiệm kỳ"},{"pos":"n.","en":"An examination taken halfway through an academic term.","vi":"bài thi giữa kỳ"}],"examples":[{"en":"Our mid-term exams start after the spring holiday.","vi":"Các bài thi giữa kỳ của chúng tôi bắt đầu sau kỳ nghỉ xuân.","audioKind":"ex"},{"en":"Mid-term assessments can help teachers identify learning difficulties before students take their final examinations.","vi":"Các bài đánh giá giữa kỳ có thể giúp giáo viên xác định khó khăn trong học tập trước khi học sinh bước vào kỳ thi cuối kỳ.","audioKind":"ex2"}],"collocations":[{"en":"mid-term exam","vi":"kỳ thi giữa kỳ"},{"en":"mid-term assessment","vi":"đánh giá giữa kỳ"},{"en":"mid-term elections","vi":"bầu cử giữa nhiệm kỳ"}],"wordFamily":["term (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cũng thường được viết là midterm; đóng vai trò là danh từ chỉ kỳ thi giữa kỳ, phổ biến hơn trong tiếng Anh - Mỹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prefix', 'en-b2-3', 'prefix', '/ˈpriːfɪks/', 'B2', 'tiền tố', 'n.', 'prefixation (n.)', 'Trái nghĩa: suffix', 'prefix đứng ở đầu từ, suffix đứng ở cuối từ; cả hai được gọi chung là affix.', 'Adding the prefix un turns happy into its opposite.', NULL, 'Thêm tiền tố un vào từ happy để tạo thành từ trái nghĩa.', '{"wordId":"prefix","ukIpa":"/ˈpriːfɪks/","usIpa":"/ˈpriːfɪks/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"A word part added at the beginning to change meaning.","vi":"tiền tố"}],"examples":[{"en":"Adding the prefix un turns happy into its opposite.","vi":"Thêm tiền tố un vào từ happy để tạo thành từ trái nghĩa.","audioKind":"ex"},{"en":"Learning common prefixes can help students infer the meanings of unfamiliar words when reading academic texts.","vi":"Học các tiền tố phổ biến có thể giúp học sinh suy luận nghĩa của các từ không quen thuộc khi đọc văn bản học thuật.","audioKind":"ex2"}],"collocations":[{"en":"negative prefix","vi":"tiền tố mang nghĩa phủ định"},{"en":"add a prefix","vi":"thêm tiền tố"},{"en":"common prefixes","vi":"các tiền tố phổ biến"}],"wordFamily":["prefixation (n.)"],"synonyms":[],"antonyms":["suffix"],"tipVi":"prefix đứng ở đầu từ, suffix đứng ở cuối từ; cả hai được gọi chung là affix.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_encyclopaedia', 'en-b2-3', 'encyclopaedia', '/ɪnˌsaɪ.kləˈpiː.di.ə/', 'B2', 'bách khoa toàn thư', 'n.', 'encyclopaedic (adj.)', NULL, 'Cách viết theo Anh-Anh; tiếng Anh-Mỹ thường viết là encyclopedia.', 'We found a dinosaur picture in the encyclopaedia.', NULL, 'Chúng tôi tìm thấy hình ảnh một chú khủng long trong cuốn bách khoa toàn thư.', '{"wordId":"encyclopaedia","ukIpa":"/ɪnˌsaɪ.kləˈpiː.di.ə/","usIpa":"/ɪnˌsaɪ.kləˈpiː.di.ə/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"A reference work containing information about many subjects or one field","vi":"bách khoa toàn thư"}],"examples":[{"en":"We found a dinosaur picture in the encyclopaedia.","vi":"Chúng tôi tìm thấy hình ảnh một chú khủng long trong cuốn bách khoa toàn thư.","audioKind":"ex"},{"en":"An online encyclopaedia provides a useful starting point for research, but students should verify information using reliable sources.","vi":"Bách khoa toàn thư trực tuyến cung cấp điểm khởi đầu hữu ích cho việc nghiên cứu, nhưng học sinh nên xác minh thông tin bằng các nguồn đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"online encyclopaedia","vi":"bách khoa toàn thư trực tuyến"},{"en":"an encyclopaedia entry","vi":"mục từ bách khoa toàn thư"},{"en":"consult an encyclopaedia","vi":"tra cứu bách khoa toàn thư"}],"wordFamily":["encyclopaedic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cách viết theo Anh-Anh; tiếng Anh-Mỹ thường viết là encyclopedia.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_paraphrase', 'en-b2-3', 'paraphrase', '/ˈpærəfreɪz/', 'B2', 'diễn giải bằng từ ngữ khác; nói cách khác; bản diễn giải; lời chú giải', 'v.', 'paraphrasing (n.)', 'Đồng nghĩa: rephrase, restate', 'Diễn giải phải giữ nguyên ý gốc; trong khi summarize lại tập trung vào việc tóm tắt các điểm chính.', 'Could you paraphrase that explanation so I can understand?', NULL, 'Bạn có thể diễn giải lại lời giải thích đó để tôi dễ hiểu hơn được không?', '{"wordId":"paraphrase","ukIpa":"/ˈpærəfreɪz/","usIpa":"/ˈpærəfreɪz/","cefr":"B2","topic":"education","senses":[{"pos":"v.","en":"Express the same meaning using different words.","vi":"diễn giải bằng từ ngữ khác; nói cách khác"},{"pos":"n.","en":"A version expressing the same meaning in different words.","vi":"bản diễn giải; lời chú giải"}],"examples":[{"en":"Could you paraphrase that explanation so I can understand?","vi":"Bạn có thể diễn giải lại lời giải thích đó để tôi dễ hiểu hơn được không?","audioKind":"ex"},{"en":"Students should learn to paraphrase sources accurately while acknowledging the original authors in their academic writing.","vi":"Học sinh nên học cách diễn giải chính xác các tài liệu tham khảo đồng thời ghi công tác giả gốc trong bài viết học thuật của mình.","audioKind":"ex2"}],"collocations":[{"en":"paraphrase a passage","vi":"diễn giải một đoạn văn"},{"en":"accurate paraphrase","vi":"bản diễn giải chính xác"},{"en":"paraphrase in your own words","vi":"diễn giải bằng ngôn từ của chính bạn"}],"wordFamily":["paraphrasing (n.)"],"synonyms":["rephrase","restate"],"antonyms":[],"tipVi":"Diễn giải phải giữ nguyên ý gốc; trong khi summarize lại tập trung vào việc tóm tắt các điểm chính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_equip', 'en-b2-3', 'equip', '/ɪˈkwɪp/', 'B2', 'trang bị; lắp đặt thiết bị; trang bị kiến thức; chuẩn bị kỹ năng', 'v.', 'equipment (n.), equipped (adj.)', 'Đồng nghĩa: outfit, prepare', 'Thường dùng cấu trúc equip A with B; dạng quá khứ equipped gấp đôi chữ p.', 'We equipped our bikes with lights before riding home.', NULL, 'Chúng tôi đã gắn đèn cho xe đạp của mình trước khi đạp xe về nhà.', '{"wordId":"equip","ukIpa":"/ɪˈkwɪp/","usIpa":"/ɪˈkwɪp/","cefr":"B2","topic":"education","senses":[{"pos":"v.","en":"To provide someone or something with necessary tools or equipment","vi":"trang bị; lắp đặt thiết bị"},{"pos":"v.","en":"To give someone the skills or knowledge they need","vi":"trang bị kiến thức; chuẩn bị kỹ năng"}],"examples":[{"en":"We equipped our bikes with lights before riding home.","vi":"Chúng tôi đã gắn đèn cho xe đạp của mình trước khi đạp xe về nhà.","audioKind":"ex"},{"en":"Schools should equip students with practical financial skills so they can manage their money confidently as adults.","vi":"Nhà trường nên trang bị cho học sinh các kỹ năng tài chính thiết thực để các em có thể tự tin quản lý tiền bạc khi trưởng thành.","audioKind":"ex2"}],"collocations":[{"en":"equip something with","vi":"trang bị cho cái gì với cái gì"},{"en":"equip students with skills","vi":"trang bị kỹ năng cho học sinh"},{"en":"fully equipped kitchen","vi":"nhà bếp được trang bị đầy đủ"}],"wordFamily":["equipment (n.)","equipped (adj.)"],"synonyms":["outfit","prepare"],"antonyms":[],"tipVi":"Thường dùng cấu trúc equip A with B; dạng quá khứ equipped gấp đôi chữ p.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_instruct', 'en-b2-3', 'instruct', '/ɪnˈstrʌkt/', 'B2', 'chỉ thị; ra lệnh; hướng dẫn; dạy; hướng dẫn kỹ năng', 'v.', 'instruction (n.), instructor (n.), instructional (adj.), instructive (adj.)', 'Đồng nghĩa: direct, teach', 'instruct sb to do là chỉ thị; instruct sb in là dạy học.', 'The guide instructed us to stay on the path.', NULL, 'Hướng dẫn viên đã chỉ thị chúng tôi không được rời khỏi đường mòn.', '{"wordId":"instruct","ukIpa":"/ɪnˈstrʌkt/","usIpa":"/ɪnˈstrʌkt/","cefr":"B2","topic":"education","senses":[{"pos":"v.","en":"formally tell someone to do something","vi":"chỉ thị; ra lệnh; hướng dẫn"},{"pos":"v.","en":"teach someone a skill or explain how to do something","vi":"dạy; hướng dẫn kỹ năng"}],"examples":[{"en":"The guide instructed us to stay on the path.","vi":"Hướng dẫn viên đã chỉ thị chúng tôi không được rời khỏi đường mòn.","audioKind":"ex"},{"en":"Schools should instruct students in basic first aid so they can respond safely during emergencies.","vi":"Nhà trường nên dạy học sinh các kỹ năng sơ cứu cơ bản để các em có thể ứng phó an toàn trong các tình huống khẩn cấp.","audioKind":"ex2"}],"collocations":[{"en":"instruct someone to do something","vi":"chỉ thị ai đó làm gì"},{"en":"instruct someone in something","vi":"hướng dẫn ai đó về việc gì"},{"en":"instruct staff","vi":"chỉ đạo nhân viên"}],"wordFamily":["instruction (n.)","instructor (n.)","instructional (adj.)","instructive (adj.)"],"synonyms":["direct","teach"],"antonyms":[],"tipVi":"instruct sb to do là chỉ thị; instruct sb in là dạy học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scholarship', 'en-b2-3', 'scholarship', '/ˈskɑːlərʃɪp/', 'B2', 'học bổng; học thuật; sự nghiên cứu chuyên sâu', 'n.', 'scholar (n.), scholarly (adj.)', NULL, 'Chỉ học bổng thì đếm được; chỉ học vấn hay nghiên cứu học thuật thì không đếm được.', 'A scholarship helped Ravi pay for his university course.', NULL, 'Một suất học bổng đã giúp Ravi chi trả cho khóa học đại học của mình.', '{"wordId":"scholarship","ukIpa":"/ˈskɒləʃɪp/","usIpa":"/ˈskɑːlərʃɪp/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"Money awarded to help someone pay for their studies.","vi":"học bổng"},{"pos":"n.","en":"Serious academic study or the knowledge gained through it.","vi":"học thuật; sự nghiên cứu chuyên sâu"}],"examples":[{"en":"A scholarship helped Ravi pay for his university course.","vi":"Một suất học bổng đã giúp Ravi chi trả cho khóa học đại học của mình.","audioKind":"ex"},{"en":"Universities should offer more scholarships to talented applicants from families with limited financial resources.","vi":"Các trường đại học nên cung cấp nhiều học bổng hơn cho các ứng viên có tài năng đến từ các gia đình có hoàn cảnh tài chính hạn hẹp.","audioKind":"ex2"}],"collocations":[{"en":"win a scholarship","vi":"giành học bổng"},{"en":"full scholarship","vi":"học bổng toàn phần"},{"en":"academic scholarship","vi":"nghiên cứu học thuật"}],"wordFamily":["scholar (n.)","scholarly (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ học bổng thì đếm được; chỉ học vấn hay nghiên cứu học thuật thì không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grammatical', 'en-b2-3', 'grammatical', '/ɡrəˈmætɪkəl/', 'B2', 'thuộc về ngữ pháp; đúng ngữ pháp', 'adj.', 'grammar (n.), grammatically (adv.), ungrammatical (adj.)', 'Trái nghĩa: ungrammatical', 'Có thể chỉ "thuộc về ngữ pháp", hoặc chỉ câu "đúng ngữ pháp".', 'Our teacher explained the grammatical rules using simple examples.', NULL, 'Giáo viên của chúng tôi đã giải thích các quy tắc ngữ pháp bằng những ví dụ đơn giản.', '{"wordId":"grammatical","ukIpa":"/ɡrəˈmætɪkəl/","usIpa":"/ɡrəˈmætɪkəl/","cefr":"B2","topic":"education","senses":[{"pos":"adj.","en":"relating to the rules for forming words and sentences","vi":"thuộc về ngữ pháp"},{"pos":"adj.","en":"following the accepted grammar rules of a language","vi":"đúng ngữ pháp"}],"examples":[{"en":"Our teacher explained the grammatical rules using simple examples.","vi":"Giáo viên của chúng tôi đã giải thích các quy tắc ngữ pháp bằng những ví dụ đơn giản.","audioKind":"ex"},{"en":"Although grammatical accuracy matters in language learning, students also need opportunities to develop confidence through conversation.","vi":"Mặc dù sự chính xác về ngữ pháp rất quan trọng trong việc học ngôn ngữ, học sinh cũng cần cơ hội để phát triển sự tự tin thông qua trò chuyện.","audioKind":"ex2"}],"collocations":[{"en":"grammatical accuracy","vi":"tính chính xác về ngữ pháp"},{"en":"grammatical errors","vi":"lỗi ngữ pháp"},{"en":"grammatical structure","vi":"cấu trúc ngữ pháp"}],"wordFamily":["grammar (n.)","grammatically (adv.)","ungrammatical (adj.)"],"synonyms":[],"antonyms":["ungrammatical"],"tipVi":"Có thể chỉ \"thuộc về ngữ pháp\", hoặc chỉ câu \"đúng ngữ pháp\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_compulsory', 'en-b2-3', 'compulsory', '/kəmˈpʌlsəri/', 'B2', 'bắt buộc; cưỡng chế; là môn học bắt buộc', 'adj.', 'compulsorily (adv.), compulsion (n.), compel (v.)', 'Đồng nghĩa: mandatory, obligatory · Trái nghĩa: optional, voluntary', 'compulsory nhấn mạnh quy định bắt buộc phải làm, trái nghĩa với optional (tự chọn).', 'Wearing a helmet is compulsory at this climbing centre.', NULL, 'Đội mũ bảo hiểm là quy định bắt buộc tại trung tâm leo núi này.', '{"wordId":"compulsory","ukIpa":"/kəmˈpʌlsəri/","usIpa":"/kəmˈpʌlsəri/","cefr":"B2","topic":"education","senses":[{"pos":"adj.","en":"required by a law or rule, rather than optional","vi":"bắt buộc; cưỡng chế; là môn học bắt buộc"}],"examples":[{"en":"Wearing a helmet is compulsory at this climbing centre.","vi":"Đội mũ bảo hiểm là quy định bắt buộc tại trung tâm leo núi này.","audioKind":"ex"},{"en":"Compulsory education helps ensure that all children acquire basic skills regardless of their family income.","vi":"Giáo dục bắt buộc giúp đảm bảo rằng tất cả trẻ em đều có được các kỹ năng cơ bản bất kể thu nhập gia đình của các em.","audioKind":"ex2"}],"collocations":[{"en":"compulsory education","vi":"giáo dục bắt buộc"},{"en":"compulsory subject","vi":"môn học bắt buộc"},{"en":"compulsory attendance","vi":"sự điểm danh bắt buộc"}],"wordFamily":["compulsorily (adv.)","compulsion (n.)","compel (v.)"],"synonyms":["mandatory","obligatory"],"antonyms":["optional","voluntary"],"tipVi":"compulsory nhấn mạnh quy định bắt buộc phải làm, trái nghĩa với optional (tự chọn).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_challenging', 'en-b2-3', 'challenging', '/ˈtʃælɪndʒɪŋ/', 'B2', 'đầy thử thách; có tính thách thức; khó khăn; khiêu khích; mang tính chất thách thức', 'adj.', 'challenge (n.), challenge (v.), challenger (n.)', 'Đồng nghĩa: demanding, difficult · Trái nghĩa: easy, undemanding', 'Dùng challenging để chỉ nhiệm vụ có độ khó, không dùng challenged.', 'This challenging puzzle kept us busy all afternoon.', NULL, 'Trò chơi ô chữ đầy thử thách này khiến chúng tôi bận rộn suốt cả buổi chiều.', '{"wordId":"challenging","ukIpa":"/ˈtʃælɪndʒɪŋ/","usIpa":"/ˈtʃælɪndʒɪŋ/","cefr":"B2","topic":"education","senses":[{"pos":"adj.","en":"Difficult in a way that tests skills or determination.","vi":"đầy thử thách; có tính thách thức; khó khăn"},{"pos":"adj.","en":"Expressing doubt or inviting disagreement or competition.","vi":"khiêu khích; mang tính chất thách thức"}],"examples":[{"en":"This challenging puzzle kept us busy all afternoon.","vi":"Trò chơi ô chữ đầy thử thách này khiến chúng tôi bận rộn suốt cả buổi chiều.","audioKind":"ex"},{"en":"Providing affordable healthcare in remote communities remains challenging because trained medical staff and essential equipment are often scarce.","vi":"Việc cung cấp dịch vụ chăm sóc y tế giá cả phải chăng ở các vùng sâu vùng xa vẫn rất khó khăn do thiếu hụt nhân viên y tế được đào tạo và trang thiết bị thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"challenging task","vi":"nhiệm vụ đầy thử thách"},{"en":"challenging environment","vi":"môi trường đầy thử thách"},{"en":"intellectually challenging","vi":"thách thức trí tuệ"}],"wordFamily":["challenge (n.)","challenge (v.)","challenger (n.)"],"synonyms":["demanding","difficult"],"antonyms":["easy","undemanding"],"tipVi":"Dùng challenging để chỉ nhiệm vụ có độ khó, không dùng challenged.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_furthermore', 'en-b2-3', 'furthermore', '/ˌfɝːðɚˈmɔːr/', 'B2', 'hơn nữa; ngoài ra', 'adv.', NULL, 'Đồng nghĩa: moreover, additionally', 'Phó từ bổ sung ý nghĩa trang trọng; khi nối các câu hoàn chỉnh, đằng trước dùng dấu chấm hoặc dấu chấm phẩy.', 'The flat is spacious; furthermore, it has a balcony.', NULL, 'Căn hộ rất rộng rãi, hơn nữa lại có một cái ban công.', '{"wordId":"furthermore","ukIpa":"/ˌfɜːðəˈmɔː/","usIpa":"/ˌfɝːðɚˈmɔːr/","cefr":"B2","topic":"education","senses":[{"pos":"adv.","en":"In addition, introducing another point supporting what was said","vi":"hơn nữa; ngoài ra"}],"examples":[{"en":"The flat is spacious; furthermore, it has a balcony.","vi":"Căn hộ rất rộng rãi, hơn nữa lại có một cái ban công.","audioKind":"ex"},{"en":"Public transport reduces traffic congestion; furthermore, it can make cities more accessible to residents without cars.","vi":"Giao thông công cộng giúp giảm tình trạng ùn tắc; hơn nữa, nó còn giúp người dân không có ô tô di chuyển trong thành phố thuận tiện hơn.","audioKind":"ex2"}],"collocations":[{"en":"furthermore, it is important","vi":"hơn nữa, điều quan trọng là"},{"en":"furthermore, evidence suggests","vi":"ngoài ra, các bằng chứng cho thấy"}],"wordFamily":[],"synonyms":["moreover","additionally"],"antonyms":[],"tipVi":"Phó từ bổ sung ý nghĩa trang trọng; khi nối các câu hoàn chỉnh, đằng trước dùng dấu chấm hoặc dấu chấm phẩy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_academy', 'en-b2-3', 'academy', '/əˈkædəmi/', 'B2', 'học viện; trường chuyên đào tạo một môn hoặc kỹ năng cụ thể; viện hàn lâm; hội khoa học hoặc nghệ thuật', 'n.', 'academic (adj.), academically (adv.), academician (n.)', NULL, 'Thường chỉ cơ sở đào tạo chuyên môn hoặc tổ chức học thuật, không nhất thiết là đại học.', 'She attends a dance academy near the station.', NULL, 'Cô ấy theo học tại một học viện khiêu vũ gần nhà ga.', '{"wordId":"academy","ukIpa":"/əˈkædəmi/","usIpa":"/əˈkædəmi/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"A school providing training in a particular subject or skill.","vi":"học viện; trường chuyên đào tạo một môn hoặc kỹ năng cụ thể"},{"pos":"n.","en":"An organization promoting scholarship, science, or the arts.","vi":"viện hàn lâm; hội khoa học hoặc nghệ thuật"}],"examples":[{"en":"She attends a dance academy near the station.","vi":"Cô ấy theo học tại một học viện khiêu vũ gần nhà ga.","audioKind":"ex"},{"en":"A well-funded arts academy can provide talented young people with training they could not otherwise afford.","vi":"Một học viện nghệ thuật được tài trợ tốt có thể cung cấp cho những người trẻ tài năng sự đào tạo mà họ không đủ khả năng chi trả nếu không có sự hỗ trợ đó.","audioKind":"ex2"}],"collocations":[{"en":"a music academy","vi":"học viện âm nhạc"},{"en":"a military academy","vi":"trường quân sự"},{"en":"an academy of sciences","vi":"viện hàn lâm khoa học"}],"wordFamily":["academic (adj.)","academically (adv.)","academician (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ cơ sở đào tạo chuyên môn hoặc tổ chức học thuật, không nhất thiết là đại học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_distraction', 'en-b2-3', 'distraction', '/dɪˈstrækʃən/', 'B2', 'sự xao nhãng; điều làm phân tâm; tình trạng mất tập trung; hoạt động giải trí; tiêu khiển', 'n.', 'distract (v.), distracted (adj.), distracting (adj.)', 'Đồng nghĩa: diversion', 'Vật gây phân tâm cụ thể thì đếm được; chỉ trạng thái phân tâm thường không đếm được.', 'The television is a distraction when I do homework.', NULL, 'Ti vi là thứ làm tôi xao nhãng khi làm bài tập về nhà.', '{"wordId":"distraction","ukIpa":"/dɪˈstrækʃən/","usIpa":"/dɪˈstrækʃən/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"Something that takes your attention away from your main activity","vi":"sự xao nhãng; điều làm phân tâm"},{"pos":"n.","en":"The state of being unable to give something full attention","vi":"tình trạng mất tập trung"},{"pos":"n.","en":"An activity that helps you forget worries or boredom","vi":"hoạt động giải trí; tiêu khiển"}],"examples":[{"en":"The television is a distraction when I do homework.","vi":"Ti vi là thứ làm tôi xao nhãng khi làm bài tập về nhà.","audioKind":"ex"},{"en":"Reducing digital distractions in classrooms may help students concentrate and engage more deeply with challenging material.","vi":"Việc giảm bớt các thiết bị kỹ thuật số gây xao nhãng trong lớp học có thể giúp học sinh tập trung và tiếp thu sâu hơn với tài liệu khó.","audioKind":"ex2"}],"collocations":[{"en":"avoid distractions","vi":"tránh những điều xao nhãng"},{"en":"a welcome distraction","vi":"một trò tiêu khiển đáng mừng"},{"en":"a major distraction","vi":"sự xao nhãng lớn"}],"wordFamily":["distract (v.)","distracted (adj.)","distracting (adj.)"],"synonyms":["diversion"],"antonyms":[],"tipVi":"Vật gây phân tâm cụ thể thì đếm được; chỉ trạng thái phân tâm thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_equivalent', 'en-b2-3', 'equivalent', '/ɪˈkwɪvələnt/', 'B2', 'tương đương, ngang bằng (về giá trị, số lượng, ý nghĩa hoặc chức năng); vật tương đương, bản tương đương', 'adj.', 'equivalence (n.), equivalently (adv.)', 'Đồng nghĩa: equal, comparable · Trái nghĩa: unequal', 'Thường dùng cấu trúc "equivalent to"; cần lưu ý là "tương đương" không có nghĩa là "hoàn toàn giống hệt".', 'This small heater produces heat equivalent to that larger one.', NULL, 'Chiếc máy sưởi nhỏ này tạo ra lượng nhiệt tương đương với chiếc máy lớn kia.', '{"wordId":"equivalent","ukIpa":"/ɪˈkwɪvələnt/","usIpa":"/ɪˈkwɪvələnt/","cefr":"B2","topic":"education","senses":[{"pos":"adj.","en":"Equal in value, amount, meaning, or function.","vi":"tương đương, ngang bằng (về giá trị, số lượng, ý nghĩa hoặc chức năng)"},{"pos":"n.","en":"Something equal to another thing in value, meaning, or function.","vi":"vật tương đương, bản tương đương"}],"examples":[{"en":"This small heater produces heat equivalent to that larger one.","vi":"Chiếc máy sưởi nhỏ này tạo ra lượng nhiệt tương đương với chiếc máy lớn kia.","audioKind":"ex"},{"en":"Employers should recognise overseas qualifications when they are equivalent to those awarded by domestic institutions.","vi":"Các nhà tuyển dụng nên công nhận bằng cấp nước ngoài khi chúng tương đương với bằng cấp do các cơ sở trong nước cấp.","audioKind":"ex2"}],"collocations":[{"en":"equivalent to","vi":"tương đương với"},{"en":"an equivalent qualification","vi":"bằng cấp tương đương"},{"en":"the equivalent of","vi":"thứ tương đương với"}],"wordFamily":["equivalence (n.)","equivalently (adv.)"],"synonyms":["equal","comparable"],"antonyms":["unequal"],"tipVi":"Thường dùng cấu trúc \"equivalent to\"; cần lưu ý là \"tương đương\" không có nghĩa là \"hoàn toàn giống hệt\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_attentively', 'en-b2-3', 'attentively', '/əˈtentɪvli/', 'B2', 'chăm chú; chăm chỉ; lắng nghe chăm chú; ân cần; chu đáo', 'adv.', 'attention (n.), attentive (adj.), inattentive (adj.), attentiveness (n.)', 'Đồng nghĩa: carefully · Trái nghĩa: inattentively', 'Thường gặp nhất trong cụm listen attentively, tập trung vào sự tập trung tinh thần thay vì lòng quan tâm.', 'The children listened attentively as their grandmother told a story.', NULL, 'Lũ trẻ lắng nghe rất chăm chú khi người bà kể chuyện.', '{"wordId":"attentively","ukIpa":"/əˈtentɪvli/","usIpa":"/əˈtentɪvli/","cefr":"B2","topic":"education","senses":[{"pos":"adv.","en":"with careful attention to what is happening","vi":"chăm chú; chăm chỉ; lắng nghe chăm chú"},{"pos":"adv.","en":"with care for another person''s needs","vi":"ân cần; chu đáo"}],"examples":[{"en":"The children listened attentively as their grandmother told a story.","vi":"Lũ trẻ lắng nghe rất chăm chú khi người bà kể chuyện.","audioKind":"ex"},{"en":"Students who listen attentively during group discussions are more likely to understand perspectives different from their own.","vi":"Những học sinh lắng nghe một cách chăm chú trong các buổi thảo luận nhóm có nhiều khả năng thấu hiểu những góc nhìn khác biệt với quan điểm của bản thân.","audioKind":"ex2"}],"collocations":[{"en":"listen attentively","vi":"lắng nghe chăm chú"},{"en":"watch attentively","vi":"quan sát kỹ lưỡng"},{"en":"care attentively for","vi":"chăm sóc chu đáo"}],"wordFamily":["attention (n.)","attentive (adj.)","inattentive (adj.)","attentiveness (n.)"],"synonyms":["carefully"],"antonyms":["inattentively"],"tipVi":"Thường gặp nhất trong cụm listen attentively, tập trung vào sự tập trung tinh thần thay vì lòng quan tâm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_3_1', 'en-b2-3', 'Cách dùng “undergraduate” (n.) — sinh viên đại học chưa tốt nghiệp; sinh viên bậc cử nhân', 'undergraduate student  ·  undergraduate degree  ·  undergraduate course', 'Chỉ sinh viên đang theo học tấm bằng đại học đầu tiên, không đồng nghĩa với sinh viên bỏ học hay sinh viên dự bị.', 'Họ từ (Word Family): graduate (n.), postgraduate (n.), graduation (n.)', '[{"hanzi":"My sister is an undergraduate studying chemistry nearby.","pinyin":"","meaning":"Chị gái tôi là sinh viên năm nhất đại học đang học ngành hóa học ở gần đây."},{"hanzi":"Many undergraduate courses now include practical placements to help students prepare for their future careers.","pinyin":"","meaning":"Nhiều chương trình đào tạo bậc cử nhân hiện nay bao gồm các đợt thực tập thực tế để giúp sinh viên chuẩn bị cho sự nghiệp tương lai."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_3_2', 'en-b2-3', 'Cách dùng “mid-term” (adj.) — giữa học kỳ; giữa nhiệm kỳ', 'mid-term exam  ·  mid-term assessment  ·  mid-term elections', 'Cũng thường được viết là midterm; đóng vai trò là danh từ chỉ kỳ thi giữa kỳ, phổ biến hơn trong tiếng Anh - Mỹ.', 'Họ từ (Word Family): term (n.)', '[{"hanzi":"Our mid-term exams start after the spring holiday.","pinyin":"","meaning":"Các bài thi giữa kỳ của chúng tôi bắt đầu sau kỳ nghỉ xuân."},{"hanzi":"Mid-term assessments can help teachers identify learning difficulties before students take their final examinations.","pinyin":"","meaning":"Các bài đánh giá giữa kỳ có thể giúp giáo viên xác định khó khăn trong học tập trước khi học sinh bước vào kỳ thi cuối kỳ."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_3_3', 'en-b2-3', 'Cách dùng “furthermore” (adv.) — hơn nữa; ngoài ra', 'furthermore, it is important  ·  furthermore, evidence suggests', 'Phó từ bổ sung ý nghĩa trang trọng; khi nối các câu hoàn chỉnh, đằng trước dùng dấu chấm hoặc dấu chấm phẩy.', 'Đồng nghĩa: moreover, additionally', '[{"hanzi":"The flat is spacious; furthermore, it has a balcony.","pinyin":"","meaning":"Căn hộ rất rộng rãi, hơn nữa lại có một cái ban công."},{"hanzi":"Public transport reduces traffic congestion; furthermore, it can make cities more accessible to residents without cars.","pinyin":"","meaning":"Giao thông công cộng giúp giảm tình trạng ùn tắc; hơn nữa, nó còn giúp người dân không có ô tô di chuyển trong thành phố thuận tiện hơn."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_3_4', 'en-b2-3', 'Cách dùng “verbal” (adj.) — bằng lời nói; dạng nói (thay vì dạng viết)', 'a verbal agreement  ·  verbal communication  ·  verbal skills', 'verbal cũng dùng để chỉ việc diễn đạt bằng từ ngữ, không phải lúc nào cũng đối lập hoàn toàn với written.', 'Họ từ (Word Family): verbally (adv.), verbalise (v.), non-verbal (adj.) | Đồng nghĩa: oral, spoken · Trái nghĩa: non-verbal', '[{"hanzi":"We made a verbal agreement to share the garden.","pinyin":"","meaning":"Chúng tôi đã đạt được thỏa thuận miệng về việc dùng chung khu vườn."},{"hanzi":"Employers should confirm verbal agreements in writing to prevent misunderstandings about working hours and responsibilities.","pinyin":"","meaning":"Người sử dụng lao động nên xác nhận các thỏa thuận miệng bằng văn bản để tránh những hiểu lầm về thời gian làm việc và trách nhiệm."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_3_1', 'en-b2-3', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_3_1_1', 'ten_b2_3_1', 'enrol', 'I plan to enrol on a cooking course next month.', 'I plan to enrol on a cooking course next month.', '/ɪnˈroʊl/', 'Tôi dự định đăng ký một khóa học nấu ăn vào tháng tới.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_3_1_2', 'ten_b2_3_1', 'undergraduate', 'My sister is an undergraduate studying chemistry nearby.', 'My sister is an undergraduate studying chemistry nearby.', '/ˌʌndərˈɡrædʒuət/', 'Chị gái tôi là sinh viên năm nhất đại học đang học ngành hóa học ở gần đây.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_3_1_3', 'ten_b2_3_1', 'knowledgeable', 'Our knowledgeable guide explained how each garden plant grows.', 'Our knowledgeable guide explained how each garden plant grows.', '/ˈnɑːlɪdʒəbəl/', 'Hướng dẫn viên am hiểu của chúng tôi đã giải thích cách từng loại cây trong vườn phát triển.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_3_1_4', 'ten_b2_3_1', 'detailed', 'She gave me detailed instructions for baking the cake.', 'She gave me detailed instructions for baking the cake.', '/dɪˈteɪld/', 'Cô ấy đưa cho tôi hướng dẫn chi tiết để làm bánh ngọt.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_3_1_5', 'ten_b2_3_1', 'qualify', 'Our team needs another win to qualify for the final.', 'Our team needs another win to qualify for the final.', '/ˈkwɑːlɪfaɪ/', 'Đội của chúng tôi cần chiến thắng thêm một trận nữa để lọt vào vòng chung kết.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_3_1_6', 'ten_b2_3_1', 'adequately', 'This small heater adequately warms our entire bedroom.', 'This small heater adequately warms our entire bedroom.', '/ˈædɪkwətli/', 'Chiếc lò sưởi nhỏ này sưởi ấm đủ cho toàn bộ phòng ngủ của chúng tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_3_1_7', 'ten_b2_3_1', 'verbal', 'We made a verbal agreement to share the garden.', 'We made a verbal agreement to share the garden.', '/ˈvɝːbəl/', 'Chúng tôi đã đạt được thỏa thuận miệng về việc dùng chung khu vườn.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_3_1_8', 'ten_b2_3_1', 'comprehensive', 'This comprehensive guide covers every trail in the park.', 'This comprehensive guide covers every trail in the park.', '/ˌkɑːmprɪˈhensɪv/', 'Cẩm nang chi tiết này bao trùm mọi tuyến đường mòn trong công viên.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_3_1_1', 'en-b2-3', 'ten_b2_3_1', 'listening', 'listening', 'I plan to enrol on a cooking course next month.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Giáo viên yêu cầu chúng tôi nêu một từ trái nghĩa của từ generous.","Việc sửa chữa nhà bếp nằm ngoài phạm vi công việc này.","Cẩm nang chi tiết này bao trùm mọi tuyến đường mòn trong công viên.","Tôi dự định đăng ký một khóa học nấu ăn vào tháng tới."]'::jsonb, 3, 'I plan to enrol on a cooking course next month. → Tôi dự định đăng ký một khóa học nấu ăn vào tháng tới.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_3_1_2', 'en-b2-3', 'ten_b2_3_1', 'listening', 'listening', 'My sister is an undergraduate studying chemistry nearby.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một suất học bổng đã giúp Ravi chi trả cho khóa học đại học của mình.","Chị gái tôi là sinh viên năm nhất đại học đang học ngành hóa học ở gần đây.","Trò chơi ô chữ đầy thử thách này khiến chúng tôi bận rộn suốt cả buổi chiều.","Cô ấy đưa cho tôi hướng dẫn chi tiết để làm bánh ngọt."]'::jsonb, 1, 'My sister is an undergraduate studying chemistry nearby. → Chị gái tôi là sinh viên năm nhất đại học đang học ngành hóa học ở gần đây.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_3_1_3', 'en-b2-3', 'ten_b2_3_1', 'listening', 'listening', 'Our knowledgeable guide explained how each garden plant grows.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Ti vi là thứ làm tôi xao nhãng khi làm bài tập về nhà.","Hướng dẫn viên am hiểu của chúng tôi đã giải thích cách từng loại cây trong vườn phát triển.","Cô ấy đưa cho tôi hướng dẫn chi tiết để làm bánh ngọt.","Chiếc lò sưởi nhỏ này sưởi ấm đủ cho toàn bộ phòng ngủ của chúng tôi."]'::jsonb, 1, 'Our knowledgeable guide explained how each garden plant grows. → Hướng dẫn viên am hiểu của chúng tôi đã giải thích cách từng loại cây trong vườn phát triển.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_3_2', 'en-b2-3', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_3_2_1', 'ten_b2_3_2', 'enrol', 'Governments can encourage adults to enrol in vocational training by offering flexible schedules and financial support.', 'Governments can encourage adults to enrol in vocational training by offering flexible schedules and financial support.', '/ɪnˈroʊl/', 'Chính phủ có thể khuyến khích người lớn tham gia đào tạo nghề bằng cách cung cấp lịch học linh hoạt và hỗ trợ tài chính.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_3_2_2', 'ten_b2_3_2', 'undergraduate', 'Many undergraduate courses now include practical placements to help students prepare for their future careers.', 'Many undergraduate courses now include practical placements to help students prepare for their future careers.', '/ˌʌndərˈɡrædʒuət/', 'Nhiều chương trình đào tạo bậc cử nhân hiện nay bao gồm các đợt thực tập thực tế để giúp sinh viên chuẩn bị cho sự nghiệp tương lai.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_3_2_3', 'ten_b2_3_2', 'knowledgeable', 'Knowledgeable teachers can help students evaluate online information rather than accept every claim they encounter.', 'Knowledgeable teachers can help students evaluate online information rather than accept every claim they encounter.', '/ˈnɑːlɪdʒəbəl/', 'Những giáo viên am hiểu có thể giúp học sinh đánh giá thông tin trên mạng thay vì tiếp nhận mọi tuyên bố mà các em bắt gặp.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_3_2_4', 'ten_b2_3_2', 'detailed', 'Detailed research into commuting patterns can help cities design more efficient public transport systems.', 'Detailed research into commuting patterns can help cities design more efficient public transport systems.', '/dɪˈteɪld/', 'Nghiên cứu chi tiết về các mô hình đi lại có thể giúp các thành phố thiết kế hệ thống giao thông công cộng hiệu quả hơn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_3_2_5', 'ten_b2_3_2', 'qualify', 'Students from low-income households may qualify for financial support that covers tuition fees and essential living costs.', 'Students from low-income households may qualify for financial support that covers tuition fees and essential living costs.', '/ˈkwɑːlɪfaɪ/', 'Học sinh từ các hộ gia đình thu nhập thấp có thể đủ điều kiện nhận hỗ trợ tài chính để chi trả học phí và các chi phí sinh hoạt thiết yếu.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_3_2_6', 'ten_b2_3_2', 'adequately', 'Schools must be adequately funded to provide all children with equal opportunities to learn.', 'Schools must be adequately funded to provide all children with equal opportunities to learn.', '/ˈædɪkwətli/', 'Các trường học cần được cấp kinh phí đầy đủ để cung cấp cho mọi trẻ em cơ hội học tập bình đẳng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_3_2_1', 'en-b2-3', 'ten_b2_3_2', 'listening', 'listening', 'Governments can encourage adults to enrol in vocational training by offering flexible schedules and financial support.', NULL, 'Trong câu vừa nghe, từ “enrol” mang nghĩa nào sau đây?', '["bổ nhiệm; chỉ định","kiện; khởi kiện","cuộc tranh cãi; sự bất đồng công khai","ghi danh; đăng ký; tuyển sinh"]'::jsonb, 3, '“enrol” (/ɪnˈroʊl/): ghi danh; đăng ký; tuyển sinh. Câu đầy đủ: Governments can encourage adults to enrol in vocational training by offering flexible schedules and financial support.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_3_2_2', 'en-b2-3', 'ten_b2_3_2', 'listening', 'listening', 'Many undergraduate courses now include practical placements to help students prepare for their future careers.', NULL, 'Trong câu vừa nghe, từ “undergraduate” mang nghĩa nào sau đây?', '["sinh viên đại học chưa tốt nghiệp; sinh viên bậc cử nhân","am hiểu; uyên bác; có kiến thức sâu rộng","phong cách nấu nướng; ẩm thực; nền văn hóa ẩm thực","bị phóng đại; nói quá; cường điệu"]'::jsonb, 0, '“undergraduate” (/ˌʌndərˈɡrædʒuət/): sinh viên đại học chưa tốt nghiệp; sinh viên bậc cử nhân. Câu đầy đủ: Many undergraduate courses now include practical placements to help students prepare for their future careers.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
