INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_3_2', 'en-b2-3', NULL, 'comprehensive_test', 'listening', 'My sister is an undergraduate studying chemistry nearby.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Giáo viên của chúng tôi đã giải thích các quy tắc ngữ pháp bằng những ví dụ đơn giản.","Chị gái tôi là sinh viên năm nhất đại học đang học ngành hóa học ở gần đây.","Cô ấy theo học tại một học viện khiêu vũ gần nhà ga.","Việc sửa chữa nhà bếp nằm ngoài phạm vi công việc này."]'::jsonb, 1, 'My sister is an undergraduate studying chemistry nearby. → Chị gái tôi là sinh viên năm nhất đại học đang học ngành hóa học ở gần đây.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_3_3', 'en-b2-3', NULL, 'comprehensive_test', 'listening', 'knowledgeable', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cần gạt; đòn bẩy","am hiểu; uyên bác; có kiến thức sâu rộng","người chăn cừu","bổ ích; đáng làm; mang lại sự thỏa mãn"]'::jsonb, 1, 'knowledgeable (/ˈnɑːlɪdʒəbəl/) → am hiểu; uyên bác; có kiến thức sâu rộng', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_3_4', 'en-b2-3', NULL, 'comprehensive_test', 'listening', 'She gave me detailed instructions for baking the cake.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy đưa cho tôi hướng dẫn chi tiết để làm bánh ngọt.","Cô ấy theo học tại một học viện khiêu vũ gần nhà ga.","Bạn có thể diễn giải lại lời giải thích đó để tôi dễ hiểu hơn được không?","Ti vi là thứ làm tôi xao nhãng khi làm bài tập về nhà."]'::jsonb, 0, 'She gave me detailed instructions for baking the cake. → Cô ấy đưa cho tôi hướng dẫn chi tiết để làm bánh ngọt.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_3_5', 'en-b2-3', NULL, 'comprehensive_test', 'listening', 'qualify', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đạt điều kiện; đủ tiêu chuẩn","trừu tượng","ra hoa; nở hoa","nghiêm khắc; cay nghiệt"]'::jsonb, 0, 'qualify (/ˈkwɑːlɪfaɪ/) → đạt điều kiện; đủ tiêu chuẩn; đạt văn bằng chuyên môn; đủ năng lực hành nghề; làm cho rõ nghĩa hơn; hạn chế', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_3_6', 'en-b2-3', NULL, 'comprehensive_test', 'listening', 'This small heater adequately warms our entire bedroom.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã đạt được thỏa thuận miệng về việc dùng chung khu vườn.","Đội mũ bảo hiểm là quy định bắt buộc tại trung tâm leo núi này.","Chiếc lò sưởi nhỏ này sưởi ấm đủ cho toàn bộ phòng ngủ của chúng tôi.","Chúng tôi đã gắn đèn cho xe đạp của mình trước khi đạp xe về nhà."]'::jsonb, 2, 'This small heater adequately warms our entire bedroom. → Chiếc lò sưởi nhỏ này sưởi ấm đủ cho toàn bộ phòng ngủ của chúng tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_3_7', 'en-b2-3', NULL, 'comprehensive_test', 'listening', 'verbal', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["giới tính (mang tính xã hội và văn hóa)","tháo ra; tách rời","có lẽ; có thể là; theo như dự đoán","bằng lời nói; dạng nói (thay vì dạng viết)"]'::jsonb, 3, 'verbal (/ˈvɝːbəl/) → bằng lời nói; dạng nói (thay vì dạng viết); thuộc về từ ngữ; liên quan đến ngôn từ', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_3_8', 'en-b2-3', NULL, 'comprehensive_test', 'listening', 'This comprehensive guide covers every trail in the park.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Trò chơi ô chữ đầy thử thách này khiến chúng tôi bận rộn suốt cả buổi chiều.","Anh họ tôi đã đạt bằng cử nhân ngành kỹ thuật.","Cẩm nang chi tiết này bao trùm mọi tuyến đường mòn trong công viên.","Chiếc máy sưởi nhỏ này tạo ra lượng nhiệt tương đương với chiếc máy lớn kia."]'::jsonb, 2, 'This comprehensive guide covers every trail in the park. → Cẩm nang chi tiết này bao trùm mọi tuyến đường mòn trong công viên.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_3_9', 'en-b2-3', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To meet requirements, or make someone suitable for something.”?', '["grammatical","qualify","compulsory","academy"]'::jsonb, 1, 'qualify (/ˈkwɑːlɪfaɪ/) → đạt điều kiện; đủ tiêu chuẩn', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
