INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_3_18', 'en-b2-3', NULL, 'comprehensive_test', 'reading', NULL, 'Governments can encourage adults to enrol in vocational training by offering flexible schedules and financial support.', 'Dựa vào câu trên, từ “enrol” có nghĩa phù hợp nhất là gì?', '["sự ấm áp; độ ấm","ghi danh; đăng ký; tuyển sinh","chích; đốt","đồ cổ; cổ vật"]'::jsonb, 1, 'enrol: ghi danh; đăng ký; tuyển sinh. Dịch cả câu: Chính phủ có thể khuyến khích người lớn tham gia đào tạo nghề bằng cách cung cấp lịch học linh hoạt và hỗ trợ tài chính.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_3_19', 'en-b2-3', NULL, 'comprehensive_test', 'reading', NULL, 'Many undergraduate courses now include practical placements to help students prepare for their future careers.', 'Dựa vào câu trên, từ “undergraduate” có nghĩa phù hợp nhất là gì?', '["đỉnh núi; chỏm núi","sai lầm; hiểu lầm","nổi bật; gây ấn tượng mạnh; rõ rệt","sinh viên đại học chưa tốt nghiệp; sinh viên bậc cử nhân"]'::jsonb, 3, 'undergraduate: sinh viên đại học chưa tốt nghiệp; sinh viên bậc cử nhân; thuộc về bậc đại học; dành cho sinh viên bậc cử nhân. Dịch cả câu: Nhiều chương trình đào tạo bậc cử nhân hiện nay bao gồm các đợt thực tập thực tế để giúp sinh viên chuẩn bị cho sự nghiệp tương lai.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_3_20', 'en-b2-3', NULL, 'comprehensive_test', 'reading', NULL, 'Knowledgeable teachers can help students evaluate online information rather than accept every claim they encounter.', 'Dựa vào câu trên, từ “knowledgeable” có nghĩa phù hợp nhất là gì?', '["giải trí; mang tính thư giãn","quận; hạt; tỉnh (đơn vị hành chính)","con bọ; bọ cánh cứng","am hiểu; uyên bác; có kiến thức sâu rộng"]'::jsonb, 3, 'knowledgeable: am hiểu; uyên bác; có kiến thức sâu rộng. Dịch cả câu: Những giáo viên am hiểu có thể giúp học sinh đánh giá thông tin trên mạng thay vì tiếp nhận mọi tuyên bố mà các em bắt gặp.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_3_21', 'en-b2-3', NULL, 'comprehensive_test', 'reading', NULL, 'Detailed research into commuting patterns can help cities design more efficient public transport systems.', 'Dựa vào câu trên, từ “detailed” có nghĩa phù hợp nhất là gì?', '["chi tiết; tỉ mỉ; tường tận","chùm sáng; tia sáng","cú đột quỵ (não)","xướng ngôn viên; phát thanh viên; người phát thanh"]'::jsonb, 0, 'detailed: chi tiết; tỉ mỉ; tường tận. Dịch cả câu: Nghiên cứu chi tiết về các mô hình đi lại có thể giúp các thành phố thiết kế hệ thống giao thông công cộng hiệu quả hơn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_3_22', 'en-b2-3', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự xao nhãng; điều làm phân tâm”', '["armour","distraction","brainstorm","edition"]'::jsonb, 1, 'sự xao nhãng; điều làm phân tâm → distraction (/dɪˈstrækʃən/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_3_23', 'en-b2-3', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tương đương, ngang bằng (về giá trị, số lượng, ý nghĩa hoặc chức năng)”', '["lantern","equivalent","tangle","delicate"]'::jsonb, 1, 'tương đương, ngang bằng (về giá trị, số lượng, ý nghĩa hoặc chức năng) → equivalent (/ɪˈkwɪvələnt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_3_24', 'en-b2-3', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “chăm chú; chăm chỉ; lắng nghe chăm chú”', '["attentively","pedestrian","swollen","honor"]'::jsonb, 0, 'chăm chú; chăm chỉ; lắng nghe chăm chú → attentively (/əˈtentɪvli/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-4', 'en', 'Bài 4: Giáo dục & Trường học (4) - CEFR B2', 'CEFR B2', 'B2 · Giáo dục', '27 từ vựng Tiếng Anh CEFR B2 chủ đề giáo dục & trường học kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4004, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recite', 'en-b2-4', 'recite', '/rɪˈsaɪt/', 'B2', 'đọc thuộc lòng; ngâm thơ; kể lể; liệt kê (chi tiết)', 'v.', 'recitation (n.)', NULL, 'recite nhấn mạnh việc phát âm đọc to; memorise nhấn mạnh việc ghi nhớ.', 'My sister recited a short poem after dinner.', NULL, 'Em gái tôi đọc một bài thơ ngắn sau bữa tối.', '{"wordId":"recite","ukIpa":"/rɪˈsaɪt/","usIpa":"/rɪˈsaɪt/","cefr":"B2","topic":"education","senses":[{"pos":"v.","en":"Say a poem or passage aloud, often from memory","vi":"đọc thuộc lòng; ngâm thơ"},{"pos":"v.","en":"Say a series of facts or details aloud","vi":"kể lể; liệt kê (chi tiết)"}],"examples":[{"en":"My sister recited a short poem after dinner.","vi":"Em gái tôi đọc một bài thơ ngắn sau bữa tối.","audioKind":"ex"},{"en":"Students who merely recite facts may struggle to apply their knowledge to unfamiliar problems.","vi":"Những học sinh chỉ biết học vẹt các sự kiện có thể gặp khó khăn trong việc vận dụng kiến thức vào các vấn đề xa lạ.","audioKind":"ex2"}],"collocations":[{"en":"recite a poem","vi":"đọc thuộc lòng một bài thơ"},{"en":"recite from memory","vi":"học thuộc lòng từ trí nhớ"},{"en":"recite a list","vi":"đọc một loạt danh sách"}],"wordFamily":["recitation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"recite nhấn mạnh việc phát âm đọc to; memorise nhấn mạnh việc ghi nhớ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_coursework', 'en-b2-4', 'coursework', '/ˈkɔːrswɝːk/', 'B2', 'bài tập khóa học; đồ án học phần', 'n.', 'course (n.)', NULL, 'Không đếm được, không nói a coursework; một phần bài tập dùng a piece of.', 'I finished my coursework before meeting friends for lunch.', NULL, 'Tôi đã hoàn thành bài tập khóa học trước khi đi ăn trưa với bạn bè.', '{"wordId":"coursework","ukIpa":"/ˈkɔːswɜːk/","usIpa":"/ˈkɔːrswɝːk/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"Work completed during a course, often contributing to final assessment.","vi":"bài tập khóa học; đồ án học phần"}],"examples":[{"en":"I finished my coursework before meeting friends for lunch.","vi":"Tôi đã hoàn thành bài tập khóa học trước khi đi ăn trưa với bạn bè.","audioKind":"ex"},{"en":"Assessing students through coursework can provide a broader picture of their abilities than relying solely on examinations.","vi":"Việc đánh giá học sinh qua bài tập khóa học có thể mang lại bức tranh toàn diện hơn về năng lực của họ so với việc chỉ dựa vào các kỳ thi.","audioKind":"ex2"}],"collocations":[{"en":"submit coursework","vi":"nộp bài tập khóa học"},{"en":"complete coursework","vi":"hoàn thành bài tập khóa học"},{"en":"coursework assessment","vi":"đánh giá qua bài tập khóa học"}],"wordFamily":["course (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Không đếm được, không nói a coursework; một phần bài tập dùng a piece of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_comparative', 'en-b2-4', 'comparative', '/kəmˈpærətɪv/', 'B2', 'mang tính so sánh; đối chiếu; tương đối; từ so sánh (trong ngữ pháp)', 'adj.', 'compare (v.), comparison (n.), comparatively (adv.), comparable (adj.)', 'Đồng nghĩa: relative · Trái nghĩa: absolute', 'comparative còn có thể chỉ hình thức so sánh trong ngữ pháp, chẳng hạn như better.', 'We enjoyed the comparative quiet of the village.', NULL, 'Chúng tôi rất tận hưởng không gian yên bình tương đối của ngôi làng.', '{"wordId":"comparative","ukIpa":"/kəmˈpærətɪv/","usIpa":"/kəmˈpærətɪv/","cefr":"B2","topic":"education","senses":[{"pos":"adj.","en":"Examining similarities or differences between two or more things.","vi":"mang tính so sánh; đối chiếu"},{"pos":"adj.","en":"True to some degree when compared with something else.","vi":"tương đối"},{"pos":"n.","en":"An adjective or adverb form expressing a higher or lower degree.","vi":"từ so sánh (trong ngữ pháp)"}],"examples":[{"en":"We enjoyed the comparative quiet of the village.","vi":"Chúng tôi rất tận hưởng không gian yên bình tương đối của ngôi làng.","audioKind":"ex"},{"en":"A comparative study of transport systems can help cities identify effective ways to reduce congestion.","vi":"Một nghiên cứu so sánh về các hệ thống giao thông có thể giúp các thành phố tìm ra nhữngh hiệu quả để giảm thiểu tình trạng ùn tắc.","audioKind":"ex2"}],"collocations":[{"en":"comparative study","vi":"nghiên cứu so sánh"},{"en":"comparative advantage","vi":"lợi thế so sánh"},{"en":"comparative analysis","vi":"phân tích so sánh"},{"en":"comparative form","vi":"dạng so sánh hơn"}],"wordFamily":["compare (v.)","comparison (n.)","comparatively (adv.)","comparable (adj.)"],"synonyms":["relative"],"antonyms":["absolute"],"tipVi":"comparative còn có thể chỉ hình thức so sánh trong ngữ pháp, chẳng hạn như better.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_latin', 'en-b2-4', 'Latin', '/ˈlætɪn/', 'B2', 'tiếng La-tinh; thuộc tiếng La-tinh; thuộc thành La-tinh cổ đại; thuộc Mỹ-La-tinh, con người hoặc văn hóa nơi đây', 'n.', NULL, NULL, 'Viết hoa chữ cái đầu; Latin America chỉ Mỹ-La-tinh.', 'My sister studies Latin at school twice a week.', NULL, 'Em gái tôi học tiếng La-tinh ở trường hai lần một tuần.', '{"wordId":"latin","ukIpa":"/ˈlætɪn/","usIpa":"/ˈlætɪn/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"The language of ancient Rome.","vi":"tiếng La-tinh"},{"pos":"adj.","en":"Relating to Latin or ancient Rome.","vi":"thuộc tiếng La-tinh; thuộc thành La-tinh cổ đại"},{"pos":"adj.","en":"Relating to Latin America, its people, or its culture.","vi":"thuộc Mỹ-La-tinh, con người hoặc văn hóa nơi đây"}],"examples":[{"en":"My sister studies Latin at school twice a week.","vi":"Em gái tôi học tiếng La-tinh ở trường hai lần một tuần.","audioKind":"ex"},{"en":"Studying Latin can help students understand the origins of scientific terms and the development of European languages.","vi":"Việc học tiếng La-tinh có thể giúp học sinh hiểu được nguồn gốc của các thuật ngữ khoa học và sự phát triển của các ngôn ngữ châu Âu.","audioKind":"ex2"}],"collocations":[{"en":"study Latin","vi":"học tiếng La-tinh"},{"en":"classical Latin","vi":"tiếng La-tinh cổ điển"},{"en":"Latin alphabet","vi":"bảng chữ cái La-tinh"},{"en":"Latin music","vi":"âm nhạc Mỹ-La-tinh"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Viết hoa chữ cái đầu; Latin America chỉ Mỹ-La-tinh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_outline', 'en-b2-4', 'outline', '/ˈaʊtlaɪn/', 'B2', 'đề cương; dàn ý; bản tóm tắt; vạch ra; nêu các điểm chính; phác thảo; đường viền; hình dáng bên ngoài', 'n.', NULL, 'Đồng nghĩa: summary, overview', 'Khi chỉ tóm tắt, nó nhấn mạnh các nội dung chính mà không đi vào chi tiết đầy đủ.', 'I wrote a quick outline before starting my essay.', NULL, 'Tôi đã viết một bản dàn ý nhanh trước khi bắt tay viết bài luận.', '{"wordId":"outline","ukIpa":"/ˈaʊtlaɪn/","usIpa":"/ˈaʊtlaɪn/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"a short description covering the main points","vi":"đề cương; dàn ý; bản tóm tắt"},{"pos":"v.","en":"to describe the main points without giving full details","vi":"vạch ra; nêu các điểm chính; phác thảo"},{"pos":"n.","en":"the line showing the outer shape of something","vi":"đường viền; hình dáng bên ngoài"}],"examples":[{"en":"I wrote a quick outline before starting my essay.","vi":"Tôi đã viết một bản dàn ý nhanh trước khi bắt tay viết bài luận.","audioKind":"ex"},{"en":"The report outlines several practical measures that schools can adopt to support students with learning difficulties.","vi":"Báo cáo phác thảo một số biện pháp thiết thực mà các nhà trường có thể áp dụng để hỗ trợ học sinh gặp khó khăn trong học tập.","audioKind":"ex2"}],"collocations":[{"en":"essay outline","vi":"dàn ý bài luận"},{"en":"outline a plan","vi":"phác thảo kế hoạch"},{"en":"a brief outline","vi":"bản tóm tắt ngắn gọn"},{"en":"the outline of","vi":"đường viền của"}],"wordFamily":[],"synonyms":["summary","overview"],"antonyms":[],"tipVi":"Khi chỉ tóm tắt, nó nhấn mạnh các nội dung chính mà không đi vào chi tiết đầy đủ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_summarize', 'en-b2-4', 'summarize', '/ˈsʌməraɪz/', 'B2', 'tóm tắt; khái quát', 'v.', 'summary (n.), summarization (n.)', 'Đồng nghĩa: sum up, outline, recap', 'Tiếng Anh-Anh thường viết là summarise; khi tóm tắt cần giữ lại các ý chính.', 'Could you summarize the story before we discuss it?', NULL, 'Bạn có thể tóm tắt câu chuyện trước khi chúng ta thảo luận không?', '{"wordId":"summarize","ukIpa":"/ˈsʌməraɪz/","usIpa":"/ˈsʌməraɪz/","cefr":"B2","topic":"education","senses":[{"pos":"v.","en":"to state the main points briefly","vi":"tóm tắt; khái quát"}],"examples":[{"en":"Could you summarize the story before we discuss it?","vi":"Bạn có thể tóm tắt câu chuyện trước khi chúng ta thảo luận không?","audioKind":"ex"},{"en":"Students should learn to summarize research findings accurately rather than reproduce every detail from their sources.","vi":"Học sinh nên học cách tóm tắt các kết quả nghiên cứu một cách chính xác thay vì lặp lại mọi chi tiết từ nguồn tài liệu của họ.","audioKind":"ex2"}],"collocations":[{"en":"summarize the findings","vi":"tóm tắt các kết quả"},{"en":"summarize the main points","vi":"tóm tắt các ý chính"},{"en":"summarize an argument","vi":"tóm tắt một luận điểm"}],"wordFamily":["summary (n.)","summarization (n.)"],"synonyms":["sum up","outline","recap"],"antonyms":[],"tipVi":"Tiếng Anh-Anh thường viết là summarise; khi tóm tắt cần giữ lại các ý chính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_appendix', 'en-b2-4', 'appendix', '/əˈpendɪks/', 'B2', 'phụ lục (sách, tài liệu); ruột thừa', 'n.', 'append (v.), appendicitis (n.)', NULL, 'Phụ lục có dạng số nhiều là appendices; ruột thừa thường dùng appendixes.', 'You''ll find the full recipe in the appendix.', NULL, 'Bạn sẽ tìm thấy công thức đầy đủ ở phần phụ lục.', '{"wordId":"appendix","ukIpa":"/əˈpendɪks/","usIpa":"/əˈpendɪks/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"An extra section containing supporting information at a book''s end","vi":"phụ lục (sách, tài liệu)"},{"pos":"n.","en":"A small tube attached to the beginning of the large intestine","vi":"ruột thừa"}],"examples":[{"en":"You''ll find the full recipe in the appendix.","vi":"Bạn sẽ tìm thấy công thức đầy đủ ở phần phụ lục.","audioKind":"ex"},{"en":"The report includes an appendix explaining how researchers collected and analysed the survey data.","vi":"Báo cáo bao gồm một phần phụ lục giải thích cách các nhà nghiên cứu thu thập và phân tích dữ liệu khảo sát.","audioKind":"ex2"}],"collocations":[{"en":"in the appendix","vi":"trong phần phụ lục"},{"en":"an appendix to a report","vi":"phụ lục của một bản báo cáo"},{"en":"a ruptured appendix","vi":"viêm ruột thừa cấp / ruột thừa bị vỡ"}],"wordFamily":["append (v.)","appendicitis (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Phụ lục có dạng số nhiều là appendices; ruột thừa thường dùng appendixes.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_assess', 'en-b2-4', 'assess', '/əˈses/', 'B2', 'đánh giá; định giá; tính toán giá trị; định mức', 'v.', 'assessment (n.), assessor (n.)', 'Đồng nghĩa: evaluate, appraise', 'assess đi trực tiếp với tân ngữ; danh từ của nó là assessment.', 'The mechanic assessed the damage before repairing my bicycle.', NULL, 'Thợ máy đã đánh giá mức độ hư hỏng trước khi sửa chiếc xe đạp cho tôi.', '{"wordId":"assess","ukIpa":"/əˈses/","usIpa":"/əˈses/","cefr":"B2","topic":"education","senses":[{"pos":"v.","en":"Judge the quality, importance, or condition of something.","vi":"đánh giá; định giá"},{"pos":"v.","en":"Calculate the value of something or the amount owed.","vi":"tính toán giá trị; định mức"}],"examples":[{"en":"The mechanic assessed the damage before repairing my bicycle.","vi":"Thợ máy đã đánh giá mức độ hư hỏng trước khi sửa chiếc xe đạp cho tôi.","audioKind":"ex"},{"en":"Schools should assess students through varied tasks rather than relying entirely on final examinations.","vi":"Nhà trường nên đánh giá học sinh thông qua nhiều hình thức đa dạng thay vì hoàn toàn phụ thuộc vào các bài thi cuối kỳ.","audioKind":"ex2"}],"collocations":[{"en":"assess the impact","vi":"đánh giá tác động"},{"en":"assess the risk","vi":"đánh giá rủi ro"},{"en":"assess performance","vi":"đánh giá năng lực"},{"en":"assess the damage","vi":"đánh giá thiệt hại"}],"wordFamily":["assessment (n.)","assessor (n.)"],"synonyms":["evaluate","appraise"],"antonyms":[],"tipVi":"assess đi trực tiếp với tân ngữ; danh từ của nó là assessment.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_suffix', 'en-b2-4', 'suffix', '/ˈsʌfɪks/', 'B2', 'hậu tố', 'n.', 'suffixation (n.)', NULL, 'suffix được thêm vào cuối từ; trong khi prefix được thêm vào đầu từ.', 'Our teacher showed us how a suffix changes a word.', NULL, 'Giáo viên đã cho chúng tôi thấy một hậu tố làm thay đổi từ tính như thế nào.', '{"wordId":"suffix","ukIpa":"/ˈsʌfɪks/","usIpa":"/ˈsʌfɪks/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"A word part added at the end to change meaning or grammar.","vi":"hậu tố"}],"examples":[{"en":"Our teacher showed us how a suffix changes a word.","vi":"Giáo viên đã cho chúng tôi thấy một hậu tố làm thay đổi từ tính như thế nào.","audioKind":"ex"},{"en":"Learning common suffixes helps students recognise word classes and understand unfamiliar vocabulary in academic texts.","vi":"Việc học các hậu tố thông thường giúp học sinh nhận diện từ loại và hiểu được các từ vựng lạ trong văn bản học thuật.","audioKind":"ex2"}],"collocations":[{"en":"add a suffix","vi":"thêm hậu tố"},{"en":"a noun suffix","vi":"hậu tố danh từ"},{"en":"a plural suffix","vi":"hậu tố số nhiều"}],"wordFamily":["suffixation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"suffix được thêm vào cuối từ; trong khi prefix được thêm vào đầu từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_linguistics', 'en-b2-4', 'linguistics', '/lɪŋˈɡwɪstɪks/', 'B2', 'ngôn ngữ học', 'n.', 'linguist (n.), linguistic (adj.), linguistically (adv.)', NULL, 'Mặc dù tận cùng bằng chữ s, tên môn học này thường đi với động từ số ít.', 'My sister studies linguistics and loves comparing different accents.', NULL, 'Chị tôi học chuyên ngành ngôn ngữ học và rất thích so sánh các ngữ điệu khác nhau.', '{"wordId":"linguistics","ukIpa":"/lɪŋˈɡwɪstɪks/","usIpa":"/lɪŋˈɡwɪstɪks/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"The scientific study of language and how it works.","vi":"ngôn ngữ học"}],"examples":[{"en":"My sister studies linguistics and loves comparing different accents.","vi":"Chị tôi học chuyên ngành ngôn ngữ học và rất thích so sánh các ngữ điệu khác nhau.","audioKind":"ex"},{"en":"Research in linguistics can help teachers develop more effective methods for teaching foreign languages.","vi":"Nghiên cứu trong lĩnh vực ngôn ngữ học có thể giúp giáo viên phát triển các phương pháp giảng dạy ngoại ngữ hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"applied linguistics","vi":"ngôn ngữ học ứng dụng"},{"en":"historical linguistics","vi":"ngôn ngữ học lịch sử"},{"en":"study linguistics","vi":"nghiên cứu ngôn ngữ học"}],"wordFamily":["linguist (n.)","linguistic (adj.)","linguistically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Mặc dù tận cùng bằng chữ s, tên môn học này thường đi với động từ số ít.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_feedback', 'en-b2-4', 'feedback', '/ˈfiːdbæk/', 'B2', 'phản hồi; ý kiến đóng góp', 'n.', 'feed back (v.)', NULL, 'Không đếm được, không dùng a feedback hay feedbacks; hãy dùng some feedback.', 'My tutor gave me helpful feedback on my essay.', NULL, 'Giáo viên hướng dẫn đã đưa ra những nhận xét hữu ích cho bài luận của tôi.', '{"wordId":"feedback","ukIpa":"/ˈfiːdbæk/","usIpa":"/ˈfiːdbæk/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"comments about performance or work that help someone improve","vi":"phản hồi; ý kiến đóng góp"}],"examples":[{"en":"My tutor gave me helpful feedback on my essay.","vi":"Giáo viên hướng dẫn đã đưa ra những nhận xét hữu ích cho bài luận của tôi.","audioKind":"ex"},{"en":"Regular feedback enables students to identify weaknesses and develop more effective strategies for independent learning.","vi":"Phản hồi thường xuyên giúp học sinh nhận ra điểm yếu và xây dựng các chiến lược học tập độc lập hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"constructive feedback","vi":"phản hồi mang tính xây dựng"},{"en":"give feedback on","vi":"đưa ra phản hồi về"},{"en":"customer feedback","vi":"ý kiến phản hồi của khách hàng"},{"en":"ask for feedback","vi":"xin ý kiến góp ý"}],"wordFamily":["feed back (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Không đếm được, không dùng a feedback hay feedbacks; hãy dùng some feedback.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_literal', 'en-b2-4', 'literal', '/ˈlɪtərəl/', 'B2', 'theo nghĩa đen; nguyên văn; sao y bản chính; dịch sát từng chữ', 'adj.', 'literally (adv.)', 'Trái nghĩa: figurative', 'literal mang nghĩa sát chữ; còn literary mang nghĩa văn học, cần lưu ý phân biệt.', 'I meant cold feet in the literal sense.', NULL, 'Ý tôi chân thực là lạnh chân theo đúng nghĩa đen, không có ẩn ý gì cả.', '{"wordId":"literal","ukIpa":"/ˈlɪtərəl/","usIpa":"/ˈlɪtərəl/","cefr":"B2","topic":"education","senses":[{"pos":"adj.","en":"using the basic meaning of words, without metaphor","vi":"theo nghĩa đen; nguyên văn"},{"pos":"adj.","en":"following the exact words rather than the overall meaning","vi":"sao y bản chính; dịch sát từng chữ"}],"examples":[{"en":"I meant cold feet in the literal sense.","vi":"Ý tôi chân thực là lạnh chân theo đúng nghĩa đen, không có ẩn ý gì cả.","audioKind":"ex"},{"en":"A literal translation may preserve individual words while failing to convey the cultural meaning of an expression.","vi":"Bản dịch sát từng chữ có thể giữ lại được từng từ đơn lẻ nhưng lại thất bại trong việc truyền tải ý nghĩa văn hóa của một thành ngữ.","audioKind":"ex2"}],"collocations":[{"en":"literal meaning","vi":"ý nghĩa theo nghĩa đen"},{"en":"literal translation","vi":"bản dịch sát nghĩa từng từ"},{"en":"literal interpretation","vi":"cách hiểu theo nghĩa đen"}],"wordFamily":["literally (adv.)"],"synonyms":[],"antonyms":["figurative"],"tipVi":"literal mang nghĩa sát chữ; còn literary mang nghĩa văn học, cần lưu ý phân biệt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clarify', 'en-b2-4', 'clarify', '/ˈklerəfaɪ/', 'B2', 'làm rõ; giải thích; lọc trong (chất lỏng)', 'v.', 'clarification (n), clarity (n), clear (adj)', 'Đồng nghĩa: explain, elucidate · Trái nghĩa: obscure, confuse', 'clarify trực tiếp đi liền với nội dung cần giải thích, ví dụ như clarify the rules.', 'Could you clarify which entrance we should use?', NULL, 'Bạn có thể làm rõ xem chúng ta nên đi lối vào nào không?', '{"wordId":"clarify","ukIpa":"/ˈklærɪfaɪ/","usIpa":"/ˈklerəfaɪ/","cefr":"B2","topic":"education","senses":[{"pos":"v.","en":"To make something easier to understand by explaining it clearly.","vi":"làm rõ; giải thích"},{"pos":"v.","en":"To make a liquid clearer by removing unwanted substances.","vi":"lọc trong (chất lỏng)"}],"examples":[{"en":"Could you clarify which entrance we should use?","vi":"Bạn có thể làm rõ xem chúng ta nên đi lối vào nào không?","audioKind":"ex"},{"en":"Governments should clarify how personal data will be used before introducing digital identity systems.","vi":"Chính phủ nên làm rõ cách thức dữ liệu cá nhân sẽ được sử dụng trước khi triển khai hệ thống định danh kỹ thuật số.","audioKind":"ex2"}],"collocations":[{"en":"clarify a point","vi":"làm rõ một vấn đề"},{"en":"clarify the situation","vi":"làm rõ tình hình"},{"en":"clarify the meaning","vi":"giải thích ý nghĩa"},{"en":"clarified butter","vi":"bơ đun lọc trong"}],"wordFamily":["clarification (n)","clarity (n)","clear (adj)"],"synonyms":["explain","elucidate"],"antonyms":["obscure","confuse"],"tipVi":"clarify trực tiếp đi liền với nội dung cần giải thích, ví dụ như clarify the rules.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_concise', 'en-b2-4', 'concise', '/kənˈsaɪs/', 'B2', 'ngắn gọn; súc tích', 'adj.', 'concisely (adv.), conciseness (n.), concision (n.)', 'Đồng nghĩa: succinct, brief · Trái nghĩa: wordy, verbose', 'Không chỉ mang nghĩa ngắn, từ này còn nhấn mạnh thông tin rõ ràng và không rườm rà.', 'Her concise directions helped us find the station easily.', NULL, 'Những chỉ dẫn ngắn gọn của cô ấy đã giúp chúng tôi tìm thấy nhà ga một cách dễ dàng.', '{"wordId":"concise","ukIpa":"/kənˈsaɪs/","usIpa":"/kənˈsaɪs/","cefr":"B2","topic":"education","senses":[{"pos":"adj.","en":"Expressing information clearly in few words, without unnecessary detail.","vi":"ngắn gọn; súc tích"}],"examples":[{"en":"Her concise directions helped us find the station easily.","vi":"Những chỉ dẫn ngắn gọn của cô ấy đã giúp chúng tôi tìm thấy nhà ga một cách dễ dàng.","audioKind":"ex"},{"en":"Clear and concise public health advice enables people to understand risks and make informed decisions quickly.","vi":"Các khuyến nghị y tế công cộng rõ ràng và súc tích giúp mọi người hiểu được rủi ro và đưa ra quyết định sáng suốt một cách nhanh chóng.","audioKind":"ex2"}],"collocations":[{"en":"clear and concise","vi":"rõ ràng và súc tích"},{"en":"concise summary","vi":"bản tóm tắt ngắn gọn"},{"en":"concise explanation","vi":"lời giải thích súc tích"}],"wordFamily":["concisely (adv.)","conciseness (n.)","concision (n.)"],"synonyms":["succinct","brief"],"antonyms":["wordy","verbose"],"tipVi":"Không chỉ mang nghĩa ngắn, từ này còn nhấn mạnh thông tin rõ ràng và không rườm rà.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_attendance', 'en-b2-4', 'attendance', '/əˈtendəns/', 'B2', 'sự tham dự; sự có mặt; sỉ số; số lượng người tham dự', 'n.', 'attend (v.), attendee (n.), attendant (n.)', 'Trái nghĩa: absence', 'Động từ attend đi thẳng với tân ngữ chỉ sự kiện; còn danh từ attendance thường đi với giới từ at.', 'Our teacher checks attendance at the start of every lesson.', NULL, 'Giáo viên của chúng tôi điểm danh vào đầu mỗi buổi học.', '{"wordId":"attendance","ukIpa":"/əˈtendəns/","usIpa":"/əˈtendəns/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"The act of being present at an event or place.","vi":"sự tham dự; sự có mặt"},{"pos":"n.","en":"The number of people present at an event.","vi":"sỉ số; số lượng người tham dự"}],"examples":[{"en":"Our teacher checks attendance at the start of every lesson.","vi":"Giáo viên của chúng tôi điểm danh vào đầu mỗi buổi học.","audioKind":"ex"},{"en":"Regular school attendance is associated with stronger academic performance and better opportunities for social development.","vi":"Việc đi học chuyên cần có liên quan mật thiết đến kết quả học tập tốt hơn và nhiều cơ hội phát triển kỹ năng xã hội hơn.","audioKind":"ex2"}],"collocations":[{"en":"school attendance","vi":"tỷ lệ đến trường"},{"en":"attendance rate","vi":"tỷ lệ chuyên cần"},{"en":"poor attendance","vi":"tỷ lệ có mặt kém"},{"en":"compulsory attendance","vi":"sự tham gia bắt buộc"}],"wordFamily":["attend (v.)","attendee (n.)","attendant (n.)"],"synonyms":[],"antonyms":["absence"],"tipVi":"Động từ attend đi thẳng với tân ngữ chỉ sự kiện; còn danh từ attendance thường đi với giới từ at.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_repetition', 'en-b2-4', 'repetition', '/ˌrepəˈtɪʃən/', 'B2', 'sự lặp lại; sự luyện tập lặp đi lặp lại', 'n.', 'repeat (v.), repetitive (adj.), repeatedly (adv.)', NULL, 'Từ repetition nhấn mạnh sự lặp lại; còn rehearsal chỉ buổi tập dượt trước khi biểu diễn.', 'Through daily repetition, I finally remembered the whole song.', NULL, 'Nhờ lặp đi lặp lại hàng ngày, cuối cùng tôi đã ghi nhớ được toàn bộ bài hát.', '{"wordId":"repetition","ukIpa":"/ˌrepəˈtɪʃən/","usIpa":"/ˌrepəˈtɪʃən/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"Doing or saying something again, often several times","vi":"sự lặp lại; sự luyện tập lặp đi lặp lại"}],"examples":[{"en":"Through daily repetition, I finally remembered the whole song.","vi":"Nhờ lặp đi lặp lại hàng ngày, cuối cùng tôi đã ghi nhớ được toàn bộ bài hát.","audioKind":"ex"},{"en":"Regular repetition can help language learners remember new vocabulary, especially when combined with meaningful practice.","vi":"Việc lặp lại thường xuyên có thể giúp người học ngoại ngữ ghi nhớ từ vựng mới, nhất là khi kết hợp với các bài tập có ý nghĩa.","audioKind":"ex2"}],"collocations":[{"en":"constant repetition","vi":"sự lặp lại liên tục"},{"en":"avoid repetition","vi":"tránh lặp từ"},{"en":"learn through repetition","vi":"học tập thông qua sự lặp lại"}],"wordFamily":["repeat (v.)","repetitive (adj.)","repeatedly (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ repetition nhấn mạnh sự lặp lại; còn rehearsal chỉ buổi tập dượt trước khi biểu diễn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cite', 'en-b2-4', 'cite', '/saɪt/', 'B2', 'trích dẫn; dẫn chứng; nêu ra; viện dẫn (lý do)', 'v.', 'citation (n.)', 'Đồng nghĩa: quote, reference, mention', 'cite là trích dẫn; site là địa điểm; sight là thị lực, ba từ này phát âm giống nhau.', 'Please cite the book you used for your project.', NULL, 'Vui lòng trích dẫn cuốn sách bạn đã dùng cho dự án của mình.', '{"wordId":"cite","ukIpa":"/saɪt/","usIpa":"/saɪt/","cefr":"B2","topic":"education","senses":[{"pos":"v.","en":"To mention a source or example supporting a statement.","vi":"trích dẫn; dẫn chứng"},{"pos":"v.","en":"To give something as a reason or explanation.","vi":"nêu ra; viện dẫn (lý do)"}],"examples":[{"en":"Please cite the book you used for your project.","vi":"Vui lòng trích dẫn cuốn sách bạn đã dùng cho dự án của mình.","audioKind":"ex"},{"en":"Researchers often cite access to green spaces as an important factor in improving urban residents'' mental health.","vi":"Các nhà nghiên cứu thường viện dẫn việc tiếp cận không gian xanh là một yếu tố quan trọng trong việc cải thiện sức khỏe tinh thần của cư dân đô thị.","audioKind":"ex2"}],"collocations":[{"en":"cite evidence","vi":"trích dẫn chứng cứ"},{"en":"cite a source","vi":"trích dẫn nguồn"},{"en":"cite an example","vi":"dẫn chứng một ví dụ"},{"en":"cite as a reason","vi":"nêu làm lý do"}],"wordFamily":["citation (n.)"],"synonyms":["quote","reference","mention"],"antonyms":[],"tipVi":"cite là trích dẫn; site là địa điểm; sight là thị lực, ba từ này phát âm giống nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exceptional', 'en-b2-4', 'exceptional', '/ɪkˈsepʃənəl/', 'B2', 'xuất chúng; kiệt xuất; phi thường; đặc biệt; ngoại lệ', 'adj.', 'exception (n.), exceptionally (adv.)', 'Đồng nghĩa: outstanding, extraordinary · Trái nghĩa: ordinary, mediocre', 'Thường chỉ mức độ xuất sắc đặc biệt; exceptional circumstances nghĩa là trường hợp đặc biệt.', 'The young violinist gave an exceptional performance last night.', NULL, 'Nghệ sĩ vĩ cầm trẻ tuổi đã có màn trình diễn xuất sắc vào tối qua.', '{"wordId":"exceptional","ukIpa":"/ɪkˈsepʃənəl/","usIpa":"/ɪkˈsepʃənəl/","cefr":"B2","topic":"education","senses":[{"pos":"adj.","en":"far better than usual","vi":"xuất chúng; kiệt xuất; phi thường"},{"pos":"adj.","en":"unusual and outside normal circumstances","vi":"đặc biệt; ngoại lệ"}],"examples":[{"en":"The young violinist gave an exceptional performance last night.","vi":"Nghệ sĩ vĩ cầm trẻ tuổi đã có màn trình diễn xuất sắc vào tối qua.","audioKind":"ex"},{"en":"Students with exceptional ability may require additional challenges to remain engaged in classroom learning.","vi":"Học sinh có năng lực vượt trội có thể cần những thử thách bổ sung để duy trì sự tập trung trong việc học trên lớp.","audioKind":"ex2"}],"collocations":[{"en":"exceptional ability","vi":"năng lực xuất chúng"},{"en":"exceptional circumstances","vi":"trường hợp ngoại lệ"},{"en":"exceptional performance","vi":"màn trình diễn xuất sắc"}],"wordFamily":["exception (n.)","exceptionally (adv.)"],"synonyms":["outstanding","extraordinary"],"antonyms":["ordinary","mediocre"],"tipVi":"Thường chỉ mức độ xuất sắc đặc biệt; exceptional circumstances nghĩa là trường hợp đặc biệt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tuition', 'en-b2-4', 'tuition', '/tuˈɪʃən/', 'B2', 'học phí; sự dạy học; sự kèm cặp; sự kèm học', 'n.', NULL, NULL, 'Danh từ không đếm được; trong tiếng Anh-Anh, khi nói về tiền học phí thường dùng tuition fees.', 'She works at weekends to help pay her tuition.', NULL, 'Cô ấy đi làm vào các ngày cuối tuần để giúp chi trả học phí của mình.', '{"wordId":"tuition","ukIpa":"/tjuˈɪʃən/","usIpa":"/tuˈɪʃən/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"money paid for teaching at a school or university","vi":"học phí"},{"pos":"n.","en":"teaching provided to an individual or a small group","vi":"sự dạy học; sự kèm cặp; sự kèm học"}],"examples":[{"en":"She works at weekends to help pay her tuition.","vi":"Cô ấy đi làm vào các ngày cuối tuần để giúp chi trả học phí của mình.","audioKind":"ex"},{"en":"Rising university tuition fees may discourage students from disadvantaged backgrounds from pursuing higher education.","vi":"Học phí đại học tăng cao có thể khiến học sinh sinh viên đến từ các gia đình có hoàn cảnh khó khăn nản lòng trong việc theo đuổi giáo dục bậc cao.","audioKind":"ex2"}],"collocations":[{"en":"tuition fees","vi":"học phí"},{"en":"private tuition","vi":"gia sư riêng"},{"en":"pay tuition","vi":"đóng học phí"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ không đếm được; trong tiếng Anh-Anh, khi nói về tiền học phí thường dùng tuition fees.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_correction', 'en-b2-4', 'correction', '/kəˈrekʃən/', 'B2', 'sự sửa chữa; sự hiệu chỉnh', 'n.', 'correct (v.), correct (adj.), correctly (adv.), corrective (adj.)', 'Đồng nghĩa: rectification, amendment', 'Một chỗ sửa cụ thể là danh từ đếm được; quá trình sửa chữa nói chung thường không đếm được.', 'I made a correction before sending the email.', NULL, 'Tôi đã sửa một lỗi trước khi gửi email.', '{"wordId":"correction","ukIpa":"/kəˈrekʃən/","usIpa":"/kəˈrekʃən/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"A change that fixes an error, or the act of fixing it.","vi":"sự sửa chữa; sự hiệu chỉnh"}],"examples":[{"en":"I made a correction before sending the email.","vi":"Tôi đã sửa một lỗi trước khi gửi email.","audioKind":"ex"},{"en":"Timely correction of factual errors helps news organizations maintain public trust and prevent misinformation from spreading.","vi":"Việc kịp thời sửa chữa các lỗi sai về mặt sự kiện giúp các tổ chức tin tức duy trì lòng tin của công chúng và ngăn chặn sự lan truyền của thông tin sai lệch.","audioKind":"ex2"}],"collocations":[{"en":"make a correction","vi":"tiến hành sửa chữa"},{"en":"error correction","vi":"sửa lỗi"},{"en":"minor correction","vi":"sửa đổi nhỏ"},{"en":"correction of errors","vi":"sự hiệu chỉnh lỗi sai"}],"wordFamily":["correct (v.)","correct (adj.)","correctly (adv.)","corrective (adj.)"],"synonyms":["rectification","amendment"],"antonyms":[],"tipVi":"Một chỗ sửa cụ thể là danh từ đếm được; quá trình sửa chữa nói chung thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_assessed', 'en-b2-4', 'assessed', '/əˈsest/', 'B2', 'được đánh giá; được định giá', 'v.', 'assess (v.), assessment (n.), assessor (n.)', 'Đồng nghĩa: evaluated, appraised', 'Là dạng quá khứ và quá phân từ của assess, âm cuối phát âm là /st/.', 'The mechanic assessed the damage before repairing my bicycle.', NULL, 'Người thợ máy đã đánh giá mức độ hư hỏng trước khi sửa chiếc xe đạp cho tôi.', '{"wordId":"assessed","ukIpa":"/əˈsest/","usIpa":"/əˈsest/","cefr":"B2","topic":"education","senses":[{"pos":"v.","en":"Evaluated the quality, value, extent, or importance of something.","vi":"được đánh giá; được định giá"}],"examples":[{"en":"The mechanic assessed the damage before repairing my bicycle.","vi":"Người thợ máy đã đánh giá mức độ hư hỏng trước khi sửa chiếc xe đạp cho tôi.","audioKind":"ex"},{"en":"Students should be assessed through varied tasks rather than judged solely on their performance in final examinations.","vi":"Học sinh nên được đánh giá thông qua các nhiệm vụ đa dạng thay vì chỉ bị phán đoán dựa trên kết quả các bài kiểm tra cuối kỳ.","audioKind":"ex2"}],"collocations":[{"en":"assessed the damage","vi":"đánh giá mức độ tổn thất"},{"en":"assessed the risk","vi":"đánh giá rủi ro"},{"en":"be assessed on","vi":"được đánh giá dựa trên"}],"wordFamily":["assess (v.)","assessment (n.)","assessor (n.)"],"synonyms":["evaluated","appraised"],"antonyms":[],"tipVi":"Là dạng quá khứ và quá phân từ của assess, âm cuối phát âm là /st/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_visual', 'en-b2-4', 'visual', '/ˈvɪʒuəl/', 'B2', 'thuộc về thị giác; tài liệu trực quan; hình ảnh', 'adj.', 'visually (adv.), visualise (v.), visualisation (n.)', NULL, 'visual chỉ những gì liên quan đến thị giác; từ "sinh động" thường dùng vivid.', 'The exhibition combines music with some stunning visual effects.', NULL, 'Triển lãm kết hợp âm nhạc với một số hiệu ứng thị giác tuyệt đẹp.', '{"wordId":"visual","ukIpa":"/ˈvɪʒuəl/","usIpa":"/ˈvɪʒuəl/","cefr":"B2","topic":"education","senses":[{"pos":"adj.","en":"Relating to sight or things that can be seen.","vi":"thuộc về thị giác"},{"pos":"n.","en":"An image used to explain something or attract attention.","vi":"tài liệu trực quan; hình ảnh"}],"examples":[{"en":"The exhibition combines music with some stunning visual effects.","vi":"Triển lãm kết hợp âm nhạc với một số hiệu ứng thị giác tuyệt đẹp.","audioKind":"ex"},{"en":"Teachers can use visual aids to make complex scientific concepts easier for younger students to understand.","vi":"Giáo viên có thể sử dụng các phương tiện trực quan để giúp học sinh nhỏ tuổi dễ hiểu hơn các khái niệm khoa học phức tạp.","audioKind":"ex2"}],"collocations":[{"en":"visual aids","vi":"dụng cụ trực quan"},{"en":"visual effects","vi":"hiệu ứng thị giác"},{"en":"visual impairment","vi":"khiếm thị"},{"en":"visual information","vi":"thông tin thị giác"}],"wordFamily":["visually (adv.)","visualise (v.)","visualisation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"visual chỉ những gì liên quan đến thị giác; từ \"sinh động\" thường dùng vivid.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_module', 'en-b2-4', 'module', '/ˈmɑːdʒuːl/', 'B2', 'học phần; phần; đơn vị học tập; khối chức năng; bộ phận; mô-đun phần mềm', 'n.', 'modular (adj.)', 'Đồng nghĩa: unit, component', 'Khóa học trong module là một đơn vị độc lập, thường bao gồm nhiều bài học.', 'We finished the photography module with an outdoor project.', NULL, 'Chúng tôi đã hoàn thành học phần nhiếp ảnh với một dự án ngoài trời.', '{"wordId":"module","ukIpa":"/ˈmɒdjuːl/","usIpa":"/ˈmɑːdʒuːl/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"a separate unit within a larger course of study","vi":"học phần; phần; đơn vị học tập"},{"pos":"n.","en":"a separate part of a machine, system, or software","vi":"khối chức năng; bộ phận; mô-đun phần mềm"}],"examples":[{"en":"We finished the photography module with an outdoor project.","vi":"Chúng tôi đã hoàn thành học phần nhiếp ảnh với một dự án ngoài trời.","audioKind":"ex"},{"en":"Universities increasingly offer a compulsory module on digital skills to prepare students for changing workplace demands.","vi":"Các trường đại học ngày càng cung cấp nhiều học phần bắt buộc về kỹ năng số nhằm chuẩn bị cho sinh viên trước những nhu cầu thay đổi của nơi làm việc.","audioKind":"ex2"}],"collocations":[{"en":"a compulsory module","vi":"học phần bắt buộc"},{"en":"an optional module","vi":"học phần tự chọn"},{"en":"a software module","vi":"mô-đun phần mềm"},{"en":"complete a module","vi":"hoàn thành một học phần"}],"wordFamily":["modular (adj.)"],"synonyms":["unit","component"],"antonyms":[],"tipVi":"Khóa học trong module là một đơn vị độc lập, thường bao gồm nhiều bài học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bilingual', 'en-b2-4', 'bilingual', '/ˌbaɪˈlɪŋɡwəl/', 'B2', 'song ngữ; sử dụng hai ngôn ngữ; người sử dụng thành thạo hai ngôn ngữ', 'adj.', 'bilingualism (n.)', 'Trái nghĩa: monolingual', 'Để chỉ việc thành thạo hai ngôn ngữ nào, có thể dùng cấu trúc bilingual in A and B.', 'Our bilingual neighbour speaks both English and Chinese fluently.', NULL, 'Người hàng xóm song ngữ của chúng tôi nói trôi chảy cả tiếng Anh lẫn tiếng Trung.', '{"wordId":"bilingual","ukIpa":"/ˌbaɪˈlɪŋɡwəl/","usIpa":"/ˌbaɪˈlɪŋɡwəl/","cefr":"B2","topic":"education","senses":[{"pos":"adj.","en":"Able to use two languages, or involving two languages.","vi":"song ngữ; sử dụng hai ngôn ngữ"},{"pos":"n.","en":"Someone who can use two languages fluently.","vi":"người sử dụng thành thạo hai ngôn ngữ"}],"examples":[{"en":"Our bilingual neighbour speaks both English and Chinese fluently.","vi":"Người hàng xóm song ngữ của chúng tôi nói trôi chảy cả tiếng Anh lẫn tiếng Trung.","audioKind":"ex"},{"en":"Bilingual education can help children maintain their cultural identity while developing skills for an increasingly connected world.","vi":"Giáo dục song ngữ có thể giúp trẻ em duy trì bản sắc văn hóa trong khi phát triển các kỹ năng cho một thế giới ngày càng kết nối.","audioKind":"ex2"}],"collocations":[{"en":"bilingual education","vi":"giáo dục song ngữ"},{"en":"bilingual dictionary","vi":"từ điển song ngữ"},{"en":"bilingual speaker","vi":"người nói song ngữ"}],"wordFamily":["bilingualism (n.)"],"synonyms":[],"antonyms":["monolingual"],"tipVi":"Để chỉ việc thành thạo hai ngôn ngữ nào, có thể dùng cấu trúc bilingual in A and B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_kindergarten', 'en-b2-4', 'kindergarten', '/ˈkɪndərɡɑːrtən/', 'B2', 'trường mẫu giáo; lớp mẫu giáo', 'n.', NULL, NULL, 'Tiếng Anh-Mỹ thường chỉ năm học trước tiểu học; tiếng Anh-Anh thường dùng nursery.', 'My daughter painted a bright yellow bird at kindergarten.', NULL, 'Con gái tôi đã vẽ một chú chim màu vàng rực rỡ ở trường mẫu giáo.', '{"wordId":"kindergarten","ukIpa":"/ˈkɪndəɡɑːtən/","usIpa":"/ˈkɪndərɡɑːrtən/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"A school or class for children beginning their education","vi":"trường mẫu giáo; lớp mẫu giáo"}],"examples":[{"en":"My daughter painted a bright yellow bird at kindergarten.","vi":"Con gái tôi đã vẽ một chú chim màu vàng rực rỡ ở trường mẫu giáo.","audioKind":"ex"},{"en":"High-quality kindergarten education can develop children''s social skills and prepare them for more structured learning.","vi":"Giáo dục mầm non chất lượng cao có thể phát triển kỹ năng xã hội của trẻ và chuẩn bị cho các em bước vào môi trường học tập có hệ thống hơn.","audioKind":"ex2"}],"collocations":[{"en":"kindergarten teacher","vi":"giáo viên mầm non"},{"en":"attend kindergarten","vi":"đi học mẫu giáo"},{"en":"kindergarten classroom","vi":"lớp học mẫu giáo"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tiếng Anh-Mỹ thường chỉ năm học trước tiểu học; tiếng Anh-Anh thường dùng nursery.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_overview', 'en-b2-4', 'overview', '/ˈoʊvɚvjuː/', 'B2', 'tổng quan; bản tóm tắt', 'n.', NULL, 'Đồng nghĩa: summary, outline', 'Thường đóng vai trò là danh từ đếm được; hay đi với cụm an overview of.', 'Our guide gave us an overview of the tour.', NULL, 'Hướng dẫn viên đã cung cấp cho chúng tôi một cái nhìn tổng quan về chuyến tham quan.', '{"wordId":"overview","ukIpa":"/ˈəʊvəvjuː/","usIpa":"/ˈoʊvɚvjuː/","cefr":"B2","topic":"education","senses":[{"pos":"n.","en":"A short account presenting the main features of a subject.","vi":"tổng quan; bản tóm tắt"}],"examples":[{"en":"Our guide gave us an overview of the tour.","vi":"Hướng dẫn viên đã cung cấp cho chúng tôi một cái nhìn tổng quan về chuyến tham quan.","audioKind":"ex"},{"en":"The opening section provides an overview of the main challenges facing renewable energy development.","vi":"Phần mở đầu cung cấp một cái nhìn tổng quan về những thách thức chính đối với sự phát triển năng lượng tái tạo.","audioKind":"ex2"}],"collocations":[{"en":"provide an overview","vi":"cung cấp cái nhìn tổng quan"},{"en":"a brief overview","vi":"bản tóm tắt ngắn gọn"},{"en":"a general overview","vi":"tổng quan chung"},{"en":"an overview of","vi":"tổng quan về..."}],"wordFamily":[],"synonyms":["summary","outline"],"antonyms":[],"tipVi":"Thường đóng vai trò là danh từ đếm được; hay đi với cụm an overview of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_illustrate', 'en-b2-4', 'illustrate', '/ˈɪləstreɪt/', 'B2', 'làm rõ, minh họa (qua ví dụ hoặc bằng chứng); minh họa, vẽ tranh minh họa cho sách', 'v.', 'illustration (n.), illustrator (n.), illustrative (adj.)', 'Đồng nghĩa: demonstrate, explain', 'illustrate có thể dùng ví dụ để giải thích, không nhất thiết phải liên quan đến hình ảnh.', 'She used two jars to illustrate the difference.', NULL, 'Cô ấy dùng hai chiếc lọ để minh họa cho sự khác biệt.', '{"wordId":"illustrate","ukIpa":"/ˈɪləstreɪt/","usIpa":"/ˈɪləstreɪt/","cefr":"B2","topic":"education","senses":[{"pos":"v.","en":"To make something clear through examples or evidence.","vi":"làm rõ, minh họa (qua ví dụ hoặc bằng chứng)"},{"pos":"v.","en":"To provide pictures for a book or other publication.","vi":"minh họa, vẽ tranh minh họa cho sách"}],"examples":[{"en":"She used two jars to illustrate the difference.","vi":"Cô ấy dùng hai chiếc lọ để minh họa cho sự khác biệt.","audioKind":"ex"},{"en":"These findings illustrate how access to public transport can improve employment opportunities in disadvantaged communities.","vi":"Những phát hiện này minh họa cách việc tiếp cận giao thông công cộng có thể cải thiện cơ hội việc làm ở các cộng đồng kém may mắn.","audioKind":"ex2"}],"collocations":[{"en":"illustrate a point","vi":"làm rõ một quan điểm"},{"en":"illustrate the importance of","vi":"minh họa tầm quan trọng của"},{"en":"illustrate a book","vi":"minh họa cho một cuốn sách"}],"wordFamily":["illustration (n.)","illustrator (n.)","illustrative (adj.)"],"synonyms":["demonstrate","explain"],"antonyms":[],"tipVi":"illustrate có thể dùng ví dụ để giải thích, không nhất thiết phải liên quan đến hình ảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_4_1', 'en-b2-4', 'Cách dùng “attendance” (n.) — sự tham dự; sự có mặt', 'school attendance  ·  attendance rate  ·  poor attendance', 'Động từ attend đi thẳng với tân ngữ chỉ sự kiện; còn danh từ attendance thường đi với giới từ at.', 'Họ từ (Word Family): attend (v.), attendee (n.), attendant (n.) | Trái nghĩa: absence', '[{"hanzi":"Our teacher checks attendance at the start of every lesson.","pinyin":"","meaning":"Giáo viên của chúng tôi điểm danh vào đầu mỗi buổi học."},{"hanzi":"Regular school attendance is associated with stronger academic performance and better opportunities for social development.","pinyin":"","meaning":"Việc đi học chuyên cần có liên quan mật thiết đến kết quả học tập tốt hơn và nhiều cơ hội phát triển kỹ năng xã hội hơn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_4_2', 'en-b2-4', 'Cách dùng “tuition” (n.) — học phí', 'tuition fees  ·  private tuition  ·  pay tuition', 'Danh từ không đếm được; trong tiếng Anh-Anh, khi nói về tiền học phí thường dùng tuition fees.', NULL, '[{"hanzi":"She works at weekends to help pay her tuition.","pinyin":"","meaning":"Cô ấy đi làm vào các ngày cuối tuần để giúp chi trả học phí của mình."},{"hanzi":"Rising university tuition fees may discourage students from disadvantaged backgrounds from pursuing higher education.","pinyin":"","meaning":"Học phí đại học tăng cao có thể khiến học sinh sinh viên đến từ các gia đình có hoàn cảnh khó khăn nản lòng trong việc theo đuổi giáo dục bậc cao."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_4_3', 'en-b2-4', 'Cách dùng “exceptional” (adj.) — xuất chúng; kiệt xuất; phi thường', 'exceptional ability  ·  exceptional circumstances  ·  exceptional performance', 'Thường chỉ mức độ xuất sắc đặc biệt; exceptional circumstances nghĩa là trường hợp đặc biệt.', 'Họ từ (Word Family): exception (n.), exceptionally (adv.) | Đồng nghĩa: outstanding, extraordinary · Trái nghĩa: ordinary, mediocre', '[{"hanzi":"The young violinist gave an exceptional performance last night.","pinyin":"","meaning":"Nghệ sĩ vĩ cầm trẻ tuổi đã có màn trình diễn xuất sắc vào tối qua."},{"hanzi":"Students with exceptional ability may require additional challenges to remain engaged in classroom learning.","pinyin":"","meaning":"Học sinh có năng lực vượt trội có thể cần những thử thách bổ sung để duy trì sự tập trung trong việc học trên lớp."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_4_4', 'en-b2-4', 'Cách dùng “correction” (n.) — sự sửa chữa; sự hiệu chỉnh', 'make a correction  ·  error correction  ·  minor correction', 'Một chỗ sửa cụ thể là danh từ đếm được; quá trình sửa chữa nói chung thường không đếm được.', 'Họ từ (Word Family): correct (v.), correct (adj.), correctly (adv.), corrective (adj.) | Đồng nghĩa: rectification, amendment', '[{"hanzi":"I made a correction before sending the email.","pinyin":"","meaning":"Tôi đã sửa một lỗi trước khi gửi email."},{"hanzi":"Timely correction of factual errors helps news organizations maintain public trust and prevent misinformation from spreading.","pinyin":"","meaning":"Việc kịp thời sửa chữa các lỗi sai về mặt sự kiện giúp các tổ chức tin tức duy trì lòng tin của công chúng và ngăn chặn sự lan truyền của thông tin sai lệch."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
