INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_4_1_2', 'ten_b2_4_1', 'coursework', 'I finished my coursework before meeting friends for lunch.', 'I finished my coursework before meeting friends for lunch.', '/ˈkɔːrswɝːk/', 'Tôi đã hoàn thành bài tập khóa học trước khi đi ăn trưa với bạn bè.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
