INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_4_1_4', 'ten_b2_4_1', 'Latin', 'My sister studies Latin at school twice a week.', 'My sister studies Latin at school twice a week.', '/ˈlætɪn/', 'Em gái tôi học tiếng La-tinh ở trường hai lần một tuần.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_4_1_5', 'ten_b2_4_1', 'outline', 'I wrote a quick outline before starting my essay.', 'I wrote a quick outline before starting my essay.', '/ˈaʊtlaɪn/', 'Tôi đã viết một bản dàn ý nhanh trước khi bắt tay viết bài luận.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_4_1_6', 'ten_b2_4_1', 'summarize', 'Could you summarize the story before we discuss it?', 'Could you summarize the story before we discuss it?', '/ˈsʌməraɪz/', 'Bạn có thể tóm tắt câu chuyện trước khi chúng ta thảo luận không?', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_4_1_7', 'ten_b2_4_1', 'appendix', 'You''ll find the full recipe in the appendix.', 'You''ll find the full recipe in the appendix.', '/əˈpendɪks/', 'Bạn sẽ tìm thấy công thức đầy đủ ở phần phụ lục.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_4_1_8', 'ten_b2_4_1', 'assess', 'The mechanic assessed the damage before repairing my bicycle.', 'The mechanic assessed the damage before repairing my bicycle.', '/əˈses/', 'Thợ máy đã đánh giá mức độ hư hỏng trước khi sửa chiếc xe đạp cho tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_4_1_1', 'en-b2-4', 'ten_b2_4_1', 'listening', 'listening', 'My sister recited a short poem after dinner.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hướng dẫn viên đã cung cấp cho chúng tôi một cái nhìn tổng quan về chuyến tham quan.","Người hàng xóm song ngữ của chúng tôi nói trôi chảy cả tiếng Anh lẫn tiếng Trung.","Em gái tôi đọc một bài thơ ngắn sau bữa tối.","Thợ máy đã đánh giá mức độ hư hỏng trước khi sửa chiếc xe đạp cho tôi."]'::jsonb, 2, 'My sister recited a short poem after dinner. → Em gái tôi đọc một bài thơ ngắn sau bữa tối.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_4_1_2', 'en-b2-4', 'ten_b2_4_1', 'listening', 'listening', 'I finished my coursework before meeting friends for lunch.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Giáo viên hướng dẫn đã đưa ra những nhận xét hữu ích cho bài luận của tôi.","Chúng tôi rất tận hưởng không gian yên bình tương đối của ngôi làng.","Chúng tôi đã hoàn thành học phần nhiếp ảnh với một dự án ngoài trời.","Tôi đã hoàn thành bài tập khóa học trước khi đi ăn trưa với bạn bè."]'::jsonb, 3, 'I finished my coursework before meeting friends for lunch. → Tôi đã hoàn thành bài tập khóa học trước khi đi ăn trưa với bạn bè.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_4_1_3', 'en-b2-4', 'ten_b2_4_1', 'listening', 'listening', 'We enjoyed the comparative quiet of the village.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Em gái tôi đọc một bài thơ ngắn sau bữa tối.","Triển lãm kết hợp âm nhạc với một số hiệu ứng thị giác tuyệt đẹp.","Tôi đã hoàn thành bài tập khóa học trước khi đi ăn trưa với bạn bè.","Chúng tôi rất tận hưởng không gian yên bình tương đối của ngôi làng."]'::jsonb, 3, 'We enjoyed the comparative quiet of the village. → Chúng tôi rất tận hưởng không gian yên bình tương đối của ngôi làng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_4_2', 'en-b2-4', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_4_2_1', 'ten_b2_4_2', 'recite', 'Students who merely recite facts may struggle to apply their knowledge to unfamiliar problems.', 'Students who merely recite facts may struggle to apply their knowledge to unfamiliar problems.', '/rɪˈsaɪt/', 'Những học sinh chỉ biết học vẹt các sự kiện có thể gặp khó khăn trong việc vận dụng kiến thức vào các vấn đề xa lạ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_4_2_2', 'ten_b2_4_2', 'coursework', 'Assessing students through coursework can provide a broader picture of their abilities than relying solely on examinations.', 'Assessing students through coursework can provide a broader picture of their abilities than relying solely on examinations.', '/ˈkɔːrswɝːk/', 'Việc đánh giá học sinh qua bài tập khóa học có thể mang lại bức tranh toàn diện hơn về năng lực của họ so với việc chỉ dựa vào các kỳ thi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_4_2_3', 'ten_b2_4_2', 'comparative', 'A comparative study of transport systems can help cities identify effective ways to reduce congestion.', 'A comparative study of transport systems can help cities identify effective ways to reduce congestion.', '/kəmˈpærətɪv/', 'Một nghiên cứu so sánh về các hệ thống giao thông có thể giúp các thành phố tìm ra nhữngh hiệu quả để giảm thiểu tình trạng ùn tắc.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_4_2_4', 'ten_b2_4_2', 'Latin', 'Studying Latin can help students understand the origins of scientific terms and the development of European languages.', 'Studying Latin can help students understand the origins of scientific terms and the development of European languages.', '/ˈlætɪn/', 'Việc học tiếng La-tinh có thể giúp học sinh hiểu được nguồn gốc của các thuật ngữ khoa học và sự phát triển của các ngôn ngữ châu Âu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_4_2_5', 'ten_b2_4_2', 'outline', 'The report outlines several practical measures that schools can adopt to support students with learning difficulties.', 'The report outlines several practical measures that schools can adopt to support students with learning difficulties.', '/ˈaʊtlaɪn/', 'Báo cáo phác thảo một số biện pháp thiết thực mà các nhà trường có thể áp dụng để hỗ trợ học sinh gặp khó khăn trong học tập.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_4_2_6', 'ten_b2_4_2', 'summarize', 'Students should learn to summarize research findings accurately rather than reproduce every detail from their sources.', 'Students should learn to summarize research findings accurately rather than reproduce every detail from their sources.', '/ˈsʌməraɪz/', 'Học sinh nên học cách tóm tắt các kết quả nghiên cứu một cách chính xác thay vì lặp lại mọi chi tiết từ nguồn tài liệu của họ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_4_2_1', 'en-b2-4', 'ten_b2_4_2', 'listening', 'listening', 'Students who merely recite facts may struggle to apply their knowledge to unfamiliar problems.', NULL, 'Trong câu vừa nghe, từ “recite” mang nghĩa nào sau đây?', '["cửa hàng; điểm bán lẻ","khoáng vật; khoáng chất","tần suất; số lần","đọc thuộc lòng; ngâm thơ"]'::jsonb, 3, '“recite” (/rɪˈsaɪt/): đọc thuộc lòng; ngâm thơ. Câu đầy đủ: Students who merely recite facts may struggle to apply their knowledge to unfamiliar problems.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_4_2_2', 'en-b2-4', 'ten_b2_4_2', 'listening', 'listening', 'Assessing students through coursework can provide a broader picture of their abilities than relying solely on examinations.', NULL, 'Trong câu vừa nghe, từ “coursework” mang nghĩa nào sau đây?', '["duy trì; giữ gìn","sự áp dụng; sự tiếp nhận","sự theo đuổi; sự mưu cầu","bài tập khóa học; đồ án học phần"]'::jsonb, 3, '“coursework” (/ˈkɔːrswɝːk/): bài tập khóa học; đồ án học phần. Câu đầy đủ: Assessing students through coursework can provide a broader picture of their abilities than relying solely on examinations.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
