INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_4_2', 'en-b2-4', NULL, 'comprehensive_test', 'listening', 'I finished my coursework before meeting friends for lunch.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Em gái tôi học tiếng La-tinh ở trường hai lần một tuần.","Ý tôi chân thực là lạnh chân theo đúng nghĩa đen, không có ẩn ý gì cả.","Tôi đã hoàn thành bài tập khóa học trước khi đi ăn trưa với bạn bè.","Cô ấy dùng hai chiếc lọ để minh họa cho sự khác biệt."]'::jsonb, 2, 'I finished my coursework before meeting friends for lunch. → Tôi đã hoàn thành bài tập khóa học trước khi đi ăn trưa với bạn bè.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_4_3', 'en-b2-4', NULL, 'comprehensive_test', 'listening', 'comparative', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bản ghi nhớ; thông báo nội bộ","cơn khát","mang tính so sánh; đối chiếu","tại cửa hàng; trong cửa hàng (vật lý)"]'::jsonb, 2, 'comparative (/kəmˈpærətɪv/) → mang tính so sánh; đối chiếu; tương đối; từ so sánh (trong ngữ pháp)', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_4_4', 'en-b2-4', NULL, 'comprehensive_test', 'listening', 'My sister studies Latin at school twice a week.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nhờ lặp đi lặp lại hàng ngày, cuối cùng tôi đã ghi nhớ được toàn bộ bài hát.","Ý tôi chân thực là lạnh chân theo đúng nghĩa đen, không có ẩn ý gì cả.","Em gái tôi học tiếng La-tinh ở trường hai lần một tuần.","Chúng tôi rất tận hưởng không gian yên bình tương đối của ngôi làng."]'::jsonb, 2, 'My sister studies Latin at school twice a week. → Em gái tôi học tiếng La-tinh ở trường hai lần một tuần.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_4_5', 'en-b2-4', NULL, 'comprehensive_test', 'listening', 'outline', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thuốc lá; cây thuốc lá","đề cương; dàn ý; bản tóm tắt","tự truyện","một cách hiệu quả; có hiệu quả"]'::jsonb, 1, 'outline (/ˈaʊtlaɪn/) → đề cương; dàn ý; bản tóm tắt; vạch ra; nêu các điểm chính; phác thảo; đường viền; hình dáng bên ngoài', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_4_6', 'en-b2-4', NULL, 'comprehensive_test', 'listening', 'Could you summarize the story before we discuss it?', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hướng dẫn viên đã cung cấp cho chúng tôi một cái nhìn tổng quan về chuyến tham quan.","Cô ấy đi làm vào các ngày cuối tuần để giúp chi trả học phí của mình.","Thợ máy đã đánh giá mức độ hư hỏng trước khi sửa chiếc xe đạp cho tôi.","Bạn có thể tóm tắt câu chuyện trước khi chúng ta thảo luận không?"]'::jsonb, 3, 'Could you summarize the story before we discuss it? → Bạn có thể tóm tắt câu chuyện trước khi chúng ta thảo luận không?', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_4_7', 'en-b2-4', NULL, 'comprehensive_test', 'listening', 'appendix', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự ấm áp; độ ấm","cáp; dây cáp (mang điện hoặc tín hiệu điện tử)","phụ lục (sách, tài liệu)","nhà câu lạc bộ; trụ sở câu lạc bộ"]'::jsonb, 2, 'appendix (/əˈpendɪks/) → phụ lục (sách, tài liệu); ruột thừa', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_4_8', 'en-b2-4', NULL, 'comprehensive_test', 'listening', 'The mechanic assessed the damage before repairing my bicycle.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bạn có thể làm rõ xem chúng ta nên đi lối vào nào không?","Bạn sẽ tìm thấy công thức đầy đủ ở phần phụ lục.","Người hàng xóm song ngữ của chúng tôi nói trôi chảy cả tiếng Anh lẫn tiếng Trung.","Thợ máy đã đánh giá mức độ hư hỏng trước khi sửa chiếc xe đạp cho tôi."]'::jsonb, 3, 'The mechanic assessed the damage before repairing my bicycle. → Thợ máy đã đánh giá mức độ hư hỏng trước khi sửa chiếc xe đạp cho tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_4_9', 'en-b2-4', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a short description covering the main points”?', '["outline","illustrate","recite","linguistics"]'::jsonb, 0, 'outline (/ˈaʊtlaɪn/) → đề cương; dàn ý; bản tóm tắt', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_4_10', 'en-b2-4', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to state the main points briefly”?', '["recite","summarize","assess","literal"]'::jsonb, 1, 'summarize (/ˈsʌməraɪz/) → tóm tắt; khái quát', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_4_11', 'en-b2-4', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “An extra section containing supporting information at a book''s end”?', '["assess","tuition","recite","appendix"]'::jsonb, 3, 'appendix (/əˈpendɪks/) → phụ lục (sách, tài liệu)', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_4_12', 'en-b2-4', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Judge the quality, importance, or condition of something.”?', '["repetition","assess","feedback","bilingual"]'::jsonb, 1, 'assess (/əˈses/) → đánh giá; định giá', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
