INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_4_18', 'en-b2-4', NULL, 'comprehensive_test', 'reading', NULL, 'Students who merely recite facts may struggle to apply their knowledge to unfamiliar problems.', 'Dựa vào câu trên, từ “recite” có nghĩa phù hợp nhất là gì?', '["đọc thuộc lòng; ngâm thơ","thận trọng; cẩn trọng; dè dặt","cách dùng từ; lời lẽ; văn bản","đất sét; đất nung"]'::jsonb, 0, 'recite: đọc thuộc lòng; ngâm thơ; kể lể; liệt kê (chi tiết). Dịch cả câu: Những học sinh chỉ biết học vẹt các sự kiện có thể gặp khó khăn trong việc vận dụng kiến thức vào các vấn đề xa lạ.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_4_19', 'en-b2-4', NULL, 'comprehensive_test', 'reading', NULL, 'Assessing students through coursework can provide a broader picture of their abilities than relying solely on examinations.', 'Dựa vào câu trên, từ “coursework” có nghĩa phù hợp nhất là gì?', '["trái đạo đức; đồi phong bại tục; bất chính","làm phân tâm; làm xao nhãng","linh hoạt; dễ thích ứng","bài tập khóa học; đồ án học phần"]'::jsonb, 3, 'coursework: bài tập khóa học; đồ án học phần. Dịch cả câu: Việc đánh giá học sinh qua bài tập khóa học có thể mang lại bức tranh toàn diện hơn về năng lực của họ so với việc chỉ dựa vào các kỳ thi.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_4_20', 'en-b2-4', NULL, 'comprehensive_test', 'reading', NULL, 'A comparative study of transport systems can help cities identify effective ways to reduce congestion.', 'Dựa vào câu trên, từ “comparative” có nghĩa phù hợp nhất là gì?', '["mang tính so sánh; đối chiếu","bộ (cơ quan chính phủ)","ném nhẹ; vứt","mềm mại, mượt mà, sáng bóng như lụa"]'::jsonb, 0, 'comparative: mang tính so sánh; đối chiếu; tương đối; từ so sánh (trong ngữ pháp). Dịch cả câu: Một nghiên cứu so sánh về các hệ thống giao thông có thể giúp các thành phố tìm ra nhữngh hiệu quả để giảm thiểu tình trạng ùn tắc.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_4_21', 'en-b2-4', NULL, 'comprehensive_test', 'reading', NULL, 'Studying Latin can help students understand the origins of scientific terms and the development of European languages.', 'Dựa vào câu trên, từ “Latin” có nghĩa phù hợp nhất là gì?', '["tiếng La-tinh","kêu lên; thốt lên","mọi người; người (thường chỉ một nhóm cụ thể)","lớn lao; khổng lồ; cực kỳ"]'::jsonb, 0, 'Latin: tiếng La-tinh; thuộc tiếng La-tinh; thuộc thành La-tinh cổ đại; thuộc Mỹ-La-tinh, con người hoặc văn hóa nơi đây. Dịch cả câu: Việc học tiếng La-tinh có thể giúp học sinh hiểu được nguồn gốc của các thuật ngữ khoa học và sự phát triển của các ngôn ngữ châu Âu.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_4_22', 'en-b2-4', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “trường mẫu giáo; lớp mẫu giáo”', '["ally","kindergarten","pitch","sibling"]'::jsonb, 1, 'trường mẫu giáo; lớp mẫu giáo → kindergarten (/ˈkɪndərɡɑːrtən/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
