INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_4_24', 'en-b2-4', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “làm rõ, minh họa (qua ví dụ hoặc bằng chứng)”', '["illustrate","feast","mathematical","rating"]'::jsonb, 0, 'làm rõ, minh họa (qua ví dụ hoặc bằng chứng) → illustrate (/ˈɪləstreɪt/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-5', 'en', 'Bài 5: Du lịch & Di chuyển (1) - CEFR B2', 'CEFR B2', 'B2 · Du lịch', '23 từ vựng Tiếng Anh CEFR B2 chủ đề du lịch & di chuyển kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4005, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stunning', 'en-b2-5', 'stunning', '/ˈstʌnɪŋ/', 'B2', 'tuyệt đẹp; lộng lẫy; gây ấn tượng mạnh; gây kinh ngạc; làm sửng sốt', 'adj.', 'stun (v.), stunned (adj.), stunningly (adv.)', 'Đồng nghĩa: breathtaking, spectacular', 'stunning dùng để miêu tả sự vật gây kinh ngạc/tuyệt đẹp; stunned dùng để miêu tả người bị choáng váng, sững sờ.', 'We enjoyed a stunning view from the hilltop.', NULL, 'Chúng tôi đã ngắm nhìn khung cảnh tuyệt đẹp từ đỉnh đồi.', '{"wordId":"stunning","ukIpa":"/ˈstʌnɪŋ/","usIpa":"/ˈstʌnɪŋ/","cefr":"B2","topic":"travel","senses":[{"pos":"adj.","en":"extremely beautiful or impressive","vi":"tuyệt đẹp; lộng lẫy; gây ấn tượng mạnh"},{"pos":"adj.","en":"causing great surprise or shock","vi":"gây kinh ngạc; làm sửng sốt"}],"examples":[{"en":"We enjoyed a stunning view from the hilltop.","vi":"Chúng tôi đã ngắm nhìn khung cảnh tuyệt đẹp từ đỉnh đồi.","audioKind":"ex"},{"en":"The region''s stunning coastal scenery attracts visitors, but increased tourism places pressure on fragile ecosystems.","vi":"Cảnh quan ven biển tuyệt đẹp của khu vực thu hút du khách, nhưng lượng khách du lịch tăng lên lại gây áp lực cho các hệ sinh thái mong manh.","audioKind":"ex2"}],"collocations":[{"en":"stunning scenery","vi":"phong cảnh tuyệt đẹp"},{"en":"a stunning achievement","vi":"thành tựu đáng kinh ngạc"},{"en":"a stunning victory","vi":"chiến thắng vang dội"},{"en":"look stunning","vi":"trông lộng lẫy"}],"wordFamily":["stun (v.)","stunned (adj.)","stunningly (adv.)"],"synonyms":["breathtaking","spectacular"],"antonyms":[],"tipVi":"stunning dùng để miêu tả sự vật gây kinh ngạc/tuyệt đẹp; stunned dùng để miêu tả người bị choáng váng, sững sờ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_moped', 'en-b2-5', 'moped', '/ˈmoʊped/', 'B2', 'xe gắn máy dung tích nhỏ; xe mốp-pết', 'n.', NULL, NULL, 'Danh từ moped có hai âm tiết; cần phân biệt với moped là dạng quá khứ của động từ mope, phát âm là /məʊpt/.', 'She parked her moped beside the bakery this morning.', NULL, 'Sáng nay cô ấy đã đỗ chiếc xe gắn máy của mình ngay cạnh tiệm bánh.', '{"wordId":"moped","ukIpa":"/ˈməʊped/","usIpa":"/ˈmoʊped/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"A small motorcycle with a low-powered engine, sometimes with pedals","vi":"xe gắn máy dung tích nhỏ; xe mốp-pết"}],"examples":[{"en":"She parked her moped beside the bakery this morning.","vi":"Sáng nay cô ấy đã đỗ chiếc xe gắn máy của mình ngay cạnh tiệm bánh.","audioKind":"ex"},{"en":"A moped can offer affordable transport for short journeys, although riders remain vulnerable on busy urban roads.","vi":"Xe gắn máy có thể là phương tiện đi lại tiết kiệm cho những quãng đường ngắn, mặc dù người điều khiển vẫn dễ gặp nguy hiểm trên các tuyến đường đô thị đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"ride a moped","vi":"lái xe gắn máy"},{"en":"rent a moped","vi":"thuê xe mốp-pết"},{"en":"moped rider","vi":"người lái xe gắn máy"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ moped có hai âm tiết; cần phân biệt với moped là dạng quá khứ của động từ mope, phát âm là /məʊpt/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bunk', 'en-b2-5', 'bunk', '/bʌŋk/', 'B2', 'giường tầng; giường nằm (trên tàu, xe)', 'n.', NULL, 'Đồng nghĩa: berth', 'top bunk là giường tầng trên; bunk bed chỉ giường tầng.', 'I climbed into the top bunk and fell asleep.', NULL, 'Tôi trèo lên giường tầng trên và chìm vào giấc ngủ.', '{"wordId":"bunk","ukIpa":"/bʌŋk/","usIpa":"/bʌŋk/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"A narrow bed, often arranged above or below another.","vi":"giường tầng; giường nằm (trên tàu, xe)"}],"examples":[{"en":"I climbed into the top bunk and fell asleep.","vi":"Tôi trèo lên giường tầng trên và chìm vào giấc ngủ.","audioKind":"ex"},{"en":"Providing each passenger with a comfortable bunk could make overnight trains more attractive than short flights.","vi":"Việc cung cấp cho mỗi hành khách một chiếc giường nằm thoải mái có thể làm cho các chuyến tàu đêm trở nên hấp dẫn hơn so với các chuyến bay ngắn.","audioKind":"ex2"}],"collocations":[{"en":"top bunk","vi":"giường tầng trên"},{"en":"bottom bunk","vi":"giường tầng dưới"},{"en":"bunk bed","vi":"giường tầng"}],"wordFamily":[],"synonyms":["berth"],"antonyms":[],"tipVi":"top bunk là giường tầng trên; bunk bed chỉ giường tầng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_resort', 'en-b2-5', 'resort', '/rɪˈzɔːrt/', 'B2', 'khu nghỉ dưỡng; khu du lịch; phải viện đến; phải dùng đến; biện pháp cuối cùng; phương án cứu vãn', 'n.', NULL, NULL, 'Trong cấu trúc resort to thì to là giới từ, theo sau là danh từ hoặc danh động từ.', 'We stayed at a quiet resort beside the lake.', NULL, 'Chúng tôi ở tại một khu nghỉ dưỡng yên tĩnh nằm bên hồ.', '{"wordId":"resort","ukIpa":"/rɪˈzɔːt/","usIpa":"/rɪˈzɔːrt/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"a place people visit for holidays and leisure","vi":"khu nghỉ dưỡng; khu du lịch"},{"pos":"v.","en":"to use something undesirable because other options have failed","vi":"phải viện đến; phải dùng đến"},{"pos":"n.","en":"an option used when other choices are unavailable","vi":"biện pháp cuối cùng; phương án cứu vãn"}],"examples":[{"en":"We stayed at a quiet resort beside the lake.","vi":"Chúng tôi ở tại một khu nghỉ dưỡng yên tĩnh nằm bên hồ.","audioKind":"ex"},{"en":"Governments should not resort to cutting education budgets when seeking solutions to short-term financial problems.","vi":"Chính phủ không nên viện đến biện pháp cắt giảm ngân sách giáo dục khi tìm cách giải quyết các vấn đề tài chính ngắn hạn.","audioKind":"ex2"}],"collocations":[{"en":"seaside resort","vi":"khu nghỉ dưỡng ven biển"},{"en":"resort to violence","vi":"phải viện đến bạo lực"},{"en":"as a last resort","vi":"như là biện pháp cuối cùng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong cấu trúc resort to thì to là giới từ, theo sau là danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_auto', 'en-b2-5', 'auto', '/ˈɔːtoʊ/', 'B2', 'xe hơi, ô tô (đặc biệt trong tiếng Anh Mỹ)', 'n.', 'automobile (n.)', 'Đồng nghĩa: car, automobile', 'Chủ yếu được dùng trong tiếng Anh Mỹ, thường làm định ngữ, như auto industry.', 'He took his car to an auto repair shop.', NULL, 'Anh ấy đem xe của mình đến tiệm sửa xe.', '{"wordId":"auto","ukIpa":"/ˈɔːtəʊ/","usIpa":"/ˈɔːtoʊ/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"A car, especially in American English","vi":"xe hơi, ô tô (đặc biệt trong tiếng Anh Mỹ)"}],"examples":[{"en":"He took his car to an auto repair shop.","vi":"Anh ấy đem xe của mình đến tiệm sửa xe.","audioKind":"ex"},{"en":"The auto industry faces growing pressure to produce affordable electric vehicles and reduce its environmental impact.","vi":"Ngành công nghiệp ô tô đang đối mặt với áp lực ngày càng lớn trong việc sản xuất các dòng xe điện có giá cả phải chăng và giảm thiểu tác động đến môi trường.","audioKind":"ex2"}],"collocations":[{"en":"auto industry","vi":"ngành công nghiệp ô tô"},{"en":"auto repair shop","vi":"tiệm sửa xe ô tô"},{"en":"auto parts","vi":"phụ tùng ô tô"}],"wordFamily":["automobile (n.)"],"synonyms":["car","automobile"],"antonyms":[],"tipVi":"Chủ yếu được dùng trong tiếng Anh Mỹ, thường làm định ngữ, như auto industry.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mileage', 'en-b2-5', 'mileage', '/ˈmaɪlɪdʒ/', 'B2', 'số dặm đã đi; quãng đường di chuyển; mức tiêu thụ nhiên liệu; hiệu suất nhiên liệu; lợi ích; giá trị sử dụng', 'n.', 'mile (n.)', NULL, 'low mileage chỉ xe chạy ít; good mileage thường chỉ xe tiết kiệm xăng.', 'This used car has surprisingly low mileage for its age.', NULL, 'Chiếc xe đã qua sử dụng này có số dặm đã đi thấp đến bất ngờ so với tuổi đời của nó.', '{"wordId":"mileage","ukIpa":"/ˈmaɪlɪdʒ/","usIpa":"/ˈmaɪlɪdʒ/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"the total distance a vehicle has travelled","vi":"số dặm đã đi; quãng đường di chuyển"},{"pos":"n.","en":"the distance a vehicle travels using a given amount of fuel","vi":"mức tiêu thụ nhiên liệu; hiệu suất nhiên liệu"},{"pos":"n.","en":"the usefulness or advantage gained from something","vi":"lợi ích; giá trị sử dụng"}],"examples":[{"en":"This used car has surprisingly low mileage for its age.","vi":"Chiếc xe đã qua sử dụng này có số dặm đã đi thấp đến bất ngờ so với tuổi đời của nó.","audioKind":"ex"},{"en":"Vehicles with better fuel mileage can lower household transport costs and reduce demand for fossil fuels.","vi":"Những phương tiện có hiệu suất nhiên liệu tốt hơn có thể làm giảm chi phí đi lại của hộ gia đình và hạ thấp nhu cầu về nhiên liệu hóa thạch.","audioKind":"ex2"}],"collocations":[{"en":"low mileage","vi":"số dặm đi được ít"},{"en":"annual mileage","vi":"số dặm đi được hàng năm"},{"en":"fuel mileage","vi":"hiệu suất tiêu thụ nhiên liệu"},{"en":"get mileage out of","vi":"thu được lợi ích từ"}],"wordFamily":["mile (n.)"],"synonyms":[],"antonyms":[],"tipVi":"low mileage chỉ xe chạy ít; good mileage thường chỉ xe tiết kiệm xăng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tow', 'en-b2-5', 'tow', '/toʊ/', 'B2', 'kéo; cẩu (xe cộ, tàu thuyền); sự kéo; sự lai dắt', 'v.', 'towing (n.), towbar (n.)', 'Đồng nghĩa: pull, haul', 'Nhấn mạnh việc kéo xe cộ hoặc tàu thuyền; cụm tow away thường chỉ hành động cẩu xe đỗ sai quy định đi nơi khác.', 'A truck towed our broken car to the garage.', NULL, 'Một chiếc xe tải đã kéo chiếc ô tô hỏng của chúng tôi về xưởng sửa chữa.', '{"wordId":"tow","ukIpa":"/təʊ/","usIpa":"/toʊ/","cefr":"B2","topic":"travel","senses":[{"pos":"v.","en":"To pull a vehicle or boat using another vehicle.","vi":"kéo; cẩu (xe cộ, tàu thuyền)"},{"pos":"n.","en":"The act of pulling a vehicle or boat.","vi":"sự kéo; sự lai dắt"}],"examples":[{"en":"A truck towed our broken car to the garage.","vi":"Một chiếc xe tải đã kéo chiếc ô tô hỏng của chúng tôi về xưởng sửa chữa.","audioKind":"ex"},{"en":"Local authorities may tow illegally parked vehicles to keep emergency access routes clear in crowded urban areas.","vi":"Các cơ quan chức năng có thể cẩu các phương tiện đỗ sai quy định đi để đảm bảo các tuyến đường cứu hộ luôn thông thoáng tại các khu đô thị đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"tow a car","vi":"kéo xe ô tô"},{"en":"tow truck","vi":"xe cẩu kéo"},{"en":"take in tow","vi":"lai dắt đi"},{"en":"give someone a tow","vi":"hỗ trợ kéo xe giúp ai đó"}],"wordFamily":["towing (n.)","towbar (n.)"],"synonyms":["pull","haul"],"antonyms":[],"tipVi":"Nhấn mạnh việc kéo xe cộ hoặc tàu thuyền; cụm tow away thường chỉ hành động cẩu xe đỗ sai quy định đi nơi khác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_carrier', 'en-b2-5', 'carrier', '/ˈkæriər/', 'B2', 'hãng vận chuyển; công ty vận tải; người mang mầm bệnh; vật trung gian truyền bệnh; vật dụng mang theo; túi đựng', 'n.', 'carry (v.)', NULL, 'Trong y học, carrier có thể không có triệu chứng nhưng vẫn mang mầm bệnh.', 'The carrier delivered our new sofa this morning.', NULL, 'Hãng vận chuyển đã giao chiếc ghế sofa mới cho chúng tôi sáng nay.', '{"wordId":"carrier","ukIpa":"/ˈkæriə/","usIpa":"/ˈkæriər/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"a company or person that transports people or goods","vi":"hãng vận chuyển; công ty vận tải"},{"pos":"n.","en":"a person or animal that carries and may spread disease","vi":"người mang mầm bệnh; vật trung gian truyền bệnh"},{"pos":"n.","en":"an object designed to hold something while it is carried","vi":"vật dụng mang theo; túi đựng"}],"examples":[{"en":"The carrier delivered our new sofa this morning.","vi":"Hãng vận chuyển đã giao chiếc ghế sofa mới cho chúng tôi sáng nay.","audioKind":"ex"},{"en":"People can be carriers of certain infections without symptoms, making effective disease prevention more challenging.","vi":"Con người có thể là vật mang một số bệnh nhiễm trùng mà không có triệu chứng, điều này khiến cho công tác phòng chống dịch bệnh hiệu quả trở nên thách thức hơn.","audioKind":"ex2"}],"collocations":[{"en":"air carrier","vi":"hãng hàng không"},{"en":"disease carrier","vi":"người truyền bệnh"},{"en":"baby carrier","vi":"đai địu em bé"},{"en":"pet carrier","vi":"lồng vận chuyển thú cưng"}],"wordFamily":["carry (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong y học, carrier có thể không có triệu chứng nhưng vẫn mang mầm bệnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_overtake', 'en-b2-5', 'overtake', '/ˌoʊvərˈteɪk/', 'B2', 'vượt qua; vượt xe; vượt trội; vượt qua về thành tích; bất ngờ ập đến; chiếm hữu', 'v.', NULL, 'Đồng nghĩa: pass, outstrip · Trái nghĩa: fall behind', 'Dạng quá khứ là overtook, quá khứ phân từ là overtaken.', 'We waited for a safe gap to overtake the tractor.', NULL, 'Chúng tôi đợi khoảng trống an toàn để vượt qua chiếc máy kéo.', '{"wordId":"overtake","ukIpa":"/ˌəʊvəˈteɪk/","usIpa":"/ˌoʊvərˈteɪk/","cefr":"B2","topic":"travel","senses":[{"pos":"v.","en":"To catch up with and move ahead of someone.","vi":"vượt qua; vượt xe"},{"pos":"v.","en":"To become greater or more successful than someone or something.","vi":"vượt trội; vượt qua về thành tích"},{"pos":"v.","en":"To affect someone suddenly and strongly.","vi":"bất ngờ ập đến; chiếm hữu"}],"examples":[{"en":"We waited for a safe gap to overtake the tractor.","vi":"Chúng tôi đợi khoảng trống an toàn để vượt qua chiếc máy kéo.","audioKind":"ex"},{"en":"Renewable energy could overtake fossil fuels as the main source of electricity in some countries.","vi":"Năng lượng tái tạo có thể vượt qua nhiên liệu hóa thạch để trở thành nguồn cung cấp điện chính ở một số quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"overtake a vehicle","vi":"vượt qua một phương tiện"},{"en":"overtake a rival","vi":"vượt qua đối thủ"},{"en":"be overtaken by events","vi":"bị diễn biến thời thế làm cho lỗi thời"}],"wordFamily":[],"synonyms":["pass","outstrip"],"antonyms":["fall behind"],"tipVi":"Dạng quá khứ là overtook, quá khứ phân từ là overtaken.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_eastward', 'en-b2-5', 'eastward', '/ˈiːstwərd/', 'B2', 'hướng đông; về hướng đông; hướng về phía đông', 'adv.', 'east (n.), eastern (adj.), eastwards (adv.)', 'Đồng nghĩa: eastwards · Trái nghĩa: westward', 'eastwards cũng có thể dùng làm phó từ; dùng eastward khi làm tính từ.', 'We drove eastward until the morning sun warmed our faces.', NULL, 'Chúng tôi lái xe hướng về phía đông cho đến khi ánh nắng ban mai sưởi ấm khuôn mặt mình.', '{"wordId":"eastward","ukIpa":"/ˈiːstwəd/","usIpa":"/ˈiːstwərd/","cefr":"B2","topic":"travel","senses":[{"pos":"adv.","en":"Towards the east.","vi":"hướng đông; về hướng đông"},{"pos":"adj.","en":"Moving, facing, or directed towards the east.","vi":"hướng về phía đông"}],"examples":[{"en":"We drove eastward until the morning sun warmed our faces.","vi":"Chúng tôi lái xe hướng về phía đông cho đến khi ánh nắng ban mai sưởi ấm khuôn mặt mình.","audioKind":"ex"},{"en":"The city''s eastward expansion has increased demand for public transport and placed pressure on surrounding farmland.","vi":"Sự mở rộng về phía đông của thành phố đã làm gia tăng nhu cầu giao thông công cộng và gây áp lực lên đất nông nghiệp xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"move eastward","vi":"di chuyển về hướng đông"},{"en":"travel eastward","vi":"hành trình hướng về phía đông"},{"en":"eastward expansion","vi":"sự mở rộng về hướng đông"}],"wordFamily":["east (n.)","eastern (adj.)","eastwards (adv.)"],"synonyms":["eastwards"],"antonyms":["westward"],"tipVi":"eastwards cũng có thể dùng làm phó từ; dùng eastward khi làm tính từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pickpocket', 'en-b2-5', 'pickpocket', '/ˈpɪkpɑːkɪt/', 'B2', 'kẻ móc túi; tên trộm vặt nơi công cộng', 'n.', 'pickpocketing (n.)', 'Đồng nghĩa: thief', 'Từ này chỉ rõ hành vi ăn trộm từ túi áo quần hoặc túi xách, cụ thể hơn từ thief.', 'A pickpocket took her wallet on the crowded bus.', NULL, 'Một tên móc túi đã lấy trộm ví của cô ấy trên chuyến xe buýt đông đúc.', '{"wordId":"pickpocket","ukIpa":"/ˈpɪkpɒkɪt/","usIpa":"/ˈpɪkpɑːkɪt/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"Someone who steals from people''s pockets or bags in public.","vi":"kẻ móc túi; tên trộm vặt nơi công cộng"}],"examples":[{"en":"A pickpocket took her wallet on the crowded bus.","vi":"Một tên móc túi đã lấy trộm ví của cô ấy trên chuyến xe buýt đông đúc.","audioKind":"ex"},{"en":"Tourists can reduce their risk of encountering pickpockets by keeping valuables secure in crowded public spaces.","vi":"Du khách có thể giảm nguy cơ bị móc túi bằng cách cất giữ cẩn thận các vật có giá trị ở những nơi công cộng đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"watch out for pickpockets","vi":"đề phòng móc túi"},{"en":"a gang of pickpockets","vi":"một băng nhóm móc túi"},{"en":"catch a pickpocket","vi":"bắt quả tang kẻ móc túi"}],"wordFamily":["pickpocketing (n.)"],"synonyms":["thief"],"antonyms":[],"tipVi":"Từ này chỉ rõ hành vi ăn trộm từ túi áo quần hoặc túi xách, cụ thể hơn từ thief.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_trek', 'en-b2-5', 'trek', '/trek/', 'B2', 'chuyến đi bộ đường dài gian khổ; đi bộ đường dài; vượt dốc gian khổ', 'n.', 'trekker (n.), trekking (n.)', 'Đồng nghĩa: hike', 'Ngày nay thường chỉ việc đi bộ gian khổ; trekked và trekking đều phải gấp đôi chữ k.', 'Our trek through the forest ended beside a waterfall.', NULL, 'Hành trình đi bộ xuyên rừng của chúng tôi kết thúc bên cạnh một ngọn thác.', '{"wordId":"trek","ukIpa":"/trek/","usIpa":"/trek/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"a long, difficult journey on foot","vi":"chuyến đi bộ đường dài gian khổ"},{"pos":"v.","en":"to walk a long distance, often across difficult terrain","vi":"đi bộ đường dài; vượt dốc gian khổ"}],"examples":[{"en":"Our trek through the forest ended beside a waterfall.","vi":"Hành trình đi bộ xuyên rừng của chúng tôi kết thúc bên cạnh một ngọn thác.","audioKind":"ex"},{"en":"Visitors who trek through remote mountain regions can support local economies by hiring guides and purchasing local supplies.","vi":"Du khách đi bộ qua các vùng núi hiểm trở có thể hỗ trợ nền kinh tế địa phương bằng cách thuê hướng dẫn viên và mua nhu yếu phẩm tại chỗ.","audioKind":"ex2"}],"collocations":[{"en":"a mountain trek","vi":"chuyến leo núi đường dài"},{"en":"trek through the forest","vi":"đi bộ xuyên rừng"},{"en":"go on a trek","vi":"đi trek đường dài"}],"wordFamily":["trekker (n.)","trekking (n.)"],"synonyms":["hike"],"antonyms":[],"tipVi":"Ngày nay thường chỉ việc đi bộ gian khổ; trekked và trekking đều phải gấp đôi chữ k.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wander', 'en-b2-5', 'wander', '/ˈwɑːndər/', 'B2', 'đi lang thang; lang thang không có mục đích cố định; suy nghĩ lan man; xao nhãng khỏi chủ đề chính', 'v.', 'wanderer (n.), wandering (adj.)', 'Đồng nghĩa: roam, ramble', 'wander có nghĩa là đi lang thang; cần phân biệt với từ wonder có nghĩa là tự hỏi, chú ý kỹ chính tả.', 'We wandered through the market and bought some peaches.', NULL, 'Chúng tôi đi lang thang qua khu chợ và mua vài quả đào.', '{"wordId":"wander","ukIpa":"/ˈwɒndə/","usIpa":"/ˈwɑːndər/","cefr":"B2","topic":"travel","senses":[{"pos":"v.","en":"to move around without a fixed route or purpose","vi":"đi lang thang; lang thang không có mục đích cố định"},{"pos":"v.","en":"to stop concentrating or move away from the main subject","vi":"suy nghĩ lan man; xao nhãng khỏi chủ đề chính"}],"examples":[{"en":"We wandered through the market and bought some peaches.","vi":"Chúng tôi đi lang thang qua khu chợ và mua vài quả đào.","audioKind":"ex"},{"en":"Visitors who wander beyond popular tourist areas often discover local businesses that benefit from additional spending.","vi":"Những du khách tản bộ vượt ra ngoài các khu du lịch phổ biến thường khám phá ra các hàng quán địa phương được hưởng lợi từ nguồn chi tiêu thêm.","audioKind":"ex2"}],"collocations":[{"en":"wander around","vi":"lang thang quanh quẩn"},{"en":"wander off","vi":"đi lạc; bỏ đi"},{"en":"let your mind wander","vi":"để tâm trí lang thang"},{"en":"wander off the subject","vi":"lạc đề"}],"wordFamily":["wanderer (n.)","wandering (adj.)"],"synonyms":["roam","ramble"],"antonyms":[],"tipVi":"wander có nghĩa là đi lang thang; cần phân biệt với từ wonder có nghĩa là tự hỏi, chú ý kỹ chính tả.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_brake', 'en-b2-5', 'brake', '/breɪk/', 'B2', 'phanh; thắng; thiết bị hãm; phanh lại; đạp phanh; hãm phanh', 'n.', 'braking (n.)', NULL, 'brake là phanh xe; từ đồng âm break có nghĩa là làm vỡ hoặc nghỉ ngơi.', 'I squeezed the brakes as my bicycle reached the corner.', NULL, 'Tôi bóp chặt phanh khi chiếc xe đạp của mình đi đến khúc cua.', '{"wordId":"brake","ukIpa":"/breɪk/","usIpa":"/breɪk/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"a device that slows or stops a moving vehicle","vi":"phanh; thắng; thiết bị hãm"},{"pos":"v.","en":"to slow or stop a vehicle using its brakes","vi":"phanh lại; đạp phanh; hãm phanh"}],"examples":[{"en":"I squeezed the brakes as my bicycle reached the corner.","vi":"Tôi bóp chặt phanh khi chiếc xe đạp của mình đi đến khúc cua.","audioKind":"ex"},{"en":"Drivers should brake gently on wet roads to reduce the risk of losing control.","vi":"Người lái xe nên đạp phanh nhẹ nhàng trên đường ướt để giảm nguy cơ mất lái.","audioKind":"ex2"}],"collocations":[{"en":"apply the brakes","vi":"đạp phanh; áp dụng phanh"},{"en":"brake sharply","vi":"phanh gấp; thắng gấp"},{"en":"brake pedal","vi":"bàn đạp phanh"},{"en":"emergency brake","vi":"phanh khẩn cấp"}],"wordFamily":["braking (n.)"],"synonyms":[],"antonyms":[],"tipVi":"brake là phanh xe; từ đồng âm break có nghĩa là làm vỡ hoặc nghỉ ngơi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_toll', 'en-b2-5', 'toll', '/toʊl/', 'B2', 'phí cầu đường; lệ phí qua đường; tổn thất; số lượng thương vong; rung chuông chậm và đều', 'n.', NULL, NULL, 'Cụm từ take a toll on mang nghĩa gây ra thiệt hại hoặc tổn thất; death toll dùng để chỉ số người chết.', 'We paid a toll before driving across the bridge.', NULL, 'Chúng tôi đã trả phí cầu đường trước khi lái xe qua cầu.', '{"wordId":"toll","ukIpa":"/təʊl/","usIpa":"/toʊl/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"money paid to use a road or bridge","vi":"phí cầu đường; lệ phí qua đường"},{"pos":"n.","en":"the number harmed, or damage caused by something","vi":"tổn thất; số lượng thương vong"},{"pos":"v.","en":"to ring a large bell slowly and repeatedly","vi":"rung chuông chậm và đều"}],"examples":[{"en":"We paid a toll before driving across the bridge.","vi":"Chúng tôi đã trả phí cầu đường trước khi lái xe qua cầu.","audioKind":"ex"},{"en":"Long working hours can take a heavy toll on employees'' physical health and family relationships.","vi":"Thời gian làm việc kéo dài có thể gây ra những tổn thất nặng nề cho sức khỏe thể chất và các mối quan hệ gia đình của nhân viên.","audioKind":"ex2"}],"collocations":[{"en":"pay a toll","vi":"trả phí qua đường"},{"en":"death toll","vi":"số lượng người tử vong"},{"en":"take a toll on","vi":"gây tổn thất nặng nề cho"},{"en":"a bell tolls","vi":"tiếng chuông ngân vang"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ take a toll on mang nghĩa gây ra thiệt hại hoặc tổn thất; death toll dùng để chỉ số người chết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_remote', 'en-b2-5', 'remote', '/rɪˈmoʊt/', 'B2', 'hẻo lánh; xa xôi; từ xa; rất ít; mong manh', 'adj.', 'remotely (adv.), remoteness (n.)', 'Đồng nghĩa: distant, isolated · Trái nghĩa: nearby', 'Remote cũng có thể đóng vai trò là danh từ, trong văn nói thường chỉ chiếc điều khiển từ xa.', 'They live in a remote village surrounded by mountains.', NULL, 'Họ sống trong một ngôi làng hẻo lánh được bao bọc bởi núi non.', '{"wordId":"remote","ukIpa":"/rɪˈməʊt/","usIpa":"/rɪˈmoʊt/","cefr":"B2","topic":"travel","senses":[{"pos":"adj.","en":"Far away from towns, cities, or other people.","vi":"hẻo lánh; xa xôi"},{"pos":"adj.","en":"Done or controlled from a different location.","vi":"từ xa"},{"pos":"adj.","en":"Very unlikely to happen.","vi":"rất ít; mong manh"}],"examples":[{"en":"They live in a remote village surrounded by mountains.","vi":"Họ sống trong một ngôi làng hẻo lánh được bao bọc bởi núi non.","audioKind":"ex"},{"en":"Remote working can expand employment opportunities for people who live far from major urban centres.","vi":"Làm việc từ xa có thể mở rộng cơ hội việc làm cho những người sống xa các trung tâm đô thị lớn.","audioKind":"ex2"}],"collocations":[{"en":"remote village","vi":"làng hẻo lánh"},{"en":"remote working","vi":"làm việc từ xa"},{"en":"remote control","vi":"điều khiển từ xa"},{"en":"remote possibility","vi":"khả năng rất nhỏ"}],"wordFamily":["remotely (adv.)","remoteness (n.)"],"synonyms":["distant","isolated"],"antonyms":["nearby"],"tipVi":"Remote cũng có thể đóng vai trò là danh từ, trong văn nói thường chỉ chiếc điều khiển từ xa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_terminal', 'en-b2-5', 'terminal', '/ˈtɝːmɪnəl/', 'B2', 'nhà ga hành khách; bến cuối; giai đoạn cuối; nan y (bệnh không thể chữa khỏi); thiết bị đầu cuối (máy tính)', 'n.', 'terminate (v.), termination (n.), terminally (adv.)', NULL, 'terminal illness chỉ căn bệnh hiểm nghèo không thể chữa trị.', 'Our bus stopped outside the airport terminal before sunrise.', NULL, 'Xe buýt của chúng tôi dừng lại ngay bên ngoài nhà ga sân bay trước khi mặt trời mọc.', '{"wordId":"terminal","ukIpa":"/ˈtɜːmɪnəl/","usIpa":"/ˈtɝːmɪnəl/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"A building or station where passengers begin or end journeys.","vi":"nhà ga hành khách; bến cuối"},{"pos":"adj.","en":"Describing an illness that cannot be cured and causes death.","vi":"giai đoạn cuối; nan y (bệnh không thể chữa khỏi)"},{"pos":"n.","en":"Equipment used to access and interact with a computer system.","vi":"thiết bị đầu cuối (máy tính)"}],"examples":[{"en":"Our bus stopped outside the airport terminal before sunrise.","vi":"Xe buýt của chúng tôi dừng lại ngay bên ngoài nhà ga sân bay trước khi mặt trời mọc.","audioKind":"ex"},{"en":"A new passenger terminal could ease overcrowding, but its construction may disrupt nearby communities.","vi":"Một nhà ga hành khách mới có thể làm giảm tình trạng quá tải, nhưng việc xây dựng nó có thể gây ảnh hưởng đến các khu dân cư lân cận.","audioKind":"ex2"}],"collocations":[{"en":"airport terminal","vi":"nhà ga sân bay"},{"en":"terminal illness","vi":"căn bệnh nan y"},{"en":"computer terminal","vi":"thiết bị đầu cuối máy tính"}],"wordFamily":["terminate (v.)","termination (n.)","terminally (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"terminal illness chỉ căn bệnh hiểm nghèo không thể chữa trị.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_arabian', 'en-b2-5', 'Arabian', '/əˈreɪbiən/', 'B2', 'thuộc về bán đảo Ả Rập; ngựa Ả Rập', 'adj.', 'Arab (n.), Arabic (n.)', NULL, 'Arabian thường chỉ bán đảo hoặc giống ngựa; tiếng nói/ngôn ngữ dùng Arabic, chỉ con người thường dùng Arab.', 'We admired the Arabian horses trotting across the sandy field.', NULL, 'Chúng tôi trầm trồ ngắm nhìn những chú ngựa Ả Rập đang phi nước đại trên bãi đất cát.', '{"wordId":"arabian","ukIpa":"/əˈreɪbiən/","usIpa":"/əˈreɪbiən/","cefr":"B2","topic":"travel","senses":[{"pos":"adj.","en":"Relating to Arabia, especially its geography, culture, or wildlife.","vi":"thuộc về bán đảo Ả Rập"},{"pos":"n.","en":"A horse of a breed originally developed in Arabia.","vi":"ngựa Ả Rập"}],"examples":[{"en":"We admired the Arabian horses trotting across the sandy field.","vi":"Chúng tôi trầm trồ ngắm nhìn những chú ngựa Ả Rập đang phi nước đại trên bãi đất cát.","audioKind":"ex"},{"en":"The Arabian Peninsula faces significant water shortages, encouraging investment in desalination technology and more efficient irrigation.","vi":"Bán đảo Ả Rập đang đối mặt với tình trạng thiếu nước nghiêm trọng, thúc đẩy đầu tư vào công nghệ khử mặn và hệ thống tưới tiêu hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"Arabian Peninsula","vi":"Bán đảo Ả Rập"},{"en":"Arabian horse","vi":"ngựa Ả Rập"},{"en":"Arabian Sea","vi":"Biển Ả Rập"}],"wordFamily":["Arab (n.)","Arabic (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Arabian thường chỉ bán đảo hoặc giống ngựa; tiếng nói/ngôn ngữ dùng Arabic, chỉ con người thường dùng Arab.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_puncture', 'en-b2-5', 'puncture', '/ˈpʌŋktʃər/', 'B2', 'lỗ thủng; vết thủng lốp; làm thủng; làm xì lốp', 'n.', NULL, NULL, 'Tiếng Anh-Anh dùng get a puncture; tiếng Anh-Mỹ thường dùng get a flat.', 'A puncture in my bicycle tyre made me late.', NULL, 'Vết thủng trên lốp xe đạp đã làm tôi bị muộn giờ.', '{"wordId":"puncture","ukIpa":"/ˈpʌŋktʃə/","usIpa":"/ˈpʌŋktʃər/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"A small hole made by a sharp object, especially in tyres.","vi":"lỗ thủng; vết thủng lốp"},{"pos":"v.","en":"Make a small hole in something with a sharp object.","vi":"làm thủng; làm xì lốp"}],"examples":[{"en":"A puncture in my bicycle tyre made me late.","vi":"Vết thủng trên lốp xe đạp đã làm tôi bị muộn giờ.","audioKind":"ex"},{"en":"Sharp debris on poorly maintained cycle lanes can puncture tyres and discourage residents from cycling to work.","vi":"Mảnh vỡ sắc nhọn trên các làn đường dành cho xe đạp kém bảo trì có thể làm thủng lốp và khiến người dân nản lòng không muốn đạp xe đi làm.","audioKind":"ex2"}],"collocations":[{"en":"repair a puncture","vi":"vá lốp thủng"},{"en":"get a puncture","vi":"bị thủng lốp"},{"en":"puncture a tyre","vi":"làm thủng lốp xe"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tiếng Anh-Anh dùng get a puncture; tiếng Anh-Mỹ thường dùng get a flat.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_yacht', 'en-b2-5', 'yacht', '/jɑːt/', 'B2', 'du thuyền; thuyền buồm', 'n.', 'yachting (n.)', NULL, 'ch không phát âm; thường chỉ dùng cho thuyền đi chơi hoặc thi đấu.', 'We watched a white yacht sail across the bay.', NULL, 'Chúng tôi ngắm nhìn một chiếc du thuyền màu trắng lướt qua vịnh.', '{"wordId":"yacht","ukIpa":"/jɒt/","usIpa":"/jɑːt/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"A boat used for pleasure trips or racing.","vi":"du thuyền; thuyền buồm"}],"examples":[{"en":"We watched a white yacht sail across the bay.","vi":"Chúng tôi ngắm nhìn một chiếc du thuyền màu trắng lướt qua vịnh.","audioKind":"ex"},{"en":"The growing popularity of yacht tourism can generate income for coastal communities but may damage marine habitats.","vi":"Sự phổ biến ngày càng tăng của du lịch du thuyền có thể tạo ra thu nhập cho các cộng đồng ven biển nhưng cũng có thể làm tổn hại đến môi trường sống dưới lòng đại dương.","audioKind":"ex2"}],"collocations":[{"en":"sailing yacht","vi":"thuyền buồm"},{"en":"luxury yacht","vi":"du thuyền sang trọng"},{"en":"yacht racing","vi":"đua thuyền buồm"}],"wordFamily":["yachting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"ch không phát âm; thường chỉ dùng cho thuyền đi chơi hoặc thi đấu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aisle', 'en-b2-5', 'aisle', '/aɪl/', 'B2', 'lối đi (giữa các hàng ghế hoặc kệ hàng)', 'n.', NULL, 'Đồng nghĩa: passage, walkway', 'Chữ s không phát âm, phát âm giống từ isle; aisle seat là ghế ngồi gần lối đi.', 'Please keep your bag out of the aisle.', NULL, 'Xin vui lòng để túi xách của bạn ra khỏi lối đi.', '{"wordId":"aisle","ukIpa":"/aɪl/","usIpa":"/aɪl/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"a passage between rows of seats or shelves","vi":"lối đi (giữa các hàng ghế hoặc kệ hàng)"}],"examples":[{"en":"Please keep your bag out of the aisle.","vi":"Xin vui lòng để túi xách của bạn ra khỏi lối đi.","audioKind":"ex"},{"en":"Wider supermarket aisles can improve accessibility for wheelchair users and make shopping more comfortable for everyone.","vi":"Lối đi siêu thị rộng hơn có thể cải thiện khả năng tiếp cận cho người dùng xe lăn và giúp việc mua sắm trở nên thoải mái hơn cho mọi người.","audioKind":"ex2"}],"collocations":[{"en":"aisle seat","vi":"ghế ngồi gần lối đi"},{"en":"supermarket aisle","vi":"lối đi giữa các kệ siêu thị"},{"en":"walk down the aisle","vi":"đi dọc lối đi; kết hôn"}],"wordFamily":[],"synonyms":["passage","walkway"],"antonyms":[],"tipVi":"Chữ s không phát âm, phát âm giống từ isle; aisle seat là ghế ngồi gần lối đi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_southward', 'en-b2-5', 'southward', '/ˈsaʊθwərd/', 'B2', 'về phía nam; hướng về phía nam', 'adv.', 'south (n.), southern (adj.), southwards (adv.)', 'Đồng nghĩa: southwards · Trái nghĩa: northward', 'southward vừa làm tính từ vừa làm trạng từ; southwards chỉ dùng làm trạng từ.', 'We drove southward until we reached the coast.', NULL, 'Chúng tôi lái xe về phía nam cho đến khi đến bờ biển.', '{"wordId":"southward","ukIpa":"/ˈsaʊθwəd/","usIpa":"/ˈsaʊθwərd/","cefr":"B2","topic":"travel","senses":[{"pos":"adv.","en":"towards the south","vi":"về phía nam"},{"pos":"adj.","en":"moving or pointing towards the south","vi":"hướng về phía nam"}],"examples":[{"en":"We drove southward until we reached the coast.","vi":"Chúng tôi lái xe về phía nam cho đến khi đến bờ biển.","audioKind":"ex"},{"en":"The southward movement of some marine species may reflect changes in ocean temperatures and food availability.","vi":"Sự di chuyển về phía nam của một số loài sinh vật biển có thể phản ánh sự thay đổi nhiệt độ đại dương và nguồn thức ăn.","audioKind":"ex2"}],"collocations":[{"en":"move southward","vi":"di chuyển về phía nam"},{"en":"southward migration","vi":"sự di cư về hướng nam"},{"en":"southward journey","vi":"hành trình về phía nam"}],"wordFamily":["south (n.)","southern (adj.)","southwards (adv.)"],"synonyms":["southwards"],"antonyms":["northward"],"tipVi":"southward vừa làm tính từ vừa làm trạng từ; southwards chỉ dùng làm trạng từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_suite', 'en-b2-5', 'suite', '/swiːt/', 'B2', 'phòng suite (phòng khách sạn gồm nhiều phòng thông nhau); phòng thượng hạng; bộ phần mềm; bộ đồ đạc (nội thất); bản nhạc giao hưởng (gồm nhiều chương liên quan đến nhau)', 'n.', NULL, NULL, 'Phát âm giống từ sweet; từ suit có nghĩa là bộ com-lê và phát âm khác.', 'Our hotel suite has a balcony overlooking the sea.', NULL, 'Phòng suite của khách sạn chúng tôi có ban công hướng ra biển.', '{"wordId":"suite","ukIpa":"/swiːt/","usIpa":"/swiːt/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"Connected rooms used together, especially in a hotel","vi":"phòng suite (phòng khách sạn gồm nhiều phòng thông nhau); phòng thượng hạng"},{"pos":"n.","en":"A set of software programs or furniture used together","vi":"bộ phần mềm; bộ đồ đạc (nội thất)"},{"pos":"n.","en":"A musical work consisting of several related pieces","vi":"bản nhạc giao hưởng (gồm nhiều chương liên quan đến nhau)"}],"examples":[{"en":"Our hotel suite has a balcony overlooking the sea.","vi":"Phòng suite của khách sạn chúng tôi có ban công hướng ra biển.","audioKind":"ex"},{"en":"The university provides a software suite that enables students to analyse data and prepare research presentations.","vi":"Trường đại học cung cấp một bộ phần mềm giúp sinh viên phân tích dữ liệu và chuẩn bị bài thuyết trình nghiên cứu.","audioKind":"ex2"}],"collocations":[{"en":"a hotel suite","vi":"phòng suite khách sạn"},{"en":"a software suite","vi":"bộ phần mềm"},{"en":"a three-piece suite","vi":"bộ sofa ba món"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Phát âm giống từ sweet; từ suit có nghĩa là bộ com-lê và phát âm khác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_5_1', 'en-b2-5', 'Cách dùng “stunning” (adj.) — tuyệt đẹp; lộng lẫy; gây ấn tượng mạnh', 'stunning scenery  ·  a stunning achievement  ·  a stunning victory', 'stunning dùng để miêu tả sự vật gây kinh ngạc/tuyệt đẹp; stunned dùng để miêu tả người bị choáng váng, sững sờ.', 'Họ từ (Word Family): stun (v.), stunned (adj.), stunningly (adv.) | Đồng nghĩa: breathtaking, spectacular', '[{"hanzi":"We enjoyed a stunning view from the hilltop.","pinyin":"","meaning":"Chúng tôi đã ngắm nhìn khung cảnh tuyệt đẹp từ đỉnh đồi."},{"hanzi":"The region''s stunning coastal scenery attracts visitors, but increased tourism places pressure on fragile ecosystems.","pinyin":"","meaning":"Cảnh quan ven biển tuyệt đẹp của khu vực thu hút du khách, nhưng lượng khách du lịch tăng lên lại gây áp lực cho các hệ sinh thái mong manh."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_5_2', 'en-b2-5', 'Cách dùng “tow” (v.) — kéo; cẩu (xe cộ, tàu thuyền)', 'tow a car  ·  tow truck  ·  take in tow', 'Nhấn mạnh việc kéo xe cộ hoặc tàu thuyền; cụm tow away thường chỉ hành động cẩu xe đỗ sai quy định đi nơi khác.', 'Họ từ (Word Family): towing (n.), towbar (n.) | Đồng nghĩa: pull, haul', '[{"hanzi":"A truck towed our broken car to the garage.","pinyin":"","meaning":"Một chiếc xe tải đã kéo chiếc ô tô hỏng của chúng tôi về xưởng sửa chữa."},{"hanzi":"Local authorities may tow illegally parked vehicles to keep emergency access routes clear in crowded urban areas.","pinyin":"","meaning":"Các cơ quan chức năng có thể cẩu các phương tiện đỗ sai quy định đi để đảm bảo các tuyến đường cứu hộ luôn thông thoáng tại các khu đô thị đông đúc."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_5_3', 'en-b2-5', 'Cách dùng “moped” (n.) — xe gắn máy dung tích nhỏ; xe mốp-pết', 'ride a moped  ·  rent a moped  ·  moped rider', 'Danh từ moped có hai âm tiết; cần phân biệt với moped là dạng quá khứ của động từ mope, phát âm là /məʊpt/.', NULL, '[{"hanzi":"She parked her moped beside the bakery this morning.","pinyin":"","meaning":"Sáng nay cô ấy đã đỗ chiếc xe gắn máy của mình ngay cạnh tiệm bánh."},{"hanzi":"A moped can offer affordable transport for short journeys, although riders remain vulnerable on busy urban roads.","pinyin":"","meaning":"Xe gắn máy có thể là phương tiện đi lại tiết kiệm cho những quãng đường ngắn, mặc dù người điều khiển vẫn dễ gặp nguy hiểm trên các tuyến đường đô thị đông đúc."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_5_4', 'en-b2-5', 'Cách dùng “Arabian” (adj.) — thuộc về bán đảo Ả Rập', 'Arabian Peninsula  ·  Arabian horse  ·  Arabian Sea', 'Arabian thường chỉ bán đảo hoặc giống ngựa; tiếng nói/ngôn ngữ dùng Arabic, chỉ con người thường dùng Arab.', 'Họ từ (Word Family): Arab (n.), Arabic (n.)', '[{"hanzi":"We admired the Arabian horses trotting across the sandy field.","pinyin":"","meaning":"Chúng tôi trầm trồ ngắm nhìn những chú ngựa Ả Rập đang phi nước đại trên bãi đất cát."},{"hanzi":"The Arabian Peninsula faces significant water shortages, encouraging investment in desalination technology and more efficient irrigation.","pinyin":"","meaning":"Bán đảo Ả Rập đang đối mặt với tình trạng thiếu nước nghiêm trọng, thúc đẩy đầu tư vào công nghệ khử mặn và hệ thống tưới tiêu hiệu quả hơn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_5_1', 'en-b2-5', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_5_1_1', 'ten_b2_5_1', 'stunning', 'We enjoyed a stunning view from the hilltop.', 'We enjoyed a stunning view from the hilltop.', '/ˈstʌnɪŋ/', 'Chúng tôi đã ngắm nhìn khung cảnh tuyệt đẹp từ đỉnh đồi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_5_1_2', 'ten_b2_5_1', 'moped', 'She parked her moped beside the bakery this morning.', 'She parked her moped beside the bakery this morning.', '/ˈmoʊped/', 'Sáng nay cô ấy đã đỗ chiếc xe gắn máy của mình ngay cạnh tiệm bánh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_5_1_3', 'ten_b2_5_1', 'bunk', 'I climbed into the top bunk and fell asleep.', 'I climbed into the top bunk and fell asleep.', '/bʌŋk/', 'Tôi trèo lên giường tầng trên và chìm vào giấc ngủ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_5_1_4', 'ten_b2_5_1', 'resort', 'We stayed at a quiet resort beside the lake.', 'We stayed at a quiet resort beside the lake.', '/rɪˈzɔːrt/', 'Chúng tôi ở tại một khu nghỉ dưỡng yên tĩnh nằm bên hồ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_5_1_5', 'ten_b2_5_1', 'auto', 'He took his car to an auto repair shop.', 'He took his car to an auto repair shop.', '/ˈɔːtoʊ/', 'Anh ấy đem xe của mình đến tiệm sửa xe.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_5_1_6', 'ten_b2_5_1', 'mileage', 'This used car has surprisingly low mileage for its age.', 'This used car has surprisingly low mileage for its age.', '/ˈmaɪlɪdʒ/', 'Chiếc xe đã qua sử dụng này có số dặm đã đi thấp đến bất ngờ so với tuổi đời của nó.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_5_1_7', 'ten_b2_5_1', 'tow', 'A truck towed our broken car to the garage.', 'A truck towed our broken car to the garage.', '/toʊ/', 'Một chiếc xe tải đã kéo chiếc ô tô hỏng của chúng tôi về xưởng sửa chữa.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_5_1_8', 'ten_b2_5_1', 'carrier', 'The carrier delivered our new sofa this morning.', 'The carrier delivered our new sofa this morning.', '/ˈkæriər/', 'Hãng vận chuyển đã giao chiếc ghế sofa mới cho chúng tôi sáng nay.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_5_1_1', 'en-b2-5', 'ten_b2_5_1', 'listening', 'listening', 'We enjoyed a stunning view from the hilltop.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Phòng suite của khách sạn chúng tôi có ban công hướng ra biển.","Chúng tôi đã trả phí cầu đường trước khi lái xe qua cầu.","Xe buýt của chúng tôi dừng lại ngay bên ngoài nhà ga sân bay trước khi mặt trời mọc.","Chúng tôi đã ngắm nhìn khung cảnh tuyệt đẹp từ đỉnh đồi."]'::jsonb, 3, 'We enjoyed a stunning view from the hilltop. → Chúng tôi đã ngắm nhìn khung cảnh tuyệt đẹp từ đỉnh đồi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_5_1_2', 'en-b2-5', 'ten_b2_5_1', 'listening', 'listening', 'She parked her moped beside the bakery this morning.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Xe buýt của chúng tôi dừng lại ngay bên ngoài nhà ga sân bay trước khi mặt trời mọc.","Sáng nay cô ấy đã đỗ chiếc xe gắn máy của mình ngay cạnh tiệm bánh.","Vết thủng trên lốp xe đạp đã làm tôi bị muộn giờ.","Chiếc xe đã qua sử dụng này có số dặm đã đi thấp đến bất ngờ so với tuổi đời của nó."]'::jsonb, 1, 'She parked her moped beside the bakery this morning. → Sáng nay cô ấy đã đỗ chiếc xe gắn máy của mình ngay cạnh tiệm bánh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_5_1_3', 'en-b2-5', 'ten_b2_5_1', 'listening', 'listening', 'I climbed into the top bunk and fell asleep.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi lái xe về phía nam cho đến khi đến bờ biển.","Tôi trèo lên giường tầng trên và chìm vào giấc ngủ.","Chúng tôi đi lang thang qua khu chợ và mua vài quả đào.","Xe buýt của chúng tôi dừng lại ngay bên ngoài nhà ga sân bay trước khi mặt trời mọc."]'::jsonb, 1, 'I climbed into the top bunk and fell asleep. → Tôi trèo lên giường tầng trên và chìm vào giấc ngủ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_5_2', 'en-b2-5', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_5_2_1', 'ten_b2_5_2', 'stunning', 'The region''s stunning coastal scenery attracts visitors, but increased tourism places pressure on fragile ecosystems.', 'The region''s stunning coastal scenery attracts visitors, but increased tourism places pressure on fragile ecosystems.', '/ˈstʌnɪŋ/', 'Cảnh quan ven biển tuyệt đẹp của khu vực thu hút du khách, nhưng lượng khách du lịch tăng lên lại gây áp lực cho các hệ sinh thái mong manh.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_5_2_2', 'ten_b2_5_2', 'moped', 'A moped can offer affordable transport for short journeys, although riders remain vulnerable on busy urban roads.', 'A moped can offer affordable transport for short journeys, although riders remain vulnerable on busy urban roads.', '/ˈmoʊped/', 'Xe gắn máy có thể là phương tiện đi lại tiết kiệm cho những quãng đường ngắn, mặc dù người điều khiển vẫn dễ gặp nguy hiểm trên các tuyến đường đô thị đông đúc.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_5_2_3', 'ten_b2_5_2', 'bunk', 'Providing each passenger with a comfortable bunk could make overnight trains more attractive than short flights.', 'Providing each passenger with a comfortable bunk could make overnight trains more attractive than short flights.', '/bʌŋk/', 'Việc cung cấp cho mỗi hành khách một chiếc giường nằm thoải mái có thể làm cho các chuyến tàu đêm trở nên hấp dẫn hơn so với các chuyến bay ngắn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_5_2_4', 'ten_b2_5_2', 'resort', 'Governments should not resort to cutting education budgets when seeking solutions to short-term financial problems.', 'Governments should not resort to cutting education budgets when seeking solutions to short-term financial problems.', '/rɪˈzɔːrt/', 'Chính phủ không nên viện đến biện pháp cắt giảm ngân sách giáo dục khi tìm cách giải quyết các vấn đề tài chính ngắn hạn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_5_2_5', 'ten_b2_5_2', 'auto', 'The auto industry faces growing pressure to produce affordable electric vehicles and reduce its environmental impact.', 'The auto industry faces growing pressure to produce affordable electric vehicles and reduce its environmental impact.', '/ˈɔːtoʊ/', 'Ngành công nghiệp ô tô đang đối mặt với áp lực ngày càng lớn trong việc sản xuất các dòng xe điện có giá cả phải chăng và giảm thiểu tác động đến môi trường.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_5_2_6', 'ten_b2_5_2', 'mileage', 'Vehicles with better fuel mileage can lower household transport costs and reduce demand for fossil fuels.', 'Vehicles with better fuel mileage can lower household transport costs and reduce demand for fossil fuels.', '/ˈmaɪlɪdʒ/', 'Những phương tiện có hiệu suất nhiên liệu tốt hơn có thể làm giảm chi phí đi lại của hộ gia đình và hạ thấp nhu cầu về nhiên liệu hóa thạch.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_5_2_1', 'en-b2-5', 'ten_b2_5_2', 'listening', 'listening', 'The region''s stunning coastal scenery attracts visitors, but increased tourism places pressure on fragile ecosystems.', NULL, 'Trong câu vừa nghe, từ “stunning” mang nghĩa nào sau đây?', '["tuyệt đẹp; lộng lẫy; gây ấn tượng mạnh","mái chèo","sự say mê; niềm hứng thú tột độ","làm việc tự do; thuộc nghề tự do"]'::jsonb, 0, '“stunning” (/ˈstʌnɪŋ/): tuyệt đẹp; lộng lẫy; gây ấn tượng mạnh. Câu đầy đủ: The region''s stunning coastal scenery attracts visitors, but increased tourism places pressure on fragile ecosystems.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_5_2_2', 'en-b2-5', 'ten_b2_5_2', 'listening', 'listening', 'A moped can offer affordable transport for short journeys, although riders remain vulnerable on busy urban roads.', NULL, 'Trong câu vừa nghe, từ “moped” mang nghĩa nào sau đây?', '["bọt","mũi khâu; mũi kim; đường khâu","vương quốc","xe gắn máy dung tích nhỏ; xe mốp-pết"]'::jsonb, 3, '“moped” (/ˈmoʊped/): xe gắn máy dung tích nhỏ; xe mốp-pết. Câu đầy đủ: A moped can offer affordable transport for short journeys, although riders remain vulnerable on busy urban roads.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
