INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_5_1', 'en-b2-5', NULL, 'comprehensive_test', 'listening', 'stunning', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["ban hội thẩm; hội đồng chuyên gia","khả năng xảy ra","tuyệt đẹp; lộng lẫy; gây ấn tượng mạnh","sự không đồng tình; sự phản đối"]'::jsonb, 2, 'stunning (/ˈstʌnɪŋ/) → tuyệt đẹp; lộng lẫy; gây ấn tượng mạnh; gây kinh ngạc; làm sửng sốt', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_5_2', 'en-b2-5', NULL, 'comprehensive_test', 'listening', 'She parked her moped beside the bakery this morning.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi bóp chặt phanh khi chiếc xe đạp của mình đi đến khúc cua.","Hãng vận chuyển đã giao chiếc ghế sofa mới cho chúng tôi sáng nay.","Chúng tôi đi lang thang qua khu chợ và mua vài quả đào.","Sáng nay cô ấy đã đỗ chiếc xe gắn máy của mình ngay cạnh tiệm bánh."]'::jsonb, 3, 'She parked her moped beside the bakery this morning. → Sáng nay cô ấy đã đỗ chiếc xe gắn máy của mình ngay cạnh tiệm bánh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_5_3', 'en-b2-5', NULL, 'comprehensive_test', 'listening', 'bunk', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thỏa thuận dàn xếp; sự hòa giải (kết thúc tranh chấp)","ném nhẹ; vứt","giường tầng; giường nằm (trên tàu, xe)","lo lắng; bận tâm"]'::jsonb, 2, 'bunk (/bʌŋk/) → giường tầng; giường nằm (trên tàu, xe)', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_5_4', 'en-b2-5', NULL, 'comprehensive_test', 'listening', 'We stayed at a quiet resort beside the lake.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đi lang thang qua khu chợ và mua vài quả đào.","Hãng vận chuyển đã giao chiếc ghế sofa mới cho chúng tôi sáng nay.","Chúng tôi ở tại một khu nghỉ dưỡng yên tĩnh nằm bên hồ.","Chúng tôi lái xe hướng về phía đông cho đến khi ánh nắng ban mai sưởi ấm khuôn mặt mình."]'::jsonb, 2, 'We stayed at a quiet resort beside the lake. → Chúng tôi ở tại một khu nghỉ dưỡng yên tĩnh nằm bên hồ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_5_5', 'en-b2-5', NULL, 'comprehensive_test', 'listening', 'auto', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["lá phổi; phổi","xe hơi, ô tô (đặc biệt trong tiếng Anh Mỹ)","di cư; di trú","đồ gốm"]'::jsonb, 1, 'auto (/ˈɔːtoʊ/) → xe hơi, ô tô (đặc biệt trong tiếng Anh Mỹ)', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_5_6', 'en-b2-5', NULL, 'comprehensive_test', 'listening', 'This used car has surprisingly low mileage for its age.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Xe buýt của chúng tôi dừng lại ngay bên ngoài nhà ga sân bay trước khi mặt trời mọc.","Chiếc xe đã qua sử dụng này có số dặm đã đi thấp đến bất ngờ so với tuổi đời của nó.","Một tên móc túi đã lấy trộm ví của cô ấy trên chuyến xe buýt đông đúc.","Chúng tôi ở tại một khu nghỉ dưỡng yên tĩnh nằm bên hồ."]'::jsonb, 1, 'This used car has surprisingly low mileage for its age. → Chiếc xe đã qua sử dụng này có số dặm đã đi thấp đến bất ngờ so với tuổi đời của nó.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
