INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_5_8', 'en-b2-5', NULL, 'comprehensive_test', 'listening', 'The carrier delivered our new sofa this morning.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã trả phí cầu đường trước khi lái xe qua cầu.","Hãng vận chuyển đã giao chiếc ghế sofa mới cho chúng tôi sáng nay.","Tôi bóp chặt phanh khi chiếc xe đạp của mình đi đến khúc cua.","Chúng tôi ngắm nhìn một chiếc du thuyền màu trắng lướt qua vịnh."]'::jsonb, 1, 'The carrier delivered our new sofa this morning. → Hãng vận chuyển đã giao chiếc ghế sofa mới cho chúng tôi sáng nay.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
