INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_5_18', 'en-b2-5', NULL, 'comprehensive_test', 'reading', NULL, 'The region''s stunning coastal scenery attracts visitors, but increased tourism places pressure on fragile ecosystems.', 'Dựa vào câu trên, từ “stunning” có nghĩa phù hợp nhất là gì?', '["hướng ra ngoài; ra phía ngoài","hoạt động giải trí; tiêu khiển","nhà khảo cổ học","tuyệt đẹp; lộng lẫy; gây ấn tượng mạnh"]'::jsonb, 3, 'stunning: tuyệt đẹp; lộng lẫy; gây ấn tượng mạnh; gây kinh ngạc; làm sửng sốt. Dịch cả câu: Cảnh quan ven biển tuyệt đẹp của khu vực thu hút du khách, nhưng lượng khách du lịch tăng lên lại gây áp lực cho các hệ sinh thái mong manh.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_5_19', 'en-b2-5', NULL, 'comprehensive_test', 'reading', NULL, 'A moped can offer affordable transport for short journeys, although riders remain vulnerable on busy urban roads.', 'Dựa vào câu trên, từ “moped” có nghĩa phù hợp nhất là gì?', '["nỗi thống khổ; sự đau buồn; sự lo lắng","xe gắn máy dung tích nhỏ; xe mốp-pết","kinh độ","chuyến du ngoạn trên biển; chuyến đi bằng tàu thủy"]'::jsonb, 1, 'moped: xe gắn máy dung tích nhỏ; xe mốp-pết. Dịch cả câu: Xe gắn máy có thể là phương tiện đi lại tiết kiệm cho những quãng đường ngắn, mặc dù người điều khiển vẫn dễ gặp nguy hiểm trên các tuyến đường đô thị đông đúc.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_5_20', 'en-b2-5', NULL, 'comprehensive_test', 'reading', NULL, 'Providing each passenger with a comfortable bunk could make overnight trains more attractive than short flights.', 'Dựa vào câu trên, từ “bunk” có nghĩa phù hợp nhất là gì?', '["sự cố gắng; nỗ lực","đoàn kết; đồng lòng","giường tầng; giường nằm (trên tàu, xe)","kẻ hèn nhát; đồ nhát gan"]'::jsonb, 2, 'bunk: giường tầng; giường nằm (trên tàu, xe). Dịch cả câu: Việc cung cấp cho mỗi hành khách một chiếc giường nằm thoải mái có thể làm cho các chuyến tàu đêm trở nên hấp dẫn hơn so với các chuyến bay ngắn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_5_21', 'en-b2-5', NULL, 'comprehensive_test', 'reading', NULL, 'Governments should not resort to cutting education budgets when seeking solutions to short-term financial problems.', 'Dựa vào câu trên, từ “resort” có nghĩa phù hợp nhất là gì?', '["chàng trai; cậu thanh niên","sự chuyển đổi; giai đoạn chuyển tiếp","khu nghỉ dưỡng; khu du lịch","người nghiện công việc; người cuồng công việc"]'::jsonb, 2, 'resort: khu nghỉ dưỡng; khu du lịch; phải viện đến; phải dùng đến; biện pháp cuối cùng; phương án cứu vãn. Dịch cả câu: Chính phủ không nên viện đến biện pháp cắt giảm ngân sách giáo dục khi tìm cách giải quyết các vấn đề tài chính ngắn hạn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_5_22', 'en-b2-5', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “lối đi (giữa các hàng ghế hoặc kệ hàng)”', '["aisle","superstitious","gender","burial"]'::jsonb, 0, 'lối đi (giữa các hàng ghế hoặc kệ hàng) → aisle (/aɪl/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_5_23', 'en-b2-5', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “về phía nam”', '["southward","efficiency","hardship","concerned"]'::jsonb, 0, 'về phía nam → southward (/ˈsaʊθwərd/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_5_24', 'en-b2-5', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “phòng suite (phòng khách sạn gồm nhiều phòng thông nhau); phòng thượng hạng”', '["logic","suite","placement","sparkling"]'::jsonb, 1, 'phòng suite (phòng khách sạn gồm nhiều phòng thông nhau); phòng thượng hạng → suite (/swiːt/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-6', 'en', 'Bài 6: Du lịch & Di chuyển (2) - CEFR B2', 'CEFR B2', 'B2 · Du lịch', '22 từ vựng Tiếng Anh CEFR B2 chủ đề du lịch & di chuyển kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4006, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ashore', 'en-b2-6', 'ashore', '/əˈʃɔːr/', 'B2', 'lên bờ; vào bờ', 'adv.', NULL, 'Đồng nghĩa: onshore · Trái nghĩa: offshore', 'ashore là phó từ, không dùng giới từ to trước go ashore.', 'We went ashore to buy fresh bread and fruit.', NULL, 'Chúng tôi đã lên bờ để mua bánh mì và trái cây tươi.', '{"wordId":"ashore","ukIpa":"/əˈʃɔː/","usIpa":"/əˈʃɔːr/","cefr":"B2","topic":"travel","senses":[{"pos":"adv.","en":"onto or on land beside a sea, lake, or river","vi":"lên bờ; vào bờ"}],"examples":[{"en":"We went ashore to buy fresh bread and fruit.","vi":"Chúng tôi đã lên bờ để mua bánh mì và trái cây tươi.","audioKind":"ex"},{"en":"Plastic waste washed ashore can damage coastal ecosystems and reduce the appeal of beaches to tourists.","vi":"Rác thải nhựa trôi dạt vào bờ có thể tàn phá các hệ sinh thái ven biển và làm giảm sự thu hút của các bãi biển đối với khách du lịch.","audioKind":"ex2"}],"collocations":[{"en":"go ashore","vi":"lên bờ"},{"en":"come ashore","vi":"dạt vào bờ"},{"en":"wash ashore","vi":"trôi dạt vào bờ"}],"wordFamily":[],"synonyms":["onshore"],"antonyms":["offshore"],"tipVi":"ashore là phó từ, không dùng giới từ to trước go ashore.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_curve', 'en-b2-6', 'curve', '/kɝːv/', 'B2', 'đường cong; khúc cua; uốn cong; bẻ cong', 'n.', 'curved (adj.), curvature (n.)', 'Đồng nghĩa: bend', 'curve có thể làm danh từ hoặc động từ; "vận dụng tính từ" của nó là curved.', 'The driver slowed down as we approached a sharp curve.', NULL, 'Tài xế giảm tốc độ khi chúng tôi tiến đến một khúc cua gắt.', '{"wordId":"curve","ukIpa":"/kɜːv/","usIpa":"/kɝːv/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"a line or shape that bends smoothly","vi":"đường cong; khúc cua"},{"pos":"v.","en":"to bend smoothly, or make something bend smoothly","vi":"uốn cong; bẻ cong"}],"examples":[{"en":"The driver slowed down as we approached a sharp curve.","vi":"Tài xế giảm tốc độ khi chúng tôi tiến đến một khúc cua gắt.","audioKind":"ex"},{"en":"Roads that curve around existing woodland can reduce habitat destruction, although they may increase construction costs.","vi":"Những con đường uốn lượn quanh khu rừng hiện có có thể làm giảm tình trạng tàn phá môi trường sống, mặc dù chúng có thể làm tăng chi phí xây dựng.","audioKind":"ex2"}],"collocations":[{"en":"a sharp curve","vi":"khúc cua gắt"},{"en":"a gentle curve","vi":"khúc cua thoai thoải"},{"en":"a learning curve","vi":"đường cong học tập"},{"en":"curve around","vi":"uốn lượn quanh"}],"wordFamily":["curved (adj.)","curvature (n.)"],"synonyms":["bend"],"antonyms":[],"tipVi":"curve có thể làm danh từ hoặc động từ; \"vận dụng tính từ\" của nó là curved.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_seaport', 'en-b2-6', 'seaport', '/ˈsiːpɔːrt/', 'B2', 'cảng biển; thành phố cảng', 'n.', 'port (n.)', 'Đồng nghĩa: port', 'seaport nhấn mạnh vào cảng biển, khác với cảng sông và sân bay.', 'Huge ships arrive at the seaport every morning.', NULL, 'Những con tàu khổng lồ cập cảng biển vào mỗi buổi sáng.', '{"wordId":"seaport","ukIpa":"/ˈsiːpɔːt/","usIpa":"/ˈsiːpɔːrt/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"A coastal harbour or town where ships load and unload.","vi":"cảng biển; thành phố cảng"}],"examples":[{"en":"Huge ships arrive at the seaport every morning.","vi":"Những con tàu khổng lồ cập cảng biển vào mỗi buổi sáng.","audioKind":"ex"},{"en":"Investment in modern seaports can strengthen international trade and create employment in coastal regions.","vi":"Đầu tư vào các cảng biển hiện đại có thể thúc đẩy thương mại quốc tế và tạo việc làm ở các vùng ven biển.","audioKind":"ex2"}],"collocations":[{"en":"major seaport","vi":"cảng biển lớn"},{"en":"busy seaport","vi":"cảng biển tấp nập"},{"en":"seaport development","vi":"phát triển cảng biển"}],"wordFamily":["port (n.)"],"synonyms":["port"],"antonyms":[],"tipVi":"seaport nhấn mạnh vào cảng biển, khác với cảng sông và sân bay.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hospitality', 'en-b2-6', 'hospitality', '/ˌhɑːspɪˈtæləti/', 'B2', 'sự hiếu khách; lòng mến khách; ngành dịch vụ nhà hàng khách sạn', 'n.', 'hospitable (adj.), hospitably (adv.), inhospitable (adj.)', 'Trái nghĩa: inhospitality', 'Thường là danh từ không đếm được; hospitality industry chỉ ngành dịch vụ lưu trú và ăn uống.', 'Their warm hospitality made us feel completely at home.', NULL, 'Sự hiếu khách nồng hậu của họ khiến chúng tôi cảm thấy thoải mái như ở nhà.', '{"wordId":"hospitality","ukIpa":"/ˌhɒspɪˈtæləti/","usIpa":"/ˌhɑːspɪˈtæləti/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"Friendly and generous treatment of guests or visitors.","vi":"sự hiếu khách; lòng mến khách"},{"pos":"n.","en":"The business of providing accommodation, food, and services to guests.","vi":"ngành dịch vụ nhà hàng khách sạn"}],"examples":[{"en":"Their warm hospitality made us feel completely at home.","vi":"Sự hiếu khách nồng hậu của họ khiến chúng tôi cảm thấy thoải mái như ở nhà.","audioKind":"ex"},{"en":"The hospitality industry creates employment opportunities, but seasonal demand can make workers'' incomes less predictable.","vi":"Ngành dịch vụ nhà hàng khách sạn tạo ra các cơ hội việc làm, nhưng nhu cầu theo mùa có thể làm cho thu nhập của người lao động bấp bênh hơn.","audioKind":"ex2"}],"collocations":[{"en":"warm hospitality","vi":"sự hiếu khách nồng hậu"},{"en":"extend hospitality to","vi":"đãi ngộ"},{"en":"hospitality industry","vi":"ngành khách sạn nhà hàng"}],"wordFamily":["hospitable (adj.)","hospitably (adv.)","inhospitable (adj.)"],"synonyms":[],"antonyms":["inhospitality"],"tipVi":"Thường là danh từ không đếm được; hospitality industry chỉ ngành dịch vụ lưu trú và ăn uống.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hitchhike', 'en-b2-6', 'hitchhike', '/ˈhɪtʃhaɪk/', 'B2', 'đi nhờ xe; quá giang', 'v.', 'hitchhiker (n.), hitchhiking (n.)', NULL, 'Thường đóng vai trò là nội động từ; đi kèm với giới từ to trước điểm đến.', 'We hitchhiked to the coast with our backpacks.', NULL, 'Chúng tôi đã đeo balo và đi nhờ xe đến vùng bờ biển.', '{"wordId":"hitchhike","ukIpa":"/ˈhɪtʃhaɪk/","usIpa":"/ˈhɪtʃhaɪk/","cefr":"B2","topic":"travel","senses":[{"pos":"v.","en":"Travel by getting free rides in passing vehicles.","vi":"đi nhờ xe; quá giang"}],"examples":[{"en":"We hitchhiked to the coast with our backpacks.","vi":"Chúng tôi đã đeo balo và đi nhờ xe đến vùng bờ biển.","audioKind":"ex"},{"en":"Although some tourists hitchhike to reduce travel costs, limited transport services can make such journeys unpredictable.","vi":"Mặc dù một số du khách chọn đi nhờ xe để giảm chi phí đi lại, nhưng các dịch vụ giao thông hạn chế có thể khiến những hành trình như vậy trở nên khó lường.","audioKind":"ex2"}],"collocations":[{"en":"hitchhike across a country","vi":"đi nhờ xe xuyên quốc gia"},{"en":"hitchhike to the coast","vi":"đi nhờ xe ra biển"}],"wordFamily":["hitchhiker (n.)","hitchhiking (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường đóng vai trò là nội động từ; đi kèm với giới từ to trước điểm đến.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deck', 'en-b2-6', 'deck', '/dek/', 'B2', 'boong tàu; tầng xe buýt; sàn hiên gỗ ngoài trời; một bộ bài', 'n.', NULL, NULL, 'Bộ bài trong tiếng Anh Mỹ thường dùng deck, trong khi tiếng Anh Anh cũng hay dùng pack.', 'We stood on deck and watched dolphins swim past.', NULL, 'Chúng tôi đứng trên boong tàu và ngắm nhìn những chú cá heo bơi lội qua.', '{"wordId":"deck","ukIpa":"/dek/","usIpa":"/dek/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"a floor on a ship or a level of a bus","vi":"boong tàu; tầng xe buýt"},{"pos":"n.","en":"a wooden outdoor platform beside a house","vi":"sàn hiên gỗ ngoài trời"},{"pos":"n.","en":"a complete set of playing cards","vi":"một bộ bài"}],"examples":[{"en":"We stood on deck and watched dolphins swim past.","vi":"Chúng tôi đứng trên boong tàu và ngắm nhìn những chú cá heo bơi lội qua.","audioKind":"ex"},{"en":"Passengers on the upper deck of sightseeing buses can enjoy clear views of historic buildings.","vi":"Hành khách ở tầng trên của xe buýt ngắm cảnh có thể tận hưởng tầm nhìn quang đãng ra các công trình kiến trúc lịch sử.","audioKind":"ex2"}],"collocations":[{"en":"on deck","vi":"trên boong tàu"},{"en":"upper deck","vi":"tầng trên; boong trên"},{"en":"wooden deck","vi":"sân hiên bằng gỗ"},{"en":"a deck of cards","vi":"một bộ bài tây"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Bộ bài trong tiếng Anh Mỹ thường dùng deck, trong khi tiếng Anh Anh cũng hay dùng pack.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mainland', 'en-b2-6', 'mainland', '/ˈmeɪnlənd/', 'B2', 'đất liền; đại lục; thuộc đất liền; thuộc đại lục', 'n.', NULL, NULL, 'Danh từ thường dùng ''the mainland''; khi làm định từ dùng các cụm như ''mainland Europe''.', 'We caught the morning ferry back to the mainland.', NULL, 'Chúng tôi đã bắt chuyến phà buổi sáng để trở về đất liền.', '{"wordId":"mainland","ukIpa":"/ˈmeɪnlənd/","usIpa":"/ˈmeɪnlənd/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"The main land area, excluding nearby islands.","vi":"đất liền; đại lục"},{"pos":"adj.","en":"Located on or relating to the main land area.","vi":"thuộc đất liền; thuộc đại lục"}],"examples":[{"en":"We caught the morning ferry back to the mainland.","vi":"Chúng tôi đã bắt chuyến phà buổi sáng để trở về đất liền.","audioKind":"ex"},{"en":"Reliable transport links between small islands and the mainland are essential for healthcare access and economic development.","vi":"Các kết nối giao thông đáng tin cậy giữa các hòn đảo nhỏ và đất liền đóng vai trò thiết yếu cho việc tiếp cận dịch vụ y tế và phát triển kinh tế.","audioKind":"ex2"}],"collocations":[{"en":"on the mainland","vi":"trên đất liền"},{"en":"mainland Europe","vi":"lục địa Châu Âu"},{"en":"mainland residents","vi":"cư dân đất liền"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ thường dùng ''the mainland''; khi làm định từ dùng các cụm như ''mainland Europe''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shipwreck', 'en-b2-6', 'shipwreck', '/ˈʃɪprek/', 'B2', 'tai nạn đắm tàu; sự cố đắm tàu (tai nạn trong đó một con tàu bị phá hủy hoặc chìm); xác tàu đắm; tàn tích tàu chìm (phần còn lại của một con tàu đã chìm hoặc bị phá hủy)', 'n.', 'shipwrecked (adj.)', NULL, 'Từ này vừa chỉ sự kiện tai nạn đắm tàu, vừa chỉ thân tàu còn sót lại sau khi chìm.', 'Everyone survived the shipwreck and reached the nearby island.', NULL, 'Tất cả mọi người đều sống sót sau vụ đắm tàu và bơi được vào hòn đảo gần đó.', '{"wordId":"shipwreck","ukIpa":"/ˈʃɪprek/","usIpa":"/ˈʃɪprek/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"An accident in which a ship is destroyed or sinks.","vi":"tai nạn đắm tàu; sự cố đắm tàu (tai nạn trong đó một con tàu bị phá hủy hoặc chìm)"},{"pos":"n.","en":"The remains of a ship that has sunk or been destroyed.","vi":"xác tàu đắm; tàn tích tàu chìm (phần còn lại của một con tàu đã chìm hoặc bị phá hủy)"}],"examples":[{"en":"Everyone survived the shipwreck and reached the nearby island.","vi":"Tất cả mọi người đều sống sót sau vụ đắm tàu và bơi được vào hòn đảo gần đó.","audioKind":"ex"},{"en":"Studying a shipwreck can reveal valuable information about historical trade routes and traditional methods of shipbuilding.","vi":"Việc nghiên cứu xác tàu đắm có thể hé lộ những thông tin quý giá về các tuyến đường thương mại lịch sử và phương pháp đóng tàu truyền thống.","audioKind":"ex2"}],"collocations":[{"en":"survive a shipwreck","vi":"sống sót sau vụ đắm tàu"},{"en":"an ancient shipwreck","vi":"xác tàu cổ"},{"en":"explore a shipwreck","vi":"khảo sát xác tàu đắm"}],"wordFamily":["shipwrecked (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ này vừa chỉ sự kiện tai nạn đắm tàu, vừa chỉ thân tàu còn sót lại sau khi chìm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_expedition', 'en-b2-6', 'expedition', '/ˌekspəˈdɪʃən/', 'B2', 'cuộc thám hiểm; cuộc viễn chinh; chuyến khảo sát; đội thám hiểm; đoàn khảo sát', 'n.', 'expeditionary (adj.)', NULL, 'Expedition thường chỉ những chuyến đi xa có tổ chức và mục đích cụ thể.', 'We packed warm clothes for our expedition into the mountains.', NULL, 'Chúng tôi đã chuẩn bị quần áo ấm cho chuyến thám hiểm vào vùng núi cao.', '{"wordId":"expedition","ukIpa":"/ˌekspəˈdɪʃən/","usIpa":"/ˌekspəˈdɪʃən/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"An organised journey made for exploration or a specific purpose.","vi":"cuộc thám hiểm; cuộc viễn chinh; chuyến khảo sát"},{"pos":"n.","en":"A group of people travelling together to explore or investigate.","vi":"đội thám hiểm; đoàn khảo sát"}],"examples":[{"en":"We packed warm clothes for our expedition into the mountains.","vi":"Chúng tôi đã chuẩn bị quần áo ấm cho chuyến thám hiểm vào vùng núi cao.","audioKind":"ex"},{"en":"A scientific expedition to the polar regions collected valuable evidence of changes in sea ice.","vi":"Một đoàn thám hiểm khoa học tới các vùng cực đã thu thập những bằng chứng quý giá về sự biến đổi của băng biển.","audioKind":"ex2"}],"collocations":[{"en":"a scientific expedition","vi":"một chuyến khảo sát khoa học"},{"en":"go on an expedition","vi":"đi thám hiểm"},{"en":"lead an expedition","vi":"dẫn đầu một đoàn thám hiểm"},{"en":"an expedition to Antarctica","vi":"chuyến thám hiểm Nam Cực"}],"wordFamily":["expeditionary (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Expedition thường chỉ những chuyến đi xa có tổ chức và mục đích cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_non-refundable', 'en-b2-6', 'non-refundable', '/ˌnɑːn rɪˈfʌndəbl/', 'B2', 'không được hoàn tiền; không thể trả lại tiền', 'adj.', 'refund (n.), refund (v.), refundable (adj.)', 'Trái nghĩa: refundable', 'Chỉ tiền đã thanh toán không được hoàn trả, không dùng để chỉ đồ vật không được trả lại.', 'We chose cheaper tickets, but they were non-refundable.', NULL, 'Chúng tôi đã chọn vé rẻ hơn, nhưng chúng không được hoàn tiền.', '{"wordId":"non-refundable","ukIpa":"/ˌnɒn rɪˈfʌndəbl/","usIpa":"/ˌnɑːn rɪˈfʌndəbl/","cefr":"B2","topic":"travel","senses":[{"pos":"adj.","en":"Not eligible for money to be returned after payment.","vi":"không được hoàn tiền; không thể trả lại tiền"}],"examples":[{"en":"We chose cheaper tickets, but they were non-refundable.","vi":"Chúng tôi đã chọn vé rẻ hơn, nhưng chúng không được hoàn tiền.","audioKind":"ex"},{"en":"Non-refundable booking fees can discourage travellers from changing plans, even when their circumstances unexpectedly change.","vi":"Phí đặt chỗ không được hoàn lại có thể khiến du khách ngần ngại thay đổi kế hoạch, ngay cả khi hoàn cảnh của họ bất ngờ thay đổi.","audioKind":"ex2"}],"collocations":[{"en":"a non-refundable deposit","vi":"tiền đặt cọc không được hoàn lại"},{"en":"a non-refundable ticket","vi":"vé không được hoàn tiền"},{"en":"a non-refundable booking fee","vi":"phí đặt chỗ không hoàn lại"}],"wordFamily":["refund (n.)","refund (v.)","refundable (adj.)"],"synonyms":[],"antonyms":["refundable"],"tipVi":"Chỉ tiền đã thanh toán không được hoàn trả, không dùng để chỉ đồ vật không được trả lại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_expressway', 'en-b2-6', 'expressway', '/ɪkˈspresweɪ/', 'B2', 'đường cao tốc', 'n.', NULL, 'Đồng nghĩa: motorway, freeway', 'Phổ biến trong tiếng Anh Mỹ và châu Á; tiếng Anh Anh thường dùng motorway.', 'We took the expressway to reach the airport before sunrise.', NULL, 'Chúng tôi đi đường cao tốc để đến sân bay trước khi trời sáng.', '{"wordId":"expressway","ukIpa":"/ɪkˈspresweɪ/","usIpa":"/ɪkˈspresweɪ/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"A wide road designed for fast traffic, with limited access.","vi":"đường cao tốc"}],"examples":[{"en":"We took the expressway to reach the airport before sunrise.","vi":"Chúng tôi đi đường cao tốc để đến sân bay trước khi trời sáng.","audioKind":"ex"},{"en":"Building a new expressway may reduce journey times, but it can also encourage greater dependence on private cars.","vi":"Việc xây dựng một con đường cao tốc mới có thể rút ngắn thời gian di chuyển, nhưng cũng có thể làm gia tăng sự phụ thuộc vào ô tô cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"expressway exit","vi":"lối ra đường cao tốc"},{"en":"expressway construction","vi":"thi công đường cao tốc"},{"en":"take the expressway","vi":"đi đường cao tốc"}],"wordFamily":[],"synonyms":["motorway","freeway"],"antonyms":[],"tipVi":"Phổ biến trong tiếng Anh Mỹ và châu Á; tiếng Anh Anh thường dùng motorway.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shuttle', 'en-b2-6', 'shuttle', '/ˈʃʌtəl/', 'B2', 'xe đưa đón; phương tiện vận chuyển qua lại; tàu con thoi; chạy tuyến trung chuyển; di chuyển qua lại', 'n.', NULL, NULL, 'Trong ngữ cảnh giao thông, từ này nhấn mạnh việc di chuyển liên tục giữa hai điểm; tàu vũ trụ dùng space shuttle.', 'We took the free shuttle from the airport to our hotel.', NULL, 'Chúng tôi đã bắt chuyến xe buýt đưa đón miễn phí từ sân bay về khách sạn.', '{"wordId":"shuttle","ukIpa":"/ˈʃʌtəl/","usIpa":"/ˈʃʌtəl/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"a vehicle making frequent trips between two places","vi":"xe đưa đón; phương tiện vận chuyển qua lại"},{"pos":"n.","en":"a spacecraft designed for repeated journeys into space","vi":"tàu con thoi"},{"pos":"v.","en":"to travel or carry people repeatedly between places","vi":"chạy tuyến trung chuyển; di chuyển qua lại"}],"examples":[{"en":"We took the free shuttle from the airport to our hotel.","vi":"Chúng tôi đã bắt chuyến xe buýt đưa đón miễn phí từ sân bay về khách sạn.","audioKind":"ex"},{"en":"Regular shuttle services between railway stations and business parks could reduce dependence on private cars.","vi":"Dịch vụ xe đưa đón thường xuyên giữa các ga tàu và khu thương mại có thể làm giảm sự phụ thuộc vào phương tiện cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"shuttle bus","vi":"xe buýt đưa đón"},{"en":"airport shuttle","vi":"xe đưa đón sân bay"},{"en":"space shuttle","vi":"tàu con thoi"},{"en":"shuttle between","vi":"di chuyển qua lại giữa"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong ngữ cảnh giao thông, từ này nhấn mạnh việc di chuyển liên tục giữa hai điểm; tàu vũ trụ dùng space shuttle.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_elsewhere', 'en-b2-6', 'elsewhere', '/ˌelsˈwer/', 'B2', 'ở nơi khác; đến nơi khác', 'adv.', NULL, NULL, 'Bản thân từ này là trạng từ, thông thường không dùng in elsewhere hay to elsewhere.', 'This café is full, so let''s eat elsewhere.', NULL, 'Quán cà phê này hết chỗ rồi, chúng ta hãy đi nơi khác ăn đi.', '{"wordId":"elsewhere","ukIpa":"/ˌelsˈweə/","usIpa":"/ˌelsˈwer/","cefr":"B2","topic":"travel","senses":[{"pos":"adv.","en":"in or to another place","vi":"ở nơi khác; đến nơi khác"}],"examples":[{"en":"This café is full, so let''s eat elsewhere.","vi":"Quán cà phê này hết chỗ rồi, chúng ta hãy đi nơi khác ăn đi.","audioKind":"ex"},{"en":"When local housing becomes unaffordable, young workers often move elsewhere in search of better living conditions.","vi":"Khi giá nhà ở địa phương trở nên quá đắt đỏ, những lao động trẻ thường chuyển đến nơi khác để tìm kiếm điều kiện sống tốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"look elsewhere","vi":"tìm kiếm ở nơi khác"},{"en":"go elsewhere","vi":"đi đến nơi khác"},{"en":"elsewhere in the world","vi":"ở những nơi khác trên thế giới"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Bản thân từ này là trạng từ, thông thường không dùng in elsewhere hay to elsewhere.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_homestay', 'en-b2-6', 'homestay', '/ˈhoʊmsteɪ/', 'B2', 'sự ở nhờ nhà người bản xứ; hình thức du lịch homestay', 'n.', NULL, NULL, 'Nhấn mạnh việc sống trong một gia đình bản địa; gia đình đón tiếp thường gọi là host family.', 'During my homestay, I cooked dinner with the family.', NULL, 'Trong thời gian ở homestay, tôi đã cùng gia đình nấu bữa tối.', '{"wordId":"homestay","ukIpa":"/ˈhəʊmsteɪ/","usIpa":"/ˈhoʊmsteɪ/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"A stay in a local family''s home while visiting another place","vi":"sự ở nhờ nhà người bản xứ; hình thức du lịch homestay"}],"examples":[{"en":"During my homestay, I cooked dinner with the family.","vi":"Trong thời gian ở homestay, tôi đã cùng gia đình nấu bữa tối.","audioKind":"ex"},{"en":"A homestay can help international students practise everyday language skills and understand local customs.","vi":"Hình thức ở homestay có thể giúp các sinh viên quốc tế rèn luyện kỹ năng ngôn ngữ hàng ngày và hiểu rõ hơn về phong tục địa phương.","audioKind":"ex2"}],"collocations":[{"en":"homestay accommodation","vi":"nơi ở dạng homestay"},{"en":"homestay programme","vi":"chương trình homestay"},{"en":"homestay family","vi":"gia đình nhận homestay"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Nhấn mạnh việc sống trong một gia đình bản địa; gia đình đón tiếp thường gọi là host family.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pedal', 'en-b2-6', 'pedal', '/ˈpedəl/', 'B2', 'bàn đạp; chân vịt; đạp bàn đạp; lái xe đạp', 'n.', NULL, NULL, 'Thì quá khứ theo tiếng Anh-Anh thường viết là pedalled, còn tiếng Anh-Mỹ viết là pedaled.', 'My foot slipped off the pedal in the rain.', NULL, 'Chân tôi bị trượt khỏi bàn đạp trong cơn mưa.', '{"wordId":"pedal","ukIpa":"/ˈpedəl/","usIpa":"/ˈpedəl/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"A part pushed with the foot to operate something.","vi":"bàn đạp; chân vịt"},{"pos":"v.","en":"To move a bicycle by pushing its pedals.","vi":"đạp bàn đạp; lái xe đạp"}],"examples":[{"en":"My foot slipped off the pedal in the rain.","vi":"Chân tôi bị trượt khỏi bàn đạp trong cơn mưa.","audioKind":"ex"},{"en":"More residents would pedal to work if cities provided safer cycling routes and secure bicycle parking.","vi":"Nhiều cư dân sẽ đạp xe đi làm nếu các thành phố cung cấp các tuyến đường đạp xe an toàn hơn và bãi đỗ xe đạp bảo đảm.","audioKind":"ex2"}],"collocations":[{"en":"brake pedal","vi":"bàn đạp phanh"},{"en":"bicycle pedal","vi":"bàn đạp xe đạp"},{"en":"pedal uphill","vi":"đạp xe lên dốc"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thì quá khứ theo tiếng Anh-Anh thường viết là pedalled, còn tiếng Anh-Mỹ viết là pedaled.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_oceania', 'en-b2-6', 'Oceania', '/ˌoʊ.ʃiˈæ.ni.ə/', 'B2', 'châu Đại Dương', 'n.', NULL, NULL, 'Danh từ riêng, viết hoa chữ cái đầu; thường không đứng trước mạo từ "the".', 'Our neighbour travelled around Oceania with a small backpack.', NULL, 'Hàng xóm của chúng tôi đã đi du lịch vòng quanh châu Đại Dương với một chiếc balo nhỏ.', '{"wordId":"oceania","ukIpa":"/ˌəʊ.siˈɑː.ni.ə/","usIpa":"/ˌoʊ.ʃiˈæ.ni.ə/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"the region including Australia, New Zealand, and many Pacific islands","vi":"châu Đại Dương"}],"examples":[{"en":"Our neighbour travelled around Oceania with a small backpack.","vi":"Hàng xóm của chúng tôi đã đi du lịch vòng quanh châu Đại Dương với một chiếc balo nhỏ.","audioKind":"ex"},{"en":"Many island communities in Oceania face growing risks from rising sea levels and increasingly severe storms.","vi":"Nhiều cộng đồng đảo ở châu Đại Dương đang phải đối mặt với rủi ro ngày càng tăng từ mực nước biển dâng cao và các trận bão ngày càng dữ dội.","audioKind":"ex2"}],"collocations":[{"en":"island nations in Oceania","vi":"các quốc đảo ở châu Đại Dương"},{"en":"across Oceania","vi":"khắp châu Đại Dương"},{"en":"the peoples of Oceania","vi":"các dân tộc ở châu Đại Dương"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ riêng, viết hoa chữ cái đầu; thường không đứng trước mạo từ \"the\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_luxurious', 'en-b2-6', 'luxurious', '/lʌɡˈʒʊriəs/', 'B2', 'sang trọng; xa hoa; đắt tiền', 'adj.', 'luxury (n.), luxuriously (adv.)', 'Đồng nghĩa: lavish, opulent · Trái nghĩa: basic, spartan', 'Luxurious chỉ sự sang trọng, thoải mái; luxuriant thường chỉ cây cối tươi tốt, rậm rạp.', 'Our hotel room had a luxurious bath overlooking the sea.', NULL, 'Phòng khách sạn của chúng tôi có một bồn tắm sang trọng nhìn ra biển.', '{"wordId":"luxurious","ukIpa":"/lʌɡˈʒʊəriəs/","usIpa":"/lʌɡˈʒʊriəs/","cefr":"B2","topic":"travel","senses":[{"pos":"adj.","en":"Very comfortable and expensive, often with beautiful surroundings or materials.","vi":"sang trọng; xa hoa; đắt tiền"}],"examples":[{"en":"Our hotel room had a luxurious bath overlooking the sea.","vi":"Phòng khách sạn của chúng tôi có một bồn tắm sang trọng nhìn ra biển.","audioKind":"ex"},{"en":"Although luxurious resorts attract wealthy visitors, their high water consumption can place pressure on local resources.","vi":"Mặc dù các khu nghỉ dưỡng sang trọng thu hút khách du lịch giàu có, nhưng lượng nước tiêu thụ lớn của họ có thể gây áp lực lên tài nguyên địa phương.","audioKind":"ex2"}],"collocations":[{"en":"luxurious hotel","vi":"khách sạn sang trọng"},{"en":"luxurious lifestyle","vi":"lối sống xa hoa"},{"en":"luxurious accommodation","vi":"chỗ ở sang trọng"}],"wordFamily":["luxury (n.)","luxuriously (adv.)"],"synonyms":["lavish","opulent"],"antonyms":["basic","spartan"],"tipVi":"Luxurious chỉ sự sang trọng, thoải mái; luxuriant thường chỉ cây cối tươi tốt, rậm rạp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_compartment', 'en-b2-6', 'compartment', '/kəmˈpɑːrtmənt/', 'B2', 'ngăn; ngăn tủ; khoang; toa xe lửa chia toa', 'n.', 'compartmentalise (v.), compartmentalisation (n.)', NULL, 'Chỉ phần không gian được ngăn ra bên trong một không gian lớn hơn, chẳng hạn như ngăn nhỏ trong túi.', 'Keep your keys in the small compartment inside your bag.', NULL, 'Hãy để chìa khóa của bạn trong ngăn nhỏ bên trong túi xách.', '{"wordId":"compartment","ukIpa":"/kəmˈpɑːtmənt/","usIpa":"/kəmˈpɑːrtmənt/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"A separate section within a container, vehicle, or building.","vi":"ngăn; ngăn tủ; khoang; toa xe lửa chia toa"}],"examples":[{"en":"Keep your keys in the small compartment inside your bag.","vi":"Hãy để chìa khóa của bạn trong ngăn nhỏ bên trong túi xách.","audioKind":"ex"},{"en":"Separate compartments on trains can provide passengers with greater privacy during long journeys.","vi":"Các khoang riêng biệt trên tàu hỏa có thể mang lại cho hành khách sự riêng tư lớn hơn trong những chuyến đi dài.","audioKind":"ex2"}],"collocations":[{"en":"storage compartment","vi":"ngăn chứa đồ"},{"en":"glove compartment","vi":"hộc để đồ ô tô"},{"en":"train compartment","vi":"khoang tàu"}],"wordFamily":["compartmentalise (v.)","compartmentalisation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ phần không gian được ngăn ra bên trong một không gian lớn hơn, chẳng hạn như ngăn nhỏ trong túi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wagon', 'en-b2-6', 'wagon', '/ˈwæɡən/', 'B2', 'xe ngựa kéo bốn bánh chở hàng; toa xe lửa chở hàng', 'n.', NULL, NULL, 'Tiếng Anh-Anh cũng viết là waggon; nghĩa chở hàng bằng đường sắt chủ yếu được dùng trong tiếng Anh-Anh.', 'The horse pulled a wagon loaded with fresh apples.', NULL, 'Con ngựa kéo một chiếc xe chở đầy táo tươi.', '{"wordId":"wagon","ukIpa":"/ˈwæɡən/","usIpa":"/ˈwæɡən/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"a four-wheeled vehicle pulled by horses to carry goods","vi":"xe ngựa kéo bốn bánh chở hàng"},{"pos":"n.","en":"a railway vehicle for carrying goods, especially in British English","vi":"toa xe lửa chở hàng"}],"examples":[{"en":"The horse pulled a wagon loaded with fresh apples.","vi":"Con ngựa kéo một chiếc xe chở đầy táo tươi.","audioKind":"ex"},{"en":"Before modern roads developed, farmers relied on horse-drawn wagons to transport their produce to regional markets.","vi":"Trước khi các tuyến đường hiện đại phát triển, nông dân phải dựa vào xe ngựa kéo để vận chuyển nông sản của họ đến các chợ vùng.","audioKind":"ex2"}],"collocations":[{"en":"horse-drawn wagon","vi":"xe ngựa kéo"},{"en":"covered wagon","vi":"xe có mui chở hàng"},{"en":"goods wagon","vi":"toa xe lửa chở hàng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tiếng Anh-Anh cũng viết là waggon; nghĩa chở hàng bằng đường sắt chủ yếu được dùng trong tiếng Anh-Anh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_descent', 'en-b2-6', 'descent', '/dɪˈsent/', 'B2', 'sự đi xuống, sự hạ xuống (di chuyển từ vị trí cao xuống vị trí thấp hơn); dòng dõi, nguồn gốc gia đình (tổ tiên hoặc huyết thống của một người); đoạn dốc xuống, con đường đi xuống', 'n.', 'descend (v.), descendant (n.)', 'Đồng nghĩa: ancestry · Trái nghĩa: ascent', '"descent" là danh từ; động từ tương ứng là "descend", cần tránh nhầm lẫn với tính từ "decent".', 'The plane began its descent as the coastline appeared.', NULL, 'Máy bay bắt đầu hạ độ cao khi đường bờ biển hiện ra.', '{"wordId":"descent","ukIpa":"/dɪˈsent/","usIpa":"/dɪˈsent/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"Movement from a higher position to a lower one.","vi":"sự đi xuống, sự hạ xuống (di chuyển từ vị trí cao xuống vị trí thấp hơn)"},{"pos":"n.","en":"A person''s family origins or ancestry.","vi":"dòng dõi, nguồn gốc gia đình (tổ tiên hoặc huyết thống của một người)"},{"pos":"n.","en":"A slope or path that leads downwards.","vi":"đoạn dốc xuống, con đường đi xuống"}],"examples":[{"en":"The plane began its descent as the coastline appeared.","vi":"Máy bay bắt đầu hạ độ cao khi đường bờ biển hiện ra.","audioKind":"ex"},{"en":"People of different ethnic descent contribute diverse skills and perspectives to their local communities.","vi":"Những người có nguồn gốc sắc tộc khác nhau đóng góp các kỹ năng và góc nhìn đa dạng cho cộng đồng địa phương của họ.","audioKind":"ex2"}],"collocations":[{"en":"begin the descent","vi":"bắt đầu hạ độ cao"},{"en":"a steep descent","vi":"đoạn dốc đứng"},{"en":"of Chinese descent","vi":"có gốc gác Trung Quốc"}],"wordFamily":["descend (v.)","descendant (n.)"],"synonyms":["ancestry"],"antonyms":["ascent"],"tipVi":"\"descent\" là danh từ; động từ tương ứng là \"descend\", cần tránh nhầm lẫn với tính từ \"decent\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_signpost', 'en-b2-6', 'signpost', '/ˈsaɪnpoʊst/', 'B2', 'cột chỉ đường; biển chỉ đường; đặt biển chỉ đường; đánh dấu đường đi; làm rõ cấu trúc; vạch rõ định hướng', 'n.', 'signposting (n.)', NULL, 'Trong văn bản học thuật hoặc bài viết, động từ signpost dùng để chỉ việc sử dụng các từ nối hoặc câu dẫn để làm rõ cấu trúc lập luận.', 'We stopped at the signpost beside the forest path.', NULL, 'Chúng tôi dừng lại ở tấm biển chỉ đường ngay cạnh lối mòn trong rừng.', '{"wordId":"signpost","ukIpa":"/ˈsaɪnpəʊst/","usIpa":"/ˈsaɪnpoʊst/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"A roadside post showing directions to different places.","vi":"cột chỉ đường; biển chỉ đường"},{"pos":"v.","en":"Mark a route or place with signs showing directions.","vi":"đặt biển chỉ đường; đánh dấu đường đi"},{"pos":"v.","en":"Make the structure or direction of an explanation clear.","vi":"làm rõ cấu trúc; vạch rõ định hướng"}],"examples":[{"en":"We stopped at the signpost beside the forest path.","vi":"Chúng tôi dừng lại ở tấm biển chỉ đường ngay cạnh lối mòn trong rừng.","audioKind":"ex"},{"en":"Writers should signpost changes in their argument so that readers can follow complex discussions more easily.","vi":"Các tác giả nên vạch rõ sự chuyển ý trong lập luận của mình để người đọc dễ dàng theo dõi các cuộc tranh luận phức tạp.","audioKind":"ex2"}],"collocations":[{"en":"follow the signposts","vi":"đi theo các biển chỉ đường"},{"en":"clearly signposted","vi":"có biển chỉ đường rõ ràng"},{"en":"signpost an argument","vi":"làm rõ mạch lập luận"}],"wordFamily":["signposting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong văn bản học thuật hoặc bài viết, động từ signpost dùng để chỉ việc sử dụng các từ nối hoặc câu dẫn để làm rõ cấu trúc lập luận.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lifeboat', 'en-b2-6', 'lifeboat', '/ˈlaɪfboʊt/', 'B2', 'thuyền cứu sinh; xuồng cứu nạn', 'n.', NULL, NULL, 'lifeboat là thuyền cứu sinh; life jacket là áo phao cứu sinh.', 'The crew lowered the lifeboat carefully into the sea.', NULL, 'Thủy thủ đoàn cẩn thận hạ xuồng cứu sinh xuống biển.', '{"wordId":"lifeboat","ukIpa":"/ˈlaɪfbəʊt/","usIpa":"/ˈlaɪfboʊt/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"A boat used to rescue people in danger at sea.","vi":"thuyền cứu sinh; xuồng cứu nạn"}],"examples":[{"en":"The crew lowered the lifeboat carefully into the sea.","vi":"Thủy thủ đoàn cẩn thận hạ xuồng cứu sinh xuống biển.","audioKind":"ex"},{"en":"Coastal communities rely on trained lifeboat crews to rescue swimmers and sailors during emergencies at sea.","vi":"Các cộng đồng ven biển dựa vào các đội cứu sinh được huấn luyện bài bản để giải cứu người bơi lội và thủy thủ trong các trường hợp khẩn cấp trên biển.","audioKind":"ex2"}],"collocations":[{"en":"a lifeboat crew","vi":"đội cứu sinh"},{"en":"launch a lifeboat","vi":"hạ thủy xuồng cứu sinh"},{"en":"a lifeboat station","vi":"trạm cứu sinh"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"lifeboat là thuyền cứu sinh; life jacket là áo phao cứu sinh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_6_1', 'en-b2-6', 'Cách dùng “signpost” (n.) — cột chỉ đường; biển chỉ đường', 'follow the signposts  ·  clearly signposted  ·  signpost an argument', 'Trong văn bản học thuật hoặc bài viết, động từ signpost dùng để chỉ việc sử dụng các từ nối hoặc câu dẫn để làm rõ cấu trúc lập luận.', 'Họ từ (Word Family): signposting (n.)', '[{"hanzi":"We stopped at the signpost beside the forest path.","pinyin":"","meaning":"Chúng tôi dừng lại ở tấm biển chỉ đường ngay cạnh lối mòn trong rừng."},{"hanzi":"Writers should signpost changes in their argument so that readers can follow complex discussions more easily.","pinyin":"","meaning":"Các tác giả nên vạch rõ sự chuyển ý trong lập luận của mình để người đọc dễ dàng theo dõi các cuộc tranh luận phức tạp."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_6_2', 'en-b2-6', 'Cách dùng “shuttle” (n.) — xe đưa đón; phương tiện vận chuyển qua lại', 'shuttle bus  ·  airport shuttle  ·  space shuttle', 'Trong ngữ cảnh giao thông, từ này nhấn mạnh việc di chuyển liên tục giữa hai điểm; tàu vũ trụ dùng space shuttle.', NULL, '[{"hanzi":"We took the free shuttle from the airport to our hotel.","pinyin":"","meaning":"Chúng tôi đã bắt chuyến xe buýt đưa đón miễn phí từ sân bay về khách sạn."},{"hanzi":"Regular shuttle services between railway stations and business parks could reduce dependence on private cars.","pinyin":"","meaning":"Dịch vụ xe đưa đón thường xuyên giữa các ga tàu và khu thương mại có thể làm giảm sự phụ thuộc vào phương tiện cá nhân."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_6_3', 'en-b2-6', 'Cách dùng “wagon” (n.) — xe ngựa kéo bốn bánh chở hàng', 'horse-drawn wagon  ·  covered wagon  ·  goods wagon', 'Tiếng Anh-Anh cũng viết là waggon; nghĩa chở hàng bằng đường sắt chủ yếu được dùng trong tiếng Anh-Anh.', NULL, '[{"hanzi":"The horse pulled a wagon loaded with fresh apples.","pinyin":"","meaning":"Con ngựa kéo một chiếc xe chở đầy táo tươi."},{"hanzi":"Before modern roads developed, farmers relied on horse-drawn wagons to transport their produce to regional markets.","pinyin":"","meaning":"Trước khi các tuyến đường hiện đại phát triển, nông dân phải dựa vào xe ngựa kéo để vận chuyển nông sản của họ đến các chợ vùng."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_6_4', 'en-b2-6', 'Cách dùng “compartment” (n.) — ngăn; ngăn tủ; khoang; toa xe lửa chia toa', 'storage compartment  ·  glove compartment  ·  train compartment', 'Chỉ phần không gian được ngăn ra bên trong một không gian lớn hơn, chẳng hạn như ngăn nhỏ trong túi.', 'Họ từ (Word Family): compartmentalise (v.), compartmentalisation (n.)', '[{"hanzi":"Keep your keys in the small compartment inside your bag.","pinyin":"","meaning":"Hãy để chìa khóa của bạn trong ngăn nhỏ bên trong túi xách."},{"hanzi":"Separate compartments on trains can provide passengers with greater privacy during long journeys.","pinyin":"","meaning":"Các khoang riêng biệt trên tàu hỏa có thể mang lại cho hành khách sự riêng tư lớn hơn trong những chuyến đi dài."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_6_1', 'en-b2-6', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_6_1_1', 'ten_b2_6_1', 'ashore', 'We went ashore to buy fresh bread and fruit.', 'We went ashore to buy fresh bread and fruit.', '/əˈʃɔːr/', 'Chúng tôi đã lên bờ để mua bánh mì và trái cây tươi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_6_1_2', 'ten_b2_6_1', 'curve', 'The driver slowed down as we approached a sharp curve.', 'The driver slowed down as we approached a sharp curve.', '/kɝːv/', 'Tài xế giảm tốc độ khi chúng tôi tiến đến một khúc cua gắt.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_6_1_3', 'ten_b2_6_1', 'seaport', 'Huge ships arrive at the seaport every morning.', 'Huge ships arrive at the seaport every morning.', '/ˈsiːpɔːrt/', 'Những con tàu khổng lồ cập cảng biển vào mỗi buổi sáng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_6_1_4', 'ten_b2_6_1', 'hospitality', 'Their warm hospitality made us feel completely at home.', 'Their warm hospitality made us feel completely at home.', '/ˌhɑːspɪˈtæləti/', 'Sự hiếu khách nồng hậu của họ khiến chúng tôi cảm thấy thoải mái như ở nhà.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_6_1_5', 'ten_b2_6_1', 'hitchhike', 'We hitchhiked to the coast with our backpacks.', 'We hitchhiked to the coast with our backpacks.', '/ˈhɪtʃhaɪk/', 'Chúng tôi đã đeo balo và đi nhờ xe đến vùng bờ biển.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_6_1_6', 'ten_b2_6_1', 'deck', 'We stood on deck and watched dolphins swim past.', 'We stood on deck and watched dolphins swim past.', '/dek/', 'Chúng tôi đứng trên boong tàu và ngắm nhìn những chú cá heo bơi lội qua.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_6_1_7', 'ten_b2_6_1', 'mainland', 'We caught the morning ferry back to the mainland.', 'We caught the morning ferry back to the mainland.', '/ˈmeɪnlənd/', 'Chúng tôi đã bắt chuyến phà buổi sáng để trở về đất liền.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_6_1_8', 'ten_b2_6_1', 'shipwreck', 'Everyone survived the shipwreck and reached the nearby island.', 'Everyone survived the shipwreck and reached the nearby island.', '/ˈʃɪprek/', 'Tất cả mọi người đều sống sót sau vụ đắm tàu và bơi được vào hòn đảo gần đó.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_6_1_1', 'en-b2-6', 'ten_b2_6_1', 'listening', 'listening', 'We went ashore to buy fresh bread and fruit.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã lên bờ để mua bánh mì và trái cây tươi.","Phòng khách sạn của chúng tôi có một bồn tắm sang trọng nhìn ra biển.","Chân tôi bị trượt khỏi bàn đạp trong cơn mưa.","Những con tàu khổng lồ cập cảng biển vào mỗi buổi sáng."]'::jsonb, 0, 'We went ashore to buy fresh bread and fruit. → Chúng tôi đã lên bờ để mua bánh mì và trái cây tươi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_6_1_2', 'en-b2-6', 'ten_b2_6_1', 'listening', 'listening', 'The driver slowed down as we approached a sharp curve.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã bắt chuyến xe buýt đưa đón miễn phí từ sân bay về khách sạn.","Phòng khách sạn của chúng tôi có một bồn tắm sang trọng nhìn ra biển.","Tài xế giảm tốc độ khi chúng tôi tiến đến một khúc cua gắt.","Hàng xóm của chúng tôi đã đi du lịch vòng quanh châu Đại Dương với một chiếc balo nhỏ."]'::jsonb, 2, 'The driver slowed down as we approached a sharp curve. → Tài xế giảm tốc độ khi chúng tôi tiến đến một khúc cua gắt.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_6_1_3', 'en-b2-6', 'ten_b2_6_1', 'listening', 'listening', 'Huge ships arrive at the seaport every morning.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chân tôi bị trượt khỏi bàn đạp trong cơn mưa.","Tài xế giảm tốc độ khi chúng tôi tiến đến một khúc cua gắt.","Chúng tôi đã lên bờ để mua bánh mì và trái cây tươi.","Những con tàu khổng lồ cập cảng biển vào mỗi buổi sáng."]'::jsonb, 3, 'Huge ships arrive at the seaport every morning. → Những con tàu khổng lồ cập cảng biển vào mỗi buổi sáng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_6_2', 'en-b2-6', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_6_2_1', 'ten_b2_6_2', 'ashore', 'Plastic waste washed ashore can damage coastal ecosystems and reduce the appeal of beaches to tourists.', 'Plastic waste washed ashore can damage coastal ecosystems and reduce the appeal of beaches to tourists.', '/əˈʃɔːr/', 'Rác thải nhựa trôi dạt vào bờ có thể tàn phá các hệ sinh thái ven biển và làm giảm sự thu hút của các bãi biển đối với khách du lịch.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_6_2_2', 'ten_b2_6_2', 'curve', 'Roads that curve around existing woodland can reduce habitat destruction, although they may increase construction costs.', 'Roads that curve around existing woodland can reduce habitat destruction, although they may increase construction costs.', '/kɝːv/', 'Những con đường uốn lượn quanh khu rừng hiện có có thể làm giảm tình trạng tàn phá môi trường sống, mặc dù chúng có thể làm tăng chi phí xây dựng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_6_2_3', 'ten_b2_6_2', 'seaport', 'Investment in modern seaports can strengthen international trade and create employment in coastal regions.', 'Investment in modern seaports can strengthen international trade and create employment in coastal regions.', '/ˈsiːpɔːrt/', 'Đầu tư vào các cảng biển hiện đại có thể thúc đẩy thương mại quốc tế và tạo việc làm ở các vùng ven biển.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_6_2_4', 'ten_b2_6_2', 'hospitality', 'The hospitality industry creates employment opportunities, but seasonal demand can make workers'' incomes less predictable.', 'The hospitality industry creates employment opportunities, but seasonal demand can make workers'' incomes less predictable.', '/ˌhɑːspɪˈtæləti/', 'Ngành dịch vụ nhà hàng khách sạn tạo ra các cơ hội việc làm, nhưng nhu cầu theo mùa có thể làm cho thu nhập của người lao động bấp bênh hơn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_6_2_5', 'ten_b2_6_2', 'hitchhike', 'Although some tourists hitchhike to reduce travel costs, limited transport services can make such journeys unpredictable.', 'Although some tourists hitchhike to reduce travel costs, limited transport services can make such journeys unpredictable.', '/ˈhɪtʃhaɪk/', 'Mặc dù một số du khách chọn đi nhờ xe để giảm chi phí đi lại, nhưng các dịch vụ giao thông hạn chế có thể khiến những hành trình như vậy trở nên khó lường.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_6_2_6', 'ten_b2_6_2', 'deck', 'Passengers on the upper deck of sightseeing buses can enjoy clear views of historic buildings.', 'Passengers on the upper deck of sightseeing buses can enjoy clear views of historic buildings.', '/dek/', 'Hành khách ở tầng trên của xe buýt ngắm cảnh có thể tận hưởng tầm nhìn quang đãng ra các công trình kiến trúc lịch sử.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_6_2_1', 'en-b2-6', 'ten_b2_6_2', 'listening', 'listening', 'Plastic waste washed ashore can damage coastal ecosystems and reduce the appeal of beaches to tourists.', NULL, 'Trong câu vừa nghe, từ “ashore” mang nghĩa nào sau đây?', '["do đó; vì vậy; kết quả là","cuộc tranh luận; cuộc thảo luận","lên bờ; vào bờ","thỉnh thoảng; đôi khi; không thường xuyên"]'::jsonb, 2, '“ashore” (/əˈʃɔːr/): lên bờ; vào bờ. Câu đầy đủ: Plastic waste washed ashore can damage coastal ecosystems and reduce the appeal of beaches to tourists.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_6_2_2', 'en-b2-6', 'ten_b2_6_2', 'listening', 'listening', 'Roads that curve around existing woodland can reduce habitat destruction, although they may increase construction costs.', NULL, 'Trong câu vừa nghe, từ “curve” mang nghĩa nào sau đây?', '["thuộc Liên Xô cũ; thuộc các hội đồng Xô-viết","chân không; khoảng trống","nghị sĩ quốc hội; hạ nghị sĩ Mỹ","đường cong; khúc cua"]'::jsonb, 3, '“curve” (/kɝːv/): đường cong; khúc cua. Câu đầy đủ: Roads that curve around existing woodland can reduce habitat destruction, although they may increase construction costs.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
