INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_6_1', 'en-b2-6', NULL, 'comprehensive_test', 'listening', 'ashore', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["lên bờ; vào bờ","sự ở nhờ nhà người bản xứ; hình thức du lịch homestay","khoản vay thế chấp mua nhà; tiền thế chấp","một món đồ trang phục, quần áo"]'::jsonb, 0, 'ashore (/əˈʃɔːr/) → lên bờ; vào bờ', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_6_2', 'en-b2-6', NULL, 'comprehensive_test', 'listening', 'The driver slowed down as we approached a sharp curve.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tài xế giảm tốc độ khi chúng tôi tiến đến một khúc cua gắt.","Con ngựa kéo một chiếc xe chở đầy táo tươi.","Hàng xóm của chúng tôi đã đi du lịch vòng quanh châu Đại Dương với một chiếc balo nhỏ.","Phòng khách sạn của chúng tôi có một bồn tắm sang trọng nhìn ra biển."]'::jsonb, 0, 'The driver slowed down as we approached a sharp curve. → Tài xế giảm tốc độ khi chúng tôi tiến đến một khúc cua gắt.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_6_3', 'en-b2-6', NULL, 'comprehensive_test', 'listening', 'seaport', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bị cấm; không được phép","thuộc về nhiếp ảnh; bằng ảnh","sự ấm áp; độ ấm","cảng biển; thành phố cảng"]'::jsonb, 3, 'seaport (/ˈsiːpɔːrt/) → cảng biển; thành phố cảng', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_6_4', 'en-b2-6', NULL, 'comprehensive_test', 'listening', 'Their warm hospitality made us feel completely at home.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã bắt chuyến xe buýt đưa đón miễn phí từ sân bay về khách sạn.","Chúng tôi đã lên bờ để mua bánh mì và trái cây tươi.","Những con tàu khổng lồ cập cảng biển vào mỗi buổi sáng.","Sự hiếu khách nồng hậu của họ khiến chúng tôi cảm thấy thoải mái như ở nhà."]'::jsonb, 3, 'Their warm hospitality made us feel completely at home. → Sự hiếu khách nồng hậu của họ khiến chúng tôi cảm thấy thoải mái như ở nhà.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_6_5', 'en-b2-6', NULL, 'comprehensive_test', 'listening', 'hitchhike', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thắng lợi lớn; thành tựu vẻ vang","ước tính; ước lượng","gãy bẻ bộp; đứt phựt","đi nhờ xe; quá giang"]'::jsonb, 3, 'hitchhike (/ˈhɪtʃhaɪk/) → đi nhờ xe; quá giang', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_6_6', 'en-b2-6', NULL, 'comprehensive_test', 'listening', 'We stood on deck and watched dolphins swim past.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sự hiếu khách nồng hậu của họ khiến chúng tôi cảm thấy thoải mái như ở nhà.","Tất cả mọi người đều sống sót sau vụ đắm tàu và bơi được vào hòn đảo gần đó.","Chúng tôi đứng trên boong tàu và ngắm nhìn những chú cá heo bơi lội qua.","Con ngựa kéo một chiếc xe chở đầy táo tươi."]'::jsonb, 2, 'We stood on deck and watched dolphins swim past. → Chúng tôi đứng trên boong tàu và ngắm nhìn những chú cá heo bơi lội qua.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_6_7', 'en-b2-6', NULL, 'comprehensive_test', 'listening', 'mainland', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["gợi ý; lời ám chỉ","vui vẻ; thú vị; dễ chịu","nhà thiên văn học","đất liền; đại lục"]'::jsonb, 3, 'mainland (/ˈmeɪnlənd/) → đất liền; đại lục; thuộc đất liền; thuộc đại lục', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_6_8', 'en-b2-6', NULL, 'comprehensive_test', 'listening', 'Everyone survived the shipwreck and reached the nearby island.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã lên bờ để mua bánh mì và trái cây tươi.","Chân tôi bị trượt khỏi bàn đạp trong cơn mưa.","Quán cà phê này hết chỗ rồi, chúng ta hãy đi nơi khác ăn đi.","Tất cả mọi người đều sống sót sau vụ đắm tàu và bơi được vào hòn đảo gần đó."]'::jsonb, 3, 'Everyone survived the shipwreck and reached the nearby island. → Tất cả mọi người đều sống sót sau vụ đắm tàu và bơi được vào hòn đảo gần đó.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
