INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_6_17', 'en-b2-6', NULL, 'comprehensive_test', 'fill_blank', NULL, NULL, 'Điền từ thích hợp vào chỗ trống:
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_6_18', 'en-b2-6', NULL, 'comprehensive_test', 'reading', NULL, 'Plastic waste washed ashore can damage coastal ecosystems and reduce the appeal of beaches to tourists.', 'Dựa vào câu trên, từ “ashore” có nghĩa phù hợp nhất là gì?', '["sự số ruột; sự bực bội do chờ đợi","lên bờ; vào bờ","nỗi đau buồn sâu sắc; niềm thương tiếc","tháo ra; tách rời"]'::jsonb, 1, 'ashore: lên bờ; vào bờ. Dịch cả câu: Rác thải nhựa trôi dạt vào bờ có thể tàn phá các hệ sinh thái ven biển và làm giảm sự thu hút của các bãi biển đối với khách du lịch.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_6_19', 'en-b2-6', NULL, 'comprehensive_test', 'reading', NULL, 'Roads that curve around existing woodland can reduce habitat destruction, although they may increase construction costs.', 'Dựa vào câu trên, từ “curve” có nghĩa phù hợp nhất là gì?', '["ma sát; lực ma sát","đường cong; khúc cua","vụ thu hoạch; mùa gặt; sản lượng thu hoạch","cơn giận; tính khí; tâm trạng cáu kỉnh"]'::jsonb, 1, 'curve: đường cong; khúc cua; uốn cong; bẻ cong. Dịch cả câu: Những con đường uốn lượn quanh khu rừng hiện có có thể làm giảm tình trạng tàn phá môi trường sống, mặc dù chúng có thể làm tăng chi phí xây dựng.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_6_20', 'en-b2-6', NULL, 'comprehensive_test', 'reading', NULL, 'Investment in modern seaports can strengthen international trade and create employment in coastal regions.', 'Dựa vào câu trên, từ “seaport” có nghĩa phù hợp nhất là gì?', '["cảng biển; thành phố cảng","truyền thuyết; sự tích","bản quyền; quyền tác giả","dừng lại; ngừng lại; làm cho dừng lại"]'::jsonb, 0, 'seaport: cảng biển; thành phố cảng. Dịch cả câu: Đầu tư vào các cảng biển hiện đại có thể thúc đẩy thương mại quốc tế và tạo việc làm ở các vùng ven biển.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_6_21', 'en-b2-6', NULL, 'comprehensive_test', 'reading', NULL, 'The hospitality industry creates employment opportunities, but seasonal demand can make workers'' incomes less predictable.', 'Dựa vào câu trên, từ “hospitality” có nghĩa phù hợp nhất là gì?', '["sự hiếu khách; lòng mến khách","cột; trụ (cấu trúc chống đỡ)","cải cách; cải tiến (hệ thống)","làm nản lòng; khiến buồn bã"]'::jsonb, 0, 'hospitality: sự hiếu khách; lòng mến khách; ngành dịch vụ nhà hàng khách sạn. Dịch cả câu: Ngành dịch vụ nhà hàng khách sạn tạo ra các cơ hội việc làm, nhưng nhu cầu theo mùa có thể làm cho thu nhập của người lao động bấp bênh hơn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_6_22', 'en-b2-6', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự đi xuống, sự hạ xuống (di chuyển từ vị trí cao xuống vị trí thấp hơn)”', '["typically","descent","function","cooperate"]'::jsonb, 1, 'sự đi xuống, sự hạ xuống (di chuyển từ vị trí cao xuống vị trí thấp hơn) → descent (/dɪˈsent/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_6_23', 'en-b2-6', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cột chỉ đường; biển chỉ đường”', '["composition","signpost","neutral","antonym"]'::jsonb, 1, 'cột chỉ đường; biển chỉ đường → signpost (/ˈsaɪnpoʊst/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_6_24', 'en-b2-6', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thuyền cứu sinh; xuồng cứu nạn”', '["navigate","counsellor","lifeboat","deed"]'::jsonb, 2, 'thuyền cứu sinh; xuồng cứu nạn → lifeboat (/ˈlaɪfboʊt/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-7', 'en', 'Bài 7: Du lịch & Di chuyển (3) - CEFR B2', 'CEFR B2', 'B2 · Du lịch', '22 từ vựng Tiếng Anh CEFR B2 chủ đề du lịch & di chuyển kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4007, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_airliner', 'en-b2-7', 'airliner', '/ˈerlaɪnər/', 'B2', 'máy bay chở khách cỡ lớn; máy bay phản lực thương mại', 'n.', 'airline (n.)', 'Đồng nghĩa: passenger aircraft', 'airliner chỉ máy bay chở khách; airline chỉ hãng hàng không chứ không phải chuyến bay.', 'We watched a huge airliner land in the rain.', NULL, 'Chúng tôi đứng xem một chiếc máy bay chở khách khổng lồ hạ cánh trong cơn mưa.', '{"wordId":"airliner","ukIpa":"/ˈeəlaɪnə/","usIpa":"/ˈerlaɪnər/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"A large aircraft used to carry paying passengers.","vi":"máy bay chở khách cỡ lớn; máy bay phản lực thương mại"}],"examples":[{"en":"We watched a huge airliner land in the rain.","vi":"Chúng tôi đứng xem một chiếc máy bay chở khách khổng lồ hạ cánh trong cơn mưa.","audioKind":"ex"},{"en":"Modern airliners can carry more passengers efficiently, although aviation remains a significant source of greenhouse gas emissions.","vi":"Các dòng máy bay chở khách hiện đại có thể vận chuyển nhiều hành khách hơn một cách hiệu quả, mặc dù ngành hàng không vẫn là nguồn phát thải khí nhà kính đáng kể.","audioKind":"ex2"}],"collocations":[{"en":"a passenger airliner","vi":"máy bay chở khách"},{"en":"a commercial airliner","vi":"máy bay thương mại"},{"en":"a jet airliner","vi":"máy bay phản lực chở khách"}],"wordFamily":["airline (n.)"],"synonyms":["passenger aircraft"],"antonyms":[],"tipVi":"airliner chỉ máy bay chở khách; airline chỉ hãng hàng không chứ không phải chuyến bay.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_carousel', 'en-b2-7', 'carousel', '/ˌkærəˈsel/', 'B2', 'vòng quay ngựa gỗ; ngựa gỗ vòng tròn; băng chuyền hành lý (tại sân bay)', 'n.', NULL, 'Đồng nghĩa: merry-go-round', 'Chỉ vòng quay ngựa gỗ hoặc băng chuyền hành lý, không dùng cho tiệc tùng ồn ào.', 'The children waved as the carousel carried them round.', NULL, 'Bọn trẻ vẫy tay khi vòng quay ngựa gỗ đưa chúng quay vòng.', '{"wordId":"carousel","ukIpa":"/ˌkærəˈsel/","usIpa":"/ˌkærəˈsel/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"A rotating fairground ride with seats often shaped like horses.","vi":"vòng quay ngựa gỗ; ngựa gỗ vòng tròn"},{"pos":"n.","en":"A moving belt carrying luggage for passengers at an airport.","vi":"băng chuyền hành lý (tại sân bay)"}],"examples":[{"en":"The children waved as the carousel carried them round.","vi":"Bọn trẻ vẫy tay khi vòng quay ngựa gỗ đưa chúng quay vòng.","audioKind":"ex"},{"en":"Clear information near each baggage carousel can help arriving passengers navigate unfamiliar airports more efficiently.","vi":"Thông tin rõ ràng gần mỗi băng chuyền hành lý có thể giúp hành khách mới đến tìm đường ở các sân bay lạ một cách hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"ride a carousel","vi":"cưỡi ngựa gỗ vòng tròn"},{"en":"baggage carousel","vi":"băng chuyền hành lý"},{"en":"carousel horse","vi":"con ngựa trên vòng quay ngựa gỗ"}],"wordFamily":[],"synonyms":["merry-go-round"],"antonyms":[],"tipVi":"Chỉ vòng quay ngựa gỗ hoặc băng chuyền hành lý, không dùng cho tiệc tùng ồn ào.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_carriage', 'en-b2-7', 'carriage', '/ˈkærɪdʒ/', 'B2', 'toa tàu khách; xe ngựa kéo; sự vận chuyển hàng hóa; cước phí vận chuyển', 'n.', 'carry (v.), carrier (n.)', NULL, 'Khoang hoặc toa tàu chở khách tiếng Anh-Anh thường dùng carriage, còn tiếng Anh-Mỹ dùng car.', 'We found two empty seats in the last carriage.', NULL, 'Chúng tôi tìm thấy hai chỗ ngồi trống ở toa tàu cuối cùng.', '{"wordId":"carriage","ukIpa":"/ˈkærɪdʒ/","usIpa":"/ˈkærɪdʒ/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"A railway vehicle in which passengers travel.","vi":"toa tàu khách"},{"pos":"n.","en":"A wheeled vehicle pulled by horses, usually carrying people.","vi":"xe ngựa kéo"},{"pos":"n.","en":"The transport of goods, or the charge for this.","vi":"sự vận chuyển hàng hóa; cước phí vận chuyển"}],"examples":[{"en":"We found two empty seats in the last carriage.","vi":"Chúng tôi tìm thấy hai chỗ ngồi trống ở toa tàu cuối cùng.","audioKind":"ex"},{"en":"Adding an extra carriage to each train could reduce overcrowding and improve the daily experience of commuters.","vi":"Việc thêm một toa tàu vào mỗi chuyến đoàn tàu có thể làm giảm tình trạng quá tải và cải thiện trải nghiệm đi lại hàng ngày của những người đi làm.","audioKind":"ex2"}],"collocations":[{"en":"railway carriage","vi":"toa xe lửa"},{"en":"horse-drawn carriage","vi":"xe ngựa kéo"},{"en":"carriage costs","vi":"chi phí vận chuyển"}],"wordFamily":["carry (v.)","carrier (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khoang hoặc toa tàu chở khách tiếng Anh-Anh thường dùng carriage, còn tiếng Anh-Mỹ dùng car.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cuisine', 'en-b2-7', 'cuisine', '/kwɪˈziːn/', 'B2', 'phong cách nấu nướng; ẩm thực; nền văn hóa ẩm thực', 'n.', NULL, NULL, 'Từ "cuisine" dùng để chỉ trường phái ẩm thực hoặc cách nấu nướng, không dùng để chỉ một món ăn đơn lẻ.', 'This little restaurant serves delicious cuisine from southern India.', NULL, 'Nhà hàng nhỏ này phục vụ các món ăn ngon mang hương vị miền Nam Ấn Độ.', '{"wordId":"cuisine","ukIpa":"/kwɪˈziːn/","usIpa":"/kwɪˈziːn/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"A style of cooking associated with a place or culture.","vi":"phong cách nấu nướng; ẩm thực; nền văn hóa ẩm thực"}],"examples":[{"en":"This little restaurant serves delicious cuisine from southern India.","vi":"Nhà hàng nhỏ này phục vụ các món ăn ngon mang hương vị miền Nam Ấn Độ.","audioKind":"ex"},{"en":"Traditional cuisine can attract international tourists while helping local communities preserve their cultural identity.","vi":"Ẩm thực truyền thống có thể thu hút khách du lịch quốc tế đồng thời giúp cộng đồng địa phương bảo tồn bản sắc văn hóa của họ.","audioKind":"ex2"}],"collocations":[{"en":"local cuisine","vi":"ẩm thực địa phương"},{"en":"traditional cuisine","vi":"ẩm thực truyền thống"},{"en":"international cuisine","vi":"ẩm thực quốc tế"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Từ \"cuisine\" dùng để chỉ trường phái ẩm thực hoặc cách nấu nướng, không dùng để chỉ một món ăn đơn lẻ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cruise', 'en-b2-7', 'cruise', '/kruːz/', 'B2', 'chuyến du ngoạn trên biển; chuyến đi bằng tàu thủy; di chuyển đều tốc; lướt đi êm ái', 'n.', 'cruiser (n.)', NULL, 'Khi đóng vai trò là danh từ chỉ một chuyến du ngoạn trên biển, từ này đếm được: a cruise.', 'We took a cruise around the islands last summer.', NULL, 'Mùa hè năm ngoái, chúng tôi đã đi chuyến du thuyền vòng quanh các hòn đảo.', '{"wordId":"cruise","ukIpa":"/kruːz/","usIpa":"/kruːz/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"a holiday travelling by ship and visiting different places","vi":"chuyến du ngoạn trên biển; chuyến đi bằng tàu thủy"},{"pos":"v.","en":"to travel smoothly at a steady speed","vi":"di chuyển đều tốc; lướt đi êm ái"}],"examples":[{"en":"We took a cruise around the islands last summer.","vi":"Mùa hè năm ngoái, chúng tôi đã đi chuyến du thuyền vòng quanh các hòn đảo.","audioKind":"ex"},{"en":"The growing popularity of cruise holidays has raised concerns about air pollution in coastal cities.","vi":"Sự phổ biến ngày càng tăng của các kỳ nghỉ trên tàu du lịch đã dấy lên những lo ngại về ô nhiễm không khí tại các thành phố ven biển.","audioKind":"ex2"}],"collocations":[{"en":"go on a cruise","vi":"đi du thuyền"},{"en":"cruise ship","vi":"tàu du lịch"},{"en":"cruise along","vi":"lướt đi êm ái"}],"wordFamily":["cruiser (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi đóng vai trò là danh từ chỉ một chuyến du ngoạn trên biển, từ này đếm được: a cruise.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_halt', 'en-b2-7', 'halt', '/hɔːlt/', 'B2', 'dừng lại; ngừng lại; làm cho dừng lại; sự dừng lại; sự ngừng trệ', 'v.', NULL, 'Đồng nghĩa: stop, cease · Trái nghĩa: continue', 'Từ halt mang tính trang trọng hơn stop; cụm từ come to a halt diễn tả hành động dừng lại hoàn toàn.', 'The bus halted suddenly when a sheep crossed.', NULL, 'Chiếc xe buýt dừng lại đột ngột khi có một con cừu băng qua đường.', '{"wordId":"halt","ukIpa":"/hɔːlt/","usIpa":"/hɔːlt/","cefr":"B2","topic":"travel","senses":[{"pos":"v.","en":"to stop moving or happening, or make something stop","vi":"dừng lại; ngừng lại; làm cho dừng lại"},{"pos":"n.","en":"a stop in movement, activity, or progress","vi":"sự dừng lại; sự ngừng trệ"}],"examples":[{"en":"The bus halted suddenly when a sheep crossed.","vi":"Chiếc xe buýt dừng lại đột ngột khi có một con cừu băng qua đường.","audioKind":"ex"},{"en":"Urgent international cooperation is needed to halt the destruction of habitats and protect species at risk of extinction.","vi":"Cần có sự hợp tác quốc tế khẩn cấp để ngăn chặn sự tàn phá môi trường sống và bảo vệ các loài có nguy cơ tuyệt chủng.","audioKind":"ex2"}],"collocations":[{"en":"come to a halt","vi":"dừng lại"},{"en":"bring to a halt","vi":"làm cho dừng lại"},{"en":"halt production","vi":"ngừng sản xuất"},{"en":"halt the decline","vi":"ngăn chặn sự suy giảm"}],"wordFamily":[],"synonyms":["stop","cease"],"antonyms":["continue"],"tipVi":"Từ halt mang tính trang trọng hơn stop; cụm từ come to a halt diễn tả hành động dừng lại hoàn toàn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_overseas', 'en-b2-7', 'overseas', '/ˌoʊvɚˈsiːz/', 'B2', 'ở nước ngoài; ra nước ngoài; thuộc nước ngoài; đến từ nước ngoài', 'adv.', NULL, 'Đồng nghĩa: abroad', 'Khi làm phó từ, không dùng giới từ to trước overseas (ví dụ: go overseas); từ này cũng có thể đứng trước để bổ nghĩa cho danh từ.', 'My cousin moved overseas and calls us every weekend.', NULL, 'Anh họ tôi đã chuyển ra nước ngoài sinh sống và gọi điện cho chúng tôi vào mỗi cuối tuần.', '{"wordId":"overseas","ukIpa":"/ˌəʊvəˈsiːz/","usIpa":"/ˌoʊvɚˈsiːz/","cefr":"B2","topic":"travel","senses":[{"pos":"adv.","en":"in or to a foreign country","vi":"ở nước ngoài; ra nước ngoài"},{"pos":"adj.","en":"located in, coming from, or relating to foreign countries","vi":"ở nước ngoài; thuộc nước ngoài; đến từ nước ngoài"}],"examples":[{"en":"My cousin moved overseas and calls us every weekend.","vi":"Anh họ tôi đã chuyển ra nước ngoài sinh sống và gọi điện cho chúng tôi vào mỗi cuối tuần.","audioKind":"ex"},{"en":"Studying overseas can broaden students'' perspectives, although adapting to a different culture often takes time.","vi":"Đi du học có thể mở rộng tầm nhìn của học sinh, mặc dù việc thích nghi với một nền văn hóa khác thường cần có thời gian.","audioKind":"ex2"}],"collocations":[{"en":"study overseas","vi":"du học"},{"en":"work overseas","vi":"làm việc ở nước ngoài"},{"en":"overseas markets","vi":"thị trường nước ngoài"},{"en":"overseas students","vi":"du học sinh"}],"wordFamily":[],"synonyms":["abroad"],"antonyms":[],"tipVi":"Khi làm phó từ, không dùng giới từ to trước overseas (ví dụ: go overseas); từ này cũng có thể đứng trước để bổ nghĩa cho danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_excursion', 'en-b2-7', 'excursion', '/ɪkˈskɝːʒən/', 'B2', 'chuyến tham quan; cuộc dã ngoại', 'n.', NULL, 'Đồng nghĩa: outing, trip', 'Thường chỉ chuyến đi ngắn mang tính giải trí theo nhóm, đi kèm với cụm từ go on an excursion.', 'We packed sandwiches for our excursion to the lake.', NULL, 'Chúng tôi đã chuẩn bị bánh mì kẹp cho chuyến dã ngoại ra hồ.', '{"wordId":"excursion","ukIpa":"/ɪkˈskɜːʃən/","usIpa":"/ɪkˈskɝːʒən/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"A short journey made for pleasure, often with a group.","vi":"chuyến tham quan; cuộc dã ngoại"}],"examples":[{"en":"We packed sandwiches for our excursion to the lake.","vi":"Chúng tôi đã chuẩn bị bánh mì kẹp cho chuyến dã ngoại ra hồ.","audioKind":"ex"},{"en":"School excursions to nature reserves can deepen students'' understanding of local wildlife and conservation.","vi":"Các chuyến tham quan khu bảo tồn thiên nhiên của trường học có thể làm sâu sắc thêm hiểu biết của học sinh về động vật hoang dã và công tác bảo tồn địa phương.","audioKind":"ex2"}],"collocations":[{"en":"go on an excursion","vi":"đi dã ngoại"},{"en":"a day excursion","vi":"chuyến đi trong ngày"},{"en":"a school excursion","vi":"chuyến tham quan do trường tổ chức"}],"wordFamily":[],"synonyms":["outing","trip"],"antonyms":[],"tipVi":"Thường chỉ chuyến đi ngắn mang tính giải trí theo nhóm, đi kèm với cụm từ go on an excursion.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_descend', 'en-b2-7', 'descend', '/dɪˈsend/', 'B2', 'đi xuống; hạ xuống', 'v.', 'descent (n.), descendant (n.)', 'Đồng nghĩa: go down · Trái nghĩa: ascend, rise', 'Có thể trực tiếp kết hợp với stairs; dùng "be descended from" để chỉ là hậu duệ của ai đó.', 'We descended the narrow stairs into a cool cellar.', NULL, 'Chúng tôi đi xuống chiếc cầu thang hẹp để vào một căn hầm mát mẻ.', '{"wordId":"descend","ukIpa":"/dɪˈsend/","usIpa":"/dɪˈsend/","cefr":"B2","topic":"travel","senses":[{"pos":"v.","en":"to move down or go to a lower position","vi":"đi xuống; hạ xuống"}],"examples":[{"en":"We descended the narrow stairs into a cool cellar.","vi":"Chúng tôi đi xuống chiếc cầu thang hẹp để vào một căn hầm mát mẻ.","audioKind":"ex"},{"en":"As aircraft descend towards urban airports, their noise can significantly affect the quality of life in nearby communities.","vi":"Khi máy bay hạ độ cao hướng về các sân bay đô thị, tiếng ồn của chúng có thể ảnh hưởng đáng kể đến chất lượng cuộc sống của cộng đồng dân cư gần đó.","audioKind":"ex2"}],"collocations":[{"en":"descend the stairs","vi":"đi xuống cầu thang"},{"en":"descend into a valley","vi":"đi xuống thung lũng"},{"en":"be descended from","vi":"là hậu duệ của"}],"wordFamily":["descent (n.)","descendant (n.)"],"synonyms":["go down"],"antonyms":["ascend","rise"],"tipVi":"Có thể trực tiếp kết hợp với stairs; dùng \"be descended from\" để chỉ là hậu duệ của ai đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_parachute', 'en-b2-7', 'parachute', '/ˈpærəʃuːt/', 'B2', 'dù; cái dù; nhảy dù; thả dù', 'n.', 'parachutist (n.), parachuting (n.)', NULL, 'Khi là động từ, từ này có thể chỉ người nhảy dù hoặc thả vật tư từ trên không.', 'Her parachute opened smoothly above the green fields.', NULL, 'Chiếc dù của cô ấy mở bung ra một cách suôn sẻ phía trên những cánh đồng xanh ngắt.', '{"wordId":"parachute","ukIpa":"/ˈpærəʃuːt/","usIpa":"/ˈpærəʃuːt/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"Equipment that slows a fall through the air","vi":"dù; cái dù"},{"pos":"v.","en":"To jump or drop something from aircraft using a parachute","vi":"nhảy dù; thả dù"}],"examples":[{"en":"Her parachute opened smoothly above the green fields.","vi":"Chiếc dù của cô ấy mở bung ra một cách suôn sẻ phía trên những cánh đồng xanh ngắt.","audioKind":"ex"},{"en":"Rescue teams used parachutes to deliver essential supplies to villages isolated by severe flooding.","vi":"Các đội cứu hộ đã dùng dù để chuyển vật tư thiết yếu đến các ngôi làng bị cô lập do lũ lụt nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"open a parachute","vi":"mở dù"},{"en":"parachute jump","vi":"cú nhảy dù"},{"en":"parachute supplies into","vi":"thả dù hàng cứu trợ xuống"}],"wordFamily":["parachutist (n.)","parachuting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi là động từ, từ này có thể chỉ người nhảy dù hoặc thả vật tư từ trên không.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hold-up', 'en-b2-7', 'hold-up', '/ˈhoʊld ʌp/', 'B2', 'sự chậm trễ; sự tắc nghẽn; vụ cướp có vũ trang', 'n.', NULL, 'Đồng nghĩa: delay, robbery', 'Dạng danh từ có dấu gạch nối; cụm động từ tương ứng được viết là hold up.', 'A hold-up on the bridge made us miss lunch.', NULL, 'Sự cố tắc nghẽn trên cầu đã khiến chúng tôi lỡ bữa trưa.', '{"wordId":"hold-up","ukIpa":"/ˈhəʊld ʌp/","usIpa":"/ˈhoʊld ʌp/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"A delay that prevents something from continuing as planned","vi":"sự chậm trễ; sự tắc nghẽn"},{"pos":"n.","en":"A robbery involving threats with a weapon","vi":"vụ cướp có vũ trang"}],"examples":[{"en":"A hold-up on the bridge made us miss lunch.","vi":"Sự cố tắc nghẽn trên cầu đã khiến chúng tôi lỡ bữa trưa.","audioKind":"ex"},{"en":"Even a brief hold-up in the supply chain can significantly increase costs for small manufacturers.","vi":"Ngay cả một sự chậm trễ nhỏ trong chuỗi cung ứng cũng có thể làm tăng đáng kể chi phí đối với các nhà sản xuất quy mô nhỏ.","audioKind":"ex2"}],"collocations":[{"en":"traffic hold-up","vi":"tắc nghẽn giao thông"},{"en":"a lengthy hold-up","vi":"một sự chậm trễ kéo dài"},{"en":"an armed hold-up","vi":"một vụ cướp có vũ trang"}],"wordFamily":[],"synonyms":["delay","robbery"],"antonyms":[],"tipVi":"Dạng danh từ có dấu gạch nối; cụm động từ tương ứng được viết là hold up.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wreck', 'en-b2-7', 'wreck', '/rek/', 'B2', 'xác tàu đắm; phương tiện bị hư hỏng nặng; làm hỏng nặng; phá hoại', 'n.', 'wreckage (n.), wrecked (adj.)', NULL, 'wreck có thể chỉ một chiếc tàu bị tai nạn; wreckage dùng chung để chỉ phần tàn tích.', 'Divers found a shipwreck beside the wreck of a submarine.', NULL, 'Các thợ lặn tìm thấy một con tàu đắm nằm bên cạnh xác một chiếc tàu ngầm.', '{"wordId":"wreck","ukIpa":"/rek/","usIpa":"/rek/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"A ship or vehicle that has been badly damaged.","vi":"xác tàu đắm; phương tiện bị hư hỏng nặng"},{"pos":"v.","en":"To badly damage something or ruin a plan.","vi":"làm hỏng nặng; phá hoại"}],"examples":[{"en":"Divers found a shipwreck beside the wreck of a submarine.","vi":"Các thợ lặn tìm thấy một con tàu đắm nằm bên cạnh xác một chiếc tàu ngầm.","audioKind":"ex"},{"en":"Poorly planned construction can wreck historic neighbourhoods and permanently reduce their cultural value for future generations.","vi":"Việc xây dựng được quy hoạch kém có thể phá hủy các khu phố lịch sử và làm giảm vĩnh viễn giá trị văn hóa của chúng đối với các thế hệ tương lai.","audioKind":"ex2"}],"collocations":[{"en":"a shipwreck''s wreck","vi":"xác tàu chìm"},{"en":"a car wreck","vi":"xác xe ô tô hỏng"},{"en":"wreck someone''s plans","vi":"làm hỏng kế hoạch của ai đó"}],"wordFamily":["wreckage (n.)","wrecked (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"wreck có thể chỉ một chiếc tàu bị tai nạn; wreckage dùng chung để chỉ phần tàn tích.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cargo', 'en-b2-7', 'cargo', '/ˈkɑːrɡoʊ/', 'B2', 'hàng hóa (chuyên chở bằng tàu thủy, máy bay hoặc phương tiện lớn)', 'n.', NULL, 'Đồng nghĩa: freight', 'cargo thường chỉ hàng hóa thương mại được vận chuyển, không dùng cho hành lý xách tay của hành khách.', 'The crane lifted the cargo onto the waiting ship.', NULL, 'Cần cẩu đã cẩu hàng hóa lên con tàu đang chờ sẵn.', '{"wordId":"cargo","ukIpa":"/ˈkɑːɡəʊ/","usIpa":"/ˈkɑːrɡoʊ/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"goods carried by a ship, aircraft, or other large vehicle","vi":"hàng hóa (chuyên chở bằng tàu thủy, máy bay hoặc phương tiện lớn)"}],"examples":[{"en":"The crane lifted the cargo onto the waiting ship.","vi":"Cần cẩu đã cẩu hàng hóa lên con tàu đang chờ sẵn.","audioKind":"ex"},{"en":"Moving cargo by rail rather than road can reduce emissions and ease congestion on major highways.","vi":"Vận chuyển hàng hóa bằng đường sắt thay vì đường bộ có thể làm giảm lượng khí thải và giảm bớt tình trạng ùn tắc trên các tuyến cao tốc chính.","audioKind":"ex2"}],"collocations":[{"en":"cargo ship","vi":"tàu chở hàng"},{"en":"air cargo","vi":"hàng không vận"},{"en":"load cargo","vi":"xếp hàng hóa"},{"en":"cargo hold","vi":"khoang chứa hàng"}],"wordFamily":[],"synonyms":["freight"],"antonyms":[],"tipVi":"cargo thường chỉ hàng hóa thương mại được vận chuyển, không dùng cho hành lý xách tay của hành khách.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_automobile', 'en-b2-7', 'automobile', '/ˈɔːtəməbiːl/', 'B2', 'xe ô tô', 'n.', 'automotive (adj.)', 'Đồng nghĩa: car', 'Chủ yếu dùng trong tiếng Anh-Mỹ, mang tính trang trọng; giao tiếp hàng ngày thường dùng car.', 'My grandfather keeps a vintage automobile in his garage.', NULL, 'Ông tôi giữ một chiếc ô tô cổ trong gara của ông.', '{"wordId":"automobile","ukIpa":"/ˈɔːtəməbiːl/","usIpa":"/ˈɔːtəməbiːl/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"a road vehicle with an engine, usually carrying few passengers","vi":"xe ô tô"}],"examples":[{"en":"My grandfather keeps a vintage automobile in his garage.","vi":"Ông tôi giữ một chiếc ô tô cổ trong gara của ông.","audioKind":"ex"},{"en":"Growth in automobile ownership has increased pressure on road networks and contributed to urban air pollution.","vi":"Sự gia tăng về quyền sở hữu ô tô đã tạo thêm áp lực lên hệ thống đường bộ và góp phần gây ô nhiễm không khí đô thị.","audioKind":"ex2"}],"collocations":[{"en":"automobile industry","vi":"ngành công nghiệp ô tô"},{"en":"automobile manufacturer","vi":"nhà sản xuất ô tô"},{"en":"automobile ownership","vi":"quyền sở hữu ô tô"}],"wordFamily":["automotive (adj.)"],"synonyms":["car"],"antonyms":[],"tipVi":"Chủ yếu dùng trong tiếng Anh-Mỹ, mang tính trang trọng; giao tiếp hàng ngày thường dùng car.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_westward', 'en-b2-7', 'westward', '/ˈwestwərd/', 'B2', 'về hướng tây; hướng tây; về phía tây', 'adv.', 'west (n.), western (adj.), westwards (adv.)', 'Đồng nghĩa: westwards · Trái nghĩa: eastward', 'westward có thể đóng vai trò là tính từ hoặc trạng từ; westwards chỉ dùng làm trạng từ.', 'We drove westward as the sun began to set.', NULL, 'Chúng tôi lái xe hướng về phía tây khi mặt trời bắt đầu lặn.', '{"wordId":"westward","ukIpa":"/ˈwestwəd/","usIpa":"/ˈwestwərd/","cefr":"B2","topic":"travel","senses":[{"pos":"adv.","en":"towards the west","vi":"về hướng tây; hướng tây"},{"pos":"adj.","en":"moving or pointing towards the west","vi":"hướng tây; về phía tây"}],"examples":[{"en":"We drove westward as the sun began to set.","vi":"Chúng tôi lái xe hướng về phía tây khi mặt trời bắt đầu lặn.","audioKind":"ex"},{"en":"The westward expansion of the city has increased pressure on farmland and created demand for new infrastructure.","vi":"Sự mở ức về hướng tây của thành phố đã làm gia tăng áp lực lên đất nông nghiệp và tạo ra nhu cầu về cơ sở hạ tầng mới.","audioKind":"ex2"}],"collocations":[{"en":"travel westward","vi":"đi về hướng tây"},{"en":"westward expansion","vi":"sự mở rộng về hướng tây"},{"en":"westward migration","vi":"sự di cư về hướng tây"}],"wordFamily":["west (n.)","western (adj.)","westwards (adv.)"],"synonyms":["westwards"],"antonyms":["eastward"],"tipVi":"westward có thể đóng vai trò là tính từ hoặc trạng từ; westwards chỉ dùng làm trạng từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_retreat', 'en-b2-7', 'retreat', '/rɪˈtriːt/', 'B2', 'rút lui; thoái lui; sự rút lui; sự thoái lui; nơi nghỉ dưỡng; chốn bình yên', 'v.', NULL, 'Đồng nghĩa: withdraw · Trái nghĩa: advance', 'retreat nhấn mạnh hành động lùi về phía sau; nghĩa danh từ chỉ nơi tĩnh dưỡng cũng rất phổ biến.', 'We retreated indoors when the rain began falling heavily.', NULL, 'Chúng tôi đã rút vào trong nhà khi trời bắt đầu đổ mưa lớn.', '{"wordId":"retreat","ukIpa":"/rɪˈtriːt/","usIpa":"/rɪˈtriːt/","cefr":"B2","topic":"travel","senses":[{"pos":"v.","en":"To move back or away from danger or difficulty.","vi":"rút lui; thoái lui"},{"pos":"n.","en":"An act of moving back or away from something.","vi":"sự rút lui; sự thoái lui"},{"pos":"n.","en":"A quiet place where people go to rest.","vi":"nơi nghỉ dưỡng; chốn bình yên"}],"examples":[{"en":"We retreated indoors when the rain began falling heavily.","vi":"Chúng tôi đã rút vào trong nhà khi trời bắt đầu đổ mưa lớn.","audioKind":"ex"},{"en":"As glaciers retreat due to rising temperatures, communities downstream face increasing uncertainty about their future water supplies.","vi":"Khi băng hà rút lui do nhiệt độ tăng, các cộng đồng ở hạ lưu phải đối mặt với sự bất định ngày càng lớn về nguồn nước trong tương lai.","audioKind":"ex2"}],"collocations":[{"en":"retreat from","vi":"rút lui khỏi"},{"en":"beat a retreat","vi":"vội vã rút lui"},{"en":"mountain retreat","vi":"nơi nghỉ dưỡng trên núi"}],"wordFamily":[],"synonyms":["withdraw"],"antonyms":["advance"],"tipVi":"retreat nhấn mạnh hành động lùi về phía sau; nghĩa danh từ chỉ nơi tĩnh dưỡng cũng rất phổ biến.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_paradise', 'en-b2-7', 'paradise', '/ˈpærədaɪs/', 'B2', 'thiên đường; chốn bồng lai tiên cảnh; nơi lý tưởng; cõi thiên đàng', 'n.', 'paradisiacal (adj.)', 'Đồng nghĩa: heaven, utopia', 'a paradise for theo sau là người hoặc động vật, chỉ nơi chốn lý tưởng cho họ.', 'This quiet beach is a paradise for swimmers.', NULL, 'Bãi biển yên tĩnh này là thiên đường dành cho những người thích bơi lội.', '{"wordId":"paradise","ukIpa":"/ˈpærədaɪs/","usIpa":"/ˈpærədaɪs/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"A place or situation offering great beauty, happiness, or enjoyment","vi":"thiên đường; chốn bồng lai tiên cảnh; nơi lý tưởng"},{"pos":"n.","en":"A perfect place of happiness after death in some religions","vi":"cõi thiên đàng"}],"examples":[{"en":"This quiet beach is a paradise for swimmers.","vi":"Bãi biển yên tĩnh này là thiên đường dành cho những người thích bơi lội.","audioKind":"ex"},{"en":"Although tourism can turn remote islands into holiday paradises, uncontrolled development may damage the ecosystems that attract visitors.","vi":"Mặc dù ngành du lịch có thể biến những hòn đảo hẻo lánh thành thiên đường nghỉ dưỡng, việc phát triển không kiểm soát có thể phá hủy các hệ sinh thái thu hút du khách.","audioKind":"ex2"}],"collocations":[{"en":"a tropical paradise","vi":"thiên đường nhiệt đới"},{"en":"a paradise for wildlife","vi":"thiên đường của động vật hoang dã"},{"en":"an island paradise","vi":"thiên đường đảo ngọc"}],"wordFamily":["paradisiacal (adj.)"],"synonyms":["heaven","utopia"],"antonyms":[],"tipVi":"a paradise for theo sau là người hoặc động vật, chỉ nơi chốn lý tưởng cho họ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_anchor', 'en-b2-7', 'anchor', '/ˈæŋkər/', 'B2', 'cái neo; mỏ neo; thả neo; neo đậu; cố định chặt; chỗ dựa tinh thần; điểm tựa vững chắc', 'n.', 'anchorage (n.)', NULL, '"drop anchor" nghĩa là thả neo; "weigh anchor" nghĩa là nhổ neo, không phải cân nặng.', 'We dropped the anchor beside a quiet island.', NULL, 'Chúng tôi đã thả neo bên cạnh một hòn đảo yên tĩnh.', '{"wordId":"anchor","ukIpa":"/ˈæŋkə/","usIpa":"/ˈæŋkər/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"A heavy object that holds a boat in place underwater.","vi":"cái neo; mỏ neo"},{"pos":"v.","en":"To secure a boat with an anchor or fix something firmly.","vi":"thả neo; neo đậu; cố định chặt"},{"pos":"n.","en":"A person or thing providing stability and support.","vi":"chỗ dựa tinh thần; điểm tựa vững chắc"}],"examples":[{"en":"We dropped the anchor beside a quiet island.","vi":"Chúng tôi đã thả neo bên cạnh một hòn đảo yên tĩnh.","audioKind":"ex"},{"en":"Strong community networks can provide an anchor for families adapting to life in unfamiliar cities.","vi":"Mạng lưới cộng đồng vững mạnh có thể mang lại điểm tựa vững chắc cho các gia đình đang thích nghi với cuộc sống ở những thành phố xa lạ.","audioKind":"ex2"}],"collocations":[{"en":"drop anchor","vi":"thả neo"},{"en":"weigh anchor","vi":"nhổ neo"},{"en":"anchor a boat","vi":"neo thuyền"},{"en":"an emotional anchor","vi":"chỗ dựa tinh thần"}],"wordFamily":["anchorage (n.)"],"synonyms":[],"antonyms":[],"tipVi":"\"drop anchor\" nghĩa là thả neo; \"weigh anchor\" nghĩa là nhổ neo, không phải cân nặng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fleet', 'en-b2-7', 'fleet', '/fliːt/', 'B2', 'hạm đội; đội tàu thủy; đội xe; đội máy bay', 'n.', NULL, NULL, 'Đây là danh từ tập hợp; cụm từ a fleet of có thể đi với tàu thuyền, xe cộ hoặc máy bay.', 'A fleet of fishing boats returned before sunset.', NULL, 'Một đoàn thuyền đánh cá đã quay trở về trước khi mặt trời lặn.', '{"wordId":"fleet","ukIpa":"/fliːt/","usIpa":"/fliːt/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"a group of ships controlled or operated together","vi":"hạm đội; đội tàu thủy"},{"pos":"n.","en":"vehicles or aircraft owned or operated by one organisation","vi":"đội xe; đội máy bay"}],"examples":[{"en":"A fleet of fishing boats returned before sunset.","vi":"Một đoàn thuyền đánh cá đã quay trở về trước khi mặt trời lặn.","audioKind":"ex"},{"en":"Replacing the city''s ageing bus fleet with electric vehicles could significantly reduce air pollution in residential areas.","vi":"Việc thay thế đội xe buýt đã cũ của thành phố bằng các phương tiện chạy điện có thể làm giảm đáng kể tình trạng ô nhiễm không khí tại các khu dân cư.","audioKind":"ex2"}],"collocations":[{"en":"fishing fleet","vi":"đội tàu đánh cá"},{"en":"naval fleet","vi":"hạm đội hải quân"},{"en":"bus fleet","vi":"đội xe buýt"},{"en":"a fleet of vehicles","vi":"một đoàn xe"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Đây là danh từ tập hợp; cụm từ a fleet of có thể đi với tàu thuyền, xe cộ hoặc máy bay.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_steer', 'en-b2-7', 'steer', '/stɪr/', 'B2', 'lái (xe, thuyền); điều khiển hướng đi; dẫn dắt; định hướng (hành động hoặc sự phát triển); bò đực nghiến (bò đực bị thiến để lấy thịt)', 'v.', 'steering (n.)', 'Đồng nghĩa: guide, direct', 'Cụm từ steer clear of mang nghĩa là tránh xa ai đó hoặc cái gì đó.', 'She carefully steered the boat away from the rocks.', NULL, 'Cô ấy cẩn thận lái con thuyền tránh xa các mỏm đá.', '{"wordId":"steer","ukIpa":"/stɪə/","usIpa":"/stɪr/","cefr":"B2","topic":"travel","senses":[{"pos":"v.","en":"To control the direction in which a vehicle moves.","vi":"lái (xe, thuyền); điều khiển hướng đi"},{"pos":"v.","en":"To guide someone''s actions or the development of something.","vi":"dẫn dắt; định hướng (hành động hoặc sự phát triển)"},{"pos":"n.","en":"A male cow castrated and usually raised for meat.","vi":"bò đực nghiến (bò đực bị thiến để lấy thịt)"}],"examples":[{"en":"She carefully steered the boat away from the rocks.","vi":"Cô ấy cẩn thận lái con thuyền tránh xa các mỏm đá.","audioKind":"ex"},{"en":"Governments can steer investment towards renewable energy by offering financial incentives and establishing clear environmental standards.","vi":"Chính phủ có thể định hướng dòng vốn đầu tư vào năng lượng tái tạo bằng cách đưa ra các ưu đãi tài chính và thiết lập các tiêu chuẩn môi trường rõ ràng.","audioKind":"ex2"}],"collocations":[{"en":"steer a boat","vi":"lái thuyền"},{"en":"steer clear of","vi":"tránh xa"},{"en":"steer the conversation","vi":"dẫn dắt cuộc trò chuyện"}],"wordFamily":["steering (n.)"],"synonyms":["guide","direct"],"antonyms":[],"tipVi":"Cụm từ steer clear of mang nghĩa là tránh xa ai đó hoặc cái gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tanker', 'en-b2-7', 'tanker', '/ˈtæŋkər/', 'B2', 'tàu chở dầu; tàu chở chất lỏng; xe bồn; xe chở nhiên liệu', 'n.', 'tank (n.)', NULL, 'Danh từ tank chỉ thùng chứa; tanker chỉ tàu hoặc xe chuyên dụng để vận chuyển chất lỏng.', 'We watched a huge tanker sail into the harbour.', NULL, 'Chúng tôi đứng nhìn một chiếc tàu chở dầu khổng lồ tiến vào cảng.', '{"wordId":"tanker","ukIpa":"/ˈtæŋkə/","usIpa":"/ˈtæŋkər/","cefr":"B2","topic":"travel","senses":[{"pos":"n.","en":"A ship designed to carry large quantities of liquid","vi":"tàu chở dầu; tàu chở chất lỏng"},{"pos":"n.","en":"A road vehicle carrying liquids or gases in a large tank","vi":"xe bồn; xe chở nhiên liệu"}],"examples":[{"en":"We watched a huge tanker sail into the harbour.","vi":"Chúng tôi đứng nhìn một chiếc tàu chở dầu khổng lồ tiến vào cảng.","audioKind":"ex"},{"en":"An accident involving an oil tanker can cause lasting damage to coastal ecosystems.","vi":"Một vụ tai nạn liên quan đến xe chở dầu có thể gây ra những tổn hại lâu dài đối với hệ sinh thái ven biển.","audioKind":"ex2"}],"collocations":[{"en":"oil tanker","vi":"tàu chở dầu"},{"en":"fuel tanker","vi":"xe bồn chở nhiên liệu"},{"en":"tanker truck","vi":"xe tải bồn"}],"wordFamily":["tank (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ tank chỉ thùng chứa; tanker chỉ tàu hoặc xe chuyên dụng để vận chuyển chất lỏng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_navigate', 'en-b2-7', 'navigate', '/ˈnævɪɡeɪt/', 'B2', 'dẫn đường; xác định phương hướng; điều hướng; lướt (trang web); giải quyết; ứng phó', 'v.', 'navigation (n.), navigator (n.), navigational (adj.), navigable (adj.)', NULL, 'Có thể kết hợp trực tiếp với địa điểm hoặc trang web, hoặc dùng với navigate through.', 'We used a map to navigate the narrow streets.', NULL, 'Chúng tôi dùng bản đồ để tìm đường qua những con phố chật hẹp.', '{"wordId":"navigate","ukIpa":"/ˈnævɪɡeɪt/","usIpa":"/ˈnævɪɡeɪt/","cefr":"B2","topic":"travel","senses":[{"pos":"v.","en":"to find or direct the way to a destination","vi":"dẫn đường; xác định phương hướng"},{"pos":"v.","en":"to move around a website or digital system","vi":"điều hướng; lướt (trang web)"},{"pos":"v.","en":"to deal successfully with a complicated situation","vi":"giải quyết; ứng phó"}],"examples":[{"en":"We used a map to navigate the narrow streets.","vi":"Chúng tôi dùng bản đồ để tìm đường qua những con phố chật hẹp.","audioKind":"ex"},{"en":"Clear website design helps users navigate public services and access essential information without unnecessary delays.","vi":"Thiết kế trang web rõ ràng giúp người dùng tìm kiếm thông tin dịch vụ công cộng và tiếp cận các thông tin thiết yếu mà không bị trì hoãn vô ích.","audioKind":"ex2"}],"collocations":[{"en":"navigate a website","vi":"lướt trang web"},{"en":"navigate through traffic","vi":"đi xuyên qua dòng xe cộ"},{"en":"navigate unfamiliar terrain","vi":"tìm đường ở địa hình xa lạ"},{"en":"navigate a crisis","vi":"vượt qua một cuộc khủng hoảng"}],"wordFamily":["navigation (n.)","navigator (n.)","navigational (adj.)","navigable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể kết hợp trực tiếp với địa điểm hoặc trang web, hoặc dùng với navigate through.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_7_1', 'en-b2-7', 'Cách dùng “overseas” (adv.) — ở nước ngoài; ra nước ngoài', 'study overseas  ·  work overseas  ·  overseas markets', 'Khi làm phó từ, không dùng giới từ to trước overseas (ví dụ: go overseas); từ này cũng có thể đứng trước để bổ nghĩa cho danh từ.', 'Đồng nghĩa: abroad', '[{"hanzi":"My cousin moved overseas and calls us every weekend.","pinyin":"","meaning":"Anh họ tôi đã chuyển ra nước ngoài sinh sống và gọi điện cho chúng tôi vào mỗi cuối tuần."},{"hanzi":"Studying overseas can broaden students'' perspectives, although adapting to a different culture often takes time.","pinyin":"","meaning":"Đi du học có thể mở rộng tầm nhìn của học sinh, mặc dù việc thích nghi với một nền văn hóa khác thường cần có thời gian."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_7_2', 'en-b2-7', 'Cách dùng “cuisine” (n.) — phong cách nấu nướng; ẩm thực; nền văn hóa ẩm thực', 'local cuisine  ·  traditional cuisine  ·  international cuisine', 'Từ "cuisine" dùng để chỉ trường phái ẩm thực hoặc cách nấu nướng, không dùng để chỉ một món ăn đơn lẻ.', NULL, '[{"hanzi":"This little restaurant serves delicious cuisine from southern India.","pinyin":"","meaning":"Nhà hàng nhỏ này phục vụ các món ăn ngon mang hương vị miền Nam Ấn Độ."},{"hanzi":"Traditional cuisine can attract international tourists while helping local communities preserve their cultural identity.","pinyin":"","meaning":"Ẩm thực truyền thống có thể thu hút khách du lịch quốc tế đồng thời giúp cộng đồng địa phương bảo tồn bản sắc văn hóa của họ."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_7_3', 'en-b2-7', 'Cách dùng “cargo” (n.) — hàng hóa (chuyên chở bằng tàu thủy, máy bay hoặc phương tiện lớn)', 'cargo ship  ·  air cargo  ·  load cargo', 'cargo thường chỉ hàng hóa thương mại được vận chuyển, không dùng cho hành lý xách tay của hành khách.', 'Đồng nghĩa: freight', '[{"hanzi":"The crane lifted the cargo onto the waiting ship.","pinyin":"","meaning":"Cần cẩu đã cẩu hàng hóa lên con tàu đang chờ sẵn."},{"hanzi":"Moving cargo by rail rather than road can reduce emissions and ease congestion on major highways.","pinyin":"","meaning":"Vận chuyển hàng hóa bằng đường sắt thay vì đường bộ có thể làm giảm lượng khí thải và giảm bớt tình trạng ùn tắc trên các tuyến cao tốc chính."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_7_4', 'en-b2-7', 'Cách dùng “halt” (v.) — dừng lại; ngừng lại; làm cho dừng lại', 'come to a halt  ·  bring to a halt  ·  halt production', 'Từ halt mang tính trang trọng hơn stop; cụm từ come to a halt diễn tả hành động dừng lại hoàn toàn.', 'Đồng nghĩa: stop, cease · Trái nghĩa: continue', '[{"hanzi":"The bus halted suddenly when a sheep crossed.","pinyin":"","meaning":"Chiếc xe buýt dừng lại đột ngột khi có một con cừu băng qua đường."},{"hanzi":"Urgent international cooperation is needed to halt the destruction of habitats and protect species at risk of extinction.","pinyin":"","meaning":"Cần có sự hợp tác quốc tế khẩn cấp để ngăn chặn sự tàn phá môi trường sống và bảo vệ các loài có nguy cơ tuyệt chủng."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_7_1', 'en-b2-7', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_7_1_1', 'ten_b2_7_1', 'airliner', 'We watched a huge airliner land in the rain.', 'We watched a huge airliner land in the rain.', '/ˈerlaɪnər/', 'Chúng tôi đứng xem một chiếc máy bay chở khách khổng lồ hạ cánh trong cơn mưa.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_7_1_2', 'ten_b2_7_1', 'carousel', 'The children waved as the carousel carried them round.', 'The children waved as the carousel carried them round.', '/ˌkærəˈsel/', 'Bọn trẻ vẫy tay khi vòng quay ngựa gỗ đưa chúng quay vòng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_7_1_3', 'ten_b2_7_1', 'carriage', 'We found two empty seats in the last carriage.', 'We found two empty seats in the last carriage.', '/ˈkærɪdʒ/', 'Chúng tôi tìm thấy hai chỗ ngồi trống ở toa tàu cuối cùng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_7_1_4', 'ten_b2_7_1', 'cuisine', 'This little restaurant serves delicious cuisine from southern India.', 'This little restaurant serves delicious cuisine from southern India.', '/kwɪˈziːn/', 'Nhà hàng nhỏ này phục vụ các món ăn ngon mang hương vị miền Nam Ấn Độ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_7_1_5', 'ten_b2_7_1', 'cruise', 'We took a cruise around the islands last summer.', 'We took a cruise around the islands last summer.', '/kruːz/', 'Mùa hè năm ngoái, chúng tôi đã đi chuyến du thuyền vòng quanh các hòn đảo.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
