INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_7_1_7', 'ten_b2_7_1', 'overseas', 'My cousin moved overseas and calls us every weekend.', 'My cousin moved overseas and calls us every weekend.', '/ˌoʊvɚˈsiːz/', 'Anh họ tôi đã chuyển ra nước ngoài sinh sống và gọi điện cho chúng tôi vào mỗi cuối tuần.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_7_1_8', 'ten_b2_7_1', 'excursion', 'We packed sandwiches for our excursion to the lake.', 'We packed sandwiches for our excursion to the lake.', '/ɪkˈskɝːʒən/', 'Chúng tôi đã chuẩn bị bánh mì kẹp cho chuyến dã ngoại ra hồ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_7_1_1', 'en-b2-7', 'ten_b2_7_1', 'listening', 'listening', 'We watched a huge airliner land in the rain.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bãi biển yên tĩnh này là thiên đường dành cho những người thích bơi lội.","Bọn trẻ vẫy tay khi vòng quay ngựa gỗ đưa chúng quay vòng.","Nhà hàng nhỏ này phục vụ các món ăn ngon mang hương vị miền Nam Ấn Độ.","Chúng tôi đứng xem một chiếc máy bay chở khách khổng lồ hạ cánh trong cơn mưa."]'::jsonb, 3, 'We watched a huge airliner land in the rain. → Chúng tôi đứng xem một chiếc máy bay chở khách khổng lồ hạ cánh trong cơn mưa.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_7_1_2', 'en-b2-7', 'ten_b2_7_1', 'listening', 'listening', 'The children waved as the carousel carried them round.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đứng nhìn một chiếc tàu chở dầu khổng lồ tiến vào cảng.","Bọn trẻ vẫy tay khi vòng quay ngựa gỗ đưa chúng quay vòng.","Chiếc dù của cô ấy mở bung ra một cách suôn sẻ phía trên những cánh đồng xanh ngắt.","Chúng tôi đứng xem một chiếc máy bay chở khách khổng lồ hạ cánh trong cơn mưa."]'::jsonb, 1, 'The children waved as the carousel carried them round. → Bọn trẻ vẫy tay khi vòng quay ngựa gỗ đưa chúng quay vòng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_7_1_3', 'en-b2-7', 'ten_b2_7_1', 'listening', 'listening', 'We found two empty seats in the last carriage.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bọn trẻ vẫy tay khi vòng quay ngựa gỗ đưa chúng quay vòng.","Chúng tôi tìm thấy hai chỗ ngồi trống ở toa tàu cuối cùng.","Các thợ lặn tìm thấy một con tàu đắm nằm bên cạnh xác một chiếc tàu ngầm.","Chúng tôi đứng xem một chiếc máy bay chở khách khổng lồ hạ cánh trong cơn mưa."]'::jsonb, 1, 'We found two empty seats in the last carriage. → Chúng tôi tìm thấy hai chỗ ngồi trống ở toa tàu cuối cùng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_7_2', 'en-b2-7', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_7_2_1', 'ten_b2_7_2', 'airliner', 'Modern airliners can carry more passengers efficiently, although aviation remains a significant source of greenhouse gas emissions.', 'Modern airliners can carry more passengers efficiently, although aviation remains a significant source of greenhouse gas emissions.', '/ˈerlaɪnər/', 'Các dòng máy bay chở khách hiện đại có thể vận chuyển nhiều hành khách hơn một cách hiệu quả, mặc dù ngành hàng không vẫn là nguồn phát thải khí nhà kính đáng kể.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_7_2_2', 'ten_b2_7_2', 'carousel', 'Clear information near each baggage carousel can help arriving passengers navigate unfamiliar airports more efficiently.', 'Clear information near each baggage carousel can help arriving passengers navigate unfamiliar airports more efficiently.', '/ˌkærəˈsel/', 'Thông tin rõ ràng gần mỗi băng chuyền hành lý có thể giúp hành khách mới đến tìm đường ở các sân bay lạ một cách hiệu quả hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_7_2_3', 'ten_b2_7_2', 'carriage', 'Adding an extra carriage to each train could reduce overcrowding and improve the daily experience of commuters.', 'Adding an extra carriage to each train could reduce overcrowding and improve the daily experience of commuters.', '/ˈkærɪdʒ/', 'Việc thêm một toa tàu vào mỗi chuyến đoàn tàu có thể làm giảm tình trạng quá tải và cải thiện trải nghiệm đi lại hàng ngày của những người đi làm.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_7_2_4', 'ten_b2_7_2', 'cuisine', 'Traditional cuisine can attract international tourists while helping local communities preserve their cultural identity.', 'Traditional cuisine can attract international tourists while helping local communities preserve their cultural identity.', '/kwɪˈziːn/', 'Ẩm thực truyền thống có thể thu hút khách du lịch quốc tế đồng thời giúp cộng đồng địa phương bảo tồn bản sắc văn hóa của họ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_7_2_5', 'ten_b2_7_2', 'cruise', 'The growing popularity of cruise holidays has raised concerns about air pollution in coastal cities.', 'The growing popularity of cruise holidays has raised concerns about air pollution in coastal cities.', '/kruːz/', 'Sự phổ biến ngày càng tăng của các kỳ nghỉ trên tàu du lịch đã dấy lên những lo ngại về ô nhiễm không khí tại các thành phố ven biển.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_7_2_6', 'ten_b2_7_2', 'halt', 'Urgent international cooperation is needed to halt the destruction of habitats and protect species at risk of extinction.', 'Urgent international cooperation is needed to halt the destruction of habitats and protect species at risk of extinction.', '/hɔːlt/', 'Cần có sự hợp tác quốc tế khẩn cấp để ngăn chặn sự tàn phá môi trường sống và bảo vệ các loài có nguy cơ tuyệt chủng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_7_2_1', 'en-b2-7', 'ten_b2_7_2', 'listening', 'listening', 'Modern airliners can carry more passengers efficiently, although aviation remains a significant source of greenhouse gas emissions.', NULL, 'Trong câu vừa nghe, từ “airliner” mang nghĩa nào sau đây?', '["chữa khỏi; điều trị dứt điểm","bộ xương; khung xương","máy bay chở khách cỡ lớn; máy bay phản lực thương mại","bồi thẩm đoàn"]'::jsonb, 2, '“airliner” (/ˈerlaɪnər/): máy bay chở khách cỡ lớn; máy bay phản lực thương mại. Câu đầy đủ: Modern airliners can carry more passengers efficiently, although aviation remains a significant source of greenhouse gas emissions.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_7_2_2', 'en-b2-7', 'ten_b2_7_2', 'listening', 'listening', 'Clear information near each baggage carousel can help arriving passengers navigate unfamiliar airports more efficiently.', NULL, 'Trong câu vừa nghe, từ “carousel” mang nghĩa nào sau đây?', '["chứng chuột rút; cơn đau thắt cơ","vòng quay ngựa gỗ; ngựa gỗ vòng tròn","tước đoạt; làm cho mất đi","lợi ích; mục đích; vì (ai/cái gì)"]'::jsonb, 1, '“carousel” (/ˌkærəˈsel/): vòng quay ngựa gỗ; ngựa gỗ vòng tròn. Câu đầy đủ: Clear information near each baggage carousel can help arriving passengers navigate unfamiliar airports more efficiently.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
