INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_b2_7_1', 'en-b2-7', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “airliner” (/ˈerlaɪnər/) có nghĩa là gì?', '["máy bay chở khách cỡ lớn; máy bay phản lực thương mại","tàu chở dầu; tàu chở chất lỏng","rút lui; thoái lui","hạm đội; đội tàu thủy"]'::jsonb, 0, '“airliner” (n.): máy bay chở khách cỡ lớn; máy bay phản lực thương mại.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
