INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_7_1', 'en-b2-7', NULL, 'comprehensive_test', 'listening', 'airliner', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["từ chức; xin thôi việc","máy bay chở khách cỡ lớn; máy bay phản lực thương mại","kết quả nghiên cứu; phát hiện điều tra","quầy hàng; sạp hàng"]'::jsonb, 1, 'airliner (/ˈerlaɪnər/) → máy bay chở khách cỡ lớn; máy bay phản lực thương mại', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_7_2', 'en-b2-7', NULL, 'comprehensive_test', 'listening', 'The children waved as the carousel carried them round.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bọn trẻ vẫy tay khi vòng quay ngựa gỗ đưa chúng quay vòng.","Cần cẩu đã cẩu hàng hóa lên con tàu đang chờ sẵn.","Nhà hàng nhỏ này phục vụ các món ăn ngon mang hương vị miền Nam Ấn Độ.","Chiếc xe buýt dừng lại đột ngột khi có một con cừu băng qua đường."]'::jsonb, 0, 'The children waved as the carousel carried them round. → Bọn trẻ vẫy tay khi vòng quay ngựa gỗ đưa chúng quay vòng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_7_3', 'en-b2-7', NULL, 'comprehensive_test', 'listening', 'carriage', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cào (dụng cụ có cán dài và răng cào để gom lá hoặc làm phẳng đất)","cấp phó; người đại diện; người phụ tá","toa tàu khách","có triển vọng; đầy hứa hẹn"]'::jsonb, 2, 'carriage (/ˈkærɪdʒ/) → toa tàu khách; xe ngựa kéo; sự vận chuyển hàng hóa; cước phí vận chuyển', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_7_4', 'en-b2-7', NULL, 'comprehensive_test', 'listening', 'This little restaurant serves delicious cuisine from southern India.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đứng xem một chiếc máy bay chở khách khổng lồ hạ cánh trong cơn mưa.","Chúng tôi đứng nhìn một chiếc tàu chở dầu khổng lồ tiến vào cảng.","Nhà hàng nhỏ này phục vụ các món ăn ngon mang hương vị miền Nam Ấn Độ.","Mùa hè năm ngoái, chúng tôi đã đi chuyến du thuyền vòng quanh các hòn đảo."]'::jsonb, 2, 'This little restaurant serves delicious cuisine from southern India. → Nhà hàng nhỏ này phục vụ các món ăn ngon mang hương vị miền Nam Ấn Độ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_7_5', 'en-b2-7', NULL, 'comprehensive_test', 'listening', 'cruise', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["phần còn lại; số dư","chuyến du ngoạn trên biển; chuyến đi bằng tàu thủy","con bạc; người đánh bạc","chiếm; chiếm giữ; chiếm lĩnh không gian/thời gian"]'::jsonb, 1, 'cruise (/kruːz/) → chuyến du ngoạn trên biển; chuyến đi bằng tàu thủy; di chuyển đều tốc; lướt đi êm ái', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_7_6', 'en-b2-7', NULL, 'comprehensive_test', 'listening', 'The bus halted suddenly when a sheep crossed.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bãi biển yên tĩnh này là thiên đường dành cho những người thích bơi lội.","Một đoàn thuyền đánh cá đã quay trở về trước khi mặt trời lặn.","Chiếc xe buýt dừng lại đột ngột khi có một con cừu băng qua đường.","Ông tôi giữ một chiếc ô tô cổ trong gara của ông."]'::jsonb, 2, 'The bus halted suddenly when a sheep crossed. → Chiếc xe buýt dừng lại đột ngột khi có một con cừu băng qua đường.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_7_7', 'en-b2-7', NULL, 'comprehensive_test', 'listening', 'overseas', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["ở nước ngoài; ra nước ngoài","có động lực; có tinh thần chủ động","bằng lời nói; dạng nói (thay vì dạng viết)","hạt cườm; hạt chuỗi"]'::jsonb, 0, 'overseas (/ˌoʊvɚˈsiːz/) → ở nước ngoài; ra nước ngoài; thuộc nước ngoài; đến từ nước ngoài', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_7_8', 'en-b2-7', NULL, 'comprehensive_test', 'listening', 'We packed sandwiches for our excursion to the lake.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi dùng bản đồ để tìm đường qua những con phố chật hẹp.","Các thợ lặn tìm thấy một con tàu đắm nằm bên cạnh xác một chiếc tàu ngầm.","Chúng tôi đã chuẩn bị bánh mì kẹp cho chuyến dã ngoại ra hồ.","Ông tôi giữ một chiếc ô tô cổ trong gara của ông."]'::jsonb, 2, 'We packed sandwiches for our excursion to the lake. → Chúng tôi đã chuẩn bị bánh mì kẹp cho chuyến dã ngoại ra hồ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
