INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_7_18', 'en-b2-7', NULL, 'comprehensive_test', 'reading', NULL, 'Modern airliners can carry more passengers efficiently, although aviation remains a significant source of greenhouse gas emissions.', 'Dựa vào câu trên, từ “airliner” có nghĩa phù hợp nhất là gì?', '["công thức (toán học, khoa học)","thuộc về nghệ thuật","tủ có ngăn kéo để đựng quần áo (kiểu Mỹ)","máy bay chở khách cỡ lớn; máy bay phản lực thương mại"]'::jsonb, 3, 'airliner: máy bay chở khách cỡ lớn; máy bay phản lực thương mại. Dịch cả câu: Các dòng máy bay chở khách hiện đại có thể vận chuyển nhiều hành khách hơn một cách hiệu quả, mặc dù ngành hàng không vẫn là nguồn phát thải khí nhà kính đáng kể.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_7_19', 'en-b2-7', NULL, 'comprehensive_test', 'reading', NULL, 'Clear information near each baggage carousel can help arriving passengers navigate unfamiliar airports more efficiently.', 'Dựa vào câu trên, từ “carousel” có nghĩa phù hợp nhất là gì?', '["vòng quay ngựa gỗ; ngựa gỗ vòng tròn","sủa","sự xao nhãng; điều làm phân tâm","giờ làm thêm; tiền làm thêm giờ"]'::jsonb, 0, 'carousel: vòng quay ngựa gỗ; ngựa gỗ vòng tròn; băng chuyền hành lý (tại sân bay). Dịch cả câu: Thông tin rõ ràng gần mỗi băng chuyền hành lý có thể giúp hành khách mới đến tìm đường ở các sân bay lạ một cách hiệu quả hơn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_7_20', 'en-b2-7', NULL, 'comprehensive_test', 'reading', NULL, 'Adding an extra carriage to each train could reduce overcrowding and improve the daily experience of commuters.', 'Dựa vào câu trên, từ “carriage” có nghĩa phù hợp nhất là gì?', '["toa tàu khách","thành phần; cấu tạo","vòng; thòng lọng; đường đi hình vòng","tính từ: vỡ lòng; nhập môn; giới thiệu"]'::jsonb, 0, 'carriage: toa tàu khách; xe ngựa kéo; sự vận chuyển hàng hóa; cước phí vận chuyển. Dịch cả câu: Việc thêm một toa tàu vào mỗi chuyến đoàn tàu có thể làm giảm tình trạng quá tải và cải thiện trải nghiệm đi lại hàng ngày của những người đi làm.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_7_21', 'en-b2-7', NULL, 'comprehensive_test', 'reading', NULL, 'Traditional cuisine can attract international tourists while helping local communities preserve their cultural identity.', 'Dựa vào câu trên, từ “cuisine” có nghĩa phù hợp nhất là gì?', '["triết học (nghiên cứu về tri thức, sự tồn tại, thực tại và giá trị đạo đức)","phong cách nấu nướng; ẩm thực; nền văn hóa ẩm thực","áp đặt; ban hành (luật, thuế, hình phạt)","hoàn toàn; cực kỳ; tuyệt đối"]'::jsonb, 1, 'cuisine: phong cách nấu nướng; ẩm thực; nền văn hóa ẩm thực. Dịch cả câu: Ẩm thực truyền thống có thể thu hút khách du lịch quốc tế đồng thời giúp cộng đồng địa phương bảo tồn bản sắc văn hóa của họ.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_7_22', 'en-b2-7', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “lái (xe, thuyền); điều khiển hướng đi”', '["capture","indicate","spotlight","steer"]'::jsonb, 3, 'lái (xe, thuyền); điều khiển hướng đi → steer (/stɪr/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_7_23', 'en-b2-7', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tàu chở dầu; tàu chở chất lỏng”', '["casualty","archaeology","descend","tanker"]'::jsonb, 3, 'tàu chở dầu; tàu chở chất lỏng → tanker (/ˈtæŋkər/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_7_24', 'en-b2-7', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “dẫn đường; xác định phương hướng”', '["crust","eager","motor","navigate"]'::jsonb, 3, 'dẫn đường; xác định phương hướng → navigate (/ˈnævɪɡeɪt/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-8', 'en', 'Bài 8: Xã hội & Cộng đồng (1) - CEFR B2', 'CEFR B2', 'B2 · Xã hội', '26 từ vựng Tiếng Anh CEFR B2 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4008, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_approachable', 'en-b2-8', 'approachable', '/əˈproʊtʃəbl/', 'B2', 'gần gũi; thân thiện; dễ gần; dễ tiếp cận; dễ hiểu', 'adj.', 'approach (v.), approachability (n.), unapproachable (adj.)', 'Đồng nghĩa: friendly, welcoming · Trái nghĩa: unapproachable', 'Khi mô tả con người, từ này nhấn mạnh sự dễ trò chuyện, khiến người khác dám đến nhờ giúp đỡ.', 'Our new teacher seems approachable, so I asked for help.', NULL, 'Giáo viên mới của chúng tôi có vẻ rất dễ gần, nên tôi đã nhờ cô giúp đỡ.', '{"wordId":"approachable","ukIpa":"/əˈprəʊtʃəbl/","usIpa":"/əˈproʊtʃəbl/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"friendly and easy to talk to","vi":"gần gũi; thân thiện; dễ gần"},{"pos":"adj.","en":"easy to understand or enjoy without special knowledge","vi":"dễ tiếp cận; dễ hiểu"}],"examples":[{"en":"Our new teacher seems approachable, so I asked for help.","vi":"Giáo viên mới của chúng tôi có vẻ rất dễ gần, nên tôi đã nhờ cô giúp đỡ.","audioKind":"ex"},{"en":"Approachable healthcare professionals may encourage patients to discuss sensitive concerns before their conditions become more serious.","vi":"Các chuyên gia y tế thân thiện, dễ gần có thể khuyến khích bệnh nhân thảo luận về những lo lắng tế nhị trước khi tình trạng bệnh trở nên nghiêm trọng hơn.","audioKind":"ex2"}],"collocations":[{"en":"an approachable teacher","vi":"một giáo viên thân thiện"},{"en":"friendly and approachable","vi":"thân thiện và dễ gần"},{"en":"an approachable style","vi":"một phong cách dễ hiểu"}],"wordFamily":["approach (v.)","approachability (n.)","unapproachable (adj.)"],"synonyms":["friendly","welcoming"],"antonyms":["unapproachable"],"tipVi":"Khi mô tả con người, từ này nhấn mạnh sự dễ trò chuyện, khiến người khác dám đến nhờ giúp đỡ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rally', 'en-b2-8', 'rally', '/ˈræli/', 'B2', 'cuộc mít tinh; cuộc biểu tình; tập hợp; kêu gọi ủng hộ; phục hồi; hồi sức; tăng trở lại', 'n.', NULL, 'Đồng nghĩa: gathering, mobilise, recover', 'rally support for có nghĩa là "kêu gọi sự ủng hộ cho...".', 'Hundreds attended a peaceful rally in the town square.', NULL, 'Hàng trăm người đã tham gia một cuộc mít tinh ôn hòa ở quảng trường thị trấn.', '{"wordId":"rally","ukIpa":"/ˈræli/","usIpa":"/ˈræli/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"A large public meeting supporting a cause or expressing opinions.","vi":"cuộc mít tinh; cuộc biểu tình"},{"pos":"v.","en":"To gather people together to support someone or something.","vi":"tập hợp; kêu gọi ủng hộ"},{"pos":"v.","en":"To regain strength or improve after a difficult period.","vi":"phục hồi; hồi sức; tăng trở lại"}],"examples":[{"en":"Hundreds attended a peaceful rally in the town square.","vi":"Hàng trăm người đã tham gia một cuộc mít tinh ôn hòa ở quảng trường thị trấn.","audioKind":"ex"},{"en":"Community leaders rallied support for a public library, arguing that free access to information benefits everyone.","vi":"Các nhà lãnh đạo cộng đồng đã kêu gọi sự ủng hộ cho một thư viện công cộng, với lập luận rằng việc tiếp cận thông tin miễn phí mang lại lợi ích cho tất cả mọi người.","audioKind":"ex2"}],"collocations":[{"en":"hold a rally","vi":"tổ chức một cuộc mít tinh"},{"en":"rally support","vi":"kêu gọi ủng hộ"},{"en":"rally around someone","vi":"tập hợp ủng hộ ai đó"}],"wordFamily":[],"synonyms":["gathering","mobilise","recover"],"antonyms":[],"tipVi":"rally support for có nghĩa là \"kêu gọi sự ủng hộ cho...\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_upbringing', 'en-b2-8', 'upbringing', '/ˈʌpbrɪŋɪŋ/', 'B2', 'sự nuôi nấng; sự dạy dỗ; giáo dục gia đình', 'n.', 'bring up (v.)', NULL, 'Chỉ việc nuôi dưỡng và giáo dục trong gia đình thời thơ ấu, không đồng nghĩa với giáo dục ở trường học.', 'Her upbringing taught her to share with others.', NULL, 'Cách giáo dục của gia đình đã dạy cô ấy biết chia sẻ với người khác.', '{"wordId":"upbringing","ukIpa":"/ˈʌpbrɪŋɪŋ/","usIpa":"/ˈʌpbrɪŋɪŋ/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"The way parents care for and teach a child","vi":"sự nuôi nấng; sự dạy dỗ; giáo dục gia đình"}],"examples":[{"en":"Her upbringing taught her to share with others.","vi":"Cách giáo dục của gia đình đã dạy cô ấy biết chia sẻ với người khác.","audioKind":"ex"},{"en":"A supportive upbringing can help children develop confidence and cope more effectively with challenges at school.","vi":"Sự nuôi dạy đầy sự nâng đỡ có thể giúp trẻ em phát triển sự tự tin và đối phó hiệu quả hơn với các thử thách ở trường.","audioKind":"ex2"}],"collocations":[{"en":"a strict upbringing","vi":"sự giáo dục nghiêm khắc"},{"en":"a sheltered upbringing","vi":"tuổi thơ được bao bọc kỹ lưỡng"},{"en":"a privileged upbringing","vi":"hoàn cảnh sống vương giả"}],"wordFamily":["bring up (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ việc nuôi dưỡng và giáo dục trong gia đình thời thơ ấu, không đồng nghĩa với giáo dục ở trường học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fellow', 'en-b2-8', 'fellow', '/ˈfeloʊ/', 'B2', 'cùng cảnh ngộ; có chung hoàn cảnh; anh chàng; gã; hội viên; nghiên cứu viên', 'adj.', 'fellowship (n.)', NULL, 'Tính từ chỉ đặt trước danh từ, ví dụ my fellow students.', 'I shared my umbrella with a fellow passenger.', NULL, 'Tôi đã chia sẻ chiếc ô của mình với một hành khách cùng chuyến.', '{"wordId":"fellow","ukIpa":"/ˈfeləʊ/","usIpa":"/ˈfeloʊ/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Sharing a situation, activity, or status with someone","vi":"cùng cảnh ngộ; có chung hoàn cảnh"},{"pos":"n.","en":"A man or boy, referred to informally","vi":"anh chàng; gã"},{"pos":"n.","en":"A member of a learned society or certain academic institutions","vi":"hội viên; nghiên cứu viên"}],"examples":[{"en":"I shared my umbrella with a fellow passenger.","vi":"Tôi đã chia sẻ chiếc ô của mình với một hành khách cùng chuyến.","audioKind":"ex"},{"en":"Students who regularly exchange ideas with fellow learners often develop greater confidence and stronger communication skills.","vi":"Những học sinh thường xuyên trao đổi ý tưởng với các bạn học thường phát triển sự tự tin lớn hơn và kỹ năng giao tiếp mạnh mẽ hơn.","audioKind":"ex2"}],"collocations":[{"en":"fellow students","vi":"bạn học"},{"en":"fellow passengers","vi":"hành khách đi cùng"},{"en":"research fellow","vi":"nghiên cứu viên"},{"en":"a friendly fellow","vi":"một chàng trai thân thiện"}],"wordFamily":["fellowship (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tính từ chỉ đặt trước danh từ, ví dụ my fellow students.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_torture', 'en-b2-8', 'torture', '/ˈtɔːrtʃər/', 'B2', 'sự tra tấn; cực hình; nỗi giày vò; tra tấn; hành hạ; giày vò', 'n.', 'torturer (n.), tortured (adj.)', 'Đồng nghĩa: torment, agony', 'Mang sắc thái nghĩa rất mạnh; trong giao tiếp hằng ngày có thể dùng để nói quá về sự giày vò, chứ không chỉ là sự khó chịu thông thường.', 'Waiting all afternoon for the results was pure torture.', NULL, 'Chờ đợi kết quả suốt cả buổi chiều thật sự là một cực hình.', '{"wordId":"torture","ukIpa":"/ˈtɔːtʃə/","usIpa":"/ˈtɔːrtʃər/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"deliberately inflicted severe pain, or an extremely distressing experience","vi":"sự tra tấn; cực hình; nỗi giày vò"},{"pos":"v.","en":"to deliberately cause severe physical or mental suffering","vi":"tra tấn; hành hạ; giày vò"}],"examples":[{"en":"Waiting all afternoon for the results was pure torture.","vi":"Chờ đợi kết quả suốt cả buổi chiều thật sự là một cực hình.","audioKind":"ex"},{"en":"International agreements prohibit torture and require governments to protect the basic rights of all prisoners.","vi":"Các hiệp định quốc tế nghiêm cấm việc tra tấn và yêu cầu chính phủ các nước bảo vệ các quyền cơ bản của mọi tù nhân.","audioKind":"ex2"}],"collocations":[{"en":"psychological torture","vi":"tra tấn tinh thần"},{"en":"pure torture","vi":"cực hình thực sự"},{"en":"prohibit torture","vi":"nghiêm cấm tra tấn"},{"en":"subject someone to torture","vi":"tra tấn ai đó"}],"wordFamily":["torturer (n.)","tortured (adj.)"],"synonyms":["torment","agony"],"antonyms":[],"tipVi":"Mang sắc thái nghĩa rất mạnh; trong giao tiếp hằng ngày có thể dùng để nói quá về sự giày vò, chứ không chỉ là sự khó chịu thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_greedy', 'en-b2-8', 'greedy', '/ˈɡriːdi/', 'B2', 'tham lam; hám lợi; tham ăn', 'adj.', 'greed (n.), greedily (adv.), greediness (n.)', 'Đồng nghĩa: avaricious · Trái nghĩa: generous', 'Thường mang nghĩa tiêu cực; sau "greedy for" là thứ mà ai đó tham lam muốn có (như tiền bạc, quyền lực).', 'Don''t be greedy; leave some biscuits for your sister.', NULL, 'Đừng tham ăn thế; hãy để phần bánh quy cho em gái con nữa.', '{"wordId":"greedy","ukIpa":"/ˈɡriːdi/","usIpa":"/ˈɡriːdi/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"wanting more money or possessions than one needs","vi":"tham lam; hám lợi"},{"pos":"adj.","en":"wanting to eat more food than one needs","vi":"tham ăn"}],"examples":[{"en":"Don''t be greedy; leave some biscuits for your sister.","vi":"Đừng tham ăn thế; hãy để phần bánh quy cho em gái con nữa.","audioKind":"ex"},{"en":"Greedy investors may prioritise immediate profits over the long-term environmental consequences of their business decisions.","vi":"Những nhà đầu tư tham lam có thể đặt lợi nhuận trước mắt lên trên những hệ quả môi trường lâu dài từ các quyết định kinh doanh của họ.","audioKind":"ex2"}],"collocations":[{"en":"greedy for money","vi":"hám tiền"},{"en":"greedy for power","vi":"ham quyền lực"},{"en":"a greedy investor","vi":"nhà đầu tư tham lam"}],"wordFamily":["greed (n.)","greedily (adv.)","greediness (n.)"],"synonyms":["avaricious"],"antonyms":["generous"],"tipVi":"Thường mang nghĩa tiêu cực; sau \"greedy for\" là thứ mà ai đó tham lam muốn có (như tiền bạc, quyền lực).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_soul', 'en-b2-8', 'soul', '/soʊl/', 'B2', 'tâm hồn; linh hồn; con người; cá nhân; nhạc soul; dòng nhạc soul đặc trưng', 'n.', 'soulful (adj.), soulless (adj.)', 'Đồng nghĩa: spirit', 'Cụm từ not a soul có nghĩa là "không một bóng người", không liên quan đến nghĩa linh hồn.', 'Walking beside the sea always seems to soothe my soul.', NULL, 'Đi dạo dọc bờ biển dường như luôn giúp xoa dịu tâm hồn tôi.', '{"wordId":"soul","ukIpa":"/səʊl/","usIpa":"/soʊl/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"The spiritual part of a person, separate from the body.","vi":"tâm hồn; linh hồn"},{"pos":"n.","en":"A person, especially when describing their character.","vi":"con người; cá nhân"},{"pos":"n.","en":"Expressive popular music combining gospel and rhythm and blues.","vi":"nhạc soul; dòng nhạc soul đặc trưng"}],"examples":[{"en":"Walking beside the sea always seems to soothe my soul.","vi":"Đi dạo dọc bờ biển dường như luôn giúp xoa dịu tâm hồn tôi.","audioKind":"ex"},{"en":"Many cultural traditions view the soul as something that continues to exist after the body dies.","vi":"Nhiều truyền thống văn hóa quan niệm rằng linh hồn vẫn tiếp tục tồn tại sau khi thể xác chết đi.","audioKind":"ex2"}],"collocations":[{"en":"heart and soul","vi":"hết lòng hết dạ; toàn tâm toàn ý"},{"en":"a kind soul","vi":"một người tốt bụng"},{"en":"not a soul","vi":"không một bóng người"},{"en":"soul music","vi":"nhạc soul"}],"wordFamily":["soulful (adj.)","soulless (adj.)"],"synonyms":["spirit"],"antonyms":[],"tipVi":"Cụm từ not a soul có nghĩa là \"không một bóng người\", không liên quan đến nghĩa linh hồn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_anonymous', 'en-b2-8', 'anonymous', '/əˈnɑːnəməs/', 'B2', 'giấu tên; vô danh; không có điểm đặc sắc; mờ nhạt', 'adj.', 'anonymity (n.), anonymously (adv.), anonymise (v.)', 'Đồng nghĩa: unnamed · Trái nghĩa: identified', 'Ẩn danh là anonymous; bảo mật là confidential, nghĩa khác nhau.', 'An anonymous donor paid for the children''s new playground.', NULL, 'Một nhà hảo tâm giấu tên đã tài trợ tiền làm sân chơi mới cho lũ trẻ.', '{"wordId":"anonymous","ukIpa":"/əˈnɒnɪməs/","usIpa":"/əˈnɑːnəməs/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Having a name that is unknown or kept secret.","vi":"giấu tên; vô danh"},{"pos":"adj.","en":"Lacking distinctive features that make something easy to recognize.","vi":"không có điểm đặc sắc; mờ nhạt"}],"examples":[{"en":"An anonymous donor paid for the children''s new playground.","vi":"Một nhà hảo tâm giấu tên đã tài trợ tiền làm sân chơi mới cho lũ trẻ.","audioKind":"ex"},{"en":"Anonymous surveys can encourage employees to express honest opinions about conditions in their workplace.","vi":"Các cuộc khảo sát ẩn danh có thể khuyến khích nhân viên bày tỏ ý kiến thành thật về điều kiện làm việc nơi công sở.","audioKind":"ex2"}],"collocations":[{"en":"remain anonymous","vi":"giữ ẩn danh"},{"en":"anonymous donor","vi":"nhà tài trợ giấu tên"},{"en":"anonymous survey","vi":"khảo sát ẩn danh"},{"en":"anonymous source","vi":"nguồn tin giấu tên"}],"wordFamily":["anonymity (n.)","anonymously (adv.)","anonymise (v.)"],"synonyms":["unnamed"],"antonyms":["identified"],"tipVi":"Ẩn danh là anonymous; bảo mật là confidential, nghĩa khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_civilian', 'en-b2-8', 'civilian', '/səˈvɪliən/', 'B2', 'thường dân; người không thuộc lực lượng vũ trang; thuộc về dân sự; phi quân sự', 'n.', NULL, 'Đồng nghĩa: non-military · Trái nghĩa: military', 'Civilian chỉ người không phải quân nhân; công chức thường là civil servant.', 'The rescue boat carried both soldiers and civilians.', NULL, 'Con thuyền cứu hộ chở cả binh lính lẫn thường dân.', '{"wordId":"civilian","ukIpa":"/səˈvɪliən/","usIpa":"/səˈvɪliən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"A person who is not a member of the armed forces","vi":"thường dân; người không thuộc lực lượng vũ trang"},{"pos":"adj.","en":"Relating to people or activities outside the armed forces","vi":"thuộc về dân sự; phi quân sự"}],"examples":[{"en":"The rescue boat carried both soldiers and civilians.","vi":"Con thuyền cứu hộ chở cả binh lính lẫn thường dân.","audioKind":"ex"},{"en":"Satellite technology originally developed for military purposes now supports many civilian applications, including weather forecasting and navigation.","vi":"Công nghệ vệ tinh ban đầu phát triển cho mục đích quân sự nay hỗ trợ nhiều ứng dụng dân sự, bao gồm dự báo thời tiết và định vị.","audioKind":"ex2"}],"collocations":[{"en":"civilian population","vi":"dân thường"},{"en":"civilian life","vi":"cuộc sống dân sự"},{"en":"civilian aircraft","vi":"máy bay dân dụng"},{"en":"protect civilians","vi":"bảo vệ thường dân"}],"wordFamily":[],"synonyms":["non-military"],"antonyms":["military"],"tipVi":"Civilian chỉ người không phải quân nhân; công chức thường là civil servant.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_truthful', 'en-b2-8', 'truthful', '/ˈtruːθfəl/', 'B2', 'trung thực; thành thật; đúng sự thật', 'adj.', 'truth (n.), truthfully (adv.), truthfulness (n.), untruthful (adj.)', 'Đồng nghĩa: honest · Trái nghĩa: untruthful, dishonest', 'Truthful chỉ tính trung thực hoặc đúng sự thật; "người bạn chân chính" dùng true.', 'Please be truthful about how the vase broke.', NULL, 'Hãy kể sự thật về việc chiếc bình hoa bị vỡ như thế nào nhé.', '{"wordId":"truthful","ukIpa":"/ˈtruːθfəl/","usIpa":"/ˈtruːθfəl/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Telling the truth or accurately describing what happened.","vi":"trung thực; thành thật; đúng sự thật"}],"examples":[{"en":"Please be truthful about how the vase broke.","vi":"Hãy kể sự thật về việc chiếc bình hoa bị vỡ như thế nào nhé.","audioKind":"ex"},{"en":"Truthful reporting helps citizens understand public issues and make informed decisions about their communities.","vi":"Những bản tin trung thực giúp người dân hiểu rõ các vấn đề công cộng và đưa ra quyết định sáng suốt về cộng đồng của họ.","audioKind":"ex2"}],"collocations":[{"en":"be truthful about something","vi":"thành thật về điều gì đó"},{"en":"a truthful account","vi":"một lời kể chân thực"},{"en":"a truthful answer","vi":"một câu trả lời thành thật"}],"wordFamily":["truth (n.)","truthfully (adv.)","truthfulness (n.)","untruthful (adj.)"],"synonyms":["honest"],"antonyms":["untruthful","dishonest"],"tipVi":"Truthful chỉ tính trung thực hoặc đúng sự thật; \"người bạn chân chính\" dùng true.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_expose', 'en-b2-8', 'expose', '/ɪkˈspoʊz/', 'B2', 'tiếp xúc; phơi bày; đặt vào; vạch trần; bóc trần; lộ ra; để lộ; phơi ra', 'v.', 'exposure (n.), exposed (adj.)', 'Đồng nghĩa: reveal, uncover · Trái nghĩa: conceal', 'Cấu trúc expose A to B diễn tả việc đưa A tiếp xúc với B, và B không nhất thiết phải là điều có hại.', 'Don''t expose your skin to strong sunlight without protection.', NULL, 'Đừng để làn da tiếp xúc với ánh nắng gay gắt mà không có biện pháp bảo vệ.', '{"wordId":"expose","ukIpa":"/ɪkˈspəʊz/","usIpa":"/ɪkˈspoʊz/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"To put someone or something in contact with an influence","vi":"tiếp xúc; phơi bày; đặt vào"},{"pos":"v.","en":"To reveal something hidden, especially wrongdoing","vi":"vạch trần; phơi bày; bóc trần"},{"pos":"v.","en":"To uncover something previously hidden or protected","vi":"lộ ra; để lộ; phơi ra"}],"examples":[{"en":"Don''t expose your skin to strong sunlight without protection.","vi":"Đừng để làn da tiếp xúc với ánh nắng gay gắt mà không có biện pháp bảo vệ.","audioKind":"ex"},{"en":"Investigative journalism can expose unsafe working conditions and pressure companies to improve their treatment of employees.","vi":"Báo chí điều tra có thể vạch trần những điều kiện làm việc không an toàn và gây áp lực buộc các công ty phải cải thiện cách đối xử với nhân viên.","audioKind":"ex2"}],"collocations":[{"en":"expose someone to risk","vi":"đẩy ai vào rủi ro"},{"en":"expose corruption","vi":"vạch trần tham nhũng"},{"en":"expose children to music","vi":"cho trẻ tiếp cận với âm nhạc"}],"wordFamily":["exposure (n.)","exposed (adj.)"],"synonyms":["reveal","uncover"],"antonyms":["conceal"],"tipVi":"Cấu trúc expose A to B diễn tả việc đưa A tiếp xúc với B, và B không nhất thiết phải là điều có hại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_acceptance', 'en-b2-8', 'acceptance', '/əkˈseptəns/', 'B2', 'sự chấp nhận, sự nhận; sự tiếp nhận, sự công nhận; sự chấp nhận thực tế', 'n.', 'accept (v.), acceptable (adj.), unacceptable (adj.)', 'Đồng nghĩa: approval, recognition · Trái nghĩa: rejection', 'Thường là danh từ không đếm được; acceptance of đi sau với sự việc được đón nhận.', 'Her acceptance of the invitation made us all smile.', NULL, 'Việc cô ấy nhận lời mời khiến tất cả chúng tôi đều mỉm cười.', '{"wordId":"acceptance","ukIpa":"/əkˈseptəns/","usIpa":"/əkˈseptəns/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"The act of agreeing to receive or do something offered.","vi":"sự chấp nhận, sự nhận"},{"pos":"n.","en":"Willingness to welcome someone or regard something as suitable.","vi":"sự tiếp nhận, sự công nhận"},{"pos":"n.","en":"Recognition that a situation is real and must be faced.","vi":"sự chấp nhận thực tế"}],"examples":[{"en":"Her acceptance of the invitation made us all smile.","vi":"Việc cô ấy nhận lời mời khiến tất cả chúng tôi đều mỉm cười.","audioKind":"ex"},{"en":"Public acceptance of renewable energy projects often increases when local communities share in the economic benefits.","vi":"Sự công nhận của công chúng đối với các dự án năng lượng tái tạo thường tăng lên khi cộng đồng địa phương cùng chia sẻ các lợi ích kinh tế.","audioKind":"ex2"}],"collocations":[{"en":"acceptance of an offer","vi":"sự chấp nhận một lời đề nghị"},{"en":"gain acceptance","vi":"giành được sự công nhận"},{"en":"widespread acceptance","vi":"sự công nhận rộng rãi"},{"en":"social acceptance","vi":"sự chấp nhận của xã hội"}],"wordFamily":["accept (v.)","acceptable (adj.)","unacceptable (adj.)"],"synonyms":["approval","recognition"],"antonyms":["rejection"],"tipVi":"Thường là danh từ không đếm được; acceptance of đi sau với sự việc được đón nhận.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_islam', 'en-b2-8', 'Islam', '/ˈɪslɑːm/', 'B2', 'Hồi giáo', 'n.', 'Islamic (adj.)', NULL, 'Islam dùng để chỉ tôn giáo; Muslim dùng để chỉ người theo đạo Hồi hoặc thuộc về người Hồi giáo.', 'Our guide explained how Islam influences the mosque''s design.', NULL, 'Hướng dẫn viên giải thích cách đạo Hồi ảnh hưởng đến thiết kế của nhà thờ.', '{"wordId":"islam","ukIpa":"/ˈɪzlɑːm/","usIpa":"/ˈɪslɑːm/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"The religion followed by Muslims, teaching belief in one God","vi":"Hồi giáo"}],"examples":[{"en":"Our guide explained how Islam influences the mosque''s design.","vi":"Hướng dẫn viên giải thích cách đạo Hồi ảnh hưởng đến thiết kế của nhà thờ.","audioKind":"ex"},{"en":"Learning about Islam and other major religions can help students understand the traditions of diverse communities.","vi":"Việc tìm hiểu về Hồi giáo và các tôn giáo lớn khác có thể giúp học sinh thấu hiểu truyền thống của các cộng đồng đa dạng.","audioKind":"ex2"}],"collocations":[{"en":"the teachings of Islam","vi":"giáo lý đạo Hồi"},{"en":"the history of Islam","vi":"lịch sử Hồi giáo"},{"en":"convert to Islam","vi":"cải đạo sang Hồi giáo"}],"wordFamily":["Islamic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Islam dùng để chỉ tôn giáo; Muslim dùng để chỉ người theo đạo Hồi hoặc thuộc về người Hồi giáo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_adoption', 'en-b2-8', 'adoption', '/əˈdɑːpʃən/', 'B2', 'sự áp dụng; sự tiếp nhận; việc nhận nuôi con nuôi', 'n.', 'adopt (v.), adoptive (adj.), adopted (adj.)', NULL, 'Adoption là áp dụng hoặc nhận nuôi; adaptation là sự thích nghi hoặc cải biên.', 'The adoption of online booking made appointments much easier.', NULL, 'Việc áp dụng đặt lịch trực tuyến giúp cho việc hẹn gặp trở nên dễ dàng hơn rất nhiều.', '{"wordId":"adoption","ukIpa":"/əˈdɒpʃən/","usIpa":"/əˈdɑːpʃən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"the act of beginning to use an idea or method","vi":"sự áp dụng; sự tiếp nhận"},{"pos":"n.","en":"the legal process of becoming a child''s parent","vi":"việc nhận nuôi con nuôi"}],"examples":[{"en":"The adoption of online booking made appointments much easier.","vi":"Việc áp dụng đặt lịch trực tuyến giúp cho việc hẹn gặp trở nên dễ dàng hơn rất nhiều.","audioKind":"ex"},{"en":"Wider adoption of renewable energy could reduce air pollution and create employment in rural communities.","vi":"Việc áp dụng rộng rãi năng lượng tái tạo có thể làm giảm ô nhiễm không khí và tạo ra việc làm ở các cộng đồng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"adoption of technology","vi":"việc áp dụng công nghệ"},{"en":"widespread adoption","vi":"sự áp dụng rộng rãi"},{"en":"child adoption","vi":"việc nhận nuôi trẻ em"},{"en":"adoption agency","vi":"tổ chức nhận nuôi"}],"wordFamily":["adopt (v.)","adoptive (adj.)","adopted (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Adoption là áp dụng hoặc nhận nuôi; adaptation là sự thích nghi hoặc cải biên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_faith', 'en-b2-8', 'faith', '/feɪθ/', 'B2', 'niềm tin; lòng tin; sự tín nhiệm; tín ngưỡng; tôn giáo', 'n.', 'faithful (adj.), faithfully (adv.), faithless (adj.)', 'Đồng nghĩa: trust, confidence, belief · Trái nghĩa: doubt, distrust', 'Để diễn đạt sự tin tưởng vào ai hoặc cái gì, hãy sử dụng cụm have faith in.', 'I have faith in your ability to fix this.', NULL, 'Tôi đặt niềm tin vào năng lực giải quyết vấn đề này của bạn.', '{"wordId":"faith","ukIpa":"/feɪθ/","usIpa":"/feɪθ/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"Strong trust or confidence in someone or something.","vi":"niềm tin; lòng tin; sự tín nhiệm"},{"pos":"n.","en":"Belief in a god, or a particular religious system.","vi":"tín ngưỡng; tôn giáo"}],"examples":[{"en":"I have faith in your ability to fix this.","vi":"Tôi đặt niềm tin vào năng lực giải quyết vấn đề này của bạn.","audioKind":"ex"},{"en":"Transparent decision-making can strengthen public faith in institutions and encourage greater participation in community affairs.","vi":"Quá trình ra quyết định minh bạch có thể củng cố niềm tin của công chúng vào các thể chế và khuyến khích sự tham gia sâu rộng hơn vào các vấn đề cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"have faith in","vi":"tin tưởng vào"},{"en":"lose faith in","vi":"mất niềm tin vào"},{"en":"religious faith","vi":"tín ngưỡng tôn giáo"},{"en":"in good faith","vi":"với thiện chí; một cách thành thật"}],"wordFamily":["faithful (adj.)","faithfully (adv.)","faithless (adj.)"],"synonyms":["trust","confidence","belief"],"antonyms":["doubt","distrust"],"tipVi":"Để diễn đạt sự tin tưởng vào ai hoặc cái gì, hãy sử dụng cụm have faith in.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tolerate', 'en-b2-8', 'tolerate', '/ˈtɑːləreɪt/', 'B2', 'chịu đựng; dung thứ; chịu được; kham nổi', 'v.', 'tolerance (n.), tolerant (adj.), tolerable (adj.), intolerant (adj.)', 'Đồng nghĩa: endure, put up with', 'Đi theo sau bởi danh từ hoặc danh động từ: tolerate doing, không dùng to do.', 'I can tolerate noise, but not while studying.', NULL, 'Tôi có thể chịu đựng được tiếng ồn, nhưng không thể chịu được khi đang học bài.', '{"wordId":"tolerate","ukIpa":"/ˈtɒləreɪt/","usIpa":"/ˈtɑːləreɪt/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"To accept something unpleasant or unwanted without stopping it.","vi":"chịu đựng; dung thứ"},{"pos":"v.","en":"To withstand difficult conditions or substances without serious harm.","vi":"chịu được; kham nổi"}],"examples":[{"en":"I can tolerate noise, but not while studying.","vi":"Tôi có thể chịu đựng được tiếng ồn, nhưng không thể chịu được khi đang học bài.","audioKind":"ex"},{"en":"Schools should not tolerate bullying, because every student deserves a safe and supportive learning environment.","vi":"Nhà trường không nên dung thứ cho nạn bắt nạt học đường, bởi vì mọi học sinh đều xứng đáng có được một môi trường học tập an toàn và luôn nhận được sự hỗ trợ.","audioKind":"ex2"}],"collocations":[{"en":"tolerate noise","vi":"chịu ức tiếng ồn"},{"en":"tolerate uncertainty","vi":"chấp nhận sự bất định"},{"en":"tolerate heat","vi":"chịu đựng sức nóng"},{"en":"refuse to tolerate","vi":"từ chối dung thứ"}],"wordFamily":["tolerance (n.)","tolerant (adj.)","tolerable (adj.)","intolerant (adj.)"],"synonyms":["endure","put up with"],"antonyms":[],"tipVi":"Đi theo sau bởi danh từ hoặc danh động từ: tolerate doing, không dùng to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_progressive', 'en-b2-8', 'progressive', '/prəˈɡresɪv/', 'B2', 'tiến bộ; ủng hộ cải cách; tiến triển từng bước; dần dần; người có tư tưởng tiến bộ; người ủng hộ cải cách', 'adj.', 'progress (n.), progress (v.), progressively (adv.), progression (n.)', 'Đồng nghĩa: forward-thinking · Trái nghĩa: conservative', 'Có thể chỉ việc ủng hộ cải cách hoặc sự phát triển từng bước, không nhất thiết là theo hướng tốt hơn.', 'Our new manager has progressive ideas about flexible working.', NULL, 'Quản lý mới của chúng tôi có những ý tưởng tiến bộ về làm việc linh hoạt.', '{"wordId":"progressive","ukIpa":"/prəˈɡresɪv/","usIpa":"/prəˈɡresɪv/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"supporting new ideas and changes intended to improve society","vi":"tiến bộ; ủng hộ cải cách"},{"pos":"adj.","en":"happening or developing gradually over time","vi":"tiến triển từng bước; dần dần"},{"pos":"n.","en":"a person who supports social or political reform","vi":"người có tư tưởng tiến bộ; người ủng hộ cải cách"}],"examples":[{"en":"Our new manager has progressive ideas about flexible working.","vi":"Quản lý mới của chúng tôi có những ý tưởng tiến bộ về làm việc linh hoạt.","audioKind":"ex"},{"en":"Progressive education policies can promote equal opportunities by providing additional support for students from disadvantaged backgrounds.","vi":"Các chính sách giáo dục tiến bộ có thể thúc đẩy cơ hội bình đẳng bằng cách hỗ trợ thêm cho học sinh có hoàn cảnh khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"progressive policies","vi":"chính sách tiến bộ"},{"en":"progressive outlook","vi":"tư duy tiến bộ"},{"en":"progressive change","vi":"sự thay đổi từng bước"},{"en":"progressive taxation","vi":"thuế lũy tiến"}],"wordFamily":["progress (n.)","progress (v.)","progressively (adv.)","progression (n.)"],"synonyms":["forward-thinking"],"antonyms":["conservative"],"tipVi":"Có thể chỉ việc ủng hộ cải cách hoặc sự phát triển từng bước, không nhất thiết là theo hướng tốt hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_moral', 'en-b2-8', 'moral', '/ˈmɔːrəl/', 'B2', 'thuộc đạo đức; có đạo đức; ý nghĩa bài học; bài học đạo đức', 'adj.', 'morality (n.), morally (adv.), immoral (adj.)', 'Đồng nghĩa: ethical · Trái nghĩa: immoral', '"moral" chỉ đạo đức; "morale" chỉ sĩ khí, chú ý phân biệt cách viết.', 'Returning the lost wallet was clearly the moral choice.', NULL, 'Việc trả lại chiếc ví bị mất rõ ràng là một lựa chọn đúng đắn về mặt đạo đức.', '{"wordId":"moral","ukIpa":"/ˈmɒrəl/","usIpa":"/ˈmɔːrəl/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"concerning right and wrong, or following accepted standards of goodness","vi":"thuộc đạo đức; có đạo đức"},{"pos":"n.","en":"a lesson about right and wrong learned from a story","vi":"ý nghĩa bài học; bài học đạo đức"}],"examples":[{"en":"Returning the lost wallet was clearly the moral choice.","vi":"Việc trả lại chiếc ví bị mất rõ ràng là một lựa chọn đúng đắn về mặt đạo đức.","audioKind":"ex"},{"en":"Companies have a moral responsibility to ensure that their suppliers provide safe working conditions.","vi":"Các doanh nghiệp có trách nhiệm đạo đức trong việc đảm bảo rằng các nhà cung cấp của họ cung cấp điều kiện làm việc an toàn.","audioKind":"ex2"}],"collocations":[{"en":"moral responsibility","vi":"trách nhiệm đạo đức"},{"en":"moral dilemma","vi":"tình thế tiến thối lưỡng nan về đạo đức"},{"en":"moral support","vi":"sự hỗ trợ tinh thần"},{"en":"the moral of the story","vi":"ý nghĩa của câu chuyện"}],"wordFamily":["morality (n.)","morally (adv.)","immoral (adj.)"],"synonyms":["ethical"],"antonyms":["immoral"],"tipVi":"\"moral\" chỉ đạo đức; \"morale\" chỉ sĩ khí, chú ý phân biệt cách viết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_respectfully', 'en-b2-8', 'respectfully', '/rɪˈspektfəli/', 'B2', 'một cách cung kính; một cách tôn trọng', 'adv.', 'respect (n.), respect (v.), respectful (adj.)', 'Đồng nghĩa: politely, courteously · Trái nghĩa: disrespectfully, rudely', 'Đừng nhầm lẫn với "respectively" (tương ứng); từ này nhấn mạnh sự tôn trọng.', 'The children listened respectfully while their grandfather shared memories.', NULL, 'Lũ trẻ chăm chú lắng nghe một cách cung kính khi người ông chia sẻ những ký ức.', '{"wordId":"respectfully","ukIpa":"/rɪˈspektfəli/","usIpa":"/rɪˈspektfəli/","cefr":"B2","topic":"society","senses":[{"pos":"adv.","en":"In a way that shows politeness and regard for others.","vi":"một cách cung kính; một cách tôn trọng"}],"examples":[{"en":"The children listened respectfully while their grandfather shared memories.","vi":"Lũ trẻ chăm chú lắng nghe một cách cung kính khi người ông chia sẻ những ký ức.","audioKind":"ex"},{"en":"Students should learn to disagree respectfully with opposing views rather than dismissing them without careful consideration.","vi":"Học sinh nên học cách bày tỏ quan điểm trái chiều một cách tôn trọng thay vì bác bỏ chúng mà không suy nghĩ kỹ càng.","audioKind":"ex2"}],"collocations":[{"en":"respectfully disagree","vi":"lịch sự không đồng tình"},{"en":"respectfully request","vi":"kính cẩn yêu cầu"},{"en":"treat someone respectfully","vi":"đối xử với ai đó một cách tôn trọng"}],"wordFamily":["respect (n.)","respect (v.)","respectful (adj.)"],"synonyms":["politely","courteously"],"antonyms":["disrespectfully","rudely"],"tipVi":"Đừng nhầm lẫn với \"respectively\" (tương ứng); từ này nhấn mạnh sự tôn trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_orphan', 'en-b2-8', 'orphan', '/ˈɔːrfən/', 'B2', 'đứa trẻ mồ côi; làm cho mồ côi', 'n.', 'orphanage (n.)', NULL, 'Thường dùng be orphaned để chỉ việc mất cả cha lẫn mẹ mà trở thành mồ côi.', 'The story follows an orphan living with her aunt.', NULL, 'Câu chuyện xoay quanh một đứa trẻ mồ côi sống cùng người cô của mình.', '{"wordId":"orphan","ukIpa":"/ˈɔːfən/","usIpa":"/ˈɔːrfən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"a child whose parents have both died","vi":"đứa trẻ mồ côi"},{"pos":"v.","en":"to cause a child to lose both parents through death","vi":"làm cho mồ côi"}],"examples":[{"en":"The story follows an orphan living with her aunt.","vi":"Câu chuyện xoay quanh một đứa trẻ mồ côi sống cùng người cô của mình.","audioKind":"ex"},{"en":"Children orphaned by natural disasters need stable care, emotional support, and continued access to education.","vi":"Những đứa trẻ mồ côi do thiên tai cần được chăm sóc ổn định, hỗ trợ tinh thần và tiếp tục có cơ hội học tập.","audioKind":"ex2"}],"collocations":[{"en":"be orphaned at a young age","vi":"mồ côi từ khi còn nhỏ"},{"en":"care for orphans","vi":"chăm sóc trẻ mồ côi"},{"en":"an orphaned child","vi":"một đứa trẻ mồ côi"}],"wordFamily":["orphanage (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng be orphaned để chỉ việc mất cả cha lẫn mẹ mà trở thành mồ côi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_suspicion', 'en-b2-8', 'suspicion', '/səˈspɪʃən/', 'B2', 'sự hoài nghi; sự nghi ngờ; tình nghi; sự ngờ vực; sự thiếu lòng tin; chút ít; một chút', 'n.', 'suspect (v.), suspicious (adj.), suspiciously (adv.)', 'Đồng nghĩa: doubt, mistrust · Trái nghĩa: trust', 'Thường kết hợp với giới từ suspicion of hoặc mệnh đề suspicion that.', 'I had a suspicion that someone had moved my keys.', NULL, 'Tôi có linh cảm nghi ngờ rằng ai đó đã động vào chìa khóa của mình.', '{"wordId":"suspicion","ukIpa":"/səˈspɪʃən/","usIpa":"/səˈspɪʃən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"a belief that something is wrong without definite proof","vi":"sự hoài nghi; sự nghi ngờ; tình nghi"},{"pos":"n.","en":"a feeling that someone or something cannot be trusted","vi":"sự ngờ vực; sự thiếu lòng tin"},{"pos":"n.","en":"a very small amount of something","vi":"chút ít; một chút"}],"examples":[{"en":"I had a suspicion that someone had moved my keys.","vi":"Tôi có linh cảm nghi ngờ rằng ai đó đã động vào chìa khóa của mình.","audioKind":"ex"},{"en":"A lack of transparency can increase public suspicion of how government contracts are awarded.","vi":"Sự thiếu minh bạch có thể làm tăng mức độ hoài nghi của công chúng đối với cách thức trao các gói thầu chính phủ.","audioKind":"ex2"}],"collocations":[{"en":"arouse suspicion","vi":"gây nghi ngờ"},{"en":"under suspicion","vi":"đang bị nghi ngờ"},{"en":"on suspicion of theft","vi":"với nghi án trộm cắp"},{"en":"a suspicion that","vi":"sự hoài nghi rằng"}],"wordFamily":["suspect (v.)","suspicious (adj.)","suspiciously (adv.)"],"synonyms":["doubt","mistrust"],"antonyms":["trust"],"tipVi":"Thường kết hợp với giới từ suspicion of hoặc mệnh đề suspicion that.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_salute', 'en-b2-8', 'salute', '/səˈluːt/', 'B2', 'chào; giơ tay chào; ca ngợi; tôn vinh; lời chào; sự chào', 'v.', 'salutation (n.)', NULL, 'Động từ đi thẳng với tân ngữ chỉ người: salute someone, không cần dùng từ to.', 'The officer raised her hand to salute the captain.', NULL, 'Viên sĩ quan giơ tay chào vị đại úy.', '{"wordId":"salute","ukIpa":"/səˈluːt/","usIpa":"/səˈluːt/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"To show respect through a formal gesture, especially in the military.","vi":"chào; giơ tay chào"},{"pos":"v.","en":"To publicly express admiration for someone or their achievements.","vi":"ca ngợi; tôn vinh"},{"pos":"n.","en":"A formal gesture or action showing respect.","vi":"lời chào; sự chào"}],"examples":[{"en":"The officer raised her hand to salute the captain.","vi":"Viên sĩ quan giơ tay chào vị đại úy.","audioKind":"ex"},{"en":"Public ceremonies can salute the contributions of volunteers while encouraging more citizens to participate in community projects.","vi":"Các buổi lễ cộng đồng có thể vinh danh cống hiến của các tình nguyện viên đồng thời khích lệ thêm nhiều công dân tham gia vào các dự án xã hội.","audioKind":"ex2"}],"collocations":[{"en":"salute an officer","vi":"chào cấp trên"},{"en":"give a salute","vi":"thực hiện động tác chào"},{"en":"salute someone''s courage","vi":"ca ngợi lòng dũng cảm của ai đó"}],"wordFamily":["salutation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ đi thẳng với tân ngữ chỉ người: salute someone, không cần dùng từ to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pistol', 'en-b2-8', 'pistol', '/ˈpɪstəl/', 'B2', 'súng lục; súng ngắn', 'n.', NULL, 'Đồng nghĩa: handgun', 'pistol chỉ súng ngắn cầm tay; rifle thường chỉ súng trường dài.', 'The old pistol was displayed behind thick museum glass.', NULL, 'Khẩu súng ngắn cũ được trưng bày sau lớp kính dày trong bảo tàng.', '{"wordId":"pistol","ukIpa":"/ˈpɪstəl/","usIpa":"/ˈpɪstəl/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"A small gun designed to be held in one hand.","vi":"súng lục; súng ngắn"}],"examples":[{"en":"The old pistol was displayed behind thick museum glass.","vi":"Khẩu súng ngắn cũ được trưng bày sau lớp kính dày trong bảo tàng.","audioKind":"ex"},{"en":"Strict pistol storage requirements can reduce accidental injuries and improve safety in local communities.","vi":"Các quy định nghiêm ngặt về việc cất giữ súng ngắn có thể giúp giảm thiểu tai nạn thương tích và nâng cao mức độ an toàn tại các cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"carry a pistol","vi":"mặc súng ngắn; mang theo súng lục"},{"en":"a starting pistol","vi":"súng hiệu lệnh xuất phát"},{"en":"an antique pistol","vi":"súng ngắn cổ"}],"wordFamily":[],"synonyms":["handgun"],"antonyms":[],"tipVi":"pistol chỉ súng ngắn cầm tay; rifle thường chỉ súng trường dài.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dominant', 'en-b2-8', 'dominant', '/ˈdɑːmənənt/', 'B2', 'chiếm ưu thế; có chủ đạo; trội', 'adj.', 'dominate (v.), dominance (n.)', 'Đồng nghĩa: leading, predominant · Trái nghĩa: subordinate', 'Dominant là tính từ; dominate là động từ.', 'Blue is the dominant colour in our living room.', NULL, 'Màu xanh dương là tông màu chủ đạo trong phòng khách của chúng tôi.', '{"wordId":"dominant","ukIpa":"/ˈdɒmɪnənt/","usIpa":"/ˈdɑːmənənt/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"More powerful, influential, or noticeable than others.","vi":"chiếm ưu thế; có chủ đạo"},{"pos":"adj.","en":"Expressed when at least one copy of a gene is present.","vi":"trội"}],"examples":[{"en":"Blue is the dominant colour in our living room.","vi":"Màu xanh dương là tông màu chủ đạo trong phòng khách của chúng tôi.","audioKind":"ex"},{"en":"Private cars remain the dominant form of transport in cities with limited investment in public transport.","vi":"Xe hơi cá nhân vẫn là phương tiện giao thông chiếm ưu thế tại các thành phố có nguồn đầu tư hạn chế cho giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"a dominant role","vi":"vai trò chủ đạo"},{"en":"a dominant position","vi":"vị thế thống trị"},{"en":"the dominant culture","vi":"văn hóa chủ đạo"},{"en":"a dominant gene","vi":"gen trội"}],"wordFamily":["dominate (v.)","dominance (n.)"],"synonyms":["leading","predominant"],"antonyms":["subordinate"],"tipVi":"Dominant là tính từ; dominate là động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_entitle', 'en-b2-8', 'entitle', '/ɪnˈtaɪtəl/', 'B2', 'cho quyền; cho phép hưởng; đặt tên; đặt tựa đề', 'v.', 'entitlement (n.), entitled (adj.)', NULL, 'Cấu trúc entitle sb to sth hoặc to do sth; hay gặp ở thể bị động.', 'This ticket entitles you to a free lunch.', NULL, 'Vé này cho phép bạn được hưởng một bữa trưa miễn phí.', '{"wordId":"entitle","ukIpa":"/ɪnˈtaɪtəl/","usIpa":"/ɪnˈtaɪtəl/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"To give someone the right to have or do something.","vi":"cho quyền; cho phép hưởng"},{"pos":"v.","en":"To give a name to a book, film, or other work.","vi":"đặt tên; đặt tựa đề"}],"examples":[{"en":"This ticket entitles you to a free lunch.","vi":"Vé này cho phép bạn được hưởng một bữa trưa miễn phí.","audioKind":"ex"},{"en":"Employment laws should entitle all workers to paid leave, regardless of the size of their organisation.","vi":"Luật lao động nên trao cho tất cả người lao động quyền nghỉ phép có lương, bất kể quy mô tổ chức của họ lớn hay nhỏ.","audioKind":"ex2"}],"collocations":[{"en":"entitle someone to benefits","vi":"cho phép ai hưởng quyền lợi"},{"en":"be entitled to compensation","vi":"được quyền nhận bồi thường"},{"en":"be entitled to vote","vi":"có quyền đi bầu cử"}],"wordFamily":["entitlement (n.)","entitled (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc entitle sb to sth hoặc to do sth; hay gặp ở thể bị động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_regional', 'en-b2-8', 'regional', '/ˈriːdʒənəl/', 'B2', 'thuộc vùng; mang tính khu vực; địa phương', 'adj.', 'region (n.), regionally (adv.)', NULL, 'Phạm vi của regional thường lớn hơn local và nhỏ hơn national.', 'The market sells regional cheeses made in nearby villages.', NULL, 'Khu chợ bán các loại phô mai mang hương vị đặc trưng vùng miền được làm ở các ngôi làng lân cận.', '{"wordId":"regional","ukIpa":"/ˈriːdʒənəl/","usIpa":"/ˈriːdʒənəl/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Relating to a particular area within a country or world.","vi":"thuộc vùng; mang tính khu vực; địa phương"}],"examples":[{"en":"The market sells regional cheeses made in nearby villages.","vi":"Khu chợ bán các loại phô mai mang hương vị đặc trưng vùng miền được làm ở các ngôi làng lân cận.","audioKind":"ex"},{"en":"Regional differences in employment opportunities often encourage young adults to move from rural communities to larger cities.","vi":"Sự khác biệt về cơ hội việc làm giữa các vùng miền thường thúc đẩy thanh niên di chuyển từ vùng nông thôn đến các thành phố lớn hơn.","audioKind":"ex2"}],"collocations":[{"en":"regional development","vi":"phát triển vùng"},{"en":"regional differences","vi":"sự khác biệt vùng miền"},{"en":"regional economy","vi":"kinh tế khu vực"},{"en":"regional cooperation","vi":"hợp tác khu vực"}],"wordFamily":["region (n.)","regionally (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Phạm vi của regional thường lớn hơn local và nhỏ hơn national.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_8_1', 'en-b2-8', 'Cách dùng “torture” (n.) — sự tra tấn; cực hình; nỗi giày vò', 'psychological torture  ·  pure torture  ·  prohibit torture', 'Mang sắc thái nghĩa rất mạnh; trong giao tiếp hằng ngày có thể dùng để nói quá về sự giày vò, chứ không chỉ là sự khó chịu thông thường.', 'Họ từ (Word Family): torturer (n.), tortured (adj.) | Đồng nghĩa: torment, agony', '[{"hanzi":"Waiting all afternoon for the results was pure torture.","pinyin":"","meaning":"Chờ đợi kết quả suốt cả buổi chiều thật sự là một cực hình."},{"hanzi":"International agreements prohibit torture and require governments to protect the basic rights of all prisoners.","pinyin":"","meaning":"Các hiệp định quốc tế nghiêm cấm việc tra tấn và yêu cầu chính phủ các nước bảo vệ các quyền cơ bản của mọi tù nhân."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_8_2', 'en-b2-8', 'Cách dùng “greedy” (adj.) — tham lam; hám lợi', 'greedy for money  ·  greedy for power  ·  a greedy investor', 'Thường mang nghĩa tiêu cực; sau "greedy for" là thứ mà ai đó tham lam muốn có (như tiền bạc, quyền lực).', 'Họ từ (Word Family): greed (n.), greedily (adv.), greediness (n.) | Đồng nghĩa: avaricious · Trái nghĩa: generous', '[{"hanzi":"Don''t be greedy; leave some biscuits for your sister.","pinyin":"","meaning":"Đừng tham ăn thế; hãy để phần bánh quy cho em gái con nữa."},{"hanzi":"Greedy investors may prioritise immediate profits over the long-term environmental consequences of their business decisions.","pinyin":"","meaning":"Những nhà đầu tư tham lam có thể đặt lợi nhuận trước mắt lên trên những hệ quả môi trường lâu dài từ các quyết định kinh doanh của họ."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_8_3', 'en-b2-8', 'Cách dùng “upbringing” (n.) — sự nuôi nấng; sự dạy dỗ; giáo dục gia đình', 'a strict upbringing  ·  a sheltered upbringing  ·  a privileged upbringing', 'Chỉ việc nuôi dưỡng và giáo dục trong gia đình thời thơ ấu, không đồng nghĩa với giáo dục ở trường học.', 'Họ từ (Word Family): bring up (v.)', '[{"hanzi":"Her upbringing taught her to share with others.","pinyin":"","meaning":"Cách giáo dục của gia đình đã dạy cô ấy biết chia sẻ với người khác."},{"hanzi":"A supportive upbringing can help children develop confidence and cope more effectively with challenges at school.","pinyin":"","meaning":"Sự nuôi dạy đầy sự nâng đỡ có thể giúp trẻ em phát triển sự tự tin và đối phó hiệu quả hơn với các thử thách ở trường."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_8_4', 'en-b2-8', 'Cách dùng “progressive” (adj.) — tiến bộ; ủng hộ cải cách', 'progressive policies  ·  progressive outlook  ·  progressive change', 'Có thể chỉ việc ủng hộ cải cách hoặc sự phát triển từng bước, không nhất thiết là theo hướng tốt hơn.', 'Họ từ (Word Family): progress (n.), progress (v.), progressively (adv.), progression (n.) | Đồng nghĩa: forward-thinking · Trái nghĩa: conservative', '[{"hanzi":"Our new manager has progressive ideas about flexible working.","pinyin":"","meaning":"Quản lý mới của chúng tôi có những ý tưởng tiến bộ về làm việc linh hoạt."},{"hanzi":"Progressive education policies can promote equal opportunities by providing additional support for students from disadvantaged backgrounds.","pinyin":"","meaning":"Các chính sách giáo dục tiến bộ có thể thúc đẩy cơ hội bình đẳng bằng cách hỗ trợ thêm cho học sinh có hoàn cảnh khó khăn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_8_1', 'en-b2-8', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_8_1_1', 'ten_b2_8_1', 'approachable', 'Our new teacher seems approachable, so I asked for help.', 'Our new teacher seems approachable, so I asked for help.', '/əˈproʊtʃəbl/', 'Giáo viên mới của chúng tôi có vẻ rất dễ gần, nên tôi đã nhờ cô giúp đỡ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_8_1_2', 'ten_b2_8_1', 'rally', 'Hundreds attended a peaceful rally in the town square.', 'Hundreds attended a peaceful rally in the town square.', '/ˈræli/', 'Hàng trăm người đã tham gia một cuộc mít tinh ôn hòa ở quảng trường thị trấn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_8_1_3', 'ten_b2_8_1', 'upbringing', 'Her upbringing taught her to share with others.', 'Her upbringing taught her to share with others.', '/ˈʌpbrɪŋɪŋ/', 'Cách giáo dục của gia đình đã dạy cô ấy biết chia sẻ với người khác.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_8_1_4', 'ten_b2_8_1', 'fellow', 'I shared my umbrella with a fellow passenger.', 'I shared my umbrella with a fellow passenger.', '/ˈfeloʊ/', 'Tôi đã chia sẻ chiếc ô của mình với một hành khách cùng chuyến.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_8_1_5', 'ten_b2_8_1', 'torture', 'Waiting all afternoon for the results was pure torture.', 'Waiting all afternoon for the results was pure torture.', '/ˈtɔːrtʃər/', 'Chờ đợi kết quả suốt cả buổi chiều thật sự là một cực hình.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_8_1_6', 'ten_b2_8_1', 'greedy', 'Don''t be greedy; leave some biscuits for your sister.', 'Don''t be greedy; leave some biscuits for your sister.', '/ˈɡriːdi/', 'Đừng tham ăn thế; hãy để phần bánh quy cho em gái con nữa.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_8_1_7', 'ten_b2_8_1', 'soul', 'Walking beside the sea always seems to soothe my soul.', 'Walking beside the sea always seems to soothe my soul.', '/soʊl/', 'Đi dạo dọc bờ biển dường như luôn giúp xoa dịu tâm hồn tôi.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_8_1_8', 'ten_b2_8_1', 'anonymous', 'An anonymous donor paid for the children''s new playground.', 'An anonymous donor paid for the children''s new playground.', '/əˈnɑːnəməs/', 'Một nhà hảo tâm giấu tên đã tài trợ tiền làm sân chơi mới cho lũ trẻ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_8_1_1', 'en-b2-8', 'ten_b2_8_1', 'listening', 'listening', 'Our new teacher seems approachable, so I asked for help.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Con thuyền cứu hộ chở cả binh lính lẫn thường dân.","Viên sĩ quan giơ tay chào vị đại úy.","Một nhà hảo tâm giấu tên đã tài trợ tiền làm sân chơi mới cho lũ trẻ.","Giáo viên mới của chúng tôi có vẻ rất dễ gần, nên tôi đã nhờ cô giúp đỡ."]'::jsonb, 3, 'Our new teacher seems approachable, so I asked for help. → Giáo viên mới của chúng tôi có vẻ rất dễ gần, nên tôi đã nhờ cô giúp đỡ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_8_1_2', 'en-b2-8', 'ten_b2_8_1', 'listening', 'listening', 'Hundreds attended a peaceful rally in the town square.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Lũ trẻ chăm chú lắng nghe một cách cung kính khi người ông chia sẻ những ký ức.","Đi dạo dọc bờ biển dường như luôn giúp xoa dịu tâm hồn tôi.","Khẩu súng ngắn cũ được trưng bày sau lớp kính dày trong bảo tàng.","Hàng trăm người đã tham gia một cuộc mít tinh ôn hòa ở quảng trường thị trấn."]'::jsonb, 3, 'Hundreds attended a peaceful rally in the town square. → Hàng trăm người đã tham gia một cuộc mít tinh ôn hòa ở quảng trường thị trấn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_8_1_3', 'en-b2-8', 'ten_b2_8_1', 'listening', 'listening', 'Her upbringing taught her to share with others.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hãy kể sự thật về việc chiếc bình hoa bị vỡ như thế nào nhé.","Cách giáo dục của gia đình đã dạy cô ấy biết chia sẻ với người khác.","Giáo viên mới của chúng tôi có vẻ rất dễ gần, nên tôi đã nhờ cô giúp đỡ.","Khu chợ bán các loại phô mai mang hương vị đặc trưng vùng miền được làm ở các ngôi làng lân cận."]'::jsonb, 1, 'Her upbringing taught her to share with others. → Cách giáo dục của gia đình đã dạy cô ấy biết chia sẻ với người khác.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_8_2', 'en-b2-8', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_8_2_1', 'ten_b2_8_2', 'approachable', 'Approachable healthcare professionals may encourage patients to discuss sensitive concerns before their conditions become more serious.', 'Approachable healthcare professionals may encourage patients to discuss sensitive concerns before their conditions become more serious.', '/əˈproʊtʃəbl/', 'Các chuyên gia y tế thân thiện, dễ gần có thể khuyến khích bệnh nhân thảo luận về những lo lắng tế nhị trước khi tình trạng bệnh trở nên nghiêm trọng hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_8_2_2', 'ten_b2_8_2', 'rally', 'Community leaders rallied support for a public library, arguing that free access to information benefits everyone.', 'Community leaders rallied support for a public library, arguing that free access to information benefits everyone.', '/ˈræli/', 'Các nhà lãnh đạo cộng đồng đã kêu gọi sự ủng hộ cho một thư viện công cộng, với lập luận rằng việc tiếp cận thông tin miễn phí mang lại lợi ích cho tất cả mọi người.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_8_2_3', 'ten_b2_8_2', 'upbringing', 'A supportive upbringing can help children develop confidence and cope more effectively with challenges at school.', 'A supportive upbringing can help children develop confidence and cope more effectively with challenges at school.', '/ˈʌpbrɪŋɪŋ/', 'Sự nuôi dạy đầy sự nâng đỡ có thể giúp trẻ em phát triển sự tự tin và đối phó hiệu quả hơn với các thử thách ở trường.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_8_2_4', 'ten_b2_8_2', 'fellow', 'Students who regularly exchange ideas with fellow learners often develop greater confidence and stronger communication skills.', 'Students who regularly exchange ideas with fellow learners often develop greater confidence and stronger communication skills.', '/ˈfeloʊ/', 'Những học sinh thường xuyên trao đổi ý tưởng với các bạn học thường phát triển sự tự tin lớn hơn và kỹ năng giao tiếp mạnh mẽ hơn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_8_2_5', 'ten_b2_8_2', 'torture', 'International agreements prohibit torture and require governments to protect the basic rights of all prisoners.', 'International agreements prohibit torture and require governments to protect the basic rights of all prisoners.', '/ˈtɔːrtʃər/', 'Các hiệp định quốc tế nghiêm cấm việc tra tấn và yêu cầu chính phủ các nước bảo vệ các quyền cơ bản của mọi tù nhân.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_8_2_6', 'ten_b2_8_2', 'greedy', 'Greedy investors may prioritise immediate profits over the long-term environmental consequences of their business decisions.', 'Greedy investors may prioritise immediate profits over the long-term environmental consequences of their business decisions.', '/ˈɡriːdi/', 'Những nhà đầu tư tham lam có thể đặt lợi nhuận trước mắt lên trên những hệ quả môi trường lâu dài từ các quyết định kinh doanh của họ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_8_2_1', 'en-b2-8', 'ten_b2_8_2', 'listening', 'listening', 'Approachable healthcare professionals may encourage patients to discuss sensitive concerns before their conditions become more serious.', NULL, 'Trong câu vừa nghe, từ “approachable” mang nghĩa nào sau đây?', '["sự bối rối; sự ngượng ngùng","gần gũi; thân thiện; dễ gần","địa ngục","chinh phục; chiếm đóng"]'::jsonb, 1, '“approachable” (/əˈproʊtʃəbl/): gần gũi; thân thiện; dễ gần. Câu đầy đủ: Approachable healthcare professionals may encourage patients to discuss sensitive concerns before their conditions become more serious.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_8_2_2', 'en-b2-8', 'ten_b2_8_2', 'listening', 'listening', 'Community leaders rallied support for a public library, arguing that free access to information benefits everyone.', NULL, 'Trong câu vừa nghe, từ “rally” mang nghĩa nào sau đây?', '["có tính chiếm hữu; ích kỷ trong quan hệ","cuộc mít tinh; cuộc biểu tình","men; men nở; nấm men","giới tính (mang tính xã hội và văn hóa)"]'::jsonb, 1, '“rally” (/ˈræli/): cuộc mít tinh; cuộc biểu tình. Câu đầy đủ: Community leaders rallied support for a public library, arguing that free access to information benefits everyone.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
