INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_8_2', 'en-b2-8', 'Hundreds attended a peaceful rally in the town square', 'Hàng trăm người đã tham gia một cuộc mít tinh ôn hòa ở quảng trường thị trấn.', 'rally /ˈræli/', '["a","attended","town","peaceful","in","the","rally","square","Hundreds"]'::jsonb, NULL, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_8_3', 'en-b2-8', 'Her upbringing taught her to share with others', 'Cách giáo dục của gia đình đã dạy cô ấy biết chia sẻ với người khác.', 'upbringing /ˈʌpbrɪŋɪŋ/', '["upbringing","taught","to","share","her","others","with","Her"]'::jsonb, NULL, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_8_4', 'en-b2-8', 'I shared my umbrella with a fellow passenger', 'Tôi đã chia sẻ chiếc ô của mình với một hành khách cùng chuyến.', 'fellow /ˈfeloʊ/', '["my","passenger","I","with","a","shared","fellow","umbrella"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_8_5', 'en-b2-8', 'Waiting all afternoon for the results was pure torture', 'Chờ đợi kết quả suốt cả buổi chiều thật sự là một cực hình.', 'torture /ˈtɔːrtʃər/', '["all","afternoon","was","for","torture","the","Waiting","pure","results"]'::jsonb, NULL, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_8_6', 'en-b2-8', 'Don''t be greedy; leave some biscuits for your sister', 'Đừng tham ăn thế; hãy để phần bánh quy cho em gái con nữa.', 'greedy /ˈɡriːdi/', '["Don''t","biscuits","some","your","for","leave","greedy","sister","be"]'::jsonb, NULL, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_8_7', 'en-b2-8', 'Walking beside the sea always seems to soothe my soul', 'Đi dạo dọc bờ biển dường như luôn giúp xoa dịu tâm hồn tôi.', 'soul /soʊl/', '["always","beside","to","seems","my","Walking","the","soul","soothe","sea"]'::jsonb, NULL, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_8_8', 'en-b2-8', 'An anonymous donor paid for the children''s new playground', 'Một nhà hảo tâm giấu tên đã tài trợ tiền làm sân chơi mới cho lũ trẻ.', 'anonymous /əˈnɑːnəməs/', '["for","paid","donor","An","playground","new","anonymous","the","children''s"]'::jsonb, NULL, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_8_9', 'en-b2-8', 'The rescue boat carried both soldiers and civilians', 'Con thuyền cứu hộ chở cả binh lính lẫn thường dân.', 'civilian /səˈvɪliən/', '["carried","rescue","soldiers","civilians","and","boat","The","both"]'::jsonb, NULL, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
