INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_8_1', 'en-b2-8', NULL, 'comprehensive_test', 'listening', 'approachable', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["trên (thường dùng trong văn phong trang trọng hoặc văn chương)","gần gũi; thân thiện; dễ gần","chuyên gia tư vấn; cố vấn tâm lý; giáo viên hướng dẫn","không thực tế; không khả thi"]'::jsonb, 1, 'approachable (/əˈproʊtʃəbl/) → gần gũi; thân thiện; dễ gần; dễ tiếp cận; dễ hiểu', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_8_2', 'en-b2-8', NULL, 'comprehensive_test', 'listening', 'Hundreds attended a peaceful rally in the town square.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hàng trăm người đã tham gia một cuộc mít tinh ôn hòa ở quảng trường thị trấn.","Viên sĩ quan giơ tay chào vị đại úy.","Màu xanh dương là tông màu chủ đạo trong phòng khách của chúng tôi.","Đi dạo dọc bờ biển dường như luôn giúp xoa dịu tâm hồn tôi."]'::jsonb, 0, 'Hundreds attended a peaceful rally in the town square. → Hàng trăm người đã tham gia một cuộc mít tinh ôn hòa ở quảng trường thị trấn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_8_3', 'en-b2-8', NULL, 'comprehensive_test', 'listening', 'upbringing', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["vắc-xin; chất kích thích hệ miễn dịch chống lại bệnh tật","sự nuôi nấng; sự dạy dỗ; giáo dục gia đình","người chỉ huy (dàn nhạc, hợp xướng)","đống lớn; khối lớn; lượng lớn"]'::jsonb, 1, 'upbringing (/ˈʌpbrɪŋɪŋ/) → sự nuôi nấng; sự dạy dỗ; giáo dục gia đình', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_8_4', 'en-b2-8', NULL, 'comprehensive_test', 'listening', 'I shared my umbrella with a fellow passenger.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã chia sẻ chiếc ô của mình với một hành khách cùng chuyến.","Con thuyền cứu hộ chở cả binh lính lẫn thường dân.","Hàng trăm người đã tham gia một cuộc mít tinh ôn hòa ở quảng trường thị trấn.","Lũ trẻ chăm chú lắng nghe một cách cung kính khi người ông chia sẻ những ký ức."]'::jsonb, 0, 'I shared my umbrella with a fellow passenger. → Tôi đã chia sẻ chiếc ô của mình với một hành khách cùng chuyến.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_8_5', 'en-b2-8', NULL, 'comprehensive_test', 'listening', 'torture', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự tra tấn; cực hình; nỗi giày vò","đầy đủ; thỏa đáng; tương xứng","kỷ luật; tính tự giác","lãnh thổ; vùng đất; khu vực"]'::jsonb, 0, 'torture (/ˈtɔːrtʃər/) → sự tra tấn; cực hình; nỗi giày vò; tra tấn; hành hạ; giày vò', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_8_6', 'en-b2-8', NULL, 'comprehensive_test', 'listening', 'Don''t be greedy; leave some biscuits for your sister.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Đừng để làn da tiếp xúc với ánh nắng gay gắt mà không có biện pháp bảo vệ.","Tôi có linh cảm nghi ngờ rằng ai đó đã động vào chìa khóa của mình.","Đừng tham ăn thế; hãy để phần bánh quy cho em gái con nữa.","Viên sĩ quan giơ tay chào vị đại úy."]'::jsonb, 2, 'Don''t be greedy; leave some biscuits for your sister. → Đừng tham ăn thế; hãy để phần bánh quy cho em gái con nữa.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_8_7', 'en-b2-8', NULL, 'comprehensive_test', 'listening', 'soul', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thu được; tìm thấy; nhận được","tâm hồn; linh hồn","nhà trệt; nhà một tầng","nhà thiên văn học"]'::jsonb, 1, 'soul (/soʊl/) → tâm hồn; linh hồn; con người; cá nhân; nhạc soul; dòng nhạc soul đặc trưng', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_8_8', 'en-b2-8', NULL, 'comprehensive_test', 'listening', 'An anonymous donor paid for the children''s new playground.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một nhà hảo tâm giấu tên đã tài trợ tiền làm sân chơi mới cho lũ trẻ.","Vé này cho phép bạn được hưởng một bữa trưa miễn phí.","Tôi có linh cảm nghi ngờ rằng ai đó đã động vào chìa khóa của mình.","Viên sĩ quan giơ tay chào vị đại úy."]'::jsonb, 0, 'An anonymous donor paid for the children''s new playground. → Một nhà hảo tâm giấu tên đã tài trợ tiền làm sân chơi mới cho lũ trẻ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_8_9', 'en-b2-8', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “deliberately inflicted severe pain, or an extremely distressing experience”?', '["truthful","soul","torture","respectfully"]'::jsonb, 2, 'torture (/ˈtɔːrtʃər/) → sự tra tấn; cực hình; nỗi giày vò', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
