INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_8_18', 'en-b2-8', NULL, 'comprehensive_test', 'reading', NULL, 'Approachable healthcare professionals may encourage patients to discuss sensitive concerns before their conditions become more serious.', 'Dựa vào câu trên, từ “approachable” có nghĩa phù hợp nhất là gì?', '["khả năng phán đoán; sự đánh giá","điểm cao trào; đỉnh điểm","gần gũi; thân thiện; dễ gần","liên kết; đoàn kết; thống nhất"]'::jsonb, 2, 'approachable: gần gũi; thân thiện; dễ gần; dễ tiếp cận; dễ hiểu. Dịch cả câu: Các chuyên gia y tế thân thiện, dễ gần có thể khuyến khích bệnh nhân thảo luận về những lo lắng tế nhị trước khi tình trạng bệnh trở nên nghiêm trọng hơn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_8_19', 'en-b2-8', NULL, 'comprehensive_test', 'reading', NULL, 'Community leaders rallied support for a public library, arguing that free access to information benefits everyone.', 'Dựa vào câu trên, từ “rally” có nghĩa phù hợp nhất là gì?', '["cuộc mít tinh; cuộc biểu tình","nhím gai nhỏ (nhím ăn sâu bọ)","khoảng thời gian; khoảng cách","đàn (chim, cừu hoặc dê)"]'::jsonb, 0, 'rally: cuộc mít tinh; cuộc biểu tình; tập hợp; kêu gọi ủng hộ; phục hồi; hồi sức; tăng trở lại. Dịch cả câu: Các nhà lãnh đạo cộng đồng đã kêu gọi sự ủng hộ cho một thư viện công cộng, với lập luận rằng việc tiếp cận thông tin miễn phí mang lại lợi ích cho tất cả mọi người.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_8_20', 'en-b2-8', NULL, 'comprehensive_test', 'reading', NULL, 'A supportive upbringing can help children develop confidence and cope more effectively with challenges at school.', 'Dựa vào câu trên, từ “upbringing” có nghĩa phù hợp nhất là gì?', '["sự điên rồ; hành vi cực kỳ ng U dốt và nguy hiểm","sự nuôi nấng; sự dạy dỗ; giáo dục gia đình","chiếm; chiếm giữ; chiếm lĩnh không gian/thời gian","sự phê duyệt; sự cho phép"]'::jsonb, 1, 'upbringing: sự nuôi nấng; sự dạy dỗ; giáo dục gia đình. Dịch cả câu: Sự nuôi dạy đầy sự nâng đỡ có thể giúp trẻ em phát triển sự tự tin và đối phó hiệu quả hơn với các thử thách ở trường.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_8_21', 'en-b2-8', NULL, 'comprehensive_test', 'reading', NULL, 'Students who regularly exchange ideas with fellow learners often develop greater confidence and stronger communication skills.', 'Dựa vào câu trên, từ “fellow” có nghĩa phù hợp nhất là gì?', '["làm nhiễm trùng; lây bệnh","người ứng tuyển; thí sinh; người nộp đơn","bản năng; thiên tính","cùng cảnh ngộ; có chung hoàn cảnh"]'::jsonb, 3, 'fellow: cùng cảnh ngộ; có chung hoàn cảnh; anh chàng; gã; hội viên; nghiên cứu viên. Dịch cả câu: Những học sinh thường xuyên trao đổi ý tưởng với các bạn học thường phát triển sự tự tin lớn hơn và kỹ năng giao tiếp mạnh mẽ hơn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_8_22', 'en-b2-8', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “chiếm ưu thế; có chủ đạo”', '["terrify","inherit","hesitant","dominant"]'::jsonb, 3, 'chiếm ưu thế; có chủ đạo → dominant (/ˈdɑːmənənt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_8_23', 'en-b2-8', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cho quyền; cho phép hưởng”', '["disturbance","chill","entitle","saddle"]'::jsonb, 2, 'cho quyền; cho phép hưởng → entitle (/ɪnˈtaɪtəl/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_8_24', 'en-b2-8', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thuộc vùng; mang tính khu vực; địa phương”', '["regional","pollutant","maximize","rooster"]'::jsonb, 0, 'thuộc vùng; mang tính khu vực; địa phương → regional (/ˈriːdʒənəl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-9', 'en', 'Bài 9: Xã hội & Cộng đồng (2) - CEFR B2', 'CEFR B2', 'B2 · Xã hội', '26 từ vựng Tiếng Anh CEFR B2 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4009, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_institution', 'en-b2-9', 'institution', '/ˌɪnstɪˈtuːʃən/', 'B2', 'cơ quan; tổ chức; viện; thể chế; phong tục lâu đời', 'n.', 'institutional (adj.), institutionalise (v.)', NULL, 'Có thể chỉ tổ chức cụ thể hoặc các thể chế xã hội như hôn nhân.', 'My sister works at a respected institution near home.', NULL, 'Chị tôi làm việc tại một cơ quan có uy tín gần nhà.', '{"wordId":"institution","ukIpa":"/ˌɪnstɪˈtjuːʃən/","usIpa":"/ˌɪnstɪˈtuːʃən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"An established organisation serving an educational, financial, or public purpose.","vi":"cơ quan; tổ chức; viện"},{"pos":"n.","en":"An established custom or system within a society.","vi":"thể chế; phong tục lâu đời"}],"examples":[{"en":"My sister works at a respected institution near home.","vi":"Chị tôi làm việc tại một cơ quan có uy tín gần nhà.","audioKind":"ex"},{"en":"Every educational institution should provide accessible facilities and appropriate support for students with disabilities.","vi":"Mỗi cơ chế giáo dục nên cung cấp các tiện ích tiếp cận dễ dàng và sự hỗ trợ phù hợp cho học sinh khuyết tật.","audioKind":"ex2"}],"collocations":[{"en":"educational institution","vi":"cơ sở giáo dục"},{"en":"financial institution","vi":"tổ chức tài chính"},{"en":"the institution of marriage","vi":"thể chế hôn nhân"}],"wordFamily":["institutional (adj.)","institutionalise (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể chỉ tổ chức cụ thể hoặc các thể chế xã hội như hôn nhân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_childish', 'en-b2-9', 'childish', '/ˈtʃaɪldɪʃ/', 'B2', 'ấu trĩ; trẻ con; không chín chắn; thuộc về trẻ em; mang tính trẻ thơ', 'adj.', 'child (n.), childhood (n.), childishly (adv.), childishness (n.)', 'Đồng nghĩa: immature · Trái nghĩa: mature', 'childish thường mang sắc thái chê bai; childlike thiên về sự trong sáng, ngây thơ.', 'Hiding my shoes was a childish thing to do.', NULL, 'Giấu giày của tôi đi là một hành động thật trẻ con.', '{"wordId":"childish","ukIpa":"/ˈtʃaɪldɪʃ/","usIpa":"/ˈtʃaɪldɪʃ/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Behaving immaturely in a way unsuitable for an adult.","vi":"ấu trĩ; trẻ con; không chín chắn"},{"pos":"adj.","en":"Typical of or connected with children.","vi":"thuộc về trẻ em; mang tính trẻ thơ"}],"examples":[{"en":"Hiding my shoes was a childish thing to do.","vi":"Giấu giày của tôi đi là một hành động thật trẻ con.","audioKind":"ex"},{"en":"Dismissing young people''s concerns as childish can discourage them from participating in discussions about their communities.","vi":"Việc gạt bỏ những bận tâm của giới trẻ là ấu trĩ có thể khiến họ nản lòng, không muốn tham gia các cuộc thảo luận về vấn đề cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"childish behaviour","vi":"hành vi trẻ con"},{"en":"childish argument","vi":"cuộc cãi vã ngớ ngẩn"},{"en":"childish delight","vi":"niềm vui ngây thơ"}],"wordFamily":["child (n.)","childhood (n.)","childishly (adv.)","childishness (n.)"],"synonyms":["immature"],"antonyms":["mature"],"tipVi":"childish thường mang sắc thái chê bai; childlike thiên về sự trong sáng, ngây thơ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_honour', 'en-b2-9', 'honour', '/ˈɑːnər/', 'B2', 'vinh dự; lòng tự trọng; niềm tự hào; tôn vinh; tỏ lòng kính trọng; biểu dương; thực hiện; giữ (lời hứa, cam kết)', 'n.', 'honourable (adj.), honoured (adj.), dishonour (n.)', 'Đồng nghĩa: respect, esteem · Trái nghĩa: dishonour', 'Từ ''honour'' viết theo Anh-Anh, ''honor'' viết theo Anh-Mỹ; chữ ''h'' không được phát âm nên dùng mạo từ ''an''.', 'It was an honour to represent my local team.', NULL, 'Thật là một vinh dự lớn khi được đại diện cho đội bóng địa phương của tôi.', '{"wordId":"honour","ukIpa":"/ˈɒnə/","usIpa":"/ˈɑːnər/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"Great respect, or something that brings pride and privilege.","vi":"vinh dự; lòng tự trọng; niềm tự hào"},{"pos":"v.","en":"To show deep respect or publicly recognize someone''s achievements.","vi":"tôn vinh; tỏ lòng kính trọng; biểu dương"},{"pos":"v.","en":"To do what a promise or agreement requires.","vi":"thực hiện; giữ (lời hứa, cam kết)"}],"examples":[{"en":"It was an honour to represent my local team.","vi":"Thật là một vinh dự lớn khi được đại diện cho đội bóng địa phương của tôi.","audioKind":"ex"},{"en":"Companies must honour their commitments to workers if they hope to maintain trust and reduce staff turnover.","vi":"Các công ty phải thực hiện cam kết của mình với người lao động nếu họ muốn duy trì lòng tin và giảm tỷ lệ nhân viên nghỉ việc.","audioKind":"ex2"}],"collocations":[{"en":"a great honour","vi":"vinh dự lớn"},{"en":"in honour of","vi":"để tưởng nhớ; để bày tỏ lòng kính trọng đối với"},{"en":"honour a commitment","vi":"thực hiện cam kết"},{"en":"a guest of honour","vi":"khách mời danh dự"}],"wordFamily":["honourable (adj.)","honoured (adj.)","dishonour (n.)"],"synonyms":["respect","esteem"],"antonyms":["dishonour"],"tipVi":"Từ ''honour'' viết theo Anh-Anh, ''honor'' viết theo Anh-Mỹ; chữ ''h'' không được phát âm nên dùng mạo từ ''an''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deny', 'en-b2-9', 'deny', '/dɪˈnaɪ/', 'B2', 'phủ nhận; chối bỏ; từ chối cung cấp; tước đoạt', 'v.', 'denial (n.), deniable (adj.), undeniable (adj.)', 'Trái nghĩa: admit', 'Cấu trúc phủ nhận làm gì dùng ''deny doing'', không dùng ''deny to do''.', 'She denied eating the last piece of cake.', NULL, 'Cô ấy chối đã ăn miếng bánh cuối cùng.', '{"wordId":"deny","ukIpa":"/dɪˈnaɪ/","usIpa":"/dɪˈnaɪ/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"Say that something is not true or did not happen.","vi":"phủ nhận; chối bỏ"},{"pos":"v.","en":"Refuse to give or allow someone something.","vi":"từ chối cung cấp; tước đoạt"}],"examples":[{"en":"She denied eating the last piece of cake.","vi":"Cô ấy chối đã ăn miếng bánh cuối cùng.","audioKind":"ex"},{"en":"No child should be denied access to education because their family cannot afford school fees.","vi":"Không đứa trẻ nào nên bị tước quyền tiếp cận giáo dục chỉ vì gia đình không đủ khả năng đóng học phí.","audioKind":"ex2"}],"collocations":[{"en":"deny doing something","vi":"phủ nhận việc làm gì đó"},{"en":"deny an allegation","vi":"bác bỏ cáo buộc"},{"en":"deny access to","vi":"từ chối quyền tiếp cận"}],"wordFamily":["denial (n.)","deniable (adj.)","undeniable (adj.)"],"synonyms":[],"antonyms":["admit"],"tipVi":"Cấu trúc phủ nhận làm gì dùng ''deny doing'', không dùng ''deny to do''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bond', 'en-b2-9', 'bond', '/bɑːnd/', 'B2', 'mối liên kết; sự gắn bó; tình cảm; trái phiếu; gắn kết; tạo quan hệ thân thiết; kết dính', 'n.', 'bonding (n.), bonded (adj.)', NULL, 'Cụm ''bond with sb'' chỉ việc thắt chặt tình cảm; ''issue bonds'' có nghĩa là phát hành trái phiếu.', 'Caring for the puppy strengthened the bond between the sisters.', NULL, 'Việc chăm sóc chú cún đã làm thắt chặt thêm tình cảm giữa hai chị em.', '{"wordId":"bond","ukIpa":"/bɒnd/","usIpa":"/bɑːnd/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"a close connection between people or groups","vi":"mối liên kết; sự gắn bó; tình cảm"},{"pos":"n.","en":"an investment representing a loan with promised repayment and interest","vi":"trái phiếu"},{"pos":"v.","en":"to develop a close relationship or join things firmly together","vi":"gắn kết; tạo quan hệ thân thiết; kết dính"}],"examples":[{"en":"Caring for the puppy strengthened the bond between the sisters.","vi":"Việc chăm sóc chú cún đã làm thắt chặt thêm tình cảm giữa hai chị em.","audioKind":"ex"},{"en":"Governments often issue bonds to finance major infrastructure projects without immediately increasing taxes on households.","vi":"Chính phủ thường phát hành trái phiếu để tài trợ cho các dự án cơ sở hạ tầng lớn mà không làm tăng ngay gánh nặng thuế cho các hộ gia đình.","audioKind":"ex2"}],"collocations":[{"en":"a strong bond","vi":"mối liên kết bền chặt"},{"en":"form a bond","vi":"thiết lập mối quan hệ"},{"en":"government bonds","vi":"trái phiếu chính phủ"},{"en":"bond with","vi":"gắn bó với"}],"wordFamily":["bonding (n.)","bonded (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm ''bond with sb'' chỉ việc thắt chặt tình cảm; ''issue bonds'' có nghĩa là phát hành trái phiếu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disgrace', 'en-b2-9', 'disgrace', '/dɪsˈɡreɪs/', 'B2', 'sự mất thể diện; sự ô nhục; người hoặc vật gây xấu hổ; làm nhục; làm mất mặt', 'n.', 'disgraceful (adj.), disgracefully (adv.), disgraced (adj.)', 'Đồng nghĩa: dishonour, shame · Trái nghĩa: honour', 'Khi chỉ sự ô nhục, từ này không đếm được; a disgrace chỉ người hoặc việc gây xấu hổ.', 'The captain left in disgrace after cheating during the match.', NULL, 'Đội trưởng đã rời đi trong sự hổ thẹn sau khi gian lận trong trận đấu.', '{"wordId":"disgrace","ukIpa":"/dɪsˈɡreɪs/","usIpa":"/dɪsˈɡreɪs/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"loss of respect caused by unacceptable behaviour","vi":"sự mất thể diện; sự ô nhục"},{"pos":"n.","en":"a person or thing deserving strong disapproval","vi":"người hoặc vật gây xấu hổ"},{"pos":"v.","en":"to cause someone or something to lose respect","vi":"làm nhục; làm mất mặt"}],"examples":[{"en":"The captain left in disgrace after cheating during the match.","vi":"Đội trưởng đã rời đi trong sự hổ thẹn sau khi gian lận trong trận đấu.","audioKind":"ex"},{"en":"Officials who misuse public funds bring disgrace on their institutions and weaken public trust in government.","vi":"Các quan chức lạm dụng công quỹ làm hoen ố uy tín của cơ quan họ và làm suy yếu niềm tin của công chúng vào chính phủ.","audioKind":"ex2"}],"collocations":[{"en":"in disgrace","vi":"trong sự hổ thẹn"},{"en":"bring disgrace on","vi":"làm ô nhục..."},{"en":"a disgrace to","vi":"điều đáng hổ thẹn cho..."},{"en":"disgrace yourself","vi":"làm mất mặt bản thân"}],"wordFamily":["disgraceful (adj.)","disgracefully (adv.)","disgraced (adj.)"],"synonyms":["dishonour","shame"],"antonyms":["honour"],"tipVi":"Khi chỉ sự ô nhục, từ này không đếm được; a disgrace chỉ người hoặc việc gây xấu hổ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recognition', 'en-b2-9', 'recognition', '/ˌrekəɡˈnɪʃən/', 'B2', 'sự nhận ra; sự nhận diện; sự công nhận; sự đánh giá cao từ công chúng; sự thừa nhận; sự công nhận chính thức', 'n.', 'recognise (v.), recognisable (adj.), recognised (adj.)', NULL, 'Thường là danh từ không đếm được; cụm in recognition of thường dùng để ghi nhận đóng góp.', 'His face lit up with recognition when I waved.', NULL, 'Khuôn mặt anh ấy bừng sáng sự nhận ra khi tôi vẫy tay chào.', '{"wordId":"recognition","ukIpa":"/ˌrekəɡˈnɪʃən/","usIpa":"/ˌrekəɡˈnɪʃən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"The act of identifying someone or something encountered before.","vi":"sự nhận ra; sự nhận diện"},{"pos":"n.","en":"Public appreciation of someone''s achievements or value.","vi":"sự công nhận; sự đánh giá cao từ công chúng"},{"pos":"n.","en":"Acceptance that something exists, is true, or has official status.","vi":"sự thừa nhận; sự công nhận chính thức"}],"examples":[{"en":"His face lit up with recognition when I waved.","vi":"Khuôn mặt anh ấy bừng sáng sự nhận ra khi tôi vẫy tay chào.","audioKind":"ex"},{"en":"Greater recognition of unpaid care work could lead to fairer social policies and stronger support for families.","vi":"Việc công nhận xứng đáng hơn đối với công việc chăm sóc không công có thể dẫn đến các chính sách xã hội công bằng hơn và mang lại sự hỗ trợ vững chắc hơn cho các gia đình.","audioKind":"ex2"}],"collocations":[{"en":"facial recognition","vi":"nhận diện khuôn mặt"},{"en":"gain recognition","vi":"đạt được sự công nhận"},{"en":"in recognition of","vi":"để ghi nhận; để bày tỏ sự tri ân"},{"en":"official recognition","vi":"sự công nhận chính thức"}],"wordFamily":["recognise (v.)","recognisable (adj.)","recognised (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; cụm in recognition of thường dùng để ghi nhận đóng góp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_confront', 'en-b2-9', 'confront', '/kənˈfrʌnt/', 'B2', 'đối mặt; giải quyết; đối chất; chất vấn', 'v.', 'confrontation (n.), confrontational (adj.)', 'Đồng nghĩa: face · Trái nghĩa: avoid', 'đi thẳng với danh từ chỉ vấn đề; be confronted with diễn tả việc phải đối mặt với khó khăn.', 'She finally confronted her fear and entered the swimming pool.', NULL, 'Cô ấy cuối cùng đã đối mặt với nỗi sợ hãi của mình và bước xuống hồ bơi.', '{"wordId":"confront","ukIpa":"/kənˈfrʌnt/","usIpa":"/kənˈfrʌnt/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"To face and deal with a difficult situation or problem.","vi":"đối mặt; giải quyết"},{"pos":"v.","en":"To challenge someone directly about something they have done.","vi":"đối chất; chất vấn"}],"examples":[{"en":"She finally confronted her fear and entered the swimming pool.","vi":"Cô ấy cuối cùng đã đối mặt với nỗi sợ hãi của mình và bước xuống hồ bơi.","audioKind":"ex"},{"en":"Cities must confront the challenges of an ageing population by improving housing, healthcare, and public transport.","vi":"Các thành phố phải đối mặt với những thách thức của tình trạng già hóa dân số bằng cách cải thiện nhà ở, y tế và giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"confront a problem","vi":"đối mặt với một vấn đề"},{"en":"be confronted with","vi":"phải đối mặt với"},{"en":"confront someone about something","vi":"chất vấn ai đó về việc gì"}],"wordFamily":["confrontation (n.)","confrontational (adj.)"],"synonyms":["face"],"antonyms":["avoid"],"tipVi":"đi thẳng với danh từ chỉ vấn đề; be confronted with diễn tả việc phải đối mặt với khó khăn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_offence', 'en-b2-9', 'offence', '/əˈfens/', 'B2', 'tội phạm; hành vi phạm pháp; sự xúc phạm; sự mất lòng', 'n.', 'offend (v.), offender (n.), offensive (adj.)', 'Đồng nghĩa: violation, transgression', 'Lối viết tiếng Anh-Anh là offence, tiếng Anh-Mỹ là offense; take offence thể hiện thái độ tức giận.', 'Parking here is an offence, so let''s move the car.', NULL, 'Đỗ xe ở đây là vi phạm luật, vì vậy chúng ta hãy di chuyển xe đi.', '{"wordId":"offence","ukIpa":"/əˈfens/","usIpa":"/əˈfens/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"An act that breaks a law or rule.","vi":"tội phạm; hành vi phạm pháp"},{"pos":"n.","en":"Hurt or anger caused by something rude or disrespectful.","vi":"sự xúc phạm; sự mất lòng"}],"examples":[{"en":"Parking here is an offence, so let''s move the car.","vi":"Đỗ xe ở đây là vi phạm luật, vì vậy chúng ta hãy di chuyển xe đi.","audioKind":"ex"},{"en":"Community service may be more effective than imprisonment for people who commit a minor offence.","vi":"Dịch vụ cộng đồng có thể hiệu quả hơn việc giam giữ đối với những người phạm tội nhẹ.","audioKind":"ex2"}],"collocations":[{"en":"commit an offence","vi":"phạm tội; vi pháp"},{"en":"a criminal offence","vi":"tội hình sự"},{"en":"take offence","vi":"cảm thấy bị xúc phạm"},{"en":"cause offence","vi":"gây ra sự khó chịu"}],"wordFamily":["offend (v.)","offender (n.)","offensive (adj.)"],"synonyms":["violation","transgression"],"antonyms":[],"tipVi":"Lối viết tiếng Anh-Anh là offence, tiếng Anh-Mỹ là offense; take offence thể hiện thái độ tức giận.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fund-raising', 'en-b2-9', 'fund-raising', '/ˈfʌndˌreɪzɪŋ/', 'B2', 'hoạt động gây quỹ; quyên góp', 'n.', 'fundraiser (n.), fund (n.), fund (v.)', NULL, 'Cũng thường được viết là fundraising; raise funds có nghĩa là gây quỹ.', 'Our fund-raising dinner helped buy books for the library.', NULL, 'Bữa tối gây quỹ của chúng tôi đã giúp mua sách cho thư viện.', '{"wordId":"fund-raising","ukIpa":"/ˈfʌndˌreɪzɪŋ/","usIpa":"/ˈfʌndˌreɪzɪŋ/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"The activity of collecting money for an organization or cause.","vi":"hoạt động gây quỹ; quyên góp"}],"examples":[{"en":"Our fund-raising dinner helped buy books for the library.","vi":"Bữa tối gây quỹ của chúng tôi đã giúp mua sách cho thư viện.","audioKind":"ex"},{"en":"Community fund-raising can support local services, but essential healthcare should not depend entirely on charitable donations.","vi":"Việc gây quỹ cộng đồng có thể hỗ trợ các dịch vụ địa phương, nhưng y tế thiết yếu không nên hoàn toàn phụ thuộc vào các khoản đóng góp từ thiện.","audioKind":"ex2"}],"collocations":[{"en":"fund-raising event","vi":"sự kiện gây quỹ"},{"en":"fund-raising campaign","vi":"chiến dịch gây quỹ"},{"en":"fund-raising target","vi":"mục tiêu gây quỹ"}],"wordFamily":["fundraiser (n.)","fund (n.)","fund (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Cũng thường được viết là fundraising; raise funds có nghĩa là gây quỹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_harsh', 'en-b2-9', 'harsh', '/hɑːrʃ/', 'B2', 'nghiêm khắc; cay nghiệt; khắc nghiệt; khắc khổ; chói; gắt; cay (mùi, vị)', 'adj.', 'harshly (adv.), harshness (n.)', 'Đồng nghĩa: severe, stern · Trái nghĩa: gentle, mild', 'Nhấn mạnh mức độ nghiêm khắc đến mức khó chịu hoặc khó lòng chịu đựng hơn từ strict.', 'His harsh criticism upset everyone at the dinner table.', NULL, 'Những lời chỉ trích cay nghiệt của anh ấy đã làm mọi người khó chịu tại bàn ăn.', '{"wordId":"harsh","ukIpa":"/hɑːʃ/","usIpa":"/hɑːrʃ/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"unkind or excessively severe in judging or treating others","vi":"nghiêm khắc; cay nghiệt"},{"pos":"adj.","en":"very difficult or unpleasant to live in or experience","vi":"khắc nghiệt; khắc khổ"},{"pos":"adj.","en":"unpleasantly strong and uncomfortable to the senses","vi":"chói; gắt; cay (mùi, vị)"}],"examples":[{"en":"His harsh criticism upset everyone at the dinner table.","vi":"Những lời chỉ trích cay nghiệt của anh ấy đã làm mọi người khó chịu tại bàn ăn.","audioKind":"ex"},{"en":"Farmers in regions with harsh climates need reliable irrigation systems to maintain stable food production.","vi":"Nông dân ở những vùng có khí hậu khắc nghiệt cần hệ thống tưới tiêu đáng tin cậy để duy trì năng suất lương thực ổn định.","audioKind":"ex2"}],"collocations":[{"en":"harsh criticism","vi":"lời chỉ trích cay nghiệt"},{"en":"harsh conditions","vi":"điều kiện khắc nghiệt"},{"en":"harsh punishment","vi":"hình phạt nghiêm khắc"},{"en":"harsh light","vi":"ánh sáng chói"}],"wordFamily":["harshly (adv.)","harshness (n.)"],"synonyms":["severe","stern"],"antonyms":["gentle","mild"],"tipVi":"Nhấn mạnh mức độ nghiêm khắc đến mức khó chịu hoặc khó lòng chịu đựng hơn từ strict.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reputation', 'en-b2-9', 'reputation', '/ˌrepjəˈteɪʃən/', 'B2', 'danh tiếng, uy tín, tiếng tăm', 'n.', 'reputable (adj.), reputed (adj.)', 'Đồng nghĩa: standing', 'Dùng reputation for để chỉ đặc điểm; danh tiếng có thể tốt hoặc xấu.', 'This little bakery has a reputation for excellent bread.', NULL, 'Tiệm bánh nhỏ này nổi tiếng với những chiếc bánh mì tuyệt hảo.', '{"wordId":"reputation","ukIpa":"/ˌrepjuˈteɪʃən/","usIpa":"/ˌrepjəˈteɪʃən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"The general opinion people have about someone or something.","vi":"danh tiếng, uy tín, tiếng tăm"}],"examples":[{"en":"This little bakery has a reputation for excellent bread.","vi":"Tiệm bánh nhỏ này nổi tiếng với những chiếc bánh mì tuyệt hảo.","audioKind":"ex"},{"en":"Companies that respond honestly to customer complaints are more likely to maintain a good reputation.","vi":"Các công ty phản hồi thành thật với khiếu nại của khách hàng sẽ có nhiều khả năng duy trì được uy tín tốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"build a reputation","vi":"gây dựng uy tín"},{"en":"damage someone''s reputation","vi":"làm tổn hại danh tiếng của ai đó"},{"en":"a reputation for quality","vi":"uy tín về chất lượng"}],"wordFamily":["reputable (adj.)","reputed (adj.)"],"synonyms":["standing"],"antonyms":[],"tipVi":"Dùng reputation for để chỉ đặc điểm; danh tiếng có thể tốt hoặc xấu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_debate', 'en-b2-9', 'debate', '/dɪˈbeɪt/', 'B2', 'cuộc tranh luận; cuộc thảo luận; tranh luận; bàn luận; cân nhắc; suy tính', 'n.', 'debatable (adj.), debater (n.)', 'Đồng nghĩa: discussion, deliberation', 'Động từ có thể trực tiếp đi với vấn đề; debate whether to diễn tả sự cân nhắc.', 'We had a lively debate about keeping pets indoors.', NULL, 'Chúng tôi đã có một cuộc tranh luận sôi nổi về việc nuôi thú cưng trong nhà.', '{"wordId":"debate","ukIpa":"/dɪˈbeɪt/","usIpa":"/dɪˈbeɪt/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"A discussion in which people express different views.","vi":"cuộc tranh luận; cuộc thảo luận"},{"pos":"v.","en":"To discuss a subject by considering different views.","vi":"tranh luận; bàn luận"},{"pos":"v.","en":"To think carefully about options before making a decision.","vi":"cân nhắc; suy tính"}],"examples":[{"en":"We had a lively debate about keeping pets indoors.","vi":"Chúng tôi đã có một cuộc tranh luận sôi nổi về việc nuôi thú cưng trong nhà.","audioKind":"ex"},{"en":"The debate over free public transport centres on its environmental benefits and the cost to taxpayers.","vi":"Cuộc tranh luận về giao thông công cộng miễn phí tập trung vào lợi ích môi trường và gánh nặng chi phí đối với người nộp thuế.","audioKind":"ex2"}],"collocations":[{"en":"public debate","vi":"thảo luận công khai"},{"en":"heated debate","vi":"tranh luận gay gắt"},{"en":"debate an issue","vi":"thảo luận một vấn đề"},{"en":"debate whether to","vi":"cân nhắc xem có nên"}],"wordFamily":["debatable (adj.)","debater (n.)"],"synonyms":["discussion","deliberation"],"antonyms":[],"tipVi":"Động từ có thể trực tiếp đi với vấn đề; debate whether to diễn tả sự cân nhắc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gay', 'en-b2-9', 'gay', '/ɡeɪ/', 'B2', 'đồng tính (nam); liên quan đến người đồng tính', 'adj.', NULL, 'Đồng nghĩa: homosexual · Trái nghĩa: heterosexual', 'Thường dùng làm tính từ; nghĩa "vui vẻ" nay đã ít được sử dụng.', 'My uncle is gay and lives with his husband.', NULL, 'Chú của tôi là người đồng tính và đang sống cùng chồng của chú ấy.', '{"wordId":"gay","ukIpa":"/ɡeɪ/","usIpa":"/ɡeɪ/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Romantically or sexually attracted to people of the same sex.","vi":"đồng tính (nam)"},{"pos":"adj.","en":"Relating to gay people, their lives, or their culture.","vi":"liên quan đến người đồng tính"}],"examples":[{"en":"My uncle is gay and lives with his husband.","vi":"Chú của tôi là người đồng tính và đang sống cùng chồng của chú ấy.","audioKind":"ex"},{"en":"Schools can promote inclusion by ensuring that gay students receive the same respect and support as their peers.","vi":"Các trường học có thể thúc đẩy sự hòa nhập bằng cách đảm bảo học sinh đồng tính nhận được sự tôn trọng và hỗ trợ ngang bằng với các bạn đồng trang lứa.","audioKind":"ex2"}],"collocations":[{"en":"gay couple","vi":"cặp đôi đồng tính"},{"en":"gay rights","vi":"quyền của người đồng tính"},{"en":"openly gay","vi":"công khai thừa nhận là người đồng tính"}],"wordFamily":[],"synonyms":["homosexual"],"antonyms":["heterosexual"],"tipVi":"Thường dùng làm tính từ; nghĩa \"vui vẻ\" nay đã ít được sử dụng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_parade', 'en-b2-9', 'parade', '/pəˈreɪd/', 'B2', 'cuộc diễu hành; đoàn diễu hành; diễu hành; tuần hành; khoe khoang; phô trương', 'n.', NULL, 'Đồng nghĩa: procession, march', 'parade nhấn mạnh vào việc diễu hành trưng bày, trình diễn; trong khi đó cuộc diễu hành phản đối thường dùng march.', 'Children waved flags as the parade passed our balcony.', NULL, 'Lũ trẻ vẫy cờ khi đoàn diễu hành đi qua ban công nhà chúng tôi.', '{"wordId":"parade","ukIpa":"/pəˈreɪd/","usIpa":"/pəˈreɪd/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"An organised procession of people or vehicles watched by spectators.","vi":"cuộc diễu hành; đoàn diễu hành"},{"pos":"v.","en":"To walk together in an organised public procession.","vi":"diễu hành; tuần hành"},{"pos":"v.","en":"To show something publicly, often to attract admiration.","vi":"khoe khoang; phô trương"}],"examples":[{"en":"Children waved flags as the parade passed our balcony.","vi":"Lũ trẻ vẫy cờ khi đoàn diễu hành đi qua ban công nhà chúng tôi.","audioKind":"ex"},{"en":"A cultural parade allows communities to celebrate their traditions and share them with people from different backgrounds.","vi":"Một cuộc diễu hành văn hóa tạo cơ hội cho các cộng đồng tôn vinh truyền thống của mình và chia sẻ chúng với những người có hoàn cảnh khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"a street parade","vi":"cuộc diễu hành trên đường phố"},{"en":"a carnival parade","vi":"đoàn diễu hành lễ hội"},{"en":"parade through the streets","vi":"diễu hành qua các con phố"}],"wordFamily":[],"synonyms":["procession","march"],"antonyms":[],"tipVi":"parade nhấn mạnh vào việc diễu hành trưng bày, trình diễn; trong khi đó cuộc diễu hành phản đối thường dùng march.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_escort', 'en-b2-9', 'escort', '/ɪˈskɔːrt/', 'B2', 'hộ tống; đi kèm; người hộ tống; đội bảo vệ', 'v.', NULL, 'Đồng nghĩa: accompany', 'Trọng âm của động từ nằm ở âm tiết cuối; trong khi danh từ có phát âm tiếng Anh /ˈeskɔːt/ và tiếng Anh-Mỹ /ˈeskɔːrt/.', 'A staff member escorted us to the waiting room.', NULL, 'Một nhân viên đã hộ tống chúng tôi đến phòng chờ.', '{"wordId":"escort","ukIpa":"/ɪˈskɔːt/","usIpa":"/ɪˈskɔːrt/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"To accompany someone to guide or protect them","vi":"hộ tống; đi kèm"},{"pos":"n.","en":"A person or group accompanying someone for protection or guidance","vi":"người hộ tống; đội bảo vệ"}],"examples":[{"en":"A staff member escorted us to the waiting room.","vi":"Một nhân viên đã hộ tống chúng tôi đến phòng chờ.","audioKind":"ex"},{"en":"Trained volunteers can escort elderly residents to medical appointments, improving access to essential healthcare services.","vi":"Các tình nguyện viên được đào tạo có thể hộ tống cư dân cao tuổi đi khám bệnh, qua đó giúp họ tiếp cận tốt hơn với các dịch vụ chăm sóc sức khỏe thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"escort someone to","vi":"hộ tống ai đến"},{"en":"a police escort","vi":"đội cảnh sát hộ tống"},{"en":"under escort","vi":"được hộ tống"}],"wordFamily":[],"synonyms":["accompany"],"antonyms":[],"tipVi":"Trọng âm của động từ nằm ở âm tiết cuối; trong khi danh từ có phát âm tiếng Anh /ˈeskɔːt/ và tiếng Anh-Mỹ /ˈeskɔːrt/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_identification', 'en-b2-9', 'identification', '/aɪˌdentɪfɪˈkeɪʃən/', 'B2', 'sự nhận diện; sự xác định; giấy tờ tùy thân; chứng minh thư; sự đồng cảm; sự thấu cảm', 'n.', 'identify (v.), identifiable (adj.), identity (n.)', NULL, 'Khi dùng với nghĩa giấy tờ tùy thân, từ này thường không đếm được và có thể viết tắt là ID.', 'The receptionist asked me to show some identification.', NULL, 'Nhân viên lễ tân yêu cầu tôi xuất trình giấy tờ tùy thân.', '{"wordId":"identification","ukIpa":"/aɪˌdentɪfɪˈkeɪʃən/","usIpa":"/aɪˌdentɪfɪˈkeɪʃən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"the process of establishing who or what someone or something is","vi":"sự nhận diện; sự xác định"},{"pos":"n.","en":"a document that proves who you are","vi":"giấy tờ tùy thân; chứng minh thư"},{"pos":"n.","en":"a feeling of connection with another person or group","vi":"sự đồng cảm; sự thấu cảm"}],"examples":[{"en":"The receptionist asked me to show some identification.","vi":"Nhân viên lễ tân yêu cầu tôi xuất trình giấy tờ tùy thân.","audioKind":"ex"},{"en":"Early identification of learning difficulties allows schools to provide appropriate support before students fall behind.","vi":"Việc phát hiện sớm các khó khăn trong học tập giúp nhà trường cung cấp sự hỗ trợ phù hợp trước khi học sinh bị tụt lại phía sau.","audioKind":"ex2"}],"collocations":[{"en":"proof of identification","vi":"bằng chứng nhận dạng"},{"en":"species identification","vi":"định danh loài"},{"en":"early identification","vi":"nhận diện sớm"},{"en":"identification with","vi":"sự đồng cảm với"}],"wordFamily":["identify (v.)","identifiable (adj.)","identity (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi dùng với nghĩa giấy tờ tùy thân, từ này thường không đếm được và có thể viết tắt là ID.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_peer', 'en-b2-9', 'peer', '/pɪr/', 'B2', 'bạn cùng lứa; người cùng cấp bậc hoặc năng lực; nhìn chăm chú; cố gắng nhìn cho rõ; quý tộc Anh', 'n.', 'peerage (n.), peerless (adj.)', 'Đồng nghĩa: equal', 'Danh từ thường ở dạng số nhiều peers; động từ thường đi với through, at hoặc into.', 'She peered through the window to see the kitten.', NULL, 'Cô ấy dán mắt nhìn qua khung cửa sổ để ngắm chú mèo con.', '{"wordId":"peer","ukIpa":"/pɪə/","usIpa":"/pɪr/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"Someone of similar age, status, or ability","vi":"bạn cùng lứa; người cùng cấp bậc hoặc năng lực"},{"pos":"v.","en":"To look carefully, especially when something is difficult to see","vi":"nhìn chăm chú; cố gắng nhìn cho rõ"},{"pos":"n.","en":"A person holding a British noble title","vi":"quý tộc Anh"}],"examples":[{"en":"She peered through the window to see the kitten.","vi":"Cô ấy dán mắt nhìn qua khung cửa sổ để ngắm chú mèo con.","audioKind":"ex"},{"en":"Students often gain confidence when they receive constructive feedback from their peers during collaborative classroom activities.","vi":"Học sinh thường trở nên tự tin hơn khi nhận được những lời góp ý mang tính xây dựng từ bạn bè trong các hoạt động hợp tác tại lớp.","audioKind":"ex2"}],"collocations":[{"en":"peer pressure","vi":"áp lực từ bạn bè cùng trang lứa"},{"en":"peer review","vi":"sự thẩm định của đồng nghiệp"},{"en":"peer group","vi":"nhóm bạn cùng lứa"},{"en":"peer through","vi":"nhìn chăm chú qua..."}],"wordFamily":["peerage (n.)","peerless (adj.)"],"synonyms":["equal"],"antonyms":[],"tipVi":"Danh từ thường ở dạng số nhiều peers; động từ thường đi với through, at hoặc into.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_folk', 'en-b2-9', 'folk', '/foʊk/', 'B2', 'mọi người; người (thường chỉ một nhóm cụ thể); mang tính truyền thống của dân gian; nhạc dân gian; dân ca', 'n.', 'folklore (n.)', 'Đồng nghĩa: people', 'Khi chỉ mọi người thì dùng động từ số nhiều; my folks trong văn nói dùng để chỉ cha mẹ.', 'Local folk gather here to chat every evening.', NULL, 'Người dân địa phương tụ tập ở đây để trò chuyện mỗi tối.', '{"wordId":"folk","ukIpa":"/fəʊk/","usIpa":"/foʊk/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"People, especially those belonging to a particular group.","vi":"mọi người; người (thường chỉ một nhóm cụ thể)"},{"pos":"adj.","en":"Connected with the traditional culture of ordinary people.","vi":"mang tính truyền thống của dân gian"},{"pos":"n.","en":"Music rooted in the traditions of a community.","vi":"nhạc dân gian; dân ca"}],"examples":[{"en":"Local folk gather here to chat every evening.","vi":"Người dân địa phương tụ tập ở đây để trò chuyện mỗi tối.","audioKind":"ex"},{"en":"Traditional folk music can help younger generations understand the cultural heritage of their communities.","vi":"Nhạc dân gian truyền thống có thể giúp thế hệ trẻ thấu hiểu di sản văn hóa của cộng đồng mình.","audioKind":"ex2"}],"collocations":[{"en":"local folk","vi":"người dân địa phương"},{"en":"folk music","vi":"nhạc dân gian"},{"en":"folk tale","vi":"truyện dân gian"},{"en":"folk dance","vi":"múa dân gian"}],"wordFamily":["folklore (n.)"],"synonyms":["people"],"antonyms":[],"tipVi":"Khi chỉ mọi người thì dùng động từ số nhiều; my folks trong văn nói dùng để chỉ cha mẹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_boundary', 'en-b2-9', 'boundary', '/ˈbaʊndəri/', 'B2', 'ranh giới; đường biên giới; giới hạn; hạn mức', 'n.', NULL, 'Đồng nghĩa: border, limit', 'boundary nhấn mạnh vạch phân chia; border thường dùng cho ranh giới quốc gia hoặc vùng lãnh thổ.', 'A low stone wall marks the boundary of our garden.', NULL, 'Một bức tường đá thấp đánh dấu ranh giới khu vườn của chúng tôi.', '{"wordId":"boundary","ukIpa":"/ˈbaʊndəri/","usIpa":"/ˈbaʊndəri/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"A line marking where one area ends and another begins","vi":"ranh giới; đường biên giới"},{"pos":"n.","en":"A limit defining acceptable behaviour or the scope of something","vi":"giới hạn; hạn mức"}],"examples":[{"en":"A low stone wall marks the boundary of our garden.","vi":"Một bức tường đá thấp đánh dấu ranh giới khu vườn của chúng tôi.","audioKind":"ex"},{"en":"Clear boundaries between work and personal life can protect employees'' mental health and reduce long-term stress.","vi":"Ranh giới rõ ràng giữa công việc và đời sống cá nhân có thể bảo vệ sức khỏe tâm thần của nhân viên và giảm bớt căng thẳng lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"a national boundary","vi":"đường biên giới quốc gia"},{"en":"set boundaries","vi":"thiết lập ranh giới"},{"en":"cross a boundary","vi":"vượt quá ranh giới"},{"en":"push the boundaries","vi":"vượt qua các giới hạn"}],"wordFamily":[],"synonyms":["border","limit"],"antonyms":[],"tipVi":"boundary nhấn mạnh vạch phân chia; border thường dùng cho ranh giới quốc gia hoặc vùng lãnh thổ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_immigration', 'en-b2-9', 'immigration', '/ˌɪmɪˈɡreɪʃən/', 'B2', 'sự nhập cư; việc di cư vào nước khác; khu vực kiểm tra nhập cảnh; thủ tục nhập cảnh', 'n.', 'immigrate (v.), immigrant (n.), migration (n.), emigration (n.)', 'Trái nghĩa: emigration', 'Immigration nhấn mạnh việc di chuyển vào trong; emigration nhấn mạnh việc rời đi.', 'We showed our passports at immigration after the flight.', NULL, 'Chúng tôi xuất trình hộ chiếu ở quầy kiểm tra nhập cảnh sau chuyến bay.', '{"wordId":"immigration","ukIpa":"/ˌɪmɪˈɡreɪʃən/","usIpa":"/ˌɪmɪˈɡreɪʃən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"The process of entering another country to live there.","vi":"sự nhập cư; việc di cư vào nước khác"},{"pos":"n.","en":"The official checks or checkpoint for people entering a country.","vi":"khu vực kiểm tra nhập cảnh; thủ tục nhập cảnh"}],"examples":[{"en":"We showed our passports at immigration after the flight.","vi":"Chúng tôi xuất trình hộ chiếu ở quầy kiểm tra nhập cảnh sau chuyến bay.","audioKind":"ex"},{"en":"Immigration can help address labour shortages, particularly when newcomers receive language training and employment support.","vi":"Nhập cư có thể giúp giải quyết tình trạng thiếu hụt lao động, đặc biệt khi người mới đến nhận được đào tạo ngôn ngữ và hỗ trợ việc làm.","audioKind":"ex2"}],"collocations":[{"en":"immigration policy","vi":"chính sách nhập cư"},{"en":"immigration control","vi":"kiểm soát nhập cư"},{"en":"immigration officer","vi":"cán bộ quản lý xuất nhập cảnh"},{"en":"go through immigration","vi":"làm thủ tục nhập cảnh"}],"wordFamily":["immigrate (v.)","immigrant (n.)","migration (n.)","emigration (n.)"],"synonyms":[],"antonyms":["emigration"],"tipVi":"Immigration nhấn mạnh việc di chuyển vào trong; emigration nhấn mạnh việc rời đi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_violent', 'en-b2-9', 'violent', '/ˈvaɪələnt/', 'B2', 'bạo lực; hung bạo; dữ dội; mãnh liệt; mạnh', 'adj.', 'violence (n.), violently (adv.), nonviolent (adj.)', 'Trái nghĩa: nonviolent, peaceful', 'Có thể dùng để chỉ hành vi bạo lực hoặc mô tả bão tố, sự rung chuyển dữ dội.', 'A violent storm shook the windows throughout the night.', NULL, 'Một trận cuồng phong dữ dội đã làm rung chuyển các khung cửa sổ suốt cả đêm.', '{"wordId":"violent","ukIpa":"/ˈvaɪələnt/","usIpa":"/ˈvaɪələnt/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Using physical force to hurt people or damage things.","vi":"bạo lực; hung bạo"},{"pos":"adj.","en":"Extremely strong, sudden, or forceful.","vi":"dữ dội; mãnh liệt; mạnh"}],"examples":[{"en":"A violent storm shook the windows throughout the night.","vi":"Một trận cuồng phong dữ dội đã làm rung chuyển các khung cửa sổ suốt cả đêm.","audioKind":"ex"},{"en":"Reducing children''s exposure to violent content is a common concern among parents and educators.","vi":"Giảm bớt việc trẻ em tiếp cận với nội dung bạo lực là mối quan tâm chung của các bậc phụ huynh và nhà giáo dục.","audioKind":"ex2"}],"collocations":[{"en":"violent behaviour","vi":"hành vi bạo lực"},{"en":"violent crime","vi":"tội phạm bạo lực"},{"en":"a violent storm","vi":"một trận bão dữ dội"}],"wordFamily":["violence (n.)","violently (adv.)","nonviolent (adj.)"],"synonyms":[],"antonyms":["nonviolent","peaceful"],"tipVi":"Có thể dùng để chỉ hành vi bạo lực hoặc mô tả bão tố, sự rung chuyển dữ dội.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_emigrate', 'en-b2-9', 'emigrate', '/ˈem.ə.ɡreɪt/', 'B2', 'di cư; xuất ngoại', 'v.', 'emigration (n.), emigrant (n.)', 'Trái nghĩa: immigrate', 'emigrate nhấn mạnh việc rời đi, immigrate nhấn mạnh việc đến nơi mới; đi với giới từ from hoặc to.', 'Her grandparents emigrated to Canada when they were young.', NULL, 'Ông bà của cô ấy đã di cư sang Canada khi họ còn trẻ.', '{"wordId":"emigrate","ukIpa":"/ˈem.ɪ.ɡreɪt/","usIpa":"/ˈem.ə.ɡreɪt/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"To leave your country to live permanently in another","vi":"di cư; xuất ngoại"}],"examples":[{"en":"Her grandparents emigrated to Canada when they were young.","vi":"Ông bà của cô ấy đã di cư sang Canada khi họ còn trẻ.","audioKind":"ex"},{"en":"Skilled workers may emigrate when their home countries offer limited opportunities for professional development.","vi":"Lao động tay nghề cao có thể di cư sang nước khác khi quê hương của họ mang lại ít cơ hội phát triển nghề nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"emigrate from","vi":"di cư từ"},{"en":"emigrate to","vi":"di cư đến"},{"en":"emigrate permanently","vi":"định cư vĩnh viễn ở nước ngoài"}],"wordFamily":["emigration (n.)","emigrant (n.)"],"synonyms":[],"antonyms":["immigrate"],"tipVi":"emigrate nhấn mạnh việc rời đi, immigrate nhấn mạnh việc đến nơi mới; đi với giới từ from hoặc to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_integrate', 'en-b2-9', 'integrate', '/ˈɪntɪɡreɪt/', 'B2', 'tích hợp; kết hợp; hòa nhập; làm cho hòa nhập', 'v.', 'integration (n.), integrated (adj.)', 'Đồng nghĩa: combine, incorporate · Trái nghĩa: separate, segregate', 'Thường dùng cấu trúc integrate A into B, hoặc integrate A with B.', 'This app integrates my calendar with my shopping list.', NULL, 'Ứng dụng này tích hợp lịch làm việc của tôi với danh sách mua sắm.', '{"wordId":"integrate","ukIpa":"/ˈɪntɪɡreɪt/","usIpa":"/ˈɪntɪɡreɪt/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"To combine separate parts so they work together effectively.","vi":"tích hợp; kết hợp"},{"pos":"v.","en":"To join, or help someone join, a group or society.","vi":"hòa nhập; làm cho hòa nhập"}],"examples":[{"en":"This app integrates my calendar with my shopping list.","vi":"Ứng dụng này tích hợp lịch làm việc của tôi với danh sách mua sắm.","audioKind":"ex"},{"en":"Schools should integrate digital tools into classroom activities while ensuring that all students have equal access.","vi":"Nhà trường nên tích hợp các công cụ kỹ thuật số vào các hoạt động trên lớp đồng thời đảm bảo rằng tất cả học sinh đều có quyền tiếp cận bình đẳng.","audioKind":"ex2"}],"collocations":[{"en":"integrate A into B","vi":"tích hợp A vào B"},{"en":"integrate with","vi":"kết hợp với"},{"en":"integrate into society","vi":"hòa nhập vào xã hội"}],"wordFamily":["integration (n.)","integrated (adj.)"],"synonyms":["combine","incorporate"],"antonyms":["separate","segregate"],"tipVi":"Thường dùng cấu trúc integrate A into B, hoặc integrate A with B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exclusive', 'en-b2-9', 'exclusive', '/ɪkˈskluːsɪv/', 'B2', 'dành riêng; độc quyền; cao cấp; sang trọng; dành cho giới thượng lưu; bản tin độc quyền', 'adj.', 'exclude (v.), exclusion (n.), exclusively (adv.), exclusivity (n.)', 'Đồng nghĩa: restricted · Trái nghĩa: inclusive', 'exclusive to có nghĩa là "dành riêng cho..."; exclusive of có nghĩa là không bao gồm.', 'Guests have exclusive use of the pool this afternoon.', NULL, 'Chiều nay khách lưu trú có quyền sử dụng hồ bơi độc quyền.', '{"wordId":"exclusive","ukIpa":"/ɪkˈskluːsɪv/","usIpa":"/ɪkˈskluːsɪv/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Available only to a particular person or group.","vi":"dành riêng; độc quyền"},{"pos":"adj.","en":"Expensive and available mainly to wealthy or privileged people.","vi":"cao cấp; sang trọng; dành cho giới thượng lưu"},{"pos":"n.","en":"A news story published by only one media organisation.","vi":"bản tin độc quyền"}],"examples":[{"en":"Guests have exclusive use of the pool this afternoon.","vi":"Chiều nay khách lưu trú có quyền sử dụng hồ bơi độc quyền.","audioKind":"ex"},{"en":"Giving one company exclusive rights to public data may restrict competition and discourage innovation.","vi":"Việc trao cho một công ty quyền độc quyền sử dụng dữ liệu công cộng có thể hạn chế sự cạnh tranh và kìm hãm đổi mới sáng tạo.","audioKind":"ex2"}],"collocations":[{"en":"exclusive access","vi":"quyền sử dụng độc quyền"},{"en":"exclusive rights","vi":"quyền độc quyền"},{"en":"exclusive interview","vi":"phỏng vấn độc quyền"},{"en":"mutually exclusive","vi":"loại trừ lẫn nhau"}],"wordFamily":["exclude (v.)","exclusion (n.)","exclusively (adv.)","exclusivity (n.)"],"synonyms":["restricted"],"antonyms":["inclusive"],"tipVi":"exclusive to có nghĩa là \"dành riêng cho...\"; exclusive of có nghĩa là không bao gồm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dignity', 'en-b2-9', 'dignity', '/ˈdɪɡnəti/', 'B2', 'phẩm giá; lòng tự trọng; sự điềm đạm; sự trang nghiêm', 'n.', 'dignified (adj.), dignify (v.), undignified (adj.)', 'Đồng nghĩa: self-respect · Trái nghĩa: indignity', 'Danh từ này thường không đếm được; cụm từ with dignity có thể diễn tả thái độ có phẩm giá, đàng hoàng.', 'The nurse protected his dignity by closing the curtain.', NULL, 'Y tá đã bảo vệ phẩm giá của bệnh nhân bằng cách kéo rèm lại.', '{"wordId":"dignity","ukIpa":"/ˈdɪɡnəti/","usIpa":"/ˈdɪɡnəti/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"A person''s worth and right to be treated with respect.","vi":"phẩm giá; lòng tự trọng"},{"pos":"n.","en":"Calm, controlled behaviour that earns respect.","vi":"sự điềm đạm; sự trang nghiêm"}],"examples":[{"en":"The nurse protected his dignity by closing the curtain.","vi":"Y tá đã bảo vệ phẩm giá của bệnh nhân bằng cách kéo rèm lại.","audioKind":"ex"},{"en":"Care services should preserve the dignity of older people by respecting their privacy and personal choices.","vi":"Các dịch vụ chăm sóc nên duy trì phẩm giá của người cao tuổi bằng cách tôn trọng quyền riêng tư và lựa chọn cá nhân của họ.","audioKind":"ex2"}],"collocations":[{"en":"human dignity","vi":"phẩm giá con người"},{"en":"preserve someone''s dignity","vi":"giữ gìn phẩm giá của ai đó"},{"en":"treat someone with dignity","vi":"đối xử với ai đó một cách có tôn nghiêm"},{"en":"a sense of dignity","vi":"ý thức tự trọng"}],"wordFamily":["dignified (adj.)","dignify (v.)","undignified (adj.)"],"synonyms":["self-respect"],"antonyms":["indignity"],"tipVi":"Danh từ này thường không đếm được; cụm từ with dignity có thể diễn tả thái độ có phẩm giá, đàng hoàng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_9_1', 'en-b2-9', 'Cách dùng “escort” (v.) — hộ tống; đi kèm', 'escort someone to  ·  a police escort  ·  under escort', 'Trọng âm của động từ nằm ở âm tiết cuối; trong khi danh từ có phát âm tiếng Anh /ˈeskɔːt/ và tiếng Anh-Mỹ /ˈeskɔːrt/.', 'Đồng nghĩa: accompany', '[{"hanzi":"A staff member escorted us to the waiting room.","pinyin":"","meaning":"Một nhân viên đã hộ tống chúng tôi đến phòng chờ."},{"hanzi":"Trained volunteers can escort elderly residents to medical appointments, improving access to essential healthcare services.","pinyin":"","meaning":"Các tình nguyện viên được đào tạo có thể hộ tống cư dân cao tuổi đi khám bệnh, qua đó giúp họ tiếp cận tốt hơn với các dịch vụ chăm sóc sức khỏe thiết yếu."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_9_2', 'en-b2-9', 'Cách dùng “parade” (n.) — cuộc diễu hành; đoàn diễu hành', 'a street parade  ·  a carnival parade  ·  parade through the streets', 'parade nhấn mạnh vào việc diễu hành trưng bày, trình diễn; trong khi đó cuộc diễu hành phản đối thường dùng march.', 'Đồng nghĩa: procession, march', '[{"hanzi":"Children waved flags as the parade passed our balcony.","pinyin":"","meaning":"Lũ trẻ vẫy cờ khi đoàn diễu hành đi qua ban công nhà chúng tôi."},{"hanzi":"A cultural parade allows communities to celebrate their traditions and share them with people from different backgrounds.","pinyin":"","meaning":"Một cuộc diễu hành văn hóa tạo cơ hội cho các cộng đồng tôn vinh truyền thống của mình và chia sẻ chúng với những người có hoàn cảnh khác nhau."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_9_3', 'en-b2-9', 'Cách dùng “honour” (n.) — vinh dự; lòng tự trọng; niềm tự hào', 'a great honour  ·  in honour of  ·  honour a commitment', 'Từ ''honour'' viết theo Anh-Anh, ''honor'' viết theo Anh-Mỹ; chữ ''h'' không được phát âm nên dùng mạo từ ''an''.', 'Họ từ (Word Family): honourable (adj.), honoured (adj.), dishonour (n.) | Đồng nghĩa: respect, esteem · Trái nghĩa: dishonour', '[{"hanzi":"It was an honour to represent my local team.","pinyin":"","meaning":"Thật là một vinh dự lớn khi được đại diện cho đội bóng địa phương của tôi."},{"hanzi":"Companies must honour their commitments to workers if they hope to maintain trust and reduce staff turnover.","pinyin":"","meaning":"Các công ty phải thực hiện cam kết của mình với người lao động nếu họ muốn duy trì lòng tin và giảm tỷ lệ nhân viên nghỉ việc."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_9_4', 'en-b2-9', 'Cách dùng “dignity” (n.) — phẩm giá; lòng tự trọng', 'human dignity  ·  preserve someone''s dignity  ·  treat someone with dignity', 'Danh từ này thường không đếm được; cụm từ with dignity có thể diễn tả thái độ có phẩm giá, đàng hoàng.', 'Họ từ (Word Family): dignified (adj.), dignify (v.), undignified (adj.) | Đồng nghĩa: self-respect · Trái nghĩa: indignity', '[{"hanzi":"The nurse protected his dignity by closing the curtain.","pinyin":"","meaning":"Y tá đã bảo vệ phẩm giá của bệnh nhân bằng cách kéo rèm lại."},{"hanzi":"Care services should preserve the dignity of older people by respecting their privacy and personal choices.","pinyin":"","meaning":"Các dịch vụ chăm sóc nên duy trì phẩm giá của người cao tuổi bằng cách tôn trọng quyền riêng tư và lựa chọn cá nhân của họ."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_9_1', 'en-b2-9', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_9_1_1', 'ten_b2_9_1', 'institution', 'My sister works at a respected institution near home.', 'My sister works at a respected institution near home.', '/ˌɪnstɪˈtuːʃən/', 'Chị tôi làm việc tại một cơ quan có uy tín gần nhà.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_9_1_2', 'ten_b2_9_1', 'childish', 'Hiding my shoes was a childish thing to do.', 'Hiding my shoes was a childish thing to do.', '/ˈtʃaɪldɪʃ/', 'Giấu giày của tôi đi là một hành động thật trẻ con.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_9_1_3', 'ten_b2_9_1', 'honour', 'It was an honour to represent my local team.', 'It was an honour to represent my local team.', '/ˈɑːnər/', 'Thật là một vinh dự lớn khi được đại diện cho đội bóng địa phương của tôi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_9_1_4', 'ten_b2_9_1', 'deny', 'She denied eating the last piece of cake.', 'She denied eating the last piece of cake.', '/dɪˈnaɪ/', 'Cô ấy chối đã ăn miếng bánh cuối cùng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_9_1_5', 'ten_b2_9_1', 'bond', 'Caring for the puppy strengthened the bond between the sisters.', 'Caring for the puppy strengthened the bond between the sisters.', '/bɑːnd/', 'Việc chăm sóc chú cún đã làm thắt chặt thêm tình cảm giữa hai chị em.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_9_1_6', 'ten_b2_9_1', 'disgrace', 'The captain left in disgrace after cheating during the match.', 'The captain left in disgrace after cheating during the match.', '/dɪsˈɡreɪs/', 'Đội trưởng đã rời đi trong sự hổ thẹn sau khi gian lận trong trận đấu.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_9_1_7', 'ten_b2_9_1', 'recognition', 'His face lit up with recognition when I waved.', 'His face lit up with recognition when I waved.', '/ˌrekəɡˈnɪʃən/', 'Khuôn mặt anh ấy bừng sáng sự nhận ra khi tôi vẫy tay chào.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_9_1_8', 'ten_b2_9_1', 'confront', 'She finally confronted her fear and entered the swimming pool.', 'She finally confronted her fear and entered the swimming pool.', '/kənˈfrʌnt/', 'Cô ấy cuối cùng đã đối mặt với nỗi sợ hãi của mình và bước xuống hồ bơi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_9_1_1', 'en-b2-9', 'ten_b2_9_1', 'listening', 'listening', 'My sister works at a respected institution near home.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Ông bà của cô ấy đã di cư sang Canada khi họ còn trẻ.","Cô ấy cuối cùng đã đối mặt với nỗi sợ hãi của mình và bước xuống hồ bơi.","Chị tôi làm việc tại một cơ quan có uy tín gần nhà.","Khuôn mặt anh ấy bừng sáng sự nhận ra khi tôi vẫy tay chào."]'::jsonb, 2, 'My sister works at a respected institution near home. → Chị tôi làm việc tại một cơ quan có uy tín gần nhà.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_9_1_2', 'en-b2-9', 'ten_b2_9_1', 'listening', 'listening', 'Hiding my shoes was a childish thing to do.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Giấu giày của tôi đi là một hành động thật trẻ con.","Chiều nay khách lưu trú có quyền sử dụng hồ bơi độc quyền.","Chị tôi làm việc tại một cơ quan có uy tín gần nhà.","Khuôn mặt anh ấy bừng sáng sự nhận ra khi tôi vẫy tay chào."]'::jsonb, 0, 'Hiding my shoes was a childish thing to do. → Giấu giày của tôi đi là một hành động thật trẻ con.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_9_1_3', 'en-b2-9', 'ten_b2_9_1', 'listening', 'listening', 'It was an honour to represent my local team.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Thật là một vinh dự lớn khi được đại diện cho đội bóng địa phương của tôi.","Người dân địa phương tụ tập ở đây để trò chuyện mỗi tối.","Đội trưởng đã rời đi trong sự hổ thẹn sau khi gian lận trong trận đấu.","Chiều nay khách lưu trú có quyền sử dụng hồ bơi độc quyền."]'::jsonb, 0, 'It was an honour to represent my local team. → Thật là một vinh dự lớn khi được đại diện cho đội bóng địa phương của tôi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_9_2', 'en-b2-9', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_9_2_1', 'ten_b2_9_2', 'institution', 'Every educational institution should provide accessible facilities and appropriate support for students with disabilities.', 'Every educational institution should provide accessible facilities and appropriate support for students with disabilities.', '/ˌɪnstɪˈtuːʃən/', 'Mỗi cơ chế giáo dục nên cung cấp các tiện ích tiếp cận dễ dàng và sự hỗ trợ phù hợp cho học sinh khuyết tật.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_9_2_2', 'ten_b2_9_2', 'childish', 'Dismissing young people''s concerns as childish can discourage them from participating in discussions about their communities.', 'Dismissing young people''s concerns as childish can discourage them from participating in discussions about their communities.', '/ˈtʃaɪldɪʃ/', 'Việc gạt bỏ những bận tâm của giới trẻ là ấu trĩ có thể khiến họ nản lòng, không muốn tham gia các cuộc thảo luận về vấn đề cộng đồng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_9_2_3', 'ten_b2_9_2', 'honour', 'Companies must honour their commitments to workers if they hope to maintain trust and reduce staff turnover.', 'Companies must honour their commitments to workers if they hope to maintain trust and reduce staff turnover.', '/ˈɑːnər/', 'Các công ty phải thực hiện cam kết của mình với người lao động nếu họ muốn duy trì lòng tin và giảm tỷ lệ nhân viên nghỉ việc.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_9_2_4', 'ten_b2_9_2', 'deny', 'No child should be denied access to education because their family cannot afford school fees.', 'No child should be denied access to education because their family cannot afford school fees.', '/dɪˈnaɪ/', 'Không đứa trẻ nào nên bị tước quyền tiếp cận giáo dục chỉ vì gia đình không đủ khả năng đóng học phí.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_9_2_5', 'ten_b2_9_2', 'bond', 'Governments often issue bonds to finance major infrastructure projects without immediately increasing taxes on households.', 'Governments often issue bonds to finance major infrastructure projects without immediately increasing taxes on households.', '/bɑːnd/', 'Chính phủ thường phát hành trái phiếu để tài trợ cho các dự án cơ sở hạ tầng lớn mà không làm tăng ngay gánh nặng thuế cho các hộ gia đình.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_9_2_6', 'ten_b2_9_2', 'disgrace', 'Officials who misuse public funds bring disgrace on their institutions and weaken public trust in government.', 'Officials who misuse public funds bring disgrace on their institutions and weaken public trust in government.', '/dɪsˈɡreɪs/', 'Các quan chức lạm dụng công quỹ làm hoen ố uy tín của cơ quan họ và làm suy yếu niềm tin của công chúng vào chính phủ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_9_2_1', 'en-b2-9', 'ten_b2_9_2', 'listening', 'listening', 'Every educational institution should provide accessible facilities and appropriate support for students with disabilities.', NULL, 'Trong câu vừa nghe, từ “institution” mang nghĩa nào sau đây?', '["cơ quan; tổ chức; viện","thanh kiếm; đao","rút tiền (từ tài khoản ngân hàng)","xé rách; làm rách"]'::jsonb, 0, '“institution” (/ˌɪnstɪˈtuːʃən/): cơ quan; tổ chức; viện. Câu đầy đủ: Every educational institution should provide accessible facilities and appropriate support for students with disabilities.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_9_2_2', 'en-b2-9', 'ten_b2_9_2', 'listening', 'listening', 'Dismissing young people''s concerns as childish can discourage them from participating in discussions about their communities.', NULL, 'Trong câu vừa nghe, từ “childish” mang nghĩa nào sau đây?', '["thành lập; thiết lập","ấu trĩ; trẻ con; không chín chắn","vinh dự; lòng tự trọng; niềm tự hào","thỉnh thoảng; đôi khi"]'::jsonb, 1, '“childish” (/ˈtʃaɪldɪʃ/): ấu trĩ; trẻ con; không chín chắn. Câu đầy đủ: Dismissing young people''s concerns as childish can discourage them from participating in discussions about their communities.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
