INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_9_1', 'en-b2-9', NULL, 'comprehensive_test', 'listening', 'institution', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thủy triều; nước thủy triều","cơ quan; tổ chức; viện","sự mở rộng; sự bành trướng; sự phình ra","nỗi đau đớn; sự khổ sở"]'::jsonb, 1, 'institution (/ˌɪnstɪˈtuːʃən/) → cơ quan; tổ chức; viện; thể chế; phong tục lâu đời', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_9_2', 'en-b2-9', NULL, 'comprehensive_test', 'listening', 'Hiding my shoes was a childish thing to do.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ứng dụng này tích hợp lịch làm việc của tôi với danh sách mua sắm.","Giấu giày của tôi đi là một hành động thật trẻ con.","Một nhân viên đã hộ tống chúng tôi đến phòng chờ.","Chúng tôi đã có một cuộc tranh luận sôi nổi về việc nuôi thú cưng trong nhà."]'::jsonb, 1, 'Hiding my shoes was a childish thing to do. → Giấu giày của tôi đi là một hành động thật trẻ con.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_9_3', 'en-b2-9', NULL, 'comprehensive_test', 'listening', 'honour', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["trái đạo đức; đồi phong bại tục; bất chính","vinh dự; lòng tự trọng; niềm tự hào","giòn; giòn rụm","truy tìm; lần theo dấu vết; truy nguyên"]'::jsonb, 1, 'honour (/ˈɑːnər/) → vinh dự; lòng tự trọng; niềm tự hào; tôn vinh; tỏ lòng kính trọng; biểu dương; thực hiện; giữ (lời hứa, cam kết)', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_9_4', 'en-b2-9', NULL, 'comprehensive_test', 'listening', 'She denied eating the last piece of cake.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ứng dụng này tích hợp lịch làm việc của tôi với danh sách mua sắm.","Cô ấy chối đã ăn miếng bánh cuối cùng.","Cô ấy dán mắt nhìn qua khung cửa sổ để ngắm chú mèo con.","Việc chăm sóc chú cún đã làm thắt chặt thêm tình cảm giữa hai chị em."]'::jsonb, 1, 'She denied eating the last piece of cake. → Cô ấy chối đã ăn miếng bánh cuối cùng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_9_5', 'en-b2-9', NULL, 'comprehensive_test', 'listening', 'bond', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["ra mắt; giới thiệu (sản phẩm); khởi xướng; phát động","cúi chụm lại; nép sát; cuộn tròn","sự phun trào (núi lửa)","mối liên kết; sự gắn bó; tình cảm"]'::jsonb, 3, 'bond (/bɑːnd/) → mối liên kết; sự gắn bó; tình cảm; trái phiếu; gắn kết; tạo quan hệ thân thiết; kết dính', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_9_6', 'en-b2-9', NULL, 'comprehensive_test', 'listening', 'The captain left in disgrace after cheating during the match.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ông bà của cô ấy đã di cư sang Canada khi họ còn trẻ.","Đội trưởng đã rời đi trong sự hổ thẹn sau khi gian lận trong trận đấu.","Chúng tôi đã có một cuộc tranh luận sôi nổi về việc nuôi thú cưng trong nhà.","Chúng tôi xuất trình hộ chiếu ở quầy kiểm tra nhập cảnh sau chuyến bay."]'::jsonb, 1, 'The captain left in disgrace after cheating during the match. → Đội trưởng đã rời đi trong sự hổ thẹn sau khi gian lận trong trận đấu.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_9_7', 'en-b2-9', NULL, 'comprehensive_test', 'listening', 'recognition', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["phần còn lại; đồ thừa","vội vàng; hấp tấp; liều lĩnh","sự nhận ra; sự nhận diện","mọi người; người (thường chỉ một nhóm cụ thể)"]'::jsonb, 2, 'recognition (/ˌrekəɡˈnɪʃən/) → sự nhận ra; sự nhận diện; sự công nhận; sự đánh giá cao từ công chúng; sự thừa nhận; sự công nhận chính thức', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_9_8', 'en-b2-9', NULL, 'comprehensive_test', 'listening', 'She finally confronted her fear and entered the swimming pool.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi xuất trình hộ chiếu ở quầy kiểm tra nhập cảnh sau chuyến bay.","Đội trưởng đã rời đi trong sự hổ thẹn sau khi gian lận trong trận đấu.","Cô ấy cuối cùng đã đối mặt với nỗi sợ hãi của mình và bước xuống hồ bơi.","Cô ấy chối đã ăn miếng bánh cuối cùng."]'::jsonb, 2, 'She finally confronted her fear and entered the swimming pool. → Cô ấy cuối cùng đã đối mặt với nỗi sợ hãi của mình và bước xuống hồ bơi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_9_9', 'en-b2-9', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a close connection between people or groups”?', '["exclusive","debate","identification","bond"]'::jsonb, 3, 'bond (/bɑːnd/) → mối liên kết; sự gắn bó; tình cảm', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_9_10', 'en-b2-9', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “loss of respect caused by unacceptable behaviour”?', '["gay","exclusive","disgrace","deny"]'::jsonb, 2, 'disgrace (/dɪsˈɡreɪs/) → sự mất thể diện; sự ô nhục', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_9_11', 'en-b2-9', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “The act of identifying someone or something encountered before.”?', '["violent","bond","recognition","harsh"]'::jsonb, 2, 'recognition (/ˌrekəɡˈnɪʃən/) → sự nhận ra; sự nhận diện', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
