INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_9_18', 'en-b2-9', NULL, 'comprehensive_test', 'reading', NULL, 'Every educational institution should provide accessible facilities and appropriate support for students with disabilities.', 'Dựa vào câu trên, từ “institution” có nghĩa phù hợp nhất là gì?', '["viên nang; viên con nhộng","quầy hàng; sạp hàng","thợ thủ công; nghệ nhân","cơ quan; tổ chức; viện"]'::jsonb, 3, 'institution: cơ quan; tổ chức; viện; thể chế; phong tục lâu đời. Dịch cả câu: Mỗi cơ chế giáo dục nên cung cấp các tiện ích tiếp cận dễ dàng và sự hỗ trợ phù hợp cho học sinh khuyết tật.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_9_19', 'en-b2-9', NULL, 'comprehensive_test', 'reading', NULL, 'Dismissing young people''s concerns as childish can discourage them from participating in discussions about their communities.', 'Dựa vào câu trên, từ “childish” có nghĩa phù hợp nhất là gì?', '["ấu trĩ; trẻ con; không chín chắn","sưng tấy, sưng phồng (do chấn thương hoặc bệnh tật)","cằn nhằn; phàn nàn","phòng khiêu vũ; vũ trường"]'::jsonb, 0, 'childish: ấu trĩ; trẻ con; không chín chắn; thuộc về trẻ em; mang tính trẻ thơ. Dịch cả câu: Việc gạt bỏ những bận tâm của giới trẻ là ấu trĩ có thể khiến họ nản lòng, không muốn tham gia các cuộc thảo luận về vấn đề cộng đồng.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_9_20', 'en-b2-9', NULL, 'comprehensive_test', 'reading', NULL, 'Companies must honour their commitments to workers if they hope to maintain trust and reduce staff turnover.', 'Dựa vào câu trên, từ “honour” có nghĩa phù hợp nhất là gì?', '["móng vuốt","thư mục tham khảo; danh mục tài liệu tham khảo","vinh dự; lòng tự trọng; niềm tự hào","cảng biển; thành phố cảng"]'::jsonb, 2, 'honour: vinh dự; lòng tự trọng; niềm tự hào; tôn vinh; tỏ lòng kính trọng; biểu dương; thực hiện; giữ (lời hứa, cam kết). Dịch cả câu: Các công ty phải thực hiện cam kết của mình với người lao động nếu họ muốn duy trì lòng tin và giảm tỷ lệ nhân viên nghỉ việc.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_9_21', 'en-b2-9', NULL, 'comprehensive_test', 'reading', NULL, 'No child should be denied access to education because their family cannot afford school fees.', 'Dựa vào câu trên, từ “deny” có nghĩa phù hợp nhất là gì?', '["bãi rác; bãi chôn lấp rác","đủ; đầy đủ","phủ nhận; chối bỏ","rõ rệt; đáng kể; rõ ràng"]'::jsonb, 2, 'deny: phủ nhận; chối bỏ; từ chối cung cấp; tước đoạt. Dịch cả câu: Không đứa trẻ nào nên bị tước quyền tiếp cận giáo dục chỉ vì gia đình không đủ khả năng đóng học phí.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_9_22', 'en-b2-9', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tích hợp; kết hợp”', '["lime","hesitation","slavery","integrate"]'::jsonb, 3, 'tích hợp; kết hợp → integrate (/ˈɪntɪɡreɪt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_9_23', 'en-b2-9', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “dành riêng; độc quyền”', '["findings","exclusive","overwhelming","certainty"]'::jsonb, 1, 'dành riêng; độc quyền → exclusive (/ɪkˈskluːsɪv/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_9_24', 'en-b2-9', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “phẩm giá; lòng tự trọng”', '["cosmetics","motivate","craft","dignity"]'::jsonb, 3, 'phẩm giá; lòng tự trọng → dignity (/ˈdɪɡnəti/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-10', 'en', 'Bài 10: Xã hội & Cộng đồng (3) - CEFR B2', 'CEFR B2', 'B2 · Xã hội', '26 từ vựng Tiếng Anh CEFR B2 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4010, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_oppose', 'en-b2-10', 'oppose', '/əˈpoʊz/', 'B2', 'động từ: phản đối; chống lại', 'v.', 'opposition (n.), opponent (n.), opposed (adj.)', 'Đồng nghĩa: resist, object to · Trái nghĩa: support, favour', 'Động từ oppose đi trực tiếp với danh từ hoặc danh động từ, không cần giới từ to.', 'Our neighbours oppose building a road through the park.', NULL, 'Những người hàng xóm của chúng tôi phản đối việc xây dựng con đường đi xuyên qua công viên.', '{"wordId":"oppose","ukIpa":"/əˈpəʊz/","usIpa":"/əˈpoʊz/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"Disagree with something and try to prevent or change it.","vi":"động từ: phản đối; chống lại"}],"examples":[{"en":"Our neighbours oppose building a road through the park.","vi":"Những người hàng xóm của chúng tôi phản đối việc xây dựng con đường đi xuyên qua công viên.","audioKind":"ex"},{"en":"Many residents oppose airport expansion because they fear increased noise and damage to local wildlife habitats.","vi":"Nhiều cư dân phản đối việc mở rộng sân bay vì họ lo ngại tiếng ồn gia tăng và tổn hại đến môi trường sống của động vật hoang dã địa phương.","audioKind":"ex2"}],"collocations":[{"en":"strongly oppose","vi":"kịch liệt phản đối"},{"en":"oppose a proposal","vi":"phản đối một đề xuất"},{"en":"oppose doing something","vi":"phản đối việc làm gì đó"}],"wordFamily":["opposition (n.)","opponent (n.)","opposed (adj.)"],"synonyms":["resist","object to"],"antonyms":["support","favour"],"tipVi":"Động từ oppose đi trực tiếp với danh từ hoặc danh động từ, không cần giới từ to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_patrol', 'en-b2-10', 'patrol', '/pəˈtroʊl/', 'B2', 'tuần tra; kiểm tra; hoạt động tuần tra; đội tuần tra', 'v.', NULL, NULL, 'Quá khứ patrolled, tiếp diễn patrolling, đều nhân đôi chữ l.', 'Two guards patrol the park after dark each evening.', NULL, 'Hai bảo vệ đi tuần tra quanh công viên vào mỗi buổi tối sau khi trời tối.', '{"wordId":"patrol","ukIpa":"/pəˈtrəʊl/","usIpa":"/pəˈtroʊl/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"To move around an area regularly to maintain safety.","vi":"tuần tra; kiểm tra"},{"pos":"n.","en":"An activity or group that checks an area for danger.","vi":"hoạt động tuần tra; đội tuần tra"}],"examples":[{"en":"Two guards patrol the park after dark each evening.","vi":"Hai bảo vệ đi tuần tra quanh công viên vào mỗi buổi tối sau khi trời tối.","audioKind":"ex"},{"en":"Rangers patrol protected forests to prevent illegal logging and monitor threats to endangered wildlife.","vi":"Các kiểm lâm viên tuần tra các khu rừng được bảo vệ để ngăn chặn tình trạng chặt phá rừng trái phép và theo dõi các mối đe dọa đối với động vật hoang dã có nguy cơ tuyệt chủng.","audioKind":"ex2"}],"collocations":[{"en":"on patrol","vi":"đang tuần tra"},{"en":"patrol the streets","vi":"tuần tra đường phố"},{"en":"border patrol","vi":"tuần tra biên giới; đội tuần tra biên giới"},{"en":"regular patrols","vi":"các đợt tuần tra định kỳ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Quá khứ patrolled, tiếp diễn patrolling, đều nhân đôi chữ l.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_immoral', 'en-b2-10', 'immoral', '/ɪˈmɔːrəl/', 'B2', 'trái đạo đức; đồi phong bại tục; bất chính', 'adj.', 'moral (adj.), morality (n.), immorality (n.), immorally (adv.)', 'Đồng nghĩa: unethical, wrong · Trái nghĩa: moral, ethical', 'immoral chỉ hành vi trái đạo đức; amoral chỉ trạng thái không có ý thức về đạo đức.', 'She thought keeping the lost wallet would be immoral.', NULL, 'Cô ấy nghĩ rằng việc giữ lại chiếc ví nhặt được là hành vi trái đạo đức.', '{"wordId":"immoral","ukIpa":"/ɪˈmɒrəl/","usIpa":"/ɪˈmɔːrəl/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Contrary to accepted principles of right and wrong.","vi":"trái đạo đức; đồi phong bại tục; bất chính"}],"examples":[{"en":"She thought keeping the lost wallet would be immoral.","vi":"Cô ấy nghĩ rằng việc giữ lại chiếc ví nhặt được là hành vi trái đạo đức.","audioKind":"ex"},{"en":"Many consumers consider it immoral for companies to exploit vulnerable workers in pursuit of higher profits.","vi":"Nhiều người tiêu dùng cho rằng việc các doanh nghiệp bóc lột lao động dễ bị tổn thương để chuộc lợi cao là điều trái đạo đức.","audioKind":"ex2"}],"collocations":[{"en":"immoral behaviour","vi":"hành vi trái đạo đức"},{"en":"immoral practices","vi":"thủ đoạn trái đạo đức"},{"en":"consider something immoral","vi":"coi điều gì là trái đạo đức"}],"wordFamily":["moral (adj.)","morality (n.)","immorality (n.)","immorally (adv.)"],"synonyms":["unethical","wrong"],"antonyms":["moral","ethical"],"tipVi":"immoral chỉ hành vi trái đạo đức; amoral chỉ trạng thái không có ý thức về đạo đức.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_participation', 'en-b2-10', 'participation', '/pɑːrˌtɪsəˈpeɪʃən/', 'B2', 'sự tham gia; sự góp mặt', 'n.', 'participate (v.), participant (n.), participatory (adj.)', 'Đồng nghĩa: involvement, engagement', 'Thường là danh từ không đếm được; khi nói tham gia vào hoạt động nào, dùng participation in.', 'Your participation made our neighbourhood clean-up much more enjoyable.', NULL, 'Sự tham gia của bạn đã giúp hoạt động dọn dẹp khu phố của chúng ta vui vẻ hơn rất nhiều.', '{"wordId":"participation","ukIpa":"/pɑːˌtɪsɪˈpeɪʃən/","usIpa":"/pɑːrˌtɪsəˈpeɪʃən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"the act of taking part in an activity or event","vi":"sự tham gia; sự góp mặt"}],"examples":[{"en":"Your participation made our neighbourhood clean-up much more enjoyable.","vi":"Sự tham gia của bạn đã giúp hoạt động dọn dẹp khu phố của chúng ta vui vẻ hơn rất nhiều.","audioKind":"ex"},{"en":"Active participation in community projects can strengthen social connections and give residents a greater sense of belonging.","vi":"Việc tham gia tích cực vào các dự án cộng đồng có thể củng cố các mối quan hệ xã hội và mang lại cho cư dân cảm giác thuộc về lớn hơn.","audioKind":"ex2"}],"collocations":[{"en":"participation in","vi":"tham gia vào"},{"en":"active participation","vi":"sự tham gia tích cực"},{"en":"public participation","vi":"sự tham gia của công chúng"},{"en":"encourage participation","vi":"khuyến khích sự tham gia"}],"wordFamily":["participate (v.)","participant (n.)","participatory (adj.)"],"synonyms":["involvement","engagement"],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; khi nói tham gia vào hoạt động nào, dùng participation in.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inherit', 'en-b2-10', 'inherit', '/ɪnˈherɪt/', 'B2', 'thừa kế (tài sản); di truyền (đặc điểm từ cha mẹ); tiếp quản; gánh chịu (trách nhiệm, vấn đề)', 'v.', 'inheritance (n.), inherited (adj.), inheritor (n.)', NULL, 'Thường dùng cấu trúc "inherit sth from sb"; cũng có thể dùng cho đặc điểm di truyền.', 'Leila inherited a small cottage from her grandmother.', NULL, 'Leila đã thừa kế một ngôi nhà nhỏ từ bà của mình.', '{"wordId":"inherit","ukIpa":"/ɪnˈherɪt/","usIpa":"/ɪnˈherɪt/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"Receive money or property from someone who has died","vi":"thừa kế (tài sản)"},{"pos":"v.","en":"Receive physical characteristics genetically from your parents","vi":"di truyền (đặc điểm từ cha mẹ)"},{"pos":"v.","en":"Receive responsibilities or problems left by a previous person","vi":"tiếp quản; gánh chịu (trách nhiệm, vấn đề)"}],"examples":[{"en":"Leila inherited a small cottage from her grandmother.","vi":"Leila đã thừa kế một ngôi nhà nhỏ từ bà của mình.","audioKind":"ex"},{"en":"Future generations may inherit serious environmental problems unless governments take decisive action to reduce pollution.","vi":"Các thế hệ tương lai có thể phải gánh chịu những vấn đề môi trường nghiêm trọng nếu chính phủ không có hành động quyết liệt để giảm thiểu ô nhiễm.","audioKind":"ex2"}],"collocations":[{"en":"inherit property","vi":"thừa kế tài sản"},{"en":"inherit a fortune","vi":"thừa kế gia tài lớn"},{"en":"inherit traits","vi":"di truyền các đặc điểm"},{"en":"inherit from","vi":"thừa kế từ"}],"wordFamily":["inheritance (n.)","inherited (adj.)","inheritor (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng cấu trúc \"inherit sth from sb\"; cũng có thể dùng cho đặc điểm di truyền.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spy', 'en-b2-10', 'spy', '/spaɪ/', 'B2', 'gián điệp; mật thám; theo dõi; ám sát; chợt thấy; thoắt thấy', 'n.', 'spying (n.)', NULL, 'Theo dõi ai dùng spy on; quá khứ và phân từ quá khứ là spied.', 'I spied a tiny kitten hiding behind the flowerpot.', NULL, 'Tôi thoáng thấy một chú mèo con đang trốn sau chậu hoa.', '{"wordId":"spy","ukIpa":"/spaɪ/","usIpa":"/spaɪ/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"Someone who secretly gathers information about a country or organisation","vi":"gián điệp; mật thám"},{"pos":"v.","en":"To secretly watch someone or gather information about them","vi":"theo dõi; ám sát"},{"pos":"v.","en":"To notice someone or something, especially after looking carefully","vi":"chợt thấy; thoắt thấy"}],"examples":[{"en":"I spied a tiny kitten hiding behind the flowerpot.","vi":"Tôi thoáng thấy một chú mèo con đang trốn sau chậu hoa.","audioKind":"ex"},{"en":"Many users worry that connected devices could spy on their activities without permission.","vi":"Nhiều người dùng lo ngại rằng các thiết bị kết nối có thể theo dõi hoạt động của họ mà không có sự cho phép.","audioKind":"ex2"}],"collocations":[{"en":"spy on someone","vi":"theo dõi ai đó"},{"en":"spy novel","vi":"tiểu thuyết trinh thám"},{"en":"spy network","vi":"mạng lưới gián điệp"}],"wordFamily":["spying (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Theo dõi ai dùng spy on; quá khứ và phân từ quá khứ là spied.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hostage', 'en-b2-10', 'hostage', '/ˈhɑːstɪdʒ/', 'B2', 'con tin', 'n.', NULL, NULL, 'Trong cụm take hoặc hold someone hostage, trước hostage không dùng mạo từ.', 'The hostage returned home safely and hugged her family.', NULL, 'Nữ con tin đã trở về nhà an toàn và ôm lấy gia đình mình.', '{"wordId":"hostage","ukIpa":"/ˈhɒstɪdʒ/","usIpa":"/ˈhɑːstɪdʒ/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"someone held captive to force others to meet demands","vi":"con tin"}],"examples":[{"en":"The hostage returned home safely and hugged her family.","vi":"Nữ con tin đã trở về nhà an toàn và ôm lấy gia đình mình.","audioKind":"ex"},{"en":"Governments must balance public safety with the need to secure the release of every hostage.","vi":"Chính phủ phải cân bằng giữa an toàn công cộng và nhu cầu đảm bảo sự tự do cho từng con tin.","audioKind":"ex2"}],"collocations":[{"en":"take someone hostage","vi":"bắt cóc ai làm con tin"},{"en":"hold someone hostage","vi":"giam giữ ai làm con tin"},{"en":"release a hostage","vi":"giải cứu con tin"},{"en":"hostage negotiations","vi":"đàm phán con tin"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong cụm take hoặc hold someone hostage, trước hostage không dùng mạo từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_commit', 'en-b2-10', 'commit', '/kəˈmɪt/', 'B2', 'phạm (tội hoặc sai lầm nghiêm trọng); cam kết; hứa chắc chắn; dành; đầu tư (tiền bạc, thời gian, nguồn lực)', 'v.', 'commitment (n.), committed (adj.)', NULL, 'Trong "commit to", "to" là giới từ, theo sau là danh từ hoặc danh động từ (V-ing).', 'The police arrested someone who had committed a burglary.', NULL, 'Cảnh sát đã bắt giữ một người phạm tội trộm cắp.', '{"wordId":"commit","ukIpa":"/kəˈmɪt/","usIpa":"/kəˈmɪt/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"To do something illegal or seriously wrong.","vi":"phạm (tội hoặc sai lầm nghiêm trọng)"},{"pos":"v.","en":"To promise firmly to do something or support someone.","vi":"cam kết; hứa chắc chắn"},{"pos":"v.","en":"To make money, time, or resources available for a purpose.","vi":"dành; đầu tư (tiền bạc, thời gian, nguồn lực)"}],"examples":[{"en":"The police arrested someone who had committed a burglary.","vi":"Cảnh sát đã bắt giữ một người phạm tội trộm cắp.","audioKind":"ex"},{"en":"Governments must commit sufficient resources to public transport if they want to reduce urban traffic congestion.","vi":"Chính phủ phải đầu tư đủ nguồn lực cho giao thông công cộng nếu muốn giảm ùn tắc giao thông đô thị.","audioKind":"ex2"}],"collocations":[{"en":"commit a crime","vi":"phạm tội"},{"en":"commit to doing something","vi":"cam kết làm gì"},{"en":"commit resources to","vi":"đầu tư nguồn lực vào"},{"en":"commit oneself to","vi":"cống hiến hết mình cho"}],"wordFamily":["commitment (n.)","committed (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong \"commit to\", \"to\" là giới từ, theo sau là danh từ hoặc danh động từ (V-ing).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_adapt', 'en-b2-10', 'adapt', '/əˈdæpt/', 'B2', 'thích nghi; làm cho thích ứng; chuyển thể; điều chỉnh (cho mục đích khác)', 'v.', 'adaptation (n.), adaptable (adj.), adaptability (n.), adaptive (adj.)', 'Đồng nghĩa: adjust, modify', '"adapt to" đi với danh từ hoặc danh động từ (V-ing); tránh nhầm lẫn với "adopt" (áp dụng, nhận nuôi).', 'Our cat quickly adapted to life in the new flat.', NULL, 'Con mèo của chúng tôi nhanh chóng thích nghi với cuộc sống ở căn hộ mới.', '{"wordId":"adapt","ukIpa":"/əˈdæpt/","usIpa":"/əˈdæpt/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"to change behaviour or features to suit new conditions","vi":"thích nghi; làm cho thích ứng"},{"pos":"v.","en":"to change something for a different use or audience","vi":"chuyển thể; điều chỉnh (cho mục đích khác)"}],"examples":[{"en":"Our cat quickly adapted to life in the new flat.","vi":"Con mèo của chúng tôi nhanh chóng thích nghi với cuộc sống ở căn hộ mới.","audioKind":"ex"},{"en":"Schools must adapt their teaching methods to meet the needs of students from diverse cultural backgrounds.","vi":"Nhà trường phải điều chỉnh phương pháp giảng dạy để đáp ứng nhu cầu của học sinh đến từ các nền văn hóa đa dạng.","audioKind":"ex2"}],"collocations":[{"en":"adapt to change","vi":"thích ứng với sự thay đổi"},{"en":"adapt teaching methods","vi":"điều chỉnh phương pháp giảng dạy"},{"en":"adapt a novel for television","vi":"chuyển thể tiểu thuyết thành phim truyền hình"}],"wordFamily":["adaptation (n.)","adaptable (adj.)","adaptability (n.)","adaptive (adj.)"],"synonyms":["adjust","modify"],"antonyms":[],"tipVi":"\"adapt to\" đi với danh từ hoặc danh động từ (V-ing); tránh nhầm lẫn với \"adopt\" (áp dụng, nhận nuôi).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mutual', 'en-b2-10', 'mutual', '/ˈmjuːtʃuəl/', 'B2', 'lẫn nhau; qua lại; chung; cùng có', 'adj.', 'mutually (adv.)', 'Đồng nghĩa: reciprocal, shared · Trái nghĩa: one-sided', '"mutual friend" là bạn chung (của hai hay nhiều người), không phải là bạn bè của nhau.', 'Our friendship grew through mutual trust and honest conversations.', NULL, 'Tình bạn của chúng tôi lớn dần qua sự tin tưởng lẫn nhau và những cuộc trò chuyện chân thành.', '{"wordId":"mutual","ukIpa":"/ˈmjuːtʃuəl/","usIpa":"/ˈmjuːtʃuəl/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Felt or done by each person towards the other.","vi":"lẫn nhau; qua lại"},{"pos":"adj.","en":"Shared by two or more people or groups.","vi":"chung; cùng có"}],"examples":[{"en":"Our friendship grew through mutual trust and honest conversations.","vi":"Tình bạn của chúng tôi lớn dần qua sự tin tưởng lẫn nhau và những cuộc trò chuyện chân thành.","audioKind":"ex"},{"en":"Successful international cooperation depends on mutual respect and a willingness to address shared environmental challenges.","vi":"Sự hợp tác quốc tế thành công phụ thuộc vào sự tôn trọng lẫn nhau và thiện chí cùng giải quyết các thách thức chung về môi trường.","audioKind":"ex2"}],"collocations":[{"en":"mutual respect","vi":"sự tôn trọng lẫn nhau"},{"en":"mutual benefit","vi":"lợi ích chung; cùng có lợi"},{"en":"mutual friend","vi":"bạn chung"},{"en":"by mutual agreement","vi":"theo sự đồng thuận của đôi bên"}],"wordFamily":["mutually (adv.)"],"synonyms":["reciprocal","shared"],"antonyms":["one-sided"],"tipVi":"\"mutual friend\" là bạn chung (của hai hay nhiều người), không phải là bạn bè của nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_goodness', 'en-b2-10', 'goodness', '/ˈɡʊdnəs/', 'B2', 'lòng tốt; đức hạnh; chất bổ dưỡng; dưỡng chất (trong thực phẩm); trời ơi (biểu lộ sự ngạc nhiên, lo lắng hoặc sốc)', 'n.', 'good (adj.)', 'Đồng nghĩa: kindness, virtue · Trái nghĩa: wickedness', 'Khi là danh từ thường không đếm được; "My goodness" dùng để biểu lộ sự ngạc nhiên.', 'Her goodness showed when she shared her last sandwich.', NULL, 'Lòng tốt của cô ấy được thể hiện khi cô chia sẻ chiếc bánh mì cuối cùng của mình.', '{"wordId":"goodness","ukIpa":"/ˈɡʊdnəs/","usIpa":"/ˈɡʊdnəs/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"the quality of being kind and morally good","vi":"lòng tốt; đức hạnh"},{"pos":"n.","en":"the substances in food that help keep you healthy","vi":"chất bổ dưỡng; dưỡng chất (trong thực phẩm)"},{"pos":"int.","en":"used to express surprise, worry, or shock","vi":"trời ơi (biểu lộ sự ngạc nhiên, lo lắng hoặc sốc)"}],"examples":[{"en":"Her goodness showed when she shared her last sandwich.","vi":"Lòng tốt của cô ấy được thể hiện khi cô chia sẻ chiếc bánh mì cuối cùng của mình.","audioKind":"ex"},{"en":"Steaming vegetables can preserve more of their natural goodness than boiling them for long periods.","vi":"Hấp rau củ có thể giữ lại nhiều dưỡng chất tự nhiên hơn so với việc luộc trong thời gian dài.","audioKind":"ex2"}],"collocations":[{"en":"out of the goodness of your heart","vi":"xuất phát từ tấm lòng nhân hậu"},{"en":"natural goodness","vi":"dưỡng chất tự nhiên"},{"en":"thank goodness","vi":"may quá; ơn trời"},{"en":"my goodness","vi":"trời ơi"}],"wordFamily":["good (adj.)"],"synonyms":["kindness","virtue"],"antonyms":["wickedness"],"tipVi":"Khi là danh từ thường không đếm được; \"My goodness\" dùng để biểu lộ sự ngạc nhiên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_coffin', 'en-b2-10', 'coffin', '/ˈkɔːfɪn/', 'B2', 'quan tài; linh cữu', 'n.', NULL, 'Đồng nghĩa: casket', 'Từ casket trong tiếng Anh-Mỹ cũng thường mang nghĩa là quan tài.', 'White flowers lay on the closed wooden coffin.', NULL, 'Những bông hoa trắng được đặt trên chiếc quan tài bằng gỗ đã đóng nắp.', '{"wordId":"coffin","ukIpa":"/ˈkɒfɪn/","usIpa":"/ˈkɔːfɪn/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"A box holding a dead person''s body for burial or cremation.","vi":"quan tài; linh cữu"}],"examples":[{"en":"White flowers lay on the closed wooden coffin.","vi":"Những bông hoa trắng được đặt trên chiếc quan tài bằng gỗ đã đóng nắp.","audioKind":"ex"},{"en":"The materials used to make a coffin can reflect local resources and cultural traditions.","vi":"Các vật liệu dùng để làm quan tài có thể phản ánh nguồn tài nguyên địa phương và truyền thống văn hóa.","audioKind":"ex2"}],"collocations":[{"en":"a wooden coffin","vi":"quan tài gỗ"},{"en":"carry a coffin","vi":"khiêng quan tài"},{"en":"a nail in the coffin","vi":"góp phần làm suy sụp"}],"wordFamily":[],"synonyms":["casket"],"antonyms":[],"tipVi":"Từ casket trong tiếng Anh-Mỹ cũng thường mang nghĩa là quan tài.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dependence', 'en-b2-10', 'dependence', '/dɪˈpendəns/', 'B2', 'sự phụ thuộc; sự dựa dẫm; tính lệ thuộc; sự nghiện', 'n.', 'depend (v.), dependent (adj.), independence (n.), independent (adj.)', 'Đồng nghĩa: reliance · Trái nghĩa: independence, self-reliance', 'Cụm từ cố định dependence on, không dùng dependence of.', 'Learning to cycle reduced my dependence on lifts from friends.', NULL, 'Việc học đi xe đạp đã làm giảm sự phụ thuộc của tôi vào việc nhờ bạn bè chở đi.', '{"wordId":"dependence","ukIpa":"/dɪˈpendəns/","usIpa":"/dɪˈpendəns/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"the need to rely on someone or something","vi":"sự phụ thuộc; sự dựa dẫm"},{"pos":"n.","en":"a strong physical or mental need for a substance","vi":"tính lệ thuộc; sự nghiện"}],"examples":[{"en":"Learning to cycle reduced my dependence on lifts from friends.","vi":"Việc học đi xe đạp đã làm giảm sự phụ thuộc của tôi vào việc nhờ bạn bè chở đi.","audioKind":"ex"},{"en":"Investment in renewable energy can reduce a country''s dependence on imported fuels and improve energy security.","vi":"Việc đầu tư vào năng lượng tái tạo có thể giảm sự phụ thuộc của một quốc gia vào nhiên liệu nhập khẩu và nâng cao an ninh năng lượng.","audioKind":"ex2"}],"collocations":[{"en":"dependence on","vi":"sự phụ thuộc vào"},{"en":"reduce dependence","vi":"giảm sự phụ thuộc"},{"en":"financial dependence","vi":"sự phụ thuộc tài chính"},{"en":"drug dependence","vi":"sự lệ thuộc vào thuốc"}],"wordFamily":["depend (v.)","dependent (adj.)","independence (n.)","independent (adj.)"],"synonyms":["reliance"],"antonyms":["independence","self-reliance"],"tipVi":"Cụm từ cố định dependence on, không dùng dependence of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conservative', 'en-b2-10', 'conservative', '/kənˈsɝːvətɪv/', 'B2', 'bảo thủ; thủ cựu; thận trọng; ở mức độ dè dặt (để tránh đánh giá quá cao); người theo phái bảo thủ', 'adj.', 'conservatism (n.), conservatively (adv.)', 'Đồng nghĩa: traditional, cautious · Trái nghĩa: progressive', 'Chữ viết thường thường chỉ tính bảo thủ; chữ viết hoa có thể chỉ đảng bảo thủ.', 'My uncle is conservative and dislikes changing family traditions.', NULL, 'Chú tôi rất bảo thủ và không thích thay đổi các truyền thống của gia đình.', '{"wordId":"conservative","ukIpa":"/kənˈsɜːvətɪv/","usIpa":"/kənˈsɝːvətɪv/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"preferring traditional ideas and avoiding major changes","vi":"bảo thủ; thủ cựu"},{"pos":"adj.","en":"deliberately low or cautious to avoid overestimating","vi":"thận trọng; ở mức độ dè dặt (để tránh đánh giá quá cao)"},{"pos":"n.","en":"someone who favours traditional values and limited change","vi":"người theo phái bảo thủ"}],"examples":[{"en":"My uncle is conservative and dislikes changing family traditions.","vi":"Chú tôi rất bảo thủ và không thích thay đổi các truyền thống của gia đình.","audioKind":"ex"},{"en":"Even conservative estimates suggest that improving home insulation could substantially reduce household energy consumption.","vi":"Ngay cả theo ước tính thận trọng, việc cải thiện hệ thống cách nhiệt của ngôi nhà cũng có thể giảm đáng kể lượng tiêu thụ năng lượng của hộ gia đình.","audioKind":"ex2"}],"collocations":[{"en":"conservative views","vi":"quan điểm bảo thủ"},{"en":"conservative estimate","vi":"ước tính thận trọng"},{"en":"conservative approach","vi":"cách tiếp cận thận trọng"}],"wordFamily":["conservatism (n.)","conservatively (adv.)"],"synonyms":["traditional","cautious"],"antonyms":["progressive"],"tipVi":"Chữ viết thường thường chỉ tính bảo thủ; chữ viết hoa có thể chỉ đảng bảo thủ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_encounter', 'en-b2-10', 'encounter', '/ɪnˈkaʊntər/', 'B2', 'gặp phải; bắt gặp (đặc biệt là tình cờ hoặc bất ngờ); sự tình cờ gặp gỡ; cuộc chạm trán', 'v.', NULL, 'Đồng nghĩa: meet, come across', 'Động từ "encounter" có thể đi trực tiếp với tân ngữ; danh từ thường dùng cụm "an encounter with".', 'We encountered a curious fox on our evening walk.', NULL, 'Chúng tôi tình cờ gặp một con cáo tò mò trong chuyến đi dạo buổi tối.', '{"wordId":"encounter","ukIpa":"/ɪnˈkaʊntə/","usIpa":"/ɪnˈkaʊntər/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"meet someone or experience something, especially unexpectedly","vi":"gặp phải; bắt gặp (đặc biệt là tình cờ hoặc bất ngờ)"},{"pos":"n.","en":"an unexpected meeting or experience involving someone or something","vi":"sự tình cờ gặp gỡ; cuộc chạm trán"}],"examples":[{"en":"We encountered a curious fox on our evening walk.","vi":"Chúng tôi tình cờ gặp một con cáo tò mò trong chuyến đi dạo buổi tối.","audioKind":"ex"},{"en":"Students studying abroad may encounter cultural differences that challenge their assumptions about communication and social behaviour.","vi":"Các du học sinh có thể gặp phải những khác biệt văn hóa làm thách thức những quan niệm vốn có của họ về giao tiếp và hành vi xã hội.","audioKind":"ex2"}],"collocations":[{"en":"encounter difficulties","vi":"gặp khó khăn"},{"en":"encounter resistance","vi":"gặp phải sự kháng cự"},{"en":"a chance encounter","vi":"một cuộc tình cờ gặp gỡ"},{"en":"an encounter with","vi":"cuộc gặp gỡ với"}],"wordFamily":[],"synonyms":["meet","come across"],"antonyms":[],"tipVi":"Động từ \"encounter\" có thể đi trực tiếp với tân ngữ; danh từ thường dùng cụm \"an encounter with\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_faithfully', 'en-b2-10', 'faithfully', '/ˈfeɪθfəli/', 'B2', 'trung thành; tận tụy; trung thực; chính xác sát bản gốc', 'adv.', 'faithful (adj.), faithfulness (n.), faith (n.)', 'Đồng nghĩa: loyally, accurately · Trái nghĩa: unfaithfully', 'Trong thư tín thương mại tiếng Anh, khi không biết rõ tên người nhận, người ta thường dùng cụm "Yours faithfully".', 'Our dog waited faithfully beside the door every evening.', NULL, 'Chú chó của chúng tôi vẫn trung thành ngồi chờ ngoài cửa vào mỗi buổi tối.', '{"wordId":"faithfully","ukIpa":"/ˈfeɪθfəli/","usIpa":"/ˈfeɪθfəli/","cefr":"B2","topic":"society","senses":[{"pos":"adv.","en":"with continuing loyalty or commitment","vi":"trung thành; tận tụy"},{"pos":"adv.","en":"in a way that accurately matches the original","vi":"trung thực; chính xác sát bản gốc"}],"examples":[{"en":"Our dog waited faithfully beside the door every evening.","vi":"Chú chó của chúng tôi vẫn trung thành ngồi chờ ngoài cửa vào mỗi buổi tối.","audioKind":"ex"},{"en":"Museum restorers aim to reproduce historical colours faithfully while preserving as much original material as possible.","vi":"Các chuyên gia phục chế bảo tàng hướng tới việc tái hiện chính xác các màu sắc lịch sử đồng thời bảo tồn nguyên vẹn tối đa chất liệu ban đầu.","audioKind":"ex2"}],"collocations":[{"en":"serve faithfully","vi":"tận tuỵ phục vụ"},{"en":"reproduce faithfully","vi":"tái hiện trung thực"},{"en":"Yours faithfully","vi":"Kính thư (dùng cuối thư trang trọng)"}],"wordFamily":["faithful (adj.)","faithfulness (n.)","faith (n.)"],"synonyms":["loyally","accurately"],"antonyms":["unfaithfully"],"tipVi":"Trong thư tín thương mại tiếng Anh, khi không biết rõ tên người nhận, người ta thường dùng cụm \"Yours faithfully\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clash', 'en-b2-10', 'clash', '/klæʃ/', 'B2', 'sự xung đột; sự trùng lịch; xung đột; mâu thuẫn; không đồng điệu (màu sắc); tiếng leng keng (của kim loại va chạm)', 'n.', NULL, 'Đồng nghĩa: conflict, disagreement · Trái nghĩa: harmony', 'Cụm clash with có thể dùng để chỉ xung đột thời gian, bất đồng quan điểm hoặc màu sắc không hợp nhau.', 'My dentist appointment clashes with our weekly team meeting.', NULL, 'Lịch hẹn nha sĩ của tôi trùng với cuộc họp đội hàng tuần.', '{"wordId":"clash","ukIpa":"/klæʃ/","usIpa":"/klæʃ/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"A conflict between people, ideas, or scheduled events.","vi":"sự xung đột; sự trùng lịch"},{"pos":"v.","en":"To conflict, occur simultaneously, or look unpleasant together.","vi":"xung đột; mâu thuẫn; không đồng điệu (màu sắc)"},{"pos":"n.","en":"A loud ringing sound made when metal objects strike together.","vi":"tiếng leng keng (của kim loại va chạm)"}],"examples":[{"en":"My dentist appointment clashes with our weekly team meeting.","vi":"Lịch hẹn nha sĩ của tôi trùng với cuộc họp đội hàng tuần.","audioKind":"ex"},{"en":"A clash between economic priorities and environmental goals can delay decisions about major infrastructure projects.","vi":"Sự xung đột giữa các ưu tiên kinh tế và các mục tiêu môi trường có thể làm trì hoãn các quyết định về các dự án cơ sở hạ tầng lớn.","audioKind":"ex2"}],"collocations":[{"en":"a clash of interests","vi":"sự xung đột lợi ích"},{"en":"clash with","vi":"mâu thuẫn với"},{"en":"a scheduling clash","vi":"sự trùng lịch"},{"en":"a clash of cymbals","vi":"tiếng chập cheng va chạm"}],"wordFamily":[],"synonyms":["conflict","disagreement"],"antonyms":["harmony"],"tipVi":"Cụm clash with có thể dùng để chỉ xung đột thời gian, bất đồng quan điểm hoặc màu sắc không hợp nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_behalf', 'en-b2-10', 'behalf', '/bɪˈhæf/', 'B2', 'sự thay mặt, đại diện hoặc vì lợi ích của ai đó', 'n.', NULL, NULL, 'Thường được sử dụng trong các cụm từ "on behalf of" hoặc "on someone''s behalf".', 'I accepted the prize on behalf of my sister.', NULL, 'Tôi đã nhận giải thưởng thay cho chị gái mình.', '{"wordId":"behalf","ukIpa":"/bɪˈhɑːf/","usIpa":"/bɪˈhæf/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"Used in phrases meaning representing someone or supporting their interests.","vi":"sự thay mặt, đại diện hoặc vì lợi ích của ai đó"}],"examples":[{"en":"I accepted the prize on behalf of my sister.","vi":"Tôi đã nhận giải thưởng thay cho chị gái mình.","audioKind":"ex"},{"en":"Community organisations often speak on behalf of residents who struggle to make their concerns heard.","vi":"Các tổ chức cộng đồng thường lên tiếng thay cho những cư dân gặp khó khăn trong việc đưa tiếng nói và mối quan tâm của họ đến với cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"on behalf of someone","vi":"thay mặt cho ai đó"},{"en":"on someone''s behalf","vi":"vì lợi ích của ai đó"},{"en":"act on behalf of","vi":"hành động thay mặt cho"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường được sử dụng trong các cụm từ \"on behalf of\" hoặc \"on someone''s behalf\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lottery', 'en-b2-10', 'lottery', '/ˈlɑːtəri/', 'B2', 'xổ số; vé số; sự việc may rủi; trò may rủi', 'n.', NULL, NULL, 'by lottery có nghĩa là thông qua việc bốc thăm ngẫu nhiên, không nhất thiết phải liên quan đến việc mua vé số.', 'My uncle bought a lottery ticket at the shop.', NULL, 'Chú tôi đã mua một tờ vé số ở cửa hàng.', '{"wordId":"lottery","ukIpa":"/ˈlɒtəri/","usIpa":"/ˈlɑːtəri/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"a game where randomly chosen tickets win prizes","vi":"xổ số; vé số"},{"pos":"n.","en":"a selection process or situation whose outcome depends on chance","vi":"sự việc may rủi; trò may rủi"}],"examples":[{"en":"My uncle bought a lottery ticket at the shop.","vi":"Chú tôi đã mua một tờ vé số ở cửa hàng.","audioKind":"ex"},{"en":"Allocating school places by lottery may reduce favouritism, but it can also create uncertainty for families.","vi":"Việc phân bổ suất học bằng hình thức bốc thăm có thể hạn chế sự thiên vị, nhưng đồng thời cũng tạo ra sự bấp bênh cho các gia đình.","audioKind":"ex2"}],"collocations":[{"en":"a lottery ticket","vi":"một tờ vé số"},{"en":"win the lottery","vi":"trúng số"},{"en":"a lottery draw","vi":"buổi quay số trúng thưởng"},{"en":"by lottery","vi":"bằng hình thức bốc thăm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"by lottery có nghĩa là thông qua việc bốc thăm ngẫu nhiên, không nhất thiết phải liên quan đến việc mua vé số.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_privilege', 'en-b2-10', 'privilege', '/ˈprɪvəlɪdʒ/', 'B2', 'đặc quyền; sự ưu đãi đặc biệt; vinh dự; niềm vinh hạnh', 'n.', 'privileged (adj.), underprivileged (adj.)', 'Đồng nghĩa: advantage, honour', 'Để diễn tả niềm vinh hạnh làm gì, thường dùng cấu trúc have the privilege of doing.', 'Having the whole garden to myself felt like a privilege.', NULL, 'Được sở hữu toàn bộ khu vườn một mình mang lại cảm giác như một sự ưu ái đặc biệt.', '{"wordId":"privilege","ukIpa":"/ˈprɪvəlɪdʒ/","usIpa":"/ˈprɪvəlɪdʒ/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"A special right or advantage available only to certain people.","vi":"đặc quyền; sự ưu đãi đặc biệt"},{"pos":"n.","en":"An opportunity to do something regarded as a special honour.","vi":"vinh dự; niềm vinh hạnh"}],"examples":[{"en":"Having the whole garden to myself felt like a privilege.","vi":"Được sở hữu toàn bộ khu vườn một mình mang lại cảm giác như một sự ưu ái đặc biệt.","audioKind":"ex"},{"en":"Access to quality education should be a universal right rather than a privilege reserved for wealthy families.","vi":"Việc tiếp cận nền giáo dục chất lượng nên là quyền lợi phổ quát của mọi người thay vì là đặc quyền chỉ dành riêng cho các gia đình giàu có.","audioKind":"ex2"}],"collocations":[{"en":"enjoy a privilege","vi":"hưởng đặc quyền"},{"en":"a rare privilege","vi":"một vinh dự hiếm có"},{"en":"have the privilege of","vi":"có vinh dự được..."},{"en":"class privilege","vi":"đặc quyền giai cấp"}],"wordFamily":["privileged (adj.)","underprivileged (adj.)"],"synonyms":["advantage","honour"],"antonyms":[],"tipVi":"Để diễn tả niềm vinh hạnh làm gì, thường dùng cấu trúc have the privilege of doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_controversial', 'en-b2-10', 'controversial', '/ˌkɑːntrəˈvɜːrʃəl/', 'B2', 'gây tranh cãi; có nhiều ý kiến trái chiều', 'adj.', 'controversy (n.), controversially (adv.), uncontroversial (adj.)', 'Đồng nghĩa: contentious, disputed · Trái nghĩa: uncontroversial', 'Biểu thị việc gây ra bất đồng, không có nghĩa là sai trái hay không được chào đón.', 'The controversial parking rules divided our usually friendly neighbours.', NULL, 'Quy định đậu xe gây tranh cãi đã làm chia rẽ những người hàng xóm vốn thân thiện của chúng tôi.', '{"wordId":"controversial","ukIpa":"/ˌkɒntrəˈvɜːʃəl/","usIpa":"/ˌkɑːntrəˈvɜːrʃəl/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"causing strong disagreement or public debate","vi":"gây tranh cãi; có nhiều ý kiến trái chiều"}],"examples":[{"en":"The controversial parking rules divided our usually friendly neighbours.","vi":"Quy định đậu xe gây tranh cãi đã làm chia rẽ những người hàng xóm vốn thân thiện của chúng tôi.","audioKind":"ex"},{"en":"Charging drivers to enter city centres remains controversial, although it can reduce congestion and improve air quality.","vi":"Việc thu phí các tài xế đi vào trung tâm thành phố vẫn là một vấn đề gây tranh cãi, mặc dù nó có thể làm giảm tình trạng tắc nghẽn và cải thiện chất lượng không khí.","audioKind":"ex2"}],"collocations":[{"en":"a controversial issue","vi":"một vấn đề gây tranh cãi"},{"en":"a controversial decision","vi":"một quyết định gây tranh cãi"},{"en":"highly controversial","vi":"hết sức gây tranh cãi"}],"wordFamily":["controversy (n.)","controversially (adv.)","uncontroversial (adj.)"],"synonyms":["contentious","disputed"],"antonyms":["uncontroversial"],"tipVi":"Biểu thị việc gây ra bất đồng, không có nghĩa là sai trái hay không được chào đón.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_insufficient', 'en-b2-10', 'insufficient', '/ˌɪnsəˈfɪʃənt/', 'B2', 'không đủ; không đáp ứng đủ', 'adj.', 'insufficiently (adv.), insufficiency (n.), sufficient (adj.), sufficiency (n.)', 'Đồng nghĩa: inadequate · Trái nghĩa: sufficient, adequate', 'Mang tính trang trọng hơn; thường dùng insufficient for hoặc insufficient to do.', 'We had insufficient paint to finish the kitchen walls.', NULL, 'Chúng tôi không có đủ sơn để hoàn thành các bức tường trong bếp.', '{"wordId":"insufficient","ukIpa":"/ˌɪnsəˈfɪʃənt/","usIpa":"/ˌɪnsəˈfɪʃənt/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"not enough for a particular need or purpose","vi":"không đủ; không đáp ứng đủ"}],"examples":[{"en":"We had insufficient paint to finish the kitchen walls.","vi":"Chúng tôi không có đủ sơn để hoàn thành các bức tường trong bếp.","audioKind":"ex"},{"en":"Insufficient funding prevents many rural schools from providing students with reliable internet access and modern learning materials.","vi":"Nguồn vốn không đủ khiến nhiều trường học vùng sâu vùng xa không thể cung cấp cho học sinh kết nối internet đáng tin cậy và tài liệu học tập hiện đại.","audioKind":"ex2"}],"collocations":[{"en":"insufficient funds","vi":"kinh phí không đủ"},{"en":"insufficient evidence","vi":"không đủ bằng chứng"},{"en":"insufficient to meet demand","vi":"không đủ để đáp ứng nhu cầu"}],"wordFamily":["insufficiently (adv.)","insufficiency (n.)","sufficient (adj.)","sufficiency (n.)"],"synonyms":["inadequate"],"antonyms":["sufficient","adequate"],"tipVi":"Mang tính trang trọng hơn; thường dùng insufficient for hoặc insufficient to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_honor', 'en-b2-10', 'honor', '/ˈɑːnər/', 'B2', 'vinh dự; sự kính trọng; tôn vinh; tỏ lòng kính trọng; thực hiện; giữ lời (cam kết)', 'n.', 'honorable (adj.), honorary (adj.), honored (adj.)', 'Đồng nghĩa: respect, esteem · Trái nghĩa: dishonor', 'Cách viết theo kiểu Mỹ; kiểu Anh là honour, chữ h câm.', 'Our neighbors held a dinner in honor of my grandmother.', NULL, 'Những người hàng xóm đã tổ chức một bữa tối để tỏ lòng kính trọng đối với bà tôi.', '{"wordId":"honor","ukIpa":"/ˈɒnə/","usIpa":"/ˈɑːnər/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"great respect or recognition for someone''s qualities or achievements","vi":"vinh dự; sự kính trọng"},{"pos":"v.","en":"show respect or give public recognition to someone","vi":"tôn vinh; tỏ lòng kính trọng"},{"pos":"v.","en":"do what a promise or agreement requires","vi":"thực hiện; giữ lời (cam kết)"}],"examples":[{"en":"Our neighbors held a dinner in honor of my grandmother.","vi":"Những người hàng xóm đã tổ chức một bữa tối để tỏ lòng kính trọng đối với bà tôi.","audioKind":"ex"},{"en":"Governments should honor their commitments to protect vulnerable communities when introducing major economic reforms.","vi":"Chính phủ nên thực hiện các cam kết bảo vệ các cộng đồng dễ bị tổn thương khi tiến hành các cải cách kinh tế lớn.","audioKind":"ex2"}],"collocations":[{"en":"in honor of","vi":"để tưởng nhớ; nhằm vinh danh"},{"en":"a great honor","vi":"một vinh dự lớn"},{"en":"honor a commitment","vi":"thực hiện cam kết"},{"en":"guest of honor","vi":"khách mời danh dự"}],"wordFamily":["honorable (adj.)","honorary (adj.)","honored (adj.)"],"synonyms":["respect","esteem"],"antonyms":["dishonor"],"tipVi":"Cách viết theo kiểu Mỹ; kiểu Anh là honour, chữ h câm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_status', 'en-b2-10', 'status', '/ˈsteɪtəs/', 'B2', 'địa vị xã hội; thân phận; tình trạng; trạng thái', 'n.', NULL, NULL, 'Có thể chỉ địa vị xã hội hoặc tình trạng hiện tại, cần chú ý ngữ cảnh.', 'Her new role gave her higher status at work.', NULL, 'Vai trò mới đã mang lại cho cô ấy địa vị cao hơn trong công việc.', '{"wordId":"status","ukIpa":"/ˈsteɪtəs/","usIpa":"/ˈsteɪtəs/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"A person''s social position or standing within a group.","vi":"địa vị xã hội; thân phận"},{"pos":"n.","en":"The current condition or situation of someone or something.","vi":"tình trạng; trạng thái"}],"examples":[{"en":"Her new role gave her higher status at work.","vi":"Vai trò mới đã mang lại cho cô ấy địa vị cao hơn trong công việc.","audioKind":"ex"},{"en":"Access to quality healthcare should depend on medical need rather than a person''s economic status.","vi":"Việc tiếp cận dịch vụ y tế chất lượng nên phụ thuộc vào nhu cầu y tế chứ không phải địa vị kinh tế của một cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"social status","vi":"địa vị xã hội"},{"en":"marital status","vi":"tình trạng hôn nhân"},{"en":"current status","vi":"trạng thái hiện tại"},{"en":"status symbol","vi":"biểu tượng địa vị"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Có thể chỉ địa vị xã hội hoặc tình trạng hiện tại, cần chú ý ngữ cảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_welfare', 'en-b2-10', 'welfare', '/ˈwelfer/', 'B2', 'hạnh phúc; sự an sinh; phúc lợi; phúc lợi xã hội; tiền trợ cấp', 'n.', NULL, 'Đồng nghĩa: well-being', 'Là danh từ không đếm được; khi làm từ bổ nghĩa đứng trước thì vẫn giữ nguyên là danh từ.', 'The shelter puts the welfare of its animals first.', NULL, 'Trung tâm cứu trợ đặt sự an sinh của các loài động vật lên hàng đầu.', '{"wordId":"welfare","ukIpa":"/ˈwelfeə/","usIpa":"/ˈwelfer/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"The health, happiness, and good living conditions of people.","vi":"hạnh phúc; sự an sinh; phúc lợi"},{"pos":"n.","en":"Public support for people who need money or care.","vi":"phúc lợi xã hội; tiền trợ cấp"}],"examples":[{"en":"The shelter puts the welfare of its animals first.","vi":"Trung tâm cứu trợ đặt sự an sinh của các loài động vật lên hàng đầu.","audioKind":"ex"},{"en":"Governments should protect children''s welfare by ensuring access to nutritious food and safe housing.","vi":"Chính phủ nên bảo vệ phúc lợi của trẻ em bằng cách đảm bảo quyền tiếp cận thực phẩm bổ dưỡng và nhà ở an toàn.","audioKind":"ex2"}],"collocations":[{"en":"animal welfare","vi":"phúc lợi động vật"},{"en":"social welfare","vi":"phúc lợi xã hội"},{"en":"welfare benefits","vi":"tiền trợ cấp phúc lợi"}],"wordFamily":[],"synonyms":["well-being"],"antonyms":[],"tipVi":"Là danh từ không đếm được; khi làm từ bổ nghĩa đứng trước thì vẫn giữ nguyên là danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_offensive', 'en-b2-10', 'offensive', '/əˈfensɪv/', 'B2', 'xúc phạm; lăng mạ; gây khó chịu; mang tính tấn công; để tấn công; cuộc tấn công; chiến dịch tấn công', 'adj.', 'offend (v.), offence (n.), offensively (adv.)', 'Đồng nghĩa: insulting, objectionable · Trái nghĩa: inoffensive, defensive', 'Diễn tả cảm giác bị xúc phạm dùng offended, không dùng offensive.', 'He apologised when he realised his joke was offensive.', NULL, 'Anh ấy đã xin lỗi khi nhận ra trò đùa của mình mang tính xúc phạm.', '{"wordId":"offensive","ukIpa":"/əˈfensɪv/","usIpa":"/əˈfensɪv/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Causing people to feel insulted, upset, or disgusted.","vi":"xúc phạm; lăng mạ; gây khó chịu"},{"pos":"adj.","en":"Intended or used for attacking rather than defending.","vi":"mang tính tấn công; để tấn công"},{"pos":"n.","en":"An organized attack or campaign to achieve a goal.","vi":"cuộc tấn công; chiến dịch tấn công"}],"examples":[{"en":"He apologised when he realised his joke was offensive.","vi":"Anh ấy đã xin lỗi khi nhận ra trò đùa của mình mang tính xúc phạm.","audioKind":"ex"},{"en":"Schools should address offensive behaviour promptly while helping students understand why their words can hurt others.","vi":"Nhà trường nên xử lý kịp thời các hành vi xúc phạm đồng thời giúp học sinh hiểu lý do tại sao lời nói của các em có thể làm tổn thương người khác.","audioKind":"ex2"}],"collocations":[{"en":"offensive language","vi":"ngôn từ xúc phạm"},{"en":"find something offensive","vi":"cảm thấy chướng tai gai mắt; thấy phản cảm"},{"en":"offensive tactics","vi":"chiến thuật tấn công"},{"en":"launch an offensive","vi":"phát động một cuộc tấn công"}],"wordFamily":["offend (v.)","offence (n.)","offensively (adv.)"],"synonyms":["insulting","objectionable"],"antonyms":["inoffensive","defensive"],"tipVi":"Diễn tả cảm giác bị xúc phạm dùng offended, không dùng offensive.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_10_1', 'en-b2-10', 'Cách dùng “faithfully” (adv.) — trung thành; tận tụy', 'serve faithfully  ·  reproduce faithfully  ·  Yours faithfully', 'Trong thư tín thương mại tiếng Anh, khi không biết rõ tên người nhận, người ta thường dùng cụm "Yours faithfully".', 'Họ từ (Word Family): faithful (adj.), faithfulness (n.), faith (n.) | Đồng nghĩa: loyally, accurately · Trái nghĩa: unfaithfully', '[{"hanzi":"Our dog waited faithfully beside the door every evening.","pinyin":"","meaning":"Chú chó của chúng tôi vẫn trung thành ngồi chờ ngoài cửa vào mỗi buổi tối."},{"hanzi":"Museum restorers aim to reproduce historical colours faithfully while preserving as much original material as possible.","pinyin":"","meaning":"Các chuyên gia phục chế bảo tàng hướng tới việc tái hiện chính xác các màu sắc lịch sử đồng thời bảo tồn nguyên vẹn tối đa chất liệu ban đầu."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_10_2', 'en-b2-10', 'Cách dùng “lottery” (n.) — xổ số; vé số', 'a lottery ticket  ·  win the lottery  ·  a lottery draw', 'by lottery có nghĩa là thông qua việc bốc thăm ngẫu nhiên, không nhất thiết phải liên quan đến việc mua vé số.', NULL, '[{"hanzi":"My uncle bought a lottery ticket at the shop.","pinyin":"","meaning":"Chú tôi đã mua một tờ vé số ở cửa hàng."},{"hanzi":"Allocating school places by lottery may reduce favouritism, but it can also create uncertainty for families.","pinyin":"","meaning":"Việc phân bổ suất học bằng hình thức bốc thăm có thể hạn chế sự thiên vị, nhưng đồng thời cũng tạo ra sự bấp bênh cho các gia đình."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_10_3', 'en-b2-10', 'Cách dùng “adapt” (v.) — thích nghi; làm cho thích ứng', 'adapt to change  ·  adapt teaching methods  ·  adapt a novel for television', '"adapt to" đi với danh từ hoặc danh động từ (V-ing); tránh nhầm lẫn với "adopt" (áp dụng, nhận nuôi).', 'Họ từ (Word Family): adaptation (n.), adaptable (adj.), adaptability (n.), adaptive (adj.) | Đồng nghĩa: adjust, modify', '[{"hanzi":"Our cat quickly adapted to life in the new flat.","pinyin":"","meaning":"Con mèo của chúng tôi nhanh chóng thích nghi với cuộc sống ở căn hộ mới."},{"hanzi":"Schools must adapt their teaching methods to meet the needs of students from diverse cultural backgrounds.","pinyin":"","meaning":"Nhà trường phải điều chỉnh phương pháp giảng dạy để đáp ứng nhu cầu của học sinh đến từ các nền văn hóa đa dạng."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_10_4', 'en-b2-10', 'Cách dùng “clash” (n.) — sự xung đột; sự trùng lịch', 'a clash of interests  ·  clash with  ·  a scheduling clash', 'Cụm clash with có thể dùng để chỉ xung đột thời gian, bất đồng quan điểm hoặc màu sắc không hợp nhau.', 'Đồng nghĩa: conflict, disagreement · Trái nghĩa: harmony', '[{"hanzi":"My dentist appointment clashes with our weekly team meeting.","pinyin":"","meaning":"Lịch hẹn nha sĩ của tôi trùng với cuộc họp đội hàng tuần."},{"hanzi":"A clash between economic priorities and environmental goals can delay decisions about major infrastructure projects.","pinyin":"","meaning":"Sự xung đột giữa các ưu tiên kinh tế và các mục tiêu môi trường có thể làm trì hoãn các quyết định về các dự án cơ sở hạ tầng lớn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_10_1', 'en-b2-10', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_10_1_1', 'ten_b2_10_1', 'oppose', 'Our neighbours oppose building a road through the park.', 'Our neighbours oppose building a road through the park.', '/əˈpoʊz/', 'Những người hàng xóm của chúng tôi phản đối việc xây dựng con đường đi xuyên qua công viên.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_10_1_2', 'ten_b2_10_1', 'patrol', 'Two guards patrol the park after dark each evening.', 'Two guards patrol the park after dark each evening.', '/pəˈtroʊl/', 'Hai bảo vệ đi tuần tra quanh công viên vào mỗi buổi tối sau khi trời tối.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_10_1_3', 'ten_b2_10_1', 'immoral', 'She thought keeping the lost wallet would be immoral.', 'She thought keeping the lost wallet would be immoral.', '/ɪˈmɔːrəl/', 'Cô ấy nghĩ rằng việc giữ lại chiếc ví nhặt được là hành vi trái đạo đức.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_10_1_4', 'ten_b2_10_1', 'participation', 'Your participation made our neighbourhood clean-up much more enjoyable.', 'Your participation made our neighbourhood clean-up much more enjoyable.', '/pɑːrˌtɪsəˈpeɪʃən/', 'Sự tham gia của bạn đã giúp hoạt động dọn dẹp khu phố của chúng ta vui vẻ hơn rất nhiều.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_10_1_5', 'ten_b2_10_1', 'inherit', 'Leila inherited a small cottage from her grandmother.', 'Leila inherited a small cottage from her grandmother.', '/ɪnˈherɪt/', 'Leila đã thừa kế một ngôi nhà nhỏ từ bà của mình.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_10_1_6', 'ten_b2_10_1', 'spy', 'I spied a tiny kitten hiding behind the flowerpot.', 'I spied a tiny kitten hiding behind the flowerpot.', '/spaɪ/', 'Tôi thoáng thấy một chú mèo con đang trốn sau chậu hoa.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_10_1_7', 'ten_b2_10_1', 'hostage', 'The hostage returned home safely and hugged her family.', 'The hostage returned home safely and hugged her family.', '/ˈhɑːstɪdʒ/', 'Nữ con tin đã trở về nhà an toàn và ôm lấy gia đình mình.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_10_1_8', 'ten_b2_10_1', 'commit', 'The police arrested someone who had committed a burglary.', 'The police arrested someone who had committed a burglary.', '/kəˈmɪt/', 'Cảnh sát đã bắt giữ một người phạm tội trộm cắp.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_10_1_1', 'en-b2-10', 'ten_b2_10_1', 'listening', 'listening', 'Our neighbours oppose building a road through the park.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy nghĩ rằng việc giữ lại chiếc ví nhặt được là hành vi trái đạo đức.","Lòng tốt của cô ấy được thể hiện khi cô chia sẻ chiếc bánh mì cuối cùng của mình.","Những người hàng xóm của chúng tôi phản đối việc xây dựng con đường đi xuyên qua công viên.","Leila đã thừa kế một ngôi nhà nhỏ từ bà của mình."]'::jsonb, 2, 'Our neighbours oppose building a road through the park. → Những người hàng xóm của chúng tôi phản đối việc xây dựng con đường đi xuyên qua công viên.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_10_1_2', 'en-b2-10', 'ten_b2_10_1', 'listening', 'listening', 'Two guards patrol the park after dark each evening.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Quy định đậu xe gây tranh cãi đã làm chia rẽ những người hàng xóm vốn thân thiện của chúng tôi.","Hai bảo vệ đi tuần tra quanh công viên vào mỗi buổi tối sau khi trời tối.","Cảnh sát đã bắt giữ một người phạm tội trộm cắp.","Những người hàng xóm của chúng tôi phản đối việc xây dựng con đường đi xuyên qua công viên."]'::jsonb, 1, 'Two guards patrol the park after dark each evening. → Hai bảo vệ đi tuần tra quanh công viên vào mỗi buổi tối sau khi trời tối.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_10_1_3', 'en-b2-10', 'ten_b2_10_1', 'listening', 'listening', 'She thought keeping the lost wallet would be immoral.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy nghĩ rằng việc giữ lại chiếc ví nhặt được là hành vi trái đạo đức.","Cảnh sát đã bắt giữ một người phạm tội trộm cắp.","Anh ấy đã xin lỗi khi nhận ra trò đùa của mình mang tính xúc phạm.","Chúng tôi không có đủ sơn để hoàn thành các bức tường trong bếp."]'::jsonb, 0, 'She thought keeping the lost wallet would be immoral. → Cô ấy nghĩ rằng việc giữ lại chiếc ví nhặt được là hành vi trái đạo đức.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_10_2', 'en-b2-10', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_10_2_1', 'ten_b2_10_2', 'oppose', 'Many residents oppose airport expansion because they fear increased noise and damage to local wildlife habitats.', 'Many residents oppose airport expansion because they fear increased noise and damage to local wildlife habitats.', '/əˈpoʊz/', 'Nhiều cư dân phản đối việc mở rộng sân bay vì họ lo ngại tiếng ồn gia tăng và tổn hại đến môi trường sống của động vật hoang dã địa phương.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_10_2_2', 'ten_b2_10_2', 'patrol', 'Rangers patrol protected forests to prevent illegal logging and monitor threats to endangered wildlife.', 'Rangers patrol protected forests to prevent illegal logging and monitor threats to endangered wildlife.', '/pəˈtroʊl/', 'Các kiểm lâm viên tuần tra các khu rừng được bảo vệ để ngăn chặn tình trạng chặt phá rừng trái phép và theo dõi các mối đe dọa đối với động vật hoang dã có nguy cơ tuyệt chủng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_10_2_3', 'ten_b2_10_2', 'immoral', 'Many consumers consider it immoral for companies to exploit vulnerable workers in pursuit of higher profits.', 'Many consumers consider it immoral for companies to exploit vulnerable workers in pursuit of higher profits.', '/ɪˈmɔːrəl/', 'Nhiều người tiêu dùng cho rằng việc các doanh nghiệp bóc lột lao động dễ bị tổn thương để chuộc lợi cao là điều trái đạo đức.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_10_2_4', 'ten_b2_10_2', 'participation', 'Active participation in community projects can strengthen social connections and give residents a greater sense of belonging.', 'Active participation in community projects can strengthen social connections and give residents a greater sense of belonging.', '/pɑːrˌtɪsəˈpeɪʃən/', 'Việc tham gia tích cực vào các dự án cộng đồng có thể củng cố các mối quan hệ xã hội và mang lại cho cư dân cảm giác thuộc về lớn hơn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_10_2_5', 'ten_b2_10_2', 'inherit', 'Future generations may inherit serious environmental problems unless governments take decisive action to reduce pollution.', 'Future generations may inherit serious environmental problems unless governments take decisive action to reduce pollution.', '/ɪnˈherɪt/', 'Các thế hệ tương lai có thể phải gánh chịu những vấn đề môi trường nghiêm trọng nếu chính phủ không có hành động quyết liệt để giảm thiểu ô nhiễm.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_10_2_6', 'ten_b2_10_2', 'spy', 'Many users worry that connected devices could spy on their activities without permission.', 'Many users worry that connected devices could spy on their activities without permission.', '/spaɪ/', 'Nhiều người dùng lo ngại rằng các thiết bị kết nối có thể theo dõi hoạt động của họ mà không có sự cho phép.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_10_2_1', 'en-b2-10', 'ten_b2_10_2', 'listening', 'listening', 'Many residents oppose airport expansion because they fear increased noise and damage to local wildlife habitats.', NULL, 'Trong câu vừa nghe, từ “oppose” mang nghĩa nào sau đây?', '["chắc chắn; có khả năng cao","động từ: phản đối; chống lại","danh tiếng, uy tín, tiếng tăm","đóng góp; góp phần"]'::jsonb, 1, '“oppose” (/əˈpoʊz/): động từ: phản đối; chống lại. Câu đầy đủ: Many residents oppose airport expansion because they fear increased noise and damage to local wildlife habitats.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_10_2_2', 'en-b2-10', 'ten_b2_10_2', 'listening', 'listening', 'Rangers patrol protected forests to prevent illegal logging and monitor threats to endangered wildlife.', NULL, 'Trong câu vừa nghe, từ “patrol” mang nghĩa nào sau đây?', '["tuần tra; kiểm tra","tiêm phòng; tiêm chủng vaccine","sự ước tính; sự đánh giá","một phần; phần nào; không hoàn toàn"]'::jsonb, 0, '“patrol” (/pəˈtroʊl/): tuần tra; kiểm tra. Câu đầy đủ: Rangers patrol protected forests to prevent illegal logging and monitor threats to endangered wildlife.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
