INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_10_2', 'en-b2-10', NULL, 'comprehensive_test', 'listening', 'Two guards patrol the park after dark each evening.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tình bạn của chúng tôi lớn dần qua sự tin tưởng lẫn nhau và những cuộc trò chuyện chân thành.","Hai bảo vệ đi tuần tra quanh công viên vào mỗi buổi tối sau khi trời tối.","Leila đã thừa kế một ngôi nhà nhỏ từ bà của mình.","Cô ấy nghĩ rằng việc giữ lại chiếc ví nhặt được là hành vi trái đạo đức."]'::jsonb, 1, 'Two guards patrol the park after dark each evening. → Hai bảo vệ đi tuần tra quanh công viên vào mỗi buổi tối sau khi trời tối.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_10_3', 'en-b2-10', NULL, 'comprehensive_test', 'listening', 'immoral', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["phòng trưng bày; showroom","lớn tuổi hơn (thường trong cùng gia đình)","phản hồi; ý kiến đóng góp","trái đạo đức; đồi phong bại tục; bất chính"]'::jsonb, 3, 'immoral (/ɪˈmɔːrəl/) → trái đạo đức; đồi phong bại tục; bất chính', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_10_4', 'en-b2-10', NULL, 'comprehensive_test', 'listening', 'Your participation made our neighbourhood clean-up much more enjoyable.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Con mèo của chúng tôi nhanh chóng thích nghi với cuộc sống ở căn hộ mới.","Vai trò mới đã mang lại cho cô ấy địa vị cao hơn trong công việc.","Sự tham gia của bạn đã giúp hoạt động dọn dẹp khu phố của chúng ta vui vẻ hơn rất nhiều.","Chú tôi rất bảo thủ và không thích thay đổi các truyền thống của gia đình."]'::jsonb, 2, 'Your participation made our neighbourhood clean-up much more enjoyable. → Sự tham gia của bạn đã giúp hoạt động dọn dẹp khu phố của chúng ta vui vẻ hơn rất nhiều.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_10_5', 'en-b2-10', NULL, 'comprehensive_test', 'listening', 'inherit', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bản tin; thông báo chính thức ngắn gọn về tin tức mới nhất","thừa kế (tài sản)","tư duy theo nhóm; động não; thảo luận tìm ý tưởng","tổng, trước thuế; gộp"]'::jsonb, 1, 'inherit (/ɪnˈherɪt/) → thừa kế (tài sản); di truyền (đặc điểm từ cha mẹ); tiếp quản; gánh chịu (trách nhiệm, vấn đề)', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_10_6', 'en-b2-10', NULL, 'comprehensive_test', 'listening', 'I spied a tiny kitten hiding behind the flowerpot.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Con mèo của chúng tôi nhanh chóng thích nghi với cuộc sống ở căn hộ mới.","Chúng tôi không có đủ sơn để hoàn thành các bức tường trong bếp.","Tôi thoáng thấy một chú mèo con đang trốn sau chậu hoa.","Lòng tốt của cô ấy được thể hiện khi cô chia sẻ chiếc bánh mì cuối cùng của mình."]'::jsonb, 2, 'I spied a tiny kitten hiding behind the flowerpot. → Tôi thoáng thấy một chú mèo con đang trốn sau chậu hoa.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_10_7', 'en-b2-10', NULL, 'comprehensive_test', 'listening', 'hostage', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nước cộng hòa; chế độ cộng hòa","lấp lánh; tỏa sáng","có hình tam giác","con tin"]'::jsonb, 3, 'hostage (/ˈhɑːstɪdʒ/) → con tin', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_10_8', 'en-b2-10', NULL, 'comprehensive_test', 'listening', 'The police arrested someone who had committed a burglary.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chú chó của chúng tôi vẫn trung thành ngồi chờ ngoài cửa vào mỗi buổi tối.","Chúng tôi không có đủ sơn để hoàn thành các bức tường trong bếp.","Nữ con tin đã trở về nhà an toàn và ôm lấy gia đình mình.","Cảnh sát đã bắt giữ một người phạm tội trộm cắp."]'::jsonb, 3, 'The police arrested someone who had committed a burglary. → Cảnh sát đã bắt giữ một người phạm tội trộm cắp.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_10_9', 'en-b2-10', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Receive money or property from someone who has died”?', '["inherit","adapt","hostage","spy"]'::jsonb, 0, 'inherit (/ɪnˈherɪt/) → thừa kế (tài sản)', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
