INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_10_18', 'en-b2-10', NULL, 'comprehensive_test', 'reading', NULL, 'Many residents oppose airport expansion because they fear increased noise and damage to local wildlife habitats.', 'Dựa vào câu trên, từ “oppose” có nghĩa phù hợp nhất là gì?', '["dễ vỡ; dễ hỏng","cụ thể; riêng biệt","khoa (trong trường đại học)","động từ: phản đối; chống lại"]'::jsonb, 3, 'oppose: động từ: phản đối; chống lại. Dịch cả câu: Nhiều cư dân phản đối việc mở rộng sân bay vì họ lo ngại tiếng ồn gia tăng và tổn hại đến môi trường sống của động vật hoang dã địa phương.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_10_19', 'en-b2-10', NULL, 'comprehensive_test', 'reading', NULL, 'Rangers patrol protected forests to prevent illegal logging and monitor threats to endangered wildlife.', 'Dựa vào câu trên, từ “patrol” có nghĩa phù hợp nhất là gì?', '["phân bón","tuần tra; kiểm tra","bi thảm; đau thương","cây roi"]'::jsonb, 1, 'patrol: tuần tra; kiểm tra; hoạt động tuần tra; đội tuần tra. Dịch cả câu: Các kiểm lâm viên tuần tra các khu rừng được bảo vệ để ngăn chặn tình trạng chặt phá rừng trái phép và theo dõi các mối đe dọa đối với động vật hoang dã có nguy cơ tuyệt chủng.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_10_20', 'en-b2-10', NULL, 'comprehensive_test', 'reading', NULL, 'Many consumers consider it immoral for companies to exploit vulnerable workers in pursuit of higher profits.', 'Dựa vào câu trên, từ “immoral” có nghĩa phù hợp nhất là gì?', '["trái đạo đức; đồi phong bại tục; bất chính","bạo lực; hung bạo","được đánh giá; được định giá","nhỏ; nhẹ; mong manh; không đáng kể"]'::jsonb, 0, 'immoral: trái đạo đức; đồi phong bại tục; bất chính. Dịch cả câu: Nhiều người tiêu dùng cho rằng việc các doanh nghiệp bóc lột lao động dễ bị tổn thương để chuộc lợi cao là điều trái đạo đức.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_10_21', 'en-b2-10', NULL, 'comprehensive_test', 'reading', NULL, 'Active participation in community projects can strengthen social connections and give residents a greater sense of belonging.', 'Dựa vào câu trên, từ “participation” có nghĩa phù hợp nhất là gì?', '["người mới bắt đầu; người có ít kinh nghiệm","thuộc học tập; thuộc học thuật","cách dùng từ; lời lẽ; văn bản","sự tham gia; sự góp mặt"]'::jsonb, 3, 'participation: sự tham gia; sự góp mặt. Dịch cả câu: Việc tham gia tích cực vào các dự án cộng đồng có thể củng cố các mối quan hệ xã hội và mang lại cho cư dân cảm giác thuộc về lớn hơn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_10_22', 'en-b2-10', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “địa vị xã hội; thân phận”', '["whip","slight","status","vegan"]'::jsonb, 2, 'địa vị xã hội; thân phận → status (/ˈsteɪtəs/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_10_23', 'en-b2-10', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hạnh phúc; sự an sinh; phúc lợi”', '["welfare","spear","insufficient","flexibility"]'::jsonb, 0, 'hạnh phúc; sự an sinh; phúc lợi → welfare (/ˈwelfer/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
