INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-11', 'en', 'Bài 11: Xã hội & Cộng đồng (4) - CEFR B2', 'CEFR B2', 'B2 · Xã hội', '26 từ vựng Tiếng Anh CEFR B2 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4011, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_smuggle', 'en-b2-11', 'smuggle', '/ˈsmʌɡəl/', 'B2', 'vận chuyển trái phép; buôn lậu; lén mang vào', 'v.', 'smuggler (n.), smuggling (n.)', NULL, 'Thường dùng smuggle sth into/out of một nơi nào đó để chỉ việc lén vận chuyển ra vào.', 'Someone tried to smuggle rare birds through the airport.', NULL, 'Ai đó đã cố gắng buôn lậu các loài chim quý hiếm qua sân bay.', '{"wordId":"smuggle","ukIpa":"/ˈsmʌɡəl/","usIpa":"/ˈsmʌɡəl/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"To move goods or people secretly and against the rules.","vi":"vận chuyển trái phép; buôn lậu; lén mang vào"}],"examples":[{"en":"Someone tried to smuggle rare birds through the airport.","vi":"Ai đó đã cố gắng buôn lậu các loài chim quý hiếm qua sân bay.","audioKind":"ex"},{"en":"Stronger international cooperation is needed to stop criminal groups that smuggle endangered animals across national borders.","vi":"Cần tăng cường hợp tác quốc tế để ngăn chặn các băng nhóm tội phạm buôn lậu động vật có nguy cơ tuyệt chủng qua biên giới quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"smuggle goods","vi":"buôn lậu hàng hóa"},{"en":"smuggle something into a country","vi":"lén đưa thứ gì vào một nước"},{"en":"smuggle something across a border","vi":"vận chuyển trái phép vật gì qua biên giới"}],"wordFamily":["smuggler (n.)","smuggling (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng smuggle sth into/out of một nơi nào đó để chỉ việc lén vận chuyển ra vào.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_resolve', 'en-b2-11', 'resolve', '/rɪˈzɑːlv/', 'B2', 'giải quyết; tháo gỡ; kiên quyết; quyết tâm làm gì; sự kiên quyết; lòng quyết tâm', 'v.', 'resolution (n.), resolved (adj.), unresolved (adj.)', 'Đồng nghĩa: settle, determination', '"Resolve a problem" mang nghĩa giải quyết, trong khi "resolve to do" mang nghĩa quyết tâm làm gì.', 'We resolved the argument by taking turns cooking dinner.', NULL, 'Chúng tôi đã giải quyết cuộc cãi vã bằng cách luân phiên nấu bữa tối.', '{"wordId":"resolve","ukIpa":"/rɪˈzɒlv/","usIpa":"/rɪˈzɑːlv/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"To find a satisfactory solution to a problem or disagreement.","vi":"giải quyết; tháo gỡ"},{"pos":"v.","en":"To decide firmly to do something.","vi":"kiên quyết; quyết tâm làm gì"},{"pos":"n.","en":"Strong determination to achieve something.","vi":"sự kiên quyết; lòng quyết tâm"}],"examples":[{"en":"We resolved the argument by taking turns cooking dinner.","vi":"Chúng tôi đã giải quyết cuộc cãi vã bằng cách luân phiên nấu bữa tối.","audioKind":"ex"},{"en":"International cooperation is essential to resolve disputes over shared water resources and prevent future conflicts.","vi":"Hợp tác quốc tế là yếu tố cốt lõi để giải quyết các tranh chấp về nguồn nước chung và ngăn ngừa những xung đột trong tương lai.","audioKind":"ex2"}],"collocations":[{"en":"resolve a dispute","vi":"giải quyết tranh chấp"},{"en":"resolve an issue","vi":"giải quyết vấn đề"},{"en":"resolve to do something","vi":"quyết tâm làm điều gì đó"},{"en":"strengthen someone''s resolve","vi":"củng cố quyết tâm của ai đó"}],"wordFamily":["resolution (n.)","resolved (adj.)","unresolved (adj.)"],"synonyms":["settle","determination"],"antonyms":[],"tipVi":"\"Resolve a problem\" mang nghĩa giải quyết, trong khi \"resolve to do\" mang nghĩa quyết tâm làm gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_manner', 'en-b2-11', 'manner', '/ˈmænər/', 'B2', 'cách thức; phương pháp; thái độ; cách ứng xử; lễ phép; phép lịch sự', 'n.', 'mannered (adj.), mannerism (n.), mannerly (adj.)', NULL, 'Biểu thị "lễ phép, lễ nghi" dùng số nhiều manners.', 'She answered my questions in a calm manner.', NULL, 'Cô ấy đã trả lời các câu hỏi của tôi với một thái độ điềm tĩnh.', '{"wordId":"manner","ukIpa":"/ˈmænə/","usIpa":"/ˈmænər/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"The way something is done or happens.","vi":"cách thức; phương pháp"},{"pos":"n.","en":"The way someone behaves towards other people.","vi":"thái độ; cách ứng xử"},{"pos":"n.","en":"Socially acceptable ways of behaving, usually expressed in the plural.","vi":"lễ phép; phép lịch sự"}],"examples":[{"en":"She answered my questions in a calm manner.","vi":"Cô ấy đã trả lời các câu hỏi của tôi với một thái độ điềm tĩnh.","audioKind":"ex"},{"en":"Schools should teach children to express disagreement in a respectful manner while encouraging independent thinking.","vi":"Nhà trường nên dạy học sinh cách bày tỏ sự bất đồng theo hướng tôn trọng người khác, đồng thời khuyến khích tư duy độc lập.","audioKind":"ex2"}],"collocations":[{"en":"in a professional manner","vi":"làm việc một cách chuyên nghiệp"},{"en":"a friendly manner","vi":"thái độ thân thiện"},{"en":"good manners","vi":"cư xử đúng mực"},{"en":"table manners","vi":"quy tắc ăn uống lịch sự"}],"wordFamily":["mannered (adj.)","mannerism (n.)","mannerly (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Biểu thị \"lễ phép, lễ nghi\" dùng số nhiều manners.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_isolation', 'en-b2-11', 'isolation', '/ˌaɪsəˈleɪʃən/', 'B2', 'sự cô lập; sự tách biệt; sự cách ly', 'n.', 'isolate (v.), isolated (adj.), isolating (adj.)', 'Đồng nghĩa: separation, seclusion · Trái nghĩa: integration', 'in isolation có thể mang nghĩa một mình, hoặc xét theo chiều hướng tách biệt khỏi bối cảnh chung.', 'Weekly visits from neighbours helped reduce her sense of isolation.', NULL, 'Những chuyến thăm hàng tuần từ những người hàng xóm đã giúp làm giảm cảm giác cô đơn của cô ấy.', '{"wordId":"isolation","ukIpa":"/ˌaɪsəˈleɪʃən/","usIpa":"/ˌaɪsəˈleɪʃən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"The state of being separated from other people or places.","vi":"sự cô lập; sự tách biệt"},{"pos":"n.","en":"Keeping someone or something apart to prevent contact or infection.","vi":"sự cách ly"}],"examples":[{"en":"Weekly visits from neighbours helped reduce her sense of isolation.","vi":"Những chuyến thăm hàng tuần từ những người hàng xóm đã giúp làm giảm cảm giác cô đơn của cô ấy.","audioKind":"ex"},{"en":"Investment in community centres may reduce social isolation among older residents who live alone.","vi":"Đầu tư vào các trung tâm cộng đồng có thể làm giảm tình trạng cô lập xã hội ở những cư dân lớn tuổi sống một mình.","audioKind":"ex2"}],"collocations":[{"en":"social isolation","vi":"sự cô lập xã hội"},{"en":"in isolation","vi":"một cách tách biệt; độc lập"},{"en":"isolation ward","vi":"phòng cách ly"},{"en":"a sense of isolation","vi":"cảm giác cô đơn"}],"wordFamily":["isolate (v.)","isolated (adj.)","isolating (adj.)"],"synonyms":["separation","seclusion"],"antonyms":["integration"],"tipVi":"in isolation có thể mang nghĩa một mình, hoặc xét theo chiều hướng tách biệt khỏi bối cảnh chung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_controversy', 'en-b2-11', 'controversy', '/ˈkɑːntrəvɝːsi/', 'B2', 'cuộc tranh cãi; sự bất đồng công khai', 'n.', 'controversial (adj.), controversially (adv.), uncontroversial (adj.)', 'Đồng nghĩa: dispute, disagreement · Trái nghĩa: consensus', 'Thường chỉ sự tranh luận rộng rãi trong công chúng về một vấn đề, không phải là cuộc cãi vã thông thường.', 'The plan to close our pool sparked local controversy.', NULL, 'Kế hoạch đóng cửa hồ bơi của chúng tôi đã châm ngòi cho những tranh cãi tại địa phương.', '{"wordId":"controversy","ukIpa":"/ˈkɒntrəvɜːsi/","usIpa":"/ˈkɑːntrəvɝːsi/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"Strong public disagreement about a particular issue.","vi":"cuộc tranh cãi; sự bất đồng công khai"}],"examples":[{"en":"The plan to close our pool sparked local controversy.","vi":"Kế hoạch đóng cửa hồ bơi của chúng tôi đã châm ngòi cho những tranh cãi tại địa phương.","audioKind":"ex"},{"en":"The use of facial recognition in public spaces has generated controversy over privacy and personal freedom.","vi":"Việc sử dụng công nghệ nhận diện khuôn mặt ở nơi công cộng đã gây ra nhiều tranh cãi về quyền riêng tư và tự do cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"spark controversy","vi":"châm ngòi tranh cãi"},{"en":"controversy over","vi":"tranh cãi về"},{"en":"a subject of controversy","vi":"một chủ đề gây tranh cãi"},{"en":"amid controversy","vi":"trong bối cảnh tranh cãi"}],"wordFamily":["controversial (adj.)","controversially (adv.)","uncontroversial (adj.)"],"synonyms":["dispute","disagreement"],"antonyms":["consensus"],"tipVi":"Thường chỉ sự tranh luận rộng rãi trong công chúng về một vấn đề, không phải là cuộc cãi vã thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conventional', 'en-b2-11', 'conventional', '/kənˈvenʃənəl/', 'B2', 'truyền thống; theo tập quán; thông thường', 'adj.', 'convention (n.), conventionally (adv.), unconventional (adj.)', 'Đồng nghĩa: traditional, standard · Trái nghĩa: unconventional', 'conventional nhấn mạnh sự tuân thủ các quy chuẩn thông thường, không nhất thiết phải có lịch sử lâu đời.', 'We chose a conventional oven instead of a microwave.', NULL, 'Chúng tôi đã chọn lò nướng thông thường thay vì lò vi sóng.', '{"wordId":"conventional","ukIpa":"/kənˈvenʃənəl/","usIpa":"/kənˈvenʃənəl/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"following methods or ideas that are usual and widely accepted","vi":"truyền thống; theo tập quán; thông thường"}],"examples":[{"en":"We chose a conventional oven instead of a microwave.","vi":"Chúng tôi đã chọn lò nướng thông thường thay vì lò vi sóng.","audioKind":"ex"},{"en":"Conventional farming methods often rely on chemical fertilisers to maintain high crop yields over large areas.","vi":"Các phương pháp canh tác truyền thống thường phụ thuộc vào phân bón hóa học để duy trì năng suất cây trồng cao trên diện tích rộng lớn.","audioKind":"ex2"}],"collocations":[{"en":"conventional methods","vi":"phương pháp thông thường"},{"en":"conventional wisdom","vi":"quan niệm thông thường; trí tuệ truyền thống"},{"en":"conventional medicine","vi":"y học cổ truyền; y học thông thường"},{"en":"conventional farming","vi":"canh tác truyền thống"}],"wordFamily":["convention (n.)","conventionally (adv.)","unconventional (adj.)"],"synonyms":["traditional","standard"],"antonyms":["unconventional"],"tipVi":"conventional nhấn mạnh sự tuân thủ các quy chuẩn thông thường, không nhất thiết phải có lịch sử lâu đời.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inadequate', 'en-b2-11', 'inadequate', '/ɪnˈædɪkwət/', 'B2', 'không đủ; không tương xứng; cảm thấy kém cỏi; không đủ năng lực', 'adj.', 'adequate (adj.), inadequately (adv.), inadequacy (n.)', 'Đồng nghĩa: insufficient, unsatisfactory · Trái nghĩa: adequate, sufficient', 'Thường dùng inadequate for; chỉ số lượng không đủ hoặc chất lượng không đạt chuẩn.', 'This tiny heater is inadequate for such a large room.', NULL, 'Cái lò sưởi nhỏ bé này hoàn toàn không đủ ấm cho một căn phòng rộng lớn như vậy.', '{"wordId":"inadequate","ukIpa":"/ɪnˈædɪkwət/","usIpa":"/ɪnˈædɪkwət/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"not enough or not good enough for a particular purpose","vi":"không đủ; không tương xứng"},{"pos":"adj.","en":"feeling unable to handle a situation successfully","vi":"cảm thấy kém cỏi; không đủ năng lực"}],"examples":[{"en":"This tiny heater is inadequate for such a large room.","vi":"Cái lò sưởi nhỏ bé này hoàn toàn không đủ ấm cho một căn phòng rộng lớn như vậy.","audioKind":"ex"},{"en":"Inadequate public transport can prevent rural residents from accessing employment opportunities and essential healthcare services.","vi":"Hệ thống giao thông công cộng thiếu thốn có thể cản trở cư dân vùng nông thôn tiếp cận cơ hội việc làm và các dịch vụ y tế thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"inadequate funding","vi":"kinh phí thiếu hụt"},{"en":"inadequate facilities","vi":"cơ sở vật chất kém"},{"en":"inadequate for the task","vi":"không đủ năng lực hoàn thành nhiệm vụ"},{"en":"feel inadequate","vi":"cảm thấy tự ti"}],"wordFamily":["adequate (adj.)","inadequately (adv.)","inadequacy (n.)"],"synonyms":["insufficient","unsatisfactory"],"antonyms":["adequate","sufficient"],"tipVi":"Thường dùng inadequate for; chỉ số lượng không đủ hoặc chất lượng không đạt chuẩn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hostile', 'en-b2-11', 'hostile', '/ˈhɑːstəl/', 'B2', 'thù địch; chống đối; khắc nghiệt; bất lợi; thuộc về địch; đối địch', 'adj.', 'hostility (n.)', 'Đồng nghĩa: unfriendly, antagonistic · Trái nghĩa: friendly, welcoming', 'Tính từ hostile đi với giới từ to theo sau là danh từ hoặc danh động từ, mang ý nghĩa thể hiện sự thù địch hoặc chống đối.', 'His hostile reply made everyone at the table uncomfortable.', NULL, 'Câu trả lời đầy thù địch của anh ấy khiến mọi người trên bàn ăn cảm thấy khó chịu.', '{"wordId":"hostile","ukIpa":"/ˈhɒstaɪl/","usIpa":"/ˈhɑːstəl/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"unfriendly or strongly opposed to someone or something","vi":"thù địch; chống đối"},{"pos":"adj.","en":"having conditions that make life or progress difficult","vi":"khắc nghiệt; bất lợi"},{"pos":"adj.","en":"belonging to an enemy or acting against another side","vi":"thuộc về địch; đối địch"}],"examples":[{"en":"His hostile reply made everyone at the table uncomfortable.","vi":"Câu trả lời đầy thù địch của anh ấy khiến mọi người trên bàn ăn cảm thấy khó chịu.","audioKind":"ex"},{"en":"Communities may become hostile to new developments if residents feel excluded from the planning process.","vi":"Cộng đồng có thể trở nên chống đối các dự án phát triển mới nếu cư dân cảm thấy mình bị gạt ra ngoài quá trình lập kế hoạch.","audioKind":"ex2"}],"collocations":[{"en":"hostile to change","vi":"chống lại sự thay đổi"},{"en":"hostile reception","vi":"sự tiếp đón lạnh nhạt"},{"en":"hostile environment","vi":"môi trường khắc nghiệt"},{"en":"hostile forces","vi":"lực lượng địch"}],"wordFamily":["hostility (n.)"],"synonyms":["unfriendly","antagonistic"],"antonyms":["friendly","welcoming"],"tipVi":"Tính từ hostile đi với giới từ to theo sau là danh từ hoặc danh động từ, mang ý nghĩa thể hiện sự thù địch hoặc chống đối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_harmony', 'en-b2-11', 'harmony', '/ˈhɑːrməni/', 'B2', 'sự hòa hợp; sự hòa thuận; sự hài hòa; sự ăn ý; hà so (âm nhạc)', 'n.', 'harmonious (adj.), harmoniously (adv.), harmonise (v.), harmonisation (n.)', 'Đồng nghĩa: accord, agreement · Trái nghĩa: conflict, discord', 'Thường dùng cụm in harmony with để chỉ sự hòa hợp hoặc nhất quán với điều gì đó.', 'Our cats and dogs live together in perfect harmony.', NULL, 'Mèo và chó nhà chúng tôi sống cùng nhau vô cùng hòa thuận.', '{"wordId":"harmony","ukIpa":"/ˈhɑːməni/","usIpa":"/ˈhɑːrməni/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"A peaceful relationship in which people cooperate and agree.","vi":"sự hòa hợp; sự hòa thuận"},{"pos":"n.","en":"A pleasing match or agreement between different things.","vi":"sự hài hòa; sự ăn ý"},{"pos":"n.","en":"Different musical notes played or sung together to support a melody.","vi":"hà so (âm nhạc)"}],"examples":[{"en":"Our cats and dogs live together in perfect harmony.","vi":"Mèo và chó nhà chúng tôi sống cùng nhau vô cùng hòa thuận.","audioKind":"ex"},{"en":"Community projects can promote social harmony by bringing residents from different backgrounds together to achieve shared goals.","vi":"Các dự án cộng đồng có thể thúc đẩy sự hòa hợp xã hội bằng cách quy tụ cư dân từ các nền tảng khác nhau để đạtλο chung mục tiêu.","audioKind":"ex2"}],"collocations":[{"en":"live in harmony","vi":"sống hòa thuận"},{"en":"social harmony","vi":"sự hòa hợp xã hội"},{"en":"in harmony with nature","vi":"hài hòa với thiên nhiên"},{"en":"sing in harmony","vi":"hát bè hòa âm"}],"wordFamily":["harmonious (adj.)","harmoniously (adv.)","harmonise (v.)","harmonisation (n.)"],"synonyms":["accord","agreement"],"antonyms":["conflict","discord"],"tipVi":"Thường dùng cụm in harmony with để chỉ sự hòa hợp hoặc nhất quán với điều gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dialect', 'en-b2-11', 'dialect', '/ˈdaɪəlekt/', 'B2', 'phương tiếng; tiếng địa phương', 'n.', 'dialectal (adj.)', NULL, 'dialect liên quan đến từ vựng và ngữ pháp, trong khi accent chủ yếu chỉ ngữ điệu/giọng điệu.', 'My grandmother speaks a dialect I sometimes struggle to understand.', NULL, 'Bà tôi nói một thứ tiếng địa phương mà đôi khi tôi thấy rất khó hiểu.', '{"wordId":"dialect","ukIpa":"/ˈdaɪəlekt/","usIpa":"/ˈdaɪəlekt/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"A language variety used in a particular region or community.","vi":"phương tiếng; tiếng địa phương"}],"examples":[{"en":"My grandmother speaks a dialect I sometimes struggle to understand.","vi":"Bà tôi nói một thứ tiếng địa phương mà đôi khi tôi thấy rất khó hiểu.","audioKind":"ex"},{"en":"Schools can help preserve local dialects while teaching students the standard language needed for wider communication.","vi":"Nhà trường có thể giúp bảo tồn các phương ngữ địa phương trong khi vẫn dạy học sinh ngôn ngữ chuẩn cần thiết cho việc giao tiếp rộng rãi hơn.","audioKind":"ex2"}],"collocations":[{"en":"local dialect","vi":"tiếng địa phương"},{"en":"regional dialect","vi":"phương ngữ vùng miền"},{"en":"speak a dialect","vi":"nói tiếng địa phương"}],"wordFamily":["dialectal (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"dialect liên quan đến từ vựng và ngữ pháp, trong khi accent chủ yếu chỉ ngữ điệu/giọng điệu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_acquaintance', 'en-b2-11', 'acquaintance', '/əˈkweɪntəns/', 'B2', 'người quen (không phải bạn thân); sự quen biết; sự hiểu biết sơ qua', 'n.', 'acquaint (v.), acquainted (adj.)', NULL, 'Là danh từ đếm được khi chỉ người quen; khi mang nghĩa hiểu biết thường đi kèm với "with".', 'An acquaintance from my yoga class waved at me.', NULL, 'Một người quen ở lớp yoga đã vẫy tay chào tôi.', '{"wordId":"acquaintance","ukIpa":"/əˈkweɪntəns/","usIpa":"/əˈkweɪntəns/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"Someone you know, but who is not a close friend.","vi":"người quen (không phải bạn thân)"},{"pos":"n.","en":"Some knowledge of a person or subject.","vi":"sự quen biết; sự hiểu biết sơ qua"}],"examples":[{"en":"An acquaintance from my yoga class waved at me.","vi":"Một người quen ở lớp yoga đã vẫy tay chào tôi.","audioKind":"ex"},{"en":"Even a basic acquaintance with local customs can help international students adapt more easily to life abroad.","vi":"Ngay cả một sự hiểu biết cơ bản về phong tục địa phương cũng có thể giúp sinh viên quốc tế thích nghi dễ dàng hơn với cuộc sống ở nước ngoài.","audioKind":"ex2"}],"collocations":[{"en":"a casual acquaintance","vi":"người quen sơ giao"},{"en":"make someone''s acquaintance","vi":"làm quen với ai đó"},{"en":"acquaintance with","vi":"sự hiểu biết về..."}],"wordFamily":["acquaint (v.)","acquainted (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ đếm được khi chỉ người quen; khi mang nghĩa hiểu biết thường đi kèm với \"with\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_transition', 'en-b2-11', 'transition', '/trænˈzɪʃən/', 'B2', 'sự chuyển đổi; giai đoạn chuyển tiếp; chuyển đổi; chuyển tiếp', 'n.', 'transitional (adj.)', 'Đồng nghĩa: change, shift', 'Thường dùng cấu trúc "transition from A to B" để chỉ sự chuyển đổi giữa hai trạng thái.', 'A familiar toy eased her transition to nursery.', NULL, 'Một món đồ chơi quen thuộc đã giúp cô bé chuyển tiếp sang môi trường nhà trẻ dễ dàng hơn.', '{"wordId":"transition","ukIpa":"/trænˈzɪʃən/","usIpa":"/trænˈzɪʃən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"A change from one state, stage, or situation to another.","vi":"sự chuyển đổi; giai đoạn chuyển tiếp"},{"pos":"v.","en":"To change from one state or situation to another.","vi":"chuyển đổi; chuyển tiếp"}],"examples":[{"en":"A familiar toy eased her transition to nursery.","vi":"Một món đồ chơi quen thuộc đã giúp cô bé chuyển tiếp sang môi trường nhà trẻ dễ dàng hơn.","audioKind":"ex"},{"en":"The transition from fossil fuels to renewable energy requires sustained investment and careful government planning.","vi":"Quá trình chuyển đổi từ nhiên liệu hóa thạch sang năng lượng tái tạo đòi hỏi sự đầu tư bền vững và kế hoạch cẩn trọng của chính phủ.","audioKind":"ex2"}],"collocations":[{"en":"a smooth transition","vi":"sự chuyển đổi suôn sẻ"},{"en":"transition from A to B","vi":"sự chuyển đổi từ A sang B"},{"en":"a transition period","vi":"giai đoạn chuyển tiếp"}],"wordFamily":["transitional (adj.)"],"synonyms":["change","shift"],"antonyms":[],"tipVi":"Thường dùng cấu trúc \"transition from A to B\" để chỉ sự chuyển đổi giữa hai trạng thái.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_crisis', 'en-b2-11', 'crisis', '/ˈkraɪsɪs/', 'B2', 'cuộc khủng hoảng; thời điểm gay cấn', 'n.', NULL, 'Đồng nghĩa: emergency', 'Dạng số nhiều là crises /ˈkraɪsiːz/, cần chú ý phát âm phần đuôi.', 'The broken water pipe caused a crisis at home.', NULL, 'Đường ống nước bị vỡ đã gây ra một phen khốn đốn ở nhà.', '{"wordId":"crisis","ukIpa":"/ˈkraɪsɪs/","usIpa":"/ˈkraɪsɪs/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"a serious situation requiring urgent decisions or action","vi":"cuộc khủng hoảng; thời điểm gay cấn"}],"examples":[{"en":"The broken water pipe caused a crisis at home.","vi":"Đường ống nước bị vỡ đã gây ra một phen khốn đốn ở nhà.","audioKind":"ex"},{"en":"The housing crisis has forced many young adults to delay moving into their own homes.","vi":"Cuộc khủng hoảng nhà ở đã buộc nhiều người trẻ tuổi phải hoãn việc dọn ra ở riêng.","audioKind":"ex2"}],"collocations":[{"en":"face a crisis","vi":"đối mặt với khủng hoảng"},{"en":"housing crisis","vi":"khủng hoảng nhà ở"},{"en":"crisis management","vi":"quản lý khủng hoảng"},{"en":"in times of crisis","vi":"trong thời kỳ khủng hoảng"}],"wordFamily":[],"synonyms":["emergency"],"antonyms":[],"tipVi":"Dạng số nhiều là crises /ˈkraɪsiːz/, cần chú ý phát âm phần đuôi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_convention', 'en-b2-11', 'convention', '/kənˈvenʃən/', 'B2', 'thói quen; tập quán; phong tục; hội nghị; đại hội; công ước; hiệp định quốc tế', 'n.', 'conventional (adj.), conventionally (adv.), unconventional (adj.)', NULL, 'Nghĩa thông lệ và hội nghị thường là danh từ đếm được; cụm từ "by convention" mang nghĩa theo thông lệ.', 'By convention, guests wait until everyone is seated before eating.', NULL, 'Theo thông lệ, khách mời sẽ đợi mọi người ngồi vào chỗ rồi mới bắt đầu dùng bữa.', '{"wordId":"convention","ukIpa":"/kənˈvenʃən/","usIpa":"/kənˈvenʃən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"An accepted way of behaving or doing something.","vi":"thói quen; tập quán; phong tục"},{"pos":"n.","en":"A large meeting of people with shared interests or work.","vi":"hội nghị; đại hội"},{"pos":"n.","en":"A formal agreement between countries about a particular issue.","vi":"công ước; hiệp định quốc tế"}],"examples":[{"en":"By convention, guests wait until everyone is seated before eating.","vi":"Theo thông lệ, khách mời sẽ đợi mọi người ngồi vào chỗ rồi mới bắt đầu dùng bữa.","audioKind":"ex"},{"en":"An international convention can strengthen environmental protection by establishing shared responsibilities for participating countries.","vi":"Một công ước quốc tế có thể tăng cường công tác bảo vệ môi trường bằng cách thiết lập các trách nhiệm chung cho các quốc gia tham gia.","audioKind":"ex2"}],"collocations":[{"en":"social convention","vi":"tập quán xã hội"},{"en":"annual convention","vi":"hội nghị thường niên"},{"en":"international convention","vi":"công ước quốc tế"},{"en":"by convention","vi":"theo thông lệ"}],"wordFamily":["conventional (adj.)","conventionally (adv.)","unconventional (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa thông lệ và hội nghị thường là danh từ đếm được; cụm từ \"by convention\" mang nghĩa theo thông lệ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cater', 'en-b2-11', 'cater', '/ˈkeɪtər/', 'B2', 'phục vụ; đáp ứng nhu cầu; cung cấp tiệc; nấu ăn phục vụ sự kiện', 'v.', 'catering (n.), caterer (n.)', NULL, 'cater for chỉ việc đáp ứng nhu cầu hoặc cung cấp thức ăn; cater to thường chỉ việc chiều theo.', 'These weekend classes cater for children of all ages.', NULL, 'Những lớp học cuối tuần này dành cho trẻ em ở mọi lứa tuổi.', '{"wordId":"cater","ukIpa":"/ˈkeɪtə/","usIpa":"/ˈkeɪtər/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"to provide what a particular person or group needs","vi":"phục vụ; đáp ứng nhu cầu"},{"pos":"v.","en":"to supply food and drinks for an event","vi":"cung cấp tiệc; nấu ăn phục vụ sự kiện"}],"examples":[{"en":"These weekend classes cater for children of all ages.","vi":"Những lớp học cuối tuần này dành cho trẻ em ở mọi lứa tuổi.","audioKind":"ex"},{"en":"Public transport systems should cater for passengers with limited mobility by providing accessible vehicles and stations.","vi":"Hệ thống giao thông công cộng nên đáp ứng nhu cầu của hành khách đi lại khó khăn bằng cách cung cấp các phương tiện và nhà ga có lối đi thuận tiện.","audioKind":"ex2"}],"collocations":[{"en":"cater for different needs","vi":"đáp ứng các nhu cầu khác nhau"},{"en":"cater to individual tastes","vi":"phục vụ thị hiếu cá nhân"},{"en":"cater for a wedding","vi":"nấu tiệc cưới"}],"wordFamily":["catering (n.)","caterer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"cater for chỉ việc đáp ứng nhu cầu hoặc cung cấp thức ăn; cater to thường chỉ việc chiều theo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inquiry', 'en-b2-11', 'inquiry', '/ˈɪnkwəri/', 'B2', 'cuộc điều tra; sự nghiên cứu; sự hỏi; sự dò hỏi', 'n.', 'inquire (v.), inquiring (adj.)', 'Đồng nghĩa: investigation, enquiry', 'Điều tra về việc gì dùng inquiry into; trong tiếng Anh Anh, enquiry cũng thường mang nghĩa là hỏi thông tin.', 'My inquiry about the missing parcel received a quick reply.', NULL, 'Yêu cầu tra cứu của tôi về kiện hàng bị thất lạc đã nhận được phản hồi nhanh chóng.', '{"wordId":"inquiry","ukIpa":"/ɪnˈkwaɪəri/","usIpa":"/ˈɪnkwəri/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"a process of investigating facts or seeking knowledge","vi":"cuộc điều tra; sự nghiên cứu"},{"pos":"n.","en":"a request for information about something","vi":"sự hỏi; sự dò hỏi"}],"examples":[{"en":"My inquiry about the missing parcel received a quick reply.","vi":"Yêu cầu tra cứu của tôi về kiện hàng bị thất lạc đã nhận được phản hồi nhanh chóng.","audioKind":"ex"},{"en":"An independent inquiry into river pollution revealed serious weaknesses in the current system of environmental monitoring.","vi":"Một cuộc điều tra độc lập về tình trạng ô nhiễm dòng sông đã phơi bày những điểm yếu nghiêm trọng trong hệ thống giám sát môi trường hiện tại.","audioKind":"ex2"}],"collocations":[{"en":"public inquiry","vi":"cuộc điều tra công khai"},{"en":"inquiry into","vi":"cuộc điều tra về"},{"en":"make an inquiry","vi":"gửi yêu cầu hỏi thông tin"},{"en":"scientific inquiry","vi":"nghiên cứu khoa học"}],"wordFamily":["inquire (v.)","inquiring (adj.)"],"synonyms":["investigation","enquiry"],"antonyms":[],"tipVi":"Điều tra về việc gì dùng inquiry into; trong tiếng Anh Anh, enquiry cũng thường mang nghĩa là hỏi thông tin.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unite', 'en-b2-11', 'unite', '/juˈnaɪt/', 'B2', 'liên kết; đoàn kết; thống nhất', 'v.', 'unity (n.), united (adj.), unification (n.), reunite (v.)', 'Đồng nghĩa: join, unify · Trái nghĩa: divide, separate', 'unite có thể dùng ở dạng ngoại động từ hoặc nội động từ, nhấn mạnh việc cùng nhau hướng tới một mục tiêu chung.', 'The whole village united to repair the damaged bridge.', NULL, 'Toàn bộ ngôi làng đã đồng lòng chung sức sửa chữa cây cầu bị hỏng.', '{"wordId":"unite","ukIpa":"/juˈnaɪt/","usIpa":"/juˈnaɪt/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"To join together or bring people together for a shared purpose.","vi":"liên kết; đoàn kết; thống nhất"}],"examples":[{"en":"The whole village united to repair the damaged bridge.","vi":"Toàn bộ ngôi làng đã đồng lòng chung sức sửa chữa cây cầu bị hỏng.","audioKind":"ex"},{"en":"Shared environmental goals can unite communities that otherwise have very different economic and political interests.","vi":"Các mục tiêu chung về môi trường có thể gắn kết các cộng đồng vốn có lợi ích kinh tế và chính trị vô cùng khác biệt.","audioKind":"ex2"}],"collocations":[{"en":"unite against","vi":"đoàn kết chống lại"},{"en":"unite behind a leader","vi":"đoàn kết ủng hộ một nhà lãnh đạo"},{"en":"unite efforts","vi":"hợp sức; gom góp nỗ lực"}],"wordFamily":["unity (n.)","united (adj.)","unification (n.)","reunite (v.)"],"synonyms":["join","unify"],"antonyms":["divide","separate"],"tipVi":"unite có thể dùng ở dạng ngoại động từ hoặc nội động từ, nhấn mạnh việc cùng nhau hướng tới một mục tiêu chung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_riot', 'en-b2-11', 'riot', '/ˈraɪət/', 'B2', 'bạo loạn; cuộc nổi loạn; gây bạo loạn; nổi loạn', 'n.', 'rioter (n.), rioting (n.), riotous (adj.)', NULL, 'riot liên quan đến các hành vi bạo lực náo loạn, không đồng nghĩa với hoạt động protest ôn hòa.', 'The shop closed early because a riot broke out nearby.', NULL, 'Cửa hàng đã đóng cửa sớm vì một cuộc bạo loạn bùng phát gần đó.', '{"wordId":"riot","ukIpa":"/ˈraɪət/","usIpa":"/ˈraɪət/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"Violent public disorder involving a crowd of people.","vi":"bạo loạn; cuộc nổi loạn"},{"pos":"v.","en":"To behave violently as part of a crowd in public.","vi":"gây bạo loạn; nổi loạn"}],"examples":[{"en":"The shop closed early because a riot broke out nearby.","vi":"Cửa hàng đã đóng cửa sớm vì một cuộc bạo loạn bùng phát gần đó.","audioKind":"ex"},{"en":"Effective communication between communities and local authorities may help prevent peaceful demonstrations from turning into riots.","vi":"Giao tiếp hiệu quả giữa cộng đồng và chính quyền địa phương có thể giúp ngăn chặn các cuộc biểu tình ôn hòa biến thành bạo loạn.","audioKind":"ex2"}],"collocations":[{"en":"a riot breaks out","vi":"bạo loạn bùng nổ"},{"en":"riot police","vi":"cảnh sát chống bạo động"},{"en":"spark a riot","vi":"châm ngòi bạo loạn"}],"wordFamily":["rioter (n.)","rioting (n.)","riotous (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"riot liên quan đến các hành vi bạo lực náo loạn, không đồng nghĩa với hoạt động protest ôn hòa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_propose', 'en-b2-11', 'propose', '/prəˈpoʊz/', 'B2', 'đề xuất; đưa ra ý kiến; cầu hôn; dự định; có ý định', 'v.', 'proposal (n.), proposer (n.)', 'Đồng nghĩa: suggest, put forward', 'propose doing là đề xuất; propose to do thường là dự định.', 'I proposed sharing a taxi to save us money.', NULL, 'Tôi đã đề xuất đi chung xe taxi để tiết kiệm tiền.', '{"wordId":"propose","ukIpa":"/prəˈpəʊz/","usIpa":"/prəˈpoʊz/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"Suggest an idea or plan for others to consider.","vi":"đề xuất; đưa ra ý kiến"},{"pos":"v.","en":"Ask someone to marry you.","vi":"cầu hôn"},{"pos":"v.","en":"Intend or plan to do something.","vi":"dự định; có ý định"}],"examples":[{"en":"I proposed sharing a taxi to save us money.","vi":"Tôi đã đề xuất đi chung xe taxi để tiết kiệm tiền.","audioKind":"ex"},{"en":"Researchers propose expanding urban green spaces to improve air quality and encourage residents to exercise more regularly.","vi":"Các nhà nghiên cứu đề xuất mở rộng không gian xanh đô thị nhằm cải thiện chất lượng không khí và khuyến khích người dân tập thể dục đều đặn hơn.","audioKind":"ex2"}],"collocations":[{"en":"propose a solution","vi":"đưa ra giải pháp"},{"en":"propose doing something","vi":"đề xuất làm gì đó"},{"en":"propose to someone","vi":"cầu hôn ai đó"},{"en":"propose a motion","vi":"đưa ra kiến nghị/động thái"}],"wordFamily":["proposal (n.)","proposer (n.)"],"synonyms":["suggest","put forward"],"antonyms":[],"tipVi":"propose doing là đề xuất; propose to do thường là dự định.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_enquiry', 'en-b2-11', 'enquiry', '/ɪnˈkwaɪri/', 'B2', 'câu hỏi; sự hỏi thông tin; cuộc điều tra; sự thẩm tra', 'n.', 'enquire (v.), enquirer (n.)', 'Đồng nghĩa: inquiry, query, investigation', 'Đây là danh từ đếm được, số nhiều là enquiries; tiếng Anh-Mỹ thường viết là inquiry.', 'The receptionist answered my enquiry about the opening hours.', NULL, 'Nhân viên lễ tân đã trả lời câu hỏi của tôi về giờ mở cửa.', '{"wordId":"enquiry","ukIpa":"/ɪnˈkwaɪəri/","usIpa":"/ɪnˈkwaɪri/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"A question or request for information.","vi":"câu hỏi; sự hỏi thông tin"},{"pos":"n.","en":"An organised attempt to discover facts about a matter.","vi":"cuộc điều tra; sự thẩm tra"}],"examples":[{"en":"The receptionist answered my enquiry about the opening hours.","vi":"Nhân viên lễ tân đã trả lời câu hỏi của tôi về giờ mở cửa.","audioKind":"ex"},{"en":"A public enquiry into the transport project could help explain why construction costs rose so sharply.","vi":"Một cuộc điều tra công khai về dự án giao thông có thể giúp giải thích lý do tại sao chi phí xây dựng lại tăng vọt đến vậy.","audioKind":"ex2"}],"collocations":[{"en":"make an enquiry","vi":"đưa ra câu hỏi; thực hiện việc hỏi đáp"},{"en":"enquiry about","vi":"câu hỏi về..."},{"en":"public enquiry","vi":"cuộc điều tra công khai"},{"en":"enquiry desk","vi":"bàn hướng dẫn; quầy thông tin"}],"wordFamily":["enquire (v.)","enquirer (n.)"],"synonyms":["inquiry","query","investigation"],"antonyms":[],"tipVi":"Đây là danh từ đếm được, số nhiều là enquiries; tiếng Anh-Mỹ thường viết là inquiry.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_masculine', 'en-b2-11', 'masculine', '/ˈmæskjəlɪn/', 'B2', 'mang tính nam; nam tính; (thuộc ngữ pháp) giống đực; giống đực', 'adj.', 'masculinity (n.)', 'Đồng nghĩa: manly · Trái nghĩa: feminine', 'male chỉ giới tính sinh học; masculine thường chỉ đặc điểm hoặc giới tính ngữ pháp.', 'The jacket gives the outfit a traditionally masculine look.', NULL, 'Chiếc áo khoác mang lại cho tổng thể trang phục vẻ ngoài nam tính truyền thống.', '{"wordId":"masculine","ukIpa":"/ˈmæskjəlɪn/","usIpa":"/ˈmæskjəlɪn/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Having qualities or appearances traditionally associated with men","vi":"mang tính nam; nam tính"},{"pos":"adj.","en":"Belonging to a grammatical gender category in some languages","vi":"(thuộc ngữ pháp) giống đực; giống đực"}],"examples":[{"en":"The jacket gives the outfit a traditionally masculine look.","vi":"Chiếc áo khoác mang lại cho tổng thể trang phục vẻ ngoài nam tính truyền thống.","audioKind":"ex"},{"en":"Ideas about masculine behaviour vary across cultures and can influence the career choices available to young people.","vi":"Các quan niệm về hành vi nam tính khác nhau giữa các nền văn hóa và có thể ảnh hưởng đến những lựa chọn nghề nghiệp dành cho giới trẻ.","audioKind":"ex2"}],"collocations":[{"en":"masculine appearance","vi":"ngoại hình nam tính"},{"en":"masculine identity","vi":"danh tính nam"},{"en":"masculine noun","vi":"danh từ giống đực"}],"wordFamily":["masculinity (n.)"],"synonyms":["manly"],"antonyms":["feminine"],"tipVi":"male chỉ giới tính sinh học; masculine thường chỉ đặc điểm hoặc giới tính ngữ pháp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_registered', 'en-b2-11', 'registered', '/ˈredʒɪstərd/', 'B2', 'đã đăng ký; đã ghi danh', 'adj.', 'register (v.), register (n.), registration (n.)', 'Trái nghĩa: unregistered', 'registered nurse chỉ y tá có chứng chỉ hành nghề chính thức.', 'Only registered members can borrow books from this library.', NULL, 'Chỉ có hội viên đã đăng ký mới được mượn sách từ thư viện này.', '{"wordId":"registered","ukIpa":"/ˈredʒɪstəd/","usIpa":"/ˈredʒɪstərd/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Officially recorded on a list or in a system.","vi":"đã đăng ký; đã ghi danh"}],"examples":[{"en":"Only registered members can borrow books from this library.","vi":"Chỉ có hội viên đã đăng ký mới được mượn sách từ thư viện này.","audioKind":"ex"},{"en":"Employing registered nurses in community clinics can improve access to reliable healthcare in rural areas.","vi":"Việc thuê các y tá đã đăng ký tại các phòng khám cộng đồng có thể giúp người dân ở vùng nông thôn tiếp cận dịch vụ chăm sóc sức khỏe đáng tin cậy dễ dàng hơn.","audioKind":"ex2"}],"collocations":[{"en":"registered nurse","vi":"y tá đã đăng ký"},{"en":"registered charity","vi":"tổ chức từ thiện đã đăng ký"},{"en":"registered owner","vi":"chủ sở hữu đứng tên đăng ký"},{"en":"registered post","vi":"thư bảo đảm"}],"wordFamily":["register (v.)","register (n.)","registration (n.)"],"synonyms":[],"antonyms":["unregistered"],"tipVi":"registered nurse chỉ y tá có chứng chỉ hành nghề chính thức.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_considerate', 'en-b2-11', 'considerate', '/kənˈsɪdərət/', 'B2', 'chu đáo; ân cần; biết nghĩ cho người khác', 'adj.', 'consideration (n.), considerately (adv.), inconsiderate (adj.)', 'Đồng nghĩa: thoughtful · Trái nghĩa: inconsiderate, thoughtless', 'considerate mang nghĩa chu đáo, ân cần; trong khi considerable có nghĩa là đáng kể.', 'Our considerate neighbour turns down the music after dinner.', NULL, 'Người hàng xóm chu đáo của chúng tôi thường vặn nhỏ nhạc sau bữa tối.', '{"wordId":"considerate","ukIpa":"/kənˈsɪdərət/","usIpa":"/kənˈsɪdərət/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Careful not to upset or inconvenience other people.","vi":"chu đáo; ân cần; biết nghĩ cho người khác"}],"examples":[{"en":"Our considerate neighbour turns down the music after dinner.","vi":"Người hàng xóm chu đáo của chúng tôi thường vặn nhỏ nhạc sau bữa tối.","audioKind":"ex"},{"en":"Being considerate towards other passengers can make public transport more comfortable and accessible for everyone.","vi":"Việc biết quan tâm, thể hiện sự chu đáo với các hành khách khác có thể khiến phương tiện giao thông công cộng trở nên thoải mái và dễ tiếp cận hơn cho mọi người.","audioKind":"ex2"}],"collocations":[{"en":"considerate of others","vi":"chu đáo với người khác"},{"en":"considerate behaviour","vi":"hành vi chu đáo"},{"en":"considerate neighbour","vi":"người hàng xóm chu đáo"}],"wordFamily":["consideration (n.)","considerately (adv.)","inconsiderate (adj.)"],"synonyms":["thoughtful"],"antonyms":["inconsiderate","thoughtless"],"tipVi":"considerate mang nghĩa chu đáo, ân cần; trong khi considerable có nghĩa là đáng kể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unjust', 'en-b2-11', 'unjust', '/ʌnˈdʒʌst/', 'B2', 'bất công; không công bằng; phi lý', 'adj.', 'just (adj.), unjustly (adv.), injustice (n.), justice (n.)', 'Đồng nghĩa: unfair, inequitable · Trái nghĩa: just, fair', 'unjust nhấn mạnh sự vi phạm nguyên tắc công lý/đạo đức; unfair có phạm vi sử dụng rộng và thông dụng hơn.', 'It seemed unjust to blame her for everyone''s mistakes.', NULL, 'Thật bất công khi đổ lỗi sai lầm của mọi người lên cô ấy.', '{"wordId":"unjust","ukIpa":"/ʌnˈdʒʌst/","usIpa":"/ʌnˈdʒʌst/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"not fair or morally right","vi":"bất công; không công bằng; phi lý"}],"examples":[{"en":"It seemed unjust to blame her for everyone''s mistakes.","vi":"Thật bất công khi đổ lỗi sai lầm của mọi người lên cô ấy.","audioKind":"ex"},{"en":"An unjust legal system can weaken public trust and discourage citizens from seeking help through official channels.","vi":"Một hệ thống pháp luật bất công có thể làm suy giảm niềm tin của công chúng và khiến người dân ngại tìm kiếm sự hỗ trợ qua các kênh chính thức.","audioKind":"ex2"}],"collocations":[{"en":"unjust treatment","vi":"sự đối xử bất công"},{"en":"an unjust law","vi":"một đạo luật bất công"},{"en":"an unjust punishment","vi":"một hình phạt bất công"}],"wordFamily":["just (adj.)","unjustly (adv.)","injustice (n.)","justice (n.)"],"synonyms":["unfair","inequitable"],"antonyms":["just","fair"],"tipVi":"unjust nhấn mạnh sự vi phạm nguyên tắc công lý/đạo đức; unfair có phạm vi sử dụng rộng và thông dụng hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_confess', 'en-b2-11', 'confess', '/kənˈfes/', 'B2', 'thú nhận; thú tội; khai nhận; thú thực; thừa nhận điều khó nói', 'v.', 'confession (n.)', 'Đồng nghĩa: admit · Trái nghĩa: deny', 'Cấu trúc confess to với to là một giới từ, theo sau là danh từ hoặc danh động từ.', 'I confessed to eating the last slice of cake.', NULL, 'Tôi đành thú nhận là mình đã ăn nốt miếng bánh ngọt cuối cùng.', '{"wordId":"confess","ukIpa":"/kənˈfes/","usIpa":"/kənˈfes/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"to admit doing something wrong or illegal","vi":"thú nhận; thú tội; khai nhận"},{"pos":"v.","en":"to admit something personal that you feel embarrassed about","vi":"thú thực; thừa nhận điều khó nói"}],"examples":[{"en":"I confessed to eating the last slice of cake.","vi":"Tôi đành thú nhận là mình đã ăn nốt miếng bánh ngọt cuối cùng.","audioKind":"ex"},{"en":"Students may be more willing to confess their mistakes when teachers respond calmly and offer constructive guidance.","vi":"Học sinh có thể sẽ sẵn sàng thừa nhận lỗi lầm của mình hơn khi giáo viên phản ứng bình tĩnh và đưa ra những lời hướng dẫn mang tính xây dựng.","audioKind":"ex2"}],"collocations":[{"en":"confess to doing something","vi":"thú nhận đã làm điều gì"},{"en":"confess a crime","vi":"thú tội"},{"en":"confess that","vi":"thừa nhận rằng"}],"wordFamily":["confession (n.)"],"synonyms":["admit"],"antonyms":["deny"],"tipVi":"Cấu trúc confess to với to là một giới từ, theo sau là danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_norm', 'en-b2-11', 'norm', '/nɔːrm/', 'B2', 'điều bình thường; chuẩn mực thông thường; quy tắc ứng xử; chuẩn mực hành vi', 'n.', 'normal (adj.), normally (adv.), normality (n.)', NULL, 'Để chỉ "điều bình thường/thông lệ", thường dùng "the norm"; khi chỉ các quy tắc ứng xử thường dùng ở dạng số nhiều.', 'Working from home is now the norm in our team.', NULL, 'Làm việc tại nhà giờ đây đã trở thành điều bình thường trong nhóm chúng tôi.', '{"wordId":"norm","ukIpa":"/nɔːm/","usIpa":"/nɔːrm/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"a usual situation or accepted standard","vi":"điều bình thường; chuẩn mực thông thường"},{"pos":"n.","en":"an accepted rule for behaviour within a group","vi":"quy tắc ứng xử; chuẩn mực hành vi"}],"examples":[{"en":"Working from home is now the norm in our team.","vi":"Làm việc tại nhà giờ đây đã trở thành điều bình thường trong nhóm chúng tôi.","audioKind":"ex"},{"en":"Social norms influence how people interact, although acceptable behaviour can vary significantly across cultures.","vi":"Các chuẩn mực xã hội ảnh hưởng đến cách mọi người tương tác, mặc dù hành vi được chấp nhận có thể khác nhau đáng kể giữa các nền văn hóa.","audioKind":"ex2"}],"collocations":[{"en":"the norm","vi":"điều bình thường; thông lệ"},{"en":"social norms","vi":"các chuẩn mực xã hội"},{"en":"cultural norms","vi":"các chuẩn mực văn hóa"},{"en":"become the norm","vi":"trở thành thông lệ"}],"wordFamily":["normal (adj.)","normally (adv.)","normality (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Để chỉ \"điều bình thường/thông lệ\", thường dùng \"the norm\"; khi chỉ các quy tắc ứng xử thường dùng ở dạng số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_11_1', 'en-b2-11', 'Cách dùng “hostile” (adj.) — thù địch; chống đối', 'hostile to change  ·  hostile reception  ·  hostile environment', 'Tính từ hostile đi với giới từ to theo sau là danh từ hoặc danh động từ, mang ý nghĩa thể hiện sự thù địch hoặc chống đối.', 'Họ từ (Word Family): hostility (n.) | Đồng nghĩa: unfriendly, antagonistic · Trái nghĩa: friendly, welcoming', '[{"hanzi":"His hostile reply made everyone at the table uncomfortable.","pinyin":"","meaning":"Câu trả lời đầy thù địch của anh ấy khiến mọi người trên bàn ăn cảm thấy khó chịu."},{"hanzi":"Communities may become hostile to new developments if residents feel excluded from the planning process.","pinyin":"","meaning":"Cộng đồng có thể trở nên chống đối các dự án phát triển mới nếu cư dân cảm thấy mình bị gạt ra ngoài quá trình lập kế hoạch."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_11_2', 'en-b2-11', 'Cách dùng “norm” (n.) — điều bình thường; chuẩn mực thông thường', 'the norm  ·  social norms  ·  cultural norms', 'Để chỉ "điều bình thường/thông lệ", thường dùng "the norm"; khi chỉ các quy tắc ứng xử thường dùng ở dạng số nhiều.', 'Họ từ (Word Family): normal (adj.), normally (adv.), normality (n.)', '[{"hanzi":"Working from home is now the norm in our team.","pinyin":"","meaning":"Làm việc tại nhà giờ đây đã trở thành điều bình thường trong nhóm chúng tôi."},{"hanzi":"Social norms influence how people interact, although acceptable behaviour can vary significantly across cultures.","pinyin":"","meaning":"Các chuẩn mực xã hội ảnh hưởng đến cách mọi người tương tác, mặc dù hành vi được chấp nhận có thể khác nhau đáng kể giữa các nền văn hóa."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_11_3', 'en-b2-11', 'Cách dùng “unite” (v.) — liên kết; đoàn kết; thống nhất', 'unite against  ·  unite behind a leader  ·  unite efforts', 'unite có thể dùng ở dạng ngoại động từ hoặc nội động từ, nhấn mạnh việc cùng nhau hướng tới một mục tiêu chung.', 'Họ từ (Word Family): unity (n.), united (adj.), unification (n.), reunite (v.) | Đồng nghĩa: join, unify · Trái nghĩa: divide, separate', '[{"hanzi":"The whole village united to repair the damaged bridge.","pinyin":"","meaning":"Toàn bộ ngôi làng đã đồng lòng chung sức sửa chữa cây cầu bị hỏng."},{"hanzi":"Shared environmental goals can unite communities that otherwise have very different economic and political interests.","pinyin":"","meaning":"Các mục tiêu chung về môi trường có thể gắn kết các cộng đồng vốn có lợi ích kinh tế và chính trị vô cùng khác biệt."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_11_4', 'en-b2-11', 'Cách dùng “inquiry” (n.) — cuộc điều tra; sự nghiên cứu', 'public inquiry  ·  inquiry into  ·  make an inquiry', 'Điều tra về việc gì dùng inquiry into; trong tiếng Anh Anh, enquiry cũng thường mang nghĩa là hỏi thông tin.', 'Họ từ (Word Family): inquire (v.), inquiring (adj.) | Đồng nghĩa: investigation, enquiry', '[{"hanzi":"My inquiry about the missing parcel received a quick reply.","pinyin":"","meaning":"Yêu cầu tra cứu của tôi về kiện hàng bị thất lạc đã nhận được phản hồi nhanh chóng."},{"hanzi":"An independent inquiry into river pollution revealed serious weaknesses in the current system of environmental monitoring.","pinyin":"","meaning":"Một cuộc điều tra độc lập về tình trạng ô nhiễm dòng sông đã phơi bày những điểm yếu nghiêm trọng trong hệ thống giám sát môi trường hiện tại."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_11_1', 'en-b2-11', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
