INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_11_1_2', 'ten_b2_11_1', 'resolve', 'We resolved the argument by taking turns cooking dinner.', 'We resolved the argument by taking turns cooking dinner.', '/rɪˈzɑːlv/', 'Chúng tôi đã giải quyết cuộc cãi vã bằng cách luân phiên nấu bữa tối.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_11_1_3', 'ten_b2_11_1', 'manner', 'She answered my questions in a calm manner.', 'She answered my questions in a calm manner.', '/ˈmænər/', 'Cô ấy đã trả lời các câu hỏi của tôi với một thái độ điềm tĩnh.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_11_1_4', 'ten_b2_11_1', 'isolation', 'Weekly visits from neighbours helped reduce her sense of isolation.', 'Weekly visits from neighbours helped reduce her sense of isolation.', '/ˌaɪsəˈleɪʃən/', 'Những chuyến thăm hàng tuần từ những người hàng xóm đã giúp làm giảm cảm giác cô đơn của cô ấy.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_11_1_5', 'ten_b2_11_1', 'controversy', 'The plan to close our pool sparked local controversy.', 'The plan to close our pool sparked local controversy.', '/ˈkɑːntrəvɝːsi/', 'Kế hoạch đóng cửa hồ bơi của chúng tôi đã châm ngòi cho những tranh cãi tại địa phương.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_11_1_6', 'ten_b2_11_1', 'conventional', 'We chose a conventional oven instead of a microwave.', 'We chose a conventional oven instead of a microwave.', '/kənˈvenʃənəl/', 'Chúng tôi đã chọn lò nướng thông thường thay vì lò vi sóng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_11_1_7', 'ten_b2_11_1', 'inadequate', 'This tiny heater is inadequate for such a large room.', 'This tiny heater is inadequate for such a large room.', '/ɪnˈædɪkwət/', 'Cái lò sưởi nhỏ bé này hoàn toàn không đủ ấm cho một căn phòng rộng lớn như vậy.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_11_1_8', 'ten_b2_11_1', 'hostile', 'His hostile reply made everyone at the table uncomfortable.', 'His hostile reply made everyone at the table uncomfortable.', '/ˈhɑːstəl/', 'Câu trả lời đầy thù địch của anh ấy khiến mọi người trên bàn ăn cảm thấy khó chịu.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_11_1_1', 'en-b2-11', 'ten_b2_11_1', 'listening', 'listening', 'Someone tried to smuggle rare birds through the airport.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy đã trả lời các câu hỏi của tôi với một thái độ điềm tĩnh.","Cái lò sưởi nhỏ bé này hoàn toàn không đủ ấm cho một căn phòng rộng lớn như vậy.","Chiếc áo khoác mang lại cho tổng thể trang phục vẻ ngoài nam tính truyền thống.","Ai đó đã cố gắng buôn lậu các loài chim quý hiếm qua sân bay."]'::jsonb, 3, 'Someone tried to smuggle rare birds through the airport. → Ai đó đã cố gắng buôn lậu các loài chim quý hiếm qua sân bay.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_11_1_2', 'en-b2-11', 'ten_b2_11_1', 'listening', 'listening', 'We resolved the argument by taking turns cooking dinner.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Ai đó đã cố gắng buôn lậu các loài chim quý hiếm qua sân bay.","Chúng tôi đã giải quyết cuộc cãi vã bằng cách luân phiên nấu bữa tối.","Câu trả lời đầy thù địch của anh ấy khiến mọi người trên bàn ăn cảm thấy khó chịu.","Theo thông lệ, khách mời sẽ đợi mọi người ngồi vào chỗ rồi mới bắt đầu dùng bữa."]'::jsonb, 1, 'We resolved the argument by taking turns cooking dinner. → Chúng tôi đã giải quyết cuộc cãi vã bằng cách luân phiên nấu bữa tối.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_11_1_3', 'en-b2-11', 'ten_b2_11_1', 'listening', 'listening', 'She answered my questions in a calm manner.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã chọn lò nướng thông thường thay vì lò vi sóng.","Đường ống nước bị vỡ đã gây ra một phen khốn đốn ở nhà.","Tôi đã đề xuất đi chung xe taxi để tiết kiệm tiền.","Cô ấy đã trả lời các câu hỏi của tôi với một thái độ điềm tĩnh."]'::jsonb, 3, 'She answered my questions in a calm manner. → Cô ấy đã trả lời các câu hỏi của tôi với một thái độ điềm tĩnh.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_11_2', 'en-b2-11', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_11_2_1', 'ten_b2_11_2', 'smuggle', 'Stronger international cooperation is needed to stop criminal groups that smuggle endangered animals across national borders.', 'Stronger international cooperation is needed to stop criminal groups that smuggle endangered animals across national borders.', '/ˈsmʌɡəl/', 'Cần tăng cường hợp tác quốc tế để ngăn chặn các băng nhóm tội phạm buôn lậu động vật có nguy cơ tuyệt chủng qua biên giới quốc gia.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_11_2_2', 'ten_b2_11_2', 'resolve', 'International cooperation is essential to resolve disputes over shared water resources and prevent future conflicts.', 'International cooperation is essential to resolve disputes over shared water resources and prevent future conflicts.', '/rɪˈzɑːlv/', 'Hợp tác quốc tế là yếu tố cốt lõi để giải quyết các tranh chấp về nguồn nước chung và ngăn ngừa những xung đột trong tương lai.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_11_2_3', 'ten_b2_11_2', 'manner', 'Schools should teach children to express disagreement in a respectful manner while encouraging independent thinking.', 'Schools should teach children to express disagreement in a respectful manner while encouraging independent thinking.', '/ˈmænər/', 'Nhà trường nên dạy học sinh cách bày tỏ sự bất đồng theo hướng tôn trọng người khác, đồng thời khuyến khích tư duy độc lập.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_11_2_4', 'ten_b2_11_2', 'isolation', 'Investment in community centres may reduce social isolation among older residents who live alone.', 'Investment in community centres may reduce social isolation among older residents who live alone.', '/ˌaɪsəˈleɪʃən/', 'Đầu tư vào các trung tâm cộng đồng có thể làm giảm tình trạng cô lập xã hội ở những cư dân lớn tuổi sống một mình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_11_2_5', 'ten_b2_11_2', 'controversy', 'The use of facial recognition in public spaces has generated controversy over privacy and personal freedom.', 'The use of facial recognition in public spaces has generated controversy over privacy and personal freedom.', '/ˈkɑːntrəvɝːsi/', 'Việc sử dụng công nghệ nhận diện khuôn mặt ở nơi công cộng đã gây ra nhiều tranh cãi về quyền riêng tư và tự do cá nhân.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_11_2_6', 'ten_b2_11_2', 'conventional', 'Conventional farming methods often rely on chemical fertilisers to maintain high crop yields over large areas.', 'Conventional farming methods often rely on chemical fertilisers to maintain high crop yields over large areas.', '/kənˈvenʃənəl/', 'Các phương pháp canh tác truyền thống thường phụ thuộc vào phân bón hóa học để duy trì năng suất cây trồng cao trên diện tích rộng lớn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_11_2_1', 'en-b2-11', 'ten_b2_11_2', 'listening', 'listening', 'Stronger international cooperation is needed to stop criminal groups that smuggle endangered animals across national borders.', NULL, 'Trong câu vừa nghe, từ “smuggle” mang nghĩa nào sau đây?', '["thiên đường; chốn bồng lai tiên cảnh; nơi lý tưởng","áp đặt; ban hành (luật, thuế, hình phạt)","trước đây; thuở trước","vận chuyển trái phép; buôn lậu; lén mang vào"]'::jsonb, 3, '“smuggle” (/ˈsmʌɡəl/): vận chuyển trái phép; buôn lậu; lén mang vào. Câu đầy đủ: Stronger international cooperation is needed to stop criminal groups that smuggle endangered animals across national borders.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_11_2_2', 'en-b2-11', 'ten_b2_11_2', 'listening', 'listening', 'International cooperation is essential to resolve disputes over shared water resources and prevent future conflicts.', NULL, 'Trong câu vừa nghe, từ “resolve” mang nghĩa nào sau đây?', '["thuộc về quân đội; quân sự","giải quyết; tháo gỡ","cuộc mít tinh; cuộc biểu tình","mí mắt; mi mắt"]'::jsonb, 1, '“resolve” (/rɪˈzɑːlv/): giải quyết; tháo gỡ. Câu đầy đủ: International cooperation is essential to resolve disputes over shared water resources and prevent future conflicts.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
