INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_11_2', 'en-b2-11', NULL, 'comprehensive_test', 'listening', 'We resolved the argument by taking turns cooking dinner.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một món đồ chơi quen thuộc đã giúp cô bé chuyển tiếp sang môi trường nhà trẻ dễ dàng hơn.","Yêu cầu tra cứu của tôi về kiện hàng bị thất lạc đã nhận được phản hồi nhanh chóng.","Chúng tôi đã giải quyết cuộc cãi vã bằng cách luân phiên nấu bữa tối.","Nhân viên lễ tân đã trả lời câu hỏi của tôi về giờ mở cửa."]'::jsonb, 2, 'We resolved the argument by taking turns cooking dinner. → Chúng tôi đã giải quyết cuộc cãi vã bằng cách luân phiên nấu bữa tối.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_11_3', 'en-b2-11', NULL, 'comprehensive_test', 'listening', 'manner', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tưởng tượng; ảo tưởng; hư cấu","cách thức; phương pháp","nhàn rỗi; không hoạt động; bỏ không","ngắn hạn"]'::jsonb, 1, 'manner (/ˈmænər/) → cách thức; phương pháp; thái độ; cách ứng xử; lễ phép; phép lịch sự', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_11_4', 'en-b2-11', NULL, 'comprehensive_test', 'listening', 'Weekly visits from neighbours helped reduce her sense of isolation.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những chuyến thăm hàng tuần từ những người hàng xóm đã giúp làm giảm cảm giác cô đơn của cô ấy.","Đường ống nước bị vỡ đã gây ra một phen khốn đốn ở nhà.","Bà tôi nói một thứ tiếng địa phương mà đôi khi tôi thấy rất khó hiểu.","Theo thông lệ, khách mời sẽ đợi mọi người ngồi vào chỗ rồi mới bắt đầu dùng bữa."]'::jsonb, 0, 'Weekly visits from neighbours helped reduce her sense of isolation. → Những chuyến thăm hàng tuần từ những người hàng xóm đã giúp làm giảm cảm giác cô đơn của cô ấy.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_11_5', 'en-b2-11', NULL, 'comprehensive_test', 'listening', 'controversy', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cuộc tranh cãi; sự bất đồng công khai","vật lộn; cố gắng hết sức","sương mù mỏng; làn sương","bình luận trực tiếp, tường thuật diễn biến sự việc"]'::jsonb, 0, 'controversy (/ˈkɑːntrəvɝːsi/) → cuộc tranh cãi; sự bất đồng công khai', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_11_6', 'en-b2-11', NULL, 'comprehensive_test', 'listening', 'We chose a conventional oven instead of a microwave.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Toàn bộ ngôi làng đã đồng lòng chung sức sửa chữa cây cầu bị hỏng.","Chúng tôi đã giải quyết cuộc cãi vã bằng cách luân phiên nấu bữa tối.","Chúng tôi đã chọn lò nướng thông thường thay vì lò vi sóng.","Cô ấy đã trả lời các câu hỏi của tôi với một thái độ điềm tĩnh."]'::jsonb, 2, 'We chose a conventional oven instead of a microwave. → Chúng tôi đã chọn lò nướng thông thường thay vì lò vi sóng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_11_7', 'en-b2-11', NULL, 'comprehensive_test', 'listening', 'inadequate', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["căng thẳng; căng","chú thích ảnh; phụ đề","không đủ; không tương xứng","trộn; pha trộn; hòa quyện"]'::jsonb, 2, 'inadequate (/ɪnˈædɪkwət/) → không đủ; không tương xứng; cảm thấy kém cỏi; không đủ năng lực', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_11_8', 'en-b2-11', NULL, 'comprehensive_test', 'listening', 'His hostile reply made everyone at the table uncomfortable.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cửa hàng đã đóng cửa sớm vì một cuộc bạo loạn bùng phát gần đó.","Cái lò sưởi nhỏ bé này hoàn toàn không đủ ấm cho một căn phòng rộng lớn như vậy.","Câu trả lời đầy thù địch của anh ấy khiến mọi người trên bàn ăn cảm thấy khó chịu.","Kế hoạch đóng cửa hồ bơi của chúng tôi đã châm ngòi cho những tranh cãi tại địa phương."]'::jsonb, 2, 'His hostile reply made everyone at the table uncomfortable. → Câu trả lời đầy thù địch của anh ấy khiến mọi người trên bàn ăn cảm thấy khó chịu.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_11_9', 'en-b2-11', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Strong public disagreement about a particular issue.”?', '["controversy","considerate","harmony","inquiry"]'::jsonb, 0, 'controversy (/ˈkɑːntrəvɝːsi/) → cuộc tranh cãi; sự bất đồng công khai', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_11_10', 'en-b2-11', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “following methods or ideas that are usual and widely accepted”?', '["confess","inquiry","conventional","registered"]'::jsonb, 2, 'conventional (/kənˈvenʃənəl/) → truyền thống; theo tập quán; thông thường', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_11_11', 'en-b2-11', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “not enough or not good enough for a particular purpose”?', '["inquiry","registered","confess","inadequate"]'::jsonb, 3, 'inadequate (/ɪnˈædɪkwət/) → không đủ; không tương xứng', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_11_12', 'en-b2-11', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “unfriendly or strongly opposed to someone or something”?', '["hostile","manner","harmony","dialect"]'::jsonb, 0, 'hostile (/ˈhɑːstəl/) → thù địch; chống đối', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_11_13', 'en-b2-11', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A peaceful relationship in which people cooperate and agree.”?', '["inquiry","acquaintance","confess","harmony"]'::jsonb, 3, 'harmony (/ˈhɑːrməni/) → sự hòa hợp; sự hòa thuận', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
