INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_11_18', 'en-b2-11', NULL, 'comprehensive_test', 'reading', NULL, 'Stronger international cooperation is needed to stop criminal groups that smuggle endangered animals across national borders.', 'Dựa vào câu trên, từ “smuggle” có nghĩa phù hợp nhất là gì?', '["khiên; vật che chắn","dễ nổ; có tính nổ","vận chuyển trái phép; buôn lậu; lén mang vào","gan"]'::jsonb, 2, 'smuggle: vận chuyển trái phép; buôn lậu; lén mang vào. Dịch cả câu: Cần tăng cường hợp tác quốc tế để ngăn chặn các băng nhóm tội phạm buôn lậu động vật có nguy cơ tuyệt chủng qua biên giới quốc gia.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_11_19', 'en-b2-11', NULL, 'comprehensive_test', 'reading', NULL, 'International cooperation is essential to resolve disputes over shared water resources and prevent future conflicts.', 'Dựa vào câu trên, từ “resolve” có nghĩa phù hợp nhất là gì?', '["sự thiếu hụt; tình trạng khan hiếm","trong nước; nội địa","tuyệt vời; xuất sắc","giải quyết; tháo gỡ"]'::jsonb, 3, 'resolve: giải quyết; tháo gỡ; kiên quyết; quyết tâm làm gì; sự kiên quyết; lòng quyết tâm. Dịch cả câu: Hợp tác quốc tế là yếu tố cốt lõi để giải quyết các tranh chấp về nguồn nước chung và ngăn ngừa những xung đột trong tương lai.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_11_20', 'en-b2-11', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should teach children to express disagreement in a respectful manner while encouraging independent thinking.', 'Dựa vào câu trên, từ “manner” có nghĩa phù hợp nhất là gì?', '["cách thức; phương pháp","sự tuyệt vọng","kinh độ","hình bầu dục; hình trứng"]'::jsonb, 0, 'manner: cách thức; phương pháp; thái độ; cách ứng xử; lễ phép; phép lịch sự. Dịch cả câu: Nhà trường nên dạy học sinh cách bày tỏ sự bất đồng theo hướng tôn trọng người khác, đồng thời khuyến khích tư duy độc lập.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_11_21', 'en-b2-11', NULL, 'comprehensive_test', 'reading', NULL, 'Investment in community centres may reduce social isolation among older residents who live alone.', 'Dựa vào câu trên, từ “isolation” có nghĩa phù hợp nhất là gì?', '["chuyên gia tư vấn tâm lý; người hướng dẫn","mờ ảo; thiếu ánh sáng","sự cô lập; sự tách biệt","vitamin"]'::jsonb, 2, 'isolation: sự cô lập; sự tách biệt; sự cách ly. Dịch cả câu: Đầu tư vào các trung tâm cộng đồng có thể làm giảm tình trạng cô lập xã hội ở những cư dân lớn tuổi sống một mình.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_11_22', 'en-b2-11', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bất công; không công bằng; phi lý”', '["unjust","congressman","unaware","accuracy"]'::jsonb, 0, 'bất công; không công bằng; phi lý → unjust (/ʌnˈdʒʌst/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_11_23', 'en-b2-11', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thú nhận; thú tội; khai nhận”', '["assist","confession","expectancy","confess"]'::jsonb, 3, 'thú nhận; thú tội; khai nhận → confess (/kənˈfes/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_11_24', 'en-b2-11', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “điều bình thường; chuẩn mực thông thường”', '["equip","baggy","lobby","norm"]'::jsonb, 3, 'điều bình thường; chuẩn mực thông thường → norm (/nɔːrm/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-12', 'en', 'Bài 12: Xã hội & Cộng đồng (5) - CEFR B2', 'CEFR B2', 'B2 · Xã hội', '26 từ vựng Tiếng Anh CEFR B2 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4012, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gang', 'en-b2-12', 'gang', '/ɡæŋ/', 'B2', 'băng đảng; nhóm tội phạm; nhóm bạn; tốp công nhân', 'n.', NULL, NULL, 'Khi chỉ nhóm bạn thì mang sắc thái thân mật, khẩu ngữ; trong ngữ cảnh trang trọng thường dùng để chỉ băng nhóm tội phạm.', 'Our whole gang meets at the park on Saturdays.', NULL, 'Cả nhóm bạn chúng tôi đều gặp nhau ở công viên vào các ngày thứ Bảy.', '{"wordId":"gang","ukIpa":"/ɡæŋ/","usIpa":"/ɡæŋ/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"A group of people involved in crime or violence.","vi":"băng đảng; nhóm tội phạm"},{"pos":"n.","en":"A group of friends or people working together.","vi":"nhóm bạn; tốp công nhân"}],"examples":[{"en":"Our whole gang meets at the park on Saturdays.","vi":"Cả nhóm bạn chúng tôi đều gặp nhau ở công viên vào các ngày thứ Bảy.","audioKind":"ex"},{"en":"Community programmes can reduce gang membership by offering young people educational support and meaningful employment opportunities.","vi":"Các chương trình cộng đồng có thể làm giảm tình trạng thanh thiếu niên gia nhập băng đảng bằng cách cung cấp hỗ trợ giáo dục và cơ hội việc làm ý nghĩa.","audioKind":"ex2"}],"collocations":[{"en":"a criminal gang","vi":"một băng đảng tội phạm"},{"en":"gang violence","vi":"bạo lực băng đảng"},{"en":"a gang of workers","vi":"một tốp công nhân"},{"en":"gang up on someone","vi":"hùa vào bắt nạt ai đó"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ nhóm bạn thì mang sắc thái thân mật, khẩu ngữ; trong ngữ cảnh trang trọng thường dùng để chỉ băng nhóm tội phạm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aggressive', 'en-b2-12', 'aggressive', '/əˈɡresɪv/', 'B2', 'hung hăng; hiếu chiến; hay gây sự; quyết đoán; xông xáo; mạnh mẽ', 'adj.', 'aggression (n.), aggressively (adv.), aggressiveness (n.), aggressor (n.)', 'Đồng nghĩa: hostile, combative, forceful · Trái nghĩa: peaceful, unassertive', 'Dùng miêu tả hành vi thường mang nghĩa tiêu cực; trong bối cảnh kinh doanh có thể chỉ sự quyết đoán tiến thủ.', 'The aggressive dog growled whenever anyone approached its gate.', NULL, 'Con chó hung dữ gầm gừ mỗi khi có ai lại gần cổng nhà nó.', '{"wordId":"aggressive","ukIpa":"/əˈɡresɪv/","usIpa":"/əˈɡresɪv/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Ready to argue, threaten, or attack.","vi":"hung hăng; hiếu chiến; hay gây sự"},{"pos":"adj.","en":"Using forceful, determined methods to achieve a goal.","vi":"quyết đoán; xông xáo; mạnh mẽ"}],"examples":[{"en":"The aggressive dog growled whenever anyone approached its gate.","vi":"Con chó hung dữ gầm gừ mỗi khi có ai lại gần cổng nhà nó.","audioKind":"ex"},{"en":"Aggressive marketing campaigns may increase sales, but they can also encourage unnecessary consumption and household debt.","vi":"Các chiến dịch tiếp thị mạnh mẽ có thể làm tăng doanh số bán hàng, nhưng chúng cũng có thể thúc đẩy tiêu dùng không cần thiết và nợ gia đình.","audioKind":"ex2"}],"collocations":[{"en":"aggressive behaviour","vi":"hành vi hung hăng"},{"en":"aggressive marketing","vi":"tiếp thị mạnh mẽ"},{"en":"an aggressive approach","vi":"cách tiếp cận quyết đoán"}],"wordFamily":["aggression (n.)","aggressively (adv.)","aggressiveness (n.)","aggressor (n.)"],"synonyms":["hostile","combative","forceful"],"antonyms":["peaceful","unassertive"],"tipVi":"Dùng miêu tả hành vi thường mang nghĩa tiêu cực; trong bối cảnh kinh doanh có thể chỉ sự quyết đoán tiến thủ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_adopt', 'en-b2-12', 'adopt', '/əˈdɑːpt/', 'B2', 'áp dụng; chọn theo; nhận nuôi; thông qua; phê chuẩn', 'v.', 'adoption (n.), adoptive (adj.), adopted (adj.)', NULL, 'Cần phân biệt "adopt" (áp dụng, nhận nuôi) với "adapt" (thích nghi, chuyển thể).', 'We adopted a simpler way to organise our shopping.', NULL, 'Chúng tôi đã áp dụng một cách đơn giản hơn để tổ chức việc mua sắm của mình.', '{"wordId":"adopt","ukIpa":"/əˈdɒpt/","usIpa":"/əˈdɑːpt/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"To start using a method, idea, or approach.","vi":"áp dụng; chọn theo"},{"pos":"v.","en":"To legally take someone else''s child into your family.","vi":"nhận nuôi"},{"pos":"v.","en":"To formally approve a proposal, policy, or rule.","vi":"thông qua; phê chuẩn"}],"examples":[{"en":"We adopted a simpler way to organise our shopping.","vi":"Chúng tôi đã áp dụng một cách đơn giản hơn để tổ chức việc mua sắm của mình.","audioKind":"ex"},{"en":"Governments should adopt long-term strategies that improve public transport rather than simply building more roads.","vi":"Chính phủ nên áp dụng các chiến lược dài hạn nhằm cải thiện giao thông công cộng thay vì chỉ đơn thuần xây thêm đường sá.","audioKind":"ex2"}],"collocations":[{"en":"adopt an approach","vi":"áp dụng một phương pháp"},{"en":"adopt a policy","vi":"thực thi một chính sách"},{"en":"adopt a child","vi":"nhận nuôi một đứa trẻ"},{"en":"adopt a resolution","vi":"thông qua một nghị quyết"}],"wordFamily":["adoption (n.)","adoptive (adj.)","adopted (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cần phân biệt \"adopt\" (áp dụng, nhận nuôi) với \"adapt\" (thích nghi, chuyển thể).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_brutal', 'en-b2-12', 'brutal', '/ˈbruːtəl/', 'B2', 'tàn bạo; dã man; hung ác; khắc nghiệt; dữ dội; thẳng thắn đến phũ phàng', 'adj.', 'brutality (n.), brutally (adv.), brutalise (v.)', 'Đồng nghĩa: cruel, merciless · Trái nghĩa: gentle, humane', 'brutal honesty chỉ sự thẳng thắn không nể nang đến mức khó chấp nhận.', 'The brutal winter left our garden bare and frozen.', NULL, 'Mùa đông khắc nghiệt khiến khuτη vườn của chúng tôi trở nên trơ trọi và đóng băng.', '{"wordId":"brutal","ukIpa":"/ˈbruːtəl/","usIpa":"/ˈbruːtəl/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Extremely cruel or violent","vi":"tàn bạo; dã man; hung ác"},{"pos":"adj.","en":"Extremely harsh, difficult, or direct","vi":"khắc nghiệt; dữ dội; thẳng thắn đến phũ phàng"}],"examples":[{"en":"The brutal winter left our garden bare and frozen.","vi":"Mùa đông khắc nghiệt khiến khuτη vườn của chúng tôi trở nên trơ trọi và đóng băng.","audioKind":"ex"},{"en":"Brutal treatment of prisoners violates human rights and undermines public trust in the justice system.","vi":"Đối xử tàn bạo với tù nhân vi phạm nhân quyền và làm suy giảm lòng tin của công chúng đối với hệ thống tư pháp.","audioKind":"ex2"}],"collocations":[{"en":"brutal treatment","vi":"đối xử tàn bạo"},{"en":"brutal attack","vi":"cuộc tấn công tàn bạo"},{"en":"brutal honesty","vi":"sự thẳng thắn phũ phàng"},{"en":"brutal winter","vi":"mùa đông khắc nghiệt"}],"wordFamily":["brutality (n.)","brutally (adv.)","brutalise (v.)"],"synonyms":["cruel","merciless"],"antonyms":["gentle","humane"],"tipVi":"brutal honesty chỉ sự thẳng thắn không nể nang đến mức khó chấp nhận.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_funeral', 'en-b2-12', 'funeral', '/ˈfjuːnərəl/', 'B2', 'tang lễ; đám tang', 'n.', NULL, NULL, 'Thường là danh từ đếm được: attend a funeral (tham dự tang lễ).', 'We brought white flowers to our neighbour''s funeral yesterday.', NULL, 'Hôm qua chúng tôi mang hoa trắng đến dự đám tang của người hàng xóm.', '{"wordId":"funeral","ukIpa":"/ˈfjuːnərəl/","usIpa":"/ˈfjuːnərəl/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"a ceremony held to remember and honour someone who has died","vi":"tang lễ; đám tang"}],"examples":[{"en":"We brought white flowers to our neighbour''s funeral yesterday.","vi":"Hôm qua chúng tôi mang hoa trắng đến dự đám tang của người hàng xóm.","audioKind":"ex"},{"en":"Funeral traditions vary across cultures, but they often provide families with emotional support during bereavement.","vi":"Các truyền thống tang lễ khác nhau giữa các nền văn hóa, nhưng chúng thường mang lại sự hỗ trợ tinh thần cho các gia đình trong lúc tang gia bối rối.","audioKind":"ex2"}],"collocations":[{"en":"attend a funeral","vi":"tham dự tang lễ"},{"en":"funeral service","vi":"lễ tang"},{"en":"funeral procession","vi":"đoàn đưa tang"},{"en":"funeral arrangements","vi":"sắp xếp tang lễ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ đếm được: attend a funeral (tham dự tang lễ).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_regardless', 'en-b2-12', 'regardless', '/rɪˈɡɑːrdləs/', 'B2', 'bất chấp; mặc dù; bất kể', 'adv.', NULL, 'Đồng nghĩa: anyway, nevertheless', 'regardless là trạng từ; khi đi với danh từ thì dùng regardless of.', 'Rain was forecast, but we went hiking regardless.', NULL, 'Dự báo có mưa, nhưng chúng tôi vẫn đi leo núi.', '{"wordId":"regardless","ukIpa":"/rɪˈɡɑːdləs/","usIpa":"/rɪˈɡɑːrdləs/","cefr":"B2","topic":"society","senses":[{"pos":"adv.","en":"Despite difficulties, objections, or other circumstances.","vi":"bất chấp; mặc dù; bất kể"}],"examples":[{"en":"Rain was forecast, but we went hiking regardless.","vi":"Dự báo có mưa, nhưng chúng tôi vẫn đi leo núi.","audioKind":"ex"},{"en":"Public libraries should provide access to reliable information for everyone, regardless of income or educational background.","vi":"Các thư viện công cộng nên cung cấp khả năng tiếp cận thông tin đáng tin cậy cho mọi người, bất kể thu nhập hay nền tảng giáo dục.","audioKind":"ex2"}],"collocations":[{"en":"regardless of age","vi":"bất kể tuổi tác"},{"en":"regardless of cost","vi":"bất chấp chi phí"},{"en":"carry on regardless","vi":"vẫn tiếp tục bất chấp khó khăn"}],"wordFamily":[],"synonyms":["anyway","nevertheless"],"antonyms":[],"tipVi":"regardless là trạng từ; khi đi với danh từ thì dùng regardless of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_loyal', 'en-b2-12', 'loyal', '/ˈlɔɪəl/', 'B2', 'trung thành; trung thực', 'adj.', 'loyalty (n.), loyally (adv.), disloyal (adj.), disloyalty (n.)', 'Đồng nghĩa: faithful, devoted · Trái nghĩa: disloyal, unfaithful', 'Biểu thị sự trung thành với ai hoặc tổ chức nào thì dùng loyal to, không dùng loyal with.', 'Our loyal dog waits by the door every evening.', NULL, 'Chú chó trung thành của chúng tôi đứng đợi bên cửa mỗi buổi chiều tối.', '{"wordId":"loyal","ukIpa":"/ˈlɔɪəl/","usIpa":"/ˈlɔɪəl/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Continuing to support someone or something, even during difficulties.","vi":"trung thành; trung thực"}],"examples":[{"en":"Our loyal dog waits by the door every evening.","vi":"Chú chó trung thành của chúng tôi đứng đợi bên cửa mỗi buổi chiều tối.","audioKind":"ex"},{"en":"Companies that treat their employees fairly are more likely to retain a loyal and productive workforce.","vi":"Các công ty đối xử công bằng với nhân viên có nhiều khả năng giữ chân được lực lượng lao động trung thành và làm việc hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"loyal to","vi":"trung thành với"},{"en":"a loyal customer","vi":"khách hàng trung thành"},{"en":"remain loyal","vi":"giữ lòng trung thành"},{"en":"a loyal supporter","vi":"người ủng hộ trung thành"}],"wordFamily":["loyalty (n.)","loyally (adv.)","disloyal (adj.)","disloyalty (n.)"],"synonyms":["faithful","devoted"],"antonyms":["disloyal","unfaithful"],"tipVi":"Biểu thị sự trung thành với ai hoặc tổ chức nào thì dùng loyal to, không dùng loyal with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aid', 'en-b2-12', 'aid', '/eɪd/', 'B2', 'sự viện trợ; sự cứu trợ; tiền trợ giúp; giúp đỡ; hỗ trợ; thúc đẩy; thiết bị hỗ trợ; công cụ trợ giúp', 'n.', 'aided (adj.), unaided (adj.)', 'Đồng nghĩa: help, assistance, support', 'Nghĩa viện trợ thường không đếm được; nghĩa công cụ hỗ trợ thì đếm được, ví dụ a hearing aid.', 'Volunteers brought food and medical aid to the village.', NULL, 'Các tình nguyện viên đã mang lương thực và viện trợ y tế đến cho ngôi làng.', '{"wordId":"aid","ukIpa":"/eɪd/","usIpa":"/eɪd/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"Help provided through money, supplies, services, or practical support.","vi":"sự viện trợ; sự cứu trợ; tiền trợ giúp"},{"pos":"v.","en":"To help someone or make a process easier.","vi":"giúp đỡ; hỗ trợ; thúc đẩy"},{"pos":"n.","en":"An object or device that helps someone do something.","vi":"thiết bị hỗ trợ; công cụ trợ giúp"}],"examples":[{"en":"Volunteers brought food and medical aid to the village.","vi":"Các tình nguyện viên đã mang lương thực và viện trợ y tế đến cho ngôi làng.","audioKind":"ex"},{"en":"International aid can improve access to clean water, but lasting progress also requires investment in local infrastructure.","vi":"Viện trợ quốc tế có thể cải thiện khả năng tiếp cận nguồn nước sạch, nhưng sự tiến bộ lâu dài cũng đòi hỏi phải đầu tư vào cơ sở hạ tầng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"humanitarian aid","vi":"viện trợ nhân đạo"},{"en":"financial aid","vi":"hỗ trợ tài chính"},{"en":"first aid","vi":"sơ cứu"},{"en":"hearing aid","vi":"máy trợ thính"}],"wordFamily":["aided (adj.)","unaided (adj.)"],"synonyms":["help","assistance","support"],"antonyms":[],"tipVi":"Nghĩa viện trợ thường không đếm được; nghĩa công cụ hỗ trợ thì đếm được, ví dụ a hearing aid.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_contribution', 'en-b2-12', 'contribution', '/ˌkɑːntrɪˈbjuːʃən/', 'B2', 'sự đóng góp; phần đóng góp; khoản tiền đóng góp; vật phẩm quyên góp; bài viết; bài cộng tác', 'n.', 'contribute (v.), contributor (n.), contributory (adj.)', NULL, 'Thường dùng make a contribution to; sau to đi với danh từ hoặc danh động từ.', 'Your contribution helped us finish the garden before sunset.', NULL, 'Sự đóng góp của bạn đã giúp chúng tôi hoàn thành khu vườn trước khi trời tối.', '{"wordId":"contribution","ukIpa":"/ˌkɒntrɪˈbjuːʃən/","usIpa":"/ˌkɑːntrɪˈbjuːʃən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"Something done or provided to help achieve a shared result.","vi":"sự đóng góp; phần đóng góp"},{"pos":"n.","en":"Money or goods given to support a person or cause.","vi":"khoản tiền đóng góp; vật phẩm quyên góp"},{"pos":"n.","en":"A piece of writing supplied for a publication.","vi":"bài viết; bài cộng tác"}],"examples":[{"en":"Your contribution helped us finish the garden before sunset.","vi":"Sự đóng góp của bạn đã giúp chúng tôi hoàn thành khu vườn trước khi trời tối.","audioKind":"ex"},{"en":"Public libraries make a valuable contribution to lifelong learning by providing free access to information.","vi":"Các thư viện công cộng đóng góp quý giá cho việc học tập suốt đời bằng cách cung cấp quyền truy cập miễn phí vào thông tin.","audioKind":"ex2"}],"collocations":[{"en":"make a contribution to","vi":"đóng góp vào"},{"en":"a significant contribution","vi":"sự đóng góp đáng kể"},{"en":"a voluntary contribution","vi":"khoản đóng góp tự nguyện"}],"wordFamily":["contribute (v.)","contributor (n.)","contributory (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng make a contribution to; sau to đi với danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_donation', 'en-b2-12', 'donation', '/doʊˈneɪʃən/', 'B2', 'khoản quyên góp; khoản đóng góp; vật phẩm từ thiện', 'n.', 'donate (v.), donor (n.)', 'Đồng nghĩa: contribution', 'Thường dùng make a donation to để chỉ việc quyên góp cho ai hoặc tổ chức nào.', 'We made a small donation to the animal shelter.', NULL, 'Chúng tôi đã đóng góp một khoản tiền nhỏ cho quỹ cứu trợ động vật.', '{"wordId":"donation","ukIpa":"/dəʊˈneɪʃən/","usIpa":"/doʊˈneɪʃən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"Money or goods given to help a person or organisation.","vi":"khoản quyên góp; khoản đóng góp; vật phẩm từ thiện"}],"examples":[{"en":"We made a small donation to the animal shelter.","vi":"Chúng tôi đã đóng góp một khoản tiền nhỏ cho quỹ cứu trợ động vật.","audioKind":"ex"},{"en":"Regular donations from local businesses enable the charity to provide free meals for vulnerable residents.","vi":"Các khoản đóng góp thường xuyên từ các doanh nghiệp địa phương giúp tổ chức từ thiện này cung cấp các bữa ăn miễn phí cho những cư dân có hoàn cảnh khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"make a donation","vi":"quyên góp; tặng quà"},{"en":"generous donation","vi":"khoản quyên góp hào phóng"},{"en":"blood donation","vi":"hiến máu"}],"wordFamily":["donate (v.)","donor (n.)"],"synonyms":["contribution"],"antonyms":[],"tipVi":"Thường dùng make a donation to để chỉ việc quyên góp cho ai hoặc tổ chức nào.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_settlement', 'en-b2-12', 'settlement', '/ˈsetlmənt/', 'B2', 'thỏa thuận dàn xếp; sự hòa giải (kết thúc tranh chấp); vùng định cư; khu dân cư; nơi cư trú; sự thanh toán; sự trả nợ', 'n.', 'settle (v.), settler (n.), settled (adj.)', 'Đồng nghĩa: agreement', 'Có thể chỉ thỏa thuận giải quyết tranh chấp, hoặc chỉ nơi con người sinh sống lập nghiệp.', 'The neighbours finally reached a settlement over the damaged fence.', NULL, 'Những người hàng xóm cuối cùng cũng đạt được thỏa thuận dàn xếp về phần hàng rào bị hỏng.', '{"wordId":"settlement","ukIpa":"/ˈsetlmənt/","usIpa":"/ˈsetlmənt/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"An agreement that ends a dispute.","vi":"thỏa thuận dàn xếp; sự hòa giải (kết thúc tranh chấp)"},{"pos":"n.","en":"A place where people establish a community.","vi":"vùng định cư; khu dân cư; nơi cư trú"},{"pos":"n.","en":"The payment of money owed.","vi":"sự thanh toán; sự trả nợ"}],"examples":[{"en":"The neighbours finally reached a settlement over the damaged fence.","vi":"Những người hàng xóm cuối cùng cũng đạt được thỏa thuận dàn xếp về phần hàng rào bị hỏng.","audioKind":"ex"},{"en":"Ancient settlements often developed near rivers because reliable water supplies supported farming, trade, and daily life.","vi":"Các khu định cư cổ đại thường phát triển gần các con sông vì nguồn nước ổn định hỗ trợ cho nông nghiệp, thương mại và đời sống hằng ngày.","audioKind":"ex2"}],"collocations":[{"en":"reach a settlement","vi":"đạt được thỏa thuận"},{"en":"a peace settlement","vi":"thỏa thuận hòa bình"},{"en":"a rural settlement","vi":"vùng định cư nông thôn"},{"en":"settlement of debts","vi":"thanh toán các khoản nợ"}],"wordFamily":["settle (v.)","settler (n.)","settled (adj.)"],"synonyms":["agreement"],"antonyms":[],"tipVi":"Có thể chỉ thỏa thuận giải quyết tranh chấp, hoặc chỉ nơi con người sinh sống lập nghiệp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_formal', 'en-b2-12', 'formal', '/ˈfɔːrməl/', 'B2', 'chính thức; theo quy chuẩn; trang trọng; trang nghiêm; chính quy; bài bản', 'adj.', 'formally (adv.), formality (n.), formalise (v.), informal (adj.)', 'Đồng nghĩa: official · Trái nghĩa: informal, casual', 'formal khác với former: từ đầu nghĩa là ''chính thức'', từ sau nghĩa là ''trước đây''.', 'You need a formal invitation to attend the ceremony.', NULL, 'Bạn cần có một lời mời chính thức để tham dự buổi lễ.', '{"wordId":"formal","ukIpa":"/ˈfɔːməl/","usIpa":"/ˈfɔːrməl/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Following established rules or officially recognised procedures.","vi":"chính thức; theo quy chuẩn"},{"pos":"adj.","en":"Suitable for serious occasions rather than relaxed situations.","vi":"trang trọng; trang nghiêm"},{"pos":"adj.","en":"Organised and structured, especially within an educational institution.","vi":"chính quy; bài bản"}],"examples":[{"en":"You need a formal invitation to attend the ceremony.","vi":"Bạn cần có một lời mời chính thức để tham dự buổi lễ.","audioKind":"ex"},{"en":"Formal education provides essential knowledge, while practical experience helps students apply what they have learned.","vi":"Giáo dục chính quy cung cấp những kiến thức nền tảng, trong khi kinh nghiệm thực tế giúp học sinh vận dụng những gì đã học.","audioKind":"ex2"}],"collocations":[{"en":"formal agreement","vi":"thỏa thuận chính thức"},{"en":"formal complaint","vi":"đơn khiếu nại chính thức"},{"en":"formal education","vi":"giáo dục chính quy"},{"en":"formal dress","vi":"trang phục trang trọng"}],"wordFamily":["formally (adv.)","formality (n.)","formalise (v.)","informal (adj.)"],"synonyms":["official"],"antonyms":["informal","casual"],"tipVi":"formal khác với former: từ đầu nghĩa là ''chính thức'', từ sau nghĩa là ''trước đây''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_independence', 'en-b2-12', 'independence', '/ˌɪndɪˈpendəns/', 'B2', 'sự tự lập; tính tự chủ; nền độc lập của quốc gia', 'n.', 'independent (adj), independently (adv), depend (v), dependence (n)', 'Đồng nghĩa: autonomy, self-reliance · Trái nghĩa: dependence', 'Từ independence thường không đếm được; cụm independence from dùng để chỉ sự tự do, không phụ thuộc hoặc không chịu sự kiểm soát của ai.', 'Learning to cook gave him a sense of independence.', NULL, 'Việc học nấu ăn đã mang lại cho anh ấy cảm giác tự lập.', '{"wordId":"independence","ukIpa":"/ˌɪndɪˈpendəns/","usIpa":"/ˌɪndɪˈpendəns/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"The ability to live or act without relying on others.","vi":"sự tự lập; tính tự chủ"},{"pos":"n.","en":"A country''s freedom from control by another country.","vi":"nền độc lập của quốc gia"}],"examples":[{"en":"Learning to cook gave him a sense of independence.","vi":"Việc học nấu ăn đã mang lại cho anh ấy cảm giác tự lập.","audioKind":"ex"},{"en":"Accessible housing can help older people maintain their independence while remaining connected to their local communities.","vi":"Nhà ở phù hợp và dễ tiếp cận có thể giúp người cao tuổi duy trì sự tự lập trong cuộc sống đồng thời giữ vững sự gắn kết với cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"financial independence","vi":"sự độc lập tài chính"},{"en":"gain independence","vi":"giành được độc lập"},{"en":"maintain independence","vi":"duy trì sự tự chủ"},{"en":"independence from","vi":"sự độc lập khỏi..."}],"wordFamily":["independent (adj)","independently (adv)","depend (v)","dependence (n)"],"synonyms":["autonomy","self-reliance"],"antonyms":["dependence"],"tipVi":"Từ independence thường không đếm được; cụm independence from dùng để chỉ sự tự do, không phụ thuộc hoặc không chịu sự kiểm soát của ai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_panel', 'en-b2-12', 'panel', '/ˈpænəl/', 'B2', 'ban hội thẩm; hội đồng chuyên gia; tấm; mảng (gỗ, kính, v.v.); bảng điều khiển; mặt đồng hồ', 'n.', 'panelling (n.), panellist (n.)', NULL, 'Nhóm chuyên gia dùng "a panel of experts"; thành viên trong hội đồng gọi là "panellist".', 'The panel listened carefully as each student presented an idea.', NULL, 'Hội đồng giám khảo đã lắng nghe chăm chú khi từng học sinh trình bày ý tưởng của mình.', '{"wordId":"panel","ukIpa":"/ˈpænəl/","usIpa":"/ˈpænəl/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"a group chosen to discuss, judge, or advise","vi":"ban hội thẩm; hội đồng chuyên gia"},{"pos":"n.","en":"a flat piece forming part of a surface","vi":"tấm; mảng (gỗ, kính, v.v.)"},{"pos":"n.","en":"a surface containing controls or instruments","vi":"bảng điều khiển; mặt đồng hồ"}],"examples":[{"en":"The panel listened carefully as each student presented an idea.","vi":"Hội đồng giám khảo đã lắng nghe chăm chú khi từng học sinh trình bày ý tưởng của mình.","audioKind":"ex"},{"en":"An independent panel should assess the environmental impact of major construction projects before work begins.","vi":"Một hội đồng độc lập nên đánh giá tác động môi trường của các dự án xây dựng lớn trước khi công trình được khởi động.","audioKind":"ex2"}],"collocations":[{"en":"a panel of experts","vi":"hội đồng chuyên gia"},{"en":"a judging panel","vi":"ban giám khảo"},{"en":"control panel","vi":"bảng điều khiển"},{"en":"wooden panel","vi":"tấm gỗ ốp"}],"wordFamily":["panelling (n.)","panellist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nhóm chuyên gia dùng \"a panel of experts\"; thành viên trong hội đồng gọi là \"panellist\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bless', 'en-b2-12', 'bless', '/bles/', 'B2', 'cầu phước; ban phúc; ban tặng; có phước', 'v.', 'blessing (n.), blessed (adj.)', 'Trái nghĩa: curse', 'be blessed with biểu thị có phước sở hữu một ưu điểm hoặc nguồn lực nào đó.', 'The priest paused to bless the family before their journey.', NULL, 'Vị linh mục dừng lại để cầu phước cho gia đình trước chuyến hành trình của họ.', '{"wordId":"bless","ukIpa":"/bles/","usIpa":"/bles/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"To ask for divine protection or favour for someone or something.","vi":"cầu phước; ban phúc"},{"pos":"v.","en":"To give someone something good or fortunate.","vi":"ban tặng; có phước"}],"examples":[{"en":"The priest paused to bless the family before their journey.","vi":"Vị linh mục dừng lại để cầu phước cho gia đình trước chuyến hành trình của họ.","audioKind":"ex"},{"en":"Regions blessed with abundant sunshine can develop solar energy to meet a growing share of their electricity needs.","vi":"Những vùng đất được thiên nhiên ban tặng nguồn ánh sáng dồi dào có thể phát triển năng lượng mặt trời để đáp ứng nhu cầu điện năng ngày càng tăng.","audioKind":"ex2"}],"collocations":[{"en":"bless someone","vi":"cầu phúc cho ai đó"},{"en":"be blessed with","vi":"có phước có được"},{"en":"bless you","vi":"chúc bạn bình an"}],"wordFamily":["blessing (n.)","blessed (adj.)"],"synonyms":[],"antonyms":["curse"],"tipVi":"be blessed with biểu thị có phước sở hữu một ưu điểm hoặc nguồn lực nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tragedy', 'en-b2-12', 'tragedy', '/ˈtrædʒədi/', 'B2', 'thảm kịch; tai họa; tai nạn đau lòng; kịch bi thảm; tác phẩm bi kịch', 'n.', 'tragic (adj.), tragically (adv.)', 'Đồng nghĩa: disaster, catastrophe · Trái nghĩa: comedy', 'Vừa chỉ tai họa ngoài đời thực, vừa chỉ kịch bi thảm; nghĩa sau đối lập với comedy.', 'The whole village came together after the tragedy.', NULL, 'Cả làng đã quây quần lại bên nhau sau thảm kịch đó.', '{"wordId":"tragedy","ukIpa":"/ˈtrædʒədi/","usIpa":"/ˈtrædʒədi/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"An event causing great suffering, sadness, or loss.","vi":"thảm kịch; tai họa; tai nạn đau lòng"},{"pos":"n.","en":"A serious play or story ending in suffering or death.","vi":"kịch bi thảm; tác phẩm bi kịch"}],"examples":[{"en":"The whole village came together after the tragedy.","vi":"Cả làng đã quây quần lại bên nhau sau thảm kịch đó.","audioKind":"ex"},{"en":"Improved road design and stricter safety regulations can help prevent the tragedy of avoidable traffic deaths.","vi":"Việc cải thiện thiết kế đường xá và các quy định an toàn nghiêm ngặt hơn có thể giúp ngăn chặn thảm kịch tử vong do tai nạn giao thông có thể tránh được.","audioKind":"ex2"}],"collocations":[{"en":"a terrible tragedy","vi":"một thảm kịch khủng khiếp"},{"en":"prevent a tragedy","vi":"ngăn chặn một thảm kịch"},{"en":"tragedy strikes","vi":"tai họa giáng xuống"},{"en":"classical tragedy","vi":"bi kịch cổ điển"}],"wordFamily":["tragic (adj.)","tragically (adv.)"],"synonyms":["disaster","catastrophe"],"antonyms":["comedy"],"tipVi":"Vừa chỉ tai họa ngoài đời thực, vừa chỉ kịch bi thảm; nghĩa sau đối lập với comedy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_assembly', 'en-b2-12', 'assembly', '/əˈsembli/', 'B2', 'cuộc họp; sự tụ họp; sự lắp ráp; khâu ráp nối; hội đồng; cơ quan lập pháp', 'n.', 'assemble (v.), disassemble (v.)', 'Đồng nghĩa: gathering', 'Nghĩa tập trung, hội họp thường đếm được; nghĩa lắp ráp thường không đếm được.', 'The whole school gathered in the hall for assembly.', NULL, 'Toàn trường tập trung tại hội trường để tham gia buổi sinh hoạt toàn trường.', '{"wordId":"assembly","ukIpa":"/əˈsembli/","usIpa":"/əˈsembli/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"A gathering of people for a shared purpose.","vi":"cuộc họp; sự tụ họp"},{"pos":"n.","en":"The process of joining parts to make something complete.","vi":"sự lắp ráp; khâu ráp nối"},{"pos":"n.","en":"A group elected to discuss public matters and make laws.","vi":"hội đồng; cơ quan lập pháp"}],"examples":[{"en":"The whole school gathered in the hall for assembly.","vi":"Toàn trường tập trung tại hội trường để tham gia buổi sinh hoạt toàn trường.","audioKind":"ex"},{"en":"Automation has reduced the time required for vehicle assembly, although skilled workers remain essential for quality control.","vi":"Tự động hóa đã giảm bớt thời gian cần thiết cho việc lắp ráp xe hơi, mặc dù công nhân lành nghề vẫn đóng vai trò cốt lõi trong việc kiểm soát chất lượng.","audioKind":"ex2"}],"collocations":[{"en":"school assembly","vi":"buổi sinh hoạt trường"},{"en":"assembly line","vi":"dây chuyền lắp ráp"},{"en":"legislative assembly","vi":"hội đồng lập pháp"},{"en":"freedom of assembly","vi":"quyền tự do hội họp"}],"wordFamily":["assemble (v.)","disassemble (v.)"],"synonyms":["gathering"],"antonyms":[],"tipVi":"Nghĩa tập trung, hội họp thường đếm được; nghĩa lắp ráp thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_respectful', 'en-b2-12', 'respectful', '/rɪˈspektfəl/', 'B2', 'biểu lộ sự tôn trọng; lễ phép; kính cẩn', 'adj.', 'respect (n.), respectfully (adv.), disrespectful (adj.)', 'Đồng nghĩa: courteous, polite · Trái nghĩa: disrespectful, rude', 'respectful mang nghĩa tôn trọng người khác; respectable mang nghĩa đáng kính trọng, đáng nể.', 'The children remained respectful while their grandmother was speaking.', NULL, 'Bọn trẻ vẫn giữ thái độ kính cẩn khi bà của chúng đang nói chuyện.', '{"wordId":"respectful","ukIpa":"/rɪˈspektfəl/","usIpa":"/rɪˈspektfəl/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"showing politeness and consideration towards someone or something","vi":"biểu lộ sự tôn trọng; lễ phép; kính cẩn"}],"examples":[{"en":"The children remained respectful while their grandmother was speaking.","vi":"Bọn trẻ vẫn giữ thái độ kính cẩn khi bà của chúng đang nói chuyện.","audioKind":"ex"},{"en":"Respectful discussion enables students to consider opposing views without allowing disagreement to damage their relationships.","vi":"Buổi thảo luận tôn trọng lẫn nhau giúp học sinh cân nhắc các quan điểm trái chiều mà không để sự bất đồng làm tổn hại đến mối quan hệ của họ.","audioKind":"ex2"}],"collocations":[{"en":"respectful attitude","vi":"thái độ tôn trọng"},{"en":"respectful of others","vi":"tôn trọng người khác"},{"en":"respectful silence","vi":"sự im lặng kính cẩn"}],"wordFamily":["respect (n.)","respectfully (adv.)","disrespectful (adj.)"],"synonyms":["courteous","polite"],"antonyms":["disrespectful","rude"],"tipVi":"respectful mang nghĩa tôn trọng người khác; respectable mang nghĩa đáng kính trọng, đáng nể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gambler', 'en-b2-12', 'gambler', '/ˈɡæmblər/', 'B2', 'con bạc; người đánh bạc; người thích mạo hiểm để đạt phần thưởng', 'n.', 'gamble (v.), gambling (n.)', NULL, 'gamble là hành động đánh bạc hoặc mạo hiểm; gambler chỉ người thực hiện hành động đó.', 'The gambler left the table after losing his money.', NULL, 'Tên con bạc đã rời khỏi bàn chơi sau khi thua sạch tiền.', '{"wordId":"gambler","ukIpa":"/ˈɡæmblə/","usIpa":"/ˈɡæmblər/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"Someone who risks money on uncertain outcomes","vi":"con bạc; người đánh bạc"},{"pos":"n.","en":"Someone willing to take risks for possible rewards","vi":"người thích mạo hiểm để đạt phần thưởng"}],"examples":[{"en":"The gambler left the table after losing his money.","vi":"Tên con bạc đã rời khỏi bàn chơi sau khi thua sạch tiền.","audioKind":"ex"},{"en":"Support services can help a problem gambler regain financial stability and rebuild relationships with family members.","vi":"Các dịch vụ hỗ trợ có thể giúp một người nghiện cờ bạc khôi phục sự ổn định tài chính và xây dựng lại mối quan hệ với các thành viên trong gia đình.","audioKind":"ex2"}],"collocations":[{"en":"problem gambler","vi":"người có vấn đề về cờ bạc"},{"en":"compulsive gambler","vi":"người nghiện cờ bạc"},{"en":"professional gambler","vi":"con bạc chuyên nghiệp"}],"wordFamily":["gamble (v.)","gambling (n.)"],"synonyms":[],"antonyms":[],"tipVi":"gamble là hành động đánh bạc hoặc mạo hiểm; gambler chỉ người thực hiện hành động đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_injustice', 'en-b2-12', 'injustice', '/ɪnˈdʒʌstɪs/', 'B2', 'sự bất công; hành động bất công', 'n.', 'justice (n.), unjust (adj.), unjustly (adv.)', 'Đồng nghĩa: unfairness, inequity · Trái nghĩa: justice, fairness', 'Khi chỉ chung chung sự bất công thì không đếm được; khi chỉ một vụ việc bất công cụ thể thì có thể dùng an injustice.', 'We challenged the injustice of excluding her from the team.', NULL, 'Chúng tôi đã lên tiếng phản đối sự bất công khi cô ấy bị loại khỏi đội.', '{"wordId":"injustice","ukIpa":"/ɪnˈdʒʌstɪs/","usIpa":"/ɪnˈdʒʌstɪs/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"Unfair treatment or a particular example of it.","vi":"sự bất công; hành động bất công"}],"examples":[{"en":"We challenged the injustice of excluding her from the team.","vi":"Chúng tôi đã lên tiếng phản đối sự bất công khi cô ấy bị loại khỏi đội.","audioKind":"ex"},{"en":"Access to affordable legal advice is essential for people seeking to challenge injustice in the workplace.","vi":"Khả năng tiếp cận dịch vụ tư vấn pháp lý có chi phí hợp lý là điều thiết yếu đối với những người muốn đấu tranh chống lại sự bất công nơi công sở.","audioKind":"ex2"}],"collocations":[{"en":"social injustice","vi":"bất công xã hội"},{"en":"a sense of injustice","vi":"cảm giác bất công"},{"en":"suffer an injustice","vi":"chịu đựng sự đối xử bất công"},{"en":"challenge injustice","vi":"đấu tranh chống lại sự bất công"}],"wordFamily":["justice (n.)","unjust (adj.)","unjustly (adv.)"],"synonyms":["unfairness","inequity"],"antonyms":["justice","fairness"],"tipVi":"Khi chỉ chung chung sự bất công thì không đếm được; khi chỉ một vụ việc bất công cụ thể thì có thể dùng an injustice.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_urge', 'en-b2-12', 'urge', '/ɝːdʒ/', 'B2', 'thúc giục; nài nỉ; khuyên răn mạnh mẽ; sự thèm muốn mãnh liệt; sự thôi thúc', 'v.', 'urging (n.)', NULL, 'Động từ dùng cấu trúc urge sb to do, còn danh từ dùng an urge to do.', 'I resisted the urge to eat another biscuit.', NULL, 'Tôi đã kìm nén sự thôi thúc muốn ăn thêm một chiếc bánh quy nữa.', '{"wordId":"urge","ukIpa":"/ɜːdʒ/","usIpa":"/ɝːdʒ/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"To strongly encourage someone to do something.","vi":"thúc giục; nài nỉ; khuyên răn mạnh mẽ"},{"pos":"n.","en":"A strong desire to do something.","vi":"sự thèm muốn mãnh liệt; sự thôi thúc"}],"examples":[{"en":"I resisted the urge to eat another biscuit.","vi":"Tôi đã kìm nén sự thôi thúc muốn ăn thêm một chiếc bánh quy nữa.","audioKind":"ex"},{"en":"Health experts urge governments to invest in preventive care rather than focus solely on treating diseases.","vi":"Các chuyên gia y tế thúc giục chính phủ đầu tư vào công tác chăm sóc phòng ngừa thay vì chỉ tập trung chữa bệnh.","audioKind":"ex2"}],"collocations":[{"en":"urge someone to do something","vi":"thúc giục ai đó làm điều gì"},{"en":"a strong urge to","vi":"thôi thúc mạnh mẽ làm gì"},{"en":"resist the urge","vi":"kìm nén sự thôi thúc"},{"en":"urge caution","vi":"khuyên nên thận trọng"}],"wordFamily":["urging (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ dùng cấu trúc urge sb to do, còn danh từ dùng an urge to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_voluntary', 'en-b2-12', 'voluntary', '/ˈvɑːlənteri/', 'B2', 'tự nguyện; không bắt buộc; tình nguyện; không nhận thù lao', 'adj.', 'voluntarily (adv.), volunteer (n.), volunteer (v.), involuntary (adj.)', 'Đồng nghĩa: optional, unpaid · Trái nghĩa: compulsory, involuntary', 'voluntary là tính từ; từ chỉ "tình nguyện viên" là volunteer.', 'Joining the weekend walking group is completely voluntary.', NULL, 'Tham gia nhóm đi bộ cuối tuần hoàn toàn là tự nguyện.', '{"wordId":"voluntary","ukIpa":"/ˈvɒləntri/","usIpa":"/ˈvɑːlənteri/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"done by choice rather than because it is required","vi":"tự nguyện; không bắt buộc"},{"pos":"adj.","en":"done without payment to help people or an organisation","vi":"tình nguyện; không nhận thù lao"}],"examples":[{"en":"Joining the weekend walking group is completely voluntary.","vi":"Tham gia nhóm đi bộ cuối tuần hoàn toàn là tự nguyện.","audioKind":"ex"},{"en":"Voluntary work can help young people develop practical skills while contributing to their local communities.","vi":"Công việc tình nguyện có thể giúp người trẻ phát triển các kỹ năng thực tế đồng thời đóng góp cho cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"voluntary work","vi":"công việc tình nguyện"},{"en":"voluntary participation","vi":"sự tham gia tự nguyện"},{"en":"voluntary organisation","vi":"tổ chức tình nguyện"},{"en":"voluntary contributions","vi":"khoản đóng góp tự nguyện"}],"wordFamily":["voluntarily (adv.)","volunteer (n.)","volunteer (v.)","involuntary (adj.)"],"synonyms":["optional","unpaid"],"antonyms":["compulsory","involuntary"],"tipVi":"voluntary là tính từ; từ chỉ \"tình nguyện viên\" là volunteer.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_interfere', 'en-b2-12', 'interfere', '/ˌɪntərˈfɪr/', 'B2', 'can thiệp; xen vào; cản trở; gây ảnh hưởng', 'v.', 'interference (n.), interfering (adj.)', 'Đồng nghĩa: meddle, intrude', 'interfere đi với "in" thường chỉ việc can thiệp chuyện riêng; đi với "with" thường chỉ việc cản trở quá trình nào đó.', 'Please don''t interfere when I''m teaching the puppy to sit.', NULL, 'Xin đừng can thiệp khi tôi đang dạy chú cún ngồi.', '{"wordId":"interfere","ukIpa":"/ˌɪntəˈfɪə/","usIpa":"/ˌɪntərˈfɪr/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"To become involved in others'' affairs without being wanted.","vi":"can thiệp; xen vào"},{"pos":"v.","en":"To prevent something from working or progressing properly.","vi":"cản trở; gây ảnh hưởng"}],"examples":[{"en":"Please don''t interfere when I''m teaching the puppy to sit.","vi":"Xin đừng can thiệp khi tôi đang dạy chú cún ngồi.","audioKind":"ex"},{"en":"Excessive background noise can interfere with students'' concentration and reduce their ability to absorb new information.","vi":"Tiếng ồn nền quá mức có thể cản trở sự tập trung của học sinh và làm giảm khả năng tiếp thu thông tin mới.","audioKind":"ex2"}],"collocations":[{"en":"interfere in someone''s affairs","vi":"can thiệp vào việc của ai đó"},{"en":"interfere with concentration","vi":"cản trở sự tập trung"},{"en":"interfere with sleep","vi":"cản trở giấc ngủ"}],"wordFamily":["interference (n.)","interfering (adj.)"],"synonyms":["meddle","intrude"],"antonyms":[],"tipVi":"interfere đi với \"in\" thường chỉ việc can thiệp chuyện riêng; đi với \"with\" thường chỉ việc cản trở quá trình nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_participant', 'en-b2-12', 'participant', '/pɑːrˈtɪsɪpənt/', 'B2', 'người tham gia; người tham dự', 'n.', 'participate (v.), participation (n.), participatory (adj.)', NULL, 'Thường đóng vai trò danh từ; diễn đạt người tham gia một hoạt động nào đó dùng participant in.', 'Each participant brought a homemade dish to the cooking workshop.', NULL, 'Mỗi người tham gia đã mang theo một món ăn tự nấu đến buổi hội thảo nấu ăn.', '{"wordId":"participant","ukIpa":"/pɑːˈtɪsɪpənt/","usIpa":"/pɑːrˈtɪsɪpənt/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"Someone who takes part in an activity or event.","vi":"người tham gia; người tham dự"}],"examples":[{"en":"Each participant brought a homemade dish to the cooking workshop.","vi":"Mỗi người tham gia đã mang theo một món ăn tự nấu đến buổi hội thảo nấu ăn.","audioKind":"ex"},{"en":"Every participant in the research project gave informed consent before sharing information about their daily exercise habits.","vi":"Mọi người tham gia dự án nghiên cứu đều đã đưa ra sự đồng thuận có ý thức trước khi chia sẻ thông tin về thói quen tập thể dục hàng ngày của họ.","audioKind":"ex2"}],"collocations":[{"en":"active participant","vi":"người tham gia tích cực"},{"en":"participant in a study","vi":"người tham gia nghiên cứu"},{"en":"study participants","vi":"các đối tượng nghiên cứu"}],"wordFamily":["participate (v.)","participation (n.)","participatory (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường đóng vai trò danh từ; diễn đạt người tham gia một hoạt động nào đó dùng participant in.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sensitive', 'en-b2-12', 'sensitive', '/ˈsensətɪv/', 'B2', 'nhạy cảm; dễ bị ảnh hưởng bởi cảm xúc, chất hoặc sự thay đổi; biết quan tâm và thấu đáo với cảm xúc của người khác; cần được xử lý cẩn thận do dễ gây tổn hại hoặc xúc phạm', 'adj.', 'sensitivity (n.), sensitively (adv.), insensitive (adj.)', 'Trái nghĩa: insensitive', 'sensitive chỉ sự nhạy cảm; sensible chỉ sự sáng suốt, hợp lý, tránh nhầm lẫn giữa hai từ này.', 'My skin is sensitive to this new washing powder.', NULL, 'Làn da của tôi rất nhạy cảm với loại bột giặt mới này.', '{"wordId":"sensitive","ukIpa":"/ˈsensətɪv/","usIpa":"/ˈsensətɪv/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Easily affected by emotions, substances, or changes","vi":"nhạy cảm; dễ bị ảnh hưởng bởi cảm xúc, chất hoặc sự thay đổi"},{"pos":"adj.","en":"Aware of and considerate towards other people''s feelings","vi":"biết quan tâm và thấu đáo với cảm xúc của người khác"},{"pos":"adj.","en":"Requiring careful handling because of possible harm or offence","vi":"cần được xử lý cẩn thận do dễ gây tổn hại hoặc xúc phạm"}],"examples":[{"en":"My skin is sensitive to this new washing powder.","vi":"Làn da của tôi rất nhạy cảm với loại bột giặt mới này.","audioKind":"ex"},{"en":"Teachers should be sensitive to students'' cultural backgrounds when discussing potentially controversial issues in class.","vi":"Giáo viên nên nhạy bén với hoàn cảnh văn hóa của học sinh khi thảo luận về các vấn đề có thể gây tranh cãi trong lớp học.","audioKind":"ex2"}],"collocations":[{"en":"sensitive skin","vi":"da nhạy cảm"},{"en":"sensitive to criticism","vi":"nhạy cảm với những lời chỉ trích"},{"en":"sensitive information","vi":"thông tin nhạy cảm"},{"en":"sensitive issue","vi":"vấn đề nhạy cảm"}],"wordFamily":["sensitivity (n.)","sensitively (adv.)","insensitive (adj.)"],"synonyms":[],"antonyms":["insensitive"],"tipVi":"sensitive chỉ sự nhạy cảm; sensible chỉ sự sáng suốt, hợp lý, tránh nhầm lẫn giữa hai từ này.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_confession', 'en-b2-12', 'confession', '/kənˈfeʃən/', 'B2', 'sự thú nhận; lời khai nhận đã làm điều gì sai trái; sự xưng tội; hành vi thú nhận tội lỗi, đặc biệt là trước linh mục', 'n.', 'confess (v.), confessional (adj.)', 'Đồng nghĩa: admission · Trái nghĩa: denial', 'confession đi với giới từ to theo sau là danh từ hoặc danh động từ.', 'I have a confession: I ate the last biscuit.', NULL, 'Tôi có một lời thú nhận: chiếc bánh quy cuối cùng là do tôi ăn đấy.', '{"wordId":"confession","ukIpa":"/kənˈfeʃən/","usIpa":"/kənˈfeʃən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"an admission that you have done something wrong","vi":"sự thú nhận; lời khai nhận đã làm điều gì sai trái"},{"pos":"n.","en":"the act of admitting sins, especially to a priest","vi":"sự xưng tội; hành vi thú nhận tội lỗi, đặc biệt là trước linh mục"}],"examples":[{"en":"I have a confession: I ate the last biscuit.","vi":"Tôi có một lời thú nhận: chiếc bánh quy cuối cùng là do tôi ăn đấy.","audioKind":"ex"},{"en":"Courts should examine whether a confession was obtained voluntarily before accepting it as reliable evidence.","vi":"Tòa án nên xem xét liệu lời khai nhận tội có được đưa ra một cách tự nguyện hay không trước khi chấp nhận nó làm bằng chứng đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"make a confession","vi":"đưa ra lời thú nhận"},{"en":"extract a confession","vi":"ép cung lấy lời khai"},{"en":"a false confession","vi":"lời khai nhận tội sai sự thật"},{"en":"go to confession","vi":"đi xưng tội"}],"wordFamily":["confess (v.)","confessional (adj.)"],"synonyms":["admission"],"antonyms":["denial"],"tipVi":"confession đi với giới từ to theo sau là danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_12_1', 'en-b2-12', 'Cách dùng “independence” (n.) — sự tự lập; tính tự chủ', 'financial independence  ·  gain independence  ·  maintain independence', 'Từ independence thường không đếm được; cụm independence from dùng để chỉ sự tự do, không phụ thuộc hoặc không chịu sự kiểm soát của ai.', 'Họ từ (Word Family): independent (adj), independently (adv), depend (v), dependence (n) | Đồng nghĩa: autonomy, self-reliance · Trái nghĩa: dependence', '[{"hanzi":"Learning to cook gave him a sense of independence.","pinyin":"","meaning":"Việc học nấu ăn đã mang lại cho anh ấy cảm giác tự lập."},{"hanzi":"Accessible housing can help older people maintain their independence while remaining connected to their local communities.","pinyin":"","meaning":"Nhà ở phù hợp và dễ tiếp cận có thể giúp người cao tuổi duy trì sự tự lập trong cuộc sống đồng thời giữ vững sự gắn kết với cộng đồng địa phương."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_12_2', 'en-b2-12', 'Cách dùng “gang” (n.) — băng đảng; nhóm tội phạm', 'a criminal gang  ·  gang violence  ·  a gang of workers', 'Khi chỉ nhóm bạn thì mang sắc thái thân mật, khẩu ngữ; trong ngữ cảnh trang trọng thường dùng để chỉ băng nhóm tội phạm.', NULL, '[{"hanzi":"Our whole gang meets at the park on Saturdays.","pinyin":"","meaning":"Cả nhóm bạn chúng tôi đều gặp nhau ở công viên vào các ngày thứ Bảy."},{"hanzi":"Community programmes can reduce gang membership by offering young people educational support and meaningful employment opportunities.","pinyin":"","meaning":"Các chương trình cộng đồng có thể làm giảm tình trạng thanh thiếu niên gia nhập băng đảng bằng cách cung cấp hỗ trợ giáo dục và cơ hội việc làm ý nghĩa."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_12_3', 'en-b2-12', 'Cách dùng “injustice” (n.) — sự bất công; hành động bất công', 'social injustice  ·  a sense of injustice  ·  suffer an injustice', 'Khi chỉ chung chung sự bất công thì không đếm được; khi chỉ một vụ việc bất công cụ thể thì có thể dùng an injustice.', 'Họ từ (Word Family): justice (n.), unjust (adj.), unjustly (adv.) | Đồng nghĩa: unfairness, inequity · Trái nghĩa: justice, fairness', '[{"hanzi":"We challenged the injustice of excluding her from the team.","pinyin":"","meaning":"Chúng tôi đã lên tiếng phản đối sự bất công khi cô ấy bị loại khỏi đội."},{"hanzi":"Access to affordable legal advice is essential for people seeking to challenge injustice in the workplace.","pinyin":"","meaning":"Khả năng tiếp cận dịch vụ tư vấn pháp lý có chi phí hợp lý là điều thiết yếu đối với những người muốn đấu tranh chống lại sự bất công nơi công sở."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_12_4', 'en-b2-12', 'Cách dùng “interfere” (v.) — can thiệp; xen vào', 'interfere in someone''s affairs  ·  interfere with concentration  ·  interfere with sleep', 'interfere đi với "in" thường chỉ việc can thiệp chuyện riêng; đi với "with" thường chỉ việc cản trở quá trình nào đó.', 'Họ từ (Word Family): interference (n.), interfering (adj.) | Đồng nghĩa: meddle, intrude', '[{"hanzi":"Please don''t interfere when I''m teaching the puppy to sit.","pinyin":"","meaning":"Xin đừng can thiệp khi tôi đang dạy chú cún ngồi."},{"hanzi":"Excessive background noise can interfere with students'' concentration and reduce their ability to absorb new information.","pinyin":"","meaning":"Tiếng ồn nền quá mức có thể cản trở sự tập trung của học sinh và làm giảm khả năng tiếp thu thông tin mới."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_12_1', 'en-b2-12', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
