INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_12_1_2', 'ten_b2_12_1', 'aggressive', 'The aggressive dog growled whenever anyone approached its gate.', 'The aggressive dog growled whenever anyone approached its gate.', '/əˈɡresɪv/', 'Con chó hung dữ gầm gừ mỗi khi có ai lại gần cổng nhà nó.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_12_1_3', 'ten_b2_12_1', 'adopt', 'We adopted a simpler way to organise our shopping.', 'We adopted a simpler way to organise our shopping.', '/əˈdɑːpt/', 'Chúng tôi đã áp dụng một cách đơn giản hơn để tổ chức việc mua sắm của mình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_12_1_4', 'ten_b2_12_1', 'brutal', 'The brutal winter left our garden bare and frozen.', 'The brutal winter left our garden bare and frozen.', '/ˈbruːtəl/', 'Mùa đông khắc nghiệt khiến khuτη vườn của chúng tôi trở nên trơ trọi và đóng băng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_12_1_5', 'ten_b2_12_1', 'funeral', 'We brought white flowers to our neighbour''s funeral yesterday.', 'We brought white flowers to our neighbour''s funeral yesterday.', '/ˈfjuːnərəl/', 'Hôm qua chúng tôi mang hoa trắng đến dự đám tang của người hàng xóm.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_12_1_6', 'ten_b2_12_1', 'regardless', 'Rain was forecast, but we went hiking regardless.', 'Rain was forecast, but we went hiking regardless.', '/rɪˈɡɑːrdləs/', 'Dự báo có mưa, nhưng chúng tôi vẫn đi leo núi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_12_1_7', 'ten_b2_12_1', 'loyal', 'Our loyal dog waits by the door every evening.', 'Our loyal dog waits by the door every evening.', '/ˈlɔɪəl/', 'Chú chó trung thành của chúng tôi đứng đợi bên cửa mỗi buổi chiều tối.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_12_1_8', 'ten_b2_12_1', 'aid', 'Volunteers brought food and medical aid to the village.', 'Volunteers brought food and medical aid to the village.', '/eɪd/', 'Các tình nguyện viên đã mang lương thực và viện trợ y tế đến cho ngôi làng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_12_1_1', 'en-b2-12', 'ten_b2_12_1', 'listening', 'listening', 'Our whole gang meets at the park on Saturdays.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Sự đóng góp của bạn đã giúp chúng tôi hoàn thành khu vườn trước khi trời tối.","Cả nhóm bạn chúng tôi đều gặp nhau ở công viên vào các ngày thứ Bảy.","Hội đồng giám khảo đã lắng nghe chăm chú khi từng học sinh trình bày ý tưởng của mình.","Cả làng đã quây quần lại bên nhau sau thảm kịch đó."]'::jsonb, 1, 'Our whole gang meets at the park on Saturdays. → Cả nhóm bạn chúng tôi đều gặp nhau ở công viên vào các ngày thứ Bảy.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_12_1_2', 'en-b2-12', 'ten_b2_12_1', 'listening', 'listening', 'The aggressive dog growled whenever anyone approached its gate.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cả nhóm bạn chúng tôi đều gặp nhau ở công viên vào các ngày thứ Bảy.","Con chó hung dữ gầm gừ mỗi khi có ai lại gần cổng nhà nó.","Hội đồng giám khảo đã lắng nghe chăm chú khi từng học sinh trình bày ý tưởng của mình.","Bạn cần có một lời mời chính thức để tham dự buổi lễ."]'::jsonb, 1, 'The aggressive dog growled whenever anyone approached its gate. → Con chó hung dữ gầm gừ mỗi khi có ai lại gần cổng nhà nó.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_12_1_3', 'en-b2-12', 'ten_b2_12_1', 'listening', 'listening', 'We adopted a simpler way to organise our shopping.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Mùa đông khắc nghiệt khiến khuτη vườn của chúng tôi trở nên trơ trọi và đóng băng.","Mỗi người tham gia đã mang theo một món ăn tự nấu đến buổi hội thảo nấu ăn.","Chúng tôi đã áp dụng một cách đơn giản hơn để tổ chức việc mua sắm của mình.","Các tình nguyện viên đã mang lương thực và viện trợ y tế đến cho ngôi làng."]'::jsonb, 2, 'We adopted a simpler way to organise our shopping. → Chúng tôi đã áp dụng một cách đơn giản hơn để tổ chức việc mua sắm của mình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_12_2', 'en-b2-12', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_12_2_1', 'ten_b2_12_2', 'gang', 'Community programmes can reduce gang membership by offering young people educational support and meaningful employment opportunities.', 'Community programmes can reduce gang membership by offering young people educational support and meaningful employment opportunities.', '/ɡæŋ/', 'Các chương trình cộng đồng có thể làm giảm tình trạng thanh thiếu niên gia nhập băng đảng bằng cách cung cấp hỗ trợ giáo dục và cơ hội việc làm ý nghĩa.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_12_2_2', 'ten_b2_12_2', 'aggressive', 'Aggressive marketing campaigns may increase sales, but they can also encourage unnecessary consumption and household debt.', 'Aggressive marketing campaigns may increase sales, but they can also encourage unnecessary consumption and household debt.', '/əˈɡresɪv/', 'Các chiến dịch tiếp thị mạnh mẽ có thể làm tăng doanh số bán hàng, nhưng chúng cũng có thể thúc đẩy tiêu dùng không cần thiết và nợ gia đình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_12_2_3', 'ten_b2_12_2', 'adopt', 'Governments should adopt long-term strategies that improve public transport rather than simply building more roads.', 'Governments should adopt long-term strategies that improve public transport rather than simply building more roads.', '/əˈdɑːpt/', 'Chính phủ nên áp dụng các chiến lược dài hạn nhằm cải thiện giao thông công cộng thay vì chỉ đơn thuần xây thêm đường sá.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_12_2_4', 'ten_b2_12_2', 'brutal', 'Brutal treatment of prisoners violates human rights and undermines public trust in the justice system.', 'Brutal treatment of prisoners violates human rights and undermines public trust in the justice system.', '/ˈbruːtəl/', 'Đối xử tàn bạo với tù nhân vi phạm nhân quyền và làm suy giảm lòng tin của công chúng đối với hệ thống tư pháp.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_12_2_5', 'ten_b2_12_2', 'funeral', 'Funeral traditions vary across cultures, but they often provide families with emotional support during bereavement.', 'Funeral traditions vary across cultures, but they often provide families with emotional support during bereavement.', '/ˈfjuːnərəl/', 'Các truyền thống tang lễ khác nhau giữa các nền văn hóa, nhưng chúng thường mang lại sự hỗ trợ tinh thần cho các gia đình trong lúc tang gia bối rối.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_12_2_6', 'ten_b2_12_2', 'regardless', 'Public libraries should provide access to reliable information for everyone, regardless of income or educational background.', 'Public libraries should provide access to reliable information for everyone, regardless of income or educational background.', '/rɪˈɡɑːrdləs/', 'Các thư viện công cộng nên cung cấp khả năng tiếp cận thông tin đáng tin cậy cho mọi người, bất kể thu nhập hay nền tảng giáo dục.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_12_2_1', 'en-b2-12', 'ten_b2_12_2', 'listening', 'listening', 'Community programmes can reduce gang membership by offering young people educational support and meaningful employment opportunities.', NULL, 'Trong câu vừa nghe, từ “gang” mang nghĩa nào sau đây?', '["sự đánh giá; sự nhận định","băng đảng; nhóm tội phạm","từ chức; xin thôi việc","tương ứng; phù hợp"]'::jsonb, 1, '“gang” (/ɡæŋ/): băng đảng; nhóm tội phạm. Câu đầy đủ: Community programmes can reduce gang membership by offering young people educational support and meaningful employment opportunities.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_12_2_2', 'en-b2-12', 'ten_b2_12_2', 'listening', 'listening', 'Aggressive marketing campaigns may increase sales, but they can also encourage unnecessary consumption and household debt.', NULL, 'Trong câu vừa nghe, từ “aggressive” mang nghĩa nào sau đây?', '["hung hăng; hiếu chiến; hay gây sự","hết hạn; sự mãn hạn","hợp lý; sáng suốt","tham lam; hám lợi"]'::jsonb, 0, '“aggressive” (/əˈɡresɪv/): hung hăng; hiếu chiến; hay gây sự. Câu đầy đủ: Aggressive marketing campaigns may increase sales, but they can also encourage unnecessary consumption and household debt.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
