INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_12_2', 'en-b2-12', NULL, 'comprehensive_test', 'listening', 'The aggressive dog growled whenever anyone approached its gate.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sự đóng góp của bạn đã giúp chúng tôi hoàn thành khu vườn trước khi trời tối.","Con chó hung dữ gầm gừ mỗi khi có ai lại gần cổng nhà nó.","Chúng tôi đã đóng góp một khoản tiền nhỏ cho quỹ cứu trợ động vật.","Việc học nấu ăn đã mang lại cho anh ấy cảm giác tự lập."]'::jsonb, 1, 'The aggressive dog growled whenever anyone approached its gate. → Con chó hung dữ gầm gừ mỗi khi có ai lại gần cổng nhà nó.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_12_3', 'en-b2-12', NULL, 'comprehensive_test', 'listening', 'adopt', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đặt mua dài hạn; đăng ký sử dụng dịch vụ","thông tin đầu vào; nguồn lực đầu vào","không biết; thiếu hiểu biết (về một sự việc/chủ đề)","áp dụng; chọn theo"]'::jsonb, 3, 'adopt (/əˈdɑːpt/) → áp dụng; chọn theo; nhận nuôi; thông qua; phê chuẩn', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_12_4', 'en-b2-12', NULL, 'comprehensive_test', 'listening', 'The brutal winter left our garden bare and frozen.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Mỗi người tham gia đã mang theo một món ăn tự nấu đến buổi hội thảo nấu ăn.","Các tình nguyện viên đã mang lương thực và viện trợ y tế đến cho ngôi làng.","Vị linh mục dừng lại để cầu phước cho gia đình trước chuyến hành trình của họ.","Mùa đông khắc nghiệt khiến khuτη vườn của chúng tôi trở nên trơ trọi và đóng băng."]'::jsonb, 3, 'The brutal winter left our garden bare and frozen. → Mùa đông khắc nghiệt khiến khuτη vườn của chúng tôi trở nên trơ trọi và đóng băng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_12_5', 'en-b2-12', NULL, 'comprehensive_test', 'listening', 'funeral', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tang lễ; đám tang","trung thành; tận tụy","mang nét nữ tính; dịu dàng","giữa học kỳ; giữa nhiệm kỳ"]'::jsonb, 0, 'funeral (/ˈfjuːnərəl/) → tang lễ; đám tang', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_12_6', 'en-b2-12', NULL, 'comprehensive_test', 'listening', 'Rain was forecast, but we went hiking regardless.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã áp dụng một cách đơn giản hơn để tổ chức việc mua sắm của mình.","Chú chó trung thành của chúng tôi đứng đợi bên cửa mỗi buổi chiều tối.","Tôi đã kìm nén sự thôi thúc muốn ăn thêm một chiếc bánh quy nữa.","Dự báo có mưa, nhưng chúng tôi vẫn đi leo núi."]'::jsonb, 3, 'Rain was forecast, but we went hiking regardless. → Dự báo có mưa, nhưng chúng tôi vẫn đi leo núi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_12_7', 'en-b2-12', NULL, 'comprehensive_test', 'listening', 'loyal', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chim công đực; công trống","làm kiệt sức; làm mệt lử","mái chèo","trung thành; trung thực"]'::jsonb, 3, 'loyal (/ˈlɔɪəl/) → trung thành; trung thực', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_12_8', 'en-b2-12', NULL, 'comprehensive_test', 'listening', 'Volunteers brought food and medical aid to the village.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bọn trẻ vẫn giữ thái độ kính cẩn khi bà của chúng đang nói chuyện.","Chúng tôi đã đóng góp một khoản tiền nhỏ cho quỹ cứu trợ động vật.","Các tình nguyện viên đã mang lương thực và viện trợ y tế đến cho ngôi làng.","Chúng tôi đã lên tiếng phản đối sự bất công khi cô ấy bị loại khỏi đội."]'::jsonb, 2, 'Volunteers brought food and medical aid to the village. → Các tình nguyện viên đã mang lương thực và viện trợ y tế đến cho ngôi làng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_12_9', 'en-b2-12', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a ceremony held to remember and honour someone who has died”?', '["sensitive","funeral","respectful","independence"]'::jsonb, 1, 'funeral (/ˈfjuːnərəl/) → tang lễ; đám tang', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_12_10', 'en-b2-12', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Despite difficulties, objections, or other circumstances.”?', '["contribution","regardless","independence","donation"]'::jsonb, 1, 'regardless (/rɪˈɡɑːrdləs/) → bất chấp; mặc dù; bất kể', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_12_11', 'en-b2-12', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Continuing to support someone or something, even during difficulties.”?', '["panel","bless","aggressive","loyal"]'::jsonb, 3, 'loyal (/ˈlɔɪəl/) → trung thành; trung thực', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_12_12', 'en-b2-12', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Help provided through money, supplies, services, or practical support.”?', '["urge","settlement","aid","participant"]'::jsonb, 2, 'aid (/eɪd/) → sự viện trợ; sự cứu trợ; tiền trợ giúp', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_12_13', 'en-b2-12', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Something done or provided to help achieve a shared result.”?', '["contribution","loyal","sensitive","confession"]'::jsonb, 0, 'contribution (/ˌkɑːntrɪˈbjuːʃən/) → sự đóng góp; phần đóng góp', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
