INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_12_18', 'en-b2-12', NULL, 'comprehensive_test', 'reading', NULL, 'Community programmes can reduce gang membership by offering young people educational support and meaningful employment opportunities.', 'Dựa vào câu trên, từ “gang” có nghĩa phù hợp nhất là gì?', '["sự từ chối; sự bác bỏ","tổng quan; bản tóm tắt","băng đảng; nhóm tội phạm","không hoàn hảo; có khuyết điểm"]'::jsonb, 2, 'gang: băng đảng; nhóm tội phạm; nhóm bạn; tốp công nhân. Dịch cả câu: Các chương trình cộng đồng có thể làm giảm tình trạng thanh thiếu niên gia nhập băng đảng bằng cách cung cấp hỗ trợ giáo dục và cơ hội việc làm ý nghĩa.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_12_19', 'en-b2-12', NULL, 'comprehensive_test', 'reading', NULL, 'Aggressive marketing campaigns may increase sales, but they can also encourage unnecessary consumption and household debt.', 'Dựa vào câu trên, từ “aggressive” có nghĩa phù hợp nhất là gì?', '["bị phóng đại; nói quá; cường điệu","đáng chú ý; nổi bật; rõ rệt","hung hăng; hiếu chiến; hay gây sự","sự theo đuổi; sự mưu cầu"]'::jsonb, 2, 'aggressive: hung hăng; hiếu chiến; hay gây sự; quyết đoán; xông xáo; mạnh mẽ. Dịch cả câu: Các chiến dịch tiếp thị mạnh mẽ có thể làm tăng doanh số bán hàng, nhưng chúng cũng có thể thúc đẩy tiêu dùng không cần thiết và nợ gia đình.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_12_20', 'en-b2-12', NULL, 'comprehensive_test', 'reading', NULL, 'Governments should adopt long-term strategies that improve public transport rather than simply building more roads.', 'Dựa vào câu trên, từ “adopt” có nghĩa phù hợp nhất là gì?', '["áp dụng; chọn theo","thải ra; phát ra; tỏa ra","liên minh; khối liên minh","sự điều hướng; sự định vị và dẫn đường"]'::jsonb, 0, 'adopt: áp dụng; chọn theo; nhận nuôi; thông qua; phê chuẩn. Dịch cả câu: Chính phủ nên áp dụng các chiến lược dài hạn nhằm cải thiện giao thông công cộng thay vì chỉ đơn thuần xây thêm đường sá.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_12_21', 'en-b2-12', NULL, 'comprehensive_test', 'reading', NULL, 'Brutal treatment of prisoners violates human rights and undermines public trust in the justice system.', 'Dựa vào câu trên, từ “brutal” có nghĩa phù hợp nhất là gì?', '["phong cách nấu nướng; ẩm thực; nền văn hóa ẩm thực","tuyệt vời, tuyệt diệu","tàn bạo; dã man; hung ác","vỗ tay; hoan hô"]'::jsonb, 2, 'brutal: tàn bạo; dã man; hung ác; khắc nghiệt; dữ dội; thẳng thắn đến phũ phàng. Dịch cả câu: Đối xử tàn bạo với tù nhân vi phạm nhân quyền và làm suy giảm lòng tin của công chúng đối với hệ thống tư pháp.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_12_22', 'en-b2-12', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “người tham gia; người tham dự”', '["participant","anchor","comet","minister"]'::jsonb, 0, 'người tham gia; người tham dự → participant (/pɑːrˈtɪsɪpənt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_12_23', 'en-b2-12', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nhạy cảm; dễ bị ảnh hưởng bởi cảm xúc, chất hoặc sự thay đổi”', '["rage","extract","sensitive","yield"]'::jsonb, 2, 'nhạy cảm; dễ bị ảnh hưởng bởi cảm xúc, chất hoặc sự thay đổi → sensitive (/ˈsensətɪv/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_12_24', 'en-b2-12', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự thú nhận; lời khai nhận đã làm điều gì sai trái”', '["debate","acid","confession","multifunction"]'::jsonb, 2, 'sự thú nhận; lời khai nhận đã làm điều gì sai trái → confession (/kənˈfeʃən/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-13', 'en', 'Bài 13: Xã hội & Cộng đồng (6) - CEFR B2', 'CEFR B2', 'B2 · Xã hội', '26 từ vựng Tiếng Anh CEFR B2 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4013, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_publicly', 'en-b2-13', 'publicly', '/ˈpʌblɪkli/', 'B2', 'công khai; trước công chúng; một cách công khai; bằng nguồn vốn hoặc sự sở hữu của chính phủ hoặc cộng đồng', 'adv.', 'public (adj.), publicity (n.), publicise (v.)', 'Đồng nghĩa: openly · Trái nghĩa: privately', 'Cách viết đúng chính tả là publicly, không phải publically.', 'She publicly thanked the neighbours who found her cat.', NULL, 'Cô ấy đã công khai cảm ơn những người hàng xóm đã tìm thấy con mèo cho cô ấy.', '{"wordId":"publicly","ukIpa":"/ˈpʌblɪkli/","usIpa":"/ˈpʌblɪkli/","cefr":"B2","topic":"society","senses":[{"pos":"adv.","en":"in a way that people generally can see or know","vi":"công khai; trước công chúng; một cách công khai"},{"pos":"adv.","en":"through government or community funding or ownership","vi":"bằng nguồn vốn hoặc sự sở hữu của chính phủ hoặc cộng đồng"}],"examples":[{"en":"She publicly thanked the neighbours who found her cat.","vi":"Cô ấy đã công khai cảm ơn những người hàng xóm đã tìm thấy con mèo cho cô ấy.","audioKind":"ex"},{"en":"Research funded by taxpayers should be publicly available so that everyone can benefit from its findings.","vi":"Các nghiên cứu do người đóng thuế tài trợ nên được cung cấp công khai để mọi người đều có thể hưởng lợi từ kết quả nghiên cứu đó.","audioKind":"ex2"}],"collocations":[{"en":"publicly available","vi":"công khai cho công chúng tiếp cận"},{"en":"publicly funded","vi":"được tài trợ bằng ngân sách công"},{"en":"publicly acknowledge","vi":"công khai thừa nhận"},{"en":"publicly owned","vi":"thuộc sở hữu công cộng"}],"wordFamily":["public (adj.)","publicity (n.)","publicise (v.)"],"synonyms":["openly"],"antonyms":["privately"],"tipVi":"Cách viết đúng chính tả là publicly, không phải publically.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_accessible', 'en-b2-13', 'accessible', '/əkˈsesəbl/', 'B2', 'dễ tiếp cận, dễ vào, dễ lấy hoặc dễ sử dụng; dễ hiểu, dễ tiếp thu đối với mọi người', 'adj.', 'access (n.), access (v.), accessibility (n.), inaccessible (adj.)', 'Đồng nghĩa: reachable · Trái nghĩa: inaccessible', 'Thường dùng accessible to sb; nội dung dễ hiểu cũng có thể dùng từ này.', 'The garden is accessible through a small wooden gate.', NULL, 'Có thể đi vào khu vườn qua một cánh cửa gỗ nhỏ.', '{"wordId":"accessible","ukIpa":"/əkˈsesəbl/","usIpa":"/əkˈsesəbl/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"easy to reach, enter, obtain, or use","vi":"dễ tiếp cận, dễ vào, dễ lấy hoặc dễ sử dụng"},{"pos":"adj.","en":"easy for people to understand","vi":"dễ hiểu, dễ tiếp thu đối với mọi người"}],"examples":[{"en":"The garden is accessible through a small wooden gate.","vi":"Có thể đi vào khu vườn qua một cánh cửa gỗ nhỏ.","audioKind":"ex"},{"en":"Public libraries should provide digital resources that are accessible to users with a wide range of abilities.","vi":"Các thư viện công cộng nên cung cấp các nguồn tài nguyên kỹ thuật số mà người dùng ở nhiều năng lực khác nhau đều có thể truy cập sử dụng.","audioKind":"ex2"}],"collocations":[{"en":"accessible to everyone","vi":"mọi người đều có thể tiếp cận"},{"en":"wheelchair accessible","vi":"có lối đi cho xe lăn"},{"en":"readily accessible","vi":"dễ dàng lấy được; dễ dàng tiếp cận"},{"en":"accessible language","vi":"ngôn ngữ dễ hiểu"}],"wordFamily":["access (n.)","access (v.)","accessibility (n.)","inaccessible (adj.)"],"synonyms":["reachable"],"antonyms":["inaccessible"],"tipVi":"Thường dùng accessible to sb; nội dung dễ hiểu cũng có thể dùng từ này.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sin', 'en-b2-13', 'sin', '/sɪn/', 'B2', 'tội lỗi; điều răn phạm; phạm tội; làm điều trái đạo đức', 'n.', 'sinful (adj.), sinner (n.)', 'Đồng nghĩa: wrongdoing', 'Từ sin mang sắc thái tôn giáo hoặc đạo đức, không đồng nghĩa với tội danh pháp lý crime.', 'He believed that lying to his friends was a sin.', NULL, 'Anh ấy tin rằng việc nói dối bạn bè là một tội lỗi.', '{"wordId":"sin","ukIpa":"/sɪn/","usIpa":"/sɪn/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"an action that breaks a religious or moral rule","vi":"tội lỗi; điều răn phạm"},{"pos":"v.","en":"to break a religious or moral rule","vi":"phạm tội; làm điều trái đạo đức"}],"examples":[{"en":"He believed that lying to his friends was a sin.","vi":"Anh ấy tin rằng việc nói dối bạn bè là một tội lỗi.","audioKind":"ex"},{"en":"Ideas about sin can influence social attitudes, even in societies where religious participation is declining.","vi":"Quan niệm về tội lỗi có thể ảnh hưởng đến thái độ xã hội, ngay cả trong những xã hội mà mức độ tham gia tôn giáo đang suy giảm.","audioKind":"ex2"}],"collocations":[{"en":"commit a sin","vi":"phạm tội"},{"en":"confess one''s sins","vi":"thú tội; xưng tội"},{"en":"sin against","vi":"phạm tội chống lại; xúc phạm"}],"wordFamily":["sinful (adj.)","sinner (n.)"],"synonyms":["wrongdoing"],"antonyms":[],"tipVi":"Từ sin mang sắc thái tôn giáo hoặc đạo đức, không đồng nghĩa với tội danh pháp lý crime.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_resist', 'en-b2-13', 'resist', '/rɪˈzɪst/', 'B2', 'chống lại; kháng cự; nhịn; cưỡng lại; kiềm chế; chịu đựng', 'v.', 'resistance (n.), resistant (adj.), irresistible (adj.)', 'Đồng nghĩa: oppose, withstand · Trái nghĩa: yield', 'Để diễn tả việc nhịn hoặc cưỡng lại làm việc gì, dùng resist doing thay vì to do.', 'I could not resist buying another warm cinnamon bun.', NULL, 'Tôi không thể kiềm chế được việc mua thêm một chiếc bánh cuộn quế ấm nóng.', '{"wordId":"resist","ukIpa":"/rɪˈzɪst/","usIpa":"/rɪˈzɪst/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"Oppose something or try to prevent it from happening","vi":"chống lại; kháng cự"},{"pos":"v.","en":"Stop yourself from doing something tempting","vi":"nhịn; cưỡng lại; kiềm chế"},{"pos":"v.","en":"Remain undamaged or unaffected by something harmful","vi":"kháng cự; chịu đựng"}],"examples":[{"en":"I could not resist buying another warm cinnamon bun.","vi":"Tôi không thể kiềm chế được việc mua thêm một chiếc bánh cuộn quế ấm nóng.","audioKind":"ex"},{"en":"Employees may resist technological change if they believe new systems will threaten their job security.","vi":"Nhân viên có thể chống lại sự thay đổi công nghệ nếu họ tin rằng các hệ thống mới sẽ đe dọa sự ổn định công việc của họ.","audioKind":"ex2"}],"collocations":[{"en":"resist change","vi":"chống lại sự thay đổi"},{"en":"resist temptation","vi":"cưỡng lại cám dỗ"},{"en":"resist pressure","vi":"chịu đựng áp lực; chống lại áp lực"},{"en":"resist corrosion","vi":"chống ăn mòn; bền với sự ăn mòn"}],"wordFamily":["resistance (n.)","resistant (adj.)","irresistible (adj.)"],"synonyms":["oppose","withstand"],"antonyms":["yield"],"tipVi":"Để diễn tả việc nhịn hoặc cưỡng lại làm việc gì, dùng resist doing thay vì to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_discriminate', 'en-b2-13', 'discriminate', '/dɪˈskrɪmɪneɪt/', 'B2', 'phân biệt đối xử; kỳ thị; phân biệt; nhận biết sự khác biệt', 'v.', 'discrimination (n.), discriminatory (adj.), discriminating (adj.)', NULL, 'Phân biệt đối xử ai dùng against; phân biệt giữa hai vật dùng between.', 'Our club does not discriminate against anyone because of age.', NULL, 'Câu lạc bộ của chúng tôi không kỳ thị bất kỳ ai vì lý do độ tuổi.', '{"wordId":"discriminate","ukIpa":"/dɪˈskrɪmɪneɪt/","usIpa":"/dɪˈskrɪmɪneɪt/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"Treat people unfairly because of their group or personal characteristics","vi":"phân biệt đối xử; kỳ thị"},{"pos":"v.","en":"Recognise differences between things","vi":"phân biệt; nhận biết sự khác biệt"}],"examples":[{"en":"Our club does not discriminate against anyone because of age.","vi":"Câu lạc bộ của chúng tôi không kỳ thị bất kỳ ai vì lý do độ tuổi.","audioKind":"ex"},{"en":"Employers must not discriminate against applicants on the basis of disability, gender, or cultural background.","vi":"Người sử dụng lao động không được kỳ thị đối với ứng viên dựa trên cơ sở khuyết tật, giới tính hoặc nền tảng văn hóa.","audioKind":"ex2"}],"collocations":[{"en":"discriminate against","vi":"kỳ thị"},{"en":"discriminate on the basis of age","vi":"phân biệt đối xử dựa trên độ tuổi"},{"en":"discriminate between","vi":"phân biệt giữa"}],"wordFamily":["discrimination (n.)","discriminatory (adj.)","discriminating (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Phân biệt đối xử ai dùng against; phân biệt giữa hai vật dùng between.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flee', 'en-b2-13', 'flee', '/fliː/', 'B2', 'trốn chạy; chạy trốn', 'v.', 'fleeing (adj.)', 'Đồng nghĩa: escape, run away', 'Quá khứ và phân từ quá khứ đều là fled; có thể trực tiếp kết hợp với địa điểm trốn chạy.', 'The birds fled when the dog entered the garden.', NULL, 'Đàn chim bay tản mác khi con chó bước vào khu vực vườn.', '{"wordId":"flee","ukIpa":"/fliː/","usIpa":"/fliː/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"To leave quickly to escape danger or an unpleasant situation.","vi":"trốn chạy; chạy trốn"}],"examples":[{"en":"The birds fled when the dog entered the garden.","vi":"Đàn chim bay tản mác khi con chó bước vào khu vực vườn.","audioKind":"ex"},{"en":"Severe flooding can force rural families to flee their homes and seek shelter in nearby towns.","vi":"Những trận lụt dữ dội có thể buộc các gia đình nông thôn phải rời bỏ nhà cửa và tìm nơi trú ẩn tại các thị trấn lân cận.","audioKind":"ex2"}],"collocations":[{"en":"flee danger","vi":"trốn chạy nguy hiểm"},{"en":"flee the country","vi":"rời khỏi đất nước"},{"en":"flee from persecution","vi":"chạy trốn sự đàn áp"}],"wordFamily":["fleeing (adj.)"],"synonyms":["escape","run away"],"antonyms":[],"tipVi":"Quá khứ và phân từ quá khứ đều là fled; có thể trực tiếp kết hợp với địa điểm trốn chạy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_freedom', 'en-b2-13', 'freedom', '/ˈfriːdəm/', 'B2', 'tự do; quyền tự chủ; sự thoát khỏi; sự miễn trừ', 'n.', 'free (adj.), free (v.), freely (adv.)', 'Đồng nghĩa: liberty · Trái nghĩa: captivity', 'freedom to do thể hiện sự tự do làm việc gì; from biểu thị sự thoát khỏi.', 'Living alone gives me freedom to choose my own routine.', NULL, 'Sống một mình cho tôi sự tự do tự sắp xếp lịch trình sinh hoạt cá nhân.', '{"wordId":"freedom","ukIpa":"/ˈfriːdəm/","usIpa":"/ˈfriːdəm/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"The right or ability to act without unnecessary restrictions.","vi":"tự do; quyền tự chủ"},{"pos":"n.","en":"The state of not experiencing something unpleasant.","vi":"sự thoát khỏi; sự miễn trừ"}],"examples":[{"en":"Living alone gives me freedom to choose my own routine.","vi":"Sống một mình cho tôi sự tự do tự sắp xếp lịch trình sinh hoạt cá nhân.","audioKind":"ex"},{"en":"Universities should protect academic freedom while encouraging researchers to consider the social consequences of their work.","vi":"Các trường đại học nên bảo vệ tự do học thuật đồng thời khuyến khích các nhà nghiên cứu cân nhắc tác động xã hội từ công việc của họ.","audioKind":"ex2"}],"collocations":[{"en":"freedom of speech","vi":"tự do ngôn luận"},{"en":"freedom to choose","vi":"tự do lựa chọn"},{"en":"academic freedom","vi":"tự do học thuật"},{"en":"freedom from fear","vi":"thoát khỏi nỗi sợ hãi"}],"wordFamily":["free (adj.)","free (v.)","freely (adv.)"],"synonyms":["liberty"],"antonyms":["captivity"],"tipVi":"freedom to do thể hiện sự tự do làm việc gì; from biểu thị sự thoát khỏi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_veil', 'en-b2-13', 'veil', '/veɪl/', 'B2', 'mạng che mặt; khăn voan; sự che đậy; lớp ngụy trang; che đậy; che giấu', 'n.', 'veiled (adj.), unveil (v.)', NULL, 'a veil of mang tính ẩn dụ chỉ một lớp che đậy; veiled cũng diễn tả sự kín đáo, hàm ý.', 'She lifted her veil to take a sip of water.', NULL, 'Cô ấy nhấc mạng che mặt lên để nhấp một ngụm nước.', '{"wordId":"veil","ukIpa":"/veɪl/","usIpa":"/veɪl/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"a thin piece of material covering the face or head","vi":"mạng che mặt; khăn voan"},{"pos":"n.","en":"something that hides or makes something else less clear","vi":"sự che đậy; lớp ngụy trang"},{"pos":"v.","en":"to hide something or prevent it from being clearly understood","vi":"che đậy; che giấu"}],"examples":[{"en":"She lifted her veil to take a sip of water.","vi":"Cô ấy nhấc mạng che mặt lên để nhấp một ngụm nước.","audioKind":"ex"},{"en":"A veil of secrecy around major planning decisions can weaken public trust in local government.","vi":"Một lớp bí mật bao trùm các quyết định quy hoạch lớn có thể làm suy yếu lòng tin của công chúng vào chính quyền địa phương.","audioKind":"ex2"}],"collocations":[{"en":"wear a veil","vi":"đeo mạng che mặt"},{"en":"a veil of secrecy","vi":"lớp màn bí mật"},{"en":"thinly veiled criticism","vi":"lời chỉ trích được ngụy trang khéo léo"}],"wordFamily":["veiled (adj.)","unveil (v.)"],"synonyms":[],"antonyms":[],"tipVi":"a veil of mang tính ẩn dụ chỉ một lớp che đậy; veiled cũng diễn tả sự kín đáo, hàm ý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_guardian', 'en-b2-13', 'guardian', '/ˈɡɑːrdiən/', 'B2', 'người giám hộ (người có trách nhiệm pháp lý đối với trẻ em hoặc người lớn cần chăm sóc); người bảo vệ; vật bảo vệ (người hoặc tổ chức bảo vệ một cái gì đó có giá trị)', 'n.', 'guard (v.), guardianship (n.)', 'Đồng nghĩa: protector, custodian', 'Trong ngữ cảnh pháp lý, "guardian" chỉ người giám hộ, không nhất thiết phải là cha mẹ của đứa trẻ.', 'Her aunt became her legal guardian and cared for her.', NULL, 'Cô ấy trở thành người giám hộ hợp pháp của cô và chăm sóc cô.', '{"wordId":"guardian","ukIpa":"/ˈɡɑːdiən/","usIpa":"/ˈɡɑːrdiən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"Someone legally responsible for a child or an adult needing care.","vi":"người giám hộ (người có trách nhiệm pháp lý đối với trẻ em hoặc người lớn cần chăm sóc)"},{"pos":"n.","en":"A person or organization that protects something valuable.","vi":"người bảo vệ; vật bảo vệ (người hoặc tổ chức bảo vệ một cái gì đó có giá trị)"}],"examples":[{"en":"Her aunt became her legal guardian and cared for her.","vi":"Cô ấy trở thành người giám hộ hợp pháp của cô và chăm sóc cô.","audioKind":"ex"},{"en":"Schools should involve parents or guardians in decisions that significantly affect children''s education and emotional wellbeing.","vi":"Nhà trường nên cho phép phụ huynh hoặc người giám hộ tham gia vào các quyết định ảnh hưởng đáng kể đến giáo dục và sự phát triển cảm xúc của trẻ em.","audioKind":"ex2"}],"collocations":[{"en":"legal guardian","vi":"người giám hộ hợp pháp"},{"en":"parent or guardian","vi":"cha mẹ hoặc người giám hộ"},{"en":"guardian of tradition","vi":"người bảo vệ truyền thống"}],"wordFamily":["guard (v.)","guardianship (n.)"],"synonyms":["protector","custodian"],"antonyms":[],"tipVi":"Trong ngữ cảnh pháp lý, \"guardian\" chỉ người giám hộ, không nhất thiết phải là cha mẹ của đứa trẻ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hardship', 'en-b2-13', 'hardship', '/ˈhɑːrdʃɪp/', 'B2', 'sự khốn khó; hoàn cảnh khó khăn (tình trạng thiếu thốn các nhu cầu thiết yếu)', 'n.', 'hard (adj.)', 'Đồng nghĩa: adversity, privation · Trái nghĩa: comfort', 'Khi dùng chỉ sự khốn khó chung, "hardship" thường không đếm được; các thử thách cụ thể có thể dùng dạng số nhiều "hardships".', 'Losing her job caused months of hardship for the family.', NULL, 'Việc mất việc đã khiến gia đình trải qua nhiều tháng trời khốn khó.', '{"wordId":"hardship","ukIpa":"/ˈhɑːdʃɪp/","usIpa":"/ˈhɑːrdʃɪp/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"severe difficulty or suffering, especially from lacking basic necessities","vi":"sự khốn khó; hoàn cảnh khó khăn (tình trạng thiếu thốn các nhu cầu thiết yếu)"}],"examples":[{"en":"Losing her job caused months of hardship for the family.","vi":"Việc mất việc đã khiến gia đình trải qua nhiều tháng trời khốn khó.","audioKind":"ex"},{"en":"Rising housing costs can cause significant financial hardship for families already struggling to afford basic necessities.","vi":"Chi phí nhà ở tăng cao có thể gây ra những khó khăn tài chính đáng kể cho các gia đình vốn đã chật vật để trang trải các nhu cầu thiết yếu cơ bản.","audioKind":"ex2"}],"collocations":[{"en":"financial hardship","vi":"khó khăn tài chính"},{"en":"face hardship","vi":"đối mặt với nghịch cảnh"},{"en":"endure hardship","vi":"chịu đựng gian khổ"}],"wordFamily":["hard (adj.)"],"synonyms":["adversity","privation"],"antonyms":["comfort"],"tipVi":"Khi dùng chỉ sự khốn khó chung, \"hardship\" thường không đếm được; các thử thách cụ thể có thể dùng dạng số nhiều \"hardships\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_invalid', 'en-b2-13', 'invalid', '/ɪnˈvælɪd/', 'B2', 'không hợp lệ; mất hiệu lực; không được chính thức công nhận; không có căn cứ; thiếu cơ sở lập luận vững chắc', 'adj.', 'valid (adj.), invalidate (v.), invalidity (n.), validation (n.)', 'Đồng nghĩa: void, unsound · Trái nghĩa: valid', 'Danh từ chỉ "người tàn tật/ốm yếu" có trọng âm ở âm tiết đầu tiên và nay ít được sử dụng hơn.', 'My ticket was invalid, so I bought another one.', NULL, 'Vé của tôi đã hết hạn nên tôi đã phải mua vé khác.', '{"wordId":"invalid","ukIpa":"/ɪnˈvælɪd/","usIpa":"/ɪnˈvælɪd/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"not legally or officially acceptable","vi":"không hợp lệ; mất hiệu lực; không được chính thức công nhận"},{"pos":"adj.","en":"not supported by sound reasoning or reliable evidence","vi":"không có căn cứ; thiếu cơ sở lập luận vững chắc"}],"examples":[{"en":"My ticket was invalid, so I bought another one.","vi":"Vé của tôi đã hết hạn nên tôi đã phải mua vé khác.","audioKind":"ex"},{"en":"Conclusions drawn from a small, unrepresentative sample may be invalid and should not guide major policy decisions.","vi":"Những kết luận được rút ra từ một mẫu dữ liệu nhỏ và thiếu tính đại diện có thể không có giá trị và không nên được dùng làm định hướng cho các quyết định chính sách quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"invalid ticket","vi":"vé không hợp lệ"},{"en":"invalid argument","vi":"lập luận không có căn cứ"},{"en":"invalid data","vi":"dữ liệu không hợp lệ"},{"en":"declare something invalid","vi":"tuyên bố cái gì đó là vô hiệu"}],"wordFamily":["valid (adj.)","invalidate (v.)","invalidity (n.)","validation (n.)"],"synonyms":["void","unsound"],"antonyms":["valid"],"tipVi":"Danh từ chỉ \"người tàn tật/ốm yếu\" có trọng âm ở âm tiết đầu tiên và nay ít được sử dụng hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grave', 'en-b2-13', 'grave', '/ɡreɪv/', 'B2', 'mộ; phần mộ; trầm trọng; nghiêm trọng; trang nghiêm; nghiêm nghị', 'n.', 'gravely (adv.), graveness (n.)', NULL, 'Khi dùng làm tính từ, từ này mang tính trang trọng hơn serious và thường bổ nghĩa cho các từ chỉ mối đe dọa hoặc hậu quả.', 'She placed fresh flowers beside her grandfather''s grave.', NULL, 'Cô ấy đặt những bông hoa tươi bên cạnh ngôi mộ của ông mình.', '{"wordId":"grave","ukIpa":"/ɡreɪv/","usIpa":"/ɡreɪv/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"A place in the ground where a dead person is buried.","vi":"mộ; phần mộ"},{"pos":"adj.","en":"Very serious and giving cause for concern.","vi":"trầm trọng; nghiêm trọng"},{"pos":"adj.","en":"Showing a serious or solemn expression or manner.","vi":"trang nghiêm; nghiêm nghị"}],"examples":[{"en":"She placed fresh flowers beside her grandfather''s grave.","vi":"Cô ấy đặt những bông hoa tươi bên cạnh ngôi mộ của ông mình.","audioKind":"ex"},{"en":"The destruction of coastal habitats poses a grave threat to biodiversity and the livelihoods of local communities.","vi":"Sự tàn phá các sinh cảnh ven biển đặt ra mối đe dọa nghiêm trọng đối với đa dạng sinh học và sinh kế của cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"visit a grave","vi":"viếng mộ; thăm mộ"},{"en":"a grave threat","vi":"mối đe dọa nghiêm trọng"},{"en":"grave consequences","vi":"hậu quả nghiêm trọng"}],"wordFamily":["gravely (adv.)","graveness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi dùng làm tính từ, từ này mang tính trang trọng hơn serious và thường bổ nghĩa cho các từ chỉ mối đe dọa hoặc hậu quả.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_incident', 'en-b2-13', 'incident', '/ˈɪnsɪdənt/', 'B2', 'sự việc; sự cố', 'n.', NULL, 'Đồng nghĩa: event, occurrence', 'incident chỉ một sự việc cụ thể; trong khi incidence chỉ tỷ lệ mắc phải hoặc tần suất xảy ra.', 'Nobody was hurt in the incident outside the station.', NULL, 'Không có ai bị thương trong sự cố xảy ra bên ngoài nhà ga.', '{"wordId":"incident","ukIpa":"/ˈɪnsɪdənt/","usIpa":"/ˈɪnsɪdənt/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"An event, especially one that is unusual or unpleasant.","vi":"sự việc; sự cố"}],"examples":[{"en":"Nobody was hurt in the incident outside the station.","vi":"Không có ai bị thương trong sự cố xảy ra bên ngoài nhà ga.","audioKind":"ex"},{"en":"Every workplace incident should be investigated carefully so that employers can identify risks and prevent similar problems.","vi":"Mỗi sự cố tại nơi làm việc cần được điều tra cẩn thận để người sử dụng lao động có thể nhận diện rủi ro và ngăn ngừa các vấn đề tương tự.","audioKind":"ex2"}],"collocations":[{"en":"report an incident","vi":"báo cáo một sự việc"},{"en":"a serious incident","vi":"một sự cố nghiêm trọng"},{"en":"an isolated incident","vi":"một sự việc đơn lẻ"},{"en":"without incident","vi":"bình an vô sự; không có sự cố đáng tiếc nào"}],"wordFamily":[],"synonyms":["event","occurrence"],"antonyms":[],"tipVi":"incident chỉ một sự việc cụ thể; trong khi incidence chỉ tỷ lệ mắc phải hoặc tần suất xảy ra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_strictly', 'en-b2-13', 'strictly', '/ˈstrɪktli/', 'B2', 'một cách nghiêm ngặt; nghiêm túc; hoàn toàn; chỉ; một cách chính xác', 'adv.', 'strict (adj.), strictness (n.)', 'Đồng nghĩa: rigorously · Trái nghĩa: loosely', 'strictly speaking là cố định biểu đạt, ý nghĩa là "strictly speaking".', 'The swimming pool strictly enforces its rule against running.', NULL, 'Hồ bơi thực hiện nghiêm ngặt quy định cấm chạy nhảy.', '{"wordId":"strictly","ukIpa":"/ˈstrɪktli/","usIpa":"/ˈstrɪktli/","cefr":"B2","topic":"society","senses":[{"pos":"adv.","en":"with rules followed or enforced exactly","vi":"một cách nghiêm ngặt; nghiêm túc"},{"pos":"adv.","en":"only, without including anything or anyone else","vi":"hoàn toàn; chỉ"},{"pos":"adv.","en":"in a completely exact or accurate way","vi":"một cách chính xác"}],"examples":[{"en":"The swimming pool strictly enforces its rule against running.","vi":"Hồ bơi thực hiện nghiêm ngặt quy định cấm chạy nhảy.","audioKind":"ex"},{"en":"Environmental regulations must be strictly enforced if governments are to protect rivers from industrial pollution.","vi":"Các quy định về môi trường phải được thực thi nghiêm ngặt nếu các chính phủ muốn bảo vệ các con sông khỏi ô nhiễm công nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"strictly prohibited","vi":"bị nghiêm cấm"},{"en":"strictly confidential","vi":"được giữ bí mật tuyệt đối"},{"en":"strictly speaking","vi":"nghiêm túc mà nói"},{"en":"strictly limited to","vi":"giới hạn nghiêm ngặt trong"}],"wordFamily":["strict (adj.)","strictness (n.)"],"synonyms":["rigorously"],"antonyms":["loosely"],"tipVi":"strictly speaking là cố định biểu đạt, ý nghĩa là \"strictly speaking\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_threaten', 'en-b2-13', 'threaten', '/ˈθretn/', 'B2', 'đe dọa; khủng bố tinh thần; làm nguy hại; có nguy cơ gây tổn hại', 'v.', 'threat (n.), threatening (adj.), threatened (adj.)', 'Đồng nghĩa: menace, endanger', 'threaten to do chỉ đe dọa làm gì; threaten sth có thể chỉ nguy hại đến điều gì.', 'They threatened to cancel our booking unless we paid today.', NULL, 'Họ đe dọa sẽ hủy đặt chỗ của chúng tôi nếu chúng tôi không thanh toán ngay trong ngày hôm nay.', '{"wordId":"threaten","ukIpa":"/ˈθretn/","usIpa":"/ˈθretn/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"Say you will cause harm or trouble unless demands are met","vi":"đe dọa; khủng bố tinh thần"},{"pos":"v.","en":"Put something at risk or make something harmful seem likely","vi":"làm nguy hại; có nguy cơ gây tổn hại"}],"examples":[{"en":"They threatened to cancel our booking unless we paid today.","vi":"Họ đe dọa sẽ hủy đặt chỗ của chúng tôi nếu chúng tôi không thanh toán ngay trong ngày hôm nay.","audioKind":"ex"},{"en":"Rising sea levels threaten coastal communities by increasing the frequency of flooding and damaging essential infrastructure.","vi":"Mực nước biển dâng cao đang đe dọa các cộng đồng ven biển bằng cách làm tăng tần suất ngập lụt và phá hủy cơ sở hạ tầng thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"threaten to do something","vi":"đe dọa làm điều gì đó"},{"en":"threaten someone''s safety","vi":"đe dọa sự an toàn của ai đó"},{"en":"threaten livelihoods","vi":"đe dọa sinh kế"},{"en":"be threatened with closure","vi":"đối mặt với nguy cơ bị đóng cửa"}],"wordFamily":["threat (n.)","threatening (adj.)","threatened (adj.)"],"synonyms":["menace","endanger"],"antonyms":[],"tipVi":"threaten to do chỉ đe dọa làm gì; threaten sth có thể chỉ nguy hại đến điều gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_affair', 'en-b2-13', 'affair', '/əˈfer/', 'B2', 'việc; sự kiện; vấn đề; chuyện ngoại tình; mối quan hệ ngoài luồng', 'n.', NULL, 'Đồng nghĩa: matter, event', 'Chỉ công việc chung thường dùng số nhiều affairs, ví dụ như current affairs.', 'The family picnic was a cheerful affair despite the rain.', NULL, 'Buổi dã ngoại của gia đình là một sự kiện vui vẻ bất chấp trời mưa.', '{"wordId":"affair","ukIpa":"/əˈfeə/","usIpa":"/əˈfer/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"a matter, event, or activity concerning someone","vi":"việc; sự kiện; vấn đề"},{"pos":"n.","en":"a romantic relationship involving someone committed to another partner","vi":"chuyện ngoại tình; mối quan hệ ngoài luồng"}],"examples":[{"en":"The family picnic was a cheerful affair despite the rain.","vi":"Buổi dã ngoại của gia đình là một sự kiện vui vẻ bất chấp trời mưa.","audioKind":"ex"},{"en":"Schools can encourage young people to take an interest in current affairs through regular discussions of global events.","vi":"Nhà trường có thể khuyến khích người trẻ quan tâm đến các vấn đề thời sự thông qua các cuộc thảo luận thường xuyên về các sự kiện toàn cầu.","audioKind":"ex2"}],"collocations":[{"en":"current affairs","vi":"thời sự"},{"en":"foreign affairs","vi":"ngoại giao; công việc đối ngoại"},{"en":"a private affair","vi":"việc riêng tư"},{"en":"have an affair","vi":"có quan hệ ngoài luồng; ngoại tình"}],"wordFamily":[],"synonyms":["matter","event"],"antonyms":[],"tipVi":"Chỉ công việc chung thường dùng số nhiều affairs, ví dụ như current affairs.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gamble', 'en-b2-13', 'gamble', '/ˈɡæmbəl/', 'B2', 'đánh bạc; cá cược; mạo hiểm; đánh liều; sự mạo hiểm; canh bạc', 'v.', 'gambler (n.), gambling (n.)', 'Đồng nghĩa: bet, risk', 'Sau "gamble on" là sự việc mà bạn đặt cược hoặc mạo hiểm trông chờ vào.', 'He refuses to gamble because he values his savings.', NULL, 'Anh ấy từ chối đánh bạc vì trân trọng số tiền tiết kiệm của mình.', '{"wordId":"gamble","ukIpa":"/ˈɡæmbəl/","usIpa":"/ˈɡæmbəl/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"to risk money on an uncertain result hoping to win more","vi":"đánh bạc; cá cược"},{"pos":"v.","en":"to take a risk in the hope of success","vi":"mạo hiểm; đánh liều"},{"pos":"n.","en":"an action with an uncertain outcome and a risk of loss","vi":"sự mạo hiểm; canh bạc"}],"examples":[{"en":"He refuses to gamble because he values his savings.","vi":"Anh ấy từ chối đánh bạc vì trân trọng số tiền tiết kiệm của mình.","audioKind":"ex"},{"en":"Relying entirely on tourism is a gamble for regions vulnerable to extreme weather and changing travel patterns.","vi":"Việc phụ thuộc hoàn toàn vào du lịch là một canh bạc đối với những khu vực dễ bị ảnh hưởng bởi thời tiết khắc nghiệt và xu hướng du lịch thay đổi.","audioKind":"ex2"}],"collocations":[{"en":"gamble on","vi":"đánh cược vào; mạo hiểm trông chờ vào"},{"en":"gamble away savings","vi":"đánh bạc hết tiền tiết kiệm"},{"en":"take a gamble","vi":"liều một phen"}],"wordFamily":["gambler (n.)","gambling (n.)"],"synonyms":["bet","risk"],"antonyms":[],"tipVi":"Sau \"gamble on\" là sự việc mà bạn đặt cược hoặc mạo hiểm trông chờ vào.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_representative', 'en-b2-13', 'representative', '/ˌreprɪˈzentətɪv/', 'B2', 'người đại diện; người ủy quyền; có tính đại diện; tiêu biểu', 'n.', 'represent (v.), representation (n.), unrepresentative (adj.)', 'Đồng nghĩa: delegate, typical · Trái nghĩa: unrepresentative', 'Tính từ thường đi với giới từ of: representative of một nhóm nào đó.', 'Our class representative asked for more books in the library.', NULL, 'Lớp trưởng của chúng tôi đã đề nghị bổ sung thêm sách trong thư viện.', '{"wordId":"representative","ukIpa":"/ˌreprɪˈzentətɪv/","usIpa":"/ˌreprɪˈzentətɪv/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"someone chosen to speak or act for other people","vi":"người đại diện; người ủy quyền"},{"pos":"adj.","en":"showing the usual features of a larger group","vi":"có tính đại diện; tiêu biểu"}],"examples":[{"en":"Our class representative asked for more books in the library.","vi":"Lớp trưởng của chúng tôi đã đề nghị bổ sung thêm sách trong thư viện.","audioKind":"ex"},{"en":"Researchers need a representative sample to draw reliable conclusions about the wider population.","vi":"Các nhà nghiên cứu cần một mẫu có tính đại diện để đưa ra các kết luận đáng tin cậy về tổng thể dân số rộng lớn hơn.","audioKind":"ex2"}],"collocations":[{"en":"a representative sample","vi":"một mẫu đại diện"},{"en":"a sales representative","vi":"đại diện bán hàng"},{"en":"representative of","vi":"mang tính đại diện cho"},{"en":"an elected representative","vi":"đại diện được bầu chọn"}],"wordFamily":["represent (v.)","representation (n.)","unrepresentative (adj.)"],"synonyms":["delegate","typical"],"antonyms":["unrepresentative"],"tipVi":"Tính từ thường đi với giới từ of: representative of một nhóm nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_noble', 'en-b2-13', 'noble', '/ˈnoʊbəl/', 'B2', 'cao thượng; cao cả; thuộc giới quý tộc; người quý tộc', 'adj.', 'nobility (n.), nobly (adv.)', 'Đồng nghĩa: honourable · Trái nghĩa: ignoble', 'Nghĩa "cao thượng" nhấn mạnh phẩm chất đạo đức, không phải địa vị xã hội.', 'Helping strangers without expecting rewards is a noble act.', NULL, 'Giúp đỡ người lạ mà không mong cầu đền đáp là một hành động cao thượng.', '{"wordId":"noble","ukIpa":"/ˈnəʊbəl/","usIpa":"/ˈnoʊbəl/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"showing strong moral qualities and concern for others","vi":"cao thượng; cao cả"},{"pos":"adj.","en":"belonging to a family with high inherited social rank","vi":"thuộc giới quý tộc"},{"pos":"n.","en":"a person belonging to a high-ranking hereditary social class","vi":"người quý tộc"}],"examples":[{"en":"Helping strangers without expecting rewards is a noble act.","vi":"Giúp đỡ người lạ mà không mong cầu đền đáp là một hành động cao thượng.","audioKind":"ex"},{"en":"Although reducing poverty is a noble goal, effective policies require sustained funding and careful evaluation.","vi":"Mặc dù giảm nghèo là một mục tiêu cao cả, các chính sách hiệu quả đòi hỏi nguồn vốn duy trì liên tục và sự đánh giá cẩn trọng.","audioKind":"ex2"}],"collocations":[{"en":"noble cause","vi":"sự nghiệp cao cả"},{"en":"noble gesture","vi":"cử chỉ cao thượng"},{"en":"noble family","vi":"gia đình quý tộc"}],"wordFamily":["nobility (n.)","nobly (adv.)"],"synonyms":["honourable"],"antonyms":["ignoble"],"tipVi":"Nghĩa \"cao thượng\" nhấn mạnh phẩm chất đạo đức, không phải địa vị xã hội.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_discrimination', 'en-b2-13', 'discrimination', '/dɪˌskrɪməˈneɪʃən/', 'B2', 'sự phân biệt đối xử; khả năng phân biệt; sự tinh tường', 'n.', 'discriminate (v.), discriminatory (adj.), discriminating (adj.)', NULL, 'Phân biệt đối xử với nhóm nào dùng discrimination against; thường là danh từ không đếm được.', 'She reported age discrimination after losing a job opportunity.', NULL, 'Cô ấy đã báo cáo về việc bị phân biệt tuổi tác sau khi mất cơ hội việc làm.', '{"wordId":"discrimination","ukIpa":"/dɪˌskrɪmɪˈneɪʃən/","usIpa":"/dɪˌskrɪməˈneɪʃən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"unfair treatment based on someone''s identity or personal characteristics","vi":"sự phân biệt đối xử"},{"pos":"n.","en":"the ability or process of noticing differences between things","vi":"khả năng phân biệt; sự tinh tường"}],"examples":[{"en":"She reported age discrimination after losing a job opportunity.","vi":"Cô ấy đã báo cáo về việc bị phân biệt tuổi tác sau khi mất cơ hội việc làm.","audioKind":"ex"},{"en":"Stronger laws against discrimination can help ensure that all citizens have equal access to employment.","vi":"Các đạo luật chống phân biệt đối xử chặt chẽ hơn có thể giúp đảm bảo mọi công dân đều có cơ hội tiếp cận việc làm bình đẳng.","audioKind":"ex2"}],"collocations":[{"en":"racial discrimination","vi":"phân biệt chủng tộc"},{"en":"age discrimination","vi":"phân biệt tuổi tác"},{"en":"discrimination against","vi":"sự phân biệt đối xử với"},{"en":"visual discrimination","vi":"khả năng phân biệt thị giác"}],"wordFamily":["discriminate (v.)","discriminatory (adj.)","discriminating (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Phân biệt đối xử với nhóm nào dùng discrimination against; thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_worship', 'en-b2-13', 'worship', '/ˈwɜːrʃɪp/', 'B2', 'sự thờ phụng; lễ thờ cúng; thờ cúng; tôn kính; tôn sùng; ngưỡng mộ cực độ', 'n.', 'worshipper (n.), worshipful (adj.)', 'Đồng nghĩa: adore, revere', 'Thì quá khứ theo kiểu Anh-Anh là worshipped, còn Anh-Mỹ thường viết là worshiped.', 'They gather for worship in a small village chapel.', NULL, 'Họ tụ tập để làm lễ tại một nhà nguyện nhỏ trong làng.', '{"wordId":"worship","ukIpa":"/ˈwɜːʃɪp/","usIpa":"/ˈwɜːrʃɪp/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"acts of showing respect and devotion to a god","vi":"sự thờ phụng; lễ thờ cúng"},{"pos":"v.","en":"to show respect and devotion to a god","vi":"thờ cúng; tôn kính"},{"pos":"v.","en":"to admire or love someone extremely strongly","vi":"tôn sùng; ngưỡng mộ cực độ"}],"examples":[{"en":"They gather for worship in a small village chapel.","vi":"Họ tụ tập để làm lễ tại một nhà nguyện nhỏ trong làng.","audioKind":"ex"},{"en":"Historic places of worship often serve as important centres of community life and cultural heritage.","vi":"Các nơi thờ tự có lịch sử lâu đời thường đóng vai trò là trung tâm quan trọng của đời sống cộng đồng và di sản văn hóa.","audioKind":"ex2"}],"collocations":[{"en":"place of worship","vi":"nơi thờ cúng"},{"en":"freedom of worship","vi":"tự do tín ngưỡng"},{"en":"religious worship","vi":"sự thờ cúng tôn giáo"},{"en":"hero worship","vi":"sự tôn sùng thần tượng"}],"wordFamily":["worshipper (n.)","worshipful (adj.)"],"synonyms":["adore","revere"],"antonyms":[],"tipVi":"Thì quá khứ theo kiểu Anh-Anh là worshipped, còn Anh-Mỹ thường viết là worshiped.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_superstition', 'en-b2-13', 'superstition', '/ˌsuːpərˈstɪʃən/', 'B2', 'sự mê tín; điều mê tín dị đoan', 'n.', 'superstitious (adj.), superstitiously (adv.)', NULL, 'Nói chung về thói quen mê tín thì không đếm được; một quan niệm mê tín cụ thể thì đếm được.', 'My uncle avoids walking under ladders because of superstition.', NULL, 'Chú tôi tránh đi dưới các bậc thang vì sự mê tín.', '{"wordId":"superstition","ukIpa":"/ˌsuːpəˈstɪʃən/","usIpa":"/ˌsuːpərˈstɪʃən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"An unsupported belief linking events or actions to supernatural forces.","vi":"sự mê tín; điều mê tín dị đoan"}],"examples":[{"en":"My uncle avoids walking under ladders because of superstition.","vi":"Chú tôi tránh đi dưới các bậc thang vì sự mê tín.","audioKind":"ex"},{"en":"Science education can help students distinguish evidence-based explanations from superstition while respecting different cultural traditions.","vi":"Giáo dục khoa học có thể giúp học sinh phân biệt các giải thích có căn cứ bằng chứng với sự mê tín, đồng thời tôn trọng các truyền thống văn hóa khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"popular superstition","vi":"quan niệm mê tín phổ biến"},{"en":"out of superstition","vi":"vì sự mê tín"},{"en":"superstition about bad luck","vi":"sự mê tín về vận rủi"}],"wordFamily":["superstitious (adj.)","superstitiously (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Nói chung về thói quen mê tín thì không đếm được; một quan niệm mê tín cụ thể thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prominent', 'en-b2-13', 'prominent', '/ˈprɑːmɪnənt/', 'B2', 'nổi bật, nổi tiếng, có tầm ảnh hưởng; dễ thấy, dễ nhận biết (do vị trí, kích thước hoặc hình dáng)', 'adj.', 'prominence (n.), prominently (adv.)', 'Đồng nghĩa: notable, conspicuous · Trái nghĩa: obscure, inconspicuous', 'Có thể dùng để chỉ người quan trọng nổi tiếng, hoặc chỉ vị trí, hình dáng nổi bật, dễ nhìn thấy.', 'A prominent local artist opened the exhibition yesterday.', NULL, 'Một họa sĩ nổi tiếng tại địa phương đã khai mạc triển lãm ngày hôm qua.', '{"wordId":"prominent","ukIpa":"/ˈprɒmɪnənt/","usIpa":"/ˈprɑːmɪnənt/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Important, well known, or influential","vi":"nổi bật, nổi tiếng, có tầm ảnh hưởng"},{"pos":"adj.","en":"Easily noticed because of position, size, or shape","vi":"dễ thấy, dễ nhận biết (do vị trí, kích thước hoặc hình dáng)"}],"examples":[{"en":"A prominent local artist opened the exhibition yesterday.","vi":"Một họa sĩ nổi tiếng tại địa phương đã khai mạc triển lãm ngày hôm qua.","audioKind":"ex"},{"en":"Universities play a prominent role in developing technologies that support the transition to renewable energy.","vi":"Các trường đại học đóng vai trò quan trọng trong việc phát triển các công nghệ hỗ trợ quá trình chuyển đổi sang năng lượng tái tạo.","audioKind":"ex2"}],"collocations":[{"en":"a prominent role","vi":"vai trò quan trọng"},{"en":"a prominent figure","vi":"nhân vật nổi tiếng"},{"en":"a prominent position","vi":"vị trí dễ thấy"}],"wordFamily":["prominence (n.)","prominently (adv.)"],"synonyms":["notable","conspicuous"],"antonyms":["obscure","inconspicuous"],"tipVi":"Có thể dùng để chỉ người quan trọng nổi tiếng, hoặc chỉ vị trí, hình dáng nổi bật, dễ nhìn thấy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reunion', 'en-b2-13', 'reunion', '/ˌriːˈjuːniən/', 'B2', 'cuộc sum họp; sự đoàn tụ; buổi gặp mặt', 'n.', 'reunite (v.), reunited (adj.)', NULL, 'Nhấn mạnh sự gặp lại sau một thời gian xa cách, không dùng chung cho mọi loại tiệc tùng.', 'Our family reunion filled the garden with laughter.', NULL, 'Buổi họp mặt gia đình của chúng tôi đã làm ngập tràn khu vườn bằng những tiếng cười.', '{"wordId":"reunion","ukIpa":"/ˌriːˈjuːniən/","usIpa":"/ˌriːˈjuːniən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"An occasion when people meet again after time apart.","vi":"cuộc sum họp; sự đoàn tụ; buổi gặp mặt"}],"examples":[{"en":"Our family reunion filled the garden with laughter.","vi":"Buổi họp mặt gia đình của chúng tôi đã làm ngập tràn khu vườn bằng những tiếng cười.","audioKind":"ex"},{"en":"School reunions can strengthen social connections and encourage former students to support their local communities.","vi":"Các buổi họp lớp có thể củng cố các mối quan hệ xã hội và khuyến khích cựu học sinh hỗ trợ cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"family reunion","vi":"cuộc đoàn tụ gia đình"},{"en":"school reunion","vi":"buổi họp lớp; buổi họp mặt cựu học sinh"},{"en":"a joyful reunion","vi":"một cuộc hội ngộ vui vẻ"}],"wordFamily":["reunite (v.)","reunited (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nhấn mạnh sự gặp lại sau một thời gian xa cách, không dùng chung cho mọi loại tiệc tùng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_privacy', 'en-b2-13', 'privacy', '/ˈpraɪvəsi/', 'B2', 'sự riêng tư; quyền riêng tư; sự ên ấm, độc lập; sự không bị làm phiền', 'n.', 'private (adj.), privately (adv.)', NULL, 'Thông thường là danh từ không đếm được; phát âm ở Anh và Mỹ có sự khác biệt rõ rệt ở âm tiết đầu tiên.', 'Please knock before entering; everyone needs a little privacy.', NULL, 'Vui lòng gõ cửa trước khi vào; ai cũng cần có chút không gian riêng tư.', '{"wordId":"privacy","ukIpa":"/ˈprɪvəsi/","usIpa":"/ˈpraɪvəsi/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"Freedom from unwanted access to personal information or private life.","vi":"sự riêng tư; quyền riêng tư"},{"pos":"n.","en":"The state of being alone and free from disturbance.","vi":"sự ên ấm, độc lập; sự không bị làm phiền"}],"examples":[{"en":"Please knock before entering; everyone needs a little privacy.","vi":"Vui lòng gõ cửa trước khi vào; ai cũng cần có chút không gian riêng tư.","audioKind":"ex"},{"en":"Governments should protect individual privacy while allowing researchers to use anonymous data for public health studies.","vi":"Chính phủ nên bảo vệ quyền riêng tư của cá nhân trong khi vẫn cho phép các nhà nghiên cứu sử dụng dữ liệu ẩn danh cho các nghiên cứu y tế công cộng.","audioKind":"ex2"}],"collocations":[{"en":"protect privacy","vi":"bảo vệ quyền riêng tư"},{"en":"invasion of privacy","vi":"sự xâm phạm đời tư"},{"en":"privacy settings","vi":"cài đặt quyền riêng tư"},{"en":"in the privacy of your home","vi":"trong không gian riêng tư của ngôi nhà bạn"}],"wordFamily":["private (adj.)","privately (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Thông thường là danh từ không đếm được; phát âm ở Anh và Mỹ có sự khác biệt rõ rệt ở âm tiết đầu tiên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_widow', 'en-b2-13', 'widow', '/ˈwɪdoʊ/', 'B2', 'góa phụ; người phụ nữ góa chồng', 'n.', 'widower (n.), widowed (adj.), widowhood (n.)', NULL, 'widow chỉ phụ nữ góa chồng; đàn ông góa vợ dùng widower.', 'The widow next door invited us over for tea.', NULL, 'Bà góa phụ ở nhà bên cạnh đã mời chúng tôi sang uống trà.', '{"wordId":"widow","ukIpa":"/ˈwɪdəʊ/","usIpa":"/ˈwɪdoʊ/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"a woman whose spouse has died and who has not remarried","vi":"góa phụ; người phụ nữ góa chồng"}],"examples":[{"en":"The widow next door invited us over for tea.","vi":"Bà góa phụ ở nhà bên cạnh đã mời chúng tôi sang uống trà.","audioKind":"ex"},{"en":"A widow living alone may benefit from community programmes that offer companionship and practical support.","vi":"Một góa phụ sống một mình có thể được hưởng lợi từ các chương trình cộng đồng cung cấp sự đồng hành và hỗ trợ thiết thực.","audioKind":"ex2"}],"collocations":[{"en":"an elderly widow","vi":"một góa phụ lớn tuổi"},{"en":"a war widow","vi":"góa phụ chiến tranh"},{"en":"a young widow","vi":"một góa phụ trẻ tuổi"}],"wordFamily":["widower (n.)","widowed (adj.)","widowhood (n.)"],"synonyms":[],"antonyms":[],"tipVi":"widow chỉ phụ nữ góa chồng; đàn ông góa vợ dùng widower.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_13_1', 'en-b2-13', 'Cách dùng “hardship” (n.) — sự khốn khó; hoàn cảnh khó khăn (tình trạng thiếu thốn các nhu cầu thiết yếu)', 'financial hardship  ·  face hardship  ·  endure hardship', 'Khi dùng chỉ sự khốn khó chung, "hardship" thường không đếm được; các thử thách cụ thể có thể dùng dạng số nhiều "hardships".', 'Họ từ (Word Family): hard (adj.) | Đồng nghĩa: adversity, privation · Trái nghĩa: comfort', '[{"hanzi":"Losing her job caused months of hardship for the family.","pinyin":"","meaning":"Việc mất việc đã khiến gia đình trải qua nhiều tháng trời khốn khó."},{"hanzi":"Rising housing costs can cause significant financial hardship for families already struggling to afford basic necessities.","pinyin":"","meaning":"Chi phí nhà ở tăng cao có thể gây ra những khó khăn tài chính đáng kể cho các gia đình vốn đã chật vật để trang trải các nhu cầu thiết yếu cơ bản."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_13_2', 'en-b2-13', 'Cách dùng “grave” (n.) — mộ; phần mộ', 'visit a grave  ·  a grave threat  ·  grave consequences', 'Khi dùng làm tính từ, từ này mang tính trang trọng hơn serious và thường bổ nghĩa cho các từ chỉ mối đe dọa hoặc hậu quả.', 'Họ từ (Word Family): gravely (adv.), graveness (n.)', '[{"hanzi":"She placed fresh flowers beside her grandfather''s grave.","pinyin":"","meaning":"Cô ấy đặt những bông hoa tươi bên cạnh ngôi mộ của ông mình."},{"hanzi":"The destruction of coastal habitats poses a grave threat to biodiversity and the livelihoods of local communities.","pinyin":"","meaning":"Sự tàn phá các sinh cảnh ven biển đặt ra mối đe dọa nghiêm trọng đối với đa dạng sinh học và sinh kế của cộng đồng địa phương."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_13_3', 'en-b2-13', 'Cách dùng “privacy” (n.) — sự riêng tư; quyền riêng tư', 'protect privacy  ·  invasion of privacy  ·  privacy settings', 'Thông thường là danh từ không đếm được; phát âm ở Anh và Mỹ có sự khác biệt rõ rệt ở âm tiết đầu tiên.', 'Họ từ (Word Family): private (adj.), privately (adv.)', '[{"hanzi":"Please knock before entering; everyone needs a little privacy.","pinyin":"","meaning":"Vui lòng gõ cửa trước khi vào; ai cũng cần có chút không gian riêng tư."},{"hanzi":"Governments should protect individual privacy while allowing researchers to use anonymous data for public health studies.","pinyin":"","meaning":"Chính phủ nên bảo vệ quyền riêng tư của cá nhân trong khi vẫn cho phép các nhà nghiên cứu sử dụng dữ liệu ẩn danh cho các nghiên cứu y tế công cộng."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_13_4', 'en-b2-13', 'Cách dùng “guardian” (n.) — người giám hộ (người có trách nhiệm pháp lý đối với trẻ em hoặc người lớn cần chăm sóc)', 'legal guardian  ·  parent or guardian  ·  guardian of tradition', 'Trong ngữ cảnh pháp lý, "guardian" chỉ người giám hộ, không nhất thiết phải là cha mẹ của đứa trẻ.', 'Họ từ (Word Family): guard (v.), guardianship (n.) | Đồng nghĩa: protector, custodian', '[{"hanzi":"Her aunt became her legal guardian and cared for her.","pinyin":"","meaning":"Cô ấy trở thành người giám hộ hợp pháp của cô và chăm sóc cô."},{"hanzi":"Schools should involve parents or guardians in decisions that significantly affect children''s education and emotional wellbeing.","pinyin":"","meaning":"Nhà trường nên cho phép phụ huynh hoặc người giám hộ tham gia vào các quyết định ảnh hưởng đáng kể đến giáo dục và sự phát triển cảm xúc của trẻ em."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_13_1', 'en-b2-13', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_13_1_1', 'ten_b2_13_1', 'publicly', 'She publicly thanked the neighbours who found her cat.', 'She publicly thanked the neighbours who found her cat.', '/ˈpʌblɪkli/', 'Cô ấy đã công khai cảm ơn những người hàng xóm đã tìm thấy con mèo cho cô ấy.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_13_1_2', 'ten_b2_13_1', 'accessible', 'The garden is accessible through a small wooden gate.', 'The garden is accessible through a small wooden gate.', '/əkˈsesəbl/', 'Có thể đi vào khu vườn qua một cánh cửa gỗ nhỏ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_13_1_3', 'ten_b2_13_1', 'sin', 'He believed that lying to his friends was a sin.', 'He believed that lying to his friends was a sin.', '/sɪn/', 'Anh ấy tin rằng việc nói dối bạn bè là một tội lỗi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_13_1_4', 'ten_b2_13_1', 'resist', 'I could not resist buying another warm cinnamon bun.', 'I could not resist buying another warm cinnamon bun.', '/rɪˈzɪst/', 'Tôi không thể kiềm chế được việc mua thêm một chiếc bánh cuộn quế ấm nóng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_13_1_5', 'ten_b2_13_1', 'discriminate', 'Our club does not discriminate against anyone because of age.', 'Our club does not discriminate against anyone because of age.', '/dɪˈskrɪmɪneɪt/', 'Câu lạc bộ của chúng tôi không kỳ thị bất kỳ ai vì lý do độ tuổi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_13_1_6', 'ten_b2_13_1', 'flee', 'The birds fled when the dog entered the garden.', 'The birds fled when the dog entered the garden.', '/fliː/', 'Đàn chim bay tản mác khi con chó bước vào khu vực vườn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_13_1_7', 'ten_b2_13_1', 'freedom', 'Living alone gives me freedom to choose my own routine.', 'Living alone gives me freedom to choose my own routine.', '/ˈfriːdəm/', 'Sống một mình cho tôi sự tự do tự sắp xếp lịch trình sinh hoạt cá nhân.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_13_1_8', 'ten_b2_13_1', 'veil', 'She lifted her veil to take a sip of water.', 'She lifted her veil to take a sip of water.', '/veɪl/', 'Cô ấy nhấc mạng che mặt lên để nhấp một ngụm nước.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_13_1_1', 'en-b2-13', 'ten_b2_13_1', 'listening', 'listening', 'She publicly thanked the neighbours who found her cat.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy đã công khai cảm ơn những người hàng xóm đã tìm thấy con mèo cho cô ấy.","Anh ấy tin rằng việc nói dối bạn bè là một tội lỗi.","Cô ấy nhấc mạng che mặt lên để nhấp một ngụm nước.","Họ tụ tập để làm lễ tại một nhà nguyện nhỏ trong làng."]'::jsonb, 0, 'She publicly thanked the neighbours who found her cat. → Cô ấy đã công khai cảm ơn những người hàng xóm đã tìm thấy con mèo cho cô ấy.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_13_1_2', 'en-b2-13', 'ten_b2_13_1', 'listening', 'listening', 'The garden is accessible through a small wooden gate.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chú tôi tránh đi dưới các bậc thang vì sự mê tín.","Sống một mình cho tôi sự tự do tự sắp xếp lịch trình sinh hoạt cá nhân.","Có thể đi vào khu vườn qua một cánh cửa gỗ nhỏ.","Vui lòng gõ cửa trước khi vào; ai cũng cần có chút không gian riêng tư."]'::jsonb, 2, 'The garden is accessible through a small wooden gate. → Có thể đi vào khu vườn qua một cánh cửa gỗ nhỏ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_13_1_3', 'en-b2-13', 'ten_b2_13_1', 'listening', 'listening', 'He believed that lying to his friends was a sin.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Buổi họp mặt gia đình của chúng tôi đã làm ngập tràn khu vườn bằng những tiếng cười.","Việc mất việc đã khiến gia đình trải qua nhiều tháng trời khốn khó.","Anh ấy tin rằng việc nói dối bạn bè là một tội lỗi.","Một họa sĩ nổi tiếng tại địa phương đã khai mạc triển lãm ngày hôm qua."]'::jsonb, 2, 'He believed that lying to his friends was a sin. → Anh ấy tin rằng việc nói dối bạn bè là một tội lỗi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_13_2', 'en-b2-13', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_13_2_1', 'ten_b2_13_2', 'publicly', 'Research funded by taxpayers should be publicly available so that everyone can benefit from its findings.', 'Research funded by taxpayers should be publicly available so that everyone can benefit from its findings.', '/ˈpʌblɪkli/', 'Các nghiên cứu do người đóng thuế tài trợ nên được cung cấp công khai để mọi người đều có thể hưởng lợi từ kết quả nghiên cứu đó.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_13_2_2', 'ten_b2_13_2', 'accessible', 'Public libraries should provide digital resources that are accessible to users with a wide range of abilities.', 'Public libraries should provide digital resources that are accessible to users with a wide range of abilities.', '/əkˈsesəbl/', 'Các thư viện công cộng nên cung cấp các nguồn tài nguyên kỹ thuật số mà người dùng ở nhiều năng lực khác nhau đều có thể truy cập sử dụng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_13_2_3', 'ten_b2_13_2', 'sin', 'Ideas about sin can influence social attitudes, even in societies where religious participation is declining.', 'Ideas about sin can influence social attitudes, even in societies where religious participation is declining.', '/sɪn/', 'Quan niệm về tội lỗi có thể ảnh hưởng đến thái độ xã hội, ngay cả trong những xã hội mà mức độ tham gia tôn giáo đang suy giảm.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_13_2_4', 'ten_b2_13_2', 'resist', 'Employees may resist technological change if they believe new systems will threaten their job security.', 'Employees may resist technological change if they believe new systems will threaten their job security.', '/rɪˈzɪst/', 'Nhân viên có thể chống lại sự thay đổi công nghệ nếu họ tin rằng các hệ thống mới sẽ đe dọa sự ổn định công việc của họ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_13_2_5', 'ten_b2_13_2', 'discriminate', 'Employers must not discriminate against applicants on the basis of disability, gender, or cultural background.', 'Employers must not discriminate against applicants on the basis of disability, gender, or cultural background.', '/dɪˈskrɪmɪneɪt/', 'Người sử dụng lao động không được kỳ thị đối với ứng viên dựa trên cơ sở khuyết tật, giới tính hoặc nền tảng văn hóa.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_13_2_6', 'ten_b2_13_2', 'flee', 'Severe flooding can force rural families to flee their homes and seek shelter in nearby towns.', 'Severe flooding can force rural families to flee their homes and seek shelter in nearby towns.', '/fliː/', 'Những trận lụt dữ dội có thể buộc các gia đình nông thôn phải rời bỏ nhà cửa và tìm nơi trú ẩn tại các thị trấn lân cận.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_13_2_1', 'en-b2-13', 'ten_b2_13_2', 'listening', 'listening', 'Research funded by taxpayers should be publicly available so that everyone can benefit from its findings.', NULL, 'Trong câu vừa nghe, từ “publicly” mang nghĩa nào sau đây?', '["công khai; trước công chúng; một cách công khai","làm cho sai lạc; đánh lừa; dẫn dắt sai đường","đóng góp; góp phần","hạn chót; thời hạn cuối cùng"]'::jsonb, 0, '“publicly” (/ˈpʌblɪkli/): công khai; trước công chúng; một cách công khai. Câu đầy đủ: Research funded by taxpayers should be publicly available so that everyone can benefit from its findings.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_13_2_2', 'en-b2-13', 'ten_b2_13_2', 'listening', 'listening', 'Public libraries should provide digital resources that are accessible to users with a wide range of abilities.', NULL, 'Trong câu vừa nghe, từ “accessible” mang nghĩa nào sau đây?', '["sự tài trợ; việc hỗ trợ kinh phí","cầu chì; thiết bị ngắt điện an toàn","dễ tiếp cận, dễ vào, dễ lấy hoặc dễ sử dụng","vết thương; thương tích"]'::jsonb, 2, '“accessible” (/əkˈsesəbl/): dễ tiếp cận, dễ vào, dễ lấy hoặc dễ sử dụng. Câu đầy đủ: Public libraries should provide digital resources that are accessible to users with a wide range of abilities.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
