INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_13_2', 'en-b2-13', NULL, 'comprehensive_test', 'listening', 'The garden is accessible through a small wooden gate.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Có thể đi vào khu vườn qua một cánh cửa gỗ nhỏ.","Họ đe dọa sẽ hủy đặt chỗ của chúng tôi nếu chúng tôi không thanh toán ngay trong ngày hôm nay.","Cô ấy trở thành người giám hộ hợp pháp của cô và chăm sóc cô.","Cô ấy đã báo cáo về việc bị phân biệt tuổi tác sau khi mất cơ hội việc làm."]'::jsonb, 0, 'The garden is accessible through a small wooden gate. → Có thể đi vào khu vườn qua một cánh cửa gỗ nhỏ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_13_3', 'en-b2-13', NULL, 'comprehensive_test', 'listening', 'sin', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tội lỗi; điều răn phạm","sự phun trào (núi lửa)","cao thượng; cao cả","tính mới lạ; sự mới mẻ"]'::jsonb, 0, 'sin (/sɪn/) → tội lỗi; điều răn phạm; phạm tội; làm điều trái đạo đức', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_13_4', 'en-b2-13', NULL, 'comprehensive_test', 'listening', 'I could not resist buying another warm cinnamon bun.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Câu lạc bộ của chúng tôi không kỳ thị bất kỳ ai vì lý do độ tuổi.","Tôi không thể kiềm chế được việc mua thêm một chiếc bánh cuộn quế ấm nóng.","Anh ấy tin rằng việc nói dối bạn bè là một tội lỗi.","Sống một mình cho tôi sự tự do tự sắp xếp lịch trình sinh hoạt cá nhân."]'::jsonb, 1, 'I could not resist buying another warm cinnamon bun. → Tôi không thể kiềm chế được việc mua thêm một chiếc bánh cuộn quế ấm nóng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_13_5', 'en-b2-13', NULL, 'comprehensive_test', 'listening', 'discriminate', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["xây dựng; kiến tạo","đường chân trời","thực tế; thực sự","phân biệt đối xử; kỳ thị"]'::jsonb, 3, 'discriminate (/dɪˈskrɪmɪneɪt/) → phân biệt đối xử; kỳ thị; phân biệt; nhận biết sự khác biệt', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_13_6', 'en-b2-13', NULL, 'comprehensive_test', 'listening', 'The birds fled when the dog entered the garden.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Anh ấy từ chối đánh bạc vì trân trọng số tiền tiết kiệm của mình.","Có thể đi vào khu vườn qua một cánh cửa gỗ nhỏ.","Đàn chim bay tản mác khi con chó bước vào khu vực vườn.","Cô ấy đặt những bông hoa tươi bên cạnh ngôi mộ của ông mình."]'::jsonb, 2, 'The birds fled when the dog entered the garden. → Đàn chim bay tản mác khi con chó bước vào khu vực vườn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_13_7', 'en-b2-13', NULL, 'comprehensive_test', 'listening', 'freedom', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tiền kiếm được, thu nhập (tiền nhận được từ việc làm việc)","ống mềm (dùng để dẫn nước hoặc chất lỏng khác)","sự lo lắng; sự quan tâm","tự do; quyền tự chủ"]'::jsonb, 3, 'freedom (/ˈfriːdəm/) → tự do; quyền tự chủ; sự thoát khỏi; sự miễn trừ', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_13_8', 'en-b2-13', NULL, 'comprehensive_test', 'listening', 'She lifted her veil to take a sip of water.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy nhấc mạng che mặt lên để nhấp một ngụm nước.","Cô ấy đặt những bông hoa tươi bên cạnh ngôi mộ của ông mình.","Cô ấy trở thành người giám hộ hợp pháp của cô và chăm sóc cô.","Giúp đỡ người lạ mà không mong cầu đền đáp là một hành động cao thượng."]'::jsonb, 0, 'She lifted her veil to take a sip of water. → Cô ấy nhấc mạng che mặt lên để nhấp một ngụm nước.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
