INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_13_18', 'en-b2-13', NULL, 'comprehensive_test', 'reading', NULL, 'Research funded by taxpayers should be publicly available so that everyone can benefit from its findings.', 'Dựa vào câu trên, từ “publicly” có nghĩa phù hợp nhất là gì?', '["thính giác; khả năng nghe","công khai; trước công chúng; một cách công khai","làm cho ổn định, giữ vững, trở nên vững vàng","ghi danh; đăng ký; tuyển sinh"]'::jsonb, 1, 'publicly: công khai; trước công chúng; một cách công khai; bằng nguồn vốn hoặc sự sở hữu của chính phủ hoặc cộng đồng. Dịch cả câu: Các nghiên cứu do người đóng thuế tài trợ nên được cung cấp công khai để mọi người đều có thể hưởng lợi từ kết quả nghiên cứu đó.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_13_19', 'en-b2-13', NULL, 'comprehensive_test', 'reading', NULL, 'Public libraries should provide digital resources that are accessible to users with a wide range of abilities.', 'Dựa vào câu trên, từ “accessible” có nghĩa phù hợp nhất là gì?', '["tủ có ngăn kéo để đựng quần áo (kiểu Mỹ)","truyền (tín hiệu, thông tin, năng lượng)","dễ tiếp cận, dễ vào, dễ lấy hoặc dễ sử dụng","con sứa (động vật biển thân mềm có xúc tu gây ngứa)"]'::jsonb, 2, 'accessible: dễ tiếp cận, dễ vào, dễ lấy hoặc dễ sử dụng; dễ hiểu, dễ tiếp thu đối với mọi người. Dịch cả câu: Các thư viện công cộng nên cung cấp các nguồn tài nguyên kỹ thuật số mà người dùng ở nhiều năng lực khác nhau đều có thể truy cập sử dụng.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_13_20', 'en-b2-13', NULL, 'comprehensive_test', 'reading', NULL, 'Ideas about sin can influence social attitudes, even in societies where religious participation is declining.', 'Dựa vào câu trên, từ “sin” có nghĩa phù hợp nhất là gì?', '["trụ sở chính; tổng hành dinh","vấp ngã; lạng quạng","không màu; trong suốt","tội lỗi; điều răn phạm"]'::jsonb, 3, 'sin: tội lỗi; điều răn phạm; phạm tội; làm điều trái đạo đức. Dịch cả câu: Quan niệm về tội lỗi có thể ảnh hưởng đến thái độ xã hội, ngay cả trong những xã hội mà mức độ tham gia tôn giáo đang suy giảm.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_13_21', 'en-b2-13', NULL, 'comprehensive_test', 'reading', NULL, 'Employees may resist technological change if they believe new systems will threaten their job security.', 'Dựa vào câu trên, từ “resist” có nghĩa phù hợp nhất là gì?', '["đión rén; di chuyển rón rén","biện pháp phòng ngừa; biện pháp đề phòng","chống lại; kháng cự","liên tục; luôn luôn; thường xuyên"]'::jsonb, 2, 'resist: chống lại; kháng cự; nhịn; cưỡng lại; kiềm chế; chịu đựng. Dịch cả câu: Nhân viên có thể chống lại sự thay đổi công nghệ nếu họ tin rằng các hệ thống mới sẽ đe dọa sự ổn định công việc của họ.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
