INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_13_24', 'en-b2-13', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “góa phụ; người phụ nữ góa chồng”', '["widow","perspective","joint","commute"]'::jsonb, 0, 'góa phụ; người phụ nữ góa chồng → widow (/ˈwɪdoʊ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-14', 'en', 'Bài 14: Xã hội & Cộng đồng (7) - CEFR B2', 'CEFR B2', 'B2 · Xã hội', '26 từ vựng Tiếng Anh CEFR B2 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4014, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mercy', 'en-b2-14', 'mercy', '/ˈmɝːsi/', 'B2', 'sự khoan dung; lòng trắc ẩn; sự nhân nhượng (không trừng phạt hoặc làm hại)', 'n.', 'merciful (adj.), merciless (adj.), mercifully (adv.)', 'Đồng nghĩa: compassion, leniency · Trái nghĩa: cruelty', 'Cố định at the mercy of có nghĩa là hoàn toàn bị chi phối hoặc phó mặc cho ai/cái gì.', 'The teacher showed mercy and accepted my late homework.', NULL, 'Cô giáo đã tỏ lòng khoan dung và chấp nhận bài tập về nhà nộp muộn của tôi.', '{"wordId":"mercy","ukIpa":"/ˈmɜːsi/","usIpa":"/ˈmɝːsi/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"Kindness shown by choosing not to punish or harm someone.","vi":"sự khoan dung; lòng trắc ẩn; sự nhân nhượng (không trừng phạt hoặc làm hại)"}],"examples":[{"en":"The teacher showed mercy and accepted my late homework.","vi":"Cô giáo đã tỏ lòng khoan dung và chấp nhận bài tập về nhà nộp muộn của tôi.","audioKind":"ex"},{"en":"A fair justice system should balance appropriate punishment with mercy towards people who genuinely seek to change.","vi":"Một hệ thống tư pháp công bằng phải cân bằng giữa hình phạt thích đáng và sự khoan hồng đối với những người thực sự muốn hướng thiện.","audioKind":"ex2"}],"collocations":[{"en":"show mercy","vi":"thể hiện lòng nhân từ"},{"en":"beg for mercy","vi":"cầu xin sự tha thứ"},{"en":"at the mercy of","vi":"phó mặc cho ai đó định đoạt"},{"en":"without mercy","vi":"không mảy may thương xót"}],"wordFamily":["merciful (adj.)","merciless (adj.)","mercifully (adv.)"],"synonyms":["compassion","leniency"],"antonyms":["cruelty"],"tipVi":"Cố định at the mercy of có nghĩa là hoàn toàn bị chi phối hoặc phó mặc cho ai/cái gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rural', 'en-b2-14', 'rural', '/ˈrʊrəl/', 'B2', 'thuộc nông thôn; thuộc vùng quê', 'adj.', 'rurally (adv.)', 'Trái nghĩa: urban', 'rural dùng để chỉ các vấn đề ở vùng quê, còn urban dùng cho thành thị.', 'My grandparents live in a quiet rural village.', NULL, 'Ông bà tôi sống trong một ngôi làng nông thôn yên bình.', '{"wordId":"rural","ukIpa":"/ˈrʊərəl/","usIpa":"/ˈrʊrəl/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Relating to the countryside rather than towns or cities.","vi":"thuộc nông thôn; thuộc vùng quê"}],"examples":[{"en":"My grandparents live in a quiet rural village.","vi":"Ông bà tôi sống trong một ngôi làng nông thôn yên bình.","audioKind":"ex"},{"en":"Reliable internet access can improve educational opportunities for children living in remote rural areas.","vi":"Khả năng truy cập internet ổn định có thể cải thiện cơ hội giáo dục cho trẻ em sống ở các vùng nông thôn hẻo lánh.","audioKind":"ex2"}],"collocations":[{"en":"rural areas","vi":"các vùng nông thôn"},{"en":"rural communities","vi":"cộng đồng nông thôn"},{"en":"rural development","vi":"phát triển nông thôn"},{"en":"rural population","vi":"dân số nông thôn"}],"wordFamily":["rurally (adv.)"],"synonyms":[],"antonyms":["urban"],"tipVi":"rural dùng để chỉ các vấn đề ở vùng quê, còn urban dùng cho thành thị.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sacred', 'en-b2-14', 'sacred', '/ˈseɪkrɪd/', 'B2', 'thần thánh; thiêng liêng; bất khả xâm phạm; được coi trọng tuyệt đối', 'adj.', 'sacredness (n.)', 'Đồng nghĩa: holy', 'sacred có thể chỉ tính thiêng liêng tôn giáo hoặc sự tôn kính tối cao, bất khả xâm phạm.', 'Visitors remove their shoes before entering the sacred temple.', NULL, 'Du khách phải cởi giày trước khi bước vào ngôi đền thiêng.', '{"wordId":"sacred","ukIpa":"/ˈseɪkrɪd/","usIpa":"/ˈseɪkrɪd/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Connected with religion and deserving deep respect","vi":"thần thánh; thiêng liêng"},{"pos":"adj.","en":"Considered too important or valuable to change or harm","vi":"bất khả xâm phạm; được coi trọng tuyệt đối"}],"examples":[{"en":"Visitors remove their shoes before entering the sacred temple.","vi":"Du khách phải cởi giày trước khi bước vào ngôi đền thiêng.","audioKind":"ex"},{"en":"Tourism can support local economies, but visitors must respect sacred places and religious customs.","vi":"Du lịch có thể hỗ trợ kinh tế địa phương, nhưng du khách phải tôn trọng các thánh địa và phong tục tôn giáo.","audioKind":"ex2"}],"collocations":[{"en":"sacred site","vi":"thánh địa"},{"en":"sacred music","vi":"nhạc thánh; âm nhạc tôn giáo"},{"en":"hold something sacred","vi":"coi trọng điều gì là thiêng liêng"}],"wordFamily":["sacredness (n.)"],"synonyms":["holy"],"antonyms":[],"tipVi":"sacred có thể chỉ tính thiêng liêng tôn giáo hoặc sự tôn kính tối cao, bất khả xâm phạm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tease', 'en-b2-14', 'tease', '/tiːz/', 'B2', 'trêu chọc; chế nhạo; người hay trêu ghẹo người khác', 'v.', 'teasing (n.), teasingly (adv.)', 'Đồng nghĩa: make fun of, mock', 'Thường dùng cấu trúc tease sb about sth; có thể mang nghĩa thân mật hoặc ác ý.', 'My cousins always tease me about my enormous backpack.', NULL, 'Họ hàng của tôi luôn trêu chọc tôi về chiếc ba lô quá khổ của mình.', '{"wordId":"tease","ukIpa":"/tiːz/","usIpa":"/tiːz/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"Make jokes about someone, playfully or unkindly.","vi":"trêu chọc; chế nhạo"},{"pos":"n.","en":"Someone who enjoys making jokes about other people.","vi":"người hay trêu ghẹo người khác"}],"examples":[{"en":"My cousins always tease me about my enormous backpack.","vi":"Họ hàng của tôi luôn trêu chọc tôi về chiếc ba lô quá khổ của mình.","audioKind":"ex"},{"en":"Schools should teach children that teasing classmates about their appearance can seriously damage their confidence.","vi":"Nhà trường nên giáo dục trẻ em rằng việc trêu chọc ngoại hình của bạn học có thể làm tổn hại nghiêm trọng đến sự tự tin của các em.","audioKind":"ex2"}],"collocations":[{"en":"tease someone about something","vi":"trêu chọc ai về điều gì"},{"en":"gently tease","vi":"trêu nhẹ nhàng"},{"en":"tease out","vi":"gợi ra; gỡ rối"}],"wordFamily":["teasing (n.)","teasingly (adv.)"],"synonyms":["make fun of","mock"],"antonyms":[],"tipVi":"Thường dùng cấu trúc tease sb about sth; có thể mang nghĩa thân mật hoặc ác ý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wicked', 'en-b2-14', 'wicked', '/ˈwɪkɪd/', 'B2', 'xấu xa; độc ác; tinh nghịch; láu lỉnh', 'adj.', 'wickedly (adv.), wickedness (n.)', 'Đồng nghĩa: evil, immoral, mischievous · Trái nghĩa: good, virtuous', 'Thường có lực mạnh hơn "bad"; khi mô tả nụ cười, từ này có thể chỉ sự tinh nghịch thay vì tàn ác.', 'The wicked queen locked every garden gate in the kingdom.', NULL, 'Mụ hoàng hậu độc ác đã khóa chặt từng chiếc cổng vườn trong vương quốc.', '{"wordId":"wicked","ukIpa":"/ˈwɪkɪd/","usIpa":"/ˈwɪkɪd/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Morally very bad and deliberately harmful.","vi":"xấu xa; độc ác"},{"pos":"adj.","en":"Playfully naughty, often in an amusing way.","vi":"tinh nghịch; láu lỉnh"}],"examples":[{"en":"The wicked queen locked every garden gate in the kingdom.","vi":"Mụ hoàng hậu độc ác đã khóa chặt từng chiếc cổng vườn trong vương quốc.","audioKind":"ex"},{"en":"Traditional stories often contrast wicked characters with kind heroes to help children understand the consequences of moral choices.","vi":"Các câu chuyện truyền thống thường đối lập các nhân vật phản diện độc ác với các anh hùng tốt bụng nhằm giúp trẻ em hiểu rõ hậu quả của những lựa chọn đạo đức.","audioKind":"ex2"}],"collocations":[{"en":"a wicked act","vi":"hành vi đồi bại"},{"en":"a wicked grin","vi":"nụ cười tinh nghịch"},{"en":"a wicked sense of humour","vi":"khiếu hài hước tinh quái"}],"wordFamily":["wickedly (adv.)","wickedness (n.)"],"synonyms":["evil","immoral","mischievous"],"antonyms":["good","virtuous"],"tipVi":"Thường có lực mạnh hơn \"bad\"; khi mô tả nụ cười, từ này có thể chỉ sự tinh nghịch thay vì tàn ác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_insult', 'en-b2-14', 'insult', '/ɪnˈsʌlt/', 'B2', 'lăng mạ; xúc phạm; lời lăng mạ; sự xúc phạm', 'v.', 'insulting (adj.), insulted (adj.)', 'Đồng nghĩa: offend · Trái nghĩa: compliment', 'Động từ nhấn trọng âm ở âm tiết sau; danh từ phát âm là /ˈɪnsʌlt/ với trọng âm rơi vào âm tiết đầu.', 'I never meant to insult you with that joke.', NULL, 'Tôi hoàn toàn không có ý định xúc phạm bạn bằng câu nói đùa đó.', '{"wordId":"insult","ukIpa":"/ɪnˈsʌlt/","usIpa":"/ɪnˈsʌlt/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"Say or do something that treats someone with disrespect.","vi":"lăng mạ; xúc phạm"},{"pos":"n.","en":"A remark or action that shows disrespect and causes offence.","vi":"lời lăng mạ; sự xúc phạm"}],"examples":[{"en":"I never meant to insult you with that joke.","vi":"Tôi hoàn toàn không có ý định xúc phạm bạn bằng câu nói đùa đó.","audioKind":"ex"},{"en":"Public debates become less productive when participants insult their opponents instead of addressing the issues.","vi":"Các cuộc tranh luận công khai sẽ kém hiệu quả hơn khi người tham gia xúc phạm đối thủ thay vì tập trung giải quyết vấn đề.","audioKind":"ex2"}],"collocations":[{"en":"a personal insult","vi":"sự xúc phạm cá nhân"},{"en":"feel insulted","vi":"cảm thấy bị xúc phạm"},{"en":"add insult to injury","vi":"thêm dầu vào lửa"}],"wordFamily":["insulting (adj.)","insulted (adj.)"],"synonyms":["offend"],"antonyms":["compliment"],"tipVi":"Động từ nhấn trọng âm ở âm tiết sau; danh từ phát âm là /ˈɪnsʌlt/ với trọng âm rơi vào âm tiết đầu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_assistance', 'en-b2-14', 'assistance', '/əˈsɪstəns/', 'B2', 'sự trợ giúp; sự hỗ trợ', 'n.', 'assist (v.), assistant (n.)', 'Đồng nghĩa: help, support, aid', 'Là danh từ không đếm được; dùng để chỉ sự giúp đỡ mang tính trang trọng hơn từ help.', 'Please ask for assistance if your suitcase is too heavy.', NULL, 'Xin vui lòng yêu cầu trợ giúp nếu vali của bạn quá nặng.', '{"wordId":"assistance","ukIpa":"/əˈsɪstəns/","usIpa":"/əˈsɪstəns/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"Help given to someone who needs it.","vi":"sự trợ giúp; sự hỗ trợ"}],"examples":[{"en":"Please ask for assistance if your suitcase is too heavy.","vi":"Xin vui lòng yêu cầu trợ giúp nếu vali của bạn quá nặng.","audioKind":"ex"},{"en":"Financial assistance can enable students from disadvantaged backgrounds to complete their university education.","vi":"Sự hỗ trợ tài chính có thể giúp những sinh viên có hoàn cảnh khó khăn hoàn thành chương trình đại học.","audioKind":"ex2"}],"collocations":[{"en":"provide assistance","vi":"cung cấp hỗ trợ"},{"en":"financial assistance","vi":"hỗ trợ tài chính"},{"en":"seek assistance","vi":"tìm kiếm sự giúp đỡ"},{"en":"with the assistance of","vi":"với sự hỗ trợ của"}],"wordFamily":["assist (v.)","assistant (n.)"],"synonyms":["help","support","aid"],"antonyms":[],"tipVi":"Là danh từ không đếm được; dùng để chỉ sự giúp đỡ mang tính trang trọng hơn từ help.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rank', 'en-b2-14', 'rank', '/ræŋk/', 'B2', 'cấp bậc; quân hàm; địa vị; xếp hạng; phân loại; hàng; dãy', 'n.', 'ranking (n.), ranked (adj.)', NULL, 'rank có thể đóng vai trò danh từ hoặc động từ; ranking thường chỉ thứ hạng hoặc bảng xếp hạng.', 'After years of service, she reached the rank of captain.', NULL, 'Sau nhiều năm phục vụ, cô ấy đã đạt đến cấp bậc đại úy.', '{"wordId":"rank","ukIpa":"/ræŋk/","usIpa":"/ræŋk/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"A position within an ordered system of importance or authority","vi":"cấp bậc; quân hàm; địa vị"},{"pos":"v.","en":"To place or be placed in order of quality or importance","vi":"xếp hạng; phân loại"},{"pos":"n.","en":"A line of people or things arranged side by side","vi":"hàng; dãy"}],"examples":[{"en":"After years of service, she reached the rank of captain.","vi":"Sau nhiều năm phục vụ, cô ấy đã đạt đến cấp bậc đại úy.","audioKind":"ex"},{"en":"International surveys often rank cities according to housing affordability, public transport, and the quality of healthcare.","vi":"Các cuộc khảo sát quốc tế thường xếp hạng các thành phố theo khả năng chi trả nhà ở, giao thông công cộng và chất lượng chăm sóc sức khỏe.","audioKind":"ex2"}],"collocations":[{"en":"hold the rank of","vi":"mang quân hàm"},{"en":"rank among the best","vi":"lọt vào top xuất sắc nhất"},{"en":"rank highly","vi":"xếp hạng cao"},{"en":"in order of rank","vi":"theo thứ tự cấp bậc"}],"wordFamily":["ranking (n.)","ranked (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"rank có thể đóng vai trò danh từ hoặc động từ; ranking thường chỉ thứ hạng hoặc bảng xếp hạng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fraud', 'en-b2-14', 'fraud', '/frɔːd/', 'B2', 'hành vi gian lận; nạn lừa đảo; kẻ lừa đảo; đồ giả', 'n.', 'fraudulent (adj.), fraudulently (adv.), fraudster (n.)', 'Đồng nghĩa: deception', 'Hành vi gian lận thường là danh từ không đếm được; khi chỉ kẻ lừa đảo thì dùng a fraud.', 'The bank called after spotting possible fraud on my account.', NULL, 'Ngân hàng đã gọi điện sau khi phát hiện hành vi gian lận có thể xảy ra trong tài khoản của tôi.', '{"wordId":"fraud","ukIpa":"/frɔːd/","usIpa":"/frɔːd/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"Dishonest behaviour intended to gain money or another advantage.","vi":"hành vi gian lận; nạn lừa đảo"},{"pos":"n.","en":"A person or thing pretending to be genuine.","vi":"kẻ lừa đảo; đồ giả"}],"examples":[{"en":"The bank called after spotting possible fraud on my account.","vi":"Ngân hàng đã gọi điện sau khi phát hiện hành vi gian lận có thể xảy ra trong tài khoản của tôi.","audioKind":"ex"},{"en":"Stronger consumer protection laws can help prevent online fraud and increase public confidence in digital payments.","vi":"Các điều luật bảo vệ người tiêu dùng chặt chẽ hơn có thể giúp ngăn ngừa lừa đảo trực tuyến và gia tăng niềm tin của công chúng vào thanh toán kỹ thuật số.","audioKind":"ex2"}],"collocations":[{"en":"commit fraud","vi":"phạm tội gian lận"},{"en":"identity fraud","vi":"lừa đảo giả mạo danh tính"},{"en":"insurance fraud","vi":"gian lận bảo hiểm"},{"en":"a complete fraud","vi":"một kẻ lừa đảo đích thực"}],"wordFamily":["fraudulent (adj.)","fraudulently (adv.)","fraudster (n.)"],"synonyms":["deception"],"antonyms":[],"tipVi":"Hành vi gian lận thường là danh từ không đếm được; khi chỉ kẻ lừa đảo thì dùng a fraud.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_circumstance', 'en-b2-14', 'circumstance', '/ˈsɝːkəmstæns/', 'B2', 'hoàn cảnh; điều kiện; trường hợp; hoàn cảnh sống; điều kiện kinh tế', 'n.', 'circumstantial (adj.)', 'Đồng nghĩa: condition, situation', 'Thường dùng ở dạng số nhiều; khi "under no circumstances" đứng ở đầu câu thì phải đảo ngữ.', 'Under no circumstances should you leave the front door unlocked.', NULL, 'Dù ở bất kỳ hoàn cảnh nào, bạn cũng không được để cửa trước không khóa.', '{"wordId":"circumstance","ukIpa":"/ˈsɜːkəmstəns/","usIpa":"/ˈsɝːkəmstæns/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"a fact or condition that affects a situation","vi":"hoàn cảnh; điều kiện; trường hợp"},{"pos":"n.","en":"the conditions of someone''s life, especially their financial situation","vi":"hoàn cảnh sống; điều kiện kinh tế"}],"examples":[{"en":"Under no circumstances should you leave the front door unlocked.","vi":"Dù ở bất kỳ hoàn cảnh nào, bạn cũng không được để cửa trước không khóa.","audioKind":"ex"},{"en":"Schools should consider each student''s personal circumstances when developing policies on attendance and access to learning resources.","vi":"Nhà trường nên xem xét hoàn cảnh cá nhân của từng học sinh khi xây dựng các quy định về chuyên cần và quyền tiếp cận nguồn học liệu.","audioKind":"ex2"}],"collocations":[{"en":"under the circumstances","vi":"trong hoàn cảnh đó"},{"en":"personal circumstances","vi":"hoàn cảnh cá nhân"},{"en":"unforeseen circumstances","vi":"tình huống phát sinh bất ngờ"},{"en":"under no circumstances","vi":"tuyệt đối không"}],"wordFamily":["circumstantial (adj.)"],"synonyms":["condition","situation"],"antonyms":[],"tipVi":"Thường dùng ở dạng số nhiều; khi \"under no circumstances\" đứng ở đầu câu thì phải đảo ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_willingly', 'en-b2-14', 'willingly', '/ˈwɪlɪŋli/', 'B2', 'tự nguyện; sẵn sàng; một cách vui vẻ', 'adv.', 'willing (adj.), willingness (n.), unwilling (adj.), unwillingly (adv.)', 'Đồng nghĩa: readily, voluntarily · Trái nghĩa: unwillingly, reluctantly', 'Nhấn mạnh tính tự nguyện thay vì bị ép buộc; không đồng nghĩa đơn thuần với từ "vui vẻ".', 'My neighbour willingly watered the plants while I was away.', NULL, 'Người hàng xóm đã vui vẻ giúp tôi tưới cây trong lúc tôi đi vắng.', '{"wordId":"willingly","ukIpa":"/ˈwɪlɪŋli/","usIpa":"/ˈwɪlɪŋli/","cefr":"B2","topic":"society","senses":[{"pos":"adv.","en":"By choice and without needing to be forced or persuaded.","vi":"tự nguyện; sẵn sàng; một cách vui vẻ"}],"examples":[{"en":"My neighbour willingly watered the plants while I was away.","vi":"Người hàng xóm đã vui vẻ giúp tôi tưới cây trong lúc tôi đi vắng.","audioKind":"ex"},{"en":"Residents are more likely to participate willingly in recycling schemes when collection services are convenient and reliable.","vi":"Cư dân có xu hướng tự nguyện tham gia vào các chương trình tái chế hơn khi các dịch vụ thu gom thuận tiện và đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"willingly agree","vi":"vui vẻ đồng ý"},{"en":"participate willingly","vi":"tự nguyện tham gia"},{"en":"willingly accept","vi":"sẵn lòng chấp nhận"}],"wordFamily":["willing (adj.)","willingness (n.)","unwilling (adj.)","unwillingly (adv.)"],"synonyms":["readily","voluntarily"],"antonyms":["unwillingly","reluctantly"],"tipVi":"Nhấn mạnh tính tự nguyện thay vì bị ép buộc; không đồng nghĩa đơn thuần với từ \"vui vẻ\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_increasingly', 'en-b2-14', 'increasingly', '/ɪnˈkriːsɪŋli/', 'B2', 'ngày càng; càng lúc càng', 'adv.', 'increase (v.), increase (n.), increasing (adj.)', 'Đồng nghĩa: progressively · Trái nghĩa: decreasingly', 'Có thể trực tiếp bổ nghĩa cho tính từ ở dạng nguyên cấp, ví dụ: "increasingly popular".', 'The bus has become increasingly crowded since last month.', NULL, 'Tuyến xe buýt này đã trở nên đông đúc hơn kể từ tháng trước.', '{"wordId":"increasingly","ukIpa":"/ɪnˈkriːsɪŋli/","usIpa":"/ɪnˈkriːsɪŋli/","cefr":"B2","topic":"society","senses":[{"pos":"adv.","en":"More and more as time passes","vi":"ngày càng; càng lúc càng"}],"examples":[{"en":"The bus has become increasingly crowded since last month.","vi":"Tuyến xe buýt này đã trở nên đông đúc hơn kể từ tháng trước.","audioKind":"ex"},{"en":"As cities expand, governments are increasingly investing in public transport to reduce congestion and improve air quality.","vi":"Khi các thành phố mở rộng, chính phủ ngày càng đầu tư nhiều hơn vào giao thông công cộng nhằm giảm thiểu tình trạng ùn tắc và cải thiện chất lượng không khí.","audioKind":"ex2"}],"collocations":[{"en":"increasingly important","vi":"ngày càng quan trọng"},{"en":"increasingly common","vi":"ngày càng phổ biến"},{"en":"increasingly concerned","vi":"ngày càng lo lắng"},{"en":"increasingly difficult","vi":"ngày càng khó khăn"}],"wordFamily":["increase (v.)","increase (n.)","increasing (adj.)"],"synonyms":["progressively"],"antonyms":["decreasingly"],"tipVi":"Có thể trực tiếp bổ nghĩa cho tính từ ở dạng nguyên cấp, ví dụ: \"increasingly popular\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hell', 'en-b2-14', 'hell', '/hel/', 'B2', 'địa ngục; hoàn cảnh cực khổ; chốn khổ ải', 'n.', 'hellish (adj.)', 'Trái nghĩa: heaven', 'Nghĩa ẩn dụ có sắc thái mạnh; dùng làm từ chửi thề hoặc nhấn mạnh có thể gây xúc phạm người khác.', 'The old painting showed flames rising from hell.', NULL, 'Bức tranh cũ vẽ những ngọn lửa bốc lên từ địa ngục.', '{"wordId":"hell","ukIpa":"/hel/","usIpa":"/hel/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"A place of punishment after death in some religious beliefs.","vi":"địa ngục"},{"pos":"n.","en":"An extremely unpleasant experience, situation, or place.","vi":"hoàn cảnh cực khổ; chốn khổ ải"}],"examples":[{"en":"The old painting showed flames rising from hell.","vi":"Bức tranh cũ vẽ những ngọn lửa bốc lên từ địa ngục.","audioKind":"ex"},{"en":"For residents exposed to constant construction noise, daily life can become hell unless effective regulations are enforced.","vi":"Đối với cư dân phải chịu đựng tiếng ồn xây dựng liên tục, cuộc sống hàng ngày có thể trở thành địa ngục trừ khi các quy định hiệu quả được thực thi.","audioKind":"ex2"}],"collocations":[{"en":"go through hell","vi":"trải qua muôn vàn cay đắng"},{"en":"make someone''s life hell","vi":"biến cuộc đời ai đó thành chuỗi ngày khổ ải"},{"en":"a living hell","vi":"chốn địa ngục trần gian"}],"wordFamily":["hellish (adj.)"],"synonyms":[],"antonyms":["heaven"],"tipVi":"Nghĩa ẩn dụ có sắc thái mạnh; dùng làm từ chửi thề hoặc nhấn mạnh có thể gây xúc phạm người khác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_diversity', 'en-b2-14', 'diversity', '/daɪˈvɜːrsəti/', 'B2', 'tính đa dạng; sự phong phú', 'n.', 'diverse (adj.), diversify (v.), diversification (n.)', 'Đồng nghĩa: variety · Trái nghĩa: uniformity', 'Thường là danh từ không đếm được; cụm từ a diversity of dùng để chỉ nhiều loại khác nhau.', 'Our garden attracts a surprising diversity of colourful birds.', NULL, 'Khu vườn của chúng tôi thu hút một lượng lớn các loài chim đầy màu sắc đến ngạc nhiên.', '{"wordId":"diversity","ukIpa":"/daɪˈvɜːsəti/","usIpa":"/daɪˈvɜːrsəti/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"The presence of many different types of people or things.","vi":"tính đa dạng; sự phong phú"}],"examples":[{"en":"Our garden attracts a surprising diversity of colourful birds.","vi":"Khu vườn của chúng tôi thu hút một lượng lớn các loài chim đầy màu sắc đến ngạc nhiên.","audioKind":"ex"},{"en":"Cultural diversity can enrich urban life by introducing residents to different traditions, languages, and perspectives.","vi":"Tính đa dạng văn hóa có thể làm phong phú đời sống đô thị bằng cách giúp cư dân tiếp cận với các truyền thống, ngôn ngữ và góc nhìn khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"cultural diversity","vi":"sự đa dạng văn hóa"},{"en":"biological diversity","vi":"đa dạng sinh học"},{"en":"promote diversity","vi":"thúc đẩy tính đa dạng"}],"wordFamily":["diverse (adj.)","diversify (v.)","diversification (n.)"],"synonyms":["variety"],"antonyms":["uniformity"],"tipVi":"Thường là danh từ không đếm được; cụm từ a diversity of dùng để chỉ nhiều loại khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_idol', 'en-b2-14', 'idol', '/ˈaɪdəl/', 'B2', 'thần tượng; người được ngưỡng mộ và noi theo; tượng thần', 'n.', 'idolise (v.), idolisation (n.)', NULL, '"Idol" là thần tượng; còn "idle" là rảnh rỗi, hai từ này có cách phát âm giống nhau.', 'Lina finally met her sporting idol after the match.', NULL, 'Lina cuối cùng đã được gặp thần tượng thể thao của mình sau trận đấu.', '{"wordId":"idol","ukIpa":"/ˈaɪdəl/","usIpa":"/ˈaɪdəl/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"someone greatly admired and often imitated","vi":"thần tượng; người được ngưỡng mộ và noi theo"},{"pos":"n.","en":"an image or object worshipped as a god","vi":"tượng thần"}],"examples":[{"en":"Lina finally met her sporting idol after the match.","vi":"Lina cuối cùng đã được gặp thần tượng thể thao của mình sau trận đấu.","audioKind":"ex"},{"en":"Young people may adopt unhealthy habits when their idols promote unrealistic standards of physical appearance.","vi":"Giới trẻ có thể tiếp thu những thói quen không lành mạnh khi thần tượng của họ cổ súy cho những tiêu chuẩn ngoại hình phi thực tế.","audioKind":"ex2"}],"collocations":[{"en":"a sporting idol","vi":"một thần tượng thể thao"},{"en":"a pop idol","vi":"thần tượng nhạc pop"},{"en":"worship an idol","vi":"thờ phụng thần tượng"}],"wordFamily":["idolise (v.)","idolisation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"\"Idol\" là thần tượng; còn \"idle\" là rảnh rỗi, hai từ này có cách phát âm giống nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dependent', 'en-b2-14', 'dependent', '/dɪˈpendənt/', 'B2', 'phụ thuộc; lệ thuộc; tùy thuộc vào', 'adj.', 'depend (v.), dependence (n.), dependency (n.), independent (adj.)', 'Đồng nghĩa: reliant · Trái nghĩa: independent', 'Thường đi với giới từ on; trong tiếng Anh Anh, danh từ chỉ "người lệ thuộc/sống phụ thuộc" thường được viết là dependant.', 'The young birds are still dependent on their parents.', NULL, 'Những chú chim non vẫn còn phải phụ thuộc vào chim bố mẹ.', '{"wordId":"dependent","ukIpa":"/dɪˈpendənt/","usIpa":"/dɪˈpendənt/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Needing someone or something for support or survival.","vi":"phụ thuộc; lệ thuộc"},{"pos":"adj.","en":"Decided or affected by a particular condition or factor.","vi":"tùy thuộc vào"}],"examples":[{"en":"The young birds are still dependent on their parents.","vi":"Những chú chim non vẫn còn phải phụ thuộc vào chim bố mẹ.","audioKind":"ex"},{"en":"Rural communities are often dependent on reliable bus services for access to healthcare, employment, and further education.","vi":"Các cộng đồng nông thôn thường phụ thuộc vào các dịch vụ xe buýt đáng tin cậy để tiếp cận chăm sóc y tế, việc làm và giáo dục bậc cao.","audioKind":"ex2"}],"collocations":[{"en":"dependent on","vi":"phụ thuộc vào"},{"en":"financially dependent","vi":"phụ thuộc tài chính"},{"en":"heavily dependent on","vi":"phụ thuộc nặng nề vào"},{"en":"dependent children","vi":"con cái phụ thuộc (vào cha mẹ)"}],"wordFamily":["depend (v.)","dependence (n.)","dependency (n.)","independent (adj.)"],"synonyms":["reliant"],"antonyms":["independent"],"tipVi":"Thường đi với giới từ on; trong tiếng Anh Anh, danh từ chỉ \"người lệ thuộc/sống phụ thuộc\" thường được viết là dependant.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_persuasion', 'en-b2-14', 'persuasion', '/pɚˈsweɪʒən/', 'B2', 'sự thuyết phục; sự khuyên bảo; niềm tin; khuynh hướng (tôn giáo, chính trị)', 'n.', 'persuade (v.), persuasive (adj.), persuasively (adv.)', NULL, 'Khi mang nghĩa là sự thuyết phục, danh từ này thường không đếm được; động từ tương ứng là "persuade".', 'After some persuasion, my brother joined our evening walk.', NULL, 'Sau một hồi thuyết phục, em trai tôi đã tham gia đi dạo buổi tối cùng chúng tôi.', '{"wordId":"persuasion","ukIpa":"/pəˈsweɪʒən/","usIpa":"/pɚˈsweɪʒən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"The process of getting someone to agree or do something.","vi":"sự thuyết phục; sự khuyên bảo"},{"pos":"n.","en":"A particular religious or political belief or group.","vi":"niềm tin; khuynh hướng (tôn giáo, chính trị)"}],"examples":[{"en":"After some persuasion, my brother joined our evening walk.","vi":"Sau một hồi thuyết phục, em trai tôi đã tham gia đi dạo buổi tối cùng chúng tôi.","audioKind":"ex"},{"en":"Public health campaigns often rely on persuasion rather than legal restrictions to encourage healthier habits.","vi":"Các chiến dịch y tế công cộng thường dựa vào sự thuyết phục thay vì các biện pháp hạn chế pháp lý để khuyến khích những thói quen lành mạnh hơn.","audioKind":"ex2"}],"collocations":[{"en":"powers of persuasion","vi":"khả năng thuyết phục"},{"en":"gentle persuasion","vi":"sự thuyết phục nhẹ nhàng"},{"en":"political persuasion","vi":"khuynh hướng chính trị"}],"wordFamily":["persuade (v.)","persuasive (adj.)","persuasively (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi mang nghĩa là sự thuyết phục, danh từ này thường không đếm được; động từ tương ứng là \"persuade\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_impact', 'en-b2-14', 'impact', '/ˈɪmpækt/', 'B2', 'tác động; ảnh hưởng lớn; sự va chạm; lực tác động; tác động đến; ảnh hưởng sâu sắc', 'n.', 'impactful (adj.)', 'Đồng nghĩa: effect, influence', 'Danh từ trọng âm ở âm tiết đầu; động từ thường phát âm là /ɪmˈpækt/.', 'The new playground had a positive impact on our neighbourhood.', NULL, 'Khu vui chơi mới đã mang lại tác động tích cực cho khu1 xóm của chúng ta.', '{"wordId":"impact","ukIpa":"/ˈɪmpækt/","usIpa":"/ˈɪmpækt/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"a strong effect on someone or something","vi":"tác động; ảnh hưởng lớn"},{"pos":"n.","en":"the force or action of one object hitting another","vi":"sự va chạm; lực tác động"},{"pos":"v.","en":"to affect someone or something, often strongly","vi":"tác động đến; ảnh hưởng sâu sắc"}],"examples":[{"en":"The new playground had a positive impact on our neighbourhood.","vi":"Khu vui chơi mới đã mang lại tác động tích cực cho khu1 xóm của chúng ta.","audioKind":"ex"},{"en":"Governments should assess the environmental impact of major construction projects before allowing work to begin.","vi":"Các chính phủ nên đánh giá tác động môi trường của các dự án xây dựng lớn trước khi cho phép khởi công.","audioKind":"ex2"}],"collocations":[{"en":"have an impact on","vi":"có tác động đến"},{"en":"environmental impact","vi":"tác động môi trường"},{"en":"on impact","vi":"khi va chạm"},{"en":"impact on communities","vi":"tác động đến cộng đồng"}],"wordFamily":["impactful (adj.)"],"synonyms":["effect","influence"],"antonyms":[],"tipVi":"Danh từ trọng âm ở âm tiết đầu; động từ thường phát âm là /ɪmˈpækt/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_whoever', 'en-b2-14', 'whoever', '/huːˈevər/', 'B2', 'bất cứ ai; bất kỳ người nào mà; ai mà (dùng trong câu hỏi để diễn tả sự ngạc nhiên về danh tính)', 'pron.', 'who (pron.)', NULL, 'Có thể mở đầu mệnh đề danh từ hoặc mệnh đề nhượng bộ; không phải lúc nào cũng thay thế được bằng no matter who.', 'Whoever finishes first can choose the next game.', NULL, 'Ai hoàn thành trước có thể chọn trò chơi tiếp theo.', '{"wordId":"whoever","ukIpa":"/huːˈevə/","usIpa":"/huːˈevər/","cefr":"B2","topic":"society","senses":[{"pos":"pron.","en":"any person who, or no matter which person","vi":"bất cứ ai; bất kỳ người nào mà"},{"pos":"pron.","en":"used in questions to express surprise about someone''s identity","vi":"ai mà (dùng trong câu hỏi để diễn tả sự ngạc nhiên về danh tính)"}],"examples":[{"en":"Whoever finishes first can choose the next game.","vi":"Ai hoàn thành trước có thể chọn trò chơi tiếp theo.","audioKind":"ex"},{"en":"Public libraries should welcome whoever needs access to reliable information, regardless of their income or educational background.","vi":"Các thư viện công cộng nên chào đón bất kỳ ai cần tiếp cận thông tin đáng tin cậy, không phân biệt thu nhập hay nền tảng học vấn của họ.","audioKind":"ex2"}],"collocations":[{"en":"whoever you are","vi":"dù bạn là ai"},{"en":"whoever wants to","vi":"bất cứ ai muốn"},{"en":"whoever is responsible","vi":"bất kỳ ai phải chịu trách nhiệm"}],"wordFamily":["who (pron.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể mở đầu mệnh đề danh từ hoặc mệnh đề nhượng bộ; không phải lúc nào cũng thay thế được bằng no matter who.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prejudice', 'en-b2-14', 'prejudice', '/ˈpredʒədɪs/', 'B2', 'cố kiến; thành kiến; định kiến; gây định kiến; làm tổn hại', 'n.', 'prejudiced (adj.)', 'Đồng nghĩa: bias', 'Khi nói về thành kiến chống lại một nhóm người nào đó, thường dùng prejudice against.', 'Her neighbours welcomed her warmly, without any prejudice.', NULL, 'Những người hàng xóm đã chào đón cô ấy nồng nhiệt, không chút thành kiến.', '{"wordId":"prejudice","ukIpa":"/ˈpredʒədɪs/","usIpa":"/ˈpredʒədɪs/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"An unfair opinion formed without enough knowledge or experience.","vi":"cố kiến; thành kiến; định kiến"},{"pos":"v.","en":"To unfairly influence someone''s judgement or harm their chances.","vi":"gây định kiến; làm tổn hại"}],"examples":[{"en":"Her neighbours welcomed her warmly, without any prejudice.","vi":"Những người hàng xóm đã chào đón cô ấy nồng nhiệt, không chút thành kiến.","audioKind":"ex"},{"en":"Schools can challenge prejudice by encouraging students to learn about cultures different from their own.","vi":"Nhà trường có thể xóa bỏ định kiến bằng cách khuyến khích học sinh tìm hiểu về các nền văn hóa khác biệt với văn hóa của chính mình.","audioKind":"ex2"}],"collocations":[{"en":"racial prejudice","vi":"định kiến chủng tộc"},{"en":"prejudice against","vi":"thành kiến đối với"},{"en":"challenge prejudice","vi":"thách thức định kiến"},{"en":"prejudice someone''s chances","vi":"làm tổn hại cơ hội của ai đó"}],"wordFamily":["prejudiced (adj.)"],"synonyms":["bias"],"antonyms":[],"tipVi":"Khi nói về thành kiến chống lại một nhóm người nào đó, thường dùng prejudice against.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disgraceful', 'en-b2-14', 'disgraceful', '/dɪsˈɡreɪsfəl/', 'B2', 'đáng xấu hổ; tồi tệ', 'adj.', 'disgrace (n.), disgrace (v.), disgracefully (adv.)', 'Đồng nghĩa: shameful, outrageous · Trái nghĩa: admirable', 'Dùng để thể hiện sự lên án mạnh mẽ; từ "nghèo nàn/mất mặt về danh dự" thường dùng "disgraced".', 'Leaving rubbish all over this beautiful park is disgraceful.', NULL, 'Vứt rác bừa bãi khắp công viên xinh đẹp này là hành động rất đáng xấu hổ.', '{"wordId":"disgraceful","ukIpa":"/dɪsˈɡreɪsfəl/","usIpa":"/dɪsˈɡreɪsfəl/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"So bad or unacceptable that it deserves strong disapproval.","vi":"đáng xấu hổ; tồi tệ"}],"examples":[{"en":"Leaving rubbish all over this beautiful park is disgraceful.","vi":"Vứt rác bừa bãi khắp công viên xinh đẹp này là hành động rất đáng xấu hổ.","audioKind":"ex"},{"en":"The report exposed disgraceful working conditions and called for stronger protection of employees across the industry.","vi":"Báo cáo đã phơi bày điều kiện làm việc tồi tệ và kêu gọi tăng cường bảo vệ người lao động trong toàn ngành.","audioKind":"ex2"}],"collocations":[{"en":"disgraceful behaviour","vi":"hành vi đáng xấu hổ"},{"en":"disgraceful treatment","vi":"sự đối xử tồi tệ"},{"en":"absolutely disgraceful","vi":"hết sức tồi tệ"}],"wordFamily":["disgrace (n.)","disgrace (v.)","disgracefully (adv.)"],"synonyms":["shameful","outrageous"],"antonyms":["admirable"],"tipVi":"Dùng để thể hiện sự lên án mạnh mẽ; từ \"nghèo nàn/mất mặt về danh dự\" thường dùng \"disgraced\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_excessive', 'en-b2-14', 'excessive', '/ɪkˈsesɪv/', 'B2', 'quá mức; thái quá', 'adj.', 'excess (n.), excessively (adv.)', 'Đồng nghĩa: undue, inordinate · Trái nghĩa: moderate, reasonable', 'Mang nghĩa vượt quá giới hạn hợp lý, không đồng nghĩa với "extra" (thêm vào).', 'The excessive heat made our afternoon walk uncomfortable.', NULL, 'Cái nóng gay gắt khiến buổi đi dạo chiều của chúng tôi trở nên thật khó chịu.', '{"wordId":"excessive","ukIpa":"/ɪkˈsesɪv/","usIpa":"/ɪkˈsesɪv/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Greater than is necessary, reasonable, or acceptable.","vi":"quá mức; thái quá"}],"examples":[{"en":"The excessive heat made our afternoon walk uncomfortable.","vi":"Cái nóng gay gắt khiến buổi đi dạo chiều của chúng tôi trở nên thật khó chịu.","audioKind":"ex"},{"en":"Excessive use of private cars contributes to urban air pollution and places pressure on existing roads.","vi":"Việc sử dụng xe cá nhân quá mức góp phần gây ô nhiễm không khí đô thị và tạo áp lực lên hệ thống đường sá hiện có.","audioKind":"ex2"}],"collocations":[{"en":"excessive consumption","vi":"tiêu dùng quá mức"},{"en":"excessive pressure","vi":"áp lực quá lớn"},{"en":"excessive noise","vi":"tiếng ồn quá mức"},{"en":"excessive use of","vi":"sử dụng quá mức"}],"wordFamily":["excess (n.)","excessively (adv.)"],"synonyms":["undue","inordinate"],"antonyms":["moderate","reasonable"],"tipVi":"Mang nghĩa vượt quá giới hạn hợp lý, không đồng nghĩa với \"extra\" (thêm vào).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deceive', 'en-b2-14', 'deceive', '/dɪˈsiːv/', 'B2', 'lừa dối; đánh lừa', 'v.', 'deception (n.), deceptive (adj.), deceit (n.), deceitful (adj.)', 'Đồng nghĩa: mislead, trick', 'Cấu trúc "deceive sb into doing sth" có nghĩa là lừa ai đó làm việc gì.', 'The seller deceived me about the bicycle''s condition.', NULL, 'Người bán đã lừa dối tôi về tình trạng của chiếc xe đạp.', '{"wordId":"deceive","ukIpa":"/dɪˈsiːv/","usIpa":"/dɪˈsiːv/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"to deliberately make someone believe something that is not true","vi":"lừa dối; đánh lừa"}],"examples":[{"en":"The seller deceived me about the bicycle''s condition.","vi":"Người bán đã lừa dối tôi về tình trạng của chiếc xe đạp.","audioKind":"ex"},{"en":"Misleading advertisements can deceive consumers into purchasing products that offer little benefit to their health.","vi":"Những quảng cáo gây hiểu lầm có thể đánh lừa người tiêu dùng mua những sản phẩm mang lại rất ít lợi ích cho sức khỏe của họ.","audioKind":"ex2"}],"collocations":[{"en":"deceive someone into doing something","vi":"lừa ai đó làm gì"},{"en":"deceive yourself","vi":"tự lừa dối bản thân"},{"en":"deliberately deceive","vi":"cố tình lừa dối"}],"wordFamily":["deception (n.)","deceptive (adj.)","deceit (n.)","deceitful (adj.)"],"synonyms":["mislead","trick"],"antonyms":[],"tipVi":"Cấu trúc \"deceive sb into doing sth\" có nghĩa là lừa ai đó làm việc gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conflict', 'en-b2-14', 'conflict', '/ˈkɑːnflɪkt/', 'B2', 'xung đột; tranh chấp; mâu thuẫn; sự trái ngược; trái ngược', 'n.', 'conflicting (adj.)', 'Đồng nghĩa: disagreement, clash · Trái nghĩa: harmony', 'Danh từ nhấn trọng âm ở âm tiết thứ nhất, động từ nhấn trọng âm ở âm tiết thứ hai.', 'Sharing a bedroom sometimes causes conflict between the brothers.', NULL, 'Việc dùng chung phòng ngủ đôi khi gây ra xung đột giữa hai anh em.', '{"wordId":"conflict","ukIpa":"/ˈkɒnflɪkt/","usIpa":"/ˈkɑːnflɪkt/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"A serious disagreement or struggle between people or groups.","vi":"xung đột; tranh chấp"},{"pos":"n.","en":"A situation where different needs or ideas cannot agree.","vi":"mâu thuẫn; sự trái ngược"},{"pos":"v.","en":"To disagree with or be incompatible with something.","vi":"xung đột; mâu thuẫn; trái ngược"}],"examples":[{"en":"Sharing a bedroom sometimes causes conflict between the brothers.","vi":"Việc dùng chung phòng ngủ đôi khi gây ra xung đột giữa hai anh em.","audioKind":"ex"},{"en":"Economic growth can conflict with environmental protection when industries rely heavily on fossil fuels.","vi":"Tăng trưởng kinh tế có thể mâu thuẫn với việc bảo vệ môi trường khi các ngành công nghiệp phụ thuộc quá nhiều vào nhiên liệu hóa thạch.","audioKind":"ex2"}],"collocations":[{"en":"resolve a conflict","vi":"giải quyết xung đột"},{"en":"conflict with","vi":"mâu thuẫn với"},{"en":"a conflict of interest","vi":"xung đột lợi ích"}],"wordFamily":["conflicting (adj.)"],"synonyms":["disagreement","clash"],"antonyms":["harmony"],"tipVi":"Danh từ nhấn trọng âm ở âm tiết thứ nhất, động từ nhấn trọng âm ở âm tiết thứ hai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cooperate', 'en-b2-14', 'cooperate', '/koʊˈɑːpəreɪt/', 'B2', 'hợp tác; cộng tác; phối hợp; hỗ trợ', 'v.', 'cooperation (n.), cooperative (adj.), cooperatively (adv.)', 'Đồng nghĩa: collaborate', 'Đây là nội động từ: hợp tác với ai dùng "with", hợp tác về việc gì dùng "on".', 'We cooperated with our neighbours to clean the shared garden.', NULL, 'Chúng tôi đã hợp tác với hàng xóm để dọn dẹp khu vườn chung.', '{"wordId":"cooperate","ukIpa":"/kəʊˈɒpəreɪt/","usIpa":"/koʊˈɑːpəreɪt/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"to work together to achieve a shared aim","vi":"hợp tác; cộng tác"},{"pos":"v.","en":"to help by doing what someone asks","vi":"phối hợp; hỗ trợ"}],"examples":[{"en":"We cooperated with our neighbours to clean the shared garden.","vi":"Chúng tôi đã hợp tác với hàng xóm để dọn dẹp khu vườn chung.","audioKind":"ex"},{"en":"Countries must cooperate on climate policy because pollution crosses borders and affects communities far from its source.","vi":"Các quốc gia phải hợp tác về chính sách khí hậu vì ô nhiễm vượt qua biên giới và ảnh hưởng đến các cộng đồng ở rất xa nguồn phát thải.","audioKind":"ex2"}],"collocations":[{"en":"cooperate with","vi":"hợp tác với"},{"en":"cooperate on a project","vi":"hợp tác trong một dự án"},{"en":"cooperate closely","vi":"hợp tác chặt chẽ"}],"wordFamily":["cooperation (n.)","cooperative (adj.)","cooperatively (adv.)"],"synonyms":["collaborate"],"antonyms":[],"tipVi":"Đây là nội động từ: hợp tác với ai dùng \"with\", hợp tác về việc gì dùng \"on\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gender', 'en-b2-14', 'gender', '/ˈdʒendər/', 'B2', 'giới tính (mang tính xã hội và văn hóa); giống (phân loại ngữ pháp của từ)', 'n.', 'gendered (adj.)', NULL, 'gender thường nhấn mạnh khía cạnh xã hội và văn hóa; sex thường nhấn mạnh khía cạnh sinh học.', 'The club welcomes everyone, regardless of age or gender.', NULL, 'Câu lạc bộ chào đón tất cả mọi người, không phân biệt độ tuổi hay giới tính.', '{"wordId":"gender","ukIpa":"/ˈdʒendə/","usIpa":"/ˈdʒendər/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"Being male, female, or another identity, especially socially and culturally.","vi":"giới tính (mang tính xã hội và văn hóa)"},{"pos":"n.","en":"A grammatical class of nouns affecting related word forms.","vi":"giống (phân loại ngữ pháp của từ)"}],"examples":[{"en":"The club welcomes everyone, regardless of age or gender.","vi":"Câu lạc bộ chào đón tất cả mọi người, không phân biệt độ tuổi hay giới tính.","audioKind":"ex"},{"en":"Policies promoting gender equality can improve access to education and expand employment opportunities across society.","vi":"Các chính sách thúc đẩy bình đẳng giới có thể cải thiện khả năng tiếp cận giáo dục và mở rộng cơ hội việc làm trên toàn xã hội.","audioKind":"ex2"}],"collocations":[{"en":"gender equality","vi":"bình đẳng giới"},{"en":"gender roles","vi":"vai trò giới"},{"en":"gender identity","vi":"bản dạng giới"},{"en":"gender gap","vi":"khoảng cách giới"}],"wordFamily":["gendered (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"gender thường nhấn mạnh khía cạnh xã hội và văn hóa; sex thường nhấn mạnh khía cạnh sinh học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_14_1', 'en-b2-14', 'Cách dùng “dependent” (adj.) — phụ thuộc; lệ thuộc', 'dependent on  ·  financially dependent  ·  heavily dependent on', 'Thường đi với giới từ on; trong tiếng Anh Anh, danh từ chỉ "người lệ thuộc/sống phụ thuộc" thường được viết là dependant.', 'Họ từ (Word Family): depend (v.), dependence (n.), dependency (n.), independent (adj.) | Đồng nghĩa: reliant · Trái nghĩa: independent', '[{"hanzi":"The young birds are still dependent on their parents.","pinyin":"","meaning":"Những chú chim non vẫn còn phải phụ thuộc vào chim bố mẹ."},{"hanzi":"Rural communities are often dependent on reliable bus services for access to healthcare, employment, and further education.","pinyin":"","meaning":"Các cộng đồng nông thôn thường phụ thuộc vào các dịch vụ xe buýt đáng tin cậy để tiếp cận chăm sóc y tế, việc làm và giáo dục bậc cao."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_14_2', 'en-b2-14', 'Cách dùng “whoever” (pron.) — bất cứ ai; bất kỳ người nào mà', 'whoever you are  ·  whoever wants to  ·  whoever is responsible', 'Có thể mở đầu mệnh đề danh từ hoặc mệnh đề nhượng bộ; không phải lúc nào cũng thay thế được bằng no matter who.', 'Họ từ (Word Family): who (pron.)', '[{"hanzi":"Whoever finishes first can choose the next game.","pinyin":"","meaning":"Ai hoàn thành trước có thể chọn trò chơi tiếp theo."},{"hanzi":"Public libraries should welcome whoever needs access to reliable information, regardless of their income or educational background.","pinyin":"","meaning":"Các thư viện công cộng nên chào đón bất kỳ ai cần tiếp cận thông tin đáng tin cậy, không phân biệt thu nhập hay nền tảng học vấn của họ."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_14_3', 'en-b2-14', 'Cách dùng “persuasion” (n.) — sự thuyết phục; sự khuyên bảo', 'powers of persuasion  ·  gentle persuasion  ·  political persuasion', 'Khi mang nghĩa là sự thuyết phục, danh từ này thường không đếm được; động từ tương ứng là "persuade".', 'Họ từ (Word Family): persuade (v.), persuasive (adj.), persuasively (adv.)', '[{"hanzi":"After some persuasion, my brother joined our evening walk.","pinyin":"","meaning":"Sau một hồi thuyết phục, em trai tôi đã tham gia đi dạo buổi tối cùng chúng tôi."},{"hanzi":"Public health campaigns often rely on persuasion rather than legal restrictions to encourage healthier habits.","pinyin":"","meaning":"Các chiến dịch y tế công cộng thường dựa vào sự thuyết phục thay vì các biện pháp hạn chế pháp lý để khuyến khích những thói quen lành mạnh hơn."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_14_4', 'en-b2-14', 'Cách dùng “insult” (v.) — lăng mạ; xúc phạm', 'a personal insult  ·  feel insulted  ·  add insult to injury', 'Động từ nhấn trọng âm ở âm tiết sau; danh từ phát âm là /ˈɪnsʌlt/ với trọng âm rơi vào âm tiết đầu.', 'Họ từ (Word Family): insulting (adj.), insulted (adj.) | Đồng nghĩa: offend · Trái nghĩa: compliment', '[{"hanzi":"I never meant to insult you with that joke.","pinyin":"","meaning":"Tôi hoàn toàn không có ý định xúc phạm bạn bằng câu nói đùa đó."},{"hanzi":"Public debates become less productive when participants insult their opponents instead of addressing the issues.","pinyin":"","meaning":"Các cuộc tranh luận công khai sẽ kém hiệu quả hơn khi người tham gia xúc phạm đối thủ thay vì tập trung giải quyết vấn đề."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_14_1', 'en-b2-14', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
