INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_14_1_4', 'ten_b2_14_1', 'tease', 'My cousins always tease me about my enormous backpack.', 'My cousins always tease me about my enormous backpack.', '/tiːz/', 'Họ hàng của tôi luôn trêu chọc tôi về chiếc ba lô quá khổ của mình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
