INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_14_1_7', 'ten_b2_14_1', 'assistance', 'Please ask for assistance if your suitcase is too heavy.', 'Please ask for assistance if your suitcase is too heavy.', '/əˈsɪstəns/', 'Xin vui lòng yêu cầu trợ giúp nếu vali của bạn quá nặng.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_14_1_8', 'ten_b2_14_1', 'rank', 'After years of service, she reached the rank of captain.', 'After years of service, she reached the rank of captain.', '/ræŋk/', 'Sau nhiều năm phục vụ, cô ấy đã đạt đến cấp bậc đại úy.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_14_1_1', 'en-b2-14', 'ten_b2_14_1', 'listening', 'listening', 'The teacher showed mercy and accepted my late homework.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô giáo đã tỏ lòng khoan dung và chấp nhận bài tập về nhà nộp muộn của tôi.","Vứt rác bừa bãi khắp công viên xinh đẹp này là hành động rất đáng xấu hổ.","Du khách phải cởi giày trước khi bước vào ngôi đền thiêng.","Người bán đã lừa dối tôi về tình trạng của chiếc xe đạp."]'::jsonb, 0, 'The teacher showed mercy and accepted my late homework. → Cô giáo đã tỏ lòng khoan dung và chấp nhận bài tập về nhà nộp muộn của tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_14_1_2', 'en-b2-14', 'ten_b2_14_1', 'listening', 'listening', 'My grandparents live in a quiet rural village.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Khu vườn của chúng tôi thu hút một lượng lớn các loài chim đầy màu sắc đến ngạc nhiên.","Bức tranh cũ vẽ những ngọn lửa bốc lên từ địa ngục.","Ông bà tôi sống trong một ngôi làng nông thôn yên bình.","Chúng tôi đã hợp tác với hàng xóm để dọn dẹp khu vườn chung."]'::jsonb, 2, 'My grandparents live in a quiet rural village. → Ông bà tôi sống trong một ngôi làng nông thôn yên bình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_14_1_3', 'en-b2-14', 'ten_b2_14_1', 'listening', 'listening', 'Visitors remove their shoes before entering the sacred temple.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã hợp tác với hàng xóm để dọn dẹp khu vườn chung.","Người bán đã lừa dối tôi về tình trạng của chiếc xe đạp.","Du khách phải cởi giày trước khi bước vào ngôi đền thiêng.","Xin vui lòng yêu cầu trợ giúp nếu vali của bạn quá nặng."]'::jsonb, 2, 'Visitors remove their shoes before entering the sacred temple. → Du khách phải cởi giày trước khi bước vào ngôi đền thiêng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_14_2', 'en-b2-14', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_14_2_1', 'ten_b2_14_2', 'mercy', 'A fair justice system should balance appropriate punishment with mercy towards people who genuinely seek to change.', 'A fair justice system should balance appropriate punishment with mercy towards people who genuinely seek to change.', '/ˈmɝːsi/', 'Một hệ thống tư pháp công bằng phải cân bằng giữa hình phạt thích đáng và sự khoan hồng đối với những người thực sự muốn hướng thiện.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_14_2_2', 'ten_b2_14_2', 'rural', 'Reliable internet access can improve educational opportunities for children living in remote rural areas.', 'Reliable internet access can improve educational opportunities for children living in remote rural areas.', '/ˈrʊrəl/', 'Khả năng truy cập internet ổn định có thể cải thiện cơ hội giáo dục cho trẻ em sống ở các vùng nông thôn hẻo lánh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_14_2_3', 'ten_b2_14_2', 'sacred', 'Tourism can support local economies, but visitors must respect sacred places and religious customs.', 'Tourism can support local economies, but visitors must respect sacred places and religious customs.', '/ˈseɪkrɪd/', 'Du lịch có thể hỗ trợ kinh tế địa phương, nhưng du khách phải tôn trọng các thánh địa và phong tục tôn giáo.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_14_2_4', 'ten_b2_14_2', 'tease', 'Schools should teach children that teasing classmates about their appearance can seriously damage their confidence.', 'Schools should teach children that teasing classmates about their appearance can seriously damage their confidence.', '/tiːz/', 'Nhà trường nên giáo dục trẻ em rằng việc trêu chọc ngoại hình của bạn học có thể làm tổn hại nghiêm trọng đến sự tự tin của các em.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_14_2_5', 'ten_b2_14_2', 'wicked', 'Traditional stories often contrast wicked characters with kind heroes to help children understand the consequences of moral choices.', 'Traditional stories often contrast wicked characters with kind heroes to help children understand the consequences of moral choices.', '/ˈwɪkɪd/', 'Các câu chuyện truyền thống thường đối lập các nhân vật phản diện độc ác với các anh hùng tốt bụng nhằm giúp trẻ em hiểu rõ hậu quả của những lựa chọn đạo đức.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_14_2_6', 'ten_b2_14_2', 'insult', 'Public debates become less productive when participants insult their opponents instead of addressing the issues.', 'Public debates become less productive when participants insult their opponents instead of addressing the issues.', '/ɪnˈsʌlt/', 'Các cuộc tranh luận công khai sẽ kém hiệu quả hơn khi người tham gia xúc phạm đối thủ thay vì tập trung giải quyết vấn đề.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_14_2_1', 'en-b2-14', 'ten_b2_14_2', 'listening', 'listening', 'A fair justice system should balance appropriate punishment with mercy towards people who genuinely seek to change.', NULL, 'Trong câu vừa nghe, từ “mercy” mang nghĩa nào sau đây?', '["vô lý; ngớ ngẩn; lố bịch","sự khoan dung; lòng trắc ẩn; sự nhân nhượng (không trừng phạt hoặc làm hại)","trụ sở chính; tổng hành dinh","bò đực đã bị thiến dùng để kéo cày, bò kéo, trâu bò lực lưỡng"]'::jsonb, 1, '“mercy” (/ˈmɝːsi/): sự khoan dung; lòng trắc ẩn; sự nhân nhượng (không trừng phạt hoặc làm hại). Câu đầy đủ: A fair justice system should balance appropriate punishment with mercy towards people who genuinely seek to change.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_14_2_2', 'en-b2-14', 'ten_b2_14_2', 'listening', 'listening', 'Reliable internet access can improve educational opportunities for children living in remote rural areas.', NULL, 'Trong câu vừa nghe, từ “rural” mang nghĩa nào sau đây?', '["đi nhờ xe; quá giang","thuộc nông thôn; thuộc vùng quê","hoạt động gây quỹ; quyên góp","khu nghỉ dưỡng; khu du lịch"]'::jsonb, 1, '“rural” (/ˈrʊrəl/): thuộc nông thôn; thuộc vùng quê. Câu đầy đủ: Reliable internet access can improve educational opportunities for children living in remote rural areas.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
