INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_14_1', 'en-b2-14', NULL, 'comprehensive_test', 'listening', 'mercy', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["hình dáng mặt nghiêng; biên dạng","sự khoan dung; lòng trắc ẩn; sự nhân nhượng (không trừng phạt hoặc làm hại)","trải qua; chịu đựng; tiếp nhận (quá trình, sự thay đổi hoặc điều trị)","mạnh mẽ; quyết liệt; triệt để; đáng kể"]'::jsonb, 1, 'mercy (/ˈmɝːsi/) → sự khoan dung; lòng trắc ẩn; sự nhân nhượng (không trừng phạt hoặc làm hại)', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_14_2', 'en-b2-14', NULL, 'comprehensive_test', 'listening', 'My grandparents live in a quiet rural village.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những người hàng xóm đã chào đón cô ấy nồng nhiệt, không chút thành kiến.","Khu vui chơi mới đã mang lại tác động tích cực cho khu1 xóm của chúng ta.","Người hàng xóm đã vui vẻ giúp tôi tưới cây trong lúc tôi đi vắng.","Ông bà tôi sống trong một ngôi làng nông thôn yên bình."]'::jsonb, 3, 'My grandparents live in a quiet rural village. → Ông bà tôi sống trong một ngôi làng nông thôn yên bình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_14_3', 'en-b2-14', NULL, 'comprehensive_test', 'listening', 'sacred', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["giẻ lau; vải vụn","thần thánh; thiêng liêng","ngân sách; khoản kinh phí","độ sáng; sự rực rỡ"]'::jsonb, 1, 'sacred (/ˈseɪkrɪd/) → thần thánh; thiêng liêng; bất khả xâm phạm; được coi trọng tuyệt đối', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_14_4', 'en-b2-14', NULL, 'comprehensive_test', 'listening', 'My cousins always tease me about my enormous backpack.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã hợp tác với hàng xóm để dọn dẹp khu vườn chung.","Tuyến xe buýt này đã trở nên đông đúc hơn kể từ tháng trước.","Họ hàng của tôi luôn trêu chọc tôi về chiếc ba lô quá khổ của mình.","Những người hàng xóm đã chào đón cô ấy nồng nhiệt, không chút thành kiến."]'::jsonb, 2, 'My cousins always tease me about my enormous backpack. → Họ hàng của tôi luôn trêu chọc tôi về chiếc ba lô quá khổ của mình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
