INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_14_6', 'en-b2-14', NULL, 'comprehensive_test', 'listening', 'I never meant to insult you with that joke.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Dù ở bất kỳ hoàn cảnh nào, bạn cũng không được để cửa trước không khóa.","Sau nhiều năm phục vụ, cô ấy đã đạt đến cấp bậc đại úy.","Việc dùng chung phòng ngủ đôi khi gây ra xung đột giữa hai anh em.","Tôi hoàn toàn không có ý định xúc phạm bạn bằng câu nói đùa đó."]'::jsonb, 3, 'I never meant to insult you with that joke. → Tôi hoàn toàn không có ý định xúc phạm bạn bằng câu nói đùa đó.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_14_7', 'en-b2-14', NULL, 'comprehensive_test', 'listening', 'assistance', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự trợ giúp; sự hỗ trợ","chồng (đồ vật xếp chồng lên nhau)","gây lo âu; làm bồn chồn; đáng lo ngại","đường cao tốc"]'::jsonb, 0, 'assistance (/əˈsɪstəns/) → sự trợ giúp; sự hỗ trợ', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_14_8', 'en-b2-14', NULL, 'comprehensive_test', 'listening', 'After years of service, she reached the rank of captain.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Câu lạc bộ chào đón tất cả mọi người, không phân biệt độ tuổi hay giới tính.","Tuyến xe buýt này đã trở nên đông đúc hơn kể từ tháng trước.","Sau nhiều năm phục vụ, cô ấy đã đạt đến cấp bậc đại úy.","Ngân hàng đã gọi điện sau khi phát hiện hành vi gian lận có thể xảy ra trong tài khoản của tôi."]'::jsonb, 2, 'After years of service, she reached the rank of captain. → Sau nhiều năm phục vụ, cô ấy đã đạt đến cấp bậc đại úy.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_14_9', 'en-b2-14', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Morally very bad and deliberately harmful.”?', '["cooperate","sacred","wicked","insult"]'::jsonb, 2, 'wicked (/ˈwɪkɪd/) → xấu xa; độc ác', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_14_10', 'en-b2-14', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Say or do something that treats someone with disrespect.”?', '["increasingly","deceive","insult","hell"]'::jsonb, 2, 'insult (/ɪnˈsʌlt/) → lăng mạ; xúc phạm', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_14_11', 'en-b2-14', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Help given to someone who needs it.”?', '["mercy","assistance","rural","wicked"]'::jsonb, 1, 'assistance (/əˈsɪstəns/) → sự trợ giúp; sự hỗ trợ', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
