INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_14_18', 'en-b2-14', NULL, 'comprehensive_test', 'reading', NULL, 'A fair justice system should balance appropriate punishment with mercy towards people who genuinely seek to change.', 'Dựa vào câu trên, từ “mercy” có nghĩa phù hợp nhất là gì?', '["nhà ga hành khách; bến cuối","hình tròn; có dạng vòng tròn","chờ đợi; ngóng chờ","sự khoan dung; lòng trắc ẩn; sự nhân nhượng (không trừng phạt hoặc làm hại)"]'::jsonb, 3, 'mercy: sự khoan dung; lòng trắc ẩn; sự nhân nhượng (không trừng phạt hoặc làm hại). Dịch cả câu: Một hệ thống tư pháp công bằng phải cân bằng giữa hình phạt thích đáng và sự khoan hồng đối với những người thực sự muốn hướng thiện.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_14_19', 'en-b2-14', NULL, 'comprehensive_test', 'reading', NULL, 'Reliable internet access can improve educational opportunities for children living in remote rural areas.', 'Dựa vào câu trên, từ “rural” có nghĩa phù hợp nhất là gì?', '["có thể xảy ra; có khả năng cao","vỡ vụn; bẻ vụn","thuộc nông thôn; thuộc vùng quê","đỏ mặt vì xấu hổ hoặc ngại ngùng"]'::jsonb, 2, 'rural: thuộc nông thôn; thuộc vùng quê. Dịch cả câu: Khả năng truy cập internet ổn định có thể cải thiện cơ hội giáo dục cho trẻ em sống ở các vùng nông thôn hẻo lánh.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_14_20', 'en-b2-14', NULL, 'comprehensive_test', 'reading', NULL, 'Tourism can support local economies, but visitors must respect sacred places and religious customs.', 'Dựa vào câu trên, từ “sacred” có nghĩa phù hợp nhất là gì?', '["du thuyền; thuyền buồm","bền vững; không gây hại môi trường","thần thánh; thiêng liêng","cuộc sum họp; sự đoàn tụ; buổi gặp mặt"]'::jsonb, 2, 'sacred: thần thánh; thiêng liêng; bất khả xâm phạm; được coi trọng tuyệt đối. Dịch cả câu: Du lịch có thể hỗ trợ kinh tế địa phương, nhưng du khách phải tôn trọng các thánh địa và phong tục tôn giáo.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_14_21', 'en-b2-14', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should teach children that teasing classmates about their appearance can seriously damage their confidence.', 'Dựa vào câu trên, từ “tease” có nghĩa phù hợp nhất là gì?', '["trêu chọc; chế nhạo","cơn giận; tính khí; tâm trạng cáu kỉnh","cột chỉ đường; biển chỉ đường","sự bình phục; sự phục hồi"]'::jsonb, 0, 'tease: trêu chọc; chế nhạo; người hay trêu ghẹo người khác. Dịch cả câu: Nhà trường nên giáo dục trẻ em rằng việc trêu chọc ngoại hình của bạn học có thể làm tổn hại nghiêm trọng đến sự tự tin của các em.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
