INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_14_24', 'en-b2-14', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “giới tính (mang tính xã hội và văn hóa)”', '["exhibit","astonishment","gender","straightforward"]'::jsonb, 2, 'giới tính (mang tính xã hội và văn hóa) → gender (/ˈdʒendər/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-15', 'en', 'Bài 15: Xã hội & Cộng đồng (8) - CEFR B2', 'CEFR B2', 'B2 · Xã hội', '26 từ vựng Tiếng Anh CEFR B2 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4015, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chaos', 'en-b2-15', 'chaos', '/ˈkeɪɑːs/', 'B2', 'sự hỗn loạn; tình trạng lộn xộn', 'n.', 'chaotic (adj.), chaotically (adv.)', 'Đồng nghĩa: disorder, confusion · Trái nghĩa: order', 'Là danh từ không đếm được; âm ch được phát âm là /k/, không phải /tʃ/.', 'The kitchen was in chaos after we baked together.', NULL, 'Căn bếp trở nên hỗn loạn sau khi chúng tôi cùng nhau làm bánh.', '{"wordId":"chaos","ukIpa":"/ˈkeɪɒs/","usIpa":"/ˈkeɪɑːs/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"a state of complete confusion and lack of order","vi":"sự hỗn loạn; tình trạng lộn xộn"}],"examples":[{"en":"The kitchen was in chaos after we baked together.","vi":"Căn bếp trở nên hỗn loạn sau khi chúng tôi cùng nhau làm bánh.","audioKind":"ex"},{"en":"Unexpected road closures caused chaos across the city, highlighting the need for better emergency planning.","vi":"Việc đóng cửa đường bất ngờ đã gây ra tình trạng hỗn loạn khắp thành phố, làm nổi bật nhu cầu cần có các kế hoạch ứng phó khẩn cấp tốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"in chaos","vi":"rơi vào hỗn loạn"},{"en":"cause chaos","vi":"gây ra sự hỗn loạn"},{"en":"complete chaos","vi":"sự hỗn loạn hoàn toàn"},{"en":"traffic chaos","vi":"sự hỗn loạn giao thông"}],"wordFamily":["chaotic (adj.)","chaotically (adv.)"],"synonyms":["disorder","confusion"],"antonyms":["order"],"tipVi":"Là danh từ không đếm được; âm ch được phát âm là /k/, không phải /tʃ/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_obligation', 'en-b2-15', 'obligation', '/ˌɑːblɪˈɡeɪʃən/', 'B2', 'nghĩa vụ; trách nhiệm', 'n.', 'oblige (v.), obligatory (adj.), obliged (adj.)', 'Đồng nghĩa: duty, responsibility', 'Thường dùng cấu trúc have an obligation to do, mang ý nghĩa có nghĩa vụ phải làm gì.', 'You have no obligation to buy anything here.', NULL, 'Bạn không có nghĩa vụ phải mua bất cứ thứ gì ở đây.', '{"wordId":"obligation","ukIpa":"/ˌɒblɪˈɡeɪʃən/","usIpa":"/ˌɑːblɪˈɡeɪʃən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"Something you must do for legal or moral reasons","vi":"nghĩa vụ; trách nhiệm"}],"examples":[{"en":"You have no obligation to buy anything here.","vi":"Bạn không có nghĩa vụ phải mua bất cứ thứ gì ở đây.","audioKind":"ex"},{"en":"Employers have a legal obligation to provide safe working conditions and protect employees from preventable harm.","vi":"Người sử dụng lao động có nghĩa vụ pháp lý trong việc cung cấp điều kiện làm việc an toàn và bảo vệ nhân viên khỏi những tổn thương có thể phòng ngừa.","audioKind":"ex2"}],"collocations":[{"en":"legal obligation","vi":"nghĩa vụ pháp lý"},{"en":"moral obligation","vi":"nghĩa vụ đạo đức"},{"en":"fulfil an obligation","vi":"thựchiện nghĩa vụ"},{"en":"under no obligation","vi":"không có nghĩa vụ"}],"wordFamily":["oblige (v.)","obligatory (adj.)","obliged (adj.)"],"synonyms":["duty","responsibility"],"antonyms":[],"tipVi":"Thường dùng cấu trúc have an obligation to do, mang ý nghĩa có nghĩa vụ phải làm gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thoughtful', 'en-b2-15', 'thoughtful', '/ˈθɔːtfəl/', 'B2', 'chu đáo; ân cần; trầm ngâm; suy tư sâu sắc', 'adj.', 'thought (n.), thoughtfully (adv.), thoughtfulness (n.), thoughtless (adj.)', 'Đồng nghĩa: considerate, reflective · Trái nghĩa: thoughtless, inconsiderate', 'Sự chu đáo đối với ai dùng thoughtful of someone; thoughtful không nhất thiết mang ý nghĩa lo lắng.', 'It was thoughtful of you to bring an umbrella.', NULL, 'Bạn thật chu đáo khi mang theo ô.', '{"wordId":"thoughtful","ukIpa":"/ˈθɔːtfəl/","usIpa":"/ˈθɔːtfəl/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"showing care for other people''s needs and feelings","vi":"chu đáo; ân cần"},{"pos":"adj.","en":"thinking carefully, or showing careful consideration","vi":"trầm ngâm; suy tư sâu sắc"}],"examples":[{"en":"It was thoughtful of you to bring an umbrella.","vi":"Bạn thật chu đáo khi mang theo ô.","audioKind":"ex"},{"en":"Thoughtful urban planning can create public spaces that meet the needs of residents with limited mobility.","vi":"Quy hoạch đô thị chu đáo có thể tạo ra các không gian công cộng đáp ứng nhu cầu của cư dân có khả năng di chuyển hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"thoughtful gesture","vi":"hành động chu đáo"},{"en":"thoughtful of someone","vi":"sự chu đáo của ai đó"},{"en":"thoughtful consideration","vi":"sự suy xét thấu đáo"},{"en":"thoughtful expression","vi":"vẻ mặt trầm ngâm"}],"wordFamily":["thought (n.)","thoughtfully (adv.)","thoughtfulness (n.)","thoughtless (adj.)"],"synonyms":["considerate","reflective"],"antonyms":["thoughtless","inconsiderate"],"tipVi":"Sự chu đáo đối với ai dùng thoughtful of someone; thoughtful không nhất thiết mang ý nghĩa lo lắng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_slang', 'en-b2-15', 'slang', '/slæŋ/', 'B2', 'tiếng lóng', 'n.', NULL, NULL, 'Thường là danh từ không đếm được; một biểu hiện tiếng lóng dùng a slang term.', 'My younger cousin uses slang I cannot understand.', NULL, 'Đứa em họ nhỏ tuổi của tôi dùng những từ lóng mà tôi không thể hiểu nổi.', '{"wordId":"slang","ukIpa":"/slæŋ/","usIpa":"/slæŋ/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"very informal words used by particular groups of people","vi":"tiếng lóng"}],"examples":[{"en":"My younger cousin uses slang I cannot understand.","vi":"Đứa em họ nhỏ tuổi của tôi dùng những từ lóng mà tôi không thể hiểu nổi.","audioKind":"ex"},{"en":"Although slang can strengthen group identity, excessive use may create barriers between speakers from different generations.","vi":"Mặc dù tiếng lóng có thể củng cố bản sắc nhóm, việc lạm dụng có thể tạo ra rào cản giữa những người nói thuộc các thế hệ khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"use slang","vi":"sử dụng tiếng lóng"},{"en":"a slang term","vi":"một từ lóng"},{"en":"internet slang","vi":"tiếng lóng cư dân mạng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; một biểu hiện tiếng lóng dùng a slang term.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_evil', 'en-b2-15', 'evil', '/ˈiː.vəl/', 'B2', 'xấu xa; độc ác; tội ác; điều ác; tai họa', 'adj.', NULL, 'Đồng nghĩa: wicked · Trái nghĩa: good', 'Mức độ nghiêm trọng mạnh hơn rất nhiều so với bad, thường liên quan đến các hành vi trái đạo đức trầm trọng.', 'In the story, an evil wizard steals everyone''s dreams.', NULL, 'Trong câu chuyện, một phù thủy độc ác đã đánh cắp giấc mơ của tất cả mọi người.', '{"wordId":"evil","ukIpa":"/ˈiː.vəl/","usIpa":"/ˈiː.vəl/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"morally very bad and deliberately causing harm","vi":"xấu xa; độc ác"},{"pos":"n.","en":"serious moral wrongdoing or something that causes great harm","vi":"tội ác; điều ác; tai họa"}],"examples":[{"en":"In the story, an evil wizard steals everyone''s dreams.","vi":"Trong câu chuyện, một phù thủy độc ác đã đánh cắp giấc mơ của tất cả mọi người.","audioKind":"ex"},{"en":"Literature often explores the conflict between good and evil through characters who face difficult moral choices.","vi":"Văn học thường khai thác cuộc xung đột giữa thiện và ác thông qua các nhân vật phải đối mặt với những lựa chọn đạo đức khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"good and evil","vi":"thiện và ác"},{"en":"an evil intention","vi":"ý đồ xấu"},{"en":"a necessary evil","vi":"một điều xấu nhưng buộc phải chấp nhận"}],"wordFamily":[],"synonyms":["wicked"],"antonyms":["good"],"tipVi":"Mức độ nghiêm trọng mạnh hơn rất nhiều so với bad, thường liên quan đến các hành vi trái đạo đức trầm trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_investigation', 'en-b2-15', 'investigation', '/ɪnˌvestɪˈɡeɪʃn/', 'B2', 'cuộc điều tra; sự tìm hiểu; công trình nghiên cứu; sự khảo sát', 'n.', 'investigate (v.), investigator (n.), investigative (adj.)', 'Đồng nghĩa: inquiry, examination', 'Điều tra về cái gì dùng investigation into; under investigation có nghĩa là đang bị điều tra.', 'An investigation revealed why the kitchen ceiling was leaking.', NULL, 'Một cuộc điều tra đã làm sáng tỏ lý do tại sao trần nhà bếp bị dột.', '{"wordId":"investigation","ukIpa":"/ɪnˌvestɪˈɡeɪʃn/","usIpa":"/ɪnˌvestɪˈɡeɪʃn/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"a careful effort to discover facts about an event or problem","vi":"cuộc điều tra; sự tìm hiểu"},{"pos":"n.","en":"a systematic study intended to increase knowledge about a subject","vi":"công trình nghiên cứu; sự khảo sát"}],"examples":[{"en":"An investigation revealed why the kitchen ceiling was leaking.","vi":"Một cuộc điều tra đã làm sáng tỏ lý do tại sao trần nhà bếp bị dột.","audioKind":"ex"},{"en":"An independent investigation into river pollution could help authorities identify its causes and prevent further environmental damage.","vi":"Một cuộc điều tra độc lập về tình trạng ô nhiễm sông ngòi có thể giúp nhà chức trách xác định nguyên nhân và ngăn chặn tổn hại môi trường tiếp diễn.","audioKind":"ex2"}],"collocations":[{"en":"conduct an investigation","vi":"tiến hành điều tra"},{"en":"launch an investigation","vi":"mở cuộc điều tra"},{"en":"an investigation into","vi":"cuộc điều tra về"},{"en":"under investigation","vi":"đang trong quá trình điều tra"}],"wordFamily":["investigate (v.)","investigator (n.)","investigative (adj.)"],"synonyms":["inquiry","examination"],"antonyms":[],"tipVi":"Điều tra về cái gì dùng investigation into; under investigation có nghĩa là đang bị điều tra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mankind', 'en-b2-15', 'mankind', '/mænˈkaɪnd/', 'B2', 'loài người', 'n.', NULL, 'Đồng nghĩa: humankind, humanity', 'Chỉ toàn thể nhân loại chứ không chỉ giới nam; từ mang tính bao hàm hơn có thể dùng humankind.', 'This museum explores how mankind learned to grow food.', NULL, 'Bảo tàng này khám phá cách loài người học được cách trồng trọt lương thực.', '{"wordId":"mankind","ukIpa":"/mænˈkaɪnd/","usIpa":"/mænˈkaɪnd/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"all human beings considered as one group","vi":"loài người"}],"examples":[{"en":"This museum explores how mankind learned to grow food.","vi":"Bảo tàng này khám phá cách loài người học được cách trồng trọt lương thực.","audioKind":"ex"},{"en":"Climate change presents a challenge to mankind that requires sustained cooperation across national borders.","vi":"Biến đổi khí hậu đặt ra một thách thức đối với nhân loại, đòi hỏi sự hợp tác bền chặt vượt qua cả biên giới các quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"the future of mankind","vi":"tương lai của nhân loại"},{"en":"the history of mankind","vi":"lịch sử loài người"},{"en":"for the benefit of mankind","vi":"vì lợi ích của nhân loại"}],"wordFamily":[],"synonyms":["humankind","humanity"],"antonyms":[],"tipVi":"Chỉ toàn thể nhân loại chứ không chỉ giới nam; từ mang tính bao hàm hơn có thể dùng humankind.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unreasonable', 'en-b2-15', 'unreasonable', '/ʌnˈriːzənəbl/', 'B2', 'vô lý; không phải phép, không hợp lẽ phải; quá đáng; quá cao, vượt mức hợp lý', 'adj.', 'reasonable (adj.), unreasonably (adv.), reason (n.)', 'Đồng nghĩa: unfair, excessive · Trái nghĩa: reasonable', 'Có thể dùng để chỉ tính cách con người không hợp lẽ phải, hoặc dùng cho yêu cầu, giá cả quá mức.', 'It seems unreasonable to blame you for the weather.', NULL, 'Thật là vô lý khi trách bạn vì thời tiết xấu.', '{"wordId":"unreasonable","ukIpa":"/ʌnˈriːzənəbl/","usIpa":"/ʌnˈriːzənəbl/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Not fair, sensible, or willing to accept good reasons.","vi":"vô lý; không phải phép, không hợp lẽ phải"},{"pos":"adj.","en":"Greater than is fair or acceptable.","vi":"quá đáng; quá cao, vượt mức hợp lý"}],"examples":[{"en":"It seems unreasonable to blame you for the weather.","vi":"Thật là vô lý khi trách bạn vì thời tiết xấu.","audioKind":"ex"},{"en":"Expecting employees to answer messages throughout their holidays places unreasonable demands on their time and harms wellbeing.","vi":"Việc yêu cầu nhân viên trả lời tin nhắn trong suốt kỳ nghỉ là một đòi hỏi quá đáng đối với thời gian của họ và gây hại cho sức khỏe tinh thần.","audioKind":"ex2"}],"collocations":[{"en":"unreasonable demands","vi":"đòi hỏi quá đáng"},{"en":"unreasonable behaviour","vi":"hành vi vô lý"},{"en":"unreasonable expectations","vi":"kỳ vọng phi lý"}],"wordFamily":["reasonable (adj.)","unreasonably (adv.)","reason (n.)"],"synonyms":["unfair","excessive"],"antonyms":["reasonable"],"tipVi":"Có thể dùng để chỉ tính cách con người không hợp lẽ phải, hoặc dùng cho yêu cầu, giá cả quá mức.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_overwhelming', 'en-b2-15', 'overwhelming', '/ˌoʊvərˈwelmɪŋ/', 'B2', 'áp đảo; vô cùng lớn, mạnh mẽ; choáng ngợp; quá lớn khiến khó chịu đựng nổi', 'adj.', 'overwhelm (v.), overwhelmingly (adv.)', NULL, 'Nhấn mạnh mức độ cực lớn; có thể dùng để chỉ sự ủng hộ hoặc áp lực.', 'The proposal received overwhelming support from our neighbours.', NULL, 'Đề xuất này nhận được sự ủng hộ áp đảo từ những người hàng xóm của chúng tôi.', '{"wordId":"overwhelming","ukIpa":"/ˌəʊvəˈwelmɪŋ/","usIpa":"/ˌoʊvərˈwelmɪŋ/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"So great or strong that little can oppose it","vi":"áp đảo; vô cùng lớn, mạnh mẽ"},{"pos":"adj.","en":"Too intense or difficult to deal with","vi":"choáng ngợp; quá lớn khiến khó chịu đựng nổi"}],"examples":[{"en":"The proposal received overwhelming support from our neighbours.","vi":"Đề xuất này nhận được sự ủng hộ áp đảo từ những người hàng xóm của chúng tôi.","audioKind":"ex"},{"en":"An overwhelming majority of residents support investment in reliable public transport rather than wider roads.","vi":"Đại đa số cư dân ủng hộ việc đầu tư vào giao thông công cộng đáng tin cậy hơn là mở rộng đường xá.","audioKind":"ex2"}],"collocations":[{"en":"overwhelming majority","vi":"đại đa số"},{"en":"overwhelming evidence","vi":"bằng chứng thuyết phục"},{"en":"overwhelming support","vi":"sự ủng hộ áp đảo"},{"en":"overwhelming pressure","vi":"áp lực nặng nề"}],"wordFamily":["overwhelm (v.)","overwhelmingly (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Nhấn mạnh mức độ cực lớn; có thể dùng để chỉ sự ủng hộ hoặc áp lực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_establish', 'en-b2-15', 'establish', '/ɪˈstæblɪʃ/', 'B2', 'thành lập; thiết lập; xác lập; củng cố vị thế; chứng minh; xác minh', 'v.', 'establishment (n.), established (adj.)', 'Đồng nghĩa: found, set up', 'establish là ngoại động từ, theo sau là các tổ chức, hệ thống hoặc sự việc.', 'Our neighbours established a gardening club last spring.', NULL, 'Những người hàng xóm của chúng tôi đã thành lập một câu lạc bộ làm vườn vào mùa xuân năm ngoái.', '{"wordId":"establish","ukIpa":"/ɪˈstæblɪʃ/","usIpa":"/ɪˈstæblɪʃ/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"to start an organisation, system, or lasting arrangement","vi":"thành lập; thiết lập"},{"pos":"v.","en":"to make a position or reputation widely accepted","vi":"xác lập; củng cố vị thế"},{"pos":"v.","en":"to discover or prove that something is true","vi":"chứng minh; xác minh"}],"examples":[{"en":"Our neighbours established a gardening club last spring.","vi":"Những người hàng xóm của chúng tôi đã thành lập một câu lạc bộ làm vườn vào mùa xuân năm ngoái.","audioKind":"ex"},{"en":"Governments should establish clear standards to ensure that new housing is both safe and energy efficient.","vi":"Chính phủ nên thiết lập các tiêu chuẩn rõ ràng để đảm bảo nhà ở mới vừa an toàn vừa tiết kiệm năng lượng.","audioKind":"ex2"}],"collocations":[{"en":"establish a business","vi":"thành lập doanh nghiệp"},{"en":"establish a reputation","vi":"gây dựng danh tiếng"},{"en":"establish the facts","vi":"xác minh sự thật"},{"en":"establish a link","vi":"thiết lập mối liên kết"}],"wordFamily":["establishment (n.)","established (adj.)"],"synonyms":["found","set up"],"antonyms":[],"tipVi":"establish là ngoại động từ, theo sau là các tổ chức, hệ thống hoặc sự việc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_interact', 'en-b2-15', 'interact', '/ˌɪntərˈækt/', 'B2', 'tương tác; giao tiếp; tác động lẫn nhau; ảnh hưởng lẫn nhau', 'v.', 'interaction (n.), interactive (adj.), interactively (adv.)', NULL, 'Động từ nội intransitive: tương tác với ai dùng interact with someone.', 'Our neighbours often interact while their children play outside.', NULL, 'Những người hàng xóm của chúng tôi thường tương tác với nhau khi con cái họ chơi đùa bên ngoài.', '{"wordId":"interact","ukIpa":"/ˌɪntərˈækt/","usIpa":"/ˌɪntərˈækt/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"To communicate or do things with other people.","vi":"tương tác; giao tiếp"},{"pos":"v.","en":"To affect one another when combined or brought together.","vi":"tác động lẫn nhau; ảnh hưởng lẫn nhau"}],"examples":[{"en":"Our neighbours often interact while their children play outside.","vi":"Những người hàng xóm của chúng tôi thường tương tác với nhau khi con cái họ chơi đùa bên ngoài.","audioKind":"ex"},{"en":"Group projects encourage students to interact with classmates whose experiences and perspectives differ from their own.","vi":"Các dự án nhóm khuyến khích sinh viên tương tác với các bạn học có kinh nghiệm và quan điểm khác biệt với mình.","audioKind":"ex2"}],"collocations":[{"en":"interact with","vi":"tương tác với"},{"en":"interact socially","vi":"giao tiếp xã hội"},{"en":"interact with each other","vi":"tương tác lẫn nhau"}],"wordFamily":["interaction (n.)","interactive (adj.)","interactively (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ nội intransitive: tương tác với ai dùng interact with someone.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_superstitious', 'en-b2-15', 'superstitious', '/ˌsuːpərˈstɪʃəs/', 'B2', 'mê tín', 'adj.', 'superstition (n.), superstitiously (adv.)', NULL, 'Thường dùng be superstitious about để chỉ việc mê tín về điều gì đó.', 'My superstitious cousin always carries a lucky stone.', NULL, 'Người anh em họ mê tín của tôi luôn mang theo một viên đá may mắn.', '{"wordId":"superstitious","ukIpa":"/ˌsuːpəˈstɪʃəs/","usIpa":"/ˌsuːpərˈstɪʃəs/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"believing certain actions or objects bring good or bad luck","vi":"mê tín"}],"examples":[{"en":"My superstitious cousin always carries a lucky stone.","vi":"Người anh em họ mê tín của tôi luôn mang theo một viên đá may mắn.","audioKind":"ex"},{"en":"Superstitious beliefs may influence financial decisions when people rely on lucky objects rather than reliable evidence.","vi":"Các quan niệm mê tín có thể ảnh hưởng đến quyết định tài chính khi mọi người dựa vào các vật may mắn thay vì bằng chứng đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"superstitious beliefs","vi":"quan niệm mê tín"},{"en":"superstitious about","vi":"mê tín về điều gì"},{"en":"superstitious practices","vi":"thực hành mê tín"}],"wordFamily":["superstition (n.)","superstitiously (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng be superstitious about để chỉ việc mê tín về điều gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_kidnap', 'en-b2-15', 'kidnap', '/ˈkɪdnæp/', 'B2', 'bắt cóc; cướp giữ người trái phép', 'v.', 'kidnapper (n.), kidnapping (n.)', 'Đồng nghĩa: abduct · Trái nghĩa: release', 'Không hạn chế ở trẻ em; thường dùng quá khứ kidnapped, phân từ kidnapping.', 'In the film, criminals kidnap a wealthy businessman.', NULL, 'Trong bộ phim, những kẻ tội phạm bắt cóc một doanh nhân giàu có.', '{"wordId":"kidnap","ukIpa":"/ˈkɪdnæp/","usIpa":"/ˈkɪdnæp/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"To take someone away illegally and hold them captive","vi":"bắt cóc; cướp giữ người trái phép"}],"examples":[{"en":"In the film, criminals kidnap a wealthy businessman.","vi":"Trong bộ phim, những kẻ tội phạm bắt cóc một doanh nhân giàu có.","audioKind":"ex"},{"en":"International cooperation helps police investigate criminal groups that kidnap people and demand money for their release.","vi":"Sự hợp tác quốc tế giúp cảnh sát điều tra các băng nhóm tội phạm bắt cóc người và đòi tiền chuộc để thả họ.","audioKind":"ex2"}],"collocations":[{"en":"kidnap someone for ransom","vi":"bắt cóc ai đó đòi tiền chuộc"},{"en":"a kidnapping victim","vi":"nạn nhân bị bắt cóc"},{"en":"a kidnapping attempt","vi":"âm mưu bắt cóc"}],"wordFamily":["kidnapper (n.)","kidnapping (n.)"],"synonyms":["abduct"],"antonyms":["release"],"tipVi":"Không hạn chế ở trẻ em; thường dùng quá khứ kidnapped, phân từ kidnapping.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disrupt', 'en-b2-15', 'disrupt', '/dɪsˈrʌpt/', 'B2', 'làm gián đoạn; làm rối loạn; cản trở', 'v.', 'disruption (n.), disruptive (adj.)', 'Đồng nghĩa: disturb, interrupt', 'Là ngoại động từ, trực tiếp đi kèm với hoạt động hoặc hệ thống; không phải là tính từ.', 'Heavy snow could disrupt our train journey tomorrow.', NULL, 'Tuyết dày có thể làm gián đoạn hành trình tàu hỏa của chúng ta vào ngày mai.', '{"wordId":"disrupt","ukIpa":"/dɪsˈrʌpt/","usIpa":"/dɪsˈrʌpt/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"Prevent an activity or system from continuing normally.","vi":"làm gián đoạn; làm rối loạn; cản trở"}],"examples":[{"en":"Heavy snow could disrupt our train journey tomorrow.","vi":"Tuyết dày có thể làm gián đoạn hành trình tàu hỏa của chúng ta vào ngày mai.","audioKind":"ex"},{"en":"Frequent power cuts disrupt online learning, particularly in rural communities where reliable internet access is already limited.","vi":"Tình trạng mất điện thường xuyên làm gián đoạn việc học trực tuyến, đặc biệt là ở các cộng đồng nông thôn nơi khả năng truy cập internet ổn định vốn đã hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"disrupt traffic","vi":"làm gián đoạn giao thông"},{"en":"disrupt services","vi":"làm gián đoạn dịch vụ"},{"en":"disrupt sleep","vi":"làm gián đoạn giấc ngủ"},{"en":"disrupt learning","vi":"làm gián đoạn việc học"}],"wordFamily":["disruption (n.)","disruptive (adj.)"],"synonyms":["disturb","interrupt"],"antonyms":[],"tipVi":"Là ngoại động từ, trực tiếp đi kèm với hoạt động hoặc hệ thống; không phải là tính từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_indirectly', 'en-b2-15', 'indirectly', '/ˌɪndəˈrektli/', 'B2', 'gián tiếp; qua trung gian; một cách bóng gió; vòng vo', 'adv.', 'indirect (adj.), direct (adj.), directly (adv.)', 'Trái nghĩa: directly', 'Là phó từ, không phải tính từ; dùng indirectly khi bổ nghĩa cho động từ.', 'I heard about the empty flat indirectly through a colleague.', NULL, 'Tôi nghe thông tin về căn hộ trống một cách gián tiếp qua một đồng nghiệp.', '{"wordId":"indirectly","ukIpa":"/ˌɪndəˈrektli/","usIpa":"/ˌɪndəˈrektli/","cefr":"B2","topic":"society","senses":[{"pos":"adv.","en":"Through another person, thing, or stage rather than directly","vi":"gián tiếp; qua trung gian"},{"pos":"adv.","en":"Without expressing something clearly or openly","vi":"một cách bóng gió; vòng vo"}],"examples":[{"en":"I heard about the empty flat indirectly through a colleague.","vi":"Tôi nghe thông tin về căn hộ trống một cách gián tiếp qua một đồng nghiệp.","audioKind":"ex"},{"en":"Higher fuel prices indirectly affect food costs because transporting agricultural products becomes more expensive for suppliers.","vi":"Giá nhiên liệu cao hơn sẽ gián tiếp ảnh hưởng đến giá thực phẩm vì chi phí vận chuyển nông sản đối với các nhà cung cấp trở nên đắt đỏ hơn.","audioKind":"ex2"}],"collocations":[{"en":"indirectly affect","vi":"ảnh hưởng gián tiếp"},{"en":"indirectly responsible for","vi":"chịu trách nhiệm gián tiếp"},{"en":"refer indirectly to","vi":"nhắc đến một cách bóng gió"},{"en":"directly or indirectly","vi":"trực tiếp hay gián tiếp"}],"wordFamily":["indirect (adj.)","direct (adj.)","directly (adv.)"],"synonyms":[],"antonyms":["directly"],"tipVi":"Là phó từ, không phải tính từ; dùng indirectly khi bổ nghĩa cho động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_migration', 'en-b2-15', 'migration', '/maɪˈɡreɪʃən/', 'B2', 'sự di cư; sự chuyển cư của con người; sự di trú của động vật; sự chuyển đổi dữ liệu hoặc hệ thống', 'n.', 'migrate (v.), migrant (n.), migratory (adj.)', NULL, 'Migration mang nghĩa chung là di cư; immigration nhấn mạnh việc di cư nhập cảnh vào một nước.', 'We watched the birds during their annual autumn migration.', NULL, 'Chúng tôi đã quan sát những chú chim trong chuyến di trú mùa thu thường niên của chúng.', '{"wordId":"migration","ukIpa":"/maɪˈɡreɪʃən/","usIpa":"/maɪˈɡreɪʃən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"The movement of people to live in another place.","vi":"sự di cư; sự chuyển cư của con người"},{"pos":"n.","en":"The regular movement of animals between regions, often with the seasons.","vi":"sự di trú của động vật"},{"pos":"n.","en":"The transfer of data or software to another computer system.","vi":"sự chuyển đổi dữ liệu hoặc hệ thống"}],"examples":[{"en":"We watched the birds during their annual autumn migration.","vi":"Chúng tôi đã quan sát những chú chim trong chuyến di trú mùa thu thường niên của chúng.","audioKind":"ex"},{"en":"Migration from rural areas to cities can increase pressure on housing while providing workers for expanding industries.","vi":"Sự di cư từ nông thôn ra thành phố có thể làm gia tăng áp lực về nhà ở đồng thời cung cấp lao động cho các ngành công nghiệp đang mở rộng.","audioKind":"ex2"}],"collocations":[{"en":"rural-to-urban migration","vi":"di cư từ nông thôn ra thành phố"},{"en":"seasonal migration","vi":"sự di cư theo mùa"},{"en":"bird migration","vi":"sự di trú của loài chim"},{"en":"data migration","vi":"sự chuyển đổi dữ liệu"}],"wordFamily":["migrate (v.)","migrant (n.)","migratory (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Migration mang nghĩa chung là di cư; immigration nhấn mạnh việc di cư nhập cảnh vào một nước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_concern', 'en-b2-15', 'concern', '/kənˈsɝːn/', 'B2', 'sự lo lắng; sự quan tâm; vấn đề đáng lo ngại; mối bận tâm; liên quan đến; khiến lo lắng', 'n.', 'concerned (adj.), concerning (prep.)', 'Đồng nghĩa: worry', 'concern about thường chỉ sự lo lắng về sự việc; for thường chỉ sự quan tâm đến ai đó.', 'Her main concern is getting home before the storm.', NULL, 'Mối quan tâm lớn nhất của cô ấy là về nhà trước cơn bão.', '{"wordId":"concern","ukIpa":"/kənˈsɜːn/","usIpa":"/kənˈsɝːn/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"A feeling of worry about something important","vi":"sự lo lắng; sự quan tâm"},{"pos":"n.","en":"An issue that matters or causes worry","vi":"vấn đề đáng lo ngại; mối bận tâm"},{"pos":"v.","en":"To relate to someone or something, or cause worry","vi":"liên quan đến; khiến lo lắng"}],"examples":[{"en":"Her main concern is getting home before the storm.","vi":"Mối quan tâm lớn nhất của cô ấy là về nhà trước cơn bão.","audioKind":"ex"},{"en":"Growing concern about air pollution has encouraged many cities to invest in cleaner public transport systems.","vi":"Sự lo ngại ngày càng tăng về ô nhiễm không khí đã khuyến khích nhiều thành phố đầu tư vào các hệ thống giao thông công cộng sạch hơn.","audioKind":"ex2"}],"collocations":[{"en":"concern about safety","vi":"sự lo lắng về vấn đề an toàn"},{"en":"raise concerns","vi":"gây ra những lo ngại"},{"en":"a major concern","vi":"một vấn đề lớn"},{"en":"concern for others","vi":"sự quan tâm đến người khác"}],"wordFamily":["concerned (adj.)","concerning (prep.)"],"synonyms":["worry"],"antonyms":[],"tipVi":"concern about thường chỉ sự lo lắng về sự việc; for thường chỉ sự quan tâm đến ai đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_holy', 'en-b2-15', 'holy', '/ˈhoʊli/', 'B2', 'thần thánh; thiêng liêng; thánh', 'adj.', 'holiness (n.), unholy (adj.)', 'Đồng nghĩa: sacred · Trái nghĩa: unholy', 'holy nhấn mạnh tính chất thiêng liêng về tôn giáo, phát âm giống với wholly.', 'Visitors remove their shoes before entering this holy place.', NULL, 'Du khách cởi giày trước khi bước vào chốn linh thiêng này.', '{"wordId":"holy","ukIpa":"/ˈhəʊli/","usIpa":"/ˈhoʊli/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Connected with a religion and treated with deep respect","vi":"thần thánh; thiêng liêng; thánh"}],"examples":[{"en":"Visitors remove their shoes before entering this holy place.","vi":"Du khách cởi giày trước khi bước vào chốn linh thiêng này.","audioKind":"ex"},{"en":"Protecting holy sites requires governments to balance public access with respect for local religious traditions.","vi":"Việc bảo vệ các thánh địa đòi hỏi chính quyền phải cân bằng giữa nhu cầu tham quan của công chúng và sự tôn trọng đối với các truyền thống tôn giáo địa phương.","audioKind":"ex2"}],"collocations":[{"en":"holy place","vi":"thánh địa"},{"en":"holy book","vi":"kinh thánh"},{"en":"holy day","vi":"ngày lễ tôn giáo"}],"wordFamily":["holiness (n.)","unholy (adj.)"],"synonyms":["sacred"],"antonyms":["unholy"],"tipVi":"holy nhấn mạnh tính chất thiêng liêng về tôn giáo, phát âm giống với wholly.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_distribution', 'en-b2-15', 'distribution', '/ˌdɪstrɪˈbjuːʃən/', 'B2', 'sự phân phát; sự phân phối; sự phân bố', 'n.', 'distribute (v.), distributor (n.), redistribution (n.)', NULL, 'Vừa chỉ quá trình phân phát, vừa chỉ trạng thái phân bố của dân cư và các yếu tố khác.', 'Volunteers organised the distribution of warm blankets after the storm.', NULL, 'Các tình nguyện viên đã tổ chức phân phát chăn ấm sau cơn bão.', '{"wordId":"distribution","ukIpa":"/ˌdɪstrɪˈbjuːʃən/","usIpa":"/ˌdɪstrɪˈbjuːʃən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"the process of giving or delivering things to different people","vi":"sự phân phát; sự phân phối"},{"pos":"n.","en":"the way something is spread across an area or group","vi":"sự phân bố"}],"examples":[{"en":"Volunteers organised the distribution of warm blankets after the storm.","vi":"Các tình nguyện viên đã tổ chức phân phát chăn ấm sau cơn bão.","audioKind":"ex"},{"en":"The uneven distribution of medical services leaves many rural communities without adequate access to healthcare.","vi":"Sự phân bố không đều của các dịch vụ y tế khiến nhiều cộng đồng nông thôn không thể tiếp cận đầy đủ với chăm sóc sức khỏe.","audioKind":"ex2"}],"collocations":[{"en":"distribution of resources","vi":"phân bổ tài nguyên"},{"en":"population distribution","vi":"sự phân bố dân cư"},{"en":"distribution network","vi":"mạng lưới phân phối"},{"en":"uneven distribution","vi":"phân bố không đều"}],"wordFamily":["distribute (v.)","distributor (n.)","redistribution (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Vừa chỉ quá trình phân phát, vừa chỉ trạng thái phân bố của dân cư và các yếu tố khác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_embrace', 'en-b2-15', 'embrace', '/ɪmˈbreɪs/', 'B2', 'chấp nhận; đón nhận, hưởng ứng; ôm; cái ôm', 'v.', NULL, 'Đồng nghĩa: accept, adopt, hug · Trái nghĩa: reject', 'Khi thể hiện sự tiếp nhận, thường đi với các danh từ trừu tượng như change, idea.', 'My grandparents have embraced video calls to stay connected.', NULL, 'Ông bà tôi đã đón nhận việc gọi video để giữ liên lạc.', '{"wordId":"embrace","ukIpa":"/ɪmˈbreɪs/","usIpa":"/ɪmˈbreɪs/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"to willingly accept an idea, change, or opportunity","vi":"chấp nhận; đón nhận, hưởng ứng"},{"pos":"v.","en":"to hold someone closely in your arms","vi":"ôm"},{"pos":"n.","en":"an act of holding someone closely in your arms","vi":"cái ôm"}],"examples":[{"en":"My grandparents have embraced video calls to stay connected.","vi":"Ông bà tôi đã đón nhận việc gọi video để giữ liên lạc.","audioKind":"ex"},{"en":"Schools that embrace new technology should also ensure that all students have equal access to digital resources.","vi":"Các trường học đón nhận công nghệ mới cũng nên đảm bảo rằng mọi học sinh đều có quyền tiếp cận bình đẳng với tài nguyên số.","audioKind":"ex2"}],"collocations":[{"en":"embrace change","vi":"đón nhận sự thay đổi"},{"en":"embrace an opportunity","vi":"nắm bắt cơ hội"},{"en":"a warm embrace","vi":"cái ôm ấm áp"}],"wordFamily":[],"synonyms":["accept","adopt","hug"],"antonyms":["reject"],"tipVi":"Khi thể hiện sự tiếp nhận, thường đi với các danh từ trừu tượng như change, idea.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tribe', 'en-b2-15', 'tribe', '/traɪb/', 'B2', 'bộ lạc; bộ tộc', 'n.', 'tribal (adj.)', NULL, 'Khi chỉ một cộng đồng cụ thể, nên tôn trọng tên tự xưng của họ và tránh dùng từ chung chung.', 'The guide belongs to a tribe from this valley.', NULL, 'Hướng dẫn viên này thuộc về một bộ tộc đến từ thung lũng này.', '{"wordId":"tribe","ukIpa":"/traɪb/","usIpa":"/traɪb/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"a social group sharing ancestry, traditions, and community ties","vi":"bộ lạc; bộ tộc"}],"examples":[{"en":"The guide belongs to a tribe from this valley.","vi":"Hướng dẫn viên này thuộc về một bộ tộc đến từ thung lũng này.","audioKind":"ex"},{"en":"Development projects should respect the land rights and cultural traditions of local tribes.","vi":"Các dự án phát triển nên tôn trọng quyền về đất đai và truyền thống văn hóa của các bộ tộc địa phương.","audioKind":"ex2"}],"collocations":[{"en":"tribal traditions","vi":"truyền thống bộ tộc"},{"en":"a nomadic tribe","vi":"một bộ lạc du mục"},{"en":"members of a tribe","vi":"thành viên của một bộ lạc"}],"wordFamily":["tribal (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ một cộng đồng cụ thể, nên tôn trọng tên tự xưng của họ và tránh dùng từ chung chung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cooperation', 'en-b2-15', 'cooperation', '/koʊˌɑːpəˈreɪʃən/', 'B2', 'hợp tác; cộng tác; sự phối hợp; sự hỗ trợ', 'n.', 'cooperate (v.), cooperative (adj.), cooperatively (adv.)', 'Đồng nghĩa: collaboration, teamwork · Trái nghĩa: non-cooperation', 'Thường là danh từ không đếm được; cụm từ "hợp tác với ai" dùng in cooperation with.', 'Cleaning the shared kitchen requires cooperation from everyone.', NULL, 'Việc dọn dẹp nhà bếp chung đòi hỏi sự phối hợp từ tất cả mọi người.', '{"wordId":"cooperation","ukIpa":"/kəʊˌɒpəˈreɪʃən/","usIpa":"/koʊˌɑːpəˈreɪʃən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"the act of working together towards a shared goal","vi":"hợp tác; cộng tác"},{"pos":"n.","en":"willingness to help or do what someone requests","vi":"sự phối hợp; sự hỗ trợ"}],"examples":[{"en":"Cleaning the shared kitchen requires cooperation from everyone.","vi":"Việc dọn dẹp nhà bếp chung đòi hỏi sự phối hợp từ tất cả mọi người.","audioKind":"ex"},{"en":"International cooperation is essential for addressing environmental problems that extend beyond the borders of individual countries.","vi":"Hợp tác quốc tế là yếu tố thiết yếu để giải quyết các vấn đề môi trường vượt ra ngoài biên giới của từng quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"international cooperation","vi":"hợp tác quốc tế"},{"en":"close cooperation","vi":"hợp tác chặt chẽ"},{"en":"in cooperation with","vi":"hợp tác với"},{"en":"full cooperation","vi":"sự phối hợp đầy đủ"}],"wordFamily":["cooperate (v.)","cooperative (adj.)","cooperatively (adv.)"],"synonyms":["collaboration","teamwork"],"antonyms":["non-cooperation"],"tipVi":"Thường là danh từ không đếm được; cụm từ \"hợp tác với ai\" dùng in cooperation with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_criticize', 'en-b2-15', 'criticize', '/ˈkrɪtɪsaɪz/', 'B2', 'chỉ trích; phê bình; chê bai', 'v.', 'criticism (n.), critic (n.), critical (adj.), critically (adv.)', 'Đồng nghĩa: fault, condemn · Trái nghĩa: praise', 'criticize sb for sth; tiếng Anh-Anh thường viết là criticise.', 'Please don''t criticize my cooking before you taste it.', NULL, 'Xin đừng chê món ăn của tôi trước khi bạn nếm thử nó.', '{"wordId":"criticize","ukIpa":"/ˈkrɪtɪsaɪz/","usIpa":"/ˈkrɪtɪsaɪz/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"express disapproval of someone or something","vi":"chỉ trích; phê bình; chê bai"}],"examples":[{"en":"Please don''t criticize my cooking before you taste it.","vi":"Xin đừng chê món ăn của tôi trước khi bạn nếm thử nó.","audioKind":"ex"},{"en":"Many residents criticize the council for prioritizing road construction over improvements to public transport.","vi":"Nhiều cư dân chỉ trích hội đồng thành phố vì ưu tiên xây dựng đường xá hơn là cải thiện giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"strongly criticize","vi":"chỉ trích gay gắt"},{"en":"criticize someone for something","vi":"chỉ trích ai vì điều gì"},{"en":"widely criticized","vi":"bị chỉ trích rộng rãi"}],"wordFamily":["criticism (n.)","critic (n.)","critical (adj.)","critically (adv.)"],"synonyms":["fault","condemn"],"antonyms":["praise"],"tipVi":"criticize sb for sth; tiếng Anh-Anh thường viết là criticise.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_notable', 'en-b2-15', 'notable', '/ˈnoʊtəbl/', 'B2', 'đáng chú ý; nổi bật; rõ rệt; nhân vật nổi tiếng; yếu nhân', 'adj.', 'notably (adv.)', 'Đồng nghĩa: remarkable, significant · Trái nghĩa: unremarkable', 'notable for diễn tả ý nghĩa nổi tiếng hoặc gây chú ý nhờ vào điều gì đó.', 'Her balcony is notable for its bright yellow flowers.', NULL, 'Ban công nhà cô ấy gây ấn tượng mạnh bởi những bông hoa màu vàng rực rỡ.', '{"wordId":"notable","ukIpa":"/ˈnəʊtəbl/","usIpa":"/ˈnoʊtəbl/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"important or unusual enough to deserve attention","vi":"đáng chú ý; nổi bật; rõ rệt"},{"pos":"n.","en":"a famous or important person, especially in a particular community","vi":"nhân vật nổi tiếng; yếu nhân"}],"examples":[{"en":"Her balcony is notable for its bright yellow flowers.","vi":"Ban công nhà cô ấy gây ấn tượng mạnh bởi những bông hoa màu vàng rực rỡ.","audioKind":"ex"},{"en":"The city has achieved a notable reduction in air pollution since introducing stricter vehicle standards.","vi":"Thành phố đã đạt được mức giảm ô nhiễm không khí đáng kể kể từ khi áp dụng các tiêu chuẩn xe cộ nghiêm ngặt hơn.","audioKind":"ex2"}],"collocations":[{"en":"a notable achievement","vi":"một thành tựu đáng chú ý"},{"en":"a notable exception","vi":"một ngoại lệ đáng chú ý"},{"en":"notable for","vi":"nổi tiếng vì; đáng chú ý vì"}],"wordFamily":["notably (adv.)"],"synonyms":["remarkable","significant"],"antonyms":["unremarkable"],"tipVi":"notable for diễn tả ý nghĩa nổi tiếng hoặc gây chú ý nhờ vào điều gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_immigrate', 'en-b2-15', 'immigrate', '/ˈɪmɪɡreɪt/', 'B2', 'nhập cư; chuyển đến sinh sống lâu dài ở một quốc gia khác', 'v.', 'immigration (n.), immigrant (n.)', 'Trái nghĩa: emigrate', 'immigrate to nhấn mạnh chiều hướng nhập cư; emigrate from nhấn mạnh chiều hướng di cư ra đi.', 'Her grandparents immigrated to Canada and opened a bakery.', NULL, 'Ông bà của cô ấy đã di cư sang Canada và mở một tiệm bánh.', '{"wordId":"immigrate","ukIpa":"/ˈɪmɪɡreɪt/","usIpa":"/ˈɪmɪɡreɪt/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"To move to another country to live there permanently.","vi":"nhập cư; chuyển đến sinh sống lâu dài ở một quốc gia khác"}],"examples":[{"en":"Her grandparents immigrated to Canada and opened a bakery.","vi":"Ông bà của cô ấy đã di cư sang Canada và mở một tiệm bánh.","audioKind":"ex"},{"en":"People who immigrate often contribute valuable skills to their host countries while adapting to unfamiliar social customs.","vi":"Những người nhập cư thường đóng góp các kỹ năng quý giá cho quốc gia tiếp nhận họ trong khi vẫn phải thích nghi với các phong tục xã hội xa lạ.","audioKind":"ex2"}],"collocations":[{"en":"immigrate to a country","vi":"nhập cư vào một quốc gia"},{"en":"immigrate from abroad","vi":"nhập cư từ nước ngoài"}],"wordFamily":["immigration (n.)","immigrant (n.)"],"synonyms":[],"antonyms":["emigrate"],"tipVi":"immigrate to nhấn mạnh chiều hướng nhập cư; emigrate from nhấn mạnh chiều hướng di cư ra đi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_burden', 'en-b2-15', 'burden', '/ˈbɝːdən/', 'B2', 'gánh nặng; trách nhiệm nặng nề; mối lo âu; chất gánh nặng; bắt gánh vác; làm phiền toái', 'n.', 'burdensome (adj.)', 'Đồng nghĩa: load · Trái nghĩa: relief', 'Gánh nặng đặt lên ai đó dùng a burden on someone.', 'Sharing the housework eased the burden on my father.', NULL, 'Việc chia sẻ việc nhà đã làm giảm bớt gánh nặng cho bố tôi.', '{"wordId":"burden","ukIpa":"/ˈbɜːdən/","usIpa":"/ˈbɝːdən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"a heavy load, difficult duty, or source of worry","vi":"gánh nặng; trách nhiệm nặng nề; mối lo âu"},{"pos":"v.","en":"to give someone a heavy responsibility or worry","vi":"chất gánh nặng; bắt gánh vác; làm phiền toái"}],"examples":[{"en":"Sharing the housework eased the burden on my father.","vi":"Việc chia sẻ việc nhà đã làm giảm bớt gánh nặng cho bố tôi.","audioKind":"ex"},{"en":"Affordable childcare can reduce the financial burden on families and help parents return to work.","vi":"Dịch vụ chăm sóc trẻ giá cả phải chăng có thể giảm bớt gánh nặng tài chính cho các gia đình và giúp cha mẹ quay lại làm việc.","audioKind":"ex2"}],"collocations":[{"en":"financial burden","vi":"gánh nặng tài chính"},{"en":"ease the burden","vi":"làm nhẹ gánh nặng"},{"en":"bear the burden","vi":"gánh vác trọng trách"},{"en":"be burdened with debt","vi":"mang nợ nần"}],"wordFamily":["burdensome (adj.)"],"synonyms":["load"],"antonyms":["relief"],"tipVi":"Gánh nặng đặt lên ai đó dùng a burden on someone.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_15_1', 'en-b2-15', 'Cách dùng “evil” (adj.) — xấu xa; độc ác', 'good and evil  ·  an evil intention  ·  a necessary evil', 'Mức độ nghiêm trọng mạnh hơn rất nhiều so với bad, thường liên quan đến các hành vi trái đạo đức trầm trọng.', 'Đồng nghĩa: wicked · Trái nghĩa: good', '[{"hanzi":"In the story, an evil wizard steals everyone''s dreams.","pinyin":"","meaning":"Trong câu chuyện, một phù thủy độc ác đã đánh cắp giấc mơ của tất cả mọi người."},{"hanzi":"Literature often explores the conflict between good and evil through characters who face difficult moral choices.","pinyin":"","meaning":"Văn học thường khai thác cuộc xung đột giữa thiện và ác thông qua các nhân vật phải đối mặt với những lựa chọn đạo đức khó khăn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_15_2', 'en-b2-15', 'Cách dùng “thoughtful” (adj.) — chu đáo; ân cần', 'thoughtful gesture  ·  thoughtful of someone  ·  thoughtful consideration', 'Sự chu đáo đối với ai dùng thoughtful of someone; thoughtful không nhất thiết mang ý nghĩa lo lắng.', 'Họ từ (Word Family): thought (n.), thoughtfully (adv.), thoughtfulness (n.), thoughtless (adj.) | Đồng nghĩa: considerate, reflective · Trái nghĩa: thoughtless, inconsiderate', '[{"hanzi":"It was thoughtful of you to bring an umbrella.","pinyin":"","meaning":"Bạn thật chu đáo khi mang theo ô."},{"hanzi":"Thoughtful urban planning can create public spaces that meet the needs of residents with limited mobility.","pinyin":"","meaning":"Quy hoạch đô thị chu đáo có thể tạo ra các không gian công cộng đáp ứng nhu cầu của cư dân có khả năng di chuyển hạn chế."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_15_3', 'en-b2-15', 'Cách dùng “unreasonable” (adj.) — vô lý; không phải phép, không hợp lẽ phải', 'unreasonable demands  ·  unreasonable behaviour  ·  unreasonable expectations', 'Có thể dùng để chỉ tính cách con người không hợp lẽ phải, hoặc dùng cho yêu cầu, giá cả quá mức.', 'Họ từ (Word Family): reasonable (adj.), unreasonably (adv.), reason (n.) | Đồng nghĩa: unfair, excessive · Trái nghĩa: reasonable', '[{"hanzi":"It seems unreasonable to blame you for the weather.","pinyin":"","meaning":"Thật là vô lý khi trách bạn vì thời tiết xấu."},{"hanzi":"Expecting employees to answer messages throughout their holidays places unreasonable demands on their time and harms wellbeing.","pinyin":"","meaning":"Việc yêu cầu nhân viên trả lời tin nhắn trong suốt kỳ nghỉ là một đòi hỏi quá đáng đối với thời gian của họ và gây hại cho sức khỏe tinh thần."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_15_4', 'en-b2-15', 'Cách dùng “mankind” (n.) — loài người', 'the future of mankind  ·  the history of mankind  ·  for the benefit of mankind', 'Chỉ toàn thể nhân loại chứ không chỉ giới nam; từ mang tính bao hàm hơn có thể dùng humankind.', 'Đồng nghĩa: humankind, humanity', '[{"hanzi":"This museum explores how mankind learned to grow food.","pinyin":"","meaning":"Bảo tàng này khám phá cách loài người học được cách trồng trọt lương thực."},{"hanzi":"Climate change presents a challenge to mankind that requires sustained cooperation across national borders.","pinyin":"","meaning":"Biến đổi khí hậu đặt ra một thách thức đối với nhân loại, đòi hỏi sự hợp tác bền chặt vượt qua cả biên giới các quốc gia."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_15_1', 'en-b2-15', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_15_1_1', 'ten_b2_15_1', 'chaos', 'The kitchen was in chaos after we baked together.', 'The kitchen was in chaos after we baked together.', '/ˈkeɪɑːs/', 'Căn bếp trở nên hỗn loạn sau khi chúng tôi cùng nhau làm bánh.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_15_1_2', 'ten_b2_15_1', 'obligation', 'You have no obligation to buy anything here.', 'You have no obligation to buy anything here.', '/ˌɑːblɪˈɡeɪʃən/', 'Bạn không có nghĩa vụ phải mua bất cứ thứ gì ở đây.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_15_1_3', 'ten_b2_15_1', 'thoughtful', 'It was thoughtful of you to bring an umbrella.', 'It was thoughtful of you to bring an umbrella.', '/ˈθɔːtfəl/', 'Bạn thật chu đáo khi mang theo ô.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_15_1_4', 'ten_b2_15_1', 'slang', 'My younger cousin uses slang I cannot understand.', 'My younger cousin uses slang I cannot understand.', '/slæŋ/', 'Đứa em họ nhỏ tuổi của tôi dùng những từ lóng mà tôi không thể hiểu nổi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
