INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_15_1_6', 'ten_b2_15_1', 'investigation', 'An investigation revealed why the kitchen ceiling was leaking.', 'An investigation revealed why the kitchen ceiling was leaking.', '/ɪnˌvestɪˈɡeɪʃn/', 'Một cuộc điều tra đã làm sáng tỏ lý do tại sao trần nhà bếp bị dột.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_15_1_7', 'ten_b2_15_1', 'mankind', 'This museum explores how mankind learned to grow food.', 'This museum explores how mankind learned to grow food.', '/mænˈkaɪnd/', 'Bảo tàng này khám phá cách loài người học được cách trồng trọt lương thực.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_15_1_8', 'ten_b2_15_1', 'unreasonable', 'It seems unreasonable to blame you for the weather.', 'It seems unreasonable to blame you for the weather.', '/ʌnˈriːzənəbl/', 'Thật là vô lý khi trách bạn vì thời tiết xấu.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_15_1_1', 'en-b2-15', 'ten_b2_15_1', 'listening', 'listening', 'The kitchen was in chaos after we baked together.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi nghe thông tin về căn hộ trống một cách gián tiếp qua một đồng nghiệp.","Ông bà tôi đã đón nhận việc gọi video để giữ liên lạc.","Căn bếp trở nên hỗn loạn sau khi chúng tôi cùng nhau làm bánh.","Một cuộc điều tra đã làm sáng tỏ lý do tại sao trần nhà bếp bị dột."]'::jsonb, 2, 'The kitchen was in chaos after we baked together. → Căn bếp trở nên hỗn loạn sau khi chúng tôi cùng nhau làm bánh.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_15_1_2', 'en-b2-15', 'ten_b2_15_1', 'listening', 'listening', 'You have no obligation to buy anything here.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Đề xuất này nhận được sự ủng hộ áp đảo từ những người hàng xóm của chúng tôi.","Bảo tàng này khám phá cách loài người học được cách trồng trọt lương thực.","Bạn không có nghĩa vụ phải mua bất cứ thứ gì ở đây.","Mối quan tâm lớn nhất của cô ấy là về nhà trước cơn bão."]'::jsonb, 2, 'You have no obligation to buy anything here. → Bạn không có nghĩa vụ phải mua bất cứ thứ gì ở đây.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_15_1_3', 'en-b2-15', 'ten_b2_15_1', 'listening', 'listening', 'It was thoughtful of you to bring an umbrella.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi nghe thông tin về căn hộ trống một cách gián tiếp qua một đồng nghiệp.","Việc chia sẻ việc nhà đã làm giảm bớt gánh nặng cho bố tôi.","Bạn thật chu đáo khi mang theo ô.","Tuyết dày có thể làm gián đoạn hành trình tàu hỏa của chúng ta vào ngày mai."]'::jsonb, 2, 'It was thoughtful of you to bring an umbrella. → Bạn thật chu đáo khi mang theo ô.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_15_2', 'en-b2-15', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_15_2_1', 'ten_b2_15_2', 'chaos', 'Unexpected road closures caused chaos across the city, highlighting the need for better emergency planning.', 'Unexpected road closures caused chaos across the city, highlighting the need for better emergency planning.', '/ˈkeɪɑːs/', 'Việc đóng cửa đường bất ngờ đã gây ra tình trạng hỗn loạn khắp thành phố, làm nổi bật nhu cầu cần có các kế hoạch ứng phó khẩn cấp tốt hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_15_2_2', 'ten_b2_15_2', 'obligation', 'Employers have a legal obligation to provide safe working conditions and protect employees from preventable harm.', 'Employers have a legal obligation to provide safe working conditions and protect employees from preventable harm.', '/ˌɑːblɪˈɡeɪʃən/', 'Người sử dụng lao động có nghĩa vụ pháp lý trong việc cung cấp điều kiện làm việc an toàn và bảo vệ nhân viên khỏi những tổn thương có thể phòng ngừa.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_15_2_3', 'ten_b2_15_2', 'thoughtful', 'Thoughtful urban planning can create public spaces that meet the needs of residents with limited mobility.', 'Thoughtful urban planning can create public spaces that meet the needs of residents with limited mobility.', '/ˈθɔːtfəl/', 'Quy hoạch đô thị chu đáo có thể tạo ra các không gian công cộng đáp ứng nhu cầu của cư dân có khả năng di chuyển hạn chế.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_15_2_4', 'ten_b2_15_2', 'slang', 'Although slang can strengthen group identity, excessive use may create barriers between speakers from different generations.', 'Although slang can strengthen group identity, excessive use may create barriers between speakers from different generations.', '/slæŋ/', 'Mặc dù tiếng lóng có thể củng cố bản sắc nhóm, việc lạm dụng có thể tạo ra rào cản giữa những người nói thuộc các thế hệ khác nhau.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_15_2_5', 'ten_b2_15_2', 'evil', 'Literature often explores the conflict between good and evil through characters who face difficult moral choices.', 'Literature often explores the conflict between good and evil through characters who face difficult moral choices.', '/ˈiː.vəl/', 'Văn học thường khai thác cuộc xung đột giữa thiện và ác thông qua các nhân vật phải đối mặt với những lựa chọn đạo đức khó khăn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_15_2_6', 'ten_b2_15_2', 'investigation', 'An independent investigation into river pollution could help authorities identify its causes and prevent further environmental damage.', 'An independent investigation into river pollution could help authorities identify its causes and prevent further environmental damage.', '/ɪnˌvestɪˈɡeɪʃn/', 'Một cuộc điều tra độc lập về tình trạng ô nhiễm sông ngòi có thể giúp nhà chức trách xác định nguyên nhân và ngăn chặn tổn hại môi trường tiếp diễn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_15_2_1', 'en-b2-15', 'ten_b2_15_2', 'listening', 'listening', 'Unexpected road closures caused chaos across the city, highlighting the need for better emergency planning.', NULL, 'Trong câu vừa nghe, từ “chaos” mang nghĩa nào sau đây?', '["dựa trên sự thật; thực tế","sự hỗn loạn; tình trạng lộn xộn","sự bất hạnh; vận rủi","hoàn toàn; thuần túy; chỉ vì"]'::jsonb, 1, '“chaos” (/ˈkeɪɑːs/): sự hỗn loạn; tình trạng lộn xộn. Câu đầy đủ: Unexpected road closures caused chaos across the city, highlighting the need for better emergency planning.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_15_2_2', 'en-b2-15', 'ten_b2_15_2', 'listening', 'listening', 'Employers have a legal obligation to provide safe working conditions and protect employees from preventable harm.', NULL, 'Trong câu vừa nghe, từ “obligation” mang nghĩa nào sau đây?', '["nghĩa vụ; trách nhiệm","quyền công dân; quốc tịch","nắm vững; tinh thông","nói tục; chửi thề"]'::jsonb, 0, '“obligation” (/ˌɑːblɪˈɡeɪʃən/): nghĩa vụ; trách nhiệm. Câu đầy đủ: Employers have a legal obligation to provide safe working conditions and protect employees from preventable harm.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
