INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_15_2', 'en-b2-15', NULL, 'comprehensive_test', 'listening', 'You have no obligation to buy anything here.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã quan sát những chú chim trong chuyến di trú mùa thu thường niên của chúng.","Bạn không có nghĩa vụ phải mua bất cứ thứ gì ở đây.","Xin đừng chê món ăn của tôi trước khi bạn nếm thử nó.","Du khách cởi giày trước khi bước vào chốn linh thiêng này."]'::jsonb, 1, 'You have no obligation to buy anything here. → Bạn không có nghĩa vụ phải mua bất cứ thứ gì ở đây.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_15_3', 'en-b2-15', NULL, 'comprehensive_test', 'listening', 'thoughtful', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["ngu ngốc; ngớ ngẩn","hiệu suất, hiệu quả làm việc","có tính chiếm hữu; ích kỷ trong quan hệ","chu đáo; ân cần"]'::jsonb, 3, 'thoughtful (/ˈθɔːtfəl/) → chu đáo; ân cần; trầm ngâm; suy tư sâu sắc', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_15_4', 'en-b2-15', NULL, 'comprehensive_test', 'listening', 'My younger cousin uses slang I cannot understand.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ông bà của cô ấy đã di cư sang Canada và mở một tiệm bánh.","Du khách cởi giày trước khi bước vào chốn linh thiêng này.","Việc dọn dẹp nhà bếp chung đòi hỏi sự phối hợp từ tất cả mọi người.","Đứa em họ nhỏ tuổi của tôi dùng những từ lóng mà tôi không thể hiểu nổi."]'::jsonb, 3, 'My younger cousin uses slang I cannot understand. → Đứa em họ nhỏ tuổi của tôi dùng những từ lóng mà tôi không thể hiểu nổi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_15_5', 'en-b2-15', NULL, 'comprehensive_test', 'listening', 'evil', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["hộ tống; đi kèm","xấu xa; độc ác","phân loại; xếp loại","can ngăn; làm nản lòng"]'::jsonb, 1, 'evil (/ˈiː.vəl/) → xấu xa; độc ác; tội ác; điều ác; tai họa', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_15_6', 'en-b2-15', NULL, 'comprehensive_test', 'listening', 'An investigation revealed why the kitchen ceiling was leaking.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một cuộc điều tra đã làm sáng tỏ lý do tại sao trần nhà bếp bị dột.","Hướng dẫn viên này thuộc về một bộ tộc đến từ thung lũng này.","Thật là vô lý khi trách bạn vì thời tiết xấu.","Việc chia sẻ việc nhà đã làm giảm bớt gánh nặng cho bố tôi."]'::jsonb, 0, 'An investigation revealed why the kitchen ceiling was leaking. → Một cuộc điều tra đã làm sáng tỏ lý do tại sao trần nhà bếp bị dột.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_15_7', 'en-b2-15', NULL, 'comprehensive_test', 'listening', 'mankind', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["loài người","thuộc về công dân; dân sự (không phải quân sự)","mương; rãnh thoát nước","hướng ra ngoài; ra phía ngoài"]'::jsonb, 0, 'mankind (/mænˈkaɪnd/) → loài người', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_15_8', 'en-b2-15', NULL, 'comprehensive_test', 'listening', 'It seems unreasonable to blame you for the weather.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ban công nhà cô ấy gây ấn tượng mạnh bởi những bông hoa màu vàng rực rỡ.","Căn bếp trở nên hỗn loạn sau khi chúng tôi cùng nhau làm bánh.","Bạn không có nghĩa vụ phải mua bất cứ thứ gì ở đây.","Thật là vô lý khi trách bạn vì thời tiết xấu."]'::jsonb, 3, 'It seems unreasonable to blame you for the weather. → Thật là vô lý khi trách bạn vì thời tiết xấu.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
