INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_15_18', 'en-b2-15', NULL, 'comprehensive_test', 'reading', NULL, 'Unexpected road closures caused chaos across the city, highlighting the need for better emergency planning.', 'Dựa vào câu trên, từ “chaos” có nghĩa phù hợp nhất là gì?', '["thông cảm; chia sẻ (nỗi đau, khó khăn)","bữa tiệc lớn; bữa ăn thịnh soạn","Khu ổ chuột","sự hỗn loạn; tình trạng lộn xộn"]'::jsonb, 3, 'chaos: sự hỗn loạn; tình trạng lộn xộn. Dịch cả câu: Việc đóng cửa đường bất ngờ đã gây ra tình trạng hỗn loạn khắp thành phố, làm nổi bật nhu cầu cần có các kế hoạch ứng phó khẩn cấp tốt hơn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_15_19', 'en-b2-15', NULL, 'comprehensive_test', 'reading', NULL, 'Employers have a legal obligation to provide safe working conditions and protect employees from preventable harm.', 'Dựa vào câu trên, từ “obligation” có nghĩa phù hợp nhất là gì?', '["sự mê tín; điều mê tín dị đoan","nghĩa vụ; trách nhiệm","chú thích ảnh; phụ đề","xác suất; khả năng"]'::jsonb, 1, 'obligation: nghĩa vụ; trách nhiệm. Dịch cả câu: Người sử dụng lao động có nghĩa vụ pháp lý trong việc cung cấp điều kiện làm việc an toàn và bảo vệ nhân viên khỏi những tổn thương có thể phòng ngừa.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_15_20', 'en-b2-15', NULL, 'comprehensive_test', 'reading', NULL, 'Thoughtful urban planning can create public spaces that meet the needs of residents with limited mobility.', 'Dựa vào câu trên, từ “thoughtful” có nghĩa phù hợp nhất là gì?', '["tủ có ngăn kéo để đựng quần áo (kiểu Mỹ)","chu đáo; ân cần","tổ chức; tiến hành","sự bắt chước; sự mô phỏng"]'::jsonb, 1, 'thoughtful: chu đáo; ân cần; trầm ngâm; suy tư sâu sắc. Dịch cả câu: Quy hoạch đô thị chu đáo có thể tạo ra các không gian công cộng đáp ứng nhu cầu của cư dân có khả năng di chuyển hạn chế.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_15_21', 'en-b2-15', NULL, 'comprehensive_test', 'reading', NULL, 'Although slang can strengthen group identity, excessive use may create barriers between speakers from different generations.', 'Dựa vào câu trên, từ “slang” có nghĩa phù hợp nhất là gì?', '["tiếng lóng","đi dạo; tản bộ thong thả","sự tận tụy; tinh thần cống hiến","thở dài"]'::jsonb, 0, 'slang: tiếng lóng. Dịch cả câu: Mặc dù tiếng lóng có thể củng cố bản sắc nhóm, việc lạm dụng có thể tạo ra rào cản giữa những người nói thuộc các thế hệ khác nhau.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_15_22', 'en-b2-15', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đáng chú ý; nổi bật; rõ rệt”', '["banner","transition","notable","warehouse"]'::jsonb, 2, 'đáng chú ý; nổi bật; rõ rệt → notable (/ˈnoʊtəbl/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_15_23', 'en-b2-15', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nhập cư; chuyển đến sinh sống lâu dài ở một quốc gia khác”', '["terminal","harsh","implement","immigrate"]'::jsonb, 3, 'nhập cư; chuyển đến sinh sống lâu dài ở một quốc gia khác → immigrate (/ˈɪmɪɡreɪt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_15_24', 'en-b2-15', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “gánh nặng; trách nhiệm nặng nề; mối lo âu”', '["appreciation","burden","deforestation","insight"]'::jsonb, 1, 'gánh nặng; trách nhiệm nặng nề; mối lo âu → burden (/ˈbɝːdən/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-16', 'en', 'Bài 16: Xã hội & Cộng đồng (9) - CEFR B2', 'CEFR B2', 'B2 · Xã hội', '26 từ vựng Tiếng Anh CEFR B2 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4016, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lad', 'en-b2-16', 'lad', '/læd/', 'B2', 'chàng trai; cậu thanh niên', 'n.', 'laddish (adj.)', 'Đồng nghĩa: boy, young man', 'Thuộc văn nói Anh-Anh; văn viết trang trọng nên dùng boy hoặc young man.', 'A friendly lad helped us carry the bags.', NULL, 'Một cậu thanh niên thân thiện đã giúp chúng tôi xách túi đồ.', '{"wordId":"lad","ukIpa":"/læd/","usIpa":"/læd/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"A boy or young man, especially in informal British English.","vi":"chàng trai; cậu thanh niên"}],"examples":[{"en":"A friendly lad helped us carry the bags.","vi":"Một cậu thanh niên thân thiện đã giúp chúng tôi xách túi đồ.","audioKind":"ex"},{"en":"As a young lad, the novelist experienced rural poverty, which later became a central theme in his work.","vi":"Thuở nhỏ, nhà văn này từng trải qua cảnh nghèo khó nơi thôn quê, điều sau này đã trở thành chủ đề cốt lõi trong các tác phẩm của ông.","audioKind":"ex2"}],"collocations":[{"en":"a young lad","vi":"một thiếu niên trẻ"},{"en":"a local lad","vi":"một thanh niên địa phương"},{"en":"a teenage lad","vi":"một cậu thiếu niên"}],"wordFamily":["laddish (adj.)"],"synonyms":["boy","young man"],"antonyms":[],"tipVi":"Thuộc văn nói Anh-Anh; văn viết trang trọng nên dùng boy hoặc young man.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_burial', 'en-b2-16', 'burial', '/ˈberiəl/', 'B2', 'sự chôn cất; lễ an táng', 'n.', 'bury (v.)', 'Đồng nghĩa: interment', 'burial nhấn mạnh việc chôn cất xuống đất; funeral chung chung chỉ buổi lễ tang.', 'The family gathered quietly for the burial yesterday.', NULL, 'Gia đình đã quây quần lặng lẽ trong lễ an táng vào ngày hôm qua.', '{"wordId":"burial","ukIpa":"/ˈberiəl/","usIpa":"/ˈberiəl/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"the act or ceremony of placing a dead body underground","vi":"sự chôn cất; lễ an táng"}],"examples":[{"en":"The family gathered quietly for the burial yesterday.","vi":"Gia đình đã quây quần lặng lẽ trong lễ an táng vào ngày hôm qua.","audioKind":"ex"},{"en":"Ancient burial sites provide valuable evidence about the beliefs and social structures of past communities.","vi":"Các di tích mai táng cổ đại cung cấp bằng chứng quý giá về niềm tin và cấu trúc xã hội của các cộng đồng trong quá khứ.","audioKind":"ex2"}],"collocations":[{"en":"burial site","vi":"di tích mai táng"},{"en":"burial ground","vi":"bãi tha ma"},{"en":"burial customs","vi":"tục lệ ma chay"}],"wordFamily":["bury (v.)"],"synonyms":["interment"],"antonyms":[],"tipVi":"burial nhấn mạnh việc chôn cất xuống đất; funeral chung chung chỉ buổi lễ tang.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_restricted', 'en-b2-16', 'restricted', '/rɪˈstrɪktɪd/', 'B2', 'bị hạn chế; có giới hạn; chỉ dành riêng cho những người có thẩm quyền', 'adj.', 'restrict (v.), restriction (n.), restrictive (adj.), unrestricted (adj.)', 'Đồng nghĩa: limited, controlled · Trái nghĩa: unrestricted, unlimited', 'restricted to nghĩa là "chỉ giới hạn ở"; đồng thời là phân từ quá khứ của restrict.', 'Parking is restricted here during the busy morning hours.', NULL, 'Việc đỗ xe bị hạn chế ở đây trong những giờ cao điểm buổi sáng.', '{"wordId":"restricted","ukIpa":"/rɪˈstrɪktɪd/","usIpa":"/rɪˈstrɪktɪd/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"limited in amount, range, or freedom","vi":"bị hạn chế; có giới hạn"},{"pos":"adj.","en":"available or open only to people with permission","vi":"chỉ dành riêng cho những người có thẩm quyền"}],"examples":[{"en":"Parking is restricted here during the busy morning hours.","vi":"Việc đỗ xe bị hạn chế ở đây trong những giờ cao điểm buổi sáng.","audioKind":"ex"},{"en":"Restricted access to affordable healthcare can worsen existing inequalities between wealthy communities and disadvantaged rural populations.","vi":"Quyền tiếp cận dịch vụ y tế giá cả phải chăng bị hạn chế có thể làm trầm trọng thêm tình trạng bất bình đẳng hiện có giữa các cộng đồng giàu có và nhóm dân cư nông thôn có hoàn cảnh khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"restricted access","vi":"quyền truy cập bị hạn chế"},{"en":"a restricted area","vi":"khu vực hạn chế"},{"en":"restricted movement","vi":"sự di chuyển bị hạn chế"},{"en":"restricted to members","vi":"chỉ dành riêng cho hội viên"}],"wordFamily":["restrict (v.)","restriction (n.)","restrictive (adj.)","unrestricted (adj.)"],"synonyms":["limited","controlled"],"antonyms":["unrestricted","unlimited"],"tipVi":"restricted to nghĩa là \"chỉ giới hạn ở\"; đồng thời là phân từ quá khứ của restrict.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_robbery', 'en-b2-16', 'robbery', '/ˈrɑːbəri/', 'B2', 'vụ cướp, nạn cướp bóc', 'n.', 'rob (v.), robber (n.)', NULL, 'robbery liên quan đến bạo lực hoặc đe dọa; theft mang nghĩa ăn cắp thông thường.', 'The shop closed early after a robbery yesterday.', NULL, 'Cửa hàng đã đóng cửa sớm sau một vụ cướp ngày hôm qua.', '{"wordId":"robbery","ukIpa":"/ˈrɒbəri/","usIpa":"/ˈrɑːbəri/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"Stealing from a person or place using force or threats.","vi":"vụ cướp, nạn cướp bóc"}],"examples":[{"en":"The shop closed early after a robbery yesterday.","vi":"Cửa hàng đã đóng cửa sớm sau một vụ cướp ngày hôm qua.","audioKind":"ex"},{"en":"Better street lighting may reduce the risk of robbery and help residents feel safer after dark.","vi":"Hệ thống chiếu sáng đường phố tốt hơn có thể làm giảm nguy cơ cướp giật và giúp cư dân cảm thấy an toàn hơn sau khi trời tối.","audioKind":"ex2"}],"collocations":[{"en":"commit a robbery","vi":"phạm tội cướp bóc"},{"en":"armed robbery","vi":"vụ cướp có vũ trang"},{"en":"bank robbery","vi":"vụ cướp ngân hàng"},{"en":"attempted robbery","vi":"âmደት cướp"}],"wordFamily":["rob (v.)","robber (n.)"],"synonyms":[],"antonyms":[],"tipVi":"robbery liên quan đến bạo lực hoặc đe dọa; theft mang nghĩa ăn cắp thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dispute', 'en-b2-16', 'dispute', '/dɪˈspjuːt/', 'B2', 'cuộc tranh chấp; sự tranh cãi; tranh cãi; bác bỏ; đặt nghi vấn; tranh chấp; tranh giành', 'n.', 'disputed (adj.), disputable (adj.), indisputable (adj.)', 'Đồng nghĩa: disagreement, contest · Trái nghĩa: agreement', 'dispute a claim mang nghĩa là đặt nghi vấn về một tuyên bố, không phải là thảo luận về tuyên bố đó.', 'Our neighbours settled their dispute over the garden fence.', NULL, 'Những người hàng xóm của chúng tôi đã giải quyết xong tranh chấp về hàng rào khu vườn.', '{"wordId":"dispute","ukIpa":"/dɪˈspjuːt/","usIpa":"/dɪˈspjuːt/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"a serious disagreement between people or groups","vi":"cuộc tranh chấp; sự tranh cãi"},{"pos":"v.","en":"to question whether something is true or correct","vi":"tranh cãi; bác bỏ; đặt nghi vấn"},{"pos":"v.","en":"to argue about something or compete to control it","vi":"tranh chấp; tranh giành"}],"examples":[{"en":"Our neighbours settled their dispute over the garden fence.","vi":"Những người hàng xóm của chúng tôi đã giải quyết xong tranh chấp về hàng rào khu vườn.","audioKind":"ex"},{"en":"Independent experts dispute the claim that building more roads will permanently reduce traffic congestion.","vi":"Các chuyên gia độc lập đặt nghi vấn về quan điểm cho rằng việc xây dựng thêm đường xá sẽ giải quyết vĩnh viễn tình trạng ùn tắc giao thông.","audioKind":"ex2"}],"collocations":[{"en":"settle a dispute","vi":"giải quyết tranh chấp"},{"en":"a dispute over pay","vi":"tranh chấp tiền lương"},{"en":"dispute a claim","vi":"tranh cãi về một luận điểm"},{"en":"in dispute","vi":"đang tranh chấp"}],"wordFamily":["disputed (adj.)","disputable (adj.)","indisputable (adj.)"],"synonyms":["disagreement","contest"],"antonyms":["agreement"],"tipVi":"dispute a claim mang nghĩa là đặt nghi vấn về một tuyên bố, không phải là thảo luận về tuyên bố đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hospitable', 'en-b2-16', 'hospitable', '/hɑːˈspɪtəbəl/', 'B2', 'hiếu khách; niềm nở, chu đáo với khách; thích hợp; ôn hòa, đáng sống (khí hậu, môi trường)', 'adj.', 'hospitality (n.), hospitably (adv.), inhospitable (adj.)', 'Đồng nghĩa: welcoming, friendly · Trái nghĩa: inhospitable, unwelcoming', 'Khi chỉ con người thì dịch là "hieu khach"; khi chỉ môi trường thì dịch là "thich hop de sinh song".', 'Our hospitable neighbours invited us in for warm soup.', NULL, 'Những người hàng xóm hiếu khách của chúng tôi đã mời chúng tôi vào nhà để ăn một bát súp nóng.', '{"wordId":"hospitable","ukIpa":"/hɒˈspɪtəbl/","usIpa":"/hɑːˈspɪtəbəl/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Friendly and generous towards guests or visitors.","vi":"hiếu khách; niềm nở, chu đáo với khách"},{"pos":"adj.","en":"Providing suitable conditions for people, animals, or plants to live.","vi":"thích hợp; ôn hòa, đáng sống (khí hậu, môi trường)"}],"examples":[{"en":"Our hospitable neighbours invited us in for warm soup.","vi":"Những người hàng xóm hiếu khách của chúng tôi đã mời chúng tôi vào nhà để ăn một bát súp nóng.","audioKind":"ex"},{"en":"A hospitable climate and reliable water supplies have encouraged human settlement in this region for centuries.","vi":"Khí hậu ôn hòa và nguồn nước ổn định đã thu hút con người đến định cư ở vùng này trong nhiều thế kỷ.","audioKind":"ex2"}],"collocations":[{"en":"a hospitable host","vi":"chủ nhà hiếu khách"},{"en":"hospitable to visitors","vi":"tiếp đón khách khứa niềm nở"},{"en":"a hospitable environment","vi":"môi trường thích hợp cho sự sống"}],"wordFamily":["hospitality (n.)","hospitably (adv.)","inhospitable (adj.)"],"synonyms":["welcoming","friendly"],"antonyms":["inhospitable","unwelcoming"],"tipVi":"Khi chỉ con người thì dịch là \"hieu khach\"; khi chỉ môi trường thì dịch là \"thich hop de sinh song\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_civil', 'en-b2-16', 'civil', '/ˈsɪvəl/', 'B2', 'thuộc về công dân; dân sự (không phải quân sự); thuộc về pháp luật dân sự (không phải hình sự); lịch sự; nhã nhặn', 'adj.', 'civility (n.), civilly (adv.), uncivil (adj.)', NULL, 'civil law chỉ luật dân sự; trong khi civil war có nghĩa là nội chiến.', 'The airport handles both military and civil aircraft.', NULL, 'Sân bay này phục vụ cả máy bay quân sự lẫn máy bay dân dụng.', '{"wordId":"civil","ukIpa":"/ˈsɪvəl/","usIpa":"/ˈsɪvəl/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Relating to citizens or ordinary society rather than the military.","vi":"thuộc về công dân; dân sự (không phải quân sự)"},{"pos":"adj.","en":"Relating to private legal disputes rather than criminal offences.","vi":"thuộc về pháp luật dân sự (không phải hình sự)"},{"pos":"adj.","en":"Polite and respectful, though not necessarily friendly.","vi":"lịch sự; nhã nhặn"}],"examples":[{"en":"The airport handles both military and civil aircraft.","vi":"Sân bay này phục vụ cả máy bay quân sự lẫn máy bay dân dụng.","audioKind":"ex"},{"en":"Protecting civil rights requires accessible legal services and public institutions that treat all citizens fairly.","vi":"Việc bảo vệ quyền công dân đòi hỏi các dịch vụ pháp lý dễ tiếp cận và các thể viện công cộng đối xử công bằng với mọi công dân.","audioKind":"ex2"}],"collocations":[{"en":"civil rights","vi":"quyền công dân"},{"en":"civil aviation","vi":"hàng không dân dụng"},{"en":"civil law","vi":"luật dân sự"},{"en":"remain civil","vi":"giữ thái độ lịch sự"}],"wordFamily":["civility (n.)","civilly (adv.)","uncivil (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"civil law chỉ luật dân sự; trong khi civil war có nghĩa là nội chiến.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_famine', 'en-b2-16', 'famine', '/ˈfæmɪn/', 'B2', 'nạn đói; nạn thiếu lương thực trầm trọng', 'n.', NULL, NULL, 'Từ famine chỉ tình trạng thiếu hụt lương thực quy mô lớn; trong khi hunger dùng cho cá nhân thấy đói.', 'Our community sent food to families affected by famine.', NULL, 'Cộng đồng của chúng tôi đã gửi thực phẩm đến các gia đình bị ảnh hưởng bởi nạn đói.', '{"wordId":"famine","ukIpa":"/ˈfæmɪn/","usIpa":"/ˈfæmɪn/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"a severe shortage of food affecting many people","vi":"nạn đói; nạn thiếu lương thực trầm trọng"}],"examples":[{"en":"Our community sent food to families affected by famine.","vi":"Cộng đồng của chúng tôi đã gửi thực phẩm đến các gia đình bị ảnh hưởng bởi nạn đói.","audioKind":"ex"},{"en":"Prolonged drought can lead to famine when farming communities lack reliable irrigation systems and emergency food reserves.","vi":"Hạn hán kéo dài có thể dẫn đến nạn đói khi các cộng đồng nông nghiệp thiếu hệ thống tưới tiêu đáng tin cậy và dự trữ lương thực khẩn cấp.","audioKind":"ex2"}],"collocations":[{"en":"widespread famine","vi":"nạn đói diện rộng"},{"en":"famine relief","vi":"cứu trợ nạn đói"},{"en":"prevent famine","vi":"ngăn chặn nạn đói"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Từ famine chỉ tình trạng thiếu hụt lương thực quy mô lớn; trong khi hunger dùng cho cá nhân thấy đói.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_distribute', 'en-b2-16', 'distribute', '/dɪˈstrɪbjuːt/', 'B2', 'phân phát; phân phối; phân bố; rải đều', 'v.', 'distribution (n.), distributor (n.)', 'Đồng nghĩa: hand out, allocate · Trái nghĩa: collect', 'distribute A to B có nghĩa là "phân phát A cho B".', 'Volunteers distribute fresh fruit outside the community centre every Friday.', NULL, 'Các tình nguyện viên phát trái cây tươi bên ngoài trung tâm cộng đồng vào mỗi thứ Sáu.', '{"wordId":"distribute","ukIpa":"/dɪˈstrɪbjuːt/","usIpa":"/dɪˈstrɪbjuːt/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"to give or deliver something to several people or places","vi":"phân phát; phân phối"},{"pos":"v.","en":"to spread something over an area","vi":"phân bố; rải đều"}],"examples":[{"en":"Volunteers distribute fresh fruit outside the community centre every Friday.","vi":"Các tình nguyện viên phát trái cây tươi bên ngoài trung tâm cộng đồng vào mỗi thứ Sáu.","audioKind":"ex"},{"en":"Governments must distribute healthcare resources fairly so that rural communities receive the same quality of care as urban residents.","vi":"Chính phủ phải phân bổ nguồn lực y tế một cách công bằng để các cộng đồng nông thôn nhận được chất lượng chăm sóc tương đương với cư dân thành thị.","audioKind":"ex2"}],"collocations":[{"en":"distribute food","vi":"phát lương thực"},{"en":"distribute resources","vi":"phân bổ nguồn lực"},{"en":"evenly distributed","vi":"phân bố đều"},{"en":"widely distributed","vi":"phân bố rộng rãi"}],"wordFamily":["distribution (n.)","distributor (n.)"],"synonyms":["hand out","allocate"],"antonyms":["collect"],"tipVi":"distribute A to B có nghĩa là \"phân phát A cho B\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_courtesy', 'en-b2-16', 'courtesy', '/ˈkɝːtəsi/', 'B2', 'lịch sự; nhã nhặn; hành động lịch thiệp; ân huệ; miễn phí', 'n.', 'courteous (adj.), courteously (adv.)', 'Đồng nghĩa: politeness, civility · Trái nghĩa: rudeness', 'courtesy of dùng để chỉ việc được bên nào đó tài trợ hoặc cho phép sử dụng.', 'She treated every guest with courtesy, even when tired.', NULL, 'Cô ấy đối xử với mọi vị khách một cách lịch sự, ngay cả khi rất mệt mỏi.', '{"wordId":"courtesy","ukIpa":"/ˈkɜːtəsi/","usIpa":"/ˈkɝːtəsi/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"polite behaviour showing respect and consideration for others","vi":"lịch sự; nhã nhặn"},{"pos":"n.","en":"a polite or helpful act","vi":"hành động lịch thiệp; ân huệ"},{"pos":"adj.","en":"provided free to customers as a service","vi":"miễn phí"}],"examples":[{"en":"She treated every guest with courtesy, even when tired.","vi":"Cô ấy đối xử với mọi vị khách một cách lịch sự, ngay cả khi rất mệt mỏi.","audioKind":"ex"},{"en":"Showing courtesy towards fellow passengers can make public transport more pleasant and accessible for everyone.","vi":"Ứng xử lịch thiệp với các hành khách khác có thể làm cho phương tiện giao thông công cộng trở nên dễ chịu và thuận tiện hơn cho tất cả mọi người.","audioKind":"ex2"}],"collocations":[{"en":"common courtesy","vi":"phép lịch sự tối thiểu"},{"en":"as a courtesy","vi":"vì phép lịch sự"},{"en":"courtesy bus","vi":"xe buýt miễn phí của khách sạn"},{"en":"courtesy of","vi":"sự tài trợ bởi"}],"wordFamily":["courteous (adj.)","courteously (adv.)"],"synonyms":["politeness","civility"],"antonyms":["rudeness"],"tipVi":"courtesy of dùng để chỉ việc được bên nào đó tài trợ hoặc cho phép sử dụng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_contribute', 'en-b2-16', 'contribute', '/kənˈtrɪbjuːt/', 'B2', 'đóng góp; góp phần; gây ra; góp phần tạo nên; đóng góp bài viết; viết bài', 'v.', 'contribution (n.), contributor (n.), contributory (adj.)', NULL, 'Từ to trong contribute to là giới từ, theo sau là danh từ hoặc danh động từ.', 'Everyone contributed a dish to our shared evening meal.', NULL, 'Mọi người đều đóng góp một món ăn cho bữa tối chung của chúng tôi.', '{"wordId":"contribute","ukIpa":"/kənˈtrɪbjuːt/","usIpa":"/kənˈtrɪbjuːt/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"To give money, time, or effort towards a shared purpose","vi":"đóng góp; góp phần"},{"pos":"v.","en":"To help cause a particular result","vi":"gây ra; góp phần tạo nên"},{"pos":"v.","en":"To write material for a publication or website","vi":"đóng góp bài viết; viết bài"}],"examples":[{"en":"Everyone contributed a dish to our shared evening meal.","vi":"Mọi người đều đóng góp một món ăn cho bữa tối chung của chúng tôi.","audioKind":"ex"},{"en":"Limited access to affordable housing can contribute to social inequality and force workers to accept longer commutes.","vi":"Khả năng tiếp cận nhà ở giá rẻ hạn chế có thể làm gia tăng bất bình đẳng xã hội và buộc người lao động phải chấp nhận thời gian di chuyển dài hơn.","audioKind":"ex2"}],"collocations":[{"en":"contribute to a discussion","vi":"tham gia thảo luận"},{"en":"contribute to economic growth","vi":"góp phần thúc đẩy tăng trưởng kinh tế"},{"en":"contribute funds","vi":"đóng góp quỹ"},{"en":"contribute an article","vi":"viết một bài báo"}],"wordFamily":["contribution (n.)","contributor (n.)","contributory (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ to trong contribute to là giới từ, theo sau là danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_absolute', 'en-b2-16', 'absolute', '/ˈæbsəluːt/', 'B2', 'hoàn toàn; tuyệt đối; không bị giới hạn', 'adj.', 'absolutely (adv.)', 'Đồng nghĩa: complete, total · Trái nghĩa: partial, relative', 'Thường chỉ mức độ đã đạt tới cực hạn, thông thường không dùng với từ very.', 'The room fell into absolute silence when she entered.', NULL, 'Căn phòng chìm vào sự im lặng tuyệt đối khi cô ấy bước vào.', '{"wordId":"absolute","ukIpa":"/ˈæbsəluːt/","usIpa":"/ˈæbsəluːt/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"complete or total","vi":"hoàn toàn; tuyệt đối"},{"pos":"adj.","en":"not limited by conditions, rules, or other authorities","vi":"tuyệt đối; không bị giới hạn"}],"examples":[{"en":"The room fell into absolute silence when she entered.","vi":"Căn phòng chìm vào sự im lặng tuyệt đối khi cô ấy bước vào.","audioKind":"ex"},{"en":"Giving any single institution absolute power can weaken accountability and reduce public trust in government.","vi":"Việc trao quyền lực tuyệt đối cho bất kỳ tổ chức nào cũng có thể làm suy yếu cơ chế giải trình và giảm niềm tin của công chúng vào chính phủ.","audioKind":"ex2"}],"collocations":[{"en":"absolute silence","vi":"sự im lặng tuyệt đối"},{"en":"absolute certainty","vi":"sự chắc chắn tuyệt đối"},{"en":"absolute power","vi":"quyền lực tuyệt đối"},{"en":"an absolute necessity","vi":"một nhu cầu thiết yếu tuyệt đối"}],"wordFamily":["absolutely (adv.)"],"synonyms":["complete","total"],"antonyms":["partial","relative"],"tipVi":"Thường chỉ mức độ đã đạt tới cực hạn, thông thường không dùng với từ very.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_universal', 'en-b2-16', 'universal', '/ˌjuːnɪˈvɝːsəl/', 'B2', 'phổ biến; toàn cục; chung cho tất cả; vạn năng; dùng chung cho nhiều thiết bị khác nhau', 'adj.', 'universally (adv.), universality (n.)', NULL, 'Chỉ tính chất áp dụng cho tất cả hoặc tồn tại phổ biến, sắc thái ý nghĩa thường mạnh hơn từ common.', 'The new playground won universal approval from local families.', NULL, 'Khu vui chơi mới đã nhận được sự đồng thuận tuyệt đối từ các gia đình trong vùng.', '{"wordId":"universal","ukIpa":"/ˌjuːnɪˈvɜːsəl/","usIpa":"/ˌjuːnɪˈvɝːsəl/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Existing everywhere or applying to everyone in a group.","vi":"phổ biến; toàn cục; chung cho tất cả"},{"pos":"adj.","en":"Suitable for use with many different devices or situations.","vi":"vạn năng; dùng chung cho nhiều thiết bị khác nhau"}],"examples":[{"en":"The new playground won universal approval from local families.","vi":"Khu vui chơi mới đã nhận được sự đồng thuận tuyệt đối từ các gia đình trong vùng.","audioKind":"ex"},{"en":"Universal access to affordable healthcare can reduce inequality and improve the overall wellbeing of a population.","vi":"Quyền tiếp cận dịch vụ y tế phổ cập với mức giá phải chăng có thể làm giảm bất bình đẳng và cải thiện phúc lợi chung của toàn dân.","audioKind":"ex2"}],"collocations":[{"en":"universal access","vi":"quyền tiếp cận phổ cập"},{"en":"universal healthcare","vi":"y tế toàn dân"},{"en":"universal appeal","vi":"sức hút phổ biến"},{"en":"universal charger","vi":"bộ sạc đa năng"}],"wordFamily":["universally (adv.)","universality (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ tính chất áp dụng cho tất cả hoặc tồn tại phổ biến, sắc thái ý nghĩa thường mạnh hơn từ common.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_companion', 'en-b2-16', 'companion', '/kəmˈpænjən/', 'B2', 'bạn đồng hành; người bầu bạn; thú cưng bầu bạn; sách hướng dẫn; cẩm nang tham khảo', 'n.', 'companionship (n.), companionable (adj.)', 'Đồng nghĩa: partner, friend', 'companion nhấn mạnh sự đồng hành, không nhất thiết phải là bạn thân, cũng có thể chỉ động vật.', 'My dog has been a loyal companion for years.', NULL, 'Con chó của tôi đã là người bạn trung thành trong nhiều năm.', '{"wordId":"companion","ukIpa":"/kəmˈpænjən/","usIpa":"/kəmˈpænjən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"a person or animal that spends time with someone","vi":"bạn đồng hành; người bầu bạn; thú cưng bầu bạn"},{"pos":"n.","en":"a book providing useful information about a particular subject","vi":"sách hướng dẫn; cẩm nang tham khảo"}],"examples":[{"en":"My dog has been a loyal companion for years.","vi":"Con chó của tôi đã là người bạn trung thành trong nhiều năm.","audioKind":"ex"},{"en":"For older adults living alone, a companion can reduce loneliness and encourage regular participation in community activities.","vi":"Đối với người cao tuổi sống một mình, một người bạn đồng hành có thể làm giảm bớt cảm giác cô đơn và khuyến khích họ thường xuyên tham gia các hoạt động cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"a travelling companion","vi":"bạn đồng hành trong các chuyến đi"},{"en":"a loyal companion","vi":"người bạn trung thành"},{"en":"a companion to literature","vi":"sách hướng dẫn văn học"}],"wordFamily":["companionship (n.)","companionable (adj.)"],"synonyms":["partner","friend"],"antonyms":[],"tipVi":"companion nhấn mạnh sự đồng hành, không nhất thiết phải là bạn thân, cũng có thể chỉ động vật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_etiquette', 'en-b2-16', 'etiquette', '/ˈetɪkət/', 'B2', 'phép tắc xã giao; quy tắc ứng xử', 'n.', NULL, 'Đồng nghĩa: protocol, manners', 'Thường là danh từ không đếm được; chỉ các quy tắc lễ nghi chung, không dùng cho một hành động đơn lẻ.', 'My aunt taught me basic table etiquette before dinner.', NULL, 'Dì của tôi đã dạy tôi các quy tắc ứng xử cơ bản trên bàn ăn trước bữa tối.', '{"wordId":"etiquette","ukIpa":"/ˈetɪket/","usIpa":"/ˈetɪkət/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"Accepted rules of polite behaviour in particular social situations.","vi":"phép tắc xã giao; quy tắc ứng xử"}],"examples":[{"en":"My aunt taught me basic table etiquette before dinner.","vi":"Dì của tôi đã dạy tôi các quy tắc ứng xử cơ bản trên bàn ăn trước bữa tối.","audioKind":"ex"},{"en":"Learning local etiquette can help international students avoid misunderstandings and build stronger relationships with their hosts.","vi":"Việc tìm hiểu phép tắc xã giao địa phương có thể giúp các du học sinh tránh được những hiểu lầm và xây dựng mối quan hệ tốt đẹp hơn với người dân bản địa.","audioKind":"ex2"}],"collocations":[{"en":"table etiquette","vi":"phép tắc trên bàn ăn"},{"en":"business etiquette","vi":"quy tắc ứng xử trong kinh doanh"},{"en":"social etiquette","vi":"phép xã giao"},{"en":"rules of etiquette","vi":"quy tắc lễ nghi"}],"wordFamily":[],"synonyms":["protocol","manners"],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; chỉ các quy tắc lễ nghi chung, không dùng cho một hành động đơn lẻ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_innocent', 'en-b2-16', 'innocent', '/ˈɪnəsənt/', 'B2', 'vô tội; không có tội; ngây thơ; trong sáng; khờ khạo; vô hại; không có ý xấu', 'adj.', 'innocence (n.), innocently (adv.)', 'Đồng nghĩa: blameless, naive · Trái nghĩa: guilty', 'Để nói không phạm tội gì, dùng cấu trúc innocent of chứ không dùng innocent from.', 'The broken vase was not his fault; he was innocent.', NULL, 'Chiếc bình vỡ không phải lỗi của cậu ấy; cậu ấy hoàn toàn vô tội.', '{"wordId":"innocent","ukIpa":"/ˈɪnəsənt/","usIpa":"/ˈɪnəsənt/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Not responsible for a crime or wrongdoing.","vi":"vô tội; không có tội"},{"pos":"adj.","en":"Lacking experience or knowledge of unpleasant aspects of life.","vi":"ngây thơ; trong sáng; khờ khạo"},{"pos":"adj.","en":"Not intended to hurt, offend, or cause trouble.","vi":"vô hại; không có ý xấu"}],"examples":[{"en":"The broken vase was not his fault; he was innocent.","vi":"Chiếc bình vỡ không phải lỗi của cậu ấy; cậu ấy hoàn toàn vô tội.","audioKind":"ex"},{"en":"A fair legal system must protect innocent people while ensuring that those responsible for crimes face justice.","vi":"Một hệ thống pháp luật công bằng phải bảo vệ những người vô tội đồng thời đảm bảo những kẻ phạm tội phải chịu sự trừng phạt của pháp luật.","audioKind":"ex2"}],"collocations":[{"en":"innocent of a crime","vi":"vô can trong một vụ án"},{"en":"innocent victims","vi":"những nạn nhân vô tội"},{"en":"an innocent mistake","vi":"một lỗi lầm vô ý"}],"wordFamily":["innocence (n.)","innocently (adv.)"],"synonyms":["blameless","naive"],"antonyms":["guilty"],"tipVi":"Để nói không phạm tội gì, dùng cấu trúc innocent of chứ không dùng innocent from.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bias', 'en-b2-16', 'bias', '/ˈbaɪəs/', 'B2', 'sự thiên vị; thành kiến; độ lệch; sai lệch hệ thống; làm lệch lạc; gây thiên vị', 'n.', 'biased (adj.), unbiased (adj.)', 'Đồng nghĩa: prejudice, partiality · Trái nghĩa: impartiality', 'Bias against dùng để chỉ sự thành kiến chống lại ai; in favour of dùng để chỉ sự thiên vị.', 'The referee showed clear bias towards the home team.', NULL, 'Trọng tài đã thể hiện rõ sự thiên vị đối với đội chủ nhà.', '{"wordId":"bias","ukIpa":"/ˈbaɪəs/","usIpa":"/ˈbaɪəs/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"an unfair preference for or against a person or group","vi":"sự thiên vị; thành kiến"},{"pos":"n.","en":"a systematic distortion that makes research results less accurate","vi":"độ lệch; sai lệch hệ thống"},{"pos":"v.","en":"to unfairly influence someone''s judgement or a study''s results","vi":"làm lệch lạc; gây thiên vị"}],"examples":[{"en":"The referee showed clear bias towards the home team.","vi":"Trọng tài đã thể hiện rõ sự thiên vị đối với đội chủ nhà.","audioKind":"ex"},{"en":"Researchers should select participants carefully to minimise bias and ensure that their findings represent the wider population.","vi":"Các nhà nghiên cứu nên lựa chọn người tham gia cẩn thận để giảm thiểu sai lệch và đảm bảo kết quả nghiên cứu mang tính đại diện cho cộng đồng rộng lớn hơn.","audioKind":"ex2"}],"collocations":[{"en":"bias against","vi":"sự thành kiến chống lại"},{"en":"gender bias","vi":"thiên vị giới tính"},{"en":"sampling bias","vi":"sai lệch chọn mẫu"},{"en":"unconscious bias","vi":"thành kiến vô thức"}],"wordFamily":["biased (adj.)","unbiased (adj.)"],"synonyms":["prejudice","partiality"],"antonyms":["impartiality"],"tipVi":"Bias against dùng để chỉ sự thành kiến chống lại ai; in favour of dùng để chỉ sự thiên vị.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_respective', 'en-b2-16', 'respective', '/rɪˈspektɪv/', 'B2', 'tương ứng; riêng của mỗi người/vật', 'adj.', 'respectively (adv.)', NULL, 'Thường đứng trước danh từ số nhiều; tránh nhầm lẫn với từ respectful.', 'After dinner, the children returned to their respective rooms.', NULL, 'Sau bữa tối, lũ trẻ lần lượt trở về phòng riêng của chúng.', '{"wordId":"respective","ukIpa":"/rɪˈspektɪv/","usIpa":"/rɪˈspektɪv/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Belonging separately to each person or thing already mentioned.","vi":"tương ứng; riêng của mỗi người/vật"}],"examples":[{"en":"After dinner, the children returned to their respective rooms.","vi":"Sau bữa tối, lũ trẻ lần lượt trở về phòng riêng của chúng.","audioKind":"ex"},{"en":"Schools and families should understand their respective responsibilities in supporting children''s emotional development and academic progress.","vi":"Nhà trường và gia đình nên hiểu rõ trách nhiệm tương ứng của mình trong việc hỗ trợ sự phát triển cảm xúc và tiến bộ học tập của trẻ em.","audioKind":"ex2"}],"collocations":[{"en":"respective roles","vi":"vai trò riêng"},{"en":"respective responsibilities","vi":"trách nhiệm tương ứng"},{"en":"respective countries","vi":"quốc gia của mỗi bên"}],"wordFamily":["respectively (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường đứng trước danh từ số nhiều; tránh nhầm lẫn với từ respectful.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_feminine', 'en-b2-16', 'feminine', '/ˈfemənɪn/', 'B2', 'mang nét nữ tính; dịu dàng; thuộc giống cái (về mặt ngữ pháp)', 'adj.', 'femininity (n)', 'Trái nghĩa: masculine', 'feminine nhấn mạnh khí chất hoặc giới tính ngữ pháp; female nhấn mạnh giới tính sinh học.', 'She chose a feminine blouse with delicate lace sleeves.', NULL, 'Cô ấy chọn một chiếc áo kiểu nữ tính với phần tay áo ren tinh tế.', '{"wordId":"feminine","ukIpa":"/ˈfemənɪn/","usIpa":"/ˈfemənɪn/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Having qualities or styles traditionally associated with women.","vi":"mang nét nữ tính; dịu dàng"},{"pos":"adj.","en":"Belonging to a grammatical gender class often associated with females.","vi":"thuộc giống cái (về mặt ngữ pháp)"}],"examples":[{"en":"She chose a feminine blouse with delicate lace sleeves.","vi":"Cô ấy chọn một chiếc áo kiểu nữ tính với phần tay áo ren tinh tế.","audioKind":"ex"},{"en":"Advertising often reinforces narrow ideas about feminine appearance, which can influence how young people perceive themselves.","vi":"Quảng cáo thường củng cố những quan niệm hạn hẹp về vẻ bề ngoài nữ tính, điều này có thể ảnh hưởng đến cách giới trẻ nhìn nhận bản thân.","audioKind":"ex2"}],"collocations":[{"en":"feminine style","vi":"phong cách nữ tính"},{"en":"feminine appearance","vi":"vẻ ngoài nữ tính"},{"en":"feminine noun","vi":"danh từ giống cái"}],"wordFamily":["femininity (n)"],"synonyms":[],"antonyms":["masculine"],"tipVi":"feminine nhấn mạnh khí chất hoặc giới tính ngữ pháp; female nhấn mạnh giới tính sinh học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tension', 'en-b2-16', 'tension', '/ˈtenʃən/', 'B2', 'sự căng thẳng (quan hệ); tình hình căng thẳng; sự căng thẳng (tinh thần); sự lo âu; sức căng; độ căng', 'n.', 'tense (adj.), tensely (adv.)', 'Đồng nghĩa: strain, stress', 'Mối quan hệ căng thẳng thường dùng tension between; mâu thuẫn nhiều bên có thể dùng dạng số nhiều.', 'Tension grew between the neighbours over the shared driveway.', NULL, 'Mối quan hệ giữa những người hàng xóm trở nên căng thẳng vì lối đi chung.', '{"wordId":"tension","ukIpa":"/ˈtenʃən/","usIpa":"/ˈtenʃən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"Strained relations between people or groups that may cause conflict","vi":"sự căng thẳng (quan hệ); tình hình căng thẳng"},{"pos":"n.","en":"A feeling of worry that makes relaxation difficult","vi":"sự căng thẳng (tinh thần); sự lo âu"},{"pos":"n.","en":"A force that stretches or pulls something tight","vi":"sức căng; độ căng"}],"examples":[{"en":"Tension grew between the neighbours over the shared driveway.","vi":"Mối quan hệ giữa những người hàng xóm trở nên căng thẳng vì lối đi chung.","audioKind":"ex"},{"en":"Competition for limited water supplies can increase tension between farming communities and nearby cities.","vi":"Sự cạnh tranh về nguồn nước hạn chế có thể làm gia tăng căng thẳng giữa các cộng đồng làm nông nghiệp và các thành phố lân cận.","audioKind":"ex2"}],"collocations":[{"en":"ease tension","vi":"làm dịu căng thẳng"},{"en":"political tension","vi":"căng thẳng chính trị"},{"en":"muscle tension","vi":"căng cơ"},{"en":"surface tension","vi":"sức căng bề mặt"}],"wordFamily":["tense (adj.)","tensely (adv.)"],"synonyms":["strain","stress"],"antonyms":[],"tipVi":"Mối quan hệ căng thẳng thường dùng tension between; mâu thuẫn nhiều bên có thể dùng dạng số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_neutral', 'en-b2-16', 'neutral', '/ˈnuːtrəl/', 'B2', 'trung lập; không thiên vị; (màu sắc) trung tính; nhạt; (xe cộ) số mo; số không; số trung gian', 'adj.', 'neutrality (n.), neutralise (v.), neutrally (adv.)', 'Đồng nghĩa: impartial, unbiased · Trái nghĩa: biased, partisan', 'Giữ trung lập dùng remain neutral; xe cộ về số mo dùng in neutral.', 'I stayed neutral while my friends argued about the rules.', NULL, 'Tôi giữ thái độ trung lập trong khi các bạn tôi tranh cãi về các quy tắc.', '{"wordId":"neutral","ukIpa":"/ˈnjuːtrəl/","usIpa":"/ˈnuːtrəl/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"not supporting either side in a disagreement or conflict","vi":"trung lập; không thiên vị"},{"pos":"adj.","en":"having a colour that is not bright or strong","vi":"(màu sắc) trung tính; nhạt"},{"pos":"n.","en":"a gear position in which the engine does not drive wheels","vi":"(xe cộ) số mo; số không; số trung gian"}],"examples":[{"en":"I stayed neutral while my friends argued about the rules.","vi":"Tôi giữ thái độ trung lập trong khi các bạn tôi tranh cãi về các quy tắc.","audioKind":"ex"},{"en":"Journalists should remain neutral when reporting political debates so that audiences can form their own opinions.","vi":"Các nhà báo nên giữ thái độ trung lập khi đưa tin về các cuộc tranh luận chính trị để khán giả có thể tự đưa ra quan điểm của riêng mình.","audioKind":"ex2"}],"collocations":[{"en":"remain neutral","vi":"giữ thái độ trung lập"},{"en":"a neutral observer","vi":"quan sát viên trung lập"},{"en":"neutral colours","vi":"màu sắc trung tính"},{"en":"in neutral","vi":"đang ở số mo"}],"wordFamily":["neutrality (n.)","neutralise (v.)","neutrally (adv.)"],"synonyms":["impartial","unbiased"],"antonyms":["biased","partisan"],"tipVi":"Giữ trung lập dùng remain neutral; xe cộ về số mo dùng in neutral.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_anthem', 'en-b2-16', 'anthem', '/ˈænθəm/', 'B2', 'quốc ca; bài hát ca ngợi; thánh ca tôn giáo', 'n.', NULL, NULL, 'National anthem chỉ quốc ca; trong ngữ cảnh tôn giáo có thể chỉ bài hợp xướng thánh ca.', 'The crowd stood proudly as the national anthem began.', NULL, 'Đám đông đứng nghiêm trang đầy kiêu hãnh khi quốc ca bắt đầu vang lên.', '{"wordId":"anthem","ukIpa":"/ˈænθəm/","usIpa":"/ˈænθəm/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"A song expressing loyalty to a country or group","vi":"quốc ca; bài hát ca ngợi"},{"pos":"n.","en":"A religious song sung by a choir","vi":"thánh ca tôn giáo"}],"examples":[{"en":"The crowd stood proudly as the national anthem began.","vi":"Đám đông đứng nghiêm trang đầy kiêu hãnh khi quốc ca bắt đầu vang lên.","audioKind":"ex"},{"en":"Singing a national anthem at international sporting events can strengthen a shared sense of identity.","vi":"Việc hát quốc ca tại các sự kiện thể thao quốc tế có thể củng cố ý thức bản sắc chung.","audioKind":"ex2"}],"collocations":[{"en":"national anthem","vi":"quốc ca"},{"en":"sing an anthem","vi":"hát bài ca ngợi"},{"en":"the national anthem plays","vi":"quốc ca vang lên"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"National anthem chỉ quốc ca; trong ngữ cảnh tôn giáo có thể chỉ bài hợp xướng thánh ca.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_maintain', 'en-b2-16', 'maintain', '/meɪnˈteɪn/', 'B2', 'duy trì; giữ gìn; bảo dưỡng; bảo trì; khẳng định; quả quyết', 'v.', 'maintenance (n.), maintainable (adj.)', 'Đồng nghĩa: preserve, sustain', 'maintain đi thẳng với tân ngữ; khi mang nghĩa khẳng định quả quyết có thể đi với mệnh đề that.', 'Regular walks help me maintain a healthy weight.', NULL, 'Những chuyến đi bộ thường xuyên giúp tôi duy trì cân nặng lành mạnh.', '{"wordId":"maintain","ukIpa":"/meɪnˈteɪn/","usIpa":"/meɪnˈteɪn/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"To keep something at the same level or in existence.","vi":"duy trì; giữ gìn"},{"pos":"v.","en":"To keep something working well through regular care and repairs.","vi":"bảo dưỡng; bảo trì"},{"pos":"v.","en":"To firmly state that something is true.","vi":"khẳng định; quả quyết"}],"examples":[{"en":"Regular walks help me maintain a healthy weight.","vi":"Những chuyến đi bộ thường xuyên giúp tôi duy trì cân nặng lành mạnh.","audioKind":"ex"},{"en":"Governments must maintain essential public services while responding to growing pressure on national budgets.","vi":"Chính phủ phải duy trì các dịch vụ công thiết yếu trong khi vẫn phải đối phó với áp lực ngày càng tăng đối với ngân sách quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"maintain a balance","vi":"duy trì sự cân bằng"},{"en":"maintain standards","vi":"duy trì tiêu chuẩn"},{"en":"maintain equipment","vi":"bảo dưỡng thiết bị"},{"en":"maintain that","vi":"khẳng định rằng"}],"wordFamily":["maintenance (n.)","maintainable (adj.)"],"synonyms":["preserve","sustain"],"antonyms":[],"tipVi":"maintain đi thẳng với tân ngữ; khi mang nghĩa khẳng định quả quyết có thể đi với mệnh đề that.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_elderly', 'en-b2-16', 'elderly', '/ˈeldərli/', 'B2', 'có tuổi; cao tuổi; già', 'adj.', 'elder (n.)', 'Đồng nghĩa: older, aged · Trái nghĩa: young', 'Chỉ người già, không chỉ người trung niên; older people thường mang tính trung lập hơn.', 'An elderly neighbour showed me how to grow tomatoes.', NULL, 'Một người hàng xóm lớn tuổi đã chỉ cho tôi cách trồng cà chua.', '{"wordId":"elderly","ukIpa":"/ˈeldəli/","usIpa":"/ˈeldərli/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"old, especially when describing people","vi":"có tuổi; cao tuổi; già"}],"examples":[{"en":"An elderly neighbour showed me how to grow tomatoes.","vi":"Một người hàng xóm lớn tuổi đã chỉ cho tôi cách trồng cà chua.","audioKind":"ex"},{"en":"Cities should provide accessible public transport so that elderly residents can remain active and independent.","vi":"Các thành phố nên cung cấp giao thông công cộng dễ tiếp cận để cư dân cao tuổi có thể duy trì sự năng động và sống độc lập.","audioKind":"ex2"}],"collocations":[{"en":"elderly people","vi":"người cao tuổi"},{"en":"elderly residents","vi":"cư dân cao tuổi"},{"en":"elderly care","vi":"chăm sóc người cao tuổi"}],"wordFamily":["elder (n.)"],"synonyms":["older","aged"],"antonyms":["young"],"tipVi":"Chỉ người già, không chỉ người trung niên; older people thường mang tính trung lập hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_majority', 'en-b2-16', 'majority', '/məˈdʒɔːrəti/', 'B2', 'đa số; phần lớn; số phiếu áp đảo; số phiếu vượt trội', 'n.', 'major (adj.)', 'Đồng nghĩa: most · Trái nghĩa: minority', 'the majority of khi đi với danh từ số nhiều thường đi kèm với động từ chia ở số nhiều.', 'The majority of our neighbours have dogs or cats.', NULL, 'Phần lớn những người hàng xóm của chúng tôi đều nuôi chó hoặc mèo.', '{"wordId":"majority","ukIpa":"/məˈdʒɒrəti/","usIpa":"/məˈdʒɔːrəti/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"the larger part of a group, exceeding half its members","vi":"đa số; phần lớn"},{"pos":"n.","en":"the extra votes by which one candidate or side wins","vi":"số phiếu áp đảo; số phiếu vượt trội"}],"examples":[{"en":"The majority of our neighbours have dogs or cats.","vi":"Phần lớn những người hàng xóm của chúng tôi đều nuôi chó hoặc mèo.","audioKind":"ex"},{"en":"The majority of respondents supported greater investment in public transport rather than the construction of new roads.","vi":"Đa số những người tham gia khảo sát ủng hộ việc đầu tư nhiều hơn cho giao thông công cộng thay vì xây dựng các con đường mới.","audioKind":"ex2"}],"collocations":[{"en":"the vast majority of","vi":"đại đa số; phần lớn"},{"en":"a clear majority","vi":"đa số áp đảo; đa số rõ rệt"},{"en":"win a majority","vi":"giành được đa số phiếu"}],"wordFamily":["major (adj.)"],"synonyms":["most"],"antonyms":["minority"],"tipVi":"the majority of khi đi với danh từ số nhiều thường đi kèm với động từ chia ở số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_united', 'en-b2-16', 'united', '/juˈnaɪtɪd/', 'B2', 'đoàn kết; đồng lòng; thống nhất; liên hiệp', 'adj.', 'unite (v.), unity (n.), unification (n.)', 'Đồng nghĩa: unified · Trái nghĩa: divided', 'be united in đi với lập trường chung; united front chỉ mặt trận thống nhất.', 'Our neighbours remained united despite disagreements about the garden.', NULL, 'Những người hàng xóm của chúng tôi vẫn giữ được sự đoàn kết mặc dù có những bất đồng về khu vườn.', '{"wordId":"united","ukIpa":"/juˈnaɪtɪd/","usIpa":"/juˈnaɪtɪd/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Working together or sharing the same aims and opinions.","vi":"đoàn kết; đồng lòng"},{"pos":"adj.","en":"Joined together to form a single group or whole.","vi":"thống nhất; liên hiệp"}],"examples":[{"en":"Our neighbours remained united despite disagreements about the garden.","vi":"Những người hàng xóm của chúng tôi vẫn giữ được sự đoàn kết mặc dù có những bất đồng về khu vườn.","audioKind":"ex"},{"en":"A united response from governments and communities is essential for addressing the long-term challenges of climate change.","vi":"Một phản ứng đồng lòng từ các chính phủ và cộng đồng là điều thiết yếu để giải quyết những thách thức lâu dài của biến đổi khí hậu.","audioKind":"ex2"}],"collocations":[{"en":"a united front","vi":"mặt trận thống nhất"},{"en":"a united response","vi":"phản ứng đồng lòng"},{"en":"united in opposition","vi":"đồng lòng phản đối"},{"en":"remain united","vi":"giữ vững sự đoàn kết"}],"wordFamily":["unite (v.)","unity (n.)","unification (n.)"],"synonyms":["unified"],"antonyms":["divided"],"tipVi":"be united in đi với lập trường chung; united front chỉ mặt trận thống nhất.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_16_1', 'en-b2-16', 'Cách dùng “famine” (n.) — nạn đói; nạn thiếu lương thực trầm trọng', 'widespread famine  ·  famine relief  ·  prevent famine', 'Từ famine chỉ tình trạng thiếu hụt lương thực quy mô lớn; trong khi hunger dùng cho cá nhân thấy đói.', NULL, '[{"hanzi":"Our community sent food to families affected by famine.","pinyin":"","meaning":"Cộng đồng của chúng tôi đã gửi thực phẩm đến các gia đình bị ảnh hưởng bởi nạn đói."},{"hanzi":"Prolonged drought can lead to famine when farming communities lack reliable irrigation systems and emergency food reserves.","pinyin":"","meaning":"Hạn hán kéo dài có thể dẫn đến nạn đói khi các cộng đồng nông nghiệp thiếu hệ thống tưới tiêu đáng tin cậy và dự trữ lương thực khẩn cấp."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_16_2', 'en-b2-16', 'Cách dùng “etiquette” (n.) — phép tắc xã giao; quy tắc ứng xử', 'table etiquette  ·  business etiquette  ·  social etiquette', 'Thường là danh từ không đếm được; chỉ các quy tắc lễ nghi chung, không dùng cho một hành động đơn lẻ.', 'Đồng nghĩa: protocol, manners', '[{"hanzi":"My aunt taught me basic table etiquette before dinner.","pinyin":"","meaning":"Dì của tôi đã dạy tôi các quy tắc ứng xử cơ bản trên bàn ăn trước bữa tối."},{"hanzi":"Learning local etiquette can help international students avoid misunderstandings and build stronger relationships with their hosts.","pinyin":"","meaning":"Việc tìm hiểu phép tắc xã giao địa phương có thể giúp các du học sinh tránh được những hiểu lầm và xây dựng mối quan hệ tốt đẹp hơn với người dân bản địa."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_16_3', 'en-b2-16', 'Cách dùng “hospitable” (adj.) — hiếu khách; niềm nở, chu đáo với khách', 'a hospitable host  ·  hospitable to visitors  ·  a hospitable environment', 'Khi chỉ con người thì dịch là "hieu khach"; khi chỉ môi trường thì dịch là "thich hop de sinh song".', 'Họ từ (Word Family): hospitality (n.), hospitably (adv.), inhospitable (adj.) | Đồng nghĩa: welcoming, friendly · Trái nghĩa: inhospitable, unwelcoming', '[{"hanzi":"Our hospitable neighbours invited us in for warm soup.","pinyin":"","meaning":"Những người hàng xóm hiếu khách của chúng tôi đã mời chúng tôi vào nhà để ăn một bát súp nóng."},{"hanzi":"A hospitable climate and reliable water supplies have encouraged human settlement in this region for centuries.","pinyin":"","meaning":"Khí hậu ôn hòa và nguồn nước ổn định đã thu hút con người đến định cư ở vùng này trong nhiều thế kỷ."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_16_4', 'en-b2-16', 'Cách dùng “dispute” (n.) — cuộc tranh chấp; sự tranh cãi', 'settle a dispute  ·  a dispute over pay  ·  dispute a claim', 'dispute a claim mang nghĩa là đặt nghi vấn về một tuyên bố, không phải là thảo luận về tuyên bố đó.', 'Họ từ (Word Family): disputed (adj.), disputable (adj.), indisputable (adj.) | Đồng nghĩa: disagreement, contest · Trái nghĩa: agreement', '[{"hanzi":"Our neighbours settled their dispute over the garden fence.","pinyin":"","meaning":"Những người hàng xóm của chúng tôi đã giải quyết xong tranh chấp về hàng rào khu vườn."},{"hanzi":"Independent experts dispute the claim that building more roads will permanently reduce traffic congestion.","pinyin":"","meaning":"Các chuyên gia độc lập đặt nghi vấn về quan điểm cho rằng việc xây dựng thêm đường xá sẽ giải quyết vĩnh viễn tình trạng ùn tắc giao thông."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_16_1', 'en-b2-16', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_16_1_1', 'ten_b2_16_1', 'lad', 'A friendly lad helped us carry the bags.', 'A friendly lad helped us carry the bags.', '/læd/', 'Một cậu thanh niên thân thiện đã giúp chúng tôi xách túi đồ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_16_1_2', 'ten_b2_16_1', 'burial', 'The family gathered quietly for the burial yesterday.', 'The family gathered quietly for the burial yesterday.', '/ˈberiəl/', 'Gia đình đã quây quần lặng lẽ trong lễ an táng vào ngày hôm qua.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_16_1_3', 'ten_b2_16_1', 'restricted', 'Parking is restricted here during the busy morning hours.', 'Parking is restricted here during the busy morning hours.', '/rɪˈstrɪktɪd/', 'Việc đỗ xe bị hạn chế ở đây trong những giờ cao điểm buổi sáng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_16_1_4', 'ten_b2_16_1', 'robbery', 'The shop closed early after a robbery yesterday.', 'The shop closed early after a robbery yesterday.', '/ˈrɑːbəri/', 'Cửa hàng đã đóng cửa sớm sau một vụ cướp ngày hôm qua.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_16_1_5', 'ten_b2_16_1', 'dispute', 'Our neighbours settled their dispute over the garden fence.', 'Our neighbours settled their dispute over the garden fence.', '/dɪˈspjuːt/', 'Những người hàng xóm của chúng tôi đã giải quyết xong tranh chấp về hàng rào khu vườn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_16_1_6', 'ten_b2_16_1', 'hospitable', 'Our hospitable neighbours invited us in for warm soup.', 'Our hospitable neighbours invited us in for warm soup.', '/hɑːˈspɪtəbəl/', 'Những người hàng xóm hiếu khách của chúng tôi đã mời chúng tôi vào nhà để ăn một bát súp nóng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_16_1_7', 'ten_b2_16_1', 'civil', 'The airport handles both military and civil aircraft.', 'The airport handles both military and civil aircraft.', '/ˈsɪvəl/', 'Sân bay này phục vụ cả máy bay quân sự lẫn máy bay dân dụng.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_16_1_8', 'ten_b2_16_1', 'famine', 'Our community sent food to families affected by famine.', 'Our community sent food to families affected by famine.', '/ˈfæmɪn/', 'Cộng đồng của chúng tôi đã gửi thực phẩm đến các gia đình bị ảnh hưởng bởi nạn đói.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_16_1_1', 'en-b2-16', 'ten_b2_16_1', 'listening', 'listening', 'A friendly lad helped us carry the bags.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những người hàng xóm hiếu khách của chúng tôi đã mời chúng tôi vào nhà để ăn một bát súp nóng.","Dì của tôi đã dạy tôi các quy tắc ứng xử cơ bản trên bàn ăn trước bữa tối.","Một cậu thanh niên thân thiện đã giúp chúng tôi xách túi đồ.","Cửa hàng đã đóng cửa sớm sau một vụ cướp ngày hôm qua."]'::jsonb, 2, 'A friendly lad helped us carry the bags. → Một cậu thanh niên thân thiện đã giúp chúng tôi xách túi đồ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_16_1_2', 'en-b2-16', 'ten_b2_16_1', 'listening', 'listening', 'The family gathered quietly for the burial yesterday.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Việc đỗ xe bị hạn chế ở đây trong những giờ cao điểm buổi sáng.","Cô ấy đối xử với mọi vị khách một cách lịch sự, ngay cả khi rất mệt mỏi.","Khu vui chơi mới đã nhận được sự đồng thuận tuyệt đối từ các gia đình trong vùng.","Gia đình đã quây quần lặng lẽ trong lễ an táng vào ngày hôm qua."]'::jsonb, 3, 'The family gathered quietly for the burial yesterday. → Gia đình đã quây quần lặng lẽ trong lễ an táng vào ngày hôm qua.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_16_1_3', 'en-b2-16', 'ten_b2_16_1', 'listening', 'listening', 'Parking is restricted here during the busy morning hours.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Khu vui chơi mới đã nhận được sự đồng thuận tuyệt đối từ các gia đình trong vùng.","Phần lớn những người hàng xóm của chúng tôi đều nuôi chó hoặc mèo.","Việc đỗ xe bị hạn chế ở đây trong những giờ cao điểm buổi sáng.","Dì của tôi đã dạy tôi các quy tắc ứng xử cơ bản trên bàn ăn trước bữa tối."]'::jsonb, 2, 'Parking is restricted here during the busy morning hours. → Việc đỗ xe bị hạn chế ở đây trong những giờ cao điểm buổi sáng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_16_2', 'en-b2-16', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_16_2_1', 'ten_b2_16_2', 'lad', 'As a young lad, the novelist experienced rural poverty, which later became a central theme in his work.', 'As a young lad, the novelist experienced rural poverty, which later became a central theme in his work.', '/læd/', 'Thuở nhỏ, nhà văn này từng trải qua cảnh nghèo khó nơi thôn quê, điều sau này đã trở thành chủ đề cốt lõi trong các tác phẩm của ông.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_16_2_2', 'ten_b2_16_2', 'burial', 'Ancient burial sites provide valuable evidence about the beliefs and social structures of past communities.', 'Ancient burial sites provide valuable evidence about the beliefs and social structures of past communities.', '/ˈberiəl/', 'Các di tích mai táng cổ đại cung cấp bằng chứng quý giá về niềm tin và cấu trúc xã hội của các cộng đồng trong quá khứ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_16_2_3', 'ten_b2_16_2', 'restricted', 'Restricted access to affordable healthcare can worsen existing inequalities between wealthy communities and disadvantaged rural populations.', 'Restricted access to affordable healthcare can worsen existing inequalities between wealthy communities and disadvantaged rural populations.', '/rɪˈstrɪktɪd/', 'Quyền tiếp cận dịch vụ y tế giá cả phải chăng bị hạn chế có thể làm trầm trọng thêm tình trạng bất bình đẳng hiện có giữa các cộng đồng giàu có và nhóm dân cư nông thôn có hoàn cảnh khó khăn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_16_2_4', 'ten_b2_16_2', 'robbery', 'Better street lighting may reduce the risk of robbery and help residents feel safer after dark.', 'Better street lighting may reduce the risk of robbery and help residents feel safer after dark.', '/ˈrɑːbəri/', 'Hệ thống chiếu sáng đường phố tốt hơn có thể làm giảm nguy cơ cướp giật và giúp cư dân cảm thấy an toàn hơn sau khi trời tối.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_16_2_5', 'ten_b2_16_2', 'dispute', 'Independent experts dispute the claim that building more roads will permanently reduce traffic congestion.', 'Independent experts dispute the claim that building more roads will permanently reduce traffic congestion.', '/dɪˈspjuːt/', 'Các chuyên gia độc lập đặt nghi vấn về quan điểm cho rằng việc xây dựng thêm đường xá sẽ giải quyết vĩnh viễn tình trạng ùn tắc giao thông.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_16_2_6', 'ten_b2_16_2', 'hospitable', 'A hospitable climate and reliable water supplies have encouraged human settlement in this region for centuries.', 'A hospitable climate and reliable water supplies have encouraged human settlement in this region for centuries.', '/hɑːˈspɪtəbəl/', 'Khí hậu ôn hòa và nguồn nước ổn định đã thu hút con người đến định cư ở vùng này trong nhiều thế kỷ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_16_2_1', 'en-b2-16', 'ten_b2_16_2', 'listening', 'listening', 'As a young lad, the novelist experienced rural poverty, which later became a central theme in his work.', NULL, 'Trong câu vừa nghe, từ “lad” mang nghĩa nào sau đây?', '["đậu nành; sản phẩm từ đậu nành","tầm quan trọng; ý nghĩa","trải qua; chịu đựng; tiếp nhận (quá trình, sự thay đổi hoặc điều trị)","chàng trai; cậu thanh niên"]'::jsonb, 3, '“lad” (/læd/): chàng trai; cậu thanh niên. Câu đầy đủ: As a young lad, the novelist experienced rural poverty, which later became a central theme in his work.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_16_2_2', 'en-b2-16', 'ten_b2_16_2', 'listening', 'listening', 'Ancient burial sites provide valuable evidence about the beliefs and social structures of past communities.', NULL, 'Trong câu vừa nghe, từ “burial” mang nghĩa nào sau đây?', '["cơn mưa rào lớn; trận mưa xối xả","theo nghĩa đen; nguyên văn","sự chôn cất; lễ an táng","sự nhắc đến; ý nhắc tới"]'::jsonb, 2, '“burial” (/ˈberiəl/): sự chôn cất; lễ an táng. Câu đầy đủ: Ancient burial sites provide valuable evidence about the beliefs and social structures of past communities.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
