INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_16_2', 'en-b2-16', NULL, 'comprehensive_test', 'listening', 'The family gathered quietly for the burial yesterday.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Dì của tôi đã dạy tôi các quy tắc ứng xử cơ bản trên bàn ăn trước bữa tối.","Một cậu thanh niên thân thiện đã giúp chúng tôi xách túi đồ.","Gia đình đã quây quần lặng lẽ trong lễ an táng vào ngày hôm qua.","Những người hàng xóm của chúng tôi đã giải quyết xong tranh chấp về hàng rào khu vườn."]'::jsonb, 2, 'The family gathered quietly for the burial yesterday. → Gia đình đã quây quần lặng lẽ trong lễ an táng vào ngày hôm qua.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_16_3', 'en-b2-16', NULL, 'comprehensive_test', 'listening', 'restricted', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["vỡ nợ; phá sản","liên minh; khối liên minh","nghe chừng; hình như; có vẻ như","bị hạn chế; có giới hạn"]'::jsonb, 3, 'restricted (/rɪˈstrɪktɪd/) → bị hạn chế; có giới hạn; chỉ dành riêng cho những người có thẩm quyền', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_16_4', 'en-b2-16', NULL, 'comprehensive_test', 'listening', 'The shop closed early after a robbery yesterday.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một người hàng xóm lớn tuổi đã chỉ cho tôi cách trồng cà chua.","Chiếc bình vỡ không phải lỗi của cậu ấy; cậu ấy hoàn toàn vô tội.","Căn phòng chìm vào sự im lặng tuyệt đối khi cô ấy bước vào.","Cửa hàng đã đóng cửa sớm sau một vụ cướp ngày hôm qua."]'::jsonb, 3, 'The shop closed early after a robbery yesterday. → Cửa hàng đã đóng cửa sớm sau một vụ cướp ngày hôm qua.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_16_5', 'en-b2-16', NULL, 'comprehensive_test', 'listening', 'dispute', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự kỳ vọng; niềm tin rằng điều gì đó sẽ xảy ra","thuộc về nghệ thuật","băng rôn; biểu ngữ; cờ","cuộc tranh chấp; sự tranh cãi"]'::jsonb, 3, 'dispute (/dɪˈspjuːt/) → cuộc tranh chấp; sự tranh cãi; tranh cãi; bác bỏ; đặt nghi vấn; tranh chấp; tranh giành', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_16_6', 'en-b2-16', NULL, 'comprehensive_test', 'listening', 'Our hospitable neighbours invited us in for warm soup.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những người hàng xóm hiếu khách của chúng tôi đã mời chúng tôi vào nhà để ăn một bát súp nóng.","Việc đỗ xe bị hạn chế ở đây trong những giờ cao điểm buổi sáng.","Cô ấy chọn một chiếc áo kiểu nữ tính với phần tay áo ren tinh tế.","Căn phòng chìm vào sự im lặng tuyệt đối khi cô ấy bước vào."]'::jsonb, 0, 'Our hospitable neighbours invited us in for warm soup. → Những người hàng xóm hiếu khách của chúng tôi đã mời chúng tôi vào nhà để ăn một bát súp nóng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_16_7', 'en-b2-16', NULL, 'comprehensive_test', 'listening', 'civil', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["khoác lác; khoe khoang","thuộc về công dân; dân sự (không phải quân sự)","khảo cổ học","không biết; không nhận thức được"]'::jsonb, 1, 'civil (/ˈsɪvəl/) → thuộc về công dân; dân sự (không phải quân sự); thuộc về pháp luật dân sự (không phải hình sự); lịch sự; nhã nhặn', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_16_8', 'en-b2-16', NULL, 'comprehensive_test', 'listening', 'Our community sent food to families affected by famine.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cộng đồng của chúng tôi đã gửi thực phẩm đến các gia đình bị ảnh hưởng bởi nạn đói.","Gia đình đã quây quần lặng lẽ trong lễ an táng vào ngày hôm qua.","Các tình nguyện viên phát trái cây tươi bên ngoài trung tâm cộng đồng vào mỗi thứ Sáu.","Tôi giữ thái độ trung lập trong khi các bạn tôi tranh cãi về các quy tắc."]'::jsonb, 0, 'Our community sent food to families affected by famine. → Cộng đồng của chúng tôi đã gửi thực phẩm đến các gia đình bị ảnh hưởng bởi nạn đói.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_16_9', 'en-b2-16', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a serious disagreement between people or groups”?', '["lad","dispute","contribute","robbery"]'::jsonb, 1, 'dispute (/dɪˈspjuːt/) → cuộc tranh chấp; sự tranh cãi', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
