INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_16_18', 'en-b2-16', NULL, 'comprehensive_test', 'reading', NULL, 'As a young lad, the novelist experienced rural poverty, which later became a central theme in his work.', 'Dựa vào câu trên, từ “lad” có nghĩa phù hợp nhất là gì?', '["tiếp xúc; phơi bày; đặt vào","chính; chủ yếu; hàng đầu","khu nghỉ dưỡng; khu du lịch","chàng trai; cậu thanh niên"]'::jsonb, 3, 'lad: chàng trai; cậu thanh niên. Dịch cả câu: Thuở nhỏ, nhà văn này từng trải qua cảnh nghèo khó nơi thôn quê, điều sau này đã trở thành chủ đề cốt lõi trong các tác phẩm của ông.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_16_19', 'en-b2-16', NULL, 'comprehensive_test', 'reading', NULL, 'Ancient burial sites provide valuable evidence about the beliefs and social structures of past communities.', 'Dựa vào câu trên, từ “burial” có nghĩa phù hợp nhất là gì?', '["cố ý; chủ tâm","ngành kế toán; công tác kế toán","thịnh vượng; phát đạt; giàu có","sự chôn cất; lễ an táng"]'::jsonb, 3, 'burial: sự chôn cất; lễ an táng. Dịch cả câu: Các di tích mai táng cổ đại cung cấp bằng chứng quý giá về niềm tin và cấu trúc xã hội của các cộng đồng trong quá khứ.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_16_20', 'en-b2-16', NULL, 'comprehensive_test', 'reading', NULL, 'Restricted access to affordable healthcare can worsen existing inequalities between wealthy communities and disadvantaged rural populations.', 'Dựa vào câu trên, từ “restricted” có nghĩa phù hợp nhất là gì?', '["bị hạn chế; có giới hạn","phanh; thắng; thiết bị hãm","tuyệt vọng; liều lĩnh","sự ghê tởm; sự kinh tởm; sự bất bình"]'::jsonb, 0, 'restricted: bị hạn chế; có giới hạn; chỉ dành riêng cho những người có thẩm quyền. Dịch cả câu: Quyền tiếp cận dịch vụ y tế giá cả phải chăng bị hạn chế có thể làm trầm trọng thêm tình trạng bất bình đẳng hiện có giữa các cộng đồng giàu có và nhóm dân cư nông thôn có hoàn cảnh khó khăn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_16_21', 'en-b2-16', NULL, 'comprehensive_test', 'reading', NULL, 'Better street lighting may reduce the risk of robbery and help residents feel safer after dark.', 'Dựa vào câu trên, từ “robbery” có nghĩa phù hợp nhất là gì?', '["bi thảm; đau thương","cách xử lý; sự giải quyết","vụ cướp, nạn cướp bóc","chung; liên hợp; phối hợp"]'::jsonb, 2, 'robbery: vụ cướp, nạn cướp bóc. Dịch cả câu: Hệ thống chiếu sáng đường phố tốt hơn có thể làm giảm nguy cơ cướp giật và giúp cư dân cảm thấy an toàn hơn sau khi trời tối.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_16_22', 'en-b2-16', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “có tuổi; cao tuổi; già”', '["elderly","hearing","gender","apparent"]'::jsonb, 0, 'có tuổi; cao tuổi; già → elderly (/ˈeldərli/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_16_23', 'en-b2-16', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đa số; phần lớn”', '["enquiry","correction","majority","overload"]'::jsonb, 2, 'đa số; phần lớn → majority (/məˈdʒɔːrəti/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_16_24', 'en-b2-16', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đoàn kết; đồng lòng”', '["united","activate","nerve","encyclopaedia"]'::jsonb, 0, 'đoàn kết; đồng lòng → united (/juˈnaɪtɪd/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-17', 'en', 'Bài 17: Xã hội & Cộng đồng (10) - CEFR B2', 'CEFR B2', 'B2 · Xã hội', '26 từ vựng Tiếng Anh CEFR B2 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4017, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inhabitant', 'en-b2-17', 'inhabitant', '/ɪnˈhæbɪtənt/', 'B2', 'cư dân; động thực vật sinh sống tại một nơi', 'n.', 'inhabit (v.), inhabited (adj.), uninhabited (adj.), inhabitable (adj.)', 'Đồng nghĩa: resident', 'Thường dùng inhabitants of + địa điểm; không đồng nghĩa với citizens (công dân có quốc tịch).', 'Every inhabitant of the village helped repair the bridge.', NULL, 'Mỗi cư dân trong làng đều chung tay sửa chữa cây cầu.', '{"wordId":"inhabitant","ukIpa":"/ɪnˈhæbɪtənt/","usIpa":"/ɪnˈhæbɪtənt/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"A person or animal that lives in a particular place.","vi":"cư dân; động thực vật sinh sống tại một nơi"}],"examples":[{"en":"Every inhabitant of the village helped repair the bridge.","vi":"Mỗi cư dân trong làng đều chung tay sửa chữa cây cầu.","audioKind":"ex"},{"en":"Rapid urban growth can place pressure on housing and reduce access to green spaces for local inhabitants.","vi":"Sự bùng nổ đô thị nhanh chóng có thể gây áp lực lên nhà ở và làm giảm không gian xanh cho cư dân địa phương.","audioKind":"ex2"}],"collocations":[{"en":"local inhabitants","vi":"cư dân địa phương"},{"en":"the inhabitants of a city","vi":"cư dân của một thành phố"},{"en":"original inhabitants","vi":"cư dân bản địa"}],"wordFamily":["inhabit (v.)","inhabited (adj.)","uninhabited (adj.)","inhabitable (adj.)"],"synonyms":["resident"],"antonyms":[],"tipVi":"Thường dùng inhabitants of + địa điểm; không đồng nghĩa với citizens (công dân có quốc tịch).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_homeless', 'en-b2-17', 'homeless', '/ˈhoʊmləs/', 'B2', 'vô gia cư', 'adj.', 'home (n.), homelessness (n.)', 'Đồng nghĩa: unhoused', 'Không nói a homeless; phải dùng a homeless person.', 'The flood left several families homeless in our town.', NULL, 'Trận lũ lụt đã khiến nhiều gia đình ở thị trấn chúng tôi rơi vào cảnh màn trời chiếu đất.', '{"wordId":"homeless","ukIpa":"/ˈhəʊmləs/","usIpa":"/ˈhoʊmləs/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Without a permanent place to live.","vi":"vô gia cư"}],"examples":[{"en":"The flood left several families homeless in our town.","vi":"Trận lũ lụt đã khiến nhiều gia đình ở thị trấn chúng tôi rơi vào cảnh màn trời chiếu đất.","audioKind":"ex"},{"en":"Affordable housing and accessible support services are essential to helping homeless people rebuild stable lives.","vi":"Nhà ở giá rẻ và các dịch vụ hỗ trợ dễ tiếp cận đóng vai trò thiết yếu trong việc giúp người vô gia cư tạo dựng lại cuộc sống ổn định.","audioKind":"ex2"}],"collocations":[{"en":"homeless people","vi":"những người vô gia cư"},{"en":"become homeless","vi":"trở thành người vô gia cư"},{"en":"leave someone homeless","vi":"khiến ai đó rơi vào cảnh vô gia cư"},{"en":"a homeless shelter","vi":"trú ẩn cho người vô gia cư"}],"wordFamily":["home (n.)","homelessness (n.)"],"synonyms":["unhoused"],"antonyms":[],"tipVi":"Không nói a homeless; phải dùng a homeless person.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_outsider', 'en-b2-17', 'outsider', '/ˌaʊtˈsaɪdɚ/', 'B2', 'người ngoài cuộc; kẻ ngoại đạo; đối thủ không được đánh giá cao', 'n.', 'outside (adv.)', 'Trái nghĩa: insider', 'Có thể chỉ người ngoài nhóm hoặc chỉ thí sinh/đội bóng ít có khả năng giành chiến thắng.', 'At first, I felt like an outsider at school.', NULL, 'Lúc đầu, tôi cảm thấy mình giống như một người ngoài cuộc ở trường học.', '{"wordId":"outsider","ukIpa":"/ˌaʊtˈsaɪdə/","usIpa":"/ˌaʊtˈsaɪdɚ/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"Someone who does not belong to a particular group.","vi":"người ngoài cuộc; kẻ ngoại đạo"},{"pos":"n.","en":"A competitor considered unlikely to win.","vi":"đối thủ không được đánh giá cao"}],"examples":[{"en":"At first, I felt like an outsider at school.","vi":"Lúc đầu, tôi cảm thấy mình giống như một người ngoài cuộc ở trường học.","audioKind":"ex"},{"en":"An outsider may identify weaknesses in an organisation that its long-standing members have failed to notice.","vi":"Một người ngoài cuộc có thể nhận diện ra những điểm yếu trong một tổ chức mà các thành viên lâu năm đã bỏ sót.","audioKind":"ex2"}],"collocations":[{"en":"feel like an outsider","vi":"cảm thấy như một người ngoài cuộc"},{"en":"an outsider''s perspective","vi":"góc nhìn của người ngoài"},{"en":"a rank outsider","vi":"một đối thủ hoàn toàn lép vế"}],"wordFamily":["outside (adv.)"],"synonyms":[],"antonyms":["insider"],"tipVi":"Có thể chỉ người ngoài nhóm hoặc chỉ thí sinh/đội bóng ít có khả năng giành chiến thắng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_freely', 'en-b2-17', 'freely', '/ˈfriːli/', 'B2', 'tự do; không bị ràng buộc; thẳng thắn; cởi mở; tự nguyện; hào phóng', 'adv.', 'free (adj.), free (v.), freedom (n.)', NULL, 'freely chủ yếu chỉ sự không bị hạn chế; dùng từ miễn phí thì dùng for free.', 'The chickens wander freely around the garden all day.', NULL, 'Những con gà đi lại tự do quanh khu vườn cả ngày.', '{"wordId":"freely","ukIpa":"/ˈfriːli/","usIpa":"/ˈfriːli/","cefr":"B2","topic":"society","senses":[{"pos":"adv.","en":"without restrictions or anything preventing movement or action","vi":"tự do; không bị ràng buộc"},{"pos":"adv.","en":"openly and honestly, without hiding thoughts or facts","vi":"thẳng thắn; cởi mở"},{"pos":"adv.","en":"willingly and generously, without being forced","vi":"tự nguyện; hào phóng"}],"examples":[{"en":"The chickens wander freely around the garden all day.","vi":"Những con gà đi lại tự do quanh khu vườn cả ngày.","audioKind":"ex"},{"en":"Students should be able to express their opinions freely while respecting the rights and feelings of others.","vi":"Học sinh nên được tự do bày tỏ quan điểm của mình đồng thời tôn trọng quyền và cảm xúc của người khác.","audioKind":"ex2"}],"collocations":[{"en":"move freely","vi":"di chuyển tự do"},{"en":"speak freely","vi":"nói chuyện thoải mái"},{"en":"freely admit","vi":"thẳng thắn thừa nhận"},{"en":"give freely","vi":"cho đi hào phóng"}],"wordFamily":["free (adj.)","free (v.)","freedom (n.)"],"synonyms":[],"antonyms":[],"tipVi":"freely chủ yếu chỉ sự không bị hạn chế; dùng từ miễn phí thì dùng for free.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mature', 'en-b2-17', 'mature', '/məˈtʃʊr/', 'B2', 'chín chắn; trưởng thành; biết điều; phát triển hoàn toàn; phát triển hoàn thiện', 'adj.', 'maturity (n.), immature (adj.), immaturity (n.), maturation (n.)', 'Đồng nghĩa: sensible, grown-up · Trái nghĩa: immature', 'Có thể chỉ sự phát triển hoàn thiện về thể chất, hoặc sự chín chắn, khôn ngoan trong cách cư xử.', 'Leila gave a mature response when her plans changed.', NULL, 'Leila đã có phản ứng rất chín chắn khi kế hoạch của cô ấy thay đổi.', '{"wordId":"mature","ukIpa":"/məˈtʃʊə/","usIpa":"/məˈtʃʊr/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Behaving sensibly and showing good judgment","vi":"chín chắn; trưởng thành; biết điều"},{"pos":"adj.","en":"Fully grown or developed","vi":"phát triển hoàn toàn; trưởng thành"},{"pos":"v.","en":"To become fully developed or more sensible","vi":"trưởng thành; phát triển hoàn thiện"}],"examples":[{"en":"Leila gave a mature response when her plans changed.","vi":"Leila đã có phản ứng rất chín chắn khi kế hoạch của cô ấy thay đổi.","audioKind":"ex"},{"en":"Living independently can help young adults mature as they learn to manage money and resolve everyday problems.","vi":"Sống tự lập có thể giúp người trẻ trưởng thành hơn khi họ học cách quản lý tiền bạc và giải quyết các vấn đề hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"a mature attitude","vi":"thái độ chín chắn"},{"en":"a mature student","vi":"sinh viên lớn tuổi (quay lại học)"},{"en":"mature trees","vi":"cây trưởng thành"},{"en":"emotionally mature","vi":"chín chắn về mặt cảm xúc"}],"wordFamily":["maturity (n.)","immature (adj.)","immaturity (n.)","maturation (n.)"],"synonyms":["sensible","grown-up"],"antonyms":["immature"],"tipVi":"Có thể chỉ sự phát triển hoàn thiện về thể chất, hoặc sự chín chắn, khôn ngoan trong cách cư xử.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_greed', 'en-b2-17', 'greed', '/ɡriːd/', 'B2', 'lòng tham; sự tham lam', 'n.', 'greedy (adj.), greedily (adv.)', 'Đồng nghĩa: avarice · Trái nghĩa: generosity', 'Danh từ không đếm được; greed for theo sau là các đối tượng khao khát như tiền bạc, quyền lực.', 'His greed left everyone else without any cake.', NULL, 'Lòng tham của anh ta khiến mọi người chẳng còn chút bánh nào.', '{"wordId":"greed","ukIpa":"/ɡriːd/","usIpa":"/ɡriːd/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"a strong desire for more than one needs or deserves","vi":"lòng tham; sự tham lam"}],"examples":[{"en":"His greed left everyone else without any cake.","vi":"Lòng tham của anh ta khiến mọi người chẳng còn chút bánh nào.","audioKind":"ex"},{"en":"Corporate greed can undermine environmental protection when companies prioritise short-term profits over the welfare of local communities.","vi":"Lòng tham của doanh nghiệp có thể làm suy yếu việc bảo vệ môi trường khi các công ty đặt lợi nhuận ngắn hạn lên trên phúc lợi của cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"corporate greed","vi":"lòng tham của doanh nghiệp"},{"en":"greed for power","vi":"lòng tham quyền lực"},{"en":"driven by greed","vi":"bị lòng tham thúc đẩy"}],"wordFamily":["greedy (adj.)","greedily (adv.)"],"synonyms":["avarice"],"antonyms":["generosity"],"tipVi":"Danh từ không đếm được; greed for theo sau là các đối tượng khao khát như tiền bạc, quyền lực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_refusal', 'en-b2-17', 'refusal', '/rɪˈfjuːzəl/', 'B2', 'sự từ chối; lời khước từ', 'n.', 'refuse (v.)', 'Đồng nghĩa: rejection · Trái nghĩa: acceptance', 'Biểu thị sự từ chối làm việc gì, dùng refusal to do, không dùng of doing.', 'His polite refusal did not upset the host.', NULL, 'Lời từ chối lịch sự của anh ấy không làm chủ nhà khó chịu.', '{"wordId":"refusal","ukIpa":"/rɪˈfjuːzəl/","usIpa":"/rɪˈfjuːzəl/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"an act of saying you will not do or accept something","vi":"sự từ chối; lời khước từ"}],"examples":[{"en":"His polite refusal did not upset the host.","vi":"Lời từ chối lịch sự của anh ấy không làm chủ nhà khó chịu.","audioKind":"ex"},{"en":"A government''s refusal to address public concerns can weaken trust and reduce participation in democratic processes.","vi":"Việc chính phủ từ chối giải quyết các mối quan tâm của công chúng có thể làm xói mòn lòng tin và làm giảm sự tham gia vào các tiến trình dân chủ.","audioKind":"ex2"}],"collocations":[{"en":"refusal to cooperate","vi":"sự từ chối hợp tác"},{"en":"a firm refusal","vi":"lời từ chối kiên quyết"},{"en":"meet with refusal","vi":"vấp phải sự từ chối"}],"wordFamily":["refuse (v.)"],"synonyms":["rejection"],"antonyms":["acceptance"],"tipVi":"Biểu thị sự từ chối làm việc gì, dùng refusal to do, không dùng of doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_brag', 'en-b2-17', 'brag', '/bræɡ/', 'B2', 'khoác lác; khoe khoang', 'v.', 'bragging (n.), braggart (n.)', 'Đồng nghĩa: boast', 'Thường đi với about hoặc that; dạng quá khứ bragged được gấp đôi chữ cái g.', 'He always brags about how fast he can swim.', NULL, 'Anh ta luôn khoác lác về việc mình bơi giỏi đến mức nào.', '{"wordId":"brag","ukIpa":"/bræɡ/","usIpa":"/bræɡ/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"to talk too proudly about your achievements or possessions","vi":"khoác lác; khoe khoang"}],"examples":[{"en":"He always brags about how fast he can swim.","vi":"Anh ta luôn khoác lác về việc mình bơi giỏi đến mức nào.","audioKind":"ex"},{"en":"Social media can encourage users to brag about personal achievements rather than discuss everyday challenges honestly.","vi":"Mạng xã hội có thể khuyến khích người dùng khoe khoang về thành tích cá nhân thay vì thảo luận thành thật về những thử thách thường ngày.","audioKind":"ex2"}],"collocations":[{"en":"brag about achievements","vi":"khoe khoang thành tích"},{"en":"brag to friends","vi":"khoác lác với bạn bè"},{"en":"brag that you won","vi":"khoe rằng mình đã thắng"}],"wordFamily":["bragging (n.)","braggart (n.)"],"synonyms":["boast"],"antonyms":[],"tipVi":"Thường đi với about hoặc that; dạng quá khứ bragged được gấp đôi chữ cái g.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_objection', 'en-b2-17', 'objection', '/əbˈdʒekʃən/', 'B2', 'sự phản đối; lời phản đối; ý kiến phản đối', 'n.', 'object (v.), objector (n.), objectionable (adj.)', 'Đồng nghĩa: opposition · Trái nghĩa: approval', 'Từ objection đi với giới từ to, theo sau là danh từ hoặc danh động từ.', 'My only objection is that the tickets cost too much.', NULL, 'Điểm phản đối duy nhất của tôi là giá vé quá đắt.', '{"wordId":"objection","ukIpa":"/əbˈdʒekʃən/","usIpa":"/əbˈdʒekʃən/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"An expression of opposition, or a reason for opposing something.","vi":"sự phản đối; lời phản đối; ý kiến phản đối"}],"examples":[{"en":"My only objection is that the tickets cost too much.","vi":"Điểm phản đối duy nhất của tôi là giá vé quá đắt.","audioKind":"ex"},{"en":"Residents raised an objection to the proposed airport expansion because of its likely impact on noise levels.","vi":"Người dân đã nêu ý kiến phản đối đề xuất mở rộng sân bay vì tác động có thể xảy ra đối với mức độ tiếng ồn.","audioKind":"ex2"}],"collocations":[{"en":"raise an objection","vi":"nêu ý kiến phản đối"},{"en":"have no objection to","vi":"không có phản đối gì với"},{"en":"a strong objection","vi":"sự phản đối mạnh mẽ"}],"wordFamily":["object (v.)","objector (n.)","objectionable (adj.)"],"synonyms":["opposition"],"antonyms":["approval"],"tipVi":"Từ objection đi với giới từ to, theo sau là danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_appropriate', 'en-b2-17', 'appropriate', '/əˈproʊpriət/', 'B2', 'phù hợp; thích hợp; đúng đắn; chiếm đoạt; tự ý sử dụng (không phép); cấp ngân sách; trích quỹ', 'adj.', 'appropriately (adv.), appropriateness (n.), inappropriate (adj.), appropriation (n.)', 'Đồng nghĩa: suitable, fitting · Trái nghĩa: inappropriate, unsuitable', 'Tính từ đọc phần đuôi là /ət/, trong khi động từ đọc là /eɪt/.', 'Are these shoes appropriate for a long mountain walk?', NULL, 'Đôi giày này có phù hợp cho việc đi bộ đường dài trên núi không?', '{"wordId":"appropriate","ukIpa":"/əˈprəʊpriət/","usIpa":"/əˈproʊpriət/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"suitable for a particular situation or purpose","vi":"phù hợp; thích hợp; đúng đắn"},{"pos":"v.","en":"to take something for your own use without permission","vi":"chiếm đoạt; tự ý sử dụng (không phép)"},{"pos":"v.","en":"to officially set aside money for a particular purpose","vi":"cấp ngân sách; trích quỹ"}],"examples":[{"en":"Are these shoes appropriate for a long mountain walk?","vi":"Đôi giày này có phù hợp cho việc đi bộ đường dài trên núi không?","audioKind":"ex"},{"en":"Governments should provide appropriate training to help workers adapt to technological changes in the labour market.","vi":"Chính phủ nên cung cấp các khóa đào tạo phù hợp để giúp người lao động thích ứng với những thay đổi về công nghệ trên thị trường lao động.","audioKind":"ex2"}],"collocations":[{"en":"appropriate for","vi":"phù hợp với"},{"en":"appropriate measures","vi":"biện pháp thích hợp"},{"en":"appropriate behaviour","vi":"hành vi đúng mực"},{"en":"appropriate funds for","vi":"bố trí ngân sách cho"}],"wordFamily":["appropriately (adv.)","appropriateness (n.)","inappropriate (adj.)","appropriation (n.)"],"synonyms":["suitable","fitting"],"antonyms":["inappropriate","unsuitable"],"tipVi":"Tính từ đọc phần đuôi là /ət/, trong khi động từ đọc là /eɪt/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disagreement', 'en-b2-17', 'disagreement', '/ˌdɪsəˈɡriːmənt/', 'B2', 'sự bất đồng quan điểm; cuộc tranh cãi', 'n.', 'disagree (v.), agree (v.), agreement (n.)', 'Đồng nghĩa: difference of opinion, dispute · Trái nghĩa: agreement, consensus', 'Sự tranh cãi cụ thể có thể đếm được; khi nói chung về việc bất đồng quan điểm thường không đếm được.', 'We had a disagreement about whose turn it was.', NULL, 'Chúng tôi đã xảy ra tranh cãi về việc ai là người đến lượt.', '{"wordId":"disagreement","ukIpa":"/ˌdɪsəˈɡriːmənt/","usIpa":"/ˌdɪsəˈɡriːmənt/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"A difference of opinion or an argument about it.","vi":"sự bất đồng quan điểm; cuộc tranh cãi"}],"examples":[{"en":"We had a disagreement about whose turn it was.","vi":"Chúng tôi đã xảy ra tranh cãi về việc ai là người đến lượt.","audioKind":"ex"},{"en":"Disagreement over public spending priorities is inevitable, but transparent discussions can help governments build broader support.","vi":"Sự bất đồng về các ưu tiên chi tiêu công là điều không thể tránh khỏi, nhưng các cuộc thảo luận minh bạch có thể giúp chính phủ xây dựng sự ủng hộ rộng rãi hơn.","audioKind":"ex2"}],"collocations":[{"en":"a disagreement over something","vi":"mâu thuẫn về một vấn đề gì đó"},{"en":"a disagreement between","vi":"sự bất đồng giữa"},{"en":"resolve a disagreement","vi":"giải quyết bất đồng"},{"en":"be in disagreement","vi":"bất đồng ý kiến"}],"wordFamily":["disagree (v.)","agree (v.)","agreement (n.)"],"synonyms":["difference of opinion","dispute"],"antonyms":["agreement","consensus"],"tipVi":"Sự tranh cãi cụ thể có thể đếm được; khi nói chung về việc bất đồng quan điểm thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_elder', 'en-b2-17', 'elder', '/ˈeldɚ/', 'B2', 'lớn tuổi hơn (thường trong cùng gia đình); người lớn tuổi, bậc trưởng bối (được cộng đồng kính trọng)', 'adj.', 'elderly (adj.)', 'Đồng nghĩa: older, senior · Trái nghĩa: younger', 'elder đa số đứng trước danh từ chỉ người thân; để so sánh tuổi tác, dùng older than.', 'My elder sister taught me how to ride a bicycle.', NULL, 'Chị gái đã dạy tôi cách đi xe đạp.', '{"wordId":"elder","ukIpa":"/ˈeldə/","usIpa":"/ˈeldɚ/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Older than another person, especially within the same family","vi":"lớn tuổi hơn (thường trong cùng gia đình)"},{"pos":"n.","en":"An older person, especially one respected within a community","vi":"người lớn tuổi, bậc trưởng bối (được cộng đồng kính trọng)"}],"examples":[{"en":"My elder sister taught me how to ride a bicycle.","vi":"Chị gái đã dạy tôi cách đi xe đạp.","audioKind":"ex"},{"en":"Community elders can help preserve local traditions by sharing their knowledge and experiences with younger generations.","vi":"Các bậc cao niên trong cộng đồng có thể giúp gìn giữ truyền thống địa phương bằng cách chia sẻ kiến thức và kinh nghiệm của mình cho các thế hệ trẻ.","audioKind":"ex2"}],"collocations":[{"en":"elder brother","vi":"anh trai"},{"en":"elder sister","vi":"chị gái"},{"en":"community elders","vi":"các bậc cao niên trong cộng đồng"},{"en":"respect your elders","vi":"kính trọng người lớn tuổi"}],"wordFamily":["elderly (adj.)"],"synonyms":["older","senior"],"antonyms":["younger"],"tipVi":"elder đa số đứng trước danh từ chỉ người thân; để so sánh tuổi tác, dùng older than.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_survivor', 'en-b2-17', 'survivor', '/sərˈvaɪvər/', 'B2', 'người sống sót; người <b>còn sống</b>', 'n.', 'survive (v.), survival (n.)', NULL, 'Survivor chỉ người; survival chỉ sự sinh tồn.', 'Rescuers pulled a survivor from the flooded house.', NULL, 'Nhân viên cứu hộ đã đưa một người sống sót ra khỏi ngôi nhà bị ngập lụt.', '{"wordId":"survivor","ukIpa":"/səˈvaɪvə/","usIpa":"/sərˈvaɪvər/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"Someone who remains alive after danger, illness, or disaster.","vi":"người sống sót; người <b>còn sống</b>"}],"examples":[{"en":"Rescuers pulled a survivor from the flooded house.","vi":"Nhân viên cứu hộ đã đưa một người sống sót ra khỏi ngôi nhà bị ngập lụt.","audioKind":"ex"},{"en":"Every disaster survivor should have access to safe housing, medical treatment, and long-term psychological support.","vi":"Mỗi người sống sót sau thảm họa đều nên được tiếp cận nhà ở an toàn, điều trị y tế và hỗ trợ tâm lý dài hạn.","audioKind":"ex2"}],"collocations":[{"en":"sole survivor","vi":"người sống sót duy nhất"},{"en":"earthquake survivor","vi":"người sống sót sau động đất"},{"en":"cancer survivor","vi":"người chiến thắng căn bệnh ung thư"}],"wordFamily":["survive (v.)","survival (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Survivor chỉ người; survival chỉ sự sinh tồn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_diverse', 'en-b2-17', 'diverse', '/daɪˈvɝːs/', 'B2', 'đa dạng; phong phú', 'adj.', 'diversity (n.), diversify (v.), diversification (n.)', 'Đồng nghĩa: varied, wide-ranging · Trái nghĩa: uniform, homogeneous', 'Từ diverse nhấn mạnh sự đa dạng về chủng loại hoặc khác biệt lớn, thường dùng để bổ nghĩa cho nhóm hoặc phạm vi.', 'Our garden attracts a diverse range of colourful birds.', NULL, 'Khu vườn nhà chúng tôi thu hút rất nhiều loài chim đầy màu sắc khác nhau.', '{"wordId":"diverse","ukIpa":"/daɪˈvɜːs/","usIpa":"/daɪˈvɝːs/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Including many different kinds of people or things.","vi":"đa dạng; phong phú"}],"examples":[{"en":"Our garden attracts a diverse range of colourful birds.","vi":"Khu vườn nhà chúng tôi thu hút rất nhiều loài chim đầy màu sắc khác nhau.","audioKind":"ex"},{"en":"A culturally diverse workforce can bring fresh perspectives and improve an organisation''s ability to solve problems.","vi":"Đội ngũ nhân sự đa dạng về văn hóa có thể mang lại những góc nhìn mới mẻ và nâng cao năng lực giải quyết vấn đề của tổ chức.","audioKind":"ex2"}],"collocations":[{"en":"diverse backgrounds","vi":"các nền tảng đa dạng"},{"en":"diverse range","vi":"nhiều loại phong phú"},{"en":"culturally diverse","vi":"đa dạng về mặt văn hóa"},{"en":"diverse needs","vi":"các nhu cầu đa dạng"}],"wordFamily":["diversity (n.)","diversify (v.)","diversification (n.)"],"synonyms":["varied","wide-ranging"],"antonyms":["uniform","homogeneous"],"tipVi":"Từ diverse nhấn mạnh sự đa dạng về chủng loại hoặc khác biệt lớn, thường dùng để bổ nghĩa cho nhóm hoặc phạm vi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_presence', 'en-b2-17', 'presence', '/ˈprezns/', 'B2', 'sự có mặt; sự hiện diện; sự tồn tại; khí chất; phong thái', 'n.', 'present (adj.)', 'Trái nghĩa: absence', 'In someone''s presence nghĩa là có mặt hoặc đứng trước mặt ai đó.', 'Her presence at the concert made her daughter smile.', NULL, 'Sự có mặt của cô ấy tại buổi hòa nhạc đã làm con gái cô nở nụ cười.', '{"wordId":"presence","ukIpa":"/ˈprezns/","usIpa":"/ˈprezns/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"The state of being in a particular place.","vi":"sự có mặt; sự hiện diện"},{"pos":"n.","en":"The fact that something exists in a place or situation.","vi":"sự tồn tại"},{"pos":"n.","en":"A quality that makes someone noticeable and impressive.","vi":"khí chất; phong thái"}],"examples":[{"en":"Her presence at the concert made her daughter smile.","vi":"Sự có mặt của cô ấy tại buổi hòa nhạc đã làm con gái cô nở nụ cười.","audioKind":"ex"},{"en":"The presence of green spaces in urban neighbourhoods can improve residents'' physical and mental health.","vi":"Sự hiện diện của các mảng xanh trong khu dân cư đô thị có thể cải thiện sức khỏe thể chất và tinh thần của cư dân.","audioKind":"ex2"}],"collocations":[{"en":"in someone''s presence","vi":"trước mặt ai đó"},{"en":"the presence of","vi":"sự hiện diện của"},{"en":"stage presence","vi":"phong thái biểu diễn trên sân khấu"}],"wordFamily":["present (adj.)"],"synonyms":[],"antonyms":["absence"],"tipVi":"In someone''s presence nghĩa là có mặt hoặc đứng trước mặt ai đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deprive', 'en-b2-17', 'deprive', '/dɪˈpraɪv/', 'B2', 'tước đoạt; làm cho mất đi', 'v.', 'deprivation (n.), deprived (adj.)', NULL, 'Cấu trúc cố định deprive sb of sth, giới từ đi kèm là of.', 'The noisy roadworks deprived us of sleep all week.', NULL, 'Công trình đường sá ồn ào đã làm chúng tôi mất ngủ suốt cả tuần.', '{"wordId":"deprive","ukIpa":"/dɪˈpraɪv/","usIpa":"/dɪˈpraɪv/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"to prevent someone from having something they need or value","vi":"tước đoạt; làm cho mất đi"}],"examples":[{"en":"The noisy roadworks deprived us of sleep all week.","vi":"Công trình đường sá ồn ào đã làm chúng tôi mất ngủ suốt cả tuần.","audioKind":"ex"},{"en":"Unequal access to technology can deprive disadvantaged students of valuable opportunities to develop essential digital skills.","vi":"Sự tiếp cận công nghệ không bình đẳng có thể tước đi của học sinh có hoàn cảnh khó khăn những cơ hội quý giá để phát triển các kỹ năng số thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"deprive someone of something","vi":"tước đoạt cái gì của ai"},{"en":"deprive someone of sleep","vi":"làm cho ai mất ngủ"},{"en":"deprive someone of opportunities","vi":"tước đoạt cơ hội của ai"}],"wordFamily":["deprivation (n.)","deprived (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc cố định deprive sb of sth, giới từ đi kèm là of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deed', 'en-b2-17', 'deed', '/diːd/', 'B2', 'việc làm; hành động; chiến công; văn bản pháp lý; khế ước; giấy chứng nhận quyền sở hữu', 'n.', NULL, 'Đồng nghĩa: act, action', 'Mang nghĩa hành động thì từ này khá trang trọng; khế ước nhà đất thường dùng ở dạng số nhiều deeds.', 'Helping our neighbour carry groceries was a kind deed.', NULL, 'Giúp hàng xóm xách đồ tạp hóa là một việc làm tốt.', '{"wordId":"deed","ukIpa":"/diːd/","usIpa":"/diːd/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"an action, especially one that is notably good or bad","vi":"việc làm; hành động; chiến công"},{"pos":"n.","en":"a legal document proving ownership or recording an agreement","vi":"văn bản pháp lý; khế ước; giấy chứng nhận quyền sở hữu"}],"examples":[{"en":"Helping our neighbour carry groceries was a kind deed.","vi":"Giúp hàng xóm xách đồ tạp hóa là một việc làm tốt.","audioKind":"ex"},{"en":"Recognising good deeds in schools can encourage students to take greater responsibility for their local communities.","vi":"Việc công nhận những việc làm tốt ở trường học có thể khuyến khích học sinh có ý thức trách nhiệm lớn hơn đối với cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a good deed","vi":"một việc làm tốt"},{"en":"heroic deeds","vi":"những chiến công anh dũng"},{"en":"title deeds","vi":"văn bản chuyển nhượng quyền sở hữu"},{"en":"in word and deed","vi":"trong lời nói và việc làm"}],"wordFamily":[],"synonyms":["act","action"],"antonyms":[],"tipVi":"Mang nghĩa hành động thì từ này khá trang trọng; khế ước nhà đất thường dùng ở dạng số nhiều deeds.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_abandon', 'en-b2-17', 'abandon', '/əˈbændən/', 'B2', 'bỏ rơi; ruồng bỏ; bỏ mặc; từ bỏ; chấm dứt; bỏ dở; sự buông thả; sự vô tư lự không kiềm chế', 'v.', 'abandoned (adj.), abandonment (n.)', 'Đồng nghĩa: desert, forsake', 'abandon đi thẳng với tân ngữ; danh từ thường gặp trong cụm with abandon.', 'We had to abandon our car in the snow.', NULL, 'Chúng tôi buộc phải bỏ lại chiếc ô tô của mình giữa trời tuyết.', '{"wordId":"abandon","ukIpa":"/əˈbændən/","usIpa":"/əˈbændən/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"To leave someone or something without intending to return.","vi":"bỏ rơi; ruồng bỏ; bỏ mặc"},{"pos":"v.","en":"To stop doing or pursuing something before it is finished.","vi":"từ bỏ; chấm dứt; bỏ dở"},{"pos":"n.","en":"A lack of restraint in expressing feelings or enjoying yourself.","vi":"sự buông thả; sự vô tư lự không kiềm chế"}],"examples":[{"en":"We had to abandon our car in the snow.","vi":"Chúng tôi buộc phải bỏ lại chiếc ô tô của mình giữa trời tuyết.","audioKind":"ex"},{"en":"Cities should not abandon ambitious recycling programmes simply because initial participation rates are lower than expected.","vi":"Các thành phố không nên từ bỏ các chương trình tái chế đầy tham vọng chỉ vì tỷ lệ tham gia ban đầu thấp hơn dự kiến.","audioKind":"ex2"}],"collocations":[{"en":"abandon a vehicle","vi":"bỏ lại phương tiện"},{"en":"abandon a plan","vi":"từ bỏ một kế hoạch"},{"en":"abandon hope","vi":"từ bỏ hy vọng"},{"en":"with abandon","vi":"một cách cuồng nhiệt; hoàn toàn thả lỏng"}],"wordFamily":["abandoned (adj.)","abandonment (n.)"],"synonyms":["desert","forsake"],"antonyms":[],"tipVi":"abandon đi thẳng với tân ngữ; danh từ thường gặp trong cụm with abandon.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sibling', 'en-b2-17', 'sibling', '/ˈsɪblɪŋ/', 'B2', 'anh chị em ruột', 'n.', NULL, NULL, 'Danh từ đếm được, số ít chỉ một người anh hoặc em, không phân biệt giới tính.', 'My younger sibling always borrows my favourite blue jacket.', NULL, 'Đứa em của tôi lúc nào cũng mượn chiếc áo khoác màu xanh dương yêu thích của tôi.', '{"wordId":"sibling","ukIpa":"/ˈsɪblɪŋ/","usIpa":"/ˈsɪblɪŋ/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"a brother or sister","vi":"anh chị em ruột"}],"examples":[{"en":"My younger sibling always borrows my favourite blue jacket.","vi":"Đứa em của tôi lúc nào cũng mượn chiếc áo khoác màu xanh dương yêu thích của tôi.","audioKind":"ex"},{"en":"Children with siblings may develop negotiation skills early by sharing toys and resolving disagreements at home.","vi":"Trẻ em có anh chị em ruột có thể phát triển kỹ năng thương lượng từ sớm thông qua việc chia sẻ đồ chơi và giải quyết bất đồng ở nhà.","audioKind":"ex2"}],"collocations":[{"en":"older sibling","vi":"anh/chị lớn"},{"en":"younger sibling","vi":"em trai/em gái"},{"en":"sibling rivalry","vi":"sự cạnh tranh giữa các anh chị em"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ đếm được, số ít chỉ một người anh hoặc em, không phân biệt giới tính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_alien', 'en-b2-17', 'alien', '/ˈeɪliən/', 'B2', 'xa lạ; khác biệt; không quen thuộc; sinh vật ngoài hành tinh; ngoại lai; xa lạ với môi trường tự nhiên bản địa', 'adj.', 'alienate (v.), alienation (n.)', 'Đồng nghĩa: unfamiliar, foreign · Trái nghĩa: familiar', 'Gói gọn người nước ngoài bằng từ alien có thể mang sắc thái xa cách; thường dùng foreign national chuẩn hơn.', 'The city''s constant noise felt alien after our quiet village.', NULL, 'Tiếng ồn ào liên tục của thành phố khiến chúng tôi cảm thấy xa lạ sau quãng thời gian ở ngôi làng yên tĩnh.', '{"wordId":"alien","ukIpa":"/ˈeɪliən/","usIpa":"/ˈeɪliən/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Unfamiliar or very different from what someone knows or accepts","vi":"xa lạ; khác biệt; không quen thuộc"},{"pos":"n.","en":"A living creature believed or imagined to come from another planet","vi":"sinh vật ngoài hành tinh"},{"pos":"adj.","en":"Coming from a different country or natural environment","vi":"ngoại lai; xa lạ với môi trường tự nhiên bản địa"}],"examples":[{"en":"The city''s constant noise felt alien after our quiet village.","vi":"Tiếng ồn ào liên tục của thành phố khiến chúng tôi cảm thấy xa lạ sau quãng thời gian ở ngôi làng yên tĩnh.","audioKind":"ex"},{"en":"Teaching methods that seem alien to international students may require careful explanation and additional support from university staff.","vi":"Các phương pháp giảng dạy có vẻ xa lạ với sinh viên quốc tế có thể đòi hỏi sự giải thích cẩn thận và hỗ trợ thêm từ nhân viên trường đại học.","audioKind":"ex2"}],"collocations":[{"en":"alien to","vi":"xa lạ với"},{"en":"alien species","vi":"loài ngoại lai"},{"en":"alien environment","vi":"môi trường xa lạ"},{"en":"alien life","vi":"sự sống ngoài hành tinh"}],"wordFamily":["alienate (v.)","alienation (n.)"],"synonyms":["unfamiliar","foreign"],"antonyms":["familiar"],"tipVi":"Gói gọn người nước ngoài bằng từ alien có thể mang sắc thái xa cách; thường dùng foreign national chuẩn hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_compromise', 'en-b2-17', 'compromise', '/ˈkɑːmprəmaɪz/', 'B2', 'sự thỏa hiệp; giải pháp dung hòa; phương án đôi bên cùng nhượng bộ; thỏa hiệp; nhượng bộ; đạt được thỏa thuận dung hòa; làm phương hại; gây tổn hại; đặt vào tình thế nguy hiểm', 'n.', 'compromising (adj.), uncompromising (adj.)', NULL, 'Cấu trúc compromise on dùng để chỉ việc nhượng bộ về một vấn đề; khi đi trực tiếp với tân ngữ, từ này mang nghĩa làm tổn hại.', 'We reached a compromise and shared the last biscuit.', NULL, 'Chúng tôi đã đạt được một sự thỏa hiệp và chia nhau chiếc bánh quy cuối cùng.', '{"wordId":"compromise","ukIpa":"/ˈkɒmprəmaɪz/","usIpa":"/ˈkɑːmprəmaɪz/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"An agreement in which each side accepts less than originally wanted.","vi":"sự thỏa hiệp; giải pháp dung hòa; phương án đôi bên cùng nhượng bộ"},{"pos":"v.","en":"To reach agreement by accepting less than you originally wanted.","vi":"thỏa hiệp; nhượng bộ; đạt được thỏa thuận dung hòa"},{"pos":"v.","en":"To weaken or put something valuable at risk.","vi":"làm phương hại; gây tổn hại; đặt vào tình thế nguy hiểm"}],"examples":[{"en":"We reached a compromise and shared the last biscuit.","vi":"Chúng tôi đã đạt được một sự thỏa hiệp và chia nhau chiếc bánh quy cuối cùng.","audioKind":"ex"},{"en":"Governments must find a compromise between expanding housing supply and protecting green spaces in densely populated cities.","vi":"Chính phủ phải tìm ra một giải pháp dung hòa giữa việc mở rộng nguồn cung nhà ở và bảo vệ không gian xanh tại các thành phố đông dân cư.","audioKind":"ex2"}],"collocations":[{"en":"reach a compromise","vi":"đạt được thỏa hiệp"},{"en":"compromise on","vi":"thỏa hiệp về vấn đề gì"},{"en":"compromise safety","vi":"làm phương hại đến an toàn"},{"en":"a reasonable compromise","vi":"một giải pháp thỏa hiệp hợp lý"}],"wordFamily":["compromising (adj.)","uncompromising (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc compromise on dùng để chỉ việc nhượng bộ về một vấn đề; khi đi trực tiếp với tân ngữ, từ này mang nghĩa làm tổn hại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_interference', 'en-b2-17', 'interference', '/ˌɪntərˈfɪrəns/', 'B2', 'sự can thiệp; sự nhúng tay; sự cản trở; sự gây nhiễu; nhiễu tín hiệu', 'n.', 'interfere (v.), interfering (adj.)', NULL, 'Giới từ in thường đi với các vấn đề mang nghĩa can thiệp; with thường đi với các hoạt động mang nghĩa cản trở.', 'I wanted to choose my clothes without anyone''s interference.', NULL, 'Tôi muốn tự chọn quần áo của mình mà không có sự can thiệp của bất kỳ ai.', '{"wordId":"interference","ukIpa":"/ˌɪntəˈfɪərəns/","usIpa":"/ˌɪntərˈfɪrəns/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"unwanted involvement in someone else''s affairs or decisions","vi":"sự can thiệp; sự nhúng tay"},{"pos":"n.","en":"an action or influence that disrupts an activity or process","vi":"sự cản trở; sự gây nhiễu"},{"pos":"n.","en":"unwanted signals that reduce the quality of electronic reception","vi":"nhiễu tín hiệu"}],"examples":[{"en":"I wanted to choose my clothes without anyone''s interference.","vi":"Tôi muốn tự chọn quần áo của mình mà không có sự can thiệp của bất kỳ ai.","audioKind":"ex"},{"en":"Universities need protection from political interference to ensure that research findings remain independent and credible.","vi":"Các trường đại học cần được bảo vệ khỏi sự can thiệp chính trị để đảm bảo rằng các kết quả nghiên cứu vẫn giữ được tính độc lập và đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"interference in domestic affairs","vi":"can thiệp vào công việc nội bộ"},{"en":"political interference","vi":"can thiệp chính trị"},{"en":"interference with sleep","vi":"sự cản trở giấc ngủ"},{"en":"radio interference","vi":"nhiễu sóng vô tuyến"}],"wordFamily":["interfere (v.)","interfering (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Giới từ in thường đi với các vấn đề mang nghĩa can thiệp; with thường đi với các hoạt động mang nghĩa cản trở.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_influential', 'en-b2-17', 'influential', '/ˌɪnfluˈenʃəl/', 'B2', 'có tầm ảnh hưởng; có sức ảnh hưởng lớn', 'adj.', 'influence (n.), influence (v.)', 'Trái nghĩa: uninfluential', 'Thường dùng be influential in doing, thể hiện có ảnh hưởng trong việc làm gì.', 'Her grandfather was an influential teacher in their village.', NULL, 'Ông của cô ấy từng là một giáo viên có sức ảnh hưởng trong ngôi làng của họ.', '{"wordId":"influential","ukIpa":"/ˌɪnfluˈenʃəl/","usIpa":"/ˌɪnfluˈenʃəl/","cefr":"B2","topic":"society","senses":[{"pos":"adj.","en":"Able to strongly affect people''s opinions, decisions, or actions.","vi":"có tầm ảnh hưởng; có sức ảnh hưởng lớn"}],"examples":[{"en":"Her grandfather was an influential teacher in their village.","vi":"Ông của cô ấy từng là một giáo viên có sức ảnh hưởng trong ngôi làng của họ.","audioKind":"ex"},{"en":"Scientific advisers can be influential in shaping government policies on public health and environmental protection.","vi":"Các cố vấn khoa học có thể đóng vai trò có tầm ảnh hưởng trong việc định hình các chính sách của chính phủ về y tế công cộng và bảo vệ môi trường.","audioKind":"ex2"}],"collocations":[{"en":"influential figure","vi":"nhân vật có tầm ảnh hưởng"},{"en":"highly influential","vi":"có ảnh hưởng lớn"},{"en":"influential in shaping policy","vi":"có sức ảnh hưởng trong việc định hình chính sách"}],"wordFamily":["influence (n.)","influence (v.)"],"synonyms":[],"antonyms":["uninfluential"],"tipVi":"Thường dùng be influential in doing, thể hiện có ảnh hưởng trong việc làm gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_generosity', 'en-b2-17', 'generosity', '/ˌdʒenəˈrɑːsəti/', 'B2', 'sự hào phóng; tính rộng lượng; lòng bao dung; sự rộng lượng', 'n.', 'generous (adj.), generously (adv.)', 'Đồng nghĩa: munificence, kindness · Trái nghĩa: stinginess', 'Thường không đếm được; một hành động hào phóng dùng an act of generosity.', 'Thanks to your generosity, everyone has a warm coat.', NULL, 'Nhờ có lòng hào phóng của bạn mà ai nấy đều có một chiếc áo khoác ấm áp.', '{"wordId":"generosity","ukIpa":"/ˌdʒenəˈrɒsəti/","usIpa":"/ˌdʒenəˈrɑːsəti/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"Willingness to give money, time, or help freely.","vi":"sự hào phóng; tính rộng lượng"},{"pos":"n.","en":"Willingness to be kind and forgiving towards others.","vi":"lòng bao dung; sự rộng lượng"}],"examples":[{"en":"Thanks to your generosity, everyone has a warm coat.","vi":"Nhờ có lòng hào phóng của bạn mà ai nấy đều có một chiếc áo khoác ấm áp.","audioKind":"ex"},{"en":"Community projects often depend on the generosity of residents who contribute both money and valuable practical skills.","vi":"Các dự án cộng đồng thường phụ thuộc vào sự đóng góp hào phóng của cư dân, những người vừa tài trợ tiền vừa đóng góp các kỹ năng thực tế quý giá.","audioKind":"ex2"}],"collocations":[{"en":"show generosity","vi":"thể hiện sự hào phóng"},{"en":"an act of generosity","vi":"hành động hào phóng"},{"en":"generosity towards others","vi":"lòng hào phóng đối với người khác"}],"wordFamily":["generous (adj.)","generously (adv.)"],"synonyms":["munificence","kindness"],"antonyms":["stinginess"],"tipVi":"Thường không đếm được; một hành động hào phóng dùng an act of generosity.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_youngster', 'en-b2-17', 'youngster', '/ˈjʌŋstər/', 'B2', 'đứa trẻ; thanh thiếu niên', 'n.', 'young (adj.), youth (n.), youthful (adj.)', 'Đồng nghĩa: child, young person', 'Dùng cho cả nam và nữ, sắc thái gần gũi; văn phong trang trọng hơn có thể dùng young people.', 'A cheerful youngster helped me pick up the apples.', NULL, 'Một đứa trẻ vui vẻ đã giúp tôi nhặt những quả táo lên.', '{"wordId":"youngster","ukIpa":"/ˈjʌŋstə/","usIpa":"/ˈjʌŋstər/","cefr":"B2","topic":"society","senses":[{"pos":"n.","en":"A child or young person.","vi":"đứa trẻ; thanh thiếu niên"}],"examples":[{"en":"A cheerful youngster helped me pick up the apples.","vi":"Một đứa trẻ vui vẻ đã giúp tôi nhặt những quả táo lên.","audioKind":"ex"},{"en":"Community sports programmes give youngsters opportunities to develop teamwork skills and build friendships outside school.","vi":"Các chương trình thể thao cộng đồng mang đến cho giới trẻ cơ hội phát triển kỹ năng làm việc nhóm và xây dựng tình bạn ngoài trường học.","audioKind":"ex2"}],"collocations":[{"en":"local youngsters","vi":"giới trẻ địa phương"},{"en":"talented youngsters","vi":"những người trẻ tài năng"},{"en":"a group of youngsters","vi":"một nhóm trẻ em"}],"wordFamily":["young (adj.)","youth (n.)","youthful (adj.)"],"synonyms":["child","young person"],"antonyms":[],"tipVi":"Dùng cho cả nam và nữ, sắc thái gần gũi; văn phong trang trọng hơn có thể dùng young people.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_swear', 'en-b2-17', 'swear', '/swer/', 'B2', 'nói tục; chửi thề; thề; cam đoan', 'v.', 'swearing (n.)', 'Đồng nghĩa: curse, vow', 'Dạng quá khứ là swore, quá khứ phân từ là sworn; swear at có nghĩa là chửi mắng.', 'Please don''t swear when the game goes wrong.', NULL, 'Xin đừng nói tục khi chơi game không suôn sẻ.', '{"wordId":"swear","ukIpa":"/sweə/","usIpa":"/swer/","cefr":"B2","topic":"society","senses":[{"pos":"v.","en":"to use rude or offensive words","vi":"nói tục; chửi thề"},{"pos":"v.","en":"to make a serious promise or insist something is true","vi":"thề; cam đoan"}],"examples":[{"en":"Please don''t swear when the game goes wrong.","vi":"Xin đừng nói tục khi chơi game không suôn sẻ.","audioKind":"ex"},{"en":"Witnesses must swear to tell the truth before giving evidence in many legal systems.","vi":"Trong nhiều hệ thống pháp luật, nhân chứng phải tuyên bố thề nói sự thật trước khi đưa ra lời khai.","audioKind":"ex2"}],"collocations":[{"en":"swear at someone","vi":"chửi mắng ai đó"},{"en":"swear to do something","vi":"thề làm điều gì đó"},{"en":"swear an oath","vi":"tuyên thệ"}],"wordFamily":["swearing (n.)"],"synonyms":["curse","vow"],"antonyms":[],"tipVi":"Dạng quá khứ là swore, quá khứ phân từ là sworn; swear at có nghĩa là chửi mắng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_17_1', 'en-b2-17', 'Cách dùng “compromise” (n.) — sự thỏa hiệp; giải pháp dung hòa; phương án đôi bên cùng nhượng bộ', 'reach a compromise  ·  compromise on  ·  compromise safety', 'Cấu trúc compromise on dùng để chỉ việc nhượng bộ về một vấn đề; khi đi trực tiếp với tân ngữ, từ này mang nghĩa làm tổn hại.', 'Họ từ (Word Family): compromising (adj.), uncompromising (adj.)', '[{"hanzi":"We reached a compromise and shared the last biscuit.","pinyin":"","meaning":"Chúng tôi đã đạt được một sự thỏa hiệp và chia nhau chiếc bánh quy cuối cùng."},{"hanzi":"Governments must find a compromise between expanding housing supply and protecting green spaces in densely populated cities.","pinyin":"","meaning":"Chính phủ phải tìm ra một giải pháp dung hòa giữa việc mở rộng nguồn cung nhà ở và bảo vệ không gian xanh tại các thành phố đông dân cư."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_17_2', 'en-b2-17', 'Cách dùng “diverse” (adj.) — đa dạng; phong phú', 'diverse backgrounds  ·  diverse range  ·  culturally diverse', 'Từ diverse nhấn mạnh sự đa dạng về chủng loại hoặc khác biệt lớn, thường dùng để bổ nghĩa cho nhóm hoặc phạm vi.', 'Họ từ (Word Family): diversity (n.), diversify (v.), diversification (n.) | Đồng nghĩa: varied, wide-ranging · Trái nghĩa: uniform, homogeneous', '[{"hanzi":"Our garden attracts a diverse range of colourful birds.","pinyin":"","meaning":"Khu vườn nhà chúng tôi thu hút rất nhiều loài chim đầy màu sắc khác nhau."},{"hanzi":"A culturally diverse workforce can bring fresh perspectives and improve an organisation''s ability to solve problems.","pinyin":"","meaning":"Đội ngũ nhân sự đa dạng về văn hóa có thể mang lại những góc nhìn mới mẻ và nâng cao năng lực giải quyết vấn đề của tổ chức."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_17_3', 'en-b2-17', 'Cách dùng “interference” (n.) — sự can thiệp; sự nhúng tay', 'interference in domestic affairs  ·  political interference  ·  interference with sleep', 'Giới từ in thường đi với các vấn đề mang nghĩa can thiệp; with thường đi với các hoạt động mang nghĩa cản trở.', 'Họ từ (Word Family): interfere (v.), interfering (adj.)', '[{"hanzi":"I wanted to choose my clothes without anyone''s interference.","pinyin":"","meaning":"Tôi muốn tự chọn quần áo của mình mà không có sự can thiệp của bất kỳ ai."},{"hanzi":"Universities need protection from political interference to ensure that research findings remain independent and credible.","pinyin":"","meaning":"Các trường đại học cần được bảo vệ khỏi sự can thiệp chính trị để đảm bảo rằng các kết quả nghiên cứu vẫn giữ được tính độc lập và đáng tin cậy."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_17_4', 'en-b2-17', 'Cách dùng “alien” (adj.) — xa lạ; khác biệt; không quen thuộc', 'alien to  ·  alien species  ·  alien environment', 'Gói gọn người nước ngoài bằng từ alien có thể mang sắc thái xa cách; thường dùng foreign national chuẩn hơn.', 'Họ từ (Word Family): alienate (v.), alienation (n.) | Đồng nghĩa: unfamiliar, foreign · Trái nghĩa: familiar', '[{"hanzi":"The city''s constant noise felt alien after our quiet village.","pinyin":"","meaning":"Tiếng ồn ào liên tục của thành phố khiến chúng tôi cảm thấy xa lạ sau quãng thời gian ở ngôi làng yên tĩnh."},{"hanzi":"Teaching methods that seem alien to international students may require careful explanation and additional support from university staff.","pinyin":"","meaning":"Các phương pháp giảng dạy có vẻ xa lạ với sinh viên quốc tế có thể đòi hỏi sự giải thích cẩn thận và hỗ trợ thêm từ nhân viên trường đại học."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_17_1', 'en-b2-17', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
