INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_17_1_2', 'ten_b2_17_1', 'homeless', 'The flood left several families homeless in our town.', 'The flood left several families homeless in our town.', '/ˈhoʊmləs/', 'Trận lũ lụt đã khiến nhiều gia đình ở thị trấn chúng tôi rơi vào cảnh màn trời chiếu đất.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_17_1_3', 'ten_b2_17_1', 'outsider', 'At first, I felt like an outsider at school.', 'At first, I felt like an outsider at school.', '/ˌaʊtˈsaɪdɚ/', 'Lúc đầu, tôi cảm thấy mình giống như một người ngoài cuộc ở trường học.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_17_1_4', 'ten_b2_17_1', 'freely', 'The chickens wander freely around the garden all day.', 'The chickens wander freely around the garden all day.', '/ˈfriːli/', 'Những con gà đi lại tự do quanh khu vườn cả ngày.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_17_1_5', 'ten_b2_17_1', 'mature', 'Leila gave a mature response when her plans changed.', 'Leila gave a mature response when her plans changed.', '/məˈtʃʊr/', 'Leila đã có phản ứng rất chín chắn khi kế hoạch của cô ấy thay đổi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_17_1_6', 'ten_b2_17_1', 'greed', 'His greed left everyone else without any cake.', 'His greed left everyone else without any cake.', '/ɡriːd/', 'Lòng tham của anh ta khiến mọi người chẳng còn chút bánh nào.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_17_1_7', 'ten_b2_17_1', 'refusal', 'His polite refusal did not upset the host.', 'His polite refusal did not upset the host.', '/rɪˈfjuːzəl/', 'Lời từ chối lịch sự của anh ấy không làm chủ nhà khó chịu.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_17_1_8', 'ten_b2_17_1', 'brag', 'He always brags about how fast he can swim.', 'He always brags about how fast he can swim.', '/bræɡ/', 'Anh ta luôn khoác lác về việc mình bơi giỏi đến mức nào.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_17_1_1', 'en-b2-17', 'ten_b2_17_1', 'listening', 'listening', 'Every inhabitant of the village helped repair the bridge.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tiếng ồn ào liên tục của thành phố khiến chúng tôi cảm thấy xa lạ sau quãng thời gian ở ngôi làng yên tĩnh.","Một đứa trẻ vui vẻ đã giúp tôi nhặt những quả táo lên.","Chúng tôi đã đạt được một sự thỏa hiệp và chia nhau chiếc bánh quy cuối cùng.","Mỗi cư dân trong làng đều chung tay sửa chữa cây cầu."]'::jsonb, 3, 'Every inhabitant of the village helped repair the bridge. → Mỗi cư dân trong làng đều chung tay sửa chữa cây cầu.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_17_1_2', 'en-b2-17', 'ten_b2_17_1', 'listening', 'listening', 'The flood left several families homeless in our town.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những con gà đi lại tự do quanh khu vườn cả ngày.","Mỗi cư dân trong làng đều chung tay sửa chữa cây cầu.","Trận lũ lụt đã khiến nhiều gia đình ở thị trấn chúng tôi rơi vào cảnh màn trời chiếu đất.","Leila đã có phản ứng rất chín chắn khi kế hoạch của cô ấy thay đổi."]'::jsonb, 2, 'The flood left several families homeless in our town. → Trận lũ lụt đã khiến nhiều gia đình ở thị trấn chúng tôi rơi vào cảnh màn trời chiếu đất.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_17_1_3', 'en-b2-17', 'ten_b2_17_1', 'listening', 'listening', 'At first, I felt like an outsider at school.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi muốn tự chọn quần áo của mình mà không có sự can thiệp của bất kỳ ai.","Lúc đầu, tôi cảm thấy mình giống như một người ngoài cuộc ở trường học.","Chúng tôi đã đạt được một sự thỏa hiệp và chia nhau chiếc bánh quy cuối cùng.","Tiếng ồn ào liên tục của thành phố khiến chúng tôi cảm thấy xa lạ sau quãng thời gian ở ngôi làng yên tĩnh."]'::jsonb, 1, 'At first, I felt like an outsider at school. → Lúc đầu, tôi cảm thấy mình giống như một người ngoài cuộc ở trường học.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_17_2', 'en-b2-17', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_17_2_1', 'ten_b2_17_2', 'inhabitant', 'Rapid urban growth can place pressure on housing and reduce access to green spaces for local inhabitants.', 'Rapid urban growth can place pressure on housing and reduce access to green spaces for local inhabitants.', '/ɪnˈhæbɪtənt/', 'Sự bùng nổ đô thị nhanh chóng có thể gây áp lực lên nhà ở và làm giảm không gian xanh cho cư dân địa phương.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_17_2_2', 'ten_b2_17_2', 'homeless', 'Affordable housing and accessible support services are essential to helping homeless people rebuild stable lives.', 'Affordable housing and accessible support services are essential to helping homeless people rebuild stable lives.', '/ˈhoʊmləs/', 'Nhà ở giá rẻ và các dịch vụ hỗ trợ dễ tiếp cận đóng vai trò thiết yếu trong việc giúp người vô gia cư tạo dựng lại cuộc sống ổn định.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_17_2_3', 'ten_b2_17_2', 'outsider', 'An outsider may identify weaknesses in an organisation that its long-standing members have failed to notice.', 'An outsider may identify weaknesses in an organisation that its long-standing members have failed to notice.', '/ˌaʊtˈsaɪdɚ/', 'Một người ngoài cuộc có thể nhận diện ra những điểm yếu trong một tổ chức mà các thành viên lâu năm đã bỏ sót.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_17_2_4', 'ten_b2_17_2', 'freely', 'Students should be able to express their opinions freely while respecting the rights and feelings of others.', 'Students should be able to express their opinions freely while respecting the rights and feelings of others.', '/ˈfriːli/', 'Học sinh nên được tự do bày tỏ quan điểm của mình đồng thời tôn trọng quyền và cảm xúc của người khác.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_17_2_5', 'ten_b2_17_2', 'mature', 'Living independently can help young adults mature as they learn to manage money and resolve everyday problems.', 'Living independently can help young adults mature as they learn to manage money and resolve everyday problems.', '/məˈtʃʊr/', 'Sống tự lập có thể giúp người trẻ trưởng thành hơn khi họ học cách quản lý tiền bạc và giải quyết các vấn đề hàng ngày.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_17_2_6', 'ten_b2_17_2', 'greed', 'Corporate greed can undermine environmental protection when companies prioritise short-term profits over the welfare of local communities.', 'Corporate greed can undermine environmental protection when companies prioritise short-term profits over the welfare of local communities.', '/ɡriːd/', 'Lòng tham của doanh nghiệp có thể làm suy yếu việc bảo vệ môi trường khi các công ty đặt lợi nhuận ngắn hạn lên trên phúc lợi của cộng đồng địa phương.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_17_2_1', 'en-b2-17', 'ten_b2_17_2', 'listening', 'listening', 'Rapid urban growth can place pressure on housing and reduce access to green spaces for local inhabitants.', NULL, 'Trong câu vừa nghe, từ “inhabitant” mang nghĩa nào sau đây?', '["không tính lãi; miễn lãi","cư dân; động thực vật sinh sống tại một nơi","chuyên gia tư vấn tâm lý; người hướng dẫn","niềm tin; lòng tin; sự tín nhiệm"]'::jsonb, 1, '“inhabitant” (/ɪnˈhæbɪtənt/): cư dân; động thực vật sinh sống tại một nơi. Câu đầy đủ: Rapid urban growth can place pressure on housing and reduce access to green spaces for local inhabitants.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_17_2_2', 'en-b2-17', 'ten_b2_17_2', 'listening', 'listening', 'Affordable housing and accessible support services are essential to helping homeless people rebuild stable lives.', NULL, 'Trong câu vừa nghe, từ “homeless” mang nghĩa nào sau đây?', '["nhà ngân hàng; nhân sự cấp cao ngành ngân hàng","thần thánh; thiêng liêng; thánh","vô gia cư","quốc hội; nghị viện"]'::jsonb, 2, '“homeless” (/ˈhoʊmləs/): vô gia cư. Câu đầy đủ: Affordable housing and accessible support services are essential to helping homeless people rebuild stable lives.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
