INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_17_2', 'en-b2-17', 'The flood left several families homeless in our town', 'Trận lũ lụt đã khiến nhiều gia đình ở thị trấn chúng tôi rơi vào cảnh màn trời chiếu đất.', 'homeless /ˈhoʊmləs/', '["town","homeless","in","The","families","flood","our","left","several"]'::jsonb, NULL, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
