INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_17_1', 'en-b2-17', NULL, 'comprehensive_test', 'listening', 'inhabitant', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cư dân; động thực vật sinh sống tại một nơi","nhãn hiệu; thương hiệu đã đăng ký","galông (đơn vị đo thể tích)","sự xung đột; sự trùng lịch"]'::jsonb, 0, 'inhabitant (/ɪnˈhæbɪtənt/) → cư dân; động thực vật sinh sống tại một nơi', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_17_2', 'en-b2-17', NULL, 'comprehensive_test', 'listening', 'The flood left several families homeless in our town.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi buộc phải bỏ lại chiếc ô tô của mình giữa trời tuyết.","Đôi giày này có phù hợp cho việc đi bộ đường dài trên núi không?","Trận lũ lụt đã khiến nhiều gia đình ở thị trấn chúng tôi rơi vào cảnh màn trời chiếu đất.","Nhờ có lòng hào phóng của bạn mà ai nấy đều có một chiếc áo khoác ấm áp."]'::jsonb, 2, 'The flood left several families homeless in our town. → Trận lũ lụt đã khiến nhiều gia đình ở thị trấn chúng tôi rơi vào cảnh màn trời chiếu đất.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_17_3', 'en-b2-17', NULL, 'comprehensive_test', 'listening', 'outsider', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["uyển chuyển; duyên dáng; thanh tú","người ngoài cuộc; kẻ ngoại đạo","sỏi; đá dăm","bạn đồng hành; người bầu bạn; thú cưng bầu bạn"]'::jsonb, 1, 'outsider (/ˌaʊtˈsaɪdɚ/) → người ngoài cuộc; kẻ ngoại đạo; đối thủ không được đánh giá cao', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_17_4', 'en-b2-17', NULL, 'comprehensive_test', 'listening', 'The chickens wander freely around the garden all day.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Công trình đường sá ồn ào đã làm chúng tôi mất ngủ suốt cả tuần.","Leila đã có phản ứng rất chín chắn khi kế hoạch của cô ấy thay đổi.","Những con gà đi lại tự do quanh khu vườn cả ngày.","Lòng tham của anh ta khiến mọi người chẳng còn chút bánh nào."]'::jsonb, 2, 'The chickens wander freely around the garden all day. → Những con gà đi lại tự do quanh khu vườn cả ngày.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_17_5', 'en-b2-17', NULL, 'comprehensive_test', 'listening', 'mature', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chín chắn; trưởng thành; biết điều","thuộc về thành phố; đô thị","hòn cuội; viên đá nhỏ nhẵn","đâm thủng; chọc thủng bằng vật nhọn"]'::jsonb, 0, 'mature (/məˈtʃʊr/) → chín chắn; trưởng thành; biết điều; phát triển hoàn toàn; phát triển hoàn thiện', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_17_6', 'en-b2-17', NULL, 'comprehensive_test', 'listening', 'His greed left everyone else without any cake.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã đạt được một sự thỏa hiệp và chia nhau chiếc bánh quy cuối cùng.","Nhân viên cứu hộ đã đưa một người sống sót ra khỏi ngôi nhà bị ngập lụt.","Một đứa trẻ vui vẻ đã giúp tôi nhặt những quả táo lên.","Lòng tham của anh ta khiến mọi người chẳng còn chút bánh nào."]'::jsonb, 3, 'His greed left everyone else without any cake. → Lòng tham của anh ta khiến mọi người chẳng còn chút bánh nào.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_17_7', 'en-b2-17', NULL, 'comprehensive_test', 'listening', 'refusal', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["có năng lực; có tay nghề; thành thạo","cơ sở vật chất; trang thiết bị; phương tiện","đa dạng; phong phú","sự từ chối; lời khước từ"]'::jsonb, 3, 'refusal (/rɪˈfjuːzəl/) → sự từ chối; lời khước từ', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_17_8', 'en-b2-17', NULL, 'comprehensive_test', 'listening', 'He always brags about how fast he can swim.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Lúc đầu, tôi cảm thấy mình giống như một người ngoài cuộc ở trường học.","Khu vườn nhà chúng tôi thu hút rất nhiều loài chim đầy màu sắc khác nhau.","Nhân viên cứu hộ đã đưa một người sống sót ra khỏi ngôi nhà bị ngập lụt.","Anh ta luôn khoác lác về việc mình bơi giỏi đến mức nào."]'::jsonb, 3, 'He always brags about how fast he can swim. → Anh ta luôn khoác lác về việc mình bơi giỏi đến mức nào.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_17_9', 'en-b2-17', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Behaving sensibly and showing good judgment”?', '["inhabitant","mature","homeless","freely"]'::jsonb, 1, 'mature (/məˈtʃʊr/) → chín chắn; trưởng thành; biết điều', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_17_10', 'en-b2-17', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a strong desire for more than one needs or deserves”?', '["greed","refusal","outsider","freely"]'::jsonb, 0, 'greed (/ɡriːd/) → lòng tham; sự tham lam', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_17_11', 'en-b2-17', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “an act of saying you will not do or accept something”?', '["brag","refusal","elder","presence"]'::jsonb, 1, 'refusal (/rɪˈfjuːzəl/) → sự từ chối; lời khước từ', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_17_12', 'en-b2-17', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to talk too proudly about your achievements or possessions”?', '["brag","deprive","sibling","outsider"]'::jsonb, 0, 'brag (/bræɡ/) → khoác lác; khoe khoang', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_17_13', 'en-b2-17', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “An expression of opposition, or a reason for opposing something.”?', '["diverse","objection","elder","freely"]'::jsonb, 1, 'objection (/əbˈdʒekʃən/) → sự phản đối; lời phản đối; ý kiến phản đối', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
