INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_17_18', 'en-b2-17', NULL, 'comprehensive_test', 'reading', NULL, 'Rapid urban growth can place pressure on housing and reduce access to green spaces for local inhabitants.', 'Dựa vào câu trên, từ “inhabitant” có nghĩa phù hợp nhất là gì?', '["phá rừng; nạn phá rừng","chim bồ câu","cư dân; động thực vật sinh sống tại một nơi","cố ý; chủ tâm"]'::jsonb, 2, 'inhabitant: cư dân; động thực vật sinh sống tại một nơi. Dịch cả câu: Sự bùng nổ đô thị nhanh chóng có thể gây áp lực lên nhà ở và làm giảm không gian xanh cho cư dân địa phương.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_17_19', 'en-b2-17', NULL, 'comprehensive_test', 'reading', NULL, 'Affordable housing and accessible support services are essential to helping homeless people rebuild stable lives.', 'Dựa vào câu trên, từ “homeless” có nghĩa phù hợp nhất là gì?', '["vấp ngã; lạng quạng","vô gia cư","thực tế; khả thi","vui vẻ; thú vị; dễ chịu"]'::jsonb, 1, 'homeless: vô gia cư. Dịch cả câu: Nhà ở giá rẻ và các dịch vụ hỗ trợ dễ tiếp cận đóng vai trò thiết yếu trong việc giúp người vô gia cư tạo dựng lại cuộc sống ổn định.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_17_20', 'en-b2-17', NULL, 'comprehensive_test', 'reading', NULL, 'An outsider may identify weaknesses in an organisation that its long-standing members have failed to notice.', 'Dựa vào câu trên, từ “outsider” có nghĩa phù hợp nhất là gì?', '["người ngoài cuộc; kẻ ngoại đạo","giải trí; mang tính thư giãn","được cho là; theo như người ta nói","sự cho ăn; việc ăn uống; việc cho bú"]'::jsonb, 0, 'outsider: người ngoài cuộc; kẻ ngoại đạo; đối thủ không được đánh giá cao. Dịch cả câu: Một người ngoài cuộc có thể nhận diện ra những điểm yếu trong một tổ chức mà các thành viên lâu năm đã bỏ sót.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_17_21', 'en-b2-17', NULL, 'comprehensive_test', 'reading', NULL, 'Students should be able to express their opinions freely while respecting the rights and feelings of others.', 'Dựa vào câu trên, từ “freely” có nghĩa phù hợp nhất là gì?', '["sự tham gia; sự góp mặt","thuộc về nghệ thuật","tốt hơn; thích hợp hơn; đáng chọn hơn","tự do; không bị ràng buộc"]'::jsonb, 3, 'freely: tự do; không bị ràng buộc; thẳng thắn; cởi mở; tự nguyện; hào phóng. Dịch cả câu: Học sinh nên được tự do bày tỏ quan điểm của mình đồng thời tôn trọng quyền và cảm xúc của người khác.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_17_22', 'en-b2-17', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự hào phóng; tính rộng lượng”', '["generosity","numerical","constantly","exception"]'::jsonb, 0, 'sự hào phóng; tính rộng lượng → generosity (/ˌdʒenəˈrɑːsəti/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_17_23', 'en-b2-17', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đứa trẻ; thanh thiếu niên”', '["distribution","youngster","outlet","slogan"]'::jsonb, 1, 'đứa trẻ; thanh thiếu niên → youngster (/ˈjʌŋstər/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_17_24', 'en-b2-17', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nói tục; chửi thề”', '["swear","stool","cast","incentive"]'::jsonb, 0, 'nói tục; chửi thề → swear (/swer/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-18', 'en', 'Bài 18: Thiên nhiên & Thời tiết (1) - CEFR B2', 'CEFR B2', 'B2 · Thiên nhiên', '28 từ vựng Tiếng Anh CEFR B2 chủ đề thiên nhiên & thời tiết kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4018, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pit', 'en-b2-18', 'pit', '/pɪt/', 'B2', 'cái hố; hầm sâu; khu vực bảo dưỡng xe đua; hột (của một số loại quả)', 'n.', NULL, 'Đồng nghĩa: hole, hollow', 'Khu vực bảo dưỡng xe đua thường dùng the pits; nghĩa chỉ hột trái cây chủ yếu được dùng trong tiếng Anh-Mỹ.', 'We dug a shallow pit for the new tree.', NULL, 'Chúng tôi đã đào một cái hố nông để trồng cây mới.', '{"wordId":"pit","ukIpa":"/pɪt/","usIpa":"/pɪt/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A large hole in the ground","vi":"cái hố; hầm sâu"},{"pos":"n.","en":"An area where racing cars stop for servicing","vi":"khu vực bảo dưỡng xe đua"},{"pos":"n.","en":"The hard central part of certain fruits","vi":"hột (của một số loại quả)"}],"examples":[{"en":"We dug a shallow pit for the new tree.","vi":"Chúng tôi đã đào một cái hố nông để trồng cây mới.","audioKind":"ex"},{"en":"Abandoned mining pits can threaten local ecosystems unless restoration projects stabilise the soil and improve water quality.","vi":"Các mỏ quặng bỏ hoang có thể đe dọa hệ sinh thái địa phương trừ khi các dự án phục hồi có thể ổn định đất và cải thiện chất lượng nguồn nước.","audioKind":"ex2"}],"collocations":[{"en":"dig a pit","vi":"đào hố"},{"en":"a deep pit","vi":"hố sâu"},{"en":"a pit stop","vi":"trạm dừng sửa chữa xe đua"},{"en":"a peach pit","vi":"hột đào"}],"wordFamily":[],"synonyms":["hole","hollow"],"antonyms":[],"tipVi":"Khu vực bảo dưỡng xe đua thường dùng the pits; nghĩa chỉ hột trái cây chủ yếu được dùng trong tiếng Anh-Mỹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_species', 'en-b2-18', 'species', '/ˈspiːʃiːz/', 'B2', 'loài (sinh học)', 'n.', NULL, NULL, 'Dạng số ít và số nhiều giống nhau: one species, many species.', 'Several species of butterfly visit our garden each summer.', NULL, 'Một vài loài bướm ghé thăm khu vườn của chúng tôi vào mỗi mùa hè.', '{"wordId":"species","ukIpa":"/ˈspiːʃiːz/","usIpa":"/ˈspiːʃiːz/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A biological group whose members can usually breed with one another.","vi":"loài (sinh học)"}],"examples":[{"en":"Several species of butterfly visit our garden each summer.","vi":"Một vài loài bướm ghé thăm khu vườn của chúng tôi vào mỗi mùa hè.","audioKind":"ex"},{"en":"Protecting natural habitats is essential for preventing the extinction of species threatened by human activity.","vi":"Bảo vệ các sinh cảnh tự nhiên là điều cốt yếu để ngăn chặn sự tuyệt chủng của các loài đang bị đe dọa bởi hoạt động của con người.","audioKind":"ex2"}],"collocations":[{"en":"endangered species","vi":"loài có nguy cơ tuyệt chủng"},{"en":"native species","vi":"loài bản địa"},{"en":"invasive species","vi":"loài xâm lấn"},{"en":"species diversity","vi":"đa dạng sinh học"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số ít và số nhiều giống nhau: one species, many species.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_claw', 'en-b2-18', 'claw', '/klɔː/', 'B2', 'móng vuốt; càng (cua, ghẹ); cào; cấu bằng móng vuốt hoặc ngón tay', 'n.', 'clawed (adj.)', NULL, 'claw là móng vuốt nhọn; paw chỉ toàn bộ bàn chân của động vật như chó, mèo.', 'The cat caught my sleeve with one sharp claw.', NULL, 'Con mèo đã cào vào tay áo tôi bằng một chiếc móng sắc nhọn.', '{"wordId":"claw","ukIpa":"/klɔː/","usIpa":"/klɔː/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"a sharp, curved nail on an animal''s foot","vi":"móng vuốt"},{"pos":"n.","en":"a jointed gripping part on a crab or similar animal","vi":"càng (cua, ghẹ)"},{"pos":"v.","en":"to scratch or pull at something with claws or fingers","vi":"cào; cấu bằng móng vuốt hoặc ngón tay"}],"examples":[{"en":"The cat caught my sleeve with one sharp claw.","vi":"Con mèo đã cào vào tay áo tôi bằng một chiếc móng sắc nhọn.","audioKind":"ex"},{"en":"Sharp claws help many predators catch prey, while other animals use them to climb or dig.","vi":"Móng vuốt sắc nhọn giúp nhiều loài săn mồi bắt con mồi, trong khi các loài khác dùng chúng để leo trèo hoặc đào bới.","audioKind":"ex2"}],"collocations":[{"en":"sharp claws","vi":"móng vuốt sắc nhọn"},{"en":"crab claws","vi":"càng cua"},{"en":"claw at something","vi":"cào cấu vật gì"}],"wordFamily":["clawed (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"claw là móng vuốt nhọn; paw chỉ toàn bộ bàn chân của động vật như chó, mèo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dawn', 'en-b2-18', 'dawn', '/dɔːn/', 'B2', 'buổi bình minh; rạng đông; sự khởi đầu; thời kỳ khai nguyên; bắt đầu ló dạng; vỡ lẽ', 'n.', NULL, 'Đồng nghĩa: daybreak · Trái nghĩa: dusk', 'It dawned on me that… nghĩa là "Tôi chợt nhận ra rằng…".', 'We left at dawn to avoid the heavy traffic.', NULL, 'Chúng tôi khởi hành từ lúc rạng đông để tránh tình trạng kẹt xe nặng.', '{"wordId":"dawn","ukIpa":"/dɔːn/","usIpa":"/dɔːn/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"the early morning when daylight first appears","vi":"buổi bình minh; rạng đông"},{"pos":"n.","en":"the beginning of a new period or development","vi":"sự khởi đầu; thời kỳ khai nguyên"},{"pos":"v.","en":"to become understood, or to begin growing light","vi":"bắt đầu ló dạng; vỡ lẽ"}],"examples":[{"en":"We left at dawn to avoid the heavy traffic.","vi":"Chúng tôi khởi hành từ lúc rạng đông để tránh tình trạng kẹt xe nặng.","audioKind":"ex"},{"en":"The dawn of digital communication has transformed how people maintain relationships across national borders.","vi":"Sự khởi đầu của kỷ nguyên truyền thông kỹ thuật số đã thay đổi cách con người duy trì các mối quan hệ vượt biên giới quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"at dawn","vi":"vào lúc bình minh"},{"en":"from dawn to dusk","vi":"từ sáng sớm đến tối mịt"},{"en":"the dawn of a new era","vi":"sự khởi đầu của một kỷ nguyên mới"},{"en":"dawn on someone","vi":"chợt hiểu ra; vỡ lẽ ra"}],"wordFamily":[],"synonyms":["daybreak"],"antonyms":["dusk"],"tipVi":"It dawned on me that… nghĩa là \"Tôi chợt nhận ra rằng…\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shallow', 'en-b2-18', 'shallow', '/ˈʃæloʊ/', 'B2', 'nông; cạn; nông cạn; hời hợt; thiếu sâu sắc; nông (hơi thở nông)', 'adj.', 'shallowness (n.)', 'Đồng nghĩa: superficial · Trái nghĩa: deep', 'Nước nông hay suy nghĩ hời hợt đều dùng shallow, từ trái nghĩa là deep.', 'The children splashed happily in the shallow end of the pool.', NULL, 'Bọn trẻ vui đùa thỏa thích ở khu vực nước cạn của hồ bơi.', '{"wordId":"shallow","ukIpa":"/ˈʃæləʊ/","usIpa":"/ˈʃæloʊ/","cefr":"B2","topic":"nature","senses":[{"pos":"adj.","en":"Having little depth from the surface to the bottom","vi":"nông; cạn"},{"pos":"adj.","en":"Lacking serious thought, understanding, or emotional depth","vi":"nông cạn; hời hợt; thiếu sâu sắc"},{"pos":"adj.","en":"Taking only a small amount of air into the lungs","vi":"nông (hơi thở nông)"}],"examples":[{"en":"The children splashed happily in the shallow end of the pool.","vi":"Bọn trẻ vui đùa thỏa thích ở khu vực nước cạn của hồ bơi.","audioKind":"ex"},{"en":"Shallow coastal waters provide important habitats for young fish, making their protection essential for sustainable fisheries.","vi":"Vùng nước ven biển nông cung cấp môi trường sống quan trọng cho cá non, khiến việc bảo vệ chúng trở nên thiết yếu đối với nghề cá bền vững.","audioKind":"ex2"}],"collocations":[{"en":"shallow water","vi":"nước nông"},{"en":"a shallow dish","vi":"cái đĩa nông"},{"en":"shallow breathing","vi":"hơi thở nông"},{"en":"a shallow understanding","vi":"sự hiểu biết hời hợt"}],"wordFamily":["shallowness (n.)"],"synonyms":["superficial"],"antonyms":["deep"],"tipVi":"Nước nông hay suy nghĩ hời hợt đều dùng shallow, từ trái nghĩa là deep.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_graze', 'en-b2-18', 'graze', '/ɡreɪz/', 'B2', 'gặm cỏ; thả gia súc ăn cỏ; làm trầy da; sướt da; lướt qua; vết trầy xước da', 'v.', 'grazing (n.)', NULL, 'Động vật ăn cỏ có thể dùng graze on grass; graze cattle có nghĩa là thả trâu bò ăn cỏ.', 'Sheep graze quietly beside the river every summer morning.', NULL, 'Đàn cừu thong thả gặm cỏ bên bờ sông vào mỗi buổi sáng mùa hè.', '{"wordId":"graze","ukIpa":"/ɡreɪz/","usIpa":"/ɡreɪz/","cefr":"B2","topic":"nature","senses":[{"pos":"v.","en":"to eat growing grass, or let animals feed on it","vi":"gặm cỏ; thả gia súc ăn cỏ"},{"pos":"v.","en":"to scrape skin slightly or touch something while passing","vi":"làm trầy da; sướt da; lướt qua"},{"pos":"n.","en":"a small injury where skin has been scraped off","vi":"vết trầy xước da"}],"examples":[{"en":"Sheep graze quietly beside the river every summer morning.","vi":"Đàn cừu thong thả gặm cỏ bên bờ sông vào mỗi buổi sáng mùa hè.","audioKind":"ex"},{"en":"Allowing cattle to graze too intensively can damage vegetation and increase the risk of soil erosion.","vi":"Để gia súc gặm cỏ quá mức có thể tàn phá thảm thực vật và làm tăng nguy cơ xói mòn đất.","audioKind":"ex2"}],"collocations":[{"en":"graze on grass","vi":"gặm cỏ"},{"en":"graze cattle","vi":"chăn thả gia súc"},{"en":"graze your knee","vi":"trầy xước đầu gối"}],"wordFamily":["grazing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Động vật ăn cỏ có thể dùng graze on grass; graze cattle có nghĩa là thả trâu bò ăn cỏ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dove', 'en-b2-18', 'dove', '/dʌv/', 'B2', 'chim bồ câu; người chủ hòa; phe chủ hòa', 'n.', NULL, 'Trái nghĩa: hawk', 'Khi chỉ người chủ hòa, từ này trái nghĩa với hawk (chủ trương cứng rắn).', 'A white dove landed gently on our garden wall.', NULL, 'Một con chim bồ câu trắng nhẹ nhàng đậu trên bức tường vườn nhà chúng tôi.', '{"wordId":"dove","ukIpa":"/dʌv/","usIpa":"/dʌv/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"a bird often associated with peace","vi":"chim bồ câu"},{"pos":"n.","en":"someone who favours peaceful solutions rather than military action","vi":"người chủ hòa; phe chủ hòa"}],"examples":[{"en":"A white dove landed gently on our garden wall.","vi":"Một con chim bồ câu trắng nhẹ nhàng đậu trên bức tường vườn nhà chúng tôi.","audioKind":"ex"},{"en":"Political doves argue that international disputes should be resolved through negotiation rather than military intervention.","vi":"Những người theo chủ trương ôn hòa trong chính trị lập luận rằng các tranh chấp quốc tế nên được giải quyết thông qua đàm phán thay vì can thiệp quân sự.","audioKind":"ex2"}],"collocations":[{"en":"a white dove","vi":"chim bồ câu trắng"},{"en":"a symbol of peace","vi":"biểu tượng của hòa bình"},{"en":"a political dove","vi":"nhà chính trị chủ hòa"}],"wordFamily":[],"synonyms":[],"antonyms":["hawk"],"tipVi":"Khi chỉ người chủ hòa, từ này trái nghĩa với hawk (chủ trương cứng rắn).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_abundant', 'en-b2-18', 'abundant', '/əˈbʌndənt/', 'B2', 'phong phú; dồi dào', 'adj.', 'abundance (n.), abundantly (adv.)', 'Đồng nghĩa: plentiful, ample · Trái nghĩa: scarce', 'abundant nhấn mạnh số lượng phong phú; danh từ đi kèm là an abundance of.', 'Fresh fruit is abundant here during the summer.', NULL, 'Trái cây tươi rất dồi dào ở đây vào mùa hè.', '{"wordId":"abundant","ukIpa":"/əˈbʌndənt/","usIpa":"/əˈbʌndənt/","cefr":"B2","topic":"nature","senses":[{"pos":"adj.","en":"Available in large amounts, often more than needed.","vi":"phong phú; dồi dào"}],"examples":[{"en":"Fresh fruit is abundant here during the summer.","vi":"Trái cây tươi rất dồi dào ở đây vào mùa hè.","audioKind":"ex"},{"en":"Regions with abundant sunlight have considerable potential to generate affordable electricity from solar energy.","vi":"Các khu vực có nhiều ánh nắng mặt trời có tiềm năng lớn trong việc sản xuất điện giá rẻ từ năng lượng mặt trời.","audioKind":"ex2"}],"collocations":[{"en":"abundant resources","vi":"tài nguyên phong phú"},{"en":"abundant evidence","vi":"bằng chứng xác thực"},{"en":"abundant wildlife","vi":"động thực vật hoang dã phong phú"}],"wordFamily":["abundance (n.)","abundantly (adv.)"],"synonyms":["plentiful","ample"],"antonyms":["scarce"],"tipVi":"abundant nhấn mạnh số lượng phong phú; danh từ đi kèm là an abundance of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_landscape', 'en-b2-18', 'landscape', '/ˈlændskeɪp/', 'B2', 'cảnh quan; phong cảnh; bối cảnh; cục diện; làm cảnh quan; kiến thiết cảnh quan', 'n.', 'landscaping (n.), landscaper (n.)', 'Đồng nghĩa: scenery', 'landscape là danh từ đếm được, chỉ một vùng cảnh quan; scenery thường không đếm được.', 'Snow covered the landscape beyond our small wooden cabin.', NULL, 'Tuyết bao phủ phong cảnh bên ngoài căn nhà gỗ nhỏ của chúng tôi.', '{"wordId":"landscape","ukIpa":"/ˈlændskeɪp/","usIpa":"/ˈlændskeɪp/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"The visible features of an area of land.","vi":"cảnh quan; phong cảnh"},{"pos":"n.","en":"The overall conditions and features of a particular field.","vi":"bối cảnh; cục diện"},{"pos":"v.","en":"To improve land by arranging plants and other outdoor features.","vi":"làm cảnh quan; kiến thiết cảnh quan"}],"examples":[{"en":"Snow covered the landscape beyond our small wooden cabin.","vi":"Tuyết bao phủ phong cảnh bên ngoài căn nhà gỗ nhỏ của chúng tôi.","audioKind":"ex"},{"en":"Large wind farms can alter the rural landscape, although they provide an important source of clean energy.","vi":"Các trang trại điện gió lớn có thể làm thay đổi cảnh quan nông thôn, dù chúng cung cấp nguồn năng lượng sạch quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"rural landscape","vi":"cảnh quan nông thôn"},{"en":"natural landscape","vi":"cảnh quan thiên nhiên"},{"en":"political landscape","vi":"cục diện chính trị"},{"en":"landscape design","vi":"thiết kế cảnh quan"}],"wordFamily":["landscaping (n.)","landscaper (n.)"],"synonyms":["scenery"],"antonyms":[],"tipVi":"landscape là danh từ đếm được, chỉ một vùng cảnh quan; scenery thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_moss', 'en-b2-18', 'moss', '/mɔːs/', 'B2', 'rêu', 'n.', 'mossy (adj.)', NULL, 'Thường là danh từ không đếm được; lichen chỉ địa y, không giống với moss.', 'Thick green moss covered the stones beside the stream.', NULL, 'Lớp rêu xanh dày phủ kín những viên đá bên bờ suối.', '{"wordId":"moss","ukIpa":"/mɒs/","usIpa":"/mɔːs/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A small green plant growing in soft patches on damp surfaces.","vi":"rêu"}],"examples":[{"en":"Thick green moss covered the stones beside the stream.","vi":"Lớp rêu xanh dày phủ kín những viên đá bên bờ suối.","audioKind":"ex"},{"en":"Moss helps forest ecosystems retain moisture and provides a habitat for many tiny organisms.","vi":"Rêu giúp các hệ sinh thái rừng giữ độ ẩm và cung cấp môi trường sống cho nhiều loài sinh vật nhỏ.","audioKind":"ex2"}],"collocations":[{"en":"a patch of moss","vi":"một mảng rêu"},{"en":"thick moss","vi":"rêu dày"},{"en":"moss-covered rocks","vi":"những tảng đá phủ đầy rêu"}],"wordFamily":["mossy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; lichen chỉ địa y, không giống với moss.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_feeding', 'en-b2-18', 'feeding', '/ˈfiːdɪŋ/', 'B2', 'sự cho ăn; việc ăn uống; việc cho bú', 'n.', 'feed (v.), feeder (n.)', NULL, 'Vừa có thể đóng vai trò là danh từ, vừa có thể là phân từ hiện tại của động từ feed.', 'The puppies always get excited around feeding time.', NULL, 'Những chú chó con luôn trở nên phấn khích vào giờ cho ăn.', '{"wordId":"feeding","ukIpa":"/ˈfiːdɪŋ/","usIpa":"/ˈfiːdɪŋ/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"The act of giving or taking food.","vi":"sự cho ăn; việc ăn uống; việc cho bú"}],"examples":[{"en":"The puppies always get excited around feeding time.","vi":"Những chú chó con luôn trở nên phấn khích vào giờ cho ăn.","audioKind":"ex"},{"en":"Regular feeding of wild animals by tourists can alter their behaviour and increase their dependence on humans.","vi":"Việc khách du lịch thường xuyên cho động vật hoang dã ăn có thể làm thay đổi tập tính của chúng và làm tăng sự phụ thuộc của chúng vào con người.","audioKind":"ex2"}],"collocations":[{"en":"feeding time","vi":"giờ cho ăn"},{"en":"feeding habits","vi":"thói quen ăn uống"},{"en":"bottle feeding","vi":"cho bú bình"},{"en":"a feeding schedule","vi":"lịch cho ăn"}],"wordFamily":["feed (v.)","feeder (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Vừa có thể đóng vai trò là danh từ, vừa có thể là phân từ hiện tại của động từ feed.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_calf', 'en-b2-18', 'calf', '/kæf/', 'B2', 'bê con; con non của động vật lớn (như voi, cá voi); bắp chân', 'n.', 'calves (n.), calve (v.)', NULL, 'Dạng số nhiều là calves; chữ l không được phát âm.', 'The calf stayed close to its mother in the field.', NULL, 'Con bê đi sát bên mẹ nó trên cánh đồng.', '{"wordId":"calf","ukIpa":"/kɑːf/","usIpa":"/kæf/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A young cow or another large mammal, such as an elephant.","vi":"bê con; con non của động vật lớn (như voi, cá voi)"},{"pos":"n.","en":"The fleshy back part of the leg below the knee.","vi":"bắp chân"}],"examples":[{"en":"The calf stayed close to its mother in the field.","vi":"Con bê đi sát bên mẹ nó trên cánh đồng.","audioKind":"ex"},{"en":"Farmers must provide each calf with adequate nutrition and shelter to support healthy growth.","vi":"Nông dân phải cung cấp cho mỗi con bê đầy đủ dinh dưỡng và nơi ở để hỗ trợ sự phát triển khỏe mạnh.","audioKind":"ex2"}],"collocations":[{"en":"a newborn calf","vi":"một con bê mới sinh"},{"en":"calf muscles","vi":"cơ bắp chân"},{"en":"raise a calf","vi":"nuôi bê"}],"wordFamily":["calves (n.)","calve (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều là calves; chữ l không được phát âm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_changeable', 'en-b2-18', 'changeable', '/ˈtʃeɪndʒəbl/', 'B2', 'thay đổi thất thường; dễ thay đổi', 'adj.', 'change (v.), change (n.), unchangeable (adj.)', 'Đồng nghĩa: variable, unpredictable · Trái nghĩa: stable, constant', 'Thường dùng để tả thời tiết hoặc tâm trạng thay đổi thất thường; lưu ý giữ chữ "e" cuối từ "change".', 'Pack a light jacket because the weather is changeable.', NULL, 'Hãy mang theo một chiếc áo khoác mỏng vì thời tiết rất thất thường.', '{"wordId":"changeable","ukIpa":"/ˈtʃeɪndʒəbl/","usIpa":"/ˈtʃeɪndʒəbl/","cefr":"B2","topic":"nature","senses":[{"pos":"adj.","en":"Likely to change frequently or unexpectedly.","vi":"thay đổi thất thường; dễ thay đổi"}],"examples":[{"en":"Pack a light jacket because the weather is changeable.","vi":"Hãy mang theo một chiếc áo khoác mỏng vì thời tiết rất thất thường.","audioKind":"ex"},{"en":"Farmers need reliable forecasts to plan their work effectively in regions with highly changeable weather.","vi":"Nông dân cần những dự báo đáng tin cậy để lên kế hoạch công việc hiệu quả ở những vùng có thời tiết thay đổi thất thường.","audioKind":"ex2"}],"collocations":[{"en":"changeable weather","vi":"thời tiết thất thường"},{"en":"a changeable mood","vi":"tâm trạng dễ thay đổi"},{"en":"highly changeable","vi":"rất dễ thay đổi"}],"wordFamily":["change (v.)","change (n.)","unchangeable (adj.)"],"synonyms":["variable","unpredictable"],"antonyms":["stable","constant"],"tipVi":"Thường dùng để tả thời tiết hoặc tâm trạng thay đổi thất thường; lưu ý giữ chữ \"e\" cuối từ \"change\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gigantic', 'en-b2-18', 'gigantic', '/dʒaɪˈɡæntɪk/', 'B2', 'khổng lồ; to lớn', 'adj.', 'giant (n.), gigantically (adv.)', 'Đồng nghĩa: enormous, huge, immense · Trái nghĩa: tiny, minute', 'Mức độ lớn mạnh hơn big, thường dùng để miêu tả kích thước, quy mô hoặc khối lượng công việc.', 'A gigantic pumpkin filled the entire kitchen table.', NULL, 'Một quả bí ngô khổng lồ chiếm trọn chiếc bàn ăn.', '{"wordId":"gigantic","ukIpa":"/dʒaɪˈɡæntɪk/","usIpa":"/dʒaɪˈɡæntɪk/","cefr":"B2","topic":"nature","senses":[{"pos":"adj.","en":"extremely large in size or amount","vi":"khổng lồ; to lớn"}],"examples":[{"en":"A gigantic pumpkin filled the entire kitchen table.","vi":"Một quả bí ngô khổng lồ chiếm trọn chiếc bàn ăn.","audioKind":"ex"},{"en":"Building gigantic dams can generate renewable electricity, but it may also destroy habitats and displace local communities.","vi":"Việc xây dựng các con đập khổng lồ có thể tạo ra điện tái tạo, nhưng nó cũng có thể phá hủy môi trường sống và khiến các cộng đồng địa phương phải di dời.","audioKind":"ex2"}],"collocations":[{"en":"a gigantic task","vi":"một nhiệm vụ vô cùng khó khăn"},{"en":"a gigantic structure","vi":"một công trình kiến trúc khổng lồ"},{"en":"a gigantic wave","vi":"một con sóng thần lớn"}],"wordFamily":["giant (n.)","gigantically (adv.)"],"synonyms":["enormous","huge","immense"],"antonyms":["tiny","minute"],"tipVi":"Mức độ lớn mạnh hơn big, thường dùng để miêu tả kích thước, quy mô hoặc khối lượng công việc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tide', 'en-b2-18', 'tide', '/taɪd/', 'B2', 'thủy triều; nước thủy triều; xu hướng; trào lưu', 'n.', 'tidal (adj.)', NULL, 'tide chỉ hiện tượng dâng hạ chu kỳ của nước biển, còn wave chỉ một con sóng đơn lẻ.', 'At low tide, we walked across the exposed sand.', NULL, 'Vào lúc thủy triều xuống, chúng tôi đi bộ qua bãi cát lộ thiên.', '{"wordId":"tide","ukIpa":"/taɪd/","usIpa":"/taɪd/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"the regular rise and fall of the sea","vi":"thủy triều; nước thủy triều"},{"pos":"n.","en":"a strong movement or change in events or opinion","vi":"xu hướng; trào lưu"}],"examples":[{"en":"At low tide, we walked across the exposed sand.","vi":"Vào lúc thủy triều xuống, chúng tôi đi bộ qua bãi cát lộ thiên.","audioKind":"ex"},{"en":"Coastal planners must consider how rising sea levels and high tides could threaten homes and transport infrastructure.","vi":"Các nhà quy hoạch vùng ven biển phải cân nhắc việc nước biển dâng và triều cường cao có thể đe dọa các ngôi nhà cùng cơ sở hạ tầng giao thông như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"high tide","vi":"triều cường; nước lên"},{"en":"low tide","vi":"thủy triều xuống; nước rút"},{"en":"turn the tide","vi":"xoay chuyển tình thế"},{"en":"a tide of change","vi":"làn sóng thay đổi"}],"wordFamily":["tidal (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"tide chỉ hiện tượng dâng hạ chu kỳ của nước biển, còn wave chỉ một con sóng đơn lẻ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_moonlight', 'en-b2-18', 'moonlight', '/ˈmuːnlaɪt/', 'B2', 'ánh trăng; làm việc ngoài giờ; làm thêm nghề tay trái', 'n.', 'moon (n.), moonlit (adj.)', NULL, 'Ánh trăng là danh từ không đếm được; động từ thường đi với as để chỉ vai trò làm thêm.', 'Moonlight shone through the curtains onto my pillow.', NULL, 'Ánh trăng chiếu qua rèm cửa lên chiếc gối của tôi.', '{"wordId":"moonlight","ukIpa":"/ˈmuːnlaɪt/","usIpa":"/ˈmuːnlaɪt/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"The light that reaches Earth from the moon.","vi":"ánh trăng"},{"pos":"v.","en":"To do another paid job alongside your main job, often secretly.","vi":"làm việc ngoài giờ; làm thêm nghề tay trái"}],"examples":[{"en":"Moonlight shone through the curtains onto my pillow.","vi":"Ánh trăng chiếu qua rèm cửa lên chiếc gối của tôi.","audioKind":"ex"},{"en":"Artificial lighting can obscure natural moonlight, potentially affecting the behaviour of animals that are active at night.","vi":"Ánh sáng nhân tạo có thể lu mờ ánh trăng tự nhiên, qua đó có tiềm năng ảnh hưởng đến tập tính của các loài động vật hoạt động về đêm.","audioKind":"ex2"}],"collocations":[{"en":"in the moonlight","vi":"dưới ánh trăng"},{"en":"pale moonlight","vi":"ánh trăng nhợt nhạt"},{"en":"moonlight as a waiter","vi":"làm thêm chân bồi bàn"}],"wordFamily":["moon (n.)","moonlit (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Ánh trăng là danh từ không đếm được; động từ thường đi với as để chỉ vai trò làm thêm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_basin', 'en-b2-18', 'basin', '/ˈbeɪsən/', 'B2', 'chậu rửa; vũng nước; lưu vực sông; bồn địa', 'n.', NULL, NULL, 'river basin chỉ toàn bộ lưu vực, không chỉ riêng lòng sông.', 'She filled the basin with water to wash her face.', NULL, 'Cô ấy đổ đầy nước vào chậu để rửa mặt.', '{"wordId":"basin","ukIpa":"/ˈbeɪsən/","usIpa":"/ˈbeɪsən/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A wide, open container for water or washing.","vi":"chậu rửa; vũng nước"},{"pos":"n.","en":"The land drained by a river and its smaller rivers.","vi":"lưu vực sông"},{"pos":"n.","en":"A broad area of low land surrounded by higher ground.","vi":"bồn địa"}],"examples":[{"en":"She filled the basin with water to wash her face.","vi":"Cô ấy đổ đầy nước vào chậu để rửa mặt.","audioKind":"ex"},{"en":"Agricultural expansion across the river basin has increased pressure on freshwater supplies and damaged natural habitats.","vi":"Sự mở rộng nông nghiệp trên khắp lưu vực sông đã làm gia tăng áp lực lên nguồn cung cấp nước ngọt và tàn phá các môi trường sống tự nhiên.","audioKind":"ex2"}],"collocations":[{"en":"wash basin","vi":"chậu rửa mặt"},{"en":"river basin","vi":"lưu vực sông"},{"en":"drainage basin","vi":"vùng thu lưu vực"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"river basin chỉ toàn bộ lưu vực, không chỉ riêng lòng sông.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hedge', 'en-b2-18', 'hedge', '/hedʒ/', 'B2', 'hàng rào cây xanh; bụi cây rào; biện pháp phòng ngừa rủi ro tài chính; nói lảng tránh; né tránh câu trả lời rõ ràng', 'n.', 'hedging (n.)', NULL, 'Trong tài chính thường dùng a hedge against để chỉ cách phòng ngừa rủi ro nào đó.', 'A thick hedge separates our garden from the pavement.', NULL, 'Một hàng rào cây xanh rậm rạp ngăn cách khu vườn nhà chúng tôi với lối đi bộ.', '{"wordId":"hedge","ukIpa":"/hedʒ/","usIpa":"/hedʒ/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"a row of closely planted bushes forming a boundary","vi":"hàng rào cây xanh; bụi cây rào"},{"pos":"n.","en":"something that reduces the risk of financial loss","vi":"biện pháp phòng ngừa rủi ro tài chính"},{"pos":"v.","en":"to avoid giving a clear or definite answer","vi":"nói lảng tránh; né tránh câu trả lời rõ ràng"}],"examples":[{"en":"A thick hedge separates our garden from the pavement.","vi":"Một hàng rào cây xanh rậm rạp ngăn cách khu vườn nhà chúng tôi với lối đi bộ.","audioKind":"ex"},{"en":"Some investors purchase gold as a hedge against inflation, although its value can also fluctuate.","vi":"Một số nhà đầu tư mua vàng như một biện pháp phòng ngừa lạm phát, mặc dù giá trị của vàng cũng có thể biến động.","audioKind":"ex2"}],"collocations":[{"en":"trim a hedge","vi":"cắt tỉa hàng rào cây"},{"en":"a hedge against inflation","vi":"biện pháp chống lạm phát"},{"en":"hedge your bets","vi":"mua bảo hiểm rủi ro; phương án dự phòng"}],"wordFamily":["hedging (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong tài chính thường dùng a hedge against để chỉ cách phòng ngừa rủi ro nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grasshopper', 'en-b2-18', 'grasshopper', '/ˈɡræshɑːpər/', 'B2', 'châu chấu; cào cào', 'n.', NULL, NULL, 'Locust chỉ một số loài châu chấu có khả năng bay đàn di cư.', 'A green grasshopper landed on my sleeve in the garden.', NULL, 'Một con châu chấu màu xanh đã đậu lên tay áo tôi ở trong vườn.', '{"wordId":"grasshopper","ukIpa":"/ˈɡrɑːshɒpə/","usIpa":"/ˈɡræshɑːpər/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"An insect with long back legs used for jumping.","vi":"châu chấu; cào cào"}],"examples":[{"en":"A green grasshopper landed on my sleeve in the garden.","vi":"Một con châu chấu màu xanh đã đậu lên tay áo tôi ở trong vườn.","audioKind":"ex"},{"en":"Grasshoppers provide food for many birds and play an important role in maintaining healthy grassland ecosystems.","vi":"Châu chấu cung cấp thức ăn cho nhiều loài chim và đóng vai trò quan trọng trong việc duy trì hệ sinh thái đồng cỏ lành mạnh.","audioKind":"ex2"}],"collocations":[{"en":"a green grasshopper","vi":"một con châu chấu xanh"},{"en":"a grasshopper leaps","vi":"châu chấu nhảy"},{"en":"grasshopper species","vi":"các loài châu chấu"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Locust chỉ một số loài châu chấu có khả năng bay đàn di cư.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gulf', 'en-b2-18', 'gulf', '/ɡʌlf/', 'B2', 'vịnh (vùng biển lớn một phần được bao quanh bởi đất liền); khoảng cách lớn; sự khác biệt sâu sắc', 'n.', NULL, NULL, 'gulf có thể chỉ vịnh biển, và cụm từ gulf between thường dùng để chỉ khoảng cách lớn.', 'Fishing boats crossed the gulf as the sun rose.', NULL, 'Những chiếc thuyền đánh cá vượt qua vịnh khi mặt trời mọc.', '{"wordId":"gulf","ukIpa":"/ɡʌlf/","usIpa":"/ɡʌlf/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A large area of sea partly surrounded by land.","vi":"vịnh (vùng biển lớn một phần được bao quanh bởi đất liền)"},{"pos":"n.","en":"A major difference separating people, groups, or ideas.","vi":"khoảng cách lớn; sự khác biệt sâu sắc"}],"examples":[{"en":"Fishing boats crossed the gulf as the sun rose.","vi":"Những chiếc thuyền đánh cá vượt qua vịnh khi mặt trời mọc.","audioKind":"ex"},{"en":"Unequal access to digital technology can widen the gulf between wealthy communities and poorer ones.","vi":"Sự tiếp cận công nghệ số không đồng đều có thể làm nới rộng khoảng cách giữa các cộng đồng giàu có và nghèo khó.","audioKind":"ex2"}],"collocations":[{"en":"a wide gulf","vi":"khoảng cách lớn"},{"en":"bridge the gulf","vi":"thu hẹp khoảng cách"},{"en":"the gulf between rich and poor","vi":"khoảng cách giàu nghèo"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"gulf có thể chỉ vịnh biển, và cụm từ gulf between thường dùng để chỉ khoảng cách lớn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_beetle', 'en-b2-18', 'beetle', '/ˈbiːtəl/', 'B2', 'con bọ; bọ cánh cứng', 'n.', NULL, NULL, 'Chỉ côn trùng bọ cánh cứng; không dùng để chỉ người bị cận thị.', 'A shiny beetle crawled slowly across the garden path.', NULL, 'Một con bọ cánh cứng sáng bóng bò chậm chạp qua lối đi trong vườn.', '{"wordId":"beetle","ukIpa":"/ˈbiːtəl/","usIpa":"/ˈbiːtəl/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"An insect with hard outer wings covering its flying wings.","vi":"con bọ; bọ cánh cứng"}],"examples":[{"en":"A shiny beetle crawled slowly across the garden path.","vi":"Một con bọ cánh cứng sáng bóng bò chậm chạp qua lối đi trong vườn.","audioKind":"ex"},{"en":"Some beetle species help maintain healthy forests by breaking down dead wood and recycling nutrients.","vi":"Một số loài bọ cánh cứng giúp duy trì sức khỏe của rừng bằng cách phân hủy gỗ mục và tái 1vòng chất dinh dưỡng.","audioKind":"ex2"}],"collocations":[{"en":"dung beetle","vi":"bọ hung"},{"en":"stag beetle","vi":"bọ kìm"},{"en":"beetle species","vi":"loài bọ cánh cứng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ côn trùng bọ cánh cứng; không dùng để chỉ người bị cận thị.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_harvest', 'en-b2-18', 'harvest', '/ˈhɑːrvɪst/', 'B2', 'vụ thu hoạch; mùa gặt; sản lượng thu hoạch; thu hoạch; gặt hái', 'n.', 'harvester (n.)', NULL, 'Danh từ có thể chỉ hoạt động thu hoạch, hoặc chỉ cây trồng/sản lượng thu được.', 'We celebrated the apple harvest with a homemade pie.', NULL, 'Chúng tôi kỷ niệm vụ thu hoạch táo bằng một chiếc bánh táo tự làm.', '{"wordId":"harvest","ukIpa":"/ˈhɑːvɪst/","usIpa":"/ˈhɑːrvɪst/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"the gathering of crops, or the crops gathered","vi":"vụ thu hoạch; mùa gặt; sản lượng thu hoạch"},{"pos":"v.","en":"to gather crops when they are ready","vi":"thu hoạch; gặt hái"}],"examples":[{"en":"We celebrated the apple harvest with a homemade pie.","vi":"Chúng tôi kỷ niệm vụ thu hoạch táo bằng một chiếc bánh táo tự làm.","audioKind":"ex"},{"en":"Unpredictable rainfall can reduce the annual harvest, threatening rural incomes and increasing food prices in cities.","vi":"Lượng mưa thất thường có thể làm giảm sản lượng thu hoạch hàng năm, đe dọa thu nhập ở vùng nông thôn và làm tăng giá thực phẩm ở các thành phố.","audioKind":"ex2"}],"collocations":[{"en":"a good harvest","vi":"mùa màng bội thu"},{"en":"harvest season","vi":"mùa thu hoạch"},{"en":"harvest crops","vi":"thu hoạch hoa màu"}],"wordFamily":["harvester (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ có thể chỉ hoạt động thu hoạch, hoặc chỉ cây trồng/sản lượng thu được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shrub', 'en-b2-18', 'shrub', '/ʃrʌb/', 'B2', 'cây bụi; bụi cây', 'n.', 'shrubby (adj.), shrubbery (n.)', 'Đồng nghĩa: bush', 'Danh từ đếm được, chỉ bụi cây; một quần thể cây bụi có thể dùng shrubbery.', 'A small bird was hiding beneath the flowering shrub.', NULL, 'Một chú chim nhỏ đang ẩn nấp dưới tán cây bụi đang ra hoa.', '{"wordId":"shrub","ukIpa":"/ʃrʌb/","usIpa":"/ʃrʌb/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A woody plant with several stems, usually smaller than a tree","vi":"cây bụi; bụi cây"}],"examples":[{"en":"A small bird was hiding beneath the flowering shrub.","vi":"Một chú chim nhỏ đang ẩn nấp dưới tán cây bụi đang ra hoa.","audioKind":"ex"},{"en":"Planting native shrubs in urban parks provides shelter for wildlife and can reduce the need for irrigation.","vi":"Việc trồng các loài cây bụi bản địa trong công viên đô thị cung cấp nơi trú ẩn cho động vật hoang dã và có thể giảm nhu cầu tưới tiêu.","audioKind":"ex2"}],"collocations":[{"en":"flowering shrub","vi":"cây bụi ra hoa"},{"en":"evergreen shrub","vi":"cây bụi thường xanh"},{"en":"native shrubs","vi":"cây bụi bản địa"},{"en":"plant shrubs","vi":"trồng cây bụi"}],"wordFamily":["shrubby (adj.)","shrubbery (n.)"],"synonyms":["bush"],"antonyms":[],"tipVi":"Danh từ đếm được, chỉ bụi cây; một quần thể cây bụi có thể dùng shrubbery.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_peacock', 'en-b2-18', 'peacock', '/ˈpiːkɑːk/', 'B2', 'chim công đực; công trống', 'n.', NULL, NULL, 'Về mặt ngữ nghĩa, peacock dùng để chỉ công đực, còn công mái gọi là peahen.', 'The peacock spread its brilliant feathers beside the pond.', NULL, 'Con công đực xòe chiếc đuôi rực rỡ bên bờ ao.', '{"wordId":"peacock","ukIpa":"/ˈpiːkɒk/","usIpa":"/ˈpiːkɑːk/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"a male peafowl with long, colourful feathers it spreads out","vi":"chim công đực; công trống"}],"examples":[{"en":"The peacock spread its brilliant feathers beside the pond.","vi":"Con công đực xòe chiếc đuôi rực rỡ bên bờ ao.","audioKind":"ex"},{"en":"The elaborate display of a peacock illustrates how mate selection can influence the evolution of animal appearance.","vi":"Màn khoe mã tinh tế của con công đực minh họa cách việc lựa chọn bạn tình có thể ảnh hưởng đến quá trình tiến hóa ngoại hình của động vật.","audioKind":"ex2"}],"collocations":[{"en":"peacock feathers","vi":"lông công"},{"en":"a peacock''s tail","vi":"đuôi công đực"},{"en":"as proud as a peacock","vi":"kiêu ngạo như công"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Về mặt ngữ nghĩa, peacock dùng để chỉ công đực, còn công mái gọi là peahen.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pine', 'en-b2-18', 'pine', '/paɪn/', 'B2', 'cây thông; gỗ thông; khao khát; héo mòn vì mong nhớ', 'n.', NULL, NULL, 'pine for biểu thị sự khao khát hoặc nhớ nhung; pine away chỉ tình trạng ngày càng tiều tụy, héo mòn.', 'We rested beneath a tall pine after lunch.', NULL, 'Chúng tôi nghỉ ngơi dưới bóng một cây thông cao sau bữa trưa.', '{"wordId":"pine","ukIpa":"/paɪn/","usIpa":"/paɪn/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"An evergreen tree with needles, or the wood it produces.","vi":"cây thông; gỗ thông"},{"pos":"v.","en":"Long deeply for someone or something, sometimes becoming weak.","vi":"khao khát; héo mòn vì mong nhớ"}],"examples":[{"en":"We rested beneath a tall pine after lunch.","vi":"Chúng tôi nghỉ ngơi dưới bóng một cây thông cao sau bữa trưa.","audioKind":"ex"},{"en":"Planting pine trees can support timber production, but diverse native forests generally provide richer wildlife habitats.","vi":"Việc trồng cây thông có thể hỗ trợ sản xuất gỗ, nhưng các khu rừng nguyên sinh với đa dạng sinh học thường cung cấp môi trường sống phong phú hơn cho động vật hoang dã.","audioKind":"ex2"}],"collocations":[{"en":"pine forest","vi":"rừng thông"},{"en":"pine cone","vi":"quả thông"},{"en":"pine for someone","vi":"khao khát ai đó"},{"en":"pine away","vi":"tiêu tụy vì nhớ nhung"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"pine for biểu thị sự khao khát hoặc nhớ nhung; pine away chỉ tình trạng ngày càng tiều tụy, héo mòn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_horizon', 'en-b2-18', 'horizon', '/həˈraɪzən/', 'B2', 'đường chân trời; tầm hiểu biết; tầm nhìn; chân trời kiến thức', 'n.', NULL, NULL, 'Cụm từ chỉ tầm hiểu biết thường dùng ở số nhiều: broaden your horizons.', 'We watched a small boat disappear beyond the horizon.', NULL, 'Chúng tôi đứng nhìn một con thuyền nhỏ khuất dần sau đường chân trời.', '{"wordId":"horizon","ukIpa":"/həˈraɪzən/","usIpa":"/həˈraɪzən/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"The line where the sky seems to meet land or sea.","vi":"đường chân trời"},{"pos":"n.","en":"The limits of someone''s knowledge, experience, or interests.","vi":"tầm hiểu biết; tầm nhìn; chân trời kiến thức"}],"examples":[{"en":"We watched a small boat disappear beyond the horizon.","vi":"Chúng tôi đứng nhìn một con thuyền nhỏ khuất dần sau đường chân trời.","audioKind":"ex"},{"en":"Studying abroad can broaden students'' horizons by exposing them to unfamiliar customs and different approaches to learning.","vi":"Việc du học có thể mở rộng tầm nhìn của học sinh bằng cách cho các em tiếpنده với những phong tục xa lạ và các phương pháp học tập khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"on the horizon","vi":"sắp xảy ra; ở chân trời"},{"en":"broaden your horizons","vi":"mở rộng tầm nhìn"},{"en":"beyond the horizon","vi":"ngoài đường chân trời"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ chỉ tầm hiểu biết thường dùng ở số nhiều: broaden your horizons.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flesh', 'en-b2-18', 'flesh', '/fleʃ/', 'B2', 'thịt; phần mô mềm giữa da và xương; phần thịt quả; cùi (của quả hoặc rau củ)', 'n.', 'fleshy (adj.)', NULL, 'Thông thường không đếm được; thịt động vật dùng để ăn thường dùng từ meat thay vì flesh.', 'The ripe peach had sweet flesh and a small stone.', NULL, 'Quả đào chín có phần thịt ngọt lịm và hạt nhỏ.', '{"wordId":"flesh","ukIpa":"/fleʃ/","usIpa":"/fleʃ/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"The soft tissue between the skin and bones.","vi":"thịt; phần mô mềm giữa da và xương"},{"pos":"n.","en":"The soft inner part of a fruit or vegetable.","vi":"phần thịt quả; cùi (của quả hoặc rau củ)"}],"examples":[{"en":"The ripe peach had sweet flesh and a small stone.","vi":"Quả đào chín có phần thịt ngọt lịm và hạt nhỏ.","audioKind":"ex"},{"en":"Fruits with brightly coloured flesh often contain nutrients that contribute to a healthy, balanced diet.","vi":"Những loại trái cây có phần thịt màu rực rỡ thường chứa các chất dinh dưỡng góp phần duy trì chế độ ăn uống lành mạnh và cân bằng.","audioKind":"ex2"}],"collocations":[{"en":"soft flesh","vi":"phần thịt mềm"},{"en":"fruit flesh","vi":"thịt quả"},{"en":"in the flesh","vi":"bằng xương bằng thịt; trực tiếp gặp mặt"},{"en":"flesh and blood","vi":"da thịt; người thân ruột thịt"}],"wordFamily":["fleshy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thông thường không đếm được; thịt động vật dùng để ăn thường dùng từ meat thay vì flesh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hillside', 'en-b2-18', 'hillside', '/ˈhɪlsaɪd/', 'B2', 'sườn đồi; dốc đồi', 'n.', 'hill (n.), hilly (adj.)', 'Đồng nghĩa: slope', 'Chỉ phần sườn dốc của ngọn đồi; dùng on the hillside để chỉ vị trí trên sườn đồi.', 'Small white houses dotted the hillside above the village.', NULL, 'Những ngôi nhà trắng nhỏ nằm rải rác trên sườn đồi phía trên ngôi làng.', '{"wordId":"hillside","ukIpa":"/ˈhɪlsaɪd/","usIpa":"/ˈhɪlsaɪd/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"The sloping surface of a hill.","vi":"sườn đồi; dốc đồi"}],"examples":[{"en":"Small white houses dotted the hillside above the village.","vi":"Những ngôi nhà trắng nhỏ nằm rải rác trên sườn đồi phía trên ngôi làng.","audioKind":"ex"},{"en":"Planting native trees on a bare hillside can reduce soil erosion and provide habitats for wildlife.","vi":"Việc trồng cây bản địa trên một sườn đồi trọc có thể làm giảm xói mòn đất và tạo môi trường sống cho động vật hoang dã.","audioKind":"ex2"}],"collocations":[{"en":"a steep hillside","vi":"sườn đồi dốc"},{"en":"a wooded hillside","vi":"sườn đồi có nhiều cây cối"},{"en":"on the hillside","vi":"trên sườn đồi"}],"wordFamily":["hill (n.)","hilly (adj.)"],"synonyms":["slope"],"antonyms":[],"tipVi":"Chỉ phần sườn dốc của ngọn đồi; dùng on the hillside để chỉ vị trí trên sườn đồi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 28, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_18_1', 'en-b2-18', 'Cách dùng “pit” (n.) — cái hố; hầm sâu', 'dig a pit  ·  a deep pit  ·  a pit stop', 'Khu vực bảo dưỡng xe đua thường dùng the pits; nghĩa chỉ hột trái cây chủ yếu được dùng trong tiếng Anh-Mỹ.', 'Đồng nghĩa: hole, hollow', '[{"hanzi":"We dug a shallow pit for the new tree.","pinyin":"","meaning":"Chúng tôi đã đào một cái hố nông để trồng cây mới."},{"hanzi":"Abandoned mining pits can threaten local ecosystems unless restoration projects stabilise the soil and improve water quality.","pinyin":"","meaning":"Các mỏ quặng bỏ hoang có thể đe dọa hệ sinh thái địa phương trừ khi các dự án phục hồi có thể ổn định đất và cải thiện chất lượng nguồn nước."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_18_2', 'en-b2-18', 'Cách dùng “changeable” (adj.) — thay đổi thất thường; dễ thay đổi', 'changeable weather  ·  a changeable mood  ·  highly changeable', 'Thường dùng để tả thời tiết hoặc tâm trạng thay đổi thất thường; lưu ý giữ chữ "e" cuối từ "change".', 'Họ từ (Word Family): change (v.), change (n.), unchangeable (adj.) | Đồng nghĩa: variable, unpredictable · Trái nghĩa: stable, constant', '[{"hanzi":"Pack a light jacket because the weather is changeable.","pinyin":"","meaning":"Hãy mang theo một chiếc áo khoác mỏng vì thời tiết rất thất thường."},{"hanzi":"Farmers need reliable forecasts to plan their work effectively in regions with highly changeable weather.","pinyin":"","meaning":"Nông dân cần những dự báo đáng tin cậy để lên kế hoạch công việc hiệu quả ở những vùng có thời tiết thay đổi thất thường."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_18_3', 'en-b2-18', 'Cách dùng “pine” (n.) — cây thông; gỗ thông', 'pine forest  ·  pine cone  ·  pine for someone', 'pine for biểu thị sự khao khát hoặc nhớ nhung; pine away chỉ tình trạng ngày càng tiều tụy, héo mòn.', NULL, '[{"hanzi":"We rested beneath a tall pine after lunch.","pinyin":"","meaning":"Chúng tôi nghỉ ngơi dưới bóng một cây thông cao sau bữa trưa."},{"hanzi":"Planting pine trees can support timber production, but diverse native forests generally provide richer wildlife habitats.","pinyin":"","meaning":"Việc trồng cây thông có thể hỗ trợ sản xuất gỗ, nhưng các khu rừng nguyên sinh với đa dạng sinh học thường cung cấp môi trường sống phong phú hơn cho động vật hoang dã."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_18_4', 'en-b2-18', 'Cách dùng “gigantic” (adj.) — khổng lồ; to lớn', 'a gigantic task  ·  a gigantic structure  ·  a gigantic wave', 'Mức độ lớn mạnh hơn big, thường dùng để miêu tả kích thước, quy mô hoặc khối lượng công việc.', 'Họ từ (Word Family): giant (n.), gigantically (adv.) | Đồng nghĩa: enormous, huge, immense · Trái nghĩa: tiny, minute', '[{"hanzi":"A gigantic pumpkin filled the entire kitchen table.","pinyin":"","meaning":"Một quả bí ngô khổng lồ chiếm trọn chiếc bàn ăn."},{"hanzi":"Building gigantic dams can generate renewable electricity, but it may also destroy habitats and displace local communities.","pinyin":"","meaning":"Việc xây dựng các con đập khổng lồ có thể tạo ra điện tái tạo, nhưng nó cũng có thể phá hủy môi trường sống và khiến các cộng đồng địa phương phải di dời."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_18_1', 'en-b2-18', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
