INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_18_1_3', 'ten_b2_18_1', 'claw', 'The cat caught my sleeve with one sharp claw.', 'The cat caught my sleeve with one sharp claw.', '/klɔː/', 'Con mèo đã cào vào tay áo tôi bằng một chiếc móng sắc nhọn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_18_1_4', 'ten_b2_18_1', 'dawn', 'We left at dawn to avoid the heavy traffic.', 'We left at dawn to avoid the heavy traffic.', '/dɔːn/', 'Chúng tôi khởi hành từ lúc rạng đông để tránh tình trạng kẹt xe nặng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_18_1_5', 'ten_b2_18_1', 'shallow', 'The children splashed happily in the shallow end of the pool.', 'The children splashed happily in the shallow end of the pool.', '/ˈʃæloʊ/', 'Bọn trẻ vui đùa thỏa thích ở khu vực nước cạn của hồ bơi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_18_1_6', 'ten_b2_18_1', 'graze', 'Sheep graze quietly beside the river every summer morning.', 'Sheep graze quietly beside the river every summer morning.', '/ɡreɪz/', 'Đàn cừu thong thả gặm cỏ bên bờ sông vào mỗi buổi sáng mùa hè.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_18_1_7', 'ten_b2_18_1', 'dove', 'A white dove landed gently on our garden wall.', 'A white dove landed gently on our garden wall.', '/dʌv/', 'Một con chim bồ câu trắng nhẹ nhàng đậu trên bức tường vườn nhà chúng tôi.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_18_1_8', 'ten_b2_18_1', 'abundant', 'Fresh fruit is abundant here during the summer.', 'Fresh fruit is abundant here during the summer.', '/əˈbʌndənt/', 'Trái cây tươi rất dồi dào ở đây vào mùa hè.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_18_1_1', 'en-b2-18', 'ten_b2_18_1', 'listening', 'listening', 'We dug a shallow pit for the new tree.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã đào một cái hố nông để trồng cây mới.","Những chú chó con luôn trở nên phấn khích vào giờ cho ăn.","Con bê đi sát bên mẹ nó trên cánh đồng.","Quả đào chín có phần thịt ngọt lịm và hạt nhỏ."]'::jsonb, 0, 'We dug a shallow pit for the new tree. → Chúng tôi đã đào một cái hố nông để trồng cây mới.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_18_1_2', 'en-b2-18', 'ten_b2_18_1', 'listening', 'listening', 'Several species of butterfly visit our garden each summer.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hãy mang theo một chiếc áo khoác mỏng vì thời tiết rất thất thường.","Một chú chim nhỏ đang ẩn nấp dưới tán cây bụi đang ra hoa.","Con công đực xòe chiếc đuôi rực rỡ bên bờ ao.","Một vài loài bướm ghé thăm khu vườn của chúng tôi vào mỗi mùa hè."]'::jsonb, 3, 'Several species of butterfly visit our garden each summer. → Một vài loài bướm ghé thăm khu vườn của chúng tôi vào mỗi mùa hè.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_18_1_3', 'en-b2-18', 'ten_b2_18_1', 'listening', 'listening', 'The cat caught my sleeve with one sharp claw.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hãy mang theo một chiếc áo khoác mỏng vì thời tiết rất thất thường.","Những chiếc thuyền đánh cá vượt qua vịnh khi mặt trời mọc.","Một quả bí ngô khổng lồ chiếm trọn chiếc bàn ăn.","Con mèo đã cào vào tay áo tôi bằng một chiếc móng sắc nhọn."]'::jsonb, 3, 'The cat caught my sleeve with one sharp claw. → Con mèo đã cào vào tay áo tôi bằng một chiếc móng sắc nhọn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_18_2', 'en-b2-18', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_18_2_1', 'ten_b2_18_2', 'pit', 'Abandoned mining pits can threaten local ecosystems unless restoration projects stabilise the soil and improve water quality.', 'Abandoned mining pits can threaten local ecosystems unless restoration projects stabilise the soil and improve water quality.', '/pɪt/', 'Các mỏ quặng bỏ hoang có thể đe dọa hệ sinh thái địa phương trừ khi các dự án phục hồi có thể ổn định đất và cải thiện chất lượng nguồn nước.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_18_2_2', 'ten_b2_18_2', 'species', 'Protecting natural habitats is essential for preventing the extinction of species threatened by human activity.', 'Protecting natural habitats is essential for preventing the extinction of species threatened by human activity.', '/ˈspiːʃiːz/', 'Bảo vệ các sinh cảnh tự nhiên là điều cốt yếu để ngăn chặn sự tuyệt chủng của các loài đang bị đe dọa bởi hoạt động của con người.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_18_2_3', 'ten_b2_18_2', 'claw', 'Sharp claws help many predators catch prey, while other animals use them to climb or dig.', 'Sharp claws help many predators catch prey, while other animals use them to climb or dig.', '/klɔː/', 'Móng vuốt sắc nhọn giúp nhiều loài săn mồi bắt con mồi, trong khi các loài khác dùng chúng để leo trèo hoặc đào bới.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_18_2_4', 'ten_b2_18_2', 'dawn', 'The dawn of digital communication has transformed how people maintain relationships across national borders.', 'The dawn of digital communication has transformed how people maintain relationships across national borders.', '/dɔːn/', 'Sự khởi đầu của kỷ nguyên truyền thông kỹ thuật số đã thay đổi cách con người duy trì các mối quan hệ vượt biên giới quốc gia.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_18_2_5', 'ten_b2_18_2', 'shallow', 'Shallow coastal waters provide important habitats for young fish, making their protection essential for sustainable fisheries.', 'Shallow coastal waters provide important habitats for young fish, making their protection essential for sustainable fisheries.', '/ˈʃæloʊ/', 'Vùng nước ven biển nông cung cấp môi trường sống quan trọng cho cá non, khiến việc bảo vệ chúng trở nên thiết yếu đối với nghề cá bền vững.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_18_2_6', 'ten_b2_18_2', 'graze', 'Allowing cattle to graze too intensively can damage vegetation and increase the risk of soil erosion.', 'Allowing cattle to graze too intensively can damage vegetation and increase the risk of soil erosion.', '/ɡreɪz/', 'Để gia súc gặm cỏ quá mức có thể tàn phá thảm thực vật và làm tăng nguy cơ xói mòn đất.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_18_2_1', 'en-b2-18', 'ten_b2_18_2', 'listening', 'listening', 'Abandoned mining pits can threaten local ecosystems unless restoration projects stabilise the soil and improve water quality.', NULL, 'Trong câu vừa nghe, từ “pit” mang nghĩa nào sau đây?', '["bạo lực; hung bạo","hiệu suất, hiệu quả làm việc","cái hố; hầm sâu","tuyệt vời, tuyệt diệu"]'::jsonb, 2, '“pit” (/pɪt/): cái hố; hầm sâu. Câu đầy đủ: Abandoned mining pits can threaten local ecosystems unless restoration projects stabilise the soil and improve water quality.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_18_2_2', 'en-b2-18', 'ten_b2_18_2', 'listening', 'listening', 'Protecting natural habitats is essential for preventing the extinction of species threatened by human activity.', NULL, 'Trong câu vừa nghe, từ “species” mang nghĩa nào sau đây?', '["có miễn dịch; kháng bệnh","chức năng; tác dụng","suy đoán; phỏng đoán","loài (sinh học)"]'::jsonb, 3, '“species” (/ˈspiːʃiːz/): loài (sinh học). Câu đầy đủ: Protecting natural habitats is essential for preventing the extinction of species threatened by human activity.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_18_1', 'en-b2-18', 'We dug a shallow pit for the new tree', 'Chúng tôi đã đào một cái hố nông để trồng cây mới.', 'pit /pɪt/', '["We","tree","for","the","pit","a","new","dug","shallow"]'::jsonb, NULL, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_18_2', 'en-b2-18', 'Several species of butterfly visit our garden each summer', 'Một vài loài bướm ghé thăm khu vườn của chúng tôi vào mỗi mùa hè.', 'species /ˈspiːʃiːz/', '["species","our","garden","each","summer","Several","visit","butterfly","of"]'::jsonb, NULL, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_18_3', 'en-b2-18', 'The cat caught my sleeve with one sharp claw', 'Con mèo đã cào vào tay áo tôi bằng một chiếc móng sắc nhọn.', 'claw /klɔː/', '["The","sleeve","caught","with","sharp","cat","my","one","claw"]'::jsonb, NULL, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_18_4', 'en-b2-18', 'We left at dawn to avoid the heavy traffic', 'Chúng tôi khởi hành từ lúc rạng đông để tránh tình trạng kẹt xe nặng.', 'dawn /dɔːn/', '["dawn","avoid","We","at","to","the","heavy","left","traffic"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_18_5', 'en-b2-18', 'The children splashed happily in the shallow end of the pool', 'Bọn trẻ vui đùa thỏa thích ở khu vực nước cạn của hồ bơi.', 'shallow /ˈʃæloʊ/', '["end","in","splashed","the","of","pool","happily","children","The","shallow","the"]'::jsonb, NULL, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_18_6', 'en-b2-18', 'Sheep graze quietly beside the river every summer morning', 'Đàn cừu thong thả gặm cỏ bên bờ sông vào mỗi buổi sáng mùa hè.', 'graze /ɡreɪz/', '["Sheep","summer","quietly","graze","morning","river","every","beside","the"]'::jsonb, NULL, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_18_7', 'en-b2-18', 'A white dove landed gently on our garden wall', 'Một con chim bồ câu trắng nhẹ nhàng đậu trên bức tường vườn nhà chúng tôi.', 'dove /dʌv/', '["garden","landed","our","dove","wall","white","gently","A","on"]'::jsonb, NULL, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_18_8', 'en-b2-18', 'Fresh fruit is abundant here during the summer', 'Trái cây tươi rất dồi dào ở đây vào mùa hè.', 'abundant /əˈbʌndənt/', '["is","here","the","during","Fresh","fruit","abundant","summer"]'::jsonb, NULL, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
