INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_18_2', 'en-b2-18', NULL, 'comprehensive_test', 'listening', 'Several species of butterfly visit our garden each summer.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một vài loài bướm ghé thăm khu vườn của chúng tôi vào mỗi mùa hè.","Ánh trăng chiếu qua rèm cửa lên chiếc gối của tôi.","Cô ấy đổ đầy nước vào chậu để rửa mặt.","Vào lúc thủy triều xuống, chúng tôi đi bộ qua bãi cát lộ thiên."]'::jsonb, 0, 'Several species of butterfly visit our garden each summer. → Một vài loài bướm ghé thăm khu vườn của chúng tôi vào mỗi mùa hè.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_18_3', 'en-b2-18', NULL, 'comprehensive_test', 'listening', 'claw', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đường cong; khúc cua","gây tranh cãi; có nhiều ý kiến trái chiều","móng vuốt","vết thương; thương tích"]'::jsonb, 2, 'claw (/klɔː/) → móng vuốt; càng (cua, ghẹ); cào; cấu bằng móng vuốt hoặc ngón tay', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_18_4', 'en-b2-18', NULL, 'comprehensive_test', 'listening', 'We left at dawn to avoid the heavy traffic.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy đổ đầy nước vào chậu để rửa mặt.","Một hàng rào cây xanh rậm rạp ngăn cách khu vườn nhà chúng tôi với lối đi bộ.","Chúng tôi khởi hành từ lúc rạng đông để tránh tình trạng kẹt xe nặng.","Đàn cừu thong thả gặm cỏ bên bờ sông vào mỗi buổi sáng mùa hè."]'::jsonb, 2, 'We left at dawn to avoid the heavy traffic. → Chúng tôi khởi hành từ lúc rạng đông để tránh tình trạng kẹt xe nặng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_18_5', 'en-b2-18', NULL, 'comprehensive_test', 'listening', 'shallow', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đi nhón chân, đi rón rén","nông; cạn","thuộc về bán đảo Ả Rập","bộ lọc; thiết bị lọc"]'::jsonb, 1, 'shallow (/ˈʃæloʊ/) → nông; cạn; nông cạn; hời hợt; thiếu sâu sắc; nông (hơi thở nông)', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_18_6', 'en-b2-18', NULL, 'comprehensive_test', 'listening', 'Sheep graze quietly beside the river every summer morning.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Đàn cừu thong thả gặm cỏ bên bờ sông vào mỗi buổi sáng mùa hè.","Chúng tôi đứng nhìn một con thuyền nhỏ khuất dần sau đường chân trời.","Một con bọ cánh cứng sáng bóng bò chậm chạp qua lối đi trong vườn.","Chúng tôi khởi hành từ lúc rạng đông để tránh tình trạng kẹt xe nặng."]'::jsonb, 0, 'Sheep graze quietly beside the river every summer morning. → Đàn cừu thong thả gặm cỏ bên bờ sông vào mỗi buổi sáng mùa hè.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_18_7', 'en-b2-18', NULL, 'comprehensive_test', 'listening', 'dove', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nhà u tư; chủ doanh nghiệp; doanh nhân","chim bồ câu","tủ có ngăn kéo để đựng quần áo (kiểu Mỹ)","công tác quản lý; hoạt động hành chính"]'::jsonb, 1, 'dove (/dʌv/) → chim bồ câu; người chủ hòa; phe chủ hòa', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_18_8', 'en-b2-18', NULL, 'comprehensive_test', 'listening', 'Fresh fruit is abundant here during the summer.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Trái cây tươi rất dồi dào ở đây vào mùa hè.","Chúng tôi nghỉ ngơi dưới bóng một cây thông cao sau bữa trưa.","Một quả bí ngô khổng lồ chiếm trọn chiếc bàn ăn.","Con công đực xòe chiếc đuôi rực rỡ bên bờ ao."]'::jsonb, 0, 'Fresh fruit is abundant here during the summer. → Trái cây tươi rất dồi dào ở đây vào mùa hè.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_18_9', 'en-b2-18', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Having little depth from the surface to the bottom”?', '["changeable","shallow","species","flesh"]'::jsonb, 1, 'shallow (/ˈʃæloʊ/) → nông; cạn', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
