INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_18_18', 'en-b2-18', NULL, 'comprehensive_test', 'reading', NULL, 'Abandoned mining pits can threaten local ecosystems unless restoration projects stabilise the soil and improve water quality.', 'Dựa vào câu trên, từ “pit” có nghĩa phù hợp nhất là gì?', '["cái hố; hầm sâu","hoàn toàn; tuyệt đối","bằng lời nói; dạng nói (thay vì dạng viết)","tốt hơn; chất lượng cao hơn"]'::jsonb, 0, 'pit: cái hố; hầm sâu; khu vực bảo dưỡng xe đua; hột (của một số loại quả). Dịch cả câu: Các mỏ quặng bỏ hoang có thể đe dọa hệ sinh thái địa phương trừ khi các dự án phục hồi có thể ổn định đất và cải thiện chất lượng nguồn nước.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_18_19', 'en-b2-18', NULL, 'comprehensive_test', 'reading', NULL, 'Protecting natural habitats is essential for preventing the extinction of species threatened by human activity.', 'Dựa vào câu trên, từ “species” có nghĩa phù hợp nhất là gì?', '["làm quá tải; chồng chất gánh nặng","loài (sinh học)","nâng cao; tăng cường; cải thiện","phai màu; làm phai màu"]'::jsonb, 1, 'species: loài (sinh học). Dịch cả câu: Bảo vệ các sinh cảnh tự nhiên là điều cốt yếu để ngăn chặn sự tuyệt chủng của các loài đang bị đe dọa bởi hoạt động của con người.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_18_20', 'en-b2-18', NULL, 'comprehensive_test', 'reading', NULL, 'Sharp claws help many predators catch prey, while other animals use them to climb or dig.', 'Dựa vào câu trên, từ “claw” có nghĩa phù hợp nhất là gì?', '["đặc quyền; sự ưu đãi đặc biệt","không được hoàn tiền; không thể trả lại tiền","đòi hỏi nhiều nỗ lực; khắt khe; vất vả","móng vuốt"]'::jsonb, 3, 'claw: móng vuốt; càng (cua, ghẹ); cào; cấu bằng móng vuốt hoặc ngón tay. Dịch cả câu: Móng vuốt sắc nhọn giúp nhiều loài săn mồi bắt con mồi, trong khi các loài khác dùng chúng để leo trèo hoặc đào bới.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_18_21', 'en-b2-18', NULL, 'comprehensive_test', 'reading', NULL, 'The dawn of digital communication has transformed how people maintain relationships across national borders.', 'Dựa vào câu trên, từ “dawn” có nghĩa phù hợp nhất là gì?', '["hoạt động gây quỹ; quyên góp","buổi bình minh; rạng đông","đại bác; hải pháo","có ích; có lợi"]'::jsonb, 1, 'dawn: buổi bình minh; rạng đông; sự khởi đầu; thời kỳ khai nguyên; bắt đầu ló dạng; vỡ lẽ. Dịch cả câu: Sự khởi đầu của kỷ nguyên truyền thông kỹ thuật số đã thay đổi cách con người duy trì các mối quan hệ vượt biên giới quốc gia.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_18_22', 'en-b2-18', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đường chân trời”', '["octopus","deceive","philosopher","horizon"]'::jsonb, 3, 'đường chân trời → horizon (/həˈraɪzən/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_18_23', 'en-b2-18', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thịt; phần mô mềm giữa da và xương”', '["rip","flesh","flap","subjective"]'::jsonb, 1, 'thịt; phần mô mềm giữa da và xương → flesh (/fleʃ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_18_24', 'en-b2-18', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sườn đồi; dốc đồi”', '["imitation","distinct","sponsorship","hillside"]'::jsonb, 3, 'sườn đồi; dốc đồi → hillside (/ˈhɪlsaɪd/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-19', 'en', 'Bài 19: Thiên nhiên & Thời tiết (2) - CEFR B2', 'CEFR B2', 'B2 · Thiên nhiên', '27 từ vựng Tiếng Anh CEFR B2 chủ đề thiên nhiên & thời tiết kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4019, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_squirrel', 'en-b2-19', 'squirrel', '/ˈskwɜːrəl/', 'B2', 'con sóc; cất giấu; tích trữ (thường dùng với "away")', 'n.', NULL, NULL, 'Khi dùng như động từ thường đi với "away" ("squirrel away"), mang nghĩa cất giấu hoặc tích trữ một cách kín đáo.', 'A squirrel buried a nut beside our garden gate.', NULL, 'Một con sóc đã chôn một hạt dẻ bên cạnh cổng vườn nhà tôi.', '{"wordId":"squirrel","ukIpa":"/ˈskwɪrəl/","usIpa":"/ˈskwɜːrəl/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A small rodent with a bushy tail, often living in trees.","vi":"con sóc"},{"pos":"v.","en":"To store something secretly for later use, usually with away.","vi":"cất giấu; tích trữ (thường dùng với \"away\")"}],"examples":[{"en":"A squirrel buried a nut beside our garden gate.","vi":"Một con sóc đã chôn một hạt dẻ bên cạnh cổng vườn nhà tôi.","audioKind":"ex"},{"en":"Urban parks provide squirrels with food and shelter, although feeding them can alter their natural behaviour.","vi":"Các công viên đô thị cung cấp thức ăn và nơi trú ẩn cho sóc, mặc dù việc cho chúng ăn có thể làm thay đổi tập tính tự nhiên của chúng.","audioKind":"ex2"}],"collocations":[{"en":"a grey squirrel","vi":"sóc xám"},{"en":"a red squirrel","vi":"sóc đỏ"},{"en":"squirrel away money","vi":"tích cóp tiền bạc"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi dùng như động từ thường đi với \"away\" (\"squirrel away\"), mang nghĩa cất giấu hoặc tích trữ một cách kín đáo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_drift', 'en-b2-19', 'drift', '/drɪft/', 'B2', 'trôi dạt; bay lơ lửng; trôi đi; dần chệch hướng; ý chính; đại ý', 'v.', 'drifter (n.), drifting (adj.)', 'Đồng nghĩa: float', '"drift" nhấn mạnh việc di chuyển theo nước, gió, hoặc thiếu phương hướng rõ ràng.', 'We watched a fallen leaf drift across the pond.', NULL, 'Chúng tôi ngắm nhìn một chiếc lá rụng trôi qua mặt ao.', '{"wordId":"drift","ukIpa":"/drɪft/","usIpa":"/drɪft/","cefr":"B2","topic":"nature","senses":[{"pos":"v.","en":"To move slowly, carried by water or air.","vi":"trôi dạt; bay lơ lửng"},{"pos":"v.","en":"To move or change gradually without clear purpose or control.","vi":"trôi đi; dần chệch hướng"},{"pos":"n.","en":"The general meaning of what someone says or writes.","vi":"ý chính; đại ý"}],"examples":[{"en":"We watched a fallen leaf drift across the pond.","vi":"Chúng tôi ngắm nhìn một chiếc lá rụng trôi qua mặt ao.","audioKind":"ex"},{"en":"Without affordable housing and stable employment, young residents may gradually drift away from rural communities.","vi":"Nếu không có nhà ở giá rẻ và việc làm ổn định, cư dân trẻ tuổi có thể dần rời bỏ các cộng đồng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"drift apart","vi":"dần xa cách"},{"en":"drift off to sleep","vi":"chìm vào giấc ngủ"},{"en":"drift away","vi":"dần rời xa"},{"en":"get the drift","vi":"nắm được đại ý"}],"wordFamily":["drifter (n.)","drifting (adj.)"],"synonyms":["float"],"antonyms":[],"tipVi":"\"drift\" nhấn mạnh việc di chuyển theo nước, gió, hoặc thiếu phương hướng rõ ràng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_charcoal', 'en-b2-19', 'charcoal', '/ˈtʃɑːrkoʊl/', 'B2', 'than củi; than gỗ; than vẽ; bút than', 'n.', NULL, NULL, '"charcoal" thường là danh từ không đếm được; "coal" là than đá, không phải than củi.', 'We cooked the vegetables over glowing charcoal in the garden.', NULL, 'Chúng tôi nướng rau củ trên bếp than hồng trong vườn.', '{"wordId":"charcoal","ukIpa":"/ˈtʃɑːkəʊl/","usIpa":"/ˈtʃɑːrkoʊl/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A black material made by heating wood with little air.","vi":"than củi; than gỗ"},{"pos":"n.","en":"Charcoal sticks used for drawing.","vi":"than vẽ; bút than"}],"examples":[{"en":"We cooked the vegetables over glowing charcoal in the garden.","vi":"Chúng tôi nướng rau củ trên bếp than hồng trong vườn.","audioKind":"ex"},{"en":"Heavy demand for charcoal can contribute to deforestation where trees are harvested faster than they can regrow.","vi":"Nhu cầu tiêu thụ than củi lớn có thể góp phần gây ra nạn phá rừng ở những nơi cây bị chặt nhanh hơn tốc độ tái sinh.","audioKind":"ex2"}],"collocations":[{"en":"charcoal grill","vi":"bếp nướng than"},{"en":"charcoal drawing","vi":"tranh vẽ bằng than"},{"en":"activated charcoal","vi":"than hoạt tính"},{"en":"charcoal production","vi":"sản xuất than củi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"\"charcoal\" thường là danh từ không đếm được; \"coal\" là than đá, không phải than củi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_breed', 'en-b2-19', 'breed', '/briːd/', 'B2', 'sinh sản; gây giống; giống (vật nuôi); gây ra; sinh ra', 'v.', 'breeder (n.), breeding (n.), crossbreed (v.)', 'Đồng nghĩa: reproduce', 'Dạng quá khứ và quá khứ phân từ đều là bred; breed (giống loài vật nuôi) khác với species (loài sinh học).', 'These birds usually breed here during the warmer months.', NULL, 'Những loài chim này thường sinh sản ở đây trong những tháng ấm áp hơn.', '{"wordId":"breed","ukIpa":"/briːd/","usIpa":"/briːd/","cefr":"B2","topic":"nature","senses":[{"pos":"v.","en":"To produce young, or keep animals to produce young.","vi":"sinh sản; gây giống"},{"pos":"n.","en":"A group of domestic animals sharing particular inherited characteristics.","vi":"giống (vật nuôi)"},{"pos":"v.","en":"To cause something, especially something harmful, to develop.","vi":"gây ra; sinh ra"}],"examples":[{"en":"These birds usually breed here during the warmer months.","vi":"Những loài chim này thường sinh sản ở đây trong những tháng ấm áp hơn.","audioKind":"ex"},{"en":"Conservation programmes breed endangered animals in protected environments before releasing them into suitable natural habitats.","vi":"Các chương trình bảo tồn nhân giống động vật có nguy cơ tuyệt chủng trong môi trường được bảo vệ trước khi thả chúng về môi trường sống tự nhiên phù hợp.","audioKind":"ex2"}],"collocations":[{"en":"breeding season","vi":"mùa sinh sản"},{"en":"a breed of dog","vi":"một giống chó"},{"en":"breed animals","vi":"gây giống động vật"},{"en":"breed resentment","vi":"nuôi dưỡng sự oán giận"}],"wordFamily":["breeder (n.)","breeding (n.)","crossbreed (v.)"],"synonyms":["reproduce"],"antonyms":[],"tipVi":"Dạng quá khứ và quá khứ phân từ đều là bred; breed (giống loài vật nuôi) khác với species (loài sinh học).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_turnip', 'en-b2-19', 'turnip', '/ˈtɝːnɪp/', 'B2', 'củ cải trắng (phần đầu có màu tím)', 'n.', NULL, NULL, 'Chỉ củ cải trắng (turnip); tránh nhầm lẫn với radish (củ cải đỏ) hoặc swede (củ cải Thụy Điển).', 'I added a chopped turnip to the vegetable soup.', NULL, 'Tôi đã thêm một củ cải trắng cắt nhỏ vào món súp rau củ.', '{"wordId":"turnip","ukIpa":"/ˈtɜːnɪp/","usIpa":"/ˈtɝːnɪp/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"a round root vegetable, usually white with a purple top","vi":"củ cải trắng (phần đầu có màu tím)"}],"examples":[{"en":"I added a chopped turnip to the vegetable soup.","vi":"Tôi đã thêm một củ cải trắng cắt nhỏ vào món súp rau củ.","audioKind":"ex"},{"en":"Growing root vegetables such as turnips can help communities diversify local food supplies during cooler months.","vi":"Việc trồng các loại rau củ như củ cải trắng có thể giúp cộng đồng đa dạng hóa nguồn cung cấp thực phẩm địa phương trong những tháng lạnh hơn.","audioKind":"ex2"}],"collocations":[{"en":"roasted turnips","vi":"củ cải trắng nướng"},{"en":"turnip greens","vi":"lá củ cải trắng"},{"en":"turnip soup","vi":"súp củ cải trắng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ củ cải trắng (turnip); tránh nhầm lẫn với radish (củ cải đỏ) hoặc swede (củ cải Thụy Điển).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flock', 'en-b2-19', 'flock', '/flɑːk/', 'B2', 'đàn (chim, cừu hoặc dê); tụ tập đông đảo; đổ xô đến', 'n.', NULL, 'Đồng nghĩa: gather, crowd · Trái nghĩa: disperse', 'Dùng từ flock cho đàn chim và cừu; đối với đàn bò thường dùng herd.', 'A flock of geese landed beside the quiet lake.', NULL, 'Một đàn ngỗng hạ xuống bên hồ nước yên tĩnh.', '{"wordId":"flock","ukIpa":"/flɒk/","usIpa":"/flɑːk/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A group of birds, sheep, or goats","vi":"đàn (chim, cừu hoặc dê)"},{"pos":"v.","en":"Go or gather somewhere in large numbers","vi":"tụ tập đông đảo; đổ xô đến"}],"examples":[{"en":"A flock of geese landed beside the quiet lake.","vi":"Một đàn ngỗng hạ xuống bên hồ nước yên tĩnh.","audioKind":"ex"},{"en":"Visitors flock to coastal towns during summer, bringing income but also placing pressure on local infrastructure.","vi":"Du khách đổ xô đến các thị trấn ven biển vào mùa hè, mang lại nguồn thu nhập nhưng đồng thời cũng gây áp lực lên cơ sở hạ tầng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a flock of sheep","vi":"một đàn cừu"},{"en":"a flock of birds","vi":"một đàn chim"},{"en":"flock to","vi":"đổ xô đến"},{"en":"flock together","vi":"tụ tập lại với nhau"}],"wordFamily":[],"synonyms":["gather","crowd"],"antonyms":["disperse"],"tipVi":"Dùng từ flock cho đàn chim và cừu; đối với đàn bò thường dùng herd.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_octopus', 'en-b2-19', 'octopus', '/ˈɑːktəpəs/', 'B2', 'con bạch tuộc', 'n.', NULL, NULL, 'Dạng số nhiều phổ biến là "octopuses"; các xúc tu của chúng thường được gọi là "arms".', 'An octopus squeezed through a narrow gap between rocks.', NULL, 'Một con bạch tuộc đã lách qua khe hẹp giữa các tảng đá.', '{"wordId":"octopus","ukIpa":"/ˈɒktəpəs/","usIpa":"/ˈɑːktəpəs/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"a sea animal with a soft body and eight arms","vi":"con bạch tuộc"}],"examples":[{"en":"An octopus squeezed through a narrow gap between rocks.","vi":"Một con bạch tuộc đã lách qua khe hẹp giữa các tảng đá.","audioKind":"ex"},{"en":"Research into octopus behaviour has revealed remarkable learning abilities, challenging traditional assumptions about intelligence in marine animals.","vi":"Nghiên cứu về tập tính của bạch tuộc đã hé lộ khả năng học hỏi đáng kinh ngạc, thách thức những quan niệm truyền thống về trí thông minh ở động vật biển.","audioKind":"ex2"}],"collocations":[{"en":"octopus arms","vi":"các xúc tu của bạch tuộc"},{"en":"octopus behaviour","vi":"hành vi của bạch tuộc"},{"en":"a giant octopus","vi":"một con bạch tuộc khổng lồ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều phổ biến là \"octopuses\"; các xúc tu của chúng thường được gọi là \"arms\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_canyon', 'en-b2-19', 'canyon', '/ˈkænjən/', 'B2', 'hẻm núi; vực sâu có vách đá dựng đứng và thường có sông chảy qua', 'n.', NULL, 'Đồng nghĩa: gorge', 'canyon nhấn mạnh thung lũng sâu và hai bên vách đá dựng đứng; valley dùng chung cho các loại thung lũng.', 'We watched a river winding through the rocky canyon.', NULL, 'Chúng tôi ngắm nhìn dòng sông uốn lượn qua hẻm núi đá.', '{"wordId":"canyon","ukIpa":"/ˈkænjən/","usIpa":"/ˈkænjən/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A deep valley with steep sides, often containing a river.","vi":"hẻm núi; vực sâu có vách đá dựng đứng và thường có sông chảy qua"}],"examples":[{"en":"We watched a river winding through the rocky canyon.","vi":"Chúng tôi ngắm nhìn dòng sông uốn lượn qua hẻm núi đá.","audioKind":"ex"},{"en":"Tourism in remote canyon regions can generate income, but excessive development may threaten fragile natural habitats.","vi":"Hoạt động du lịch tại các vùng hẻm núi hẻo lánh có thể tạo ra thu nhập, nhưng việc phát triển quá mức có thể đe dọa các môi trường sống tự nhiên vốn mỏng manh.","audioKind":"ex2"}],"collocations":[{"en":"deep canyon","vi":"hẻm núi sâu"},{"en":"canyon walls","vi":"vách hẻm núi"},{"en":"canyon floor","vi":"đáy hẻm núi"}],"wordFamily":[],"synonyms":["gorge"],"antonyms":[],"tipVi":"canyon nhấn mạnh thung lũng sâu và hai bên vách đá dựng đứng; valley dùng chung cho các loại thung lũng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tornado', 'en-b2-19', 'tornado', '/tɔːrˈneɪdoʊ/', 'B2', 'cơn lốc xoáy; vòi rồng', 'n.', NULL, NULL, 'Dạng số nhiều có thể viết là tornadoes hoặc tornados.', 'We watched the tornado from a safe underground shelter.', NULL, 'Chúng tôi quan sát trận lốc xoáy từ một hầm trú ẩn ngầm an toàn.', '{"wordId":"tornado","ukIpa":"/tɔːˈneɪdəʊ/","usIpa":"/tɔːrˈneɪdoʊ/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"a violently rotating column of air reaching down from a cloud","vi":"cơn lốc xoáy; vòi rồng"}],"examples":[{"en":"We watched the tornado from a safe underground shelter.","vi":"Chúng tôi quan sát trận lốc xoáy từ một hầm trú ẩn ngầm an toàn.","audioKind":"ex"},{"en":"Effective warning systems can reduce injuries when a tornado approaches a densely populated area.","vi":"Hệ thống cảnh báo hiệu quả có thể giảm thiểu thương vong khi một trận lốc xoáy tiến đến khu vực đông dân cư.","audioKind":"ex2"}],"collocations":[{"en":"a powerful tornado","vi":"một trận lốc xoáy mạnh"},{"en":"tornado warning","vi":"cảnh báo lốc xoáy"},{"en":"tornado damage","vi":"thiệt hại do lốc xoáy"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều có thể viết là tornadoes hoặc tornados.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_instinct', 'en-b2-19', 'instinct', '/ˈɪnstɪŋkt/', 'B2', 'bản năng; thiên tính; sự mách bảo của trực giác; cảm tính', 'n.', 'instinctive (adj.), instinctively (adv.), instinctual (adj.)', 'Đồng nghĩa: intuition, gut feeling', 'instinct thường chỉ bản năng bẩm sinh; intuition thiên về năng lực phán đoán bằng trực giác.', 'By instinct, the newborn kitten searched for its mother.', NULL, 'Theo bản năng, chú mèo con mới sinh đã tìm kiếm mẹ của mình.', '{"wordId":"instinct","ukIpa":"/ˈɪnstɪŋkt/","usIpa":"/ˈɪnstɪŋkt/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A natural tendency to behave without learning or conscious thought.","vi":"bản năng; thiên tính"},{"pos":"n.","en":"A feeling about something that does not involve conscious reasoning.","vi":"sự mách bảo của trực giác; cảm tính"}],"examples":[{"en":"By instinct, the newborn kitten searched for its mother.","vi":"Theo bản năng, chú mèo con mới sinh đã tìm kiếm mẹ của mình.","audioKind":"ex"},{"en":"Although instinct can guide rapid decisions, public health policies should primarily rely on reliable scientific evidence.","vi":"Mặc dù trực giác có thể định hướng cho các quyết định nhanh chóng, các chính sách y tế công cộng vẫn nên chủ yếu dựa vào các bằng chứng khoa học đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"survival instinct","vi":"bản năng sinh tồn"},{"en":"by instinct","vi":"theo bản năng"},{"en":"trust your instincts","vi":"tin vào trực giác của bạn"},{"en":"an instinct for","vi":"bản năng thiên bẩm về..."}],"wordFamily":["instinctive (adj.)","instinctively (adv.)","instinctual (adj.)"],"synonyms":["intuition","gut feeling"],"antonyms":[],"tipVi":"instinct thường chỉ bản năng bẩm sinh; intuition thiên về năng lực phán đoán bằng trực giác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plentiful', 'en-b2-19', 'plentiful', '/ˈplentɪfəl/', 'B2', 'dồi dào; phong phú', 'adj.', 'plenty (pron.), plentifully (adv.)', 'Đồng nghĩa: abundant, ample · Trái nghĩa: scarce', 'Biểu thị vật tư hoặc cơ hội dồi dào, không dùng để chỉ một người giàu có.', 'Fresh berries are plentiful at the market this summer.', NULL, 'Vào mùa hè năm nay, các loại quả mọng tươi có rất nhiều ở chợ.', '{"wordId":"plentiful","ukIpa":"/ˈplentɪfəl/","usIpa":"/ˈplentɪfəl/","cefr":"B2","topic":"nature","senses":[{"pos":"adj.","en":"Available in large amounts or numbers.","vi":"dồi dào; phong phú"}],"examples":[{"en":"Fresh berries are plentiful at the market this summer.","vi":"Vào mùa hè năm nay, các loại quả mọng tươi có rất nhiều ở chợ.","audioKind":"ex"},{"en":"Regions with plentiful sunshine are well placed to generate affordable electricity through investment in solar technology.","vi":"Những vùng có ánh nắng dồi dào có vị thế thuận lợi để sản xuất điện giá rẻ thông qua đầu tư vào công nghệ năng lượng mặt trời.","audioKind":"ex2"}],"collocations":[{"en":"a plentiful supply","vi":"nguồn cung dồi dào"},{"en":"plentiful resources","vi":"tài nguyên phong phú"},{"en":"plentiful food","vi":"thực phẩm dồi dào"}],"wordFamily":["plenty (pron.)","plentifully (adv.)"],"synonyms":["abundant","ample"],"antonyms":["scarce"],"tipVi":"Biểu thị vật tư hoặc cơ hội dồi dào, không dùng để chỉ một người giàu có.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_trunk', 'en-b2-19', 'trunk', '/trʌŋk/', 'B2', 'thân cây; vòi voi; cốp xe ô tô', 'n.', NULL, NULL, 'Cốp xe ô tô trong tiếng Mỹ dùng trunk, tiếng Anh-Anh dùng boot.', 'We rested against the trunk of an old oak.', NULL, 'Chúng tôi tựa lưng vào thân của một cây sồi cổ thụ để nghỉ ngơi.', '{"wordId":"trunk","ukIpa":"/trʌŋk/","usIpa":"/trʌŋk/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"The thick main stem of a tree.","vi":"thân cây"},{"pos":"n.","en":"An elephant''s long nose, used for breathing and holding things.","vi":"vòi voi"},{"pos":"n.","en":"The enclosed space in a car for carrying luggage.","vi":"cốp xe ô tô"}],"examples":[{"en":"We rested against the trunk of an old oak.","vi":"Chúng tôi tựa lưng vào thân của một cây sồi cổ thụ để nghỉ ngơi.","audioKind":"ex"},{"en":"Damage to a tree''s trunk can reduce its ability to transport water and nutrients.","vi":"Tổn thương ở thân cây có thể làm giảm khả năng vận chuyển nước và chất dinh dưỡng của cây.","audioKind":"ex2"}],"collocations":[{"en":"tree trunk","vi":"thân cây"},{"en":"an elephant''s trunk","vi":"vòi voi"},{"en":"car trunk","vi":"cốp xe ô tô"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cốp xe ô tô trong tiếng Mỹ dùng trunk, tiếng Anh-Anh dùng boot.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gravel', 'en-b2-19', 'gravel', '/ˈɡrævəl/', 'B2', 'sỏi; đá dăm', 'n.', 'gravelly (adj.)', NULL, 'Thường là danh từ không đếm được; một viên sỏi nhỏ có thể dùng a pebble.', 'Gravel crunched beneath our shoes as we approached the cottage.', NULL, 'Những viên sỏi kêu lạo xạo dưới giày chúng tôi khi cả nhóm tiến lại gần ngôi nhà nhỏ.', '{"wordId":"gravel","ukIpa":"/ˈɡrævl/","usIpa":"/ˈɡrævəl/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"small stones used to cover paths or make concrete","vi":"sỏi; đá dăm"}],"examples":[{"en":"Gravel crunched beneath our shoes as we approached the cottage.","vi":"Những viên sỏi kêu lạo xạo dưới giày chúng tôi khi cả nhóm tiến lại gần ngôi nhà nhỏ.","audioKind":"ex"},{"en":"Gravel paths can allow rainwater to drain into the soil, reducing surface runoff in urban parks.","vi":"Những lối đi rải sỏi cho phép nước mưa thấm xuống đất, làm giảm dòng chảy bề mặt tại các công viên đô thị.","audioKind":"ex2"}],"collocations":[{"en":"gravel path","vi":"lối đi rải sỏi"},{"en":"gravel driveway","vi":"lối xe chạy rải sỏi"},{"en":"gravel pit","vi":"mỏ khai thác sỏi"}],"wordFamily":["gravelly (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; một viên sỏi nhỏ có thể dùng a pebble.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_eruption', 'en-b2-19', 'eruption', '/ɪˈrʌpʃən/', 'B2', 'sự phun trào (núi lửa); sự bùng nổ đột ngột', 'n.', 'erupt (v.), eruptive (adj.)', 'Đồng nghĩa: outburst', 'Thường đi kèm với từ volcanic; ngoài ra cũng có thể dùng để chỉ sự bùng nổ của cảm xúc hoặc hoạt động nào đó.', 'We watched the eruption from a safe distance.', NULL, 'Chúng tôi đứng từ một khoảng cách an toàn để theo dõi vụ phun trào.', '{"wordId":"eruption","ukIpa":"/ɪˈrʌpʃən/","usIpa":"/ɪˈrʌpʃən/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"a sudden release of lava, ash, and gases from a volcano","vi":"sự phun trào (núi lửa)"},{"pos":"n.","en":"a sudden, forceful outbreak of an emotion or activity","vi":"sự bùng nổ đột ngột"}],"examples":[{"en":"We watched the eruption from a safe distance.","vi":"Chúng tôi đứng từ một khoảng cách an toàn để theo dõi vụ phun trào.","audioKind":"ex"},{"en":"A major volcanic eruption can disrupt air travel and affect the climate far beyond the surrounding region.","vi":"Một trận phun trào núi lửa lớn có thể làm gián đoạn giao thông hàng không và tác động đến khí hậu ở những vùng rất xa ngoài khu vực xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"volcanic eruption","vi":"núi lửa phun trào"},{"en":"an eruption of anger","vi":"cơn giận bùng phát"},{"en":"predict an eruption","vi":"dự báo một trận phun trào"}],"wordFamily":["erupt (v.)","eruptive (adj.)"],"synonyms":["outburst"],"antonyms":[],"tipVi":"Thường đi kèm với từ volcanic; ngoài ra cũng có thể dùng để chỉ sự bùng nổ của cảm xúc hoặc hoạt động nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_beak', 'en-b2-19', 'beak', '/biːk/', 'B2', 'mỏ chim', 'n.', 'beaked (adj.)', 'Đồng nghĩa: bill', 'Mỏ chim có thể dùng beak hoặc bill; miệng người thường dùng mouth.', 'The sparrow carried a tiny seed in its beak.', NULL, 'Con chim sẻ ngậm một hạt giống nhỏ xíu trong chiếc mỏ của nó.', '{"wordId":"beak","ukIpa":"/biːk/","usIpa":"/biːk/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"The hard, pointed mouth of a bird.","vi":"mỏ chim"}],"examples":[{"en":"The sparrow carried a tiny seed in its beak.","vi":"Con chim sẻ ngậm một hạt giống nhỏ xíu trong chiếc mỏ của nó.","audioKind":"ex"},{"en":"The shape of a bird''s beak reflects its diet and adaptation to particular environmental conditions.","vi":"Hình dáng mỏ của một loài chim phản ánh chế độ ăn uống và khả năng thích nghi của nó với các điều kiện môi trường cụ thể.","audioKind":"ex2"}],"collocations":[{"en":"a sharp beak","vi":"mỏ nhọn"},{"en":"a curved beak","vi":"mỏ cong"},{"en":"in its beak","vi":"trong mỏ"}],"wordFamily":["beaked (adj.)"],"synonyms":["bill"],"antonyms":[],"tipVi":"Mỏ chim có thể dùng beak hoặc bill; miệng người thường dùng mouth.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_peninsula', 'en-b2-19', 'peninsula', '/pəˈnɪnsələ/', 'B2', 'bán đảo', 'n.', 'peninsular (adj.)', NULL, 'Bán đảo là dải đất nối với đất liền nhưng được nước bao bọc xung quanh ba mặt; island chỉ hòn đảo bốn bề là nước.', 'We cycled around the peninsula and stopped at a beach.', NULL, 'Chúng tôi đạp xe vòng quanh bán đảo và dừng chân tại một bãi biển.', '{"wordId":"peninsula","ukIpa":"/pəˈnɪnsjələ/","usIpa":"/pəˈnɪnsələ/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"Land almost surrounded by water but connected to a larger landmass.","vi":"bán đảo"}],"examples":[{"en":"We cycled around the peninsula and stopped at a beach.","vi":"Chúng tôi đạp xe vòng quanh bán đảo và dừng chân tại một bãi biển.","audioKind":"ex"},{"en":"Tourism on the peninsula provides local employment, but excessive development could damage its fragile coastal habitats.","vi":"Ngành du lịch trên bán đảo tạo ra việc làm cho người dân địa phương, nhưng việc phát triển quá mức có thể tàn phá các hệ sinh thái ven biển vốn mong manh tại đây.","audioKind":"ex2"}],"collocations":[{"en":"a narrow peninsula","vi":"bán đảo hẹp"},{"en":"the tip of the peninsula","vi":"mũi bán đảo"},{"en":"on a peninsula","vi":"trên một bán đảo"}],"wordFamily":["peninsular (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Bán đảo là dải đất nối với đất liền nhưng được nước bao bọc xung quanh ba mặt; island chỉ hòn đảo bốn bề là nước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pearl', 'en-b2-19', 'pearl', '/pɝːl/', 'B2', 'hạt ngọc trai', 'n.', 'pearly (adj.)', NULL, 'a pearl là một hạt ngọc trai; dùng a string of pearls để chỉ một chuỗi ngọc trai.', 'A single pearl hung from her silver necklace.', NULL, 'Một viên ngọc trai đơn lẻ được treo trên chiếc dây chuyền bạc của cô ấy.', '{"wordId":"pearl","ukIpa":"/pɜːl/","usIpa":"/pɝːl/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A smooth, usually pale gem formed inside certain shellfish.","vi":"hạt ngọc trai"}],"examples":[{"en":"A single pearl hung from her silver necklace.","vi":"Một viên ngọc trai đơn lẻ được treo trên chiếc dây chuyền bạc của cô ấy.","audioKind":"ex"},{"en":"Pearl farming can provide coastal communities with income, although its environmental effects depend on local management practices.","vi":"Nuôi trồng ngọc trai có thể mang lại thu nhập cho cộng đồng ven biển, dù tác động môi trường của nó phụ thuộc vào phương pháp quản lý địa phương.","audioKind":"ex2"}],"collocations":[{"en":"pearl necklace","vi":"vòng ngọc trai"},{"en":"cultured pearl","vi":"ngọc trai nuôi"},{"en":"a string of pearls","vi":"một chuỗi ngọc trai"},{"en":"pearls of wisdom","vi":"lời vàng ý ngọc"}],"wordFamily":["pearly (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"a pearl là một hạt ngọc trai; dùng a string of pearls để chỉ một chuỗi ngọc trai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rooster', 'en-b2-19', 'rooster', '/ˈruːstər/', 'B2', 'gà trống', 'n.', NULL, 'Đồng nghĩa: cockerel', 'rooster thường được dùng trong tiếng Anh-Mỹ; cockerel đặc biệt chỉ gà trống tơ.', 'The rooster woke us just before sunrise this morning.', NULL, 'Con gà trống đã đánh thức chúng tôi dậy ngay trước khi mặt trời mọc vào sáng nay.', '{"wordId":"rooster","ukIpa":"/ˈruːstə/","usIpa":"/ˈruːstər/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"An adult male chicken.","vi":"gà trống"}],"examples":[{"en":"The rooster woke us just before sunrise this morning.","vi":"Con gà trống đã đánh thức chúng tôi dậy ngay trước khi mặt trời mọc vào sáng nay.","audioKind":"ex"},{"en":"Keeping a rooster in a densely populated neighbourhood may cause noise disputes between otherwise friendly neighbours.","vi":"Việc nuôi gà trống ở một khu dân cư đông đúc có thể gây ra tranh chấp tiếng ồn giữa những người hàng xóm vốn thân thiện với nhau.","audioKind":"ex2"}],"collocations":[{"en":"a rooster crows","vi":"gà trống gáy"},{"en":"a rooster''s crow","vi":"tiếng gáy của gà trống"}],"wordFamily":[],"synonyms":["cockerel"],"antonyms":[],"tipVi":"rooster thường được dùng trong tiếng Anh-Mỹ; cockerel đặc biệt chỉ gà trống tơ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bamboo', 'en-b2-19', 'bamboo', '/ˌbæmˈbuː/', 'B2', 'cây tre; tre; vật liệu bằng tre', 'n.', NULL, NULL, 'Khi chỉ chung loài cây hoặc vật liệu, từ này thường không đếm được.', 'She planted bamboo along the fence for extra privacy.', NULL, 'Cô ấy trồng tre dọc theo hàng rào để tăng tính riêng tư.', '{"wordId":"bamboo","ukIpa":"/ˌbæmˈbuː/","usIpa":"/ˌbæmˈbuː/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A tall plant with hollow woody stems, or its strong material.","vi":"cây tre; tre; vật liệu bằng tre"}],"examples":[{"en":"She planted bamboo along the fence for extra privacy.","vi":"Cô ấy trồng tre dọc theo hàng rào để tăng tính riêng tư.","audioKind":"ex"},{"en":"Bamboo grows rapidly and can provide a renewable building material when plantations are managed responsibly.","vi":"Tre lớn lên rất nhanh và có thể cung cấp nguồn vật liệu xây dựng tái tạo khi các khu rừng trồng được quản lý một cách có trách nhiệm.","audioKind":"ex2"}],"collocations":[{"en":"a bamboo forest","vi":"rừng tre"},{"en":"bamboo shoots","vi":"măng"},{"en":"bamboo furniture","vi":"đồ nội thất bằng tre"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ chung loài cây hoặc vật liệu, từ này thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shepherd', 'en-b2-19', 'shepherd', '/ˈʃepərd/', 'B2', 'người chăn cừu; dẫn dắt; hộ tống; hướng dẫn', 'n.', 'shepherdess (n.)', 'Đồng nghĩa: herder, guide', 'Khi là động từ, thường là ngoại động từ: shepherd sb into/through một địa điểm nào đó.', 'The shepherd led the sheep home before sunset.', NULL, 'Người chăn cừu lùa đàn cừu về nhà trước khi mặt trời lặn.', '{"wordId":"shepherd","ukIpa":"/ˈʃepəd/","usIpa":"/ˈʃepərd/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A person who looks after sheep","vi":"người chăn cừu"},{"pos":"v.","en":"To guide people carefully in a particular direction","vi":"dẫn dắt; hộ tống; hướng dẫn"}],"examples":[{"en":"The shepherd led the sheep home before sunset.","vi":"Người chăn cừu lùa đàn cừu về nhà trước khi mặt trời lặn.","audioKind":"ex"},{"en":"Museum staff shepherd visitors through crowded galleries to ensure that everyone can move safely between exhibits.","vi":"Nhân viên bảo tàng hướng dẫn khách tham quan qua các phòng trưng bày đông đúc để đảm bảo mọi người di chuyển an toàn giữa các khu vực triển lãm.","audioKind":"ex2"}],"collocations":[{"en":"a flock of sheep","vi":"một đàn cừu"},{"en":"a shepherd''s hut","vi":"túp lều của người chăn cừu"},{"en":"shepherd visitors through","vi":"hướng dẫn khách tham quan đi qua"}],"wordFamily":["shepherdess (n.)"],"synonyms":["herder","guide"],"antonyms":[],"tipVi":"Khi là động từ, thường là ngoại động từ: shepherd sb into/through một địa điểm nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_typhoon', 'en-b2-19', 'typhoon', '/taɪˈfuːn/', 'B2', 'bão nhiệt đới; bão cuồng phong', 'n.', NULL, NULL, 'Từ này và từ hurricane đều chỉ bão nhiệt đới, tên gọi thay đổi tùy thuộc vào vùng biển xảy ra.', 'We stayed indoors as the typhoon shook the windows.', NULL, 'Chúng tôi ở trong nhà khi cơn bão làm rung chuyển những khung cửa sổ.', '{"wordId":"typhoon","ukIpa":"/taɪˈfuːn/","usIpa":"/taɪˈfuːn/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A powerful tropical storm in the western Pacific Ocean.","vi":"bão nhiệt đới; bão cuồng phong"}],"examples":[{"en":"We stayed indoors as the typhoon shook the windows.","vi":"Chúng tôi ở trong nhà khi cơn bão làm rung chuyển những khung cửa sổ.","audioKind":"ex"},{"en":"Coastal communities need stronger buildings and reliable warning systems to reduce damage caused by typhoons.","vi":"Các cộng đồng ven biển cần những công trình kiên cố hơn cùng hệ thống cảnh báo đáng tin cậy để giảm thiểu thiệt hại do bão gây ra.","audioKind":"ex2"}],"collocations":[{"en":"a powerful typhoon","vi":"một cơn bão lớn"},{"en":"a typhoon hits","vi":"bão đổ bộ"},{"en":"typhoon warning","vi":"cảnh báo bão"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Từ này và từ hurricane đều chỉ bão nhiệt đới, tên gọi thay đổi tùy thuộc vào vùng biển xảy ra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bloom', 'en-b2-19', 'bloom', '/bluːm/', 'B2', 'ra hoa; nở hoa; hoa; sự ra hoa; phát triển rực rỡ; tỏa sáng', 'v.', 'blooming (adj.)', 'Đồng nghĩa: blossom, flower · Trái nghĩa: wither', 'bloom có thể làm động từ; để chỉ trạng thái đang ra hoa, dùng cụm in bloom.', 'The roses bloom beside our kitchen window every summer.', NULL, 'Những khóm hoa hồng nở rộ bên cửa sổ nhà bếp của chúng tôi vào mỗi mùa hè.', '{"wordId":"bloom","ukIpa":"/bluːm/","usIpa":"/bluːm/","cefr":"B2","topic":"nature","senses":[{"pos":"v.","en":"To produce flowers.","vi":"ra hoa; nở hoa"},{"pos":"n.","en":"A flower, or the state of producing flowers.","vi":"hoa; sự ra hoa"},{"pos":"v.","en":"To develop successfully or become more confident and attractive.","vi":"phát triển rực rỡ; tỏa sáng"}],"examples":[{"en":"The roses bloom beside our kitchen window every summer.","vi":"Những khóm hoa hồng nở rộ bên cửa sổ nhà bếp của chúng tôi vào mỗi mùa hè.","audioKind":"ex"},{"en":"Urban gardens that bloom throughout spring and summer provide valuable food sources for bees and other pollinators.","vi":"Các khu vườn đô thị nở hoa suốt mùa xuân và mùa hè cung cấp nguồn thức ăn quý giá cho loài ong và các loài thụ phấn khác.","audioKind":"ex2"}],"collocations":[{"en":"in full bloom","vi":"đang nở rộ"},{"en":"come into bloom","vi":"bắt đầu ra hoa"},{"en":"spring blooms","vi":"những đóa hoa mùa xuân"}],"wordFamily":["blooming (adj.)"],"synonyms":["blossom","flower"],"antonyms":["wither"],"tipVi":"bloom có thể làm động từ; để chỉ trạng thái đang ra hoa, dùng cụm in bloom.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ostrich', 'en-b2-19', 'ostrich', '/ˈɑːstrɪtʃ/', 'B2', 'chim đà điểu', 'n.', NULL, NULL, 'Dạng số nhiều là ostriches; hành vi "vùi đầu vào cát để trốn tránh" thực tế không đúng với loài này.', 'The ostrich ran quickly across the dusty grassland.', NULL, 'Con đà điểu chạy vụt qua bãi cỏ đầy bụi.', '{"wordId":"ostrich","ukIpa":"/ˈɒstrɪtʃ/","usIpa":"/ˈɑːstrɪtʃ/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"a very large flightless bird with long legs and neck","vi":"chim đà điểu"}],"examples":[{"en":"The ostrich ran quickly across the dusty grassland.","vi":"Con đà điểu chạy vụt qua bãi cỏ đầy bụi.","audioKind":"ex"},{"en":"Although the ostrich cannot fly, its powerful legs allow it to escape many predators in open habitats.","vi":"Mặc dù đà điểu không biết bay, nhưng đôi chân khỏe mạnh giúp nó chạy trốn nhiều loài săn mồi ở các vùng sinh sống rộng mở.","audioKind":"ex2"}],"collocations":[{"en":"ostrich egg","vi":"trứng đà điểu"},{"en":"ostrich feather","vi":"lông đà điểu"},{"en":"ostrich farm","vi":"trang trại nuôi đà điểu"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều là ostriches; hành vi \"vùi đầu vào cát để trốn tránh\" thực tế không đúng với loài này.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_decay', 'en-b2-19', 'decay', '/dɪˈkeɪ/', 'B2', 'phân hủy; mục rữa; sự phân hủy; sự mục rữa; sự suy tàn; sự suy thoái', 'v.', 'decayed (adj.), decaying (adj.)', 'Đồng nghĩa: rot, deterioration', 'Danh từ thường không đếm được; tooth decay chỉ sâu răng, không phải rụng răng.', 'Fallen leaves decay slowly beneath the trees each winter.', NULL, 'Lá rụng phân hủy từ từ dưới tán cây vào mỗi mùa đông.', '{"wordId":"decay","ukIpa":"/dɪˈkeɪ/","usIpa":"/dɪˈkeɪ/","cefr":"B2","topic":"nature","senses":[{"pos":"v.","en":"to gradually break down through natural processes","vi":"phân hủy; mục rữa"},{"pos":"n.","en":"the natural process of rotting or breaking down","vi":"sự phân hủy; sự mục rữa"},{"pos":"n.","en":"a gradual loss of strength, quality, or importance","vi":"sự suy tàn; sự suy thoái"}],"examples":[{"en":"Fallen leaves decay slowly beneath the trees each winter.","vi":"Lá rụng phân hủy từ từ dưới tán cây vào mỗi mùa đông.","audioKind":"ex"},{"en":"Urban decay often accelerates when public infrastructure is neglected and businesses move away from residential neighbourhoods.","vi":"Sự suy thoái đô thị thường gia tăng nhanh chóng khi cơ sở hạ tầng công cộng bị bỏ bê và các doanh nghiệp chuyển khỏi các khu dân cư.","audioKind":"ex2"}],"collocations":[{"en":"tooth decay","vi":"sâu răng"},{"en":"urban decay","vi":"sự suy thoái đô thị"},{"en":"decaying vegetation","vi":"thực vật mục rữa"},{"en":"prevent decay","vi":"ngăn ngừa sự phân hủy"}],"wordFamily":["decayed (adj.)","decaying (adj.)"],"synonyms":["rot","deterioration"],"antonyms":[],"tipVi":"Danh từ thường không đếm được; tooth decay chỉ sâu răng, không phải rụng răng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mammal', 'en-b2-19', 'mammal', '/ˈmæməl/', 'B2', 'động vật có vú', 'n.', 'mammalian (adj.)', NULL, 'Cá voi và cá heo cũng là động vật có vú; không nên chỉ dựa vào môi trường sống để phán đoán.', 'A dolphin is a mammal, even though it lives underwater.', NULL, 'Cá heo là một loài động vật có vú, mặc dù nó sống dưới nước.', '{"wordId":"mammal","ukIpa":"/ˈmæməl/","usIpa":"/ˈmæməl/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A warm-blooded animal whose females produce milk for their young.","vi":"động vật có vú"}],"examples":[{"en":"A dolphin is a mammal, even though it lives underwater.","vi":"Cá heo là một loài động vật có vú, mặc dù nó sống dưới nước.","audioKind":"ex"},{"en":"Protecting marine mammals requires international cooperation because these animals often migrate across the waters of several countries.","vi":"Việc bảo vệ các loài động vật có vú ở biển đòi hỏi sự hợp tác quốc tế vì những loài vật này thường di cư qua vùng biển của nhiều quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"marine mammal","vi":"động vật có vú biển"},{"en":"small mammal","vi":"động vật có vú nhỏ"},{"en":"mammal species","vi":"các loài động vật có vú"}],"wordFamily":["mammalian (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cá voi và cá heo cũng là động vật có vú; không nên chỉ dựa vào môi trường sống để phán đoán.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pebble', 'en-b2-19', 'pebble', '/ˈpebəl/', 'B2', 'hòn cuội; viên đá nhỏ nhẵn', 'n.', 'pebbly (adj.)', NULL, 'pebble nhấn mạnh vào viên đá nhỏ và nhẵn; stone dùng để chỉ chung đá.', 'A smooth grey pebble lay beside my wet shoes.', NULL, 'Một viên đá cuội màu xám nhẵn nhụi nằm cạnh đôi giày ướt của tôi.', '{"wordId":"pebble","ukIpa":"/ˈpebəl/","usIpa":"/ˈpebəl/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A small, smooth stone, often found near water.","vi":"hòn cuội; viên đá nhỏ nhẵn"}],"examples":[{"en":"A smooth grey pebble lay beside my wet shoes.","vi":"Một viên đá cuội màu xám nhẵn nhụi nằm cạnh đôi giày ướt của tôi.","audioKind":"ex"},{"en":"Removing pebbles from beaches can disturb coastal habitats and reduce natural protection against erosion.","vi":"Việc lấy sỏi đá cuội khỏi bãi biển có thể làm xáo trộn môi trường sống ven biển và làm giảm khả năng bảo vệ tự nhiên chống lại hiện tượng xói mòn.","audioKind":"ex2"}],"collocations":[{"en":"a smooth pebble","vi":"viên đá cuội nhẵn"},{"en":"a pebble beach","vi":"bãi biển đá cuội"},{"en":"collect pebbles","vi":"nhặt đá cuội"}],"wordFamily":["pebbly (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"pebble nhấn mạnh vào viên đá nhỏ và nhẵn; stone dùng để chỉ chung đá.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ripen', 'en-b2-19', 'ripen', '/ˈraɪpən/', 'B2', 'chín; làm cho chín', 'v.', 'ripe (adj.), ripeness (n.), unripe (adj.)', 'Đồng nghĩa: mature', 'ripe là tính từ; ripen là động từ, có thể là ngoại động từ hoặc nội động từ.', 'Leave these green tomatoes on the windowsill to ripen.', NULL, 'Để những quả cà chua xanh này lên bệ cửa sổ cho chúng tự chín.', '{"wordId":"ripen","ukIpa":"/ˈraɪpən/","usIpa":"/ˈraɪpən/","cefr":"B2","topic":"nature","senses":[{"pos":"v.","en":"to become ripe or make fruit or crops ripe","vi":"chín; làm cho chín"}],"examples":[{"en":"Leave these green tomatoes on the windowsill to ripen.","vi":"Để những quả cà chua xanh này lên bệ cửa sổ cho chúng tự chín.","audioKind":"ex"},{"en":"Warmer temperatures can cause fruit to ripen earlier, forcing farmers to adjust their harvesting schedules.","vi":"Nhiệt độ ấm hơn có thể làm cho trái cây chín sớm hơn, buộc nông dân phải điều chỉnh lịch thu hoạch.","audioKind":"ex2"}],"collocations":[{"en":"ripen naturally","vi":"chín tự nhiên"},{"en":"ripen on the vine","vi":"chín trên giàn"},{"en":"ripen in the sun","vi":"chín dưới ánh nắng"}],"wordFamily":["ripe (adj.)","ripeness (n.)","unripe (adj.)"],"synonyms":["mature"],"antonyms":[],"tipVi":"ripe là tính từ; ripen là động từ, có thể là ngoại động từ hoặc nội động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_19_1', 'en-b2-19', 'Cách dùng “peninsula” (n.) — bán đảo', 'a narrow peninsula  ·  the tip of the peninsula  ·  on a peninsula', 'Bán đảo là dải đất nối với đất liền nhưng được nước bao bọc xung quanh ba mặt; island chỉ hòn đảo bốn bề là nước.', 'Họ từ (Word Family): peninsular (adj.)', '[{"hanzi":"We cycled around the peninsula and stopped at a beach.","pinyin":"","meaning":"Chúng tôi đạp xe vòng quanh bán đảo và dừng chân tại một bãi biển."},{"hanzi":"Tourism on the peninsula provides local employment, but excessive development could damage its fragile coastal habitats.","pinyin":"","meaning":"Ngành du lịch trên bán đảo tạo ra việc làm cho người dân địa phương, nhưng việc phát triển quá mức có thể tàn phá các hệ sinh thái ven biển vốn mong manh tại đây."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_19_2', 'en-b2-19', 'Cách dùng “squirrel” (n.) — con sóc', 'a grey squirrel  ·  a red squirrel  ·  squirrel away money', 'Khi dùng như động từ thường đi với "away" ("squirrel away"), mang nghĩa cất giấu hoặc tích trữ một cách kín đáo.', NULL, '[{"hanzi":"A squirrel buried a nut beside our garden gate.","pinyin":"","meaning":"Một con sóc đã chôn một hạt dẻ bên cạnh cổng vườn nhà tôi."},{"hanzi":"Urban parks provide squirrels with food and shelter, although feeding them can alter their natural behaviour.","pinyin":"","meaning":"Các công viên đô thị cung cấp thức ăn và nơi trú ẩn cho sóc, mặc dù việc cho chúng ăn có thể làm thay đổi tập tính tự nhiên của chúng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_19_3', 'en-b2-19', 'Cách dùng “eruption” (n.) — sự phun trào (núi lửa)', 'volcanic eruption  ·  an eruption of anger  ·  predict an eruption', 'Thường đi kèm với từ volcanic; ngoài ra cũng có thể dùng để chỉ sự bùng nổ của cảm xúc hoặc hoạt động nào đó.', 'Họ từ (Word Family): erupt (v.), eruptive (adj.) | Đồng nghĩa: outburst', '[{"hanzi":"We watched the eruption from a safe distance.","pinyin":"","meaning":"Chúng tôi đứng từ một khoảng cách an toàn để theo dõi vụ phun trào."},{"hanzi":"A major volcanic eruption can disrupt air travel and affect the climate far beyond the surrounding region.","pinyin":"","meaning":"Một trận phun trào núi lửa lớn có thể làm gián đoạn giao thông hàng không và tác động đến khí hậu ở những vùng rất xa ngoài khu vực xung quanh."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_19_4', 'en-b2-19', 'Cách dùng “breed” (v.) — sinh sản; gây giống', 'breeding season  ·  a breed of dog  ·  breed animals', 'Dạng quá khứ và quá khứ phân từ đều là bred; breed (giống loài vật nuôi) khác với species (loài sinh học).', 'Họ từ (Word Family): breeder (n.), breeding (n.), crossbreed (v.) | Đồng nghĩa: reproduce', '[{"hanzi":"These birds usually breed here during the warmer months.","pinyin":"","meaning":"Những loài chim này thường sinh sản ở đây trong những tháng ấm áp hơn."},{"hanzi":"Conservation programmes breed endangered animals in protected environments before releasing them into suitable natural habitats.","pinyin":"","meaning":"Các chương trình bảo tồn nhân giống động vật có nguy cơ tuyệt chủng trong môi trường được bảo vệ trước khi thả chúng về môi trường sống tự nhiên phù hợp."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_19_1', 'en-b2-19', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_19_1_1', 'ten_b2_19_1', 'squirrel', 'A squirrel buried a nut beside our garden gate.', 'A squirrel buried a nut beside our garden gate.', '/ˈskwɜːrəl/', 'Một con sóc đã chôn một hạt dẻ bên cạnh cổng vườn nhà tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
