INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_19_1_8', 'ten_b2_19_1', 'canyon', 'We watched a river winding through the rocky canyon.', 'We watched a river winding through the rocky canyon.', '/ˈkænjən/', 'Chúng tôi ngắm nhìn dòng sông uốn lượn qua hẻm núi đá.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_19_1_1', 'en-b2-19', 'ten_b2_19_1', 'listening', 'listening', 'A squirrel buried a nut beside our garden gate.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một con sóc đã chôn một hạt dẻ bên cạnh cổng vườn nhà tôi.","Con đà điểu chạy vụt qua bãi cỏ đầy bụi.","Một viên đá cuội màu xám nhẵn nhụi nằm cạnh đôi giày ướt của tôi.","Tôi đã thêm một củ cải trắng cắt nhỏ vào món súp rau củ."]'::jsonb, 0, 'A squirrel buried a nut beside our garden gate. → Một con sóc đã chôn một hạt dẻ bên cạnh cổng vườn nhà tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_19_1_2', 'en-b2-19', 'ten_b2_19_1', 'listening', 'listening', 'We watched a fallen leaf drift across the pond.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những viên sỏi kêu lạo xạo dưới giày chúng tôi khi cả nhóm tiến lại gần ngôi nhà nhỏ.","Con chim sẻ ngậm một hạt giống nhỏ xíu trong chiếc mỏ của nó.","Chúng tôi ngắm nhìn một chiếc lá rụng trôi qua mặt ao.","Một viên đá cuội màu xám nhẵn nhụi nằm cạnh đôi giày ướt của tôi."]'::jsonb, 2, 'We watched a fallen leaf drift across the pond. → Chúng tôi ngắm nhìn một chiếc lá rụng trôi qua mặt ao.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_19_1_3', 'en-b2-19', 'ten_b2_19_1', 'listening', 'listening', 'We cooked the vegetables over glowing charcoal in the garden.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Con gà trống đã đánh thức chúng tôi dậy ngay trước khi mặt trời mọc vào sáng nay.","Một viên ngọc trai đơn lẻ được treo trên chiếc dây chuyền bạc của cô ấy.","Theo bản năng, chú mèo con mới sinh đã tìm kiếm mẹ của mình.","Chúng tôi nướng rau củ trên bếp than hồng trong vườn."]'::jsonb, 3, 'We cooked the vegetables over glowing charcoal in the garden. → Chúng tôi nướng rau củ trên bếp than hồng trong vườn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_19_2', 'en-b2-19', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_19_2_1', 'ten_b2_19_2', 'squirrel', 'Urban parks provide squirrels with food and shelter, although feeding them can alter their natural behaviour.', 'Urban parks provide squirrels with food and shelter, although feeding them can alter their natural behaviour.', '/ˈskwɜːrəl/', 'Các công viên đô thị cung cấp thức ăn và nơi trú ẩn cho sóc, mặc dù việc cho chúng ăn có thể làm thay đổi tập tính tự nhiên của chúng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_19_2_2', 'ten_b2_19_2', 'drift', 'Without affordable housing and stable employment, young residents may gradually drift away from rural communities.', 'Without affordable housing and stable employment, young residents may gradually drift away from rural communities.', '/drɪft/', 'Nếu không có nhà ở giá rẻ và việc làm ổn định, cư dân trẻ tuổi có thể dần rời bỏ các cộng đồng nông thôn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_19_2_3', 'ten_b2_19_2', 'charcoal', 'Heavy demand for charcoal can contribute to deforestation where trees are harvested faster than they can regrow.', 'Heavy demand for charcoal can contribute to deforestation where trees are harvested faster than they can regrow.', '/ˈtʃɑːrkoʊl/', 'Nhu cầu tiêu thụ than củi lớn có thể góp phần gây ra nạn phá rừng ở những nơi cây bị chặt nhanh hơn tốc độ tái sinh.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_19_2_4', 'ten_b2_19_2', 'breed', 'Conservation programmes breed endangered animals in protected environments before releasing them into suitable natural habitats.', 'Conservation programmes breed endangered animals in protected environments before releasing them into suitable natural habitats.', '/briːd/', 'Các chương trình bảo tồn nhân giống động vật có nguy cơ tuyệt chủng trong môi trường được bảo vệ trước khi thả chúng về môi trường sống tự nhiên phù hợp.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_19_2_5', 'ten_b2_19_2', 'turnip', 'Growing root vegetables such as turnips can help communities diversify local food supplies during cooler months.', 'Growing root vegetables such as turnips can help communities diversify local food supplies during cooler months.', '/ˈtɝːnɪp/', 'Việc trồng các loại rau củ như củ cải trắng có thể giúp cộng đồng đa dạng hóa nguồn cung cấp thực phẩm địa phương trong những tháng lạnh hơn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_19_2_6', 'ten_b2_19_2', 'flock', 'Visitors flock to coastal towns during summer, bringing income but also placing pressure on local infrastructure.', 'Visitors flock to coastal towns during summer, bringing income but also placing pressure on local infrastructure.', '/flɑːk/', 'Du khách đổ xô đến các thị trấn ven biển vào mùa hè, mang lại nguồn thu nhập nhưng đồng thời cũng gây áp lực lên cơ sở hạ tầng địa phương.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_19_2_1', 'en-b2-19', 'ten_b2_19_2', 'listening', 'listening', 'Urban parks provide squirrels with food and shelter, although feeding them can alter their natural behaviour.', NULL, 'Trong câu vừa nghe, từ “squirrel” mang nghĩa nào sau đây?', '["thí sinh; người tham gia thi đấu","sự thích nghi; tính thích nghi","vỡ nợ; phá sản","con sóc"]'::jsonb, 3, '“squirrel” (/ˈskwɜːrəl/): con sóc. Câu đầy đủ: Urban parks provide squirrels with food and shelter, although feeding them can alter their natural behaviour.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_19_2_2', 'en-b2-19', 'ten_b2_19_2', 'listening', 'listening', 'Without affordable housing and stable employment, young residents may gradually drift away from rural communities.', NULL, 'Trong câu vừa nghe, từ “drift” mang nghĩa nào sau đây?', '["sự đổi mới; sự cải tiến","sự đóng góp; phần đóng góp","trôi dạt; bay lơ lửng","sự cất giữ; sự bảo quản"]'::jsonb, 2, '“drift” (/drɪft/): trôi dạt; bay lơ lửng. Câu đầy đủ: Without affordable housing and stable employment, young residents may gradually drift away from rural communities.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
