INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_19_2', 'en-b2-19', NULL, 'comprehensive_test', 'listening', 'We watched a fallen leaf drift across the pond.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Con chim sẻ ngậm một hạt giống nhỏ xíu trong chiếc mỏ của nó.","Một con bạch tuộc đã lách qua khe hẹp giữa các tảng đá.","Một viên ngọc trai đơn lẻ được treo trên chiếc dây chuyền bạc của cô ấy.","Chúng tôi ngắm nhìn một chiếc lá rụng trôi qua mặt ao."]'::jsonb, 3, 'We watched a fallen leaf drift across the pond. → Chúng tôi ngắm nhìn một chiếc lá rụng trôi qua mặt ao.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_19_3', 'en-b2-19', NULL, 'comprehensive_test', 'listening', 'charcoal', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bền; bền bỉ","than củi; than gỗ","trước; tiên quyết; có trước","vải bạt; loại vải dày, chắc dùng cho lều, túi và buồm"]'::jsonb, 1, 'charcoal (/ˈtʃɑːrkoʊl/) → than củi; than gỗ; than vẽ; bút than', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_19_4', 'en-b2-19', NULL, 'comprehensive_test', 'listening', 'These birds usually breed here during the warmer months.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một con bạch tuộc đã lách qua khe hẹp giữa các tảng đá.","Chúng tôi đứng từ một khoảng cách an toàn để theo dõi vụ phun trào.","Những loài chim này thường sinh sản ở đây trong những tháng ấm áp hơn.","Cô ấy trồng tre dọc theo hàng rào để tăng tính riêng tư."]'::jsonb, 2, 'These birds usually breed here during the warmer months. → Những loài chim này thường sinh sản ở đây trong những tháng ấm áp hơn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_19_5', 'en-b2-19', NULL, 'comprehensive_test', 'listening', 'turnip', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đồ ăn nhẹ và đồ uống; tiệc trà nhẹ","chiến thuật; thủ thuật; mưu lược (một hành động cụ thể nhằm đạt được mục tiêu)","củ cải trắng (phần đầu có màu tím)","độc lập; không cần sự giúp đỡ"]'::jsonb, 2, 'turnip (/ˈtɝːnɪp/) → củ cải trắng (phần đầu có màu tím)', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_19_6', 'en-b2-19', NULL, 'comprehensive_test', 'listening', 'A flock of geese landed beside the quiet lake.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Người chăn cừu lùa đàn cừu về nhà trước khi mặt trời lặn.","Một đàn ngỗng hạ xuống bên hồ nước yên tĩnh.","Một viên đá cuội màu xám nhẵn nhụi nằm cạnh đôi giày ướt của tôi.","Những viên sỏi kêu lạo xạo dưới giày chúng tôi khi cả nhóm tiến lại gần ngôi nhà nhỏ."]'::jsonb, 1, 'A flock of geese landed beside the quiet lake. → Một đàn ngỗng hạ xuống bên hồ nước yên tĩnh.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_19_7', 'en-b2-19', NULL, 'comprehensive_test', 'listening', 'octopus', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự bán lẻ; việc bán hàng trực tiếp cho người tiêu dùng","giẻ lau; vải vụn","con bạch tuộc","mỏng manh, dễ vỡ, dễ hư hỏng"]'::jsonb, 2, 'octopus (/ˈɑːktəpəs/) → con bạch tuộc', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_19_8', 'en-b2-19', NULL, 'comprehensive_test', 'listening', 'We watched a river winding through the rocky canyon.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi quan sát trận lốc xoáy từ một hầm trú ẩn ngầm an toàn.","Chúng tôi nướng rau củ trên bếp than hồng trong vườn.","Một viên ngọc trai đơn lẻ được treo trên chiếc dây chuyền bạc của cô ấy.","Chúng tôi ngắm nhìn dòng sông uốn lượn qua hẻm núi đá."]'::jsonb, 3, 'We watched a river winding through the rocky canyon. → Chúng tôi ngắm nhìn dòng sông uốn lượn qua hẻm núi đá.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
