INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_19_18', 'en-b2-19', NULL, 'comprehensive_test', 'reading', NULL, 'Urban parks provide squirrels with food and shelter, although feeding them can alter their natural behaviour.', 'Dựa vào câu trên, từ “squirrel” có nghĩa phù hợp nhất là gì?', '["con sóc","trong nước; nội địa","cây tre; tre; vật liệu bằng tre","tích hợp; kết hợp"]'::jsonb, 0, 'squirrel: con sóc; cất giấu; tích trữ (thường dùng với "away"). Dịch cả câu: Các công viên đô thị cung cấp thức ăn và nơi trú ẩn cho sóc, mặc dù việc cho chúng ăn có thể làm thay đổi tập tính tự nhiên của chúng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_19_19', 'en-b2-19', NULL, 'comprehensive_test', 'reading', NULL, 'Without affordable housing and stable employment, young residents may gradually drift away from rural communities.', 'Dựa vào câu trên, từ “drift” có nghĩa phù hợp nhất là gì?', '["đáng chú ý; phi thường; xuất sắc","trôi dạt; bay lơ lửng","trí thông minh; năng lực trí tuệ","vương quốc"]'::jsonb, 1, 'drift: trôi dạt; bay lơ lửng; trôi đi; dần chệch hướng; ý chính; đại ý. Dịch cả câu: Nếu không có nhà ở giá rẻ và việc làm ổn định, cư dân trẻ tuổi có thể dần rời bỏ các cộng đồng nông thôn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_19_20', 'en-b2-19', NULL, 'comprehensive_test', 'reading', NULL, 'Heavy demand for charcoal can contribute to deforestation where trees are harvested faster than they can regrow.', 'Dựa vào câu trên, từ “charcoal” có nghĩa phù hợp nhất là gì?', '["than củi; than gỗ","tổn hại; sự tổn thương","nhạy cảm; dễ bị ảnh hưởng bởi cảm xúc, chất hoặc sự thay đổi","căng thẳng; căng"]'::jsonb, 0, 'charcoal: than củi; than gỗ; than vẽ; bút than. Dịch cả câu: Nhu cầu tiêu thụ than củi lớn có thể góp phần gây ra nạn phá rừng ở những nơi cây bị chặt nhanh hơn tốc độ tái sinh.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_19_21', 'en-b2-19', NULL, 'comprehensive_test', 'reading', NULL, 'Conservation programmes breed endangered animals in protected environments before releasing them into suitable natural habitats.', 'Dựa vào câu trên, từ “breed” có nghĩa phù hợp nhất là gì?', '["ngược chiều kim đồng hồ","sự lựa chọn; sự tuyển chọn","không thỏa đáng; không đạt yêu cầu","sinh sản; gây giống"]'::jsonb, 3, 'breed: sinh sản; gây giống; giống (vật nuôi); gây ra; sinh ra. Dịch cả câu: Các chương trình bảo tồn nhân giống động vật có nguy cơ tuyệt chủng trong môi trường được bảo vệ trước khi thả chúng về môi trường sống tự nhiên phù hợp.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_19_22', 'en-b2-19', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “động vật có vú”', '["satisfactory","specialty","regardless","mammal"]'::jsonb, 3, 'động vật có vú → mammal (/ˈmæməl/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_19_23', 'en-b2-19', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hòn cuội; viên đá nhỏ nhẵn”', '["batch","pebble","specialist","dismiss"]'::jsonb, 1, 'hòn cuội; viên đá nhỏ nhẵn → pebble (/ˈpebəl/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_19_24', 'en-b2-19', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “chín; làm cho chín”', '["ripen","bunk","kitesurfing","cruise"]'::jsonb, 0, 'chín; làm cho chín → ripen (/ˈraɪpən/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-20', 'en', 'Bài 20: Thiên nhiên & Thời tiết (3) - CEFR B2', 'CEFR B2', 'B2 · Thiên nhiên', '27 từ vựng Tiếng Anh CEFR B2 chủ đề thiên nhiên & thời tiết kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4020, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exotic', 'en-b2-20', 'exotic', '/ɪɡˈzɑːtɪk/', 'B2', 'mang phong cách lạ; ngoại lai; đẹp kỳ lạ; không phải bản địa', 'adj.', 'exotically (adv.), exoticism (n.)', 'Trái nghĩa: native', 'Trong ngữ cảnh sinh thái, từ này chỉ sinh vật không phải bản địa, chưa chắc đã mang tính xâm lấn.', 'The market sells exotic fruits I have never tasted.', NULL, 'Khu chợ bán những loại trái cây ngoại lai mà tôi chưa từng nếm qua.', '{"wordId":"exotic","ukIpa":"/ɪɡˈzɒtɪk/","usIpa":"/ɪɡˈzɑːtɪk/","cefr":"B2","topic":"nature","senses":[{"pos":"adj.","en":"Unusual and interesting, especially because of a connection with distant countries.","vi":"mang phong cách lạ; ngoại lai; đẹp kỳ lạ"},{"pos":"adj.","en":"Originating outside the region where something is now found.","vi":"ngoại lai; không phải bản địa"}],"examples":[{"en":"The market sells exotic fruits I have never tasted.","vi":"Khu chợ bán những loại trái cây ngoại lai mà tôi chưa từng nếm qua.","audioKind":"ex"},{"en":"Introducing exotic plants into local gardens can threaten native species if their spread is not controlled.","vi":"Việc đưa các loài thực vật ngoại lai vào vườn nhà có thể đe dọa các loài bản địa nếu sự lây lan của chúng không được kiểm soát.","audioKind":"ex2"}],"collocations":[{"en":"exotic fruit","vi":"trái cây ngoại lai"},{"en":"exotic destination","vi":"điểm đến kỳ thú"},{"en":"exotic species","vi":"loài ngoại lai"}],"wordFamily":["exotically (adv.)","exoticism (n.)"],"synonyms":[],"antonyms":["native"],"tipVi":"Trong ngữ cảnh sinh thái, từ này chỉ sinh vật không phải bản địa, chưa chắc đã mang tính xâm lấn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sting', 'en-b2-20', 'sting', '/stɪŋ/', 'B2', 'chích; đốt; vết đốt; cơn đau nhói; làm tổn thương (tình cảm); làm đau lòng', 'v.', 'stinging (adj.), stinger (n.)', NULL, 'Dạng quá khứ đơn và quá khứ phân từ đều là "stung"; dùng "sting" cho hành động đốt/chích (của ong, sứa...), còn cắn dùng "bite".', 'A bee stung my ankle while I watered the flowers.', NULL, 'Một con ong đã đốt vào mắt cá chân tôi khi tôi đang tưới hoa.', '{"wordId":"sting","ukIpa":"/stɪŋ/","usIpa":"/stɪŋ/","cefr":"B2","topic":"nature","senses":[{"pos":"v.","en":"Cause sharp pain with a pointed body part or irritating substance","vi":"chích; đốt"},{"pos":"n.","en":"A painful insect injury or a sudden sharp pain","vi":"vết đốt; cơn đau nhói"},{"pos":"v.","en":"Make someone feel suddenly upset or hurt","vi":"làm tổn thương (tình cảm); làm đau lòng"}],"examples":[{"en":"A bee stung my ankle while I watered the flowers.","vi":"Một con ong đã đốt vào mắt cá chân tôi khi tôi đang tưới hoa.","audioKind":"ex"},{"en":"Harsh criticism can sting young learners and discourage them from participating in classroom discussions.","vi":"Những lời chỉ trích gay gắt có thể làm tổn thương những người học nhỏ tuổi và khiến họ ngại tham gia thảo luận trên lớp.","audioKind":"ex2"}],"collocations":[{"en":"a bee sting","vi":"vết ong đốt"},{"en":"a wasp sting","vi":"vết ong bắp cày đốt"},{"en":"stinging criticism","vi":"lời chỉ trích gay gắt"}],"wordFamily":["stinging (adj.)","stinger (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ đơn và quá khứ phân từ đều là \"stung\"; dùng \"sting\" cho hành động đốt/chích (của ong, sứa...), còn cắn dùng \"bite\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_peak', 'en-b2-20', 'peak', '/piːk/', 'B2', 'đỉnh núi; đỉnh cao; đạt đỉnh; lên đến mức cao nhất; cao điểm; nhiều nhất', 'n.', NULL, 'Đồng nghĩa: summit, pinnacle', 'Cấu trúc peak at dùng để chỉ mức đỉnh điểm; peak season chỉ mùa du lịch hoặc làm ăn cao điểm.', 'Snow still covered the mountain peak in June.', NULL, 'Tuyết vẫn phủ trắng đỉnh núi vào tháng Sáu.', '{"wordId":"peak","ukIpa":"/piːk/","usIpa":"/piːk/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A mountain''s top or the highest level of something.","vi":"đỉnh núi; đỉnh cao"},{"pos":"v.","en":"To reach the highest level or amount.","vi":"đạt đỉnh; lên đến mức cao nhất"},{"pos":"adj.","en":"At the highest level of activity, demand, or achievement.","vi":"cao điểm; nhiều nhất"}],"examples":[{"en":"Snow still covered the mountain peak in June.","vi":"Tuyết vẫn phủ trắng đỉnh núi vào tháng Sáu.","audioKind":"ex"},{"en":"Electricity demand usually peaks in the early evening, when households use several appliances at once.","vi":"Nhu cầu điện năng thường đạt mức cao nhất vào chập tối, khi các hộ gia đình sử dụng đồng thời nhiều thiết bị điện.","audioKind":"ex2"}],"collocations":[{"en":"reach a peak","vi":"đạt đến đỉnh điểm"},{"en":"peak demand","vi":"nhu cầu cao điểm"},{"en":"mountain peak","vi":"đỉnh núi"},{"en":"peak season","vi":"mùa cao điểm"}],"wordFamily":[],"synonyms":["summit","pinnacle"],"antonyms":[],"tipVi":"Cấu trúc peak at dùng để chỉ mức đỉnh điểm; peak season chỉ mùa du lịch hoặc làm ăn cao điểm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_undersea', 'en-b2-20', 'undersea', '/ˌʌndɚˈsiː/', 'B2', 'ở dưới biển; dưới mặt nước biển', 'adj.', NULL, 'Đồng nghĩa: submarine', 'Thường đặt trước danh từ; nhấn mạnh ở dưới mặt nước biển chứ không phải mọi môi trường dưới nước.', 'The documentary showed colourful fish around an undersea cave.', NULL, 'Bộ phim tài liệu cho thấy những chú cá đầy màu sắc quanh một hang động dưới biển.', '{"wordId":"undersea","ukIpa":"/ˌʌndəˈsiː/","usIpa":"/ˌʌndɚˈsiː/","cefr":"B2","topic":"nature","senses":[{"pos":"adj.","en":"Located or happening below the surface of the sea","vi":"ở dưới biển; dưới mặt nước biển"}],"examples":[{"en":"The documentary showed colourful fish around an undersea cave.","vi":"Bộ phim tài liệu cho thấy những chú cá đầy màu sắc quanh một hang động dưới biển.","audioKind":"ex"},{"en":"Undersea cables connect continents and provide essential infrastructure for global communication and international trade.","vi":"Cáp ngầm kết nối các châu lục và cung cấp cơ sở hạ tầng thiết yếu cho giao tiếp toàn cầu và thương mại quốc tế.","audioKind":"ex2"}],"collocations":[{"en":"undersea cable","vi":"cáp ngầm"},{"en":"undersea exploration","vi":"khảo sát đáy biển"},{"en":"undersea tunnel","vi":"hầm vượt biển"}],"wordFamily":[],"synonyms":["submarine"],"antonyms":[],"tipVi":"Thường đặt trước danh từ; nhấn mạnh ở dưới mặt nước biển chứ không phải mọi môi trường dưới nước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_blizzard', 'en-b2-20', 'blizzard', '/ˈblɪzərd/', 'B2', 'bão tuyết', 'n.', NULL, 'Đồng nghĩa: snowstorm', 'Nhấn mạnh gió mạnh và thời tiết khắc nghiệt hơn từ snowstorm thông thường.', 'We stayed indoors while the blizzard shook our windows.', NULL, 'Chúng tôi ở trong nhà khi trận bão tuyết làm rung chuyển các khung cửa sổ.', '{"wordId":"blizzard","ukIpa":"/ˈblɪzəd/","usIpa":"/ˈblɪzərd/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A severe snowstorm with strong winds.","vi":"bão tuyết"}],"examples":[{"en":"We stayed indoors while the blizzard shook our windows.","vi":"Chúng tôi ở trong nhà khi trận bão tuyết làm rung chuyển các khung cửa sổ.","audioKind":"ex"},{"en":"A severe blizzard can disrupt public transport and leave rural communities without electricity for several days.","vi":"Một trận bão tuyết dữ dội có thể làm gián đoạn giao thông công cộng và khiến các cộng đồng nông thôn mất điện trong vài ngày.","audioKind":"ex2"}],"collocations":[{"en":"a severe blizzard","vi":"một trận bão tuyết dữ dội"},{"en":"blizzard conditions","vi":"điều kiện bão tuyết"}],"wordFamily":[],"synonyms":["snowstorm"],"antonyms":[],"tipVi":"Nhấn mạnh gió mạnh và thời tiết khắc nghiệt hơn từ snowstorm thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vast', 'en-b2-20', 'vast', '/væst/', 'B2', 'rộng lớn; bao la; vô cùng', 'adj.', 'vastly (adv.), vastness (n.)', 'Đồng nghĩa: enormous, immense, huge · Trái nghĩa: tiny', 'Cụm the vast majority of có nghĩa là đại đa số trong...', 'A vast desert stretched beyond the small village.', NULL, 'Một sa mạc rộng lớn trải dài vượt qua ngôi làng nhỏ.', '{"wordId":"vast","ukIpa":"/vɑːst/","usIpa":"/væst/","cefr":"B2","topic":"nature","senses":[{"pos":"adj.","en":"Extremely large in area, size, amount, or degree.","vi":"rộng lớn; bao la; vô cùng"}],"examples":[{"en":"A vast desert stretched beyond the small village.","vi":"Một sa mạc rộng lớn trải dài vượt qua ngôi làng nhỏ.","audioKind":"ex"},{"en":"Digital libraries give students access to vast amounts of information, although evaluating its reliability remains essential.","vi":"Thư viện số giúp sinh viên tiếp cận lượng thông tin khổng lồ, mặc dù việc đánh giá độ tin cậy của thông tin vẫn là điều thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"the vast majority","vi":"đại đa số"},{"en":"vast amounts of","vi":"lượng lớn"},{"en":"a vast area","vi":"vùng đất rộng lớn"},{"en":"vast resources","vi":"nguồn tài nguyên phong phú"}],"wordFamily":["vastly (adv.)","vastness (n.)"],"synonyms":["enormous","immense","huge"],"antonyms":["tiny"],"tipVi":"Cụm the vast majority of có nghĩa là đại đa số trong...","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_breeze', 'en-b2-20', 'breeze', '/briːz/', 'B2', 'gió nhẹ; cơn gió thoảng; việc rất dễ dàng; đi lướt qua nhanh chóng; vượt qua dễ dàng', 'n.', 'breezy (adj.), breezily (adv.)', NULL, 'be a breeze là cụm khẩu ngữ chỉ việc ''dễ như trở bàn tay''.', 'A cool breeze lifted the curtains beside my bed.', NULL, 'Một cơn gió mát thổi bay bức rèm bên giường tôi.', '{"wordId":"breeze","ukIpa":"/briːz/","usIpa":"/briːz/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A light, gentle wind","vi":"gió nhẹ; cơn gió thoảng"},{"pos":"n.","en":"Something that is very easy to do","vi":"việc rất dễ dàng"},{"pos":"v.","en":"Move or complete something easily and confidently","vi":"đi lướt qua nhanh chóng; vượt qua dễ dàng"}],"examples":[{"en":"A cool breeze lifted the curtains beside my bed.","vi":"Một cơn gió mát thổi bay bức rèm bên giường tôi.","audioKind":"ex"},{"en":"Coastal parks offer residents pleasant places to exercise while enjoying the fresh sea breeze.","vi":"Các công viên ven biển mang đến cho cư dân không gian tập thể dục dễ chịu trong lúc tận hưởng làn gió biển trong lành.","audioKind":"ex2"}],"collocations":[{"en":"a gentle breeze","vi":"một làn gió nhẹ"},{"en":"a sea breeze","vi":"gió biển"},{"en":"be a breeze","vi":"việc dễ như trở bàn tay"},{"en":"breeze through an exam","vi":"vượt qua kỳ thi một cách dễ dàng"}],"wordFamily":["breezy (adj.)","breezily (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"be a breeze là cụm khẩu ngữ chỉ việc ''dễ như trở bàn tay''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dusk', 'en-b2-20', 'dusk', '/dʌsk/', 'B2', 'chạng vạng; hoàng hôn; chiều tà', 'n.', NULL, 'Đồng nghĩa: twilight, nightfall · Trái nghĩa: dawn', 'Dùng cụm at dusk để chỉ thời điểm hoàng hôn; dawn là từ chỉ bình minh.', 'We reached the campsite at dusk and lit a lantern.', NULL, 'Chúng tôi đến khu cắm trại vào lúc chạng vạng và thắp lên một ngọn đèn lồng.', '{"wordId":"dusk","ukIpa":"/dʌsk/","usIpa":"/dʌsk/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"The time when daylight fades before night.","vi":"chạng vạng; hoàng hôn; chiều tà"}],"examples":[{"en":"We reached the campsite at dusk and lit a lantern.","vi":"Chúng tôi đến khu cắm trại vào lúc chạng vạng và thắp lên một ngọn đèn lồng.","audioKind":"ex"},{"en":"Improved street lighting can make public spaces safer for pedestrians who travel home after dusk.","vi":"Hệ thống chiếu sáng đường phố được cải thiện có thể giúp không gian công cộng trở nên an toàn hơn cho những người đi bộ về nhà sau khi trời tối.","audioKind":"ex2"}],"collocations":[{"en":"at dusk","vi":"vào lúc chạng vạng"},{"en":"from dawn to dusk","vi":"từ sáng sớm đến tối mịt"},{"en":"as dusk falls","vi":"khi hoàng hôn buông xuống"}],"wordFamily":[],"synonyms":["twilight","nightfall"],"antonyms":["dawn"],"tipVi":"Dùng cụm at dusk để chỉ thời điểm hoàng hôn; dawn là từ chỉ bình minh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stump', 'en-b2-20', 'stump', '/stʌmp/', 'B2', 'gốc cây; gốc cội; làm khó; làm bối rối', 'n.', NULL, 'Đồng nghĩa: baffle, puzzle', 'Cụm be stumped by có nghĩa là bị làm khó hoặc bị đánh đố, chứ không phải bị vấp ngã.', 'We sat on a tree stump to eat lunch.', NULL, 'Chúng tôi ngồi trên một gốc cây để ăn trưa.', '{"wordId":"stump","ukIpa":"/stʌmp/","usIpa":"/stʌmp/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"the base remaining after a tree or object is cut","vi":"gốc cây; gốc cội"},{"pos":"v.","en":"to leave someone unable to answer or solve something","vi":"làm khó; làm bối rối"}],"examples":[{"en":"We sat on a tree stump to eat lunch.","vi":"Chúng tôi ngồi trên một gốc cây để ăn trưa.","audioKind":"ex"},{"en":"Removing tree stumps can disturb forest soils and destroy habitats used by insects and other small organisms.","vi":"Việc nhổ gốc cây có thể làm xáo trộn đất rừng và phá hủy môi trường sống của côn trùng cùng các sinh vật nhỏ khác.","audioKind":"ex2"}],"collocations":[{"en":"a tree stump","vi":"một gốc cây"},{"en":"remove a stump","vi":"nhổ gốc cây"},{"en":"be stumped by a question","vi":"bị bí trước một câu hỏi"}],"wordFamily":[],"synonyms":["baffle","puzzle"],"antonyms":[],"tipVi":"Cụm be stumped by có nghĩa là bị làm khó hoặc bị đánh đố, chứ không phải bị vấp ngã.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_frost', 'en-b2-20', 'frost', '/frɔːst/', 'B2', 'sương giá; băng giá; phủ sương; đóng băng; trét kem đường (lên bánh)', 'n.', 'frosty (adj.), frosted (adj.), frosting (n.)', NULL, 'frost là sương giá chứ không phải tuyết; động từ chỉ việc phủ kem đường lên bánh ngọt thường phổ biến trong tiếng Mỹ.', 'A thin frost covered the grass outside our kitchen.', NULL, 'Một lớp sương giá mỏng phủ kín thảm cỏ ngoài bếp nhà chúng tôi.', '{"wordId":"frost","ukIpa":"/frɒst/","usIpa":"/frɔːst/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"Thin ice crystals on surfaces, or weather that forms them.","vi":"sương giá; băng giá"},{"pos":"v.","en":"To cover or become covered with a thin layer of ice.","vi":"phủ sương; đóng băng"},{"pos":"v.","en":"To cover a cake with a sweet, creamy topping.","vi":"trét kem đường (lên bánh)"}],"examples":[{"en":"A thin frost covered the grass outside our kitchen.","vi":"Một lớp sương giá mỏng phủ kín thảm cỏ ngoài bếp nhà chúng tôi.","audioKind":"ex"},{"en":"Unexpected spring frost can damage young crops, reducing yields and increasing financial pressure on farmers.","vi":"Sương giá bất chợt vào mùa xuân có thể tàn phá cây trồng non, làm giảm năng suất và gia tăng gánh nặng tài chính cho người nông dân.","audioKind":"ex2"}],"collocations":[{"en":"a sharp frost","vi":"sương giá nặng"},{"en":"ground frost","vi":"sương giá mặt đất"},{"en":"frost damage","vi":"thiệt hại do sương giá"},{"en":"frost a cake","vi":"phủ kem đường lên bánh"}],"wordFamily":["frosty (adj.)","frosted (adj.)","frosting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"frost là sương giá chứ không phải tuyết; động từ chỉ việc phủ kem đường lên bánh ngọt thường phổ biến trong tiếng Mỹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_overcast', 'en-b2-20', 'overcast', '/ˈoʊvərkæst/', 'B2', 'âm u, mây mù, xám xịt', 'adj.', NULL, 'Đồng nghĩa: cloudy · Trái nghĩa: clear, sunny', 'Chỉ bầu trời bị che phủ bởi mây, không nhất thiết là sẽ có mưa.', 'The sky was overcast when we left for school.', NULL, 'Bầu trời âm u mây mù khi chúng tôi xuất phát đi học.', '{"wordId":"overcast","ukIpa":"/ˌəʊvəˈkɑːst/","usIpa":"/ˈoʊvərkæst/","cefr":"B2","topic":"nature","senses":[{"pos":"adj.","en":"Covered with clouds, making the sky dull and grey.","vi":"âm u, mây mù, xám xịt"}],"examples":[{"en":"The sky was overcast when we left for school.","vi":"Bầu trời âm u mây mù khi chúng tôi xuất phát đi học.","audioKind":"ex"},{"en":"Although overcast conditions reduce solar electricity generation, modern panels can still produce useful amounts of power.","vi":"Mặc dù thời tiết âm u làm giảm hiệu suất phát điện mặt trời, các tấm pin hiện đại vẫn có thể tạo ra lượng điện năng hữu ích.","audioKind":"ex2"}],"collocations":[{"en":"an overcast sky","vi":"bầu trời âm u mây mù"},{"en":"an overcast day","vi":"một ngày trời âm u"},{"en":"overcast conditions","vi":"điều kiện thời tiết âm u"}],"wordFamily":[],"synonyms":["cloudy"],"antonyms":["clear","sunny"],"tipVi":"Chỉ bầu trời bị che phủ bởi mây, không nhất thiết là sẽ có mưa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_twig', 'en-b2-20', 'twig', '/twɪɡ/', 'B2', 'cành con, nhánh cây nhỏ; chợt hiểu ra, nhận ra điều gì đó', 'n.', NULL, NULL, 'Nghĩa động từ là cách dùng không trang trọng trong tiếng Anh-Anh; dạng quá khứ là twigged.', 'A sparrow carried a twig back to its nest.', NULL, 'Một con chim sẻ cậm một cành cây nhỏ bay về tổ của nó.', '{"wordId":"twig","ukIpa":"/twɪɡ/","usIpa":"/twɪɡ/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"a small, thin branch of a tree or bush","vi":"cành con, nhánh cây nhỏ"},{"pos":"v.","en":"to suddenly understand or notice something","vi":"chợt hiểu ra, nhận ra điều gì đó"}],"examples":[{"en":"A sparrow carried a twig back to its nest.","vi":"Một con chim sẻ cậm một cành cây nhỏ bay về tổ của nó.","audioKind":"ex"},{"en":"Leaving fallen twigs on forest floors provides shelter for insects and supports the natural recycling of nutrients.","vi":"Việc để lại những cành cây khô rơi rụng trên nền rừng tạo ra nơi trú ẩn cho côn trùng và hỗ trợ quá trình tái chế chất dinh dưỡng tự nhiên.","audioKind":"ex2"}],"collocations":[{"en":"dry twigs","vi":"cành cây khô"},{"en":"snap a twig","vi":"bẻ gãy cành cây nhỏ"},{"en":"twig that","vi":"chợt nhận ra rằng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa động từ là cách dùng không trang trọng trong tiếng Anh-Anh; dạng quá khứ là twigged.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_log', 'en-b2-20', 'log', '/lɔːɡ/', 'B2', 'khúc gỗ, khúc thân cây đã đốn; sổ nhật ký, bản ghi chép chi tiết các sự kiện hoạt động; ghi chép thông tin về các sự kiện, hoạt động hoặc số đo', 'n.', 'logging (n.), logger (n.)', NULL, 'Dạng quá khứ của động từ là logged; log in nghĩa là đăng nhập hệ thống.', 'We sat on a fallen log beside the lake.', NULL, 'Chúng tôi ngồi trên một khúc gỗ bị đổ bên bờ hồ.', '{"wordId":"log","ukIpa":"/lɒɡ/","usIpa":"/lɔːɡ/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"a thick piece of wood cut from a tree","vi":"khúc gỗ, khúc thân cây đã đốn"},{"pos":"n.","en":"a detailed record of events or activities","vi":"sổ nhật ký, bản ghi chép chi tiết các sự kiện hoạt động"},{"pos":"v.","en":"to record information about events, activities, or measurements","vi":"ghi chép thông tin về các sự kiện, hoạt động hoặc số đo"}],"examples":[{"en":"We sat on a fallen log beside the lake.","vi":"Chúng tôi ngồi trên một khúc gỗ bị đổ bên bờ hồ.","audioKind":"ex"},{"en":"Researchers log changes in water temperature to assess how climate change affects freshwater ecosystems over time.","vi":"Các nhà nghiên cứu ghi chép lại những thay đổi về nhiệt độ nước để đánh giá biến đổi khí hậu ảnh hưởng thế nào đến các hệ sinh thái nước ngọt theo thời gian.","audioKind":"ex2"}],"collocations":[{"en":"a fallen log","vi":"khúc gỗ bị đổ"},{"en":"keep a log","vi":"giữ nhật ký ghi chép"},{"en":"log data","vi":"ghi dữ liệu"},{"en":"log in","vi":"đăng nhập"}],"wordFamily":["logging (n.)","logger (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ của động từ là logged; log in nghĩa là đăng nhập hệ thống.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hive', 'en-b2-20', 'hive', '/haɪv/', 'B2', 'tổ ong; thùng nuôi ong; nơi tấp nập; chốn bận rộn', 'n.', NULL, 'Đồng nghĩa: beehive', 'Cụm ''a hive of activity'' dùng để miêu tả một nơi chốn náo nhiệt, mọi người đang bận rộn hoạt động.', 'The beekeeper lifted the lid and inspected the hive.', NULL, 'Người nuôi ong đã nhấc nắp lên và kiểm tra cái thùng nuôi ong.', '{"wordId":"hive","ukIpa":"/haɪv/","usIpa":"/haɪv/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A structure where a colony of bees lives.","vi":"tổ ong; thùng nuôi ong"},{"pos":"n.","en":"A place full of busy people and activity.","vi":"nơi tấp nập; chốn bận rộn"}],"examples":[{"en":"The beekeeper lifted the lid and inspected the hive.","vi":"Người nuôi ong đã nhấc nắp lên và kiểm tra cái thùng nuôi ong.","audioKind":"ex"},{"en":"Each community garden became a hive of activity as residents worked together to grow fresh vegetables.","vi":"Mỗi khu vườn cộng đồng đều trở thành một nơi tấp nập khi cư dân cùng nhau làm việc để trồng rau sạch.","audioKind":"ex2"}],"collocations":[{"en":"a bee hive","vi":"tổ ong"},{"en":"a hive of activity","vi":"nơi hoạt động tấp nập"},{"en":"inspect a hive","vi":"kiểm tra tổ ong"}],"wordFamily":[],"synonyms":["beehive"],"antonyms":[],"tipVi":"Cụm ''a hive of activity'' dùng để miêu tả một nơi chốn náo nhiệt, mọi người đang bận rộn hoạt động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inland', 'en-b2-20', 'inland', '/ˈɪnlənd/', 'B2', 'thuộc nội địa; ở sâu trong đất liền; hướng vào nội địa; ở trong nội địa', 'adj.', NULL, NULL, 'Trái nghĩa với ''coastal'' (thuộc ven biển); khi đóng vai trò là trạng từ, từ này cũng thường được nhấn mạnh ở âm tiết thứ hai.', 'We stayed in a quiet inland village surrounded by hills.', NULL, 'Chúng tôi ở lại một ngôi làng nội địa yên tĩnh được bao quanh bởi các ngọn đồi.', '{"wordId":"inland","ukIpa":"/ˈɪnlənd/","usIpa":"/ˈɪnlənd/","cefr":"B2","topic":"nature","senses":[{"pos":"adj.","en":"Located away from the coast, towards the country''s interior","vi":"thuộc nội địa; ở sâu trong đất liền"},{"pos":"adv.","en":"Away from the coast, towards or within the interior","vi":"hướng vào nội địa; ở trong nội địa"}],"examples":[{"en":"We stayed in a quiet inland village surrounded by hills.","vi":"Chúng tôi ở lại một ngôi làng nội địa yên tĩnh được bao quanh bởi các ngọn đồi.","audioKind":"ex"},{"en":"As coastal flooding becomes more frequent, some communities may move inland to reduce their exposure to risk.","vi":"Khi tình trạng ngập lụt ven biển trở nên thường xuyên hơn, một số cộng đồng có thể di dời vào sâu trong nội địa để giảm thiểu rủi ro.","audioKind":"ex2"}],"collocations":[{"en":"inland areas","vi":"các khu vực nội địa"},{"en":"inland waterways","vi":"đường thủy nội địa"},{"en":"move inland","vi":"di dời vào nội địa"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trái nghĩa với ''coastal'' (thuộc ven biển); khi đóng vai trò là trạng từ, từ này cũng thường được nhấn mạnh ở âm tiết thứ hai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_trail', 'en-b2-20', 'trail', '/treɪl/', 'B2', 'đường mòn; lối đi; vết tích; dấu vết; kéo lê; tụt lại phía sau', 'n.', 'trailing (adj.)', NULL, 'trail đóng vai trò danh từ có thể chỉ đường mòn hoặc dấu vết; trail behind chỉ việc tụt lại phía sau.', 'We followed a narrow trail through the pine forest.', NULL, 'Chúng tôi đi theo một lối mòn nhỏ xuyên qua khu rừng thông.', '{"wordId":"trail","ukIpa":"/treɪl/","usIpa":"/treɪl/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A path through countryside, forests, or mountains.","vi":"đường mòn; lối đi"},{"pos":"n.","en":"A series of marks or objects left by something moving.","vi":"vết tích; dấu vết"},{"pos":"v.","en":"To drag behind something or move slowly behind others.","vi":"kéo lê; tụt lại phía sau"}],"examples":[{"en":"We followed a narrow trail through the pine forest.","vi":"Chúng tôi đi theo một lối mòn nhỏ xuyên qua khu rừng thông.","audioKind":"ex"},{"en":"Maintaining walking trails can encourage outdoor recreation while protecting fragile habitats from uncontrolled visitor access.","vi":"Việc duy trì các tuyến đường mòn đi bộ có thể thúc đẩy hoạt động giải trí ngoài trời đồng thời bảo vệ các sinh cảnh mỏng manh khỏi việc du khách tự ý giẫm đạp.","audioKind":"ex2"}],"collocations":[{"en":"a hiking trail","vi":"tuyến đường đi bộ đường dài"},{"en":"a trail of footprints","vi":"một vệt dấu chân"},{"en":"trail behind","vi":"tụt lại phía sau"}],"wordFamily":["trailing (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"trail đóng vai trò danh từ có thể chỉ đường mòn hoặc dấu vết; trail behind chỉ việc tụt lại phía sau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cod', 'en-b2-20', 'cod', '/kɑːd/', 'B2', 'cá tuyết; thịt cá tuyết', 'n.', NULL, NULL, 'Dạng số ít và số nhiều của loài cá này đều là cod; khi chỉ thịt cá thì đây là danh từ không đếm được.', 'We baked the cod with lemon and fresh herbs.', NULL, 'Chúng tôi nướng cá tuyết với chanh và các loại thảo mộc tươi.', '{"wordId":"cod","ukIpa":"/kɒd/","usIpa":"/kɑːd/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A large sea fish, or its white flesh eaten as food.","vi":"cá tuyết; thịt cá tuyết"}],"examples":[{"en":"We baked the cod with lemon and fresh herbs.","vi":"Chúng tôi nướng cá tuyết với chanh và các loại thảo mộc tươi.","audioKind":"ex"},{"en":"Strict fishing limits can help cod populations recover while protecting the long-term livelihoods of coastal communities.","vi":"Các hạn chế đánh bắt nghiêm ngặt có thể giúp quần thể cá tuyết phục hồi đồng thời bảo vệ sinh kế lâu dài của các cộng đồng ven biển.","audioKind":"ex2"}],"collocations":[{"en":"cod fillet","vi":"phi lê cá tuyết"},{"en":"cod liver oil","vi":"dầu gan cá tuyết"},{"en":"cod stocks","vi":"nguồn lợi cá tuyết"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số ít và số nhiều của loài cá này đều là cod; khi chỉ thịt cá thì đây là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_richness', 'en-b2-20', 'richness', '/ˈrɪtʃnəs/', 'B2', 'sự phong phú; tính đa dạng; sự nồng đượm; sự đậm đà (hương vị hoặc màu sắc)', 'n.', 'rich (adj.), richly (adv.), enrich (v.), enrichment (n.)', 'Đồng nghĩa: abundance', 'Thường chỉ sự phong phú về nội dung hoặc độ đậm đà của hương vị; sự giàu có về tiền tài thường dùng wealth.', 'The richness of local wildlife amazed us during our walk.', NULL, 'Sự phong phú của động vật hoang dã địa phương đã khiến chúng tôi kinh ngạc trong chuyến đi dạo.', '{"wordId":"richness","ukIpa":"/ˈrɪtʃnəs/","usIpa":"/ˈrɪtʃnəs/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"The quality of containing many varied or valuable elements.","vi":"sự phong phú; tính đa dạng"},{"pos":"n.","en":"A deep, strong, or full quality of flavour or colour.","vi":"sự nồng đượm; sự đậm đà (hương vị hoặc màu sắc)"}],"examples":[{"en":"The richness of local wildlife amazed us during our walk.","vi":"Sự phong phú của động vật hoang dã địa phương đã khiến chúng tôi kinh ngạc trong chuyến đi dạo.","audioKind":"ex"},{"en":"Protecting traditional crafts helps preserve the cultural richness of communities facing rapid social change.","vi":"Việc bảo tồn các nghề thủ công truyền thống giúp duy trì sự giàu có về văn hóa của các cộng đồng đang đối mặt với sự biến đổi xã hội nhanh chóng.","audioKind":"ex2"}],"collocations":[{"en":"cultural richness","vi":"sự phong phú về văn hóa"},{"en":"species richness","vi":"mức độ đa dạng loài"},{"en":"richness of flavour","vi":"độ đậm đà của hương vị"}],"wordFamily":["rich (adj.)","richly (adv.)","enrich (v.)","enrichment (n.)"],"synonyms":["abundance"],"antonyms":[],"tipVi":"Thường chỉ sự phong phú về nội dung hoặc độ đậm đà của hương vị; sự giàu có về tiền tài thường dùng wealth.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_feather', 'en-b2-20', 'feather', '/ˈfeðər/', 'B2', 'lông vũ; chiếc lông chim', 'n.', 'feathery (adj.), feathered (adj.)', NULL, 'feather chỉ một chiếc lông vũ riêng lẻ; fur thường chỉ lớp lông dày của động vật.', 'A white feather floated gently onto the garden path.', NULL, 'Một chiếc lông vũ màu trắng nhẹ nhàng bay xuống lối đi trong vườn.', '{"wordId":"feather","ukIpa":"/ˈfeðə/","usIpa":"/ˈfeðər/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"One of the light, soft structures covering a bird''s body.","vi":"lông vũ; chiếc lông chim"}],"examples":[{"en":"A white feather floated gently onto the garden path.","vi":"Một chiếc lông vũ màu trắng nhẹ nhàng bay xuống lối đi trong vườn.","audioKind":"ex"},{"en":"Feathers help birds maintain their body temperature, allowing them to survive in colder environments.","vi":"Lông vũ giúp các loài chim duy trì thân nhiệt, cho phép chúng sinh tồn trong môi trường lạnh giá hơn.","audioKind":"ex2"}],"collocations":[{"en":"a bird''s feathers","vi":"lông của một con chim"},{"en":"tail feathers","vi":"lông đuôi"},{"en":"as light as a feather","vi":"nhẹ tựa lông hồng; nhẹ như tơ"}],"wordFamily":["feathery (adj.)","feathered (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"feather chỉ một chiếc lông vũ riêng lẻ; fur thường chỉ lớp lông dày của động vật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spectacular', 'en-b2-20', 'spectacular', '/spekˈtækjəlɚ/', 'B2', 'ngoạn mục; hùng vĩ; đẹp mắt; ấn tượng; đáng kinh ngạc', 'adj.', 'spectacularly (adv.), spectacle (n.)', 'Đồng nghĩa: impressive, stunning · Trái nghĩa: unimpressive', 'Có thể dùng để miêu tả cảnh quan hùng vĩ hoặc bổ nghĩa cho các danh từ trừu tượng như growth.', 'We watched a spectacular sunset from the hilltop.', NULL, 'Chúng tôi đã ngắm nhìn một hoàng hôn ngoạn mục từ đỉnh đồi.', '{"wordId":"spectacular","ukIpa":"/spekˈtækjələ/","usIpa":"/spekˈtækjəlɚ/","cefr":"B2","topic":"nature","senses":[{"pos":"adj.","en":"extremely impressive to see or experience","vi":"ngoạn mục; hùng vĩ; đẹp mắt"},{"pos":"adj.","en":"unusually great or impressive in degree","vi":"ngoạn mục; ấn tượng; đáng kinh ngạc"}],"examples":[{"en":"We watched a spectacular sunset from the hilltop.","vi":"Chúng tôi đã ngắm nhìn một hoàng hôn ngoạn mục từ đỉnh đồi.","audioKind":"ex"},{"en":"The region''s spectacular mountain scenery attracts tourists, creating jobs but also increasing pressure on fragile ecosystems.","vi":"Phong cảnh núi non hùng vĩ của vùng này thu hút đông đảo du khách, tạo ra việc làm nhưng đồng thời cũng gia tăng áp lực lên hệ sinh thái mỏng manh.","audioKind":"ex2"}],"collocations":[{"en":"spectacular scenery","vi":"cảnh quan ngoạn mục"},{"en":"a spectacular display","vi":"màn trình diễn mãn nhãn"},{"en":"spectacular growth","vi":"sự tăng trưởng ngoạn mục"}],"wordFamily":["spectacularly (adv.)","spectacle (n.)"],"synonyms":["impressive","stunning"],"antonyms":["unimpressive"],"tipVi":"Có thể dùng để miêu tả cảnh quan hùng vĩ hoặc bổ nghĩa cho các danh từ trừu tượng như growth.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inhabit', 'en-b2-20', 'inhabit', '/ɪnˈhæbɪt/', 'B2', 'sinh sống ở; cư ngụ ở', 'v.', 'inhabitant (n.), inhabitable (adj.), uninhabited (adj.)', 'Đồng nghĩa: occupy, live in', 'Là ngoại động từ, đi trực tiếp với địa điểm, không thêm "in".', 'Tiny crabs inhabit the rock pools near our house.', NULL, 'Những con cua nhỏ sinh sống trong các vũng nước trên đá gần nhà chúng tôi.', '{"wordId":"inhabit","ukIpa":"/ɪnˈhæbɪt/","usIpa":"/ɪnˈhæbɪt/","cefr":"B2","topic":"nature","senses":[{"pos":"v.","en":"To live in a particular place or environment","vi":"sinh sống ở; cư ngụ ở"}],"examples":[{"en":"Tiny crabs inhabit the rock pools near our house.","vi":"Những con cua nhỏ sinh sống trong các vũng nước trên đá gần nhà chúng tôi.","audioKind":"ex"},{"en":"Many species that inhabit tropical forests face increasing pressure as agricultural expansion reduces the area of suitable habitat.","vi":"Nhiều loài sinh sống trong các khu rừng nhiệt đới đang đối mặt với áp lực ngày càng tăng khi việc mở rộng nông nghiệp làm thu hẹp diện tích môi trường sống phù hợp.","audioKind":"ex2"}],"collocations":[{"en":"inhabit an island","vi":"sinh sống trên đảo"},{"en":"inhabit coastal waters","vi":"sinh sống ở vùng nước ven biển"},{"en":"densely inhabited areas","vi":"các khu vực đông dân cư"}],"wordFamily":["inhabitant (n.)","inhabitable (adj.)","uninhabited (adj.)"],"synonyms":["occupy","live in"],"antonyms":[],"tipVi":"Là ngoại động từ, đi trực tiếp với địa điểm, không thêm \"in\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hollow', 'en-b2-20', 'hollow', '/ˈhɑːloʊ/', 'B2', 'rỗng; trống rỗng bên trong; sáo rỗng; không chân thành; làm rỗng; khoét rỗng', 'adj.', 'hollowness (n.), hollowly (adv.)', 'Trái nghĩa: solid', 'hollow chỉ bên trong có khoảng trống; empty chỉ bên trong không có gì.', 'We found a squirrel hiding inside a hollow tree.', NULL, 'Chúng tôi tìm thấy một con sóc đang trốn bên trong một cái cây rỗng.', '{"wordId":"hollow","ukIpa":"/ˈhɒləʊ/","usIpa":"/ˈhɑːloʊ/","cefr":"B2","topic":"nature","senses":[{"pos":"adj.","en":"having an empty space inside","vi":"rỗng; trống rỗng bên trong"},{"pos":"adj.","en":"lacking real meaning, value, or sincere feeling","vi":"sáo rỗng; không chân thành"},{"pos":"v.","en":"to remove the inside of something, leaving an empty space","vi":"làm rỗng; khoét rỗng"}],"examples":[{"en":"We found a squirrel hiding inside a hollow tree.","vi":"Chúng tôi tìm thấy một con sóc đang trốn bên trong một cái cây rỗng.","audioKind":"ex"},{"en":"Government promises to protect endangered species will remain hollow unless they are supported by adequate funding and effective enforcement.","vi":"Các cam kết của chính phủ về việc bảo vệ các loài có nguy cơ tuyệt chủng sẽ vẫn chỉ là lời nói sáo rỗng trừ khi chúng được hỗ trợ bởi nguồn kinh phí đầy đủ và việc thực thi hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"a hollow tree","vi":"cây rỗng ruột"},{"en":"hollow promises","vi":"lời hứa sáo rỗng"},{"en":"a hollow sound","vi":"âm thanh rỗng"},{"en":"hollow out","vi":"khoét rỗng"}],"wordFamily":["hollowness (n.)","hollowly (adv.)"],"synonyms":[],"antonyms":["solid"],"tipVi":"hollow chỉ bên trong có khoảng trống; empty chỉ bên trong không có gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_poultry', 'en-b2-20', 'poultry', '/ˈpoʊltri/', 'B2', 'gia cầm (chim được nuôi để lấy thịt hoặc trứng); thịt gia cầm (thịt từ các loài chim được nuôi như gà và gà tây)', 'n.', NULL, NULL, 'Không dùng a poultry; để chỉ một con gia cầm, có thể dùng a chicken, v.v.', 'My aunt keeps poultry in a spacious backyard enclosure.', NULL, 'Dì tôi nuôi gia cầm trong một khu rào rộng rãi ở sân sau.', '{"wordId":"poultry","ukIpa":"/ˈpəʊltri/","usIpa":"/ˈpoʊltri/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"Birds such as chickens kept for their meat or eggs.","vi":"gia cầm (chim được nuôi để lấy thịt hoặc trứng)"},{"pos":"n.","en":"Meat from farmed birds such as chickens and turkeys.","vi":"thịt gia cầm (thịt từ các loài chim được nuôi như gà và gà tây)"}],"examples":[{"en":"My aunt keeps poultry in a spacious backyard enclosure.","vi":"Dì tôi nuôi gia cầm trong một khu rào rộng rãi ở sân sau.","audioKind":"ex"},{"en":"Higher welfare standards for poultry can improve animal health, although they may increase production costs.","vi":"Các tiêu chuẩn phúc lợi cao hơn đối với gia cầm có thể cải thiện sức khỏe động vật, mặc dù chúng có thể làm tăng chi phí sản xuất.","audioKind":"ex2"}],"collocations":[{"en":"poultry farming","vi":"chăn nuôi gia cầm"},{"en":"poultry feed","vi":"thức ăn cho gia cầm"},{"en":"poultry products","vi":"sản phẩm từ gia cầm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Không dùng a poultry; để chỉ một con gia cầm, có thể dùng a chicken, v.v.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flap', 'en-b2-20', 'flap', '/flæp/', 'B2', 'vỗ; đập; bay phần phật; tấm che; nắp (vải/giấy); sự hoảng loạn; sự lo lắng', 'v.', 'flapping (n.)', 'Đồng nghĩa: flutter', 'Dạng quá khứ là flapped và dạng tiếp diễn là flapping, đều nhân đôi phụ âm p.', 'The ducks flapped their wings and splashed across the pond.', NULL, 'Những con vịt vỗ cánh và bơi tung tóe khắp mặt ao.', '{"wordId":"flap","ukIpa":"/flæp/","usIpa":"/flæp/","cefr":"B2","topic":"nature","senses":[{"pos":"v.","en":"To move up and down repeatedly, or make something move.","vi":"vỗ; đập; bay phần phật"},{"pos":"n.","en":"A flat piece attached along one edge, often covering something.","vi":"tấm che; nắp (vải/giấy)"},{"pos":"n.","en":"A state of worry or unnecessary excitement.","vi":"sự hoảng loạn; sự lo lắng"}],"examples":[{"en":"The ducks flapped their wings and splashed across the pond.","vi":"Những con vịt vỗ cánh và bơi tung tóe khắp mặt ao.","audioKind":"ex"},{"en":"Observing how birds flap their wings can help engineers develop more efficient designs for small flying robots.","vi":"Việc quan sát cách các loài chim vỗ cánh có thể giúp các kỹ sư phát triển thiết kế hiệu quả hơn cho robot bay nhỏ.","audioKind":"ex2"}],"collocations":[{"en":"flap your wings","vi":"vỗ cánh"},{"en":"pocket flap","vi":"nắp túi áo"},{"en":"get in a flap","vi":"rơi vào trạng thái hoảng loạn"}],"wordFamily":["flapping (n.)"],"synonyms":["flutter"],"antonyms":[],"tipVi":"Dạng quá khứ là flapped và dạng tiếp diễn là flapping, đều nhân đôi phụ âm p.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scent', 'en-b2-20', 'scent', '/sent/', 'B2', 'hương thơm; mùi hương; dấu vết mùi; ngửi thấy; đánh hơi thấy', 'n.', 'scented (adj.), unscented (adj.)', 'Đồng nghĩa: smell, fragrance', 'scent thường chỉ hương thơm dễ chịu, cũng dùng cho mùi động vật để lại; chữ c không phát âm.', 'The scent of fresh bread filled the kitchen.', NULL, 'Hương thơm của bánh mì mới nướng lan tỏa khắp căn bếp.', '{"wordId":"scent","ukIpa":"/sent/","usIpa":"/sent/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A noticeable smell, especially a pleasant one.","vi":"hương thơm; mùi hương"},{"pos":"n.","en":"A smell left behind that an animal can follow.","vi":"dấu vết mùi"},{"pos":"v.","en":"To detect something by its smell.","vi":"ngửi thấy; đánh hơi thấy"}],"examples":[{"en":"The scent of fresh bread filled the kitchen.","vi":"Hương thơm của bánh mì mới nướng lan tỏa khắp căn bếp.","audioKind":"ex"},{"en":"The scent of flowers can attract pollinators, helping many plant species reproduce and maintain healthy ecosystems.","vi":"Hương thơm của các loài hoa có thể thu hút các loài thụ phấn, giúp nhiều loài thực vật sinh sản và duy trì hệ sinh thái lành mạnh.","audioKind":"ex2"}],"collocations":[{"en":"a delicate scent","vi":"hương thơm dịu nhẹ"},{"en":"the scent of flowers","vi":"hương hoa"},{"en":"follow a scent","vi":"lần theo dấu vết mùi"}],"wordFamily":["scented (adj.)","unscented (adj.)"],"synonyms":["smell","fragrance"],"antonyms":[],"tipVi":"scent thường chỉ hương thơm dễ chịu, cũng dùng cho mùi động vật để lại; chữ c không phát âm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_arctic', 'en-b2-20', 'arctic', '/ˈɑːrktɪk/', 'B2', 'thuộc Bắc Cực; lạnh buốt; lạnh giá; vùng Bắc Cực', 'adj.', NULL, 'Đồng nghĩa: polar, freezing · Trái nghĩa: antarctic', 'Dùng "the Arctic" khi chỉ vùng Bắc Cực; vùng Nam Cực là "the Antarctic".', 'An arctic fox curled up beside a snowy rock.', NULL, 'Một con cáo Bắc Cực cuộn tròn bên cạnh mảng đá phủ đầy tuyết.', '{"wordId":"arctic","ukIpa":"/ˈɑːktɪk/","usIpa":"/ˈɑːrktɪk/","cefr":"B2","topic":"nature","senses":[{"pos":"adj.","en":"Relating to the region around the North Pole.","vi":"thuộc Bắc Cực"},{"pos":"adj.","en":"Extremely cold.","vi":"lạnh buốt; lạnh giá"},{"pos":"n.","en":"The region surrounding the North Pole.","vi":"vùng Bắc Cực"}],"examples":[{"en":"An arctic fox curled up beside a snowy rock.","vi":"Một con cáo Bắc Cực cuộn tròn bên cạnh mảng đá phủ đầy tuyết.","audioKind":"ex"},{"en":"Rising temperatures threaten arctic wildlife by reducing the sea ice that many species depend on.","vi":"Nhiệt độ tăng cao đang đe dọa động vật hoang dã ở Bắc Cực bằng cách làm giảm lớp băng biển mà nhiều loài sinh vật phụ thuộc vào.","audioKind":"ex2"}],"collocations":[{"en":"arctic fox","vi":"cáo Bắc Cực"},{"en":"arctic conditions","vi":"điều kiện giá lạnh ở Bắc Cực"},{"en":"the Arctic","vi":"vùng Bắc Cực"}],"wordFamily":[],"synonyms":["polar","freezing"],"antonyms":["antarctic"],"tipVi":"Dùng \"the Arctic\" khi chỉ vùng Bắc Cực; vùng Nam Cực là \"the Antarctic\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_barn', 'en-b2-20', 'barn', '/bɑːrn/', 'B2', 'kho lúa; chuồng trại', 'n.', NULL, NULL, 'Chỉ các tòa nhà lớn trong nông trại dùng để cất giữ hoa màu hoặc nuôi nhốt gia súc.', 'We stacked the hay inside the barn before sunset.', NULL, 'Chúng tôi đã chất đống cỏ khô vào trong kho trước khi mặt trời lặn.', '{"wordId":"barn","ukIpa":"/bɑːn/","usIpa":"/bɑːrn/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"a large farm building for storing crops or keeping animals","vi":"kho lúa; chuồng trại"}],"examples":[{"en":"We stacked the hay inside the barn before sunset.","vi":"Chúng tôi đã chất đống cỏ khô vào trong kho trước khi mặt trời lặn.","audioKind":"ex"},{"en":"Converting unused barns into visitor accommodation can provide additional income for farmers in rural communities.","vi":"Việc chuyển đổi các kho chứa không dùng đến thành nơi lưu trú cho du khách có thể mang lại thêm thu nhập cho nông dân ở các vùng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"store hay in a barn","vi":"cất cỏ khô vào kho"},{"en":"barn conversion","vi":"cải tạo kho chứa"},{"en":"wooden barn","vi":"kho gỗ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ các tòa nhà lớn trong nông trại dùng để cất giữ hoa màu hoặc nuôi nhốt gia súc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_20_1', 'en-b2-20', 'Cách dùng “sting” (v.) — chích; đốt', 'a bee sting  ·  a wasp sting  ·  stinging criticism', 'Dạng quá khứ đơn và quá khứ phân từ đều là "stung"; dùng "sting" cho hành động đốt/chích (của ong, sứa...), còn cắn dùng "bite".', 'Họ từ (Word Family): stinging (adj.), stinger (n.)', '[{"hanzi":"A bee stung my ankle while I watered the flowers.","pinyin":"","meaning":"Một con ong đã đốt vào mắt cá chân tôi khi tôi đang tưới hoa."},{"hanzi":"Harsh criticism can sting young learners and discourage them from participating in classroom discussions.","pinyin":"","meaning":"Những lời chỉ trích gay gắt có thể làm tổn thương những người học nhỏ tuổi và khiến họ ngại tham gia thảo luận trên lớp."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_20_2', 'en-b2-20', 'Cách dùng “inland” (adj.) — thuộc nội địa; ở sâu trong đất liền', 'inland areas  ·  inland waterways  ·  move inland', 'Trái nghĩa với ''coastal'' (thuộc ven biển); khi đóng vai trò là trạng từ, từ này cũng thường được nhấn mạnh ở âm tiết thứ hai.', NULL, '[{"hanzi":"We stayed in a quiet inland village surrounded by hills.","pinyin":"","meaning":"Chúng tôi ở lại một ngôi làng nội địa yên tĩnh được bao quanh bởi các ngọn đồi."},{"hanzi":"As coastal flooding becomes more frequent, some communities may move inland to reduce their exposure to risk.","pinyin":"","meaning":"Khi tình trạng ngập lụt ven biển trở nên thường xuyên hơn, một số cộng đồng có thể di dời vào sâu trong nội địa để giảm thiểu rủi ro."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_20_3', 'en-b2-20', 'Cách dùng “frost” (n.) — sương giá; băng giá', 'a sharp frost  ·  ground frost  ·  frost damage', 'frost là sương giá chứ không phải tuyết; động từ chỉ việc phủ kem đường lên bánh ngọt thường phổ biến trong tiếng Mỹ.', 'Họ từ (Word Family): frosty (adj.), frosted (adj.), frosting (n.)', '[{"hanzi":"A thin frost covered the grass outside our kitchen.","pinyin":"","meaning":"Một lớp sương giá mỏng phủ kín thảm cỏ ngoài bếp nhà chúng tôi."},{"hanzi":"Unexpected spring frost can damage young crops, reducing yields and increasing financial pressure on farmers.","pinyin":"","meaning":"Sương giá bất chợt vào mùa xuân có thể tàn phá cây trồng non, làm giảm năng suất và gia tăng gánh nặng tài chính cho người nông dân."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_20_4', 'en-b2-20', 'Cách dùng “richness” (n.) — sự phong phú; tính đa dạng', 'cultural richness  ·  species richness  ·  richness of flavour', 'Thường chỉ sự phong phú về nội dung hoặc độ đậm đà của hương vị; sự giàu có về tiền tài thường dùng wealth.', 'Họ từ (Word Family): rich (adj.), richly (adv.), enrich (v.), enrichment (n.) | Đồng nghĩa: abundance', '[{"hanzi":"The richness of local wildlife amazed us during our walk.","pinyin":"","meaning":"Sự phong phú của động vật hoang dã địa phương đã khiến chúng tôi kinh ngạc trong chuyến đi dạo."},{"hanzi":"Protecting traditional crafts helps preserve the cultural richness of communities facing rapid social change.","pinyin":"","meaning":"Việc bảo tồn các nghề thủ công truyền thống giúp duy trì sự giàu có về văn hóa của các cộng đồng đang đối mặt với sự biến đổi xã hội nhanh chóng."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_20_1', 'en-b2-20', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_20_1_1', 'ten_b2_20_1', 'exotic', 'The market sells exotic fruits I have never tasted.', 'The market sells exotic fruits I have never tasted.', '/ɪɡˈzɑːtɪk/', 'Khu chợ bán những loại trái cây ngoại lai mà tôi chưa từng nếm qua.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_20_1_2', 'ten_b2_20_1', 'sting', 'A bee stung my ankle while I watered the flowers.', 'A bee stung my ankle while I watered the flowers.', '/stɪŋ/', 'Một con ong đã đốt vào mắt cá chân tôi khi tôi đang tưới hoa.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_20_1_3', 'ten_b2_20_1', 'peak', 'Snow still covered the mountain peak in June.', 'Snow still covered the mountain peak in June.', '/piːk/', 'Tuyết vẫn phủ trắng đỉnh núi vào tháng Sáu.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_20_1_4', 'ten_b2_20_1', 'undersea', 'The documentary showed colourful fish around an undersea cave.', 'The documentary showed colourful fish around an undersea cave.', '/ˌʌndɚˈsiː/', 'Bộ phim tài liệu cho thấy những chú cá đầy màu sắc quanh một hang động dưới biển.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_20_1_5', 'ten_b2_20_1', 'blizzard', 'We stayed indoors while the blizzard shook our windows.', 'We stayed indoors while the blizzard shook our windows.', '/ˈblɪzərd/', 'Chúng tôi ở trong nhà khi trận bão tuyết làm rung chuyển các khung cửa sổ.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_20_1_6', 'ten_b2_20_1', 'vast', 'A vast desert stretched beyond the small village.', 'A vast desert stretched beyond the small village.', '/væst/', 'Một sa mạc rộng lớn trải dài vượt qua ngôi làng nhỏ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_20_1_7', 'ten_b2_20_1', 'breeze', 'A cool breeze lifted the curtains beside my bed.', 'A cool breeze lifted the curtains beside my bed.', '/briːz/', 'Một cơn gió mát thổi bay bức rèm bên giường tôi.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_20_1_8', 'ten_b2_20_1', 'dusk', 'We reached the campsite at dusk and lit a lantern.', 'We reached the campsite at dusk and lit a lantern.', '/dʌsk/', 'Chúng tôi đến khu cắm trại vào lúc chạng vạng và thắp lên một ngọn đèn lồng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_20_1_1', 'en-b2-20', 'ten_b2_20_1', 'listening', 'listening', 'The market sells exotic fruits I have never tasted.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một con cáo Bắc Cực cuộn tròn bên cạnh mảng đá phủ đầy tuyết.","Khu chợ bán những loại trái cây ngoại lai mà tôi chưa từng nếm qua.","Chúng tôi đến khu cắm trại vào lúc chạng vạng và thắp lên một ngọn đèn lồng.","Dì tôi nuôi gia cầm trong một khu rào rộng rãi ở sân sau."]'::jsonb, 1, 'The market sells exotic fruits I have never tasted. → Khu chợ bán những loại trái cây ngoại lai mà tôi chưa từng nếm qua.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_20_1_2', 'en-b2-20', 'ten_b2_20_1', 'listening', 'listening', 'A bee stung my ankle while I watered the flowers.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một con ong đã đốt vào mắt cá chân tôi khi tôi đang tưới hoa.","Chúng tôi đã chất đống cỏ khô vào trong kho trước khi mặt trời lặn.","Chúng tôi đi theo một lối mòn nhỏ xuyên qua khu rừng thông.","Chúng tôi tìm thấy một con sóc đang trốn bên trong một cái cây rỗng."]'::jsonb, 0, 'A bee stung my ankle while I watered the flowers. → Một con ong đã đốt vào mắt cá chân tôi khi tôi đang tưới hoa.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_20_1_3', 'en-b2-20', 'ten_b2_20_1', 'listening', 'listening', 'Snow still covered the mountain peak in June.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đến khu cắm trại vào lúc chạng vạng và thắp lên một ngọn đèn lồng.","Chúng tôi tìm thấy một con sóc đang trốn bên trong một cái cây rỗng.","Chúng tôi ngồi trên một gốc cây để ăn trưa.","Tuyết vẫn phủ trắng đỉnh núi vào tháng Sáu."]'::jsonb, 3, 'Snow still covered the mountain peak in June. → Tuyết vẫn phủ trắng đỉnh núi vào tháng Sáu.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_20_2', 'en-b2-20', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_20_2_1', 'ten_b2_20_2', 'exotic', 'Introducing exotic plants into local gardens can threaten native species if their spread is not controlled.', 'Introducing exotic plants into local gardens can threaten native species if their spread is not controlled.', '/ɪɡˈzɑːtɪk/', 'Việc đưa các loài thực vật ngoại lai vào vườn nhà có thể đe dọa các loài bản địa nếu sự lây lan của chúng không được kiểm soát.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_20_2_2', 'ten_b2_20_2', 'sting', 'Harsh criticism can sting young learners and discourage them from participating in classroom discussions.', 'Harsh criticism can sting young learners and discourage them from participating in classroom discussions.', '/stɪŋ/', 'Những lời chỉ trích gay gắt có thể làm tổn thương những người học nhỏ tuổi và khiến họ ngại tham gia thảo luận trên lớp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_20_2_3', 'ten_b2_20_2', 'peak', 'Electricity demand usually peaks in the early evening, when households use several appliances at once.', 'Electricity demand usually peaks in the early evening, when households use several appliances at once.', '/piːk/', 'Nhu cầu điện năng thường đạt mức cao nhất vào chập tối, khi các hộ gia đình sử dụng đồng thời nhiều thiết bị điện.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_20_2_4', 'ten_b2_20_2', 'undersea', 'Undersea cables connect continents and provide essential infrastructure for global communication and international trade.', 'Undersea cables connect continents and provide essential infrastructure for global communication and international trade.', '/ˌʌndɚˈsiː/', 'Cáp ngầm kết nối các châu lục và cung cấp cơ sở hạ tầng thiết yếu cho giao tiếp toàn cầu và thương mại quốc tế.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_20_2_5', 'ten_b2_20_2', 'blizzard', 'A severe blizzard can disrupt public transport and leave rural communities without electricity for several days.', 'A severe blizzard can disrupt public transport and leave rural communities without electricity for several days.', '/ˈblɪzərd/', 'Một trận bão tuyết dữ dội có thể làm gián đoạn giao thông công cộng và khiến các cộng đồng nông thôn mất điện trong vài ngày.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_20_2_6', 'ten_b2_20_2', 'vast', 'Digital libraries give students access to vast amounts of information, although evaluating its reliability remains essential.', 'Digital libraries give students access to vast amounts of information, although evaluating its reliability remains essential.', '/væst/', 'Thư viện số giúp sinh viên tiếp cận lượng thông tin khổng lồ, mặc dù việc đánh giá độ tin cậy của thông tin vẫn là điều thiết yếu.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_20_2_1', 'en-b2-20', 'ten_b2_20_2', 'listening', 'listening', 'Introducing exotic plants into local gardens can threaten native species if their spread is not controlled.', NULL, 'Trong câu vừa nghe, từ “exotic” mang nghĩa nào sau đây?', '["mang phong cách lạ; ngoại lai; đẹp kỳ lạ","vô cùng, hết sức, sâu sắc (về cảm xúc hoặc niềm tin)","hòn cuội; viên đá nhỏ nhẵn","tổn hại; sự tổn thương"]'::jsonb, 0, '“exotic” (/ɪɡˈzɑːtɪk/): mang phong cách lạ; ngoại lai; đẹp kỳ lạ. Câu đầy đủ: Introducing exotic plants into local gardens can threaten native species if their spread is not controlled.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_20_2_2', 'en-b2-20', 'ten_b2_20_2', 'listening', 'listening', 'Harsh criticism can sting young learners and discourage them from participating in classroom discussions.', NULL, 'Trong câu vừa nghe, từ “sting” mang nghĩa nào sau đây?', '["sự bất hạnh; vận rủi","chích; đốt","dài hạn; lâu dài","phục vụ; đáp ứng nhu cầu"]'::jsonb, 1, '“sting” (/stɪŋ/): chích; đốt. Câu đầy đủ: Harsh criticism can sting young learners and discourage them from participating in classroom discussions.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_20_1', 'en-b2-20', 'The market sells exotic fruits I have never tasted', 'Khu chợ bán những loại trái cây ngoại lai mà tôi chưa từng nếm qua.', 'exotic /ɪɡˈzɑːtɪk/', '["tasted","sells","The","never","exotic","fruits","have","market","I"]'::jsonb, NULL, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
