INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_20_4', 'en-b2-20', 'The documentary showed colourful fish around an undersea cave', 'Bộ phim tài liệu cho thấy những chú cá đầy màu sắc quanh một hang động dưới biển.', 'undersea /ˌʌndɚˈsiː/', '["The","an","fish","showed","undersea","colourful","documentary","cave","around"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_20_5', 'en-b2-20', 'We stayed indoors while the blizzard shook our windows', 'Chúng tôi ở trong nhà khi trận bão tuyết làm rung chuyển các khung cửa sổ.', 'blizzard /ˈblɪzərd/', '["shook","stayed","the","blizzard","our","We","indoors","windows","while"]'::jsonb, NULL, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_20_6', 'en-b2-20', 'A vast desert stretched beyond the small village', 'Một sa mạc rộng lớn trải dài vượt qua ngôi làng nhỏ.', 'vast /væst/', '["vast","village","stretched","the","desert","beyond","small","A"]'::jsonb, NULL, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_20_7', 'en-b2-20', 'A cool breeze lifted the curtains beside my bed', 'Một cơn gió mát thổi bay bức rèm bên giường tôi.', 'breeze /briːz/', '["breeze","the","A","curtains","cool","lifted","bed","beside","my"]'::jsonb, NULL, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_20_8', 'en-b2-20', 'We reached the campsite at dusk and lit a lantern', 'Chúng tôi đến khu cắm trại vào lúc chạng vạng và thắp lên một ngọn đèn lồng.', 'dusk /dʌsk/', '["lantern","the","We","campsite","at","and","dusk","reached","lit","a"]'::jsonb, NULL, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
