INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_20_1', 'en-b2-20', NULL, 'comprehensive_test', 'listening', 'exotic', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bách khoa toàn thư","điện tử","mang phong cách lạ; ngoại lai; đẹp kỳ lạ","hãng; đại lý; doanh nghiệp sắp xếp các dịch vụ cho cá nhân hoặc doanh nghiệp khác"]'::jsonb, 2, 'exotic (/ɪɡˈzɑːtɪk/) → mang phong cách lạ; ngoại lai; đẹp kỳ lạ; không phải bản địa', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_20_2', 'en-b2-20', NULL, 'comprehensive_test', 'listening', 'A bee stung my ankle while I watered the flowers.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một sa mạc rộng lớn trải dài vượt qua ngôi làng nhỏ.","Sự phong phú của động vật hoang dã địa phương đã khiến chúng tôi kinh ngạc trong chuyến đi dạo.","Người nuôi ong đã nhấc nắp lên và kiểm tra cái thùng nuôi ong.","Một con ong đã đốt vào mắt cá chân tôi khi tôi đang tưới hoa."]'::jsonb, 3, 'A bee stung my ankle while I watered the flowers. → Một con ong đã đốt vào mắt cá chân tôi khi tôi đang tưới hoa.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_20_3', 'en-b2-20', NULL, 'comprehensive_test', 'listening', 'peak', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thói quen; tập quán; phong tục","thuộc nội địa; ở sâu trong đất liền","cơn thịnh nộ; sự tức giận tột độ","đỉnh núi; đỉnh cao"]'::jsonb, 3, 'peak (/piːk/) → đỉnh núi; đỉnh cao; đạt đỉnh; lên đến mức cao nhất; cao điểm; nhiều nhất', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_20_4', 'en-b2-20', NULL, 'comprehensive_test', 'listening', 'The documentary showed colourful fish around an undersea cave.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi ở lại một ngôi làng nội địa yên tĩnh được bao quanh bởi các ngọn đồi.","Bộ phim tài liệu cho thấy những chú cá đầy màu sắc quanh một hang động dưới biển.","Sự phong phú của động vật hoang dã địa phương đã khiến chúng tôi kinh ngạc trong chuyến đi dạo.","Chúng tôi ở trong nhà khi trận bão tuyết làm rung chuyển các khung cửa sổ."]'::jsonb, 1, 'The documentary showed colourful fish around an undersea cave. → Bộ phim tài liệu cho thấy những chú cá đầy màu sắc quanh một hang động dưới biển.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_20_5', 'en-b2-20', NULL, 'comprehensive_test', 'listening', 'blizzard', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["giấu tên; vô danh","cành con, nhánh cây nhỏ","người kể chuyện; người thuyết minh; giọng đọc thuyết minh","bão tuyết"]'::jsonb, 3, 'blizzard (/ˈblɪzərd/) → bão tuyết', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_20_6', 'en-b2-20', NULL, 'comprehensive_test', 'listening', 'A vast desert stretched beyond the small village.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một con chim sẻ cậm một cành cây nhỏ bay về tổ của nó.","Những con vịt vỗ cánh và bơi tung tóe khắp mặt ao.","Tuyết vẫn phủ trắng đỉnh núi vào tháng Sáu.","Một sa mạc rộng lớn trải dài vượt qua ngôi làng nhỏ."]'::jsonb, 3, 'A vast desert stretched beyond the small village. → Một sa mạc rộng lớn trải dài vượt qua ngôi làng nhỏ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_20_7', 'en-b2-20', NULL, 'comprehensive_test', 'listening', 'breeze', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["gió nhẹ; cơn gió thoảng","mẫu; mẫu vật; vật mẫu","thợ gốm; người làm gốm","giám sát; theo dõi"]'::jsonb, 0, 'breeze (/briːz/) → gió nhẹ; cơn gió thoảng; việc rất dễ dàng; đi lướt qua nhanh chóng; vượt qua dễ dàng', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_20_8', 'en-b2-20', NULL, 'comprehensive_test', 'listening', 'We reached the campsite at dusk and lit a lantern.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi ở lại một ngôi làng nội địa yên tĩnh được bao quanh bởi các ngọn đồi.","Chúng tôi đến khu cắm trại vào lúc chạng vạng và thắp lên một ngọn đèn lồng.","Một chiếc lông vũ màu trắng nhẹ nhàng bay xuống lối đi trong vườn.","Người nuôi ong đã nhấc nắp lên và kiểm tra cái thùng nuôi ong."]'::jsonb, 1, 'We reached the campsite at dusk and lit a lantern. → Chúng tôi đến khu cắm trại vào lúc chạng vạng và thắp lên một ngọn đèn lồng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_20_9', 'en-b2-20', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A severe snowstorm with strong winds.”?', '["blizzard","scent","inland","poultry"]'::jsonb, 0, 'blizzard (/ˈblɪzərd/) → bão tuyết', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
