INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_20_18', 'en-b2-20', NULL, 'comprehensive_test', 'reading', NULL, 'Introducing exotic plants into local gardens can threaten native species if their spread is not controlled.', 'Dựa vào câu trên, từ “exotic” có nghĩa phù hợp nhất là gì?', '["xấu xa; độc ác","gãi (để giảm ngứa)","mang phong cách lạ; ngoại lai; đẹp kỳ lạ","trang thiết bị; đồ dùng"]'::jsonb, 2, 'exotic: mang phong cách lạ; ngoại lai; đẹp kỳ lạ; không phải bản địa. Dịch cả câu: Việc đưa các loài thực vật ngoại lai vào vườn nhà có thể đe dọa các loài bản địa nếu sự lây lan của chúng không được kiểm soát.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_20_19', 'en-b2-20', NULL, 'comprehensive_test', 'reading', NULL, 'Harsh criticism can sting young learners and discourage them from participating in classroom discussions.', 'Dựa vào câu trên, từ “sting” có nghĩa phù hợp nhất là gì?', '["chích; đốt","châm ngôn; phương châm; khẩu hiệu","sự phản đối; lời phản đối; ý kiến phản đối","độ dày; bề dày"]'::jsonb, 0, 'sting: chích; đốt; vết đốt; cơn đau nhói; làm tổn thương (tình cảm); làm đau lòng. Dịch cả câu: Những lời chỉ trích gay gắt có thể làm tổn thương những người học nhỏ tuổi và khiến họ ngại tham gia thảo luận trên lớp.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_20_20', 'en-b2-20', NULL, 'comprehensive_test', 'reading', NULL, 'Electricity demand usually peaks in the early evening, when households use several appliances at once.', 'Dựa vào câu trên, từ “peak” có nghĩa phù hợp nhất là gì?', '["hãng; đại lý; doanh nghiệp sắp xếp các dịch vụ cho cá nhân hoặc doanh nghiệp khác","quan tài; linh cữu","đỉnh núi; đỉnh cao","sự đi xuống, sự hạ xuống (di chuyển từ vị trí cao xuống vị trí thấp hơn)"]'::jsonb, 2, 'peak: đỉnh núi; đỉnh cao; đạt đỉnh; lên đến mức cao nhất; cao điểm; nhiều nhất. Dịch cả câu: Nhu cầu điện năng thường đạt mức cao nhất vào chập tối, khi các hộ gia đình sử dụng đồng thời nhiều thiết bị điện.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_20_21', 'en-b2-20', NULL, 'comprehensive_test', 'reading', NULL, 'Undersea cables connect continents and provide essential infrastructure for global communication and international trade.', 'Dựa vào câu trên, từ “undersea” có nghĩa phù hợp nhất là gì?', '["chi tiết; tỉ mỉ; tường tận","hạn chế; giới hạn","chim sẻ","ở dưới biển; dưới mặt nước biển"]'::jsonb, 3, 'undersea: ở dưới biển; dưới mặt nước biển. Dịch cả câu: Cáp ngầm kết nối các châu lục và cung cấp cơ sở hạ tầng thiết yếu cho giao tiếp toàn cầu và thương mại quốc tế.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_20_22', 'en-b2-20', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hương thơm; mùi hương”', '["scent","damp","chip","impulse"]'::jsonb, 0, 'hương thơm; mùi hương → scent (/sent/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_20_23', 'en-b2-20', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thuộc Bắc Cực”', '["plentiful","arctic","motor","protein"]'::jsonb, 1, 'thuộc Bắc Cực → arctic (/ˈɑːrktɪk/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_20_24', 'en-b2-20', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “kho lúa; chuồng trại”', '["barn","basin","territory","manual"]'::jsonb, 0, 'kho lúa; chuồng trại → barn (/bɑːrn/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-21', 'en', 'Bài 21: Thiên nhiên & Thời tiết (4) - CEFR B2', 'CEFR B2', 'B2 · Thiên nhiên', '27 từ vựng Tiếng Anh CEFR B2 chủ đề thiên nhiên & thời tiết kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4021, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_waving', 'en-b2-21', 'waving', '/ˈweɪvɪŋ/', 'B2', 'phấp phới, lay động, đu đưa qua lại nhẹ nhàng (thường là trong gió)', 'adj.', 'wave (v.), wave (n.), wavy (adj.)', NULL, 'Thường là dạng phân từ hiện tại của "wave"; dạng tĩnh có nghĩa là "gợn sóng" thường dùng "wavy".', 'We rested beneath the gently waving branches of a willow.', NULL, 'Chúng tôi nghỉ ngơi dưới những tán lá liễu đang khẽ đu đưa trong gió.', '{"wordId":"waving","ukIpa":"/ˈweɪvɪŋ/","usIpa":"/ˈweɪvɪŋ/","cefr":"B2","topic":"nature","senses":[{"pos":"adj.","en":"Moving gently back and forth, often in the wind.","vi":"phấp phới, lay động, đu đưa qua lại nhẹ nhàng (thường là trong gió)"}],"examples":[{"en":"We rested beneath the gently waving branches of a willow.","vi":"Chúng tôi nghỉ ngơi dưới những tán lá liễu đang khẽ đu đưa trong gió.","audioKind":"ex"},{"en":"The waving grasses along restored riverbanks provide valuable habitats for wildlife and help protect soil from erosion.","vi":"Những thảm cỏ lay động ven các bờ sông được phục hồi mang lại môi trường sống quý giá cho động vật hoang dã và giúp bảo vệ đất khỏi bị xói mòn.","audioKind":"ex2"}],"collocations":[{"en":"waving branches","vi":"cành cây đu đưa"},{"en":"waving flags","vi":"lá cờ phấp phới"},{"en":"gently waving grass","vi":"thảm cỏ khẽ lay động"}],"wordFamily":["wave (v.)","wave (n.)","wavy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là dạng phân từ hiện tại của \"wave\"; dạng tĩnh có nghĩa là \"gợn sóng\" thường dùng \"wavy\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_walnut', 'en-b2-21', 'walnut', '/ˈwɔːlnʌt/', 'B2', 'quả óc chó; cây óc chó; gỗ óc chó', 'n.', NULL, NULL, 'Đếm được khi chỉ quả hoặc cây, không đếm được khi chỉ chất liệu gỗ óc chó.', 'She cracked a walnut and shared the kernel with me.', NULL, 'Cô ấy đập một quả óc chó và chia phần nhân cho tôi.', '{"wordId":"walnut","ukIpa":"/ˈwɔːlnʌt/","usIpa":"/ˈwɔːlnʌt/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"An edible nut with a wrinkled kernel and hard shell.","vi":"quả óc chó"},{"pos":"n.","en":"A tree producing walnuts, or its wood used for furniture.","vi":"cây óc chó; gỗ óc chó"}],"examples":[{"en":"She cracked a walnut and shared the kernel with me.","vi":"Cô ấy đập một quả óc chó và chia phần nhân cho tôi.","audioKind":"ex"},{"en":"Growing walnut trees can provide farmers with additional income while increasing tree cover in rural areas.","vi":"Việc trồng cây óc chó có thể mang lại thêm thu nhập cho nông dân đồng thời tăng độ che phủ của cây xanh ở các vùng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"walnut shell","vi":"vỏ quả óc chó"},{"en":"walnut tree","vi":"cây óc chó"},{"en":"walnut oil","vi":"dầu quả óc chó"},{"en":"walnut furniture","vi":"đồ nội thất bằng gỗ óc chó"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Đếm được khi chỉ quả hoặc cây, không đếm được khi chỉ chất liệu gỗ óc chó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prey', 'en-b2-21', 'prey', '/preɪ/', 'B2', 'con mồi (bị động vật khác săn đuổi và ăn thịt); nạn nhân; mục tiêu bị lợi dụng hoặc hại; săn mồi; bóc lột; làm hại (thường đi với giới từ on)', 'n.', NULL, 'Trái nghĩa: predator', 'Danh từ prey thường là danh từ không đếm được; động từ thường đi với on (prey on); tránh nhầm lẫn với từ pray (cầu nguyện).', 'The owl watched its prey from a low branch.', NULL, 'Con cú chăm chú quan sát con mồi từ một cành cây thấp.', '{"wordId":"prey","ukIpa":"/preɪ/","usIpa":"/preɪ/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"An animal hunted and eaten by another animal.","vi":"con mồi (bị động vật khác săn đuổi và ăn thịt)"},{"pos":"n.","en":"Someone targeted for harm or exploitation.","vi":"nạn nhân; mục tiêu bị lợi dụng hoặc hại"},{"pos":"v.","en":"To hunt animals or exploit vulnerable people, usually with on.","vi":"săn mồi; bóc lột; làm hại (thường đi với giới từ on)"}],"examples":[{"en":"The owl watched its prey from a low branch.","vi":"Con cú chăm chú quan sát con mồi từ một cành cây thấp.","audioKind":"ex"},{"en":"When natural prey becomes scarce, some predators move closer to farms in search of food.","vi":"Khi con mồi tự nhiên trở nên khan hiếm, một số loài săn mồi sẽ di chuyển đến gần các trang trại hơn để tìm kiếm thức ăn.","audioKind":"ex2"}],"collocations":[{"en":"birds of prey","vi":"các loài chim săn mồi"},{"en":"prey on small animals","vi":"săn bắt động vật nhỏ"},{"en":"fall prey to fraud","vi":"sập bẫy lừa đảo"}],"wordFamily":[],"synonyms":[],"antonyms":["predator"],"tipVi":"Danh từ prey thường là danh từ không đếm được; động từ thường đi với on (prey on); tránh nhầm lẫn với từ pray (cầu nguyện).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_moist', 'en-b2-21', 'moist', '/mɔɪst/', 'B2', 'ẩm; ẩm ướt; ẩm mịn', 'adj.', 'moisture (n.), moisten (v.)', 'Đồng nghĩa: damp · Trái nghĩa: dry', 'moist thường chỉ mức độ ẩm ướt vừa phải, dễ chịu; damp thường mang sắc thái ẩm thấp và khó chịu hơn.', 'Keep the soil moist until the first leaves appear.', NULL, 'Hãy giữ cho đất ẩm cho đến khi những chiếc lá đầu tiên nhú lên.', '{"wordId":"moist","ukIpa":"/mɔɪst/","usIpa":"/mɔɪst/","cefr":"B2","topic":"nature","senses":[{"pos":"adj.","en":"Slightly wet, rather than dry or soaked.","vi":"ẩm; ẩm ướt; ẩm mịn"}],"examples":[{"en":"Keep the soil moist until the first leaves appear.","vi":"Hãy giữ cho đất ẩm cho đến khi những chiếc lá đầu tiên nhú lên.","audioKind":"ex"},{"en":"A layer of fallen leaves helps keep soil moist, reducing the need for frequent watering.","vi":"Một lớp lá rụng giúp giữ ẩm cho đất, làm giảm nhu cầu phải tưới nước thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"moist soil","vi":"đất ẩm"},{"en":"keep something moist","vi":"giữ cho vật gì ẩm"},{"en":"moist cake","vi":"bánh ẩm mềm"}],"wordFamily":["moisture (n.)","moisten (v.)"],"synonyms":["damp"],"antonyms":["dry"],"tipVi":"moist thường chỉ mức độ ẩm ướt vừa phải, dễ chịu; damp thường mang sắc thái ẩm thấp và khó chịu hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_darken', 'en-b2-21', 'darken', '/ˈdɑːrkən/', 'B2', 'làm tối đi; trở nên tối hơn; trở nên u ám; làm cho sầm mặt lại', 'v.', 'dark (adj.), darkness (n.)', 'Đồng nghĩa: dim · Trái nghĩa: brighten, lighten', 'Cả động từ transitive và intransitive đều dùng được: mây làm trời tối, hoặc trời tự tối.', 'Heavy clouds darkened the sky before we reached home.', NULL, 'Những đám mây dày đặc làm bầu trời tối sầm lại trước khi chúng tôi về đến nhà.', '{"wordId":"darken","ukIpa":"/ˈdɑːkən/","usIpa":"/ˈdɑːrkən/","cefr":"B2","topic":"nature","senses":[{"pos":"v.","en":"to become darker or make something darker","vi":"làm tối đi; trở nên tối hơn"},{"pos":"v.","en":"to become or make someone look unhappy or angry","vi":"trở nên u ám; làm cho sầm mặt lại"}],"examples":[{"en":"Heavy clouds darkened the sky before we reached home.","vi":"Những đám mây dày đặc làm bầu trời tối sầm lại trước khi chúng tôi về đến nhà.","audioKind":"ex"},{"en":"Thick smoke from industrial fires can darken the sky and reduce visibility across nearby residential areas.","vi":"Khói dày đặc từ các vụ hỏa hoạn công nghiệp có thể làm tối bầu trời và giảm tầm nhìn ở các khu dân cư lân cận.","audioKind":"ex2"}],"collocations":[{"en":"darken the sky","vi":"làm tối bầu trời"},{"en":"darken a room","vi":"làm tối phòng"},{"en":"someone''s face darkens","vi":"nét mặt ai đó sầm lại"}],"wordFamily":["dark (adj.)","darkness (n.)"],"synonyms":["dim"],"antonyms":["brighten","lighten"],"tipVi":"Cả động từ transitive và intransitive đều dùng được: mây làm trời tối, hoặc trời tự tối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_herb', 'en-b2-21', 'herb', '/ɝːb/', 'B2', 'thảo mộc; rau thơm; cây thuốc', 'n.', 'herbal (adj.), herbalist (n.)', NULL, 'Phát âm chữ h ở Anh-Anh, thường câm ở Anh-Mỹ; lưu ý mạo từ tương ứng a herb hoặc an herb.', 'She grows fresh herbs in pots beside the kitchen window.', NULL, 'Cô ấy trồng các loại rau thơm tươi trong chậu cạnh cửa sổ nhà bếp.', '{"wordId":"herb","ukIpa":"/hɜːb/","usIpa":"/ɝːb/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A plant used to flavour food or make medicines.","vi":"thảo mộc; rau thơm; cây thuốc"}],"examples":[{"en":"She grows fresh herbs in pots beside the kitchen window.","vi":"Cô ấy trồng các loại rau thơm tươi trong chậu cạnh cửa sổ nhà bếp.","audioKind":"ex"},{"en":"Growing herbs at home can encourage healthier cooking and reduce the need for packaged seasonings.","vi":"Trồng thảo mộc tại nhà có thể khuyến khích việc nấu ăn lành mạnh hơn và giảm nhu cầu sử dụng gia vị đóng gói sẵn.","audioKind":"ex2"}],"collocations":[{"en":"fresh herbs","vi":"thảo mộc tươi"},{"en":"dried herbs","vi":"thảo mộc khô"},{"en":"medicinal herbs","vi":"dược thảo"},{"en":"herb garden","vi":"vườn thảo mộc"}],"wordFamily":["herbal (adj.)","herbalist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Phát âm chữ h ở Anh-Anh, thường câm ở Anh-Mỹ; lưu ý mạo từ tương ứng a herb hoặc an herb.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reptile', 'en-b2-21', 'reptile', '/ˈreptaɪl/', 'B2', 'động vật bò sát', 'n.', 'reptilian (adj.)', NULL, 'Rắn, thằn lằn và rùa thuộc nhóm bò sát; ếch không thuộc nhóm này.', 'The reptile lay perfectly still on a warm rock.', NULL, 'Con vật bò sát nằm bất động trên một tảng đá ấm áp.', '{"wordId":"reptile","ukIpa":"/ˈreptaɪl/","usIpa":"/ˈreptaɪl/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"a cold-blooded animal with scaly skin, such as a snake","vi":"động vật bò sát"}],"examples":[{"en":"The reptile lay perfectly still on a warm rock.","vi":"Con vật bò sát nằm bất động trên một tảng đá ấm áp.","audioKind":"ex"},{"en":"Many reptile species depend on external heat sources to regulate their body temperature throughout the day.","vi":"Nhiều loài bò sát phụ thuộc vào các nguồn nhiệt bên ngoài để điều hòa thân nhiệt suốt cả ngày.","audioKind":"ex2"}],"collocations":[{"en":"reptile species","vi":"loài bò sát"},{"en":"reptile eggs","vi":"trứng bò sát"},{"en":"reptile enclosure","vi":"chuồng nuôi bò sát"}],"wordFamily":["reptilian (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Rắn, thằn lằn và rùa thuộc nhóm bò sát; ếch không thuộc nhóm này.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_downpour', 'en-b2-21', 'downpour', '/ˈdaʊnpɔːr/', 'B2', 'cơn mưa rào lớn; trận mưa xối xả', 'n.', NULL, 'Đồng nghĩa: deluge', 'Là danh từ đếm được: một trận mưa lớn dùng a downpour.', 'We sheltered in a doorway until the downpour finally stopped.', NULL, 'Chúng tôi trú mưa ở hiên cửa cho đến khi trận mưa rào cuối cùng cũng tạnh.', '{"wordId":"downpour","ukIpa":"/ˈdaʊnpɔː/","usIpa":"/ˈdaʊnpɔːr/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"a heavy fall of rain, often starting suddenly","vi":"cơn mưa rào lớn; trận mưa xối xả"}],"examples":[{"en":"We sheltered in a doorway until the downpour finally stopped.","vi":"Chúng tôi trú mưa ở hiên cửa cho đến khi trận mưa rào cuối cùng cũng tạnh.","audioKind":"ex"},{"en":"A sudden downpour can overwhelm urban drainage systems, particularly where concrete surfaces prevent water from soaking into soil.","vi":"Một trận mưa xối xả bất ngờ có thể làm hệ thống thoát nước đô thị quá tải, nhất là ở những nơi bề mặt bê tông ngăn nước thấm xuống đất.","audioKind":"ex2"}],"collocations":[{"en":"heavy downpour","vi":"trận mưa như trút nước"},{"en":"sudden downpour","vi":"cơn mưa rào bất chợt"},{"en":"torrential downpour","vi":"trận mưa xối xả"}],"wordFamily":[],"synonyms":["deluge"],"antonyms":[],"tipVi":"Là danh từ đếm được: một trận mưa lớn dùng a downpour.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tame', 'en-b2-21', 'tame', '/teɪm/', 'B2', 'thuần hóa; dễ gần; kiểm soát; nhạt nhẽo; tẻ nhạt', 'adj.', 'tamer (n.), tameness (n.)', 'Đồng nghĩa: docile, domesticated · Trái nghĩa: wild', 'Từ tame chỉ việc không sợ con người hoặc đã được thuần hóa, không có nghĩa là tự nhiên hoàn toàn vô hại.', 'The tame rabbit ate directly from my hand.', NULL, 'Chú thỏ thuần hóa đã ăn trực tiếp từ lòng bàn tay tôi.', '{"wordId":"tame","ukIpa":"/teɪm/","usIpa":"/teɪm/","cefr":"B2","topic":"nature","senses":[{"pos":"adj.","en":"Used to people and not wild or dangerous.","vi":"thuần hóa; dễ gần"},{"pos":"v.","en":"To train a wild animal or bring something under control.","vi":"thuần hóa; kiểm soát"},{"pos":"adj.","en":"Not exciting, adventurous, or impressive.","vi":"nhạt nhẽo; tẻ nhạt"}],"examples":[{"en":"The tame rabbit ate directly from my hand.","vi":"Chú thỏ thuần hóa đã ăn trực tiếp từ lòng bàn tay tôi.","audioKind":"ex"},{"en":"Even tame animals require careful handling, especially when young children are learning to interact with them.","vi":"Ngay cả những loài động vật đã được thuần hóa cũng cần được đối xử cẩn thận, đặc biệt khi trẻ nhỏ đang học cách tương tác với chúng.","audioKind":"ex2"}],"collocations":[{"en":"tame animals","vi":"động vật thuần hóa"},{"en":"tame a horse","vi":"thuần hóa một con ngựa"},{"en":"tame inflation","vi":"kiểm soát lạm phát"}],"wordFamily":["tamer (n.)","tameness (n.)"],"synonyms":["docile","domesticated"],"antonyms":["wild"],"tipVi":"Từ tame chỉ việc không sợ con người hoặc đã được thuần hóa, không có nghĩa là tự nhiên hoàn toàn vô hại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_burrow', 'en-b2-21', 'burrow', '/ˈbɜːroʊ/', 'B2', 'hang ổ; đường hầm (do động vật đào để trú ẩn); đào hang; chui rúc; luồn lách', 'n.', 'burrowing (adj.)', NULL, 'burrow chỉ việc đào hang hoặc địa đạo; đừng nhầm lẫn với borrow (vay, mượn).', 'A rabbit disappeared into its burrow beneath the hedge.', NULL, 'Một con chú thỏ đã biến mất vào cái hang của nó bên dưới bụi cây.', '{"wordId":"burrow","ukIpa":"/ˈbʌrəʊ/","usIpa":"/ˈbɜːroʊ/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A hole or tunnel dug by an animal for shelter","vi":"hang ổ; đường hầm (do động vật đào để trú ẩn)"},{"pos":"v.","en":"To dig a tunnel or push into something","vi":"đào hang; chui rúc; luồn lách"}],"examples":[{"en":"A rabbit disappeared into its burrow beneath the hedge.","vi":"Một con chú thỏ đã biến mất vào cái hang của nó bên dưới bụi cây.","audioKind":"ex"},{"en":"Animals that burrow underground can improve soil quality by allowing air and water to penetrate deeper layers.","vi":"Các loài động vật đào hang dưới lòng đất có thể cải thiện chất lượng đất bằng cách giúp không khí và nước thấm sâu hơn vào các tầng đất bên dưới.","audioKind":"ex2"}],"collocations":[{"en":"a rabbit burrow","vi":"hang thỏ"},{"en":"burrow into the ground","vi":"chui xuống đất"},{"en":"burrow under a blanket","vi":"chui vào trong chăn"}],"wordFamily":["burrowing (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"burrow chỉ việc đào hang hoặc địa đạo; đừng nhầm lẫn với borrow (vay, mượn).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gorilla', 'en-b2-21', 'gorilla', '/ɡəˈrɪlə/', 'B2', 'khỉ đột', 'n.', NULL, NULL, 'Từ "gorilla" chỉ khỉ đột; "chimpanzee" chỉ tinh tinh.', 'The young gorilla clung tightly to its mother''s back.', NULL, 'Chú khỉ đột con bám chặt vào lưng mẹ.', '{"wordId":"gorilla","ukIpa":"/ɡəˈrɪlə/","usIpa":"/ɡəˈrɪlə/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A large African ape with dark hair and powerful arms.","vi":"khỉ đột"}],"examples":[{"en":"The young gorilla clung tightly to its mother''s back.","vi":"Chú khỉ đột con bám chặt vào lưng mẹ.","audioKind":"ex"},{"en":"Protecting gorilla habitats also preserves tropical forests that support numerous other species and store carbon.","vi":"Việc bảo vệ môi trường sống của khỉ đột đồng thời gìn giữ các khu rừng nhiệt đới vốn là nơi sinh sống của vô số loài khác và đóng vai trò lưu trữ carbon.","audioKind":"ex2"}],"collocations":[{"en":"a mountain gorilla","vi":"khỉ đột núi"},{"en":"a silverback gorilla","vi":"khỉ đột lưng bạc"},{"en":"gorilla conservation","vi":"bảo tồn khỉ đột"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Từ \"gorilla\" chỉ khỉ đột; \"chimpanzee\" chỉ tinh tinh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_weed', 'en-b2-21', 'weed', '/wiːd/', 'B2', 'cỏ dại; làm cỏ; nhổ cỏ', 'n.', 'weeding (n.), weedy (adj.)', NULL, 'Cụm "weed out" có thể dùng theo nghĩa ẩn dụ là loại bỏ những người hoặc vật không phù hợp.', 'A stubborn weed has grown between the paving stones.', NULL, 'Một cây cỏ dại cứng đầu đã mọc lên giữa những viên đá lát đường.', '{"wordId":"weed","ukIpa":"/wiːd/","usIpa":"/wiːd/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A plant growing where it is not wanted.","vi":"cỏ dại"},{"pos":"v.","en":"To remove unwanted plants from an area.","vi":"làm cỏ; nhổ cỏ"}],"examples":[{"en":"A stubborn weed has grown between the paving stones.","vi":"Một cây cỏ dại cứng đầu đã mọc lên giữa những viên đá lát đường.","audioKind":"ex"},{"en":"Farmers can control weeds without chemicals by rotating crops and covering exposed soil with organic material.","vi":"Nông dân có thể kiểm soát cỏ dại mà không cần dùng hóa chất bằng cách luân canh cây trồng và phủ vật liệu hữu cơ lên đất trống.","audioKind":"ex2"}],"collocations":[{"en":"pull up weeds","vi":"nhổ cỏ dại"},{"en":"weed the garden","vi":"làm cỏ khu vườn"},{"en":"weed control","vi":"phòng trừ cỏ dại"},{"en":"weed out","vi":"loại bỏ; sàng lọc"}],"wordFamily":["weeding (n.)","weedy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm \"weed out\" có thể dùng theo nghĩa ẩn dụ là loại bỏ những người hoặc vật không phù hợp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sparrow', 'en-b2-21', 'sparrow', '/ˈspæroʊ/', 'B2', 'chim sẻ', 'n.', NULL, NULL, 'Là danh từ đếm được, dạng số nhiều thêm s trực tiếp; không dùng để chỉ chung tất cả các loài chim nhỏ.', 'A sparrow landed beside my cup on the balcony.', NULL, 'Một chú chim sẻ đã đậu ngay cạnh cốc nước của tôi trên ban công.', '{"wordId":"sparrow","ukIpa":"/ˈspærəʊ/","usIpa":"/ˈspæroʊ/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A small brownish bird often found near people''s homes","vi":"chim sẻ"}],"examples":[{"en":"A sparrow landed beside my cup on the balcony.","vi":"Một chú chim sẻ đã đậu ngay cạnh cốc nước của tôi trên ban công.","audioKind":"ex"},{"en":"Urban gardens provide food and shelter for sparrows, helping maintain bird populations in densely populated areas.","vi":"Khu vườn đô thị cung cấp thức ăn và nơi trú ẩn cho chim sẻ, giúp duy trì số lượng loài chim này ở các khu vực đông dân cư.","audioKind":"ex2"}],"collocations":[{"en":"a flock of sparrows","vi":"một đàn chim sẻ"},{"en":"house sparrow","vi":"chim sẻ nhà"},{"en":"tree sparrow","vi":"chim sẻ cây"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ đếm được, dạng số nhiều thêm s trực tiếp; không dùng để chỉ chung tất cả các loài chim nhỏ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bud', 'en-b2-21', 'bud', '/bʌd/', 'B2', 'chồi; nụ; hoa chúm chím; đâm chồi; nảy lộc', 'n.', 'budding (adj.)', NULL, 'Động từ có dạng quá khứ là "budded", hiện phân từ là "budding", gấp đôi chữ "d".', 'A tiny green bud appeared on the bare branch.', NULL, 'Một nụ xanh nhỏ xíu đã mọc lên trên cành cây trơ trụi.', '{"wordId":"bud","ukIpa":"/bʌd/","usIpa":"/bʌd/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"a small growth that develops into a leaf or flower","vi":"chồi; nụ; hoa chúm chím"},{"pos":"v.","en":"to produce new buds","vi":"đâm chồi; nảy lộc"}],"examples":[{"en":"A tiny green bud appeared on the bare branch.","vi":"Một nụ xanh nhỏ xíu đã mọc lên trên cành cây trơ trụi.","audioKind":"ex"},{"en":"Warmer spring temperatures can cause trees to bud earlier, leaving new growth vulnerable to sudden frost.","vi":"Nhiệt độ mùa xuân ấm hơn có thể khiến cây cối đâm chồi sớm hơn, khiến chồi non dễ bị tổn thương trước những đợt sương giá bất chợt.","audioKind":"ex2"}],"collocations":[{"en":"a flower bud","vi":"nụ hoa"},{"en":"a leaf bud","vi":"chồi lá"},{"en":"in bud","vi":"chớm nở; đang độ chúm chím"},{"en":"nip something in the bud","vi":"bóp chết từ trong trứng nước"}],"wordFamily":["budding (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ có dạng quá khứ là \"budded\", hiện phân từ là \"budding\", gấp đôi chữ \"d\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shady', 'en-b2-21', 'shady', '/ˈʃeɪdi/', 'B2', 'có bóng râm; mát mẻ; mờ ám; đáng ngờ', 'adj.', 'shade (n.), shade (v.), shadiness (n.)', 'Đồng nghĩa: shaded, suspicious · Trái nghĩa: sunny', 'Shady chỉ bóng râm hoặc sự đáng ngờ; shadowy thường chỉ sự tối tăm, mờ ảo.', 'We found a shady spot beneath the old oak.', NULL, 'Chúng tôi tìm thấy một góc râm mát dưới tán cây sồi cổ thụ.', '{"wordId":"shady","ukIpa":"/ˈʃeɪdi/","usIpa":"/ˈʃeɪdi/","cefr":"B2","topic":"nature","senses":[{"pos":"adj.","en":"Protected from direct sunlight by trees or other objects.","vi":"có bóng râm; mát mẻ"},{"pos":"adj.","en":"Seeming dishonest or possibly involved in illegal activities.","vi":"mờ ám; đáng ngờ"}],"examples":[{"en":"We found a shady spot beneath the old oak.","vi":"Chúng tôi tìm thấy một góc râm mát dưới tán cây sồi cổ thụ.","audioKind":"ex"},{"en":"Planting trees along busy streets creates shady spaces that encourage walking during hot weather.","vi":"Việc trồng cây xanh dọc theo các tuyến đường nhộn nhịp tạo ra những khoảng không gian râm mát, khuyến khích mọi người đi bộ trong thời tiết oi bức.","audioKind":"ex2"}],"collocations":[{"en":"shady spot","vi":"chỗ râm mát"},{"en":"shady dealings","vi":"giao dịch mờ ám"},{"en":"shady character","vi":"nhân vật đáng ngờ"}],"wordFamily":["shade (n.)","shade (v.)","shadiness (n.)"],"synonyms":["shaded","suspicious"],"antonyms":["sunny"],"tipVi":"Shady chỉ bóng râm hoặc sự đáng ngờ; shadowy thường chỉ sự tối tăm, mờ ảo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_summit', 'en-b2-21', 'summit', '/ˈsʌmɪt/', 'B2', 'đỉnh núi; chỏm núi; hội nghị thượng đỉnh; cuộc gặp gỡ cấp cao', 'n.', NULL, 'Đồng nghĩa: peak, mountaintop', 'Nói về đỉnh núi thường dùng cụm the summit of; nói về hội nghị thượng đỉnh dùng a summit.', 'We reached the snowy summit just before sunrise.', NULL, 'Chúng tôi đã lên đến đỉnh núi phủ đầy tuyết ngay trước khi mặt trời mọc.', '{"wordId":"summit","ukIpa":"/ˈsʌmɪt/","usIpa":"/ˈsʌmɪt/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"The highest point of a mountain.","vi":"đỉnh núi; chỏm núi"},{"pos":"n.","en":"A meeting between national leaders or other senior officials.","vi":"hội nghị thượng đỉnh; cuộc gặp gỡ cấp cao"}],"examples":[{"en":"We reached the snowy summit just before sunrise.","vi":"Chúng tôi đã lên đến đỉnh núi phủ đầy tuyết ngay trước khi mặt trời mọc.","audioKind":"ex"},{"en":"At the climate summit, national leaders discussed practical measures to reduce emissions and support vulnerable communities.","vi":"Tại hội nghị thượng đỉnh về khí hậu, các nhà lãnh đạo quốc gia đã thảo luận về các biện pháp thực tế nhằm giảm phát thải và hỗ trợ các cộng đồng dễ bị tổn thương.","audioKind":"ex2"}],"collocations":[{"en":"reach the summit","vi":"chạm đỉnh núi"},{"en":"a climate summit","vi":"hội nghị thượng đỉnh về khí hậu"},{"en":"hold a summit","vi":"tổ chức hội nghị thượng đỉnh"},{"en":"summit talks","vi":"đàm phán cấp cao"}],"wordFamily":[],"synonyms":["peak","mountaintop"],"antonyms":[],"tipVi":"Nói về đỉnh núi thường dùng cụm the summit of; nói về hội nghị thượng đỉnh dùng a summit.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mediterranean', 'en-b2-21', 'Mediterranean', '/ˌmedɪtəˈreɪniən/', 'B2', 'Địa Trung Hải; thuộc Địa Trung Hải', 'n.', NULL, NULL, 'Khi chỉ vùng biển thường dùng the Mediterranean và viết hoa chữ cái đầu.', 'We sailed across the Mediterranean on a small boat.', NULL, 'Chúng tôi chèo thuyền vượt qua Địa Trung Hải trên một chiếc thuyền nhỏ.', '{"wordId":"mediterranean","ukIpa":"/ˌmedɪtəˈreɪniən/","usIpa":"/ˌmedɪtəˈreɪniən/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"The sea between southern Europe, northern Africa, and western Asia.","vi":"Địa Trung Hải"},{"pos":"adj.","en":"Relating to the Mediterranean Sea or the countries around it.","vi":"thuộc Địa Trung Hải"}],"examples":[{"en":"We sailed across the Mediterranean on a small boat.","vi":"Chúng tôi chèo thuyền vượt qua Địa Trung Hải trên một chiếc thuyền nhỏ.","audioKind":"ex"},{"en":"The Mediterranean region faces increasing water shortages as rising temperatures place pressure on agriculture and tourism.","vi":"Khu vực Địa Trung Hải phải đối mặt với tình trạng thiếu nước ngày càng nghiêm trọng khi nhiệt độ tăng cao gây áp lực lên ngành nông nghiệp và du lịch.","audioKind":"ex2"}],"collocations":[{"en":"the Mediterranean Sea","vi":"Biển Địa Trung Hải"},{"en":"Mediterranean climate","vi":"khí hậu Địa Trung Hải"},{"en":"Mediterranean diet","vi":"chế độ ăn Địa Trung Hải"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ vùng biển thường dùng the Mediterranean và viết hoa chữ cái đầu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fin', 'en-b2-21', 'fin', '/fɪn/', 'B2', 'vây cá; bộ phận hình vây; chân vịt (dùng khi bơi lặn)', 'n.', 'finned (adj.)', NULL, 'Khi chỉ chân vịt lặn, thường dùng dạng số nhiều fins.', 'We spotted a shark''s fin just above the water.', NULL, 'Chúng tôi phát hiện một chiếc vây cá mập ngay trên mặt nước.', '{"wordId":"fin","ukIpa":"/fɪn/","usIpa":"/fɪn/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"a flat body part or structure aiding movement or stability","vi":"vây cá; bộ phận hình vây"},{"pos":"n.","en":"a flat rubber covering worn on a foot for swimming","vi":"chân vịt (dùng khi bơi lặn)"}],"examples":[{"en":"We spotted a shark''s fin just above the water.","vi":"Chúng tôi phát hiện một chiếc vây cá mập ngay trên mặt nước.","audioKind":"ex"},{"en":"Changes in fin shape can affect how efficiently fish move through different aquatic environments.","vi":"Sự thay đổi về hình dáng vây có thể ảnh hưởng đến hiệu quả di chuyển của cá qua các môi trường nước khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"dorsal fin","vi":"vây lưng"},{"en":"tail fin","vi":"vây đuôi"},{"en":"shark fin","vi":"vây cá mập"},{"en":"diving fins","vi":"chân vịt lặn"}],"wordFamily":["finned (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ chân vịt lặn, thường dùng dạng số nhiều fins.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_blossom', 'en-b2-21', 'blossom', '/ˈblɑːsəm/', 'B2', 'hoa; cụm hoa trên cây hoặc bụi cây; ra hoa; nở hoa; phát triển rực rỡ; trở nên tự tin hơn', 'n.', 'blossoming (adj.)', 'Đồng nghĩa: bloom, flower · Trái nghĩa: wither', 'Thường chỉ hoa của cây; blossom into có thể dùng theo nghĩa ẩn dụ là trưởng thành thành.', 'Pink blossom covered the cherry tree outside our kitchen.', NULL, 'Cây anh đào bên ngoài nhà bếp của chúng tôi ngập tràn những bông hoa màu hồng.', '{"wordId":"blossom","ukIpa":"/ˈblɒsəm/","usIpa":"/ˈblɑːsəm/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"a flower or mass of flowers on a tree or bush","vi":"hoa; cụm hoa trên cây hoặc bụi cây"},{"pos":"v.","en":"to produce flowers","vi":"ra hoa; nở hoa"},{"pos":"v.","en":"to develop successfully or become more confident","vi":"phát triển rực rỡ; trở nên tự tin hơn"}],"examples":[{"en":"Pink blossom covered the cherry tree outside our kitchen.","vi":"Cây anh đào bên ngoài nhà bếp của chúng tôi ngập tràn những bông hoa màu hồng.","audioKind":"ex"},{"en":"Creative talent can blossom when schools provide supportive teaching and regular opportunities for artistic expression.","vi":"Tài năng sáng tạo có thể nở rộ khi các nhà trường cung cấp môi trường giảng dạy hỗ trợ và cơ hội thường xuyên để thể hiện nghệ thuật.","audioKind":"ex2"}],"collocations":[{"en":"cherry blossom","vi":"hoa anh đào"},{"en":"in blossom","vi":"đang nở hoa"},{"en":"blossom into","vi":"phát triển thành; trở thành"}],"wordFamily":["blossoming (adj.)"],"synonyms":["bloom","flower"],"antonyms":["wither"],"tipVi":"Thường chỉ hoa của cây; blossom into có thể dùng theo nghĩa ẩn dụ là trưởng thành thành.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_paw', 'en-b2-21', 'paw', '/pɔː/', 'B2', 'bàn chân (của thú vật như chó, mèo); dùng vuốt cào; bới bằng chân', 'n.', NULL, NULL, '"Paw" chỉ cả bàn chân của thú vật; "claw" chỉ móng vuốt nhọn ở đầu ngón.', 'The puppy rested one muddy paw on my knee.', NULL, 'Chú cún con đặt một chiếc chân dính đầy bùn lên đầu gối của tôi.', '{"wordId":"paw","ukIpa":"/pɔː/","usIpa":"/pɔː/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"the foot of an animal such as a cat or dog","vi":"bàn chân (của thú vật như chó, mèo)"},{"pos":"v.","en":"to scratch or touch something repeatedly with a paw or hoof","vi":"dùng vuốt cào; bới bằng chân"}],"examples":[{"en":"The puppy rested one muddy paw on my knee.","vi":"Chú cún con đặt một chiếc chân dính đầy bùn lên đầu gối của tôi.","audioKind":"ex"},{"en":"Urban wildlife may suffer paw injuries from broken glass and other waste left in public spaces.","vi":"Động vật hoang dã đô thị có thể bị thương ở chân do các mảnh thủy tinh vỡ và rác thải khác bỏ lại ở những nơi công cộng.","audioKind":"ex2"}],"collocations":[{"en":"front paw","vi":"chân trước"},{"en":"paw print","vi":"dấu chân thú"},{"en":"paw at the door","vi":"cào cửa bằng chân"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"\"Paw\" chỉ cả bàn chân của thú vật; \"claw\" chỉ móng vuốt nhọn ở đầu ngón.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_jellyfish', 'en-b2-21', 'jellyfish', '/ˈdʒelifɪʃ/', 'B2', 'con sứa (động vật biển thân mềm có xúc tu gây ngứa)', 'n.', NULL, NULL, 'Dạng số nhiều thường vẫn giữ nguyên là jellyfish; đây không phải là loài cá thực sự.', 'A translucent jellyfish drifted past our boat this morning.', NULL, 'Một con sứa trong suốt trôi dạt qua thuyền của chúng tôi vào sáng nay.', '{"wordId":"jellyfish","ukIpa":"/ˈdʒelifɪʃ/","usIpa":"/ˈdʒelifɪʃ/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"a soft sea animal with hanging tentacles that can sting","vi":"con sứa (động vật biển thân mềm có xúc tu gây ngứa)"}],"examples":[{"en":"A translucent jellyfish drifted past our boat this morning.","vi":"Một con sứa trong suốt trôi dạt qua thuyền của chúng tôi vào sáng nay.","audioKind":"ex"},{"en":"Rising ocean temperatures may encourage jellyfish populations to grow, potentially disrupting marine ecosystems and coastal tourism.","vi":"Nhiệt độ đại dương tăng cao có thể thúc đẩy sự bùng nổ số lượng sứa, có khả năng làm gián đoạn hệ sinh thái biển và du lịch ven biển.","audioKind":"ex2"}],"collocations":[{"en":"a jellyfish sting","vi":"vết sứa đốt"},{"en":"a swarm of jellyfish","vi":"một đàn sứa"},{"en":"jellyfish populations","vi":"quần thể sứa"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều thường vẫn giữ nguyên là jellyfish; đây không phải là loài cá thực sự.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_howl', 'en-b2-21', 'howl', '/haʊl/', 'B2', 'hú; gào thét; rú lên; tiếng hú; tiếng gào thét; tiếng kêu la', 'v.', 'howling (adj.)', 'Đồng nghĩa: wail', 'Được dùng cho cả tiếng kêu dài của động vật, tiếng gió thổi hoặc phản ứng mạnh mẽ của con người.', 'Our dog howled when the ambulance passed the house.', NULL, 'Con chó nhà chúng tôi đã hú lên khi chiếc xe cứu thương chạy qua nhà.', '{"wordId":"howl","ukIpa":"/haʊl/","usIpa":"/haʊl/","cefr":"B2","topic":"nature","senses":[{"pos":"v.","en":"Make a long, loud cry or a similar rushing sound.","vi":"hú; gào thét; rú lên"},{"pos":"n.","en":"A long, loud cry expressing pain, anger, or another strong feeling.","vi":"tiếng hú; tiếng gào thét; tiếng kêu la"}],"examples":[{"en":"Our dog howled when the ambulance passed the house.","vi":"Con chó nhà chúng tôi đã hú lên khi chiếc xe cứu thương chạy qua nhà.","audioKind":"ex"},{"en":"Residents complained that wind howled through poorly insulated windows, making their homes uncomfortable during winter.","vi":"Cư dân phàn nàn rằng gió rít qua những khung cửa sổ cách nhiệt kém, khiến cho ngôi nhà của họ trở nên kém thoải mái trong mùa đông.","audioKind":"ex2"}],"collocations":[{"en":"howl at the moon","vi":"hú dưới trăng"},{"en":"howl with laughter","vi":"cười phá lên"},{"en":"howls of protest","vi":"những tiếng phản đối giận dữ"},{"en":"the wind howls","vi":"gió rít"}],"wordFamily":["howling (adj.)"],"synonyms":["wail"],"antonyms":[],"tipVi":"Được dùng cho cả tiếng kêu dài của động vật, tiếng gió thổi hoặc phản ứng mạnh mẽ của con người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_volcanic', 'en-b2-21', 'volcanic', '/vɑːlˈkænɪk/', 'B2', 'thuộc về núi lửa; do núi lửa tạo ra; bùng nổ dữ dội; mãnh liệt', 'adj.', 'volcano (n.), volcanism (n.)', NULL, 'Thường dùng làm tính từ; cụm từ ''volcanic rock'' dịch là đá núi lửa.', 'We walked across dark volcanic rock near the coast.', NULL, 'Chúng tôi bước đi trên lớp đá núi lửa sẫm màu gần bờ biển.', '{"wordId":"volcanic","ukIpa":"/vɒlˈkænɪk/","usIpa":"/vɑːlˈkænɪk/","cefr":"B2","topic":"nature","senses":[{"pos":"adj.","en":"Related to volcanoes or produced by their activity.","vi":"thuộc về núi lửa; do núi lửa tạo ra"},{"pos":"adj.","en":"Sudden and extremely powerful, especially when describing anger.","vi":"bùng nổ dữ dội; mãnh liệt"}],"examples":[{"en":"We walked across dark volcanic rock near the coast.","vi":"Chúng tôi bước đi trên lớp đá núi lửa sẫm màu gần bờ biển.","audioKind":"ex"},{"en":"Although volcanic eruptions threaten nearby settlements, the resulting soils can support highly productive agriculture over time.","vi":"Mặc dù các đợt phun trào núi lửa đe dọa các khu dân cư gần đó, nhưng lớp đất tạo ra sau đó có thể hỗ trợ nền nông nghiệp có năng suất cao theo thời gian.","audioKind":"ex2"}],"collocations":[{"en":"volcanic eruption","vi":"sự phun trào núi lửa"},{"en":"volcanic ash","vi":"tro núi lửa"},{"en":"volcanic activity","vi":"hoạt động núi lửa"},{"en":"volcanic rock","vi":"đá núi lửa"}],"wordFamily":["volcano (n.)","volcanism (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng làm tính từ; cụm từ ''volcanic rock'' dịch là đá núi lửa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hedgehog', 'en-b2-21', 'hedgehog', '/ˈhedʒhɑːɡ/', 'B2', 'nhím gai nhỏ (nhím ăn sâu bọ)', 'n.', NULL, NULL, 'hedgehog là nhím gai nhỏ (ăn sâu bọ); porcupine là nhím bờm/nhím lớn (gặm nhấm), đây là hai loài khác nhau.', 'A hedgehog shuffled through the leaves beside our fence.', NULL, 'Một chú nhím lạch bạch đi qua đám lá rụng bên hàng rào nhà chúng tôi.', '{"wordId":"hedgehog","ukIpa":"/ˈhedʒhɒɡ/","usIpa":"/ˈhedʒhɑːɡ/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A small mammal with spines that curls into a ball.","vi":"nhím gai nhỏ (nhím ăn sâu bọ)"}],"examples":[{"en":"A hedgehog shuffled through the leaves beside our fence.","vi":"Một chú nhím lạch bạch đi qua đám lá rụng bên hàng rào nhà chúng tôi.","audioKind":"ex"},{"en":"Leaving small gaps beneath garden fences allows hedgehogs to move safely between feeding areas.","vi":"Để những khe hở nhỏ dưới hàng rào vườn giúp nhím di chuyển an toàn giữa các khu vực kiếm ăn.","audioKind":"ex2"}],"collocations":[{"en":"a hedgehog''s spines","vi":"gai nhím"},{"en":"hedgehog habitat","vi":"môi trường sống của nhím"},{"en":"a baby hedgehog","vi":"nhím con"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"hedgehog là nhím gai nhỏ (ăn sâu bọ); porcupine là nhím bờm/nhím lớn (gặm nhấm), đây là hai loài khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sparkle', 'en-b2-21', 'sparkle', '/ˈspɑːrkəl/', 'B2', 'lấp lánh; chiếu sáng rực rỡ; ánh lấp lánh; sự sôi nổi, sự nhiệt huyết', 'v.', 'sparkling (adj.)', 'Đồng nghĩa: glitter, twinkle', 'sparkle nhấn mạnh điểm sáng lấp lánh; shine chỉ sự phát sáng nói chung.', 'The tiny crystals sparkle whenever sunlight enters the room.', NULL, 'Những viên tinh thể nhỏ bé lấp lánh mỗi khi ánh nắng chiếu vào phòng.', '{"wordId":"sparkle","ukIpa":"/ˈspɑːkəl/","usIpa":"/ˈspɑːrkəl/","cefr":"B2","topic":"nature","senses":[{"pos":"v.","en":"to shine with small, bright flashes of light","vi":"lấp lánh; chiếu sáng rực rỡ"},{"pos":"n.","en":"bright flashes of light, or a lively, exciting quality","vi":"ánh lấp lánh; sự sôi nổi, sự nhiệt huyết"}],"examples":[{"en":"The tiny crystals sparkle whenever sunlight enters the room.","vi":"Những viên tinh thể nhỏ bé lấp lánh mỗi khi ánh nắng chiếu vào phòng.","audioKind":"ex"},{"en":"Although the river sparkles in the sunlight, regular testing is necessary to assess its water quality.","vi":"Mặc dù dòng sông lấp lánh dưới ánh mặt trời, việc kiểm tra định kỳ vẫn rất cần thiết để đánh giá chất lượng nước.","audioKind":"ex2"}],"collocations":[{"en":"sparkle in the sunlight","vi":"lấp lánh dưới ánh mặt trời"},{"en":"eyes sparkle","vi":"mắt lấp lánh"},{"en":"add sparkle to","vi":"thêm sức sống cho"}],"wordFamily":["sparkling (adj.)"],"synonyms":["glitter","twinkle"],"antonyms":[],"tipVi":"sparkle nhấn mạnh điểm sáng lấp lánh; shine chỉ sự phát sáng nói chung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dense', 'en-b2-21', 'dense', '/dens/', 'B2', 'dày đặc; đông đúc, rậm rạp; khó hiểu; phức tạp; chậm hiểu; đần độn', 'adj.', 'density (n.), densely (adv.)', 'Đồng nghĩa: thick, closely packed · Trái nghĩa: sparse', 'Dùng để chỉ người chậm hiểu có thể mang hàm ý xúc phạm; trạng từ chỉ mật độ dùng densely.', 'Dense fog hid the bridge from our kitchen window.', NULL, 'Sương mù dày đặc che khuất cây cầu nhìn từ cửa sổ nhà bếp của chúng tôi.', '{"wordId":"dense","ukIpa":"/dens/","usIpa":"/dens/","cefr":"B2","topic":"nature","senses":[{"pos":"adj.","en":"Containing many things packed closely together","vi":"dày đặc; đông đúc, rậm rạp"},{"pos":"adj.","en":"Difficult to understand because information is tightly packed","vi":"khó hiểu; phức tạp"},{"pos":"adj.","en":"Slow to understand things","vi":"chậm hiểu; đần độn"}],"examples":[{"en":"Dense fog hid the bridge from our kitchen window.","vi":"Sương mù dày đặc che khuất cây cầu nhìn từ cửa sổ nhà bếp của chúng tôi.","audioKind":"ex"},{"en":"Dense urban development can reduce travel distances, but it requires careful planning to preserve green spaces.","vi":"Sự phát triển đô thị với mật độ cao có thể rút ngắn khoảng cách di chuyển, nhưng đòi hỏi phải lập kế hoạch cẩn thận để bảo tồn các không gian xanh.","audioKind":"ex2"}],"collocations":[{"en":"dense fog","vi":"sương mù dày đặc"},{"en":"dense forest","vi":"rừng rậm"},{"en":"dense population","vi":"mật độ dân số cao"},{"en":"dense prose","vi":"bài văn khó hiểu"}],"wordFamily":["density (n.)","densely (adv.)"],"synonyms":["thick","closely packed"],"antonyms":["sparse"],"tipVi":"Dùng để chỉ người chậm hiểu có thể mang hàm ý xúc phạm; trạng từ chỉ mật độ dùng densely.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hatch', 'en-b2-21', 'hatch', '/hætʃ/', 'B2', 'nở; ấp trứng; cửa sập; ô cửa nhỏ; âm mưu; lên kế hoạch bí mật', 'v.', 'hatching (n.), hatchling (n.), hatchery (n.)', NULL, 'Khi là động từ mang nghĩa nở/ấp trứng; danh từ thường chỉ cửa sập hoặc khe hở nhỏ.', 'We watched three chicks hatch on the farm yesterday.', NULL, 'Hôm qua chúng tôi đã chứng kiến ba con gà con nở ở trang trại.', '{"wordId":"hatch","ukIpa":"/hætʃ/","usIpa":"/hætʃ/","cefr":"B2","topic":"nature","senses":[{"pos":"v.","en":"to emerge from an egg, or cause this to happen","vi":"nở; ấp trứng"},{"pos":"n.","en":"an opening in a floor, ceiling, or wall","vi":"cửa sập; ô cửa nhỏ"},{"pos":"v.","en":"to develop a plan, often secretly","vi":"âm mưu; lên kế hoạch bí mật"}],"examples":[{"en":"We watched three chicks hatch on the farm yesterday.","vi":"Hôm qua chúng tôi đã chứng kiến ba con gà con nở ở trang trại.","audioKind":"ex"},{"en":"Rising temperatures can affect when turtle eggs hatch, potentially reducing the survival chances of young turtles.","vi":"Nhiệt độ tăng cao có thể ảnh hưởng đến thời điểm trứng rùa nở, có khả năng làm giảm cơ hội sống sót của rùa con.","audioKind":"ex2"}],"collocations":[{"en":"hatch an egg","vi":"ấp trứng"},{"en":"hatch a plan","vi":"lên kế hoạch bí mật"},{"en":"escape hatch","vi":"cửa thoát hiểm"}],"wordFamily":["hatching (n.)","hatchling (n.)","hatchery (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi là động từ mang nghĩa nở/ấp trứng; danh từ thường chỉ cửa sập hoặc khe hở nhỏ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_21_1', 'en-b2-21', 'Cách dùng “prey” (n.) — con mồi (bị động vật khác săn đuổi và ăn thịt)', 'birds of prey  ·  prey on small animals  ·  fall prey to fraud', 'Danh từ prey thường là danh từ không đếm được; động từ thường đi với on (prey on); tránh nhầm lẫn với từ pray (cầu nguyện).', 'Trái nghĩa: predator', '[{"hanzi":"The owl watched its prey from a low branch.","pinyin":"","meaning":"Con cú chăm chú quan sát con mồi từ một cành cây thấp."},{"hanzi":"When natural prey becomes scarce, some predators move closer to farms in search of food.","pinyin":"","meaning":"Khi con mồi tự nhiên trở nên khan hiếm, một số loài săn mồi sẽ di chuyển đến gần các trang trại hơn để tìm kiếm thức ăn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_21_2', 'en-b2-21', 'Cách dùng “hedgehog” (n.) — nhím gai nhỏ (nhím ăn sâu bọ)', 'a hedgehog''s spines  ·  hedgehog habitat  ·  a baby hedgehog', 'hedgehog là nhím gai nhỏ (ăn sâu bọ); porcupine là nhím bờm/nhím lớn (gặm nhấm), đây là hai loài khác nhau.', NULL, '[{"hanzi":"A hedgehog shuffled through the leaves beside our fence.","pinyin":"","meaning":"Một chú nhím lạch bạch đi qua đám lá rụng bên hàng rào nhà chúng tôi."},{"hanzi":"Leaving small gaps beneath garden fences allows hedgehogs to move safely between feeding areas.","pinyin":"","meaning":"Để những khe hở nhỏ dưới hàng rào vườn giúp nhím di chuyển an toàn giữa các khu vực kiếm ăn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_21_3', 'en-b2-21', 'Cách dùng “tame” (adj.) — thuần hóa; dễ gần', 'tame animals  ·  tame a horse  ·  tame inflation', 'Từ tame chỉ việc không sợ con người hoặc đã được thuần hóa, không có nghĩa là tự nhiên hoàn toàn vô hại.', 'Họ từ (Word Family): tamer (n.), tameness (n.) | Đồng nghĩa: docile, domesticated · Trái nghĩa: wild', '[{"hanzi":"The tame rabbit ate directly from my hand.","pinyin":"","meaning":"Chú thỏ thuần hóa đã ăn trực tiếp từ lòng bàn tay tôi."},{"hanzi":"Even tame animals require careful handling, especially when young children are learning to interact with them.","pinyin":"","meaning":"Ngay cả những loài động vật đã được thuần hóa cũng cần được đối xử cẩn thận, đặc biệt khi trẻ nhỏ đang học cách tương tác với chúng."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_21_4', 'en-b2-21', 'Cách dùng “sparrow” (n.) — chim sẻ', 'a flock of sparrows  ·  house sparrow  ·  tree sparrow', 'Là danh từ đếm được, dạng số nhiều thêm s trực tiếp; không dùng để chỉ chung tất cả các loài chim nhỏ.', NULL, '[{"hanzi":"A sparrow landed beside my cup on the balcony.","pinyin":"","meaning":"Một chú chim sẻ đã đậu ngay cạnh cốc nước của tôi trên ban công."},{"hanzi":"Urban gardens provide food and shelter for sparrows, helping maintain bird populations in densely populated areas.","pinyin":"","meaning":"Khu vườn đô thị cung cấp thức ăn và nơi trú ẩn cho chim sẻ, giúp duy trì số lượng loài chim này ở các khu vực đông dân cư."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_21_1', 'en-b2-21', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_21_1_1', 'ten_b2_21_1', 'waving', 'We rested beneath the gently waving branches of a willow.', 'We rested beneath the gently waving branches of a willow.', '/ˈweɪvɪŋ/', 'Chúng tôi nghỉ ngơi dưới những tán lá liễu đang khẽ đu đưa trong gió.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_21_1_2', 'ten_b2_21_1', 'walnut', 'She cracked a walnut and shared the kernel with me.', 'She cracked a walnut and shared the kernel with me.', '/ˈwɔːlnʌt/', 'Cô ấy đập một quả óc chó và chia phần nhân cho tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_21_1_3', 'ten_b2_21_1', 'prey', 'The owl watched its prey from a low branch.', 'The owl watched its prey from a low branch.', '/preɪ/', 'Con cú chăm chú quan sát con mồi từ một cành cây thấp.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_21_1_4', 'ten_b2_21_1', 'moist', 'Keep the soil moist until the first leaves appear.', 'Keep the soil moist until the first leaves appear.', '/mɔɪst/', 'Hãy giữ cho đất ẩm cho đến khi những chiếc lá đầu tiên nhú lên.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_21_1_5', 'ten_b2_21_1', 'darken', 'Heavy clouds darkened the sky before we reached home.', 'Heavy clouds darkened the sky before we reached home.', '/ˈdɑːrkən/', 'Những đám mây dày đặc làm bầu trời tối sầm lại trước khi chúng tôi về đến nhà.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_21_1_6', 'ten_b2_21_1', 'herb', 'She grows fresh herbs in pots beside the kitchen window.', 'She grows fresh herbs in pots beside the kitchen window.', '/ɝːb/', 'Cô ấy trồng các loại rau thơm tươi trong chậu cạnh cửa sổ nhà bếp.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_21_1_7', 'ten_b2_21_1', 'reptile', 'The reptile lay perfectly still on a warm rock.', 'The reptile lay perfectly still on a warm rock.', '/ˈreptaɪl/', 'Con vật bò sát nằm bất động trên một tảng đá ấm áp.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_21_1_8', 'ten_b2_21_1', 'downpour', 'We sheltered in a doorway until the downpour finally stopped.', 'We sheltered in a doorway until the downpour finally stopped.', '/ˈdaʊnpɔːr/', 'Chúng tôi trú mưa ở hiên cửa cho đến khi trận mưa rào cuối cùng cũng tạnh.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_21_1_1', 'en-b2-21', 'ten_b2_21_1', 'listening', 'listening', 'We rested beneath the gently waving branches of a willow.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi nghỉ ngơi dưới những tán lá liễu đang khẽ đu đưa trong gió.","Cô ấy trồng các loại rau thơm tươi trong chậu cạnh cửa sổ nhà bếp.","Một chú nhím lạch bạch đi qua đám lá rụng bên hàng rào nhà chúng tôi.","Chúng tôi bước đi trên lớp đá núi lửa sẫm màu gần bờ biển."]'::jsonb, 0, 'We rested beneath the gently waving branches of a willow. → Chúng tôi nghỉ ngơi dưới những tán lá liễu đang khẽ đu đưa trong gió.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_21_1_2', 'en-b2-21', 'ten_b2_21_1', 'listening', 'listening', 'She cracked a walnut and shared the kernel with me.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy đập một quả óc chó và chia phần nhân cho tôi.","Con vật bò sát nằm bất động trên một tảng đá ấm áp.","Chúng tôi đã lên đến đỉnh núi phủ đầy tuyết ngay trước khi mặt trời mọc.","Con chó nhà chúng tôi đã hú lên khi chiếc xe cứu thương chạy qua nhà."]'::jsonb, 0, 'She cracked a walnut and shared the kernel with me. → Cô ấy đập một quả óc chó và chia phần nhân cho tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_21_1_3', 'en-b2-21', 'ten_b2_21_1', 'listening', 'listening', 'The owl watched its prey from a low branch.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Con cú chăm chú quan sát con mồi từ một cành cây thấp.","Cây anh đào bên ngoài nhà bếp của chúng tôi ngập tràn những bông hoa màu hồng.","Chúng tôi chèo thuyền vượt qua Địa Trung Hải trên một chiếc thuyền nhỏ.","Chúng tôi phát hiện một chiếc vây cá mập ngay trên mặt nước."]'::jsonb, 0, 'The owl watched its prey from a low branch. → Con cú chăm chú quan sát con mồi từ một cành cây thấp.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_21_2', 'en-b2-21', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_21_2_1', 'ten_b2_21_2', 'waving', 'The waving grasses along restored riverbanks provide valuable habitats for wildlife and help protect soil from erosion.', 'The waving grasses along restored riverbanks provide valuable habitats for wildlife and help protect soil from erosion.', '/ˈweɪvɪŋ/', 'Những thảm cỏ lay động ven các bờ sông được phục hồi mang lại môi trường sống quý giá cho động vật hoang dã và giúp bảo vệ đất khỏi bị xói mòn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_21_2_2', 'ten_b2_21_2', 'walnut', 'Growing walnut trees can provide farmers with additional income while increasing tree cover in rural areas.', 'Growing walnut trees can provide farmers with additional income while increasing tree cover in rural areas.', '/ˈwɔːlnʌt/', 'Việc trồng cây óc chó có thể mang lại thêm thu nhập cho nông dân đồng thời tăng độ che phủ của cây xanh ở các vùng nông thôn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_21_2_3', 'ten_b2_21_2', 'prey', 'When natural prey becomes scarce, some predators move closer to farms in search of food.', 'When natural prey becomes scarce, some predators move closer to farms in search of food.', '/preɪ/', 'Khi con mồi tự nhiên trở nên khan hiếm, một số loài săn mồi sẽ di chuyển đến gần các trang trại hơn để tìm kiếm thức ăn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_21_2_4', 'ten_b2_21_2', 'moist', 'A layer of fallen leaves helps keep soil moist, reducing the need for frequent watering.', 'A layer of fallen leaves helps keep soil moist, reducing the need for frequent watering.', '/mɔɪst/', 'Một lớp lá rụng giúp giữ ẩm cho đất, làm giảm nhu cầu phải tưới nước thường xuyên.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_21_2_5', 'ten_b2_21_2', 'darken', 'Thick smoke from industrial fires can darken the sky and reduce visibility across nearby residential areas.', 'Thick smoke from industrial fires can darken the sky and reduce visibility across nearby residential areas.', '/ˈdɑːrkən/', 'Khói dày đặc từ các vụ hỏa hoạn công nghiệp có thể làm tối bầu trời và giảm tầm nhìn ở các khu dân cư lân cận.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_21_2_6', 'ten_b2_21_2', 'herb', 'Growing herbs at home can encourage healthier cooking and reduce the need for packaged seasonings.', 'Growing herbs at home can encourage healthier cooking and reduce the need for packaged seasonings.', '/ɝːb/', 'Trồng thảo mộc tại nhà có thể khuyến khích việc nấu ăn lành mạnh hơn và giảm nhu cầu sử dụng gia vị đóng gói sẵn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_21_2_1', 'en-b2-21', 'ten_b2_21_2', 'listening', 'listening', 'The waving grasses along restored riverbanks provide valuable habitats for wildlife and help protect soil from erosion.', NULL, 'Trong câu vừa nghe, từ “waving” mang nghĩa nào sau đây?', '["phân tích","tang lễ; đám tang","quy mô; mức độ","phấp phới, lay động, đu đưa qua lại nhẹ nhàng (thường là trong gió)"]'::jsonb, 3, '“waving” (/ˈweɪvɪŋ/): phấp phới, lay động, đu đưa qua lại nhẹ nhàng (thường là trong gió). Câu đầy đủ: The waving grasses along restored riverbanks provide valuable habitats for wildlife and help protect soil from erosion.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_21_2_2', 'en-b2-21', 'ten_b2_21_2', 'listening', 'listening', 'Growing walnut trees can provide farmers with additional income while increasing tree cover in rural areas.', NULL, 'Trong câu vừa nghe, từ “walnut” mang nghĩa nào sau đây?', '["thuộc về tổ chức; thuộc cơ cấu tổ chức","quả óc chó","sự nhẹ nhõm; sự thở phào","kỹ thuật viên; thợ kỹ thuật"]'::jsonb, 1, '“walnut” (/ˈwɔːlnʌt/): quả óc chó. Câu đầy đủ: Growing walnut trees can provide farmers with additional income while increasing tree cover in rural areas.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
