INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_21_3', 'en-b2-21', 'The owl watched its prey from a low branch', 'Con cú chăm chú quan sát con mồi từ một cành cây thấp.', 'prey /preɪ/', '["prey","a","from","its","owl","branch","The","watched","low"]'::jsonb, NULL, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_21_4', 'en-b2-21', 'Keep the soil moist until the first leaves appear', 'Hãy giữ cho đất ẩm cho đến khi những chiếc lá đầu tiên nhú lên.', 'moist /mɔɪst/', '["leaves","soil","until","the","Keep","first","the","moist","appear"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
