INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_21_2', 'en-b2-21', NULL, 'comprehensive_test', 'listening', 'She cracked a walnut and shared the kernel with me.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi bước đi trên lớp đá núi lửa sẫm màu gần bờ biển.","Hôm qua chúng tôi đã chứng kiến ba con gà con nở ở trang trại.","Những đám mây dày đặc làm bầu trời tối sầm lại trước khi chúng tôi về đến nhà.","Cô ấy đập một quả óc chó và chia phần nhân cho tôi."]'::jsonb, 3, 'She cracked a walnut and shared the kernel with me. → Cô ấy đập một quả óc chó và chia phần nhân cho tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_21_3', 'en-b2-21', NULL, 'comprehensive_test', 'listening', 'prey', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["điều khoản; điều mục trong văn bản pháp lý","con mồi (bị động vật khác săn đuổi và ăn thịt)","cảm xúc; tình cảm","con quạ"]'::jsonb, 1, 'prey (/preɪ/) → con mồi (bị động vật khác săn đuổi và ăn thịt); nạn nhân; mục tiêu bị lợi dụng hoặc hại; săn mồi; bóc lột; làm hại (thường đi với giới từ on)', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_21_4', 'en-b2-21', NULL, 'comprehensive_test', 'listening', 'Keep the soil moist until the first leaves appear.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hãy giữ cho đất ẩm cho đến khi những chiếc lá đầu tiên nhú lên.","Cây anh đào bên ngoài nhà bếp của chúng tôi ngập tràn những bông hoa màu hồng.","Những viên tinh thể nhỏ bé lấp lánh mỗi khi ánh nắng chiếu vào phòng.","Chúng tôi bước đi trên lớp đá núi lửa sẫm màu gần bờ biển."]'::jsonb, 0, 'Keep the soil moist until the first leaves appear. → Hãy giữ cho đất ẩm cho đến khi những chiếc lá đầu tiên nhú lên.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_21_5', 'en-b2-21', NULL, 'comprehensive_test', 'listening', 'darken', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thuộc học tập; thuộc học thuật","sự có mặt; sự hiện diện","hướng ra ngoài; ra phía ngoài","làm tối đi; trở nên tối hơn"]'::jsonb, 3, 'darken (/ˈdɑːrkən/) → làm tối đi; trở nên tối hơn; trở nên u ám; làm cho sầm mặt lại', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_21_6', 'en-b2-21', NULL, 'comprehensive_test', 'listening', 'She grows fresh herbs in pots beside the kitchen window.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Con cú chăm chú quan sát con mồi từ một cành cây thấp.","Một nụ xanh nhỏ xíu đã mọc lên trên cành cây trơ trụi.","Một chú nhím lạch bạch đi qua đám lá rụng bên hàng rào nhà chúng tôi.","Cô ấy trồng các loại rau thơm tươi trong chậu cạnh cửa sổ nhà bếp."]'::jsonb, 3, 'She grows fresh herbs in pots beside the kitchen window. → Cô ấy trồng các loại rau thơm tươi trong chậu cạnh cửa sổ nhà bếp.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_21_7', 'en-b2-21', NULL, 'comprehensive_test', 'listening', 'reptile', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["phần cốt lõi, trung tâm, quan trọng nhất; lõi (trái cây)","động vật bò sát","bằng chứng; chứng cứ; dấu hiệu","không đáng kể; nhỏ nhặt"]'::jsonb, 1, 'reptile (/ˈreptaɪl/) → động vật bò sát', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_21_8', 'en-b2-21', NULL, 'comprehensive_test', 'listening', 'We sheltered in a doorway until the downpour finally stopped.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một cây cỏ dại cứng đầu đã mọc lên giữa những viên đá lát đường.","Hãy giữ cho đất ẩm cho đến khi những chiếc lá đầu tiên nhú lên.","Chúng tôi trú mưa ở hiên cửa cho đến khi trận mưa rào cuối cùng cũng tạnh.","Con vật bò sát nằm bất động trên một tảng đá ấm áp."]'::jsonb, 2, 'We sheltered in a doorway until the downpour finally stopped. → Chúng tôi trú mưa ở hiên cửa cho đến khi trận mưa rào cuối cùng cũng tạnh.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_21_9', 'en-b2-21', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to become darker or make something darker”?', '["hedgehog","moist","waving","darken"]'::jsonb, 3, 'darken (/ˈdɑːrkən/) → làm tối đi; trở nên tối hơn', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_21_10', 'en-b2-21', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A plant used to flavour food or make medicines.”?', '["herb","Mediterranean","blossom","walnut"]'::jsonb, 0, 'herb (/ɝːb/) → thảo mộc; rau thơm; cây thuốc', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_21_11', 'en-b2-21', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a cold-blooded animal with scaly skin, such as a snake”?', '["bud","reptile","jellyfish","tame"]'::jsonb, 1, 'reptile (/ˈreptaɪl/) → động vật bò sát', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_21_12', 'en-b2-21', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a heavy fall of rain, often starting suddenly”?', '["weed","darken","downpour","bud"]'::jsonb, 2, 'downpour (/ˈdaʊnpɔːr/) → cơn mưa rào lớn; trận mưa xối xả', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_21_13', 'en-b2-21', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Used to people and not wild or dangerous.”?', '["weed","tame","prey","Mediterranean"]'::jsonb, 1, 'tame (/teɪm/) → thuần hóa; dễ gần', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
