INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_21_18', 'en-b2-21', NULL, 'comprehensive_test', 'reading', NULL, 'The waving grasses along restored riverbanks provide valuable habitats for wildlife and help protect soil from erosion.', 'Dựa vào câu trên, từ “waving” có nghĩa phù hợp nhất là gì?', '["trích dẫn; dẫn chứng","sao Kim","hoàng đế; vị vua cai trị đế quốc","phấp phới, lay động, đu đưa qua lại nhẹ nhàng (thường là trong gió)"]'::jsonb, 3, 'waving: phấp phới, lay động, đu đưa qua lại nhẹ nhàng (thường là trong gió). Dịch cả câu: Những thảm cỏ lay động ven các bờ sông được phục hồi mang lại môi trường sống quý giá cho động vật hoang dã và giúp bảo vệ đất khỏi bị xói mòn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_21_19', 'en-b2-21', NULL, 'comprehensive_test', 'reading', NULL, 'Growing walnut trees can provide farmers with additional income while increasing tree cover in rural areas.', 'Dựa vào câu trên, từ “walnut” có nghĩa phù hợp nhất là gì?', '["quả óc chó","rễ cây; rễ","chung; liên hợp; phối hợp","đầy đủ; thỏa đáng; tương xứng"]'::jsonb, 0, 'walnut: quả óc chó; cây óc chó; gỗ óc chó. Dịch cả câu: Việc trồng cây óc chó có thể mang lại thêm thu nhập cho nông dân đồng thời tăng độ che phủ của cây xanh ở các vùng nông thôn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_21_20', 'en-b2-21', NULL, 'comprehensive_test', 'reading', NULL, 'When natural prey becomes scarce, some predators move closer to farms in search of food.', 'Dựa vào câu trên, từ “prey” có nghĩa phù hợp nhất là gì?', '["con mồi (bị động vật khác săn đuổi và ăn thịt)","độ ẩm không khí","mục tiêu; mục đích","hầu như; gần như hoàn toàn"]'::jsonb, 0, 'prey: con mồi (bị động vật khác săn đuổi và ăn thịt); nạn nhân; mục tiêu bị lợi dụng hoặc hại; săn mồi; bóc lột; làm hại (thường đi với giới từ on). Dịch cả câu: Khi con mồi tự nhiên trở nên khan hiếm, một số loài săn mồi sẽ di chuyển đến gần các trang trại hơn để tìm kiếm thức ăn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_21_21', 'en-b2-21', NULL, 'comprehensive_test', 'reading', NULL, 'A layer of fallen leaves helps keep soil moist, reducing the need for frequent watering.', 'Dựa vào câu trên, từ “moist” có nghĩa phù hợp nhất là gì?', '["đâm; chọc; thọc","ẩm; ẩm ướt; ẩm mịn","không phù hợp; không đạt tiêu chuẩn","đáng chú ý; phi thường; xuất sắc"]'::jsonb, 1, 'moist: ẩm; ẩm ướt; ẩm mịn. Dịch cả câu: Một lớp lá rụng giúp giữ ẩm cho đất, làm giảm nhu cầu phải tưới nước thường xuyên.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_21_22', 'en-b2-21', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “lấp lánh; chiếu sáng rực rỡ”', '["hurrah","sparkle","darken","batch"]'::jsonb, 1, 'lấp lánh; chiếu sáng rực rỡ → sparkle (/ˈspɑːrkəl/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_21_23', 'en-b2-21', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “dày đặc; đông đúc, rậm rạp”', '["dense","saddle","species","bacterium"]'::jsonb, 0, 'dày đặc; đông đúc, rậm rạp → dense (/dens/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_21_24', 'en-b2-21', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nở; ấp trứng”', '["ancestor","supplier","kidnap","hatch"]'::jsonb, 3, 'nở; ấp trứng → hatch (/hætʃ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-22', 'en', 'Bài 22: Thiên nhiên & Thời tiết (5) - CEFR B2', 'CEFR B2', 'B2 · Thiên nhiên', '27 từ vựng Tiếng Anh CEFR B2 chủ đề thiên nhiên & thời tiết kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4022, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bark', 'en-b2-22', 'bark', '/bɑːrk/', 'B2', 'sủa; tiếng chó sủa; vỏ cây', 'v.', NULL, NULL, 'Tiếng chó sủa (bark) có thể đếm được; vỏ cây (bark) thường không đếm được.', 'Our dog barks whenever someone knocks on the door.', NULL, 'Con chó nhà chúng tôi cứ sủa mỗi khi có ai gõ cửa.', '{"wordId":"bark","ukIpa":"/bɑːk/","usIpa":"/bɑːrk/","cefr":"B2","topic":"nature","senses":[{"pos":"v.","en":"to make the short, loud sound of a dog","vi":"sủa"},{"pos":"n.","en":"a short, loud sound made by a dog","vi":"tiếng chó sủa"},{"pos":"n.","en":"the outer protective layer of a tree trunk or branch","vi":"vỏ cây"}],"examples":[{"en":"Our dog barks whenever someone knocks on the door.","vi":"Con chó nhà chúng tôi cứ sủa mỗi khi có ai gõ cửa.","audioKind":"ex"},{"en":"The bark of mature trees provides shelter for insects and helps protect the trunk from damage.","vi":"Vỏ cây trưởng thành là nơi trú ẩn cho côn trùng và giúp bảo vệ thân cây khỏi bị hư hại.","audioKind":"ex2"}],"collocations":[{"en":"bark at someone","vi":"sủa ai đó"},{"en":"a loud bark","vi":"một tiếng sủa lớn"},{"en":"tree bark","vi":"vỏ cây"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tiếng chó sủa (bark) có thể đếm được; vỏ cây (bark) thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_migrate', 'en-b2-22', 'migrate', '/ˈmaɪɡreɪt/', 'B2', 'di cư; di trú; chuyển đổi (dữ liệu hoặc phần mềm sang hệ thống mới)', 'v.', 'migration (n.), migrant (n.), migratory (adj.)', 'Đồng nghĩa: relocate, move', 'migrate nhấn mạnh sự di chuyển nói chung; immigrate là nhập cư, emigrate là xuất cư.', 'These birds migrate south when the weather turns cold.', NULL, 'Những loài chim này di cư về phương nam khi thời tiết trở lạnh.', '{"wordId":"migrate","ukIpa":"/maɪˈɡreɪt/","usIpa":"/ˈmaɪɡreɪt/","cefr":"B2","topic":"nature","senses":[{"pos":"v.","en":"to move to another region, seasonally or to live there","vi":"di cư; di trú"},{"pos":"v.","en":"to move data or software to a different computer system","vi":"chuyển đổi (dữ liệu hoặc phần mềm sang hệ thống mới)"}],"examples":[{"en":"These birds migrate south when the weather turns cold.","vi":"Những loài chim này di cư về phương nam khi thời tiết trở lạnh.","audioKind":"ex"},{"en":"Many young adults migrate to urban areas because employment opportunities are often limited in rural communities.","vi":"Nhiều thanh niên di cư về các khu vực đô thị vì cơ hội việc làm ở các vùng nông thôn thường rất hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"migrate south","vi":"di cư về phía nam"},{"en":"migrate to cities","vi":"di cư lên thành phố"},{"en":"migrate data","vi":"chuyển dữ liệu"}],"wordFamily":["migration (n.)","migrant (n.)","migratory (adj.)"],"synonyms":["relocate","move"],"antonyms":[],"tipVi":"migrate nhấn mạnh sự di chuyển nói chung; immigrate là nhập cư, emigrate là xuất cư.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lobster', 'en-b2-22', 'lobster', '/ˈlɑːbstər/', 'B2', 'tôm hùm', 'n.', NULL, NULL, 'Chỉ động vật thì đếm được; chỉ thịt tôm hùm làm thức ăn thì không đếm được.', 'We watched a lobster crawl across the rocky seabed.', NULL, 'Chúng tôi nhìn thấy một con tôm hùm bò ngang qua đáy biển nhiều đá.', '{"wordId":"lobster","ukIpa":"/ˈlɒbstə/","usIpa":"/ˈlɑːbstər/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A large sea animal with a hard shell and claws.","vi":"tôm hùm"}],"examples":[{"en":"We watched a lobster crawl across the rocky seabed.","vi":"Chúng tôi nhìn thấy một con tôm hùm bò ngang qua đáy biển nhiều đá.","audioKind":"ex"},{"en":"Restrictions on lobster fishing can protect marine ecosystems while supporting the long-term livelihoods of coastal communities.","vi":"Việc hạn chế đánh bắt tôm hùm có thể bảo vệ các hệ sinh thái biển đồng thời duy trì sinh kế lâu dài cho các cộng đồng ven biển.","audioKind":"ex2"}],"collocations":[{"en":"lobster fishing","vi":"đánh bắt tôm hùm"},{"en":"lobster tail","vi":"đuôi tôm hùm"},{"en":"lobster pot","vi":"lồng bắt tôm hùm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ động vật thì đếm được; chỉ thịt tôm hùm làm thức ăn thì không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mist', 'en-b2-22', 'mist', '/mɪst/', 'B2', 'sương mù mỏng; làn sương; phủ sương; làm mờ (bằng hơi nước)', 'n.', 'misty (adj.)', NULL, '"mist" thường mỏng hơn "fog"; kính bị mờ hơi nước có thể dùng cụm "mist over".', 'A thin mist floated above the lake this morning.', NULL, 'Sáng nay một làn sương mỏng trôi lơ lửng trên mặt hồ.', '{"wordId":"mist","ukIpa":"/mɪst/","usIpa":"/mɪst/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"tiny water drops in the air that reduce visibility","vi":"sương mù mỏng; làn sương"},{"pos":"v.","en":"to become or make something covered with tiny water drops","vi":"phủ sương; làm mờ (bằng hơi nước)"}],"examples":[{"en":"A thin mist floated above the lake this morning.","vi":"Sáng nay một làn sương mỏng trôi lơ lửng trên mặt hồ.","audioKind":"ex"},{"en":"Drivers should reduce their speed when mist limits visibility on rural roads during the early morning.","vi":"Người lái xe nên giảm tốc độ khi sương mù làm hạn chế tầm nhìn trên các tuyến đường nông thôn vào sáng sớm.","audioKind":"ex2"}],"collocations":[{"en":"thick mist","vi":"sương mù dày đặc"},{"en":"morning mist","vi":"sương sớm"},{"en":"mist over","vi":"bị mờ đi vì hơi nước"}],"wordFamily":["misty (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"\"mist\" thường mỏng hơn \"fog\"; kính bị mờ hơi nước có thể dùng cụm \"mist over\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_landslide', 'en-b2-22', 'landslide', '/ˈlændslaɪd/', 'B2', 'vụ sạt lở đất; lở đất; chiến thắng áp đảo (trong bầu cử)', 'n.', NULL, NULL, 'Trong ngữ cảnh chính trị, từ này thường chỉ chiến thắng áp đảo trong các cuộc bầu cử.', 'A landslide blocked the road after last night''s rain.', NULL, 'Một vụ sạt lở đất đã chắn ngang con đường sau cơn mưa đêm qua.', '{"wordId":"landslide","ukIpa":"/ˈlændslaɪd/","usIpa":"/ˈlændslaɪd/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"a mass of earth and rocks sliding down a slope","vi":"vụ sạt lở đất; lở đất"},{"pos":"n.","en":"an election victory by a very large margin","vi":"chiến thắng áp đảo (trong bầu cử)"}],"examples":[{"en":"A landslide blocked the road after last night''s rain.","vi":"Một vụ sạt lở đất đã chắn ngang con đường sau cơn mưa đêm qua.","audioKind":"ex"},{"en":"Removing trees from steep hillsides can increase the risk of landslides during periods of heavy rainfall.","vi":"Việc chặt phá cây cối trên các sườn đồi dốc có thể làm tăng nguy cơ sạt lở đất trong những đợt mưa lớn.","audioKind":"ex2"}],"collocations":[{"en":"trigger a landslide","vi":"gây ra sạt lở đất"},{"en":"landslide risk","vi":"nguy cơ sạt lở đất"},{"en":"landslide victory","vi":"chiến thắng áp đảo"},{"en":"win by a landslide","vi":"thắng áp đảo"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong ngữ cảnh chính trị, từ này thường chỉ chiến thắng áp đảo trong các cuộc bầu cử.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wag', 'en-b2-22', 'wag', '/wæɡ/', 'B2', 'vẫy, lắc lư qua lại (đuôi, đầu); sự vẫy, sự lắc lư; người hay nói đùa, người hài hước', 'v.', NULL, NULL, 'Dạng quá khứ là "wagged" và phân từ là "wagging", cả hai đều gấp đôi chữ "g".', 'The puppy wagged its tail when I came home.', NULL, 'Chú chó con vẫy đuôi rối rít khi tôi về đến nhà.', '{"wordId":"wag","ukIpa":"/wæɡ/","usIpa":"/wæɡ/","cefr":"B2","topic":"nature","senses":[{"pos":"v.","en":"move repeatedly from side to side","vi":"vẫy, lắc lư qua lại (đuôi, đầu)"},{"pos":"n.","en":"a movement from side to side","vi":"sự vẫy, sự lắc lư"},{"pos":"n.","en":"someone who often makes clever or amusing remarks","vi":"người hay nói đùa, người hài hước"}],"examples":[{"en":"The puppy wagged its tail when I came home.","vi":"Chú chó con vẫy đuôi rối rít khi tôi về đến nhà.","audioKind":"ex"},{"en":"Although dogs often wag their tails during friendly encounters, this movement does not always indicate happiness.","vi":"Mặc dù loài chó thường vẫy đuôi trong các cuộc gặp gỡ thân thiện, động thái này không phải lúc nào cũng biểu thị sự vui vẻ.","audioKind":"ex2"}],"collocations":[{"en":"wag its tail","vi":"vẫy đuôi"},{"en":"wag a finger at someone","vi":"ra hiệu quở trách bằng cách lắc ngón tay"},{"en":"a wag of the tail","vi":"một cái vẫy đuôi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ là \"wagged\" và phân từ là \"wagging\", cả hai đều gấp đôi chữ \"g\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ox', 'en-b2-22', 'ox', '/ɑːks/', 'B2', 'bò đực đã bị thiến dùng để kéo cày, bò kéo, trâu bò lực lưỡng', 'n.', NULL, NULL, 'Dạng số nhiều là "oxen"; từ này chuyên chỉ bò dùng để lao động, không đồng nghĩa với con bò đực giống "bull".', 'The ox pulled a wooden cart along the path.', NULL, 'Con bò kéo chiếc xe gỗ đi dọc theo con đường mòn.', '{"wordId":"ox","ukIpa":"/ɒks/","usIpa":"/ɑːks/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"a large bovine, often a castrated male, used for work","vi":"bò đực đã bị thiến dùng để kéo cày, bò kéo, trâu bò lực lưỡng"}],"examples":[{"en":"The ox pulled a wooden cart along the path.","vi":"Con bò kéo chiếc xe gỗ đi dọc theo con đường mòn.","audioKind":"ex"},{"en":"Before agricultural machinery became widespread, farmers in many regions relied on oxen to plough their fields.","vi":"Trước khi máy móc nông nghiệp trở nên phổ biến, nông dân ở nhiều vùng đã phải dựa vào sức kéo của bò để cày ruộng.","audioKind":"ex2"}],"collocations":[{"en":"a pair of oxen","vi":"một cặp bò kéo"},{"en":"an ox cart","vi":"xe bò kéo"},{"en":"as strong as an ox","vi":"khỏe như trâu"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều là \"oxen\"; từ này chuyên chỉ bò dùng để lao động, không đồng nghĩa với con bò đực giống \"bull\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sow', 'en-b2-22', 'sow', '/soʊ/', 'B2', 'gieo hạt; gieo trồng; gieo rắc; nhen nhóm', 'v.', 'sower (n.)', 'Đồng nghĩa: plant · Trái nghĩa: reap', 'Thì quá khứ là sowed, phân từ II là sown hoặc sowed; từ chỉ con lợn cái đọc là /saʊ/.', 'We sowed carrot seeds in the garden this morning.', NULL, 'Sáng nay chúng tôi đã gieo hạt cà rốt trong vườn.', '{"wordId":"sow","ukIpa":"/səʊ/","usIpa":"/soʊ/","cefr":"B2","topic":"nature","senses":[{"pos":"v.","en":"To put seeds in soil so they can grow.","vi":"gieo hạt; gieo trồng"},{"pos":"v.","en":"To cause feelings or problems to begin and spread.","vi":"gieo rắc; nhen nhóm"}],"examples":[{"en":"We sowed carrot seeds in the garden this morning.","vi":"Sáng nay chúng tôi đã gieo hạt cà rốt trong vườn.","audioKind":"ex"},{"en":"Misleading online reports can sow distrust among communities and weaken confidence in public institutions.","vi":"Các bài báo trực tuyến gây hiểu lầm có thể gieo rắc sự ngờ vực giữa các cộng đồng và làm suy yếu lòng tin vào các tổ chức công.","audioKind":"ex2"}],"collocations":[{"en":"sow seeds","vi":"gieo hạt"},{"en":"sow doubt","vi":"gây nghi ngờ"},{"en":"sow discord","vi":"gây chia rẽ"}],"wordFamily":["sower (n.)"],"synonyms":["plant"],"antonyms":["reap"],"tipVi":"Thì quá khứ là sowed, phân từ II là sown hoặc sowed; từ chỉ con lợn cái đọc là /saʊ/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_oak', 'en-b2-22', 'oak', '/oʊk/', 'B2', 'cây sồi; gỗ sồi', 'n.', NULL, NULL, 'Khi chỉ cây thì đếm được, chỉ gỗ thì không đếm được; oak table dùng oak làm định ngữ.', 'We spread our picnic blanket beneath a huge oak.', NULL, 'Chúng tôi trải thảm dã ngoại dưới bóng một cây sồi lớn.', '{"wordId":"oak","ukIpa":"/əʊk/","usIpa":"/oʊk/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"a large tree that produces acorns","vi":"cây sồi"},{"pos":"n.","en":"the strong, hard wood of an oak tree","vi":"gỗ sồi"}],"examples":[{"en":"We spread our picnic blanket beneath a huge oak.","vi":"Chúng tôi trải thảm dã ngoại dưới bóng một cây sồi lớn.","audioKind":"ex"},{"en":"Protecting mature oak trees helps preserve woodland habitats and supports a wide variety of native wildlife.","vi":"Việc bảo vệ những cây sồi trưởng thành giúp duy trì môi trường sống trong rừng và hỗ trợ đa dạng sinh học bản địa.","audioKind":"ex2"}],"collocations":[{"en":"oak tree","vi":"cây sồi"},{"en":"solid oak","vi":"gỗ sồi đặc"},{"en":"oak furniture","vi":"đồ nội thất bằng gỗ sồi"},{"en":"oak woodland","vi":"rừng sồi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ cây thì đếm được, chỉ gỗ thì không đếm được; oak table dùng oak làm định ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_root', 'en-b2-22', 'root', '/ruːt/', 'B2', 'rễ cây; rễ; gốc rễ; nguyên nhân gốc rễ; nguồn cội; bén rễ; ra rễ', 'n.', 'rooted (adj.), rootless (adj.)', NULL, 'Bản thân từ root không có nghĩa là nhổ tận gốc; phải dùng root out mới mang nghĩa triệt phá, nhổ tận gốc.', 'Thick roots from the oak have cracked our garden path.', NULL, 'Những chiếc rễ dày của cây sồi đã làm nứt lối đi trong vườn của chúng tôi.', '{"wordId":"root","ukIpa":"/ruːt/","usIpa":"/ruːt/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"the part of a plant that absorbs water from soil","vi":"rễ cây; rễ"},{"pos":"n.","en":"the basic cause or origin of something","vi":"gốc rễ; nguyên nhân gốc rễ; nguồn cội"},{"pos":"v.","en":"to grow roots or cause a plant to grow roots","vi":"bén rễ; ra rễ"}],"examples":[{"en":"Thick roots from the oak have cracked our garden path.","vi":"Những chiếc rễ dày của cây sồi đã làm nứt lối đi trong vườn của chúng tôi.","audioKind":"ex"},{"en":"Effective policies should address the root of poverty rather than simply provide temporary financial assistance.","vi":"Các chính sách hiệu quả nên giải quyết tận gốc rễ của tình trạng nghèo đói thay vì chỉ cung cấp hỗ trợ tài chính tạm thời.","audioKind":"ex2"}],"collocations":[{"en":"root cause","vi":"nguyên nhân gốc rễ"},{"en":"take root","vi":"bén rễ; cắm rễ; bén rễ sâu"},{"en":"at the root of","vi":"là cội nguồn của"},{"en":"plant roots","vi":"rễ thực vật"}],"wordFamily":["rooted (adj.)","rootless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Bản thân từ root không có nghĩa là nhổ tận gốc; phải dùng root out mới mang nghĩa triệt phá, nhổ tận gốc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_herd', 'en-b2-22', 'herd', '/hɝːd/', 'B2', 'bầy; đàn (thú lớn); dồn; lùa (động vật hoặc con người)', 'n.', 'herder (n.)', NULL, 'Các loài như bò, voi thường dùng herd; trong khi cừu hay chim thường dùng flock.', 'A herd of cows blocked the narrow country road.', NULL, 'Một đàn bò đã chặn ngang con đường làng chật hẹp.', '{"wordId":"herd","ukIpa":"/hɜːd/","usIpa":"/hɝːd/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"a group of large animals living or moving together","vi":"bầy; đàn (thú lớn)"},{"pos":"v.","en":"to guide animals or people together in a particular direction","vi":"dồn; lùa (động vật hoặc con người)"}],"examples":[{"en":"A herd of cows blocked the narrow country road.","vi":"Một đàn bò đã chặn ngang con đường làng chật hẹp.","audioKind":"ex"},{"en":"Protecting migration routes allows herds of wild animals to reach essential sources of food and water.","vi":"Bảo vệ các tuyến đường di cư giúp các đàn động vật hoang dã tiếp cận được các nguồn nước và thức ăn thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"a herd of cattle","vi":"một đàn gia súc"},{"en":"herd animals","vi":"động vật sống theo bầy đàn"},{"en":"herd cattle","vi":"lùa gia súc"},{"en":"herd instinct","vi":"bản năng bầy đàn"}],"wordFamily":["herder (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Các loài như bò, voi thường dùng herd; trong khi cừu hay chim thường dùng flock.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_roar', 'en-b2-22', 'roar', '/rɔːr/', 'B2', 'gầm; rống; gầm rú; tiếng gầm; tiếng gầm rú; tiếng ầm ầm', 'v.', NULL, 'Đồng nghĩa: bellow', 'Có thể dùng để chỉ tiếng sư tử gầm, tiếng động cơ gầm hoặc tiếng hò reo của đám đông.', 'The lion roared, and its cubs huddled closer together.', NULL, 'Con sư tử gầm lên, và những con sư tử con nép sát vào nhau hơn.', '{"wordId":"roar","ukIpa":"/rɔː/","usIpa":"/rɔːr/","cefr":"B2","topic":"nature","senses":[{"pos":"v.","en":"to make a very loud, deep sound","vi":"gầm; rống; gầm rú"},{"pos":"n.","en":"a very loud, deep sound","vi":"tiếng gầm; tiếng gầm rú; tiếng ầm ầm"}],"examples":[{"en":"The lion roared, and its cubs huddled closer together.","vi":"Con sư tử gầm lên, và những con sư tử con nép sát vào nhau hơn.","audioKind":"ex"},{"en":"Aircraft engines roar above nearby homes, exposing residents to noise pollution that can affect sleep quality.","vi":"Động cơ máy bay gầm rú ngay phía trên các khu nhà gần đó, khiến cư dân phải đối mặt với ô nhiễm tiếng ồn có thể ảnh hưởng đến chất lượng giấc ngủ.","audioKind":"ex2"}],"collocations":[{"en":"roar with laughter","vi":"cười phá lên"},{"en":"a roar of applause","vi":"tiếng vỗ tay như sấm"},{"en":"the roar of an engine","vi":"tiếng động cơ gầm rú"}],"wordFamily":[],"synonyms":["bellow"],"antonyms":[],"tipVi":"Có thể dùng để chỉ tiếng sư tử gầm, tiếng động cơ gầm hoặc tiếng hò reo của đám đông.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rot', 'en-b2-22', 'rot', '/rɑːt/', 'B2', 'thối rữa; mục nát; phân hủy; sự thối rữa; tình trạng mục nát', 'v.', 'rotten (adj.), rotting (adj.)', 'Đồng nghĩa: decay, decompose', 'Cả rot và decay đều chỉ sự phân hủy, nhưng khi viết dạng phân từ của rot cần chú ý gấp đôi chữ t (rotting).', 'The peaches will rot if you leave them outside.', NULL, 'Những quả đào sẽ bị thối rữa nếu bạn để chúng ở ngoài trời.', '{"wordId":"rot","ukIpa":"/rɒt/","usIpa":"/rɑːt/","cefr":"B2","topic":"nature","senses":[{"pos":"v.","en":"to break down naturally, or cause something to do so","vi":"thối rữa; mục nát; phân hủy"},{"pos":"n.","en":"the process or condition of decaying","vi":"sự thối rữa; tình trạng mục nát"}],"examples":[{"en":"The peaches will rot if you leave them outside.","vi":"Những quả đào sẽ bị thối rữa nếu bạn để chúng ở ngoài trời.","audioKind":"ex"},{"en":"Poor ventilation allows moisture to accumulate in older buildings, increasing the risk of rot in wooden structures.","vi":"Hệ thống thông gió kém khiến độ ẩm tích tụ trong các tòa nhà cũ, làm tăng nguy cơ mục nát ở các kết cấu gỗ.","audioKind":"ex2"}],"collocations":[{"en":"wood rot","vi":"mục gỗ"},{"en":"rot away","vi":"mục nát dần"},{"en":"dry rot","vi":"bệnh mục khô"}],"wordFamily":["rotten (adj.)","rotting (adj.)"],"synonyms":["decay","decompose"],"antonyms":[],"tipVi":"Cả rot và decay đều chỉ sự phân hủy, nhưng khi viết dạng phân từ của rot cần chú ý gấp đôi chữ t (rotting).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stem', 'en-b2-22', 'stem', '/stem/', 'B2', 'thân cây; cuống; bắt nguồn từ; xuất phát từ; ngăn chặn; kìm hãm', 'n.', NULL, 'Đồng nghĩa: stalk, originate, curb', 'Dùng stem from để chỉ nguyên nhân; chữ viết hoa STEM chỉ các ngành khoa học, công nghệ, kỹ thuật và toán học.', 'She cut the rose stem before filling the vase.', NULL, 'Cô ấy cắt cuống hoa hồng trước khi cắm vào lọ.', '{"wordId":"stem","ukIpa":"/stem/","usIpa":"/stem/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"the main plant part supporting leaves, flowers, or fruit","vi":"thân cây; cuống"},{"pos":"v.","en":"originate or result from something","vi":"bắt nguồn từ; xuất phát từ"},{"pos":"v.","en":"stop or reduce an unwanted flow or increase","vi":"ngăn chặn; kìm hãm"}],"examples":[{"en":"She cut the rose stem before filling the vase.","vi":"Cô ấy cắt cuống hoa hồng trước khi cắm vào lọ.","audioKind":"ex"},{"en":"Many urban transport problems stem from poor planning rather than a simple shortage of road space.","vi":"Nhiều vấn đề giao thông đô thị bắt nguồn từ việc quy hoạch kém chứ không đơn thuần là do thiếu không gian đường sá.","audioKind":"ex2"}],"collocations":[{"en":"plant stem","vi":"thân cây"},{"en":"stem from","vi":"bắt nguồn từ"},{"en":"stem the flow of","vi":"ngăn chặn dòng chảy của"},{"en":"stem the tide of","vi":"ngăn chặn đà lan rộng của"}],"wordFamily":[],"synonyms":["stalk","originate","curb"],"antonyms":[],"tipVi":"Dùng stem from để chỉ nguyên nhân; chữ viết hoa STEM chỉ các ngành khoa học, công nghệ, kỹ thuật và toán học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_altitude', 'en-b2-22', 'altitude', '/ˈæltɪtuːd/', 'B2', 'độ cao (so với mực nước biển hoặc mặt đất)', 'n.', NULL, 'Đồng nghĩa: height, elevation', 'altitude chỉ độ cao; attitude chỉ thái độ, chú ý phân biệt cách viết.', 'We felt breathless because of the high altitude.', NULL, 'Chúng tôi cảm thấy hụt hơi vì vùng cao có độ cao lớn.', '{"wordId":"altitude","ukIpa":"/ˈæltɪtjuːd/","usIpa":"/ˈæltɪtuːd/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"Height above sea level or above the ground.","vi":"độ cao (so với mực nước biển hoặc mặt đất)"}],"examples":[{"en":"We felt breathless because of the high altitude.","vi":"Chúng tôi cảm thấy hụt hơi vì vùng cao có độ cao lớn.","audioKind":"ex"},{"en":"At higher altitudes, reduced oxygen levels can affect physical performance and require a period of adjustment.","vi":"Ở độ cao lớn hơn, lượng oxy giảm có thể ảnh hưởng đến thể lực và đòi hỏi một khoảng thời gian để thích nghi.","audioKind":"ex2"}],"collocations":[{"en":"at high altitude","vi":"ở độ cao lớn"},{"en":"gain altitude","vi":"tăng độ cao"},{"en":"cruising altitude","vi":"độ cao bay đường dài"}],"wordFamily":[],"synonyms":["height","elevation"],"antonyms":[],"tipVi":"altitude chỉ độ cao; attitude chỉ thái độ, chú ý phân biệt cách viết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_crow', 'en-b2-22', 'crow', '/kroʊ/', 'B2', 'con quạ; gáy (gà trống); khoác lác; kiêu hãnh khoe khoang', 'n.', NULL, NULL, 'Danh từ chỉ con quạ, nhưng động từ lại có thể chỉ tiếng gà trống gáy.', 'A crow landed on the fence beside our garden.', NULL, 'Một con quạ đậu trên hàng rào bên cạnh khu vườn của chúng tôi.', '{"wordId":"crow","ukIpa":"/krəʊ/","usIpa":"/kroʊ/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A large black bird with a loud, rough call.","vi":"con quạ"},{"pos":"v.","en":"Make the loud call typical of a male chicken.","vi":"gáy (gà trống)"},{"pos":"v.","en":"Talk proudly and annoyingly about your own success.","vi":"khoác lác; kiêu hãnh khoe khoang"}],"examples":[{"en":"A crow landed on the fence beside our garden.","vi":"Một con quạ đậu trên hàng rào bên cạnh khu vườn của chúng tôi.","audioKind":"ex"},{"en":"Studies of crow behaviour suggest that some birds can solve complex problems and use simple tools.","vi":"Các nghiên cứu về hành vi của quạ cho thấy một số loài chim có thể giải quyết các vấn đề phức tạp và sử dụng các công cụ đơn giản.","audioKind":"ex2"}],"collocations":[{"en":"a flock of crows","vi":"một đàn quạ"},{"en":"a rooster crows","vi":"gà trống gáy"},{"en":"crow about a victory","vi":"khoác lác về một chiến thắng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ chỉ con quạ, nhưng động từ lại có thể chỉ tiếng gà trống gáy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_being', 'en-b2-22', 'being', '/ˈbiːɪŋ/', 'B2', 'sinh vật; con người; sự tồn tại; bản chất', 'n.', 'be (v.)', 'Đồng nghĩa: creature, existence · Trái nghĩa: non-existence', 'Chỉ sinh vật khi đếm được; biểu thị "sự tồn tại" thì thường không đếm được.', 'Every living being in this pond needs clean water.', NULL, 'Mọi sinh vật sống trong cái ao này đều cần nước sạch.', '{"wordId":"being","ukIpa":"/ˈbiːɪŋ/","usIpa":"/ˈbiːɪŋ/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"a living creature, especially a person","vi":"sinh vật; con người"},{"pos":"n.","en":"existence or the essential nature of a person or thing","vi":"sự tồn tại; bản chất"}],"examples":[{"en":"Every living being in this pond needs clean water.","vi":"Mọi sinh vật sống trong cái ao này đều cần nước sạch.","audioKind":"ex"},{"en":"Respect for every human being should guide the development of public services and social welfare policies.","vi":"Việc tôn trọng mọi con người cần phải định hướng cho sự phát triển của các dịch vụ công và chính sách an sinh xã hội.","audioKind":"ex2"}],"collocations":[{"en":"human being","vi":"con người"},{"en":"living being","vi":"sinh vật sống"},{"en":"come into being","vi":"hình thành; ra đời"}],"wordFamily":["be (v.)"],"synonyms":["creature","existence"],"antonyms":["non-existence"],"tipVi":"Chỉ sinh vật khi đếm được; biểu thị \"sự tồn tại\" thì thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_predator', 'en-b2-22', 'predator', '/ˈpredətər/', 'B2', 'động vật ăn thịt; động vật săn mồi; kẻ săn mồi; kẻ bóc lột', 'n.', 'predation (n.), predatory (adj.)', NULL, 'Predator là kẻ săn mồi, còn prey là con mồi bị săn.', 'The rabbit froze when it noticed a predator nearby.', NULL, 'Con thỏ đứng sững lại khi nhận ra có kẻ săn mồi ở gần đó.', '{"wordId":"predator","ukIpa":"/ˈpredətə/","usIpa":"/ˈpredətər/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"An animal that hunts and eats other animals.","vi":"động vật ăn thịt; động vật săn mồi"},{"pos":"n.","en":"A person or organisation that exploits others for personal gain.","vi":"kẻ săn mồi; kẻ bóc lột"}],"examples":[{"en":"The rabbit froze when it noticed a predator nearby.","vi":"Con thỏ đứng sững lại khi nhận ra có kẻ săn mồi ở gần đó.","audioKind":"ex"},{"en":"Protecting natural predators can help farmers control pests without relying heavily on chemical pesticides.","vi":"Bảo vệ các loài động vật săn mồi tự nhiên có thể giúp nông dân kiểm soát dịch hại mà không phải phụ thuộc quá nhiều vào thuốc trừ sâu hóa học.","audioKind":"ex2"}],"collocations":[{"en":"natural predator","vi":"thiên địch; động vật ăn thịt tự nhiên"},{"en":"apex predator","vi":"động vật ăn thịt đầu bảng"},{"en":"predator population","vi":"quần thể động vật săn mồi"}],"wordFamily":["predation (n.)","predatory (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Predator là kẻ săn mồi, còn prey là con mồi bị săn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_survival', 'en-b2-22', 'survival', '/sərˈvaɪvəl/', 'B2', 'sự sống sót; sự tồn tại; sự sinh tồn', 'n.', 'survive (v.), survivor (n.)', NULL, 'survival chỉ trạng thái sống sót; người sống sót dùng "survivor".', 'The lost hikers carried blankets and other survival equipment.', NULL, 'Những người đi bộ đường dài bị lạc đã mang theo chăn và các thiết bị sinh tồn khác.', '{"wordId":"survival","ukIpa":"/səˈvaɪvəl/","usIpa":"/sərˈvaɪvəl/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"the state of remaining alive or continuing to exist","vi":"sự sống sót; sự tồn tại; sự sinh tồn"}],"examples":[{"en":"The lost hikers carried blankets and other survival equipment.","vi":"Những người đi bộ đường dài bị lạc đã mang theo chăn và các thiết bị sinh tồn khác.","audioKind":"ex"},{"en":"Protecting natural habitats is essential for the survival of species threatened by climate change.","vi":"Việc bảo vệ môi trường sống tự nhiên là điều thiết yếu cho sự sống còn của các loài bị đe dọa bởi biến đổi khí hậu.","audioKind":"ex2"}],"collocations":[{"en":"survival skills","vi":"kỹ năng sinh tồn"},{"en":"survival rate","vi":"tỷ lệ sống sót"},{"en":"long-term survival","vi":"sự tồn tại lâu dài"},{"en":"fight for survival","vi":"đấu tranh sinh tồn"}],"wordFamily":["survive (v.)","survivor (n.)"],"synonyms":[],"antonyms":[],"tipVi":"survival chỉ trạng thái sống sót; người sống sót dùng \"survivor\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_erupt', 'en-b2-22', 'erupt', '/ɪˈrʌpt/', 'B2', 'phun trào (núi lửa); phun ra; bùng nổ; bùng phát (cảm xúc, tiếng ồn)', 'v.', 'eruption (n.), eruptive (adj.)', NULL, 'Thường dùng làm nội động từ; "erupt into" có thể theo sau bởi tiếng vỗ tay, v.v.', 'We watched the volcano erupt in a nature documentary.', NULL, 'Chúng tôi đã xem cảnh núi lửa phun trào trong một bộ phim tài liệu về thiên nhiên.', '{"wordId":"erupt","ukIpa":"/ɪˈrʌpt/","usIpa":"/ɪˈrʌpt/","cefr":"B2","topic":"nature","senses":[{"pos":"v.","en":"To force out lava, ash, or gas from a volcano.","vi":"phun trào (núi lửa); phun ra"},{"pos":"v.","en":"To begin suddenly with strong emotion, noise, or activity.","vi":"bùng nổ; bùng phát (cảm xúc, tiếng ồn)"}],"examples":[{"en":"We watched the volcano erupt in a nature documentary.","vi":"Chúng tôi đã xem cảnh núi lửa phun trào trong một bộ phim tài liệu về thiên nhiên.","audioKind":"ex"},{"en":"When volcanoes erupt, clouds of ash can disrupt air travel and affect communities far from the crater.","vi":"Khi núi lửa phun trào, những đám mây tro bụi có thể làm gián đoạn giao thông hàng không và ảnh hưởng đến các cộng đồng ở xa miệng núi lửa.","audioKind":"ex2"}],"collocations":[{"en":"volcano erupts","vi":"núi lửa phun trào"},{"en":"erupt into applause","vi":"vỡ òa trong tiếng vỗ tay"},{"en":"erupt in anger","vi":"nổi giận đùng đùng"}],"wordFamily":["eruption (n.)","eruptive (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng làm nội động từ; \"erupt into\" có thể theo sau bởi tiếng vỗ tay, v.v.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_riverside', 'en-b2-22', 'riverside', '/ˈrɪvərsaɪd/', 'B2', 'vùng bờ sông; ven sông', 'n.', 'river (n.)', 'Đồng nghĩa: riverbank', 'Thường dùng làm danh từ bổ nghĩa, ví dụ như a riverside park (công viên ven sông).', 'We walked along the riverside after a late lunch.', NULL, 'Chúng tôi đi dạo dọc bờ sông sau bữa trưa muộn.', '{"wordId":"riverside","ukIpa":"/ˈrɪvəsaɪd/","usIpa":"/ˈrɪvərsaɪd/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"The area of land beside a river.","vi":"vùng bờ sông; ven sông"}],"examples":[{"en":"We walked along the riverside after a late lunch.","vi":"Chúng tôi đi dạo dọc bờ sông sau bữa trưa muộn.","audioKind":"ex"},{"en":"Improving access to the riverside can create attractive public spaces and encourage residents to exercise outdoors.","vi":"Việc cải thiện lối đi ra bờ sông có thể tạo ra các không gian công cộng thu hút và khuyến khích cư dân tập thể dục ngoài trời.","audioKind":"ex2"}],"collocations":[{"en":"along the riverside","vi":"dọc theo bờ sông"},{"en":"a riverside walk","vi":"lối đi ven sông"},{"en":"a riverside park","vi":"công viên ven sông"}],"wordFamily":["river (n.)"],"synonyms":["riverbank"],"antonyms":[],"tipVi":"Thường dùng làm danh từ bổ nghĩa, ví dụ như a riverside park (công viên ven sông).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_steep', 'en-b2-22', 'steep', '/stiːp/', 'B2', 'dốc; dốc đứng; tăng/giảm mạnh; quá cao (về giá cả); ngâm (trong chất lỏng để ra vị hoặc mềm)', 'adj.', 'steeply (adv.), steepness (n.)', 'Trái nghĩa: gentle', 'steep vừa dùng để tả độ dốc của địa hình, vừa tả giá cả đắt đỏ hoặc sự biến động mạnh.', 'We pushed our bikes up the steep hill.', NULL, 'Chúng tôi đẩy xe đạp lên ngọn đồi dốc.', '{"wordId":"steep","ukIpa":"/stiːp/","usIpa":"/stiːp/","cefr":"B2","topic":"nature","senses":[{"pos":"adj.","en":"rising or falling at a sharp angle","vi":"dốc; dốc đứng"},{"pos":"adj.","en":"describing a sharp change or an unusually high price","vi":"tăng/giảm mạnh; quá cao (về giá cả)"},{"pos":"v.","en":"to leave something in liquid to release flavour or soften it","vi":"ngâm (trong chất lỏng để ra vị hoặc mềm)"}],"examples":[{"en":"We pushed our bikes up the steep hill.","vi":"Chúng tôi đẩy xe đạp lên ngọn đồi dốc.","audioKind":"ex"},{"en":"A steep rise in housing costs can force young workers to move away from major cities.","vi":"Chi phí nhà ở tăng vọt có thể buộc những người lao động trẻ phải rời khỏi các thành phố lớn.","audioKind":"ex2"}],"collocations":[{"en":"steep slope","vi":"sườn dốc"},{"en":"steep rise","vi":"sự tăng vọt"},{"en":"steep decline","vi":"sự sụt giảm mạnh"},{"en":"steep prices","vi":"giá cả quá cao"}],"wordFamily":["steeply (adv.)","steepness (n.)"],"synonyms":[],"antonyms":["gentle"],"tipVi":"steep vừa dùng để tả độ dốc của địa hình, vừa tả giá cả đắt đỏ hoặc sự biến động mạnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_depth', 'en-b2-22', 'depth', '/depθ/', 'B2', 'chiều sâu; độ sâu; độ sâu sắc; mức độ chi tiết và thấu đáo', 'n.', 'deep (adj.), deeply (adv.), deepen (v.)', 'Trái nghĩa: shallowness', 'Cụm in depth có nghĩa là "một cách sâu sắc/chi tiết", không dịch là "ở trong độ sâu".', 'Check the depth before you jump into the pool.', NULL, 'Hãy kiểm tra độ sâu trước khi bạn nhảy xuống hồ bơi.', '{"wordId":"depth","ukIpa":"/depθ/","usIpa":"/depθ/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"The distance from a surface to the bottom.","vi":"chiều sâu; độ sâu"},{"pos":"n.","en":"The degree of detail, understanding, or seriousness.","vi":"độ sâu sắc; mức độ chi tiết và thấu đáo"}],"examples":[{"en":"Check the depth before you jump into the pool.","vi":"Hãy kiểm tra độ sâu trước khi bạn nhảy xuống hồ bơi.","audioKind":"ex"},{"en":"University courses should encourage students to explore complex environmental issues in greater depth.","vi":"Các khóa học đại học nên khuyến khích sinh viên khám phá các vấn đề môi trường phức tạp một cách sâu sắc hơn.","audioKind":"ex2"}],"collocations":[{"en":"water depth","vi":"độ sâu của nước"},{"en":"in depth","vi":"một cách sâu sắc; chi tiết"},{"en":"depth of knowledge","vi":"chiều sâu kiến thức"}],"wordFamily":["deep (adj.)","deeply (adv.)","deepen (v.)"],"synonyms":[],"antonyms":["shallowness"],"tipVi":"Cụm in depth có nghĩa là \"một cách sâu sắc/chi tiết\", không dịch là \"ở trong độ sâu\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wasp', 'en-b2-22', 'wasp', '/wɑːsp/', 'B2', 'ong bắp cày; ong vò vẽ', 'n.', 'waspish (adj.)', NULL, 'wasp là ong bắp cày, trong khi bee là ong mật; đây là hai loài côn trùng khác nhau.', 'A wasp landed on the edge of my glass.', NULL, 'Một con wasp đậu ở rìa ly của tôi.', '{"wordId":"wasp","ukIpa":"/wɒsp/","usIpa":"/wɑːsp/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A narrow-waisted flying insect that can sting.","vi":"ong bắp cày; ong vò vẽ"}],"examples":[{"en":"A wasp landed on the edge of my glass.","vi":"Một con wasp đậu ở rìa ly của tôi.","audioKind":"ex"},{"en":"Although wasps are often considered pests, many species help control insects that damage agricultural crops.","vi":"Mặc dù ong bắp cày thường được coi là loài gây hại, nhưng nhiều loài giúp kiểm soát côn trùng phá hoại mùa màng.","audioKind":"ex2"}],"collocations":[{"en":"wasp sting","vi":"vết ong bắp cày đốt"},{"en":"wasp nest","vi":"tổ ong bắp cày"}],"wordFamily":["waspish (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"wasp là ong bắp cày, trong khi bee là ong mật; đây là hai loài côn trùng khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_oyster', 'en-b2-22', 'oyster', '/ˈɔɪstər/', 'B2', 'con hàu; con trai', 'n.', NULL, NULL, 'Cụm thành ngữ the world is your oyster có nghĩa là bạn có vô vàn cơ hội rộng mở trước mắt.', 'The oyster shell felt rough against my fingers.', NULL, 'Vỏ hàu sần sùi cọ xát vào các ngón tay của tôi.', '{"wordId":"oyster","ukIpa":"/ˈɔɪstə/","usIpa":"/ˈɔɪstər/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A shellfish with a rough shell, sometimes producing pearls.","vi":"con hàu; con trai"}],"examples":[{"en":"The oyster shell felt rough against my fingers.","vi":"Vỏ hàu sần sùi cọ xát vào các ngón tay của tôi.","audioKind":"ex"},{"en":"Restoring oyster populations can improve coastal water quality because these shellfish filter particles from the surrounding water.","vi":"Việc phục hồi các quần thể hàu có thể cải thiện chất lượng nước ven biển vì loài nhuyễn thể này lọc các hạt lơ lửng trong vùng nước xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"oyster shell","vi":"vỏ hàu"},{"en":"oyster farm","vi":"trang trại nuôi hàu"},{"en":"oyster reef","vi":"rạn hàu"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm thành ngữ the world is your oyster có nghĩa là bạn có vô vàn cơ hội rộng mở trước mắt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_capture', 'en-b2-22', 'capture', '/ˈkæptʃər/', 'B2', 'bắt giữ; tóm gọn; ghi lại; lưu giữ (hình ảnh, âm thanh); sự bắt giữ; sự tóm gọn', 'v.', 'captive (n.), captivity (n.), captor (n.)', 'Đồng nghĩa: catch, record · Trái nghĩa: release', 'Việc ghi lại hình ảnh hoặc bầu không khí cũng có thể dùng từ capture.', 'Rescuers captured the injured bird and gently examined its wing.', NULL, 'Các nhân viên cứu hộ đã bắt giữ con chim bị thương và nhẹ nhàng kiểm tra cánh của nó.', '{"wordId":"capture","ukIpa":"/ˈkæptʃə/","usIpa":"/ˈkæptʃər/","cefr":"B2","topic":"nature","senses":[{"pos":"v.","en":"to catch someone or something and prevent escape","vi":"bắt giữ; tóm gọn"},{"pos":"v.","en":"to record an image, sound, or particular quality","vi":"ghi lại; lưu giữ (hình ảnh, âm thanh)"},{"pos":"n.","en":"the act of catching someone or something","vi":"sự bắt giữ; sự tóm gọn"}],"examples":[{"en":"Rescuers captured the injured bird and gently examined its wing.","vi":"Các nhân viên cứu hộ đã bắt giữ con chim bị thương và nhẹ nhàng kiểm tra cánh của nó.","audioKind":"ex"},{"en":"Wildlife researchers use remote cameras to capture animal behaviour without disturbing natural habitats.","vi":"Các nhà nghiên cứu động vật hoang dã sử dụng camera từ xa để ghi lại hành vi của động vật mà không làm xáo trộn môi trường sống tự nhiên của chúng.","audioKind":"ex2"}],"collocations":[{"en":"capture an image","vi":"chụp ảnh; quay phim"},{"en":"capture attention","vi":"thu hút sự chú ý"},{"en":"capture the atmosphere","vi":"ghi lại bầu không khí"},{"en":"capture a suspect","vi":"bắt giữ nghi phạm"}],"wordFamily":["captive (n.)","captivity (n.)","captor (n.)"],"synonyms":["catch","record"],"antonyms":["release"],"tipVi":"Việc ghi lại hình ảnh hoặc bầu không khí cũng có thể dùng từ capture.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lily', 'en-b2-22', 'lily', '/ˈlɪli/', 'B2', 'cây hoa lily; hoa loa kèn; hoa bách hợp', 'n.', NULL, NULL, 'Số nhiều là lilies; water lily có nghĩa là hoa súng.', 'A white lily opened beside our kitchen window this morning.', NULL, 'Một bông hoa lily trắng đã nở rộ cạnh cửa sổ nhà bếp của chúng tôi vào sáng nay.', '{"wordId":"lily","ukIpa":"/ˈlɪli/","usIpa":"/ˈlɪli/","cefr":"B2","topic":"nature","senses":[{"pos":"n.","en":"A plant with large, often trumpet-shaped flowers.","vi":"cây hoa lily; hoa loa kèn; hoa bách hợp"}],"examples":[{"en":"A white lily opened beside our kitchen window this morning.","vi":"Một bông hoa lily trắng đã nở rộ cạnh cửa sổ nhà bếp của chúng tôi vào sáng nay.","audioKind":"ex"},{"en":"Urban gardens planted with lilies and other flowering species can provide attractive spaces for local residents.","vi":"Các khu vườn đô thị trồng hoa lily và các loài hoa khác có thể tạo ra không gian hấp dẫn cho cư dân địa phương.","audioKind":"ex2"}],"collocations":[{"en":"white lily","vi":"hoa lily trắng"},{"en":"lily bulb","vi":"củ hoa lily"},{"en":"water lily","vi":"hoa súng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Số nhiều là lilies; water lily có nghĩa là hoa súng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_22_1', 'en-b2-22', 'Cách dùng “ox” (n.) — bò đực đã bị thiến dùng để kéo cày, bò kéo, trâu bò lực lưỡng', 'a pair of oxen  ·  an ox cart  ·  as strong as an ox', 'Dạng số nhiều là "oxen"; từ này chuyên chỉ bò dùng để lao động, không đồng nghĩa với con bò đực giống "bull".', NULL, '[{"hanzi":"The ox pulled a wooden cart along the path.","pinyin":"","meaning":"Con bò kéo chiếc xe gỗ đi dọc theo con đường mòn."},{"hanzi":"Before agricultural machinery became widespread, farmers in many regions relied on oxen to plough their fields.","pinyin":"","meaning":"Trước khi máy móc nông nghiệp trở nên phổ biến, nông dân ở nhiều vùng đã phải dựa vào sức kéo của bò để cày ruộng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_22_2', 'en-b2-22', 'Cách dùng “stem” (n.) — thân cây; cuống', 'plant stem  ·  stem from  ·  stem the flow of', 'Dùng stem from để chỉ nguyên nhân; chữ viết hoa STEM chỉ các ngành khoa học, công nghệ, kỹ thuật và toán học.', 'Đồng nghĩa: stalk, originate, curb', '[{"hanzi":"She cut the rose stem before filling the vase.","pinyin":"","meaning":"Cô ấy cắt cuống hoa hồng trước khi cắm vào lọ."},{"hanzi":"Many urban transport problems stem from poor planning rather than a simple shortage of road space.","pinyin":"","meaning":"Nhiều vấn đề giao thông đô thị bắt nguồn từ việc quy hoạch kém chứ không đơn thuần là do thiếu không gian đường sá."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_22_3', 'en-b2-22', 'Cách dùng “rot” (v.) — thối rữa; mục nát; phân hủy', 'wood rot  ·  rot away  ·  dry rot', 'Cả rot và decay đều chỉ sự phân hủy, nhưng khi viết dạng phân từ của rot cần chú ý gấp đôi chữ t (rotting).', 'Họ từ (Word Family): rotten (adj.), rotting (adj.) | Đồng nghĩa: decay, decompose', '[{"hanzi":"The peaches will rot if you leave them outside.","pinyin":"","meaning":"Những quả đào sẽ bị thối rữa nếu bạn để chúng ở ngoài trời."},{"hanzi":"Poor ventilation allows moisture to accumulate in older buildings, increasing the risk of rot in wooden structures.","pinyin":"","meaning":"Hệ thống thông gió kém khiến độ ẩm tích tụ trong các tòa nhà cũ, làm tăng nguy cơ mục nát ở các kết cấu gỗ."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_22_4', 'en-b2-22', 'Cách dùng “root” (n.) — rễ cây; rễ', 'root cause  ·  take root  ·  at the root of', 'Bản thân từ root không có nghĩa là nhổ tận gốc; phải dùng root out mới mang nghĩa triệt phá, nhổ tận gốc.', 'Họ từ (Word Family): rooted (adj.), rootless (adj.)', '[{"hanzi":"Thick roots from the oak have cracked our garden path.","pinyin":"","meaning":"Những chiếc rễ dày của cây sồi đã làm nứt lối đi trong vườn của chúng tôi."},{"hanzi":"Effective policies should address the root of poverty rather than simply provide temporary financial assistance.","pinyin":"","meaning":"Các chính sách hiệu quả nên giải quyết tận gốc rễ của tình trạng nghèo đói thay vì chỉ cung cấp hỗ trợ tài chính tạm thời."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_22_1', 'en-b2-22', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_22_1_1', 'ten_b2_22_1', 'bark', 'Our dog barks whenever someone knocks on the door.', 'Our dog barks whenever someone knocks on the door.', '/bɑːrk/', 'Con chó nhà chúng tôi cứ sủa mỗi khi có ai gõ cửa.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_22_1_2', 'ten_b2_22_1', 'migrate', 'These birds migrate south when the weather turns cold.', 'These birds migrate south when the weather turns cold.', '/ˈmaɪɡreɪt/', 'Những loài chim này di cư về phương nam khi thời tiết trở lạnh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_22_1_3', 'ten_b2_22_1', 'lobster', 'We watched a lobster crawl across the rocky seabed.', 'We watched a lobster crawl across the rocky seabed.', '/ˈlɑːbstər/', 'Chúng tôi nhìn thấy một con tôm hùm bò ngang qua đáy biển nhiều đá.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_22_1_4', 'ten_b2_22_1', 'mist', 'A thin mist floated above the lake this morning.', 'A thin mist floated above the lake this morning.', '/mɪst/', 'Sáng nay một làn sương mỏng trôi lơ lửng trên mặt hồ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_22_1_5', 'ten_b2_22_1', 'landslide', 'A landslide blocked the road after last night''s rain.', 'A landslide blocked the road after last night''s rain.', '/ˈlændslaɪd/', 'Một vụ sạt lở đất đã chắn ngang con đường sau cơn mưa đêm qua.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_22_1_6', 'ten_b2_22_1', 'wag', 'The puppy wagged its tail when I came home.', 'The puppy wagged its tail when I came home.', '/wæɡ/', 'Chú chó con vẫy đuôi rối rít khi tôi về đến nhà.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_22_1_7', 'ten_b2_22_1', 'ox', 'The ox pulled a wooden cart along the path.', 'The ox pulled a wooden cart along the path.', '/ɑːks/', 'Con bò kéo chiếc xe gỗ đi dọc theo con đường mòn.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_22_1_8', 'ten_b2_22_1', 'sow', 'We sowed carrot seeds in the garden this morning.', 'We sowed carrot seeds in the garden this morning.', '/soʊ/', 'Sáng nay chúng tôi đã gieo hạt cà rốt trong vườn.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_22_1_1', 'en-b2-22', 'ten_b2_22_1', 'listening', 'listening', 'Our dog barks whenever someone knocks on the door.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Mọi sinh vật sống trong cái ao này đều cần nước sạch.","Con chó nhà chúng tôi cứ sủa mỗi khi có ai gõ cửa.","Vỏ hàu sần sùi cọ xát vào các ngón tay của tôi.","Chúng tôi trải thảm dã ngoại dưới bóng một cây sồi lớn."]'::jsonb, 1, 'Our dog barks whenever someone knocks on the door. → Con chó nhà chúng tôi cứ sủa mỗi khi có ai gõ cửa.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_22_1_2', 'en-b2-22', 'ten_b2_22_1', 'listening', 'listening', 'These birds migrate south when the weather turns cold.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã xem cảnh núi lửa phun trào trong một bộ phim tài liệu về thiên nhiên.","Một vụ sạt lở đất đã chắn ngang con đường sau cơn mưa đêm qua.","Những loài chim này di cư về phương nam khi thời tiết trở lạnh.","Con sư tử gầm lên, và những con sư tử con nép sát vào nhau hơn."]'::jsonb, 2, 'These birds migrate south when the weather turns cold. → Những loài chim này di cư về phương nam khi thời tiết trở lạnh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_22_1_3', 'en-b2-22', 'ten_b2_22_1', 'listening', 'listening', 'We watched a lobster crawl across the rocky seabed.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi nhìn thấy một con tôm hùm bò ngang qua đáy biển nhiều đá.","Con sư tử gầm lên, và những con sư tử con nép sát vào nhau hơn.","Một con wasp đậu ở rìa ly của tôi.","Hãy kiểm tra độ sâu trước khi bạn nhảy xuống hồ bơi."]'::jsonb, 0, 'We watched a lobster crawl across the rocky seabed. → Chúng tôi nhìn thấy một con tôm hùm bò ngang qua đáy biển nhiều đá.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_22_2', 'en-b2-22', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_22_2_1', 'ten_b2_22_2', 'bark', 'The bark of mature trees provides shelter for insects and helps protect the trunk from damage.', 'The bark of mature trees provides shelter for insects and helps protect the trunk from damage.', '/bɑːrk/', 'Vỏ cây trưởng thành là nơi trú ẩn cho côn trùng và giúp bảo vệ thân cây khỏi bị hư hại.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_22_2_2', 'ten_b2_22_2', 'migrate', 'Many young adults migrate to urban areas because employment opportunities are often limited in rural communities.', 'Many young adults migrate to urban areas because employment opportunities are often limited in rural communities.', '/ˈmaɪɡreɪt/', 'Nhiều thanh niên di cư về các khu vực đô thị vì cơ hội việc làm ở các vùng nông thôn thường rất hạn chế.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_22_2_3', 'ten_b2_22_2', 'lobster', 'Restrictions on lobster fishing can protect marine ecosystems while supporting the long-term livelihoods of coastal communities.', 'Restrictions on lobster fishing can protect marine ecosystems while supporting the long-term livelihoods of coastal communities.', '/ˈlɑːbstər/', 'Việc hạn chế đánh bắt tôm hùm có thể bảo vệ các hệ sinh thái biển đồng thời duy trì sinh kế lâu dài cho các cộng đồng ven biển.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_22_2_4', 'ten_b2_22_2', 'mist', 'Drivers should reduce their speed when mist limits visibility on rural roads during the early morning.', 'Drivers should reduce their speed when mist limits visibility on rural roads during the early morning.', '/mɪst/', 'Người lái xe nên giảm tốc độ khi sương mù làm hạn chế tầm nhìn trên các tuyến đường nông thôn vào sáng sớm.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_22_2_5', 'ten_b2_22_2', 'landslide', 'Removing trees from steep hillsides can increase the risk of landslides during periods of heavy rainfall.', 'Removing trees from steep hillsides can increase the risk of landslides during periods of heavy rainfall.', '/ˈlændslaɪd/', 'Việc chặt phá cây cối trên các sườn đồi dốc có thể làm tăng nguy cơ sạt lở đất trong những đợt mưa lớn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_22_2_6', 'ten_b2_22_2', 'wag', 'Although dogs often wag their tails during friendly encounters, this movement does not always indicate happiness.', 'Although dogs often wag their tails during friendly encounters, this movement does not always indicate happiness.', '/wæɡ/', 'Mặc dù loài chó thường vẫy đuôi trong các cuộc gặp gỡ thân thiện, động thái này không phải lúc nào cũng biểu thị sự vui vẻ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_22_2_1', 'en-b2-22', 'ten_b2_22_2', 'listening', 'listening', 'The bark of mature trees provides shelter for insects and helps protect the trunk from damage.', NULL, 'Trong câu vừa nghe, từ “bark” mang nghĩa nào sau đây?', '["canxi","mồ mả; lăng mộ","sủa","mảnh vụn; mảnh vỡ; đoạn"]'::jsonb, 2, '“bark” (/bɑːrk/): sủa. Câu đầy đủ: The bark of mature trees provides shelter for insects and helps protect the trunk from damage.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_22_2_2', 'en-b2-22', 'ten_b2_22_2', 'listening', 'listening', 'Many young adults migrate to urban areas because employment opportunities are often limited in rural communities.', NULL, 'Trong câu vừa nghe, từ “migrate” mang nghĩa nào sau đây?', '["cùng cảnh ngộ; có chung hoàn cảnh","sự xây dựng; công trình xây dựng","di cư; di trú","trêu chọc; chế nhạo"]'::jsonb, 2, '“migrate” (/ˈmaɪɡreɪt/): di cư; di trú. Câu đầy đủ: Many young adults migrate to urban areas because employment opportunities are often limited in rural communities.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
