INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_22_2', 'en-b2-22', NULL, 'comprehensive_test', 'listening', 'These birds migrate south when the weather turns cold.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những loài chim này di cư về phương nam khi thời tiết trở lạnh.","Chúng tôi đi dạo dọc bờ sông sau bữa trưa muộn.","Một vụ sạt lở đất đã chắn ngang con đường sau cơn mưa đêm qua.","Một đàn bò đã chặn ngang con đường làng chật hẹp."]'::jsonb, 0, 'These birds migrate south when the weather turns cold. → Những loài chim này di cư về phương nam khi thời tiết trở lạnh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
