INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_22_4', 'en-b2-22', NULL, 'comprehensive_test', 'listening', 'A thin mist floated above the lake this morning.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Con chó nhà chúng tôi cứ sủa mỗi khi có ai gõ cửa.","Sáng nay một làn sương mỏng trôi lơ lửng trên mặt hồ.","Một bông hoa lily trắng đã nở rộ cạnh cửa sổ nhà bếp của chúng tôi vào sáng nay.","Những loài chim này di cư về phương nam khi thời tiết trở lạnh."]'::jsonb, 1, 'A thin mist floated above the lake this morning. → Sáng nay một làn sương mỏng trôi lơ lửng trên mặt hồ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_22_5', 'en-b2-22', NULL, 'comprehensive_test', 'listening', 'landslide', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["pháo đài; đồn lũy; thành trì","vụ sạt lở đất; lở đất","độc lập; không cần sự giúp đỡ","thuộc nội địa; ở sâu trong đất liền"]'::jsonb, 1, 'landslide (/ˈlændslaɪd/) → vụ sạt lở đất; lở đất; chiến thắng áp đảo (trong bầu cử)', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_22_6', 'en-b2-22', NULL, 'comprehensive_test', 'listening', 'The puppy wagged its tail when I came home.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đẩy xe đạp lên ngọn đồi dốc.","Chú chó con vẫy đuôi rối rít khi tôi về đến nhà.","Vỏ hàu sần sùi cọ xát vào các ngón tay của tôi.","Cô ấy cắt cuống hoa hồng trước khi cắm vào lọ."]'::jsonb, 1, 'The puppy wagged its tail when I came home. → Chú chó con vẫy đuôi rối rít khi tôi về đến nhà.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_22_7', 'en-b2-22', NULL, 'comprehensive_test', 'listening', 'ox', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đứa trẻ mồ côi","làm nản lòng; khiến buồn bã","thanh kiếm; đao","bò đực đã bị thiến dùng để kéo cày, bò kéo, trâu bò lực lưỡng"]'::jsonb, 3, 'ox (/ɑːks/) → bò đực đã bị thiến dùng để kéo cày, bò kéo, trâu bò lực lưỡng', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_22_8', 'en-b2-22', NULL, 'comprehensive_test', 'listening', 'We sowed carrot seeds in the garden this morning.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đi dạo dọc bờ sông sau bữa trưa muộn.","Sáng nay chúng tôi đã gieo hạt cà rốt trong vườn.","Con chó nhà chúng tôi cứ sủa mỗi khi có ai gõ cửa.","Các nhân viên cứu hộ đã bắt giữ con chim bị thương và nhẹ nhàng kiểm tra cánh của nó."]'::jsonb, 1, 'We sowed carrot seeds in the garden this morning. → Sáng nay chúng tôi đã gieo hạt cà rốt trong vườn.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_22_9', 'en-b2-22', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a mass of earth and rocks sliding down a slope”?', '["riverside","landslide","root","wag"]'::jsonb, 1, 'landslide (/ˈlændslaɪd/) → vụ sạt lở đất; lở đất', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_22_10', 'en-b2-22', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “move repeatedly from side to side”?', '["crow","wag","mist","stem"]'::jsonb, 1, 'wag (/wæɡ/) → vẫy, lắc lư qua lại (đuôi, đầu)', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
