INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_22_18', 'en-b2-22', NULL, 'comprehensive_test', 'reading', NULL, 'The bark of mature trees provides shelter for insects and helps protect the trunk from damage.', 'Dựa vào câu trên, từ “bark” có nghĩa phù hợp nhất là gì?', '["cào (dụng cụ có cán dài và răng cào để gom lá hoặc làm phẳng đất)","sủa","về cơ bản; bản chất là; cốt lõi là","ra mắt; giới thiệu (sản phẩm); khởi xướng; phát động"]'::jsonb, 1, 'bark: sủa; tiếng chó sủa; vỏ cây. Dịch cả câu: Vỏ cây trưởng thành là nơi trú ẩn cho côn trùng và giúp bảo vệ thân cây khỏi bị hư hại.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_22_19', 'en-b2-22', NULL, 'comprehensive_test', 'reading', NULL, 'Many young adults migrate to urban areas because employment opportunities are often limited in rural communities.', 'Dựa vào câu trên, từ “migrate” có nghĩa phù hợp nhất là gì?', '["di cư; di trú","thị lực; khả năng nhìn","chỉ huy; người chỉ huy","hồi tưởng; thiền định"]'::jsonb, 0, 'migrate: di cư; di trú; chuyển đổi (dữ liệu hoặc phần mềm sang hệ thống mới). Dịch cả câu: Nhiều thanh niên di cư về các khu vực đô thị vì cơ hội việc làm ở các vùng nông thôn thường rất hạn chế.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_22_20', 'en-b2-22', NULL, 'comprehensive_test', 'reading', NULL, 'Restrictions on lobster fishing can protect marine ecosystems while supporting the long-term livelihoods of coastal communities.', 'Dựa vào câu trên, từ “lobster” có nghĩa phù hợp nhất là gì?', '["lỗi thời; cũ kỹ","không thể tránh khỏi; chắc chắn xảy ra","sự phân chia; sự phân bổ","tôm hùm"]'::jsonb, 3, 'lobster: tôm hùm. Dịch cả câu: Việc hạn chế đánh bắt tôm hùm có thể bảo vệ các hệ sinh thái biển đồng thời duy trì sinh kế lâu dài cho các cộng đồng ven biển.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_22_21', 'en-b2-22', NULL, 'comprehensive_test', 'reading', NULL, 'Drivers should reduce their speed when mist limits visibility on rural roads during the early morning.', 'Dựa vào câu trên, từ “mist” có nghĩa phù hợp nhất là gì?', '["môn bắn cung; kỹ thuật bắn cung","sương mù mỏng; làn sương","sự phản đối; lời phản đối; ý kiến phản đối","phạm (tội hoặc sai lầm nghiêm trọng)"]'::jsonb, 1, 'mist: sương mù mỏng; làn sương; phủ sương; làm mờ (bằng hơi nước). Dịch cả câu: Người lái xe nên giảm tốc độ khi sương mù làm hạn chế tầm nhìn trên các tuyến đường nông thôn vào sáng sớm.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
