INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_22_24', 'en-b2-22', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cây hoa lily; hoa loa kèn; hoa bách hợp”', '["sin","lily","punch","sector"]'::jsonb, 1, 'cây hoa lily; hoa loa kèn; hoa bách hợp → lily (/ˈlɪli/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-23', 'en', 'Bài 23: Môi trường & Sinh thái (1) - CEFR B2', 'CEFR B2', 'B2 · Môi trường', '19 từ vựng Tiếng Anh CEFR B2 chủ đề môi trường & sinh thái kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4023, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shaded', 'en-b2-23', 'shaded', '/ˈʃeɪdɪd/', 'B2', 'có bóng râm; che râm; tránh nắng trực tiếp; được tô bóng; có đánh bóng mờ', 'adj.', 'shade (n.), shade (v.), shady (adj.), shading (n.)', 'Đồng nghĩa: shady · Trái nghĩa: sunlit', 'Cũng có thể dùng làm dạng quá khứ hoặc quá khứ phân từ của shade, diễn tả hành động che nắng.', 'We found a shaded bench beneath an old tree.', NULL, 'Chúng tôi tìm thấy một chiếc ghế dài có bóng râm dưới tán cây cổ thụ.', '{"wordId":"shaded","ukIpa":"/ˈʃeɪdɪd/","usIpa":"/ˈʃeɪdɪd/","cefr":"B2","topic":"environment","senses":[{"pos":"adj.","en":"Protected from direct sunlight.","vi":"có bóng râm; che râm; tránh nắng trực tiếp"},{"pos":"adj.","en":"Made darker with colour or drawn marks.","vi":"được tô bóng; có đánh bóng mờ"}],"examples":[{"en":"We found a shaded bench beneath an old tree.","vi":"Chúng tôi tìm thấy một chiếc ghế dài có bóng râm dưới tán cây cổ thụ.","audioKind":"ex"},{"en":"Providing shaded areas in public parks encourages outdoor activity during hot weather and reduces heat exposure.","vi":"Việc bố trí các khu vực có mái che hoặc bóng râm tại công viên công cộng giúp khuyến khích các hoạt động ngoài trời trong thời tiết nắng nóng và giảm thiểu tác động của nhiệt độ cao.","audioKind":"ex2"}],"collocations":[{"en":"shaded area","vi":"khu vực có bóng râm"},{"en":"shaded path","vi":"lối đi râm mát"},{"en":"shaded seating","vi":"chỗ ngồi có che nắng"}],"wordFamily":["shade (n.)","shade (v.)","shady (adj.)","shading (n.)"],"synonyms":["shady"],"antonyms":["sunlit"],"tipVi":"Cũng có thể dùng làm dạng quá khứ hoặc quá khứ phân từ của shade, diễn tả hành động che nắng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_agricultural', 'en-b2-23', 'agricultural', '/ˌæɡrɪˈkʌltʃərəl/', 'B2', 'thuộc về nông nghiệp', 'adj.', 'agriculture (n.), agriculturally (adv.)', NULL, 'Đây là tính từ, thường đi kèm với các danh từ như land, production, machinery.', 'The museum displays agricultural tools used by local farmers.', NULL, 'Bảo tàng trưng bày các dụng cụ nông nghiệp từng được sử dụng bởi nông dân địa phương.', '{"wordId":"agricultural","ukIpa":"/ˌæɡrɪˈkʌltʃərəl/","usIpa":"/ˌæɡrɪˈkʌltʃərəl/","cefr":"B2","topic":"environment","senses":[{"pos":"adj.","en":"relating to farming, including growing crops and raising animals","vi":"thuộc về nông nghiệp"}],"examples":[{"en":"The museum displays agricultural tools used by local farmers.","vi":"Bảo tàng trưng bày các dụng cụ nông nghiệp từng được sử dụng bởi nông dân địa phương.","audioKind":"ex"},{"en":"Modern agricultural practices can increase food production, but excessive chemical use may damage soil and water quality.","vi":"Các phương thức canh tác nông nghiệp hiện đại có thể nâng cao sản lượng lương thực, nhưng việc lạm dụng hóa chất có thể làm tổn hại đến chất lượng đất và nguồn nước.","audioKind":"ex2"}],"collocations":[{"en":"agricultural land","vi":"đất nông nghiệp"},{"en":"agricultural production","vi":"sản xuất nông nghiệp"},{"en":"agricultural machinery","vi":"máy móc nông nghiệp"},{"en":"agricultural practices","vi":"phương thức canh tác nông nghiệp"}],"wordFamily":["agriculture (n.)","agriculturally (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Đây là tính từ, thường đi kèm với các danh từ như land, production, machinery.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disposable', 'en-b2-23', 'disposable', '/dɪˈspoʊzəbl/', 'B2', 'dùng một lần; vứt đi sau khi dùng; có thể tùy ý sử dụng (sau khi đã trừ thuế)', 'adj.', 'dispose (v.), disposal (n.)', 'Đồng nghĩa: single-use, throwaway · Trái nghĩa: reusable', 'disposable income chỉ thu nhập sau thuế, không phải là số dư sau khi trừ đi chi phí sinh hoạt.', 'We packed disposable plates for the picnic by the lake.', NULL, 'Chúng tôi đã chuẩn bị những chiếc đĩa dùng một lần cho buổi dã ngoại bên hồ.', '{"wordId":"disposable","ukIpa":"/dɪˈspəʊzəbl/","usIpa":"/dɪˈspoʊzəbl/","cefr":"B2","topic":"environment","senses":[{"pos":"adj.","en":"intended to be thrown away after use","vi":"dùng một lần; vứt đi sau khi dùng"},{"pos":"adj.","en":"available for spending or saving after taxes are paid","vi":"có thể tùy ý sử dụng (sau khi đã trừ thuế)"}],"examples":[{"en":"We packed disposable plates for the picnic by the lake.","vi":"Chúng tôi đã chuẩn bị những chiếc đĩa dùng một lần cho buổi dã ngoại bên hồ.","audioKind":"ex"},{"en":"Reducing the use of disposable packaging could significantly decrease the amount of waste sent to landfill.","vi":"Việc giảm sử dụng bao bì dùng một lần có thể làm giảm đáng kể lượng rác thải đưa đến các bãi chôn lấp.","audioKind":"ex2"}],"collocations":[{"en":"disposable income","vi":"thu nhập khả dụng"},{"en":"disposable gloves","vi":"găng tay dùng một lần"},{"en":"disposable packaging","vi":"bao bì dùng một lần"},{"en":"disposable cups","vi":"cốc dùng một lần"}],"wordFamily":["dispose (v.)","disposal (n.)"],"synonyms":["single-use","throwaway"],"antonyms":["reusable"],"tipVi":"disposable income chỉ thu nhập sau thuế, không phải là số dư sau khi trừ đi chi phí sinh hoạt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_habitat', 'en-b2-23', 'habitat', '/ˈhæbɪtæt/', 'B2', 'môi trường sống; nơi sinh sống tự nhiên', 'n.', NULL, NULL, '''Habit'' là thói quen, còn ''habitat'' là môi trường sống của động thực vật.', 'This pond provides a perfect habitat for frogs.', NULL, 'Ao nước này cung cấp một môi trường sống lý tưởng cho loài ếch.', '{"wordId":"habitat","ukIpa":"/ˈhæbɪtæt/","usIpa":"/ˈhæbɪtæt/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"the natural environment where an animal or plant lives","vi":"môi trường sống; nơi sinh sống tự nhiên"}],"examples":[{"en":"This pond provides a perfect habitat for frogs.","vi":"Ao nước này cung cấp một môi trường sống lý tưởng cho loài ếch.","audioKind":"ex"},{"en":"Urban expansion destroys natural habitats, making it harder for native species to find food and shelter.","vi":"Sự mở rộng đô thị phá hủy các môi trường sống tự nhiên, khiến các loài bản địa ngày càng khó khăn hơn trong việc tìm kiếm thức ăn và nơi trú ẩn.","audioKind":"ex2"}],"collocations":[{"en":"natural habitat","vi":"môi trường sống tự nhiên"},{"en":"habitat loss","vi":"sự mất mát môi trường sống"},{"en":"habitat destruction","vi":"sự tàn phá môi trường sống"},{"en":"protect habitats","vi":"bảo vệ các môi trường sống"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"''Habit'' là thói quen, còn ''habitat'' là môi trường sống của động thực vật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_marine', 'en-b2-23', 'marine', '/məˈriːn/', 'B2', 'thuộc về biển; sinh vật biển; thuộc về hàng hải; vận tải biển; lính thủy đánh bộ', 'adj.', NULL, NULL, 'Marine thiên về biển; thuộc về hải quân thường dùng naval.', 'We watched a documentary about marine life last night.', NULL, 'Chúng tôi đã xem một bộ phim tài liệu về đời sống sinh vật biển tối qua.', '{"wordId":"marine","ukIpa":"/məˈriːn/","usIpa":"/məˈriːn/","cefr":"B2","topic":"environment","senses":[{"pos":"adj.","en":"Relating to the sea or organisms living in it","vi":"thuộc về biển; sinh vật biển"},{"pos":"adj.","en":"Relating to ships and transport by sea","vi":"thuộc về hàng hải; vận tải biển"},{"pos":"n.","en":"A soldier trained to serve on land and at sea","vi":"lính thủy đánh bộ"}],"examples":[{"en":"We watched a documentary about marine life last night.","vi":"Chúng tôi đã xem một bộ phim tài liệu về đời sống sinh vật biển tối qua.","audioKind":"ex"},{"en":"Plastic pollution threatens marine ecosystems and reduces the income of communities that depend on fishing.","vi":"Ô nhiễm nhựa đe dọa các hệ sinh thái biển và làm giảm thu nhập của các cộng đồng phụ thuộc vào nghề đánh bắt cá.","audioKind":"ex2"}],"collocations":[{"en":"marine life","vi":"sinh vật biển"},{"en":"marine ecosystem","vi":"hệ sinh thái biển"},{"en":"marine pollution","vi":"ô nhiễm môi trường biển"},{"en":"marine transport","vi":"vận tải biển"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Marine thiên về biển; thuộc về hải quân thường dùng naval.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_landfill', 'en-b2-23', 'landfill', '/ˈlændfɪl/', 'B2', 'bãi rác; bãi chôn lấp rác; việc chôn lấp rác thải', 'n.', NULL, NULL, 'Khi chỉ bãi rác thì đây là danh từ đếm được; khi chỉ phương pháp xử lý chôn lấp thì thường không đếm được.', 'The truck carried our rubbish to a nearby landfill.', NULL, 'Chiếc xe tải đã chở rác của chúng tôi đến bãi chôn lấp gần đó.', '{"wordId":"landfill","ukIpa":"/ˈlændfɪl/","usIpa":"/ˈlændfɪl/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"A place where waste is buried in the ground.","vi":"bãi rác; bãi chôn lấp rác"},{"pos":"n.","en":"The disposal of waste by burying it in the ground.","vi":"việc chôn lấp rác thải"}],"examples":[{"en":"The truck carried our rubbish to a nearby landfill.","vi":"Chiếc xe tải đã chở rác của chúng tôi đến bãi chôn lấp gần đó.","audioKind":"ex"},{"en":"Expanding recycling services could reduce the amount of household waste sent to landfill each year.","vi":"Việc mở rộng các dịch vụ tái chế có thể làm giảm lượng rác thải sinh hoạt đem đi chôn lấp mỗi năm.","audioKind":"ex2"}],"collocations":[{"en":"landfill site","vi":"bãi chôn lấp rác"},{"en":"send waste to landfill","vi":"đem rác đi chôn lấp"},{"en":"landfill capacity","vi":"dung tích bãi chôn lấp"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ bãi rác thì đây là danh từ đếm được; khi chỉ phương pháp xử lý chôn lấp thì thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dam', 'en-b2-23', 'dam', '/dæm/', 'B2', 'đập nước; đập ngăn nước; xây đập; chặn dòng nước', 'n.', NULL, NULL, 'dam là con đập chặn dòng nước; reservoir là hồ chứa nước.', 'We watched water rushing through the gates of the dam.', NULL, 'Chúng tôi đứng nhìn dòng nước cuồn cuộn chảy qua các cửa xả của con đập.', '{"wordId":"dam","ukIpa":"/dæm/","usIpa":"/dæm/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"A barrier across a river that holds back water.","vi":"đập nước; đập ngăn nước"},{"pos":"v.","en":"To block a river or stream with a barrier.","vi":"xây đập; chặn dòng nước"}],"examples":[{"en":"We watched water rushing through the gates of the dam.","vi":"Chúng tôi đứng nhìn dòng nước cuồn cuộn chảy qua các cửa xả của con đập.","audioKind":"ex"},{"en":"Building a dam can provide renewable electricity, but it may also disrupt river ecosystems and displace communities.","vi":"Việc xây dựng đập nước có thể cung cấp điện tái tạo, nhưng nó cũng có thể làm gián đoạn hệ sinh thái sông ngòi và buộc người dân phải di dời.","audioKind":"ex2"}],"collocations":[{"en":"build a dam","vi":"xây đập"},{"en":"a hydroelectric dam","vi":"đập thủy điện"},{"en":"dam a river","vi":"ngăn dòng sông bằng đập"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"dam là con đập chặn dòng nước; reservoir là hồ chứa nước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_polar', 'en-b2-23', 'polar', '/ˈpoʊlər/', 'B2', 'thuộc vùng cực; ở địa cực; hoàn toàn trái ngược', 'adj.', 'pole (n.), polarity (n.)', NULL, 'polar chỉ hai vùng cực; polar opposites mang nghĩa hoàn toàn trái ngược nhau.', 'We watched a film about animals in polar regions.', NULL, 'Chúng tôi đã xem một bộ phim về các loài động vật ở vùng cực.', '{"wordId":"polar","ukIpa":"/ˈpəʊlə/","usIpa":"/ˈpoʊlər/","cefr":"B2","topic":"environment","senses":[{"pos":"adj.","en":"Relating to the regions around the Earth''s poles.","vi":"thuộc vùng cực; ở địa cực"},{"pos":"adj.","en":"Completely opposite in character, direction, or opinion.","vi":"hoàn toàn trái ngược"}],"examples":[{"en":"We watched a film about animals in polar regions.","vi":"Chúng tôi đã xem một bộ phim về các loài động vật ở vùng cực.","audioKind":"ex"},{"en":"Rising global temperatures threaten polar ecosystems by reducing the sea ice that many species depend on.","vi":"Nhiệt độ toàn cầu tăng cao đe dọa các hệ sinh thái vùng cực bằng cách làm giảm lượng băng biển mà nhiều loài phụ thuộc vào.","audioKind":"ex2"}],"collocations":[{"en":"polar regions","vi":"các vùng cực"},{"en":"polar ice caps","vi":"chỏm băng ở vùng cực"},{"en":"polar bear","vi":"gấu Bắc Cực"},{"en":"polar opposites","vi":"những điều hoàn toàn trái ngược"}],"wordFamily":["pole (n.)","polarity (n.)"],"synonyms":[],"antonyms":[],"tipVi":"polar chỉ hai vùng cực; polar opposites mang nghĩa hoàn toàn trái ngược nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_renewable', 'en-b2-23', 'renewable', '/rɪˈnuːəbl/', 'B2', 'có thể tái tạo (năng lượng, tài nguyên); có thể gia hạn', 'adj.', 'renew (v.), renewal (n.), renewables (n.), non-renewable (adj.)', 'Trái nghĩa: non-renewable', 'Danh từ renewables thường dùng ở dạng số nhiều để chỉ các nguồn năng lượng tái tạo.', 'Our new solar panels provide renewable energy for the house.', NULL, 'Các tấm pin mặt trời mới của chúng tôi cung cấp năng lượng tái tạo cho ngôi nhà.', '{"wordId":"renewable","ukIpa":"/rɪˈnjuːəbl/","usIpa":"/rɪˈnuːəbl/","cefr":"B2","topic":"environment","senses":[{"pos":"adj.","en":"Naturally replaced and therefore available for continued use.","vi":"có thể tái tạo (năng lượng, tài nguyên)"},{"pos":"adj.","en":"Able to be extended for another period of time.","vi":"có thể gia hạn"}],"examples":[{"en":"Our new solar panels provide renewable energy for the house.","vi":"Các tấm pin mặt trời mới của chúng tôi cung cấp năng lượng tái tạo cho ngôi nhà.","audioKind":"ex"},{"en":"Investment in renewable energy can create jobs while reducing a country''s dependence on imported fossil fuels.","vi":"Đầu tư vào năng lượng tái tạo có thể tạo ra việc làm đồng thời giảm sự phụ thuộc của một quốc gia vào nhiên liệu hóa thạch nhập khẩu.","audioKind":"ex2"}],"collocations":[{"en":"renewable energy","vi":"năng lượng tái tạo"},{"en":"renewable resources","vi":"tài nguyên tái tạo"},{"en":"renewable sources","vi":"các nguồn tái tạo"},{"en":"renewable contract","vi":"hợp đồng có thể gia hạn"}],"wordFamily":["renew (v.)","renewal (n.)","renewables (n.)","non-renewable (adj.)"],"synonyms":[],"antonyms":["non-renewable"],"tipVi":"Danh từ renewables thường dùng ở dạng số nhiều để chỉ các nguồn năng lượng tái tạo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_emit', 'en-b2-23', 'emit', '/ɪˈmɪt/', 'B2', 'thải ra; phát ra; tỏa ra', 'v.', 'emission (n.), emitter (n.)', 'Đồng nghĩa: release, give off', 'Dạng quá khứ là "emitted" và dạng phân từ là "emitting", cả hai đều phải gấp đôi phụ âm "t".', 'These small lamps emit a soft, warm light.', NULL, 'Những chiếc đèn nhỏ này phát ra ánh sáng dịu nhẹ và ấm áp.', '{"wordId":"emit","ukIpa":"/ɪˈmɪt/","usIpa":"/ɪˈmɪt/","cefr":"B2","topic":"environment","senses":[{"pos":"v.","en":"to release gas, heat, light, or sound","vi":"thải ra; phát ra; tỏa ra"}],"examples":[{"en":"These small lamps emit a soft, warm light.","vi":"Những chiếc đèn nhỏ này phát ra ánh sáng dịu nhẹ và ấm áp.","audioKind":"ex"},{"en":"Factories that emit harmful gases should install cleaner technology to reduce their impact on public health.","vi":"Các nhà máy thải ra khí thải độc hại nên lắp đặt công nghệ sạch hơn để giảm thiểu tác động đến sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"emit light","vi":"phát sáng"},{"en":"emit radiation","vi":"phát bức xạ"},{"en":"emit greenhouse gases","vi":"thải khí nhà kính"}],"wordFamily":["emission (n.)","emitter (n.)"],"synonyms":["release","give off"],"antonyms":[],"tipVi":"Dạng quá khứ là \"emitted\" và dạng phân từ là \"emitting\", cả hai đều phải gấp đôi phụ âm \"t\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_organic', 'en-b2-23', 'organic', '/ɔːrˈɡænɪk/', 'B2', 'hữu cơ; canh tác hữu cơ; thuộc về sinh vật; gốc carbon; phát triển tự nhiên', 'adj.', 'organically (adv.), inorganic (adj.)', 'Trái nghĩa: inorganic', 'Trong ngữ cảnh thực phẩm, từ này chỉ sản phẩm canh tác tự nhiên; trong hóa học thường chỉ hợp chất chứa carbon.', 'She buys organic carrots from a nearby farm.', NULL, 'Cô ấy mua cà rốt hữu cơ từ một trang trại gần nhà.', '{"wordId":"organic","ukIpa":"/ɔːˈɡænɪk/","usIpa":"/ɔːrˈɡænɪk/","cefr":"B2","topic":"environment","senses":[{"pos":"adj.","en":"produced without artificial fertilizers or most synthetic pesticides","vi":"hữu cơ; canh tác hữu cơ"},{"pos":"adj.","en":"relating to living things or carbon-based substances","vi":"thuộc về sinh vật; gốc carbon"},{"pos":"adj.","en":"developing gradually and naturally rather than through outside intervention","vi":"phát triển tự nhiên"}],"examples":[{"en":"She buys organic carrots from a nearby farm.","vi":"Cô ấy mua cà rốt hữu cơ từ một trang trại gần nhà.","audioKind":"ex"},{"en":"Organic farming can support biodiversity, although its lower yields may require more land for food production.","vi":"Nông nghiệp hữu cơ có thể hỗ trợ đa dạng sinh học, dù năng suất thấp hơn có thể đòi hỏi nhiều đất đai hơn cho sản xuất lương thực.","audioKind":"ex2"}],"collocations":[{"en":"organic food","vi":"thực phẩm hữu cơ"},{"en":"organic farming","vi":"nông nghiệp hữu cơ"},{"en":"organic matter","vi":"chất hữu cơ"},{"en":"organic growth","vi":"sự tăng trưởng tự nhiên"}],"wordFamily":["organically (adv.)","inorganic (adj.)"],"synonyms":[],"antonyms":["inorganic"],"tipVi":"Trong ngữ cảnh thực phẩm, từ này chỉ sản phẩm canh tác tự nhiên; trong hóa học thường chỉ hợp chất chứa carbon.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fertilizer', 'en-b2-23', 'fertilizer', '/ˈfɝːtəlaɪzər/', 'B2', 'phân bón', 'n.', 'fertilize (v.), fertile (adj.), fertility (n.), fertilization (n.)', NULL, 'Tiếng Anh-Anh có thể viết là fertiliser; khi chỉ chung chung chất phân bón thì thường là danh từ không đếm được.', 'We added fertilizer to help the tomato plants grow.', NULL, 'Chúng tôi bón phân để giúp cây cà chua phát triển tốt.', '{"wordId":"fertilizer","ukIpa":"/ˈfɜːtəlaɪzə/","usIpa":"/ˈfɝːtəlaɪzər/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"a substance added to soil to help plants grow","vi":"phân bón"}],"examples":[{"en":"We added fertilizer to help the tomato plants grow.","vi":"Chúng tôi bón phân để giúp cây cà chua phát triển tốt.","audioKind":"ex"},{"en":"Excessive use of chemical fertilizer can pollute nearby rivers and damage the ecosystems that depend on them.","vi":"Việc lạm dụng phân bón hóa học có thể gây ô nhiễm các dòng sông lân cận và tàn phá hệ sinh thái phụ thuộc vào chúng.","audioKind":"ex2"}],"collocations":[{"en":"chemical fertilizer","vi":"phân bón hóa học"},{"en":"organic fertilizer","vi":"phân bón hữu cơ"},{"en":"apply fertilizer","vi":"bón phân"}],"wordFamily":["fertilize (v.)","fertile (adj.)","fertility (n.)","fertilization (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tiếng Anh-Anh có thể viết là fertiliser; khi chỉ chung chung chất phân bón thì thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_extinction', 'en-b2-23', 'extinction', '/ɪkˈstɪŋkʃən/', 'B2', 'sự tuyệt chủng; sự tiêu vong hoàn toàn', 'n.', 'extinct (adj.)', NULL, 'extinct là tính từ; còn extinction là danh từ thường không đếm được.', 'These rare birds face extinction if their forest disappears.', NULL, 'Những loài chim quý hiếm này sẽ đối mặt với nguy cơ tuyệt chủng nếu khu rừng của chúng biến mất.', '{"wordId":"extinction","ukIpa":"/ɪkˈstɪŋkʃən/","usIpa":"/ɪkˈstɪŋkʃən/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"the complete disappearance of a species or type of thing","vi":"sự tuyệt chủng; sự tiêu vong hoàn toàn"}],"examples":[{"en":"These rare birds face extinction if their forest disappears.","vi":"Những loài chim quý hiếm này sẽ đối mặt với nguy cơ tuyệt chủng nếu khu rừng của chúng biến mất.","audioKind":"ex"},{"en":"Protecting natural habitats is essential to preventing the extinction of species threatened by intensive farming and urban expansion.","vi":"Bảo vệ các sinh cảnh tự nhiên là điều cốt yếu để ngăn chặn tình trạng tuyệt chủng của các loài đang bị đe dọa bởi canh tác thâm canh và sự mở rộng đô thị.","audioKind":"ex2"}],"collocations":[{"en":"face extinction","vi":"đối mặt với nguy cơ tuyệt chủng"},{"en":"on the brink of extinction","vi":"bên bờ vực tuyệt chủng"},{"en":"mass extinction","vi":"tuyệt chủng hàng loạt"},{"en":"prevent extinction","vi":"ngăn chặn sự tuyệt chủng"}],"wordFamily":["extinct (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"extinct là tính từ; còn extinction là danh từ thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conservation', 'en-b2-23', 'conservation', '/ˌkɑːnsɚˈveɪʃən/', 'B2', 'bảo tồn thiên nhiên; bảo vệ động thực vật; sự tiết kiệm tài nguyên; bảo vệ tài nguyên; sự bảo tồn và trùng tu di tích', 'n.', 'conserve (v.), conservationist (n.)', 'Đồng nghĩa: preservation, protection', 'Thường là danh từ không đếm được; có thể chỉ việc bảo vệ thiên nhiên hoặc tiết kiệm năng lượng.', 'Our class joined a conservation project to protect local frogs.', NULL, 'Lớp chúng tôi đã tham gia một dự án bảo tồn nhằm bảo vệ loài ếch địa phương.', '{"wordId":"conservation","ukIpa":"/ˌkɒnsəˈveɪʃən/","usIpa":"/ˌkɑːnsɚˈveɪʃən/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"the protection of wildlife and natural environments","vi":"bảo tồn thiên nhiên; bảo vệ động thực vật"},{"pos":"n.","en":"careful use of resources to avoid waste","vi":"sự tiết kiệm tài nguyên; bảo vệ tài nguyên"},{"pos":"n.","en":"the protection and repair of valuable old objects or buildings","vi":"sự bảo tồn và trùng tu di tích"}],"examples":[{"en":"Our class joined a conservation project to protect local frogs.","vi":"Lớp chúng tôi đã tham gia một dự án bảo tồn nhằm bảo vệ loài ếch địa phương.","audioKind":"ex"},{"en":"Successful wildlife conservation requires cooperation between local communities, researchers, and governments over many years.","vi":"Công tác bảo tồn động vật hoang dã thành công đòi hỏi sự hợp tác lâu dài giữa các cộng đồng địa phương, các nhà nghiên cứu và chính phủ.","audioKind":"ex2"}],"collocations":[{"en":"wildlife conservation","vi":"bảo tồn động vật hoang dã"},{"en":"energy conservation","vi":"tiết kiệm năng lượng"},{"en":"water conservation","vi":"bảo vệ nguồn nước"},{"en":"conservation efforts","vi":"các nỗ lực bảo tồn"}],"wordFamily":["conserve (v.)","conservationist (n.)"],"synonyms":["preservation","protection"],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; có thể chỉ việc bảo vệ thiên nhiên hoặc tiết kiệm năng lượng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sustainable', 'en-b2-23', 'sustainable', '/səˈsteɪnəbl/', 'B2', 'bền vững; không gây hại môi trường; có thể duy trì lâu dài', 'adj.', 'sustain (v.), sustainability (n.), sustainably (adv.), unsustainable (adj.)', 'Trái nghĩa: unsustainable', 'renewable nhấn mạnh có thể tái tạo; sustainable nhấn mạnh tính bền vững.', 'She chooses sustainable products with little or no plastic packaging.', NULL, 'Cô ấy chọn các sản phẩm bền vững có ít hoặc không có bao bì nhựa.', '{"wordId":"sustainable","ukIpa":"/səˈsteɪnəbl/","usIpa":"/səˈsteɪnəbl/","cefr":"B2","topic":"environment","senses":[{"pos":"adj.","en":"Using resources without exhausting them or causing lasting environmental damage.","vi":"bền vững; không gây hại môi trường"},{"pos":"adj.","en":"Able to continue over a long period.","vi":"có thể duy trì lâu dài"}],"examples":[{"en":"She chooses sustainable products with little or no plastic packaging.","vi":"Cô ấy chọn các sản phẩm bền vững có ít hoặc không có bao bì nhựa.","audioKind":"ex"},{"en":"Cities should promote sustainable transport by investing in reliable bus services and safe cycling infrastructure.","vi":"Các thành phố nên thúc đẩy giao thông bền vững bằng cách đầu tư vào dịch vụ xe buýt đáng tin cậy và cơ sở hạ tầng đạp xe an toàn.","audioKind":"ex2"}],"collocations":[{"en":"sustainable development","vi":"phát triển bền vững"},{"en":"sustainable agriculture","vi":"nông nghiệp bền vững"},{"en":"sustainable transport","vi":"giao thông bền vững"},{"en":"sustainable growth","vi":"tăng trưởng bền vững"}],"wordFamily":["sustain (v.)","sustainability (n.)","sustainably (adv.)","unsustainable (adj.)"],"synonyms":[],"antonyms":["unsustainable"],"tipVi":"renewable nhấn mạnh có thể tái tạo; sustainable nhấn mạnh tính bền vững.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pesticide', 'en-b2-23', 'pesticide', '/ˈpestɪsaɪd/', 'B2', 'thuốc trừ sâu; thuốc bảo vệ thực vật', 'n.', 'pest (n.)', NULL, 'Pesticide chỉ chung các loại thuốc trừ sâu bệnh; insecticide chỉ riêng thuốc diệt côn trùng.', 'The farmer wore protective clothing while spraying pesticide on crops.', NULL, 'Người nông dân mặc đồ bảo hộ trong lúc phun thuốc trừ sâu cho mùa màng.', '{"wordId":"pesticide","ukIpa":"/ˈpestɪsaɪd/","usIpa":"/ˈpestɪsaɪd/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"A substance used to kill pests that damage crops.","vi":"thuốc trừ sâu; thuốc bảo vệ thực vật"}],"examples":[{"en":"The farmer wore protective clothing while spraying pesticide on crops.","vi":"Người nông dân mặc đồ bảo hộ trong lúc phun thuốc trừ sâu cho mùa màng.","audioKind":"ex"},{"en":"Excessive pesticide use can harm beneficial insects and contaminate water sources near agricultural land.","vi":"Việc sử dụng quá nhiều thuốc trừ sâu có thể gây hại cho côn trùng có ích và làm ô nhiễm nguồn nước gần đất nông nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"pesticide use","vi":"việc sử dụng thuốc trừ sâu"},{"en":"pesticide residues","vi":"dư lượng thuốc trừ sâu"},{"en":"spray pesticides","vi":"phun thuốc trừ sâu"},{"en":"reduce pesticide use","vi":"giảm thiểu việc dùng thuốc trừ sâu"}],"wordFamily":["pest (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Pesticide chỉ chung các loại thuốc trừ sâu bệnh; insecticide chỉ riêng thuốc diệt côn trùng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sewage', 'en-b2-23', 'sewage', '/ˈsuːɪdʒ/', 'B2', 'nước thải; chất thải sinh hoạt', 'n.', NULL, 'Đồng nghĩa: wastewater', 'Là danh từ không đếm được; sewage là nước thải, còn sewer mới là hệ thống cống ngầm.', 'Untreated sewage flowed into the river after the storm.', NULL, 'Nước thải chưa qua xử lý đã chảy thẳng xuống sông sau trận giông bão.', '{"wordId":"sewage","ukIpa":"/ˈsuːɪdʒ/","usIpa":"/ˈsuːɪdʒ/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"Wastewater and human waste carried away through drains","vi":"nước thải; chất thải sinh hoạt"}],"examples":[{"en":"Untreated sewage flowed into the river after the storm.","vi":"Nước thải chưa qua xử lý đã chảy thẳng xuống sông sau trận giông bão.","audioKind":"ex"},{"en":"Investing in modern sewage treatment facilities is essential for protecting freshwater ecosystems and maintaining public health.","vi":"Đầu tư vào các cơ sở xử lý nước thải hiện đại đóng vai trò thiết yếu trong việc bảo vệ hệ sinh thái nước ngọt và duy trì sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"raw sewage","vi":"nước thải thô (chưa xử lý)"},{"en":"sewage treatment","vi":"xử lý nước thải"},{"en":"sewage disposal","vi":"tiêu hủy nước thải"},{"en":"sewage system","vi":"hệ thống thoát nước thải"}],"wordFamily":[],"synonyms":["wastewater"],"antonyms":[],"tipVi":"Là danh từ không đếm được; sewage là nước thải, còn sewer mới là hệ thống cống ngầm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_surroundings', 'en-b2-23', 'surroundings', '/səˈraʊndɪŋz/', 'B2', 'vùng xung quanh; môi trường xung quanh', 'n.', 'surround (v.), surrounding (adj.)', 'Đồng nghĩa: environment', 'Luôn dùng ở dạng số nhiều (surroundings), khi làm chủ ngữ thì động từ theo sau cũng ở dạng số nhiều.', 'We ate lunch in the peaceful surroundings of the garden.', NULL, 'Chúng tôi ăn trưa giữa không gian yên bình của khu vườn.', '{"wordId":"surroundings","ukIpa":"/səˈraʊndɪŋz/","usIpa":"/səˈraʊndɪŋz/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"The places, objects, and conditions around a person or thing.","vi":"vùng xung quanh; môi trường xung quanh"}],"examples":[{"en":"We ate lunch in the peaceful surroundings of the garden.","vi":"Chúng tôi ăn trưa giữa không gian yên bình của khu vườn.","audioKind":"ex"},{"en":"Students may concentrate better in pleasant surroundings, especially when classrooms offer natural light and views of greenery.","vi":"Học sinh có thể tập trung tốt hơn trong những không gian dễ chịu, đặc biệt là khi lớp học có ánh sáng tự nhiên và tầm nhìn ra cây xanh.","audioKind":"ex2"}],"collocations":[{"en":"peaceful surroundings","vi":"môi trường xung quanh yên bình"},{"en":"natural surroundings","vi":"môi trường tự nhiên xung quanh"},{"en":"unfamiliar surroundings","vi":"khung cảnh xa lạ"},{"en":"pleasant surroundings","vi":"môi trường dễ chịu"}],"wordFamily":["surround (v.)","surrounding (adj.)"],"synonyms":["environment"],"antonyms":[],"tipVi":"Luôn dùng ở dạng số nhiều (surroundings), khi làm chủ ngữ thì động từ theo sau cũng ở dạng số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_consume', 'en-b2-23', 'consume', '/kənˈsuːm/', 'B2', 'tiêu thụ; tiêu tốn; ăn; uống; chiếm trọn tâm trí; tàn phá hoàn toàn', 'v.', 'consumer (n.), consumption (n.), consumable (adj.)', NULL, 'Khi dùng với nghĩa ăn uống thì mang tính trang trọng hơn các từ eat và drink; danh từ tương ứng là consumption.', 'Our old heater consumes too much electricity in winter.', NULL, 'Chiếc lò sưởi cũ của chúng tôi tiêu tốn quá nhiều điện năng vào mùa đông.', '{"wordId":"consume","ukIpa":"/kənˈsjuːm/","usIpa":"/kənˈsuːm/","cefr":"B2","topic":"environment","senses":[{"pos":"v.","en":"to use resources, energy, or time","vi":"tiêu thụ; tiêu tốn"},{"pos":"v.","en":"to eat food or drink liquids","vi":"ăn; uống"},{"pos":"v.","en":"to fill someone''s mind or destroy something completely","vi":"chiếm trọn tâm trí; tàn phá hoàn toàn"}],"examples":[{"en":"Our old heater consumes too much electricity in winter.","vi":"Chiếc lò sưởi cũ của chúng tôi tiêu tốn quá nhiều điện năng vào mùa đông.","audioKind":"ex"},{"en":"Households can reduce their environmental impact by consuming fewer resources and choosing products that last longer.","vi":"Các hộ gia đình có thể giảm thiểu tác động đến môi trường bằng cách tiêu thụ ít tài nguyên hơn và lựa chọn những sản phẩm có độ bền cao hơn.","audioKind":"ex2"}],"collocations":[{"en":"consume energy","vi":"tiêu thụ năng lượng"},{"en":"consume food","vi":"tiêu thụ thực phẩm"},{"en":"be consumed by fear","vi":"bị chi phối bởi nỗi sợ hãi"}],"wordFamily":["consumer (n.)","consumption (n.)","consumable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi dùng với nghĩa ăn uống thì mang tính trang trọng hơn các từ eat và drink; danh từ tương ứng là consumption.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_23_1', 'en-b2-23', 'Cách dùng “fertilizer” (n.) — phân bón', 'chemical fertilizer  ·  organic fertilizer  ·  apply fertilizer', 'Tiếng Anh-Anh có thể viết là fertiliser; khi chỉ chung chung chất phân bón thì thường là danh từ không đếm được.', 'Họ từ (Word Family): fertilize (v.), fertile (adj.), fertility (n.), fertilization (n.)', '[{"hanzi":"We added fertilizer to help the tomato plants grow.","pinyin":"","meaning":"Chúng tôi bón phân để giúp cây cà chua phát triển tốt."},{"hanzi":"Excessive use of chemical fertilizer can pollute nearby rivers and damage the ecosystems that depend on them.","pinyin":"","meaning":"Việc lạm dụng phân bón hóa học có thể gây ô nhiễm các dòng sông lân cận và tàn phá hệ sinh thái phụ thuộc vào chúng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_23_2', 'en-b2-23', 'Cách dùng “organic” (adj.) — hữu cơ; canh tác hữu cơ', 'organic food  ·  organic farming  ·  organic matter', 'Trong ngữ cảnh thực phẩm, từ này chỉ sản phẩm canh tác tự nhiên; trong hóa học thường chỉ hợp chất chứa carbon.', 'Họ từ (Word Family): organically (adv.), inorganic (adj.) | Trái nghĩa: inorganic', '[{"hanzi":"She buys organic carrots from a nearby farm.","pinyin":"","meaning":"Cô ấy mua cà rốt hữu cơ từ một trang trại gần nhà."},{"hanzi":"Organic farming can support biodiversity, although its lower yields may require more land for food production.","pinyin":"","meaning":"Nông nghiệp hữu cơ có thể hỗ trợ đa dạng sinh học, dù năng suất thấp hơn có thể đòi hỏi nhiều đất đai hơn cho sản xuất lương thực."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_23_3', 'en-b2-23', 'Cách dùng “consume” (v.) — tiêu thụ; tiêu tốn', 'consume energy  ·  consume food  ·  be consumed by fear', 'Khi dùng với nghĩa ăn uống thì mang tính trang trọng hơn các từ eat và drink; danh từ tương ứng là consumption.', 'Họ từ (Word Family): consumer (n.), consumption (n.), consumable (adj.)', '[{"hanzi":"Our old heater consumes too much electricity in winter.","pinyin":"","meaning":"Chiếc lò sưởi cũ của chúng tôi tiêu tốn quá nhiều điện năng vào mùa đông."},{"hanzi":"Households can reduce their environmental impact by consuming fewer resources and choosing products that last longer.","pinyin":"","meaning":"Các hộ gia đình có thể giảm thiểu tác động đến môi trường bằng cách tiêu thụ ít tài nguyên hơn và lựa chọn những sản phẩm có độ bền cao hơn."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_23_4', 'en-b2-23', 'Cách dùng “landfill” (n.) — bãi rác; bãi chôn lấp rác', 'landfill site  ·  send waste to landfill  ·  landfill capacity', 'Khi chỉ bãi rác thì đây là danh từ đếm được; khi chỉ phương pháp xử lý chôn lấp thì thường không đếm được.', NULL, '[{"hanzi":"The truck carried our rubbish to a nearby landfill.","pinyin":"","meaning":"Chiếc xe tải đã chở rác của chúng tôi đến bãi chôn lấp gần đó."},{"hanzi":"Expanding recycling services could reduce the amount of household waste sent to landfill each year.","pinyin":"","meaning":"Việc mở rộng các dịch vụ tái chế có thể làm giảm lượng rác thải sinh hoạt đem đi chôn lấp mỗi năm."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_23_1', 'en-b2-23', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_23_1_1', 'ten_b2_23_1', 'shaded', 'We found a shaded bench beneath an old tree.', 'We found a shaded bench beneath an old tree.', '/ˈʃeɪdɪd/', 'Chúng tôi tìm thấy một chiếc ghế dài có bóng râm dưới tán cây cổ thụ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_23_1_2', 'ten_b2_23_1', 'agricultural', 'The museum displays agricultural tools used by local farmers.', 'The museum displays agricultural tools used by local farmers.', '/ˌæɡrɪˈkʌltʃərəl/', 'Bảo tàng trưng bày các dụng cụ nông nghiệp từng được sử dụng bởi nông dân địa phương.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_23_1_3', 'ten_b2_23_1', 'disposable', 'We packed disposable plates for the picnic by the lake.', 'We packed disposable plates for the picnic by the lake.', '/dɪˈspoʊzəbl/', 'Chúng tôi đã chuẩn bị những chiếc đĩa dùng một lần cho buổi dã ngoại bên hồ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_23_1_4', 'ten_b2_23_1', 'habitat', 'This pond provides a perfect habitat for frogs.', 'This pond provides a perfect habitat for frogs.', '/ˈhæbɪtæt/', 'Ao nước này cung cấp một môi trường sống lý tưởng cho loài ếch.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_23_1_5', 'ten_b2_23_1', 'marine', 'We watched a documentary about marine life last night.', 'We watched a documentary about marine life last night.', '/məˈriːn/', 'Chúng tôi đã xem một bộ phim tài liệu về đời sống sinh vật biển tối qua.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_23_1_6', 'ten_b2_23_1', 'landfill', 'The truck carried our rubbish to a nearby landfill.', 'The truck carried our rubbish to a nearby landfill.', '/ˈlændfɪl/', 'Chiếc xe tải đã chở rác của chúng tôi đến bãi chôn lấp gần đó.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_23_1_7', 'ten_b2_23_1', 'dam', 'We watched water rushing through the gates of the dam.', 'We watched water rushing through the gates of the dam.', '/dæm/', 'Chúng tôi đứng nhìn dòng nước cuồn cuộn chảy qua các cửa xả của con đập.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_23_1_8', 'ten_b2_23_1', 'polar', 'We watched a film about animals in polar regions.', 'We watched a film about animals in polar regions.', '/ˈpoʊlər/', 'Chúng tôi đã xem một bộ phim về các loài động vật ở vùng cực.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_23_1_1', 'en-b2-23', 'ten_b2_23_1', 'listening', 'listening', 'We found a shaded bench beneath an old tree.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy chọn các sản phẩm bền vững có ít hoặc không có bao bì nhựa.","Những chiếc đèn nhỏ này phát ra ánh sáng dịu nhẹ và ấm áp.","Người nông dân mặc đồ bảo hộ trong lúc phun thuốc trừ sâu cho mùa màng.","Chúng tôi tìm thấy một chiếc ghế dài có bóng râm dưới tán cây cổ thụ."]'::jsonb, 3, 'We found a shaded bench beneath an old tree. → Chúng tôi tìm thấy một chiếc ghế dài có bóng râm dưới tán cây cổ thụ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_23_1_2', 'en-b2-23', 'ten_b2_23_1', 'listening', 'listening', 'The museum displays agricultural tools used by local farmers.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Người nông dân mặc đồ bảo hộ trong lúc phun thuốc trừ sâu cho mùa màng.","Cô ấy chọn các sản phẩm bền vững có ít hoặc không có bao bì nhựa.","Chúng tôi bón phân để giúp cây cà chua phát triển tốt.","Bảo tàng trưng bày các dụng cụ nông nghiệp từng được sử dụng bởi nông dân địa phương."]'::jsonb, 3, 'The museum displays agricultural tools used by local farmers. → Bảo tàng trưng bày các dụng cụ nông nghiệp từng được sử dụng bởi nông dân địa phương.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_23_1_3', 'en-b2-23', 'ten_b2_23_1', 'listening', 'listening', 'We packed disposable plates for the picnic by the lake.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã chuẩn bị những chiếc đĩa dùng một lần cho buổi dã ngoại bên hồ.","Lớp chúng tôi đã tham gia một dự án bảo tồn nhằm bảo vệ loài ếch địa phương.","Cô ấy mua cà rốt hữu cơ từ một trang trại gần nhà.","Chiếc lò sưởi cũ của chúng tôi tiêu tốn quá nhiều điện năng vào mùa đông."]'::jsonb, 0, 'We packed disposable plates for the picnic by the lake. → Chúng tôi đã chuẩn bị những chiếc đĩa dùng một lần cho buổi dã ngoại bên hồ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_23_2', 'en-b2-23', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_23_2_1', 'ten_b2_23_2', 'shaded', 'Providing shaded areas in public parks encourages outdoor activity during hot weather and reduces heat exposure.', 'Providing shaded areas in public parks encourages outdoor activity during hot weather and reduces heat exposure.', '/ˈʃeɪdɪd/', 'Việc bố trí các khu vực có mái che hoặc bóng râm tại công viên công cộng giúp khuyến khích các hoạt động ngoài trời trong thời tiết nắng nóng và giảm thiểu tác động của nhiệt độ cao.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_23_2_2', 'ten_b2_23_2', 'agricultural', 'Modern agricultural practices can increase food production, but excessive chemical use may damage soil and water quality.', 'Modern agricultural practices can increase food production, but excessive chemical use may damage soil and water quality.', '/ˌæɡrɪˈkʌltʃərəl/', 'Các phương thức canh tác nông nghiệp hiện đại có thể nâng cao sản lượng lương thực, nhưng việc lạm dụng hóa chất có thể làm tổn hại đến chất lượng đất và nguồn nước.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_23_2_3', 'ten_b2_23_2', 'disposable', 'Reducing the use of disposable packaging could significantly decrease the amount of waste sent to landfill.', 'Reducing the use of disposable packaging could significantly decrease the amount of waste sent to landfill.', '/dɪˈspoʊzəbl/', 'Việc giảm sử dụng bao bì dùng một lần có thể làm giảm đáng kể lượng rác thải đưa đến các bãi chôn lấp.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_23_2_4', 'ten_b2_23_2', 'habitat', 'Urban expansion destroys natural habitats, making it harder for native species to find food and shelter.', 'Urban expansion destroys natural habitats, making it harder for native species to find food and shelter.', '/ˈhæbɪtæt/', 'Sự mở rộng đô thị phá hủy các môi trường sống tự nhiên, khiến các loài bản địa ngày càng khó khăn hơn trong việc tìm kiếm thức ăn và nơi trú ẩn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_23_2_5', 'ten_b2_23_2', 'marine', 'Plastic pollution threatens marine ecosystems and reduces the income of communities that depend on fishing.', 'Plastic pollution threatens marine ecosystems and reduces the income of communities that depend on fishing.', '/məˈriːn/', 'Ô nhiễm nhựa đe dọa các hệ sinh thái biển và làm giảm thu nhập của các cộng đồng phụ thuộc vào nghề đánh bắt cá.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_23_2_6', 'ten_b2_23_2', 'landfill', 'Expanding recycling services could reduce the amount of household waste sent to landfill each year.', 'Expanding recycling services could reduce the amount of household waste sent to landfill each year.', '/ˈlændfɪl/', 'Việc mở rộng các dịch vụ tái chế có thể làm giảm lượng rác thải sinh hoạt đem đi chôn lấp mỗi năm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_23_2_1', 'en-b2-23', 'ten_b2_23_2', 'listening', 'listening', 'Providing shaded areas in public parks encourages outdoor activity during hot weather and reduces heat exposure.', NULL, 'Trong câu vừa nghe, từ “shaded” mang nghĩa nào sau đây?', '["tuyệt vời, tuyệt diệu","tại cửa hàng; trong cửa hàng (vật lý)","hàm; xương hàm","có bóng râm; che râm; tránh nắng trực tiếp"]'::jsonb, 3, '“shaded” (/ˈʃeɪdɪd/): có bóng râm; che râm; tránh nắng trực tiếp. Câu đầy đủ: Providing shaded areas in public parks encourages outdoor activity during hot weather and reduces heat exposure.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_23_2_2', 'en-b2-23', 'ten_b2_23_2', 'listening', 'listening', 'Modern agricultural practices can increase food production, but excessive chemical use may damage soil and water quality.', NULL, 'Trong câu vừa nghe, từ “agricultural” mang nghĩa nào sau đây?', '["làm mềm; trở nên mềm hơn","thuộc về nông nghiệp","liên tục; không ngừng","kinh điển; có giá trị lâu bền"]'::jsonb, 1, '“agricultural” (/ˌæɡrɪˈkʌltʃərəl/): thuộc về nông nghiệp. Câu đầy đủ: Modern agricultural practices can increase food production, but excessive chemical use may damage soil and water quality.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
