INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_23_1', 'en-b2-23', NULL, 'comprehensive_test', 'listening', 'shaded', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["khoản trợ cấp, tiền cấp phát từ một tổ chức cho mục đích cụ thể","chứng trầm cảm; sự trầm uất","có bóng râm; che râm; tránh nắng trực tiếp","chất bột đường; cacbohydrat"]'::jsonb, 2, 'shaded (/ˈʃeɪdɪd/) → có bóng râm; che râm; tránh nắng trực tiếp; được tô bóng; có đánh bóng mờ', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_23_2', 'en-b2-23', NULL, 'comprehensive_test', 'listening', 'The museum displays agricultural tools used by local farmers.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những loài chim quý hiếm này sẽ đối mặt với nguy cơ tuyệt chủng nếu khu rừng của chúng biến mất.","Bảo tàng trưng bày các dụng cụ nông nghiệp từng được sử dụng bởi nông dân địa phương.","Chúng tôi ăn trưa giữa không gian yên bình của khu vườn.","Cô ấy mua cà rốt hữu cơ từ một trang trại gần nhà."]'::jsonb, 1, 'The museum displays agricultural tools used by local farmers. → Bảo tàng trưng bày các dụng cụ nông nghiệp từng được sử dụng bởi nông dân địa phương.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_23_3', 'en-b2-23', NULL, 'comprehensive_test', 'listening', 'disposable', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["mọc lông tơ; mềm mại","dùng một lần; vứt đi sau khi dùng","thịnh vượng; phát đạt; giàu có","hương thơm; mùi thơm dễ chịu"]'::jsonb, 1, 'disposable (/dɪˈspoʊzəbl/) → dùng một lần; vứt đi sau khi dùng; có thể tùy ý sử dụng (sau khi đã trừ thuế)', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_23_4', 'en-b2-23', NULL, 'comprehensive_test', 'listening', 'This pond provides a perfect habitat for frogs.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ao nước này cung cấp một môi trường sống lý tưởng cho loài ếch.","Những loài chim quý hiếm này sẽ đối mặt với nguy cơ tuyệt chủng nếu khu rừng của chúng biến mất.","Chúng tôi đứng nhìn dòng nước cuồn cuộn chảy qua các cửa xả của con đập.","Bảo tàng trưng bày các dụng cụ nông nghiệp từng được sử dụng bởi nông dân địa phương."]'::jsonb, 0, 'This pond provides a perfect habitat for frogs. → Ao nước này cung cấp một môi trường sống lý tưởng cho loài ếch.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_23_5', 'en-b2-23', NULL, 'comprehensive_test', 'listening', 'marine', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["số mệnh; định mệnh","cầu phước; ban phúc","thuộc về biển; sinh vật biển","kỳ quan; điều kỳ diệu"]'::jsonb, 2, 'marine (/məˈriːn/) → thuộc về biển; sinh vật biển; thuộc về hàng hải; vận tải biển; lính thủy đánh bộ', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_23_6', 'en-b2-23', NULL, 'comprehensive_test', 'listening', 'The truck carried our rubbish to a nearby landfill.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chiếc xe tải đã chở rác của chúng tôi đến bãi chôn lấp gần đó.","Những chiếc đèn nhỏ này phát ra ánh sáng dịu nhẹ và ấm áp.","Các tấm pin mặt trời mới của chúng tôi cung cấp năng lượng tái tạo cho ngôi nhà.","Chúng tôi đã chuẩn bị những chiếc đĩa dùng một lần cho buổi dã ngoại bên hồ."]'::jsonb, 0, 'The truck carried our rubbish to a nearby landfill. → Chiếc xe tải đã chở rác của chúng tôi đến bãi chôn lấp gần đó.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_23_7', 'en-b2-23', NULL, 'comprehensive_test', 'listening', 'dam', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["vải bạt; loại vải dày, chắc dùng cho lều, túi và buồm","ảo (tạo bởi máy tính hoặc qua mạng)","đập nước; đập ngăn nước","bác sĩ phẫu thuật"]'::jsonb, 2, 'dam (/dæm/) → đập nước; đập ngăn nước; xây đập; chặn dòng nước', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_23_8', 'en-b2-23', NULL, 'comprehensive_test', 'listening', 'We watched a film about animals in polar regions.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đứng nhìn dòng nước cuồn cuộn chảy qua các cửa xả của con đập.","Chúng tôi đã xem một bộ phim về các loài động vật ở vùng cực.","Chúng tôi ăn trưa giữa không gian yên bình của khu vườn.","Bảo tàng trưng bày các dụng cụ nông nghiệp từng được sử dụng bởi nông dân địa phương."]'::jsonb, 1, 'We watched a film about animals in polar regions. → Chúng tôi đã xem một bộ phim về các loài động vật ở vùng cực.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
