INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_23_18', 'en-b2-23', NULL, 'comprehensive_test', 'reading', NULL, 'Providing shaded areas in public parks encourages outdoor activity during hot weather and reduces heat exposure.', 'Dựa vào câu trên, từ “shaded” có nghĩa phù hợp nhất là gì?', '["có bóng râm; che râm; tránh nắng trực tiếp","lâu dài; bền vững; kéo dài","sự hình thành; sự thành lập","có tính chiếm hữu; ích kỷ trong quan hệ"]'::jsonb, 0, 'shaded: có bóng râm; che râm; tránh nắng trực tiếp; được tô bóng; có đánh bóng mờ. Dịch cả câu: Việc bố trí các khu vực có mái che hoặc bóng râm tại công viên công cộng giúp khuyến khích các hoạt động ngoài trời trong thời tiết nắng nóng và giảm thiểu tác động của nhiệt độ cao.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_23_19', 'en-b2-23', NULL, 'comprehensive_test', 'reading', NULL, 'Modern agricultural practices can increase food production, but excessive chemical use may damage soil and water quality.', 'Dựa vào câu trên, từ “agricultural” có nghĩa phù hợp nhất là gì?', '["thuộc về nông nghiệp","riêng biệt; đặc biệt, chuyên dụng","vô cùng ngốc nghếch; phi lý; nguy hiểm","ngày càng; càng lúc càng"]'::jsonb, 0, 'agricultural: thuộc về nông nghiệp. Dịch cả câu: Các phương thức canh tác nông nghiệp hiện đại có thể nâng cao sản lượng lương thực, nhưng việc lạm dụng hóa chất có thể làm tổn hại đến chất lượng đất và nguồn nước.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_23_20', 'en-b2-23', NULL, 'comprehensive_test', 'reading', NULL, 'Reducing the use of disposable packaging could significantly decrease the amount of waste sent to landfill.', 'Dựa vào câu trên, từ “disposable” có nghĩa phù hợp nhất là gì?', '["dùng một lần; vứt đi sau khi dùng","đề cương; dàn ý; bản tóm tắt","hẻo lánh; xa xôi","thỏa đáng; đạt yêu cầu; đủ tiêu chuẩn"]'::jsonb, 0, 'disposable: dùng một lần; vứt đi sau khi dùng; có thể tùy ý sử dụng (sau khi đã trừ thuế). Dịch cả câu: Việc giảm sử dụng bao bì dùng một lần có thể làm giảm đáng kể lượng rác thải đưa đến các bãi chôn lấp.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_23_21', 'en-b2-23', NULL, 'comprehensive_test', 'reading', NULL, 'Urban expansion destroys natural habitats, making it harder for native species to find food and shelter.', 'Dựa vào câu trên, từ “habitat” có nghĩa phù hợp nhất là gì?', '["nói tục; chửi thề","môi trường sống; nơi sinh sống tự nhiên","khác biệt; tách biệt","sự có mặt; sự hiện diện"]'::jsonb, 1, 'habitat: môi trường sống; nơi sinh sống tự nhiên. Dịch cả câu: Sự mở rộng đô thị phá hủy các môi trường sống tự nhiên, khiến các loài bản địa ngày càng khó khăn hơn trong việc tìm kiếm thức ăn và nơi trú ẩn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_23_22', 'en-b2-23', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nước thải; chất thải sinh hoạt”', '["moped","downward","sewage","commission"]'::jsonb, 2, 'nước thải; chất thải sinh hoạt → sewage (/ˈsuːɪdʒ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_23_23', 'en-b2-23', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “vùng xung quanh; môi trường xung quanh”', '["upon","decimal","surroundings","footstep"]'::jsonb, 2, 'vùng xung quanh; môi trường xung quanh → surroundings (/səˈraʊndɪŋz/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_23_24', 'en-b2-23', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tiêu thụ; tiêu tốn”', '["skinny","consume","division","migrate"]'::jsonb, 1, 'tiêu thụ; tiêu tốn → consume (/kənˈsuːm/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-24', 'en', 'Bài 24: Môi trường & Sinh thái (2) - CEFR B2', 'CEFR B2', 'B2 · Môi trường', '19 từ vựng Tiếng Anh CEFR B2 chủ đề môi trường & sinh thái kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4024, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_threat', 'en-b2-24', 'threat', '/θret/', 'B2', 'mối đe dọa; nguy cơ tiềm ẩn; lời đe dọa; sự hăm dọa', 'n.', 'threaten (v.), threatening (adj.)', 'Đồng nghĩa: danger, menace', 'Dùng danh từ "threat"; nếu là động từ hãy dùng "threaten".', 'The rising river poses a threat to our village.', NULL, 'Mực nước sông dâng cao đang gây ra mối đe dọa cho ngôi làng của chúng ta.', '{"wordId":"threat","ukIpa":"/θret/","usIpa":"/θret/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"Something that could cause harm or damage.","vi":"mối đe dọa; nguy cơ tiềm ẩn"},{"pos":"n.","en":"A statement expressing an intention to cause harm.","vi":"lời đe dọa; sự hăm dọa"}],"examples":[{"en":"The rising river poses a threat to our village.","vi":"Mực nước sông dâng cao đang gây ra mối đe dọa cho ngôi làng của chúng ta.","audioKind":"ex"},{"en":"Habitat destruction remains a major threat to biodiversity, particularly in regions experiencing rapid agricultural expansion.","vi":"Sự tàn phá môi trường sống vẫn là mối đe dọa lớn đối với đa dạng sinh học, đặc biệt ở các khu vực đang mở rộng diện tích nông nghiệp nhanh chóng.","audioKind":"ex2"}],"collocations":[{"en":"pose a threat to","vi":"gây ra mối đe dọa cho"},{"en":"under threat","vi":"đang bị đe dọa"},{"en":"make a threat","vi":"đưa ra lời đe dọa"},{"en":"a serious threat","vi":"mối đe dọa nghiêm trọng"}],"wordFamily":["threaten (v.)","threatening (adj.)"],"synonyms":["danger","menace"],"antonyms":[],"tipVi":"Dùng danh từ \"threat\"; nếu là động từ hãy dùng \"threaten\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disposal', 'en-b2-24', 'disposal', '/dɪˈspoʊzəl/', 'B2', 'sự vứt bỏ; sự xử lý; sự sẵn có để sử dụng', 'n.', 'dispose (v.), disposable (adj.)', NULL, 'at someone''s disposal diễn tả nghĩa sẵn sàng phục vụ cho ai sử dụng hoặc định đoạt.', 'The council provides bins for the disposal of batteries.', NULL, 'Hội đồng thành phố cung cấp các thùng chứa để xử lý pin thải.', '{"wordId":"disposal","ukIpa":"/dɪˈspəʊzəl/","usIpa":"/dɪˈspoʊzəl/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"The process of getting rid of unwanted things","vi":"sự vứt bỏ; sự xử lý"},{"pos":"n.","en":"The state of being available for someone''s use","vi":"sự sẵn có để sử dụng"}],"examples":[{"en":"The council provides bins for the disposal of batteries.","vi":"Hội đồng thành phố cung cấp các thùng chứa để xử lý pin thải.","audioKind":"ex"},{"en":"Safe waste disposal is essential for protecting groundwater and reducing health risks in densely populated areas.","vi":"Việc xử lý chất thải an toàn là rất quan trọng để bảo vệ nước ngầm và giảm thiểu rủi ro sức khỏe ở các khu vực đông dân cư.","audioKind":"ex2"}],"collocations":[{"en":"waste disposal","vi":"xử lý chất thải"},{"en":"safe disposal","vi":"xử lý an toàn"},{"en":"at your disposal","vi":"tùy bạn sử dụng"}],"wordFamily":["dispose (v.)","disposable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"at someone''s disposal diễn tả nghĩa sẵn sàng phục vụ cho ai sử dụng hoặc định đoạt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pollutant', 'en-b2-24', 'pollutant', '/pəˈluːtənt/', 'B2', 'chất gây ô nhiễm', 'n.', 'pollute (v.), pollution (n.), polluted (adj.)', NULL, 'pollutant chỉ chất ô nhiễm cụ thể, là danh từ đếm được; pollution chỉ tình trạng ô nhiễm.', 'This filter removes harmful pollutants from our drinking water.', NULL, 'Bộ lọc này loại bỏ các chất ô nhiễm có hại ra khỏi nguồn nước uống của chúng ta.', '{"wordId":"pollutant","ukIpa":"/pəˈluːtənt/","usIpa":"/pəˈluːtənt/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"A substance that makes air, water, or soil dirty or harmful.","vi":"chất gây ô nhiễm"}],"examples":[{"en":"This filter removes harmful pollutants from our drinking water.","vi":"Bộ lọc này loại bỏ các chất ô nhiễm có hại ra khỏi nguồn nước uống của chúng ta.","audioKind":"ex"},{"en":"Stricter controls on industrial pollutants could improve air quality and reduce respiratory illness in urban areas.","vi":"Việc kiểm soát chặt chẽ hơn các chất ô nhiễm công nghiệp có thể cải thiện chất lượng không khí và giảm các bệnh về đường hô hấp ở khu vực đô thị.","audioKind":"ex2"}],"collocations":[{"en":"air pollutant","vi":"chất ô nhiễm không khí"},{"en":"harmful pollutants","vi":"chất ô nhiễm có hại"},{"en":"industrial pollutants","vi":"chất ô nhiễm công nghiệp"}],"wordFamily":["pollute (v.)","pollution (n.)","polluted (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"pollutant chỉ chất ô nhiễm cụ thể, là danh từ đếm được; pollution chỉ tình trạng ô nhiễm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_erode', 'en-b2-24', 'erode', '/ɪˈroʊd/', 'B2', 'bị xói mòn; bị bào mòn; làm xói mòn; làm suy yếu dần', 'v.', 'erosion (n.), erosive (adj.)', 'Đồng nghĩa: wear away, undermine · Trái nghĩa: strengthen', 'Có thể dùng cho hiện tượng tự nhiên, hoặc chỉ sự suy giảm của lòng tin, giá trị.', 'Strong waves have eroded the cliffs near our village.', NULL, 'Những con sóng mạnh đã làm xói mòn các vách đá gần làng chúng tôi.', '{"wordId":"erode","ukIpa":"/ɪˈrəʊd/","usIpa":"/ɪˈroʊd/","cefr":"B2","topic":"environment","senses":[{"pos":"v.","en":"To gradually wear away soil or rock through natural forces.","vi":"bị xói mòn; bị bào mòn"},{"pos":"v.","en":"To gradually reduce strength, value, or confidence.","vi":"làm xói mòn; làm suy yếu dần"}],"examples":[{"en":"Strong waves have eroded the cliffs near our village.","vi":"Những con sóng mạnh đã làm xói mòn các vách đá gần làng chúng tôi.","audioKind":"ex"},{"en":"Persistent inflation can erode household savings, making it harder for families to afford essential goods.","vi":"Lạm phát kéo dài có thể làm xói mòn tiền tiết kiệm của hộ gia đình, khiến các gia đình khó chi trả cho các mặt hàng thiết yếu hơn.","audioKind":"ex2"}],"collocations":[{"en":"erode the soil","vi":"xói mòn đất"},{"en":"erode public trust","vi":"làm xói mòn lòng tin của công chúng"},{"en":"erode purchasing power","vi":"làm giảm sức mua"},{"en":"coastal erosion","vi":"sự xói mòn bờ biển"}],"wordFamily":["erosion (n.)","erosive (adj.)"],"synonyms":["wear away","undermine"],"antonyms":["strengthen"],"tipVi":"Có thể dùng cho hiện tượng tự nhiên, hoặc chỉ sự suy giảm của lòng tin, giá trị.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plough', 'en-b2-24', 'plough', '/plaʊ/', 'B2', 'cái cày; cày ruộng; cày đất', 'n.', 'ploughing (n.), ploughman (n.)', NULL, 'Kiểu Mỹ viết là plow; cả hai cách viết đều phát âm là /plaʊ/.', 'The farmer pulled an old plough from the shed.', NULL, 'Người nông dân lôi một chiếc cày cũ ra khỏi nhà kho.', '{"wordId":"plough","ukIpa":"/plaʊ/","usIpa":"/plaʊ/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"A farm tool that turns soil before crops are planted","vi":"cái cày"},{"pos":"v.","en":"To turn soil with a plough before planting","vi":"cày ruộng; cày đất"}],"examples":[{"en":"The farmer pulled an old plough from the shed.","vi":"Người nông dân lôi một chiếc cày cũ ra khỏi nhà kho.","audioKind":"ex"},{"en":"Farmers who plough steep slopes too frequently may increase soil erosion and reduce long-term agricultural productivity.","vi":"Những người nông dân cày xới các sườn dốc quá thường xuyên có thể làm tăng xói mòn đất và làm giảm năng suất nông nghiệp lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"plough a field","vi":"cày một thửa ruộng"},{"en":"a horse-drawn plough","vi":"cái cày kéo bằng ngựa"},{"en":"plough through","vi":"vượt qua khó khăn; cày miệt mài"}],"wordFamily":["ploughing (n.)","ploughman (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Kiểu Mỹ viết là plow; cả hai cách viết đều phát âm là /plaʊ/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_footprint', 'en-b2-24', 'footprint', '/ˈfʊtprɪnt/', 'B2', 'dấu chân; diện tích chiếm chỗ; không gian chiếm dụng; dấu chân sinh thái; tác động môi trường', 'n.', NULL, NULL, 'carbon footprint chỉ mức độ ảnh hưởng carbon đến môi trường, không phải là dấu chân vật lý.', 'A muddy footprint covered the clean kitchen floor.', NULL, 'Một dấu chân dính bùn in trên sàn nhà bếp sạch bóng.', '{"wordId":"footprint","ukIpa":"/ˈfʊtprɪnt/","usIpa":"/ˈfʊtprɪnt/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"A mark left by a foot on a surface.","vi":"dấu chân"},{"pos":"n.","en":"The amount of ground or space something occupies.","vi":"diện tích chiếm chỗ; không gian chiếm dụng"},{"pos":"n.","en":"The environmental impact of a person, product, or activity.","vi":"dấu chân sinh thái; tác động môi trường"}],"examples":[{"en":"A muddy footprint covered the clean kitchen floor.","vi":"Một dấu chân dính bùn in trên sàn nhà bếp sạch bóng.","audioKind":"ex"},{"en":"Choosing locally grown food can sometimes reduce the carbon footprint associated with transporting agricultural products.","vi":"Việc lựa chọn thực phẩm trồng tại địa phương đôi khi có thể làm giảm lượng khí thải carbon liên quan đến việc vận chuyển nông sản.","audioKind":"ex2"}],"collocations":[{"en":"leave footprints","vi":"để lại dấu chân"},{"en":"carbon footprint","vi":"dấu chân carbon"},{"en":"a small footprint","vi":"diện tích chiếm chỗ nhỏ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"carbon footprint chỉ mức độ ảnh hưởng carbon đến môi trường, không phải là dấu chân vật lý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_livestock', 'en-b2-24', 'livestock', '/ˈlaɪvstɑːk/', 'B2', 'gia súc; vật nuôi', 'n.', NULL, 'Đồng nghĩa: farm animals', 'Là danh từ tập hợp, không thêm -s; chỉ các loài vật nuôi trang trại còn sống.', 'The farmer moved the livestock into a sheltered field.', NULL, 'Người nông dân lùa đàn gia súc vào một khu đồng có mái che.', '{"wordId":"livestock","ukIpa":"/ˈlaɪvstɒk/","usIpa":"/ˈlaɪvstɑːk/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"farm animals kept for food, materials, or work","vi":"gia súc; vật nuôi"}],"examples":[{"en":"The farmer moved the livestock into a sheltered field.","vi":"Người nông dân lùa đàn gia súc vào một khu đồng có mái che.","audioKind":"ex"},{"en":"Raising livestock requires substantial land and water resources, which can increase pressure on ecosystems in dry regions.","vi":"Việc chăn nuôi gia súc đòi hỏi nguồn tài nguyên đất và nước đáng kể, điều này có thể làm gia tăng áp lực lên hệ sinh thái ở các vùng khô hạn.","audioKind":"ex2"}],"collocations":[{"en":"raise livestock","vi":"chăn nuôi gia súc"},{"en":"livestock farming","vi":"ngành chăn nuôi"},{"en":"livestock feed","vi":"thức ăn cho gia súc"},{"en":"livestock production","vi":"sản xuất chăn nuôi"}],"wordFamily":[],"synonyms":["farm animals"],"antonyms":[],"tipVi":"Là danh từ tập hợp, không thêm -s; chỉ các loài vật nuôi trang trại còn sống.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_adaptation', 'en-b2-24', 'adaptation', '/ˌædæpˈteɪʃən/', 'B2', 'sự thích nghi; tính thích nghi; tác phẩm chuyển thể (như phim ảnh); sự cải biên; sự điều chỉnh', 'n.', 'adapt (v.), adaptable (adj.), adaptive (adj.), adaptability (n.)', 'Đồng nghĩa: adjustment', 'Thích nghi với việc gì dùng adaptation to; chuyển thể từ cái gì dùng adaptation of.', 'Our adaptation to the colder weather took several weeks.', NULL, 'Việc chúng tôi thích nghi với thời tiết lạnh hơn mất vài tuần.', '{"wordId":"adaptation","ukIpa":"/ˌædæpˈteɪʃən/","usIpa":"/ˌædæpˈteɪʃən/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"The process of changing to suit new conditions.","vi":"sự thích nghi; tính thích nghi"},{"pos":"n.","en":"A work changed into another form, such as a film.","vi":"tác phẩm chuyển thể (như phim ảnh)"},{"pos":"n.","en":"A change made to something to suit a particular purpose.","vi":"sự cải biên; sự điều chỉnh"}],"examples":[{"en":"Our adaptation to the colder weather took several weeks.","vi":"Việc chúng tôi thích nghi với thời tiết lạnh hơn mất vài tuần.","audioKind":"ex"},{"en":"Climate adaptation requires governments to improve flood defences and support communities facing increasingly frequent extreme weather.","vi":"Sự thích ứng với biến đổi khí hậu đòi hỏi các chính phủ phải cải thiện các công trình phòng chống lũ lụt và hỗ trợ các cộng đồng đối mặt với thời tiết cực đoan ngày càng thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"adaptation to change","vi":"sự thích nghi với sự thay đổi"},{"en":"climate adaptation","vi":"thích ứng với khí hậu"},{"en":"a film adaptation","vi":"một bộ phim chuyển thể"},{"en":"evolutionary adaptation","vi":"sự thích nghi tiến hóa"}],"wordFamily":["adapt (v.)","adaptable (adj.)","adaptive (adj.)","adaptability (n.)"],"synonyms":["adjustment"],"antonyms":[],"tipVi":"Thích nghi với việc gì dùng adaptation to; chuyển thể từ cái gì dùng adaptation of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_smog', 'en-b2-24', 'smog', '/smɑːɡ/', 'B2', 'khói bụi ô nhiễm; sương mù quang hóa', 'n.', 'smoggy (adj.)', NULL, 'Thường là danh từ không đếm được; smog chỉ khói bụi ô nhiễm chứ không phải sương mù tự nhiên.', 'Thick smog hid the hills beyond our apartment.', NULL, 'Lớp sương mù dày đặc che khuất những ngọn đồi phía sau căn hộ của chúng tôi.', '{"wordId":"smog","ukIpa":"/smɒɡ/","usIpa":"/smɑːɡ/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"Polluted air forming a thick cloud over an area.","vi":"khói bụi ô nhiễm; sương mù quang hóa"}],"examples":[{"en":"Thick smog hid the hills beyond our apartment.","vi":"Lớp sương mù dày đặc che khuất những ngọn đồi phía sau căn hộ của chúng tôi.","audioKind":"ex"},{"en":"Reducing vehicle emissions can help cities tackle smog and protect residents from respiratory diseases.","vi":"Giảm lượng khí thải từ phương tiện giao thông có thể giúp các thành phố giải quyết tình trạng khói bụi và bảo vệ cư dân khỏi các bệnh về đường hô hấp.","audioKind":"ex2"}],"collocations":[{"en":"thick smog","vi":"sương mù dày đặc"},{"en":"smog levels","vi":"mức độ ô nhiễm khói bụi"},{"en":"photochemical smog","vi":"sương mù quang hóa"}],"wordFamily":["smoggy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; smog chỉ khói bụi ô nhiễm chứ không phải sương mù tự nhiên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_extreme', 'en-b2-24', 'extreme', '/ɪkˈstriːm/', 'B2', 'cực độ; vô cùng; khắc nghiệt; cực đoan; quá khích; điểm cực hạn; thái cực', 'adj.', 'extremely (adv.), extremism (n.), extremist (n.)', 'Đồng nghĩa: severe, excessive · Trái nghĩa: moderate', 'Phó từ của nó là extremely; thành ngữ chỉ sự thái quá thường dùng là go to extremes.', 'We kept the curtains closed during the extreme heat.', NULL, 'Chúng tôi luôn kéo rèm trong suốt đợt nắng nóng khắc nghiệt.', '{"wordId":"extreme","ukIpa":"/ɪkˈstriːm/","usIpa":"/ɪkˈstriːm/","cefr":"B2","topic":"environment","senses":[{"pos":"adj.","en":"very great in degree or far beyond what is usual","vi":"cực độ; vô cùng; khắc nghiệt"},{"pos":"adj.","en":"far beyond what most people consider reasonable or acceptable","vi":"cực đoan; quá khích"},{"pos":"n.","en":"either end of a range of conditions or behaviour","vi":"điểm cực hạn; thái cực"}],"examples":[{"en":"We kept the curtains closed during the extreme heat.","vi":"Chúng tôi luôn kéo rèm trong suốt đợt nắng nóng khắc nghiệt.","audioKind":"ex"},{"en":"Extreme weather events can damage infrastructure and place considerable pressure on emergency services in vulnerable communities.","vi":"Các hiện tượng thời tiết cực đoan có thể tàn phá cơ sở hạ tầng và gây áp lực lớn lên các dịch vụ cứu hộ khẩn cấp ở những cộng đồng dễ bị tổn thương.","audioKind":"ex2"}],"collocations":[{"en":"extreme weather","vi":"thời tiết khắc nghiệt"},{"en":"extreme poverty","vi":"sự nghèo đói cùng cực"},{"en":"extreme views","vi":"quan điểm cực đoan"},{"en":"go to extremes","vi":"làm gì đó tới mức thái quá"}],"wordFamily":["extremely (adv.)","extremism (n.)","extremist (n.)"],"synonyms":["severe","excessive"],"antonyms":["moderate"],"tipVi":"Phó từ của nó là extremely; thành ngữ chỉ sự thái quá thường dùng là go to extremes.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scorching', 'en-b2-24', 'scorching', '/ˈskɔːrtʃɪŋ/', 'B2', 'nóng như đổ lửa; oi bức', 'adj.', 'scorch (v.), scorched (adj.)', 'Đồng nghĩa: sweltering, blistering · Trái nghĩa: freezing', 'Diễn tả thời tiết cực kỳ nóng, thường dùng "scorching hot", thông thường không dùng "very" để bổ nghĩa.', 'We sheltered under a tree in the scorching heat.', NULL, 'Chúng tôi đã trú dưới bóng cây trong cái nắng oi ả.', '{"wordId":"scorching","ukIpa":"/ˈskɔːtʃɪŋ/","usIpa":"/ˈskɔːrtʃɪŋ/","cefr":"B2","topic":"environment","senses":[{"pos":"adj.","en":"Extremely hot, especially when describing weather.","vi":"nóng như đổ lửa; oi bức"}],"examples":[{"en":"We sheltered under a tree in the scorching heat.","vi":"Chúng tôi đã trú dưới bóng cây trong cái nắng oi ả.","audioKind":"ex"},{"en":"Increasingly frequent periods of scorching weather threaten crop yields and place additional pressure on water supplies.","vi":"Các đợt nắng nóng gay gắt xuất hiện ngày càng thường xuyên đang đe dọa năng suất cây trồng và tạo thêm áp lực lên nguồn cung cấp nước.","audioKind":"ex2"}],"collocations":[{"en":"scorching heat","vi":"cái nóng như thiêu đốt"},{"en":"scorching hot","vi":"nóng oi bức"},{"en":"a scorching summer","vi":"mùa hè nóng nực"}],"wordFamily":["scorch (v.)","scorched (adj.)"],"synonyms":["sweltering","blistering"],"antonyms":["freezing"],"tipVi":"Diễn tả thời tiết cực kỳ nóng, thường dùng \"scorching hot\", thông thường không dùng \"very\" để bổ nghĩa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_consumption', 'en-b2-24', 'consumption', '/kənˈsʌmpʃən/', 'B2', 'sự tiêu thụ; sự tiêu dùng; sự tiêu thụ thực phẩm; lượng tiêu thụ', 'n.', 'consume (v.), consumer (n.), consumable (adj.)', NULL, 'Thường là danh từ không đếm được; người tiêu dùng là consumer, không phải consumption.', 'Our electricity consumption rises when we use the heater.', NULL, 'Mức tiêu thụ điện của chúng tôi tăng lên khi sử dụng lò sưởi.', '{"wordId":"consumption","ukIpa":"/kənˈsʌmpʃən/","usIpa":"/kənˈsʌmpʃən/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"the use of resources, energy, goods, or services","vi":"sự tiêu thụ; sự tiêu dùng"},{"pos":"n.","en":"the act or amount of eating or drinking something","vi":"sự tiêu thụ thực phẩm; lượng tiêu thụ"}],"examples":[{"en":"Our electricity consumption rises when we use the heater.","vi":"Mức tiêu thụ điện của chúng tôi tăng lên khi sử dụng lò sưởi.","audioKind":"ex"},{"en":"Governments can reduce fossil fuel consumption by investing in reliable public transport and renewable energy.","vi":"Chính phủ có thể giảm mức tiêu thụ nhiên liệu hóa thạch bằng cách đầu tư vào hệ thống giao thông công cộng đáng tin cậy và năng lượng tái tạo.","audioKind":"ex2"}],"collocations":[{"en":"energy consumption","vi":"lượng tiêu thụ năng lượng"},{"en":"water consumption","vi":"lượng nước tiêu thụ"},{"en":"household consumption","vi":"tiêu dùng hộ gia đình"},{"en":"fit for human consumption","vi":"được phép tiêu thụ cho con người"}],"wordFamily":["consume (v.)","consumer (n.)","consumable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; người tiêu dùng là consumer, không phải consumption.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_acre', 'en-b2-24', 'acre', '/ˈeɪkər/', 'B2', 'mẫu Anh (đơn vị đo diện tích)', 'n.', 'acreage (n.)', NULL, 'Đơn vị diện tích: một acre tương đương khoảng 4.047 mét vuông, không bằng một héc-ta.', 'Their vegetable garden covers almost an acre behind the house.', NULL, 'Khu vườn trồng rau của họ rộng gần một mẫu Anh ở phía sau ngôi nhà.', '{"wordId":"acre","ukIpa":"/ˈeɪkə/","usIpa":"/ˈeɪkər/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"A unit of land area equal to about 4,047 square metres","vi":"mẫu Anh (đơn vị đo diện tích)"}],"examples":[{"en":"Their vegetable garden covers almost an acre behind the house.","vi":"Khu vườn trồng rau của họ rộng gần một mẫu Anh ở phía sau ngôi nhà.","audioKind":"ex"},{"en":"Protecting each acre of wetland helps preserve wildlife habitats and reduces the risk of local flooding.","vi":"Bảo vệ từng mẫu đất ngập nước giúp duy trì môi trường sống của động vật hoang dã và giảm nguy cơ ngập lụt tại địa phương.","audioKind":"ex2"}],"collocations":[{"en":"an acre of land","vi":"một mẫu đất"},{"en":"per acre","vi":"mỗi mẫu Anh"},{"en":"hundreds of acres","vi":"hàng trăm mẫu đất"}],"wordFamily":["acreage (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Đơn vị diện tích: một acre tương đương khoảng 4.047 mét vuông, không bằng một héc-ta.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ozone', 'en-b2-24', 'ozone', '/ˈoʊzoʊn/', 'B2', 'ô-don (khí có ba nguyên tử ô-xy trong mỗi phân tử)', 'n.', NULL, NULL, 'Ô-don là danh từ không đếm được; ô-don trên cao có tác dụng bảo vệ, còn ô-don mặt đất có hại.', 'High ozone levels kept us from jogging outside today.', NULL, 'Nồng độ ô-don cao khiến chúng tôi không thể chạy bộ ngoài trời hôm nay.', '{"wordId":"ozone","ukIpa":"/ˈəʊzəʊn/","usIpa":"/ˈoʊzoʊn/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"A gas whose molecules each contain three oxygen atoms.","vi":"ô-don (khí có ba nguyên tử ô-xy trong mỗi phân tử)"}],"examples":[{"en":"High ozone levels kept us from jogging outside today.","vi":"Nồng độ ô-don cao khiến chúng tôi không thể chạy bộ ngoài trời hôm nay.","audioKind":"ex"},{"en":"While ozone high in the atmosphere protects life, ground-level ozone can damage human health and crops.","vi":"Mặc dù tầng ô-don ở trên cao bảo vệ sự sống, ô-don ở tầng mặt đất lại có thể gây hại cho sức khỏe con người và mùa màng.","audioKind":"ex2"}],"collocations":[{"en":"ozone layer","vi":"tầng ô-don"},{"en":"ground-level ozone","vi":"ô-don tầng mặt đất"},{"en":"ozone depletion","vi":"sự suy giảm ô-don"},{"en":"ozone levels","vi":"nồng độ ô-don"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Ô-don là danh từ không đếm được; ô-don trên cao có tác dụng bảo vệ, còn ô-don mặt đất có hại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_drought', 'en-b2-24', 'drought', '/draʊt/', 'B2', 'hạn hán', 'n.', NULL, NULL, 'Phát âm vần với out; cần tránh nhầm lẫn với từ draught.', 'The river dried up during the long drought.', NULL, 'Con sông đã khô cạn trong đợt hạn hán kéo dài.', '{"wordId":"drought","ukIpa":"/draʊt/","usIpa":"/draʊt/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"A long period with little or no rain.","vi":"hạn hán"}],"examples":[{"en":"The river dried up during the long drought.","vi":"Con sông đã khô cạn trong đợt hạn hán kéo dài.","audioKind":"ex"},{"en":"Prolonged drought can reduce agricultural yields and force rural communities to depend on imported food.","vi":"Hạn hán kéo dài có thể làm giảm năng suất nông nghiệp và buộc các cộng đồng nông thôn phải phụ thuộc vào lương thực nhập khẩu.","audioKind":"ex2"}],"collocations":[{"en":"severe drought","vi":"hạn hán nghiêm trọng"},{"en":"prolonged drought","vi":"hạn hán kéo dài"},{"en":"drought conditions","vi":"tình trạng hạn hán"},{"en":"drought relief","vi":"cứu trợ hạn hán"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Phát âm vần với out; cần tránh nhầm lẫn với từ draught.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_harm', 'en-b2-24', 'harm', '/hɑːrm/', 'B2', 'tổn hại; sự tổn thương; làm hại; gây tổn hại', 'n.', 'harmful (adj.), harmless (adj.), harmlessly (adv.)', 'Đồng nghĩa: damage, hurt', 'Danh từ không đếm được; dùng cấu trúc do harm to, còn động từ harm đi trực tiếp với tân ngữ.', 'Too much sunlight can harm the leaves of this plant.', NULL, 'Ánh nắng quá gắt có thể làm tổn hại lá của loài cây này.', '{"wordId":"harm","ukIpa":"/hɑːm/","usIpa":"/hɑːrm/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"Physical injury or damage to someone''s wellbeing or something''s condition.","vi":"tổn hại; sự tổn thương"},{"pos":"v.","en":"To injure someone or damage something.","vi":"làm hại; gây tổn hại"}],"examples":[{"en":"Too much sunlight can harm the leaves of this plant.","vi":"Ánh nắng quá gắt có thể làm tổn hại lá của loài cây này.","audioKind":"ex"},{"en":"Stricter controls on industrial waste could reduce the harm caused to rivers and protect local wildlife.","vi":"Việc kiểm soát chặt chẽ hơn đối với chất thải công nghiệp có thể làm giảm những tổn hại gây ra cho các dòng sông và bảo vệ động vật hoang dã địa phương.","audioKind":"ex2"}],"collocations":[{"en":"cause harm","vi":"gây tổn hại"},{"en":"do more harm than good","vi":"lợi bất cập hại"},{"en":"harm the environment","vi":"gây hại cho môi trường"}],"wordFamily":["harmful (adj.)","harmless (adj.)","harmlessly (adv.)"],"synonyms":["damage","hurt"],"antonyms":[],"tipVi":"Danh từ không đếm được; dùng cấu trúc do harm to, còn động từ harm đi trực tiếp với tân ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_packaging', 'en-b2-24', 'packaging', '/ˈpækɪdʒɪŋ/', 'B2', 'vật liệu đóng gói; bao bì', 'n.', 'package (n.), package (v.), pack (v.)', NULL, 'Thường là danh từ không đếm được khi chỉ vật liệu đóng gói; dùng "package" cho một kiện hàng.', 'This toy comes with far too much plastic packaging.', NULL, 'Món đồ chơi này dùng quá nhiều bao bì nhựa.', '{"wordId":"packaging","ukIpa":"/ˈpækɪdʒɪŋ/","usIpa":"/ˈpækɪdʒɪŋ/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"Materials used to wrap and protect products.","vi":"vật liệu đóng gói; bao bì"}],"examples":[{"en":"This toy comes with far too much plastic packaging.","vi":"Món đồ chơi này dùng quá nhiều bao bì nhựa.","audioKind":"ex"},{"en":"Manufacturers should reduce unnecessary packaging to conserve resources and limit the amount of household waste.","vi":"Các nhà sản xuất nên giảm bớt bao bì không cần thiết để tiết kiệm tài nguyên và hạn chế lượng rác thải sinh hoạt.","audioKind":"ex2"}],"collocations":[{"en":"recyclable packaging","vi":"bao bì tái chế"},{"en":"excessive packaging","vi":"bao bì quá mức"},{"en":"packaging materials","vi":"vật liệu đóng gói"}],"wordFamily":["package (n.)","package (v.)","pack (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được khi chỉ vật liệu đóng gói; dùng \"package\" cho một kiện hàng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_extinct', 'en-b2-24', 'extinct', '/ɪkˈstɪŋkt/', 'B2', 'tuyệt chủng; không còn hoạt động (núi lửa)', 'adj.', 'extinction (n.)', 'Trái nghĩa: extant', 'extinct chỉ đã tuyệt chủng; endangered chỉ loài nguy cấp, chưa tuyệt chủng.', 'My little cousin asked why dinosaurs became extinct.', NULL, 'Cậu em họ nhỏ của tôi hỏi tại sao khủng long lại tuyệt chủng.', '{"wordId":"extinct","ukIpa":"/ɪkˈstɪŋkt/","usIpa":"/ɪkˈstɪŋkt/","cefr":"B2","topic":"environment","senses":[{"pos":"adj.","en":"having no living members left","vi":"tuyệt chủng"},{"pos":"adj.","en":"describing a volcano not expected to erupt again","vi":"không còn hoạt động (núi lửa)"}],"examples":[{"en":"My little cousin asked why dinosaurs became extinct.","vi":"Cậu em họ nhỏ của tôi hỏi tại sao khủng long lại tuyệt chủng.","audioKind":"ex"},{"en":"Without stronger habitat protection, many endangered species could become extinct within the next few decades.","vi":"Nếu không có các biện pháp bảo vệ môi trường sống mạnh mẽ hơn, nhiều loài nguy cấp có thể sẽ tuyệt chủng trong vài thập kỷ tới.","audioKind":"ex2"}],"collocations":[{"en":"become extinct","vi":"trở nên tuyệt chủng"},{"en":"extinct species","vi":"loài tuyệt chủng"},{"en":"extinct volcano","vi":"núi lửa đã tắt"}],"wordFamily":["extinction (n.)"],"synonyms":[],"antonyms":["extant"],"tipVi":"extinct chỉ đã tuyệt chủng; endangered chỉ loài nguy cấp, chưa tuyệt chủng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_agriculture', 'en-b2-24', 'agriculture', '/ˈæɡrɪkʌltʃər/', 'B2', 'nông nghiệp', 'n.', 'agricultural (adj.), agriculturist (n.)', 'Đồng nghĩa: farming', 'Là danh từ không đếm được; tính từ tương ứng là agricultural.', 'Many families here earn their living through agriculture.', NULL, 'Nhiều gia đình ở đây kiếm sống bằng nghề làm nông.', '{"wordId":"agriculture","ukIpa":"/ˈæɡrɪkʌltʃə/","usIpa":"/ˈæɡrɪkʌltʃər/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"The activity of growing crops and raising animals for food.","vi":"nông nghiệp"}],"examples":[{"en":"Many families here earn their living through agriculture.","vi":"Nhiều gia đình ở đây kiếm sống bằng nghề làm nông.","audioKind":"ex"},{"en":"Sustainable agriculture can protect soil quality while providing enough food for a growing global population.","vi":"Nông nghiệp bền vững có thể bảo vệ chất lượng đất đai trong khi vẫn cung cấp đủ lương thực cho dân số toàn cầu đang gia tăng.","audioKind":"ex2"}],"collocations":[{"en":"sustainable agriculture","vi":"nông nghiệp bền vững"},{"en":"intensive agriculture","vi":"nông nghiệp thâm canh"},{"en":"organic agriculture","vi":"nông nghiệp hữu cơ"}],"wordFamily":["agricultural (adj.)","agriculturist (n.)"],"synonyms":["farming"],"antonyms":[],"tipVi":"Là danh từ không đếm được; tính từ tương ứng là agricultural.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_24_1', 'en-b2-24', 'Cách dùng “scorching” (adj.) — nóng như đổ lửa; oi bức', 'scorching heat  ·  scorching hot  ·  a scorching summer', 'Diễn tả thời tiết cực kỳ nóng, thường dùng "scorching hot", thông thường không dùng "very" để bổ nghĩa.', 'Họ từ (Word Family): scorch (v.), scorched (adj.) | Đồng nghĩa: sweltering, blistering · Trái nghĩa: freezing', '[{"hanzi":"We sheltered under a tree in the scorching heat.","pinyin":"","meaning":"Chúng tôi đã trú dưới bóng cây trong cái nắng oi ả."},{"hanzi":"Increasingly frequent periods of scorching weather threaten crop yields and place additional pressure on water supplies.","pinyin":"","meaning":"Các đợt nắng nóng gay gắt xuất hiện ngày càng thường xuyên đang đe dọa năng suất cây trồng và tạo thêm áp lực lên nguồn cung cấp nước."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_24_2', 'en-b2-24', 'Cách dùng “smog” (n.) — khói bụi ô nhiễm; sương mù quang hóa', 'thick smog  ·  smog levels  ·  photochemical smog', 'Thường là danh từ không đếm được; smog chỉ khói bụi ô nhiễm chứ không phải sương mù tự nhiên.', 'Họ từ (Word Family): smoggy (adj.)', '[{"hanzi":"Thick smog hid the hills beyond our apartment.","pinyin":"","meaning":"Lớp sương mù dày đặc che khuất những ngọn đồi phía sau căn hộ của chúng tôi."},{"hanzi":"Reducing vehicle emissions can help cities tackle smog and protect residents from respiratory diseases.","pinyin":"","meaning":"Giảm lượng khí thải từ phương tiện giao thông có thể giúp các thành phố giải quyết tình trạng khói bụi và bảo vệ cư dân khỏi các bệnh về đường hô hấp."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_24_3', 'en-b2-24', 'Cách dùng “ozone” (n.) — ô-don (khí có ba nguyên tử ô-xy trong mỗi phân tử)', 'ozone layer  ·  ground-level ozone  ·  ozone depletion', 'Ô-don là danh từ không đếm được; ô-don trên cao có tác dụng bảo vệ, còn ô-don mặt đất có hại.', NULL, '[{"hanzi":"High ozone levels kept us from jogging outside today.","pinyin":"","meaning":"Nồng độ ô-don cao khiến chúng tôi không thể chạy bộ ngoài trời hôm nay."},{"hanzi":"While ozone high in the atmosphere protects life, ground-level ozone can damage human health and crops.","pinyin":"","meaning":"Mặc dù tầng ô-don ở trên cao bảo vệ sự sống, ô-don ở tầng mặt đất lại có thể gây hại cho sức khỏe con người và mùa màng."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_24_4', 'en-b2-24', 'Cách dùng “packaging” (n.) — vật liệu đóng gói; bao bì', 'recyclable packaging  ·  excessive packaging  ·  packaging materials', 'Thường là danh từ không đếm được khi chỉ vật liệu đóng gói; dùng "package" cho một kiện hàng.', 'Họ từ (Word Family): package (n.), package (v.), pack (v.)', '[{"hanzi":"This toy comes with far too much plastic packaging.","pinyin":"","meaning":"Món đồ chơi này dùng quá nhiều bao bì nhựa."},{"hanzi":"Manufacturers should reduce unnecessary packaging to conserve resources and limit the amount of household waste.","pinyin":"","meaning":"Các nhà sản xuất nên giảm bớt bao bì không cần thiết để tiết kiệm tài nguyên và hạn chế lượng rác thải sinh hoạt."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_24_1', 'en-b2-24', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_24_1_1', 'ten_b2_24_1', 'threat', 'The rising river poses a threat to our village.', 'The rising river poses a threat to our village.', '/θret/', 'Mực nước sông dâng cao đang gây ra mối đe dọa cho ngôi làng của chúng ta.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_24_1_2', 'ten_b2_24_1', 'disposal', 'The council provides bins for the disposal of batteries.', 'The council provides bins for the disposal of batteries.', '/dɪˈspoʊzəl/', 'Hội đồng thành phố cung cấp các thùng chứa để xử lý pin thải.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_24_1_3', 'ten_b2_24_1', 'pollutant', 'This filter removes harmful pollutants from our drinking water.', 'This filter removes harmful pollutants from our drinking water.', '/pəˈluːtənt/', 'Bộ lọc này loại bỏ các chất ô nhiễm có hại ra khỏi nguồn nước uống của chúng ta.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_24_1_4', 'ten_b2_24_1', 'erode', 'Strong waves have eroded the cliffs near our village.', 'Strong waves have eroded the cliffs near our village.', '/ɪˈroʊd/', 'Những con sóng mạnh đã làm xói mòn các vách đá gần làng chúng tôi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_24_1_5', 'ten_b2_24_1', 'plough', 'The farmer pulled an old plough from the shed.', 'The farmer pulled an old plough from the shed.', '/plaʊ/', 'Người nông dân lôi một chiếc cày cũ ra khỏi nhà kho.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_24_1_6', 'ten_b2_24_1', 'footprint', 'A muddy footprint covered the clean kitchen floor.', 'A muddy footprint covered the clean kitchen floor.', '/ˈfʊtprɪnt/', 'Một dấu chân dính bùn in trên sàn nhà bếp sạch bóng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_24_1_7', 'ten_b2_24_1', 'livestock', 'The farmer moved the livestock into a sheltered field.', 'The farmer moved the livestock into a sheltered field.', '/ˈlaɪvstɑːk/', 'Người nông dân lùa đàn gia súc vào một khu đồng có mái che.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_24_1_8', 'ten_b2_24_1', 'adaptation', 'Our adaptation to the colder weather took several weeks.', 'Our adaptation to the colder weather took several weeks.', '/ˌædæpˈteɪʃən/', 'Việc chúng tôi thích nghi với thời tiết lạnh hơn mất vài tuần.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_24_1_1', 'en-b2-24', 'ten_b2_24_1', 'listening', 'listening', 'The rising river poses a threat to our village.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Người nông dân lôi một chiếc cày cũ ra khỏi nhà kho.","Một dấu chân dính bùn in trên sàn nhà bếp sạch bóng.","Mực nước sông dâng cao đang gây ra mối đe dọa cho ngôi làng của chúng ta.","Chúng tôi đã trú dưới bóng cây trong cái nắng oi ả."]'::jsonb, 2, 'The rising river poses a threat to our village. → Mực nước sông dâng cao đang gây ra mối đe dọa cho ngôi làng của chúng ta.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_24_1_2', 'en-b2-24', 'ten_b2_24_1', 'listening', 'listening', 'The council provides bins for the disposal of batteries.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Lớp sương mù dày đặc che khuất những ngọn đồi phía sau căn hộ của chúng tôi.","Hội đồng thành phố cung cấp các thùng chứa để xử lý pin thải.","Mực nước sông dâng cao đang gây ra mối đe dọa cho ngôi làng của chúng ta.","Ánh nắng quá gắt có thể làm tổn hại lá của loài cây này."]'::jsonb, 1, 'The council provides bins for the disposal of batteries. → Hội đồng thành phố cung cấp các thùng chứa để xử lý pin thải.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_24_1_3', 'en-b2-24', 'ten_b2_24_1', 'listening', 'listening', 'This filter removes harmful pollutants from our drinking water.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Món đồ chơi này dùng quá nhiều bao bì nhựa.","Mức tiêu thụ điện của chúng tôi tăng lên khi sử dụng lò sưởi.","Bộ lọc này loại bỏ các chất ô nhiễm có hại ra khỏi nguồn nước uống của chúng ta.","Ánh nắng quá gắt có thể làm tổn hại lá của loài cây này."]'::jsonb, 2, 'This filter removes harmful pollutants from our drinking water. → Bộ lọc này loại bỏ các chất ô nhiễm có hại ra khỏi nguồn nước uống của chúng ta.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_24_2', 'en-b2-24', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_24_2_1', 'ten_b2_24_2', 'threat', 'Habitat destruction remains a major threat to biodiversity, particularly in regions experiencing rapid agricultural expansion.', 'Habitat destruction remains a major threat to biodiversity, particularly in regions experiencing rapid agricultural expansion.', '/θret/', 'Sự tàn phá môi trường sống vẫn là mối đe dọa lớn đối với đa dạng sinh học, đặc biệt ở các khu vực đang mở rộng diện tích nông nghiệp nhanh chóng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_24_2_2', 'ten_b2_24_2', 'disposal', 'Safe waste disposal is essential for protecting groundwater and reducing health risks in densely populated areas.', 'Safe waste disposal is essential for protecting groundwater and reducing health risks in densely populated areas.', '/dɪˈspoʊzəl/', 'Việc xử lý chất thải an toàn là rất quan trọng để bảo vệ nước ngầm và giảm thiểu rủi ro sức khỏe ở các khu vực đông dân cư.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_24_2_3', 'ten_b2_24_2', 'pollutant', 'Stricter controls on industrial pollutants could improve air quality and reduce respiratory illness in urban areas.', 'Stricter controls on industrial pollutants could improve air quality and reduce respiratory illness in urban areas.', '/pəˈluːtənt/', 'Việc kiểm soát chặt chẽ hơn các chất ô nhiễm công nghiệp có thể cải thiện chất lượng không khí và giảm các bệnh về đường hô hấp ở khu vực đô thị.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_24_2_4', 'ten_b2_24_2', 'erode', 'Persistent inflation can erode household savings, making it harder for families to afford essential goods.', 'Persistent inflation can erode household savings, making it harder for families to afford essential goods.', '/ɪˈroʊd/', 'Lạm phát kéo dài có thể làm xói mòn tiền tiết kiệm của hộ gia đình, khiến các gia đình khó chi trả cho các mặt hàng thiết yếu hơn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_24_2_5', 'ten_b2_24_2', 'plough', 'Farmers who plough steep slopes too frequently may increase soil erosion and reduce long-term agricultural productivity.', 'Farmers who plough steep slopes too frequently may increase soil erosion and reduce long-term agricultural productivity.', '/plaʊ/', 'Những người nông dân cày xới các sườn dốc quá thường xuyên có thể làm tăng xói mòn đất và làm giảm năng suất nông nghiệp lâu dài.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_24_2_6', 'ten_b2_24_2', 'footprint', 'Choosing locally grown food can sometimes reduce the carbon footprint associated with transporting agricultural products.', 'Choosing locally grown food can sometimes reduce the carbon footprint associated with transporting agricultural products.', '/ˈfʊtprɪnt/', 'Việc lựa chọn thực phẩm trồng tại địa phương đôi khi có thể làm giảm lượng khí thải carbon liên quan đến việc vận chuyển nông sản.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_24_2_1', 'en-b2-24', 'ten_b2_24_2', 'listening', 'listening', 'Habitat destruction remains a major threat to biodiversity, particularly in regions experiencing rapid agricultural expansion.', NULL, 'Trong câu vừa nghe, từ “threat” mang nghĩa nào sau đây?', '["khoản tiền trả góp theo kỳ","mối đe dọa; nguy cơ tiềm ẩn","kiểm soát, quản lý thông qua quy tắc hoặc luật lệ","chương trình giảng dạy; chương trình học"]'::jsonb, 1, '“threat” (/θret/): mối đe dọa; nguy cơ tiềm ẩn. Câu đầy đủ: Habitat destruction remains a major threat to biodiversity, particularly in regions experiencing rapid agricultural expansion.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_24_2_2', 'en-b2-24', 'ten_b2_24_2', 'listening', 'listening', 'Safe waste disposal is essential for protecting groundwater and reducing health risks in densely populated areas.', NULL, 'Trong câu vừa nghe, từ “disposal” mang nghĩa nào sau đây?', '["lời khuyên; khuyến nghị","phụ thuộc; lệ thuộc","cám dỗ; lôi cuốn; thu hút","sự vứt bỏ; sự xử lý"]'::jsonb, 3, '“disposal” (/dɪˈspoʊzəl/): sự vứt bỏ; sự xử lý. Câu đầy đủ: Safe waste disposal is essential for protecting groundwater and reducing health risks in densely populated areas.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
