INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_24_5', 'en-b2-24', 'The farmer pulled an old plough from the shed', 'Người nông dân lôi một chiếc cày cũ ra khỏi nhà kho.', 'plough /plaʊ/', '["pulled","plough","The","shed","an","farmer","old","from","the"]'::jsonb, NULL, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
