INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_24_8', 'en-b2-24', 'Our adaptation to the colder weather took several weeks', 'Việc chúng tôi thích nghi với thời tiết lạnh hơn mất vài tuần.', 'adaptation /ˌædæpˈteɪʃən/', '["Our","the","weeks","weather","to","colder","several","took","adaptation"]'::jsonb, NULL, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_24_9', 'en-b2-24', 'Thick smog hid the hills beyond our apartment', 'Lớp sương mù dày đặc che khuất những ngọn đồi phía sau căn hộ của chúng tôi.', 'smog /smɑːɡ/', '["the","smog","apartment","Thick","hills","hid","beyond","our"]'::jsonb, NULL, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
