INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_24_2', 'en-b2-24', NULL, 'comprehensive_test', 'listening', 'The council provides bins for the disposal of batteries.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Việc chúng tôi thích nghi với thời tiết lạnh hơn mất vài tuần.","Hội đồng thành phố cung cấp các thùng chứa để xử lý pin thải.","Nhiều gia đình ở đây kiếm sống bằng nghề làm nông.","Người nông dân lùa đàn gia súc vào một khu đồng có mái che."]'::jsonb, 1, 'The council provides bins for the disposal of batteries. → Hội đồng thành phố cung cấp các thùng chứa để xử lý pin thải.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_24_3', 'en-b2-24', NULL, 'comprehensive_test', 'listening', 'pollutant', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đặt mua dài hạn; đăng ký sử dụng dịch vụ","chất gây ô nhiễm","có tầm ảnh hưởng; có sức ảnh hưởng lớn","riêng biệt; đặc biệt, chuyên dụng"]'::jsonb, 1, 'pollutant (/pəˈluːtənt/) → chất gây ô nhiễm', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_24_4', 'en-b2-24', NULL, 'comprehensive_test', 'listening', 'Strong waves have eroded the cliffs near our village.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ánh nắng quá gắt có thể làm tổn hại lá của loài cây này.","Hội đồng thành phố cung cấp các thùng chứa để xử lý pin thải.","Những con sóng mạnh đã làm xói mòn các vách đá gần làng chúng tôi.","Một dấu chân dính bùn in trên sàn nhà bếp sạch bóng."]'::jsonb, 2, 'Strong waves have eroded the cliffs near our village. → Những con sóng mạnh đã làm xói mòn các vách đá gần làng chúng tôi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_24_5', 'en-b2-24', NULL, 'comprehensive_test', 'listening', 'plough', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự phân biệt, điểm khác biệt","chế độ nô lệ; tình trạng nô lệ","cái cày","đối phó; đương đầu; giải quyết"]'::jsonb, 2, 'plough (/plaʊ/) → cái cày; cày ruộng; cày đất', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_24_6', 'en-b2-24', NULL, 'comprehensive_test', 'listening', 'A muddy footprint covered the clean kitchen floor.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những con sóng mạnh đã làm xói mòn các vách đá gần làng chúng tôi.","Nồng độ ô-don cao khiến chúng tôi không thể chạy bộ ngoài trời hôm nay.","Một dấu chân dính bùn in trên sàn nhà bếp sạch bóng.","Món đồ chơi này dùng quá nhiều bao bì nhựa."]'::jsonb, 2, 'A muddy footprint covered the clean kitchen floor. → Một dấu chân dính bùn in trên sàn nhà bếp sạch bóng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
