INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_24_8', 'en-b2-24', NULL, 'comprehensive_test', 'listening', 'Our adaptation to the colder weather took several weeks.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Việc chúng tôi thích nghi với thời tiết lạnh hơn mất vài tuần.","Bộ lọc này loại bỏ các chất ô nhiễm có hại ra khỏi nguồn nước uống của chúng ta.","Mức tiêu thụ điện của chúng tôi tăng lên khi sử dụng lò sưởi.","Món đồ chơi này dùng quá nhiều bao bì nhựa."]'::jsonb, 0, 'Our adaptation to the colder weather took several weeks. → Việc chúng tôi thích nghi với thời tiết lạnh hơn mất vài tuần.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
