INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_24_18', 'en-b2-24', NULL, 'comprehensive_test', 'reading', NULL, 'Habitat destruction remains a major threat to biodiversity, particularly in regions experiencing rapid agricultural expansion.', 'Dựa vào câu trên, từ “threat” có nghĩa phù hợp nhất là gì?', '["chồng (đồ vật xếp chồng lên nhau)","trung thành; tận tụy","mối đe dọa; nguy cơ tiềm ẩn","hầu như không; vừa mới; suýt nữa thì không"]'::jsonb, 2, 'threat: mối đe dọa; nguy cơ tiềm ẩn; lời đe dọa; sự hăm dọa. Dịch cả câu: Sự tàn phá môi trường sống vẫn là mối đe dọa lớn đối với đa dạng sinh học, đặc biệt ở các khu vực đang mở rộng diện tích nông nghiệp nhanh chóng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_24_19', 'en-b2-24', NULL, 'comprehensive_test', 'reading', NULL, 'Safe waste disposal is essential for protecting groundwater and reducing health risks in densely populated areas.', 'Dựa vào câu trên, từ “disposal” có nghĩa phù hợp nhất là gì?', '["bồi thường; đền bù","đồ gốm","có thể xảy ra; có khả năng cao","sự vứt bỏ; sự xử lý"]'::jsonb, 3, 'disposal: sự vứt bỏ; sự xử lý; sự sẵn có để sử dụng. Dịch cả câu: Việc xử lý chất thải an toàn là rất quan trọng để bảo vệ nước ngầm và giảm thiểu rủi ro sức khỏe ở các khu vực đông dân cư.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_24_20', 'en-b2-24', NULL, 'comprehensive_test', 'reading', NULL, 'Stricter controls on industrial pollutants could improve air quality and reduce respiratory illness in urban areas.', 'Dựa vào câu trên, từ “pollutant” có nghĩa phù hợp nhất là gì?', '["cho rằng; giả định; nghĩ rằng","xoay quanh; quay","chất gây ô nhiễm","cầu phước; ban phúc"]'::jsonb, 2, 'pollutant: chất gây ô nhiễm. Dịch cả câu: Việc kiểm soát chặt chẽ hơn các chất ô nhiễm công nghiệp có thể cải thiện chất lượng không khí và giảm các bệnh về đường hô hấp ở khu vực đô thị.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_24_21', 'en-b2-24', NULL, 'comprehensive_test', 'reading', NULL, 'Persistent inflation can erode household savings, making it harder for families to afford essential goods.', 'Dựa vào câu trên, từ “erode” có nghĩa phù hợp nhất là gì?', '["có nguy cơ bị đe dọa; có nguy cơ tuyệt chủng","bị xói mòn; bị bào mòn","sự chuyển đổi; giai đoạn chuyển tiếp","góc nhìn; quan điểm"]'::jsonb, 1, 'erode: bị xói mòn; bị bào mòn; làm xói mòn; làm suy yếu dần. Dịch cả câu: Lạm phát kéo dài có thể làm xói mòn tiền tiết kiệm của hộ gia đình, khiến các gia đình khó chi trả cho các mặt hàng thiết yếu hơn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_24_22', 'en-b2-24', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “vật liệu đóng gói; bao bì”', '["packaging","conservative","analysis","outsider"]'::jsonb, 0, 'vật liệu đóng gói; bao bì → packaging (/ˈpækɪdʒɪŋ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_24_23', 'en-b2-24', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tuyệt chủng”', '["activate","poll","extinct","alien"]'::jsonb, 2, 'tuyệt chủng → extinct (/ɪkˈstɪŋkt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_24_24', 'en-b2-24', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nông nghiệp”', '["fibre","agriculture","throne","textile"]'::jsonb, 1, 'nông nghiệp → agriculture (/ˈæɡrɪkʌltʃər/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-25', 'en', 'Bài 25: Môi trường & Sinh thái (3) - CEFR B2', 'CEFR B2', 'B2 · Môi trường', '19 từ vựng Tiếng Anh CEFR B2 chủ đề môi trường & sinh thái kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4025, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conserve', 'en-b2-25', 'conserve', '/kənˈsɝːv/', 'B2', 'tiết kiệm; bảo tồn; bảo vệ', 'v.', 'conservation (n.), conservationist (n.)', 'Đồng nghĩa: preserve, protect · Trái nghĩa: waste', 'conserve nhấn mạnh việc tiết kiệm hoặc bảo vệ; reserve nhấn mạnh việc dự trữ, để dành.', 'We collect rainwater to conserve water in the garden.', NULL, 'Chúng tôi thu gom nước mưa để tiết kiệm nước trong vườn.', '{"wordId":"conserve","ukIpa":"/kənˈsɜːv/","usIpa":"/kənˈsɝːv/","cefr":"B2","topic":"environment","senses":[{"pos":"v.","en":"Use resources carefully to avoid wasting them.","vi":"tiết kiệm"},{"pos":"v.","en":"Protect something valuable from damage, loss, or destruction.","vi":"bảo tồn; bảo vệ"}],"examples":[{"en":"We collect rainwater to conserve water in the garden.","vi":"Chúng tôi thu gom nước mưa để tiết kiệm nước trong vườn.","audioKind":"ex"},{"en":"Governments should encourage efficient farming methods that conserve water without reducing the supply of affordable food.","vi":"Chính phủ nên khuyến khích các phương thức canh tác hiệu quả giúp tiết kiệm nước mà không làm giảm nguồn cung thực phẩm có giá cả phải chăng.","audioKind":"ex2"}],"collocations":[{"en":"conserve energy","vi":"tiết kiệm năng lượng"},{"en":"conserve water","vi":"tiết kiệm nước"},{"en":"conserve wildlife","vi":"bảo tồn động vật hoang dã"}],"wordFamily":["conservation (n.)","conservationist (n.)"],"synonyms":["preserve","protect"],"antonyms":["waste"],"tipVi":"conserve nhấn mạnh việc tiết kiệm hoặc bảo vệ; reserve nhấn mạnh việc dự trữ, để dành.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_coral', 'en-b2-25', 'coral', '/ˈkɔːrəl/', 'B2', 'san hô; động vật san hô; màu hồng cam; màu san hô', 'n.', NULL, NULL, 'Chỉ vật liệu san hô thường không đếm được; chỉ các loài hoặc quần thể có thể dùng corals.', 'Bright fish swam between branches of coral beneath us.', NULL, 'Những chú cá rực rỡ bơi lội giữa các khóm san hô phía dưới chúng tôi.', '{"wordId":"coral","ukIpa":"/ˈkɒrəl/","usIpa":"/ˈkɔːrəl/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"tiny sea animals, or the hard structures they build","vi":"san hô; động vật san hô"},{"pos":"adj.","en":"having a pinkish-orange colour","vi":"màu hồng cam; màu san hô"}],"examples":[{"en":"Bright fish swam between branches of coral beneath us.","vi":"Những chú cá rực rỡ bơi lội giữa các khóm san hô phía dưới chúng tôi.","audioKind":"ex"},{"en":"Rising ocean temperatures threaten coral reefs, which provide essential habitats for many marine species.","vi":"Nhiệt độ đại dương tăng cao đang đe dọa các rạn san hô, nơi cung cấp môi trường sống thiết yếu cho nhiều loài sinh vật biển.","audioKind":"ex2"}],"collocations":[{"en":"coral reef","vi":"rạn san hô"},{"en":"coral bleaching","vi":"hiện tượng tẩy trắng san hô"},{"en":"coral colony","vi":"quần thể san hô"},{"en":"coral restoration","vi":"phục hồi san hô"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ vật liệu san hô thường không đếm được; chỉ các loài hoặc quần thể có thể dùng corals.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ecosystem', 'en-b2-25', 'ecosystem', '/ˈiːkoʊsɪstəm/', 'B2', 'hệ sinh thái', 'n.', NULL, NULL, 'Chỉ hệ thống bao gồm các sinh vật và môi trường tương tác với nhau, không chỉ đơn thuần là quần thể sinh vật.', 'This small pond supports a surprisingly rich ecosystem.', NULL, 'Ao nhỏ này nuôi dưỡng một hệ sinh thái phong phú đến bất ngờ.', '{"wordId":"ecosystem","ukIpa":"/ˈiːkəʊsɪstəm/","usIpa":"/ˈiːkoʊsɪstəm/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"Living things and their environment interacting as a connected system.","vi":"hệ sinh thái"}],"examples":[{"en":"This small pond supports a surprisingly rich ecosystem.","vi":"Ao nhỏ này nuôi dưỡng một hệ sinh thái phong phú đến bất ngờ.","audioKind":"ex"},{"en":"Removing a single species can disrupt an entire ecosystem because organisms depend on one another for survival.","vi":"Việc loại bỏ một loài duy nhất có thể làm gián đoạn toàn bộ hệ sinh thái vì các sinh vật phụ thuộc lẫn nhau để sinh tồn.","audioKind":"ex2"}],"collocations":[{"en":"marine ecosystem","vi":"hệ sinh thái biển"},{"en":"fragile ecosystem","vi":"hệ sinh thái mong manh"},{"en":"protect ecosystems","vi":"bảo vệ các hệ sinh thái"},{"en":"disrupt an ecosystem","vi":"làm gián đoạn hệ sinh thái"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ hệ thống bao gồm các sinh vật và môi trường tương tác với nhau, không chỉ đơn thuần là quần thể sinh vật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_destruction', 'en-b2-25', 'destruction', '/dɪˈstrʌkʃən/', 'B2', 'sự tàn phá; sự phá hủy', 'n.', 'destroy (v.), destructive (adj.), destructively (adv.)', 'Đồng nghĩa: devastation · Trái nghĩa: creation', 'Thường là danh từ không đếm được; động từ là destroy, không phải destruct.', 'The storm left a trail of destruction along the coast.', NULL, 'Cơn bão để lại một vệt tàn phá dọc theo bờ biển.', '{"wordId":"destruction","ukIpa":"/dɪˈstrʌkʃən/","usIpa":"/dɪˈstrʌkʃən/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"Damage so severe that something no longer exists or works.","vi":"sự tàn phá; sự phá hủy"}],"examples":[{"en":"The storm left a trail of destruction along the coast.","vi":"Cơn bão để lại một vệt tàn phá dọc theo bờ biển.","audioKind":"ex"},{"en":"The destruction of natural habitats threatens biodiversity and reduces the resources available to local communities.","vi":"Sự tàn phá các môi trường sống tự nhiên đe dọa sự đa dạng sinh học và làm giảm các nguồn tài nguyên sẵn có cho cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"habitat destruction","vi":"sự hủy hoại môi trường sống"},{"en":"widespread destruction","vi":"sự tàn phá diện rộng"},{"en":"a trail of destruction","vi":"một vệt tàn phá"}],"wordFamily":["destroy (v.)","destructive (adj.)","destructively (adv.)"],"synonyms":["devastation"],"antonyms":["creation"],"tipVi":"Thường là danh từ không đếm được; động từ là destroy, không phải destruct.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_humidity', 'en-b2-25', 'humidity', '/hjuːˈmɪdəti/', 'B2', 'độ ẩm không khí', 'n.', 'humid (adj.), humidify (v.), humidifier (n.)', NULL, 'Thường là danh từ không đếm được; mức độ ẩm cao hay thấp dùng tính từ high hoặc low.', 'The high humidity made my shirt feel damp.', NULL, 'Độ ẩm cao làm cho chiếc áo sơ mi của tôi có cảm giác ẩm ướt.', '{"wordId":"humidity","ukIpa":"/hjuːˈmɪdəti/","usIpa":"/hjuːˈmɪdəti/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"The amount of water vapour in the air","vi":"độ ẩm không khí"}],"examples":[{"en":"The high humidity made my shirt feel damp.","vi":"Độ ẩm cao làm cho chiếc áo sơ mi của tôi có cảm giác ẩm ướt.","audioKind":"ex"},{"en":"High humidity can reduce comfort in classrooms, making effective ventilation particularly important during warmer months.","vi":"Độ ẩm cao có thể làm giảm sự thoải mái trong phòng học, khiến việc thông gió hiệu quả trở nên đặc biệt quan trọng trong những tháng ấm hơn.","audioKind":"ex2"}],"collocations":[{"en":"high humidity","vi":"độ ẩm cao"},{"en":"relative humidity","vi":"độ ẩm tương đối"},{"en":"humidity levels","vi":"mức độ ẩm"},{"en":"low humidity","vi":"độ ẩm thấp"}],"wordFamily":["humid (adj.)","humidify (v.)","humidifier (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; mức độ ẩm cao hay thấp dùng tính từ high hoặc low.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_emission', 'en-b2-25', 'emission', '/ɪˈmɪʃən/', 'B2', 'chất thải; khí thải; sự phát thải; sự thải ra', 'n.', 'emit (v.), emitter (n.)', NULL, 'Chỉ khí thải hoặc mức độ phát thải thường dùng dạng số nhiều emissions; động từ tương ứng là emit.', 'The mechanic checked my car''s emissions this morning.', NULL, 'Thợ máy đã kiểm tra lượng khí thải ô tô của tôi vào sáng nay.', '{"wordId":"emission","ukIpa":"/ɪˈmɪʃən/","usIpa":"/ɪˈmɪʃən/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"A substance released into the environment, especially a polluting gas.","vi":"chất thải; khí thải"},{"pos":"n.","en":"The process of releasing gas, heat, light, or other energy.","vi":"sự phát thải; sự thải ra"}],"examples":[{"en":"The mechanic checked my car''s emissions this morning.","vi":"Thợ máy đã kiểm tra lượng khí thải ô tô của tôi vào sáng nay.","audioKind":"ex"},{"en":"Governments can reduce carbon emissions by investing in renewable energy and improving public transport networks.","vi":"Chính phủ có thể giảm lượng khí thải carbon bằng cách đầu tư vào năng lượng tái tạo và cải thiện mạng lưới giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"carbon emissions","vi":"khí thải carbon"},{"en":"exhaust emissions","vi":"khí thải ống xả"},{"en":"reduce emissions","vi":"cắt giảm lượng khí thải"},{"en":"emission standards","vi":"tiêu chuẩn khí thải"}],"wordFamily":["emit (v.)","emitter (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ khí thải hoặc mức độ phát thải thường dùng dạng số nhiều emissions; động từ tương ứng là emit.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ecology', 'en-b2-25', 'ecology', '/iˈkɑːlədʒi/', 'B2', 'sinh thái học; sinh thái; quan hệ sinh thái', 'n.', 'ecological (adj.), ecologist (n.), ecologically (adv.)', NULL, 'ecology chỉ sinh thái học hoặc quan hệ sinh thái, không đồng nghĩa với environment.', 'My sister studies ecology and often visits local wetlands.', NULL, 'Chị tôi học ngành sinh thái học và thường xuyên đến thăm các vùng đất ngập nước ở địa phương.', '{"wordId":"ecology","ukIpa":"/iˈkɒlədʒi/","usIpa":"/iˈkɑːlədʒi/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"The study of relationships between living things and their environment.","vi":"sinh thái học"},{"pos":"n.","en":"The relationships between living things and their environment.","vi":"sinh thái; quan hệ sinh thái"}],"examples":[{"en":"My sister studies ecology and often visits local wetlands.","vi":"Chị tôi học ngành sinh thái học và thường xuyên đến thăm các vùng đất ngập nước ở địa phương.","audioKind":"ex"},{"en":"Understanding forest ecology can help governments protect wildlife while managing natural resources more effectively.","vi":"Hiểu biết về sinh thái học rừng có thể giúp các chính phủ bảo vệ động vật hoang dã đồng thời quản lý tài nguyên thiên nhiên hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"marine ecology","vi":"sinh thái học biển"},{"en":"forest ecology","vi":"sinh thái học rừng"},{"en":"study ecology","vi":"nghiên cứu sinh thái học"}],"wordFamily":["ecological (adj.)","ecologist (n.)","ecologically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"ecology chỉ sinh thái học hoặc quan hệ sinh thái, không đồng nghĩa với environment.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_severe', 'en-b2-25', 'severe', '/səˈvɪr/', 'B2', 'nghiêm trọng; dữ dội; tàn khốc; nghiêm khắc; khắt khe', 'adj.', 'severity (n.), severely (adv.)', 'Đồng nghĩa: serious, harsh, intense · Trái nghĩa: mild, lenient', 'Có thể tu từ các từ chỉ cơn đau, thời tiết, sự thiếu hụt hoặc hình phạt, thể hiện mức độ nặng nề.', 'Severe storms knocked down several trees near our house.', NULL, 'Những cơn bão dữ dội đã quật ngã vài cái cây gần nhà chúng tôi.', '{"wordId":"severe","ukIpa":"/sɪˈvɪə/","usIpa":"/səˈvɪr/","cefr":"B2","topic":"environment","senses":[{"pos":"adj.","en":"Very bad, intense, or damaging.","vi":"nghiêm trọng; dữ dội; tàn khốc"},{"pos":"adj.","en":"Very strict or harsh in treatment or judgment.","vi":"nghiêm khắc; khắt khe"}],"examples":[{"en":"Severe storms knocked down several trees near our house.","vi":"Những cơn bão dữ dội đã quật ngã vài cái cây gần nhà chúng tôi.","audioKind":"ex"},{"en":"Severe water shortages can undermine agricultural production, forcing governments to invest in more efficient irrigation systems.","vi":"Tình trạng thiếu nước nghiêm trọng có thể làm suy yếu sản xuất nông nghiệp, buộc chính phủ phải đầu tư vào các hệ thống tưới tiêu hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"severe pain","vi":"cơn đau dữ dội"},{"en":"severe weather","vi":"thời tiết khắc nghiệt"},{"en":"a severe shortage","vi":"tình trạng thiếu hụt trầm trọng"},{"en":"severe punishment","vi":"hình phạt nghiêm khắc"}],"wordFamily":["severity (n.)","severely (adv.)"],"synonyms":["serious","harsh","intense"],"antonyms":["mild","lenient"],"tipVi":"Có thể tu từ các từ chỉ cơn đau, thời tiết, sự thiếu hụt hoặc hình phạt, thể hiện mức độ nặng nề.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_threatened', 'en-b2-25', 'threatened', '/ˈθretənd/', 'B2', 'có nguy cơ bị đe dọa; có nguy cơ tuyệt chủng; cảm thấy bị đe dọa', 'adj.', 'threat (n.), threaten (v.), threatening (adj.)', 'Đồng nghĩa: endangered, at risk · Trái nghĩa: safe', 'threatened chỉ đối tượng đang chịu sự đe dọa; threatening chỉ đối tượng gây ra mối đe dọa.', 'The rescue centre cares for several threatened bird species.', NULL, 'Trung tâm cứu hộ đang chăm sóc cho một số loài chim đang bị đe dọa.', '{"wordId":"threatened","ukIpa":"/ˈθretənd/","usIpa":"/ˈθretənd/","cefr":"B2","topic":"environment","senses":[{"pos":"adj.","en":"At risk of harm, loss, or extinction.","vi":"có nguy cơ bị đe dọa; có nguy cơ tuyệt chủng"},{"pos":"adj.","en":"Feeling that someone or something may cause harm or loss.","vi":"cảm thấy bị đe dọa"}],"examples":[{"en":"The rescue centre cares for several threatened bird species.","vi":"Trung tâm cứu hộ đang chăm sóc cho một số loài chim đang bị đe dọa.","audioKind":"ex"},{"en":"Protecting threatened species requires governments to preserve natural habitats and address the underlying causes of biodiversity loss.","vi":"Bảo vệ các loài bị đe dọa đòi hỏi chính phủ phải gìn giữ các môi trường sống tự nhiên và giải quyết các nguyên nhân cốt lõi dẫn đến tình trạng suy giảm đa dạng sinh học.","audioKind":"ex2"}],"collocations":[{"en":"threatened species","vi":"loài bị đe dọa"},{"en":"feel threatened","vi":"cảm thấy bị đe dọa"},{"en":"threatened with extinction","vi":"có nguy cơ tuyệt chủng"}],"wordFamily":["threat (n.)","threaten (v.)","threatening (adj.)"],"synonyms":["endangered","at risk"],"antonyms":["safe"],"tipVi":"threatened chỉ đối tượng đang chịu sự đe dọa; threatening chỉ đối tượng gây ra mối đe dọa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_man-made', 'en-b2-25', 'man-made', '/ˌmænˈmeɪd/', 'B2', 'nhân tạo; do con người làm ra', 'adj.', NULL, 'Đồng nghĩa: artificial, human-made · Trái nghĩa: natural', 'Nhấn mạnh do con người sản xuất hoặc tạo ra; cũng có thể dùng human-made.', 'We walked around a man-made lake near the airport.', NULL, 'Chúng tôi đi dạo quanh một hồ nước nhân tạo gần sân bay.', '{"wordId":"man-made","ukIpa":"/ˌmænˈmeɪd/","usIpa":"/ˌmænˈmeɪd/","cefr":"B2","topic":"environment","senses":[{"pos":"adj.","en":"made or caused by people rather than occurring naturally","vi":"nhân tạo; do con người làm ra"}],"examples":[{"en":"We walked around a man-made lake near the airport.","vi":"Chúng tôi đi dạo quanh một hồ nước nhân tạo gần sân bay.","audioKind":"ex"},{"en":"Man-made barriers such as dams can disrupt river ecosystems by preventing fish from reaching their breeding grounds.","vi":"Các rào cản nhân tạo như đập nước có thể phá vỡ hệ sinh thái sông ngòi bằng cách ngăn cản cá bơi về bãi đẻ của chúng.","audioKind":"ex2"}],"collocations":[{"en":"man-made lake","vi":"hồ nhân tạo"},{"en":"man-made materials","vi":"vật liệu nhân tạo"},{"en":"man-made disaster","vi":"thảm họa do con người gây ra"},{"en":"man-made fibres","vi":"sợi nhân tạo"}],"wordFamily":[],"synonyms":["artificial","human-made"],"antonyms":["natural"],"tipVi":"Nhấn mạnh do con người sản xuất hoặc tạo ra; cũng có thể dùng human-made.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deforestation', 'en-b2-25', 'deforestation', '/ˌdiːfɔːrɪˈsteɪʃən/', 'B2', 'phá rừng; nạn phá rừng', 'n.', 'deforest (v.), forest (n.), reforestation (n.)', 'Trái nghĩa: reforestation', 'Là danh từ không đếm được; thường được dùng trong các chủ đề về mất môi trường sống và biến đổi khí hậu.', 'Deforestation has left the hillside bare and dusty.', NULL, 'Nạn phá rừng đã làm cho sườn đồi trở nên trọc lóc và đầy bụi bẩn.', '{"wordId":"deforestation","ukIpa":"/ˌdiːfɒrɪˈsteɪʃən/","usIpa":"/ˌdiːfɔːrɪˈsteɪʃən/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"The clearing of forests by cutting down trees.","vi":"phá rừng; nạn phá rừng"}],"examples":[{"en":"Deforestation has left the hillside bare and dusty.","vi":"Nạn phá rừng đã làm cho sườn đồi trở nên trọc lóc và đầy bụi bẩn.","audioKind":"ex"},{"en":"Reducing deforestation can protect wildlife habitats and help limit the effects of climate change.","vi":"Giảm thiểu nạn phá rừng có thể bảo vệ môi trường sống của động vật hoang dã và giúp hạn chế các tác động của biến đổi khí hậu.","audioKind":"ex2"}],"collocations":[{"en":"prevent deforestation","vi":"ngăn chặn nạn phá rừng"},{"en":"widespread deforestation","vi":"nạn phá rừng diện rộng"},{"en":"tropical deforestation","vi":"nạn phá rừng nhiệt đới"}],"wordFamily":["deforest (v.)","forest (n.)","reforestation (n.)"],"synonyms":[],"antonyms":["reforestation"],"tipVi":"Là danh từ không đếm được; thường được dùng trong các chủ đề về mất môi trường sống và biến đổi khí hậu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reef', 'en-b2-25', 'reef', '/riːf/', 'B2', 'rạn đá ngầm; đá ngầm', 'n.', NULL, NULL, 'reef chỉ dải đá ngầm gần mặt nước biển, không phải vách đá ven biển cliff.', 'We watched colourful fish swimming around the coral reef.', NULL, 'Chúng tôi ngắm nhìn những chú cá đầy màu sắc bơi lội xung quanh rạn san hô.', '{"wordId":"reef","ukIpa":"/riːf/","usIpa":"/riːf/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"A ridge of rock or coral near the sea''s surface.","vi":"rạn đá ngầm; đá ngầm"}],"examples":[{"en":"We watched colourful fish swimming around the coral reef.","vi":"Chúng tôi ngắm nhìn những chú cá đầy màu sắc bơi lội xung quanh rạn san hô.","audioKind":"ex"},{"en":"Protecting coral reefs is essential because they support marine biodiversity and help shield coastlines from powerful waves.","vi":"Bảo vệ các rạn san hô là điều vô cùng quan trọng vì chúng duy trì đa dạng sinh học biển và giúp bảo vệ vùng ven bờ trước những con sóng lớn.","audioKind":"ex2"}],"collocations":[{"en":"coral reef","vi":"rạn san hô"},{"en":"barrier reef","vi":"đại rạn san hô"},{"en":"reef ecosystem","vi":"hệ sinh thái rạn san hô"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"reef chỉ dải đá ngầm gần mặt nước biển, không phải vách đá ven biển cliff.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scarce', 'en-b2-25', 'scarce', '/skers/', 'B2', 'khan hiếm; thiếu thốn', 'adj.', 'scarcity (n.)', 'Đồng nghĩa: limited · Trái nghĩa: abundant, plentiful', 'scarce chỉ tình trạng thiếu hụt nguồn cung; trong khi rare nhấn mạnh sự hiếm có, không nhất thiết là thiếu thốn.', 'Fresh vegetables became scarce after snow blocked the roads.', NULL, 'Rau tươi trở nên khan hiếm sau khi tuyết chặn đứt các con đường.', '{"wordId":"scarce","ukIpa":"/skeəs/","usIpa":"/skers/","cefr":"B2","topic":"environment","senses":[{"pos":"adj.","en":"not available in large enough amounts to meet demand","vi":"khan hiếm; thiếu thốn"}],"examples":[{"en":"Fresh vegetables became scarce after snow blocked the roads.","vi":"Rau tươi trở nên khan hiếm sau khi tuyết chặn đứt các con đường.","audioKind":"ex"},{"en":"As clean water becomes increasingly scarce, governments must invest in efficient irrigation and better water management systems.","vi":"Khi nguồn nước sạch ngày càng trở nên khan hiếm, chính phủ phải đầu tư vào hệ thống tưới tiêu hiệu quả và quản lý nguồn nước tốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"scarce resources","vi":"tài nguyên khan hiếm"},{"en":"become scarce","vi":"trở nên khan hiếm"},{"en":"increasingly scarce","vi":"ngày càng khan hiếm"}],"wordFamily":["scarcity (n.)"],"synonyms":["limited"],"antonyms":["abundant","plentiful"],"tipVi":"scarce chỉ tình trạng thiếu hụt nguồn cung; trong khi rare nhấn mạnh sự hiếm có, không nhất thiết là thiếu thốn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dispose', 'en-b2-25', 'dispose', '/dɪˈspoʊz/', 'B2', 'vứt bỏ; giải quyết; khiến ai đó có khuynh hướng hoặc sẵn lòng làm gì', 'v.', 'disposal (n.), disposable (adj.), disposition (n.)', NULL, 'Khi mang nghĩa vứt bỏ, bắt buộc phải dùng cụm "dispose of", không được trực tiếp đi với danh từ chỉ vật.', 'Where can I dispose of these old batteries safely?', NULL, 'Tôi có thể vứt bỏ những viên pin cũ này một cách an toàn ở đâu?', '{"wordId":"dispose","ukIpa":"/dɪˈspəʊz/","usIpa":"/dɪˈspoʊz/","cefr":"B2","topic":"environment","senses":[{"pos":"v.","en":"to get rid of something, used with of","vi":"vứt bỏ; giải quyết"},{"pos":"v.","en":"to make someone likely or willing to do something","vi":"khiến ai đó có khuynh hướng hoặc sẵn lòng làm gì"}],"examples":[{"en":"Where can I dispose of these old batteries safely?","vi":"Tôi có thể vứt bỏ những viên pin cũ này một cách an toàn ở đâu?","audioKind":"ex"},{"en":"Local authorities should provide convenient facilities so residents can dispose of household waste responsibly.","vi":"Chính quyền địa phương nên cung cấp các cơ sở tiện lợi để cư dân có thể xử lý rác thải sinh hoạt một cách có trách nhiệm.","audioKind":"ex2"}],"collocations":[{"en":"dispose of waste","vi":"xử lý chất thải"},{"en":"dispose of unwanted items","vi":"vứt bỏ các vật dụng không cần thiết"},{"en":"be disposed to agree","vi":"có khuynh hướng đồng ý"}],"wordFamily":["disposal (n.)","disposable (adj.)","disposition (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi mang nghĩa vứt bỏ, bắt buộc phải dùng cụm \"dispose of\", không được trực tiếp đi với danh từ chỉ vật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pest', 'en-b2-25', 'pest', '/pest/', 'B2', 'sâu bọ; loài gây hại; kẻ phiền phức; người hay quấy rầy', 'n.', 'pesticide (n.)', NULL, 'pest không giới hạn ở côn trùng, mà còn có thể chỉ chuột và các động vật gây hại khác.', 'These tiny pests have eaten holes in my cabbage leaves.', NULL, 'Những con sâu nhỏ này đã ăn thủng lá bắp cải của tôi.', '{"wordId":"pest","ukIpa":"/pest/","usIpa":"/pest/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"An insect or animal that damages crops, food, or property.","vi":"sâu bọ; loài gây hại"},{"pos":"n.","en":"Someone who annoys others, especially repeatedly.","vi":"kẻ phiền phức; người hay quấy rầy"}],"examples":[{"en":"These tiny pests have eaten holes in my cabbage leaves.","vi":"Những con sâu nhỏ này đã ăn thủng lá bắp cải của tôi.","audioKind":"ex"},{"en":"Farmers can control pests through biological methods that reduce reliance on chemicals and protect beneficial insects.","vi":"Nông dân có thể kiểm soát sâu bệnh bằng các phương pháp sinh học giúp giảm sự phụ thuộc vào hóa chất và bảo vệ côn trùng có ích.","audioKind":"ex2"}],"collocations":[{"en":"pest control","vi":"phòng trừ sâu bệnh"},{"en":"crop pests","vi":"sâu hại cây trồng"},{"en":"a garden pest","vi":"sâu bọ trong vườn"}],"wordFamily":["pesticide (n.)"],"synonyms":[],"antonyms":[],"tipVi":"pest không giới hạn ở côn trùng, mà còn có thể chỉ chuột và các động vật gây hại khác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_restore', 'en-b2-25', 'restore', '/rɪˈstɔːr/', 'B2', 'khôi phục; làm cho hồi phục; tu sửa; phục hồi; trả lại; hoàn lại', 'v.', 'restoration (n.), restorer (n.), restorative (adj.)', 'Đồng nghĩa: reinstate, repair', 'Cấu trúc restore A to B: khôi phục A về trạng thái B hoặc trả lại A cho B.', 'The engineers restored power before our food went bad.', NULL, 'Các kỹ sư đã khôi phục lại nguồn điện trước khi thức ăn của chúng tôi bị hỏng.', '{"wordId":"restore","ukIpa":"/rɪˈstɔː/","usIpa":"/rɪˈstɔːr/","cefr":"B2","topic":"environment","senses":[{"pos":"v.","en":"To bring back a previous condition, ability, or situation.","vi":"khôi phục; làm cho hồi phục"},{"pos":"v.","en":"To repair something old or damaged to its earlier condition.","vi":"tu sửa; phục hồi"},{"pos":"v.","en":"To return something to its rightful owner or place.","vi":"trả lại; hoàn lại"}],"examples":[{"en":"The engineers restored power before our food went bad.","vi":"Các kỹ sư đã khôi phục lại nguồn điện trước khi thức ăn của chúng tôi bị hỏng.","audioKind":"ex"},{"en":"Planting native trees can help restore damaged ecosystems and provide essential habitats for local wildlife.","vi":"Việc trồng cây bản địa có thể giúp phục hồi các hệ sinh thái bị tàn phá và cung cấp môi trường sống thiết yếu cho động vật hoang dã địa phương.","audioKind":"ex2"}],"collocations":[{"en":"restore confidence","vi":"lấy lại niềm tin"},{"en":"restore power","vi":"khôi phục nguồn điện"},{"en":"restore a historic building","vi":"trùng tu một tòa nhà lịch sử"},{"en":"restore something to its owner","vi":"trao trả lại vật gì cho chủ sở hữu"}],"wordFamily":["restoration (n.)","restorer (n.)","restorative (adj.)"],"synonyms":["reinstate","repair"],"antonyms":[],"tipVi":"Cấu trúc restore A to B: khôi phục A về trạng thái B hoặc trả lại A cho B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_timber', 'en-b2-25', 'timber', '/ˈtɪmbər/', 'B2', 'gỗ xây dựng; gỗ nguyên liệu; rừng lấy gỗ', 'n.', NULL, 'Đồng nghĩa: wood, lumber', 'Khi chỉ chất liệu gỗ thì thường là danh từ không đếm được; tiếng Anh-Mỹ thường dùng lumber để chỉ gỗ đã qua chế biến.', 'The carpenter stacked the timber beside the workshop.', NULL, 'Người thợ mộc xếp đống gỗ xây dựng bên cạnh xưởng làm việc.', '{"wordId":"timber","ukIpa":"/ˈtɪmbə/","usIpa":"/ˈtɪmbər/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"wood prepared for building or making things","vi":"gỗ xây dựng; gỗ nguyên liệu"},{"pos":"n.","en":"trees grown for wood used in construction or manufacturing","vi":"rừng lấy gỗ"}],"examples":[{"en":"The carpenter stacked the timber beside the workshop.","vi":"Người thợ mộc xếp đống gỗ xây dựng bên cạnh xưởng làm việc.","audioKind":"ex"},{"en":"Using responsibly sourced timber in construction can reduce environmental damage while supporting sustainable forest management.","vi":"Sử dụng gỗ có nguồn gốc bền vững trong xây dựng có thể làm giảm tác hại môi trường đồng thời hỗ trợ quản lý rừng bền vững.","audioKind":"ex2"}],"collocations":[{"en":"timber industry","vi":"ngành công nghiệp gỗ"},{"en":"timber frame","vi":"khung gỗ"},{"en":"sustainably sourced timber","vi":"gỗ có nguồn gốc bền vững"}],"wordFamily":[],"synonyms":["wood","lumber"],"antonyms":[],"tipVi":"Khi chỉ chất liệu gỗ thì thường là danh từ không đếm được; tiếng Anh-Mỹ thường dùng lumber để chỉ gỗ đã qua chế biến.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_preserve', 'en-b2-25', 'preserve', '/prɪˈzɝːv/', 'B2', 'bảo vệ; bảo quản; duy trì; muối; đóng hộp (thực phẩm); khu bảo tồn', 'v.', 'preservation (n.), preservative (n.)', 'Đồng nghĩa: protect, conserve · Trái nghĩa: destroy', 'preserve nhấn mạnh việc giữ nguyên trạng thái; dùng cả trong việc bảo quản thực phẩm.', 'We preserve old family photographs in a special album.', NULL, 'Chúng tôi lưu giữ những bức ảnh gia đình cũ trong một cuốn album đặc biệt.', '{"wordId":"preserve","ukIpa":"/prɪˈzɜːv/","usIpa":"/prɪˈzɝːv/","cefr":"B2","topic":"environment","senses":[{"pos":"v.","en":"Keep something safe, unchanged, or in good condition","vi":"bảo vệ; bảo quản; duy trì"},{"pos":"v.","en":"Treat food so it stays safe to eat longer","vi":"muối; đóng hộp (thực phẩm)"},{"pos":"n.","en":"An area where wildlife and natural habitats are protected","vi":"khu bảo tồn"}],"examples":[{"en":"We preserve old family photographs in a special album.","vi":"Chúng tôi lưu giữ những bức ảnh gia đình cũ trong một cuốn album đặc biệt.","audioKind":"ex"},{"en":"Local authorities should preserve historic buildings while adapting them to meet the needs of modern communities.","vi":"Chính quyền địa phương nên bảo tồn các di tích lịch sử đồng thời cải tạo chúng để đáp ứng nhu cầu của cộng đồng hiện đại.","audioKind":"ex2"}],"collocations":[{"en":"preserve cultural heritage","vi":"bảo tồn di sản văn hóa"},{"en":"preserve biodiversity","vi":"bảo tồn đa dạng sinh học"},{"en":"preserve food","vi":"bảo quản thực phẩm"}],"wordFamily":["preservation (n.)","preservative (n.)"],"synonyms":["protect","conserve"],"antonyms":["destroy"],"tipVi":"preserve nhấn mạnh việc giữ nguyên trạng thái; dùng cả trong việc bảo quản thực phẩm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_greenhouse', 'en-b2-25', 'greenhouse', '/ˈɡriːnhaʊs/', 'B2', 'nhà kính, nhà ươm cây', 'n.', NULL, 'Đồng nghĩa: glasshouse', 'greenhouse là danh từ, đồng thời có thể dùng làm tính từ bổ nghĩa, ví dụ như greenhouse gases.', 'We grow tomatoes in the greenhouse throughout the winter.', NULL, 'Chúng tôi trồng cà chua trong nhà kính suốt cả mùa đông.', '{"wordId":"greenhouse","ukIpa":"/ˈɡriːnhaʊs/","usIpa":"/ˈɡriːnhaʊs/","cefr":"B2","topic":"environment","senses":[{"pos":"n.","en":"a glass or plastic building that keeps growing plants warm","vi":"nhà kính, nhà ươm cây"}],"examples":[{"en":"We grow tomatoes in the greenhouse throughout the winter.","vi":"Chúng tôi trồng cà chua trong nhà kính suốt cả mùa đông.","audioKind":"ex"},{"en":"Greenhouse cultivation can extend growing seasons, although heating these structures may require considerable amounts of energy.","vi":"Việc canh tác trong nhà kính có thể kéo dài thời gian sinh trưởng, mặc dù việc sưởi ấm các cấu trúc này có thể tiêu tốn một lượng năng lượng đáng kể.","audioKind":"ex2"}],"collocations":[{"en":"grow plants in a greenhouse","vi":"trồng cây trong nhà kính"},{"en":"greenhouse gas emissions","vi":"phát thải khí nhà kính"},{"en":"the greenhouse effect","vi":"hiệu ứng nhà kính"}],"wordFamily":[],"synonyms":["glasshouse"],"antonyms":[],"tipVi":"greenhouse là danh từ, đồng thời có thể dùng làm tính từ bổ nghĩa, ví dụ như greenhouse gases.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_25_1', 'en-b2-25', 'Cách dùng “timber” (n.) — gỗ xây dựng; gỗ nguyên liệu', 'timber industry  ·  timber frame  ·  sustainably sourced timber', 'Khi chỉ chất liệu gỗ thì thường là danh từ không đếm được; tiếng Anh-Mỹ thường dùng lumber để chỉ gỗ đã qua chế biến.', 'Đồng nghĩa: wood, lumber', '[{"hanzi":"The carpenter stacked the timber beside the workshop.","pinyin":"","meaning":"Người thợ mộc xếp đống gỗ xây dựng bên cạnh xưởng làm việc."},{"hanzi":"Using responsibly sourced timber in construction can reduce environmental damage while supporting sustainable forest management.","pinyin":"","meaning":"Sử dụng gỗ có nguồn gốc bền vững trong xây dựng có thể làm giảm tác hại môi trường đồng thời hỗ trợ quản lý rừng bền vững."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_25_2', 'en-b2-25', 'Cách dùng “scarce” (adj.) — khan hiếm; thiếu thốn', 'scarce resources  ·  become scarce  ·  increasingly scarce', 'scarce chỉ tình trạng thiếu hụt nguồn cung; trong khi rare nhấn mạnh sự hiếm có, không nhất thiết là thiếu thốn.', 'Họ từ (Word Family): scarcity (n.) | Đồng nghĩa: limited · Trái nghĩa: abundant, plentiful', '[{"hanzi":"Fresh vegetables became scarce after snow blocked the roads.","pinyin":"","meaning":"Rau tươi trở nên khan hiếm sau khi tuyết chặn đứt các con đường."},{"hanzi":"As clean water becomes increasingly scarce, governments must invest in efficient irrigation and better water management systems.","pinyin":"","meaning":"Khi nguồn nước sạch ngày càng trở nên khan hiếm, chính phủ phải đầu tư vào hệ thống tưới tiêu hiệu quả và quản lý nguồn nước tốt hơn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_25_3', 'en-b2-25', 'Cách dùng “ecosystem” (n.) — hệ sinh thái', 'marine ecosystem  ·  fragile ecosystem  ·  protect ecosystems', 'Chỉ hệ thống bao gồm các sinh vật và môi trường tương tác với nhau, không chỉ đơn thuần là quần thể sinh vật.', NULL, '[{"hanzi":"This small pond supports a surprisingly rich ecosystem.","pinyin":"","meaning":"Ao nhỏ này nuôi dưỡng một hệ sinh thái phong phú đến bất ngờ."},{"hanzi":"Removing a single species can disrupt an entire ecosystem because organisms depend on one another for survival.","pinyin":"","meaning":"Việc loại bỏ một loài duy nhất có thể làm gián đoạn toàn bộ hệ sinh thái vì các sinh vật phụ thuộc lẫn nhau để sinh tồn."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_25_4', 'en-b2-25', 'Cách dùng “deforestation” (n.) — phá rừng; nạn phá rừng', 'prevent deforestation  ·  widespread deforestation  ·  tropical deforestation', 'Là danh từ không đếm được; thường được dùng trong các chủ đề về mất môi trường sống và biến đổi khí hậu.', 'Họ từ (Word Family): deforest (v.), forest (n.), reforestation (n.) | Trái nghĩa: reforestation', '[{"hanzi":"Deforestation has left the hillside bare and dusty.","pinyin":"","meaning":"Nạn phá rừng đã làm cho sườn đồi trở nên trọc lóc và đầy bụi bẩn."},{"hanzi":"Reducing deforestation can protect wildlife habitats and help limit the effects of climate change.","pinyin":"","meaning":"Giảm thiểu nạn phá rừng có thể bảo vệ môi trường sống của động vật hoang dã và giúp hạn chế các tác động của biến đổi khí hậu."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_25_1', 'en-b2-25', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_25_1_1', 'ten_b2_25_1', 'conserve', 'We collect rainwater to conserve water in the garden.', 'We collect rainwater to conserve water in the garden.', '/kənˈsɝːv/', 'Chúng tôi thu gom nước mưa để tiết kiệm nước trong vườn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_25_1_2', 'ten_b2_25_1', 'coral', 'Bright fish swam between branches of coral beneath us.', 'Bright fish swam between branches of coral beneath us.', '/ˈkɔːrəl/', 'Những chú cá rực rỡ bơi lội giữa các khóm san hô phía dưới chúng tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_25_1_3', 'ten_b2_25_1', 'ecosystem', 'This small pond supports a surprisingly rich ecosystem.', 'This small pond supports a surprisingly rich ecosystem.', '/ˈiːkoʊsɪstəm/', 'Ao nhỏ này nuôi dưỡng một hệ sinh thái phong phú đến bất ngờ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_25_1_4', 'ten_b2_25_1', 'destruction', 'The storm left a trail of destruction along the coast.', 'The storm left a trail of destruction along the coast.', '/dɪˈstrʌkʃən/', 'Cơn bão để lại một vệt tàn phá dọc theo bờ biển.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_25_1_5', 'ten_b2_25_1', 'humidity', 'The high humidity made my shirt feel damp.', 'The high humidity made my shirt feel damp.', '/hjuːˈmɪdəti/', 'Độ ẩm cao làm cho chiếc áo sơ mi của tôi có cảm giác ẩm ướt.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_25_1_6', 'ten_b2_25_1', 'emission', 'The mechanic checked my car''s emissions this morning.', 'The mechanic checked my car''s emissions this morning.', '/ɪˈmɪʃən/', 'Thợ máy đã kiểm tra lượng khí thải ô tô của tôi vào sáng nay.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_25_1_7', 'ten_b2_25_1', 'ecology', 'My sister studies ecology and often visits local wetlands.', 'My sister studies ecology and often visits local wetlands.', '/iˈkɑːlədʒi/', 'Chị tôi học ngành sinh thái học và thường xuyên đến thăm các vùng đất ngập nước ở địa phương.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_25_1_8', 'ten_b2_25_1', 'severe', 'Severe storms knocked down several trees near our house.', 'Severe storms knocked down several trees near our house.', '/səˈvɪr/', 'Những cơn bão dữ dội đã quật ngã vài cái cây gần nhà chúng tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_25_1_1', 'en-b2-25', 'ten_b2_25_1', 'listening', 'listening', 'We collect rainwater to conserve water in the garden.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những chú cá rực rỡ bơi lội giữa các khóm san hô phía dưới chúng tôi.","Rau tươi trở nên khan hiếm sau khi tuyết chặn đứt các con đường.","Chúng tôi trồng cà chua trong nhà kính suốt cả mùa đông.","Chúng tôi thu gom nước mưa để tiết kiệm nước trong vườn."]'::jsonb, 3, 'We collect rainwater to conserve water in the garden. → Chúng tôi thu gom nước mưa để tiết kiệm nước trong vườn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_25_1_2', 'en-b2-25', 'ten_b2_25_1', 'listening', 'listening', 'Bright fish swam between branches of coral beneath us.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những chú cá rực rỡ bơi lội giữa các khóm san hô phía dưới chúng tôi.","Chúng tôi ngắm nhìn những chú cá đầy màu sắc bơi lội xung quanh rạn san hô.","Chúng tôi thu gom nước mưa để tiết kiệm nước trong vườn.","Những cơn bão dữ dội đã quật ngã vài cái cây gần nhà chúng tôi."]'::jsonb, 0, 'Bright fish swam between branches of coral beneath us. → Những chú cá rực rỡ bơi lội giữa các khóm san hô phía dưới chúng tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_25_1_3', 'en-b2-25', 'ten_b2_25_1', 'listening', 'listening', 'This small pond supports a surprisingly rich ecosystem.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những cơn bão dữ dội đã quật ngã vài cái cây gần nhà chúng tôi.","Ao nhỏ này nuôi dưỡng một hệ sinh thái phong phú đến bất ngờ.","Các kỹ sư đã khôi phục lại nguồn điện trước khi thức ăn của chúng tôi bị hỏng.","Những chú cá rực rỡ bơi lội giữa các khóm san hô phía dưới chúng tôi."]'::jsonb, 1, 'This small pond supports a surprisingly rich ecosystem. → Ao nhỏ này nuôi dưỡng một hệ sinh thái phong phú đến bất ngờ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_25_2', 'en-b2-25', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_25_2_1', 'ten_b2_25_2', 'conserve', 'Governments should encourage efficient farming methods that conserve water without reducing the supply of affordable food.', 'Governments should encourage efficient farming methods that conserve water without reducing the supply of affordable food.', '/kənˈsɝːv/', 'Chính phủ nên khuyến khích các phương thức canh tác hiệu quả giúp tiết kiệm nước mà không làm giảm nguồn cung thực phẩm có giá cả phải chăng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_25_2_2', 'ten_b2_25_2', 'coral', 'Rising ocean temperatures threaten coral reefs, which provide essential habitats for many marine species.', 'Rising ocean temperatures threaten coral reefs, which provide essential habitats for many marine species.', '/ˈkɔːrəl/', 'Nhiệt độ đại dương tăng cao đang đe dọa các rạn san hô, nơi cung cấp môi trường sống thiết yếu cho nhiều loài sinh vật biển.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_25_2_3', 'ten_b2_25_2', 'ecosystem', 'Removing a single species can disrupt an entire ecosystem because organisms depend on one another for survival.', 'Removing a single species can disrupt an entire ecosystem because organisms depend on one another for survival.', '/ˈiːkoʊsɪstəm/', 'Việc loại bỏ một loài duy nhất có thể làm gián đoạn toàn bộ hệ sinh thái vì các sinh vật phụ thuộc lẫn nhau để sinh tồn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_25_2_4', 'ten_b2_25_2', 'destruction', 'The destruction of natural habitats threatens biodiversity and reduces the resources available to local communities.', 'The destruction of natural habitats threatens biodiversity and reduces the resources available to local communities.', '/dɪˈstrʌkʃən/', 'Sự tàn phá các môi trường sống tự nhiên đe dọa sự đa dạng sinh học và làm giảm các nguồn tài nguyên sẵn có cho cộng đồng địa phương.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_25_2_5', 'ten_b2_25_2', 'humidity', 'High humidity can reduce comfort in classrooms, making effective ventilation particularly important during warmer months.', 'High humidity can reduce comfort in classrooms, making effective ventilation particularly important during warmer months.', '/hjuːˈmɪdəti/', 'Độ ẩm cao có thể làm giảm sự thoải mái trong phòng học, khiến việc thông gió hiệu quả trở nên đặc biệt quan trọng trong những tháng ấm hơn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_25_2_6', 'ten_b2_25_2', 'emission', 'Governments can reduce carbon emissions by investing in renewable energy and improving public transport networks.', 'Governments can reduce carbon emissions by investing in renewable energy and improving public transport networks.', '/ɪˈmɪʃən/', 'Chính phủ có thể giảm lượng khí thải carbon bằng cách đầu tư vào năng lượng tái tạo và cải thiện mạng lưới giao thông công cộng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_25_2_1', 'en-b2-25', 'ten_b2_25_2', 'listening', 'listening', 'Governments should encourage efficient farming methods that conserve water without reducing the supply of affordable food.', NULL, 'Trong câu vừa nghe, từ “conserve” mang nghĩa nào sau đây?', '["sự theo đuổi; sự mưu cầu","tiết kiệm","chất; chất liệu","bảo hành; giấy bảo hành"]'::jsonb, 1, '“conserve” (/kənˈsɝːv/): tiết kiệm. Câu đầy đủ: Governments should encourage efficient farming methods that conserve water without reducing the supply of affordable food.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_25_2_2', 'en-b2-25', 'ten_b2_25_2', 'listening', 'listening', 'Rising ocean temperatures threaten coral reefs, which provide essential habitats for many marine species.', NULL, 'Trong câu vừa nghe, từ “coral” mang nghĩa nào sau đây?', '["san hô; động vật san hô","thuộc về bán đảo Ả Rập","làm sắc; mài giũa; gọt nhọn","chuyên môn; sở trường"]'::jsonb, 0, '“coral” (/ˈkɔːrəl/): san hô; động vật san hô. Câu đầy đủ: Rising ocean temperatures threaten coral reefs, which provide essential habitats for many marine species.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
