INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_25_2', 'en-b2-25', NULL, 'comprehensive_test', 'listening', 'Bright fish swam between branches of coral beneath us.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ao nhỏ này nuôi dưỡng một hệ sinh thái phong phú đến bất ngờ.","Chị tôi học ngành sinh thái học và thường xuyên đến thăm các vùng đất ngập nước ở địa phương.","Những chú cá rực rỡ bơi lội giữa các khóm san hô phía dưới chúng tôi.","Chúng tôi ngắm nhìn những chú cá đầy màu sắc bơi lội xung quanh rạn san hô."]'::jsonb, 2, 'Bright fish swam between branches of coral beneath us. → Những chú cá rực rỡ bơi lội giữa các khóm san hô phía dưới chúng tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_25_3', 'en-b2-25', NULL, 'comprehensive_test', 'listening', 'ecosystem', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đàn clarinet; kèn clarinet","tiêm chủng; việc tiêm vắc-xin","hệ sinh thái","vỗ nhẹ; xoa nhẹ"]'::jsonb, 2, 'ecosystem (/ˈiːkoʊsɪstəm/) → hệ sinh thái', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_25_4', 'en-b2-25', NULL, 'comprehensive_test', 'listening', 'The storm left a trail of destruction along the coast.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nạn phá rừng đã làm cho sườn đồi trở nên trọc lóc và đầy bụi bẩn.","Người thợ mộc xếp đống gỗ xây dựng bên cạnh xưởng làm việc.","Thợ máy đã kiểm tra lượng khí thải ô tô của tôi vào sáng nay.","Cơn bão để lại một vệt tàn phá dọc theo bờ biển."]'::jsonb, 3, 'The storm left a trail of destruction along the coast. → Cơn bão để lại một vệt tàn phá dọc theo bờ biển.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_25_5', 'en-b2-25', NULL, 'comprehensive_test', 'listening', 'humidity', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["độ ẩm không khí","boong tàu; tầng xe buýt","rượu mạnh","làm lớn hơn; mở rộng; phóng to"]'::jsonb, 0, 'humidity (/hjuːˈmɪdəti/) → độ ẩm không khí', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_25_6', 'en-b2-25', NULL, 'comprehensive_test', 'listening', 'The mechanic checked my car''s emissions this morning.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Trung tâm cứu hộ đang chăm sóc cho một số loài chim đang bị đe dọa.","Thợ máy đã kiểm tra lượng khí thải ô tô của tôi vào sáng nay.","Tôi có thể vứt bỏ những viên pin cũ này một cách an toàn ở đâu?","Chúng tôi thu gom nước mưa để tiết kiệm nước trong vườn."]'::jsonb, 1, 'The mechanic checked my car''s emissions this morning. → Thợ máy đã kiểm tra lượng khí thải ô tô của tôi vào sáng nay.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_25_7', 'en-b2-25', NULL, 'comprehensive_test', 'listening', 'ecology', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["làm suy yếu; làm cho yếu đi; suy giảm","sinh thái học","sự mê tín; điều mê tín dị đoan","móc treo; cọc; chốt"]'::jsonb, 1, 'ecology (/iˈkɑːlədʒi/) → sinh thái học; sinh thái; quan hệ sinh thái', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_25_8', 'en-b2-25', NULL, 'comprehensive_test', 'listening', 'Severe storms knocked down several trees near our house.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những cơn bão dữ dội đã quật ngã vài cái cây gần nhà chúng tôi.","Ao nhỏ này nuôi dưỡng một hệ sinh thái phong phú đến bất ngờ.","Chúng tôi trồng cà chua trong nhà kính suốt cả mùa đông.","Những chú cá rực rỡ bơi lội giữa các khóm san hô phía dưới chúng tôi."]'::jsonb, 0, 'Severe storms knocked down several trees near our house. → Những cơn bão dữ dội đã quật ngã vài cái cây gần nhà chúng tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_25_9', 'en-b2-25', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “The amount of water vapour in the air”?', '["humidity","man-made","deforestation","ecosystem"]'::jsonb, 0, 'humidity (/hjuːˈmɪdəti/) → độ ẩm không khí', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
