INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_25_18', 'en-b2-25', NULL, 'comprehensive_test', 'reading', NULL, 'Governments should encourage efficient farming methods that conserve water without reducing the supply of affordable food.', 'Dựa vào câu trên, từ “conserve” có nghĩa phù hợp nhất là gì?', '["tương đương, ngang bằng (về giá trị, số lượng, ý nghĩa hoặc chức năng)","thanh thiếu niên","tiết kiệm","thường; thông thường; đại khái là"]'::jsonb, 2, 'conserve: tiết kiệm; bảo tồn; bảo vệ. Dịch cả câu: Chính phủ nên khuyến khích các phương thức canh tác hiệu quả giúp tiết kiệm nước mà không làm giảm nguồn cung thực phẩm có giá cả phải chăng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_25_19', 'en-b2-25', NULL, 'comprehensive_test', 'reading', NULL, 'Rising ocean temperatures threaten coral reefs, which provide essential habitats for many marine species.', 'Dựa vào câu trên, từ “coral” có nghĩa phù hợp nhất là gì?', '["vũ khí, trang thiết bị quân sự","quan điểm; góc nhìn","san hô; động vật san hô","dữ dội; gay gắt; cực kỳ"]'::jsonb, 2, 'coral: san hô; động vật san hô; màu hồng cam; màu san hô. Dịch cả câu: Nhiệt độ đại dương tăng cao đang đe dọa các rạn san hô, nơi cung cấp môi trường sống thiết yếu cho nhiều loài sinh vật biển.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_25_20', 'en-b2-25', NULL, 'comprehensive_test', 'reading', NULL, 'Removing a single species can disrupt an entire ecosystem because organisms depend on one another for survival.', 'Dựa vào câu trên, từ “ecosystem” có nghĩa phù hợp nhất là gì?', '["hiện ra; xuất hiện; nổi lên","về cơ bản; bản chất là; cốt lõi là","miễn cưỡng; bất đắc dĩ; ngần ngại","hệ sinh thái"]'::jsonb, 3, 'ecosystem: hệ sinh thái. Dịch cả câu: Việc loại bỏ một loài duy nhất có thể làm gián đoạn toàn bộ hệ sinh thái vì các sinh vật phụ thuộc lẫn nhau để sinh tồn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_25_21', 'en-b2-25', NULL, 'comprehensive_test', 'reading', NULL, 'The destruction of natural habitats threatens biodiversity and reduces the resources available to local communities.', 'Dựa vào câu trên, từ “destruction” có nghĩa phù hợp nhất là gì?', '["thuộc về biển; sinh vật biển","sự nuôi nấng; sự dạy dỗ; giáo dục gia đình","sự tàn phá; sự phá hủy","giải trí; mang tính thư giãn"]'::jsonb, 2, 'destruction: sự tàn phá; sự phá hủy. Dịch cả câu: Sự tàn phá các môi trường sống tự nhiên đe dọa sự đa dạng sinh học và làm giảm các nguồn tài nguyên sẵn có cho cộng đồng địa phương.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_25_22', 'en-b2-25', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “gỗ xây dựng; gỗ nguyên liệu”', '["ceramics","mankind","limitation","timber"]'::jsonb, 3, 'gỗ xây dựng; gỗ nguyên liệu → timber (/ˈtɪmbər/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_25_23', 'en-b2-25', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bảo vệ; bảo quản; duy trì”', '["socialism","preserve","constant","huddle"]'::jsonb, 1, 'bảo vệ; bảo quản; duy trì → preserve (/prɪˈzɝːv/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_25_24', 'en-b2-25', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nhà kính, nhà ươm cây”', '["shepherd","recession","greenhouse","trek"]'::jsonb, 2, 'nhà kính, nhà ươm cây → greenhouse (/ˈɡriːnhaʊs/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-26', 'en', 'Bài 26: Sức khỏe & Cơ thể (1) - CEFR B2', 'CEFR B2', 'B2 · Sức khỏe', '25 từ vựng Tiếng Anh CEFR B2 chủ đề sức khỏe & cơ thể kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4026, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_irritation', 'en-b2-26', 'irritation', '/ˌɪrɪˈteɪʃən/', 'B2', 'sự bực bội; nỗi khó chịu; sự kích ứng; sự mẩn ngứa', 'n.', 'irritate (v.), irritated (adj.), irritating (adj.), irritable (adj.)', 'Đồng nghĩa: annoyance', 'Có thể dùng để chỉ sự bực bội về mặt cảm xúc, hoặc tình trạng kích ứng, khó chịu trên da.', 'He sighed with irritation when the phone rang again.', NULL, 'Anh ấy thở dài đầy bực bội khi điện thoại lại reo lên lần nữa.', '{"wordId":"irritation","ukIpa":"/ˌɪrɪˈteɪʃən/","usIpa":"/ˌɪrɪˈteɪʃən/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"the feeling of being annoyed","vi":"sự bực bội; nỗi khó chịu"},{"pos":"n.","en":"soreness or discomfort in a part of the body","vi":"sự kích ứng; sự mẩn ngứa"}],"examples":[{"en":"He sighed with irritation when the phone rang again.","vi":"Anh ấy thở dài đầy bực bội khi điện thoại lại reo lên lần nữa.","audioKind":"ex"},{"en":"Exposure to household cleaning products may cause skin irritation, especially among people with sensitive skin.","vi":"Tiếp xúc với các sản phẩm vệ sinh gia dụng có thể gây kích ứng da, đặc biệt đối với những người có làn da nhạy cảm.","audioKind":"ex2"}],"collocations":[{"en":"skin irritation","vi":"kích ứng da"},{"en":"eye irritation","vi":"kích ứng mắt"},{"en":"a source of irritation","vi":"nguồn gây khó chịu"}],"wordFamily":["irritate (v.)","irritated (adj.)","irritating (adj.)","irritable (adj.)"],"synonyms":["annoyance"],"antonyms":[],"tipVi":"Có thể dùng để chỉ sự bực bội về mặt cảm xúc, hoặc tình trạng kích ứng, khó chịu trên da.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_calory', 'en-b2-26', 'calory', '/ˈkæləri/', 'B2', 'calo (đơn vị đo nhiệt lượng hoặc năng lượng từ thức ăn)', 'n.', 'calorie (n.), caloric (adj.), calorific (adj.)', 'Đồng nghĩa: calorie', 'calory là biến thể ít dùng; trong văn viết hiện đại hãy dùng calorie.', 'I do not count every calory in my lunch.', NULL, 'Tôi không tính từng calo trong bữa trưa của mình.', '{"wordId":"calory","ukIpa":"/ˈkæləri/","usIpa":"/ˈkæləri/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"A unit measuring heat energy or energy supplied by food.","vi":"calo (đơn vị đo nhiệt lượng hoặc năng lượng từ thức ăn)"}],"examples":[{"en":"I do not count every calory in my lunch.","vi":"Tôi không tính từng calo trong bữa trưa của mình.","audioKind":"ex"},{"en":"Although calory intake matters, public health advice should also consider nutritional quality and access to fresh food.","vi":"Mặc dù lượng calo nạp vào rất quan trọng, nhưng các khuyến nghị về sức khỏe cộng đồng cũng cần xem xét chất lượng dinh dưỡng và khả năng tiếp cận thực phẩm tươi sống.","audioKind":"ex2"}],"collocations":[{"en":"calory intake","vi":"lượng calo nạp vào"},{"en":"calory content","vi":"hàm lượng calo"}],"wordFamily":["calorie (n.)","caloric (adj.)","calorific (adj.)"],"synonyms":["calorie"],"antonyms":[],"tipVi":"calory là biến thể ít dùng; trong văn viết hiện đại hãy dùng calorie.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_alcoholism', 'en-b2-26', 'alcoholism', '/ˈælkəhɔːlɪzəm/', 'B2', 'chứng nghiện rượu; tình trạng lệ thuộc vào rượu', 'n.', 'alcohol (n.), alcoholic (adj.)', 'Đồng nghĩa: alcohol dependence', 'Chỉ bệnh trạng nghiện rượu, không chỉ người nghiện rượu.', 'The clinic offers confidential support for people with alcoholism.', NULL, 'Phòng khám cung cấp dịch vụ hỗ trợ bảo mật cho những người gặp vấn đề về nghiện rượu.', '{"wordId":"alcoholism","ukIpa":"/ˈælkəhɒlɪzəm/","usIpa":"/ˈælkəhɔːlɪzəm/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"a condition involving dependence on alcohol and difficulty controlling drinking","vi":"chứng nghiện rượu; tình trạng lệ thuộc vào rượu"}],"examples":[{"en":"The clinic offers confidential support for people with alcoholism.","vi":"Phòng khám cung cấp dịch vụ hỗ trợ bảo mật cho những người gặp vấn đề về nghiện rượu.","audioKind":"ex"},{"en":"Effective treatment for alcoholism often combines medical care, psychological support, and help from family members.","vi":"Phương pháp điều trị chứng nghiện rượu hiệu quả thường kết hợp chăm sóc y tế, hỗ trợ tâm lý và sự giúp đỡ từ các thành viên trong gia đình.","audioKind":"ex2"}],"collocations":[{"en":"treatment for alcoholism","vi":"điều trị chứng nghiện rượu"},{"en":"recover from alcoholism","vi":"hồi phục sau cơn nghiện rượu"},{"en":"chronic alcoholism","vi":"chứng nghiện rượu mãn tính"}],"wordFamily":["alcohol (n.)","alcoholic (adj.)"],"synonyms":["alcohol dependence"],"antonyms":[],"tipVi":"Chỉ bệnh trạng nghiện rượu, không chỉ người nghiện rượu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_capsule', 'en-b2-26', 'capsule', '/ˈkæpsəl/', 'B2', 'viên nang; viên con nhộng; khoang tàu vũ trụ; khoang kín nhỏ', 'n.', 'encapsulate (v.), encapsulation (n.)', NULL, 'Thuốc dạng "capsule" có lớp vỏ bọc; còn "tablet" thường là viên nén.', 'The pharmacist told me to swallow the capsule with water.', NULL, 'Dược sĩ dặn tôi uống viên nang này với nước.', '{"wordId":"capsule","ukIpa":"/ˈkæpsjuːl/","usIpa":"/ˈkæpsəl/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"a small soluble case containing medicine that you swallow","vi":"viên nang; viên con nhộng"},{"pos":"n.","en":"a small enclosed compartment carrying people or equipment in space","vi":"khoang tàu vũ trụ; khoang kín nhỏ"}],"examples":[{"en":"The pharmacist told me to swallow the capsule with water.","vi":"Dược sĩ dặn tôi uống viên nang này với nước.","audioKind":"ex"},{"en":"The space capsule was designed to protect its crew from extreme temperatures during their return to Earth.","vi":"Khoang tàu vũ trụ được thiết kế để bảo vệ phi hành đoàn khỏi nhiệt độ khắc nghiệt trong quá trình trở về Trái Đất.","audioKind":"ex2"}],"collocations":[{"en":"swallow a capsule","vi":"uống viên nang"},{"en":"space capsule","vi":"khoang tàu vũ trụ"},{"en":"time capsule","vi":"hộp thời gian"}],"wordFamily":["encapsulate (v.)","encapsulation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thuốc dạng \"capsule\" có lớp vỏ bọc; còn \"tablet\" thường là viên nén.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_jaw', 'en-b2-26', 'jaw', '/dʒɔː/', 'B2', 'hàm; xương hàm', 'n.', NULL, NULL, 'jaw chỉ hàm xương hoặc vùng hàm; chin chỉ riêng phần cằm ở dưới cùng của khuôn mặt.', 'My jaw felt sore after chewing the hard bread.', NULL, 'Hàm của tôi thấy ê ẩm sau khi nhai miếng bánh mì cứng ngắc đó.', '{"wordId":"jaw","ukIpa":"/dʒɔː/","usIpa":"/dʒɔː/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"either bone structure in the mouth that holds the teeth","vi":"hàm; xương hàm"}],"examples":[{"en":"My jaw felt sore after chewing the hard bread.","vi":"Hàm của tôi thấy ê ẩm sau khi nhai miếng bánh mì cứng ngắc đó.","audioKind":"ex"},{"en":"Protective equipment can reduce the risk of jaw injuries among people who participate in contact sports.","vi":"Thiết bị bảo hộ có thể làm giảm nguy cơ chấn thương vùng hàm cho những người tham gia các môn thể thao va chạm.","audioKind":"ex2"}],"collocations":[{"en":"lower jaw","vi":"hàm dưới"},{"en":"upper jaw","vi":"hàm trên"},{"en":"clench your jaw","vi":"cắn chặt hàm"},{"en":"jaw injury","vi":"chấn thương hàm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"jaw chỉ hàm xương hoặc vùng hàm; chin chỉ riêng phần cằm ở dưới cùng của khuôn mặt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vegan', 'en-b2-26', 'vegan', '/ˈviːɡən/', 'B2', 'người ăn chay thuần (không ăn thịt và các sản phẩm từ động vật); thuần chay (không chứa thành phần động vật)', 'n.', 'veganism (n.)', NULL, 'vegan không ăn trứng và sữa; vegetarian thường vẫn ăn trứng và sữa.', 'As a vegan, I cook with beans instead of meat.', NULL, 'Là một người ăn chay thuần, tôi nấu ăn bằng đậu thay vì thịt.', '{"wordId":"vegan","ukIpa":"/ˈviːɡən/","usIpa":"/ˈviːɡən/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"Someone who avoids animal foods and usually other animal products.","vi":"người ăn chay thuần (không ăn thịt và các sản phẩm từ động vật)"},{"pos":"adj.","en":"Using or containing no animal products.","vi":"thuần chay (không chứa thành phần động vật)"}],"examples":[{"en":"As a vegan, I cook with beans instead of meat.","vi":"Là một người ăn chay thuần, tôi nấu ăn bằng đậu thay vì thịt.","audioKind":"ex"},{"en":"A carefully planned vegan diet can meet nutritional needs while reducing some environmental impacts of food production.","vi":"Một chế độ ăn thuần chay được lên kế hoạch kỹ lưỡng có thể đáp ứng nhu cầu dinh dưỡng đồng thời giảm thiểu một số tác động môi trường từ việc sản xuất thực phẩm.","audioKind":"ex2"}],"collocations":[{"en":"a vegan diet","vi":"chế độ ăn thuần chay"},{"en":"vegan food","vi":"thực phẩm thuần chay"},{"en":"go vegan","vi":"theo lối sống thuần chay"},{"en":"vegan leather","vi":"da nhân tạo thuần chay"}],"wordFamily":["veganism (n.)"],"synonyms":[],"antonyms":[],"tipVi":"vegan không ăn trứng và sữa; vegetarian thường vẫn ăn trứng và sữa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_energetic', 'en-b2-26', 'energetic', '/ˌenərˈdʒetɪk/', 'B2', 'tràn đầy năng lượng; năng nổ; hoạt bát', 'adj.', 'energy (n.), energetically (adv.), energise (v.)', 'Đồng nghĩa: lively, vigorous · Trái nghĩa: lethargic, listless', 'energetic là tính từ miêu tả con người hoặc hoạt động có nhiều năng lượng; energy là danh từ.', 'Our energetic puppy chased a ball around the garden.', NULL, 'Chú chó con đầy năng lượng của chúng tôi đuổi theo quả bóng quanh khu vườn.', '{"wordId":"energetic","ukIpa":"/ˌenəˈdʒetɪk/","usIpa":"/ˌenərˈdʒetɪk/","cefr":"B2","topic":"health","senses":[{"pos":"adj.","en":"Having or showing plenty of energy and enthusiasm.","vi":"tràn đầy năng lượng; năng nổ; hoạt bát"}],"examples":[{"en":"Our energetic puppy chased a ball around the garden.","vi":"Chú chó con đầy năng lượng của chúng tôi đuổi theo quả bóng quanh khu vườn.","audioKind":"ex"},{"en":"Regular physical activity can help office workers feel more energetic and maintain concentration throughout the day.","vi":"Hoạt động thể chất đều đặn có thể giúp nhân viên văn phòng cảm thấy tràn đầy năng lượng hơn và duy trì sự tập trung trong suốt cả ngày.","audioKind":"ex2"}],"collocations":[{"en":"feel energetic","vi":"cảm thấy tràn đầy năng lượng"},{"en":"energetic children","vi":"những đứa trẻ năng động"},{"en":"energetic approach","vi":"phương pháp tiếp cận mạnh mẽ"}],"wordFamily":["energy (n.)","energetically (adv.)","energise (v.)"],"synonyms":["lively","vigorous"],"antonyms":["lethargic","listless"],"tipVi":"energetic là tính từ miêu tả con người hoặc hoạt động có nhiều năng lượng; energy là danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wound', 'en-b2-26', 'wound', '/wuːnd/', 'B2', 'vết thương; thương tích; làm bị thương; gây thương tích; làm tổn thương sâu sắc (tâm lý, tình cảm)', 'n.', 'wounded (adj.)', 'Đồng nghĩa: injury, injure · Trái nghĩa: heal', 'Danh từ vết thương đọc là /wuːnd/; dạng quá khứ của từ wind là wound đọc là /waʊnd/.', 'The nurse gently cleaned the wound on my knee.', NULL, 'Cô y tá nhẹ nhàng rửa sạch vết thương trên đầu gối của tôi.', '{"wordId":"wound","ukIpa":"/wuːnd/","usIpa":"/wuːnd/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"An injury involving damage to skin or other body tissue.","vi":"vết thương; thương tích"},{"pos":"v.","en":"To injure someone''s body, especially by damaging the skin.","vi":"làm bị thương; gây thương tích"},{"pos":"v.","en":"To hurt someone''s feelings deeply.","vi":"làm tổn thương sâu sắc (tâm lý, tình cảm)"}],"examples":[{"en":"The nurse gently cleaned the wound on my knee.","vi":"Cô y tá nhẹ nhàng rửa sạch vết thương trên đầu gối của tôi.","audioKind":"ex"},{"en":"Access to clean water and basic medical supplies is essential for treating wounds and preventing infection.","vi":"Việc tiếp cận nguồn nước sạch và các vật tư y tế cơ bản là vô cùng thiết yếu để xử lý vết thương và ngăn ngừa nhiễm trùng.","audioKind":"ex2"}],"collocations":[{"en":"a deep wound","vi":"vết thương sâu"},{"en":"treat a wound","vi":"xử lý vết thương"},{"en":"wound someone''s pride","vi":"làm tổn thương lòng tự trọng của ai đó"}],"wordFamily":["wounded (adj.)"],"synonyms":["injury","injure"],"antonyms":["heal"],"tipVi":"Danh từ vết thương đọc là /wuːnd/; dạng quá khứ của từ wind là wound đọc là /waʊnd/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_suffering', 'en-b2-26', 'suffering', '/ˈsʌfərɪŋ/', 'B2', 'nỗi đau đớn; sự khổ sở', 'n.', 'suffer (v.), sufferer (n.)', 'Đồng nghĩa: distress, pain, anguish', 'Khi dùng chỉ sự đau đớn chung thường không đếm được; sufferings dùng để chỉ nhiều loại khổ nạn khác nhau.', 'The medicine eased her suffering and helped her sleep.', NULL, 'Liều thuốc đã làm dịu bớt nỗi đau của cô ấy và giúp cô dễ ngủ hơn.', '{"wordId":"suffering","ukIpa":"/ˈsʌfərɪŋ/","usIpa":"/ˈsʌfərɪŋ/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"Physical or mental pain experienced by people or animals.","vi":"nỗi đau đớn; sự khổ sở"}],"examples":[{"en":"The medicine eased her suffering and helped her sleep.","vi":"Liều thuốc đã làm dịu bớt nỗi đau của cô ấy và giúp cô dễ ngủ hơn.","audioKind":"ex"},{"en":"Improving access to clean water can reduce human suffering in communities affected by prolonged drought.","vi":"Việc cải thiện khả năng tiếp cận nước sạch có thể làm giảm bớt nỗi thống khổ của con người tại các cộng đồng chịu ảnh hưởng bởi hạn hán kéo dài.","audioKind":"ex2"}],"collocations":[{"en":"alleviate suffering","vi":"xoa dịu nỗi đau"},{"en":"human suffering","vi":"nỗi khổ của nhân loại"},{"en":"unnecessary suffering","vi":"nỗi đau không cần thiết"}],"wordFamily":["suffer (v.)","sufferer (n.)"],"synonyms":["distress","pain","anguish"],"antonyms":[],"tipVi":"Khi dùng chỉ sự đau đớn chung thường không đếm được; sufferings dùng để chỉ nhiều loại khổ nạn khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_skull', 'en-b2-26', 'skull', '/skʌl/', 'B2', 'hộp sọ; đầu lâu', 'n.', NULL, 'Đồng nghĩa: cranium', 'skull chỉ khung xương bảo vệ phần đầu, còn brain chỉ phần não bên trong.', 'The museum displayed the skull of a large dinosaur.', NULL, 'Viện bảo tàng trưng bày hộp sọ của một loài khủng long lớn.', '{"wordId":"skull","ukIpa":"/skʌl/","usIpa":"/skʌl/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"the bony structure of the head that protects the brain","vi":"hộp sọ; đầu lâu"}],"examples":[{"en":"The museum displayed the skull of a large dinosaur.","vi":"Viện bảo tàng trưng bày hộp sọ của một loài khủng long lớn.","audioKind":"ex"},{"en":"Wearing a properly fitted helmet helps protect the skull and brain during cycling accidents.","vi":"Đội mũ bảo hiểm vừa vặn giúp bảo vệ hộp sọ và bộ não khi xảy ra tai nạn xe đạp.","audioKind":"ex2"}],"collocations":[{"en":"a skull fracture","vi":"nứt hộp sọ"},{"en":"the base of the skull","vi":"vùng nền sọ"},{"en":"a human skull","vi":"hộp sọ người"}],"wordFamily":[],"synonyms":["cranium"],"antonyms":[],"tipVi":"skull chỉ khung xương bảo vệ phần đầu, còn brain chỉ phần não bên trong.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_digestion', 'en-b2-26', 'digestion', '/daɪˈdʒestʃən/', 'B2', 'sự tiêu hóa; khả năng tiêu hóa', 'n.', 'digest (v.), digestive (adj.), digestible (adj.), indigestion (n.)', NULL, 'Danh từ này thường không đếm được; từ chỉ chứng khó tiêu là indigestion.', 'Drinking enough water helps keep your digestion working well.', NULL, 'Uống đủ nước giúp duy trì hoạt động tiêu hóa của cơ thể diễn ra suôn sẻ.', '{"wordId":"digestion","ukIpa":"/daɪˈdʒestʃən/","usIpa":"/daɪˈdʒestʃən/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"the process of breaking down food so the body absorbs nutrients","vi":"sự tiêu hóa; khả năng tiêu hóa"}],"examples":[{"en":"Drinking enough water helps keep your digestion working well.","vi":"Uống đủ nước giúp duy trì hoạt động tiêu hóa của cơ thể diễn ra suôn sẻ.","audioKind":"ex"},{"en":"A balanced diet supports healthy digestion and provides the nutrients needed for growth and daily activity.","vi":"Một chế độ ăn uống cân đối sẽ hỗ trợ quá trình tiêu hóa khỏe mạnh và cung cấp các chất dinh dưỡng cần thiết cho sự phát triển cũng như các hoạt động hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"aid digestion","vi":"hỗ trợ tiêu hóa"},{"en":"healthy digestion","vi":"hệ tiêu hóa khỏe mạnh"},{"en":"poor digestion","vi":"chứng tiêu hóa kém"}],"wordFamily":["digest (v.)","digestive (adj.)","digestible (adj.)","indigestion (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ này thường không đếm được; từ chỉ chứng khó tiêu là indigestion.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sprain', 'en-b2-26', 'sprain', '/spreɪn/', 'B2', 'trật khớp; bong gân; chấn thương bong gân', 'v.', 'sprained (adj.)', NULL, 'sprain chỉ trật khớp, bong gân; strain thường chỉ căng cơ hoặc gân.', 'I sprained my ankle while running for the bus.', NULL, 'Tôi đã bị trật khớp chân khi chạy đuổi theo xe buýt.', '{"wordId":"sprain","ukIpa":"/spreɪn/","usIpa":"/spreɪn/","cefr":"B2","topic":"health","senses":[{"pos":"v.","en":"To injure a joint by twisting it too far.","vi":"trật khớp; bong gân"},{"pos":"n.","en":"An injury caused by twisting a joint too far.","vi":"chấn thương bong gân"}],"examples":[{"en":"I sprained my ankle while running for the bus.","vi":"Tôi đã bị trật khớp chân khi chạy đuổi theo xe buýt.","audioKind":"ex"},{"en":"Athletes who sprain a joint should allow sufficient recovery time before returning to competitive sport.","vi":"Các vận động viên bị bong gân khớp nên dành đủ thời gian hồi phục trước khi trở lại thi đấu thể thao.","audioKind":"ex2"}],"collocations":[{"en":"sprain an ankle","vi":"bong gân mắt cá chân"},{"en":"sprain a wrist","vi":"bong gân cổ tay"},{"en":"a severe sprain","vi":"một ca bong gân nặng"}],"wordFamily":["sprained (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"sprain chỉ trật khớp, bong gân; strain thường chỉ căng cơ hoặc gân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vital', 'en-b2-26', 'vital', '/ˈvaɪtəl/', 'B2', 'vô cùng quan trọng; thiết yếu; cần thiết để duy trì sự sống', 'adj.', 'vitally (adv.), vitality (n.)', 'Đồng nghĩa: essential, crucial · Trái nghĩa: unimportant', 'Thường dùng cấu trúc be vital for/to, thể hiện tầm quan trọng cốt lõi đối với cái gì đó.', 'A warm coat is vital on these freezing mornings.', NULL, 'Một chiếc áo khoác ấm là thứ thiết yếu trong những buổi sáng lạnh buốt này.', '{"wordId":"vital","ukIpa":"/ˈvaɪtəl/","usIpa":"/ˈvaɪtəl/","cefr":"B2","topic":"health","senses":[{"pos":"adj.","en":"extremely important or necessary","vi":"vô cùng quan trọng; thiết yếu"},{"pos":"adj.","en":"necessary for keeping a living body alive","vi":"cần thiết để duy trì sự sống"}],"examples":[{"en":"A warm coat is vital on these freezing mornings.","vi":"Một chiếc áo khoác ấm là thứ thiết yếu trong những buổi sáng lạnh buốt này.","audioKind":"ex"},{"en":"Reliable public transport plays a vital role in reducing urban congestion and improving access to employment.","vi":"Giao thông công cộng đáng tin cậy đóng vai trò thiết yếu trong việc giảm ùn tắc đô thị và cải thiện khả năng tiếp cận việc làm.","audioKind":"ex2"}],"collocations":[{"en":"play a vital role","vi":"đóng vai trò thiết yếu"},{"en":"vital importance","vi":"tầm quan trọng cực kỳ lớn"},{"en":"vital organs","vi":"các cơ quan sống còn"},{"en":"vital for survival","vi":"cần thiết cho sự sinh tồn"}],"wordFamily":["vitally (adv.)","vitality (n.)"],"synonyms":["essential","crucial"],"antonyms":["unimportant"],"tipVi":"Thường dùng cấu trúc be vital for/to, thể hiện tầm quan trọng cốt lõi đối với cái gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cure', 'en-b2-26', 'cure', '/kjʊr/', 'B2', 'chữa khỏi; điều trị dứt điểm; phương pháp chữa trị; thuốc chữa', 'v.', 'curable (adj.), incurable (adj.)', 'Đồng nghĩa: heal', 'cure nhấn mạnh việc chữa khỏi hẳn; treat chỉ mang ý nghĩa điều trị chứ không cam kết khỏi bệnh hoàn toàn.', 'The doctor said these tablets could cure the infection.', NULL, 'Bác sĩ nói những viên thuốc này có thể chữa khỏi căn bệnh nhiễm trùng.', '{"wordId":"cure","ukIpa":"/kjʊə/","usIpa":"/kjʊr/","cefr":"B2","topic":"health","senses":[{"pos":"v.","en":"to make a disease disappear or someone healthy again","vi":"chữa khỏi; điều trị dứt điểm"},{"pos":"n.","en":"a treatment that makes a disease or condition disappear","vi":"phương pháp chữa trị; thuốc chữa"}],"examples":[{"en":"The doctor said these tablets could cure the infection.","vi":"Bác sĩ nói những viên thuốc này có thể chữa khỏi căn bệnh nhiễm trùng.","audioKind":"ex"},{"en":"Although medical research has advanced considerably, scientists have not yet found a cure for every disease.","vi":"Mặc dù nghiên cứu y học đã đạt được những tiến bộ đáng kể, các nhà khoa học vẫn chưa tìm ra phương pháp chữa khỏi mọi loại bệnh.","audioKind":"ex2"}],"collocations":[{"en":"cure a disease","vi":"chữa khỏi bệnh"},{"en":"a cure for","vi":"phương thuốc chữa trị cho"},{"en":"cure someone of","vi":"chữa khỏi bệnh gì cho ai"}],"wordFamily":["curable (adj.)","incurable (adj.)"],"synonyms":["heal"],"antonyms":[],"tipVi":"cure nhấn mạnh việc chữa khỏi hẳn; treat chỉ mang ý nghĩa điều trị chứ không cam kết khỏi bệnh hoàn toàn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exhaust', 'en-b2-26', 'exhaust', '/ɪɡˈzɔːst/', 'B2', 'làm kiệt sức; làm mệt lử; dùng cạn; cạn kiệt; tiêu thụ hết; khí thải; ống xả', 'v.', 'exhausted (adj.), exhausting (adj.), exhaustion (n.), exhaustive (adj.)', NULL, 'exhausted chỉ người bị mệt lử; exhausting chỉ sự vật gây mệt mỏi.', 'Carrying those heavy boxes upstairs completely exhausted me.', NULL, 'Việc khuân những chiếc thùng nặng đó lên lầu làm tôi mệt lử luôn.', '{"wordId":"exhaust","ukIpa":"/ɪɡˈzɔːst/","usIpa":"/ɪɡˈzɔːst/","cefr":"B2","topic":"health","senses":[{"pos":"v.","en":"To make someone extremely tired.","vi":"làm kiệt sức; làm mệt lử"},{"pos":"v.","en":"To use all of something, leaving none remaining.","vi":"dùng cạn; cạn kiệt; tiêu thụ hết"},{"pos":"n.","en":"Waste gases from an engine, or the pipe releasing them.","vi":"khí thải; ống xả"}],"examples":[{"en":"Carrying those heavy boxes upstairs completely exhausted me.","vi":"Việc khuân những chiếc thùng nặng đó lên lầu làm tôi mệt lử luôn.","audioKind":"ex"},{"en":"Intensive farming can exhaust soil nutrients, reducing agricultural productivity and increasing dependence on artificial fertilisers.","vi":"Nông nghiệp thâm canh có thể làm cạn kiệt chất dinh dưỡng trong đất, làm giảm năng suất nông nghiệp và gia tăng sự phụ thuộc vào phân bón hóa học.","audioKind":"ex2"}],"collocations":[{"en":"exhaust natural resources","vi":"làm cạn kiệt tài nguyên thiên nhiên"},{"en":"exhaust all possibilities","vi":"thử mọi khả năng"},{"en":"exhaust fumes","vi":"khí thải động cơ"},{"en":"an exhaust pipe","vi":"ống xả"}],"wordFamily":["exhausted (adj.)","exhausting (adj.)","exhaustion (n.)","exhaustive (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"exhausted chỉ người bị mệt lử; exhausting chỉ sự vật gây mệt mỏi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_organ', 'en-b2-26', 'organ', '/ˈɔːrɡən/', 'B2', 'cơ quan (trong cơ thể sinh vật); đàn ống; đàn phong cầm', 'n.', NULL, NULL, 'organ là cơ quan nội tạng; organism là cơ thể sống hoàn chỉnh.', 'The heart is an organ that pumps blood.', NULL, 'Tim là một cơ quan có chức năng bơm máu.', '{"wordId":"organ","ukIpa":"/ˈɔːɡən/","usIpa":"/ˈɔːrɡən/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"A body part that performs a particular function.","vi":"cơ quan (trong cơ thể sinh vật)"},{"pos":"n.","en":"A keyboard instrument producing sound through pipes or electronic equipment.","vi":"đàn ống; đàn phong cầm"}],"examples":[{"en":"The heart is an organ that pumps blood.","vi":"Tim là một cơ quan có chức năng bơm máu.","audioKind":"ex"},{"en":"Public awareness campaigns can encourage organ donation and help reduce waiting times for patients needing transplants.","vi":"Các chiến dịch nâng cao nhận thức cộng đồng có thể khuyến khích việc hiến tạng và giúp rút ngắn thời gian chờ đợi cho những bệnh nhân cần cấy ghép.","audioKind":"ex2"}],"collocations":[{"en":"internal organs","vi":"các nội tạng"},{"en":"organ donation","vi":"hiến tặng nội tạng"},{"en":"organ transplant","vi":"ghép tạng"},{"en":"play the organ","vi":"chơi đàn phong cầm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"organ là cơ quan nội tạng; organism là cơ thể sống hoàn chỉnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_counsellor', 'en-b2-26', 'counsellor', '/ˈkaʊnsələr/', 'B2', 'chuyên gia tư vấn tâm lý; người hướng dẫn; cố vấn (người đưa ra lời khuyên chuyên môn về một lĩnh vực cụ thể)', 'n.', 'counsel (v.), counselling (n.)', 'Đồng nghĩa: adviser', 'Tiếng Anh-Anh viết là counsellor, tiếng Anh-Mỹ là counselor; tránh nhầm lẫn với councillor nghĩa là ủy viên hội đồng.', 'The school counsellor helped me talk about my worries.', NULL, 'Chuyên gia tư vấn tâm lý của trường đã giúp tôi thổ lộ những nỗi lo lắng của mình.', '{"wordId":"counsellor","ukIpa":"/ˈkaʊnsələ/","usIpa":"/ˈkaʊnsələr/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"Someone trained to help people discuss and manage personal problems.","vi":"chuyên gia tư vấn tâm lý; người hướng dẫn"},{"pos":"n.","en":"Someone who gives professional advice on a particular subject.","vi":"cố vấn (người đưa ra lời khuyên chuyên môn về một lĩnh vực cụ thể)"}],"examples":[{"en":"The school counsellor helped me talk about my worries.","vi":"Chuyên gia tư vấn tâm lý của trường đã giúp tôi thổ lộ những nỗi lo lắng của mình.","audioKind":"ex"},{"en":"Access to a trained counsellor can help university students manage stress and adjust to independent living.","vi":"Việc tiếp cận với một chuyên gia tư vấn được đào tạo bài bản có thể giúp sinh viên đại học quản lý căng thẳng và thích nghi với cuộc sống tự lập.","audioKind":"ex2"}],"collocations":[{"en":"a school counsellor","vi":"chuyên gia tư vấn học đường"},{"en":"a marriage counsellor","vi":"chuyên gia tư vấn hôn nhân"},{"en":"a careers counsellor","vi":"cố vấn hướng nghiệp"}],"wordFamily":["counsel (v.)","counselling (n.)"],"synonyms":["adviser"],"antonyms":[],"tipVi":"Tiếng Anh-Anh viết là counsellor, tiếng Anh-Mỹ là counselor; tránh nhầm lẫn với councillor nghĩa là ủy viên hội đồng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_remedy', 'en-b2-26', 'remedy', '/ˈremədi/', 'B2', 'phương thuốc; cách chữa bệnh; biện pháp khắc phục; giải pháp giải quyết vấn đề; cải thiện; khắc phục; sửa chữa', 'n.', 'remedial (adj.)', NULL, 'Danh từ thường đi với giới từ for; động từ tác động trực tiếp lên vấn đề, không thêm for.', 'Warm lemon water is her favourite remedy for colds.', NULL, 'Nước chanh ấm là bài thuốc chữa cảm lạnh yêu thích của cô ấy.', '{"wordId":"remedy","ukIpa":"/ˈremədi/","usIpa":"/ˈremədi/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"A treatment or medicine used to relieve an illness.","vi":"phương thuốc; cách chữa bệnh"},{"pos":"n.","en":"A way of correcting a problem or improving a situation.","vi":"biện pháp khắc phục; giải pháp giải quyết vấn đề"},{"pos":"v.","en":"To correct a problem or improve an unsatisfactory situation.","vi":"cải thiện; khắc phục; sửa chữa"}],"examples":[{"en":"Warm lemon water is her favourite remedy for colds.","vi":"Nước chanh ấm là bài thuốc chữa cảm lạnh yêu thích của cô ấy.","audioKind":"ex"},{"en":"Improving access to affordable training could help remedy the shortage of skilled workers in rural areas.","vi":"Việc cải thiện khả năng tiếp cận các chương trình đào tạo vừa túi tiền có thể giúp giải quyết tình trạng thiếu hụt lao động tay nghề cao ở các vùng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"home remedy","vi":"phương pháp chữa bệnh tại nhà"},{"en":"a remedy for","vi":"biện pháp giải quyết cho..."},{"en":"remedy a problem","vi":"khắc phục vấn đề"},{"en":"remedy the situation","vi":"cải thiện tình hình"}],"wordFamily":["remedial (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ thường đi với giới từ for; động từ tác động trực tiếp lên vấn đề, không thêm for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_overdose', 'en-b2-26', 'overdose', '/ˈoʊvərdoʊs/', 'B2', 'lượng thuốc dùng quá liều an toàn; dùng quá liều thuốc', 'n.', 'dose (n.)', NULL, 'Động từ dùng overdose on sth; danh từ dùng an overdose of sth.', 'The pharmacist explained how to avoid an accidental overdose.', NULL, 'Dược sĩ đã giải thích cách tránh dùng quá liều do vô ý.', '{"wordId":"overdose","ukIpa":"/ˈəʊvədəʊs/","usIpa":"/ˈoʊvərdoʊs/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"an amount of a drug taken that exceeds safe limits","vi":"lượng thuốc dùng quá liều an toàn"},{"pos":"v.","en":"to take a dangerously large amount of a drug","vi":"dùng quá liều thuốc"}],"examples":[{"en":"The pharmacist explained how to avoid an accidental overdose.","vi":"Dược sĩ đã giải thích cách tránh dùng quá liều do vô ý.","audioKind":"ex"},{"en":"Clear packaging and professional advice can reduce the risk of accidental overdose among patients taking several medicines.","vi":"Bao bì rõ ràng và lời khuyên chuyên nghiệp có thể làm giảm nguy cơ uống quá liều do nhầm lẫn ở những bệnh nhân đang dùng nhiều loại thuốc.","audioKind":"ex2"}],"collocations":[{"en":"an accidental overdose","vi":"uống quá liều do tai nạn"},{"en":"a drug overdose","vi":"quá liều thuốc"},{"en":"overdose on medication","vi":"quá liều thuốc điều trị"}],"wordFamily":["dose (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ dùng overdose on sth; danh từ dùng an overdose of sth.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_precaution', 'en-b2-26', 'precaution', '/prɪˈkɔːʃən/', 'B2', 'biện pháp phòng ngừa; biện pháp đề phòng', 'n.', 'precautionary (adj.)', 'Đồng nghĩa: safeguard', 'Thường dùng take precautions; as a precaution mang nghĩa phòng hờ.', 'We packed an extra torch as a precaution.', NULL, 'Chúng tôi đã đóng gói thêm một chiếc đèn pin như một biện pháp đề phòng.', '{"wordId":"precaution","ukIpa":"/prɪˈkɔːʃən/","usIpa":"/prɪˈkɔːʃən/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"an action taken to prevent danger, damage, or problems","vi":"biện pháp phòng ngừa; biện pháp đề phòng"}],"examples":[{"en":"We packed an extra torch as a precaution.","vi":"Chúng tôi đã đóng gói thêm một chiếc đèn pin như một biện pháp đề phòng.","audioKind":"ex"},{"en":"Taking basic safety precautions in laboratories can prevent accidents and protect both students and teaching staff.","vi":"Việc thực hiện các biện pháp an toàn cơ bản trong phòng thí nghiệm có thể ngăn ngừa tai nạn và bảo vệ cả học sinh lẫn giáo viên.","audioKind":"ex2"}],"collocations":[{"en":"take precautions","vi":"tiến hành các biện pháp phòng ngừa"},{"en":"as a precaution","vi":"như một biện pháp đề phòng"},{"en":"safety precautions","vi":"các biện pháp an toàn"},{"en":"a precaution against fire","vi":"biện pháp phòng chống cháy nổ"}],"wordFamily":["precautionary (adj.)"],"synonyms":["safeguard"],"antonyms":[],"tipVi":"Thường dùng take precautions; as a precaution mang nghĩa phòng hờ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_swollen', 'en-b2-26', 'swollen', '/ˈswoʊlən/', 'B2', 'sưng tấy, sưng phồng (do chấn thương hoặc bệnh tật); dâng cao, tràn nước (sau trận mưa lớn)', 'adj.', 'swell (v.), swelling (n.)', NULL, 'Cũng là phân từ quá khứ của swell; dạng quá khứ đơn là swelled.', 'My ankle was swollen after I fell during practice.', NULL, 'Mắt cá chân của tôi bị sưng lên sau khi tôi ngã lúc tập luyện.', '{"wordId":"swollen","ukIpa":"/ˈswəʊlən/","usIpa":"/ˈswoʊlən/","cefr":"B2","topic":"health","senses":[{"pos":"adj.","en":"larger than normal because of injury or illness","vi":"sưng tấy, sưng phồng (do chấn thương hoặc bệnh tật)"},{"pos":"adj.","en":"carrying more water than usual after heavy rain","vi":"dâng cao, tràn nước (sau trận mưa lớn)"}],"examples":[{"en":"My ankle was swollen after I fell during practice.","vi":"Mắt cá chân của tôi bị sưng lên sau khi tôi ngã lúc tập luyện.","audioKind":"ex"},{"en":"After several days of heavy rain, the swollen river threatened homes built close to its banks.","vi":"Sau nhiều ngày mưa lớn, dòng sông dâng nước đã đe dọa các ngôi nhà nằm gần bờ.","audioKind":"ex2"}],"collocations":[{"en":"a swollen ankle","vi":"mắt cá chân sưng tấy"},{"en":"swollen glands","vi":"tuyến hạch sưng lớn"},{"en":"a swollen river","vi":"dòng sông dâng nước"}],"wordFamily":["swell (v.)","swelling (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cũng là phân từ quá khứ của swell; dạng quá khứ đơn là swelled.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_strain', 'en-b2-26', 'strain', '/streɪn/', 'B2', 'áp lực, gánh nặng; làm căng, làm quá sức, kéo căng; chủng, loài phụ, dòng (sinh học)', 'n.', 'strained (adj.)', 'Đồng nghĩa: pressure, burden', 'strain có thể chỉ việc căng/lấn cơ bắp; sprain chủ yếu chỉ bong gân khớp.', 'I strained my back while lifting that heavy box.', NULL, 'Tôi đã bị căng cơ lưng khi nhấc chiếc hộp nặng đó lên.', '{"wordId":"strain","ukIpa":"/streɪn/","usIpa":"/streɪn/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"pressure or difficulty that tests someone''s strength or resources","vi":"áp lực, gánh nặng"},{"pos":"v.","en":"to injure or overwork a muscle or body part","vi":"làm căng, làm quá sức, kéo căng"},{"pos":"n.","en":"a particular type of plant, animal, or microorganism","vi":"chủng, loài phụ, dòng (sinh học)"}],"examples":[{"en":"I strained my back while lifting that heavy box.","vi":"Tôi đã bị căng cơ lưng khi nhấc chiếc hộp nặng đó lên.","audioKind":"ex"},{"en":"Rapid population growth puts considerable strain on public services, particularly housing and healthcare in large cities.","vi":"Sự bùng nổ dân số nhanh chóng tạo ra áp lực đáng kể lên các dịch vụ công cộng, đặc biệt là nhà ở và y tế tại các thành phố lớn.","audioKind":"ex2"}],"collocations":[{"en":"put a strain on","vi":"gây áp lực lên"},{"en":"under strain","vi":"chịu áp lực"},{"en":"strain a muscle","vi":"làm căng cơ"},{"en":"a strain of virus","vi":"một chủng virus"}],"wordFamily":["strained (adj.)"],"synonyms":["pressure","burden"],"antonyms":[],"tipVi":"strain có thể chỉ việc căng/lấn cơ bắp; sprain chủ yếu chỉ bong gân khớp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_calcium', 'en-b2-26', 'calcium', '/ˈkælsiəm/', 'B2', 'canxi', 'n.', NULL, NULL, 'Danh từ không đếm được; ký hiệu hóa học là Ca.', 'This yoghurt provides calcium for healthy bones and teeth.', NULL, 'Món sữa chua này cung cấp canxi giúp xương và răng chắc khỏe.', '{"wordId":"calcium","ukIpa":"/ˈkælsiəm/","usIpa":"/ˈkælsiəm/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"A chemical element needed for strong bones and teeth","vi":"canxi"}],"examples":[{"en":"This yoghurt provides calcium for healthy bones and teeth.","vi":"Món sữa chua này cung cấp canxi giúp xương và răng chắc khỏe.","audioKind":"ex"},{"en":"School meals should include adequate sources of calcium to support children''s bone development during periods of rapid growth.","vi":"Khẩu phần ăn học đường nên bao gồm các nguồn cung cấp canxi đầy đủ để hỗ trợ sự phát triển xương của trẻ trong giai đoạn tăng trưởng nhanh.","audioKind":"ex2"}],"collocations":[{"en":"calcium intake","vi":"lượng canxi nạp vào"},{"en":"calcium deficiency","vi":"sự thiếu hụt canxi"},{"en":"calcium supplements","vi":"thực phẩm bổ sung canxi"},{"en":"a source of calcium","vi":"nguồn cung cấp canxi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ không đếm được; ký hiệu hóa học là Ca.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_adolescent', 'en-b2-26', 'adolescent', '/ˌædəˈlesənt/', 'B2', 'thanh thiếu niên; thuộc về tuổi dậy thì; thuộc về lứa tuổi thanh thiếu niên', 'n.', 'adolescence (n.)', 'Đồng nghĩa: teenager', 'Vừa có thể làm danh từ vừa làm tính từ; mang tính trang trọng hơn từ teenager.', 'The club offers cooking classes for adolescents after school.', NULL, 'Câu lạc bộ cung cấp các lớp học nấu ăn sau giờ học dành cho thanh thiếu niên.', '{"wordId":"adolescent","ukIpa":"/ˌædəˈlesənt/","usIpa":"/ˌædəˈlesənt/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"a young person developing from a child into an adult","vi":"thanh thiếu niên"},{"pos":"adj.","en":"relating to the stage between childhood and adulthood","vi":"thuộc về tuổi dậy thì; thuộc về lứa tuổi thanh thiếu niên"}],"examples":[{"en":"The club offers cooking classes for adolescents after school.","vi":"Câu lạc bộ cung cấp các lớp học nấu ăn sau giờ học dành cho thanh thiếu niên.","audioKind":"ex"},{"en":"Regular physical activity can improve adolescent mental health and support the development of lasting social connections.","vi":"Hoạt động thể chất đều đặn có thể cải thiện sức khỏe tinh thần của thanh thiếu niên và hỗ trợ quá trình hình thành các mối quan hệ xã hội bền vững.","audioKind":"ex2"}],"collocations":[{"en":"adolescent development","vi":"sự phát triển của thanh thiếu niên"},{"en":"adolescent behaviour","vi":"hành vi của thanh thiếu niên"},{"en":"adolescent mental health","vi":"sức khỏe tinh thần của thanh thiếu niên"}],"wordFamily":["adolescence (n.)"],"synonyms":["teenager"],"antonyms":[],"tipVi":"Vừa có thể làm danh từ vừa làm tính từ; mang tính trang trọng hơn từ teenager.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_beneficial', 'en-b2-26', 'beneficial', '/ˌbenɪˈfɪʃəl/', 'B2', 'có ích; có lợi', 'adj.', 'benefit (n.), benefit (v.), beneficially (adv.)', 'Đồng nghĩa: helpful, advantageous · Trái nghĩa: harmful, detrimental', 'Thường đi kèm với giới từ to hoặc for để chỉ đối tượng hoặc lĩnh vực nhận được lợi ích.', 'A short walk after lunch is beneficial for digestion.', NULL, 'Đi bộ nhẹ nhàng sau bữa trưa rất có ích cho việc tiêu hóa.', '{"wordId":"beneficial","ukIpa":"/ˌbenɪˈfɪʃəl/","usIpa":"/ˌbenɪˈfɪʃəl/","cefr":"B2","topic":"health","senses":[{"pos":"adj.","en":"Having a helpful or positive effect.","vi":"có ích; có lợi"}],"examples":[{"en":"A short walk after lunch is beneficial for digestion.","vi":"Đi bộ nhẹ nhàng sau bữa trưa rất có ích cho việc tiêu hóa.","audioKind":"ex"},{"en":"Access to green spaces is particularly beneficial to urban residents who have limited opportunities for outdoor exercise.","vi":"Việc tiếp cận các không gian xanh đặc biệt có lợi cho cư dân đô thị, những người có ít cơ hội tập thể dục ngoài trời.","audioKind":"ex2"}],"collocations":[{"en":"beneficial effect","vi":"tác động có lợi"},{"en":"beneficial to health","vi":"có lợi cho sức khỏe"},{"en":"mutually beneficial","vi":"cùng có lợi"}],"wordFamily":["benefit (n.)","benefit (v.)","beneficially (adv.)"],"synonyms":["helpful","advantageous"],"antonyms":["harmful","detrimental"],"tipVi":"Thường đi kèm với giới từ to hoặc for để chỉ đối tượng hoặc lĩnh vực nhận được lợi ích.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_26_1', 'en-b2-26', 'Cách dùng “counsellor” (n.) — chuyên gia tư vấn tâm lý; người hướng dẫn', 'a school counsellor  ·  a marriage counsellor  ·  a careers counsellor', 'Tiếng Anh-Anh viết là counsellor, tiếng Anh-Mỹ là counselor; tránh nhầm lẫn với councillor nghĩa là ủy viên hội đồng.', 'Họ từ (Word Family): counsel (v.), counselling (n.) | Đồng nghĩa: adviser', '[{"hanzi":"The school counsellor helped me talk about my worries.","pinyin":"","meaning":"Chuyên gia tư vấn tâm lý của trường đã giúp tôi thổ lộ những nỗi lo lắng của mình."},{"hanzi":"Access to a trained counsellor can help university students manage stress and adjust to independent living.","pinyin":"","meaning":"Việc tiếp cận với một chuyên gia tư vấn được đào tạo bài bản có thể giúp sinh viên đại học quản lý căng thẳng và thích nghi với cuộc sống tự lập."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_26_2', 'en-b2-26', 'Cách dùng “suffering” (n.) — nỗi đau đớn; sự khổ sở', 'alleviate suffering  ·  human suffering  ·  unnecessary suffering', 'Khi dùng chỉ sự đau đớn chung thường không đếm được; sufferings dùng để chỉ nhiều loại khổ nạn khác nhau.', 'Họ từ (Word Family): suffer (v.), sufferer (n.) | Đồng nghĩa: distress, pain, anguish', '[{"hanzi":"The medicine eased her suffering and helped her sleep.","pinyin":"","meaning":"Liều thuốc đã làm dịu bớt nỗi đau của cô ấy và giúp cô dễ ngủ hơn."},{"hanzi":"Improving access to clean water can reduce human suffering in communities affected by prolonged drought.","pinyin":"","meaning":"Việc cải thiện khả năng tiếp cận nước sạch có thể làm giảm bớt nỗi thống khổ của con người tại các cộng đồng chịu ảnh hưởng bởi hạn hán kéo dài."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_26_3', 'en-b2-26', 'Cách dùng “cure” (v.) — chữa khỏi; điều trị dứt điểm', 'cure a disease  ·  a cure for  ·  cure someone of', 'cure nhấn mạnh việc chữa khỏi hẳn; treat chỉ mang ý nghĩa điều trị chứ không cam kết khỏi bệnh hoàn toàn.', 'Họ từ (Word Family): curable (adj.), incurable (adj.) | Đồng nghĩa: heal', '[{"hanzi":"The doctor said these tablets could cure the infection.","pinyin":"","meaning":"Bác sĩ nói những viên thuốc này có thể chữa khỏi căn bệnh nhiễm trùng."},{"hanzi":"Although medical research has advanced considerably, scientists have not yet found a cure for every disease.","pinyin":"","meaning":"Mặc dù nghiên cứu y học đã đạt được những tiến bộ đáng kể, các nhà khoa học vẫn chưa tìm ra phương pháp chữa khỏi mọi loại bệnh."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_26_4', 'en-b2-26', 'Cách dùng “energetic” (adj.) — tràn đầy năng lượng; năng nổ; hoạt bát', 'feel energetic  ·  energetic children  ·  energetic approach', 'energetic là tính từ miêu tả con người hoặc hoạt động có nhiều năng lượng; energy là danh từ.', 'Họ từ (Word Family): energy (n.), energetically (adv.), energise (v.) | Đồng nghĩa: lively, vigorous · Trái nghĩa: lethargic, listless', '[{"hanzi":"Our energetic puppy chased a ball around the garden.","pinyin":"","meaning":"Chú chó con đầy năng lượng của chúng tôi đuổi theo quả bóng quanh khu vườn."},{"hanzi":"Regular physical activity can help office workers feel more energetic and maintain concentration throughout the day.","pinyin":"","meaning":"Hoạt động thể chất đều đặn có thể giúp nhân viên văn phòng cảm thấy tràn đầy năng lượng hơn và duy trì sự tập trung trong suốt cả ngày."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_26_1', 'en-b2-26', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_26_1_1', 'ten_b2_26_1', 'irritation', 'He sighed with irritation when the phone rang again.', 'He sighed with irritation when the phone rang again.', '/ˌɪrɪˈteɪʃən/', 'Anh ấy thở dài đầy bực bội khi điện thoại lại reo lên lần nữa.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_26_1_2', 'ten_b2_26_1', 'calory', 'I do not count every calory in my lunch.', 'I do not count every calory in my lunch.', '/ˈkæləri/', 'Tôi không tính từng calo trong bữa trưa của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_26_1_3', 'ten_b2_26_1', 'alcoholism', 'The clinic offers confidential support for people with alcoholism.', 'The clinic offers confidential support for people with alcoholism.', '/ˈælkəhɔːlɪzəm/', 'Phòng khám cung cấp dịch vụ hỗ trợ bảo mật cho những người gặp vấn đề về nghiện rượu.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_26_1_4', 'ten_b2_26_1', 'capsule', 'The pharmacist told me to swallow the capsule with water.', 'The pharmacist told me to swallow the capsule with water.', '/ˈkæpsəl/', 'Dược sĩ dặn tôi uống viên nang này với nước.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_26_1_5', 'ten_b2_26_1', 'jaw', 'My jaw felt sore after chewing the hard bread.', 'My jaw felt sore after chewing the hard bread.', '/dʒɔː/', 'Hàm của tôi thấy ê ẩm sau khi nhai miếng bánh mì cứng ngắc đó.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_26_1_6', 'ten_b2_26_1', 'vegan', 'As a vegan, I cook with beans instead of meat.', 'As a vegan, I cook with beans instead of meat.', '/ˈviːɡən/', 'Là một người ăn chay thuần, tôi nấu ăn bằng đậu thay vì thịt.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_26_1_7', 'ten_b2_26_1', 'energetic', 'Our energetic puppy chased a ball around the garden.', 'Our energetic puppy chased a ball around the garden.', '/ˌenərˈdʒetɪk/', 'Chú chó con đầy năng lượng của chúng tôi đuổi theo quả bóng quanh khu vườn.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_26_1_8', 'ten_b2_26_1', 'wound', 'The nurse gently cleaned the wound on my knee.', 'The nurse gently cleaned the wound on my knee.', '/wuːnd/', 'Cô y tá nhẹ nhàng rửa sạch vết thương trên đầu gối của tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_26_1_1', 'en-b2-26', 'ten_b2_26_1', 'listening', 'listening', 'He sighed with irritation when the phone rang again.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chú chó con đầy năng lượng của chúng tôi đuổi theo quả bóng quanh khu vườn.","Dược sĩ đã giải thích cách tránh dùng quá liều do vô ý.","Hàm của tôi thấy ê ẩm sau khi nhai miếng bánh mì cứng ngắc đó.","Anh ấy thở dài đầy bực bội khi điện thoại lại reo lên lần nữa."]'::jsonb, 3, 'He sighed with irritation when the phone rang again. → Anh ấy thở dài đầy bực bội khi điện thoại lại reo lên lần nữa.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_26_1_2', 'en-b2-26', 'ten_b2_26_1', 'listening', 'listening', 'I do not count every calory in my lunch.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi không tính từng calo trong bữa trưa của mình.","Là một người ăn chay thuần, tôi nấu ăn bằng đậu thay vì thịt.","Chuyên gia tư vấn tâm lý của trường đã giúp tôi thổ lộ những nỗi lo lắng của mình.","Phòng khám cung cấp dịch vụ hỗ trợ bảo mật cho những người gặp vấn đề về nghiện rượu."]'::jsonb, 0, 'I do not count every calory in my lunch. → Tôi không tính từng calo trong bữa trưa của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_26_1_3', 'en-b2-26', 'ten_b2_26_1', 'listening', 'listening', 'The clinic offers confidential support for people with alcoholism.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Phòng khám cung cấp dịch vụ hỗ trợ bảo mật cho những người gặp vấn đề về nghiện rượu.","Liều thuốc đã làm dịu bớt nỗi đau của cô ấy và giúp cô dễ ngủ hơn.","Hàm của tôi thấy ê ẩm sau khi nhai miếng bánh mì cứng ngắc đó.","Câu lạc bộ cung cấp các lớp học nấu ăn sau giờ học dành cho thanh thiếu niên."]'::jsonb, 0, 'The clinic offers confidential support for people with alcoholism. → Phòng khám cung cấp dịch vụ hỗ trợ bảo mật cho những người gặp vấn đề về nghiện rượu.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_26_2', 'en-b2-26', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_26_2_1', 'ten_b2_26_2', 'irritation', 'Exposure to household cleaning products may cause skin irritation, especially among people with sensitive skin.', 'Exposure to household cleaning products may cause skin irritation, especially among people with sensitive skin.', '/ˌɪrɪˈteɪʃən/', 'Tiếp xúc với các sản phẩm vệ sinh gia dụng có thể gây kích ứng da, đặc biệt đối với những người có làn da nhạy cảm.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_26_2_2', 'ten_b2_26_2', 'calory', 'Although calory intake matters, public health advice should also consider nutritional quality and access to fresh food.', 'Although calory intake matters, public health advice should also consider nutritional quality and access to fresh food.', '/ˈkæləri/', 'Mặc dù lượng calo nạp vào rất quan trọng, nhưng các khuyến nghị về sức khỏe cộng đồng cũng cần xem xét chất lượng dinh dưỡng và khả năng tiếp cận thực phẩm tươi sống.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_26_2_3', 'ten_b2_26_2', 'alcoholism', 'Effective treatment for alcoholism often combines medical care, psychological support, and help from family members.', 'Effective treatment for alcoholism often combines medical care, psychological support, and help from family members.', '/ˈælkəhɔːlɪzəm/', 'Phương pháp điều trị chứng nghiện rượu hiệu quả thường kết hợp chăm sóc y tế, hỗ trợ tâm lý và sự giúp đỡ từ các thành viên trong gia đình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_26_2_4', 'ten_b2_26_2', 'capsule', 'The space capsule was designed to protect its crew from extreme temperatures during their return to Earth.', 'The space capsule was designed to protect its crew from extreme temperatures during their return to Earth.', '/ˈkæpsəl/', 'Khoang tàu vũ trụ được thiết kế để bảo vệ phi hành đoàn khỏi nhiệt độ khắc nghiệt trong quá trình trở về Trái Đất.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_26_2_5', 'ten_b2_26_2', 'jaw', 'Protective equipment can reduce the risk of jaw injuries among people who participate in contact sports.', 'Protective equipment can reduce the risk of jaw injuries among people who participate in contact sports.', '/dʒɔː/', 'Thiết bị bảo hộ có thể làm giảm nguy cơ chấn thương vùng hàm cho những người tham gia các môn thể thao va chạm.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_26_2_6', 'ten_b2_26_2', 'vegan', 'A carefully planned vegan diet can meet nutritional needs while reducing some environmental impacts of food production.', 'A carefully planned vegan diet can meet nutritional needs while reducing some environmental impacts of food production.', '/ˈviːɡən/', 'Một chế độ ăn thuần chay được lên kế hoạch kỹ lưỡng có thể đáp ứng nhu cầu dinh dưỡng đồng thời giảm thiểu một số tác động môi trường từ việc sản xuất thực phẩm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_26_2_1', 'en-b2-26', 'ten_b2_26_2', 'listening', 'listening', 'Exposure to household cleaning products may cause skin irritation, especially among people with sensitive skin.', NULL, 'Trong câu vừa nghe, từ “irritation” mang nghĩa nào sau đây?', '["sự bực bội; nỗi khó chịu","chồng (đồ vật xếp chồng lên nhau)","vitamin","động lực; sự khuyến khích; tiền thưởng khích lệ"]'::jsonb, 0, '“irritation” (/ˌɪrɪˈteɪʃən/): sự bực bội; nỗi khó chịu. Câu đầy đủ: Exposure to household cleaning products may cause skin irritation, especially among people with sensitive skin.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_26_2_2', 'en-b2-26', 'ten_b2_26_2', 'listening', 'listening', 'Although calory intake matters, public health advice should also consider nutritional quality and access to fresh food.', NULL, 'Trong câu vừa nghe, từ “calory” mang nghĩa nào sau đây?', '["calo (đơn vị đo nhiệt lượng hoặc năng lượng từ thức ăn)","ra hoa; nở hoa","bộ xương; khung xương","thỉnh thoảng; đôi khi; không thường xuyên"]'::jsonb, 0, '“calory” (/ˈkæləri/): calo (đơn vị đo nhiệt lượng hoặc năng lượng từ thức ăn). Câu đầy đủ: Although calory intake matters, public health advice should also consider nutritional quality and access to fresh food.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
