INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_26_1', 'en-b2-26', NULL, 'comprehensive_test', 'listening', 'irritation', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự bực bội; nỗi khó chịu","thay đổi; biến đổi","khác biệt; tách biệt","tính đơn giản; sự dễ hiểu"]'::jsonb, 0, 'irritation (/ˌɪrɪˈteɪʃən/) → sự bực bội; nỗi khó chịu; sự kích ứng; sự mẩn ngứa', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_26_2', 'en-b2-26', NULL, 'comprehensive_test', 'listening', 'I do not count every calory in my lunch.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Câu lạc bộ cung cấp các lớp học nấu ăn sau giờ học dành cho thanh thiếu niên.","Tôi không tính từng calo trong bữa trưa của mình.","Việc khuân những chiếc thùng nặng đó lên lầu làm tôi mệt lử luôn.","Đi bộ nhẹ nhàng sau bữa trưa rất có ích cho việc tiêu hóa."]'::jsonb, 1, 'I do not count every calory in my lunch. → Tôi không tính từng calo trong bữa trưa của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_26_3', 'en-b2-26', NULL, 'comprehensive_test', 'listening', 'alcoholism', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chứng nghiện rượu; tình trạng lệ thuộc vào rượu","chín; làm cho chín","sự yên tĩnh; sự thanh bình","chăm sóc da; việc dưỡng da"]'::jsonb, 0, 'alcoholism (/ˈælkəhɔːlɪzəm/) → chứng nghiện rượu; tình trạng lệ thuộc vào rượu', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_26_4', 'en-b2-26', NULL, 'comprehensive_test', 'listening', 'The pharmacist told me to swallow the capsule with water.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi không tính từng calo trong bữa trưa của mình.","Dược sĩ dặn tôi uống viên nang này với nước.","Dược sĩ đã giải thích cách tránh dùng quá liều do vô ý.","Câu lạc bộ cung cấp các lớp học nấu ăn sau giờ học dành cho thanh thiếu niên."]'::jsonb, 1, 'The pharmacist told me to swallow the capsule with water. → Dược sĩ dặn tôi uống viên nang này với nước.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_26_5', 'en-b2-26', NULL, 'comprehensive_test', 'listening', 'jaw', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nhà thiên văn học","cuối cùng; sau một chuỗi sự kiện","sự chấp nhận, sự nhận","hàm; xương hàm"]'::jsonb, 3, 'jaw (/dʒɔː/) → hàm; xương hàm', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_26_6', 'en-b2-26', NULL, 'comprehensive_test', 'listening', 'As a vegan, I cook with beans instead of meat.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Dược sĩ đã giải thích cách tránh dùng quá liều do vô ý.","Câu lạc bộ cung cấp các lớp học nấu ăn sau giờ học dành cho thanh thiếu niên.","Là một người ăn chay thuần, tôi nấu ăn bằng đậu thay vì thịt.","Chuyên gia tư vấn tâm lý của trường đã giúp tôi thổ lộ những nỗi lo lắng của mình."]'::jsonb, 2, 'As a vegan, I cook with beans instead of meat. → Là một người ăn chay thuần, tôi nấu ăn bằng đậu thay vì thịt.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_26_7', 'en-b2-26', NULL, 'comprehensive_test', 'listening', 'energetic', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["làm phiền; gây bực bội; chọc tức","vui mừng; hân hoan; mang lại niềm vui","thuộc về nông nghiệp","tràn đầy năng lượng; năng nổ; hoạt bát"]'::jsonb, 3, 'energetic (/ˌenərˈdʒetɪk/) → tràn đầy năng lượng; năng nổ; hoạt bát', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_26_8', 'en-b2-26', NULL, 'comprehensive_test', 'listening', 'The nurse gently cleaned the wound on my knee.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô y tá nhẹ nhàng rửa sạch vết thương trên đầu gối của tôi.","Món sữa chua này cung cấp canxi giúp xương và răng chắc khỏe.","Nước chanh ấm là bài thuốc chữa cảm lạnh yêu thích của cô ấy.","Phòng khám cung cấp dịch vụ hỗ trợ bảo mật cho những người gặp vấn đề về nghiện rượu."]'::jsonb, 0, 'The nurse gently cleaned the wound on my knee. → Cô y tá nhẹ nhàng rửa sạch vết thương trên đầu gối của tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
