INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_26_18', 'en-b2-26', NULL, 'comprehensive_test', 'reading', NULL, 'Exposure to household cleaning products may cause skin irritation, especially among people with sensitive skin.', 'Dựa vào câu trên, từ “irritation” có nghĩa phù hợp nhất là gì?', '["nạn đói; nạn thiếu lương thực trầm trọng","có động lực; có tinh thần chủ động","sự số ruột; sự bực bội do chờ đợi","sự bực bội; nỗi khó chịu"]'::jsonb, 3, 'irritation: sự bực bội; nỗi khó chịu; sự kích ứng; sự mẩn ngứa. Dịch cả câu: Tiếp xúc với các sản phẩm vệ sinh gia dụng có thể gây kích ứng da, đặc biệt đối với những người có làn da nhạy cảm.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_26_19', 'en-b2-26', NULL, 'comprehensive_test', 'reading', NULL, 'Although calory intake matters, public health advice should also consider nutritional quality and access to fresh food.', 'Dựa vào câu trên, từ “calory” có nghĩa phù hợp nhất là gì?', '["chèn vào; đút vào","hơn nữa; ngoài ra","calo (đơn vị đo nhiệt lượng hoặc năng lượng từ thức ăn)","trước đó; ở phần trước"]'::jsonb, 2, 'calory: calo (đơn vị đo nhiệt lượng hoặc năng lượng từ thức ăn). Dịch cả câu: Mặc dù lượng calo nạp vào rất quan trọng, nhưng các khuyến nghị về sức khỏe cộng đồng cũng cần xem xét chất lượng dinh dưỡng và khả năng tiếp cận thực phẩm tươi sống.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_26_20', 'en-b2-26', NULL, 'comprehensive_test', 'reading', NULL, 'Effective treatment for alcoholism often combines medical care, psychological support, and help from family members.', 'Dựa vào câu trên, từ “alcoholism” có nghĩa phù hợp nhất là gì?', '["nhà kính, nhà ươm cây","nhà phân phối; thương gia; người buôn bán","công ty; hãng","chứng nghiện rượu; tình trạng lệ thuộc vào rượu"]'::jsonb, 3, 'alcoholism: chứng nghiện rượu; tình trạng lệ thuộc vào rượu. Dịch cả câu: Phương pháp điều trị chứng nghiện rượu hiệu quả thường kết hợp chăm sóc y tế, hỗ trợ tâm lý và sự giúp đỡ từ các thành viên trong gia đình.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_26_21', 'en-b2-26', NULL, 'comprehensive_test', 'reading', NULL, 'The space capsule was designed to protect its crew from extreme temperatures during their return to Earth.', 'Dựa vào câu trên, từ “capsule” có nghĩa phù hợp nhất là gì?', '["đồng (kim loại màu nâu đỏ)","lo lắng; bận tâm","viên nang; viên con nhộng","kỳ quan; điều kỳ diệu"]'::jsonb, 2, 'capsule: viên nang; viên con nhộng; khoang tàu vũ trụ; khoang kín nhỏ. Dịch cả câu: Khoang tàu vũ trụ được thiết kế để bảo vệ phi hành đoàn khỏi nhiệt độ khắc nghiệt trong quá trình trở về Trái Đất.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_26_22', 'en-b2-26', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “canxi”', '["calcium","tremendous","paw","Oceania"]'::jsonb, 0, 'canxi → calcium (/ˈkælsiəm/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_26_23', 'en-b2-26', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thanh thiếu niên”', '["outcome","adolescent","urge","boundary"]'::jsonb, 1, 'thanh thiếu niên → adolescent (/ˌædəˈlesənt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_26_24', 'en-b2-26', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “có ích; có lợi”', '["beneficial","trail","restore","simplicity"]'::jsonb, 0, 'có ích; có lợi → beneficial (/ˌbenɪˈfɪʃəl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-27', 'en', 'Bài 27: Sức khỏe & Cơ thể (2) - CEFR B2', 'CEFR B2', 'B2 · Sức khỏe', '25 từ vựng Tiếng Anh CEFR B2 chủ đề sức khỏe & cơ thể kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4027, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_snore', 'en-b2-27', 'snore', '/snɔːr/', 'B2', 'ngáy; ngáy ngủ; tiếng ngáy', 'v.', 'snoring (n.), snorer (n.)', NULL, 'Dùng như động từ thường là không túc từ; snoring có thể chỉ hiện tượng ngáy.', 'My brother snores so loudly that the dog leaves.', NULL, 'Anh trai tôi ngáy to đến mức con chó phải bỏ đi nơi khác.', '{"wordId":"snore","ukIpa":"/snɔː/","usIpa":"/snɔːr/","cefr":"B2","topic":"health","senses":[{"pos":"v.","en":"to breathe noisily through your nose and throat while sleeping","vi":"ngáy; ngáy ngủ"},{"pos":"n.","en":"a noisy breath made by someone who is sleeping","vi":"tiếng ngáy"}],"examples":[{"en":"My brother snores so loudly that the dog leaves.","vi":"Anh trai tôi ngáy to đến mức con chó phải bỏ đi nơi khác.","audioKind":"ex"},{"en":"People who snore regularly may benefit from medical advice, particularly if their breathing stops briefly during sleep.","vi":"Những người thường xuyên ngáy có thể cần sự tư vấn y tế, đặc biệt là khi nhịp thở của họ bị ngắt quãng ngắn trong khi ngủ.","audioKind":"ex2"}],"collocations":[{"en":"snore loudly","vi":"ngáy to"},{"en":"start snoring","vi":"bắt đầu ngáy"},{"en":"a loud snore","vi":"tiếng ngáy lớn"}],"wordFamily":["snoring (n.)","snorer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng như động từ thường là không túc từ; snoring có thể chỉ hiện tượng ngáy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_digest', 'en-b2-27', 'digest', '/daɪˈdʒest/', 'B2', 'tiêu hóa; hiểu; lĩnh hội; ngấm; bản tóm tắt; tập san văn/tài liệu', 'v.', 'digestion (n.), digestive (adj.), digestible (adj.), indigestion (n.)', NULL, 'Danh từ trọng âm rơi vào âm tiết đầu, phát âm là /ˈdaɪdʒest/.', 'My stomach finds heavy meals difficult to digest.', NULL, 'Dạ dày của tôi rất khó tiêu hóa những bữa ăn nhiều đạm và nặng bụng.', '{"wordId":"digest","ukIpa":"/daɪˈdʒest/","usIpa":"/daɪˈdʒest/","cefr":"B2","topic":"health","senses":[{"pos":"v.","en":"Break down food inside the body so it can be used.","vi":"tiêu hóa"},{"pos":"v.","en":"Think about information until you understand it.","vi":"hiểu; lĩnh hội; ngấm"},{"pos":"n.","en":"A short collection of the main points from longer material.","vi":"bản tóm tắt; tập san văn/tài liệu"}],"examples":[{"en":"My stomach finds heavy meals difficult to digest.","vi":"Dạ dày của tôi rất khó tiêu hóa những bữa ăn nhiều đạm và nặng bụng.","audioKind":"ex"},{"en":"Students need sufficient time to digest complex information before applying it to unfamiliar problems.","vi":"Học sinh cần có đủ thời gian để lĩnh hội các thông tin phức tạp trước khi áp dụng chúng vào các vấn đề chưa quen thuộc.","audioKind":"ex2"}],"collocations":[{"en":"digest food","vi":"tiêu hóa thức ăn"},{"en":"digest information","vi":"hiểu thông tin"},{"en":"a monthly digest","vi":"bản tóm tắt hàng tháng"}],"wordFamily":["digestion (n.)","digestive (adj.)","digestible (adj.)","indigestion (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ trọng âm rơi vào âm tiết đầu, phát âm là /ˈdaɪdʒest/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_protein', 'en-b2-27', 'protein', '/ˈproʊtiːn/', 'B2', 'chất đạm; protein', 'n.', NULL, NULL, 'Từ protein thường không đếm được khi chỉ chất dinh dưỡng; có thể đếm được khi chỉ các loại protein khác nhau.', 'These beans add protein to our vegetable soup.', NULL, 'Những hạt đậu này bổ sung protein cho món súp rau củ của chúng ta.', '{"wordId":"protein","ukIpa":"/ˈprəʊtiːn/","usIpa":"/ˈproʊtiːn/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"A nutrient needed for growth and repair of body tissues.","vi":"chất đạm; protein"}],"examples":[{"en":"These beans add protein to our vegetable soup.","vi":"Những hạt đậu này bổ sung protein cho món súp rau củ của chúng ta.","audioKind":"ex"},{"en":"A balanced plant-based diet can provide sufficient protein when it includes varied sources such as beans and nuts.","vi":"Một chế độ ăn thuần thực vật cân bằng có thể cung cấp đủ lượng protein khi bao gồm các nguồn thực phẩm đa dạng như đậu và các loại hạt.","audioKind":"ex2"}],"collocations":[{"en":"high in protein","vi":"giàu protein"},{"en":"a source of protein","vi":"một nguồn protein"},{"en":"plant protein","vi":"protein thực vật"},{"en":"protein intake","vi":"lượng protein nạp vào"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Từ protein thường không đếm được khi chỉ chất dinh dưỡng; có thể đếm được khi chỉ các loại protein khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hearing', 'en-b2-27', 'hearing', '/ˈhɪrɪŋ/', 'B2', 'thính giác; khả năng nghe; phiên điều trần; buổi xét xử', 'n.', 'hear (v.), hearer (n.)', NULL, 'Không đếm được khi chỉ thính lực; đếm được khi chỉ phiên điều trần.', 'My grandfather''s hearing improved after he received a hearing aid.', NULL, 'Thính giác của ông tôi đã cải thiện sau khi ông đeo máy trợ thính.', '{"wordId":"hearing","ukIpa":"/ˈhɪərɪŋ/","usIpa":"/ˈhɪrɪŋ/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"The ability to notice sounds through your ears.","vi":"thính giác; khả năng nghe"},{"pos":"n.","en":"An official meeting to consider evidence or arguments.","vi":"phiên điều trần; buổi xét xử"}],"examples":[{"en":"My grandfather''s hearing improved after he received a hearing aid.","vi":"Thính giác của ông tôi đã cải thiện sau khi ông đeo máy trợ thính.","audioKind":"ex"},{"en":"A public hearing allows residents to express concerns before major construction projects receive official approval.","vi":"Một phiên điều trần công khai cho phép cư dân bày tỏ những mối lo ngại trước khi các dự án xây dựng lớn nhận được phê duyệt chính thức.","audioKind":"ex2"}],"collocations":[{"en":"hearing loss","vi":"sự suy giảm thính lực"},{"en":"a hearing aid","vi":"máy trợ thính"},{"en":"a public hearing","vi":"phiên điều trần công khai"},{"en":"a court hearing","vi":"phiên tòa xét xử"}],"wordFamily":["hear (v.)","hearer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Không đếm được khi chỉ thính lực; đếm được khi chỉ phiên điều trần.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prescribe', 'en-b2-27', 'prescribe', '/prɪˈskraɪb/', 'B2', 'kê đơn (thuốc); chỉ định điều trị; quy định; chỉ định; ra lệnh', 'v.', 'prescription (n.), prescriptive (adj.), prescriber (n.)', 'Đồng nghĩa: stipulate', 'prescribe là kê đơn thuốc; describe là miêu tả, cần chú ý phân biệt.', 'The doctor prescribed eye drops for my sore eyes.', NULL, 'Bác sĩ đã kê thuốc nhỏ mắt để chữa chứng đau mắt cho tôi.', '{"wordId":"prescribe","ukIpa":"/prɪˈskraɪb/","usIpa":"/prɪˈskraɪb/","cefr":"B2","topic":"health","senses":[{"pos":"v.","en":"officially recommend a medicine or treatment as a medical professional","vi":"kê đơn (thuốc); chỉ định điều trị"},{"pos":"v.","en":"state officially what must be done or how","vi":"quy định; chỉ định; ra lệnh"}],"examples":[{"en":"The doctor prescribed eye drops for my sore eyes.","vi":"Bác sĩ đã kê thuốc nhỏ mắt để chữa chứng đau mắt cho tôi.","audioKind":"ex"},{"en":"Doctors should prescribe antibiotics only when necessary to reduce the risk of bacteria developing resistance.","vi":"Các bác sĩ chỉ nên kê kháng sinh khi thực sự cần thiết để giảm nguy cơ vi khuẩn kháng thuốc.","audioKind":"ex2"}],"collocations":[{"en":"prescribe medication","vi":"kê đơn thuốc"},{"en":"prescribe treatment","vi":"chỉ định phương pháp điều trị"},{"en":"prescribe antibiotics","vi":"kê thuốc kháng sinh"},{"en":"prescribed by law","vi":"được pháp luật quy định"}],"wordFamily":["prescription (n.)","prescriptive (adj.)","prescriber (n.)"],"synonyms":["stipulate"],"antonyms":[],"tipVi":"prescribe là kê đơn thuốc; describe là miêu tả, cần chú ý phân biệt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_drowsy', 'en-b2-27', 'drowsy', '/ˈdraʊzi/', 'B2', 'buồn ngủ; lờ đờ', 'adj.', 'drowsiness (n.), drowsily (adv.)', 'Đồng nghĩa: sleepy · Trái nghĩa: alert', 'Thường dùng để mô tả con người buồn ngủ; khi nói thuốc gây buồn ngủ, có thể dùng make someone drowsy.', 'The warm room made me drowsy after lunch.', NULL, 'Căn phòng ấm áp làm tôi cảm thấy buồn ngủ sau bữa trưa.', '{"wordId":"drowsy","ukIpa":"/ˈdraʊzi/","usIpa":"/ˈdraʊzi/","cefr":"B2","topic":"health","senses":[{"pos":"adj.","en":"Feeling sleepy and finding it hard to stay awake","vi":"buồn ngủ; lờ đờ"}],"examples":[{"en":"The warm room made me drowsy after lunch.","vi":"Căn phòng ấm áp làm tôi cảm thấy buồn ngủ sau bữa trưa.","audioKind":"ex"},{"en":"Drivers who feel drowsy should stop somewhere safe, as fatigue significantly increases the risk of accidents.","vi":"Những tài xế cảm thấy buồn ngủ nên dừng xe ở một nơi an toàn, bởi vì sự mệt mỏi làm tăng đáng kể nguy cơ xảy ra tai nạn.","audioKind":"ex2"}],"collocations":[{"en":"feel drowsy","vi":"cảm thấy buồn ngủ"},{"en":"make someone drowsy","vi":"làm ai đó buồn ngủ"},{"en":"drowsy driving","vi":"tình trạng lái xe khi buồn ngủ"}],"wordFamily":["drowsiness (n.)","drowsily (adv.)"],"synonyms":["sleepy"],"antonyms":["alert"],"tipVi":"Thường dùng để mô tả con người buồn ngủ; khi nói thuốc gây buồn ngủ, có thể dùng make someone drowsy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sexual', 'en-b2-27', 'sexual', '/ˈsekʃuəl/', 'B2', 'liên quan đến tình dục; thuộc về giới tính; có sự sinh sản hữu tính', 'adj.', 'sex (n.), sexually (adv.), sexuality (n.)', NULL, 'sexual chỉ các vấn đề liên quan đến tính dục; trong khi sexy thường biểu thị sự gợi cảm.', 'The clinic offers confidential advice about sexual health.', NULL, 'Phòng khám cung cấp dịch vụ tư vấn bảo mật về sức khỏe tình dục.', '{"wordId":"sexual","ukIpa":"/ˈsekʃuəl/","usIpa":"/ˈsekʃuəl/","cefr":"B2","topic":"health","senses":[{"pos":"adj.","en":"Relating to sex or physical attraction between people.","vi":"liên quan đến tình dục; thuộc về giới tính"},{"pos":"adj.","en":"Involving reproduction through the joining of male and female cells.","vi":"có sự sinh sản hữu tính"}],"examples":[{"en":"The clinic offers confidential advice about sexual health.","vi":"Phòng khám cung cấp dịch vụ tư vấn bảo mật về sức khỏe tình dục.","audioKind":"ex"},{"en":"Schools can provide age-appropriate sexual health education to help young people make informed decisions.","vi":"Nhà trường có thể cung cấp giáo dục sức khỏe tình dục phù hợp theo độ tuổi để giúp giới trẻ đưa ra các quyết định sáng suốt.","audioKind":"ex2"}],"collocations":[{"en":"sexual health","vi":"sức khỏe tình dục"},{"en":"sexual reproduction","vi":"sinh sản hữu tính"},{"en":"sexual attraction","vi":"sự hấp dẫn giới tính"}],"wordFamily":["sex (n.)","sexually (adv.)","sexuality (n.)"],"synonyms":[],"antonyms":[],"tipVi":"sexual chỉ các vấn đề liên quan đến tính dục; trong khi sexy thường biểu thị sự gợi cảm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_meditate', 'en-b2-27', 'meditate', '/ˈmedɪteɪt/', 'B2', 'hồi tưởng; thiền định; suy ngẫm; trầm tư', 'v.', 'meditation (n.), meditative (adj.)', 'Đồng nghĩa: contemplate, reflect', 'Để diễn tả ý suy ngẫm sâu sắc về điều gì, thường dùng meditate on hoặc meditate upon.', 'I meditate for ten minutes before breakfast each morning.', NULL, 'Tôi thiền mười phút trước bữa sáng mỗi buổi sáng.', '{"wordId":"meditate","ukIpa":"/ˈmedɪteɪt/","usIpa":"/ˈmedɪteɪt/","cefr":"B2","topic":"health","senses":[{"pos":"v.","en":"to focus your mind calmly, often as a mental exercise","vi":"hồi tưởng; thiền định"},{"pos":"v.","en":"to think deeply and carefully about something","vi":"suy ngẫm; trầm tư"}],"examples":[{"en":"I meditate for ten minutes before breakfast each morning.","vi":"Tôi thiền mười phút trước bữa sáng mỗi buổi sáng.","audioKind":"ex"},{"en":"Some employers encourage staff to meditate during breaks as a way of managing workplace stress.","vi":"Một số nhà tuyển dụng khuyến khích nhân viên thiền trong giờ nghỉ như một cách để quản lý áp lực nơi công sở.","audioKind":"ex2"}],"collocations":[{"en":"meditate daily","vi":"thiền định mỗi ngày"},{"en":"meditate on something","vi":"suy ngẫm về điều gì"},{"en":"learn to meditate","vi":"học cách thiền"}],"wordFamily":["meditation (n.)","meditative (adj.)"],"synonyms":["contemplate","reflect"],"antonyms":[],"tipVi":"Để diễn tả ý suy ngẫm sâu sắc về điều gì, thường dùng meditate on hoặc meditate upon.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_abnormal', 'en-b2-27', 'abnormal', '/æbˈnɔːrml/', 'B2', 'bất thường; trái với thông thường', 'adj.', 'normal (adj.), normally (adv.), abnormally (adv.), abnormality (n.)', 'Đồng nghĩa: unusual, atypical · Trái nghĩa: normal, typical', 'Thường dùng trong y học hoặc các hiện tượng bất thường, không nên tùy tiện dùng để đánh giá con người.', 'The mechanic noticed an abnormal noise from the engine.', NULL, 'Thợ máy nhận thấy một tiếng động bất thường phát ra từ động cơ.', '{"wordId":"abnormal","ukIpa":"/æbˈnɔːml/","usIpa":"/æbˈnɔːrml/","cefr":"B2","topic":"health","senses":[{"pos":"adj.","en":"Different from what is usual or expected, often causing concern.","vi":"bất thường; trái với thông thường"}],"examples":[{"en":"The mechanic noticed an abnormal noise from the engine.","vi":"Thợ máy nhận thấy một tiếng động bất thường phát ra từ động cơ.","audioKind":"ex"},{"en":"Regular medical screening can detect abnormal changes before they develop into conditions that require complex treatment.","vi":"Sàng lọc y tế định kỳ có thể phát hiện các thay đổi bất thường trước khi chúng phát triển thành các bệnh cần điều trị phức tạp.","audioKind":"ex2"}],"collocations":[{"en":"abnormal behaviour","vi":"hành vi bất thường"},{"en":"abnormal growth","vi":"sự phát triển bất thường"},{"en":"abnormal heart rhythm","vi":"nhịp tim bất thường"}],"wordFamily":["normal (adj.)","normally (adv.)","abnormally (adv.)","abnormality (n.)"],"synonyms":["unusual","atypical"],"antonyms":["normal","typical"],"tipVi":"Thường dùng trong y học hoặc các hiện tượng bất thường, không nên tùy tiện dùng để đánh giá con người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dental', 'en-b2-27', 'dental', '/ˈdentəl/', 'B2', 'thuộc về răng; nha khoa', 'adj.', 'dentist (n.), dentistry (n.)', NULL, '"dental" là tính từ; nha sĩ là "dentist".', 'My dental appointment is early tomorrow, before work.', NULL, 'Lịch hẹn nha khoa của tôi vào sáng sớm mai, trước giờ làm.', '{"wordId":"dental","ukIpa":"/ˈdentəl/","usIpa":"/ˈdentəl/","cefr":"B2","topic":"health","senses":[{"pos":"adj.","en":"Relating to teeth or their care and treatment","vi":"thuộc về răng; nha khoa"}],"examples":[{"en":"My dental appointment is early tomorrow, before work.","vi":"Lịch hẹn nha khoa của tôi vào sáng sớm mai, trước giờ làm.","audioKind":"ex"},{"en":"Providing affordable dental care in schools could reduce health inequalities and prevent problems later in life.","vi":"Việc cung cấp dịch vụ chăm sóc nha khoa với chi phí hợp lý tại trường học có thể giảm bớt bất bình đẳng về sức khỏe và phòng ngừa các vấn đề về sau.","audioKind":"ex2"}],"collocations":[{"en":"dental care","vi":"chăm sóc răng miệng"},{"en":"dental treatment","vi":"điều trị nha khoa"},{"en":"dental check-up","vi":"khám răng"},{"en":"dental floss","vi":"chỉ nha khoa"}],"wordFamily":["dentist (n.)","dentistry (n.)"],"synonyms":[],"antonyms":[],"tipVi":"\"dental\" là tính từ; nha sĩ là \"dentist\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cigar', 'en-b2-27', 'cigar', '/sɪˈɡɑːr/', 'B2', 'xì gà', 'n.', NULL, NULL, '"cigar" là xì gà; "cigarette" là thuốc lá điếu thường được cuốn bằng giấy.', 'An unlit cigar lay inside the small wooden box.', NULL, 'Một điếu xì gà chưa châm lửa nằm bên trong chiếc hộp gỗ nhỏ.', '{"wordId":"cigar","ukIpa":"/sɪˈɡɑː/","usIpa":"/sɪˈɡɑːr/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"a thick roll of dried tobacco leaves made for smoking","vi":"xì gà"}],"examples":[{"en":"An unlit cigar lay inside the small wooden box.","vi":"Một điếu xì gà chưa châm lửa nằm bên trong chiếc hộp gỗ nhỏ.","audioKind":"ex"},{"en":"Public health campaigns should explain that smoking cigars also carries serious risks to health.","vi":"Các chiến dịch y tế công cộng nên giải thích rằng việc hút xì gà cũng tiềm ẩn những rủi ro nghiêm trọng đối với sức khỏe.","audioKind":"ex2"}],"collocations":[{"en":"cigar smoke","vi":"khói xì gà"},{"en":"cigar box","vi":"hộp đựng xì gà"},{"en":"smoke a cigar","vi":"hút xì gà"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"\"cigar\" là xì gà; \"cigarette\" là thuốc lá điếu thường được cuốn bằng giấy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rib', 'en-b2-27', 'rib', '/rɪb/', 'B2', 'xương sườn; sườn (thịt); trêu chọc (một cách thân thiện)', 'n.', 'ribbed (adj.)', NULL, 'Khi nói về món sườn thường dùng dạng số nhiều "ribs"; động từ "rib" thuộc lối nói thân mật, không trang trọng.', 'The doctor pointed to a rib on the model.', NULL, 'Bác sĩ chỉ vào một chiếc xương sườn trên mô hình.', '{"wordId":"rib","ukIpa":"/rɪb/","usIpa":"/rɪb/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"One of the curved bones surrounding the chest.","vi":"xương sườn"},{"pos":"n.","en":"A piece of meat containing an animal''s rib bones.","vi":"sườn (thịt)"},{"pos":"v.","en":"To tease someone in a friendly way.","vi":"trêu chọc (một cách thân thiện)"}],"examples":[{"en":"The doctor pointed to a rib on the model.","vi":"Bác sĩ chỉ vào một chiếc xương sườn trên mô hình.","audioKind":"ex"},{"en":"Wearing appropriate protective equipment can reduce the risk of rib injuries during contact sports.","vi":"Việc trang bị đồ bảo hộ phù hợp có thể làm giảm nguy cơ chấn thương xương sườn khi chơi các môn thể thao đối kháng.","audioKind":"ex2"}],"collocations":[{"en":"broken rib","vi":"xương sườn bị gãy"},{"en":"rib cage","vi":"lồng ngực"},{"en":"grilled ribs","vi":"sườn nướng"},{"en":"rib someone about something","vi":"trêu chọc ai về chuyện gì"}],"wordFamily":["ribbed (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi nói về món sườn thường dùng dạng số nhiều \"ribs\"; động từ \"rib\" thuộc lối nói thân mật, không trang trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nerve', 'en-b2-27', 'nerve', '/nɝːv/', 'B2', 'dây thần kinh; can đảm; gan dạ; sự trơ trẽn; mặt dày', 'n.', 'nervous (adj.), nervously (adv.), nervousness (n.)', NULL, 'Nerve chỉ lòng can đảm thường là danh từ không đếm được; nerves có thể chỉ sự căng thẳng thần kinh.', 'The dentist explained that a nerve was causing the pain.', NULL, 'Nha sĩ giải thích rằng một dây thần kinh đang gây ra cơn đau.', '{"wordId":"nerve","ukIpa":"/nɜːv/","usIpa":"/nɝːv/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"A fibre carrying signals between the brain and body.","vi":"dây thần kinh"},{"pos":"n.","en":"The courage to do something difficult or frightening.","vi":"can đảm; gan dạ"},{"pos":"n.","en":"Rude confidence that makes someone behave without respect.","vi":"sự trơ trẽn; mặt dày"}],"examples":[{"en":"The dentist explained that a nerve was causing the pain.","vi":"Nha sĩ giải thích rằng một dây thần kinh đang gây ra cơn đau.","audioKind":"ex"},{"en":"Damage to a single nerve can affect movement and reduce a patient''s quality of life.","vi":"Tổn thương dù chỉ một dây thần kinh cũng có thể ảnh hưởng đến khả năng vận động và làm giảm chất lượng cuộc sống của bệnh nhân.","audioKind":"ex2"}],"collocations":[{"en":"nerve damage","vi":"tổn thương thần kinh"},{"en":"lose your nerve","vi":"mất can đảm"},{"en":"have the nerve to do something","vi":"cả gan làm điều gì"}],"wordFamily":["nervous (adj.)","nervously (adv.)","nervousness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nerve chỉ lòng can đảm thường là danh từ không đếm được; nerves có thể chỉ sự căng thẳng thần kinh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_liver', 'en-b2-27', 'liver', '/ˈlɪvər/', 'B2', 'gan; gan động vật (dùng làm thức ăn)', 'n.', NULL, NULL, 'Khi chỉ cơ quan trong cơ thể, thường dùng "the liver"; khi chỉ thực phẩm, từ này thường không đếm được.', 'The doctor explained how the liver keeps us healthy.', NULL, 'Bác sĩ đã giải thích cách gan duy trì sức khỏe cho cơ thể chúng ta.', '{"wordId":"liver","ukIpa":"/ˈlɪvə/","usIpa":"/ˈlɪvər/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"An organ that processes nutrients and removes harmful substances from blood.","vi":"gan"},{"pos":"n.","en":"An animal''s liver prepared or eaten as food.","vi":"gan động vật (dùng làm thức ăn)"}],"examples":[{"en":"The doctor explained how the liver keeps us healthy.","vi":"Bác sĩ đã giải thích cách gan duy trì sức khỏe cho cơ thể chúng ta.","audioKind":"ex"},{"en":"Public health campaigns should explain how a balanced diet can support the liver and reduce disease risks.","vi":"Các chiến dịch y tế cộng đồng nên giải thích cách một chế độ ăn uống cân bằng có thể hỗ trợ gan và giảm thiểu nguy cơ mắc bệnh.","audioKind":"ex2"}],"collocations":[{"en":"liver disease","vi":"bệnh gan"},{"en":"liver function","vi":"chức năng gan"},{"en":"liver transplant","vi":"ghép gan"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ cơ quan trong cơ thể, thường dùng \"the liver\"; khi chỉ thực phẩm, từ này thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_psychologist', 'en-b2-27', 'psychologist', '/saɪˈkɑːlədʒɪst/', 'B2', 'chuyên gia tâm lý; nhà tâm lý học', 'n.', 'psychology (n.), psychological (adj.), psychologically (adv.)', NULL, 'Chữ cái đầu p không phát âm; không đồng nhất với bác sĩ tâm thần psychiatrist.', 'The psychologist helped me understand why exams made me anxious.', NULL, 'Chuyên gia tâm lý đã giúp tôi hiểu tại sao các kỳ thi lại khiến tôi lo lắng.', '{"wordId":"psychologist","ukIpa":"/saɪˈkɒlədʒɪst/","usIpa":"/saɪˈkɑːlədʒɪst/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"An expert who studies the mind or helps with psychological problems.","vi":"chuyên gia tâm lý; nhà tâm lý học"}],"examples":[{"en":"The psychologist helped me understand why exams made me anxious.","vi":"Chuyên gia tâm lý đã giúp tôi hiểu tại sao các kỳ thi lại khiến tôi lo lắng.","audioKind":"ex"},{"en":"A school psychologist can support students whose emotional difficulties interfere with learning and social development.","vi":"Nhà tâm lý học đường có thể hỗ trợ những học sinh có khó khăn về mặt cảm xúc cản trở quá trình học tập và phát triển xã hội.","audioKind":"ex2"}],"collocations":[{"en":"clinical psychologist","vi":"chuyên gia tâm lý lâm sàng"},{"en":"educational psychologist","vi":"chuyên gia tâm lý học đường"},{"en":"consult a psychologist","vi":"tư vấn chuyên gia tâm lý"}],"wordFamily":["psychology (n.)","psychological (adj.)","psychologically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Chữ cái đầu p không phát âm; không đồng nhất với bác sĩ tâm thần psychiatrist.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_obesity', 'en-b2-27', 'obesity', '/oʊˈbiːsəti/', 'B2', 'bệnh béo phì', 'n.', 'obese (adj.)', NULL, 'Là danh từ không đếm được; có thể dùng cụm people with obesity để gọi người mắc bệnh.', 'The clinic offers supportive care for people with obesity.', NULL, 'Phòng khám cung cấp dịch vụ chăm sóc hỗ trợ cho những người mắc bệnh béo phì.', '{"wordId":"obesity","ukIpa":"/əʊˈbiːsəti/","usIpa":"/oʊˈbiːsəti/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"A condition involving excess body fat that can harm health.","vi":"bệnh béo phì"}],"examples":[{"en":"The clinic offers supportive care for people with obesity.","vi":"Phòng khám cung cấp dịch vụ chăm sóc hỗ trợ cho những người mắc bệnh béo phì.","audioKind":"ex"},{"en":"Preventing obesity requires attention to food environments, physical activity, and the wider social factors that influence health.","vi":"Phòng ngừa béo phì đòi hỏi phải chú ý đến môi trường thực phẩm, hoạt động thể chất và các yếu tố xã hội rộng lớn hơn ảnh hưởng đến sức khỏe.","audioKind":"ex2"}],"collocations":[{"en":"childhood obesity","vi":"bệnh béo phì ở trẻ em"},{"en":"obesity prevention","vi":"phòng ngừa béo phì"},{"en":"obesity rates","vi":"tỷ lệ béo phì"}],"wordFamily":["obese (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ không đếm được; có thể dùng cụm people with obesity để gọi người mắc bệnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_numb', 'en-b2-27', 'numb', '/nʌm/', 'B2', 'mất cảm giác; tê (một phần cơ thể); vô cảm; đờ đẫn (thường do sốc); làm tê liệt; làm mất cảm giác', 'adj.', 'numbness (n), numbly (adv)', NULL, 'Phụ âm b cuối không phát âm; từ này có thể dùng cho cả cảm giác thể chất lẫn cảm xúc tinh thần.', 'My fingers went numb while I waited in the snow.', NULL, 'Ngón tay tôi bị tê cứng khi đứng chờ trong tuyết.', '{"wordId":"numb","ukIpa":"/nʌm/","usIpa":"/nʌm/","cefr":"B2","topic":"health","senses":[{"pos":"adj.","en":"Unable to feel physical sensations in part of the body.","vi":"mất cảm giác; tê (một phần cơ thể)"},{"pos":"adj.","en":"Unable to feel emotions, often because of shock.","vi":"vô cảm; đờ đẫn (thường do sốc)"},{"pos":"v.","en":"To make a body part or someone''s feelings less sensitive.","vi":"làm tê liệt; làm mất cảm giác"}],"examples":[{"en":"My fingers went numb while I waited in the snow.","vi":"Ngón tay tôi bị tê cứng khi đứng chờ trong tuyết.","audioKind":"ex"},{"en":"Workers exposed to extreme cold may develop numb fingers, reducing their ability to handle equipment safely.","vi":"Những công nhân tiếp xúc với cái lạnh khắc nghiệt có thể bị tê ngón tay, làm giảm khả năng vận hành thiết bị an toàn.","audioKind":"ex2"}],"collocations":[{"en":"go numb","vi":"trở nên tê cóng"},{"en":"feel numb","vi":"cảm thấy tê"},{"en":"numb with shock","vi":"chết lặng vì sốc"},{"en":"numb the pain","vi":"làm giảm cơn đau"}],"wordFamily":["numbness (n)","numbly (adv)"],"synonyms":[],"antonyms":[],"tipVi":"Phụ âm b cuối không phát âm; từ này có thể dùng cho cả cảm giác thể chất lẫn cảm xúc tinh thần.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_surgeon', 'en-b2-27', 'surgeon', '/ˈsɝːdʒən/', 'B2', 'bác sĩ phẫu thuật', 'n.', 'surgery (n.), surgical (adj.), surgically (adv.)', NULL, 'surgeon chỉ bác sĩ phẫu thuật; surgery có thể chỉ ca phẫu thuật hoặc phòng khám.', 'The surgeon explained the operation before I went home.', NULL, 'Bác sĩ phẫu thuật đã giải thích về ca mổ trước khi tôi xuất viện.', '{"wordId":"surgeon","ukIpa":"/ˈsɜːdʒən/","usIpa":"/ˈsɝːdʒən/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"a doctor trained to perform operations","vi":"bác sĩ phẫu thuật"}],"examples":[{"en":"The surgeon explained the operation before I went home.","vi":"Bác sĩ phẫu thuật đã giải thích về ca mổ trước khi tôi xuất viện.","audioKind":"ex"},{"en":"Rural hospitals often struggle to recruit experienced surgeons, which can delay essential treatment for local residents.","vi":"Các bệnh viện nông thôn thường gặp khó khăn trong việc tuyển dụng bác sĩ phẫu thuật giàu kinh nghiệm, điều này có thể làm chậm trễ việc điều trị thiết yếu cho cư dân địa phương.","audioKind":"ex2"}],"collocations":[{"en":"experienced surgeon","vi":"bác sĩ phẫu thuật giàu kinh nghiệm"},{"en":"heart surgeon","vi":"bác sĩ phẫu thuật tim"},{"en":"orthopaedic surgeon","vi":"bác sĩ phẫu thuật chỉnh hình"}],"wordFamily":["surgery (n.)","surgical (adj.)","surgically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"surgeon chỉ bác sĩ phẫu thuật; surgery có thể chỉ ca phẫu thuật hoặc phòng khám.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_follow-up', 'en-b2-27', 'follow-up', '/ˈfɑːloʊ ʌp/', 'B2', 'đợt tái khám; buổi theo dõi; việc theo dõi tiến độ; tiếp theo; mang tính theo dõi, bổ sung', 'n.', 'follow (v.)', NULL, 'Danh từ và tính từ viết có dấu gạch nối; cụm động từ follow up không có.', 'The clinic arranged a follow-up to check my recovery.', NULL, 'Phòng khám đã sắp xếp một buổi tái khám để kiểm tra tình trạng hồi phục của tôi.', '{"wordId":"follow-up","ukIpa":"/ˈfɒləʊ ʌp/","usIpa":"/ˈfɑːloʊ ʌp/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"An action continuing or checking earlier work or treatment.","vi":"đợt tái khám; buổi theo dõi; việc theo dõi tiến độ"},{"pos":"adj.","en":"Done after something to continue it or check its results.","vi":"tiếp theo; mang tính theo dõi, bổ sung"}],"examples":[{"en":"The clinic arranged a follow-up to check my recovery.","vi":"Phòng khám đã sắp xếp một buổi tái khám để kiểm tra tình trạng hồi phục của tôi.","audioKind":"ex"},{"en":"A follow-up study is needed to determine whether the training programme produces lasting improvements in employment outcomes.","vi":"Cần phải tiến hành một nghiên cứu tiếp theo để xác định xem chương trình đào tạo có mang lại những cải thiện lâu dài về kết quả việc làm hay không.","audioKind":"ex2"}],"collocations":[{"en":"a follow-up appointment","vi":"lịch hẹn tái khám"},{"en":"a follow-up study","vi":"nghiên cứu tiếp theo"},{"en":"a follow-up question","vi":"câu hỏi truy vấn"},{"en":"a follow-up visit","vi":"chuyến thăm lại"}],"wordFamily":["follow (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ và tính từ viết có dấu gạch nối; cụm động từ follow up không có.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_harmful', 'en-b2-27', 'harmful', '/ˈhɑːrmfəl/', 'B2', 'có hại; gây tổn hại', 'adj.', 'harm (n.), harm (v.), harmless (adj.)', 'Đồng nghĩa: damaging, detrimental · Trái nghĩa: harmless, beneficial', 'Diễn đạt việc có hại cho cái gì dùng harmful to, tuyệt đối không dùng harmful for.', 'Too much direct sunlight can be harmful to your skin.', NULL, 'Ánh nắng mặt trời chiếu trực tiếp quá nhiều có thể gây hại cho làn da của bạn.', '{"wordId":"harmful","ukIpa":"/ˈhɑːmfəl/","usIpa":"/ˈhɑːrmfəl/","cefr":"B2","topic":"health","senses":[{"pos":"adj.","en":"causing or likely to cause damage or injury","vi":"có hại; gây tổn hại"}],"examples":[{"en":"Too much direct sunlight can be harmful to your skin.","vi":"Ánh nắng mặt trời chiếu trực tiếp quá nhiều có thể gây hại cho làn da của bạn.","audioKind":"ex"},{"en":"Stricter controls on industrial waste could reduce the harmful effects of water pollution on local ecosystems.","vi":"Việc kiểm soát chặt chẽ hơn đối với chất thải công nghiệp có thể làm giảm tác hại của ô nhiễm nước đối với hệ sinh thái địa phương.","audioKind":"ex2"}],"collocations":[{"en":"harmful to health","vi":"có hại cho sức khỏe"},{"en":"harmful effects","vi":"tác hại"},{"en":"harmful substances","vi":"chất có hại"},{"en":"potentially harmful","vi":"có tiềm ẩn nguy cơ gây hại"}],"wordFamily":["harm (n.)","harm (v.)","harmless (adj.)"],"synonyms":["damaging","detrimental"],"antonyms":["harmless","beneficial"],"tipVi":"Diễn đạt việc có hại cho cái gì dùng harmful to, tuyệt đối không dùng harmful for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_soy', 'en-b2-27', 'soy', '/sɔɪ/', 'B2', 'đậu nành; sản phẩm từ đậu nành; nước tương; xì dầu', 'n.', 'soybean (n.)', 'Đồng nghĩa: soya', 'Tiếng Anh-Anh cũng thường dùng soya; “nước tương” thường được gọi là soy sauce.', 'I usually pour soy milk over my breakfast cereal.', NULL, 'Tôi thường chan sữa đậu nành vào ngũ cốc ăn sáng của mình.', '{"wordId":"soy","ukIpa":"/sɔɪ/","usIpa":"/sɔɪ/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"beans grown for their protein, or food made from them","vi":"đậu nành; sản phẩm từ đậu nành"},{"pos":"n.","en":"a salty brown sauce made from fermented beans","vi":"nước tương; xì dầu"}],"examples":[{"en":"I usually pour soy milk over my breakfast cereal.","vi":"Tôi thường chan sữa đậu nành vào ngũ cốc ăn sáng của mình.","audioKind":"ex"},{"en":"Soy provides plant protein, but expanding its cultivation can threaten forests when land is cleared irresponsibly.","vi":"Đậu nành cung cấp protein thực vật, nhưng việc mở rộng diện tích trồng trọt có thể đe dọa các khu rừng nếu đất đai bị khai phá một cách thiếu trách nhiệm.","audioKind":"ex2"}],"collocations":[{"en":"soy milk","vi":"sữa đậu nành"},{"en":"soy sauce","vi":"nước tương"},{"en":"soy protein","vi":"protein đậu nành"},{"en":"soy products","vi":"sản phẩm từ đậu nành"}],"wordFamily":["soybean (n.)"],"synonyms":["soya"],"antonyms":[],"tipVi":"Tiếng Anh-Anh cũng thường dùng soya; “nước tương” thường được gọi là soy sauce.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unconscious', 'en-b2-27', 'unconscious', '/ʌnˈkɑːnʃəs/', 'B2', 'bất tỉnh; mất tri giác; vô thức; không nhận thức được', 'adj.', 'conscious (adj.), unconsciously (adv.), unconsciousness (n.), consciousness (n.)', 'Đồng nghĩa: unaware, insensible · Trái nghĩa: conscious, aware', 'unconscious of diễn tả việc không nhận thức được điều gì; trạng thái bất tỉnh khác với việc ngủ thông thường.', 'The unconscious patient was breathing steadily beneath a blanket.', NULL, 'Bệnh nhân đang bất tỉnh vẫn thở đều đặn dưới tấm chăn.', '{"wordId":"unconscious","ukIpa":"/ʌnˈkɒnʃəs/","usIpa":"/ʌnˈkɑːnʃəs/","cefr":"B2","topic":"health","senses":[{"pos":"adj.","en":"unable to see, hear, or respond because awareness is lost","vi":"bất tỉnh; mất tri giác"},{"pos":"adj.","en":"done without awareness, or unaware of something","vi":"vô thức; không nhận thức được"}],"examples":[{"en":"The unconscious patient was breathing steadily beneath a blanket.","vi":"Bệnh nhân đang bất tỉnh vẫn thở đều đặn dưới tấm chăn.","audioKind":"ex"},{"en":"Unconscious bias can influence recruitment decisions, even when employers aim to treat all applicants fairly.","vi":"Định kiến vô thức có thể ảnh hưởng đến các quyết định tuyển dụng, ngay cả khi nhà tuyển dụng nhắm tới việc đối xử công bằng với mọi ứng viên.","audioKind":"ex2"}],"collocations":[{"en":"fall unconscious","vi":"rơi vào trạng thái bất tỉnh"},{"en":"remain unconscious","vi":"vẫn bất tỉnh"},{"en":"unconscious bias","vi":"định kiến vô thức"},{"en":"unconscious of","vi":"không hay biết về"}],"wordFamily":["conscious (adj.)","unconsciously (adv.)","unconsciousness (n.)","consciousness (n.)"],"synonyms":["unaware","insensible"],"antonyms":["conscious","aware"],"tipVi":"unconscious of diễn tả việc không nhận thức được điều gì; trạng thái bất tỉnh khác với việc ngủ thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pimple', 'en-b2-27', 'pimple', '/ˈpɪmpəl/', 'B2', 'mụn trứng cá; mụn nhọt', 'n.', 'pimply (adj.)', 'Đồng nghĩa: spot', 'Pimple chỉ nốt mụn đơn lẻ; acne chỉ tình trạng bệnh lý mụn trứng cá nói chung.', 'A small pimple appeared on my chin overnight.', NULL, 'Một cái mụn nhỏ mọc lên trên cằm tôi sau một đêm.', '{"wordId":"pimple","ukIpa":"/ˈpɪmpəl/","usIpa":"/ˈpɪmpəl/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"A small raised spot on the skin, often red.","vi":"mụn trứng cá; mụn nhọt"}],"examples":[{"en":"A small pimple appeared on my chin overnight.","vi":"Một cái mụn nhỏ mọc lên trên cằm tôi sau một đêm.","audioKind":"ex"},{"en":"Teenagers who develop pimples may benefit from gentle skincare rather than frequent washing with harsh soap.","vi":"Thanh thiếu niên bị mụn trứng cá có thể được cải thiện nhờ cách chăm sóc da nhẹ nhàng thay vì rửa mặt thường xuyên bằng xà phòng có tính tẩy mạnh.","audioKind":"ex2"}],"collocations":[{"en":"get a pimple","vi":"mọc mụn"},{"en":"squeeze a pimple","vi":"nặn mụn"},{"en":"a pimple on your chin","vi":"mụn ở cằm"}],"wordFamily":["pimply (adj.)"],"synonyms":["spot"],"antonyms":[],"tipVi":"Pimple chỉ nốt mụn đơn lẻ; acne chỉ tình trạng bệnh lý mụn trứng cá nói chung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_starve', 'en-b2-27', 'starve', '/stɑːrv/', 'B2', 'chết đói; thiếu ăn; làm cho chết đói; bỏ đói; thiếu thốn trầm trọng (nguồn lực, v.v.)', 'v.', 'starvation (n.)', NULL, 'Trong đời sống, I''m starving có nghĩa là tôi đang rất đói, chứ không phải sắp chết đói.', 'Without regular feeding, these rescued animals could starve.', NULL, 'Nếu không được cho ăn đều đặn, những con vật được giải cứu này có thể sẽ chết đói.', '{"wordId":"starve","ukIpa":"/stɑːv/","usIpa":"/stɑːrv/","cefr":"B2","topic":"health","senses":[{"pos":"v.","en":"To suffer or die from insufficient food","vi":"chết đói; thiếu ăn; làm cho chết đói"},{"pos":"v.","en":"To deny someone or something an essential resource","vi":"bỏ đói; thiếu thốn trầm trọng (nguồn lực, v.v.)"}],"examples":[{"en":"Without regular feeding, these rescued animals could starve.","vi":"Nếu không được cho ăn đều đặn, những con vật được giải cứu này có thể sẽ chết đói.","audioKind":"ex"},{"en":"When drought destroys crops, rural families may starve unless emergency food supplies reach them quickly.","vi":"Khi hạn hán làm hỏng mùa màng, các gia đình nông thôn có thể rơi cảnh thiếu đói trừ khi nguồn lương thực cứu trợ đến tay họ thật nhanh chóng.","audioKind":"ex2"}],"collocations":[{"en":"starve to death","vi":"chết đói"},{"en":"be starving","vi":"đói lả"},{"en":"be starved of resources","vi":"thiếu thốn tài nguyên trầm trọng"}],"wordFamily":["starvation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong đời sống, I''m starving có nghĩa là tôi đang rất đói, chứ không phải sắp chết đói.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_surgery', 'en-b2-27', 'surgery', '/ˈsɝːdʒəri/', 'B2', 'phẫu thuật; phòng khám', 'n.', 'surgeon (n.), surgical (adj.), surgically (adv.)', NULL, 'Nghĩa phẫu thuật thường không đếm được; trong tiếng Anh-Anh, nghĩa phòng khám là danh từ đếm được.', 'My uncle is recovering well after knee surgery.', NULL, 'Chú của tôi đang hồi phục rất tốt sau ca phẫu thuật đầu gối.', '{"wordId":"surgery","ukIpa":"/ˈsɜːdʒəri/","usIpa":"/ˈsɝːdʒəri/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"Medical treatment involving cutting into the body to repair damage.","vi":"phẫu thuật"},{"pos":"n.","en":"A place where a doctor or dentist sees patients.","vi":"phòng khám"}],"examples":[{"en":"My uncle is recovering well after knee surgery.","vi":"Chú của tôi đang hồi phục rất tốt sau ca phẫu thuật đầu gối.","audioKind":"ex"},{"en":"Advances in medical technology have made many types of surgery safer and reduced patients'' recovery times.","vi":"Những tiến bộ trong công nghệ y tế đã làm cho nhiều loại phẫu thuật trở nên an toàn hơn và rút ngắn thời gian hồi phục của bệnh nhân.","audioKind":"ex2"}],"collocations":[{"en":"undergo surgery","vi":"trải qua phẫu thuật"},{"en":"emergency surgery","vi":"phẫu thuật cấp cứu"},{"en":"minor surgery","vi":"phẫu thuật nhỏ"},{"en":"a doctor''s surgery","vi":"phòng khám của bác sĩ"}],"wordFamily":["surgeon (n.)","surgical (adj.)","surgically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa phẫu thuật thường không đếm được; trong tiếng Anh-Anh, nghĩa phòng khám là danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_27_1', 'en-b2-27', 'Cách dùng “rib” (n.) — xương sườn', 'broken rib  ·  rib cage  ·  grilled ribs', 'Khi nói về món sườn thường dùng dạng số nhiều "ribs"; động từ "rib" thuộc lối nói thân mật, không trang trọng.', 'Họ từ (Word Family): ribbed (adj.)', '[{"hanzi":"The doctor pointed to a rib on the model.","pinyin":"","meaning":"Bác sĩ chỉ vào một chiếc xương sườn trên mô hình."},{"hanzi":"Wearing appropriate protective equipment can reduce the risk of rib injuries during contact sports.","pinyin":"","meaning":"Việc trang bị đồ bảo hộ phù hợp có thể làm giảm nguy cơ chấn thương xương sườn khi chơi các môn thể thao đối kháng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_27_2', 'en-b2-27', 'Cách dùng “protein” (n.) — chất đạm; protein', 'high in protein  ·  a source of protein  ·  plant protein', 'Từ protein thường không đếm được khi chỉ chất dinh dưỡng; có thể đếm được khi chỉ các loại protein khác nhau.', NULL, '[{"hanzi":"These beans add protein to our vegetable soup.","pinyin":"","meaning":"Những hạt đậu này bổ sung protein cho món súp rau củ của chúng ta."},{"hanzi":"A balanced plant-based diet can provide sufficient protein when it includes varied sources such as beans and nuts.","pinyin":"","meaning":"Một chế độ ăn thuần thực vật cân bằng có thể cung cấp đủ lượng protein khi bao gồm các nguồn thực phẩm đa dạng như đậu và các loại hạt."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_27_3', 'en-b2-27', 'Cách dùng “unconscious” (adj.) — bất tỉnh; mất tri giác', 'fall unconscious  ·  remain unconscious  ·  unconscious bias', 'unconscious of diễn tả việc không nhận thức được điều gì; trạng thái bất tỉnh khác với việc ngủ thông thường.', 'Họ từ (Word Family): conscious (adj.), unconsciously (adv.), unconsciousness (n.), consciousness (n.) | Đồng nghĩa: unaware, insensible · Trái nghĩa: conscious, aware', '[{"hanzi":"The unconscious patient was breathing steadily beneath a blanket.","pinyin":"","meaning":"Bệnh nhân đang bất tỉnh vẫn thở đều đặn dưới tấm chăn."},{"hanzi":"Unconscious bias can influence recruitment decisions, even when employers aim to treat all applicants fairly.","pinyin":"","meaning":"Định kiến vô thức có thể ảnh hưởng đến các quyết định tuyển dụng, ngay cả khi nhà tuyển dụng nhắm tới việc đối xử công bằng với mọi ứng viên."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_27_4', 'en-b2-27', 'Cách dùng “liver” (n.) — gan', 'liver disease  ·  liver function  ·  liver transplant', 'Khi chỉ cơ quan trong cơ thể, thường dùng "the liver"; khi chỉ thực phẩm, từ này thường không đếm được.', NULL, '[{"hanzi":"The doctor explained how the liver keeps us healthy.","pinyin":"","meaning":"Bác sĩ đã giải thích cách gan duy trì sức khỏe cho cơ thể chúng ta."},{"hanzi":"Public health campaigns should explain how a balanced diet can support the liver and reduce disease risks.","pinyin":"","meaning":"Các chiến dịch y tế cộng đồng nên giải thích cách một chế độ ăn uống cân bằng có thể hỗ trợ gan và giảm thiểu nguy cơ mắc bệnh."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_27_1', 'en-b2-27', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
