INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_27_1_2', 'ten_b2_27_1', 'digest', 'My stomach finds heavy meals difficult to digest.', 'My stomach finds heavy meals difficult to digest.', '/daɪˈdʒest/', 'Dạ dày của tôi rất khó tiêu hóa những bữa ăn nhiều đạm và nặng bụng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
