INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_27_1_4', 'ten_b2_27_1', 'hearing', 'My grandfather''s hearing improved after he received a hearing aid.', 'My grandfather''s hearing improved after he received a hearing aid.', '/ˈhɪrɪŋ/', 'Thính giác của ông tôi đã cải thiện sau khi ông đeo máy trợ thính.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_27_1_5', 'ten_b2_27_1', 'prescribe', 'The doctor prescribed eye drops for my sore eyes.', 'The doctor prescribed eye drops for my sore eyes.', '/prɪˈskraɪb/', 'Bác sĩ đã kê thuốc nhỏ mắt để chữa chứng đau mắt cho tôi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_27_1_6', 'ten_b2_27_1', 'drowsy', 'The warm room made me drowsy after lunch.', 'The warm room made me drowsy after lunch.', '/ˈdraʊzi/', 'Căn phòng ấm áp làm tôi cảm thấy buồn ngủ sau bữa trưa.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_27_1_7', 'ten_b2_27_1', 'sexual', 'The clinic offers confidential advice about sexual health.', 'The clinic offers confidential advice about sexual health.', '/ˈsekʃuəl/', 'Phòng khám cung cấp dịch vụ tư vấn bảo mật về sức khỏe tình dục.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_27_1_8', 'ten_b2_27_1', 'meditate', 'I meditate for ten minutes before breakfast each morning.', 'I meditate for ten minutes before breakfast each morning.', '/ˈmedɪteɪt/', 'Tôi thiền mười phút trước bữa sáng mỗi buổi sáng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_27_1_1', 'en-b2-27', 'ten_b2_27_1', 'listening', 'listening', 'My brother snores so loudly that the dog leaves.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bác sĩ phẫu thuật đã giải thích về ca mổ trước khi tôi xuất viện.","Phòng khám đã sắp xếp một buổi tái khám để kiểm tra tình trạng hồi phục của tôi.","Anh trai tôi ngáy to đến mức con chó phải bỏ đi nơi khác.","Nha sĩ giải thích rằng một dây thần kinh đang gây ra cơn đau."]'::jsonb, 2, 'My brother snores so loudly that the dog leaves. → Anh trai tôi ngáy to đến mức con chó phải bỏ đi nơi khác.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_27_1_2', 'en-b2-27', 'ten_b2_27_1', 'listening', 'listening', 'My stomach finds heavy meals difficult to digest.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một điếu xì gà chưa châm lửa nằm bên trong chiếc hộp gỗ nhỏ.","Bác sĩ đã giải thích cách gan duy trì sức khỏe cho cơ thể chúng ta.","Ngón tay tôi bị tê cứng khi đứng chờ trong tuyết.","Dạ dày của tôi rất khó tiêu hóa những bữa ăn nhiều đạm và nặng bụng."]'::jsonb, 3, 'My stomach finds heavy meals difficult to digest. → Dạ dày của tôi rất khó tiêu hóa những bữa ăn nhiều đạm và nặng bụng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_27_1_3', 'en-b2-27', 'ten_b2_27_1', 'listening', 'listening', 'These beans add protein to our vegetable soup.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Thính giác của ông tôi đã cải thiện sau khi ông đeo máy trợ thính.","Anh trai tôi ngáy to đến mức con chó phải bỏ đi nơi khác.","Những hạt đậu này bổ sung protein cho món súp rau củ của chúng ta.","Bác sĩ phẫu thuật đã giải thích về ca mổ trước khi tôi xuất viện."]'::jsonb, 2, 'These beans add protein to our vegetable soup. → Những hạt đậu này bổ sung protein cho món súp rau củ của chúng ta.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_27_2', 'en-b2-27', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_27_2_1', 'ten_b2_27_2', 'snore', 'People who snore regularly may benefit from medical advice, particularly if their breathing stops briefly during sleep.', 'People who snore regularly may benefit from medical advice, particularly if their breathing stops briefly during sleep.', '/snɔːr/', 'Những người thường xuyên ngáy có thể cần sự tư vấn y tế, đặc biệt là khi nhịp thở của họ bị ngắt quãng ngắn trong khi ngủ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_27_2_2', 'ten_b2_27_2', 'digest', 'Students need sufficient time to digest complex information before applying it to unfamiliar problems.', 'Students need sufficient time to digest complex information before applying it to unfamiliar problems.', '/daɪˈdʒest/', 'Học sinh cần có đủ thời gian để lĩnh hội các thông tin phức tạp trước khi áp dụng chúng vào các vấn đề chưa quen thuộc.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_27_2_3', 'ten_b2_27_2', 'protein', 'A balanced plant-based diet can provide sufficient protein when it includes varied sources such as beans and nuts.', 'A balanced plant-based diet can provide sufficient protein when it includes varied sources such as beans and nuts.', '/ˈproʊtiːn/', 'Một chế độ ăn thuần thực vật cân bằng có thể cung cấp đủ lượng protein khi bao gồm các nguồn thực phẩm đa dạng như đậu và các loại hạt.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_27_2_4', 'ten_b2_27_2', 'hearing', 'A public hearing allows residents to express concerns before major construction projects receive official approval.', 'A public hearing allows residents to express concerns before major construction projects receive official approval.', '/ˈhɪrɪŋ/', 'Một phiên điều trần công khai cho phép cư dân bày tỏ những mối lo ngại trước khi các dự án xây dựng lớn nhận được phê duyệt chính thức.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_27_2_5', 'ten_b2_27_2', 'prescribe', 'Doctors should prescribe antibiotics only when necessary to reduce the risk of bacteria developing resistance.', 'Doctors should prescribe antibiotics only when necessary to reduce the risk of bacteria developing resistance.', '/prɪˈskraɪb/', 'Các bác sĩ chỉ nên kê kháng sinh khi thực sự cần thiết để giảm nguy cơ vi khuẩn kháng thuốc.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_27_2_6', 'ten_b2_27_2', 'drowsy', 'Drivers who feel drowsy should stop somewhere safe, as fatigue significantly increases the risk of accidents.', 'Drivers who feel drowsy should stop somewhere safe, as fatigue significantly increases the risk of accidents.', '/ˈdraʊzi/', 'Những tài xế cảm thấy buồn ngủ nên dừng xe ở một nơi an toàn, bởi vì sự mệt mỏi làm tăng đáng kể nguy cơ xảy ra tai nạn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_27_2_1', 'en-b2-27', 'ten_b2_27_2', 'listening', 'listening', 'People who snore regularly may benefit from medical advice, particularly if their breathing stops briefly during sleep.', NULL, 'Trong câu vừa nghe, từ “snore” mang nghĩa nào sau đây?', '["cách dùng từ; lời lẽ; văn bản","ngáy; ngáy ngủ","dây đeo; quai; đai","nhà trệt; nhà một tầng"]'::jsonb, 1, '“snore” (/snɔːr/): ngáy; ngáy ngủ. Câu đầy đủ: People who snore regularly may benefit from medical advice, particularly if their breathing stops briefly during sleep.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_27_2_2', 'en-b2-27', 'ten_b2_27_2', 'listening', 'listening', 'Students need sufficient time to digest complex information before applying it to unfamiliar problems.', NULL, 'Trong câu vừa nghe, từ “digest” mang nghĩa nào sau đây?', '["nhôm","sự thất vọng; nỗi bực bội; cảm giác chán nản","danh tiếng, uy tín, tiếng tăm","tiêu hóa"]'::jsonb, 3, '“digest” (/daɪˈdʒest/): tiêu hóa. Câu đầy đủ: Students need sufficient time to digest complex information before applying it to unfamiliar problems.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
