INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_27_4', 'en-b2-27', NULL, 'comprehensive_test', 'listening', 'My grandfather''s hearing improved after he received a hearing aid.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Anh trai tôi ngáy to đến mức con chó phải bỏ đi nơi khác.","Chú của tôi đang hồi phục rất tốt sau ca phẫu thuật đầu gối.","Thính giác của ông tôi đã cải thiện sau khi ông đeo máy trợ thính.","Lịch hẹn nha khoa của tôi vào sáng sớm mai, trước giờ làm."]'::jsonb, 2, 'My grandfather''s hearing improved after he received a hearing aid. → Thính giác của ông tôi đã cải thiện sau khi ông đeo máy trợ thính.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_27_5', 'en-b2-27', NULL, 'comprehensive_test', 'listening', 'prescribe', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đề xuất; đưa ra ý kiến","làm bắn tóe chất lỏng; tạt nước","chất thải; khí thải","kê đơn (thuốc); chỉ định điều trị"]'::jsonb, 3, 'prescribe (/prɪˈskraɪb/) → kê đơn (thuốc); chỉ định điều trị; quy định; chỉ định; ra lệnh', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_27_6', 'en-b2-27', NULL, 'comprehensive_test', 'listening', 'The warm room made me drowsy after lunch.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một cái mụn nhỏ mọc lên trên cằm tôi sau một đêm.","Căn phòng ấm áp làm tôi cảm thấy buồn ngủ sau bữa trưa.","Tôi thường chan sữa đậu nành vào ngũ cốc ăn sáng của mình.","Bác sĩ phẫu thuật đã giải thích về ca mổ trước khi tôi xuất viện."]'::jsonb, 1, 'The warm room made me drowsy after lunch. → Căn phòng ấm áp làm tôi cảm thấy buồn ngủ sau bữa trưa.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_27_7', 'en-b2-27', NULL, 'comprehensive_test', 'listening', 'sexual', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự quyết tâm; nghị lực","mang nét nữ tính; dịu dàng","hoàn toàn; thuần túy; chỉ vì","liên quan đến tình dục; thuộc về giới tính"]'::jsonb, 3, 'sexual (/ˈsekʃuəl/) → liên quan đến tình dục; thuộc về giới tính; có sự sinh sản hữu tính', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_27_8', 'en-b2-27', NULL, 'comprehensive_test', 'listening', 'I meditate for ten minutes before breakfast each morning.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bác sĩ phẫu thuật đã giải thích về ca mổ trước khi tôi xuất viện.","Tôi thiền mười phút trước bữa sáng mỗi buổi sáng.","Ánh nắng mặt trời chiếu trực tiếp quá nhiều có thể gây hại cho làn da của bạn.","Bác sĩ đã giải thích cách gan duy trì sức khỏe cho cơ thể chúng ta."]'::jsonb, 1, 'I meditate for ten minutes before breakfast each morning. → Tôi thiền mười phút trước bữa sáng mỗi buổi sáng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
