INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_27_18', 'en-b2-27', NULL, 'comprehensive_test', 'reading', NULL, 'People who snore regularly may benefit from medical advice, particularly if their breathing stops briefly during sleep.', 'Dựa vào câu trên, từ “snore” có nghĩa phù hợp nhất là gì?', '["chống lại; chiến đấu; ngăn chặn","lông cừu; bộ lông cừu","ngáy; ngáy ngủ","đường chân trời"]'::jsonb, 2, 'snore: ngáy; ngáy ngủ; tiếng ngáy. Dịch cả câu: Những người thường xuyên ngáy có thể cần sự tư vấn y tế, đặc biệt là khi nhịp thở của họ bị ngắt quãng ngắn trong khi ngủ.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_27_19', 'en-b2-27', NULL, 'comprehensive_test', 'reading', NULL, 'Students need sufficient time to digest complex information before applying it to unfamiliar problems.', 'Dựa vào câu trên, từ “digest” có nghĩa phù hợp nhất là gì?', '["mí mắt; mi mắt","dụng cụ cắt; máy cắt","tiêu hóa","chiến thuật; thủ thuật; mưu lược (một hành động cụ thể nhằm đạt được mục tiêu)"]'::jsonb, 2, 'digest: tiêu hóa; hiểu; lĩnh hội; ngấm; bản tóm tắt; tập san văn/tài liệu. Dịch cả câu: Học sinh cần có đủ thời gian để lĩnh hội các thông tin phức tạp trước khi áp dụng chúng vào các vấn đề chưa quen thuộc.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_27_20', 'en-b2-27', NULL, 'comprehensive_test', 'reading', NULL, 'A balanced plant-based diet can provide sufficient protein when it includes varied sources such as beans and nuts.', 'Dựa vào câu trên, từ “protein” có nghĩa phù hợp nhất là gì?', '["phần cốt lõi, trung tâm, quan trọng nhất; lõi (trái cây)","chất đạm; protein","bằng gốm; làm bằng sứ","vỏ bánh mì; lớp vỏ bánh"]'::jsonb, 1, 'protein: chất đạm; protein. Dịch cả câu: Một chế độ ăn thuần thực vật cân bằng có thể cung cấp đủ lượng protein khi bao gồm các nguồn thực phẩm đa dạng như đậu và các loại hạt.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_27_21', 'en-b2-27', NULL, 'comprehensive_test', 'reading', NULL, 'A public hearing allows residents to express concerns before major construction projects receive official approval.', 'Dựa vào câu trên, từ “hearing” có nghĩa phù hợp nhất là gì?', '["thính giác; khả năng nghe","ngai vàng; vương tọa","chứng chuột rút; cơn đau thắt cơ","nhà phê bình; nhà bình luận"]'::jsonb, 0, 'hearing: thính giác; khả năng nghe; phiên điều trần; buổi xét xử. Dịch cả câu: Một phiên điều trần công khai cho phép cư dân bày tỏ những mối lo ngại trước khi các dự án xây dựng lớn nhận được phê duyệt chính thức.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
