INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-28', 'en', 'Bài 28: Sức khỏe & Cơ thể (3) - CEFR B2', 'CEFR B2', 'B2 · Sức khỏe', '25 từ vựng Tiếng Anh CEFR B2 chủ đề sức khỏe & cơ thể kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4028, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nutrition', 'en-b2-28', 'nutrition', '/nuˈtrɪʃən/', 'B2', 'sự dinh dưỡng; quá trình cung cấp dưỡng chất; dinh dưỡng học', 'n.', 'nutritional (adj.), nutritious (adj.), nutritionist (n.), nutrient (n.)', 'Đồng nghĩa: nourishment', 'nutrition không đếm được; nutrient chỉ các chất dinh dưỡng cụ thể.', 'Good nutrition helps children grow and stay active.', NULL, 'Dinh dưỡng tốt giúp trẻ em phát triển và luôn năng động.', '{"wordId":"nutrition","ukIpa":"/njuˈtrɪʃən/","usIpa":"/nuˈtrɪʃən/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"the process of obtaining and using food for health","vi":"sự dinh dưỡng; quá trình cung cấp dưỡng chất"},{"pos":"n.","en":"the study of how food affects health and growth","vi":"dinh dưỡng học"}],"examples":[{"en":"Good nutrition helps children grow and stay active.","vi":"Dinh dưỡng tốt giúp trẻ em phát triển và luôn năng động.","audioKind":"ex"},{"en":"Schools should teach nutrition so that young people can make informed choices about their daily diets.","vi":"Nhà trường nên giảng dạy về dinh dưỡng để giới trẻ có thể đưa ra những lựa chọn sáng suốt về chế độ ăn uống hàng ngày của mình.","audioKind":"ex2"}],"collocations":[{"en":"good nutrition","vi":"dinh dưỡng tốt"},{"en":"adequate nutrition","vi":"dinh dưỡng đầy đủ"},{"en":"nutrition education","vi":"giáo dục dinh dưỡng"}],"wordFamily":["nutritional (adj.)","nutritious (adj.)","nutritionist (n.)","nutrient (n.)"],"synonyms":["nourishment"],"antonyms":[],"tipVi":"nutrition không đếm được; nutrient chỉ các chất dinh dưỡng cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_color-blind', 'en-b2-28', 'color-blind', '/ˈkʌlər blaɪnd/', 'B2', 'mắc chứng mù màu; không phân biệt được màu sắc', 'adj.', 'color blindness (n.)', NULL, 'Tiếng Anh-Anh thường viết là colour-blind; người bị mù màu không nhất thiết là hoàn toàn không thấy màu nào.', 'My color-blind uncle sometimes confuses red apples with green ones.', NULL, 'Người chú bị mù màu của tôi đôi khi nhầm lẫn giữa táo đỏ và táo xanh.', '{"wordId":"color-blind","ukIpa":"/ˈkʌlə blaɪnd/","usIpa":"/ˈkʌlər blaɪnd/","cefr":"B2","topic":"health","senses":[{"pos":"adj.","en":"unable to distinguish some colours from others","vi":"mắc chứng mù màu; không phân biệt được màu sắc"}],"examples":[{"en":"My color-blind uncle sometimes confuses red apples with green ones.","vi":"Người chú bị mù màu của tôi đôi khi nhầm lẫn giữa táo đỏ và táo xanh.","audioKind":"ex"},{"en":"Designers should use distinct shapes alongside colours to make public information accessible to color-blind users.","vi":"Các nhà thiết kế nên sử dụng các hình khối khác biệt đi kèm với màu sắc để người mù màu cũng có thể tiếp cận được thông tin công cộng.","audioKind":"ex2"}],"collocations":[{"en":"red-green color-blind","vi":"mù màu đỏ-lục"},{"en":"color-blind users","vi":"người dùng bị mù màu"}],"wordFamily":["color blindness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tiếng Anh-Anh thường viết là colour-blind; người bị mù màu không nhất thiết là hoàn toàn không thấy màu nào.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spit', 'en-b2-28', 'spit', '/spɪt/', 'B2', 'khạc nhổ; nhổ ra; nước bọt; nước miếng', 'v.', 'spitting (n.)', NULL, 'Quá khứ và quá phân từ Anh-Anh thường dùng spat, Anh-Mỹ cũng dùng spit.', 'He spat the bitter seed into a tissue.', NULL, 'Anh ấy nhổ hạt đắng vào một tờ khăn giấy.', '{"wordId":"spit","ukIpa":"/spɪt/","usIpa":"/spɪt/","cefr":"B2","topic":"health","senses":[{"pos":"v.","en":"To force saliva or something else out of your mouth.","vi":"khạc nhổ; nhổ ra"},{"pos":"n.","en":"The liquid produced naturally inside your mouth.","vi":"nước bọt; nước miếng"}],"examples":[{"en":"He spat the bitter seed into a tissue.","vi":"Anh ấy nhổ hạt đắng vào một tờ khăn giấy.","audioKind":"ex"},{"en":"Public health campaigns discourage people from spitting in shared spaces because this behaviour can contribute to disease transmission.","vi":"Các chiến dịch y tế cộng đồng khuyên mọi người không nên khạc nhổ bừa bãi ở nơi công cộng vì hành vi này có thể làm lây lan dịch bệnh.","audioKind":"ex2"}],"collocations":[{"en":"spit out","vi":"nhổ ra"},{"en":"spit into a tissue","vi":"nhổ vào khăn giấy"},{"en":"spit it out","vi":"nói ra hết đi; thành khẩn khai báo"}],"wordFamily":["spitting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Quá khứ và quá phân từ Anh-Anh thường dùng spat, Anh-Mỹ cũng dùng spit.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_kidney', 'en-b2-28', 'kidney', '/ˈkɪdni/', 'B2', 'thận', 'n.', NULL, NULL, 'kidney là danh từ đếm được; tính từ y khoa renal có nghĩa là "thuộc về thận".', 'The doctor checked his kidneys during a routine examination.', NULL, 'Bác sĩ đã kiểm tra thận của anh ấy trong một buổi khám sức khỏe định kỳ.', '{"wordId":"kidney","ukIpa":"/ˈkɪdni/","usIpa":"/ˈkɪdni/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"Either of two organs that filter blood and produce urine.","vi":"thận"}],"examples":[{"en":"The doctor checked his kidneys during a routine examination.","vi":"Bác sĩ đã kiểm tra thận của anh ấy trong một buổi khám sức khỏe định kỳ.","audioKind":"ex"},{"en":"Public health campaigns should explain how managing blood pressure can help prevent kidney disease.","vi":"Các chiến dịch y tế công cộng nên giải thích cách quản lý huyết áp có thể giúp ngăn ngừa bệnh thận.","audioKind":"ex2"}],"collocations":[{"en":"kidney disease","vi":"bệnh thận"},{"en":"kidney function","vi":"chức năng thận"},{"en":"kidney stone","vi":"sỏi thận"},{"en":"kidney transplant","vi":"ghép thận"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"kidney là danh từ đếm được; tính từ y khoa renal có nghĩa là \"thuộc về thận\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vision', 'en-b2-28', 'vision', '/ˈvɪʒən/', 'B2', 'thị lực; tầm nhìn; tầm nhìn xa; viễn kiến; ảo ảnh', 'n.', 'visual (adj.), visualise (v.), visionary (adj.)', 'Đồng nghĩa: sight, eyesight', 'Khi chỉ thị lực thì thường không đếm được; khi chỉ tầm nhìn cụ thể thì dùng a vision.', 'My new glasses have made my vision much clearer.', NULL, 'Cặp kính mới của tôi giúp thị lực rõ hơn rất nhiều.', '{"wordId":"vision","ukIpa":"/ˈvɪʒən/","usIpa":"/ˈvɪʒən/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"the ability to see","vi":"thị lực; tầm nhìn"},{"pos":"n.","en":"an imagined future or the ability to plan for it","vi":"tầm nhìn xa; viễn kiến"},{"pos":"n.","en":"an image experienced as real but not physically present","vi":"ảo ảnh"}],"examples":[{"en":"My new glasses have made my vision much clearer.","vi":"Cặp kính mới của tôi giúp thị lực rõ hơn rất nhiều.","audioKind":"ex"},{"en":"Urban planners need a clear vision of how expanding cities can remain both liveable and environmentally sustainable.","vi":"Các nhà quy hoạch đô thị cần có tầm nhìn rõ ràng về cách các thành phố đang mở rộng có thể vừa đáng sống vừa bền vững về mặt môi trường.","audioKind":"ex2"}],"collocations":[{"en":"blurred vision","vi":"thị lực suy giảm"},{"en":"peripheral vision","vi":"thị giác ngoại biên"},{"en":"a clear vision","vi":"một tầm nhìn rõ ràng"},{"en":"a vision for the future","vi":"tầm nhìn cho tương lai"}],"wordFamily":["visual (adj.)","visualise (v.)","visionary (adj.)"],"synonyms":["sight","eyesight"],"antonyms":[],"tipVi":"Khi chỉ thị lực thì thường không đếm được; khi chỉ tầm nhìn cụ thể thì dùng a vision.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lung', 'en-b2-28', 'lung', '/lʌŋ/', 'B2', 'lá phổi; phổi', 'n.', NULL, NULL, 'Dùng lung cho một lá phổi đơn lẻ; khi nói về cả hai lá phổi hoặc hệ hô hấp nói chung thường dùng số nhiều lungs.', 'The doctor listened to my lungs through a stethoscope.', NULL, 'Bác sĩ đã nghe phổi của tôi bằng ống nghe.', '{"wordId":"lung","ukIpa":"/lʌŋ/","usIpa":"/lʌŋ/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"Either of the two chest organs used for breathing.","vi":"lá phổi; phổi"}],"examples":[{"en":"The doctor listened to my lungs through a stethoscope.","vi":"Bác sĩ đã nghe phổi của tôi bằng ống nghe.","audioKind":"ex"},{"en":"Long periods of exposure to polluted air can damage the lungs and increase the risk of respiratory disease.","vi":"Việc tiếp xúc lâu dài với không khí ô nhiễm có thể làm tổn thương phổi và làm gia tăng nguy cơ mắc các bệnh về đường hô hấp.","audioKind":"ex2"}],"collocations":[{"en":"lung disease","vi":"bệnh phổi"},{"en":"lung capacity","vi":"dung tích phổi"},{"en":"lung cancer","vi":"ung thư phổi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dùng lung cho một lá phổi đơn lẻ; khi nói về cả hai lá phổi hoặc hệ hô hấp nói chung thường dùng số nhiều lungs.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pregnancy', 'en-b2-28', 'pregnancy', '/ˈpreɡnənsi/', 'B2', 'sự mang thai; thai kỳ', 'n.', 'pregnant (adj.)', NULL, '"during pregnancy" có nghĩa là trong thời kỳ mang thai; tính từ của nó là "pregnant".', 'She enjoyed gentle walks throughout her pregnancy last year.', NULL, 'Năm ngoái, cô ấy thích đi bộ nhẹ nhàng trong suốt thai kỳ của mình.', '{"wordId":"pregnancy","ukIpa":"/ˈpreɡnənsi/","usIpa":"/ˈpreɡnənsi/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"The condition or period of carrying a developing baby.","vi":"sự mang thai; thai kỳ"}],"examples":[{"en":"She enjoyed gentle walks throughout her pregnancy last year.","vi":"Năm ngoái, cô ấy thích đi bộ nhẹ nhàng trong suốt thai kỳ của mình.","audioKind":"ex"},{"en":"Access to reliable healthcare during pregnancy improves health outcomes for both mothers and their babies.","vi":"Việc tiếp cận dịch vụ chăm sóc sức khỏe đáng tin cậy trong thai kỳ giúp cải thiện kết quả sức khỏe cho cả mẹ và bé.","audioKind":"ex2"}],"collocations":[{"en":"during pregnancy","vi":"trong thời kỳ mang thai"},{"en":"early pregnancy","vi":"giai đoạn đầu thai kỳ"},{"en":"pregnancy test","vi":"xét nghiệm thai kỳ"}],"wordFamily":["pregnant (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"\"during pregnancy\" có nghĩa là trong thời kỳ mang thai; tính từ của nó là \"pregnant\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vaccinate', 'en-b2-28', 'vaccinate', '/ˈvæksɪneɪt/', 'B2', 'tiêm phòng; tiêm chủng vaccine', 'v.', 'vaccine (n.), vaccination (n.)', 'Đồng nghĩa: immunise, inoculate', 'Sử dụng cấu trúc vaccinate someone against để chỉ việc tiêm phòng chống lại một căn bệnh cụ thể.', 'The vet will vaccinate our puppy during today''s appointment.', NULL, 'Bác sĩ thú y sẽ tiêm phòng cho chú chó nhỏ của chúng tôi trong lịch hẹn hôm nay.', '{"wordId":"vaccinate","ukIpa":"/ˈvæksɪneɪt/","usIpa":"/ˈvæksɪneɪt/","cefr":"B2","topic":"health","senses":[{"pos":"v.","en":"To give a vaccine that helps protect against a disease.","vi":"tiêm phòng; tiêm chủng vaccine"}],"examples":[{"en":"The vet will vaccinate our puppy during today''s appointment.","vi":"Bác sĩ thú y sẽ tiêm phòng cho chú chó nhỏ của chúng tôi trong lịch hẹn hôm nay.","audioKind":"ex"},{"en":"Public health programmes aim to vaccinate vulnerable populations and reduce the spread of infectious diseases.","vi":"Các chương trình y tế cộng đồng hướng đến mục tiêu tiêm chủng cho các nhóm dân cư dễ bị tổn thương và hạn chế sự lây lan của các bệnh truyền nhiễm.","audioKind":"ex2"}],"collocations":[{"en":"vaccinate against measles","vi":"tiêm phòng sởi"},{"en":"vaccinate children","vi":"tiêm chủng cho trẻ em"},{"en":"get vaccinated","vi":"tiêm vaccine"}],"wordFamily":["vaccine (n.)","vaccination (n.)"],"synonyms":["immunise","inoculate"],"antonyms":[],"tipVi":"Sử dụng cấu trúc vaccinate someone against để chỉ việc tiêm phòng chống lại một căn bệnh cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_infectious', 'en-b2-28', 'infectious', '/ɪnˈfekʃəs/', 'B2', 'có tính truyền nhiễm; dễ lây lan; có sức lan tỏa; dễ lây sang người khác', 'adj.', 'infect (v.), infection (n.), infectiousness (n.)', 'Đồng nghĩa: contagious · Trái nghĩa: non-infectious', 'infectious chỉ tính chất dễ lây bệnh; infected chỉ việc đã bị nhiễm bệnh.', 'His infectious laugh soon had everyone at the table smiling.', NULL, 'Tiếng cười rộn ràng đầy sức lan tỏa của anh ấy nhanh chóng khiến mọi người quanh bàn bật cười.', '{"wordId":"infectious","ukIpa":"/ɪnˈfekʃəs/","usIpa":"/ɪnˈfekʃəs/","cefr":"B2","topic":"health","senses":[{"pos":"adj.","en":"able to spread disease between people or organisms","vi":"có tính truyền nhiễm; dễ lây lan"},{"pos":"adj.","en":"causing others to share the same feeling or behaviour","vi":"có sức lan tỏa; dễ lây sang người khác"}],"examples":[{"en":"His infectious laugh soon had everyone at the table smiling.","vi":"Tiếng cười rộn ràng đầy sức lan tỏa của anh ấy nhanh chóng khiến mọi người quanh bàn bật cười.","audioKind":"ex"},{"en":"Improved sanitation and access to clean water are essential for preventing infectious diseases in densely populated communities.","vi":"Cải thiện hệ thống vệ sinh và khả năng tiếp cận nước sạch là điều cốt lõi để phòng ngừa các bệnh truyền nhiễm ở những cộng đồng dân cư đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"infectious disease","vi":"bệnh truyền nhiễm"},{"en":"highly infectious","vi":"có tính lây truyền rất cao"},{"en":"infectious enthusiasm","vi":"sự nhiệt huyết có sức lan tỏa"},{"en":"infectious laughter","vi":"tiếng cười rộn ràng lây lan"}],"wordFamily":["infect (v.)","infection (n.)","infectiousness (n.)"],"synonyms":["contagious"],"antonyms":["non-infectious"],"tipVi":"infectious chỉ tính chất dễ lây bệnh; infected chỉ việc đã bị nhiễm bệnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hazard', 'en-b2-28', 'hazard', '/ˈhæzərd/', 'B2', 'mối nguy hiểm; hiểm họa; liều lĩnh đưa ra; phỏng đoán', 'n.', 'hazardous (adj.)', 'Đồng nghĩa: danger, risk', 'Danh từ chỉ nguồn gốc gây nguy hiểm; động từ thường gặp trong cấu trúc hazard a guess.', 'That loose cable is a hazard near the stairs.', NULL, 'Đường dây điện lỏng lẻo đó là một mối nguy hiểm ở gần cầu thang.', '{"wordId":"hazard","ukIpa":"/ˈhæzəd/","usIpa":"/ˈhæzərd/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"Something that could cause harm, damage, or an accident.","vi":"mối nguy hiểm; hiểm họa"},{"pos":"v.","en":"To suggest something despite uncertainty about whether it is correct.","vi":"liều lĩnh đưa ra; phỏng đoán"}],"examples":[{"en":"That loose cable is a hazard near the stairs.","vi":"Đường dây điện lỏng lẻo đó là một mối nguy hiểm ở gần cầu thang.","audioKind":"ex"},{"en":"Poorly stored industrial chemicals pose a serious health hazard to workers and residents in nearby communities.","vi":"Hóa chất công nghiệp được bảo quản kém gây ra mối đe dọa nghiêm trọng về sức khỏe cho công nhân và cư dân ở các cộng đồng lân cận.","audioKind":"ex2"}],"collocations":[{"en":"health hazard","vi":"mối nguy hiểm cho sức khỏe"},{"en":"fire hazard","vi":"nguy cơ hỏa hoạn"},{"en":"pose a hazard","vi":"gây ra mối nguy hiểm"},{"en":"hazard a guess","vi":"đoán mò; đưa ra phỏng đoán"}],"wordFamily":["hazardous (adj.)"],"synonyms":["danger","risk"],"antonyms":[],"tipVi":"Danh từ chỉ nguồn gốc gây nguy hiểm; động từ thường gặp trong cấu trúc hazard a guess.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_meditation', 'en-b2-28', 'meditation', '/ˌmedɪˈteɪʃən/', 'B2', 'sự thiền định; tĩnh tâm; sự trầm ngâm; sự suy ngẫm sâu sắc', 'n.', 'meditate (v.), meditative (adj.)', NULL, 'Cụm từ meditation chỉ việc thiền nói chung thường là không đếm được; meditation on có thể dùng để chỉ sự suy ngẫm sâu sắc về một vấn đề nào đó.', 'Ten minutes of meditation helps me relax before bed.', NULL, 'Mười phút thiền định giúp tôi thư giãn trước khi đi ngủ.', '{"wordId":"meditation","ukIpa":"/ˌmedɪˈteɪʃən/","usIpa":"/ˌmedɪˈteɪʃən/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"The practice of focusing attention to calm and train the mind.","vi":"sự thiền định; tĩnh tâm"},{"pos":"n.","en":"Deep, careful thought about a particular subject.","vi":"sự trầm ngâm; sự suy ngẫm sâu sắc"}],"examples":[{"en":"Ten minutes of meditation helps me relax before bed.","vi":"Mười phút thiền định giúp tôi thư giãn trước khi đi ngủ.","audioKind":"ex"},{"en":"Some schools offer meditation sessions to help students manage stress and improve their ability to concentrate.","vi":"Một số trường học tổ chức các buổi thiền định nhằm giúp học sinh giảm bớt căng thẳng và nâng cao khả năng tập trung.","audioKind":"ex2"}],"collocations":[{"en":"practise meditation","vi":"thực hành thiền định"},{"en":"mindfulness meditation","vi":"thiền chánh niệm"},{"en":"meditation session","vi":"buổi thiền định"},{"en":"deep meditation","vi":"sự trầm ngâm sâu sắc"}],"wordFamily":["meditate (v.)","meditative (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ meditation chỉ việc thiền nói chung thường là không đếm được; meditation on có thể dùng để chỉ sự suy ngẫm sâu sắc về một vấn đề nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tobacco', 'en-b2-28', 'tobacco', '/təˈbækoʊ/', 'B2', 'thuốc lá; cây thuốc lá', 'n.', 'tobacconist (n.)', NULL, 'Thông thường là danh từ không đếm được; một chiếc lá thuốc lá dùng "a tobacco leaf".', 'The farmer hung tobacco leaves inside a wooden barn.', NULL, 'Người nông dân treo những lá thuốc lá bên trong một cái kho bằng gỗ.', '{"wordId":"tobacco","ukIpa":"/təˈbækəʊ/","usIpa":"/təˈbækoʊ/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"A plant whose dried leaves are used to make smoking products","vi":"thuốc lá; cây thuốc lá"}],"examples":[{"en":"The farmer hung tobacco leaves inside a wooden barn.","vi":"Người nông dân treo những lá thuốc lá bên trong một cái kho bằng gỗ.","audioKind":"ex"},{"en":"Higher taxes on tobacco products can discourage smoking and generate revenue for public health programmes.","vi":"Việc đánh thuế cao hơn đối với các sản phẩm thuốc lá có thể hạn chế hút thuốc và tạo nguồn thu cho các chương trình y tế công cộng.","audioKind":"ex2"}],"collocations":[{"en":"tobacco products","vi":"sản phẩm thuốc lá"},{"en":"tobacco industry","vi":"ngành công nghiệp thuốc lá"},{"en":"tobacco farming","vi":"việc trồng thuốc lá"},{"en":"tobacco control","vi":"phòng chống thuốc lá"}],"wordFamily":["tobacconist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thông thường là danh từ không đếm được; một chiếc lá thuốc lá dùng \"a tobacco leaf\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vomit', 'en-b2-28', 'vomit', '/ˈvɑːmɪt/', 'B2', 'nôn; mửa; chất nôn', 'v.', 'vomiting (n.)', 'Đồng nghĩa: throw up, be sick', 'Danh từ chỉ chất nôn; quá trình nôn mửa thường dùng danh từ vomiting.', 'The rough boat ride made several passengers vomit.', NULL, 'Chuyến đi thuyền tròng cồng khiến vài hành khách bị nôn mửa.', '{"wordId":"vomit","ukIpa":"/ˈvɒmɪt/","usIpa":"/ˈvɑːmɪt/","cefr":"B2","topic":"health","senses":[{"pos":"v.","en":"To bring food or liquid from the stomach through the mouth.","vi":"nôn; mửa"},{"pos":"n.","en":"Food or liquid brought up from the stomach.","vi":"chất nôn"}],"examples":[{"en":"The rough boat ride made several passengers vomit.","vi":"Chuyến đi thuyền tròng cồng khiến vài hành khách bị nôn mửa.","audioKind":"ex"},{"en":"Patients who vomit repeatedly may become dehydrated and should seek medical advice if symptoms persist.","vi":"Những bệnh nhân nôn mửa liên tục có thể bị mất nước và nên đi khám bác sĩ nếu các triệu chứng vẫn tiếp diễn.","audioKind":"ex2"}],"collocations":[{"en":"start to vomit","vi":"bắt đầu nôn"},{"en":"vomit repeatedly","vi":"nôn mửa liên tục"},{"en":"nausea and vomiting","vi":"buồn nôn và nôn"}],"wordFamily":["vomiting (n.)"],"synonyms":["throw up","be sick"],"antonyms":[],"tipVi":"Danh từ chỉ chất nôn; quá trình nôn mửa thường dùng danh từ vomiting.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_diagnose', 'en-b2-28', 'diagnose', '/ˌdaɪəɡˈnoʊs/', 'B2', 'chẩn đoán (bệnh); xác định nguyên nhân; tìm ra bản chất (của vấn đề)', 'v.', 'diagnosis (n.), diagnostic (adj.)', 'Đồng nghĩa: identify', 'Khi muốn diễn đạt việc chẩn đoán ai đó mắc bệnh gì, hãy dùng cấu trúc diagnose someone with [tên bệnh].', 'The doctor diagnosed asthma after checking my breathing.', NULL, 'Bác sĩ đã chẩn đoán tôi mắc bệnh hen suyễn sau khi kiểm tra nhịp thở.', '{"wordId":"diagnose","ukIpa":"/ˈdaɪəɡnəʊz/","usIpa":"/ˌdaɪəɡˈnoʊs/","cefr":"B2","topic":"health","senses":[{"pos":"v.","en":"to identify an illness by examining symptoms and test results","vi":"chẩn đoán (bệnh)"},{"pos":"v.","en":"to identify the cause or nature of a problem","vi":"xác định nguyên nhân; tìm ra bản chất (của vấn đề)"}],"examples":[{"en":"The doctor diagnosed asthma after checking my breathing.","vi":"Bác sĩ đã chẩn đoán tôi mắc bệnh hen suyễn sau khi kiểm tra nhịp thở.","audioKind":"ex"},{"en":"New screening technologies can help doctors diagnose certain diseases before serious symptoms appear.","vi":"Các công nghệ sàng lọc tân tiến có thể hỗ trợ bác sĩ chẩn đoán ra một số căn bệnh trước cả khi những triệu chứng rõ rệt xuất hiện.","audioKind":"ex2"}],"collocations":[{"en":"diagnose a disease","vi":"chẩn đoán bệnh"},{"en":"be diagnosed with","vi":"được chẩn đoán mắc bệnh"},{"en":"diagnose a fault","vi":"xác định lỗi kỹ thuật"}],"wordFamily":["diagnosis (n.)","diagnostic (adj.)"],"synonyms":["identify"],"antonyms":[],"tipVi":"Khi muốn diễn đạt việc chẩn đoán ai đó mắc bệnh gì, hãy dùng cấu trúc diagnose someone with [tên bệnh].","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_moderate', 'en-b2-28', 'moderate', '/ˈmɑːdərət/', 'B2', 'vừa phải; trung bình; điều độ; ôn hòa; không cực đoan; làm dịu đi; tiết chế; giảm bớt sự gay gắt', 'adj.', 'moderately (adv.), moderation (n.), moderator (n.)', 'Đồng nghĩa: reasonable · Trái nghĩa: extreme, excessive', 'Tính từ có đuôi phát âm là /ət/, còn động từ có đuôi phát âm là /eɪt/.', 'A moderate amount of exercise helps me sleep better.', NULL, 'Tập thể dục điều độ giúp tôi ngủ ngon hơn.', '{"wordId":"moderate","ukIpa":"/ˈmɒdərət/","usIpa":"/ˈmɑːdərət/","cefr":"B2","topic":"health","senses":[{"pos":"adj.","en":"Neither very large nor very small in amount or degree","vi":"vừa phải; trung bình; điều độ"},{"pos":"adj.","en":"Avoiding extreme political views or actions","vi":"ôn hòa; không cực đoan"},{"pos":"v.","en":"To become or make something less extreme or intense","vi":"làm dịu đi; tiết chế; giảm bớt sự gay gắt"}],"examples":[{"en":"A moderate amount of exercise helps me sleep better.","vi":"Tập thể dục điều độ giúp tôi ngủ ngon hơn.","audioKind":"ex"},{"en":"Moderate increases in housing density could accommodate urban growth without placing excessive pressure on local infrastructure.","vi":"Việc gia tăng mật độ nhà ở một cách vừa phải có thể đáp ứng sự phát triển của đô thị mà không gây áp lực quá lớn lên cơ sở hạ tầng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"moderate exercise","vi":"tập thể dục vừa phải"},{"en":"moderate growth","vi":"tăng trưởng ôn hòa"},{"en":"moderate views","vi":"quan điểm ôn hòa"},{"en":"moderate your expectations","vi":"điều chỉnh kỳ vọng của bạn"}],"wordFamily":["moderately (adv.)","moderation (n.)","moderator (n.)"],"synonyms":["reasonable"],"antonyms":["extreme","excessive"],"tipVi":"Tính từ có đuôi phát âm là /ət/, còn động từ có đuôi phát âm là /eɪt/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thirst', 'en-b2-28', 'thirst', '/θɝːst/', 'B2', 'cơn khát; sự khao khát; niềm khao khát', 'n.', 'thirsty (adj.), thirstily (adv.)', NULL, 'Cảm giác khát thường dùng tính từ "thirsty"; cụm "thirst for" diễn tả niềm khát khao điều gì đó.', 'Cool water relieved my thirst after the long walk.', NULL, 'Nước mát đã làm dịu cơn khát của tôi sau chuyến đi bộ dài.', '{"wordId":"thirst","ukIpa":"/θɜːst/","usIpa":"/θɝːst/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"The feeling of needing or wanting something to drink.","vi":"cơn khát"},{"pos":"n.","en":"A strong desire to have or learn something.","vi":"sự khao khát; niềm khao khát"}],"examples":[{"en":"Cool water relieved my thirst after the long walk.","vi":"Nước mát đã làm dịu cơn khát của tôi sau chuyến đi bộ dài.","audioKind":"ex"},{"en":"Schools should nurture children''s thirst for knowledge rather than focus exclusively on examination results.","vi":"Nhà trường nên nuôi dưỡng niềm khao khát tri thức của trẻ em thay vì chỉ tập trung hoàn toàn vào kết quả thi cử.","audioKind":"ex2"}],"collocations":[{"en":"quench your thirst","vi":"giải khát"},{"en":"a thirst for knowledge","vi":"niềm khát khao tri thức"},{"en":"a thirst for adventure","vi":"niềm khát khao phiêu lưu"}],"wordFamily":["thirsty (adj.)","thirstily (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Cảm giác khát thường dùng tính từ \"thirsty\"; cụm \"thirst for\" diễn tả niềm khát khao điều gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_infant', 'en-b2-28', 'infant', '/ˈɪnfənt/', 'B2', 'trẻ sơ sinh; đứa bé; thuộc về trẻ sơ sinh; ở giai đoạn đầu phát triển', 'n.', 'infancy (n.)', 'Đồng nghĩa: baby', 'Mang tính trang trọng hơn từ baby; cụm infant mortality chuyên chỉ tỷ lệ tử vong của trẻ sơ sinh.', 'The infant slept peacefully in her father''s arms.', NULL, 'Đứa trẻ sơ sinh ngủ say sưa trong vòng tay của bố.', '{"wordId":"infant","ukIpa":"/ˈɪnfənt/","usIpa":"/ˈɪnfənt/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"a baby or very young child","vi":"trẻ sơ sinh; đứa bé"},{"pos":"adj.","en":"relating to babies or an early stage of development","vi":"thuộc về trẻ sơ sinh; ở giai đoạn đầu phát triển"}],"examples":[{"en":"The infant slept peacefully in her father''s arms.","vi":"Đứa trẻ sơ sinh ngủ say sưa trong vòng tay của bố.","audioKind":"ex"},{"en":"Access to clean water and basic healthcare is essential for reducing infant mortality in disadvantaged communities.","vi":"Việc tiếp cận nguồn nước sạch và dịch vụ chăm sóc sức khỏe cơ bản là điều cốt yếu để làm giảm tỷ lệ tử vong ở trẻ sơ sinh tại các cộng đồng kém may mắn.","audioKind":"ex2"}],"collocations":[{"en":"infant care","vi":"chăm sóc trẻ sơ sinh"},{"en":"infant mortality","vi":"tỷ lệ tử vong ở trẻ sơ sinh"},{"en":"infant formula","vi":"sữa công thức cho trẻ"},{"en":"an infant industry","vi":"ngành công nghiệp non trẻ"}],"wordFamily":["infancy (n.)"],"synonyms":["baby"],"antonyms":[],"tipVi":"Mang tính trang trọng hơn từ baby; cụm infant mortality chuyên chỉ tỷ lệ tử vong của trẻ sơ sinh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vaccine', 'en-b2-28', 'vaccine', '/vækˈsiːn/', 'B2', 'vắc-xin; chất kích thích hệ miễn dịch chống lại bệnh tật', 'n.', 'vaccinate (v.), vaccination (n.)', NULL, 'Kết hợp với ''a vaccine against'' khi nói về vắc-xin phòng bệnh nào đó.', 'The nurse explained how the vaccine helps protect against illness.', NULL, 'Y tá giải thích cách vắc-xin giúp bảo vệ cơ thể chống lại bệnh tật.', '{"wordId":"vaccine","ukIpa":"/ˈvæksiːn/","usIpa":"/vækˈsiːn/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"a substance that trains the immune system to resist disease","vi":"vắc-xin; chất kích thích hệ miễn dịch chống lại bệnh tật"}],"examples":[{"en":"The nurse explained how the vaccine helps protect against illness.","vi":"Y tá giải thích cách vắc-xin giúp bảo vệ cơ thể chống lại bệnh tật.","audioKind":"ex"},{"en":"Ensuring fair access to vaccines is essential for protecting vulnerable populations and reducing the spread of infectious diseases.","vi":"Đảm bảo khả năng tiếp cận vắc-xin công bằng là điều cốt yếu để bảo vệ các nhóm dân cư dễ bị tổn thương và giảm thiểu sự lây lan của các bệnh truyền nhiễm.","audioKind":"ex2"}],"collocations":[{"en":"develop a vaccine","vi":"entwickeln / phát triển vắc-xin"},{"en":"receive a vaccine","vi":"tiêm vắc-xin"},{"en":"vaccine safety","vi":"an toàn vắc-xin"},{"en":"vaccine development","vi":"nghiên cứu và phát triển vắc-xin"}],"wordFamily":["vaccinate (v.)","vaccination (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Kết hợp với ''a vaccine against'' khi nói về vắc-xin phòng bệnh nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_skincare', 'en-b2-28', 'skincare', '/ˈskɪnker/', 'B2', 'chăm sóc da; việc dưỡng da', 'n.', 'skin (n.)', NULL, 'Thông thường không đếm được; cũng có thể viết thành hai từ skin care.', 'My daily skincare routine includes washing gently and applying moisturiser.', NULL, 'Quy trình chăm sóc da hàng ngày của tôi bao gồm việc rửa mặt nhẹ nhàng và thoa kem dưỡng ẩm.', '{"wordId":"skincare","ukIpa":"/ˈskɪnkeə/","usIpa":"/ˈskɪnker/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"the practice of keeping skin clean, healthy, and protected","vi":"chăm sóc da; việc dưỡng da"}],"examples":[{"en":"My daily skincare routine includes washing gently and applying moisturiser.","vi":"Quy trình chăm sóc da hàng ngày của tôi bao gồm việc rửa mặt nhẹ nhàng và thoa kem dưỡng ẩm.","audioKind":"ex"},{"en":"Public health campaigns can promote sensible skincare habits, including regular sun protection and avoiding irritating products.","vi":"Các chiến dịch y tế công cộng có thể thúc đẩy thói quen chăm sóc da hợp lý, bao gồm việc chống nắng thường xuyên và tránh các sản phẩm gây kích ứng.","audioKind":"ex2"}],"collocations":[{"en":"skincare routine","vi":"quy trình chăm sóc da hàng ngày"},{"en":"skincare products","vi":"sản phẩm chăm sóc da"},{"en":"daily skincare","vi":"chăm sóc da hàng ngày"}],"wordFamily":["skin (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thông thường không đếm được; cũng có thể viết thành hai từ skin care.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deadly', 'en-b2-28', 'deadly', '/ˈdedli/', 'B2', 'gây chết người; chí mạng; cực kỳ; hoàn toàn', 'adj.', 'dead (adj.), death (n.), die (v.)', 'Đồng nghĩa: lethal, fatal · Trái nghĩa: harmless', 'Mặc dù có tận cùng bằng -ly, deadly thường đóng vai trò là tính từ với nghĩa gây chết người.', 'These pretty mushrooms can be deadly if you eat them.', NULL, 'Những cây nấm đẹp mắt này có thể gây chết người nếu bạn ăn phải chúng.', '{"wordId":"deadly","ukIpa":"/ˈdedli/","usIpa":"/ˈdedli/","cefr":"B2","topic":"health","senses":[{"pos":"adj.","en":"Causing death or likely to cause death.","vi":"gây chết người; chí mạng"},{"pos":"adv.","en":"Extremely or completely, especially with certain adjectives.","vi":"cực kỳ; hoàn toàn"}],"examples":[{"en":"These pretty mushrooms can be deadly if you eat them.","vi":"Những cây nấm đẹp mắt này có thể gây chết người nếu bạn ăn phải chúng.","audioKind":"ex"},{"en":"Improved access to clean drinking water can prevent deadly diseases in communities with inadequate sanitation.","vi":"Khả năng tiếp cận nước uống sạch tốt hơn có thể ngăn ngừa các căn bệnh gây chết người ở những cộng đồng có cơ sở vệ sinh kém.","audioKind":"ex2"}],"collocations":[{"en":"a deadly disease","vi":"một căn bệnh gây chết người"},{"en":"a deadly poison","vi":"một chất độc chí mạng"},{"en":"deadly serious","vi":"vô cùng nghiêm túc"},{"en":"deadly dull","vi":"cực kỳ nhàm chán"}],"wordFamily":["dead (adj.)","death (n.)","die (v.)"],"synonyms":["lethal","fatal"],"antonyms":["harmless"],"tipVi":"Mặc dù có tận cùng bằng -ly, deadly thường đóng vai trò là tính từ với nghĩa gây chết người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cosmetic', 'en-b2-28', 'cosmetic', '/kɑːzˈmetɪk/', 'B2', 'thuộc về thẩm mỹ; để làm đẹp; mang tính bề ngoài; chỉ để che đậy vấn đề; mỹ phẩm', 'adj.', 'cosmetics (n.), cosmetically (adv.)', NULL, 'Khi dùng danh từ chỉ "mỹ phẩm", người ta thường dùng số nhiều cosmetics.', 'This shop sells cosmetic products alongside soap and shampoo.', NULL, 'Cửa hàng này bán các sản phẩm làm đẹp bên cạnh xà phòng và dầu gội.', '{"wordId":"cosmetic","ukIpa":"/kɒzˈmetɪk/","usIpa":"/kɑːzˈmetɪk/","cefr":"B2","topic":"health","senses":[{"pos":"adj.","en":"intended to improve or change physical appearance","vi":"thuộc về thẩm mỹ; để làm đẹp"},{"pos":"adj.","en":"changing appearances without solving underlying problems","vi":"mang tính bề ngoài; chỉ để che đậy vấn đề"},{"pos":"n.","en":"a product used to improve or change physical appearance","vi":"mỹ phẩm"}],"examples":[{"en":"This shop sells cosmetic products alongside soap and shampoo.","vi":"Cửa hàng này bán các sản phẩm làm đẹp bên cạnh xà phòng và dầu gội.","audioKind":"ex"},{"en":"Critics argue that cosmetic changes to school buildings cannot address deeper problems such as overcrowded classrooms.","vi":"Các nhà phê bình lập luận rằng những thay đổi mang tính bề ngoài đối với các tòa nhà trường học không thể giải quyết được các vấn đề sâu xa hơn như lớp học quá tải.","audioKind":"ex2"}],"collocations":[{"en":"cosmetic products","vi":"sản phẩm mỹ phẩm"},{"en":"cosmetic surgery","vi":"phẫu thuật thẩm mỹ"},{"en":"cosmetic changes","vi":"những thay đổi mang tính hình thức"}],"wordFamily":["cosmetics (n.)","cosmetically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi dùng danh từ chỉ \"mỹ phẩm\", người ta thường dùng số nhiều cosmetics.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shiver', 'en-b2-28', 'shiver', '/ˈʃɪvər/', 'B2', 'run rẩy; đánh cầm cập; cảm giác rùng mình; cơn ớn lạnh', 'v.', 'shivery (adj.)', 'Đồng nghĩa: tremble, shake', 'Thường dùng shiver with cold hoặc fear để diễn tả nguyên nhân gây run.', 'I shivered while waiting outside in my thin jacket.', NULL, 'Tôi run lẩy bẩy khi đứng đợi ở bên ngoài với chiếc áo khoác mỏng manh.', '{"wordId":"shiver","ukIpa":"/ˈʃɪvə/","usIpa":"/ˈʃɪvər/","cefr":"B2","topic":"health","senses":[{"pos":"v.","en":"To shake slightly because of cold, fear, or excitement","vi":"run rẩy; đánh cầm cập"},{"pos":"n.","en":"A brief shaking movement caused by cold or strong emotion","vi":"cảm giác rùng mình; cơn ớn lạnh"}],"examples":[{"en":"I shivered while waiting outside in my thin jacket.","vi":"Tôi run lẩy bẩy khi đứng đợi ở bên ngoài với chiếc áo khoác mỏng manh.","audioKind":"ex"},{"en":"People may shiver when exposed to low temperatures, as muscle movements help the body generate heat.","vi":"Con người có thể run lên khi tiếp xúc với nhiệt độ thấp, vì các chuyển động cơ bắp giúp cơ thể sinh nhiệt.","audioKind":"ex2"}],"collocations":[{"en":"shiver with cold","vi":"rét run"},{"en":"shiver with fear","vi":"sợ run cả người"},{"en":"a shiver down your spine","vi":"lạnh sống lưng; ớn lạnh dọc sống lưng"}],"wordFamily":["shivery (adj.)"],"synonyms":["tremble","shake"],"antonyms":[],"tipVi":"Thường dùng shiver with cold hoặc fear để diễn tả nguyên nhân gây run.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_immune', 'en-b2-28', 'immune', '/ɪˈmjuːn/', 'B2', 'có miễn dịch; kháng bệnh; thuộc hệ miễn dịch; không bị ảnh hưởng; được miễn trừ', 'adj.', 'immunity (n.), immunise (v.), immunisation (n.)', NULL, 'immune to mang nghĩa không bị ảnh hưởng; immune from thường mang nghĩa được miễn trừ pháp lý.', 'The vet explained that vaccination would make our puppy immune.', NULL, 'Bác sĩ thú y giải thích rằng việc tiêm phòng sẽ giúp chú cún nhà chúng ta có khả năng miễn dịch.', '{"wordId":"immune","ukIpa":"/ɪˈmjuːn/","usIpa":"/ɪˈmjuːn/","cefr":"B2","topic":"health","senses":[{"pos":"adj.","en":"Protected against a particular disease.","vi":"có miễn dịch; kháng bệnh"},{"pos":"adj.","en":"Relating to the body''s defence against disease.","vi":"thuộc hệ miễn dịch"},{"pos":"adj.","en":"Not affected by something, or protected from a legal obligation.","vi":"không bị ảnh hưởng; được miễn trừ"}],"examples":[{"en":"The vet explained that vaccination would make our puppy immune.","vi":"Bác sĩ thú y giải thích rằng việc tiêm phòng sẽ giúp chú cún nhà chúng ta có khả năng miễn dịch.","audioKind":"ex"},{"en":"Although technology creates new opportunities, no industry is completely immune to the effects of economic change.","vi":"Mặc dù công nghệ mang lại những cơ hội mới, không có ngành công nghiệp nào hoàn toàn miễn nhiễm trước những tác động của biến động kinh tế.","audioKind":"ex2"}],"collocations":[{"en":"immune to infection","vi":"có khả năng miễn dịch với nhiễm trùng"},{"en":"the immune system","vi":"hệ miễn dịch"},{"en":"an immune response","vi":"phản ứng miễn dịch"},{"en":"immune from prosecution","vi":"được miễn truy tố"}],"wordFamily":["immunity (n.)","immunise (v.)","immunisation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"immune to mang nghĩa không bị ảnh hưởng; immune from thường mang nghĩa được miễn trừ pháp lý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_carbohydrates', 'en-b2-28', 'carbohydrates', '/ˌkɑːrboʊˈhaɪdreɪts/', 'B2', 'chất bột đường; cacbohydrat', 'n.', 'carbohydrate (n.)', NULL, 'Đây là dạng số nhiều của carbohydrate; cả đường và tinh bột đều thuộc nhóm này.', 'Rice and potatoes provide carbohydrates that fuel your daily activities.', NULL, 'Cơm và khoai tây cung cấp chất bột đường giúp cung cấp năng lượng cho các hoạt động hàng ngày của bạn.', '{"wordId":"carbohydrates","ukIpa":"/ˌkɑːbəʊˈhaɪdreɪts/","usIpa":"/ˌkɑːrboʊˈhaɪdreɪts/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"Nutrients such as sugars and starches that provide the body energy","vi":"chất bột đường; cacbohydrat"}],"examples":[{"en":"Rice and potatoes provide carbohydrates that fuel your daily activities.","vi":"Cơm và khoai tây cung cấp chất bột đường giúp cung cấp năng lượng cho các hoạt động hàng ngày của bạn.","audioKind":"ex"},{"en":"A balanced diet includes carbohydrates, proteins, and fats in proportions suited to individual nutritional needs.","vi":"Một chế độ ăn uống cân bằng bao gồm chất bột đường, chất đạm và chất béo với tỷ lệ phù hợp với nhu cầu dinh dưỡng của từng cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"complex carbohydrates","vi":"cacbohydrat phức hợp"},{"en":"refined carbohydrates","vi":"cacbohydrat tinh chế"},{"en":"rich in carbohydrates","vi":"giàu chất bột đường"}],"wordFamily":["carbohydrate (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Đây là dạng số nhiều của carbohydrate; cả đường và tinh bột đều thuộc nhóm này.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recovery', 'en-b2-28', 'recovery', '/rɪˈkʌvəri/', 'B2', 'sự bình phục; sự phục hồi; sự lấy lại; sự thu hồi', 'n.', 'recover (v.), recoverable (adj.)', NULL, 'Quá trình bình phục thường dùng cụm make a recovery; recover là động từ.', 'Her recovery was slow, but she could walk again.', NULL, 'Cô ấy bình phục chậm, nhưng cuối cùng cũng có thể đi lại được.', '{"wordId":"recovery","ukIpa":"/rɪˈkʌvəri/","usIpa":"/rɪˈkʌvəri/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"A return to health or a normal condition.","vi":"sự bình phục; sự phục hồi"},{"pos":"n.","en":"The process of getting something lost or stolen back.","vi":"sự lấy lại; sự thu hồi"}],"examples":[{"en":"Her recovery was slow, but she could walk again.","vi":"Cô ấy bình phục chậm, nhưng cuối cùng cũng có thể đi lại được.","audioKind":"ex"},{"en":"Economic recovery depends partly on restoring consumer confidence and supporting small businesses through difficult periods.","vi":"Sự phục hồi kinh tế phụ thuộc một phần vào việc khôi phục niềm tin của người tiêu dùng và hỗ trợ các doanh nghiệp nhỏ vượt qua giai đoạn khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"make a full recovery","vi":"bình phục hoàn toàn"},{"en":"economic recovery","vi":"phục hồi kinh tế"},{"en":"data recovery","vi":"khôi phục dữ liệu"}],"wordFamily":["recover (v.)","recoverable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Quá trình bình phục thường dùng cụm make a recovery; recover là động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_28_1', 'en-b2-28', 'Cách dùng “meditation” (n.) — sự thiền định; tĩnh tâm', 'practise meditation  ·  mindfulness meditation  ·  meditation session', 'Cụm từ meditation chỉ việc thiền nói chung thường là không đếm được; meditation on có thể dùng để chỉ sự suy ngẫm sâu sắc về một vấn đề nào đó.', 'Họ từ (Word Family): meditate (v.), meditative (adj.)', '[{"hanzi":"Ten minutes of meditation helps me relax before bed.","pinyin":"","meaning":"Mười phút thiền định giúp tôi thư giãn trước khi đi ngủ."},{"hanzi":"Some schools offer meditation sessions to help students manage stress and improve their ability to concentrate.","pinyin":"","meaning":"Một số trường học tổ chức các buổi thiền định nhằm giúp học sinh giảm bớt căng thẳng và nâng cao khả năng tập trung."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_28_2', 'en-b2-28', 'Cách dùng “lung” (n.) — lá phổi; phổi', 'lung disease  ·  lung capacity  ·  lung cancer', 'Dùng lung cho một lá phổi đơn lẻ; khi nói về cả hai lá phổi hoặc hệ hô hấp nói chung thường dùng số nhiều lungs.', NULL, '[{"hanzi":"The doctor listened to my lungs through a stethoscope.","pinyin":"","meaning":"Bác sĩ đã nghe phổi của tôi bằng ống nghe."},{"hanzi":"Long periods of exposure to polluted air can damage the lungs and increase the risk of respiratory disease.","pinyin":"","meaning":"Việc tiếp xúc lâu dài với không khí ô nhiễm có thể làm tổn thương phổi và làm gia tăng nguy cơ mắc các bệnh về đường hô hấp."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_28_3', 'en-b2-28', 'Cách dùng “color-blind” (adj.) — mắc chứng mù màu; không phân biệt được màu sắc', 'red-green color-blind  ·  color-blind users', 'Tiếng Anh-Anh thường viết là colour-blind; người bị mù màu không nhất thiết là hoàn toàn không thấy màu nào.', 'Họ từ (Word Family): color blindness (n.)', '[{"hanzi":"My color-blind uncle sometimes confuses red apples with green ones.","pinyin":"","meaning":"Người chú bị mù màu của tôi đôi khi nhầm lẫn giữa táo đỏ và táo xanh."},{"hanzi":"Designers should use distinct shapes alongside colours to make public information accessible to color-blind users.","pinyin":"","meaning":"Các nhà thiết kế nên sử dụng các hình khối khác biệt đi kèm với màu sắc để người mù màu cũng có thể tiếp cận được thông tin công cộng."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_28_4', 'en-b2-28', 'Cách dùng “diagnose” (v.) — chẩn đoán (bệnh)', 'diagnose a disease  ·  be diagnosed with  ·  diagnose a fault', 'Khi muốn diễn đạt việc chẩn đoán ai đó mắc bệnh gì, hãy dùng cấu trúc diagnose someone with [tên bệnh].', 'Họ từ (Word Family): diagnosis (n.), diagnostic (adj.) | Đồng nghĩa: identify', '[{"hanzi":"The doctor diagnosed asthma after checking my breathing.","pinyin":"","meaning":"Bác sĩ đã chẩn đoán tôi mắc bệnh hen suyễn sau khi kiểm tra nhịp thở."},{"hanzi":"New screening technologies can help doctors diagnose certain diseases before serious symptoms appear.","pinyin":"","meaning":"Các công nghệ sàng lọc tân tiến có thể hỗ trợ bác sĩ chẩn đoán ra một số căn bệnh trước cả khi những triệu chứng rõ rệt xuất hiện."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_28_1', 'en-b2-28', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_28_1_1', 'ten_b2_28_1', 'nutrition', 'Good nutrition helps children grow and stay active.', 'Good nutrition helps children grow and stay active.', '/nuˈtrɪʃən/', 'Dinh dưỡng tốt giúp trẻ em phát triển và luôn năng động.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_28_1_2', 'ten_b2_28_1', 'color-blind', 'My color-blind uncle sometimes confuses red apples with green ones.', 'My color-blind uncle sometimes confuses red apples with green ones.', '/ˈkʌlər blaɪnd/', 'Người chú bị mù màu của tôi đôi khi nhầm lẫn giữa táo đỏ và táo xanh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_28_1_3', 'ten_b2_28_1', 'spit', 'He spat the bitter seed into a tissue.', 'He spat the bitter seed into a tissue.', '/spɪt/', 'Anh ấy nhổ hạt đắng vào một tờ khăn giấy.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_28_1_4', 'ten_b2_28_1', 'kidney', 'The doctor checked his kidneys during a routine examination.', 'The doctor checked his kidneys during a routine examination.', '/ˈkɪdni/', 'Bác sĩ đã kiểm tra thận của anh ấy trong một buổi khám sức khỏe định kỳ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_28_1_5', 'ten_b2_28_1', 'vision', 'My new glasses have made my vision much clearer.', 'My new glasses have made my vision much clearer.', '/ˈvɪʒən/', 'Cặp kính mới của tôi giúp thị lực rõ hơn rất nhiều.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_28_1_6', 'ten_b2_28_1', 'lung', 'The doctor listened to my lungs through a stethoscope.', 'The doctor listened to my lungs through a stethoscope.', '/lʌŋ/', 'Bác sĩ đã nghe phổi của tôi bằng ống nghe.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_28_1_7', 'ten_b2_28_1', 'pregnancy', 'She enjoyed gentle walks throughout her pregnancy last year.', 'She enjoyed gentle walks throughout her pregnancy last year.', '/ˈpreɡnənsi/', 'Năm ngoái, cô ấy thích đi bộ nhẹ nhàng trong suốt thai kỳ của mình.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_28_1_8', 'ten_b2_28_1', 'vaccinate', 'The vet will vaccinate our puppy during today''s appointment.', 'The vet will vaccinate our puppy during today''s appointment.', '/ˈvæksɪneɪt/', 'Bác sĩ thú y sẽ tiêm phòng cho chú chó nhỏ của chúng tôi trong lịch hẹn hôm nay.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_28_1_1', 'en-b2-28', 'ten_b2_28_1', 'listening', 'listening', 'Good nutrition helps children grow and stay active.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Dinh dưỡng tốt giúp trẻ em phát triển và luôn năng động.","Mười phút thiền định giúp tôi thư giãn trước khi đi ngủ.","Quy trình chăm sóc da hàng ngày của tôi bao gồm việc rửa mặt nhẹ nhàng và thoa kem dưỡng ẩm.","Người nông dân treo những lá thuốc lá bên trong một cái kho bằng gỗ."]'::jsonb, 0, 'Good nutrition helps children grow and stay active. → Dinh dưỡng tốt giúp trẻ em phát triển và luôn năng động.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_28_1_2', 'en-b2-28', 'ten_b2_28_1', 'listening', 'listening', 'My color-blind uncle sometimes confuses red apples with green ones.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Người chú bị mù màu của tôi đôi khi nhầm lẫn giữa táo đỏ và táo xanh.","Bác sĩ đã chẩn đoán tôi mắc bệnh hen suyễn sau khi kiểm tra nhịp thở.","Chuyến đi thuyền tròng cồng khiến vài hành khách bị nôn mửa.","Cô ấy bình phục chậm, nhưng cuối cùng cũng có thể đi lại được."]'::jsonb, 0, 'My color-blind uncle sometimes confuses red apples with green ones. → Người chú bị mù màu của tôi đôi khi nhầm lẫn giữa táo đỏ và táo xanh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_28_1_3', 'en-b2-28', 'ten_b2_28_1', 'listening', 'listening', 'He spat the bitter seed into a tissue.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Anh ấy nhổ hạt đắng vào một tờ khăn giấy.","Đứa trẻ sơ sinh ngủ say sưa trong vòng tay của bố.","Đường dây điện lỏng lẻo đó là một mối nguy hiểm ở gần cầu thang.","Cơm và khoai tây cung cấp chất bột đường giúp cung cấp năng lượng cho các hoạt động hàng ngày của bạn."]'::jsonb, 0, 'He spat the bitter seed into a tissue. → Anh ấy nhổ hạt đắng vào một tờ khăn giấy.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_28_2', 'en-b2-28', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_28_2_1', 'ten_b2_28_2', 'nutrition', 'Schools should teach nutrition so that young people can make informed choices about their daily diets.', 'Schools should teach nutrition so that young people can make informed choices about their daily diets.', '/nuˈtrɪʃən/', 'Nhà trường nên giảng dạy về dinh dưỡng để giới trẻ có thể đưa ra những lựa chọn sáng suốt về chế độ ăn uống hàng ngày của mình.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_28_2_2', 'ten_b2_28_2', 'color-blind', 'Designers should use distinct shapes alongside colours to make public information accessible to color-blind users.', 'Designers should use distinct shapes alongside colours to make public information accessible to color-blind users.', '/ˈkʌlər blaɪnd/', 'Các nhà thiết kế nên sử dụng các hình khối khác biệt đi kèm với màu sắc để người mù màu cũng có thể tiếp cận được thông tin công cộng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_28_2_3', 'ten_b2_28_2', 'spit', 'Public health campaigns discourage people from spitting in shared spaces because this behaviour can contribute to disease transmission.', 'Public health campaigns discourage people from spitting in shared spaces because this behaviour can contribute to disease transmission.', '/spɪt/', 'Các chiến dịch y tế cộng đồng khuyên mọi người không nên khạc nhổ bừa bãi ở nơi công cộng vì hành vi này có thể làm lây lan dịch bệnh.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_28_2_4', 'ten_b2_28_2', 'kidney', 'Public health campaigns should explain how managing blood pressure can help prevent kidney disease.', 'Public health campaigns should explain how managing blood pressure can help prevent kidney disease.', '/ˈkɪdni/', 'Các chiến dịch y tế công cộng nên giải thích cách quản lý huyết áp có thể giúp ngăn ngừa bệnh thận.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_28_2_5', 'ten_b2_28_2', 'vision', 'Urban planners need a clear vision of how expanding cities can remain both liveable and environmentally sustainable.', 'Urban planners need a clear vision of how expanding cities can remain both liveable and environmentally sustainable.', '/ˈvɪʒən/', 'Các nhà quy hoạch đô thị cần có tầm nhìn rõ ràng về cách các thành phố đang mở rộng có thể vừa đáng sống vừa bền vững về mặt môi trường.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_28_2_6', 'ten_b2_28_2', 'lung', 'Long periods of exposure to polluted air can damage the lungs and increase the risk of respiratory disease.', 'Long periods of exposure to polluted air can damage the lungs and increase the risk of respiratory disease.', '/lʌŋ/', 'Việc tiếp xúc lâu dài với không khí ô nhiễm có thể làm tổn thương phổi và làm gia tăng nguy cơ mắc các bệnh về đường hô hấp.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_28_2_1', 'en-b2-28', 'ten_b2_28_2', 'listening', 'listening', 'Schools should teach nutrition so that young people can make informed choices about their daily diets.', NULL, 'Trong câu vừa nghe, từ “nutrition” mang nghĩa nào sau đây?', '["dầu mỡ; mỡ bôi trơn","thận","sự dinh dưỡng; quá trình cung cấp dưỡng chất","nhà khảo cổ học"]'::jsonb, 2, '“nutrition” (/nuˈtrɪʃən/): sự dinh dưỡng; quá trình cung cấp dưỡng chất. Câu đầy đủ: Schools should teach nutrition so that young people can make informed choices about their daily diets.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_28_2_2', 'en-b2-28', 'ten_b2_28_2', 'listening', 'listening', 'Designers should use distinct shapes alongside colours to make public information accessible to color-blind users.', NULL, 'Trong câu vừa nghe, từ “color-blind” mang nghĩa nào sau đây?', '["lối đi (giữa các hàng ghế hoặc kệ hàng)","tương đối; so sánh ra","thương nhân; tiểu thương; nhà giao dịch","mắc chứng mù màu; không phân biệt được màu sắc"]'::jsonb, 3, '“color-blind” (/ˈkʌlər blaɪnd/): mắc chứng mù màu; không phân biệt được màu sắc. Câu đầy đủ: Designers should use distinct shapes alongside colours to make public information accessible to color-blind users.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
