INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_28_2', 'en-b2-28', 'My color-blind uncle sometimes confuses red apples with green ones', 'Người chú bị mù màu của tôi đôi khi nhầm lẫn giữa táo đỏ và táo xanh.', 'color-blind /ˈkʌlər blaɪnd/', '["sometimes","My","uncle","apples","with","green","ones","color-blind","confuses","red"]'::jsonb, NULL, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
