INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_28_2', 'en-b2-28', NULL, 'comprehensive_test', 'listening', 'My color-blind uncle sometimes confuses red apples with green ones.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Quy trình chăm sóc da hàng ngày của tôi bao gồm việc rửa mặt nhẹ nhàng và thoa kem dưỡng ẩm.","Đường dây điện lỏng lẻo đó là một mối nguy hiểm ở gần cầu thang.","Người chú bị mù màu của tôi đôi khi nhầm lẫn giữa táo đỏ và táo xanh.","Cặp kính mới của tôi giúp thị lực rõ hơn rất nhiều."]'::jsonb, 2, 'My color-blind uncle sometimes confuses red apples with green ones. → Người chú bị mù màu của tôi đôi khi nhầm lẫn giữa táo đỏ và táo xanh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
