INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_28_4', 'en-b2-28', NULL, 'comprehensive_test', 'listening', 'The doctor checked his kidneys during a routine examination.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Mười phút thiền định giúp tôi thư giãn trước khi đi ngủ.","Người nông dân treo những lá thuốc lá bên trong một cái kho bằng gỗ.","Bác sĩ đã kiểm tra thận của anh ấy trong một buổi khám sức khỏe định kỳ.","Bác sĩ thú y giải thích rằng việc tiêm phòng sẽ giúp chú cún nhà chúng ta có khả năng miễn dịch."]'::jsonb, 2, 'The doctor checked his kidneys during a routine examination. → Bác sĩ đã kiểm tra thận của anh ấy trong một buổi khám sức khỏe định kỳ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_28_5', 'en-b2-28', NULL, 'comprehensive_test', 'listening', 'vision', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cảng biển; thành phố cảng","thị lực; tầm nhìn","lạc quan; mang tính hy vọng","sự tham dự; sự có mặt"]'::jsonb, 1, 'vision (/ˈvɪʒən/) → thị lực; tầm nhìn; tầm nhìn xa; viễn kiến; ảo ảnh', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_28_6', 'en-b2-28', NULL, 'comprehensive_test', 'listening', 'The doctor listened to my lungs through a stethoscope.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cửa hàng này bán các sản phẩm làm đẹp bên cạnh xà phòng và dầu gội.","Tôi run lẩy bẩy khi đứng đợi ở bên ngoài với chiếc áo khoác mỏng manh.","Bác sĩ đã nghe phổi của tôi bằng ống nghe.","Y tá giải thích cách vắc-xin giúp bảo vệ cơ thể chống lại bệnh tật."]'::jsonb, 2, 'The doctor listened to my lungs through a stethoscope. → Bác sĩ đã nghe phổi của tôi bằng ống nghe.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
