INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_28_18', 'en-b2-28', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should teach nutrition so that young people can make informed choices about their daily diets.', 'Dựa vào câu trên, từ “nutrition” có nghĩa phù hợp nhất là gì?', '["sự dinh dưỡng; quá trình cung cấp dưỡng chất","dùng một lần; vứt đi sau khi dùng","khiêm tốn","ngân sách; khoản kinh phí"]'::jsonb, 0, 'nutrition: sự dinh dưỡng; quá trình cung cấp dưỡng chất; dinh dưỡng học. Dịch cả câu: Nhà trường nên giảng dạy về dinh dưỡng để giới trẻ có thể đưa ra những lựa chọn sáng suốt về chế độ ăn uống hàng ngày của mình.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_28_19', 'en-b2-28', NULL, 'comprehensive_test', 'reading', NULL, 'Designers should use distinct shapes alongside colours to make public information accessible to color-blind users.', 'Dựa vào câu trên, từ “color-blind” có nghĩa phù hợp nhất là gì?', '["thu được; tìm thấy; nhận được","tinh thể","sân hiên; ban công lớn; sân thượng","mắc chứng mù màu; không phân biệt được màu sắc"]'::jsonb, 3, 'color-blind: mắc chứng mù màu; không phân biệt được màu sắc. Dịch cả câu: Các nhà thiết kế nên sử dụng các hình khối khác biệt đi kèm với màu sắc để người mù màu cũng có thể tiếp cận được thông tin công cộng.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_28_20', 'en-b2-28', NULL, 'comprehensive_test', 'reading', NULL, 'Public health campaigns discourage people from spitting in shared spaces because this behaviour can contribute to disease transmission.', 'Dựa vào câu trên, từ “spit” có nghĩa phù hợp nhất là gì?', '["thực tế; thực sự","khạc nhổ; nhổ ra","sao Kim","nỗi cô đơn; sự cô độc"]'::jsonb, 1, 'spit: khạc nhổ; nhổ ra; nước bọt; nước miếng. Dịch cả câu: Các chiến dịch y tế cộng đồng khuyên mọi người không nên khạc nhổ bừa bãi ở nơi công cộng vì hành vi này có thể làm lây lan dịch bệnh.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_28_21', 'en-b2-28', NULL, 'comprehensive_test', 'reading', NULL, 'Public health campaigns should explain how managing blood pressure can help prevent kidney disease.', 'Dựa vào câu trên, từ “kidney” có nghĩa phù hợp nhất là gì?', '["cáp; dây cáp (mang điện hoặc tín hiệu điện tử)","hạt cườm; hạt chuỗi","thận","phụ lục (sách, tài liệu)"]'::jsonb, 2, 'kidney: thận. Dịch cả câu: Các chiến dịch y tế công cộng nên giải thích cách quản lý huyết áp có thể giúp ngăn ngừa bệnh thận.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_28_22', 'en-b2-28', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “có miễn dịch; kháng bệnh”', '["immune","wax","knowledgeable","truly"]'::jsonb, 0, 'có miễn dịch; kháng bệnh → immune (/ɪˈmjuːn/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_28_23', 'en-b2-28', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “chất bột đường; cacbohydrat”', '["handful","carbohydrates","gallon","demonstration"]'::jsonb, 1, 'chất bột đường; cacbohydrat → carbohydrates (/ˌkɑːrboʊˈhaɪdreɪts/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_28_24', 'en-b2-28', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự bình phục; sự phục hồi”', '["stool","concept","recovery","delicate"]'::jsonb, 2, 'sự bình phục; sự phục hồi → recovery (/rɪˈkʌvəri/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-29', 'en', 'Bài 29: Sức khỏe & Cơ thể (4) - CEFR B2', 'CEFR B2', 'B2 · Sức khỏe', '25 từ vựng Tiếng Anh CEFR B2 chủ đề sức khỏe & cơ thể kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4029, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exhaustion', 'en-b2-29', 'exhaustion', '/ɪɡˈzɔːstʃən/', 'B2', 'sự kiệt sức; tình trạng mệt mỏi cực độ về thể chất hoặc tinh thần; sự cạn kiệt; việc sử dụng hết hoàn toàn nguồn cung hoặc nguồn lực có sẵn', 'n.', 'exhaust (v.), exhausted (adj.), exhausting (adj.), exhaustive (adj.)', 'Đồng nghĩa: fatigue, depletion', 'exhaustion không có nghĩa là chi tiết; tính từ exhaustive mới mang nghĩa là thấu đáo, toàn diện.', 'After the long hike, he fell asleep from exhaustion.', NULL, 'Sau chuyến đi bộ đường dài kéo dài, anh ấy đã ngủ thiếp đi vì kiệt sức.', '{"wordId":"exhaustion","ukIpa":"/ɪɡˈzɔːstʃən/","usIpa":"/ɪɡˈzɔːstʃən/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"A state of extreme physical or mental tiredness.","vi":"sự kiệt sức; tình trạng mệt mỏi cực độ về thể chất hoặc tinh thần"},{"pos":"n.","en":"The complete use of an available supply or resource.","vi":"sự cạn kiệt; việc sử dụng hết hoàn toàn nguồn cung hoặc nguồn lực có sẵn"}],"examples":[{"en":"After the long hike, he fell asleep from exhaustion.","vi":"Sau chuyến đi bộ đường dài kéo dài, anh ấy đã ngủ thiếp đi vì kiệt sức.","audioKind":"ex"},{"en":"Persistent exhaustion among healthcare workers can reduce the quality of patient care and increase staff turnover.","vi":"Tình trạng kiệt sức kéo dài ở nhân viên y tế có thể làm giảm chất lượng chăm sóc bệnh nhân và gia tăng tỷ lệ nhân viên nghỉ việc.","audioKind":"ex2"}],"collocations":[{"en":"physical exhaustion","vi":"kiệt sức về thể chất"},{"en":"mental exhaustion","vi":"kiệt quệ tinh thần"},{"en":"the exhaustion of resources","vi":"sự cạn kiệt tài nguyên"}],"wordFamily":["exhaust (v.)","exhausted (adj.)","exhausting (adj.)","exhaustive (adj.)"],"synonyms":["fatigue","depletion"],"antonyms":[],"tipVi":"exhaustion không có nghĩa là chi tiết; tính từ exhaustive mới mang nghĩa là thấu đáo, toàn diện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_calorie', 'en-b2-29', 'calorie', '/ˈkæləri/', 'B2', 'lượng calo; đơn vị đo năng lượng (trong thực phẩm)', 'n.', 'caloric (adj.)', NULL, 'Trong ngữ cảnh thực phẩm, calorie thường chỉ kilocalories (kcal); trong vật lý là calo.', 'This walking app estimates how many calories I burn.', NULL, 'Ứng dụng đi bộ này ước tính lượng calo tôi đã đốt cháy.', '{"wordId":"calorie","ukIpa":"/ˈkæləri/","usIpa":"/ˈkæləri/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"A unit measuring energy, especially energy in food.","vi":"lượng calo; đơn vị đo năng lượng (trong thực phẩm)"}],"examples":[{"en":"This walking app estimates how many calories I burn.","vi":"Ứng dụng đi bộ này ước tính lượng calo tôi đã đốt cháy.","audioKind":"ex"},{"en":"Although calorie information can guide food choices, a balanced diet also depends on nutrient quality.","vi":"Mặc dù thông tin về lượng calo có thể định hướng việc lựa chọn thực phẩm, chế độ ăn uống cân bằng còn phụ thuộc vào chất lượng dinh dưỡng.","audioKind":"ex2"}],"collocations":[{"en":"burn calories","vi":"đốt cháy calo"},{"en":"calorie intake","vi":"lượng calo nạp vào"},{"en":"low in calories","vi":"ít calo"},{"en":"calorie content","vi":"hàm lượng calo"}],"wordFamily":["caloric (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong ngữ cảnh thực phẩm, calorie thường chỉ kilocalories (kcal); trong vật lý là calo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prevention', 'en-b2-29', 'prevention', '/prɪˈvenʃən/', 'B2', 'sự phòng ngừa; sự ngăn chặn', 'n.', 'prevent (v.), preventive (adj.), preventable (adj.)', NULL, 'Thường là danh từ không đếm được; động từ đi kèm là prevent sb from doing.', 'Regular handwashing is a simple method of infection prevention.', NULL, 'Rửa tay thường xuyên là một biện pháp đơn giản để phòng ngừa lây nhiễm.', '{"wordId":"prevention","ukIpa":"/prɪˈvenʃən/","usIpa":"/prɪˈvenʃən/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"Action taken to stop something unwanted from happening.","vi":"sự phòng ngừa; sự ngăn chặn"}],"examples":[{"en":"Regular handwashing is a simple method of infection prevention.","vi":"Rửa tay thường xuyên là một biện pháp đơn giản để phòng ngừa lây nhiễm.","audioKind":"ex"},{"en":"Investment in disease prevention can reduce pressure on hospitals and improve public health over the long term.","vi":"Đầu tư vào việc phòng ngừa dịch bệnh có thể làm giảm áp lực cho các bệnh viện và cải thiện sức khỏe cộng đồng về lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"disease prevention","vi":"phòng ngừa dịch bệnh"},{"en":"crime prevention","vi":"phòng chống tội phạm"},{"en":"fire prevention","vi":"phòng cháy"}],"wordFamily":["prevent (v.)","preventive (adj.)","preventable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; động từ đi kèm là prevent sb from doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inject', 'en-b2-29', 'inject', '/ɪnˈdʒekt/', 'B2', 'tiêm; bơm; rót vào; truyền thêm năng lượng, tiền bạc hoặc thứ gì đó mới vào một tình huống', 'v.', 'injection (n.), injectable (adj.)', NULL, 'Thường dùng cấu trúc inject A into B: tiêm/đưa A vào B.', 'The nurse will inject the medicine into my arm.', NULL, 'Y tá sẽ tiêm thuốc vào bắp tay của tôi.', '{"wordId":"inject","ukIpa":"/ɪnˈdʒekt/","usIpa":"/ɪnˈdʒekt/","cefr":"B2","topic":"health","senses":[{"pos":"v.","en":"To put a substance into something using a needle or pressure.","vi":"tiêm; bơm"},{"pos":"v.","en":"To introduce money, energy, or something new into a situation.","vi":"rót vào; truyền thêm năng lượng, tiền bạc hoặc thứ gì đó mới vào một tình huống"}],"examples":[{"en":"The nurse will inject the medicine into my arm.","vi":"Y tá sẽ tiêm thuốc vào bắp tay của tôi.","audioKind":"ex"},{"en":"Public investment can inject new energy into declining towns by supporting local businesses and improving transport.","vi":"Đầu tư công có thể thổi luồng sinh khí mới vào các thị trấn đang suy thoái bằng cách hỗ trợ các doanh nghiệp địa phương và cải thiện giao thông.","audioKind":"ex2"}],"collocations":[{"en":"inject medicine","vi":"tiêm thuốc"},{"en":"inject funds into","vi":"rót vốn vào"},{"en":"inject new life into","vi":"thổi sức sống mới vào"}],"wordFamily":["injection (n.)","injectable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng cấu trúc inject A into B: tiêm/đưa A vào B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_treadmill', 'en-b2-29', 'treadmill', '/ˈtredmɪl/', 'B2', 'máy chạy bộ; công việc đơn điệu và bận rộn', 'n.', NULL, NULL, 'Dùng giới từ on trong cụm on a treadmill, không dùng in.', 'I walk on the treadmill when it rains outside.', NULL, 'Tôi tập trên máy chạy bộ khi bên ngoài trời mưa.', '{"wordId":"treadmill","ukIpa":"/ˈtredmɪl/","usIpa":"/ˈtredmɪl/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"An exercise machine with a moving surface for walking or running.","vi":"máy chạy bộ"},{"pos":"n.","en":"A tiring routine that seems endless and brings little satisfaction.","vi":"công việc đơn điệu và bận rộn"}],"examples":[{"en":"I walk on the treadmill when it rains outside.","vi":"Tôi tập trên máy chạy bộ khi bên ngoài trời mưa.","audioKind":"ex"},{"en":"For some employees, the treadmill of daily work leaves little time for family life or personal interests.","vi":"Đối với một số nhân viên,guồng quay công việc bận rộn hằng ngày khiến họ hầu như không có thời gian dành cho đời sống gia đình hay sở thích cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"run on a treadmill","vi":"chạy trên máy chạy bộ"},{"en":"treadmill workout","vi":"buổi tập với máy chạy bộ"},{"en":"the treadmill of daily life","vi":"guồng quay cuộc sống thường nhật"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dùng giới từ on trong cụm on a treadmill, không dùng in.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_itch', 'en-b2-29', 'itch', '/ɪtʃ/', 'B2', 'gây ngứa; bị ngứa; cảm giác ngứa; khao khát; nóng lòng muốn làm gì', 'v.', 'itchy (adj.), itchiness (n.)', NULL, 'itch là cảm giác ngứa ngáy, scratch là hành động gãi; nghĩa khao khát thường dùng cấu trúc be itching to.', 'This woollen scarf makes my neck itch all day.', NULL, 'Chiếc khăn quàng cổ bằng len này làm cổ tôi ngứa ngáy cả ngày.', '{"wordId":"itch","ukIpa":"/ɪtʃ/","usIpa":"/ɪtʃ/","cefr":"B2","topic":"health","senses":[{"pos":"v.","en":"to feel an uncomfortable sensation that makes you want to scratch","vi":"gây ngứa; bị ngứa"},{"pos":"n.","en":"an uncomfortable feeling on your skin that makes you scratch","vi":"cảm giác ngứa"},{"pos":"v.","en":"to want very much to do something","vi":"khao khát; nóng lòng muốn làm gì"}],"examples":[{"en":"This woollen scarf makes my neck itch all day.","vi":"Chiếc khăn quàng cổ bằng len này làm cổ tôi ngứa ngáy cả ngày.","audioKind":"ex"},{"en":"Some synthetic fabrics can cause sensitive skin to itch, making material choice important in clothing design.","vi":"Một số loại vải tổng hợp có thể khiến làn da nhạy cảm bị ngứa, làm cho việc lựa chọn chất liệu trong thiết kế trang phục trở nên quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"scratch an itch","vi":"gãi ngứa"},{"en":"itch to do something","vi":"nóng lòng muốn làm gì"},{"en":"itch for a chance","vi":"khát khao có cơ hội"}],"wordFamily":["itchy (adj.)","itchiness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"itch là cảm giác ngứa ngáy, scratch là hành động gãi; nghĩa khao khát thường dùng cấu trúc be itching to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vein', 'en-b2-29', 'vein', '/veɪn/', 'B2', 'tĩnh mạch; gân lá; vân quặng; mạch khoáng', 'n.', 'venous (adj.)', NULL, 'vein chỉ tĩnh mạch; artery chỉ động mạch, hai từ này không phải là từ trái nghĩa trực tiếp.', 'A blue vein was visible beneath his wrist.', NULL, 'Có thể nhìn thấy một mạch máu xanh nổi lên dưới cổ tay anh ấy.', '{"wordId":"vein","ukIpa":"/veɪn/","usIpa":"/veɪn/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"a blood vessel that carries blood towards the heart","vi":"tĩnh mạch"},{"pos":"n.","en":"a thin tube carrying water and nutrients through a leaf","vi":"gân lá"},{"pos":"n.","en":"a narrow layer of mineral within rock","vi":"vân quặng; mạch khoáng"}],"examples":[{"en":"A blue vein was visible beneath his wrist.","vi":"Có thể nhìn thấy một mạch máu xanh nổi lên dưới cổ tay anh ấy.","audioKind":"ex"},{"en":"Regular movement helps blood flow through the veins and may reduce health risks associated with prolonged sitting.","vi":"Việc vận động thường xuyên giúp máu lưu thông qua các tĩnh mạch và có thể làm giảm các nguy cơ sức khỏe liên quan đến việc ngồi lâu.","audioKind":"ex2"}],"collocations":[{"en":"varicose veins","vi":"giãn tĩnh mạch"},{"en":"leaf veins","vi":"gân lá"},{"en":"a vein of gold","vi":"mạch vàng"}],"wordFamily":["venous (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"vein chỉ tĩnh mạch; artery chỉ động mạch, hai từ này không phải là từ trái nghĩa trực tiếp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prescription', 'en-b2-29', 'prescription', '/prɪˈskrɪpʃən/', 'B2', 'đơn thuốc; thuốc theo đơn; phương pháp giải quyết; giải pháp; chỉ định bán theo đơn', 'n.', 'prescribe (v.)', NULL, 'Đơn thuốc dùng giới từ for để chỉ loại thuốc; on prescription nghĩa là phải có đơn của bác sĩ.', 'The doctor gave me a prescription for eye drops.', NULL, 'Bác sĩ đã kê cho tôi đơn thuốc nhỏ mắt.', '{"wordId":"prescription","ukIpa":"/prɪˈskrɪpʃən/","usIpa":"/prɪˈskrɪpʃən/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"A doctor''s written order for medicine, or the medicine ordered","vi":"đơn thuốc; thuốc theo đơn"},{"pos":"n.","en":"A suggested method for dealing with a problem","vi":"phương pháp giải quyết; giải pháp"},{"pos":"adj.","en":"Available only with a doctor''s written order","vi":"chỉ định bán theo đơn"}],"examples":[{"en":"The doctor gave me a prescription for eye drops.","vi":"Bác sĩ đã kê cho tôi đơn thuốc nhỏ mắt.","audioKind":"ex"},{"en":"Requiring a prescription for certain medicines can reduce misuse and protect public health.","vi":"Việc yêu cầu phải có đơn thuốc đối với một số loại dược phẩm nhất định có thể hạn chế tình trạng lạm dụng và bảo vệ sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"write a prescription","vi":"kê đơn thuốc"},{"en":"fill a prescription","vi":"lấy thuốc theo đơn"},{"en":"prescription medicine","vi":"thuốc kê đơn"},{"en":"a prescription for success","vi":"bí quyết thành công"}],"wordFamily":["prescribe (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Đơn thuốc dùng giới từ for để chỉ loại thuốc; on prescription nghĩa là phải có đơn của bác sĩ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_protective', 'en-b2-29', 'protective', '/prəˈtektɪv/', 'B2', 'có tính bảo vệ; phòng ngừa (tổn thương, hư hỏng); có ý che chở; bảo vệ (ai đó khỏi nguy hiểm)', 'adj.', 'protect (v.), protection (n.), protectively (adv.), overprotective (adj.)', NULL, 'Để diễn tả ý muốn che chở, bảo vệ ai đó, hãy dùng be protective of.', 'Wear protective gloves before handling those sharp metal pieces.', NULL, 'Hãy đeo găng tay bảo hộ trước khi cầm nắm những miếng kim loại sắc bén đó.', '{"wordId":"protective","ukIpa":"/prəˈtektɪv/","usIpa":"/prəˈtektɪv/","cefr":"B2","topic":"health","senses":[{"pos":"adj.","en":"Intended to prevent injury, damage, or other harm","vi":"có tính bảo vệ; phòng ngừa (tổn thương, hư hỏng)"},{"pos":"adj.","en":"Wanting to keep someone safe from harm or trouble","vi":"có ý che chở; bảo vệ (ai đó khỏi nguy hiểm)"}],"examples":[{"en":"Wear protective gloves before handling those sharp metal pieces.","vi":"Hãy đeo găng tay bảo hộ trước khi cầm nắm những miếng kim loại sắc bén đó.","audioKind":"ex"},{"en":"Employers should provide protective equipment and regular training to reduce injuries in dangerous workplaces.","vi":"Người sử dụng lao động nên cung cấp trang thiết bị bảo hộ và tổ chức đào tạo thường xuyên để giảm thiểu tai nạn lao động tại các nơi làm việc nguy hiểm.","audioKind":"ex2"}],"collocations":[{"en":"protective clothing","vi":"quần áo bảo hộ"},{"en":"protective equipment","vi":"trang thiết bị bảo hộ"},{"en":"protective measures","vi":"các biện pháp bảo vệ"},{"en":"protective of someone","vi":"có lòng bảo vệ ai đó"}],"wordFamily":["protect (v.)","protection (n.)","protectively (adv.)","overprotective (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Để diễn tả ý muốn che chở, bảo vệ ai đó, hãy dùng be protective of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_beverage', 'en-b2-29', 'beverage', '/ˈbevərɪdʒ/', 'B2', 'đồ uống; thức uống (như trà, nước ép, cà phê)', 'n.', NULL, 'Đồng nghĩa: drink', 'beverage mang tính trang trọng hơn, thường dùng trong ngành ẩm thực hoặc văn cảnh học thuật; trong đời sống thường dùng drink.', 'Would you like a hot beverage with your sandwich?', NULL, 'Bạn có muốn dùng một món đồ uống nóng kèm với bánh mì kẹp không?', '{"wordId":"beverage","ukIpa":"/ˈbevərɪdʒ/","usIpa":"/ˈbevərɪdʒ/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"A drink, such as tea, juice, or coffee.","vi":"đồ uống; thức uống (như trà, nước ép, cà phê)"}],"examples":[{"en":"Would you like a hot beverage with your sandwich?","vi":"Bạn có muốn dùng một món đồ uống nóng kèm với bánh mì kẹp không?","audioKind":"ex"},{"en":"Reducing the consumption of sugary beverages could help lower obesity rates among young people.","vi":"Việc giảm tiêu thụ đồ uống có đường có thể giúp hạ thấp tỷ lệ béo phì ở giới trẻ.","audioKind":"ex2"}],"collocations":[{"en":"hot beverage","vi":"đồ uống nóng"},{"en":"alcoholic beverage","vi":"đồ uống có cồn"},{"en":"sugary beverage","vi":"đồ uống có đường"},{"en":"food and beverages","vi":"thực phẩm và đồ uống"}],"wordFamily":[],"synonyms":["drink"],"antonyms":[],"tipVi":"beverage mang tính trang trọng hơn, thường dùng trong ngành ẩm thực hoặc văn cảnh học thuật; trong đời sống thường dùng drink.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_medication', 'en-b2-29', 'medication', '/ˌmedɪˈkeɪʃən/', 'B2', 'thuốc chữa bệnh; việc dùng thuốc điều trị', 'n.', 'medicate (v.), medicated (adj.)', 'Đồng nghĩa: medicine', 'Danh từ chỉ chung thuốc thường là không đếm được; có thể dùng medications khi chỉ nhiều loại thuốc khác nhau.', 'She takes her medication with breakfast every morning.', NULL, 'Cô ấy uống thuốc vào bữa sáng mỗi ngày.', '{"wordId":"medication","ukIpa":"/ˌmedɪˈkeɪʃən/","usIpa":"/ˌmedɪˈkeɪʃən/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"Medicine used to treat illness, or treatment using medicine.","vi":"thuốc chữa bệnh; việc dùng thuốc điều trị"}],"examples":[{"en":"She takes her medication with breakfast every morning.","vi":"Cô ấy uống thuốc vào bữa sáng mỗi ngày.","audioKind":"ex"},{"en":"Affordable medication is essential for improving public health, particularly in communities with limited medical services.","vi":"Thuốc có giá cả phải chăng là điều cốt yếu để cải thiện sức khỏe cộng đồng, đặc biệt là ở những cộng đồng có dịch vụ y tế hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"take medication","vi":"uống thuốc"},{"en":"prescribe medication","vi":"kê đơn thuốc"},{"en":"be on medication","vi":"đang trong quá trình điều trị bằng thuốc"}],"wordFamily":["medicate (v.)","medicated (adj.)"],"synonyms":["medicine"],"antonyms":[],"tipVi":"Danh từ chỉ chung thuốc thường là không đếm được; có thể dùng medications khi chỉ nhiều loại thuốc khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_therapy', 'en-b2-29', 'therapy', '/ˈθerəpi/', 'B2', 'liệu pháp; sự điều trị (cải thiện sức khỏe thể chất hoặc tinh thần)', 'n.', 'therapist (n.), therapeutic (adj.)', 'Đồng nghĩa: treatment', 'Khi chỉ việc điều trị nói chung thì danh từ này không đếm được; các liệu pháp cụ thể có thể dùng dạng số nhiều.', 'After her injury, regular therapy helped her walk comfortably again.', NULL, 'Sau chấn thương, các buổi trị liệu đều đặn đã giúp cô ấy đi lại thoải mái trở lại.', '{"wordId":"therapy","ukIpa":"/ˈθerəpi/","usIpa":"/ˈθerəpi/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"Treatment intended to improve physical or mental health.","vi":"liệu pháp; sự điều trị (cải thiện sức khỏe thể chất hoặc tinh thần)"}],"examples":[{"en":"After her injury, regular therapy helped her walk comfortably again.","vi":"Sau chấn thương, các buổi trị liệu đều đặn đã giúp cô ấy đi lại thoải mái trở lại.","audioKind":"ex"},{"en":"Schools that provide access to psychological therapy may better support students experiencing persistent anxiety.","vi":"Các trường học cung cấp dịch vụ trị liệu tâm lý có thể hỗ trợ tốt hơn cho học sinh đang gặp tình trạng lo âu kéo dài.","audioKind":"ex2"}],"collocations":[{"en":"speech therapy","vi":"liệu pháp ngôn ngữ"},{"en":"physical therapy","vi":"vật lý trị liệu"},{"en":"undergo therapy","vi":"trải qua điều trị"},{"en":"psychological therapy","vi":"trị liệu tâm lý"}],"wordFamily":["therapist (n.)","therapeutic (adj.)"],"synonyms":["treatment"],"antonyms":[],"tipVi":"Khi chỉ việc điều trị nói chung thì danh từ này không đếm được; các liệu pháp cụ thể có thể dùng dạng số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nursing', 'en-b2-29', 'nursing', '/ˈnɜːrsɪŋ/', 'B2', 'công tác điều dưỡng; nghề điều dưỡng; sự chăm sóc bệnh nhân', 'n.', 'nurse (n.), nurse (v.)', NULL, 'nursing khi chỉ chuyên ngành hoặc nghề điều dưỡng thường là danh từ không đếm được.', 'My sister chose nursing because she enjoys helping people.', NULL, 'Chị tôi chọn ngành điều dưỡng vì chị thích giúp đỡ mọi người.', '{"wordId":"nursing","ukIpa":"/ˈnɜːsɪŋ/","usIpa":"/ˈnɜːrsɪŋ/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"The work of caring for people who are ill or injured.","vi":"công tác điều dưỡng; nghề điều dưỡng; sự chăm sóc bệnh nhân"}],"examples":[{"en":"My sister chose nursing because she enjoys helping people.","vi":"Chị tôi chọn ngành điều dưỡng vì chị thích giúp đỡ mọi người.","audioKind":"ex"},{"en":"Investment in nursing education is essential to meet the growing healthcare needs of an ageing population.","vi":"Việc đầu tư vào giáo dục điều dưỡng là rất quan trọng để đáp ứng nhu cầu chăm sóc sức khỏe ngày càng tăng của một dân số đang già hóa.","audioKind":"ex2"}],"collocations":[{"en":"nursing care","vi":"dịch vụ chăm sóc điều dưỡng"},{"en":"a nursing home","vi":"viện dưỡng lão"},{"en":"nursing staff","vi":"đội ngũ điều dưỡng"},{"en":"a nursing degree","vi":"bằng cử nhân điều dưỡng"}],"wordFamily":["nurse (n.)","nurse (v.)"],"synonyms":[],"antonyms":[],"tipVi":"nursing khi chỉ chuyên ngành hoặc nghề điều dưỡng thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_infection', 'en-b2-29', 'infection', '/ɪnˈfekʃən/', 'B2', 'sự nhiễm trùng; bệnh truyền nhiễm', 'n.', 'infect (v.), infected (adj.), infectious (adj.)', NULL, '"infection" có thể chỉ quá trình nhiễm trùng hoặc một ca nhiễm trùng cụ thể.', 'The doctor checked my sore throat for signs of infection.', NULL, 'Bác sĩ đã kiểm tra cổ họng bị đau của tôi để xem có dấu hiệu nhiễm trùng không.', '{"wordId":"infection","ukIpa":"/ɪnˈfekʃən/","usIpa":"/ɪnˈfekʃən/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"a condition caused by harmful organisms entering the body","vi":"sự nhiễm trùng; bệnh truyền nhiễm"}],"examples":[{"en":"The doctor checked my sore throat for signs of infection.","vi":"Bác sĩ đã kiểm tra cổ họng bị đau của tôi để xem có dấu hiệu nhiễm trùng không.","audioKind":"ex"},{"en":"Improved sanitation can reduce the risk of infection, particularly in communities with limited access to clean water.","vi":"Việc cải thiện điều kiện vệ sinh có thể làm giảm nguy cơ nhiễm trùng, đặc biệt là ở những cộng đồng ít có cơ hội tiếp cận nguồn nước sạch.","audioKind":"ex2"}],"collocations":[{"en":"prevent infection","vi":"ngăn ngừa nhiễm trùng"},{"en":"risk of infection","vi":"nguy cơ nhiễm trùng"},{"en":"bacterial infection","vi":"nhiễm trùng do vi khuẩn"},{"en":"spread of infection","vi":"sự lây lan của nhiễm trùng"}],"wordFamily":["infect (v.)","infected (adj.)","infectious (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"\"infection\" có thể chỉ quá trình nhiễm trùng hoặc một ca nhiễm trùng cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vaccination', 'en-b2-29', 'vaccination', '/ˌvæksɪˈneɪʃən/', 'B2', 'tiêm chủng; việc tiêm vắc-xin', 'n.', 'vaccinate (v.), vaccine (n.), vaccinated (adj.)', 'Đồng nghĩa: immunisation', 'Việc tiêm phòng để ngăn ngừa một bệnh nào đó dùng cấu trúc vaccination against.', 'The nurse asked me to relax before my vaccination.', NULL, 'Cô y tá bảo tôi thả lỏng trước khi tiêm vắc-xin.', '{"wordId":"vaccination","ukIpa":"/ˌvæksɪˈneɪʃən/","usIpa":"/ˌvæksɪˈneɪʃən/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"Giving a vaccine to help protect someone against disease","vi":"tiêm chủng; việc tiêm vắc-xin"}],"examples":[{"en":"The nurse asked me to relax before my vaccination.","vi":"Cô y tá bảo tôi thả lỏng trước khi tiêm vắc-xin.","audioKind":"ex"},{"en":"Accessible vaccination programmes help prevent infectious diseases and reduce pressure on public healthcare services.","vi":"Các chương trình tiêm chủng dễ tiếp cận giúp ngăn ngừa các bệnh truyền nhiễm và giảm áp lực cho các dịch vụ y tế công cộng.","audioKind":"ex2"}],"collocations":[{"en":"a vaccination programme","vi":"chương trình tiêm chủng"},{"en":"vaccination against flu","vi":"tiêm vắc-xin cúm"},{"en":"vaccination coverage","vi":"tỷ lệ bao phủ tiêm chủng"}],"wordFamily":["vaccinate (v.)","vaccine (n.)","vaccinated (adj.)"],"synonyms":["immunisation"],"antonyms":[],"tipVi":"Việc tiêm phòng để ngăn ngừa một bệnh nào đó dùng cấu trúc vaccination against.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_herbal', 'en-b2-29', 'herbal', '/ˈɝːbəl/', 'B2', 'thuộc thảo mộc; làm từ thảo mộc', 'adj.', 'herb (n.), herbalist (n.)', NULL, 'Trong tiếng Anh-Anh, âm h thường được phát âm, trong khi tiếng Anh-Mỹ thường câm âm h.', 'I usually drink herbal tea before going to bed.', NULL, 'Tôi thường uống trà thảo mộc trước khi đi ngủ.', '{"wordId":"herbal","ukIpa":"/ˈhɜːbəl/","usIpa":"/ˈɝːbəl/","cefr":"B2","topic":"health","senses":[{"pos":"adj.","en":"Relating to herbs or made from them.","vi":"thuộc thảo mộc; làm từ thảo mộc"}],"examples":[{"en":"I usually drink herbal tea before going to bed.","vi":"Tôi thường uống trà thảo mộc trước khi đi ngủ.","audioKind":"ex"},{"en":"Although herbal remedies are widely used, their safety and effectiveness should be assessed through reliable scientific research.","vi":"Mặc dù các bài thuốc thảo mộc được sử dụng rộng rãi, tính an toàn và hiệu quả của chúng vẫn nên được đánh giá thông qua các nghiên cứu khoa học đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"herbal tea","vi":"trà thảo mộc"},{"en":"herbal medicine","vi":"thảo dược"},{"en":"herbal remedy","vi":"phương pháp chữa bệnh bằng thảo mộc"}],"wordFamily":["herb (n.)","herbalist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh, âm h thường được phát âm, trong khi tiếng Anh-Mỹ thường câm âm h.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_suicide', 'en-b2-29', 'suicide', '/ˈsuːɪsaɪd/', 'B2', 'hành vi tự sát; sự tự tử', 'n.', 'suicidal (adj.)', NULL, 'Biểu đạt trung lập thường dùng die by suicide để tránh mang tính kỳ thị.', 'Our local centre offers free workshops on suicide prevention.', NULL, 'Trung tâm địa phương của chúng tôi tổ chức các buổi hội thảo miễn phí về phòng ngừa tự sát.', '{"wordId":"suicide","ukIpa":"/ˈsuːɪsaɪd/","usIpa":"/ˈsuːɪsaɪd/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"The act of intentionally causing one''s own death.","vi":"hành vi tự sát; sự tự tử"}],"examples":[{"en":"Our local centre offers free workshops on suicide prevention.","vi":"Trung tâm địa phương của chúng tôi tổ chức các buổi hội thảo miễn phí về phòng ngừa tự sát.","audioKind":"ex"},{"en":"Suicide prevention requires accessible mental health services, supportive communities, and responsible reporting in the media.","vi":"Công tác phòng ngừa tự sát đòi hỏi các dịch vụ y tế tâm thần dễ tiếp cận, cộng đồng hỗ trợ và việc đưa tin có trách nhiệm trên các phương tiện truyền thông.","audioKind":"ex2"}],"collocations":[{"en":"suicide prevention","vi":"phòng ngừa tự sát"},{"en":"suicide risk","vi":"nguy cơ tự sát"},{"en":"die by suicide","vi":"chết do tự sát"}],"wordFamily":["suicidal (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Biểu đạt trung lập thường dùng die by suicide để tránh mang tính kỳ thị.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fatal', 'en-b2-29', 'fatal', '/ˈfeɪtəl/', 'B2', 'gây tử vong; chí mạng; gây thất bại hoàn toàn; tai hại', 'adj.', 'fatally (adv.), fatality (n.)', 'Đồng nghĩa: deadly, lethal · Trái nghĩa: non-fatal', 'fatal nhấn mạnh việc gây chết người hoặc dẫn đến thất bại; fateful chỉ sự việc có ảnh hưởng trọng đại.', 'These wild mushrooms can be fatal if you eat them.', NULL, 'Những loại nấm dại này có thể gây tử vong nếu bạn ăn chúng.', '{"wordId":"fatal","ukIpa":"/ˈfeɪtəl/","usIpa":"/ˈfeɪtəl/","cefr":"B2","topic":"health","senses":[{"pos":"adj.","en":"Causing someone''s death.","vi":"gây tử vong; chí mạng"},{"pos":"adj.","en":"Causing something to fail completely.","vi":"gây thất bại hoàn toàn; tai hại"}],"examples":[{"en":"These wild mushrooms can be fatal if you eat them.","vi":"Những loại nấm dại này có thể gây tử vong nếu bạn ăn chúng.","audioKind":"ex"},{"en":"Lower speed limits near schools can reduce the risk of fatal accidents involving pedestrians and cyclists.","vi":"Việc giảm giới hạn tốc độ gần các trường học có thể làm giảm nguy cơ tai nạn chết người liên quan đến người đi bộ và người đi xe đạp.","audioKind":"ex2"}],"collocations":[{"en":"fatal accident","vi":"tai nạn chết người"},{"en":"fatal injury","vi":"thương tích chí mạng"},{"en":"fatal flaw","vi":"sai sót chí mạng"},{"en":"prove fatal","vi":"cuối cùng dẫn đến tử vong"}],"wordFamily":["fatally (adv.)","fatality (n.)"],"synonyms":["deadly","lethal"],"antonyms":["non-fatal"],"tipVi":"fatal nhấn mạnh việc gây chết người hoặc dẫn đến thất bại; fateful chỉ sự việc có ảnh hưởng trọng đại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_eyesight', 'en-b2-29', 'eyesight', '/ˈaɪsaɪt/', 'B2', 'thị lực; khả năng nhìn', 'n.', NULL, 'Đồng nghĩa: vision, sight', 'eyesight là danh từ không đếm được, không dùng an eyesight.', 'My grandfather still has excellent eyesight without wearing glasses.', NULL, 'Ông của tôi vẫn có thị lực rất tốt mà không cần đeo kính.', '{"wordId":"eyesight","ukIpa":"/ˈaɪsaɪt/","usIpa":"/ˈaɪsaɪt/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"The ability to see","vi":"thị lực; khả năng nhìn"}],"examples":[{"en":"My grandfather still has excellent eyesight without wearing glasses.","vi":"Ông của tôi vẫn có thị lực rất tốt mà không cần đeo kính.","audioKind":"ex"},{"en":"Regular eye examinations can identify conditions that may damage eyesight if they are left untreated.","vi":"Khám mắt định kỳ có thể phát hiện các bệnh lý có thể làm tổn hại thị lực nếu không được điều trị.","audioKind":"ex2"}],"collocations":[{"en":"poor eyesight","vi":"thị lực kém"},{"en":"good eyesight","vi":"thị lực tốt"},{"en":"damage your eyesight","vi":"làm tổn hại thị lực"}],"wordFamily":[],"synonyms":["vision","sight"],"antonyms":[],"tipVi":"eyesight là danh từ không đếm được, không dùng an eyesight.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bruise', 'en-b2-29', 'bruise', '/bruːz/', 'B2', 'vết bầm tím; vết thâm; làm bầm tím; làm dập', 'n.', 'bruised (adj.), bruising (n.)', NULL, 'Từ "bruise" thường chỉ vết thương không rách da; từ "cut" dùng cho vết cắt rách da.', 'I have a purple bruise on my knee.', NULL, 'Tôi có một vết bầm tím màu tím trên đầu gối.', '{"wordId":"bruise","ukIpa":"/bruːz/","usIpa":"/bruːz/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"A dark mark caused by bleeding under the skin.","vi":"vết bầm tím; vết thâm"},{"pos":"v.","en":"To injure skin or fruit without breaking its surface.","vi":"làm bầm tím; làm dập"}],"examples":[{"en":"I have a purple bruise on my knee.","vi":"Tôi có một vết bầm tím màu tím trên đầu gối.","audioKind":"ex"},{"en":"Soft fruit can bruise during transport, so producers need packaging that provides adequate protection.","vi":"Trái cây mềm rất dễ bị dập trong quá trình vận chuyển, vì vậy nhà sản xuất cần sử dụng bao bì cung cấp khả năng bảo vệ đầy đủ.","audioKind":"ex2"}],"collocations":[{"en":"a nasty bruise","vi":"một vết bầm nặng"},{"en":"bruise easily","vi":"dễ bị bầm tím"},{"en":"a bruised knee","vi":"đầu gối bị bầm tím"}],"wordFamily":["bruised (adj.)","bruising (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ \"bruise\" thường chỉ vết thương không rách da; từ \"cut\" dùng cho vết cắt rách da.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_complication', 'en-b2-29', 'complication', '/ˌkɑːmplɪˈkeɪʃən/', 'B2', 'sự phức tạp; rắc rối phát sinh; biến chứng', 'n.', 'complicate (v.), complicated (adj.)', NULL, 'Có thể chỉ một vấn đề rắc rối phát sinh thêm, hoặc chỉ các triệu chứng bệnh lý và biến chứng y khoa.', 'A delayed train added another complication to our journey.', NULL, 'Việc tàu hỏa bị trễ chuyến lại tạo thêm một rắc rối nữa cho chuyến đi của chúng tôi.', '{"wordId":"complication","ukIpa":"/ˌkɒmplɪˈkeɪʃən/","usIpa":"/ˌkɑːmplɪˈkeɪʃən/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"An extra problem that makes a situation harder to manage","vi":"sự phức tạp; rắc rối phát sinh"},{"pos":"n.","en":"An additional medical problem arising during an illness or treatment","vi":"biến chứng"}],"examples":[{"en":"A delayed train added another complication to our journey.","vi":"Việc tàu hỏa bị trễ chuyến lại tạo thêm một rắc rối nữa cho chuyến đi của chúng tôi.","audioKind":"ex"},{"en":"Regular medical checkups can help detect complications early and improve outcomes for patients with chronic conditions.","vi":"Việc khám sức khỏe định kỳ có thể giúp phát hiện sớm các biến chứng và cải thiện kết quả điều trị cho bệnh nhân mắc bệnh mạn tính.","audioKind":"ex2"}],"collocations":[{"en":"an unexpected complication","vi":"một rắc rối bất ngờ"},{"en":"a serious complication","vi":"biến chứng nghiêm trọng"},{"en":"avoid complications","vi":"tránh rắc rối"},{"en":"postoperative complications","vi":"biến chứng sau phẫu thuật"}],"wordFamily":["complicate (v.)","complicated (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể chỉ một vấn đề rắc rối phát sinh thêm, hoặc chỉ các triệu chứng bệnh lý và biến chứng y khoa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_infect', 'en-b2-29', 'infect', '/ɪnˈfekt/', 'B2', 'làm nhiễm trùng; lây bệnh; lây lan cảm xúc; ảnh hưởng tâm lý', 'v.', 'infection (n.), infectious (adj.), infected (adj.)', NULL, 'Thường dùng cấu trúc infect someone with a virus để chỉ việc làm cho ai đó bị nhiễm vi rút.', 'One sick rabbit can infect the others in its cage.', NULL, 'Một con thỏ bệnh có thể lây bệnh cho những con khác trong cùng lồng.', '{"wordId":"infect","ukIpa":"/ɪnˈfekt/","usIpa":"/ɪnˈfekt/","cefr":"B2","topic":"health","senses":[{"pos":"v.","en":"to cause a person or organism to develop an infection","vi":"làm nhiễm trùng; lây bệnh"},{"pos":"v.","en":"to spread a feeling or attitude to others","vi":"lây lan cảm xúc; ảnh hưởng tâm lý"}],"examples":[{"en":"One sick rabbit can infect the others in its cage.","vi":"Một con thỏ bệnh có thể lây bệnh cho những con khác trong cùng lồng.","audioKind":"ex"},{"en":"Viruses can infect vulnerable patients more easily when hospitals lack effective hygiene measures and adequate ventilation.","vi":"Vi rút có thể dễ dàng lây nhiễm cho những bệnh nhân có sức đề kháng yếu khi các bệnh viện thiếu biện pháp vệ sinh hiệu quả và thông gió đầy đủ.","audioKind":"ex2"}],"collocations":[{"en":"infect someone with a virus","vi":"khiến ai đó bị nhiễm vi rút"},{"en":"become infected","vi":"bị lây nhiễm"},{"en":"infect a wound","vi":"làm nhiễm trùng vết thương"}],"wordFamily":["infection (n.)","infectious (adj.)","infected (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng cấu trúc infect someone with a virus để chỉ việc làm cho ai đó bị nhiễm vi rút.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_edible', 'en-b2-29', 'edible', '/ˈedɪbəl/', 'B2', 'ăn được; dùng làm thức ăn', 'adj.', 'inedible (adj.), edibility (n.)', 'Trái nghĩa: inedible', 'edible biểu thị có thể ăn được, không biểu thị là ngon miệng; đừng phỏng đoán sự an toàn của thực vật hoang dã chỉ dựa vào vẻ bề ngoài.', 'These edible flowers make the salad look especially colourful.', NULL, 'Những bông hoa ăn được này làm cho món salad trông đặc biệt rực rỡ.', '{"wordId":"edible","ukIpa":"/ˈedɪbəl/","usIpa":"/ˈedɪbəl/","cefr":"B2","topic":"health","senses":[{"pos":"adj.","en":"Safe or suitable to eat.","vi":"ăn được; dùng làm thức ăn"}],"examples":[{"en":"These edible flowers make the salad look especially colourful.","vi":"Những bông hoa ăn được này làm cho món salad trông đặc biệt rực rỡ.","audioKind":"ex"},{"en":"Redistributing edible food that shops would otherwise discard could reduce waste and support families on low incomes.","vi":"Việc phân phối lại thực phẩm ăn được mà các cửa hàng vốn dĩ sẽ vứt bỏ có thể giúp giảm thiểu lãng phí và hỗ trợ các gia đình có thu nhập thấp.","audioKind":"ex2"}],"collocations":[{"en":"edible plants","vi":"thực vật ăn được"},{"en":"edible flowers","vi":"hoa ăn được"},{"en":"edible oil","vi":"dầu ăn"}],"wordFamily":["inedible (adj.)","edibility (n.)"],"synonyms":[],"antonyms":["inedible"],"tipVi":"edible biểu thị có thể ăn được, không biểu thị là ngon miệng; đừng phỏng đoán sự an toàn của thực vật hoang dã chỉ dựa vào vẻ bề ngoài.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_obese', 'en-b2-29', 'obese', '/oʊˈbiːs/', 'B2', 'béo phì; thừa cân quá mức', 'adj.', 'obesity (n.)', NULL, 'Đây là thuật ngữ y tế, mức độ nặng hơn overweight; cần thận trọng khi nhắc đến ngoại hình của người khác.', 'The vet said our cat was obese and needed exercise.', NULL, 'Bác sĩ thú y nói rằng con mèo của chúng tôi bị béo phì và cần phải vận động.', '{"wordId":"obese","ukIpa":"/əʊˈbiːs/","usIpa":"/oʊˈbiːs/","cefr":"B2","topic":"health","senses":[{"pos":"adj.","en":"having excessive body fat that may harm health","vi":"béo phì; thừa cân quá mức"}],"examples":[{"en":"The vet said our cat was obese and needed exercise.","vi":"Bác sĩ thú y nói rằng con mèo của chúng tôi bị béo phì và cần phải vận động.","audioKind":"ex"},{"en":"People who are obese should have access to supportive healthcare without facing discrimination or blame.","vi":"Những người béo phì nên được tiếp cận các dịch vụ chăm sóc sức khỏe hỗ trợ mà không phải đối mặt với sự kỳ thị hay đổ lỗi.","audioKind":"ex2"}],"collocations":[{"en":"clinically obese","vi":"béo phì lâm sàng"},{"en":"become obese","vi":"trở nên béo phì"},{"en":"obese patients","vi":"bệnh nhân béo phì"}],"wordFamily":["obesity (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Đây là thuật ngữ y tế, mức độ nặng hơn overweight; cần thận trọng khi nhắc đến ngoại hình của người khác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fatty', 'en-b2-29', 'fatty', '/ˈfæti/', 'B2', 'nhiều mỡ; chứa nhiều chất béo', 'adj.', 'fat (n.), fat (adj.)', 'Trái nghĩa: lean', 'Dùng làm danh từ để gọi người có thể mang ý lăng mạ, nên tránh sử dụng.', 'This soup tastes rich because the meat is fatty.', NULL, 'Món súp này có vị đậm đà vì phần thịt khá nhiều mỡ.', '{"wordId":"fatty","ukIpa":"/ˈfæti/","usIpa":"/ˈfæti/","cefr":"B2","topic":"health","senses":[{"pos":"adj.","en":"Containing much fat, or consisting of fat.","vi":"nhiều mỡ; chứa nhiều chất béo"}],"examples":[{"en":"This soup tastes rich because the meat is fatty.","vi":"Món súp này có vị đậm đà vì phần thịt khá nhiều mỡ.","audioKind":"ex"},{"en":"Although some fatty foods provide essential nutrients, excessive consumption of saturated fat may increase cardiovascular health risks.","vi":"Mặc dù một số thực phẩm giàu chất béo cung cấp dưỡng chất thiết yếu, việc tiêu thụ quá nhiều chất béo bão hòa có thể làm tăng nguy cơ mắc bệnh tim mạch.","audioKind":"ex2"}],"collocations":[{"en":"fatty foods","vi":"thực phẩm nhiều chất béo"},{"en":"fatty tissue","vi":"mô mỡ"},{"en":"fatty acids","vi":"axit béo"},{"en":"fatty fish","vi":"cá béo"}],"wordFamily":["fat (n.)","fat (adj.)"],"synonyms":[],"antonyms":["lean"],"tipVi":"Dùng làm danh từ để gọi người có thể mang ý lăng mạ, nên tránh sử dụng.","noteVi":"Dùng làm danh từ để gọi người béo mang tính lăng mạ.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_29_1', 'en-b2-29', 'Cách dùng “edible” (adj.) — ăn được; dùng làm thức ăn', 'edible plants  ·  edible flowers  ·  edible oil', 'edible biểu thị có thể ăn được, không biểu thị là ngon miệng; đừng phỏng đoán sự an toàn của thực vật hoang dã chỉ dựa vào vẻ bề ngoài.', 'Họ từ (Word Family): inedible (adj.), edibility (n.) | Trái nghĩa: inedible', '[{"hanzi":"These edible flowers make the salad look especially colourful.","pinyin":"","meaning":"Những bông hoa ăn được này làm cho món salad trông đặc biệt rực rỡ."},{"hanzi":"Redistributing edible food that shops would otherwise discard could reduce waste and support families on low incomes.","pinyin":"","meaning":"Việc phân phối lại thực phẩm ăn được mà các cửa hàng vốn dĩ sẽ vứt bỏ có thể giúp giảm thiểu lãng phí và hỗ trợ các gia đình có thu nhập thấp."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_29_2', 'en-b2-29', 'Cách dùng “beverage” (n.) — đồ uống; thức uống (như trà, nước ép, cà phê)', 'hot beverage  ·  alcoholic beverage  ·  sugary beverage', 'beverage mang tính trang trọng hơn, thường dùng trong ngành ẩm thực hoặc văn cảnh học thuật; trong đời sống thường dùng drink.', 'Đồng nghĩa: drink', '[{"hanzi":"Would you like a hot beverage with your sandwich?","pinyin":"","meaning":"Bạn có muốn dùng một món đồ uống nóng kèm với bánh mì kẹp không?"},{"hanzi":"Reducing the consumption of sugary beverages could help lower obesity rates among young people.","pinyin":"","meaning":"Việc giảm tiêu thụ đồ uống có đường có thể giúp hạ thấp tỷ lệ béo phì ở giới trẻ."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_29_3', 'en-b2-29', 'Cách dùng “therapy” (n.) — liệu pháp; sự điều trị (cải thiện sức khỏe thể chất hoặc tinh thần)', 'speech therapy  ·  physical therapy  ·  undergo therapy', 'Khi chỉ việc điều trị nói chung thì danh từ này không đếm được; các liệu pháp cụ thể có thể dùng dạng số nhiều.', 'Họ từ (Word Family): therapist (n.), therapeutic (adj.) | Đồng nghĩa: treatment', '[{"hanzi":"After her injury, regular therapy helped her walk comfortably again.","pinyin":"","meaning":"Sau chấn thương, các buổi trị liệu đều đặn đã giúp cô ấy đi lại thoải mái trở lại."},{"hanzi":"Schools that provide access to psychological therapy may better support students experiencing persistent anxiety.","pinyin":"","meaning":"Các trường học cung cấp dịch vụ trị liệu tâm lý có thể hỗ trợ tốt hơn cho học sinh đang gặp tình trạng lo âu kéo dài."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_29_4', 'en-b2-29', 'Cách dùng “medication” (n.) — thuốc chữa bệnh; việc dùng thuốc điều trị', 'take medication  ·  prescribe medication  ·  be on medication', 'Danh từ chỉ chung thuốc thường là không đếm được; có thể dùng medications khi chỉ nhiều loại thuốc khác nhau.', 'Họ từ (Word Family): medicate (v.), medicated (adj.) | Đồng nghĩa: medicine', '[{"hanzi":"She takes her medication with breakfast every morning.","pinyin":"","meaning":"Cô ấy uống thuốc vào bữa sáng mỗi ngày."},{"hanzi":"Affordable medication is essential for improving public health, particularly in communities with limited medical services.","pinyin":"","meaning":"Thuốc có giá cả phải chăng là điều cốt yếu để cải thiện sức khỏe cộng đồng, đặc biệt là ở những cộng đồng có dịch vụ y tế hạn chế."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_29_1', 'en-b2-29', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_29_1_1', 'ten_b2_29_1', 'exhaustion', 'After the long hike, he fell asleep from exhaustion.', 'After the long hike, he fell asleep from exhaustion.', '/ɪɡˈzɔːstʃən/', 'Sau chuyến đi bộ đường dài kéo dài, anh ấy đã ngủ thiếp đi vì kiệt sức.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_29_1_2', 'ten_b2_29_1', 'calorie', 'This walking app estimates how many calories I burn.', 'This walking app estimates how many calories I burn.', '/ˈkæləri/', 'Ứng dụng đi bộ này ước tính lượng calo tôi đã đốt cháy.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_29_1_3', 'ten_b2_29_1', 'prevention', 'Regular handwashing is a simple method of infection prevention.', 'Regular handwashing is a simple method of infection prevention.', '/prɪˈvenʃən/', 'Rửa tay thường xuyên là một biện pháp đơn giản để phòng ngừa lây nhiễm.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_29_1_4', 'ten_b2_29_1', 'inject', 'The nurse will inject the medicine into my arm.', 'The nurse will inject the medicine into my arm.', '/ɪnˈdʒekt/', 'Y tá sẽ tiêm thuốc vào bắp tay của tôi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_29_1_5', 'ten_b2_29_1', 'treadmill', 'I walk on the treadmill when it rains outside.', 'I walk on the treadmill when it rains outside.', '/ˈtredmɪl/', 'Tôi tập trên máy chạy bộ khi bên ngoài trời mưa.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_29_1_6', 'ten_b2_29_1', 'itch', 'This woollen scarf makes my neck itch all day.', 'This woollen scarf makes my neck itch all day.', '/ɪtʃ/', 'Chiếc khăn quàng cổ bằng len này làm cổ tôi ngứa ngáy cả ngày.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_29_1_7', 'ten_b2_29_1', 'vein', 'A blue vein was visible beneath his wrist.', 'A blue vein was visible beneath his wrist.', '/veɪn/', 'Có thể nhìn thấy một mạch máu xanh nổi lên dưới cổ tay anh ấy.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_29_1_8', 'ten_b2_29_1', 'prescription', 'The doctor gave me a prescription for eye drops.', 'The doctor gave me a prescription for eye drops.', '/prɪˈskrɪpʃən/', 'Bác sĩ đã kê cho tôi đơn thuốc nhỏ mắt.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_29_1_1', 'en-b2-29', 'ten_b2_29_1', 'listening', 'listening', 'After the long hike, he fell asleep from exhaustion.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Trung tâm địa phương của chúng tôi tổ chức các buổi hội thảo miễn phí về phòng ngừa tự sát.","Tôi tập trên máy chạy bộ khi bên ngoài trời mưa.","Y tá sẽ tiêm thuốc vào bắp tay của tôi.","Sau chuyến đi bộ đường dài kéo dài, anh ấy đã ngủ thiếp đi vì kiệt sức."]'::jsonb, 3, 'After the long hike, he fell asleep from exhaustion. → Sau chuyến đi bộ đường dài kéo dài, anh ấy đã ngủ thiếp đi vì kiệt sức.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_29_1_2', 'en-b2-29', 'ten_b2_29_1', 'listening', 'listening', 'This walking app estimates how many calories I burn.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Món súp này có vị đậm đà vì phần thịt khá nhiều mỡ.","Chị tôi chọn ngành điều dưỡng vì chị thích giúp đỡ mọi người.","Y tá sẽ tiêm thuốc vào bắp tay của tôi.","Ứng dụng đi bộ này ước tính lượng calo tôi đã đốt cháy."]'::jsonb, 3, 'This walking app estimates how many calories I burn. → Ứng dụng đi bộ này ước tính lượng calo tôi đã đốt cháy.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_29_1_3', 'en-b2-29', 'ten_b2_29_1', 'listening', 'listening', 'Regular handwashing is a simple method of infection prevention.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Rửa tay thường xuyên là một biện pháp đơn giản để phòng ngừa lây nhiễm.","Chị tôi chọn ngành điều dưỡng vì chị thích giúp đỡ mọi người.","Hãy đeo găng tay bảo hộ trước khi cầm nắm những miếng kim loại sắc bén đó.","Sau chấn thương, các buổi trị liệu đều đặn đã giúp cô ấy đi lại thoải mái trở lại."]'::jsonb, 0, 'Regular handwashing is a simple method of infection prevention. → Rửa tay thường xuyên là một biện pháp đơn giản để phòng ngừa lây nhiễm.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_29_2', 'en-b2-29', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_29_2_1', 'ten_b2_29_2', 'exhaustion', 'Persistent exhaustion among healthcare workers can reduce the quality of patient care and increase staff turnover.', 'Persistent exhaustion among healthcare workers can reduce the quality of patient care and increase staff turnover.', '/ɪɡˈzɔːstʃən/', 'Tình trạng kiệt sức kéo dài ở nhân viên y tế có thể làm giảm chất lượng chăm sóc bệnh nhân và gia tăng tỷ lệ nhân viên nghỉ việc.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_29_2_2', 'ten_b2_29_2', 'calorie', 'Although calorie information can guide food choices, a balanced diet also depends on nutrient quality.', 'Although calorie information can guide food choices, a balanced diet also depends on nutrient quality.', '/ˈkæləri/', 'Mặc dù thông tin về lượng calo có thể định hướng việc lựa chọn thực phẩm, chế độ ăn uống cân bằng còn phụ thuộc vào chất lượng dinh dưỡng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_29_2_3', 'ten_b2_29_2', 'prevention', 'Investment in disease prevention can reduce pressure on hospitals and improve public health over the long term.', 'Investment in disease prevention can reduce pressure on hospitals and improve public health over the long term.', '/prɪˈvenʃən/', 'Đầu tư vào việc phòng ngừa dịch bệnh có thể làm giảm áp lực cho các bệnh viện và cải thiện sức khỏe cộng đồng về lâu dài.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_29_2_4', 'ten_b2_29_2', 'inject', 'Public investment can inject new energy into declining towns by supporting local businesses and improving transport.', 'Public investment can inject new energy into declining towns by supporting local businesses and improving transport.', '/ɪnˈdʒekt/', 'Đầu tư công có thể thổi luồng sinh khí mới vào các thị trấn đang suy thoái bằng cách hỗ trợ các doanh nghiệp địa phương và cải thiện giao thông.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_29_2_5', 'ten_b2_29_2', 'treadmill', 'For some employees, the treadmill of daily work leaves little time for family life or personal interests.', 'For some employees, the treadmill of daily work leaves little time for family life or personal interests.', '/ˈtredmɪl/', 'Đối với một số nhân viên,guồng quay công việc bận rộn hằng ngày khiến họ hầu như không có thời gian dành cho đời sống gia đình hay sở thích cá nhân.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_29_2_6', 'ten_b2_29_2', 'itch', 'Some synthetic fabrics can cause sensitive skin to itch, making material choice important in clothing design.', 'Some synthetic fabrics can cause sensitive skin to itch, making material choice important in clothing design.', '/ɪtʃ/', 'Một số loại vải tổng hợp có thể khiến làn da nhạy cảm bị ngứa, làm cho việc lựa chọn chất liệu trong thiết kế trang phục trở nên quan trọng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_29_2_1', 'en-b2-29', 'ten_b2_29_2', 'listening', 'listening', 'Persistent exhaustion among healthcare workers can reduce the quality of patient care and increase staff turnover.', NULL, 'Trong câu vừa nghe, từ “exhaustion” mang nghĩa nào sau đây?', '["thuộc thời Trung cổ","không còn tươi, ôi thiu (đặc biệt là bánh mì hoặc không khí)","rõ rệt; dễ nhận thấy","sự kiệt sức; tình trạng mệt mỏi cực độ về thể chất hoặc tinh thần"]'::jsonb, 3, '“exhaustion” (/ɪɡˈzɔːstʃən/): sự kiệt sức; tình trạng mệt mỏi cực độ về thể chất hoặc tinh thần. Câu đầy đủ: Persistent exhaustion among healthcare workers can reduce the quality of patient care and increase staff turnover.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_29_2_2', 'en-b2-29', 'ten_b2_29_2', 'listening', 'listening', 'Although calorie information can guide food choices, a balanced diet also depends on nutrient quality.', NULL, 'Trong câu vừa nghe, từ “calorie” mang nghĩa nào sau đây?', '["rộng lớn; bao la; vô cùng","vấp ngã; lạng quạng","sự phòng thủ; sự bảo vệ","lượng calo; đơn vị đo năng lượng (trong thực phẩm)"]'::jsonb, 3, '“calorie” (/ˈkæləri/): lượng calo; đơn vị đo năng lượng (trong thực phẩm). Câu đầy đủ: Although calorie information can guide food choices, a balanced diet also depends on nutrient quality.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
