INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_29_2', 'en-b2-29', NULL, 'comprehensive_test', 'listening', 'This walking app estimates how many calories I burn.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi có một vết bầm tím màu tím trên đầu gối.","Tôi thường uống trà thảo mộc trước khi đi ngủ.","Ông của tôi vẫn có thị lực rất tốt mà không cần đeo kính.","Ứng dụng đi bộ này ước tính lượng calo tôi đã đốt cháy."]'::jsonb, 3, 'This walking app estimates how many calories I burn. → Ứng dụng đi bộ này ước tính lượng calo tôi đã đốt cháy.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
