INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_29_4', 'en-b2-29', NULL, 'comprehensive_test', 'listening', 'The nurse will inject the medicine into my arm.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Y tá sẽ tiêm thuốc vào bắp tay của tôi.","Trung tâm địa phương của chúng tôi tổ chức các buổi hội thảo miễn phí về phòng ngừa tự sát.","Ứng dụng đi bộ này ước tính lượng calo tôi đã đốt cháy.","Việc tàu hỏa bị trễ chuyến lại tạo thêm một rắc rối nữa cho chuyến đi của chúng tôi."]'::jsonb, 0, 'The nurse will inject the medicine into my arm. → Y tá sẽ tiêm thuốc vào bắp tay của tôi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_29_5', 'en-b2-29', NULL, 'comprehensive_test', 'listening', 'treadmill', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chậu rửa; vũng nước","máy chạy bộ","lái (xe, thuyền); điều khiển hướng đi","quan sát; để ý"]'::jsonb, 1, 'treadmill (/ˈtredmɪl/) → máy chạy bộ; công việc đơn điệu và bận rộn', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_29_6', 'en-b2-29', NULL, 'comprehensive_test', 'listening', 'This woollen scarf makes my neck itch all day.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Trung tâm địa phương của chúng tôi tổ chức các buổi hội thảo miễn phí về phòng ngừa tự sát.","Bạn có muốn dùng một món đồ uống nóng kèm với bánh mì kẹp không?","Chiếc khăn quàng cổ bằng len này làm cổ tôi ngứa ngáy cả ngày.","Cô y tá bảo tôi thả lỏng trước khi tiêm vắc-xin."]'::jsonb, 2, 'This woollen scarf makes my neck itch all day. → Chiếc khăn quàng cổ bằng len này làm cổ tôi ngứa ngáy cả ngày.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_29_7', 'en-b2-29', NULL, 'comprehensive_test', 'listening', 'vein', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tích cực; theo chiều hướng tốt; đầy lạc quan","tĩnh mạch","làm tối đi; trở nên tối hơn","thuộc đạo đức; có đạo đức"]'::jsonb, 1, 'vein (/veɪn/) → tĩnh mạch; gân lá; vân quặng; mạch khoáng', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_29_8', 'en-b2-29', NULL, 'comprehensive_test', 'listening', 'The doctor gave me a prescription for eye drops.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chị tôi chọn ngành điều dưỡng vì chị thích giúp đỡ mọi người.","Bác sĩ đã kê cho tôi đơn thuốc nhỏ mắt.","Cô y tá bảo tôi thả lỏng trước khi tiêm vắc-xin.","Những loại nấm dại này có thể gây tử vong nếu bạn ăn chúng."]'::jsonb, 1, 'The doctor gave me a prescription for eye drops. → Bác sĩ đã kê cho tôi đơn thuốc nhỏ mắt.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_29_9', 'en-b2-29', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “An exercise machine with a moving surface for walking or running.”?', '["therapy","prevention","herbal","treadmill"]'::jsonb, 3, 'treadmill (/ˈtredmɪl/) → máy chạy bộ', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
