INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_29_18', 'en-b2-29', NULL, 'comprehensive_test', 'reading', NULL, 'Persistent exhaustion among healthcare workers can reduce the quality of patient care and increase staff turnover.', 'Dựa vào câu trên, từ “exhaustion” có nghĩa phù hợp nhất là gì?', '["sự kiệt sức; tình trạng mệt mỏi cực độ về thể chất hoặc tinh thần","nhà thuyền; thuyền cư trú","thuộc vùng; mang tính khu vực; địa phương","cô đơn; buồn tủi"]'::jsonb, 0, 'exhaustion: sự kiệt sức; tình trạng mệt mỏi cực độ về thể chất hoặc tinh thần; sự cạn kiệt; việc sử dụng hết hoàn toàn nguồn cung hoặc nguồn lực có sẵn. Dịch cả câu: Tình trạng kiệt sức kéo dài ở nhân viên y tế có thể làm giảm chất lượng chăm sóc bệnh nhân và gia tăng tỷ lệ nhân viên nghỉ việc.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_29_19', 'en-b2-29', NULL, 'comprehensive_test', 'reading', NULL, 'Although calorie information can guide food choices, a balanced diet also depends on nutrient quality.', 'Dựa vào câu trên, từ “calorie” có nghĩa phù hợp nhất là gì?', '["sự chuyển động; sự di chuyển","lượng calo; đơn vị đo năng lượng (trong thực phẩm)","nhà trẻ; trường mẫu giáo","trí thông minh; năng lực trí tuệ"]'::jsonb, 1, 'calorie: lượng calo; đơn vị đo năng lượng (trong thực phẩm). Dịch cả câu: Mặc dù thông tin về lượng calo có thể định hướng việc lựa chọn thực phẩm, chế độ ăn uống cân bằng còn phụ thuộc vào chất lượng dinh dưỡng.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_29_20', 'en-b2-29', NULL, 'comprehensive_test', 'reading', NULL, 'Investment in disease prevention can reduce pressure on hospitals and improve public health over the long term.', 'Dựa vào câu trên, từ “prevention” có nghĩa phù hợp nhất là gì?', '["sự vứt bỏ; sự xử lý","thắng lợi lớn; thành tựu vẻ vang","sự phòng ngừa; sự ngăn chặn","từ nối; liên từ"]'::jsonb, 2, 'prevention: sự phòng ngừa; sự ngăn chặn. Dịch cả câu: Đầu tư vào việc phòng ngừa dịch bệnh có thể làm giảm áp lực cho các bệnh viện và cải thiện sức khỏe cộng đồng về lâu dài.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_29_21', 'en-b2-29', NULL, 'comprehensive_test', 'reading', NULL, 'Public investment can inject new energy into declining towns by supporting local businesses and improving transport.', 'Dựa vào câu trên, từ “inject” có nghĩa phù hợp nhất là gì?', '["cáp; dây cáp (mang điện hoặc tín hiệu điện tử)","chồng (đồ vật xếp chồng lên nhau)","tiêm; bơm","ẩm; ẩm ướt; ẩm mịn"]'::jsonb, 2, 'inject: tiêm; bơm; rót vào; truyền thêm năng lượng, tiền bạc hoặc thứ gì đó mới vào một tình huống. Dịch cả câu: Đầu tư công có thể thổi luồng sinh khí mới vào các thị trấn đang suy thoái bằng cách hỗ trợ các doanh nghiệp địa phương và cải thiện giao thông.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_29_22', 'en-b2-29', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ăn được; dùng làm thức ăn”', '["usage","peak","edible","basin"]'::jsonb, 2, 'ăn được; dùng làm thức ăn → edible (/ˈedɪbəl/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
