INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-30', 'en', 'Bài 30: Sức khỏe & Cơ thể (5) - CEFR B2', 'CEFR B2', 'B2 · Sức khỏe', '25 từ vựng Tiếng Anh CEFR B2 chủ đề sức khỏe & cơ thể kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4030, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disorder', 'en-b2-30', 'disorder', '/dɪsˈɔːrdər/', 'B2', 'rối loạn; chứng bệnh; sự suy giảm chức năng; sự lộn xộn; tình trạng bừa bãi; sự náo loạn; bạo động công cộng', 'n.', 'order (n.), disordered (adj.), disorderly (adj.)', NULL, 'Nghĩa bệnh lý là danh từ đếm được; nghĩa lộn xộn hay náo loạn thường không đếm được.', 'A sleep disorder kept him awake most nights.', NULL, 'Chứng rối loạn giấc ngủ khiến anh ấy thức trắng hầu hết các đêm.', '{"wordId":"disorder","ukIpa":"/dɪsˈɔːdə/","usIpa":"/dɪsˈɔːrdər/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"a condition that disrupts normal physical or mental functioning","vi":"rối loạn; chứng bệnh; sự suy giảm chức năng"},{"pos":"n.","en":"a state in which things are not properly arranged","vi":"sự lộn xộn; tình trạng bừa bãi"},{"pos":"n.","en":"uncontrolled public behaviour that disturbs peace or safety","vi":"sự náo loạn; bạo động công cộng"}],"examples":[{"en":"A sleep disorder kept him awake most nights.","vi":"Chứng rối loạn giấc ngủ khiến anh ấy thức trắng hầu hết các đêm.","audioKind":"ex"},{"en":"Early treatment of anxiety disorders can improve students'' wellbeing and help them participate more fully in education.","vi":"Việc điều trị sớm các chứng rối loạn lo âu có thể cải thiện sức khỏe tinh thần của học sinh và giúp các em tham gia học tập đầy đủ hơn.","audioKind":"ex2"}],"collocations":[{"en":"sleep disorder","vi":"chứng rối loạn giấc ngủ"},{"en":"eating disorder","vi":"chứng rối loạn ăn uống"},{"en":"in disorder","vi":"bừa bộn; lộn xộn"},{"en":"public disorder","vi":"tình trạng gây rối trật tự công cộng"}],"wordFamily":["order (n.)","disordered (adj.)","disorderly (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa bệnh lý là danh từ đếm được; nghĩa lộn xộn hay náo loạn thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cope', 'en-b2-30', 'cope', '/koʊp/', 'B2', 'đối phó; đương đầu; giải quyết', 'v.', 'coping (n.)', 'Đồng nghĩa: manage', 'cope là nội động từ, khi đi với khó khăn hoặc áp lực thì phải dùng với with.', 'I cope with busy mornings by preparing breakfast ahead.', NULL, 'Tôi đối phó với những buổi sáng bận rộn bằng cách chuẩn bị bữa sáng từ trước.', '{"wordId":"cope","ukIpa":"/kəʊp/","usIpa":"/koʊp/","cefr":"B2","topic":"health","senses":[{"pos":"v.","en":"To manage a difficult situation successfully.","vi":"đối phó; đương đầu; giải quyết"}],"examples":[{"en":"I cope with busy mornings by preparing breakfast ahead.","vi":"Tôi đối phó với những buổi sáng bận rộn bằng cách chuẩn bị bữa sáng từ trước.","audioKind":"ex"},{"en":"Schools should teach practical strategies that help students cope with examination stress and maintain their mental wellbeing.","vi":"Nhà trường nên trang bị các chiến lược thực tế giúp học sinh đối phó với áp lực thi cử và duy trì sức khỏe tinh thần.","audioKind":"ex2"}],"collocations":[{"en":"cope with stress","vi":"đối phó với áp lực"},{"en":"cope with change","vi":"thích ứng với sự thay đổi"},{"en":"cope well","vi":"ứng phó tốt"}],"wordFamily":["coping (n.)"],"synonyms":["manage"],"antonyms":[],"tipVi":"cope là nội động từ, khi đi với khó khăn hoặc áp lực thì phải dùng với with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_carbohydrate', 'en-b2-30', 'carbohydrate', '/ˌkɑːrboʊˈhaɪdreɪt/', 'B2', 'thức ăn chứa đường hoặc tinh bột cung cấp năng lượng', 'n.', NULL, NULL, 'Khi dùng chỉ chất dinh dưỡng, từ này có thể đếm được hoặc không; dùng số nhiều khi nói về các loại hoặc tổng thể.', 'Rice provides carbohydrate, which gives you energy for daily activities.', NULL, 'Cơm cung cấp carbohydrate, giúp bạn có năng lượng cho các hoạt động hàng ngày.', '{"wordId":"carbohydrate","ukIpa":"/ˌkɑːbəʊˈhaɪdreɪt/","usIpa":"/ˌkɑːrboʊˈhaɪdreɪt/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"A substance such as sugar or starch that provides energy.","vi":"thức ăn chứa đường hoặc tinh bột cung cấp năng lượng"}],"examples":[{"en":"Rice provides carbohydrate, which gives you energy for daily activities.","vi":"Cơm cung cấp carbohydrate, giúp bạn có năng lượng cho các hoạt động hàng ngày.","audioKind":"ex"},{"en":"Although carbohydrates are an important energy source, public health guidance should distinguish wholegrain foods from products containing added sugars.","vi":"Mặc dù carbohydrate là nguồn năng lượng quan trọng, các hướng dẫn y tế công cộng vẫn nên phân biệt rõ thực phẩm ngũ cốc nguyên hạt với các sản phẩm chứa đường bổ sung.","audioKind":"ex2"}],"collocations":[{"en":"complex carbohydrates","vi":"carbohydrate phức hợp"},{"en":"carbohydrate intake","vi":"lượng carbohydrate nạp vào"},{"en":"low-carbohydrate diet","vi":"chế độ ăn ít carbohydrate"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi dùng chỉ chất dinh dưỡng, từ này có thể đếm được hoặc không; dùng số nhiều khi nói về các loại hoặc tổng thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bathe', 'en-b2-30', 'bathe', '/beɪð/', 'B2', 'tắm; rửa sạch cơ thể; rửa nhẹ nhàng (bộ phận cơ thể bằng chất lỏng); bơi lội; ngâm mình (trong biển hoặc hồ)', 'v.', 'bathing (n.), bather (n.), bath (n.)', 'Đồng nghĩa: wash', 'bathe đọc /beɪð/, đừng nhầm với bath; tiếng Anh-Anh cũng có thể chỉ việc bơi lội dưới biển.', 'Gently bathe your sore feet in warm water.', NULL, 'Hãy nhẹ nhàng ngâm bàn chân đang đau nhức của bạn vào nước ấm.', '{"wordId":"bathe","ukIpa":"/beɪð/","usIpa":"/beɪð/","cefr":"B2","topic":"health","senses":[{"pos":"v.","en":"To wash yourself or another person in a bath","vi":"tắm; rửa sạch cơ thể"},{"pos":"v.","en":"To gently wash a body part with liquid","vi":"rửa nhẹ nhàng (bộ phận cơ thể bằng chất lỏng)"},{"pos":"v.","en":"To swim or spend time in the sea or a lake","vi":"bơi lội; ngâm mình (trong biển hoặc hồ)"}],"examples":[{"en":"Gently bathe your sore feet in warm water.","vi":"Hãy nhẹ nhàng ngâm bàn chân đang đau nhức của bạn vào nước ấm.","audioKind":"ex"},{"en":"Residents need reliable access to clean water to bathe safely and maintain good personal hygiene.","vi":"Cư dân cần được tiếp cận nguồn nước sạch đáng tin cậy để tắm rửa an toàn và duy trì vệ sinh cá nhân tốt.","audioKind":"ex2"}],"collocations":[{"en":"bathe a baby","vi":"tắm cho em bé"},{"en":"bathe a wound","vi":"rửa vết thương"},{"en":"bathe in the sea","vi":"tắm biển"}],"wordFamily":["bathing (n.)","bather (n.)","bath (n.)"],"synonyms":["wash"],"antonyms":[],"tipVi":"bathe đọc /beɪð/, đừng nhầm với bath; tiếng Anh-Anh cũng có thể chỉ việc bơi lội dưới biển.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_eyelid', 'en-b2-30', 'eyelid', '/ˈaɪlɪd/', 'B2', 'mí mắt; mi mắt', 'n.', NULL, NULL, 'eyelid là mí mắt; eyelash là lông mi.', 'A tiny grain of sand irritated my eyelid.', NULL, 'Một hạt cát nhỏ làm mí mắt tôi bị cộm.', '{"wordId":"eyelid","ukIpa":"/ˈaɪlɪd/","usIpa":"/ˈaɪlɪd/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"a fold of skin that closes over the eye","vi":"mí mắt; mi mắt"}],"examples":[{"en":"A tiny grain of sand irritated my eyelid.","vi":"Một hạt cát nhỏ làm mí mắt tôi bị cộm.","audioKind":"ex"},{"en":"The eyelids help protect the eyes from dust and spread moisture across their surface during blinking.","vi":"Mí mắt giúp bảo vệ mắt khỏi bụi bẩn và phân bố độ ẩm đều trên bề mặt nhãn cầu khi chớp mắt.","audioKind":"ex2"}],"collocations":[{"en":"upper eyelid","vi":"mí mắt trên"},{"en":"lower eyelid","vi":"mí mắt dưới"},{"en":"swollen eyelid","vi":"mí mắt sưng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"eyelid là mí mắt; eyelash là lông mi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_outbreak', 'en-b2-30', 'outbreak', '/ˈaʊtbreɪk/', 'B2', 'sự bùng phát; cơn bùng nổ (bệnh dịch hoặc sự việc có hại)', 'n.', NULL, NULL, 'Danh từ outbreak viết liền thành một từ; động từ tương ứng là break out.', 'The flu outbreak kept several children home from school.', NULL, 'Vụ bùng phát bệnh cúm khiến mấy đứa trẻ phải nghỉ học ở nhà.', '{"wordId":"outbreak","ukIpa":"/ˈaʊtbreɪk/","usIpa":"/ˈaʊtbreɪk/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"The sudden start of a disease or other harmful event.","vi":"sự bùng phát; cơn bùng nổ (bệnh dịch hoặc sự việc có hại)"}],"examples":[{"en":"The flu outbreak kept several children home from school.","vi":"Vụ bùng phát bệnh cúm khiến mấy đứa trẻ phải nghỉ học ở nhà.","audioKind":"ex"},{"en":"Rapid access to reliable health information can help communities respond effectively to an outbreak of infectious disease.","vi":"Việc tiếp cận nhanh chóng với thông tin y tế đáng tin cậy có thể giúp các cộng đồng ứng phó hiệu quả với một đợt bùng phát dịch bệnh truyền nhiễm.","audioKind":"ex2"}],"collocations":[{"en":"a disease outbreak","vi":"đợt bùng phát dịch bệnh"},{"en":"the outbreak of war","vi":"sự bùng nổ chiến tranh"},{"en":"contain an outbreak","vi":"kiểm soát dịch bệnh bùng phát"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ outbreak viết liền thành một từ; động từ tương ứng là break out.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_consciousness', 'en-b2-30', 'consciousness', '/ˈkɑːnʃəsnəs/', 'B2', 'trạng thái tỉnh táo; tri giác; sự nhận thức; sự am hiểu', 'n.', 'conscious (adj.), unconscious (adj.), consciously (adv.)', 'Đồng nghĩa: awareness · Trái nghĩa: unconsciousness', 'consciousness chỉ ý thức hoặc tri giác; conscience chỉ lương tâm.', 'He regained consciousness shortly after the ambulance arrived.', NULL, 'Anh ấy đã lấy lại ý thức ngay sau khi xe cứu thương đến.', '{"wordId":"consciousness","ukIpa":"/ˈkɒnʃəsnəs/","usIpa":"/ˈkɑːnʃəsnəs/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"The state of being awake and aware of your surroundings","vi":"trạng thái tỉnh táo; tri giác"},{"pos":"n.","en":"Awareness or understanding of a particular issue or situation","vi":"sự nhận thức; sự am hiểu"}],"examples":[{"en":"He regained consciousness shortly after the ambulance arrived.","vi":"Anh ấy đã lấy lại ý thức ngay sau khi xe cứu thương đến.","audioKind":"ex"},{"en":"Environmental education can raise public consciousness of how everyday consumption affects natural resources and biodiversity.","vi":"Giáo dục môi trường có thể nâng cao ý thức cộng đồng về việc tiêu dùng hàng ngày tác động như thế nào đến tài nguyên thiên nhiên và đa dạng sinh học.","audioKind":"ex2"}],"collocations":[{"en":"lose consciousness","vi":"mất ý thức"},{"en":"regain consciousness","vi":"lấy lại ý thức"},{"en":"environmental consciousness","vi":"ý thức bảo vệ môi trường"}],"wordFamily":["conscious (adj.)","unconscious (adj.)","consciously (adv.)"],"synonyms":["awareness"],"antonyms":["unconsciousness"],"tipVi":"consciousness chỉ ý thức hoặc tri giác; conscience chỉ lương tâm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thigh', 'en-b2-30', 'thigh', '/θaɪ/', 'B2', 'đùi', 'n.', NULL, NULL, 'Chỉ phần chân từ hông đến đầu gối; phần cẳng chân thường dùng lower leg.', 'My thighs ached after cycling up the steep hill.', NULL, 'Cơ đùi của tôi bị đau nhức sau khi đạp xe lên đoạn dốc đứng.', '{"wordId":"thigh","ukIpa":"/θaɪ/","usIpa":"/θaɪ/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"The upper part of the leg, above the knee.","vi":"đùi"}],"examples":[{"en":"My thighs ached after cycling up the steep hill.","vi":"Cơ đùi của tôi bị đau nhức sau khi đạp xe lên đoạn dốc đứng.","audioKind":"ex"},{"en":"Regular cycling strengthens the thigh muscles and can improve overall fitness without excessive joint strain.","vi":"Việc đạp xe thường xuyên giúp tăng cường cơ đùi và cải thiện thể lực tổng thể mà không gây áp lực quá lớn lên các khớp xương.","audioKind":"ex2"}],"collocations":[{"en":"thigh muscles","vi":"cơ đùi"},{"en":"inner thigh","vi":"đùi trong"},{"en":"thigh injury","vi":"chấn thương đùi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ phần chân từ hông đến đầu gối; phần cẳng chân thường dùng lower leg.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_depression', 'en-b2-30', 'depression', '/dɪˈpreʃən/', 'B2', 'chứng trầm cảm; sự trầm uất; thời kỳ suy thoái kinh tế; vùng trũng; chỗ lõm xuống', 'n.', 'depress (v.), depressed (adj.), depressing (adj.)', NULL, 'Trầm cảm không đồng nghĩa với cảm giác buồn chán thoáng qua; cuộc suy thoái lớn thường dùng a depression.', 'Her doctor recommended regular counselling to help manage depression.', NULL, 'Bác sĩ của cô ấy khuyên nên tư vấn tâm lý định kỳ để giúp kiểm soát chứng trầm cảm.', '{"wordId":"depression","ukIpa":"/dɪˈpreʃən/","usIpa":"/dɪˈpreʃən/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"a condition involving persistent sadness and loss of interest","vi":"chứng trầm cảm; sự trầm uất"},{"pos":"n.","en":"a long period of severely reduced economic activity","vi":"thời kỳ suy thoái kinh tế"},{"pos":"n.","en":"an area lower than the surface around it","vi":"vùng trũng; chỗ lõm xuống"}],"examples":[{"en":"Her doctor recommended regular counselling to help manage depression.","vi":"Bác sĩ của cô ấy khuyên nên tư vấn tâm lý định kỳ để giúp kiểm soát chứng trầm cảm.","audioKind":"ex"},{"en":"Improving access to mental health services can help people with depression receive timely support and appropriate treatment.","vi":"Việc cải thiện khả năng tiếp cận các dịch vụ chăm sóc sức khỏe tinh thần có thể giúp bệnh nhân trầm cảm nhận được sự hỗ trợ kịp thời và điều trị phù hợp.","audioKind":"ex2"}],"collocations":[{"en":"suffer from depression","vi":"mắc chứng trầm cảm"},{"en":"severe depression","vi":"trầm cảm nặng"},{"en":"economic depression","vi":"suy thoái kinh tế"},{"en":"treat depression","vi":"điều trị trầm cảm"}],"wordFamily":["depress (v.)","depressed (adj.)","depressing (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Trầm cảm không đồng nghĩa với cảm giác buồn chán thoáng qua; cuộc suy thoái lớn thường dùng a depression.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_asthma', 'en-b2-30', 'asthma', '/ˈæzmə/', 'B2', 'bệnh hen suyễn', 'n.', 'asthmatic (adj.)', NULL, 'Là danh từ không đếm được; âm th không phát âm, có sự khác biệt về phụ âm giữa Anh-Anh và Anh-Mỹ.', 'My brother carries an inhaler to manage his asthma.', NULL, 'Anh trai tôi luôn mang theo ống hít để kiểm soát bệnh hen suyễn của mình.', '{"wordId":"asthma","ukIpa":"/ˈæsmə/","usIpa":"/ˈæzmə/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"A condition that can narrow airways and make breathing difficult","vi":"bệnh hen suyễn"}],"examples":[{"en":"My brother carries an inhaler to manage his asthma.","vi":"Anh trai tôi luôn mang theo ống hít để kiểm soát bệnh hen suyễn của mình.","audioKind":"ex"},{"en":"Reducing urban air pollution can help prevent asthma attacks and improve the quality of life for residents.","vi":"Giảm ô nhiễm không khí đô thị có thể giúp ngăn ngừa các cơn hen suyễn phát cơn và nâng cao chất lượng cuộc sống cho cư dân.","audioKind":"ex2"}],"collocations":[{"en":"asthma attack","vi":"cơn hen suyễn phát tác"},{"en":"severe asthma","vi":"hen suyễn nặng"},{"en":"manage asthma","vi":"kiểm soát bệnh hen suyễn"},{"en":"childhood asthma","vi":"hen suyễn ở trẻ em"}],"wordFamily":["asthmatic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ không đếm được; âm th không phát âm, có sự khác biệt về phụ âm giữa Anh-Anh và Anh-Mỹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unfit', 'en-b2-30', 'unfit', '/ʌnˈfɪt/', 'B2', 'không phù hợp; không đạt tiêu chuẩn; thể lực kém; không khỏe mạnh', 'adj.', 'fit (adj.), fitness (n.), unfitness (n.)', 'Đồng nghĩa: unsuitable · Trái nghĩa: fit, suitable', 'Thường dùng cấu trúc unfit for sth hoặc unfit to do sth.', 'The rusty bicycle was unfit for the long journey.', NULL, 'Chiếc xe đạp bị gỉ sét không còn phù hợp cho chuyến hành trình dài.', '{"wordId":"unfit","ukIpa":"/ʌnˈfɪt/","usIpa":"/ʌnˈfɪt/","cefr":"B2","topic":"health","senses":[{"pos":"adj.","en":"not suitable or good enough for a particular purpose","vi":"không phù hợp; không đạt tiêu chuẩn"},{"pos":"adj.","en":"not physically healthy or strong, often through lack of exercise","vi":"thể lực kém; không khỏe mạnh"}],"examples":[{"en":"The rusty bicycle was unfit for the long journey.","vi":"Chiếc xe đạp bị gỉ sét không còn phù hợp cho chuyến hành trình dài.","audioKind":"ex"},{"en":"Poor maintenance can make public housing unfit for occupation, putting additional pressure on local authorities.","vi":"Việc bảo trì kém có thể khiến nhà ở xã hội không đủ điều kiện để ở, tạo thêm áp lực cho chính quyền địa phương.","audioKind":"ex2"}],"collocations":[{"en":"unfit for purpose","vi":"không đáp ứng mục đích sử dụng"},{"en":"unfit for human consumption","vi":"không thích hợp cho con người tiêu thụ"},{"en":"physically unfit","vi":"thể lực kém"},{"en":"unfit to drive","vi":"không đủ điều kiện lái xe"}],"wordFamily":["fit (adj.)","fitness (n.)","unfitness (n.)"],"synonyms":["unsuitable"],"antonyms":["fit","suitable"],"tipVi":"Thường dùng cấu trúc unfit for sth hoặc unfit to do sth.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vitamin', 'en-b2-30', 'vitamin', '/ˈvaɪtəmɪn/', 'B2', 'vitamin', 'n.', NULL, NULL, 'Trong tiếng Anh-Anh, âm đầu tiên đọc là /vɪ/, trong khi tiếng Anh-Mỹ đọc là /vaɪ/.', 'These fresh oranges are a good source of vitamin C.', NULL, 'Những quả cam tươi này là nguồn cung cấp vitamin C dồi dào.', '{"wordId":"vitamin","ukIpa":"/ˈvɪtəmɪn/","usIpa":"/ˈvaɪtəmɪn/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"A substance needed in small amounts for healthy growth and functioning.","vi":"vitamin"}],"examples":[{"en":"These fresh oranges are a good source of vitamin C.","vi":"Những quả cam tươi này là nguồn cung cấp vitamin C dồi dào.","audioKind":"ex"},{"en":"A varied diet usually provides the vitamins people need without requiring them to take supplements.","vi":"Một chế độ ăn uống đa dạng thường cung cấp đủ các loại vitamin mà cơ thể cần mà không cần phải dùng đến thực phẩm bổ sung.","audioKind":"ex2"}],"collocations":[{"en":"vitamin deficiency","vi":"sự thiếu hụt vitamin"},{"en":"vitamin supplements","vi":"thực phẩm bổ sung vitamin"},{"en":"rich in vitamins","vi":"giàu vitamin"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh, âm đầu tiên đọc là /vɪ/, trong khi tiếng Anh-Mỹ đọc là /vaɪ/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_counselor', 'en-b2-30', 'counselor', '/ˈkaʊnsələr/', 'B2', 'chuyên gia tư vấn; cố vấn tâm lý; giáo viên hướng dẫn; cố vấn; luật sư (đặc biệt trong tiếng Anh-Mỹ)', 'n.', 'counsel (v.), counseling (n.)', 'Đồng nghĩa: adviser', 'Đây là cách viết theo kiểu Mỹ; tiếng Anh-Anh thường viết là counsellor.', 'The school counselor helped me manage my exam worries.', NULL, 'Chuyên gia tư vấn của trường đã giúp tôi quản lý sự lo lắng về kỳ thi.', '{"wordId":"counselor","ukIpa":"/ˈkaʊnsələ/","usIpa":"/ˈkaʊnsələr/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"Someone trained to help people with personal or emotional problems.","vi":"chuyên gia tư vấn; cố vấn tâm lý; giáo viên hướng dẫn"},{"pos":"n.","en":"Someone who gives advice on a particular subject.","vi":"cố vấn"},{"pos":"n.","en":"A lawyer, especially in American English.","vi":"luật sư (đặc biệt trong tiếng Anh-Mỹ)"}],"examples":[{"en":"The school counselor helped me manage my exam worries.","vi":"Chuyên gia tư vấn của trường đã giúp tôi quản lý sự lo lắng về kỳ thi.","audioKind":"ex"},{"en":"Employing a trained counselor can help schools support students facing emotional difficulties or challenging family circumstances.","vi":"Việc thuê một chuyên gia tư vấn được đào tạo bài bản có thể giúp các nhà trường hỗ trợ học sinh đối mặt với những khó khăn cảm xúc hoặc hoàn cảnh gia đình thử thách.","audioKind":"ex2"}],"collocations":[{"en":"school counselor","vi":"cố vấn học đường"},{"en":"mental health counselor","vi":"chuyên gia tư vấn sức khỏe tâm thần"},{"en":"career counselor","vi":"cố vấn nghề nghiệp"}],"wordFamily":["counsel (v.)","counseling (n.)"],"synonyms":["adviser"],"antonyms":[],"tipVi":"Đây là cách viết theo kiểu Mỹ; tiếng Anh-Anh thường viết là counsellor.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_swell', 'en-b2-30', 'swell', '/swel/', 'B2', 'sưng lên; phồng lên; tăng lên; lớn mạnh; sóng cuộn', 'v.', 'swelling (n.), swollen (adj.)', 'Đồng nghĩa: expand, increase · Trái nghĩa: shrink', 'Dạng quá khứ là swelled; phân từ hai thường dùng là swollen.', 'My ankle began to swell after I twisted it.', NULL, 'Mắt cá chân của tôi bắt đầu sưng lên sau khi bị trật khớp.', '{"wordId":"swell","ukIpa":"/swel/","usIpa":"/swel/","cefr":"B2","topic":"health","senses":[{"pos":"v.","en":"To become larger or rounder, or make something do so.","vi":"sưng lên; phồng lên"},{"pos":"v.","en":"To increase in amount or strength, or cause this.","vi":"tăng lên; lớn mạnh"},{"pos":"n.","en":"The movement of long, smooth waves across the sea.","vi":"sóng cuộn"}],"examples":[{"en":"My ankle began to swell after I twisted it.","vi":"Mắt cá chân của tôi bắt đầu sưng lên sau khi bị trật khớp.","audioKind":"ex"},{"en":"Seasonal tourism can swell the population of coastal towns, placing additional pressure on local water supplies.","vi":"Du lịch theo mùa có thể làm tăng dân số ở các thị trấn ven biển, gây thêm áp lực lên nguồn nước sinh hoạt địa phương.","audioKind":"ex2"}],"collocations":[{"en":"swell up","vi":"sưng phồng lên"},{"en":"swell with pride","vi":"phồng lên vì tự hào"},{"en":"a heavy swell","vi":"đợt sóng lớn"}],"wordFamily":["swelling (n.)","swollen (adj.)"],"synonyms":["expand","increase"],"antonyms":["shrink"],"tipVi":"Dạng quá khứ là swelled; phân từ hai thường dùng là swollen.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sleepiness', 'en-b2-30', 'sleepiness', '/ˈsliːpinəs/', 'B2', 'cảm giác buồn ngủ; cơn buồn ngủ', 'n.', 'sleep (v.), sleepy (adj.), sleepily (adv.), sleepless (adj.)', 'Đồng nghĩa: drowsiness · Trái nghĩa: wakefulness', 'Là danh từ không đếm được, chỉ cảm giác muốn ngủ, khác với việc đã chìm vào giấc ngủ.', 'A short walk helped me shake off my sleepiness.', NULL, 'Đi dạo một chút đã giúp tôi xua tan cơn buồn ngủ.', '{"wordId":"sleepiness","ukIpa":"/ˈsliːpinəs/","usIpa":"/ˈsliːpinəs/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"The feeling of being tired and wanting to sleep.","vi":"cảm giác buồn ngủ; cơn buồn ngủ"}],"examples":[{"en":"A short walk helped me shake off my sleepiness.","vi":"Đi dạo một chút đã giúp tôi xua tan cơn buồn ngủ.","audioKind":"ex"},{"en":"Persistent daytime sleepiness can affect students'' concentration and reduce their ability to absorb new information.","vi":"Cảm giác buồn ngủ ban ngày kéo dài có thể làm giảm sự tập trung của học sinh và làm suy yếu khả năng tiếp thu thông tin mới của các em.","audioKind":"ex2"}],"collocations":[{"en":"daytime sleepiness","vi":"buồn ngủ ban ngày"},{"en":"excessive sleepiness","vi":"chứng thèm ngủ quá mức"},{"en":"shake off sleepiness","vi":"xua tan cơn buồn ngủ"}],"wordFamily":["sleep (v.)","sleepy (adj.)","sleepily (adv.)","sleepless (adj.)"],"synonyms":["drowsiness"],"antonyms":["wakefulness"],"tipVi":"Là danh từ không đếm được, chỉ cảm giác muốn ngủ, khác với việc đã chìm vào giấc ngủ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_antibiotics', 'en-b2-30', 'antibiotics', '/ˌæntibaɪˈɑːtɪks/', 'B2', 'thuốc kháng sinh', 'n.', 'antibiotic (n.), antibiotic (adj.)', NULL, 'Là dạng số nhiều của "antibiotic"; thuốc kháng sinh không thể điều trị nhiễm virus.', 'The doctor prescribed antibiotics for my ear infection.', NULL, 'Bác sĩ đã kê đơn thuốc kháng sinh cho chứng nhiễm trùng tai của tôi.', '{"wordId":"antibiotics","ukIpa":"/ˌæntibaɪˈɒtɪks/","usIpa":"/ˌæntibaɪˈɑːtɪks/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"Medicines used to treat infections caused by bacteria.","vi":"thuốc kháng sinh"}],"examples":[{"en":"The doctor prescribed antibiotics for my ear infection.","vi":"Bác sĩ đã kê đơn thuốc kháng sinh cho chứng nhiễm trùng tai của tôi.","audioKind":"ex"},{"en":"Overusing antibiotics can make bacterial infections harder to treat, creating a serious challenge for public health.","vi":"Việc lạm dụng thuốc kháng sinh có thể khiến các bệnh nhiễm trùng do vi khuẩn trở nên khó điều trị hơn, tạo ra thách thức nghiêm trọng cho y tế công cộng.","audioKind":"ex2"}],"collocations":[{"en":"prescribe antibiotics","vi":"kê đơn thuốc kháng sinh"},{"en":"a course of antibiotics","vi":"một liệu trình kháng sinh"},{"en":"antibiotics resistance","vi":"tình trạng kháng kháng sinh"}],"wordFamily":["antibiotic (n.)","antibiotic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Là dạng số nhiều của \"antibiotic\"; thuốc kháng sinh không thể điều trị nhiễm virus.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recreation', 'en-b2-30', 'recreation', '/ˌrekriˈeɪʃən/', 'B2', 'hoạt động giải trí; tiêu khiển', 'n.', 'recreational (adj.), recreationally (adv.)', 'Đồng nghĩa: leisure, relaxation', 'Từ recreation thường không đếm được khi chỉ sự giải trí; hãy phân biệt với re-creation (sự tạo lại).', 'I swim for recreation at the local leisure centre.', NULL, 'Tôi đi bơi để giải trí ở trung tâm thể thao địa phương.', '{"wordId":"recreation","ukIpa":"/ˌrekriˈeɪʃən/","usIpa":"/ˌrekriˈeɪʃən/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"Activities done for enjoyment and relaxation when not working.","vi":"hoạt động giải trí; tiêu khiển"}],"examples":[{"en":"I swim for recreation at the local leisure centre.","vi":"Tôi đi bơi để giải trí ở trung tâm thể thao địa phương.","audioKind":"ex"},{"en":"Access to green spaces encourages outdoor recreation and can improve both physical health and mental wellbeing.","vi":"Việc tiếp cận không gian xanh giúp khuyến khích các hoạt động giải trí ngoài trời và có thể cải thiện cả sức khỏe thể chất lẫn tinh thần.","audioKind":"ex2"}],"collocations":[{"en":"outdoor recreation","vi":"hoạt động giải trí ngoài trời"},{"en":"recreation centre","vi":"trung tâm văn hóa giải trí"},{"en":"for recreation","vi":"để giải trí"},{"en":"recreation facilities","vi":"cơ sở giải trí"}],"wordFamily":["recreational (adj.)","recreationally (adv.)"],"synonyms":["leisure","relaxation"],"antonyms":[],"tipVi":"Từ recreation thường không đếm được khi chỉ sự giải trí; hãy phân biệt với re-creation (sự tạo lại).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ward', 'en-b2-30', 'ward', '/wɔːrd/', 'B2', 'phòng bệnh; khu điều trị; phường; khu vực hành chính; đơn vị bầu cử; người được giám hộ; người dưới quyền bảo trợ của tòa án', 'n.', NULL, NULL, 'Khi làm động từ thường dùng với cấu trúc ward off, mang ý nghĩa ngăn chặn, xua đuổi.', 'A nurse brought fresh blankets into the children''s ward.', NULL, 'Một y tá đã mang những chiếc chăn mới vào phòng bệnh nhi.', '{"wordId":"ward","ukIpa":"/wɔːd/","usIpa":"/wɔːrd/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"a hospital room or section for patients receiving similar care","vi":"phòng bệnh; khu điều trị"},{"pos":"n.","en":"a local district used for administration or elections","vi":"phường; khu vực hành chính; đơn vị bầu cử"},{"pos":"n.","en":"a person legally protected by a guardian or court","vi":"người được giám hộ; người dưới quyền bảo trợ của tòa án"}],"examples":[{"en":"A nurse brought fresh blankets into the children''s ward.","vi":"Một y tá đã mang những chiếc chăn mới vào phòng bệnh nhi.","audioKind":"ex"},{"en":"Expanding hospital wards alone will not improve healthcare unless sufficient trained staff are also available.","vi":"Việc chỉ mở rộng các khu điều trị trong bệnh viện sẽ không thể cải thiện dịch vụ y tế trừ khi có đủ nhân viên được đào tạo.","audioKind":"ex2"}],"collocations":[{"en":"hospital ward","vi":"phòng bệnh trong viện"},{"en":"maternity ward","vi":"khoa sản"},{"en":"electoral ward","vi":"đơn vị bầu cử"},{"en":"ward off infection","vi":"phòng tránh lây nhiễm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi làm động từ thường dùng với cấu trúc ward off, mang ý nghĩa ngăn chặn, xua đuổi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_casualty', 'en-b2-30', 'casualty', '/ˈkæʒuəlti/', 'B2', 'người bị thương hoặc thiệt mạng (trong tai nạn, xung đột, thảm họa); nạn nhân; vật hy sinh (bị tổn hại bởi hoàn cảnh hoặc sự thay đổi)', 'n.', NULL, 'Đồng nghĩa: victim', 'Bao gồm cả người bị thương và người thiệt mạng, không đồng nghĩa với fatality (chỉ người chết).', 'The ambulance took the casualty to a nearby hospital.', NULL, 'Xe cứu thương đã đưa nạn nhân đến một bệnh viện gần đó.', '{"wordId":"casualty","ukIpa":"/ˈkæʒuəlti/","usIpa":"/ˈkæʒuəlti/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"Someone injured or killed in an accident, conflict, or disaster.","vi":"người bị thương hoặc thiệt mạng (trong tai nạn, xung đột, thảm họa)"},{"pos":"n.","en":"Someone or something harmed by a situation or change.","vi":"nạn nhân; vật hy sinh (bị tổn hại bởi hoàn cảnh hoặc sự thay đổi)"}],"examples":[{"en":"The ambulance took the casualty to a nearby hospital.","vi":"Xe cứu thương đã đưa nạn nhân đến một bệnh viện gần đó.","audioKind":"ex"},{"en":"Improved building standards can reduce the number of casualties when earthquakes strike densely populated urban areas.","vi":"Các tiêu chuẩn xây dựng được cải thiện có thể làm giảm số lượng thương vong khi động đất xảy ra ở các khu vực đô thị đông dân cư.","audioKind":"ex2"}],"collocations":[{"en":"civilian casualties","vi":"thương vong dân sự"},{"en":"heavy casualties","vi":"thương vong nặng nề"},{"en":"a casualty of the recession","vi":"nạn nhân của cuộc suy thoái"}],"wordFamily":[],"synonyms":["victim"],"antonyms":[],"tipVi":"Bao gồm cả người bị thương và người thiệt mạng, không đồng nghĩa với fatality (chỉ người chết).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stroke', 'en-b2-30', 'stroke', '/stroʊk/', 'B2', 'cú đột quỵ (não); động tác đánh, quạt, khua (tay, chân, dụng cụ); vuốt ve nhẹ nhàng', 'n.', NULL, NULL, 'Bệnh đột quỵ dùng cụm have a stroke, không nhầm lẫn với đau tim (heart attack).', 'The cat purred while I stroked its soft fur.', NULL, 'Con mèo kêu gừ gừ trong lúc tôi vuốt ve bộ lông mềm mại của nó.', '{"wordId":"stroke","ukIpa":"/strəʊk/","usIpa":"/stroʊk/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"Sudden brain damage caused by interrupted blood flow or bleeding.","vi":"cú đột quỵ (não)"},{"pos":"n.","en":"One complete movement of a limb, tool, or brush.","vi":"động tác đánh, quạt, khua (tay, chân, dụng cụ)"},{"pos":"v.","en":"To move your hand gently over a surface repeatedly.","vi":"vuốt ve nhẹ nhàng"}],"examples":[{"en":"The cat purred while I stroked its soft fur.","vi":"Con mèo kêu gừ gừ trong lúc tôi vuốt ve bộ lông mềm mại của nó.","audioKind":"ex"},{"en":"Recognising the early symptoms of a stroke can help patients receive treatment before serious brain damage occurs.","vi":"Việc nhận biết các triệu chứng sớm của cơn đột quỵ có thể giúp bệnh nhân được điều trị trước khi tổn thương não nghiêm trọng xảy ra.","audioKind":"ex2"}],"collocations":[{"en":"have a stroke","vi":"bị đột quỵ"},{"en":"a brush stroke","vi":"một nét cọ"},{"en":"a swimming stroke","vi":"động tác bơi"},{"en":"stroke a cat","vi":"vuốt ve mèo"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Bệnh đột quỵ dùng cụm have a stroke, không nhầm lẫn với đau tim (heart attack).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_catching', 'en-b2-30', 'catching', '/ˈkætʃɪŋ/', 'B2', 'dễ lây; có tính truyền nhiễm; dễ lây lan; có sức lan tỏa', 'adj.', 'catch (v.)', 'Đồng nghĩa: contagious, infectious', 'Thường dùng làm vị ngữ; để chỉ giai điệu bắt tai, hãy dùng catchy thay vì catching.', 'Her laughter was catching, and soon everyone was smiling.', NULL, 'Tiếng cười của cô ấy rất dễ lan tỏa, và chẳng mấy chốc ai nấy đều mỉm cười.', '{"wordId":"catching","ukIpa":"/ˈkætʃɪŋ/","usIpa":"/ˈkætʃɪŋ/","cefr":"B2","topic":"health","senses":[{"pos":"adj.","en":"able to spread between people, like an illness or emotion","vi":"dễ lây; có tính truyền nhiễm; dễ lây lan; có sức lan tỏa"}],"examples":[{"en":"Her laughter was catching, and soon everyone was smiling.","vi":"Tiếng cười của cô ấy rất dễ lan tỏa, và chẳng mấy chốc ai nấy đều mỉm cười.","audioKind":"ex"},{"en":"Although enthusiasm can be catching, public health campaigns also need clear evidence to encourage lasting behavioural change.","vi":"Mặc dù sự nhiệt tình có thể lây lan sang người khác, các chiến dịch y tế công cộng vẫn cần có bằng chứng rõ ràng để khuyến khích sự thay đổi hành vi lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"a catching illness","vi":"bệnh truyền nhiễm"},{"en":"catching enthusiasm","vi":"sự nhiệt tình có sức lan tỏa"},{"en":"catching laughter","vi":"tiếng cười truyền cảm"}],"wordFamily":["catch (v.)"],"synonyms":["contagious","infectious"],"antonyms":[],"tipVi":"Thường dùng làm vị ngữ; để chỉ giai điệu bắt tai, hãy dùng catchy thay vì catching.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_undergo', 'en-b2-30', 'undergo', '/ˌʌndərˈɡoʊ/', 'B2', 'trải qua; chịu đựng; tiếp nhận (quá trình, sự thay đổi hoặc điều trị)', 'v.', NULL, 'Đồng nghĩa: experience', 'Dạng quá khứ là underwent, quá khứ phân tử là undergone; thường kết hợp trực tiếp với tân ngữ.', 'My uncle will undergo knee surgery early next week.', NULL, 'Chú của tôi sẽ phải trải qua ca phẫu thuật đầu gối vào đầu tuần tới.', '{"wordId":"undergo","ukIpa":"/ˌʌndəˈɡəʊ/","usIpa":"/ˌʌndərˈɡoʊ/","cefr":"B2","topic":"health","senses":[{"pos":"v.","en":"to experience a process, change, or treatment","vi":"trải qua; chịu đựng; tiếp nhận (quá trình, sự thay đổi hoặc điều trị)"}],"examples":[{"en":"My uncle will undergo knee surgery early next week.","vi":"Chú của tôi sẽ phải trải qua ca phẫu thuật đầu gối vào đầu tuần tới.","audioKind":"ex"},{"en":"Many coastal cities will undergo significant changes as rising sea levels force governments to reconsider urban planning.","vi":"Nhiều thành phố ven biển sẽ trải qua những thay đổi đáng kể khi mực nước biển dâng cao buộc chính phủ phải cân nhắc lại công tác quy hoạch đô thị.","audioKind":"ex2"}],"collocations":[{"en":"undergo surgery","vi":"trải qua phẫu thuật"},{"en":"undergo training","vi":"tham gia đào tạo"},{"en":"undergo significant changes","vi":"trải qua những thay đổi đáng kể"},{"en":"undergo tests","vi":"kiểm tra y tế"}],"wordFamily":[],"synonyms":["experience"],"antonyms":[],"tipVi":"Dạng quá khứ là underwent, quá khứ phân tử là undergone; thường kết hợp trực tiếp với tân ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cramp', 'en-b2-30', 'cramp', '/kræmp/', 'B2', 'chứng chuột rút; cơn đau thắt cơ; hạn chế; kìm hãm', 'n.', 'cramped (adj.), cramping (n.)', 'Đồng nghĩa: spasm, restrict', 'Biểu thị không gian chật hẹp dùng cramped, không dùng cramp làm tính từ.', 'A sudden cramp in my calf stopped me swimming.', NULL, 'Cơn chuột rút đột ngột ở bắp chân đã khiến tôi phải ngừng bơi.', '{"wordId":"cramp","ukIpa":"/kræmp/","usIpa":"/kræmp/","cefr":"B2","topic":"health","senses":[{"pos":"n.","en":"Sudden pain caused by a muscle tightening involuntarily.","vi":"chứng chuột rút; cơn đau thắt cơ"},{"pos":"v.","en":"To restrict someone''s movement, freedom, or ability to act.","vi":"hạn chế; kìm hãm"}],"examples":[{"en":"A sudden cramp in my calf stopped me swimming.","vi":"Cơn chuột rút đột ngột ở bắp chân đã khiến tôi phải ngừng bơi.","audioKind":"ex"},{"en":"Excessively strict classroom rules may cramp students'' creativity and discourage them from exploring unfamiliar ideas.","vi":"Quy tắc lớp học quá nghiêm ngặt có thể kìm hãm sự sáng tạo của học sinh và làm các em nản lòng trong việc khám phá những ý tưởng mới lạ.","audioKind":"ex2"}],"collocations":[{"en":"muscle cramp","vi":"chuột rút cơ bắp"},{"en":"stomach cramps","vi":"đau thắt dạ dày"},{"en":"menstrual cramps","vi":"đau bụng kinh"},{"en":"cramp someone''s style","vi":"làm mất tự nhiên; kìm hãm sự thể hiện của ai đó"}],"wordFamily":["cramped (adj.)","cramping (n.)"],"synonyms":["spasm","restrict"],"antonyms":[],"tipVi":"Biểu thị không gian chật hẹp dùng cramped, không dùng cramp làm tính từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_weaken', 'en-b2-30', 'weaken', '/ˈwiːkən/', 'B2', 'làm suy yếu; làm cho yếu đi; suy giảm', 'v.', 'weak (adj.), weakness (n.), weakly (adv.)', 'Đồng nghĩa: undermine · Trái nghĩa: strengthen', 'Từ này vừa có thể là ngoại động từ vừa là nội động từ: làm cho yếu đi hoặc tự trở nên yếu đi.', 'Too little sleep can weaken your ability to concentrate.', NULL, 'Ngủ quá ít có thể làm suy giảm khả năng tập trung của bạn.', '{"wordId":"weaken","ukIpa":"/ˈwiːkən/","usIpa":"/ˈwiːkən/","cefr":"B2","topic":"health","senses":[{"pos":"v.","en":"to become less strong, or make something less strong","vi":"làm suy yếu; làm cho yếu đi; suy giảm"}],"examples":[{"en":"Too little sleep can weaken your ability to concentrate.","vi":"Ngủ quá ít có thể làm suy giảm khả năng tập trung của bạn.","audioKind":"ex"},{"en":"Persistent unemployment can weaken local economies by reducing household spending and discouraging business investment.","vi":"Tình trạng thất nghiệp kéo dài có thể làm suy yếu nền kinh tế địa phương bằng cách giảm chi tiêu hộ gia đình và làm nản lòng hoạt động đầu tư của doanh nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"weaken the immune system","vi":"làm suy yếu hệ miễn dịch"},{"en":"weaken an argument","vi":"làm suy yếu một lập luận"},{"en":"weaken demand","vi":"làm giảm nhu cầu"}],"wordFamily":["weak (adj.)","weakness (n.)","weakly (adv.)"],"synonyms":["undermine"],"antonyms":["strengthen"],"tipVi":"Từ này vừa có thể là ngoại động từ vừa là nội động từ: làm cho yếu đi hoặc tự trở nên yếu đi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_muscular', 'en-b2-30', 'muscular', '/ˈmʌskjələr/', 'B2', 'vạm vỡ; cơ bắp lực lưỡng; thuộc về cơ bắp', 'adj.', 'muscle (n.)', NULL, 'Có thể chỉ cơ thể săn chắc, cơ bắp, hoặc chỉ liên quan đến cơ bắp nói chung.', 'The muscular swimmer lifted the heavy box easily.', NULL, 'Vận động viên bơi lội lực lưỡng đã dễ dàng nhấc bổng chiếc hộp nặng.', '{"wordId":"muscular","ukIpa":"/ˈmʌskjələ/","usIpa":"/ˈmʌskjələr/","cefr":"B2","topic":"health","senses":[{"pos":"adj.","en":"Having large, strong muscles.","vi":"vạm vỡ; cơ bắp lực lưỡng"},{"pos":"adj.","en":"Relating to the muscles of the body.","vi":"thuộc về cơ bắp"}],"examples":[{"en":"The muscular swimmer lifted the heavy box easily.","vi":"Vận động viên bơi lội lực lưỡng đã dễ dàng nhấc bổng chiếc hộp nặng.","audioKind":"ex"},{"en":"Regular resistance training can improve muscular strength and help older adults maintain their independence.","vi":"Việc tập luyện kháng lực thường xuyên có thể cải thiện sức mạnh cơ bắp và giúp người lớn tuổi duy trì khả năng tự lập.","audioKind":"ex2"}],"collocations":[{"en":"muscular strength","vi":"sức mạnh cơ bắp"},{"en":"muscular pain","vi":"đau cơ"},{"en":"muscular build","vi":"thể hình vạm vỡ"}],"wordFamily":["muscle (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể chỉ cơ thể săn chắc, cơ bắp, hoặc chỉ liên quan đến cơ bắp nói chung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_30_1', 'en-b2-30', 'Cách dùng “carbohydrate” (n.) — thức ăn chứa đường hoặc tinh bột cung cấp năng lượng', 'complex carbohydrates  ·  carbohydrate intake  ·  low-carbohydrate diet', 'Khi dùng chỉ chất dinh dưỡng, từ này có thể đếm được hoặc không; dùng số nhiều khi nói về các loại hoặc tổng thể.', NULL, '[{"hanzi":"Rice provides carbohydrate, which gives you energy for daily activities.","pinyin":"","meaning":"Cơm cung cấp carbohydrate, giúp bạn có năng lượng cho các hoạt động hàng ngày."},{"hanzi":"Although carbohydrates are an important energy source, public health guidance should distinguish wholegrain foods from products containing added sugars.","pinyin":"","meaning":"Mặc dù carbohydrate là nguồn năng lượng quan trọng, các hướng dẫn y tế công cộng vẫn nên phân biệt rõ thực phẩm ngũ cốc nguyên hạt với các sản phẩm chứa đường bổ sung."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_30_2', 'en-b2-30', 'Cách dùng “depression” (n.) — chứng trầm cảm; sự trầm uất', 'suffer from depression  ·  severe depression  ·  economic depression', 'Trầm cảm không đồng nghĩa với cảm giác buồn chán thoáng qua; cuộc suy thoái lớn thường dùng a depression.', 'Họ từ (Word Family): depress (v.), depressed (adj.), depressing (adj.)', '[{"hanzi":"Her doctor recommended regular counselling to help manage depression.","pinyin":"","meaning":"Bác sĩ của cô ấy khuyên nên tư vấn tâm lý định kỳ để giúp kiểm soát chứng trầm cảm."},{"hanzi":"Improving access to mental health services can help people with depression receive timely support and appropriate treatment.","pinyin":"","meaning":"Việc cải thiện khả năng tiếp cận các dịch vụ chăm sóc sức khỏe tinh thần có thể giúp bệnh nhân trầm cảm nhận được sự hỗ trợ kịp thời và điều trị phù hợp."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_30_3', 'en-b2-30', 'Cách dùng “recreation” (n.) — hoạt động giải trí; tiêu khiển', 'outdoor recreation  ·  recreation centre  ·  for recreation', 'Từ recreation thường không đếm được khi chỉ sự giải trí; hãy phân biệt với re-creation (sự tạo lại).', 'Họ từ (Word Family): recreational (adj.), recreationally (adv.) | Đồng nghĩa: leisure, relaxation', '[{"hanzi":"I swim for recreation at the local leisure centre.","pinyin":"","meaning":"Tôi đi bơi để giải trí ở trung tâm thể thao địa phương."},{"hanzi":"Access to green spaces encourages outdoor recreation and can improve both physical health and mental wellbeing.","pinyin":"","meaning":"Việc tiếp cận không gian xanh giúp khuyến khích các hoạt động giải trí ngoài trời và có thể cải thiện cả sức khỏe thể chất lẫn tinh thần."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_30_4', 'en-b2-30', 'Cách dùng “asthma” (n.) — bệnh hen suyễn', 'asthma attack  ·  severe asthma  ·  manage asthma', 'Là danh từ không đếm được; âm th không phát âm, có sự khác biệt về phụ âm giữa Anh-Anh và Anh-Mỹ.', 'Họ từ (Word Family): asthmatic (adj.)', '[{"hanzi":"My brother carries an inhaler to manage his asthma.","pinyin":"","meaning":"Anh trai tôi luôn mang theo ống hít để kiểm soát bệnh hen suyễn của mình."},{"hanzi":"Reducing urban air pollution can help prevent asthma attacks and improve the quality of life for residents.","pinyin":"","meaning":"Giảm ô nhiễm không khí đô thị có thể giúp ngăn ngừa các cơn hen suyễn phát cơn và nâng cao chất lượng cuộc sống cho cư dân."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_30_1', 'en-b2-30', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_30_1_1', 'ten_b2_30_1', 'disorder', 'A sleep disorder kept him awake most nights.', 'A sleep disorder kept him awake most nights.', '/dɪsˈɔːrdər/', 'Chứng rối loạn giấc ngủ khiến anh ấy thức trắng hầu hết các đêm.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_30_1_2', 'ten_b2_30_1', 'cope', 'I cope with busy mornings by preparing breakfast ahead.', 'I cope with busy mornings by preparing breakfast ahead.', '/koʊp/', 'Tôi đối phó với những buổi sáng bận rộn bằng cách chuẩn bị bữa sáng từ trước.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_30_1_3', 'ten_b2_30_1', 'carbohydrate', 'Rice provides carbohydrate, which gives you energy for daily activities.', 'Rice provides carbohydrate, which gives you energy for daily activities.', '/ˌkɑːrboʊˈhaɪdreɪt/', 'Cơm cung cấp carbohydrate, giúp bạn có năng lượng cho các hoạt động hàng ngày.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_30_1_4', 'ten_b2_30_1', 'bathe', 'Gently bathe your sore feet in warm water.', 'Gently bathe your sore feet in warm water.', '/beɪð/', 'Hãy nhẹ nhàng ngâm bàn chân đang đau nhức của bạn vào nước ấm.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_30_1_5', 'ten_b2_30_1', 'eyelid', 'A tiny grain of sand irritated my eyelid.', 'A tiny grain of sand irritated my eyelid.', '/ˈaɪlɪd/', 'Một hạt cát nhỏ làm mí mắt tôi bị cộm.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_30_1_6', 'ten_b2_30_1', 'outbreak', 'The flu outbreak kept several children home from school.', 'The flu outbreak kept several children home from school.', '/ˈaʊtbreɪk/', 'Vụ bùng phát bệnh cúm khiến mấy đứa trẻ phải nghỉ học ở nhà.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_30_1_7', 'ten_b2_30_1', 'consciousness', 'He regained consciousness shortly after the ambulance arrived.', 'He regained consciousness shortly after the ambulance arrived.', '/ˈkɑːnʃəsnəs/', 'Anh ấy đã lấy lại ý thức ngay sau khi xe cứu thương đến.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_30_1_8', 'ten_b2_30_1', 'thigh', 'My thighs ached after cycling up the steep hill.', 'My thighs ached after cycling up the steep hill.', '/θaɪ/', 'Cơ đùi của tôi bị đau nhức sau khi đạp xe lên đoạn dốc đứng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_30_1_1', 'en-b2-30', 'ten_b2_30_1', 'listening', 'listening', 'A sleep disorder kept him awake most nights.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bác sĩ đã kê đơn thuốc kháng sinh cho chứng nhiễm trùng tai của tôi.","Chứng rối loạn giấc ngủ khiến anh ấy thức trắng hầu hết các đêm.","Vụ bùng phát bệnh cúm khiến mấy đứa trẻ phải nghỉ học ở nhà.","Con mèo kêu gừ gừ trong lúc tôi vuốt ve bộ lông mềm mại của nó."]'::jsonb, 1, 'A sleep disorder kept him awake most nights. → Chứng rối loạn giấc ngủ khiến anh ấy thức trắng hầu hết các đêm.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_30_1_2', 'en-b2-30', 'ten_b2_30_1', 'listening', 'listening', 'I cope with busy mornings by preparing breakfast ahead.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những quả cam tươi này là nguồn cung cấp vitamin C dồi dào.","Một y tá đã mang những chiếc chăn mới vào phòng bệnh nhi.","Cơm cung cấp carbohydrate, giúp bạn có năng lượng cho các hoạt động hàng ngày.","Tôi đối phó với những buổi sáng bận rộn bằng cách chuẩn bị bữa sáng từ trước."]'::jsonb, 3, 'I cope with busy mornings by preparing breakfast ahead. → Tôi đối phó với những buổi sáng bận rộn bằng cách chuẩn bị bữa sáng từ trước.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_30_1_3', 'en-b2-30', 'ten_b2_30_1', 'listening', 'listening', 'Rice provides carbohydrate, which gives you energy for daily activities.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Con mèo kêu gừ gừ trong lúc tôi vuốt ve bộ lông mềm mại của nó.","Hãy nhẹ nhàng ngâm bàn chân đang đau nhức của bạn vào nước ấm.","Xe cứu thương đã đưa nạn nhân đến một bệnh viện gần đó.","Cơm cung cấp carbohydrate, giúp bạn có năng lượng cho các hoạt động hàng ngày."]'::jsonb, 3, 'Rice provides carbohydrate, which gives you energy for daily activities. → Cơm cung cấp carbohydrate, giúp bạn có năng lượng cho các hoạt động hàng ngày.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_30_2', 'en-b2-30', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_30_2_1', 'ten_b2_30_2', 'disorder', 'Early treatment of anxiety disorders can improve students'' wellbeing and help them participate more fully in education.', 'Early treatment of anxiety disorders can improve students'' wellbeing and help them participate more fully in education.', '/dɪsˈɔːrdər/', 'Việc điều trị sớm các chứng rối loạn lo âu có thể cải thiện sức khỏe tinh thần của học sinh và giúp các em tham gia học tập đầy đủ hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_30_2_2', 'ten_b2_30_2', 'cope', 'Schools should teach practical strategies that help students cope with examination stress and maintain their mental wellbeing.', 'Schools should teach practical strategies that help students cope with examination stress and maintain their mental wellbeing.', '/koʊp/', 'Nhà trường nên trang bị các chiến lược thực tế giúp học sinh đối phó với áp lực thi cử và duy trì sức khỏe tinh thần.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_30_2_3', 'ten_b2_30_2', 'carbohydrate', 'Although carbohydrates are an important energy source, public health guidance should distinguish wholegrain foods from products containing added sugars.', 'Although carbohydrates are an important energy source, public health guidance should distinguish wholegrain foods from products containing added sugars.', '/ˌkɑːrboʊˈhaɪdreɪt/', 'Mặc dù carbohydrate là nguồn năng lượng quan trọng, các hướng dẫn y tế công cộng vẫn nên phân biệt rõ thực phẩm ngũ cốc nguyên hạt với các sản phẩm chứa đường bổ sung.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_30_2_4', 'ten_b2_30_2', 'bathe', 'Residents need reliable access to clean water to bathe safely and maintain good personal hygiene.', 'Residents need reliable access to clean water to bathe safely and maintain good personal hygiene.', '/beɪð/', 'Cư dân cần được tiếp cận nguồn nước sạch đáng tin cậy để tắm rửa an toàn và duy trì vệ sinh cá nhân tốt.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_30_2_5', 'ten_b2_30_2', 'eyelid', 'The eyelids help protect the eyes from dust and spread moisture across their surface during blinking.', 'The eyelids help protect the eyes from dust and spread moisture across their surface during blinking.', '/ˈaɪlɪd/', 'Mí mắt giúp bảo vệ mắt khỏi bụi bẩn và phân bố độ ẩm đều trên bề mặt nhãn cầu khi chớp mắt.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_30_2_6', 'ten_b2_30_2', 'outbreak', 'Rapid access to reliable health information can help communities respond effectively to an outbreak of infectious disease.', 'Rapid access to reliable health information can help communities respond effectively to an outbreak of infectious disease.', '/ˈaʊtbreɪk/', 'Việc tiếp cận nhanh chóng với thông tin y tế đáng tin cậy có thể giúp các cộng đồng ứng phó hiệu quả với một đợt bùng phát dịch bệnh truyền nhiễm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_30_2_1', 'en-b2-30', 'ten_b2_30_2', 'listening', 'listening', 'Early treatment of anxiety disorders can improve students'' wellbeing and help them participate more fully in education.', NULL, 'Trong câu vừa nghe, từ “disorder” mang nghĩa nào sau đây?', '["cần gạt; đòn bẩy","rối loạn; chứng bệnh; sự suy giảm chức năng","động vật ăn thịt; động vật săn mồi","vụ sạt lở đất; lở đất"]'::jsonb, 1, '“disorder” (/dɪsˈɔːrdər/): rối loạn; chứng bệnh; sự suy giảm chức năng. Câu đầy đủ: Early treatment of anxiety disorders can improve students'' wellbeing and help them participate more fully in education.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_30_2_2', 'en-b2-30', 'ten_b2_30_2', 'listening', 'listening', 'Schools should teach practical strategies that help students cope with examination stress and maintain their mental wellbeing.', NULL, 'Trong câu vừa nghe, từ “cope” mang nghĩa nào sau đây?', '["mẫu; mẫu vật; vật mẫu","buổi hướng dẫn; buổi học kèm nhỏ","hướng ra ngoài; ra phía ngoài","đối phó; đương đầu; giải quyết"]'::jsonb, 3, '“cope” (/koʊp/): đối phó; đương đầu; giải quyết. Câu đầy đủ: Schools should teach practical strategies that help students cope with examination stress and maintain their mental wellbeing.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
