INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_30_1', 'en-b2-30', NULL, 'comprehensive_test', 'listening', 'disorder', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["vui mừng; hân hoan; mang lại niềm vui","rối loạn; chứng bệnh; sự suy giảm chức năng","chung; liên hợp; phối hợp","gần gũi; thân thiện; dễ gần"]'::jsonb, 1, 'disorder (/dɪsˈɔːrdər/) → rối loạn; chứng bệnh; sự suy giảm chức năng; sự lộn xộn; tình trạng bừa bãi; sự náo loạn; bạo động công cộng', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_30_2', 'en-b2-30', NULL, 'comprehensive_test', 'listening', 'I cope with busy mornings by preparing breakfast ahead.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bác sĩ đã kê đơn thuốc kháng sinh cho chứng nhiễm trùng tai của tôi.","Vụ bùng phát bệnh cúm khiến mấy đứa trẻ phải nghỉ học ở nhà.","Con mèo kêu gừ gừ trong lúc tôi vuốt ve bộ lông mềm mại của nó.","Tôi đối phó với những buổi sáng bận rộn bằng cách chuẩn bị bữa sáng từ trước."]'::jsonb, 3, 'I cope with busy mornings by preparing breakfast ahead. → Tôi đối phó với những buổi sáng bận rộn bằng cách chuẩn bị bữa sáng từ trước.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_30_3', 'en-b2-30', NULL, 'comprehensive_test', 'listening', 'carbohydrate', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["dốc; dốc đứng","tự vệ; phòng vệ chính đáng","thức ăn chứa đường hoặc tinh bột cung cấp năng lượng","phụ thuộc; lệ thuộc"]'::jsonb, 2, 'carbohydrate (/ˌkɑːrboʊˈhaɪdreɪt/) → thức ăn chứa đường hoặc tinh bột cung cấp năng lượng', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_30_4', 'en-b2-30', NULL, 'comprehensive_test', 'listening', 'Gently bathe your sore feet in warm water.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chứng rối loạn giấc ngủ khiến anh ấy thức trắng hầu hết các đêm.","Cơ đùi của tôi bị đau nhức sau khi đạp xe lên đoạn dốc đứng.","Hãy nhẹ nhàng ngâm bàn chân đang đau nhức của bạn vào nước ấm.","Chiếc xe đạp bị gỉ sét không còn phù hợp cho chuyến hành trình dài."]'::jsonb, 2, 'Gently bathe your sore feet in warm water. → Hãy nhẹ nhàng ngâm bàn chân đang đau nhức của bạn vào nước ấm.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_30_5', 'en-b2-30', NULL, 'comprehensive_test', 'listening', 'eyelid', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chắc chắn; có khả năng cao","trung thành; tận tụy","làm ngạc nhiên; làm kinh ngạc","mí mắt; mi mắt"]'::jsonb, 3, 'eyelid (/ˈaɪlɪd/) → mí mắt; mi mắt', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_30_6', 'en-b2-30', NULL, 'comprehensive_test', 'listening', 'The flu outbreak kept several children home from school.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một y tá đã mang những chiếc chăn mới vào phòng bệnh nhi.","Vận động viên bơi lội lực lưỡng đã dễ dàng nhấc bổng chiếc hộp nặng.","Vụ bùng phát bệnh cúm khiến mấy đứa trẻ phải nghỉ học ở nhà.","Anh ấy đã lấy lại ý thức ngay sau khi xe cứu thương đến."]'::jsonb, 2, 'The flu outbreak kept several children home from school. → Vụ bùng phát bệnh cúm khiến mấy đứa trẻ phải nghỉ học ở nhà.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
