INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_30_8', 'en-b2-30', NULL, 'comprehensive_test', 'listening', 'My thighs ached after cycling up the steep hill.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cơ đùi của tôi bị đau nhức sau khi đạp xe lên đoạn dốc đứng.","Chú của tôi sẽ phải trải qua ca phẫu thuật đầu gối vào đầu tuần tới.","Tôi đối phó với những buổi sáng bận rộn bằng cách chuẩn bị bữa sáng từ trước.","Những quả cam tươi này là nguồn cung cấp vitamin C dồi dào."]'::jsonb, 0, 'My thighs ached after cycling up the steep hill. → Cơ đùi của tôi bị đau nhức sau khi đạp xe lên đoạn dốc đứng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
