INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_30_18', 'en-b2-30', NULL, 'comprehensive_test', 'reading', NULL, 'Early treatment of anxiety disorders can improve students'' wellbeing and help them participate more fully in education.', 'Dựa vào câu trên, từ “disorder” có nghĩa phù hợp nhất là gì?', '["giận dữ; nổi giận đùng đùng","đều; đều đặn; cách đều nhau","bán chạy; có doanh số bán rất cao","rối loạn; chứng bệnh; sự suy giảm chức năng"]'::jsonb, 3, 'disorder: rối loạn; chứng bệnh; sự suy giảm chức năng; sự lộn xộn; tình trạng bừa bãi; sự náo loạn; bạo động công cộng. Dịch cả câu: Việc điều trị sớm các chứng rối loạn lo âu có thể cải thiện sức khỏe tinh thần của học sinh và giúp các em tham gia học tập đầy đủ hơn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_30_19', 'en-b2-30', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should teach practical strategies that help students cope with examination stress and maintain their mental wellbeing.', 'Dựa vào câu trên, từ “cope” có nghĩa phù hợp nhất là gì?', '["khẩu hiệu; biểu ngữ","trêu chọc; chế nhạo","đối phó; đương đầu; giải quyết","bộ xương; khung xương"]'::jsonb, 2, 'cope: đối phó; đương đầu; giải quyết. Dịch cả câu: Nhà trường nên trang bị các chiến lược thực tế giúp học sinh đối phó với áp lực thi cử và duy trì sức khỏe tinh thần.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_30_20', 'en-b2-30', NULL, 'comprehensive_test', 'reading', NULL, 'Although carbohydrates are an important energy source, public health guidance should distinguish wholegrain foods from products containing added sugars.', 'Dựa vào câu trên, từ “carbohydrate” có nghĩa phù hợp nhất là gì?', '["hôi hám; khó chịu; ghê tởm","thức ăn chứa đường hoặc tinh bột cung cấp năng lượng","sự bốc đồng; sự thôi thúc nhất thời","khái niệm; ý niệm"]'::jsonb, 1, 'carbohydrate: thức ăn chứa đường hoặc tinh bột cung cấp năng lượng. Dịch cả câu: Mặc dù carbohydrate là nguồn năng lượng quan trọng, các hướng dẫn y tế công cộng vẫn nên phân biệt rõ thực phẩm ngũ cốc nguyên hạt với các sản phẩm chứa đường bổ sung.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_30_21', 'en-b2-30', NULL, 'comprehensive_test', 'reading', NULL, 'Residents need reliable access to clean water to bathe safely and maintain good personal hygiene.', 'Dựa vào câu trên, từ “bathe” có nghĩa phù hợp nhất là gì?', '["nhà nhập khẩu; nước nhập khẩu","tắm; rửa sạch cơ thể","sao Kim","rộng thùng thình; rộng và lùng bùng"]'::jsonb, 1, 'bathe: tắm; rửa sạch cơ thể; rửa nhẹ nhàng (bộ phận cơ thể bằng chất lỏng); bơi lội; ngâm mình (trong biển hoặc hồ). Dịch cả câu: Cư dân cần được tiếp cận nguồn nước sạch đáng tin cậy để tắm rửa an toàn và duy trì vệ sinh cá nhân tốt.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_30_22', 'en-b2-30', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “chứng chuột rút; cơn đau thắt cơ”', '["cramp","obesity","progressive","seminar"]'::jsonb, 0, 'chứng chuột rút; cơn đau thắt cơ → cramp (/kræmp/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_30_23', 'en-b2-30', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “làm suy yếu; làm cho yếu đi; suy giảm”', '["inspection","weaken","recreational","fabulous"]'::jsonb, 1, 'làm suy yếu; làm cho yếu đi; suy giảm → weaken (/ˈwiːkən/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_30_24', 'en-b2-30', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “vạm vỡ; cơ bắp lực lưỡng”', '["microscope","muscular","bullet","expose"]'::jsonb, 1, 'vạm vỡ; cơ bắp lực lưỡng → muscular (/ˈmʌskjələr/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-31', 'en', 'Bài 31: Nghệ thuật & Sáng tạo (1) - CEFR B2', 'CEFR B2', 'B2 · Nghệ thuật', '22 từ vựng Tiếng Anh CEFR B2 chủ đề nghệ thuật & sáng tạo kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4031, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clarinet', 'en-b2-31', 'clarinet', '/ˌklærəˈnet/', 'B2', 'đàn clarinet; kèn clarinet', 'n.', 'clarinettist (n.)', NULL, 'Khi chơi nhạc cụ thường dùng play the clarinet, chú ý dùng mạo từ the.', 'My sister practises the clarinet quietly after dinner.', NULL, 'Em gái tôi chăm chỉ tập thổi kèn clarinet một cách yên tĩnh sau bữa tối.', '{"wordId":"clarinet","ukIpa":"/ˌklærəˈnet/","usIpa":"/ˌklærəˈnet/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"A woodwind instrument with a single reed and finger-operated keys.","vi":"đàn clarinet; kèn clarinet"}],"examples":[{"en":"My sister practises the clarinet quietly after dinner.","vi":"Em gái tôi chăm chỉ tập thổi kèn clarinet một cách yên tĩnh sau bữa tối.","audioKind":"ex"},{"en":"Learning to play the clarinet can help children develop concentration while encouraging participation in school orchestras.","vi":"Học chơi kèn clarinet có thể giúp trẻ em phát triển khả năng tập trung đồng thời khuyến khích tham gia vào các dàn nhạc của trường.","audioKind":"ex2"}],"collocations":[{"en":"play the clarinet","vi":"chơi kèn clarinet"},{"en":"a clarinet solo","vi":"bản độc tấu kèn clarinet"},{"en":"a clarinet player","vi":"người thổi kèn clarinet"}],"wordFamily":["clarinettist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chơi nhạc cụ thường dùng play the clarinet, chú ý dùng mạo từ the.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ballroom', 'en-b2-31', 'ballroom', '/ˈbɔːlruːm/', 'B2', 'phòng khiêu vũ; vũ trường', 'n.', NULL, NULL, '"Ballroom dancing" chỉ khiêu vũ giao tiếp/khiêu vũ cổ điển, không phải nhảy nhót ở hộp đêm.', 'Couples glided across the ballroom beneath a sparkling chandelier.', NULL, 'Các cặp đôi lướt nhẹ qua phòng khiêu vũ dưới ánh đèn chùm lấp lánh.', '{"wordId":"ballroom","ukIpa":"/ˈbɔːlruːm/","usIpa":"/ˈbɔːlruːm/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"A large room used for formal social dancing","vi":"phòng khiêu vũ; vũ trường"}],"examples":[{"en":"Couples glided across the ballroom beneath a sparkling chandelier.","vi":"Các cặp đôi lướt nhẹ qua phòng khiêu vũ dưới ánh đèn chùm lấp lánh.","audioKind":"ex"},{"en":"Restoring the historic ballroom could attract visitors while providing local residents with a valuable space for cultural events.","vi":"Việc trùng tu phòng khiêu vũ lịch sử này có thể thu hút du khách, đồng thời mang lại cho người dân địa phương một không gian quý giá cho các sự kiện văn hóa.","audioKind":"ex2"}],"collocations":[{"en":"ballroom dancing","vi":"khiêu vũ thể thao; khiêu vũ giao tiếp"},{"en":"a hotel ballroom","vi":"phòng khiêu vũ khách sạn"},{"en":"a grand ballroom","vi":"phòng khiêu vũ lộng lẫy"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"\"Ballroom dancing\" chỉ khiêu vũ giao tiếp/khiêu vũ cổ điển, không phải nhảy nhót ở hộp đêm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plot', 'en-b2-31', 'plot', '/plɑːt/', 'B2', 'cốt truyện; tình tiết; mảnh đất nhỏ; âm mưu; mưu đồ', 'n.', 'plotter (n)', 'Đồng nghĩa: storyline, conspire', 'Plot chỉ cốt truyện; khi làm động từ còn có thể mang nghĩa vẽ biểu đồ dữ liệu.', 'The film had a simple but exciting plot.', NULL, 'Bộ phim có cốt truyện giản dị nhưng lôi cuốn.', '{"wordId":"plot","ukIpa":"/plɒt/","usIpa":"/plɑːt/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"the connected events that make up a story","vi":"cốt truyện; tình tiết"},{"pos":"n.","en":"a small piece of land used for a particular purpose","vi":"mảnh đất nhỏ"},{"pos":"v.","en":"secretly plan something harmful or dishonest","vi":"âm mưu; mưu đồ"}],"examples":[{"en":"The film had a simple but exciting plot.","vi":"Bộ phim có cốt truyện giản dị nhưng lôi cuốn.","audioKind":"ex"},{"en":"Community gardens allow residents to grow vegetables on a small plot, improving access to fresh food.","vi":"Các khu vườn cộng đồng cho phép cư dân trồng rau trên một mảnh đất nhỏ, giúp họ tiếp cận thực phẩm tươi dễ dàng hơn.","audioKind":"ex2"}],"collocations":[{"en":"a complex plot","vi":"cốt truyện phức tạp"},{"en":"a plot of land","vi":"một mảnh đất"},{"en":"a garden plot","vi":"mảnh đất trồng rau"},{"en":"plot against someone","vi":"âm mưu chống lại ai đó"}],"wordFamily":["plotter (n)"],"synonyms":["storyline","conspire"],"antonyms":[],"tipVi":"Plot chỉ cốt truyện; khi làm động từ còn có thể mang nghĩa vẽ biểu đồ dữ liệu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_soundtrack', 'en-b2-31', 'soundtrack', '/ˈsaʊndtræk/', 'B2', 'nhạc phim; phần âm thanh', 'n.', NULL, NULL, 'Không chỉ chỉ phần nhạc nền, từ này còn có thể chỉ toàn bộ phần âm thanh bao gồm cả lời thoại và hiệu ứng.', 'I listened to the film''s soundtrack on the bus.', NULL, 'Tôi đã nghe phần nhạc phim đó trên xe buýt.', '{"wordId":"soundtrack","ukIpa":"/ˈsaʊndtræk/","usIpa":"/ˈsaʊndtræk/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"The recorded music, speech, and sounds accompanying a film or programme.","vi":"nhạc phim; phần âm thanh"}],"examples":[{"en":"I listened to the film''s soundtrack on the bus.","vi":"Tôi đã nghe phần nhạc phim đó trên xe buýt.","audioKind":"ex"},{"en":"A carefully chosen soundtrack can strengthen a documentary''s emotional impact without distracting viewers from its central message.","vi":"Một bản nhạc phim được chọn lọc kỹ càng có thể làm tăng sức lay động cảm xúc của bộ phim tài liệu mà không làm người xem xao lãng khỏi thông điệp chính.","audioKind":"ex2"}],"collocations":[{"en":"a film soundtrack","vi":"nhạc phim"},{"en":"an original soundtrack","vi":"nhạc phim gốc"},{"en":"compose a soundtrack","vi":"sáng tác nhạc phim"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Không chỉ chỉ phần nhạc nền, từ này còn có thể chỉ toàn bộ phần âm thanh bao gồm cả lời thoại và hiệu ứng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_masterpiece', 'en-b2-31', 'masterpiece', '/ˈmæstərpiːs/', 'B2', 'kiệt tác; tác phẩm để đời', 'n.', NULL, NULL, 'Thường chỉ tác phẩm, không dùng để chỉ một người có tài năng xuất chúng.', 'Everyone stopped to admire the masterpiece above the fireplace.', NULL, 'Mọi người đều dừng lại để chiêm ngưỡng bức kiệt tác phía trên lò sưởi.', '{"wordId":"masterpiece","ukIpa":"/ˈmɑːstəpiːs/","usIpa":"/ˈmæstərpiːs/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"an exceptionally fine work of art, literature, or skill","vi":"kiệt tác; tác phẩm để đời"}],"examples":[{"en":"Everyone stopped to admire the masterpiece above the fireplace.","vi":"Mọi người đều dừng lại để chiêm ngưỡng bức kiệt tác phía trên lò sưởi.","audioKind":"ex"},{"en":"Displaying a masterpiece in a public museum allows people from different backgrounds to appreciate artistic achievement.","vi":"Việc trưng bày một kiệt tác trong bảo tàng công cộng cho phép mọi người từ các nền tảng khác nhau đánh giá cao các thành tựu nghệ thuật.","audioKind":"ex2"}],"collocations":[{"en":"a literary masterpiece","vi":"một kiệt tác văn học"},{"en":"an artistic masterpiece","vi":"một kiệt tác nghệ thuật"},{"en":"create a masterpiece","vi":"tạo ra một kiệt tác"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ tác phẩm, không dùng để chỉ một người có tài năng xuất chúng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_symphony', 'en-b2-31', 'symphony', '/ˈsɪmfəni/', 'B2', 'bản giao hưởng', 'n.', 'symphonic (adj.)', NULL, 'symphony chỉ bản giao hưởng; dàn nhạc giao hưởng dùng symphony orchestra.', 'We listened to a symphony while cooking dinner.', NULL, 'Chúng tôi đã nghe một bản giao hưởng trong khi nấu bữa tối.', '{"wordId":"symphony","ukIpa":"/ˈsɪmfəni/","usIpa":"/ˈsɪmfəni/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"a long orchestral composition, usually divided into several movements","vi":"bản giao hưởng"}],"examples":[{"en":"We listened to a symphony while cooking dinner.","vi":"Chúng tôi đã nghe một bản giao hưởng trong khi nấu bữa tối.","audioKind":"ex"},{"en":"Performing a symphony requires close cooperation among musicians, demonstrating the importance of teamwork in the arts.","vi":"Trình diễn một bản giao hưởng đòi hỏi sự hợp tác chặt chẽ giữa các nhạc sĩ, minh chứng cho tầm quan trọng của tinh thần đồng đội trong nghệ thuật.","audioKind":"ex2"}],"collocations":[{"en":"compose a symphony","vi":"sáng tác một bản giao hưởng"},{"en":"perform a symphony","vi":"biểu diễn một bản giao hưởng"},{"en":"symphony orchestra","vi":"dàn nhạc giao hưởng"}],"wordFamily":["symphonic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"symphony chỉ bản giao hưởng; dàn nhạc giao hưởng dùng symphony orchestra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_layout', 'en-b2-31', 'layout', '/ˈleɪaʊt/', 'B2', 'bố cục; cách bài trí; thiết kế trang', 'n.', 'lay out (v.)', 'Đồng nghĩa: arrangement', 'Danh từ layout viết liền thành một từ; động từ lay out viết tách rời.', 'We changed the kitchen layout to create more space.', NULL, 'Chúng tôi đã thay đổi bố cục nhà bếp để tạo thêm không gian.', '{"wordId":"layout","ukIpa":"/ˈleɪaʊt/","usIpa":"/ˈleɪaʊt/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"the way parts of a space or page are arranged","vi":"bố cục; cách bài trí; thiết kế trang"}],"examples":[{"en":"We changed the kitchen layout to create more space.","vi":"Chúng tôi đã thay đổi bố cục nhà bếp để tạo thêm không gian.","audioKind":"ex"},{"en":"A clear website layout helps users find essential information quickly and improves access to public services.","vi":"Bố cục trang web rõ ràng giúp người dùng nhanh chóng tìm thấy thông tin quan trọng và cải thiện khả năng tiếp cận các dịch vụ công.","audioKind":"ex2"}],"collocations":[{"en":"page layout","vi":"bố cục trang"},{"en":"room layout","vi":"bố trí phòng"},{"en":"an open-plan layout","vi":"bố cục không gian mở"}],"wordFamily":["lay out (v.)"],"synonyms":["arrangement"],"antonyms":[],"tipVi":"Danh từ layout viết liền thành một từ; động từ lay out viết tách rời.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_best-selling', 'en-b2-31', 'best-selling', '/ˌbest ˈselɪŋ/', 'B2', 'bán chạy; có doanh số bán rất cao', 'adj.', 'bestseller (n.), sell (v.), seller (n.)', NULL, 'best-selling làm tính từ; bestseller là danh từ chỉ sách bán chạy hoặc mặt hàng bán chạy.', 'I borrowed her best-selling cookbook and tried the soup.', NULL, 'Tôi đã mượn cuốn sách nấu ăn bán chạy nhất của cô ấy và làm thử món súp.', '{"wordId":"best-selling","ukIpa":"/ˌbest ˈselɪŋ/","usIpa":"/ˌbest ˈselɪŋ/","cefr":"B2","topic":"arts","senses":[{"pos":"adj.","en":"selling in very large quantities compared with similar products","vi":"bán chạy; có doanh số bán rất cao"}],"examples":[{"en":"I borrowed her best-selling cookbook and tried the soup.","vi":"Tôi đã mượn cuốn sách nấu ăn bán chạy nhất của cô ấy và làm thử món súp.","audioKind":"ex"},{"en":"Best-selling novels can encourage wider reading, although commercial success does not necessarily indicate literary quality.","vi":"Những cuốn tiểu thuyết bán chạy có thể thúc đẩy thói quen đọc sách rộng rãi hơn, mặc dù thành công về mặt thương mại không nhất thiết phản ánh chất lượng văn học.","audioKind":"ex2"}],"collocations":[{"en":"best-selling novel","vi":"tiểu thuyết bán chạy"},{"en":"best-selling author","vi":"tác giả có sách bán chạy nhất"},{"en":"best-selling product","vi":"sản phẩm bán chạy"}],"wordFamily":["bestseller (n.)","sell (v.)","seller (n.)"],"synonyms":[],"antonyms":[],"tipVi":"best-selling làm tính từ; bestseller là danh từ chỉ sách bán chạy hoặc mặt hàng bán chạy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_verse', 'en-b2-31', 'verse', '/vɝːs/', 'B2', 'thơ; thơ ca; bài thơ có vần; khổ thơ; đoạn lời bài hát', 'n.', 'versification (n.), versify (v.)', 'Đồng nghĩa: poetry · Trái nghĩa: prose', 'Khi chỉ chung chung thể loại thơ/vần thì không đếm được; khi chỉ một khổ thơ cụ thể thì đếm được.', 'We sang the first verse together around the piano.', NULL, 'Chúng tôi cùng nhau hát đoạn lời đầu tiên bên cây đàn piano.', '{"wordId":"verse","ukIpa":"/vɜːs/","usIpa":"/vɝːs/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"Writing arranged with rhythm, often using rhyme.","vi":"thơ; thơ ca; bài thơ có vần"},{"pos":"n.","en":"A group of lines forming part of a poem or song.","vi":"khổ thơ; đoạn lời bài hát"}],"examples":[{"en":"We sang the first verse together around the piano.","vi":"Chúng tôi cùng nhau hát đoạn lời đầu tiên bên cây đàn piano.","audioKind":"ex"},{"en":"Studying verse can help language learners recognise rhythm and explore how writers convey complex emotions.","vi":"Việc nghiên cứu thơ ca có thể giúp người học ngôn ngữ nhận biết nhịp điệu và khám phá cách các nhà văn truyền tải cảm xúc phức tạp.","audioKind":"ex2"}],"collocations":[{"en":"free verse","vi":"thơ tự do"},{"en":"blank verse","vi":"thơ không vần"},{"en":"in verse","vi":"bằng hình thức thơ"},{"en":"the opening verse","vi":"khổ thơ mở đầu"}],"wordFamily":["versification (n.)","versify (v.)"],"synonyms":["poetry"],"antonyms":["prose"],"tipVi":"Khi chỉ chung chung thể loại thơ/vần thì không đếm được; khi chỉ một khổ thơ cụ thể thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_classic', 'en-b2-31', 'classic', '/ˈklæsɪk/', 'B2', 'kinh điển; có giá trị lâu bền; điển hình; tác phẩm kinh điển', 'adj.', 'classical (adj.), classically (adv.)', NULL, 'classic chỉ kinh điển hoặc điển hình; âm nhạc cổ điển dùng classical.', 'We watched a classic film together after dinner.', NULL, 'Chúng tôi cùng nhau xem một bộ phim kinh điển sau bữa tối.', '{"wordId":"classic","ukIpa":"/ˈklæsɪk/","usIpa":"/ˈklæsɪk/","cefr":"B2","topic":"arts","senses":[{"pos":"adj.","en":"Widely admired for lasting quality and value.","vi":"kinh điển; có giá trị lâu bền"},{"pos":"adj.","en":"Showing the most recognizable features of a particular kind.","vi":"điển hình; kinh điển"},{"pos":"n.","en":"A work admired over time for its excellent quality.","vi":"tác phẩm kinh điển"}],"examples":[{"en":"We watched a classic film together after dinner.","vi":"Chúng tôi cùng nhau xem một bộ phim kinh điển sau bữa tối.","audioKind":"ex"},{"en":"This housing project is a classic example of how thoughtful design can improve urban life.","vi":"Dự án nhà ở này là một ví dụ điển hình về việc thiết kế chu đáo có thể cải thiện đời sống đô thị như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"classic example","vi":"ví dụ điển hình"},{"en":"classic novel","vi":"tiểu thuyết kinh điển"},{"en":"timeless classic","vi":"tác phẩm kinh điển vượt thời gian"}],"wordFamily":["classical (adj.)","classically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"classic chỉ kinh điển hoặc điển hình; âm nhạc cổ điển dùng classical.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_applause', 'en-b2-31', 'applause', '/əˈplɔːz/', 'B2', 'tiếng vỗ tay; tràng pháo tay; sự tán dương; lời ca ngợi', 'n.', 'applaud (v.)', NULL, 'Là danh từ không đếm được; cụm ''một tràng pháo tay'' dùng a round of applause.', 'The audience burst into applause as the curtain fell.', NULL, 'Khán giả vỡ oà trong tràng pháo tay khi tấm màn hạ xuống.', '{"wordId":"applause","ukIpa":"/əˈplɔːz/","usIpa":"/əˈplɔːz/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"the sound of people clapping to show approval","vi":"tiếng vỗ tay; tràng pháo tay"},{"pos":"n.","en":"strong approval or praise for someone or something","vi":"sự tán dương; lời ca ngợi"}],"examples":[{"en":"The audience burst into applause as the curtain fell.","vi":"Khán giả vỡ oà trong tràng pháo tay khi tấm màn hạ xuống.","audioKind":"ex"},{"en":"The proposal received widespread applause for making public transport more accessible to passengers with disabilities.","vi":"Đề xuất này nhận được sự ca ngợi rộng rãi vì giúp phương tiện công cộng trở nên thuận tiện hơn cho hành khách khuyết tật.","audioKind":"ex2"}],"collocations":[{"en":"a round of applause","vi":"một tràng pháo tay"},{"en":"thunderous applause","vi":"tiếng vỗ tay như sấm"},{"en":"burst into applause","vi":"bật tiếng vỗ tay"}],"wordFamily":["applaud (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ không đếm được; cụm ''một tràng pháo tay'' dùng a round of applause.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_carve', 'en-b2-31', 'carve', '/kɑːrv/', 'B2', 'chạm trổ; khắc gỗ hoặc đá; thái thịt đã nấu thành lát để dọn ăn', 'v.', 'carver (n.), carving (n.)', 'Đồng nghĩa: sculpt', 'carve nhấn mạnh việc gọt đẽo tạo hình; carve out a career có nghĩa là tự thân gầy dựng sự nghiệp.', 'My grandfather carved a little bird from soft wood.', NULL, 'Ông tôi đã chạm trổ một chú chim nhỏ từ một khúc gỗ mềm.', '{"wordId":"carve","ukIpa":"/kɑːv/","usIpa":"/kɑːrv/","cefr":"B2","topic":"arts","senses":[{"pos":"v.","en":"to shape wood or stone by cutting away material","vi":"chạm trổ; khắc gỗ hoặc đá"},{"pos":"v.","en":"to cut cooked meat into slices for serving","vi":"thái thịt đã nấu thành lát để dọn ăn"}],"examples":[{"en":"My grandfather carved a little bird from soft wood.","vi":"Ông tôi đã chạm trổ một chú chim nhỏ từ một khúc gỗ mềm.","audioKind":"ex"},{"en":"Local artisans carve traditional patterns into wooden furniture, preserving cultural skills while creating products for modern homes.","vi":"Các nghệ nhân địa phương khắc các họa tiết truyền thống lên đồ nội thất bằng gỗ, vừa gìn giữ kỹ năng văn hóa vừa tạo ra các sản phẩm cho ngôi nhà hiện đại.","audioKind":"ex2"}],"collocations":[{"en":"carve wood","vi":"chạm khắc gỗ"},{"en":"carve a statue","vi":"tạc tượng"},{"en":"carve meat","vi":"thái thịt thành lát"},{"en":"carve out a career","vi":"gầy dựng sự nghiệp"}],"wordFamily":["carver (n.)","carving (n.)"],"synonyms":["sculpt"],"antonyms":[],"tipVi":"carve nhấn mạnh việc gọt đẽo tạo hình; carve out a career có nghĩa là tự thân gầy dựng sự nghiệp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_marble', 'en-b2-31', 'marble', '/ˈmɑːrbəl/', 'B2', 'đá cẩm thạch; đá hoa; hòn bi; bi thủy tinh', 'n.', NULL, NULL, 'Khi chỉ đá cẩm thạch thì đây là danh từ không đếm được; khi chỉ hòn bi thì đếm được.', 'The cool marble floor felt smooth under my feet.', NULL, 'Sàn đá cẩm thạch mát lạnh bước lên rất nhẵn và mịn.', '{"wordId":"marble","ukIpa":"/ˈmɑːbəl/","usIpa":"/ˈmɑːrbəl/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"a hard stone with patterns, used for buildings and sculptures","vi":"đá cẩm thạch; đá hoa"},{"pos":"n.","en":"a small glass ball used in children''s games","vi":"hòn bi; bi thủy tinh"}],"examples":[{"en":"The cool marble floor felt smooth under my feet.","vi":"Sàn đá cẩm thạch mát lạnh bước lên rất nhẵn và mịn.","audioKind":"ex"},{"en":"Although marble enhances the appearance of public buildings, extracting it can damage surrounding landscapes and habitats.","vi":"Mặc dù đá cẩm thạch làm tăng vẻ đẹp cho các công trình công cộng, việc khai thác nó có thể tàn phá cảnh quan và môi trường sống xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"marble floor","vi":"sàn đá cẩm thạch"},{"en":"marble statue","vi":"tượng đá cẩm thạch"},{"en":"play marbles","vi":"chơi bắn bi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ đá cẩm thạch thì đây là danh từ không đếm được; khi chỉ hòn bi thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ceramics', 'en-b2-31', 'ceramics', '/səˈræmɪks/', 'B2', 'nghệ thuật gốm sứ; nghề làm gốm; đồ gốm; sản phẩm bằng sứ', 'n.', 'ceramic (adj.), ceramist (n.)', 'Đồng nghĩa: pottery', 'Chỉ nghệ thuật làm gốm thì dùng số ít; chỉ các sản phẩm gốm thì dùng số nhiều.', 'I started learning ceramics at a local studio.', NULL, 'Tôi bắt đầu học làm gốm tại một xưởng thủ công địa phương.', '{"wordId":"ceramics","ukIpa":"/səˈræmɪks/","usIpa":"/səˈræmɪks/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"the art and process of making objects from fired clay","vi":"nghệ thuật gốm sứ; nghề làm gốm"},{"pos":"n.","en":"objects made from clay and hardened by heat","vi":"đồ gốm; sản phẩm bằng sứ"}],"examples":[{"en":"I started learning ceramics at a local studio.","vi":"Tôi bắt đầu học làm gốm tại một xưởng thủ công địa phương.","audioKind":"ex"},{"en":"Traditional ceramics can attract tourists while providing a reliable source of income for local craftspeople.","vi":"Các sản phẩm gốm sứ truyền thống có thể thu hút khách du lịch đồng thời tạo ra nguồn thu nhập ổn định cho các nghệ nhân địa phương.","audioKind":"ex2"}],"collocations":[{"en":"ceramics class","vi":"lớp học làm gốm"},{"en":"traditional ceramics","vi":"đồ gốm truyền thống"},{"en":"ceramics studio","vi":"xưởng gốm sứ"}],"wordFamily":["ceramic (adj.)","ceramist (n.)"],"synonyms":["pottery"],"antonyms":[],"tipVi":"Chỉ nghệ thuật làm gốm thì dùng số ít; chỉ các sản phẩm gốm thì dùng số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_graphic', 'en-b2-31', 'graphic', '/ˈɡræfɪk/', 'B2', 'thuộc về đồ họa, hình ảnh hoặc thiết kế trực quan; mô tả rất sinh động, chi tiết (thường bao gồm cả những chi tiết khó chịu); hình ảnh đồ họa, biểu đồ dùng để trình bày thông tin', 'adj.', 'graphically (adv.), graphics (n.)', 'Đồng nghĩa: visual, vivid', 'Cụm "graphic description" thường chỉ những miêu tả chi tiết đến mức gây khó chịu.', 'My cousin studies graphic design and makes colourful posters.', NULL, 'Em họ tôi học thiết kế đồ họa và làm ra những tấm áp phích đầy màu sắc.', '{"wordId":"graphic","ukIpa":"/ˈɡræfɪk/","usIpa":"/ˈɡræfɪk/","cefr":"B2","topic":"arts","senses":[{"pos":"adj.","en":"Relating to pictures, drawings, or visual design.","vi":"thuộc về đồ họa, hình ảnh hoặc thiết kế trực quan"},{"pos":"adj.","en":"Describing something very clearly, often with unpleasant details.","vi":"mô tả rất sinh động, chi tiết (thường bao gồm cả những chi tiết khó chịu)"},{"pos":"n.","en":"An image or diagram used to present information.","vi":"hình ảnh đồ họa, biểu đồ dùng để trình bày thông tin"}],"examples":[{"en":"My cousin studies graphic design and makes colourful posters.","vi":"Em họ tôi học thiết kế đồ họa và làm ra những tấm áp phích đầy màu sắc.","audioKind":"ex"},{"en":"Effective graphic design can make complex health information easier for the general public to understand.","vi":"Thiết kế đồ họa hiệu quả có thể giúp công chúng dễ dàng hiểu các thông tin y tế phức tạp hơn.","audioKind":"ex2"}],"collocations":[{"en":"graphic design","vi":"thiết kế đồ họa"},{"en":"a graphic designer","vi":"một nhà thiết kế đồ họa"},{"en":"a graphic description","vi":"một mô tả sinh động chi tiết"}],"wordFamily":["graphically (adv.)","graphics (n.)"],"synonyms":["visual","vivid"],"antonyms":[],"tipVi":"Cụm \"graphic description\" thường chỉ những miêu tả chi tiết đến mức gây khó chịu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cast', 'en-b2-31', 'cast', '/kæst/', 'B2', 'dàn diễn viên; tập thể diễn viên; ném; quăng; chiếu (ánh sáng/bóng râm); phân vai; chọn diễn viên', 'n.', 'casting (n.), recast (v.)', 'Đồng nghĩa: throw, hurl', 'Dạng quá khứ và phân từ hai đều là cast; danh từ chỉ dàn diễn viên dùng ở hình thức số ít.', 'The entire cast came outside to greet the audience.', NULL, 'Toàn bộ dàn diễn viên đã bước ra ngoài để chào khán giả.', '{"wordId":"cast","ukIpa":"/kɑːst/","usIpa":"/kæst/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"All the actors appearing in a film or play.","vi":"dàn diễn viên; tập thể diễn viên"},{"pos":"v.","en":"To throw something or send light or shadow onto something.","vi":"ném; quăng; chiếu (ánh sáng/bóng râm)"},{"pos":"v.","en":"To choose an actor for a particular role.","vi":"phân vai; chọn diễn viên"}],"examples":[{"en":"The entire cast came outside to greet the audience.","vi":"Toàn bộ dàn diễn viên đã bước ra ngoài để chào khán giả.","audioKind":"ex"},{"en":"Directors who cast actors from diverse backgrounds can help challenge stereotypes and broaden audiences'' understanding of society.","vi":"Các đạo diễn tuyển chọn diễn viên từ nhiều nền tảng đa dạng có thể giúp phá vỡ định kiến và mở rộng sự hiểu biết của khán giả về xã hội.","audioKind":"ex2"}],"collocations":[{"en":"a supporting cast","vi":"dàn diễn viên phụ"},{"en":"cast a shadow","vi":"gieo bóng râm; tạo bóng râm"},{"en":"cast doubt on","vi":"gieo rắc nghi ngờ; làm dấy lên nghi ngờ"},{"en":"cast someone as","vi":"giao vai diễn cho ai"}],"wordFamily":["casting (n.)","recast (v.)"],"synonyms":["throw","hurl"],"antonyms":[],"tipVi":"Dạng quá khứ và phân từ hai đều là cast; danh từ chỉ dàn diễn viên dùng ở hình thức số ít.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_climax', 'en-b2-31', 'climax', '/ˈklaɪmæks/', 'B2', 'điểm cao trào; đỉnh điểm; đạt đến cao trào', 'n.', 'climactic (adj.), anticlimax (n.)', 'Đồng nghĩa: peak, high point, culmination · Trái nghĩa: anticlimax', 'Climactic có nghĩa thuộc về cao trào; đừng nhầm lẫn với từ climatic mang ý nghĩa thuộc về khí hậu.', 'The concert reached its climax when the whole choir joined.', NULL, 'Buổi hòa nhạc đã đạt đến cao trào khi toàn bộ dàn hợp xướng cùng tham gia.', '{"wordId":"climax","ukIpa":"/ˈklaɪmæks/","usIpa":"/ˈklaɪmæks/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"The most exciting or important point of an event","vi":"điểm cao trào; đỉnh điểm"},{"pos":"v.","en":"Reach the most exciting or important point","vi":"đạt đến cao trào"}],"examples":[{"en":"The concert reached its climax when the whole choir joined.","vi":"Buổi hòa nhạc đã đạt đến cao trào khi toàn bộ dàn hợp xướng cùng tham gia.","audioKind":"ex"},{"en":"The film reaches its climax when the community unites to protect the forest from destruction.","vi":"Bộ phim đạt đến cao trào khi cộng đồng đoàn kết lại để bảo vệ khu rừng khỏi bị phá hủy.","audioKind":"ex2"}],"collocations":[{"en":"reach a climax","vi":"đạt đến cao trào"},{"en":"a dramatic climax","vi":"một cao trào đầy kịch tính"},{"en":"climax with","vi":"đạt đến cao trào với"}],"wordFamily":["climactic (adj.)","anticlimax (n.)"],"synonyms":["peak","high point","culmination"],"antonyms":["anticlimax"],"tipVi":"Climactic có nghĩa thuộc về cao trào; đừng nhầm lẫn với từ climatic mang ý nghĩa thuộc về khí hậu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_percussion', 'en-b2-31', 'percussion', '/pɚˈkʌʃən/', 'B2', 'nhạc cụ gõ; bộ gõ', 'n.', 'percussionist (n.), percussive (adj.)', NULL, 'Khi chỉ chung chung thì không đếm được; một nhạc cụ gõ cụ thể dùng a percussion instrument.', 'My sister plays percussion in the school band.', NULL, 'Chị tôi chơi nhạc cụ gõ trong ban nhạc của trường.', '{"wordId":"percussion","ukIpa":"/pəˈkʌʃən/","usIpa":"/pɚˈkʌʃən/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"Musical instruments played by hitting, shaking, or scraping them.","vi":"nhạc cụ gõ; bộ gõ"}],"examples":[{"en":"My sister plays percussion in the school band.","vi":"Chị tôi chơi nhạc cụ gõ trong ban nhạc của trường.","audioKind":"ex"},{"en":"Group percussion lessons can help children develop coordination while encouraging cooperation and creative expression.","vi":"Các lớp học bộ gõ nhóm có thể giúp trẻ em phát triển khả năng phối hợp đồng thời thúc đẩy tinh thần hợp tác và biểu đạt sáng tạo.","audioKind":"ex2"}],"collocations":[{"en":"percussion instruments","vi":"nhạc cụ gõ"},{"en":"play percussion","vi":"chơi nhạc cụ gõ"},{"en":"percussion section","vi":"bộ gõ"}],"wordFamily":["percussionist (n.)","percussive (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ chung chung thì không đếm được; một nhạc cụ gõ cụ thể dùng a percussion instrument.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pottery', 'en-b2-31', 'pottery', '/ˈpɑːtəri/', 'B2', 'đồ gốm; nghệ thuật làm gốm; nghề gốm; xưởng gốm; nhà máy gốm', 'n.', 'potter (n.), pot (n.)', 'Đồng nghĩa: ceramics', 'Khi chỉ chung đồ gốm thì không đếm được; một món đồ gốm dùng a piece of pottery.', 'The market stall displayed pottery in soft earthy colours.', NULL, 'Quầy hàng trong chợ trưng bày đồ gốm với tông màu đất nhẹ nhàng.', '{"wordId":"pottery","ukIpa":"/ˈpɒtəri/","usIpa":"/ˈpɑːtəri/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"Objects shaped from clay and hardened by heating.","vi":"đồ gốm"},{"pos":"n.","en":"The activity of making objects from clay.","vi":"nghệ thuật làm gốm; nghề gốm"},{"pos":"n.","en":"A place where clay objects are made.","vi":"xưởng gốm; nhà máy gốm"}],"examples":[{"en":"The market stall displayed pottery in soft earthy colours.","vi":"Quầy hàng trong chợ trưng bày đồ gốm với tông màu đất nhẹ nhàng.","audioKind":"ex"},{"en":"Traditional pottery can reveal how earlier societies stored food, traded goods, and expressed their cultural identity.","vi":"Đồ gốm truyền thống có thể cho thấy các xã hội thời xưa đã lưu trữ thực phẩm, giao thương hàng hóa và thể hiện bản sắc văn hóa của họ như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"handmade pottery","vi":"đồ gốm thủ công"},{"en":"pottery class","vi":"lớp học làm gốm"},{"en":"pottery wheel","vi":"bàn xoay làm gốm"},{"en":"pottery fragments","vi":"mảnh vỡ đồ gốm"}],"wordFamily":["potter (n.)","pot (n.)"],"synonyms":["ceramics"],"antonyms":[],"tipVi":"Khi chỉ chung đồ gốm thì không đếm được; một món đồ gốm dùng a piece of pottery.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conductor', 'en-b2-31', 'conductor', '/kənˈdʌktər/', 'B2', 'người chỉ huy (dàn nhạc, hợp xướng); chất dẫn (nhiệt, điện); nhân viên soát vé; tiếp viên (trên phương tiện giao thông công cộng)', 'n.', 'conduct (v.), conduction (n.), conductive (adj.), conductivity (n.)', NULL, 'Từ "conductor" (chất dẫn) thường đi kèm với "of heat" hoặc "of electricity".', 'The conductor raised her arms, and the orchestra fell silent.', NULL, 'Nữ nhạc trưởng giơ cao đôi tay, và dàn nhạc bỗng chốc chìm vào không gian tĩnh lặng.', '{"wordId":"conductor","ukIpa":"/kənˈdʌktə/","usIpa":"/kənˈdʌktər/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"Someone who directs an orchestra or choir","vi":"người chỉ huy (dàn nhạc, hợp xướng)"},{"pos":"n.","en":"A material that allows heat or electricity to pass through","vi":"chất dẫn (nhiệt, điện)"},{"pos":"n.","en":"Someone who checks or sells tickets on public transport","vi":"nhân viên soát vé; tiếp viên (trên phương tiện giao thông công cộng)"}],"examples":[{"en":"The conductor raised her arms, and the orchestra fell silent.","vi":"Nữ nhạc trưởng giơ cao đôi tay, và dàn nhạc bỗng chốc chìm vào không gian tĩnh lặng.","audioKind":"ex"},{"en":"Copper is an effective conductor of electricity, making it a common material in household wiring.","vi":"Đồng là một chất dẫn điện hiệu quả, khiến nó trở thành vật liệu phổ biến trong hệ thống dây điện gia dụng.","audioKind":"ex2"}],"collocations":[{"en":"an orchestra conductor","vi":"nhạc trưởng dàn nhạc"},{"en":"a good conductor of heat","vi":"chất dẫn nhiệt tốt"},{"en":"a train conductor","vi":"nhân viên soát vé tàu"}],"wordFamily":["conduct (v.)","conduction (n.)","conductive (adj.)","conductivity (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ \"conductor\" (chất dẫn) thường đi kèm với \"of heat\" hoặc \"of electricity\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_literary', 'en-b2-31', 'literary', '/ˈlɪtəreri/', 'B2', 'thuộc về văn học; mang tính văn phong; có tính văn học', 'adj.', 'literature (n.)', NULL, 'literary là mang tính văn học; literal là mang nghĩa đen, sát chữ.', 'Our local library hosts a literary festival each spring.', NULL, 'Thư viện địa phương của chúng tôi tổ chức một lễ hội văn học vào mỗi mùa xuân.', '{"wordId":"literary","ukIpa":"/ˈlɪtərəri/","usIpa":"/ˈlɪtəreri/","cefr":"B2","topic":"arts","senses":[{"pos":"adj.","en":"Relating to literature or the study of it.","vi":"thuộc về văn học"},{"pos":"adj.","en":"Typical of formal or artistic writing rather than everyday speech.","vi":"mang tính văn phong; có tính văn học"}],"examples":[{"en":"Our local library hosts a literary festival each spring.","vi":"Thư viện địa phương của chúng tôi tổ chức một lễ hội văn học vào mỗi mùa xuân.","audioKind":"ex"},{"en":"Studying literary works from different cultures can help students understand perspectives beyond their own experiences.","vi":"Việc nghiên cứu các tác phẩm văn học từ các nền văn hóa khác nhau có thể giúp học sinh thấu hiểu những góc nhìn vượt ra ngoài trải nghiệm của chính họ.","audioKind":"ex2"}],"collocations":[{"en":"literary works","vi":"tác phẩm văn học"},{"en":"literary criticism","vi":"phê bình văn học"},{"en":"a literary festival","vi":"lễ hội văn học"},{"en":"literary language","vi":"ngôn ngữ văn học"}],"wordFamily":["literature (n.)"],"synonyms":[],"antonyms":[],"tipVi":"literary là mang tính văn học; literal là mang nghĩa đen, sát chữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_contemporary', 'en-b2-31', 'contemporary', '/kənˈtempəreri/', 'B2', 'đương đại; hiện đại; đương thời; cùng thời; người cùng thời', 'adj.', NULL, 'Đồng nghĩa: modern, present-day', 'Trong nghệ thuật, contemporary dùng để chỉ tính ''đương đại''; trong bối cảnh lịch sử, từ này còn mang nghĩa ''cùng thời''.', 'The gallery displays contemporary paintings in bright, spacious rooms.', NULL, 'Phòng tranh trưng bày các tác phẩm hội họa đương đại trong những căn phòng sáng sủa và rộng rãi.', '{"wordId":"contemporary","ukIpa":"/kənˈtemprəri/","usIpa":"/kənˈtempəreri/","cefr":"B2","topic":"arts","senses":[{"pos":"adj.","en":"Belonging to the present time.","vi":"đương đại; hiện đại"},{"pos":"adj.","en":"Existing or happening during the same period.","vi":"đương thời; cùng thời"},{"pos":"n.","en":"A person who lives at the same time as another.","vi":"người cùng thời"}],"examples":[{"en":"The gallery displays contemporary paintings in bright, spacious rooms.","vi":"Phòng tranh trưng bày các tác phẩm hội họa đương đại trong những căn phòng sáng sủa và rộng rãi.","audioKind":"ex"},{"en":"Contemporary architecture increasingly incorporates natural materials to reduce environmental impact and improve the wellbeing of occupants.","vi":"Kiến trúc đương đại ngày càng kết hợp nhiều vật liệu tự nhiên nhằm giảm thiểu tác động đến môi trường và nâng cao chất lượng sống cho người sử dụng.","audioKind":"ex2"}],"collocations":[{"en":"contemporary art","vi":"nghệ thuật đương đại"},{"en":"contemporary society","vi":"xã hội đương đại"},{"en":"contemporary accounts","vi":"tài liệu đương thời"},{"en":"a contemporary of someone","vi":"người cùng thời với ai đó"}],"wordFamily":[],"synonyms":["modern","present-day"],"antonyms":[],"tipVi":"Trong nghệ thuật, contemporary dùng để chỉ tính ''đương đại''; trong bối cảnh lịch sử, từ này còn mang nghĩa ''cùng thời''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_31_1', 'en-b2-31', 'Cách dùng “contemporary” (adj.) — đương đại; hiện đại', 'contemporary art  ·  contemporary society  ·  contemporary accounts', 'Trong nghệ thuật, contemporary dùng để chỉ tính ''đương đại''; trong bối cảnh lịch sử, từ này còn mang nghĩa ''cùng thời''.', 'Đồng nghĩa: modern, present-day', '[{"hanzi":"The gallery displays contemporary paintings in bright, spacious rooms.","pinyin":"","meaning":"Phòng tranh trưng bày các tác phẩm hội họa đương đại trong những căn phòng sáng sủa và rộng rãi."},{"hanzi":"Contemporary architecture increasingly incorporates natural materials to reduce environmental impact and improve the wellbeing of occupants.","pinyin":"","meaning":"Kiến trúc đương đại ngày càng kết hợp nhiều vật liệu tự nhiên nhằm giảm thiểu tác động đến môi trường và nâng cao chất lượng sống cho người sử dụng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_31_2', 'en-b2-31', 'Cách dùng “soundtrack” (n.) — nhạc phim; phần âm thanh', 'a film soundtrack  ·  an original soundtrack  ·  compose a soundtrack', 'Không chỉ chỉ phần nhạc nền, từ này còn có thể chỉ toàn bộ phần âm thanh bao gồm cả lời thoại và hiệu ứng.', NULL, '[{"hanzi":"I listened to the film''s soundtrack on the bus.","pinyin":"","meaning":"Tôi đã nghe phần nhạc phim đó trên xe buýt."},{"hanzi":"A carefully chosen soundtrack can strengthen a documentary''s emotional impact without distracting viewers from its central message.","pinyin":"","meaning":"Một bản nhạc phim được chọn lọc kỹ càng có thể làm tăng sức lay động cảm xúc của bộ phim tài liệu mà không làm người xem xao lãng khỏi thông điệp chính."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_31_3', 'en-b2-31', 'Cách dùng “climax” (n.) — điểm cao trào; đỉnh điểm', 'reach a climax  ·  a dramatic climax  ·  climax with', 'Climactic có nghĩa thuộc về cao trào; đừng nhầm lẫn với từ climatic mang ý nghĩa thuộc về khí hậu.', 'Họ từ (Word Family): climactic (adj.), anticlimax (n.) | Đồng nghĩa: peak, high point, culmination · Trái nghĩa: anticlimax', '[{"hanzi":"The concert reached its climax when the whole choir joined.","pinyin":"","meaning":"Buổi hòa nhạc đã đạt đến cao trào khi toàn bộ dàn hợp xướng cùng tham gia."},{"hanzi":"The film reaches its climax when the community unites to protect the forest from destruction.","pinyin":"","meaning":"Bộ phim đạt đến cao trào khi cộng đồng đoàn kết lại để bảo vệ khu rừng khỏi bị phá hủy."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_31_4', 'en-b2-31', 'Cách dùng “verse” (n.) — thơ; thơ ca; bài thơ có vần', 'free verse  ·  blank verse  ·  in verse', 'Khi chỉ chung chung thể loại thơ/vần thì không đếm được; khi chỉ một khổ thơ cụ thể thì đếm được.', 'Họ từ (Word Family): versification (n.), versify (v.) | Đồng nghĩa: poetry · Trái nghĩa: prose', '[{"hanzi":"We sang the first verse together around the piano.","pinyin":"","meaning":"Chúng tôi cùng nhau hát đoạn lời đầu tiên bên cây đàn piano."},{"hanzi":"Studying verse can help language learners recognise rhythm and explore how writers convey complex emotions.","pinyin":"","meaning":"Việc nghiên cứu thơ ca có thể giúp người học ngôn ngữ nhận biết nhịp điệu và khám phá cách các nhà văn truyền tải cảm xúc phức tạp."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_31_1', 'en-b2-31', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
