INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_31_1_2', 'ten_b2_31_1', 'ballroom', 'Couples glided across the ballroom beneath a sparkling chandelier.', 'Couples glided across the ballroom beneath a sparkling chandelier.', '/ˈbɔːlruːm/', 'Các cặp đôi lướt nhẹ qua phòng khiêu vũ dưới ánh đèn chùm lấp lánh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_31_1_3', 'ten_b2_31_1', 'plot', 'The film had a simple but exciting plot.', 'The film had a simple but exciting plot.', '/plɑːt/', 'Bộ phim có cốt truyện giản dị nhưng lôi cuốn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_31_1_4', 'ten_b2_31_1', 'soundtrack', 'I listened to the film''s soundtrack on the bus.', 'I listened to the film''s soundtrack on the bus.', '/ˈsaʊndtræk/', 'Tôi đã nghe phần nhạc phim đó trên xe buýt.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_31_1_5', 'ten_b2_31_1', 'masterpiece', 'Everyone stopped to admire the masterpiece above the fireplace.', 'Everyone stopped to admire the masterpiece above the fireplace.', '/ˈmæstərpiːs/', 'Mọi người đều dừng lại để chiêm ngưỡng bức kiệt tác phía trên lò sưởi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_31_1_6', 'ten_b2_31_1', 'symphony', 'We listened to a symphony while cooking dinner.', 'We listened to a symphony while cooking dinner.', '/ˈsɪmfəni/', 'Chúng tôi đã nghe một bản giao hưởng trong khi nấu bữa tối.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_31_1_7', 'ten_b2_31_1', 'layout', 'We changed the kitchen layout to create more space.', 'We changed the kitchen layout to create more space.', '/ˈleɪaʊt/', 'Chúng tôi đã thay đổi bố cục nhà bếp để tạo thêm không gian.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_31_1_8', 'ten_b2_31_1', 'best-selling', 'I borrowed her best-selling cookbook and tried the soup.', 'I borrowed her best-selling cookbook and tried the soup.', '/ˌbest ˈselɪŋ/', 'Tôi đã mượn cuốn sách nấu ăn bán chạy nhất của cô ấy và làm thử món súp.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_31_1_1', 'en-b2-31', 'ten_b2_31_1', 'listening', 'listening', 'My sister practises the clarinet quietly after dinner.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Em gái tôi chăm chỉ tập thổi kèn clarinet một cách yên tĩnh sau bữa tối.","Chúng tôi cùng nhau hát đoạn lời đầu tiên bên cây đàn piano.","Phòng tranh trưng bày các tác phẩm hội họa đương đại trong những căn phòng sáng sủa và rộng rãi.","Nữ nhạc trưởng giơ cao đôi tay, và dàn nhạc bỗng chốc chìm vào không gian tĩnh lặng."]'::jsonb, 0, 'My sister practises the clarinet quietly after dinner. → Em gái tôi chăm chỉ tập thổi kèn clarinet một cách yên tĩnh sau bữa tối.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_31_1_2', 'en-b2-31', 'ten_b2_31_1', 'listening', 'listening', 'Couples glided across the ballroom beneath a sparkling chandelier.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi cùng nhau hát đoạn lời đầu tiên bên cây đàn piano.","Tôi đã nghe phần nhạc phim đó trên xe buýt.","Các cặp đôi lướt nhẹ qua phòng khiêu vũ dưới ánh đèn chùm lấp lánh.","Em gái tôi chăm chỉ tập thổi kèn clarinet một cách yên tĩnh sau bữa tối."]'::jsonb, 2, 'Couples glided across the ballroom beneath a sparkling chandelier. → Các cặp đôi lướt nhẹ qua phòng khiêu vũ dưới ánh đèn chùm lấp lánh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_31_1_3', 'en-b2-31', 'ten_b2_31_1', 'listening', 'listening', 'The film had a simple but exciting plot.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Quầy hàng trong chợ trưng bày đồ gốm với tông màu đất nhẹ nhàng.","Phòng tranh trưng bày các tác phẩm hội họa đương đại trong những căn phòng sáng sủa và rộng rãi.","Bộ phim có cốt truyện giản dị nhưng lôi cuốn.","Ông tôi đã chạm trổ một chú chim nhỏ từ một khúc gỗ mềm."]'::jsonb, 2, 'The film had a simple but exciting plot. → Bộ phim có cốt truyện giản dị nhưng lôi cuốn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_31_2', 'en-b2-31', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_31_2_1', 'ten_b2_31_2', 'clarinet', 'Learning to play the clarinet can help children develop concentration while encouraging participation in school orchestras.', 'Learning to play the clarinet can help children develop concentration while encouraging participation in school orchestras.', '/ˌklærəˈnet/', 'Học chơi kèn clarinet có thể giúp trẻ em phát triển khả năng tập trung đồng thời khuyến khích tham gia vào các dàn nhạc của trường.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_31_2_2', 'ten_b2_31_2', 'ballroom', 'Restoring the historic ballroom could attract visitors while providing local residents with a valuable space for cultural events.', 'Restoring the historic ballroom could attract visitors while providing local residents with a valuable space for cultural events.', '/ˈbɔːlruːm/', 'Việc trùng tu phòng khiêu vũ lịch sử này có thể thu hút du khách, đồng thời mang lại cho người dân địa phương một không gian quý giá cho các sự kiện văn hóa.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_31_2_3', 'ten_b2_31_2', 'plot', 'Community gardens allow residents to grow vegetables on a small plot, improving access to fresh food.', 'Community gardens allow residents to grow vegetables on a small plot, improving access to fresh food.', '/plɑːt/', 'Các khu vườn cộng đồng cho phép cư dân trồng rau trên một mảnh đất nhỏ, giúp họ tiếp cận thực phẩm tươi dễ dàng hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_31_2_4', 'ten_b2_31_2', 'soundtrack', 'A carefully chosen soundtrack can strengthen a documentary''s emotional impact without distracting viewers from its central message.', 'A carefully chosen soundtrack can strengthen a documentary''s emotional impact without distracting viewers from its central message.', '/ˈsaʊndtræk/', 'Một bản nhạc phim được chọn lọc kỹ càng có thể làm tăng sức lay động cảm xúc của bộ phim tài liệu mà không làm người xem xao lãng khỏi thông điệp chính.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_31_2_5', 'ten_b2_31_2', 'masterpiece', 'Displaying a masterpiece in a public museum allows people from different backgrounds to appreciate artistic achievement.', 'Displaying a masterpiece in a public museum allows people from different backgrounds to appreciate artistic achievement.', '/ˈmæstərpiːs/', 'Việc trưng bày một kiệt tác trong bảo tàng công cộng cho phép mọi người từ các nền tảng khác nhau đánh giá cao các thành tựu nghệ thuật.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_31_2_6', 'ten_b2_31_2', 'symphony', 'Performing a symphony requires close cooperation among musicians, demonstrating the importance of teamwork in the arts.', 'Performing a symphony requires close cooperation among musicians, demonstrating the importance of teamwork in the arts.', '/ˈsɪmfəni/', 'Trình diễn một bản giao hưởng đòi hỏi sự hợp tác chặt chẽ giữa các nhạc sĩ, minh chứng cho tầm quan trọng của tinh thần đồng đội trong nghệ thuật.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_31_2_1', 'en-b2-31', 'ten_b2_31_2', 'listening', 'listening', 'Learning to play the clarinet can help children develop concentration while encouraging participation in school orchestras.', NULL, 'Trong câu vừa nghe, từ “clarinet” mang nghĩa nào sau đây?', '["bố cục; cách bài trí; thiết kế trang","một cách tất yếu; không thể tránh khỏi","tăng vọt; vọt lên rất cao","đàn clarinet; kèn clarinet"]'::jsonb, 3, '“clarinet” (/ˌklærəˈnet/): đàn clarinet; kèn clarinet. Câu đầy đủ: Learning to play the clarinet can help children develop concentration while encouraging participation in school orchestras.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_31_2_2', 'en-b2-31', 'ten_b2_31_2', 'listening', 'listening', 'Restoring the historic ballroom could attract visitors while providing local residents with a valuable space for cultural events.', NULL, 'Trong câu vừa nghe, từ “ballroom” mang nghĩa nào sau đây?', '["từ chối; bác bỏ","sự phát hiện; sự dò tìm; sự xét nghiệm","phòng khiêu vũ; vũ trường","sự nhẹ nhõm; sự thở phào"]'::jsonb, 2, '“ballroom” (/ˈbɔːlruːm/): phòng khiêu vũ; vũ trường. Câu đầy đủ: Restoring the historic ballroom could attract visitors while providing local residents with a valuable space for cultural events.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
