INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_31_2', 'en-b2-31', NULL, 'comprehensive_test', 'listening', 'Couples glided across the ballroom beneath a sparkling chandelier.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Các cặp đôi lướt nhẹ qua phòng khiêu vũ dưới ánh đèn chùm lấp lánh.","Quầy hàng trong chợ trưng bày đồ gốm với tông màu đất nhẹ nhàng.","Tôi bắt đầu học làm gốm tại một xưởng thủ công địa phương.","Bộ phim có cốt truyện giản dị nhưng lôi cuốn."]'::jsonb, 0, 'Couples glided across the ballroom beneath a sparkling chandelier. → Các cặp đôi lướt nhẹ qua phòng khiêu vũ dưới ánh đèn chùm lấp lánh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
