INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_31_5', 'en-b2-31', NULL, 'comprehensive_test', 'listening', 'masterpiece', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["trả giá; đấu giá; bỏ thầu","thuộc về công nghệ; kỹ thuật","sự giảm bớt; sự cắt giảm; sự hạ giá","kiệt tác; tác phẩm để đời"]'::jsonb, 3, 'masterpiece (/ˈmæstərpiːs/) → kiệt tác; tác phẩm để đời', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_31_6', 'en-b2-31', NULL, 'comprehensive_test', 'listening', 'We listened to a symphony while cooking dinner.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã nghe một bản giao hưởng trong khi nấu bữa tối.","Tôi đã nghe phần nhạc phim đó trên xe buýt.","Toàn bộ dàn diễn viên đã bước ra ngoài để chào khán giả.","Chúng tôi đã thay đổi bố cục nhà bếp để tạo thêm không gian."]'::jsonb, 0, 'We listened to a symphony while cooking dinner. → Chúng tôi đã nghe một bản giao hưởng trong khi nấu bữa tối.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_31_7', 'en-b2-31', NULL, 'comprehensive_test', 'listening', 'layout', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["kéo; cẩu (xe cộ, tàu thuyền)","thần thánh; thiêng liêng; thánh","bố cục; cách bài trí; thiết kế trang","sự hoàn thành; sự hoàn thành xong; sự khánh thành"]'::jsonb, 2, 'layout (/ˈleɪaʊt/) → bố cục; cách bài trí; thiết kế trang', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_31_8', 'en-b2-31', NULL, 'comprehensive_test', 'listening', 'I borrowed her best-selling cookbook and tried the soup.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã mượn cuốn sách nấu ăn bán chạy nhất của cô ấy và làm thử món súp.","Em họ tôi học thiết kế đồ họa và làm ra những tấm áp phích đầy màu sắc.","Nữ nhạc trưởng giơ cao đôi tay, và dàn nhạc bỗng chốc chìm vào không gian tĩnh lặng.","Bộ phim có cốt truyện giản dị nhưng lôi cuốn."]'::jsonb, 0, 'I borrowed her best-selling cookbook and tried the soup. → Tôi đã mượn cuốn sách nấu ăn bán chạy nhất của cô ấy và làm thử món súp.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_31_9', 'en-b2-31', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “an exceptionally fine work of art, literature, or skill”?', '["symphony","percussion","masterpiece","graphic"]'::jsonb, 2, 'masterpiece (/ˈmæstərpiːs/) → kiệt tác; tác phẩm để đời', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_31_10', 'en-b2-31', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a long orchestral composition, usually divided into several movements”?', '["symphony","applause","climax","classic"]'::jsonb, 0, 'symphony (/ˈsɪmfəni/) → bản giao hưởng', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_31_11', 'en-b2-31', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “the way parts of a space or page are arranged”?', '["applause","layout","ballroom","symphony"]'::jsonb, 1, 'layout (/ˈleɪaʊt/) → bố cục; cách bài trí; thiết kế trang', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_31_12', 'en-b2-31', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “selling in very large quantities compared with similar products”?', '["climax","ballroom","best-selling","clarinet"]'::jsonb, 2, 'best-selling (/ˌbest ˈselɪŋ/) → bán chạy; có doanh số bán rất cao', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
