INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_31_18', 'en-b2-31', NULL, 'comprehensive_test', 'reading', NULL, 'Learning to play the clarinet can help children develop concentration while encouraging participation in school orchestras.', 'Dựa vào câu trên, từ “clarinet” có nghĩa phù hợp nhất là gì?', '["chinh phục; chiếm đóng","có hại; gây tổn hại","làm rõ, minh họa (qua ví dụ hoặc bằng chứng)","đàn clarinet; kèn clarinet"]'::jsonb, 3, 'clarinet: đàn clarinet; kèn clarinet. Dịch cả câu: Học chơi kèn clarinet có thể giúp trẻ em phát triển khả năng tập trung đồng thời khuyến khích tham gia vào các dàn nhạc của trường.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_31_19', 'en-b2-31', NULL, 'comprehensive_test', 'reading', NULL, 'Restoring the historic ballroom could attract visitors while providing local residents with a valuable space for cultural events.', 'Dựa vào câu trên, từ “ballroom” có nghĩa phù hợp nhất là gì?', '["phòng khiêu vũ; vũ trường","bò; trườn (bằng tay và đầu gối)","cách dùng từ; lời lẽ; văn bản","sang trọng; xa hoa; đắt tiền"]'::jsonb, 0, 'ballroom: phòng khiêu vũ; vũ trường. Dịch cả câu: Việc trùng tu phòng khiêu vũ lịch sử này có thể thu hút du khách, đồng thời mang lại cho người dân địa phương một không gian quý giá cho các sự kiện văn hóa.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_31_20', 'en-b2-31', NULL, 'comprehensive_test', 'reading', NULL, 'Community gardens allow residents to grow vegetables on a small plot, improving access to fresh food.', 'Dựa vào câu trên, từ “plot” có nghĩa phù hợp nhất là gì?', '["sự tạo ra; quá trình sáng tạo; sự thành lập","tuyển dụng; chiêu mộ","cốt truyện; tình tiết","danh mục; sách giới thiệu sản phẩm"]'::jsonb, 2, 'plot: cốt truyện; tình tiết; mảnh đất nhỏ; âm mưu; mưu đồ. Dịch cả câu: Các khu vườn cộng đồng cho phép cư dân trồng rau trên một mảnh đất nhỏ, giúp họ tiếp cận thực phẩm tươi dễ dàng hơn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_31_21', 'en-b2-31', NULL, 'comprehensive_test', 'reading', NULL, 'A carefully chosen soundtrack can strengthen a documentary''s emotional impact without distracting viewers from its central message.', 'Dựa vào câu trên, từ “soundtrack” có nghĩa phù hợp nhất là gì?', '["nhạc phim; phần âm thanh","chế độ dân chủ; nền dân chủ","vô cùng, hết sức, sâu sắc (về cảm xúc hoặc niềm tin)","thuốc kháng sinh"]'::jsonb, 0, 'soundtrack: nhạc phim; phần âm thanh. Dịch cả câu: Một bản nhạc phim được chọn lọc kỹ càng có thể làm tăng sức lay động cảm xúc của bộ phim tài liệu mà không làm người xem xao lãng khỏi thông điệp chính.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
