INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-32', 'en', 'Bài 32: Nghệ thuật & Sáng tạo (2) - CEFR B2', 'CEFR B2', 'B2 · Nghệ thuật', '21 từ vựng Tiếng Anh CEFR B2 chủ đề nghệ thuật & sáng tạo kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4032, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_solo', 'en-b2-32', 'solo', '/ˈsoʊloʊ/', 'B2', 'bản độc tấu; bài đơn ca; đơn; độc tấu; một mình; không có sự giúp đỡ của người khác', 'n.', 'soloist (n.)', NULL, 'Có thể làm danh từ, tính từ và trạng từ; nghệ sĩ biểu diễn đơn ca/độc tấu gọi là soloist.', 'Everyone fell silent when she began her violin solo.', NULL, 'Mọi người đều trở nên im lặng khi cô ấy bắt đầu bản độc tấu vĩ cầm của mình.', '{"wordId":"solo","ukIpa":"/ˈsəʊləʊ/","usIpa":"/ˈsoʊloʊ/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"A musical piece or passage performed by one person.","vi":"bản độc tấu; bài đơn ca"},{"pos":"adj.","en":"Done or performed by one person alone.","vi":"đơn; độc tấu; một mình"},{"pos":"adv.","en":"Alone, without other people helping or taking part.","vi":"một mình; không có sự giúp đỡ của người khác"}],"examples":[{"en":"Everyone fell silent when she began her violin solo.","vi":"Mọi người đều trở nên im lặng khi cô ấy bắt đầu bản độc tấu vĩ cầm của mình.","audioKind":"ex"},{"en":"Solo travel can encourage independence by requiring individuals to manage unfamiliar situations without relying on companions.","vi":"Việc du lịch một mình có thể thúc đẩy tính độc lập bằng cách đòi hỏi cá nhân phải tự xử lý các tình huống xa lạ mà không dựa dẫm vào bạn đồng hành.","audioKind":"ex2"}],"collocations":[{"en":"a piano solo","vi":"bản độc tấu piano"},{"en":"a solo performance","vi":"buổi biểu diễn đơn"},{"en":"a solo career","vi":"sự nghiệp đơn ca"},{"en":"travel solo","vi":"du lịch một mình"}],"wordFamily":["soloist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể làm danh từ, tính từ và trạng từ; nghệ sĩ biểu diễn đơn ca/độc tấu gọi là soloist.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_narrative', 'en-b2-32', 'narrative', '/ˈnærətɪv/', 'B2', 'bài tường thuật; câu chuyện; hệ thống quan điểm; góc nhìn giải thích; mang tính tường thuật', 'n.', 'narrate (v.), narration (n.), narrator (n.)', 'Đồng nghĩa: account, story', 'Khi làm danh từ, từ này chỉ cốt truyện hoặc bài tường thuật; khi làm tính từ, nó thường bổ nghĩa cho cấu trúc hoặc kỹ thuật.', 'Her travel diary contains a lively narrative of the journey.', NULL, 'Nhật ký du lịch của cô ấy chứa đựng một bản tường thuật sinh động về chuyến hành trình.', '{"wordId":"narrative","ukIpa":"/ˈnærətɪv/","usIpa":"/ˈnærətɪv/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"A description of connected events, real or imagined.","vi":"bài tường thuật; câu chuyện"},{"pos":"n.","en":"A particular account used to explain events and shape understanding.","vi":"hệ thống quan điểm; góc nhìn giải thích"},{"pos":"adj.","en":"Related to telling stories or describing connected events.","vi":"mang tính tường thuật"}],"examples":[{"en":"Her travel diary contains a lively narrative of the journey.","vi":"Nhật ký du lịch của cô ấy chứa đựng một bản tường thuật sinh động về chuyến hành trình.","audioKind":"ex"},{"en":"Museums can use personal narratives to help visitors understand how historical events affected the lives of ordinary people.","vi":"Các bảo tàng có thể sử dụng những câu chuyện cá nhân để giúp khách tham quan hiểu được các sự kiện lịch sử đã tác động ra sao đến cuộc sống của những người bình thường.","audioKind":"ex2"}],"collocations":[{"en":"personal narrative","vi":"câu chuyện cá nhân"},{"en":"dominant narrative","vi":"luận điệu chủ đạo"},{"en":"narrative structure","vi":"cấu trúc tự sự"}],"wordFamily":["narrate (v.)","narration (n.)","narrator (n.)"],"synonyms":["account","story"],"antonyms":[],"tipVi":"Khi làm danh từ, từ này chỉ cốt truyện hoặc bài tường thuật; khi làm tính từ, nó thường bổ nghĩa cho cấu trúc hoặc kỹ thuật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chorus', 'en-b2-32', 'chorus', '/ˈkɔːrəs/', 'B2', 'đoạn điệp khúc; khúc nối (trong bài hát); dàn đồng ca; tiếng hô đồng thanh; đồng thanh nói; đồng thanh hát', 'n.', 'choral (adj.), chorister (n.)', NULL, 'Chorus trong bài hát là đoạn điệp khúc lặp đi lặp lại, đối lập với verse là lời chính.', 'Everyone joined in when the song reached its chorus.', NULL, 'Mọi người cùng hòa giọng khi bài hát đến đoạn điệp khúc.', '{"wordId":"chorus","ukIpa":"/ˈkɔːrəs/","usIpa":"/ˈkɔːrəs/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"A repeated section of a song, usually with unchanged words.","vi":"đoạn điệp khúc; khúc nối (trong bài hát)"},{"pos":"n.","en":"A group singing together, or many voices sounding together.","vi":"dàn đồng ca; tiếng hô đồng thanh"},{"pos":"v.","en":"To say or sing something together at the same time.","vi":"đồng thanh nói; đồng thanh hát"}],"examples":[{"en":"Everyone joined in when the song reached its chorus.","vi":"Mọi người cùng hòa giọng khi bài hát đến đoạn điệp khúc.","audioKind":"ex"},{"en":"A memorable chorus can help environmental campaign songs reach wider audiences and encourage participation in community activities.","vi":"Một đoạn điệp khúc dễ nhớ có thể giúp các bài hát tuyên truyền về môi trường tiếp cận được nhiều khán giả hơn và khuyến khích mọi người tham gia các hoạt động cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"sing the chorus","vi":"hát đoạn điệp khúc"},{"en":"join in the chorus","vi":"hòa giọng vào điệp khúc"},{"en":"a chorus of approval","vi":"tiếng nói đồng tình"}],"wordFamily":["choral (adj.)","chorister (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chorus trong bài hát là đoạn điệp khúc lặp đi lặp lại, đối lập với verse là lời chính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rap', 'en-b2-32', 'rap', '/ræp/', 'B2', 'nhạc rap; ca khúc rap; hát rap; đọc rap; gõ nhanh; đập nhẹ và nhanh', 'n.', 'rapper (n.)', NULL, 'rap kết thúc bằng phụ âm đôi: các dạng quá khứ và phân từ là rapped, rapping đều gấp đôi chữ p.', 'My brother listens to rap while he cooks dinner.', NULL, 'Anh trai tôi nghe nhạc rap trong lúc nấu bữa tối.', '{"wordId":"rap","ukIpa":"/ræp/","usIpa":"/ræp/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"music with words spoken rhythmically over a strong beat","vi":"nhạc rap; ca khúc rap"},{"pos":"v.","en":"to speak words rhythmically over a musical beat","vi":"hát rap; đọc rap"},{"pos":"v.","en":"to hit a surface with short, sharp blows","vi":"gõ nhanh; đập nhẹ và nhanh"}],"examples":[{"en":"My brother listens to rap while he cooks dinner.","vi":"Anh trai tôi nghe nhạc rap trong lúc nấu bữa tối.","audioKind":"ex"},{"en":"Rap can give young people a creative way to express their experiences and discuss social issues.","vi":"Nhạc rap có thể mang lại cho giới trẻ một phương thức sáng tạo để bày tỏ trải nghiệm của bản thân và thảo luận các vấn đề xã hội.","audioKind":"ex2"}],"collocations":[{"en":"rap music","vi":"nhạc rap"},{"en":"rap artist","vi":"nghệ sĩ rap"},{"en":"rap on the door","vi":"gõ cửa dồn dập"}],"wordFamily":["rapper (n.)"],"synonyms":[],"antonyms":[],"tipVi":"rap kết thúc bằng phụ âm đôi: các dạng quá khứ và phân từ là rapped, rapping đều gấp đôi chữ p.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_melody', 'en-b2-32', 'melody', '/ˈmelədi/', 'B2', 'giai điệu; khúc ca', 'n.', 'melodic (adj.), melodious (adj.)', 'Đồng nghĩa: tune', 'melody chỉ giai điệu có thể ngân nga; rhythm chỉ nhịp điệu.', 'She hummed a gentle melody while watering the plants.', NULL, 'Cô ấy vừa tưới cây vừa khẽ ngân nga một giai điệu dịu dàng.', '{"wordId":"melody","ukIpa":"/ˈmelədi/","usIpa":"/ˈmelədi/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"A sequence of musical sounds forming a recognisable tune.","vi":"giai điệu; khúc ca"}],"examples":[{"en":"She hummed a gentle melody while watering the plants.","vi":"Cô ấy vừa tưới cây vừa khẽ ngân nga một giai điệu dịu dàng.","audioKind":"ex"},{"en":"A memorable melody can help children recall information, making music a useful tool in early education.","vi":"Một giai điệu dễ nhớ có thể giúp trẻ em ghi nhớ thông tin, biến âm nhạc thành một công cụ hữu ích trong giáo dục mầm non.","audioKind":"ex2"}],"collocations":[{"en":"gentle melody","vi":"giai điệu nhẹ nhàng"},{"en":"catchy melody","vi":"giai điệu bắt tai"},{"en":"compose a melody","vi":"sáng tác một giai điệu"}],"wordFamily":["melodic (adj.)","melodious (adj.)"],"synonyms":["tune"],"antonyms":[],"tipVi":"melody chỉ giai điệu có thể ngân nga; rhythm chỉ nhịp điệu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_compose', 'en-b2-32', 'compose', '/kəmˈpoʊz/', 'B2', 'sáng tác (nhạc); viết (văn bản); cấu thành; tạo thành; làm cho bình tĩnh; kìm nén cảm xúc', 'v.', 'composer (n.), composition (n.), composed (adj.), composure (n.)', NULL, 'be composed of diễn tả "được cấu thành từ".', 'She composed a short tune on her old piano.', NULL, 'Cô ấy đã sáng tác một bản nhạc ngắn trên cây đàn piano cũ của mình.', '{"wordId":"compose","ukIpa":"/kəmˈpəʊz/","usIpa":"/kəmˈpoʊz/","cefr":"B2","topic":"arts","senses":[{"pos":"v.","en":"To create music or carefully write a piece of writing","vi":"sáng tác (nhạc); viết (văn bản)"},{"pos":"v.","en":"To be the parts that together form a whole","vi":"cấu thành; tạo thành"},{"pos":"v.","en":"To calm yourself and regain control of your emotions","vi":"làm cho bình tĩnh; kìm nén cảm xúc"}],"examples":[{"en":"She composed a short tune on her old piano.","vi":"Cô ấy đã sáng tác một bản nhạc ngắn trên cây đàn piano cũ của mình.","audioKind":"ex"},{"en":"Students who compose their own music can develop creativity while gaining a deeper understanding of musical structure.","vi":"Những học sinh tự sáng tác âm nhạc có thể phát triển sự sáng tạo đồng thời hiểu sâu hơn về cấu trúc âm nhạc.","audioKind":"ex2"}],"collocations":[{"en":"compose music","vi":"sáng tác nhạc"},{"en":"compose a poem","vi":"làm thơ"},{"en":"be composed of","vi":"được cấu thành từ"},{"en":"compose yourself","vi":"giữ bình tĩnh"}],"wordFamily":["composer (n.)","composition (n.)","composed (adj.)","composure (n.)"],"synonyms":[],"antonyms":[],"tipVi":"be composed of diễn tả \"được cấu thành từ\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_creation', 'en-b2-32', 'creation', '/kriˈeɪʃən/', 'B2', 'sự tạo ra; quá trình sáng tạo; sự thành lập; tác phẩm; sáng tạo phẩm', 'n.', 'create (v.), creator (n.), creative (adj.), creativity (n.)', 'Trái nghĩa: destruction', 'Chỉ quá trình tạo ra thường không đếm được; chỉ tác phẩm cụ thể thì đếm được.', 'The creation of our garden took several busy weekends.', NULL, 'Công viên của chúng tôi đã mất vài tuần bận rộn mới được tạo nên.', '{"wordId":"creation","ukIpa":"/kriˈeɪʃən/","usIpa":"/kriˈeɪʃən/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"the process of bringing something new into existence","vi":"sự tạo ra; quá trình sáng tạo; sự thành lập"},{"pos":"n.","en":"something new that someone has made or designed","vi":"tác phẩm; sáng tạo phẩm"}],"examples":[{"en":"The creation of our garden took several busy weekends.","vi":"Công viên của chúng tôi đã mất vài tuần bận rộn mới được tạo nên.","audioKind":"ex"},{"en":"Investment in renewable energy can support job creation while helping countries reduce their dependence on fossil fuels.","vi":"Việc đầu tư vào năng lượng tái tạo có thể thúc đẩy tạo việc làm đồng thời giúp các quốc gia giảm sự phụ thuộc vào nhiên liệu hóa thạch.","audioKind":"ex2"}],"collocations":[{"en":"job creation","vi":"tạo việc làm"},{"en":"the creation of wealth","vi":"sự tạo ra của cải"},{"en":"an original creation","vi":"một tác phẩm nguyên bản"}],"wordFamily":["create (v.)","creator (n.)","creative (adj.)","creativity (n.)"],"synonyms":[],"antonyms":["destruction"],"tipVi":"Chỉ quá trình tạo ra thường không đếm được; chỉ tác phẩm cụ thể thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_potter', 'en-b2-32', 'potter', '/ˈpɑːtɚ/', 'B2', 'thợ gốm; người làm gốm; làm việc lặt vặt một cách thong thả; bận rộn thư thả', 'n.', 'pottery (n.), pot (n.)', 'Đồng nghĩa: ceramicist', 'Khi dùng làm động từ, thường gặp cụm potter about/around, chỉ việc bận rộn thong thả với những việc nhỏ nhặt.', 'The potter shaped a bowl with her wet hands.', NULL, 'Người thợ gốm đã tạo hình chiếc bát bằng đôi bàn tay ẩm ướt của mình.', '{"wordId":"potter","ukIpa":"/ˈpɒtə/","usIpa":"/ˈpɑːtɚ/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"someone who makes pots and other objects from clay","vi":"thợ gốm; người làm gốm"},{"pos":"v.","en":"to spend time doing small tasks without hurrying","vi":"làm việc lặt vặt một cách thong thả; bận rộn thư thả"}],"examples":[{"en":"The potter shaped a bowl with her wet hands.","vi":"Người thợ gốm đã tạo hình chiếc bát bằng đôi bàn tay ẩm ướt của mình.","audioKind":"ex"},{"en":"Local potters can preserve traditional skills while attracting visitors interested in the region''s cultural heritage.","vi":"Những người thợ gốm địa phương có thể bảo tồn các kỹ năng truyền thống đồng thời thu hút du khách quan tâm đến di sản văn hóa của vùng.","audioKind":"ex2"}],"collocations":[{"en":"a skilled potter","vi":"thợ gốm lành nghề"},{"en":"a potter''s wheel","vi":"bàn xoay làm gốm"},{"en":"potter about the garden","vi":"làm việc lặt vặt quanh vườn"}],"wordFamily":["pottery (n.)","pot (n.)"],"synonyms":["ceramicist"],"antonyms":[],"tipVi":"Khi dùng làm động từ, thường gặp cụm potter about/around, chỉ việc bận rộn thong thả với những việc nhỏ nhặt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_profile', 'en-b2-32', 'profile', '/ˈproʊfaɪl/', 'B2', 'hình dáng mặt nghiêng; biên dạng; tiểu sử; hồ sơ tóm tắt; mức độ quan tâm của công chúng', 'n.', 'profile (v.), profiling (n.)', NULL, 'in profile chỉ góc nhìn ngang; a high profile chỉ mức độ nổi bật, thu hút nhiều chú ý.', 'She drew her grandfather''s profile with a soft pencil.', NULL, 'Cô ấy vẽ nét mặt nghiêng của ông nội bằng một cây bút chì mềm.', '{"wordId":"profile","ukIpa":"/ˈprəʊfaɪl/","usIpa":"/ˈproʊfaɪl/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"The outline of a face or object seen from the side.","vi":"hình dáng mặt nghiêng; biên dạng"},{"pos":"n.","en":"A short description of someone''s life, work, or characteristics.","vi":"tiểu sử; hồ sơ tóm tắt"},{"pos":"n.","en":"The amount of public attention someone or something receives.","vi":"mức độ quan tâm của công chúng"}],"examples":[{"en":"She drew her grandfather''s profile with a soft pencil.","vi":"Cô ấy vẽ nét mặt nghiêng của ông nội bằng một cây bút chì mềm.","audioKind":"ex"},{"en":"Public exhibitions can raise the profile of local artists and attract visitors to smaller towns.","vi":"Các cuộc triển lãm công cộng có thể nâng cao tên tuổi của các nghệ sĩ địa phương và thu hút khách du lịch đến các thị trấn nhỏ hơn.","audioKind":"ex2"}],"collocations":[{"en":"in profile","vi":"nhìn từ góc độ nghiêng"},{"en":"a detailed profile","vi":"hồ sơ chi tiết"},{"en":"raise the profile of","vi":"nâng cao uy tín của"},{"en":"keep a low profile","vi":"giữ lối sống kín đáo"}],"wordFamily":["profile (v.)","profiling (n.)"],"synonyms":[],"antonyms":[],"tipVi":"in profile chỉ góc nhìn ngang; a high profile chỉ mức độ nổi bật, thu hút nhiều chú ý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_illustration', 'en-b2-32', 'illustration', '/ˌɪləˈstreɪʃən/', 'B2', 'hình minh họa; tranh minh họa; ví dụ minh họa; minh chứng', 'n.', 'illustrate (v.), illustrator (n.), illustrative (adj.)', NULL, 'Hình minh họa hoặc ví dụ là danh từ đếm được; chỉ hành động minh họa bằng ví dụ thường không đếm được.', 'The book has a beautiful illustration of a whale.', NULL, 'Cuốn sách có hình minh họa một con cá voi rất đẹp.', '{"wordId":"illustration","ukIpa":"/ˌɪləˈstreɪʃən/","usIpa":"/ˌɪləˈstreɪʃən/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"A picture that accompanies or explains something.","vi":"hình minh họa; tranh minh họa"},{"pos":"n.","en":"An example that makes an idea clearer.","vi":"ví dụ minh họa; minh chứng"}],"examples":[{"en":"The book has a beautiful illustration of a whale.","vi":"Cuốn sách có hình minh họa một con cá voi rất đẹp.","audioKind":"ex"},{"en":"The rapid recovery of this forest provides a clear illustration of the benefits of long-term conservation.","vi":"Sự phục hồi nhanh chóng của khu rừng này cung cấp một minh chứng rõ ràng về lợi ích của công tác bảo tồn lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"a clear illustration of","vi":"một minh chứng rõ ràng về"},{"en":"book illustration","vi":"tranh minh họa sách"},{"en":"by way of illustration","vi":"bằng cách minh họa; để làm ví dụ"}],"wordFamily":["illustrate (v.)","illustrator (n.)","illustrative (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Hình minh họa hoặc ví dụ là danh từ đếm được; chỉ hành động minh họa bằng ví dụ thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ceramic', 'en-b2-32', 'ceramic', '/səˈræmɪk/', 'B2', 'bằng gốm; làm bằng sứ; chất liệu gốm; đồ gốm', 'adj.', 'ceramics (n.), ceramist (n.)', NULL, '"ceramics" có thể chỉ các sản phẩm bằng gốm sứ, hoặc dùng để chỉ nghệ thuật làm gốm.', 'She keeps fresh flowers in a blue ceramic vase.', NULL, 'Cô ấy cắm hoa tươi trong một chiếc bình gốm màu xanh.', '{"wordId":"ceramic","ukIpa":"/səˈræmɪk/","usIpa":"/səˈræmɪk/","cefr":"B2","topic":"arts","senses":[{"pos":"adj.","en":"Made from clay or similar materials hardened by heat.","vi":"bằng gốm; làm bằng sứ"},{"pos":"n.","en":"A material hardened by heat, or an object made from it.","vi":"chất liệu gốm; đồ gốm"}],"examples":[{"en":"She keeps fresh flowers in a blue ceramic vase.","vi":"Cô ấy cắm hoa tươi trong một chiếc bình gốm màu xanh.","audioKind":"ex"},{"en":"Ceramic tiles are widely used in public buildings because they are durable and relatively easy to clean.","vi":"Gạch ceramic được sử dụng rộng rãi trong các công trình công cộng vì chúng bền và tương đối dễ lau chùi.","audioKind":"ex2"}],"collocations":[{"en":"ceramic tiles","vi":"gạch ceramic"},{"en":"ceramic bowl","vi":"bát gốm"},{"en":"ceramic coating","vi":"lớp phủ gốm"},{"en":"ceramic materials","vi":"vật liệu gốm"}],"wordFamily":["ceramics (n.)","ceramist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"\"ceramics\" có thể chỉ các sản phẩm bằng gốm sứ, hoặc dùng để chỉ nghệ thuật làm gốm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_elegant', 'en-b2-32', 'elegant', '/ˈelɪɡənt/', 'B2', 'thanh lịch; trang nhã; đơn giản mà tinh tế; gọn gàng và hiệu quả', 'adj.', 'elegance (n.), elegantly (adv.)', 'Đồng nghĩa: graceful, stylish · Trái nghĩa: inelegant', 'Có thể dùng để mô tả diện mạo thanh lịch hoặc giải pháp thông minh, gọn gàng.', 'She wore an elegant blue dress to dinner.', NULL, 'Cô ấy mặc một chiếc đầm xanh thanh lịch đi dự tiệc tối.', '{"wordId":"elegant","ukIpa":"/ˈelɪɡənt/","usIpa":"/ˈelɪɡənt/","cefr":"B2","topic":"arts","senses":[{"pos":"adj.","en":"attractive and graceful in appearance or style","vi":"thanh lịch; trang nhã"},{"pos":"adj.","en":"simple and effective in solving a problem","vi":"đơn giản mà tinh tế; gọn gàng và hiệu quả"}],"examples":[{"en":"She wore an elegant blue dress to dinner.","vi":"Cô ấy mặc một chiếc đầm xanh thanh lịch đi dự tiệc tối.","audioKind":"ex"},{"en":"The architect proposed an elegant solution that improved ventilation without increasing the building''s energy consumption.","vi":"Kiến trúc sư đã đề xuất một giải pháp tinh tế giúp cải thiện sự thông thoáng mà không làm tăng mức tiêu thụ năng lượng của tòa nhà.","audioKind":"ex2"}],"collocations":[{"en":"elegant design","vi":"thiết kế trang nhã"},{"en":"elegant solution","vi":"giải pháp tinh tế"},{"en":"elegant dress","vi":"chiếc đầm thanh lịch"}],"wordFamily":["elegance (n.)","elegantly (adv.)"],"synonyms":["graceful","stylish"],"antonyms":["inelegant"],"tipVi":"Có thể dùng để mô tả diện mạo thanh lịch hoặc giải pháp thông minh, gọn gàng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bestseller', 'en-b2-32', 'bestseller', '/ˌbestˈselər/', 'B2', 'sách bán chạy; sản phẩm bán chạy', 'n.', 'bestselling (adj.)', NULL, 'Chỉ cuốn sách hoặc sản phẩm bán chạy, không dùng để chỉ tác giả viết sách bán chạy.', 'Her first novel became a bestseller within weeks.', NULL, 'Cuốn tiểu thuyết đầu tay của cô ấy đã trở thành sách bán chạy chỉ trong vòng vài tuần.', '{"wordId":"bestseller","ukIpa":"/ˌbestˈselə/","usIpa":"/ˌbestˈselər/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"A book or other product that sells in very large quantities.","vi":"sách bán chạy; sản phẩm bán chạy"}],"examples":[{"en":"Her first novel became a bestseller within weeks.","vi":"Cuốn tiểu thuyết đầu tay của cô ấy đã trở thành sách bán chạy chỉ trong vòng vài tuần.","audioKind":"ex"},{"en":"A bestseller can introduce complex scientific ideas to readers who rarely engage with academic publications.","vi":"Một cuốn sách bán chạy có thể giới thiệu các khái niệm khoa học phức tạp đến những độc giả vốn hiếm khi tiếp cận với các ấn phẩm học thuật.","audioKind":"ex2"}],"collocations":[{"en":"international bestseller","vi":"sách bán chạy quốc tế"},{"en":"become a bestseller","vi":"trở thành sách bán chạy"},{"en":"bestseller list","vi":"bảng xếp hạng sách bán chạy"}],"wordFamily":["bestselling (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ cuốn sách hoặc sản phẩm bán chạy, không dùng để chỉ tác giả viết sách bán chạy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_audition', 'en-b2-32', 'audition', '/ɔːˈdɪʃən/', 'B2', 'buổi thử vai; buổi thử giọng; thử vai; thử giọng', 'n.', NULL, NULL, 'Nghĩa hiện đại phổ biến là thử vai hoặc thử giọng, không mang nghĩa thính giác thông thường.', 'Lena practised her song before the audition yesterday.', NULL, 'Lena đã luyện tập bài hát của cô ấy trước buổi thử giọng vào ngày hôm qua.', '{"wordId":"audition","ukIpa":"/ɔːˈdɪʃən/","usIpa":"/ɔːˈdɪʃən/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"A short performance to show suitability for a performing role.","vi":"buổi thử vai; buổi thử giọng"},{"pos":"v.","en":"Perform or test someone for a role in a production.","vi":"thử vai; thử giọng"}],"examples":[{"en":"Lena practised her song before the audition yesterday.","vi":"Lena đã luyện tập bài hát của cô ấy trước buổi thử giọng vào ngày hôm qua.","audioKind":"ex"},{"en":"Open auditions can help local theatres discover talented performers who lack professional training or industry connections.","vi":"Các buổi thử vai công khai có thể giúp các nhà hát địa phương tìm ra những tài năng biểu diễn còn thiếu đào tạo chuyên nghiệp hoặc mối quan hệ trong ngành.","audioKind":"ex2"}],"collocations":[{"en":"attend an audition","vi":"tham gia buổi thử vai"},{"en":"hold auditions","vi":"tổ chức các buổi thử vai"},{"en":"audition for a role","vi":"thử vai cho một nhân vật"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa hiện đại phổ biến là thử vai hoặc thử giọng, không mang nghĩa thính giác thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_canvas', 'en-b2-32', 'canvas', '/ˈkænvəs/', 'B2', 'vải bạt; loại vải dày, chắc dùng cho lều, túi và buồm; vải bố vẽ tranh; bức tranh sơn dầu vẽ trên vải bố', 'n.', NULL, NULL, 'Canvas khi chỉ chất liệu vải là danh từ không đếm được; khi chỉ một bức tranh vẽ trên vải bố thì đếm được.', 'She packed her lunch in a sturdy canvas bag.', NULL, 'Cô ấy đựng bữa trưa trong một chiếc túi vải bạt chắc chắn.', '{"wordId":"canvas","ukIpa":"/ˈkænvəs/","usIpa":"/ˈkænvəs/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"Strong, heavy cloth used for tents, bags, and sails.","vi":"vải bạt; loại vải dày, chắc dùng cho lều, túi và buồm"},{"pos":"n.","en":"Cloth used for painting, or a painting on this cloth.","vi":"vải bố vẽ tranh; bức tranh sơn dầu vẽ trên vải bố"}],"examples":[{"en":"She packed her lunch in a sturdy canvas bag.","vi":"Cô ấy đựng bữa trưa trong một chiếc túi vải bạt chắc chắn.","audioKind":"ex"},{"en":"Painting on canvas allows students to explore colour and texture while developing their creative confidence.","vi":"Vẽ tranh trên vải bố giúp học sinh khám phá màu sắc và kết cấu đồng thời phát triển sự tự tin sáng tạo của các em.","audioKind":"ex2"}],"collocations":[{"en":"canvas bag","vi":"túi vải bạt"},{"en":"canvas tent","vi":"lều vải bạt"},{"en":"oil on canvas","vi":"tranh sơn dầu trên vải bố"},{"en":"blank canvas","vi":"tấm vải bố trắng; mặt phẳng trắng chưa phác thảo"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Canvas khi chỉ chất liệu vải là danh từ không đếm được; khi chỉ một bức tranh vẽ trên vải bố thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_miniature', 'en-b2-32', 'miniature', '/ˈmɪnətʃɚ/', 'B2', 'thu nhỏ; mini; mô hình thu nhỏ; tranh vẽ thu nhỏ', 'adj.', 'miniaturize (v.), miniaturization (n.)', 'Đồng nghĩa: tiny, small-scale · Trái nghĩa: full-size', 'in miniature diễn tả ý nghĩa "dưới hình thức thu nhỏ".', 'My cousin built a miniature castle from spare wood.', NULL, 'Anh họ tôi đã làm một lâu đài thu nhỏ từ gỗ thừa.', '{"wordId":"miniature","ukIpa":"/ˈmɪnətʃə/","usIpa":"/ˈmɪnətʃɚ/","cefr":"B2","topic":"arts","senses":[{"pos":"adj.","en":"Much smaller than the usual size of something.","vi":"thu nhỏ; mini"},{"pos":"n.","en":"A very small model or finely detailed small painting.","vi":"mô hình thu nhỏ; tranh vẽ thu nhỏ"}],"examples":[{"en":"My cousin built a miniature castle from spare wood.","vi":"Anh họ tôi đã làm một lâu đài thu nhỏ từ gỗ thừa.","audioKind":"ex"},{"en":"Architects often use miniature models to demonstrate how proposed buildings will fit into existing urban neighbourhoods.","vi":"Các kiến trúc sư thường sử dụng mô hình thu nhỏ để minh họa cách các công trình đề xuất hòa nhập vào các khu phố đô thị hiện có.","audioKind":"ex2"}],"collocations":[{"en":"miniature model","vi":"mô hình thu nhỏ"},{"en":"miniature railway","vi":"đường sắt thu nhỏ"},{"en":"in miniature","vi":"dưới dạng thu nhỏ"}],"wordFamily":["miniaturize (v.)","miniaturization (n.)"],"synonyms":["tiny","small-scale"],"antonyms":["full-size"],"tipVi":"in miniature diễn tả ý nghĩa \"dưới hình thức thu nhỏ\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rehearse', 'en-b2-32', 'rehearse', '/rɪˈhɝːs/', 'B2', 'tập dượt; diễn tập', 'v.', 'rehearsal (n.), rehearsed (adj.)', 'Đồng nghĩa: practise', 'Sau "rehearse" là trực tiếp nội dung tập dượt; tập dượt cho buổi biểu diễn dùng "for".', 'We rehearsed our dance in the empty school hall.', NULL, 'Chúng tôi đã tập dượt điệu nhảy của mình trong hội trường trường học trống trải.', '{"wordId":"rehearse","ukIpa":"/rɪˈhɜːs/","usIpa":"/rɪˈhɝːs/","cefr":"B2","topic":"arts","senses":[{"pos":"v.","en":"to practise a performance or activity before doing it publicly","vi":"tập dượt; diễn tập"}],"examples":[{"en":"We rehearsed our dance in the empty school hall.","vi":"Chúng tôi đã tập dượt điệu nhảy của mình trong hội trường trường học trống trải.","audioKind":"ex"},{"en":"Students who rehearse their presentations with classmates often develop greater confidence and communicate their ideas more clearly.","vi":"Những học sinh tập dượt bài thuyết trình cùng bạn học thường tự tin hơn và truyền đạt ý tưởng rõ ràng hơn.","audioKind":"ex2"}],"collocations":[{"en":"rehearse a play","vi":"tập dượt một vở kịch"},{"en":"rehearse a speech","vi":"tập dượt bài phát biểu"},{"en":"rehearse for a performance","vi":"tập dượt cho một buổi biểu diễn"}],"wordFamily":["rehearsal (n.)","rehearsed (adj.)"],"synonyms":["practise"],"antonyms":[],"tipVi":"Sau \"rehearse\" là trực tiếp nội dung tập dượt; tập dượt cho buổi biểu diễn dùng \"for\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_portray', 'en-b2-32', 'portray', '/pɔːrˈtreɪ/', 'B2', 'khắc họa; miêu tả; đóng vai; thủ vai', 'v.', 'portrayal (n.)', 'Đồng nghĩa: depict, represent', 'Thường dùng cấu trúc "portray A as B", nghĩa là khắc họa A như là B.', 'Her paintings portray village life in warm colours.', NULL, 'Những bức tranh của cô ấy khắc họa cuộc sống làng quê bằng những gam màu ấm áp.', '{"wordId":"portray","ukIpa":"/pɔːˈtreɪ/","usIpa":"/pɔːrˈtreɪ/","cefr":"B2","topic":"arts","senses":[{"pos":"v.","en":"To represent someone or something in words or images","vi":"khắc họa; miêu tả"},{"pos":"v.","en":"To play a character in a film or performance","vi":"đóng vai; thủ vai"}],"examples":[{"en":"Her paintings portray village life in warm colours.","vi":"Những bức tranh của cô ấy khắc họa cuộc sống làng quê bằng những gam màu ấm áp.","audioKind":"ex"},{"en":"News reports often portray urban life as stressful, overlooking the social and cultural opportunities cities provide.","vi":"Các bản tin thường khắc họa cuộc sống đô thị là đầy căng thẳng, bỏ qua những cơ hội xã hội và văn hóa mà thành phố mang lại.","audioKind":"ex2"}],"collocations":[{"en":"portray someone as","vi":"khắc họa ai đó như là"},{"en":"accurately portray","vi":"khắc họa chính xác"},{"en":"portray a character","vi":"đóng một vai diễn"}],"wordFamily":["portrayal (n.)"],"synonyms":["depict","represent"],"antonyms":[],"tipVi":"Thường dùng cấu trúc \"portray A as B\", nghĩa là khắc họa A như là B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_craft', 'en-b2-32', 'craft', '/kræft/', 'B2', 'thủ công; nghề thủ công; chế tác thủ công; làm tỉ mỉ; tàu thuyền; phương tiện bay', 'n.', 'craftsman (n.), craftsmanship (n.), handicraft (n.)', NULL, 'Khi chỉ tàu thuyền hoặc phương tiện bay, craft có hình thức số ít và số nhiều giống nhau.', 'My neighbour teaches the craft of weaving willow baskets.', NULL, 'Hàng xóm của tôi dạy nghề đan giỏ liễu.', '{"wordId":"craft","ukIpa":"/krɑːft/","usIpa":"/kræft/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"An activity involving skill in making things by hand","vi":"thủ công; nghề thủ công"},{"pos":"v.","en":"Make something carefully and skilfully","vi":"chế tác thủ công; làm tỉ mỉ"},{"pos":"n.","en":"A boat, aircraft, or spacecraft","vi":"tàu thuyền; phương tiện bay"}],"examples":[{"en":"My neighbour teaches the craft of weaving willow baskets.","vi":"Hàng xóm của tôi dạy nghề đan giỏ liễu.","audioKind":"ex"},{"en":"Traditional craft workshops can preserve cultural knowledge while creating employment opportunities in rural communities.","vi":"Các xưởng thủ công truyền thống có thể lưu giữ tri thức văn hóa đồng thời tạo ra cơ hội việc làm cho các cộng đồng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"traditional crafts","vi":"thủ công truyền thống"},{"en":"learn a craft","vi":"học một nghề thủ công"},{"en":"craft a proposal","vi":"soạn thảo một đề xuất"},{"en":"landing craft","vi":"tàu đổ bộ"}],"wordFamily":["craftsman (n.)","craftsmanship (n.)","handicraft (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ tàu thuyền hoặc phương tiện bay, craft có hình thức số ít và số nhiều giống nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_villain', 'en-b2-32', 'villain', '/ˈvɪlən/', 'B2', 'nhân vật phản diện; kẻ ác; thủ phạm; nguyên nhân chính gây ra rắc rối', 'n.', 'villainous (adj.), villainy (n.)', 'Đồng nghĩa: evildoer · Trái nghĩa: hero', 'Thường chỉ nhân vật phản diện trong câu chuyện; đừng nhầm lẫn với villa "biệt thự".', 'The villain hid the stolen jewels inside a boot.', NULL, 'Kẻ ác đã giấu những món đồ trang sức bị đánh cắp bên trong một chiếc ủng.', '{"wordId":"villain","ukIpa":"/ˈvɪlən/","usIpa":"/ˈvɪlən/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"an evil character in a story, or a cruel person","vi":"nhân vật phản diện; kẻ ác"},{"pos":"n.","en":"someone or something considered responsible for a problem","vi":"thủ phạm; nguyên nhân chính gây ra rắc rối"}],"examples":[{"en":"The villain hid the stolen jewels inside a boot.","vi":"Kẻ ác đã giấu những món đồ trang sức bị đánh cắp bên trong một chiếc ủng.","audioKind":"ex"},{"en":"Films often portray a single villain, although real social problems usually have more complex causes.","vi":"Phim ảnh thường khắc họa một nhân vật phản diện đơn lẻ, mặc dù các vấn đề xã hội thực tế thường có nguyên nhân phức tạp hơn.","audioKind":"ex2"}],"collocations":[{"en":"play the villain","vi":"vào vai phản diện"},{"en":"the villain of the story","vi":"nhân vật phản diện trong câu chuyện"},{"en":"the real villain","vi":"thủ phạm thực sự"}],"wordFamily":["villainous (adj.)","villainy (n.)"],"synonyms":["evildoer"],"antonyms":["hero"],"tipVi":"Thường chỉ nhân vật phản diện trong câu chuyện; đừng nhầm lẫn với villa \"biệt thự\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_autobiography', 'en-b2-32', 'autobiography', '/ˌɔːtəbaɪˈɑːɡrəfi/', 'B2', 'tự truyện', 'n.', 'autobiographical (adj.), autobiographer (n.)', NULL, 'autobiography là cuốn sách do chính nhân vật tự viết về cuộc đời mình; còn biography là tiểu sử do người khác viết.', 'My grandmother is writing her autobiography at the kitchen table.', NULL, 'Bà tôi đang ngồi viết cuốn tự truyện của mình bên chiếc bàn bếp.', '{"wordId":"autobiography","ukIpa":"/ˌɔːtəbaɪˈɒɡrəfi/","usIpa":"/ˌɔːtəbaɪˈɑːɡrəfi/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"a book about someone''s life written by that person","vi":"tự truyện"}],"examples":[{"en":"My grandmother is writing her autobiography at the kitchen table.","vi":"Bà tôi đang ngồi viết cuốn tự truyện của mình bên chiếc bàn bếp.","audioKind":"ex"},{"en":"An autobiography offers insights into personal experience, although its account of historical events may be selective.","vi":"Một cuốn tự truyện mang lại góc nhìn sâu sắc về trải nghiệm cá nhân, mặc dù cách thuật lại các sự kiện lịch sử trong đó có thể mang tính chọn lọc.","audioKind":"ex2"}],"collocations":[{"en":"write an autobiography","vi":"viết tự truyện"},{"en":"publish an autobiography","vi":"xuất bản tự truyện"},{"en":"a bestselling autobiography","vi":"cuốn tự truyện bán chạy nhất"}],"wordFamily":["autobiographical (adj.)","autobiographer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"autobiography là cuốn sách do chính nhân vật tự viết về cuộc đời mình; còn biography là tiểu sử do người khác viết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_32_1', 'en-b2-32', 'Cách dùng “narrative” (n.) — bài tường thuật; câu chuyện', 'personal narrative  ·  dominant narrative  ·  narrative structure', 'Khi làm danh từ, từ này chỉ cốt truyện hoặc bài tường thuật; khi làm tính từ, nó thường bổ nghĩa cho cấu trúc hoặc kỹ thuật.', 'Họ từ (Word Family): narrate (v.), narration (n.), narrator (n.) | Đồng nghĩa: account, story', '[{"hanzi":"Her travel diary contains a lively narrative of the journey.","pinyin":"","meaning":"Nhật ký du lịch của cô ấy chứa đựng một bản tường thuật sinh động về chuyến hành trình."},{"hanzi":"Museums can use personal narratives to help visitors understand how historical events affected the lives of ordinary people.","pinyin":"","meaning":"Các bảo tàng có thể sử dụng những câu chuyện cá nhân để giúp khách tham quan hiểu được các sự kiện lịch sử đã tác động ra sao đến cuộc sống của những người bình thường."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_32_2', 'en-b2-32', 'Cách dùng “autobiography” (n.) — tự truyện', 'write an autobiography  ·  publish an autobiography  ·  a bestselling autobiography', 'autobiography là cuốn sách do chính nhân vật tự viết về cuộc đời mình; còn biography là tiểu sử do người khác viết.', 'Họ từ (Word Family): autobiographical (adj.), autobiographer (n.)', '[{"hanzi":"My grandmother is writing her autobiography at the kitchen table.","pinyin":"","meaning":"Bà tôi đang ngồi viết cuốn tự truyện của mình bên chiếc bàn bếp."},{"hanzi":"An autobiography offers insights into personal experience, although its account of historical events may be selective.","pinyin":"","meaning":"Một cuốn tự truyện mang lại góc nhìn sâu sắc về trải nghiệm cá nhân, mặc dù cách thuật lại các sự kiện lịch sử trong đó có thể mang tính chọn lọc."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_32_3', 'en-b2-32', 'Cách dùng “potter” (n.) — thợ gốm; người làm gốm', 'a skilled potter  ·  a potter''s wheel  ·  potter about the garden', 'Khi dùng làm động từ, thường gặp cụm potter about/around, chỉ việc bận rộn thong thả với những việc nhỏ nhặt.', 'Họ từ (Word Family): pottery (n.), pot (n.) | Đồng nghĩa: ceramicist', '[{"hanzi":"The potter shaped a bowl with her wet hands.","pinyin":"","meaning":"Người thợ gốm đã tạo hình chiếc bát bằng đôi bàn tay ẩm ướt của mình."},{"hanzi":"Local potters can preserve traditional skills while attracting visitors interested in the region''s cultural heritage.","pinyin":"","meaning":"Những người thợ gốm địa phương có thể bảo tồn các kỹ năng truyền thống đồng thời thu hút du khách quan tâm đến di sản văn hóa của vùng."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_32_4', 'en-b2-32', 'Cách dùng “canvas” (n.) — vải bạt; loại vải dày, chắc dùng cho lều, túi và buồm', 'canvas bag  ·  canvas tent  ·  oil on canvas', 'Canvas khi chỉ chất liệu vải là danh từ không đếm được; khi chỉ một bức tranh vẽ trên vải bố thì đếm được.', NULL, '[{"hanzi":"She packed her lunch in a sturdy canvas bag.","pinyin":"","meaning":"Cô ấy đựng bữa trưa trong một chiếc túi vải bạt chắc chắn."},{"hanzi":"Painting on canvas allows students to explore colour and texture while developing their creative confidence.","pinyin":"","meaning":"Vẽ tranh trên vải bố giúp học sinh khám phá màu sắc và kết cấu đồng thời phát triển sự tự tin sáng tạo của các em."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_32_1', 'en-b2-32', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
