INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_32_1_3', 'ten_b2_32_1', 'chorus', 'Everyone joined in when the song reached its chorus.', 'Everyone joined in when the song reached its chorus.', '/ˈkɔːrəs/', 'Mọi người cùng hòa giọng khi bài hát đến đoạn điệp khúc.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_32_1_4', 'ten_b2_32_1', 'rap', 'My brother listens to rap while he cooks dinner.', 'My brother listens to rap while he cooks dinner.', '/ræp/', 'Anh trai tôi nghe nhạc rap trong lúc nấu bữa tối.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_32_1_5', 'ten_b2_32_1', 'melody', 'She hummed a gentle melody while watering the plants.', 'She hummed a gentle melody while watering the plants.', '/ˈmelədi/', 'Cô ấy vừa tưới cây vừa khẽ ngân nga một giai điệu dịu dàng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_32_1_6', 'ten_b2_32_1', 'compose', 'She composed a short tune on her old piano.', 'She composed a short tune on her old piano.', '/kəmˈpoʊz/', 'Cô ấy đã sáng tác một bản nhạc ngắn trên cây đàn piano cũ của mình.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_32_1_7', 'ten_b2_32_1', 'creation', 'The creation of our garden took several busy weekends.', 'The creation of our garden took several busy weekends.', '/kriˈeɪʃən/', 'Công viên của chúng tôi đã mất vài tuần bận rộn mới được tạo nên.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_32_1_8', 'ten_b2_32_1', 'potter', 'The potter shaped a bowl with her wet hands.', 'The potter shaped a bowl with her wet hands.', '/ˈpɑːtɚ/', 'Người thợ gốm đã tạo hình chiếc bát bằng đôi bàn tay ẩm ướt của mình.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_32_1_1', 'en-b2-32', 'ten_b2_32_1', 'listening', 'listening', 'Everyone fell silent when she began her violin solo.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Công viên của chúng tôi đã mất vài tuần bận rộn mới được tạo nên.","Kẻ ác đã giấu những món đồ trang sức bị đánh cắp bên trong một chiếc ủng.","Cô ấy đựng bữa trưa trong một chiếc túi vải bạt chắc chắn.","Mọi người đều trở nên im lặng khi cô ấy bắt đầu bản độc tấu vĩ cầm của mình."]'::jsonb, 3, 'Everyone fell silent when she began her violin solo. → Mọi người đều trở nên im lặng khi cô ấy bắt đầu bản độc tấu vĩ cầm của mình.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_32_1_2', 'en-b2-32', 'ten_b2_32_1', 'listening', 'listening', 'Her travel diary contains a lively narrative of the journey.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hàng xóm của tôi dạy nghề đan giỏ liễu.","Mọi người đều trở nên im lặng khi cô ấy bắt đầu bản độc tấu vĩ cầm của mình.","Người thợ gốm đã tạo hình chiếc bát bằng đôi bàn tay ẩm ướt của mình.","Nhật ký du lịch của cô ấy chứa đựng một bản tường thuật sinh động về chuyến hành trình."]'::jsonb, 3, 'Her travel diary contains a lively narrative of the journey. → Nhật ký du lịch của cô ấy chứa đựng một bản tường thuật sinh động về chuyến hành trình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_32_1_3', 'en-b2-32', 'ten_b2_32_1', 'listening', 'listening', 'Everyone joined in when the song reached its chorus.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy đựng bữa trưa trong một chiếc túi vải bạt chắc chắn.","Bà tôi đang ngồi viết cuốn tự truyện của mình bên chiếc bàn bếp.","Mọi người cùng hòa giọng khi bài hát đến đoạn điệp khúc.","Lena đã luyện tập bài hát của cô ấy trước buổi thử giọng vào ngày hôm qua."]'::jsonb, 2, 'Everyone joined in when the song reached its chorus. → Mọi người cùng hòa giọng khi bài hát đến đoạn điệp khúc.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_32_2', 'en-b2-32', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_32_2_1', 'ten_b2_32_2', 'solo', 'Solo travel can encourage independence by requiring individuals to manage unfamiliar situations without relying on companions.', 'Solo travel can encourage independence by requiring individuals to manage unfamiliar situations without relying on companions.', '/ˈsoʊloʊ/', 'Việc du lịch một mình có thể thúc đẩy tính độc lập bằng cách đòi hỏi cá nhân phải tự xử lý các tình huống xa lạ mà không dựa dẫm vào bạn đồng hành.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_32_2_2', 'ten_b2_32_2', 'narrative', 'Museums can use personal narratives to help visitors understand how historical events affected the lives of ordinary people.', 'Museums can use personal narratives to help visitors understand how historical events affected the lives of ordinary people.', '/ˈnærətɪv/', 'Các bảo tàng có thể sử dụng những câu chuyện cá nhân để giúp khách tham quan hiểu được các sự kiện lịch sử đã tác động ra sao đến cuộc sống của những người bình thường.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_32_2_3', 'ten_b2_32_2', 'chorus', 'A memorable chorus can help environmental campaign songs reach wider audiences and encourage participation in community activities.', 'A memorable chorus can help environmental campaign songs reach wider audiences and encourage participation in community activities.', '/ˈkɔːrəs/', 'Một đoạn điệp khúc dễ nhớ có thể giúp các bài hát tuyên truyền về môi trường tiếp cận được nhiều khán giả hơn và khuyến khích mọi người tham gia các hoạt động cộng đồng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_32_2_4', 'ten_b2_32_2', 'rap', 'Rap can give young people a creative way to express their experiences and discuss social issues.', 'Rap can give young people a creative way to express their experiences and discuss social issues.', '/ræp/', 'Nhạc rap có thể mang lại cho giới trẻ một phương thức sáng tạo để bày tỏ trải nghiệm của bản thân và thảo luận các vấn đề xã hội.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_32_2_5', 'ten_b2_32_2', 'melody', 'A memorable melody can help children recall information, making music a useful tool in early education.', 'A memorable melody can help children recall information, making music a useful tool in early education.', '/ˈmelədi/', 'Một giai điệu dễ nhớ có thể giúp trẻ em ghi nhớ thông tin, biến âm nhạc thành một công cụ hữu ích trong giáo dục mầm non.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_32_2_6', 'ten_b2_32_2', 'compose', 'Students who compose their own music can develop creativity while gaining a deeper understanding of musical structure.', 'Students who compose their own music can develop creativity while gaining a deeper understanding of musical structure.', '/kəmˈpoʊz/', 'Những học sinh tự sáng tác âm nhạc có thể phát triển sự sáng tạo đồng thời hiểu sâu hơn về cấu trúc âm nhạc.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_32_2_1', 'en-b2-32', 'ten_b2_32_2', 'listening', 'listening', 'Solo travel can encourage independence by requiring individuals to manage unfamiliar situations without relying on companions.', NULL, 'Trong câu vừa nghe, từ “solo” mang nghĩa nào sau đây?', '["bản độc tấu; bài đơn ca","giống; tương tự","cố vấn; giáo viên hướng dẫn","dốc; dốc đứng"]'::jsonb, 0, '“solo” (/ˈsoʊloʊ/): bản độc tấu; bài đơn ca. Câu đầy đủ: Solo travel can encourage independence by requiring individuals to manage unfamiliar situations without relying on companions.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_32_2_2', 'en-b2-32', 'ten_b2_32_2', 'listening', 'listening', 'Museums can use personal narratives to help visitors understand how historical events affected the lives of ordinary people.', NULL, 'Trong câu vừa nghe, từ “narrative” mang nghĩa nào sau đây?', '["súng lục; súng ngắn","lớn tuổi hơn (thường trong cùng gia đình)","bài tường thuật; câu chuyện","bộ lạc; bộ tộc"]'::jsonb, 2, '“narrative” (/ˈnærətɪv/): bài tường thuật; câu chuyện. Câu đầy đủ: Museums can use personal narratives to help visitors understand how historical events affected the lives of ordinary people.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
