INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_32_2', 'en-b2-32', NULL, 'comprehensive_test', 'listening', 'Her travel diary contains a lively narrative of the journey.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy cắm hoa tươi trong một chiếc bình gốm màu xanh.","Cô ấy mặc một chiếc đầm xanh thanh lịch đi dự tiệc tối.","Lena đã luyện tập bài hát của cô ấy trước buổi thử giọng vào ngày hôm qua.","Nhật ký du lịch của cô ấy chứa đựng một bản tường thuật sinh động về chuyến hành trình."]'::jsonb, 3, 'Her travel diary contains a lively narrative of the journey. → Nhật ký du lịch của cô ấy chứa đựng một bản tường thuật sinh động về chuyến hành trình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_32_3', 'en-b2-32', NULL, 'comprehensive_test', 'listening', 'chorus', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chín; làm cho chín","hàng hóa (chuyên chở bằng tàu thủy, máy bay hoặc phương tiện lớn)","đoạn điệp khúc; khúc nối (trong bài hát)","máy khoan; cái khoan"]'::jsonb, 2, 'chorus (/ˈkɔːrəs/) → đoạn điệp khúc; khúc nối (trong bài hát); dàn đồng ca; tiếng hô đồng thanh; đồng thanh nói; đồng thanh hát', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_32_4', 'en-b2-32', NULL, 'comprehensive_test', 'listening', 'My brother listens to rap while he cooks dinner.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Anh trai tôi nghe nhạc rap trong lúc nấu bữa tối.","Anh họ tôi đã làm một lâu đài thu nhỏ từ gỗ thừa.","Cô ấy cắm hoa tươi trong một chiếc bình gốm màu xanh.","Người thợ gốm đã tạo hình chiếc bát bằng đôi bàn tay ẩm ướt của mình."]'::jsonb, 0, 'My brother listens to rap while he cooks dinner. → Anh trai tôi nghe nhạc rap trong lúc nấu bữa tối.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_32_5', 'en-b2-32', NULL, 'comprehensive_test', 'listening', 'melody', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["khả năng xảy ra","nhàn rỗi; không hoạt động; bỏ không","ở dưới biển; dưới mặt nước biển","giai điệu; khúc ca"]'::jsonb, 3, 'melody (/ˈmelədi/) → giai điệu; khúc ca', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_32_6', 'en-b2-32', NULL, 'comprehensive_test', 'listening', 'She composed a short tune on her old piano.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những bức tranh của cô ấy khắc họa cuộc sống làng quê bằng những gam màu ấm áp.","Cuốn sách có hình minh họa một con cá voi rất đẹp.","Cô ấy đã sáng tác một bản nhạc ngắn trên cây đàn piano cũ của mình.","Bà tôi đang ngồi viết cuốn tự truyện của mình bên chiếc bàn bếp."]'::jsonb, 2, 'She composed a short tune on her old piano. → Cô ấy đã sáng tác một bản nhạc ngắn trên cây đàn piano cũ của mình.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_32_7', 'en-b2-32', NULL, 'comprehensive_test', 'listening', 'creation', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["run rẩy; đánh cầm cập","khả năng xảy ra","bó hoa","sự tạo ra; quá trình sáng tạo; sự thành lập"]'::jsonb, 3, 'creation (/kriˈeɪʃən/) → sự tạo ra; quá trình sáng tạo; sự thành lập; tác phẩm; sáng tạo phẩm', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_32_8', 'en-b2-32', NULL, 'comprehensive_test', 'listening', 'The potter shaped a bowl with her wet hands.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy đựng bữa trưa trong một chiếc túi vải bạt chắc chắn.","Mọi người cùng hòa giọng khi bài hát đến đoạn điệp khúc.","Người thợ gốm đã tạo hình chiếc bát bằng đôi bàn tay ẩm ướt của mình.","Anh họ tôi đã làm một lâu đài thu nhỏ từ gỗ thừa."]'::jsonb, 2, 'The potter shaped a bowl with her wet hands. → Người thợ gốm đã tạo hình chiếc bát bằng đôi bàn tay ẩm ướt của mình.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
