INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_32_18', 'en-b2-32', NULL, 'comprehensive_test', 'reading', NULL, 'Solo travel can encourage independence by requiring individuals to manage unfamiliar situations without relying on companions.', 'Dựa vào câu trên, từ “solo” có nghĩa phù hợp nhất là gì?', '["bản độc tấu; bài đơn ca","sưng tấy, sưng phồng (do chấn thương hoặc bệnh tật)","cơn giận; tính khí; tâm trạng cáu kỉnh","cấp phó; người đại diện; người phụ tá"]'::jsonb, 0, 'solo: bản độc tấu; bài đơn ca; đơn; độc tấu; một mình; không có sự giúp đỡ của người khác. Dịch cả câu: Việc du lịch một mình có thể thúc đẩy tính độc lập bằng cách đòi hỏi cá nhân phải tự xử lý các tình huống xa lạ mà không dựa dẫm vào bạn đồng hành.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_32_19', 'en-b2-32', NULL, 'comprehensive_test', 'reading', NULL, 'Museums can use personal narratives to help visitors understand how historical events affected the lives of ordinary people.', 'Dựa vào câu trên, từ “narrative” có nghĩa phù hợp nhất là gì?', '["nguyên tắc; phương châm sống","khả năng phán đoán; sự đánh giá","bài tường thuật; câu chuyện","thuộc về cơ khí; thuộc về máy móc"]'::jsonb, 2, 'narrative: bài tường thuật; câu chuyện; hệ thống quan điểm; góc nhìn giải thích; mang tính tường thuật. Dịch cả câu: Các bảo tàng có thể sử dụng những câu chuyện cá nhân để giúp khách tham quan hiểu được các sự kiện lịch sử đã tác động ra sao đến cuộc sống của những người bình thường.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_32_20', 'en-b2-32', NULL, 'comprehensive_test', 'reading', NULL, 'A memorable chorus can help environmental campaign songs reach wider audiences and encourage participation in community activities.', 'Dựa vào câu trên, từ “chorus” có nghĩa phù hợp nhất là gì?', '["sự tuyệt chủng; sự tiêu vong hoàn toàn","gia súc; vật nuôi","sáng tác (nhạc); viết (văn bản)","đoạn điệp khúc; khúc nối (trong bài hát)"]'::jsonb, 3, 'chorus: đoạn điệp khúc; khúc nối (trong bài hát); dàn đồng ca; tiếng hô đồng thanh; đồng thanh nói; đồng thanh hát. Dịch cả câu: Một đoạn điệp khúc dễ nhớ có thể giúp các bài hát tuyên truyền về môi trường tiếp cận được nhiều khán giả hơn và khuyến khích mọi người tham gia các hoạt động cộng đồng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_32_21', 'en-b2-32', NULL, 'comprehensive_test', 'reading', NULL, 'Rap can give young people a creative way to express their experiences and discuss social issues.', 'Dựa vào câu trên, từ “rap” có nghĩa phù hợp nhất là gì?', '["nhạc rap; ca khúc rap","liên quan đến tình dục; thuộc về giới tính","từ chối; bác bỏ","va chạm; đâm vào nhau"]'::jsonb, 0, 'rap: nhạc rap; ca khúc rap; hát rap; đọc rap; gõ nhanh; đập nhẹ và nhanh. Dịch cả câu: Nhạc rap có thể mang lại cho giới trẻ một phương thức sáng tạo để bày tỏ trải nghiệm của bản thân và thảo luận các vấn đề xã hội.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_32_22', 'en-b2-32', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thủ công; nghề thủ công”', '["calcium","audition","massive","craft"]'::jsonb, 3, 'thủ công; nghề thủ công → craft (/kræft/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
