INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-33', 'en', 'Bài 33: Nghệ thuật & Sáng tạo (3) - CEFR B2', 'CEFR B2', 'B2 · Nghệ thuật', '21 từ vựng Tiếng Anh CEFR B2 chủ đề nghệ thuật & sáng tạo kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4033, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_legend', 'en-b2-33', 'legend', '/ˈledʒənd/', 'B2', 'truyền thuyết; sự tích; nhân vật huyền thoại; tượng đài; chú giải bản đồ; phần giải thích ký hiệu', 'n.', 'legendary (adj.)', NULL, 'Từ legend có thể bắt nguồn từ nguyên mẫu lịch sử nhưng không đồng nghĩa với một sự thật lịch sử đã được kiểm chứng.', 'Grandma told us a legend about a sleeping dragon.', NULL, 'Bà đã kể cho chúng tôi nghe một truyền thuyết về một con rồng đang ngủ say.', '{"wordId":"legend","ukIpa":"/ˈledʒənd/","usIpa":"/ˈledʒənd/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"an old popular story that may not be historically true","vi":"truyền thuyết; sự tích"},{"pos":"n.","en":"someone greatly admired for exceptional achievements","vi":"nhân vật huyền thoại; tượng đài"},{"pos":"n.","en":"a guide explaining the symbols used on a map or chart","vi":"chú giải bản đồ; phần giải thích ký hiệu"}],"examples":[{"en":"Grandma told us a legend about a sleeping dragon.","vi":"Bà đã kể cho chúng tôi nghe một truyền thuyết về một con rồng đang ngủ say.","audioKind":"ex"},{"en":"Local legends can strengthen cultural identity while attracting visitors interested in the history of a region.","vi":"Những truyền thuyết địa phương vừa có thể củng cố bản sắc văn hóa vừa thu hút du khách quan tâm đến lịch sử của một vùng đất.","audioKind":"ex2"}],"collocations":[{"en":"according to legend","vi":"theo truyền thuyết"},{"en":"local legend","vi":"truyền thuyết địa phương"},{"en":"a living legend","vi":"một huyền thoại sống"},{"en":"map legend","vi":"chú giải bản đồ"}],"wordFamily":["legendary (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ legend có thể bắt nguồn từ nguyên mẫu lịch sử nhưng không đồng nghĩa với một sự thật lịch sử đã được kiểm chứng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bead', 'en-b2-33', 'bead', '/biːd/', 'B2', 'hạt cườm; hạt chuỗi; giọt (chất lỏng nhỏ, tròn)', 'n.', 'beaded (adj.), beading (n.)', NULL, 'Nghĩa chỉ giọt chất lỏng thường dùng cụm a bead of sweat để chỉ một giọt mồ hôi.', 'She threaded a blue bead onto the silver wire.', NULL, 'Cô ấy xâu một hạt cườm màu xanh vào sợi dây bạc.', '{"wordId":"bead","ukIpa":"/biːd/","usIpa":"/biːd/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"A small pierced ball used in jewellery or decoration.","vi":"hạt cườm; hạt chuỗi"},{"pos":"n.","en":"A small round drop of liquid.","vi":"giọt (chất lỏng nhỏ, tròn)"}],"examples":[{"en":"She threaded a blue bead onto the silver wire.","vi":"Cô ấy xâu một hạt cườm màu xanh vào sợi dây bạc.","audioKind":"ex"},{"en":"Traditional bead jewellery can provide income for local craftspeople while preserving skills passed down through generations.","vi":"Trang sức hạt cườm truyền thống vừa mang lại thu nhập cho thợ thủ công địa phương, vừa gìn giữ các kỹ năng được truyền qua nhiều thế hệ.","audioKind":"ex2"}],"collocations":[{"en":"glass beads","vi":"hạt cườm bằng thủy tinh"},{"en":"string beads","vi":"xâu hạt cườm"},{"en":"a bead of sweat","vi":"một giọt mồ hôi"}],"wordFamily":["beaded (adj.)","beading (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa chỉ giọt chất lỏng thường dùng cụm a bead of sweat để chỉ một giọt mồ hôi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_authentic', 'en-b2-33', 'authentic', '/ɔːˈθentɪk/', 'B2', 'chính gốc; đích thực; chuẩn vị; chân thực; đáng tin cậy', 'adj.', 'authenticity (n.), authenticate (v.), authentically (adv.)', 'Đồng nghĩa: genuine, real · Trái nghĩa: fake', 'authentic nhấn mạnh tính nguyên bản hoặc chính gốc, không chỉ đơn thuần là đúng sự thật.', 'This small restaurant serves authentic dishes from the region.', NULL, 'Nhà hàng nhỏ này phục vụ các món ăn chính gốc từ vùng miền đó.', '{"wordId":"authentic","ukIpa":"/ɔːˈθentɪk/","usIpa":"/ɔːˈθentɪk/","cefr":"B2","topic":"arts","senses":[{"pos":"adj.","en":"Genuine or traditional, rather than copied or invented","vi":"chính gốc; đích thực; chuẩn vị"},{"pos":"adj.","en":"Accurately representing real events, experiences, or conditions","vi":"chân thực; đáng tin cậy"}],"examples":[{"en":"This small restaurant serves authentic dishes from the region.","vi":"Nhà hàng nhỏ này phục vụ các món ăn chính gốc từ vùng miền đó.","audioKind":"ex"},{"en":"Museums should preserve authentic objects while using digital tools to make local history more accessible.","vi":"Các bảo tàng nên bảo tồn các hiện vật nguyên bản đồng thời sử dụng các công cụ kỹ thuật số để lịch sử địa phương trở nên gần gũi hơn với công chúng.","audioKind":"ex2"}],"collocations":[{"en":"authentic cuisine","vi":"ẩm thực chính gốc"},{"en":"authentic experience","vi":"trải nghiệm chân thực"},{"en":"authentic account","vi":"bản tường thuật chân thực"}],"wordFamily":["authenticity (n.)","authenticate (v.)","authentically (adv.)"],"synonyms":["genuine","real"],"antonyms":["fake"],"tipVi":"authentic nhấn mạnh tính nguyên bản hoặc chính gốc, không chỉ đơn thuần là đúng sự thật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_acrobat', 'en-b2-33', 'acrobat', '/ˈækrəbæt/', 'B2', 'diễn viên xiêng; nghệ sĩ nhào lộn', 'n.', 'acrobatic (adj.), acrobatics (n.), acrobatically (adv.)', NULL, 'acrobat chỉ người biểu diễn; acrobatics chỉ nghệ thuật hoặc kỹ năng nhào lộn.', 'The acrobat balanced on one hand above the soft mat.', NULL, 'Nghệ sĩ nhào lộn đứng bằng một tay trên tấm thảm mềm.', '{"wordId":"acrobat","ukIpa":"/ˈækrəbæt/","usIpa":"/ˈækrəbæt/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"A performer who does difficult balancing, jumping, or gymnastic movements.","vi":"diễn viên xiêng; nghệ sĩ nhào lộn"}],"examples":[{"en":"The acrobat balanced on one hand above the soft mat.","vi":"Nghệ sĩ nhào lộn đứng bằng một tay trên tấm thảm mềm.","audioKind":"ex"},{"en":"Training as an acrobat requires sustained physical discipline, making injury prevention an essential part of professional education.","vi":"Việc huấn luyện để trở thành một nghệ sĩ nhào lộn đòi hỏi kỷ luật thể chất bền bỉ, khiến việc phòng ngừa chấn thương trở thành một phần thiết yếu trong đào tạo chuyên nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"skilled acrobat","vi":"nghệ sĩ nhào lộn lành nghề"},{"en":"circus acrobat","vi":"diễn viên xiếc nhào lộn"},{"en":"professional acrobat","vi":"nghệ sĩ nhào lộn chuyên nghiệp"}],"wordFamily":["acrobatic (adj.)","acrobatics (n.)","acrobatically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"acrobat chỉ người biểu diễn; acrobatics chỉ nghệ thuật hoặc kỹ năng nhào lộn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_novelist', 'en-b2-33', 'novelist', '/ˈnɑːvəlɪst/', 'B2', 'tiểu thuyết gia; nhà văn viết tiểu thuyết', 'n.', 'novel (n.)', 'Đồng nghĩa: fiction writer', 'novelist thường chỉ tác giả viết tiểu thuyết dài, novel là tiểu thuyết dài.', 'The novelist spends every morning writing at her kitchen table.', NULL, 'Nữ tiểu thuyết gia dành mỗi buổi sáng để viết lách bên chiếc bàn trong bếp của cô ấy.', '{"wordId":"novelist","ukIpa":"/ˈnɒvəlɪst/","usIpa":"/ˈnɑːvəlɪst/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"A person who writes novels.","vi":"tiểu thuyết gia; nhà văn viết tiểu thuyết"}],"examples":[{"en":"The novelist spends every morning writing at her kitchen table.","vi":"Nữ tiểu thuyết gia dành mỗi buổi sáng để viết lách bên chiếc bàn trong bếp của cô ấy.","audioKind":"ex"},{"en":"A skilled novelist can reveal social inequalities through characters whose experiences differ greatly from those of readers.","vi":"Một tiểu thuyết gia tài năng có thể vạch trần sự bất bình đẳng xã hội thông qua các nhân vật có trải nghiệm khác biệt lớn so với độc giả.","audioKind":"ex2"}],"collocations":[{"en":"historical novelist","vi":"tiểu thuyết gia viết về lịch sử"},{"en":"bestselling novelist","vi":"tác giả tiểu thuyết bán chạy nhất"},{"en":"aspiring novelist","vi":"người có hoài bão viết tiểu thuyết"}],"wordFamily":["novel (n.)"],"synonyms":["fiction writer"],"antonyms":[],"tipVi":"novelist thường chỉ tác giả viết tiểu thuyết dài, novel là tiểu thuyết dài.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_graceful', 'en-b2-33', 'graceful', '/ˈɡreɪsfəl/', 'B2', 'uyển chuyển; duyên dáng; thanh tú', 'adj.', 'grace (n.), gracefully (adv.), gracefulness (n.)', 'Đồng nghĩa: elegant · Trái nghĩa: clumsy, awkward', 'graceful thường miêu tả dáng vẻ, động tác uyển chuyển; gracious thường chỉ sự nhã nhặn, lịch thiệp.', 'The swan made a graceful turn across the pond.', NULL, 'Con thiên nga có cú uốn mình uyển chuyển bơi lội trên mặt hồ.', '{"wordId":"graceful","ukIpa":"/ˈɡreɪsfəl/","usIpa":"/ˈɡreɪsfəl/","cefr":"B2","topic":"arts","senses":[{"pos":"adj.","en":"Moving or shaped in a smooth, attractive way.","vi":"uyển chuyển; duyên dáng; thanh tú"}],"examples":[{"en":"The swan made a graceful turn across the pond.","vi":"Con thiên nga có cú uốn mình uyển chuyển bơi lội trên mặt hồ.","audioKind":"ex"},{"en":"The bridge combines graceful curves with practical engineering, creating an attractive landmark for the city.","vi":"Cây cầu kết hợp giữa các đường cong uyển chuyển và kỹ thuật xây dựng thực tế, tạo nên một thắng cảnh nổi bật cho thành phố.","audioKind":"ex2"}],"collocations":[{"en":"graceful movements","vi":"những chuyển động uyển chuyển"},{"en":"graceful curves","vi":"đường cong duyên dáng"},{"en":"a graceful dancer","vi":"một vũ công có dáng múa uyển chuyển"}],"wordFamily":["grace (n.)","gracefully (adv.)","gracefulness (n.)"],"synonyms":["elegant"],"antonyms":["clumsy","awkward"],"tipVi":"graceful thường miêu tả dáng vẻ, động tác uyển chuyển; gracious thường chỉ sự nhã nhặn, lịch thiệp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_critic', 'en-b2-33', 'critic', '/ˈkrɪtɪk/', 'B2', 'nhà phê bình; nhà bình luận; người chỉ trích; người phản đối', 'n.', 'criticism (n.), criticise (v.), critical (adj.), critically (adv.)', 'Đồng nghĩa: reviewer, commentator', 'critic chỉ người, trong khi criticism chỉ lời phê bình hoặc sự chỉ trích.', 'The film critic praised the young actor''s performance.', NULL, 'Nhà phê bình điện ảnh đã ca ngợi màn diễn xuất của nam diễn viên trẻ.', '{"wordId":"critic","ukIpa":"/ˈkrɪtɪk/","usIpa":"/ˈkrɪtɪk/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"Someone who judges and discusses artistic works professionally.","vi":"nhà phê bình; nhà bình luận"},{"pos":"n.","en":"Someone who expresses disapproval of a person, policy, or idea.","vi":"người chỉ trích; người phản đối"}],"examples":[{"en":"The film critic praised the young actor''s performance.","vi":"Nhà phê bình điện ảnh đã ca ngợi màn diễn xuất của nam diễn viên trẻ.","audioKind":"ex"},{"en":"Critics of urban expansion argue that new developments often destroy valuable habitats and increase car dependence.","vi":"Những người chỉ trích việc mở rộng đô thị lập luận rằng các dự án phát triển mới thường phá hủy các môi trường sống quý giá và làm tăng sự phụ thuộc vào ô tô.","audioKind":"ex2"}],"collocations":[{"en":"film critic","vi":"nhà phê bình điện ảnh"},{"en":"literary critic","vi":"nhà phê bình văn học"},{"en":"an outspoken critic","vi":"một nhà chỉ trích thẳng thắn"}],"wordFamily":["criticism (n.)","criticise (v.)","critical (adj.)","critically (adv.)"],"synonyms":["reviewer","commentator"],"antonyms":[],"tipVi":"critic chỉ người, trong khi criticism chỉ lời phê bình hoặc sự chỉ trích.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_magnificent', 'en-b2-33', 'magnificent', '/mæɡˈnɪfɪsənt/', 'B2', 'tráng lệ; nguy nga; hùng vĩ; tuyệt vời; xuất sắc', 'adj.', 'magnificence (n.), magnificently (adv.)', 'Đồng nghĩa: splendid, spectacular, superb', 'Thường dùng để miêu tả phong cảnh, kiến trúc hoặc thành tựu, không dùng để chỉ phẩm chất đạo đức cao thượng.', 'The balcony offers a magnificent view of snowy mountains.', NULL, 'Ban công mang đến một tầm nhìn tráng lệ ra những dãy núi tuyết.', '{"wordId":"magnificent","ukIpa":"/mæɡˈnɪfɪsənt/","usIpa":"/mæɡˈnɪfɪsənt/","cefr":"B2","topic":"arts","senses":[{"pos":"adj.","en":"Extremely beautiful, grand, or impressive.","vi":"tráng lệ; nguy nga; hùng vĩ"},{"pos":"adj.","en":"Exceptionally good or skilfully done.","vi":"tuyệt vời; xuất sắc"}],"examples":[{"en":"The balcony offers a magnificent view of snowy mountains.","vi":"Ban công mang đến một tầm nhìn tráng lệ ra những dãy núi tuyết.","audioKind":"ex"},{"en":"Preserving magnificent historic buildings can strengthen local identity and attract visitors from other regions.","vi":"Việc bảo tồn các tòa nhà lịch sử nguy nga có thể củng cố bản sắc địa phương và thu hút du khách từ các vùng khác.","audioKind":"ex2"}],"collocations":[{"en":"magnificent scenery","vi":"cảnh sắc tráng lệ"},{"en":"a magnificent building","vi":"một tòa nhà nguy nga"},{"en":"a magnificent achievement","vi":"một thành tựu xuất sắc"}],"wordFamily":["magnificence (n.)","magnificently (adv.)"],"synonyms":["splendid","spectacular","superb"],"antonyms":[],"tipVi":"Thường dùng để miêu tả phong cảnh, kiến trúc hoặc thành tựu, không dùng để chỉ phẩm chất đạo đức cao thượng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_applaud', 'en-b2-33', 'applaud', '/əˈplɔːd/', 'B2', 'vỗ tay; hoan hô; tán dương; ca ngợi', 'v.', 'applause (n.)', 'Đồng nghĩa: clap, praise · Trái nghĩa: boo', 'Có thể kết hợp trực tiếp với tân ngữ là người hoặc sự việc; danh từ tương ứng là applause (không đếm được).', 'Everyone applauded when the young dancer finished her performance.', NULL, 'Mọi người đều vỗ tay khi nữ vũ công trẻ hoàn thành bài biểu diễn của mình.', '{"wordId":"applaud","ukIpa":"/əˈplɔːd/","usIpa":"/əˈplɔːd/","cefr":"B2","topic":"arts","senses":[{"pos":"v.","en":"Clap your hands to show enjoyment or approval.","vi":"vỗ tay; hoan hô"},{"pos":"v.","en":"Express strong approval of someone or something.","vi":"tán dương; ca ngợi"}],"examples":[{"en":"Everyone applauded when the young dancer finished her performance.","vi":"Mọi người đều vỗ tay khi nữ vũ công trẻ hoàn thành bài biểu diễn của mình.","audioKind":"ex"},{"en":"Environmental groups applauded the council''s decision to protect urban wetlands from further commercial development.","vi":"Các nhóm bảo vệ môi trường đã nhiệt liệt tán dương quyết định của hội đồng nhằm bảo vệ các vùng đất ngập nước đô thị khỏi các dự án phát triển thương mại.","audioKind":"ex2"}],"collocations":[{"en":"applaud a performance","vi":"vỗ tay tán thưởng một màn trình diễn"},{"en":"applaud a decision","vi":"tán dương một quyết định"},{"en":"applaud someone''s efforts","vi":"ca ngợi nỗ lực của ai đó"}],"wordFamily":["applause (n.)"],"synonyms":["clap","praise"],"antonyms":["boo"],"tipVi":"Có thể kết hợp trực tiếp với tân ngữ là người hoặc sự việc; danh từ tương ứng là applause (không đếm được).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rehearsal', 'en-b2-33', 'rehearsal', '/rɪˈhɝːsəl/', 'B2', 'buổi tổng duyệt; buổi diễn tập', 'n.', 'rehearse (v.)', 'Đồng nghĩa: practice, run-through', 'Một buổi rehearsal có thể đếm được; in rehearsal diễn tả trạng thái đang trong thời gian luyện tập.', 'Our final rehearsal finished just before the audience arrived.', NULL, 'Buổi tổng duyệt cuối cùng của chúng tôi vừa kết thúc ngay trước khi khán giả đến.', '{"wordId":"rehearsal","ukIpa":"/rɪˈhɜːsəl/","usIpa":"/rɪˈhɝːsəl/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"A practice session before a performance or important event.","vi":"buổi tổng duyệt; buổi diễn tập"}],"examples":[{"en":"Our final rehearsal finished just before the audience arrived.","vi":"Buổi tổng duyệt cuối cùng của chúng tôi vừa kết thúc ngay trước khi khán giả đến.","audioKind":"ex"},{"en":"Regular rehearsal helps students develop confidence and teamwork skills before they perform in front of an audience.","vi":"Việc diễn tập thường xuyên giúp học sinh phát triển sự tự tin và kỹ năng làm việc nhóm trước khi biểu diễn trước khán giả.","audioKind":"ex2"}],"collocations":[{"en":"dress rehearsal","vi":"buổi tổng duyệt trang phục"},{"en":"in rehearsal","vi":"đang trong quá trình diễn tập"},{"en":"rehearsal room","vi":"phòng tập; phòng diễn tập"}],"wordFamily":["rehearse (v.)"],"synonyms":["practice","run-through"],"antonyms":[],"tipVi":"Một buổi rehearsal có thể đếm được; in rehearsal diễn tả trạng thái đang trong thời gian luyện tập.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exhibit', 'en-b2-33', 'exhibit', '/ɪɡˈzɪbɪt/', 'B2', 'trưng bày; triển lãm; thể hiện; biểu lộ; vật trưng bày; vật chứng', 'v.', 'exhibition (n.), exhibitor (n.)', 'Đồng nghĩa: display, show', 'Trong tiếng Anh Anh, exhibit thường chỉ một món vật trưng bày đơn lẻ, còn exhibition dùng cho buổi triển lãm.', 'The local gallery exhibits pottery made by young artists.', NULL, 'Phòng tranh địa phương trưng bày các tác phẩm gốm do các nghệ sĩ trẻ thực hiện.', '{"wordId":"exhibit","ukIpa":"/ɪɡˈzɪbɪt/","usIpa":"/ɪɡˈzɪbɪt/","cefr":"B2","topic":"arts","senses":[{"pos":"v.","en":"to display objects or artworks for people to see","vi":"trưng bày; triển lãm"},{"pos":"v.","en":"to show a particular quality, feeling or behaviour","vi":"thể hiện; biểu lộ"},{"pos":"n.","en":"an object displayed publicly or presented as evidence in court","vi":"vật trưng bày; vật chứng"}],"examples":[{"en":"The local gallery exhibits pottery made by young artists.","vi":"Phòng tranh địa phương trưng bày các tác phẩm gốm do các nghệ sĩ trẻ thực hiện.","audioKind":"ex"},{"en":"Children who regularly engage in creative activities often exhibit greater confidence when solving unfamiliar problems.","vi":"Trẻ em thường xuyên tham gia vào các hoạt động sáng tạo thường thể hiện sự tự tin lớn hơn khi giải quyết các vấn đề chưa quen thuộc.","audioKind":"ex2"}],"collocations":[{"en":"exhibit artwork","vi":"trưng bày tác phẩm nghệ thuật"},{"en":"exhibit symptoms","vi":"hiện triệu chứng"},{"en":"a museum exhibit","vi":"hiện vật bảo tàng"}],"wordFamily":["exhibition (n.)","exhibitor (n.)"],"synonyms":["display","show"],"antonyms":[],"tipVi":"Trong tiếng Anh Anh, exhibit thường chỉ một món vật trưng bày đơn lẻ, còn exhibition dùng cho buổi triển lãm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clay', 'en-b2-33', 'clay', '/kleɪ/', 'B2', 'đất sét; đất nung', 'n.', 'clayey (adj.)', NULL, 'Thường không đếm được; a piece of clay dùng để chỉ một khối đất sét.', 'The children shaped wet clay into tiny bowls.', NULL, 'Bọn trẻ nặn đất sét ướt thành những chiếc bát nhỏ.', '{"wordId":"clay","ukIpa":"/kleɪ/","usIpa":"/kleɪ/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"Heavy earth that can be shaped when wet and baked hard.","vi":"đất sét; đất nung"}],"examples":[{"en":"The children shaped wet clay into tiny bowls.","vi":"Bọn trẻ nặn đất sét ướt thành những chiếc bát nhỏ.","audioKind":"ex"},{"en":"Traditional clay buildings can provide effective insulation, helping communities maintain comfortable indoor temperatures with less energy.","vi":"Các công trình xây dựng bằng đất sét truyền thống có thể cách nhiệt hiệu quả, giúp cộng đồng duy trì nhiệt độ trong nhà thoải mái với ít năng lượng hơn.","audioKind":"ex2"}],"collocations":[{"en":"wet clay","vi":"đất sét ướt"},{"en":"clay soil","vi":"đất thịt pha sét"},{"en":"a clay pot","vi":"chậu đất sét"},{"en":"shape clay","vi":"nặn đất sét"}],"wordFamily":["clayey (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường không đếm được; a piece of clay dùng để chỉ một khối đất sét.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_weave', 'en-b2-33', 'weave', '/wiːv/', 'B2', 'dệt; đan; lách qua; di chuyển vòng tránh chướng ngại vật liên tục; lồng ghép; kết hợp các yếu tố khác nhau thành một câu chuyện hoặc tổng thể gắn kết', 'v.', 'weaver (n.), weaving (n.), woven (adj.)', NULL, 'Dạng quá khứ của dệt/đan là wove, phân từ hai là woven.', 'My aunt taught me to weave a small basket.', NULL, 'Cô tôi đã dạy tôi cách đan một chiếc giỏ nhỏ.', '{"wordId":"weave","ukIpa":"/wiːv/","usIpa":"/wiːv/","cefr":"B2","topic":"arts","senses":[{"pos":"v.","en":"Make fabric or baskets by crossing threads or strips.","vi":"dệt; đan"},{"pos":"v.","en":"Move by repeatedly changing direction around obstacles.","vi":"lách qua; di chuyển vòng tránh chướng ngại vật liên tục"},{"pos":"v.","en":"Combine different elements into a connected story or whole.","vi":"lồng ghép; kết hợp các yếu tố khác nhau thành một câu chuyện hoặc tổng thể gắn kết"}],"examples":[{"en":"My aunt taught me to weave a small basket.","vi":"Cô tôi đã dạy tôi cách đan một chiếc giỏ nhỏ.","audioKind":"ex"},{"en":"Effective documentaries weave personal stories into broader discussions of social change and public policy.","vi":"Các bộ phim tài liệu hiệu quả sẽ lồng ghép những câu chuyện cá nhân vào các cuộc thảo luận rộng lớn hơn về sự thay đổi xã hội và chính sách công.","audioKind":"ex2"}],"collocations":[{"en":"weave a basket","vi":"đan giỏ"},{"en":"weave through traffic","vi":"lách qua dòng xe cộ"},{"en":"weave into a story","vi":"lồng ghép vào câu chuyện"}],"wordFamily":["weaver (n.)","weaving (n.)","woven (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ của dệt/đan là wove, phân từ hai là woven.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_heroine', 'en-b2-33', 'heroine', '/ˈheroʊɪn/', 'B2', 'nữ nhân vật chính; nữ chính; nữ anh hùng; người phụ nữ kiên cường', 'n.', 'hero (n.), heroic (adj.), heroism (n.)', NULL, 'Phát âm giống từ heroin (ma túy), cần chú ý chữ e ở cuối.', 'The heroine of this novel sails across the ocean.', NULL, 'Nữ chính của cuốn tiểu thuyết này chèo thuyền vượt đại dương.', '{"wordId":"heroine","ukIpa":"/ˈherəʊɪn/","usIpa":"/ˈheroʊɪn/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"the main female character in a story","vi":"nữ nhân vật chính; nữ chính"},{"pos":"n.","en":"a woman admired for courage or remarkable achievements","vi":"nữ anh hùng; người phụ nữ kiên cường"}],"examples":[{"en":"The heroine of this novel sails across the ocean.","vi":"Nữ chính của cuốn tiểu thuyết này chèo thuyền vượt đại dương.","audioKind":"ex"},{"en":"A confident heroine in children''s literature can challenge stereotypes and broaden young readers'' expectations.","vi":"Một nữ chính tự tin trong văn học thiếu nhi có thể thách thức các định kiến và mở rộng kỳ vọng của độc giả trẻ.","audioKind":"ex2"}],"collocations":[{"en":"the heroine of a novel","vi":"nữ chính của một cuốn tiểu thuyết"},{"en":"a national heroine","vi":"nữ anh hùng dân tộc"},{"en":"a tragic heroine","vi":"nữ nhân vật chính bi kịch"}],"wordFamily":["hero (n.)","heroic (adj.)","heroism (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Phát âm giống từ heroin (ma túy), cần chú ý chữ e ở cuối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fantasy', 'en-b2-33', 'fantasy', '/ˈfæntəsi/', 'B2', 'ảo tưởng; sự tưởng tượng; văn học kỳ ảo; thể loại kỳ ảo', 'n.', 'fantasise (v.), fantasize (v.)', 'Đồng nghĩa: daydream · Trái nghĩa: reality', 'Ý chỉ ảo tưởng cụ thể thì đếm được; khi chỉ thể loại văn học kỳ ảo thì thường không đếm được.', 'Living in a castle was my favourite childhood fantasy.', NULL, 'Sống trong một lâu đài là điều ảo tưởng thuở nhỏ tôi thích nhất.', '{"wordId":"fantasy","ukIpa":"/ˈfæntəsi/","usIpa":"/ˈfæntəsi/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"An imagined situation that is unlikely to happen","vi":"ảo tưởng; sự tưởng tượng"},{"pos":"n.","en":"Stories featuring magic, imaginary worlds, or impossible events","vi":"văn học kỳ ảo; thể loại kỳ ảo"}],"examples":[{"en":"Living in a castle was my favourite childhood fantasy.","vi":"Sống trong một lâu đài là điều ảo tưởng thuở nhỏ tôi thích nhất.","audioKind":"ex"},{"en":"Fantasy literature can encourage young readers to explore moral questions through imaginary worlds and unusual characters.","vi":"Văn học kỳ ảo có thể khuyến khích độc giả trẻ khám phá các vấn đề đạo đức thông qua các thế giới tưởng tượng và các nhân vật phi thường.","audioKind":"ex2"}],"collocations":[{"en":"a childhood fantasy","vi":"ảo tưởng thời thơ ấu"},{"en":"fantasy fiction","vi":"tiểu thuyết kỳ ảo"},{"en":"a fantasy world","vi":"thế giới kỳ ảo"},{"en":"indulge in fantasy","vi":"chìm đắm trong ảo tưởng"}],"wordFamily":["fantasise (v.)","fantasize (v.)"],"synonyms":["daydream"],"antonyms":["reality"],"tipVi":"Ý chỉ ảo tưởng cụ thể thì đếm được; khi chỉ thể loại văn học kỳ ảo thì thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_narrator', 'en-b2-33', 'narrator', '/ˈnæreɪtər/', 'B2', 'người kể chuyện; người thuyết minh; giọng đọc thuyết minh', 'n.', 'narrate (v.), narration (n.), narrative (n.)', 'Đồng nghĩa: storyteller', 'Người kể chuyện không nhất thiết phải là tác giả; trong tiểu thuyết, vai trò này có thể do một nhân vật hư cấu đảm nhiệm.', 'The narrator''s gentle voice helped me fall asleep.', NULL, 'Giọng đọc thuyết minh nhẹ nhàng đã giúp tôi dễ dàng chìm vào giấc ngủ.', '{"wordId":"narrator","ukIpa":"/nəˈreɪtə/","usIpa":"/ˈnæreɪtər/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"The person or voice telling a story","vi":"người kể chuyện; người thuyết minh; giọng đọc thuyết minh"}],"examples":[{"en":"The narrator''s gentle voice helped me fall asleep.","vi":"Giọng đọc thuyết minh nhẹ nhàng đã giúp tôi dễ dàng chìm vào giấc ngủ.","audioKind":"ex"},{"en":"An unreliable narrator encourages readers to question events and consider how personal perspectives shape their understanding of reality.","vi":"Một người kể chuyện không đáng tin cậy khuyến khích độc giả đặt câu hỏi về các sự kiện và suy ngẫm về cách góc nhìn cá nhân định hình sự hiểu biết của họ về thực tế.","audioKind":"ex2"}],"collocations":[{"en":"first-person narrator","vi":"người kể chuyện ở ngôi thứ nhất"},{"en":"unreliable narrator","vi":"người kể chuyện không đáng tin cậy"},{"en":"documentary narrator","vi":"người thuyết minh phim tài liệu"}],"wordFamily":["narrate (v.)","narration (n.)","narrative (n.)"],"synonyms":["storyteller"],"antonyms":[],"tipVi":"Người kể chuyện không nhất thiết phải là tác giả; trong tiểu thuyết, vai trò này có thể do một nhân vật hư cấu đảm nhiệm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_best-seller', 'en-b2-33', 'best-seller', '/ˌbest ˈselər/', 'B2', 'sách bán chạy; sản phẩm bán chạy', 'n.', 'best-selling (adj.)', NULL, 'Cũng thường được viết là bestseller; dạng tính từ là best-selling.', 'That cookbook became a best-seller within a month.', NULL, 'Cuốn sách nấu ăn đó đã trở thành sách bán chạy chỉ trong vòng một tháng.', '{"wordId":"best-seller","ukIpa":"/ˌbest ˈselə/","usIpa":"/ˌbest ˈselər/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"a book or product that sells in very large quantities","vi":"sách bán chạy; sản phẩm bán chạy"}],"examples":[{"en":"That cookbook became a best-seller within a month.","vi":"Cuốn sách nấu ăn đó đã trở thành sách bán chạy chỉ trong vòng một tháng.","audioKind":"ex"},{"en":"A best-seller can encourage wider public interest in scientific issues that previously attracted little attention.","vi":"Một cuốn sách bán chạy có thể khơi dậy sự quan tâm rộng rãi của công chúng đối với các vấn đề khoa học vốn trước đây ít nhận được sự chú ý.","audioKind":"ex2"}],"collocations":[{"en":"an international best-seller","vi":"sách bán chạy quốc tế"},{"en":"become a best-seller","vi":"trở thành sách bán chạy"},{"en":"a best-seller list","vi":"danh sách sách bán chạy"}],"wordFamily":["best-selling (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cũng thường được viết là bestseller; dạng tính từ là best-selling.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_artistic', 'en-b2-33', 'artistic', '/ɑːrˈtɪstɪk/', 'B2', 'thuộc về nghệ thuật; có khiếu nghệ thuật; tài hoa; mang tính nghệ thuật; có giá trị thẩm mỹ', 'adj.', 'art (n.), artist (n.), artistically (adv.)', NULL, 'artistic chỉ nghệ thuật hoặc năng khiếu nghệ thuật; artificial chỉ đồ nhân tạo.', 'The festival celebrates artistic traditions through music and dance.', NULL, 'Lễ hội tôn vinh các truyền thống nghệ thuật thông qua âm nhạc và khiêu vũ.', '{"wordId":"artistic","ukIpa":"/ɑːˈtɪstɪk/","usIpa":"/ɑːrˈtɪstɪk/","cefr":"B2","topic":"arts","senses":[{"pos":"adj.","en":"Related to art or the creation of art","vi":"thuộc về nghệ thuật"},{"pos":"adj.","en":"Good at creating or appreciating art","vi":"có khiếu nghệ thuật; tài hoa"},{"pos":"adj.","en":"Beautiful or attractive in a way that shows creative skill","vi":"mang tính nghệ thuật; có giá trị thẩm mỹ"}],"examples":[{"en":"The festival celebrates artistic traditions through music and dance.","vi":"Lễ hội tôn vinh các truyền thống nghệ thuật thông qua âm nhạc và khiêu vũ.","audioKind":"ex"},{"en":"Schools should provide opportunities for artistic expression, as creative activities can support emotional development and cultural understanding.","vi":"Các trường học nên tạo cơ hội cho sự thể hiện nghệ thuật, bởi các hoạt động sáng tạo có thể hỗ trợ sự phát triển cảm xúc và sự thấu hiểu văn hóa.","audioKind":"ex2"}],"collocations":[{"en":"artistic expression","vi":"sự biểu đạt nghệ thuật"},{"en":"artistic talent","vi":"tài năng nghệ thuật"},{"en":"artistic freedom","vi":"tự do nghệ thuật"},{"en":"artistic value","vi":"giá trị nghệ thuật"}],"wordFamily":["art (n.)","artist (n.)","artistically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"artistic chỉ nghệ thuật hoặc năng khiếu nghệ thuật; artificial chỉ đồ nhân tạo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gem', 'en-b2-33', 'gem', '/dʒem/', 'B2', 'đá quý; viên ngọc quý; vật báu; người tài năng', 'n.', 'gemstone (n.)', 'Đồng nghĩa: jewel', 'Hidden gem thường chỉ những địa điểm tuyệt vời hoặc sản phẩm chất lượng chưa được nhiều người biết đến.', 'The tiny blue gem sparkled in her silver ring.', NULL, 'Viên đá quý màu xanh nhỏ xíu lấp lánh trên chiếc nhẫn bạc của cô ấy.', '{"wordId":"gem","ukIpa":"/dʒem/","usIpa":"/dʒem/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"a valuable stone, often cut and polished for jewellery","vi":"đá quý"},{"pos":"n.","en":"a person or thing of exceptional quality or value","vi":"viên ngọc quý; vật báu; người tài năng"}],"examples":[{"en":"The tiny blue gem sparkled in her silver ring.","vi":"Viên đá quý màu xanh nhỏ xíu lấp lánh trên chiếc nhẫn bạc của cô ấy.","audioKind":"ex"},{"en":"Small regional museums often contain hidden gems that reveal important aspects of a community''s cultural history.","vi":"Các bảo tàng khu vực nhỏ thường chứa đựng những viên ngọc ẩn giấu hé lộ các khía cạnh quan trọng trong lịch sử văn hóa của cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"precious gem","vi":"đá quý"},{"en":"hidden gem","vi":"nơi chốn tuyệt vời ít người biết"},{"en":"a gem of a book","vi":"một cuốn sách tuyệt hay"}],"wordFamily":["gemstone (n.)"],"synonyms":["jewel"],"antonyms":[],"tipVi":"Hidden gem thường chỉ những địa điểm tuyệt vời hoặc sản phẩm chất lượng chưa được nhiều người biết đến.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ornament', 'en-b2-33', 'ornament', '/ˈɔːrnəmənt/', 'B2', 'đồ trang trí, vật trang hoàng; trang trí, tô điểm', 'n.', 'ornamental (adj.), ornamentation (n.)', 'Đồng nghĩa: decoration, adornment', 'Danh từ nhấn trọng âm ở âm tiết đầu; động từ có âm tiết cuối phát âm là /ment/.', 'A small glass ornament sparkled on the wooden shelf.', NULL, 'Một món đồ trang trí bằng thủy tinh nhỏ lấp lánh trên chiếc kệ gỗ.', '{"wordId":"ornament","ukIpa":"/ˈɔːnəmənt/","usIpa":"/ˈɔːrnəmənt/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"An object used to make something look more attractive.","vi":"đồ trang trí, vật trang hoàng"},{"pos":"v.","en":"To decorate something with attractive objects or details.","vi":"trang trí, tô điểm"}],"examples":[{"en":"A small glass ornament sparkled on the wooden shelf.","vi":"Một món đồ trang trí bằng thủy tinh nhỏ lấp lánh trên chiếc kệ gỗ.","audioKind":"ex"},{"en":"Traditional ornaments displayed in local museums can reveal how earlier communities expressed cultural identity through decorative objects.","vi":"Những món đồ trang trí truyền thống được trưng bày trong bảo tàng địa phương có thể cho thấy các cộng đồng thời trước đã thể hiện bản sắc văn hóa qua các vật phẩm trang trí như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"glass ornament","vi":"đồ trang trí bằng thủy tinh"},{"en":"decorative ornament","vi":"vật trang hoàng"},{"en":"ornament something with","vi":"trang trí cái gì bằng"}],"wordFamily":["ornamental (adj.)","ornamentation (n.)"],"synonyms":["decoration","adornment"],"antonyms":[],"tipVi":"Danh từ nhấn trọng âm ở âm tiết đầu; động từ có âm tiết cuối phát âm là /ment/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grace', 'en-b2-33', 'grace', '/ɡreɪs/', 'B2', 'vẻ duyên dáng; sự thanh lịch; sự uyển chuyển; thời gian gia hạn; sự khoan dung; làm cho sang trọng; tô điểm', 'n.', 'graceful (adj.), gracefully (adv.), gracious (adj.)', 'Đồng nghĩa: elegance, poise · Trái nghĩa: clumsiness', 'Danh từ grace chỉ sự duyên dáng thường là danh từ không đếm được; grace period chỉ thời gian gia hạn.', 'The dancer moved across the stage with effortless grace.', NULL, 'Nữ vũ công di chuyển uyển chuyển khắp sân khấu một cách đầy tự nhiên.', '{"wordId":"grace","ukIpa":"/ɡreɪs/","usIpa":"/ɡreɪs/","cefr":"B2","topic":"arts","senses":[{"pos":"n.","en":"smooth, attractive movement or behaviour","vi":"vẻ duyên dáng; sự thanh lịch; sự uyển chuyển"},{"pos":"n.","en":"extra time or kindness freely given","vi":"thời gian gia hạn; sự khoan dung"},{"pos":"v.","en":"make a place or occasion more attractive by being present","vi":"làm cho sang trọng; tô điểm"}],"examples":[{"en":"The dancer moved across the stage with effortless grace.","vi":"Nữ vũ công di chuyển uyển chuyển khắp sân khấu một cách đầy tự nhiên.","audioKind":"ex"},{"en":"A short grace period can help households manage unexpected delays in receiving their income.","vi":"Một khoảng thời gian gia hạn ngắn có thể giúp các hộ gia đình xử lý các khoản thu nhập bị chậm trễ bất ngờ.","audioKind":"ex2"}],"collocations":[{"en":"with grace","vi":"một cách duyên dáng"},{"en":"a grace period","vi":"thời gian gia hạn"},{"en":"grace the occasion","vi":"làm rạng rỡ sự kiện"}],"wordFamily":["graceful (adj.)","gracefully (adv.)","gracious (adj.)"],"synonyms":["elegance","poise"],"antonyms":["clumsiness"],"tipVi":"Danh từ grace chỉ sự duyên dáng thường là danh từ không đếm được; grace period chỉ thời gian gia hạn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_33_1', 'en-b2-33', 'Cách dùng “narrator” (n.) — người kể chuyện; người thuyết minh; giọng đọc thuyết minh', 'first-person narrator  ·  unreliable narrator  ·  documentary narrator', 'Người kể chuyện không nhất thiết phải là tác giả; trong tiểu thuyết, vai trò này có thể do một nhân vật hư cấu đảm nhiệm.', 'Họ từ (Word Family): narrate (v.), narration (n.), narrative (n.) | Đồng nghĩa: storyteller', '[{"hanzi":"The narrator''s gentle voice helped me fall asleep.","pinyin":"","meaning":"Giọng đọc thuyết minh nhẹ nhàng đã giúp tôi dễ dàng chìm vào giấc ngủ."},{"hanzi":"An unreliable narrator encourages readers to question events and consider how personal perspectives shape their understanding of reality.","pinyin":"","meaning":"Một người kể chuyện không đáng tin cậy khuyến khích độc giả đặt câu hỏi về các sự kiện và suy ngẫm về cách góc nhìn cá nhân định hình sự hiểu biết của họ về thực tế."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_33_2', 'en-b2-33', 'Cách dùng “legend” (n.) — truyền thuyết; sự tích', 'according to legend  ·  local legend  ·  a living legend', 'Từ legend có thể bắt nguồn từ nguyên mẫu lịch sử nhưng không đồng nghĩa với một sự thật lịch sử đã được kiểm chứng.', 'Họ từ (Word Family): legendary (adj.)', '[{"hanzi":"Grandma told us a legend about a sleeping dragon.","pinyin":"","meaning":"Bà đã kể cho chúng tôi nghe một truyền thuyết về một con rồng đang ngủ say."},{"hanzi":"Local legends can strengthen cultural identity while attracting visitors interested in the history of a region.","pinyin":"","meaning":"Những truyền thuyết địa phương vừa có thể củng cố bản sắc văn hóa vừa thu hút du khách quan tâm đến lịch sử của một vùng đất."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_33_3', 'en-b2-33', 'Cách dùng “exhibit” (v.) — trưng bày; triển lãm', 'exhibit artwork  ·  exhibit symptoms  ·  a museum exhibit', 'Trong tiếng Anh Anh, exhibit thường chỉ một món vật trưng bày đơn lẻ, còn exhibition dùng cho buổi triển lãm.', 'Họ từ (Word Family): exhibition (n.), exhibitor (n.) | Đồng nghĩa: display, show', '[{"hanzi":"The local gallery exhibits pottery made by young artists.","pinyin":"","meaning":"Phòng tranh địa phương trưng bày các tác phẩm gốm do các nghệ sĩ trẻ thực hiện."},{"hanzi":"Children who regularly engage in creative activities often exhibit greater confidence when solving unfamiliar problems.","pinyin":"","meaning":"Trẻ em thường xuyên tham gia vào các hoạt động sáng tạo thường thể hiện sự tự tin lớn hơn khi giải quyết các vấn đề chưa quen thuộc."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_33_4', 'en-b2-33', 'Cách dùng “magnificent” (adj.) — tráng lệ; nguy nga; hùng vĩ', 'magnificent scenery  ·  a magnificent building  ·  a magnificent achievement', 'Thường dùng để miêu tả phong cảnh, kiến trúc hoặc thành tựu, không dùng để chỉ phẩm chất đạo đức cao thượng.', 'Họ từ (Word Family): magnificence (n.), magnificently (adv.) | Đồng nghĩa: splendid, spectacular, superb', '[{"hanzi":"The balcony offers a magnificent view of snowy mountains.","pinyin":"","meaning":"Ban công mang đến một tầm nhìn tráng lệ ra những dãy núi tuyết."},{"hanzi":"Preserving magnificent historic buildings can strengthen local identity and attract visitors from other regions.","pinyin":"","meaning":"Việc bảo tồn các tòa nhà lịch sử nguy nga có thể củng cố bản sắc địa phương và thu hút du khách từ các vùng khác."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_33_1', 'en-b2-33', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
