INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_33_1_5', 'ten_b2_33_1', 'novelist', 'The novelist spends every morning writing at her kitchen table.', 'The novelist spends every morning writing at her kitchen table.', '/ˈnɑːvəlɪst/', 'Nữ tiểu thuyết gia dành mỗi buổi sáng để viết lách bên chiếc bàn trong bếp của cô ấy.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_33_1_6', 'ten_b2_33_1', 'graceful', 'The swan made a graceful turn across the pond.', 'The swan made a graceful turn across the pond.', '/ˈɡreɪsfəl/', 'Con thiên nga có cú uốn mình uyển chuyển bơi lội trên mặt hồ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_33_1_7', 'ten_b2_33_1', 'critic', 'The film critic praised the young actor''s performance.', 'The film critic praised the young actor''s performance.', '/ˈkrɪtɪk/', 'Nhà phê bình điện ảnh đã ca ngợi màn diễn xuất của nam diễn viên trẻ.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_33_1_8', 'ten_b2_33_1', 'magnificent', 'The balcony offers a magnificent view of snowy mountains.', 'The balcony offers a magnificent view of snowy mountains.', '/mæɡˈnɪfɪsənt/', 'Ban công mang đến một tầm nhìn tráng lệ ra những dãy núi tuyết.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_33_1_1', 'en-b2-33', 'ten_b2_33_1', 'listening', 'listening', 'Grandma told us a legend about a sleeping dragon.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Ban công mang đến một tầm nhìn tráng lệ ra những dãy núi tuyết.","Bà đã kể cho chúng tôi nghe một truyền thuyết về một con rồng đang ngủ say.","Giọng đọc thuyết minh nhẹ nhàng đã giúp tôi dễ dàng chìm vào giấc ngủ.","Nhà hàng nhỏ này phục vụ các món ăn chính gốc từ vùng miền đó."]'::jsonb, 1, 'Grandma told us a legend about a sleeping dragon. → Bà đã kể cho chúng tôi nghe một truyền thuyết về một con rồng đang ngủ say.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_33_1_2', 'en-b2-33', 'ten_b2_33_1', 'listening', 'listening', 'She threaded a blue bead onto the silver wire.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Sống trong một lâu đài là điều ảo tưởng thuở nhỏ tôi thích nhất.","Viên đá quý màu xanh nhỏ xíu lấp lánh trên chiếc nhẫn bạc của cô ấy.","Nữ vũ công di chuyển uyển chuyển khắp sân khấu một cách đầy tự nhiên.","Cô ấy xâu một hạt cườm màu xanh vào sợi dây bạc."]'::jsonb, 3, 'She threaded a blue bead onto the silver wire. → Cô ấy xâu một hạt cườm màu xanh vào sợi dây bạc.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_33_1_3', 'en-b2-33', 'ten_b2_33_1', 'listening', 'listening', 'This small restaurant serves authentic dishes from the region.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Viên đá quý màu xanh nhỏ xíu lấp lánh trên chiếc nhẫn bạc của cô ấy.","Cô tôi đã dạy tôi cách đan một chiếc giỏ nhỏ.","Nhà hàng nhỏ này phục vụ các món ăn chính gốc từ vùng miền đó.","Nữ chính của cuốn tiểu thuyết này chèo thuyền vượt đại dương."]'::jsonb, 2, 'This small restaurant serves authentic dishes from the region. → Nhà hàng nhỏ này phục vụ các món ăn chính gốc từ vùng miền đó.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_33_2', 'en-b2-33', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_33_2_1', 'ten_b2_33_2', 'legend', 'Local legends can strengthen cultural identity while attracting visitors interested in the history of a region.', 'Local legends can strengthen cultural identity while attracting visitors interested in the history of a region.', '/ˈledʒənd/', 'Những truyền thuyết địa phương vừa có thể củng cố bản sắc văn hóa vừa thu hút du khách quan tâm đến lịch sử của một vùng đất.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_33_2_2', 'ten_b2_33_2', 'bead', 'Traditional bead jewellery can provide income for local craftspeople while preserving skills passed down through generations.', 'Traditional bead jewellery can provide income for local craftspeople while preserving skills passed down through generations.', '/biːd/', 'Trang sức hạt cườm truyền thống vừa mang lại thu nhập cho thợ thủ công địa phương, vừa gìn giữ các kỹ năng được truyền qua nhiều thế hệ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_33_2_3', 'ten_b2_33_2', 'authentic', 'Museums should preserve authentic objects while using digital tools to make local history more accessible.', 'Museums should preserve authentic objects while using digital tools to make local history more accessible.', '/ɔːˈθentɪk/', 'Các bảo tàng nên bảo tồn các hiện vật nguyên bản đồng thời sử dụng các công cụ kỹ thuật số để lịch sử địa phương trở nên gần gũi hơn với công chúng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_33_2_4', 'ten_b2_33_2', 'acrobat', 'Training as an acrobat requires sustained physical discipline, making injury prevention an essential part of professional education.', 'Training as an acrobat requires sustained physical discipline, making injury prevention an essential part of professional education.', '/ˈækrəbæt/', 'Việc huấn luyện để trở thành một nghệ sĩ nhào lộn đòi hỏi kỷ luật thể chất bền bỉ, khiến việc phòng ngừa chấn thương trở thành một phần thiết yếu trong đào tạo chuyên nghiệp.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_33_2_5', 'ten_b2_33_2', 'novelist', 'A skilled novelist can reveal social inequalities through characters whose experiences differ greatly from those of readers.', 'A skilled novelist can reveal social inequalities through characters whose experiences differ greatly from those of readers.', '/ˈnɑːvəlɪst/', 'Một tiểu thuyết gia tài năng có thể vạch trần sự bất bình đẳng xã hội thông qua các nhân vật có trải nghiệm khác biệt lớn so với độc giả.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_33_2_6', 'ten_b2_33_2', 'graceful', 'The bridge combines graceful curves with practical engineering, creating an attractive landmark for the city.', 'The bridge combines graceful curves with practical engineering, creating an attractive landmark for the city.', '/ˈɡreɪsfəl/', 'Cây cầu kết hợp giữa các đường cong uyển chuyển và kỹ thuật xây dựng thực tế, tạo nên một thắng cảnh nổi bật cho thành phố.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_33_2_1', 'en-b2-33', 'ten_b2_33_2', 'listening', 'listening', 'Local legends can strengthen cultural identity while attracting visitors interested in the history of a region.', NULL, 'Trong câu vừa nghe, từ “legend” mang nghĩa nào sau đây?', '["chuyến đi bộ đường dài gian khổ","truyền thuyết; sự tích","quầy (thanh toán, phục vụ); mặt bàn (nhà bếp)","tương đối; so sánh ra"]'::jsonb, 1, '“legend” (/ˈledʒənd/): truyền thuyết; sự tích. Câu đầy đủ: Local legends can strengthen cultural identity while attracting visitors interested in the history of a region.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_33_2_2', 'en-b2-33', 'ten_b2_33_2', 'listening', 'listening', 'Traditional bead jewellery can provide income for local craftspeople while preserving skills passed down through generations.', NULL, 'Trong câu vừa nghe, từ “bead” mang nghĩa nào sau đây?', '["táo bạo; liều lĩnh","tính từ: chính; chủ yếu; quan trọng nhất","sự việc; sự cố","hạt cườm; hạt chuỗi"]'::jsonb, 3, '“bead” (/biːd/): hạt cườm; hạt chuỗi. Câu đầy đủ: Traditional bead jewellery can provide income for local craftspeople while preserving skills passed down through generations.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
