INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_33_2', 'en-b2-33', NULL, 'comprehensive_test', 'listening', 'She threaded a blue bead onto the silver wire.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nghệ sĩ nhào lộn đứng bằng một tay trên tấm thảm mềm.","Cô tôi đã dạy tôi cách đan một chiếc giỏ nhỏ.","Cô ấy xâu một hạt cườm màu xanh vào sợi dây bạc.","Sống trong một lâu đài là điều ảo tưởng thuở nhỏ tôi thích nhất."]'::jsonb, 2, 'She threaded a blue bead onto the silver wire. → Cô ấy xâu một hạt cườm màu xanh vào sợi dây bạc.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_33_3', 'en-b2-33', NULL, 'comprehensive_test', 'listening', 'authentic', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đàn clarinet; kèn clarinet","sự bùng nổ; sự phát triển nhanh chóng","chính gốc; đích thực; chuẩn vị","cơn khát"]'::jsonb, 2, 'authentic (/ɔːˈθentɪk/) → chính gốc; đích thực; chuẩn vị; chân thực; đáng tin cậy', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_33_4', 'en-b2-33', NULL, 'comprehensive_test', 'listening', 'The acrobat balanced on one hand above the soft mat.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Mọi người đều vỗ tay khi nữ vũ công trẻ hoàn thành bài biểu diễn của mình.","Nhà phê bình điện ảnh đã ca ngợi màn diễn xuất của nam diễn viên trẻ.","Phòng tranh địa phương trưng bày các tác phẩm gốm do các nghệ sĩ trẻ thực hiện.","Nghệ sĩ nhào lộn đứng bằng một tay trên tấm thảm mềm."]'::jsonb, 3, 'The acrobat balanced on one hand above the soft mat. → Nghệ sĩ nhào lộn đứng bằng một tay trên tấm thảm mềm.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_33_5', 'en-b2-33', NULL, 'comprehensive_test', 'listening', 'novelist', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tiểu thuyết gia; nhà văn viết tiểu thuyết","nắm vững; tinh thông","sự có mặt; sự hiện diện","từ chức; xin thôi việc"]'::jsonb, 0, 'novelist (/ˈnɑːvəlɪst/) → tiểu thuyết gia; nhà văn viết tiểu thuyết', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_33_6', 'en-b2-33', NULL, 'comprehensive_test', 'listening', 'The swan made a graceful turn across the pond.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nữ chính của cuốn tiểu thuyết này chèo thuyền vượt đại dương.","Con thiên nga có cú uốn mình uyển chuyển bơi lội trên mặt hồ.","Bọn trẻ nặn đất sét ướt thành những chiếc bát nhỏ.","Mọi người đều vỗ tay khi nữ vũ công trẻ hoàn thành bài biểu diễn của mình."]'::jsonb, 1, 'The swan made a graceful turn across the pond. → Con thiên nga có cú uốn mình uyển chuyển bơi lội trên mặt hồ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_33_7', 'en-b2-33', NULL, 'comprehensive_test', 'listening', 'critic', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nhà phê bình; nhà bình luận","theo chiều kim đồng hồ","sự tận tụy; tinh thần cống hiến","dệt; đan"]'::jsonb, 0, 'critic (/ˈkrɪtɪk/) → nhà phê bình; nhà bình luận; người chỉ trích; người phản đối', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_33_8', 'en-b2-33', NULL, 'comprehensive_test', 'listening', 'The balcony offers a magnificent view of snowy mountains.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sống trong một lâu đài là điều ảo tưởng thuở nhỏ tôi thích nhất.","Ban công mang đến một tầm nhìn tráng lệ ra những dãy núi tuyết.","Bà đã kể cho chúng tôi nghe một truyền thuyết về một con rồng đang ngủ say.","Cuốn sách nấu ăn đó đã trở thành sách bán chạy chỉ trong vòng một tháng."]'::jsonb, 1, 'The balcony offers a magnificent view of snowy mountains. → Ban công mang đến một tầm nhìn tráng lệ ra những dãy núi tuyết.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
