INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_33_18', 'en-b2-33', NULL, 'comprehensive_test', 'reading', NULL, 'Local legends can strengthen cultural identity while attracting visitors interested in the history of a region.', 'Dựa vào câu trên, từ “legend” có nghĩa phù hợp nhất là gì?', '["truyền thuyết; sự tích","sự vắng mặt; sự không có mặt","nhiều; đông đảo","làm mờ; trở nên mờ đi"]'::jsonb, 0, 'legend: truyền thuyết; sự tích; nhân vật huyền thoại; tượng đài; chú giải bản đồ; phần giải thích ký hiệu. Dịch cả câu: Những truyền thuyết địa phương vừa có thể củng cố bản sắc văn hóa vừa thu hút du khách quan tâm đến lịch sử của một vùng đất.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_33_19', 'en-b2-33', NULL, 'comprehensive_test', 'reading', NULL, 'Traditional bead jewellery can provide income for local craftspeople while preserving skills passed down through generations.', 'Dựa vào câu trên, từ “bead” có nghĩa phù hợp nhất là gì?', '["hạt cườm; hạt chuỗi","tương ứng, có liên quan trực tiếp với cái khác","thỉnh thoảng; đôi khi","bạn đồng hành; người bầu bạn; thú cưng bầu bạn"]'::jsonb, 0, 'bead: hạt cườm; hạt chuỗi; giọt (chất lỏng nhỏ, tròn). Dịch cả câu: Trang sức hạt cườm truyền thống vừa mang lại thu nhập cho thợ thủ công địa phương, vừa gìn giữ các kỹ năng được truyền qua nhiều thế hệ.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_33_20', 'en-b2-33', NULL, 'comprehensive_test', 'reading', NULL, 'Museums should preserve authentic objects while using digital tools to make local history more accessible.', 'Dựa vào câu trên, từ “authentic” có nghĩa phù hợp nhất là gì?', '["chính gốc; đích thực; chuẩn vị","bản thân; cái tôi","cầu phước; ban phúc","sợi"]'::jsonb, 0, 'authentic: chính gốc; đích thực; chuẩn vị; chân thực; đáng tin cậy. Dịch cả câu: Các bảo tàng nên bảo tồn các hiện vật nguyên bản đồng thời sử dụng các công cụ kỹ thuật số để lịch sử địa phương trở nên gần gũi hơn với công chúng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_33_21', 'en-b2-33', NULL, 'comprehensive_test', 'reading', NULL, 'Training as an acrobat requires sustained physical discipline, making injury prevention an essential part of professional education.', 'Dựa vào câu trên, từ “acrobat” có nghĩa phù hợp nhất là gì?', '["mục lục; danh mục sản phẩm","diễn viên xiêng; nghệ sĩ nhào lộn","học viện; trường chuyên đào tạo một môn hoặc kỹ năng cụ thể","cuộc mít tinh; cuộc biểu tình"]'::jsonb, 1, 'acrobat: diễn viên xiêng; nghệ sĩ nhào lộn. Dịch cả câu: Việc huấn luyện để trở thành một nghệ sĩ nhào lộn đòi hỏi kỷ luật thể chất bền bỉ, khiến việc phòng ngừa chấn thương trở thành một phần thiết yếu trong đào tạo chuyên nghiệp.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
