INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_33_23', 'en-b2-33', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đồ trang trí, vật trang hoàng”', '["fame","ornament","grip","interface"]'::jsonb, 1, 'đồ trang trí, vật trang hoàng → ornament (/ˈɔːrnəmənt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_33_24', 'en-b2-33', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “vẻ duyên dáng; sự thanh lịch; sự uyển chuyển”', '["sympathize","appreciation","faculty","grace"]'::jsonb, 3, 'vẻ duyên dáng; sự thanh lịch; sự uyển chuyển → grace (/ɡreɪs/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-34', 'en', 'Bài 34: Tư duy & Nhận thức (1) - CEFR B2', 'CEFR B2', 'B2 · Tư duy', '28 từ vựng Tiếng Anh CEFR B2 chủ đề tư duy & nhận thức kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4034, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_philosophy', 'en-b2-34', 'philosophy', '/fɪˈlɑːsəfi/', 'B2', 'triết học (nghiên cứu về tri thức, sự tồn tại, thực tại và giá trị đạo đức); triết lý sống; hệ tư tưởng (tập hợp niềm tin định hướng hành động và quyết định)', 'n.', 'philosopher (n.), philosophical (adj.), philosophically (adv.)', NULL, 'Chỉ môn học thì thường không đếm được; chỉ một tập hợp tư tưởng cụ thể thì dùng a philosophy.', 'My sister studies philosophy and enjoys discussing difficult questions.', NULL, 'Chị tôi học chuyên ngành triết học và rất thích thảo luận về những câu hỏi hóc búa.', '{"wordId":"philosophy","ukIpa":"/fɪˈlɒsəfi/","usIpa":"/fɪˈlɑːsəfi/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"The study of knowledge, existence, reality, and moral values","vi":"triết học (nghiên cứu về tri thức, sự tồn tại, thực tại và giá trị đạo đức)"},{"pos":"n.","en":"A set of beliefs that guides actions and decisions","vi":"triết lý sống; hệ tư tưởng (tập hợp niềm tin định hướng hành động và quyết định)"}],"examples":[{"en":"My sister studies philosophy and enjoys discussing difficult questions.","vi":"Chị tôi học chuyên ngành triết học và rất thích thảo luận về những câu hỏi hóc búa.","audioKind":"ex"},{"en":"Studying philosophy can help students question assumptions and develop stronger arguments about complex ethical issues.","vi":"Việc học triết học có thể giúp sinh viên chất vấn các giả định có sẵn và đưa ra những lập luận sắc bén hơn về các vấn đề đạo đức phức tạp.","audioKind":"ex2"}],"collocations":[{"en":"study philosophy","vi":"nghiên cứu triết học"},{"en":"moral philosophy","vi":"đạo đức học"},{"en":"personal philosophy","vi":"triết lý sống cá nhân"},{"en":"philosophy of education","vi":"triết học giáo dục"}],"wordFamily":["philosopher (n.)","philosophical (adj.)","philosophically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ môn học thì thường không đếm được; chỉ một tập hợp tư tưởng cụ thể thì dùng a philosophy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_consistency', 'en-b2-34', 'consistency', '/kənˈsɪstənsi/', 'B2', 'tính nhất quán; độ ổn định; độ đặc; độ sánh; độ mịn', 'n.', 'consistent (adj.), consistently (adv.), inconsistent (adj.), inconsistency (n.)', 'Đồng nghĩa: uniformity · Trái nghĩa: inconsistency', 'Khi nói đến tính nhất quán trong lĩnh vực nào đó, dùng consistency in.', 'Our coach values consistency more than occasional brilliant performances.', NULL, 'Huấn luyện viên của chúng tôi coi trọng sự ổn định hơn những màn trình diễn xuất thần thỉnh thoảng.', '{"wordId":"consistency","ukIpa":"/kənˈsɪstənsi/","usIpa":"/kənˈsɪstənsi/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"The quality of staying similar in behaviour, standards, or results.","vi":"tính nhất quán; độ ổn định"},{"pos":"n.","en":"How thick, firm, or smooth a substance is.","vi":"độ đặc; độ sánh; độ mịn"}],"examples":[{"en":"Our coach values consistency more than occasional brilliant performances.","vi":"Huấn luyện viên của chúng tôi coi trọng sự ổn định hơn những màn trình diễn xuất thần thỉnh thoảng.","audioKind":"ex"},{"en":"Greater consistency in marking standards would help ensure that students receive fair results across different examination centres.","vi":"Tính nhất quán cao hơn trong các tiêu chuẩn chấm điểm sẽ giúp đảm bảo học sinh nhận được kết quả công bằng ở các trung tâm thi khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"consistency in quality","vi":"tính ổn định về chất lượng"},{"en":"maintain consistency","vi":"duy trì tính nhất quán"},{"en":"a smooth consistency","vi":"độ mịn màng đồng nhất"}],"wordFamily":["consistent (adj.)","consistently (adv.)","inconsistent (adj.)","inconsistency (n.)"],"synonyms":["uniformity"],"antonyms":["inconsistency"],"tipVi":"Khi nói đến tính nhất quán trong lĩnh vực nào đó, dùng consistency in.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_principle', 'en-b2-34', 'principle', '/ˈprɪnsəpəl/', 'B2', 'nguyên tắc; phương châm sống; nguyên lý; định luật cơ bản', 'n.', 'principled (adj.), unprincipled (adj.)', 'Đồng nghĩa: rule, standard, doctrine', 'Tránh nhầm lẫn với principal: từ đó có thể mang nghĩa "chính" hoặc "hiệu trưởng".', 'I refused the extra money as a matter of principle.', NULL, 'Tôi đã từ chối số tiền thừa ra vì vấn đề nguyên tắc.', '{"wordId":"principle","ukIpa":"/ˈprɪnsəpəl/","usIpa":"/ˈprɪnsəpəl/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"A belief or rule that guides decisions and behaviour.","vi":"nguyên tắc; phương châm sống"},{"pos":"n.","en":"A basic truth explaining how something works.","vi":"nguyên lý; định luật cơ bản"}],"examples":[{"en":"I refused the extra money as a matter of principle.","vi":"Tôi đã từ chối số tiền thừa ra vì vấn đề nguyên tắc.","audioKind":"ex"},{"en":"The principle of equal opportunity should guide policies designed to improve access to higher education.","vi":"Nguyên tắc cơ hội bình đẳng nên định hướng cho các chính sách nhằm cải thiện khả năng tiếp cận giáo dục đại học.","audioKind":"ex2"}],"collocations":[{"en":"basic principle","vi":"nguyên tắc cơ bản"},{"en":"in principle","vi":"về nguyên tắc; trên lý thuyết"},{"en":"on principle","vi":"vì nguyên tắc"},{"en":"guiding principle","vi":"nguyên tắc chỉ đạo"}],"wordFamily":["principled (adj.)","unprincipled (adj.)"],"synonyms":["rule","standard","doctrine"],"antonyms":[],"tipVi":"Tránh nhầm lẫn với principal: từ đó có thể mang nghĩa \"chính\" hoặc \"hiệu trưởng\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_extent', 'en-b2-34', 'extent', '/ɪkˈstent/', 'B2', 'mức độ; phạm vi', 'n.', 'extend (v.), extension (n.), extensive (adj.), extensively (adv.)', NULL, 'Diễn đạt "ở mức độ nào đó" dùng to some extent.', 'We only discovered the extent of the leak yesterday.', NULL, 'Chúng tôi mới chỉ phát hiện ra mức độ nghiêm trọng của vụ rò rỉ vào ngày hôm qua.', '{"wordId":"extent","ukIpa":"/ɪkˈstent/","usIpa":"/ɪkˈstent/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"How much something happens or how far it reaches.","vi":"mức độ; phạm vi"}],"examples":[{"en":"We only discovered the extent of the leak yesterday.","vi":"Chúng tôi mới chỉ phát hiện ra mức độ nghiêm trọng của vụ rò rỉ vào ngày hôm qua.","audioKind":"ex"},{"en":"The extent to which public transport reduces pollution depends on passenger numbers and energy sources.","vi":"Mức độ mà giao thông công cộng làm giảm ô nhiễm phụ thuộc vào số lượng hành khách và nguồn năng lượng.","audioKind":"ex2"}],"collocations":[{"en":"to some extent","vi":"ở mức độ nào đó"},{"en":"the full extent of","vi":"toàn bộ mức độ của"},{"en":"to a large extent","vi":"phần lớn; ở mức độ lớn"}],"wordFamily":["extend (v.)","extension (n.)","extensive (adj.)","extensively (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Diễn đạt \"ở mức độ nào đó\" dùng to some extent.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_derive', 'en-b2-34', 'derive', '/dɪˈraɪv/', 'B2', 'thu được; tìm thấy; nhận được; bắt nguồn từ; chuyển hóa từ', 'v.', 'derivation (n.), derivative (n.)', 'Đồng nghĩa: obtain, gain', 'Cấu trúc derive A from B nghĩa là lấy A từ B; còn derive from nghĩa là có nguồn gốc từ.', 'I derive great pleasure from growing vegetables on my balcony.', NULL, 'Tôi tìm thấy niềm vui lớn từ việc trồng rau trên ban công nhà mình.', '{"wordId":"derive","ukIpa":"/dɪˈraɪv/","usIpa":"/dɪˈraɪv/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"to obtain something from a particular source","vi":"thu được; tìm thấy; nhận được"},{"pos":"v.","en":"to come or develop from something else","vi":"bắt nguồn từ; chuyển hóa từ"}],"examples":[{"en":"I derive great pleasure from growing vegetables on my balcony.","vi":"Tôi tìm thấy niềm vui lớn từ việc trồng rau trên ban công nhà mình.","audioKind":"ex"},{"en":"Many coastal communities derive a significant proportion of their income from tourism and fishing.","vi":"Nhiều cộng đồng ven biển có phần lớn thu nhập xuất phát từ hoạt động du lịch và đánh bắt hải sản.","audioKind":"ex2"}],"collocations":[{"en":"derive pleasure from","vi":"thu được niềm vui từ"},{"en":"derive income from","vi":"kiếm thu nhập từ"},{"en":"derive from","vi":"bắt nguồn từ"},{"en":"be derived from","vi":"được bắt nguồn từ; được suy ra từ"}],"wordFamily":["derivation (n.)","derivative (n.)"],"synonyms":["obtain","gain"],"antonyms":[],"tipVi":"Cấu trúc derive A from B nghĩa là lấy A từ B; còn derive from nghĩa là có nguồn gốc từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_emerge', 'en-b2-34', 'emerge', '/ɪˈmɝːdʒ/', 'B2', 'hiện ra; xuất hiện; nổi lên; hình thành; phát triển; nổi bật; vươn lên', 'v.', 'emergence (n.), emerging (adj.), emergent (adj.)', 'Đồng nghĩa: appear, surface · Trái nghĩa: disappear', 'Đây là nội động từ; thường đi với emerge from hoặc emerge as.', 'A small rabbit emerged from beneath the garden shed.', NULL, 'Một chú thỏ nhỏ chui ra từ bên dưới túp lều trong vườn.', '{"wordId":"emerge","ukIpa":"/ɪˈmɜːdʒ/","usIpa":"/ɪˈmɝːdʒ/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"To become visible or known after being hidden.","vi":"hiện ra; xuất hiện; nổi lên"},{"pos":"v.","en":"To develop or become important and noticeable.","vi":"hình thành; phát triển; nổi bật; vươn lên"}],"examples":[{"en":"A small rabbit emerged from beneath the garden shed.","vi":"Một chú thỏ nhỏ chui ra từ bên dưới túp lều trong vườn.","audioKind":"ex"},{"en":"New employment opportunities may emerge as governments invest more heavily in renewable energy infrastructure.","vi":"Cơ hội việc làm mới có thể xuất hiện khi các chính phủ đầu tư mạnh mẽ hơn vào cơ sở hạ tầng năng lượng tái tạo.","audioKind":"ex2"}],"collocations":[{"en":"emerge from","vi":"nổi lên từ"},{"en":"emerge as a leader","vi":"vươn lên thành nhà lãnh đạo"},{"en":"evidence emerges","vi":"bằng chứng xuất hiện"}],"wordFamily":["emergence (n.)","emerging (adj.)","emergent (adj.)"],"synonyms":["appear","surface"],"antonyms":["disappear"],"tipVi":"Đây là nội động từ; thường đi với emerge from hoặc emerge as.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sufficient', 'en-b2-34', 'sufficient', '/səˈfɪʃənt/', 'B2', 'đủ; đầy đủ', 'adj.', 'suffice (v.), sufficiently (adv.), insufficient (adj.), sufficiency (n.)', 'Đồng nghĩa: enough, adequate · Trái nghĩa: insufficient, inadequate', 'Thường dùng cấu trúc "sufficient for" hoặc "sufficient to do", mang sắc thái trang trọng.', 'We have sufficient food for everyone at the picnic.', NULL, 'Chúng tôi có đủ thức ăn cho tất cả mọi người tham gia buổi dã ngoại.', '{"wordId":"sufficient","ukIpa":"/səˈfɪʃənt/","usIpa":"/səˈfɪʃənt/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"enough to meet a need or achieve a purpose","vi":"đủ; đầy đủ"}],"examples":[{"en":"We have sufficient food for everyone at the picnic.","vi":"Chúng tôi có đủ thức ăn cho tất cả mọi người tham gia buổi dã ngoại.","audioKind":"ex"},{"en":"Without sufficient funding, local authorities may struggle to maintain essential services for their growing populations.","vi":"Nếu không có đủ nguồn tài trợ, chính quyền địa phương có thể gặp khó khăn trong việc duy trì các dịch vụ thiết yếu cho dân số đang ngày càng tăng.","audioKind":"ex2"}],"collocations":[{"en":"sufficient evidence","vi":"bằng chứng đầy đủ"},{"en":"sufficient funds","vi":"nguồn vốn dồi dào"},{"en":"sufficient time","vi":"đủ thời gian"},{"en":"sufficient for","vi":"đủ cho"}],"wordFamily":["suffice (v.)","sufficiently (adv.)","insufficient (adj.)","sufficiency (n.)"],"synonyms":["enough","adequate"],"antonyms":["insufficient","inadequate"],"tipVi":"Thường dùng cấu trúc \"sufficient for\" hoặc \"sufficient to do\", mang sắc thái trang trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ineffective', 'en-b2-34', 'ineffective', '/ˌɪnɪˈfektɪv/', 'B2', 'không hiệu quả; không có tác dụng', 'adj.', 'effective (adj.), ineffectively (adv.), ineffectiveness (n.)', 'Đồng nghĩa: unsuccessful, ineffectual · Trái nghĩa: effective', 'ineffective chỉ việc không có kết quả; inefficient chỉ hiệu suất thấp.', 'This tiny fan is ineffective in such a large room.', NULL, 'Chiếc quạt nhỏ xíu này chẳng có tác dụng gì trong căn phòng rộng lớn như vậy.', '{"wordId":"ineffective","ukIpa":"/ˌɪnɪˈfektɪv/","usIpa":"/ˌɪnɪˈfektɪv/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"not producing the result that is wanted","vi":"không hiệu quả; không có tác dụng"}],"examples":[{"en":"This tiny fan is ineffective in such a large room.","vi":"Chiếc quạt nhỏ xíu này chẳng có tác dụng gì trong căn phòng rộng lớn như vậy.","audioKind":"ex"},{"en":"Awareness campaigns may be ineffective unless governments also provide affordable alternatives to environmentally harmful products.","vi":"Các chiến dịch nâng cao nhận thức có thể không mang lại hiệu quả trừ khi chính phủ đồng thời cung cấp các giải pháp thay thế có giá cả phải chăng cho các sản phẩm gây hại môi trường.","audioKind":"ex2"}],"collocations":[{"en":"ineffective treatment","vi":"phương pháp điều trị không hiệu quả"},{"en":"ineffective policy","vi":"chính sách không hiệu quả"},{"en":"prove ineffective","vi":"chứng tỏ không hiệu quả"}],"wordFamily":["effective (adj.)","ineffectively (adv.)","ineffectiveness (n.)"],"synonyms":["unsuccessful","ineffectual"],"antonyms":["effective"],"tipVi":"ineffective chỉ việc không có kết quả; inefficient chỉ hiệu suất thấp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_naive', 'en-b2-34', 'naive', '/naɪˈiːv/', 'B2', 'ngây thơ; khờ dại; dễ tin người', 'adj.', 'naively (adv.), naivety (n.)', 'Đồng nghĩa: inexperienced, gullible · Trái nghĩa: sophisticated, worldly', 'Thường hàm ý thiếu kinh nghiệm, dễ tin người, không phải là nghĩa hoàn toàn tích cực.', 'I was naive to believe the repair would cost nothing.', NULL, 'Tôi thật ngây thơ khi tin rằng việc sửa chữa sẽ không tốn chút phí nào.', '{"wordId":"naive","ukIpa":"/naɪˈiːv/","usIpa":"/naɪˈiːv/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Too willing to trust because of limited experience.","vi":"ngây thơ; khờ dại; dễ tin người"}],"examples":[{"en":"I was naive to believe the repair would cost nothing.","vi":"Tôi thật ngây thơ khi tin rằng việc sửa chữa sẽ không tốn chút phí nào.","audioKind":"ex"},{"en":"It would be naive to assume that economic growth alone can solve every social problem.","vi":"Thật ngây thơ khi cho rằng chỉ riêng tăng trưởng kinh tế có thể giải quyết mọi vấn đề xã hội.","audioKind":"ex2"}],"collocations":[{"en":"naive assumption","vi":"giả định ngây thơ"},{"en":"naive optimism","vi":"sự lạc quan tếu"},{"en":"politically naive","vi":"non kém về chính trị"}],"wordFamily":["naively (adv.)","naivety (n.)"],"synonyms":["inexperienced","gullible"],"antonyms":["sophisticated","worldly"],"tipVi":"Thường hàm ý thiếu kinh nghiệm, dễ tin người, không phải là nghĩa hoàn toàn tích cực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_outlook', 'en-b2-34', 'outlook', '/ˈaʊtlʊk/', 'B2', 'cái nhìn; thái độ sống; quan điểm; viễn cảnh; triển vọng; cảnh quan; tầm nhìn', 'n.', NULL, 'Đồng nghĩa: perspective, prospects', 'Thái độ thường đi với on; triển vọng thường đi với for, ví dụ outlook for growth.', 'Despite recent difficulties, Lina maintains a cheerful outlook.', NULL, 'Bất chấp những khó khăn gần đây, Lina vẫn duy trì một thái độ sống tích cực.', '{"wordId":"outlook","ukIpa":"/ˈaʊtlʊk/","usIpa":"/ˈaʊtlʊk/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"a person''s general attitude towards life or a situation","vi":"cái nhìn; thái độ sống; quan điểm"},{"pos":"n.","en":"the likely future situation","vi":"viễn cảnh; triển vọng"},{"pos":"n.","en":"the view from a particular place","vi":"cảnh quan; tầm nhìn"}],"examples":[{"en":"Despite recent difficulties, Lina maintains a cheerful outlook.","vi":"Bất chấp những khó khăn gần đây, Lina vẫn duy trì một thái độ sống tích cực.","audioKind":"ex"},{"en":"Studying abroad can broaden students'' outlook by exposing them to unfamiliar customs and different ways of thinking.","vi":"Việc du học có thể mở rộng tầm nhìn của học sinh bằng cách cho các em tiếp xúc với những phong tục lạ và các phương thức tư duy khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"outlook on life","vi":"nhân sinh quan"},{"en":"positive outlook","vi":"thái độ tích cực"},{"en":"economic outlook","vi":"triển vọng kinh tế"},{"en":"broaden your outlook","vi":"mở rộng tầm nhìn của bạn"}],"wordFamily":[],"synonyms":["perspective","prospects"],"antonyms":[],"tipVi":"Thái độ thường đi với on; triển vọng thường đi với for, ví dụ outlook for growth.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_indication', 'en-b2-34', 'indication', '/ˌɪndɪˈkeɪʃən/', 'B2', 'dấu hiệu, biểu hiện, sự ám chỉ', 'n.', 'indicate (v.), indicative (adj.), indicator (n.)', 'Đồng nghĩa: sign, signal', 'Thường dùng indication of sth hoặc indication that theo sau là mệnh đề.', 'Those dark clouds are an indication of approaching rain.', NULL, 'Những đám mây đen đó là dấu hiệu sắp có mưa.', '{"wordId":"indication","ukIpa":"/ˌɪndɪˈkeɪʃən/","usIpa":"/ˌɪndɪˈkeɪʃən/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"a sign suggesting that something exists or may happen","vi":"dấu hiệu, biểu hiện, sự ám chỉ"}],"examples":[{"en":"Those dark clouds are an indication of approaching rain.","vi":"Những đám mây đen đó là dấu hiệu sắp có mưa.","audioKind":"ex"},{"en":"Rising demand for public transport provides an indication that urban travel habits are changing.","vi":"Nhu cầu đi lại bằng phương tiện công cộng tăng cao cho thấy thói quen di chuyển trong đô thị đang thay đổi.","audioKind":"ex2"}],"collocations":[{"en":"a clear indication","vi":"một dấu hiệu rõ ràng"},{"en":"give an indication of","vi":"cho thấy dấu hiệu của..."},{"en":"little indication","vi":"hầu như không có dấu hiệu"}],"wordFamily":["indicate (v.)","indicative (adj.)","indicator (n.)"],"synonyms":["sign","signal"],"antonyms":[],"tipVi":"Thường dùng indication of sth hoặc indication that theo sau là mệnh đề.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_positively', 'en-b2-34', 'positively', '/ˈpɑːzətɪvli/', 'B2', 'tích cực; theo chiều hướng tốt; đầy lạc quan; chắc chắn; quả quyết; rành rọt; thật sự; hoàn toàn; đích thực', 'adv.', 'positive (adj.), positivity (n.)', 'Trái nghĩa: negatively', 'positively có thể dùng để nhấn mạnh sắc thái biểu cảm, hoặc diễn tả thái độ tích cực cũng như sự chắc chắn.', 'My sister reacted positively when I suggested a picnic.', NULL, 'Chị tôi đã phản ứng rất tích cực khi tôi đưa ra ý định đi dã ngoại.', '{"wordId":"positively","ukIpa":"/ˈpɒzətɪvli/","usIpa":"/ˈpɑːzətɪvli/","cefr":"B2","topic":"thinking","senses":[{"pos":"adv.","en":"In a way that shows approval, confidence, or optimism.","vi":"tích cực; theo chiều hướng tốt; đầy lạc quan"},{"pos":"adv.","en":"With certainty and no doubt.","vi":"chắc chắn; quả quyết; rành rọt"},{"pos":"adv.","en":"Used to strongly emphasise a description.","vi":"thật sự; hoàn toàn; đích thực"}],"examples":[{"en":"My sister reacted positively when I suggested a picnic.","vi":"Chị tôi đã phản ứng rất tích cực khi tôi đưa ra ý định đi dã ngoại.","audioKind":"ex"},{"en":"Students often respond positively to detailed feedback that recognises their progress and offers practical guidance.","vi":"Học sinh thường phản hồi tích cực đối với những lời nhận xét chi tiết vừa công nhận sự tiến bộ vừa đưa ra định hướng thực tế cho các em.","audioKind":"ex2"}],"collocations":[{"en":"respond positively","vi":"phản hồi tích cực"},{"en":"positively identify","vi":"xác định chính xác"},{"en":"positively influence","vi":"tác động tích cực"},{"en":"positively delighted","vi":"thật sự vui mừng khôn tả"}],"wordFamily":["positive (adj.)","positivity (n.)"],"synonyms":[],"antonyms":["negatively"],"tipVi":"positively có thể dùng để nhấn mạnh sắc thái biểu cảm, hoặc diễn tả thái độ tích cực cũng như sự chắc chắn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_evidence', 'en-b2-34', 'evidence', '/ˈevɪdəns/', 'B2', 'bằng chứng; chứng cứ; dấu hiệu; chứng tỏ; biểu thị', 'n.', 'evident (adj.), evidently (adv.)', NULL, 'Làm danh từ thường không đếm được: một bằng chứng dùng a piece of evidence.', 'The muddy footprints were evidence that someone had entered.', NULL, 'Những vết chân dính bùn là bằng chứng cho thấy có ai đó đã đi vào.', '{"wordId":"evidence","ukIpa":"/ˈevɪdəns/","usIpa":"/ˈevɪdəns/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"Facts or signs that help establish whether something is true.","vi":"bằng chứng; chứng cứ; dấu hiệu"},{"pos":"v.","en":"To show clearly that something exists or is true.","vi":"chứng tỏ; biểu thị"}],"examples":[{"en":"The muddy footprints were evidence that someone had entered.","vi":"Những vết chân dính bùn là bằng chứng cho thấy có ai đó đã đi vào.","audioKind":"ex"},{"en":"Governments should consider scientific evidence before introducing policies intended to improve public health outcomes.","vi":"Chính phủ nên cân nhắc các bằng chứng khoa học trước khi ban hành các chính sách nhằm cải thiện kết quả sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"strong evidence","vi":"bằng chứng xác thực"},{"en":"scientific evidence","vi":"bằng chứng khoa học"},{"en":"evidence of","vi":"bằng chứng về"},{"en":"provide evidence","vi":"cung cấp bằng chứng"}],"wordFamily":["evident (adj.)","evidently (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Làm danh từ thường không đếm được: một bằng chứng dùng a piece of evidence.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_approach', 'en-b2-34', 'approach', '/əˈproʊtʃ/', 'B2', 'phương pháp; cách tiếp cận; tiến lại gần; đến gần; bắt tay vào xử lý; tiếp cận (ai đó)', 'n.', 'approachable (adj.), unapproachable (adj.)', 'Đồng nghĩa: method, tackle, near', 'Khi là danh từ mang nghĩa "phương pháp", dùng "to" + danh từ hoặc danh động từ (V-ing); khi là động từ, tân ngữ đi trực tiếp ngay sau.', 'We tried a different approach to training our puppy.', NULL, 'Chúng tôi đã thử một cách tiếp cận khác để huấn luyện chú chó con của mình.', '{"wordId":"approach","ukIpa":"/əˈprəʊtʃ/","usIpa":"/əˈproʊtʃ/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"A way of dealing with a task or problem.","vi":"phương pháp; cách tiếp cận"},{"pos":"v.","en":"To move nearer to someone or something.","vi":"tiến lại gần; đến gần"},{"pos":"v.","en":"To begin dealing with something or contact someone about it.","vi":"bắt tay vào xử lý; tiếp cận (ai đó)"}],"examples":[{"en":"We tried a different approach to training our puppy.","vi":"Chúng tôi đã thử một cách tiếp cận khác để huấn luyện chú chó con của mình.","audioKind":"ex"},{"en":"A balanced approach to urban planning should consider both economic growth and the protection of green spaces.","vi":"Một phương pháp quy hoạch đô thị cân bằng cần xem xét cả tăng trưởng kinh tế và việc bảo vệ không gian xanh.","audioKind":"ex2"}],"collocations":[{"en":"an approach to learning","vi":"phương pháp học tập"},{"en":"adopt an approach","vi":"áp dụng một phương pháp"},{"en":"approach a problem","vi":"giải quyết một vấn đề"},{"en":"approach someone for advice","vi":"tìm đến ai đó để xin lời khuyên"}],"wordFamily":["approachable (adj.)","unapproachable (adj.)"],"synonyms":["method","tackle","near"],"antonyms":[],"tipVi":"Khi là danh từ mang nghĩa \"phương pháp\", dùng \"to\" + danh từ hoặc danh động từ (V-ing); khi là động từ, tân ngữ đi trực tiếp ngay sau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_angle', 'en-b2-34', 'angle', '/ˈæŋɡəl/', 'B2', 'góc; góc độ; góc nhìn; khía cạnh; đặt nghiêng; làm nghiêng', 'n.', 'angled (adj.), angular (adj.)', 'Đồng nghĩa: perspective, slant', '"angle" là góc độ; "angel" mới là thiên thần, hãy chú ý thứ tự chữ cái.', 'Adjust the angle of your screen to reduce glare.', NULL, 'Hãy điều chỉnh góc màn hình để giảm độ chói.', '{"wordId":"angle","ukIpa":"/ˈæŋɡəl/","usIpa":"/ˈæŋɡəl/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"The space between two lines or surfaces that meet.","vi":"góc; góc độ"},{"pos":"n.","en":"A particular way of considering or presenting something.","vi":"góc nhìn; khía cạnh"},{"pos":"v.","en":"To position something so that it slopes or faces sideways.","vi":"đặt nghiêng; làm nghiêng"}],"examples":[{"en":"Adjust the angle of your screen to reduce glare.","vi":"Hãy điều chỉnh góc màn hình để giảm độ chói.","audioKind":"ex"},{"en":"Examining housing shortages from an economic angle can reveal how planning restrictions influence property prices.","vi":"Việc xem xét tình trạng thiếu nhà ở từ góc độ kinh tế có thể cho thấy các hạn chế về quy hoạch ảnh hưởng đến giá bất động sản như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"a right angle","vi":"góc vuông"},{"en":"at an angle","vi":"ở một góc nghiêng"},{"en":"from a different angle","vi":"từ một góc nhìn khác"},{"en":"a viewing angle","vi":"góc nhìn"}],"wordFamily":["angled (adj.)","angular (adj.)"],"synonyms":["perspective","slant"],"antonyms":[],"tipVi":"\"angle\" là góc độ; \"angel\" mới là thiên thần, hãy chú ý thứ tự chữ cái.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_persuasive', 'en-b2-34', 'persuasive', '/pɚˈsweɪsɪv/', 'B2', 'có sức thuyết phục', 'adj.', 'persuade (v.), persuasion (n.), persuasively (adv.)', 'Đồng nghĩa: convincing · Trái nghĩa: unconvincing', 'Thường dùng để mô tả lập luận hoặc cách diễn đạt có sức thuyết phục, không dùng làm danh từ.', 'Her persuasive explanation finally convinced me to join the club.', NULL, 'Lời giải thích đầy sức thuyết phục của cô ấy cuối cùng đã thuyết phục tôi tham gia câu lạc bộ.', '{"wordId":"persuasive","ukIpa":"/pəˈsweɪsɪv/","usIpa":"/pɚˈsweɪsɪv/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Able to make people believe something or agree with you","vi":"có sức thuyết phục"}],"examples":[{"en":"Her persuasive explanation finally convinced me to join the club.","vi":"Lời giải thích đầy sức thuyết phục của cô ấy cuối cùng đã thuyết phục tôi tham gia câu lạc bộ.","audioKind":"ex"},{"en":"Public health campaigns need persuasive messages that encourage people to adopt healthier daily habits.","vi":"Các chiến dịch y tế công cộng cần những thông điệp có sức thuyết phục để khuyến khích mọi người áp dụng thói quen sinh hoạt lành mạnh hơn.","audioKind":"ex2"}],"collocations":[{"en":"persuasive argument","vi":"lập luận có sức thuyết phục"},{"en":"persuasive evidence","vi":"bằng chứng có sức thuyết phục"},{"en":"persuasive speaker","vi":"diễn giả có tài thuyết phục"}],"wordFamily":["persuade (v.)","persuasion (n.)","persuasively (adv.)"],"synonyms":["convincing"],"antonyms":["unconvincing"],"tipVi":"Thường dùng để mô tả lập luận hoặc cách diễn đạt có sức thuyết phục, không dùng làm danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pointless', 'en-b2-34', 'pointless', '/ˈpɔɪntləs/', 'B2', 'vô nghĩa; vô ích; không có mục đích', 'adj.', 'point (n.), pointlessly (adv.), pointlessness (n.)', 'Đồng nghĩa: futile, useless · Trái nghĩa: worthwhile, meaningful', 'Thường dùng cấu trúc "it is pointless to do" để diễn đạt việc làm gì đó là vô ích.', 'It is pointless to water plants during heavy rain.', NULL, 'Tưới cây khi trời đang mưa to là việc làm vô ích.', '{"wordId":"pointless","ukIpa":"/ˈpɔɪntləs/","usIpa":"/ˈpɔɪntləs/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Having no useful purpose or chance of achieving anything.","vi":"vô nghĩa; vô ích; không có mục đích"}],"examples":[{"en":"It is pointless to water plants during heavy rain.","vi":"Tưới cây khi trời đang mưa to là việc làm vô ích.","audioKind":"ex"},{"en":"Some students consider examinations pointless when they test memorisation rather than practical understanding of a subject.","vi":"Một số sinh viên cho rằng các kỳ thi là vô nghĩa khi chúng chỉ kiểm tra khả năng ghi nhớ thay vì sự hiểu biết thực tế về một môn học.","audioKind":"ex2"}],"collocations":[{"en":"a pointless exercise","vi":"việc làm vô ích"},{"en":"pointless arguments","vi":"những cuộc tranh luận vô nghĩa"},{"en":"seem pointless","vi":"có vẻ vô nghĩa"}],"wordFamily":["point (n.)","pointlessly (adv.)","pointlessness (n.)"],"synonyms":["futile","useless"],"antonyms":["worthwhile","meaningful"],"tipVi":"Thường dùng cấu trúc \"it is pointless to do\" để diễn đạt việc làm gì đó là vô ích.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_critical', 'en-b2-34', 'critical', '/ˈkrɪtɪkəl/', 'B2', 'mang tính quyết định; tối quan trọng; cốt yếu; mang tính phê bình; chỉ trích; đánh giá khắt khe; nguy kịch; trầm trọng', 'adj.', 'critically (adv.), critic (n.), criticism (n.), criticise (v.)', NULL, 'critical of dùng để chỉ sự chỉ trích; critical to dùng để chỉ tầm quan trọng đối với cái gì.', 'Your support was critical when I started my business.', NULL, 'Sự hỗ trợ của bạn mang tính quyết định khi tôi mới bắt đầu khởi nghiệp.', '{"wordId":"critical","ukIpa":"/ˈkrɪtɪkəl/","usIpa":"/ˈkrɪtɪkəl/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"extremely important to the success or outcome of something","vi":"mang tính quyết định; tối quan trọng; cốt yếu"},{"pos":"adj.","en":"expressing disapproval or carefully judging strengths and weaknesses","vi":"mang tính phê bình; chỉ trích; đánh giá khắt khe"},{"pos":"adj.","en":"so serious that someone may die or something may fail","vi":"nguy kịch; trầm trọng"}],"examples":[{"en":"Your support was critical when I started my business.","vi":"Sự hỗ trợ của bạn mang tính quyết định khi tôi mới bắt đầu khởi nghiệp.","audioKind":"ex"},{"en":"Access to clean water is critical to improving public health in rapidly growing urban communities.","vi":"Việc tiếp cận nguồn nước sạch có ý nghĩa tối quan trọng trong việc cải thiện y tế công cộng tại các cộng đồng đô thị đang phát triển nhanh chóng.","audioKind":"ex2"}],"collocations":[{"en":"critical to success","vi":"quan trọng sống còn đối với sự thành công"},{"en":"critical thinking","vi":"tư duy phản biện"},{"en":"critical of someone","vi":"chỉ trích ai đó"},{"en":"in critical condition","vi":"trong tình trạng nguy kịch"}],"wordFamily":["critically (adv.)","critic (n.)","criticism (n.)","criticise (v.)"],"synonyms":[],"antonyms":[],"tipVi":"critical of dùng để chỉ sự chỉ trích; critical to dùng để chỉ tầm quan trọng đối với cái gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_interpret', 'en-b2-34', 'interpret', '/ɪnˈtɝːprɪt/', 'B2', 'giải thích; hiểu; diễn giải; phiên dịch', 'v.', 'interpretation (n.), interpreter (n.), misinterpret (v.)', 'Đồng nghĩa: explain, construe', 'interpret có thể chỉ việc phiên dịch (nói); trong khi dịch viết thường dùng translate.', 'I interpreted her smile as permission to sit down.', NULL, 'Tôi hiểu nụ cười của cô ấy là sự cho phép tôi ngồi xuống.', '{"wordId":"interpret","ukIpa":"/ɪnˈtɜːprɪt/","usIpa":"/ɪnˈtɝːprɪt/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"To explain or understand the meaning of something","vi":"giải thích; hiểu; diễn giải"},{"pos":"v.","en":"To translate someone''s speech into another language as they speak","vi":"phiên dịch"}],"examples":[{"en":"I interpreted her smile as permission to sit down.","vi":"Tôi hiểu nụ cười của cô ấy là sự cho phép tôi ngồi xuống.","audioKind":"ex"},{"en":"Researchers must interpret survey results carefully because cultural differences may influence how participants understand the questions.","vi":"Các nhà nghiên cứu phải diễn giải kết quả khảo sát một cách cẩn thận vì sự khác biệt văn hóa có thể ảnh hưởng đến cách người tham gia hiểu các câu hỏi.","audioKind":"ex2"}],"collocations":[{"en":"interpret data","vi":"phân tích dữ liệu"},{"en":"interpret something as","vi":"hiểu điều gì như là"},{"en":"interpret for someone","vi":"phiên dịch cho ai đó"}],"wordFamily":["interpretation (n.)","interpreter (n.)","misinterpret (v.)"],"synonyms":["explain","construe"],"antonyms":[],"tipVi":"interpret có thể chỉ việc phiên dịch (nói); trong khi dịch viết thường dùng translate.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_imaginary', 'en-b2-34', 'imaginary', '/ɪˈmædʒəneri/', 'B2', 'tưởng tượng; ảo tưởng; hư cấu', 'adj.', 'imagine (v.), imagination (n.), imaginative (adj.)', 'Đồng nghĩa: fictional, unreal · Trái nghĩa: real, actual', 'imaginary chỉ những thứ thuộc về tưởng tượng; còn imaginative chỉ người hoặc vật giàu trí tưởng tượng.', 'The child poured tea for an imaginary friend.', NULL, 'Đứa trẻ rót trà cho một người bạn tưởng tượng.', '{"wordId":"imaginary","ukIpa":"/ɪˈmædʒɪnəri/","usIpa":"/ɪˈmædʒəneri/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"existing only in the mind, not in reality","vi":"tưởng tượng; ảo tưởng; hư cấu"}],"examples":[{"en":"The child poured tea for an imaginary friend.","vi":"Đứa trẻ rót trà cho một người bạn tưởng tượng.","audioKind":"ex"},{"en":"Creating imaginary worlds through storytelling can help children develop creativity and explore unfamiliar social situations safely.","vi":"Việc xây dựng những thế giới tưởng tượng qua kể chuyện có thể giúp trẻ phát triển sự sáng tạo và khám phá các tình huống xã hội xa lạ một cách an toàn.","audioKind":"ex2"}],"collocations":[{"en":"imaginary friend","vi":"bạn tưởng tượng"},{"en":"imaginary world","vi":"thế giới ảo"},{"en":"imaginary situation","vi":"tình huống giả định"}],"wordFamily":["imagine (v.)","imagination (n.)","imaginative (adj.)"],"synonyms":["fictional","unreal"],"antonyms":["real","actual"],"tipVi":"imaginary chỉ những thứ thuộc về tưởng tượng; còn imaginative chỉ người hoặc vật giàu trí tưởng tượng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_somewhat', 'en-b2-34', 'somewhat', '/ˈsʌmwʌt/', 'B2', 'hơi; có chút ít', 'adv.', NULL, 'Đồng nghĩa: rather, slightly', 'Mang tính trang trọng hơn a bit, thường dùng để làm dịu nhận định hoặc văn phong.', 'I felt somewhat nervous before my first driving lesson.', NULL, 'Tôi cảm thấy hơi lo lắng trước buổi học lái xe đầu tiên của mình.', '{"wordId":"somewhat","ukIpa":"/ˈsʌmwɒt/","usIpa":"/ˈsʌmwʌt/","cefr":"B2","topic":"thinking","senses":[{"pos":"adv.","en":"To a limited degree; rather, but not very.","vi":"hơi; có chút ít"}],"examples":[{"en":"I felt somewhat nervous before my first driving lesson.","vi":"Tôi cảm thấy hơi lo lắng trước buổi học lái xe đầu tiên của mình.","audioKind":"ex"},{"en":"Although online learning offers flexibility, its effectiveness remains somewhat dependent on students'' motivation and access to technology.","vi":"Mặc dù học trực tuyến mang lại sự linh hoạt, hiệu quả của nó vẫn phần nào phụ thuộc vào động lực của học sinh và khả năng tiếp cận công nghệ.","audioKind":"ex2"}],"collocations":[{"en":"somewhat different","vi":"hơi khác một chút"},{"en":"somewhat limited","vi":"có phần hạn chế"},{"en":"somewhat concerned","vi":"có chút lo ngại"}],"wordFamily":[],"synonyms":["rather","slightly"],"antonyms":[],"tipVi":"Mang tính trang trọng hơn a bit, thường dùng để làm dịu nhận định hoặc văn phong.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deepen', 'en-b2-34', 'deepen', '/ˈdiːpən/', 'B2', 'làm sâu sắc hơn; tăng cường; làm sâu thêm; đào sâu; trở nên trầm hơn; làm trầm giọng', 'v.', 'deep (adj.), deeply (adv.), depth (n.)', 'Đồng nghĩa: intensify, strengthen · Trái nghĩa: weaken', 'Cả ngoại động từ và nội động từ: deepen trust; a crisis deepens.', 'Sharing stories can deepen your friendship with someone.', NULL, 'Chia sẻ những câu chuyện có thể làm sâu sắc thêm tình bạn của bạn với ai đó.', '{"wordId":"deepen","ukIpa":"/ˈdiːpən/","usIpa":"/ˈdiːpən/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"To become stronger or more complete, or make something so","vi":"làm sâu sắc hơn; tăng cường"},{"pos":"v.","en":"To become physically deeper, or make something deeper","vi":"làm sâu thêm; đào sâu"},{"pos":"v.","en":"To become lower in pitch, or make a sound lower","vi":"trở nên trầm hơn; làm trầm giọng"}],"examples":[{"en":"Sharing stories can deepen your friendship with someone.","vi":"Chia sẻ những câu chuyện có thể làm sâu sắc thêm tình bạn của bạn với ai đó.","audioKind":"ex"},{"en":"International exchange programmes can deepen students'' understanding of other cultures and encourage greater respect for different perspectives.","vi":"Các chương trình trao đổi quốc tế có thể làm sâu sắc thêm hiểu biết của sinh viên về các nền văn hóa khác và thúc đẩy sự tôn trọng lớn hơn đối với các quan điểm khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"deepen understanding","vi":"làm sâu sắc thêm sự hiểu biết"},{"en":"deepen a crisis","vi":"làm trầm trọng thêm khủng hoảng"},{"en":"deepen a channel","vi":"đào sâu luồng lạch"},{"en":"a voice deepens","vi":"giọng nói trầm xuống"}],"wordFamily":["deep (adj.)","deeply (adv.)","depth (n.)"],"synonyms":["intensify","strengthen"],"antonyms":["weaken"],"tipVi":"Cả ngoại động từ và nội động từ: deepen trust; a crisis deepens.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_subjective', 'en-b2-34', 'subjective', '/səbˈdʒektɪv/', 'B2', 'chủ quan', 'adj.', 'subjectively (adv.), subjectivity (n.)', 'Trái nghĩa: objective', 'subjective nhấn mạnh cảm xúc cá nhân; objective nhấn mạnh sự thật khách quan.', 'Taste is subjective, so choose whichever colour you prefer.', NULL, 'Gu thẩm mỹ mang tính chủ quan, vì vậy cứ chọn màu nào bạn thích đi.', '{"wordId":"subjective","ukIpa":"/səbˈdʒektɪv/","usIpa":"/səbˈdʒektɪv/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Based on personal feelings or opinions rather than independent facts","vi":"chủ quan"}],"examples":[{"en":"Taste is subjective, so choose whichever colour you prefer.","vi":"Gu thẩm mỹ mang tính chủ quan, vì vậy cứ chọn màu nào bạn thích đi.","audioKind":"ex"},{"en":"Although student feedback is valuable, subjective opinions should not be the sole basis for evaluating teaching quality.","vi":"Mặc dù phản hồi của học sinh rất có giá trị, các ý kiến chủ quan không nên là cơ sở duy nhất để đánh giá chất lượng giảng dạy.","audioKind":"ex2"}],"collocations":[{"en":"subjective judgement","vi":"nhận định chủ quan"},{"en":"subjective experience","vi":"trải nghiệm chủ quan"},{"en":"highly subjective","vi":"rất chủ quan"}],"wordFamily":["subjectively (adv.)","subjectivity (n.)"],"synonyms":[],"antonyms":["objective"],"tipVi":"subjective nhấn mạnh cảm xúc cá nhân; objective nhấn mạnh sự thật khách quan.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_impossibility', 'en-b2-34', 'impossibility', '/ɪmˌpɑːsəˈbɪləti/', 'B2', 'sự bất khả thi; điều không thể xảy ra', 'n.', 'impossible (adj.), impossibly (adv.), possible (adj.), possibility (n.)', 'Trái nghĩa: possibility', 'Dùng dạng không đếm được khi chỉ tính bất khả thi, và đếm được khi chỉ một việc không thể xảy ra cụ thể.', 'Carrying this sofa upstairs alone is an impossibility.', NULL, 'Việc tự mình khiêng chiếc ghế sofa này lên lầu là điều bất khả thi.', '{"wordId":"impossibility","ukIpa":"/ɪmˌpɒsəˈbɪləti/","usIpa":"/ɪmˌpɑːsəˈbɪləti/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"the state of being impossible, or something that cannot happen","vi":"sự bất khả thi; điều không thể xảy ra"}],"examples":[{"en":"Carrying this sofa upstairs alone is an impossibility.","vi":"Việc tự mình khiêng chiếc ghế sofa này lên lầu là điều bất khả thi.","audioKind":"ex"},{"en":"The impossibility of predicting every natural disaster highlights the importance of resilient infrastructure and emergency planning.","vi":"Việc không thể dự đoán trước mọi thảm họa tự nhiên làm nổi bật tầm quan trọng của cơ sở hạ tầng kiên cố và kế hoạch ứng phó khẩn cấp.","audioKind":"ex2"}],"collocations":[{"en":"a practical impossibility","vi":"một điều thực tế không thể xảy ra"},{"en":"a physical impossibility","vi":"một điều kiện vật lý không thể xảy ra"},{"en":"the impossibility of doing something","vi":"sự bất khả thi khi làm điều gì đó"}],"wordFamily":["impossible (adj.)","impossibly (adv.)","possible (adj.)","possibility (n.)"],"synonyms":[],"antonyms":["possibility"],"tipVi":"Dùng dạng không đếm được khi chỉ tính bất khả thi, và đếm được khi chỉ một việc không thể xảy ra cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_overlook', 'en-b2-34', 'overlook', '/ˌoʊvərˈlʊk/', 'B2', 'bỏ sót; không chú ý; nhìn xuống; hướng ra; tha thứ; phớt lờ', 'v.', NULL, NULL, 'overlook có nghĩa là bỏ sót hoặc nhìn từ trên xuống; đừng nhầm lẫn với oversee nghĩa là giám sát.', 'I overlooked a small crack in the bowl.', NULL, 'Tôi đã bỏ sót một vết nứt nhỏ trên cái bát.', '{"wordId":"overlook","ukIpa":"/ˌəʊvəˈlʊk/","usIpa":"/ˌoʊvərˈlʊk/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"To fail to notice or consider something.","vi":"bỏ sót; không chú ý"},{"pos":"v.","en":"To have a view of somewhere from above.","vi":"nhìn xuống; hướng ra"},{"pos":"v.","en":"To deliberately ignore a mistake or fault.","vi":"tha thứ; phớt lờ"}],"examples":[{"en":"I overlooked a small crack in the bowl.","vi":"Tôi đã bỏ sót một vết nứt nhỏ trên cái bát.","audioKind":"ex"},{"en":"Urban planners sometimes overlook the needs of older residents when designing new public transport systems.","vi":"Các nhà quy hoạch đô thị đôi khi bỏ qua nhu cầu của cư dân lớn tuổi khi thiết kế hệ thống giao thông công cộng mới.","audioKind":"ex2"}],"collocations":[{"en":"overlook a detail","vi":"bỏ sót một chi tiết"},{"en":"overlook the fact that","vi":"bỏ qua thực tế là"},{"en":"overlook the sea","vi":"nhìn ra biển"},{"en":"overlook a mistake","vi":"bỏ qua một lỗi lầm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"overlook có nghĩa là bỏ sót hoặc nhìn từ trên xuống; đừng nhầm lẫn với oversee nghĩa là giám sát.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_certainty', 'en-b2-34', 'certainty', '/ˈsɝːtnti/', 'B2', 'sự chắc chắn; niềm tin chắc; điều chắc chắn', 'n.', 'certain (adj.), certainly (adv.), uncertain (adj.), uncertainty (n.)', 'Đồng nghĩa: assurance, sureness · Trái nghĩa: uncertainty, doubt', 'Chỉ sự chắc chắn thường không đếm được; a certainty chỉ một việc chắc chắn xảy ra.', 'I cannot say with certainty where I left my keys.', NULL, 'Tôi không thể khẳng định chắc chắn mình đã để chìa khóa ở đâu.', '{"wordId":"certainty","ukIpa":"/ˈsɜːtnti/","usIpa":"/ˈsɝːtnti/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"The state of being completely sure about something.","vi":"sự chắc chắn; niềm tin chắc"},{"pos":"n.","en":"Something that is definitely true or sure to happen.","vi":"điều chắc chắn"}],"examples":[{"en":"I cannot say with certainty where I left my keys.","vi":"Tôi không thể khẳng định chắc chắn mình đã để chìa khóa ở đâu.","audioKind":"ex"},{"en":"Although climate models continue to improve, scientists cannot predict every regional change with absolute certainty.","vi":"Mặc dù các mô hình khí hậu ngày càng cải thiện, các nhà khoa học vẫn không thể dự đoán mọi thay đổi theo vùng với độ chính xác tuyệt đối.","audioKind":"ex2"}],"collocations":[{"en":"with certainty","vi":"với sự chắc chắn"},{"en":"absolute certainty","vi":"sự chắc chắn tuyệt đối"},{"en":"a degree of certainty","vi":"mức độ chắc chắn nhất định"}],"wordFamily":["certain (adj.)","certainly (adv.)","uncertain (adj.)","uncertainty (n.)"],"synonyms":["assurance","sureness"],"antonyms":["uncertainty","doubt"],"tipVi":"Chỉ sự chắc chắn thường không đếm được; a certainty chỉ một việc chắc chắn xảy ra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_eternal', 'en-b2-34', 'eternal', '/ɪˈtɝːnəl/', 'B2', 'vĩnh cửu; bất tận; vô tận; lặp đi lặp lại gây khó chịu', 'adj.', 'eternally (adv.), eternity (n.)', 'Đồng nghĩa: everlasting, endless · Trái nghĩa: temporary, transient', 'eternal nhấn mạnh không có điểm kết thúc; eternal complaints có thể dùng mang tính cường điệu để chỉ những lời phàn nàn không dứt.', 'The couple promised eternal love beneath the flowering tree.', NULL, 'Cặp đôi hứa hẹn tình yêu vĩnh cửu dưới tán cây đang nở hoa.', '{"wordId":"eternal","ukIpa":"/ɪˈtɜːnəl/","usIpa":"/ɪˈtɝːnəl/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Lasting forever, without an end.","vi":"vĩnh cửu; bất tận"},{"pos":"adj.","en":"Seeming to continue endlessly, often in an annoying way.","vi":"vô tận; lặp đi lặp lại gây khó chịu"}],"examples":[{"en":"The couple promised eternal love beneath the flowering tree.","vi":"Cặp đôi hứa hẹn tình yêu vĩnh cửu dưới tán cây đang nở hoa.","audioKind":"ex"},{"en":"Many ancient cultures used monumental architecture to express hopes for eternal life and preserve collective memories.","vi":"Nhiều nền văn hóa cổ đại đã sử dụng kiến trúc hoành tráng để bày tỏ hy vọng về sự bất tử và lưu giữ ký ức tập thể.","audioKind":"ex2"}],"collocations":[{"en":"eternal life","vi":"sự sống vĩnh cửu"},{"en":"eternal love","vi":"tình yêu vĩnh cửu"},{"en":"eternal optimism","vi":"sự lạc quan bất diệt"}],"wordFamily":["eternally (adv.)","eternity (n.)"],"synonyms":["everlasting","endless"],"antonyms":["temporary","transient"],"tipVi":"eternal nhấn mạnh không có điểm kết thúc; eternal complaints có thể dùng mang tính cường điệu để chỉ những lời phàn nàn không dứt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_distinct', 'en-b2-34', 'distinct', '/dɪˈstɪŋkt/', 'B2', 'khác biệt; tách biệt; rõ ràng; dễ nhận thấy', 'adj.', 'distinction (n.), distinctly (adv.), distinctive (adj.), distinctness (n.)', 'Đồng nghĩa: different, clear · Trái nghĩa: similar, indistinct', 'distinct from có nghĩa là "khác với"; tránh nhầm lẫn với từ distant.', 'The twins have similar faces but distinct personalities.', NULL, 'Cặp sinh đôi có khuôn mặt giống nhau nhưng tính cách lại khác biệt.', '{"wordId":"distinct","ukIpa":"/dɪˈstɪŋkt/","usIpa":"/dɪˈstɪŋkt/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"clearly different or separate from something else","vi":"khác biệt; tách biệt"},{"pos":"adj.","en":"easy to notice, hear, see, or recognize","vi":"rõ ràng; dễ nhận thấy"}],"examples":[{"en":"The twins have similar faces but distinct personalities.","vi":"Cặp sinh đôi có khuôn mặt giống nhau nhưng tính cách lại khác biệt.","audioKind":"ex"},{"en":"Public transport and private cars serve distinct needs, so urban planners should consider both.","vi":"Giao thông công cộng và xe hơi cá nhân đáp ứng những nhu cầu khác nhau, vì vậy các nhà quy hoạch đô thị nên cân nhắc cả hai.","audioKind":"ex2"}],"collocations":[{"en":"distinct from","vi":"khác với"},{"en":"two distinct groups","vi":"hai nhóm riêng biệt"},{"en":"distinct advantage","vi":"lợi thế rõ rệt"}],"wordFamily":["distinction (n.)","distinctly (adv.)","distinctive (adj.)","distinctness (n.)"],"synonyms":["different","clear"],"antonyms":["similar","indistinct"],"tipVi":"distinct from có nghĩa là \"khác với\"; tránh nhầm lẫn với từ distant.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 28, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_34_1', 'en-b2-34', 'Cách dùng “approach” (n.) — phương pháp; cách tiếp cận', 'an approach to learning  ·  adopt an approach  ·  approach a problem', 'Khi là danh từ mang nghĩa "phương pháp", dùng "to" + danh từ hoặc danh động từ (V-ing); khi là động từ, tân ngữ đi trực tiếp ngay sau.', 'Họ từ (Word Family): approachable (adj.), unapproachable (adj.) | Đồng nghĩa: method, tackle, near', '[{"hanzi":"We tried a different approach to training our puppy.","pinyin":"","meaning":"Chúng tôi đã thử một cách tiếp cận khác để huấn luyện chú chó con của mình."},{"hanzi":"A balanced approach to urban planning should consider both economic growth and the protection of green spaces.","pinyin":"","meaning":"Một phương pháp quy hoạch đô thị cân bằng cần xem xét cả tăng trưởng kinh tế và việc bảo vệ không gian xanh."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_34_2', 'en-b2-34', 'Cách dùng “eternal” (adj.) — vĩnh cửu; bất tận', 'eternal life  ·  eternal love  ·  eternal optimism', 'eternal nhấn mạnh không có điểm kết thúc; eternal complaints có thể dùng mang tính cường điệu để chỉ những lời phàn nàn không dứt.', 'Họ từ (Word Family): eternally (adv.), eternity (n.) | Đồng nghĩa: everlasting, endless · Trái nghĩa: temporary, transient', '[{"hanzi":"The couple promised eternal love beneath the flowering tree.","pinyin":"","meaning":"Cặp đôi hứa hẹn tình yêu vĩnh cửu dưới tán cây đang nở hoa."},{"hanzi":"Many ancient cultures used monumental architecture to express hopes for eternal life and preserve collective memories.","pinyin":"","meaning":"Nhiều nền văn hóa cổ đại đã sử dụng kiến trúc hoành tráng để bày tỏ hy vọng về sự bất tử và lưu giữ ký ức tập thể."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_34_3', 'en-b2-34', 'Cách dùng “positively” (adv.) — tích cực; theo chiều hướng tốt; đầy lạc quan', 'respond positively  ·  positively identify  ·  positively influence', 'positively có thể dùng để nhấn mạnh sắc thái biểu cảm, hoặc diễn tả thái độ tích cực cũng như sự chắc chắn.', 'Họ từ (Word Family): positive (adj.), positivity (n.) | Trái nghĩa: negatively', '[{"hanzi":"My sister reacted positively when I suggested a picnic.","pinyin":"","meaning":"Chị tôi đã phản ứng rất tích cực khi tôi đưa ra ý định đi dã ngoại."},{"hanzi":"Students often respond positively to detailed feedback that recognises their progress and offers practical guidance.","pinyin":"","meaning":"Học sinh thường phản hồi tích cực đối với những lời nhận xét chi tiết vừa công nhận sự tiến bộ vừa đưa ra định hướng thực tế cho các em."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_34_4', 'en-b2-34', 'Cách dùng “impossibility” (n.) — sự bất khả thi; điều không thể xảy ra', 'a practical impossibility  ·  a physical impossibility  ·  the impossibility of doing something', 'Dùng dạng không đếm được khi chỉ tính bất khả thi, và đếm được khi chỉ một việc không thể xảy ra cụ thể.', 'Họ từ (Word Family): impossible (adj.), impossibly (adv.), possible (adj.), possibility (n.) | Trái nghĩa: possibility', '[{"hanzi":"Carrying this sofa upstairs alone is an impossibility.","pinyin":"","meaning":"Việc tự mình khiêng chiếc ghế sofa này lên lầu là điều bất khả thi."},{"hanzi":"The impossibility of predicting every natural disaster highlights the importance of resilient infrastructure and emergency planning.","pinyin":"","meaning":"Việc không thể dự đoán trước mọi thảm họa tự nhiên làm nổi bật tầm quan trọng của cơ sở hạ tầng kiên cố và kế hoạch ứng phó khẩn cấp."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_34_1', 'en-b2-34', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_34_1_1', 'ten_b2_34_1', 'philosophy', 'My sister studies philosophy and enjoys discussing difficult questions.', 'My sister studies philosophy and enjoys discussing difficult questions.', '/fɪˈlɑːsəfi/', 'Chị tôi học chuyên ngành triết học và rất thích thảo luận về những câu hỏi hóc búa.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_34_1_2', 'ten_b2_34_1', 'consistency', 'Our coach values consistency more than occasional brilliant performances.', 'Our coach values consistency more than occasional brilliant performances.', '/kənˈsɪstənsi/', 'Huấn luyện viên của chúng tôi coi trọng sự ổn định hơn những màn trình diễn xuất thần thỉnh thoảng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_34_1_3', 'ten_b2_34_1', 'principle', 'I refused the extra money as a matter of principle.', 'I refused the extra money as a matter of principle.', '/ˈprɪnsəpəl/', 'Tôi đã từ chối số tiền thừa ra vì vấn đề nguyên tắc.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_34_1_4', 'ten_b2_34_1', 'extent', 'We only discovered the extent of the leak yesterday.', 'We only discovered the extent of the leak yesterday.', '/ɪkˈstent/', 'Chúng tôi mới chỉ phát hiện ra mức độ nghiêm trọng của vụ rò rỉ vào ngày hôm qua.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_34_1_5', 'ten_b2_34_1', 'derive', 'I derive great pleasure from growing vegetables on my balcony.', 'I derive great pleasure from growing vegetables on my balcony.', '/dɪˈraɪv/', 'Tôi tìm thấy niềm vui lớn từ việc trồng rau trên ban công nhà mình.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_34_1_6', 'ten_b2_34_1', 'emerge', 'A small rabbit emerged from beneath the garden shed.', 'A small rabbit emerged from beneath the garden shed.', '/ɪˈmɝːdʒ/', 'Một chú thỏ nhỏ chui ra từ bên dưới túp lều trong vườn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_34_1_7', 'ten_b2_34_1', 'sufficient', 'We have sufficient food for everyone at the picnic.', 'We have sufficient food for everyone at the picnic.', '/səˈfɪʃənt/', 'Chúng tôi có đủ thức ăn cho tất cả mọi người tham gia buổi dã ngoại.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_34_1_8', 'ten_b2_34_1', 'ineffective', 'This tiny fan is ineffective in such a large room.', 'This tiny fan is ineffective in such a large room.', '/ˌɪnɪˈfektɪv/', 'Chiếc quạt nhỏ xíu này chẳng có tác dụng gì trong căn phòng rộng lớn như vậy.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_34_1_1', 'en-b2-34', 'ten_b2_34_1', 'listening', 'listening', 'My sister studies philosophy and enjoys discussing difficult questions.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chia sẻ những câu chuyện có thể làm sâu sắc thêm tình bạn của bạn với ai đó.","Hãy điều chỉnh góc màn hình để giảm độ chói.","Tưới cây khi trời đang mưa to là việc làm vô ích.","Chị tôi học chuyên ngành triết học và rất thích thảo luận về những câu hỏi hóc búa."]'::jsonb, 3, 'My sister studies philosophy and enjoys discussing difficult questions. → Chị tôi học chuyên ngành triết học và rất thích thảo luận về những câu hỏi hóc búa.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_34_1_2', 'en-b2-34', 'ten_b2_34_1', 'listening', 'listening', 'Our coach values consistency more than occasional brilliant performances.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chị tôi học chuyên ngành triết học và rất thích thảo luận về những câu hỏi hóc búa.","Huấn luyện viên của chúng tôi coi trọng sự ổn định hơn những màn trình diễn xuất thần thỉnh thoảng.","Tôi tìm thấy niềm vui lớn từ việc trồng rau trên ban công nhà mình.","Hãy điều chỉnh góc màn hình để giảm độ chói."]'::jsonb, 1, 'Our coach values consistency more than occasional brilliant performances. → Huấn luyện viên của chúng tôi coi trọng sự ổn định hơn những màn trình diễn xuất thần thỉnh thoảng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_34_1_3', 'en-b2-34', 'ten_b2_34_1', 'listening', 'listening', 'I refused the extra money as a matter of principle.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Gu thẩm mỹ mang tính chủ quan, vì vậy cứ chọn màu nào bạn thích đi.","Tôi đã từ chối số tiền thừa ra vì vấn đề nguyên tắc.","Việc tự mình khiêng chiếc ghế sofa này lên lầu là điều bất khả thi.","Chiếc quạt nhỏ xíu này chẳng có tác dụng gì trong căn phòng rộng lớn như vậy."]'::jsonb, 1, 'I refused the extra money as a matter of principle. → Tôi đã từ chối số tiền thừa ra vì vấn đề nguyên tắc.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_34_2', 'en-b2-34', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_34_2_1', 'ten_b2_34_2', 'philosophy', 'Studying philosophy can help students question assumptions and develop stronger arguments about complex ethical issues.', 'Studying philosophy can help students question assumptions and develop stronger arguments about complex ethical issues.', '/fɪˈlɑːsəfi/', 'Việc học triết học có thể giúp sinh viên chất vấn các giả định có sẵn và đưa ra những lập luận sắc bén hơn về các vấn đề đạo đức phức tạp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_34_2_2', 'ten_b2_34_2', 'consistency', 'Greater consistency in marking standards would help ensure that students receive fair results across different examination centres.', 'Greater consistency in marking standards would help ensure that students receive fair results across different examination centres.', '/kənˈsɪstənsi/', 'Tính nhất quán cao hơn trong các tiêu chuẩn chấm điểm sẽ giúp đảm bảo học sinh nhận được kết quả công bằng ở các trung tâm thi khác nhau.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_34_2_3', 'ten_b2_34_2', 'principle', 'The principle of equal opportunity should guide policies designed to improve access to higher education.', 'The principle of equal opportunity should guide policies designed to improve access to higher education.', '/ˈprɪnsəpəl/', 'Nguyên tắc cơ hội bình đẳng nên định hướng cho các chính sách nhằm cải thiện khả năng tiếp cận giáo dục đại học.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_34_2_4', 'ten_b2_34_2', 'extent', 'The extent to which public transport reduces pollution depends on passenger numbers and energy sources.', 'The extent to which public transport reduces pollution depends on passenger numbers and energy sources.', '/ɪkˈstent/', 'Mức độ mà giao thông công cộng làm giảm ô nhiễm phụ thuộc vào số lượng hành khách và nguồn năng lượng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_34_2_5', 'ten_b2_34_2', 'derive', 'Many coastal communities derive a significant proportion of their income from tourism and fishing.', 'Many coastal communities derive a significant proportion of their income from tourism and fishing.', '/dɪˈraɪv/', 'Nhiều cộng đồng ven biển có phần lớn thu nhập xuất phát từ hoạt động du lịch và đánh bắt hải sản.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_34_2_6', 'ten_b2_34_2', 'emerge', 'New employment opportunities may emerge as governments invest more heavily in renewable energy infrastructure.', 'New employment opportunities may emerge as governments invest more heavily in renewable energy infrastructure.', '/ɪˈmɝːdʒ/', 'Cơ hội việc làm mới có thể xuất hiện khi các chính phủ đầu tư mạnh mẽ hơn vào cơ sở hạ tầng năng lượng tái tạo.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_34_2_1', 'en-b2-34', 'ten_b2_34_2', 'listening', 'listening', 'Studying philosophy can help students question assumptions and develop stronger arguments about complex ethical issues.', NULL, 'Trong câu vừa nghe, từ “philosophy” mang nghĩa nào sau đây?', '["cái thứ hai; người thứ hai; điều thứ hai (trong số hai đối tượng đã nhắc tới)","triết học (nghiên cứu về tri thức, sự tồn tại, thực tại và giá trị đạo đức)","bề ngoài; phần bên ngoài","băng rôn; biểu ngữ; cờ"]'::jsonb, 1, '“philosophy” (/fɪˈlɑːsəfi/): triết học (nghiên cứu về tri thức, sự tồn tại, thực tại và giá trị đạo đức). Câu đầy đủ: Studying philosophy can help students question assumptions and develop stronger arguments about complex ethical issues.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_34_2_2', 'en-b2-34', 'ten_b2_34_2', 'listening', 'listening', 'Greater consistency in marking standards would help ensure that students receive fair results across different examination centres.', NULL, 'Trong câu vừa nghe, từ “consistency” mang nghĩa nào sau đây?', '["thành phần; linh kiện; bộ phận cấu thành","tính nhất quán; độ ổn định","khiên; vật che chắn","vùng ngoại ô; vùng rìa thị trấn (thường dùng số nhiều)"]'::jsonb, 1, '“consistency” (/kənˈsɪstənsi/): tính nhất quán; độ ổn định. Câu đầy đủ: Greater consistency in marking standards would help ensure that students receive fair results across different examination centres.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
