INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_34_1', 'en-b2-34', NULL, 'comprehensive_test', 'listening', 'philosophy', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["có tính thực dụng; nặng về công năng hơn trang trí","ngụy trang; che giấu","cầu chì; thiết bị ngắt điện an toàn","triết học (nghiên cứu về tri thức, sự tồn tại, thực tại và giá trị đạo đức)"]'::jsonb, 3, 'philosophy (/fɪˈlɑːsəfi/) → triết học (nghiên cứu về tri thức, sự tồn tại, thực tại và giá trị đạo đức); triết lý sống; hệ tư tưởng (tập hợp niềm tin định hướng hành động và quyết định)', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_34_2', 'en-b2-34', NULL, 'comprehensive_test', 'listening', 'Our coach values consistency more than occasional brilliant performances.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã từ chối số tiền thừa ra vì vấn đề nguyên tắc.","Cặp đôi hứa hẹn tình yêu vĩnh cửu dưới tán cây đang nở hoa.","Gu thẩm mỹ mang tính chủ quan, vì vậy cứ chọn màu nào bạn thích đi.","Huấn luyện viên của chúng tôi coi trọng sự ổn định hơn những màn trình diễn xuất thần thỉnh thoảng."]'::jsonb, 3, 'Our coach values consistency more than occasional brilliant performances. → Huấn luyện viên của chúng tôi coi trọng sự ổn định hơn những màn trình diễn xuất thần thỉnh thoảng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_34_3', 'en-b2-34', NULL, 'comprehensive_test', 'listening', 'principle', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự kiểm tra, sự thanh tra (xem xét kỹ lưỡng để đánh giá tình trạng, chất lượng hoặc độ an toàn)","nguyên tắc; phương châm sống","tuyệt chủng","chấp nhận; đón nhận, hưởng ứng"]'::jsonb, 1, 'principle (/ˈprɪnsəpəl/) → nguyên tắc; phương châm sống; nguyên lý; định luật cơ bản', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_34_4', 'en-b2-34', NULL, 'comprehensive_test', 'listening', 'We only discovered the extent of the leak yesterday.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi mới chỉ phát hiện ra mức độ nghiêm trọng của vụ rò rỉ vào ngày hôm qua.","Chia sẻ những câu chuyện có thể làm sâu sắc thêm tình bạn của bạn với ai đó.","Chúng tôi đã thử một cách tiếp cận khác để huấn luyện chú chó con của mình.","Bất chấp những khó khăn gần đây, Lina vẫn duy trì một thái độ sống tích cực."]'::jsonb, 0, 'We only discovered the extent of the leak yesterday. → Chúng tôi mới chỉ phát hiện ra mức độ nghiêm trọng của vụ rò rỉ vào ngày hôm qua.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_34_5', 'en-b2-34', NULL, 'comprehensive_test', 'listening', 'derive', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["mỏng manh, dễ vỡ, dễ hư hỏng","thu được; tìm thấy; nhận được","đống lớn; khối lớn; lượng lớn","mờ ảo; thiếu ánh sáng"]'::jsonb, 1, 'derive (/dɪˈraɪv/) → thu được; tìm thấy; nhận được; bắt nguồn từ; chuyển hóa từ', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_34_6', 'en-b2-34', NULL, 'comprehensive_test', 'listening', 'A small rabbit emerged from beneath the garden shed.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sự hỗ trợ của bạn mang tính quyết định khi tôi mới bắt đầu khởi nghiệp.","Một chú thỏ nhỏ chui ra từ bên dưới túp lều trong vườn.","Tưới cây khi trời đang mưa to là việc làm vô ích.","Gu thẩm mỹ mang tính chủ quan, vì vậy cứ chọn màu nào bạn thích đi."]'::jsonb, 1, 'A small rabbit emerged from beneath the garden shed. → Một chú thỏ nhỏ chui ra từ bên dưới túp lều trong vườn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_34_7', 'en-b2-34', NULL, 'comprehensive_test', 'listening', 'sufficient', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thường dân; người không thuộc lực lượng vũ trang","địa vị xã hội; thân phận","đủ; đầy đủ","tiêm phòng; tiêm chủng vaccine"]'::jsonb, 2, 'sufficient (/səˈfɪʃənt/) → đủ; đầy đủ', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_34_8', 'en-b2-34', NULL, 'comprehensive_test', 'listening', 'This tiny fan is ineffective in such a large room.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chiếc quạt nhỏ xíu này chẳng có tác dụng gì trong căn phòng rộng lớn như vậy.","Một chú thỏ nhỏ chui ra từ bên dưới túp lều trong vườn.","Sự hỗ trợ của bạn mang tính quyết định khi tôi mới bắt đầu khởi nghiệp.","Tôi không thể khẳng định chắc chắn mình đã để chìa khóa ở đâu."]'::jsonb, 0, 'This tiny fan is ineffective in such a large room. → Chiếc quạt nhỏ xíu này chẳng có tác dụng gì trong căn phòng rộng lớn như vậy.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_34_9', 'en-b2-34', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to obtain something from a particular source”?', '["derive","outlook","philosophy","extent"]'::jsonb, 0, 'derive (/dɪˈraɪv/) → thu được; tìm thấy; nhận được', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_34_10', 'en-b2-34', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To become visible or known after being hidden.”?', '["somewhat","persuasive","consistency","emerge"]'::jsonb, 3, 'emerge (/ɪˈmɝːdʒ/) → hiện ra; xuất hiện; nổi lên', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_34_11', 'en-b2-34', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “enough to meet a need or achieve a purpose”?', '["consistency","sufficient","ineffective","evidence"]'::jsonb, 1, 'sufficient (/səˈfɪʃənt/) → đủ; đầy đủ', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_34_12', 'en-b2-34', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “not producing the result that is wanted”?', '["ineffective","evidence","indication","naive"]'::jsonb, 0, 'ineffective (/ˌɪnɪˈfektɪv/) → không hiệu quả; không có tác dụng', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_34_13', 'en-b2-34', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Too willing to trust because of limited experience.”?', '["naive","indication","derive","evidence"]'::jsonb, 0, 'naive (/naɪˈiːv/) → ngây thơ; khờ dại; dễ tin người', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
