INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_34_18', 'en-b2-34', NULL, 'comprehensive_test', 'reading', NULL, 'Studying philosophy can help students question assumptions and develop stronger arguments about complex ethical issues.', 'Dựa vào câu trên, từ “philosophy” có nghĩa phù hợp nhất là gì?', '["gỉ sét, vảy sắt","triết học (nghiên cứu về tri thức, sự tồn tại, thực tại và giá trị đạo đức)","giàu có; phú quý","đồng (kim loại màu nâu đỏ)"]'::jsonb, 1, 'philosophy: triết học (nghiên cứu về tri thức, sự tồn tại, thực tại và giá trị đạo đức); triết lý sống; hệ tư tưởng (tập hợp niềm tin định hướng hành động và quyết định). Dịch cả câu: Việc học triết học có thể giúp sinh viên chất vấn các giả định có sẵn và đưa ra những lập luận sắc bén hơn về các vấn đề đạo đức phức tạp.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_34_19', 'en-b2-34', NULL, 'comprehensive_test', 'reading', NULL, 'Greater consistency in marking standards would help ensure that students receive fair results across different examination centres.', 'Dựa vào câu trên, từ “consistency” có nghĩa phù hợp nhất là gì?', '["thuộc hệ mét; theo hệ mét","tính nhất quán; độ ổn định","chính xác; tỉ mỉ","chuyên về; chuyên môn hóa"]'::jsonb, 1, 'consistency: tính nhất quán; độ ổn định; độ đặc; độ sánh; độ mịn. Dịch cả câu: Tính nhất quán cao hơn trong các tiêu chuẩn chấm điểm sẽ giúp đảm bảo học sinh nhận được kết quả công bằng ở các trung tâm thi khác nhau.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_34_20', 'en-b2-34', NULL, 'comprehensive_test', 'reading', NULL, 'The principle of equal opportunity should guide policies designed to improve access to higher education.', 'Dựa vào câu trên, từ “principle” có nghĩa phù hợp nhất là gì?', '["nguyên tắc; phương châm sống","ban đầu; lúc đầu","nhỏ; nhẹ; mong manh; không đáng kể","cười khúc khích; cười tủm tỉm"]'::jsonb, 0, 'principle: nguyên tắc; phương châm sống; nguyên lý; định luật cơ bản. Dịch cả câu: Nguyên tắc cơ hội bình đẳng nên định hướng cho các chính sách nhằm cải thiện khả năng tiếp cận giáo dục đại học.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_34_21', 'en-b2-34', NULL, 'comprehensive_test', 'reading', NULL, 'The extent to which public transport reduces pollution depends on passenger numbers and energy sources.', 'Dựa vào câu trên, từ “extent” có nghĩa phù hợp nhất là gì?', '["mức độ; phạm vi","sự bất đồng quan điểm; cuộc tranh cãi","cái cày","chỗ trống việc làm; vị trí tuyển dụng"]'::jsonb, 0, 'extent: mức độ; phạm vi. Dịch cả câu: Mức độ mà giao thông công cộng làm giảm ô nhiễm phụ thuộc vào số lượng hành khách và nguồn năng lượng.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_34_22', 'en-b2-34', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự chắc chắn; niềm tin chắc”', '["bulletin","preceding","certainty","retail"]'::jsonb, 2, 'sự chắc chắn; niềm tin chắc → certainty (/ˈsɝːtnti/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_34_23', 'en-b2-34', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “vĩnh cửu; bất tận”', '["rag","eternal","outlet","curve"]'::jsonb, 1, 'vĩnh cửu; bất tận → eternal (/ɪˈtɝːnəl/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_34_24', 'en-b2-34', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “khác biệt; tách biệt”', '["clubhouse","existence","distinct","correspondent"]'::jsonb, 2, 'khác biệt; tách biệt → distinct (/dɪˈstɪŋkt/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-35', 'en', 'Bài 35: Tư duy & Nhận thức (2) - CEFR B2', 'CEFR B2', 'B2 · Tư duy', '28 từ vựng Tiếng Anh CEFR B2 chủ đề tư duy & nhận thức kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4035, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_speculate', 'en-b2-35', 'speculate', '/ˈspekjəleɪt/', 'B2', 'suy đoán; phỏng đoán; đầu cơ', 'v.', 'speculation (n.), speculative (adj.), speculator (n.)', 'Đồng nghĩa: conjecture', 'suy đoán thường đi với giới từ about hoặc mệnh đề that; lĩnh vực đầu cơ dùng giới từ in.', 'We can only speculate about what caused the delay.', NULL, 'Chúng ta chỉ có thể phỏng đoán về nguyên nhân gây ra sự chậm trễ.', '{"wordId":"speculate","ukIpa":"/ˈspekjuleɪt/","usIpa":"/ˈspekjəleɪt/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"Form ideas about something without having enough evidence.","vi":"suy đoán; phỏng đoán"},{"pos":"v.","en":"Buy and sell assets hoping to profit from price changes.","vi":"đầu cơ"}],"examples":[{"en":"We can only speculate about what caused the delay.","vi":"Chúng ta chỉ có thể phỏng đoán về nguyên nhân gây ra sự chậm trễ.","audioKind":"ex"},{"en":"Researchers speculate that changing work patterns could reduce traffic congestion in major urban centres.","vi":"Các nhà nghiên cứu phỏng đoán rằng việc thay đổi mô hình làm việc có thể giảm ùn tắc giao thông ở các trung tâm đô thị lớn.","audioKind":"ex2"}],"collocations":[{"en":"speculate about the cause","vi":"suy đoán về nguyên nhân"},{"en":"speculate that","vi":"phỏng đoán rằng"},{"en":"speculate in property","vi":"đầu cơ bất động sản"}],"wordFamily":["speculation (n.)","speculative (adj.)","speculator (n.)"],"synonyms":["conjecture"],"antonyms":[],"tipVi":"suy đoán thường đi với giới từ about hoặc mệnh đề that; lĩnh vực đầu cơ dùng giới từ in.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mistaken', 'en-b2-35', 'mistaken', '/mɪˈsteɪkən/', 'B2', 'sai lầm; hiểu lầm', 'adj.', 'mistake (n.), mistake (v.), mistakenly (adv.)', 'Đồng nghĩa: wrong, incorrect · Trái nghĩa: correct, right', 'Nhân vật làm chủ ngữ thường dùng be mistaken about, diễn tả việc hiểu lầm hoặc nhầm lẫn về điều gì đó.', 'I was mistaken about the time of our appointment.', NULL, 'Tôi đã nhầm về thời gian cuộc hẹn của chúng tôi.', '{"wordId":"mistaken","ukIpa":"/mɪˈsteɪkən/","usIpa":"/mɪˈsteɪkən/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Wrong about something or based on an incorrect belief.","vi":"sai lầm; hiểu lầm"}],"examples":[{"en":"I was mistaken about the time of our appointment.","vi":"Tôi đã nhầm về thời gian cuộc hẹn của chúng tôi.","audioKind":"ex"},{"en":"The mistaken belief that all bacteria are harmful can prevent people from understanding their ecological importance.","vi":"Quan điểm sai lầm rằng tất cả vi khuẩn đều có hại có thể ngăn cản mọi người hiểu rõ tầm quan trọng sinh thái của chúng.","audioKind":"ex2"}],"collocations":[{"en":"be mistaken about","vi":"nhầm lẫn về"},{"en":"mistaken belief","vi":"quan điểm sai lầm"},{"en":"mistaken identity","vi":"nhận dạng nhầm"},{"en":"if I am not mistaken","vi":"nếu tôi không nhầm"}],"wordFamily":["mistake (n.)","mistake (v.)","mistakenly (adv.)"],"synonyms":["wrong","incorrect"],"antonyms":["correct","right"],"tipVi":"Nhân vật làm chủ ngữ thường dùng be mistaken about, diễn tả việc hiểu lầm hoặc nhầm lẫn về điều gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thinker', 'en-b2-35', 'thinker', '/ˈθɪŋkər/', 'B2', 'nhà tư tưởng; người có tư duy sâu sắc', 'n.', 'think (v.), thinking (n.), thought (n.), thoughtful (adj.)', NULL, 'thinker chỉ con người; thinking chỉ quá trình suy nghĩ hoặc lối tư duy.', 'My grandfather is a quiet thinker who enjoys difficult questions.', NULL, 'Ông nội tôi là một người trầm tính, thích suy ngẫm và hứng thú với những câu hỏi hóc búa.', '{"wordId":"thinker","ukIpa":"/ˈθɪŋkə/","usIpa":"/ˈθɪŋkər/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"someone who thinks deeply or develops important ideas","vi":"nhà tư tưởng; người có tư duy sâu sắc"}],"examples":[{"en":"My grandfather is a quiet thinker who enjoys difficult questions.","vi":"Ông nội tôi là một người trầm tính, thích suy ngẫm và hứng thú với những câu hỏi hóc búa.","audioKind":"ex"},{"en":"Education should encourage students to become independent thinkers rather than simply accept established ideas without question.","vi":"Giáo dục nên khích lệ học sinh trở thành những người có tư duy độc lập thay vì chỉ tiếp nhận thụ động các quan niệm đã có sẵn.","audioKind":"ex2"}],"collocations":[{"en":"independent thinker","vi":"người tư duy độc lập"},{"en":"critical thinker","vi":"nhà tư duy phản biện"},{"en":"influential thinker","vi":"nhà tư tưởng có tầm ảnh hưởng"},{"en":"original thinker","vi":"nhà tư tưởng có tính nguyên bản"}],"wordFamily":["think (v.)","thinking (n.)","thought (n.)","thoughtful (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"thinker chỉ con người; thinking chỉ quá trình suy nghĩ hoặc lối tư duy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_predictable', 'en-b2-35', 'predictable', '/prɪˈdɪktəbəl/', 'B2', 'có thể đoán trước; dự đoán được; dễ đoán; nhàm chán', 'adj.', 'predict (v.), prediction (n.), predictability (n.), predictably (adv.)', 'Đồng nghĩa: foreseeable, expected · Trái nghĩa: unpredictable', 'Có thể mang nghĩa trung lập chỉ sự việc có thể lường trước, hoặc mang nghĩa chê bai chỉ cốt truyện sáo mòn.', 'The film''s predictable ending made us laugh rather than cry.', NULL, 'Cái kết dễ đoán của bộ phim khiến chúng tôi chỉ muốn bật cười thay vì xúc động.', '{"wordId":"predictable","ukIpa":"/prɪˈdɪktəbəl/","usIpa":"/prɪˈdɪktəbəl/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Happening or behaving in a way that can be expected.","vi":"có thể đoán trước; dự đoán được"},{"pos":"adj.","en":"Boring because nothing surprising or original happens.","vi":"dễ đoán; nhàm chán"}],"examples":[{"en":"The film''s predictable ending made us laugh rather than cry.","vi":"Cái kết dễ đoán của bộ phim khiến chúng tôi chỉ muốn bật cười thay vì xúc động.","audioKind":"ex"},{"en":"A predictable income helps families plan their spending and reduces the stress associated with financial uncertainty.","vi":"Nguồn thu nhập ổn định giúp các gia đình chủ động hoạch định chi tiêu và giảm bớt áp lực từ những bất ổn tài chính.","audioKind":"ex2"}],"collocations":[{"en":"predictable outcome","vi":"kết quả có thể đoán trước"},{"en":"predictable pattern","vi":"mô hình có thể dự đoán"},{"en":"highly predictable","vi":"rất dễ đoán"}],"wordFamily":["predict (v.)","prediction (n.)","predictability (n.)","predictably (adv.)"],"synonyms":["foreseeable","expected"],"antonyms":["unpredictable"],"tipVi":"Có thể mang nghĩa trung lập chỉ sự việc có thể lường trước, hoặc mang nghĩa chê bai chỉ cốt truyện sáo mòn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fate', 'en-b2-35', 'fate', '/feɪt/', 'B2', 'số mệnh; định mệnh; số phận; cục diện; kết cục', 'n.', 'fated (adj.), fateful (adj.)', 'Đồng nghĩa: destiny', 'Thường là danh từ không đếm được khi mang nghĩa thiên mệnh; a terrible fate dùng để chỉ một kết cục bi thảm.', 'It felt like fate when we met again.', NULL, 'Cảm giác giống như định mệnh khi chúng tôi gặp lại nhau.', '{"wordId":"fate","ukIpa":"/feɪt/","usIpa":"/feɪt/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"a power believed to control what happens in people''s lives","vi":"số mệnh; định mệnh"},{"pos":"n.","en":"what eventually happens to someone or something, often something bad","vi":"số phận; cục diện; kết cục"}],"examples":[{"en":"It felt like fate when we met again.","vi":"Cảm giác giống như định mệnh khi chúng tôi gặp lại nhau.","audioKind":"ex"},{"en":"The fate of many endangered species depends on whether governments protect their habitats from further destruction.","vi":"Số phận của nhiều loài nguy cấp phụ thuộc vào việc các chính phủ có bảo vệ môi trường sống của chúng khỏi sự tàn phá tiếp theo hay không.","audioKind":"ex2"}],"collocations":[{"en":"leave something to fate","vi":"phó mặc cho số phận"},{"en":"seal someone''s fate","vi":"định đoạt số phận của ai"},{"en":"suffer the same fate","vi":"chịu chung số phận"}],"wordFamily":["fated (adj.)","fateful (adj.)"],"synonyms":["destiny"],"antonyms":[],"tipVi":"Thường là danh từ không đếm được khi mang nghĩa thiên mệnh; a terrible fate dùng để chỉ một kết cục bi thảm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_preference', 'en-b2-35', 'preference', '/ˈprefrəns/', 'B2', 'sự ưu tiên; sở thích; sự thiên về; quyền ưu tiên; sự ưu đãi', 'n.', 'prefer (v.), preferable (adj.), preferably (adv.), preferential (adj.)', 'Đồng nghĩa: liking', 'Sự ưa thích đối với cái gì dùng ''preference for'', không dùng ''to''.', 'My preference is tea, but coffee is fine too.', NULL, 'Sở thích của tôi là trà, nhưng uống cà phê cũng được.', '{"wordId":"preference","ukIpa":"/ˈprefrəns/","usIpa":"/ˈprefrəns/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"a greater liking for one thing than for another","vi":"sự ưu tiên; sở thích; sự thiên về"},{"pos":"n.","en":"an advantage given to someone or something over others","vi":"quyền ưu tiên; sự ưu đãi"}],"examples":[{"en":"My preference is tea, but coffee is fine too.","vi":"Sở thích của tôi là trà, nhưng uống cà phê cũng được.","audioKind":"ex"},{"en":"Consumer preference for locally grown food can encourage sustainable farming and reduce transport emissions.","vi":"Sự ưa chuộng của người tiêu dùng đối với thực phẩm trồng tại địa phương có thể thúc đẩy nền nông nghiệp bền vững và giảm lượng khí thải do vận chuyển.","audioKind":"ex2"}],"collocations":[{"en":"a preference for","vi":"sự ưa thích đối với"},{"en":"personal preference","vi":"sở thích cá nhân"},{"en":"give preference to","vi":"ưu tiên cho"},{"en":"in preference to","vi":"thay vì; ưu tiên hơn"}],"wordFamily":["prefer (v.)","preferable (adj.)","preferably (adv.)","preferential (adj.)"],"synonyms":["liking"],"antonyms":[],"tipVi":"Sự ưa thích đối với cái gì dùng ''preference for'', không dùng ''to''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_trait', 'en-b2-35', 'trait', '/treɪt/', 'B2', 'đặc điểm; nét tiêu biểu; phẩm chất', 'n.', NULL, 'Đồng nghĩa: characteristic, attribute', 'trait là danh từ đếm được, thường chỉ đặc điểm tính cách hoặc di truyền.', 'Patience is the trait I admire most in my sister.', NULL, 'Sự kiên nhẫn là phẩm chất ở chị tôi mà tôi ngưỡng mộ nhất.', '{"wordId":"trait","ukIpa":"/treɪt/","usIpa":"/treɪt/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"A particular quality in someone''s character or an organism''s nature.","vi":"đặc điểm; nét tiêu biểu; phẩm chất"}],"examples":[{"en":"Patience is the trait I admire most in my sister.","vi":"Sự kiên nhẫn là phẩm chất ở chị tôi mà tôi ngưỡng mộ nhất.","audioKind":"ex"},{"en":"Although some personality traits are inherited, social experiences also influence how individuals behave in different situations.","vi":"Mặc dù một số nét tính cách là do di truyền, nhưng các trải nghiệm xã hội cũng ảnh hưởng đến cách cá nhân hành xử trong các tình huống khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"personality trait","vi":"nét tính cách"},{"en":"inherited trait","vi":"đặc điểm di truyền"},{"en":"distinctive trait","vi":"đặc điểm riêng biệt"}],"wordFamily":[],"synonyms":["characteristic","attribute"],"antonyms":[],"tipVi":"trait là danh từ đếm được, thường chỉ đặc điểm tính cách hoặc di truyền.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_motto', 'en-b2-35', 'motto', '/ˈmɑːtoʊ/', 'B2', 'châm ngôn; phương châm; khẩu hiệu', 'n.', NULL, 'Đồng nghĩa: maxim', 'motto nhấn mạnh niềm tin chỉ đạo; slogan thường dùng hơn cho khẩu hiệu quảng cáo.', 'My grandmother''s motto was always to help others first.', NULL, 'Phương châm của bà tôi luôn là đặt việc giúp đỡ người khác lên hàng đầu.', '{"wordId":"motto","ukIpa":"/ˈmɒtəʊ/","usIpa":"/ˈmɑːtoʊ/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"A short phrase expressing someone''s guiding belief or purpose.","vi":"châm ngôn; phương châm; khẩu hiệu"}],"examples":[{"en":"My grandmother''s motto was always to help others first.","vi":"Phương châm của bà tôi luôn là đặt việc giúp đỡ người khác lên hàng đầu.","audioKind":"ex"},{"en":"A school''s motto can express shared values, but daily teaching practices must also reflect those principles.","vi":"Khẩu hiệu của một ngôi trường có thể thể hiện các giá trị chung, nhưng các hoạt động giảng dạy hàng ngày cũng phải phản ánh những nguyên tắc đó.","audioKind":"ex2"}],"collocations":[{"en":"a personal motto","vi":"phương châm cá nhân"},{"en":"a school motto","vi":"khẩu hiệu nhà trường"},{"en":"adopt a motto","vi":"áp dụng một câu châm ngôn"}],"wordFamily":[],"synonyms":["maxim"],"antonyms":[],"tipVi":"motto nhấn mạnh niềm tin chỉ đạo; slogan thường dùng hơn cho khẩu hiệu quảng cáo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_uncertainty', 'en-b2-35', 'uncertainty', '/ʌnˈsɝːtnti/', 'B2', 'sự không chắc chắn; sự bấp bênh; yếu tố bất định; điều chưa biết', 'n.', 'uncertain (adj.), certain (adj.), certainty (n.)', 'Đồng nghĩa: doubt · Trái nghĩa: certainty', 'Khi chỉ trạng thái không chắc chắn nói chung thường dùng dạng không đếm được; khi chỉ các yếu tố cụ thể chưa biết có thể dùng số nhiều.', 'The delayed flight left us facing hours of uncertainty.', NULL, 'Chuyến bay bị hoãn khiến chúng tôi phải đối mặt với nhiều giờ chờ đợi trong tâm trạng bất an.', '{"wordId":"uncertainty","ukIpa":"/ʌnˈsɜːtnti/","usIpa":"/ʌnˈsɝːtnti/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"a state of not knowing what is true or will happen","vi":"sự không chắc chắn; sự bấp bênh"},{"pos":"n.","en":"something that is unknown or cannot be predicted","vi":"yếu tố bất định; điều chưa biết"}],"examples":[{"en":"The delayed flight left us facing hours of uncertainty.","vi":"Chuyến bay bị hoãn khiến chúng tôi phải đối mặt với nhiều giờ chờ đợi trong tâm trạng bất an.","audioKind":"ex"},{"en":"Economic uncertainty can discourage businesses from investing in new equipment or hiring additional staff.","vi":"Sự bất ổn kinh tế có thể khiến các doanh nghiệp ngần ngại đầu tư vào thiết bị mới hoặc tuyển thêm nhân viên.","audioKind":"ex2"}],"collocations":[{"en":"economic uncertainty","vi":"sự bất ổn kinh tế"},{"en":"a period of uncertainty","vi":"một giai đoạn bất ổn"},{"en":"reduce uncertainty","vi":"giảm thiểu sự bất ổn"},{"en":"uncertainty about the future","vi":"sự không chắc chắn về tương lai"}],"wordFamily":["uncertain (adj.)","certain (adj.)","certainty (n.)"],"synonyms":["doubt"],"antonyms":["certainty"],"tipVi":"Khi chỉ trạng thái không chắc chắn nói chung thường dùng dạng không đếm được; khi chỉ các yếu tố cụ thể chưa biết có thể dùng số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_downside', 'en-b2-35', 'downside', '/ˈdaʊnsaɪd/', 'B2', 'mặt hạn chế; điểm bất lợi', 'n.', NULL, 'Đồng nghĩa: disadvantage, drawback · Trái nghĩa: upside, advantage', 'Thường đi với cấu trúc the downside of/to sth để chỉ ra điểm bất lợi của một việc nào đó.', 'The only downside of this flat is the noise.', NULL, 'Điểm bất lợi duy nhất của căn hộ này là tiếng ồn.', '{"wordId":"downside","ukIpa":"/ˈdaʊnsaɪd/","usIpa":"/ˈdaʊnsaɪd/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"a disadvantage or negative aspect of something","vi":"mặt hạn chế; điểm bất lợi"}],"examples":[{"en":"The only downside of this flat is the noise.","vi":"Điểm bất lợi duy nhất của căn hộ này là tiếng ồn.","audioKind":"ex"},{"en":"One downside of remote working is that employees may have fewer opportunities to build strong professional relationships.","vi":"Một mặt hạn chế của việc làm việc từ xa là nhân viên có thể có ít cơ hội hơn để xây dựng các mối quan hệ nghề nghiệp vững chắc.","audioKind":"ex2"}],"collocations":[{"en":"the downside of","vi":"mặt trái của"},{"en":"a potential downside","vi":"một bất lợi tiềm ẩn"},{"en":"on the downside","vi":"nhìn từ mặt hạn chế"}],"wordFamily":[],"synonyms":["disadvantage","drawback"],"antonyms":["upside","advantage"],"tipVi":"Thường đi với cấu trúc the downside of/to sth để chỉ ra điểm bất lợi của một việc nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_madness', 'en-b2-35', 'madness', '/ˈmædnəs/', 'B2', 'sự điên rồ; hành vi cực kỳ ng U dốt và nguy hiểm; tình trạng tâm thần bất ổn nghiêm trọng', 'n.', 'mad (adj.), madly (adv.), madden (v.)', 'Đồng nghĩa: insanity, folly · Trái nghĩa: sanity', 'Cách dùng chỉ bệnh tâm thần đã lỗi thời và có thể gây xúc phạm, nên tránh dùng cho việc chẩn đoán y khoa.', 'Driving through this thick fog would be absolute madness.', NULL, 'Lái xe trong màn sương mù dày đặc này thì đích thị là hành động liều mạng.', '{"wordId":"madness","ukIpa":"/ˈmædnəs/","usIpa":"/ˈmædnəs/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"Extremely foolish, unreasonable, or dangerous behaviour.","vi":"sự điên rồ; hành vi cực kỳ ng U dốt và nguy hiểm"},{"pos":"n.","en":"An old-fashioned term for severe mental illness.","vi":"tình trạng tâm thần bất ổn nghiêm trọng"}],"examples":[{"en":"Driving through this thick fog would be absolute madness.","vi":"Lái xe trong màn sương mù dày đặc này thì đích thị là hành động liều mạng.","audioKind":"ex"},{"en":"Critics described the destruction of healthy forests for temporary economic gains as environmental madness.","vi":"Các nhà phê bình mô tả việc phá hủy những khu rừng khỏe mạnh để đổi lấy lợi ích kinh tế ngắn hạn là một hành động điên rồ về mặt môi trường.","audioKind":"ex2"}],"collocations":[{"en":"absolute madness","vi":"hoàn toàn điên rồ"},{"en":"sheer madness","vi":"sự dại dột tột cùng"},{"en":"a moment of madness","vi":"một phút chốc bốc đồng"}],"wordFamily":["mad (adj.)","madly (adv.)","madden (v.)"],"synonyms":["insanity","folly"],"antonyms":["sanity"],"tipVi":"Cách dùng chỉ bệnh tâm thần đã lỗi thời và có thể gây xúc phạm, nên tránh dùng cho việc chẩn đoán y khoa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unaware', 'en-b2-35', 'unaware', '/ˌʌnəˈwer/', 'B2', 'không biết; không nhận thức được', 'adj.', 'aware (adj.), awareness (n.), unawareness (n.)', 'Đồng nghĩa: oblivious · Trái nghĩa: aware', 'Thường dùng cấu trúc be unaware of hoặc be unaware that với mệnh đề.', 'I was unaware that my umbrella was still outside.', NULL, 'Tôi không hề biết chiếc ô của mình vẫn còn ở bên ngoài.', '{"wordId":"unaware","ukIpa":"/ˌʌnəˈweə/","usIpa":"/ˌʌnəˈwer/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Not knowing or noticing that something exists or is happening.","vi":"không biết; không nhận thức được"}],"examples":[{"en":"I was unaware that my umbrella was still outside.","vi":"Tôi không hề biết chiếc ô của mình vẫn còn ở bên ngoài.","audioKind":"ex"},{"en":"Many consumers remain unaware of the environmental damage caused by the production of cheap clothing.","vi":"Nhiều người tiêu dùng vẫn chưa nhận thức được những tổn hại môi trường do việc sản xuất quần áo giá rẻ gây ra.","audioKind":"ex2"}],"collocations":[{"en":"unaware of","vi":"không biết về"},{"en":"completely unaware","vi":"hoàn toàn không hay biết"},{"en":"remain unaware","vi":"vẫn không hề hay biết"}],"wordFamily":["aware (adj.)","awareness (n.)","unawareness (n.)"],"synonyms":["oblivious"],"antonyms":["aware"],"tipVi":"Thường dùng cấu trúc be unaware of hoặc be unaware that với mệnh đề.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_attribute', 'en-b2-35', 'attribute', '/əˈtrɪbjuːt/', 'B2', 'quy cho; quy nguyên nhân; đổ cho; thuộc tính; đặc tính; đặc điểm', 'v.', 'attribution (n.), attributable (adj.)', 'Đồng nghĩa: ascribe, quality', 'Cấu trúc attribute A to B nghĩa là quy A cho B; danh từ đọc trọng âm ở âm tiết đầu tiên.', 'She attributes her good health to daily walks.', NULL, 'Cô ấy cho rằng sức khỏe tốt của mình là nhờ đi bộ mỗi ngày.', '{"wordId":"attribute","ukIpa":"/əˈtrɪbjuːt/","usIpa":"/əˈtrɪbjuːt/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"To regard something as caused or created by someone or something.","vi":"quy cho; quy nguyên nhân; đổ cho"},{"pos":"n.","en":"A quality or feature of a person or thing.","vi":"thuộc tính; đặc tính; đặc điểm"}],"examples":[{"en":"She attributes her good health to daily walks.","vi":"Cô ấy cho rằng sức khỏe tốt của mình là nhờ đi bộ mỗi ngày.","audioKind":"ex"},{"en":"Researchers attribute the decline in local air pollution to stricter controls on industrial emissions.","vi":"Các nhà nghiên cứu quy việc giảm ô nhiễm không khí cục bộ là nhờ các biện pháp kiểm soát khí thải công nghiệp nghiêm ngặt hơn.","audioKind":"ex2"}],"collocations":[{"en":"attribute success to","vi":"quy thành công cho"},{"en":"be attributed to","vi":"được quy cho là"},{"en":"a key attribute","vi":"một đặc điểm quan trọng"}],"wordFamily":["attribution (n.)","attributable (adj.)"],"synonyms":["ascribe","quality"],"antonyms":[],"tipVi":"Cấu trúc attribute A to B nghĩa là quy A cho B; danh từ đọc trọng âm ở âm tiết đầu tiên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_logic', 'en-b2-35', 'logic', '/ˈlɑːdʒɪk/', 'B2', 'lập luận; lý lẽ; logic; môn logic học', 'n.', 'logical (adj.), logically (adv.), illogical (adj.), logician (n.)', 'Đồng nghĩa: reasoning', 'Từ logic thường không đếm được; cụm từ the logic behind dùng để chỉ lý lẽ hoặc cơ sở đằng sau một việc gì đó.', 'I understand the logic behind your plan to save money.', NULL, 'Tôi hiểu cơ sở lập luận đằng sau kế hoạch tiết kiệm tiền của bạn.', '{"wordId":"logic","ukIpa":"/ˈlɒdʒɪk/","usIpa":"/ˈlɑːdʒɪk/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"Reasoning that connects ideas in a clear, consistent way.","vi":"lập luận; lý lẽ; logic"},{"pos":"n.","en":"The study of rules for reasoning correctly.","vi":"môn logic học"}],"examples":[{"en":"I understand the logic behind your plan to save money.","vi":"Tôi hiểu cơ sở lập luận đằng sau kế hoạch tiết kiệm tiền của bạn.","audioKind":"ex"},{"en":"The logic behind investing in public transport is that fewer cars can reduce urban congestion.","vi":"Lý lẽ đằng sau việc đầu tư vào giao thông công cộng là việc giảm bớt ô tô có thể làm giảm tình trạng ùn tắc đô thị.","audioKind":"ex2"}],"collocations":[{"en":"the logic behind something","vi":"logic đằng sau cái gì đó"},{"en":"sound logic","vi":"lập luận chặt chẽ"},{"en":"flawed logic","vi":"lập luận có lỗ hổng"},{"en":"formal logic","vi":"logic hình thức"}],"wordFamily":["logical (adj.)","logically (adv.)","illogical (adj.)","logician (n.)"],"synonyms":["reasoning"],"antonyms":[],"tipVi":"Từ logic thường không đếm được; cụm từ the logic behind dùng để chỉ lý lẽ hoặc cơ sở đằng sau một việc gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dimension', 'en-b2-35', 'dimension', '/daɪˈmenʃən/', 'B2', 'khía cạnh; phương diện; kích thước; khổ; chiều; không gian', 'n.', 'dimensional (adj.), multidimensional (adj.)', 'Đồng nghĩa: aspect, facet', 'Khi nói về các kích thước vật lý cụ thể như chiều dài hay chiều rộng, ta thường dùng dạng số nhiều "dimensions".', 'Cooking together added a new dimension to our friendship.', NULL, 'Việc cùng nhau nấu ăn đã mang lại một khía cạnh mới cho tình bạn của chúng tôi.', '{"wordId":"dimension","ukIpa":"/daɪˈmenʃən/","usIpa":"/daɪˈmenʃən/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"A particular aspect of a situation, problem, or experience.","vi":"khía cạnh; phương diện"},{"pos":"n.","en":"A measurement of something, such as its length or width.","vi":"kích thước; khổ"},{"pos":"n.","en":"An independent direction of measurement, such as length, width, or height.","vi":"chiều; không gian"}],"examples":[{"en":"Cooking together added a new dimension to our friendship.","vi":"Việc cùng nhau nấu ăn đã mang lại một khía cạnh mới cho tình bạn của chúng tôi.","audioKind":"ex"},{"en":"Urban planning has a social dimension, since the design of neighbourhoods can influence how frequently residents interact.","vi":"Quy hoạch đô thị mang tính chất xã hội, vì thiết kế của các khu dân cư có thể ảnh hưởng đến tần suất tương tác giữa các cư dân.","audioKind":"ex2"}],"collocations":[{"en":"a social dimension","vi":"khía cạnh xã hội"},{"en":"add a new dimension","vi":"thêm một khía cạnh mới"},{"en":"physical dimensions","vi":"kích thước thực tế"},{"en":"in three dimensions","vi":"theo không gian ba chiều"}],"wordFamily":["dimensional (adj.)","multidimensional (adj.)"],"synonyms":["aspect","facet"],"antonyms":[],"tipVi":"Khi nói về các kích thước vật lý cụ thể như chiều dài hay chiều rộng, ta thường dùng dạng số nhiều \"dimensions\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thus', 'en-b2-35', 'thus', '/ðʌs/', 'B2', 'do đó; vì vậy; từ đó; như thế; theo cách này', 'adv.', NULL, 'Đồng nghĩa: therefore, hence', '"thus" là một trạng từ, không thể dùng độc lập chỉ với một dấu phẩy để nối hai mệnh đề độc lập.', 'The road was flooded; thus, we took another route.', NULL, 'Con đường đã bị ngập nước; do đó, chúng tôi phải đi con đường khác.', '{"wordId":"thus","ukIpa":"/ðʌs/","usIpa":"/ðʌs/","cefr":"B2","topic":"thinking","senses":[{"pos":"adv.","en":"As a result of what has just been stated","vi":"do đó; vì vậy; từ đó"},{"pos":"adv.","en":"In this way","vi":"như thế; theo cách này"}],"examples":[{"en":"The road was flooded; thus, we took another route.","vi":"Con đường đã bị ngập nước; do đó, chúng tôi phải đi con đường khác.","audioKind":"ex"},{"en":"Improved public transport can reduce dependence on private cars, thus lowering emissions and easing urban congestion.","vi":"Việc cải thiện giao thông công cộng có thể giảm sự phụ thuộc vào ô tô cá nhân, từ đó làm giảm lượng khí thải và giảm bớt tình trạng ùn tắc giao thông đô thị.","audioKind":"ex2"}],"collocations":[{"en":"thus reducing costs","vi":"từ đó làm giảm chi phí"},{"en":"thus enabling","vi":"từ đó tạo điều kiện cho"},{"en":"thus far","vi":"cho đến nay"}],"wordFamily":[],"synonyms":["therefore","hence"],"antonyms":[],"tipVi":"\"thus\" là một trạng từ, không thể dùng độc lập chỉ với một dấu phẩy để nối hai mệnh đề độc lập.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_weakness', 'en-b2-35', 'weakness', '/ˈwiːknəs/', 'B2', 'điểm yếu; nhược điểm; sự suy yếu; sự mất sức; sự thích thú đặc biệt; niềm đam mê khó cưỡng', 'n.', 'weak (adj.), weaken (v.), weakly (adv.)', 'Đồng nghĩa: shortcoming, frailty · Trái nghĩa: strength', 'Điểm yếu thường đếm được; sự suy yếu thể chất không đếm được; sở thích đặc biệt dùng cấu trúc a weakness for.', 'My main weakness in cooking is getting the timing right.', NULL, 'Điểm yếu lớn nhất của tôi khi nấu ăn là canh thời gian chưa chuẩn.', '{"wordId":"weakness","ukIpa":"/ˈwiːknəs/","usIpa":"/ˈwiːknəs/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"a feature that makes someone or something less effective","vi":"điểm yếu; nhược điểm"},{"pos":"n.","en":"a lack of physical strength or energy","vi":"sự suy yếu; sự mất sức"},{"pos":"n.","en":"a strong liking that is difficult to resist","vi":"sự thích thú đặc biệt; niềm đam mê khó cưỡng"}],"examples":[{"en":"My main weakness in cooking is getting the timing right.","vi":"Điểm yếu lớn nhất của tôi khi nấu ăn là canh thời gian chưa chuẩn.","audioKind":"ex"},{"en":"The recent transport disruption exposed a serious weakness in the city''s emergency planning system.","vi":"Sự cố gián đoạn giao thông gần đây đã phơi bày một điểm yếu nghiêm trọng trong hệ thống lập kế hoạch khẩn cấp của thành phố.","audioKind":"ex2"}],"collocations":[{"en":"strengths and weaknesses","vi":"ưu điểm và nhược điểm"},{"en":"muscle weakness","vi":"sự yếu cơ"},{"en":"a weakness for chocolate","vi":"sự thích ăn sô-cô-la đến mức khó cưỡng"}],"wordFamily":["weak (adj.)","weaken (v.)","weakly (adv.)"],"synonyms":["shortcoming","frailty"],"antonyms":["strength"],"tipVi":"Điểm yếu thường đếm được; sự suy yếu thể chất không đếm được; sở thích đặc biệt dùng cấu trúc a weakness for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_remarkable', 'en-b2-35', 'remarkable', '/rɪˈmɑːrkəbl/', 'B2', 'đáng chú ý; phi thường; xuất sắc', 'adj.', 'remarkably (adv.), unremarkable (adj.)', 'Đồng nghĩa: extraordinary, notable, exceptional · Trái nghĩa: ordinary, unremarkable', 'Biểu thị sự đáng chú ý, thường mang ý nghĩa khen ngợi, nhưng không nhất thiết chỉ dùng cho điều tốt.', 'The injured bird made a remarkable recovery within weeks.', NULL, 'Con chim bị thương đã hồi phục một cách kỳ diệu chỉ trong vòng vài tuần.', '{"wordId":"remarkable","ukIpa":"/rɪˈmɑːkəbl/","usIpa":"/rɪˈmɑːrkəbl/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"unusual or impressive enough to deserve special attention","vi":"đáng chú ý; phi thường; xuất sắc"}],"examples":[{"en":"The injured bird made a remarkable recovery within weeks.","vi":"Con chim bị thương đã hồi phục một cách kỳ diệu chỉ trong vòng vài tuần.","audioKind":"ex"},{"en":"Recent advances in renewable energy demonstrate the remarkable potential of technology to reduce dependence on fossil fuels.","vi":"Những tiến bộ gần đây trong lĩnh vực năng lượng tái tạo cho thấy tiềm năng phi thường của công nghệ trong việc giảm sự phụ thuộc vào nhiên liệu hóa thạch.","audioKind":"ex2"}],"collocations":[{"en":"remarkable achievement","vi":"thành tựu phi thường"},{"en":"remarkable recovery","vi":"sự hồi phục kỳ diệu"},{"en":"remarkable progress","vi":"tiến bộ rõ rệt"},{"en":"remarkable ability","vi":"năng lực phi thường"}],"wordFamily":["remarkably (adv.)","unremarkable (adj.)"],"synonyms":["extraordinary","notable","exceptional"],"antonyms":["ordinary","unremarkable"],"tipVi":"Biểu thị sự đáng chú ý, thường mang ý nghĩa khen ngợi, nhưng không nhất thiết chỉ dùng cho điều tốt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_supposedly', 'en-b2-35', 'supposedly', '/səˈpoʊzɪdli/', 'B2', 'được cho là; theo như người ta nói', 'adv.', 'suppose (v.), supposed (adj.), supposition (n.)', 'Đồng nghĩa: allegedly, reportedly', 'Thường ngụ ý sự hoài nghi đối với thông tin được nghe, không có nghĩa là tự mình tưởng tượng ra.', 'This shortcut is supposedly quicker, but we keep getting lost.', NULL, 'Đường tắt này được cho là nhanh hơn, nhưng chúng tôi cứ mãi bị lạc.', '{"wordId":"supposedly","ukIpa":"/səˈpəʊzɪdli/","usIpa":"/səˈpoʊzɪdli/","cefr":"B2","topic":"thinking","senses":[{"pos":"adv.","en":"according to what people say, though it may be untrue","vi":"được cho là; theo như người ta nói"}],"examples":[{"en":"This shortcut is supposedly quicker, but we keep getting lost.","vi":"Đường tắt này được cho là nhanh hơn, nhưng chúng tôi cứ mãi bị lạc.","audioKind":"ex"},{"en":"Some supposedly environmentally friendly products still require substantial energy to manufacture and transport to consumers.","vi":"Một số sản phẩm được cho là thân thiện với môi trường vẫn đòi hỏi lượng năng lượng lớn để sản xuất và vận chuyển đến tay người tiêu dùng.","audioKind":"ex2"}],"collocations":[{"en":"supposedly true","vi":"được cho là đúng"},{"en":"supposedly harmless","vi":"được cho là vô hại"},{"en":"supposedly independent","vi":"được cho là độc lập"}],"wordFamily":["suppose (v.)","supposed (adj.)","supposition (n.)"],"synonyms":["allegedly","reportedly"],"antonyms":[],"tipVi":"Thường ngụ ý sự hoài nghi đối với thông tin được nghe, không có nghĩa là tự mình tưởng tượng ra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_strategy', 'en-b2-35', 'strategy', '/ˈstrætədʒi/', 'B2', 'chiến lược; kế hoạch hành động', 'n.', 'strategic (adj.), strategically (adv.), strategist (n.)', 'Đồng nghĩa: plan, approach', 'Thường dùng cấu trúc a strategy for doing sth để chỉ chiến lược làm việc gì đó.', 'Our strategy was to save a little every week.', NULL, 'Chiến lược của chúng tôi là mỗi tuần tiết kiệm một ít tiền.', '{"wordId":"strategy","ukIpa":"/ˈstrætədʒi/","usIpa":"/ˈstrætədʒi/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"a planned approach for achieving a particular goal","vi":"chiến lược; kế hoạch hành động"}],"examples":[{"en":"Our strategy was to save a little every week.","vi":"Chiến lược của chúng tôi là mỗi tuần tiết kiệm một ít tiền.","audioKind":"ex"},{"en":"An effective transport strategy should improve public services while reducing dependence on private cars.","vi":"Một chiến lược giao thông hiệu quả nên vừa cải thiện các dịch vụ công cộng vừa giảm sự phụ thuộc vào ô tô cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"develop a strategy","vi":"lên chiến lược"},{"en":"implement a strategy","vi":"thực thi chiến lược"},{"en":"long-term strategy","vi":"chiến lược dài hạn"},{"en":"a strategy for growth","vi":"chiến lược tăng trưởng"}],"wordFamily":["strategic (adj.)","strategically (adv.)","strategist (n.)"],"synonyms":["plan","approach"],"antonyms":[],"tipVi":"Thường dùng cấu trúc a strategy for doing sth để chỉ chiến lược làm việc gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tactics', 'en-b2-35', 'tactics', '/ˈtæktɪks/', 'B2', 'chiến thuật; thủ thuật; mưu kế', 'n.', 'tactic (n.), tactical (adj.), tactically (adv.), tactician (n.)', 'Đồng nghĩa: methods, manoeuvres', 'strategy thiên về chiến lược tổng thể, trong khi tactics thiên về thủ thuật và phương pháp cụ thể.', 'Our coach changed tactics halfway through the football match.', NULL, 'Huấn luyện viên của chúng tôi đã thay đổi chiến thuật khi trận bóng đá đi được nửa chặng đường.', '{"wordId":"tactics","ukIpa":"/ˈtæktɪks/","usIpa":"/ˈtæktɪks/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"Specific methods used to achieve a goal or gain an advantage.","vi":"chiến thuật; thủ thuật; mưu kế"}],"examples":[{"en":"Our coach changed tactics halfway through the football match.","vi":"Huấn luyện viên của chúng tôi đã thay đổi chiến thuật khi trận bóng đá đi được nửa chặng đường.","audioKind":"ex"},{"en":"Companies increasingly use digital marketing tactics to attract younger consumers and compete in crowded markets.","vi":"Các doanh nghiệp ngày càng áp dụng nhiều chiến thuật tiếp thị kỹ thuật số để thu hút người tiêu dùng trẻ tuổi và cạnh tranh trong những thị trường đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"change tactics","vi":"thay đổi chiến thuật"},{"en":"marketing tactics","vi":"chiến thuật tiếp thị"},{"en":"negotiating tactics","vi":"chiến thuật đàm phán"},{"en":"delaying tactics","vi":"thủ đoạn câu giờ"}],"wordFamily":["tactic (n.)","tactical (adj.)","tactically (adv.)","tactician (n.)"],"synonyms":["methods","manoeuvres"],"antonyms":[],"tipVi":"strategy thiên về chiến lược tổng thể, trong khi tactics thiên về thủ thuật và phương pháp cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_suspect', 'en-b2-35', 'suspect', '/səˈspekt/', 'B2', 'động từ: nghi ngờ; phỏng đoán; danh từ: kẻ tình nghi; đối tượng tình nghi; tính từ: đáng ngờ; không đáng tin cậy', 'v.', 'suspicion (n.), suspicious (adj.), suspiciously (adv.)', NULL, 'Động từ suspect có trọng âm rơi vào âm tiết thứ hai; khi là danh từ và tính từ, trọng âm rơi vào âm tiết đầu.', 'I suspect the cat knocked the cup off the table.', NULL, 'Tôi nghi ngờ chính con mèo đã làm rơi chiếc cốc khỏi bàn.', '{"wordId":"suspect","ukIpa":"/səˈspekt/","usIpa":"/səˈspekt/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"To think something is likely true without being certain.","vi":"động từ: nghi ngờ; phỏng đoán"},{"pos":"n.","en":"A person believed to have possibly committed a crime.","vi":"danh từ: kẻ tình nghi; đối tượng tình nghi"},{"pos":"adj.","en":"Not trustworthy or possibly wrong, unsafe, or dishonest.","vi":"tính từ: đáng ngờ; không đáng tin cậy"}],"examples":[{"en":"I suspect the cat knocked the cup off the table.","vi":"Tôi nghi ngờ chính con mèo đã làm rơi chiếc cốc khỏi bàn.","audioKind":"ex"},{"en":"Researchers suspect that prolonged screen use may affect sleep quality, although further evidence is needed.","vi":"Các nhà nghiên cứu phỏng đoán rằng việc tiếp xúc với màn hình trong thời gian dài có thể ảnh hưởng đến chất lượng giấc ngủ, mặc dù vẫn cần thêm bằng chứng.","audioKind":"ex2"}],"collocations":[{"en":"suspect that","vi":"nghi ngờ rằng"},{"en":"suspect someone of something","vi":"nghi ngờ ai đó làm gì"},{"en":"a prime suspect","vi":"kẻ tình nghi số một"},{"en":"suspect evidence","vi":"bằng chứng đáng ngờ"}],"wordFamily":["suspicion (n.)","suspicious (adj.)","suspiciously (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ suspect có trọng âm rơi vào âm tiết thứ hai; khi là danh từ và tính từ, trọng âm rơi vào âm tiết đầu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_evaluate', 'en-b2-35', 'evaluate', '/ɪˈvæljueɪt/', 'B2', 'đánh giá, thẩm định chất lượng, giá trị hoặc hiệu quả của cái gì', 'v.', 'evaluation (n.), evaluator (n.), evaluative (adj.)', 'Đồng nghĩa: assess, appraise', 'Nhấn mạnh việc đưa ra phán đoán dựa trên tiêu chuẩn, không chỉ là mô tả sự việc.', 'We evaluated three cameras before choosing one for our trip.', NULL, 'Chúng tôi đã đánh giá ba chiếc máy ảnh trước khi chọn một chiếc cho chuyến đi.', '{"wordId":"evaluate","ukIpa":"/ɪˈvæljueɪt/","usIpa":"/ɪˈvæljueɪt/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"Carefully judge the quality, value or effectiveness of something","vi":"đánh giá, thẩm định chất lượng, giá trị hoặc hiệu quả của cái gì"}],"examples":[{"en":"We evaluated three cameras before choosing one for our trip.","vi":"Chúng tôi đã đánh giá ba chiếc máy ảnh trước khi chọn một chiếc cho chuyến đi.","audioKind":"ex"},{"en":"Governments should evaluate the long-term environmental effects of major construction projects before approving them.","vi":"Chính phủ nên đánh giá tác động môi trường lâu dài của các dự án xây dựng lớn trước khi phê duyệt chúng.","audioKind":"ex2"}],"collocations":[{"en":"evaluate the impact","vi":"đánh giá tác động"},{"en":"evaluate effectiveness","vi":"đánh giá hiệu quả"},{"en":"evaluate performance","vi":"đánh giá hiệu suất"},{"en":"critically evaluate","vi":"đánh giá phản biện"}],"wordFamily":["evaluation (n.)","evaluator (n.)","evaluative (adj.)"],"synonyms":["assess","appraise"],"antonyms":[],"tipVi":"Nhấn mạnh việc đưa ra phán đoán dựa trên tiêu chuẩn, không chỉ là mô tả sự việc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_preceding', 'en-b2-35', 'preceding', '/prɪˈsiːdɪŋ/', 'B2', 'trước đó; ở phần trước', 'adj.', 'precede (v.), precedence (n.)', 'Đồng nghĩa: previous, prior · Trái nghĩa: following, subsequent', 'Preceding chỉ thời gian hoặc sự việc diễn ra trước thời điểm đang bàn tới, không đồng nghĩa với trước hiện tại.', 'I slept badly on the night preceding my interview.', NULL, 'Tôi đã ngủ rất kém vào đêm trước buổi phỏng vấn của mình.', '{"wordId":"preceding","ukIpa":"/prɪˈsiːdɪŋ/","usIpa":"/prɪˈsiːdɪŋ/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Happening or appearing before the thing being discussed.","vi":"trước đó; ở phần trước"}],"examples":[{"en":"I slept badly on the night preceding my interview.","vi":"Tôi đã ngủ rất kém vào đêm trước buổi phỏng vấn của mình.","audioKind":"ex"},{"en":"The survey revealed that household energy consumption had fallen significantly compared with the preceding year.","vi":"Cuộc khảo sát cho thấy mức tiêu thụ năng lượng của các hộ gia đình đã giảm đáng kể so với năm trước đó.","audioKind":"ex2"}],"collocations":[{"en":"the preceding year","vi":"năm trước"},{"en":"the preceding paragraph","vi":"đoạn văn trước"},{"en":"the immediately preceding period","vi":"giai đoạn ngay trước đó"}],"wordFamily":["precede (v.)","precedence (n.)"],"synonyms":["previous","prior"],"antonyms":["following","subsequent"],"tipVi":"Preceding chỉ thời gian hoặc sự việc diễn ra trước thời điểm đang bàn tới, không đồng nghĩa với trước hiện tại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_logical', 'en-b2-35', 'logical', '/ˈlɑːdʒɪkəl/', 'B2', 'hợp lý; logic; thuộc logic học', 'adj.', 'logic (n.), logically (adv.), illogical (adj.)', 'Đồng nghĩa: rational, reasonable · Trái nghĩa: illogical, irrational', 'Logical nhấn mạnh tính hợp lý trong suy luận, không đảm bảo rằng thực tế chắc chắn đúng.', 'Taking the bus seemed logical because parking was expensive.', NULL, 'Đi xe buýt có vẻ là một lựa chọn hợp lý vì phí gửi xe quá đắt.', '{"wordId":"logical","ukIpa":"/ˈlɒdʒɪkəl/","usIpa":"/ˈlɑːdʒɪkəl/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Based on clear reasoning, with ideas that fit together sensibly.","vi":"hợp lý; logic"},{"pos":"adj.","en":"Relating to the formal rules of correct reasoning.","vi":"thuộc logic học"}],"examples":[{"en":"Taking the bus seemed logical because parking was expensive.","vi":"Đi xe buýt có vẻ là một lựa chọn hợp lý vì phí gửi xe quá đắt.","audioKind":"ex"},{"en":"Students should learn to construct logical arguments rather than simply memorise facts for examinations.","vi":"Học sinh nên học cách xây dựng các lập luận logic thay vì chỉ đơn thuần học thuộc lòng các dữ kiện cho các kỳ thi.","audioKind":"ex2"}],"collocations":[{"en":"logical conclusion","vi":"kết luận hợp lý"},{"en":"logical reasoning","vi":"lập luận logic"},{"en":"logical sequence","vi":"trình tự logic"},{"en":"logical argument","vi":"lập luận chặt chẽ"}],"wordFamily":["logic (n.)","logically (adv.)","illogical (adj.)"],"synonyms":["rational","reasonable"],"antonyms":["illogical","irrational"],"tipVi":"Logical nhấn mạnh tính hợp lý trong suy luận, không đảm bảo rằng thực tế chắc chắn đúng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_attempt', 'en-b2-35', 'attempt', '/əˈtempt/', 'B2', 'sự cố gắng; nỗ lực; thử; cố gắng', 'n.', 'attempted (adj.)', 'Đồng nghĩa: try, endeavour', 'Động từ theo sau bởi to do; danh từ thường đi với cụm an attempt at doing.', 'My first attempt at baking bread was surprisingly successful.', NULL, 'Lần đầu tiên tôi thử làm bánh mì đã thành công một cách đáng ngạc nhiên.', '{"wordId":"attempt","ukIpa":"/əˈtempt/","usIpa":"/əˈtempt/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"An effort to do something, especially something difficult.","vi":"sự cố gắng; nỗ lực"},{"pos":"v.","en":"To try to do something, especially something difficult.","vi":"thử; cố gắng"}],"examples":[{"en":"My first attempt at baking bread was surprisingly successful.","vi":"Lần đầu tiên tôi thử làm bánh mì đã thành công một cách đáng ngạc nhiên.","audioKind":"ex"},{"en":"Many cities are attempting to reduce air pollution by improving public transport and expanding cycling networks.","vi":"Nhiều thành phố đang cố gắng giảm thiểu ô nhiễm không khí bằng cách cải thiện giao thông công cộng và mở rộng mạng lưới đường dành cho xe đạp.","audioKind":"ex2"}],"collocations":[{"en":"make an attempt","vi":"thực hiện nỗ lực"},{"en":"attempt to do something","vi":"cố gắng làm gì đó"},{"en":"a successful attempt","vi":"một nỗ lực thành công"},{"en":"in an attempt to","vi":"nhằm mục đích cố gắng"}],"wordFamily":["attempted (adj.)"],"synonyms":["try","endeavour"],"antonyms":[],"tipVi":"Động từ theo sau bởi to do; danh từ thường đi với cụm an attempt at doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_judgement', 'en-b2-35', 'judgement', '/ˈdʒʌdʒmənt/', 'B2', 'khả năng phán đoán; sự đánh giá; ý kiến; quan điểm; nhận định; phán quyết; quyết định của tòa án', 'n.', 'judge (v.), judgemental (adj.)', 'Đồng nghĩa: discernment, assessment', 'Tiếng Anh-Anh có thể viết là judgement hoặc judgment; tiếng Anh-Mỹ thường dùng judgment.', 'I trust your judgement when choosing a reliable bicycle.', NULL, 'Tôi tin tưởng khả năng phán đoán của bạn khi chọn mua một chiếc xe đạp đáng tin cậy.', '{"wordId":"judgement","ukIpa":"/ˈdʒʌdʒmənt/","usIpa":"/ˈdʒʌdʒmənt/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"the ability to make sensible decisions after considering information","vi":"khả năng phán đoán; sự đánh giá"},{"pos":"n.","en":"an opinion formed after considering something carefully","vi":"ý kiến; quan điểm; nhận định"},{"pos":"n.","en":"an official decision made by a court","vi":"phán quyết; quyết định của tòa án"}],"examples":[{"en":"I trust your judgement when choosing a reliable bicycle.","vi":"Tôi tin tưởng khả năng phán đoán của bạn khi chọn mua một chiếc xe đạp đáng tin cậy.","audioKind":"ex"},{"en":"Schools should teach students to exercise independent judgement when evaluating information from unfamiliar online sources.","vi":"Nhà trường nên dạy học sinh cách đưa ra phán quyết độc lập khi đánh giá thông tin từ các nguồn trực tuyến không quen thuộc.","audioKind":"ex2"}],"collocations":[{"en":"sound judgement","vi":"khả năng phán đoán sáng suốt"},{"en":"make a judgement","vi":"đưa ra phán quyết; đưa ra đánh giá"},{"en":"exercise judgement","vi":"sử dụng phán đoán"},{"en":"court judgement","vi":"phán quyết của tòa án"}],"wordFamily":["judge (v.)","judgemental (adj.)"],"synonyms":["discernment","assessment"],"antonyms":[],"tipVi":"Tiếng Anh-Anh có thể viết là judgement hoặc judgment; tiếng Anh-Mỹ thường dùng judgment.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_insane', 'en-b2-35', 'insane', '/ɪnˈseɪn/', 'B2', 'vô cùng ngốc nghếch; phi lý; nguy hiểm; mắc bệnh tâm thần nặng (thuật ngữ cũ, nay ít dùng trừ trong pháp lý)', 'adj.', 'insanity (n.), insanely (adv.), sane (adj.), sanity (n.)', 'Đồng nghĩa: irrational, absurd · Trái nghĩa: sane, sensible', 'Trong văn nói, từ này có thể chỉ sự hoang đường; việc dùng để chỉ bệnh tâm thần nay đã lỗi thời và có thể gây tổn thương.', 'Driving through that storm would be an insane risk.', NULL, 'Lái xe băng qua cơn bão đó sẽ là một canh bạc vô cùng nguy hiểm.', '{"wordId":"insane","ukIpa":"/ɪnˈseɪn/","usIpa":"/ɪnˈseɪn/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Extremely foolish, unreasonable, or dangerous.","vi":"vô cùng ngốc nghếch; phi lý; nguy hiểm"},{"pos":"adj.","en":"Severely mentally ill; an outdated term except in legal contexts.","vi":"mắc bệnh tâm thần nặng (thuật ngữ cũ, nay ít dùng trừ trong pháp lý)"}],"examples":[{"en":"Driving through that storm would be an insane risk.","vi":"Lái xe băng qua cơn bão đó sẽ là một canh bạc vô cùng nguy hiểm.","audioKind":"ex"},{"en":"Critics described the proposal as insane because its enormous costs would outweigh any potential benefits.","vi":"Các nhà phê bình gọi đề xuất này là hoàn toàn hoang đường vì chi phí khổng lồ của nó sẽ lấn át mọi lợi ích tiềm năng.","audioKind":"ex2"}],"collocations":[{"en":"an insane idea","vi":"một ý tưởng hoang đường"},{"en":"an insane risk","vi":"một canh bạc liều lĩnh"},{"en":"drive someone insane","vi":"làm ai đó phát điên"}],"wordFamily":["insanity (n.)","insanely (adv.)","sane (adj.)","sanity (n.)"],"synonyms":["irrational","absurd"],"antonyms":["sane","sensible"],"tipVi":"Trong văn nói, từ này có thể chỉ sự hoang đường; việc dùng để chỉ bệnh tâm thần nay đã lỗi thời và có thể gây tổn thương.","noteVi":"Tránh dùng từ này để miêu tả người mắc bệnh tâm thần vì có thể gây xúc phạm.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 28, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_35_1', 'en-b2-35', 'Cách dùng “uncertainty” (n.) — sự không chắc chắn; sự bấp bênh', 'economic uncertainty  ·  a period of uncertainty  ·  reduce uncertainty', 'Khi chỉ trạng thái không chắc chắn nói chung thường dùng dạng không đếm được; khi chỉ các yếu tố cụ thể chưa biết có thể dùng số nhiều.', 'Họ từ (Word Family): uncertain (adj.), certain (adj.), certainty (n.) | Đồng nghĩa: doubt · Trái nghĩa: certainty', '[{"hanzi":"The delayed flight left us facing hours of uncertainty.","pinyin":"","meaning":"Chuyến bay bị hoãn khiến chúng tôi phải đối mặt với nhiều giờ chờ đợi trong tâm trạng bất an."},{"hanzi":"Economic uncertainty can discourage businesses from investing in new equipment or hiring additional staff.","pinyin":"","meaning":"Sự bất ổn kinh tế có thể khiến các doanh nghiệp ngần ngại đầu tư vào thiết bị mới hoặc tuyển thêm nhân viên."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_35_2', 'en-b2-35', 'Cách dùng “insane” (adj.) — vô cùng ngốc nghếch; phi lý; nguy hiểm', 'an insane idea  ·  an insane risk  ·  drive someone insane', 'Trong văn nói, từ này có thể chỉ sự hoang đường; việc dùng để chỉ bệnh tâm thần nay đã lỗi thời và có thể gây tổn thương.', 'Họ từ (Word Family): insanity (n.), insanely (adv.), sane (adj.), sanity (n.) | Đồng nghĩa: irrational, absurd · Trái nghĩa: sane, sensible', '[{"hanzi":"Driving through that storm would be an insane risk.","pinyin":"","meaning":"Lái xe băng qua cơn bão đó sẽ là một canh bạc vô cùng nguy hiểm."},{"hanzi":"Critics described the proposal as insane because its enormous costs would outweigh any potential benefits.","pinyin":"","meaning":"Các nhà phê bình gọi đề xuất này là hoàn toàn hoang đường vì chi phí khổng lồ của nó sẽ lấn át mọi lợi ích tiềm năng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_35_3', 'en-b2-35', 'Cách dùng “dimension” (n.) — khía cạnh; phương diện', 'a social dimension  ·  add a new dimension  ·  physical dimensions', 'Khi nói về các kích thước vật lý cụ thể như chiều dài hay chiều rộng, ta thường dùng dạng số nhiều "dimensions".', 'Họ từ (Word Family): dimensional (adj.), multidimensional (adj.) | Đồng nghĩa: aspect, facet', '[{"hanzi":"Cooking together added a new dimension to our friendship.","pinyin":"","meaning":"Việc cùng nhau nấu ăn đã mang lại một khía cạnh mới cho tình bạn của chúng tôi."},{"hanzi":"Urban planning has a social dimension, since the design of neighbourhoods can influence how frequently residents interact.","pinyin":"","meaning":"Quy hoạch đô thị mang tính chất xã hội, vì thiết kế của các khu dân cư có thể ảnh hưởng đến tần suất tương tác giữa các cư dân."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_35_4', 'en-b2-35', 'Cách dùng “preceding” (adj.) — trước đó; ở phần trước', 'the preceding year  ·  the preceding paragraph  ·  the immediately preceding period', 'Preceding chỉ thời gian hoặc sự việc diễn ra trước thời điểm đang bàn tới, không đồng nghĩa với trước hiện tại.', 'Họ từ (Word Family): precede (v.), precedence (n.) | Đồng nghĩa: previous, prior · Trái nghĩa: following, subsequent', '[{"hanzi":"I slept badly on the night preceding my interview.","pinyin":"","meaning":"Tôi đã ngủ rất kém vào đêm trước buổi phỏng vấn của mình."},{"hanzi":"The survey revealed that household energy consumption had fallen significantly compared with the preceding year.","pinyin":"","meaning":"Cuộc khảo sát cho thấy mức tiêu thụ năng lượng của các hộ gia đình đã giảm đáng kể so với năm trước đó."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_35_1', 'en-b2-35', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_35_1_1', 'ten_b2_35_1', 'speculate', 'We can only speculate about what caused the delay.', 'We can only speculate about what caused the delay.', '/ˈspekjəleɪt/', 'Chúng ta chỉ có thể phỏng đoán về nguyên nhân gây ra sự chậm trễ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_35_1_2', 'ten_b2_35_1', 'mistaken', 'I was mistaken about the time of our appointment.', 'I was mistaken about the time of our appointment.', '/mɪˈsteɪkən/', 'Tôi đã nhầm về thời gian cuộc hẹn của chúng tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_35_1_3', 'ten_b2_35_1', 'thinker', 'My grandfather is a quiet thinker who enjoys difficult questions.', 'My grandfather is a quiet thinker who enjoys difficult questions.', '/ˈθɪŋkər/', 'Ông nội tôi là một người trầm tính, thích suy ngẫm và hứng thú với những câu hỏi hóc búa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_35_1_4', 'ten_b2_35_1', 'predictable', 'The film''s predictable ending made us laugh rather than cry.', 'The film''s predictable ending made us laugh rather than cry.', '/prɪˈdɪktəbəl/', 'Cái kết dễ đoán của bộ phim khiến chúng tôi chỉ muốn bật cười thay vì xúc động.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_35_1_5', 'ten_b2_35_1', 'fate', 'It felt like fate when we met again.', 'It felt like fate when we met again.', '/feɪt/', 'Cảm giác giống như định mệnh khi chúng tôi gặp lại nhau.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_35_1_6', 'ten_b2_35_1', 'preference', 'My preference is tea, but coffee is fine too.', 'My preference is tea, but coffee is fine too.', '/ˈprefrəns/', 'Sở thích của tôi là trà, nhưng uống cà phê cũng được.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_35_1_7', 'ten_b2_35_1', 'trait', 'Patience is the trait I admire most in my sister.', 'Patience is the trait I admire most in my sister.', '/treɪt/', 'Sự kiên nhẫn là phẩm chất ở chị tôi mà tôi ngưỡng mộ nhất.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_35_1_8', 'ten_b2_35_1', 'motto', 'My grandmother''s motto was always to help others first.', 'My grandmother''s motto was always to help others first.', '/ˈmɑːtoʊ/', 'Phương châm của bà tôi luôn là đặt việc giúp đỡ người khác lên hàng đầu.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_35_1_1', 'en-b2-35', 'ten_b2_35_1', 'listening', 'listening', 'We can only speculate about what caused the delay.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Lần đầu tiên tôi thử làm bánh mì đã thành công một cách đáng ngạc nhiên.","Chúng ta chỉ có thể phỏng đoán về nguyên nhân gây ra sự chậm trễ.","Đường tắt này được cho là nhanh hơn, nhưng chúng tôi cứ mãi bị lạc.","Chiến lược của chúng tôi là mỗi tuần tiết kiệm một ít tiền."]'::jsonb, 1, 'We can only speculate about what caused the delay. → Chúng ta chỉ có thể phỏng đoán về nguyên nhân gây ra sự chậm trễ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_35_1_2', 'en-b2-35', 'ten_b2_35_1', 'listening', 'listening', 'I was mistaken about the time of our appointment.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi đã nhầm về thời gian cuộc hẹn của chúng tôi.","Tôi nghi ngờ chính con mèo đã làm rơi chiếc cốc khỏi bàn.","Chuyến bay bị hoãn khiến chúng tôi phải đối mặt với nhiều giờ chờ đợi trong tâm trạng bất an.","Tôi tin tưởng khả năng phán đoán của bạn khi chọn mua một chiếc xe đạp đáng tin cậy."]'::jsonb, 0, 'I was mistaken about the time of our appointment. → Tôi đã nhầm về thời gian cuộc hẹn của chúng tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_35_1_3', 'en-b2-35', 'ten_b2_35_1', 'listening', 'listening', 'My grandfather is a quiet thinker who enjoys difficult questions.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chuyến bay bị hoãn khiến chúng tôi phải đối mặt với nhiều giờ chờ đợi trong tâm trạng bất an.","Ông nội tôi là một người trầm tính, thích suy ngẫm và hứng thú với những câu hỏi hóc búa.","Tôi không hề biết chiếc ô của mình vẫn còn ở bên ngoài.","Tôi nghi ngờ chính con mèo đã làm rơi chiếc cốc khỏi bàn."]'::jsonb, 1, 'My grandfather is a quiet thinker who enjoys difficult questions. → Ông nội tôi là một người trầm tính, thích suy ngẫm và hứng thú với những câu hỏi hóc búa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_35_2', 'en-b2-35', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_35_2_1', 'ten_b2_35_2', 'speculate', 'Researchers speculate that changing work patterns could reduce traffic congestion in major urban centres.', 'Researchers speculate that changing work patterns could reduce traffic congestion in major urban centres.', '/ˈspekjəleɪt/', 'Các nhà nghiên cứu phỏng đoán rằng việc thay đổi mô hình làm việc có thể giảm ùn tắc giao thông ở các trung tâm đô thị lớn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_35_2_2', 'ten_b2_35_2', 'mistaken', 'The mistaken belief that all bacteria are harmful can prevent people from understanding their ecological importance.', 'The mistaken belief that all bacteria are harmful can prevent people from understanding their ecological importance.', '/mɪˈsteɪkən/', 'Quan điểm sai lầm rằng tất cả vi khuẩn đều có hại có thể ngăn cản mọi người hiểu rõ tầm quan trọng sinh thái của chúng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_35_2_3', 'ten_b2_35_2', 'thinker', 'Education should encourage students to become independent thinkers rather than simply accept established ideas without question.', 'Education should encourage students to become independent thinkers rather than simply accept established ideas without question.', '/ˈθɪŋkər/', 'Giáo dục nên khích lệ học sinh trở thành những người có tư duy độc lập thay vì chỉ tiếp nhận thụ động các quan niệm đã có sẵn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_35_2_4', 'ten_b2_35_2', 'predictable', 'A predictable income helps families plan their spending and reduces the stress associated with financial uncertainty.', 'A predictable income helps families plan their spending and reduces the stress associated with financial uncertainty.', '/prɪˈdɪktəbəl/', 'Nguồn thu nhập ổn định giúp các gia đình chủ động hoạch định chi tiêu và giảm bớt áp lực từ những bất ổn tài chính.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_35_2_5', 'ten_b2_35_2', 'fate', 'The fate of many endangered species depends on whether governments protect their habitats from further destruction.', 'The fate of many endangered species depends on whether governments protect their habitats from further destruction.', '/feɪt/', 'Số phận của nhiều loài nguy cấp phụ thuộc vào việc các chính phủ có bảo vệ môi trường sống của chúng khỏi sự tàn phá tiếp theo hay không.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_35_2_6', 'ten_b2_35_2', 'preference', 'Consumer preference for locally grown food can encourage sustainable farming and reduce transport emissions.', 'Consumer preference for locally grown food can encourage sustainable farming and reduce transport emissions.', '/ˈprefrəns/', 'Sự ưa chuộng của người tiêu dùng đối với thực phẩm trồng tại địa phương có thể thúc đẩy nền nông nghiệp bền vững và giảm lượng khí thải do vận chuyển.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_35_2_1', 'en-b2-35', 'ten_b2_35_2', 'listening', 'listening', 'Researchers speculate that changing work patterns could reduce traffic congestion in major urban centres.', NULL, 'Trong câu vừa nghe, từ “speculate” mang nghĩa nào sau đây?', '["vết bầm tím; vết thâm","sự từ chối; sự bác bỏ","suy đoán; phỏng đoán","độ ẩm; hơi ẩm"]'::jsonb, 2, '“speculate” (/ˈspekjəleɪt/): suy đoán; phỏng đoán. Câu đầy đủ: Researchers speculate that changing work patterns could reduce traffic congestion in major urban centres.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_35_2_2', 'en-b2-35', 'ten_b2_35_2', 'listening', 'listening', 'The mistaken belief that all bacteria are harmful can prevent people from understanding their ecological importance.', NULL, 'Trong câu vừa nghe, từ “mistaken” mang nghĩa nào sau đây?', '["trừu tượng","sai lầm; hiểu lầm","dễ chịu; dễ mến; thú vị","cột mốc quan trọng; bước ngoặt"]'::jsonb, 1, '“mistaken” (/mɪˈsteɪkən/): sai lầm; hiểu lầm. Câu đầy đủ: The mistaken belief that all bacteria are harmful can prevent people from understanding their ecological importance.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
