INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_35_4', 'en-b2-35', 'The film''s predictable ending made us laugh rather than cry', 'Cái kết dễ đoán của bộ phim khiến chúng tôi chỉ muốn bật cười thay vì xúc động.', 'predictable /prɪˈdɪktəbəl/', '["us","laugh","made","than","The","predictable","rather","cry","film''s","ending"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_35_5', 'en-b2-35', 'It felt like fate when we met again', 'Cảm giác giống như định mệnh khi chúng tôi gặp lại nhau.', 'fate /feɪt/', '["met","fate","like","when","we","again","It","felt"]'::jsonb, NULL, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_35_6', 'en-b2-35', 'My preference is tea, but coffee is fine too', 'Sở thích của tôi là trà, nhưng uống cà phê cũng được.', 'preference /ˈprefrəns/', '["fine","tea","coffee","too","is","My","preference","is","but"]'::jsonb, NULL, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
