INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_35_8', 'en-b2-35', 'My grandmother''s motto was always to help others first', 'Phương châm của bà tôi luôn là đặt việc giúp đỡ người khác lên hàng đầu.', 'motto /ˈmɑːtoʊ/', '["first","always","grandmother''s","help","others","motto","was","My","to"]'::jsonb, NULL, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_35_9', 'en-b2-35', 'The delayed flight left us facing hours of uncertainty', 'Chuyến bay bị hoãn khiến chúng tôi phải đối mặt với nhiều giờ chờ đợi trong tâm trạng bất an.', 'uncertainty /ʌnˈsɝːtnti/', '["The","delayed","flight","of","left","us","hours","facing","uncertainty"]'::jsonb, NULL, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
