INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_35_1', 'en-b2-35', NULL, 'comprehensive_test', 'listening', 'speculate', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["suy đoán; phỏng đoán","nguyên tắc; phương châm sống","sân hiên; ban công lớn; sân thượng","sinh vật; con người"]'::jsonb, 0, 'speculate (/ˈspekjəleɪt/) → suy đoán; phỏng đoán; đầu cơ', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_35_2', 'en-b2-35', NULL, 'comprehensive_test', 'listening', 'I was mistaken about the time of our appointment.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Con đường đã bị ngập nước; do đó, chúng tôi phải đi con đường khác.","Tôi đã nhầm về thời gian cuộc hẹn của chúng tôi.","Tôi nghi ngờ chính con mèo đã làm rơi chiếc cốc khỏi bàn.","Chúng ta chỉ có thể phỏng đoán về nguyên nhân gây ra sự chậm trễ."]'::jsonb, 1, 'I was mistaken about the time of our appointment. → Tôi đã nhầm về thời gian cuộc hẹn của chúng tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_35_3', 'en-b2-35', NULL, 'comprehensive_test', 'listening', 'thinker', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nhà tư tưởng; người có tư duy sâu sắc","giám sát; theo dõi","dễ tiếp cận, dễ vào, dễ lấy hoặc dễ sử dụng","thảm kịch; tai họa; tai nạn đau lòng"]'::jsonb, 0, 'thinker (/ˈθɪŋkər/) → nhà tư tưởng; người có tư duy sâu sắc', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_35_4', 'en-b2-35', NULL, 'comprehensive_test', 'listening', 'The film''s predictable ending made us laugh rather than cry.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã đánh giá ba chiếc máy ảnh trước khi chọn một chiếc cho chuyến đi.","Sự kiên nhẫn là phẩm chất ở chị tôi mà tôi ngưỡng mộ nhất.","Cái kết dễ đoán của bộ phim khiến chúng tôi chỉ muốn bật cười thay vì xúc động.","Lần đầu tiên tôi thử làm bánh mì đã thành công một cách đáng ngạc nhiên."]'::jsonb, 2, 'The film''s predictable ending made us laugh rather than cry. → Cái kết dễ đoán của bộ phim khiến chúng tôi chỉ muốn bật cười thay vì xúc động.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_35_5', 'en-b2-35', NULL, 'comprehensive_test', 'listening', 'fate', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["số mệnh; định mệnh","chất; chất liệu","vô lý; không phải phép, không hợp lẽ phải","tinh thần; ý chí; nhiệt huyết"]'::jsonb, 0, 'fate (/feɪt/) → số mệnh; định mệnh; số phận; cục diện; kết cục', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_35_6', 'en-b2-35', NULL, 'comprehensive_test', 'listening', 'My preference is tea, but coffee is fine too.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi hiểu cơ sở lập luận đằng sau kế hoạch tiết kiệm tiền của bạn.","Sở thích của tôi là trà, nhưng uống cà phê cũng được.","Chuyến bay bị hoãn khiến chúng tôi phải đối mặt với nhiều giờ chờ đợi trong tâm trạng bất an.","Điểm yếu lớn nhất của tôi khi nấu ăn là canh thời gian chưa chuẩn."]'::jsonb, 1, 'My preference is tea, but coffee is fine too. → Sở thích của tôi là trà, nhưng uống cà phê cũng được.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_35_7', 'en-b2-35', NULL, 'comprehensive_test', 'listening', 'trait', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tốc độ; nhịp độ","đặc điểm; nét tiêu biểu; phẩm chất","sự thuận tiện; tính tiện lợi","suy thoái kinh tế; thời kỳ kinh tế sụt giảm"]'::jsonb, 1, 'trait (/treɪt/) → đặc điểm; nét tiêu biểu; phẩm chất', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_35_8', 'en-b2-35', NULL, 'comprehensive_test', 'listening', 'My grandmother''s motto was always to help others first.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Việc cùng nhau nấu ăn đã mang lại một khía cạnh mới cho tình bạn của chúng tôi.","Phương châm của bà tôi luôn là đặt việc giúp đỡ người khác lên hàng đầu.","Chúng ta chỉ có thể phỏng đoán về nguyên nhân gây ra sự chậm trễ.","Lần đầu tiên tôi thử làm bánh mì đã thành công một cách đáng ngạc nhiên."]'::jsonb, 1, 'My grandmother''s motto was always to help others first. → Phương châm của bà tôi luôn là đặt việc giúp đỡ người khác lên hàng đầu.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_35_9', 'en-b2-35', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a power believed to control what happens in people''s lives”?', '["fate","motto","attempt","uncertainty"]'::jsonb, 0, 'fate (/feɪt/) → số mệnh; định mệnh', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_35_10', 'en-b2-35', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a greater liking for one thing than for another”?', '["unaware","logical","logic","preference"]'::jsonb, 3, 'preference (/ˈprefrəns/) → sự ưu tiên; sở thích; sự thiên về', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_35_11', 'en-b2-35', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A particular quality in someone''s character or an organism''s nature.”?', '["mistaken","logic","trait","logical"]'::jsonb, 2, 'trait (/treɪt/) → đặc điểm; nét tiêu biểu; phẩm chất', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_35_12', 'en-b2-35', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A short phrase expressing someone''s guiding belief or purpose.”?', '["evaluate","motto","thus","suspect"]'::jsonb, 1, 'motto (/ˈmɑːtoʊ/) → châm ngôn; phương châm; khẩu hiệu', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
