INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_35_18', 'en-b2-35', NULL, 'comprehensive_test', 'reading', NULL, 'Researchers speculate that changing work patterns could reduce traffic congestion in major urban centres.', 'Dựa vào câu trên, từ “speculate” có nghĩa phù hợp nhất là gì?', '["không biết; thiếu hiểu biết (về một sự việc/chủ đề)","nhà bán buôn; doanh nghiệp bán sỉ","đậu nành; sản phẩm từ đậu nành","suy đoán; phỏng đoán"]'::jsonb, 3, 'speculate: suy đoán; phỏng đoán; đầu cơ. Dịch cả câu: Các nhà nghiên cứu phỏng đoán rằng việc thay đổi mô hình làm việc có thể giảm ùn tắc giao thông ở các trung tâm đô thị lớn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_35_19', 'en-b2-35', NULL, 'comprehensive_test', 'reading', NULL, 'The mistaken belief that all bacteria are harmful can prevent people from understanding their ecological importance.', 'Dựa vào câu trên, từ “mistaken” có nghĩa phù hợp nhất là gì?', '["có lẽ; có thể là; theo như dự đoán","sự tức giận; cơn giận","hang ổ; đường hầm (do động vật đào để trú ẩn)","sai lầm; hiểu lầm"]'::jsonb, 3, 'mistaken: sai lầm; hiểu lầm. Dịch cả câu: Quan điểm sai lầm rằng tất cả vi khuẩn đều có hại có thể ngăn cản mọi người hiểu rõ tầm quan trọng sinh thái của chúng.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_35_20', 'en-b2-35', NULL, 'comprehensive_test', 'reading', NULL, 'Education should encourage students to become independent thinkers rather than simply accept established ideas without question.', 'Dựa vào câu trên, từ “thinker” có nghĩa phù hợp nhất là gì?', '["nhà tư tưởng; người có tư duy sâu sắc","khái niệm; ý niệm","có nguy cơ bị đe dọa; có nguy cơ tuyệt chủng","nhạc phim; phần âm thanh"]'::jsonb, 0, 'thinker: nhà tư tưởng; người có tư duy sâu sắc. Dịch cả câu: Giáo dục nên khích lệ học sinh trở thành những người có tư duy độc lập thay vì chỉ tiếp nhận thụ động các quan niệm đã có sẵn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_35_21', 'en-b2-35', NULL, 'comprehensive_test', 'reading', NULL, 'A predictable income helps families plan their spending and reduces the stress associated with financial uncertainty.', 'Dựa vào câu trên, từ “predictable” có nghĩa phù hợp nhất là gì?', '["có thể đoán trước; dự đoán được","trụ sở chính; tổng hành dinh","chuyển đổi; biến đổi; cải tạo","sự thấu hiểu; cái nhìn sâu sắc"]'::jsonb, 0, 'predictable: có thể đoán trước; dự đoán được; dễ đoán; nhàm chán. Dịch cả câu: Nguồn thu nhập ổn định giúp các gia đình chủ động hoạch định chi tiêu và giảm bớt áp lực từ những bất ổn tài chính.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_35_22', 'en-b2-35', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự cố gắng; nỗ lực”', '["representative","texture","loneliness","attempt"]'::jsonb, 3, 'sự cố gắng; nỗ lực → attempt (/əˈtempt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_35_23', 'en-b2-35', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “khả năng phán đoán; sự đánh giá”', '["demolish","dove","judgement","convenience"]'::jsonb, 2, 'khả năng phán đoán; sự đánh giá → judgement (/ˈdʒʌdʒmənt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_35_24', 'en-b2-35', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “vô cùng ngốc nghếch; phi lý; nguy hiểm”', '["insane","feather","novelty","preservation"]'::jsonb, 0, 'vô cùng ngốc nghếch; phi lý; nguy hiểm → insane (/ɪnˈseɪn/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-36', 'en', 'Bài 36: Tư duy & Nhận thức (3) - CEFR B2', 'CEFR B2', 'B2 · Tư duy', '28 từ vựng Tiếng Anh CEFR B2 chủ đề tư duy & nhận thức kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4036, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deliberate', 'en-b2-36', 'deliberate', '/dɪˈlɪbərət/', 'B2', 'cố ý; chủ tâm; thận trọng; từ tốn; thong thả; cân nhắc kỹ lưỡng; thảo luận', 'adj.', 'deliberately (adv.), deliberation (n.)', 'Đồng nghĩa: intentional · Trái nghĩa: accidental', 'Dạng tính từ có phần đuôi phát âm là /ət/, trong khi dạng động từ phát âm là /eɪt/.', 'Leaving my phone at home was a deliberate choice.', NULL, 'Việc để điện thoại ở nhà là một lựa chọn có chủ ý của tôi.', '{"wordId":"deliberate","ukIpa":"/dɪˈlɪbərət/","usIpa":"/dɪˈlɪbərət/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Done intentionally rather than by accident.","vi":"cố ý; chủ tâm"},{"pos":"adj.","en":"Slow and careful, rather than hurried.","vi":"thận trọng; từ tốn; thong thả"},{"pos":"v.","en":"To consider something carefully before making a decision.","vi":"cân nhắc kỹ lưỡng; thảo luận"}],"examples":[{"en":"Leaving my phone at home was a deliberate choice.","vi":"Việc để điện thoại ở nhà là một lựa chọn có chủ ý của tôi.","audioKind":"ex"},{"en":"Local authorities should deliberate carefully before approving developments that could permanently damage natural habitats.","vi":"Các cơ quan chức năng địa phương nên cân nhắc kỹ lưỡng trước khi phê duyệt các dự án phát triển có thể gây tổn hại vĩnh viễn đến môi trường sống tự nhiên.","audioKind":"ex2"}],"collocations":[{"en":"a deliberate attempt","vi":"một nỗ lực có chủ đích"},{"en":"deliberate damage","vi":"hành vi cố ý phá hoại"},{"en":"deliberate movements","vi":"những chuyển động thong thả, cẩn trọng"},{"en":"deliberate on a proposal","vi":"cân nhắc về một đề xuất"}],"wordFamily":["deliberately (adv.)","deliberation (n.)"],"synonyms":["intentional"],"antonyms":["accidental"],"tipVi":"Dạng tính từ có phần đuôi phát âm là /ət/, trong khi dạng động từ phát âm là /eɪt/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_justify', 'en-b2-36', 'justify', '/ˈdʒʌstɪfaɪ/', 'B2', 'biện minh; chứng minh là hợp lý', 'v.', 'justification (n.), justifiable (adj.), justifiably (adv.)', NULL, 'Sau "justify" dùng danh từ hoặc danh động từ (V-ing), không dùng động từ nguyên mẫu có "to".', 'I cannot justify buying another coat this winter.', NULL, 'Tôi không thể biện minh cho việc mua thêm một chiếc áo khoác nữa vào mùa đông này.', '{"wordId":"justify","ukIpa":"/ˈdʒʌstɪfaɪ/","usIpa":"/ˈdʒʌstɪfaɪ/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"Give good reasons for an action, decision, or belief.","vi":"biện minh; chứng minh là hợp lý"}],"examples":[{"en":"I cannot justify buying another coat this winter.","vi":"Tôi không thể biện minh cho việc mua thêm một chiếc áo khoác nữa vào mùa đông này.","audioKind":"ex"},{"en":"Governments must justify major infrastructure spending by demonstrating clear benefits for the wider community.","vi":"Chính phủ phải chứng minh tính hợp lý của các khoản chi tiêu lớn cho cơ sở hạ tầng bằng cách chỉ ra những lợi ích rõ ràng cho cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"justify a decision","vi":"biện minh cho một quyết định"},{"en":"justify the cost","vi":"chứng minh chi phí là hợp lý"},{"en":"justify doing something","vi":"chứng minh việc làm gì đó là hợp lý"}],"wordFamily":["justification (n.)","justifiable (adj.)","justifiably (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Sau \"justify\" dùng danh từ hoặc danh động từ (V-ing), không dùng động từ nguyên mẫu có \"to\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_genius', 'en-b2-36', 'genius', '/ˈdʒiːniəs/', 'B2', 'thiên tài; tài năng thiên bẩm; năng khiếu phi thường', 'n.', NULL, NULL, 'Khi chỉ người thiên tài thì dùng như danh từ đếm được; khi chỉ tài năng phi thường thì thường là danh từ không đếm được.', 'My sister is a genius at fixing broken toys.', NULL, 'Chị gái tôi là một thiên tài trong việc sửa chữa đồ chơi hỏng.', '{"wordId":"genius","ukIpa":"/ˈdʒiːniəs/","usIpa":"/ˈdʒiːniəs/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"someone with exceptional intelligence or creative ability","vi":"thiên tài"},{"pos":"n.","en":"exceptional natural ability in a particular area","vi":"tài năng thiên bẩm; năng khiếu phi thường"}],"examples":[{"en":"My sister is a genius at fixing broken toys.","vi":"Chị gái tôi là một thiên tài trong việc sửa chữa đồ chơi hỏng.","audioKind":"ex"},{"en":"Creative genius often develops when schools allow students to experiment rather than simply memorise facts.","vi":"Tài năng sáng tạo thường phát triển khi trường học cho phép học sinh thử nghiệm thay vì chỉ ghi nhớ kiến thức.","audioKind":"ex2"}],"collocations":[{"en":"a mathematical genius","vi":"thiên tài toán học"},{"en":"creative genius","vi":"tài năng sáng tạo"},{"en":"a genius at","vi":"bậc thầy về"},{"en":"a stroke of genius","vi":"một ý tưởng thiên tài"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ người thiên tài thì dùng như danh từ đếm được; khi chỉ tài năng phi thường thì thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_enhance', 'en-b2-36', 'enhance', '/ɪnˈhæns/', 'B2', 'nâng cao; tăng cường; cải thiện', 'v.', 'enhancement (n.), enhancer (n.)', 'Đồng nghĩa: improve, boost · Trái nghĩa: diminish, impair', 'Nhấn mạnh sự nâng cao về chất lượng, hiệu quả hoặc giá trị, không chỉ đơn thuần là tăng số lượng.', 'A little lemon juice enhances the flavour of this soup.', NULL, 'Một chút nước cốt chanh làm tăng hương vị của món súp này.', '{"wordId":"enhance","ukIpa":"/ɪnˈhɑːns/","usIpa":"/ɪnˈhæns/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"Improve the quality, value, or appeal of something","vi":"nâng cao; tăng cường; cải thiện"}],"examples":[{"en":"A little lemon juice enhances the flavour of this soup.","vi":"Một chút nước cốt chanh làm tăng hương vị của món súp này.","audioKind":"ex"},{"en":"Access to green spaces can enhance residents'' wellbeing and encourage more active lifestyles in crowded cities.","vi":"Việc tiếp cận không gian xanh có thể nâng cao sức khỏe tinh thần của cư dân và khuyến khích lối sống năng động hơn ở các thành phố đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"enhance performance","vi":"nâng cao hiệu suất"},{"en":"enhance the quality of","vi":"nâng cao chất lượng của"},{"en":"enhance someone''s reputation","vi":"nâng cao uy tín của ai"}],"wordFamily":["enhancement (n.)","enhancer (n.)"],"synonyms":["improve","boost"],"antonyms":["diminish","impair"],"tipVi":"Nhấn mạnh sự nâng cao về chất lượng, hiệu quả hoặc giá trị, không chỉ đơn thuần là tăng số lượng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_self', 'en-b2-36', 'self', '/self/', 'B2', 'bản thân; cái tôi', 'n.', 'selfish (adj.), selfless (adj.), selfhood (n.)', NULL, '"self" là danh từ; để diễn đạt "chính tôi" thường dùng "myself".', 'After a good sleep, I felt like my usual self.', NULL, 'Sau một giấc ngủ ngon, tôi cảm thấy mình lại trở về trạng thái bình thường.', '{"wordId":"self","ukIpa":"/self/","usIpa":"/self/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"The personality and qualities that make you who you are.","vi":"bản thân; cái tôi"}],"examples":[{"en":"After a good sleep, I felt like my usual self.","vi":"Sau một giấc ngủ ngon, tôi cảm thấy mình lại trở về trạng thái bình thường.","audioKind":"ex"},{"en":"Creative activities can help young people develop a stronger sense of self during periods of rapid change.","vi":"Các hoạt động sáng tạo có thể giúp người trẻ hình thành ý thức về bản thân mạnh mẽ hơn trong những giai đoạn thay đổi nhanh chóng.","audioKind":"ex2"}],"collocations":[{"en":"a sense of self","vi":"ý thức về bản thân"},{"en":"your true self","vi":"con người thật của bạn"},{"en":"your usual self","vi":"trạng thái bình thường của bạn"}],"wordFamily":["selfish (adj.)","selfless (adj.)","selfhood (n.)"],"synonyms":[],"antonyms":[],"tipVi":"\"self\" là danh từ; để diễn đạt \"chính tôi\" thường dùng \"myself\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_proportion', 'en-b2-36', 'proportion', '/prəˈpɔːrʃən/', 'B2', 'tỷ lệ; phần (của một tổng thể); mối quan hệ về kích thước hoặc số lượng giữa các sự vật', 'n.', 'proportional (adj.), proportionally (adv.), proportionate (adj.), disproportionate (adj.)', 'Đồng nghĩa: share, percentage', 'Sau cụm "a proportion of", động từ chia số ít hay số nhiều phụ thuộc vào danh từ phía sau.', 'A large proportion of my wages goes on rent.', NULL, 'Phần lớn tiền lương của tôi dùng để trả tiền thuê nhà.', '{"wordId":"proportion","ukIpa":"/prəˈpɔːʃən/","usIpa":"/prəˈpɔːrʃən/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"a part or share of a whole","vi":"tỷ lệ; phần (của một tổng thể)"},{"pos":"n.","en":"the relationship in size or amount between things","vi":"mối quan hệ về kích thước hoặc số lượng giữa các sự vật"}],"examples":[{"en":"A large proportion of my wages goes on rent.","vi":"Phần lớn tiền lương của tôi dùng để trả tiền thuê nhà.","audioKind":"ex"},{"en":"The proportion of residents using public transport increased after the city introduced cheaper monthly passes.","vi":"Tỷ lệ cư dân sử dụng phương tiện giao thông công cộng đã tăng lên sau khi thành phố triển khai vé tháng giá rẻ hơn.","audioKind":"ex2"}],"collocations":[{"en":"a large proportion of","vi":"phần lớn"},{"en":"in proportion to","vi":"tỷ lệ thuận với"},{"en":"out of proportion","vi":"mất cân đối; không tương xứng"}],"wordFamily":["proportional (adj.)","proportionally (adv.)","proportionate (adj.)","disproportionate (adj.)"],"synonyms":["share","percentage"],"antonyms":[],"tipVi":"Sau cụm \"a proportion of\", động từ chia số ít hay số nhiều phụ thuộc vào danh từ phía sau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_evident', 'en-b2-36', 'evident', '/ˈevɪdənt/', 'B2', 'rõ ràng; hiển nhiên; dễ nhận thấy', 'adj.', 'evidence (n.), evidently (adv.)', 'Đồng nghĩa: obvious, apparent, clear · Trái nghĩa: unclear', 'Cấu trúc phổ biến It is evident that... dùng để diễn đạt ý rõ ràng là...', 'Her relief was evident when the puppy returned.', NULL, 'Sự nhẹ nhõm hiện rõ trên khuôn mặt cô ấy khi chú chó con quay về.', '{"wordId":"evident","ukIpa":"/ˈevɪdənt/","usIpa":"/ˈevɪdənt/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Easy to see, understand, or recognize.","vi":"rõ ràng; hiển nhiên; dễ nhận thấy"}],"examples":[{"en":"Her relief was evident when the puppy returned.","vi":"Sự nhẹ nhõm hiện rõ trên khuôn mặt cô ấy khi chú chó con quay về.","audioKind":"ex"},{"en":"The benefits of improved public transport are evident in cities where traffic congestion has decreased.","vi":"Lợi ích của việc cải thiện giao thông công cộng là điều hiển nhiên ở những thành phố nơi tình trạng tắc nghẽn giao thông đã giảm bớt.","audioKind":"ex2"}],"collocations":[{"en":"clearly evident","vi":"rõ mồn một; thấy rõ"},{"en":"become evident","vi":"trở nên rõ ràng"},{"en":"evident from","vi":"có thể thấy rõ từ..."}],"wordFamily":["evidence (n.)","evidently (adv.)"],"synonyms":["obvious","apparent","clear"],"antonyms":["unclear"],"tipVi":"Cấu trúc phổ biến It is evident that... dùng để diễn đạt ý rõ ràng là...","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_intelligence', 'en-b2-36', 'intelligence', '/ɪnˈtelɪdʒəns/', 'B2', 'trí thông minh; năng lực trí tuệ; thông tin tình báo; công tác tình báo', 'n.', 'intelligent (adj.), intelligently (adv.)', 'Đồng nghĩa: intellect', 'Thường là danh từ không đếm được; intelligence agency chỉ cơ quan tình báo.', 'Her intelligence helped her solve the puzzle quickly.', NULL, 'Sự thông minh đã giúp cô ấy giải câu đố một cách nhanh chóng.', '{"wordId":"intelligence","ukIpa":"/ɪnˈtelɪdʒəns/","usIpa":"/ɪnˈtelɪdʒəns/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"The ability to learn, understand, and solve problems.","vi":"trí thông minh; năng lực trí tuệ"},{"pos":"n.","en":"Secret information gathered about other countries or possible threats.","vi":"thông tin tình báo; công tác tình báo"}],"examples":[{"en":"Her intelligence helped her solve the puzzle quickly.","vi":"Sự thông minh đã giúp cô ấy giải câu đố một cách nhanh chóng.","audioKind":"ex"},{"en":"Traditional examinations may measure memory more effectively than intelligence, creativity, or practical problem-solving skills.","vi":"Các bài thi truyền thống có thể đo lường trí nhớ hiệu quả hơn là trí tuệ, sự sáng tạo hoặc kỹ năng giải quyết vấn đề thực tế.","audioKind":"ex2"}],"collocations":[{"en":"artificial intelligence","vi":"trí tuệ nhân tạo"},{"en":"emotional intelligence","vi":"trí thông minh cảm xúc"},{"en":"gather intelligence","vi":"thu thập tình báo"},{"en":"intelligence agency","vi":"cơ quan tình báo"}],"wordFamily":["intelligent (adj.)","intelligently (adv.)"],"synonyms":["intellect"],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; intelligence agency chỉ cơ quan tình báo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sane', 'en-b2-36', 'sane', '/seɪn/', 'B2', 'hợp lý; sáng suốt; tỉnh táo; minh mẫn', 'adj.', 'sanity (n.), insane (adj.), insanity (n.)', 'Đồng nghĩa: sensible, rational · Trái nghĩa: irrational, insane', 'Khi chỉ sự sáng suốt, từ này có nét nghĩa gần với sensible; không phải mọi bệnh lý tâm thần đều ảnh hưởng đến sự tỉnh táo này.', 'Taking a short break seemed like the only sane choice.', NULL, 'Tranh thủ nghỉ ngơi chốc lát có vẻ là lựa chọn sáng suốt duy nhất.', '{"wordId":"sane","ukIpa":"/seɪn/","usIpa":"/seɪn/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Showing reasonable judgment rather than extreme or foolish thinking.","vi":"hợp lý; sáng suốt"},{"pos":"adj.","en":"Able to think clearly and understand reality.","vi":"tỉnh táo; minh mẫn"}],"examples":[{"en":"Taking a short break seemed like the only sane choice.","vi":"Tranh thủ nghỉ ngơi chốc lát có vẻ là lựa chọn sáng suốt duy nhất.","audioKind":"ex"},{"en":"A sane approach to urban planning balances economic growth with residents'' need for green spaces.","vi":"Một cách tiếp cận hợp lý trong quy hoạch đô thị là cân bằng giữa tăng trưởng kinh tế và nhu cầu về không gian xanh của cư dân.","audioKind":"ex2"}],"collocations":[{"en":"a sane approach","vi":"phương pháp tiếp cận hợp lý"},{"en":"a sane decision","vi":"quyết định sáng suốt"},{"en":"keep someone sane","vi":"giữ cho ai đó tỉnh táo"}],"wordFamily":["sanity (n.)","insane (adj.)","insanity (n.)"],"synonyms":["sensible","rational"],"antonyms":["irrational","insane"],"tipVi":"Khi chỉ sự sáng suốt, từ này có nét nghĩa gần với sensible; không phải mọi bệnh lý tâm thần đều ảnh hưởng đến sự tỉnh táo này.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_concept', 'en-b2-36', 'concept', '/ˈkɑːnsept/', 'B2', 'khái niệm; ý niệm', 'n.', 'conceptual (adj.), conceptually (adv.), conceptualise (v.)', 'Đồng nghĩa: idea, notion', 'Là danh từ đếm được; thường dùng cụm the concept of để dẫn dắt một khái niệm cụ thể.', 'The teacher used toy cars to explain the concept.', NULL, 'Giáo viên đã dùng những chiếc xe đồ chơi để giải thích khái niệm này.', '{"wordId":"concept","ukIpa":"/ˈkɒnsept/","usIpa":"/ˈkɑːnsept/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"an idea or principle used to understand or plan something","vi":"khái niệm; ý niệm"}],"examples":[{"en":"The teacher used toy cars to explain the concept.","vi":"Giáo viên đã dùng những chiếc xe đồ chơi để giải thích khái niệm này.","audioKind":"ex"},{"en":"The concept of sustainable development involves meeting current needs without limiting the opportunities available to future generations.","vi":"Khái niệm phát triển bền vững bao gồm việc đáp ứng các nhu cầu hiện tại mà không làm hạn chế các cơ hội dành cho các thế hệ tương lai.","audioKind":"ex2"}],"collocations":[{"en":"basic concept","vi":"khái niệm cơ bản"},{"en":"grasp a concept","vi":"nắm bắt một khái niệm"},{"en":"the concept of","vi":"khái niệm về"},{"en":"abstract concept","vi":"khái niệm trừu tượng"}],"wordFamily":["conceptual (adj.)","conceptually (adv.)","conceptualise (v.)"],"synonyms":["idea","notion"],"antonyms":[],"tipVi":"Là danh từ đếm được; thường dùng cụm the concept of để dẫn dắt một khái niệm cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_convinced', 'en-b2-36', 'convinced', '/kənˈvɪnst/', 'B2', 'tin chắc; hoàn toàn tin tưởng', 'adj.', 'convince (v.), convincing (adj.), convincingly (adv.), unconvinced (adj.)', 'Đồng nghĩa: certain, sure · Trái nghĩa: unconvinced, doubtful', 'Khi diễn tả con người cảm thấy tin chắc, dùng convinced; khi nói về sự việc có tính thuyết phục, dùng convincing.', 'I''m convinced I left my keys on the kitchen table.', NULL, 'Tôi chắc chắn rằng mình đã để chìa khóa trên bàn bếp.', '{"wordId":"convinced","ukIpa":"/kənˈvɪnst/","usIpa":"/kənˈvɪnst/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"completely sure that something is true or right","vi":"tin chắc; hoàn toàn tin tưởng"}],"examples":[{"en":"I''m convinced I left my keys on the kitchen table.","vi":"Tôi chắc chắn rằng mình đã để chìa khóa trên bàn bếp.","audioKind":"ex"},{"en":"Many researchers are convinced that regular physical activity contributes significantly to better mental health.","vi":"Nhiều nhà nghiên cứu tin chắc rằng việc vận động cơ thể thường xuyên góp phần đáng kể vào việc cải thiện sức khỏe tinh thần.","audioKind":"ex2"}],"collocations":[{"en":"convinced that","vi":"tin chắc rằng"},{"en":"convinced of","vi":"tin chắc về điều gì"},{"en":"fully convinced","vi":"hoàn toàn tin tưởng"},{"en":"remain convinced","vi":"vẫn đinh ninh rằng"}],"wordFamily":["convince (v.)","convincing (adj.)","convincingly (adv.)","unconvinced (adj.)"],"synonyms":["certain","sure"],"antonyms":["unconvinced","doubtful"],"tipVi":"Khi diễn tả con người cảm thấy tin chắc, dùng convinced; khi nói về sự việc có tính thuyết phục, dùng convincing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bound', 'en-b2-36', 'bound', '/baʊnd/', 'B2', 'chắc chắn; có khả năng cao; hướng về; đi đến; nhảy cẫng lên; chạy nhanh', 'adj.', 'bind (v.), binding (adj.), bounded (adj.)', NULL, 'bound to theo sau là động từ; bound for theo sau là điểm đến.', 'You''re bound to feel tired after such a long walk.', NULL, 'Bạn chắc chắn sẽ cảm thấy mệt sau một quãng đường đi bộ dài như vậy.', '{"wordId":"bound","ukIpa":"/baʊnd/","usIpa":"/baʊnd/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Certain or very likely to happen","vi":"chắc chắn; có khả năng cao"},{"pos":"adj.","en":"Travelling towards a particular destination","vi":"hướng về; đi đến"},{"pos":"v.","en":"To move with long, energetic jumps","vi":"nhảy cẫng lên; chạy nhanh"}],"examples":[{"en":"You''re bound to feel tired after such a long walk.","vi":"Bạn chắc chắn sẽ cảm thấy mệt sau một quãng đường đi bộ dài như vậy.","audioKind":"ex"},{"en":"Without adequate investment in public transport, growing cities are bound to experience increasingly severe traffic congestion.","vi":"Nếu thiếu đầu tư đầy đủ cho giao thông công cộng, các đô thị đang phát triển chắc chắn sẽ phải đối mặt với tình trạng tắc nghẽn giao thông ngày càng nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"be bound to do","vi":"chắc chắn sẽ làm gì"},{"en":"be bound for","vi":"hướng đến"},{"en":"bound by law","vi":"bị ràng buộc bởi pháp luật"},{"en":"bound up with","vi":"gắn chặt với"}],"wordFamily":["bind (v.)","binding (adj.)","bounded (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"bound to theo sau là động từ; bound for theo sau là điểm đến.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_realistic', 'en-b2-36', 'realistic', '/ˌriːəˈlɪstɪk/', 'B2', 'thực tế; khả thi; chân thực; giống như thật', 'adj.', 'realism (n.), realist (n.), realistically (adv.), unrealistic (adj.)', 'Đồng nghĩa: practical, lifelike · Trái nghĩa: unrealistic', 'realistic nhấn mạnh sự phù hợp với thực tế hoặc tính chân thực, còn real nhấn mạnh sự tồn tại có thật.', 'Finishing this puzzle tonight is not a realistic goal.', NULL, 'Hoàn thành bức tranh ghép này trong tối nay không phải là một mục tiêu thực tế.', '{"wordId":"realistic","ukIpa":"/ˌrɪəˈlɪstɪk/","usIpa":"/ˌriːəˈlɪstɪk/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Based on what is actually possible or likely","vi":"thực tế; khả thi"},{"pos":"adj.","en":"Looking or sounding very much like real life","vi":"chân thực; giống như thật"}],"examples":[{"en":"Finishing this puzzle tonight is not a realistic goal.","vi":"Hoàn thành bức tranh ghép này trong tối nay không phải là một mục tiêu thực tế.","audioKind":"ex"},{"en":"Governments should set realistic targets for reducing emissions, taking economic conditions and available technology into account.","vi":"Chính phủ nên đặt ra các mục tiêu giảm phát thải khả thi, có tính đến điều kiện kinh tế và công nghệ hiện có.","audioKind":"ex2"}],"collocations":[{"en":"realistic expectations","vi":"kỳ vọng thực tế"},{"en":"set realistic goals","vi":"đặt ra mục tiêu khả thi"},{"en":"a realistic portrait","vi":"bức chân dung chân thực"}],"wordFamily":["realism (n.)","realist (n.)","realistically (adv.)","unrealistic (adj.)"],"synonyms":["practical","lifelike"],"antonyms":["unrealistic"],"tipVi":"realistic nhấn mạnh sự phù hợp với thực tế hoặc tính chân thực, còn real nhấn mạnh sự tồn tại có thật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pursuit', 'en-b2-36', 'pursuit', '/pɚˈsuːt/', 'B2', 'sự theo đuổi; sự mưu cầu; sự truy đuổi; sự săn lùng; hoạt động giải trí; sở thích', 'n.', 'pursue (v.), pursuer (n.)', NULL, 'Khi mang nghĩa theo đuổi hoặc truy đuổi thì thường là danh từ không đếm được; khi chỉ sở thích giải trí thì đếm được.', 'Her pursuit of happiness led her to gardening.', NULL, 'Việc tìm kiếm hạnh phúc đã đưa cô ấy đến với công việc làm vườn.', '{"wordId":"pursuit","ukIpa":"/pəˈsjuːt/","usIpa":"/pɚˈsuːt/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"The effort to achieve or obtain something","vi":"sự theo đuổi; sự mưu cầu"},{"pos":"n.","en":"The act of following someone to catch them","vi":"sự truy đuổi; sự săn lùng"},{"pos":"n.","en":"An activity you enjoy doing regularly","vi":"hoạt động giải trí; sở thích"}],"examples":[{"en":"Her pursuit of happiness led her to gardening.","vi":"Việc tìm kiếm hạnh phúc đã đưa cô ấy đến với công việc làm vườn.","audioKind":"ex"},{"en":"The pursuit of economic growth should not come at the expense of environmental protection.","vi":"Việc theo đuổi tăng trưởng kinh tế không nên đánh đổi bằng việc hy sinh bảo vệ môi trường.","audioKind":"ex2"}],"collocations":[{"en":"in pursuit of","vi":"trong quá trình theo đuổi / truy đuổi"},{"en":"the pursuit of knowledge","vi":"sự theo đuổi tri thức"},{"en":"leisure pursuits","vi":"các hoạt động giải trí"}],"wordFamily":["pursue (v.)","pursuer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi mang nghĩa theo đuổi hoặc truy đuổi thì thường là danh từ không đếm được; khi chỉ sở thích giải trí thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reflection', 'en-b2-36', 'reflection', '/rɪˈflekʃən/', 'B2', 'hình ảnh phản chiếu; ảnh phản chiếu; bóng; sự suy ngẫm; sự cân nhắc kỹ lưỡng; sự phản ánh; sự biểu hiện', 'n.', 'reflect (v.), reflective (adj.)', 'Đồng nghĩa: image, contemplation', 'on reflection diễn tả ý sau khi suy ngẫm kỹ; a reflection of diễn tả sự thể hiện của cái gì đó.', 'A duck disturbed the mountain''s reflection in the lake.', NULL, 'Một con vịt đã làm xao động hình bóng của những ngọn núi trên mặt hồ.', '{"wordId":"reflection","ukIpa":"/rɪˈflekʃən/","usIpa":"/rɪˈflekʃən/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"an image seen in a mirror or shiny surface","vi":"hình ảnh phản chiếu; ảnh phản chiếu; bóng"},{"pos":"n.","en":"careful thought about an experience, idea, or decision","vi":"sự suy ngẫm; sự cân nhắc kỹ lưỡng"},{"pos":"n.","en":"something that shows the nature or condition of something else","vi":"sự phản ánh; sự biểu hiện"}],"examples":[{"en":"A duck disturbed the mountain''s reflection in the lake.","vi":"Một con vịt đã làm xao động hình bóng của những ngọn núi trên mặt hồ.","audioKind":"ex"},{"en":"Regular reflection on classroom experiences can help teachers identify weaknesses and improve their teaching methods.","vi":"Việc thường xuyên suy ngẫm về trải nghiệm trên lớp có thể giúp giáo viên nhận ra điểm yếu và cải thiện phương pháp giảng dạy của họ.","audioKind":"ex2"}],"collocations":[{"en":"a reflection in the mirror","vi":"bóng trong gương"},{"en":"on reflection","vi":"sau khi suy nghĩ kỹ"},{"en":"a reflection of society","vi":"sự phản ánh của xã hội"}],"wordFamily":["reflect (v.)","reflective (adj.)"],"synonyms":["image","contemplation"],"antonyms":[],"tipVi":"on reflection diễn tả ý sau khi suy ngẫm kỹ; a reflection of diễn tả sự thể hiện của cái gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_actual', 'en-b2-36', 'actual', '/ˈæktʃuəl/', 'B2', 'thực tế; thực sự', 'adj.', 'actually (adv.), actuality (n.)', 'Đồng nghĩa: real, true · Trái nghĩa: imaginary', 'actual mang nghĩa thực tế, không đồng nghĩa với current (hiện tại).', 'The actual bill was much lower than we expected.', NULL, 'Hóa đơn thực tế thấp hơn nhiều so với chúng tôi mong đợi.', '{"wordId":"actual","ukIpa":"/ˈæktʃuəl/","usIpa":"/ˈæktʃuəl/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"real, rather than imagined, estimated, or claimed","vi":"thực tế; thực sự"}],"examples":[{"en":"The actual bill was much lower than we expected.","vi":"Hóa đơn thực tế thấp hơn nhiều so với chúng tôi mong đợi.","audioKind":"ex"},{"en":"Governments should measure the actual impact of transport policies rather than relying solely on predicted benefits.","vi":"Chính phủ nên đo lường tác động thực tế của các chính sách giao thông thay vì chỉ dựa vào những lợi ích dự đoán.","audioKind":"ex2"}],"collocations":[{"en":"actual cost","vi":"chi phí thực tế"},{"en":"actual results","vi":"kết quả thực tế"},{"en":"actual size","vi":"kích thước thực tế"}],"wordFamily":["actually (adv.)","actuality (n.)"],"synonyms":["real","true"],"antonyms":["imaginary"],"tipVi":"actual mang nghĩa thực tế, không đồng nghĩa với current (hiện tại).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_relevant', 'en-b2-36', 'relevant', '/ˈreləvənt/', 'B2', 'có liên quan; thích hợp; sát thực tế', 'adj.', 'relevance (n.), irrelevant (adj.)', 'Đồng nghĩa: pertinent, applicable · Trái nghĩa: irrelevant', 'Dùng cấu trúc relevant to để chỉ sự liên quan đến cái gì, không dùng giới từ with.', 'Please bring any documents relevant to your application.', NULL, 'Vui lòng mang theo bất kỳ tài liệu nào liên quan đến đơn đăng ký của bạn.', '{"wordId":"relevant","ukIpa":"/ˈreləvənt/","usIpa":"/ˈreləvənt/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"closely connected with the subject or situation being considered","vi":"có liên quan; thích hợp; sát thực tế"}],"examples":[{"en":"Please bring any documents relevant to your application.","vi":"Vui lòng mang theo bất kỳ tài liệu nào liên quan đến đơn đăng ký của bạn.","audioKind":"ex"},{"en":"Universities should ensure that their courses remain relevant to the changing needs of the labour market.","vi":"Các trường đại học nên đảm bảo rằng các khóa học của họ luôn sát với nhu cầu thay đổi của thị trường lao động.","audioKind":"ex2"}],"collocations":[{"en":"relevant to","vi":"liên quan đến"},{"en":"relevant experience","vi":"kinh nghiệm liên quan"},{"en":"relevant information","vi":"thông tin liên quan"},{"en":"highly relevant","vi":"có liên quan mật thiết"}],"wordFamily":["relevance (n.)","irrelevant (adj.)"],"synonyms":["pertinent","applicable"],"antonyms":["irrelevant"],"tipVi":"Dùng cấu trúc relevant to để chỉ sự liên quan đến cái gì, không dùng giới từ with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_purely', 'en-b2-36', 'purely', '/ˈpjʊrli/', 'B2', 'hoàn toàn; thuần túy; chỉ vì', 'adv.', 'pure (adj.), purity (n.), purify (v.)', 'Đồng nghĩa: solely, exclusively, entirely', 'Thường đứng trước các giới từ for, by hoặc trước tính từ nhằm nhấn mạnh sự độc quyền, không pha lẫn yếu tố khác.', 'I bought this little camera purely for fun.', NULL, 'Tôi mua chiếc máy ảnh nhỏ này thuần túy để giải trí.', '{"wordId":"purely","ukIpa":"/ˈpjʊəli/","usIpa":"/ˈpjʊrli/","cefr":"B2","topic":"thinking","senses":[{"pos":"adv.","en":"Only for the stated reason or in the stated way.","vi":"hoàn toàn; thuần túy; chỉ vì"}],"examples":[{"en":"I bought this little camera purely for fun.","vi":"Tôi mua chiếc máy ảnh nhỏ này thuần túy để giải trí.","audioKind":"ex"},{"en":"University education should not be judged purely by graduates'' salaries, as it also brings wider social benefits.","vi":"Không nên đánh giá giáo dục đại học hoàn toàn dựa trên mức lương của sinh viên tốt nghiệp, vì nó còn mang lại nhiều lợi ích xã hội rộng lớn hơn.","audioKind":"ex2"}],"collocations":[{"en":"purely by chance","vi":"hoàn toàn tình cờ"},{"en":"purely for pleasure","vi":"hoàn toàn vì mục đích giải trí"},{"en":"purely personal","vi":"thuần túy mang tính cá nhân"},{"en":"purely theoretical","vi":"hoàn toàn mang tính lý thuyết"}],"wordFamily":["pure (adj.)","purity (n.)","purify (v.)"],"synonyms":["solely","exclusively","entirely"],"antonyms":[],"tipVi":"Thường đứng trước các giới từ for, by hoặc trước tính từ nhằm nhấn mạnh sự độc quyền, không pha lẫn yếu tố khác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_significance', 'en-b2-36', 'significance', '/sɪɡˈnɪfɪkəns/', 'B2', 'tầm quan trọng; ý nghĩa; hàm ý; ý nghĩa đặc biệt', 'n.', 'significant (adj.), significantly (adv.), insignificant (adj.)', 'Đồng nghĩa: importance, meaning · Trái nghĩa: insignificance', 'be of great significance tương đương với be very significant.', 'I finally understood the significance of her quiet smile.', NULL, 'Cuối cùng tôi đã hiểu được ý nghĩa đằng sau nụ cười nhẹ nhàng của cô ấy.', '{"wordId":"significance","ukIpa":"/sɪɡˈnɪfɪkəns/","usIpa":"/sɪɡˈnɪfɪkəns/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"the importance of something, especially its effects","vi":"tầm quan trọng; ý nghĩa"},{"pos":"n.","en":"the special meaning that something carries or suggests","vi":"hàm ý; ý nghĩa đặc biệt"}],"examples":[{"en":"I finally understood the significance of her quiet smile.","vi":"Cuối cùng tôi đã hiểu được ý nghĩa đằng sau nụ cười nhẹ nhàng của cô ấy.","audioKind":"ex"},{"en":"The discovery has considerable significance for scientists seeking cleaner and more affordable sources of energy.","vi":"Phát hiện này mang ý nghĩa to lớn đối với các nhà khoa học đang tìm kiếm các nguồn năng lượng sạch hơn và tiết kiệm hơn.","audioKind":"ex2"}],"collocations":[{"en":"great significance","vi":"tầm quan trọng lớn"},{"en":"historical significance","vi":"ý nghĩa lịch sử"},{"en":"the significance of","vi":"tầm quan trọng/ý nghĩa của"},{"en":"attach significance to","vi":"coi trọng"}],"wordFamily":["significant (adj.)","significantly (adv.)","insignificant (adj.)"],"synonyms":["importance","meaning"],"antonyms":["insignificance"],"tipVi":"be of great significance tương đương với be very significant.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inevitably', 'en-b2-36', 'inevitably', '/ɪnˈevɪtəbli/', 'B2', 'một cách tất yếu; không thể tránh khỏi', 'adv.', 'inevitable (adj.), inevitability (n.)', 'Đồng nghĩa: unavoidably · Trái nghĩa: avoidably', 'Mức độ chắc chắn mạnh hơn "probably", diễn tả kết quả không thể tránh khỏi.', 'Without regular watering, these flowers will inevitably die.', NULL, 'Nếu không tưới nước thường xuyên, những bông hoa này chắc chắn sẽ chết.', '{"wordId":"inevitably","ukIpa":"/ɪnˈevɪtəbli/","usIpa":"/ɪnˈevɪtəbli/","cefr":"B2","topic":"thinking","senses":[{"pos":"adv.","en":"in a way that cannot be prevented or avoided","vi":"một cách tất yếu; không thể tránh khỏi"}],"examples":[{"en":"Without regular watering, these flowers will inevitably die.","vi":"Nếu không tưới nước thường xuyên, những bông hoa này chắc chắn sẽ chết.","audioKind":"ex"},{"en":"A growing population will inevitably increase demand for housing unless household sizes change significantly.","vi":"Dân số tăng lên tất yếu sẽ làm gia tăng nhu cầu về nhà ở trừ khi quy mô hộ gia đình thay đổi đáng kể.","audioKind":"ex2"}],"collocations":[{"en":"inevitably lead to","vi":"tất yếu dẫn đến"},{"en":"inevitably involve","vi":"không thể tránh khỏi việc liên quan đến"},{"en":"almost inevitably","vi":"hầu như không thể tránh khỏi"}],"wordFamily":["inevitable (adj.)","inevitability (n.)"],"synonyms":["unavoidably"],"antonyms":["avoidably"],"tipVi":"Mức độ chắc chắn mạnh hơn \"probably\", diễn tả kết quả không thể tránh khỏi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ignorant', 'en-b2-36', 'ignorant', '/ˈɪɡnərənt/', 'B2', 'không biết; thiếu hiểu biết (về một sự việc/chủ đề); vô học; thiếu kiến thức; ngu dốt', 'adj.', 'ignorance (n.), ignorantly (adv.)', 'Đồng nghĩa: unaware, uninformed · Trái nghĩa: knowledgeable, informed', 'Thường dùng cấu trúc "be ignorant of"; dùng để miêu tả trực tiếp một người có thể mang nghĩa tiêu cực/xúc phạm.', 'I was ignorant of the rules until someone explained them.', NULL, 'Tôi chẳng hề biết gì về các quy tắc đó cho đến khi có người giải thích.', '{"wordId":"ignorant","ukIpa":"/ˈɪɡnərənt/","usIpa":"/ˈɪɡnərənt/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"not knowing about a particular fact or subject","vi":"không biết; thiếu hiểu biết (về một sự việc/chủ đề)"},{"pos":"adj.","en":"lacking knowledge, education, or understanding","vi":"vô học; thiếu kiến thức; ngu dốt"}],"examples":[{"en":"I was ignorant of the rules until someone explained them.","vi":"Tôi chẳng hề biết gì về các quy tắc đó cho đến khi có người giải thích.","audioKind":"ex"},{"en":"Consumers who remain ignorant of online privacy risks may share sensitive information without considering the consequences.","vi":"Những người tiêu dùng thiếu hiểu biết về rủi ro quyền riêng tư trực tuyến có thể chia sẻ thông tin nhạy cảm mà không cân nhắc hậu quả.","audioKind":"ex2"}],"collocations":[{"en":"ignorant of the facts","vi":"không biết sự thật"},{"en":"remain ignorant","vi":"vẫn không hay biết"},{"en":"an ignorant remark","vi":"một lời nhận xét thiếu hiểu biết"}],"wordFamily":["ignorance (n.)","ignorantly (adv.)"],"synonyms":["unaware","uninformed"],"antonyms":["knowledgeable","informed"],"tipVi":"Thường dùng cấu trúc \"be ignorant of\"; dùng để miêu tả trực tiếp một người có thể mang nghĩa tiêu cực/xúc phạm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_apparent', 'en-b2-36', 'apparent', '/əˈpærənt/', 'B2', 'rõ ràng; hiển nhiên; có vẻ ngoài; bề ngoài (nhưng chưa chắc đúng sự thật)', 'adj.', 'apparently (adv.)', 'Đồng nghĩa: obvious, evident · Trái nghĩa: hidden', 'Có thể mang nghĩa "rõ ràng" hoặc "có vẻ như", cần dựa vào ngữ cảnh để hiểu đúng.', 'Her excitement was apparent from her huge smile.', NULL, 'Sự hào hứng của cô ấy thể hiện rõ qua nụ cười rạng rỡ.', '{"wordId":"apparent","ukIpa":"/əˈpærənt/","usIpa":"/əˈpærənt/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Easy to see or understand.","vi":"rõ ràng; hiển nhiên"},{"pos":"adj.","en":"Seeming to be true, though possibly not actually true.","vi":"có vẻ ngoài; bề ngoài (nhưng chưa chắc đúng sự thật)"}],"examples":[{"en":"Her excitement was apparent from her huge smile.","vi":"Sự hào hứng của cô ấy thể hiện rõ qua nụ cười rạng rỡ.","audioKind":"ex"},{"en":"Despite the apparent benefits of remote learning, some students struggle without direct support from teachers.","vi":"Mặc dù có những lợi ích rõ ràng bề ngoài của việc học từ xa, một số học sinh vẫn gặp khó khăn khi thiếu sự hỗ trợ trực tiếp từ giáo viên.","audioKind":"ex2"}],"collocations":[{"en":"become apparent","vi":"trở nên rõ ràng"},{"en":"for no apparent reason","vi":"không có lý do rõ ràng"},{"en":"apparent contradiction","vi":"sự mâu thuẫn bề ngoài"}],"wordFamily":["apparently (adv.)"],"synonyms":["obvious","evident"],"antonyms":["hidden"],"tipVi":"Có thể mang nghĩa \"rõ ràng\" hoặc \"có vẻ như\", cần dựa vào ngữ cảnh để hiểu đúng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_apparently', 'en-b2-36', 'apparently', '/əˈpærəntli/', 'B2', 'nghe chừng; hình như; có vẻ như', 'adv.', 'apparent (adj.)', 'Đồng nghĩa: seemingly', 'Biểu thị theo thông tin có sẵn nhưng chưa chắc chắn hoàn toàn.', 'Apparently, the bakery closes early on rainy days.', NULL, 'Hình như tiệm bánh đóng cửa sớm vào những ngày mưa.', '{"wordId":"apparently","ukIpa":"/əˈpærəntli/","usIpa":"/əˈpærəntli/","cefr":"B2","topic":"thinking","senses":[{"pos":"adv.","en":"According to available information, though not necessarily certain.","vi":"nghe chừng; hình như; có vẻ như"}],"examples":[{"en":"Apparently, the bakery closes early on rainy days.","vi":"Hình như tiệm bánh đóng cửa sớm vào những ngày mưa.","audioKind":"ex"},{"en":"Apparently, many residents support the proposed park, although a formal survey has not yet been conducted.","vi":"Có vẻ như nhiều cư dân ủng hộ khu, mặc dù một cuộc khảo sát chính thức vẫn chưa được tiến hành.","audioKind":"ex2"}],"collocations":[{"en":"apparently harmless","vi":"trông có vẻ vô hại"},{"en":"apparently unaware","vi":"hình như không hay biết"},{"en":"apparently simple","vi":"trông có vẻ đơn giản"}],"wordFamily":["apparent (adj.)"],"synonyms":["seemingly"],"antonyms":[],"tipVi":"Biểu thị theo thông tin có sẵn nhưng chưa chắc chắn hoàn toàn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_assumption', 'en-b2-36', 'assumption', '/əˈsʌmpʃən/', 'B2', 'giả định; điều phỏng đoán; sự đảm nhận (trách nhiệm, quyền lực hoặc vai trò)', 'n.', 'assume (v.), assumed (adj.)', 'Đồng nghĩa: supposition, presumption', 'Thường đi với mệnh đề assumption that, chỉ quan điểm được chấp nhận mà chưa có chứng minh.', 'My assumption that the shop opened early was wrong.', NULL, 'Giả định của tôi rằng cửa hàng mở cửa sớm đã sai bét.', '{"wordId":"assumption","ukIpa":"/əˈsʌmpʃən/","usIpa":"/əˈsʌmpʃən/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"Something accepted as true without definite proof.","vi":"giả định; điều phỏng đoán"},{"pos":"n.","en":"The act of taking on responsibility, power, or a role.","vi":"sự đảm nhận (trách nhiệm, quyền lực hoặc vai trò)"}],"examples":[{"en":"My assumption that the shop opened early was wrong.","vi":"Giả định của tôi rằng cửa hàng mở cửa sớm đã sai bét.","audioKind":"ex"},{"en":"The assumption that all young people possess advanced digital skills may lead to inadequate support in schools.","vi":"Giả định rằng tất cả người trẻ tuổi đều sở hữu kỹ năng số nâng cao có thể dẫn đến việc cung cấp sự hỗ trợ chưa thỏa đáng trong nhà trường.","audioKind":"ex2"}],"collocations":[{"en":"make an assumption","vi":"đưa ra giả định"},{"en":"underlying assumption","vi":"giả định ngầm"},{"en":"challenge an assumption","vi":"thách thức một giả định"},{"en":"assumption of responsibility","vi":"sự gánh vác trách nhiệm"}],"wordFamily":["assume (v.)","assumed (adj.)"],"synonyms":["supposition","presumption"],"antonyms":[],"tipVi":"Thường đi với mệnh đề assumption that, chỉ quan điểm được chấp nhận mà chưa có chứng minh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_implication', 'en-b2-36', 'implication', '/ˌɪmplɪˈkeɪʃən/', 'B2', 'hệ quả; tác động tiềm ẩn; ngụ ý; ẩn ý; sự dính líu; sự liên lụy', 'n.', 'imply (v.), implicate (v.), implicit (adj.)', NULL, 'Nghĩa chỉ tác động tiềm ẩn thường dùng số nhiều implications và đi với giới từ for.', 'We discussed the financial implications of buying a puppy.', NULL, 'Chúng tôi đã thảo luận về những hệ quả tài chính của việc nuôi một chú chó con.', '{"wordId":"implication","ukIpa":"/ˌɪmplɪˈkeɪʃən/","usIpa":"/ˌɪmplɪˈkeɪʃən/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"a possible effect or consequence of an action or decision","vi":"hệ quả; tác động tiềm ẩn"},{"pos":"n.","en":"an idea suggested without being stated directly","vi":"ngụ ý; ẩn ý"},{"pos":"n.","en":"involvement in something wrong or illegal","vi":"sự dính líu; sự liên lụy"}],"examples":[{"en":"We discussed the financial implications of buying a puppy.","vi":"Chúng tôi đã thảo luận về những hệ quả tài chính của việc nuôi một chú chó con.","audioKind":"ex"},{"en":"Policymakers must consider the long-term implications of automation for employment, education, and social equality.","vi":"Các nhà hoạch định chính sách phải xem xét những tác động lâu dài của tự động hóa đối với việc làm, giáo dục và bình đẳng xã hội.","audioKind":"ex2"}],"collocations":[{"en":"implications for employment","vi":"tác động đối với việc làm"},{"en":"far-reaching implications","vi":"hệ quả sâu sắc"},{"en":"by implication","vi":"theo hàm ý"}],"wordFamily":["imply (v.)","implicate (v.)","implicit (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa chỉ tác động tiềm ẩn thường dùng số nhiều implications và đi với giới từ for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exception', 'en-b2-36', 'exception', '/ɪkˈsepʃən/', 'B2', 'ngoại lệ; sự phản đối; sự khiếu nại', 'n.', 'exceptional (adj.), exceptionally (adv.)', NULL, 'Quy tắc ngoại lệ dùng exception to, không dùng exception of.', 'Everyone enjoyed the soup, with the exception of my brother.', NULL, 'Mọi người đều thích món súp, ngoại trừ anh trai tôi.', '{"wordId":"exception","ukIpa":"/ɪkˈsepʃən/","usIpa":"/ɪkˈsepʃən/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"someone or something not included in a general rule or pattern","vi":"ngoại lệ"},{"pos":"n.","en":"an objection, especially in the phrase take exception to","vi":"sự phản đối; sự khiếu nại"}],"examples":[{"en":"Everyone enjoyed the soup, with the exception of my brother.","vi":"Mọi người đều thích món súp, ngoại trừ anh trai tôi.","audioKind":"ex"},{"en":"Although public transport is generally affordable, rural communities often represent an exception because services are limited.","vi":"Mặc dù phương tiện giao thông công cộng thường có giá cả phải chăng, các cộng đồng nông thôn thường là một ngoại lệ vì dịch vụ ở đây còn hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"an exception to the rule","vi":"một ngoại lệ của quy tắc"},{"en":"with the exception of","vi":"ngoại trừ"},{"en":"make an exception","vi":"phá lệ"},{"en":"take exception to","vi":"phản đối; không bằng lòng"}],"wordFamily":["exceptional (adj.)","exceptionally (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Quy tắc ngoại lệ dùng exception to, không dùng exception of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_consideration', 'en-b2-36', 'consideration', '/kənˌsɪdəˈreɪʃən/', 'B2', 'sự cân nhắc; sự suy xét; sự quan tâm; sự chu đáo; yếu tố cần xem xét', 'n.', 'consider (v.), considerate (adj.), considered (adj.)', NULL, 'Khi mang nghĩa cân nhắc hay sự quan tâm, từ này thường không đếm được; khi chỉ yếu tố cân nhắc thì đếm được.', 'After careful consideration, we chose the smaller flat.', NULL, 'Sau khi cân nhắc kỹ lưỡng, chúng tôi đã chọn căn hộ nhỏ hơn.', '{"wordId":"consideration","ukIpa":"/kənˌsɪdəˈreɪʃən/","usIpa":"/kənˌsɪdəˈreɪʃən/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"Careful thought about something before making a decision.","vi":"sự cân nhắc; sự suy xét"},{"pos":"n.","en":"Care for other people''s feelings, needs, or comfort.","vi":"sự quan tâm; sự chu đáo"},{"pos":"n.","en":"Something important to think about when making a decision.","vi":"yếu tố cần xem xét"}],"examples":[{"en":"After careful consideration, we chose the smaller flat.","vi":"Sau khi cân nhắc kỹ lưỡng, chúng tôi đã chọn căn hộ nhỏ hơn.","audioKind":"ex"},{"en":"Urban planners should take the needs of older residents into consideration when designing public transport systems.","vi":"Các nhà quy hoạch đô thị nên xem xét nhu cầu của cư dân cao tuổi khi thiết kế các hệ thống giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"careful consideration","vi":"sự cân nhắc kỹ lưỡng"},{"en":"take into consideration","vi":"xem xét đến; tính đến"},{"en":"under consideration","vi":"đang được xem xét"},{"en":"show consideration for","vi":"thể hiện sự chu đáo đối với"}],"wordFamily":["consider (v.)","considerate (adj.)","considered (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi mang nghĩa cân nhắc hay sự quan tâm, từ này thường không đếm được; khi chỉ yếu tố cân nhắc thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_classify', 'en-b2-36', 'classify', '/ˈklæsɪfaɪ/', 'B2', 'phân loại; xếp loại; xếp vào diện bảo mật; liệt vào loại mật', 'v.', 'classification (n.), classified (adj.), unclassified (adj.)', 'Đồng nghĩa: categorise, group', 'Cấu trúc classify A as B có nghĩa là "xếp A vào nhóm B / phân loại A là B".', 'We classify our books by subject on separate shelves.', NULL, 'Chúng tôi phân loại sách theo chủ đề trên các giá sách riêng biệt.', '{"wordId":"classify","ukIpa":"/ˈklæsɪfaɪ/","usIpa":"/ˈklæsɪfaɪ/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"To arrange things in groups according to shared characteristics.","vi":"phân loại; xếp loại"},{"pos":"v.","en":"To officially restrict access to sensitive information.","vi":"xếp vào diện bảo mật; liệt vào loại mật"}],"examples":[{"en":"We classify our books by subject on separate shelves.","vi":"Chúng tôi phân loại sách theo chủ đề trên các giá sách riêng biệt.","audioKind":"ex"},{"en":"Researchers classify household waste into several categories to identify which materials could be recycled more effectively.","vi":"Các nhà nghiên cứu phân loại rác thải sinh hoạt thành nhiều nhóm khác nhau để xác định vật liệu nào có thể tái chế hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"classify as","vi":"phân loại là"},{"en":"classify according to","vi":"phân loại theo"},{"en":"classify information","vi":"xếp thông tin vào diện mật"}],"wordFamily":["classification (n.)","classified (adj.)","unclassified (adj.)"],"synonyms":["categorise","group"],"antonyms":[],"tipVi":"Cấu trúc classify A as B có nghĩa là \"xếp A vào nhóm B / phân loại A là B\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 28, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_36_1', 'en-b2-36', 'Cách dùng “sane” (adj.) — hợp lý; sáng suốt', 'a sane approach  ·  a sane decision  ·  keep someone sane', 'Khi chỉ sự sáng suốt, từ này có nét nghĩa gần với sensible; không phải mọi bệnh lý tâm thần đều ảnh hưởng đến sự tỉnh táo này.', 'Họ từ (Word Family): sanity (n.), insane (adj.), insanity (n.) | Đồng nghĩa: sensible, rational · Trái nghĩa: irrational, insane', '[{"hanzi":"Taking a short break seemed like the only sane choice.","pinyin":"","meaning":"Tranh thủ nghỉ ngơi chốc lát có vẻ là lựa chọn sáng suốt duy nhất."},{"hanzi":"A sane approach to urban planning balances economic growth with residents'' need for green spaces.","pinyin":"","meaning":"Một cách tiếp cận hợp lý trong quy hoạch đô thị là cân bằng giữa tăng trưởng kinh tế và nhu cầu về không gian xanh của cư dân."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_36_2', 'en-b2-36', 'Cách dùng “genius” (n.) — thiên tài', 'a mathematical genius  ·  creative genius  ·  a genius at', 'Khi chỉ người thiên tài thì dùng như danh từ đếm được; khi chỉ tài năng phi thường thì thường là danh từ không đếm được.', NULL, '[{"hanzi":"My sister is a genius at fixing broken toys.","pinyin":"","meaning":"Chị gái tôi là một thiên tài trong việc sửa chữa đồ chơi hỏng."},{"hanzi":"Creative genius often develops when schools allow students to experiment rather than simply memorise facts.","pinyin":"","meaning":"Tài năng sáng tạo thường phát triển khi trường học cho phép học sinh thử nghiệm thay vì chỉ ghi nhớ kiến thức."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_36_3', 'en-b2-36', 'Cách dùng “pursuit” (n.) — sự theo đuổi; sự mưu cầu', 'in pursuit of  ·  the pursuit of knowledge  ·  leisure pursuits', 'Khi mang nghĩa theo đuổi hoặc truy đuổi thì thường là danh từ không đếm được; khi chỉ sở thích giải trí thì đếm được.', 'Họ từ (Word Family): pursue (v.), pursuer (n.)', '[{"hanzi":"Her pursuit of happiness led her to gardening.","pinyin":"","meaning":"Việc tìm kiếm hạnh phúc đã đưa cô ấy đến với công việc làm vườn."},{"hanzi":"The pursuit of economic growth should not come at the expense of environmental protection.","pinyin":"","meaning":"Việc theo đuổi tăng trưởng kinh tế không nên đánh đổi bằng việc hy sinh bảo vệ môi trường."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_36_4', 'en-b2-36', 'Cách dùng “convinced” (adj.) — tin chắc; hoàn toàn tin tưởng', 'convinced that  ·  convinced of  ·  fully convinced', 'Khi diễn tả con người cảm thấy tin chắc, dùng convinced; khi nói về sự việc có tính thuyết phục, dùng convincing.', 'Họ từ (Word Family): convince (v.), convincing (adj.), convincingly (adv.), unconvinced (adj.) | Đồng nghĩa: certain, sure · Trái nghĩa: unconvinced, doubtful', '[{"hanzi":"I''m convinced I left my keys on the kitchen table.","pinyin":"","meaning":"Tôi chắc chắn rằng mình đã để chìa khóa trên bàn bếp."},{"hanzi":"Many researchers are convinced that regular physical activity contributes significantly to better mental health.","pinyin":"","meaning":"Nhiều nhà nghiên cứu tin chắc rằng việc vận động cơ thể thường xuyên góp phần đáng kể vào việc cải thiện sức khỏe tinh thần."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_36_1', 'en-b2-36', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_36_1_1', 'ten_b2_36_1', 'deliberate', 'Leaving my phone at home was a deliberate choice.', 'Leaving my phone at home was a deliberate choice.', '/dɪˈlɪbərət/', 'Việc để điện thoại ở nhà là một lựa chọn có chủ ý của tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_36_1_2', 'ten_b2_36_1', 'justify', 'I cannot justify buying another coat this winter.', 'I cannot justify buying another coat this winter.', '/ˈdʒʌstɪfaɪ/', 'Tôi không thể biện minh cho việc mua thêm một chiếc áo khoác nữa vào mùa đông này.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_36_1_3', 'ten_b2_36_1', 'genius', 'My sister is a genius at fixing broken toys.', 'My sister is a genius at fixing broken toys.', '/ˈdʒiːniəs/', 'Chị gái tôi là một thiên tài trong việc sửa chữa đồ chơi hỏng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_36_1_4', 'ten_b2_36_1', 'enhance', 'A little lemon juice enhances the flavour of this soup.', 'A little lemon juice enhances the flavour of this soup.', '/ɪnˈhæns/', 'Một chút nước cốt chanh làm tăng hương vị của món súp này.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_36_1_5', 'ten_b2_36_1', 'self', 'After a good sleep, I felt like my usual self.', 'After a good sleep, I felt like my usual self.', '/self/', 'Sau một giấc ngủ ngon, tôi cảm thấy mình lại trở về trạng thái bình thường.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_36_1_6', 'ten_b2_36_1', 'proportion', 'A large proportion of my wages goes on rent.', 'A large proportion of my wages goes on rent.', '/prəˈpɔːrʃən/', 'Phần lớn tiền lương của tôi dùng để trả tiền thuê nhà.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_36_1_7', 'ten_b2_36_1', 'evident', 'Her relief was evident when the puppy returned.', 'Her relief was evident when the puppy returned.', '/ˈevɪdənt/', 'Sự nhẹ nhõm hiện rõ trên khuôn mặt cô ấy khi chú chó con quay về.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_36_1_8', 'ten_b2_36_1', 'intelligence', 'Her intelligence helped her solve the puzzle quickly.', 'Her intelligence helped her solve the puzzle quickly.', '/ɪnˈtelɪdʒəns/', 'Sự thông minh đã giúp cô ấy giải câu đố một cách nhanh chóng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_36_1_1', 'en-b2-36', 'ten_b2_36_1', 'listening', 'listening', 'Leaving my phone at home was a deliberate choice.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Việc để điện thoại ở nhà là một lựa chọn có chủ ý của tôi.","Vui lòng mang theo bất kỳ tài liệu nào liên quan đến đơn đăng ký của bạn.","Sự nhẹ nhõm hiện rõ trên khuôn mặt cô ấy khi chú chó con quay về.","Mọi người đều thích món súp, ngoại trừ anh trai tôi."]'::jsonb, 0, 'Leaving my phone at home was a deliberate choice. → Việc để điện thoại ở nhà là một lựa chọn có chủ ý của tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_36_1_2', 'en-b2-36', 'ten_b2_36_1', 'listening', 'listening', 'I cannot justify buying another coat this winter.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi không thể biện minh cho việc mua thêm một chiếc áo khoác nữa vào mùa đông này.","Mọi người đều thích món súp, ngoại trừ anh trai tôi.","Sau một giấc ngủ ngon, tôi cảm thấy mình lại trở về trạng thái bình thường.","Sự thông minh đã giúp cô ấy giải câu đố một cách nhanh chóng."]'::jsonb, 0, 'I cannot justify buying another coat this winter. → Tôi không thể biện minh cho việc mua thêm một chiếc áo khoác nữa vào mùa đông này.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_36_1_3', 'en-b2-36', 'ten_b2_36_1', 'listening', 'listening', 'My sister is a genius at fixing broken toys.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chị gái tôi là một thiên tài trong việc sửa chữa đồ chơi hỏng.","Một con vịt đã làm xao động hình bóng của những ngọn núi trên mặt hồ.","Tôi chẳng hề biết gì về các quy tắc đó cho đến khi có người giải thích.","Chúng tôi đã thảo luận về những hệ quả tài chính của việc nuôi một chú chó con."]'::jsonb, 0, 'My sister is a genius at fixing broken toys. → Chị gái tôi là một thiên tài trong việc sửa chữa đồ chơi hỏng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_36_2', 'en-b2-36', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_36_2_1', 'ten_b2_36_2', 'deliberate', 'Local authorities should deliberate carefully before approving developments that could permanently damage natural habitats.', 'Local authorities should deliberate carefully before approving developments that could permanently damage natural habitats.', '/dɪˈlɪbərət/', 'Các cơ quan chức năng địa phương nên cân nhắc kỹ lưỡng trước khi phê duyệt các dự án phát triển có thể gây tổn hại vĩnh viễn đến môi trường sống tự nhiên.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_36_2_2', 'ten_b2_36_2', 'justify', 'Governments must justify major infrastructure spending by demonstrating clear benefits for the wider community.', 'Governments must justify major infrastructure spending by demonstrating clear benefits for the wider community.', '/ˈdʒʌstɪfaɪ/', 'Chính phủ phải chứng minh tính hợp lý của các khoản chi tiêu lớn cho cơ sở hạ tầng bằng cách chỉ ra những lợi ích rõ ràng cho cộng đồng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_36_2_3', 'ten_b2_36_2', 'genius', 'Creative genius often develops when schools allow students to experiment rather than simply memorise facts.', 'Creative genius often develops when schools allow students to experiment rather than simply memorise facts.', '/ˈdʒiːniəs/', 'Tài năng sáng tạo thường phát triển khi trường học cho phép học sinh thử nghiệm thay vì chỉ ghi nhớ kiến thức.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_36_2_4', 'ten_b2_36_2', 'enhance', 'Access to green spaces can enhance residents'' wellbeing and encourage more active lifestyles in crowded cities.', 'Access to green spaces can enhance residents'' wellbeing and encourage more active lifestyles in crowded cities.', '/ɪnˈhæns/', 'Việc tiếp cận không gian xanh có thể nâng cao sức khỏe tinh thần của cư dân và khuyến khích lối sống năng động hơn ở các thành phố đông đúc.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_36_2_5', 'ten_b2_36_2', 'self', 'Creative activities can help young people develop a stronger sense of self during periods of rapid change.', 'Creative activities can help young people develop a stronger sense of self during periods of rapid change.', '/self/', 'Các hoạt động sáng tạo có thể giúp người trẻ hình thành ý thức về bản thân mạnh mẽ hơn trong những giai đoạn thay đổi nhanh chóng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_36_2_6', 'ten_b2_36_2', 'proportion', 'The proportion of residents using public transport increased after the city introduced cheaper monthly passes.', 'The proportion of residents using public transport increased after the city introduced cheaper monthly passes.', '/prəˈpɔːrʃən/', 'Tỷ lệ cư dân sử dụng phương tiện giao thông công cộng đã tăng lên sau khi thành phố triển khai vé tháng giá rẻ hơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_36_2_1', 'en-b2-36', 'ten_b2_36_2', 'listening', 'listening', 'Local authorities should deliberate carefully before approving developments that could permanently damage natural habitats.', NULL, 'Trong câu vừa nghe, từ “deliberate” mang nghĩa nào sau đây?', '["làm sáng lên; làm rực rỡ hơn","chính xác; tỉ mỉ","cố ý; chủ tâm","mở rộng; làm lớn hơn"]'::jsonb, 2, '“deliberate” (/dɪˈlɪbərət/): cố ý; chủ tâm. Câu đầy đủ: Local authorities should deliberate carefully before approving developments that could permanently damage natural habitats.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_36_2_2', 'en-b2-36', 'ten_b2_36_2', 'listening', 'listening', 'Governments must justify major infrastructure spending by demonstrating clear benefits for the wider community.', NULL, 'Trong câu vừa nghe, từ “justify” mang nghĩa nào sau đây?', '["vô cùng; cực kỳ","băng đảng; nhóm tội phạm","biện minh; chứng minh là hợp lý","lông vũ; chiếc lông chim"]'::jsonb, 2, '“justify” (/ˈdʒʌstɪfaɪ/): biện minh; chứng minh là hợp lý. Câu đầy đủ: Governments must justify major infrastructure spending by demonstrating clear benefits for the wider community.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
