INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_36_2', 'en-b2-36', NULL, 'comprehensive_test', 'listening', 'I cannot justify buying another coat this winter.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi chắc chắn rằng mình đã để chìa khóa trên bàn bếp.","Chị gái tôi là một thiên tài trong việc sửa chữa đồ chơi hỏng.","Hóa đơn thực tế thấp hơn nhiều so với chúng tôi mong đợi.","Tôi không thể biện minh cho việc mua thêm một chiếc áo khoác nữa vào mùa đông này."]'::jsonb, 3, 'I cannot justify buying another coat this winter. → Tôi không thể biện minh cho việc mua thêm một chiếc áo khoác nữa vào mùa đông này.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_36_3', 'en-b2-36', NULL, 'comprehensive_test', 'listening', 'genius', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thiên tài","tiếng La-tinh","phai màu; làm phai màu","diễn giải bằng từ ngữ khác; nói cách khác"]'::jsonb, 0, 'genius (/ˈdʒiːniəs/) → thiên tài; tài năng thiên bẩm; năng khiếu phi thường', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_36_4', 'en-b2-36', NULL, 'comprehensive_test', 'listening', 'A little lemon juice enhances the flavour of this soup.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi không thể biện minh cho việc mua thêm một chiếc áo khoác nữa vào mùa đông này.","Hoàn thành bức tranh ghép này trong tối nay không phải là một mục tiêu thực tế.","Giả định của tôi rằng cửa hàng mở cửa sớm đã sai bét.","Một chút nước cốt chanh làm tăng hương vị của món súp này."]'::jsonb, 3, 'A little lemon juice enhances the flavour of this soup. → Một chút nước cốt chanh làm tăng hương vị của món súp này.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_36_5', 'en-b2-36', NULL, 'comprehensive_test', 'listening', 'self', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tính đa dạng; sự phong phú","run rẩy; đánh cầm cập","bản thân; cái tôi","tính từ: vỡ lòng; nhập môn; giới thiệu"]'::jsonb, 2, 'self (/self/) → bản thân; cái tôi', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_36_6', 'en-b2-36', NULL, 'comprehensive_test', 'listening', 'A large proportion of my wages goes on rent.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cuối cùng tôi đã hiểu được ý nghĩa đằng sau nụ cười nhẹ nhàng của cô ấy.","Việc tìm kiếm hạnh phúc đã đưa cô ấy đến với công việc làm vườn.","Sự thông minh đã giúp cô ấy giải câu đố một cách nhanh chóng.","Phần lớn tiền lương của tôi dùng để trả tiền thuê nhà."]'::jsonb, 3, 'A large proportion of my wages goes on rent. → Phần lớn tiền lương của tôi dùng để trả tiền thuê nhà.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_36_7', 'en-b2-36', NULL, 'comprehensive_test', 'listening', 'evident', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nhân tạo; giả","rõ ràng; hiển nhiên; dễ nhận thấy","vô cùng, hết sức, sâu sắc (về cảm xúc hoặc niềm tin)","bóp; véo; kẹp"]'::jsonb, 1, 'evident (/ˈevɪdənt/) → rõ ràng; hiển nhiên; dễ nhận thấy', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_36_8', 'en-b2-36', NULL, 'comprehensive_test', 'listening', 'Her intelligence helped her solve the puzzle quickly.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Giáo viên đã dùng những chiếc xe đồ chơi để giải thích khái niệm này.","Bạn chắc chắn sẽ cảm thấy mệt sau một quãng đường đi bộ dài như vậy.","Tôi chẳng hề biết gì về các quy tắc đó cho đến khi có người giải thích.","Sự thông minh đã giúp cô ấy giải câu đố một cách nhanh chóng."]'::jsonb, 3, 'Her intelligence helped her solve the puzzle quickly. → Sự thông minh đã giúp cô ấy giải câu đố một cách nhanh chóng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_36_9', 'en-b2-36', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “The personality and qualities that make you who you are.”?', '["exception","evident","self","realistic"]'::jsonb, 2, 'self (/self/) → bản thân; cái tôi', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
