INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_36_18', 'en-b2-36', NULL, 'comprehensive_test', 'reading', NULL, 'Local authorities should deliberate carefully before approving developments that could permanently damage natural habitats.', 'Dựa vào câu trên, từ “deliberate” có nghĩa phù hợp nhất là gì?', '["sự cố gắng; nỗ lực","cố ý; chủ tâm","cột mốc quan trọng; bước ngoặt","bỏ sót; không chú ý"]'::jsonb, 1, 'deliberate: cố ý; chủ tâm; thận trọng; từ tốn; thong thả; cân nhắc kỹ lưỡng; thảo luận. Dịch cả câu: Các cơ quan chức năng địa phương nên cân nhắc kỹ lưỡng trước khi phê duyệt các dự án phát triển có thể gây tổn hại vĩnh viễn đến môi trường sống tự nhiên.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_36_19', 'en-b2-36', NULL, 'comprehensive_test', 'reading', NULL, 'Governments must justify major infrastructure spending by demonstrating clear benefits for the wider community.', 'Dựa vào câu trên, từ “justify” có nghĩa phù hợp nhất là gì?', '["sự nhiễm trùng; bệnh truyền nhiễm","kỷ luật; tính tự giác","sự phong phú; tính đa dạng","biện minh; chứng minh là hợp lý"]'::jsonb, 3, 'justify: biện minh; chứng minh là hợp lý. Dịch cả câu: Chính phủ phải chứng minh tính hợp lý của các khoản chi tiêu lớn cho cơ sở hạ tầng bằng cách chỉ ra những lợi ích rõ ràng cho cộng đồng.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_36_20', 'en-b2-36', NULL, 'comprehensive_test', 'reading', NULL, 'Creative genius often develops when schools allow students to experiment rather than simply memorise facts.', 'Dựa vào câu trên, từ “genius” có nghĩa phù hợp nhất là gì?', '["thiên tài","vĩnh cửu; bất tận","hoàn toàn; cực kỳ; tuyệt đối","cuối cùng; sau một chuỗi sự kiện"]'::jsonb, 0, 'genius: thiên tài; tài năng thiên bẩm; năng khiếu phi thường. Dịch cả câu: Tài năng sáng tạo thường phát triển khi trường học cho phép học sinh thử nghiệm thay vì chỉ ghi nhớ kiến thức.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_36_21', 'en-b2-36', NULL, 'comprehensive_test', 'reading', NULL, 'Access to green spaces can enhance residents'' wellbeing and encourage more active lifestyles in crowded cities.', 'Dựa vào câu trên, từ “enhance” có nghĩa phù hợp nhất là gì?', '["nâng cao; tăng cường; cải thiện","động từ: nghi ngờ; phỏng đoán","xây dựng lại; tái thiết","sự tự lập; tính tự chủ"]'::jsonb, 0, 'enhance: nâng cao; tăng cường; cải thiện. Dịch cả câu: Việc tiếp cận không gian xanh có thể nâng cao sức khỏe tinh thần của cư dân và khuyến khích lối sống năng động hơn ở các thành phố đông đúc.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_36_22', 'en-b2-36', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ngoại lệ”', '["formal","stab","presence","exception"]'::jsonb, 3, 'ngoại lệ → exception (/ɪkˈsepʃən/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_36_23', 'en-b2-36', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự cân nhắc; sự suy xét”', '["pit","ounce","division","consideration"]'::jsonb, 3, 'sự cân nhắc; sự suy xét → consideration (/kənˌsɪdəˈreɪʃən/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_36_24', 'en-b2-36', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “phân loại; xếp loại”', '["beneath","classify","minimal","sword"]'::jsonb, 1, 'phân loại; xếp loại → classify (/ˈklæsɪfaɪ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-37', 'en', 'Bài 37: Tư duy & Nhận thức (4) - CEFR B2', 'CEFR B2', 'B2 · Tư duy', '28 từ vựng Tiếng Anh CEFR B2 chủ đề tư duy & nhận thức kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4037, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_foresee', 'en-b2-37', 'foresee', '/fɔːrˈsiː/', 'B2', 'dự đoán; thấy trước', 'v.', 'foreseeable (adj.), unforeseen (adj.)', 'Đồng nghĩa: anticipate, predict', 'Dạng quá khứ là foresaw, quá khứ phân từ là foreseen.', 'We didn''t foresee such a long queue outside.', NULL, 'Chúng tôi đã không lường trước được hàng người chờ dài như vậy ở bên ngoài.', '{"wordId":"foresee","ukIpa":"/fɔːˈsiː/","usIpa":"/fɔːrˈsiː/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"to know or expect something before it happens","vi":"dự đoán; thấy trước"}],"examples":[{"en":"We didn''t foresee such a long queue outside.","vi":"Chúng tôi đã không lường trước được hàng người chờ dài như vậy ở bên ngoài.","audioKind":"ex"},{"en":"Urban planners must foresee future transport needs before approving major housing developments on the city''s outskirts.","vi":"Các nhà quy hoạch đô thị phải dự đoán nhu cầu giao thông trong tương lai trước khi phê duyệt các dự án phát triển nhà ở quy mô lớn ở vùng ngoại ô thành phố.","audioKind":"ex2"}],"collocations":[{"en":"foresee problems","vi":"dự đoán vấn đề"},{"en":"foresee consequences","vi":"lường trước hậu quả"},{"en":"difficult to foresee","vi":"khó lường trước"}],"wordFamily":["foreseeable (adj.)","unforeseen (adj.)"],"synonyms":["anticipate","predict"],"antonyms":[],"tipVi":"Dạng quá khứ là foresaw, quá khứ phân từ là foreseen.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_analyze', 'en-b2-37', 'analyze', '/ˈænəlaɪz/', 'B2', 'phân tích', 'v.', 'analysis (n.), analyst (n.), analytical (adj.), analytically (adv.)', 'Đồng nghĩa: examine, investigate', 'Cách viết theo kiểu Mỹ là analyze, trong khi tiếng Anh - Anh thường viết là analyse.', 'We analyzed our spending before planning the next holiday.', NULL, 'Chúng tôi đã phân tích các khoản chi tiêu của mình trước khi lên kế hoạch cho chuyến nghỉ dưỡng tiếp theo.', '{"wordId":"analyze","ukIpa":"/ˈænəlaɪz/","usIpa":"/ˈænəlaɪz/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"Examine something carefully to understand its parts or meaning.","vi":"phân tích"}],"examples":[{"en":"We analyzed our spending before planning the next holiday.","vi":"Chúng tôi đã phân tích các khoản chi tiêu của mình trước khi lên kế hoạch cho chuyến nghỉ dưỡng tiếp theo.","audioKind":"ex"},{"en":"Researchers analyze traffic patterns to identify areas where improved public transport could reduce congestion.","vi":"Các nhà nghiên cứu phân tích các mẫu hình giao thông để xác định những khu vực mà việc cải thiện giao thông công cộng có thể làm giảm tình trạng tắc nghẽn.","audioKind":"ex2"}],"collocations":[{"en":"analyze data","vi":"phân tích dữ liệu"},{"en":"analyze results","vi":"phân tích kết quả"},{"en":"analyze a problem","vi":"phân tích một vấn đề"}],"wordFamily":["analysis (n.)","analyst (n.)","analytical (adj.)","analytically (adv.)"],"synonyms":["examine","investigate"],"antonyms":[],"tipVi":"Cách viết theo kiểu Mỹ là analyze, trong khi tiếng Anh - Anh thường viết là analyse.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_significant', 'en-b2-37', 'significant', '/sɪɡˈnɪfɪkənt/', 'B2', 'đáng kể; quan trọng; lớn; mang ý nghĩa sâu xa; có ẩn ý', 'adj.', 'significance (n.), significantly (adv.), insignificant (adj.)', 'Đồng nghĩa: important, notable · Trái nghĩa: insignificant, negligible', 'Trong thống kê, significant chỉ đạt mức ý nghĩa thống kê, không đồng nghĩa với việc tác động thực tế lớn.', 'Moving closer to work made a significant difference to me.', NULL, 'Việc chuyển đến gần chỗ làm hơn đã tạo ra một sự thay đổi đáng kể đối với tôi.', '{"wordId":"significant","ukIpa":"/sɪɡˈnɪfɪkənt/","usIpa":"/sɪɡˈnɪfɪkənt/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"large or important enough to deserve attention","vi":"đáng kể; quan trọng; lớn"},{"pos":"adj.","en":"expressing a meaning that is not directly stated","vi":"mang ý nghĩa sâu xa; có ẩn ý"}],"examples":[{"en":"Moving closer to work made a significant difference to me.","vi":"Việc chuyển đến gần chỗ làm hơn đã tạo ra một sự thay đổi đáng kể đối với tôi.","audioKind":"ex"},{"en":"Access to reliable internet services has a significant impact on educational opportunities in remote communities.","vi":"Khả năng tiếp cận các dịch vụ Internet đáng tin cậy có tác động quan trọng đến các cơ hội giáo dục ở các cộng đồng vùng sâu vùng xa.","audioKind":"ex2"}],"collocations":[{"en":"a significant increase","vi":"sự gia tăng đáng kể"},{"en":"a significant impact","vi":"tác động đáng kể"},{"en":"statistically significant","vi":"có ý nghĩa thống kê"},{"en":"a significant glance","vi":"một cái nhìn đầy ẩn ý"}],"wordFamily":["significance (n.)","significantly (adv.)","insignificant (adj.)"],"synonyms":["important","notable"],"antonyms":["insignificant","negligible"],"tipVi":"Trong thống kê, significant chỉ đạt mức ý nghĩa thống kê, không đồng nghĩa với việc tác động thực tế lớn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_overall', 'en-b2-37', 'overall', '/ˌoʊvərˈɔːl/', 'B2', 'tổng thể; toàn bộ; chung; nhìn chung; tổng quan; nói chung', 'adj.', NULL, 'Đồng nghĩa: total, general', 'Tính từ đặt trước danh từ; trạng từ có thể đặt đầu câu để khái quát tổng thể tình hình.', 'The overall cost includes breakfast and a train ticket.', NULL, 'Tổng chi phí đã bao gồm bữa sáng và một vé tàu.', '{"wordId":"overall","ukIpa":"/ˌəʊvərˈɔːl/","usIpa":"/ˌoʊvərˈɔːl/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"considering or including every part of something","vi":"tổng thể; toàn bộ; chung"},{"pos":"adv.","en":"when everything is considered together","vi":"nhìn chung; tổng quan; nói chung"}],"examples":[{"en":"The overall cost includes breakfast and a train ticket.","vi":"Tổng chi phí đã bao gồm bữa sáng và một vé tàu.","audioKind":"ex"},{"en":"Overall, investment in public transport can reduce urban congestion while improving access to employment opportunities.","vi":"Nhìn chung, việc đầu tư vào giao thông công cộng có thể làm giảm tình trạng tắc nghẽn đô thị đồng thời cải thiện khả năng tiếp cận các cơ hội việc làm.","audioKind":"ex2"}],"collocations":[{"en":"overall cost","vi":"tổng chi phí"},{"en":"overall performance","vi":"hiệu suất tổng thể"},{"en":"overall impact","vi":"tác động tổng thể"},{"en":"overall improvement","vi":"sự cải thiện toàn diện"}],"wordFamily":[],"synonyms":["total","general"],"antonyms":[],"tipVi":"Tính từ đặt trước danh từ; trạng từ có thể đặt đầu câu để khái quát tổng thể tình hình.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_undoubtedly', 'en-b2-37', 'undoubtedly', '/ʌnˈdaʊtɪdli/', 'B2', 'chắc chắn; không nghi ngờ gì; rõ ràng là', 'adv.', 'doubt (n.), doubtful (adj.), undoubted (adj.)', 'Đồng nghĩa: certainly, unquestionably · Trái nghĩa: doubtfully', 'Sắc thái khẳng định rất mạnh; khi thiếu bằng chứng nên dùng các từ giảm nhẹ như probably.', 'This is undoubtedly the warmest coat I have ever owned.', NULL, 'Đây chắc chắn là chiếc áo khoác ấm nhất mà tôi từng có.', '{"wordId":"undoubtedly","ukIpa":"/ʌnˈdaʊtɪdli/","usIpa":"/ʌnˈdaʊtɪdli/","cefr":"B2","topic":"thinking","senses":[{"pos":"adv.","en":"Certainly true, with no reasonable doubt.","vi":"chắc chắn; không nghi ngờ gì; rõ ràng là"}],"examples":[{"en":"This is undoubtedly the warmest coat I have ever owned.","vi":"Đây chắc chắn là chiếc áo khoác ấm nhất mà tôi từng có.","audioKind":"ex"},{"en":"Access to clean drinking water undoubtedly improves public health, particularly in communities with limited medical services.","vi":"Việc tiếp cận nguồn nước uống sạch chắc chắn sẽ cải thiện sức khỏe cộng đồng, đặc biệt là ở những cộng đồng có dịch vụ y tế hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"undoubtedly true","vi":"chắc chắn đúng"},{"en":"undoubtedly important","vi":"chắc chắn quan trọng"},{"en":"will undoubtedly benefit","vi":"chắc chắn sẽ mang lại lợi ích"}],"wordFamily":["doubt (n.)","doubtful (adj.)","undoubted (adj.)"],"synonyms":["certainly","unquestionably"],"antonyms":["doubtfully"],"tipVi":"Sắc thái khẳng định rất mạnh; khi thiếu bằng chứng nên dùng các từ giảm nhẹ như probably.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_specific', 'en-b2-37', 'specific', '/spəˈsɪfɪk/', 'B2', 'cụ thể; riêng biệt; rõ ràng; chi tiết; đặc thù; đặc trưng', 'adj.', 'specifically (adv.), specify (v.), specification (n.), specificity (n.)', 'Đồng nghĩa: particular, precise · Trái nghĩa: general, vague', 'Cụm từ "specific to" có nghĩa là "đặc trưng hoặc dành riêng cho..."', 'Is there a specific colour you would prefer?', NULL, 'Bạn có thích một màu cụ thể nào không?', '{"wordId":"specific","ukIpa":"/spəˈsɪfɪk/","usIpa":"/spəˈsɪfɪk/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"relating to one particular thing rather than things in general","vi":"cụ thể; riêng biệt"},{"pos":"adj.","en":"giving exact details rather than general information","vi":"rõ ràng; chi tiết"},{"pos":"adj.","en":"found only in a particular person, place, or thing","vi":"đặc thù; đặc trưng"}],"examples":[{"en":"Is there a specific colour you would prefer?","vi":"Bạn có thích một màu cụ thể nào không?","audioKind":"ex"},{"en":"Governments should set specific targets for reducing air pollution so that progress can be measured accurately.","vi":"Chính phủ nên đặt ra các mục tiêu cụ thể để giảm thiểu ô nhiễm không khí nhằm đo lường tiến độ một cách chính xác.","audioKind":"ex2"}],"collocations":[{"en":"specific needs","vi":"nhu cầu cụ thể"},{"en":"specific details","vi":"chi tiết cụ thể"},{"en":"specific targets","vi":"mục tiêu cụ thể"},{"en":"specific to","vi":"đặc thù của"}],"wordFamily":["specifically (adv.)","specify (v.)","specification (n.)","specificity (n.)"],"synonyms":["particular","precise"],"antonyms":["general","vague"],"tipVi":"Cụm từ \"specific to\" có nghĩa là \"đặc trưng hoặc dành riêng cho...\"","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_assume', 'en-b2-37', 'assume', '/əˈsuːm/', 'B2', 'cho rằng; giả định; nghĩ rằng; đảm nhận; gánh vác; nhậm chức; mang; có được (vẻ ngoài hoặc tính chất)', 'v.', 'assumption (n.), assumed (adj.)', 'Đồng nghĩa: suppose, presume', 'Từ "assume" thường đi với mệnh đề "that", nhấn mạnh việc phỏng đoán mà chưa có bằng chứng xác thực.', 'Don''t assume the shop is open on Sundays.', NULL, 'Đừng vội cho rằng cửa hàng mở cửa vào Chủ nhật.', '{"wordId":"assume","ukIpa":"/əˈsjuːm/","usIpa":"/əˈsuːm/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"To accept something as true without having proof.","vi":"cho rằng; giả định; nghĩ rằng"},{"pos":"v.","en":"To take on a duty, responsibility, or position.","vi":"đảm nhận; gánh vác; nhậm chức"},{"pos":"v.","en":"To begin to have a particular appearance or quality.","vi":"mang; có được (vẻ ngoài hoặc tính chất)"}],"examples":[{"en":"Don''t assume the shop is open on Sundays.","vi":"Đừng vội cho rằng cửa hàng mở cửa vào Chủ nhật.","audioKind":"ex"},{"en":"Policymakers should not assume that all households have reliable internet access or adequate digital skills.","vi":"Các nhà hoạch định chính sách không nên mặc định rằng tất cả các hộ gia đình đều có kết nối Internet ổn định hoặc kỹ năng số đầy đủ.","audioKind":"ex2"}],"collocations":[{"en":"assume that","vi":"giả định rằng"},{"en":"assume responsibility","vi":"gánh vác trách nhiệm"},{"en":"assume office","vi":"nhậm chức"}],"wordFamily":["assumption (n.)","assumed (adj.)"],"synonyms":["suppose","presume"],"antonyms":[],"tipVi":"Từ \"assume\" thường đi với mệnh đề \"that\", nhấn mạnh việc phỏng đoán mà chưa có bằng chứng xác thực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_concentration', 'en-b2-37', 'concentration', '/ˌkɑːnsənˈtreɪʃən/', 'B2', 'sự tập trung; sự chuyên tâm; nồng độ; sự tập trung (số lượng lớn); sự tụ hội', 'n.', 'concentrate (v.), concentrated (adj.)', NULL, 'Nghĩa "sự tập trung" thường không đếm được; dùng "concentration of" để chỉ nồng độ của một chất.', 'The constant noise outside made concentration difficult for me.', NULL, 'Tiếng ồn liên tục bên ngoài khiến tôi khó tập trung.', '{"wordId":"concentration","ukIpa":"/ˌkɒnsənˈtreɪʃən/","usIpa":"/ˌkɑːnsənˈtreɪʃən/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"The ability to keep your attention on one activity.","vi":"sự tập trung; sự chuyên tâm"},{"pos":"n.","en":"The amount of a substance present in a mixture.","vi":"nồng độ"},{"pos":"n.","en":"A large amount of something gathered in one place.","vi":"sự tập trung (số lượng lớn); sự tụ hội"}],"examples":[{"en":"The constant noise outside made concentration difficult for me.","vi":"Tiếng ồn liên tục bên ngoài khiến tôi khó tập trung.","audioKind":"ex"},{"en":"High concentrations of air pollutants near busy roads can pose serious health risks to residents.","vi":"Nồng độ chất ô nhiễm không khí cao gần các tuyến đường đông đúc có thể gây ra những rủi ro nghiêm trọng cho sức khỏe cư dân.","audioKind":"ex2"}],"collocations":[{"en":"lose concentration","vi":"mất tập trung"},{"en":"improve concentration","vi":"cải thiện sự tập trung"},{"en":"a high concentration of","vi":"nồng độ cao của; sự tập trung lớn của"},{"en":"a concentration of wealth","vi":"sự tập trung của cải"}],"wordFamily":["concentrate (v.)","concentrated (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa \"sự tập trung\" thường không đếm được; dùng \"concentration of\" để chỉ nồng độ của một chất.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ultimately', 'en-b2-37', 'ultimately', '/ˈʌltɪmətli/', 'B2', 'cuối cùng; sau một chuỗi sự kiện; xem xét yếu tố cốt lõi nhất; suy cho cùng; gạt đi mọi thứ thì', 'adv.', 'ultimate (adj.)', 'Đồng nghĩa: eventually, in the end', 'Nhấn mạnh kết quả cuối cùng hoặc yếu tố cốt lõi, không dùng cho mục cuối cùng trong một danh sách liệt kê.', 'We explored several flats but ultimately chose this small house.', NULL, 'Chúng tôi đã xem qua vài căn hộ nhưng cuối cùng vẫn chọn ngôi nhà nhỏ này.', '{"wordId":"ultimately","ukIpa":"/ˈʌltɪmətli/","usIpa":"/ˈʌltɪmətli/","cefr":"B2","topic":"thinking","senses":[{"pos":"adv.","en":"in the end, after a series of events","vi":"cuối cùng; sau một chuỗi sự kiện"},{"pos":"adv.","en":"when considering the most important underlying fact","vi":"xem xét yếu tố cốt lõi nhất; suy cho cùng; gạt đi mọi thứ thì"}],"examples":[{"en":"We explored several flats but ultimately chose this small house.","vi":"Chúng tôi đã xem qua vài căn hộ nhưng cuối cùng vẫn chọn ngôi nhà nhỏ này.","audioKind":"ex"},{"en":"Although technology can support classroom learning, educational success ultimately depends on effective teaching and student engagement.","vi":"Mặc dù công nghệ có thể hỗ trợ việc học trên lớp, nhưng thành công trong giáo dục suy cho cùng vẫn phụ thuộc vào phương pháp giảng dạy hiệu quả và sự tham gia của học sinh.","audioKind":"ex2"}],"collocations":[{"en":"ultimately depend on","vi":"suy cho cùng phụ thuộc vào"},{"en":"ultimately lead to","vi":"cuối cùng dẫn đến"},{"en":"ultimately responsible","vi":"chịu trách nhiệm cuối cùng"}],"wordFamily":["ultimate (adj.)"],"synonyms":["eventually","in the end"],"antonyms":[],"tipVi":"Nhấn mạnh kết quả cuối cùng hoặc yếu tố cốt lõi, không dùng cho mục cuối cùng trong một danh sách liệt kê.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_contrary', 'en-b2-37', 'contrary', '/ˈkɑːntreri/', 'B2', 'trái ngược; tương phản; điều ngược lại', 'adj.', NULL, 'Đồng nghĩa: opposite', 'on the contrary dùng để đính chính quan điểm trước đó, mang nghĩa là hoàn toàn ngược lại.', 'Contrary to the forecast, sunshine filled our garden.', NULL, 'Trái với dự báo thời tiết, ánh nắng đã tràn ngập khu vườn của chúng tôi.', '{"wordId":"contrary","ukIpa":"/ˈkɒntrəri/","usIpa":"/ˈkɑːntreri/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"opposite to something or inconsistent with it","vi":"trái ngược; tương phản"},{"pos":"n.","en":"the opposite of what has been said or suggested","vi":"điều ngược lại"}],"examples":[{"en":"Contrary to the forecast, sunshine filled our garden.","vi":"Trái với dự báo thời tiết, ánh nắng đã tràn ngập khu vườn của chúng tôi.","audioKind":"ex"},{"en":"Contrary to popular belief, expanding road networks does not always reduce traffic congestion in major cities.","vi":"Trái ngược với quan niệm phổ biến, việc mở rộng mạng lưới đường bộ không phải lúc nào cũng làm giảm tình trạng tắc nghẽn giao thông ở các thành phố lớn.","audioKind":"ex2"}],"collocations":[{"en":"contrary to expectations","vi":"trái với mong đợi"},{"en":"contrary evidence","vi":"chứng cứ ngược lại"},{"en":"on the contrary","vi":"ngược lại; trái lại"},{"en":"to the contrary","vi":"trái với điều đó"}],"wordFamily":[],"synonyms":["opposite"],"antonyms":[],"tipVi":"on the contrary dùng để đính chính quan điểm trước đó, mang nghĩa là hoàn toàn ngược lại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_perfection', 'en-b2-37', 'perfection', '/pərˈfekʃn/', 'B2', 'sự hoàn hảo; tính toàn mỹ', 'n.', 'perfect (adj.), perfectly (adv.), perfectionist (n.), imperfection (n.)', 'Đồng nghĩa: flawlessness · Trái nghĩa: imperfection', 'Thường là danh từ không đếm được; to perfection diễn tả việc làm gì đó hoàn hảo, đúng mực.', 'The bread was baked to perfection, with a crisp crust.', NULL, 'Ổ bánh mì được nướng chín hoàn hảo với phần vỏ giòn rụm.', '{"wordId":"perfection","ukIpa":"/pəˈfekʃn/","usIpa":"/pərˈfekʃn/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"The state of being completely without faults or weaknesses","vi":"sự hoàn hảo; tính toàn mỹ"}],"examples":[{"en":"The bread was baked to perfection, with a crisp crust.","vi":"Ổ bánh mì được nướng chín hoàn hảo với phần vỏ giòn rụm.","audioKind":"ex"},{"en":"An excessive desire for perfection can increase students'' anxiety and discourage them from experimenting with new ideas.","vi":"Mong muốn đạt đến sự hoàn hảo một cách thái quá có thể làm gia tăng sự lo lắng của học sinh và khiến các em dè dặt trong việc thử nghiệm những ý tưởng mới.","audioKind":"ex2"}],"collocations":[{"en":"strive for perfection","vi":"nỗ lực đạt đến sự hoàn hảo"},{"en":"achieve perfection","vi":"đạt được sự hoàn hảo"},{"en":"to perfection","vi":"một cách hoàn hảo; hoàn mỹ"},{"en":"pursuit of perfection","vi":"sự theo đuổi sự hoàn hảo"}],"wordFamily":["perfect (adj.)","perfectly (adv.)","perfectionist (n.)","imperfection (n.)"],"synonyms":["flawlessness"],"antonyms":["imperfection"],"tipVi":"Thường là danh từ không đếm được; to perfection diễn tả việc làm gì đó hoàn hảo, đúng mực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_correspond', 'en-b2-37', 'correspond', '/ˌkɔːrəˈspɑːnd/', 'B2', 'tương ứng; phù hợp; thư tín; trao đổi thư từ', 'v.', 'correspondence (n.), corresponding (adj.), correspondingly (adv.), correspondent (n.)', 'Đồng nghĩa: match', 'Tương ứng thường dùng correspond to; liên lạc với ai dùng with.', 'The colours on these lids correspond to the containers.', NULL, 'Màu sắc trên những chiếc nắp này tương ứng với các hộp đựng.', '{"wordId":"correspond","ukIpa":"/ˌkɒrəˈspɒnd/","usIpa":"/ˌkɔːrəˈspɑːnd/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"To match something or have an equivalent role or position.","vi":"tương ứng; phù hợp"},{"pos":"v.","en":"To exchange letters or messages with someone.","vi":"thư tín; trao đổi thư từ"}],"examples":[{"en":"The colours on these lids correspond to the containers.","vi":"Màu sắc trên những chiếc nắp này tương ứng với các hộp đựng.","audioKind":"ex"},{"en":"University courses should correspond more closely to the skills that employers need in a changing economy.","vi":"Các khóa học đại học nên phù hợp chặt chẽ hơn với các kỹ năng mà nhà tuyển dụng cần trong một nền kinh tế đang thay đổi.","audioKind":"ex2"}],"collocations":[{"en":"correspond to","vi":"tương ứng với"},{"en":"correspond with someone","vi":"thư tín với ai đó"},{"en":"correspond closely","vi":"phù hợp chặt chẽ"}],"wordFamily":["correspondence (n.)","corresponding (adj.)","correspondingly (adv.)","correspondent (n.)"],"synonyms":["match"],"antonyms":[],"tipVi":"Tương ứng thường dùng correspond to; liên lạc với ai dùng with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_estimation', 'en-b2-37', 'estimation', '/ˌestəˈmeɪʃən/', 'B2', 'sự ước tính; sự đánh giá; cách nhìn nhận', 'n.', 'estimate (v.), estimate (n.), estimated (adj.)', 'Đồng nghĩa: assessment, approximation', '"estimation" thường chỉ quá trình ước tính; để chỉ con số ước tính cụ thể thường dùng "estimate".', 'By my estimation, we need three more chairs.', NULL, 'Theo tôi ước tính, chúng ta cần thêm ba chiếc ghế nữa.', '{"wordId":"estimation","ukIpa":"/ˌestɪˈmeɪʃən/","usIpa":"/ˌestəˈmeɪʃən/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"The process of judging an approximate amount, size, or value.","vi":"sự ước tính; sự đánh giá"},{"pos":"n.","en":"An opinion about someone''s character or something''s value.","vi":"sự đánh giá; cách nhìn nhận"}],"examples":[{"en":"By my estimation, we need three more chairs.","vi":"Theo tôi ước tính, chúng ta cần thêm ba chiếc ghế nữa.","audioKind":"ex"},{"en":"Accurate estimation of construction costs helps local authorities avoid wasting public funds on unfinished projects.","vi":"Việc ước tính chính xác chi phí xây dựng giúp chính quyền địa phương tránh lãng phí ngân sách công vào các dự án dở dang.","audioKind":"ex2"}],"collocations":[{"en":"cost estimation","vi":"ước tính chi phí"},{"en":"rough estimation","vi":"ước tính sơ bộ"},{"en":"in my estimation","vi":"theo đánh giá của tôi"}],"wordFamily":["estimate (v.)","estimate (n.)","estimated (adj.)"],"synonyms":["assessment","approximation"],"antonyms":[],"tipVi":"\"estimation\" thường chỉ quá trình ước tính; để chỉ con số ước tính cụ thể thường dùng \"estimate\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_insignificant', 'en-b2-37', 'insignificant', '/ˌɪnsɪɡˈnɪfɪkənt/', 'B2', 'không đáng kể; nhỏ nhặt', 'adj.', 'significant (adj.), insignificance (n.), insignificantly (adv.), significance (n.)', 'Đồng nghĩa: negligible, trivial, minor · Trái nghĩa: significant, important', 'Nhấn mạnh không quan trọng hoặc ảnh hưởng nhỏ, không đồng nghĩa với meaningless.', 'The scratch is insignificant compared with the broken window.', NULL, 'Vết trầy xước này chẳng đáng là bao so với chiếc cửa sổ bị vỡ.', '{"wordId":"insignificant","ukIpa":"/ˌɪnsɪɡˈnɪfɪkənt/","usIpa":"/ˌɪnsɪɡˈnɪfɪkənt/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Too small or unimportant to have much effect.","vi":"không đáng kể; nhỏ nhặt"}],"examples":[{"en":"The scratch is insignificant compared with the broken window.","vi":"Vết trầy xước này chẳng đáng là bao so với chiếc cửa sổ bị vỡ.","audioKind":"ex"},{"en":"Although individual savings may seem insignificant, widespread reductions in energy use can produce substantial environmental benefits.","vi":"Mặc dù việc tiết kiệm của cá nhân có vẻ không đáng kể, nhưng việc giảm thiểu tiêu thụ năng lượng trên diện rộng có thể mang lại lợi ích môi trường đáng kể.","audioKind":"ex2"}],"collocations":[{"en":"an insignificant amount","vi":"một lượng nhỏ không đáng kể"},{"en":"seem insignificant","vi":"có vẻ không đáng kể"},{"en":"statistically insignificant","vi":"không có ý nghĩa thống kê"}],"wordFamily":["significant (adj.)","insignificance (n.)","insignificantly (adv.)","significance (n.)"],"synonyms":["negligible","trivial","minor"],"antonyms":["significant","important"],"tipVi":"Nhấn mạnh không quan trọng hoặc ảnh hưởng nhỏ, không đồng nghĩa với meaningless.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_discourage', 'en-b2-37', 'discourage', '/dɪsˈkɜːrɪdʒ/', 'B2', 'can ngăn; làm nản lòng; làm mất tinh thần; làm nhụt chí', 'v.', 'discouragement (n.), discouraging (adj.), discouraged (adj.), encourage (v.)', 'Đồng nghĩa: deter, dissuade · Trái nghĩa: encourage', 'Dùng discourage sb from doing, không dùng from to do.', 'Heavy rain did not discourage us from walking outside.', NULL, 'Cơn mưa lớn không làm chúng tôi chùn bước khỏi việc đi dạo bên ngoài.', '{"wordId":"discourage","ukIpa":"/dɪsˈkʌrɪdʒ/","usIpa":"/dɪsˈkɜːrɪdʒ/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"Make someone less willing or likely to do something","vi":"can ngăn; làm nản lòng"},{"pos":"v.","en":"Make someone lose confidence or hope","vi":"làm mất tinh thần; làm nhụt chí"}],"examples":[{"en":"Heavy rain did not discourage us from walking outside.","vi":"Cơn mưa lớn không làm chúng tôi chùn bước khỏi việc đi dạo bên ngoài.","audioKind":"ex"},{"en":"Higher parking charges may discourage commuters from driving into city centres during peak hours.","vi":"Mức phí đỗ xe cao hơn có thể làm giảm ý định tự lái xe vào trung tâm thành phố của những người đi làm vào giờ cao điểm.","audioKind":"ex2"}],"collocations":[{"en":"discourage someone from doing something","vi":"ngăn cản ai làm việc gì"},{"en":"discourage car use","vi":"hạn chế việc sử dụng ô tô"},{"en":"feel discouraged","vi":"cảm thấy nản lòng"}],"wordFamily":["discouragement (n.)","discouraging (adj.)","discouraged (adj.)","encourage (v.)"],"synonyms":["deter","dissuade"],"antonyms":["encourage"],"tipVi":"Dùng discourage sb from doing, không dùng from to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_impulse', 'en-b2-37', 'impulse', '/ˈɪmpʌls/', 'B2', 'sự bốc đồng; sự thôi thúc nhất thời; xung điện; xung thần kinh; động lực; sự kích thích', 'n.', 'impulsive (adj.), impulsively (adv.), impulsiveness (n.)', 'Đồng nghĩa: urge', 'on impulse diễn tả sự bốc đồng nhất thời; theo sau impulse thường dùng dạng to do.', 'I bought this bright yellow umbrella on impulse.', NULL, 'Tôi đã mua chiếc ô màu vàng rực này trong một phút bốc đồng.', '{"wordId":"impulse","ukIpa":"/ˈɪmpʌls/","usIpa":"/ˈɪmpʌls/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"A sudden strong desire to act without thinking carefully.","vi":"sự bốc đồng; sự thôi thúc nhất thời"},{"pos":"n.","en":"A brief electrical signal travelling through a nerve or circuit.","vi":"xung điện; xung thần kinh"},{"pos":"n.","en":"Something that encourages an activity or development.","vi":"động lực; sự kích thích"}],"examples":[{"en":"I bought this bright yellow umbrella on impulse.","vi":"Tôi đã mua chiếc ô màu vàng rực này trong một phút bốc đồng.","audioKind":"ex"},{"en":"Online retailers often encourage consumers to act on impulse by presenting discounts as available for a limited time.","vi":"Các nhà bán lẻ trực tuyến thường khuyến khích người tiêu dùng mua hàng theo sự bốc đồng bằng cách đưa ra các chương trình giảm giá trong thời gian có hạn.","audioKind":"ex2"}],"collocations":[{"en":"on impulse","vi":"trong lúc bốc đồng"},{"en":"resist the impulse to","vi":"kìm nén sự thôi thúc làm gì"},{"en":"nerve impulses","vi":"xung thần kinh"},{"en":"impulse buying","vi":"mua hàng bốc đồng"}],"wordFamily":["impulsive (adj.)","impulsively (adv.)","impulsiveness (n.)"],"synonyms":["urge"],"antonyms":[],"tipVi":"on impulse diễn tả sự bốc đồng nhất thời; theo sau impulse thường dùng dạng to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ultimate', 'en-b2-37', 'ultimate', '/ˈʌltɪmət/', 'B2', 'mục tiêu cuối cùng, kết quả quan trọng nhất; tuyệt vời nhất, tối thượng, cực đỉnh', 'adj.', 'ultimately (adv.)', 'Đồng nghĩa: final', 'ultimate thường nhấn mạnh mục tiêu sau cùng hoặc mức độ tối thượng, không mang nghĩa là lần gần đây nhất.', 'Our ultimate goal is to buy a small house.', NULL, 'Mục tiêu cuối cùng của chúng tôi là mua một ngôi nhà nhỏ.', '{"wordId":"ultimate","ukIpa":"/ˈʌltɪmət/","usIpa":"/ˈʌltɪmət/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Being the final or most important aim or result.","vi":"mục tiêu cuối cùng, kết quả quan trọng nhất"},{"pos":"adj.","en":"The best or most extreme example of something.","vi":"tuyệt vời nhất, tối thượng, cực đỉnh"}],"examples":[{"en":"Our ultimate goal is to buy a small house.","vi":"Mục tiêu cuối cùng của chúng tôi là mua một ngôi nhà nhỏ.","audioKind":"ex"},{"en":"The ultimate aim of public transport investment should be to provide affordable and reliable travel for everyone.","vi":"Mục tiêu tối thượng của việc đầu tư vào giao thông công cộng phải là cung cấp dịch vụ đi lại giá cả phải chăng và đáng tin cậy cho tất cả mọi người.","audioKind":"ex2"}],"collocations":[{"en":"ultimate goal","vi":"mục tiêu cuối cùng"},{"en":"ultimate responsibility","vi":"trách nhiệm cao nhất"},{"en":"the ultimate in comfort","vi":"sự thoải mái tuyệt đối"}],"wordFamily":["ultimately (adv.)"],"synonyms":["final"],"antonyms":[],"tipVi":"ultimate thường nhấn mạnh mục tiêu sau cùng hoặc mức độ tối thượng, không mang nghĩa là lần gần đây nhất.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rash', 'en-b2-37', 'rash', '/ræʃ/', 'B2', 'vội vàng; hấp tấp; liều lĩnh; phát ban', 'adj.', 'rashly (adv.), rashness (n.)', 'Đồng nghĩa: reckless, hasty · Trái nghĩa: cautious, considered', 'Dùng làm tính từ để chỉ sự liều lĩnh; dùng làm danh từ để chỉ bệnh phát ban, thường đi với a rash.', 'It was rash to leave without checking the weather.', NULL, 'Thật là hấp tấp khi rời đi mà không kiểm tra thời tiết trước.', '{"wordId":"rash","ukIpa":"/ræʃ/","usIpa":"/ræʃ/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Done without enough thought about possible risks or consequences.","vi":"vội vàng; hấp tấp; liều lĩnh"},{"pos":"n.","en":"An area of irritated skin covered with spots.","vi":"phát ban"}],"examples":[{"en":"It was rash to leave without checking the weather.","vi":"Thật là hấp tấp khi rời đi mà không kiểm tra thời tiết trước.","audioKind":"ex"},{"en":"Rash decisions about urban development can leave communities with inadequate transport and limited access to green spaces.","vi":"Những quyết định vội vàng về phát triển đô thị có thể khiến cộng đồng thiếu thốn giao thông và hạn chế không gian xanh.","audioKind":"ex2"}],"collocations":[{"en":"a rash decision","vi":"một quyết định hấp tấp"},{"en":"a rash promise","vi":"một lời hứa vội vàng"},{"en":"develop a rash","vi":"bị phát ban"},{"en":"a skin rash","vi":"chứng phát ban da"}],"wordFamily":["rashly (adv.)","rashness (n.)"],"synonyms":["reckless","hasty"],"antonyms":["cautious","considered"],"tipVi":"Dùng làm tính từ để chỉ sự liều lĩnh; dùng làm danh từ để chỉ bệnh phát ban, thường đi với a rash.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_long-term', 'en-b2-37', 'long-term', '/ˌlɔːŋ ˈtɝːm/', 'B2', 'dài hạn; lâu dài', 'adj.', NULL, 'Trái nghĩa: short-term', 'Khi làm định ngữ thường có dấu gạch nối; trong cụm in the long term thì không thêm.', 'We need a long-term plan for our garden.', NULL, 'Chúng ta cần một kế hoạch dài hạn cho khu vườn của mình.', '{"wordId":"long-term","ukIpa":"/ˌlɒŋ ˈtɜːm/","usIpa":"/ˌlɔːŋ ˈtɝːm/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"continuing or having effects over a long period","vi":"dài hạn; lâu dài"}],"examples":[{"en":"We need a long-term plan for our garden.","vi":"Chúng ta cần một kế hoạch dài hạn cho khu vườn của mình.","audioKind":"ex"},{"en":"Investment in public transport can bring long-term benefits to both local economies and the environment.","vi":"Đầu tư vào giao thông công cộng có thể mang lại lợi ích lâu dài cho cả nền kinh tế địa phương lẫn môi trường.","audioKind":"ex2"}],"collocations":[{"en":"long-term goal","vi":"mục tiêu dài hạn"},{"en":"long-term impact","vi":"tác động lâu dài"},{"en":"long-term investment","vi":"đầu tư dài hạn"}],"wordFamily":[],"synonyms":[],"antonyms":["short-term"],"tipVi":"Khi làm định ngữ thường có dấu gạch nối; trong cụm in the long term thì không thêm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_comparatively', 'en-b2-37', 'comparatively', '/kəmˈpærətɪvli/', 'B2', 'tương đối; so sánh ra', 'adv.', 'compare (v.), comparison (n.), comparative (adj.), comparable (adj.)', 'Đồng nghĩa: relatively', 'Thường bổ nghĩa cho tính từ ở dạng nguyên cấp, chẳng hạn như comparatively cheap.', 'This cafe is comparatively quiet after the lunch rush.', NULL, 'Quán cà phê này tương đối yên tĩnh sau giờ cao điểm ăn trưa.', '{"wordId":"comparatively","ukIpa":"/kəmˈpærətɪvli/","usIpa":"/kəmˈpærətɪvli/","cefr":"B2","topic":"thinking","senses":[{"pos":"adv.","en":"To a particular degree when compared with something else.","vi":"tương đối; so sánh ra"}],"examples":[{"en":"This cafe is comparatively quiet after the lunch rush.","vi":"Quán cà phê này tương đối yên tĩnh sau giờ cao điểm ăn trưa.","audioKind":"ex"},{"en":"Cycling remains a comparatively inexpensive form of transport, especially in cities with safe and extensive cycle networks.","vi":"Đi xe đạp vẫn là một hình thức giao thông có chi phí tương đối rẻ, đặc biệt là ở các thành phố có hệ thống đường dành cho xe đạp an toàn và rộng khắp.","audioKind":"ex2"}],"collocations":[{"en":"comparatively low","vi":"tương đối thấp"},{"en":"comparatively inexpensive","vi":"tương đối rẻ"},{"en":"comparatively little","vi":"tương đối ít"}],"wordFamily":["compare (v.)","comparison (n.)","comparative (adj.)","comparable (adj.)"],"synonyms":["relatively"],"antonyms":[],"tipVi":"Thường bổ nghĩa cho tính từ ở dạng nguyên cấp, chẳng hạn như comparatively cheap.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_factor', 'en-b2-37', 'factor', '/ˈfæktər/', 'B2', 'yếu tố; nhân tố ảnh hưởng; tính đến; cân nhắc khi đưa ra quyết định', 'n.', NULL, NULL, 'Động từ thường dùng factor in, biểu thị việc đưa một yếu tố nào đó vào cân nhắc.', 'Price was the main factor when we chose our sofa.', NULL, 'Giá cả là yếu tố chính khi chúng tôi chọn mua ghế sofa.', '{"wordId":"factor","ukIpa":"/ˈfæktə/","usIpa":"/ˈfæktər/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"something that influences a result or situation","vi":"yếu tố; nhân tố ảnh hưởng"},{"pos":"v.","en":"to include something when calculating or making a decision","vi":"tính đến; cân nhắc khi đưa ra quyết định"}],"examples":[{"en":"Price was the main factor when we chose our sofa.","vi":"Giá cả là yếu tố chính khi chúng tôi chọn mua ghế sofa.","audioKind":"ex"},{"en":"Access to reliable public transport is a key factor in reducing dependence on private cars.","vi":"Khả năng tiếp cận giao thông công cộng đáng tin cậy là nhân tố then chốt trong việc giảm sự phụ thuộc vào xe hơi cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"key factor","vi":"yếu tố then chốt"},{"en":"contributing factor","vi":"yếu tố góp phần"},{"en":"risk factor","vi":"yếu tố rủi ro"},{"en":"factor in the cost","vi":"tính đến chi phí"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Động từ thường dùng factor in, biểu thị việc đưa một yếu tố nào đó vào cân nhắc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_expectation', 'en-b2-37', 'expectation', '/ˌekspekˈteɪʃn/', 'B2', 'sự kỳ vọng; niềm tin rằng điều gì đó sẽ xảy ra; tiêu chuẩn thành công hoặc hành vi mà ai đó mong đợi', 'n.', 'expect (v.), expected (adj.), unexpected (adj.)', 'Đồng nghĩa: anticipation', 'Khi biểu thị sự kỳ vọng về biểu hiện hoặc thành tích, người ta thường dùng dạng số nhiều expectations.', 'We packed warm coats in expectation of cold weather.', NULL, 'Chúng tôi đã chuẩn bị áo khoác ấm vì dự đoán thời tiết sẽ lạnh.', '{"wordId":"expectation","ukIpa":"/ˌekspekˈteɪʃn/","usIpa":"/ˌekspekˈteɪʃn/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"A belief that something will happen.","vi":"sự kỳ vọng; niềm tin rằng điều gì đó sẽ xảy ra"},{"pos":"n.","en":"A standard of success or behaviour someone hopes for.","vi":"tiêu chuẩn thành công hoặc hành vi mà ai đó mong đợi"}],"examples":[{"en":"We packed warm coats in expectation of cold weather.","vi":"Chúng tôi đã chuẩn bị áo khoác ấm vì dự đoán thời tiết sẽ lạnh.","audioKind":"ex"},{"en":"High parental expectations can motivate students, but excessive pressure may negatively affect their mental health.","vi":"Sự kỳ vọng cao từ phía phụ huynh có thể khích lệ học sinh, nhưng áp lực quá mức có thể tác động tiêu cực đến sức khỏe tinh thần của các em.","audioKind":"ex2"}],"collocations":[{"en":"in expectation of","vi":"với mong đợi rằng; chuẩn bị cho việc"},{"en":"meet expectations","vi":"đáp ứng kỳ vọng"},{"en":"exceed expectations","vi":"vượt quá mong đợi"},{"en":"high expectations","vi":"kỳ vọng cao"}],"wordFamily":["expect (v.)","expected (adj.)","unexpected (adj.)"],"synonyms":["anticipation"],"antonyms":[],"tipVi":"Khi biểu thị sự kỳ vọng về biểu hiện hoặc thành tích, người ta thường dùng dạng số nhiều expectations.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ridiculous', 'en-b2-37', 'ridiculous', '/rɪˈdɪkjələs/', 'B2', 'lố bịch; ngớ ngẩn; nực cười; vô lý', 'adj.', 'ridiculously (adv.), ridiculousness (n.), ridicule (v.)', 'Đồng nghĩa: absurd, ludicrous, preposterous · Trái nghĩa: reasonable, sensible', 'Từ này có sắc thái mạnh, nhấn mạnh tính phi lý, không hợp logic chứ không chỉ đơn thuần là buồn cười.', 'This tiny sandwich costs a ridiculous amount of money.', NULL, 'Chiếc bánh mì kẹp nhỏ xíu này có mức giá đắt đến mức vô lý.', '{"wordId":"ridiculous","ukIpa":"/rɪˈdɪkjələs/","usIpa":"/rɪˈdɪkjələs/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Extremely silly or unreasonable and deserving to be laughed at.","vi":"lố bịch; ngớ ngẩn; nực cười; vô lý"}],"examples":[{"en":"This tiny sandwich costs a ridiculous amount of money.","vi":"Chiếc bánh mì kẹp nhỏ xíu này có mức giá đắt đến mức vô lý.","audioKind":"ex"},{"en":"It is ridiculous to expect public transport use to increase without improving the reliability of existing services.","vi":"Thật là ngớ ngẩn khi mong đợi tỷ lệ sử dụng giao thông công cộng tăng lên mà không cải thiện độ tin cậy của các dịch vụ hiện có.","audioKind":"ex2"}],"collocations":[{"en":"a ridiculous idea","vi":"một ý tưởng ngớ ngẩn"},{"en":"look ridiculous","vi":"trông nực cười"},{"en":"absolutely ridiculous","vi":"hết sức vô lý"}],"wordFamily":["ridiculously (adv.)","ridiculousness (n.)","ridicule (v.)"],"synonyms":["absurd","ludicrous","preposterous"],"antonyms":["reasonable","sensible"],"tipVi":"Từ này có sắc thái mạnh, nhấn mạnh tính phi lý, không hợp logic chứ không chỉ đơn thuần là buồn cười.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tactic', 'en-b2-37', 'tactic', '/ˈtæktɪk/', 'B2', 'chiến thuật; thủ thuật; mưu lược (một hành động cụ thể nhằm đạt được mục tiêu)', 'n.', 'tactical (adj.), tactically (adv.), tactician (n.)', 'Đồng nghĩa: method, ploy', '"strategy" chỉ chiến lược tổng thể, trong khi "tactic" chỉ thủ thuật hoặc phương pháp cụ thể.', 'Her tactic was to practise before everyone else arrived.', NULL, 'Chiến thuật của cô ấy là tập luyện trước khi tất cả mọi người đến.', '{"wordId":"tactic","ukIpa":"/ˈtæktɪk/","usIpa":"/ˈtæktɪk/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"A particular action used to achieve a goal.","vi":"chiến thuật; thủ thuật; mưu lược (một hành động cụ thể nhằm đạt được mục tiêu)"}],"examples":[{"en":"Her tactic was to practise before everyone else arrived.","vi":"Chiến thuật của cô ấy là tập luyện trước khi tất cả mọi người đến.","audioKind":"ex"},{"en":"Offering cheaper public transport is one tactic cities can use to discourage unnecessary car journeys.","vi":"Cung cấp phương tiện giao thông công cộng rẻ hơn là một chiến thuật mà các thành phố có thể áp dụng để hạn chế việc lái xe không cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"effective tactic","vi":"chiến thuật hiệu quả"},{"en":"marketing tactic","vi":"thủ thuật tiếp thị"},{"en":"change tactics","vi":"thay đổi chiến thuật"}],"wordFamily":["tactical (adj.)","tactically (adv.)","tactician (n.)"],"synonyms":["method","ploy"],"antonyms":[],"tipVi":"\"strategy\" chỉ chiến lược tổng thể, trong khi \"tactic\" chỉ thủ thuật hoặc phương pháp cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nevertheless', 'en-b2-37', 'nevertheless', '/ˌnevɚðəˈles/', 'B2', 'tuy nhiên; dù vậy; mặc dù thế (bất chấp điều vừa mới được đề cập)', 'adv.', NULL, 'Đồng nghĩa: nonetheless, however', 'Đây là trạng từ, không phải liên tư; khi nối hai mệnh đề độc lập, có thể dùng dấu chấm phẩy trước nó.', 'The climb was tiring; nevertheless, we enjoyed the view.', NULL, 'Chuyến leo núi rất mệt nhọc; thế nhưng, chúng tôi vẫn tận hưởng được khung cảnh.', '{"wordId":"nevertheless","ukIpa":"/ˌnevəðəˈles/","usIpa":"/ˌnevɚðəˈles/","cefr":"B2","topic":"thinking","senses":[{"pos":"adv.","en":"Despite what has just been mentioned.","vi":"tuy nhiên; dù vậy; mặc dù thế (bất chấp điều vừa mới được đề cập)"}],"examples":[{"en":"The climb was tiring; nevertheless, we enjoyed the view.","vi":"Chuyến leo núi rất mệt nhọc; thế nhưng, chúng tôi vẫn tận hưởng được khung cảnh.","audioKind":"ex"},{"en":"Public transport improvements require considerable investment; nevertheless, they can reduce congestion and improve urban air quality.","vi":"Việc cải thiện giao thông công cộng đòi hỏi khoản đầu tư đáng kể; tuy nhiên, những cải thiện đó có thể làm giảm ùn tắc và nâng cao chất lượng không khí đô thị.","audioKind":"ex2"}],"collocations":[{"en":"but nevertheless","vi":"nhưng dù vậy"},{"en":"nevertheless remain","vi":"tuy nhiên vẫn duy trì"}],"wordFamily":[],"synonyms":["nonetheless","however"],"antonyms":[],"tipVi":"Đây là trạng từ, không phải liên tư; khi nối hai mệnh đề độc lập, có thể dùng dấu chấm phẩy trước nó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_alternative', 'en-b2-37', 'alternative', '/ɔːlˈtɝːnətɪv/', 'B2', 'sự lựa chọn thay thế; phương án thay thế; có thể thay thế; phương án khác; phi truyền thống; khác thường', 'n.', 'alternatively (adv.)', 'Đồng nghĩa: option, substitute', 'Thay thế cái gì dùng alternative to, không giới hạn trong việc lựa chọn giữa hai thứ.', 'Cycling is a cheaper alternative to taking the bus.', NULL, 'Đi xe đạp là một lựa chọn thay thế rẻ hơn so với việc đi xe buýt.', '{"wordId":"alternative","ukIpa":"/ɔːlˈtɜːnətɪv/","usIpa":"/ɔːlˈtɝːnətɪv/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"something you can choose instead of something else","vi":"sự lựa chọn thay thế; phương án thay thế"},{"pos":"adj.","en":"available to use or choose instead of something else","vi":"có thể thay thế; phương án khác"},{"pos":"adj.","en":"different from what is usual or widely accepted","vi":"phi truyền thống; khác thường"}],"examples":[{"en":"Cycling is a cheaper alternative to taking the bus.","vi":"Đi xe đạp là một lựa chọn thay thế rẻ hơn so với việc đi xe buýt.","audioKind":"ex"},{"en":"Governments should invest in alternative energy sources to reduce dependence on fossil fuels and improve energy security.","vi":"Chính phủ nên đầu tư vào các nguồn năng lượng thay thế để giảm sự phụ thuộc vào nhiên liệu hóa thạch và nâng cao an ninh năng lượng.","audioKind":"ex2"}],"collocations":[{"en":"an alternative to","vi":"phương án thay thế cho"},{"en":"alternative energy","vi":"năng lượng thay thế"},{"en":"a viable alternative","vi":"một giải pháp thay thế khả thi"},{"en":"have no alternative","vi":"không còn sự lựa chọn nào khác"}],"wordFamily":["alternatively (adv.)"],"synonyms":["option","substitute"],"antonyms":[],"tipVi":"Thay thế cái gì dùng alternative to, không giới hạn trong việc lựa chọn giữa hai thứ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fundamental', 'en-b2-37', 'fundamental', '/ˌfʌndəˈmentəl/', 'B2', 'cơ bản; nền tảng; cốt lõi; nguyên lý cơ bản; kiến thức nền tảng', 'adj.', 'fundamentally (adv.)', 'Đồng nghĩa: basic, essential · Trái nghĩa: secondary, inessential', 'Danh từ thường dùng ở dạng số nhiều fundamentals, diễn tả các nguyên lý cơ bản.', 'Trust is fundamental to a happy life together.', NULL, 'Sự tin tưởng là nền tảng cốt lõi cho một cuộc sống hạnh phúc viên mãn bên nhau.', '{"wordId":"fundamental","ukIpa":"/ˌfʌndəˈmentəl/","usIpa":"/ˌfʌndəˈmentəl/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Forming the essential basis of something.","vi":"cơ bản; nền tảng; cốt lõi"},{"pos":"n.","en":"A basic principle or skill, usually considered with others.","vi":"nguyên lý cơ bản; kiến thức nền tảng"}],"examples":[{"en":"Trust is fundamental to a happy life together.","vi":"Sự tin tưởng là nền tảng cốt lõi cho một cuộc sống hạnh phúc viên mãn bên nhau.","audioKind":"ex"},{"en":"Access to clean drinking water is a fundamental requirement for improving public health in disadvantaged communities.","vi":"Khả năng tiếp cận nước uống sạch là điều kiện tiên quyết cơ bản nhằm nâng cao sức khỏe cộng đồng tại các cộng đồng còn nhiều thiệt thòi.","audioKind":"ex2"}],"collocations":[{"en":"fundamental to","vi":"tối quan trọng đối với"},{"en":"a fundamental principle","vi":"nguyên tắc cơ bản"},{"en":"fundamental change","vi":"sự thay đổi mang tính cốt lõi"},{"en":"the fundamentals of","vi":"những kiến thức nền tảng của"}],"wordFamily":["fundamentally (adv.)"],"synonyms":["basic","essential"],"antonyms":["secondary","inessential"],"tipVi":"Danh từ thường dùng ở dạng số nhiều fundamentals, diễn tả các nguyên lý cơ bản.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_eliminate', 'en-b2-37', 'eliminate', '/ɪˈlɪmɪneɪt/', 'B2', 'loại bỏ; xóa bỏ hoàn toàn; loại trực tiếp; loại khỏi cuộc thi', 'v.', 'elimination (n.)', 'Đồng nghĩa: remove, eradicate, exclude', 'Mang tính triệt để hơn reduce, nhấn mạnh việc loại bỏ hoặc loại trừ hoàn toàn.', 'This water filter eliminates unpleasant smells from tap water.', NULL, 'Máy lọc nước này loại bỏ mùi khó chịu khỏi nước máy.', '{"wordId":"eliminate","ukIpa":"/ɪˈlɪmɪneɪt/","usIpa":"/ɪˈlɪmɪneɪt/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"To remove or get rid of something completely.","vi":"loại bỏ; xóa bỏ hoàn toàn"},{"pos":"v.","en":"To defeat someone so they cannot continue in a competition.","vi":"loại trực tiếp; loại khỏi cuộc thi"}],"examples":[{"en":"This water filter eliminates unpleasant smells from tap water.","vi":"Máy lọc nước này loại bỏ mùi khó chịu khỏi nước máy.","audioKind":"ex"},{"en":"Improved public transport could eliminate the need for many urban residents to own a private car.","vi":"Hệ thống giao thông công cộng được cải thiện có thể loại bỏ nhu cầu sở hữu xe ô tô riêng của nhiều cư dân thành thị.","audioKind":"ex2"}],"collocations":[{"en":"eliminate the need for","vi":"loại bỏ nhu cầu về"},{"en":"eliminate errors","vi":"loại bỏ lỗi sai"},{"en":"eliminate a possibility","vi":"loại bỏ một khả năng"},{"en":"be eliminated from a competition","vi":"bị loại khỏi một cuộc thi"}],"wordFamily":["elimination (n.)"],"synonyms":["remove","eradicate","exclude"],"antonyms":[],"tipVi":"Mang tính triệt để hơn reduce, nhấn mạnh việc loại bỏ hoặc loại trừ hoàn toàn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 28, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_37_1', 'en-b2-37', 'Cách dùng “ultimately” (adv.) — cuối cùng; sau một chuỗi sự kiện', 'ultimately depend on  ·  ultimately lead to  ·  ultimately responsible', 'Nhấn mạnh kết quả cuối cùng hoặc yếu tố cốt lõi, không dùng cho mục cuối cùng trong một danh sách liệt kê.', 'Họ từ (Word Family): ultimate (adj.) | Đồng nghĩa: eventually, in the end', '[{"hanzi":"We explored several flats but ultimately chose this small house.","pinyin":"","meaning":"Chúng tôi đã xem qua vài căn hộ nhưng cuối cùng vẫn chọn ngôi nhà nhỏ này."},{"hanzi":"Although technology can support classroom learning, educational success ultimately depends on effective teaching and student engagement.","pinyin":"","meaning":"Mặc dù công nghệ có thể hỗ trợ việc học trên lớp, nhưng thành công trong giáo dục suy cho cùng vẫn phụ thuộc vào phương pháp giảng dạy hiệu quả và sự tham gia của học sinh."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_37_2', 'en-b2-37', 'Cách dùng “significant” (adj.) — đáng kể; quan trọng; lớn', 'a significant increase  ·  a significant impact  ·  statistically significant', 'Trong thống kê, significant chỉ đạt mức ý nghĩa thống kê, không đồng nghĩa với việc tác động thực tế lớn.', 'Họ từ (Word Family): significance (n.), significantly (adv.), insignificant (adj.) | Đồng nghĩa: important, notable · Trái nghĩa: insignificant, negligible', '[{"hanzi":"Moving closer to work made a significant difference to me.","pinyin":"","meaning":"Việc chuyển đến gần chỗ làm hơn đã tạo ra một sự thay đổi đáng kể đối với tôi."},{"hanzi":"Access to reliable internet services has a significant impact on educational opportunities in remote communities.","pinyin":"","meaning":"Khả năng tiếp cận các dịch vụ Internet đáng tin cậy có tác động quan trọng đến các cơ hội giáo dục ở các cộng đồng vùng sâu vùng xa."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_37_3', 'en-b2-37', 'Cách dùng “ultimate” (adj.) — mục tiêu cuối cùng, kết quả quan trọng nhất', 'ultimate goal  ·  ultimate responsibility  ·  the ultimate in comfort', 'ultimate thường nhấn mạnh mục tiêu sau cùng hoặc mức độ tối thượng, không mang nghĩa là lần gần đây nhất.', 'Họ từ (Word Family): ultimately (adv.) | Đồng nghĩa: final', '[{"hanzi":"Our ultimate goal is to buy a small house.","pinyin":"","meaning":"Mục tiêu cuối cùng của chúng tôi là mua một ngôi nhà nhỏ."},{"hanzi":"The ultimate aim of public transport investment should be to provide affordable and reliable travel for everyone.","pinyin":"","meaning":"Mục tiêu tối thượng của việc đầu tư vào giao thông công cộng phải là cung cấp dịch vụ đi lại giá cả phải chăng và đáng tin cậy cho tất cả mọi người."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_37_4', 'en-b2-37', 'Cách dùng “expectation” (n.) — sự kỳ vọng; niềm tin rằng điều gì đó sẽ xảy ra', 'in expectation of  ·  meet expectations  ·  exceed expectations', 'Khi biểu thị sự kỳ vọng về biểu hiện hoặc thành tích, người ta thường dùng dạng số nhiều expectations.', 'Họ từ (Word Family): expect (v.), expected (adj.), unexpected (adj.) | Đồng nghĩa: anticipation', '[{"hanzi":"We packed warm coats in expectation of cold weather.","pinyin":"","meaning":"Chúng tôi đã chuẩn bị áo khoác ấm vì dự đoán thời tiết sẽ lạnh."},{"hanzi":"High parental expectations can motivate students, but excessive pressure may negatively affect their mental health.","pinyin":"","meaning":"Sự kỳ vọng cao từ phía phụ huynh có thể khích lệ học sinh, nhưng áp lực quá mức có thể tác động tiêu cực đến sức khỏe tinh thần của các em."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_37_1', 'en-b2-37', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_37_1_1', 'ten_b2_37_1', 'foresee', 'We didn''t foresee such a long queue outside.', 'We didn''t foresee such a long queue outside.', '/fɔːrˈsiː/', 'Chúng tôi đã không lường trước được hàng người chờ dài như vậy ở bên ngoài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_37_1_2', 'ten_b2_37_1', 'analyze', 'We analyzed our spending before planning the next holiday.', 'We analyzed our spending before planning the next holiday.', '/ˈænəlaɪz/', 'Chúng tôi đã phân tích các khoản chi tiêu của mình trước khi lên kế hoạch cho chuyến nghỉ dưỡng tiếp theo.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_37_1_3', 'ten_b2_37_1', 'significant', 'Moving closer to work made a significant difference to me.', 'Moving closer to work made a significant difference to me.', '/sɪɡˈnɪfɪkənt/', 'Việc chuyển đến gần chỗ làm hơn đã tạo ra một sự thay đổi đáng kể đối với tôi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_37_1_4', 'ten_b2_37_1', 'overall', 'The overall cost includes breakfast and a train ticket.', 'The overall cost includes breakfast and a train ticket.', '/ˌoʊvərˈɔːl/', 'Tổng chi phí đã bao gồm bữa sáng và một vé tàu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_37_1_5', 'ten_b2_37_1', 'undoubtedly', 'This is undoubtedly the warmest coat I have ever owned.', 'This is undoubtedly the warmest coat I have ever owned.', '/ʌnˈdaʊtɪdli/', 'Đây chắc chắn là chiếc áo khoác ấm nhất mà tôi từng có.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_37_1_6', 'ten_b2_37_1', 'specific', 'Is there a specific colour you would prefer?', 'Is there a specific colour you would prefer?', '/spəˈsɪfɪk/', 'Bạn có thích một màu cụ thể nào không?', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_37_1_7', 'ten_b2_37_1', 'assume', 'Don''t assume the shop is open on Sundays.', 'Don''t assume the shop is open on Sundays.', '/əˈsuːm/', 'Đừng vội cho rằng cửa hàng mở cửa vào Chủ nhật.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_37_1_8', 'ten_b2_37_1', 'concentration', 'The constant noise outside made concentration difficult for me.', 'The constant noise outside made concentration difficult for me.', '/ˌkɑːnsənˈtreɪʃən/', 'Tiếng ồn liên tục bên ngoài khiến tôi khó tập trung.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_37_1_1', 'en-b2-37', 'ten_b2_37_1', 'listening', 'listening', 'We didn''t foresee such a long queue outside.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã không lường trước được hàng người chờ dài như vậy ở bên ngoài.","Đi xe đạp là một lựa chọn thay thế rẻ hơn so với việc đi xe buýt.","Chiếc bánh mì kẹp nhỏ xíu này có mức giá đắt đến mức vô lý.","Việc chuyển đến gần chỗ làm hơn đã tạo ra một sự thay đổi đáng kể đối với tôi."]'::jsonb, 0, 'We didn''t foresee such a long queue outside. → Chúng tôi đã không lường trước được hàng người chờ dài như vậy ở bên ngoài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_37_1_2', 'en-b2-37', 'ten_b2_37_1', 'listening', 'listening', 'We analyzed our spending before planning the next holiday.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Mục tiêu cuối cùng của chúng tôi là mua một ngôi nhà nhỏ.","Chúng tôi đã phân tích các khoản chi tiêu của mình trước khi lên kế hoạch cho chuyến nghỉ dưỡng tiếp theo.","Theo tôi ước tính, chúng ta cần thêm ba chiếc ghế nữa.","Vết trầy xước này chẳng đáng là bao so với chiếc cửa sổ bị vỡ."]'::jsonb, 1, 'We analyzed our spending before planning the next holiday. → Chúng tôi đã phân tích các khoản chi tiêu của mình trước khi lên kế hoạch cho chuyến nghỉ dưỡng tiếp theo.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_37_1_3', 'en-b2-37', 'ten_b2_37_1', 'listening', 'listening', 'Moving closer to work made a significant difference to me.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tổng chi phí đã bao gồm bữa sáng và một vé tàu.","Việc chuyển đến gần chỗ làm hơn đã tạo ra một sự thay đổi đáng kể đối với tôi.","Trái với dự báo thời tiết, ánh nắng đã tràn ngập khu vườn của chúng tôi.","Tôi đã mua chiếc ô màu vàng rực này trong một phút bốc đồng."]'::jsonb, 1, 'Moving closer to work made a significant difference to me. → Việc chuyển đến gần chỗ làm hơn đã tạo ra một sự thay đổi đáng kể đối với tôi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_37_2', 'en-b2-37', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_37_2_1', 'ten_b2_37_2', 'foresee', 'Urban planners must foresee future transport needs before approving major housing developments on the city''s outskirts.', 'Urban planners must foresee future transport needs before approving major housing developments on the city''s outskirts.', '/fɔːrˈsiː/', 'Các nhà quy hoạch đô thị phải dự đoán nhu cầu giao thông trong tương lai trước khi phê duyệt các dự án phát triển nhà ở quy mô lớn ở vùng ngoại ô thành phố.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_37_2_2', 'ten_b2_37_2', 'analyze', 'Researchers analyze traffic patterns to identify areas where improved public transport could reduce congestion.', 'Researchers analyze traffic patterns to identify areas where improved public transport could reduce congestion.', '/ˈænəlaɪz/', 'Các nhà nghiên cứu phân tích các mẫu hình giao thông để xác định những khu vực mà việc cải thiện giao thông công cộng có thể làm giảm tình trạng tắc nghẽn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_37_2_3', 'ten_b2_37_2', 'significant', 'Access to reliable internet services has a significant impact on educational opportunities in remote communities.', 'Access to reliable internet services has a significant impact on educational opportunities in remote communities.', '/sɪɡˈnɪfɪkənt/', 'Khả năng tiếp cận các dịch vụ Internet đáng tin cậy có tác động quan trọng đến các cơ hội giáo dục ở các cộng đồng vùng sâu vùng xa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_37_2_4', 'ten_b2_37_2', 'overall', 'Overall, investment in public transport can reduce urban congestion while improving access to employment opportunities.', 'Overall, investment in public transport can reduce urban congestion while improving access to employment opportunities.', '/ˌoʊvərˈɔːl/', 'Nhìn chung, việc đầu tư vào giao thông công cộng có thể làm giảm tình trạng tắc nghẽn đô thị đồng thời cải thiện khả năng tiếp cận các cơ hội việc làm.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_37_2_5', 'ten_b2_37_2', 'undoubtedly', 'Access to clean drinking water undoubtedly improves public health, particularly in communities with limited medical services.', 'Access to clean drinking water undoubtedly improves public health, particularly in communities with limited medical services.', '/ʌnˈdaʊtɪdli/', 'Việc tiếp cận nguồn nước uống sạch chắc chắn sẽ cải thiện sức khỏe cộng đồng, đặc biệt là ở những cộng đồng có dịch vụ y tế hạn chế.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_37_2_6', 'ten_b2_37_2', 'specific', 'Governments should set specific targets for reducing air pollution so that progress can be measured accurately.', 'Governments should set specific targets for reducing air pollution so that progress can be measured accurately.', '/spəˈsɪfɪk/', 'Chính phủ nên đặt ra các mục tiêu cụ thể để giảm thiểu ô nhiễm không khí nhằm đo lường tiến độ một cách chính xác.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_37_2_1', 'en-b2-37', 'ten_b2_37_2', 'listening', 'listening', 'Urban planners must foresee future transport needs before approving major housing developments on the city''s outskirts.', NULL, 'Trong câu vừa nghe, từ “foresee” mang nghĩa nào sau đây?', '["hành vi tự sát; sự tự tử","chứng trầm cảm; sự trầm uất","trung thực; thành thật; đúng sự thật","dự đoán; thấy trước"]'::jsonb, 3, '“foresee” (/fɔːrˈsiː/): dự đoán; thấy trước. Câu đầy đủ: Urban planners must foresee future transport needs before approving major housing developments on the city''s outskirts.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_37_2_2', 'en-b2-37', 'ten_b2_37_2', 'listening', 'listening', 'Researchers analyze traffic patterns to identify areas where improved public transport could reduce congestion.', NULL, 'Trong câu vừa nghe, từ “analyze” mang nghĩa nào sau đây?', '["kinh độ","có thể tái tạo (năng lượng, tài nguyên)","phân tích","nhôm"]'::jsonb, 2, '“analyze” (/ˈænəlaɪz/): phân tích. Câu đầy đủ: Researchers analyze traffic patterns to identify areas where improved public transport could reduce congestion.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
