INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_37_2', 'en-b2-37', NULL, 'comprehensive_test', 'listening', 'We analyzed our spending before planning the next holiday.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cơn mưa lớn không làm chúng tôi chùn bước khỏi việc đi dạo bên ngoài.","Chúng tôi đã phân tích các khoản chi tiêu của mình trước khi lên kế hoạch cho chuyến nghỉ dưỡng tiếp theo.","Màu sắc trên những chiếc nắp này tương ứng với các hộp đựng.","Chúng tôi đã không lường trước được hàng người chờ dài như vậy ở bên ngoài."]'::jsonb, 1, 'We analyzed our spending before planning the next holiday. → Chúng tôi đã phân tích các khoản chi tiêu của mình trước khi lên kế hoạch cho chuyến nghỉ dưỡng tiếp theo.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_37_3', 'en-b2-37', NULL, 'comprehensive_test', 'listening', 'significant', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đáng kể; quan trọng; lớn","thận","nghiêm trọng; dữ dội; tàn khốc","chăm chú; chăm chỉ; lắng nghe chăm chú"]'::jsonb, 0, 'significant (/sɪɡˈnɪfɪkənt/) → đáng kể; quan trọng; lớn; mang ý nghĩa sâu xa; có ẩn ý', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_37_4', 'en-b2-37', NULL, 'comprehensive_test', 'listening', 'The overall cost includes breakfast and a train ticket.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Theo tôi ước tính, chúng ta cần thêm ba chiếc ghế nữa.","Bạn có thích một màu cụ thể nào không?","Tổng chi phí đã bao gồm bữa sáng và một vé tàu.","Mục tiêu cuối cùng của chúng tôi là mua một ngôi nhà nhỏ."]'::jsonb, 2, 'The overall cost includes breakfast and a train ticket. → Tổng chi phí đã bao gồm bữa sáng và một vé tàu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_37_5', 'en-b2-37', NULL, 'comprehensive_test', 'listening', 'undoubtedly', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chắc chắn; không nghi ngờ gì; rõ ràng là","độ ẩm; hơi ẩm","sự điên rồ; hành vi cực kỳ ng U dốt và nguy hiểm","thuộc về nghe nhìn"]'::jsonb, 0, 'undoubtedly (/ʌnˈdaʊtɪdli/) → chắc chắn; không nghi ngờ gì; rõ ràng là', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_37_6', 'en-b2-37', NULL, 'comprehensive_test', 'listening', 'Is there a specific colour you would prefer?', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bạn có thích một màu cụ thể nào không?","Tiếng ồn liên tục bên ngoài khiến tôi khó tập trung.","Đây chắc chắn là chiếc áo khoác ấm nhất mà tôi từng có.","Chuyến leo núi rất mệt nhọc; thế nhưng, chúng tôi vẫn tận hưởng được khung cảnh."]'::jsonb, 0, 'Is there a specific colour you would prefer? → Bạn có thích một màu cụ thể nào không?', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_37_7', 'en-b2-37', NULL, 'comprehensive_test', 'listening', 'assume', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tháo ra; tách rời","do đó; vì vậy; kết quả là","cho rằng; giả định; nghĩ rằng","phí cầu đường; lệ phí qua đường"]'::jsonb, 2, 'assume (/əˈsuːm/) → cho rằng; giả định; nghĩ rằng; đảm nhận; gánh vác; nhậm chức; mang; có được (vẻ ngoài hoặc tính chất)', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_37_8', 'en-b2-37', NULL, 'comprehensive_test', 'listening', 'The constant noise outside made concentration difficult for me.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chiếc bánh mì kẹp nhỏ xíu này có mức giá đắt đến mức vô lý.","Tiếng ồn liên tục bên ngoài khiến tôi khó tập trung.","Ổ bánh mì được nướng chín hoàn hảo với phần vỏ giòn rụm.","Chiến thuật của cô ấy là tập luyện trước khi tất cả mọi người đến."]'::jsonb, 1, 'The constant noise outside made concentration difficult for me. → Tiếng ồn liên tục bên ngoài khiến tôi khó tập trung.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_37_9', 'en-b2-37', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Certainly true, with no reasonable doubt.”?', '["ridiculous","undoubtedly","estimation","tactic"]'::jsonb, 1, 'undoubtedly (/ʌnˈdaʊtɪdli/) → chắc chắn; không nghi ngờ gì; rõ ràng là', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
