INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_37_18', 'en-b2-37', NULL, 'comprehensive_test', 'reading', NULL, 'Urban planners must foresee future transport needs before approving major housing developments on the city''s outskirts.', 'Dựa vào câu trên, từ “foresee” có nghĩa phù hợp nhất là gì?', '["sự trợ giúp; sự hỗ trợ","dự đoán; thấy trước","động lực; sự khuyến khích; tiền thưởng khích lệ","bách khoa toàn thư"]'::jsonb, 1, 'foresee: dự đoán; thấy trước. Dịch cả câu: Các nhà quy hoạch đô thị phải dự đoán nhu cầu giao thông trong tương lai trước khi phê duyệt các dự án phát triển nhà ở quy mô lớn ở vùng ngoại ô thành phố.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_37_19', 'en-b2-37', NULL, 'comprehensive_test', 'reading', NULL, 'Researchers analyze traffic patterns to identify areas where improved public transport could reduce congestion.', 'Dựa vào câu trên, từ “analyze” có nghĩa phù hợp nhất là gì?', '["thuộc địa","làm nhiễm trùng; lây bệnh","thúc giục; nài nỉ; khuyên răn mạnh mẽ","phân tích"]'::jsonb, 3, 'analyze: phân tích. Dịch cả câu: Các nhà nghiên cứu phân tích các mẫu hình giao thông để xác định những khu vực mà việc cải thiện giao thông công cộng có thể làm giảm tình trạng tắc nghẽn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_37_20', 'en-b2-37', NULL, 'comprehensive_test', 'reading', NULL, 'Access to reliable internet services has a significant impact on educational opportunities in remote communities.', 'Dựa vào câu trên, từ “significant” có nghĩa phù hợp nhất là gì?', '["đáng kể; quan trọng; lớn","con tin","bắt giữ; tóm gọn","có tính chiếm hữu; ích kỷ trong quan hệ"]'::jsonb, 0, 'significant: đáng kể; quan trọng; lớn; mang ý nghĩa sâu xa; có ẩn ý. Dịch cả câu: Khả năng tiếp cận các dịch vụ Internet đáng tin cậy có tác động quan trọng đến các cơ hội giáo dục ở các cộng đồng vùng sâu vùng xa.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_37_21', 'en-b2-37', NULL, 'comprehensive_test', 'reading', NULL, 'Overall, investment in public transport can reduce urban congestion while improving access to employment opportunities.', 'Dựa vào câu trên, từ “overall” có nghĩa phù hợp nhất là gì?', '["trong suốt","thế thân; vật thay thế","sự tham gia; sự góp mặt","tổng thể; toàn bộ; chung"]'::jsonb, 3, 'overall: tổng thể; toàn bộ; chung; nhìn chung; tổng quan; nói chung. Dịch cả câu: Nhìn chung, việc đầu tư vào giao thông công cộng có thể làm giảm tình trạng tắc nghẽn đô thị đồng thời cải thiện khả năng tiếp cận các cơ hội việc làm.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_37_22', 'en-b2-37', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự lựa chọn thay thế; phương án thay thế”', '["armour","tiptoe","interact","alternative"]'::jsonb, 3, 'sự lựa chọn thay thế; phương án thay thế → alternative (/ɔːlˈtɝːnətɪv/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_37_23', 'en-b2-37', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cơ bản; nền tảng; cốt lõi”', '["chairwoman","fundamental","impose","doubtful"]'::jsonb, 1, 'cơ bản; nền tảng; cốt lõi → fundamental (/ˌfʌndəˈmentəl/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_37_24', 'en-b2-37', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “loại bỏ; xóa bỏ hoàn toàn”', '["overtime","eliminate","sack","relay"]'::jsonb, 1, 'loại bỏ; xóa bỏ hoàn toàn → eliminate (/ɪˈlɪmɪneɪt/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-38', 'en', 'Bài 38: Tư duy & Nhận thức (5) - CEFR B2', 'CEFR B2', 'B2 · Tư duy', '28 từ vựng Tiếng Anh CEFR B2 chủ đề tư duy & nhận thức kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4038, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_relate', 'en-b2-38', 'relate', '/rɪˈleɪt/', 'B2', 'liên quan; gắn kết; thấu cảm; đồng cảm; kể lại; thuật lại', 'v.', 'related (adj.), relation (n.), relationship (n.), unrelated (adj.)', 'Đồng nghĩa: connect, recount', 'Cấu trúc relate to có thể mang nghĩa "liên quan đến" hoặc "đồng cảm, thấu hiểu".', 'I can relate to your fear of flying.', NULL, 'Tôi hoàn toàn có thể thấu cảm với nỗi sợ đi máy bay của bạn.', '{"wordId":"relate","ukIpa":"/rɪˈleɪt/","usIpa":"/rɪˈleɪt/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"To have or establish a connection between things.","vi":"liên quan; gắn kết"},{"pos":"v.","en":"To understand someone''s feelings through similar personal experience.","vi":"thấu cảm; đồng cảm"},{"pos":"v.","en":"To tell someone about events or experiences.","vi":"kể lại; thuật lại"}],"examples":[{"en":"I can relate to your fear of flying.","vi":"Tôi hoàn toàn có thể thấu cảm với nỗi sợ đi máy bay của bạn.","audioKind":"ex"},{"en":"Researchers should relate their findings to existing evidence before drawing conclusions about the causes of unemployment.","vi":"Các nhà nghiên cứu nên liên kết kết quả phát hiện của họ với các bằng chứng hiện có trước khi đưa ra kết luận về nguyên nhân dẫn đến tình trạng thất nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"relate to","vi":"liên quan đến; thấu cảm với"},{"en":"relate A to B","vi":"liên kết A với B"},{"en":"relate an experience","vi":"kể lại một trải nghiệm"}],"wordFamily":["related (adj.)","relation (n.)","relationship (n.)","unrelated (adj.)"],"synonyms":["connect","recount"],"antonyms":[],"tipVi":"Cấu trúc relate to có thể mang nghĩa \"liên quan đến\" hoặc \"đồng cảm, thấu hiểu\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_seemingly', 'en-b2-38', 'seemingly', '/ˈsiːmɪŋli/', 'B2', 'có vẻ như; thoạt nhìn thì', 'adv.', 'seem (v.), seeming (adj.)', 'Đồng nghĩa: apparently', 'Thường đứng trước tính từ, nhấn mạnh rằng vẻ bề ngoài chưa chắc đã đúng sự thật.', 'The seemingly empty box had a kitten inside.', NULL, 'Cái hộp thoạt nhìn có vẻ trống rỗng nhưng bên trong lại có một chú mèo con.', '{"wordId":"seemingly","ukIpa":"/ˈsiːmɪŋli/","usIpa":"/ˈsiːmɪŋli/","cefr":"B2","topic":"thinking","senses":[{"pos":"adv.","en":"In a way that appears true but may not be.","vi":"có vẻ như; thoạt nhìn thì"}],"examples":[{"en":"The seemingly empty box had a kitten inside.","vi":"Cái hộp thoạt nhìn có vẻ trống rỗng nhưng bên trong lại có một chú mèo con.","audioKind":"ex"},{"en":"Seemingly minor changes in daily travel habits can significantly reduce a city''s overall carbon emissions.","vi":"Những thay đổi có vẻ nhỏ nhặt trong thói quen đi lại hằng ngày có thể làm giảm đáng kể lượng khí thải carbon tổng thể của một thành phố.","audioKind":"ex2"}],"collocations":[{"en":"seemingly impossible","vi":"có vẻ như không thể"},{"en":"seemingly endless","vi":"dường như vô tận"},{"en":"seemingly harmless","vi":"có vẻ vô hại"}],"wordFamily":["seem (v.)","seeming (adj.)"],"synonyms":["apparently"],"antonyms":[],"tipVi":"Thường đứng trước tính từ, nhấn mạnh rằng vẻ bề ngoài chưa chắc đã đúng sự thật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_imaginative', 'en-b2-38', 'imaginative', '/ɪˈmædʒɪnətɪv/', 'B2', 'giàu trí tưởng tượng; sáng tạo', 'adj.', 'imagine (v.), imagination (n.), imaginatively (adv.), unimaginative (adj.)', 'Đồng nghĩa: creative, inventive · Trái nghĩa: unimaginative', 'imaginative chỉ có trí tưởng tượng/sáng tạo; imaginary chỉ mang tính tưởng tượng không có thực.', 'My imaginative niece turned empty boxes into a spaceship.', NULL, 'Cô cháu gái giàu trí tưởng tượng của tôi đã biến những chiếc hộp rỗng thành một con tàu vũ trụ.', '{"wordId":"imaginative","ukIpa":"/ɪˈmædʒɪnətɪv/","usIpa":"/ɪˈmædʒɪnətɪv/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"able to produce original ideas, or showing this ability","vi":"giàu trí tưởng tượng; sáng tạo"}],"examples":[{"en":"My imaginative niece turned empty boxes into a spaceship.","vi":"Cô cháu gái giàu trí tưởng tượng của tôi đã biến những chiếc hộp rỗng thành một con tàu vũ trụ.","audioKind":"ex"},{"en":"Schools should encourage imaginative thinking rather than require students to memorise every detail of a textbook.","vi":"Nhà trường nên khuyến khích tư duy sáng tạo thay vì bắt học sinh ghi nhớ từng chi tiết trong sách giáo khoa.","audioKind":"ex2"}],"collocations":[{"en":"imaginative thinking","vi":"tư duy sáng tạo"},{"en":"imaginative approach","vi":"phương pháp sáng tạo"},{"en":"imaginative solution","vi":"giải pháp sáng tạo"}],"wordFamily":["imagine (v.)","imagination (n.)","imaginatively (adv.)","unimaginative (adj.)"],"synonyms":["creative","inventive"],"antonyms":["unimaginative"],"tipVi":"imaginative chỉ có trí tưởng tượng/sáng tạo; imaginary chỉ mang tính tưởng tượng không có thực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_characteristic', 'en-b2-38', 'characteristic', '/ˌkærəktəˈrɪstɪk/', 'B2', 'đặc điểm; nét tiêu biểu của một người hoặc một vật; điển hình; đặc trưng của một người, sự vật hoặc nhóm cụ thể', 'n.', 'characteristically (adv.), characterise (v.), characterisation (n.)', 'Đồng nghĩa: feature, trait', 'Tính từ thường dùng trong cấu trúc be characteristic of, thể hiện là đặc điểm tiêu biểu của...', 'One striking characteristic of this cat is its curly fur.', NULL, 'Một đặc điểm nổi bật của con mèo này là bộ lông xoăn của nó.', '{"wordId":"characteristic","ukIpa":"/ˌkærəktəˈrɪstɪk/","usIpa":"/ˌkærəktəˈrɪstɪk/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"A quality that is typical of a person or thing.","vi":"đặc điểm; nét tiêu biểu của một người hoặc một vật"},{"pos":"adj.","en":"Typical of a particular person, thing, or group.","vi":"điển hình; đặc trưng của một người, sự vật hoặc nhóm cụ thể"}],"examples":[{"en":"One striking characteristic of this cat is its curly fur.","vi":"Một đặc điểm nổi bật của con mèo này là bộ lông xoăn của nó.","audioKind":"ex"},{"en":"The ability to adapt quickly is an important characteristic of successful businesses in a changing economy.","vi":"Khả năng thích ứng nhanh là một đặc điểm quan trọng của các doanh nghiệp thành công trong nền kinh tế đang thay đổi.","audioKind":"ex2"}],"collocations":[{"en":"distinctive characteristic","vi":"đặc điểm nổi bật"},{"en":"physical characteristics","vi":"đặc điểm thể chất"},{"en":"characteristic of","vi":"đặc trưng của"}],"wordFamily":["characteristically (adv.)","characterise (v.)","characterisation (n.)"],"synonyms":["feature","trait"],"antonyms":[],"tipVi":"Tính từ thường dùng trong cấu trúc be characteristic of, thể hiện là đặc điểm tiêu biểu của...","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_relatively', 'en-b2-38', 'relatively', '/ˈrelətɪvli/', 'B2', 'tương đối; khá là', 'adv.', 'relative (adj.)', 'Đồng nghĩa: comparatively', 'Biểu thị mức độ qua so sánh, không đồng nghĩa với từ very.', 'The kitchen is relatively small, but it feels bright.', NULL, 'Phòng bếp khá nhỏ, nhưng mang lại cảm giác sáng sủa.', '{"wordId":"relatively","ukIpa":"/ˈrelətɪvli/","usIpa":"/ˈrelətɪvli/","cefr":"B2","topic":"thinking","senses":[{"pos":"adv.","en":"To a certain degree compared with something else.","vi":"tương đối; khá là"}],"examples":[{"en":"The kitchen is relatively small, but it feels bright.","vi":"Phòng bếp khá nhỏ, nhưng mang lại cảm giác sáng sủa.","audioKind":"ex"},{"en":"Cycling is a relatively inexpensive form of transport that can reduce congestion in crowded cities.","vi":"Đi xe đạp là một hình thức di chuyển tương đối rẻ tiền, có thể giúp giảm tình trạng ùn tắc ở các thành phố đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"relatively low","vi":"tương đối thấp"},{"en":"relatively easy","vi":"khá dễ dàng"},{"en":"relatively speaking","vi":"tương đối mà nói; xét về mặt tương đối"}],"wordFamily":["relative (adj.)"],"synonyms":["comparatively"],"antonyms":[],"tipVi":"Biểu thị mức độ qua so sánh, không đồng nghĩa với từ very.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_merely', 'en-b2-38', 'merely', '/ˈmɪrli/', 'B2', 'chỉ là; đơn thuần là', 'adv.', 'mere (adj.)', 'Đồng nghĩa: only, just, simply', 'Sắc thái trang trọng hơn từ only; thường được đặt trước động từ thường và sau động từ to be.', 'I wasn''t complaining; I was merely asking a question.', NULL, 'Tôi không hề phàn nàn; tôi chỉ đang đặt một câu hỏi mà thôi.', '{"wordId":"merely","ukIpa":"/ˈmɪəli/","usIpa":"/ˈmɪrli/","cefr":"B2","topic":"thinking","senses":[{"pos":"adv.","en":"only, and nothing more or more important","vi":"chỉ là; đơn thuần là"}],"examples":[{"en":"I wasn''t complaining; I was merely asking a question.","vi":"Tôi không hề phàn nàn; tôi chỉ đang đặt một câu hỏi mà thôi.","audioKind":"ex"},{"en":"Building more roads merely shifts traffic problems elsewhere unless governments also invest in reliable public transport.","vi":"Việc xây dựng thêm đường xá đơn thuần chỉ đẩy vấn đề giao thông sang nơi khác trừ khi chính phủ cũng đầu tư vào hệ thống giao thông công cộng đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"merely a matter of","vi":"chỉ là vấn đề về"},{"en":"not merely","vi":"không chỉ đơn thuần là"},{"en":"merely because","vi":"chỉ vì"}],"wordFamily":["mere (adj.)"],"synonyms":["only","just","simply"],"antonyms":[],"tipVi":"Sắc thái trang trọng hơn từ only; thường được đặt trước động từ thường và sau động từ to be.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_imply', 'en-b2-38', 'imply', '/ɪmˈplaɪ/', 'B2', 'ám chỉ; ngụ ý; bao hàm; ngầm hiểu', 'v.', 'implication (n.), implied (adj.)', 'Đồng nghĩa: suggest, insinuate · Trái nghĩa: state explicitly', '"imply" là người nói ám chỉ; "infer" là người nghe suy ra.', 'Are you trying to imply that my cooking is bad?', NULL, 'Bạn đang cố ám chỉ rằng tôi nấu ăn dở phải không?', '{"wordId":"imply","ukIpa":"/ɪmˈplaɪ/","usIpa":"/ɪmˈplaɪ/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"To suggest something without stating it directly.","vi":"ám chỉ; ngụ ý"},{"pos":"v.","en":"To involve something as a necessary result or condition.","vi":"bao hàm; ngầm hiểu"}],"examples":[{"en":"Are you trying to imply that my cooking is bad?","vi":"Bạn đang cố ám chỉ rằng tôi nấu ăn dở phải không?","audioKind":"ex"},{"en":"Higher spending on education does not necessarily imply better outcomes unless resources are allocated effectively.","vi":"Việc chi tiêu nhiều hơn cho giáo dục không nhất thiết có nghĩa là kết quả sẽ tốt hơn trừ khi các nguồn lực được phân bổ hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"imply that","vi":"ám chỉ rằng"},{"en":"not necessarily imply","vi":"không nhất thiết có nghĩa là"},{"en":"strongly imply","vi":"ám chỉ mạnh mẽ"}],"wordFamily":["implication (n.)","implied (adj.)"],"synonyms":["suggest","insinuate"],"antonyms":["state explicitly"],"tipVi":"\"imply\" là người nói ám chỉ; \"infer\" là người nghe suy ra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_marked', 'en-b2-38', 'marked', '/mɑːrkt/', 'B2', 'rõ rệt; đáng kể; rõ ràng; có đánh dấu; có ký hiệu', 'adj.', 'mark (v.), mark (n.), markedly (adv.), unmarked (adj.)', 'Đồng nghĩa: noticeable, pronounced, distinct · Trái nghĩa: unmarked', 'Thường dùng trong văn phong học thuật để diễn tả ý nghĩa "rõ rệt, đáng kể"; phát âm đuôi là /t/.', 'There is a marked difference between these two cakes.', NULL, 'Có sự khác biệt rõ rệt giữa hai chiếc bánh này.', '{"wordId":"marked","ukIpa":"/mɑːkt/","usIpa":"/mɑːrkt/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Clearly noticeable and often substantial","vi":"rõ rệt; đáng kể; rõ ràng"},{"pos":"adj.","en":"Having a visible mark that identifies or distinguishes something","vi":"có đánh dấu; có ký hiệu"}],"examples":[{"en":"There is a marked difference between these two cakes.","vi":"Có sự khác biệt rõ rệt giữa hai chiếc bánh này.","audioKind":"ex"},{"en":"The introduction of dedicated cycle lanes led to a marked increase in bicycle use among urban commuters.","vi":"Việc đưa vào sử dụng các làn đường dành riêng cho xe đạp đã dẫn đến sự gia tăng đáng kể trong việc sử dụng xe đạp của những người đi làm ở đô thị.","audioKind":"ex2"}],"collocations":[{"en":"a marked increase","vi":"sự gia tăng đáng kể"},{"en":"a marked improvement","vi":"sự cải thiện rõ rệt"},{"en":"a marked contrast","vi":"sự tương phản rõ rệt"},{"en":"clearly marked","vi":"được đánh dấu rõ ràng"}],"wordFamily":["mark (v.)","mark (n.)","markedly (adv.)","unmarked (adj.)"],"synonyms":["noticeable","pronounced","distinct"],"antonyms":["unmarked"],"tipVi":"Thường dùng trong văn phong học thuật để diễn tả ý nghĩa \"rõ rệt, đáng kể\"; phát âm đuôi là /t/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_approximate', 'en-b2-38', 'approximate', '/əˈprɑːksɪmət/', 'B2', 'xấp xỉ; khoảng; gần bằng', 'adj.', 'approximately (adv.), approximation (n.)', 'Đồng nghĩa: rough, estimated · Trái nghĩa: exact, precise', 'Tính từ có phần đuôi phát âm là /mət/, trong khi động từ phát âm là /meɪt/.', 'Can you give me an approximate price for the repairs?', NULL, 'Bạn có thể cho tôi biết giá xấp xỉ của việc sửa chữa này không?', '{"wordId":"approximate","ukIpa":"/əˈprɒksɪmət/","usIpa":"/əˈprɑːksɪmət/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Close to the actual amount or value, but not exact","vi":"xấp xỉ; khoảng"},{"pos":"v.","en":"To be close to something in amount, quality, or character","vi":"xấp xỉ; gần bằng"}],"examples":[{"en":"Can you give me an approximate price for the repairs?","vi":"Bạn có thể cho tôi biết giá xấp xỉ của việc sửa chữa này không?","audioKind":"ex"},{"en":"Researchers used survey responses to calculate the approximate proportion of residents who regularly used public transport.","vi":"Các nhà nghiên cứu đã sử dụng các câu trả lời khảo sát để tính toán tỷ lệ xấp xỉ của cư dân thường xuyên sử dụng phương tiện giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"approximate cost","vi":"chi phí ước tính"},{"en":"approximate size","vi":"kích thước xấp xỉ"},{"en":"approximate figure","vi":"con số ước chừng"}],"wordFamily":["approximately (adv.)","approximation (n.)"],"synonyms":["rough","estimated"],"antonyms":["exact","precise"],"tipVi":"Tính từ có phần đuôi phát âm là /mət/, trong khi động từ phát âm là /meɪt/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conscience', 'en-b2-38', 'conscience', '/ˈkɑːnʃəns/', 'B2', 'lương tâm; ý thức đạo đức; sự ân hận; nỗi day dứt', 'n.', 'conscientious (adj.), conscientiously (adv.)', NULL, 'conscience là lương tâm; conscious là có ý thức.', 'My conscience told me to return the lost wallet.', NULL, 'Lương tâm bảo tôi phải trả lại chiếc ví bị mất.', '{"wordId":"conscience","ukIpa":"/ˈkɒnʃəns/","usIpa":"/ˈkɑːnʃəns/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"Your inner sense of what is right and wrong.","vi":"lương tâm; ý thức đạo đức"},{"pos":"n.","en":"Guilt about something wrong you have done.","vi":"sự ân hận; nỗi day dứt"}],"examples":[{"en":"My conscience told me to return the lost wallet.","vi":"Lương tâm bảo tôi phải trả lại chiếc ví bị mất.","audioKind":"ex"},{"en":"Consumers may struggle with their conscience when buying cheap products made under poor working conditions.","vi":"Người tiêu dùng có thể phải dằn vặt lương tâm khi mua các sản phẩm giá rẻ được sản xuất trong điều kiện lao động tồi tệ.","audioKind":"ex2"}],"collocations":[{"en":"a clear conscience","vi":"lương tâm trong sạch"},{"en":"a guilty conscience","vi":"sự cắn rứt lương tâm"},{"en":"a matter of conscience","vi":"vấn đề thuộc về lương tâm"}],"wordFamily":["conscientious (adj.)","conscientiously (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"conscience là lương tâm; conscious là có ý thức.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_suspicious', 'en-b2-38', 'suspicious', '/səˈspɪʃəs/', 'B2', 'khả nghi; đáng ngờ; hoài nghi; đa nghi', 'adj.', 'suspicion (n.), suspect (v.), suspiciously (adv.)', 'Đồng nghĩa: suspect, distrustful · Trái nghĩa: trusting', 'Sự việc đáng ngờ dùng suspicious; hoài nghi điều gì dùng suspicious of.', 'I noticed a suspicious charge on my bank statement.', NULL, 'Tôi nhận thấy có một khoản phí khả nghi trong sao kê ngân hàng của mình.', '{"wordId":"suspicious","ukIpa":"/səˈspɪʃəs/","usIpa":"/səˈspɪʃəs/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Making you think something is wrong, dishonest, or illegal.","vi":"khả nghi; đáng ngờ"},{"pos":"adj.","en":"Feeling that someone or something cannot be trusted.","vi":"hoài nghi; đa nghi"}],"examples":[{"en":"I noticed a suspicious charge on my bank statement.","vi":"Tôi nhận thấy có một khoản phí khả nghi trong sao kê ngân hàng của mình.","audioKind":"ex"},{"en":"Consumers are increasingly suspicious of environmental claims that companies make without providing clear evidence to support them.","vi":"Người tiêu dùng ngày càng tỏ ra hoài nghi đối với các tuyên bố về môi trường mà doanh nghiệp đưa ra nhưng không có bằng chứng rõ ràng chứng minh.","audioKind":"ex2"}],"collocations":[{"en":"suspicious behaviour","vi":"hành vi đáng ngờ"},{"en":"suspicious circumstances","vi":"hoàn cảnh khả nghi"},{"en":"suspicious of someone","vi":"hoài nghi ai đó"},{"en":"highly suspicious","vi":"rất đáng ngờ"}],"wordFamily":["suspicion (n.)","suspect (v.)","suspiciously (adv.)"],"synonyms":["suspect","distrustful"],"antonyms":["trusting"],"tipVi":"Sự việc đáng ngờ dùng suspicious; hoài nghi điều gì dùng suspicious of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sequence', 'en-b2-38', 'sequence', '/ˈsiːkwəns/', 'B2', 'trình tự; chuỗi; một loạt; sắp xếp theo trình tự', 'n.', 'sequential (adj.), sequentially (adv.)', 'Đồng nghĩa: series, order', 'Cụm a sequence of đi với danh từ số nhiều, biểu thị một chuỗi sự việc.', 'Arrange these pictures in the correct sequence before dinner.', NULL, 'Hãy sắp xếp những bức tranh này theo đúng trình tự trước bữa tối.', '{"wordId":"sequence","ukIpa":"/ˈsiːkwəns/","usIpa":"/ˈsiːkwəns/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"An ordered series of things, actions, or events.","vi":"trình tự; chuỗi; một loạt"},{"pos":"v.","en":"To arrange things or events in a particular order.","vi":"sắp xếp theo trình tự"}],"examples":[{"en":"Arrange these pictures in the correct sequence before dinner.","vi":"Hãy sắp xếp những bức tranh này theo đúng trình tự trước bữa tối.","audioKind":"ex"},{"en":"Understanding the sequence of events helps researchers identify the factors that contributed to an environmental disaster.","vi":"Việc nắm bắt chuỗi sự kiện giúp các nhà nghiên cứu xác định những yếu tố góp phần gây ra thảm họa môi trường.","audioKind":"ex2"}],"collocations":[{"en":"in sequence","vi":"theo thứ tự"},{"en":"a sequence of events","vi":"một loạt các sự kiện"},{"en":"the correct sequence","vi":"trình tự chính xác"}],"wordFamily":["sequential (adj.)","sequentially (adv.)"],"synonyms":["series","order"],"antonyms":[],"tipVi":"Cụm a sequence of đi với danh từ số nhiều, biểu thị một chuỗi sự việc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inferior', 'en-b2-38', 'inferior', '/ɪnˈfɪriər/', 'B2', 'kém hơn; thấp kém; cấp bậc thấp hơn; cấp dưới', 'adj.', 'inferiority (n.)', 'Đồng nghĩa: substandard · Trái nghĩa: superior', 'So sánh dùng inferior to, không dùng than; feel inferior nghĩa là tự ti.', 'The cheaper bag felt inferior to the leather one.', NULL, 'Chiếc túi rẻ hơn có cảm giác kém hơn so với chiếc túi da.', '{"wordId":"inferior","ukIpa":"/ɪnˈfɪəriə/","usIpa":"/ɪnˈfɪriər/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Lower in quality, value, or ability than something else.","vi":"kém hơn; thấp kém"},{"pos":"adj.","en":"Having a lower rank or position.","vi":"cấp bậc thấp hơn"},{"pos":"n.","en":"Someone with a lower rank or position than another person.","vi":"cấp dưới"}],"examples":[{"en":"The cheaper bag felt inferior to the leather one.","vi":"Chiếc túi rẻ hơn có cảm giác kém hơn so với chiếc túi da.","audioKind":"ex"},{"en":"Schools in disadvantaged areas should not receive inferior equipment simply because local funding is limited.","vi":"Các trường học ở vùng khó khăn không nên nhận trang thiết bị kém chất lượng chỉ vì nguồn kinh phí địa phương hạn hẹp.","audioKind":"ex2"}],"collocations":[{"en":"inferior to","vi":"kém hơn"},{"en":"inferior quality","vi":"chất lượng kém"},{"en":"feel inferior","vi":"cảm thấy tự ti"}],"wordFamily":["inferiority (n.)"],"synonyms":["substandard"],"antonyms":["superior"],"tipVi":"So sánh dùng inferior to, không dùng than; feel inferior nghĩa là tự ti.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_core', 'en-b2-38', 'core', '/kɔːr/', 'B2', 'phần cốt lõi, trung tâm, quan trọng nhất; lõi (trái cây); mang tính cốt lõi, trung tâm và rất quan trọng; khoét lõi, bỏ lõi (của quả)', 'n.', NULL, 'Đồng nghĩa: centre', 'Phần lõi cứng của quả táo, lê,... gọi là "core"; trong khi hột cứng của quả đào, mận,... thường gọi là "stone".', 'She ate the apple and threw away the core.', NULL, 'Cô ấy ăn xong quả táo và vứt phần lõi đi.', '{"wordId":"core","ukIpa":"/kɔː/","usIpa":"/kɔːr/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"the central or most important part of something","vi":"phần cốt lõi, trung tâm, quan trọng nhất; lõi (trái cây)"},{"pos":"adj.","en":"central and essential to something","vi":"mang tính cốt lõi, trung tâm và rất quan trọng"},{"pos":"v.","en":"to remove the hard central part of a fruit","vi":"khoét lõi, bỏ lõi (của quả)"}],"examples":[{"en":"She ate the apple and threw away the core.","vi":"Cô ấy ăn xong quả táo và vứt phần lõi đi.","audioKind":"ex"},{"en":"Critical thinking should be a core skill taught in schools because it helps students evaluate information independently.","vi":"Tư duy phản biện nên là một kỹ năng cốt lõi được giảng dạy trong nhà trường vì nó giúp học sinh đánh giá thông tin một cách độc lập.","audioKind":"ex2"}],"collocations":[{"en":"at the core of","vi":"ở cốt lõi của"},{"en":"core skills","vi":"các kỹ năng cốt lõi"},{"en":"apple core","vi":"lõi táo"},{"en":"the Earth''s core","vi":"lõi Trái Đất"}],"wordFamily":[],"synonyms":["centre"],"antonyms":[],"tipVi":"Phần lõi cứng của quả táo, lê,... gọi là \"core\"; trong khi hột cứng của quả đào, mận,... thường gọi là \"stone\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vague', 'en-b2-38', 'vague', '/veɪɡ/', 'B2', 'mơ hồ; không rõ ràng; chung chung; mờ nhạt; không rõ nét (về hình dáng, ký ức hoặc cảm xúc)', 'adj.', 'vaguely (adv.), vagueness (n.)', 'Đồng nghĩa: unclear, imprecise · Trái nghĩa: clear, precise', 'Cụm từ be vague about diễn tả thái độ không nói rõ ràng hoặc mập mờ về một vấn đề nào đó.', 'His vague directions left us wandering around the station.', NULL, 'Những chỉ dẫn mơ hồ của anh ấy khiến chúng tôi cứ đi vòng quanh nhàga mãi.', '{"wordId":"vague","ukIpa":"/veɪɡ/","usIpa":"/veɪɡ/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Not clearly expressed or lacking specific details","vi":"mơ hồ; không rõ ràng; chung chung"},{"pos":"adj.","en":"Not clear in shape, memory, or feeling","vi":"mờ nhạt; không rõ nét (về hình dáng, ký ức hoặc cảm xúc)"}],"examples":[{"en":"His vague directions left us wandering around the station.","vi":"Những chỉ dẫn mơ hồ của anh ấy khiến chúng tôi cứ đi vòng quanh nhàga mãi.","audioKind":"ex"},{"en":"Vague environmental targets make it difficult for citizens to assess whether government policies are achieving meaningful progress.","vi":"Các mục tiêu môi trường mơ hồ khiến người dân khó đánh giá xem các chính sách của chính phủ có đang đạt được tiến bộ thực chất hay không.","audioKind":"ex2"}],"collocations":[{"en":"vague idea","vi":"ý tưởng mơ hồ"},{"en":"vague memory","vi":"ký ức mơ hồ"},{"en":"vague instructions","vi":"chỉ dẫn mơ hồ"},{"en":"vague about","vi":"không rõ về điều gì"}],"wordFamily":["vaguely (adv.)","vagueness (n.)"],"synonyms":["unclear","imprecise"],"antonyms":["clear","precise"],"tipVi":"Cụm từ be vague about diễn tả thái độ không nói rõ ràng hoặc mập mờ về một vấn đề nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_consequently', 'en-b2-38', 'consequently', '/ˈkɑːnsəkwentli/', 'B2', 'do đó; vì vậy; kết quả là', 'adv.', 'consequence (n.), consequent (adj.), consequential (adj.)', 'Đồng nghĩa: therefore, thus, hence', 'Là trạng từ chứ không phải liên hội từ; khi nối hai mệnh đề độc lập có thể dùng dấu chấm phẩy ở phía trước.', 'The bakery was closed; consequently, we went home without bread.', NULL, 'Tiệm bánh đã đóng cửa; do đó, chúng tôi ra về mà không mua được bánh mì.', '{"wordId":"consequently","ukIpa":"/ˈkɒnsɪkwəntli/","usIpa":"/ˈkɑːnsəkwentli/","cefr":"B2","topic":"thinking","senses":[{"pos":"adv.","en":"as a result of something mentioned earlier","vi":"do đó; vì vậy; kết quả là"}],"examples":[{"en":"The bakery was closed; consequently, we went home without bread.","vi":"Tiệm bánh đã đóng cửa; do đó, chúng tôi ra về mà không mua được bánh mì.","audioKind":"ex"},{"en":"Housing costs have risen sharply; consequently, many young adults are delaying their decision to live independently.","vi":"Chi phí nhà ở đã tăng vọt; do đó, nhiều người trẻ tuổi đang hoãn việc quyết định sống tự lập.","audioKind":"ex2"}],"collocations":[{"en":"and consequently","vi":"và do đó"},{"en":"consequently lead to","vi":"dẫn đến kết quả là"},{"en":"consequently require","vi":"do đó đòi hỏi"}],"wordFamily":["consequence (n.)","consequent (adj.)","consequential (adj.)"],"synonyms":["therefore","thus","hence"],"antonyms":[],"tipVi":"Là trạng từ chứ không phải liên hội từ; khi nối hai mệnh đề độc lập có thể dùng dấu chấm phẩy ở phía trước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grasp', 'en-b2-38', 'grasp', '/ɡræsp/', 'B2', 'hiểu; nắm bắt; lĩnh hội; nắm chặt; túm lấy; sự thấu hiểu; cái ôm chặt', 'v.', NULL, 'Đồng nghĩa: understand, comprehend, grip', 'Khi diễn tả sự thấu hiểu, từ này có thể dùng làm động từ; dạng danh từ thường đi với cụm a grasp of.', 'I finally grasped the rules after watching one round.', NULL, 'Cuối cùng tôi cũng hiểu được luật chơi sau khi theo dõi xong một hiệp.', '{"wordId":"grasp","ukIpa":"/ɡrɑːsp/","usIpa":"/ɡræsp/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"To understand something, especially a difficult idea.","vi":"hiểu; nắm bắt; lĩnh hội"},{"pos":"v.","en":"To take and hold something firmly.","vi":"nắm chặt; túm lấy"},{"pos":"n.","en":"An understanding of something, or a firm hold.","vi":"sự thấu hiểu; cái ôm chặt"}],"examples":[{"en":"I finally grasped the rules after watching one round.","vi":"Cuối cùng tôi cũng hiểu được luật chơi sau khi theo dõi xong một hiệp.","audioKind":"ex"},{"en":"Students grasp complex scientific concepts more easily when teachers connect them to familiar everyday experiences.","vi":"Học sinh dễ dàng tiếp thu các khái niệm khoa học phức tạp hơn khi giáo viên kết nối chúng với những trải nghiệm quen thuộc hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"grasp a concept","vi":"hiểu một khái niệm"},{"en":"a firm grasp of","vi":"sự thấu hiểu sâu sắc về..."},{"en":"grasp an opportunity","vi":"chớp lấy cơ hội"},{"en":"within reach or grasp","vi":"trong tầm tay; trong tầm với"}],"wordFamily":[],"synonyms":["understand","comprehend","grip"],"antonyms":[],"tipVi":"Khi diễn tả sự thấu hiểu, từ này có thể dùng làm động từ; dạng danh từ thường đi với cụm a grasp of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_calculation', 'en-b2-38', 'calculation', '/ˌkælkjəˈleɪʃən/', 'B2', 'sự tính toán; kết quả tính toán; sự ước tính; sự cân nhắc', 'n.', 'calculate (v.), calculator (n.), calculated (adj.), incalculable (adj.)', 'Đồng nghĩa: computation, reckoning', 'Một phép tính cụ thể là danh từ đếm được; khi chỉ quá trình tính toán thì có thể không đếm được.', 'My calculation showed we had enough money for dinner.', NULL, 'Phép tính của tôi cho thấy chúng tôi có đủ tiền cho bữa tối.', '{"wordId":"calculation","ukIpa":"/ˌkælkjʊˈleɪʃən/","usIpa":"/ˌkælkjəˈleɪʃən/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"the process or result of working something out using numbers","vi":"sự tính toán; kết quả tính toán"},{"pos":"n.","en":"a judgement about likely outcomes made after careful consideration","vi":"sự ước tính; sự cân nhắc"}],"examples":[{"en":"My calculation showed we had enough money for dinner.","vi":"Phép tính của tôi cho thấy chúng tôi có đủ tiền cho bữa tối.","audioKind":"ex"},{"en":"Accurate calculation of energy costs helps households compare heating systems and make informed decisions about long-term investments.","vi":"Việc tính toán chính xác chi phí năng lượng giúp các hộ gia đình so sánh các hệ thống sưởi và đưa ra quyết định sáng suốt về các khoản đầu tư dài hạn.","audioKind":"ex2"}],"collocations":[{"en":"perform a calculation","vi":"thực hiện phép tính"},{"en":"accurate calculation","vi":"tính toán chính xác"},{"en":"calculation error","vi":"lỗi tính toán"},{"en":"by my calculations","vi":"theo tính toán của tôi"}],"wordFamily":["calculate (v.)","calculator (n.)","calculated (adj.)","incalculable (adj.)"],"synonyms":["computation","reckoning"],"antonyms":[],"tipVi":"Một phép tính cụ thể là danh từ đếm được; khi chỉ quá trình tính toán thì có thể không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_essentially', 'en-b2-38', 'essentially', '/ɪˈsenʃəli/', 'B2', 'về cơ bản; bản chất là; cốt lõi là', 'adv.', 'essential (adj.), essence (n.)', 'Đồng nghĩa: basically, fundamentally', 'Đây là trạng từ, không phải tính từ; thường dùng để khái quát các đặc điểm hoặc sự thật cốt lõi.', 'These two phones are essentially the same, apart from colour.', NULL, 'Hai chiếc điện thoại này về cơ bản là giống nhau, ngoại trừ màu sắc.', '{"wordId":"essentially","ukIpa":"/ɪˈsenʃəli/","usIpa":"/ɪˈsenʃəli/","cefr":"B2","topic":"thinking","senses":[{"pos":"adv.","en":"When considering the most important features or facts.","vi":"về cơ bản; bản chất là; cốt lõi là"}],"examples":[{"en":"These two phones are essentially the same, apart from colour.","vi":"Hai chiếc điện thoại này về cơ bản là giống nhau, ngoại trừ màu sắc.","audioKind":"ex"},{"en":"Although teaching methods have changed, the purpose of education remains essentially the same across generations.","vi":"Mặc dù phương pháp giảng dạy đã thay đổi, mục đích của giáo dục về cơ bản vẫn giữ nguyên qua các thế hệ.","audioKind":"ex2"}],"collocations":[{"en":"essentially the same","vi":"cơ bản là giống nhau"},{"en":"essentially different","vi":"về bản chất là khác nhau"},{"en":"essentially a matter of","vi":"về cơ bản là vấn đề về"}],"wordFamily":["essential (adj.)","essence (n.)"],"synonyms":["basically","fundamentally"],"antonyms":[],"tipVi":"Đây là trạng từ, không phải tính từ; thường dùng để khái quát các đặc điểm hoặc sự thật cốt lõi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_corresponding', 'en-b2-38', 'corresponding', '/ˌkɔːrəˈspɑːndɪŋ/', 'B2', 'tương ứng, có liên quan trực tiếp với cái khác', 'adj.', 'correspond (v.), correspondence (n.), correspondingly (adv.)', 'Đồng nghĩa: matching, equivalent', 'Nhấn mạnh mối quan hệ tương hỗ; correspond to diễn tả việc tương ứng với thứ gì đó.', 'Put each coloured lid on its corresponding container.', NULL, 'Hãy đặt mỗi chiếc nắp màu lên chiếc hộp tương ứng của nó.', '{"wordId":"corresponding","ukIpa":"/ˌkɒrɪˈspɒndɪŋ/","usIpa":"/ˌkɔːrəˈspɑːndɪŋ/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Matching or directly related to something else","vi":"tương ứng, có liên quan trực tiếp với cái khác"}],"examples":[{"en":"Put each coloured lid on its corresponding container.","vi":"Hãy đặt mỗi chiếc nắp màu lên chiếc hộp tương ứng của nó.","audioKind":"ex"},{"en":"A rise in urban population often creates a corresponding increase in demand for public transport.","vi":"Sự gia tăng dân số đô thị thường tạo ra nhu cầu tương ứng về phương tiện giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"corresponding increase","vi":"sự gia tăng tương ứng"},{"en":"corresponding period","vi":"kỳ tương ứng"},{"en":"corresponding figures","vi":"số liệu tương ứng"}],"wordFamily":["correspond (v.)","correspondence (n.)","correspondingly (adv.)"],"synonyms":["matching","equivalent"],"antonyms":[],"tipVi":"Nhấn mạnh mối quan hệ tương hỗ; correspond to diễn tả việc tương ứng với thứ gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_doubtful', 'en-b2-38', 'doubtful', '/ˈdaʊtfəl/', 'B2', 'hoài nghi; không chắc chắn; ít có khả năng xảy ra; khó có thể; đáng ngờ; không đáng tin cậy', 'adj.', 'doubt (n.), doubt (v.), doubtfully (adv.), doubtless (adv.)', 'Đồng nghĩa: uncertain, unsure, questionable · Trái nghĩa: certain, confident', 'Chủ ngữ chỉ người thường dùng doubtful about; cũng có thể dùng doubtful whether.', 'I was doubtful about buying a second-hand bicycle online.', NULL, 'Tôi thấy băn khoăn về việc mua một chiếc xe đạp cũ trên mạng.', '{"wordId":"doubtful","ukIpa":"/ˈdaʊtfəl/","usIpa":"/ˈdaʊtfəl/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Feeling unsure whether something is true or will happen.","vi":"hoài nghi; không chắc chắn"},{"pos":"adj.","en":"Unlikely to happen or be true.","vi":"ít có khả năng xảy ra; khó có thể"},{"pos":"adj.","en":"Not clearly good, honest, or reliable.","vi":"đáng ngờ; không đáng tin cậy"}],"examples":[{"en":"I was doubtful about buying a second-hand bicycle online.","vi":"Tôi thấy băn khoăn về việc mua một chiếc xe đạp cũ trên mạng.","audioKind":"ex"},{"en":"It is doubtful whether expanding roads alone can solve traffic congestion in rapidly growing cities.","vi":"Vẫn còn phải xem liệu việc chỉ mở rộng đường sá có thể giải quyết được tình trạng tắc nghẽn giao thông ở các đô thị đang phát triển nhanh chóng hay không.","audioKind":"ex2"}],"collocations":[{"en":"doubtful about","vi":"hoài nghi về"},{"en":"doubtful whether","vi":"còn nghi ngờ liệu"},{"en":"of doubtful value","vi":"có giá trị đáng ngờ"}],"wordFamily":["doubt (n.)","doubt (v.)","doubtfully (adv.)","doubtless (adv.)"],"synonyms":["uncertain","unsure","questionable"],"antonyms":["certain","confident"],"tipVi":"Chủ ngữ chỉ người thường dùng doubtful about; cũng có thể dùng doubtful whether.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_distinguish', 'en-b2-38', 'distinguish', '/dɪˈstɪŋɡwɪʃ/', 'B2', 'phân biệt; nhận diện; làm nổi bật; làm cho khác biệt; nhìn rõ; nghe rõ', 'v.', 'distinction (n.), distinctive (adj.), distinguishable (adj.), distinguished (adj.)', 'Đồng nghĩa: differentiate, tell apart · Trái nghĩa: confuse', 'Thường dùng cấu trúc distinguish A from B hoặc between A and B.', 'I can distinguish the twins by their voices.', NULL, 'Tôi có thể phân biệt cặp sinh đôi qua giọng nói của họ.', '{"wordId":"distinguish","ukIpa":"/dɪˈstɪŋɡwɪʃ/","usIpa":"/dɪˈstɪŋɡwɪʃ/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"to recognize the difference between people or things","vi":"phân biệt; nhận diện"},{"pos":"v.","en":"to make someone or something different from others","vi":"làm nổi bật; làm cho khác biệt"},{"pos":"v.","en":"to see or hear something clearly enough to recognize it","vi":"nhìn rõ; nghe rõ"}],"examples":[{"en":"I can distinguish the twins by their voices.","vi":"Tôi có thể phân biệt cặp sinh đôi qua giọng nói của họ.","audioKind":"ex"},{"en":"Students should learn to distinguish reliable evidence from personal opinion when evaluating information online.","vi":"Học sinh nên học cách phân biệt giữa bằng chứng đáng tin cậy và quan điểm cá nhân khi đánh giá thông tin trên mạng.","audioKind":"ex2"}],"collocations":[{"en":"distinguish between","vi":"phân biệt giữa"},{"en":"distinguish A from B","vi":"phân biệt A với B"},{"en":"distinguish yourself","vi":"làm cho bản thân nổi bật"}],"wordFamily":["distinction (n.)","distinctive (adj.)","distinguishable (adj.)","distinguished (adj.)"],"synonyms":["differentiate","tell apart"],"antonyms":["confuse"],"tipVi":"Thường dùng cấu trúc distinguish A from B hoặc between A and B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_philosopher', 'en-b2-38', 'philosopher', '/fɪˈlɑːsəfər/', 'B2', 'nhà triết học', 'n.', 'philosophy (n.), philosophical (adj.), philosophically (adv.), philosophise (v.)', NULL, 'philosopher chỉ con người, còn philosophy chỉ triết học hoặc hệ tư tưởng.', 'The philosopher asked us what makes a life meaningful.', NULL, 'Triết gia nọ đã đặt câu hỏi cho chúng tôi về điều làm cho cuộc sống trở nên có ý nghĩa.', '{"wordId":"philosopher","ukIpa":"/fɪˈlɒsəfə/","usIpa":"/fɪˈlɑːsəfər/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"Someone who studies fundamental questions about existence, knowledge, and values.","vi":"nhà triết học"}],"examples":[{"en":"The philosopher asked us what makes a life meaningful.","vi":"Triết gia nọ đã đặt câu hỏi cho chúng tôi về điều làm cho cuộc sống trở nên có ý nghĩa.","audioKind":"ex"},{"en":"A philosopher might question whether economic growth should be the main measure of a society''s progress.","vi":"Một nhà triết học có thể đặt câu hỏi liệu tăng trưởng kinh tế có nên là thước đo chính cho sự tiến bộ của xã hội hay không.","audioKind":"ex2"}],"collocations":[{"en":"moral philosopher","vi":"nhà triết học đạo đức"},{"en":"political philosopher","vi":"nhà triết học chính trị"},{"en":"ancient philosopher","vi":"triết gia cổ đại"}],"wordFamily":["philosophy (n.)","philosophical (adj.)","philosophically (adv.)","philosophise (v.)"],"synonyms":[],"antonyms":[],"tipVi":"philosopher chỉ con người, còn philosophy chỉ triết học hoặc hệ tư tưởng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_perspective', 'en-b2-38', 'perspective', '/pərˈspektɪv/', 'B2', 'góc nhìn; quan điểm; phép phối cảnh; khả năng đánh giá khách quan; sự cân nhắc đúng mực', 'n.', NULL, 'Đồng nghĩa: viewpoint, outlook', 'Khi nói từ một góc độ nào đó, dùng từ from a perspective, không dùng in.', 'Hearing her story gave me a completely different perspective.', NULL, 'Lắng nghe câu chuyện của cô ấy mang lại cho tôi một góc nhìn hoàn toàn khác.', '{"wordId":"perspective","ukIpa":"/pəˈspektɪv/","usIpa":"/pərˈspektɪv/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"A particular way of considering a situation or issue.","vi":"góc nhìn; quan điểm"},{"pos":"n.","en":"A drawing technique that makes objects appear realistically distant.","vi":"phép phối cảnh"},{"pos":"n.","en":"The ability to judge the relative importance of things.","vi":"khả năng đánh giá khách quan; sự cân nhắc đúng mực"}],"examples":[{"en":"Hearing her story gave me a completely different perspective.","vi":"Lắng nghe câu chuyện của cô ấy mang lại cho tôi một góc nhìn hoàn toàn khác.","audioKind":"ex"},{"en":"Examining urban development from residents'' perspective can help planners create more inclusive and accessible public spaces.","vi":"Việc xem xét sự phát triển đô thị từ góc độ của cư dân có thể giúp các nhà quy hoạch kiến tạo những không gian công cộng mang tính bao trùm và dễ tiếp cận hơn.","audioKind":"ex2"}],"collocations":[{"en":"from a different perspective","vi":"từ một góc nhìn khác"},{"en":"broaden your perspective","vi":"mở rộng tầm nhìn"},{"en":"put things into perspective","vi":"nhìn nhận vấn đề một cách khách quan"},{"en":"a sense of perspective","vi":"tinh thần nhận thức đúng mực"}],"wordFamily":[],"synonyms":["viewpoint","outlook"],"antonyms":[],"tipVi":"Khi nói từ một góc độ nào đó, dùng từ from a perspective, không dùng in.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_drawback', 'en-b2-38', 'drawback', '/ˈdrɔːbæk/', 'B2', 'nhược điểm; hạn chế; bất lợi', 'n.', NULL, 'Đồng nghĩa: disadvantage, downside · Trái nghĩa: advantage, benefit', 'Là danh từ đếm được, thường dùng cấu trúc "a drawback of" đi với danh từ hoặc danh động từ.', 'The flat''s only drawback is its tiny kitchen.', NULL, 'Nhược điểm duy nhất của căn hộ là phòng bếp quá nhỏ.', '{"wordId":"drawback","ukIpa":"/ˈdrɔːbæk/","usIpa":"/ˈdrɔːbæk/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"A disadvantage that makes something less useful or attractive","vi":"nhược điểm; hạn chế; bất lợi"}],"examples":[{"en":"The flat''s only drawback is its tiny kitchen.","vi":"Nhược điểm duy nhất của căn hộ là phòng bếp quá nhỏ.","audioKind":"ex"},{"en":"A major drawback of working remotely is the reduced opportunity for informal communication with colleagues.","vi":"Một hạn chế lớn của việc làm việc từ xa là cơ hội giao lưu không chính thức với đồng nghiệp bị giảm đi.","audioKind":"ex2"}],"collocations":[{"en":"a major drawback","vi":"một nhược điểm lớn"},{"en":"the main drawback","vi":"nhược điểm chính"},{"en":"a drawback of","vi":"hạn chế của"}],"wordFamily":[],"synonyms":["disadvantage","downside"],"antonyms":["advantage","benefit"],"tipVi":"Là danh từ đếm được, thường dùng cấu trúc \"a drawback of\" đi với danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_underestimate', 'en-b2-38', 'underestimate', '/ˌʌndərˈestɪmeɪt/', 'B2', 'đánh giá thấp; coi thường; sự ước tính thấp hơn thực tế', 'v.', 'underestimation (n.), estimate (v.), estimation (n.)', 'Đồng nghĩa: underrate · Trái nghĩa: overestimate', 'Động từ có phần đuôi phát âm là / meɪt /, danh từ có phần đuôi phát âm là / mət /.', 'We underestimated the traffic and arrived half an hour late.', NULL, 'Chúng tôi đã đánh giá thấp tình hình giao thông nên đã đến muộn nửa tiếng.', '{"wordId":"underestimate","ukIpa":"/ˌʌndərˈestɪmeɪt/","usIpa":"/ˌʌndərˈestɪmeɪt/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"To judge something as less important, capable, or large than reality","vi":"đánh giá thấp; coi thường"},{"pos":"n.","en":"An estimate that is lower than the actual amount","vi":"sự ước tính thấp hơn thực tế"}],"examples":[{"en":"We underestimated the traffic and arrived half an hour late.","vi":"Chúng tôi đã đánh giá thấp tình hình giao thông nên đã đến muộn nửa tiếng.","audioKind":"ex"},{"en":"Policymakers should not underestimate the long-term effects of poor housing on children''s health and educational achievement.","vi":"Các nhà hoạch định chính sách không nên đánh giá thấp những ảnh hưởng lâu dài của điều kiện nhà ở kém đối với sức khỏe và thành tích học tập của trẻ em.","audioKind":"ex2"}],"collocations":[{"en":"underestimate the cost","vi":"đánh giá thấp chi phí"},{"en":"underestimate the importance of","vi":"đánh giá thấp tầm quan trọng của"},{"en":"seriously underestimate","vi":"đánh giá thấp một cách nghiêm trọng"}],"wordFamily":["underestimation (n.)","estimate (v.)","estimation (n.)"],"synonyms":["underrate"],"antonyms":["overestimate"],"tipVi":"Động từ có phần đuôi phát âm là / meɪt /, danh từ có phần đuôi phát âm là / mət /.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_preferable', 'en-b2-38', 'preferable', '/ˈprefrəbl/', 'B2', 'tốt hơn; thích hợp hơn; đáng chọn hơn', 'adj.', 'prefer (v.), preference (n.), preferably (adv.)', 'Đồng nghĩa: better', 'Dùng cấu trúc "A is preferable to B", không dùng "than"; thường không đi kèm với "more".', 'A quiet evening at home is preferable to another party.', NULL, 'Một buổi tối yên tĩnh ở nhà vẫn tốt hơn là đi dự một bữa tiệc khác.', '{"wordId":"preferable","ukIpa":"/ˈprefrəbl/","usIpa":"/ˈprefrəbl/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Better or more suitable than another option.","vi":"tốt hơn; thích hợp hơn; đáng chọn hơn"}],"examples":[{"en":"A quiet evening at home is preferable to another party.","vi":"Một buổi tối yên tĩnh ở nhà vẫn tốt hơn là đi dự một bữa tiệc khác.","audioKind":"ex"},{"en":"Investing in reliable public transport is often preferable to building more roads in densely populated cities.","vi":"Đầu tư vào giao thông công cộng đáng tin cậy thường tốt hơn là xây thêm đường ở những thành phố đông dân cư.","audioKind":"ex2"}],"collocations":[{"en":"preferable to","vi":"tốt hơn so với"},{"en":"far preferable","vi":"tốt hơn nhiều"},{"en":"a preferable alternative","vi":"một lựa chọn thay thế tốt hơn"}],"wordFamily":["prefer (v.)","preference (n.)","preferably (adv.)"],"synonyms":["better"],"antonyms":[],"tipVi":"Dùng cấu trúc \"A is preferable to B\", không dùng \"than\"; thường không đi kèm với \"more\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_associate', 'en-b2-38', 'associate', '/əˈsoʊʃieɪt/', 'B2', 'liên tưởng; kết nối; đồng nghiệp; đối tác kinh doanh; phó; liên kết (chức vụ dưới cấp chính)', 'v.', 'association (n.), associated (adj.)', 'Đồng nghĩa: connect, link · Trái nghĩa: dissociate', 'Động từ phát âm âm cuối là /eɪt/; danh từ và tính từ phát âm âm cuối là /ət/.', 'I always associate the smell of cinnamon with home.', NULL, 'Tôi luôn liên tưởng mùi quế với gia đình.', '{"wordId":"associate","ukIpa":"/əˈsəʊsieɪt/","usIpa":"/əˈsoʊʃieɪt/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"to connect people or things in your mind","vi":"liên tưởng; kết nối"},{"pos":"n.","en":"someone connected with you through work or business","vi":"đồng nghiệp; đối tác kinh doanh"},{"pos":"adj.","en":"having a related position, often below the main or full rank","vi":"phó; liên kết (chức vụ dưới cấp chính)"}],"examples":[{"en":"I always associate the smell of cinnamon with home.","vi":"Tôi luôn liên tưởng mùi quế với gia đình.","audioKind":"ex"},{"en":"Many consumers associate higher prices with better quality, although research suggests this connection is not always reliable.","vi":"Nhiều người tiêu dùng gắn mức giá cao hơn với chất lượng tốt hơn, mặc dù các nghiên cứu cho thấy mối liên hệ này không phải lúc nào cũng đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"associate A with B","vi":"liên tưởng A với B"},{"en":"be associated with","vi":"có liên quan đến"},{"en":"business associate","vi":"đối tác kinh doanh"},{"en":"associate professor","vi":"phó giáo sư"}],"wordFamily":["association (n.)","associated (adj.)"],"synonyms":["connect","link"],"antonyms":["dissociate"],"tipVi":"Động từ phát âm âm cuối là /eɪt/; danh từ và tính từ phát âm âm cuối là /ət/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 28, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_38_1', 'en-b2-38', 'Cách dùng “core” (n.) — phần cốt lõi, trung tâm, quan trọng nhất; lõi (trái cây)', 'at the core of  ·  core skills  ·  apple core', 'Phần lõi cứng của quả táo, lê,... gọi là "core"; trong khi hột cứng của quả đào, mận,... thường gọi là "stone".', 'Đồng nghĩa: centre', '[{"hanzi":"She ate the apple and threw away the core.","pinyin":"","meaning":"Cô ấy ăn xong quả táo và vứt phần lõi đi."},{"hanzi":"Critical thinking should be a core skill taught in schools because it helps students evaluate information independently.","pinyin":"","meaning":"Tư duy phản biện nên là một kỹ năng cốt lõi được giảng dạy trong nhà trường vì nó giúp học sinh đánh giá thông tin một cách độc lập."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_38_2', 'en-b2-38', 'Cách dùng “consequently” (adv.) — do đó; vì vậy; kết quả là', 'and consequently  ·  consequently lead to  ·  consequently require', 'Là trạng từ chứ không phải liên hội từ; khi nối hai mệnh đề độc lập có thể dùng dấu chấm phẩy ở phía trước.', 'Họ từ (Word Family): consequence (n.), consequent (adj.), consequential (adj.) | Đồng nghĩa: therefore, thus, hence', '[{"hanzi":"The bakery was closed; consequently, we went home without bread.","pinyin":"","meaning":"Tiệm bánh đã đóng cửa; do đó, chúng tôi ra về mà không mua được bánh mì."},{"hanzi":"Housing costs have risen sharply; consequently, many young adults are delaying their decision to live independently.","pinyin":"","meaning":"Chi phí nhà ở đã tăng vọt; do đó, nhiều người trẻ tuổi đang hoãn việc quyết định sống tự lập."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_38_3', 'en-b2-38', 'Cách dùng “grasp” (v.) — hiểu; nắm bắt; lĩnh hội', 'grasp a concept  ·  a firm grasp of  ·  grasp an opportunity', 'Khi diễn tả sự thấu hiểu, từ này có thể dùng làm động từ; dạng danh từ thường đi với cụm a grasp of.', 'Đồng nghĩa: understand, comprehend, grip', '[{"hanzi":"I finally grasped the rules after watching one round.","pinyin":"","meaning":"Cuối cùng tôi cũng hiểu được luật chơi sau khi theo dõi xong một hiệp."},{"hanzi":"Students grasp complex scientific concepts more easily when teachers connect them to familiar everyday experiences.","pinyin":"","meaning":"Học sinh dễ dàng tiếp thu các khái niệm khoa học phức tạp hơn khi giáo viên kết nối chúng với những trải nghiệm quen thuộc hàng ngày."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_38_4', 'en-b2-38', 'Cách dùng “marked” (adj.) — rõ rệt; đáng kể; rõ ràng', 'a marked increase  ·  a marked improvement  ·  a marked contrast', 'Thường dùng trong văn phong học thuật để diễn tả ý nghĩa "rõ rệt, đáng kể"; phát âm đuôi là /t/.', 'Họ từ (Word Family): mark (v.), mark (n.), markedly (adv.), unmarked (adj.) | Đồng nghĩa: noticeable, pronounced, distinct · Trái nghĩa: unmarked', '[{"hanzi":"There is a marked difference between these two cakes.","pinyin":"","meaning":"Có sự khác biệt rõ rệt giữa hai chiếc bánh này."},{"hanzi":"The introduction of dedicated cycle lanes led to a marked increase in bicycle use among urban commuters.","pinyin":"","meaning":"Việc đưa vào sử dụng các làn đường dành riêng cho xe đạp đã dẫn đến sự gia tăng đáng kể trong việc sử dụng xe đạp của những người đi làm ở đô thị."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_38_1', 'en-b2-38', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_38_1_1', 'ten_b2_38_1', 'relate', 'I can relate to your fear of flying.', 'I can relate to your fear of flying.', '/rɪˈleɪt/', 'Tôi hoàn toàn có thể thấu cảm với nỗi sợ đi máy bay của bạn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_38_1_2', 'ten_b2_38_1', 'seemingly', 'The seemingly empty box had a kitten inside.', 'The seemingly empty box had a kitten inside.', '/ˈsiːmɪŋli/', 'Cái hộp thoạt nhìn có vẻ trống rỗng nhưng bên trong lại có một chú mèo con.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_38_1_3', 'ten_b2_38_1', 'imaginative', 'My imaginative niece turned empty boxes into a spaceship.', 'My imaginative niece turned empty boxes into a spaceship.', '/ɪˈmædʒɪnətɪv/', 'Cô cháu gái giàu trí tưởng tượng của tôi đã biến những chiếc hộp rỗng thành một con tàu vũ trụ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_38_1_4', 'ten_b2_38_1', 'characteristic', 'One striking characteristic of this cat is its curly fur.', 'One striking characteristic of this cat is its curly fur.', '/ˌkærəktəˈrɪstɪk/', 'Một đặc điểm nổi bật của con mèo này là bộ lông xoăn của nó.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_38_1_5', 'ten_b2_38_1', 'relatively', 'The kitchen is relatively small, but it feels bright.', 'The kitchen is relatively small, but it feels bright.', '/ˈrelətɪvli/', 'Phòng bếp khá nhỏ, nhưng mang lại cảm giác sáng sủa.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_38_1_6', 'ten_b2_38_1', 'merely', 'I wasn''t complaining; I was merely asking a question.', 'I wasn''t complaining; I was merely asking a question.', '/ˈmɪrli/', 'Tôi không hề phàn nàn; tôi chỉ đang đặt một câu hỏi mà thôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_38_1_7', 'ten_b2_38_1', 'imply', 'Are you trying to imply that my cooking is bad?', 'Are you trying to imply that my cooking is bad?', '/ɪmˈplaɪ/', 'Bạn đang cố ám chỉ rằng tôi nấu ăn dở phải không?', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_38_1_8', 'ten_b2_38_1', 'marked', 'There is a marked difference between these two cakes.', 'There is a marked difference between these two cakes.', '/mɑːrkt/', 'Có sự khác biệt rõ rệt giữa hai chiếc bánh này.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_38_1_1', 'en-b2-38', 'ten_b2_38_1', 'listening', 'listening', 'I can relate to your fear of flying.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi hoàn toàn có thể thấu cảm với nỗi sợ đi máy bay của bạn.","Tôi thấy băn khoăn về việc mua một chiếc xe đạp cũ trên mạng.","Cô ấy ăn xong quả táo và vứt phần lõi đi.","Chiếc túi rẻ hơn có cảm giác kém hơn so với chiếc túi da."]'::jsonb, 0, 'I can relate to your fear of flying. → Tôi hoàn toàn có thể thấu cảm với nỗi sợ đi máy bay của bạn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_38_1_2', 'en-b2-38', 'ten_b2_38_1', 'listening', 'listening', 'The seemingly empty box had a kitten inside.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Phòng bếp khá nhỏ, nhưng mang lại cảm giác sáng sủa.","Tôi không hề phàn nàn; tôi chỉ đang đặt một câu hỏi mà thôi.","Cuối cùng tôi cũng hiểu được luật chơi sau khi theo dõi xong một hiệp.","Cái hộp thoạt nhìn có vẻ trống rỗng nhưng bên trong lại có một chú mèo con."]'::jsonb, 3, 'The seemingly empty box had a kitten inside. → Cái hộp thoạt nhìn có vẻ trống rỗng nhưng bên trong lại có một chú mèo con.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_38_1_3', 'en-b2-38', 'ten_b2_38_1', 'listening', 'listening', 'My imaginative niece turned empty boxes into a spaceship.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô cháu gái giàu trí tưởng tượng của tôi đã biến những chiếc hộp rỗng thành một con tàu vũ trụ.","Tiệm bánh đã đóng cửa; do đó, chúng tôi ra về mà không mua được bánh mì.","Lương tâm bảo tôi phải trả lại chiếc ví bị mất.","Chiếc túi rẻ hơn có cảm giác kém hơn so với chiếc túi da."]'::jsonb, 0, 'My imaginative niece turned empty boxes into a spaceship. → Cô cháu gái giàu trí tưởng tượng của tôi đã biến những chiếc hộp rỗng thành một con tàu vũ trụ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_38_2', 'en-b2-38', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_38_2_1', 'ten_b2_38_2', 'relate', 'Researchers should relate their findings to existing evidence before drawing conclusions about the causes of unemployment.', 'Researchers should relate their findings to existing evidence before drawing conclusions about the causes of unemployment.', '/rɪˈleɪt/', 'Các nhà nghiên cứu nên liên kết kết quả phát hiện của họ với các bằng chứng hiện có trước khi đưa ra kết luận về nguyên nhân dẫn đến tình trạng thất nghiệp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_38_2_2', 'ten_b2_38_2', 'seemingly', 'Seemingly minor changes in daily travel habits can significantly reduce a city''s overall carbon emissions.', 'Seemingly minor changes in daily travel habits can significantly reduce a city''s overall carbon emissions.', '/ˈsiːmɪŋli/', 'Những thay đổi có vẻ nhỏ nhặt trong thói quen đi lại hằng ngày có thể làm giảm đáng kể lượng khí thải carbon tổng thể của một thành phố.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_38_2_3', 'ten_b2_38_2', 'imaginative', 'Schools should encourage imaginative thinking rather than require students to memorise every detail of a textbook.', 'Schools should encourage imaginative thinking rather than require students to memorise every detail of a textbook.', '/ɪˈmædʒɪnətɪv/', 'Nhà trường nên khuyến khích tư duy sáng tạo thay vì bắt học sinh ghi nhớ từng chi tiết trong sách giáo khoa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_38_2_4', 'ten_b2_38_2', 'characteristic', 'The ability to adapt quickly is an important characteristic of successful businesses in a changing economy.', 'The ability to adapt quickly is an important characteristic of successful businesses in a changing economy.', '/ˌkærəktəˈrɪstɪk/', 'Khả năng thích ứng nhanh là một đặc điểm quan trọng của các doanh nghiệp thành công trong nền kinh tế đang thay đổi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_38_2_5', 'ten_b2_38_2', 'relatively', 'Cycling is a relatively inexpensive form of transport that can reduce congestion in crowded cities.', 'Cycling is a relatively inexpensive form of transport that can reduce congestion in crowded cities.', '/ˈrelətɪvli/', 'Đi xe đạp là một hình thức di chuyển tương đối rẻ tiền, có thể giúp giảm tình trạng ùn tắc ở các thành phố đông đúc.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_38_2_6', 'ten_b2_38_2', 'merely', 'Building more roads merely shifts traffic problems elsewhere unless governments also invest in reliable public transport.', 'Building more roads merely shifts traffic problems elsewhere unless governments also invest in reliable public transport.', '/ˈmɪrli/', 'Việc xây dựng thêm đường xá đơn thuần chỉ đẩy vấn đề giao thông sang nơi khác trừ khi chính phủ cũng đầu tư vào hệ thống giao thông công cộng đáng tin cậy.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_38_2_1', 'en-b2-38', 'ten_b2_38_2', 'listening', 'listening', 'Researchers should relate their findings to existing evidence before drawing conclusions about the causes of unemployment.', NULL, 'Trong câu vừa nghe, từ “relate” mang nghĩa nào sau đây?', '["sự phản đối; lời phản đối; ý kiến phản đối","liên quan; gắn kết","phương tiện truyền thông; báo chí","phong phú; dồi dào"]'::jsonb, 1, '“relate” (/rɪˈleɪt/): liên quan; gắn kết. Câu đầy đủ: Researchers should relate their findings to existing evidence before drawing conclusions about the causes of unemployment.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_38_2_2', 'en-b2-38', 'ten_b2_38_2', 'listening', 'listening', 'Seemingly minor changes in daily travel habits can significantly reduce a city''s overall carbon emissions.', NULL, 'Trong câu vừa nghe, từ “seemingly” mang nghĩa nào sau đây?', '["độ sáng; sự rực rỡ","có vẻ như; thoạt nhìn thì","độ ẩm không khí","hoạt động gây quỹ; quyên góp"]'::jsonb, 1, '“seemingly” (/ˈsiːmɪŋli/): có vẻ như; thoạt nhìn thì. Câu đầy đủ: Seemingly minor changes in daily travel habits can significantly reduce a city''s overall carbon emissions.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
