INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_38_2', 'en-b2-38', 'The seemingly empty box had a kitten inside', 'Cái hộp thoạt nhìn có vẻ trống rỗng nhưng bên trong lại có một chú mèo con.', 'seemingly /ˈsiːmɪŋli/', '["empty","inside","kitten","a","seemingly","had","box","The"]'::jsonb, NULL, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
