INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_38_4', 'en-b2-38', 'One striking characteristic of this cat is its curly fur', 'Một đặc điểm nổi bật của con mèo này là bộ lông xoăn của nó.', 'characteristic /ˌkærəktəˈrɪstɪk/', '["curly","One","its","cat","striking","is","this","of","fur","characteristic"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_38_5', 'en-b2-38', 'The kitchen is relatively small, but it feels bright', 'Phòng bếp khá nhỏ, nhưng mang lại cảm giác sáng sủa.', 'relatively /ˈrelətɪvli/', '["is","but","kitchen","it","The","bright","relatively","feels","small"]'::jsonb, NULL, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_38_6', 'en-b2-38', 'I wasn''t complaining; I was merely asking a question', 'Tôi không hề phàn nàn; tôi chỉ đang đặt một câu hỏi mà thôi.', 'merely /ˈmɪrli/', '["asking","I","question","complaining","was","I","wasn''t","a","merely"]'::jsonb, NULL, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
