INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_38_1', 'en-b2-38', NULL, 'comprehensive_test', 'listening', 'relate', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["biểu lộ sự tôn trọng; lễ phép; kính cẩn","lạc quan; mang tính hy vọng","hãng; đại lý; doanh nghiệp sắp xếp các dịch vụ cho cá nhân hoặc doanh nghiệp khác","liên quan; gắn kết"]'::jsonb, 3, 'relate (/rɪˈleɪt/) → liên quan; gắn kết; thấu cảm; đồng cảm; kể lại; thuật lại', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_38_2', 'en-b2-38', NULL, 'comprehensive_test', 'listening', 'The seemingly empty box had a kitten inside.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một đặc điểm nổi bật của con mèo này là bộ lông xoăn của nó.","Cái hộp thoạt nhìn có vẻ trống rỗng nhưng bên trong lại có một chú mèo con.","Cô cháu gái giàu trí tưởng tượng của tôi đã biến những chiếc hộp rỗng thành một con tàu vũ trụ.","Hãy sắp xếp những bức tranh này theo đúng trình tự trước bữa tối."]'::jsonb, 1, 'The seemingly empty box had a kitten inside. → Cái hộp thoạt nhìn có vẻ trống rỗng nhưng bên trong lại có một chú mèo con.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_38_3', 'en-b2-38', NULL, 'comprehensive_test', 'listening', 'imaginative', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["giàu trí tưởng tượng; sáng tạo","bố cục; cách bài trí; thiết kế trang","nhúng; chấm","đáng kể; nhiều"]'::jsonb, 0, 'imaginative (/ɪˈmædʒɪnətɪv/) → giàu trí tưởng tượng; sáng tạo', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_38_4', 'en-b2-38', NULL, 'comprehensive_test', 'listening', 'One striking characteristic of this cat is its curly fur.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một đặc điểm nổi bật của con mèo này là bộ lông xoăn của nó.","Cô ấy ăn xong quả táo và vứt phần lõi đi.","Chiếc túi rẻ hơn có cảm giác kém hơn so với chiếc túi da.","Tôi không hề phàn nàn; tôi chỉ đang đặt một câu hỏi mà thôi."]'::jsonb, 0, 'One striking characteristic of this cat is its curly fur. → Một đặc điểm nổi bật của con mèo này là bộ lông xoăn của nó.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_38_5', 'en-b2-38', NULL, 'comprehensive_test', 'listening', 'relatively', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tương đối; khá là","tang lễ; đám tang","sự khôn ngoan; trí tuệ; sự sáng suốt","làm việc tự do; thuộc nghề tự do"]'::jsonb, 0, 'relatively (/ˈrelətɪvli/) → tương đối; khá là', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_38_6', 'en-b2-38', NULL, 'comprehensive_test', 'listening', 'I wasn''t complaining; I was merely asking a question.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi không hề phàn nàn; tôi chỉ đang đặt một câu hỏi mà thôi.","Tôi thấy băn khoăn về việc mua một chiếc xe đạp cũ trên mạng.","Tôi nhận thấy có một khoản phí khả nghi trong sao kê ngân hàng của mình.","Hãy đặt mỗi chiếc nắp màu lên chiếc hộp tương ứng của nó."]'::jsonb, 0, 'I wasn''t complaining; I was merely asking a question. → Tôi không hề phàn nàn; tôi chỉ đang đặt một câu hỏi mà thôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_38_7', 'en-b2-38', NULL, 'comprehensive_test', 'listening', 'imply', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["ám chỉ; ngụ ý","làm dịu; giảm bớt; làm giảm","sự tiến hóa","thuộc về biển; sinh vật biển"]'::jsonb, 0, 'imply (/ɪmˈplaɪ/) → ám chỉ; ngụ ý; bao hàm; ngầm hiểu', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_38_8', 'en-b2-38', NULL, 'comprehensive_test', 'listening', 'There is a marked difference between these two cakes.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nhược điểm duy nhất của căn hộ là phòng bếp quá nhỏ.","Có sự khác biệt rõ rệt giữa hai chiếc bánh này.","Cô ấy ăn xong quả táo và vứt phần lõi đi.","Lắng nghe câu chuyện của cô ấy mang lại cho tôi một góc nhìn hoàn toàn khác."]'::jsonb, 1, 'There is a marked difference between these two cakes. → Có sự khác biệt rõ rệt giữa hai chiếc bánh này.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_38_9', 'en-b2-38', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To a certain degree compared with something else.”?', '["underestimate","conscience","relatively","perspective"]'::jsonb, 2, 'relatively (/ˈrelətɪvli/) → tương đối; khá là', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_38_10', 'en-b2-38', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “only, and nothing more or more important”?', '["merely","underestimate","associate","sequence"]'::jsonb, 0, 'merely (/ˈmɪrli/) → chỉ là; đơn thuần là', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_38_11', 'en-b2-38', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To suggest something without stating it directly.”?', '["drawback","distinguish","essentially","imply"]'::jsonb, 3, 'imply (/ɪmˈplaɪ/) → ám chỉ; ngụ ý', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_38_12', 'en-b2-38', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Clearly noticeable and often substantial”?', '["merely","conscience","sequence","marked"]'::jsonb, 3, 'marked (/mɑːrkt/) → rõ rệt; đáng kể; rõ ràng', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_38_13', 'en-b2-38', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Close to the actual amount or value, but not exact”?', '["grasp","doubtful","approximate","preferable"]'::jsonb, 2, 'approximate (/əˈprɑːksɪmət/) → xấp xỉ; khoảng', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
