INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_38_18', 'en-b2-38', NULL, 'comprehensive_test', 'reading', NULL, 'Researchers should relate their findings to existing evidence before drawing conclusions about the causes of unemployment.', 'Dựa vào câu trên, từ “relate” có nghĩa phù hợp nhất là gì?', '["hiệu suất, hiệu quả làm việc","liên quan; gắn kết","Địa Trung Hải","có tay nghề; lành nghề"]'::jsonb, 1, 'relate: liên quan; gắn kết; thấu cảm; đồng cảm; kể lại; thuật lại. Dịch cả câu: Các nhà nghiên cứu nên liên kết kết quả phát hiện của họ với các bằng chứng hiện có trước khi đưa ra kết luận về nguyên nhân dẫn đến tình trạng thất nghiệp.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_38_19', 'en-b2-38', NULL, 'comprehensive_test', 'reading', NULL, 'Seemingly minor changes in daily travel habits can significantly reduce a city''s overall carbon emissions.', 'Dựa vào câu trên, từ “seemingly” có nghĩa phù hợp nhất là gì?', '["thỏa đáng; đạt yêu cầu; đủ tiêu chuẩn","mất cảm giác; tê (một phần cơ thể)","có vẻ như; thoạt nhìn thì","ứng cử viên; người xin việc"]'::jsonb, 2, 'seemingly: có vẻ như; thoạt nhìn thì. Dịch cả câu: Những thay đổi có vẻ nhỏ nhặt trong thói quen đi lại hằng ngày có thể làm giảm đáng kể lượng khí thải carbon tổng thể của một thành phố.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_38_20', 'en-b2-38', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should encourage imaginative thinking rather than require students to memorise every detail of a textbook.', 'Dựa vào câu trên, từ “imaginative” có nghĩa phù hợp nhất là gì?', '["buổi tổng duyệt; buổi diễn tập","thỉnh thoảng; đôi khi; không thường xuyên","giàu trí tưởng tượng; sáng tạo","chủ tịch; chủ tịch hội đồng quản trị; người điều hành cuộc họp"]'::jsonb, 2, 'imaginative: giàu trí tưởng tượng; sáng tạo. Dịch cả câu: Nhà trường nên khuyến khích tư duy sáng tạo thay vì bắt học sinh ghi nhớ từng chi tiết trong sách giáo khoa.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_38_21', 'en-b2-38', NULL, 'comprehensive_test', 'reading', NULL, 'The ability to adapt quickly is an important characteristic of successful businesses in a changing economy.', 'Dựa vào câu trên, từ “characteristic” có nghĩa phù hợp nhất là gì?', '["đặc điểm; nét tiêu biểu của một người hoặc một vật","sự ngóng trông; niềm hy vọng; sự chờ đợi","phát hiện; khám phá; vạch trần","sự hoài nghi; sự nghi ngờ; tình nghi"]'::jsonb, 0, 'characteristic: đặc điểm; nét tiêu biểu của một người hoặc một vật; điển hình; đặc trưng của một người, sự vật hoặc nhóm cụ thể. Dịch cả câu: Khả năng thích ứng nhanh là một đặc điểm quan trọng của các doanh nghiệp thành công trong nền kinh tế đang thay đổi.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_38_22', 'en-b2-38', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đánh giá thấp; coi thường”', '["moral","fleet","underestimate","novelty"]'::jsonb, 2, 'đánh giá thấp; coi thường → underestimate (/ˌʌndərˈestɪmeɪt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_38_23', 'en-b2-38', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tốt hơn; thích hợp hơn; đáng chọn hơn”', '["trek","spontaneous","impact","preferable"]'::jsonb, 3, 'tốt hơn; thích hợp hơn; đáng chọn hơn → preferable (/ˈprefrəbl/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_38_24', 'en-b2-38', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “liên tưởng; kết nối”', '["independently","acrobat","associate","creation"]'::jsonb, 2, 'liên tưởng; kết nối → associate (/əˈsoʊʃieɪt/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-39', 'en', 'Bài 39: Tư duy & Nhận thức (6) - CEFR B2', 'CEFR B2', 'B2 · Tư duy', '28 từ vựng Tiếng Anh CEFR B2 chủ đề tư duy & nhận thức kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4039, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_limitation', 'en-b2-39', 'limitation', '/ˌlɪmɪˈteɪʃən/', 'B2', 'hạn chế; thiếu sót; sự giới hạn; mức giới hạn', 'n.', 'limit (n.), limit (v.), limited (adj.), limitless (adj.)', 'Đồng nghĩa: restriction, constraint', 'Khi mang nghĩa "những hạn chế/thiếu sót" thường dùng ở dạng số nhiều; giới hạn đối với cái gì dùng "limitation on".', 'The main limitation of this camera is its battery life.', NULL, 'Hạn chế chính của chiếc máy ảnh này là thời lượng pin.', '{"wordId":"limitation","ukIpa":"/ˌlɪmɪˈteɪʃən/","usIpa":"/ˌlɪmɪˈteɪʃən/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"a weakness that prevents someone or something from being fully effective","vi":"hạn chế; thiếu sót"},{"pos":"n.","en":"a rule or condition that controls how much is allowed","vi":"sự giới hạn; mức giới hạn"}],"examples":[{"en":"The main limitation of this camera is its battery life.","vi":"Hạn chế chính của chiếc máy ảnh này là thời lượng pin.","audioKind":"ex"},{"en":"Researchers should acknowledge the limitations of small samples before drawing conclusions about the wider population.","vi":"Các nhà nghiên cứu nên thừa nhận những hạn chế của các mẫu khảo sát nhỏ trước khi đưa ra kết luận về cộng đồng rộng lớn hơn.","audioKind":"ex2"}],"collocations":[{"en":"limitations of a study","vi":"những hạn chế của một nghiên cứu"},{"en":"place limitations on","vi":"đặt ra giới hạn đối với"},{"en":"budget limitations","vi":"hạn chế về ngân sách"},{"en":"recognise your limitations","vi":"nhận thức được giới hạn của bản thân"}],"wordFamily":["limit (n.)","limit (v.)","limited (adj.)","limitless (adj.)"],"synonyms":["restriction","constraint"],"antonyms":[],"tipVi":"Khi mang nghĩa \"những hạn chế/thiếu sót\" thường dùng ở dạng số nhiều; giới hạn đối với cái gì dùng \"limitation on\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hence', 'en-b2-39', 'hence', '/hens/', 'B2', 'do đó; vì vậy; kể từ nay; sau này', 'adv.', NULL, 'Đồng nghĩa: therefore, thus', 'Từ trang trọng; khi mang nghĩa "do đó", phía sau có thể đi trực tiếp với một cụm danh từ.', 'The oven broke, hence our cold dinner tonight.', NULL, 'Lò nướng bị hỏng, vì vậy tối nay chúng ta ăn đồ nguội.', '{"wordId":"hence","ukIpa":"/hens/","usIpa":"/hens/","cefr":"B2","topic":"thinking","senses":[{"pos":"adv.","en":"For this reason; as a result","vi":"do đó; vì vậy"},{"pos":"adv.","en":"After a stated period measured from now","vi":"kể từ nay; sau này"}],"examples":[{"en":"The oven broke, hence our cold dinner tonight.","vi":"Lò nướng bị hỏng, vì vậy tối nay chúng ta ăn đồ nguội.","audioKind":"ex"},{"en":"Urban populations are growing rapidly; hence, governments need to invest more in reliable public transport.","vi":"Dân số đô thị đang tăng nhanh; do đó, chính phủ cần đầu tư nhiều hơn vào hệ thống giao thông công cộng đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"hence the need for","vi":"do đó cần phải"},{"en":"hence the importance of","vi":"do đó thấy được tầm quan trọng của"},{"en":"years hence","vi":"nhiều năm sau"}],"wordFamily":[],"synonyms":["therefore","thus"],"antonyms":[],"tipVi":"Từ trang trọng; khi mang nghĩa \"do đó\", phía sau có thể đi trực tiếp với một cụm danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_regard', 'en-b2-39', 'regard', '/rɪˈɡɑːrd/', 'B2', 'xem là; coi như; sự tôn trọng; sự quan tâm; lời hỏi thăm; lời chúc', 'v.', 'regarding (prep.), regardless (adv.)', NULL, 'Cụm từ "xem A là B" sử dụng regard A as B, không dùng to be.', 'I regard this little café as my second home.', NULL, 'Tôi xem quán cà phê nhỏ này như ngôi nhà thứ hai của mình.', '{"wordId":"regard","ukIpa":"/rɪˈɡɑːd/","usIpa":"/rɪˈɡɑːrd/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"To think of someone or something in a particular way.","vi":"xem là; coi như"},{"pos":"n.","en":"Respect for someone or attention to something.","vi":"sự tôn trọng; sự quan tâm"},{"pos":"n.","en":"Friendly greetings sent to someone, expressed in the plural.","vi":"lời hỏi thăm; lời chúc"}],"examples":[{"en":"I regard this little café as my second home.","vi":"Tôi xem quán cà phê nhỏ này như ngôi nhà thứ hai của mình.","audioKind":"ex"},{"en":"Policymakers increasingly regard access to reliable internet services as essential for equal participation in modern education.","vi":"Các nhà hoạch định chính sách ngày càng coi việc tiếp cận dịch vụ Internet đáng tin cậy là yếu tố thiết yếu để tham gia bình đẳng vào giáo dục hiện đại.","audioKind":"ex2"}],"collocations":[{"en":"regard as","vi":"coi như là"},{"en":"high regard for","vi":"sự tôn trọng cao đối với"},{"en":"with regard to","vi":"về việc; liên quan đến"},{"en":"send my regards","vi":"gửi lời hỏi thăm"}],"wordFamily":["regarding (prep.)","regardless (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ \"xem A là B\" sử dụng regard A as B, không dùng to be.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_likelihood', 'en-b2-39', 'likelihood', '/ˈlaɪklihʊd/', 'B2', 'khả năng xảy ra', 'n.', 'likely (adj.), unlikely (adj.)', 'Đồng nghĩa: probability, chance', 'Thường dùng cấu trúc likelihood of doing hoặc mệnh đề likelihood that.', 'Dark clouds increased the likelihood of rain this afternoon.', NULL, 'Những đám mây đen làm tăng khả năng trời sẽ mưa vào chiều nay.', '{"wordId":"likelihood","ukIpa":"/ˈlaɪklihʊd/","usIpa":"/ˈlaɪklihʊd/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"the chance that something will happen","vi":"khả năng xảy ra"}],"examples":[{"en":"Dark clouds increased the likelihood of rain this afternoon.","vi":"Những đám mây đen làm tăng khả năng trời sẽ mưa vào chiều nay.","audioKind":"ex"},{"en":"Regular physical activity can reduce the likelihood of developing certain health conditions later in life.","vi":"Hoạt động thể chất thường xuyên có thể làm giảm nguy cơ mắc một số bệnh tật về sau trong cuộc đời.","audioKind":"ex2"}],"collocations":[{"en":"the likelihood of","vi":"khả năng xảy ra..."},{"en":"increase the likelihood","vi":"làm tăng khả năng"},{"en":"reduce the likelihood","vi":"làm giảm khả năng"},{"en":"in all likelihood","vi":"mười mươi; mười phần chắc chắn"}],"wordFamily":["likely (adj.)","unlikely (adj.)"],"synonyms":["probability","chance"],"antonyms":[],"tipVi":"Thường dùng cấu trúc likelihood of doing hoặc mệnh đề likelihood that.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flaw', 'en-b2-39', 'flaw', '/flɔː/', 'B2', 'lỗi; khiếm khuyết; tì vết; làm hỏng; làm kém hoàn hảo', 'n.', 'flawed (adj.), flawless (adj.), flawlessly (adv.)', 'Đồng nghĩa: defect, fault, imperfection', 'Danh từ đếm được; lỗi của vật gì đó thường dùng a flaw in sth.', 'I noticed a tiny flaw in the glass bowl.', NULL, 'Tôi nhận thấy có một tì vết nhỏ trên chiếc bát thủy tinh.', '{"wordId":"flaw","ukIpa":"/flɔː/","usIpa":"/flɔː/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"a fault that makes something imperfect or less effective","vi":"lỗi; khiếm khuyết; tì vết"},{"pos":"v.","en":"to damage something or make it imperfect","vi":"làm hỏng; làm kém hoàn hảo"}],"examples":[{"en":"I noticed a tiny flaw in the glass bowl.","vi":"Tôi nhận thấy có một tì vết nhỏ trên chiếc bát thủy tinh.","audioKind":"ex"},{"en":"A major flaw in the research design makes its conclusions about student performance less reliable.","vi":"Một thiếu sót lớn trong thiết kế nghiên cứu khiến cho các kết luận về hiệuSức học tập của học sinh trở nên kém tin cậy hơn.","audioKind":"ex2"}],"collocations":[{"en":"a fundamental flaw","vi":"lỗi cơ bản"},{"en":"a design flaw","vi":"lỗi thiết kế"},{"en":"a fatal flaw","vi":"lỗi chí mạng"},{"en":"a flaw in the argument","vi":"lỗ hổng trong lập luận"}],"wordFamily":["flawed (adj.)","flawless (adj.)","flawlessly (adv.)"],"synonyms":["defect","fault","imperfection"],"antonyms":[],"tipVi":"Danh từ đếm được; lỗi của vật gì đó thường dùng a flaw in sth.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_closely', 'en-b2-39', 'closely', '/ˈkloʊsli/', 'B2', 'kỹ lưỡng; tỉ mỉ; chặt chẽ; mật thiết; sát nhau; gần gũi', 'adv.', 'close (adj.), closeness (n.)', NULL, 'look closely có nghĩa là nhìn kỹ, quan sát kỹ; stand close có nghĩa là đứng gần.', 'Look closely at this leaf and notice its tiny veins.', NULL, 'Hãy quan sát kỹ chiếc lá này và chú ý đến những đường gân nhỏ của nó.', '{"wordId":"closely","ukIpa":"/ˈkləʊsli/","usIpa":"/ˈkloʊsli/","cefr":"B2","topic":"thinking","senses":[{"pos":"adv.","en":"with careful attention to details or changes","vi":"kỹ lưỡng; tỉ mỉ; chặt chẽ"},{"pos":"adv.","en":"with a strong connection or much cooperation","vi":"chặt chẽ; mật thiết"},{"pos":"adv.","en":"with little space between people or things","vi":"sát nhau; gần gũi"}],"examples":[{"en":"Look closely at this leaf and notice its tiny veins.","vi":"Hãy quan sát kỹ chiếc lá này và chú ý đến những đường gân nhỏ của nó.","audioKind":"ex"},{"en":"Governments should closely monitor air quality near schools to protect children from the harmful effects of pollution.","vi":"Chính phủ nên giám sát chặt chẽ chất lượng không khí gần các trường học để bảo vệ trẻ em khỏi tác hại của ô nhiễm.","audioKind":"ex2"}],"collocations":[{"en":"closely monitor","vi":"giám sát chặt chẽ"},{"en":"closely related","vi":"có liên quan mật thiết"},{"en":"work closely with","vi":"làm việc chặt chẽ với"},{"en":"look closely","vi":"nhìn kỹ"}],"wordFamily":["close (adj.)","closeness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"look closely có nghĩa là nhìn kỹ, quan sát kỹ; stand close có nghĩa là đứng gần.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_criteria', 'en-b2-39', 'criteria', '/kraɪˈtɪriə/', 'B2', 'tiêu chuẩn; tiêu chí', 'n.', 'criterion (n.)', 'Đồng nghĩa: standards', 'criteria là dạng số nhiều, số ít là criterion; dùng cấu trúc criteria are.', 'This flat meets all our criteria for a home.', NULL, 'Căn hộ này đáp ứng tất cả các tiêu chí của chúng tôi về một ngôi nhà.', '{"wordId":"criteria","ukIpa":"/kraɪˈtɪəriə/","usIpa":"/kraɪˈtɪriə/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"Standards used to judge something or make a decision.","vi":"tiêu chuẩn; tiêu chí"}],"examples":[{"en":"This flat meets all our criteria for a home.","vi":"Căn hộ này đáp ứng tất cả các tiêu chí của chúng tôi về một ngôi nhà.","audioKind":"ex"},{"en":"Scholarships should be awarded according to clear criteria that consider both academic achievement and financial need.","vi":"Học bổng nên được trao theo các tiêu chí rõ ràng, xem xét cả thành tích học tập lẫn nhu cầu tài chính.","audioKind":"ex2"}],"collocations":[{"en":"meet the criteria","vi":"đáp ứng tiêu chuẩn"},{"en":"selection criteria","vi":"tiêu chí tuyển chọn"},{"en":"assessment criteria","vi":"tiêu chí đánh giá"}],"wordFamily":["criterion (n.)"],"synonyms":["standards"],"antonyms":[],"tipVi":"criteria là dạng số nhiều, số ít là criterion; dùng cấu trúc criteria are.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_presumably', 'en-b2-39', 'presumably', '/prɪˈzuːməbli/', 'B2', 'có lẽ; có thể là; theo như dự đoán', 'adv.', 'presume (v.), presumption (n.)', 'Đồng nghĩa: probably, likely', 'Thể hiện sự phỏng đoán dựa trên cơ sở thực tế, không mang ý nghĩa chắc chắn tuyệt đối như certainly.', 'Her coat is gone, so presumably she has left.', NULL, 'Áo khoác của cô ấy không còn ở đây, có lẽ cô ấy đã đi rồi.', '{"wordId":"presumably","ukIpa":"/prɪˈzjuːməbli/","usIpa":"/prɪˈzuːməbli/","cefr":"B2","topic":"thinking","senses":[{"pos":"adv.","en":"Probably true, based on what is known or reasonably expected.","vi":"có lẽ; có thể là; theo như dự đoán"}],"examples":[{"en":"Her coat is gone, so presumably she has left.","vi":"Áo khoác của cô ấy không còn ở đây, có lẽ cô ấy đã đi rồi.","audioKind":"ex"},{"en":"More frequent bus services would presumably encourage commuters to leave their cars at home, reducing urban traffic.","vi":"Các chuyến xe buýt với tần suất dày đặc hơn có lẽ sẽ khuyến khích người đi làm để xe ở nhà, qua đó làm giảm ùn tắc giao thông đô thị.","audioKind":"ex2"}],"collocations":[{"en":"presumably because","vi":"có lẽ bởi vì"},{"en":"presumably intended to","vi":"có lẽ được dùng để"},{"en":"presumably true","vi":"có lẽ là đúng"}],"wordFamily":["presume (v.)","presumption (n.)"],"synonyms":["probably","likely"],"antonyms":[],"tipVi":"Thể hiện sự phỏng đoán dựa trên cơ sở thực tế, không mang ý nghĩa chắc chắn tuyệt đối như certainly.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_impractical', 'en-b2-39', 'impractical', '/ɪmˈpræktɪkəl/', 'B2', 'không thực tế; không khả thi; không khéo léo trong việc xử lý các công việc thường ngày', 'adj.', 'practical (adj.), impracticality (n.), impractically (adv.)', 'Đồng nghĩa: unworkable, unrealistic · Trái nghĩa: practical, workable', 'Là tính từ, không phải động từ; không thực tế không nhất thiết là không thể.', 'These white shoes are impractical for a muddy walk.', NULL, 'Đôi giày trắng này không thực tế để đi vào con đường lầy lội.', '{"wordId":"impractical","ukIpa":"/ɪmˈpræktɪkəl/","usIpa":"/ɪmˈpræktɪkəl/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Unlikely to work well or be useful in practice","vi":"không thực tế; không khả thi"},{"pos":"adj.","en":"Not skilled at handling everyday practical tasks","vi":"không khéo léo trong việc xử lý các công việc thường ngày"}],"examples":[{"en":"These white shoes are impractical for a muddy walk.","vi":"Đôi giày trắng này không thực tế để đi vào con đường lầy lội.","audioKind":"ex"},{"en":"Building underground railways may be impractical in smaller cities because construction costs often exceed available budgets.","vi":"Việc xây dựng hệ thống đường sắt ngầm có thể không khả thi ở các thành phố nhỏ hơn vì chi phí xây dựng thường vượt quá ngân sách có sẵn.","audioKind":"ex2"}],"collocations":[{"en":"an impractical solution","vi":"một giải pháp không thực tế"},{"en":"highly impractical","vi":"rất kém thực tế"},{"en":"impractical for everyday use","vi":"không phù hợp cho việc sử dụng hàng ngày"}],"wordFamily":["practical (adj.)","impracticality (n.)","impractically (adv.)"],"synonyms":["unworkable","unrealistic"],"antonyms":["practical","workable"],"tipVi":"Là tính từ, không phải động từ; không thực tế không nhất thiết là không thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_instance', 'en-b2-39', 'instance', '/ˈɪnstəns/', 'B2', 'ví dụ; trường hợp; tình huống cụ thể', 'n.', NULL, 'Đồng nghĩa: example, case', 'for instance mang nghĩa là "ví dụ", có chức năng tương tự như for example.', 'Some fruits freeze well; berries, for instance, keep their flavour.', NULL, 'Một số loại quả đông lạnh rất tốt; chẳng hạn như quả mọng giữ được hương vị của chúng.', '{"wordId":"instance","ukIpa":"/ˈɪnstəns/","usIpa":"/ˈɪnstəns/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"A particular example or occurrence of something.","vi":"ví dụ; trường hợp; tình huống cụ thể"}],"examples":[{"en":"Some fruits freeze well; berries, for instance, keep their flavour.","vi":"Một số loại quả đông lạnh rất tốt; chẳng hạn như quả mọng giữ được hương vị của chúng.","audioKind":"ex"},{"en":"This project provides an instance of successful cooperation between local businesses and environmental research groups.","vi":"Dự án này cung cấp một ví dụ thực tế về sự hợp tác thành công giữa các doanh nghiệp địa phương và các nhóm nghiên cứu môi trường.","audioKind":"ex2"}],"collocations":[{"en":"for instance","vi":"ví dụ như"},{"en":"in this instance","vi":"trong trường hợp này"},{"en":"an isolated instance","vi":"một trường hợp cá biệt"}],"wordFamily":[],"synonyms":["example","case"],"antonyms":[],"tipVi":"for instance mang nghĩa là \"ví dụ\", có chức năng tương tự như for example.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_absurd', 'en-b2-39', 'absurd', '/əbˈsɝːd/', 'B2', 'vô lý; ngớ ngẩn; lố bịch', 'adj.', 'absurdity (n.), absurdly (adv.)', 'Đồng nghĩa: ridiculous, ludicrous · Trái nghĩa: reasonable, sensible', 'Cấu trúc phổ biến: It is absurd to do sth.', 'It seems absurd to drive when the shop is so close.', NULL, 'Thật vô lý khi lái xe đi khi cửa hàng ở gần như vậy.', '{"wordId":"absurd","ukIpa":"/əbˈsɜːd/","usIpa":"/əbˈsɝːd/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Completely unreasonable or silly.","vi":"vô lý; ngớ ngẩn; lố bịch"}],"examples":[{"en":"It seems absurd to drive when the shop is so close.","vi":"Thật vô lý khi lái xe đi khi cửa hàng ở gần như vậy.","audioKind":"ex"},{"en":"It is absurd to expect public transport use to increase without improving service quality or affordability.","vi":"Thật vô lý khi mong đợi tỷ lệ sử dụng giao thông công cộng tăng lên mà không cải thiện chất lượng dịch vụ hoặc mức giá phải chăng.","audioKind":"ex2"}],"collocations":[{"en":"an absurd idea","vi":"một ý tưởng ngớ ngẩn"},{"en":"an absurd claim","vi":"một tuyên bố vô lý"},{"en":"completely absurd","vi":"hoàn toàn vô lý"}],"wordFamily":["absurdity (n.)","absurdly (adv.)"],"synonyms":["ridiculous","ludicrous"],"antonyms":["reasonable","sensible"],"tipVi":"Cấu trúc phổ biến: It is absurd to do sth.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_analyse', 'en-b2-39', 'analyse', '/ˈænəlaɪz/', 'B2', 'phân tích; xem xét kỹ lưỡng', 'v.', 'analysis (n.), analyst (n.), analytical (adj.), analytically (adv.)', 'Đồng nghĩa: examine, investigate', 'Cách viết Anh-Anh là analyse, trong khi tiếng Anh-Mỹ thường viết là analyze.', 'We analysed our spending and cancelled two unused subscriptions.', NULL, 'Chúng tôi đã phân tích các khoản chi tiêu và hủy hai gói đăng ký không dùng đến.', '{"wordId":"analyse","ukIpa":"/ˈænəlaɪz/","usIpa":"/ˈænəlaɪz/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"to examine something carefully to understand its parts or causes","vi":"phân tích; xem xét kỹ lưỡng"}],"examples":[{"en":"We analysed our spending and cancelled two unused subscriptions.","vi":"Chúng tôi đã phân tích các khoản chi tiêu và hủy hai gói đăng ký không dùng đến.","audioKind":"ex"},{"en":"Researchers analyse survey responses to identify the main barriers preventing adults from returning to education.","vi":"Các nhà nghiên cứu phân tích các câu trả lời khảo sát để xác định những rào cản chính ngăn cản người lớn quay trở lại học tập.","audioKind":"ex2"}],"collocations":[{"en":"analyse data","vi":"phân tích dữ liệu"},{"en":"analyse the results","vi":"phân tích kết quả"},{"en":"analyse a problem","vi":"phân tích một vấn đề"}],"wordFamily":["analysis (n.)","analyst (n.)","analytical (adj.)","analytically (adv.)"],"synonyms":["examine","investigate"],"antonyms":[],"tipVi":"Cách viết Anh-Anh là analyse, trong khi tiếng Anh-Mỹ thường viết là analyze.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inevitable', 'en-b2-39', 'inevitable', '/ɪnˈevɪtəbl/', 'B2', 'không thể tránh khỏi; chắc chắn xảy ra', 'adj.', 'inevitably (adv.), inevitability (n.)', 'Đồng nghĩa: unavoidable, inescapable · Trái nghĩa: avoidable', 'Thường dùng cấu trúc it is inevitable that… để diễn tả việc gì đó chắc chắn sẽ xảy ra.', 'With traffic this heavy, a delay seems inevitable.', NULL, 'Với tình hình giao thông đông đúc thế này, việc bị trễ là điều dường như không thể tránh khỏi.', '{"wordId":"inevitable","ukIpa":"/ɪnˈevɪtəbl/","usIpa":"/ɪnˈevɪtəbl/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Certain to happen and impossible to prevent","vi":"không thể tránh khỏi; chắc chắn xảy ra"}],"examples":[{"en":"With traffic this heavy, a delay seems inevitable.","vi":"Với tình hình giao thông đông đúc thế này, việc bị trễ là điều dường như không thể tránh khỏi.","audioKind":"ex"},{"en":"Some job losses may be inevitable as factories introduce machines that perform routine tasks more efficiently.","vi":"Một số việc mất việc làm có thể là điều tất yếu khi các nhà máy đưa vào sử dụng máy móc thực hiện các công việc thường lệ hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"inevitable consequences","vi":"hậu quả tất yếu"},{"en":"inevitable change","vi":"sự thay đổi tất yếu"},{"en":"almost inevitable","vi":"gần như không thể tránh khỏi"}],"wordFamily":["inevitably (adv.)","inevitability (n.)"],"synonyms":["unavoidable","inescapable"],"antonyms":["avoidable"],"tipVi":"Thường dùng cấu trúc it is inevitable that… để diễn tả việc gì đó chắc chắn sẽ xảy ra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bold', 'en-b2-39', 'bold', '/boʊld/', 'B2', 'táo bạo; dũng cảm; nổi bật; rực rỡ; in đậm', 'adj.', 'boldly (adv.), boldness (n.)', 'Đồng nghĩa: daring, confident · Trái nghĩa: timid, cautious', 'in bold biểu thị "in đậm", thường dùng trong hướng dẫn trình bày văn bản.', 'She made a bold decision to open her own bakery.', NULL, 'Cô ấy đã đưa ra một quyết định táo bạo là tự mở tiệm bánh riêng.', '{"wordId":"bold","ukIpa":"/bəʊld/","usIpa":"/boʊld/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Willing to take risks or act with confidence.","vi":"táo bạo; dũng cảm"},{"pos":"adj.","en":"Strong and easily noticed in colour, shape, or design.","vi":"nổi bật; rực rỡ"},{"pos":"adj.","en":"Printed with thicker, darker lines than ordinary type.","vi":"in đậm"}],"examples":[{"en":"She made a bold decision to open her own bakery.","vi":"Cô ấy đã đưa ra một quyết định táo bạo là tự mở tiệm bánh riêng.","audioKind":"ex"},{"en":"Governments need bold policies to address housing shortages while protecting green spaces and supporting affordable development.","vi":"Chính phủ cần có các chính sách táo bạo để giải quyết tình trạng thiếu hụt nhà ở, đồng thời bảo vệ không gian xanh và hỗ trợ phát triển nhà ở vừa túi tiền.","audioKind":"ex2"}],"collocations":[{"en":"bold decision","vi":"quyết định táo bạo"},{"en":"bold colours","vi":"màu sắc nổi bật"},{"en":"bold type","vi":"chữ in đậm"},{"en":"bold approach","vi":"cách tiếp cận táo bạo"}],"wordFamily":["boldly (adv.)","boldness (n.)"],"synonyms":["daring","confident"],"antonyms":["timid","cautious"],"tipVi":"in bold biểu thị \"in đậm\", thường dùng trong hướng dẫn trình bày văn bản.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_odds', 'en-b2-39', 'odds', '/ɑːdz/', 'B2', 'xác suất; khả năng; tỷ lệ cá cược', 'n.', NULL, 'Đồng nghĩa: chances, likelihood', 'odds luôn dùng ở dạng số nhiều, thường đi với of hoặc mệnh đề that.', 'The odds of finding my keys here are low.', NULL, 'Khả năng tìm thấy chìa khóa của tôi ở đây rất thấp.', '{"wordId":"odds","ukIpa":"/ɒdz/","usIpa":"/ɑːdz/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"The likelihood that something will happen.","vi":"xác suất; khả năng"},{"pos":"n.","en":"The ratio determining how much a successful bet pays.","vi":"tỷ lệ cá cược"}],"examples":[{"en":"The odds of finding my keys here are low.","vi":"Khả năng tìm thấy chìa khóa của tôi ở đây rất thấp.","audioKind":"ex"},{"en":"Access to affordable healthcare can improve the odds of recovery for patients with chronic illnesses.","vi":"Việc tiếp cận dịch vụ chăm sóc sức khỏe vừa phải có thể nâng cao cơ hội hồi phục cho bệnh nhân mắc bệnh mãn tính.","audioKind":"ex2"}],"collocations":[{"en":"the odds of success","vi":"khả năng thành công"},{"en":"against all odds","vi":"bất chấp mọi khó khăn"},{"en":"at odds with","vi":"mâu thuẫn với; không ăn khớp với"},{"en":"improve the odds","vi":"nâng cao cơ hội"}],"wordFamily":[],"synonyms":["chances","likelihood"],"antonyms":[],"tipVi":"odds luôn dùng ở dạng số nhiều, thường đi với of hoặc mệnh đề that.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nonsense', 'en-b2-39', 'nonsense', '/ˈnɑːnsens/', 'B2', 'lời nói nhảm; điều vô lý; chuyện nhảm nhí; hành vi ngớ ngẩn; trò hề', 'n.', 'nonsensical (adj.)', 'Đồng nghĩa: rubbish, absurdity · Trái nghĩa: sense', 'Thường là danh từ không đếm được; nói một tràng vô lý dùng complete nonsense.', 'That story about a flying bicycle is complete nonsense.', NULL, 'Câu chuyện về chiếc xe đạp bay đó hoàn toàn làa nhảm nhí.', '{"wordId":"nonsense","ukIpa":"/ˈnɒnsəns/","usIpa":"/ˈnɑːnsens/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"words or ideas that are absurd or have no meaning","vi":"lời nói nhảm; điều vô lý; chuyện nhảm nhí"},{"pos":"n.","en":"silly or unacceptable behaviour","vi":"hành vi ngớ ngẩn; trò hề"}],"examples":[{"en":"That story about a flying bicycle is complete nonsense.","vi":"Câu chuyện về chiếc xe đạp bay đó hoàn toàn làa nhảm nhí.","audioKind":"ex"},{"en":"Schools should teach students to distinguish reliable evidence from nonsense circulated through social media platforms.","vi":"Nhà trường nên dạy học sinh cách phân biệt bằng chứng đáng tin cậy với những lời đồn nhảm lan truyền trên các nền tảng mạng xã hội.","audioKind":"ex2"}],"collocations":[{"en":"talk nonsense","vi":"nói nhảm"},{"en":"complete nonsense","vi":"hoàn toàn nhảm nhí"},{"en":"a load of nonsense","vi":"một đống vô nghĩa"},{"en":"put up with nonsense","vi":"chịu đựng những trò nhảm nhí"}],"wordFamily":["nonsensical (adj.)"],"synonyms":["rubbish","absurdity"],"antonyms":["sense"],"tipVi":"Thường là danh từ không đếm được; nói một tràng vô lý dùng complete nonsense.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_estimate', 'en-b2-39', 'estimate', '/ˈestəmeɪt/', 'B2', 'ước tính; ước lượng; sự ước tính; bản dự toán chi phí', 'v.', 'estimation (n.), estimated (adj.), overestimate (v.), underestimate (v.)', 'Đồng nghĩa: approximate', 'Động từ phát âm đuôi /eɪt/; danh từ phát âm đuôi /ət/.', 'We estimate the repairs will take about three days.', NULL, 'Chúng tôi ước tính việc sửa chữa sẽ mất khoảng ba ngày.', '{"wordId":"estimate","ukIpa":"/ˈestɪmeɪt/","usIpa":"/ˈestəmeɪt/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"To judge an approximate amount, value, or size.","vi":"ước tính; ước lượng"},{"pos":"n.","en":"An approximate calculation of an amount, value, or cost.","vi":"sự ước tính; bản dự toán chi phí"}],"examples":[{"en":"We estimate the repairs will take about three days.","vi":"Chúng tôi ước tính việc sửa chữa sẽ mất khoảng ba ngày.","audioKind":"ex"},{"en":"Researchers estimate that improved public transport could significantly reduce the number of cars entering city centres.","vi":"Các nhà nghiên cứu ước tính rằng việc cải thiện giao thông công cộng có thể làm giảm đáng kể số lượng ô tô đi vào trung tâm thành phố.","audioKind":"ex2"}],"collocations":[{"en":"estimate the cost","vi":"ước tính chi phí"},{"en":"a rough estimate","vi":"ước tính sơ bộ"},{"en":"a conservative estimate","vi":"ước tính thận trọng"},{"en":"be estimated at","vi":"được ước tính là"}],"wordFamily":["estimation (n.)","estimated (adj.)","overestimate (v.)","underestimate (v.)"],"synonyms":["approximate"],"antonyms":[],"tipVi":"Động từ phát âm đuôi /eɪt/; danh từ phát âm đuôi /ət/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recall', 'en-b2-39', 'recall', '/rɪˈkɔːl/', 'B2', 'nhớ lại; hồi tưởng; triệu hồi; thu hồi; trí nhớ; lệnh thu hồi sản phẩm', 'v.', NULL, 'Đồng nghĩa: remember, recollect · Trái nghĩa: forget', 'Để diễn đạt việc nhớ lại đã làm việc gì, dùng recall doing, không dùng to do.', 'I still recall the smell of my grandmother''s kitchen.', NULL, 'Tôi vẫn nhớ như in mùi hương từ nhà bếp của bà tôi.', '{"wordId":"recall","ukIpa":"/rɪˈkɔːl/","usIpa":"/rɪˈkɔːl/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"to remember something from the past","vi":"nhớ lại; hồi tưởng"},{"pos":"v.","en":"to order someone back or request the return of products","vi":"triệu hồi; thu hồi"},{"pos":"n.","en":"the ability to remember, or an official request for returns","vi":"trí nhớ; lệnh thu hồi sản phẩm"}],"examples":[{"en":"I still recall the smell of my grandmother''s kitchen.","vi":"Tôi vẫn nhớ như in mùi hương từ nhà bếp của bà tôi.","audioKind":"ex"},{"en":"Manufacturers should recall faulty products promptly to protect consumers and maintain public trust in safety standards.","vi":"Các nhà sản xuất nên nhanh chóng thu hồi các sản phẩm bị lỗi để bảo vệ người tiêu dùng và duy trì niềm tin của công chúng đối với các tiêu chuẩn an toàn.","audioKind":"ex2"}],"collocations":[{"en":"recall a detail","vi":"nhớ lại một chi tiết"},{"en":"recall doing something","vi":"nhớ lại việc đã làm"},{"en":"product recall","vi":"thu hồi sản phẩm"},{"en":"total recall","vi":"trí nhớ hoàn hảo"}],"wordFamily":[],"synonyms":["remember","recollect"],"antonyms":["forget"],"tipVi":"Để diễn đạt việc nhớ lại đã làm việc gì, dùng recall doing, không dùng to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_confusion', 'en-b2-39', 'confusion', '/kənˈfjuːʒən/', 'B2', 'sự bối rối; sự mơ hồ; sự không hiểu rõ; sự nhầm lẫn; tình trạng lộn xộn', 'n.', 'confuse (v.), confused (adj.), confusing (adj.)', 'Đồng nghĩa: bewilderment · Trái nghĩa: clarity', 'Người cảm thấy bối rối dùng confused; sự việc gây bối rối dùng confusing.', 'He stared at the unfamiliar controls in confusion.', NULL, 'Anh ấy nhìn chằm chằm vào bảng điều khiển xa lạ với vẻ đầy bối rối.', '{"wordId":"confusion","ukIpa":"/kənˈfjuːʒən/","usIpa":"/kənˈfjuːʒən/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"A state of not understanding something clearly","vi":"sự bối rối; sự mơ hồ; sự không hiểu rõ"},{"pos":"n.","en":"A situation where things are mixed up or poorly organised","vi":"sự nhầm lẫn; tình trạng lộn xộn"}],"examples":[{"en":"He stared at the unfamiliar controls in confusion.","vi":"Anh ấy nhìn chằm chằm vào bảng điều khiển xa lạ với vẻ đầy bối rối.","audioKind":"ex"},{"en":"Clear instructions can reduce confusion among patients and help them take their medication safely.","vi":"Những hướng dẫn rõ ràng có thể làm giảm bớt sự bối rối ở bệnh nhân và giúp họ dùng thuốc một cách an toàn.","audioKind":"ex2"}],"collocations":[{"en":"cause confusion","vi":"gây ra sự bối rối"},{"en":"avoid confusion","vi":"tránh nhầm lẫn"},{"en":"clear up confusion","vi":"làm sáng tỏ sự bối rối"},{"en":"confusion over","vi":"sự bối rối về"}],"wordFamily":["confuse (v.)","confused (adj.)","confusing (adj.)"],"synonyms":["bewilderment"],"antonyms":["clarity"],"tipVi":"Người cảm thấy bối rối dùng confused; sự việc gây bối rối dùng confusing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recommendation', 'en-b2-39', 'recommendation', '/ˌrekəmenˈdeɪʃən/', 'B2', 'lời khuyên; khuyến nghị; sự giới thiệu; thư giới thiệu', 'n.', 'recommend (v.), recommended (adj.)', NULL, 'Mệnh đề sau recommendation thường dùng should hoặc động từ nguyên mẫu.', 'On your recommendation, I started taking short evening walks.', NULL, 'Theo gợi ý của bạn, tôi đã bắt đầu đi dạo nhẹ nhàng vào buổi tối.', '{"wordId":"recommendation","ukIpa":"/ˌrekəmenˈdeɪʃən/","usIpa":"/ˌrekəmenˈdeɪʃən/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"advice about the best thing to do","vi":"lời khuyên; khuyến nghị"},{"pos":"n.","en":"a statement supporting someone''s or something''s suitability or quality","vi":"sự giới thiệu; thư giới thiệu"}],"examples":[{"en":"On your recommendation, I started taking short evening walks.","vi":"Theo gợi ý của bạn, tôi đã bắt đầu đi dạo nhẹ nhàng vào buổi tối.","audioKind":"ex"},{"en":"The committee''s main recommendation was to improve public transport before introducing higher parking charges in the city centre.","vi":"Khuyến nghị chính của ủy ban là cải thiện giao thông công cộng trước khi áp dụng phí đỗ xe cao hơn ở trung tâm thành phố.","audioKind":"ex2"}],"collocations":[{"en":"make a recommendation","vi":"đưa ra khuyến nghị"},{"en":"follow a recommendation","vi":"làm theo lời khuyên"},{"en":"on someone''s recommendation","vi":"theo lời giới thiệu của ai đó"},{"en":"letter of recommendation","vi":"thư giới thiệu"}],"wordFamily":["recommend (v.)","recommended (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Mệnh đề sau recommendation thường dùng should hoặc động từ nguyên mẫu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cleverness', 'en-b2-39', 'cleverness', '/ˈklevərnəs/', 'B2', 'sự thông minh; sự tháo vát; sự khéo léo', 'n.', 'clever (adj.), cleverly (adv.)', 'Đồng nghĩa: intelligence, ingenuity · Trái nghĩa: stupidity', 'Là danh từ không đếm được; có thể chỉ sự nhanh trí của con người hoặc tính thông minh, sáng tạo trong thiết kế.', 'Her cleverness helped us fix the tent before sunset.', NULL, 'Sự lanh lợi của cô ấy đã giúp chúng tôi dựng lại chiếc lều trước khi trời tối.', '{"wordId":"cleverness","ukIpa":"/ˈklevənəs/","usIpa":"/ˈklevərnəs/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"the ability to understand quickly or find effective, inventive solutions","vi":"sự thông minh; sự tháo vát; sự khéo léo"}],"examples":[{"en":"Her cleverness helped us fix the tent before sunset.","vi":"Sự lanh lợi của cô ấy đã giúp chúng tôi dựng lại chiếc lều trước khi trời tối.","audioKind":"ex"},{"en":"The cleverness of a design lies in solving practical problems without introducing unnecessary complexity.","vi":"Sự khéo léo của một thiết kế nằm ở chỗ giải quyết được các vấn đề thực tế mà không tạo ra sự phức tạp không cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"remarkable cleverness","vi":"tài trí xuất chúng"},{"en":"the cleverness of a design","vi":"sự khéo léo của thiết kế"},{"en":"show cleverness","vi":"thể hiện sự lanh lợi"}],"wordFamily":["clever (adj.)","cleverly (adv.)"],"synonyms":["intelligence","ingenuity"],"antonyms":["stupidity"],"tipVi":"Là danh từ không đếm được; có thể chỉ sự nhanh trí của con người hoặc tính thông minh, sáng tạo trong thiết kế.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_objective', 'en-b2-39', 'objective', '/əbˈdʒektɪv/', 'B2', 'mục tiêu; mục đích; khách quan; không thiên vị', 'n.', 'objectively (adv.), objectivity (n.)', 'Đồng nghĩa: goal, aim · Trái nghĩa: subjective', 'Danh từ chỉ mục tiêu; tính từ mang nghĩa khách quan, trái nghĩa với "subjective".', 'My main objective is to finish the race.', NULL, 'Mục tiêu chính của tôi là hoàn thành cuộc đua.', '{"wordId":"objective","ukIpa":"/əbˈdʒektɪv/","usIpa":"/əbˈdʒektɪv/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"Something you aim to achieve.","vi":"mục tiêu; mục đích"},{"pos":"adj.","en":"Based on facts rather than personal feelings or opinions.","vi":"khách quan; không thiên vị"}],"examples":[{"en":"My main objective is to finish the race.","vi":"Mục tiêu chính của tôi là hoàn thành cuộc đua.","audioKind":"ex"},{"en":"Researchers should remain objective when evaluating evidence about the effects of homework on student achievement.","vi":"Các nhà nghiên cứu nên giữ thái độ khách quan khi đánh giá bằng chứng về tác động của bài tập về nhà đối với thành tích học tập của học sinh.","audioKind":"ex2"}],"collocations":[{"en":"achieve an objective","vi":"đạt được mục tiêu"},{"en":"primary objective","vi":"mục tiêu chính"},{"en":"objective assessment","vi":"đánh giá khách quan"},{"en":"remain objective","vi":"giữ thái độ khách quan"}],"wordFamily":["objectively (adv.)","objectivity (n.)"],"synonyms":["goal","aim"],"antonyms":["subjective"],"tipVi":"Danh từ chỉ mục tiêu; tính từ mang nghĩa khách quan, trái nghĩa với \"subjective\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_distinction', 'en-b2-39', 'distinction', '/dɪˈstɪŋkʃən/', 'B2', 'sự phân biệt, điểm khác biệt; sự xuất sắc, nét ưu tú, sự kính trọng; điểm số ưu tú, giải thưởng danh giá', 'n.', 'distinct (adj.), distinctive (adj.), distinctly (adv.), distinguish (v.)', 'Đồng nghĩa: difference, excellence · Trái nghĩa: similarity', 'Để chỉ sự phân biệt giữa hai vật, thường dùng cụm "distinction between A and B".', 'I never understood the distinction between those two sports.', NULL, 'Tôi chưa bao giờ hiểu được sự khác biệt giữa hai môn thể thao đó.', '{"wordId":"distinction","ukIpa":"/dɪˈstɪŋkʃən/","usIpa":"/dɪˈstɪŋkʃən/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"A difference that separates one thing or group from another","vi":"sự phân biệt, điểm khác biệt"},{"pos":"n.","en":"The quality of being excellent and deserving respect","vi":"sự xuất sắc, nét ưu tú, sự kính trọng"},{"pos":"n.","en":"A special award or high grade recognizing excellent achievement","vi":"điểm số ưu tú, giải thưởng danh giá"}],"examples":[{"en":"I never understood the distinction between those two sports.","vi":"Tôi chưa bao giờ hiểu được sự khác biệt giữa hai môn thể thao đó.","audioKind":"ex"},{"en":"Policymakers should draw a clear distinction between temporary unemployment and long-term exclusion from the labour market.","vi":"Các nhà hoạch định chính sách nên phân định rõ ràng giữa tình trạng thất nghiệp tạm thời và tình trạng bị gạt ra ngoài lề thị trường lao động lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"draw a distinction between","vi":"phân biệt giữa... và..."},{"en":"a clear distinction","vi":"sự khác biệt rõ ràng"},{"en":"with distinction","vi":"đạt thành tích xuất sắc"},{"en":"a person of distinction","vi":"một nhân vật kiệt xuất"}],"wordFamily":["distinct (adj.)","distinctive (adj.)","distinctly (adv.)","distinguish (v.)"],"synonyms":["difference","excellence"],"antonyms":["similarity"],"tipVi":"Để chỉ sự phân biệt giữa hai vật, thường dùng cụm \"distinction between A and B\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_probable', 'en-b2-39', 'probable', '/ˈprɑːbəbl/', 'B2', 'có thể xảy ra; có khả năng cao', 'adj.', 'probably (adv.), probability (n.), improbable (adj.)', 'Đồng nghĩa: likely · Trái nghĩa: improbable, unlikely', 'Thường dùng cấu trúc it is probable that; không dùng cấu trúc somebody is probable to do.', 'The mechanic explained the probable cause of the noise.', NULL, 'Người thợ máy đã giải thích nguyên nhân có khả năng cao nhất gây ra tiếng ồn đó.', '{"wordId":"probable","ukIpa":"/ˈprɒbəbl/","usIpa":"/ˈprɑːbəbl/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Likely to happen or be true.","vi":"có thể xảy ra; có khả năng cao"}],"examples":[{"en":"The mechanic explained the probable cause of the noise.","vi":"Người thợ máy đã giải thích nguyên nhân có khả năng cao nhất gây ra tiếng ồn đó.","audioKind":"ex"},{"en":"Given current population trends, it is probable that demand for affordable housing will continue to rise.","vi":"Dựa trên các xu hướng dân số hiện tại, rất có khả năng nhu cầu về nhà ở giá rẻ sẽ tiếp tục tăng lên.","audioKind":"ex2"}],"collocations":[{"en":"probable cause","vi":"nguyên nhân rất có thể"},{"en":"probable outcome","vi":"kết quả có khả năng cao"},{"en":"highly probable","vi":"rất có khả năng"}],"wordFamily":["probably (adv.)","probability (n.)","improbable (adj.)"],"synonyms":["likely"],"antonyms":["improbable","unlikely"],"tipVi":"Thường dùng cấu trúc it is probable that; không dùng cấu trúc somebody is probable to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cautious', 'en-b2-39', 'cautious', '/ˈkɔːʃəs/', 'B2', 'thận trọng; cẩn trọng; dè dặt', 'adj.', 'caution (n., v.), cautiously (adv.), cautiousness (n.)', 'Đồng nghĩa: careful, wary, prudent · Trái nghĩa: reckless, careless', 'Thường đi với cấu trúc be cautious about doing, diễn tả sự cẩn trọng khi làm việc gì đó.', 'The cautious driver slowed down before the icy bridge.', NULL, 'Người lái xe cẩn trọng đã giảm tốc độ trước chiếc cầu bị đóng băng.', '{"wordId":"cautious","ukIpa":"/ˈkɔːʃəs/","usIpa":"/ˈkɔːʃəs/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Careful to avoid danger, mistakes, or unnecessary risks.","vi":"thận trọng; cẩn trọng; dè dặt"}],"examples":[{"en":"The cautious driver slowed down before the icy bridge.","vi":"Người lái xe cẩn trọng đã giảm tốc độ trước chiếc cầu bị đóng băng.","audioKind":"ex"},{"en":"Consumers should be cautious about sharing personal information with unfamiliar websites, particularly when making online payments.","vi":"Người tiêu dùng nên thận trọng khi chia sẻ thông tin cá nhân với các trang web lạ, đặc biệt là khi thực hiện thanh toán trực tuyến.","audioKind":"ex2"}],"collocations":[{"en":"cautious approach","vi":"phương pháp thận trọng"},{"en":"cautious about","vi":"thận trọng về"},{"en":"cautious optimism","vi":"lạc quan thận trọng"}],"wordFamily":["caution (n., v.)","cautiously (adv.)","cautiousness (n.)"],"synonyms":["careful","wary","prudent"],"antonyms":["reckless","careless"],"tipVi":"Thường đi với cấu trúc be cautious about doing, diễn tả sự cẩn trọng khi làm việc gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wisdom', 'en-b2-39', 'wisdom', '/ˈwɪz.dəm/', 'B2', 'sự khôn ngoan; trí tuệ; sự sáng suốt; lời khuyên khôn ngoan; đúc kết quý báu', 'n.', 'wise (adj.), wisely (adv.), unwise (adj.)', 'Đồng nghĩa: good judgement, insight · Trái nghĩa: folly, foolishness', 'Là danh từ không đếm được; knowledge thiên về kiến thức, còn wisdom thiên về năng lực phán đoán và ứng dụng.', 'My grandmother shared her wisdom while we cooked together.', NULL, 'Bà tôi chia sẻ những đúc kết sâu sắc của mình trong lúc chúng tôi cùng nhau nấu ăn.', '{"wordId":"wisdom","ukIpa":"/ˈwɪz.dəm/","usIpa":"/ˈwɪz.dəm/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"The ability to judge well using knowledge and experience","vi":"sự khôn ngoan; trí tuệ; sự sáng suốt"},{"pos":"n.","en":"Ideas or advice considered sensible and valuable","vi":"lời khuyên khôn ngoan; đúc kết quý báu"}],"examples":[{"en":"My grandmother shared her wisdom while we cooked together.","vi":"Bà tôi chia sẻ những đúc kết sâu sắc của mình trong lúc chúng tôi cùng nhau nấu ăn.","audioKind":"ex"},{"en":"The wisdom of expanding road networks is increasingly questioned as cities seek more sustainable transport solutions.","vi":"Sự khôn ngoan của việc mở rộng mạng lưới đường bộ ngày càng bị đặt dấu hỏi khi các đô thị tìm kiếm các giải pháp giao thông bền vững hơn.","audioKind":"ex2"}],"collocations":[{"en":"conventional wisdom","vi":"quan niệm thông thường; trí tuệ truyền thống"},{"en":"words of wisdom","vi":"lời vàng ý ngọc; những lời khôn ngoan"},{"en":"question the wisdom of","vi":"đặt câu hỏi về tính khôn ngoan của việc gì"},{"en":"the wisdom to do something","vi":"sự khôn ngoan để làm điều gì"}],"wordFamily":["wise (adj.)","wisely (adv.)","unwise (adj.)"],"synonyms":["good judgement","insight"],"antonyms":["folly","foolishness"],"tipVi":"Là danh từ không đếm được; knowledge thiên về kiến thức, còn wisdom thiên về năng lực phán đoán và ứng dụng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pessimistic', 'en-b2-39', 'pessimistic', '/ˌpesɪˈmɪstɪk/', 'B2', 'bi quan', 'adj.', 'pessimism (n.), pessimist (n.), pessimistically (adv.)', 'Đồng nghĩa: negative, downbeat · Trái nghĩa: optimistic', 'Thường dùng be pessimistic about; từ trái nghĩa là optimistic.', 'He felt pessimistic about the picnic when clouds gathered.', NULL, 'Anh ấy cảm thấy bi quan về buổi dã ngoại khi mây đen ùn ùn kéo đến.', '{"wordId":"pessimistic","ukIpa":"/ˌpesɪˈmɪstɪk/","usIpa":"/ˌpesɪˈmɪstɪk/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Expecting bad results or focusing on possible problems.","vi":"bi quan"}],"examples":[{"en":"He felt pessimistic about the picnic when clouds gathered.","vi":"Anh ấy cảm thấy bi quan về buổi dã ngoại khi mây đen ùn ùn kéo đến.","audioKind":"ex"},{"en":"Young people may become pessimistic about their career prospects when stable employment opportunities remain limited.","vi":"Giới trẻ có thể trở nên bi quan về triển vọng nghề nghiệp của họ khi cơ hội việc làm ổn định vẫn còn hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"pessimistic about the future","vi":"bi quan về tương lai"},{"en":"a pessimistic outlook","vi":"cái nhìn bi quan"},{"en":"a pessimistic forecast","vi":"dự báo bi quan"}],"wordFamily":["pessimism (n.)","pessimist (n.)","pessimistically (adv.)"],"synonyms":["negative","downbeat"],"antonyms":["optimistic"],"tipVi":"Thường dùng be pessimistic about; từ trái nghĩa là optimistic.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_crucial', 'en-b2-39', 'crucial', '/ˈkruːʃəl/', 'B2', 'tối quan trọng; cốt yếu', 'adj.', 'crucially (adv.)', 'Đồng nghĩa: vital, essential, critical · Trái nghĩa: unimportant', 'Mức độ mạnh hơn important; thường đi với cụm be crucial to.', 'Your spare key was crucial when I locked myself out.', NULL, 'Chìa khóa dự phòng của bạn thực sự đóng vai trò cốt yếu khi tôi bị khóa ngoài cửa.', '{"wordId":"crucial","ukIpa":"/ˈkruːʃəl/","usIpa":"/ˈkruːʃəl/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"extremely important to the success or outcome of something","vi":"tối quan trọng; cốt yếu"}],"examples":[{"en":"Your spare key was crucial when I locked myself out.","vi":"Chìa khóa dự phòng của bạn thực sự đóng vai trò cốt yếu khi tôi bị khóa ngoài cửa.","audioKind":"ex"},{"en":"Access to reliable public transport is crucial for people seeking employment beyond their immediate neighbourhoods.","vi":"Việc tiếp cận giao thông công cộng đáng tin cậy là tối quan trọng đối với những người tìm kiếm việc làm ở xa khu vực lân cận của họ.","audioKind":"ex2"}],"collocations":[{"en":"a crucial role","vi":"vai trò then chốt"},{"en":"a crucial factor","vi":"yếu tố cốt yếu"},{"en":"crucial to success","vi":"mang tính quyết định cho thành công"},{"en":"a crucial decision","vi":"quyết định then chốt"}],"wordFamily":["crucially (adv.)"],"synonyms":["vital","essential","critical"],"antonyms":["unimportant"],"tipVi":"Mức độ mạnh hơn important; thường đi với cụm be crucial to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 28, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_39_1', 'en-b2-39', 'Cách dùng “limitation” (n.) — hạn chế; thiếu sót', 'limitations of a study  ·  place limitations on  ·  budget limitations', 'Khi mang nghĩa "những hạn chế/thiếu sót" thường dùng ở dạng số nhiều; giới hạn đối với cái gì dùng "limitation on".', 'Họ từ (Word Family): limit (n.), limit (v.), limited (adj.), limitless (adj.) | Đồng nghĩa: restriction, constraint', '[{"hanzi":"The main limitation of this camera is its battery life.","pinyin":"","meaning":"Hạn chế chính của chiếc máy ảnh này là thời lượng pin."},{"hanzi":"Researchers should acknowledge the limitations of small samples before drawing conclusions about the wider population.","pinyin":"","meaning":"Các nhà nghiên cứu nên thừa nhận những hạn chế của các mẫu khảo sát nhỏ trước khi đưa ra kết luận về cộng đồng rộng lớn hơn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_39_2', 'en-b2-39', 'Cách dùng “cleverness” (n.) — sự thông minh; sự tháo vát; sự khéo léo', 'remarkable cleverness  ·  the cleverness of a design  ·  show cleverness', 'Là danh từ không đếm được; có thể chỉ sự nhanh trí của con người hoặc tính thông minh, sáng tạo trong thiết kế.', 'Họ từ (Word Family): clever (adj.), cleverly (adv.) | Đồng nghĩa: intelligence, ingenuity · Trái nghĩa: stupidity', '[{"hanzi":"Her cleverness helped us fix the tent before sunset.","pinyin":"","meaning":"Sự lanh lợi của cô ấy đã giúp chúng tôi dựng lại chiếc lều trước khi trời tối."},{"hanzi":"The cleverness of a design lies in solving practical problems without introducing unnecessary complexity.","pinyin":"","meaning":"Sự khéo léo của một thiết kế nằm ở chỗ giải quyết được các vấn đề thực tế mà không tạo ra sự phức tạp không cần thiết."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_39_3', 'en-b2-39', 'Cách dùng “wisdom” (n.) — sự khôn ngoan; trí tuệ; sự sáng suốt', 'conventional wisdom  ·  words of wisdom  ·  question the wisdom of', 'Là danh từ không đếm được; knowledge thiên về kiến thức, còn wisdom thiên về năng lực phán đoán và ứng dụng.', 'Họ từ (Word Family): wise (adj.), wisely (adv.), unwise (adj.) | Đồng nghĩa: good judgement, insight · Trái nghĩa: folly, foolishness', '[{"hanzi":"My grandmother shared her wisdom while we cooked together.","pinyin":"","meaning":"Bà tôi chia sẻ những đúc kết sâu sắc của mình trong lúc chúng tôi cùng nhau nấu ăn."},{"hanzi":"The wisdom of expanding road networks is increasingly questioned as cities seek more sustainable transport solutions.","pinyin":"","meaning":"Sự khôn ngoan của việc mở rộng mạng lưới đường bộ ngày càng bị đặt dấu hỏi khi các đô thị tìm kiếm các giải pháp giao thông bền vững hơn."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_39_4', 'en-b2-39', 'Cách dùng “presumably” (adv.) — có lẽ; có thể là; theo như dự đoán', 'presumably because  ·  presumably intended to  ·  presumably true', 'Thể hiện sự phỏng đoán dựa trên cơ sở thực tế, không mang ý nghĩa chắc chắn tuyệt đối như certainly.', 'Họ từ (Word Family): presume (v.), presumption (n.) | Đồng nghĩa: probably, likely', '[{"hanzi":"Her coat is gone, so presumably she has left.","pinyin":"","meaning":"Áo khoác của cô ấy không còn ở đây, có lẽ cô ấy đã đi rồi."},{"hanzi":"More frequent bus services would presumably encourage commuters to leave their cars at home, reducing urban traffic.","pinyin":"","meaning":"Các chuyến xe buýt với tần suất dày đặc hơn có lẽ sẽ khuyến khích người đi làm để xe ở nhà, qua đó làm giảm ùn tắc giao thông đô thị."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_39_1', 'en-b2-39', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_39_1_1', 'ten_b2_39_1', 'limitation', 'The main limitation of this camera is its battery life.', 'The main limitation of this camera is its battery life.', '/ˌlɪmɪˈteɪʃən/', 'Hạn chế chính của chiếc máy ảnh này là thời lượng pin.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_39_1_2', 'ten_b2_39_1', 'hence', 'The oven broke, hence our cold dinner tonight.', 'The oven broke, hence our cold dinner tonight.', '/hens/', 'Lò nướng bị hỏng, vì vậy tối nay chúng ta ăn đồ nguội.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_39_1_3', 'ten_b2_39_1', 'regard', 'I regard this little café as my second home.', 'I regard this little café as my second home.', '/rɪˈɡɑːrd/', 'Tôi xem quán cà phê nhỏ này như ngôi nhà thứ hai của mình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_39_1_4', 'ten_b2_39_1', 'likelihood', 'Dark clouds increased the likelihood of rain this afternoon.', 'Dark clouds increased the likelihood of rain this afternoon.', '/ˈlaɪklihʊd/', 'Những đám mây đen làm tăng khả năng trời sẽ mưa vào chiều nay.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_39_1_5', 'ten_b2_39_1', 'flaw', 'I noticed a tiny flaw in the glass bowl.', 'I noticed a tiny flaw in the glass bowl.', '/flɔː/', 'Tôi nhận thấy có một tì vết nhỏ trên chiếc bát thủy tinh.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_39_1_6', 'ten_b2_39_1', 'closely', 'Look closely at this leaf and notice its tiny veins.', 'Look closely at this leaf and notice its tiny veins.', '/ˈkloʊsli/', 'Hãy quan sát kỹ chiếc lá này và chú ý đến những đường gân nhỏ của nó.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_39_1_7', 'ten_b2_39_1', 'criteria', 'This flat meets all our criteria for a home.', 'This flat meets all our criteria for a home.', '/kraɪˈtɪriə/', 'Căn hộ này đáp ứng tất cả các tiêu chí của chúng tôi về một ngôi nhà.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_39_1_8', 'ten_b2_39_1', 'presumably', 'Her coat is gone, so presumably she has left.', 'Her coat is gone, so presumably she has left.', '/prɪˈzuːməbli/', 'Áo khoác của cô ấy không còn ở đây, có lẽ cô ấy đã đi rồi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_39_1_1', 'en-b2-39', 'ten_b2_39_1', 'listening', 'listening', 'The main limitation of this camera is its battery life.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi ước tính việc sửa chữa sẽ mất khoảng ba ngày.","Hạn chế chính của chiếc máy ảnh này là thời lượng pin.","Chúng tôi đã phân tích các khoản chi tiêu và hủy hai gói đăng ký không dùng đến.","Căn hộ này đáp ứng tất cả các tiêu chí của chúng tôi về một ngôi nhà."]'::jsonb, 1, 'The main limitation of this camera is its battery life. → Hạn chế chính của chiếc máy ảnh này là thời lượng pin.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_39_1_2', 'en-b2-39', 'ten_b2_39_1', 'listening', 'listening', 'The oven broke, hence our cold dinner tonight.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Anh ấy nhìn chằm chằm vào bảng điều khiển xa lạ với vẻ đầy bối rối.","Lò nướng bị hỏng, vì vậy tối nay chúng ta ăn đồ nguội.","Tôi nhận thấy có một tì vết nhỏ trên chiếc bát thủy tinh.","Tôi xem quán cà phê nhỏ này như ngôi nhà thứ hai của mình."]'::jsonb, 1, 'The oven broke, hence our cold dinner tonight. → Lò nướng bị hỏng, vì vậy tối nay chúng ta ăn đồ nguội.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_39_1_3', 'en-b2-39', 'ten_b2_39_1', 'listening', 'listening', 'I regard this little café as my second home.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi nhận thấy có một tì vết nhỏ trên chiếc bát thủy tinh.","Khả năng tìm thấy chìa khóa của tôi ở đây rất thấp.","Cô ấy đã đưa ra một quyết định táo bạo là tự mở tiệm bánh riêng.","Tôi xem quán cà phê nhỏ này như ngôi nhà thứ hai của mình."]'::jsonb, 3, 'I regard this little café as my second home. → Tôi xem quán cà phê nhỏ này như ngôi nhà thứ hai của mình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_39_2', 'en-b2-39', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_39_2_1', 'ten_b2_39_2', 'limitation', 'Researchers should acknowledge the limitations of small samples before drawing conclusions about the wider population.', 'Researchers should acknowledge the limitations of small samples before drawing conclusions about the wider population.', '/ˌlɪmɪˈteɪʃən/', 'Các nhà nghiên cứu nên thừa nhận những hạn chế của các mẫu khảo sát nhỏ trước khi đưa ra kết luận về cộng đồng rộng lớn hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_39_2_2', 'ten_b2_39_2', 'hence', 'Urban populations are growing rapidly; hence, governments need to invest more in reliable public transport.', 'Urban populations are growing rapidly; hence, governments need to invest more in reliable public transport.', '/hens/', 'Dân số đô thị đang tăng nhanh; do đó, chính phủ cần đầu tư nhiều hơn vào hệ thống giao thông công cộng đáng tin cậy.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_39_2_3', 'ten_b2_39_2', 'regard', 'Policymakers increasingly regard access to reliable internet services as essential for equal participation in modern education.', 'Policymakers increasingly regard access to reliable internet services as essential for equal participation in modern education.', '/rɪˈɡɑːrd/', 'Các nhà hoạch định chính sách ngày càng coi việc tiếp cận dịch vụ Internet đáng tin cậy là yếu tố thiết yếu để tham gia bình đẳng vào giáo dục hiện đại.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_39_2_4', 'ten_b2_39_2', 'likelihood', 'Regular physical activity can reduce the likelihood of developing certain health conditions later in life.', 'Regular physical activity can reduce the likelihood of developing certain health conditions later in life.', '/ˈlaɪklihʊd/', 'Hoạt động thể chất thường xuyên có thể làm giảm nguy cơ mắc một số bệnh tật về sau trong cuộc đời.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_39_2_5', 'ten_b2_39_2', 'flaw', 'A major flaw in the research design makes its conclusions about student performance less reliable.', 'A major flaw in the research design makes its conclusions about student performance less reliable.', '/flɔː/', 'Một thiếu sót lớn trong thiết kế nghiên cứu khiến cho các kết luận về hiệuSức học tập của học sinh trở nên kém tin cậy hơn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_39_2_6', 'ten_b2_39_2', 'closely', 'Governments should closely monitor air quality near schools to protect children from the harmful effects of pollution.', 'Governments should closely monitor air quality near schools to protect children from the harmful effects of pollution.', '/ˈkloʊsli/', 'Chính phủ nên giám sát chặt chẽ chất lượng không khí gần các trường học để bảo vệ trẻ em khỏi tác hại của ô nhiễm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_39_2_1', 'en-b2-39', 'ten_b2_39_2', 'listening', 'listening', 'Researchers should acknowledge the limitations of small samples before drawing conclusions about the wider population.', NULL, 'Trong câu vừa nghe, từ “limitation” mang nghĩa nào sau đây?', '["uống ừng ực; nuốt vội vàng","sự phê duyệt; sự cho phép","hiếu khách; niềm nở, chu đáo với khách","hạn chế; thiếu sót"]'::jsonb, 3, '“limitation” (/ˌlɪmɪˈteɪʃən/): hạn chế; thiếu sót. Câu đầy đủ: Researchers should acknowledge the limitations of small samples before drawing conclusions about the wider population.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_39_2_2', 'en-b2-39', 'ten_b2_39_2', 'listening', 'listening', 'Urban populations are growing rapidly; hence, governments need to invest more in reliable public transport.', NULL, 'Trong câu vừa nghe, từ “hence” mang nghĩa nào sau đây?', '["sự khôn ngoan; trí tuệ; sự sáng suốt","dùng một lần; vứt đi sau khi dùng","vượt qua; vượt xe","do đó; vì vậy"]'::jsonb, 3, '“hence” (/hens/): do đó; vì vậy. Câu đầy đủ: Urban populations are growing rapidly; hence, governments need to invest more in reliable public transport.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
