INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_39_9', 'en-b2-39', 'These white shoes are impractical for a muddy walk', 'Đôi giày trắng này không thực tế để đi vào con đường lầy lội.', 'impractical /ɪmˈpræktɪkəl/', '["are","These","for","muddy","walk","impractical","a","white","shoes"]'::jsonb, NULL, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
