INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_39_1', 'en-b2-39', NULL, 'comprehensive_test', 'listening', 'limitation', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["hạn chế; thiếu sót","nhớ lại; hồi tưởng","hạn hán","giữa học kỳ; giữa nhiệm kỳ"]'::jsonb, 0, 'limitation (/ˌlɪmɪˈteɪʃən/) → hạn chế; thiếu sót; sự giới hạn; mức giới hạn', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_39_2', 'en-b2-39', NULL, 'comprehensive_test', 'listening', 'The oven broke, hence our cold dinner tonight.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hãy quan sát kỹ chiếc lá này và chú ý đến những đường gân nhỏ của nó.","Lò nướng bị hỏng, vì vậy tối nay chúng ta ăn đồ nguội.","Hạn chế chính của chiếc máy ảnh này là thời lượng pin.","Tôi chưa bao giờ hiểu được sự khác biệt giữa hai môn thể thao đó."]'::jsonb, 1, 'The oven broke, hence our cold dinner tonight. → Lò nướng bị hỏng, vì vậy tối nay chúng ta ăn đồ nguội.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_39_3', 'en-b2-39', NULL, 'comprehensive_test', 'listening', 'regard', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["làm ngắn lại; rút ngắn; thu ngắn","sự xây dựng; công trình xây dựng","ma sát; lực ma sát","xem là; coi như"]'::jsonb, 3, 'regard (/rɪˈɡɑːrd/) → xem là; coi như; sự tôn trọng; sự quan tâm; lời hỏi thăm; lời chúc', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_39_4', 'en-b2-39', NULL, 'comprehensive_test', 'listening', 'Dark clouds increased the likelihood of rain this afternoon.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một số loại quả đông lạnh rất tốt; chẳng hạn như quả mọng giữ được hương vị của chúng.","Lò nướng bị hỏng, vì vậy tối nay chúng ta ăn đồ nguội.","Tôi nhận thấy có một tì vết nhỏ trên chiếc bát thủy tinh.","Những đám mây đen làm tăng khả năng trời sẽ mưa vào chiều nay."]'::jsonb, 3, 'Dark clouds increased the likelihood of rain this afternoon. → Những đám mây đen làm tăng khả năng trời sẽ mưa vào chiều nay.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_39_5', 'en-b2-39', NULL, 'comprehensive_test', 'listening', 'flaw', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bắt cóc; cướp giữ người trái phép","trưng bày; triển lãm","vùng xung quanh; môi trường xung quanh","lỗi; khiếm khuyết; tì vết"]'::jsonb, 3, 'flaw (/flɔː/) → lỗi; khiếm khuyết; tì vết; làm hỏng; làm kém hoàn hảo', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_39_6', 'en-b2-39', NULL, 'comprehensive_test', 'listening', 'Look closely at this leaf and notice its tiny veins.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bà tôi chia sẻ những đúc kết sâu sắc của mình trong lúc chúng tôi cùng nhau nấu ăn.","Anh ấy nhìn chằm chằm vào bảng điều khiển xa lạ với vẻ đầy bối rối.","Thật vô lý khi lái xe đi khi cửa hàng ở gần như vậy.","Hãy quan sát kỹ chiếc lá này và chú ý đến những đường gân nhỏ của nó."]'::jsonb, 3, 'Look closely at this leaf and notice its tiny veins. → Hãy quan sát kỹ chiếc lá này và chú ý đến những đường gân nhỏ của nó.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_39_7', 'en-b2-39', NULL, 'comprehensive_test', 'listening', 'criteria', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cột mốc quan trọng; bước ngoặt","đấm; thụi","cơn lốc xoáy; vòi rồng","tiêu chuẩn; tiêu chí"]'::jsonb, 3, 'criteria (/kraɪˈtɪriə/) → tiêu chuẩn; tiêu chí', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_39_8', 'en-b2-39', NULL, 'comprehensive_test', 'listening', 'Her coat is gone, so presumably she has left.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Căn hộ này đáp ứng tất cả các tiêu chí của chúng tôi về một ngôi nhà.","Bà tôi chia sẻ những đúc kết sâu sắc của mình trong lúc chúng tôi cùng nhau nấu ăn.","Tôi vẫn nhớ như in mùi hương từ nhà bếp của bà tôi.","Áo khoác của cô ấy không còn ở đây, có lẽ cô ấy đã đi rồi."]'::jsonb, 3, 'Her coat is gone, so presumably she has left. → Áo khoác của cô ấy không còn ở đây, có lẽ cô ấy đã đi rồi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_39_9', 'en-b2-39', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a fault that makes something imperfect or less effective”?', '["absurd","cautious","objective","flaw"]'::jsonb, 3, 'flaw (/flɔː/) → lỗi; khiếm khuyết; tì vết', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_39_10', 'en-b2-39', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “with careful attention to details or changes”?', '["crucial","closely","cautious","pessimistic"]'::jsonb, 1, 'closely (/ˈkloʊsli/) → kỹ lưỡng; tỉ mỉ; chặt chẽ', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_39_11', 'en-b2-39', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Standards used to judge something or make a decision.”?', '["criteria","recommendation","pessimistic","estimate"]'::jsonb, 0, 'criteria (/kraɪˈtɪriə/) → tiêu chuẩn; tiêu chí', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_39_12', 'en-b2-39', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Probably true, based on what is known or reasonably expected.”?', '["presumably","objective","analyse","wisdom"]'::jsonb, 0, 'presumably (/prɪˈzuːməbli/) → có lẽ; có thể là; theo như dự đoán', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
