INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_39_18', 'en-b2-39', NULL, 'comprehensive_test', 'reading', NULL, 'Researchers should acknowledge the limitations of small samples before drawing conclusions about the wider population.', 'Dựa vào câu trên, từ “limitation” có nghĩa phù hợp nhất là gì?', '["đánh giá thấp; coi thường","cơ bản; nền tảng; cốt lõi","bầu; bầu chọn","hạn chế; thiếu sót"]'::jsonb, 3, 'limitation: hạn chế; thiếu sót; sự giới hạn; mức giới hạn. Dịch cả câu: Các nhà nghiên cứu nên thừa nhận những hạn chế của các mẫu khảo sát nhỏ trước khi đưa ra kết luận về cộng đồng rộng lớn hơn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_39_19', 'en-b2-39', NULL, 'comprehensive_test', 'reading', NULL, 'Urban populations are growing rapidly; hence, governments need to invest more in reliable public transport.', 'Dựa vào câu trên, từ “hence” có nghĩa phù hợp nhất là gì?', '["bỏ sót; không chú ý","cư dân; động thực vật sinh sống tại một nơi","thêm; bổ sung; phụ","do đó; vì vậy"]'::jsonb, 3, 'hence: do đó; vì vậy; kể từ nay; sau này. Dịch cả câu: Dân số đô thị đang tăng nhanh; do đó, chính phủ cần đầu tư nhiều hơn vào hệ thống giao thông công cộng đáng tin cậy.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_39_20', 'en-b2-39', NULL, 'comprehensive_test', 'reading', NULL, 'Policymakers increasingly regard access to reliable internet services as essential for equal participation in modern education.', 'Dựa vào câu trên, từ “regard” có nghĩa phù hợp nhất là gì?', '["cơn giận; tính khí; tâm trạng cáu kỉnh","biểu trưng; logo; nhãn hiệu","xem là; coi như","đi lang thang; lang thang không có mục đích cố định"]'::jsonb, 2, 'regard: xem là; coi như; sự tôn trọng; sự quan tâm; lời hỏi thăm; lời chúc. Dịch cả câu: Các nhà hoạch định chính sách ngày càng coi việc tiếp cận dịch vụ Internet đáng tin cậy là yếu tố thiết yếu để tham gia bình đẳng vào giáo dục hiện đại.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_39_21', 'en-b2-39', NULL, 'comprehensive_test', 'reading', NULL, 'Regular physical activity can reduce the likelihood of developing certain health conditions later in life.', 'Dựa vào câu trên, từ “likelihood” có nghĩa phù hợp nhất là gì?', '["tiểu thuyết gia; nhà văn viết tiểu thuyết","tóm tắt; khái quát","khả năng xảy ra","đỉnh núi; đỉnh cao"]'::jsonb, 2, 'likelihood: khả năng xảy ra. Dịch cả câu: Hoạt động thể chất thường xuyên có thể làm giảm nguy cơ mắc một số bệnh tật về sau trong cuộc đời.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_39_22', 'en-b2-39', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự khôn ngoan; trí tuệ; sự sáng suốt”', '["wisdom","extent","recruit","homeless"]'::jsonb, 0, 'sự khôn ngoan; trí tuệ; sự sáng suốt → wisdom (/ˈwɪz.dəm/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_39_23', 'en-b2-39', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bi quan”', '["harm","bravery","graceful","pessimistic"]'::jsonb, 3, 'bi quan → pessimistic (/ˌpesɪˈmɪstɪk/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_39_24', 'en-b2-39', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tối quan trọng; cốt yếu”', '["waving","impact","crucial","grant"]'::jsonb, 2, 'tối quan trọng; cốt yếu → crucial (/ˈkruːʃəl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-40', 'en', 'Bài 40: Tư duy & Nhận thức (7) - CEFR B2', 'CEFR B2', 'B2 · Tư duy', '27 từ vựng Tiếng Anh CEFR B2 chủ đề tư duy & nhận thức kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4040, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_outcome', 'en-b2-40', 'outcome', '/ˈaʊtkʌm/', 'B2', 'kết quả; thành quả', 'n.', NULL, 'Đồng nghĩa: result, consequence', 'Là danh từ đếm được, thường đi với cụm the outcome of để chỉ kết quả của việc gì đó.', 'We were pleased with the outcome of the meeting.', NULL, 'Chúng tôi rất hài lòng với kết quả của cuộc họp.', '{"wordId":"outcome","ukIpa":"/ˈaʊtkʌm/","usIpa":"/ˈaʊtkʌm/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"The final result of an action, event, or process.","vi":"kết quả; thành quả"}],"examples":[{"en":"We were pleased with the outcome of the meeting.","vi":"Chúng tôi rất hài lòng với kết quả của cuộc họp.","audioKind":"ex"},{"en":"Early access to medical care can improve health outcomes for children in disadvantaged communities.","vi":"Việc tiếp cận dịch vụ chăm sóc y tế sớm có thể cải thiện tình trạng sức khỏe cho trẻ em ở các cộng đồng có hoàn cảnh khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"positive outcome","vi":"kết quả tích cực"},{"en":"learning outcomes","vi":"kết quả học tập"},{"en":"health outcomes","vi":"kết quả sức khỏe"},{"en":"likely outcome","vi":"kết quả có khả năng xảy ra"}],"wordFamily":[],"synonyms":["result","consequence"],"antonyms":[],"tipVi":"Là danh từ đếm được, thường đi với cụm the outcome of để chỉ kết quả của việc gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_latter', 'en-b2-40', 'latter', '/ˈlætər/', 'B2', 'cái thứ hai; người thứ hai; điều thứ hai (trong số hai đối tượng đã nhắc tới); sau; phần sau; giai đoạn cuối', 'pron.', NULL, 'Trái nghĩa: former', 'the latter chỉ đối tượng thứ hai trong hai đối tượng, không giống với later.', 'We tried swimming and cycling, but preferred the latter.', NULL, 'Chúng tôi đã thử bơi lội và đạp xe, nhưng thích cái sau hơn.', '{"wordId":"latter","ukIpa":"/ˈlætə/","usIpa":"/ˈlætər/","cefr":"B2","topic":"thinking","senses":[{"pos":"pron.","en":"the second of two people or things already mentioned","vi":"cái thứ hai; người thứ hai; điều thứ hai (trong số hai đối tượng đã nhắc tới)"},{"pos":"adj.","en":"closer to the end of a period or sequence","vi":"sau; phần sau; giai đoạn cuối"}],"examples":[{"en":"We tried swimming and cycling, but preferred the latter.","vi":"Chúng tôi đã thử bơi lội và đạp xe, nhưng thích cái sau hơn.","audioKind":"ex"},{"en":"Although both prevention and treatment deserve funding, healthcare budgets often devote more resources to the latter.","vi":"Mặc dù cả việc phòng ngừa và điều trị đều xứng đáng được cấp vốn, nhưng các ngân sách y tế thường dành nhiều nguồn lực hơn cho vế sau.","audioKind":"ex2"}],"collocations":[{"en":"the former and the latter","vi":"cái trước và cái sau"},{"en":"the latter half","vi":"nửa sau"},{"en":"the latter stages","vi":"các giai đoạn sau"}],"wordFamily":[],"synonyms":[],"antonyms":["former"],"tipVi":"the latter chỉ đối tượng thứ hai trong hai đối tượng, không giống với later.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_simplify', 'en-b2-40', 'simplify', '/ˈsɪmpləfaɪ/', 'B2', 'giản hóa; làm cho đơn giản dễ hiểu hơn', 'v.', 'simple (adj.), simply (adv.), simplification (n.), simplicity (n.)', 'Đồng nghĩa: streamline · Trái nghĩa: complicate', 'Simplify nhấn mạnh việc giảm bớt tính phức tạp; simple là tính từ.', 'Could you simplify these instructions before I start cooking?', NULL, 'Bạn có thể giải thích các hướng dẫn này đơn giản hơn trước khi tôi bắt đầu nấu ăn được không?', '{"wordId":"simplify","ukIpa":"/ˈsɪmplɪfaɪ/","usIpa":"/ˈsɪmpləfaɪ/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"To make something less complicated or easier to understand.","vi":"giản hóa; làm cho đơn giản dễ hiểu hơn"}],"examples":[{"en":"Could you simplify these instructions before I start cooking?","vi":"Bạn có thể giải thích các hướng dẫn này đơn giản hơn trước khi tôi bắt đầu nấu ăn được không?","audioKind":"ex"},{"en":"Governments should simplify application procedures so that small businesses can access financial support more easily.","vi":"Chính phủ nên đơn giản hóa các thủ tục nộp đơn để các doanh nghiệp nhỏ có thể tiếp cận hỗ trợ tài chính dễ dàng hơn.","audioKind":"ex2"}],"collocations":[{"en":"simplify a process","vi":"giản hóa một quy trình"},{"en":"simplify procedures","vi":"đơn giản hóa thủ tục"},{"en":"simplify an explanation","vi":"làm cho lời giải thích dễ hiểu hơn"}],"wordFamily":["simple (adj.)","simply (adv.)","simplification (n.)","simplicity (n.)"],"synonyms":["streamline"],"antonyms":["complicate"],"tipVi":"Simplify nhấn mạnh việc giảm bớt tính phức tạp; simple là tính từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_speculation', 'en-b2-40', 'speculation', '/ˌspekjəˈleɪʃən/', 'B2', 'sự phỏng đoán; sự phỏng đoán không có đủ bằng chứng chắc chắn; hoạt động đầu tư rủi ro nhằm kiếm lời nhanh', 'n.', 'speculate (v.), speculative (adj.), speculator (n.)', 'Đồng nghĩa: conjecture, guesswork', 'Nội dung phỏng đoán thường đi với about hoặc mệnh đề that; cũng có thể chỉ đầu cơ tài chính.', 'The empty shop has sparked speculation among our neighbours.', NULL, 'Cửa hàng trống trơn đó đã khơi mào nhiều lời phỏng đoán trong số những người hàng xóm của chúng tôi.', '{"wordId":"speculation","ukIpa":"/ˌspekjəˈleɪʃən/","usIpa":"/ˌspekjəˈleɪʃən/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"Ideas about something without enough evidence to be certain.","vi":"sự phỏng đoán; sự phỏng đoán không có đủ bằng chứng chắc chắn"},{"pos":"n.","en":"Risky buying and selling intended to produce quick profits.","vi":"hoạt động đầu tư rủi ro nhằm kiếm lời nhanh"}],"examples":[{"en":"The empty shop has sparked speculation among our neighbours.","vi":"Cửa hàng trống trơn đó đã khơi mào nhiều lời phỏng đoán trong số những người hàng xóm của chúng tôi.","audioKind":"ex"},{"en":"Property speculation can drive housing prices beyond local incomes, making it harder for young adults to buy homes.","vi":"Đầu cơ bất động sản có thể đẩy giá nhà vượt quá mức thu nhập của người dân địa phương, khiến những người trẻ tuổi khó mua nhà hơn.","audioKind":"ex2"}],"collocations":[{"en":"pure speculation","vi":"hoàn toàn là phỏng đoán"},{"en":"fuel speculation","vi":"thổi bùng phỏng đoán"},{"en":"speculation about","vi":"sự phỏng đoán về"},{"en":"property speculation","vi":"đầu cơ bất động sản"}],"wordFamily":["speculate (v.)","speculative (adj.)","speculator (n.)"],"synonyms":["conjecture","guesswork"],"antonyms":[],"tipVi":"Nội dung phỏng đoán thường đi với about hoặc mệnh đề that; cũng có thể chỉ đầu cơ tài chính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_supposing', 'en-b2-40', 'supposing', '/səˈpoʊzɪŋ/', 'B2', 'giả sử; giả định', 'conj.', 'suppose (v.), supposition (n.)', 'Đồng nghĩa: if, assuming', 'Tương đương với if, có thể đi kèm mệnh đề that, thường được dùng để đưa ra giả định.', 'Supposing the bus is late, can we walk instead?', NULL, 'Giả sử xe buýt đến muộn, chúng ta có thể đi bộ thay thế được không?', '{"wordId":"supposing","ukIpa":"/səˈpəʊzɪŋ/","usIpa":"/səˈpoʊzɪŋ/","cefr":"B2","topic":"thinking","senses":[{"pos":"conj.","en":"used to introduce an imagined situation or possibility","vi":"giả sử; giả định"}],"examples":[{"en":"Supposing the bus is late, can we walk instead?","vi":"Giả sử xe buýt đến muộn, chúng ta có thể đi bộ thay thế được không?","audioKind":"ex"},{"en":"Supposing that university education became free, how would governments cover the additional costs without reducing other essential services?","vi":"Giả sử giáo dục đại học trở nên miễn phí, chính phủ sẽ làm thế nào để trang trải các chi phí bổ sung mà không cắt giảm các dịch vụ thiết yếu khác?","audioKind":"ex2"}],"collocations":[{"en":"supposing that","vi":"giả sử rằng"},{"en":"supposing we could","vi":"giả sử chúng ta có thể"},{"en":"supposing you were","vi":"giả sử bạn là"}],"wordFamily":["suppose (v.)","supposition (n.)"],"synonyms":["if","assuming"],"antonyms":[],"tipVi":"Tương đương với if, có thể đi kèm mệnh đề that, thường được dùng để đưa ra giả định.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_systematic', 'en-b2-40', 'systematic', '/ˌsɪstəˈmætɪk/', 'B2', 'có hệ thống; có phương pháp', 'adj.', 'system (n.), systematically (adv.), systematise (v.)', 'Đồng nghĩa: methodical, organised · Trái nghĩa: haphazard, random', 'systematic chỉ tính có tổ chức, phương pháp; systemic chỉ tính chất toàn hệ thống.', 'Her systematic packing made everything easy to find later.', NULL, 'Cách sắp xếp hành lý có hệ thống của cô ấy giúp mọi thứ trở nên dễ tìm hơn sau đó.', '{"wordId":"systematic","ukIpa":"/ˌsɪstəˈmætɪk/","usIpa":"/ˌsɪstəˈmætɪk/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"Following an organised plan or method rather than acting randomly.","vi":"có hệ thống; có phương pháp"}],"examples":[{"en":"Her systematic packing made everything easy to find later.","vi":"Cách sắp xếp hành lý có hệ thống của cô ấy giúp mọi thứ trở nên dễ tìm hơn sau đó.","audioKind":"ex"},{"en":"A systematic review of existing research can help governments develop more effective public health policies.","vi":"Một cuộc tổng quan hệ thống về các nghiên cứu hiện có có thể giúp chính phủ xây dựng các chính sách y tế công cộng hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"a systematic approach","vi":"một phương pháp có hệ thống"},{"en":"a systematic review","vi":"một cuộc tổng quan hệ thống"},{"en":"systematic analysis","vi":"phân tích có hệ thống"}],"wordFamily":["system (n.)","systematically (adv.)","systematise (v.)"],"synonyms":["methodical","organised"],"antonyms":["haphazard","random"],"tipVi":"systematic chỉ tính có tổ chức, phương pháp; systemic chỉ tính chất toàn hệ thống.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_destiny', 'en-b2-40', 'destiny', '/ˈdestəni/', 'B2', 'vận mệnh; định mệnh; số phận', 'n.', 'destined (adj.)', 'Đồng nghĩa: fate', 'Thường chỉ tương lai đã được định sẵn; cụm shape your destiny nhấn mạnh việc chủ động làm chủ số phận.', 'She believed it was her destiny to become a musician.', NULL, 'Cô ấy tin rằng trở thành nhạc sĩ chính là định mệnh của mình.', '{"wordId":"destiny","ukIpa":"/ˈdestɪni/","usIpa":"/ˈdestəni/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"A future believed to be fixed by forces beyond personal control.","vi":"vận mệnh; định mệnh; số phận"}],"examples":[{"en":"She believed it was her destiny to become a musician.","vi":"Cô ấy tin rằng trở thành nhạc sĩ chính là định mệnh của mình.","audioKind":"ex"},{"en":"Although family circumstances influence opportunities, education can help individuals shape their own destiny rather than accept existing limitations.","vi":"Mặc dù hoàn cảnh gia đình ảnh hưởng đến cơ hội, giáo dục vẫn có thể giúp mỗi cá nhân tự định hình số phận thay vì chấp nhận những giới hạn sẵn có.","audioKind":"ex2"}],"collocations":[{"en":"shape your own destiny","vi":"tự định hình số phận"},{"en":"fulfil your destiny","vi":"hoàn thành sứ mệnh định mệnh"},{"en":"a sense of destiny","vi":"cảm giác về sứ mệnh"}],"wordFamily":["destined (adj.)"],"synonyms":["fate"],"antonyms":[],"tipVi":"Thường chỉ tương lai đã được định sẵn; cụm shape your destiny nhấn mạnh việc chủ động làm chủ số phận.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_primarily', 'en-b2-40', 'primarily', '/praɪˈmerəli/', 'B2', 'chủ yếu; phần lớn', 'adv.', 'primary (adj.)', 'Đồng nghĩa: mainly, chiefly, principally', 'Thường biểu thị ý nghĩa "chủ yếu", không mang nghĩa chỉ thứ tự thời gian trước sau.', 'I use my tablet primarily for reading books.', NULL, 'Tôi sử dụng máy tính bảng của mình chủ yếu để đọc sách.', '{"wordId":"primarily","ukIpa":"/praɪˈmerəli/","usIpa":"/praɪˈmerəli/","cefr":"B2","topic":"thinking","senses":[{"pos":"adv.","en":"Mainly, or more than anything else","vi":"chủ yếu; phần lớn"}],"examples":[{"en":"I use my tablet primarily for reading books.","vi":"Tôi sử dụng máy tính bảng của mình chủ yếu để đọc sách.","audioKind":"ex"},{"en":"Public transport policies should focus primarily on improving reliability rather than simply reducing ticket prices.","vi":"Các chính sách giao thông công cộng nên chủ yếu tập trung vào việc cải thiện độ tin cậy thay vì chỉ đơn thuần là giảm giá vé.","audioKind":"ex2"}],"collocations":[{"en":"primarily responsible for","vi":"chịu trách nhiệm chính về"},{"en":"primarily concerned with","vi":"chủ yếu quan tâm đến"},{"en":"primarily due to","vi":"chủ yếu là do"}],"wordFamily":["primary (adj.)"],"synonyms":["mainly","chiefly","principally"],"antonyms":[],"tipVi":"Thường biểu thị ý nghĩa \"chủ yếu\", không mang nghĩa chỉ thứ tự thời gian trước sau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_extensive', 'en-b2-40', 'extensive', '/ɪkˈstensɪv/', 'B2', 'rộng rãi; bao quát; lớn; bao phủ diện tích rộng; rộng lớn', 'adj.', 'extensively (adv.), extent (n.), extend (v.), extension (n.)', 'Đồng nghĩa: wide-ranging, broad · Trái nghĩa: limited, restricted', 'Nhấn mạnh phạm vi rộng hoặc số lượng lớn; trong khi intensive nhấn mạnh sự tập trung và cường độ cao.', 'The storm caused extensive damage to our roof.', NULL, 'Cơn bão đã gây ra thiệt hại diện rộng cho mái nhà của chúng tôi.', '{"wordId":"extensive","ukIpa":"/ɪkˈstensɪv/","usIpa":"/ɪkˈstensɪv/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"covering many subjects or involving a large amount","vi":"rộng rãi; bao quát; lớn"},{"pos":"adj.","en":"covering a large physical area","vi":"bao phủ diện tích rộng; rộng lớn"}],"examples":[{"en":"The storm caused extensive damage to our roof.","vi":"Cơn bão đã gây ra thiệt hại diện rộng cho mái nhà của chúng tôi.","audioKind":"ex"},{"en":"Extensive research is needed before governments introduce major changes to the national education system.","vi":"Cần phải có nghiên cứu diện rộng trước khi chính phủ đưa ra những thay đổi lớn đối với hệ thống giáo dục quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"extensive research","vi":"nghiên cứu rộng rãi"},{"en":"extensive damage","vi":"thiệt hại diện rộng"},{"en":"extensive experience","vi":"kinh nghiệm phong phú"},{"en":"extensive network","vi":"mạng lưới rộng khắp"}],"wordFamily":["extensively (adv.)","extent (n.)","extend (v.)","extension (n.)"],"synonyms":["wide-ranging","broad"],"antonyms":["limited","restricted"],"tipVi":"Nhấn mạnh phạm vi rộng hoặc số lượng lớn; trong khi intensive nhấn mạnh sự tập trung và cường độ cao.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prime', 'en-b2-40', 'prime', '/praɪm/', 'B2', 'chính; chủ yếu; hàng đầu; tốt nhất; hoàn hảo nhất; thời kỳ đỉnh cao; thời kỳ sung sức nhất', 'adj.', 'primacy (n.)', 'Đồng nghĩa: main, chief · Trái nghĩa: secondary', 'Cụm a prime example có nghĩa là ví dụ điển hình, chứ không phải là ví dụ đầu tiên.', 'Our prime concern is getting everyone home safely tonight.', NULL, 'Mối quan tâm hàng đầu của chúng tôi là đưa mọi người về nhà an toàn tối nay.', '{"wordId":"prime","ukIpa":"/praɪm/","usIpa":"/praɪm/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"most important or central","vi":"chính; chủ yếu; hàng đầu"},{"pos":"adj.","en":"of the best quality or in the best position","vi":"tốt nhất; hoàn hảo nhất"},{"pos":"n.","en":"the period of greatest strength, success, or ability","vi":"thời kỳ đỉnh cao; thời kỳ sung sức nhất"}],"examples":[{"en":"Our prime concern is getting everyone home safely tonight.","vi":"Mối quan tâm hàng đầu của chúng tôi là đưa mọi người về nhà an toàn tối nay.","audioKind":"ex"},{"en":"Reliable public transport is a prime requirement for cities seeking to reduce dependence on private cars.","vi":"Hệ thống giao thông công cộng đáng tin cậy là yêu cầu hàng đầu đối với các thành phố đang tìm cách giảm sự phụ thuộc vào ô tô cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"prime concern","vi":"mối quan tâm hàng đầu"},{"en":"prime example","vi":"ví dụ điển hình"},{"en":"prime location","vi":"vị trí đắc địa"},{"en":"in your prime","vi":"ở thời kỳ đỉnh cao"}],"wordFamily":["primacy (n.)"],"synonyms":["main","chief"],"antonyms":["secondary"],"tipVi":"Cụm a prime example có nghĩa là ví dụ điển hình, chứ không phải là ví dụ đầu tiên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_context', 'en-b2-40', 'context', '/ˈkɑːntekst/', 'B2', 'bối cảnh; hoàn cảnh xung quanh; ngữ cảnh; văn cảnh', 'n.', 'contextual (adj.), contextualise (v.)', 'Đồng nghĩa: background, circumstances', 'out of context chỉ việc thoát ly ngữ cảnh, thường dùng khi nói về việc trích dẫn sai lệch.', 'Her silence made sense once I understood the context.', NULL, 'Sự im lặng của cô ấy đã trở nên hợp lý ngay khi tôi hiểu được bối cảnh.', '{"wordId":"context","ukIpa":"/ˈkɒntekst/","usIpa":"/ˈkɑːntekst/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"The circumstances surrounding an event that help explain it.","vi":"bối cảnh; hoàn cảnh xung quanh"},{"pos":"n.","en":"The surrounding words that help explain a word or statement.","vi":"ngữ cảnh; văn cảnh"}],"examples":[{"en":"Her silence made sense once I understood the context.","vi":"Sự im lặng của cô ấy đã trở nên hợp lý ngay khi tôi hiểu được bối cảnh.","audioKind":"ex"},{"en":"Historical events should be examined in their social context rather than judged solely by contemporary standards.","vi":"Các sự kiện lịch sử nên được xem xét trong bối cảnh xã hội của chúng thay vì chỉ đánh giá bằng các tiêu chuẩn đương đại.","audioKind":"ex2"}],"collocations":[{"en":"in context","vi":"trong bối cảnh; đặt trong ngữ cảnh"},{"en":"out of context","vi":"đặt ngoài ngữ cảnh; cắt xén khỏi bối cảnh"},{"en":"historical context","vi":"bối cảnh lịch sử"},{"en":"social context","vi":"bối cảnh xã hội"}],"wordFamily":["contextual (adj.)","contextualise (v.)"],"synonyms":["background","circumstances"],"antonyms":[],"tipVi":"out of context chỉ việc thoát ly ngữ cảnh, thường dùng khi nói về việc trích dẫn sai lệch.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_abstract', 'en-b2-40', 'abstract', '/ˈæbstrækt/', 'B2', 'trừu tượng; mang tính nghệ thuật trừu tượng; bản tóm tắt', 'adj.', 'abstraction (n.), abstractly (adv.)', 'Trái nghĩa: concrete', 'Tính từ và danh từ có trọng âm rơi vào âm tiết đầu; động từ có trọng âm rơi vào âm tiết sau.', 'She uses toys to explain abstract ideas to children.', NULL, 'Cô ấy dùng đồ chơi để giải thích các khái niệm trừu tượng cho trẻ nhỏ.', '{"wordId":"abstract","ukIpa":"/ˈæbstrækt/","usIpa":"/ˈæbstrækt/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"relating to ideas rather than physical objects or specific examples","vi":"trừu tượng"},{"pos":"adj.","en":"using shapes and colours rather than realistic images","vi":"mang tính nghệ thuật trừu tượng"},{"pos":"n.","en":"a short summary of a research paper or other document","vi":"bản tóm tắt"}],"examples":[{"en":"She uses toys to explain abstract ideas to children.","vi":"Cô ấy dùng đồ chơi để giải thích các khái niệm trừu tượng cho trẻ nhỏ.","audioKind":"ex"},{"en":"Reading the abstract helps researchers decide whether a study is relevant to their own work.","vi":"Việc đọc phần tóm tắt giúp các nhà nghiên cứu xác định xem một nghiên cứu có liên quan đến công việc của họ hay không.","audioKind":"ex2"}],"collocations":[{"en":"an abstract concept","vi":"một khái niệm trừu tượng"},{"en":"abstract art","vi":"nghệ thuật trừu tượng"},{"en":"abstract thinking","vi":"tư duy trừu tượng"},{"en":"a research abstract","vi":"bản tóm tắt nghiên cứu"}],"wordFamily":["abstraction (n.)","abstractly (adv.)"],"synonyms":[],"antonyms":["concrete"],"tipVi":"Tính từ và danh từ có trọng âm rơi vào âm tiết đầu; động từ có trọng âm rơi vào âm tiết sau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_riddle', 'en-b2-40', 'riddle', '/ˈrɪdl/', 'B2', 'câu đố; điều bí ẩn; điều khó lý giải', 'n.', NULL, 'Đồng nghĩa: puzzle, mystery', 'Đáp án của câu đố dùng answer; giải đố có thể dùng solve a riddle.', 'My cousin asked a riddle that nobody could solve.', NULL, 'Anh họ tôi đố một câu đố mà không ai giải được.', '{"wordId":"riddle","ukIpa":"/ˈrɪdl/","usIpa":"/ˈrɪdl/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"a puzzling question with a clever or unexpected answer","vi":"câu đố"},{"pos":"n.","en":"something mysterious that is difficult to understand or explain","vi":"điều bí ẩn; điều khó lý giải"}],"examples":[{"en":"My cousin asked a riddle that nobody could solve.","vi":"Anh họ tôi đố một câu đố mà không ai giải được.","audioKind":"ex"},{"en":"The sudden disappearance of this ancient settlement remains a riddle despite decades of archaeological research.","vi":"Sự biến mất đột ngột của khu định cư cổ đại này vẫn là một điều bí ẩn bất chấp hàng thập kỷ nghiên cứu khảo cổ học.","audioKind":"ex2"}],"collocations":[{"en":"solve a riddle","vi":"giải đố"},{"en":"pose a riddle","vi":"đặt câu đố"},{"en":"remain a riddle","vi":"vẫn là một điều bí ẩn"}],"wordFamily":[],"synonyms":["puzzle","mystery"],"antonyms":[],"tipVi":"Đáp án của câu đố dùng answer; giải đố có thể dùng solve a riddle.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_complicate', 'en-b2-40', 'complicate', '/ˈkɑːmplɪkeɪt/', 'B2', 'làm cho phức tạp; làm cho khó giải quyết hơn', 'v.', 'complicated (adj.), complication (n.)', 'Trái nghĩa: simplify', 'Là ngoại động từ, theo sau là đối tượng bị làm cho phức tạp.', 'Changing the date now would only complicate our plans.', NULL, 'Việc thay đổi ngày bây giờ sẽ chỉ làm cho kế hoạch của chúng ta thêm rắc rối.', '{"wordId":"complicate","ukIpa":"/ˈkɒmplɪkeɪt/","usIpa":"/ˈkɑːmplɪkeɪt/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"to make something harder to understand or deal with","vi":"làm cho phức tạp; làm cho khó giải quyết hơn"}],"examples":[{"en":"Changing the date now would only complicate our plans.","vi":"Việc thay đổi ngày bây giờ sẽ chỉ làm cho kế hoạch của chúng ta thêm rắc rối.","audioKind":"ex"},{"en":"Unclear regulations can complicate efforts to establish small businesses, particularly in rapidly developing urban areas.","vi":"Các quy định không rõ ràng có thể làm gia tăng độ phức tạp trong việc thành lập các doanh nghiệp nhỏ, đặc biệt là ở các đô thị đang phát triển nhanh chóng.","audioKind":"ex2"}],"collocations":[{"en":"complicate matters","vi":"làm phức tạp vấn đề"},{"en":"complicate the situation","vi":"làm phức tạp tình hình"},{"en":"complicate the process","vi":"làm phức tạp quy trình"}],"wordFamily":["complicated (adj.)","complication (n.)"],"synonyms":[],"antonyms":["simplify"],"tipVi":"Là ngoại động từ, theo sau là đối tượng bị làm cho phức tạp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conscious', 'en-b2-40', 'conscious', '/ˈkɑːnʃəs/', 'B2', 'nhận thức được; có ý thức về; tỉnh táo; có tri giác; có chủ ý; cố ý', 'adj.', 'consciousness (n.), consciously (adv.), unconscious (adj.)', 'Đồng nghĩa: aware, awake, deliberate · Trái nghĩa: unconscious, unaware', 'Nhận thức điều gì dùng be conscious of, đừng nhầm lẫn với conscience.', 'I became conscious of someone standing behind me.', NULL, 'Tôi nhận ra có ai đó đang đứng đằng sau mình.', '{"wordId":"conscious","ukIpa":"/ˈkɒnʃəs/","usIpa":"/ˈkɑːnʃəs/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"aware of something or noticing that it exists","vi":"nhận thức được; có ý thức về"},{"pos":"adj.","en":"awake and able to notice and respond to your surroundings","vi":"tỉnh táo; có tri giác"},{"pos":"adj.","en":"done deliberately rather than automatically","vi":"có chủ ý; cố ý"}],"examples":[{"en":"I became conscious of someone standing behind me.","vi":"Tôi nhận ra có ai đó đang đứng đằng sau mình.","audioKind":"ex"},{"en":"Consumers are increasingly conscious of the environmental impact of their purchases and are choosing more sustainable products.","vi":"Người tiêu dùng ngày càng ý thức rõ hơn về tác động môi trường từ các giao dịch mua sắm của họ và đang lựa chọn những sản phẩm bền vững hơn.","audioKind":"ex2"}],"collocations":[{"en":"conscious of","vi":"nhận thức được"},{"en":"remain conscious","vi":"vẫn giữ được tỉnh táo"},{"en":"a conscious effort","vi":"một nỗ lực có ý thức"},{"en":"a conscious decision","vi":"một quyết định có chủ đích"}],"wordFamily":["consciousness (n.)","consciously (adv.)","unconscious (adj.)"],"synonyms":["aware","awake","deliberate"],"antonyms":["unconscious","unaware"],"tipVi":"Nhận thức điều gì dùng be conscious of, đừng nhầm lẫn với conscience.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_distract', 'en-b2-40', 'distract', '/dɪˈstrækt/', 'B2', 'làm phân tâm; làm xao nhãng', 'v.', 'distraction (n.), distracted (adj.), distracting (adj.)', 'Đồng nghĩa: divert', 'Thường dùng cấu trúc distract sb from sth hoặc doing sth.', 'The music distracted me while I was doing homework.', NULL, 'Tiếng nhạc làm tôi phân tâm trong lúc đang làm bài tập về nhà.', '{"wordId":"distract","ukIpa":"/dɪˈstrækt/","usIpa":"/dɪˈstrækt/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"To draw someone''s attention away from what they are doing","vi":"làm phân tâm; làm xao nhãng"}],"examples":[{"en":"The music distracted me while I was doing homework.","vi":"Tiếng nhạc làm tôi phân tâm trong lúc đang làm bài tập về nhà.","audioKind":"ex"},{"en":"Frequent phone notifications can distract employees from complex tasks and reduce their ability to concentrate for long periods.","vi":"Những thông báo điện thoại liên tục có thể làm nhân viên xao nhãng khỏi các nhiệm vụ phức tạp và làm giảm khả năng tập trung trong thời gian dài.","audioKind":"ex2"}],"collocations":[{"en":"distract someone from","vi":"làm ai đó phân tâm khỏi"},{"en":"distract attention from","vi":"chuyển hướng sự chú ý khỏi"},{"en":"easily distracted","vi":"dễ bị phân tâm"}],"wordFamily":["distraction (n.)","distracted (adj.)","distracting (adj.)"],"synonyms":["divert"],"antonyms":[],"tipVi":"Thường dùng cấu trúc distract sb from sth hoặc doing sth.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_framework', 'en-b2-40', 'framework', '/ˈfreɪmwɜːrk/', 'B2', 'khuôn khổ; hệ thống; khung sườn; cấu trúc', 'n.', NULL, NULL, 'Thường dùng cấu trúc a framework for sth, chỉ khung cơ bản cho việc gì đó.', 'Our coach gave us a framework for planning each workout.', NULL, 'Huấn luyện viên đã cung cấp cho chúng tôi một khung chuẩn để lên kế hoạch cho mỗi buổi tập.', '{"wordId":"framework","ukIpa":"/ˈfreɪmwɜːk/","usIpa":"/ˈfreɪmwɜːrk/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"A basic structure of ideas or rules supporting something","vi":"khuôn khổ; hệ thống"},{"pos":"n.","en":"A supporting structure that gives something its shape","vi":"khung sườn; cấu trúc"}],"examples":[{"en":"Our coach gave us a framework for planning each workout.","vi":"Huấn luyện viên đã cung cấp cho chúng tôi một khung chuẩn để lên kế hoạch cho mỗi buổi tập.","audioKind":"ex"},{"en":"Governments need a clear legal framework to protect personal information collected by online services.","vi":"Các chính phủ cần một khuôn khổ pháp lý rõ ràng để bảo vệ thông tin cá nhân do các dịch vụ trực tuyến thu thập.","audioKind":"ex2"}],"collocations":[{"en":"legal framework","vi":"khuôn khổ pháp lý"},{"en":"theoretical framework","vi":"khung lý thuyết"},{"en":"provide a framework","vi":"cung cấp một khuôn khổ"},{"en":"within the framework of","vi":"trong khuôn khổ của"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng cấu trúc a framework for sth, chỉ khung cơ bản cho việc gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_consequence', 'en-b2-40', 'consequence', '/ˈkɑːnsəkwens/', 'B2', 'kết quả, hậu quả; tầm quan trọng', 'n.', 'consequent (adj.), consequently (adv.), consequential (adj.)', 'Đồng nghĩa: result, outcome', 'as a consequence of đứng trước nguyên nhân, mang nghĩa là "do, vì".', 'Missing the last bus was a consequence of leaving late.', NULL, 'Việc lỡ chuyến xe buýt cuối cùng là hệ quả của việc ra về muộn.', '{"wordId":"consequence","ukIpa":"/ˈkɒnsɪkwəns/","usIpa":"/ˈkɑːnsəkwens/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"Something that happens because of an action or situation.","vi":"kết quả, hậu quả"},{"pos":"n.","en":"The quality of being important or worth considering.","vi":"tầm quan trọng"}],"examples":[{"en":"Missing the last bus was a consequence of leaving late.","vi":"Việc lỡ chuyến xe buýt cuối cùng là hệ quả của việc ra về muộn.","audioKind":"ex"},{"en":"One serious consequence of rapid urban growth is increased pressure on public transport and housing.","vi":"Một hậu quả nghiêm trọng của quá trình đô thị hóa nhanh chóng là áp lực ngày càng tăng đối với hệ thống giao thông công cộng và nhà ở.","audioKind":"ex2"}],"collocations":[{"en":"as a consequence","vi":"do đó, vì vậy"},{"en":"face the consequences","vi":"gánh chịu hậu quả"},{"en":"of little consequence","vi":"không quan trọng, chẳng đáng là bao"}],"wordFamily":["consequent (adj.)","consequently (adv.)","consequential (adj.)"],"synonyms":["result","outcome"],"antonyms":[],"tipVi":"as a consequence of đứng trước nguyên nhân, mang nghĩa là \"do, vì\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_literally', 'en-b2-40', 'literally', '/ˈlɪtərəli/', 'B2', 'theo đúng nghĩa đen; thực sự; hoàn toàn (dùng để nhấn mạnh)', 'adv.', 'literal (adj.)', 'Trái nghĩa: figuratively', 'Văn nói có thể dùng để phóng đại; văn phong trang trọng nên giữ nguyên nghĩa đen hoặc nghĩa thực sự.', 'He took my advice literally and bought a bigger plate.', NULL, 'Anh ấy đã làm theo đúng lời khuyên của tôi và mua một cái đĩa lớn hơn.', '{"wordId":"literally","ukIpa":"/ˈlɪtərəli/","usIpa":"/ˈlɪtərəli/","cefr":"B2","topic":"thinking","senses":[{"pos":"adv.","en":"According to the exact, ordinary meaning of the words.","vi":"theo đúng nghĩa đen"},{"pos":"adv.","en":"Used to stress that something is actually true.","vi":"thực sự; hoàn toàn (dùng để nhấn mạnh)"}],"examples":[{"en":"He took my advice literally and bought a bigger plate.","vi":"Anh ấy đã làm theo đúng lời khuyên của tôi và mua một cái đĩa lớn hơn.","audioKind":"ex"},{"en":"Translating idioms literally can confuse language learners because their meanings often depend on cultural context.","vi":"Việc dịch các thành ngữ theo đúng nghĩa đen có thể làm người học ngoại ngữ bối rối vì ý nghĩa của chúng thường phụ thuộc vào ngữ cảnh văn hóa.","audioKind":"ex2"}],"collocations":[{"en":"take something literally","vi":"hiểu theo đúng nghĩa đen"},{"en":"translate literally","vi":"dịch nghĩa đen"},{"en":"literally true","vi":"thực sự đúng"}],"wordFamily":["literal (adj.)"],"synonyms":[],"antonyms":["figuratively"],"tipVi":"Văn nói có thể dùng để phóng đại; văn phong trang trọng nên giữ nguyên nghĩa đen hoặc nghĩa thực sự.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_viewpoint', 'en-b2-40', 'viewpoint', '/ˈvjuːpɔɪnt/', 'B2', 'quan điểm; góc nhìn; điểm ngắm cảnh', 'n.', 'view (n.)', 'Đồng nghĩa: perspective, standpoint', 'Khi diễn đạt ý "từ góc nhìn của ai đó", hãy dùng cụm từ bắt đầu bằng từ from.', 'Hearing your story helped me understand your viewpoint.', NULL, 'Lắng nghe câu chuyện của bạn đã giúp tôi hiểu được quan điểm của bạn hơn.', '{"wordId":"viewpoint","ukIpa":"/ˈvjuːpɔɪnt/","usIpa":"/ˈvjuːpɔɪnt/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"a particular way of thinking about an issue","vi":"quan điểm; góc nhìn"},{"pos":"n.","en":"a place offering a good view of surrounding scenery","vi":"điểm ngắm cảnh"}],"examples":[{"en":"Hearing your story helped me understand your viewpoint.","vi":"Lắng nghe câu chuyện của bạn đã giúp tôi hiểu được quan điểm của bạn hơn.","audioKind":"ex"},{"en":"Considering an issue from another person''s viewpoint can help communities resolve disagreements more effectively.","vi":"Xem xét một vấn đề từ góc nhìn của người khác có thể giúp các cộng đồng giải quyết bất đồng một cách hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"from my viewpoint","vi":"theo quan điểm của tôi"},{"en":"express a viewpoint","vi":"bày tỏ quan điểm"},{"en":"opposing viewpoints","vi":"các quan điểm trái chiều"}],"wordFamily":["view (n.)"],"synonyms":["perspective","standpoint"],"antonyms":[],"tipVi":"Khi diễn đạt ý \"từ góc nhìn của ai đó\", hãy dùng cụm từ bắt đầu bằng từ from.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_insight', 'en-b2-40', 'insight', '/ˈɪnsaɪt/', 'B2', 'sự thấu hiểu; cái nhìn sâu sắc', 'n.', 'insightful (adj.)', 'Đồng nghĩa: understanding, perception', 'Thường đi với giới từ into; khi chỉ năng lực thấu hiểu chung chung thì thường không đếm được.', 'Helping at the bakery gave me insight into running a business.', NULL, 'Việc phụ giúp ở tiệm bánh đã cho tôi cái nhìn sâu sắc về cách điều hành một doanh nghiệp.', '{"wordId":"insight","ukIpa":"/ˈɪnsaɪt/","usIpa":"/ˈɪnsaɪt/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"a clear, deep understanding of a person or situation","vi":"sự thấu hiểu; cái nhìn sâu sắc"}],"examples":[{"en":"Helping at the bakery gave me insight into running a business.","vi":"Việc phụ giúp ở tiệm bánh đã cho tôi cái nhìn sâu sắc về cách điều hành một doanh nghiệp.","audioKind":"ex"},{"en":"Interviews with local residents provide valuable insight into how urban redevelopment affects community relationships and daily routines.","vi":"Các cuộc phỏng vấn với cư dân địa phương cung cấp góc nhìn sâu sắc có giá trị về cách việc tái phát triển đô thị ảnh hưởng đến mối quan hệ cộng đồng và sinh hoạt hằng ngày.","audioKind":"ex2"}],"collocations":[{"en":"insight into","vi":"sự hiểu biết sâu sắc về"},{"en":"gain insight","vi":"có được cái nhìn sâu sắc"},{"en":"provide insight","vi":"cung cấp góc nhìn sâu sắc"},{"en":"valuable insight","vi":"kiến thức thấu đáo giá trị"}],"wordFamily":["insightful (adj.)"],"synonyms":["understanding","perception"],"antonyms":[],"tipVi":"Thường đi với giới từ into; khi chỉ năng lực thấu hiểu chung chung thì thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_indicate', 'en-b2-40', 'indicate', '/ˈɪndɪkeɪt/', 'B2', 'biểu thị; cho thấy; ra hiệu; chỉ ra; trỏ vào', 'v.', 'indication (n.), indicator (n.), indicative (adj.)', 'Đồng nghĩa: show, signal', 'Khi mang nghĩa "cho thấy rằng", thường đi kèm với mệnh đề bắt đầu bằng that.', 'These dark clouds indicate that rain is coming.', NULL, 'Những đám mây đen này cho thấy trời sắp mưa.', '{"wordId":"indicate","ukIpa":"/ˈɪndɪkeɪt/","usIpa":"/ˈɪndɪkeɪt/","cefr":"B2","topic":"thinking","senses":[{"pos":"v.","en":"to show that something exists or is likely","vi":"biểu thị; cho thấy; ra hiệu"},{"pos":"v.","en":"to direct attention to something, often by pointing","vi":"chỉ ra; trỏ vào"}],"examples":[{"en":"These dark clouds indicate that rain is coming.","vi":"Những đám mây đen này cho thấy trời sắp mưa.","audioKind":"ex"},{"en":"Recent surveys indicate that affordable housing remains a major concern for young adults in urban areas.","vi":"Các cuộc khảo sát gần đây cho thấy nhà ở giá rẻ vẫn là mối quan tâm lớn đối với người trẻ tuổi ở các khu vực đô thị.","audioKind":"ex2"}],"collocations":[{"en":"indicate a need","vi":"cho thấy nhu cầu"},{"en":"clearly indicate","vi":"chỉ rõ"},{"en":"indicate that","vi":"cho thấy rằng"}],"wordFamily":["indication (n.)","indicator (n.)","indicative (adj.)"],"synonyms":["show","signal"],"antonyms":[],"tipVi":"Khi mang nghĩa \"cho thấy rằng\", thường đi kèm với mệnh đề bắt đầu bằng that.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_risky', 'en-b2-40', 'risky', '/ˈrɪski/', 'B2', 'mạo hiểm; rủi ro; nguy hiểm', 'adj.', 'risk (n.), risk (v.), riskiness (n.)', 'Đồng nghĩa: dangerous, hazardous · Trái nghĩa: safe', 'Thường dùng cấu trúc It is risky to do sth để chỉ việc làm gì đó mang tính rủi ro.', 'It is risky to cycle home without lights.', NULL, 'Đạp xe về nhà mà không bật đèn là rất nguy hiểm.', '{"wordId":"risky","ukIpa":"/ˈrɪski/","usIpa":"/ˈrɪski/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"involving a chance of harm, failure, or loss","vi":"mạo hiểm; rủi ro; nguy hiểm"}],"examples":[{"en":"It is risky to cycle home without lights.","vi":"Đạp xe về nhà mà không bật đèn là rất nguy hiểm.","audioKind":"ex"},{"en":"Investing all public funds in a single industry is risky because economic conditions can change unexpectedly.","vi":"Việc đầu tư toàn bộ quỹ công cộng vào một ngành duy nhất là rất rủi ro vì tình hình kinh tế có thể thay đổi bất ngờ.","audioKind":"ex2"}],"collocations":[{"en":"a risky investment","vi":"một khoản đầu tư rủi ro"},{"en":"risky behaviour","vi":"hành vi mạo hiểm"},{"en":"a risky strategy","vi":"chiến lược mạo hiểm"},{"en":"highly risky","vi":"rủi ro rất cao"}],"wordFamily":["risk (n.)","risk (v.)","riskiness (n.)"],"synonyms":["dangerous","hazardous"],"antonyms":["safe"],"tipVi":"Thường dùng cấu trúc It is risky to do sth để chỉ việc làm gì đó mang tính rủi ro.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_curiosity', 'en-b2-40', 'curiosity', '/ˌkjʊriˈɑːsəti/', 'B2', 'sự tò mò; lòng khao khát hiểu biết; vật kỳ lạ; đồ sưu tầm độc lạ', 'n.', 'curious (adj.), curiously (adv.)', 'Đồng nghĩa: inquisitiveness · Trái nghĩa: indifference', 'Khi mang nghĩa sự tò mò thì không đếm được; mang nghĩa vật kỳ lạ thì đếm được.', 'Curiosity led me to open the dusty wooden box.', NULL, 'Sự tò mò đã thúc đẩy tôi mở chiếc hộp gỗ phủ đầy bụi.', '{"wordId":"curiosity","ukIpa":"/ˌkjʊəriˈɒsəti/","usIpa":"/ˌkjʊriˈɑːsəti/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"a strong desire to learn or know about something","vi":"sự tò mò; lòng khao khát hiểu biết"},{"pos":"n.","en":"an unusual object that attracts interest","vi":"vật kỳ lạ; đồ sưu tầm độc lạ"}],"examples":[{"en":"Curiosity led me to open the dusty wooden box.","vi":"Sự tò mò đã thúc đẩy tôi mở chiếc hộp gỗ phủ đầy bụi.","audioKind":"ex"},{"en":"Schools should encourage children''s curiosity by allowing them to investigate questions through practical experiments.","vi":"Nhà trường nên khuyến khích sự tò mò của trẻ em bằng cách cho phép các em tìm hiểu các vấn đề thông qua các thí nghiệm thực tế.","audioKind":"ex2"}],"collocations":[{"en":"arouse curiosity","vi":"khơi gợi sự tò mò"},{"en":"satisfy your curiosity","vi":"thoả mãn sự tò mò của bạn"},{"en":"out of curiosity","vi":"vì tò mò"}],"wordFamily":["curious (adj.)","curiously (adv.)"],"synonyms":["inquisitiveness"],"antonyms":["indifference"],"tipVi":"Khi mang nghĩa sự tò mò thì không đếm được; mang nghĩa vật kỳ lạ thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_motive', 'en-b2-40', 'motive', '/ˈmoʊtɪv/', 'B2', 'động cơ; lý do', 'n.', 'motivate (v.), motivation (n.), motivated (adj.)', 'Đồng nghĩa: reason', 'motive nhấn mạnh nguyên nhân đằngหลัง hành động, thường đi với giới từ for.', 'Her motive for joining was simply to make friends.', NULL, 'Động cơ tham gia của cô ấy đơn giản chỉ là để kết bạn.', '{"wordId":"motive","ukIpa":"/ˈməʊtɪv/","usIpa":"/ˈmoʊtɪv/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"a reason for doing something","vi":"động cơ; lý do"}],"examples":[{"en":"Her motive for joining was simply to make friends.","vi":"Động cơ tham gia của cô ấy đơn giản chỉ là để kết bạn.","audioKind":"ex"},{"en":"Financial security is a major motive for many graduates who choose careers in established companies.","vi":"Sự đảm bảo về tài chính là động cơ chính cho nhiều sinh viên tốt nghiệp khi lựa chọn nghề nghiệp tại các công ty lâu đời.","audioKind":"ex2"}],"collocations":[{"en":"motive for doing something","vi":"động cơ để làm việc gì"},{"en":"underlying motive","vi":"động cơ sâu xa"},{"en":"profit motive","vi":"động cơ lợi nhuận"}],"wordFamily":["motivate (v.)","motivation (n.)","motivated (adj.)"],"synonyms":["reason"],"antonyms":[],"tipVi":"motive nhấn mạnh nguyên nhân đằngหลัง hành động, thường đi với giới từ for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_marvel', 'en-b2-40', 'marvel', '/ˈmɑːrvəl/', 'B2', 'kỳ quan; điều kỳ diệu; kinh ngạc; ngạc nhiên', 'n.', 'marvellous (adj.), marvellously (adv.)', 'Đồng nghĩa: wonder', 'Động từ thường đi với giới từ at; cách viết quá khứ marvelled theo Anh-Anh và marveled theo Anh-Mỹ.', 'We marvelled at the tiny bird''s beautifully woven nest.', NULL, 'Chúng tôi vô cùng kinh ngạc trước chiếc tổ được đan khéo léo của chú chim nhỏ.', '{"wordId":"marvel","ukIpa":"/ˈmɑːvəl/","usIpa":"/ˈmɑːrvəl/","cefr":"B2","topic":"thinking","senses":[{"pos":"n.","en":"Someone or something that causes great admiration or surprise","vi":"kỳ quan; điều kỳ diệu"},{"pos":"v.","en":"To feel great surprise or admiration","vi":"kinh ngạc; ngạc nhiên"}],"examples":[{"en":"We marvelled at the tiny bird''s beautifully woven nest.","vi":"Chúng tôi vô cùng kinh ngạc trước chiếc tổ được đan khéo léo của chú chim nhỏ.","audioKind":"ex"},{"en":"The new bridge is an engineering marvel that connects isolated communities and improves access to essential services.","vi":"Cây cầu mới là một kỳ quan kỹ thuật giúp kết nối các cộng đồng cô lập và cải thiện khả năng tiếp cận các dịch vụ thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"an engineering marvel","vi":"kỳ quan kỹ thuật"},{"en":"a technological marvel","vi":"kỳ quan công nghệ"},{"en":"marvel at","vi":"kinh ngạc trước..."},{"en":"a marvel of nature","vi":"kỳ quan thiên nhiên"}],"wordFamily":["marvellous (adj.)","marvellously (adv.)"],"synonyms":["wonder"],"antonyms":[],"tipVi":"Động từ thường đi với giới từ at; cách viết quá khứ marvelled theo Anh-Anh và marveled theo Anh-Mỹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_straightforward', 'en-b2-40', 'straightforward', '/ˌstreɪtˈfɔːrwərd/', 'B2', 'dễ hiểu, đơn giản, không phức tạp; thẳng thắn, thật thà, trực diện', 'adj.', 'straightforwardly (adv.), straightforwardness (n.)', 'Đồng nghĩa: simple, uncomplicated, direct · Trái nghĩa: complicated, devious', 'Có thể dùng để miêu tả sự việc đơn giản hoặc tính cách con người thẳng thắn.', 'The recipe is straightforward, even for a beginner.', NULL, 'Công thức nấu ăn này rất đơn giản, ngay cả đối với người mới bắt đầu.', '{"wordId":"straightforward","ukIpa":"/ˌstreɪtˈfɔːwəd/","usIpa":"/ˌstreɪtˈfɔːrwərd/","cefr":"B2","topic":"thinking","senses":[{"pos":"adj.","en":"easy to understand or do, without complications","vi":"dễ hiểu, đơn giản, không phức tạp"},{"pos":"adj.","en":"honest and direct in expressing thoughts or intentions","vi":"thẳng thắn, thật thà, trực diện"}],"examples":[{"en":"The recipe is straightforward, even for a beginner.","vi":"Công thức nấu ăn này rất đơn giản, ngay cả đối với người mới bắt đầu.","audioKind":"ex"},{"en":"Governments should make recycling procedures straightforward so that more households can participate without unnecessary confusion.","vi":"Chính phủ nên đơn giản hóa các thủ tục tái chế để nhiều hộ gia đình có thể tham gia mà không gặp phải sự bối rối không cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"a straightforward process","vi":"quy trình đơn giản"},{"en":"a straightforward answer","vi":"câu trả lời thẳng thắn"},{"en":"relatively straightforward","vi":"tương đối đơn giản"},{"en":"straightforward advice","vi":"lời khuyên rõ ràng, dễ hiểu"}],"wordFamily":["straightforwardly (adv.)","straightforwardness (n.)"],"synonyms":["simple","uncomplicated","direct"],"antonyms":["complicated","devious"],"tipVi":"Có thể dùng để miêu tả sự việc đơn giản hoặc tính cách con người thẳng thắn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_40_1', 'en-b2-40', 'Cách dùng “destiny” (n.) — vận mệnh; định mệnh; số phận', 'shape your own destiny  ·  fulfil your destiny  ·  a sense of destiny', 'Thường chỉ tương lai đã được định sẵn; cụm shape your destiny nhấn mạnh việc chủ động làm chủ số phận.', 'Họ từ (Word Family): destined (adj.) | Đồng nghĩa: fate', '[{"hanzi":"She believed it was her destiny to become a musician.","pinyin":"","meaning":"Cô ấy tin rằng trở thành nhạc sĩ chính là định mệnh của mình."},{"hanzi":"Although family circumstances influence opportunities, education can help individuals shape their own destiny rather than accept existing limitations.","pinyin":"","meaning":"Mặc dù hoàn cảnh gia đình ảnh hưởng đến cơ hội, giáo dục vẫn có thể giúp mỗi cá nhân tự định hình số phận thay vì chấp nhận những giới hạn sẵn có."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_40_2', 'en-b2-40', 'Cách dùng “extensive” (adj.) — rộng rãi; bao quát; lớn', 'extensive research  ·  extensive damage  ·  extensive experience', 'Nhấn mạnh phạm vi rộng hoặc số lượng lớn; trong khi intensive nhấn mạnh sự tập trung và cường độ cao.', 'Họ từ (Word Family): extensively (adv.), extent (n.), extend (v.), extension (n.) | Đồng nghĩa: wide-ranging, broad · Trái nghĩa: limited, restricted', '[{"hanzi":"The storm caused extensive damage to our roof.","pinyin":"","meaning":"Cơn bão đã gây ra thiệt hại diện rộng cho mái nhà của chúng tôi."},{"hanzi":"Extensive research is needed before governments introduce major changes to the national education system.","pinyin":"","meaning":"Cần phải có nghiên cứu diện rộng trước khi chính phủ đưa ra những thay đổi lớn đối với hệ thống giáo dục quốc gia."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_40_3', 'en-b2-40', 'Cách dùng “literally” (adv.) — theo đúng nghĩa đen', 'take something literally  ·  translate literally  ·  literally true', 'Văn nói có thể dùng để phóng đại; văn phong trang trọng nên giữ nguyên nghĩa đen hoặc nghĩa thực sự.', 'Họ từ (Word Family): literal (adj.) | Trái nghĩa: figuratively', '[{"hanzi":"He took my advice literally and bought a bigger plate.","pinyin":"","meaning":"Anh ấy đã làm theo đúng lời khuyên của tôi và mua một cái đĩa lớn hơn."},{"hanzi":"Translating idioms literally can confuse language learners because their meanings often depend on cultural context.","pinyin":"","meaning":"Việc dịch các thành ngữ theo đúng nghĩa đen có thể làm người học ngoại ngữ bối rối vì ý nghĩa của chúng thường phụ thuộc vào ngữ cảnh văn hóa."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_40_4', 'en-b2-40', 'Cách dùng “marvel” (n.) — kỳ quan; điều kỳ diệu', 'an engineering marvel  ·  a technological marvel  ·  marvel at', 'Động từ thường đi với giới từ at; cách viết quá khứ marvelled theo Anh-Anh và marveled theo Anh-Mỹ.', 'Họ từ (Word Family): marvellous (adj.), marvellously (adv.) | Đồng nghĩa: wonder', '[{"hanzi":"We marvelled at the tiny bird''s beautifully woven nest.","pinyin":"","meaning":"Chúng tôi vô cùng kinh ngạc trước chiếc tổ được đan khéo léo của chú chim nhỏ."},{"hanzi":"The new bridge is an engineering marvel that connects isolated communities and improves access to essential services.","pinyin":"","meaning":"Cây cầu mới là một kỳ quan kỹ thuật giúp kết nối các cộng đồng cô lập và cải thiện khả năng tiếp cận các dịch vụ thiết yếu."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_40_1', 'en-b2-40', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_40_1_1', 'ten_b2_40_1', 'outcome', 'We were pleased with the outcome of the meeting.', 'We were pleased with the outcome of the meeting.', '/ˈaʊtkʌm/', 'Chúng tôi rất hài lòng với kết quả của cuộc họp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_40_1_2', 'ten_b2_40_1', 'latter', 'We tried swimming and cycling, but preferred the latter.', 'We tried swimming and cycling, but preferred the latter.', '/ˈlætər/', 'Chúng tôi đã thử bơi lội và đạp xe, nhưng thích cái sau hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_40_1_3', 'ten_b2_40_1', 'simplify', 'Could you simplify these instructions before I start cooking?', 'Could you simplify these instructions before I start cooking?', '/ˈsɪmpləfaɪ/', 'Bạn có thể giải thích các hướng dẫn này đơn giản hơn trước khi tôi bắt đầu nấu ăn được không?', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_40_1_4', 'ten_b2_40_1', 'speculation', 'The empty shop has sparked speculation among our neighbours.', 'The empty shop has sparked speculation among our neighbours.', '/ˌspekjəˈleɪʃən/', 'Cửa hàng trống trơn đó đã khơi mào nhiều lời phỏng đoán trong số những người hàng xóm của chúng tôi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_40_1_5', 'ten_b2_40_1', 'supposing', 'Supposing the bus is late, can we walk instead?', 'Supposing the bus is late, can we walk instead?', '/səˈpoʊzɪŋ/', 'Giả sử xe buýt đến muộn, chúng ta có thể đi bộ thay thế được không?', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_40_1_6', 'ten_b2_40_1', 'systematic', 'Her systematic packing made everything easy to find later.', 'Her systematic packing made everything easy to find later.', '/ˌsɪstəˈmætɪk/', 'Cách sắp xếp hành lý có hệ thống của cô ấy giúp mọi thứ trở nên dễ tìm hơn sau đó.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_40_1_7', 'ten_b2_40_1', 'destiny', 'She believed it was her destiny to become a musician.', 'She believed it was her destiny to become a musician.', '/ˈdestəni/', 'Cô ấy tin rằng trở thành nhạc sĩ chính là định mệnh của mình.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_40_1_8', 'ten_b2_40_1', 'primarily', 'I use my tablet primarily for reading books.', 'I use my tablet primarily for reading books.', '/praɪˈmerəli/', 'Tôi sử dụng máy tính bảng của mình chủ yếu để đọc sách.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_40_1_1', 'en-b2-40', 'ten_b2_40_1', 'listening', 'listening', 'We were pleased with the outcome of the meeting.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cách sắp xếp hành lý có hệ thống của cô ấy giúp mọi thứ trở nên dễ tìm hơn sau đó.","Việc thay đổi ngày bây giờ sẽ chỉ làm cho kế hoạch của chúng ta thêm rắc rối.","Chúng tôi rất hài lòng với kết quả của cuộc họp.","Sự im lặng của cô ấy đã trở nên hợp lý ngay khi tôi hiểu được bối cảnh."]'::jsonb, 2, 'We were pleased with the outcome of the meeting. → Chúng tôi rất hài lòng với kết quả của cuộc họp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_40_1_2', 'en-b2-40', 'ten_b2_40_1', 'listening', 'listening', 'We tried swimming and cycling, but preferred the latter.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cách sắp xếp hành lý có hệ thống của cô ấy giúp mọi thứ trở nên dễ tìm hơn sau đó.","Lắng nghe câu chuyện của bạn đã giúp tôi hiểu được quan điểm của bạn hơn.","Chúng tôi đã thử bơi lội và đạp xe, nhưng thích cái sau hơn.","Tiếng nhạc làm tôi phân tâm trong lúc đang làm bài tập về nhà."]'::jsonb, 2, 'We tried swimming and cycling, but preferred the latter. → Chúng tôi đã thử bơi lội và đạp xe, nhưng thích cái sau hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_40_1_3', 'en-b2-40', 'ten_b2_40_1', 'listening', 'listening', 'Could you simplify these instructions before I start cooking?', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Sự tò mò đã thúc đẩy tôi mở chiếc hộp gỗ phủ đầy bụi.","Bạn có thể giải thích các hướng dẫn này đơn giản hơn trước khi tôi bắt đầu nấu ăn được không?","Mối quan tâm hàng đầu của chúng tôi là đưa mọi người về nhà an toàn tối nay.","Chúng tôi rất hài lòng với kết quả của cuộc họp."]'::jsonb, 1, 'Could you simplify these instructions before I start cooking? → Bạn có thể giải thích các hướng dẫn này đơn giản hơn trước khi tôi bắt đầu nấu ăn được không?', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_40_2', 'en-b2-40', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_40_2_1', 'ten_b2_40_2', 'outcome', 'Early access to medical care can improve health outcomes for children in disadvantaged communities.', 'Early access to medical care can improve health outcomes for children in disadvantaged communities.', '/ˈaʊtkʌm/', 'Việc tiếp cận dịch vụ chăm sóc y tế sớm có thể cải thiện tình trạng sức khỏe cho trẻ em ở các cộng đồng có hoàn cảnh khó khăn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_40_2_2', 'ten_b2_40_2', 'latter', 'Although both prevention and treatment deserve funding, healthcare budgets often devote more resources to the latter.', 'Although both prevention and treatment deserve funding, healthcare budgets often devote more resources to the latter.', '/ˈlætər/', 'Mặc dù cả việc phòng ngừa và điều trị đều xứng đáng được cấp vốn, nhưng các ngân sách y tế thường dành nhiều nguồn lực hơn cho vế sau.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_40_2_3', 'ten_b2_40_2', 'simplify', 'Governments should simplify application procedures so that small businesses can access financial support more easily.', 'Governments should simplify application procedures so that small businesses can access financial support more easily.', '/ˈsɪmpləfaɪ/', 'Chính phủ nên đơn giản hóa các thủ tục nộp đơn để các doanh nghiệp nhỏ có thể tiếp cận hỗ trợ tài chính dễ dàng hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_40_2_4', 'ten_b2_40_2', 'speculation', 'Property speculation can drive housing prices beyond local incomes, making it harder for young adults to buy homes.', 'Property speculation can drive housing prices beyond local incomes, making it harder for young adults to buy homes.', '/ˌspekjəˈleɪʃən/', 'Đầu cơ bất động sản có thể đẩy giá nhà vượt quá mức thu nhập của người dân địa phương, khiến những người trẻ tuổi khó mua nhà hơn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_40_2_5', 'ten_b2_40_2', 'supposing', 'Supposing that university education became free, how would governments cover the additional costs without reducing other essential services?', 'Supposing that university education became free, how would governments cover the additional costs without reducing other essential services?', '/səˈpoʊzɪŋ/', 'Giả sử giáo dục đại học trở nên miễn phí, chính phủ sẽ làm thế nào để trang trải các chi phí bổ sung mà không cắt giảm các dịch vụ thiết yếu khác?', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_40_2_6', 'ten_b2_40_2', 'systematic', 'A systematic review of existing research can help governments develop more effective public health policies.', 'A systematic review of existing research can help governments develop more effective public health policies.', '/ˌsɪstəˈmætɪk/', 'Một cuộc tổng quan hệ thống về các nghiên cứu hiện có có thể giúp chính phủ xây dựng các chính sách y tế công cộng hiệu quả hơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_40_2_1', 'en-b2-40', 'ten_b2_40_2', 'listening', 'listening', 'Early access to medical care can improve health outcomes for children in disadvantaged communities.', NULL, 'Trong câu vừa nghe, từ “outcome” mang nghĩa nào sau đây?', '["buồn ngủ; lờ đờ","thực hiện; hoàn thành (nhiệm vụ, lời hứa, thỏa thuận)","kết quả; thành quả","tia lửa; tia điện"]'::jsonb, 2, '“outcome” (/ˈaʊtkʌm/): kết quả; thành quả. Câu đầy đủ: Early access to medical care can improve health outcomes for children in disadvantaged communities.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_40_2_2', 'en-b2-40', 'ten_b2_40_2', 'listening', 'listening', 'Although both prevention and treatment deserve funding, healthcare budgets often devote more resources to the latter.', NULL, 'Trong câu vừa nghe, từ “latter” mang nghĩa nào sau đây?', '["hang ổ; đường hầm (do động vật đào để trú ẩn)","tối đa hóa; tận dụng tối đa","cái thứ hai; người thứ hai; điều thứ hai (trong số hai đối tượng đã nhắc tới)","gây ngứa; bị ngứa"]'::jsonb, 2, '“latter” (/ˈlætər/): cái thứ hai; người thứ hai; điều thứ hai (trong số hai đối tượng đã nhắc tới). Câu đầy đủ: Although both prevention and treatment deserve funding, healthcare budgets often devote more resources to the latter.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_40_1', 'en-b2-40', 'We were pleased with the outcome of the meeting', 'Chúng tôi rất hài lòng với kết quả của cuộc họp.', 'outcome /ˈaʊtkʌm/', '["We","the","of","were","meeting","with","pleased","the","outcome"]'::jsonb, NULL, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_40_2', 'en-b2-40', 'We tried swimming and cycling, but preferred the latter', 'Chúng tôi đã thử bơi lội và đạp xe, nhưng thích cái sau hơn.', 'latter /ˈlætər/', '["preferred","tried","and","We","swimming","latter","but","cycling","the"]'::jsonb, NULL, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
