INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_40_4', 'en-b2-40', 'The empty shop has sparked speculation among our neighbours', 'Cửa hàng trống trơn đó đã khơi mào nhiều lời phỏng đoán trong số những người hàng xóm của chúng tôi.', 'speculation /ˌspekjəˈleɪʃən/', '["sparked","shop","among","empty","The","has","speculation","our","neighbours"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_40_5', 'en-b2-40', 'Supposing the bus is late, can we walk instead', 'Giả sử xe buýt đến muộn, chúng ta có thể đi bộ thay thế được không?', 'supposing /səˈpoʊzɪŋ/', '["Supposing","can","is","bus","we","late","walk","the","instead"]'::jsonb, NULL, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_40_6', 'en-b2-40', 'Her systematic packing made everything easy to find later', 'Cách sắp xếp hành lý có hệ thống của cô ấy giúp mọi thứ trở nên dễ tìm hơn sau đó.', 'systematic /ˌsɪstəˈmætɪk/', '["everything","packing","find","later","systematic","Her","made","to","easy"]'::jsonb, NULL, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_40_7', 'en-b2-40', 'She believed it was her destiny to become a musician', 'Cô ấy tin rằng trở thành nhạc sĩ chính là định mệnh của mình.', 'destiny /ˈdestəni/', '["was","it","believed","become","to","her","She","a","destiny","musician"]'::jsonb, NULL, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_40_8', 'en-b2-40', 'I use my tablet primarily for reading books', 'Tôi sử dụng máy tính bảng của mình chủ yếu để đọc sách.', 'primarily /praɪˈmerəli/', '["reading","for","my","use","tablet","primarily","I","books"]'::jsonb, NULL, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_40_9', 'en-b2-40', 'The storm caused extensive damage to our roof', 'Cơn bão đã gây ra thiệt hại diện rộng cho mái nhà của chúng tôi.', 'extensive /ɪkˈstensɪv/', '["caused","roof","The","storm","our","extensive","damage","to"]'::jsonb, NULL, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
