INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_40_1', 'en-b2-40', NULL, 'comprehensive_test', 'listening', 'outcome', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự tính toán; kết quả tính toán","kết quả; thành quả","quan sát; để ý","sự chôn cất; lễ an táng"]'::jsonb, 1, 'outcome (/ˈaʊtkʌm/) → kết quả; thành quả', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_40_2', 'en-b2-40', NULL, 'comprehensive_test', 'listening', 'We tried swimming and cycling, but preferred the latter.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã thử bơi lội và đạp xe, nhưng thích cái sau hơn.","Mối quan tâm hàng đầu của chúng tôi là đưa mọi người về nhà an toàn tối nay.","Tôi sử dụng máy tính bảng của mình chủ yếu để đọc sách.","Chúng tôi vô cùng kinh ngạc trước chiếc tổ được đan khéo léo của chú chim nhỏ."]'::jsonb, 0, 'We tried swimming and cycling, but preferred the latter. → Chúng tôi đã thử bơi lội và đạp xe, nhưng thích cái sau hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_40_3', 'en-b2-40', NULL, 'comprehensive_test', 'listening', 'simplify', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tài chính; sự cấp vốn; việc thu xếp vốn","nắm vững; tinh thông","đang cầm quyền","giản hóa; làm cho đơn giản dễ hiểu hơn"]'::jsonb, 3, 'simplify (/ˈsɪmpləfaɪ/) → giản hóa; làm cho đơn giản dễ hiểu hơn', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_40_4', 'en-b2-40', NULL, 'comprehensive_test', 'listening', 'The empty shop has sparked speculation among our neighbours.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sự tò mò đã thúc đẩy tôi mở chiếc hộp gỗ phủ đầy bụi.","Việc phụ giúp ở tiệm bánh đã cho tôi cái nhìn sâu sắc về cách điều hành một doanh nghiệp.","Chúng tôi vô cùng kinh ngạc trước chiếc tổ được đan khéo léo của chú chim nhỏ.","Cửa hàng trống trơn đó đã khơi mào nhiều lời phỏng đoán trong số những người hàng xóm của chúng tôi."]'::jsonb, 3, 'The empty shop has sparked speculation among our neighbours. → Cửa hàng trống trơn đó đã khơi mào nhiều lời phỏng đoán trong số những người hàng xóm của chúng tôi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_40_5', 'en-b2-40', NULL, 'comprehensive_test', 'listening', 'supposing', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["người lao động chân tay; công nhân lao động","xe ngựa kéo bốn bánh chở hàng","giả sử; giả định","thiên văn học"]'::jsonb, 2, 'supposing (/səˈpoʊzɪŋ/) → giả sử; giả định', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_40_6', 'en-b2-40', NULL, 'comprehensive_test', 'listening', 'Her systematic packing made everything easy to find later.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Đạp xe về nhà mà không bật đèn là rất nguy hiểm.","Cách sắp xếp hành lý có hệ thống của cô ấy giúp mọi thứ trở nên dễ tìm hơn sau đó.","Lắng nghe câu chuyện của bạn đã giúp tôi hiểu được quan điểm của bạn hơn.","Việc thay đổi ngày bây giờ sẽ chỉ làm cho kế hoạch của chúng ta thêm rắc rối."]'::jsonb, 1, 'Her systematic packing made everything easy to find later. → Cách sắp xếp hành lý có hệ thống của cô ấy giúp mọi thứ trở nên dễ tìm hơn sau đó.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_40_7', 'en-b2-40', NULL, 'comprehensive_test', 'listening', 'destiny', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["hương thơm; mùi thơm dễ chịu","vận mệnh; định mệnh; số phận","súng trường","hàng hóa; sản phẩm bày bán"]'::jsonb, 1, 'destiny (/ˈdestəni/) → vận mệnh; định mệnh; số phận', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_40_8', 'en-b2-40', NULL, 'comprehensive_test', 'listening', 'I use my tablet primarily for reading books.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tiếng nhạc làm tôi phân tâm trong lúc đang làm bài tập về nhà.","Tôi sử dụng máy tính bảng của mình chủ yếu để đọc sách.","Công thức nấu ăn này rất đơn giản, ngay cả đối với người mới bắt đầu.","Động cơ tham gia của cô ấy đơn giản chỉ là để kết bạn."]'::jsonb, 1, 'I use my tablet primarily for reading books. → Tôi sử dụng máy tính bảng của mình chủ yếu để đọc sách.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_40_9', 'en-b2-40', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “used to introduce an imagined situation or possibility”?', '["systematic","extensive","supposing","latter"]'::jsonb, 2, 'supposing (/səˈpoʊzɪŋ/) → giả sử; giả định', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_40_10', 'en-b2-40', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Following an organised plan or method rather than acting randomly.”?', '["insight","systematic","outcome","indicate"]'::jsonb, 1, 'systematic (/ˌsɪstəˈmætɪk/) → có hệ thống; có phương pháp', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_40_11', 'en-b2-40', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A future believed to be fixed by forces beyond personal control.”?', '["straightforward","latter","risky","destiny"]'::jsonb, 3, 'destiny (/ˈdestəni/) → vận mệnh; định mệnh; số phận', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_40_12', 'en-b2-40', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Mainly, or more than anything else”?', '["abstract","complicate","primarily","consequence"]'::jsonb, 2, 'primarily (/praɪˈmerəli/) → chủ yếu; phần lớn', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
