INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_40_18', 'en-b2-40', NULL, 'comprehensive_test', 'reading', NULL, 'Early access to medical care can improve health outcomes for children in disadvantaged communities.', 'Dựa vào câu trên, từ “outcome” có nghĩa phù hợp nhất là gì?', '["duy trì; giữ gìn","kết quả; thành quả","tự do; không bị ràng buộc","sinh sản; gây giống"]'::jsonb, 1, 'outcome: kết quả; thành quả. Dịch cả câu: Việc tiếp cận dịch vụ chăm sóc y tế sớm có thể cải thiện tình trạng sức khỏe cho trẻ em ở các cộng đồng có hoàn cảnh khó khăn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_40_19', 'en-b2-40', NULL, 'comprehensive_test', 'reading', NULL, 'Although both prevention and treatment deserve funding, healthcare budgets often devote more resources to the latter.', 'Dựa vào câu trên, từ “latter” có nghĩa phù hợp nhất là gì?', '["về hướng tây; hướng tây","gây chết người; chí mạng","giàu có; phú quý","cái thứ hai; người thứ hai; điều thứ hai (trong số hai đối tượng đã nhắc tới)"]'::jsonb, 3, 'latter: cái thứ hai; người thứ hai; điều thứ hai (trong số hai đối tượng đã nhắc tới); sau; phần sau; giai đoạn cuối. Dịch cả câu: Mặc dù cả việc phòng ngừa và điều trị đều xứng đáng được cấp vốn, nhưng các ngân sách y tế thường dành nhiều nguồn lực hơn cho vế sau.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_40_20', 'en-b2-40', NULL, 'comprehensive_test', 'reading', NULL, 'Governments should simplify application procedures so that small businesses can access financial support more easily.', 'Dựa vào câu trên, từ “simplify” có nghĩa phù hợp nhất là gì?', '["ánh trăng","giản hóa; làm cho đơn giản dễ hiểu hơn","mồ mả; lăng mộ","con bạch tuộc"]'::jsonb, 1, 'simplify: giản hóa; làm cho đơn giản dễ hiểu hơn. Dịch cả câu: Chính phủ nên đơn giản hóa các thủ tục nộp đơn để các doanh nghiệp nhỏ có thể tiếp cận hỗ trợ tài chính dễ dàng hơn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_40_21', 'en-b2-40', NULL, 'comprehensive_test', 'reading', NULL, 'Property speculation can drive housing prices beyond local incomes, making it harder for young adults to buy homes.', 'Dựa vào câu trên, từ “speculation” có nghĩa phù hợp nhất là gì?', '["sự hài lòng; sự thỏa mãn","súng lục; súng ngắn","sự phỏng đoán; sự phỏng đoán không có đủ bằng chứng chắc chắn","được cho là; theo như người ta nói"]'::jsonb, 2, 'speculation: sự phỏng đoán; sự phỏng đoán không có đủ bằng chứng chắc chắn; hoạt động đầu tư rủi ro nhằm kiếm lời nhanh. Dịch cả câu: Đầu cơ bất động sản có thể đẩy giá nhà vượt quá mức thu nhập của người dân địa phương, khiến những người trẻ tuổi khó mua nhà hơn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_40_22', 'en-b2-40', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “động cơ; lý do”', '["fund-raising","motive","bronze","prospect"]'::jsonb, 1, 'động cơ; lý do → motive (/ˈmoʊtɪv/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_40_23', 'en-b2-40', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “kỳ quan; điều kỳ diệu”', '["punch","marvel","depress","publication"]'::jsonb, 1, 'kỳ quan; điều kỳ diệu → marvel (/ˈmɑːrvəl/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_40_24', 'en-b2-40', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “dễ hiểu, đơn giản, không phức tạp”', '["hesitation","sob","straightforward","majority"]'::jsonb, 2, 'dễ hiểu, đơn giản, không phức tạp → straightforward (/ˌstreɪtˈfɔːrwərd/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-41', 'en', 'Bài 41: Cảm xúc & Tính cách (1) - CEFR B2', 'CEFR B2', 'B2 · Cảm xúc', '24 từ vựng Tiếng Anh CEFR B2 chủ đề cảm xúc & tính cách kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4041, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_touching', 'en-b2-41', 'touching', '/ˈtʌtʃɪŋ/', 'B2', 'cảm động; xúc động; sự chạm; sự sờ (dạng phân từ hiện tại)', 'adj.', 'touch (v.), touched (adj.)', 'Đồng nghĩa: moving, heartwarming', 'Dùng touching để mô tả sự việc gây cảm động; dùng touched để chỉ cảm xúc bị động của con người.', 'Her touching farewell brought tears to my eyes.', NULL, 'Lời chia tay đầy cảm động của cô ấy khiến tôi rớm lệ.', '{"wordId":"touching","ukIpa":"/ˈtʌtʃɪŋ/","usIpa":"/ˈtʌtʃɪŋ/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"making you feel affection, sympathy, or gentle sadness","vi":"cảm động; xúc động"},{"pos":"v.","en":"putting a hand or another body part against something","vi":"sự chạm; sự sờ (dạng phân từ hiện tại)"}],"examples":[{"en":"Her touching farewell brought tears to my eyes.","vi":"Lời chia tay đầy cảm động của cô ấy khiến tôi rớm lệ.","audioKind":"ex"},{"en":"The documentary offers a touching account of volunteers helping older residents overcome loneliness in urban communities.","vi":"Bộ phim tài liệu mang đến một góc nhìn xúc động về các tình nguyện viên giúp đỡ người cao tuổi cô đơn vượt qua sự cô độc trong các cộng đồng đô thị.","audioKind":"ex2"}],"collocations":[{"en":"a touching story","vi":"một câu chuyện cảm động"},{"en":"a touching gesture","vi":"một nghĩa cử ấm lòng"},{"en":"a touching tribute","vi":"một lời tri ân đầy cảm động"}],"wordFamily":["touch (v.)","touched (adj.)"],"synonyms":["moving","heartwarming"],"antonyms":[],"tipVi":"Dùng touching để mô tả sự việc gây cảm động; dùng touched để chỉ cảm xúc bị động của con người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_optimism', 'en-b2-41', 'optimism', '/ˈɑːptɪmɪzəm/', 'B2', 'lòng lạc quan; thái độ lạc quan', 'n.', 'optimist (n.), optimistic (adj.), optimistically (adv.)', 'Đồng nghĩa: hopefulness · Trái nghĩa: pessimism', 'Đây là danh từ không đếm được; cảm giác lạc quan về điều gì dùng optimism about.', 'Her optimism helped us stay cheerful during the storm.', NULL, 'Sự lạc quan của cô ấy đã giúp chúng tôi giữ vững tinh thần vui vẻ trong suốt trận bão.', '{"wordId":"optimism","ukIpa":"/ˈɒptɪmɪzəm/","usIpa":"/ˈɑːptɪmɪzəm/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"The belief that good things will happen.","vi":"lòng lạc quan; thái độ lạc quan"}],"examples":[{"en":"Her optimism helped us stay cheerful during the storm.","vi":"Sự lạc quan của cô ấy đã giúp chúng tôi giữ vững tinh thần vui vẻ trong suốt trận bão.","audioKind":"ex"},{"en":"Despite economic uncertainty, many graduates express optimism about their chances of finding meaningful employment.","vi":"Bất chấp những bất ổn kinh tế, nhiều sinh viên tốt nghiệp vẫn bày tỏ sự lạc quan về cơ hội tìm được việc làm ý nghĩa của họ.","audioKind":"ex2"}],"collocations":[{"en":"cautious optimism","vi":"sự lạc quan thận trọng"},{"en":"optimism about the future","vi":"sự lạc quan về tương lai"},{"en":"grounds for optimism","vi":"cơ sở để lạc quan"}],"wordFamily":["optimist (n.)","optimistic (adj.)","optimistically (adv.)"],"synonyms":["hopefulness"],"antonyms":["pessimism"],"tipVi":"Đây là danh từ không đếm được; cảm giác lạc quan về điều gì dùng optimism about.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_humble', 'en-b2-41', 'humble', '/ˈhʌmbəl/', 'B2', 'khiêm tốn; không tự cao; nhỏ bé; đạm bạc; có địa vị thấp kém; làm cho khiêm nhường; hạ mình', 'adj.', 'humbly (adv.), humility (n.), humbleness (n.)', 'Đồng nghĩa: modest, unassuming · Trái nghĩa: arrogant, conceited', 'Khiêm tốn là humble; đừng nhầm lẫn với từ "súc sinh/làm nhục" là humiliate.', 'Despite winning the prize, she remained humble and thanked everyone.', NULL, 'Mặc dù giành giải thưởng, cô ấy vẫn giữ sự khiêm tốn và gửi lời cảm ơn đến tất cả mọi người.', '{"wordId":"humble","ukIpa":"/ˈhʌmbəl/","usIpa":"/ˈhʌmbəl/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"Not believing or acting as though you are better than others.","vi":"khiêm tốn; không tự cao"},{"pos":"adj.","en":"Simple or low in social position, wealth, or importance.","vi":"nhỏ bé; đạm bạc; có địa vị thấp kém"},{"pos":"v.","en":"To make someone feel less proud or important.","vi":"làm cho khiêm nhường; hạ mình"}],"examples":[{"en":"Despite winning the prize, she remained humble and thanked everyone.","vi":"Mặc dù giành giải thưởng, cô ấy vẫn giữ sự khiêm tốn và gửi lời cảm ơn đến tất cả mọi người.","audioKind":"ex"},{"en":"Effective leaders remain humble enough to acknowledge mistakes and learn from colleagues with different backgrounds and experiences.","vi":"Những nhà lãnh đạo tài ba luôn giữ được sự khiêm tốn cần thiết để thừa nhận sai lầm và học hỏi từ những đồng nghiệp có nền tảng và kinh nghiệm khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"remain humble","vi":"giữ sự khiêm tốn"},{"en":"humble origins","vi":"xuất thân thấp kém"},{"en":"a humble home","vi":"một ngôi nhà đạm bạc"},{"en":"in my humble opinion","vi":"theo ý kiến khiêm nhường của tôi"}],"wordFamily":["humbly (adv.)","humility (n.)","humbleness (n.)"],"synonyms":["modest","unassuming"],"antonyms":["arrogant","conceited"],"tipVi":"Khiêm tốn là humble; đừng nhầm lẫn với từ \"súc sinh/làm nhục\" là humiliate.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hopeful', 'en-b2-41', 'hopeful', '/ˈhoʊpfəl/', 'B2', 'tràn đầy hy vọng; lạc quan; đầy triển vọng; có hy vọng; người có triển vọng thành công', 'adj.', 'hope (n.), hope (v.), hopefully (adv.), hopeless (adj.)', 'Đồng nghĩa: optimistic · Trái nghĩa: hopeless, pessimistic', 'Con người cảm thấy hy vọng dùng hopeful; sự việc có triển vọng dùng promising.', 'She felt hopeful after her first successful driving lesson.', NULL, 'Cô ấy cảm thấy tràn đầy hy vọng sau buổi học lái xe thành công đầu tiên.', '{"wordId":"hopeful","ukIpa":"/ˈhəʊpfəl/","usIpa":"/ˈhoʊpfəl/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"feeling that something good is likely to happen","vi":"tràn đầy hy vọng; lạc quan"},{"pos":"adj.","en":"suggesting that a good result is likely","vi":"đầy triển vọng; có hy vọng"},{"pos":"n.","en":"someone hoping to succeed in a competition or particular career","vi":"người có triển vọng thành công"}],"examples":[{"en":"She felt hopeful after her first successful driving lesson.","vi":"Cô ấy cảm thấy tràn đầy hy vọng sau buổi học lái xe thành công đầu tiên.","audioKind":"ex"},{"en":"Scientists remain hopeful that improved battery technology will make renewable energy more reliable and affordable.","vi":"Các nhà khoa học vẫn nuôi hy vọng rằng công nghệ pin cải tiến sẽ giúp năng lượng tái tạo trở nên đáng tin cậy và có giá cả phải chăng hơn.","audioKind":"ex2"}],"collocations":[{"en":"hopeful about the future","vi":"lạc quan về tương lai"},{"en":"hopeful that","vi":"hy vọng rằng"},{"en":"a hopeful sign","vi":"một dấu hiệu đầy triển vọng"}],"wordFamily":["hope (n.)","hope (v.)","hopefully (adv.)","hopeless (adj.)"],"synonyms":["optimistic"],"antonyms":["hopeless","pessimistic"],"tipVi":"Con người cảm thấy hy vọng dùng hopeful; sự việc có triển vọng dùng promising.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_astonishment', 'en-b2-41', 'astonishment', '/əˈstɑːnɪʃmənt/', 'B2', 'sự kinh ngạc, sự ngạc nhiên tột độ', 'n.', 'astonish (v.), astonished (adj.), astonishing (adj.), astonishingly (adv.)', 'Đồng nghĩa: amazement, surprise', 'Thường là danh từ không đếm được; cụm từ "to one''s astonishment" có nghĩa là làm cho ai đó ngạc nhiên.', 'He stared in astonishment as the tiny seedling flowered.', NULL, 'Cậu ấy trân trân nhìn trong sự ngạc nhiên khi cây non bé xíu bắt đầu trổ hoa.', '{"wordId":"astonishment","ukIpa":"/əˈstɒnɪʃmənt/","usIpa":"/əˈstɑːnɪʃmənt/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"a feeling of very great surprise","vi":"sự kinh ngạc, sự ngạc nhiên tột độ"}],"examples":[{"en":"He stared in astonishment as the tiny seedling flowered.","vi":"Cậu ấy trân trân nhìn trong sự ngạc nhiên khi cây non bé xíu bắt đầu trổ hoa.","audioKind":"ex"},{"en":"The speed of technological change often causes astonishment, particularly among people who remember life before widespread internet access.","vi":"Tốc độ thay đổi công nghệ thường gây ra sự kinh ngạc, đặc biệt là ở những người còn nhớ cuộc sống trước khi internet phổ biến rộng rãi.","audioKind":"ex2"}],"collocations":[{"en":"in astonishment","vi":"trong sự ngạc nhiên"},{"en":"to someone''s astonishment","vi":"làm ai đó kinh ngạc"},{"en":"express astonishment","vi":"bộc lộ sự ngạc nhiên"}],"wordFamily":["astonish (v.)","astonished (adj.)","astonishing (adj.)","astonishingly (adv.)"],"synonyms":["amazement","surprise"],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; cụm từ \"to one''s astonishment\" có nghĩa là làm cho ai đó ngạc nhiên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hopeless', 'en-b2-41', 'hopeless', '/ˈhoʊpləs/', 'B2', 'tuyệt vọng; không có hy vọng; kém cỏi; cực kỳ dốt', 'adj.', 'hope (n.), hopeful (adj.), hopelessly (adv.), hopelessness (n.)', 'Đồng nghĩa: despairing, futile · Trái nghĩa: hopeful', 'Cấu trúc "kém làm việc gì" sử dụng hopeless at doing.', 'The situation seemed hopeless until our neighbours offered help.', NULL, 'Tình hình tưởng chừng như vô vọng cho đến khi những người hàng xóm đến giúp đỡ.', '{"wordId":"hopeless","ukIpa":"/ˈhəʊpləs/","usIpa":"/ˈhoʊpləs/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"Having no hope, or offering no chance of success.","vi":"tuyệt vọng; không có hy vọng"},{"pos":"adj.","en":"Very bad at doing something.","vi":"kém cỏi; cực kỳ dốt"}],"examples":[{"en":"The situation seemed hopeless until our neighbours offered help.","vi":"Tình hình tưởng chừng như vô vọng cho đến khi những người hàng xóm đến giúp đỡ.","audioKind":"ex"},{"en":"Students who feel hopeless about their academic progress may benefit from individual guidance and achievable learning goals.","vi":"Những học sinh cảm thấy tuyệt vọng về tiến1 bộ học tập của mình có thể sẽ nhận được nhiều lợi ích từ việc hướng dẫn cá nhân và các mục tiêu học tập khả thi.","audioKind":"ex2"}],"collocations":[{"en":"a hopeless situation","vi":"một hoàn cảnh vô vọng"},{"en":"feel hopeless","vi":"cảm thấy tuyệt vọng"},{"en":"hopeless at cooking","vi":"kém nấu nướng; vô vọng trong việc nấu ăn"},{"en":"a hopeless case","vi":"một trường hợp vô phương cứu chữa"}],"wordFamily":["hope (n.)","hopeful (adj.)","hopelessly (adv.)","hopelessness (n.)"],"synonyms":["despairing","futile"],"antonyms":["hopeful"],"tipVi":"Cấu trúc \"kém làm việc gì\" sử dụng hopeless at doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_affection', 'en-b2-41', 'affection', '/əˈfekʃən/', 'B2', 'sự âu yếm; lòng quý mến; tình cảm', 'n.', 'affectionate (adj.), affectionately (adv.)', 'Đồng nghĩa: fondness, love · Trái nghĩa: hatred', 'Thường không đếm được; tình cảm dành cho ai đó dùng affection for.', 'Our cat shows affection by rubbing against our legs.', NULL, 'Con mèo nhà chúng tôi thể hiện sự quấn quýt bằng cách cọ vào chân chúng tôi.', '{"wordId":"affection","ukIpa":"/əˈfekʃən/","usIpa":"/əˈfekʃən/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"A warm feeling of love or fondness for someone or something.","vi":"sự âu yếm; lòng quý mến; tình cảm"}],"examples":[{"en":"Our cat shows affection by rubbing against our legs.","vi":"Con mèo nhà chúng tôi thể hiện sự quấn quýt bằng cách cọ vào chân chúng tôi.","audioKind":"ex"},{"en":"Children who receive consistent affection from caregivers often develop greater emotional security and stronger social relationships.","vi":"Trẻ em nhận được tìnhxCảm ân cần và nhất quán từ người chăm sóc thường có sự an toàn về cảm xúc lớn hơn và mối quan hệ xã hội bền chặt hơn.","audioKind":"ex2"}],"collocations":[{"en":"show affection","vi":"thể hiện tình cảm"},{"en":"deep affection for","vi":"tình cảm sâu sắc dành cho"},{"en":"a sign of affection","vi":"dấu hiệu của sự quý mến"}],"wordFamily":["affectionate (adj.)","affectionately (adv.)"],"synonyms":["fondness","love"],"antonyms":["hatred"],"tipVi":"Thường không đếm được; tình cảm dành cho ai đó dùng affection for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sob', 'en-b2-41', 'sob', '/sɑːb/', 'B2', 'nức nở; sụt sùi; khóc nức nở; tiếng nức nở; tiếng sụt sùi', 'v.', 'sobbing (n.)', 'Đồng nghĩa: cry, weep', 'Quá khứ sobbed, tiếp diễn sobbing, đều gấp đôi chữ b.', 'The child began to sob after losing her toy.', NULL, 'Đứa trẻ bắt đầu nức nở sau khi làm mất món đồ chơi của mình.', '{"wordId":"sob","ukIpa":"/sɒb/","usIpa":"/sɑːb/","cefr":"B2","topic":"emotion","senses":[{"pos":"v.","en":"to cry with short, sudden breaths","vi":"nức nở; sụt sùi; khóc nức nở"},{"pos":"n.","en":"a short, broken breath or sound made while crying","vi":"tiếng nức nở; tiếng sụt sùi"}],"examples":[{"en":"The child began to sob after losing her toy.","vi":"Đứa trẻ bắt đầu nức nở sau khi làm mất món đồ chơi của mình.","audioKind":"ex"},{"en":"Children may sob when separated from caregivers, so schools should provide gentle support during transitions.","vi":"Trẻ nhỏ có thể nức nở khi phải rời xa người chăm sóc, vì vậy nhà trường nên cung cấp sự hỗ trợ ân cần trong giai đoạn chuyển giao.","audioKind":"ex2"}],"collocations":[{"en":"sob quietly","vi":"nức nở khẽ khàng"},{"en":"uncontrollable sobs","vi":"tiếng khóc nức nở không kìm nén được"},{"en":"between sobs","vi":"giữa những tiếng nức nở"}],"wordFamily":["sobbing (n.)"],"synonyms":["cry","weep"],"antonyms":[],"tipVi":"Quá khứ sobbed, tiếp diễn sobbing, đều gấp đôi chữ b.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_terror', 'en-b2-41', 'terror', '/ˈterər/', 'B2', 'sự kinh hãi; nỗi sợ hãi tột cùng; sự khủng bố; thủ đoạn khủng bố', 'n.', 'terrify (v.), terrified (adj.), terrifying (adj.), terrorism (n.)', 'Đồng nghĩa: horror, dread', 'Diễn tả nỗi sợ vô cùng mạnh mẽ, mức độ sâu sắc hơn từ fear; thường là danh từ không đếm được.', 'She woke in terror after dreaming about a falling lift.', NULL, 'Cô ấy bừng tỉnh trong nỗi sợ hãi tột độ sau khi mơ thấy thang máy rơi.', '{"wordId":"terror","ukIpa":"/ˈterə/","usIpa":"/ˈterər/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"An extremely strong feeling of fear.","vi":"sự kinh hãi; nỗi sợ hãi tột cùng"},{"pos":"n.","en":"Violence or threats used to frighten and control people.","vi":"sự khủng bố; thủ đoạn khủng bố"}],"examples":[{"en":"She woke in terror after dreaming about a falling lift.","vi":"Cô ấy bừng tỉnh trong nỗi sợ hãi tột độ sau khi mơ thấy thang máy rơi.","audioKind":"ex"},{"en":"Responsible news reporting should inform the public about threats without spreading unnecessary terror among communities.","vi":"Các bản tin báo chí có trách nhiệm nên thông báo cho công chúng về các mối đe dọa mà không gây ra sự hoảng loạn không cần thiết trong cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"in terror","vi":"trong cơn hoảng sợ"},{"en":"sheer terror","vi":"nỗi sợ tột độ"},{"en":"a sense of terror","vi":"cảm giác kinh hãi"},{"en":"a campaign of terror","vi":"chiến dịch khủng bố"}],"wordFamily":["terrify (v.)","terrified (adj.)","terrifying (adj.)","terrorism (n.)"],"synonyms":["horror","dread"],"antonyms":[],"tipVi":"Diễn tả nỗi sợ vô cùng mạnh mẽ, mức độ sâu sắc hơn từ fear; thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hesitation', 'en-b2-41', 'hesitation', '/ˌhezɪˈteɪʃən/', 'B2', 'sự do dự; sự ngập ngừng; sự chần chừ', 'n.', 'hesitate (v), hesitant (adj), hesitantly (adv)', 'Đồng nghĩa: indecision, reluctance · Trái nghĩa: decisiveness', 'Cấu trúc không ngần ngại làm gì: have no hesitation in doing.', 'After a moment of hesitation, Lina knocked on the door.', NULL, 'Sau một phút do dự, Lina đã gõ cửa.', '{"wordId":"hesitation","ukIpa":"/ˌhezɪˈteɪʃən/","usIpa":"/ˌhezɪˈteɪʃən/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"A pause or delay caused by uncertainty or nervousness.","vi":"sự do dự; sự ngập ngừng; sự chần chừ"}],"examples":[{"en":"After a moment of hesitation, Lina knocked on the door.","vi":"Sau một phút do dự, Lina đã gõ cửa.","audioKind":"ex"},{"en":"Some students show hesitation when speaking a foreign language because they fear making mistakes in front of classmates.","vi":"Một số học sinh tỏ ra ngập ngừng khi nói ngoại ngữ vì các em sợ mắc lỗi trước mặt bạn bè.","audioKind":"ex2"}],"collocations":[{"en":"without hesitation","vi":"không chút do dự"},{"en":"a moment''s hesitation","vi":"một khoảnh khắc do dự"},{"en":"have no hesitation in doing","vi":"không ngần ngại làm điều gì"}],"wordFamily":["hesitate (v)","hesitant (adj)","hesitantly (adv)"],"synonyms":["indecision","reluctance"],"antonyms":["decisiveness"],"tipVi":"Cấu trúc không ngần ngại làm gì: have no hesitation in doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dissatisfaction', 'en-b2-41', 'dissatisfaction', '/ˌdɪsˌsætɪsˈfækʃən/', 'B2', 'sự bất mãn; sự không hài lòng', 'n.', 'dissatisfied (adj.), satisfaction (n.), satisfy (v.)', 'Đồng nghĩa: discontent, displeasure · Trái nghĩa: satisfaction, contentment', 'Thường là danh từ không đếm được; khi nói không hài lòng với việc gì dùng dissatisfaction with.', 'He expressed his dissatisfaction with the cold meal politely.', NULL, 'Anh ấy đã lịch sự bày tỏ sự không hài lòng với bữa ăn nguội ngắt.', '{"wordId":"dissatisfaction","ukIpa":"/ˌdɪsˌsætɪsˈfækʃən/","usIpa":"/ˌdɪsˌsætɪsˈfækʃən/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"the feeling that something is not as good as expected","vi":"sự bất mãn; sự không hài lòng"}],"examples":[{"en":"He expressed his dissatisfaction with the cold meal politely.","vi":"Anh ấy đã lịch sự bày tỏ sự không hài lòng với bữa ăn nguội ngắt.","audioKind":"ex"},{"en":"Growing dissatisfaction with public transport has encouraged local authorities to review bus routes and fares.","vi":"Sự bất mãn ngày càng lớn đối với hệ thống giao thông công cộng đã thúc đẩy các cơ quan chức năng địa phương xem xét lại các tuyến xe buýt và giá vé.","audioKind":"ex2"}],"collocations":[{"en":"dissatisfaction with","vi":"sự bất mãn với"},{"en":"express dissatisfaction","vi":"bày tỏ sự không hài lòng"},{"en":"widespread dissatisfaction","vi":"sự bất mãn lan rộng"},{"en":"job dissatisfaction","vi":"sự bất mãn trong công việc"}],"wordFamily":["dissatisfied (adj.)","satisfaction (n.)","satisfy (v.)"],"synonyms":["discontent","displeasure"],"antonyms":["satisfaction","contentment"],"tipVi":"Thường là danh từ không đếm được; khi nói không hài lòng với việc gì dùng dissatisfaction with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_delightful', 'en-b2-41', 'delightful', '/dɪˈlaɪtfəl/', 'B2', 'vui vẻ; thú vị; dễ chịu', 'adj.', 'delight (n.), delight (v.), delighted (adj.), delightfully (adv.)', 'Đồng nghĩa: charming, lovely, enjoyable · Trái nghĩa: unpleasant', 'delightful mô tả thứ mang lại niềm vui; delighted chỉ cảm giác vui sướng của bản thân.', 'We found a delightful little café beside the river.', NULL, 'Chúng tôi đã tìm thấy một quán cà phê nhỏ rất dễ chịu nằm bên bờ sông.', '{"wordId":"delightful","ukIpa":"/dɪˈlaɪtfəl/","usIpa":"/dɪˈlaɪtfəl/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"very pleasant, enjoyable, or charming","vi":"vui vẻ; thú vị; dễ chịu"}],"examples":[{"en":"We found a delightful little café beside the river.","vi":"Chúng tôi đã tìm thấy một quán cà phê nhỏ rất dễ chịu nằm bên bờ sông.","audioKind":"ex"},{"en":"Well-designed public gardens offer delightful spaces where residents can relax and develop stronger connections with their neighbourhood.","vi":"Các khu vườn công cộng được thiết kế đẹp mắt mang đến không gian thư giãn tuyệt vời, giúp cư dân gắn kết hơn với khu phố của mình.","audioKind":"ex2"}],"collocations":[{"en":"a delightful experience","vi":"một trải nghiệm thú vị"},{"en":"a delightful surprise","vi":"một bất ngờ thú vị"},{"en":"a delightful place","vi":"một nơi tuyệt vời"}],"wordFamily":["delight (n.)","delight (v.)","delighted (adj.)","delightfully (adv.)"],"synonyms":["charming","lovely","enjoyable"],"antonyms":["unpleasant"],"tipVi":"delightful mô tả thứ mang lại niềm vui; delighted chỉ cảm giác vui sướng của bản thân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disturbing', 'en-b2-41', 'disturbing', '/dɪˈstɜːrbɪŋ/', 'B2', 'gây lo âu; làm bồn chồn; đáng lo ngại', 'adj.', 'disturb (v.), disturbed (adj.), disturbance (n.)', 'Đồng nghĩa: unsettling, worrying, troubling · Trái nghĩa: reassuring', 'disturbing chỉ sự vật gây bất an; disturbed chỉ cảm giác bất an của con người.', 'We heard some disturbing news about the nearby forest.', NULL, 'Chúng tôi nghe được một số tin tức đáng lo ngại về khu rừng gần đó.', '{"wordId":"disturbing","ukIpa":"/dɪˈstɜːbɪŋ/","usIpa":"/dɪˈstɜːrbɪŋ/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"Making someone feel worried, upset, or uncomfortable.","vi":"gây lo âu; làm bồn chồn; đáng lo ngại"}],"examples":[{"en":"We heard some disturbing news about the nearby forest.","vi":"Chúng tôi nghe được một số tin tức đáng lo ngại về khu rừng gần đó.","audioKind":"ex"},{"en":"The survey revealed a disturbing increase in the number of young people experiencing severe stress.","vi":"Cuộc khảo sát cho thấy một sự gia tăng đáng lo ngại về số lượng thanh thiếu niên đang phải chịu đựng áp lực tâm lý nặng nề.","audioKind":"ex2"}],"collocations":[{"en":"disturbing news","vi":"tin tức gây bất an"},{"en":"a disturbing trend","vi":"một xu hướng đáng lo ngại"},{"en":"deeply disturbing","vi":"hết sức đáng lo ngại"}],"wordFamily":["disturb (v.)","disturbed (adj.)","disturbance (n.)"],"synonyms":["unsettling","worrying","troubling"],"antonyms":["reassuring"],"tipVi":"disturbing chỉ sự vật gây bất an; disturbed chỉ cảm giác bất an của con người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_damn', 'en-b2-41', 'damn', '/dæm/', 'B2', 'chỉ trích gay gắt; phê phán mạnh mẽ; thôi chết; khỉ thật (thể hiện sự bực bội, thất vọng); khỉ gió; chết tiệt (dùng để nhấn mạnh sự khó chịu)', 'v.', 'damning (adj.), damned (adj.), damnation (n.)', 'Đồng nghĩa: condemn, denounce · Trái nghĩa: praise', 'Mang sắc thái hơi thô tục; trong văn viết trang trọng nên dùng condemn.', 'The critics damned the play for its weak ending.', NULL, 'Các nhà phê bình đã chê bai thậm tệ vở kịch vì phần kết quá yếu.', '{"wordId":"damn","ukIpa":"/dæm/","usIpa":"/dæm/","cefr":"B2","topic":"emotion","senses":[{"pos":"v.","en":"To criticize someone or something very strongly.","vi":"chỉ trích gay gắt; phê phán mạnh mẽ"},{"pos":"int.","en":"An expression of anger, frustration, or disappointment.","vi":"thôi chết; khỉ thật (thể hiện sự bực bội, thất vọng)"},{"pos":"adj.","en":"Used to emphasize annoyance about something.","vi":"khỉ gió; chết tiệt (dùng để nhấn mạnh sự khó chịu)"}],"examples":[{"en":"The critics damned the play for its weak ending.","vi":"Các nhà phê bình đã chê bai thậm tệ vở kịch vì phần kết quá yếu.","audioKind":"ex"},{"en":"Campaigners damned the proposal because it offered little protection for wildlife threatened by further industrial development.","vi":"Những nhà vận động đã lên án mạnh mẽ bản đề xuất vì nó mang lại rất ít sự bảo vệ cho động vật hoang dã trước các nguy cơ phát triển công nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"damn with faint praise","vi":"chê bai một cách mỉa mai"},{"en":"damn it","vi":"mặc thây nó; chết tiệt"},{"en":"a damn nuisance","vi":"một rắc rối phiền toái"}],"wordFamily":["damning (adj.)","damned (adj.)","damnation (n.)"],"synonyms":["condemn","denounce"],"antonyms":["praise"],"tipVi":"Mang sắc thái hơi thô tục; trong văn viết trang trọng nên dùng condemn.","noteVi":"Từ cảm thán và cách dùng mang tính cường điệu có chứa yếu tố xúc phạm nhẹ, cần cẩn trọng trong các tình huống trang trọng.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_utter', 'en-b2-41', 'utter', '/ˈʌtər/', 'B2', 'hoàn toàn; tuyệt đối; thốt ra; phát ra âm thanh', 'adj.', 'utterly (adv.), utterance (n.)', 'Đồng nghĩa: complete, total', 'Tính từ utter chỉ đứng trước danh từ; trạng từ tương ứng là utterly.', 'The kitchen was in utter chaos after we baked.', NULL, 'Căn bếp trở nên hỗn loạn hoàn toàn sau khi chúng tôi làm bánh.', '{"wordId":"utter","ukIpa":"/ˈʌtə/","usIpa":"/ˈʌtər/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"Complete or total, used to emphasise something","vi":"hoàn toàn; tuyệt đối"},{"pos":"v.","en":"To say something or make a sound with your voice","vi":"thốt ra; phát ra âm thanh"}],"examples":[{"en":"The kitchen was in utter chaos after we baked.","vi":"Căn bếp trở nên hỗn loạn hoàn toàn sau khi chúng tôi làm bánh.","audioKind":"ex"},{"en":"Without adequate planning, rapid urban expansion can result in utter confusion over land ownership and infrastructure responsibilities.","vi":"Nếu thiếu quy hoạch thỏa đáng, sự bành trướng đô thị nhanh chóng có thể dẫn đến tình trạng hỗn loạn hoàn toàn về quyền sở hữu đất đai và trách nhiệm hạ tầng.","audioKind":"ex2"}],"collocations":[{"en":"utter chaos","vi":"hỗn loạn hoàn toàn"},{"en":"utter disbelief","vi":"hoàn toàn hoài nghi"},{"en":"utter a word","vi":"thốt ra một lời"},{"en":"utter a sound","vi":"phát ra một tiếng động"}],"wordFamily":["utterly (adv.)","utterance (n.)"],"synonyms":["complete","total"],"antonyms":[],"tipVi":"Tính từ utter chỉ đứng trước danh từ; trạng từ tương ứng là utterly.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gratitude', 'en-b2-41', 'gratitude', '/ˈɡrætɪtuːd/', 'B2', 'lòng biết ơn; sự cảm kích', 'n.', 'grateful (adj.), gratefully (adv.), ingratitude (n.)', 'Đồng nghĩa: thankfulness, appreciation · Trái nghĩa: ingratitude', 'Lòng biết ơn đối với ai dùng gratitude to, biết ơn vì điều gì dùng gratitude for; thường là danh từ không đếm được.', 'She brought fresh flowers to express her gratitude.', NULL, 'Cô ấy mang hoa tươi đến để bày tỏ sự biết ơn.', '{"wordId":"gratitude","ukIpa":"/ˈɡrætɪtjuːd/","usIpa":"/ˈɡrætɪtuːd/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"A feeling of thankfulness for help or kindness received.","vi":"lòng biết ơn; sự cảm kích"}],"examples":[{"en":"She brought fresh flowers to express her gratitude.","vi":"Cô ấy mang hoa tươi đến để bày tỏ sự biết ơn.","audioKind":"ex"},{"en":"Schools can encourage gratitude by helping students recognise the contributions that others make to their daily lives.","vi":"Nhà trường có thể bồi dưỡng lòng biết ơn ở học sinh bằng cách giúp các em nhận thức được những đóng góp của người khác đối với cuộc sống thường nhật của mình.","audioKind":"ex2"}],"collocations":[{"en":"express gratitude","vi":"bày tỏ lòng biết ơn"},{"en":"gratitude to someone","vi":"lòng biết ơn đối với ai"},{"en":"gratitude for something","vi":"sự cảm kích về điều gì"},{"en":"a token of gratitude","vi":"một chút lòng thành"}],"wordFamily":["grateful (adj.)","gratefully (adv.)","ingratitude (n.)"],"synonyms":["thankfulness","appreciation"],"antonyms":["ingratitude"],"tipVi":"Lòng biết ơn đối với ai dùng gratitude to, biết ơn vì điều gì dùng gratitude for; thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_desperate', 'en-b2-41', 'desperate', '/ˈdespərət/', 'B2', 'tuyệt vọng; liều lĩnh; khao khát; thèm thuồng; nguy cấp; trầm trọng', 'adj.', 'desperately (adv.), desperation (n.)', 'Đồng nghĩa: hopeless, frantic · Trái nghĩa: hopeful', 'Dùng desperate for để chỉ sự khao khát cái gì; dùng to do để chỉ sự số sắng làm việc gì.', 'Desperate to find her cat, Aisha searched every nearby garden.', NULL, 'Vì quá tuyệt vọng muốn tìm lại con mèo, Aisha đã tìm kiếm ở mọi khu vườn gần đó.', '{"wordId":"desperate","ukIpa":"/ˈdespərət/","usIpa":"/ˈdespərət/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"Feeling nearly hopeless and ready to try anything.","vi":"tuyệt vọng; liều lĩnh"},{"pos":"adj.","en":"Wanting or needing something very badly.","vi":"khao khát; thèm thuồng"},{"pos":"adj.","en":"Extremely serious or dangerous and needing immediate action.","vi":"nguy cấp; trầm trọng"}],"examples":[{"en":"Desperate to find her cat, Aisha searched every nearby garden.","vi":"Vì quá tuyệt vọng muốn tìm lại con mèo, Aisha đã tìm kiếm ở mọi khu vườn gần đó.","audioKind":"ex"},{"en":"After prolonged drought, farming communities face desperate conditions and require urgent support to restore their livelihoods.","vi":"Sau trận hạn hán kéo dài, các cộng đồng nông nghiệp phải đối mặt với hoàn cảnh nguy cấp và cần được hỗ trợ khẩn cấp để khôi phục sinh kế.","audioKind":"ex2"}],"collocations":[{"en":"desperate for help","vi":"rất cần sự giúp đỡ"},{"en":"desperate to escape","vi":"vùng vẫy tìm đường trốn thoát"},{"en":"a desperate attempt","vi":"một nỗ lực liều lĩnh"},{"en":"desperate measures","vi":"biện pháp bất đắc dĩ"}],"wordFamily":["desperately (adv.)","desperation (n.)"],"synonyms":["hopeless","frantic"],"antonyms":["hopeful"],"tipVi":"Dùng desperate for để chỉ sự khao khát cái gì; dùng to do để chỉ sự số sắng làm việc gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sympathetic', 'en-b2-41', 'sympathetic', '/ˌsɪmpəˈθetɪk/', 'B2', 'đồng cảm; thấu cảm; thông cảm; tán thành; ủng hộ', 'adj.', 'sympathy (n.), sympathise (v.), sympathetically (adv.), unsympathetic (adj.)', 'Đồng nghĩa: understanding, compassionate · Trái nghĩa: unsympathetic', 'Thường đi với giới từ to hoặc towards; không mang nghĩa "dễ thương/đáng mến".', 'My manager was sympathetic when I explained my difficulties.', NULL, 'Quản lý của tôi đã rất thông cảm khi tôi giải thích những khó khăn của mình.', '{"wordId":"sympathetic","ukIpa":"/ˌsɪmpəˈθetɪk/","usIpa":"/ˌsɪmpəˈθetɪk/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"showing understanding and care for someone''s difficulties","vi":"đồng cảm; thấu cảm; thông cảm"},{"pos":"adj.","en":"showing approval or support for an idea or proposal","vi":"tán thành; ủng hộ"}],"examples":[{"en":"My manager was sympathetic when I explained my difficulties.","vi":"Quản lý của tôi đã rất thông cảm khi tôi giải thích những khó khăn của mình.","audioKind":"ex"},{"en":"Employers who are sympathetic to carers'' needs can improve staff wellbeing by offering flexible working arrangements.","vi":"Những người chủ sử dụng lao động thấu hiểu nhu cầu của người chăm sóc gia đình có thể cải thiện phúc lợi cho nhân viên bằng cách cung cấp các hình thức làm việc linh hoạt.","audioKind":"ex2"}],"collocations":[{"en":"a sympathetic listener","vi":"một người lắng nghe thấu cảm"},{"en":"a sympathetic attitude","vi":"thái độ cảm thông"},{"en":"sympathetic to a proposal","vi":"tán thành một đề xuất"}],"wordFamily":["sympathy (n.)","sympathise (v.)","sympathetically (adv.)","unsympathetic (adj.)"],"synonyms":["understanding","compassionate"],"antonyms":["unsympathetic"],"tipVi":"Thường đi với giới từ to hoặc towards; không mang nghĩa \"dễ thương/đáng mến\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_endure', 'en-b2-41', 'endure', '/ɪnˈdʊr/', 'B2', 'chịu đựng; cam chịu; kéo dài; bền bỉ', 'v.', 'endurance (n.), enduring (adj.), endurable (adj.)', 'Đồng nghĩa: bear, withstand, last', 'Nghĩa "chịu đựng" đi trực tiếp với túc từ; nghĩa "tiếp tục tồn tại" có thể dùng không cần túc từ.', 'We endured hours of noise while workers repaired the roof.', NULL, 'Chúng tôi đã phải chịu đựng hàng giờ tiếng ồn trong lúc công nhân sửa chữa mái nhà.', '{"wordId":"endure","ukIpa":"/ɪnˈdjʊə/","usIpa":"/ɪnˈdʊr/","cefr":"B2","topic":"emotion","senses":[{"pos":"v.","en":"To suffer something difficult or unpleasant without giving up.","vi":"chịu đựng; cam chịu"},{"pos":"v.","en":"To continue existing despite difficulties or the passage of time.","vi":"kéo dài; bền bỉ"}],"examples":[{"en":"We endured hours of noise while workers repaired the roof.","vi":"Chúng tôi đã phải chịu đựng hàng giờ tiếng ồn trong lúc công nhân sửa chữa mái nhà.","audioKind":"ex"},{"en":"Communities in dry regions must endure prolonged water shortages as climate patterns become less predictable.","vi":"Các cộng đồng ở vùng khô hạn phải chịu đựng tình trạng thiếu nước kéo dài khi các hình thức khí hậu ngày càng khó dự đoán hơn.","audioKind":"ex2"}],"collocations":[{"en":"endure hardship","vi":"chịu đựng gian khổ"},{"en":"endure pain","vi":"chịu đựng đau đớn"},{"en":"endure for centuries","vi":"tồn tại qua nhiều thế kỷ"}],"wordFamily":["endurance (n.)","enduring (adj.)","endurable (adj.)"],"synonyms":["bear","withstand","last"],"antonyms":[],"tipVi":"Nghĩa \"chịu đựng\" đi trực tiếp với túc từ; nghĩa \"tiếp tục tồn tại\" có thể dùng không cần túc từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_delight', 'en-b2-41', 'delight', '/dɪˈlaɪt/', 'B2', 'niềm vui sướng; sự thích thú; làm vui sướng; làm hài lòng; điều thú vị; nguồn vui', 'n.', 'delighted (adj.), delightful (adj.), delightfully (adv.)', 'Đồng nghĩa: joy, pleasure · Trái nghĩa: displeasure', 'delighted dùng để miêu tả người cảm thấy vui mừng; delightful miêu tả sự vật mang lại niềm vui.', 'The children squealed with delight when the puppy arrived.', NULL, 'Lũ trẻ reo lên thích thú khi chú cún con xuất hiện.', '{"wordId":"delight","ukIpa":"/dɪˈlaɪt/","usIpa":"/dɪˈlaɪt/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"a feeling of great pleasure or happiness","vi":"niềm vui sướng; sự thích thú"},{"pos":"v.","en":"to give someone great pleasure","vi":"làm vui sướng; làm hài lòng"},{"pos":"n.","en":"something or someone that gives great pleasure","vi":"điều thú vị; nguồn vui"}],"examples":[{"en":"The children squealed with delight when the puppy arrived.","vi":"Lũ trẻ reo lên thích thú khi chú cún con xuất hiện.","audioKind":"ex"},{"en":"Public gardens can bring delight to city residents while providing valuable spaces for relaxation and social interaction.","vi":"Các khu vườn công cộng có thể mang lại niềm vui cho cư dân thành phố đồng thời cung cấp không gian quý giá để thư giãn và giao lưu xã hội.","audioKind":"ex2"}],"collocations":[{"en":"with delight","vi":"một cách thích thú"},{"en":"to someone''s delight","vi":"khiến ai đó vui mừng"},{"en":"take delight in","vi":"thích thú với"},{"en":"delight in doing something","vi":"vui thích khi làm việc gì"}],"wordFamily":["delighted (adj.)","delightful (adj.)","delightfully (adv.)"],"synonyms":["joy","pleasure"],"antonyms":["displeasure"],"tipVi":"delighted dùng để miêu tả người cảm thấy vui mừng; delightful miêu tả sự vật mang lại niềm vui.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hurrah', 'en-b2-41', 'hurrah', '/hʊˈrɑː/', 'B2', 'hoan hô; tuyệt quá', 'int.', NULL, 'Đồng nghĩa: hooray', 'Đồng nghĩa với hooray; thường đứng độc lập và theo sau là dấu chấm than.', 'Hurrah, the rain has stopped and we can play outside!', NULL, 'Hoan hô, trời tạnh mưa rồi và chúng ta có thể ra ngoài chơi!', '{"wordId":"hurrah","ukIpa":"/hʊˈrɑː/","usIpa":"/hʊˈrɑː/","cefr":"B2","topic":"emotion","senses":[{"pos":"int.","en":"Used to express happiness, excitement, or approval.","vi":"hoan hô; tuyệt quá"}],"examples":[{"en":"Hurrah, the rain has stopped and we can play outside!","vi":"Hoan hô, trời tạnh mưa rồi và chúng ta có thể ra ngoài chơi!","audioKind":"ex"},{"en":"The volunteers shouted hurrah when they learned that their campaign had saved the local park.","vi":"Các tình nguyện viên đồng thanh hô vang khi biết chiến dịch của họ đã cứu được công viên địa phương.","audioKind":"ex2"}],"collocations":[{"en":"shout hurrah","vi":"hô vang hoan hô"},{"en":"a final hurrah","vi":"lần tỏa sáng cuối cùng"}],"wordFamily":[],"synonyms":["hooray"],"antonyms":[],"tipVi":"Đồng nghĩa với hooray; thường đứng độc lập và theo sau là dấu chấm than.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_enthusiasm', 'en-b2-41', 'enthusiasm', '/ɪnˈθuːziæzəm/', 'B2', 'sự nhiệt tình; sự hăng hái', 'n.', 'enthusiastic (adj.), enthusiastically (adv.), enthusiast (n.), enthuse (v.)', 'Đồng nghĩa: eagerness, passion · Trái nghĩa: apathy, indifference', 'Diễn tả sự nhiệt tình đối với việc gì dùng enthusiasm for, và danh từ này thường không đếm được.', 'The children showed real enthusiasm for planting their own vegetables.', NULL, 'Bọn trẻ thể hiện sự nhiệt tình thực sự đối với việc tự tay trồng rau của mình.', '{"wordId":"enthusiasm","ukIpa":"/ɪnˈθjuːziæzəm/","usIpa":"/ɪnˈθuːziæzəm/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"Strong interest and excitement about something you enjoy or value.","vi":"sự nhiệt tình; sự hăng hái"}],"examples":[{"en":"The children showed real enthusiasm for planting their own vegetables.","vi":"Bọn trẻ thể hiện sự nhiệt tình thực sự đối với việc tự tay trồng rau của mình.","audioKind":"ex"},{"en":"Teachers who demonstrate enthusiasm for their subjects can motivate students to explore ideas beyond the classroom.","vi":"Những giáo viên thể hiện sự nhiệt tình với môn học của họ có thể truyền cảm hứng cho học sinh khám phá những ý tưởng vượt ra ngoài lớp học.","audioKind":"ex2"}],"collocations":[{"en":"enthusiasm for","vi":"sự nhiệt tình đối với"},{"en":"with enthusiasm","vi":"một cách nhiệt tình"},{"en":"generate enthusiasm","vi":"khơi dậy sự nhiệt tình"},{"en":"lose enthusiasm","vi":"mất đi sự nhiệt tình"}],"wordFamily":["enthusiastic (adj.)","enthusiastically (adv.)","enthusiast (n.)","enthuse (v.)"],"synonyms":["eagerness","passion"],"antonyms":["apathy","indifference"],"tipVi":"Diễn tả sự nhiệt tình đối với việc gì dùng enthusiasm for, và danh từ này thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sympathize', 'en-b2-41', 'sympathize', '/ˈsɪmpəθaɪz/', 'B2', 'thông cảm; chia sẻ (nỗi đau, khó khăn); ủng hộ; đồng tình (với quan điểm, mục đích)', 'v.', 'sympathy (n.), sympathetic (adj.), sympathetically (adv.)', NULL, 'Không đi thẳng với tân ngữ mà phải dùng sympathize with; tiếng Anh - Anh có thể viết là sympathise.', 'I sympathize with you; losing a pet is painful.', NULL, 'Tôi rất đồng cảm với bạn; mất đi một con thú cưng là điều vô cùng đau đớn.', '{"wordId":"sympathize","ukIpa":"/ˈsɪmpəθaɪz/","usIpa":"/ˈsɪmpəθaɪz/","cefr":"B2","topic":"emotion","senses":[{"pos":"v.","en":"To understand and care about someone''s suffering or difficulties.","vi":"thông cảm; chia sẻ (nỗi đau, khó khăn)"},{"pos":"v.","en":"To agree with someone''s ideas, aims, or position.","vi":"ủng hộ; đồng tình (với quan điểm, mục đích)"}],"examples":[{"en":"I sympathize with you; losing a pet is painful.","vi":"Tôi rất đồng cảm với bạn; mất đi một con thú cưng là điều vô cùng đau đớn.","audioKind":"ex"},{"en":"Many residents sympathize with workers demanding better conditions, although they find the transport strike inconvenient.","vi":"Nhiều cư dân ủng hộ các công nhân đòi hỏi điều kiện làm việc tốt hơn, mặc dù họ thấy cuộc đình công giao thông gây ra không ít phiền toái.","audioKind":"ex2"}],"collocations":[{"en":"sympathize with someone","vi":"thông cảm với ai đó"},{"en":"sympathize with a cause","vi":"ủng hộ một mục đích cao đẹp"}],"wordFamily":["sympathy (n.)","sympathetic (adj.)","sympathetically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Không đi thẳng với tân ngữ mà phải dùng sympathize with; tiếng Anh - Anh có thể viết là sympathise.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_anxiously', 'en-b2-41', 'anxiously', '/ˈæŋkʃəsli/', 'B2', 'một cách lo lắng; bồn chồn; một cách thiết tha; đầy mong đợi', 'adv.', 'anxious (adj.), anxiety (n.)', 'Đồng nghĩa: nervously, uneasily · Trái nghĩa: calmly', 'Thường mang sắc thái lo lắng; nếu mong đợi trong niềm vui thuần túy thì dùng eagerly.', 'He waited anxiously outside while the vet examined his cat.', NULL, 'Anh ấy lo lắng chờ đợi bên ngoài trong lúc bác sĩ thú y khám cho con mèo của mình.', '{"wordId":"anxiously","ukIpa":"/ˈæŋkʃəsli/","usIpa":"/ˈæŋkʃəsli/","cefr":"B2","topic":"emotion","senses":[{"pos":"adv.","en":"In a worried or nervous way.","vi":"một cách lo lắng; bồn chồn"},{"pos":"adv.","en":"With a strong desire for something to happen.","vi":"một cách thiết tha; đầy mong đợi"}],"examples":[{"en":"He waited anxiously outside while the vet examined his cat.","vi":"Anh ấy lo lắng chờ đợi bên ngoài trong lúc bác sĩ thú y khám cho con mèo của mình.","audioKind":"ex"},{"en":"Many graduates anxiously await job offers as competition for entry-level positions continues to increase.","vi":"Nhiều sinh viên tốt nghiệp đang hồi hộp chờ đợi các lời mời nhận việc khi sự cạnh tranh cho các vị trí đầu vào tiếp tục gia tăng.","audioKind":"ex2"}],"collocations":[{"en":"wait anxiously","vi":"chờ đợi trong lo lắng"},{"en":"look anxiously at","vi":"nhìn với vẻ lo âu"},{"en":"anxiously await","vi":"hồi hộp chờ đợi"}],"wordFamily":["anxious (adj.)","anxiety (n.)"],"synonyms":["nervously","uneasily"],"antonyms":["calmly"],"tipVi":"Thường mang sắc thái lo lắng; nếu mong đợi trong niềm vui thuần túy thì dùng eagerly.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_41_1', 'en-b2-41', 'Cách dùng “gratitude” (n.) — lòng biết ơn; sự cảm kích', 'express gratitude  ·  gratitude to someone  ·  gratitude for something', 'Lòng biết ơn đối với ai dùng gratitude to, biết ơn vì điều gì dùng gratitude for; thường là danh từ không đếm được.', 'Họ từ (Word Family): grateful (adj.), gratefully (adv.), ingratitude (n.) | Đồng nghĩa: thankfulness, appreciation · Trái nghĩa: ingratitude', '[{"hanzi":"She brought fresh flowers to express her gratitude.","pinyin":"","meaning":"Cô ấy mang hoa tươi đến để bày tỏ sự biết ơn."},{"hanzi":"Schools can encourage gratitude by helping students recognise the contributions that others make to their daily lives.","pinyin":"","meaning":"Nhà trường có thể bồi dưỡng lòng biết ơn ở học sinh bằng cách giúp các em nhận thức được những đóng góp của người khác đối với cuộc sống thường nhật của mình."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_41_2', 'en-b2-41', 'Cách dùng “astonishment” (n.) — sự kinh ngạc, sự ngạc nhiên tột độ', 'in astonishment  ·  to someone''s astonishment  ·  express astonishment', 'Thường là danh từ không đếm được; cụm từ "to one''s astonishment" có nghĩa là làm cho ai đó ngạc nhiên.', 'Họ từ (Word Family): astonish (v.), astonished (adj.), astonishing (adj.), astonishingly (adv.) | Đồng nghĩa: amazement, surprise', '[{"hanzi":"He stared in astonishment as the tiny seedling flowered.","pinyin":"","meaning":"Cậu ấy trân trân nhìn trong sự ngạc nhiên khi cây non bé xíu bắt đầu trổ hoa."},{"hanzi":"The speed of technological change often causes astonishment, particularly among people who remember life before widespread internet access.","pinyin":"","meaning":"Tốc độ thay đổi công nghệ thường gây ra sự kinh ngạc, đặc biệt là ở những người còn nhớ cuộc sống trước khi internet phổ biến rộng rãi."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_41_3', 'en-b2-41', 'Cách dùng “sympathize” (v.) — thông cảm; chia sẻ (nỗi đau, khó khăn)', 'sympathize with someone  ·  sympathize with a cause', 'Không đi thẳng với tân ngữ mà phải dùng sympathize with; tiếng Anh - Anh có thể viết là sympathise.', 'Họ từ (Word Family): sympathy (n.), sympathetic (adj.), sympathetically (adv.)', '[{"hanzi":"I sympathize with you; losing a pet is painful.","pinyin":"","meaning":"Tôi rất đồng cảm với bạn; mất đi một con thú cưng là điều vô cùng đau đớn."},{"hanzi":"Many residents sympathize with workers demanding better conditions, although they find the transport strike inconvenient.","pinyin":"","meaning":"Nhiều cư dân ủng hộ các công nhân đòi hỏi điều kiện làm việc tốt hơn, mặc dù họ thấy cuộc đình công giao thông gây ra không ít phiền toái."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_41_4', 'en-b2-41', 'Cách dùng “endure” (v.) — chịu đựng; cam chịu', 'endure hardship  ·  endure pain  ·  endure for centuries', 'Nghĩa "chịu đựng" đi trực tiếp với túc từ; nghĩa "tiếp tục tồn tại" có thể dùng không cần túc từ.', 'Họ từ (Word Family): endurance (n.), enduring (adj.), endurable (adj.) | Đồng nghĩa: bear, withstand, last', '[{"hanzi":"We endured hours of noise while workers repaired the roof.","pinyin":"","meaning":"Chúng tôi đã phải chịu đựng hàng giờ tiếng ồn trong lúc công nhân sửa chữa mái nhà."},{"hanzi":"Communities in dry regions must endure prolonged water shortages as climate patterns become less predictable.","pinyin":"","meaning":"Các cộng đồng ở vùng khô hạn phải chịu đựng tình trạng thiếu nước kéo dài khi các hình thức khí hậu ngày càng khó dự đoán hơn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_41_1', 'en-b2-41', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
