INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_41_1_2', 'ten_b2_41_1', 'optimism', 'Her optimism helped us stay cheerful during the storm.', 'Her optimism helped us stay cheerful during the storm.', '/ˈɑːptɪmɪzəm/', 'Sự lạc quan của cô ấy đã giúp chúng tôi giữ vững tinh thần vui vẻ trong suốt trận bão.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_41_1_3', 'ten_b2_41_1', 'humble', 'Despite winning the prize, she remained humble and thanked everyone.', 'Despite winning the prize, she remained humble and thanked everyone.', '/ˈhʌmbəl/', 'Mặc dù giành giải thưởng, cô ấy vẫn giữ sự khiêm tốn và gửi lời cảm ơn đến tất cả mọi người.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_41_1_4', 'ten_b2_41_1', 'hopeful', 'She felt hopeful after her first successful driving lesson.', 'She felt hopeful after her first successful driving lesson.', '/ˈhoʊpfəl/', 'Cô ấy cảm thấy tràn đầy hy vọng sau buổi học lái xe thành công đầu tiên.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_41_1_5', 'ten_b2_41_1', 'astonishment', 'He stared in astonishment as the tiny seedling flowered.', 'He stared in astonishment as the tiny seedling flowered.', '/əˈstɑːnɪʃmənt/', 'Cậu ấy trân trân nhìn trong sự ngạc nhiên khi cây non bé xíu bắt đầu trổ hoa.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_41_1_6', 'ten_b2_41_1', 'hopeless', 'The situation seemed hopeless until our neighbours offered help.', 'The situation seemed hopeless until our neighbours offered help.', '/ˈhoʊpləs/', 'Tình hình tưởng chừng như vô vọng cho đến khi những người hàng xóm đến giúp đỡ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_41_1_7', 'ten_b2_41_1', 'affection', 'Our cat shows affection by rubbing against our legs.', 'Our cat shows affection by rubbing against our legs.', '/əˈfekʃən/', 'Con mèo nhà chúng tôi thể hiện sự quấn quýt bằng cách cọ vào chân chúng tôi.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_41_1_8', 'ten_b2_41_1', 'sob', 'The child began to sob after losing her toy.', 'The child began to sob after losing her toy.', '/sɑːb/', 'Đứa trẻ bắt đầu nức nở sau khi làm mất món đồ chơi của mình.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_41_1_1', 'en-b2-41', 'ten_b2_41_1', 'listening', 'listening', 'Her touching farewell brought tears to my eyes.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Lời chia tay đầy cảm động của cô ấy khiến tôi rớm lệ.","Cô ấy bừng tỉnh trong nỗi sợ hãi tột độ sau khi mơ thấy thang máy rơi.","Chúng tôi đã phải chịu đựng hàng giờ tiếng ồn trong lúc công nhân sửa chữa mái nhà.","Căn bếp trở nên hỗn loạn hoàn toàn sau khi chúng tôi làm bánh."]'::jsonb, 0, 'Her touching farewell brought tears to my eyes. → Lời chia tay đầy cảm động của cô ấy khiến tôi rớm lệ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_41_1_2', 'en-b2-41', 'ten_b2_41_1', 'listening', 'listening', 'Her optimism helped us stay cheerful during the storm.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã phải chịu đựng hàng giờ tiếng ồn trong lúc công nhân sửa chữa mái nhà.","Vì quá tuyệt vọng muốn tìm lại con mèo, Aisha đã tìm kiếm ở mọi khu vườn gần đó.","Sự lạc quan của cô ấy đã giúp chúng tôi giữ vững tinh thần vui vẻ trong suốt trận bão.","Các nhà phê bình đã chê bai thậm tệ vở kịch vì phần kết quá yếu."]'::jsonb, 2, 'Her optimism helped us stay cheerful during the storm. → Sự lạc quan của cô ấy đã giúp chúng tôi giữ vững tinh thần vui vẻ trong suốt trận bão.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_41_1_3', 'en-b2-41', 'ten_b2_41_1', 'listening', 'listening', 'Despite winning the prize, she remained humble and thanked everyone.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Mặc dù giành giải thưởng, cô ấy vẫn giữ sự khiêm tốn và gửi lời cảm ơn đến tất cả mọi người.","Tôi rất đồng cảm với bạn; mất đi một con thú cưng là điều vô cùng đau đớn.","Các nhà phê bình đã chê bai thậm tệ vở kịch vì phần kết quá yếu.","Lời chia tay đầy cảm động của cô ấy khiến tôi rớm lệ."]'::jsonb, 0, 'Despite winning the prize, she remained humble and thanked everyone. → Mặc dù giành giải thưởng, cô ấy vẫn giữ sự khiêm tốn và gửi lời cảm ơn đến tất cả mọi người.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_41_2', 'en-b2-41', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_41_2_1', 'ten_b2_41_2', 'touching', 'The documentary offers a touching account of volunteers helping older residents overcome loneliness in urban communities.', 'The documentary offers a touching account of volunteers helping older residents overcome loneliness in urban communities.', '/ˈtʌtʃɪŋ/', 'Bộ phim tài liệu mang đến một góc nhìn xúc động về các tình nguyện viên giúp đỡ người cao tuổi cô đơn vượt qua sự cô độc trong các cộng đồng đô thị.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_41_2_2', 'ten_b2_41_2', 'optimism', 'Despite economic uncertainty, many graduates express optimism about their chances of finding meaningful employment.', 'Despite economic uncertainty, many graduates express optimism about their chances of finding meaningful employment.', '/ˈɑːptɪmɪzəm/', 'Bất chấp những bất ổn kinh tế, nhiều sinh viên tốt nghiệp vẫn bày tỏ sự lạc quan về cơ hội tìm được việc làm ý nghĩa của họ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_41_2_3', 'ten_b2_41_2', 'humble', 'Effective leaders remain humble enough to acknowledge mistakes and learn from colleagues with different backgrounds and experiences.', 'Effective leaders remain humble enough to acknowledge mistakes and learn from colleagues with different backgrounds and experiences.', '/ˈhʌmbəl/', 'Những nhà lãnh đạo tài ba luôn giữ được sự khiêm tốn cần thiết để thừa nhận sai lầm và học hỏi từ những đồng nghiệp có nền tảng và kinh nghiệm khác nhau.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_41_2_4', 'ten_b2_41_2', 'hopeful', 'Scientists remain hopeful that improved battery technology will make renewable energy more reliable and affordable.', 'Scientists remain hopeful that improved battery technology will make renewable energy more reliable and affordable.', '/ˈhoʊpfəl/', 'Các nhà khoa học vẫn nuôi hy vọng rằng công nghệ pin cải tiến sẽ giúp năng lượng tái tạo trở nên đáng tin cậy và có giá cả phải chăng hơn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_41_2_5', 'ten_b2_41_2', 'astonishment', 'The speed of technological change often causes astonishment, particularly among people who remember life before widespread internet access.', 'The speed of technological change often causes astonishment, particularly among people who remember life before widespread internet access.', '/əˈstɑːnɪʃmənt/', 'Tốc độ thay đổi công nghệ thường gây ra sự kinh ngạc, đặc biệt là ở những người còn nhớ cuộc sống trước khi internet phổ biến rộng rãi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_41_2_6', 'ten_b2_41_2', 'hopeless', 'Students who feel hopeless about their academic progress may benefit from individual guidance and achievable learning goals.', 'Students who feel hopeless about their academic progress may benefit from individual guidance and achievable learning goals.', '/ˈhoʊpləs/', 'Những học sinh cảm thấy tuyệt vọng về tiến1 bộ học tập của mình có thể sẽ nhận được nhiều lợi ích từ việc hướng dẫn cá nhân và các mục tiêu học tập khả thi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_41_2_1', 'en-b2-41', 'ten_b2_41_2', 'listening', 'listening', 'The documentary offers a touching account of volunteers helping older residents overcome loneliness in urban communities.', NULL, 'Trong câu vừa nghe, từ “touching” mang nghĩa nào sau đây?', '["xã hội văn minh; nền văn minh","phân hủy; mục rữa","nhân viên phục vụ (trên tàu, máy bay hoặc tại sự kiện); tiếp viên","cảm động; xúc động"]'::jsonb, 3, '“touching” (/ˈtʌtʃɪŋ/): cảm động; xúc động. Câu đầy đủ: The documentary offers a touching account of volunteers helping older residents overcome loneliness in urban communities.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_41_2_2', 'en-b2-41', 'ten_b2_41_2', 'listening', 'listening', 'Despite economic uncertainty, many graduates express optimism about their chances of finding meaningful employment.', NULL, 'Trong câu vừa nghe, từ “optimism” mang nghĩa nào sau đây?', '["tối đa hóa; tận dụng tối đa","lòng lạc quan; thái độ lạc quan","tự kinh doanh; tự làm chủ","nhà bán buôn; doanh nghiệp bán sỉ"]'::jsonb, 1, '“optimism” (/ˈɑːptɪmɪzəm/): lòng lạc quan; thái độ lạc quan. Câu đầy đủ: Despite economic uncertainty, many graduates express optimism about their chances of finding meaningful employment.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
