INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_41_2', 'en-b2-41', 'Her optimism helped us stay cheerful during the storm', 'Sự lạc quan của cô ấy đã giúp chúng tôi giữ vững tinh thần vui vẻ trong suốt trận bão.', 'optimism /ˈɑːptɪmɪzəm/', '["optimism","the","us","cheerful","Her","during","helped","stay","storm"]'::jsonb, NULL, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_41_3', 'en-b2-41', 'Despite winning the prize, she remained humble and thanked everyone', 'Mặc dù giành giải thưởng, cô ấy vẫn giữ sự khiêm tốn và gửi lời cảm ơn đến tất cả mọi người.', 'humble /ˈhʌmbəl/', '["and","thanked","humble","prize","the","she","Despite","everyone","remained","winning"]'::jsonb, NULL, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_41_4', 'en-b2-41', 'She felt hopeful after her first successful driving lesson', 'Cô ấy cảm thấy tràn đầy hy vọng sau buổi học lái xe thành công đầu tiên.', 'hopeful /ˈhoʊpfəl/', '["lesson","after","felt","driving","successful","She","hopeful","her","first"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
