INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_41_7', 'en-b2-41', 'Our cat shows affection by rubbing against our legs', 'Con mèo nhà chúng tôi thể hiện sự quấn quýt bằng cách cọ vào chân chúng tôi.', 'affection /əˈfekʃən/', '["shows","by","against","Our","our","legs","affection","rubbing","cat"]'::jsonb, NULL, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
