INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_41_2', 'en-b2-41', NULL, 'comprehensive_test', 'listening', 'Her optimism helped us stay cheerful during the storm.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sự lạc quan của cô ấy đã giúp chúng tôi giữ vững tinh thần vui vẻ trong suốt trận bão.","Anh ấy đã lịch sự bày tỏ sự không hài lòng với bữa ăn nguội ngắt.","Tôi rất đồng cảm với bạn; mất đi một con thú cưng là điều vô cùng đau đớn.","Anh ấy lo lắng chờ đợi bên ngoài trong lúc bác sĩ thú y khám cho con mèo của mình."]'::jsonb, 0, 'Her optimism helped us stay cheerful during the storm. → Sự lạc quan của cô ấy đã giúp chúng tôi giữ vững tinh thần vui vẻ trong suốt trận bão.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_41_3', 'en-b2-41', NULL, 'comprehensive_test', 'listening', 'humble', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tình trạng tắc nghẽn; sự ùn tắc","khiêm tốn; không tự cao","có tính đàn hồi; co giãn","quỹ; tiền quỹ"]'::jsonb, 1, 'humble (/ˈhʌmbəl/) → khiêm tốn; không tự cao; nhỏ bé; đạm bạc; có địa vị thấp kém; làm cho khiêm nhường; hạ mình', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_41_4', 'en-b2-41', NULL, 'comprehensive_test', 'listening', 'She felt hopeful after her first successful driving lesson.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Đứa trẻ bắt đầu nức nở sau khi làm mất món đồ chơi của mình.","Con mèo nhà chúng tôi thể hiện sự quấn quýt bằng cách cọ vào chân chúng tôi.","Cô ấy cảm thấy tràn đầy hy vọng sau buổi học lái xe thành công đầu tiên.","Lời chia tay đầy cảm động của cô ấy khiến tôi rớm lệ."]'::jsonb, 2, 'She felt hopeful after her first successful driving lesson. → Cô ấy cảm thấy tràn đầy hy vọng sau buổi học lái xe thành công đầu tiên.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_41_5', 'en-b2-41', NULL, 'comprehensive_test', 'listening', 'astonishment', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["áo giáp, vỏ giáp (bảo vệ)","cái xẻng","sự kinh ngạc, sự ngạc nhiên tột độ","lỗi; khiếm khuyết; tì vết"]'::jsonb, 2, 'astonishment (/əˈstɑːnɪʃmənt/) → sự kinh ngạc, sự ngạc nhiên tột độ', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_41_6', 'en-b2-41', NULL, 'comprehensive_test', 'listening', 'The situation seemed hopeless until our neighbours offered help.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Mặc dù giành giải thưởng, cô ấy vẫn giữ sự khiêm tốn và gửi lời cảm ơn đến tất cả mọi người.","Lũ trẻ reo lên thích thú khi chú cún con xuất hiện.","Hoan hô, trời tạnh mưa rồi và chúng ta có thể ra ngoài chơi!","Tình hình tưởng chừng như vô vọng cho đến khi những người hàng xóm đến giúp đỡ."]'::jsonb, 3, 'The situation seemed hopeless until our neighbours offered help. → Tình hình tưởng chừng như vô vọng cho đến khi những người hàng xóm đến giúp đỡ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_41_7', 'en-b2-41', NULL, 'comprehensive_test', 'listening', 'affection', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự âu yếm; lòng quý mến; tình cảm","về; liên quan đến","du thuyền; thuyền buồm","sự giảm bớt; sự cắt giảm; sự hạ giá"]'::jsonb, 0, 'affection (/əˈfekʃən/) → sự âu yếm; lòng quý mến; tình cảm', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_41_8', 'en-b2-41', NULL, 'comprehensive_test', 'listening', 'The child began to sob after losing her toy.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Mặc dù giành giải thưởng, cô ấy vẫn giữ sự khiêm tốn và gửi lời cảm ơn đến tất cả mọi người.","Quản lý của tôi đã rất thông cảm khi tôi giải thích những khó khăn của mình.","Đứa trẻ bắt đầu nức nở sau khi làm mất món đồ chơi của mình.","Cô ấy cảm thấy tràn đầy hy vọng sau buổi học lái xe thành công đầu tiên."]'::jsonb, 2, 'The child began to sob after losing her toy. → Đứa trẻ bắt đầu nức nở sau khi làm mất món đồ chơi của mình.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_41_9', 'en-b2-41', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a feeling of very great surprise”?', '["astonishment","sympathize","hurrah","terror"]'::jsonb, 0, 'astonishment (/əˈstɑːnɪʃmənt/) → sự kinh ngạc, sự ngạc nhiên tột độ', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_41_10', 'en-b2-41', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Having no hope, or offering no chance of success.”?', '["hesitation","utter","astonishment","hopeless"]'::jsonb, 3, 'hopeless (/ˈhoʊpləs/) → tuyệt vọng; không có hy vọng', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_41_11', 'en-b2-41', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A warm feeling of love or fondness for someone or something.”?', '["affection","gratitude","enthusiasm","hesitation"]'::jsonb, 0, 'affection (/əˈfekʃən/) → sự âu yếm; lòng quý mến; tình cảm', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_41_12', 'en-b2-41', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to cry with short, sudden breaths”?', '["sob","affection","enthusiasm","terror"]'::jsonb, 0, 'sob (/sɑːb/) → nức nở; sụt sùi; khóc nức nở', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
