INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_41_18', 'en-b2-41', NULL, 'comprehensive_test', 'reading', NULL, 'The documentary offers a touching account of volunteers helping older residents overcome loneliness in urban communities.', 'Dựa vào câu trên, từ “touching” có nghĩa phù hợp nhất là gì?', '["cảm động; xúc động","mang tính so sánh; đối chiếu","mua; tậu","khu nghỉ dưỡng; khu du lịch"]'::jsonb, 0, 'touching: cảm động; xúc động; sự chạm; sự sờ (dạng phân từ hiện tại). Dịch cả câu: Bộ phim tài liệu mang đến một góc nhìn xúc động về các tình nguyện viên giúp đỡ người cao tuổi cô đơn vượt qua sự cô độc trong các cộng đồng đô thị.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_41_19', 'en-b2-41', NULL, 'comprehensive_test', 'reading', NULL, 'Despite economic uncertainty, many graduates express optimism about their chances of finding meaningful employment.', 'Dựa vào câu trên, từ “optimism” có nghĩa phù hợp nhất là gì?', '["lòng lạc quan; thái độ lạc quan","khối lượng công việc; lượng công việc mà ai đó phải hoàn thành trong một khoảng thời gian nhất định","đáng ao ước; đáng giá, thích hợp","học phí"]'::jsonb, 0, 'optimism: lòng lạc quan; thái độ lạc quan. Dịch cả câu: Bất chấp những bất ổn kinh tế, nhiều sinh viên tốt nghiệp vẫn bày tỏ sự lạc quan về cơ hội tìm được việc làm ý nghĩa của họ.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_41_20', 'en-b2-41', NULL, 'comprehensive_test', 'reading', NULL, 'Effective leaders remain humble enough to acknowledge mistakes and learn from colleagues with different backgrounds and experiences.', 'Dựa vào câu trên, từ “humble” có nghĩa phù hợp nhất là gì?', '["giúp đỡ; hỗ trợ","giống; tương tự","xé rách; làm rách","khiêm tốn; không tự cao"]'::jsonb, 3, 'humble: khiêm tốn; không tự cao; nhỏ bé; đạm bạc; có địa vị thấp kém; làm cho khiêm nhường; hạ mình. Dịch cả câu: Những nhà lãnh đạo tài ba luôn giữ được sự khiêm tốn cần thiết để thừa nhận sai lầm và học hỏi từ những đồng nghiệp có nền tảng và kinh nghiệm khác nhau.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_41_21', 'en-b2-41', NULL, 'comprehensive_test', 'reading', NULL, 'Scientists remain hopeful that improved battery technology will make renewable energy more reliable and affordable.', 'Dựa vào câu trên, từ “hopeful” có nghĩa phù hợp nhất là gì?', '["tràn đầy hy vọng; lạc quan","đủ; đầy đủ; thích hợp","chỉ là; đơn thuần là","kỳ thực tập, công việc thực tập"]'::jsonb, 0, 'hopeful: tràn đầy hy vọng; lạc quan; đầy triển vọng; có hy vọng; người có triển vọng thành công. Dịch cả câu: Các nhà khoa học vẫn nuôi hy vọng rằng công nghệ pin cải tiến sẽ giúp năng lượng tái tạo trở nên đáng tin cậy và có giá cả phải chăng hơn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_41_22', 'en-b2-41', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự nhiệt tình; sự hăng hái”', '["isolation","correspondent","enthusiasm","chunk"]'::jsonb, 2, 'sự nhiệt tình; sự hăng hái → enthusiasm (/ɪnˈθuːziæzəm/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_41_23', 'en-b2-41', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thông cảm; chia sẻ (nỗi đau, khó khăn)”', '["automobile","encyclopedia","sympathize","adoption"]'::jsonb, 2, 'thông cảm; chia sẻ (nỗi đau, khó khăn) → sympathize (/ˈsɪmpəθaɪz/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_41_24', 'en-b2-41', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “một cách lo lắng; bồn chồn”', '["groom","anxiously","archery","congested"]'::jsonb, 1, 'một cách lo lắng; bồn chồn → anxiously (/ˈæŋkʃəsli/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-42', 'en', 'Bài 42: Cảm xúc & Tính cách (2) - CEFR B2', 'CEFR B2', 'B2 · Cảm xúc', '24 từ vựng Tiếng Anh CEFR B2 chủ đề cảm xúc & tính cách kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4042, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_impatience', 'en-b2-42', 'impatience', '/ɪmˈpeɪʃns/', 'B2', 'sự số ruột; sự bực bội do chờ đợi; sự nôn nóng; niềm khát khao mong mỏi', 'n.', 'impatient (adj.), impatiently (adv.), patience (n.), patient (adj.)', 'Đồng nghĩa: restlessness, eagerness · Trái nghĩa: patience', 'Thường không đếm được; bày tỏ sự sốt ruột với ai hoặc việc gì thường đi với giới từ with.', 'She tapped her foot with impatience as the queue stalled.', NULL, 'Cô ấy bứt rứt lấy chân gõ xuống đất khi hàng người cứ đứng ì ra.', '{"wordId":"impatience","ukIpa":"/ɪmˈpeɪʃns/","usIpa":"/ɪmˈpeɪʃns/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"annoyance caused by waiting, delays, or other people''s behaviour","vi":"sự số ruột; sự bực bội do chờ đợi"},{"pos":"n.","en":"a strong desire for something to happen soon","vi":"sự nôn nóng; niềm khát khao mong mỏi"}],"examples":[{"en":"She tapped her foot with impatience as the queue stalled.","vi":"Cô ấy bứt rứt lấy chân gõ xuống đất khi hàng người cứ đứng ì ra.","audioKind":"ex"},{"en":"Growing impatience with unreliable public transport may encourage commuters to use private cars, increasing urban congestion.","vi":"Sự thiếu kiên nhẫn ngày càng tăng đối với hệ thống giao thông công cộng kém tin cậy có thể thúc đẩy người đi làm chuyển sang dùng ô tô riêng, làm trầm trọng thêm tình trạng tắc nghẽn đô thị.","audioKind":"ex2"}],"collocations":[{"en":"impatience with delays","vi":"sự bất mãn vì chậm trễ"},{"en":"show impatience","vi":"thể hiện sự nôn nóng"},{"en":"growing impatience","vi":"sự sốt ruột ngày càng tăng"},{"en":"with impatience","vi":"một cách nôn nóng"}],"wordFamily":["impatient (adj.)","impatiently (adv.)","patience (n.)","patient (adj.)"],"synonyms":["restlessness","eagerness"],"antonyms":["patience"],"tipVi":"Thường không đếm được; bày tỏ sự sốt ruột với ai hoặc việc gì thường đi với giới từ with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bravery', 'en-b2-42', 'bravery', '/ˈbreɪvəri/', 'B2', 'sự dũng cảm; lòng can đảm; tính gan dạ', 'n.', 'brave (adj.), bravely (adv.)', 'Đồng nghĩa: courage, courageousness · Trái nghĩa: cowardice', 'Đây là danh từ không đếm được; một hành động dũng cảm được diễn đạt là an act of bravery.', 'The little girl showed bravery during her first injection.', NULL, 'Cô bé đã thể hiện sự dũng cảm trong lần tiêm đầu tiên của mình.', '{"wordId":"bravery","ukIpa":"/ˈbreɪvəri/","usIpa":"/ˈbreɪvəri/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"The courage to face danger, pain, or difficult situations.","vi":"sự dũng cảm; lòng can đảm; tính gan dạ"}],"examples":[{"en":"The little girl showed bravery during her first injection.","vi":"Cô bé đã thể hiện sự dũng cảm trong lần tiêm đầu tiên của mình.","audioKind":"ex"},{"en":"Emergency workers demonstrate remarkable bravery when they enter dangerous areas to rescue people after natural disasters.","vi":"Các nhân viên cứu hộ đã thể hiện lòng dũng cảm phi thường khi tiến vào các khu vực hiểm trở để giải cứu người dân sau thảm họa thiên nhiên.","audioKind":"ex2"}],"collocations":[{"en":"show bravery","vi":"thể hiện lòng dũng cảm"},{"en":"remarkable bravery","vi":"sự dũng cảm phi thường"},{"en":"an act of bravery","vi":"một hành động dũng cảm"}],"wordFamily":["brave (adj.)","bravely (adv.)"],"synonyms":["courage","courageousness"],"antonyms":["cowardice"],"tipVi":"Đây là danh từ không đếm được; một hành động dũng cảm được diễn đạt là an act of bravery.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grumble', 'en-b2-42', 'grumble', '/ˈɡrʌmbəl/', 'B2', 'cằn nhằn; phàn nàn; lời phàn nàn; tiếng kêu ca; phát ra tiếng gầm gừ trầm thấp', 'v.', 'grumbler (n.), grumbling (n.)', 'Đồng nghĩa: complain, moan', 'Thường đi với cấu trúc grumble about sth để chỉ việc phàn nàn về điều gì.', 'My brother grumbled about washing the dishes again.', NULL, 'Anh trai tôi lại cằn nhằn về việc phải rửa bát.', '{"wordId":"grumble","ukIpa":"/ˈɡrʌmbəl/","usIpa":"/ˈɡrʌmbəl/","cefr":"B2","topic":"emotion","senses":[{"pos":"v.","en":"to complain in an annoyed, often quiet way","vi":"cằn nhằn; phàn nàn"},{"pos":"n.","en":"a complaint about something that annoys you","vi":"lời phàn nàn; tiếng kêu ca"},{"pos":"v.","en":"to make a low, deep rumbling sound","vi":"phát ra tiếng gầm gừ trầm thấp"}],"examples":[{"en":"My brother grumbled about washing the dishes again.","vi":"Anh trai tôi lại cằn nhằn về việc phải rửa bát.","audioKind":"ex"},{"en":"Although commuters often grumble about delays, many still prefer public transport because it reduces travel costs.","vi":"Mặc dù những người đi làm thường phàn nàn về tình trạng chậm chuyến, nhiều người vẫn thích phương tiện công cộng hơn vì nó giúp giảm chi phí đi lại.","audioKind":"ex2"}],"collocations":[{"en":"grumble about delays","vi":"phàn nàn về việc chậm trễ"},{"en":"grumble at someone","vi":"cằn nhằn ai đó"},{"en":"a common grumble","vi":"lời phàn nàn phổ biến"}],"wordFamily":["grumbler (n.)","grumbling (n.)"],"synonyms":["complain","moan"],"antonyms":[],"tipVi":"Thường đi với cấu trúc grumble about sth để chỉ việc phàn nàn về điều gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_relieved', 'en-b2-42', 'relieved', '/rɪˈliːvd/', 'B2', 'tính từ: nhẹ nhõm; yên tâm; thanh thản', 'adj.', 'relieve (v.), relief (n.)', 'Đồng nghĩa: reassured · Trái nghĩa: worried, anxious', 'Thường dùng cấu trúc be relieved to do hoặc be relieved that để diễn tả cảm xúc.', 'I felt relieved when I finally found my keys.', NULL, 'Tôi cảm thấy nhẹ nhõm khi cuối cùng cũng tìm thấy chìa khóa của mình.', '{"wordId":"relieved","ukIpa":"/rɪˈliːvd/","usIpa":"/rɪˈliːvd/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"No longer worried because something unpleasant has ended or been avoided","vi":"tính từ: nhẹ nhõm; yên tâm; thanh thản"}],"examples":[{"en":"I felt relieved when I finally found my keys.","vi":"Tôi cảm thấy nhẹ nhõm khi cuối cùng cũng tìm thấy chìa khóa của mình.","audioKind":"ex"},{"en":"Residents were relieved to hear that the local hospital would remain open despite proposed budget cuts.","vi":"Cư dân đã rất yên tâm khi nghe tin bệnh viện địa phương vẫn tiếp tục hoạt động bất chấp các đề xuất cắt giảm ngân sách.","audioKind":"ex2"}],"collocations":[{"en":"feel relieved","vi":"cảm thấy nhẹ nhõm"},{"en":"relieved to hear","vi":"nhẹ nhõm khi nghe tin"},{"en":"visibly relieved","vi":"thể hiện rõ sự nhẹ nhõm"}],"wordFamily":["relieve (v.)","relief (n.)"],"synonyms":["reassured"],"antonyms":["worried","anxious"],"tipVi":"Thường dùng cấu trúc be relieved to do hoặc be relieved that để diễn tả cảm xúc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_determination', 'en-b2-42', 'determination', '/dɪˌtɝːmɪˈneɪʃən/', 'B2', 'sự quyết tâm; nghị lực; sự xác định; sự định đoạt; sự phán quyết', 'n.', 'determine (v.), determined (adj.)', 'Đồng nghĩa: resolve, persistence · Trái nghĩa: indecision', 'Diễn tả sự quyết tâm thường đi với giới từ to do; diễn tả sự xác định thường đi với of.', 'Despite the rain, she finished the race with determination.', NULL, 'Bất chấp trời mưa, cô ấy vẫn hoàn thành cuộc đua với đầy sự quyết tâm.', '{"wordId":"determination","ukIpa":"/dɪˌtɜːmɪˈneɪʃən/","usIpa":"/dɪˌtɝːmɪˈneɪʃən/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"the firm intention to continue despite difficulties","vi":"sự quyết tâm; nghị lực"},{"pos":"n.","en":"the process of establishing a fact or making an official decision","vi":"sự xác định; sự định đoạt; sự phán quyết"}],"examples":[{"en":"Despite the rain, she finished the race with determination.","vi":"Bất chấp trời mưa, cô ấy vẫn hoàn thành cuộc đua với đầy sự quyết tâm.","audioKind":"ex"},{"en":"Students who show determination are often better able to overcome academic setbacks and achieve their goals.","vi":"Những học sinh thể hiện ý chí quyết tâm thường có khả năng vượt qua những trở ngại trong học tập và đạt được mục tiêu của mình tốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"sheer determination","vi":"quyết tâm cao độ"},{"en":"determination to succeed","vi":"quyết tâm thành công"},{"en":"determination of eligibility","vi":"xác định tư cách"}],"wordFamily":["determine (v.)","determined (adj.)"],"synonyms":["resolve","persistence"],"antonyms":["indecision"],"tipVi":"Diễn tả sự quyết tâm thường đi với giới từ to do; diễn tả sự xác định thường đi với of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pathetic', 'en-b2-42', 'pathetic', '/pəˈθetɪk/', 'B2', 'tệ hại; đáng chê trách; kém cỏi; đáng thương; thảm hại', 'adj.', 'pathetically (adv.)', 'Đồng nghĩa: pitiful, feeble', 'Thường mang sắc thái chê bai mạnh mẽ, không nên tùy tiện dùng để miêu tả người khác.', 'The broken shower produced only a pathetic trickle.', NULL, 'Vòi hoa sen bị hỏng chỉ nhỏ ra một dòng nước thảm hại.', '{"wordId":"pathetic","ukIpa":"/pəˈθetɪk/","usIpa":"/pəˈθetɪk/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"so poor or ineffective that it deserves strong criticism","vi":"tệ hại; đáng chê trách; kém cỏi"},{"pos":"adj.","en":"making you feel pity because of suffering or helplessness","vi":"đáng thương; thảm hại"}],"examples":[{"en":"The broken shower produced only a pathetic trickle.","vi":"Vòi hoa sen bị hỏng chỉ nhỏ ra một dòng nước thảm hại.","audioKind":"ex"},{"en":"Residents described the council''s response to repeated flooding as pathetic, demanding immediate investment in better drainage.","vi":"Cư dân mô tả cách phản ứng của hội đồng đối với tình trạng ngập lụt lặp đi lặp lại là vô cùng kém cỏi, đồng thời yêu cầu đầu tư ngay lập tức vào hệ thống thoát nước tốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"a pathetic excuse","vi":"một lời ngụy biện ngớ ngẩn"},{"en":"a pathetic attempt","vi":"một nỗ lực kém cỏi"},{"en":"a pathetic sight","vi":"một cảnh tượng đáng thương"}],"wordFamily":["pathetically (adv.)"],"synonyms":["pitiful","feeble"],"antonyms":[],"tipVi":"Thường mang sắc thái chê bai mạnh mẽ, không nên tùy tiện dùng để miêu tả người khác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fascinate', 'en-b2-42', 'fascinate', '/ˈfæsɪneɪt/', 'B2', 'làm say mê; thu hút sâu sắc', 'v.', 'fascination (n.), fascinating (adj.), fascinated (adj.)', 'Đồng nghĩa: captivate, enthral · Trái nghĩa: bore', 'Sự vật gây ra sự mê hoặc dùng fascinating; con người cảm thấy bị mê hoặc dùng fascinated.', 'The colourful fish fascinated the children at the aquarium.', NULL, 'Những chú cá đầy màu sắc đã làm cho lũ trẻ ở thủy cung vô cùng thích thú.', '{"wordId":"fascinate","ukIpa":"/ˈfæsɪneɪt/","usIpa":"/ˈfæsɪneɪt/","cefr":"B2","topic":"emotion","senses":[{"pos":"v.","en":"to attract and hold someone''s attention very strongly","vi":"làm say mê; thu hút sâu sắc"}],"examples":[{"en":"The colourful fish fascinated the children at the aquarium.","vi":"Những chú cá đầy màu sắc đã làm cho lũ trẻ ở thủy cung vô cùng thích thú.","audioKind":"ex"},{"en":"Ancient civilisations continue to fascinate researchers because their achievements reveal remarkable solutions to complex practical problems.","vi":"Các nền văn minh cổ đại vẫn tiếp tục làm say mê các nhà nghiên cứu bởi vì các thành tựu của họ đưa ra những giải pháp phi thường cho những vấn đề thực tiễn phức tạp.","audioKind":"ex2"}],"collocations":[{"en":"fascinate an audience","vi":"làm say lòng khán giả"},{"en":"be fascinated by","vi":"bị mê hoặc bởi"},{"en":"never cease to fascinate","vi":"luôn làm say đắm"}],"wordFamily":["fascination (n.)","fascinating (adj.)","fascinated (adj.)"],"synonyms":["captivate","enthral"],"antonyms":["bore"],"tipVi":"Sự vật gây ra sự mê hoặc dùng fascinating; con người cảm thấy bị mê hoặc dùng fascinated.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_anxious', 'en-b2-42', 'anxious', '/ˈæŋkʃəs/', 'B2', 'lo lắng; bồn chồn; khao khát; nóng lòng', 'adj.', 'anxiety (n.), anxiously (adv.)', 'Đồng nghĩa: worried, uneasy · Trái nghĩa: calm, relaxed', '"anxious about" mang nghĩa lo lắng; "anxious to do" thường mang nghĩa nóng lòng, háo hức.', 'I felt anxious while waiting for my exam results.', NULL, 'Tôi cảm thấy lo lắng khi chờ đợi kết quả thi.', '{"wordId":"anxious","ukIpa":"/ˈæŋkʃəs/","usIpa":"/ˈæŋkʃəs/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"Worried or nervous about something uncertain.","vi":"lo lắng; bồn chồn"},{"pos":"adj.","en":"Very eager to do something or for something to happen.","vi":"khao khát; nóng lòng"}],"examples":[{"en":"I felt anxious while waiting for my exam results.","vi":"Tôi cảm thấy lo lắng khi chờ đợi kết quả thi.","audioKind":"ex"},{"en":"Students may become anxious about their future when career guidance is unavailable at school.","vi":"Học sinh có thể trở nên lo lắng về tương lai khi nhà trường không cung cấp dịch vụ hướng nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"anxious about","vi":"lo lắng về"},{"en":"anxious to please","vi":"nóng lòng làm vừa lòng"},{"en":"feel anxious","vi":"cảm thấy lo lắng"}],"wordFamily":["anxiety (n.)","anxiously (adv.)"],"synonyms":["worried","uneasy"],"antonyms":["calm","relaxed"],"tipVi":"\"anxious about\" mang nghĩa lo lắng; \"anxious to do\" thường mang nghĩa nóng lòng, háo hức.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_temptation', 'en-b2-42', 'temptation', '/tempˈteɪʃən/', 'B2', 'sự cám dỗ; điều cám dỗ', 'n.', 'tempt (v.), tempting (adj.), tempted (adj.)', NULL, 'Thường dùng cấu trúc "the temptation to do" để diễn tả sự cám dỗ muốn làm việc gì đó.', 'I resisted the temptation to eat another slice of cake.', NULL, 'Tôi đã kìm lại được sự cám dỗ ăn thêm một miếng bánh nữa.', '{"wordId":"temptation","ukIpa":"/tempˈteɪʃən/","usIpa":"/tempˈteɪʃən/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"A strong desire for something, or something causing that desire.","vi":"sự cám dỗ; điều cám dỗ"}],"examples":[{"en":"I resisted the temptation to eat another slice of cake.","vi":"Tôi đã kìm lại được sự cám dỗ ăn thêm một miếng bánh nữa.","audioKind":"ex"},{"en":"Students may face the temptation to copy online material rather than develop their own ideas.","vi":"Sinh viên có thể đối mặt với sự cám dỗ sao chép tài liệu trực tuyến thay vì tự phát triển ý tưởng của riêng mình.","audioKind":"ex2"}],"collocations":[{"en":"resist temptation","vi":"chống lại sự cám dỗ"},{"en":"give in to temptation","vi":"sa vào cám dỗ"},{"en":"the temptation to do something","vi":"sự cám dỗ làm điều gì đó"}],"wordFamily":["tempt (v.)","tempting (adj.)","tempted (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng cấu trúc \"the temptation to do\" để diễn tả sự cám dỗ muốn làm việc gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lonesome', 'en-b2-42', 'lonesome', '/ˈloʊn.səm/', 'B2', 'cô đơn; buồn tủi; hiu quạnh; vắng vẻ', 'adj.', 'lonesomeness (n.)', 'Đồng nghĩa: lonely', 'Phổ biến hơn trong tiếng Anh-Mỹ; lonely thông dụng hơn, alone chỉ dùng để chỉ sự đơn độc một mình.', 'I felt lonesome after my sister moved away.', NULL, 'Tôi cảm thấy cô đơn sau khi chị gái chuyển đi.', '{"wordId":"lonesome","ukIpa":"/ˈləʊn.səm/","usIpa":"/ˈloʊn.səm/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"Feeling unhappy because you lack company","vi":"cô đơn; buồn tủi"},{"pos":"adj.","en":"Quiet and remote, with few or no people","vi":"hiu quạnh; vắng vẻ"}],"examples":[{"en":"I felt lonesome after my sister moved away.","vi":"Tôi cảm thấy cô đơn sau khi chị gái chuyển đi.","audioKind":"ex"},{"en":"Older adults may feel lonesome after retirement, especially if they have few opportunities for regular social contact.","vi":"Người lớn tuổi có thể cảm thấy cô đơn sau khi nghỉ hưu, đặc biệt là khi họ ít có cơ hội giao social thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"feel lonesome","vi":"cảm thấy cô đơn"},{"en":"a lonesome road","vi":"con đường hiu quạnh"}],"wordFamily":["lonesomeness (n.)"],"synonyms":["lonely"],"antonyms":[],"tipVi":"Phổ biến hơn trong tiếng Anh-Mỹ; lonely thông dụng hơn, alone chỉ dùng để chỉ sự đơn độc một mình.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_farewell', 'en-b2-42', 'farewell', '/ˌferˈwel/', 'B2', 'sự từ biệt; lời chia tay; tạm biệt; chúc bình an; mang tính chia tay; dùng trong tiễn biệt', 'n.', NULL, 'Đồng nghĩa: goodbye · Trái nghĩa: welcome', 'Từ này mang tính trang trọng hơn "goodbye", thường dùng trong các dịp chia tay lâu dài hoặc mang tính nghi thức.', 'We gathered at the station for a final farewell.', NULL, 'Chúng tôi tập trung tại nhà ga để nói lời chia tay cuối cùng.', '{"wordId":"farewell","ukIpa":"/ˌfeəˈwel/","usIpa":"/ˌferˈwel/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"An act of saying goodbye, especially before a long separation.","vi":"sự từ biệt; lời chia tay"},{"pos":"int.","en":"Used to say goodbye in a formal or emotional way.","vi":"tạm biệt; chúc bình an"},{"pos":"adj.","en":"Held or given to mark someone''s departure.","vi":"mang tính chia tay; dùng trong tiễn biệt"}],"examples":[{"en":"We gathered at the station for a final farewell.","vi":"Chúng tôi tập trung tại nhà ga để nói lời chia tay cuối cùng.","audioKind":"ex"},{"en":"A farewell ceremony can help graduating students reflect on their achievements and prepare for future challenges.","vi":"Một buổi lễ chia tay có thể giúp các sinh viên tốt nghiệp nhìn lại những thành quả của mình và chuẩn bị sẵn sàng cho những thử thách trong tương lai.","audioKind":"ex2"}],"collocations":[{"en":"a farewell party","vi":"bữa tiệc chia tay"},{"en":"bid someone farewell","vi":"nói lời từ biệt với ai"},{"en":"a fond farewell","vi":"một lời từ biệt đầy lưu luyến"}],"wordFamily":[],"synonyms":["goodbye"],"antonyms":["welcome"],"tipVi":"Từ này mang tính trang trọng hơn \"goodbye\", thường dùng trong các dịp chia tay lâu dài hoặc mang tính nghi thức.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deeply', 'en-b2-42', 'deeply', '/ˈdiːpli/', 'B2', 'vô cùng, hết sức, sâu sắc (về cảm xúc hoặc niềm tin); vào sâu bên trong, ở tầng sâu', 'adv.', 'deep (adj.), depth (n.), deepen (v.)', 'Đồng nghĩa: profoundly', 'Khi diễn tả mức độ, từ này thường đi kèm với các từ chỉ cảm xúc, chẳng hạn như "deeply worried".', 'I was deeply touched by your thoughtful gift.', NULL, 'Tôi vô cùng cảm động trước món quà chu đáo của bạn.', '{"wordId":"deeply","ukIpa":"/ˈdiːpli/","usIpa":"/ˈdiːpli/","cefr":"B2","topic":"emotion","senses":[{"pos":"adv.","en":"Very much, especially in relation to feelings or beliefs","vi":"vô cùng, hết sức, sâu sắc (về cảm xúc hoặc niềm tin)"},{"pos":"adv.","en":"Far into something or a long way below the surface","vi":"vào sâu bên trong, ở tầng sâu"}],"examples":[{"en":"I was deeply touched by your thoughtful gift.","vi":"Tôi vô cùng cảm động trước món quà chu đáo của bạn.","audioKind":"ex"},{"en":"Many residents are deeply concerned about the effects of air pollution on their children''s health.","vi":"Nhiều cư dân đang vô cùng lo ngại về những tác động của ô nhiễm không khí đối với sức khỏe của con cái họ.","audioKind":"ex2"}],"collocations":[{"en":"deeply concerned","vi":"vô cùng lo lắng"},{"en":"deeply rooted","vi":"bám rễ sâu, căn cơ"},{"en":"breathe deeply","vi":"hít thở sâu"},{"en":"deeply affected","vi":"bị ảnh hưởng sâu sắc"}],"wordFamily":["deep (adj.)","depth (n.)","deepen (v.)"],"synonyms":["profoundly"],"antonyms":[],"tipVi":"Khi diễn tả mức độ, từ này thường đi kèm với các từ chỉ cảm xúc, chẳng hạn như \"deeply worried\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rage', 'en-b2-42', 'rage', '/reɪdʒ/', 'B2', 'cơn thịnh nộ; sự tức giận tột độ; nổi giận đùng đùng; lôi đình tức giận; bùng nổ; hoành hành dữ dội (gây nguy hiểm hoặc hỗn loạn)', 'n.', 'raging (adj.)', 'Đồng nghĩa: fury, anger · Trái nghĩa: calm', 'rage mang sắc thái mạnh mẽ hơn anger; cụm từ all the rage có nghĩa là "phổ biến rộng rãi; thịnh hành".', 'He shook with rage when he discovered his broken bicycle.', NULL, 'Anh ấy run lên vì tức giận khi phát hiện chiếc xe đạp của mình bị hỏng.', '{"wordId":"rage","ukIpa":"/reɪdʒ/","usIpa":"/reɪdʒ/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"An extremely strong feeling of anger.","vi":"cơn thịnh nộ; sự tức giận tột độ"},{"pos":"v.","en":"Express extreme anger in a fierce or uncontrolled way.","vi":"nổi giận đùng đùng; lôi đình tức giận"},{"pos":"v.","en":"Continue with great force, causing danger or disruption.","vi":"bùng nổ; hoành hành dữ dội (gây nguy hiểm hoặc hỗn loạn)"}],"examples":[{"en":"He shook with rage when he discovered his broken bicycle.","vi":"Anh ấy run lên vì tức giận khi phát hiện chiếc xe đạp của mình bị hỏng.","audioKind":"ex"},{"en":"As wildfires rage across dry regions, local authorities must coordinate evacuations and provide temporary accommodation.","vi":"Khi cháy rừng hoành hành khắp các khu vực khô hạn, chính quyền địa phương phải điều phối việc sơ tán và cung cấp chỗ ở tạm thời.","audioKind":"ex2"}],"collocations":[{"en":"fly into a rage","vi":"nổi cơn thịnh nộ"},{"en":"shake with rage","vi":"run lên vì giận"},{"en":"road rage","vi":"cơn giận khi lái xe"},{"en":"a storm rages","vi":"bão táp hoành hành"}],"wordFamily":["raging (adj.)"],"synonyms":["fury","anger"],"antonyms":["calm"],"tipVi":"rage mang sắc thái mạnh mẽ hơn anger; cụm từ all the rage có nghĩa là \"phổ biến rộng rãi; thịnh hành\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disapproval', 'en-b2-42', 'disapproval', '/ˌdɪsəˈpruːvəl/', 'B2', 'sự không đồng tình; sự phản đối', 'n.', 'disapprove (v.), disapproving (adj.), approval (n.), approve (v.)', 'Đồng nghĩa: displeasure · Trái nghĩa: approval', 'Thường là danh từ không đếm được; việc không đồng tình với cái gì dùng disapproval of.', 'Dad shook his head in disapproval at my muddy shoes.', NULL, 'Bố lắc đầu tỏ vẻ không bằng lòng với đôi giày dính đầy bùn của tôi.', '{"wordId":"disapproval","ukIpa":"/ˌdɪsəˈpruːvəl/","usIpa":"/ˌdɪsəˈpruːvəl/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"The feeling that someone or something is wrong or unacceptable.","vi":"sự không đồng tình; sự phản đối"}],"examples":[{"en":"Dad shook his head in disapproval at my muddy shoes.","vi":"Bố lắc đầu tỏ vẻ không bằng lòng với đôi giày dính đầy bùn của tôi.","audioKind":"ex"},{"en":"Public disapproval of excessive packaging has encouraged some retailers to introduce reusable containers and reduce plastic waste.","vi":"Sự phản đối của công chúng đối với tình trạng đóng gói quá mức đã khuyến khích một số nhà bán lẻ áp dụng các loại hộp đựng tái sử dụng và giảm thiểu rác thải nhựa.","audioKind":"ex2"}],"collocations":[{"en":"express disapproval","vi":"bày tỏ sự không đồng tình"},{"en":"disapproval of something","vi":"sự không đồng tình với điều gì"},{"en":"a look of disapproval","vi":"ánh mắt không bằng lòng"},{"en":"public disapproval","vi":"sự phản đối từ công chúng"}],"wordFamily":["disapprove (v.)","disapproving (adj.)","approval (n.)","approve (v.)"],"synonyms":["displeasure"],"antonyms":["approval"],"tipVi":"Thường là danh từ không đếm được; việc không đồng tình với cái gì dùng disapproval of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sigh', 'en-b2-42', 'sigh', '/saɪ/', 'B2', 'thở dài; tiếng thở dài', 'v.', NULL, NULL, 'Âm ''gh'' là câm; tiếng thở dài cũng có thể diễn tả sự thư giãn, không nhất thiết lúc nào cũng buồn bã.', 'Dad sighed when he saw the muddy floor.', NULL, 'Bố thở dài thườn thượt khi nhìn thấy sàn nhà dính đầy bùn.', '{"wordId":"sigh","ukIpa":"/saɪ/","usIpa":"/saɪ/","cefr":"B2","topic":"emotion","senses":[{"pos":"v.","en":"To breathe out slowly and audibly, expressing feelings","vi":"thở dài"},{"pos":"n.","en":"A slow, audible breath expressing sadness, tiredness, or relief","vi":"tiếng thở dài"}],"examples":[{"en":"Dad sighed when he saw the muddy floor.","vi":"Bố thở dài thườn thượt khi nhìn thấy sàn nhà dính đầy bùn.","audioKind":"ex"},{"en":"Many commuters breathe a sigh of relief when reliable public transport reduces the stress of their daily journeys.","vi":"Nhiều người đi làm thở phào nhẹ nhõm khi hệ thống giao thông công cộng đáng tin cậy giúp giảm bớt căng thẳng trong những chuyến đi lại hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"a sigh of relief","vi":"tiếng thở phào nhẹ nhõm"},{"en":"let out a sigh","vi":"bật ra tiếng thở dài"},{"en":"sigh deeply","vi":"thở dài sâu"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Âm ''gh'' là câm; tiếng thở dài cũng có thể diễn tả sự thư giãn, không nhất thiết lúc nào cũng buồn bã.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unbearable', 'en-b2-42', 'unbearable', '/ʌnˈberəbl/', 'B2', 'không thể chịu đựng được; quá mức', 'adj.', 'bear (v.), bearable (adj.), unbearably (adv.)', 'Đồng nghĩa: intolerable, insufferable · Trái nghĩa: bearable, tolerable', 'Từ bear ở đây mang nghĩa là chịu đựng; unbearable có sắc thái biểu cảm rất mạnh.', 'The heat became unbearable, so we rested in the shade.', NULL, 'Trời nóng không chịu nổi, nên chúng tôi vào bóng râm nghỉ ngơi.', '{"wordId":"unbearable","ukIpa":"/ʌnˈbeərəbl/","usIpa":"/ʌnˈberəbl/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"Too unpleasant, painful, or intense to tolerate","vi":"không thể chịu đựng được; quá mức"}],"examples":[{"en":"The heat became unbearable, so we rested in the shade.","vi":"Trời nóng không chịu nổi, nên chúng tôi vào bóng râm nghỉ ngơi.","audioKind":"ex"},{"en":"Without adequate ventilation, summer temperatures in crowded housing can become unbearable, especially for older residents.","vi":"Nếu thiếu hệ thống thông gió phù hợp, nhiệt độ mùa hè trong những khu nhà ở đông đúc có thể trở nên ngột ngạt không thể chịu nổi, đặc biệt là đối với cư dân cao tuổi.","audioKind":"ex2"}],"collocations":[{"en":"unbearable pain","vi":"cơn đau không thể chịu đựng"},{"en":"unbearable heat","vi":"cái nóng như thiêu đốt"},{"en":"unbearable noise","vi":"tiếng ồn đinh tai nhức óc"}],"wordFamily":["bear (v.)","bearable (adj.)","unbearably (adv.)"],"synonyms":["intolerable","insufferable"],"antonyms":["bearable","tolerable"],"tipVi":"Từ bear ở đây mang nghĩa là chịu đựng; unbearable có sắc thái biểu cảm rất mạnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dread', 'en-b2-42', 'dread', '/dred/', 'B2', 'sợ hãi; lo sợ; nỗi sợ; mối lo âu', 'v.', 'dreadful (adj.), dreadfully (adv.), dreaded (adj.)', 'Đồng nghĩa: fear', 'Diễn tả sự e ngại khi phải làm việc gì thường dùng cấu trúc dread doing.', 'I dread driving on icy roads after dark.', NULL, 'Tôi rất sợ lái xe trên những con đường đóng băng sau khi trời tối.', '{"wordId":"dread","ukIpa":"/dred/","usIpa":"/dred/","cefr":"B2","topic":"emotion","senses":[{"pos":"v.","en":"Feel very worried about something unpleasant that may happen.","vi":"sợ hãi; lo sợ"},{"pos":"n.","en":"Strong fear or worry about something that may happen.","vi":"nỗi sợ; mối lo âu"}],"examples":[{"en":"I dread driving on icy roads after dark.","vi":"Tôi rất sợ lái xe trên những con đường đóng băng sau khi trời tối.","audioKind":"ex"},{"en":"Many employees dread losing their jobs when new technologies begin to replace familiar tasks in the workplace.","vi":"Nhiều nhân viên lo sợ bị mất việc khi các công nghệ mới bắt đầu thay thế những công việc quen thuộc tại nơi làm việc.","audioKind":"ex2"}],"collocations":[{"en":"dread doing something","vi":"sợ phải làm điều gì đó"},{"en":"a sense of dread","vi":"cảm giác sợ hãi"},{"en":"fill someone with dread","vi":"làm ai đó tràn ngập nỗi sợ"}],"wordFamily":["dreadful (adj.)","dreadfully (adv.)","dreaded (adj.)"],"synonyms":["fear"],"antonyms":[],"tipVi":"Diễn tả sự e ngại khi phải làm việc gì thường dùng cấu trúc dread doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_supportive', 'en-b2-42', 'supportive', '/səˈpɔːrtɪv/', 'B2', 'ủng hộ; hỗ trợ; khuyến khích', 'adj.', 'support (v.), support (n.), supporter (n.)', 'Đồng nghĩa: encouraging, helpful, understanding · Trái nghĩa: unsupportive', 'Thường dùng be supportive of để diễn tả việc ủng hộ ai đó hoặc việc gì đó.', 'My supportive sister helped me practise before the interview.', NULL, 'Người chị luôn ủng hộ tôi đã giúp tôi luyện tập trước buổi phỏng vấn.', '{"wordId":"supportive","ukIpa":"/səˈpɔːtɪv/","usIpa":"/səˈpɔːrtɪv/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"giving help, encouragement, or understanding","vi":"ủng hộ; hỗ trợ; khuyến khích"}],"examples":[{"en":"My supportive sister helped me practise before the interview.","vi":"Người chị luôn ủng hộ tôi đã giúp tôi luyện tập trước buổi phỏng vấn.","audioKind":"ex"},{"en":"A supportive classroom environment encourages students to ask questions without worrying about making mistakes.","vi":"Một môi trường lớp học mang tính hỗ trợ khuyến khích học sinh đặt câu hỏi mà không sợ mắc lỗi.","audioKind":"ex2"}],"collocations":[{"en":"a supportive family","vi":"gia đình luôn ủng hộ"},{"en":"a supportive environment","vi":"môi trường mang tính hỗ trợ"},{"en":"supportive of","vi":"ủng hộ..."}],"wordFamily":["support (v.)","support (n.)","supporter (n.)"],"synonyms":["encouraging","helpful","understanding"],"antonyms":["unsupportive"],"tipVi":"Thường dùng be supportive of để diễn tả việc ủng hộ ai đó hoặc việc gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_utterly', 'en-b2-42', 'utterly', '/ˈʌtərli/', 'B2', 'hoàn toàn; cực kỳ; tuyệt đối', 'adv.', 'utter (adj.)', 'Đồng nghĩa: completely, totally, entirely · Trái nghĩa: partly', 'Thường bổ nghĩa cho các tính từ mang sắc thái mạnh hoặc tiêu cực, chẳng hạn như impossible, ridiculous.', 'I was utterly exhausted after carrying those heavy boxes.', NULL, 'Tôi hoàn toàn kiệt sức sau khi khiêng những chiếc hộp nặng đó.', '{"wordId":"utterly","ukIpa":"/ˈʌtəli/","usIpa":"/ˈʌtərli/","cefr":"B2","topic":"emotion","senses":[{"pos":"adv.","en":"completely, used to strongly emphasise a description","vi":"hoàn toàn; cực kỳ; tuyệt đối"}],"examples":[{"en":"I was utterly exhausted after carrying those heavy boxes.","vi":"Tôi hoàn toàn kiệt sức sau khi khiêng những chiếc hộp nặng đó.","audioKind":"ex"},{"en":"Without reliable internet access, some rural students feel utterly excluded from opportunities offered by online education.","vi":"Do thiếu kết nối internet ổn định, một số học sinh vùng sâu vùng xa cảm thấy hoàn toàn bị loại khỏi các cơ hội mà giáo dục trực tuyến mang lại.","audioKind":"ex2"}],"collocations":[{"en":"utterly exhausted","vi":"kiệt sức hoàn toàn"},{"en":"utterly impossible","vi":"hoàn toàn bất khả thi"},{"en":"utterly ridiculous","vi":"vô lý hết sức"}],"wordFamily":["utter (adj.)"],"synonyms":["completely","totally","entirely"],"antonyms":["partly"],"tipVi":"Thường bổ nghĩa cho các tính từ mang sắc thái mạnh hoặc tiêu cực, chẳng hạn như impossible, ridiculous.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_astonish', 'en-b2-42', 'astonish', '/əˈstɑːnɪʃ/', 'B2', 'làm ngạc nhiên; làm kinh ngạc', 'v.', 'astonished (adj.), astonishing (adj.), astonishment (n.), astonishingly (adv.)', 'Đồng nghĩa: amaze, astound', 'Dùng astonished để chỉ người cảm thấy ngạc nhiên, và astonishing để chỉ sự việc gây ngạc nhiên.', 'The magician''s final trick astonished everyone in the room.', NULL, 'Màn ảo thuật cuối cùng của nhà ảo thuật đã khiến tất cả mọi người trong phòng kinh ngạc.', '{"wordId":"astonish","ukIpa":"/əˈstɒnɪʃ/","usIpa":"/əˈstɑːnɪʃ/","cefr":"B2","topic":"emotion","senses":[{"pos":"v.","en":"To surprise someone very much.","vi":"làm ngạc nhiên; làm kinh ngạc"}],"examples":[{"en":"The magician''s final trick astonished everyone in the room.","vi":"Màn ảo thuật cuối cùng của nhà ảo thuật đã khiến tất cả mọi người trong phòng kinh ngạc.","audioKind":"ex"},{"en":"The speed at which damaged forests recover can astonish even experienced environmental researchers.","vi":"Tốc độ phục hồi của các khu rừng bị tàn phá thậm chí có thể làm bất ngờ cả những nhà nghiên cứu môi trường dày dặn kinh nghiệm.","audioKind":"ex2"}],"collocations":[{"en":"astonish an audience","vi":"làm khán giả trầm trồ"},{"en":"be astonished at","vi":"cảm thấy ngạc nhiên về"},{"en":"be astonished to discover","vi":"kinh ngạc khi phát hiện"}],"wordFamily":["astonished (adj.)","astonishing (adj.)","astonishment (n.)","astonishingly (adv.)"],"synonyms":["amaze","astound"],"antonyms":[],"tipVi":"Dùng astonished để chỉ người cảm thấy ngạc nhiên, và astonishing để chỉ sự việc gây ngạc nhiên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bitterly', 'en-b2-42', 'bitterly', '/ˈbɪtɚli/', 'B2', 'cay đắng; đầy uất ức; vô cùng (thất vọng/buồn bã); cực kỳ; rét buốt (chỉ thời tiết lạnh hoặc cảm giác khó chịu)', 'adv.', 'bitter (adj.), bitterness (n.)', 'Đồng nghĩa: resentfully, deeply', 'Thường đi với cảm xúc tiêu cực hoặc từ cold, không dùng chung cho các tính từ tích cực.', 'He complained bitterly when his bicycle was stolen again.', NULL, 'Anh ấy phàn nàn một cách cay đắng khi chiếc xe đạp của mình lại bị trộm mất.', '{"wordId":"bitterly","ukIpa":"/ˈbɪtəli/","usIpa":"/ˈbɪtɚli/","cefr":"B2","topic":"emotion","senses":[{"pos":"adv.","en":"with strong sadness, anger, or disappointment","vi":"cay đắng; đầy uất ức; vô cùng (thất vọng/buồn bã)"},{"pos":"adv.","en":"extremely, especially when describing cold or unpleasant feelings","vi":"cực kỳ; rét buốt (chỉ thời tiết lạnh hoặc cảm giác khó chịu)"}],"examples":[{"en":"He complained bitterly when his bicycle was stolen again.","vi":"Anh ấy phàn nàn một cách cay đắng khi chiếc xe đạp của mình lại bị trộm mất.","audioKind":"ex"},{"en":"During bitterly cold winters, poorly insulated homes increase energy costs and put vulnerable residents'' health at risk.","vi":"Trong những mùa đông lạnh giá buốt, những ngôiบ้าน kém cách nhiệt làm tăng chi phí năng lượng và đe dọa sức khỏe của những cư dân dễ bị tổn thương.","audioKind":"ex2"}],"collocations":[{"en":"bitterly disappointed","vi":"vô cùng thất vọng"},{"en":"bitterly cold","vi":"lạnh buốt"},{"en":"complain bitterly","vi":"phàn nàn cay đắng"},{"en":"weep bitterly","vi":"khóc nức nở"}],"wordFamily":["bitter (adj.)","bitterness (n.)"],"synonyms":["resentfully","deeply"],"antonyms":[],"tipVi":"Thường đi với cảm xúc tiêu cực hoặc từ cold, không dùng chung cho các tính từ tích cực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disgust', 'en-b2-42', 'disgust', '/dɪsˈɡʌst/', 'B2', 'sự ghê tởm; sự kinh tởm; sự bất bình; làm ghê tởm; làm kinh tởm; gây phản cảm', 'n.', 'disgusted (adj.), disgusting (adj.)', 'Đồng nghĩa: revulsion, loathing', 'disgusted dùng để tả cảm xúc của con người; disgusting dùng để tả sự việc gây khó chịu, ghê tởm.', 'She wrinkled her nose in disgust at the rotten fruit.', NULL, 'Cô ấy nhăn mũi vì ghê tởm khi nhìn thấy quả lê bị thối.', '{"wordId":"disgust","ukIpa":"/dɪsˈɡʌst/","usIpa":"/dɪsˈɡʌst/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"a strong feeling of dislike caused by something unpleasant","vi":"sự ghê tởm; sự kinh tởm; sự bất bình"},{"pos":"v.","en":"to make someone feel strong dislike or revulsion","vi":"làm ghê tởm; làm kinh tởm; gây phản cảm"}],"examples":[{"en":"She wrinkled her nose in disgust at the rotten fruit.","vi":"Cô ấy nhăn mũi vì ghê tởm khi nhìn thấy quả lê bị thối.","audioKind":"ex"},{"en":"Residents expressed disgust at the illegal dumping of household waste beside the local river.","vi":"Cư dân bày tỏ sự phẫn nộ và bất bình trước việc đổ trộm rác thải sinh hoạt bừa bãi bên dòng sông địa phương.","audioKind":"ex2"}],"collocations":[{"en":"in disgust","vi":"với vẻ đầy ghê tởm"},{"en":"express disgust","vi":"tỏ1 thái độ bất bình"},{"en":"disgust at","vi":"sự ghê tởm đối với"}],"wordFamily":["disgusted (adj.)","disgusting (adj.)"],"synonyms":["revulsion","loathing"],"antonyms":[],"tipVi":"disgusted dùng để tả cảm xúc của con người; disgusting dùng để tả sự việc gây khó chịu, ghê tởm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_willingness', 'en-b2-42', 'willingness', '/ˈwɪlɪŋnəs/', 'B2', 'sự sẵn lòng; tinh thần tự nguyện', 'n.', 'willing (adj.), willingly (adv.), unwilling (adj.), unwillingness (n.)', 'Đồng nghĩa: readiness · Trái nghĩa: unwillingness, reluctance', 'Là danh từ không đếm được, thường đi với to do để chỉ sự sẵn sàng làm việc gì đó.', 'Her willingness to help made the move much easier.', NULL, 'Sự sẵn lòng giúp đỡ của cô ấy đã khiến việc chuyển nhà trở nên nhẹ nhàng hơn rất nhiều.', '{"wordId":"willingness","ukIpa":"/ˈwɪlɪŋnəs/","usIpa":"/ˈwɪlɪŋnəs/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"The readiness to do something without needing to be forced.","vi":"sự sẵn lòng; tinh thần tự nguyện"}],"examples":[{"en":"Her willingness to help made the move much easier.","vi":"Sự sẵn lòng giúp đỡ của cô ấy đã khiến việc chuyển nhà trở nên nhẹ nhàng hơn rất nhiều.","audioKind":"ex"},{"en":"Students'' willingness to ask questions often increases when teachers create a supportive classroom environment.","vi":"Sự sẵn sàng đặt câu hỏi của học sinh thường tăng lên khi giáo viên tạo ra một môi trường lớp học mang tính hỗ trợ.","audioKind":"ex2"}],"collocations":[{"en":"willingness to learn","vi":"ý chí học tập"},{"en":"show willingness","vi":"thể hiện sự sẵn lòng"},{"en":"a willingness to cooperate","vi":"sự sẵn sàng hợp tác"}],"wordFamily":["willing (adj.)","willingly (adv.)","unwilling (adj.)","unwillingness (n.)"],"synonyms":["readiness"],"antonyms":["unwillingness","reluctance"],"tipVi":"Là danh từ không đếm được, thường đi với to do để chỉ sự sẵn sàng làm việc gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_frustration', 'en-b2-42', 'frustration', '/frʌˈstreɪʃən/', 'B2', 'sự thất vọng; nỗi bực bội; cảm giác chán nản', 'n.', 'frustrate (v.), frustrated (adj.), frustrating (adj.)', 'Đồng nghĩa: annoyance, exasperation · Trái nghĩa: satisfaction', 'Người cảm thấy chán nản dùng "frustrated"; sự việc gây ra cảm giác đó dùng "frustrating".', 'She sighed in frustration when the printer jammed again.', NULL, 'Cô ấy thở dài đầy bực bội khi máy in lại bị kẹt giấy.', '{"wordId":"frustration","ukIpa":"/frʌˈstreɪʃən/","usIpa":"/frʌˈstreɪʃən/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"Annoyance caused by being unable to achieve what you want.","vi":"sự thất vọng; nỗi bực bội; cảm giác chán nản"}],"examples":[{"en":"She sighed in frustration when the printer jammed again.","vi":"Cô ấy thở dài đầy bực bội khi máy in lại bị kẹt giấy.","audioKind":"ex"},{"en":"Repeated delays in public transport can increase commuters'' frustration and reduce their confidence in local services.","vi":"Việc giao thông công cộng bị trì hoãn liên tục có thể làm tăng sự thất vọng của người đi làm và làm giảm niềm tin của họ vào các dịch vụ địa phương.","audioKind":"ex2"}],"collocations":[{"en":"in frustration","vi":"trong sự bực bội"},{"en":"a sense of frustration","vi":"cảm giác thất vọng"},{"en":"express frustration","vi":"bày tỏ sự bất bình"},{"en":"growing frustration","vi":"sự thất vọng ngày càng tăng"}],"wordFamily":["frustrate (v.)","frustrated (adj.)","frustrating (adj.)"],"synonyms":["annoyance","exasperation"],"antonyms":["satisfaction"],"tipVi":"Người cảm thấy chán nản dùng \"frustrated\"; sự việc gây ra cảm giác đó dùng \"frustrating\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_42_1', 'en-b2-42', 'Cách dùng “farewell” (n.) — sự từ biệt; lời chia tay', 'a farewell party  ·  bid someone farewell  ·  a fond farewell', 'Từ này mang tính trang trọng hơn "goodbye", thường dùng trong các dịp chia tay lâu dài hoặc mang tính nghi thức.', 'Đồng nghĩa: goodbye · Trái nghĩa: welcome', '[{"hanzi":"We gathered at the station for a final farewell.","pinyin":"","meaning":"Chúng tôi tập trung tại nhà ga để nói lời chia tay cuối cùng."},{"hanzi":"A farewell ceremony can help graduating students reflect on their achievements and prepare for future challenges.","pinyin":"","meaning":"Một buổi lễ chia tay có thể giúp các sinh viên tốt nghiệp nhìn lại những thành quả của mình và chuẩn bị sẵn sàng cho những thử thách trong tương lai."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_42_2', 'en-b2-42', 'Cách dùng “utterly” (adv.) — hoàn toàn; cực kỳ; tuyệt đối', 'utterly exhausted  ·  utterly impossible  ·  utterly ridiculous', 'Thường bổ nghĩa cho các tính từ mang sắc thái mạnh hoặc tiêu cực, chẳng hạn như impossible, ridiculous.', 'Họ từ (Word Family): utter (adj.) | Đồng nghĩa: completely, totally, entirely · Trái nghĩa: partly', '[{"hanzi":"I was utterly exhausted after carrying those heavy boxes.","pinyin":"","meaning":"Tôi hoàn toàn kiệt sức sau khi khiêng những chiếc hộp nặng đó."},{"hanzi":"Without reliable internet access, some rural students feel utterly excluded from opportunities offered by online education.","pinyin":"","meaning":"Do thiếu kết nối internet ổn định, một số học sinh vùng sâu vùng xa cảm thấy hoàn toàn bị loại khỏi các cơ hội mà giáo dục trực tuyến mang lại."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_42_3', 'en-b2-42', 'Cách dùng “rage” (n.) — cơn thịnh nộ; sự tức giận tột độ', 'fly into a rage  ·  shake with rage  ·  road rage', 'rage mang sắc thái mạnh mẽ hơn anger; cụm từ all the rage có nghĩa là "phổ biến rộng rãi; thịnh hành".', 'Họ từ (Word Family): raging (adj.) | Đồng nghĩa: fury, anger · Trái nghĩa: calm', '[{"hanzi":"He shook with rage when he discovered his broken bicycle.","pinyin":"","meaning":"Anh ấy run lên vì tức giận khi phát hiện chiếc xe đạp của mình bị hỏng."},{"hanzi":"As wildfires rage across dry regions, local authorities must coordinate evacuations and provide temporary accommodation.","pinyin":"","meaning":"Khi cháy rừng hoành hành khắp các khu vực khô hạn, chính quyền địa phương phải điều phối việc sơ tán và cung cấp chỗ ở tạm thời."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_42_4', 'en-b2-42', 'Cách dùng “sigh” (v.) — thở dài', 'a sigh of relief  ·  let out a sigh  ·  sigh deeply', 'Âm ''gh'' là câm; tiếng thở dài cũng có thể diễn tả sự thư giãn, không nhất thiết lúc nào cũng buồn bã.', NULL, '[{"hanzi":"Dad sighed when he saw the muddy floor.","pinyin":"","meaning":"Bố thở dài thườn thượt khi nhìn thấy sàn nhà dính đầy bùn."},{"hanzi":"Many commuters breathe a sigh of relief when reliable public transport reduces the stress of their daily journeys.","pinyin":"","meaning":"Nhiều người đi làm thở phào nhẹ nhõm khi hệ thống giao thông công cộng đáng tin cậy giúp giảm bớt căng thẳng trong những chuyến đi lại hàng ngày."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_42_1', 'en-b2-42', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_42_1_1', 'ten_b2_42_1', 'impatience', 'She tapped her foot with impatience as the queue stalled.', 'She tapped her foot with impatience as the queue stalled.', '/ɪmˈpeɪʃns/', 'Cô ấy bứt rứt lấy chân gõ xuống đất khi hàng người cứ đứng ì ra.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_42_1_2', 'ten_b2_42_1', 'bravery', 'The little girl showed bravery during her first injection.', 'The little girl showed bravery during her first injection.', '/ˈbreɪvəri/', 'Cô bé đã thể hiện sự dũng cảm trong lần tiêm đầu tiên của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_42_1_3', 'ten_b2_42_1', 'grumble', 'My brother grumbled about washing the dishes again.', 'My brother grumbled about washing the dishes again.', '/ˈɡrʌmbəl/', 'Anh trai tôi lại cằn nhằn về việc phải rửa bát.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_42_1_4', 'ten_b2_42_1', 'relieved', 'I felt relieved when I finally found my keys.', 'I felt relieved when I finally found my keys.', '/rɪˈliːvd/', 'Tôi cảm thấy nhẹ nhõm khi cuối cùng cũng tìm thấy chìa khóa của mình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_42_1_5', 'ten_b2_42_1', 'determination', 'Despite the rain, she finished the race with determination.', 'Despite the rain, she finished the race with determination.', '/dɪˌtɝːmɪˈneɪʃən/', 'Bất chấp trời mưa, cô ấy vẫn hoàn thành cuộc đua với đầy sự quyết tâm.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
