INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_42_1_7', 'ten_b2_42_1', 'fascinate', 'The colourful fish fascinated the children at the aquarium.', 'The colourful fish fascinated the children at the aquarium.', '/ˈfæsɪneɪt/', 'Những chú cá đầy màu sắc đã làm cho lũ trẻ ở thủy cung vô cùng thích thú.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_42_1_8', 'ten_b2_42_1', 'anxious', 'I felt anxious while waiting for my exam results.', 'I felt anxious while waiting for my exam results.', '/ˈæŋkʃəs/', 'Tôi cảm thấy lo lắng khi chờ đợi kết quả thi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_42_1_1', 'en-b2-42', 'ten_b2_42_1', 'listening', 'listening', 'She tapped her foot with impatience as the queue stalled.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy bứt rứt lấy chân gõ xuống đất khi hàng người cứ đứng ì ra.","Trời nóng không chịu nổi, nên chúng tôi vào bóng râm nghỉ ngơi.","Tôi hoàn toàn kiệt sức sau khi khiêng những chiếc hộp nặng đó.","Tôi rất sợ lái xe trên những con đường đóng băng sau khi trời tối."]'::jsonb, 0, 'She tapped her foot with impatience as the queue stalled. → Cô ấy bứt rứt lấy chân gõ xuống đất khi hàng người cứ đứng ì ra.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_42_1_2', 'en-b2-42', 'ten_b2_42_1', 'listening', 'listening', 'The little girl showed bravery during her first injection.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi cảm thấy nhẹ nhõm khi cuối cùng cũng tìm thấy chìa khóa của mình.","Tôi rất sợ lái xe trên những con đường đóng băng sau khi trời tối.","Cô bé đã thể hiện sự dũng cảm trong lần tiêm đầu tiên của mình.","Sự sẵn lòng giúp đỡ của cô ấy đã khiến việc chuyển nhà trở nên nhẹ nhàng hơn rất nhiều."]'::jsonb, 2, 'The little girl showed bravery during her first injection. → Cô bé đã thể hiện sự dũng cảm trong lần tiêm đầu tiên của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_42_1_3', 'en-b2-42', 'ten_b2_42_1', 'listening', 'listening', 'My brother grumbled about washing the dishes again.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Trời nóng không chịu nổi, nên chúng tôi vào bóng râm nghỉ ngơi.","Anh trai tôi lại cằn nhằn về việc phải rửa bát.","Tôi vô cùng cảm động trước món quà chu đáo của bạn.","Bố lắc đầu tỏ vẻ không bằng lòng với đôi giày dính đầy bùn của tôi."]'::jsonb, 1, 'My brother grumbled about washing the dishes again. → Anh trai tôi lại cằn nhằn về việc phải rửa bát.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_42_2', 'en-b2-42', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_42_2_1', 'ten_b2_42_2', 'impatience', 'Growing impatience with unreliable public transport may encourage commuters to use private cars, increasing urban congestion.', 'Growing impatience with unreliable public transport may encourage commuters to use private cars, increasing urban congestion.', '/ɪmˈpeɪʃns/', 'Sự thiếu kiên nhẫn ngày càng tăng đối với hệ thống giao thông công cộng kém tin cậy có thể thúc đẩy người đi làm chuyển sang dùng ô tô riêng, làm trầm trọng thêm tình trạng tắc nghẽn đô thị.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_42_2_2', 'ten_b2_42_2', 'bravery', 'Emergency workers demonstrate remarkable bravery when they enter dangerous areas to rescue people after natural disasters.', 'Emergency workers demonstrate remarkable bravery when they enter dangerous areas to rescue people after natural disasters.', '/ˈbreɪvəri/', 'Các nhân viên cứu hộ đã thể hiện lòng dũng cảm phi thường khi tiến vào các khu vực hiểm trở để giải cứu người dân sau thảm họa thiên nhiên.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_42_2_3', 'ten_b2_42_2', 'grumble', 'Although commuters often grumble about delays, many still prefer public transport because it reduces travel costs.', 'Although commuters often grumble about delays, many still prefer public transport because it reduces travel costs.', '/ˈɡrʌmbəl/', 'Mặc dù những người đi làm thường phàn nàn về tình trạng chậm chuyến, nhiều người vẫn thích phương tiện công cộng hơn vì nó giúp giảm chi phí đi lại.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_42_2_4', 'ten_b2_42_2', 'relieved', 'Residents were relieved to hear that the local hospital would remain open despite proposed budget cuts.', 'Residents were relieved to hear that the local hospital would remain open despite proposed budget cuts.', '/rɪˈliːvd/', 'Cư dân đã rất yên tâm khi nghe tin bệnh viện địa phương vẫn tiếp tục hoạt động bất chấp các đề xuất cắt giảm ngân sách.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_42_2_5', 'ten_b2_42_2', 'determination', 'Students who show determination are often better able to overcome academic setbacks and achieve their goals.', 'Students who show determination are often better able to overcome academic setbacks and achieve their goals.', '/dɪˌtɝːmɪˈneɪʃən/', 'Những học sinh thể hiện ý chí quyết tâm thường có khả năng vượt qua những trở ngại trong học tập và đạt được mục tiêu của mình tốt hơn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_42_2_6', 'ten_b2_42_2', 'pathetic', 'Residents described the council''s response to repeated flooding as pathetic, demanding immediate investment in better drainage.', 'Residents described the council''s response to repeated flooding as pathetic, demanding immediate investment in better drainage.', '/pəˈθetɪk/', 'Cư dân mô tả cách phản ứng của hội đồng đối với tình trạng ngập lụt lặp đi lặp lại là vô cùng kém cỏi, đồng thời yêu cầu đầu tư ngay lập tức vào hệ thống thoát nước tốt hơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_42_2_1', 'en-b2-42', 'ten_b2_42_2', 'listening', 'listening', 'Growing impatience with unreliable public transport may encourage commuters to use private cars, increasing urban congestion.', NULL, 'Trong câu vừa nghe, từ “impatience” mang nghĩa nào sau đây?', '["cây sồi","làm quá tải; chồng chất gánh nặng","sự số ruột; sự bực bội do chờ đợi","móc treo; cọc; chốt"]'::jsonb, 2, '“impatience” (/ɪmˈpeɪʃns/): sự số ruột; sự bực bội do chờ đợi. Câu đầy đủ: Growing impatience with unreliable public transport may encourage commuters to use private cars, increasing urban congestion.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_42_2_2', 'en-b2-42', 'ten_b2_42_2', 'listening', 'listening', 'Emergency workers demonstrate remarkable bravery when they enter dangerous areas to rescue people after natural disasters.', NULL, 'Trong câu vừa nghe, từ “bravery” mang nghĩa nào sau đây?', '["ấu trĩ; trẻ con; không chín chắn","thực hiện; hoàn thành (nhiệm vụ, lời hứa, thỏa thuận)","sự dũng cảm; lòng can đảm; tính gan dạ","sự cô lập; sự tách biệt"]'::jsonb, 2, '“bravery” (/ˈbreɪvəri/): sự dũng cảm; lòng can đảm; tính gan dạ. Câu đầy đủ: Emergency workers demonstrate remarkable bravery when they enter dangerous areas to rescue people after natural disasters.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
