INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_42_1', 'en-b2-42', NULL, 'comprehensive_test', 'listening', 'impatience', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tự vệ; phòng vệ chính đáng","sự số ruột; sự bực bội do chờ đợi","chuyến tham quan; cuộc dã ngoại","gió nhẹ; cơn gió thoảng"]'::jsonb, 1, 'impatience (/ɪmˈpeɪʃns/) → sự số ruột; sự bực bội do chờ đợi; sự nôn nóng; niềm khát khao mong mỏi', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_42_2', 'en-b2-42', NULL, 'comprehensive_test', 'listening', 'The little girl showed bravery during her first injection.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy nhăn mũi vì ghê tởm khi nhìn thấy quả lê bị thối.","Trời nóng không chịu nổi, nên chúng tôi vào bóng râm nghỉ ngơi.","Những chú cá đầy màu sắc đã làm cho lũ trẻ ở thủy cung vô cùng thích thú.","Cô bé đã thể hiện sự dũng cảm trong lần tiêm đầu tiên của mình."]'::jsonb, 3, 'The little girl showed bravery during her first injection. → Cô bé đã thể hiện sự dũng cảm trong lần tiêm đầu tiên của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_42_3', 'en-b2-42', NULL, 'comprehensive_test', 'listening', 'grumble', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nhà trẻ; trường mẫu giáo","tưởng tượng; ảo tưởng; hư cấu","cằn nhằn; phàn nàn","bó hoa"]'::jsonb, 2, 'grumble (/ˈɡrʌmbəl/) → cằn nhằn; phàn nàn; lời phàn nàn; tiếng kêu ca; phát ra tiếng gầm gừ trầm thấp', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_42_4', 'en-b2-42', NULL, 'comprehensive_test', 'listening', 'I felt relieved when I finally found my keys.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Anh trai tôi lại cằn nhằn về việc phải rửa bát.","Tôi đã kìm lại được sự cám dỗ ăn thêm một miếng bánh nữa.","Người chị luôn ủng hộ tôi đã giúp tôi luyện tập trước buổi phỏng vấn.","Tôi cảm thấy nhẹ nhõm khi cuối cùng cũng tìm thấy chìa khóa của mình."]'::jsonb, 3, 'I felt relieved when I finally found my keys. → Tôi cảm thấy nhẹ nhõm khi cuối cùng cũng tìm thấy chìa khóa của mình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_42_5', 'en-b2-42', NULL, 'comprehensive_test', 'listening', 'determination', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự quyết tâm; nghị lực","nắm vững; tinh thông","thúc giục; nài nỉ; khuyên răn mạnh mẽ","phụ kiện; linh kiện bổ trợ"]'::jsonb, 0, 'determination (/dɪˌtɝːmɪˈneɪʃən/) → sự quyết tâm; nghị lực; sự xác định; sự định đoạt; sự phán quyết', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_42_6', 'en-b2-42', NULL, 'comprehensive_test', 'listening', 'The broken shower produced only a pathetic trickle.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Vòi hoa sen bị hỏng chỉ nhỏ ra một dòng nước thảm hại.","Bất chấp trời mưa, cô ấy vẫn hoàn thành cuộc đua với đầy sự quyết tâm.","Tôi hoàn toàn kiệt sức sau khi khiêng những chiếc hộp nặng đó.","Bố thở dài thườn thượt khi nhìn thấy sàn nhà dính đầy bùn."]'::jsonb, 0, 'The broken shower produced only a pathetic trickle. → Vòi hoa sen bị hỏng chỉ nhỏ ra một dòng nước thảm hại.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_42_7', 'en-b2-42', NULL, 'comprehensive_test', 'listening', 'fascinate', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["phòng khiêu vũ; vũ trường","làm say mê; thu hút sâu sắc","lúng túng; ngượng ngùng; khó xử","chín; làm cho chín"]'::jsonb, 1, 'fascinate (/ˈfæsɪneɪt/) → làm say mê; thu hút sâu sắc', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_42_8', 'en-b2-42', NULL, 'comprehensive_test', 'listening', 'I felt anxious while waiting for my exam results.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy bứt rứt lấy chân gõ xuống đất khi hàng người cứ đứng ì ra.","Tôi cảm thấy lo lắng khi chờ đợi kết quả thi.","Bất chấp trời mưa, cô ấy vẫn hoàn thành cuộc đua với đầy sự quyết tâm.","Những chú cá đầy màu sắc đã làm cho lũ trẻ ở thủy cung vô cùng thích thú."]'::jsonb, 1, 'I felt anxious while waiting for my exam results. → Tôi cảm thấy lo lắng khi chờ đợi kết quả thi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_42_9', 'en-b2-42', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “the firm intention to continue despite difficulties”?', '["lonesome","unbearable","supportive","determination"]'::jsonb, 3, 'determination (/dɪˌtɝːmɪˈneɪʃən/) → sự quyết tâm; nghị lực', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
