INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_42_18', 'en-b2-42', NULL, 'comprehensive_test', 'reading', NULL, 'Growing impatience with unreliable public transport may encourage commuters to use private cars, increasing urban congestion.', 'Dựa vào câu trên, từ “impatience” có nghĩa phù hợp nhất là gì?', '["lo lắng; bận tâm","về hướng tây; hướng tây","sự số ruột; sự bực bội do chờ đợi","nhìn chằm chằm; chăm chú"]'::jsonb, 2, 'impatience: sự số ruột; sự bực bội do chờ đợi; sự nôn nóng; niềm khát khao mong mỏi. Dịch cả câu: Sự thiếu kiên nhẫn ngày càng tăng đối với hệ thống giao thông công cộng kém tin cậy có thể thúc đẩy người đi làm chuyển sang dùng ô tô riêng, làm trầm trọng thêm tình trạng tắc nghẽn đô thị.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_42_19', 'en-b2-42', NULL, 'comprehensive_test', 'reading', NULL, 'Emergency workers demonstrate remarkable bravery when they enter dangerous areas to rescue people after natural disasters.', 'Dựa vào câu trên, từ “bravery” có nghĩa phù hợp nhất là gì?', '["sự dũng cảm; lòng can đảm; tính gan dạ","số liệu thống kê","chung; liên hợp; phối hợp","sự phân tích, sự nghiên cứu kỹ lưỡng để hiểu rõ các bộ phận hoặc ý nghĩa"]'::jsonb, 0, 'bravery: sự dũng cảm; lòng can đảm; tính gan dạ. Dịch cả câu: Các nhân viên cứu hộ đã thể hiện lòng dũng cảm phi thường khi tiến vào các khu vực hiểm trở để giải cứu người dân sau thảm họa thiên nhiên.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_42_20', 'en-b2-42', NULL, 'comprehensive_test', 'reading', NULL, 'Although commuters often grumble about delays, many still prefer public transport because it reduces travel costs.', 'Dựa vào câu trên, từ “grumble” có nghĩa phù hợp nhất là gì?', '["đang cầm quyền","cằn nhằn; phàn nàn","tôm hùm","tia sáng; chùm bức xạ"]'::jsonb, 1, 'grumble: cằn nhằn; phàn nàn; lời phàn nàn; tiếng kêu ca; phát ra tiếng gầm gừ trầm thấp. Dịch cả câu: Mặc dù những người đi làm thường phàn nàn về tình trạng chậm chuyến, nhiều người vẫn thích phương tiện công cộng hơn vì nó giúp giảm chi phí đi lại.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_42_21', 'en-b2-42', NULL, 'comprehensive_test', 'reading', NULL, 'Residents were relieved to hear that the local hospital would remain open despite proposed budget cuts.', 'Dựa vào câu trên, từ “relieved” có nghĩa phù hợp nhất là gì?', '["tính từ: nhẹ nhõm; yên tâm; thanh thản","sự bực bội; nỗi khó chịu","sự phân chia; sự phân bổ","uống ừng ực; nuốt vội vàng"]'::jsonb, 0, 'relieved: tính từ: nhẹ nhõm; yên tâm; thanh thản. Dịch cả câu: Cư dân đã rất yên tâm khi nghe tin bệnh viện địa phương vẫn tiếp tục hoạt động bất chấp các đề xuất cắt giảm ngân sách.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_42_22', 'en-b2-42', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự ghê tởm; sự kinh tởm; sự bất bình”', '["disgust","installation","dynamic","strictly"]'::jsonb, 0, 'sự ghê tởm; sự kinh tởm; sự bất bình → disgust (/dɪsˈɡʌst/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_42_23', 'en-b2-42', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự sẵn lòng; tinh thần tự nguyện”', '["willingness","operator","orbit","coincidence"]'::jsonb, 0, 'sự sẵn lòng; tinh thần tự nguyện → willingness (/ˈwɪlɪŋnəs/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_42_24', 'en-b2-42', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự thất vọng; nỗi bực bội; cảm giác chán nản”', '["astronomy","optimism","frustration","invoice"]'::jsonb, 2, 'sự thất vọng; nỗi bực bội; cảm giác chán nản → frustration (/frʌˈstreɪʃən/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-43', 'en', 'Bài 43: Cảm xúc & Tính cách (3) - CEFR B2', 'CEFR B2', 'B2 · Cảm xúc', '24 từ vựng Tiếng Anh CEFR B2 chủ đề cảm xúc & tính cách kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4043, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_envy', 'en-b2-43', 'envy', '/ˈenvi/', 'B2', 'sự ganh tị; lòng ghen tị; ghen tị; thèm muốn; người hoặc vật khiến người khác ao ước', 'n.', 'envious (adj.), enviously (adv.), enviable (adj.), enviably (adv.)', 'Đồng nghĩa: jealousy', 'Động từ đi thẳng với tân ngữ: envy someone, không cần thêm of.', 'I envy your ability to sleep on noisy trains.', NULL, 'Tôi thực sự ghen tị với khả năng ngủ ngon trên những chuyến tàu ồn ào của bạn.', '{"wordId":"envy","ukIpa":"/ˈenvi/","usIpa":"/ˈenvi/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"a feeling of wanting something that someone else has","vi":"sự ganh tị; lòng ghen tị"},{"pos":"v.","en":"to wish you had another person''s possessions, qualities, or advantages","vi":"ghen tị; thèm muốn"},{"pos":"n.","en":"a person or thing that others wish to equal or possess","vi":"người hoặc vật khiến người khác ao ước"}],"examples":[{"en":"I envy your ability to sleep on noisy trains.","vi":"Tôi thực sự ghen tị với khả năng ngủ ngon trên những chuyến tàu ồn ào của bạn.","audioKind":"ex"},{"en":"Social media can encourage envy by exposing users to carefully selected images of other people''s achievements and lifestyles.","vi":"Mạng xã hội có thể thúc đẩy lòng ganh tị bằng cách phơi bày cho người dùng thấy những hình ảnh được chọn lọc kỹ càng về thành tựu và lối sống của người khác.","audioKind":"ex2"}],"collocations":[{"en":"envy someone something","vi":"ghen tị với ai về điều gì"},{"en":"with envy","vi":"với vẻ ghen tị"},{"en":"the envy of","vi":"niềm ao ước của (ai đó)"},{"en":"green with envy","vi":"ghen tức đỏ cả mắt"}],"wordFamily":["envious (adj.)","enviously (adv.)","enviable (adj.)","enviably (adv.)"],"synonyms":["jealousy"],"antonyms":[],"tipVi":"Động từ đi thẳng với tân ngữ: envy someone, không cần thêm of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_possessive', 'en-b2-43', 'possessive', '/pəˈzesɪv/', 'B2', 'có tính chiếm hữu; ích kỷ trong quan hệ; thuộc sở hữu; biểu thị sự sở hữu', 'adj.', 'possess (v.), possession (n.), possessiveness (n.)', NULL, 'Khi nói về sự chiếm hữu đồ vật, thường đi với giới từ about; trong ngữ pháp dùng để chỉ quan hệ sở hữu.', 'My little brother is possessive about his toy trains.', NULL, 'Em trai tôi có tính chiếm hữu rất cao đối với những món đồ chơi xe lửa của nó.', '{"wordId":"possessive","ukIpa":"/pəˈzesɪv/","usIpa":"/pəˈzesɪv/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"Wanting exclusive control over someone or something.","vi":"có tính chiếm hữu; ích kỷ trong quan hệ"},{"pos":"adj.","en":"Showing who owns something or how things are related.","vi":"thuộc sở hữu; biểu thị sự sở hữu"}],"examples":[{"en":"My little brother is possessive about his toy trains.","vi":"Em trai tôi có tính chiếm hữu rất cao đối với những món đồ chơi xe lửa của nó.","audioKind":"ex"},{"en":"Possessive behaviour in friendships can limit personal freedom and make it difficult to maintain healthy relationships.","vi":"Hành vi có tính chiếm hữu trong tình bạn có thể hạn chế sự tự do cá nhân và khiến việc duy trì các mối quan hệ lành mạnh trở nên khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"possessive about","vi":"có tính chiếm hữu đối với"},{"en":"possessive behaviour","vi":"hành vi chiếm hữu"},{"en":"possessive pronoun","vi":"đại từ sở hữu"},{"en":"possessive form","vi":"hình thức sở hữu"}],"wordFamily":["possess (v.)","possession (n.)","possessiveness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi nói về sự chiếm hữu đồ vật, thường đi với giới từ about; trong ngữ pháp dùng để chỉ quan hệ sở hữu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_memorable', 'en-b2-43', 'memorable', '/ˈmemərəbl/', 'B2', 'đáng nhớ; khó quên', 'adj.', 'memorably (adv.), memory (n.), memorise (v.)', 'Đồng nghĩa: unforgettable · Trái nghĩa: forgettable', 'Tính từ "memorable" dùng để chỉ sự vật, sự việc đáng nhớ, không dùng để chỉ trí nhớ tốt của một người.', 'That snowy train journey was a truly memorable experience.', NULL, 'Chuyến đi tàu trong khung cảnh tuyết rơi hôm đó thực sự là một trải nghiệm khó quên.', '{"wordId":"memorable","ukIpa":"/ˈmemərəbl/","usIpa":"/ˈmemərəbl/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"Special or unusual enough to be remembered for a long time.","vi":"đáng nhớ; khó quên"}],"examples":[{"en":"That snowy train journey was a truly memorable experience.","vi":"Chuyến đi tàu trong khung cảnh tuyết rơi hôm đó thực sự là một trải nghiệm khó quên.","audioKind":"ex"},{"en":"Practical experiments often make science lessons more memorable by connecting abstract ideas with direct experience.","vi":"Các thí nghiệm thực tế thường làm cho giờ học khoa học trở nên đáng nhớ hơn bằng cách kết nối các khái niệm trừu tượng với trải nghiệm trực quan.","audioKind":"ex2"}],"collocations":[{"en":"memorable experience","vi":"trải nghiệm khó quên"},{"en":"memorable occasion","vi":"dịp đáng nhớ"},{"en":"memorable performance","vi":"màn trình diễn đáng nhớ"}],"wordFamily":["memorably (adv.)","memory (n.)","memorise (v.)"],"synonyms":["unforgettable"],"antonyms":["forgettable"],"tipVi":"Tính từ \"memorable\" dùng để chỉ sự vật, sự việc đáng nhớ, không dùng để chỉ trí nhớ tốt của một người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_alarming', 'en-b2-43', 'alarming', '/əˈlɑːrmɪŋ/', 'B2', 'đáng báo động; đáng lo ngại', 'adj.', 'alarm (n.), alarm (v.), alarmed (adj.), alarmingly (adv.)', 'Đồng nghĩa: worrying, disturbing · Trái nghĩa: reassuring', 'Tính từ "alarming" mô tả sự việc gây lo lắng; còn "alarmed" mô tả cảm giác sợ hãi của con người.', 'The engine made an alarming noise as we climbed.', NULL, 'Động cơ phát ra tiếng động đáng sợ khi chúng tôi leo dốc.', '{"wordId":"alarming","ukIpa":"/əˈlɑːmɪŋ/","usIpa":"/əˈlɑːrmɪŋ/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"Causing worry or fear that something bad may happen.","vi":"đáng báo động; đáng lo ngại"}],"examples":[{"en":"The engine made an alarming noise as we climbed.","vi":"Động cơ phát ra tiếng động đáng sợ khi chúng tôi leo dốc.","audioKind":"ex"},{"en":"The alarming decline in insect populations could threaten food production and disrupt entire ecosystems.","vi":"Sự sụt giảm số lượng côn trùng đáng báo động có thể đe dọa sản xuất lương thực và làm xáo trộn toàn bộ hệ sinh thái.","audioKind":"ex2"}],"collocations":[{"en":"an alarming rate","vi":"tốc độ đáng báo động"},{"en":"an alarming increase","vi":"sự gia tăng đáng lo ngại"},{"en":"an alarming trend","vi":"xu hướng đáng báo động"}],"wordFamily":["alarm (n.)","alarm (v.)","alarmed (adj.)","alarmingly (adv.)"],"synonyms":["worrying","disturbing"],"antonyms":["reassuring"],"tipVi":"Tính từ \"alarming\" mô tả sự việc gây lo lắng; còn \"alarmed\" mô tả cảm giác sợ hãi của con người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spiritual', 'en-b2-43', 'spiritual', '/ˈspɪrɪtʃuəl/', 'B2', 'thuộc về tinh thần; thuộc về tâm hồn; thuộc về tôn giáo; thuộc về tâm linh', 'adj.', 'spirit (n.), spiritually (adv.), spirituality (n.)', 'Trái nghĩa: material', 'Có thể chỉ tầng lớp tâm hồn, không nhất thiết liên quan đến tôn giáo.', 'Walking quietly in the forest gives me spiritual comfort.', NULL, 'Đi dạo yên tĩnh trong rừng mang lại cho tôi sự an ủi về mặt tinh thần.', '{"wordId":"spiritual","ukIpa":"/ˈspɪrɪtʃuəl/","usIpa":"/ˈspɪrɪtʃuəl/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"Connected with inner feelings and meaning rather than material things.","vi":"thuộc về tinh thần; thuộc về tâm hồn"},{"pos":"adj.","en":"Related to religious beliefs or experiences.","vi":"thuộc về tôn giáo; thuộc về tâm linh"}],"examples":[{"en":"Walking quietly in the forest gives me spiritual comfort.","vi":"Đi dạo yên tĩnh trong rừng mang lại cho tôi sự an ủi về mặt tinh thần.","audioKind":"ex"},{"en":"Public spaces can support spiritual well-being by offering residents peaceful places for reflection and connection with nature.","vi":"Không gian công cộng có thể thúc đẩy sức khỏe tinh thần bằng cách cung cấp cho cư dân những nơi yên bình để suy ngẫm và kết nối với thiên nhiên.","audioKind":"ex2"}],"collocations":[{"en":"spiritual well-being","vi":"sức khỏe tinh thần"},{"en":"spiritual beliefs","vi":"niềm tin tôn giáo"},{"en":"spiritual growth","vi":"sự phát triển tâm hồn"}],"wordFamily":["spirit (n.)","spiritually (adv.)","spirituality (n.)"],"synonyms":[],"antonyms":["material"],"tipVi":"Có thể chỉ tầng lớp tâm hồn, không nhất thiết liên quan đến tôn giáo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tense', 'en-b2-43', 'tense', '/tens/', 'B2', 'căng thẳng; căng; thì; làm căng cơ; trở nên căng cứng', 'adj.', 'tension (n.), tensely (adv.), tenseness (n.)', 'Trái nghĩa: relaxed', 'Dùng làm danh từ để chỉ "thì" trong ngữ pháp; dùng làm tính từ để chỉ sự căng thẳng hoặc căng cứng.', 'She looked tense while waiting outside the interview room.', NULL, 'Cô ấy trông có vẻ căng thẳng khi đứng chờ ngoài phòng phỏng vấn.', '{"wordId":"tense","ukIpa":"/tens/","usIpa":"/tens/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"Nervous and unable to relax, or stretched tightly.","vi":"căng thẳng; căng"},{"pos":"n.","en":"A verb form that indicates time.","vi":"thì"},{"pos":"v.","en":"To tighten muscles or become physically stiff.","vi":"làm căng cơ; trở nên căng cứng"}],"examples":[{"en":"She looked tense while waiting outside the interview room.","vi":"Cô ấy trông có vẻ căng thẳng khi đứng chờ ngoài phòng phỏng vấn.","audioKind":"ex"},{"en":"A tense working environment can reduce productivity and discourage employees from sharing creative ideas.","vi":"Môi trường làm việc căng thẳng có thể làm giảm năng suất và khiến nhân viên ngần ngại chia sẻ những ý tưởng sáng tạo.","audioKind":"ex2"}],"collocations":[{"en":"feel tense","vi":"cảm thấy căng thẳng"},{"en":"a tense atmosphere","vi":"không khí căng thẳng"},{"en":"past tense","vi":"thì quá khứ"},{"en":"tense your muscles","vi":"gồng căng cơ bắp"}],"wordFamily":["tension (n.)","tensely (adv.)","tenseness (n.)"],"synonyms":[],"antonyms":["relaxed"],"tipVi":"Dùng làm danh từ để chỉ \"thì\" trong ngữ pháp; dùng làm tính từ để chỉ sự căng thẳng hoặc căng cứng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_distress', 'en-b2-43', 'distress', '/dɪˈstres/', 'B2', 'nỗi thống khổ; sự đau buồn; sự lo lắng; tình trạng nguy cấp; hoàn cảnh khó khăn; làm đau khổ; gây phiền muộn', 'n.', 'distressed (adj.), distressing (adj.)', 'Đồng nghĩa: anguish, suffering · Trái nghĩa: comfort', 'distress mạnh hơn mức sadness thông thường, và cũng có thể chỉ tình trạng lâm nguy.', 'Her neighbour noticed her distress and offered to help.', NULL, 'Người hàng xóm nhận thấy cô ấy đang đau buồn và ngỏ ý muốn giúp đỡ.', '{"wordId":"distress","ukIpa":"/dɪˈstres/","usIpa":"/dɪˈstres/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"great emotional pain, worry, or unhappiness","vi":"nỗi thống khổ; sự đau buồn; sự lo lắng"},{"pos":"n.","en":"a situation involving danger or serious difficulty","vi":"tình trạng nguy cấp; hoàn cảnh khó khăn"},{"pos":"v.","en":"to cause someone great worry or unhappiness","vi":"làm đau khổ; gây phiền muộn"}],"examples":[{"en":"Her neighbour noticed her distress and offered to help.","vi":"Người hàng xóm nhận thấy cô ấy đang đau buồn và ngỏ ý muốn giúp đỡ.","audioKind":"ex"},{"en":"Sudden unemployment can cause considerable distress, particularly for households with limited savings and high housing costs.","vi":"Việc đột ngột mất việc có thể gây ra sự lo lắng lớn, đặc biệt đối với các hộ gia đình có tiền tiết kiệm hạn hẹp và chi phí nhà ở cao.","audioKind":"ex2"}],"collocations":[{"en":"emotional distress","vi":"tổn thương tinh thần"},{"en":"in distress","vi":"lâm vào cảnh khốn cùng"},{"en":"cause distress","vi":"gây đau khổ"},{"en":"a distress signal","vi":"tín hiệu cầu cứu"}],"wordFamily":["distressed (adj.)","distressing (adj.)"],"synonyms":["anguish","suffering"],"antonyms":["comfort"],"tipVi":"distress mạnh hơn mức sadness thông thường, và cũng có thể chỉ tình trạng lâm nguy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_anger', 'en-b2-43', 'anger', '/ˈæŋɡər/', 'B2', 'sự tức giận; cơn giận; làm ai nổi giận; chọc giận', 'n.', 'angry (adj.), angrily (adv.)', 'Đồng nghĩa: rage, fury · Trái nghĩa: calm', 'anger đóng vai trò danh từ thường không đếm được; tính từ tương ứng là angry.', 'He took a deep breath to control his anger.', NULL, 'Anh ấy hít một hơi thật sâu để kìm nén cơn giận.', '{"wordId":"anger","ukIpa":"/ˈæŋɡə/","usIpa":"/ˈæŋɡər/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"a strong feeling of displeasure about something wrong or unfair","vi":"sự tức giận; cơn giận"},{"pos":"v.","en":"to make someone feel angry","vi":"làm ai nổi giận; chọc giận"}],"examples":[{"en":"He took a deep breath to control his anger.","vi":"Anh ấy hít một hơi thật sâu để kìm nén cơn giận.","audioKind":"ex"},{"en":"Public anger over rising transport costs can encourage local authorities to reconsider their pricing policies.","vi":"Sự phẫn nộ của công chúng trước việc chi phí đi lại leo thang có thể thúc đẩy chính quyền địa phương xem xét lại chính sách giá của họ.","audioKind":"ex2"}],"collocations":[{"en":"control your anger","vi":"kiểm soát sự tức giận"},{"en":"express anger","vi":"bày tỏ sự tức giận"},{"en":"public anger","vi":"sự phẫn nộ của công chúng"},{"en":"anger management","vi":"quản lý cảm xúc tức giận"}],"wordFamily":["angry (adj.)","angrily (adv.)"],"synonyms":["rage","fury"],"antonyms":["calm"],"tipVi":"anger đóng vai trò danh từ thường không đếm được; tính từ tương ứng là angry.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_relief', 'en-b2-43', 'relief', '/rɪˈliːf/', 'B2', 'sự nhẹ nhõm; sự thở phào; sự giảm đau; sự đỡ khó chịu; sự cứu trợ; hàng cứu trợ', 'n.', 'relieve (v.), relieved (adj.)', NULL, 'relief là danh từ, relieve là động từ tương ứng; cụm giảm đau dùng pain relief.', 'I sighed with relief when my missing cat returned.', NULL, 'Tôi thở phào nhẹ nhõm khi con mèo bị lạc của tôi quay trở về.', '{"wordId":"relief","ukIpa":"/rɪˈliːf/","usIpa":"/rɪˈliːf/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"Comfort felt when worry or fear ends","vi":"sự nhẹ nhõm; sự thở phào"},{"pos":"n.","en":"A reduction in pain or discomfort","vi":"sự giảm đau; sự đỡ khó chịu"},{"pos":"n.","en":"Help given to people suffering from disaster or poverty","vi":"sự cứu trợ; hàng cứu trợ"}],"examples":[{"en":"I sighed with relief when my missing cat returned.","vi":"Tôi thở phào nhẹ nhõm khi con mèo bị lạc của tôi quay trở về.","audioKind":"ex"},{"en":"Rapid delivery of emergency relief can prevent further suffering in communities affected by severe flooding.","vi":"Việc phân phối nhanh chóng hàng cứu trợ khẩn cấp có thể ngăn chặn những tổn thất tiếp theo tại các cộng đồng bị ảnh hưởng bởi lũ lụt nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"a sigh of relief","vi":"tiếng thở phào nhẹ nhõm"},{"en":"pain relief","vi":"giảm đau"},{"en":"disaster relief","vi":"cứu trợ thiên tai"},{"en":"to someone''s relief","vi":"làm ai đó nhẹ nhõm"}],"wordFamily":["relieve (v.)","relieved (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"relief là danh từ, relieve là động từ tương ứng; cụm giảm đau dùng pain relief.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reluctant', 'en-b2-43', 'reluctant', '/rɪˈlʌktənt/', 'B2', 'miễn cưỡng; bất đắc dĩ; ngần ngại', 'adj.', 'reluctance (n.), reluctantly (adv.)', 'Đồng nghĩa: unwilling, hesitant · Trái nghĩa: willing, eager', 'Thường dùng cấu trúc "be reluctant to do" để diễn tả việc không sẵn lòng hoặc miễn cưỡng làm gì.', 'He was reluctant to leave his warm bed.', NULL, 'Anh ấy miễn cưỡng rời khỏi chiếc giường ấm áp của mình.', '{"wordId":"reluctant","ukIpa":"/rɪˈlʌktənt/","usIpa":"/rɪˈlʌktənt/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"Unwilling or hesitant to do something.","vi":"miễn cưỡng; bất đắc dĩ; ngần ngại"}],"examples":[{"en":"He was reluctant to leave his warm bed.","vi":"Anh ấy miễn cưỡng rời khỏi chiếc giường ấm áp của mình.","audioKind":"ex"},{"en":"Many commuters remain reluctant to use public transport when services are infrequent or unreliable.","vi":"Nhiều người đi làm vẫn ngại sử dụng phương tiện giao thông công cộng khi các chuyến xe thưa thớt hoặc thiếu tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"reluctant to admit","vi":"ngại thừa nhận"},{"en":"reluctant to change","vi":"ngại thay đổi"},{"en":"reluctant agreement","vi":"sự đồng ý miễn cưỡng"}],"wordFamily":["reluctance (n.)","reluctantly (adv.)"],"synonyms":["unwilling","hesitant"],"antonyms":["willing","eager"],"tipVi":"Thường dùng cấu trúc \"be reluctant to do\" để diễn tả việc không sẵn lòng hoặc miễn cưỡng làm gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_moan', 'en-b2-43', 'moan', '/moʊn/', 'B2', 'rên rỉ; than rên; phàn nàn; kêu ca; cằn nhằn; tiếng rên rỉ; lời phàn nàn', 'v.', NULL, 'Đồng nghĩa: groan, complain', 'Khi diễn tả sự phàn nàn, từ này mang tính khẩu ngữ nhiều hơn, thường dùng moan about.', 'He moaned softly as the nurse examined his ankle.', NULL, 'Anh ấy khẽ rên lên khi y tá kiểm tra mắt cá chân của mình.', '{"wordId":"moan","ukIpa":"/məʊn/","usIpa":"/moʊn/","cefr":"B2","topic":"emotion","senses":[{"pos":"v.","en":"To make a low sound expressing pain or unhappiness.","vi":"rên rỉ; than rên"},{"pos":"v.","en":"To complain, especially in an annoying or repeated way.","vi":"phàn nàn; kêu ca; cằn nhằn"},{"pos":"n.","en":"A low sound of pain, or an expression of complaint.","vi":"tiếng rên rỉ; lời phàn nàn"}],"examples":[{"en":"He moaned softly as the nurse examined his ankle.","vi":"Anh ấy khẽ rên lên khi y tá kiểm tra mắt cá chân của mình.","audioKind":"ex"},{"en":"Rather than moan about unreliable buses, residents could ask local authorities to improve public transport.","vi":"Thay vì phàn nàn về những chuyến xe buýt không đúng giờ, cư dân có thể yêu cầu chính quyền địa phương cải thiện giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"moan in pain","vi":"rên rỉ vì đau đớn"},{"en":"moan about something","vi":"phàn nàn về điều gì đó"},{"en":"let out a moan","vi":"thốt lên một tiếng rên"}],"wordFamily":[],"synonyms":["groan","complain"],"antonyms":[],"tipVi":"Khi diễn tả sự phàn nàn, từ này mang tính khẩu ngữ nhiều hơn, thường dùng moan about.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unfortunate', 'en-b2-43', 'unfortunate', '/ʌnˈfɔːrtʃənət/', 'B2', 'bất hạnh; gặp vận đen; rủi ro; đáng tiếc; không may; bất cập', 'adj.', 'unfortunately (adv.), fortunate (adj.), fortunately (adv.), fortune (n.)', 'Đồng nghĩa: unlucky, regrettable · Trái nghĩa: fortunate, lucky', 'Cấu trúc "It is unfortunate that..." dùng để diễn đạt ý "thật đáng tiếc là...".', 'An unfortunate accident left my bicycle wheel badly bent.', NULL, 'Một tai nạn rủi ro đã khiến bánh xe đạp của tôi bị cong nặng.', '{"wordId":"unfortunate","ukIpa":"/ʌnˈfɔːtʃənət/","usIpa":"/ʌnˈfɔːrtʃənət/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"Experiencing bad luck or caused by bad luck.","vi":"bất hạnh; gặp vận đen; rủi ro"},{"pos":"adj.","en":"Regrettable or likely to cause problems or embarrassment.","vi":"đáng tiếc; không may; bất cập"}],"examples":[{"en":"An unfortunate accident left my bicycle wheel badly bent.","vi":"Một tai nạn rủi ro đã khiến bánh xe đạp của tôi bị cong nặng.","audioKind":"ex"},{"en":"It is unfortunate that many rural communities still lack reliable access to essential healthcare services.","vi":"Thật đáng tiếc khi nhiều cộng đồng nông thôn vẫn chưa thể tiếp cận ổn định các dịch vụ y tế thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"an unfortunate accident","vi":"một tai nạn đáng tiếc"},{"en":"unfortunate circumstances","vi":"hoàn cảnh ngặt nghèo"},{"en":"an unfortunate choice of words","vi":"lựa chọn từ ngữ kém tinh tế"}],"wordFamily":["unfortunately (adv.)","fortunate (adj.)","fortunately (adv.)","fortune (n.)"],"synonyms":["unlucky","regrettable"],"antonyms":["fortunate","lucky"],"tipVi":"Cấu trúc \"It is unfortunate that...\" dùng để diễn đạt ý \"thật đáng tiếc là...\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_annoyance', 'en-b2-43', 'annoyance', '/əˈnɔɪəns/', 'B2', 'sự bực mình; sự khó chịu; điều gây phiền toái; người gây khó chịu', 'n.', 'annoy (v.), annoyed (adj.), annoying (adj.)', 'Đồng nghĩa: irritation, exasperation · Trái nghĩa: pleasure', 'Không đếm được khi chỉ cảm xúc; đếm được khi chỉ sự việc gây phiền toái cụ thể.', 'She sighed in annoyance when the doorbell rang again.', NULL, 'Cô ấy thở dài bực bội khi chuông cửa lại reo lên.', '{"wordId":"annoyance","ukIpa":"/əˈnɔɪəns/","usIpa":"/əˈnɔɪəns/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"The feeling of being slightly angry or irritated.","vi":"sự bực mình; sự khó chịu"},{"pos":"n.","en":"Something or someone that makes you feel irritated.","vi":"điều gây phiền toái; người gây khó chịu"}],"examples":[{"en":"She sighed in annoyance when the doorbell rang again.","vi":"Cô ấy thở dài bực bội khi chuông cửa lại reo lên.","audioKind":"ex"},{"en":"Although traffic noise may seem a minor annoyance, prolonged exposure can negatively affect residents'' wellbeing.","vi":"Mặc dù tiếng ồn giao thông có vẻ chỉ là một phiền toái nhỏ, việc tiếp xúc kéo dài có thể ảnh hưởng tiêu cực đến sức khỏe của cư dân.","audioKind":"ex2"}],"collocations":[{"en":"to my annoyance","vi":"làm tôi bực mình là"},{"en":"a minor annoyance","vi":"một phiền toái nhỏ"},{"en":"a source of annoyance","vi":"nguồn cơn gây khó chịu"}],"wordFamily":["annoy (v.)","annoyed (adj.)","annoying (adj.)"],"synonyms":["irritation","exasperation"],"antonyms":["pleasure"],"tipVi":"Không đếm được khi chỉ cảm xúc; đếm được khi chỉ sự việc gây phiền toái cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_glare', 'en-b2-43', 'glare', '/ɡler/', 'B2', 'nhìn trừng trừng; lườm; ánh sáng chói; ánh sáng gắt; cái nhìn giận dữ; ánh mắt sắc lẹm', 'v.', 'glaring (adj.), glaringly (adv.)', NULL, 'glare at là lườm giận dữ; stare at chỉ là nhìn chằm chằm.', 'She glared at me when I interrupted her story.', NULL, 'Cô ấy lườm tôi khi tôi cắt ngang câu chuyện của cô ấy.', '{"wordId":"glare","ukIpa":"/ɡleə/","usIpa":"/ɡler/","cefr":"B2","topic":"emotion","senses":[{"pos":"v.","en":"Look at someone angrily for a sustained moment.","vi":"nhìn trừng trừng; lườm"},{"pos":"n.","en":"A strong, bright light that makes seeing difficult.","vi":"ánh sáng chói; ánh sáng gắt"},{"pos":"n.","en":"An angry, fixed look directed at someone.","vi":"cái nhìn giận dữ; ánh mắt sắc lẹm"}],"examples":[{"en":"She glared at me when I interrupted her story.","vi":"Cô ấy lườm tôi khi tôi cắt ngang câu chuyện của cô ấy.","audioKind":"ex"},{"en":"Careful placement of street lighting can reduce glare and improve visibility for both drivers and pedestrians.","vi":"Việc bố trí đèn đường cẩn thận có thể làm giảm độ chói và cải thiện tầm nhìn cho cả người lái xe lẫn người đi bộ.","audioKind":"ex2"}],"collocations":[{"en":"glare at someone","vi":"lườm ai đó"},{"en":"give someone a glare","vi":"trừng mắt nhìn ai đó"},{"en":"reduce glare","vi":"giảm độ chói"},{"en":"the glare of the sun","vi":"ánh nắng chói chang"}],"wordFamily":["glaring (adj.)","glaringly (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"glare at là lườm giận dữ; stare at chỉ là nhìn chằm chằm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_loneliness', 'en-b2-43', 'loneliness', '/ˈloʊnlinəs/', 'B2', 'nỗi cô đơn; sự cô độc', 'n.', 'lonely (adj.), lone (adj.)', 'Đồng nghĩa: isolation · Trái nghĩa: companionship', 'loneliness nhấn mạnh cảm giác buồn bã; trong khi solitude có thể chỉ việc tận hưởng sự một mình.', 'Calling an old friend helped ease my loneliness.', NULL, 'Gọi điện cho một người bạn cũ đã giúp tôi nguôi ngoai nỗi cô đơn.', '{"wordId":"loneliness","ukIpa":"/ˈləʊnlinəs/","usIpa":"/ˈloʊnlinəs/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"Sadness caused by feeling alone or lacking close relationships","vi":"nỗi cô đơn; sự cô độc"}],"examples":[{"en":"Calling an old friend helped ease my loneliness.","vi":"Gọi điện cho một người bạn cũ đã giúp tôi nguôi ngoai nỗi cô đơn.","audioKind":"ex"},{"en":"Community activities can reduce loneliness among older adults by creating opportunities for regular and meaningful social contact.","vi":"Các hoạt động cộng đồng có thể làm giảm bớt cảm giác cô đơn ở người cao tuổi bằng cách tạo ra các cơ hội giao lưu đều đặn và có ý nghĩa.","audioKind":"ex2"}],"collocations":[{"en":"feelings of loneliness","vi":"cảm giác cô đơn"},{"en":"ease loneliness","vi":"làm dịu nỗi cô đơn"},{"en":"social isolation and loneliness","vi":"sự cô lập xã hội và nỗi cô đơn"}],"wordFamily":["lonely (adj.)","lone (adj.)"],"synonyms":["isolation"],"antonyms":["companionship"],"tipVi":"loneliness nhấn mạnh cảm giác buồn bã; trong khi solitude có thể chỉ việc tận hưởng sự một mình.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_depress', 'en-b2-43', 'depress', '/dɪˈpres/', 'B2', 'làm nản lòng; khiến buồn bã; làm giảm sút; kìm hãm; nhấn xuống; ấn xuống', 'v.', 'depressed (adj.), depressing (adj.), depression (n.)', 'Đồng nghĩa: sadden, discourage, lower · Trái nghĩa: cheer, raise', 'depressed dùng để tả cảm xúc con người bị buồn chán, depressing dùng để tả sự việc gây chán nản.', 'Days of grey skies and constant rain depress me.', NULL, 'Những ngày trời xám xịt và mưa dầm dề khiến tôi cảm thấy chán nản.', '{"wordId":"depress","ukIpa":"/dɪˈpres/","usIpa":"/dɪˈpres/","cefr":"B2","topic":"emotion","senses":[{"pos":"v.","en":"To make someone feel unhappy and without hope.","vi":"làm nản lòng; khiến buồn bã"},{"pos":"v.","en":"To reduce an amount, value, or level of activity.","vi":"làm giảm sút; kìm hãm"},{"pos":"v.","en":"To push something down.","vi":"nhấn xuống; ấn xuống"}],"examples":[{"en":"Days of grey skies and constant rain depress me.","vi":"Những ngày trời xám xịt và mưa dầm dề khiến tôi cảm thấy chán nản.","audioKind":"ex"},{"en":"High borrowing costs can depress consumer spending, making it harder for small businesses to survive.","vi":"Chi phí đi vay cao có thể làm giảm chi tiêu của người tiêu dùng, khiến các doanh nghiệp nhỏ khó sinh tồn hơn.","audioKind":"ex2"}],"collocations":[{"en":"depress demand","vi":"kìm hãm nhu cầu"},{"en":"depress prices","vi":"kéo giảm giá cả"},{"en":"depress a pedal","vi":"đạp bàn đạp"}],"wordFamily":["depressed (adj.)","depressing (adj.)","depression (n.)"],"synonyms":["sadden","discourage","lower"],"antonyms":["cheer","raise"],"tipVi":"depressed dùng để tả cảm xúc con người bị buồn chán, depressing dùng để tả sự việc gây chán nản.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_uneasy', 'en-b2-43', 'uneasy', '/ʌnˈiːzi/', 'B2', 'bất an; lo âu; bồn chồn; không ổn định; căng thẳng; bấp bênh', 'adj.', 'unease (n.), uneasily (adv.), uneasiness (n.)', 'Đồng nghĩa: anxious, unsettled · Trái nghĩa: relaxed, reassured', 'Từ uneasy có nghĩa là bất an, không phải là "không dễ dàng"; thường đi với giới từ about.', 'I felt uneasy walking through the empty station.', NULL, 'Tôi cảm thấy hơi bất an khi đi qua nhà ga vắng vẻ.', '{"wordId":"uneasy","ukIpa":"/ʌnˈiːzi/","usIpa":"/ʌnˈiːzi/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"Feeling worried or uncomfortable about a situation.","vi":"bất an; lo âu; bồn chồn"},{"pos":"adj.","en":"Not fully settled, secure, or free from tension.","vi":"không ổn định; căng thẳng; bấp bênh"}],"examples":[{"en":"I felt uneasy walking through the empty station.","vi":"Tôi cảm thấy hơi bất an khi đi qua nhà ga vắng vẻ.","audioKind":"ex"},{"en":"Many residents remain uneasy about the proposed factory because its environmental effects have not been fully assessed.","vi":"Nhiều cư dân vẫn tỏ ra lo lắng về nhà máy dự kiến xây dựng vì tác động môi trường của nó chưa được đánh giá đầy đủ.","audioKind":"ex2"}],"collocations":[{"en":"feel uneasy","vi":"cảm thấy bất an"},{"en":"uneasy about something","vi":"lo lắng về điều gì đó"},{"en":"an uneasy truce","vi":"một lệnh ngừng bắn mong manh"},{"en":"an uneasy relationship","vi":"một mối quan hệ căng thẳng"}],"wordFamily":["unease (n.)","uneasily (adv.)","uneasiness (n.)"],"synonyms":["anxious","unsettled"],"antonyms":["relaxed","reassured"],"tipVi":"Từ uneasy có nghĩa là bất an, không phải là \"không dễ dàng\"; thường đi với giới từ about.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_restless', 'en-b2-43', 'restless', '/ˈrestləs/', 'B2', 'bồn chồn; thao thức; bất an; không thỏa mãn với hiện tại', 'adj.', 'rest (n.), restlessness (n.), restlessly (adv.), restful (adj.)', 'Đồng nghĩa: fidgety, uneasy · Trái nghĩa: calm, relaxed', 'restless chỉ việc khó giữ bình tĩnh hoặc khó nghỉ ngơi; restful chỉ sự thư thái, dễ chịu.', 'The restless child kept swinging her legs under the table.', NULL, 'Đứa trẻ bồn chồn cứ đá chân liên tục dưới gầm bàn.', '{"wordId":"restless","ukIpa":"/ˈrestləs/","usIpa":"/ˈrestləs/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"Unable to relax, stay still, or sleep peacefully.","vi":"bồn chồn; thao thức"},{"pos":"adj.","en":"Eager for change because the present situation feels unsatisfying.","vi":"bất an; không thỏa mãn với hiện tại"}],"examples":[{"en":"The restless child kept swinging her legs under the table.","vi":"Đứa trẻ bồn chồn cứ đá chân liên tục dưới gầm bàn.","audioKind":"ex"},{"en":"Students may become restless during lengthy lectures if they have few opportunities to participate actively.","vi":"Học sinh có thể trở nên bồn chồn trong những giờ giảng dài nếu có ít cơ hội tham gia tích cực.","audioKind":"ex2"}],"collocations":[{"en":"restless sleep","vi":"giấc ngủ chập chờn"},{"en":"feel restless","vi":"cảm thấy bồn chồn"},{"en":"grow restless","vi":"trở nên bồn chồn lo lắng"},{"en":"a restless spirit","vi":"tâm hồn không chịu yên bình"}],"wordFamily":["rest (n.)","restlessness (n.)","restlessly (adv.)","restful (adj.)"],"synonyms":["fidgety","uneasy"],"antonyms":["calm","relaxed"],"tipVi":"restless chỉ việc khó giữ bình tĩnh hoặc khó nghỉ ngơi; restful chỉ sự thư thái, dễ chịu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hesitant', 'en-b2-43', 'hesitant', '/ˈhezɪtənt/', 'B2', 'do dự; chần chừ; ngập ngừng', 'adj.', 'hesitate (v.), hesitation (n.), hesitantly (adv.)', 'Đồng nghĩa: uncertain, unsure · Trái nghĩa: confident, decisive', 'Thường dùng hesitant to do hoặc hesitant about sth.', 'She looked hesitant before stepping onto the narrow bridge.', NULL, 'Cô ấy tỏ ra ngập ngừng trước khi bước lên cây cầu hẹp.', '{"wordId":"hesitant","ukIpa":"/ˈhezɪtənt/","usIpa":"/ˈhezɪtənt/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"slow to act or speak because you feel uncertain","vi":"do dự; chần chừ; ngập ngừng"}],"examples":[{"en":"She looked hesitant before stepping onto the narrow bridge.","vi":"Cô ấy tỏ ra ngập ngừng trước khi bước lên cây cầu hẹp.","audioKind":"ex"},{"en":"Some older consumers remain hesitant to use online banking because they worry about financial security.","vi":"Một số người tiêu dùng lớn tuổi vẫn do dự khi sử dụng dịch vụ ngân hàng trực tuyến vì họ lo lắng về vấn đề an toàn tài chính.","audioKind":"ex2"}],"collocations":[{"en":"hesitant to agree","vi":"do dự không dám đồng ý"},{"en":"hesitant about change","vi":"chần chừ trước sự thay đổi"},{"en":"a hesitant smile","vi":"nụ cười ngập ngừng"}],"wordFamily":["hesitate (v.)","hesitation (n.)","hesitantly (adv.)"],"synonyms":["uncertain","unsure"],"antonyms":["confident","decisive"],"tipVi":"Thường dùng hesitant to do hoặc hesitant about sth.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_coward', 'en-b2-43', 'coward', '/ˈkaʊərd/', 'B2', 'kẻ hèn nhát; đồ nhát gan', 'n.', 'cowardly (adj.), cowardice (n.)', NULL, 'coward là danh từ, tính từ dùng cowardly; gọi người khác mang sắc thái chê bai.', 'He called himself a coward for avoiding the conversation.', NULL, 'Anh ấy tự mắng mình là đồ hèn nhát vì đã né tránh cuộc trò chuyện đó.', '{"wordId":"coward","ukIpa":"/ˈkaʊəd/","usIpa":"/ˈkaʊərd/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"Someone who avoids danger or difficulty because of fear","vi":"kẻ hèn nhát; đồ nhát gan"}],"examples":[{"en":"He called himself a coward for avoiding the conversation.","vi":"Anh ấy tự mắng mình là đồ hèn nhát vì đã né tránh cuộc trò chuyện đó.","audioKind":"ex"},{"en":"Calling someone a coward may discourage them from discussing their fears or seeking appropriate support.","vi":"Việc gọi ai đó là kẻ hèn nhát có thể khiến họ nản lòng không muốn giãi bày nỗi sợ hay tìm kiếm sự hỗ trợ phù hợp.","audioKind":"ex2"}],"collocations":[{"en":"a complete coward","vi":"một kẻ hoàn toàn hèn nhát"},{"en":"call someone a coward","vi":"gọi ai đó là kẻ hèn nhát"}],"wordFamily":["cowardly (adj.)","cowardice (n.)"],"synonyms":[],"antonyms":[],"tipVi":"coward là danh từ, tính từ dùng cowardly; gọi người khác mang sắc thái chê bai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bore', 'en-b2-43', 'bore', '/bɔːr/', 'B2', 'làm chán ngấy; làm phiền toái; khoan lỗ; đục thủng; kẻ tẻ nhạt; điều nhàm chán', 'v.', 'bored (adj.), boring (adj.), boredom (n.)', NULL, 'Người cảm thấy chán dùng bored; sự vật gây nhàm chán dùng boring.', 'Long meetings bore me, especially when nobody has anything new.', NULL, 'Những cuộc họp kéo dài khiến tôi phát chán, đặc biệt khi chẳng ai có điều gì mới mẻ để nói.', '{"wordId":"bore","ukIpa":"/bɔː/","usIpa":"/bɔːr/","cefr":"B2","topic":"emotion","senses":[{"pos":"v.","en":"To make someone feel uninterested or tired of something.","vi":"làm chán ngấy; làm phiền toái"},{"pos":"v.","en":"To make a hole using a tool or machine.","vi":"khoan lỗ; đục thủng"},{"pos":"n.","en":"A person or activity that is dull and uninteresting.","vi":"kẻ tẻ nhạt; điều nhàm chán"}],"examples":[{"en":"Long meetings bore me, especially when nobody has anything new.","vi":"Những cuộc họp kéo dài khiến tôi phát chán, đặc biệt khi chẳng ai có điều gì mới mẻ để nói.","audioKind":"ex"},{"en":"Lessons that rely entirely on memorisation may bore students and discourage them from exploring ideas independently.","vi":"Các bài học hoàn toàn dựa vào việc học thuộc lòng có thể làm học sinh thấy chán nản và nản lòng trong việc tự mình khám phá các ý tưởng.","audioKind":"ex2"}],"collocations":[{"en":"bore someone to tears","vi":"làm ai đó phát chán tột cùng"},{"en":"bore a hole","vi":"khoan một cái lỗ"},{"en":"a terrible bore","vi":"một thứ vô cùng tẻ nhạt"}],"wordFamily":["bored (adj.)","boring (adj.)","boredom (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Người cảm thấy chán dùng bored; sự vật gây nhàm chán dùng boring.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_weep', 'en-b2-43', 'weep', '/wiːp/', 'B2', 'khóc; rơi lệ', 'v.', 'weeping (n.)', 'Đồng nghĩa: cry, shed tears', 'Dạng quá khứ và quá khứ phân từ đều là wept; mang tính văn phong trang trọng hơn so với cry.', 'He began to weep when his lost dog returned.', NULL, 'Anh ấy bắt đầu khóc khi con chó bị lạc của mình quay trở lại.', '{"wordId":"weep","ukIpa":"/wiːp/","usIpa":"/wiːp/","cefr":"B2","topic":"emotion","senses":[{"pos":"v.","en":"To cry, usually because of strong emotion","vi":"khóc; rơi lệ"}],"examples":[{"en":"He began to weep when his lost dog returned.","vi":"Anh ấy bắt đầu khóc khi con chó bị lạc của mình quay trở lại.","audioKind":"ex"},{"en":"Emotional scenes in films can make audiences weep while encouraging greater empathy for people facing difficult circumstances.","vi":"Những cảnh cảm động trong phim có thể khiến khán giả rơi nước mắt, đồng thời khuyến khích sự đồng cảm lớn hơn đối với những người đang gặp hoàn cảnh khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"weep with joy","vi":"khóc vì vui sướng"},{"en":"weep for someone","vi":"khóc vì ai đó"},{"en":"weep bitterly","vi":"khóc nức nở"}],"wordFamily":["weeping (n.)"],"synonyms":["cry","shed tears"],"antonyms":[],"tipVi":"Dạng quá khứ và quá khứ phân từ đều là wept; mang tính văn phong trang trọng hơn so với cry.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rejection', 'en-b2-43', 'rejection', '/rɪˈdʒekʃən/', 'B2', 'sự từ chối; sự bác bỏ; sự đào thải; phản ứng đào thải', 'n.', 'reject (v.), rejected (adj.)', 'Đồng nghĩa: refusal · Trái nghĩa: acceptance', 'rejection of theo sau là người, đề xuất hoặc sự vật bị từ chối.', 'After another rejection, she revised her job application.', NULL, 'Sau một lần bị từ chối nữa, cô ấy đã sửa lại hồ sơ xin việc của mình.', '{"wordId":"rejection","ukIpa":"/rɪˈdʒekʃən/","usIpa":"/rɪˈdʒekʃən/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"The act of refusing to accept someone or something.","vi":"sự từ chối; sự bác bỏ"},{"pos":"n.","en":"The body''s immune response against transplanted tissue or an organ.","vi":"sự đào thải; phản ứng đào thải"}],"examples":[{"en":"After another rejection, she revised her job application.","vi":"Sau một lần bị từ chối nữa, cô ấy đã sửa lại hồ sơ xin việc của mình.","audioKind":"ex"},{"en":"Repeated rejection in the labour market can damage young people''s confidence and discourage further job applications.","vi":"Việc liên tục bị từ chối trên thị trường lao động có thể làm tổn hại đến sự tự tin của giới trẻ và khiến họ nản lòng không muốn nộp đơn xin việc tiếp.","audioKind":"ex2"}],"collocations":[{"en":"fear of rejection","vi":"nỗi sợ bị từ chối"},{"en":"rejection of a proposal","vi":"sự bác bỏ một đề xuất"},{"en":"face rejection","vi":"đối mặt với sự từ chối"},{"en":"organ rejection","vi":"sự đào thải cơ quan nội tạng"}],"wordFamily":["reject (v.)","rejected (adj.)"],"synonyms":["refusal"],"antonyms":["acceptance"],"tipVi":"rejection of theo sau là người, đề xuất hoặc sự vật bị từ chối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_truly', 'en-b2-43', 'truly', '/ˈtruːli/', 'B2', 'thực sự; đích thực; chân thành; một cách thành khẩn', 'adv.', 'true (adj.), truth (n.), truthful (adj.), truthfully (adv.)', 'Đồng nghĩa: genuinely, really', 'Khi chuyển true thành truly thì bỏ e ở cuối, không viết là truely.', 'This is the first place I''ve felt truly comfortable.', NULL, 'Đây là nơi đầu tiên tôi cảm thấy thực sự thoải mái.', '{"wordId":"truly","ukIpa":"/ˈtruːli/","usIpa":"/ˈtruːli/","cefr":"B2","topic":"emotion","senses":[{"pos":"adv.","en":"Really or genuinely, rather than only apparently","vi":"thực sự; đích thực"},{"pos":"adv.","en":"With sincere feelings or intentions","vi":"chân thành; một cách thành khẩn"}],"examples":[{"en":"This is the first place I''ve felt truly comfortable.","vi":"Đây là nơi đầu tiên tôi cảm thấy thực sự thoải mái.","audioKind":"ex"},{"en":"A truly inclusive education system must address the needs of students from different social backgrounds.","vi":"Một hệ thống giáo dục thực sự hòa nhập phải giải quyết được nhu cầu của học sinh từ các hoàn cảnh xã hội khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"truly believe","vi":"thực sự tin tưởng"},{"en":"truly remarkable","vi":"thực sự đáng chú ý"},{"en":"truly sorry","vi":"thành thật xin lỗi"}],"wordFamily":["true (adj.)","truth (n.)","truthful (adj.)","truthfully (adv.)"],"synonyms":["genuinely","really"],"antonyms":[],"tipVi":"Khi chuyển true thành truly thì bỏ e ở cuối, không viết là truely.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_43_1', 'en-b2-43', 'Cách dùng “possessive” (adj.) — có tính chiếm hữu; ích kỷ trong quan hệ', 'possessive about  ·  possessive behaviour  ·  possessive pronoun', 'Khi nói về sự chiếm hữu đồ vật, thường đi với giới từ about; trong ngữ pháp dùng để chỉ quan hệ sở hữu.', 'Họ từ (Word Family): possess (v.), possession (n.), possessiveness (n.)', '[{"hanzi":"My little brother is possessive about his toy trains.","pinyin":"","meaning":"Em trai tôi có tính chiếm hữu rất cao đối với những món đồ chơi xe lửa của nó."},{"hanzi":"Possessive behaviour in friendships can limit personal freedom and make it difficult to maintain healthy relationships.","pinyin":"","meaning":"Hành vi có tính chiếm hữu trong tình bạn có thể hạn chế sự tự do cá nhân và khiến việc duy trì các mối quan hệ lành mạnh trở nên khó khăn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_43_2', 'en-b2-43', 'Cách dùng “memorable” (adj.) — đáng nhớ; khó quên', 'memorable experience  ·  memorable occasion  ·  memorable performance', 'Tính từ "memorable" dùng để chỉ sự vật, sự việc đáng nhớ, không dùng để chỉ trí nhớ tốt của một người.', 'Họ từ (Word Family): memorably (adv.), memory (n.), memorise (v.) | Đồng nghĩa: unforgettable · Trái nghĩa: forgettable', '[{"hanzi":"That snowy train journey was a truly memorable experience.","pinyin":"","meaning":"Chuyến đi tàu trong khung cảnh tuyết rơi hôm đó thực sự là một trải nghiệm khó quên."},{"hanzi":"Practical experiments often make science lessons more memorable by connecting abstract ideas with direct experience.","pinyin":"","meaning":"Các thí nghiệm thực tế thường làm cho giờ học khoa học trở nên đáng nhớ hơn bằng cách kết nối các khái niệm trừu tượng với trải nghiệm trực quan."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_43_3', 'en-b2-43', 'Cách dùng “tense” (adj.) — căng thẳng; căng', 'feel tense  ·  a tense atmosphere  ·  past tense', 'Dùng làm danh từ để chỉ "thì" trong ngữ pháp; dùng làm tính từ để chỉ sự căng thẳng hoặc căng cứng.', 'Họ từ (Word Family): tension (n.), tensely (adv.), tenseness (n.) | Trái nghĩa: relaxed', '[{"hanzi":"She looked tense while waiting outside the interview room.","pinyin":"","meaning":"Cô ấy trông có vẻ căng thẳng khi đứng chờ ngoài phòng phỏng vấn."},{"hanzi":"A tense working environment can reduce productivity and discourage employees from sharing creative ideas.","pinyin":"","meaning":"Môi trường làm việc căng thẳng có thể làm giảm năng suất và khiến nhân viên ngần ngại chia sẻ những ý tưởng sáng tạo."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_43_4', 'en-b2-43', 'Cách dùng “alarming” (adj.) — đáng báo động; đáng lo ngại', 'an alarming rate  ·  an alarming increase  ·  an alarming trend', 'Tính từ "alarming" mô tả sự việc gây lo lắng; còn "alarmed" mô tả cảm giác sợ hãi của con người.', 'Họ từ (Word Family): alarm (n.), alarm (v.), alarmed (adj.), alarmingly (adv.) | Đồng nghĩa: worrying, disturbing · Trái nghĩa: reassuring', '[{"hanzi":"The engine made an alarming noise as we climbed.","pinyin":"","meaning":"Động cơ phát ra tiếng động đáng sợ khi chúng tôi leo dốc."},{"hanzi":"The alarming decline in insect populations could threaten food production and disrupt entire ecosystems.","pinyin":"","meaning":"Sự sụt giảm số lượng côn trùng đáng báo động có thể đe dọa sản xuất lương thực và làm xáo trộn toàn bộ hệ sinh thái."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
