INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_43_1_3', 'ten_b2_43_1', 'memorable', 'That snowy train journey was a truly memorable experience.', 'That snowy train journey was a truly memorable experience.', '/ˈmemərəbl/', 'Chuyến đi tàu trong khung cảnh tuyết rơi hôm đó thực sự là một trải nghiệm khó quên.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_43_1_4', 'ten_b2_43_1', 'alarming', 'The engine made an alarming noise as we climbed.', 'The engine made an alarming noise as we climbed.', '/əˈlɑːrmɪŋ/', 'Động cơ phát ra tiếng động đáng sợ khi chúng tôi leo dốc.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_43_1_5', 'ten_b2_43_1', 'spiritual', 'Walking quietly in the forest gives me spiritual comfort.', 'Walking quietly in the forest gives me spiritual comfort.', '/ˈspɪrɪtʃuəl/', 'Đi dạo yên tĩnh trong rừng mang lại cho tôi sự an ủi về mặt tinh thần.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_43_1_6', 'ten_b2_43_1', 'tense', 'She looked tense while waiting outside the interview room.', 'She looked tense while waiting outside the interview room.', '/tens/', 'Cô ấy trông có vẻ căng thẳng khi đứng chờ ngoài phòng phỏng vấn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_43_1_7', 'ten_b2_43_1', 'distress', 'Her neighbour noticed her distress and offered to help.', 'Her neighbour noticed her distress and offered to help.', '/dɪˈstres/', 'Người hàng xóm nhận thấy cô ấy đang đau buồn và ngỏ ý muốn giúp đỡ.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_43_1_8', 'ten_b2_43_1', 'anger', 'He took a deep breath to control his anger.', 'He took a deep breath to control his anger.', '/ˈæŋɡər/', 'Anh ấy hít một hơi thật sâu để kìm nén cơn giận.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_43_1_1', 'en-b2-43', 'ten_b2_43_1', 'listening', 'listening', 'I envy your ability to sleep on noisy trains.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Sau một lần bị từ chối nữa, cô ấy đã sửa lại hồ sơ xin việc của mình.","Tôi thực sự ghen tị với khả năng ngủ ngon trên những chuyến tàu ồn ào của bạn.","Một tai nạn rủi ro đã khiến bánh xe đạp của tôi bị cong nặng.","Anh ấy khẽ rên lên khi y tá kiểm tra mắt cá chân của mình."]'::jsonb, 1, 'I envy your ability to sleep on noisy trains. → Tôi thực sự ghen tị với khả năng ngủ ngon trên những chuyến tàu ồn ào của bạn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_43_1_2', 'en-b2-43', 'ten_b2_43_1', 'listening', 'listening', 'My little brother is possessive about his toy trains.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chuyến đi tàu trong khung cảnh tuyết rơi hôm đó thực sự là một trải nghiệm khó quên.","Cô ấy lườm tôi khi tôi cắt ngang câu chuyện của cô ấy.","Những ngày trời xám xịt và mưa dầm dề khiến tôi cảm thấy chán nản.","Em trai tôi có tính chiếm hữu rất cao đối với những món đồ chơi xe lửa của nó."]'::jsonb, 3, 'My little brother is possessive about his toy trains. → Em trai tôi có tính chiếm hữu rất cao đối với những món đồ chơi xe lửa của nó.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_43_1_3', 'en-b2-43', 'ten_b2_43_1', 'listening', 'listening', 'That snowy train journey was a truly memorable experience.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy thở dài bực bội khi chuông cửa lại reo lên.","Chuyến đi tàu trong khung cảnh tuyết rơi hôm đó thực sự là một trải nghiệm khó quên.","Một tai nạn rủi ro đã khiến bánh xe đạp của tôi bị cong nặng.","Những ngày trời xám xịt và mưa dầm dề khiến tôi cảm thấy chán nản."]'::jsonb, 1, 'That snowy train journey was a truly memorable experience. → Chuyến đi tàu trong khung cảnh tuyết rơi hôm đó thực sự là một trải nghiệm khó quên.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_43_2', 'en-b2-43', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_43_2_1', 'ten_b2_43_2', 'envy', 'Social media can encourage envy by exposing users to carefully selected images of other people''s achievements and lifestyles.', 'Social media can encourage envy by exposing users to carefully selected images of other people''s achievements and lifestyles.', '/ˈenvi/', 'Mạng xã hội có thể thúc đẩy lòng ganh tị bằng cách phơi bày cho người dùng thấy những hình ảnh được chọn lọc kỹ càng về thành tựu và lối sống của người khác.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_43_2_2', 'ten_b2_43_2', 'possessive', 'Possessive behaviour in friendships can limit personal freedom and make it difficult to maintain healthy relationships.', 'Possessive behaviour in friendships can limit personal freedom and make it difficult to maintain healthy relationships.', '/pəˈzesɪv/', 'Hành vi có tính chiếm hữu trong tình bạn có thể hạn chế sự tự do cá nhân và khiến việc duy trì các mối quan hệ lành mạnh trở nên khó khăn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_43_2_3', 'ten_b2_43_2', 'memorable', 'Practical experiments often make science lessons more memorable by connecting abstract ideas with direct experience.', 'Practical experiments often make science lessons more memorable by connecting abstract ideas with direct experience.', '/ˈmemərəbl/', 'Các thí nghiệm thực tế thường làm cho giờ học khoa học trở nên đáng nhớ hơn bằng cách kết nối các khái niệm trừu tượng với trải nghiệm trực quan.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_43_2_4', 'ten_b2_43_2', 'alarming', 'The alarming decline in insect populations could threaten food production and disrupt entire ecosystems.', 'The alarming decline in insect populations could threaten food production and disrupt entire ecosystems.', '/əˈlɑːrmɪŋ/', 'Sự sụt giảm số lượng côn trùng đáng báo động có thể đe dọa sản xuất lương thực và làm xáo trộn toàn bộ hệ sinh thái.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_43_2_5', 'ten_b2_43_2', 'spiritual', 'Public spaces can support spiritual well-being by offering residents peaceful places for reflection and connection with nature.', 'Public spaces can support spiritual well-being by offering residents peaceful places for reflection and connection with nature.', '/ˈspɪrɪtʃuəl/', 'Không gian công cộng có thể thúc đẩy sức khỏe tinh thần bằng cách cung cấp cho cư dân những nơi yên bình để suy ngẫm và kết nối với thiên nhiên.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_43_2_6', 'ten_b2_43_2', 'tense', 'A tense working environment can reduce productivity and discourage employees from sharing creative ideas.', 'A tense working environment can reduce productivity and discourage employees from sharing creative ideas.', '/tens/', 'Môi trường làm việc căng thẳng có thể làm giảm năng suất và khiến nhân viên ngần ngại chia sẻ những ý tưởng sáng tạo.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_43_2_1', 'en-b2-43', 'ten_b2_43_2', 'listening', 'listening', 'Social media can encourage envy by exposing users to carefully selected images of other people''s achievements and lifestyles.', NULL, 'Trong câu vừa nghe, từ “envy” mang nghĩa nào sau đây?', '["thời đại; kỷ nguyên; giai đoạn lịch sử","sự tận tụy; tinh thần cống hiến","cây tre; tre; vật liệu bằng tre","sự ganh tị; lòng ghen tị"]'::jsonb, 3, '“envy” (/ˈenvi/): sự ganh tị; lòng ghen tị. Câu đầy đủ: Social media can encourage envy by exposing users to carefully selected images of other people''s achievements and lifestyles.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_43_2_2', 'en-b2-43', 'ten_b2_43_2', 'listening', 'listening', 'Possessive behaviour in friendships can limit personal freedom and make it difficult to maintain healthy relationships.', NULL, 'Trong câu vừa nghe, từ “possessive” mang nghĩa nào sau đây?', '["con sứa (động vật biển thân mềm có xúc tu gây ngứa)","ma sát; lực ma sát","bài tập khóa học; đồ án học phần","có tính chiếm hữu; ích kỷ trong quan hệ"]'::jsonb, 3, '“possessive” (/pəˈzesɪv/): có tính chiếm hữu; ích kỷ trong quan hệ. Câu đầy đủ: Possessive behaviour in friendships can limit personal freedom and make it difficult to maintain healthy relationships.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
