INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_43_5', 'en-b2-43', 'Walking quietly in the forest gives me spiritual comfort', 'Đi dạo yên tĩnh trong rừng mang lại cho tôi sự an ủi về mặt tinh thần.', 'spiritual /ˈspɪrɪtʃuəl/', '["Walking","gives","me","the","spiritual","forest","comfort","in","quietly"]'::jsonb, NULL, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
