INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_43_1', 'en-b2-43', NULL, 'comprehensive_test', 'listening', 'envy', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự ganh tị; lòng ghen tị","làm nhiễm trùng; lây bệnh","sự điều hướng; sự định vị và dẫn đường","thép; ngành thép"]'::jsonb, 0, 'envy (/ˈenvi/) → sự ganh tị; lòng ghen tị; ghen tị; thèm muốn; người hoặc vật khiến người khác ao ước', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_43_2', 'en-b2-43', NULL, 'comprehensive_test', 'listening', 'My little brother is possessive about his toy trains.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Em trai tôi có tính chiếm hữu rất cao đối với những món đồ chơi xe lửa của nó.","Cô ấy trông có vẻ căng thẳng khi đứng chờ ngoài phòng phỏng vấn.","Anh ấy tự mắng mình là đồ hèn nhát vì đã né tránh cuộc trò chuyện đó.","Sau một lần bị từ chối nữa, cô ấy đã sửa lại hồ sơ xin việc của mình."]'::jsonb, 0, 'My little brother is possessive about his toy trains. → Em trai tôi có tính chiếm hữu rất cao đối với những món đồ chơi xe lửa của nó.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_43_3', 'en-b2-43', NULL, 'comprehensive_test', 'listening', 'memorable', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đáng nhớ; khó quên","có tay nghề; lành nghề","cuối cùng; sau một chuỗi sự kiện","thấu kính, kính, tròng kính"]'::jsonb, 0, 'memorable (/ˈmemərəbl/) → đáng nhớ; khó quên', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_43_4', 'en-b2-43', NULL, 'comprehensive_test', 'listening', 'The engine made an alarming noise as we climbed.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Anh ấy bắt đầu khóc khi con chó bị lạc của mình quay trở lại.","Một tai nạn rủi ro đã khiến bánh xe đạp của tôi bị cong nặng.","Động cơ phát ra tiếng động đáng sợ khi chúng tôi leo dốc.","Cô ấy lườm tôi khi tôi cắt ngang câu chuyện của cô ấy."]'::jsonb, 2, 'The engine made an alarming noise as we climbed. → Động cơ phát ra tiếng động đáng sợ khi chúng tôi leo dốc.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_43_5', 'en-b2-43', NULL, 'comprehensive_test', 'listening', 'spiritual', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["độ ẩm không khí","cuộc điều tra; sự tìm hiểu","thuộc về tinh thần; thuộc về tâm hồn","do đó; vì vậy; kết quả là"]'::jsonb, 2, 'spiritual (/ˈspɪrɪtʃuəl/) → thuộc về tinh thần; thuộc về tâm hồn; thuộc về tôn giáo; thuộc về tâm linh', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_43_6', 'en-b2-43', NULL, 'comprehensive_test', 'listening', 'She looked tense while waiting outside the interview room.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy tỏ ra ngập ngừng trước khi bước lên cây cầu hẹp.","Em trai tôi có tính chiếm hữu rất cao đối với những món đồ chơi xe lửa của nó.","Đây là nơi đầu tiên tôi cảm thấy thực sự thoải mái.","Cô ấy trông có vẻ căng thẳng khi đứng chờ ngoài phòng phỏng vấn."]'::jsonb, 3, 'She looked tense while waiting outside the interview room. → Cô ấy trông có vẻ căng thẳng khi đứng chờ ngoài phòng phỏng vấn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_43_7', 'en-b2-43', NULL, 'comprehensive_test', 'listening', 'distress', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["khoảng thời gian; khoảng cách","chuyến đi bộ đường dài gian khổ","lướt ván diều","nỗi thống khổ; sự đau buồn; sự lo lắng"]'::jsonb, 3, 'distress (/dɪˈstres/) → nỗi thống khổ; sự đau buồn; sự lo lắng; tình trạng nguy cấp; hoàn cảnh khó khăn; làm đau khổ; gây phiền muộn', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_43_8', 'en-b2-43', NULL, 'comprehensive_test', 'listening', 'He took a deep breath to control his anger.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những cuộc họp kéo dài khiến tôi phát chán, đặc biệt khi chẳng ai có điều gì mới mẻ để nói.","Động cơ phát ra tiếng động đáng sợ khi chúng tôi leo dốc.","Đi dạo yên tĩnh trong rừng mang lại cho tôi sự an ủi về mặt tinh thần.","Anh ấy hít một hơi thật sâu để kìm nén cơn giận."]'::jsonb, 3, 'He took a deep breath to control his anger. → Anh ấy hít một hơi thật sâu để kìm nén cơn giận.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_43_9', 'en-b2-43', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Connected with inner feelings and meaning rather than material things.”?', '["uneasy","loneliness","tense","spiritual"]'::jsonb, 3, 'spiritual (/ˈspɪrɪtʃuəl/) → thuộc về tinh thần; thuộc về tâm hồn', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_43_10', 'en-b2-43', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Nervous and unable to relax, or stretched tightly.”?', '["tense","uneasy","relief","annoyance"]'::jsonb, 0, 'tense (/tens/) → căng thẳng; căng', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_43_11', 'en-b2-43', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “great emotional pain, worry, or unhappiness”?', '["rejection","distress","spiritual","moan"]'::jsonb, 1, 'distress (/dɪˈstres/) → nỗi thống khổ; sự đau buồn; sự lo lắng', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_43_12', 'en-b2-43', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a strong feeling of displeasure about something wrong or unfair”?', '["possessive","anger","unfortunate","alarming"]'::jsonb, 1, 'anger (/ˈæŋɡər/) → sự tức giận; cơn giận', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_43_13', 'en-b2-43', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Comfort felt when worry or fear ends”?', '["moan","glare","relief","hesitant"]'::jsonb, 2, 'relief (/rɪˈliːf/) → sự nhẹ nhõm; sự thở phào', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
