INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_43_18', 'en-b2-43', NULL, 'comprehensive_test', 'reading', NULL, 'Social media can encourage envy by exposing users to carefully selected images of other people''s achievements and lifestyles.', 'Dựa vào câu trên, từ “envy” có nghĩa phù hợp nhất là gì?', '["gập ghềnh; không bằng phẳng; nhấp nhô","chấp nhận; đón nhận, hưởng ứng","nhãn hiệu; thương hiệu đã đăng ký","sự ganh tị; lòng ghen tị"]'::jsonb, 3, 'envy: sự ganh tị; lòng ghen tị; ghen tị; thèm muốn; người hoặc vật khiến người khác ao ước. Dịch cả câu: Mạng xã hội có thể thúc đẩy lòng ganh tị bằng cách phơi bày cho người dùng thấy những hình ảnh được chọn lọc kỹ càng về thành tựu và lối sống của người khác.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_43_19', 'en-b2-43', NULL, 'comprehensive_test', 'reading', NULL, 'Possessive behaviour in friendships can limit personal freedom and make it difficult to maintain healthy relationships.', 'Dựa vào câu trên, từ “possessive” có nghĩa phù hợp nhất là gì?', '["nữ nhân vật chính; nữ chính","có tính chiếm hữu; ích kỷ trong quan hệ","rất ít; tối thiểu; ở mức thấp nhất","thú nhận; thú tội; khai nhận"]'::jsonb, 1, 'possessive: có tính chiếm hữu; ích kỷ trong quan hệ; thuộc sở hữu; biểu thị sự sở hữu. Dịch cả câu: Hành vi có tính chiếm hữu trong tình bạn có thể hạn chế sự tự do cá nhân và khiến việc duy trì các mối quan hệ lành mạnh trở nên khó khăn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_43_20', 'en-b2-43', NULL, 'comprehensive_test', 'reading', NULL, 'Practical experiments often make science lessons more memorable by connecting abstract ideas with direct experience.', 'Dựa vào câu trên, từ “memorable” có nghĩa phù hợp nhất là gì?', '["sự khoan dung; lòng trắc ẩn; sự nhân nhượng (không trừng phạt hoặc làm hại)","đáng nhớ; khó quên","đang diễn ra; tiếp tục","phần lớn; đa số"]'::jsonb, 1, 'memorable: đáng nhớ; khó quên. Dịch cả câu: Các thí nghiệm thực tế thường làm cho giờ học khoa học trở nên đáng nhớ hơn bằng cách kết nối các khái niệm trừu tượng với trải nghiệm trực quan.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_43_21', 'en-b2-43', NULL, 'comprehensive_test', 'reading', NULL, 'The alarming decline in insect populations could threaten food production and disrupt entire ecosystems.', 'Dựa vào câu trên, từ “alarming” có nghĩa phù hợp nhất là gì?', '["hành vi tự sát; sự tự tử","lỗ thủng; vết thủng lốp","đáng báo động; đáng lo ngại","đoạn điệp khúc; khúc nối (trong bài hát)"]'::jsonb, 2, 'alarming: đáng báo động; đáng lo ngại. Dịch cả câu: Sự sụt giảm số lượng côn trùng đáng báo động có thể đe dọa sản xuất lương thực và làm xáo trộn toàn bộ hệ sinh thái.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_43_22', 'en-b2-43', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “khóc; rơi lệ”', '["rapid","anger","weep","sibling"]'::jsonb, 2, 'khóc; rơi lệ → weep (/wiːp/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_43_23', 'en-b2-43', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự từ chối; sự bác bỏ”', '["loop","rejection","firm","rotation"]'::jsonb, 1, 'sự từ chối; sự bác bỏ → rejection (/rɪˈdʒekʃən/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_43_24', 'en-b2-43', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thực sự; đích thực”', '["truly","grease","harvest","comparatively"]'::jsonb, 0, 'thực sự; đích thực → truly (/ˈtruːli/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-44', 'en', 'Bài 44: Cảm xúc & Tính cách (4) - CEFR B2', 'CEFR B2', 'B2 · Cảm xúc', '24 từ vựng Tiếng Anh CEFR B2 chủ đề cảm xúc & tính cách kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4044, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sincere', 'en-b2-44', 'sincere', '/sɪnˈsɪr/', 'B2', 'chân thành; thành khẩn; thật lòng', 'adj.', 'sincerely (adv.), sincerity (n.), insincere (adj.)', 'Đồng nghĩa: genuine, heartfelt · Trái nghĩa: insincere', 'Tính từ sincere nhấn mạnh sự không giả dối; trạng từ sincerely thường được dùng ở phần kết thư.', 'Her sincere apology helped us become friends again.', NULL, 'Lời xin lỗi chân thành của cô ấy đã giúp chúng tôi làm lành với nhau.', '{"wordId":"sincere","ukIpa":"/sɪnˈsɪə/","usIpa":"/sɪnˈsɪr/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"Honestly expressing what you really feel or believe","vi":"chân thành; thành khẩn; thật lòng"}],"examples":[{"en":"Her sincere apology helped us become friends again.","vi":"Lời xin lỗi chân thành của cô ấy đã giúp chúng tôi làm lành với nhau.","audioKind":"ex"},{"en":"Sincere efforts to consult local residents can strengthen public trust in major urban development projects.","vi":"Những nỗ lực chân thành nhằm tham vấn người dân địa phương có thể củng cố niềm tin của công chúng đối với các dự án phát triển đô thị quy mô lớn.","audioKind":"ex2"}],"collocations":[{"en":"sincere apology","vi":"lời xin lỗi chân thành"},{"en":"sincere thanks","vi":"lòng biết ơn chân thành"},{"en":"sincere desire","vi":"mong ước chân thành"}],"wordFamily":["sincerely (adv.)","sincerity (n.)","insincere (adj.)"],"synonyms":["genuine","heartfelt"],"antonyms":["insincere"],"tipVi":"Tính từ sincere nhấn mạnh sự không giả dối; trạng từ sincerely thường được dùng ở phần kết thư.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_overwhelm', 'en-b2-44', 'overwhelm', '/ˌoʊvərˈwelm/', 'B2', 'làm cho ngộp thở; làm cho không biết xoay sở thế nào; làm cho quá tải; làm cho không kham nổi; đánh bại hoàn toàn; áp đảo', 'v.', 'overwhelming (adj.), overwhelmed (adj.), overwhelmingly (adv.)', 'Đồng nghĩa: overpower, swamp', 'Con người cảm thấy overwhelmed; sự vật, tình huống gây ra cảm giác overwhelming.', 'I felt overwhelmed by everyone''s kindness after the move.', NULL, 'Sau khi chuyển nhà, tôi cảm thấy vô cùng xúc động trước sự tử tế của mọi người.', '{"wordId":"overwhelm","ukIpa":"/ˌəʊvəˈwelm/","usIpa":"/ˌoʊvərˈwelm/","cefr":"B2","topic":"emotion","senses":[{"pos":"v.","en":"To affect someone so strongly they cannot cope.","vi":"làm cho ngộp thở; làm cho không biết xoay sở thế nào"},{"pos":"v.","en":"To give a system or person more than they can handle.","vi":"làm cho quá tải; làm cho không kham nổi"},{"pos":"v.","en":"To defeat someone using much greater strength.","vi":"đánh bại hoàn toàn; áp đảo"}],"examples":[{"en":"I felt overwhelmed by everyone''s kindness after the move.","vi":"Sau khi chuyển nhà, tôi cảm thấy vô cùng xúc động trước sự tử tế của mọi người.","audioKind":"ex"},{"en":"A sudden increase in visitors can overwhelm local infrastructure unless tourism growth is carefully managed.","vi":"Sự gia tăng đột biến của lượng du khách có thể làm quá tải cơ sở hạ tầng địa phương trừ khi sự phát triển du lịch được quản lý cẩn thận.","audioKind":"ex2"}],"collocations":[{"en":"feel overwhelmed","vi":"cảm thấy ngợp; cảm thấy quá tải"},{"en":"be overwhelmed by emotion","vi":"xúc động đến mức không kìm nén được"},{"en":"overwhelm local services","vi":"làm quá tải các dịch vụ địa phương"}],"wordFamily":["overwhelming (adj.)","overwhelmed (adj.)","overwhelmingly (adv.)"],"synonyms":["overpower","swamp"],"antonyms":[],"tipVi":"Con người cảm thấy overwhelmed; sự vật, tình huống gây ra cảm giác overwhelming.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_despair', 'en-b2-44', 'despair', '/dɪˈsper/', 'B2', 'sự tuyệt vọng; mất hết hy vọng; tuyệt vọng', 'n.', 'despairing (adj.), despairingly (adv.)', 'Đồng nghĩa: hopelessness · Trái nghĩa: hope', 'Danh từ thường không đếm được; động từ thường đi với giới từ of chứ không cộng tân ngữ trực tiếp.', 'He felt deep despair when his final application was rejected.', NULL, 'Anh ấy cảm thấy tuyệt vọng tột cùng khi đơn xin việc cuối cùng bị từ chối.', '{"wordId":"despair","ukIpa":"/dɪˈspeə/","usIpa":"/dɪˈsper/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"The feeling that there is no hope.","vi":"sự tuyệt vọng"},{"pos":"v.","en":"To lose all hope that things will improve.","vi":"mất hết hy vọng; tuyệt vọng"}],"examples":[{"en":"He felt deep despair when his final application was rejected.","vi":"Anh ấy cảm thấy tuyệt vọng tột cùng khi đơn xin việc cuối cùng bị từ chối.","audioKind":"ex"},{"en":"Long periods of unemployment can lead to despair, highlighting the importance of accessible career advice and emotional support.","vi":"Tình trạng thất nghiệp kéo dài có thể dẫn đến sự tuyệt vọng, làm nổi bật tầm quan trọng của việc tiếp cận các dịch vụ tư vấn nghề nghiệp và hỗ trợ tinh thần.","audioKind":"ex2"}],"collocations":[{"en":"in despair","vi":"trong sự tuyệt vọng"},{"en":"a sense of despair","vi":"cảm giác tuyệt vọng"},{"en":"despair of doing something","vi":"tuyệt vọng không còn hy vọng làm gì"}],"wordFamily":["despairing (adj.)","despairingly (adv.)"],"synonyms":["hopelessness"],"antonyms":["hope"],"tipVi":"Danh từ thường không đếm được; động từ thường đi với giới từ of chứ không cộng tân ngữ trực tiếp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hilarious', 'en-b2-44', 'hilarious', '/hɪˈleriəs/', 'B2', 'vô cùng hài hước; cực kỳ buồn cười', 'adj.', 'hilariously (adv.), hilarity (n.)', 'Đồng nghĩa: very funny, side-splitting', 'Nhấn mạnh ý nghĩa "vô cùng buồn cười", không chỉ đơn thuần là vui vẻ hay náo nhiệt.', 'Her hilarious story made everyone laugh throughout dinner.', NULL, 'Câu chuyện cực kỳ hài hước của cô ấy khiến mọi người cười suốt bữa tối.', '{"wordId":"hilarious","ukIpa":"/hɪˈleəriəs/","usIpa":"/hɪˈleriəs/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"extremely funny and likely to make people laugh","vi":"vô cùng hài hước; cực kỳ buồn cười"}],"examples":[{"en":"Her hilarious story made everyone laugh throughout dinner.","vi":"Câu chuyện cực kỳ hài hước của cô ấy khiến mọi người cười suốt bữa tối.","audioKind":"ex"},{"en":"Although hilarious advertisements can attract attention, humour does not always help consumers remember the product being promoted.","vi":"Mặc dù những quảng cáo gây cười có thể thu hút sự chú ý, sự hài hước không phải lúc nào cũng giúp người tiêu dùng ghi nhớ sản phẩm được quảng cáo.","audioKind":"ex2"}],"collocations":[{"en":"hilarious story","vi":"câu chuyện cười ra nước mắt"},{"en":"hilarious comedy","vi":"phim hài cười thả ga"},{"en":"absolutely hilarious","vi":"cực kỳ hài hước"}],"wordFamily":["hilariously (adv.)","hilarity (n.)"],"synonyms":["very funny","side-splitting"],"antonyms":[],"tipVi":"Nhấn mạnh ý nghĩa \"vô cùng buồn cười\", không chỉ đơn thuần là vui vẻ hay náo nhiệt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exclaim', 'en-b2-44', 'exclaim', '/ɪkˈskleɪm/', 'B2', 'kêu lên; thốt lên', 'v.', 'exclamation (n.), exclamatory (adj.)', 'Đồng nghĩa: cry out', 'Nhấn mạnh việc phát ra âm thanh đột ngột do cảm xúc mạnh, thường dùng để dẫn lời nói trực tiếp.', '“What a beautiful rainbow!” she exclaimed, pointing towards the hills.', NULL, '"Cầu vồng đẹp quá!" cô ấy thốt lên, vừa chỉ tay về phía những ngọn đồi.', '{"wordId":"exclaim","ukIpa":"/ɪkˈskleɪm/","usIpa":"/ɪkˈskleɪm/","cefr":"B2","topic":"emotion","senses":[{"pos":"v.","en":"to say something suddenly and loudly because of strong emotion","vi":"kêu lên; thốt lên"}],"examples":[{"en":"“What a beautiful rainbow!” she exclaimed, pointing towards the hills.","vi":"\"Cầu vồng đẹp quá!\" cô ấy thốt lên, vừa chỉ tay về phía những ngọn đồi.","audioKind":"ex"},{"en":"Visitors often exclaim in surprise when museum displays reveal the impressive engineering skills of ancient societies.","vi":"Khách tham quan thường thốt lên ngạc nhiên khi các hiện vật bảo tàng cho thấy kỹ năng chế tạo ấn tượng của các xã hội cổ đại.","audioKind":"ex2"}],"collocations":[{"en":"exclaim in surprise","vi":"thốt lên vì ngạc nhiên"},{"en":"exclaim with delight","vi":"vui sướng kêu lên"}],"wordFamily":["exclamation (n.)","exclamatory (adj.)"],"synonyms":["cry out"],"antonyms":[],"tipVi":"Nhấn mạnh việc phát ra âm thanh đột ngột do cảm xúc mạnh, thường dùng để dẫn lời nói trực tiếp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spite', 'en-b2-44', 'spite', '/spaɪt/', 'B2', 'ác ý; sự thù hằn; cố tình làm tổn thương; trù dập', 'n.', 'spiteful (adj.), spitefully (adv.)', 'Đồng nghĩa: malice · Trái nghĩa: goodwill', 'Cụm từ in spite of theo sau bởi danh từ hoặc danh động từ, tuyệt đối không đi trực tiếp với một mệnh đề chứa chủ ngữ và động từ.', 'He hid his sister''s favourite toy out of spite.', NULL, 'Cậu ta giấu món đồ chơi yêu thích của em gái đi chỉ vì ác ý.', '{"wordId":"spite","ukIpa":"/spaɪt/","usIpa":"/spaɪt/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"A desire to upset or hurt someone deliberately.","vi":"ác ý; sự thù hằn"},{"pos":"v.","en":"To deliberately upset someone, often because you feel angry.","vi":"cố tình làm tổn thương; trù dập"}],"examples":[{"en":"He hid his sister''s favourite toy out of spite.","vi":"Cậu ta giấu món đồ chơi yêu thích của em gái đi chỉ vì ác ý.","audioKind":"ex"},{"en":"In spite of limited funding, the community centre continues to provide valuable support for local families.","vi":"Bất chấp nguồn kinh phí hạn hẹp, trung tâm cộng đồng vẫn tiếp tục cung cấp sự hỗ trợ quý giá cho các gia đình địa phương.","audioKind":"ex2"}],"collocations":[{"en":"out of spite","vi":"vì ác ý; do ganh ghét"},{"en":"in spite of","vi":"mặc dù; dẫu cho"},{"en":"pure spite","vi":"ác ý thuần túy"}],"wordFamily":["spiteful (adj.)","spitefully (adv.)"],"synonyms":["malice"],"antonyms":["goodwill"],"tipVi":"Cụm từ in spite of theo sau bởi danh từ hoặc danh động từ, tuyệt đối không đi trực tiếp với một mệnh đề chứa chủ ngữ và động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_emotion', 'en-b2-44', 'emotion', '/ɪˈmoʊʃən/', 'B2', 'cảm xúc; tình cảm', 'n.', 'emotional (adj.), emotionally (adv.), emotionless (adj.)', 'Đồng nghĩa: feeling', 'Khi chỉ chung chung tình cảm có thể không đếm được; các loại cảm xúc cụ thể thường dùng emotions.', 'Her voice shook with emotion when she saw her brother.', NULL, 'Giọng cô ấy run lên vì xúc động khi nhìn thấy anh trai mình.', '{"wordId":"emotion","ukIpa":"/ɪˈməʊʃən/","usIpa":"/ɪˈmoʊʃən/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"a strong feeling such as joy, fear, or sadness","vi":"cảm xúc; tình cảm"}],"examples":[{"en":"Her voice shook with emotion when she saw her brother.","vi":"Giọng cô ấy run lên vì xúc động khi nhìn thấy anh trai mình.","audioKind":"ex"},{"en":"Teaching children to recognise and manage emotion can improve their relationships and support long-term mental health.","vi":"Dạy trẻ em nhận biết và quản lý cảm xúc có thể cải thiện các mối quan hệ của chúng và hỗ trợ sức khỏe tinh thần lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"express emotion","vi":"bày tỏ cảm xúc"},{"en":"strong emotions","vi":"cảm xúc mãnh liệt"},{"en":"mixed emotions","vi":"cảm xúc lẫn lộn"},{"en":"control your emotions","vi":"kiểm soát cảm xúc của bạn"}],"wordFamily":["emotional (adj.)","emotionally (adv.)","emotionless (adj.)"],"synonyms":["feeling"],"antonyms":[],"tipVi":"Khi chỉ chung chung tình cảm có thể không đếm được; các loại cảm xúc cụ thể thường dùng emotions.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grin', 'en-b2-44', 'grin', '/ɡrɪn/', 'B2', 'cười toe toét; cười hở mười cái răng; nụ cười toe toét', 'v.', NULL, 'Đồng nghĩa: smile, beam · Trái nghĩa: frown', 'grin nhấn mạnh việc cười hở răng hơn smile; dạng quá khứ là grinned.', 'She grinned when her puppy brought back the ball.', NULL, 'Cô ấy cười toe toét khi chú cún mang quả bóng về.', '{"wordId":"grin","ukIpa":"/ɡrɪn/","usIpa":"/ɡrɪn/","cefr":"B2","topic":"emotion","senses":[{"pos":"v.","en":"To smile widely, usually showing your teeth.","vi":"cười toe toét; cười hở mười cái răng"},{"pos":"n.","en":"A broad smile that usually shows the teeth.","vi":"nụ cười toe toét"}],"examples":[{"en":"She grinned when her puppy brought back the ball.","vi":"Cô ấy cười toe toét khi chú cún mang quả bóng về.","audioKind":"ex"},{"en":"A friendly grin from a teacher may help nervous students feel more comfortable participating in classroom discussions.","vi":"Một nụ cười thân thiện từ giáo viên có thể giúp những học sinh lo lắng cảm thấy thoải mái hơn khi tham gia thảo luận trên lớp.","audioKind":"ex2"}],"collocations":[{"en":"grin broadly","vi":"cười toe toét rạng rỡ"},{"en":"a cheeky grin","vi":"nụ cười ranh mãnh"},{"en":"grin at someone","vi":"cười toe toét với ai đó"}],"wordFamily":[],"synonyms":["smile","beam"],"antonyms":["frown"],"tipVi":"grin nhấn mạnh việc cười hở răng hơn smile; dạng quá khứ là grinned.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_eager', 'en-b2-44', 'eager', '/ˈiːɡər/', 'B2', 'háo hức, mong mỏi, nhiệt tình làm hoặc có điều gì', 'adj.', 'eagerly (adv.), eagerness (n.)', 'Đồng nghĩa: keen, enthusiastic · Trái nghĩa: reluctant', 'Thường đi với cấu trúc eager to do hoặc eager for cộng với danh từ.', 'The children were eager to open their presents.', NULL, 'Bọn trẻ háo hức muốn mở quà của mình.', '{"wordId":"eager","ukIpa":"/ˈiːɡə/","usIpa":"/ˈiːɡər/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"very interested and excited about doing or having something","vi":"háo hức, mong mỏi, nhiệt tình làm hoặc có điều gì"}],"examples":[{"en":"The children were eager to open their presents.","vi":"Bọn trẻ háo hức muốn mở quà của mình.","audioKind":"ex"},{"en":"Many graduates are eager to gain practical experience before committing to a particular career path.","vi":"Nhiều sinh viên mới ra trường rất khao khát tích lũy kinh nghiệm thực tế trước khi theo đuổi một con đường sự nghiệp cụ thể.","audioKind":"ex2"}],"collocations":[{"en":"eager to learn","vi":"khao khát học hỏi"},{"en":"eager for success","vi":"khát khao thành công"},{"en":"eager anticipation","vi":"sự mong chờ háo hức"}],"wordFamily":["eagerly (adv.)","eagerness (n.)"],"synonyms":["keen","enthusiastic"],"antonyms":["reluctant"],"tipVi":"Thường đi với cấu trúc eager to do hoặc eager for cộng với danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_irritate', 'en-b2-44', 'irritate', '/ˈɪrɪteɪt/', 'B2', 'làm phiền; gây bực bội; chọc tức; làm kích ứng; gây khó chịu', 'v.', 'irritation (n.), irritating (adj.), irritated (adj.), irritant (n.)', 'Đồng nghĩa: annoy, bother · Trái nghĩa: soothe', 'irritated dùng để miêu tả cảm giác bực bội của con người; irritating dùng để miêu tả sự vật gây khó chịu.', 'The constant dripping from the tap really irritates me.', NULL, 'Tiếng nước nhỏ giọt liên tục từ vòi nước thực sự làm tôi bực mình.', '{"wordId":"irritate","ukIpa":"/ˈɪrɪteɪt/","usIpa":"/ˈɪrɪteɪt/","cefr":"B2","topic":"emotion","senses":[{"pos":"v.","en":"To make someone feel annoyed or impatient.","vi":"làm phiền; gây bực bội; chọc tức"},{"pos":"v.","en":"To make skin or another body part sore or uncomfortable.","vi":"làm kích ứng; gây khó chịu"}],"examples":[{"en":"The constant dripping from the tap really irritates me.","vi":"Tiếng nước nhỏ giọt liên tục từ vòi nước thực sự làm tôi bực mình.","audioKind":"ex"},{"en":"Some household cleaning products contain chemicals that can irritate the skin and cause breathing difficulties.","vi":"Một số sản phẩm tẩy rửa gia dụng chứa các hóa chất có thể gây kích ứng da và gây khó khăn khi hít thở.","audioKind":"ex2"}],"collocations":[{"en":"irritate the skin","vi":"kích ứng da"},{"en":"irritate the eyes","vi":"gây kích ứng mắt"},{"en":"really irritate someone","vi":"thực sự chọc tức ai đó"}],"wordFamily":["irritation (n.)","irritating (adj.)","irritated (adj.)","irritant (n.)"],"synonyms":["annoy","bother"],"antonyms":["soothe"],"tipVi":"irritated dùng để miêu tả cảm giác bực bội của con người; irritating dùng để miêu tả sự vật gây khó chịu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_concerned', 'en-b2-44', 'concerned', '/kənˈsɝːnd/', 'B2', 'lo lắng; bận tâm; liên quan; có dính líu; quan tâm; chú ý đến', 'adj.', 'concern (n.), concern (v.), concerning (prep.), unconcerned (adj.)', 'Đồng nghĩa: worried, anxious · Trái nghĩa: unconcerned', 'about thường đi với đối tượng gây lo lắng; with thường đi với chủ đề liên quan.', 'I was concerned when you missed the last bus.', NULL, 'Tôi đã rất lo lắng khi bạn lỡ chuyến xe buýt cuối cùng.', '{"wordId":"concerned","ukIpa":"/kənˈsɜːnd/","usIpa":"/kənˈsɝːnd/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"Worried about someone or something.","vi":"lo lắng; bận tâm"},{"pos":"adj.","en":"Involved in or affected by a particular matter.","vi":"liên quan; có dính líu"},{"pos":"adj.","en":"Interested in or dealing with a particular subject.","vi":"quan tâm; chú ý đến"}],"examples":[{"en":"I was concerned when you missed the last bus.","vi":"Tôi đã rất lo lắng khi bạn lỡ chuyến xe buýt cuối cùng.","audioKind":"ex"},{"en":"Residents are increasingly concerned about air pollution and want local authorities to improve public transport.","vi":"Người dân ngày càng lo ngại về ô nhiễm không khí và muốn chính quyền địa phương cải thiện giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"concerned about","vi":"lo lắng về"},{"en":"the people concerned","vi":"những người có liên quan"},{"en":"concerned with","vi":"liên quan đến; quan tâm đến"},{"en":"as far as I am concerned","vi":"theo như tôi được biết"}],"wordFamily":["concern (n.)","concern (v.)","concerning (prep.)","unconcerned (adj.)"],"synonyms":["worried","anxious"],"antonyms":["unconcerned"],"tipVi":"about thường đi với đối tượng gây lo lắng; with thường đi với chủ đề liên quan.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sincerely', 'en-b2-44', 'sincerely', '/sɪnˈsɪrli/', 'B2', 'một cách chân thành; từ đáy lòng', 'adv.', 'sincere (adj.), sincerity (n.), insincere (adj.)', 'Đồng nghĩa: genuinely, earnestly · Trái nghĩa: insincerely', 'Trong thư tín tiếng Anh, khi biết rõ tên người nhận, phần kết thư thường dùng Yours sincerely.', 'I sincerely hope you feel better very soon.', NULL, 'Tôi chân thành hy vọng bạn sẽ sớm khỏe lại.', '{"wordId":"sincerely","ukIpa":"/sɪnˈsɪəli/","usIpa":"/sɪnˈsɪrli/","cefr":"B2","topic":"emotion","senses":[{"pos":"adv.","en":"In a way that expresses what you genuinely feel.","vi":"một cách chân thành; từ đáy lòng"}],"examples":[{"en":"I sincerely hope you feel better very soon.","vi":"Tôi chân thành hy vọng bạn sẽ sớm khỏe lại.","audioKind":"ex"},{"en":"Organisations should listen sincerely to residents'' concerns before introducing changes that affect the local community.","vi":"Các tổ chức nên lắng nghe một cách chân thành những mối quan tâm của người dân trước khi đưa ra các thay đổi ảnh hưởng đến cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"sincerely hope","vi":"chân thành hy vọng"},{"en":"sincerely apologise","vi":"thành thật xin lỗi"},{"en":"sincerely believe","vi":"thành tâm tin rằng"},{"en":"Yours sincerely","vi":"Trân trọng"}],"wordFamily":["sincere (adj.)","sincerity (n.)","insincere (adj.)"],"synonyms":["genuinely","earnestly"],"antonyms":["insincerely"],"tipVi":"Trong thư tín tiếng Anh, khi biết rõ tên người nhận, phần kết thư thường dùng Yours sincerely.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tragic', 'en-b2-44', 'tragic', '/ˈtrædʒɪk/', 'B2', 'bi thảm; đau thương; thuộc về bi kịch', 'adj.', 'tragedy (n.), tragically (adv.)', 'Đồng nghĩa: heartbreaking, disastrous', 'Có mức độ nghiêm trọng hơn "sad", thường liên quan đến tử vong hoặc tai họa lớn.', 'The film tells a tragic story of lost friendship.', NULL, 'Bộ phim kể về câu chuyện bi thảm về một tình bạn đã tan vỡ.', '{"wordId":"tragic","ukIpa":"/ˈtrædʒɪk/","usIpa":"/ˈtrædʒɪk/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"Causing deep sadness, especially through death or serious suffering.","vi":"bi thảm; đau thương"},{"pos":"adj.","en":"Relating to a serious play or story with an unhappy ending.","vi":"thuộc về bi kịch"}],"examples":[{"en":"The film tells a tragic story of lost friendship.","vi":"Bộ phim kể về câu chuyện bi thảm về một tình bạn đã tan vỡ.","audioKind":"ex"},{"en":"Tragic accidents on busy roads highlight the need for safer crossings and stricter enforcement of speed limits.","vi":"Những vụ tai nạn bi thảm trên các tuyến đường đông đúc cho thấy sự cần thiết phải có lối sang đường an toàn hơn và thực thi nghiêm ngặt hơn các quy định về tốc độ.","audioKind":"ex2"}],"collocations":[{"en":"a tragic accident","vi":"một vụ tai nạn bi thảm"},{"en":"a tragic loss","vi":"một mất mát đau thương"},{"en":"a tragic ending","vi":"một cái kết bi thảm"},{"en":"a tragic hero","vi":"nhân vật chính bi kịch"}],"wordFamily":["tragedy (n.)","tragically (adv.)"],"synonyms":["heartbreaking","disastrous"],"antonyms":[],"tipVi":"Có mức độ nghiêm trọng hơn \"sad\", thường liên quan đến tử vong hoặc tai họa lớn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_satisfaction', 'en-b2-44', 'satisfaction', '/ˌsætɪsˈfækʃən/', 'B2', 'sự hài lòng; sự thỏa mãn; sự đáp ứng; sự thỏa mãn (nhu cầu, yêu cầu)', 'n.', 'satisfy (v.), satisfied (adj.), satisfying (adj.), satisfactory (adj.)', 'Đồng nghĩa: contentment, fulfilment · Trái nghĩa: dissatisfaction', 'thường là danh từ không đếm được; hài lòng với cái gì thường dùng satisfaction with.', 'He smiled with satisfaction after fixing the broken chair.', NULL, 'Anh ấy mỉm cười đầy thỏa mãn sau khi sửa xong chiếc ghế hỏng.', '{"wordId":"satisfaction","ukIpa":"/ˌsætɪsˈfækʃən/","usIpa":"/ˌsætɪsˈfækʃən/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"Pleasure felt when needs, wishes, or expectations are fulfilled.","vi":"sự hài lòng; sự thỏa mãn"},{"pos":"n.","en":"The act of meeting a need, demand, or requirement.","vi":"sự đáp ứng; sự thỏa mãn (nhu cầu, yêu cầu)"}],"examples":[{"en":"He smiled with satisfaction after fixing the broken chair.","vi":"Anh ấy mỉm cười đầy thỏa mãn sau khi sửa xong chiếc ghế hỏng.","audioKind":"ex"},{"en":"Greater job satisfaction can reduce staff turnover and encourage employees to contribute more actively to their organisations.","vi":"Sự hài lòng trong công việc cao hơn có thể làm giảm tỷ lệ nhân viên nghỉ việc và khuyến khích họ đóng góp tích cực hơn cho tổ chức của mình.","audioKind":"ex2"}],"collocations":[{"en":"job satisfaction","vi":"sự hài lòng trong công việc"},{"en":"customer satisfaction","vi":"sự hài lòng của khách hàng"},{"en":"a sense of satisfaction","vi":"cảm giác thỏa mãn"},{"en":"the satisfaction of basic needs","vi":"sự đáp ứng các nhu cầu cơ bản"}],"wordFamily":["satisfy (v.)","satisfied (adj.)","satisfying (adj.)","satisfactory (adj.)"],"synonyms":["contentment","fulfilment"],"antonyms":["dissatisfaction"],"tipVi":"thường là danh từ không đếm được; hài lòng với cái gì thường dùng satisfaction with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_anxiety', 'en-b2-44', 'anxiety', '/æŋˈzaɪəti/', 'B2', 'sự lo lắng; sự bồn chồn', 'n.', 'anxious (adj.), anxiously (adv.)', 'Đồng nghĩa: worry, unease · Trái nghĩa: calm', 'anxiety about theo sau là điều gây lo lắng; tính từ là anxious.', 'Her anxiety faded when she heard the good news.', NULL, 'Sự lo lắng của cô ấy tan biến khi nghe được tin vui.', '{"wordId":"anxiety","ukIpa":"/æŋˈzaɪəti/","usIpa":"/æŋˈzaɪəti/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"Worry or nervousness about something uncertain or threatening.","vi":"sự lo lắng; sự bồn chồn"}],"examples":[{"en":"Her anxiety faded when she heard the good news.","vi":"Sự lo lắng của cô ấy tan biến khi nghe được tin vui.","audioKind":"ex"},{"en":"Regular physical activity can reduce anxiety among students facing demanding examinations and uncertain career prospects.","vi":"Hoạt động thể chất đều đặn có thể làm giảm bớt sự lo lắng ở học sinh, sinh viên khi phải đối mặt với các kỳ thi áp lực và triển vọng nghề nghiệp bất định.","audioKind":"ex2"}],"collocations":[{"en":"anxiety about","vi":"sự lo lắng về"},{"en":"reduce anxiety","vi":"giảm bớt sự lo lắng"},{"en":"severe anxiety","vi":"sự lo âu trầm trọng"}],"wordFamily":["anxious (adj.)","anxiously (adv.)"],"synonyms":["worry","unease"],"antonyms":["calm"],"tipVi":"anxiety about theo sau là điều gây lo lắng; tính từ là anxious.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_joyful', 'en-b2-44', 'joyful', '/ˈdʒɔɪfl/', 'B2', 'vui mừng; hân hoan; mang lại niềm vui', 'adj.', 'joy (n.), joyfully (adv.), joyfulness (n.), joyless (adj.)', 'Đồng nghĩa: delighted, happy, cheerful · Trái nghĩa: sad, joyless', 'Nhấn mạnh niềm vui mãnh liệt hơn "happy", cũng có thể dùng để miêu tả dịp lễ hoặc hoàn cảnh.', 'We heard joyful laughter coming from the kitchen.', NULL, 'Chúng tôi nghe thấy tiếng cười vui vẻ vọng ra từ nhà bếp.', '{"wordId":"joyful","ukIpa":"/ˈdʒɔɪfl/","usIpa":"/ˈdʒɔɪfl/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"Feeling, expressing, or causing great happiness.","vi":"vui mừng; hân hoan; mang lại niềm vui"}],"examples":[{"en":"We heard joyful laughter coming from the kitchen.","vi":"Chúng tôi nghe thấy tiếng cười vui vẻ vọng ra từ nhà bếp.","audioKind":"ex"},{"en":"Community festivals create joyful shared experiences that can strengthen social connections among residents of different backgrounds.","vi":"Các lễ hội cộng đồng tạo ra những trải nghiệm vui vẻ chung giúp củng cố sự gắn kết xã hội giữa những cư dân có xuất thân khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"a joyful occasion","vi":"một dịp vui"},{"en":"joyful laughter","vi":"tiếng cười vui vẻ"},{"en":"a joyful reunion","vi":"cuộc hội ngộ vui vẻ"}],"wordFamily":["joy (n.)","joyfully (adv.)","joyfulness (n.)","joyless (adj.)"],"synonyms":["delighted","happy","cheerful"],"antonyms":["sad","joyless"],"tipVi":"Nhấn mạnh niềm vui mãnh liệt hơn \"happy\", cũng có thể dùng để miêu tả dịp lễ hoặc hoàn cảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_adore', 'en-b2-44', 'adore', '/əˈdɔːr/', 'B2', 'yêu mến; rất thích', 'v.', 'adoration (n.), adoring (adj.), adorable (adj.)', 'Đồng nghĩa: love, cherish · Trái nghĩa: detest, loathe', 'Sắc thái mạnh hơn "like"; theo sau là danh từ hoặc danh động từ (V-ing), không dùng với động từ nguyên mẫu có "to".', 'My grandparents adore spending quiet afternoons in their garden.', NULL, 'Ông bà tôi rất thích dành những buổi chiều yên tĩnh trong khu vườn của họ.', '{"wordId":"adore","ukIpa":"/əˈdɔː/","usIpa":"/əˈdɔːr/","cefr":"B2","topic":"emotion","senses":[{"pos":"v.","en":"to love someone or like something very much","vi":"yêu mến; rất thích"}],"examples":[{"en":"My grandparents adore spending quiet afternoons in their garden.","vi":"Ông bà tôi rất thích dành những buổi chiều yên tĩnh trong khu vườn của họ.","audioKind":"ex"},{"en":"Although many visitors adore historic neighbourhoods, excessive tourism can disrupt the daily lives of residents.","vi":"Mặc dù nhiều du khách rất yêu thích các khu phố lịch sử, nhưng du lịch quá mức có thể làm xáo trộn cuộc sống hàng ngày của người dân.","audioKind":"ex2"}],"collocations":[{"en":"absolutely adore","vi":"cực kỳ yêu thích"},{"en":"adore doing something","vi":"rất thích làm gì đó"},{"en":"adore someone","vi":"yêu mến ai đó"}],"wordFamily":["adoration (n.)","adoring (adj.)","adorable (adj.)"],"synonyms":["love","cherish"],"antonyms":["detest","loathe"],"tipVi":"Sắc thái mạnh hơn \"like\"; theo sau là danh từ hoặc danh động từ (V-ing), không dùng với động từ nguyên mẫu có \"to\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_frustrate', 'en-b2-44', 'frustrate', '/ˈfrʌstreɪt/', 'B2', 'làm nản lòng; làm bực bội; làm thất bại; cản trở', 'v.', 'frustration (n.), frustrated (adj.), frustrating (adj.)', 'Đồng nghĩa: annoy, thwart', 'Dùng "frustrated" khi nói về cảm giác nản lòng của con người; dùng "frustrating" khi nói về sự việc gây ra cảm giác đó.', 'These constant delays frustrate everyone waiting for the bus.', NULL, 'Việc liên tục bị chậm trễ này khiến tất cả những người đang đợi xe buýt cảm thấy bực bội.', '{"wordId":"frustrate","ukIpa":"/frʌˈstreɪt/","usIpa":"/ˈfrʌstreɪt/","cefr":"B2","topic":"emotion","senses":[{"pos":"v.","en":"Make someone annoyed because they cannot achieve what they want.","vi":"làm nản lòng; làm bực bội"},{"pos":"v.","en":"Prevent a plan or effort from succeeding.","vi":"làm thất bại; cản trở"}],"examples":[{"en":"These constant delays frustrate everyone waiting for the bus.","vi":"Việc liên tục bị chậm trễ này khiến tất cả những người đang đợi xe buýt cảm thấy bực bội.","audioKind":"ex"},{"en":"Complicated application procedures can frustrate small business owners who need financial support to expand their operations.","vi":"Các thủ tục đăng ký phức tạp có thể làm nản lòng các chủ doanh nghiệp nhỏ đang cần hỗ trợ tài chính để mở rộng hoạt động.","audioKind":"ex2"}],"collocations":[{"en":"frustrate efforts","vi":"cản trở nỗ lực"},{"en":"frustrate a plan","vi":"làm thất bại kế hoạch"},{"en":"deeply frustrated","vi":"vô cùng nản lòng"}],"wordFamily":["frustration (n.)","frustrated (adj.)","frustrating (adj.)"],"synonyms":["annoy","thwart"],"antonyms":[],"tipVi":"Dùng \"frustrated\" khi nói về cảm giác nản lòng của con người; dùng \"frustrating\" khi nói về sự việc gây ra cảm giác đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spirit', 'en-b2-44', 'spirit', '/ˈspɪrɪt/', 'B2', 'tinh thần; ý chí; nhiệt huyết; linh hồn; rượu mạnh', 'n.', 'spiritual (adj.), spiritually (adv.), spirited (adj.)', NULL, 'Khi chỉ tâm trạng hoặc các loại rượu mạnh, từ này thường ở dạng số nhiều là spirits.', 'Even after losing, our team showed great spirit.', NULL, 'Ngay cả sau khi thua cuộc, đội của chúng tôi vẫn thể hiện tinh thần thi đấu tuyệt vời.', '{"wordId":"spirit","ukIpa":"/ˈspɪrɪt/","usIpa":"/ˈspɪrɪt/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"Inner strength, courage, or enthusiasm","vi":"tinh thần; ý chí; nhiệt huyết"},{"pos":"n.","en":"A person''s soul or a being without a physical body","vi":"linh hồn; tinh thần"},{"pos":"n.","en":"A strong alcoholic drink made by distillation","vi":"rượu mạnh"}],"examples":[{"en":"Even after losing, our team showed great spirit.","vi":"Ngay cả sau khi thua cuộc, đội của chúng tôi vẫn thể hiện tinh thần thi đấu tuyệt vời.","audioKind":"ex"},{"en":"Community projects can strengthen a spirit of cooperation and encourage residents to take pride in their neighbourhoods.","vi":"Các dự án cộng đồng có thể củng cố tinh thần hợp tác và khuyến khích cư dân tự hào về khuNeighborhood của mình.","audioKind":"ex2"}],"collocations":[{"en":"team spirit","vi":"tinh thần đồng đội"},{"en":"fighting spirit","vi":"tinh thần chiến đấu"},{"en":"in good spirits","vi":"tâm trạng vui vẻ, phấn chấn"},{"en":"a spirit of cooperation","vi":"tinh thần hợp tác"}],"wordFamily":["spiritual (adj.)","spiritually (adv.)","spirited (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ tâm trạng hoặc các loại rượu mạnh, từ này thường ở dạng số nhiều là spirits.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_terrify', 'en-b2-44', 'terrify', '/ˈterəfaɪ/', 'B2', 'làm khiếp sợ; làm hoảng sợ', 'v.', 'terrified (adj.), terrifying (adj.), terror (n.)', 'Đồng nghĩa: frighten, scare · Trái nghĩa: reassure', 'Động từ ngoại động từ; dùng terrified để miêu tả cảm giác con người và terrifying để chỉ sự vật gây sợ hãi.', 'Sudden thunder can terrify our dog during summer storms.', NULL, 'Tiếng sấm sét bất ngờ có thể làm chú chó nhà chúng tôi vô cùng sợ hãi trong các cơn giông mùa hè.', '{"wordId":"terrify","ukIpa":"/ˈterɪfaɪ/","usIpa":"/ˈterəfaɪ/","cefr":"B2","topic":"emotion","senses":[{"pos":"v.","en":"To make someone feel extremely frightened.","vi":"làm khiếp sợ; làm hoảng sợ"}],"examples":[{"en":"Sudden thunder can terrify our dog during summer storms.","vi":"Tiếng sấm sét bất ngờ có thể làm chú chó nhà chúng tôi vô cùng sợ hãi trong các cơn giông mùa hè.","audioKind":"ex"},{"en":"Extreme weather events can terrify young children, making clear explanations and reassurance from adults especially important.","vi":"Các hiện tượng thời tiết cực đoan có thể khiến trẻ nhỏ vô cùng khiếp sợ, vì vậy những lời giải thích rõ ràng và sự trấn an từ người lớn là vô cùng quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"terrify someone","vi":"làm ai đó khiếp sợ"},{"en":"be terrified of","vi":"rất sợ hãi"},{"en":"be terrified by","vi":"bị dọa sợ bởi"}],"wordFamily":["terrified (adj.)","terrifying (adj.)","terror (n.)"],"synonyms":["frighten","scare"],"antonyms":["reassure"],"tipVi":"Động từ ngoại động từ; dùng terrified để miêu tả cảm giác con người và terrifying để chỉ sự vật gây sợ hãi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_agreeable', 'en-b2-44', 'agreeable', '/əˈɡriːəbəl/', 'B2', 'dễ chịu; dễ mến; thú vị; sẵn lòng đồng ý; tán thành', 'adj.', 'agree (v.), agreement (n.), agreeably (adv.), disagreeable (adj.)', 'Đồng nghĩa: pleasant, willing · Trái nghĩa: disagreeable, unpleasant', 'be agreeable to sth diễn tả sự sẵn lòng chấp nhận điều gì đó, mang sắc thái trang trọng.', 'We spent an agreeable afternoon chatting in the garden.', NULL, 'Chúng tôi đã dành một buổi chiều dễ chịu trò chuyện trong khu vườn.', '{"wordId":"agreeable","ukIpa":"/əˈɡriːəbəl/","usIpa":"/əˈɡriːəbəl/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"pleasant and enjoyable","vi":"dễ chịu; dễ mến; thú vị"},{"pos":"adj.","en":"willing to accept or agree to something","vi":"sẵn lòng đồng ý; tán thành"}],"examples":[{"en":"We spent an agreeable afternoon chatting in the garden.","vi":"Chúng tôi đã dành một buổi chiều dễ chịu trò chuyện trong khu vườn.","audioKind":"ex"},{"en":"Employees may be more agreeable to organisational changes when managers explain the benefits and address their concerns.","vi":"Nhân viên có thể sẽ sẵn sàng đón nhận các thay đổi về cơ cấu tổ chức hơn khi các nhà quản lý giải thích lợi ích và giải đáp những băn khoăn của họ.","audioKind":"ex2"}],"collocations":[{"en":"agreeable weather","vi":"thời tiết dễ chịu"},{"en":"agreeable company","vi":"bạn đồng hành dễ chịu"},{"en":"agreeable to a proposal","vi":"đồng ý với một đề xuất"}],"wordFamily":["agree (v.)","agreement (n.)","agreeably (adv.)","disagreeable (adj.)"],"synonyms":["pleasant","willing"],"antonyms":["disagreeable","unpleasant"],"tipVi":"be agreeable to sth diễn tả sự sẵn lòng chấp nhận điều gì đó, mang sắc thái trang trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fury', 'en-b2-44', 'fury', '/ˈfjʊri/', 'B2', 'cơn giận dữ; sự cuồng nộ; sự mãnh liệt; sự dữ dội (thường nói về thời tiết)', 'n.', 'furious (adj.), furiously (adv.)', 'Đồng nghĩa: rage, anger · Trái nghĩa: calm', 'Từ này có sắc thái mạnh hơn "anger"; cụm từ "in a fury" diễn tả trạng thái "nổi giận đùng đùng".', 'He shook with fury when he discovered the damage.', NULL, 'Anh ấy run lên vì giận dữ khi phát hiện ra món đồ bị hỏng.', '{"wordId":"fury","ukIpa":"/ˈfjʊəri/","usIpa":"/ˈfjʊri/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"An extremely strong feeling of anger.","vi":"cơn giận dữ; sự cuồng nộ"},{"pos":"n.","en":"Extreme force or violence, especially in weather.","vi":"sự mãnh liệt; sự dữ dội (thường nói về thời tiết)"}],"examples":[{"en":"He shook with fury when he discovered the damage.","vi":"Anh ấy run lên vì giận dữ khi phát hiện ra món đồ bị hỏng.","audioKind":"ex"},{"en":"The sudden closure of the local hospital provoked fury among residents who depended on its services.","vi":"Việc đóng cửa bệnh viện địa phương đột ngột đã châm ngòi cho sự phẫn nộ dữ dội trong cộng đồng cư dân vốn phụ thuộc vào các dịch vụ y tế nơi đây.","audioKind":"ex2"}],"collocations":[{"en":"shake with fury","vi":"run lên vì giận dữ"},{"en":"provoke fury","vi":"châm ngòi sự phẫn nộ"},{"en":"the fury of the storm","vi":"sự dữ dội của cơn bão"}],"wordFamily":["furious (adj.)","furiously (adv.)"],"synonyms":["rage","anger"],"antonyms":["calm"],"tipVi":"Từ này có sắc thái mạnh hơn \"anger\"; cụm từ \"in a fury\" diễn tả trạng thái \"nổi giận đùng đùng\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_miracle', 'en-b2-44', 'miracle', '/ˈmɪrəkəl/', 'B2', 'sự kỳ diệu; phép màu', 'n.', 'miraculous (adj.), miraculously (adv.)', 'Đồng nghĩa: wonder', 'work miracles chỉ việc tạo ra điều kỳ diệu, cũng có thể dùng phóng đại để chỉ hiệu quả đáng kinh ngạc.', 'It was a miracle that the vase survived.', NULL, 'Thật là một phép màu khi chiếc bình vẫn còn nguyên vẹn.', '{"wordId":"miracle","ukIpa":"/ˈmɪrəkl/","usIpa":"/ˈmɪrəkəl/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"An extraordinary event that seems impossible or beyond natural explanation.","vi":"sự kỳ diệu; phép màu"}],"examples":[{"en":"It was a miracle that the vase survived.","vi":"Thật là một phép màu khi chiếc bình vẫn còn nguyên vẹn.","audioKind":"ex"},{"en":"Although new technology can appear to work miracles, lasting environmental progress also requires changes in public behaviour.","vi":"Mặc dù công nghệ mới có vẻ tạo ra những điều kỳ diệu, nhưng tiến trình bảo vệ môi trường lâu dài cũng đòi hỏi sự thay đổi trong hành vi của cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"work miracles","vi":"tạo nên điều kỳ diệu"},{"en":"a medical miracle","vi":"một kỳ tích y học"},{"en":"a miracle cure","vi":"phương1 pháp chữa trị thần kỳ"}],"wordFamily":["miraculous (adj.)","miraculously (adv.)"],"synonyms":["wonder"],"antonyms":[],"tipVi":"work miracles chỉ việc tạo ra điều kỳ diệu, cũng có thể dùng phóng đại để chỉ hiệu quả đáng kinh ngạc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_panic', 'en-b2-44', 'panic', '/ˈpænɪk/', 'B2', 'sự hoảng loạn; sự hoảng sợ; hoảng loạn; làm cho hoảng sợ', 'n.', 'panicked (adj.), panicky (adj.)', 'Đồng nghĩa: alarm, fright · Trái nghĩa: calm', 'Dạng quá khứ panicked và phân từ/tiếp diễn panicking đều phải thêm k sau chữ c.', 'I felt a moment of panic when my keys disappeared.', NULL, 'Tôi cảm thấy hoảng loạn trong giây lát khi chìa khóa của mình biến mất.', '{"wordId":"panic","ukIpa":"/ˈpænɪk/","usIpa":"/ˈpænɪk/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"sudden strong fear that makes clear thinking difficult","vi":"sự hoảng loạn; sự hoảng sợ"},{"pos":"v.","en":"to feel or cause sudden fear and lose calm","vi":"hoảng loạn; làm cho hoảng sợ"}],"examples":[{"en":"I felt a moment of panic when my keys disappeared.","vi":"Tôi cảm thấy hoảng loạn trong giây lát khi chìa khóa của mình biến mất.","audioKind":"ex"},{"en":"Clear communication during emergencies can reduce public panic and help people follow safety instructions more effectively.","vi":"Giao tiếp rõ ràng trong các trường hợp khẩn cấp có thể làm giảm sự hoảng loạn của công chúng và giúp mọi người tuân thủ các hướng dẫn an toàn hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"in a panic","vi":"trong cơn hoảng loạn"},{"en":"panic attack","vi":"cơn hoảng loạn kịch phát"},{"en":"cause panic","vi":"gây ra hoảng loạn"},{"en":"panic buying","vi":"mua sắm hoảng loạn"}],"wordFamily":["panicked (adj.)","panicky (adj.)"],"synonyms":["alarm","fright"],"antonyms":["calm"],"tipVi":"Dạng quá khứ panicked và phân từ/tiếp diễn panicking đều phải thêm k sau chữ c.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_44_1', 'en-b2-44', 'Cách dùng “spite” (n.) — ác ý; sự thù hằn', 'out of spite  ·  in spite of  ·  pure spite', 'Cụm từ in spite of theo sau bởi danh từ hoặc danh động từ, tuyệt đối không đi trực tiếp với một mệnh đề chứa chủ ngữ và động từ.', 'Họ từ (Word Family): spiteful (adj.), spitefully (adv.) | Đồng nghĩa: malice · Trái nghĩa: goodwill', '[{"hanzi":"He hid his sister''s favourite toy out of spite.","pinyin":"","meaning":"Cậu ta giấu món đồ chơi yêu thích của em gái đi chỉ vì ác ý."},{"hanzi":"In spite of limited funding, the community centre continues to provide valuable support for local families.","pinyin":"","meaning":"Bất chấp nguồn kinh phí hạn hẹp, trung tâm cộng đồng vẫn tiếp tục cung cấp sự hỗ trợ quý giá cho các gia đình địa phương."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_44_2', 'en-b2-44', 'Cách dùng “frustrate” (v.) — làm nản lòng; làm bực bội', 'frustrate efforts  ·  frustrate a plan  ·  deeply frustrated', 'Dùng "frustrated" khi nói về cảm giác nản lòng của con người; dùng "frustrating" khi nói về sự việc gây ra cảm giác đó.', 'Họ từ (Word Family): frustration (n.), frustrated (adj.), frustrating (adj.) | Đồng nghĩa: annoy, thwart', '[{"hanzi":"These constant delays frustrate everyone waiting for the bus.","pinyin":"","meaning":"Việc liên tục bị chậm trễ này khiến tất cả những người đang đợi xe buýt cảm thấy bực bội."},{"hanzi":"Complicated application procedures can frustrate small business owners who need financial support to expand their operations.","pinyin":"","meaning":"Các thủ tục đăng ký phức tạp có thể làm nản lòng các chủ doanh nghiệp nhỏ đang cần hỗ trợ tài chính để mở rộng hoạt động."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_44_3', 'en-b2-44', 'Cách dùng “adore” (v.) — yêu mến; rất thích', 'absolutely adore  ·  adore doing something  ·  adore someone', 'Sắc thái mạnh hơn "like"; theo sau là danh từ hoặc danh động từ (V-ing), không dùng với động từ nguyên mẫu có "to".', 'Họ từ (Word Family): adoration (n.), adoring (adj.), adorable (adj.) | Đồng nghĩa: love, cherish · Trái nghĩa: detest, loathe', '[{"hanzi":"My grandparents adore spending quiet afternoons in their garden.","pinyin":"","meaning":"Ông bà tôi rất thích dành những buổi chiều yên tĩnh trong khu vườn của họ."},{"hanzi":"Although many visitors adore historic neighbourhoods, excessive tourism can disrupt the daily lives of residents.","pinyin":"","meaning":"Mặc dù nhiều du khách rất yêu thích các khu phố lịch sử, nhưng du lịch quá mức có thể làm xáo trộn cuộc sống hàng ngày của người dân."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_44_4', 'en-b2-44', 'Cách dùng “terrify” (v.) — làm khiếp sợ; làm hoảng sợ', 'terrify someone  ·  be terrified of  ·  be terrified by', 'Động từ ngoại động từ; dùng terrified để miêu tả cảm giác con người và terrifying để chỉ sự vật gây sợ hãi.', 'Họ từ (Word Family): terrified (adj.), terrifying (adj.), terror (n.) | Đồng nghĩa: frighten, scare · Trái nghĩa: reassure', '[{"hanzi":"Sudden thunder can terrify our dog during summer storms.","pinyin":"","meaning":"Tiếng sấm sét bất ngờ có thể làm chú chó nhà chúng tôi vô cùng sợ hãi trong các cơn giông mùa hè."},{"hanzi":"Extreme weather events can terrify young children, making clear explanations and reassurance from adults especially important.","pinyin":"","meaning":"Các hiện tượng thời tiết cực đoan có thể khiến trẻ nhỏ vô cùng khiếp sợ, vì vậy những lời giải thích rõ ràng và sự trấn an từ người lớn là vô cùng quan trọng."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_44_1', 'en-b2-44', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_44_1_1', 'ten_b2_44_1', 'sincere', 'Her sincere apology helped us become friends again.', 'Her sincere apology helped us become friends again.', '/sɪnˈsɪr/', 'Lời xin lỗi chân thành của cô ấy đã giúp chúng tôi làm lành với nhau.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_44_1_2', 'ten_b2_44_1', 'overwhelm', 'I felt overwhelmed by everyone''s kindness after the move.', 'I felt overwhelmed by everyone''s kindness after the move.', '/ˌoʊvərˈwelm/', 'Sau khi chuyển nhà, tôi cảm thấy vô cùng xúc động trước sự tử tế của mọi người.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_44_1_3', 'ten_b2_44_1', 'despair', 'He felt deep despair when his final application was rejected.', 'He felt deep despair when his final application was rejected.', '/dɪˈsper/', 'Anh ấy cảm thấy tuyệt vọng tột cùng khi đơn xin việc cuối cùng bị từ chối.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_44_1_4', 'ten_b2_44_1', 'hilarious', 'Her hilarious story made everyone laugh throughout dinner.', 'Her hilarious story made everyone laugh throughout dinner.', '/hɪˈleriəs/', 'Câu chuyện cực kỳ hài hước của cô ấy khiến mọi người cười suốt bữa tối.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_44_1_5', 'ten_b2_44_1', 'exclaim', '“What a beautiful rainbow!” she exclaimed, pointing towards the hills.', '“What a beautiful rainbow!” she exclaimed, pointing towards the hills.', '/ɪkˈskleɪm/', '"Cầu vồng đẹp quá!" cô ấy thốt lên, vừa chỉ tay về phía những ngọn đồi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_44_1_6', 'ten_b2_44_1', 'spite', 'He hid his sister''s favourite toy out of spite.', 'He hid his sister''s favourite toy out of spite.', '/spaɪt/', 'Cậu ta giấu món đồ chơi yêu thích của em gái đi chỉ vì ác ý.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_44_1_7', 'ten_b2_44_1', 'emotion', 'Her voice shook with emotion when she saw her brother.', 'Her voice shook with emotion when she saw her brother.', '/ɪˈmoʊʃən/', 'Giọng cô ấy run lên vì xúc động khi nhìn thấy anh trai mình.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_44_1_8', 'ten_b2_44_1', 'grin', 'She grinned when her puppy brought back the ball.', 'She grinned when her puppy brought back the ball.', '/ɡrɪn/', 'Cô ấy cười toe toét khi chú cún mang quả bóng về.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_44_1_1', 'en-b2-44', 'ten_b2_44_1', 'listening', 'listening', 'Her sincere apology helped us become friends again.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Việc liên tục bị chậm trễ này khiến tất cả những người đang đợi xe buýt cảm thấy bực bội.","Lời xin lỗi chân thành của cô ấy đã giúp chúng tôi làm lành với nhau.","Cậu ta giấu món đồ chơi yêu thích của em gái đi chỉ vì ác ý.","Thật là một phép màu khi chiếc bình vẫn còn nguyên vẹn."]'::jsonb, 1, 'Her sincere apology helped us become friends again. → Lời xin lỗi chân thành của cô ấy đã giúp chúng tôi làm lành với nhau.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_44_1_2', 'en-b2-44', 'ten_b2_44_1', 'listening', 'listening', 'I felt overwhelmed by everyone''s kindness after the move.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Anh ấy cảm thấy tuyệt vọng tột cùng khi đơn xin việc cuối cùng bị từ chối.","Tôi cảm thấy hoảng loạn trong giây lát khi chìa khóa của mình biến mất.","Cậu ta giấu món đồ chơi yêu thích của em gái đi chỉ vì ác ý.","Sau khi chuyển nhà, tôi cảm thấy vô cùng xúc động trước sự tử tế của mọi người."]'::jsonb, 3, 'I felt overwhelmed by everyone''s kindness after the move. → Sau khi chuyển nhà, tôi cảm thấy vô cùng xúc động trước sự tử tế của mọi người.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_44_1_3', 'en-b2-44', 'ten_b2_44_1', 'listening', 'listening', 'He felt deep despair when his final application was rejected.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cậu ta giấu món đồ chơi yêu thích của em gái đi chỉ vì ác ý.","Ngay cả sau khi thua cuộc, đội của chúng tôi vẫn thể hiện tinh thần thi đấu tuyệt vời.","Tiếng sấm sét bất ngờ có thể làm chú chó nhà chúng tôi vô cùng sợ hãi trong các cơn giông mùa hè.","Anh ấy cảm thấy tuyệt vọng tột cùng khi đơn xin việc cuối cùng bị từ chối."]'::jsonb, 3, 'He felt deep despair when his final application was rejected. → Anh ấy cảm thấy tuyệt vọng tột cùng khi đơn xin việc cuối cùng bị từ chối.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_44_2', 'en-b2-44', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_44_2_1', 'ten_b2_44_2', 'sincere', 'Sincere efforts to consult local residents can strengthen public trust in major urban development projects.', 'Sincere efforts to consult local residents can strengthen public trust in major urban development projects.', '/sɪnˈsɪr/', 'Những nỗ lực chân thành nhằm tham vấn người dân địa phương có thể củng cố niềm tin của công chúng đối với các dự án phát triển đô thị quy mô lớn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_44_2_2', 'ten_b2_44_2', 'overwhelm', 'A sudden increase in visitors can overwhelm local infrastructure unless tourism growth is carefully managed.', 'A sudden increase in visitors can overwhelm local infrastructure unless tourism growth is carefully managed.', '/ˌoʊvərˈwelm/', 'Sự gia tăng đột biến của lượng du khách có thể làm quá tải cơ sở hạ tầng địa phương trừ khi sự phát triển du lịch được quản lý cẩn thận.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_44_2_3', 'ten_b2_44_2', 'despair', 'Long periods of unemployment can lead to despair, highlighting the importance of accessible career advice and emotional support.', 'Long periods of unemployment can lead to despair, highlighting the importance of accessible career advice and emotional support.', '/dɪˈsper/', 'Tình trạng thất nghiệp kéo dài có thể dẫn đến sự tuyệt vọng, làm nổi bật tầm quan trọng của việc tiếp cận các dịch vụ tư vấn nghề nghiệp và hỗ trợ tinh thần.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_44_2_4', 'ten_b2_44_2', 'hilarious', 'Although hilarious advertisements can attract attention, humour does not always help consumers remember the product being promoted.', 'Although hilarious advertisements can attract attention, humour does not always help consumers remember the product being promoted.', '/hɪˈleriəs/', 'Mặc dù những quảng cáo gây cười có thể thu hút sự chú ý, sự hài hước không phải lúc nào cũng giúp người tiêu dùng ghi nhớ sản phẩm được quảng cáo.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_44_2_5', 'ten_b2_44_2', 'exclaim', 'Visitors often exclaim in surprise when museum displays reveal the impressive engineering skills of ancient societies.', 'Visitors often exclaim in surprise when museum displays reveal the impressive engineering skills of ancient societies.', '/ɪkˈskleɪm/', 'Khách tham quan thường thốt lên ngạc nhiên khi các hiện vật bảo tàng cho thấy kỹ năng chế tạo ấn tượng của các xã hội cổ đại.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_44_2_6', 'ten_b2_44_2', 'spite', 'In spite of limited funding, the community centre continues to provide valuable support for local families.', 'In spite of limited funding, the community centre continues to provide valuable support for local families.', '/spaɪt/', 'Bất chấp nguồn kinh phí hạn hẹp, trung tâm cộng đồng vẫn tiếp tục cung cấp sự hỗ trợ quý giá cho các gia đình địa phương.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_44_2_1', 'en-b2-44', 'ten_b2_44_2', 'listening', 'listening', 'Sincere efforts to consult local residents can strengthen public trust in major urban development projects.', NULL, 'Trong câu vừa nghe, từ “sincere” mang nghĩa nào sau đây?', '["một thìa đầy; một lượng bằng một muỗng","rút lui; thoái lui","chân thành; thành khẩn; thật lòng","xấu xa; độc ác"]'::jsonb, 2, '“sincere” (/sɪnˈsɪr/): chân thành; thành khẩn; thật lòng. Câu đầy đủ: Sincere efforts to consult local residents can strengthen public trust in major urban development projects.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_44_2_2', 'en-b2-44', 'ten_b2_44_2', 'listening', 'listening', 'A sudden increase in visitors can overwhelm local infrastructure unless tourism growth is carefully managed.', NULL, 'Trong câu vừa nghe, từ “overwhelm” mang nghĩa nào sau đây?', '["sương mù mỏng; làn sương","làm cho ngộp thở; làm cho không biết xoay sở thế nào","không được hoàn tiền; không thể trả lại tiền","không hiệu quả; không có tác dụng"]'::jsonb, 1, '“overwhelm” (/ˌoʊvərˈwelm/): làm cho ngộp thở; làm cho không biết xoay sở thế nào. Câu đầy đủ: A sudden increase in visitors can overwhelm local infrastructure unless tourism growth is carefully managed.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
