INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_44_2', 'en-b2-44', NULL, 'comprehensive_test', 'listening', 'I felt overwhelmed by everyone''s kindness after the move.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sau khi chuyển nhà, tôi cảm thấy vô cùng xúc động trước sự tử tế của mọi người.","Ông bà tôi rất thích dành những buổi chiều yên tĩnh trong khu vườn của họ.","Thật là một phép màu khi chiếc bình vẫn còn nguyên vẹn.","Anh ấy run lên vì giận dữ khi phát hiện ra món đồ bị hỏng."]'::jsonb, 0, 'I felt overwhelmed by everyone''s kindness after the move. → Sau khi chuyển nhà, tôi cảm thấy vô cùng xúc động trước sự tử tế của mọi người.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_44_3', 'en-b2-44', NULL, 'comprehensive_test', 'listening', 'despair', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tiếp tục; bắt đầu lại","sự kinh ngạc, sự ngạc nhiên tột độ","sự tuyệt vọng","sự thuyết phục; sự khuyên bảo"]'::jsonb, 2, 'despair (/dɪˈsper/) → sự tuyệt vọng; mất hết hy vọng; tuyệt vọng', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_44_4', 'en-b2-44', NULL, 'comprehensive_test', 'listening', 'Her hilarious story made everyone laugh throughout dinner.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Câu chuyện cực kỳ hài hước của cô ấy khiến mọi người cười suốt bữa tối.","Sau khi chuyển nhà, tôi cảm thấy vô cùng xúc động trước sự tử tế của mọi người.","Chúng tôi nghe thấy tiếng cười vui vẻ vọng ra từ nhà bếp.","Sự lo lắng của cô ấy tan biến khi nghe được tin vui."]'::jsonb, 0, 'Her hilarious story made everyone laugh throughout dinner. → Câu chuyện cực kỳ hài hước của cô ấy khiến mọi người cười suốt bữa tối.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_44_5', 'en-b2-44', NULL, 'comprehensive_test', 'listening', 'exclaim', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cách thức; phương thức","kêu lên; thốt lên","bất tỉnh; mất tri giác","rêu"]'::jsonb, 1, 'exclaim (/ɪkˈskleɪm/) → kêu lên; thốt lên', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_44_6', 'en-b2-44', NULL, 'comprehensive_test', 'listening', 'He hid his sister''s favourite toy out of spite.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Anh ấy cảm thấy tuyệt vọng tột cùng khi đơn xin việc cuối cùng bị từ chối.","Tôi đã rất lo lắng khi bạn lỡ chuyến xe buýt cuối cùng.","Cậu ta giấu món đồ chơi yêu thích của em gái đi chỉ vì ác ý.","Thật là một phép màu khi chiếc bình vẫn còn nguyên vẹn."]'::jsonb, 2, 'He hid his sister''s favourite toy out of spite. → Cậu ta giấu món đồ chơi yêu thích của em gái đi chỉ vì ác ý.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_44_7', 'en-b2-44', NULL, 'comprehensive_test', 'listening', 'emotion', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cảm xúc; tình cảm","dễ lây; có tính truyền nhiễm; dễ lây lan; có sức lan tỏa","có hình tam giác","chờ đợi; ngóng chờ"]'::jsonb, 0, 'emotion (/ɪˈmoʊʃən/) → cảm xúc; tình cảm', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_44_8', 'en-b2-44', NULL, 'comprehensive_test', 'listening', 'She grinned when her puppy brought back the ball.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy cười toe toét khi chú cún mang quả bóng về.","Việc liên tục bị chậm trễ này khiến tất cả những người đang đợi xe buýt cảm thấy bực bội.","Chúng tôi nghe thấy tiếng cười vui vẻ vọng ra từ nhà bếp.","Sau khi chuyển nhà, tôi cảm thấy vô cùng xúc động trước sự tử tế của mọi người."]'::jsonb, 0, 'She grinned when her puppy brought back the ball. → Cô ấy cười toe toét khi chú cún mang quả bóng về.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_44_9', 'en-b2-44', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to say something suddenly and loudly because of strong emotion”?', '["exclaim","adore","miracle","terrify"]'::jsonb, 0, 'exclaim (/ɪkˈskleɪm/) → kêu lên; thốt lên', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
