INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_44_18', 'en-b2-44', NULL, 'comprehensive_test', 'reading', NULL, 'Sincere efforts to consult local residents can strengthen public trust in major urban development projects.', 'Dựa vào câu trên, từ “sincere” có nghĩa phù hợp nhất là gì?', '["hồi tưởng; thiền định","bị phóng đại; nói quá; cường điệu","hấp dẫn; lôi cuốn","chân thành; thành khẩn; thật lòng"]'::jsonb, 3, 'sincere: chân thành; thành khẩn; thật lòng. Dịch cả câu: Những nỗ lực chân thành nhằm tham vấn người dân địa phương có thể củng cố niềm tin của công chúng đối với các dự án phát triển đô thị quy mô lớn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_44_19', 'en-b2-44', NULL, 'comprehensive_test', 'reading', NULL, 'A sudden increase in visitors can overwhelm local infrastructure unless tourism growth is carefully managed.', 'Dựa vào câu trên, từ “overwhelm” có nghĩa phù hợp nhất là gì?', '["tự do; không bị ràng buộc","lát đường; lát nền","vô cùng hài hước; cực kỳ buồn cười","làm cho ngộp thở; làm cho không biết xoay sở thế nào"]'::jsonb, 3, 'overwhelm: làm cho ngộp thở; làm cho không biết xoay sở thế nào; làm cho quá tải; làm cho không kham nổi; đánh bại hoàn toàn; áp đảo. Dịch cả câu: Sự gia tăng đột biến của lượng du khách có thể làm quá tải cơ sở hạ tầng địa phương trừ khi sự phát triển du lịch được quản lý cẩn thận.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_44_20', 'en-b2-44', NULL, 'comprehensive_test', 'reading', NULL, 'Long periods of unemployment can lead to despair, highlighting the importance of accessible career advice and emotional support.', 'Dựa vào câu trên, từ “despair” có nghĩa phù hợp nhất là gì?', '["tương ứng; riêng của mỗi người/vật","gạch ốp lát; gạch men; ngói","ong bắp cày; ong vò vẽ","sự tuyệt vọng"]'::jsonb, 3, 'despair: sự tuyệt vọng; mất hết hy vọng; tuyệt vọng. Dịch cả câu: Tình trạng thất nghiệp kéo dài có thể dẫn đến sự tuyệt vọng, làm nổi bật tầm quan trọng của việc tiếp cận các dịch vụ tư vấn nghề nghiệp và hỗ trợ tinh thần.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_44_21', 'en-b2-44', NULL, 'comprehensive_test', 'reading', NULL, 'Although hilarious advertisements can attract attention, humour does not always help consumers remember the product being promoted.', 'Dựa vào câu trên, từ “hilarious” có nghĩa phù hợp nhất là gì?', '["dệt; đan","vô cùng hài hước; cực kỳ buồn cười","đánh giá; định giá","lên bờ; vào bờ"]'::jsonb, 1, 'hilarious: vô cùng hài hước; cực kỳ buồn cười. Dịch cả câu: Mặc dù những quảng cáo gây cười có thể thu hút sự chú ý, sự hài hước không phải lúc nào cũng giúp người tiêu dùng ghi nhớ sản phẩm được quảng cáo.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_44_22', 'en-b2-44', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cơn giận dữ; sự cuồng nộ”', '["behalf","crawl","exotic","fury"]'::jsonb, 3, 'cơn giận dữ; sự cuồng nộ → fury (/ˈfjʊri/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
