INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_44_24', 'en-b2-44', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự hoảng loạn; sự hoảng sợ”', '["panic","diversity","dread","bold"]'::jsonb, 0, 'sự hoảng loạn; sự hoảng sợ → panic (/ˈpænɪk/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-45', 'en', 'Bài 45: Cảm xúc & Tính cách (5) - CEFR B2', 'CEFR B2', 'B2 · Cảm xúc', '24 từ vựng Tiếng Anh CEFR B2 chủ đề cảm xúc & tính cách kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4045, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_beloved', 'en-b2-45', 'beloved', '/bɪˈlʌvɪd/', 'B2', 'được yêu quý; yêu dấu; người yêu dấu; người thương', 'adj.', 'love (v.), loving (adj.), lovable (adj.)', 'Đồng nghĩa: cherished, treasured, dear · Trái nghĩa: hated', 'Thường đóng vai trò là tính từ; khi dùng như danh từ thì chỉ người tình, mang văn phong trang trọng hoặc văn chương.', 'He carefully repaired his daughter''s beloved wooden toy.', NULL, 'Anh ấy cẩn thận sửa chữa món đồ chơi bằng gỗ yêu quý của con gái mình.', '{"wordId":"beloved","ukIpa":"/bɪˈlʌvɪd/","usIpa":"/bɪˈlʌvɪd/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"deeply loved by someone or many people","vi":"được yêu quý; yêu dấu"},{"pos":"n.","en":"a person whom someone loves deeply","vi":"người yêu dấu; người thương"}],"examples":[{"en":"He carefully repaired his daughter''s beloved wooden toy.","vi":"Anh ấy cẩn thận sửa chữa món đồ chơi bằng gỗ yêu quý của con gái mình.","audioKind":"ex"},{"en":"Public libraries remain beloved community spaces because they offer opportunities for learning and social connection.","vi":"Các thư viện công cộng vẫn là không gian cộng đồng rất được yêu thích bởi vì chúng mang lại cơ hội học tập và kết nối xã hội.","audioKind":"ex2"}],"collocations":[{"en":"a beloved friend","vi":"một người bạn tri kỷ"},{"en":"a beloved pet","vi":"thú cưng yêu quý"},{"en":"a beloved institution","vi":"một cơ quan được công chúng yêu mến"}],"wordFamily":["love (v.)","loving (adj.)","lovable (adj.)"],"synonyms":["cherished","treasured","dear"],"antonyms":["hated"],"tipVi":"Thường đóng vai trò là tính từ; khi dùng như danh từ thì chỉ người tình, mang văn phong trang trọng hoặc văn chương.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_embarrassment', 'en-b2-45', 'embarrassment', '/ɪmˈbærəsmənt/', 'B2', 'sự bối rối; sự ngượng ngùng; người gây bối rối; điều gây ngượng ngùng', 'n.', 'embarrass (v.), embarrassed (adj.), embarrassing (adj.), embarrassingly (adv.)', 'Đồng nghĩa: awkwardness, discomfort', 'Nghĩa cảm xúc là danh từ không đếm được; khi chỉ người hoặc việc gây bối rối thì có thể đếm được.', 'I blushed with embarrassment when I forgot my neighbour''s name.', NULL, 'Tôi đỏ mặt vì ngượng ngùng khi quên mất tên của hàng xóm.', '{"wordId":"embarrassment","ukIpa":"/ɪmˈbærəsmənt/","usIpa":"/ɪmˈbærəsmənt/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"an uncomfortable feeling caused by awkwardness or fear of others'' judgment","vi":"sự bối rối; sự ngượng ngùng"},{"pos":"n.","en":"a person or thing that causes shame or awkwardness","vi":"người gây bối rối; điều gây ngượng ngùng"}],"examples":[{"en":"I blushed with embarrassment when I forgot my neighbour''s name.","vi":"Tôi đỏ mặt vì ngượng ngùng khi quên mất tên của hàng xóm.","audioKind":"ex"},{"en":"Fear of embarrassment may prevent language learners from practising their speaking skills in front of others.","vi":"Nỗi sợ bị bối rối có thể khiến người học ngoại ngữ ngại thực hành kỹ năng nói trước mặt người khác.","audioKind":"ex2"}],"collocations":[{"en":"to my embarrassment","vi":"làm tôi ngượng ngùng"},{"en":"blush with embarrassment","vi":"đỏ mặt vì ngượng"},{"en":"avoid embarrassment","vi":"tránh sự bối rối"},{"en":"a source of embarrassment","vi":"nguồn gốc gây ngượng ngùng"}],"wordFamily":["embarrass (v.)","embarrassed (adj.)","embarrassing (adj.)","embarrassingly (adv.)"],"synonyms":["awkwardness","discomfort"],"antonyms":[],"tipVi":"Nghĩa cảm xúc là danh từ không đếm được; khi chỉ người hoặc việc gây bối rối thì có thể đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_helpless', 'en-b2-45', 'helpless', '/ˈhelpləs/', 'B2', 'bất lực; không thể tự bảo vệ hoặc xoay sở', 'adj.', 'help (v.), helplessly (adv.), helplessness (n.), helpful (adj.)', 'Đồng nghĩa: powerless · Trái nghĩa: self-reliant', 'helpless có nghĩa là bất lực, vô phương; cần phân biệt với unhelpful có nghĩa là không hữu ích hoặc không chịu giúp đỡ.', 'I felt helpless when the lift suddenly stopped moving.', NULL, 'Tôi cảm thấy bất lực khi thang máy đột ngột dừng chạy.', '{"wordId":"helpless","ukIpa":"/ˈhelpləs/","usIpa":"/ˈhelpləs/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"Unable to protect yourself or change a difficult situation","vi":"bất lực; không thể tự bảo vệ hoặc xoay sở"}],"examples":[{"en":"I felt helpless when the lift suddenly stopped moving.","vi":"Tôi cảm thấy bất lực khi thang máy đột ngột dừng chạy.","audioKind":"ex"},{"en":"Without accessible support services, elderly people may feel helpless when trying to manage increasingly complex digital systems.","vi":"Nếu thiếu đi các dịch vụ hỗ trợ dễ tiếp cận, người cao tuổi có thể cảm thấy bất lực khi cố gắng sử dụng các hệ thống kỹ thuật số ngày càng phức tạp.","audioKind":"ex2"}],"collocations":[{"en":"feel helpless","vi":"cảm thấy bất lực"},{"en":"a helpless victim","vi":"nạn nhân vô phương tự vệ"},{"en":"helpless against","vi":"bất lực trước"}],"wordFamily":["help (v.)","helplessly (adv.)","helplessness (n.)","helpful (adj.)"],"synonyms":["powerless"],"antonyms":["self-reliant"],"tipVi":"helpless có nghĩa là bất lực, vô phương; cần phân biệt với unhelpful có nghĩa là không hữu ích hoặc không chịu giúp đỡ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sorrow', 'en-b2-45', 'sorrow', '/ˈsɑːroʊ/', 'B2', 'nỗi buồn; sự đau buồn', 'n.', 'sorrowful (adj.), sorrowfully (adv.)', 'Đồng nghĩa: sadness, grief · Trái nghĩa: joy', 'Chỉ cảm xúc buồn sâu sắc thường là danh từ không đếm được; nỗi buồn cụ thể có thể đếm được.', 'She felt deep sorrow when her closest friend moved away.', NULL, 'Cô ấy cảm thấy vô cùng đau buồn khi người bạn thân nhất của mình chuyển đi nơi khác.', '{"wordId":"sorrow","ukIpa":"/ˈsɒrəʊ/","usIpa":"/ˈsɑːroʊ/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"deep sadness caused by loss or disappointment","vi":"nỗi buồn; sự đau buồn"}],"examples":[{"en":"She felt deep sorrow when her closest friend moved away.","vi":"Cô ấy cảm thấy vô cùng đau buồn khi người bạn thân nhất của mình chuyển đi nơi khác.","audioKind":"ex"},{"en":"Community support can help people cope with sorrow after the loss of a loved one.","vi":"Sự hỗ trợ từ cộng đồng có thể giúp mọi người đối phó với nỗi đau buồn sau khi mất đi người thân yêu.","audioKind":"ex2"}],"collocations":[{"en":"deep sorrow","vi":"nỗi buồn sâu sắc"},{"en":"express sorrow","vi":"bày tỏ sự đau buồn"},{"en":"in sorrow","vi":"trong niềm đau buồn"}],"wordFamily":["sorrowful (adj.)","sorrowfully (adv.)"],"synonyms":["sadness","grief"],"antonyms":["joy"],"tipVi":"Chỉ cảm xúc buồn sâu sắc thường là danh từ không đếm được; nỗi buồn cụ thể có thể đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_appreciation', 'en-b2-45', 'appreciation', '/əˌpriːʃiˈeɪʃən/', 'B2', 'lòng biết ơn; sự cảm kích; sự thấu hiểu; sự đánh giá cao; sự tăng giá; sự lên giá', 'n.', 'appreciate (v.), appreciative (adj.), appreciatively (adv.)', 'Đồng nghĩa: gratitude, recognition · Trái nghĩa: depreciation', 'Thường không đếm được; an appreciation of có thể chỉ sự am hiểu về một việc gì đó.', 'We baked our neighbour a cake to show our appreciation.', NULL, 'Chúng tôi nướng bánh tặng hàng xóm để bày tỏ lòng biết ơn.', '{"wordId":"appreciation","ukIpa":"/əˌpriːʃiˈeɪʃən/","usIpa":"/əˌpriːʃiˈeɪʃən/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"A feeling of gratitude for someone''s help or kindness.","vi":"lòng biết ơn; sự cảm kích"},{"pos":"n.","en":"Recognition and understanding of something''s value, quality, or importance.","vi":"sự thấu hiểu; sự đánh giá cao"},{"pos":"n.","en":"An increase in the financial value of something.","vi":"sự tăng giá; sự lên giá"}],"examples":[{"en":"We baked our neighbour a cake to show our appreciation.","vi":"Chúng tôi nướng bánh tặng hàng xóm để bày tỏ lòng biết ơn.","audioKind":"ex"},{"en":"Arts education can develop students'' appreciation of cultural traditions that differ from their own.","vi":"Giáo dục nghệ thuật có thể bồi dưỡng cho học sinh sự trân trọng đối với các truyền thống văn hóa khác biệt với văn hóa của chính họ.","audioKind":"ex2"}],"collocations":[{"en":"show appreciation","vi":"bày tỏ sự biết ơn"},{"en":"in appreciation of","vi":"để bày tỏ lòng biết ơn đối với"},{"en":"an appreciation of art","vi":"sự am hiểu nghệ thuật"},{"en":"currency appreciation","vi":"đồng tiền tăng giá"}],"wordFamily":["appreciate (v.)","appreciative (adj.)","appreciatively (adv.)"],"synonyms":["gratitude","recognition"],"antonyms":["depreciation"],"tipVi":"Thường không đếm được; an appreciation of có thể chỉ sự am hiểu về một việc gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_giggle', 'en-b2-45', 'giggle', '/ˈɡɪɡəl/', 'B2', 'cười khúc khích; cười tủm tỉm; tiếng cười khúc khích; tiếng cười tủm tỉm', 'v.', 'giggly (adj.)', 'Đồng nghĩa: laugh', 'Nhấn mạnh tiếng cười khẽ, thường do vui thích hoặc căng thẳng; cười vì điều gì dùng at.', 'The children giggled when the puppy chased its tail.', NULL, 'Lũ trẻ khúc khích cười khi chú chó con đuổi theo cái đuôi của chính mình.', '{"wordId":"giggle","ukIpa":"/ˈɡɪɡəl/","usIpa":"/ˈɡɪɡəl/","cefr":"B2","topic":"emotion","senses":[{"pos":"v.","en":"laugh in a light, often nervous or silly way","vi":"cười khúc khích; cười tủm tỉm"},{"pos":"n.","en":"a light laugh caused by amusement or nervousness","vi":"tiếng cười khúc khích; tiếng cười tủm tỉm"}],"examples":[{"en":"The children giggled when the puppy chased its tail.","vi":"Lũ trẻ khúc khích cười khi chú chó con đuổi theo cái đuôi của chính mình.","audioKind":"ex"},{"en":"Young learners may giggle during unfamiliar activities, but this reaction does not necessarily indicate a lack of interest.","vi":"Người học nhỏ tuổi có thể khúc khích cười trong các hoạt động lạ lẫm, nhưng phản ứng này không nhất thiết cho thấy sự thiếu quan tâm.","audioKind":"ex2"}],"collocations":[{"en":"giggle at a joke","vi":"cười khúc khích trước một câu đùa"},{"en":"nervous giggle","vi":"tiếng cười khúc khích do căng thẳng"},{"en":"suppress a giggle","vi":"nén tiếng cười"}],"wordFamily":["giggly (adj.)"],"synonyms":["laugh"],"antonyms":[],"tipVi":"Nhấn mạnh tiếng cười khẽ, thường do vui thích hoặc căng thẳng; cười vì điều gì dùng at.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_uninterested', 'en-b2-45', 'uninterested', '/ʌnˈɪntrəstɪd/', 'B2', 'không có hứng thú, thờ ơ, không quan tâm', 'adj.', 'interest (n.), interested (adj.), interesting (adj.)', 'Đồng nghĩa: indifferent, apathetic · Trái nghĩa: interested, enthusiastic', 'Thường đi với giới từ "in"; tránh nhầm lẫn với từ "disinterested" có nghĩa là "công tâm, vô tư".', 'Leo seemed uninterested in the game and went outside.', NULL, 'Leo có vẻ không có hứng thú với trò chơi và đã đi ra ngoài.', '{"wordId":"uninterested","ukIpa":"/ʌnˈɪntrəstɪd/","usIpa":"/ʌnˈɪntrəstɪd/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"not wanting to learn about or take part in something","vi":"không có hứng thú, thờ ơ, không quan tâm"}],"examples":[{"en":"Leo seemed uninterested in the game and went outside.","vi":"Leo có vẻ không có hứng thú với trò chơi và đã đi ra ngoài.","audioKind":"ex"},{"en":"Students may appear uninterested in science when lessons offer few opportunities for practical experiments.","vi":"Học sinh có thể tỏ ra không mặn mà với môn khoa học khi các tiết học ít có cơ hội làm thí nghiệm thực tế.","audioKind":"ex2"}],"collocations":[{"en":"uninterested in politics","vi":"không quan tâm đến chính trị"},{"en":"seem uninterested","vi":"tỏ ra không có hứng thú"},{"en":"remain uninterested","vi":"vẫn giữ thái độ hờ hững"}],"wordFamily":["interest (n.)","interested (adj.)","interesting (adj.)"],"synonyms":["indifferent","apathetic"],"antonyms":["interested","enthusiastic"],"tipVi":"Thường đi với giới từ \"in\"; tránh nhầm lẫn với từ \"disinterested\" có nghĩa là \"công tâm, vô tư\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_furious', 'en-b2-45', 'furious', '/ˈfjʊriəs/', 'B2', 'giận dữ; nổi giận đùng đùng; mãnh liệt; dữ dội; nhanh chóng', 'adj.', 'fury (n.), furiously (adv.)', 'Đồng nghĩa: enraged, angry · Trái nghĩa: calm', 'Tức giận với ai dùng with, tức giận về việc gì dùng about.', 'Lena was furious when someone scratched her new bicycle.', NULL, 'Lena vô cùng tức giận khi ai đó làm xước chiếc xe đạp mới của cô ấy.', '{"wordId":"furious","ukIpa":"/ˈfjʊəriəs/","usIpa":"/ˈfjʊriəs/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"Feeling or showing extreme anger.","vi":"giận dữ; nổi giận đùng đùng"},{"pos":"adj.","en":"Done with great force, energy, or speed.","vi":"mãnh liệt; dữ dội; nhanh chóng"}],"examples":[{"en":"Lena was furious when someone scratched her new bicycle.","vi":"Lena vô cùng tức giận khi ai đó làm xước chiếc xe đạp mới của cô ấy.","audioKind":"ex"},{"en":"Residents were furious about the sudden closure of a public park without any community consultation.","vi":"Cư dân vô cùng phẫn nộ trước việc một công viên công cộng bị đóng cửa đột ngột mà không có bất kỳ cuộc tham vấn nào với cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"furious with someone","vi":"nổi giận với ai đó"},{"en":"furious about something","vi":"vô cùng tức giận về điều gì"},{"en":"a furious debate","vi":"một cuộc tranh luận gay gắt"}],"wordFamily":["fury (n.)","furiously (adv.)"],"synonyms":["enraged","angry"],"antonyms":["calm"],"tipVi":"Tức giận với ai dùng with, tức giận về việc gì dùng about.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_intense', 'en-b2-45', 'intense', '/ɪnˈtens/', 'B2', 'dữ dội; gay gắt; cực kỳ; mãnh liệt; nồng nhiệt; tập trung cao độ', 'adj.', 'intensely (adv.), intensity (n.), intensify (v.)', 'Đồng nghĩa: extreme, powerful · Trái nghĩa: mild', 'intense nhấn mạnh mức độ mạnh mẽ; trong khi intensive nhấn mạnh sự tập trung dồn dập, cường độ cao.', 'The intense heat made us search for shade.', NULL, 'Cái nắng gay gắt khiến chúng tôi phải tìm bóng râm để trốn.', '{"wordId":"intense","ukIpa":"/ɪnˈtens/","usIpa":"/ɪnˈtens/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"very strong or extreme in degree","vi":"dữ dội; gay gắt; cực kỳ"},{"pos":"adj.","en":"showing very strong feelings or serious concentration","vi":"mãnh liệt; nồng nhiệt; tập trung cao độ"}],"examples":[{"en":"The intense heat made us search for shade.","vi":"Cái nắng gay gắt khiến chúng tôi phải tìm bóng râm để trốn.","audioKind":"ex"},{"en":"Intense competition for university places can place considerable psychological pressure on students during their final school year.","vi":"Sự cạnh tranh khốc liệt để giành suất vào đại học có thể tạo ra áp lực tâm lý đáng kể cho học sinh trong năm học cuối cấp.","audioKind":"ex2"}],"collocations":[{"en":"intense heat","vi":"cái nóng gay gắt"},{"en":"intense pressure","vi":"áp lực dữ dội"},{"en":"intense competition","vi":"cạnh tranh khốc liệt"},{"en":"intense concentration","vi":"sự tập trung cao độ"}],"wordFamily":["intensely (adv.)","intensity (n.)","intensify (v.)"],"synonyms":["extreme","powerful"],"antonyms":["mild"],"tipVi":"intense nhấn mạnh mức độ mạnh mẽ; trong khi intensive nhấn mạnh sự tập trung dồn dập, cường độ cao.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unwilling', 'en-b2-45', 'unwilling', '/ʌnˈwɪlɪŋ/', 'B2', 'không muốn; không sẵn lòng; miễn cưỡng', 'adj.', 'willing (adj.), unwillingly (adv.), unwillingness (n.)', 'Đồng nghĩa: reluctant · Trái nghĩa: willing, eager', 'Thường dùng cấu trúc be unwilling to do; không chịu làm không có nghĩa là unable không thể làm.', 'He was unwilling to lend his new bicycle.', NULL, 'Anh ấy không chịu cho mượn chiếc xe đạp mới của mình.', '{"wordId":"unwilling","ukIpa":"/ʌnˈwɪlɪŋ/","usIpa":"/ʌnˈwɪlɪŋ/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"not wanting or agreeing to do something","vi":"không muốn; không sẵn lòng; miễn cưỡng"}],"examples":[{"en":"He was unwilling to lend his new bicycle.","vi":"Anh ấy không chịu cho mượn chiếc xe đạp mới của mình.","audioKind":"ex"},{"en":"Some commuters are unwilling to cycle to work because busy roads lack safe lanes and secure bicycle parking.","vi":"Một số người đi làm không muốn đạp xe đi làm vì các con đường đông đúc thiếu làn đường an toàn và bãi đỗ xe đạp an toàn.","audioKind":"ex2"}],"collocations":[{"en":"unwilling to accept","vi":"không muốn chấp nhận"},{"en":"unwilling to cooperate","vi":"không chịu hợp tác"},{"en":"an unwilling participant","vi":"một người tham gia miễn cưỡng"}],"wordFamily":["willing (adj.)","unwillingly (adv.)","unwillingness (n.)"],"synonyms":["reluctant"],"antonyms":["willing","eager"],"tipVi":"Thường dùng cấu trúc be unwilling to do; không chịu làm không có nghĩa là unable không thể làm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thrill', 'en-b2-45', 'thrill', '/θrɪl/', 'B2', 'cảm giác hồi hộp, phấn khích tột độ; làm cho phấn khích; làm cho hào hứng', 'n.', 'thrilled (adj.), thrilling (adj.), thriller (n.)', 'Đồng nghĩa: excitement, exhilaration', 'Tính từ thrilled dùng để chỉ con người cảm thấy phấn khích; thrilling dùng để chỉ sự vật gây ra cảm giác phấn khích.', 'I felt a real thrill when the kite finally flew.', NULL, 'Tôi cảm thấy thực sự phấn khích khi con diều cuối cùng cũng bay lên được.', '{"wordId":"thrill","ukIpa":"/θrɪl/","usIpa":"/θrɪl/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"a sudden strong feeling of excitement and pleasure","vi":"cảm giác hồi hộp, phấn khích tột độ"},{"pos":"v.","en":"to make someone feel very excited and pleased","vi":"làm cho phấn khích; làm cho hào hứng"}],"examples":[{"en":"I felt a real thrill when the kite finally flew.","vi":"Tôi cảm thấy thực sự phấn khích khi con diều cuối cùng cũng bay lên được.","audioKind":"ex"},{"en":"The thrill of discovery can motivate students to explore scientific questions beyond the classroom.","vi":"Cảm giác hồi hộp khi khám phá ra điều mới lạ có thể thúc đẩy học sinh tìm hiểu các vấn đề khoa học ngoài lớp học.","audioKind":"ex2"}],"collocations":[{"en":"the thrill of discovery","vi":"niềm vui thích khám phá"},{"en":"a thrill of excitement","vi":"cảm giác hồi hộp phấn khích"},{"en":"thrill an audience","vi":"làm khán giả phấn khích"}],"wordFamily":["thrilled (adj.)","thrilling (adj.)","thriller (n.)"],"synonyms":["excitement","exhilaration"],"antonyms":[],"tipVi":"Tính từ thrilled dùng để chỉ con người cảm thấy phấn khích; thrilling dùng để chỉ sự vật gây ra cảm giác phấn khích.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_blush', 'en-b2-45', 'blush', '/blʌʃ/', 'B2', 'đỏ mặt vì xấu hổ hoặc ngại ngùng; sự đỏ mặt; nét ửng hồng trên mặt', 'v.', 'blushing (adj.)', 'Đồng nghĩa: flush', 'Động từ thường ở dạng nội động từ; cấu trúc làm ai đó đỏ mặt dùng make someone blush.', 'He began to blush when everyone praised his singing.', NULL, 'Anh ấy bắt đầu đỏ mặt khi mọi người khen ngợi tiếng hát của mình.', '{"wordId":"blush","ukIpa":"/blʌʃ/","usIpa":"/blʌʃ/","cefr":"B2","topic":"emotion","senses":[{"pos":"v.","en":"To become red in the face from embarrassment or shyness.","vi":"đỏ mặt vì xấu hổ hoặc ngại ngùng"},{"pos":"n.","en":"Redness in the face caused by embarrassment or shyness.","vi":"sự đỏ mặt; nét ửng hồng trên mặt"}],"examples":[{"en":"He began to blush when everyone praised his singing.","vi":"Anh ấy bắt đầu đỏ mặt khi mọi người khen ngợi tiếng hát của mình.","audioKind":"ex"},{"en":"Students who blush during presentations may benefit from supportive feedback and regular opportunities to practise speaking.","vi":"Những học sinh hay đỏ mặt khi thuyết trình có thể được hỗ trợ nhờ những lời nhận xét khích lệ và cơ hội luyện tập nói thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"blush with embarrassment","vi":"đỏ mặt vì ngượng"},{"en":"make someone blush","vi":"làm cho ai đó đỏ mặt"},{"en":"a deep blush","vi":"đỏ bừng mặt"}],"wordFamily":["blushing (adj.)"],"synonyms":["flush"],"antonyms":[],"tipVi":"Động từ thường ở dạng nội động từ; cấu trúc làm ai đó đỏ mặt dùng make someone blush.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_liking', 'en-b2-45', 'liking', '/ˈlaɪkɪŋ/', 'B2', 'sự ưa thích; gu; sở thích', 'n.', 'like (v.), likeable (adj.), dislike (n.)', 'Đồng nghĩa: fondness, preference · Trái nghĩa: dislike, aversion', 'a liking for có nghĩa là sự yêu thích; to your liking có nghĩa là vừa ý, hợp sở thích.', 'I''ve developed a liking for spicy soup this winter.', NULL, 'Mùa đông này tôi đâm ra thích ăn súp cay.', '{"wordId":"liking","ukIpa":"/ˈlaɪkɪŋ/","usIpa":"/ˈlaɪkɪŋ/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"a feeling of enjoying or being fond of something","vi":"sự ưa thích; gu; sở thích"}],"examples":[{"en":"I''ve developed a liking for spicy soup this winter.","vi":"Mùa đông này tôi đâm ra thích ăn súp cay.","audioKind":"ex"},{"en":"Children who develop a liking for outdoor activities may be more willing to adopt healthy habits later in life.","vi":"Trẻ em phát triển niềm yêu thích với các hoạt động ngoài trời có thể sẽ sẵn sàng hình thành các thói quen lành mạnh hơn khi lớn lên.","audioKind":"ex2"}],"collocations":[{"en":"a liking for","vi":"niềm yêu thích đối với"},{"en":"take a liking to","vi":"bắt đầu thích"},{"en":"to your liking","vi":"vừa ý bạn; hợp khẩu vị bạn"},{"en":"develop a liking for","vi":"dần yêu thích"}],"wordFamily":["like (v.)","likeable (adj.)","dislike (n.)"],"synonyms":["fondness","preference"],"antonyms":["dislike","aversion"],"tipVi":"a liking for có nghĩa là sự yêu thích; to your liking có nghĩa là vừa ý, hợp sở thích.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_startle', 'en-b2-45', 'startle', '/ˈstɑːrtəl/', 'B2', 'làm giật mình; làm hoảng hốt', 'v.', 'startled (adj.), startling (adj.), startlingly (adv.)', 'Đồng nghĩa: frighten, surprise', 'Nhấn mạnh sự bất ngờ thình lình, không đồng nghĩa với nỗi sợ hãi kéo dài.', 'The sudden knock startled me while I was cooking.', NULL, 'Tiếng gõ cửa bất ngờ đã làm tôi giật mình trong lúc đang nấu ăn.', '{"wordId":"startle","ukIpa":"/ˈstɑːtəl/","usIpa":"/ˈstɑːrtəl/","cefr":"B2","topic":"emotion","senses":[{"pos":"v.","en":"To suddenly surprise or frighten someone","vi":"làm giật mình; làm hoảng hốt"}],"examples":[{"en":"The sudden knock startled me while I was cooking.","vi":"Tiếng gõ cửa bất ngờ đã làm tôi giật mình trong lúc đang nấu ăn.","audioKind":"ex"},{"en":"Loud construction noises can startle nearby wildlife and disrupt their feeding patterns during the breeding season.","vi":"Tiếng ồn xây dựng lớn có thể làm động vật hoang dã quanh đó giật mình hoảng sợ và phá vỡ tập tính kiếm ăn của chúng trong mùa sinh sản.","audioKind":"ex2"}],"collocations":[{"en":"startle someone","vi":"làm ai đó giật mình"},{"en":"be startled by","vi":"bị làm cho giật mình bởi"},{"en":"startle easily","vi":"dễ bị giật mình"}],"wordFamily":["startled (adj.)","startling (adj.)","startlingly (adv.)"],"synonyms":["frighten","surprise"],"antonyms":[],"tipVi":"Nhấn mạnh sự bất ngờ thình lình, không đồng nghĩa với nỗi sợ hãi kéo dài.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grief', 'en-b2-45', 'grief', '/ɡriːf/', 'B2', 'nỗi đau buồn sâu sắc; niềm thương tiếc', 'n.', 'grieve (v.), grieving (adj.)', 'Đồng nghĩa: sorrow, heartache · Trái nghĩa: joy', 'Khi diễn tả nỗi đau buồn thường là danh từ không đếm được và gắn liền với việc mất đi người thân.', 'She found comfort in friends during her grief.', NULL, 'Cô ấy tìm thấy sự an ủi từ bạn bè trong cơn đau buồn.', '{"wordId":"grief","ukIpa":"/ɡriːf/","usIpa":"/ɡriːf/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"Deep sadness, especially after someone you love has died","vi":"nỗi đau buồn sâu sắc; niềm thương tiếc"}],"examples":[{"en":"She found comfort in friends during her grief.","vi":"Cô ấy tìm thấy sự an ủi từ bạn bè trong cơn đau buồn.","audioKind":"ex"},{"en":"Schools should offer counselling to help young people manage grief after the loss of a family member.","vi":"Nhà trường nên cung cấp dịch vụ tư vấn tâm lý để giúp các bạn trẻ vượt qua nỗi đau thương sau khi mất đi người thân trong gia đình.","audioKind":"ex2"}],"collocations":[{"en":"deep grief","vi":"nỗi buồn sâu sắc"},{"en":"overcome with grief","vi":"đau buồn tột cùng"},{"en":"cope with grief","vi":"vượt qua nỗi đau buồn"}],"wordFamily":["grieve (v.)","grieving (adj.)"],"synonyms":["sorrow","heartache"],"antonyms":["joy"],"tipVi":"Khi diễn tả nỗi đau buồn thường là danh từ không đếm được và gắn liền với việc mất đi người thân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_curse', 'en-b2-45', 'curse', '/kɜːrs/', 'B2', 'chửi thề; nguyền rủa; lời nguyền; mối họa; tai ương', 'v.', 'cursed (adj.)', 'Đồng nghĩa: swear · Trái nghĩa: blessing', 'curse có thể mang nghĩa chửi thề hoặc yểm bùa; swear cũng có thể dùng với nghĩa thề thốt hoặc chửi thề.', 'He cursed quietly when his umbrella broke in the rain.', NULL, 'Anh ấy lẩm bẩm chửi thề khi chiếc ô bị hỏng giữa trời mưa.', '{"wordId":"curse","ukIpa":"/kɜːs/","usIpa":"/kɜːrs/","cefr":"B2","topic":"emotion","senses":[{"pos":"v.","en":"to use rude words because you are angry","vi":"chửi thề; nguyền rủa"},{"pos":"n.","en":"words intended to bring someone bad luck through magic","vi":"lời nguyền"},{"pos":"n.","en":"something that causes serious trouble or suffering","vi":"mối họa; tai ương"}],"examples":[{"en":"He cursed quietly when his umbrella broke in the rain.","vi":"Anh ấy lẩm bẩm chửi thề khi chiếc ô bị hỏng giữa trời mưa.","audioKind":"ex"},{"en":"For isolated communities, unreliable transport can be a curse that limits access to healthcare and employment.","vi":"Đối với các cộng đồng bị cô lập, giao thông kém phát triển có thể là một mối họa làm hạn chế khả năng tiếp cận dịch vụ y tế và việc làm.","audioKind":"ex2"}],"collocations":[{"en":"curse under one''s breath","vi":"lẩm bẩm chửi thề"},{"en":"put a curse on","vi":"đặt lời nguyền lên"},{"en":"a blessing and a curse","vi":"vừa là phúc vừa là họa"}],"wordFamily":["cursed (adj.)"],"synonyms":["swear"],"antonyms":["blessing"],"tipVi":"curse có thể mang nghĩa chửi thề hoặc yểm bùa; swear cũng có thể dùng với nghĩa thề thốt hoặc chửi thề.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_daring', 'en-b2-45', 'daring', '/ˈderɪŋ/', 'B2', 'táo bạo; liều lĩnh; sự táo bạo; sự cả gan', 'adj.', 'dare (v.), daringly (adv.)', 'Đồng nghĩa: bold, adventurous · Trái nghĩa: cautious, timid', 'Khi là tính từ, từ này nhấn mạnh sự dám mạo hiểm; khi là danh từ, nó thường là danh từ không đếm được.', 'Her daring outfit featured a bright orange cape.', NULL, 'Bộ trang phục táo bạo của cô ấy có điểm nhấn là chiếc áo choàng màu cam sáng.', '{"wordId":"daring","ukIpa":"/ˈdeərɪŋ/","usIpa":"/ˈderɪŋ/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"Willing to take risks or try unusually bold things.","vi":"táo bạo; liều lĩnh"},{"pos":"n.","en":"The courage to take risks or attempt difficult things.","vi":"sự táo bạo; sự cả gan"}],"examples":[{"en":"Her daring outfit featured a bright orange cape.","vi":"Bộ trang phục táo bạo của cô ấy có điểm nhấn là chiếc áo choàng màu cam sáng.","audioKind":"ex"},{"en":"The architect proposed a daring design that combined affordable housing with extensive rooftop gardens.","vi":"Kiến trúc sư đã đề xuất một thiết kế táo bạo kết hợp giữa nhà ở giá rẻ và các khu vườn rộng trên mái nhà.","audioKind":"ex2"}],"collocations":[{"en":"a daring rescue","vi":"một cuộc giải cứu táo bạo"},{"en":"a daring design","vi":"một thiết kế táo bạo"},{"en":"courage and daring","vi":"dũng khí và sự táo bạo"}],"wordFamily":["dare (v.)","daringly (adv.)"],"synonyms":["bold","adventurous"],"antonyms":["cautious","timid"],"tipVi":"Khi là tính từ, từ này nhấn mạnh sự dám mạo hiểm; khi là danh từ, nó thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_optimistic', 'en-b2-45', 'optimistic', '/ˌɑːptɪˈmɪstɪk/', 'B2', 'lạc quan; mang tính hy vọng', 'adj.', 'optimism (n.), optimist (n.), optimistically (adv.)', 'Đồng nghĩa: hopeful, positive · Trái nghĩa: pessimistic', 'Thường dùng be optimistic about; từ trái nghĩa là pessimistic.', 'Despite the rain, we remained optimistic about our picnic.', NULL, 'Mặc dù trời mưa, chúng tôi vẫn giữ thái độ lạc quan về buổi dã ngoại của mình.', '{"wordId":"optimistic","ukIpa":"/ˌɒptɪˈmɪstɪk/","usIpa":"/ˌɑːptɪˈmɪstɪk/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"Expecting good things to happen or a situation to improve.","vi":"lạc quan; mang tính hy vọng"}],"examples":[{"en":"Despite the rain, we remained optimistic about our picnic.","vi":"Mặc dù trời mưa, chúng tôi vẫn giữ thái độ lạc quan về buổi dã ngoại của mình.","audioKind":"ex"},{"en":"Many graduates remain optimistic about their career prospects despite increasing competition in the labour market.","vi":"Nhiều sinh viên tốt nghiệp vẫn lạc quan về triển vọng nghề nghiệp của họ dù sự cạnh tranh trên thị trường lao động ngày càng gay gắt.","audioKind":"ex2"}],"collocations":[{"en":"optimistic about","vi":"lạc quan về"},{"en":"cautiously optimistic","vi":"lạc quan thận trọng"},{"en":"optimistic outlook","vi":"góc nhìn lạc quan"}],"wordFamily":["optimism (n.)","optimist (n.)","optimistically (adv.)"],"synonyms":["hopeful","positive"],"antonyms":["pessimistic"],"tipVi":"Thường dùng be optimistic about; từ trái nghĩa là pessimistic.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_expectancy', 'en-b2-45', 'expectancy', '/ɪkˈspektənsi/', 'B2', 'sự ngóng trông; niềm hy vọng; sự chờ đợi; tuổi thọ dự tính; thời gian dự kiến', 'n.', 'expect (v.), expectation (n.), expectant (adj.), expectantly (adv.)', 'Đồng nghĩa: anticipation', 'life expectancy chỉ tuổi thọ dự tính (thống kê), không đồng nghĩa với độ tuổi thực tế của một cá nhân.', 'The children watched the curtain rise with eager expectancy.', NULL, 'Bọn trẻ chăm chú nhìn bức màn kéo lên với sự háo hức mong chờ.', '{"wordId":"expectancy","ukIpa":"/ɪkˈspektənsi/","usIpa":"/ɪkˈspektənsi/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"A feeling that something pleasant or exciting will happen.","vi":"sự ngóng trông; niềm hy vọng; sự chờ đợi"},{"pos":"n.","en":"The expected length of life or duration of something.","vi":"tuổi thọ dự tính; thời gian dự kiến"}],"examples":[{"en":"The children watched the curtain rise with eager expectancy.","vi":"Bọn trẻ chăm chú nhìn bức màn kéo lên với sự háo hức mong chờ.","audioKind":"ex"},{"en":"Improved sanitation and access to healthcare have increased life expectancy in many parts of the world.","vi":"Sự cải thiện về điều kiện vệ sinh và khả năng tiếp cận dịch vụ y tế đã làm tăng tuổi thọ trung bình ở nhiều nơi trên thế giới.","audioKind":"ex2"}],"collocations":[{"en":"life expectancy","vi":"tuổi thọ trung bình"},{"en":"an air of expectancy","vi":"không khí đầy mong đợi"},{"en":"eager expectancy","vi":"sự kỳ vọng háo hức"}],"wordFamily":["expect (v.)","expectation (n.)","expectant (adj.)","expectantly (adv.)"],"synonyms":["anticipation"],"antonyms":[],"tipVi":"life expectancy chỉ tuổi thọ dự tính (thống kê), không đồng nghĩa với độ tuổi thực tế của một cá nhân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_misery', 'en-b2-45', 'misery', '/ˈmɪzəri/', 'B2', 'nỗi thống khổ; sự khốn cùng; điều kiện sống nghèo đói và kham khổ', 'n.', 'miserable (adj.), miserably (adv.)', 'Đồng nghĩa: suffering, unhappiness · Trái nghĩa: happiness, joy', 'Danh từ này thường không đếm được; tuy nhiên a misery có thể chỉ một hoàn cảnh vô cùng tồi tệ.', 'The constant noise made her life a misery.', NULL, 'Tiếng ồn liên tục đã biến cuộc sống của cô ấy thành một cực hình.', '{"wordId":"misery","ukIpa":"/ˈmɪzəri/","usIpa":"/ˈmɪzəri/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"great unhappiness or suffering","vi":"nỗi thống khổ; sự khốn cùng"},{"pos":"n.","en":"extremely poor and uncomfortable living conditions","vi":"điều kiện sống nghèo đói và kham khổ"}],"examples":[{"en":"The constant noise made her life a misery.","vi":"Tiếng ồn liên tục đã biến cuộc sống của cô ấy thành một cực hình.","audioKind":"ex"},{"en":"Improving access to affordable housing can reduce the misery experienced by families living in overcrowded temporary accommodation.","vi":"Việc cải thiện khả năng tiếp cận nhà ở giá rẻ có thể làm giảm bớt nỗi thống khổ của các gia đình sống trong những khu nhà ở tạm bợ chật chội.","audioKind":"ex2"}],"collocations":[{"en":"cause misery","vi":"gây ra đau khổ"},{"en":"live in misery","vi":"sống trong cảnh khốn cùng"},{"en":"make someone''s life a misery","vi":"biến cuộc sống của ai đó thành cực hình"}],"wordFamily":["miserable (adj.)","miserably (adv.)"],"synonyms":["suffering","unhappiness"],"antonyms":["happiness","joy"],"tipVi":"Danh từ này thường không đếm được; tuy nhiên a misery có thể chỉ một hoàn cảnh vô cùng tồi tệ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fabulous', 'en-b2-45', 'fabulous', '/ˈfæbjələs/', 'B2', 'tuyệt vời, tuyệt diệu; cực kỳ lớn, khổng lồ (về số lượng, giá trị); thuộc về huyền thoại, thần thoại', 'adj.', 'fabulously (adv.)', 'Đồng nghĩa: wonderful, fantastic · Trái nghĩa: terrible', 'Nghĩa "tuyệt vời" thường dùng trong văn phong thân mật, mang sắc thái cảm xúc mạnh.', 'We had a fabulous picnic beside the lake yesterday.', NULL, 'Chúng tôi đã có một buổi dã ngoại tuyệt vời bên hồ vào ngày hôm qua.', '{"wordId":"fabulous","ukIpa":"/ˈfæbjələs/","usIpa":"/ˈfæbjələs/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"Extremely good, enjoyable, or impressive.","vi":"tuyệt vời, tuyệt diệu"},{"pos":"adj.","en":"Remarkably large in amount, value, or extent.","vi":"cực kỳ lớn, khổng lồ (về số lượng, giá trị)"},{"pos":"adj.","en":"Existing in traditional stories rather than in reality.","vi":"thuộc về huyền thoại, thần thoại"}],"examples":[{"en":"We had a fabulous picnic beside the lake yesterday.","vi":"Chúng tôi đã có một buổi dã ngoại tuyệt vời bên hồ vào ngày hôm qua.","audioKind":"ex"},{"en":"Although tourism can generate fabulous wealth, its economic benefits are not always shared fairly among local residents.","vi":"Mặc dù ngành du lịch có thể tạo ra khối tài sản khổng lồ, nhưng lợi ích kinh tế của nó không phải lúc nào cũng được chia sẻ công bằng giữa người dân địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a fabulous time","vi":"khoảng thời gian tuyệt vời"},{"en":"look fabulous","vi":"trông tuyệt đẹp"},{"en":"fabulous wealth","vi":"của cải khổng lồ"}],"wordFamily":["fabulously (adv.)"],"synonyms":["wonderful","fantastic"],"antonyms":["terrible"],"tipVi":"Nghĩa \"tuyệt vời\" thường dùng trong văn phong thân mật, mang sắc thái cảm xúc mạnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_awkward', 'en-b2-45', 'awkward', '/ˈɔːkwərd/', 'B2', 'lúng túng; ngượng ngùng; khó xử; vụng về; khó thao tác; khó cầm nắm; khó giải quyết; khó xử lý; bất tiện', 'adj.', 'awkwardly (adv.), awkwardness (n.)', NULL, 'awkward có thể chỉ sự ngượng ngùng trong giao tiếp, hoặc chỉ sự vụng về trong cử động.', 'There was an awkward silence after I forgot her name.', NULL, 'Đã có một khoảng lặng ngượng ngùng sau khi tôi quên mất tên cô ấy.', '{"wordId":"awkward","ukIpa":"/ˈɔːkwəd/","usIpa":"/ˈɔːkwərd/","cefr":"B2","topic":"emotion","senses":[{"pos":"adj.","en":"making you feel embarrassed or uncomfortable","vi":"lúng túng; ngượng ngùng; khó xử"},{"pos":"adj.","en":"moving clumsily or difficult to handle","vi":"vụng về; khó thao tác; khó cầm nắm"},{"pos":"adj.","en":"difficult to deal with or manage","vi":"khó giải quyết; khó xử lý; bất tiện"}],"examples":[{"en":"There was an awkward silence after I forgot her name.","vi":"Đã có một khoảng lặng ngượng ngùng sau khi tôi quên mất tên cô ấy.","audioKind":"ex"},{"en":"Flexible working arrangements can help parents manage awkward schedules without sacrificing their career opportunities.","vi":"Các thỏa thuận làm việc linh hoạt có thể giúp các bậc phụ huynh xử lý lịch trình khó sắp xếp mà không phải hy sinh cơ hội nghề nghiệp của họ.","audioKind":"ex2"}],"collocations":[{"en":"an awkward silence","vi":"một khoảng lặng ngượng ngùng"},{"en":"feel awkward","vi":"cảm thấy lúng túng"},{"en":"an awkward question","vi":"một câu hỏi khó trả lời"},{"en":"an awkward position","vi":"một hoàn cảnh khó xử"}],"wordFamily":["awkwardly (adv.)","awkwardness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"awkward có thể chỉ sự ngượng ngùng trong giao tiếp, hoặc chỉ sự vụng về trong cử động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_temper', 'en-b2-45', 'temper', '/ˈtempɚ/', 'B2', 'cơn giận; tính khí; tâm trạng cáu kỉnh; làm dịu; tiết chế; giảm nhẹ; tôi (kim loại); làm cứng', 'n.', 'temperamental (adj.), tempering (n.)', NULL, 'lose your temper là phát cáu; động từ thường dùng cấu trúc temper A with B.', 'He lost his temper when the drawer jammed again.', NULL, 'Anh ấy nổi giận khi ngăn kéo lại bị kẹt lần nữa.', '{"wordId":"temper","ukIpa":"/ˈtempə/","usIpa":"/ˈtempɚ/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"A tendency to become angry, or an angry mood.","vi":"cơn giận; tính khí; tâm trạng cáu kỉnh"},{"pos":"v.","en":"Make something less strong, extreme, or severe.","vi":"làm dịu; tiết chế; giảm nhẹ"},{"pos":"v.","en":"Treat metal with heat to give it suitable hardness and toughness.","vi":"tôi (kim loại); làm cứng"}],"examples":[{"en":"He lost his temper when the drawer jammed again.","vi":"Anh ấy nổi giận khi ngăn kéo lại bị kẹt lần nữa.","audioKind":"ex"},{"en":"Governments should temper enthusiasm for new technologies with careful consideration of their potential social consequences.","vi":"Chính phủ nên kết hợp sự nhiệt tình đối với các công nghệ mới với việc cân nhắc cẩn thận các hệ quả xã hội tiềm tàng của chúng.","audioKind":"ex2"}],"collocations":[{"en":"lose your temper","vi":"mất bình tĩnh"},{"en":"keep your temper","vi":"giữ bình tĩnh"},{"en":"a short temper","vi":"tính nóng nảy"},{"en":"temper enthusiasm with caution","vi":"tiết chế sự nhiệt tình bằng sự thận trọng"}],"wordFamily":["temperamental (adj.)","tempering (n.)"],"synonyms":[],"antonyms":[],"tipVi":"lose your temper là phát cáu; động từ thường dùng cấu trúc temper A with B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fascination', 'en-b2-45', 'fascination', '/ˌfæsɪˈneɪʃən/', 'B2', 'sự say mê; niềm hứng thú tột độ', 'n.', 'fascinate (v.), fascinating (adj.), fascinated (adj.)', 'Đồng nghĩa: absorption · Trái nghĩa: indifference', 'Say mê cái gì dùng fascination with; ngắm nhìn một cách say sưa dùng with fascination.', 'She watched the tiny fish with fascination for hours.', NULL, 'Cô ấy đã say sưa ngắm nhìn những chú cá nhỏ bé trong suốt nhiều giờ liền.', '{"wordId":"fascination","ukIpa":"/ˌfæsɪˈneɪʃən/","usIpa":"/ˌfæsɪˈneɪʃən/","cefr":"B2","topic":"emotion","senses":[{"pos":"n.","en":"a very strong interest in someone or something","vi":"sự say mê; niềm hứng thú tột độ"}],"examples":[{"en":"She watched the tiny fish with fascination for hours.","vi":"Cô ấy đã say sưa ngắm nhìn những chú cá nhỏ bé trong suốt nhiều giờ liền.","audioKind":"ex"},{"en":"Children''s fascination with wildlife can provide a valuable starting point for environmental education in primary schools.","vi":"Niềm say mê của trẻ em đối với động vật hoang dã có thể là điểm khởi đầu quý giá cho giáo dục môi trường ở các trường tiểu học.","audioKind":"ex2"}],"collocations":[{"en":"fascination with","vi":"sự say mê với..."},{"en":"watch with fascination","vi":"chăm chú ngắm nhìn"},{"en":"hold a fascination for","vi":"có sức hút đối với..."}],"wordFamily":["fascinate (v.)","fascinating (adj.)","fascinated (adj.)"],"synonyms":["absorption"],"antonyms":["indifference"],"tipVi":"Say mê cái gì dùng fascination with; ngắm nhìn một cách say sưa dùng with fascination.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_45_1', 'en-b2-45', 'Cách dùng “helpless” (adj.) — bất lực; không thể tự bảo vệ hoặc xoay sở', 'feel helpless  ·  a helpless victim  ·  helpless against', 'helpless có nghĩa là bất lực, vô phương; cần phân biệt với unhelpful có nghĩa là không hữu ích hoặc không chịu giúp đỡ.', 'Họ từ (Word Family): help (v.), helplessly (adv.), helplessness (n.), helpful (adj.) | Đồng nghĩa: powerless · Trái nghĩa: self-reliant', '[{"hanzi":"I felt helpless when the lift suddenly stopped moving.","pinyin":"","meaning":"Tôi cảm thấy bất lực khi thang máy đột ngột dừng chạy."},{"hanzi":"Without accessible support services, elderly people may feel helpless when trying to manage increasingly complex digital systems.","pinyin":"","meaning":"Nếu thiếu đi các dịch vụ hỗ trợ dễ tiếp cận, người cao tuổi có thể cảm thấy bất lực khi cố gắng sử dụng các hệ thống kỹ thuật số ngày càng phức tạp."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_45_2', 'en-b2-45', 'Cách dùng “beloved” (adj.) — được yêu quý; yêu dấu', 'a beloved friend  ·  a beloved pet  ·  a beloved institution', 'Thường đóng vai trò là tính từ; khi dùng như danh từ thì chỉ người tình, mang văn phong trang trọng hoặc văn chương.', 'Họ từ (Word Family): love (v.), loving (adj.), lovable (adj.) | Đồng nghĩa: cherished, treasured, dear · Trái nghĩa: hated', '[{"hanzi":"He carefully repaired his daughter''s beloved wooden toy.","pinyin":"","meaning":"Anh ấy cẩn thận sửa chữa món đồ chơi bằng gỗ yêu quý của con gái mình."},{"hanzi":"Public libraries remain beloved community spaces because they offer opportunities for learning and social connection.","pinyin":"","meaning":"Các thư viện công cộng vẫn là không gian cộng đồng rất được yêu thích bởi vì chúng mang lại cơ hội học tập và kết nối xã hội."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_45_3', 'en-b2-45', 'Cách dùng “thrill” (n.) — cảm giác hồi hộp, phấn khích tột độ', 'the thrill of discovery  ·  a thrill of excitement  ·  thrill an audience', 'Tính từ thrilled dùng để chỉ con người cảm thấy phấn khích; thrilling dùng để chỉ sự vật gây ra cảm giác phấn khích.', 'Họ từ (Word Family): thrilled (adj.), thrilling (adj.), thriller (n.) | Đồng nghĩa: excitement, exhilaration', '[{"hanzi":"I felt a real thrill when the kite finally flew.","pinyin":"","meaning":"Tôi cảm thấy thực sự phấn khích khi con diều cuối cùng cũng bay lên được."},{"hanzi":"The thrill of discovery can motivate students to explore scientific questions beyond the classroom.","pinyin":"","meaning":"Cảm giác hồi hộp khi khám phá ra điều mới lạ có thể thúc đẩy học sinh tìm hiểu các vấn đề khoa học ngoài lớp học."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_45_4', 'en-b2-45', 'Cách dùng “curse” (v.) — chửi thề; nguyền rủa', 'curse under one''s breath  ·  put a curse on  ·  a blessing and a curse', 'curse có thể mang nghĩa chửi thề hoặc yểm bùa; swear cũng có thể dùng với nghĩa thề thốt hoặc chửi thề.', 'Họ từ (Word Family): cursed (adj.) | Đồng nghĩa: swear · Trái nghĩa: blessing', '[{"hanzi":"He cursed quietly when his umbrella broke in the rain.","pinyin":"","meaning":"Anh ấy lẩm bẩm chửi thề khi chiếc ô bị hỏng giữa trời mưa."},{"hanzi":"For isolated communities, unreliable transport can be a curse that limits access to healthcare and employment.","pinyin":"","meaning":"Đối với các cộng đồng bị cô lập, giao thông kém phát triển có thể là một mối họa làm hạn chế khả năng tiếp cận dịch vụ y tế và việc làm."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_45_1', 'en-b2-45', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_45_1_1', 'ten_b2_45_1', 'beloved', 'He carefully repaired his daughter''s beloved wooden toy.', 'He carefully repaired his daughter''s beloved wooden toy.', '/bɪˈlʌvɪd/', 'Anh ấy cẩn thận sửa chữa món đồ chơi bằng gỗ yêu quý của con gái mình.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_45_1_2', 'ten_b2_45_1', 'embarrassment', 'I blushed with embarrassment when I forgot my neighbour''s name.', 'I blushed with embarrassment when I forgot my neighbour''s name.', '/ɪmˈbærəsmənt/', 'Tôi đỏ mặt vì ngượng ngùng khi quên mất tên của hàng xóm.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_45_1_3', 'ten_b2_45_1', 'helpless', 'I felt helpless when the lift suddenly stopped moving.', 'I felt helpless when the lift suddenly stopped moving.', '/ˈhelpləs/', 'Tôi cảm thấy bất lực khi thang máy đột ngột dừng chạy.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_45_1_4', 'ten_b2_45_1', 'sorrow', 'She felt deep sorrow when her closest friend moved away.', 'She felt deep sorrow when her closest friend moved away.', '/ˈsɑːroʊ/', 'Cô ấy cảm thấy vô cùng đau buồn khi người bạn thân nhất của mình chuyển đi nơi khác.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_45_1_5', 'ten_b2_45_1', 'appreciation', 'We baked our neighbour a cake to show our appreciation.', 'We baked our neighbour a cake to show our appreciation.', '/əˌpriːʃiˈeɪʃən/', 'Chúng tôi nướng bánh tặng hàng xóm để bày tỏ lòng biết ơn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_45_1_6', 'ten_b2_45_1', 'giggle', 'The children giggled when the puppy chased its tail.', 'The children giggled when the puppy chased its tail.', '/ˈɡɪɡəl/', 'Lũ trẻ khúc khích cười khi chú chó con đuổi theo cái đuôi của chính mình.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_45_1_7', 'ten_b2_45_1', 'uninterested', 'Leo seemed uninterested in the game and went outside.', 'Leo seemed uninterested in the game and went outside.', '/ʌnˈɪntrəstɪd/', 'Leo có vẻ không có hứng thú với trò chơi và đã đi ra ngoài.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_45_1_8', 'ten_b2_45_1', 'furious', 'Lena was furious when someone scratched her new bicycle.', 'Lena was furious when someone scratched her new bicycle.', '/ˈfjʊriəs/', 'Lena vô cùng tức giận khi ai đó làm xước chiếc xe đạp mới của cô ấy.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_45_1_1', 'en-b2-45', 'ten_b2_45_1', 'listening', 'listening', 'He carefully repaired his daughter''s beloved wooden toy.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Anh ấy không chịu cho mượn chiếc xe đạp mới của mình.","Chúng tôi đã có một buổi dã ngoại tuyệt vời bên hồ vào ngày hôm qua.","Anh ấy cẩn thận sửa chữa món đồ chơi bằng gỗ yêu quý của con gái mình.","Mặc dù trời mưa, chúng tôi vẫn giữ thái độ lạc quan về buổi dã ngoại của mình."]'::jsonb, 2, 'He carefully repaired his daughter''s beloved wooden toy. → Anh ấy cẩn thận sửa chữa món đồ chơi bằng gỗ yêu quý của con gái mình.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_45_1_2', 'en-b2-45', 'ten_b2_45_1', 'listening', 'listening', 'I blushed with embarrassment when I forgot my neighbour''s name.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Lũ trẻ khúc khích cười khi chú chó con đuổi theo cái đuôi của chính mình.","Tôi đỏ mặt vì ngượng ngùng khi quên mất tên của hàng xóm.","Anh ấy cẩn thận sửa chữa món đồ chơi bằng gỗ yêu quý của con gái mình.","Anh ấy nổi giận khi ngăn kéo lại bị kẹt lần nữa."]'::jsonb, 1, 'I blushed with embarrassment when I forgot my neighbour''s name. → Tôi đỏ mặt vì ngượng ngùng khi quên mất tên của hàng xóm.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_45_1_3', 'en-b2-45', 'ten_b2_45_1', 'listening', 'listening', 'I felt helpless when the lift suddenly stopped moving.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Lũ trẻ khúc khích cười khi chú chó con đuổi theo cái đuôi của chính mình.","Tôi đỏ mặt vì ngượng ngùng khi quên mất tên của hàng xóm.","Cô ấy cảm thấy vô cùng đau buồn khi người bạn thân nhất của mình chuyển đi nơi khác.","Tôi cảm thấy bất lực khi thang máy đột ngột dừng chạy."]'::jsonb, 3, 'I felt helpless when the lift suddenly stopped moving. → Tôi cảm thấy bất lực khi thang máy đột ngột dừng chạy.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_45_2', 'en-b2-45', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_45_2_1', 'ten_b2_45_2', 'beloved', 'Public libraries remain beloved community spaces because they offer opportunities for learning and social connection.', 'Public libraries remain beloved community spaces because they offer opportunities for learning and social connection.', '/bɪˈlʌvɪd/', 'Các thư viện công cộng vẫn là không gian cộng đồng rất được yêu thích bởi vì chúng mang lại cơ hội học tập và kết nối xã hội.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_45_2_2', 'ten_b2_45_2', 'embarrassment', 'Fear of embarrassment may prevent language learners from practising their speaking skills in front of others.', 'Fear of embarrassment may prevent language learners from practising their speaking skills in front of others.', '/ɪmˈbærəsmənt/', 'Nỗi sợ bị bối rối có thể khiến người học ngoại ngữ ngại thực hành kỹ năng nói trước mặt người khác.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_45_2_3', 'ten_b2_45_2', 'helpless', 'Without accessible support services, elderly people may feel helpless when trying to manage increasingly complex digital systems.', 'Without accessible support services, elderly people may feel helpless when trying to manage increasingly complex digital systems.', '/ˈhelpləs/', 'Nếu thiếu đi các dịch vụ hỗ trợ dễ tiếp cận, người cao tuổi có thể cảm thấy bất lực khi cố gắng sử dụng các hệ thống kỹ thuật số ngày càng phức tạp.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_45_2_4', 'ten_b2_45_2', 'sorrow', 'Community support can help people cope with sorrow after the loss of a loved one.', 'Community support can help people cope with sorrow after the loss of a loved one.', '/ˈsɑːroʊ/', 'Sự hỗ trợ từ cộng đồng có thể giúp mọi người đối phó với nỗi đau buồn sau khi mất đi người thân yêu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_45_2_5', 'ten_b2_45_2', 'appreciation', 'Arts education can develop students'' appreciation of cultural traditions that differ from their own.', 'Arts education can develop students'' appreciation of cultural traditions that differ from their own.', '/əˌpriːʃiˈeɪʃən/', 'Giáo dục nghệ thuật có thể bồi dưỡng cho học sinh sự trân trọng đối với các truyền thống văn hóa khác biệt với văn hóa của chính họ.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_45_2_6', 'ten_b2_45_2', 'giggle', 'Young learners may giggle during unfamiliar activities, but this reaction does not necessarily indicate a lack of interest.', 'Young learners may giggle during unfamiliar activities, but this reaction does not necessarily indicate a lack of interest.', '/ˈɡɪɡəl/', 'Người học nhỏ tuổi có thể khúc khích cười trong các hoạt động lạ lẫm, nhưng phản ứng này không nhất thiết cho thấy sự thiếu quan tâm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_45_2_1', 'en-b2-45', 'ten_b2_45_2', 'listening', 'listening', 'Public libraries remain beloved community spaces because they offer opportunities for learning and social connection.', NULL, 'Trong câu vừa nghe, từ “beloved” mang nghĩa nào sau đây?', '["vải bạt; loại vải dày, chắc dùng cho lều, túi và buồm","sự chắc chắn; niềm tin chắc","được yêu quý; yêu dấu","bài tường thuật; câu chuyện"]'::jsonb, 2, '“beloved” (/bɪˈlʌvɪd/): được yêu quý; yêu dấu. Câu đầy đủ: Public libraries remain beloved community spaces because they offer opportunities for learning and social connection.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_45_2_2', 'en-b2-45', 'ten_b2_45_2', 'listening', 'listening', 'Fear of embarrassment may prevent language learners from practising their speaking skills in front of others.', NULL, 'Trong câu vừa nghe, từ “embarrassment” mang nghĩa nào sau đây?', '["có tính thực dụng; nặng về công năng hơn trang trí","võ sĩ; chiến binh","vũ khí, trang thiết bị quân sự","sự bối rối; sự ngượng ngùng"]'::jsonb, 3, '“embarrassment” (/ɪmˈbærəsmənt/): sự bối rối; sự ngượng ngùng. Câu đầy đủ: Fear of embarrassment may prevent language learners from practising their speaking skills in front of others.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
