INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_45_2', 'en-b2-45', NULL, 'comprehensive_test', 'listening', 'I blushed with embarrassment when I forgot my neighbour''s name.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đỏ mặt vì ngượng ngùng khi quên mất tên của hàng xóm.","Anh ấy không chịu cho mượn chiếc xe đạp mới của mình.","Mặc dù trời mưa, chúng tôi vẫn giữ thái độ lạc quan về buổi dã ngoại của mình.","Anh ấy cẩn thận sửa chữa món đồ chơi bằng gỗ yêu quý của con gái mình."]'::jsonb, 0, 'I blushed with embarrassment when I forgot my neighbour''s name. → Tôi đỏ mặt vì ngượng ngùng khi quên mất tên của hàng xóm.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_45_3', 'en-b2-45', NULL, 'comprehensive_test', 'listening', 'helpless', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["quân đội; binh lính","sự phối hợp; sự điều phối","đa số; phần lớn","bất lực; không thể tự bảo vệ hoặc xoay sở"]'::jsonb, 3, 'helpless (/ˈhelpləs/) → bất lực; không thể tự bảo vệ hoặc xoay sở', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_45_4', 'en-b2-45', NULL, 'comprehensive_test', 'listening', 'She felt deep sorrow when her closest friend moved away.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Anh ấy lẩm bẩm chửi thề khi chiếc ô bị hỏng giữa trời mưa.","Bọn trẻ chăm chú nhìn bức màn kéo lên với sự háo hức mong chờ.","Cô ấy cảm thấy vô cùng đau buồn khi người bạn thân nhất của mình chuyển đi nơi khác.","Lũ trẻ khúc khích cười khi chú chó con đuổi theo cái đuôi của chính mình."]'::jsonb, 2, 'She felt deep sorrow when her closest friend moved away. → Cô ấy cảm thấy vô cùng đau buồn khi người bạn thân nhất của mình chuyển đi nơi khác.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_45_5', 'en-b2-45', NULL, 'comprehensive_test', 'listening', 'appreciation', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["ẩm; ẩm ướt; ẩm mịn","lòng biết ơn; sự cảm kích","ngân sách; khoản kinh phí","thỏa đáng; đạt yêu cầu; đủ tiêu chuẩn"]'::jsonb, 1, 'appreciation (/əˌpriːʃiˈeɪʃən/) → lòng biết ơn; sự cảm kích; sự thấu hiểu; sự đánh giá cao; sự tăng giá; sự lên giá', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_45_6', 'en-b2-45', NULL, 'comprehensive_test', 'listening', 'The children giggled when the puppy chased its tail.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi cảm thấy bất lực khi thang máy đột ngột dừng chạy.","Lũ trẻ khúc khích cười khi chú chó con đuổi theo cái đuôi của chính mình.","Cô ấy cảm thấy vô cùng đau buồn khi người bạn thân nhất của mình chuyển đi nơi khác.","Leo có vẻ không có hứng thú với trò chơi và đã đi ra ngoài."]'::jsonb, 1, 'The children giggled when the puppy chased its tail. → Lũ trẻ khúc khích cười khi chú chó con đuổi theo cái đuôi của chính mình.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_45_7', 'en-b2-45', NULL, 'comprehensive_test', 'listening', 'uninterested', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["học viện; trường chuyên đào tạo một môn hoặc kỹ năng cụ thể","khoản trợ cấp, tiền cấp phát từ một tổ chức cho mục đích cụ thể","không có hứng thú, thờ ơ, không quan tâm","sự phòng thủ; sự bảo vệ"]'::jsonb, 2, 'uninterested (/ʌnˈɪntrəstɪd/) → không có hứng thú, thờ ơ, không quan tâm', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_45_8', 'en-b2-45', NULL, 'comprehensive_test', 'listening', 'Lena was furious when someone scratched her new bicycle.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bộ trang phục táo bạo của cô ấy có điểm nhấn là chiếc áo choàng màu cam sáng.","Tiếng ồn liên tục đã biến cuộc sống của cô ấy thành một cực hình.","Chúng tôi đã có một buổi dã ngoại tuyệt vời bên hồ vào ngày hôm qua.","Lena vô cùng tức giận khi ai đó làm xước chiếc xe đạp mới của cô ấy."]'::jsonb, 3, 'Lena was furious when someone scratched her new bicycle. → Lena vô cùng tức giận khi ai đó làm xước chiếc xe đạp mới của cô ấy.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
