INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_45_18', 'en-b2-45', NULL, 'comprehensive_test', 'reading', NULL, 'Public libraries remain beloved community spaces because they offer opportunities for learning and social connection.', 'Dựa vào câu trên, từ “beloved” có nghĩa phù hợp nhất là gì?', '["được yêu quý; yêu dấu","do đó; vì vậy; từ đó","to lớn; đồ sộ; nặng nề","rạn đá ngầm; đá ngầm"]'::jsonb, 0, 'beloved: được yêu quý; yêu dấu; người yêu dấu; người thương. Dịch cả câu: Các thư viện công cộng vẫn là không gian cộng đồng rất được yêu thích bởi vì chúng mang lại cơ hội học tập và kết nối xã hội.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_45_19', 'en-b2-45', NULL, 'comprehensive_test', 'reading', NULL, 'Fear of embarrassment may prevent language learners from practising their speaking skills in front of others.', 'Dựa vào câu trên, từ “embarrassment” có nghĩa phù hợp nhất là gì?', '["cuộc đình công","thúc giục; nài nỉ; khuyên răn mạnh mẽ","nhạc phim; phần âm thanh","sự bối rối; sự ngượng ngùng"]'::jsonb, 3, 'embarrassment: sự bối rối; sự ngượng ngùng; người gây bối rối; điều gây ngượng ngùng. Dịch cả câu: Nỗi sợ bị bối rối có thể khiến người học ngoại ngữ ngại thực hành kỹ năng nói trước mặt người khác.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_45_20', 'en-b2-45', NULL, 'comprehensive_test', 'reading', NULL, 'Without accessible support services, elderly people may feel helpless when trying to manage increasingly complex digital systems.', 'Dựa vào câu trên, từ “helpless” có nghĩa phù hợp nhất là gì?', '["vết lõm","bất lực; không thể tự bảo vệ hoặc xoay sở","sự phân biệt đối xử","thanh lịch; trang nhã"]'::jsonb, 1, 'helpless: bất lực; không thể tự bảo vệ hoặc xoay sở. Dịch cả câu: Nếu thiếu đi các dịch vụ hỗ trợ dễ tiếp cận, người cao tuổi có thể cảm thấy bất lực khi cố gắng sử dụng các hệ thống kỹ thuật số ngày càng phức tạp.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_45_21', 'en-b2-45', NULL, 'comprehensive_test', 'reading', NULL, 'Community support can help people cope with sorrow after the loss of a loved one.', 'Dựa vào câu trên, từ “sorrow” có nghĩa phù hợp nhất là gì?', '["va chạm; đâm vào nhau","tốc độ; nhịp độ","bán đảo","nỗi buồn; sự đau buồn"]'::jsonb, 3, 'sorrow: nỗi buồn; sự đau buồn. Dịch cả câu: Sự hỗ trợ từ cộng đồng có thể giúp mọi người đối phó với nỗi đau buồn sau khi mất đi người thân yêu.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_45_22', 'en-b2-45', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “lúng túng; ngượng ngùng; khó xử”', '["darken","commute","chatty","awkward"]'::jsonb, 3, 'lúng túng; ngượng ngùng; khó xử → awkward (/ˈɔːkwərd/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_45_23', 'en-b2-45', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cơn giận; tính khí; tâm trạng cáu kỉnh”', '["sprinkle","panic","deforestation","temper"]'::jsonb, 3, 'cơn giận; tính khí; tâm trạng cáu kỉnh → temper (/ˈtempɚ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_45_24', 'en-b2-45', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự say mê; niềm hứng thú tột độ”', '["reflection","bow","evaporate","fascination"]'::jsonb, 3, 'sự say mê; niềm hứng thú tột độ → fascination (/ˌfæsɪˈneɪʃən/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-46', 'en', 'Bài 46: Công việc & Nghề nghiệp (1) - CEFR B2', 'CEFR B2', 'B2 · Công việc', '25 từ vựng Tiếng Anh CEFR B2 chủ đề công việc & nghề nghiệp kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4046, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_administration', 'en-b2-46', 'administration', '/ədˌmɪnɪˈstreɪʃən/', 'B2', 'công tác quản lý; hoạt động hành chính; chính phủ; ban quản trị; sự cấp phát; sự cho uống thuốc', 'n.', 'administer (v.), administrator (n.), administrative (adj.), administratively (adv.)', 'Đồng nghĩa: management', 'Khi chỉ công việc quản lý thì thường không đếm được; khi chỉ một nhiệm kỳ chính phủ thì đếm được.', 'She handles the administration for our local sports club.', NULL, 'Cô ấy phụ trách công tác hành chính cho câu lạc bộ thể thao địa phương của chúng tôi.', '{"wordId":"administration","ukIpa":"/ədˌmɪnɪˈstreɪʃən/","usIpa":"/ədˌmɪnɪˈstreɪʃən/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"The work of organising and running an institution or business.","vi":"công tác quản lý; hoạt động hành chính"},{"pos":"n.","en":"The people responsible for managing a government or organisation.","vi":"chính phủ; ban quản trị"},{"pos":"n.","en":"The act of giving medicine or treatment to someone.","vi":"sự cấp phát; sự cho uống thuốc"}],"examples":[{"en":"She handles the administration for our local sports club.","vi":"Cô ấy phụ trách công tác hành chính cho câu lạc bộ thể thao địa phương của chúng tôi.","audioKind":"ex"},{"en":"Efficient administration allows public hospitals to allocate resources fairly and respond more quickly to patients'' needs.","vi":"Công tác quản lý hiệu quả giúp các bệnh viện công phân bổ nguồn lực công bằng và đáp ứng nhanh chóng hơn các nhu cầu của bệnh nhân.","audioKind":"ex2"}],"collocations":[{"en":"public administration","vi":"hành chính công"},{"en":"business administration","vi":"quản trị kinh doanh"},{"en":"school administration","vi":"quản lý trường học"},{"en":"administration of medication","vi":"sự cho thuốc điều trị"}],"wordFamily":["administer (v.)","administrator (n.)","administrative (adj.)","administratively (adv.)"],"synonyms":["management"],"antonyms":[],"tipVi":"Khi chỉ công việc quản lý thì thường không đếm được; khi chỉ một nhiệm kỳ chính phủ thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rewarding', 'en-b2-46', 'rewarding', '/rɪˈwɔːrdɪŋ/', 'B2', 'bổ ích; đáng làm; mang lại sự thỏa mãn; có lợi nhuận cao; thu nhập hấp dẫn', 'adj.', 'reward (n.), reward (v.), unrewarding (adj.)', 'Đồng nghĩa: fulfilling, satisfying · Trái nghĩa: unrewarding, unfulfilling', 'Thường chỉ sự thỏa mãn về tinh thần; để chỉ tiền bạc cần thêm financially.', 'Teaching my little cousin to swim was surprisingly rewarding.', NULL, 'Dạy em họ tôi bơi mang lại cho tôi cảm giác thành tựu đáng ngạc nhiên.', '{"wordId":"rewarding","ukIpa":"/rɪˈwɔːdɪŋ/","usIpa":"/rɪˈwɔːrdɪŋ/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"giving satisfaction or a sense of achievement","vi":"bổ ích; đáng làm; mang lại sự thỏa mãn"},{"pos":"adj.","en":"providing substantial financial benefits","vi":"có lợi nhuận cao; thu nhập hấp dẫn"}],"examples":[{"en":"Teaching my little cousin to swim was surprisingly rewarding.","vi":"Dạy em họ tôi bơi mang lại cho tôi cảm giác thành tựu đáng ngạc nhiên.","audioKind":"ex"},{"en":"Volunteering can be a rewarding experience that develops practical skills and strengthens connections within local communities.","vi":"Hoạt động tình nguyện có thể là một trải nghiệm ý nghĩa giúp phát triển các kỹ năng thực tế và củng cố sự gắn kết trong cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"rewarding experience","vi":"trải nghiệm bổ ích"},{"en":"rewarding career","vi":"sự nghiệp đáng tự hào"},{"en":"financially rewarding","vi":"có thu nhập cao"}],"wordFamily":["reward (n.)","reward (v.)","unrewarding (adj.)"],"synonyms":["fulfilling","satisfying"],"antonyms":["unrewarding","unfulfilling"],"tipVi":"Thường chỉ sự thỏa mãn về tinh thần; để chỉ tiền bạc cần thêm financially.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_superior', 'en-b2-46', 'superior', '/suːˈpɪriər/', 'B2', 'tốt hơn; chất lượng cao hơn; cấp trên; người quản lý; kiêu ngạo; trịch thượng; tự cho mình là hơn', 'adj.', 'superiority (n.)', 'Đồng nghĩa: better · Trái nghĩa: inferior', 'Khi so sánh dùng superior to, không dùng superior than.', 'These boots offer superior grip on wet paths.', NULL, 'Đôi bốt này có độ bám đường tốt hơn hẳn trên những con đường ẩm ướt.', '{"wordId":"superior","ukIpa":"/suːˈpɪəriə/","usIpa":"/suːˈpɪriər/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"Better in quality or performance than another","vi":"tốt hơn; chất lượng cao hơn"},{"pos":"n.","en":"Someone with a higher position or rank than you","vi":"cấp trên; người quản lý"},{"pos":"adj.","en":"Behaving as though you are better than other people","vi":"kiêu ngạo; trịch thượng; tự cho mình là hơn"}],"examples":[{"en":"These boots offer superior grip on wet paths.","vi":"Đôi bốt này có độ bám đường tốt hơn hẳn trên những con đường ẩm ướt.","audioKind":"ex"},{"en":"Public transport can provide a superior alternative to private cars when services are frequent and reliable.","vi":"Giao thông công cộng có thể là một lựa chọn thay thế tối ưu cho xe hơi cá nhân khi các chuyến xe chạy thường xuyên và đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"superior quality","vi":"chất lượng cao hơn"},{"en":"superior to","vi":"vượt trội hơn"},{"en":"immediate superior","vi":"cấp trên trực tiếp"},{"en":"a superior attitude","vi":"thái độ trịch thượng"}],"wordFamily":["superiority (n.)"],"synonyms":["better"],"antonyms":["inferior"],"tipVi":"Khi so sánh dùng superior to, không dùng superior than.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sack', 'en-b2-46', 'sack', '/sæk/', 'B2', 'bao tải lớn; túi vải thô; sa thải; đuổi việc; sự sa thải; việc bị đuổi việc', 'n.', 'sacking (n.)', 'Đồng nghĩa: bag, dismiss, fire', 'Nghĩa sa thải (sack) thường dùng trong văn phong thân mật hoặc tiếng Anh - Anh; từ trang trọng hơn là dismiss.', 'We carried a heavy sack of potatoes into the kitchen.', NULL, 'Chúng tôi khiêng một bao tải khoai tây nặng vào trong bếp.', '{"wordId":"sack","ukIpa":"/sæk/","usIpa":"/sæk/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"A large, strong bag used for storing or carrying things.","vi":"bao tải lớn; túi vải thô"},{"pos":"v.","en":"To dismiss someone from their job.","vi":"sa thải; đuổi việc"},{"pos":"n.","en":"Dismissal from a job, used in the phrase the sack.","vi":"sự sa thải; việc bị đuổi việc"}],"examples":[{"en":"We carried a heavy sack of potatoes into the kitchen.","vi":"Chúng tôi khiêng một bao tải khoai tây nặng vào trong bếp.","audioKind":"ex"},{"en":"Employers should not sack workers without explaining the reasons and allowing them to challenge the decision.","vi":"Người sử dụng lao động không nên sa thải nhân công mà không giải thích rõ lý do cũng như không cho họ cơ hội phản bác quyết định đó.","audioKind":"ex2"}],"collocations":[{"en":"a sack of potatoes","vi":"một bao khoai tây"},{"en":"get the sack","vi":"bị sa thải"},{"en":"sack someone for misconduct","vi":"sa thải ai đó do vi phạm kỷ luật"}],"wordFamily":["sacking (n.)"],"synonyms":["bag","dismiss","fire"],"antonyms":[],"tipVi":"Nghĩa sa thải (sack) thường dùng trong văn phong thân mật hoặc tiếng Anh - Anh; từ trang trọng hơn là dismiss.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_labor', 'en-b2-46', 'labor', '/ˈleɪbər/', 'B2', 'lao động; nhân công; làm việc vất vả; nỗ lực làm gì; sự chuyển dạ; quá trình sinh con', 'n.', 'laborer (n.), laborious (adj.), laboriously (adv.)', 'Đồng nghĩa: work, toil', 'labor là cách viết theo tiếng Mỹ, tiếng Anh-Anh viết là labour.', 'Repairing the old fence took a full day of labor.', NULL, 'Việc sửa chữa hàng rào cũ mất trọn một ngày lao động chân tay.', '{"wordId":"labor","ukIpa":"/ˈleɪbə/","usIpa":"/ˈleɪbər/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"work, especially physical work, or the workers who perform it","vi":"lao động; nhân công"},{"pos":"v.","en":"to work hard, often with considerable physical effort","vi":"làm việc vất vả; nỗ lực làm gì"},{"pos":"n.","en":"the process of giving birth to a baby","vi":"sự chuyển dạ; quá trình sinh con"}],"examples":[{"en":"Repairing the old fence took a full day of labor.","vi":"Việc sửa chữa hàng rào cũ mất trọn một ngày lao động chân tay.","audioKind":"ex"},{"en":"Investment in automation can reduce labor costs, but governments must help displaced workers develop new skills.","vi":"Đầu tư vào tự động hóa có thể giảm chi phí nhân công, nhưng chính phủ phải giúp những công nhân mất việc phát triển các kỹ năng mới.","audioKind":"ex2"}],"collocations":[{"en":"manual labor","vi":"lao động chân tay"},{"en":"labor market","vi":"thị trường lao động"},{"en":"labor costs","vi":"chi phí nhân công"},{"en":"go into labor","vi":"bắt đầu chuyển dạ"}],"wordFamily":["laborer (n.)","laborious (adj.)","laboriously (adv.)"],"synonyms":["work","toil"],"antonyms":[],"tipVi":"labor là cách viết theo tiếng Mỹ, tiếng Anh-Anh viết là labour.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_negotiate', 'en-b2-46', 'negotiate', '/nɪˈɡoʊʃieɪt/', 'B2', 'đàm phán; thương lượng để đạt thỏa thuận; vượt qua suôn sẻ; đi qua một đoạn đường khó', 'v.', 'negotiation (n.), negotiator (n.), negotiable (adj.)', NULL, 'Đàm phán với ai dùng with; cũng có thể đi trực tiếp với agreement.', 'We negotiated a lower price for the secondhand sofa.', NULL, 'Chúng tôi đã thương lượng được mức giá rẻ hơn cho chiếc ghế sofa cũ.', '{"wordId":"negotiate","ukIpa":"/nɪˈɡəʊʃieɪt/","usIpa":"/nɪˈɡoʊʃieɪt/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"Discuss terms with others to reach an agreement.","vi":"đàm phán; thương lượng để đạt thỏa thuận"},{"pos":"v.","en":"Successfully move past an obstacle or along a difficult route.","vi":"vượt qua suôn sẻ; đi qua một đoạn đường khó"}],"examples":[{"en":"We negotiated a lower price for the secondhand sofa.","vi":"Chúng tôi đã thương lượng được mức giá rẻ hơn cho chiếc ghế sofa cũ.","audioKind":"ex"},{"en":"Governments must negotiate fair trade agreements that protect workers while encouraging international investment and economic growth.","vi":"Các chính phủ phải đàm phán các thỏa thuận thương mại công bằng nhằm bảo vệ người lao động đồng thời thúc đẩy đầu tư quốc tế và tăng trưởng kinh tế.","audioKind":"ex2"}],"collocations":[{"en":"negotiate an agreement","vi":"thương lượng đạt thỏa thuận"},{"en":"negotiate with employers","vi":"đàm phán với chủ lao động"},{"en":"negotiate a bend","vi":"vượt qua khúc cua"}],"wordFamily":["negotiation (n.)","negotiator (n.)","negotiable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Đàm phán với ai dùng with; cũng có thể đi trực tiếp với agreement.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_banker', 'en-b2-46', 'banker', '/ˈbæŋkər/', 'B2', 'nhà ngân hàng; nhân sự cấp cao ngành ngân hàng', 'n.', 'bank (n.), bank (v.), banking (n.)', NULL, 'Thường dùng để chỉ nhà ngân hàng hoặc nhân sự cấp cao, không dùng để chỉ giao dịch viên ngân hàng nói chung.', 'The banker explained our loan options over coffee.', NULL, 'Viên quản lý ngân hàng đã giải thích các gói cho vay của chúng tôi trong lúc uống cà phê.', '{"wordId":"banker","ukIpa":"/ˈbæŋkə/","usIpa":"/ˈbæŋkər/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"someone who owns a bank or holds a senior banking position","vi":"nhà ngân hàng; nhân sự cấp cao ngành ngân hàng"}],"examples":[{"en":"The banker explained our loan options over coffee.","vi":"Viên quản lý ngân hàng đã giải thích các gói cho vay của chúng tôi trong lúc uống cà phê.","audioKind":"ex"},{"en":"Bankers play an important role in assessing financial risks before approving loans to small businesses.","vi":"Các chuyên gia ngân hàng đóng vai trò quan trọng trong việc đánh giá rủi ro tài chính trước khi phê duyệt các khoản vay cho doanh nghiệp nhỏ.","audioKind":"ex2"}],"collocations":[{"en":"investment banker","vi":"nhà đầu tư ngân hàng"},{"en":"central banker","vi":"quan chức ngân hàng trung ương"},{"en":"senior banker","vi":"nhân sự cấp cao ngân hàng"}],"wordFamily":["bank (n.)","bank (v.)","banking (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng để chỉ nhà ngân hàng hoặc nhân sự cấp cao, không dùng để chỉ giao dịch viên ngân hàng nói chung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_interpreter', 'en-b2-46', 'interpreter', '/ɪnˈtɝːprɪtər/', 'B2', 'thông dịch viên, phiên dịch viên; chương trình thông dịch', 'n.', 'interpret (v.), interpretation (n.)', NULL, 'Interpreter thường làm phiên dịch nói (khẩu dịch); translator thường làm dịch viết (bút dịch).', 'An interpreter helped my grandmother speak to the doctor.', NULL, 'Một thông dịch viên đã giúp bà tôi trò chuyện với bác sĩ.', '{"wordId":"interpreter","ukIpa":"/ɪnˈtɜːprɪtə/","usIpa":"/ɪnˈtɝːprɪtər/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"Someone who translates spoken or signed communication between languages.","vi":"thông dịch viên, phiên dịch viên"},{"pos":"n.","en":"A program that reads and executes code directly.","vi":"chương trình thông dịch"}],"examples":[{"en":"An interpreter helped my grandmother speak to the doctor.","vi":"Một thông dịch viên đã giúp bà tôi trò chuyện với bác sĩ.","audioKind":"ex"},{"en":"Providing a qualified interpreter in hospitals can improve communication and reduce misunderstandings about treatment options.","vi":"Việc bố trí một phiên dịch viên đủ trình độ trong các bệnh viện có thể cải thiện việc giao tiếp và giảm bớt những hiểu lầm về các phương án điều trị.","audioKind":"ex2"}],"collocations":[{"en":"a qualified interpreter","vi":"một phiên dịch viên đủ trình độ"},{"en":"a conference interpreter","vi":"một thông dịch viên hội nghị"},{"en":"a sign language interpreter","vi":"một phiên dịch viên ngôn ngữ ký hiệu"}],"wordFamily":["interpret (v.)","interpretation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Interpreter thường làm phiên dịch nói (khẩu dịch); translator thường làm dịch viết (bút dịch).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_draft', 'en-b2-46', 'draft', '/dræft/', 'B2', 'bản thảo; bản nháp; bản phác thảo; lênร่าง; soạn thảo; phác thảo', 'n.', 'redraft (v.), drafter (n.)', NULL, 'Nghĩa "bản thảo" được dùng chung trong cả tiếng Anh-Anh và tiếng Anh-Mỹ; gió lùa tiếng Anh-Anh dùng draught.', 'I saved the first draft of my letter.', NULL, 'Tôi đã lưu lại bản nháp đầu tiên của bức thư mình viết.', '{"wordId":"draft","ukIpa":"/drɑːft/","usIpa":"/dræft/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"an early version of writing that may be changed","vi":"bản thảo; bản nháp; bản phác thảo"},{"pos":"v.","en":"to write an early version of a document","vi":"lênร่าง; soạn thảo; phác thảo"}],"examples":[{"en":"I saved the first draft of my letter.","vi":"Tôi đã lưu lại bản nháp đầu tiên của bức thư mình viết.","audioKind":"ex"},{"en":"Governments should publish draft legislation early so that citizens can comment before final decisions are made.","vi":"Chính phủ nên công bố các dự luật từ sớm để công dân có thể đưa ra ý kiến trước khi quyết định cuối cùng được thông qua.","audioKind":"ex2"}],"collocations":[{"en":"first draft","vi":"bản thảo đầu tiên"},{"en":"final draft","vi":"bản thảo cuối cùng"},{"en":"draft a proposal","vi":"soạn thảo một bản đề xuất"},{"en":"draft legislation","vi":"dự luật"}],"wordFamily":["redraft (v.)","drafter (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa \"bản thảo\" được dùng chung trong cả tiếng Anh-Anh và tiếng Anh-Mỹ; gió lùa tiếng Anh-Anh dùng draught.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_supervisor', 'en-b2-46', 'supervisor', '/ˈsuːpərvaɪzər/', 'B2', 'người giám sát; cấp trên; quản lý; giảng viên hướng dẫn nghiên cứu; người hướng dẫn học thuật', 'n.', 'supervise (v.), supervision (n.), supervisory (adj.)', NULL, 'Trong môi trường làm việc chỉ người quản lý; ở các trường đại học Anh quốc thường chỉ giảng viên hướng dẫn nghiên cứu.', 'My supervisor showed me how to use the equipment.', NULL, 'Người quản lý của tôi đã chỉ cho tôi cách sử dụng thiết bị này.', '{"wordId":"supervisor","ukIpa":"/ˈsuːpəvaɪzə/","usIpa":"/ˈsuːpərvaɪzər/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"A person who oversees other people''s work or activities.","vi":"người giám sát; cấp trên; quản lý"},{"pos":"n.","en":"An academic who guides a student''s research.","vi":"giảng viên hướng dẫn nghiên cứu; người hướng dẫn học thuật"}],"examples":[{"en":"My supervisor showed me how to use the equipment.","vi":"Người quản lý của tôi đã chỉ cho tôi cách sử dụng thiết bị này.","audioKind":"ex"},{"en":"A supportive supervisor can help new employees develop confidence and adapt to unfamiliar workplace expectations.","vi":"Một người quản lý tâm lý hỗ trợ có thể giúp nhân viên mới xây dựng sự tự tin và thích nghi với những yêu cầu công việc còn xa lạ.","audioKind":"ex2"}],"collocations":[{"en":"immediate supervisor","vi":"cấp trên trực tiếp"},{"en":"research supervisor","vi":"giảng viên hướng dẫn nghiên cứu"},{"en":"shift supervisor","vi":"quản lý ca trực"}],"wordFamily":["supervise (v.)","supervision (n.)","supervisory (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong môi trường làm việc chỉ người quản lý; ở các trường đại học Anh quốc thường chỉ giảng viên hướng dẫn nghiên cứu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_commute', 'en-b2-46', 'commute', '/kəˈmjuːt/', 'B2', 'đi lại (giữa nhà và nơi làm việc); quãng đường đi làm; giảm nhẹ hình phạt; ân xá', 'v.', 'commuter (n.), commuting (n.)', NULL, 'Cụm từ commute to work dùng để chỉ việc đi làm; còn commute a sentence dùng để chỉ việc giảm hình phạt.', 'I commute by train and usually read a book.', NULL, 'Tôi đi làm bằng tàu hỏa và thường đọc sách trên đường.', '{"wordId":"commute","ukIpa":"/kəˈmjuːt/","usIpa":"/kəˈmjuːt/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"To travel regularly between home and work.","vi":"đi lại (giữa nhà và nơi làm việc)"},{"pos":"n.","en":"A regular journey between home and work.","vi":"quãng đường đi làm"},{"pos":"v.","en":"To replace a legal punishment with a less severe one.","vi":"giảm nhẹ hình phạt; ân xá"}],"examples":[{"en":"I commute by train and usually read a book.","vi":"Tôi đi làm bằng tàu hỏa và thường đọc sách trên đường.","audioKind":"ex"},{"en":"Employees who commute long distances may experience greater stress and have less time for family activities.","vi":"Nhân viên phải di chuyển quãng đường dài để đi làm có thể chịu áp lực lớn hơn và có ít thời gian hơn cho các hoạt động gia đình.","audioKind":"ex2"}],"collocations":[{"en":"commute to work","vi":"đi làm"},{"en":"daily commute","vi":"chuyến đi làm hằng ngày"},{"en":"commute by train","vi":"đi làm bằng tàu hỏa"},{"en":"commute a sentence","vi":"giảm án"}],"wordFamily":["commuter (n.)","commuting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ commute to work dùng để chỉ việc đi làm; còn commute a sentence dùng để chỉ việc giảm hình phạt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_seek', 'en-b2-46', 'seek', '/siːk/', 'B2', 'tìm kiếm; mưu cầu; cố gắng; tìm cách', 'v.', 'seeker (n.)', 'Đồng nghĩa: look for, search for', 'Dạng quá khứ và phân từ hai đều là sought; theo sau là tân ngữ trực tiếp.', 'You should seek advice before buying a used car.', NULL, 'Bạn nên tham khảo ý kiến trước khi mua một chiếc ô tô cũ.', '{"wordId":"seek","ukIpa":"/siːk/","usIpa":"/siːk/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"To try to find or obtain something.","vi":"tìm kiếm; mưu cầu"},{"pos":"v.","en":"To try to do or achieve something.","vi":"cố gắng; tìm cách"}],"examples":[{"en":"You should seek advice before buying a used car.","vi":"Bạn nên tham khảo ý kiến trước khi mua một chiếc ô tô cũ.","audioKind":"ex"},{"en":"Many graduates seek employment abroad to gain professional experience and develop their language skills.","vi":"Nhiều sinh viên mới ra trường tìm kiếm việc làm ở nước ngoài để tích lũy kinh nghiệm chuyên môn và phát triển kỹ năng ngôn ngữ.","audioKind":"ex2"}],"collocations":[{"en":"seek advice","vi":"xin lời khuyên"},{"en":"seek employment","vi":"tìm việc làm"},{"en":"seek to improve","vi":"tìm cách cải thiện"},{"en":"seek help","vi":"tìm kiếm sự giúp đỡ"}],"wordFamily":["seeker (n.)"],"synonyms":["look for","search for"],"antonyms":[],"tipVi":"Dạng quá khứ và phân từ hai đều là sought; theo sau là tân ngữ trực tiếp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_effectively', 'en-b2-46', 'effectively', '/ɪˈfektɪvli/', 'B2', 'một cách hiệu quả; có hiệu quả; thực ra; trên thực tế; trên phương diện thực tế', 'adv.', 'effective (adj.), effectiveness (n.), ineffective (adj.)', 'Trái nghĩa: ineffectively', 'effectively nhấn mạnh vào hiệu quả đạt được; trong khi efficiently nhấn mạnh vào hiệu suất làm việc.', 'This simple brush cleans muddy shoes surprisingly effectively.', NULL, 'Chiếc bàn chải đơn giản này làm sạch giày bám bùn một cách hiệu quả đến bất ngờ.', '{"wordId":"effectively","ukIpa":"/ɪˈfektɪvli/","usIpa":"/ɪˈfektɪvli/","cefr":"B2","topic":"work","senses":[{"pos":"adv.","en":"in a way that achieves the intended result","vi":"một cách hiệu quả; có hiệu quả"},{"pos":"adv.","en":"in practice, although not officially or in every detail","vi":"thực ra; trên thực tế; trên phương diện thực tế"}],"examples":[{"en":"This simple brush cleans muddy shoes surprisingly effectively.","vi":"Chiếc bàn chải đơn giản này làm sạch giày bám bùn một cách hiệu quả đến bất ngờ.","audioKind":"ex"},{"en":"Schools can reduce waste effectively by encouraging students to reuse materials during classroom activities.","vi":"Các trường học có thể giảm thiểu rác thải một cách hiệu quả bằng cách khuyến khích học sinh tái sử dụng vật liệu trong các hoạt động trên lớp.","audioKind":"ex2"}],"collocations":[{"en":"communicate effectively","vi":"giao tiếp hiệu quả"},{"en":"work effectively","vi":"hoạt động hiệu quả"},{"en":"effectively impossible","vi":"trên thực tế là bất khả thi"}],"wordFamily":["effective (adj.)","effectiveness (n.)","ineffective (adj.)"],"synonyms":[],"antonyms":["ineffectively"],"tipVi":"effectively nhấn mạnh vào hiệu quả đạt được; trong khi efficiently nhấn mạnh vào hiệu suất làm việc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_jobless', 'en-b2-46', 'jobless', '/ˈdʒɑːbləs/', 'B2', 'thất nghiệp; không có việc làm', 'adj.', 'job (n.), joblessness (n.)', 'Đồng nghĩa: unemployed, out of work · Trái nghĩa: employed', 'the jobless dùng để chỉ cộng đồng người thất nghiệp nói chung, khi làm chủ ngữ đi với động từ số nhiều.', 'She was jobless for months after the factory closed.', NULL, 'Cô ấy đã thất nghiệp nhiều tháng trời sau khi nhà máy đóng cửa.', '{"wordId":"jobless","ukIpa":"/ˈdʒɒbləs/","usIpa":"/ˈdʒɑːbləs/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"Without paid employment, especially when wanting to work.","vi":"thất nghiệp; không có việc làm"}],"examples":[{"en":"She was jobless for months after the factory closed.","vi":"Cô ấy đã thất nghiệp nhiều tháng trời sau khi nhà máy đóng cửa.","audioKind":"ex"},{"en":"Governments should offer affordable retraining programmes to help jobless workers adapt to changes in the labour market.","vi":"Chính phủ nên cung cấp các chương trình đào tạo nghề với chi phí hợp lý để giúp người lao động thất nghiệp thích nghi với những biến động của thị trường lao động.","audioKind":"ex2"}],"collocations":[{"en":"jobless workers","vi":"công nhân thất nghiệp"},{"en":"the jobless","vi":"nhóm người thất nghiệp"},{"en":"jobless rate","vi":"tỷ lệ thất nghiệp"}],"wordFamily":["job (n.)","joblessness (n.)"],"synonyms":["unemployed","out of work"],"antonyms":["employed"],"tipVi":"the jobless dùng để chỉ cộng đồng người thất nghiệp nói chung, khi làm chủ ngữ đi với động từ số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_idle', 'en-b2-46', 'idle', '/ˈaɪdəl/', 'B2', 'nhàn rỗi; không hoạt động; bỏ không; lười biếng; vô công rỗi nghề; chạy không tải', 'adj.', 'idleness (n.), idly (adv.)', 'Đồng nghĩa: inactive · Trái nghĩa: active, busy', 'Idle có thể chỉ người rảnh rỗi, thiết bị bỏ không, hoặc động cơ chạy không tải.', 'The sewing machine has sat idle since last winter.', NULL, 'Chiếc máy khâu này đã nằm bất động từ mùa đông năm ngoái.', '{"wordId":"idle","ukIpa":"/ˈaɪdəl/","usIpa":"/ˈaɪdəl/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"Not being used or doing any work.","vi":"nhàn rỗi; không hoạt động; bỏ không"},{"pos":"adj.","en":"Avoiding work or spending time doing nothing.","vi":"lười biếng; vô công rỗi nghề"},{"pos":"v.","en":"For an engine to run while the vehicle remains still.","vi":"chạy không tải"}],"examples":[{"en":"The sewing machine has sat idle since last winter.","vi":"Chiếc máy khâu này đã nằm bất động từ mùa đông năm ngoái.","audioKind":"ex"},{"en":"Leaving delivery vehicles idling outside schools contributes to air pollution and exposes children to unnecessary health risks.","vi":"Việc để xe giao hàng nổ máy không tải bên ngoài trường học góp phần gây ô nhiễm không khí và đẩy trẻ em vào những rủi ro sức khỏe không đáng có.","audioKind":"ex2"}],"collocations":[{"en":"stand idle","vi":"bỏ không; nằm đắp chiếu"},{"en":"idle machinery","vi":"máy móc bỏ không"},{"en":"an idling engine","vi":"động cơ đang nổ không tải"},{"en":"idle gossip","vi":"lời bàn tán vô bổ"}],"wordFamily":["idleness (n.)","idly (adv.)"],"synonyms":["inactive"],"antonyms":["active","busy"],"tipVi":"Idle có thể chỉ người rảnh rỗi, thiết bị bỏ không, hoặc động cơ chạy không tải.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_appoint', 'en-b2-46', 'appoint', '/əˈpɔɪnt/', 'B2', 'bổ nhiệm; chỉ định; quy định; ấn định', 'v.', 'appointment (n.), appointee (n.), appointed (adj.)', NULL, 'Bổ nhiệm ai đó dùng appoint sb as hoặc appoint sb to vị trí.', 'The club appointed my sister as its new captain.', NULL, 'Câu lạc bộ đã bổ nhiệm chị tôi làm đội trưởng mới.', '{"wordId":"appoint","ukIpa":"/əˈpɔɪnt/","usIpa":"/əˈpɔɪnt/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"to officially choose someone for a job or responsibility","vi":"bổ nhiệm; chỉ định"},{"pos":"v.","en":"to officially decide a time or place for something","vi":"quy định; ấn định"}],"examples":[{"en":"The club appointed my sister as its new captain.","vi":"Câu lạc bộ đã bổ nhiệm chị tôi làm đội trưởng mới.","audioKind":"ex"},{"en":"Schools should appoint qualified counsellors to help students manage stress and make informed career choices.","vi":"Các trường học nên tuyển dụng các cố vấn có chuyên môn để giúp học sinh quản lý căng thẳng và đưa ra những lựa chọn nghề nghiệp sáng suốt.","audioKind":"ex2"}],"collocations":[{"en":"appoint someone as","vi":"bổ nhiệm ai làm"},{"en":"appoint a committee","vi":"chỉ định một ủy ban"},{"en":"at the appointed time","vi":"vào thời gian đã định"}],"wordFamily":["appointment (n.)","appointee (n.)","appointed (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Bổ nhiệm ai đó dùng appoint sb as hoặc appoint sb to vị trí.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cooperating', 'en-b2-46', 'cooperating', '/koʊˈɑːpəreɪtɪŋ/', 'B2', 'hợp tác; phối hợp', 'v.', 'cooperate (v.), cooperation (n.), cooperative (adj.), cooperatively (adv.)', 'Đồng nghĩa: collaborating', 'Là dạng -ing của cooperate; đi với ai đó thì dùng với with.', 'The neighbours are cooperating to repair the shared fence.', NULL, 'Những người hàng xóm đang cùng nhau sửa chữa hàng rào chung.', '{"wordId":"cooperating","ukIpa":"/kəʊˈɒpəreɪtɪŋ/","usIpa":"/koʊˈɑːpəreɪtɪŋ/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"working together or helping by doing what is requested","vi":"hợp tác; phối hợp"}],"examples":[{"en":"The neighbours are cooperating to repair the shared fence.","vi":"Những người hàng xóm đang cùng nhau sửa chữa hàng rào chung.","audioKind":"ex"},{"en":"By cooperating on clean energy research, countries can reduce costs and accelerate the development of sustainable technologies.","vi":"Bằng cách hợp tác trong nghiên cứu năng lượng sạch, các quốc gia có thể cắt giảm chi phí và đẩy nhanh sự phát triển của các công nghệ bền vững.","audioKind":"ex2"}],"collocations":[{"en":"cooperating with colleagues","vi":"hợp tác với đồng nghiệp"},{"en":"cooperating on research","vi":"hợp tác nghiên cứu"},{"en":"cooperating closely","vi":"hợp tác chặt chẽ"}],"wordFamily":["cooperate (v.)","cooperation (n.)","cooperative (adj.)","cooperatively (adv.)"],"synonyms":["collaborating"],"antonyms":[],"tipVi":"Là dạng -ing của cooperate; đi với ai đó thì dùng với with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_self-employed', 'en-b2-46', 'self-employed', '/ˌself ɪmˈplɔɪd/', 'B2', 'tự kinh doanh; tự làm chủ', 'adj.', 'self-employment (n.), employ (v.), employee (n.), employer (n.)', NULL, 'Chỉ việc làm chủ bản thân, không có nghĩa là thất nghiệp; hãy chú ý giữ nguyên dấu gạch nối.', 'My aunt is a self-employed electrician with her own van.', NULL, 'Dì tôi là một thợ điện tự do có xe tải riêng.', '{"wordId":"self-employed","ukIpa":"/ˌself ɪmˈplɔɪd/","usIpa":"/ˌself ɪmˈplɔɪd/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"Working for yourself rather than being employed by an organisation.","vi":"tự kinh doanh; tự làm chủ"}],"examples":[{"en":"My aunt is a self-employed electrician with her own van.","vi":"Dì tôi là một thợ điện tự do có xe tải riêng.","audioKind":"ex"},{"en":"Self-employed workers often enjoy flexible schedules but may lack paid holidays and a stable monthly income.","vi":"Người lao động tự do thường tận hưởng lịch trình linh hoạt nhưng có thể thiếu kỳ nghỉ có lương và thu nhập hàng tháng ổn định.","audioKind":"ex2"}],"collocations":[{"en":"self-employed workers","vi":"người lao động tự do"},{"en":"become self-employed","vi":"bắt đầu tự kinh doanh"},{"en":"self-employed consultant","vi":"cố vấn độc lập"}],"wordFamily":["self-employment (n.)","employ (v.)","employee (n.)","employer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ việc làm chủ bản thân, không có nghĩa là thất nghiệp; hãy chú ý giữ nguyên dấu gạch nối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_administrative', 'en-b2-46', 'administrative', '/ədˈmɪnəstreɪtɪv/', 'B2', 'thuộc về hành chính; quản lý', 'adj.', 'administration (n.), administrator (n.), administer (v.), administratively (adv.)', NULL, 'Chỉ công tác quản lý vận hành của tổ chức, không đồng nghĩa với cơ quan chính phủ.', 'My sister handles administrative tasks at a local clinic.', NULL, 'Chị gái tôi đảm nhận các công việc hành chính tại một phòng khám địa phương.', '{"wordId":"administrative","ukIpa":"/ədˈmɪnɪstrətɪv/","usIpa":"/ədˈmɪnəstreɪtɪv/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"Related to organising and running an institution or business.","vi":"thuộc về hành chính; quản lý"}],"examples":[{"en":"My sister handles administrative tasks at a local clinic.","vi":"Chị gái tôi đảm nhận các công việc hành chính tại một phòng khám địa phương.","audioKind":"ex"},{"en":"Reducing administrative costs could allow schools to spend more money on teaching materials and student support.","vi":"Việc cắt giảm chi phí hành chính có thể tạo điều kiện cho các trường học phân bổ nhiều nguồn lực hơn cho tài liệu giảng dạy và dịch vụ hỗ trợ học sinh.","audioKind":"ex2"}],"collocations":[{"en":"administrative staff","vi":"nhân viên hành chính"},{"en":"administrative costs","vi":"chi phí hành chính"},{"en":"administrative tasks","vi":"công việc hành chính"}],"wordFamily":["administration (n.)","administrator (n.)","administer (v.)","administratively (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ công tác quản lý vận hành của tổ chức, không đồng nghĩa với cơ quan chính phủ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_candidate', 'en-b2-46', 'candidate', '/ˈkændɪdət/', 'B2', 'ứng cử viên; người xin việc; thí sinh', 'n.', 'candidacy (n.)', 'Đồng nghĩa: applicant, contender', 'Candidate for thường đi theo sau bởi vị trí công việc hoặc chức vụ đang ứng tuyển.', 'Each candidate waited outside the office before their interview.', NULL, 'Mỗi ứng viên đều chờ đợi bên ngoài văn phòng trước khi bước vào phỏng vấn.', '{"wordId":"candidate","ukIpa":"/ˈkændɪdət/","usIpa":"/ˈkændɪdət/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"Someone competing for a job or an elected position.","vi":"ứng cử viên; người xin việc"},{"pos":"n.","en":"Someone taking an examination.","vi":"thí sinh"}],"examples":[{"en":"Each candidate waited outside the office before their interview.","vi":"Mỗi ứng viên đều chờ đợi bên ngoài văn phòng trước khi bước vào phỏng vấn.","audioKind":"ex"},{"en":"Employers should assess each candidate fairly rather than rely on assumptions about their educational or cultural background.","vi":"Nhà tuyển dụng nên đánh giá công bằng từng ứng viên thay vì dựa vào những phỏng đoán về nền tảng giáo dục hay văn hóa của họ.","audioKind":"ex2"}],"collocations":[{"en":"candidate for a position","vi":"ứng viên cho một vị trí"},{"en":"suitable candidate","vi":"ứng viên sáng giá"},{"en":"election candidate","vi":"ứng cử viên tranh cử"},{"en":"exam candidate","vi":"thí sinh dự thi"}],"wordFamily":["candidacy (n.)"],"synonyms":["applicant","contender"],"antonyms":[],"tipVi":"Candidate for thường đi theo sau bởi vị trí công việc hoặc chức vụ đang ứng tuyển.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_housekeeper', 'en-b2-46', 'housekeeper', '/ˈhaʊskiːpər/', 'B2', 'người quản gia; nhân viên dọn phòng; người giúp việc gia đình', 'n.', 'housekeeping (n.)', NULL, 'Chỉ người được thuê để dọn dẹp nhà cửa hoặc phòng khách sạn, không phân biệt giới tính.', 'The housekeeper left fresh towels beside the bathroom sink.', NULL, 'Nhân viên dọn phòng đã để những chiếc khăn tắm sạch bên cạnh bồn rửa trong phòng tắm.', '{"wordId":"housekeeper","ukIpa":"/ˈhaʊskiːpə/","usIpa":"/ˈhaʊskiːpər/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"Someone employed to clean and look after homes or hotel rooms.","vi":"người quản gia; nhân viên dọn phòng; người giúp việc gia đình"}],"examples":[{"en":"The housekeeper left fresh towels beside the bathroom sink.","vi":"Nhân viên dọn phòng đã để những chiếc khăn tắm sạch bên cạnh bồn rửa trong phòng tắm.","audioKind":"ex"},{"en":"Hotels should provide housekeepers with suitable equipment and sufficient time to clean each room safely.","vi":"Các khách sạn nên cung cấp cho nhân viên dọn phòng các thiết bị phù hợp và đủ thời gian để dọn dẹp từng phòng một cách an toàn.","audioKind":"ex2"}],"collocations":[{"en":"hotel housekeeper","vi":"nhân viên dọn phòng khách sạn"},{"en":"live-in housekeeper","vi":"người giúp việc ở lại nhà"},{"en":"hire a housekeeper","vi":"thuê người quản gia"}],"wordFamily":["housekeeping (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ người được thuê để dọn dẹp nhà cửa hoặc phòng khách sạn, không phân biệt giới tính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_found', 'en-b2-46', 'found', '/faʊnd/', 'B2', 'thành lập; sáng lập; dạng quá khứ và phân từ hai của find', 'v.', 'founder (n.), foundation (n.), founding (adj.)', 'Đồng nghĩa: establish, set up', 'Dạng quá khứ của "thành lập" là founded; dạng nguyên thể của "tìm thấy" là find.', 'My aunt founded a small charity last winter.', NULL, 'Dì tôi đã thành lập một quỹ từ thiện nhỏ vào mùa đông năm ngoái.', '{"wordId":"found","ukIpa":"/faʊnd/","usIpa":"/faʊnd/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"to establish an organization, institution, or settlement","vi":"thành lập; sáng lập"},{"pos":"v.","en":"past tense and past participle of find","vi":"dạng quá khứ và phân từ hai của find"}],"examples":[{"en":"My aunt founded a small charity last winter.","vi":"Dì tôi đã thành lập một quỹ từ thiện nhỏ vào mùa đông năm ngoái.","audioKind":"ex"},{"en":"Graduates who found new businesses can create employment opportunities and introduce innovative services to local communities.","vi":"Những sinh viên tốt nghiệp khởi nghiệp kinh doanh có thể tạo ra cơ hội việc làm và mang lại các dịch vụ đổi mới cho cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"found a company","vi":"thành lập công ty"},{"en":"found a school","vi":"thành lập trường học"},{"en":"found a charity","vi":"thành lập quỹ từ thiện"}],"wordFamily":["founder (n.)","foundation (n.)","founding (adj.)"],"synonyms":["establish","set up"],"antonyms":[],"tipVi":"Dạng quá khứ của \"thành lập\" là founded; dạng nguyên thể của \"tìm thấy\" là find.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_senior', 'en-b2-46', 'senior', '/ˈsiːniər/', 'B2', 'cấp cao; thâm niên; lớn tuổi hơn; học sinh năm cuối cấp; người cao tuổi', 'adj.', 'seniority (n.)', 'Trái nghĩa: junior', 'Khi so sánh cấp bậc dùng senior to, tuyệt đối không dùng senior than.', 'A senior nurse showed me how to change the bandage.', NULL, 'Một y tá có thâm niên đã chỉ cho tôi cách thay băng vết thương.', '{"wordId":"senior","ukIpa":"/ˈsiːniə/","usIpa":"/ˈsiːniər/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"Having a higher rank or more experience within an organisation.","vi":"cấp cao; thâm niên"},{"pos":"adj.","en":"Older than someone else, or relating to older people.","vi":"lớn tuổi hơn"},{"pos":"n.","en":"A final-year school or college student, or an older adult.","vi":"học sinh năm cuối cấp; người cao tuổi"}],"examples":[{"en":"A senior nurse showed me how to change the bandage.","vi":"Một y tá có thâm niên đã chỉ cho tôi cách thay băng vết thương.","audioKind":"ex"},{"en":"Senior managers should consult employees before introducing policies that significantly affect working conditions across the organisation.","vi":"Các nhà quản lý cấp cao nên tham khảo ý kiến nhân viên trước khi ban hành các chính sách ảnh hưởng lớn đến điều kiện làm việc trong toàn bộ tổ chức.","audioKind":"ex2"}],"collocations":[{"en":"senior management","vi":"ban lãnh đạo cấp cao"},{"en":"a senior position","vi":"một vị trí cấp cao"},{"en":"senior citizen","vi":"công dân cao tuổi"},{"en":"senior to someone","vi":"có chức vụ cao hơn ai đó"}],"wordFamily":["seniority (n.)"],"synonyms":[],"antonyms":["junior"],"tipVi":"Khi so sánh cấp bậc dùng senior to, tuyệt đối không dùng senior than.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_specialised', 'en-b2-46', 'specialised', '/ˈspeʃəlaɪzd/', 'B2', 'chuyên dụng; chuyên khoa; chuyên môn hóa', 'adj.', 'specialise (v.), specialisation (n.), specialist (n.), special (adj.)', 'Trái nghĩa: general', 'Trong tiếng Anh-Anh thường dùng specialised, trong khi tiếng Anh-Mỹ thường dùng dạng specialized.', 'The mechanic used specialised tools to repair my bicycle.', NULL, 'Thợ máy đã dùng các dụng cụ chuyên dụng để sửa chiếc xe đạp của tôi.', '{"wordId":"specialised","ukIpa":"/ˈspeʃəlaɪzd/","usIpa":"/ˈspeʃəlaɪzd/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"Designed for a particular purpose or requiring specific expert knowledge.","vi":"chuyên dụng; chuyên khoa; chuyên môn hóa"}],"examples":[{"en":"The mechanic used specialised tools to repair my bicycle.","vi":"Thợ máy đã dùng các dụng cụ chuyên dụng để sửa chiếc xe đạp của tôi.","audioKind":"ex"},{"en":"Hospitals need specialised equipment and trained staff to provide effective treatment for patients with complex conditions.","vi":"Các bệnh viện cần có thiết bị chuyên dụng và nhân viên được đào tạo bài bản để cung cấp quá trình điều trị hiệu quả cho các bệnh nhân có tình trạng bệnh phức tạp.","audioKind":"ex2"}],"collocations":[{"en":"specialised equipment","vi":"trang thiết bị chuyên dụng"},{"en":"specialised knowledge","vi":"kiến thức chuyên môn"},{"en":"specialised training","vi":"đào tạo chuyên sâu"},{"en":"highly specialised","vi":"có tính chuyên môn hóa cao"}],"wordFamily":["specialise (v.)","specialisation (n.)","specialist (n.)","special (adj.)"],"synonyms":[],"antonyms":["general"],"tipVi":"Trong tiếng Anh-Anh thường dùng specialised, trong khi tiếng Anh-Mỹ thường dùng dạng specialized.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_freelance', 'en-b2-46', 'freelance', '/ˈfriːlæns/', 'B2', 'làm việc tự do; thuộc nghề tự do; theo hình thức tự do; làm nghề tự do', 'adj.', 'freelancer (n.)', 'Đồng nghĩa: self-employed', 'Trong cụm "work freelance", "freelance" đóng vai trò là trạng từ; "freelancer" là danh từ chỉ người làm nghề tự do.', 'My sister is a freelance designer who works from home.', NULL, 'Chị tôi là một nhà thiết kế tự do làm việc tại nhà.', '{"wordId":"freelance","ukIpa":"/ˈfriːlɑːns/","usIpa":"/ˈfriːlæns/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"Working independently for different clients rather than one employer","vi":"làm việc tự do; thuộc nghề tự do"},{"pos":"adv.","en":"Independently, for different clients rather than one employer","vi":"theo hình thức tự do"},{"pos":"v.","en":"To work independently, offering services to different clients","vi":"làm nghề tự do"}],"examples":[{"en":"My sister is a freelance designer who works from home.","vi":"Chị tôi là một nhà thiết kế tự do làm việc tại nhà.","audioKind":"ex"},{"en":"Freelance work offers flexibility, but workers may struggle to maintain a stable income without regular contracts.","vi":"Làm nghề tự do mang lại sự linh hoạt, nhưng người lao động có thể chật vật duy trì thu nhập ổn định nếu không có hợp đồng thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"freelance writer","vi":"nhà văn tự do"},{"en":"work freelance","vi":"làm việc tự do"},{"en":"freelance work","vi":"công việc tự do"}],"wordFamily":["freelancer (n.)"],"synonyms":["self-employed"],"antonyms":[],"tipVi":"Trong cụm \"work freelance\", \"freelance\" đóng vai trò là trạng từ; \"freelancer\" là danh từ chỉ người làm nghề tự do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_46_1', 'en-b2-46', 'Cách dùng “supervisor” (n.) — người giám sát; cấp trên; quản lý', 'immediate supervisor  ·  research supervisor  ·  shift supervisor', 'Trong môi trường làm việc chỉ người quản lý; ở các trường đại học Anh quốc thường chỉ giảng viên hướng dẫn nghiên cứu.', 'Họ từ (Word Family): supervise (v.), supervision (n.), supervisory (adj.)', '[{"hanzi":"My supervisor showed me how to use the equipment.","pinyin":"","meaning":"Người quản lý của tôi đã chỉ cho tôi cách sử dụng thiết bị này."},{"hanzi":"A supportive supervisor can help new employees develop confidence and adapt to unfamiliar workplace expectations.","pinyin":"","meaning":"Một người quản lý tâm lý hỗ trợ có thể giúp nhân viên mới xây dựng sự tự tin và thích nghi với những yêu cầu công việc còn xa lạ."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_46_2', 'en-b2-46', 'Cách dùng “freelance” (adj.) — làm việc tự do; thuộc nghề tự do', 'freelance writer  ·  work freelance  ·  freelance work', 'Trong cụm "work freelance", "freelance" đóng vai trò là trạng từ; "freelancer" là danh từ chỉ người làm nghề tự do.', 'Họ từ (Word Family): freelancer (n.) | Đồng nghĩa: self-employed', '[{"hanzi":"My sister is a freelance designer who works from home.","pinyin":"","meaning":"Chị tôi là một nhà thiết kế tự do làm việc tại nhà."},{"hanzi":"Freelance work offers flexibility, but workers may struggle to maintain a stable income without regular contracts.","pinyin":"","meaning":"Làm nghề tự do mang lại sự linh hoạt, nhưng người lao động có thể chật vật duy trì thu nhập ổn định nếu không có hợp đồng thường xuyên."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_46_3', 'en-b2-46', 'Cách dùng “sack” (n.) — bao tải lớn; túi vải thô', 'a sack of potatoes  ·  get the sack  ·  sack someone for misconduct', 'Nghĩa sa thải (sack) thường dùng trong văn phong thân mật hoặc tiếng Anh - Anh; từ trang trọng hơn là dismiss.', 'Họ từ (Word Family): sacking (n.) | Đồng nghĩa: bag, dismiss, fire', '[{"hanzi":"We carried a heavy sack of potatoes into the kitchen.","pinyin":"","meaning":"Chúng tôi khiêng một bao tải khoai tây nặng vào trong bếp."},{"hanzi":"Employers should not sack workers without explaining the reasons and allowing them to challenge the decision.","pinyin":"","meaning":"Người sử dụng lao động không nên sa thải nhân công mà không giải thích rõ lý do cũng như không cho họ cơ hội phản bác quyết định đó."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_46_4', 'en-b2-46', 'Cách dùng “banker” (n.) — nhà ngân hàng; nhân sự cấp cao ngành ngân hàng', 'investment banker  ·  central banker  ·  senior banker', 'Thường dùng để chỉ nhà ngân hàng hoặc nhân sự cấp cao, không dùng để chỉ giao dịch viên ngân hàng nói chung.', 'Họ từ (Word Family): bank (n.), bank (v.), banking (n.)', '[{"hanzi":"The banker explained our loan options over coffee.","pinyin":"","meaning":"Viên quản lý ngân hàng đã giải thích các gói cho vay của chúng tôi trong lúc uống cà phê."},{"hanzi":"Bankers play an important role in assessing financial risks before approving loans to small businesses.","pinyin":"","meaning":"Các chuyên gia ngân hàng đóng vai trò quan trọng trong việc đánh giá rủi ro tài chính trước khi phê duyệt các khoản vay cho doanh nghiệp nhỏ."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
