INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_46_1_2', 'ten_b2_46_1', 'rewarding', 'Teaching my little cousin to swim was surprisingly rewarding.', 'Teaching my little cousin to swim was surprisingly rewarding.', '/rɪˈwɔːrdɪŋ/', 'Dạy em họ tôi bơi mang lại cho tôi cảm giác thành tựu đáng ngạc nhiên.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
