INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_46_1_5', 'ten_b2_46_1', 'labor', 'Repairing the old fence took a full day of labor.', 'Repairing the old fence took a full day of labor.', '/ˈleɪbər/', 'Việc sửa chữa hàng rào cũ mất trọn một ngày lao động chân tay.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_46_1_6', 'ten_b2_46_1', 'negotiate', 'We negotiated a lower price for the secondhand sofa.', 'We negotiated a lower price for the secondhand sofa.', '/nɪˈɡoʊʃieɪt/', 'Chúng tôi đã thương lượng được mức giá rẻ hơn cho chiếc ghế sofa cũ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_46_1_7', 'ten_b2_46_1', 'banker', 'The banker explained our loan options over coffee.', 'The banker explained our loan options over coffee.', '/ˈbæŋkər/', 'Viên quản lý ngân hàng đã giải thích các gói cho vay của chúng tôi trong lúc uống cà phê.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_46_1_8', 'ten_b2_46_1', 'interpreter', 'An interpreter helped my grandmother speak to the doctor.', 'An interpreter helped my grandmother speak to the doctor.', '/ɪnˈtɝːprɪtər/', 'Một thông dịch viên đã giúp bà tôi trò chuyện với bác sĩ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_46_1_1', 'en-b2-46', 'ten_b2_46_1', 'listening', 'listening', 'She handles the administration for our local sports club.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Thợ máy đã dùng các dụng cụ chuyên dụng để sửa chiếc xe đạp của tôi.","Cô ấy đã thất nghiệp nhiều tháng trời sau khi nhà máy đóng cửa.","Dì tôi là một thợ điện tự do có xe tải riêng.","Cô ấy phụ trách công tác hành chính cho câu lạc bộ thể thao địa phương của chúng tôi."]'::jsonb, 3, 'She handles the administration for our local sports club. → Cô ấy phụ trách công tác hành chính cho câu lạc bộ thể thao địa phương của chúng tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_46_1_2', 'en-b2-46', 'ten_b2_46_1', 'listening', 'listening', 'Teaching my little cousin to swim was surprisingly rewarding.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Dạy em họ tôi bơi mang lại cho tôi cảm giác thành tựu đáng ngạc nhiên.","Một y tá có thâm niên đã chỉ cho tôi cách thay băng vết thương.","Đôi bốt này có độ bám đường tốt hơn hẳn trên những con đường ẩm ướt.","Dì tôi đã thành lập một quỹ từ thiện nhỏ vào mùa đông năm ngoái."]'::jsonb, 0, 'Teaching my little cousin to swim was surprisingly rewarding. → Dạy em họ tôi bơi mang lại cho tôi cảm giác thành tựu đáng ngạc nhiên.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_46_1_3', 'en-b2-46', 'ten_b2_46_1', 'listening', 'listening', 'These boots offer superior grip on wet paths.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Đôi bốt này có độ bám đường tốt hơn hẳn trên những con đường ẩm ướt.","Cô ấy phụ trách công tác hành chính cho câu lạc bộ thể thao địa phương của chúng tôi.","Việc sửa chữa hàng rào cũ mất trọn một ngày lao động chân tay.","Chúng tôi đã thương lượng được mức giá rẻ hơn cho chiếc ghế sofa cũ."]'::jsonb, 0, 'These boots offer superior grip on wet paths. → Đôi bốt này có độ bám đường tốt hơn hẳn trên những con đường ẩm ướt.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_46_2', 'en-b2-46', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_46_2_1', 'ten_b2_46_2', 'administration', 'Efficient administration allows public hospitals to allocate resources fairly and respond more quickly to patients'' needs.', 'Efficient administration allows public hospitals to allocate resources fairly and respond more quickly to patients'' needs.', '/ədˌmɪnɪˈstreɪʃən/', 'Công tác quản lý hiệu quả giúp các bệnh viện công phân bổ nguồn lực công bằng và đáp ứng nhanh chóng hơn các nhu cầu của bệnh nhân.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_46_2_2', 'ten_b2_46_2', 'rewarding', 'Volunteering can be a rewarding experience that develops practical skills and strengthens connections within local communities.', 'Volunteering can be a rewarding experience that develops practical skills and strengthens connections within local communities.', '/rɪˈwɔːrdɪŋ/', 'Hoạt động tình nguyện có thể là một trải nghiệm ý nghĩa giúp phát triển các kỹ năng thực tế và củng cố sự gắn kết trong cộng đồng địa phương.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_46_2_3', 'ten_b2_46_2', 'superior', 'Public transport can provide a superior alternative to private cars when services are frequent and reliable.', 'Public transport can provide a superior alternative to private cars when services are frequent and reliable.', '/suːˈpɪriər/', 'Giao thông công cộng có thể là một lựa chọn thay thế tối ưu cho xe hơi cá nhân khi các chuyến xe chạy thường xuyên và đáng tin cậy.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_46_2_4', 'ten_b2_46_2', 'sack', 'Employers should not sack workers without explaining the reasons and allowing them to challenge the decision.', 'Employers should not sack workers without explaining the reasons and allowing them to challenge the decision.', '/sæk/', 'Người sử dụng lao động không nên sa thải nhân công mà không giải thích rõ lý do cũng như không cho họ cơ hội phản bác quyết định đó.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_46_2_5', 'ten_b2_46_2', 'labor', 'Investment in automation can reduce labor costs, but governments must help displaced workers develop new skills.', 'Investment in automation can reduce labor costs, but governments must help displaced workers develop new skills.', '/ˈleɪbər/', 'Đầu tư vào tự động hóa có thể giảm chi phí nhân công, nhưng chính phủ phải giúp những công nhân mất việc phát triển các kỹ năng mới.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_46_2_6', 'ten_b2_46_2', 'negotiate', 'Governments must negotiate fair trade agreements that protect workers while encouraging international investment and economic growth.', 'Governments must negotiate fair trade agreements that protect workers while encouraging international investment and economic growth.', '/nɪˈɡoʊʃieɪt/', 'Các chính phủ phải đàm phán các thỏa thuận thương mại công bằng nhằm bảo vệ người lao động đồng thời thúc đẩy đầu tư quốc tế và tăng trưởng kinh tế.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_46_2_1', 'en-b2-46', 'ten_b2_46_2', 'listening', 'listening', 'Efficient administration allows public hospitals to allocate resources fairly and respond more quickly to patients'' needs.', NULL, 'Trong câu vừa nghe, từ “administration” mang nghĩa nào sau đây?', '["sự quyết tâm; nghị lực","gập ghềnh; không bằng phẳng; nhấp nhô","thỉnh thoảng; đôi khi","công tác quản lý; hoạt động hành chính"]'::jsonb, 3, '“administration” (/ədˌmɪnɪˈstreɪʃən/): công tác quản lý; hoạt động hành chính. Câu đầy đủ: Efficient administration allows public hospitals to allocate resources fairly and respond more quickly to patients'' needs.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_46_2_2', 'en-b2-46', 'ten_b2_46_2', 'listening', 'listening', 'Volunteering can be a rewarding experience that develops practical skills and strengthens connections within local communities.', NULL, 'Trong câu vừa nghe, từ “rewarding” mang nghĩa nào sau đây?', '["hạt hạnh nhân; cây hạnh nhân","bổ ích; đáng làm; mang lại sự thỏa mãn","bao quanh; rào lại","sự bình phục; sự phục hồi"]'::jsonb, 1, '“rewarding” (/rɪˈwɔːrdɪŋ/): bổ ích; đáng làm; mang lại sự thỏa mãn. Câu đầy đủ: Volunteering can be a rewarding experience that develops practical skills and strengthens connections within local communities.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
