INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_46_7', 'en-b2-46', 'The banker explained our loan options over coffee', 'Viên quản lý ngân hàng đã giải thích các gói cho vay của chúng tôi trong lúc uống cà phê.', 'banker /ˈbæŋkər/', '["over","loan","options","our","The","explained","banker","coffee"]'::jsonb, NULL, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
