INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_46_1', 'en-b2-46', NULL, 'comprehensive_test', 'listening', 'administration', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["được cho là; theo như người ta nói","công tác quản lý; hoạt động hành chính","sinh ra; đem lại","mồ mả; lăng mộ"]'::jsonb, 1, 'administration (/ədˌmɪnɪˈstreɪʃən/) → công tác quản lý; hoạt động hành chính; chính phủ; ban quản trị; sự cấp phát; sự cho uống thuốc', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_46_2', 'en-b2-46', NULL, 'comprehensive_test', 'listening', 'Teaching my little cousin to swim was surprisingly rewarding.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Dạy em họ tôi bơi mang lại cho tôi cảm giác thành tựu đáng ngạc nhiên.","Chị gái tôi đảm nhận các công việc hành chính tại một phòng khám địa phương.","Một thông dịch viên đã giúp bà tôi trò chuyện với bác sĩ.","Chúng tôi khiêng một bao tải khoai tây nặng vào trong bếp."]'::jsonb, 0, 'Teaching my little cousin to swim was surprisingly rewarding. → Dạy em họ tôi bơi mang lại cho tôi cảm giác thành tựu đáng ngạc nhiên.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_46_3', 'en-b2-46', NULL, 'comprehensive_test', 'listening', 'superior', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thủy triều; nước thủy triều","cư dân; người dân","tốt hơn; chất lượng cao hơn","đồ cổ; cổ vật"]'::jsonb, 2, 'superior (/suːˈpɪriər/) → tốt hơn; chất lượng cao hơn; cấp trên; người quản lý; kiêu ngạo; trịch thượng; tự cho mình là hơn', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_46_4', 'en-b2-46', NULL, 'comprehensive_test', 'listening', 'We carried a heavy sack of potatoes into the kitchen.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chiếc bàn chải đơn giản này làm sạch giày bám bùn một cách hiệu quả đến bất ngờ.","Chúng tôi khiêng một bao tải khoai tây nặng vào trong bếp.","Một y tá có thâm niên đã chỉ cho tôi cách thay băng vết thương.","Nhân viên dọn phòng đã để những chiếc khăn tắm sạch bên cạnh bồn rửa trong phòng tắm."]'::jsonb, 1, 'We carried a heavy sack of potatoes into the kitchen. → Chúng tôi khiêng một bao tải khoai tây nặng vào trong bếp.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_46_5', 'en-b2-46', NULL, 'comprehensive_test', 'listening', 'labor', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["lao động; nhân công","làm việc tự do; thuộc nghề tự do","nhún vai","nhạc cụ gõ; bộ gõ"]'::jsonb, 0, 'labor (/ˈleɪbər/) → lao động; nhân công; làm việc vất vả; nỗ lực làm gì; sự chuyển dạ; quá trình sinh con', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_46_6', 'en-b2-46', NULL, 'comprehensive_test', 'listening', 'We negotiated a lower price for the secondhand sofa.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nhân viên dọn phòng đã để những chiếc khăn tắm sạch bên cạnh bồn rửa trong phòng tắm.","Đôi bốt này có độ bám đường tốt hơn hẳn trên những con đường ẩm ướt.","Chúng tôi đã thương lượng được mức giá rẻ hơn cho chiếc ghế sofa cũ.","Dì tôi đã thành lập một quỹ từ thiện nhỏ vào mùa đông năm ngoái."]'::jsonb, 2, 'We negotiated a lower price for the secondhand sofa. → Chúng tôi đã thương lượng được mức giá rẻ hơn cho chiếc ghế sofa cũ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_46_7', 'en-b2-46', NULL, 'comprehensive_test', 'listening', 'banker', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["rộng lớn; bao la; vô cùng","nhà ngân hàng; nhân sự cấp cao ngành ngân hàng","vô cùng, hết sức, sâu sắc (về cảm xúc hoặc niềm tin)","hình bầu dục; hình trứng"]'::jsonb, 1, 'banker (/ˈbæŋkər/) → nhà ngân hàng; nhân sự cấp cao ngành ngân hàng', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_46_8', 'en-b2-46', NULL, 'comprehensive_test', 'listening', 'An interpreter helped my grandmother speak to the doctor.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chị gái tôi đảm nhận các công việc hành chính tại một phòng khám địa phương.","Nhân viên dọn phòng đã để những chiếc khăn tắm sạch bên cạnh bồn rửa trong phòng tắm.","Một thông dịch viên đã giúp bà tôi trò chuyện với bác sĩ.","Người quản lý của tôi đã chỉ cho tôi cách sử dụng thiết bị này."]'::jsonb, 2, 'An interpreter helped my grandmother speak to the doctor. → Một thông dịch viên đã giúp bà tôi trò chuyện với bác sĩ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
