INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_46_18', 'en-b2-46', NULL, 'comprehensive_test', 'reading', NULL, 'Efficient administration allows public hospitals to allocate resources fairly and respond more quickly to patients'' needs.', 'Dựa vào câu trên, từ “administration” có nghĩa phù hợp nhất là gì?', '["sách bán chạy; sản phẩm bán chạy","khối lượng công việc; lượng công việc mà ai đó phải hoàn thành trong một khoảng thời gian nhất định","thiên đường; chốn bồng lai tiên cảnh; nơi lý tưởng","công tác quản lý; hoạt động hành chính"]'::jsonb, 3, 'administration: công tác quản lý; hoạt động hành chính; chính phủ; ban quản trị; sự cấp phát; sự cho uống thuốc. Dịch cả câu: Công tác quản lý hiệu quả giúp các bệnh viện công phân bổ nguồn lực công bằng và đáp ứng nhanh chóng hơn các nhu cầu của bệnh nhân.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_46_19', 'en-b2-46', NULL, 'comprehensive_test', 'reading', NULL, 'Volunteering can be a rewarding experience that develops practical skills and strengthens connections within local communities.', 'Dựa vào câu trên, từ “rewarding” có nghĩa phù hợp nhất là gì?', '["bổ ích; đáng làm; mang lại sự thỏa mãn","làm ngạc nhiên; làm kinh ngạc","không vững chãi; dễ đổ","nhớ lại; hồi tưởng"]'::jsonb, 0, 'rewarding: bổ ích; đáng làm; mang lại sự thỏa mãn; có lợi nhuận cao; thu nhập hấp dẫn. Dịch cả câu: Hoạt động tình nguyện có thể là một trải nghiệm ý nghĩa giúp phát triển các kỹ năng thực tế và củng cố sự gắn kết trong cộng đồng địa phương.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_46_20', 'en-b2-46', NULL, 'comprehensive_test', 'reading', NULL, 'Public transport can provide a superior alternative to private cars when services are frequent and reliable.', 'Dựa vào câu trên, từ “superior” có nghĩa phù hợp nhất là gì?', '["hương thơm; mùi thơm dễ chịu","tốt hơn; chất lượng cao hơn","bò; trườn (bằng tay và đầu gối)","hơi nước; thể hơi"]'::jsonb, 1, 'superior: tốt hơn; chất lượng cao hơn; cấp trên; người quản lý; kiêu ngạo; trịch thượng; tự cho mình là hơn. Dịch cả câu: Giao thông công cộng có thể là một lựa chọn thay thế tối ưu cho xe hơi cá nhân khi các chuyến xe chạy thường xuyên và đáng tin cậy.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_46_21', 'en-b2-46', NULL, 'comprehensive_test', 'reading', NULL, 'Employers should not sack workers without explaining the reasons and allowing them to challenge the decision.', 'Dựa vào câu trên, từ “sack” có nghĩa phù hợp nhất là gì?', '["máy phát điện","cử tri; người bỏ phiếu","bao tải lớn; túi vải thô","chỗ trống việc làm; vị trí tuyển dụng"]'::jsonb, 2, 'sack: bao tải lớn; túi vải thô; sa thải; đuổi việc; sự sa thải; việc bị đuổi việc. Dịch cả câu: Người sử dụng lao động không nên sa thải nhân công mà không giải thích rõ lý do cũng như không cho họ cơ hội phản bác quyết định đó.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_46_22', 'en-b2-46', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cấp cao; thâm niên”', '["senior","clockwise","existence","accurate"]'::jsonb, 0, 'cấp cao; thâm niên → senior (/ˈsiːniər/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_46_23', 'en-b2-46', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “chuyên dụng; chuyên khoa; chuyên môn hóa”', '["specialised","lasting","elder","inspection"]'::jsonb, 0, 'chuyên dụng; chuyên khoa; chuyên môn hóa → specialised (/ˈspeʃəlaɪzd/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_46_24', 'en-b2-46', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “làm việc tự do; thuộc nghề tự do”', '["exhaustion","evident","correlation","freelance"]'::jsonb, 3, 'làm việc tự do; thuộc nghề tự do → freelance (/ˈfriːlæns/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-47', 'en', 'Bài 47: Công việc & Nghề nghiệp (2) - CEFR B2', 'CEFR B2', 'B2 · Công việc', '25 từ vựng Tiếng Anh CEFR B2 chủ đề công việc & nghề nghiệp kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4047, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_craftsman', 'en-b2-47', 'craftsman', '/ˈkræftsmən/', 'B2', 'thợ thủ công; nghệ nhân', 'n.', 'craft (n.), craftsmanship (n.), craftswoman (n.), craftsperson (n.)', 'Đồng nghĩa: artisan', 'Dạng số nhiều của từ này là "craftsmen"; nếu muốn dùng từ trung lập về giới tính, bạn có thể chọn "craftsperson".', 'The craftsman carved a wooden bird for the display.', NULL, 'Người thợ thủ công đã chạm trổ một con chim bằng gỗ để trưng bày.', '{"wordId":"craftsman","ukIpa":"/ˈkrɑːftsmən/","usIpa":"/ˈkræftsmən/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"A skilled person, especially a man, who makes things by hand.","vi":"thợ thủ công; nghệ nhân"}],"examples":[{"en":"The craftsman carved a wooden bird for the display.","vi":"Người thợ thủ công đã chạm trổ một con chim bằng gỗ để trưng bày.","audioKind":"ex"},{"en":"Supporting local craftsmen can preserve traditional skills while providing communities with sustainable sources of income.","vi":"Việc hỗ trợ các nghệ nhân địa phương có thể bảo tồn các kỹ năng truyền thống đồng thời đem lại nguồn thu nhập bền vững cho cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"a skilled craftsman","vi":"thợ thủ công lành nghề"},{"en":"a master craftsman","vi":"bậc thầy thủ công"},{"en":"a traditional craftsman","vi":"nghệ nhân truyền thống"}],"wordFamily":["craft (n.)","craftsmanship (n.)","craftswoman (n.)","craftsperson (n.)"],"synonyms":["artisan"],"antonyms":[],"tipVi":"Dạng số nhiều của từ này là \"craftsmen\"; nếu muốn dùng từ trung lập về giới tính, bạn có thể chọn \"craftsperson\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dismiss', 'en-b2-47', 'dismiss', '/dɪsˈmɪs/', 'B2', 'gạt bỏ; xem nhẹ; không màng tới; sa thải; đuổi việc; cho phép rời đi; giải tán', 'v.', 'dismissal (n.), dismissive (adj.), dismissively (adv.)', 'Đồng nghĩa: reject · Trái nghĩa: consider', 'Cấu trúc dismiss A as B nghĩa là xem A là B rồi gạt đi không bận tâm.', 'Don''t dismiss her idea before you hear the details.', NULL, 'Đừng vội gạt phăng ý kiến của cô ấy trước khi nghe rõ chi tiết.', '{"wordId":"dismiss","ukIpa":"/dɪsˈmɪs/","usIpa":"/dɪsˈmɪs/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"to decide something is not worth considering","vi":"gạt bỏ; xem nhẹ; không màng tới"},{"pos":"v.","en":"to officially remove someone from their job","vi":"sa thải; đuổi việc"},{"pos":"v.","en":"to tell someone or a group they may leave","vi":"cho phép rời đi; giải tán"}],"examples":[{"en":"Don''t dismiss her idea before you hear the details.","vi":"Đừng vội gạt phăng ý kiến của cô ấy trước khi nghe rõ chi tiết.","audioKind":"ex"},{"en":"Governments should not dismiss public concerns about the long-term environmental effects of industrial expansion.","vi":"Chính phủ không nên xem nhẹ những lo ngại của công chúng về tác động môi trường lâu dài của việc mở rộng công nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"dismiss concerns","vi":"bỏ qua những lo ngại"},{"en":"dismiss an idea","vi":"bác bỏ một ý kiến"},{"en":"dismiss someone from a job","vi":"sa thải ai khỏi công việc"},{"en":"dismiss something as irrelevant","vi":"coi điều gì là không quan trọng nên gạt đi"}],"wordFamily":["dismissal (n.)","dismissive (adj.)","dismissively (adv.)"],"synonyms":["reject"],"antonyms":["consider"],"tipVi":"Cấu trúc dismiss A as B nghĩa là xem A là B rồi gạt đi không bận tâm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_entrepreneur', 'en-b2-47', 'entrepreneur', '/ˌɑːntrəprəˈnɝː/', 'B2', 'nhà u tư; chủ doanh nghiệp; doanh nhân', 'n.', 'entrepreneurial (adj.), entrepreneurship (n.)', NULL, 'Nhấn mạnh người khởi lập kinh doanh và chịu rủi ro tài chính, không dùng chung chung cho mọi giám đốc.', 'The young entrepreneur opened a bakery near our station.', NULL, 'Nhà khởi nghiệp trẻ tuổi đã mở một tiệm bánh gần nhà ga của chúng tôi.', '{"wordId":"entrepreneur","ukIpa":"/ˌɒntrəprəˈnɜː/","usIpa":"/ˌɑːntrəprəˈnɝː/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"someone who starts a business and takes financial risks","vi":"nhà u tư; chủ doanh nghiệp; doanh nhân"}],"examples":[{"en":"The young entrepreneur opened a bakery near our station.","vi":"Nhà khởi nghiệp trẻ tuổi đã mở một tiệm bánh gần nhà ga của chúng tôi.","audioKind":"ex"},{"en":"Local governments can support entrepreneurs by simplifying regulations and improving access to affordable loans.","vi":"Chính quyền địa phương có thể hỗ trợ các doanh nhân bằng cách đơn giản hóa các quy định và tạo điều kiện tiếp cận các khoản vay có lãi suất phải chăng.","audioKind":"ex2"}],"collocations":[{"en":"a successful entrepreneur","vi":"một doanh nhân thành đạt"},{"en":"a young entrepreneur","vi":"một nhà khởi nghiệp trẻ"},{"en":"a social entrepreneur","vi":"doanh nhân xã hội"}],"wordFamily":["entrepreneurial (adj.)","entrepreneurship (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nhấn mạnh người khởi lập kinh doanh và chịu rủi ro tài chính, không dùng chung chung cho mọi giám đốc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_demanding', 'en-b2-47', 'demanding', '/dɪˈmændɪŋ/', 'B2', 'đòi hỏi nhiều nỗ lực; khắt khe; vất vả; đòi hỏi cao; khó chiều', 'adj.', 'demand (v.), demand (n.), undemanding (adj.)', 'Đồng nghĩa: challenging, exacting · Trái nghĩa: undemanding, easy', 'Khi bổ nghĩa cho công việc, từ này chỉ sự vất vả; khi bổ nghĩa cho con người, từ này chỉ tính cách đòi hỏi cao, khó làm hài lòng.', 'After a demanding shift, I fell asleep on the bus.', NULL, 'Sau ca làm việc vất vả kéo dài, tôi đã ngủ thiếp đi trên xe buýt.', '{"wordId":"demanding","ukIpa":"/dɪˈmɑːndɪŋ/","usIpa":"/dɪˈmændɪŋ/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"Requiring considerable effort, skill, time, or attention.","vi":"đòi hỏi nhiều nỗ lực; khắt khe; vất vả"},{"pos":"adj.","en":"Expecting a great deal of attention or effort from others.","vi":"đòi hỏi cao; khó chiều"}],"examples":[{"en":"After a demanding shift, I fell asleep on the bus.","vi":"Sau ca làm việc vất vả kéo dài, tôi đã ngủ thiếp đi trên xe buýt.","audioKind":"ex"},{"en":"Physically demanding jobs may require additional safety measures to protect workers from injuries and long-term health problems.","vi":"Những công việc đòi hỏi thể lực cao có thể cần đến các biện pháp an toàn bổ sung để bảo vệ người lao động khỏi chấn thương và các vấn đề sức khỏe lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"physically demanding","vi":"đòi hỏi thể lực"},{"en":"mentally demanding","vi":"đòi hỏi trí óc"},{"en":"demanding job","vi":"công việc đòi hỏi cao"},{"en":"demanding customer","vi":"khách hàng khó tính"}],"wordFamily":["demand (v.)","demand (n.)","undemanding (adj.)"],"synonyms":["challenging","exacting"],"antonyms":["undemanding","easy"],"tipVi":"Khi bổ nghĩa cho công việc, từ này chỉ sự vất vả; khi bổ nghĩa cho con người, từ này chỉ tính cách đòi hỏi cao, khó làm hài lòng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_confidential', 'en-b2-47', 'confidential', '/ˌkɑːnfɪˈdenʃəl/', 'B2', 'bảo mật; kín; cơ mật', 'adj.', 'confidentiality (n.), confidentially (adv.)', 'Đồng nghĩa: private, secret · Trái nghĩa: public', 'confidential chỉ sự bảo mật; confident chỉ sự tự tin.', 'Please keep this confidential until I tell my family.', NULL, 'Xin hãy giữ kín chuyện này cho đến khi tôi nói với gia đình mình.', '{"wordId":"confidential","ukIpa":"/ˌkɒnfɪˈdenʃəl/","usIpa":"/ˌkɑːnfɪˈdenʃəl/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"Intended to remain private and not be shared without permission.","vi":"bảo mật; kín; cơ mật"}],"examples":[{"en":"Please keep this confidential until I tell my family.","vi":"Xin hãy giữ kín chuyện này cho đến khi tôi nói với gia đình mình.","audioKind":"ex"},{"en":"Hospitals must protect confidential patient information to maintain public trust in the healthcare system.","vi":"Các bệnh viện phải bảo vệ thông tin bảo mật của bệnh nhân để duy trì niềm tin của công chúng vào hệ thống y tế.","audioKind":"ex2"}],"collocations":[{"en":"confidential information","vi":"thông tin bảo mật"},{"en":"keep something confidential","vi":"giữ bí mật điều gì"},{"en":"strictly confidential","vi":"tuyệt mật"}],"wordFamily":["confidentiality (n.)","confidentially (adv.)"],"synonyms":["private","secret"],"antonyms":["public"],"tipVi":"confidential chỉ sự bảo mật; confident chỉ sự tự tin.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_priority', 'en-b2-47', 'priority', '/praɪˈɔːrəti/', 'B2', 'ưu tiên; việc ưu tiên; nhiệm vụ hàng đầu; quyền ưu tiên', 'n.', 'prior (adj.), prioritise (v.), prioritisation (n.)', 'Đồng nghĩa: precedence', 'give priority to đi kèm với đối tượng được ưu tiên.', 'Finding a warm home is our main priority now.', NULL, 'Tìm một ngôi nhà ấm cúng là ưu tiên hàng đầu của chúng tôi lúc này.', '{"wordId":"priority","ukIpa":"/praɪˈɒrəti/","usIpa":"/praɪˈɔːrəti/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"something considered more important than other things","vi":"ưu tiên; việc ưu tiên; nhiệm vụ hàng đầu"},{"pos":"n.","en":"the right to receive attention or action before others","vi":"quyền ưu tiên"}],"examples":[{"en":"Finding a warm home is our main priority now.","vi":"Tìm một ngôi nhà ấm cúng là ưu tiên hàng đầu của chúng tôi lúc này.","audioKind":"ex"},{"en":"Governments should give priority to preventive healthcare rather than focus exclusively on treating existing illnesses.","vi":"Chính phủ nên ưu tiên y tế dự phòng hơn là chỉ tập trung điều trị các bệnh hiện có.","audioKind":"ex2"}],"collocations":[{"en":"top priority","vi":"ưu tiên hàng đầu"},{"en":"give priority to","vi":"ưu tiên cho"},{"en":"take priority over","vi":"có ưu tiên hơn"},{"en":"set priorities","vi":"xác định các ưu tiên"}],"wordFamily":["prior (adj.)","prioritise (v.)","prioritisation (n.)"],"synonyms":["precedence"],"antonyms":[],"tipVi":"give priority to đi kèm với đối tượng được ưu tiên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_proceed', 'en-b2-47', 'proceed', '/prəˈsiːd/', 'B2', 'động từ: tiếp tục tiến hành; tiếp theo; động từ: đi đến; di chuyển về phía', 'v.', 'proceedings (n.), proceeds (n.)', 'Đồng nghĩa: continue, advance · Trái nghĩa: stop, halt', 'proceed là động từ; danh từ chỉ tiền thu được là proceeds.', 'We can proceed with dinner once everyone arrives.', NULL, 'Chúng ta có thể tiếp tục dùng bữa tối ngay khi mọi người đến đủ.', '{"wordId":"proceed","ukIpa":"/prəˈsiːd/","usIpa":"/prəˈsiːd/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"Continue an activity or move to its next stage.","vi":"động từ: tiếp tục tiến hành; tiếp theo"},{"pos":"v.","en":"Move forward or travel towards a particular place.","vi":"động từ: đi đến; di chuyển về phía"}],"examples":[{"en":"We can proceed with dinner once everyone arrives.","vi":"Chúng ta có thể tiếp tục dùng bữa tối ngay khi mọi người đến đủ.","audioKind":"ex"},{"en":"Local authorities should consult residents before they proceed with major changes to public transport.","vi":"Chính quyền địa phương nên tham khảo ý kiến cư dân trước khi tiếp tục thực hiện các thay đổi lớn đối với giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"proceed with a plan","vi":"tiếp tục thực hiện kế hoạch"},{"en":"proceed to the next stage","vi":"tiến đến giai đoạn tiếp theo"},{"en":"proceed cautiously","vi":"tiến hành một cách thận trọng"}],"wordFamily":["proceedings (n.)","proceeds (n.)"],"synonyms":["continue","advance"],"antonyms":["stop","halt"],"tipVi":"proceed là động từ; danh từ chỉ tiền thu được là proceeds.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_devote', 'en-b2-47', 'devote', '/dɪˈvoʊt/', 'B2', 'dành hết; cống hiến (thời gian, công sức, nguồn lực)', 'v.', 'devotion (n.), devoted (adj.), devotedly (adv.)', 'Đồng nghĩa: dedicate', 'Trong "devote…to", "to" là giới từ, theo sau là danh từ hoặc danh động từ (V-ing).', 'I devote an hour each evening to practising the piano.', NULL, 'Tôi dành một giờ mỗi tối để luyện tập đàn piano.', '{"wordId":"devote","ukIpa":"/dɪˈvəʊt/","usIpa":"/dɪˈvoʊt/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"To give time, effort, or resources to someone or something.","vi":"dành hết; cống hiến (thời gian, công sức, nguồn lực)"}],"examples":[{"en":"I devote an hour each evening to practising the piano.","vi":"Tôi dành một giờ mỗi tối để luyện tập đàn piano.","audioKind":"ex"},{"en":"Governments should devote more resources to preventive healthcare rather than relying entirely on expensive medical treatments.","vi":"Chính phủ nên dành nhiều nguồn lực hơn cho y tế dự phòng thay vì chỉ phụ thuộc hoàn toàn vào các phương pháp điều trị đắt đỏ.","audioKind":"ex2"}],"collocations":[{"en":"devote time to","vi":"dành thời gian cho"},{"en":"devote resources to","vi":"dành nguồn lực cho"},{"en":"devote oneself to","vi":"cống hiến hết mình cho"}],"wordFamily":["devotion (n.)","devoted (adj.)","devotedly (adv.)"],"synonyms":["dedicate"],"antonyms":[],"tipVi":"Trong \"devote…to\", \"to\" là giới từ, theo sau là danh từ hoặc danh động từ (V-ing).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_proposal', 'en-b2-47', 'proposal', '/prəˈpoʊzəl/', 'B2', 'đề xuất; kiến nghị; phương án; lời cầu hôn', 'n.', 'propose (v.), proposed (adj.)', 'Đồng nghĩa: suggestion, plan', 'proposal to do biểu thị đề xuất làm gì đó, thường là danh từ đếm được.', 'Everyone liked my proposal to turn the spare room into an office.', NULL, 'Mọi người đều thích đề xuất biến phòng trống thành văn phòng của tôi.', '{"wordId":"proposal","ukIpa":"/prəˈpəʊzəl/","usIpa":"/prəˈpoʊzəl/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"A suggested plan for others to consider.","vi":"đề xuất; kiến nghị; phương án"},{"pos":"n.","en":"An act of asking someone to marry you.","vi":"lời cầu hôn"}],"examples":[{"en":"Everyone liked my proposal to turn the spare room into an office.","vi":"Mọi người đều thích đề xuất biến phòng trống thành văn phòng của tôi.","audioKind":"ex"},{"en":"The council is considering a proposal to replace an unused car park with affordable housing.","vi":"Hội đồng đang xem xét phương án thay thế một bãi đỗ xe không sử dụng bằng nhà ở xã hội.","audioKind":"ex2"}],"collocations":[{"en":"put forward a proposal","vi":"đưa ra đề xuất"},{"en":"approve a proposal","vi":"phê duyệt đề xuất"},{"en":"a proposal to do something","vi":"đề xuất làm gì đó"},{"en":"a marriage proposal","vi":"lời cầu hôn"}],"wordFamily":["propose (v.)","proposed (adj.)"],"synonyms":["suggestion","plan"],"antonyms":[],"tipVi":"proposal to do biểu thị đề xuất làm gì đó, thường là danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_former', 'en-b2-47', 'former', '/ˈfɔːrmər/', 'B2', 'cũ; trước đây; tiền nhiệm; thứ nhất (trong hai người hoặc vật vừa nhắc tới)', 'adj.', 'formerly (adv.)', 'Đồng nghĩa: previous · Trái nghĩa: current, latter', 'the former chỉ người/vật thứ nhất trong hai đối tượng, còn the latter chỉ người/vật thứ hai.', 'My former neighbour still visits us every summer.', NULL, 'Người hàng xóm cũ của tôi vẫn đến thăm chúng tôi mỗi mùa hè.', '{"wordId":"former","ukIpa":"/ˈfɔːmə/","usIpa":"/ˈfɔːrmər/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"having a particular role or condition in the past","vi":"cũ; trước đây; tiền nhiệm"},{"pos":"adj.","en":"being the first of two people or things just mentioned","vi":"thứ nhất (trong hai người hoặc vật vừa nhắc tới)"}],"examples":[{"en":"My former neighbour still visits us every summer.","vi":"Người hàng xóm cũ của tôi vẫn đến thăm chúng tôi mỗi mùa hè.","audioKind":"ex"},{"en":"Former industrial sites can be transformed into public parks, improving urban environments and creating shared spaces.","vi":"Các khu công nghiệp cũ có thể được cải tạo thành công viên công cộng, giúp cải thiện môi trường đô thị và tạo ra các không gian sinh hoạt chung.","audioKind":"ex2"}],"collocations":[{"en":"former colleague","vi":"đồng nghiệp cũ"},{"en":"former president","vi":"cựu tổng thống"},{"en":"former industrial site","vi":"khu công nghiệp cũ"}],"wordFamily":["formerly (adv.)"],"synonyms":["previous"],"antonyms":["current","latter"],"tipVi":"the former chỉ người/vật thứ nhất trong hai đối tượng, còn the latter chỉ người/vật thứ hai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prior', 'en-b2-47', 'prior', '/ˈpraɪər/', 'B2', 'trước; tiên quyết; có trước', 'adj.', NULL, 'Đồng nghĩa: previous, earlier · Trái nghĩa: subsequent', 'Tính từ prior thường đứng trước danh từ; cụm prior to tương đương với từ before.', 'You need prior permission to use this room.', NULL, 'Bạn cần phải xin phép trước để sử dụng phòng này.', '{"wordId":"prior","ukIpa":"/ˈpraɪə/","usIpa":"/ˈpraɪər/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"existing or happening before something else","vi":"trước; tiên quyết; có trước"}],"examples":[{"en":"You need prior permission to use this room.","vi":"Bạn cần phải xin phép trước để sử dụng phòng này.","audioKind":"ex"},{"en":"Applicants with prior experience in community work may adapt more quickly to roles in public services.","vi":"Những ứng viên có kinh nghiệm làm việc cộng đồng từ trước có thể thích nghi nhanh hơn với các vị trí trong dịch vụ công.","audioKind":"ex2"}],"collocations":[{"en":"prior experience","vi":"kinh nghiệm trước đó"},{"en":"prior knowledge","vi":"kiến thức có sẵn từ trước"},{"en":"prior notice","vi":"thông báo trước"},{"en":"prior to","vi":"trước khi"}],"wordFamily":[],"synonyms":["previous","earlier"],"antonyms":["subsequent"],"tipVi":"Tính từ prior thường đứng trước danh từ; cụm prior to tương đương với từ before.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clause', 'en-b2-47', 'clause', '/klɔːz/', 'B2', 'điều khoản; điều mục trong văn bản pháp lý; mệnh đề; phân câu (gồm chủ ngữ và vị ngữ)', 'n.', NULL, NULL, 'Trong ngữ pháp, clause chứa cả chủ ngữ và vị ngữ, trong khi phrase thường không chứa.', 'One clause in our lease allows us to keep pets.', NULL, 'Một điều khoản trong hợp đồng thuê nhà của chúng tôi cho phép nuôi thú cưng.', '{"wordId":"clause","ukIpa":"/klɔːz/","usIpa":"/klɔːz/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"A separate condition or requirement in a legal document.","vi":"điều khoản; điều mục trong văn bản pháp lý"},{"pos":"n.","en":"A group of words containing a subject and a verb.","vi":"mệnh đề; phân câu (gồm chủ ngữ và vị ngữ)"}],"examples":[{"en":"One clause in our lease allows us to keep pets.","vi":"Một điều khoản trong hợp đồng thuê nhà của chúng tôi cho phép nuôi thú cưng.","audioKind":"ex"},{"en":"Employment contracts should include a clause that clearly defines workers'' rights to paid leave and flexible working.","vi":"Hợp đồng lao động nên bao gồm một điều khoản xác định rõ quyền lợi của người lao động về nghỉ phép có lương và làm việc linh hoạt.","audioKind":"ex2"}],"collocations":[{"en":"a clause in a contract","vi":"điều khoản trong hợp đồng"},{"en":"include a clause","vi":"đưa vào một điều khoản"},{"en":"main clause","vi":"mệnh đề chính"},{"en":"relative clause","vi":"mệnh đề quan hệ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong ngữ pháp, clause chứa cả chủ ngữ và vị ngữ, trong khi phrase thường không chứa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_brainstorm', 'en-b2-47', 'brainstorm', '/ˈbreɪnstɔːrm/', 'B2', 'tư duy theo nhóm; động não; thảo luận tìm ý tưởng; phiên họp thảo luận ý tưởng; buổi động não', 'v.', 'brainstorming (n.)', NULL, 'Thường đóng vai trò là động từ, có thể đi trực tiếp với các tân ngữ như "ideas" hoặc "solutions".', 'Let''s brainstorm some games for the family picnic.', NULL, 'Hãy cùng nhau lên ý tưởng cho một số trò chơi cho buổi dã ngoại gia đình nào.', '{"wordId":"brainstorm","ukIpa":"/ˈbreɪnstɔːm/","usIpa":"/ˈbreɪnstɔːrm/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"generate many ideas freely, often with other people","vi":"tư duy theo nhóm; động não; thảo luận tìm ý tưởng"},{"pos":"n.","en":"a session of freely generating ideas","vi":"phiên họp thảo luận ý tưởng; buổi động não"}],"examples":[{"en":"Let''s brainstorm some games for the family picnic.","vi":"Hãy cùng nhau lên ý tưởng cho một số trò chơi cho buổi dã ngoại gia đình nào.","audioKind":"ex"},{"en":"Students who brainstorm solutions together can develop creative thinking skills and learn to consider alternative perspectives.","vi":"Những học sinh cùng nhau thảo luận tìm giải pháp có thể phát triển kỹ năng tư duy sáng tạo và học cách nhìn nhận vấn đề từ các góc độ khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"brainstorm ideas","vi":"động não tìm ý tưởng"},{"en":"brainstorm solutions","vi":"cùng nhau bàn bạc giải pháp"},{"en":"brainstorming session","vi":"buổi họp thảo luận ý tưởng"}],"wordFamily":["brainstorming (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường đóng vai trò là động từ, có thể đi trực tiếp với các tân ngữ như \"ideas\" hoặc \"solutions\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_division', 'en-b2-47', 'division', '/dɪˈvɪʒən/', 'B2', 'sự phân chia; sự phân bổ; bộ phận; phân khu; sự bất hòa; sự chia rẽ', 'n.', 'divide (v.), divided (adj.), divisive (adj.)', 'Đồng nghĩa: separation, department, split · Trái nghĩa: unity', 'Còn có nghĩa là phép chia trong toán học; divide là động từ tương ứng.', 'We agreed on a fair division of household chores.', NULL, 'Chúng tôi đã thỏa thuận về việc phân chia công việc nhà một cách công bằng.', '{"wordId":"division","ukIpa":"/dɪˈvɪʒən/","usIpa":"/dɪˈvɪʒən/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"the act of separating something into parts or shares","vi":"sự phân chia; sự phân bổ"},{"pos":"n.","en":"a major section of a company or organisation","vi":"bộ phận; phân khu"},{"pos":"n.","en":"disagreement that separates people into opposing groups","vi":"sự bất hòa; sự chia rẽ"}],"examples":[{"en":"We agreed on a fair division of household chores.","vi":"Chúng tôi đã thỏa thuận về việc phân chia công việc nhà một cách công bằng.","audioKind":"ex"},{"en":"A clear division of responsibilities between local and national authorities can improve the delivery of public services.","vi":"Sự phân định rõ ràng về trách nhiệm giữa chính quyền địa phương và trung ương có thể nâng cao chất lượng cung cấp dịch vụ công.","audioKind":"ex2"}],"collocations":[{"en":"division of labour","vi":"phân công lao động"},{"en":"division of responsibilities","vi":"sự phân chia trách nhiệm"},{"en":"a research division","vi":"một bộ phận nghiên cứu"},{"en":"social division","vi":"sự chia rẽ xã hội"}],"wordFamily":["divide (v.)","divided (adj.)","divisive (adj.)"],"synonyms":["separation","department","split"],"antonyms":["unity"],"tipVi":"Còn có nghĩa là phép chia trong toán học; divide là động từ tương ứng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_competent', 'en-b2-47', 'competent', '/ˈkɑːmpɪtənt/', 'B2', 'có năng lực; có tay nghề; thành thạo', 'adj.', 'competence (n.), competently (adv.), incompetent (adj.)', 'Đồng nghĩa: capable, proficient · Trái nghĩa: incompetent', 'Thường dùng cấu trúc be competent at doing, thể hiện khả năng làm tốt việc gì.', 'Our new mechanic is competent and explains every repair clearly.', NULL, 'Thợ máy mới của chúng tôi rất có tay nghề và giải thích rõ ràng mọi hạng mục sửa chữa.', '{"wordId":"competent","ukIpa":"/ˈkɒmpɪtənt/","usIpa":"/ˈkɑːmpɪtənt/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"Having enough skill and knowledge to do something well.","vi":"có năng lực; có tay nghề; thành thạo"}],"examples":[{"en":"Our new mechanic is competent and explains every repair clearly.","vi":"Thợ máy mới của chúng tôi rất có tay nghề và giải thích rõ ràng mọi hạng mục sửa chữa.","audioKind":"ex"},{"en":"Schools need competent teachers who can adapt their methods to students with different learning needs.","vi":"Các trường học cần những giáo viên có năng lực, những người có thể điều chỉnh phương pháp giảng dạy phù hợp với học sinh có nhu cầu học tập khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"competent teacher","vi":"giáo viên có năng lực"},{"en":"competent at","vi":"có năng lực làm gì"},{"en":"technically competent","vi":"có chuyên môn vững vàng"}],"wordFamily":["competence (n.)","competently (adv.)","incompetent (adj.)"],"synonyms":["capable","proficient"],"antonyms":["incompetent"],"tipVi":"Thường dùng cấu trúc be competent at doing, thể hiện khả năng làm tốt việc gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_accomplish', 'en-b2-47', 'accomplish', '/əˈkɑːmplɪʃ/', 'B2', 'hoàn thành; đạt được; làm tròn', 'v.', 'accomplishment (n.), accomplished (adj.)', 'Đồng nghĩa: achieve, complete', 'Là ngoại động từ, đi thẳng tới tân ngữ là nhiệm vụ hay mục tiêu, không đi kèm với động từ nguyên mẫu có to.', 'We accomplished everything before the guests arrived for dinner.', NULL, 'Chúng tôi đã hoàn tất mọi việc trước khi khách đến ăn tối.', '{"wordId":"accomplish","ukIpa":"/əˈkʌmplɪʃ/","usIpa":"/əˈkɑːmplɪʃ/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"to successfully finish something or achieve a goal","vi":"hoàn thành; đạt được; làm tròn"}],"examples":[{"en":"We accomplished everything before the guests arrived for dinner.","vi":"Chúng tôi đã hoàn tất mọi việc trước khi khách đến ăn tối.","audioKind":"ex"},{"en":"Students can accomplish more when teachers provide clear goals and regular feedback on their progress.","vi":"Học sinh có thể đạt được nhiều thành quả hơn khi giáo viên đưa ra các mục tiêu rõ ràng và phản hồi thường xuyên về tiến độ học tập của các em.","audioKind":"ex2"}],"collocations":[{"en":"accomplish a task","vi":"hoàn thành nhiệm vụ"},{"en":"accomplish a goal","vi":"đạt được mục tiêu"},{"en":"accomplish a great deal","vi":"đạt được nhiều thành tựu lớn"}],"wordFamily":["accomplishment (n.)","accomplished (adj.)"],"synonyms":["achieve","complete"],"antonyms":[],"tipVi":"Là ngoại động từ, đi thẳng tới tân ngữ là nhiệm vụ hay mục tiêu, không đi kèm với động từ nguyên mẫu có to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_promising', 'en-b2-47', 'promising', '/ˈprɑːmɪsɪŋ/', 'B2', 'có triển vọng; đầy hứa hẹn', 'adj.', 'promise (n.), promise (v.), promisingly (adv.)', 'Đồng nghĩa: encouraging · Trái nghĩa: unpromising', 'Diễn tả tiềm năng thành công, không đồng nghĩa với việc đã thành công.', 'Your first attempt looks promising; keep practising every day.', NULL, 'Buổi thử sức đầu tiên của bạn trông rất có triển vọng; hãy tiếp tục luyện tập mỗi ngày.', '{"wordId":"promising","ukIpa":"/ˈprɒmɪsɪŋ/","usIpa":"/ˈprɑːmɪsɪŋ/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"Showing signs of likely future success or improvement.","vi":"có triển vọng; đầy hứa hẹn"}],"examples":[{"en":"Your first attempt looks promising; keep practising every day.","vi":"Buổi thử sức đầu tiên của bạn trông rất có triển vọng; hãy tiếp tục luyện tập mỗi ngày.","audioKind":"ex"},{"en":"Solar energy offers a promising solution for remote communities that lack access to reliable electricity.","vi":"Năng lượng mặt trời mang lại một giải pháp đầy hứa hẹn cho các cộng đồng vùng sâu vùng xa thiếu nguồn điện ổn định.","audioKind":"ex2"}],"collocations":[{"en":"promising results","vi":"kết quả đầy hứa hẹn"},{"en":"promising career","vi":"sự nghiệp đầy triển vọng"},{"en":"promising young artist","vi":"nghệ sĩ trẻ đầy triển vọng"},{"en":"look promising","vi":"trông có vẻ triển vọng"}],"wordFamily":["promise (n.)","promise (v.)","promisingly (adv.)"],"synonyms":["encouraging"],"antonyms":["unpromising"],"tipVi":"Diễn tả tiềm năng thành công, không đồng nghĩa với việc đã thành công.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dynamic', 'en-b2-47', 'dynamic', '/daɪˈnæmɪk/', 'B2', 'năng động; đầy năng lượng; liên tục thay đổi; động; động lực; cơ chế tương tác', 'adj.', 'dynamically (adv.), dynamism (n.)', 'Đồng nghĩa: energetic, vigorous · Trái nghĩa: static', 'Khi dùng cho con người nghĩa là năng động; khi dùng cho hệ thống nghĩa là luôn biến đổi.', 'Our dynamic coach keeps everyone moving throughout the session.', NULL, 'Huấn luyện viên đầy nhiệt huyết của chúng tôi luôn giữ cho mọi người vận động suốt buổi tập.', '{"wordId":"dynamic","ukIpa":"/daɪˈnæmɪk/","usIpa":"/daɪˈnæmɪk/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"Full of energy and eager to make things happen.","vi":"năng động; đầy năng lượng"},{"pos":"adj.","en":"Continuously changing or developing.","vi":"liên tục thay đổi; động"},{"pos":"n.","en":"A pattern of interaction between people or forces.","vi":"động lực; cơ chế tương tác"}],"examples":[{"en":"Our dynamic coach keeps everyone moving throughout the session.","vi":"Huấn luyện viên đầy nhiệt huyết của chúng tôi luôn giữ cho mọi người vận động suốt buổi tập.","audioKind":"ex"},{"en":"A dynamic economy requires businesses to adapt quickly to technological advances and changing consumer preferences.","vi":"Một nền kinh tế năng động đòi hỏi các doanh nghiệp phải nhanh chóng thích ứng với những tiến bộ công nghệ và sở thích thay đổi của người tiêu dùng.","audioKind":"ex2"}],"collocations":[{"en":"dynamic leader","vi":"lãnh đạo năng động"},{"en":"dynamic economy","vi":"nền kinh tế năng động"},{"en":"group dynamics","vi":"tương tác nhóm"}],"wordFamily":["dynamically (adv.)","dynamism (n.)"],"synonyms":["energetic","vigorous"],"antonyms":["static"],"tipVi":"Khi dùng cho con người nghĩa là năng động; khi dùng cho hệ thống nghĩa là luôn biến đổi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_self-employment', 'en-b2-47', 'self-employment', '/ˌself ɪmˈplɔɪmənt/', 'B2', 'tự kinh doanh; tự làm chủ', 'n.', 'self-employed (adj.), employment (n.), employ (v.)', NULL, 'Là danh từ không đếm được; chỉ việc tự làm việc cho chính mình, không nhất thiết là thành lập công ty lớn.', 'Self-employment lets me choose when I take holidays.', NULL, 'Tự kinh doanh cho phép tôi tự chọn thời gian nghỉ ngơi.', '{"wordId":"self-employment","ukIpa":"/ˌself ɪmˈplɔɪmənt/","usIpa":"/ˌself ɪmˈplɔɪmənt/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"working for yourself rather than for an employer","vi":"tự kinh doanh; tự làm chủ"}],"examples":[{"en":"Self-employment lets me choose when I take holidays.","vi":"Tự kinh doanh cho phép tôi tự chọn thời gian nghỉ ngơi.","audioKind":"ex"},{"en":"Although self-employment offers greater flexibility, it can also involve irregular income and limited access to employment benefits.","vi":"Mặc dù việc tự làm chủ mang lại sự linh hoạt lớn hơn, nhưng nó cũng có thể đi kèm với thu nhập không ổn định và ít quyền lợi lao động hơn.","audioKind":"ex2"}],"collocations":[{"en":"go into self-employment","vi":"bắt đầu tự kinh doanh"},{"en":"income from self-employment","vi":"thu nhập từ việc tự làm chủ"},{"en":"self-employment opportunities","vi":"cơ hội tự kinh doanh"}],"wordFamily":["self-employed (adj.)","employment (n.)","employ (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ không đếm được; chỉ việc tự làm việc cho chính mình, không nhất thiết là thành lập công ty lớn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_technician', 'en-b2-47', 'technician', '/tekˈnɪʃən/', 'B2', 'kỹ thuật viên; thợ kỹ thuật', 'n.', 'technical (adj.), technically (adv.), technique (n.)', NULL, 'technician nghiêng về vận hành và bảo trì thiết bị, không đồng nghĩa hoàn toàn với engineer.', 'The technician replaced a broken part in our washing machine.', NULL, 'Kỹ thuật viên đã thay thế một bộ phận bị hỏng trong máy giặt của chúng tôi.', '{"wordId":"technician","ukIpa":"/tekˈnɪʃən/","usIpa":"/tekˈnɪʃən/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"a trained worker who operates, maintains, or repairs technical equipment","vi":"kỹ thuật viên; thợ kỹ thuật"}],"examples":[{"en":"The technician replaced a broken part in our washing machine.","vi":"Kỹ thuật viên đã thay thế một bộ phận bị hỏng trong máy giặt của chúng tôi.","audioKind":"ex"},{"en":"Laboratory technicians play an essential role in medical research by preparing samples and maintaining specialist equipment.","vi":"Các kỹ thuật viên phòng thí nghiệm đóng vai trò thiết yếu trong nghiên cứu y học bằng cách chuẩn bị mẫu vật và bảo trì thiết bị chuyên dụng.","audioKind":"ex2"}],"collocations":[{"en":"laboratory technician","vi":"kỹ thuật viên phòng thí nghiệm"},{"en":"maintenance technician","vi":"kỹ thuật viên bảo trì"},{"en":"qualified technician","vi":"kỹ thuật viên có trình độ"}],"wordFamily":["technical (adj.)","technically (adv.)","technique (n.)"],"synonyms":[],"antonyms":[],"tipVi":"technician nghiêng về vận hành và bảo trì thiết bị, không đồng nghĩa hoàn toàn với engineer.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_quarterly', 'en-b2-47', 'quarterly', '/ˈkwɔːrtərli/', 'B2', 'theo quý; diễn ra ba tháng một lần; mỗi quý một lần; tạp chí ra hàng quý; ấn phẩm quý', 'adj.', 'quarter (n.)', NULL, 'quarterly chỉ mỗi ba tháng một lần, không phải bốn tháng một lần.', 'Our club holds quarterly meetings at the local library.', NULL, 'Câu lạc bộ của chúng tôi tổ chức các cuộc họp hàng quý tại thư viện địa phương.', '{"wordId":"quarterly","ukIpa":"/ˈkwɔːtəli/","usIpa":"/ˈkwɔːrtərli/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"Happening or produced every three months.","vi":"theo quý; diễn ra ba tháng một lần"},{"pos":"adv.","en":"Once every three months.","vi":"mỗi quý một lần"},{"pos":"n.","en":"A magazine published every three months.","vi":"tạp chí ra hàng quý; ấn phẩm quý"}],"examples":[{"en":"Our club holds quarterly meetings at the local library.","vi":"Câu lạc bộ của chúng tôi tổ chức các cuộc họp hàng quý tại thư viện địa phương.","audioKind":"ex"},{"en":"Quarterly reports allow investors to monitor company performance and identify emerging financial risks throughout the year.","vi":"Các báo cáo hàng quý cho phép nhà đầu tư theo dõi hiệu quả hoạt động của công ty và nhận diện các rủi ro tài chính phát sinh trong suốt cả năm.","audioKind":"ex2"}],"collocations":[{"en":"quarterly report","vi":"báo cáo hàng quý"},{"en":"quarterly meeting","vi":"cuộc họp hàng quý"},{"en":"pay quarterly","vi":"thanh toán theo quý"}],"wordFamily":["quarter (n.)"],"synonyms":[],"antonyms":[],"tipVi":"quarterly chỉ mỗi ba tháng một lần, không phải bốn tháng một lần.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tailor', 'en-b2-47', 'tailor', '/ˈteɪlər/', 'B2', 'thợ may; điều chỉnh cho phù hợp; may đo', 'n.', 'tailoring (n.), tailored (adj.), tailor-made (adj.)', NULL, 'Cấu trúc tailor A to B có nghĩa là "điều chỉnh hoặc thiết kế A theo B".', 'The tailor shortened my trousers while I waited nearby.', NULL, 'Thợ may đã sửa ngắn chiếc quần của tôi trong lúc tôi đứng chờ gần đó.', '{"wordId":"tailor","ukIpa":"/ˈteɪlə/","usIpa":"/ˈteɪlər/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"someone who makes or alters clothes, especially suits","vi":"thợ may"},{"pos":"v.","en":"to make or adapt something for particular needs","vi":"điều chỉnh cho phù hợp; may đo"}],"examples":[{"en":"The tailor shortened my trousers while I waited nearby.","vi":"Thợ may đã sửa ngắn chiếc quần của tôi trong lúc tôi đứng chờ gần đó.","audioKind":"ex"},{"en":"Teachers should tailor their lessons to students'' abilities rather than follow a single approach for everyone.","vi":"Giáo viên nên điều chỉnh bài giảng cho phù hợp với năng lực của học sinh thay vì áp dụng một cách tiếp cận duy nhất cho tất cả mọi người.","audioKind":"ex2"}],"collocations":[{"en":"tailor a suit","vi":"may bộ vest"},{"en":"tailor something to individual needs","vi":"chỉnh sửa cái gì cho phù hợp với nhu cầu cá nhân"},{"en":"tailor-made clothes","vi":"quần áo may đo"}],"wordFamily":["tailoring (n.)","tailored (adj.)","tailor-made (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc tailor A to B có nghĩa là \"điều chỉnh hoặc thiết kế A theo B\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_corporation', 'en-b2-47', 'corporation', '/ˌkɔːrpəˈreɪʃən/', 'B2', 'tập đoàn lớn; công ty hợp pháp; cơ quan quản lý đô thị; chính quyền thành phố', 'n.', 'corporate (adj.), incorporate (v.), incorporation (n.)', 'Đồng nghĩa: company, business', 'Thường chỉ công ty lớn; tránh nhầm lẫn với cooperation (sự hợp tác).', 'My sister works for a corporation that makes furniture.', NULL, 'Chị tôi làm việc cho một tập đoàn chuyên sản xuất đồ gỗ.', '{"wordId":"corporation","ukIpa":"/ˌkɔːpəˈreɪʃən/","usIpa":"/ˌkɔːrpəˈreɪʃən/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"A legally established company, especially a large one.","vi":"tập đoàn lớn; công ty hợp pháp"},{"pos":"n.","en":"A governing body responsible for a town or city.","vi":"cơ quan quản lý đô thị; chính quyền thành phố"}],"examples":[{"en":"My sister works for a corporation that makes furniture.","vi":"Chị tôi làm việc cho một tập đoàn chuyên sản xuất đồ gỗ.","audioKind":"ex"},{"en":"A multinational corporation can create local jobs, but its profits may largely flow back to overseas shareholders.","vi":"Một tập đoàn đa quốc gia có thể tạo ra việc làm ở địa phương, nhưng lợi nhuận của nó phần lớn có thể chảy về cho các cổ đông ở nước ngoài.","audioKind":"ex2"}],"collocations":[{"en":"multinational corporation","vi":"tập đoàn đa quốc gia"},{"en":"large corporation","vi":"công ty lớn"},{"en":"municipal corporation","vi":"tổ chức pháp nhân đô thị"}],"wordFamily":["corporate (adj.)","incorporate (v.)","incorporation (n.)"],"synonyms":["company","business"],"antonyms":[],"tipVi":"Thường chỉ công ty lớn; tránh nhầm lẫn với cooperation (sự hợp tác).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prospect', 'en-b2-47', 'prospect', '/ˈprɑːspekt/', 'B2', 'khả năng; viễn cảnh; triển vọng; cơ hội thành công; thăm dò (khoáng sản, nhiên liệu)', 'n.', 'prospective (adj.), prospector (n.), prospecting (n.)', 'Đồng nghĩa: possibility, outlook', 'Khi mang nghĩa triển vọng thường dùng ở dạng số nhiều "prospects"; sau "of" có thể dùng danh động từ (V-ing).', 'The prospect of a beach holiday cheered us up.', NULL, 'Viễn cảnh về một kỳ nghỉ ở bãi biển đã làm chúng tôi phấn chấn hẳn lên.', '{"wordId":"prospect","ukIpa":"/ˈprɒspekt/","usIpa":"/ˈprɑːspekt/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"The possibility or expectation that something will happen.","vi":"khả năng; viễn cảnh"},{"pos":"n.","en":"Chances of future success or improvement.","vi":"triển vọng; cơ hội thành công"},{"pos":"v.","en":"To search an area for valuable minerals or fuels.","vi":"thăm dò (khoáng sản, nhiên liệu)"}],"examples":[{"en":"The prospect of a beach holiday cheered us up.","vi":"Viễn cảnh về một kỳ nghỉ ở bãi biển đã làm chúng tôi phấn chấn hẳn lên.","audioKind":"ex"},{"en":"Access to vocational training can improve employment prospects for young people in economically disadvantaged regions.","vi":"Việc tiếp cận đào tạo nghề có thể cải thiện triển vọng việc làm cho thanh niên ở các khu vực khó khăn về kinh tế.","audioKind":"ex2"}],"collocations":[{"en":"the prospect of","vi":"viễn cảnh về; khả năng..."},{"en":"employment prospects","vi":"triển vọng việc làm"},{"en":"a realistic prospect","vi":"một khả năng thực tế"},{"en":"prospect for gold","vi":"thăm dò vàng"}],"wordFamily":["prospective (adj.)","prospector (n.)","prospecting (n.)"],"synonyms":["possibility","outlook"],"antonyms":[],"tipVi":"Khi mang nghĩa triển vọng thường dùng ở dạng số nhiều \"prospects\"; sau \"of\" có thể dùng danh động từ (V-ing).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_headquarters', 'en-b2-47', 'headquarters', '/ˈhedˌkwɔːrtərz/', 'B2', 'trụ sở chính; tổng hành dinh', 'n.', NULL, NULL, 'Dạng số ít và số nhiều giống nhau, luôn giữ chữ "s" ở cuối từ.', 'She works at the company''s headquarters near the river.', NULL, 'Cô ấy làm việc tại trụ sở chính của công ty gần bờ sông.', '{"wordId":"headquarters","ukIpa":"/ˌhedˈkwɔːtəz/","usIpa":"/ˈhedˌkwɔːrtərz/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"The main place from which an organisation is directed.","vi":"trụ sở chính; tổng hành dinh"}],"examples":[{"en":"She works at the company''s headquarters near the river.","vi":"Cô ấy làm việc tại trụ sở chính của công ty gần bờ sông.","audioKind":"ex"},{"en":"Moving corporate headquarters to smaller cities can create jobs and reduce pressure on major urban centres.","vi":"Việc chuyển trụ sở doanh nghiệp về các thành phố nhỏ hơn có thể tạo ra việc làm và giảm áp lực cho các trung tâm đô thị lớn.","audioKind":"ex2"}],"collocations":[{"en":"corporate headquarters","vi":"trụ sở doanh nghiệp"},{"en":"regional headquarters","vi":"trụ sở khu vực"},{"en":"headquarters staff","vi":"nhân viên trụ sở chính"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số ít và số nhiều giống nhau, luôn giữ chữ \"s\" ở cuối từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_47_1', 'en-b2-47', 'Cách dùng “demanding” (adj.) — đòi hỏi nhiều nỗ lực; khắt khe; vất vả', 'physically demanding  ·  mentally demanding  ·  demanding job', 'Khi bổ nghĩa cho công việc, từ này chỉ sự vất vả; khi bổ nghĩa cho con người, từ này chỉ tính cách đòi hỏi cao, khó làm hài lòng.', 'Họ từ (Word Family): demand (v.), demand (n.), undemanding (adj.) | Đồng nghĩa: challenging, exacting · Trái nghĩa: undemanding, easy', '[{"hanzi":"After a demanding shift, I fell asleep on the bus.","pinyin":"","meaning":"Sau ca làm việc vất vả kéo dài, tôi đã ngủ thiếp đi trên xe buýt."},{"hanzi":"Physically demanding jobs may require additional safety measures to protect workers from injuries and long-term health problems.","pinyin":"","meaning":"Những công việc đòi hỏi thể lực cao có thể cần đến các biện pháp an toàn bổ sung để bảo vệ người lao động khỏi chấn thương và các vấn đề sức khỏe lâu dài."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_47_2', 'en-b2-47', 'Cách dùng “craftsman” (n.) — thợ thủ công; nghệ nhân', 'a skilled craftsman  ·  a master craftsman  ·  a traditional craftsman', 'Dạng số nhiều của từ này là "craftsmen"; nếu muốn dùng từ trung lập về giới tính, bạn có thể chọn "craftsperson".', 'Họ từ (Word Family): craft (n.), craftsmanship (n.), craftswoman (n.), craftsperson (n.) | Đồng nghĩa: artisan', '[{"hanzi":"The craftsman carved a wooden bird for the display.","pinyin":"","meaning":"Người thợ thủ công đã chạm trổ một con chim bằng gỗ để trưng bày."},{"hanzi":"Supporting local craftsmen can preserve traditional skills while providing communities with sustainable sources of income.","pinyin":"","meaning":"Việc hỗ trợ các nghệ nhân địa phương có thể bảo tồn các kỹ năng truyền thống đồng thời đem lại nguồn thu nhập bền vững cho cộng đồng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_47_3', 'en-b2-47', 'Cách dùng “prospect” (n.) — khả năng; viễn cảnh', 'the prospect of  ·  employment prospects  ·  a realistic prospect', 'Khi mang nghĩa triển vọng thường dùng ở dạng số nhiều "prospects"; sau "of" có thể dùng danh động từ (V-ing).', 'Họ từ (Word Family): prospective (adj.), prospector (n.), prospecting (n.) | Đồng nghĩa: possibility, outlook', '[{"hanzi":"The prospect of a beach holiday cheered us up.","pinyin":"","meaning":"Viễn cảnh về một kỳ nghỉ ở bãi biển đã làm chúng tôi phấn chấn hẳn lên."},{"hanzi":"Access to vocational training can improve employment prospects for young people in economically disadvantaged regions.","pinyin":"","meaning":"Việc tiếp cận đào tạo nghề có thể cải thiện triển vọng việc làm cho thanh niên ở các khu vực khó khăn về kinh tế."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_47_4', 'en-b2-47', 'Cách dùng “accomplish” (v.) — hoàn thành; đạt được; làm tròn', 'accomplish a task  ·  accomplish a goal  ·  accomplish a great deal', 'Là ngoại động từ, đi thẳng tới tân ngữ là nhiệm vụ hay mục tiêu, không đi kèm với động từ nguyên mẫu có to.', 'Họ từ (Word Family): accomplishment (n.), accomplished (adj.) | Đồng nghĩa: achieve, complete', '[{"hanzi":"We accomplished everything before the guests arrived for dinner.","pinyin":"","meaning":"Chúng tôi đã hoàn tất mọi việc trước khi khách đến ăn tối."},{"hanzi":"Students can accomplish more when teachers provide clear goals and regular feedback on their progress.","pinyin":"","meaning":"Học sinh có thể đạt được nhiều thành quả hơn khi giáo viên đưa ra các mục tiêu rõ ràng và phản hồi thường xuyên về tiến độ học tập của các em."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_47_1', 'en-b2-47', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
