INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_47_1_2', 'ten_b2_47_1', 'dismiss', 'Don''t dismiss her idea before you hear the details.', 'Don''t dismiss her idea before you hear the details.', '/dɪsˈmɪs/', 'Đừng vội gạt phăng ý kiến của cô ấy trước khi nghe rõ chi tiết.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_47_1_3', 'ten_b2_47_1', 'entrepreneur', 'The young entrepreneur opened a bakery near our station.', 'The young entrepreneur opened a bakery near our station.', '/ˌɑːntrəprəˈnɝː/', 'Nhà khởi nghiệp trẻ tuổi đã mở một tiệm bánh gần nhà ga của chúng tôi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_47_1_4', 'ten_b2_47_1', 'demanding', 'After a demanding shift, I fell asleep on the bus.', 'After a demanding shift, I fell asleep on the bus.', '/dɪˈmændɪŋ/', 'Sau ca làm việc vất vả kéo dài, tôi đã ngủ thiếp đi trên xe buýt.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_47_1_5', 'ten_b2_47_1', 'confidential', 'Please keep this confidential until I tell my family.', 'Please keep this confidential until I tell my family.', '/ˌkɑːnfɪˈdenʃəl/', 'Xin hãy giữ kín chuyện này cho đến khi tôi nói với gia đình mình.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_47_1_6', 'ten_b2_47_1', 'priority', 'Finding a warm home is our main priority now.', 'Finding a warm home is our main priority now.', '/praɪˈɔːrəti/', 'Tìm một ngôi nhà ấm cúng là ưu tiên hàng đầu của chúng tôi lúc này.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_47_1_7', 'ten_b2_47_1', 'proceed', 'We can proceed with dinner once everyone arrives.', 'We can proceed with dinner once everyone arrives.', '/prəˈsiːd/', 'Chúng ta có thể tiếp tục dùng bữa tối ngay khi mọi người đến đủ.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_47_1_8', 'ten_b2_47_1', 'devote', 'I devote an hour each evening to practising the piano.', 'I devote an hour each evening to practising the piano.', '/dɪˈvoʊt/', 'Tôi dành một giờ mỗi tối để luyện tập đàn piano.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_47_1_1', 'en-b2-47', 'ten_b2_47_1', 'listening', 'listening', 'The craftsman carved a wooden bird for the display.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Thợ may đã sửa ngắn chiếc quần của tôi trong lúc tôi đứng chờ gần đó.","Câu lạc bộ của chúng tôi tổ chức các cuộc họp hàng quý tại thư viện địa phương.","Kỹ thuật viên đã thay thế một bộ phận bị hỏng trong máy giặt của chúng tôi.","Người thợ thủ công đã chạm trổ một con chim bằng gỗ để trưng bày."]'::jsonb, 3, 'The craftsman carved a wooden bird for the display. → Người thợ thủ công đã chạm trổ một con chim bằng gỗ để trưng bày.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_47_1_2', 'en-b2-47', 'ten_b2_47_1', 'listening', 'listening', 'Don''t dismiss her idea before you hear the details.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Đừng vội gạt phăng ý kiến của cô ấy trước khi nghe rõ chi tiết.","Tự kinh doanh cho phép tôi tự chọn thời gian nghỉ ngơi.","Xin hãy giữ kín chuyện này cho đến khi tôi nói với gia đình mình.","Bạn cần phải xin phép trước để sử dụng phòng này."]'::jsonb, 0, 'Don''t dismiss her idea before you hear the details. → Đừng vội gạt phăng ý kiến của cô ấy trước khi nghe rõ chi tiết.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_47_1_3', 'en-b2-47', 'ten_b2_47_1', 'listening', 'listening', 'The young entrepreneur opened a bakery near our station.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chị tôi làm việc cho một tập đoàn chuyên sản xuất đồ gỗ.","Nhà khởi nghiệp trẻ tuổi đã mở một tiệm bánh gần nhà ga của chúng tôi.","Thợ may đã sửa ngắn chiếc quần của tôi trong lúc tôi đứng chờ gần đó.","Đừng vội gạt phăng ý kiến của cô ấy trước khi nghe rõ chi tiết."]'::jsonb, 1, 'The young entrepreneur opened a bakery near our station. → Nhà khởi nghiệp trẻ tuổi đã mở một tiệm bánh gần nhà ga của chúng tôi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_47_2', 'en-b2-47', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_47_2_1', 'ten_b2_47_2', 'craftsman', 'Supporting local craftsmen can preserve traditional skills while providing communities with sustainable sources of income.', 'Supporting local craftsmen can preserve traditional skills while providing communities with sustainable sources of income.', '/ˈkræftsmən/', 'Việc hỗ trợ các nghệ nhân địa phương có thể bảo tồn các kỹ năng truyền thống đồng thời đem lại nguồn thu nhập bền vững cho cộng đồng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_47_2_2', 'ten_b2_47_2', 'dismiss', 'Governments should not dismiss public concerns about the long-term environmental effects of industrial expansion.', 'Governments should not dismiss public concerns about the long-term environmental effects of industrial expansion.', '/dɪsˈmɪs/', 'Chính phủ không nên xem nhẹ những lo ngại của công chúng về tác động môi trường lâu dài của việc mở rộng công nghiệp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_47_2_3', 'ten_b2_47_2', 'entrepreneur', 'Local governments can support entrepreneurs by simplifying regulations and improving access to affordable loans.', 'Local governments can support entrepreneurs by simplifying regulations and improving access to affordable loans.', '/ˌɑːntrəprəˈnɝː/', 'Chính quyền địa phương có thể hỗ trợ các doanh nhân bằng cách đơn giản hóa các quy định và tạo điều kiện tiếp cận các khoản vay có lãi suất phải chăng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_47_2_4', 'ten_b2_47_2', 'demanding', 'Physically demanding jobs may require additional safety measures to protect workers from injuries and long-term health problems.', 'Physically demanding jobs may require additional safety measures to protect workers from injuries and long-term health problems.', '/dɪˈmændɪŋ/', 'Những công việc đòi hỏi thể lực cao có thể cần đến các biện pháp an toàn bổ sung để bảo vệ người lao động khỏi chấn thương và các vấn đề sức khỏe lâu dài.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_47_2_5', 'ten_b2_47_2', 'confidential', 'Hospitals must protect confidential patient information to maintain public trust in the healthcare system.', 'Hospitals must protect confidential patient information to maintain public trust in the healthcare system.', '/ˌkɑːnfɪˈdenʃəl/', 'Các bệnh viện phải bảo vệ thông tin bảo mật của bệnh nhân để duy trì niềm tin của công chúng vào hệ thống y tế.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_47_2_6', 'ten_b2_47_2', 'priority', 'Governments should give priority to preventive healthcare rather than focus exclusively on treating existing illnesses.', 'Governments should give priority to preventive healthcare rather than focus exclusively on treating existing illnesses.', '/praɪˈɔːrəti/', 'Chính phủ nên ưu tiên y tế dự phòng hơn là chỉ tập trung điều trị các bệnh hiện có.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_47_2_1', 'en-b2-47', 'ten_b2_47_2', 'listening', 'listening', 'Supporting local craftsmen can preserve traditional skills while providing communities with sustainable sources of income.', NULL, 'Trong câu vừa nghe, từ “craftsman” mang nghĩa nào sau đây?', '["lượng sử dụng; cách sử dụng","thợ thủ công; nghệ nhân","sự tuyệt vọng","xe đưa đón; phương tiện vận chuyển qua lại"]'::jsonb, 1, '“craftsman” (/ˈkræftsmən/): thợ thủ công; nghệ nhân. Câu đầy đủ: Supporting local craftsmen can preserve traditional skills while providing communities with sustainable sources of income.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_47_2_2', 'en-b2-47', 'ten_b2_47_2', 'listening', 'listening', 'Governments should not dismiss public concerns about the long-term environmental effects of industrial expansion.', NULL, 'Trong câu vừa nghe, từ “dismiss” mang nghĩa nào sau đây?', '["gạt bỏ; xem nhẹ; không màng tới","nhà phân phối; thương gia; người buôn bán","cách thức; phương thức","đèn lồng; đèn xách tay"]'::jsonb, 0, '“dismiss” (/dɪsˈmɪs/): gạt bỏ; xem nhẹ; không màng tới. Câu đầy đủ: Governments should not dismiss public concerns about the long-term environmental effects of industrial expansion.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
