INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_47_1', 'en-b2-47', NULL, 'comprehensive_test', 'listening', 'craftsman', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["hoàng đế; vị vua cai trị đế quốc","thợ thủ công; nghệ nhân","tài chính; sự cấp vốn; việc thu xếp vốn","ổn định; đều đặn"]'::jsonb, 1, 'craftsman (/ˈkræftsmən/) → thợ thủ công; nghệ nhân', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_47_2', 'en-b2-47', NULL, 'comprehensive_test', 'listening', 'Don''t dismiss her idea before you hear the details.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng ta có thể tiếp tục dùng bữa tối ngay khi mọi người đến đủ.","Tìm một ngôi nhà ấm cúng là ưu tiên hàng đầu của chúng tôi lúc này.","Đừng vội gạt phăng ý kiến của cô ấy trước khi nghe rõ chi tiết.","Chúng tôi đã thỏa thuận về việc phân chia công việc nhà một cách công bằng."]'::jsonb, 2, 'Don''t dismiss her idea before you hear the details. → Đừng vội gạt phăng ý kiến của cô ấy trước khi nghe rõ chi tiết.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_47_3', 'en-b2-47', NULL, 'comprehensive_test', 'listening', 'entrepreneur', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nhà u tư; chủ doanh nghiệp; doanh nhân","lòng tham; sự tham lam","vận chuyển trái phép; buôn lậu; lén mang vào","bó; búi; gói"]'::jsonb, 0, 'entrepreneur (/ˌɑːntrəprəˈnɝː/) → nhà u tư; chủ doanh nghiệp; doanh nhân', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_47_4', 'en-b2-47', NULL, 'comprehensive_test', 'listening', 'After a demanding shift, I fell asleep on the bus.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sau ca làm việc vất vả kéo dài, tôi đã ngủ thiếp đi trên xe buýt.","Huấn luyện viên đầy nhiệt huyết của chúng tôi luôn giữ cho mọi người vận động suốt buổi tập.","Chị tôi làm việc cho một tập đoàn chuyên sản xuất đồ gỗ.","Chúng ta có thể tiếp tục dùng bữa tối ngay khi mọi người đến đủ."]'::jsonb, 0, 'After a demanding shift, I fell asleep on the bus. → Sau ca làm việc vất vả kéo dài, tôi đã ngủ thiếp đi trên xe buýt.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_47_5', 'en-b2-47', NULL, 'comprehensive_test', 'listening', 'confidential', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bảo mật; kín; cơ mật","ngăn; ngăn tủ; khoang; toa xe lửa chia toa","trung thực; thành thật; đúng sự thật","Khu ổ chuột"]'::jsonb, 0, 'confidential (/ˌkɑːnfɪˈdenʃəl/) → bảo mật; kín; cơ mật', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_47_6', 'en-b2-47', NULL, 'comprehensive_test', 'listening', 'Finding a warm home is our main priority now.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tìm một ngôi nhà ấm cúng là ưu tiên hàng đầu của chúng tôi lúc này.","Mọi người đều thích đề xuất biến phòng trống thành văn phòng của tôi.","Đừng vội gạt phăng ý kiến của cô ấy trước khi nghe rõ chi tiết.","Thợ may đã sửa ngắn chiếc quần của tôi trong lúc tôi đứng chờ gần đó."]'::jsonb, 0, 'Finding a warm home is our main priority now. → Tìm một ngôi nhà ấm cúng là ưu tiên hàng đầu của chúng tôi lúc này.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_47_7', 'en-b2-47', NULL, 'comprehensive_test', 'listening', 'proceed', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["dành riêng; độc quyền","vụ thu hoạch; mùa gặt; sản lượng thu hoạch","động từ: tiếp tục tiến hành; tiếp theo","không còn tươi, ôi thiu (đặc biệt là bánh mì hoặc không khí)"]'::jsonb, 2, 'proceed (/prəˈsiːd/) → động từ: tiếp tục tiến hành; tiếp theo; động từ: đi đến; di chuyển về phía', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_47_8', 'en-b2-47', NULL, 'comprehensive_test', 'listening', 'I devote an hour each evening to practising the piano.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã thỏa thuận về việc phân chia công việc nhà một cách công bằng.","Tôi dành một giờ mỗi tối để luyện tập đàn piano.","Nhà khởi nghiệp trẻ tuổi đã mở một tiệm bánh gần nhà ga của chúng tôi.","Chúng tôi đã hoàn tất mọi việc trước khi khách đến ăn tối."]'::jsonb, 1, 'I devote an hour each evening to practising the piano. → Tôi dành một giờ mỗi tối để luyện tập đàn piano.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_47_9', 'en-b2-47', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Intended to remain private and not be shared without permission.”?', '["confidential","prospect","priority","former"]'::jsonb, 0, 'confidential (/ˌkɑːnfɪˈdenʃəl/) → bảo mật; kín; cơ mật', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_47_10', 'en-b2-47', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “something considered more important than other things”?', '["competent","priority","former","accomplish"]'::jsonb, 1, 'priority (/praɪˈɔːrəti/) → ưu tiên; việc ưu tiên; nhiệm vụ hàng đầu', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_47_11', 'en-b2-47', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Continue an activity or move to its next stage.”?', '["clause","priority","proceed","promising"]'::jsonb, 2, 'proceed (/prəˈsiːd/) → động từ: tiếp tục tiến hành; tiếp theo', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_47_12', 'en-b2-47', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To give time, effort, or resources to someone or something.”?', '["dynamic","promising","competent","devote"]'::jsonb, 3, 'devote (/dɪˈvoʊt/) → dành hết; cống hiến (thời gian, công sức, nguồn lực)', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_47_13', 'en-b2-47', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A suggested plan for others to consider.”?', '["prospect","clause","proposal","quarterly"]'::jsonb, 2, 'proposal (/prəˈpoʊzəl/) → đề xuất; kiến nghị; phương án', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
