INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_47_18', 'en-b2-47', NULL, 'comprehensive_test', 'reading', NULL, 'Supporting local craftsmen can preserve traditional skills while providing communities with sustainable sources of income.', 'Dựa vào câu trên, từ “craftsman” có nghĩa phù hợp nhất là gì?', '["áp đảo; vô cùng lớn, mạnh mẽ","thợ thủ công; nghệ nhân","khả năng xảy ra","khoa (trong trường đại học)"]'::jsonb, 1, 'craftsman: thợ thủ công; nghệ nhân. Dịch cả câu: Việc hỗ trợ các nghệ nhân địa phương có thể bảo tồn các kỹ năng truyền thống đồng thời đem lại nguồn thu nhập bền vững cho cộng đồng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_47_19', 'en-b2-47', NULL, 'comprehensive_test', 'reading', NULL, 'Governments should not dismiss public concerns about the long-term environmental effects of industrial expansion.', 'Dựa vào câu trên, từ “dismiss” có nghĩa phù hợp nhất là gì?', '["lấp lánh; tỏa sáng","gạt bỏ; xem nhẹ; không màng tới","rung; rung động; làm rung chuyển","thời gian trị vì; thời kỳ cầm quyền"]'::jsonb, 1, 'dismiss: gạt bỏ; xem nhẹ; không màng tới; sa thải; đuổi việc; cho phép rời đi; giải tán. Dịch cả câu: Chính phủ không nên xem nhẹ những lo ngại của công chúng về tác động môi trường lâu dài của việc mở rộng công nghiệp.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_47_20', 'en-b2-47', NULL, 'comprehensive_test', 'reading', NULL, 'Local governments can support entrepreneurs by simplifying regulations and improving access to affordable loans.', 'Dựa vào câu trên, từ “entrepreneur” có nghĩa phù hợp nhất là gì?', '["nhà u tư; chủ doanh nghiệp; doanh nhân","tác động; ảnh hưởng lớn","giàu trí tưởng tượng; sáng tạo","xúc phạm; lăng mạ; gây khó chịu"]'::jsonb, 0, 'entrepreneur: nhà u tư; chủ doanh nghiệp; doanh nhân. Dịch cả câu: Chính quyền địa phương có thể hỗ trợ các doanh nhân bằng cách đơn giản hóa các quy định và tạo điều kiện tiếp cận các khoản vay có lãi suất phải chăng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_47_21', 'en-b2-47', NULL, 'comprehensive_test', 'reading', NULL, 'Physically demanding jobs may require additional safety measures to protect workers from injuries and long-term health problems.', 'Dựa vào câu trên, từ “demanding” có nghĩa phù hợp nhất là gì?', '["rõ ràng; rành mạch","đòi hỏi nhiều nỗ lực; khắt khe; vất vả","người giám sát; cấp trên; quản lý","tủ chén; tủ đựng đồ"]'::jsonb, 1, 'demanding: đòi hỏi nhiều nỗ lực; khắt khe; vất vả; đòi hỏi cao; khó chiều. Dịch cả câu: Những công việc đòi hỏi thể lực cao có thể cần đến các biện pháp an toàn bổ sung để bảo vệ người lao động khỏi chấn thương và các vấn đề sức khỏe lâu dài.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
