INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-48', 'en', 'Bài 48: Công việc & Nghề nghiệp (3) - CEFR B2', 'CEFR B2', 'B2 · Công việc', '25 từ vựng Tiếng Anh CEFR B2 chủ đề công việc & nghề nghiệp kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4048, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_union', 'en-b2-48', 'union', '/ˈjuːnjən/', 'B2', 'công đoàn; sự liên hiệp; liên minh', 'n.', 'unite (v.), united (adj.), unionise (v.), unionisation (n.)', NULL, 'union bắt đầu bằng âm phụ âm /j/, vì vậy dùng a union thay vì an union.', 'The union helped staff negotiate better working hours.', NULL, 'Công đoàn đã giúp nhân viên thương lượng để có thời gian làm việc hợp lý hơn.', '{"wordId":"union","ukIpa":"/ˈjuːniən/","usIpa":"/ˈjuːnjən/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"an organisation that protects workers'' rights and interests","vi":"công đoàn"},{"pos":"n.","en":"the joining of people or groups, or the resulting organisation","vi":"sự liên hiệp; liên minh"}],"examples":[{"en":"The union helped staff negotiate better working hours.","vi":"Công đoàn đã giúp nhân viên thương lượng để có thời gian làm việc hợp lý hơn.","audioKind":"ex"},{"en":"Joining a union can give employees greater influence over decisions concerning workplace safety and fair pay.","vi":"Việc gia nhập công đoàn có thể giúp nhân viên có ảnh hưởng lớn hơn đối với các quyết định liên quan đến an toàn nơi làm việc và tiền lương công bằng.","audioKind":"ex2"}],"collocations":[{"en":"join a union","vi":"gia nhập công đoàn"},{"en":"trade union","vi":"công đoàn ngành"},{"en":"union representative","vi":"đại diện công đoàn"},{"en":"political union","vi":"liên minh chính trị"}],"wordFamily":["unite (v.)","united (adj.)","unionise (v.)","unionisation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"union bắt đầu bằng âm phụ âm /j/, vì vậy dùng a union thay vì an union.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_advisor', 'en-b2-48', 'advisor', '/ədˈvaɪzər/', 'B2', 'cố vấn; giáo viên hướng dẫn', 'n.', 'advise (v.), advice (n.), advisory (adj.)', 'Đồng nghĩa: adviser, consultant', 'Cả hai cách viết advisor và adviser đều đúng; tiếng Anh-Anh thường dùng adviser.', 'My advisor helped me choose courses for next term.', NULL, 'Giáo viên hướng dẫn đã giúp tôi chọn các môn học cho học kỳ tới.', '{"wordId":"advisor","ukIpa":"/ədˈvaɪzə/","usIpa":"/ədˈvaɪzər/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"someone whose job is to give guidance or expert advice","vi":"cố vấn; giáo viên hướng dẫn"}],"examples":[{"en":"My advisor helped me choose courses for next term.","vi":"Giáo viên hướng dẫn đã giúp tôi chọn các môn học cho học kỳ tới.","audioKind":"ex"},{"en":"A qualified financial advisor can help households plan for retirement and manage the risks of long-term investments.","vi":"Một cố vấn tài chính có năng lực có thể giúp các gia đình lên kế hoạch nghỉ hưu và quản lý rủi ro từ các khoản đầu tư dài hạn.","audioKind":"ex2"}],"collocations":[{"en":"financial advisor","vi":"cố vấn tài chính"},{"en":"academic advisor","vi":"giáo viên hướng dẫn học tập"},{"en":"careers advisor","vi":"cố vấn nghề nghiệp"}],"wordFamily":["advise (v.)","advice (n.)","advisory (adj.)"],"synonyms":["adviser","consultant"],"antonyms":[],"tipVi":"Cả hai cách viết advisor và adviser đều đúng; tiếng Anh-Anh thường dùng adviser.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_steward', 'en-b2-48', 'steward', '/ˈstuːərd/', 'B2', 'nhân viên phục vụ (trên tàu, máy bay hoặc tại sự kiện); tiếp viên; người quản lý; người bảo vệ; người gìn giữ; quản lý; chăm sóc và bảo vệ có trách nhiệm', 'n.', 'stewardship (n.)', NULL, 'Không chỉ chỉ tiếp viên; cụm a steward of còn có thể dùng để chỉ người bảo vệ tài nguyên.', 'A steward helped us find our seats before the concert.', NULL, 'Một nhân viên phục vụ đã giúp chúng tôi tìm chỗ ngồi trước khi buổi hòa nhạc bắt đầu.', '{"wordId":"steward","ukIpa":"/ˈstjuːəd/","usIpa":"/ˈstuːərd/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"Someone who assists passengers or people attending an event.","vi":"nhân viên phục vụ (trên tàu, máy bay hoặc tại sự kiện); tiếp viên"},{"pos":"n.","en":"Someone responsible for caring for property or resources.","vi":"người quản lý; người bảo vệ; người gìn giữ"},{"pos":"v.","en":"To manage or protect resources responsibly.","vi":"quản lý; chăm sóc và bảo vệ có trách nhiệm"}],"examples":[{"en":"A steward helped us find our seats before the concert.","vi":"Một nhân viên phục vụ đã giúp chúng tôi tìm chỗ ngồi trước khi buổi hòa nhạc bắt đầu.","audioKind":"ex"},{"en":"Local communities can act as stewards of natural habitats when they receive adequate funding and decision-making powers.","vi":"Các cộng đồng địa phương có thể đóng vai trò là những người gìn giữ các sinh cảnh tự nhiên nếu họ nhận được đầy đủ nguồn vốn và quyền ra quyết định.","audioKind":"ex2"}],"collocations":[{"en":"a ship''s steward","vi":"tiếp viên tàu thủy"},{"en":"a steward of natural resources","vi":"người bảo vệ tài nguyên thiên nhiên"},{"en":"steward resources","vi":"quản lý tài nguyên"}],"wordFamily":["stewardship (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Không chỉ chỉ tiếp viên; cụm a steward of còn có thể dùng để chỉ người bảo vệ tài nguyên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chairman', 'en-b2-48', 'chairman', '/ˈtʃermən/', 'B2', 'chủ tịch; chủ tịch hội đồng quản trị; người điều hành cuộc họp', 'n.', 'chair (n.), chairperson (n.), chairmanship (n.)', 'Đồng nghĩa: chairperson, chair', 'Từ trung tính về giới tính có thể dùng chair hoặc chairperson.', 'The chairman welcomed everyone and opened the meeting.', NULL, 'Chủ tịch đã chào mừng mọi người và tuyên bố khai mạc cuộc họp.', '{"wordId":"chairman","ukIpa":"/ˈtʃeəmən/","usIpa":"/ˈtʃermən/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"a person, usually a man, who leads a meeting or organisation","vi":"chủ tịch; chủ tịch hội đồng quản trị; người điều hành cuộc họp"}],"examples":[{"en":"The chairman welcomed everyone and opened the meeting.","vi":"Chủ tịch đã chào mừng mọi người và tuyên bố khai mạc cuộc họp.","audioKind":"ex"},{"en":"The chairman of the committee urged members to consider how the proposed policy would affect rural communities.","vi":"Chủ tịch ủy ban thúc giục các thành viên cân nhắc xem chính sách đề xuất sẽ tác động như thế nào đến các cộng đồng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"chairman of the board","vi":"chủ tịch hội đồng quản trị"},{"en":"committee chairman","vi":"chủ tịch ủy ban"},{"en":"appoint a chairman","vi":"bổ nhiệm chủ tịch"}],"wordFamily":["chair (n.)","chairperson (n.)","chairmanship (n.)"],"synonyms":["chairperson","chair"],"antonyms":[],"tipVi":"Từ trung tính về giới tính có thể dùng chair hoặc chairperson.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_specialty', 'en-b2-48', 'specialty', '/ˈspeʃəlti/', 'B2', 'chuyên môn; sở trường; đặc sản; món ăn đặc trưng', 'n.', 'special (adj.), specialist (n.), specialise (v.), specialisation (n.)', 'Đồng nghĩa: specialism', 'Mỹ thường dùng specialty; Anh cũng thường dùng speciality.', 'Baking fruit pies has always been my grandmother''s specialty.', NULL, 'Nướng bánh tart trái cây luôn là sở trường của bà tôi.', '{"wordId":"specialty","ukIpa":"/ˈspeʃəlti/","usIpa":"/ˈspeʃəlti/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"a subject or activity someone has particular knowledge or skill in","vi":"chuyên môn; sở trường"},{"pos":"n.","en":"a food or product a person or place is known for","vi":"đặc sản; món ăn đặc trưng"}],"examples":[{"en":"Baking fruit pies has always been my grandmother''s specialty.","vi":"Nướng bánh tart trái cây luôn là sở trường của bà tôi.","audioKind":"ex"},{"en":"Choosing a medical specialty requires students to consider their interests alongside the healthcare needs of the wider population.","vi":"Việc lựa chọn một chuyên khoa y tế đòi hỏi sinh viên phải cân nhắc sở thích cá nhân bên cạnh nhu cầu chăm sóc sức khỏe của đông đảo người dân.","audioKind":"ex2"}],"collocations":[{"en":"medical specialty","vi":"chuyên khoa y tế"},{"en":"local specialty","vi":"đặc sản địa phương"},{"en":"house specialty","vi":"món đặc sản của quán"},{"en":"area of specialty","vi":"lĩnh vực chuyên môn"}],"wordFamily":["special (adj.)","specialist (n.)","specialise (v.)","specialisation (n.)"],"synonyms":["specialism"],"antonyms":[],"tipVi":"Mỹ thường dùng specialty; Anh cũng thường dùng speciality.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stall', 'en-b2-48', 'stall', '/stɔːl/', 'B2', 'quầy hàng; sạp hàng; làm đình trệ; trì hoãn; tắt máy; chết máy', 'n.', 'stallholder (n.)', NULL, 'Động từ có thể chỉ động cơ bị chết máy hoặc đàm phán bị đình trệ.', 'We bought fresh peaches from a small roadside stall.', NULL, 'Chúng tôi đã mua đào tươi ở một quầy hàng nhỏ ven đường.', '{"wordId":"stall","ukIpa":"/stɔːl/","usIpa":"/stɔːl/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"A small stand or space where goods are sold.","vi":"quầy hàng; sạp hàng"},{"pos":"v.","en":"To stop progress or deliberately delay action.","vi":"làm đình trệ; trì hoãn"},{"pos":"v.","en":"For an engine to stop unexpectedly, or cause this.","vi":"tắt máy; chết máy"}],"examples":[{"en":"We bought fresh peaches from a small roadside stall.","vi":"Chúng tôi đã mua đào tươi ở một quầy hàng nhỏ ven đường.","audioKind":"ex"},{"en":"Negotiations may stall if governments cannot agree on how to share the costs of reducing emissions.","vi":"Các cuộc đàm phán có thể rơi vào bế tắc nếu các chính phủ không thể thống nhất cách chia sẻ chi phí giảm phát thải.","audioKind":"ex2"}],"collocations":[{"en":"market stall","vi":"gian hàng chợ"},{"en":"stall for time","vi":"cố tình kéo dài thời gian"},{"en":"stall an engine","vi":"làm xe chết máy"}],"wordFamily":["stallholder (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ có thể chỉ động cơ bị chết máy hoặc đàm phán bị đình trệ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_off-duty', 'en-b2-48', 'off-duty', '/ˌɔːf ˈduːti/', 'B2', 'ngoài giờ làm việc; không trực ca; hạ ca', 'adj.', 'duty (n.)', 'Trái nghĩa: on-duty', 'Dùng off-duty trước danh từ; khi làm vị ngữ thường viết là off duty.', 'An off-duty nurse helped when my grandfather fell.', NULL, 'Một y tá đang nghỉ ca đã giúp đỡ khi ông tôi bị ngã.', '{"wordId":"off-duty","ukIpa":"/ˌɒf ˈdjuːti/","usIpa":"/ˌɔːf ˈduːti/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"not working during a particular period","vi":"ngoài giờ làm việc; không trực ca; hạ ca"}],"examples":[{"en":"An off-duty nurse helped when my grandfather fell.","vi":"Một y tá đang nghỉ ca đã giúp đỡ khi ông tôi bị ngã.","audioKind":"ex"},{"en":"Providing comfortable accommodation allows off-duty staff to rest properly, improving their performance during subsequent shifts.","vi":"Việc cung cấp chỗ ở thoải mái cho phép nhân viên ngoài giờ làm việc nghỉ ngơi đầy đủ, từ đó cải thiện hiệu suất làm việc trong các ca tiếp theo.","audioKind":"ex2"}],"collocations":[{"en":"off-duty staff","vi":"nhân viên ngoài giờ làm việc"},{"en":"an off-duty nurse","vi":"một y tá đang nghỉ ca"},{"en":"off-duty hours","vi":"thời gian ngoài giờ làm"}],"wordFamily":["duty (n.)"],"synonyms":[],"antonyms":["on-duty"],"tipVi":"Dùng off-duty trước danh từ; khi làm vị ngữ thường viết là off duty.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deputy', 'en-b2-48', 'deputy', '/ˈdepjuti/', 'B2', 'cấp phó; người đại diện; người phụ tá; đại biểu quốc hội', 'n.', 'deputise (v.)', NULL, 'Thường đặt trước chức vụ, như deputy director; không dùng để chỉ chung mọi đại diện.', 'The manager asked her deputy to lead today''s meeting.', NULL, 'Quản lý đã yêu cầu phó của mình chủ trì cuộc họp hôm nay.', '{"wordId":"deputy","ukIpa":"/ˈdepjuti/","usIpa":"/ˈdepjuti/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"someone authorised to assist or act for a more senior person","vi":"cấp phó; người đại diện; người phụ tá"},{"pos":"n.","en":"an elected member of parliament in some countries","vi":"đại biểu quốc hội"}],"examples":[{"en":"The manager asked her deputy to lead today''s meeting.","vi":"Quản lý đã yêu cầu phó của mình chủ trì cuộc họp hôm nay.","audioKind":"ex"},{"en":"Appointing a capable deputy allows school leaders to share administrative responsibilities and focus on educational improvement.","vi":"Việc bổ nhiệm một phó quản lý năng lực cho phép ban giám hiệu trường học chia sẻ trách nhiệm quản lý và tập trung vào việc cải thiện giáo dục.","audioKind":"ex2"}],"collocations":[{"en":"deputy director","vi":"phó giám đốc; phó cục trưởng"},{"en":"deputy head","vi":"phó hiệu trưởng"},{"en":"appoint a deputy","vi":"bổ nhiệm phó thủ trưởng"},{"en":"act as deputy","vi":"làm phó; làm người đại diện"}],"wordFamily":["deputise (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường đặt trước chức vụ, như deputy director; không dùng để chỉ chung mọi đại diện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_placement', 'en-b2-48', 'placement', '/ˈpleɪsmənt/', 'B2', 'công việc thực tập; đợt thực tập; sự đặt, sự bố trí, sự sắp xếp; sự tuyển dụng; sự sắp xếp vị trí việc làm', 'n.', 'place (v.), replace (v.), replacement (n.)', NULL, 'Trong tiếng Anh Anh, work placement thường chỉ đợt thực tập trong chương trình học.', 'I learned practical skills during my hospital placement.', NULL, 'Tôi đã học được các kỹ năng thực tế trong đợt thực tập tại bệnh viện.', '{"wordId":"placement","ukIpa":"/ˈpleɪsmənt/","usIpa":"/ˈpleɪsmənt/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"A temporary job that provides practical experience during training.","vi":"công việc thực tập; đợt thực tập"},{"pos":"n.","en":"The act of putting something in a particular position.","vi":"sự đặt, sự bố trí, sự sắp xếp"},{"pos":"n.","en":"The act of finding someone a suitable position or home.","vi":"sự tuyển dụng; sự sắp xếp vị trí việc làm"}],"examples":[{"en":"I learned practical skills during my hospital placement.","vi":"Tôi đã học được các kỹ năng thực tế trong đợt thực tập tại bệnh viện.","audioKind":"ex"},{"en":"Universities should offer work placements so that students can apply classroom knowledge in professional settings.","vi":"Các trường đại học nên cung cấp các kỳ thực tập làm việc để sinh viên có thể ứng dụng kiến thức trên lớp vào môi trường chuyên nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"work placement","vi":"thực tập làm việc"},{"en":"job placement","vi":"sắp xếp việc làm"},{"en":"product placement","vi":"quảng cáo lồng ghép sản phẩm"}],"wordFamily":["place (v.)","replace (v.)","replacement (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh Anh, work placement thường chỉ đợt thực tập trong chương trình học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_organizational', 'en-b2-48', 'organizational', '/ˌɔːrɡənəˈzeɪʃənəl/', 'B2', 'thuộc về tổ chức; thuộc cơ cấu tổ chức; thuộc về việc tổ chức, sắp xếp công việc', 'adj.', 'organization (n.), organize (v.), organizer (n.), organizationally (adv.)', NULL, 'Trong tiếng Anh Anh còn được viết là organisational.', 'The new manager announced several organizational changes this morning.', NULL, 'Giám đốc mới đã công bố một số thay đổi về cơ cấu tổ chức vào sáng nay.', '{"wordId":"organizational","ukIpa":"/ˌɔːɡənaɪˈzeɪʃənəl/","usIpa":"/ˌɔːrɡənəˈzeɪʃənəl/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"Relating to the structure or management of an organization.","vi":"thuộc về tổ chức; thuộc cơ cấu tổ chức"},{"pos":"adj.","en":"Relating to planning activities and arranging things effectively.","vi":"thuộc về việc tổ chức, sắp xếp công việc"}],"examples":[{"en":"The new manager announced several organizational changes this morning.","vi":"Giám đốc mới đã công bố một số thay đổi về cơ cấu tổ chức vào sáng nay.","audioKind":"ex"},{"en":"A clear organizational structure can improve communication between departments and help employees understand their responsibilities.","vi":"Cơ cấu tổ chức rõ ràng có thể cải thiện giao tiếp giữa các phòng ban và giúp nhân viên hiểu rõ trách nhiệm của mình.","audioKind":"ex2"}],"collocations":[{"en":"organizational structure","vi":"cơ cấu tổ chức"},{"en":"organizational change","vi":"thay đổi tổ chức"},{"en":"organizational skills","vi":"kỹ năng tổ chức"},{"en":"organizational culture","vi":"văn hóa tổ chức"}],"wordFamily":["organization (n.)","organize (v.)","organizer (n.)","organizationally (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh Anh còn được viết là organisational.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cooperative', 'en-b2-48', 'cooperative', '/koʊˈɑːpərətɪv/', 'B2', 'hợp tác; sẵn sàng giúp đỡ; hợp tác xã', 'adj.', 'cooperate (v.), cooperation (n.), cooperatively (adv.)', 'Đồng nghĩa: helpful, collaborative · Trái nghĩa: uncooperative', 'Dùng làm tính từ để chỉ tính hợp tác; làm danh từ để chỉ hợp tác xã.', 'Everyone was cooperative when we rearranged the shared kitchen.', NULL, 'Mọi người đều rất hợp tác khi chúng tôi sắp xếp lại nhà bếp chung.', '{"wordId":"cooperative","ukIpa":"/kəʊˈɒpərətɪv/","usIpa":"/koʊˈɑːpərətɪv/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"willing to help others or work together","vi":"hợp tác; sẵn sàng giúp đỡ"},{"pos":"n.","en":"a business owned and run jointly by its members","vi":"hợp tác xã"}],"examples":[{"en":"Everyone was cooperative when we rearranged the shared kitchen.","vi":"Mọi người đều rất hợp tác khi chúng tôi sắp xếp lại nhà bếp chung.","audioKind":"ex"},{"en":"Cooperative learning can help students develop communication skills while taking shared responsibility for completing a task.","vi":"Việc học tập hợp tác có thể giúp học sinh phát triển các kỹ năng giao tiếp đồng thời cùng chịu trách nhiệm hoàn thành nhiệm vụ.","audioKind":"ex2"}],"collocations":[{"en":"cooperative approach","vi":"phương pháp hợp tác"},{"en":"cooperative learning","vi":"học tập hợp tác"},{"en":"agricultural cooperative","vi":"hợp tác xã nông nghiệp"}],"wordFamily":["cooperate (v.)","cooperation (n.)","cooperatively (adv.)"],"synonyms":["helpful","collaborative"],"antonyms":["uncooperative"],"tipVi":"Dùng làm tính từ để chỉ tính hợp tác; làm danh từ để chỉ hợp tác xã.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_query', 'en-b2-48', 'query', '/ˈkwɪri/', 'B2', 'câu hỏi; thắc mắc; sự truy vấn; đặt câu hỏi; hoài nghi', 'n.', NULL, 'Đồng nghĩa: question, enquiry', 'Động từ query có thể đi trực tiếp với đối tượng phí tổn hoặc quyết định bị thắc mắc.', 'The receptionist answered my query about the swimming pool.', NULL, 'Nhân viên tiếp tân đã giải đáp thắc mắc của tôi về hồ bơi.', '{"wordId":"query","ukIpa":"/ˈkwɪəri/","usIpa":"/ˈkwɪri/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"A question or request for information","vi":"câu hỏi; thắc mắc; sự truy vấn"},{"pos":"v.","en":"To ask about something or question whether it is correct","vi":"đặt câu hỏi; thắc mắc; hoài nghi"}],"examples":[{"en":"The receptionist answered my query about the swimming pool.","vi":"Nhân viên tiếp tân đã giải đáp thắc mắc của tôi về hồ bơi.","audioKind":"ex"},{"en":"Consumers should query unexpected charges on their bills rather than assume that automated payment systems are always accurate.","vi":"Người tiêu dùng nên lên tiếng thắc mắc về những khoản phí bất ngờ trên hóa đơn thay vì mặc định rằng hệ thống thanh toán tự động lúc nào cũng chính xác.","audioKind":"ex2"}],"collocations":[{"en":"answer a query","vi":"giải đáp thắc mắc"},{"en":"raise a query","vi":"đưa ra câu hỏi"},{"en":"query a charge","vi":"thắc mắc về một khoản phí"},{"en":"a database query","vi":"truy vấn cơ sở dữ liệu"}],"wordFamily":[],"synonyms":["question","enquiry"],"antonyms":[],"tipVi":"Động từ query có thể đi trực tiếp với đối tượng phí tổn hoặc quyết định bị thắc mắc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_negotiation', 'en-b2-48', 'negotiation', '/nɪˌɡoʊʃiˈeɪʃən/', 'B2', 'đàm phán; thương lượng', 'n.', 'negotiate (v.), negotiator (n.), negotiable (adj.)', 'Đồng nghĩa: talks, discussions', 'Quá trình đàm phán thường dùng dạng không đếm được; các vòng đàm phán thường dùng số nhiều.', 'After some negotiation, we agreed on a fair price.', NULL, 'Sau một hồi thương lượng, chúng tôi đã chốt được một mức giá hợp lý.', '{"wordId":"negotiation","ukIpa":"/nɪˌɡəʊʃiˈeɪʃən/","usIpa":"/nɪˌɡoʊʃiˈeɪʃən/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"Discussion aimed at reaching an agreement between different parties.","vi":"đàm phán; thương lượng"}],"examples":[{"en":"After some negotiation, we agreed on a fair price.","vi":"Sau một hồi thương lượng, chúng tôi đã chốt được một mức giá hợp lý.","audioKind":"ex"},{"en":"Successful negotiation between employers and workers can prevent disputes and improve conditions throughout an industry.","vi":"Cuộc đàm phán thành công giữa người sử dụng lao động và người lao động có thể ngăn chặn các tranh chấp và cải thiện điều kiện làm việc trong toàn ngành.","audioKind":"ex2"}],"collocations":[{"en":"enter into negotiations","vi":"bắt đầu đàm phán"},{"en":"negotiation skills","vi":"kỹ năng đàm phán"},{"en":"under negotiation","vi":"đang trong quá trình thương lượng"},{"en":"peace negotiations","vi":"đàm phán hòa bình"}],"wordFamily":["negotiate (v.)","negotiator (n.)","negotiable (adj.)"],"synonyms":["talks","discussions"],"antonyms":[],"tipVi":"Quá trình đàm phán thường dùng dạng không đếm được; các vòng đàm phán thường dùng số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_retain', 'en-b2-48', 'retain', '/rɪˈteɪn/', 'B2', 'giữ lại; duy trì; ghi nhớ; nhớ; thuê dịch vụ; chiêu mộ', 'v.', 'retention (n.), retentive (adj.)', 'Đồng nghĩa: keep, preserve · Trái nghĩa: lose', 'Là từ trang trọng, đi trực tiếp với tân ngữ; việc ghi nhớ kiến thức cũng có thể dùng retain.', 'This old house still retains its original wooden doors.', NULL, 'Ngôi nhà cổ này vẫn giữ được những cánh cửa gỗ nguyên bản.', '{"wordId":"retain","ukIpa":"/rɪˈteɪn/","usIpa":"/rɪˈteɪn/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"keep or continue to have something","vi":"giữ lại; duy trì"},{"pos":"v.","en":"keep information in your memory","vi":"ghi nhớ; nhớ"},{"pos":"v.","en":"pay to keep someone''s professional services available","vi":"thuê dịch vụ; chiêu mộ"}],"examples":[{"en":"This old house still retains its original wooden doors.","vi":"Ngôi nhà cổ này vẫn giữ được những cánh cửa gỗ nguyên bản.","audioKind":"ex"},{"en":"Flexible working arrangements can help companies retain experienced employees while improving overall job satisfaction.","vi":"Các chế độ làm việc linh hoạt có thể giúp doanh nghiệp giữ chân nhân viên giàu kinh nghiệm đồng thời nâng cao sự hài lòng chung trong công việc.","audioKind":"ex2"}],"collocations":[{"en":"retain control","vi":"giữ quyền kiểm soát"},{"en":"retain information","vi":"ghi nhớ thông tin"},{"en":"retain staff","vi":"giữ chân nhân sự"},{"en":"retain moisture","vi":"giữ ẩm"}],"wordFamily":["retention (n.)","retentive (adj.)"],"synonyms":["keep","preserve"],"antonyms":["lose"],"tipVi":"Là từ trang trọng, đi trực tiếp với tân ngữ; việc ghi nhớ kiến thức cũng có thể dùng retain.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_batch', 'en-b2-48', 'batch', '/bætʃ/', 'B2', 'một mẻ; một đợt; xử lý theo đợt; gom thành nhóm', 'n.', NULL, NULL, 'batch nhấn mạnh một nhóm được sản xuất hoặc xử lý cùng nhau, thường đi với of.', 'The first batch of bread is cooling on the counter.', NULL, 'Mẻ bánh mì đầu tiên đang được để nguội trên mặt bàn.', '{"wordId":"batch","ukIpa":"/bætʃ/","usIpa":"/bætʃ/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"A group of things made or dealt with together.","vi":"một mẻ; một đợt"},{"pos":"v.","en":"Arrange or process things together in groups.","vi":"xử lý theo đợt; gom thành nhóm"}],"examples":[{"en":"The first batch of bread is cooling on the counter.","vi":"Mẻ bánh mì đầu tiên đang được để nguội trên mặt bàn.","audioKind":"ex"},{"en":"Testing each batch of food before distribution helps manufacturers maintain consistent quality and protect public health.","vi":"Việc kiểm tra từng mẻ thực phẩm trước khi phân phối giúp các nhà sản xuất duy trì chất lượng đồng đều và bảo vệ sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"a batch of","vi":"một loạt; một mẻ"},{"en":"in batches","vi":"theo từng đợt"},{"en":"batch production","vi":"sản xuất theo mẻ"},{"en":"batch processing","vi":"xử lý hàng loạt"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"batch nhấn mạnh một nhóm được sản xuất hoặc xử lý cùng nhau, thường đi với of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inspector', 'en-b2-48', 'inspector', '/ɪnˈspektər/', 'B2', 'thanh tra; thanh tra viên; cảnh sát cấp thanh tra; thanh tra cảnh sát', 'n.', 'inspect (v.), inspection (n.)', NULL, 'inspect là kiểm tra; inspector chỉ người thực hiện kiểm tra.', 'The inspector checked the kitchen before the restaurant opened.', NULL, 'Thanh tra viên đã kiểm tra khu bếp trước khi nhà hàng mở cửa.', '{"wordId":"inspector","ukIpa":"/ɪnˈspektə/","usIpa":"/ɪnˈspektər/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"an official who checks that rules and standards are followed","vi":"thanh tra; thanh tra viên"},{"pos":"n.","en":"a police officer of a particular rank","vi":"cảnh sát cấp thanh tra; thanh tra cảnh sát"}],"examples":[{"en":"The inspector checked the kitchen before the restaurant opened.","vi":"Thanh tra viên đã kiểm tra khu bếp trước khi nhà hàng mở cửa.","audioKind":"ex"},{"en":"A qualified building inspector can identify structural problems before they become serious risks to public safety.","vi":"Một thanh tra xây dựng đủ trình độ có thể nhận diện các vấn đề kết cấu trước khi chúng trở thành mối nguy hiểm nghiêm trọng đối với an toàn công cộng.","audioKind":"ex2"}],"collocations":[{"en":"safety inspector","vi":"thanh tra an toàn"},{"en":"building inspector","vi":"thanh tra xây dựng"},{"en":"police inspector","vi":"thanh tra cảnh sát"}],"wordFamily":["inspect (v.)","inspection (n.)"],"synonyms":[],"antonyms":[],"tipVi":"inspect là kiểm tra; inspector chỉ người thực hiện kiểm tra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_teller', 'en-b2-48', 'teller', '/ˈtelər/', 'B2', 'giao dịch viên ngân hàng', 'n.', 'tell (v.)', NULL, 'Thường chỉ giao dịch viên ngân hàng, không phải nhân viên thu ngân ("cashier") ở cửa hàng.', 'The teller counted the cash and handed me a receipt.', NULL, 'Giao dịch viên ngân hàng đã đếm tiền mặt và đưa cho tôi một tờ biên lai.', '{"wordId":"teller","ukIpa":"/ˈtelə/","usIpa":"/ˈtelər/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"A bank employee who handles customers'' money","vi":"giao dịch viên ngân hàng"}],"examples":[{"en":"The teller counted the cash and handed me a receipt.","vi":"Giao dịch viên ngân hàng đã đếm tiền mặt và đưa cho tôi một tờ biên lai.","audioKind":"ex"},{"en":"Although online banking is convenient, bank tellers remain important for customers who need personal assistance.","vi":"Mặc dù ngân hàng trực tuyến rất tiện lợi, các giao dịch viên ngân hàng vẫn rất quan trọng đối với những khách hàng cần sự hỗ trợ trực tiếp.","audioKind":"ex2"}],"collocations":[{"en":"bank teller","vi":"giao dịch viên ngân hàng"},{"en":"teller window","vi":"quầy giao dịch ngân hàng"},{"en":"automated teller machine","vi":"máy rút tiền tự động (ATM)"}],"wordFamily":["tell (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ giao dịch viên ngân hàng, không phải nhân viên thu ngân (\"cashier\") ở cửa hàng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_workload', 'en-b2-48', 'workload', '/ˈwɝːkloʊd/', 'B2', 'khối lượng công việc; lượng công việc mà ai đó phải hoàn thành trong một khoảng thời gian nhất định', 'n.', 'work (n.), work (v.), worker (n.)', NULL, 'Khối lượng công việc lớn dùng heavy workload, không dùng hard workload.', 'My workload doubled when two colleagues went on holiday.', NULL, 'Khối lượng công việc của tôi tăng gấp đôi khi hai đồng nghiệp nghỉ phép.', '{"wordId":"workload","ukIpa":"/ˈwɜːkləʊd/","usIpa":"/ˈwɝːkloʊd/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"The amount of work someone must complete within a particular period.","vi":"khối lượng công việc; lượng công việc mà ai đó phải hoàn thành trong một khoảng thời gian nhất định"}],"examples":[{"en":"My workload doubled when two colleagues went on holiday.","vi":"Khối lượng công việc của tôi tăng gấp đôi khi hai đồng nghiệp nghỉ phép.","audioKind":"ex"},{"en":"Employers should monitor staff workload carefully to prevent stress and maintain the quality of their services.","vi":"Người sử dụng lao động nên theo dõi kỹ khối lượng công việc của nhân viên để ngăn ngừa áp lực và duy trì chất lượng dịch vụ.","audioKind":"ex2"}],"collocations":[{"en":"heavy workload","vi":"khối lượng công việc nặng nhọc"},{"en":"manageable workload","vi":"khối lượng công việc vừa phải"},{"en":"reduce the workload","vi":"giảm khối lượng công việc"},{"en":"share the workload","vi":"chia sẻ công việc"}],"wordFamily":["work (n.)","work (v.)","worker (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khối lượng công việc lớn dùng heavy workload, không dùng hard workload.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_agency', 'en-b2-48', 'agency', '/ˈeɪdʒənsi/', 'B2', 'hãng; đại lý; doanh nghiệp sắp xếp các dịch vụ cho cá nhân hoặc doanh nghiệp khác; cơ quan; tổ chức chịu trách nhiệm về một lĩnh vực công việc cụ thể; năng lực tự chủ; khả năng tự đưa ra lựa chọn và hành động độc lập', 'n.', 'agent (n.)', NULL, 'Khi chỉ tổ chức/cơ quan thì đếm được; khi chỉ năng lực tự chủ thì thường không đếm được.', 'The travel agency booked our flights and hotel.', NULL, 'Công ty du lịch đã đặt vé máy bay và khách sạn cho chúng tôi.', '{"wordId":"agency","ukIpa":"/ˈeɪdʒənsi/","usIpa":"/ˈeɪdʒənsi/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"A business that arranges services for people or other businesses.","vi":"hãng; đại lý; doanh nghiệp sắp xếp các dịch vụ cho cá nhân hoặc doanh nghiệp khác"},{"pos":"n.","en":"An organisation responsible for a particular area of work.","vi":"cơ quan; tổ chức chịu trách nhiệm về một lĩnh vực công việc cụ thể"},{"pos":"n.","en":"The ability to make choices and act independently.","vi":"năng lực tự chủ; khả năng tự đưa ra lựa chọn và hành động độc lập"}],"examples":[{"en":"The travel agency booked our flights and hotel.","vi":"Công ty du lịch đã đặt vé máy bay và khách sạn cho chúng tôi.","audioKind":"ex"},{"en":"A national environmental agency should monitor industrial pollution and ensure that factories comply with safety regulations.","vi":"Một cơ quan môi trường quốc gia nên giám sát ô nhiễm công nghiệp và đảm bảo các nhà máy tuân thủ các quy định an toàn.","audioKind":"ex2"}],"collocations":[{"en":"a travel agency","vi":"công ty du lịch"},{"en":"a recruitment agency","vi":"trung tâm môi giới việc làm"},{"en":"a government agency","vi":"cơ quan chính phủ"},{"en":"individual agency","vi":"năng lực tự chủ cá nhân"}],"wordFamily":["agent (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ tổ chức/cơ quan thì đếm được; khi chỉ năng lực tự chủ thì thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_provided', 'en-b2-48', 'provided', '/prəˈvaɪdɪd/', 'B2', 'miễn là; với điều kiện là; cung cấp; đã cung cấp (dạng quá khứ và phân từ hai của provide)', 'conj.', 'provide (v.), provider (n.), provision (n.)', 'Đồng nghĩa: providing, if', 'Liên từ provided (that) biểu thị điều kiện; từ that có thể được lược bỏ.', 'You can borrow my bike provided you return it tonight.', NULL, 'Bạn có thể mượn xe đạp của tôi miễn là bạn trả lại nó vào tối nay.', '{"wordId":"provided","ukIpa":"/prəˈvaɪdɪd/","usIpa":"/prəˈvaɪdɪd/","cefr":"B2","topic":"work","senses":[{"pos":"conj.","en":"Only if a particular condition is met.","vi":"miễn là; với điều kiện là"},{"pos":"v.","en":"Gave something needed; past tense and past participle of provide.","vi":"cung cấp; đã cung cấp (dạng quá khứ và phân từ hai của provide)"}],"examples":[{"en":"You can borrow my bike provided you return it tonight.","vi":"Bạn có thể mượn xe đạp của tôi miễn là bạn trả lại nó vào tối nay.","audioKind":"ex"},{"en":"Remote working can improve employee satisfaction, provided that organisations offer adequate technical support and clear communication channels.","vi":"Làm việc từ xa có thể nâng cao sự hài lòng của nhân viên, miễn là các cơ quan cung cấp đầy đủ hỗ trợ kỹ thuật và kênh giao tiếp rõ ràng.","audioKind":"ex2"}],"collocations":[{"en":"provided that","vi":"miễn là; với điều kiện là"},{"en":"services provided","vi":"các dịch vụ đã cung cấp"},{"en":"information provided","vi":"thông tin đã cung cấp"}],"wordFamily":["provide (v.)","provider (n.)","provision (n.)"],"synonyms":["providing","if"],"antonyms":[],"tipVi":"Liên từ provided (that) biểu thị điều kiện; từ that có thể được lược bỏ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_resign', 'en-b2-48', 'resign', '/rɪˈzaɪn/', 'B2', 'từ chức; xin thôi việc; đành chịu; cam chịu', 'v.', 'resignation (n.), resigned (adj.)', 'Đồng nghĩa: quit, step down', 'resign oneself to sau đi với danh từ hoặc danh động từ, thể hiện sự đành lòng chấp nhận.', 'She decided to resign and open a small bakery.', NULL, 'Cô ấy quyết định từ chức và mở một tiệm bánh nhỏ.', '{"wordId":"resign","ukIpa":"/rɪˈzaɪn/","usIpa":"/rɪˈzaɪn/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"To officially leave a job or position.","vi":"từ chức; xin thôi việc"},{"pos":"v.","en":"To accept an unpleasant situation because you cannot change it.","vi":"đành chịu; cam chịu"}],"examples":[{"en":"She decided to resign and open a small bakery.","vi":"Cô ấy quyết định từ chức và mở một tiệm bánh nhỏ.","audioKind":"ex"},{"en":"Employees may resign when excessive workloads and limited career opportunities make their positions increasingly difficult to sustain.","vi":"Nhân viên có thể từ chức khi khối lượng công việc quá lớn và cơ hội thăng tiến hạn chế khiến cho vị trí của họ ngày càng khó duy trì.","audioKind":"ex2"}],"collocations":[{"en":"resign from a job","vi":"từ bỏ công việc"},{"en":"resign as chair","vi":"từ chức chủ tịch"},{"en":"resign yourself to","vi":"đành chấp nhận"}],"wordFamily":["resignation (n.)","resigned (adj.)"],"synonyms":["quit","step down"],"antonyms":[],"tipVi":"resign oneself to sau đi với danh từ hoặc danh động từ, thể hiện sự đành lòng chấp nhận.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_interruption', 'en-b2-48', 'interruption', '/ˌɪntəˈrʌpʃən/', 'B2', 'sự ngắt quãng; sự gián đoạn; sự quấy rầy', 'n.', 'interrupt (v.), uninterrupted (adj.)', 'Đồng nghĩa: disruption, disturbance', 'Một lần ngắt quãng là danh từ đếm được; cụm "without interruption" dùng để chỉ sự liên tục không ngắt.', 'Sorry for the interruption, but your taxi is here.', NULL, 'Xin lỗi vì đã làm phiền, nhưng xe taxi của bạn đến rồi.', '{"wordId":"interruption","ukIpa":"/ˌɪntəˈrʌpʃən/","usIpa":"/ˌɪntəˈrʌpʃən/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"Something that briefly stops an activity, conversation, or continuous process.","vi":"sự ngắt quãng; sự gián đoạn; sự quấy rầy"}],"examples":[{"en":"Sorry for the interruption, but your taxi is here.","vi":"Xin lỗi vì đã làm phiền, nhưng xe taxi của bạn đến rồi.","audioKind":"ex"},{"en":"Frequent interruptions in open offices can reduce concentration and make complex tasks take longer to complete.","vi":"Việc bị gián đoạn liên tục ở văn phòng làm việc chung có thể làm giảm khả năng tập trung và khiến các nhiệm vụ phức tạp mất nhiều thời gian hoàn thành hơn.","audioKind":"ex2"}],"collocations":[{"en":"without interruption","vi":"không bị gián đoạn"},{"en":"constant interruptions","vi":"sự gián đoạn liên tục"},{"en":"interruption to services","vi":"sự gián đoạn dịch vụ"}],"wordFamily":["interrupt (v.)","uninterrupted (adj.)"],"synonyms":["disruption","disturbance"],"antonyms":[],"tipVi":"Một lần ngắt quãng là danh từ đếm được; cụm \"without interruption\" dùng để chỉ sự liên tục không ngắt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_assign', 'en-b2-48', 'assign', '/əˈsaɪn/', 'B2', 'phân công; giao nhiệm vụ; ấn định; gán cho', 'v.', 'assignment (n.)', 'Đồng nghĩa: allocate, allot', 'Thường dùng cấu trúc assign sth to sb, hoặc có thể dùng assign sb sth.', 'The coach assigned each player a partner for practice.', NULL, 'Huấn luyện viên đã phân cho mỗi cầu thủ một bạn cặp để tập luyện.', '{"wordId":"assign","ukIpa":"/əˈsaɪn/","usIpa":"/əˈsaɪn/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"To give someone a task, role, or resource","vi":"phân công; giao nhiệm vụ"},{"pos":"v.","en":"To give something a particular value or category","vi":"ấn định; gán cho"}],"examples":[{"en":"The coach assigned each player a partner for practice.","vi":"Huấn luyện viên đã phân cho mỗi cầu thủ một bạn cặp để tập luyện.","audioKind":"ex"},{"en":"Teachers should assign tasks that match students'' abilities while encouraging them to develop new skills.","vi":"Giáo viên nên giao các nhiệm vụ phù hợp với năng lực của học sinh đồng thời khuyến khích các em phát triển các kỹ năng mới.","audioKind":"ex2"}],"collocations":[{"en":"assign a task","vi":"giao nhiệm vụ"},{"en":"assign responsibility","vi":"phân công trách nhiệm"},{"en":"assign someone to a team","vi":"phân bổ ai vào một đội"},{"en":"assign a value","vi":"gán giá trị"}],"wordFamily":["assignment (n.)"],"synonyms":["allocate","allot"],"antonyms":[],"tipVi":"Thường dùng cấu trúc assign sth to sb, hoặc có thể dùng assign sb sth.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reject', 'en-b2-48', 'reject', '/rɪˈdʒekt/', 'B2', 'từ chối; bác bỏ; loại bỏ; thải loại; hàng lỗi; hàng kém chất lượng', 'v.', 'rejection (n.)', 'Đồng nghĩa: refuse, decline · Trái nghĩa: accept, approve', 'Động từ có trọng âm ở âm tiết sau; danh từ có trọng âm ở âm tiết đầu, đọc là /ˈriːdʒekt/.', 'The shop rejected my offer for the old bicycle.', NULL, 'Cửa hàng đã từ chối mức giá tôi đưa ra cho chiếc xe đạp cũ.', '{"wordId":"reject","ukIpa":"/rɪˈdʒekt/","usIpa":"/rɪˈdʒekt/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"To refuse to accept, approve, or believe something.","vi":"từ chối; bác bỏ"},{"pos":"v.","en":"To remove something because it is faulty or unsuitable.","vi":"loại bỏ; thải loại"},{"pos":"n.","en":"An item not accepted because it fails to meet standards.","vi":"hàng lỗi; hàng kém chất lượng"}],"examples":[{"en":"The shop rejected my offer for the old bicycle.","vi":"Cửa hàng đã từ chối mức giá tôi đưa ra cho chiếc xe đạp cũ.","audioKind":"ex"},{"en":"Local authorities may reject construction proposals if developers cannot demonstrate that nearby wildlife habitats will be protected.","vi":"Chính quyền địa phương có thể bác bỏ các đề xuất xây dựng nếu các nhà phát triển không thể chứng minh rằng môi trường sống của động vật hoang dã gần đó sẽ được bảo vệ.","audioKind":"ex2"}],"collocations":[{"en":"reject a proposal","vi":"bác bỏ một đề xuất"},{"en":"reject an application","vi":"từ chối một đơn xin"},{"en":"reject a claim","vi":"bác bỏ một khiếu nại"},{"en":"reject defective products","vi":"loại bỏ sản phẩm lỗi"}],"wordFamily":["rejection (n.)"],"synonyms":["refuse","decline"],"antonyms":["accept","approve"],"tipVi":"Động từ có trọng âm ở âm tiết sau; danh từ có trọng âm ở âm tiết đầu, đọc là /ˈriːdʒekt/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inspection', 'en-b2-48', 'inspection', '/ɪnˈspekʃən/', 'B2', 'sự kiểm tra, sự thanh tra (xem xét kỹ lưỡng để đánh giá tình trạng, chất lượng hoặc độ an toàn)', 'n.', 'inspect (v.), inspector (n.)', 'Đồng nghĩa: examination', '"inspection" chỉ quá trình kiểm tra; kiểm tra cái gì thì dùng giới từ "of".', 'The mechanic found a loose cable during the inspection.', NULL, 'Thợ máy đã phát hiện một dây cáp bị lỏng trong quá trình kiểm tra.', '{"wordId":"inspection","ukIpa":"/ɪnˈspekʃən/","usIpa":"/ɪnˈspekʃən/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"A careful examination to check condition, quality, or safety.","vi":"sự kiểm tra, sự thanh tra (xem xét kỹ lưỡng để đánh giá tình trạng, chất lượng hoặc độ an toàn)"}],"examples":[{"en":"The mechanic found a loose cable during the inspection.","vi":"Thợ máy đã phát hiện một dây cáp bị lỏng trong quá trình kiểm tra.","audioKind":"ex"},{"en":"Regular inspection of public buildings can identify structural problems before they become serious safety risks.","vi":"Việc kiểm tra định kỳ các tòa nhà công cộng có thể phát hiện các vấn đề về kết cấu trước khi chúng trở thành rủi ro an toàn nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"carry out an inspection","vi":"tiến hành kiểm tra"},{"en":"safety inspection","vi":"kiểm tra an toàn"},{"en":"on closer inspection","vi":"qua kiểm tra kỹ hơn"}],"wordFamily":["inspect (v.)","inspector (n.)"],"synonyms":["examination"],"antonyms":[],"tipVi":"\"inspection\" chỉ quá trình kiểm tra; kiểm tra cái gì thì dùng giới từ \"of\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_48_1', 'en-b2-48', 'Cách dùng “interruption” (n.) — sự ngắt quãng; sự gián đoạn; sự quấy rầy', 'without interruption  ·  constant interruptions  ·  interruption to services', 'Một lần ngắt quãng là danh từ đếm được; cụm "without interruption" dùng để chỉ sự liên tục không ngắt.', 'Họ từ (Word Family): interrupt (v.), uninterrupted (adj.) | Đồng nghĩa: disruption, disturbance', '[{"hanzi":"Sorry for the interruption, but your taxi is here.","pinyin":"","meaning":"Xin lỗi vì đã làm phiền, nhưng xe taxi của bạn đến rồi."},{"hanzi":"Frequent interruptions in open offices can reduce concentration and make complex tasks take longer to complete.","pinyin":"","meaning":"Việc bị gián đoạn liên tục ở văn phòng làm việc chung có thể làm giảm khả năng tập trung và khiến các nhiệm vụ phức tạp mất nhiều thời gian hoàn thành hơn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_48_2', 'en-b2-48', 'Cách dùng “retain” (v.) — giữ lại; duy trì', 'retain control  ·  retain information  ·  retain staff', 'Là từ trang trọng, đi trực tiếp với tân ngữ; việc ghi nhớ kiến thức cũng có thể dùng retain.', 'Họ từ (Word Family): retention (n.), retentive (adj.) | Đồng nghĩa: keep, preserve · Trái nghĩa: lose', '[{"hanzi":"This old house still retains its original wooden doors.","pinyin":"","meaning":"Ngôi nhà cổ này vẫn giữ được những cánh cửa gỗ nguyên bản."},{"hanzi":"Flexible working arrangements can help companies retain experienced employees while improving overall job satisfaction.","pinyin":"","meaning":"Các chế độ làm việc linh hoạt có thể giúp doanh nghiệp giữ chân nhân viên giàu kinh nghiệm đồng thời nâng cao sự hài lòng chung trong công việc."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_48_3', 'en-b2-48', 'Cách dùng “negotiation” (n.) — đàm phán; thương lượng', 'enter into negotiations  ·  negotiation skills  ·  under negotiation', 'Quá trình đàm phán thường dùng dạng không đếm được; các vòng đàm phán thường dùng số nhiều.', 'Họ từ (Word Family): negotiate (v.), negotiator (n.), negotiable (adj.) | Đồng nghĩa: talks, discussions', '[{"hanzi":"After some negotiation, we agreed on a fair price.","pinyin":"","meaning":"Sau một hồi thương lượng, chúng tôi đã chốt được một mức giá hợp lý."},{"hanzi":"Successful negotiation between employers and workers can prevent disputes and improve conditions throughout an industry.","pinyin":"","meaning":"Cuộc đàm phán thành công giữa người sử dụng lao động và người lao động có thể ngăn chặn các tranh chấp và cải thiện điều kiện làm việc trong toàn ngành."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_48_4', 'en-b2-48', 'Cách dùng “teller” (n.) — giao dịch viên ngân hàng', 'bank teller  ·  teller window  ·  automated teller machine', 'Thường chỉ giao dịch viên ngân hàng, không phải nhân viên thu ngân ("cashier") ở cửa hàng.', 'Họ từ (Word Family): tell (v.)', '[{"hanzi":"The teller counted the cash and handed me a receipt.","pinyin":"","meaning":"Giao dịch viên ngân hàng đã đếm tiền mặt và đưa cho tôi một tờ biên lai."},{"hanzi":"Although online banking is convenient, bank tellers remain important for customers who need personal assistance.","pinyin":"","meaning":"Mặc dù ngân hàng trực tuyến rất tiện lợi, các giao dịch viên ngân hàng vẫn rất quan trọng đối với những khách hàng cần sự hỗ trợ trực tiếp."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_48_1', 'en-b2-48', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_48_1_1', 'ten_b2_48_1', 'union', 'The union helped staff negotiate better working hours.', 'The union helped staff negotiate better working hours.', '/ˈjuːnjən/', 'Công đoàn đã giúp nhân viên thương lượng để có thời gian làm việc hợp lý hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_48_1_2', 'ten_b2_48_1', 'advisor', 'My advisor helped me choose courses for next term.', 'My advisor helped me choose courses for next term.', '/ədˈvaɪzər/', 'Giáo viên hướng dẫn đã giúp tôi chọn các môn học cho học kỳ tới.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_48_1_3', 'ten_b2_48_1', 'steward', 'A steward helped us find our seats before the concert.', 'A steward helped us find our seats before the concert.', '/ˈstuːərd/', 'Một nhân viên phục vụ đã giúp chúng tôi tìm chỗ ngồi trước khi buổi hòa nhạc bắt đầu.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_48_1_4', 'ten_b2_48_1', 'chairman', 'The chairman welcomed everyone and opened the meeting.', 'The chairman welcomed everyone and opened the meeting.', '/ˈtʃermən/', 'Chủ tịch đã chào mừng mọi người và tuyên bố khai mạc cuộc họp.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_48_1_5', 'ten_b2_48_1', 'specialty', 'Baking fruit pies has always been my grandmother''s specialty.', 'Baking fruit pies has always been my grandmother''s specialty.', '/ˈspeʃəlti/', 'Nướng bánh tart trái cây luôn là sở trường của bà tôi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
