INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_48_1_7', 'ten_b2_48_1', 'off-duty', 'An off-duty nurse helped when my grandfather fell.', 'An off-duty nurse helped when my grandfather fell.', '/ˌɔːf ˈduːti/', 'Một y tá đang nghỉ ca đã giúp đỡ khi ông tôi bị ngã.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_48_1_8', 'ten_b2_48_1', 'deputy', 'The manager asked her deputy to lead today''s meeting.', 'The manager asked her deputy to lead today''s meeting.', '/ˈdepjuti/', 'Quản lý đã yêu cầu phó của mình chủ trì cuộc họp hôm nay.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_48_1_1', 'en-b2-48', 'ten_b2_48_1', 'listening', 'listening', 'The union helped staff negotiate better working hours.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Thợ máy đã phát hiện một dây cáp bị lỏng trong quá trình kiểm tra.","Giáo viên hướng dẫn đã giúp tôi chọn các môn học cho học kỳ tới.","Chủ tịch đã chào mừng mọi người và tuyên bố khai mạc cuộc họp.","Công đoàn đã giúp nhân viên thương lượng để có thời gian làm việc hợp lý hơn."]'::jsonb, 3, 'The union helped staff negotiate better working hours. → Công đoàn đã giúp nhân viên thương lượng để có thời gian làm việc hợp lý hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_48_1_2', 'en-b2-48', 'ten_b2_48_1', 'listening', 'listening', 'My advisor helped me choose courses for next term.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Giám đốc mới đã công bố một số thay đổi về cơ cấu tổ chức vào sáng nay.","Thợ máy đã phát hiện một dây cáp bị lỏng trong quá trình kiểm tra.","Xin lỗi vì đã làm phiền, nhưng xe taxi của bạn đến rồi.","Giáo viên hướng dẫn đã giúp tôi chọn các môn học cho học kỳ tới."]'::jsonb, 3, 'My advisor helped me choose courses for next term. → Giáo viên hướng dẫn đã giúp tôi chọn các môn học cho học kỳ tới.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_48_1_3', 'en-b2-48', 'ten_b2_48_1', 'listening', 'listening', 'A steward helped us find our seats before the concert.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bạn có thể mượn xe đạp của tôi miễn là bạn trả lại nó vào tối nay.","Cửa hàng đã từ chối mức giá tôi đưa ra cho chiếc xe đạp cũ.","Chủ tịch đã chào mừng mọi người và tuyên bố khai mạc cuộc họp.","Một nhân viên phục vụ đã giúp chúng tôi tìm chỗ ngồi trước khi buổi hòa nhạc bắt đầu."]'::jsonb, 3, 'A steward helped us find our seats before the concert. → Một nhân viên phục vụ đã giúp chúng tôi tìm chỗ ngồi trước khi buổi hòa nhạc bắt đầu.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_48_2', 'en-b2-48', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_48_2_1', 'ten_b2_48_2', 'union', 'Joining a union can give employees greater influence over decisions concerning workplace safety and fair pay.', 'Joining a union can give employees greater influence over decisions concerning workplace safety and fair pay.', '/ˈjuːnjən/', 'Việc gia nhập công đoàn có thể giúp nhân viên có ảnh hưởng lớn hơn đối với các quyết định liên quan đến an toàn nơi làm việc và tiền lương công bằng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_48_2_2', 'ten_b2_48_2', 'advisor', 'A qualified financial advisor can help households plan for retirement and manage the risks of long-term investments.', 'A qualified financial advisor can help households plan for retirement and manage the risks of long-term investments.', '/ədˈvaɪzər/', 'Một cố vấn tài chính có năng lực có thể giúp các gia đình lên kế hoạch nghỉ hưu và quản lý rủi ro từ các khoản đầu tư dài hạn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_48_2_3', 'ten_b2_48_2', 'steward', 'Local communities can act as stewards of natural habitats when they receive adequate funding and decision-making powers.', 'Local communities can act as stewards of natural habitats when they receive adequate funding and decision-making powers.', '/ˈstuːərd/', 'Các cộng đồng địa phương có thể đóng vai trò là những người gìn giữ các sinh cảnh tự nhiên nếu họ nhận được đầy đủ nguồn vốn và quyền ra quyết định.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_48_2_4', 'ten_b2_48_2', 'chairman', 'The chairman of the committee urged members to consider how the proposed policy would affect rural communities.', 'The chairman of the committee urged members to consider how the proposed policy would affect rural communities.', '/ˈtʃermən/', 'Chủ tịch ủy ban thúc giục các thành viên cân nhắc xem chính sách đề xuất sẽ tác động như thế nào đến các cộng đồng nông thôn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_48_2_5', 'ten_b2_48_2', 'specialty', 'Choosing a medical specialty requires students to consider their interests alongside the healthcare needs of the wider population.', 'Choosing a medical specialty requires students to consider their interests alongside the healthcare needs of the wider population.', '/ˈspeʃəlti/', 'Việc lựa chọn một chuyên khoa y tế đòi hỏi sinh viên phải cân nhắc sở thích cá nhân bên cạnh nhu cầu chăm sóc sức khỏe của đông đảo người dân.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_48_2_6', 'ten_b2_48_2', 'stall', 'Negotiations may stall if governments cannot agree on how to share the costs of reducing emissions.', 'Negotiations may stall if governments cannot agree on how to share the costs of reducing emissions.', '/stɔːl/', 'Các cuộc đàm phán có thể rơi vào bế tắc nếu các chính phủ không thể thống nhất cách chia sẻ chi phí giảm phát thải.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_48_2_1', 'en-b2-48', 'ten_b2_48_2', 'listening', 'listening', 'Joining a union can give employees greater influence over decisions concerning workplace safety and fair pay.', NULL, 'Trong câu vừa nghe, từ “union” mang nghĩa nào sau đây?', '["đối phó; đương đầu; giải quyết","công đoàn","nhà kho; kho hàng","cơn khát"]'::jsonb, 1, '“union” (/ˈjuːnjən/): công đoàn. Câu đầy đủ: Joining a union can give employees greater influence over decisions concerning workplace safety and fair pay.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_48_2_2', 'en-b2-48', 'ten_b2_48_2', 'listening', 'listening', 'A qualified financial advisor can help households plan for retirement and manage the risks of long-term investments.', NULL, 'Trong câu vừa nghe, từ “advisor” mang nghĩa nào sau đây?', '["cố vấn; giáo viên hướng dẫn","nghiêm trọng; dữ dội; tàn khốc","sự hạn chế; quy định hạn chế","kỳ lạ; bất thường (đôi khi theo cách khó chịu)"]'::jsonb, 0, '“advisor” (/ədˈvaɪzər/): cố vấn; giáo viên hướng dẫn. Câu đầy đủ: A qualified financial advisor can help households plan for retirement and manage the risks of long-term investments.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
