INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_48_1', 'en-b2-48', NULL, 'comprehensive_test', 'listening', 'union', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tiếp thị; marketing","xem là; coi như","thuộc về toán học; có tính toán học","công đoàn"]'::jsonb, 3, 'union (/ˈjuːnjən/) → công đoàn; sự liên hiệp; liên minh', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_48_2', 'en-b2-48', NULL, 'comprehensive_test', 'listening', 'My advisor helped me choose courses for next term.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Giáo viên hướng dẫn đã giúp tôi chọn các môn học cho học kỳ tới.","Thanh tra viên đã kiểm tra khu bếp trước khi nhà hàng mở cửa.","Giám đốc mới đã công bố một số thay đổi về cơ cấu tổ chức vào sáng nay.","Chúng tôi đã mua đào tươi ở một quầy hàng nhỏ ven đường."]'::jsonb, 0, 'My advisor helped me choose courses for next term. → Giáo viên hướng dẫn đã giúp tôi chọn các môn học cho học kỳ tới.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_48_3', 'en-b2-48', NULL, 'comprehensive_test', 'listening', 'steward', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cải cách; cải tiến (hệ thống)","phương tiện thông tin đại chúng; đại chúng truyền thông","nhân viên phục vụ (trên tàu, máy bay hoặc tại sự kiện); tiếp viên","tàn bạo; dã man; hung ác"]'::jsonb, 2, 'steward (/ˈstuːərd/) → nhân viên phục vụ (trên tàu, máy bay hoặc tại sự kiện); tiếp viên; người quản lý; người bảo vệ; người gìn giữ; quản lý; chăm sóc và bảo vệ có trách nhiệm', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_48_4', 'en-b2-48', NULL, 'comprehensive_test', 'listening', 'The chairman welcomed everyone and opened the meeting.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Thanh tra viên đã kiểm tra khu bếp trước khi nhà hàng mở cửa.","Chủ tịch đã chào mừng mọi người và tuyên bố khai mạc cuộc họp.","Huấn luyện viên đã phân cho mỗi cầu thủ một bạn cặp để tập luyện.","Nhân viên tiếp tân đã giải đáp thắc mắc của tôi về hồ bơi."]'::jsonb, 1, 'The chairman welcomed everyone and opened the meeting. → Chủ tịch đã chào mừng mọi người và tuyên bố khai mạc cuộc họp.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_48_5', 'en-b2-48', NULL, 'comprehensive_test', 'listening', 'specialty', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chuyên môn; sở trường","lông vũ; chiếc lông chim","bầu; bầu chọn","thuộc về văn học"]'::jsonb, 0, 'specialty (/ˈspeʃəlti/) → chuyên môn; sở trường; đặc sản; món ăn đặc trưng', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_48_6', 'en-b2-48', NULL, 'comprehensive_test', 'listening', 'We bought fresh peaches from a small roadside stall.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Mẻ bánh mì đầu tiên đang được để nguội trên mặt bàn.","Xin lỗi vì đã làm phiền, nhưng xe taxi của bạn đến rồi.","Công ty du lịch đã đặt vé máy bay và khách sạn cho chúng tôi.","Chúng tôi đã mua đào tươi ở một quầy hàng nhỏ ven đường."]'::jsonb, 3, 'We bought fresh peaches from a small roadside stall. → Chúng tôi đã mua đào tươi ở một quầy hàng nhỏ ven đường.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
