INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_48_8', 'en-b2-48', NULL, 'comprehensive_test', 'listening', 'The manager asked her deputy to lead today''s meeting.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ngôi nhà cổ này vẫn giữ được những cánh cửa gỗ nguyên bản.","Khối lượng công việc của tôi tăng gấp đôi khi hai đồng nghiệp nghỉ phép.","Quản lý đã yêu cầu phó của mình chủ trì cuộc họp hôm nay.","Xin lỗi vì đã làm phiền, nhưng xe taxi của bạn đến rồi."]'::jsonb, 2, 'The manager asked her deputy to lead today''s meeting. → Quản lý đã yêu cầu phó của mình chủ trì cuộc họp hôm nay.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
