INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_48_18', 'en-b2-48', NULL, 'comprehensive_test', 'reading', NULL, 'Joining a union can give employees greater influence over decisions concerning workplace safety and fair pay.', 'Dựa vào câu trên, từ “union” có nghĩa phù hợp nhất là gì?', '["tính chính xác; độ chính xác","lời nói nhảm; điều vô lý; chuyện nhảm nhí","công đoàn","đỏ mặt vì xấu hổ hoặc ngại ngùng"]'::jsonb, 2, 'union: công đoàn; sự liên hiệp; liên minh. Dịch cả câu: Việc gia nhập công đoàn có thể giúp nhân viên có ảnh hưởng lớn hơn đối với các quyết định liên quan đến an toàn nơi làm việc và tiền lương công bằng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_48_19', 'en-b2-48', NULL, 'comprehensive_test', 'reading', NULL, 'A qualified financial advisor can help households plan for retirement and manage the risks of long-term investments.', 'Dựa vào câu trên, từ “advisor” có nghĩa phù hợp nhất là gì?', '["cố vấn; giáo viên hướng dẫn","sổ tay; cẩm nang","bạn đồng hành; người bầu bạn; thú cưng bầu bạn","cô lập; cách ly"]'::jsonb, 0, 'advisor: cố vấn; giáo viên hướng dẫn. Dịch cả câu: Một cố vấn tài chính có năng lực có thể giúp các gia đình lên kế hoạch nghỉ hưu và quản lý rủi ro từ các khoản đầu tư dài hạn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_48_20', 'en-b2-48', NULL, 'comprehensive_test', 'reading', NULL, 'Local communities can act as stewards of natural habitats when they receive adequate funding and decision-making powers.', 'Dựa vào câu trên, từ “steward” có nghĩa phù hợp nhất là gì?', '["có tính truyền nhiễm; dễ lây lan","nhân viên phục vụ (trên tàu, máy bay hoặc tại sự kiện); tiếp viên","mỹ phẩm; đồ trang điểm","ưu tiên; việc ưu tiên; nhiệm vụ hàng đầu"]'::jsonb, 1, 'steward: nhân viên phục vụ (trên tàu, máy bay hoặc tại sự kiện); tiếp viên; người quản lý; người bảo vệ; người gìn giữ; quản lý; chăm sóc và bảo vệ có trách nhiệm. Dịch cả câu: Các cộng đồng địa phương có thể đóng vai trò là những người gìn giữ các sinh cảnh tự nhiên nếu họ nhận được đầy đủ nguồn vốn và quyền ra quyết định.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_48_21', 'en-b2-48', NULL, 'comprehensive_test', 'reading', NULL, 'The chairman of the committee urged members to consider how the proposed policy would affect rural communities.', 'Dựa vào câu trên, từ “chairman” có nghĩa phù hợp nhất là gì?', '["làm mát lạnh; sảng khoái; tỉnh táo","chủ tịch; chủ tịch hội đồng quản trị; người điều hành cuộc họp","tôm hùm","hoàn cảnh; điều kiện; trường hợp"]'::jsonb, 1, 'chairman: chủ tịch; chủ tịch hội đồng quản trị; người điều hành cuộc họp. Dịch cả câu: Chủ tịch ủy ban thúc giục các thành viên cân nhắc xem chính sách đề xuất sẽ tác động như thế nào đến các cộng đồng nông thôn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_48_22', 'en-b2-48', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “phân công; giao nhiệm vụ”', '["chatty","assign","estate","declaration"]'::jsonb, 1, 'phân công; giao nhiệm vụ → assign (/əˈsaɪn/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_48_23', 'en-b2-48', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “từ chối; bác bỏ”', '["reject","surgery","treaty","villain"]'::jsonb, 0, 'từ chối; bác bỏ → reject (/rɪˈdʒekt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_48_24', 'en-b2-48', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự kiểm tra, sự thanh tra (xem xét kỹ lưỡng để đánh giá tình trạng, chất lượng hoặc độ an toàn)”', '["inspection","evaluation","primarily","forth"]'::jsonb, 0, 'sự kiểm tra, sự thanh tra (xem xét kỹ lưỡng để đánh giá tình trạng, chất lượng hoặc độ an toàn) → inspection (/ɪnˈspekʃən/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-49', 'en', 'Bài 49: Công việc & Nghề nghiệp (4) - CEFR B2', 'CEFR B2', 'B2 · Công việc', '25 từ vựng Tiếng Anh CEFR B2 chủ đề công việc & nghề nghiệp kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4049, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_leadership', 'en-b2-49', 'leadership', '/ˈliːdərʃɪp/', 'B2', 'năng lực lãnh đạo, sự lãnh đạo (khả năng hoặc hoạt động dẫn dắt mọi người hướng tới các mục tiêu chung); ban lãnh đạo, giới lãnh đạo (những người điều hành một tổ chức hoặc quốc gia)', 'n.', 'lead (v.), leader (n.), leading (adj.)', NULL, 'Thường là danh từ không đếm được; có thể chỉ năng lực lãnh đạo hoặc ban lãnh đạo.', 'Her calm leadership helped our team finish the project.', NULL, 'Sự lãnh đạo điềm tĩnh của cô ấy đã giúp đội ngũ của chúng tôi hoàn thành dự án.', '{"wordId":"leadership","ukIpa":"/ˈliːdəʃɪp/","usIpa":"/ˈliːdərʃɪp/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"the ability or activity of guiding people towards shared goals","vi":"năng lực lãnh đạo, sự lãnh đạo (khả năng hoặc hoạt động dẫn dắt mọi người hướng tới các mục tiêu chung)"},{"pos":"n.","en":"the people who direct an organisation or country","vi":"ban lãnh đạo, giới lãnh đạo (những người điều hành một tổ chức hoặc quốc gia)"}],"examples":[{"en":"Her calm leadership helped our team finish the project.","vi":"Sự lãnh đạo điềm tĩnh của cô ấy đã giúp đội ngũ của chúng tôi hoàn thành dự án.","audioKind":"ex"},{"en":"Effective leadership in schools can improve staff morale and create a more supportive learning environment.","vi":"Năng lực lãnh đạo hiệu quả trong trường học có thể nâng cao tinh thần làm việc của giáo viên nhân viên và tạo ra môi trường học tập hỗ trợ tốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"leadership skills","vi":"kỹ năng lãnh đạo"},{"en":"strong leadership","vi":"sự lãnh đạo mạnh mẽ"},{"en":"under the leadership of","vi":"dưới sự lãnh đạo của"}],"wordFamily":["lead (v.)","leader (n.)","leading (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; có thể chỉ năng lực lãnh đạo hoặc ban lãnh đạo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_guideline', 'en-b2-49', 'guideline', '/ˈɡaɪdlaɪn/', 'B2', 'lời khuyên; nguyên tắc chỉ đạo; hướng dẫn; quy tắc', 'n.', NULL, 'Đồng nghĩa: guidance', 'Thường dùng ở dạng số nhiều guidelines; thường mang ý nghĩa hướng dẫn, tư vấn hơn là quy định bắt buộc.', 'These guidelines explain how to store food safely.', NULL, 'Những hướng dẫn này giải thích cách bảo quản thực phẩm an toàn.', '{"wordId":"guideline","ukIpa":"/ˈɡaɪdlaɪn/","usIpa":"/ˈɡaɪdlaɪn/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"Advice or a principle explaining how something should be done.","vi":"lời khuyên; nguyên tắc chỉ đạo; hướng dẫn; quy tắc"}],"examples":[{"en":"These guidelines explain how to store food safely.","vi":"Những hướng dẫn này giải thích cách bảo quản thực phẩm an toàn.","audioKind":"ex"},{"en":"Clear guidelines on data collection can help researchers protect participants while maintaining the quality of their studies.","vi":"Các hướng dẫn rõ ràng về việc thu thập dữ liệu có thể giúp các nhà nghiên cứu bảo vệ người tham gia đồng thời duy trì chất lượng nghiên cứu của họ.","audioKind":"ex2"}],"collocations":[{"en":"follow guidelines","vi":"tuân thủ hướng dẫn"},{"en":"issue guidelines","vi":"ban hành hướng dẫn"},{"en":"safety guidelines","vi":"hướng dẫn an toàn"},{"en":"clear guidelines","vi":"hướng dẫn rõ ràng"}],"wordFamily":[],"synonyms":["guidance"],"antonyms":[],"tipVi":"Thường dùng ở dạng số nhiều guidelines; thường mang ý nghĩa hướng dẫn, tư vấn hơn là quy định bắt buộc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recruit', 'en-b2-49', 'recruit', '/rɪˈkruːt/', 'B2', 'tuyển dụng; chiêu mộ; tuyển; nhân viên mới; thành viên mới; tân binh', 'v.', 'recruitment (n.), recruiter (n.)', 'Đồng nghĩa: hire, enlist', 'Recruit có thể làm động từ hoặc danh từ đếm được; hoạt động tuyển dụng dùng recruitment.', 'The animal shelter is recruiting volunteers for weekend shifts.', NULL, 'Trạm cứu hộ động vật đang tuyển tình nguyện viên cho các ca làm việc cuối tuần.', '{"wordId":"recruit","ukIpa":"/rɪˈkruːt/","usIpa":"/rɪˈkruːt/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"to find and employ workers or attract new members","vi":"tuyển dụng; chiêu mộ; tuyển"},{"pos":"n.","en":"someone who has recently joined an organization or armed force","vi":"nhân viên mới; thành viên mới; tân binh"}],"examples":[{"en":"The animal shelter is recruiting volunteers for weekend shifts.","vi":"Trạm cứu hộ động vật đang tuyển tình nguyện viên cho các ca làm việc cuối tuần.","audioKind":"ex"},{"en":"Hospitals need to recruit more nurses to meet the growing demand for healthcare services.","vi":"Các bệnh viện cần tuyển thêm y tá để đáp ứng nhu cầu dịch vụ chăm sóc sức khỏe ngày càng tăng.","audioKind":"ex2"}],"collocations":[{"en":"recruit staff","vi":"tuyển dụng nhân sự"},{"en":"recruit volunteers","vi":"chiêu mộ tình nguyện viên"},{"en":"a new recruit","vi":"một thành viên mới"},{"en":"recruitment agency","vi":"cơ quan tuyển dụng"}],"wordFamily":["recruitment (n.)","recruiter (n.)"],"synonyms":["hire","enlist"],"antonyms":[],"tipVi":"Recruit có thể làm động từ hoặc danh từ đếm được; hoạt động tuyển dụng dùng recruitment.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rival', 'en-b2-49', 'rival', '/ˈraɪvəl/', 'B2', 'đối thủ; người cạnh tranh; sánh kịp; sánh ngang; địch lại; cạnh tranh; đối lập', 'n.', 'rivalry (n.), unrivalled (adj.)', 'Đồng nghĩa: competitor · Trái nghĩa: ally', 'rival ở dạng động từ đi thẳng với tân ngữ, không cần thêm giới từ with.', 'She shook hands with her rival before the race.', NULL, 'Cô ấy bắt tay với đối thủ của mình trước cuộc đua.', '{"wordId":"rival","ukIpa":"/ˈraɪvəl/","usIpa":"/ˈraɪvəl/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"Someone competing with another for the same goal or advantage.","vi":"đối thủ; người cạnh tranh"},{"pos":"v.","en":"Be as good or impressive as someone or something.","vi":"sánh kịp; sánh ngang; địch lại"},{"pos":"adj.","en":"Competing for the same goal or advantage.","vi":"cạnh tranh; đối lập"}],"examples":[{"en":"She shook hands with her rival before the race.","vi":"Cô ấy bắt tay với đối thủ của mình trước cuộc đua.","audioKind":"ex"},{"en":"Smaller companies can rival larger firms by offering personalised services and responding quickly to customer needs.","vi":"Các công ty nhỏ hơn có thể sánh ngang với các hãng lớn hơn bằng cách cung cấp các dịch vụ cá nhân hóa và phản hồi nhanh chóng trước nhu cầu của khách hàng.","audioKind":"ex2"}],"collocations":[{"en":"a major rival","vi":"đối thủ lớn"},{"en":"a rival company","vi":"công ty đối thủ"},{"en":"rival teams","vi":"các đội bóng đối đầu"},{"en":"rival someone in quality","vi":"sánh ngang với ai về chất lượng"}],"wordFamily":["rivalry (n.)","unrivalled (adj.)"],"synonyms":["competitor"],"antonyms":["ally"],"tipVi":"rival ở dạng động từ đi thẳng với tân ngữ, không cần thêm giới từ with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_short-term', 'en-b2-49', 'short-term', '/ˌʃɔːrt ˈtɝːm/', 'B2', 'ngắn hạn', 'adj.', NULL, 'Trái nghĩa: long-term', 'Khi làm định ngữ đứng trước danh từ thì thường viết có gạch nối; cụm in the short term thì không.', 'This short-term job will cover my summer expenses.', NULL, 'Công việc ngắn hạn này sẽ giúp tôi trang trải các khoản chi phí mùa hè.', '{"wordId":"short-term","ukIpa":"/ˌʃɔːt ˈtɜːm/","usIpa":"/ˌʃɔːrt ˈtɝːm/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"lasting or having effects for only a limited time","vi":"ngắn hạn"}],"examples":[{"en":"This short-term job will cover my summer expenses.","vi":"Công việc ngắn hạn này sẽ giúp tôi trang trải các khoản chi phí mùa hè.","audioKind":"ex"},{"en":"Short-term solutions may reduce immediate pressure but fail to address the underlying causes of unemployment.","vi":"Các giải pháp ngắn hạn có thể làm giảm bớt áp lực trước mắt nhưng lại không giải quyết được nguyên nhân gốc rễ của tình trạng thất nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"short-term solution","vi":"giải pháp ngắn hạn"},{"en":"short-term contract","vi":"hợp đồng ngắn hạn"},{"en":"short-term memory","vi":"trí nhớ ngắn hạn"}],"wordFamily":[],"synonyms":[],"antonyms":["long-term"],"tipVi":"Khi làm định ngữ đứng trước danh từ thì thường viết có gạch nối; cụm in the short term thì không.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_executive', 'en-b2-49', 'executive', '/ɪɡˈzekjətɪv/', 'B2', 'nhà quản lý cấp cao; giám đốc điều hành; thuộc về điều hành; quản lý; hành chính; cơ quan hành pháp; bộ phận điều hành', 'n.', 'execute (v.), execution (n.)', NULL, 'Danh từ có thể chỉ cấp quản lý; tính từ thường bổ nghĩa cho các từ như power, board.', 'The executive joined our team for lunch today.', NULL, 'Vị giám đốc điều hành đã cùng đội ngũ của chúng tôi dùng bữa trưa hôm nay.', '{"wordId":"executive","ukIpa":"/ɪɡˈzekjətɪv/","usIpa":"/ɪɡˈzekjətɪv/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"a person with important management responsibilities in an organisation","vi":"nhà quản lý cấp cao; giám đốc điều hành"},{"pos":"adj.","en":"relating to managing an organisation or putting decisions into effect","vi":"thuộc về điều hành; quản lý; hành chính"},{"pos":"n.","en":"the part of a government or organisation that implements decisions","vi":"cơ quan hành pháp; bộ phận điều hành"}],"examples":[{"en":"The executive joined our team for lunch today.","vi":"Vị giám đốc điều hành đã cùng đội ngũ của chúng tôi dùng bữa trưa hôm nay.","audioKind":"ex"},{"en":"Senior executives should consider employee wellbeing alongside financial performance when making decisions about company restructuring.","vi":"Các nhà quản lý cấp cao nên cân nhắc phúc lợi của nhân viên bên cạnh hiệu quả tài chính khi đưa ra quyết định tái cơ cấu công ty.","audioKind":"ex2"}],"collocations":[{"en":"senior executive","vi":"nhà quản lý cấp cao"},{"en":"chief executive","vi":"giám đốc điều hành"},{"en":"executive power","vi":"quyền lực hành pháp"},{"en":"executive board","vi":"ban điều hành"}],"wordFamily":["execute (v.)","execution (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ có thể chỉ cấp quản lý; tính từ thường bổ nghĩa cho các từ như power, board.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_qualified', 'en-b2-49', 'qualified', '/ˈkwɑːlɪfaɪd/', 'B2', 'có chuyên môn; đủ tiêu chuẩn; có năng lực; có giới hạn; có điều kiện; chưa trọn vẹn', 'adj.', 'qualify (v.), qualification (n.), unqualified (adj.)', 'Đồng nghĩa: competent, certified · Trái nghĩa: unqualified', 'qualified for＋danh từ; qualified to do biểu thị có đủ tư cách làm gì.', 'Only a qualified electrician should repair that damaged socket.', NULL, 'Chỉ có thợ điện có chuyên môn mới nên sửa chữa ổ cắm bị hỏng đó.', '{"wordId":"qualified","ukIpa":"/ˈkwɒlɪfaɪd/","usIpa":"/ˈkwɑːlɪfaɪd/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"having the training, skills, or experience needed for something","vi":"có chuyên môn; đủ tiêu chuẩn; có năng lực"},{"pos":"adj.","en":"not complete or unconditional; involving limits or reservations","vi":"có giới hạn; có điều kiện; chưa trọn vẹn"}],"examples":[{"en":"Only a qualified electrician should repair that damaged socket.","vi":"Chỉ có thợ điện có chuyên môn mới nên sửa chữa ổ cắm bị hỏng đó.","audioKind":"ex"},{"en":"Governments should invest in teacher training to ensure that every school has enough qualified staff.","vi":"Chính phủ nên đầu tư vào đào tạo giáo viên để đảm bảo mọi trường học đều có đủ đội ngũ nhân sự đạt chuẩn.","audioKind":"ex2"}],"collocations":[{"en":"fully qualified","vi":"đạt chuẩn hoàn toàn"},{"en":"qualified to teach","vi":"có đủ điều kiện giảng dạy"},{"en":"qualified for the job","vi":"đủ năng lực cho công việc"},{"en":"qualified support","vi":"sự ủng hộ có điều kiện"}],"wordFamily":["qualify (v.)","qualification (n.)","unqualified (adj.)"],"synonyms":["competent","certified"],"antonyms":["unqualified"],"tipVi":"qualified for＋danh từ; qualified to do biểu thị có đủ tư cách làm gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dictate', 'en-b2-49', 'dictate', '/ˈdɪkteɪt/', 'B2', 'đọc cho viết; ra lệnh ghi chép; ra lệnh; áp đặt; sai khiến; quyết định; chi phối; ảnh hưởng lớn', 'v.', 'dictation (n.), dictator (n.), dictatorial (adj.)', NULL, 'dictate là đọc cho người khác viết; "làm bài chính tả" dùng take dictation.', 'Please dictate your message slowly while I write it down.', NULL, 'Xin hãy chậm rãi đọc lời nhắn để tôi ghi lại.', '{"wordId":"dictate","ukIpa":"/dɪkˈteɪt/","usIpa":"/ˈdɪkteɪt/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"to say words aloud for someone or something to record","vi":"đọc cho viết; ra lệnh ghi chép"},{"pos":"v.","en":"to tell someone what to do without allowing disagreement","vi":"ra lệnh; áp đặt; sai khiến"},{"pos":"v.","en":"to determine how something happens or is done","vi":"quyết định; chi phối; ảnh hưởng lớn"}],"examples":[{"en":"Please dictate your message slowly while I write it down.","vi":"Xin hãy chậm rãi đọc lời nhắn để tôi ghi lại.","audioKind":"ex"},{"en":"Financial pressures often dictate which courses universities offer, potentially limiting opportunities in less profitable subjects.","vi":"Áp lực tài chính thường quyết định các khóa học nào mà trường đại học cung cấp, qua đó có thể làm hạn chế cơ hội ở các môn học ít lợi nhuận hơn.","audioKind":"ex2"}],"collocations":[{"en":"dictate a letter","vi":"đọc thư cho người khác chép"},{"en":"dictate terms","vi":"áp đặt điều kiện"},{"en":"dictate policy","vi":"chi phối chính sách"}],"wordFamily":["dictation (n.)","dictator (n.)","dictatorial (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"dictate là đọc cho người khác viết; \"làm bài chính tả\" dùng take dictation.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inspect', 'en-b2-49', 'inspect', '/ɪnˈspekt/', 'B2', 'kiểm tra; thanh tra (kỹ lưỡng để tìm lỗi hoặc chi tiết); đi khảo sát; thanh tra chính thức (để đảm bảo đạt chuẩn)', 'v.', 'inspection (n.), inspector (n.)', 'Đồng nghĩa: examine, check', 'inspect là ngoại động từ nên đi thẳng đến đối tượng được kiểm tra, không cần dùng giới từ at.', 'Please inspect the bicycle''s brakes before you ride it.', NULL, 'Vui lòng kiểm tra kỹ phanh xe đạp trước khi bạn đi.', '{"wordId":"inspect","ukIpa":"/ɪnˈspekt/","usIpa":"/ɪnˈspekt/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"To examine something carefully for faults or other details.","vi":"kiểm tra; thanh tra (kỹ lưỡng để tìm lỗi hoặc chi tiết)"},{"pos":"v.","en":"To visit officially to check that required standards are met.","vi":"đi khảo sát; thanh tra chính thức (để đảm bảo đạt chuẩn)"}],"examples":[{"en":"Please inspect the bicycle''s brakes before you ride it.","vi":"Vui lòng kiểm tra kỹ phanh xe đạp trước khi bạn đi.","audioKind":"ex"},{"en":"Local authorities should inspect rental properties regularly to ensure that tenants have safe and healthy living conditions.","vi":"Chính quyền địa phương nên thường xuyên kiểm tra các bất động sản cho thuê để đảm bảo người thuê nhà có điều kiện sống an toàn và lành mạnh.","audioKind":"ex2"}],"collocations":[{"en":"inspect for damage","vi":"kiểm tra xem có hư hỏng không"},{"en":"inspect the premises","vi":"kiểm tra cơ sở vật chất"},{"en":"inspect thoroughly","vi":"kiểm tra kỹ lưỡng"}],"wordFamily":["inspection (n.)","inspector (n.)"],"synonyms":["examine","check"],"antonyms":[],"tipVi":"inspect là ngoại động từ nên đi thẳng đến đối tượng được kiểm tra, không cần dùng giới từ at.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_supervise', 'en-b2-49', 'supervise', '/ˈsuːpərvaɪz/', 'B2', 'giám sát; hướng dẫn; trông nom', 'v.', 'supervision (n.), supervisor (n.), supervisory (adj.)', 'Đồng nghĩa: oversee', 'Động từ ngoại động từ, đi thẳng với người hoặc hoạt động: supervise staff.', 'An adult must supervise the children near the pool.', NULL, 'Một người lớn phải trông nom trẻ em ở gần khu vực hồ bơi.', '{"wordId":"supervise","ukIpa":"/ˈsuːpəvaɪz/","usIpa":"/ˈsuːpərvaɪz/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"watch and guide people to ensure work or activities go properly","vi":"giám sát; hướng dẫn; trông nom"}],"examples":[{"en":"An adult must supervise the children near the pool.","vi":"Một người lớn phải trông nom trẻ em ở gần khu vực hồ bơi.","audioKind":"ex"},{"en":"Experienced nurses should supervise new staff to ensure that patients receive safe and effective care.","vi":"Các y tá có kinh nghiệm nên hướng dẫn nhân viên mới để đảm bảo rằng bệnh nhân nhận được sự chăm sóc an toàn và hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"supervise staff","vi":"giám sát nhân viên"},{"en":"supervise children","vi":"trông nom trẻ em"},{"en":"supervise a project","vi":"quản lý một dự án"}],"wordFamily":["supervision (n.)","supervisor (n.)","supervisory (adj.)"],"synonyms":["oversee"],"antonyms":[],"tipVi":"Động từ ngoại động từ, đi thẳng với người hoặc hoạt động: supervise staff.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_marketing', 'en-b2-49', 'marketing', '/ˈmɑːrkɪtɪŋ/', 'B2', 'tiếp thị; marketing', 'n.', 'market (n.), market (v.), marketer (n.), marketable (adj.)', NULL, 'marketing thường là danh từ không đếm được, phạm vi rộng hơn advertising.', 'My sister handles marketing for a small local bakery.', NULL, 'Chị gái tôi phụ trách mảng tiếp thị cho một tiệm bánh nhỏ ở địa phương.', '{"wordId":"marketing","ukIpa":"/ˈmɑːkɪtɪŋ/","usIpa":"/ˈmɑːrkɪtɪŋ/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"activities that identify customers'' needs and promote products or services","vi":"tiếp thị; marketing"}],"examples":[{"en":"My sister handles marketing for a small local bakery.","vi":"Chị gái tôi phụ trách mảng tiếp thị cho một tiệm bánh nhỏ ở địa phương.","audioKind":"ex"},{"en":"Effective marketing helps small businesses reach new customers without necessarily spending large amounts on advertising.","vi":"Hoạt động tiếp thị hiệu quả giúp các doanh nghiệp nhỏ tiếp cận khách hàng mới mà không nhất thiết phải chi những khoản tiền lớn cho quảng cáo.","audioKind":"ex2"}],"collocations":[{"en":"marketing strategy","vi":"chiến lược tiếp thị"},{"en":"digital marketing","vi":"tiếp thị kỹ thuật số"},{"en":"marketing campaign","vi":"chiến dịch tiếp thị"},{"en":"market research","vi":"nghiên cứu thị trường"}],"wordFamily":["market (n.)","market (v.)","marketer (n.)","marketable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"marketing thường là danh từ không đếm được, phạm vi rộng hơn advertising.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_resume', 'en-b2-49', 'resume', '/rɪˈzuːm/', 'B2', 'tiếp tục; bắt đầu lại', 'v.', 'resumption (n.)', 'Đồng nghĩa: restart, continue · Trái nghĩa: suspend, stop', 'Sau động từ này có thể cộng với danh từ hoặc danh động từ; lưu ý danh từ résumé mang nghĩa là sơ yếu lý lịch.', 'We will resume our walk when the rain stops.', NULL, 'Chúng tôi sẽ tiếp tục đi dạo khi trời tạnh mưa.', '{"wordId":"resume","ukIpa":"/rɪˈzjuːm/","usIpa":"/rɪˈzuːm/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"To start again after stopping or being interrupted.","vi":"tiếp tục; bắt đầu lại"}],"examples":[{"en":"We will resume our walk when the rain stops.","vi":"Chúng tôi sẽ tiếp tục đi dạo khi trời tạnh mưa.","audioKind":"ex"},{"en":"Schools can resume normal teaching once damaged buildings have been repaired and essential safety checks are complete.","vi":"Các trường học có thể khôi phục việc giảng dạy bình thường một khi các tòa nhà bị hư hỏng đã được sửa chữa và các cuộc kiểm tra an toàn thiết yếu hoàn tất.","audioKind":"ex2"}],"collocations":[{"en":"resume work","vi":"tiếp tục làm việc"},{"en":"resume talks","vi":"nối lại đàm phán"},{"en":"resume normal service","vi":"khôi phục dịch vụ bình thường"}],"wordFamily":["resumption (n.)"],"synonyms":["restart","continue"],"antonyms":["suspend","stop"],"tipVi":"Sau động từ này có thể cộng với danh từ hoặc danh động từ; lưu ý danh từ résumé mang nghĩa là sơ yếu lý lịch.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_teamwork', 'en-b2-49', 'teamwork', '/ˈtiːmwɝːk/', 'B2', 'sự hợp tác nhóm; tinh thần đồng đội', 'n.', 'team (n.), teammate (n.)', 'Đồng nghĩa: cooperation, collaboration', 'Là danh từ không đếm được; nhấn mạnh sự cộng tác cùng nhau giữa các thành viên trong nhóm.', 'Good teamwork helped us finish painting before lunch.', NULL, 'Tinh thần đồng đội tốt đã giúp chúng tôi hoàn thành việc sơn trước bữa trưa.', '{"wordId":"teamwork","ukIpa":"/ˈtiːmwɜːk/","usIpa":"/ˈtiːmwɝːk/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"People working together effectively to achieve a shared goal","vi":"sự hợp tác nhóm; tinh thần đồng đội"}],"examples":[{"en":"Good teamwork helped us finish painting before lunch.","vi":"Tinh thần đồng đội tốt đã giúp chúng tôi hoàn thành việc sơn trước bữa trưa.","audioKind":"ex"},{"en":"Group projects can develop teamwork skills that students will need in their future careers.","vi":"Các dự án nhóm có thể phát triển các kỹ năng làm việc nhóm mà sinh viên sẽ cần cho sự nghiệp tương lai của họ.","audioKind":"ex2"}],"collocations":[{"en":"effective teamwork","vi":"sự hợp tác nhóm hiệu quả"},{"en":"teamwork skills","vi":"kỹ năng làm việc nhóm"},{"en":"encourage teamwork","vi":"khuyến khích tinh thần đồng đội"}],"wordFamily":["team (n.)","teammate (n.)"],"synonyms":["cooperation","collaboration"],"antonyms":[],"tipVi":"Là danh từ không đếm được; nhấn mạnh sự cộng tác cùng nhau giữa các thành viên trong nhóm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_capable', 'en-b2-49', 'capable', '/ˈkeɪpəbəl/', 'B2', 'có khả năng, có năng lực làm gì đó; giỏi giang, có tài xử lý công việc hoặc trách nhiệm', 'adj.', 'capability (n), capably (adv), incapable (adj)', 'Đồng nghĩa: able, competent · Trái nghĩa: incapable, incompetent', 'Luôn dùng capable of doing, không dùng capable to do.', 'This little printer is capable of producing excellent colour photos.', NULL, 'Chiếc máy in nhỏ này có khả năng in ra những bức ảnh màu xuất sắc.', '{"wordId":"capable","ukIpa":"/ˈkeɪpəbəl/","usIpa":"/ˈkeɪpəbəl/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"Having the ability or qualities needed to do something.","vi":"có khả năng, có năng lực làm gì đó"},{"pos":"adj.","en":"Skilled and effective at handling tasks or responsibilities.","vi":"giỏi giang, có tài xử lý công việc hoặc trách nhiệm"}],"examples":[{"en":"This little printer is capable of producing excellent colour photos.","vi":"Chiếc máy in nhỏ này có khả năng in ra những bức ảnh màu xuất sắc.","audioKind":"ex"},{"en":"With appropriate training and support, young employees are capable of taking on substantial responsibilities within an organisation.","vi":"Với sự đào tạo và hỗ trợ phù hợp, các nhân viên trẻ hoàn toàn có khả năng đảm nhận những trách nhiệm lớn trong tổ chức.","audioKind":"ex2"}],"collocations":[{"en":"capable of doing something","vi":"có khả năng làm điều gì"},{"en":"highly capable","vi":"rất có năng lực"},{"en":"a capable leader","vi":"một nhà lãnh đạo tài năng"}],"wordFamily":["capability (n)","capably (adv)","incapable (adj)"],"synonyms":["able","competent"],"antonyms":["incapable","incompetent"],"tipVi":"Luôn dùng capable of doing, không dùng capable to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ongoing', 'en-b2-49', 'ongoing', '/ˈɑːnɡoʊɪŋ/', 'B2', 'đang diễn ra; tiếp tục', 'adj.', NULL, 'Đồng nghĩa: continuing · Trái nghĩa: completed, finished', 'Nhấn mạnh sự việc vẫn đang tiếp diễn, không đồng nghĩa với sắp xảy ra (upcoming).', 'The ongoing repairs mean we cannot use the kitchen.', NULL, 'Việc sửa chữa đang diễn ra đồng nghĩa với việc chúng tôi không thể sử dụng nhà bếp.', '{"wordId":"ongoing","ukIpa":"/ˈɒnɡəʊɪŋ/","usIpa":"/ˈɑːnɡoʊɪŋ/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"Continuing to happen or develop, rather than being finished.","vi":"đang diễn ra; tiếp tục"}],"examples":[{"en":"The ongoing repairs mean we cannot use the kitchen.","vi":"Việc sửa chữa đang diễn ra đồng nghĩa với việc chúng tôi không thể sử dụng nhà bếp.","audioKind":"ex"},{"en":"Ongoing research into renewable energy is essential for reducing dependence on fossil fuels and limiting environmental damage.","vi":"Nghiên cứu đang tiếp tục về năng lượng tái tạo là điều cốt yếu để giảm sự phụ thuộc vào nhiên liệu hóa thạch và hạn chế tổn hại môi trường.","audioKind":"ex2"}],"collocations":[{"en":"ongoing research","vi":"nghiên cứu đang tiến hành"},{"en":"an ongoing process","vi":"một quá trình đang diễn ra"},{"en":"ongoing support","vi":"sự hỗ trợ liên tục"},{"en":"an ongoing investigation","vi":"một cuộc điều tra đang tiến hành"}],"wordFamily":[],"synonyms":["continuing"],"antonyms":["completed","finished"],"tipVi":"Nhấn mạnh sự việc vẫn đang tiếp diễn, không đồng nghĩa với sắp xảy ra (upcoming).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_specialize', 'en-b2-49', 'specialize', '/ˈspeʃəlaɪz/', 'B2', 'chuyên về; chuyên môn hóa', 'v.', 'specialist (n.), specialization (n.), specialized (adj.), specialism (n.)', NULL, 'Thường đi với giới từ "in"; tiếng Anh-Anh thường viết là "specialise".', 'The bakery near our house specializes in fresh sourdough bread.', NULL, 'Tiệm bánh gần nhà chúng tôi chuyên làm bánh mì chua tươi.', '{"wordId":"specialize","ukIpa":"/ˈspeʃəlaɪz/","usIpa":"/ˈspeʃəlaɪz/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"to focus on a particular subject, activity, or service","vi":"chuyên về; chuyên môn hóa"}],"examples":[{"en":"The bakery near our house specializes in fresh sourdough bread.","vi":"Tiệm bánh gần nhà chúng tôi chuyên làm bánh mì chua tươi.","audioKind":"ex"},{"en":"Students who specialize too early may miss opportunities to develop knowledge across a broader range of subjects.","vi":"Những học sinh chuyên môn hóa quá sớm có thể bỏ lỡ cơ hội phát triển kiến thức trên nhiều lĩnh vực rộng hơn.","audioKind":"ex2"}],"collocations":[{"en":"specialize in medicine","vi":"chuyên ngành y"},{"en":"specialize in repairing cars","vi":"chuyên sửa chữa ô tô"},{"en":"highly specialized skills","vi":"các kỹ năng chuyên môn cao"}],"wordFamily":["specialist (n.)","specialization (n.)","specialized (adj.)","specialism (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường đi với giới từ \"in\"; tiếng Anh-Anh thường viết là \"specialise\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flexible', 'en-b2-49', 'flexible', '/ˈfleksəbl/', 'B2', 'linh hoạt; dễ thích ứng; dẻo dai; dễ uốn cong', 'adj.', 'flexibility (n.), flexibly (adv.), inflexible (adj.)', 'Đồng nghĩa: adaptable · Trái nghĩa: inflexible, rigid', 'Có thể dùng để mô tả thời gian/lịch trình hoặc tính chất vật lý của vật liệu.', 'My flexible schedule lets me collect the children after school.', NULL, 'Lịch trình linh hoạt giúp tôi có thể đón các con sau giờ học.', '{"wordId":"flexible","ukIpa":"/ˈfleksəbl/","usIpa":"/ˈfleksəbl/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"able to change to suit different needs or situations","vi":"linh hoạt; dễ thích ứng"},{"pos":"adj.","en":"able to bend easily without breaking","vi":"dẻo dai; dễ uốn cong"}],"examples":[{"en":"My flexible schedule lets me collect the children after school.","vi":"Lịch trình linh hoạt giúp tôi có thể đón các con sau giờ học.","audioKind":"ex"},{"en":"Flexible working arrangements can help employees balance professional responsibilities with their family commitments.","vi":"Các thỏa thuận làm việc linh hoạt có thể giúp nhân viên cân bằng giữa trách nhiệm công việc và gia đình.","audioKind":"ex2"}],"collocations":[{"en":"flexible working hours","vi":"giờ làm việc linh hoạt"},{"en":"a flexible approach","vi":"một phương pháp linh hoạt"},{"en":"flexible materials","vi":"vật liệu dẻo"}],"wordFamily":["flexibility (n.)","flexibly (adv.)","inflexible (adj.)"],"synonyms":["adaptable"],"antonyms":["inflexible","rigid"],"tipVi":"Có thể dùng để mô tả thời gian/lịch trình hoặc tính chất vật lý của vật liệu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_commitment', 'en-b2-49', 'commitment', '/kəˈmɪtmənt/', 'B2', 'sự tận tụy; tinh thần cống hiến; lời hứa; cam kết; trách nhiệm; nghĩa vụ', 'n.', 'commit (v), committed (adj)', 'Đồng nghĩa: dedication, devotion', 'commitment to trong đó to là giới từ, theo sau là danh từ hoặc danh động từ.', 'Her commitment to gardening keeps the flowers blooming.', NULL, 'Sự tận tụy của cô ấy với việc làm vườn giúp những bông hoa luôn nở rộ.', '{"wordId":"commitment","ukIpa":"/kəˈmɪtmənt/","usIpa":"/kəˈmɪtmənt/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"A strong willingness to give time and effort to something.","vi":"sự tận tụy; tinh thần cống hiến"},{"pos":"n.","en":"A firm promise to do something.","vi":"lời hứa; cam kết"},{"pos":"n.","en":"A duty or arrangement requiring your time, money, or attention.","vi":"trách nhiệm; nghĩa vụ"}],"examples":[{"en":"Her commitment to gardening keeps the flowers blooming.","vi":"Sự tận tụy của cô ấy với việc làm vườn giúp những bông hoa luôn nở rộ.","audioKind":"ex"},{"en":"Improving public transport requires sustained political commitment and reliable funding rather than occasional investment in isolated projects.","vi":"Việc cải thiện giao thông công cộng đòi hỏi sự cam kết chính trị lâu dài và nguồn vốn đáng tin cậy chứ không phải là những khoản đầu tư mang tính thời vụ vào các dự án đơn lẻ.","audioKind":"ex2"}],"collocations":[{"en":"commitment to a cause","vi":"sự cống hiến cho một sự nghiệp"},{"en":"make a commitment","vi":"đưa ra cam kết"},{"en":"family commitments","vi":"trách nhiệm gia đình"},{"en":"long-term commitment","vi":"cam kết lâu dài"}],"wordFamily":["commit (v)","committed (adj)"],"synonyms":["dedication","devotion"],"antonyms":[],"tipVi":"commitment to trong đó to là giới từ, theo sau là danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chairwoman', 'en-b2-49', 'chairwoman', '/ˈtʃerˌwʊmən/', 'B2', 'nữ chủ tịch; nữ chủ tịch hội đồng quản trị', 'n.', 'chair (n.), chair (v.), chairperson (n.), chairmanship (n.)', 'Đồng nghĩa: chair, chairperson', 'dạng số nhiều là chairwomen; nếu không muốn nhấn mạnh giới tính có thể dùng chair.', 'The chairwoman invited everyone to share their ideas.', NULL, 'Nữ chủ tịch mời mọi người chia sẻ ý kiến của mình.', '{"wordId":"chairwoman","ukIpa":"/ˈtʃeəˌwʊmən/","usIpa":"/ˈtʃerˌwʊmən/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"A woman who leads a meeting, committee, or organisation.","vi":"nữ chủ tịch; nữ chủ tịch hội đồng quản trị"}],"examples":[{"en":"The chairwoman invited everyone to share their ideas.","vi":"Nữ chủ tịch mời mọi người chia sẻ ý kiến của mình.","audioKind":"ex"},{"en":"The chairwoman proposed new training programmes to improve employees'' skills and support equal opportunities.","vi":"Nữ chủ tịch đã đề xuất các chương trình đào tạo mới nhằm nâng cao kỹ năng cho nhân viên và thúc đẩy cơ hội bình đẳng.","audioKind":"ex2"}],"collocations":[{"en":"chairwoman of the board","vi":"nữ chủ tịch hội đồng quản trị"},{"en":"committee chairwoman","vi":"nữ chủ tịch ủy ban"},{"en":"appoint a chairwoman","vi":"bổ nhiệm một nữ chủ tịch"}],"wordFamily":["chair (n.)","chair (v.)","chairperson (n.)","chairmanship (n.)"],"synonyms":["chair","chairperson"],"antonyms":[],"tipVi":"dạng số nhiều là chairwomen; nếu không muốn nhấn mạnh giới tính có thể dùng chair.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_specify', 'en-b2-49', 'specify', '/ˈspesɪfaɪ/', 'B2', 'chỉ rõ; nêu cụ thể; quy định rõ', 'v.', 'specification (n.), specific (adj.), specifically (adv.)', 'Đồng nghĩa: state, stipulate', 'Có thể đi kèm với danh từ, mệnh đề "that" hoặc mệnh đề bắt đầu bằng từ để hỏi.', 'Please specify which colour you want for the curtains.', NULL, 'Vui lòng nêu rõ màu sắc bạn muốn cho bộ rèm cửa.', '{"wordId":"specify","ukIpa":"/ˈspesɪfaɪ/","usIpa":"/ˈspesɪfaɪ/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"To state exactly what is required or meant.","vi":"chỉ rõ; nêu cụ thể; quy định rõ"}],"examples":[{"en":"Please specify which colour you want for the curtains.","vi":"Vui lòng nêu rõ màu sắc bạn muốn cho bộ rèm cửa.","audioKind":"ex"},{"en":"Governments should specify clear safety standards that all manufacturers must meet before selling products to consumers.","vi":"Chính phủ nên quy định rõ các tiêu chuẩn an toàn mà tất cả các nhà sản xuất phải đáp ứng trước khi bán sản phẩm cho người tiêu dùng.","audioKind":"ex2"}],"collocations":[{"en":"specify requirements","vi":"nêu rõ yêu cầu"},{"en":"specify a date","vi":"ấn định ngày"},{"en":"specify conditions","vi":"quy định rõ các điều kiện"}],"wordFamily":["specification (n.)","specific (adj.)","specifically (adv.)"],"synonyms":["state","stipulate"],"antonyms":[],"tipVi":"Có thể đi kèm với danh từ, mệnh đề \"that\" hoặc mệnh đề bắt đầu bằng từ để hỏi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_overtime', 'en-b2-49', 'overtime', '/ˈoʊvərtaɪm/', 'B2', 'giờ làm thêm; tiền làm thêm giờ; làm thêm giờ; ngoài giờ; hiệp phụ (thể thao)', 'n.', NULL, NULL, 'Làm thêm giờ dùng "work overtime"; còn "over time" (viết tách) mang nghĩa là theo thời gian.', 'I worked overtime yesterday to finish the kitchen repairs.', NULL, 'Hôm qua tôi đã làm thêm giờ để sửa xong nhà bếp.', '{"wordId":"overtime","ukIpa":"/ˈəʊvətaɪm/","usIpa":"/ˈoʊvərtaɪm/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"Extra working hours, or the money paid for them.","vi":"giờ làm thêm; tiền làm thêm giờ"},{"pos":"adv.","en":"For longer than the usual working hours.","vi":"làm thêm giờ; ngoài giờ"},{"pos":"n.","en":"Additional playing time used to decide a tied game.","vi":"hiệp phụ (thể thao)"}],"examples":[{"en":"I worked overtime yesterday to finish the kitchen repairs.","vi":"Hôm qua tôi đã làm thêm giờ để sửa xong nhà bếp.","audioKind":"ex"},{"en":"Regular overtime may increase short-term productivity, but it can also undermine employees'' health and reduce job satisfaction.","vi":"Việc làm thêm giờ thường xuyên có thể tăng năng suất trong ngắn hạn, nhưng cũng có thể làm suy giảm sức khỏe của nhân viên và giảm sự hài lòng trong công việc.","audioKind":"ex2"}],"collocations":[{"en":"work overtime","vi":"làm thêm giờ"},{"en":"overtime pay","vi":"tiền làm thêm giờ"},{"en":"unpaid overtime","vi":"làm thêm giờ không lương"},{"en":"mandatory overtime","vi":"làm thêm giờ bắt buộc"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Làm thêm giờ dùng \"work overtime\"; còn \"over time\" (viết tách) mang nghĩa là theo thời gian.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_punctual', 'en-b2-49', 'punctual', '/ˈpʌŋktʃuəl/', 'B2', 'đúng giờ', 'adj.', 'punctuality (n.), punctually (adv.)', 'Đồng nghĩa: on time, prompt · Trái nghĩa: late, unpunctual', 'Để diễn đạt việc đến họp đúng giờ, dùng "be punctual for a meeting".', 'Please be punctual; the bus cannot wait for everyone.', NULL, 'Xin vui lòng đến đúng giờ; xe buýt không thể đợi tất cả mọi người.', '{"wordId":"punctual","ukIpa":"/ˈpʌŋktʃuəl/","usIpa":"/ˈpʌŋktʃuəl/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"Arriving or happening at the agreed or expected time","vi":"đúng giờ"}],"examples":[{"en":"Please be punctual; the bus cannot wait for everyone.","vi":"Xin vui lòng đến đúng giờ; xe buýt không thể đợi tất cả mọi người.","audioKind":"ex"},{"en":"Punctual employees help organisations operate efficiently by ensuring that meetings and daily tasks begin on time.","vi":"Những nhân viên đúng giờ giúp tổ chức vận hành hiệu quả bằng cách đảm bảo các cuộc họp và công việc hàng ngày bắt đầu đúng hạn.","audioKind":"ex2"}],"collocations":[{"en":"be punctual for","vi":"có mặt đúng giờ (cho việc gì)"},{"en":"a punctual arrival","vi":"sự đến đúng giờ"},{"en":"punctual service","vi":"dịch vụ đúng giờ"}],"wordFamily":["punctuality (n.)","punctually (adv.)"],"synonyms":["on time","prompt"],"antonyms":["late","unpunctual"],"tipVi":"Để diễn đạt việc đến họp đúng giờ, dùng \"be punctual for a meeting\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_handling', 'en-b2-49', 'handling', '/ˈhændlɪŋ/', 'B2', 'cách xử lý; sự giải quyết; sự bốc dỡ; sự cầm nắm; thao tác; khả năng điều khiển (xe cộ)', 'n.', 'handle (v.), handler (n.)', 'Đồng nghĩa: management', 'Khi chỉ cách xử lý, thường dùng "handling of" cộng với sự việc được xử lý.', 'Her calm handling of the complaint impressed everyone.', NULL, 'Cách xử lý khiếu nại bình tĩnh của cô ấy đã gây ấn tượng với mọi người.', '{"wordId":"handling","ukIpa":"/ˈhændlɪŋ/","usIpa":"/ˈhændlɪŋ/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"The way someone deals with a situation, task, or person.","vi":"cách xử lý; sự giải quyết"},{"pos":"n.","en":"The act of moving, holding, or touching something.","vi":"sự bốc dỡ; sự cầm nắm; thao tác"},{"pos":"n.","en":"How easily a vehicle responds to its driver''s control.","vi":"khả năng điều khiển (xe cộ)"}],"examples":[{"en":"Her calm handling of the complaint impressed everyone.","vi":"Cách xử lý khiếu nại bình tĩnh của cô ấy đã gây ấn tượng với mọi người.","audioKind":"ex"},{"en":"Effective handling of household waste requires cooperation between local authorities, recycling companies, and residents throughout the community.","vi":"Việc xử lý hiệu quả rác thải sinh hoạt đòi hỏi sự hợp tác giữa chính quyền địa phương, các công ty tái chế và cư dân trong toàn cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"handling of complaints","vi":"cách xử lý khiếu nại"},{"en":"safe handling","vi":"thao tác an toàn"},{"en":"manual handling","vi":"bốc dỡ thủ công"},{"en":"handling charges","vi":"phí xử lý"}],"wordFamily":["handle (v.)","handler (n.)"],"synonyms":["management"],"antonyms":[],"tipVi":"Khi chỉ cách xử lý, thường dùng \"handling of\" cộng với sự việc được xử lý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_strike', 'en-b2-49', 'strike', '/straɪk/', 'B2', 'cuộc đình công; đánh; đập; va chạm; chợt nảy ra (ý nghĩ); gây ấn tượng', 'n.', 'striker (n.), striking (adj.)', 'Đồng nghĩa: hit', 'Quá khứ đơn là "struck"; quá khứ phân từ thường cũng dùng "struck".', 'The drivers are on strike, so we walked home.', NULL, 'Các tài xế đang đình công nên chúng tôi phải đi bộ về nhà.', '{"wordId":"strike","ukIpa":"/straɪk/","usIpa":"/straɪk/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"a refusal to work to demand better employment conditions","vi":"cuộc đình công"},{"pos":"v.","en":"hit someone or something with force","vi":"đánh; đập; va chạm"},{"pos":"v.","en":"occur suddenly to someone or create a strong impression","vi":"chợt nảy ra (ý nghĩ); gây ấn tượng"}],"examples":[{"en":"The drivers are on strike, so we walked home.","vi":"Các tài xế đang đình công nên chúng tôi phải đi bộ về nhà.","audioKind":"ex"},{"en":"Workers may go on strike when negotiations over pay and working conditions fail.","vi":"Người lao động có thể đình công khi các cuộc đàm phán về tiền lương và điều kiện làm việc thất bại.","audioKind":"ex2"}],"collocations":[{"en":"go on strike","vi":"tiến hành đình công"},{"en":"be on strike","vi":"đang đình công"},{"en":"strike a balance","vi":"đạt được sự cân bằng"},{"en":"strike someone as unusual","vi":"khiến ai đó thấy lạ"}],"wordFamily":["striker (n.)","striking (adj.)"],"synonyms":["hit"],"antonyms":[],"tipVi":"Quá khứ đơn là \"struck\"; quá khứ phân từ thường cũng dùng \"struck\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_manual', 'en-b2-49', 'manual', '/ˈmænjuəl/', 'B2', 'thủ công; bằng tay; (thuộc) lao động chân tay; sách hướng dẫn; cẩm nang', 'adj.', 'manually (adv.)', NULL, 'Khi là tính từ, manual chỉ thao tác bằng tay hoặc lao động chân tay; khi là danh từ, nó chỉ sách hướng dẫn.', 'This manual coffee grinder takes some effort to turn.', NULL, 'Máy xay cà phê thủ công này cần mất chút sức để quay.', '{"wordId":"manual","ukIpa":"/ˈmænjuəl/","usIpa":"/ˈmænjuəl/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"Done by hand or operated by a person, not automatically.","vi":"thủ công; bằng tay"},{"pos":"adj.","en":"Involving physical work rather than mainly mental work.","vi":"(thuộc) lao động chân tay"},{"pos":"n.","en":"A book giving instructions for using or doing something.","vi":"sách hướng dẫn; cẩm nang"}],"examples":[{"en":"This manual coffee grinder takes some effort to turn.","vi":"Máy xay cà phê thủ công này cần mất chút sức để quay.","audioKind":"ex"},{"en":"Although automation increases productivity, many industries still rely on manual labour for complex tasks.","vi":"Mặc dù tự động hóa làm tăng năng suất, nhiều ngành công nghiệp vẫn phụ thuộc vào lao động chân tay để thực hiện các công việc phức tạp.","audioKind":"ex2"}],"collocations":[{"en":"manual labour","vi":"lao động chân tay"},{"en":"manual control","vi":"điều khiển bằng tay"},{"en":"instruction manual","vi":"sách hướng dẫn sử dụng"},{"en":"user manual","vi":"tài liệu hướng dẫn cho người dùng"}],"wordFamily":["manually (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi là tính từ, manual chỉ thao tác bằng tay hoặc lao động chân tay; khi là danh từ, nó chỉ sách hướng dẫn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_49_1', 'en-b2-49', 'Cách dùng “resume” (v.) — tiếp tục; bắt đầu lại', 'resume work  ·  resume talks  ·  resume normal service', 'Sau động từ này có thể cộng với danh từ hoặc danh động từ; lưu ý danh từ résumé mang nghĩa là sơ yếu lý lịch.', 'Họ từ (Word Family): resumption (n.) | Đồng nghĩa: restart, continue · Trái nghĩa: suspend, stop', '[{"hanzi":"We will resume our walk when the rain stops.","pinyin":"","meaning":"Chúng tôi sẽ tiếp tục đi dạo khi trời tạnh mưa."},{"hanzi":"Schools can resume normal teaching once damaged buildings have been repaired and essential safety checks are complete.","pinyin":"","meaning":"Các trường học có thể khôi phục việc giảng dạy bình thường một khi các tòa nhà bị hư hỏng đã được sửa chữa và các cuộc kiểm tra an toàn thiết yếu hoàn tất."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_49_2', 'en-b2-49', 'Cách dùng “manual” (adj.) — thủ công; bằng tay', 'manual labour  ·  manual control  ·  instruction manual', 'Khi là tính từ, manual chỉ thao tác bằng tay hoặc lao động chân tay; khi là danh từ, nó chỉ sách hướng dẫn.', 'Họ từ (Word Family): manually (adv.)', '[{"hanzi":"This manual coffee grinder takes some effort to turn.","pinyin":"","meaning":"Máy xay cà phê thủ công này cần mất chút sức để quay."},{"hanzi":"Although automation increases productivity, many industries still rely on manual labour for complex tasks.","pinyin":"","meaning":"Mặc dù tự động hóa làm tăng năng suất, nhiều ngành công nghiệp vẫn phụ thuộc vào lao động chân tay để thực hiện các công việc phức tạp."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_49_3', 'en-b2-49', 'Cách dùng “guideline” (n.) — lời khuyên; nguyên tắc chỉ đạo; hướng dẫn; quy tắc', 'follow guidelines  ·  issue guidelines  ·  safety guidelines', 'Thường dùng ở dạng số nhiều guidelines; thường mang ý nghĩa hướng dẫn, tư vấn hơn là quy định bắt buộc.', 'Đồng nghĩa: guidance', '[{"hanzi":"These guidelines explain how to store food safely.","pinyin":"","meaning":"Những hướng dẫn này giải thích cách bảo quản thực phẩm an toàn."},{"hanzi":"Clear guidelines on data collection can help researchers protect participants while maintaining the quality of their studies.","pinyin":"","meaning":"Các hướng dẫn rõ ràng về việc thu thập dữ liệu có thể giúp các nhà nghiên cứu bảo vệ người tham gia đồng thời duy trì chất lượng nghiên cứu của họ."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_49_4', 'en-b2-49', 'Cách dùng “short-term” (adj.) — ngắn hạn', 'short-term solution  ·  short-term contract  ·  short-term memory', 'Khi làm định ngữ đứng trước danh từ thì thường viết có gạch nối; cụm in the short term thì không.', 'Trái nghĩa: long-term', '[{"hanzi":"This short-term job will cover my summer expenses.","pinyin":"","meaning":"Công việc ngắn hạn này sẽ giúp tôi trang trải các khoản chi phí mùa hè."},{"hanzi":"Short-term solutions may reduce immediate pressure but fail to address the underlying causes of unemployment.","pinyin":"","meaning":"Các giải pháp ngắn hạn có thể làm giảm bớt áp lực trước mắt nhưng lại không giải quyết được nguyên nhân gốc rễ của tình trạng thất nghiệp."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
