INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_49_1_6', 'ten_b2_49_1', 'executive', 'The executive joined our team for lunch today.', 'The executive joined our team for lunch today.', '/ɪɡˈzekjətɪv/', 'Vị giám đốc điều hành đã cùng đội ngũ của chúng tôi dùng bữa trưa hôm nay.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_49_1_7', 'ten_b2_49_1', 'qualified', 'Only a qualified electrician should repair that damaged socket.', 'Only a qualified electrician should repair that damaged socket.', '/ˈkwɑːlɪfaɪd/', 'Chỉ có thợ điện có chuyên môn mới nên sửa chữa ổ cắm bị hỏng đó.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_49_1_8', 'ten_b2_49_1', 'dictate', 'Please dictate your message slowly while I write it down.', 'Please dictate your message slowly while I write it down.', '/ˈdɪkteɪt/', 'Xin hãy chậm rãi đọc lời nhắn để tôi ghi lại.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_49_1_1', 'en-b2-49', 'ten_b2_49_1', 'listening', 'listening', 'Her calm leadership helped our team finish the project.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Sự lãnh đạo điềm tĩnh của cô ấy đã giúp đội ngũ của chúng tôi hoàn thành dự án.","Xin vui lòng đến đúng giờ; xe buýt không thể đợi tất cả mọi người.","Sự tận tụy của cô ấy với việc làm vườn giúp những bông hoa luôn nở rộ.","Chúng tôi sẽ tiếp tục đi dạo khi trời tạnh mưa."]'::jsonb, 0, 'Her calm leadership helped our team finish the project. → Sự lãnh đạo điềm tĩnh của cô ấy đã giúp đội ngũ của chúng tôi hoàn thành dự án.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_49_1_2', 'en-b2-49', 'ten_b2_49_1', 'listening', 'listening', 'These guidelines explain how to store food safely.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Xin hãy chậm rãi đọc lời nhắn để tôi ghi lại.","Chỉ có thợ điện có chuyên môn mới nên sửa chữa ổ cắm bị hỏng đó.","Vui lòng nêu rõ màu sắc bạn muốn cho bộ rèm cửa.","Những hướng dẫn này giải thích cách bảo quản thực phẩm an toàn."]'::jsonb, 3, 'These guidelines explain how to store food safely. → Những hướng dẫn này giải thích cách bảo quản thực phẩm an toàn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_49_1_3', 'en-b2-49', 'ten_b2_49_1', 'listening', 'listening', 'The animal shelter is recruiting volunteers for weekend shifts.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chỉ có thợ điện có chuyên môn mới nên sửa chữa ổ cắm bị hỏng đó.","Lịch trình linh hoạt giúp tôi có thể đón các con sau giờ học.","Trạm cứu hộ động vật đang tuyển tình nguyện viên cho các ca làm việc cuối tuần.","Xin vui lòng đến đúng giờ; xe buýt không thể đợi tất cả mọi người."]'::jsonb, 2, 'The animal shelter is recruiting volunteers for weekend shifts. → Trạm cứu hộ động vật đang tuyển tình nguyện viên cho các ca làm việc cuối tuần.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_49_2', 'en-b2-49', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_49_2_1', 'ten_b2_49_2', 'leadership', 'Effective leadership in schools can improve staff morale and create a more supportive learning environment.', 'Effective leadership in schools can improve staff morale and create a more supportive learning environment.', '/ˈliːdərʃɪp/', 'Năng lực lãnh đạo hiệu quả trong trường học có thể nâng cao tinh thần làm việc của giáo viên nhân viên và tạo ra môi trường học tập hỗ trợ tốt hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_49_2_2', 'ten_b2_49_2', 'guideline', 'Clear guidelines on data collection can help researchers protect participants while maintaining the quality of their studies.', 'Clear guidelines on data collection can help researchers protect participants while maintaining the quality of their studies.', '/ˈɡaɪdlaɪn/', 'Các hướng dẫn rõ ràng về việc thu thập dữ liệu có thể giúp các nhà nghiên cứu bảo vệ người tham gia đồng thời duy trì chất lượng nghiên cứu của họ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_49_2_3', 'ten_b2_49_2', 'recruit', 'Hospitals need to recruit more nurses to meet the growing demand for healthcare services.', 'Hospitals need to recruit more nurses to meet the growing demand for healthcare services.', '/rɪˈkruːt/', 'Các bệnh viện cần tuyển thêm y tá để đáp ứng nhu cầu dịch vụ chăm sóc sức khỏe ngày càng tăng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_49_2_4', 'ten_b2_49_2', 'rival', 'Smaller companies can rival larger firms by offering personalised services and responding quickly to customer needs.', 'Smaller companies can rival larger firms by offering personalised services and responding quickly to customer needs.', '/ˈraɪvəl/', 'Các công ty nhỏ hơn có thể sánh ngang với các hãng lớn hơn bằng cách cung cấp các dịch vụ cá nhân hóa và phản hồi nhanh chóng trước nhu cầu của khách hàng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_49_2_5', 'ten_b2_49_2', 'short-term', 'Short-term solutions may reduce immediate pressure but fail to address the underlying causes of unemployment.', 'Short-term solutions may reduce immediate pressure but fail to address the underlying causes of unemployment.', '/ˌʃɔːrt ˈtɝːm/', 'Các giải pháp ngắn hạn có thể làm giảm bớt áp lực trước mắt nhưng lại không giải quyết được nguyên nhân gốc rễ của tình trạng thất nghiệp.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_49_2_6', 'ten_b2_49_2', 'executive', 'Senior executives should consider employee wellbeing alongside financial performance when making decisions about company restructuring.', 'Senior executives should consider employee wellbeing alongside financial performance when making decisions about company restructuring.', '/ɪɡˈzekjətɪv/', 'Các nhà quản lý cấp cao nên cân nhắc phúc lợi của nhân viên bên cạnh hiệu quả tài chính khi đưa ra quyết định tái cơ cấu công ty.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_49_2_1', 'en-b2-49', 'ten_b2_49_2', 'listening', 'listening', 'Effective leadership in schools can improve staff morale and create a more supportive learning environment.', NULL, 'Trong câu vừa nghe, từ “leadership” mang nghĩa nào sau đây?', '["một miếng to, dày","năng lực lãnh đạo, sự lãnh đạo (khả năng hoặc hoạt động dẫn dắt mọi người hướng tới các mục tiêu chung)","oxi; khí oxy","xác định vị trí; tìm ra"]'::jsonb, 1, '“leadership” (/ˈliːdərʃɪp/): năng lực lãnh đạo, sự lãnh đạo (khả năng hoặc hoạt động dẫn dắt mọi người hướng tới các mục tiêu chung). Câu đầy đủ: Effective leadership in schools can improve staff morale and create a more supportive learning environment.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_49_2_2', 'en-b2-49', 'ten_b2_49_2', 'listening', 'listening', 'Clear guidelines on data collection can help researchers protect participants while maintaining the quality of their studies.', NULL, 'Trong câu vừa nghe, từ “guideline” mang nghĩa nào sau đây?', '["đáng kể; quan trọng; lớn","lời khuyên; nguyên tắc chỉ đạo; hướng dẫn; quy tắc","sưng lên; phồng lên","người ứng tuyển; thí sinh; người nộp đơn"]'::jsonb, 1, '“guideline” (/ˈɡaɪdlaɪn/): lời khuyên; nguyên tắc chỉ đạo; hướng dẫn; quy tắc. Câu đầy đủ: Clear guidelines on data collection can help researchers protect participants while maintaining the quality of their studies.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
