INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_49_1', 'en-b2-49', NULL, 'comprehensive_test', 'listening', 'leadership', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cuộc thăm dò ý kiến; điều tra dư luận","phổ biến; toàn cục; chung cho tất cả","nỗi thống khổ; sự đau buồn; sự lo lắng","năng lực lãnh đạo, sự lãnh đạo (khả năng hoặc hoạt động dẫn dắt mọi người hướng tới các mục tiêu chung)"]'::jsonb, 3, 'leadership (/ˈliːdərʃɪp/) → năng lực lãnh đạo, sự lãnh đạo (khả năng hoặc hoạt động dẫn dắt mọi người hướng tới các mục tiêu chung); ban lãnh đạo, giới lãnh đạo (những người điều hành một tổ chức hoặc quốc gia)', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_49_2', 'en-b2-49', NULL, 'comprehensive_test', 'listening', 'These guidelines explain how to store food safely.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tinh thần đồng đội tốt đã giúp chúng tôi hoàn thành việc sơn trước bữa trưa.","Trạm cứu hộ động vật đang tuyển tình nguyện viên cho các ca làm việc cuối tuần.","Công việc ngắn hạn này sẽ giúp tôi trang trải các khoản chi phí mùa hè.","Những hướng dẫn này giải thích cách bảo quản thực phẩm an toàn."]'::jsonb, 3, 'These guidelines explain how to store food safely. → Những hướng dẫn này giải thích cách bảo quản thực phẩm an toàn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_49_3', 'en-b2-49', NULL, 'comprehensive_test', 'listening', 'recruit', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tuyển dụng; chiêu mộ; tuyển","động từ: nghi ngờ; phỏng đoán","mua; tậu","làm ngắn lại; rút ngắn; thu ngắn"]'::jsonb, 0, 'recruit (/rɪˈkruːt/) → tuyển dụng; chiêu mộ; tuyển; nhân viên mới; thành viên mới; tân binh', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_49_4', 'en-b2-49', NULL, 'comprehensive_test', 'listening', 'She shook hands with her rival before the race.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Các tài xế đang đình công nên chúng tôi phải đi bộ về nhà.","Công việc ngắn hạn này sẽ giúp tôi trang trải các khoản chi phí mùa hè.","Chỉ có thợ điện có chuyên môn mới nên sửa chữa ổ cắm bị hỏng đó.","Cô ấy bắt tay với đối thủ của mình trước cuộc đua."]'::jsonb, 3, 'She shook hands with her rival before the race. → Cô ấy bắt tay với đối thủ của mình trước cuộc đua.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_49_5', 'en-b2-49', NULL, 'comprehensive_test', 'listening', 'short-term', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự can thiệp; sự nhúng tay","ngắn hạn","lỗ khóa; ổ khóa","hoài nghi; không chắc chắn"]'::jsonb, 1, 'short-term (/ˌʃɔːrt ˈtɝːm/) → ngắn hạn', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_49_6', 'en-b2-49', NULL, 'comprehensive_test', 'listening', 'The executive joined our team for lunch today.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi sẽ tiếp tục đi dạo khi trời tạnh mưa.","Vị giám đốc điều hành đã cùng đội ngũ của chúng tôi dùng bữa trưa hôm nay.","Xin hãy chậm rãi đọc lời nhắn để tôi ghi lại.","Việc sửa chữa đang diễn ra đồng nghĩa với việc chúng tôi không thể sử dụng nhà bếp."]'::jsonb, 1, 'The executive joined our team for lunch today. → Vị giám đốc điều hành đã cùng đội ngũ của chúng tôi dùng bữa trưa hôm nay.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_49_7', 'en-b2-49', NULL, 'comprehensive_test', 'listening', 'qualified', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự đánh giá; sự nhận định","có chuyên môn; đủ tiêu chuẩn; có năng lực","chuyên dụng; chuyên khoa; chuyên môn hóa","trang thiết bị; đồ dùng"]'::jsonb, 1, 'qualified (/ˈkwɑːlɪfaɪd/) → có chuyên môn; đủ tiêu chuẩn; có năng lực; có giới hạn; có điều kiện; chưa trọn vẹn', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_49_8', 'en-b2-49', NULL, 'comprehensive_test', 'listening', 'Please dictate your message slowly while I write it down.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Việc sửa chữa đang diễn ra đồng nghĩa với việc chúng tôi không thể sử dụng nhà bếp.","Chúng tôi sẽ tiếp tục đi dạo khi trời tạnh mưa.","Xin hãy chậm rãi đọc lời nhắn để tôi ghi lại.","Một người lớn phải trông nom trẻ em ở gần khu vực hồ bơi."]'::jsonb, 2, 'Please dictate your message slowly while I write it down. → Xin hãy chậm rãi đọc lời nhắn để tôi ghi lại.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_49_9', 'en-b2-49', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “lasting or having effects for only a limited time”?', '["capable","strike","marketing","short-term"]'::jsonb, 3, 'short-term (/ˌʃɔːrt ˈtɝːm/) → ngắn hạn', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_49_10', 'en-b2-49', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a person with important management responsibilities in an organisation”?', '["overtime","marketing","executive","qualified"]'::jsonb, 2, 'executive (/ɪɡˈzekjətɪv/) → nhà quản lý cấp cao; giám đốc điều hành', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_49_11', 'en-b2-49', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “having the training, skills, or experience needed for something”?', '["qualified","punctual","guideline","supervise"]'::jsonb, 0, 'qualified (/ˈkwɑːlɪfaɪd/) → có chuyên môn; đủ tiêu chuẩn; có năng lực', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_49_12', 'en-b2-49', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to say words aloud for someone or something to record”?', '["dictate","specify","short-term","punctual"]'::jsonb, 0, 'dictate (/ˈdɪkteɪt/) → đọc cho viết; ra lệnh ghi chép', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_49_13', 'en-b2-49', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To examine something carefully for faults or other details.”?', '["recruit","dictate","overtime","inspect"]'::jsonb, 3, 'inspect (/ɪnˈspekt/) → kiểm tra; thanh tra (kỹ lưỡng để tìm lỗi hoặc chi tiết)', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
