INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_49_18', 'en-b2-49', NULL, 'comprehensive_test', 'reading', NULL, 'Effective leadership in schools can improve staff morale and create a more supportive learning environment.', 'Dựa vào câu trên, từ “leadership” có nghĩa phù hợp nhất là gì?', '["năng lực lãnh đạo, sự lãnh đạo (khả năng hoặc hoạt động dẫn dắt mọi người hướng tới các mục tiêu chung)","phá rừng; nạn phá rừng","nhà u tư; chủ doanh nghiệp; doanh nhân","hiệu quả; tính hiệu quả; thành quả"]'::jsonb, 0, 'leadership: năng lực lãnh đạo, sự lãnh đạo (khả năng hoặc hoạt động dẫn dắt mọi người hướng tới các mục tiêu chung); ban lãnh đạo, giới lãnh đạo (những người điều hành một tổ chức hoặc quốc gia). Dịch cả câu: Năng lực lãnh đạo hiệu quả trong trường học có thể nâng cao tinh thần làm việc của giáo viên nhân viên và tạo ra môi trường học tập hỗ trợ tốt hơn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_49_19', 'en-b2-49', NULL, 'comprehensive_test', 'reading', NULL, 'Clear guidelines on data collection can help researchers protect participants while maintaining the quality of their studies.', 'Dựa vào câu trên, từ “guideline” có nghĩa phù hợp nhất là gì?', '["hình minh họa; tranh minh họa","lời khuyên; nguyên tắc chỉ đạo; hướng dẫn; quy tắc","sự ổn định; tính vững chắc","sự phun trào (núi lửa)"]'::jsonb, 1, 'guideline: lời khuyên; nguyên tắc chỉ đạo; hướng dẫn; quy tắc. Dịch cả câu: Các hướng dẫn rõ ràng về việc thu thập dữ liệu có thể giúp các nhà nghiên cứu bảo vệ người tham gia đồng thời duy trì chất lượng nghiên cứu của họ.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_49_20', 'en-b2-49', NULL, 'comprehensive_test', 'reading', NULL, 'Hospitals need to recruit more nurses to meet the growing demand for healthcare services.', 'Dựa vào câu trên, từ “recruit” có nghĩa phù hợp nhất là gì?', '["quyền sở hữu","tuyển dụng; chiêu mộ; tuyển","thì thầm; nói nhỏ; tai bay vách đá","thay đổi thất thường; dễ thay đổi"]'::jsonb, 1, 'recruit: tuyển dụng; chiêu mộ; tuyển; nhân viên mới; thành viên mới; tân binh. Dịch cả câu: Các bệnh viện cần tuyển thêm y tá để đáp ứng nhu cầu dịch vụ chăm sóc sức khỏe ngày càng tăng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_49_21', 'en-b2-49', NULL, 'comprehensive_test', 'reading', NULL, 'Smaller companies can rival larger firms by offering personalised services and responding quickly to customer needs.', 'Dựa vào câu trên, từ “rival” có nghĩa phù hợp nhất là gì?', '["bảo vệ; bảo quản; duy trì","thuộc về ánh sáng; quang học","sự tức giận; cơn giận","đối thủ; người cạnh tranh"]'::jsonb, 3, 'rival: đối thủ; người cạnh tranh; sánh kịp; sánh ngang; địch lại; cạnh tranh; đối lập. Dịch cả câu: Các công ty nhỏ hơn có thể sánh ngang với các hãng lớn hơn bằng cách cung cấp các dịch vụ cá nhân hóa và phản hồi nhanh chóng trước nhu cầu của khách hàng.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_49_22', 'en-b2-49', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cách xử lý; sự giải quyết”', '["heap","handling","sob","sponsor"]'::jsonb, 1, 'cách xử lý; sự giải quyết → handling (/ˈhændlɪŋ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_49_23', 'en-b2-49', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cuộc đình công”', '["strike","miracle","fantasy","trail"]'::jsonb, 0, 'cuộc đình công → strike (/straɪk/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_49_24', 'en-b2-49', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thủ công; bằng tay”', '["exclaim","wholesaler","satisfy","manual"]'::jsonb, 3, 'thủ công; bằng tay → manual (/ˈmænjuəl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-50', 'en', 'Bài 50: Công việc & Nghề nghiệp (5) - CEFR B2', 'CEFR B2', 'B2 · Công việc', '25 từ vựng Tiếng Anh CEFR B2 chủ đề công việc & nghề nghiệp kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4050, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_expertise', 'en-b2-50', 'expertise', '/ˌekspɜːrˈtiːz/', 'B2', 'kiến thức chuyên môn; kỹ năng chuyên sâu', 'n.', 'expert (n.), expert (adj.), expertly (adv.)', 'Đồng nghĩa: specialist knowledge, know-how', 'Là danh từ không đếm được; chỉ chuyên môn trong một lĩnh vực nào đó dùng expertise in.', 'We need your expertise to repair this old clock.', NULL, 'Chúng tôi cần chuyên môn của bạn để sửa chiếc đồng hồ cũ này.', '{"wordId":"expertise","ukIpa":"/ˌekspɜːˈtiːz/","usIpa":"/ˌekspɜːrˈtiːz/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"Specialist knowledge or skills gained through training and experience.","vi":"kiến thức chuyên môn; kỹ năng chuyên sâu"}],"examples":[{"en":"We need your expertise to repair this old clock.","vi":"Chúng tôi cần chuyên môn của bạn để sửa chiếc đồng hồ cũ này.","audioKind":"ex"},{"en":"Universities can support local businesses by sharing their expertise in renewable energy and sustainable manufacturing.","vi":"Các trường đại học có thể hỗ trợ các doanh nghiệp địa phương bằng cách chia sẻ chuyên môn của họ trong lĩnh vực năng lượng tái tạo và sản xuất bền vững.","audioKind":"ex2"}],"collocations":[{"en":"technical expertise","vi":"chuyên môn kỹ thuật"},{"en":"expertise in","vi":"chuyên môn trong lĩnh vực gì"},{"en":"develop expertise","vi":"phát triển chuyên môn"},{"en":"draw on expertise","vi":"tận dụng chuyên môn"}],"wordFamily":["expert (n.)","expert (adj.)","expertly (adv.)"],"synonyms":["specialist knowledge","know-how"],"antonyms":[],"tipVi":"Là danh từ không đếm được; chỉ chuyên môn trong một lĩnh vực nào đó dùng expertise in.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_obtain', 'en-b2-50', 'obtain', '/əbˈteɪn/', 'B2', 'đạt được; giành được; thu được', 'v.', 'obtainable (adj.), unobtainable (adj.)', 'Đồng nghĩa: get, acquire, secure', 'Trang trọng hơn từ get; thường dùng obtain sth from sb hoặc một tổ chức nào đó.', 'You can obtain a replacement key from the landlord.', NULL, 'Bạn có thể lấy một chiếc chìa khóa dự phòng từ chủ nhà.', '{"wordId":"obtain","ukIpa":"/əbˈteɪn/","usIpa":"/əbˈteɪn/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"To get something, especially through effort or a formal process.","vi":"đạt được; giành được; thu được"}],"examples":[{"en":"You can obtain a replacement key from the landlord.","vi":"Bạn có thể lấy một chiếc chìa khóa dự phòng từ chủ nhà.","audioKind":"ex"},{"en":"Researchers must obtain informed consent from participants before collecting personal data for a scientific study.","vi":"Các nhà nghiên cứu phải có được sự đồng thuận sau khi đã được cung cấp đầy đủ thông tin từ những người tham gia trước khi thu thập dữ liệu cá nhân cho một nghiên cứu khoa học.","audioKind":"ex2"}],"collocations":[{"en":"obtain permission","vi":"được phép; xin phép"},{"en":"obtain information","vi":"thu thập thông tin"},{"en":"obtain a qualification","vi":"đạt được bằng cấp"},{"en":"obtain consent","vi":"có được sự đồng ý"}],"wordFamily":["obtainable (adj.)","unobtainable (adj.)"],"synonyms":["get","acquire","secure"],"antonyms":[],"tipVi":"Trang trọng hơn từ get; thường dùng obtain sth from sb hoặc một tổ chức nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_outstanding', 'en-b2-50', 'outstanding', '/aʊtˈstændɪŋ/', 'B2', 'xuất sắc; nổi bật; lỗi lạc; chưa giải quyết; chưa thanh toán; còn đọng lại', 'adj.', 'outstandingly (adv.)', 'Đồng nghĩa: excellent, exceptional · Trái nghĩa: mediocre', 'Cụm outstanding debt mang nghĩa khoản nợ chưa thanh toán, không dịch là ''khoản nợ xuất sắc''.', 'The young pianist gave an outstanding performance last night.', NULL, 'Nghệ sĩ piano trẻ tuổi đã có một buổi biểu diễn xuất sắc vào tối qua.', '{"wordId":"outstanding","ukIpa":"/aʊtˈstændɪŋ/","usIpa":"/aʊtˈstændɪŋ/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"Extremely good and much better than average.","vi":"xuất sắc; nổi bật; lỗi lạc"},{"pos":"adj.","en":"Not yet completed, settled, or paid.","vi":"chưa giải quyết; chưa thanh toán; còn đọng lại"}],"examples":[{"en":"The young pianist gave an outstanding performance last night.","vi":"Nghệ sĩ piano trẻ tuổi đã có một buổi biểu diễn xuất sắc vào tối qua.","audioKind":"ex"},{"en":"Universities should recognise outstanding teaching as well as research when deciding which staff members to promote.","vi":"Các trường đại học nên ghi nhận chất lượng giảng dạy xuất sắc bên cạnh công tác nghiên cứu khi quyết định thăng chức cho nhân sự.","audioKind":"ex2"}],"collocations":[{"en":"outstanding achievement","vi":"thành tựu xuất sắc"},{"en":"outstanding performance","vi":"màn trình diễn xuất sắc"},{"en":"outstanding debt","vi":"khoản nợ chưa trả"},{"en":"outstanding issues","vi":"các vấn đề tồn đọng"}],"wordFamily":["outstandingly (adv.)"],"synonyms":["excellent","exceptional"],"antonyms":["mediocre"],"tipVi":"Cụm outstanding debt mang nghĩa khoản nợ chưa thanh toán, không dịch là ''khoản nợ xuất sắc''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ambitious', 'en-b2-50', 'ambitious', '/æmˈbɪʃəs/', 'B2', 'có hoài bão; đầy tham vọng; quy mô lớn; đòi hỏi nhiều nỗ lực hoặc nguồn lực để thành công', 'adj.', 'ambition (n.), ambitiously (adv.)', 'Đồng nghĩa: aspiring · Trái nghĩa: unambitious', 'Khi mô tả con người nghĩa là có hoài bão; khi mô tả kế hoạch thì nhấn mạnh mục tiêu lớn và độ khó cao.', 'My ambitious sister hopes to run her own bakery.', NULL, 'Người chị đầy hoài bão của tôi hy vọng sẽ tự điều hành một tiệm bánh của riêng mình.', '{"wordId":"ambitious","ukIpa":"/æmˈbɪʃəs/","usIpa":"/æmˈbɪʃəs/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"strongly wanting to achieve success","vi":"có hoài bão; đầy tham vọng"},{"pos":"adj.","en":"requiring considerable effort or resources to succeed","vi":"quy mô lớn; đòi hỏi nhiều nỗ lực hoặc nguồn lực để thành công"}],"examples":[{"en":"My ambitious sister hopes to run her own bakery.","vi":"Người chị đầy hoài bão của tôi hy vọng sẽ tự điều hành một tiệm bánh của riêng mình.","audioKind":"ex"},{"en":"The city has announced an ambitious plan to replace all diesel buses with electric vehicles within a decade.","vi":"Thành phố đã công bố một kế hoạch đầy tham vọng nhằm thay thế toàn bộ xe buýt chạy bằng dầu diesel bằng xe điện trong vòng một thập kỷ.","audioKind":"ex2"}],"collocations":[{"en":"ambitious goals","vi":"mục tiêu lớn lao"},{"en":"ambitious plan","vi":"kế hoạch đầy tham vọng"},{"en":"highly ambitious","vi":"rất có hoài bão"},{"en":"ambitious young people","vi":"những người trẻ có hoài bão"}],"wordFamily":["ambition (n.)","ambitiously (adv.)"],"synonyms":["aspiring"],"antonyms":["unambitious"],"tipVi":"Khi mô tả con người nghĩa là có hoài bão; khi mô tả kế hoạch thì nhấn mạnh mục tiêu lớn và độ khó cao.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fulfil', 'en-b2-50', 'fulfil', '/fʊlˈfɪl/', 'B2', 'thực hiện; hoàn thành (nhiệm vụ, lời hứa, thỏa thuận); đáp ứng; thỏa mãn (nhu cầu, yêu cầu); đạt được (điều mong mỏi); phát huy tối đa (năng lực)', 'v.', 'fulfilment (n.), fulfilling (adj.), unfulfilled (adj.)', NULL, 'Cách viết Anh-Anh là fulfil, Anh-Mỹ là fulfill; dạng quá khứ đều là fulfilled.', 'She fulfilled her promise and repaired my bicycle.', NULL, 'Cô ấy đã giữ đúng lời hứa và sửa chiếc xe đạp cho tôi.', '{"wordId":"fulfil","ukIpa":"/fʊlˈfɪl/","usIpa":"/fʊlˈfɪl/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"to do what a duty, promise, or agreement requires","vi":"thực hiện; hoàn thành (nhiệm vụ, lời hứa, thỏa thuận)"},{"pos":"v.","en":"to provide what is needed or meet a requirement","vi":"đáp ứng; thỏa mãn (nhu cầu, yêu cầu)"},{"pos":"v.","en":"to achieve something hoped for or develop an ability fully","vi":"đạt được (điều mong mỏi); phát huy tối đa (năng lực)"}],"examples":[{"en":"She fulfilled her promise and repaired my bicycle.","vi":"Cô ấy đã giữ đúng lời hứa và sửa chiếc xe đạp cho tôi.","audioKind":"ex"},{"en":"Public libraries fulfil an important social role by providing free access to information and learning resources.","vi":"Các thư viện công cộng đóng vai trò xã hội quan trọng bằng cách cung cấp quyền truy cập miễn phí vào thông tin và tài nguyên học tập.","audioKind":"ex2"}],"collocations":[{"en":"fulfil a promise","vi":"thực hiện lời hứa"},{"en":"fulfil requirements","vi":"đáp ứng các yêu cầu"},{"en":"fulfil your potential","vi":"phát huy tiềm năng của bạn"},{"en":"fulfil a dream","vi":"thực hiện ước mơ"}],"wordFamily":["fulfilment (n.)","fulfilling (adj.)","unfulfilled (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cách viết Anh-Anh là fulfil, Anh-Mỹ là fulfill; dạng quá khứ đều là fulfilled.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_specialist', 'en-b2-50', 'specialist', '/ˈspeʃəlɪst/', 'B2', 'chuyên gia; bác sĩ chuyên khoa; chuyên môn; chuyên sâu', 'n.', 'specialise (v.), specialisation (n.), specialised (adj.)', 'Đồng nghĩa: expert', 'Danh từ đi với giới từ in để chỉ lĩnh vực chuyên môn; tính từ thường bổ nghĩa cho knowledge.', 'My doctor sent me to a skin specialist.', NULL, 'Bác sĩ của tôi đã chuyển tôi đến gặp bác sĩ chuyên khoa da liễu.', '{"wordId":"specialist","ukIpa":"/ˈspeʃəlɪst/","usIpa":"/ˈspeʃəlɪst/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"Someone with detailed knowledge or training in a particular field.","vi":"chuyên gia; bác sĩ chuyên khoa"},{"pos":"adj.","en":"Connected with a particular field requiring special knowledge.","vi":"chuyên môn; chuyên sâu"}],"examples":[{"en":"My doctor sent me to a skin specialist.","vi":"Bác sĩ của tôi đã chuyển tôi đến gặp bác sĩ chuyên khoa da liễu.","audioKind":"ex"},{"en":"Schools should employ a specialist to support children who have difficulties with language development.","vi":"Các trường học nên thuê một chuyên gia để hỗ trợ trẻ em gặp khó khăn trong việc phát triển ngôn ngữ.","audioKind":"ex2"}],"collocations":[{"en":"a specialist in","vi":"chuyên gia về lĩnh vực gì"},{"en":"see a specialist","vi":"gặp bác sĩ chuyên khoa"},{"en":"specialist knowledge","vi":"kiến thức chuyên môn"},{"en":"specialist training","vi":"đào tạo chuyên sâu"}],"wordFamily":["specialise (v.)","specialisation (n.)","specialised (adj.)"],"synonyms":["expert"],"antonyms":[],"tipVi":"Danh từ đi với giới từ in để chỉ lĩnh vực chuyên môn; tính từ thường bổ nghĩa cho knowledge.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_invoice', 'en-b2-50', 'invoice', '/ˈɪnvɔɪs/', 'B2', 'hóa đơn; bảng kê tiền hàng; lập hóa đơn; gửi hóa đơn', 'n.', 'invoicing (n.)', 'Đồng nghĩa: bill', 'invoice thường dùng để yêu cầu thanh toán; receipt là biên lai đã thanh toán.', 'The plumber emailed an invoice after fixing our sink.', NULL, 'Thợ sửa ống nước đã gửi email hóa đơn sau khi sửa bồn rửa của chúng tôi.', '{"wordId":"invoice","ukIpa":"/ˈɪnvɔɪs/","usIpa":"/ˈɪnvɔɪs/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"a document listing goods or services and the payment required","vi":"hóa đơn; bảng kê tiền hàng"},{"pos":"v.","en":"to send someone a document requesting payment for goods or services","vi":"lập hóa đơn; gửi hóa đơn"}],"examples":[{"en":"The plumber emailed an invoice after fixing our sink.","vi":"Thợ sửa ống nước đã gửi email hóa đơn sau khi sửa bồn rửa của chúng tôi.","audioKind":"ex"},{"en":"Small businesses benefit from digital systems that track each invoice and remind customers when payments are due.","vi":"Các doanh nghiệp nhỏ được hưởng lợi từ các hệ thống kỹ thuật số giúp theo dõi từng hóa đơn và nhắc nhở khách hàng khi đến hạn thanh toán.","audioKind":"ex2"}],"collocations":[{"en":"issue an invoice","vi":"lập hóa đơn"},{"en":"pay an invoice","vi":"thanh toán hóa đơn"},{"en":"an outstanding invoice","vi":"hóa đơn chưa thanh toán"},{"en":"invoice someone for something","vi":"gửi hóa đơn tính tiền cho ai đó"}],"wordFamily":["invoicing (n.)"],"synonyms":["bill"],"antonyms":[],"tipVi":"invoice thường dùng để yêu cầu thanh toán; receipt là biên lai đã thanh toán.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mill', 'en-b2-50', 'mill', '/mɪl/', 'B2', 'cối xay; nhà máy xay xát (lúa mì, ngũ cốc); nhà máy; xưởng chế biến (giấy, thép); nghiền; xay nhỏ thành bột', 'n.', 'miller (n.), milling (n.)', NULL, 'mill thường chỉ nhà máy chế biến nguyên liệu; nhà máy thông thường dùng factory.', 'We watched wheat being ground at the old mill.', NULL, 'Chúng tôi đã xem người ta xay lúa mì tại cối xay cũ.', '{"wordId":"mill","ukIpa":"/mɪl/","usIpa":"/mɪl/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"a building or machine where grain is ground into flour","vi":"cối xay; nhà máy xay xát (lúa mì, ngũ cốc)"},{"pos":"n.","en":"a factory that processes materials such as paper or steel","vi":"nhà máy; xưởng chế biến (giấy, thép)"},{"pos":"v.","en":"to crush grain or other material into small particles","vi":"nghiền; xay nhỏ thành bột"}],"examples":[{"en":"We watched wheat being ground at the old mill.","vi":"Chúng tôi đã xem người ta xay lúa mì tại cối xay cũ.","audioKind":"ex"},{"en":"Converting abandoned textile mills into housing can preserve industrial heritage while meeting demand for urban accommodation.","vi":"Việc chuyển đổi các nhà máy dệt bỏ hoang thành nhà ở có thể bảo tồn di sản công nghiệp đồng thời đáp ứng nhu cầu nhà ở đô thị.","audioKind":"ex2"}],"collocations":[{"en":"flour mill","vi":"nhà máy bột mì; cối xay bột"},{"en":"steel mill","vi":"nhà máy thép"},{"en":"paper mill","vi":"nhà máy giấy"},{"en":"mill grain","vi":"nghiền ngũ cốc"}],"wordFamily":["miller (n.)","milling (n.)"],"synonyms":[],"antonyms":[],"tipVi":"mill thường chỉ nhà máy chế biến nguyên liệu; nhà máy thông thường dùng factory.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_coordination', 'en-b2-50', 'coordination', '/koʊˌɔːrdɪˈneɪʃən/', 'B2', 'sự phối hợp; sự điều phối; khả năng phối hợp vận động cơ thể', 'n.', 'coordinate (v.), coordinator (n.), coordinated (adj.)', NULL, 'Thường là danh từ không đếm được; giới từ between dùng để chỉ các bên cần phối hợp với nhau.', 'Moving this sofa upstairs will take some coordination.', NULL, 'Việc chuyển chiếc ghế sofa này lên lầu sẽ cần sự phối hợp nhịp nhàng.', '{"wordId":"coordination","ukIpa":"/kəʊˌɔːdɪˈneɪʃən/","usIpa":"/koʊˌɔːrdɪˈneɪʃən/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"Organising people or activities so they work effectively together","vi":"sự phối hợp; sự điều phối"},{"pos":"n.","en":"The ability to move different body parts smoothly together","vi":"khả năng phối hợp vận động cơ thể"}],"examples":[{"en":"Moving this sofa upstairs will take some coordination.","vi":"Việc chuyển chiếc ghế sofa này lên lầu sẽ cần sự phối hợp nhịp nhàng.","audioKind":"ex"},{"en":"Effective coordination between schools and health services can improve support for children with additional needs.","vi":"Sự phối hợp hiệu quả giữa nhà trường và các cơ quan y tế có thể cải thiện việc hỗ trợ cho trẻ em có nhu cầu đặc biệt.","audioKind":"ex2"}],"collocations":[{"en":"close coordination","vi":"sự phối hợp chặt chẽ"},{"en":"coordination between departments","vi":"sự phối hợp giữa các phòng ban"},{"en":"hand-eye coordination","vi":"khả năng phối hợp tay mắt"}],"wordFamily":["coordinate (v.)","coordinator (n.)","coordinated (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; giới từ between dùng để chỉ các bên cần phối hợp với nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_carpentry', 'en-b2-50', 'carpentry', '/ˈkɑːrpəntri/', 'B2', 'nghề mộc; kỹ thuật làm mộc', 'n.', 'carpenter (n.)', NULL, 'Carpentry chỉ kỹ năng hoặc công việc mộc; trong khi carpenter chỉ người thợ mộc.', 'I learned basic carpentry by building a small bookshelf.', NULL, 'Tôi đã tự học các kỹ thuật mộc cơ bản bằng cách tự đóng một chiếc giá sách nhỏ.', '{"wordId":"carpentry","ukIpa":"/ˈkɑːpəntri/","usIpa":"/ˈkɑːrpəntri/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"The work or skill of making and repairing wooden structures.","vi":"nghề mộc; kỹ thuật làm mộc"}],"examples":[{"en":"I learned basic carpentry by building a small bookshelf.","vi":"Tôi đã tự học các kỹ thuật mộc cơ bản bằng cách tự đóng một chiếc giá sách nhỏ.","audioKind":"ex"},{"en":"Schools that offer carpentry courses can help students develop practical skills and explore careers in construction.","vi":"Các trường học cung cấp khóa học về mộc có thể giúp học sinh phát triển kỹ năng thực tế và định hướng nghề nghiệp trong ngành xây dựng.","audioKind":"ex2"}],"collocations":[{"en":"carpentry skills","vi":"kỹ năng làm mộc"},{"en":"carpentry workshop","vi":"xưởng mộc"},{"en":"basic carpentry","vi":"nghề mộc cơ bản"},{"en":"carpentry tools","vi":"dụng cụ làm mộc"}],"wordFamily":["carpenter (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Carpentry chỉ kỹ năng hoặc công việc mộc; trong khi carpenter chỉ người thợ mộc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chief', 'en-b2-50', 'chief', '/tʃiːf/', 'B2', 'chính; chủ yếu; quan trọng nhất; cấp cao nhất; đứng đầu; thủ lĩnh; người đứng đầu; người phụ trách', 'adj.', 'chiefly (adv.)', 'Đồng nghĩa: main, principal · Trái nghĩa: minor', 'chief có thể đóng vai trò là tính từ hoặc danh từ; phó từ tương ứng là chiefly.', 'My chief concern is getting everyone home safely.', NULL, 'Mối quan tâm hàng đầu của tôi là đưa mọi người về nhà an toàn.', '{"wordId":"chief","ukIpa":"/tʃiːf/","usIpa":"/tʃiːf/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"Most important among several things.","vi":"chính; chủ yếu; quan trọng nhất"},{"pos":"adj.","en":"Having the highest rank in an organisation or profession.","vi":"cấp cao nhất; đứng đầu"},{"pos":"n.","en":"The person who leads a group or organisation.","vi":"thủ lĩnh; người đứng đầu; người phụ trách"}],"examples":[{"en":"My chief concern is getting everyone home safely.","vi":"Mối quan tâm hàng đầu của tôi là đưa mọi người về nhà an toàn.","audioKind":"ex"},{"en":"The chief advantage of public transport is its ability to move large crowds while using less road space.","vi":"Ưu điểm chính của giao thông công cộng là khả năng vận chuyển lượng lớn hành khách trong khi sử dụng ít không gian mặt đường hơn.","audioKind":"ex2"}],"collocations":[{"en":"chief concern","vi":"mối quan tâm hàng đầu"},{"en":"chief executive","vi":"giám đốc điều hành"},{"en":"chief reason","vi":"nguyên nhân chính"},{"en":"police chief","vi":"cảnh sát trưởng"}],"wordFamily":["chiefly (adv.)"],"synonyms":["main","principal"],"antonyms":["minor"],"tipVi":"chief có thể đóng vai trò là tính từ hoặc danh từ; phó từ tương ứng là chiefly.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_memo', 'en-b2-50', 'memo', '/ˈmemoʊ/', 'B2', 'bản ghi nhớ; thông báo nội bộ', 'n.', NULL, NULL, 'memo thường chỉ thông báo nội bộ ngắn gọn trong công việc, số nhiều là memos.', 'Our manager sent a memo about the new opening hours.', NULL, 'Quản lý của chúng tôi đã gửi một bản ghi nhớ về giờ mở cửa mới.', '{"wordId":"memo","ukIpa":"/ˈmeməʊ/","usIpa":"/ˈmemoʊ/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"A short written message, especially between people at work.","vi":"bản ghi nhớ; thông báo nội bộ"}],"examples":[{"en":"Our manager sent a memo about the new opening hours.","vi":"Quản lý của chúng tôi đã gửi một bản ghi nhớ về giờ mở cửa mới.","audioKind":"ex"},{"en":"A clear internal memo can help employees understand changes to workplace policies and avoid unnecessary confusion.","vi":"Một bản ghi nhớ nội bộ rõ ràng có thể giúp nhân viên hiểu rõ những thay đổi trong chính sách nơi làm việc và tránh sự nhầm lẫn không đáng có.","audioKind":"ex2"}],"collocations":[{"en":"send a memo","vi":"gửi bản ghi nhớ"},{"en":"internal memo","vi":"thông báo nội bộ"},{"en":"a memo about something","vi":"bản ghi nhớ về một việc gì đó"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"memo thường chỉ thông báo nội bộ ngắn gọn trong công việc, số nhiều là memos.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_briefing', 'en-b2-50', 'briefing', '/ˈbriːfɪŋ/', 'B2', 'cuộc họp giao ban; buổi phổ biến thông tin, bản hướng dẫn', 'n.', 'brief (v.), debrief (v.), debriefing (n.)', NULL, 'Không chỉ là tài liệu tóm tắt dạng văn bản, từ này còn chỉ sự hướng dẫn trực tiếp hoặc buổi họp giao ban.', 'Our guide gave us a briefing before the hike.', NULL, 'Người hướng dẫn đã phổ biến cho chúng tôi một buổi hướng dẫn trước chuyến đi bộ đường dài.', '{"wordId":"briefing","ukIpa":"/ˈbriːfɪŋ/","usIpa":"/ˈbriːfɪŋ/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"a meeting or explanation giving essential information or instructions","vi":"cuộc họp giao ban; buổi phổ biến thông tin, bản hướng dẫn"}],"examples":[{"en":"Our guide gave us a briefing before the hike.","vi":"Người hướng dẫn đã phổ biến cho chúng tôi một buổi hướng dẫn trước chuyến đi bộ đường dài.","audioKind":"ex"},{"en":"A clear safety briefing helps construction workers understand potential hazards before they begin unfamiliar tasks.","vi":"Một buổi phổ biến an toàn rõ ràng giúp công nhân xây dựng hiểu rõ các mối nguy hiểm tiềm ẩn trước khi bắt đầu những công việc chưa quen thuộc.","audioKind":"ex2"}],"collocations":[{"en":"safety briefing","vi":"buổi phổ biến an toàn"},{"en":"press briefing","vi":"buổi họp báo"},{"en":"attend a briefing","vi":"tham gia buổi giao ban"},{"en":"briefing paper","vi":"tài liệu tóm tắt"}],"wordFamily":["brief (v.)","debrief (v.)","debriefing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Không chỉ là tài liệu tóm tắt dạng văn bản, từ này còn chỉ sự hướng dẫn trực tiếp hoặc buổi họp giao ban.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flexibility', 'en-b2-50', 'flexibility', '/ˌfleksəˈbɪləti/', 'B2', 'tính linh hoạt; khả năng uyển chuyển thích nghi; độ dẻo dai; tính co giãn', 'n.', 'flexible (adj.), flexibly (adv.), inflexible (adj.)', 'Đồng nghĩa: adaptability, versatility · Trái nghĩa: rigidity, inflexibility', 'Có thể chỉ sự sắp xếp linh hoạt hoặc độ dẻo dai của cơ thể hoặc vật liệu.', 'This job gives me flexibility to collect my daughter.', NULL, 'Công việc này mang lại cho tôi sự linh hoạt để đón con gái.', '{"wordId":"flexibility","ukIpa":"/ˌfleksəˈbɪləti/","usIpa":"/ˌfleksəˈbɪləti/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"the ability to change or adapt to different needs","vi":"tính linh hoạt; khả năng uyển chuyển thích nghi"},{"pos":"n.","en":"the ability to bend or stretch easily","vi":"độ dẻo dai; tính co giãn"}],"examples":[{"en":"This job gives me flexibility to collect my daughter.","vi":"Công việc này mang lại cho tôi sự linh hoạt để đón con gái.","audioKind":"ex"},{"en":"Greater flexibility in working hours can help employees balance professional responsibilities with family commitments.","vi":"Tính linh hoạt cao hơn trong thời gian làm việc có thể giúp nhân viên cân bằng giữa trách nhiệm công việc và nghĩa vụ gia đình.","audioKind":"ex2"}],"collocations":[{"en":"offer flexibility","vi":"cung cấp sự linh hoạt"},{"en":"greater flexibility","vi":"tính linh hoạt lớn hơn"},{"en":"improve flexibility","vi":"cải thiện độ dẻo dai"},{"en":"flexibility in working hours","vi":"sự linh hoạt trong thời gian làm việc"}],"wordFamily":["flexible (adj.)","flexibly (adv.)","inflexible (adj.)"],"synonyms":["adaptability","versatility"],"antonyms":["rigidity","inflexibility"],"tipVi":"Có thể chỉ sự sắp xếp linh hoạt hoặc độ dẻo dai của cơ thể hoặc vật liệu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_completion', 'en-b2-50', 'completion', '/kəmˈpliːʃən/', 'B2', 'sự hoàn thành; sự hoàn thành xong; sự khánh thành', 'n.', 'complete (v.), complete (adj.), completely (adv.), incomplete (adj.)', NULL, 'Thường dùng on completion of để chỉ "khi hoàn thành xong cái gì".', 'Our kitchen renovation is finally nearing completion this week.', NULL, 'Việc cải tạo nhà bếp của chúng tôi cuối cùng cũng sắp hoàn thành trong tuần này.', '{"wordId":"completion","ukIpa":"/kəmˈpliːʃən/","usIpa":"/kəmˈpliːʃən/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"The act or state of finishing something.","vi":"sự hoàn thành; sự hoàn thành xong; sự khánh thành"}],"examples":[{"en":"Our kitchen renovation is finally nearing completion this week.","vi":"Việc cải tạo nhà bếp của chúng tôi cuối cùng cũng sắp hoàn thành trong tuần này.","audioKind":"ex"},{"en":"The completion of the new railway is expected to improve access to employment in rural communities.","vi":"Việc hoàn thành tuyến đường sắt mới dự kiến sẽ cải thiện khả năng tiếp cận việc làm ở các cộng đồng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"on completion","vi":"khi hoàn thành"},{"en":"near completion","vi":"gần hoàn thành"},{"en":"successful completion","vi":"hoàn thành thành công"},{"en":"completion date","vi":"ngày hoàn thành"}],"wordFamily":["complete (v.)","complete (adj.)","completely (adv.)","incomplete (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng on completion of để chỉ \"khi hoàn thành xong cái gì\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_undertake', 'en-b2-50', 'undertake', '/ˌʌndərˈteɪk/', 'B2', 'đảm nhận; đảm nhiệm; tiến hành; hứa hẹn; cam kết', 'v.', 'undertaking (n.)', NULL, 'Dạng quá khứ là undertook và quá khứ phân từ là undertaken.', 'We undertook the repairs ourselves to save money.', NULL, 'Chúng tôi đã tự mình tiến hành sửa chữa để tiết kiệm chi phí.', '{"wordId":"undertake","ukIpa":"/ˌʌndəˈteɪk/","usIpa":"/ˌʌndərˈteɪk/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"Accept responsibility for a task and begin doing it","vi":"đảm nhận; đảm nhiệm; tiến hành"},{"pos":"v.","en":"Promise to do something","vi":"hứa hẹn; cam kết"}],"examples":[{"en":"We undertook the repairs ourselves to save money.","vi":"Chúng tôi đã tự mình tiến hành sửa chữa để tiết kiệm chi phí.","audioKind":"ex"},{"en":"Universities should undertake further research before recommending major changes to national education policy.","vi":"Các trường đại học nên tiến hành nghiên cứu sâu hơn trước khi đề xuất những thay đổi lớn đối với chính sách giáo dục quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"undertake research","vi":"tiến hành nghiên cứu"},{"en":"undertake a task","vi":"đảm nhận một nhiệm vụ"},{"en":"undertake to do something","vi":"cam kết làm điều gì đó"}],"wordFamily":["undertaking (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ là undertook và quá khứ phân từ là undertaken.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_attendant', 'en-b2-50', 'attendant', '/əˈtendənt/', 'B2', 'nhân viên phục vụ; người phục vụ; đi kèm; đi theo', 'n.', 'attend (v.), attendance (n.)', NULL, 'Attendant thường chỉ nhân viên phục vụ; người tham dự sự kiện thường dùng attendee.', 'The flight attendant brought an extra blanket for my daughter.', NULL, 'Nhân viên hàng không đã mang cho con gái tôi thêm một chiếc chăn.', '{"wordId":"attendant","ukIpa":"/əˈtendənt/","usIpa":"/əˈtendənt/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"Someone employed to help people in a public place.","vi":"nhân viên phục vụ; người phục vụ"},{"pos":"adj.","en":"Occurring together with something, often as a consequence.","vi":"đi kèm; đi theo"}],"examples":[{"en":"The flight attendant brought an extra blanket for my daughter.","vi":"Nhân viên hàng không đã mang cho con gái tôi thêm một chiếc chăn.","audioKind":"ex"},{"en":"Cities must consider population growth and its attendant pressures when planning new public transport networks.","vi":"Các thành phố phải cân nhắc sự bùng nổ dân số và những áp lực đi kèm khi lên kế hoạch cho các mạng lưới giao thông công cộng mới.","audioKind":"ex2"}],"collocations":[{"en":"flight attendant","vi":"tiếp viên hàng không"},{"en":"car park attendant","vi":"nhân viên trông giữ xe"},{"en":"attendant risks","vi":"các rủi ro đi kèm"}],"wordFamily":["attend (v.)","attendance (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Attendant thường chỉ nhân viên phục vụ; người tham dự sự kiện thường dùng attendee.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_procedure', 'en-b2-50', 'procedure', '/prəˈsiːdʒər/', 'B2', 'thủ tục; quy trình; bước thực hiện; thủ thuật y tế; ca phẫu thuật', 'n.', 'procedural (adj.)', NULL, 'procedure nhấn mạnh các bước quy định; process thiên về toàn bộ quá trình.', 'The receptionist explained the procedure for joining the gym.', NULL, 'Nhân viên tiếp tân đã giải thích thủ tục đăng ký làm thành viên phòng gym.', '{"wordId":"procedure","ukIpa":"/prəˈsiːdʒə/","usIpa":"/prəˈsiːdʒər/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"an established series of actions for completing a task","vi":"thủ tục; quy trình; bước thực hiện"},{"pos":"n.","en":"a medical action performed to diagnose or treat a condition","vi":"thủ thuật y tế; ca phẫu thuật"}],"examples":[{"en":"The receptionist explained the procedure for joining the gym.","vi":"Nhân viên tiếp tân đã giải thích thủ tục đăng ký làm thành viên phòng gym.","audioKind":"ex"},{"en":"Every laboratory should establish a clear procedure for handling chemicals safely and disposing of waste responsibly.","vi":"Mỗi phòng thí nghiệm nên thiết lập một quy trình rõ ràng để xử lý hóa chất an toàn và tiêu hủy chất thải có trách nhiệm.","audioKind":"ex2"}],"collocations":[{"en":"follow a procedure","vi":"tuân theo quy trình"},{"en":"standard procedure","vi":"thủ tục chuẩn"},{"en":"a surgical procedure","vi":"ca phẫu thuật"}],"wordFamily":["procedural (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"procedure nhấn mạnh các bước quy định; process thiên về toàn bộ quá trình.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_skilled', 'en-b2-50', 'skilled', '/skɪld/', 'B2', 'có tay nghề; lành nghề; đòi hỏi chuyên môn hoặc kỹ năng thực tế', 'adj.', 'skill (n.), skilful (adj.), skilfully (adv.), unskilled (adj.)', 'Đồng nghĩa: proficient, competent · Trái nghĩa: unskilled', 'skilled at/in đi kèm với danh từ hoặc danh động từ.', 'A skilled mechanic fixed my bicycle in minutes.', NULL, 'Một thợ sửa xe lành nghề đã sửa chiếc xe đạp của tôi chỉ trong vài phút.', '{"wordId":"skilled","ukIpa":"/skɪld/","usIpa":"/skɪld/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"Having the training and ability to do something well.","vi":"có tay nghề; lành nghề"},{"pos":"adj.","en":"Requiring special training or practical ability.","vi":"đòi hỏi chuyên môn hoặc kỹ năng thực tế"}],"examples":[{"en":"A skilled mechanic fixed my bicycle in minutes.","vi":"Một thợ sửa xe lành nghề đã sửa chiếc xe đạp của tôi chỉ trong vài phút.","audioKind":"ex"},{"en":"Investment in vocational education can help countries develop a skilled workforce and reduce unemployment.","vi":"Đầu tư vào giáo dục nghề nghiệp có thể giúp các quốc gia phát triển nguồn lao động lành nghề và giảm tỷ lệ thất nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"skilled worker","vi":"công nhân lành nghề"},{"en":"highly skilled","vi":"có tay nghề cao"},{"en":"skilled at","vi":"giỏi về"},{"en":"skilled labour","vi":"lực lượng lao động có tay nghề"}],"wordFamily":["skill (n.)","skilful (adj.)","skilfully (adv.)","unskilled (adj.)"],"synonyms":["proficient","competent"],"antonyms":["unskilled"],"tipVi":"skilled at/in đi kèm với danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_firm', 'en-b2-50', 'firm', '/fɝːm/', 'B2', 'công ty; hãng; chắc chắn; vững chắc; kiên quyết; nghiêm khắc', 'n.', 'firmly (adv.), firmness (n.)', 'Đồng nghĩa: company, solid, resolute', 'Danh từ chỉ công ty; tính từ có thể chỉ vật thể chắc chắn hoặc thái độ kiên quyết.', 'My sister works for a small engineering firm.', NULL, 'Chị gái tôi làm việc cho một công ty kỹ thuật nhỏ.', '{"wordId":"firm","ukIpa":"/fɜːm/","usIpa":"/fɝːm/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"a business that provides goods or professional services","vi":"công ty; hãng"},{"pos":"adj.","en":"solid and not easily moved or pressed out of shape","vi":"chắc chắn; vững chắc"},{"pos":"adj.","en":"unlikely to change a decision or allow rules to be broken","vi":"kiên quyết; nghiêm khắc"}],"examples":[{"en":"My sister works for a small engineering firm.","vi":"Chị gái tôi làm việc cho một công ty kỹ thuật nhỏ.","audioKind":"ex"},{"en":"Each firm should provide regular training to help employees adapt to technological change.","vi":"Mỗi công ty nên tổ chức đào tạo định kỳ để giúp nhân viên thích nghi với sự thay đổi công nghệ.","audioKind":"ex2"}],"collocations":[{"en":"a law firm","vi":"công ty luật"},{"en":"a firm belief","vi":"niềm tin vững chắc"},{"en":"firm ground","vi":"nền đất vững chắc"},{"en":"take a firm stand","vi":"giữ lập trường kiên quyết"}],"wordFamily":["firmly (adv.)","firmness (n.)"],"synonyms":["company","solid","resolute"],"antonyms":[],"tipVi":"Danh từ chỉ công ty; tính từ có thể chỉ vật thể chắc chắn hoặc thái độ kiên quyết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_absence', 'en-b2-50', 'absence', '/ˈæbsəns/', 'B2', 'sự vắng mặt; sự không có mặt; sự thiếu; sự không có', 'n.', 'absent (adj.)', 'Đồng nghĩa: lack, non-attendance · Trái nghĩa: presence', 'Vắng mặt ở sự kiện nào dùng "absence from"; thiếu cái gì dùng "absence of".', 'Her absence from dinner worried the whole family.', NULL, 'Việc cô ấy vắng mặt trong bữa tối khiến cả gia đình lo lắng.', '{"wordId":"absence","ukIpa":"/ˈæbsəns/","usIpa":"/ˈæbsəns/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"a situation in which someone is not present","vi":"sự vắng mặt; sự không có mặt"},{"pos":"n.","en":"a situation in which something does not exist or occur","vi":"sự thiếu; sự không có"}],"examples":[{"en":"Her absence from dinner worried the whole family.","vi":"Việc cô ấy vắng mặt trong bữa tối khiến cả gia đình lo lắng.","audioKind":"ex"},{"en":"In the absence of reliable public transport, many residents have little choice but to drive.","vi":"Trong điều kiện thiếu hệ thống giao thông công cộng đáng tin cậy, nhiều cư dân không có lựa chọn nào khác ngoài việc lái xe.","audioKind":"ex2"}],"collocations":[{"en":"absence from work","vi":"vắng mặt tại nơi làm việc"},{"en":"in someone''s absence","vi":"khi không có mặt ai đó"},{"en":"in the absence of","vi":"trong trường hợp thiếu..."},{"en":"leave of absence","vi":"xin nghỉ phép"}],"wordFamily":["absent (adj.)"],"synonyms":["lack","non-attendance"],"antonyms":["presence"],"tipVi":"Vắng mặt ở sự kiện nào dùng \"absence from\"; thiếu cái gì dùng \"absence of\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_internship', 'en-b2-50', 'internship', '/ˈɪntɜːrnʃɪp/', 'B2', 'kỳ thực tập, công việc thực tập', 'n.', 'intern (n.), intern (v.)', NULL, 'Từ "intern" chỉ người thực tập sinh, còn "internship" chỉ vị trí hoặc khoảng thời gian thực tập.', 'Leila started a summer internship at a local museum.', NULL, 'Leila bắt đầu kỳ thực tập hè tại một viện bảo tàng địa phương.', '{"wordId":"internship","ukIpa":"/ˈɪntɜːnʃɪp/","usIpa":"/ˈɪntɜːrnʃɪp/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"A temporary job providing practical experience in a particular field.","vi":"kỳ thực tập, công việc thực tập"}],"examples":[{"en":"Leila started a summer internship at a local museum.","vi":"Leila bắt đầu kỳ thực tập hè tại một viện bảo tàng địa phương.","audioKind":"ex"},{"en":"Paid internships can help students gain professional experience without placing additional financial pressure on their families.","vi":"Các chương trình thực tập có lương có thể giúp sinh viên tích lũy kinh nghiệm chuyên môn mà không gây thêm áp lực tài chính cho gia đình.","audioKind":"ex2"}],"collocations":[{"en":"paid internship","vi":"thực tập có lương"},{"en":"summer internship","vi":"thực tập mùa hè"},{"en":"apply for an internship","vi":"nộp đơn xin thực tập"}],"wordFamily":["intern (n.)","intern (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ \"intern\" chỉ người thực tập sinh, còn \"internship\" chỉ vị trí hoặc khoảng thời gian thực tập.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_contract', 'en-b2-50', 'contract', '/ˈkɑːntrækt/', 'B2', 'hợp đồng; khế ước; co lại; thu nhỏ; mắc bệnh; nhiễm bệnh', 'n.', 'contractual (adj.), contraction (n.), contractor (n.)', 'Đồng nghĩa: agreement', 'Danh từ có trọng âm ở âm tiết đầu; động từ đọc là /kənˈtrækt/.', 'Read the contract carefully before you agree to sign it.', NULL, 'Hãy đọc kỹ hợp đồng trước khi bạn đồng ý ký tên.', '{"wordId":"contract","ukIpa":"/ˈkɒntrækt/","usIpa":"/ˈkɑːntrækt/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"A legally binding agreement between people or organisations.","vi":"hợp đồng; khế ước"},{"pos":"v.","en":"To become smaller or make something smaller.","vi":"co lại; thu nhỏ"},{"pos":"v.","en":"To catch or develop a disease.","vi":"mắc bệnh; nhiễm bệnh"}],"examples":[{"en":"Read the contract carefully before you agree to sign it.","vi":"Hãy đọc kỹ hợp đồng trước khi bạn đồng ý ký tên.","audioKind":"ex"},{"en":"A clear employment contract protects both workers and employers by defining responsibilities, working hours and payment terms.","vi":"Một hợp đồng lao động rõ ràng bảo vệ cả người lao động và người sử dụng lao động bằng cách xác định rõ trách nhiệm, thời gian làm việc và điều khoản trả lương.","audioKind":"ex2"}],"collocations":[{"en":"sign a contract","vi":"ký hợp đồng"},{"en":"employment contract","vi":"hợp đồng lao động"},{"en":"breach of contract","vi":"vi phạm hợp đồng"},{"en":"contract a disease","vi":"mắc bệnh"}],"wordFamily":["contractual (adj.)","contraction (n.)","contractor (n.)"],"synonyms":["agreement"],"antonyms":[],"tipVi":"Danh từ có trọng âm ở âm tiết đầu; động từ đọc là /kənˈtrækt/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_joint', 'en-b2-50', 'joint', '/dʒɔɪnt/', 'B2', 'chung; liên hợp; phối hợp; khớp xương; chỗ nối', 'adj.', 'jointly (adv.)', NULL, 'Khi là tính từ, joint mang nghĩa cùng tham gia thực hiện; khi là danh từ, từ này có thể chỉ khớp xương trên cơ thể.', 'Buying the sofa was a joint decision with my flatmate.', NULL, 'Việc mua chiếc ghế sofa là quyết định chung giữa tôi và bạn cùng phòng.', '{"wordId":"joint","ukIpa":"/dʒɔɪnt/","usIpa":"/dʒɔɪnt/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"Shared, owned, or done by two or more people or groups.","vi":"chung; liên hợp; phối hợp"},{"pos":"n.","en":"A place where bones or separate parts meet.","vi":"khớp xương; chỗ nối"}],"examples":[{"en":"Buying the sofa was a joint decision with my flatmate.","vi":"Việc mua chiếc ghế sofa là quyết định chung giữa tôi và bạn cùng phòng.","audioKind":"ex"},{"en":"Joint research projects allow universities to share resources and address environmental problems more effectively.","vi":"Các dự án nghiên cứu chung giúp các trường đại học chia sẻ nguồn lực và giải quyết các vấn đề môi trường một cách hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"joint effort","vi":"nỗ lực chung"},{"en":"joint venture","vi":"doanh nghiệp liên doanh"},{"en":"joint decision","vi":"quyết định chung"},{"en":"joint pain","vi":"đau khớp"}],"wordFamily":["jointly (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi là tính từ, joint mang nghĩa cùng tham gia thực hiện; khi là danh từ, từ này có thể chỉ khớp xương trên cơ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shift', 'en-b2-50', 'shift', '/ʃɪft/', 'B2', 'di chuyển; thay đổi (vị trí, hướng, tiêu điểm); sự chuyển dịch; sự thay đổi; ca làm việc; ca trực', 'v.', NULL, NULL, 'Danh từ shift có thể chỉ sự thay đổi hoặc chỉ ca làm việc trong hệ thống luân phiên.', 'We shifted the sofa closer to the window.', NULL, 'Chúng tôi đã dịch chiếc ghế sofa lại gần cửa sổ hơn.', '{"wordId":"shift","ukIpa":"/ʃɪft/","usIpa":"/ʃɪft/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"To move or change position, direction, or focus.","vi":"di chuyển; thay đổi (vị trí, hướng, tiêu điểm)"},{"pos":"n.","en":"A change in position, direction, or emphasis.","vi":"sự chuyển dịch; sự thay đổi"},{"pos":"n.","en":"A scheduled period of work in a rotating system.","vi":"ca làm việc; ca trực"}],"examples":[{"en":"We shifted the sofa closer to the window.","vi":"Chúng tôi đã dịch chiếc ghế sofa lại gần cửa sổ hơn.","audioKind":"ex"},{"en":"Governments should shift investment towards public transport to reduce traffic congestion and urban air pollution.","vi":"Chính phủ nên chuyển dịch đầu tư sang giao thông công cộng nhằm giảm thiểu tình trạng ùn tắc giao thông và ô nhiễm không khí đô thị.","audioKind":"ex2"}],"collocations":[{"en":"shift the focus","vi":"chuyển dịch trọng tâm"},{"en":"a shift in attitudes","vi":"sự thay đổi trong thái độ"},{"en":"work a night shift","vi":"làm ca đêm"},{"en":"shift responsibility","vi":"đẩy trách nhiệm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ shift có thể chỉ sự thay đổi hoặc chỉ ca làm việc trong hệ thống luân phiên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_50_1', 'en-b2-50', 'Cách dùng “joint” (adj.) — chung; liên hợp; phối hợp', 'joint effort  ·  joint venture  ·  joint decision', 'Khi là tính từ, joint mang nghĩa cùng tham gia thực hiện; khi là danh từ, từ này có thể chỉ khớp xương trên cơ thể.', 'Họ từ (Word Family): jointly (adv.)', '[{"hanzi":"Buying the sofa was a joint decision with my flatmate.","pinyin":"","meaning":"Việc mua chiếc ghế sofa là quyết định chung giữa tôi và bạn cùng phòng."},{"hanzi":"Joint research projects allow universities to share resources and address environmental problems more effectively.","pinyin":"","meaning":"Các dự án nghiên cứu chung giúp các trường đại học chia sẻ nguồn lực và giải quyết các vấn đề môi trường một cách hiệu quả hơn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_50_2', 'en-b2-50', 'Cách dùng “briefing” (n.) — cuộc họp giao ban; buổi phổ biến thông tin, bản hướng dẫn', 'safety briefing  ·  press briefing  ·  attend a briefing', 'Không chỉ là tài liệu tóm tắt dạng văn bản, từ này còn chỉ sự hướng dẫn trực tiếp hoặc buổi họp giao ban.', 'Họ từ (Word Family): brief (v.), debrief (v.), debriefing (n.)', '[{"hanzi":"Our guide gave us a briefing before the hike.","pinyin":"","meaning":"Người hướng dẫn đã phổ biến cho chúng tôi một buổi hướng dẫn trước chuyến đi bộ đường dài."},{"hanzi":"A clear safety briefing helps construction workers understand potential hazards before they begin unfamiliar tasks.","pinyin":"","meaning":"Một buổi phổ biến an toàn rõ ràng giúp công nhân xây dựng hiểu rõ các mối nguy hiểm tiềm ẩn trước khi bắt đầu những công việc chưa quen thuộc."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_50_3', 'en-b2-50', 'Cách dùng “ambitious” (adj.) — có hoài bão; đầy tham vọng', 'ambitious goals  ·  ambitious plan  ·  highly ambitious', 'Khi mô tả con người nghĩa là có hoài bão; khi mô tả kế hoạch thì nhấn mạnh mục tiêu lớn và độ khó cao.', 'Họ từ (Word Family): ambition (n.), ambitiously (adv.) | Đồng nghĩa: aspiring · Trái nghĩa: unambitious', '[{"hanzi":"My ambitious sister hopes to run her own bakery.","pinyin":"","meaning":"Người chị đầy hoài bão của tôi hy vọng sẽ tự điều hành một tiệm bánh của riêng mình."},{"hanzi":"The city has announced an ambitious plan to replace all diesel buses with electric vehicles within a decade.","pinyin":"","meaning":"Thành phố đã công bố một kế hoạch đầy tham vọng nhằm thay thế toàn bộ xe buýt chạy bằng dầu diesel bằng xe điện trong vòng một thập kỷ."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_50_4', 'en-b2-50', 'Cách dùng “internship” (n.) — kỳ thực tập, công việc thực tập', 'paid internship  ·  summer internship  ·  apply for an internship', 'Từ "intern" chỉ người thực tập sinh, còn "internship" chỉ vị trí hoặc khoảng thời gian thực tập.', 'Họ từ (Word Family): intern (n.), intern (v.)', '[{"hanzi":"Leila started a summer internship at a local museum.","pinyin":"","meaning":"Leila bắt đầu kỳ thực tập hè tại một viện bảo tàng địa phương."},{"hanzi":"Paid internships can help students gain professional experience without placing additional financial pressure on their families.","pinyin":"","meaning":"Các chương trình thực tập có lương có thể giúp sinh viên tích lũy kinh nghiệm chuyên môn mà không gây thêm áp lực tài chính cho gia đình."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_50_1', 'en-b2-50', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
