INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_50_1_4', 'ten_b2_50_1', 'ambitious', 'My ambitious sister hopes to run her own bakery.', 'My ambitious sister hopes to run her own bakery.', '/æmˈbɪʃəs/', 'Người chị đầy hoài bão của tôi hy vọng sẽ tự điều hành một tiệm bánh của riêng mình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_50_1_5', 'ten_b2_50_1', 'fulfil', 'She fulfilled her promise and repaired my bicycle.', 'She fulfilled her promise and repaired my bicycle.', '/fʊlˈfɪl/', 'Cô ấy đã giữ đúng lời hứa và sửa chiếc xe đạp cho tôi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_50_1_6', 'ten_b2_50_1', 'specialist', 'My doctor sent me to a skin specialist.', 'My doctor sent me to a skin specialist.', '/ˈspeʃəlɪst/', 'Bác sĩ của tôi đã chuyển tôi đến gặp bác sĩ chuyên khoa da liễu.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_50_1_7', 'ten_b2_50_1', 'invoice', 'The plumber emailed an invoice after fixing our sink.', 'The plumber emailed an invoice after fixing our sink.', '/ˈɪnvɔɪs/', 'Thợ sửa ống nước đã gửi email hóa đơn sau khi sửa bồn rửa của chúng tôi.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_50_1_8', 'ten_b2_50_1', 'mill', 'We watched wheat being ground at the old mill.', 'We watched wheat being ground at the old mill.', '/mɪl/', 'Chúng tôi đã xem người ta xay lúa mì tại cối xay cũ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_50_1_1', 'en-b2-50', 'ten_b2_50_1', 'listening', 'listening', 'We need your expertise to repair this old clock.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy đã giữ đúng lời hứa và sửa chiếc xe đạp cho tôi.","Nghệ sĩ piano trẻ tuổi đã có một buổi biểu diễn xuất sắc vào tối qua.","Nhân viên tiếp tân đã giải thích thủ tục đăng ký làm thành viên phòng gym.","Chúng tôi cần chuyên môn của bạn để sửa chiếc đồng hồ cũ này."]'::jsonb, 3, 'We need your expertise to repair this old clock. → Chúng tôi cần chuyên môn của bạn để sửa chiếc đồng hồ cũ này.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_50_1_2', 'en-b2-50', 'ten_b2_50_1', 'listening', 'listening', 'You can obtain a replacement key from the landlord.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã xem người ta xay lúa mì tại cối xay cũ.","Quản lý của chúng tôi đã gửi một bản ghi nhớ về giờ mở cửa mới.","Công việc này mang lại cho tôi sự linh hoạt để đón con gái.","Bạn có thể lấy một chiếc chìa khóa dự phòng từ chủ nhà."]'::jsonb, 3, 'You can obtain a replacement key from the landlord. → Bạn có thể lấy một chiếc chìa khóa dự phòng từ chủ nhà.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_50_1_3', 'en-b2-50', 'ten_b2_50_1', 'listening', 'listening', 'The young pianist gave an outstanding performance last night.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nghệ sĩ piano trẻ tuổi đã có một buổi biểu diễn xuất sắc vào tối qua.","Chị gái tôi làm việc cho một công ty kỹ thuật nhỏ.","Cô ấy đã giữ đúng lời hứa và sửa chiếc xe đạp cho tôi.","Nhân viên hàng không đã mang cho con gái tôi thêm một chiếc chăn."]'::jsonb, 0, 'The young pianist gave an outstanding performance last night. → Nghệ sĩ piano trẻ tuổi đã có một buổi biểu diễn xuất sắc vào tối qua.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_50_2', 'en-b2-50', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_50_2_1', 'ten_b2_50_2', 'expertise', 'Universities can support local businesses by sharing their expertise in renewable energy and sustainable manufacturing.', 'Universities can support local businesses by sharing their expertise in renewable energy and sustainable manufacturing.', '/ˌekspɜːrˈtiːz/', 'Các trường đại học có thể hỗ trợ các doanh nghiệp địa phương bằng cách chia sẻ chuyên môn của họ trong lĩnh vực năng lượng tái tạo và sản xuất bền vững.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_50_2_2', 'ten_b2_50_2', 'obtain', 'Researchers must obtain informed consent from participants before collecting personal data for a scientific study.', 'Researchers must obtain informed consent from participants before collecting personal data for a scientific study.', '/əbˈteɪn/', 'Các nhà nghiên cứu phải có được sự đồng thuận sau khi đã được cung cấp đầy đủ thông tin từ những người tham gia trước khi thu thập dữ liệu cá nhân cho một nghiên cứu khoa học.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_50_2_3', 'ten_b2_50_2', 'outstanding', 'Universities should recognise outstanding teaching as well as research when deciding which staff members to promote.', 'Universities should recognise outstanding teaching as well as research when deciding which staff members to promote.', '/aʊtˈstændɪŋ/', 'Các trường đại học nên ghi nhận chất lượng giảng dạy xuất sắc bên cạnh công tác nghiên cứu khi quyết định thăng chức cho nhân sự.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_50_2_4', 'ten_b2_50_2', 'ambitious', 'The city has announced an ambitious plan to replace all diesel buses with electric vehicles within a decade.', 'The city has announced an ambitious plan to replace all diesel buses with electric vehicles within a decade.', '/æmˈbɪʃəs/', 'Thành phố đã công bố một kế hoạch đầy tham vọng nhằm thay thế toàn bộ xe buýt chạy bằng dầu diesel bằng xe điện trong vòng một thập kỷ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_50_2_5', 'ten_b2_50_2', 'fulfil', 'Public libraries fulfil an important social role by providing free access to information and learning resources.', 'Public libraries fulfil an important social role by providing free access to information and learning resources.', '/fʊlˈfɪl/', 'Các thư viện công cộng đóng vai trò xã hội quan trọng bằng cách cung cấp quyền truy cập miễn phí vào thông tin và tài nguyên học tập.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_50_2_6', 'ten_b2_50_2', 'specialist', 'Schools should employ a specialist to support children who have difficulties with language development.', 'Schools should employ a specialist to support children who have difficulties with language development.', '/ˈspeʃəlɪst/', 'Các trường học nên thuê một chuyên gia để hỗ trợ trẻ em gặp khó khăn trong việc phát triển ngôn ngữ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_50_2_1', 'en-b2-50', 'ten_b2_50_2', 'listening', 'listening', 'Universities can support local businesses by sharing their expertise in renewable energy and sustainable manufacturing.', NULL, 'Trong câu vừa nghe, từ “expertise” mang nghĩa nào sau đây?', '["quá hạn thanh toán; chậm trả","căng thẳng; căng","kiến thức chuyên môn; kỹ năng chuyên sâu","có hình tam giác"]'::jsonb, 2, '“expertise” (/ˌekspɜːrˈtiːz/): kiến thức chuyên môn; kỹ năng chuyên sâu. Câu đầy đủ: Universities can support local businesses by sharing their expertise in renewable energy and sustainable manufacturing.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_50_2_2', 'en-b2-50', 'ten_b2_50_2', 'listening', 'listening', 'Researchers must obtain informed consent from participants before collecting personal data for a scientific study.', NULL, 'Trong câu vừa nghe, từ “obtain” mang nghĩa nào sau đây?', '["run rẩy; đánh cầm cập","bám chặt; ôm chặt","đạt được; giành được; thu được","rõ rệt; đáng kể; rõ ràng"]'::jsonb, 2, '“obtain” (/əbˈteɪn/): đạt được; giành được; thu được. Câu đầy đủ: Researchers must obtain informed consent from participants before collecting personal data for a scientific study.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
