INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_50_2', 'en-b2-50', NULL, 'comprehensive_test', 'listening', 'You can obtain a replacement key from the landlord.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Người hướng dẫn đã phổ biến cho chúng tôi một buổi hướng dẫn trước chuyến đi bộ đường dài.","Một thợ sửa xe lành nghề đã sửa chiếc xe đạp của tôi chỉ trong vài phút.","Bạn có thể lấy một chiếc chìa khóa dự phòng từ chủ nhà.","Hãy đọc kỹ hợp đồng trước khi bạn đồng ý ký tên."]'::jsonb, 2, 'You can obtain a replacement key from the landlord. → Bạn có thể lấy một chiếc chìa khóa dự phòng từ chủ nhà.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_50_3', 'en-b2-50', NULL, 'comprehensive_test', 'listening', 'outstanding', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["xuất sắc; nổi bật; lỗi lạc","chết đói; thiếu ăn; làm cho chết đói","lăng mạ; xúc phạm","dễ tiếp cận, dễ vào, dễ lấy hoặc dễ sử dụng"]'::jsonb, 0, 'outstanding (/aʊtˈstændɪŋ/) → xuất sắc; nổi bật; lỗi lạc; chưa giải quyết; chưa thanh toán; còn đọng lại', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_50_4', 'en-b2-50', NULL, 'comprehensive_test', 'listening', 'My ambitious sister hopes to run her own bakery.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã tự học các kỹ thuật mộc cơ bản bằng cách tự đóng một chiếc giá sách nhỏ.","Người chị đầy hoài bão của tôi hy vọng sẽ tự điều hành một tiệm bánh của riêng mình.","Người hướng dẫn đã phổ biến cho chúng tôi một buổi hướng dẫn trước chuyến đi bộ đường dài.","Chúng tôi đã tự mình tiến hành sửa chữa để tiết kiệm chi phí."]'::jsonb, 1, 'My ambitious sister hopes to run her own bakery. → Người chị đầy hoài bão của tôi hy vọng sẽ tự điều hành một tiệm bánh của riêng mình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_50_5', 'en-b2-50', NULL, 'comprehensive_test', 'listening', 'fulfil', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["góc nhìn; quan điểm","bạo loạn; cuộc nổi loạn","làm nản lòng; làm bực bội","thực hiện; hoàn thành (nhiệm vụ, lời hứa, thỏa thuận)"]'::jsonb, 3, 'fulfil (/fʊlˈfɪl/) → thực hiện; hoàn thành (nhiệm vụ, lời hứa, thỏa thuận); đáp ứng; thỏa mãn (nhu cầu, yêu cầu); đạt được (điều mong mỏi); phát huy tối đa (năng lực)', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_50_6', 'en-b2-50', NULL, 'comprehensive_test', 'listening', 'My doctor sent me to a skin specialist.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã dịch chiếc ghế sofa lại gần cửa sổ hơn.","Bạn có thể lấy một chiếc chìa khóa dự phòng từ chủ nhà.","Nhân viên tiếp tân đã giải thích thủ tục đăng ký làm thành viên phòng gym.","Bác sĩ của tôi đã chuyển tôi đến gặp bác sĩ chuyên khoa da liễu."]'::jsonb, 3, 'My doctor sent me to a skin specialist. → Bác sĩ của tôi đã chuyển tôi đến gặp bác sĩ chuyên khoa da liễu.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_50_7', 'en-b2-50', NULL, 'comprehensive_test', 'listening', 'invoice', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["hóa đơn; bảng kê tiền hàng","cấp cao; thâm niên","lúng túng; ngượng ngùng; khó xử","men; men nở; nấm men"]'::jsonb, 0, 'invoice (/ˈɪnvɔɪs/) → hóa đơn; bảng kê tiền hàng; lập hóa đơn; gửi hóa đơn', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_50_8', 'en-b2-50', NULL, 'comprehensive_test', 'listening', 'We watched wheat being ground at the old mill.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã tự học các kỹ thuật mộc cơ bản bằng cách tự đóng một chiếc giá sách nhỏ.","Nhân viên tiếp tân đã giải thích thủ tục đăng ký làm thành viên phòng gym.","Chúng tôi đã xem người ta xay lúa mì tại cối xay cũ.","Người chị đầy hoài bão của tôi hy vọng sẽ tự điều hành một tiệm bánh của riêng mình."]'::jsonb, 2, 'We watched wheat being ground at the old mill. → Chúng tôi đã xem người ta xay lúa mì tại cối xay cũ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_50_9', 'en-b2-50', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to do what a duty, promise, or agreement requires”?', '["contract","flexibility","fulfil","firm"]'::jsonb, 2, 'fulfil (/fʊlˈfɪl/) → thực hiện; hoàn thành (nhiệm vụ, lời hứa, thỏa thuận)', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_50_10', 'en-b2-50', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Someone with detailed knowledge or training in a particular field.”?', '["outstanding","specialist","carpentry","chief"]'::jsonb, 1, 'specialist (/ˈspeʃəlɪst/) → chuyên gia; bác sĩ chuyên khoa', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_50_11', 'en-b2-50', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a document listing goods or services and the payment required”?', '["invoice","undertake","joint","memo"]'::jsonb, 0, 'invoice (/ˈɪnvɔɪs/) → hóa đơn; bảng kê tiền hàng', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_50_12', 'en-b2-50', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a building or machine where grain is ground into flour”?', '["outstanding","internship","mill","coordination"]'::jsonb, 2, 'mill (/mɪl/) → cối xay; nhà máy xay xát (lúa mì, ngũ cốc)', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
