INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_50_18', 'en-b2-50', NULL, 'comprehensive_test', 'reading', NULL, 'Universities can support local businesses by sharing their expertise in renewable energy and sustainable manufacturing.', 'Dựa vào câu trên, từ “expertise” có nghĩa phù hợp nhất là gì?', '["tổ tiên; ông cha","kiến thức chuyên môn; kỹ năng chuyên sâu","gạt bỏ; xem nhẹ; không màng tới","chết đói; thiếu ăn; làm cho chết đói"]'::jsonb, 1, 'expertise: kiến thức chuyên môn; kỹ năng chuyên sâu. Dịch cả câu: Các trường đại học có thể hỗ trợ các doanh nghiệp địa phương bằng cách chia sẻ chuyên môn của họ trong lĩnh vực năng lượng tái tạo và sản xuất bền vững.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_50_19', 'en-b2-50', NULL, 'comprehensive_test', 'reading', NULL, 'Researchers must obtain informed consent from participants before collecting personal data for a scientific study.', 'Dựa vào câu trên, từ “obtain” có nghĩa phù hợp nhất là gì?', '["ở trên đầu; trên không","quyền công dân; quốc tịch","đạt được; giành được; thu được","phấp phới, lay động, đu đưa qua lại nhẹ nhàng (thường là trong gió)"]'::jsonb, 2, 'obtain: đạt được; giành được; thu được. Dịch cả câu: Các nhà nghiên cứu phải có được sự đồng thuận sau khi đã được cung cấp đầy đủ thông tin từ những người tham gia trước khi thu thập dữ liệu cá nhân cho một nghiên cứu khoa học.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_50_20', 'en-b2-50', NULL, 'comprehensive_test', 'reading', NULL, 'Universities should recognise outstanding teaching as well as research when deciding which staff members to promote.', 'Dựa vào câu trên, từ “outstanding” có nghĩa phù hợp nhất là gì?', '["xuất sắc; nổi bật; lỗi lạc","sự căng thẳng (quan hệ); tình hình căng thẳng","độ sáng; sự rực rỡ","cuộc nổi dậy; cuộc khởi nghĩa"]'::jsonb, 0, 'outstanding: xuất sắc; nổi bật; lỗi lạc; chưa giải quyết; chưa thanh toán; còn đọng lại. Dịch cả câu: Các trường đại học nên ghi nhận chất lượng giảng dạy xuất sắc bên cạnh công tác nghiên cứu khi quyết định thăng chức cho nhân sự.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_50_21', 'en-b2-50', NULL, 'comprehensive_test', 'reading', NULL, 'The city has announced an ambitious plan to replace all diesel buses with electric vehicles within a decade.', 'Dựa vào câu trên, từ “ambitious” có nghĩa phù hợp nhất là gì?', '["tương ứng, có liên quan trực tiếp với cái khác","vitamin","cái bẫy; dụng cụ bắt bẫy","có hoài bão; đầy tham vọng"]'::jsonb, 3, 'ambitious: có hoài bão; đầy tham vọng; quy mô lớn; đòi hỏi nhiều nỗ lực hoặc nguồn lực để thành công. Dịch cả câu: Thành phố đã công bố một kế hoạch đầy tham vọng nhằm thay thế toàn bộ xe buýt chạy bằng dầu diesel bằng xe điện trong vòng một thập kỷ.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
