INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-51', 'en', 'Bài 51: Công việc & Nghề nghiệp (6) - CEFR B2', 'CEFR B2', 'B2 · Công việc', '24 từ vựng Tiếng Anh CEFR B2 chủ đề công việc & nghề nghiệp kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4051, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_consultant', 'en-b2-51', 'consultant', '/kənˈsʌltənt/', 'B2', 'cố vấn; chuyên gia tư vấn; bác sĩ chuyên khoa cao cấp', 'n.', 'consult (v.), consultation (n.), consultancy (n.), consultative (adj.)', 'Đồng nghĩa: adviser', 'Trong bối cảnh y tế, consultant ở Anh chỉ bác sĩ chuyên khoa cao cấp.', 'We hired a consultant to help improve our small business.', NULL, 'Chúng tôi đã thuê một chuyên gia tư vấn để giúp cải thiện doanh nghiệp nhỏ của mình.', '{"wordId":"consultant","ukIpa":"/kənˈsʌltənt/","usIpa":"/kənˈsʌltənt/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"An expert paid to provide specialist advice.","vi":"cố vấn; chuyên gia tư vấn"},{"pos":"n.","en":"A senior hospital doctor specialising in a particular medical field.","vi":"bác sĩ chuyên khoa cao cấp"}],"examples":[{"en":"We hired a consultant to help improve our small business.","vi":"Chúng tôi đã thuê một chuyên gia tư vấn để giúp cải thiện doanh nghiệp nhỏ của mình.","audioKind":"ex"},{"en":"An environmental consultant can help companies reduce waste while ensuring that their operations comply with national regulations.","vi":"Một chuyên gia tư vấn môi trường có thể giúp các doanh nghiệp giảm thiểu rác thải đồng thời đảm bảo hoạt động của họ tuân thủ các quy định quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"a management consultant","vi":"chuyên gia tư vấn quản lý"},{"en":"an environmental consultant","vi":"chuyên gia tư vấn môi trường"},{"en":"hire a consultant","vi":"thuê cố vấn"},{"en":"a consultant surgeon","vi":"bác sĩ phẫu thuật chuyên khoa"}],"wordFamily":["consult (v.)","consultation (n.)","consultancy (n.)","consultative (adj.)"],"synonyms":["adviser"],"antonyms":[],"tipVi":"Trong bối cảnh y tế, consultant ở Anh chỉ bác sĩ chuyên khoa cao cấp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_extend', 'en-b2-51', 'extend', '/ɪkˈstend/', 'B2', 'kéo dài; mở rộng quy mô, phạm vi; giơ ra; duỗi ra (tay, chân hoặc bộ phận cơ thể); dành cho; bày tỏ (sự giúp đỡ, lời mời, sự chào đón)', 'v.', 'extension (n.), extensive (adj.), extensively (adv.), extendable (adj.)', 'Đồng nghĩa: lengthen, expand · Trái nghĩa: shorten, reduce', 'extend by đi với lượng tăng thêm; extend to đi với điểm kết thúc hoặc thời hạn mới.', 'We extended our holiday because the weather was so lovely.', NULL, 'Chúng tôi đã kéo dài kỳ nghỉ của mình vì thời tiết quá ư là tuyệt vời.', '{"wordId":"extend","ukIpa":"/ɪkˈstend/","usIpa":"/ɪkˈstend/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"To make something longer, larger, or wider in scope","vi":"kéo dài; mở rộng quy mô, phạm vi"},{"pos":"v.","en":"To stretch out a hand, arm, or other body part","vi":"giơ ra; duỗi ra (tay, chân hoặc bộ phận cơ thể)"},{"pos":"v.","en":"To offer someone help, an invitation, or a welcome","vi":"dành cho; bày tỏ (sự giúp đỡ, lời mời, sự chào đón)"}],"examples":[{"en":"We extended our holiday because the weather was so lovely.","vi":"Chúng tôi đã kéo dài kỳ nghỉ của mình vì thời tiết quá ư là tuyệt vời.","audioKind":"ex"},{"en":"Governments should extend public transport networks to ensure that residents of outer suburbs can access employment opportunities.","vi":"Chính phủ nên mở rộng mạng lưới giao thông công cộng để đảm bảo cư dân ở các vùng ngoại ô xa xôi có thể tiếp cận cơ hội việc làm.","audioKind":"ex2"}],"collocations":[{"en":"extend a deadline","vi":"gia hạn thời hạn"},{"en":"extend a network","vi":"mở rộng mạng lưới"},{"en":"extend your hand","vi":"giơ tay ra"},{"en":"extend a warm welcome","vi":"gửi lời chào nồng nhiệt"}],"wordFamily":["extension (n.)","extensive (adj.)","extensively (adv.)","extendable (adj.)"],"synonyms":["lengthen","expand"],"antonyms":["shorten","reduce"],"tipVi":"extend by đi với lượng tăng thêm; extend to đi với điểm kết thúc hoặc thời hạn mới.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bookkeeper', 'en-b2-51', 'bookkeeper', '/ˈbʊkkiːpər/', 'B2', 'người giữ sổ sách kế toán; nhân viên ghi sổ', 'n.', 'bookkeeping (n.)', NULL, 'Chủ yếu chịu trách nhiệm ghi chép sổ sách hàng ngày; phạm vi công việc của accountant (kế toán viên) thường rộng hơn.', 'Our bookkeeper checks the receipts every Friday afternoon.', NULL, 'Nhân viên ghi sổ của chúng tôi kiểm tra các biên lai vào mỗi chiều thứ Sáu.', '{"wordId":"bookkeeper","ukIpa":"/ˈbʊkkiːpə/","usIpa":"/ˈbʊkkiːpər/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"Someone whose job is recording a business''s financial transactions.","vi":"người giữ sổ sách kế toán; nhân viên ghi sổ"}],"examples":[{"en":"Our bookkeeper checks the receipts every Friday afternoon.","vi":"Nhân viên ghi sổ của chúng tôi kiểm tra các biên lai vào mỗi chiều thứ Sáu.","audioKind":"ex"},{"en":"Small businesses often employ a bookkeeper to maintain accurate financial records and track daily expenses.","vi":"Các doanh nghiệp nhỏ thường thuê nhân viên ghi sổ để duy trì hồ sơ tài chính chính xác và theo dõi chi phí hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"employ a bookkeeper","vi":"thuê nhân viên ghi sổ"},{"en":"part-time bookkeeper","vi":"nhân viên ghi sổ bán thời gian"},{"en":"experienced bookkeeper","vi":"nhân viên ghi sổ có kinh nghiệm"}],"wordFamily":["bookkeeping (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chủ yếu chịu trách nhiệm ghi chép sổ sách hàng ngày; phạm vi công việc của accountant (kế toán viên) thường rộng hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_assist', 'en-b2-51', 'assist', '/əˈsɪst/', 'B2', 'giúp đỡ; hỗ trợ', 'v.', 'assistance (n.), assistant (n.)', 'Đồng nghĩa: help, aid · Trái nghĩa: hinder', 'Trang trọng hơn help; thường dùng cấu trúc assist someone with something.', 'A friendly librarian assisted me with the printer.', NULL, 'Một nhân viên thư viện thân thiện đã hỗ trợ tôi dùng máy in.', '{"wordId":"assist","ukIpa":"/əˈsɪst/","usIpa":"/əˈsɪst/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"To help someone do something.","vi":"giúp đỡ; hỗ trợ"}],"examples":[{"en":"A friendly librarian assisted me with the printer.","vi":"Một nhân viên thư viện thân thiện đã hỗ trợ tôi dùng máy in.","audioKind":"ex"},{"en":"Local volunteers can assist older residents with online services, making essential information more accessible.","vi":"Các tình nguyện viên địa phương có thể giúp đỡ cư dân lớn tuổi sử dụng các dịch vụ trực tuyến, giúp họ tiếp cận thông tin thiết yếu dễ dàng hơn.","audioKind":"ex2"}],"collocations":[{"en":"assist someone with something","vi":"giúp ai đó làm việc gì"},{"en":"assist in doing something","vi":"hỗ trợ làm việc gì"},{"en":"assist someone to do something","vi":"giúp ai đó làm gì"}],"wordFamily":["assistance (n.)","assistant (n.)"],"synonyms":["help","aid"],"antonyms":["hinder"],"tipVi":"Trang trọng hơn help; thường dùng cấu trúc assist someone with something.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deadline', 'en-b2-51', 'deadline', '/ˈdedlaɪn/', 'B2', 'hạn chót; thời hạn cuối cùng', 'n.', NULL, 'Đồng nghĩa: time limit', 'Dùng meet a deadline để chỉ việc hoàn thành đúng hạn, không dùng catch.', 'I stayed up late to meet the application deadline.', NULL, 'Tôi đã thức khuya để kịp hoàn thành hạn nộp hồ sơ.', '{"wordId":"deadline","ukIpa":"/ˈdedlaɪn/","usIpa":"/ˈdedlaɪn/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"The latest time by which something must be completed","vi":"hạn chót; thời hạn cuối cùng"}],"examples":[{"en":"I stayed up late to meet the application deadline.","vi":"Tôi đã thức khuya để kịp hoàn thành hạn nộp hồ sơ.","audioKind":"ex"},{"en":"Setting a realistic deadline allows researchers to maintain quality without delaying the publication of important findings.","vi":"Việc ấn định một thời hạn thực tế giúp các nhà nghiên cứu duy trì chất lượng mà không làm chậm trễ việc công bố các phát hiện quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"meet a deadline","vi":"hoàn thành đúng hạn"},{"en":"miss a deadline","vi":"trễ hạn"},{"en":"extend a deadline","vi":"gia hạn chót"},{"en":"a tight deadline","vi":"thời hạn gấp gáp"}],"wordFamily":[],"synonyms":["time limit"],"antonyms":[],"tipVi":"Dùng meet a deadline để chỉ việc hoàn thành đúng hạn, không dùng catch.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_corporate', 'en-b2-51', 'corporate', '/ˈkɔːrpərət/', 'B2', 'thuộc về công ty; thuộc về doanh nghiệp; chung của tập thể; đoàn thể', 'adj.', 'corporation (n.)', NULL, 'Corporate chỉ các vấn đề công ty; cooperative chỉ tính chất hợp tác.', 'My sister handles corporate travel for a small company.', NULL, 'Chị gái tôi phụ trách việc đi lại công tác cho một công ty nhỏ.', '{"wordId":"corporate","ukIpa":"/ˈkɔːpərət/","usIpa":"/ˈkɔːrpərət/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"Relating to a company or businesses in general.","vi":"thuộc về công ty; thuộc về doanh nghiệp"},{"pos":"adj.","en":"Shared by a group acting together as one body.","vi":"chung của tập thể; đoàn thể"}],"examples":[{"en":"My sister handles corporate travel for a small company.","vi":"Chị gái tôi phụ trách việc đi lại công tác cho một công ty nhỏ.","audioKind":"ex"},{"en":"Greater corporate transparency allows consumers to assess whether businesses genuinely meet their environmental and social commitments.","vi":"Sự minh bạch doanh nghiệp cao hơn cho phép người tiêu dùng đánh giá xem các doanh nghiệp có thực sự thực hiện các cam kết về môi trường và xã hội của họ hay không.","audioKind":"ex2"}],"collocations":[{"en":"corporate culture","vi":"văn hóa doanh nghiệp"},{"en":"corporate responsibility","vi":"trách nhiệm doanh nghiệp"},{"en":"corporate profits","vi":"lợi nhuận doanh nghiệp"},{"en":"corporate identity","vi":"hình ảnh doanh nghiệp"}],"wordFamily":["corporation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Corporate chỉ các vấn đề công ty; cooperative chỉ tính chất hợp tác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_supplier', 'en-b2-51', 'supplier', '/səˈplaɪər/', 'B2', 'nhà cung cấp; bên cung ứng', 'n.', 'supply (v.), supply (n.)', 'Đồng nghĩa: provider', 'supplier of đi kèm với mặt hàng được cung cấp; supply là dạng động từ của từ này.', 'Our bakery gets fresh flour from a local supplier.', NULL, 'Tiệm bánh của chúng tôi lấy bột mì tươi từ một nhà cung cấp địa phương.', '{"wordId":"supplier","ukIpa":"/səˈplaɪə/","usIpa":"/səˈplaɪər/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"a person or company that provides goods or services","vi":"nhà cung cấp; bên cung ứng"}],"examples":[{"en":"Our bakery gets fresh flour from a local supplier.","vi":"Tiệm bánh của chúng tôi lấy bột mì tươi từ một nhà cung cấp địa phương.","audioKind":"ex"},{"en":"Businesses should assess each supplier carefully to ensure that materials are produced under fair working conditions.","vi":"Các doanh nghiệp nên đánh giá cẩn thận từng nhà cung cấp để đảm bảo nguyên liệu được sản xuất trong các điều kiện lao động công bằng.","audioKind":"ex2"}],"collocations":[{"en":"local supplier","vi":"nhà cung cấp địa phương"},{"en":"reliable supplier","vi":"nhà cung cấp đáng tin cậy"},{"en":"energy supplier","vi":"nhà cung cấp năng lượng"},{"en":"major supplier","vi":"nhà cung cấp lớn"}],"wordFamily":["supply (v.)","supply (n.)"],"synonyms":["provider"],"antonyms":[],"tipVi":"supplier of đi kèm với mặt hàng được cung cấp; supply là dạng động từ của từ này.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_regarding', 'en-b2-51', 'regarding', '/rɪˈɡɑːrdɪŋ/', 'B2', 'về; liên quan đến', 'prep.', 'regard (v.), regard (n.)', 'Đồng nghĩa: concerning, about', 'regarding đi trực tiếp với danh từ, không thêm to; mang tính trang trọng hơn about.', 'I called the hotel regarding our missing suitcase.', NULL, 'Tôi đã gọi điện cho khách sạn để hỏi về chiếc vali bị mất của chúng tôi.', '{"wordId":"regarding","ukIpa":"/rɪˈɡɑːdɪŋ/","usIpa":"/rɪˈɡɑːrdɪŋ/","cefr":"B2","topic":"work","senses":[{"pos":"prep.","en":"On the subject of someone or something.","vi":"về; liên quan đến"}],"examples":[{"en":"I called the hotel regarding our missing suitcase.","vi":"Tôi đã gọi điện cho khách sạn để hỏi về chiếc vali bị mất của chúng tôi.","audioKind":"ex"},{"en":"Schools should consult parents before making major decisions regarding changes to the curriculum or assessment methods.","vi":"Các trường học nên tham khảo ý kiến phụ huynh trước khi đưa ra các quyết định lớn liên quan đến việc thay đổi chương trình giảng dạy hoặc phương pháp đánh giá.","audioKind":"ex2"}],"collocations":[{"en":"information regarding","vi":"thông tin về"},{"en":"questions regarding","vi":"các câu hỏi liên quan đến"},{"en":"concerns regarding","vi":"những lo ngại về"}],"wordFamily":["regard (v.)","regard (n.)"],"synonyms":["concerning","about"],"antonyms":[],"tipVi":"regarding đi trực tiếp với danh từ, không thêm to; mang tính trang trọng hơn about.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vacancy', 'en-b2-51', 'vacancy', '/ˈveɪkənsi/', 'B2', 'chỗ trống việc làm; vị trí tuyển dụng; phòng trống; phòng khách sạn còn trống', 'n.', 'vacant (adj.), vacate (v.)', 'Đồng nghĩa: opening', 'Cả vị trí tuyển dụng và phòng trống đều là danh từ đếm được; dạng số nhiều là vacancies.', 'The local library has a vacancy for an assistant.', NULL, 'Thư viện địa phương hiện đang có một vị trí trợ lý còn trống.', '{"wordId":"vacancy","ukIpa":"/ˈveɪkənsi/","usIpa":"/ˈveɪkənsi/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"A job or position available for someone to fill.","vi":"chỗ trống việc làm; vị trí tuyển dụng"},{"pos":"n.","en":"A room available for someone to stay in.","vi":"phòng trống; phòng khách sạn còn trống"}],"examples":[{"en":"The local library has a vacancy for an assistant.","vi":"Thư viện địa phương hiện đang có một vị trí trợ lý còn trống.","audioKind":"ex"},{"en":"Despite rising unemployment, many employers report difficulty filling vacancies that require advanced technical skills.","vi":"Bất chấp tỷ lệ thất nghiệp tăng cao, nhiều nhà tuyển dụng vẫn cho biết họ gặp khó khăn trong việc tuyển điền vào các vị trí đòi hỏi kỹ năng kỹ thuật cao.","audioKind":"ex2"}],"collocations":[{"en":"job vacancy","vi":"vị trí việc làm trống"},{"en":"fill a vacancy","vi":"lấp đầy chỗ trống"},{"en":"a vacancy for","vi":"vị trí trống cho"},{"en":"no vacancies","vi":"hết phòng trống"}],"wordFamily":["vacant (adj.)","vacate (v.)"],"synonyms":["opening"],"antonyms":[],"tipVi":"Cả vị trí tuyển dụng và phòng trống đều là danh từ đếm được; dạng số nhiều là vacancies.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_time-consuming', 'en-b2-51', 'time-consuming', '/ˈtaɪm kənˌsuːmɪŋ/', 'B2', 'tốn thời gian; mất nhiều thời gian', 'adj.', 'consume (v.), consumption (n.)', 'Đồng nghĩa: lengthy · Trái nghĩa: time-saving', 'Nhấn mạnh việc tiêu tốn nhiều thời gian, không nhất thiết mang nghĩa là lãng phí thời gian.', 'Sorting all these old photos is surprisingly time-consuming.', NULL, 'Việc phân loại tất cả những bức ảnh cũ này thực sự tốn rất nhiều thời gian.', '{"wordId":"time-consuming","ukIpa":"/ˈtaɪm kənˌsjuːmɪŋ/","usIpa":"/ˈtaɪm kənˌsuːmɪŋ/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"taking a lot of time to do or complete","vi":"tốn thời gian; mất nhiều thời gian"}],"examples":[{"en":"Sorting all these old photos is surprisingly time-consuming.","vi":"Việc phân loại tất cả những bức ảnh cũ này thực sự tốn rất nhiều thời gian.","audioKind":"ex"},{"en":"Applying for multiple permits can be time-consuming, discouraging small businesses from expanding their operations.","vi":"Việc xin nhiều loại giấy phép có thể rất tốn thời gian, khiến các doanh nghiệp nhỏ nhụt chí trong việc mở rộng hoạt động kinh doanh.","audioKind":"ex2"}],"collocations":[{"en":"time-consuming task","vi":"nhiệm vụ tốn thời gian"},{"en":"time-consuming process","vi":"quá trình tốn thời gian"},{"en":"costly and time-consuming","vi":"vừa tốn kém vừa mất thời gian"}],"wordFamily":["consume (v.)","consumption (n.)"],"synonyms":["lengthy"],"antonyms":["time-saving"],"tipVi":"Nhấn mạnh việc tiêu tốn nhiều thời gian, không nhất thiết mang nghĩa là lãng phí thời gian.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_workaholic', 'en-b2-51', 'workaholic', '/ˌwɝːkəˈhɑːlɪk/', 'B2', 'người nghiện công việc; người cuồng công việc', 'n.', 'workaholism (n.), work (v.), worker (n.)', NULL, 'Nhấn mạnh làm việc quá mức, khó dừng lại, không đồng nghĩa với sự chăm chỉ thông thường.', 'My brother is a workaholic who rarely takes holidays.', NULL, 'Anh trai tôi là một kẻ cuồng công việc, hiếm khi chịu nghỉ phép.', '{"wordId":"workaholic","ukIpa":"/ˌwɜːkəˈhɒlɪk/","usIpa":"/ˌwɝːkəˈhɑːlɪk/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"Someone who works excessively and finds it hard to stop","vi":"người nghiện công việc; người cuồng công việc"}],"examples":[{"en":"My brother is a workaholic who rarely takes holidays.","vi":"Anh trai tôi là một kẻ cuồng công việc, hiếm khi chịu nghỉ phép.","audioKind":"ex"},{"en":"A workaholic may achieve short-term career success while neglecting personal relationships and long-term health.","vi":"Một người nghiện công việc có thể đạt được thành công sự nghiệp trong ngắn hạn nhưng lại bỏ bê các mối quan hệ cá nhân và sức khỏe lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"a self-confessed workaholic","vi":"một người tự nhận là cuồng công việc"},{"en":"become a workaholic","vi":"trở thành kẻ cuồng công việc"},{"en":"a workaholic culture","vi":"văn hóa làm việc quá sức"}],"wordFamily":["workaholism (n.)","work (v.)","worker (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nhấn mạnh làm việc quá mức, khó dừng lại, không đồng nghĩa với sự chăm chỉ thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_decorator', 'en-b2-51', 'decorator', '/ˈdekəreɪtər/', 'B2', 'thợ sơn; thợ trang trí nội thất', 'n.', 'decorate (v.), decoration (n.), decorative (adj.)', NULL, 'Trong tiếng Anh-Anh, từ này thường chỉ thợ sơn tường và dán giấy dán tường, không chỉ đơn thuần là nhà thiết kế.', 'The decorator covered our sofa before painting the ceiling.', NULL, 'Thợ trang trí đã phủ kín chiếc sofa của chúng tôi trước khi sơn trần nhà.', '{"wordId":"decorator","ukIpa":"/ˈdekəreɪtə/","usIpa":"/ˈdekəreɪtər/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"Someone whose job is painting, wallpapering, or decorating rooms.","vi":"thợ sơn; thợ trang trí nội thất"}],"examples":[{"en":"The decorator covered our sofa before painting the ceiling.","vi":"Thợ trang trí đã phủ kín chiếc sofa của chúng tôi trước khi sơn trần nhà.","audioKind":"ex"},{"en":"Employing a professional decorator can help homeowners improve their living space without undertaking major structural changes.","vi":"Thuê một thợ trang trí chuyên nghiệp có thể giúp các gia chủ cải thiện không gian sống mà không cần phải thực hiện những thay đổi lớn về cấu trúc.","audioKind":"ex2"}],"collocations":[{"en":"painter and decorator","vi":"thợ sơn và trang trí nội thất"},{"en":"interior decorator","vi":"chuyên gia trang trí nội thất"},{"en":"hire a decorator","vi":"thuê thợ trang trí"}],"wordFamily":["decorate (v.)","decoration (n.)","decorative (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh, từ này thường chỉ thợ sơn tường và dán giấy dán tường, không chỉ đơn thuần là nhà thiết kế.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_collaboration', 'en-b2-51', 'collaboration', '/kəˌlæbəˈreɪʃən/', 'B2', 'sự cộng tác; sự hợp tác; sự thông địch; sự hợp tác với kẻ thù', 'n.', 'collaborate (v.), collaborative (adj.), collaboratively (adv.), collaborator (n.)', 'Đồng nghĩa: cooperation, teamwork', 'Trong ngữ cảnh thông thường dùng để chỉ sự hợp tác; nghĩa thông địch cần phải gắn liền với bối cảnh chiến tranh.', 'Our garden makeover was a collaboration between several neighbours.', NULL, 'Việc cải tạo khu vườn của chúng tôi là thành quả hợp tác giữa một số gia đình hàng xóm.', '{"wordId":"collaboration","ukIpa":"/kəˌlæbəˈreɪʃən/","usIpa":"/kəˌlæbəˈreɪʃən/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"Working together with others to achieve a shared goal","vi":"sự cộng tác; sự hợp tác"},{"pos":"n.","en":"Helping an enemy that controls your country","vi":"sự thông địch; sự hợp tác với kẻ thù"}],"examples":[{"en":"Our garden makeover was a collaboration between several neighbours.","vi":"Việc cải tạo khu vườn của chúng tôi là thành quả hợp tác giữa một số gia đình hàng xóm.","audioKind":"ex"},{"en":"Closer collaboration between universities and local businesses can help students develop practical skills before entering the workforce.","vi":"Sự hợp tác chặt chẽ hơn giữa các trường đại học và doanh nghiệp địa phương có thể giúp sinh viên phát triển các kỹ năng thực tế trước khi gia nhập thị trường lao động.","audioKind":"ex2"}],"collocations":[{"en":"in collaboration with","vi":"hợp tác với"},{"en":"close collaboration","vi":"sự hợp tác chặt chẽ"},{"en":"international collaboration","vi":"hợp tác quốc tế"},{"en":"collaboration between","vi":"sự hợp tác giữa"}],"wordFamily":["collaborate (v.)","collaborative (adj.)","collaboratively (adv.)","collaborator (n.)"],"synonyms":["cooperation","teamwork"],"antonyms":[],"tipVi":"Trong ngữ cảnh thông thường dùng để chỉ sự hợp tác; nghĩa thông địch cần phải gắn liền với bối cảnh chiến tranh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_laborer', 'en-b2-51', 'laborer', '/ˈleɪbərər/', 'B2', 'người lao động chân tay; công nhân lao động', 'n.', 'labor (n.), labor (v.), laborious (adj.)', 'Đồng nghĩa: manual worker', 'Cách viết theo tiếng Mỹ; tiếng Anh-Anh là labourer, nhấn mạnh lao động chân tay.', 'A laborer carried heavy bricks across the building site.', NULL, 'Một công nhân lao động đang khiêng những viên gạch nặng băng qua công trường xây dựng.', '{"wordId":"laborer","ukIpa":"/ˈleɪbərə/","usIpa":"/ˈleɪbərər/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"Someone whose job involves hard physical work.","vi":"người lao động chân tay; công nhân lao động"}],"examples":[{"en":"A laborer carried heavy bricks across the building site.","vi":"Một công nhân lao động đang khiêng những viên gạch nặng băng qua công trường xây dựng.","audioKind":"ex"},{"en":"Every construction laborer should receive safety training and suitable protective equipment before starting work on site.","vi":"Mỗi công nhân xây dựng nên nhận được đào tạo an toàn và trang thiết bị bảo hộ phù hợp trước khi bắt đầu công việc tại công trường.","audioKind":"ex2"}],"collocations":[{"en":"manual laborer","vi":"người lao động chân tay"},{"en":"construction laborer","vi":"công nhân xây dựng"},{"en":"farm laborer","vi":"công nhân nông trại"},{"en":"unskilled laborer","vi":"lao động phổ thông"}],"wordFamily":["labor (n.)","labor (v.)","laborious (adj.)"],"synonyms":["manual worker"],"antonyms":[],"tipVi":"Cách viết theo tiếng Mỹ; tiếng Anh-Anh là labourer, nhấn mạnh lao động chân tay.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unpaid', 'en-b2-51', 'unpaid', '/ʌnˈpeɪd/', 'B2', 'không trả lương; làm không công; tình nguyện; chưa thanh toán; chưa trả tiền', 'adj.', 'pay (v.), paid (adj.), payment (n.)', 'Trái nghĩa: paid', 'Unpaid work chỉ công việc tình nguyện không tiền công; unpaid bills chỉ hóa đơn chưa thanh toán.', 'She does unpaid work at the animal shelter every Saturday.', NULL, 'Cô ấy làm việc không công tại trung tâm bảo vệ động vật vào mỗi thứ Bảy.', '{"wordId":"unpaid","ukIpa":"/ʌnˈpeɪd/","usIpa":"/ʌnˈpeɪd/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"Done or working without receiving money.","vi":"không trả lương; làm không công; tình nguyện"},{"pos":"adj.","en":"Not yet paid or settled.","vi":"chưa thanh toán; chưa trả tiền"}],"examples":[{"en":"She does unpaid work at the animal shelter every Saturday.","vi":"Cô ấy làm việc không công tại trung tâm bảo vệ động vật vào mỗi thứ Bảy.","audioKind":"ex"},{"en":"Unpaid internships can disadvantage students who cannot afford to work without a regular income.","vi":"Các kỳ thực tập không lương có thể gây bất lợi cho những sinh viên không có khả năng đi làm mà không có thu nhập cố định.","audioKind":"ex2"}],"collocations":[{"en":"unpaid work","vi":"công việc không lương"},{"en":"unpaid leave","vi":"nghỉ không lương"},{"en":"unpaid bills","vi":"hóa đơn chưa thanh toán"},{"en":"unpaid internship","vi":"thực tập không lương"}],"wordFamily":["pay (v.)","paid (adj.)","payment (n.)"],"synonyms":[],"antonyms":["paid"],"tipVi":"Unpaid work chỉ công việc tình nguyện không tiền công; unpaid bills chỉ hóa đơn chưa thanh toán.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_applicant', 'en-b2-51', 'applicant', '/ˈæplɪkənt/', 'B2', 'người ứng tuyển; thí sinh; người nộp đơn', 'n.', 'apply (v.), application (n.)', 'Đồng nghĩa: candidate', 'Người ứng tuyển cho một vị trí công việc cụ thể dùng applicant for a position.', 'Each applicant waited outside the office for an interview.', NULL, 'Mỗi ứng viên đều đứng đợi bên ngoài văn phòng để phỏng vấn.', '{"wordId":"applicant","ukIpa":"/ˈæplɪkənt/","usIpa":"/ˈæplɪkənt/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"Someone who formally requests a job, place, or permission.","vi":"người ứng tuyển; thí sinh; người nộp đơn"}],"examples":[{"en":"Each applicant waited outside the office for an interview.","vi":"Mỗi ứng viên đều đứng đợi bên ngoài văn phòng để phỏng vấn.","audioKind":"ex"},{"en":"Universities should assess each applicant fairly, considering both academic achievement and relevant personal experience.","vi":"Các trường đại học nên đánh giá từng ứng viên một cách công bằng, cân nhắc cả thành tích học tập lẫn kinh nghiệm cá nhân liên quan.","audioKind":"ex2"}],"collocations":[{"en":"job applicant","vi":"người tìm việc"},{"en":"successful applicant","vi":"ứng viên trúng tuyển"},{"en":"applicant for a position","vi":"người ứng tuyển cho một vị trí"}],"wordFamily":["apply (v.)","application (n.)"],"synonyms":["candidate"],"antonyms":[],"tipVi":"Người ứng tuyển cho một vị trí công việc cụ thể dùng applicant for a position.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_productive', 'en-b2-51', 'productive', '/prəˈdʌktɪv/', 'B2', 'năng suất; hiệu quả; mang lại kết quả tốt; năng suất cao; sản lượng lớn', 'adj.', 'produce (v.), production (n.), productivity (n.), productively (adv.)', 'Đồng nghĩa: fruitful · Trái nghĩa: unproductive', 'Dùng để miêu tả công việc hoặc cuộc họp có kết quả tốt; danh từ chỉ năng suất hoặc sản lượng là productivity.', 'I had a productive morning and finished my report.', NULL, 'Tôi có một buổi sáng làm việc hiệu quả và đã hoàn thành bản báo cáo.', '{"wordId":"productive","ukIpa":"/prəˈdʌktɪv/","usIpa":"/prəˈdʌktɪv/","cefr":"B2","topic":"work","senses":[{"pos":"adj.","en":"achieving a lot or producing useful results","vi":"năng suất; hiệu quả; mang lại kết quả tốt"},{"pos":"adj.","en":"producing large amounts of crops, goods, or other outputs","vi":"năng suất cao; sản lượng lớn"}],"examples":[{"en":"I had a productive morning and finished my report.","vi":"Tôi có một buổi sáng làm việc hiệu quả và đã hoàn thành bản báo cáo.","audioKind":"ex"},{"en":"Flexible working arrangements can help employees remain productive while balancing professional responsibilities with family commitments.","vi":"Các thỏa thuận làm việc linh hoạt có thể giúp nhân viên duy trì năng suất trong khi vẫn cân bằng được trách nhiệm nghề nghiệp và gia đình.","audioKind":"ex2"}],"collocations":[{"en":"a productive discussion","vi":"một buổi thảo luận hiệu quả"},{"en":"a productive day","vi":"một ngày làm việc năng suất"},{"en":"productive farmland","vi":"đất nông nghiệp màu mỡ"}],"wordFamily":["produce (v.)","production (n.)","productivity (n.)","productively (adv.)"],"synonyms":["fruitful"],"antonyms":["unproductive"],"tipVi":"Dùng để miêu tả công việc hoặc cuộc họp có kết quả tốt; danh từ chỉ năng suất hoặc sản lượng là productivity.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_launch', 'en-b2-51', 'launch', '/lɔːntʃ/', 'B2', 'ra mắt; giới thiệu (sản phẩm); khởi xướng; phát động; phóng (vũ trụ); hạ thủy (tàu thuyền); sự ra mắt; sự phát động; sự phóng', 'v.', 'relaunch (v.), launcher (n.)', NULL, 'Việc ra mắt sản phẩm, phát động chiến dịch và phóng vệ tinh đều dùng từ launch.', 'Our local bakery launched a new delivery service yesterday.', NULL, 'Tiệm bánh địa phương của chúng tôi đã ra mắt dịch vụ giao hàng mới vào ngày hôm qua.', '{"wordId":"launch","ukIpa":"/lɔːntʃ/","usIpa":"/lɔːntʃ/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"To introduce a product or start an organised activity.","vi":"ra mắt; giới thiệu (sản phẩm); khởi xướng; phát động"},{"pos":"v.","en":"To send something into space or put a boat into water.","vi":"phóng (vũ trụ); hạ thủy (tàu thuyền)"},{"pos":"n.","en":"The act of introducing something or sending it into motion.","vi":"sự ra mắt; sự phát động; sự phóng"}],"examples":[{"en":"Our local bakery launched a new delivery service yesterday.","vi":"Tiệm bánh địa phương của chúng tôi đã ra mắt dịch vụ giao hàng mới vào ngày hôm qua.","audioKind":"ex"},{"en":"Schools should launch awareness campaigns to encourage healthier eating habits and reduce food waste among students.","vi":"Các trường học nên phát động các chiến dịch nâng cao nhận thức để khuyến khích thói quen ăn uống lành mạnh hơn và giảm lãng phí thực phẩm ở học sinh.","audioKind":"ex2"}],"collocations":[{"en":"launch a campaign","vi":"phát động một chiến dịch"},{"en":"launch a product","vi":"ra mắt sản phẩm"},{"en":"launch a satellite","vi":"phóng vệ tinh"},{"en":"product launch","vi":"lễ ra mắt sản phẩm"}],"wordFamily":["relaunch (v.)","launcher (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Việc ra mắt sản phẩm, phát động chiến dịch và phóng vệ tinh đều dùng từ launch.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_maximize', 'en-b2-51', 'maximize', '/ˈmæksɪmaɪz/', 'B2', 'tối đa hóa; tận dụng tối đa', 'v.', 'maximum (n.), maximization (n.)', 'Đồng nghĩa: optimise · Trái nghĩa: minimize', 'Động từ chỉ hành động; tiếng Anh-Anh thường được viết là maximise.', 'We added shelves to maximize space in our tiny kitchen.', NULL, 'Chúng tôi lắp thêm các kệ để tận dụng tối đa không gian trong nhà bếp nhỏ của mình.', '{"wordId":"maximize","ukIpa":"/ˈmæksɪmaɪz/","usIpa":"/ˈmæksɪmaɪz/","cefr":"B2","topic":"work","senses":[{"pos":"v.","en":"to increase something as much as possible or use it fully","vi":"tối đa hóa; tận dụng tối đa"}],"examples":[{"en":"We added shelves to maximize space in our tiny kitchen.","vi":"Chúng tôi lắp thêm các kệ để tận dụng tối đa không gian trong nhà bếp nhỏ của mình.","audioKind":"ex"},{"en":"Cities should improve public transport to maximize access to employment while reducing dependence on private cars.","vi":"Các thành phố nên cải thiện giao thông công cộng để tối đa hóa khả năng tiếp cận việc làm đồng thời giảm sự phụ thuộc vào ô tô cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"maximize profits","vi":"tối đa hóa lợi nhuận"},{"en":"maximize efficiency","vi":"tối đa hóa hiệu suất"},{"en":"maximize space","vi":"tận dụng tối đa không gian"},{"en":"maximize potential","vi":"phát huy tối đa tiềm năng"}],"wordFamily":["maximum (n.)","maximization (n.)"],"synonyms":["optimise"],"antonyms":["minimize"],"tipVi":"Động từ chỉ hành động; tiếng Anh-Anh thường được viết là maximise.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_satisfactorily', 'en-b2-51', 'satisfactorily', '/ˌsætɪsˈfæktərəli/', 'B2', 'một cách thỏa đáng; đạt yêu cầu', 'adv.', 'satisfactory (adj.), satisfaction (n.), satisfy (v.), satisfactoriness (n.)', 'Đồng nghĩa: adequately, acceptably · Trái nghĩa: unsatisfactorily', 'Diễn tả việc đạt yêu cầu đề ra, không nhất thiết là xuất sắc.', 'The washing machine worked satisfactorily after the repair.', NULL, 'Máy giặt đã hoạt động tốt trở lại sau khi được sửa chữa.', '{"wordId":"satisfactorily","ukIpa":"/ˌsætɪsˈfæktərəli/","usIpa":"/ˌsætɪsˈfæktərəli/","cefr":"B2","topic":"work","senses":[{"pos":"adv.","en":"in a way that meets expectations or requirements","vi":"một cách thỏa đáng; đạt yêu cầu"}],"examples":[{"en":"The washing machine worked satisfactorily after the repair.","vi":"Máy giặt đã hoạt động tốt trở lại sau khi được sửa chữa.","audioKind":"ex"},{"en":"Public transport cannot function satisfactorily unless local authorities invest in regular maintenance and staff training.","vi":"Giao thông công cộng không thể hoạt động trơn tru trừ khi chính quyền địa phương đầu tư vào việc bảo trì thường xuyên và đào tạo nhân viên.","audioKind":"ex2"}],"collocations":[{"en":"perform satisfactorily","vi":"thể hiện thỏa đáng"},{"en":"resolve satisfactorily","vi":"giải quyết thỏa đáng"},{"en":"function satisfactorily","vi":"vận hành trơn tru"}],"wordFamily":["satisfactory (adj.)","satisfaction (n.)","satisfy (v.)","satisfactoriness (n.)"],"synonyms":["adequately","acceptably"],"antonyms":["unsatisfactorily"],"tipVi":"Diễn tả việc đạt yêu cầu đề ra, không nhất thiết là xuất sắc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_operator', 'en-b2-51', 'operator', '/ˈɑːpəreɪtər/', 'B2', 'người vận hành; chủ doanh nghiệp; nhà điều hành; nhân viên trực tổng đài; nhân viên tổng đài điện thoại', 'n.', 'operate (v.), operation (n.), operational (adj.)', NULL, 'Từ này vừa dùng để chỉ người vận hành thiết bị, vừa chỉ công ty điều hành dịch vụ.', 'The crane operator carefully lowered the beam into place.', NULL, 'Người vận hành cần cẩu đã cẩn thận hạ dầm thép vào đúng vị trí.', '{"wordId":"operator","ukIpa":"/ˈɒpəreɪtə/","usIpa":"/ˈɑːpəreɪtər/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"a person who controls a machine or piece of equipment","vi":"người vận hành"},{"pos":"n.","en":"a person or company that runs a business or service","vi":"chủ doanh nghiệp; nhà điều hành"},{"pos":"n.","en":"a person who connects calls or provides telephone assistance","vi":"nhân viên trực tổng đài; nhân viên tổng đài điện thoại"}],"examples":[{"en":"The crane operator carefully lowered the beam into place.","vi":"Người vận hành cần cẩu đã cẩn thận hạ dầm thép vào đúng vị trí.","audioKind":"ex"},{"en":"Every public transport operator should ensure that its services remain accessible to passengers with limited mobility.","vi":"Mọi nhà điều hành giao thông công cộng nên đảm bảo rằng các dịch vụ của họ luôn thuận tiện cho hành khách đi lại khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"machine operator","vi":"người vận hành máy móc"},{"en":"tour operator","vi":"công ty du lịch; đơn vị lữ hành"},{"en":"mobile network operator","vi":"nhà mạng di động"},{"en":"telephone operator","vi":"nhân viên tổng đài điện thoại"}],"wordFamily":["operate (v.)","operation (n.)","operational (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ này vừa dùng để chỉ người vận hành thiết bị, vừa chỉ công ty điều hành dịch vụ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recruitment', 'en-b2-51', 'recruitment', '/rɪˈkruːtmənt/', 'B2', 'tuyển dụng; chiêu mộ', 'n.', 'recruit (v.), recruit (n.), recruiter (n.)', 'Đồng nghĩa: hiring', 'Thường là danh từ không đếm được; khi nói tuyển dụng một nhóm đối tượng cụ thể thì dùng recruitment of.', 'Our cafe handles recruitment before the busy summer season.', NULL, 'Quán cà phê của chúng tôi tiến hành tuyển dụng nhân sự trước mùa hè bận rộn.', '{"wordId":"recruitment","ukIpa":"/rɪˈkruːtmənt/","usIpa":"/rɪˈkruːtmənt/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"the process of finding people to join an organisation","vi":"tuyển dụng; chiêu mộ"}],"examples":[{"en":"Our cafe handles recruitment before the busy summer season.","vi":"Quán cà phê của chúng tôi tiến hành tuyển dụng nhân sự trước mùa hè bận rộn.","audioKind":"ex"},{"en":"Fair recruitment practices help employers attract talented applicants from a wide range of social backgrounds.","vi":"Các phương thức tuyển dụng công bằng giúp nhà tuyển dụng thu hút những ứng viên tài năng đến từ nhiều hoàn cảnh xã hội khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"recruitment process","vi":"quy trình tuyển dụng"},{"en":"recruitment agency","vi":"công ty tuyển dụng; trung tâm môi giới việc làm"},{"en":"recruitment campaign","vi":"chiến dịch tuyển dụng"},{"en":"staff recruitment","vi":"tuyển dụng nhân sự"}],"wordFamily":["recruit (v.)","recruit (n.)","recruiter (n.)"],"synonyms":["hiring"],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; khi nói tuyển dụng một nhóm đối tượng cụ thể thì dùng recruitment of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_checklist', 'en-b2-51', 'checklist', '/ˈtʃeklɪst/', 'B2', 'danh sách kiểm tra, bảng kiểm', 'n.', NULL, NULL, 'Là danh từ đếm được; nhấn mạnh việc kiểm tra từng mục chứ không chỉ liệt kê thông thường.', 'I use a checklist when packing for a trip.', NULL, 'Tôi sử dụng danh sách kiểm tra khi thu dọn hành lý cho chuyến đi.', '{"wordId":"checklist","ukIpa":"/ˈtʃeklɪst/","usIpa":"/ˈtʃeklɪst/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"A list of things to check or do","vi":"danh sách kiểm tra, bảng kiểm"}],"examples":[{"en":"I use a checklist when packing for a trip.","vi":"Tôi sử dụng danh sách kiểm tra khi thu dọn hành lý cho chuyến đi.","audioKind":"ex"},{"en":"A standard safety checklist can help hospital staff reduce avoidable errors during routine medical procedures.","vi":"Một bảng kiểm tra an toàn tiêu chuẩn có thể giúp nhân viên bệnh viện giảm thiểu các sai sót có thể tránh được trong các quy trình y tế thông thường.","audioKind":"ex2"}],"collocations":[{"en":"safety checklist","vi":"bảng kiểm tra an toàn"},{"en":"packing checklist","vi":"danh sách đồ đạc mang theo"},{"en":"complete a checklist","vi":"hoàn thành bảng kiểm tra"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ đếm được; nhấn mạnh việc kiểm tra từng mục chứ không chỉ liệt kê thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_efficiency', 'en-b2-51', 'efficiency', '/ɪˈfɪʃnsi/', 'B2', 'hiệu suất, hiệu quả làm việc', 'n.', 'efficient (adj.), efficiently (adv.), inefficiency (n.), inefficient (adj.)', 'Trái nghĩa: inefficiency', 'efficiency nhấn mạnh việc ít lãng phí; effectiveness nhấn mạnh việc đạt được kết quả.', 'Organising my tools improved the efficiency of my work.', NULL, 'Việc sắp xếp các dụng cụ đã giúp tôi nâng cao hiệu suất công việc.', '{"wordId":"efficiency","ukIpa":"/ɪˈfɪʃnsi/","usIpa":"/ɪˈfɪʃnsi/","cefr":"B2","topic":"work","senses":[{"pos":"n.","en":"The ability to achieve results without wasting time, energy, or resources","vi":"hiệu suất, hiệu quả làm việc"}],"examples":[{"en":"Organising my tools improved the efficiency of my work.","vi":"Việc sắp xếp các dụng cụ đã giúp tôi nâng cao hiệu suất công việc.","audioKind":"ex"},{"en":"Improving energy efficiency in public buildings can reduce government spending and lower greenhouse gas emissions.","vi":"Nâng cao hiệu quả sử dụng năng lượng trong các tòa nhà công cộng có thể giảm chi phí nhà nước và hạ mức phát thải khí nhà kính.","audioKind":"ex2"}],"collocations":[{"en":"energy efficiency","vi":"hiệu quả sử dụng năng lượng"},{"en":"improve efficiency","vi":"nâng cao hiệu suất"},{"en":"operational efficiency","vi":"hiệu quả vận hành"},{"en":"fuel efficiency","vi":"hiệu suất tiêu thụ nhiên liệu"}],"wordFamily":["efficient (adj.)","efficiently (adv.)","inefficiency (n.)","inefficient (adj.)"],"synonyms":[],"antonyms":["inefficiency"],"tipVi":"efficiency nhấn mạnh việc ít lãng phí; effectiveness nhấn mạnh việc đạt được kết quả.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_51_1', 'en-b2-51', 'Cách dùng “bookkeeper” (n.) — người giữ sổ sách kế toán; nhân viên ghi sổ', 'employ a bookkeeper  ·  part-time bookkeeper  ·  experienced bookkeeper', 'Chủ yếu chịu trách nhiệm ghi chép sổ sách hàng ngày; phạm vi công việc của accountant (kế toán viên) thường rộng hơn.', 'Họ từ (Word Family): bookkeeping (n.)', '[{"hanzi":"Our bookkeeper checks the receipts every Friday afternoon.","pinyin":"","meaning":"Nhân viên ghi sổ của chúng tôi kiểm tra các biên lai vào mỗi chiều thứ Sáu."},{"hanzi":"Small businesses often employ a bookkeeper to maintain accurate financial records and track daily expenses.","pinyin":"","meaning":"Các doanh nghiệp nhỏ thường thuê nhân viên ghi sổ để duy trì hồ sơ tài chính chính xác và theo dõi chi phí hàng ngày."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_51_2', 'en-b2-51', 'Cách dùng “decorator” (n.) — thợ sơn; thợ trang trí nội thất', 'painter and decorator  ·  interior decorator  ·  hire a decorator', 'Trong tiếng Anh-Anh, từ này thường chỉ thợ sơn tường và dán giấy dán tường, không chỉ đơn thuần là nhà thiết kế.', 'Họ từ (Word Family): decorate (v.), decoration (n.), decorative (adj.)', '[{"hanzi":"The decorator covered our sofa before painting the ceiling.","pinyin":"","meaning":"Thợ trang trí đã phủ kín chiếc sofa của chúng tôi trước khi sơn trần nhà."},{"hanzi":"Employing a professional decorator can help homeowners improve their living space without undertaking major structural changes.","pinyin":"","meaning":"Thuê một thợ trang trí chuyên nghiệp có thể giúp các gia chủ cải thiện không gian sống mà không cần phải thực hiện những thay đổi lớn về cấu trúc."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_51_3', 'en-b2-51', 'Cách dùng “collaboration” (n.) — sự cộng tác; sự hợp tác', 'in collaboration with  ·  close collaboration  ·  international collaboration', 'Trong ngữ cảnh thông thường dùng để chỉ sự hợp tác; nghĩa thông địch cần phải gắn liền với bối cảnh chiến tranh.', 'Họ từ (Word Family): collaborate (v.), collaborative (adj.), collaboratively (adv.), collaborator (n.) | Đồng nghĩa: cooperation, teamwork', '[{"hanzi":"Our garden makeover was a collaboration between several neighbours.","pinyin":"","meaning":"Việc cải tạo khu vườn của chúng tôi là thành quả hợp tác giữa một số gia đình hàng xóm."},{"hanzi":"Closer collaboration between universities and local businesses can help students develop practical skills before entering the workforce.","pinyin":"","meaning":"Sự hợp tác chặt chẽ hơn giữa các trường đại học và doanh nghiệp địa phương có thể giúp sinh viên phát triển các kỹ năng thực tế trước khi gia nhập thị trường lao động."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_51_4', 'en-b2-51', 'Cách dùng “productive” (adj.) — năng suất; hiệu quả; mang lại kết quả tốt', 'a productive discussion  ·  a productive day  ·  productive farmland', 'Dùng để miêu tả công việc hoặc cuộc họp có kết quả tốt; danh từ chỉ năng suất hoặc sản lượng là productivity.', 'Họ từ (Word Family): produce (v.), production (n.), productivity (n.), productively (adv.) | Đồng nghĩa: fruitful · Trái nghĩa: unproductive', '[{"hanzi":"I had a productive morning and finished my report.","pinyin":"","meaning":"Tôi có một buổi sáng làm việc hiệu quả và đã hoàn thành bản báo cáo."},{"hanzi":"Flexible working arrangements can help employees remain productive while balancing professional responsibilities with family commitments.","pinyin":"","meaning":"Các thỏa thuận làm việc linh hoạt có thể giúp nhân viên duy trì năng suất trong khi vẫn cân bằng được trách nhiệm nghề nghiệp và gia đình."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_51_1', 'en-b2-51', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_51_1_1', 'ten_b2_51_1', 'consultant', 'We hired a consultant to help improve our small business.', 'We hired a consultant to help improve our small business.', '/kənˈsʌltənt/', 'Chúng tôi đã thuê một chuyên gia tư vấn để giúp cải thiện doanh nghiệp nhỏ của mình.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_51_1_2', 'ten_b2_51_1', 'extend', 'We extended our holiday because the weather was so lovely.', 'We extended our holiday because the weather was so lovely.', '/ɪkˈstend/', 'Chúng tôi đã kéo dài kỳ nghỉ của mình vì thời tiết quá ư là tuyệt vời.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_51_1_3', 'ten_b2_51_1', 'bookkeeper', 'Our bookkeeper checks the receipts every Friday afternoon.', 'Our bookkeeper checks the receipts every Friday afternoon.', '/ˈbʊkkiːpər/', 'Nhân viên ghi sổ của chúng tôi kiểm tra các biên lai vào mỗi chiều thứ Sáu.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_51_1_4', 'ten_b2_51_1', 'assist', 'A friendly librarian assisted me with the printer.', 'A friendly librarian assisted me with the printer.', '/əˈsɪst/', 'Một nhân viên thư viện thân thiện đã hỗ trợ tôi dùng máy in.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_51_1_5', 'ten_b2_51_1', 'deadline', 'I stayed up late to meet the application deadline.', 'I stayed up late to meet the application deadline.', '/ˈdedlaɪn/', 'Tôi đã thức khuya để kịp hoàn thành hạn nộp hồ sơ.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_51_1_6', 'ten_b2_51_1', 'corporate', 'My sister handles corporate travel for a small company.', 'My sister handles corporate travel for a small company.', '/ˈkɔːrpərət/', 'Chị gái tôi phụ trách việc đi lại công tác cho một công ty nhỏ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_51_1_7', 'ten_b2_51_1', 'supplier', 'Our bakery gets fresh flour from a local supplier.', 'Our bakery gets fresh flour from a local supplier.', '/səˈplaɪər/', 'Tiệm bánh của chúng tôi lấy bột mì tươi từ một nhà cung cấp địa phương.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_51_1_8', 'ten_b2_51_1', 'regarding', 'I called the hotel regarding our missing suitcase.', 'I called the hotel regarding our missing suitcase.', '/rɪˈɡɑːrdɪŋ/', 'Tôi đã gọi điện cho khách sạn để hỏi về chiếc vali bị mất của chúng tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_51_1_1', 'en-b2-51', 'ten_b2_51_1', 'listening', 'listening', 'We hired a consultant to help improve our small business.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tiệm bánh địa phương của chúng tôi đã ra mắt dịch vụ giao hàng mới vào ngày hôm qua.","Anh trai tôi là một kẻ cuồng công việc, hiếm khi chịu nghỉ phép.","Mỗi ứng viên đều đứng đợi bên ngoài văn phòng để phỏng vấn.","Chúng tôi đã thuê một chuyên gia tư vấn để giúp cải thiện doanh nghiệp nhỏ của mình."]'::jsonb, 3, 'We hired a consultant to help improve our small business. → Chúng tôi đã thuê một chuyên gia tư vấn để giúp cải thiện doanh nghiệp nhỏ của mình.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_51_1_2', 'en-b2-51', 'ten_b2_51_1', 'listening', 'listening', 'We extended our holiday because the weather was so lovely.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Anh trai tôi là một kẻ cuồng công việc, hiếm khi chịu nghỉ phép.","Chúng tôi đã kéo dài kỳ nghỉ của mình vì thời tiết quá ư là tuyệt vời.","Chúng tôi đã thuê một chuyên gia tư vấn để giúp cải thiện doanh nghiệp nhỏ của mình.","Việc sắp xếp các dụng cụ đã giúp tôi nâng cao hiệu suất công việc."]'::jsonb, 1, 'We extended our holiday because the weather was so lovely. → Chúng tôi đã kéo dài kỳ nghỉ của mình vì thời tiết quá ư là tuyệt vời.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_51_1_3', 'en-b2-51', 'ten_b2_51_1', 'listening', 'listening', 'Our bookkeeper checks the receipts every Friday afternoon.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một công nhân lao động đang khiêng những viên gạch nặng băng qua công trường xây dựng.","Nhân viên ghi sổ của chúng tôi kiểm tra các biên lai vào mỗi chiều thứ Sáu.","Chúng tôi đã kéo dài kỳ nghỉ của mình vì thời tiết quá ư là tuyệt vời.","Một nhân viên thư viện thân thiện đã hỗ trợ tôi dùng máy in."]'::jsonb, 1, 'Our bookkeeper checks the receipts every Friday afternoon. → Nhân viên ghi sổ của chúng tôi kiểm tra các biên lai vào mỗi chiều thứ Sáu.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_51_2', 'en-b2-51', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_51_2_1', 'ten_b2_51_2', 'consultant', 'An environmental consultant can help companies reduce waste while ensuring that their operations comply with national regulations.', 'An environmental consultant can help companies reduce waste while ensuring that their operations comply with national regulations.', '/kənˈsʌltənt/', 'Một chuyên gia tư vấn môi trường có thể giúp các doanh nghiệp giảm thiểu rác thải đồng thời đảm bảo hoạt động của họ tuân thủ các quy định quốc gia.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_51_2_2', 'ten_b2_51_2', 'extend', 'Governments should extend public transport networks to ensure that residents of outer suburbs can access employment opportunities.', 'Governments should extend public transport networks to ensure that residents of outer suburbs can access employment opportunities.', '/ɪkˈstend/', 'Chính phủ nên mở rộng mạng lưới giao thông công cộng để đảm bảo cư dân ở các vùng ngoại ô xa xôi có thể tiếp cận cơ hội việc làm.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_51_2_3', 'ten_b2_51_2', 'bookkeeper', 'Small businesses often employ a bookkeeper to maintain accurate financial records and track daily expenses.', 'Small businesses often employ a bookkeeper to maintain accurate financial records and track daily expenses.', '/ˈbʊkkiːpər/', 'Các doanh nghiệp nhỏ thường thuê nhân viên ghi sổ để duy trì hồ sơ tài chính chính xác và theo dõi chi phí hàng ngày.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_51_2_4', 'ten_b2_51_2', 'assist', 'Local volunteers can assist older residents with online services, making essential information more accessible.', 'Local volunteers can assist older residents with online services, making essential information more accessible.', '/əˈsɪst/', 'Các tình nguyện viên địa phương có thể giúp đỡ cư dân lớn tuổi sử dụng các dịch vụ trực tuyến, giúp họ tiếp cận thông tin thiết yếu dễ dàng hơn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_51_2_5', 'ten_b2_51_2', 'deadline', 'Setting a realistic deadline allows researchers to maintain quality without delaying the publication of important findings.', 'Setting a realistic deadline allows researchers to maintain quality without delaying the publication of important findings.', '/ˈdedlaɪn/', 'Việc ấn định một thời hạn thực tế giúp các nhà nghiên cứu duy trì chất lượng mà không làm chậm trễ việc công bố các phát hiện quan trọng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_51_2_6', 'ten_b2_51_2', 'corporate', 'Greater corporate transparency allows consumers to assess whether businesses genuinely meet their environmental and social commitments.', 'Greater corporate transparency allows consumers to assess whether businesses genuinely meet their environmental and social commitments.', '/ˈkɔːrpərət/', 'Sự minh bạch doanh nghiệp cao hơn cho phép người tiêu dùng đánh giá xem các doanh nghiệp có thực sự thực hiện các cam kết về môi trường và xã hội của họ hay không.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_51_2_1', 'en-b2-51', 'ten_b2_51_2', 'listening', 'listening', 'An environmental consultant can help companies reduce waste while ensuring that their operations comply with national regulations.', NULL, 'Trong câu vừa nghe, từ “consultant” mang nghĩa nào sau đây?', '["sặc sỡ; tươi sáng","trình tự; chuỗi; một loạt","cố vấn; chuyên gia tư vấn","tinh thể"]'::jsonb, 2, '“consultant” (/kənˈsʌltənt/): cố vấn; chuyên gia tư vấn. Câu đầy đủ: An environmental consultant can help companies reduce waste while ensuring that their operations comply with national regulations.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_51_2_2', 'en-b2-51', 'ten_b2_51_2', 'listening', 'listening', 'Governments should extend public transport networks to ensure that residents of outer suburbs can access employment opportunities.', NULL, 'Trong câu vừa nghe, từ “extend” mang nghĩa nào sau đây?', '["đổ sụp; sụp đổ; ngã gục","kéo dài; mở rộng quy mô, phạm vi","đề cương; dàn ý; bản tóm tắt","cái nhìn; thái độ sống; quan điểm"]'::jsonb, 1, '“extend” (/ɪkˈstend/): kéo dài; mở rộng quy mô, phạm vi. Câu đầy đủ: Governments should extend public transport networks to ensure that residents of outer suburbs can access employment opportunities.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
