INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_51_2', 'en-b2-51', NULL, 'comprehensive_test', 'listening', 'We extended our holiday because the weather was so lovely.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Việc cải tạo khu vườn của chúng tôi là thành quả hợp tác giữa một số gia đình hàng xóm.","Chúng tôi đã kéo dài kỳ nghỉ của mình vì thời tiết quá ư là tuyệt vời.","Mỗi ứng viên đều đứng đợi bên ngoài văn phòng để phỏng vấn.","Cô ấy làm việc không công tại trung tâm bảo vệ động vật vào mỗi thứ Bảy."]'::jsonb, 1, 'We extended our holiday because the weather was so lovely. → Chúng tôi đã kéo dài kỳ nghỉ của mình vì thời tiết quá ư là tuyệt vời.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_51_3', 'en-b2-51', NULL, 'comprehensive_test', 'listening', 'bookkeeper', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thuộc về thành phố; đô thị","tinh nghịch; láu lỉnh; hỗn láo","chế độ nô lệ; tình trạng nô lệ","người giữ sổ sách kế toán; nhân viên ghi sổ"]'::jsonb, 3, 'bookkeeper (/ˈbʊkkiːpər/) → người giữ sổ sách kế toán; nhân viên ghi sổ', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_51_4', 'en-b2-51', NULL, 'comprehensive_test', 'listening', 'A friendly librarian assisted me with the printer.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Anh trai tôi là một kẻ cuồng công việc, hiếm khi chịu nghỉ phép.","Một nhân viên thư viện thân thiện đã hỗ trợ tôi dùng máy in.","Việc cải tạo khu vườn của chúng tôi là thành quả hợp tác giữa một số gia đình hàng xóm.","Chúng tôi đã thuê một chuyên gia tư vấn để giúp cải thiện doanh nghiệp nhỏ của mình."]'::jsonb, 1, 'A friendly librarian assisted me with the printer. → Một nhân viên thư viện thân thiện đã hỗ trợ tôi dùng máy in.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_51_5', 'en-b2-51', NULL, 'comprehensive_test', 'listening', 'deadline', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["giảm một nửa","môn bắn cung; kỹ thuật bắn cung","hạn chót; thời hạn cuối cùng","hạn chế; giới hạn"]'::jsonb, 2, 'deadline (/ˈdedlaɪn/) → hạn chót; thời hạn cuối cùng', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_51_6', 'en-b2-51', NULL, 'comprehensive_test', 'listening', 'My sister handles corporate travel for a small company.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi có một buổi sáng làm việc hiệu quả và đã hoàn thành bản báo cáo.","Tôi đã thức khuya để kịp hoàn thành hạn nộp hồ sơ.","Chị gái tôi phụ trách việc đi lại công tác cho một công ty nhỏ.","Chúng tôi đã thuê một chuyên gia tư vấn để giúp cải thiện doanh nghiệp nhỏ của mình."]'::jsonb, 2, 'My sister handles corporate travel for a small company. → Chị gái tôi phụ trách việc đi lại công tác cho một công ty nhỏ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
