INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_51_18', 'en-b2-51', NULL, 'comprehensive_test', 'reading', NULL, 'An environmental consultant can help companies reduce waste while ensuring that their operations comply with national regulations.', 'Dựa vào câu trên, từ “consultant” có nghĩa phù hợp nhất là gì?', '["đá quý","đợt tái khám; buổi theo dõi; việc theo dõi tiến độ","cố vấn; chuyên gia tư vấn","theo đúng nghĩa đen"]'::jsonb, 2, 'consultant: cố vấn; chuyên gia tư vấn; bác sĩ chuyên khoa cao cấp. Dịch cả câu: Một chuyên gia tư vấn môi trường có thể giúp các doanh nghiệp giảm thiểu rác thải đồng thời đảm bảo hoạt động của họ tuân thủ các quy định quốc gia.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_51_19', 'en-b2-51', NULL, 'comprehensive_test', 'reading', NULL, 'Governments should extend public transport networks to ensure that residents of outer suburbs can access employment opportunities.', 'Dựa vào câu trên, từ “extend” có nghĩa phù hợp nhất là gì?', '["sự điên rồ; hành vi cực kỳ ng U dốt và nguy hiểm","nhà thiên văn học","kéo dài; mở rộng quy mô, phạm vi","nhà bán buôn; doanh nghiệp bán sỉ"]'::jsonb, 2, 'extend: kéo dài; mở rộng quy mô, phạm vi; giơ ra; duỗi ra (tay, chân hoặc bộ phận cơ thể); dành cho; bày tỏ (sự giúp đỡ, lời mời, sự chào đón). Dịch cả câu: Chính phủ nên mở rộng mạng lưới giao thông công cộng để đảm bảo cư dân ở các vùng ngoại ô xa xôi có thể tiếp cận cơ hội việc làm.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_51_20', 'en-b2-51', NULL, 'comprehensive_test', 'reading', NULL, 'Small businesses often employ a bookkeeper to maintain accurate financial records and track daily expenses.', 'Dựa vào câu trên, từ “bookkeeper” có nghĩa phù hợp nhất là gì?', '["người giữ sổ sách kế toán; nhân viên ghi sổ","miễn cưỡng; bất đắc dĩ; ngần ngại","chờ đợi; ngóng chờ","lúng túng; ngượng ngùng; khó xử"]'::jsonb, 0, 'bookkeeper: người giữ sổ sách kế toán; nhân viên ghi sổ. Dịch cả câu: Các doanh nghiệp nhỏ thường thuê nhân viên ghi sổ để duy trì hồ sơ tài chính chính xác và theo dõi chi phí hàng ngày.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_51_21', 'en-b2-51', NULL, 'comprehensive_test', 'reading', NULL, 'Local volunteers can assist older residents with online services, making essential information more accessible.', 'Dựa vào câu trên, từ “assist” có nghĩa phù hợp nhất là gì?', '["quỹ; tiền quỹ","vải bạt; loại vải dày, chắc dùng cho lều, túi và buồm","bọt","giúp đỡ; hỗ trợ"]'::jsonb, 3, 'assist: giúp đỡ; hỗ trợ. Dịch cả câu: Các tình nguyện viên địa phương có thể giúp đỡ cư dân lớn tuổi sử dụng các dịch vụ trực tuyến, giúp họ tiếp cận thông tin thiết yếu dễ dàng hơn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_51_22', 'en-b2-51', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tuyển dụng; chiêu mộ”', '["recruitment","whip","archaeology","approachable"]'::jsonb, 0, 'tuyển dụng; chiêu mộ → recruitment (/rɪˈkruːtmənt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_51_23', 'en-b2-51', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “danh sách kiểm tra, bảng kiểm”', '["checklist","dialect","participant","astonishment"]'::jsonb, 0, 'danh sách kiểm tra, bảng kiểm → checklist (/ˈtʃeklɪst/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_51_24', 'en-b2-51', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hiệu suất, hiệu quả làm việc”', '["crane","antibiotics","interpret","efficiency"]'::jsonb, 3, 'hiệu suất, hiệu quả làm việc → efficiency (/ɪˈfɪʃnsi/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-52', 'en', 'Bài 52: Kinh tế & Tài chính (1) - CEFR B2', 'CEFR B2', 'B2 · Kinh tế', '22 từ vựng Tiếng Anh CEFR B2 chủ đề kinh tế & tài chính kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4052, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_trademark', 'en-b2-52', 'trademark', '/ˈtreɪdmɑːrk/', 'B2', 'nhãn hiệu; thương hiệu đã đăng ký; dấu hiệu đặc trưng; nét riêng; đăng ký thương hiệu; đăng ký nhãn hiệu', 'n.', NULL, NULL, 'Thương hiệu dùng trademark; bản quyền dùng copyright, đối tượng bảo vệ của hai từ này khác nhau.', 'The bakery''s trademark is a tiny golden wheat stalk.', NULL, 'Biểu tượng của tiệm bánh là một bông lúa vàng nhỏ xíu.', '{"wordId":"trademark","ukIpa":"/ˈtreɪdmɑːk/","usIpa":"/ˈtreɪdmɑːrk/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"A legally protected name or symbol identifying a company''s products.","vi":"nhãn hiệu; thương hiệu đã đăng ký"},{"pos":"n.","en":"A distinctive feature strongly associated with someone or something.","vi":"dấu hiệu đặc trưng; nét riêng"},{"pos":"v.","en":"To register a name or symbol for legal protection.","vi":"đăng ký thương hiệu; đăng ký nhãn hiệu"}],"examples":[{"en":"The bakery''s trademark is a tiny golden wheat stalk.","vi":"Biểu tượng của tiệm bánh là một bông lúa vàng nhỏ xíu.","audioKind":"ex"},{"en":"Registering a trademark helps small businesses protect their identity and distinguish their products from those of competitors.","vi":"Việc đăng ký nhãn hiệu giúp các doanh nghiệp nhỏ bảo vệ bản sắc thương hiệu và phân biệt sản phẩm của họ với sản phẩm của các đối thủ cạnh tranh.","audioKind":"ex2"}],"collocations":[{"en":"registered trademark","vi":"thương hiệu đã đăng ký"},{"en":"trademark protection","vi":"bảo hộ thương hiệu"},{"en":"trademark infringement","vi":"vi phạm nhãn hiệu"},{"en":"trademark smile","vi":"nụ cười đặc trưng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thương hiệu dùng trademark; bản quyền dùng copyright, đối tượng bảo vệ của hai từ này khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_auction', 'en-b2-52', 'auction', '/ˈɔːkʃən/', 'B2', 'cuộc đấu giá; bán đấu giá', 'n.', 'auctioneer (n.)', NULL, 'Cụm từ "at auction" có thể đứng độc lập không cần mạo từ; "auction off" có nghĩa là bán đấu giá tống khứ.', 'My aunt bought this old clock at an auction.', NULL, 'Dì tôi đã mua chiếc đồng hồ cũ này tại một buổi đấu giá.', '{"wordId":"auction","ukIpa":"/ˈɔːkʃən/","usIpa":"/ˈɔːkʃən/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"a sale where an item goes to the highest bidder","vi":"cuộc đấu giá"},{"pos":"v.","en":"to sell something to the person offering the most money","vi":"bán đấu giá"}],"examples":[{"en":"My aunt bought this old clock at an auction.","vi":"Dì tôi đã mua chiếc đồng hồ cũ này tại một buổi đấu giá.","audioKind":"ex"},{"en":"Charities often auction donated artwork to raise funds for educational programmes in communities with limited resources.","vi":"Các tổ chức từ thiện thường bán đấu giá các tác phẩm nghệ thuật được tặng để gây quỹ cho các chương trình giáo dục ở những cộng đồng có nguồn lực hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"at auction","vi":"bằng hình thức đấu giá"},{"en":"hold an auction","vi":"tổ chức một phiên đấu giá"},{"en":"auction off","vi":"bán đấu giá"},{"en":"online auction","vi":"đấu giá trực tuyến"}],"wordFamily":["auctioneer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ \"at auction\" có thể đứng độc lập không cần mạo từ; \"auction off\" có nghĩa là bán đấu giá tống khứ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_low-risk', 'en-b2-52', 'low-risk', '/ˌloʊ ˈrɪsk/', 'B2', 'rủi ro thấp', 'adj.', 'risk (n.), risk (v.), risky (adj.)', 'Trái nghĩa: high-risk', 'low-risk biểu thị rủi ro thấp, không có nghĩa là hoàn toàn không có rủi ro.', 'We chose a low-risk investment for our savings.', NULL, 'Chúng tôi đã chọn một khoản đầu tư rủi ro thấp cho tiền tiết kiệm của mình.', '{"wordId":"low-risk","ukIpa":"/ˌləʊ ˈrɪsk/","usIpa":"/ˌloʊ ˈrɪsk/","cefr":"B2","topic":"economy","senses":[{"pos":"adj.","en":"having little chance of harm, loss, or failure","vi":"rủi ro thấp"}],"examples":[{"en":"We chose a low-risk investment for our savings.","vi":"Chúng tôi đã chọn một khoản đầu tư rủi ro thấp cho tiền tiết kiệm của mình.","audioKind":"ex"},{"en":"Low-risk financial products may appeal to households that prioritise stability over potentially higher returns.","vi":"Các sản phẩm tài chính rủi ro thấp có thể thu hút những hộ gia đình ưu tiên sự ổn định hơn là mức lợi nhuận tiềm năng cao hơn.","audioKind":"ex2"}],"collocations":[{"en":"low-risk investment","vi":"khoản đầu tư rủi ro thấp"},{"en":"low-risk activity","vi":"hoạt động rủi ro thấp"},{"en":"low-risk strategy","vi":"chiến lược rủi ro thấp"}],"wordFamily":["risk (n.)","risk (v.)","risky (adj.)"],"synonyms":[],"antonyms":["high-risk"],"tipVi":"low-risk biểu thị rủi ro thấp, không có nghĩa là hoàn toàn không có rủi ro.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_expand', 'en-b2-52', 'expand', '/ɪkˈspænd/', 'B2', 'mở rộng; làm lớn hơn; giải thích chi tiết; nói rõ thêm', 'v.', 'expansion (n.), expandable (adj.), expansive (adj.)', 'Đồng nghĩa: enlarge, extend, grow · Trái nghĩa: shrink, contract', 'Nghĩa "chi tiết hóa" dùng cấu trúc expand on/upon; mở rộng vật gì có thể đi trực tiếp với tân ngữ.', 'The dough expanded as it rested in the warm kitchen.', NULL, 'Khối bột nở lớn lên khi được ủ trong căn bếp ấm áp.', '{"wordId":"expand","ukIpa":"/ɪkˈspænd/","usIpa":"/ɪkˈspænd/","cefr":"B2","topic":"economy","senses":[{"pos":"v.","en":"to become larger or make something larger","vi":"mở rộng; làm lớn hơn"},{"pos":"v.","en":"to add more details to an explanation or discussion","vi":"giải thích chi tiết; nói rõ thêm"}],"examples":[{"en":"The dough expanded as it rested in the warm kitchen.","vi":"Khối bột nở lớn lên khi được ủ trong căn bếp ấm áp.","audioKind":"ex"},{"en":"Universities should expand access to online courses while ensuring that disadvantaged students have adequate equipment and internet connections.","vi":"Các trường đại học nên mở rộng khả năng tiếp cận các khóa học trực tuyến đồng thời đảm bảo rằng học sinh sinh viên có hoàn cảnh khó khăn có đủ thiết bị và kết nối internet.","audioKind":"ex2"}],"collocations":[{"en":"expand rapidly","vi":"mở rộng nhanh chóng"},{"en":"expand access to","vi":"mở rộng khả năng tiếp cận"},{"en":"expand a business","vi":"mở rộng kinh doanh"},{"en":"expand on an idea","vi":"nói rõ thêm về một ý tưởng"}],"wordFamily":["expansion (n.)","expandable (adj.)","expansive (adj.)"],"synonyms":["enlarge","extend","grow"],"antonyms":["shrink","contract"],"tipVi":"Nghĩa \"chi tiết hóa\" dùng cấu trúc expand on/upon; mở rộng vật gì có thể đi trực tiếp với tân ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inflation', 'en-b2-52', 'inflation', '/ɪnˈfleɪʃən/', 'B2', 'lạm phát, sự tăng giá; sự bơm phồng, sự bơm khí', 'n.', 'inflate (v.), inflationary (adj.), inflated (adj.)', 'Trái nghĩa: deflation', 'Trong ngữ cảnh kinh tế, từ này chỉ việc giá cả tăng chung trên diện rộng chứ không chỉ một mặt hàng đơn lẻ.', 'Inflation means our weekly shopping costs more now.', NULL, 'Lạm phát đồng nghĩa với việc chi phí mua sắm hàng tuần của chúng ta hiện nay đắt đỏ hơn.', '{"wordId":"inflation","ukIpa":"/ɪnˈfleɪʃən/","usIpa":"/ɪnˈfleɪʃən/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"A general rise in prices that reduces money''s purchasing power.","vi":"lạm phát, sự tăng giá"},{"pos":"n.","en":"The process of filling something with air or gas.","vi":"sự bơm phồng, sự bơm khí"}],"examples":[{"en":"Inflation means our weekly shopping costs more now.","vi":"Lạm phát đồng nghĩa với việc chi phí mua sắm hàng tuần của chúng ta hiện nay đắt đỏ hơn.","audioKind":"ex"},{"en":"High inflation can reduce household purchasing power, particularly when wages fail to keep pace with rising prices.","vi":"Lạm phát cao có thể làm suy giảm sức mua của các hộ gia đình, đặc biệt là khi tiền lương không theo kịp đà tăng giá cả.","audioKind":"ex2"}],"collocations":[{"en":"the rate of inflation","vi":"tỷ lệ lạm phát"},{"en":"rising inflation","vi":"lạm phát gia tăng"},{"en":"curb inflation","vi":"kiềm chế lạm phát"},{"en":"keep pace with inflation","vi":"theo kịp lạm phát"}],"wordFamily":["inflate (v.)","inflationary (adj.)","inflated (adj.)"],"synonyms":[],"antonyms":["deflation"],"tipVi":"Trong ngữ cảnh kinh tế, từ này chỉ việc giá cả tăng chung trên diện rộng chứ không chỉ một mặt hàng đơn lẻ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_past-due', 'en-b2-52', 'past-due', '/ˌpæst ˈduː/', 'B2', 'quá hạn thanh toán; chậm trả', 'adj.', NULL, 'Đồng nghĩa: overdue', 'Có thể thêm dấu gạch nối khi đứng trước danh từ; khi làm vị ngữ thường viết là past due.', 'I finally paid the past-due bill this morning.', NULL, 'Sáng nay cuối cùng tôi cũng đã thanh toán hóa đơn quá hạn đó rồi.', '{"wordId":"past-due","ukIpa":"/ˌpɑːst ˈdjuː/","usIpa":"/ˌpæst ˈduː/","cefr":"B2","topic":"economy","senses":[{"pos":"adj.","en":"not paid by the date when payment was required","vi":"quá hạn thanh toán; chậm trả"}],"examples":[{"en":"I finally paid the past-due bill this morning.","vi":"Sáng nay cuối cùng tôi cũng đã thanh toán hóa đơn quá hạn đó rồi.","audioKind":"ex"},{"en":"Financial counselling can help households manage past-due payments and avoid falling further into debt.","vi":"Tư vấn tài chính có thể giúp các hộ gia đình xử lý các khoản thanh toán quá hạn và tránh rơi vào cảnh nợ nần chồng chất.","audioKind":"ex2"}],"collocations":[{"en":"past-due bill","vi":"hóa đơn quá hạn"},{"en":"past-due payment","vi":"khoản thanh toán quá hạn"},{"en":"past-due account","vi":"tài khoản nợ quá hạn"}],"wordFamily":[],"synonyms":["overdue"],"antonyms":[],"tipVi":"Có thể thêm dấu gạch nối khi đứng trước danh từ; khi làm vị ngữ thường viết là past due.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_accounting', 'en-b2-52', 'accounting', '/əˈkaʊntɪŋ/', 'B2', 'ngành kế toán; công tác kế toán', 'n.', 'account (n.), accountant (n.), accountancy (n.)', 'Đồng nghĩa: accountancy', 'Biểu thị công việc hoặc môn học kế toán thì không đếm được; kế toán viên là accountant.', 'My sister studies accounting and helps with our shop''s finances.', NULL, 'Chị tôi học ngành kế toán và phụ giúp việc tài chính cho cửa hàng của chúng tôi.', '{"wordId":"accounting","ukIpa":"/əˈkaʊntɪŋ/","usIpa":"/əˈkaʊntɪŋ/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"The work or study of recording and reporting financial transactions.","vi":"ngành kế toán; công tác kế toán"}],"examples":[{"en":"My sister studies accounting and helps with our shop''s finances.","vi":"Chị tôi học ngành kế toán và phụ giúp việc tài chính cho cửa hàng của chúng tôi.","audioKind":"ex"},{"en":"Accurate accounting enables businesses to monitor costs, meet legal requirements, and make informed financial decisions.","vi":"Công tác kế toán chính xác giúp doanh nghiệp kiểm soát chi phí, đáp ứng các yêu cầu pháp lý và đưa ra các quyết định tài chính sáng suốt.","audioKind":"ex2"}],"collocations":[{"en":"accounting software","vi":"phần mềm kế toán"},{"en":"accounting standards","vi":"chuẩn mực kế toán"},{"en":"financial accounting","vi":"kế toán tài chính"}],"wordFamily":["account (n.)","accountant (n.)","accountancy (n.)"],"synonyms":["accountancy"],"antonyms":[],"tipVi":"Biểu thị công việc hoặc môn học kế toán thì không đếm được; kế toán viên là accountant.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_commerce', 'en-b2-52', 'commerce', '/ˈkɑːmɝːs/', 'B2', 'thương mại; buôn bán', 'n.', 'commercial (adj.), commercially (adv.), commercialise (v.)', 'Đồng nghĩa: trade, business', 'commerce thường không đếm được, tập trung vào hoạt động mua bán hàng hóa và dịch vụ.', 'The new bridge has brought more commerce to town.', NULL, 'Cây cầu mới đã mang lại nhiều hoạt động thương mại hơn cho thị trấn.', '{"wordId":"commerce","ukIpa":"/ˈkɒmɜːs/","usIpa":"/ˈkɑːmɝːs/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"The activity of buying and selling goods and services.","vi":"thương mại; buôn bán"}],"examples":[{"en":"The new bridge has brought more commerce to town.","vi":"Cây cầu mới đã mang lại nhiều hoạt động thương mại hơn cho thị trấn.","audioKind":"ex"},{"en":"Online commerce enables small businesses to reach international customers without opening physical shops abroad.","vi":"Thương mại điện tử giúp các doanh nghiệp nhỏ tiếp cận khách hàng quốc tế mà không cần mở cửa hàng vật lý ở nước ngoài.","audioKind":"ex2"}],"collocations":[{"en":"international commerce","vi":"thương mại quốc tế"},{"en":"electronic commerce","vi":"thương mại điện tử"},{"en":"chamber of commerce","vi":"phòng thương mại"}],"wordFamily":["commercial (adj.)","commercially (adv.)","commercialise (v.)"],"synonyms":["trade","business"],"antonyms":[],"tipVi":"commerce thường không đếm được, tập trung vào hoạt động mua bán hàng hóa và dịch vụ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_affordable', 'en-b2-52', 'affordable', '/əˈfɔːrdəbl/', 'B2', 'có giá phải chăng; vừa túi tiền', 'adj.', 'afford (v.), affordability (n.), unaffordable (adj.)', 'Đồng nghĩa: reasonably priced · Trái nghĩa: unaffordable', 'Nhấn mạnh giá nằm trong khả năng chi trả, không nhất thiết có nghĩa là rẻ tuyệt đối.', 'This small flat is affordable on my current salary.', NULL, 'Căn hộ nhỏ này vừa túi tiền với mức lương hiện tại của tôi.', '{"wordId":"affordable","ukIpa":"/əˈfɔːdəbl/","usIpa":"/əˈfɔːrdəbl/","cefr":"B2","topic":"economy","senses":[{"pos":"adj.","en":"Not too expensive for someone to pay for.","vi":"có giá phải chăng; vừa túi tiền"}],"examples":[{"en":"This small flat is affordable on my current salary.","vi":"Căn hộ nhỏ này vừa túi tiền với mức lương hiện tại của tôi.","audioKind":"ex"},{"en":"Governments should provide affordable housing so that essential workers can live close to their workplaces.","vi":"Chính phủ nên cung cấp nhà ở giá rẻ để những người lao động thiết yếu có thể sống gần nơi làm việc của họ.","audioKind":"ex2"}],"collocations":[{"en":"affordable housing","vi":"nhà ở giá rẻ"},{"en":"affordable prices","vi":"giá cả phải chăng"},{"en":"affordable healthcare","vi":"dịch vụ y tế vừa túi tiền"}],"wordFamily":["afford (v.)","affordability (n.)","unaffordable (adj.)"],"synonyms":["reasonably priced"],"antonyms":["unaffordable"],"tipVi":"Nhấn mạnh giá nằm trong khả năng chi trả, không nhất thiết có nghĩa là rẻ tuyệt đối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shipping', 'en-b2-52', 'shipping', '/ˈʃɪpɪŋ/', 'B2', 'sự vận chuyển hàng hóa; ngành vận tải biển; phí vận chuyển; tổng số tàu thuyền', 'n.', 'ship (n.), ship (v.), shipment (n.), shipper (n.)', 'Đồng nghĩa: transportation, delivery', 'Thường là danh từ không đếm được; trong mua sắm trực tuyến, shipping cũng có thể chỉ việc giao hàng nói chung chứ không riêng đường biển.', 'Shipping these boxes overseas will take about a month.', NULL, 'Việc vận chuyển những chiếc hộp này ra nước ngoài sẽ mất khoảng một tháng.', '{"wordId":"shipping","ukIpa":"/ˈʃɪpɪŋ/","usIpa":"/ˈʃɪpɪŋ/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"the business or process of transporting goods","vi":"sự vận chuyển hàng hóa; ngành vận tải biển"},{"pos":"n.","en":"the charge for delivering goods","vi":"phí vận chuyển"},{"pos":"n.","en":"ships considered together as a group","vi":"tổng số tàu thuyền"}],"examples":[{"en":"Shipping these boxes overseas will take about a month.","vi":"Việc vận chuyển những chiếc hộp này ra nước ngoài sẽ mất khoảng một tháng.","audioKind":"ex"},{"en":"International shipping supports global trade, but its environmental impact has prompted demands for cleaner fuels.","vi":"Vận tải biển quốc tế hỗ trợ thương mại toàn cầu, nhưng tác động môi trường của nó đã thúc đẩy các yêu cầu về nhiên liệu sạch hơn.","audioKind":"ex2"}],"collocations":[{"en":"shipping costs","vi":"chi phí vận chuyển"},{"en":"free shipping","vi":"miễn phí vận chuyển"},{"en":"shipping industry","vi":"ngành vận tải biển"},{"en":"shipping lanes","vi":"tuyến đường hàng hải"}],"wordFamily":["ship (n.)","ship (v.)","shipment (n.)","shipper (n.)"],"synonyms":["transportation","delivery"],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; trong mua sắm trực tuyến, shipping cũng có thể chỉ việc giao hàng nói chung chứ không riêng đường biển.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unaffordable', 'en-b2-52', 'unaffordable', '/ˌʌnəˈfɔːrdəbl/', 'B2', 'không kham nổi; đắt đỏ', 'adj.', 'afford (v.), affordable (adj.), affordability (n.)', 'Đồng nghĩa: prohibitively expensive · Trái nghĩa: affordable', 'Nhấn mạnh việc vượt quá khả năng thanh toán, không chỉ đơn thuần là giá cao.', 'The larger flat was unaffordable on my salary.', NULL, 'Căn hộ lớn hơn vượt quá khả năng chi trả với mức lương của tôi.', '{"wordId":"unaffordable","ukIpa":"/ˌʌnəˈfɔːdəbl/","usIpa":"/ˌʌnəˈfɔːrdəbl/","cefr":"B2","topic":"economy","senses":[{"pos":"adj.","en":"Too expensive for someone to pay for.","vi":"không kham nổi; đắt đỏ"}],"examples":[{"en":"The larger flat was unaffordable on my salary.","vi":"Căn hộ lớn hơn vượt quá khả năng chi trả với mức lương của tôi.","audioKind":"ex"},{"en":"When housing becomes unaffordable, essential workers may be forced to move far from their workplaces.","vi":"Khi nhà ở trở nên đắt đỏ vượt mức chịu đựng, những người lao động thiết yếu có thể buộc phải chuyển đến sống xa nơi làm việc của họ.","audioKind":"ex2"}],"collocations":[{"en":"unaffordable housing","vi":"nhà ở đắt đỏ"},{"en":"unaffordable rents","vi":"tiền thuê nhà không kham nổi"},{"en":"become unaffordable","vi":"trở nên đắt đỏ; vượt quá khả năng chi trả"}],"wordFamily":["afford (v.)","affordable (adj.)","affordability (n.)"],"synonyms":["prohibitively expensive"],"antonyms":["affordable"],"tipVi":"Nhấn mạnh việc vượt quá khả năng thanh toán, không chỉ đơn thuần là giá cao.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_economically', 'en-b2-52', 'economically', '/ˌiːkəˈnɑːmɪkli/', 'B2', 'về mặt kinh tế; một cách tiết kiệm', 'adv.', 'economy (n.), economic (adj.), economical (adj.), economics (n.)', NULL, 'Mang cả nghĩa "về mặt kinh tế" của economic và nghĩa "một cách tiết kiệm" của economical.', 'The town depends economically on its busy fishing harbour.', NULL, 'Thị trấn này phụ thuộc về mặt kinh tế vào cảng cá tấp nập của mình.', '{"wordId":"economically","ukIpa":"/ˌiːkəˈnɒmɪkli/","usIpa":"/ˌiːkəˈnɑːmɪkli/","cefr":"B2","topic":"economy","senses":[{"pos":"adv.","en":"in a way relating to money, trade, or the economy","vi":"về mặt kinh tế"},{"pos":"adv.","en":"using little money, fuel, or other resources","vi":"một cách tiết kiệm"}],"examples":[{"en":"The town depends economically on its busy fishing harbour.","vi":"Thị trấn này phụ thuộc về mặt kinh tế vào cảng cá tấp nập của mình.","audioKind":"ex"},{"en":"Renewable energy projects are becoming economically viable as production costs fall and demand for cleaner electricity rises.","vi":"Các dự án năng lượng tái tạo đang dần trở nên khả thi về mặt kinh tế khi chi phí sản xuất giảm và nhu cầu về điện sạch tăng lên.","audioKind":"ex2"}],"collocations":[{"en":"economically viable","vi":"khả thi về mặt kinh tế"},{"en":"economically disadvantaged","vi":"có hoàn cảnh kinh tế khó khăn"},{"en":"economically dependent","vi":"phụ thuộc về mặt kinh tế"},{"en":"live economically","vi":"sống tiết kiệm"}],"wordFamily":["economy (n.)","economic (adj.)","economical (adj.)","economics (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Mang cả nghĩa \"về mặt kinh tế\" của economic và nghĩa \"một cách tiết kiệm\" của economical.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dealer', 'en-b2-52', 'dealer', '/ˈdiːlər/', 'B2', 'nhà phân phối; thương gia; người buôn bán; người chia bài', 'n.', 'deal (v.), dealings (n.)', 'Đồng nghĩa: trader, merchant', 'Thường đi kèm với loại hàng hóa ở phía trước, chẳng hạn như ''car dealer'', để làm rõ lĩnh vực kinh doanh.', 'The dealer showed us three reliable used cars.', NULL, 'Người đại lý ô tô đã cho chúng tôi xem ba chiếc xe cũ đáng tin cậy.', '{"wordId":"dealer","ukIpa":"/ˈdiːlə/","usIpa":"/ˈdiːlər/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"A person or business that buys and sells particular goods.","vi":"nhà phân phối; thương gia; người buôn bán"},{"pos":"n.","en":"The person who gives out cards in a card game.","vi":"người chia bài"}],"examples":[{"en":"The dealer showed us three reliable used cars.","vi":"Người đại lý ô tô đã cho chúng tôi xem ba chiếc xe cũ đáng tin cậy.","audioKind":"ex"},{"en":"Consumers should choose a reputable dealer when purchasing secondhand vehicles to reduce the risk of hidden defects.","vi":"Người tiêu dùng nên chọn một đại lý uy tín khi mua xe đã qua sử dụng để giảm thiểu rủi ro gặp phải các lỗi ẩn giấu.","audioKind":"ex2"}],"collocations":[{"en":"a car dealer","vi":"đại lý ô tô"},{"en":"an art dealer","vi":"thương nhân buôn tác phẩm nghệ thuật"},{"en":"a reputable dealer","vi":"đại lý uy tín"}],"wordFamily":["deal (v.)","dealings (n.)"],"synonyms":["trader","merchant"],"antonyms":[],"tipVi":"Thường đi kèm với loại hàng hóa ở phía trước, chẳng hạn như ''car dealer'', để làm rõ lĩnh vực kinh doanh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_textile', 'en-b2-52', 'textile', '/ˈtekstaɪl/', 'B2', 'hàng dệt may; vải; thuộc về ngành dệt', 'n.', NULL, 'Đồng nghĩa: fabric, cloth', 'Khi nhắc đến các loại vải vóc và sản phẩm dệt nói chung, người ta thường dùng dạng số nhiều "textiles".', 'The market stall sells colourful textiles for making curtains.', NULL, 'Gian hàng ngoài chợ bán những loại vải nhiều màu sắc dùng để may rèm cửa.', '{"wordId":"textile","ukIpa":"/ˈtekstaɪl/","usIpa":"/ˈtekstaɪl/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"cloth made by weaving, knitting, or other fibre processing","vi":"hàng dệt may; vải"},{"pos":"adj.","en":"relating to cloth or its production","vi":"thuộc về ngành dệt"}],"examples":[{"en":"The market stall sells colourful textiles for making curtains.","vi":"Gian hàng ngoài chợ bán những loại vải nhiều màu sắc dùng để may rèm cửa.","audioKind":"ex"},{"en":"The textile industry can reduce water pollution by adopting cleaner production methods and treating wastewater effectively.","vi":"Ngành công nghiệp dệt may có thể giảm ô nhiễm nguồn nước bằng cách áp dụng các phương pháp sản xuất sạch hơn và xử lý nước thải hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"textile industry","vi":"ngành dệt may"},{"en":"textile production","vi":"sản xuất dệt may"},{"en":"textile waste","vi":"phế liệu dệt may"},{"en":"textile factory","vi":"nhà máy dệt"}],"wordFamily":[],"synonyms":["fabric","cloth"],"antonyms":[],"tipVi":"Khi nhắc đến các loại vải vóc và sản phẩm dệt nói chung, người ta thường dùng dạng số nhiều \"textiles\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stake', 'en-b2-52', 'stake', '/steɪk/', 'B2', 'lợi ích tài chính; phần hùn; cổ phần; cái cọc đóng xuống đất; đặt cược; mạo hiểm vì điều gì', 'n.', 'stakeholder (n.)', NULL, 'Cụm have a stake in nghĩa là có chung quyền lợi; at stake chỉ tình thế đang gặp rủi ro.', 'She bought a small stake in her sister''s bakery.', NULL, 'Cô ấy mua một cổ phần nhỏ trong tiệm bánh của chị gái.', '{"wordId":"stake","ukIpa":"/steɪk/","usIpa":"/steɪk/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"a financial share or personal interest in something","vi":"lợi ích tài chính; phần hùn; cổ phần"},{"pos":"n.","en":"a pointed post driven into the ground","vi":"cái cọc đóng xuống đất"},{"pos":"v.","en":"to risk money or something valuable on an outcome","vi":"đặt cược; mạo hiểm vì điều gì"}],"examples":[{"en":"She bought a small stake in her sister''s bakery.","vi":"Cô ấy mua một cổ phần nhỏ trong tiệm bánh của chị gái.","audioKind":"ex"},{"en":"Residents have a stake in urban planning because development decisions directly affect their quality of life.","vi":"Cư dân có quyền lợi gắn bó mật thiết với quy hoạch đô thị vì các quyết định phát triển ảnh hưởng trực tiếp đến chất lượng cuộc sống của họ.","audioKind":"ex2"}],"collocations":[{"en":"a stake in","vi":"có cổ phần hoặc lợi ích trong"},{"en":"at stake","vi":"đang gặp nguy hiểm; ngàn cân treo sợi tóc"},{"en":"stake a claim","vi":"tuyên bố quyền sở hữu"},{"en":"stake your reputation on","vi":"lấy danh dự ra để đánh đổi"}],"wordFamily":["stakeholder (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm have a stake in nghĩa là có chung quyền lợi; at stake chỉ tình thế đang gặp rủi ro.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_expense', 'en-b2-52', 'expense', '/ɪkˈspens/', 'B2', 'chi phí; khoản chi; sự tổn hại; sự bất lợi', 'n.', 'expensive (adj.), inexpensive (adj.), expenditure (n.)', 'Đồng nghĩa: cost, expenditure', 'Các khoản chi tiêu thường ngày thường dùng số nhiều expenses; expensive là tính từ.', 'Rent is our biggest expense every single month.', NULL, 'Tiền thuê nhà là khoản chi lớn nhất của chúng tôi mỗi tháng.', '{"wordId":"expense","ukIpa":"/ɪkˈspens/","usIpa":"/ɪkˈspens/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"money spent or needed for a particular purpose","vi":"chi phí; khoản chi"},{"pos":"n.","en":"harm or disadvantage caused while benefiting someone or something else","vi":"sự tổn hại; sự bất lợi"}],"examples":[{"en":"Rent is our biggest expense every single month.","vi":"Tiền thuê nhà là khoản chi lớn nhất của chúng tôi mỗi tháng.","audioKind":"ex"},{"en":"Cities should improve public transport without placing the entire expense on residents who already face financial difficulties.","vi":"Các thành phố nên cải thiện giao thông công cộng mà không bắt toàn bộ gánh nặng chi phí đổ lên đầu những người dân vốn đã gặp khó khăn tài chính.","audioKind":"ex2"}],"collocations":[{"en":"living expenses","vi":"chi phí sinh hoạt"},{"en":"cover the expense","vi":"chi trả chi phí"},{"en":"at the expense of","vi":"với cái giá phải trả là"},{"en":"spare no expense","vi":"không tiếc tiền"}],"wordFamily":["expensive (adj.)","inexpensive (adj.)","expenditure (n.)"],"synonyms":["cost","expenditure"],"antonyms":[],"tipVi":"Các khoản chi tiêu thường ngày thường dùng số nhiều expenses; expensive là tính từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lease', 'en-b2-52', 'lease', '/liːs/', 'B2', 'hợp đồng thuê; khế ước cho thuê; thuê; cho thuê', 'n.', 'lessor (n.), lessee (n.)', 'Đồng nghĩa: rent', 'lease from nghĩa là đi thuê từ ai; lease to nghĩa là cho người khác thuê.', 'We signed a lease for a sunny upstairs flat.', NULL, 'Chúng tôi đã ký hợp đồng thuê cho một căn hộ lầu trên ngập tràn ánh nắng.', '{"wordId":"lease","ukIpa":"/liːs/","usIpa":"/liːs/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"a legal agreement to use property for payment","vi":"hợp đồng thuê; khế ước cho thuê"},{"pos":"v.","en":"to use or let someone use property for regular payment","vi":"thuê; cho thuê"}],"examples":[{"en":"We signed a lease for a sunny upstairs flat.","vi":"Chúng tôi đã ký hợp đồng thuê cho một căn hộ lầu trên ngập tràn ánh nắng.","audioKind":"ex"},{"en":"Small businesses often lease equipment rather than purchase it outright, allowing them to manage initial costs more effectively.","vi":"Các doanh nghiệp nhỏ thường đi thuê thiết bị thay vì mua đứt, giúp họ quản lý chi phí ban đầu hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"sign a lease","vi":"ký hợp đồng thuê"},{"en":"renew a lease","vi":"gia hạn hợp đồng thuê"},{"en":"a long-term lease","vi":"hợp đồng thuê dài hạn"},{"en":"lease equipment","vi":"thuê thiết bị"}],"wordFamily":["lessor (n.)","lessee (n.)"],"synonyms":["rent"],"antonyms":[],"tipVi":"lease from nghĩa là đi thuê từ ai; lease to nghĩa là cho người khác thuê.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bankruptcy', 'en-b2-52', 'bankruptcy', '/ˈbæŋkrʌptsi/', 'B2', 'sự phá sản; tình trạng vỡ nợ', 'n.', 'bankrupt (adj.), bankrupt (v.)', 'Đồng nghĩa: insolvency · Trái nghĩa: solvency', 'Từ này thường không đếm được; khi nói đến nhiều vụ phá sản, có thể dùng dạng số nhiều bankruptcies.', 'The small bakery faced bankruptcy after months of losses.', NULL, 'Tiệm bánh nhỏ đã đối mặt với nguy cơ phá sản sau nhiều tháng thua lỗ.', '{"wordId":"bankruptcy","ukIpa":"/ˈbæŋkrʌptsi/","usIpa":"/ˈbæŋkrʌptsi/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"The legal state of being unable to pay your debts","vi":"sự phá sản; tình trạng vỡ nợ"}],"examples":[{"en":"The small bakery faced bankruptcy after months of losses.","vi":"Tiệm bánh nhỏ đã đối mặt với nguy cơ phá sản sau nhiều tháng thua lỗ.","audioKind":"ex"},{"en":"Access to affordable loans may help small businesses avoid bankruptcy during periods of economic uncertainty.","vi":"Việc tiếp cận các khoản vay với lãi suất phải chăng có thể giúp các doanh nghiệp nhỏ tránh được tình trạng phá sản trong những giai đoạn kinh tế bất ổn.","audioKind":"ex2"}],"collocations":[{"en":"file for bankruptcy","vi":"nộp đơn xin phá sản"},{"en":"declare bankruptcy","vi":"tuyên bố phá sản"},{"en":"face bankruptcy","vi":"đối mặt với phá sản"},{"en":"bankruptcy protection","vi":"sự bảo hộ phá sản"}],"wordFamily":["bankrupt (adj.)","bankrupt (v.)"],"synonyms":["insolvency"],"antonyms":["solvency"],"tipVi":"Từ này thường không đếm được; khi nói đến nhiều vụ phá sản, có thể dùng dạng số nhiều bankruptcies.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_compensate', 'en-b2-52', 'compensate', '/ˈkɑːmpenseɪt/', 'B2', 'bồi thường; đền bù; bù đắp; khỏa lấp', 'v.', 'compensation (n.), compensatory (adj.)', NULL, 'Bồi thường cho ai dùng compensate sb for sth; bù đắp dùng for.', 'The airline compensated us for our lost luggage.', NULL, 'Hãng hàng không đã bồi thường cho chúng tôi vì hành lý bị thất lạc.', '{"wordId":"compensate","ukIpa":"/ˈkɒmpenseɪt/","usIpa":"/ˈkɑːmpenseɪt/","cefr":"B2","topic":"economy","senses":[{"pos":"v.","en":"To give someone money or something else for loss or harm.","vi":"bồi thường; đền bù"},{"pos":"v.","en":"To balance a disadvantage by providing something beneficial.","vi":"bù đắp; khỏa lấp"}],"examples":[{"en":"The airline compensated us for our lost luggage.","vi":"Hãng hàng không đã bồi thường cho chúng tôi vì hành lý bị thất lạc.","audioKind":"ex"},{"en":"Governments should compensate farmers for income lost when agricultural land is converted into protected habitats.","vi":"Chính phủ nên bồi thường cho nông dân về khoản thu nhập bị mất khi đất nông nghiệp được chuyển đổi thành khu bảo tồn.","audioKind":"ex2"}],"collocations":[{"en":"compensate someone for a loss","vi":"bồi thường cho ai vì tổn thất"},{"en":"compensate for a lack of","vi":"bù đắp cho sự thiếu hụt"},{"en":"fully compensate","vi":"bồi thường thỏa đáng"}],"wordFamily":["compensation (n.)","compensatory (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Bồi thường cho ai dùng compensate sb for sth; bù đắp dùng for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_transaction', 'en-b2-52', 'transaction', '/trænˈzækʃən/', 'B2', 'giao dịch; nghiệp vụ', 'n.', 'transact (v.), transactional (adj.)', 'Đồng nghĩa: deal', 'Thường là danh từ đếm được: một giao dịch là a transaction.', 'The cashier gave me a receipt for the transaction.', NULL, 'Nhân viên thu ngân đưa cho tôi biên lai của giao dịch đó.', '{"wordId":"transaction","ukIpa":"/trænˈzækʃən/","usIpa":"/trænˈzækʃən/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"an act of buying, selling, or exchanging money","vi":"giao dịch; nghiệp vụ"}],"examples":[{"en":"The cashier gave me a receipt for the transaction.","vi":"Nhân viên thu ngân đưa cho tôi biên lai của giao dịch đó.","audioKind":"ex"},{"en":"Secure payment systems are essential for protecting personal information during online transactions and maintaining consumer confidence.","vi":"Hệ thống thanh toán bảo mật là điều thiết yếu để bảo vệ thông tin cá nhân trong các giao dịch trực tuyến và duy trì niềm tin của người tiêu dùng.","audioKind":"ex2"}],"collocations":[{"en":"financial transaction","vi":"giao dịch tài chính"},{"en":"complete a transaction","vi":"hoàn thành giao dịch"},{"en":"transaction fee","vi":"phí giao dịch"},{"en":"online transaction","vi":"giao dịch trực tuyến"}],"wordFamily":["transact (v.)","transactional (adj.)"],"synonyms":["deal"],"antonyms":[],"tipVi":"Thường là danh từ đếm được: một giao dịch là a transaction.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_retail', 'en-b2-52', 'retail', '/ˈriːteɪl/', 'B2', 'sự bán lẻ; việc bán hàng trực tiếp cho người tiêu dùng; thuộc về bán lẻ; bán lẻ; bán hàng cho người tiêu dùng', 'n.', 'retailer (n.), retailing (n.)', 'Trái nghĩa: wholesale', 'retail hướng đến việc bán lẻ cho người tiêu dùng; wholesale dùng để chỉ việc bán sỉ.', 'She works in retail and enjoys helping customers.', NULL, 'Cô ấy làm việc trong ngành bán lẻ và thích giúp đỡ khách hàng.', '{"wordId":"retail","ukIpa":"/ˈriːteɪl/","usIpa":"/ˈriːteɪl/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"the sale of goods directly to consumers","vi":"sự bán lẻ; việc bán hàng trực tiếp cho người tiêu dùng"},{"pos":"adj.","en":"relating to selling goods directly to consumers","vi":"thuộc về bán lẻ"},{"pos":"v.","en":"to sell goods to consumers, often at a stated price","vi":"bán lẻ; bán hàng cho người tiêu dùng"}],"examples":[{"en":"She works in retail and enjoys helping customers.","vi":"Cô ấy làm việc trong ngành bán lẻ và thích giúp đỡ khách hàng.","audioKind":"ex"},{"en":"The growth of online retail has changed shopping habits and increased competition for traditional town centre shops.","vi":"Sự phát triển của ngành bán lẻ trực tuyến đã thay đổi thói quen mua sắm và gia tăng sự cạnh tranh đối với các cửa hàng truyền thống ở khu trung tâm.","audioKind":"ex2"}],"collocations":[{"en":"retail price","vi":"giá bán lẻ"},{"en":"retail sector","vi":"ngành bán lẻ"},{"en":"online retail","vi":"bán lẻ trực tuyến"},{"en":"retail outlet","vi":"cửa hàng bán lẻ"}],"wordFamily":["retailer (n.)","retailing (n.)"],"synonyms":[],"antonyms":["wholesale"],"tipVi":"retail hướng đến việc bán lẻ cho người tiêu dùng; wholesale dùng để chỉ việc bán sỉ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_warehouse', 'en-b2-52', 'warehouse', '/ˈwerhaʊs/', 'B2', 'nhà kho; kho hàng; lưu kho; cất giữ trong kho', 'n.', 'warehousing (n.)', NULL, 'Chỉ tòa nhà lớn dùng để chứa hàng; cách dùng động từ mang tính trang trọng.', 'The warehouse behind the station stores furniture and kitchen equipment.', NULL, 'Nhà kho phía sau nhà ga dùng để chứa đồ đạc và thiết bị nhà bếp.', '{"wordId":"warehouse","ukIpa":"/ˈweəhaʊs/","usIpa":"/ˈwerhaʊs/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"A large building where goods are stored before distribution","vi":"nhà kho; kho hàng"},{"pos":"v.","en":"Store goods in a warehouse","vi":"lưu kho; cất giữ trong kho"}],"examples":[{"en":"The warehouse behind the station stores furniture and kitchen equipment.","vi":"Nhà kho phía sau nhà ga dùng để chứa đồ đạc và thiết bị nhà bếp.","audioKind":"ex"},{"en":"Locating a warehouse near major transport routes can reduce delivery costs and improve supply chain efficiency.","vi":"Việc đặt nhà kho gần các tuyến đường giao thông chính có thể giảm chi phí vận chuyển và nâng cao hiệu suất chuỗi cung ứng.","audioKind":"ex2"}],"collocations":[{"en":"warehouse worker","vi":"công nhân kho hàng"},{"en":"warehouse space","vi":"không gian kho bãi"},{"en":"automated warehouse","vi":"kho hàng tự động"}],"wordFamily":["warehousing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ tòa nhà lớn dùng để chứa hàng; cách dùng động từ mang tính trang trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_52_1', 'en-b2-52', 'Cách dùng “shipping” (n.) — sự vận chuyển hàng hóa; ngành vận tải biển', 'shipping costs  ·  free shipping  ·  shipping industry', 'Thường là danh từ không đếm được; trong mua sắm trực tuyến, shipping cũng có thể chỉ việc giao hàng nói chung chứ không riêng đường biển.', 'Họ từ (Word Family): ship (n.), ship (v.), shipment (n.), shipper (n.) | Đồng nghĩa: transportation, delivery', '[{"hanzi":"Shipping these boxes overseas will take about a month.","pinyin":"","meaning":"Việc vận chuyển những chiếc hộp này ra nước ngoài sẽ mất khoảng một tháng."},{"hanzi":"International shipping supports global trade, but its environmental impact has prompted demands for cleaner fuels.","pinyin":"","meaning":"Vận tải biển quốc tế hỗ trợ thương mại toàn cầu, nhưng tác động môi trường của nó đã thúc đẩy các yêu cầu về nhiên liệu sạch hơn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_52_2', 'en-b2-52', 'Cách dùng “inflation” (n.) — lạm phát, sự tăng giá', 'the rate of inflation  ·  rising inflation  ·  curb inflation', 'Trong ngữ cảnh kinh tế, từ này chỉ việc giá cả tăng chung trên diện rộng chứ không chỉ một mặt hàng đơn lẻ.', 'Họ từ (Word Family): inflate (v.), inflationary (adj.), inflated (adj.) | Trái nghĩa: deflation', '[{"hanzi":"Inflation means our weekly shopping costs more now.","pinyin":"","meaning":"Lạm phát đồng nghĩa với việc chi phí mua sắm hàng tuần của chúng ta hiện nay đắt đỏ hơn."},{"hanzi":"High inflation can reduce household purchasing power, particularly when wages fail to keep pace with rising prices.","pinyin":"","meaning":"Lạm phát cao có thể làm suy giảm sức mua của các hộ gia đình, đặc biệt là khi tiền lương không theo kịp đà tăng giá cả."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_52_3', 'en-b2-52', 'Cách dùng “auction” (n.) — cuộc đấu giá', 'at auction  ·  hold an auction  ·  auction off', 'Cụm từ "at auction" có thể đứng độc lập không cần mạo từ; "auction off" có nghĩa là bán đấu giá tống khứ.', 'Họ từ (Word Family): auctioneer (n.)', '[{"hanzi":"My aunt bought this old clock at an auction.","pinyin":"","meaning":"Dì tôi đã mua chiếc đồng hồ cũ này tại một buổi đấu giá."},{"hanzi":"Charities often auction donated artwork to raise funds for educational programmes in communities with limited resources.","pinyin":"","meaning":"Các tổ chức từ thiện thường bán đấu giá các tác phẩm nghệ thuật được tặng để gây quỹ cho các chương trình giáo dục ở những cộng đồng có nguồn lực hạn chế."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_52_4', 'en-b2-52', 'Cách dùng “dealer” (n.) — nhà phân phối; thương gia; người buôn bán', 'a car dealer  ·  an art dealer  ·  a reputable dealer', 'Thường đi kèm với loại hàng hóa ở phía trước, chẳng hạn như ''car dealer'', để làm rõ lĩnh vực kinh doanh.', 'Họ từ (Word Family): deal (v.), dealings (n.) | Đồng nghĩa: trader, merchant', '[{"hanzi":"The dealer showed us three reliable used cars.","pinyin":"","meaning":"Người đại lý ô tô đã cho chúng tôi xem ba chiếc xe cũ đáng tin cậy."},{"hanzi":"Consumers should choose a reputable dealer when purchasing secondhand vehicles to reduce the risk of hidden defects.","pinyin":"","meaning":"Người tiêu dùng nên chọn một đại lý uy tín khi mua xe đã qua sử dụng để giảm thiểu rủi ro gặp phải các lỗi ẩn giấu."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_52_1', 'en-b2-52', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_52_1_1', 'ten_b2_52_1', 'trademark', 'The bakery''s trademark is a tiny golden wheat stalk.', 'The bakery''s trademark is a tiny golden wheat stalk.', '/ˈtreɪdmɑːrk/', 'Biểu tượng của tiệm bánh là một bông lúa vàng nhỏ xíu.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_52_1_2', 'ten_b2_52_1', 'auction', 'My aunt bought this old clock at an auction.', 'My aunt bought this old clock at an auction.', '/ˈɔːkʃən/', 'Dì tôi đã mua chiếc đồng hồ cũ này tại một buổi đấu giá.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_52_1_3', 'ten_b2_52_1', 'low-risk', 'We chose a low-risk investment for our savings.', 'We chose a low-risk investment for our savings.', '/ˌloʊ ˈrɪsk/', 'Chúng tôi đã chọn một khoản đầu tư rủi ro thấp cho tiền tiết kiệm của mình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_52_1_4', 'ten_b2_52_1', 'expand', 'The dough expanded as it rested in the warm kitchen.', 'The dough expanded as it rested in the warm kitchen.', '/ɪkˈspænd/', 'Khối bột nở lớn lên khi được ủ trong căn bếp ấm áp.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_52_1_5', 'ten_b2_52_1', 'inflation', 'Inflation means our weekly shopping costs more now.', 'Inflation means our weekly shopping costs more now.', '/ɪnˈfleɪʃən/', 'Lạm phát đồng nghĩa với việc chi phí mua sắm hàng tuần của chúng ta hiện nay đắt đỏ hơn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_52_1_6', 'ten_b2_52_1', 'past-due', 'I finally paid the past-due bill this morning.', 'I finally paid the past-due bill this morning.', '/ˌpæst ˈduː/', 'Sáng nay cuối cùng tôi cũng đã thanh toán hóa đơn quá hạn đó rồi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_52_1_7', 'ten_b2_52_1', 'accounting', 'My sister studies accounting and helps with our shop''s finances.', 'My sister studies accounting and helps with our shop''s finances.', '/əˈkaʊntɪŋ/', 'Chị tôi học ngành kế toán và phụ giúp việc tài chính cho cửa hàng của chúng tôi.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_52_1_8', 'ten_b2_52_1', 'commerce', 'The new bridge has brought more commerce to town.', 'The new bridge has brought more commerce to town.', '/ˈkɑːmɝːs/', 'Cây cầu mới đã mang lại nhiều hoạt động thương mại hơn cho thị trấn.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_52_1_1', 'en-b2-52', 'ten_b2_52_1', 'listening', 'listening', 'The bakery''s trademark is a tiny golden wheat stalk.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Thị trấn này phụ thuộc về mặt kinh tế vào cảng cá tấp nập của mình.","Nhân viên thu ngân đưa cho tôi biên lai của giao dịch đó.","Tiền thuê nhà là khoản chi lớn nhất của chúng tôi mỗi tháng.","Biểu tượng của tiệm bánh là một bông lúa vàng nhỏ xíu."]'::jsonb, 3, 'The bakery''s trademark is a tiny golden wheat stalk. → Biểu tượng của tiệm bánh là một bông lúa vàng nhỏ xíu.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_52_1_2', 'en-b2-52', 'ten_b2_52_1', 'listening', 'listening', 'My aunt bought this old clock at an auction.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã ký hợp đồng thuê cho một căn hộ lầu trên ngập tràn ánh nắng.","Biểu tượng của tiệm bánh là một bông lúa vàng nhỏ xíu.","Dì tôi đã mua chiếc đồng hồ cũ này tại một buổi đấu giá.","Căn hộ nhỏ này vừa túi tiền với mức lương hiện tại của tôi."]'::jsonb, 2, 'My aunt bought this old clock at an auction. → Dì tôi đã mua chiếc đồng hồ cũ này tại một buổi đấu giá.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_52_1_3', 'en-b2-52', 'ten_b2_52_1', 'listening', 'listening', 'We chose a low-risk investment for our savings.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nhà kho phía sau nhà ga dùng để chứa đồ đạc và thiết bị nhà bếp.","Chúng tôi đã chọn một khoản đầu tư rủi ro thấp cho tiền tiết kiệm của mình.","Nhân viên thu ngân đưa cho tôi biên lai của giao dịch đó.","Dì tôi đã mua chiếc đồng hồ cũ này tại một buổi đấu giá."]'::jsonb, 1, 'We chose a low-risk investment for our savings. → Chúng tôi đã chọn một khoản đầu tư rủi ro thấp cho tiền tiết kiệm của mình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_52_2', 'en-b2-52', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_52_2_1', 'ten_b2_52_2', 'trademark', 'Registering a trademark helps small businesses protect their identity and distinguish their products from those of competitors.', 'Registering a trademark helps small businesses protect their identity and distinguish their products from those of competitors.', '/ˈtreɪdmɑːrk/', 'Việc đăng ký nhãn hiệu giúp các doanh nghiệp nhỏ bảo vệ bản sắc thương hiệu và phân biệt sản phẩm của họ với sản phẩm của các đối thủ cạnh tranh.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_52_2_2', 'ten_b2_52_2', 'auction', 'Charities often auction donated artwork to raise funds for educational programmes in communities with limited resources.', 'Charities often auction donated artwork to raise funds for educational programmes in communities with limited resources.', '/ˈɔːkʃən/', 'Các tổ chức từ thiện thường bán đấu giá các tác phẩm nghệ thuật được tặng để gây quỹ cho các chương trình giáo dục ở những cộng đồng có nguồn lực hạn chế.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_52_2_3', 'ten_b2_52_2', 'low-risk', 'Low-risk financial products may appeal to households that prioritise stability over potentially higher returns.', 'Low-risk financial products may appeal to households that prioritise stability over potentially higher returns.', '/ˌloʊ ˈrɪsk/', 'Các sản phẩm tài chính rủi ro thấp có thể thu hút những hộ gia đình ưu tiên sự ổn định hơn là mức lợi nhuận tiềm năng cao hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_52_2_4', 'ten_b2_52_2', 'expand', 'Universities should expand access to online courses while ensuring that disadvantaged students have adequate equipment and internet connections.', 'Universities should expand access to online courses while ensuring that disadvantaged students have adequate equipment and internet connections.', '/ɪkˈspænd/', 'Các trường đại học nên mở rộng khả năng tiếp cận các khóa học trực tuyến đồng thời đảm bảo rằng học sinh sinh viên có hoàn cảnh khó khăn có đủ thiết bị và kết nối internet.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_52_2_5', 'ten_b2_52_2', 'inflation', 'High inflation can reduce household purchasing power, particularly when wages fail to keep pace with rising prices.', 'High inflation can reduce household purchasing power, particularly when wages fail to keep pace with rising prices.', '/ɪnˈfleɪʃən/', 'Lạm phát cao có thể làm suy giảm sức mua của các hộ gia đình, đặc biệt là khi tiền lương không theo kịp đà tăng giá cả.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_52_2_6', 'ten_b2_52_2', 'past-due', 'Financial counselling can help households manage past-due payments and avoid falling further into debt.', 'Financial counselling can help households manage past-due payments and avoid falling further into debt.', '/ˌpæst ˈduː/', 'Tư vấn tài chính có thể giúp các hộ gia đình xử lý các khoản thanh toán quá hạn và tránh rơi vào cảnh nợ nần chồng chất.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_52_2_1', 'en-b2-52', 'ten_b2_52_2', 'listening', 'listening', 'Registering a trademark helps small businesses protect their identity and distinguish their products from those of competitors.', NULL, 'Trong câu vừa nghe, từ “trademark” mang nghĩa nào sau đây?', '["nhãn hiệu; thương hiệu đã đăng ký","bồi thẩm đoàn","do đó; vì vậy; từ đó","sinh thái học"]'::jsonb, 0, '“trademark” (/ˈtreɪdmɑːrk/): nhãn hiệu; thương hiệu đã đăng ký. Câu đầy đủ: Registering a trademark helps small businesses protect their identity and distinguish their products from those of competitors.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_52_2_2', 'en-b2-52', 'ten_b2_52_2', 'listening', 'listening', 'Charities often auction donated artwork to raise funds for educational programmes in communities with limited resources.', NULL, 'Trong câu vừa nghe, từ “auction” mang nghĩa nào sau đây?', '["tự kinh doanh; tự làm chủ","cuộc đấu giá","thuộc nội địa; ở sâu trong đất liền","thú nhận; thú tội; khai nhận"]'::jsonb, 1, '“auction” (/ˈɔːkʃən/): cuộc đấu giá. Câu đầy đủ: Charities often auction donated artwork to raise funds for educational programmes in communities with limited resources.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
