INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_52_2', 'en-b2-52', NULL, 'comprehensive_test', 'listening', 'My aunt bought this old clock at an auction.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Dì tôi đã mua chiếc đồng hồ cũ này tại một buổi đấu giá.","Sáng nay cuối cùng tôi cũng đã thanh toán hóa đơn quá hạn đó rồi.","Khối bột nở lớn lên khi được ủ trong căn bếp ấm áp.","Thị trấn này phụ thuộc về mặt kinh tế vào cảng cá tấp nập của mình."]'::jsonb, 0, 'My aunt bought this old clock at an auction. → Dì tôi đã mua chiếc đồng hồ cũ này tại một buổi đấu giá.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_52_3', 'en-b2-52', NULL, 'comprehensive_test', 'listening', 'low-risk', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["người kể chuyện; người thuyết minh; giọng đọc thuyết minh","rủi ro thấp","thông dịch viên, phiên dịch viên","học phí"]'::jsonb, 1, 'low-risk (/ˌloʊ ˈrɪsk/) → rủi ro thấp', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_52_4', 'en-b2-52', NULL, 'comprehensive_test', 'listening', 'The dough expanded as it rested in the warm kitchen.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hãng hàng không đã bồi thường cho chúng tôi vì hành lý bị thất lạc.","Chúng tôi đã ký hợp đồng thuê cho một căn hộ lầu trên ngập tràn ánh nắng.","Khối bột nở lớn lên khi được ủ trong căn bếp ấm áp.","Cô ấy mua một cổ phần nhỏ trong tiệm bánh của chị gái."]'::jsonb, 2, 'The dough expanded as it rested in the warm kitchen. → Khối bột nở lớn lên khi được ủ trong căn bếp ấm áp.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_52_5', 'en-b2-52', NULL, 'comprehensive_test', 'listening', 'inflation', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["kiến thức chuyên môn; kỹ năng chuyên sâu","lạm phát, sự tăng giá","tiếp thị; marketing","hơn nữa; ngoài ra"]'::jsonb, 1, 'inflation (/ɪnˈfleɪʃən/) → lạm phát, sự tăng giá; sự bơm phồng, sự bơm khí', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_52_6', 'en-b2-52', NULL, 'comprehensive_test', 'listening', 'I finally paid the past-due bill this morning.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã chọn một khoản đầu tư rủi ro thấp cho tiền tiết kiệm của mình.","Cô ấy mua một cổ phần nhỏ trong tiệm bánh của chị gái.","Tiệm bánh nhỏ đã đối mặt với nguy cơ phá sản sau nhiều tháng thua lỗ.","Sáng nay cuối cùng tôi cũng đã thanh toán hóa đơn quá hạn đó rồi."]'::jsonb, 3, 'I finally paid the past-due bill this morning. → Sáng nay cuối cùng tôi cũng đã thanh toán hóa đơn quá hạn đó rồi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
