INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_52_8', 'en-b2-52', NULL, 'comprehensive_test', 'listening', 'The new bridge has brought more commerce to town.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tiền thuê nhà là khoản chi lớn nhất của chúng tôi mỗi tháng.","Lạm phát đồng nghĩa với việc chi phí mua sắm hàng tuần của chúng ta hiện nay đắt đỏ hơn.","Dì tôi đã mua chiếc đồng hồ cũ này tại một buổi đấu giá.","Cây cầu mới đã mang lại nhiều hoạt động thương mại hơn cho thị trấn."]'::jsonb, 3, 'The new bridge has brought more commerce to town. → Cây cầu mới đã mang lại nhiều hoạt động thương mại hơn cho thị trấn.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
