INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_52_18', 'en-b2-52', NULL, 'comprehensive_test', 'reading', NULL, 'Registering a trademark helps small businesses protect their identity and distinguish their products from those of competitors.', 'Dựa vào câu trên, từ “trademark” có nghĩa phù hợp nhất là gì?', '["tuy nhiên; dù vậy; mặc dù thế (bất chấp điều vừa mới được đề cập)","nhãn hiệu; thương hiệu đã đăng ký","hãng vận chuyển; công ty vận tải","nỗi đau đớn; sự khổ sở"]'::jsonb, 1, 'trademark: nhãn hiệu; thương hiệu đã đăng ký; dấu hiệu đặc trưng; nét riêng; đăng ký thương hiệu; đăng ký nhãn hiệu. Dịch cả câu: Việc đăng ký nhãn hiệu giúp các doanh nghiệp nhỏ bảo vệ bản sắc thương hiệu và phân biệt sản phẩm của họ với sản phẩm của các đối thủ cạnh tranh.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_52_19', 'en-b2-52', NULL, 'comprehensive_test', 'reading', NULL, 'Charities often auction donated artwork to raise funds for educational programmes in communities with limited resources.', 'Dựa vào câu trên, từ “auction” có nghĩa phù hợp nhất là gì?', '["cuộc đấu giá","khóc; rơi lệ","không màu; trong suốt","khoảng thời gian; quãng thời gian"]'::jsonb, 0, 'auction: cuộc đấu giá; bán đấu giá. Dịch cả câu: Các tổ chức từ thiện thường bán đấu giá các tác phẩm nghệ thuật được tặng để gây quỹ cho các chương trình giáo dục ở những cộng đồng có nguồn lực hạn chế.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_52_20', 'en-b2-52', NULL, 'comprehensive_test', 'reading', NULL, 'Low-risk financial products may appeal to households that prioritise stability over potentially higher returns.', 'Dựa vào câu trên, từ “low-risk” có nghĩa phù hợp nhất là gì?', '["làm cho phức tạp; làm cho khó giải quyết hơn","rủi ro thấp","cá tuyết; thịt cá tuyết","chắc chắn; có khả năng cao"]'::jsonb, 1, 'low-risk: rủi ro thấp. Dịch cả câu: Các sản phẩm tài chính rủi ro thấp có thể thu hút những hộ gia đình ưu tiên sự ổn định hơn là mức lợi nhuận tiềm năng cao hơn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_52_21', 'en-b2-52', NULL, 'comprehensive_test', 'reading', NULL, 'Universities should expand access to online courses while ensuring that disadvantaged students have adequate equipment and internet connections.', 'Dựa vào câu trên, từ “expand” có nghĩa phù hợp nhất là gì?', '["cơ chế; phương thức vận hành","lo lắng; bồn chồn","mở rộng; làm lớn hơn","bệnh béo phì"]'::jsonb, 2, 'expand: mở rộng; làm lớn hơn; giải thích chi tiết; nói rõ thêm. Dịch cả câu: Các trường đại học nên mở rộng khả năng tiếp cận các khóa học trực tuyến đồng thời đảm bảo rằng học sinh sinh viên có hoàn cảnh khó khăn có đủ thiết bị và kết nối internet.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_52_22', 'en-b2-52', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “giao dịch; nghiệp vụ”', '["transaction","activate","memorable","disappearance"]'::jsonb, 0, 'giao dịch; nghiệp vụ → transaction (/trænˈzækʃən/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_52_23', 'en-b2-52', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự bán lẻ; việc bán hàng trực tiếp cho người tiêu dùng”', '["recall","comparatively","retail","abundant"]'::jsonb, 2, 'sự bán lẻ; việc bán hàng trực tiếp cho người tiêu dùng → retail (/ˈriːteɪl/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_52_24', 'en-b2-52', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nhà kho; kho hàng”', '["warehouse","odour","fighter","gravel"]'::jsonb, 0, 'nhà kho; kho hàng → warehouse (/ˈwerhaʊs/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-53', 'en', 'Bài 53: Kinh tế & Tài chính (2) - CEFR B2', 'CEFR B2', 'B2 · Kinh tế', '22 từ vựng Tiếng Anh CEFR B2 chủ đề kinh tế & tài chính kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4053, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_allowance', 'en-b2-53', 'allowance', '/əˈlaʊ.əns/', 'B2', 'tiền trợ cấp; tiền tiêu vặt định kỳ; hạn mức; định mức cho phép; sự châm chước; sự cân nhắc', 'n.', 'allow (v.), allowable (adj.)', NULL, 'Nghĩa tiền tiêu vặt phổ biến trong tiếng Anh-Mỹ; tiếng Anh-Anh thường dùng pocket money.', 'My weekly allowance covers bus fares and occasional snacks.', NULL, 'Khoản tiền tiêu vặt hàng tuần của tôi đủ chi trả tiền xe buýt và đôi khi mua đồ ăn vặt.', '{"wordId":"allowance","ukIpa":"/əˈlaʊ.əns/","usIpa":"/əˈlaʊ.əns/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"Money given regularly to cover particular needs","vi":"tiền trợ cấp; tiền tiêu vặt định kỳ"},{"pos":"n.","en":"An amount you are permitted to use or have","vi":"hạn mức; định mức cho phép"},{"pos":"n.","en":"An adjustment made to account for someone''s circumstances or difficulties","vi":"sự châm chước; sự cân nhắc"}],"examples":[{"en":"My weekly allowance covers bus fares and occasional snacks.","vi":"Khoản tiền tiêu vặt hàng tuần của tôi đủ chi trả tiền xe buýt và đôi khi mua đồ ăn vặt.","audioKind":"ex"},{"en":"A housing allowance can help essential workers afford accommodation in cities where rents are particularly high.","vi":"Trợ cấp nhà ở có thể giúp những lao động thiết yếu trang trải chỗ ở tại các thành phố nơi giá thuê nhà cực kỳ cao.","audioKind":"ex2"}],"collocations":[{"en":"a housing allowance","vi":"khoản trợ cấp nhà ở"},{"en":"a daily allowance","vi":"tiền trợ cấp hằng ngày"},{"en":"baggage allowance","vi":"hạn mức hành lý"},{"en":"make allowances for","vi":"châm chước; cân nhắc"}],"wordFamily":["allow (v.)","allowable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa tiền tiêu vặt phổ biến trong tiếng Anh-Mỹ; tiếng Anh-Anh thường dùng pocket money.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_outlet', 'en-b2-53', 'outlet', '/ˈaʊtlet/', 'B2', 'cửa hàng; điểm bán lẻ; lối thoát; phương thức giải tỏa (cảm xúc, năng lượng); lỗ thoát; cửa xả (chất lỏng hoặc khí)', 'n.', NULL, NULL, 'Cụm outlet for thường chỉ phương tiện bộc lộ; trong tiếng Anh Mỹ, từ này còn có nghĩa là ổ cắm điện.', 'A new clothing outlet opened near the station yesterday.', NULL, 'Một cửa hàng quần áo mới đã khai trương gần nhà ga vào ngày hôm qua.', '{"wordId":"outlet","ukIpa":"/ˈaʊtlet/","usIpa":"/ˈaʊtlet/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"A shop or other place where goods are sold.","vi":"cửa hàng; điểm bán lẻ"},{"pos":"n.","en":"A way to express feelings, energy, or creative abilities.","vi":"lối thoát; phương thức giải tỏa (cảm xúc, năng lượng)"},{"pos":"n.","en":"An opening through which liquid, gas, or air can escape.","vi":"lỗ thoát; cửa xả (chất lỏng hoặc khí)"}],"examples":[{"en":"A new clothing outlet opened near the station yesterday.","vi":"Một cửa hàng quần áo mới đã khai trương gần nhà ga vào ngày hôm qua.","audioKind":"ex"},{"en":"Community arts programmes provide a valuable outlet for young people to express emotions and develop confidence.","vi":"Các chương trình nghệ thuật cộng đồng mang lại kênh giải tỏa giá trị giúp người trẻ thể hiện cảm xúc và xây dựng sự tự tin.","audioKind":"ex2"}],"collocations":[{"en":"retail outlet","vi":"điểm bán lẻ"},{"en":"creative outlet","vi":"nơi phát huy sự sáng tạo"},{"en":"an outlet for frustration","vi":"phương thức giải tỏa sự thất vọng"},{"en":"water outlet","vi":"đầu ra của nước"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm outlet for thường chỉ phương tiện bộc lộ; trong tiếng Anh Mỹ, từ này còn có nghĩa là ổ cắm điện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_margin', 'en-b2-53', 'margin', '/ˈmɑːrdʒɪn/', 'B2', 'lề trang giấy; phần mép; khoảng cách; biên độ; mức chênh lệch; dư địa; tỷ suất lợi nhuận; biên lợi nhuận', 'n.', 'marginal (adj.), marginally (adv.)', 'Đồng nghĩa: edge, gap', 'Cụm by a narrow margin diễn tả việc chiến thắng hoặc đạt được điều gì với khoảng cách rất suýt soát.', 'Leave a wide margin for your teacher''s comments.', NULL, 'Hãy chừa lề giấy thật rộng để giáo viên viết lời phê.', '{"wordId":"margin","ukIpa":"/ˈmɑːdʒɪn/","usIpa":"/ˈmɑːrdʒɪn/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"the blank space around a page or an area''s edge","vi":"lề trang giấy; phần mép"},{"pos":"n.","en":"the difference between amounts or extra space for safety","vi":"khoảng cách; biên độ; mức chênh lệch; dư địa"},{"pos":"n.","en":"the difference between selling price and production cost","vi":"tỷ suất lợi nhuận; biên lợi nhuận"}],"examples":[{"en":"Leave a wide margin for your teacher''s comments.","vi":"Hãy chừa lề giấy thật rộng để giáo viên viết lời phê.","audioKind":"ex"},{"en":"Small retailers often operate on a narrow profit margin, making them particularly vulnerable to rising energy costs.","vi":"Các nhà bán lẻ nhỏ thường hoạt động với biên lợi nhuận thấp, điều này khiến họ đặc biệt dễ bị tổn thương trước việc chi phí năng lượng leo thang.","audioKind":"ex2"}],"collocations":[{"en":"a wide margin","vi":"lề rộng; khoảng cách lớn"},{"en":"profit margin","vi":"tỷ suất lợi nhuận"},{"en":"margin of error","vi":"sai số cho phép"},{"en":"a safety margin","vi":"mức dự phòng an toàn"}],"wordFamily":["marginal (adj.)","marginally (adv.)"],"synonyms":["edge","gap"],"antonyms":[],"tipVi":"Cụm by a narrow margin diễn tả việc chiến thắng hoặc đạt được điều gì với khoảng cách rất suýt soát.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mortgage', 'en-b2-53', 'mortgage', '/ˈmɔːrɡɪdʒ/', 'B2', 'khoản vay thế chấp mua nhà; tiền thế chấp; cầm cố; thế chấp tài sản để vay tiền', 'n.', NULL, NULL, 'Chữ t trong mortgage không được phát âm; trả hết tiền mua nhà dùng pay off.', 'We finally paid off our mortgage last spring.', NULL, 'Mùa xuân năm ngoái, chúng tôi cuối cùng đã trả hết khoản vay mua nhà.', '{"wordId":"mortgage","ukIpa":"/ˈmɔːɡɪdʒ/","usIpa":"/ˈmɔːrɡɪdʒ/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"A property loan secured against the property itself.","vi":"khoản vay thế chấp mua nhà; tiền thế chấp"},{"pos":"v.","en":"To borrow money using property as security.","vi":"cầm cố; thế chấp tài sản để vay tiền"}],"examples":[{"en":"We finally paid off our mortgage last spring.","vi":"Mùa xuân năm ngoái, chúng tôi cuối cùng đã trả hết khoản vay mua nhà.","audioKind":"ex"},{"en":"Rising interest rates can increase mortgage payments, leaving households with less money for other essential expenses.","vi":"Lãi suất tăng có thể làm tăng các khoản trả góp thế chấp, khiến các gia đình còn ít tiền hơn cho các chi phí thiết yếu khác.","audioKind":"ex2"}],"collocations":[{"en":"take out a mortgage","vi":"vay thế chấp mua nhà"},{"en":"pay off a mortgage","vi":"trả hết tiền thế chấp"},{"en":"mortgage repayments","vi":"khoản trả góp thế chấp"},{"en":"mortgage interest rates","vi":"lãi suất thế chấp"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chữ t trong mortgage không được phát âm; trả hết tiền mua nhà dùng pay off.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_decline', 'en-b2-53', 'decline', '/dɪˈklaɪn/', 'B2', 'giảm sút; suy giảm; sự suy giảm; sự sụt giảm; từ chối; khéo léo từ chối', 'v.', 'declining (adj.)', 'Đồng nghĩa: decrease, deteriorate, refuse · Trái nghĩa: increase, accept', 'Sự suy giảm dùng decline in; việc từ chối làm gì dùng decline to do.', 'I thanked her for dinner but declined the invitation.', NULL, 'Tôi cảm ơn cô ấy vì bữa tối nhưng đã từ chối lời mời.', '{"wordId":"decline","ukIpa":"/dɪˈklaɪn/","usIpa":"/dɪˈklaɪn/","cefr":"B2","topic":"economy","senses":[{"pos":"v.","en":"To become smaller, weaker, or less successful.","vi":"giảm sút; suy giảm"},{"pos":"n.","en":"A reduction in amount, strength, quality, or importance.","vi":"sự suy giảm; sự sụt giảm"},{"pos":"v.","en":"To politely refuse an offer, invitation, or request.","vi":"từ chối; khéo léo từ chối"}],"examples":[{"en":"I thanked her for dinner but declined the invitation.","vi":"Tôi cảm ơn cô ấy vì bữa tối nhưng đã từ chối lời mời.","audioKind":"ex"},{"en":"As public transport improves, private car use may decline, reducing congestion and air pollution in urban areas.","vi":"Khi giao thông công cộng được cải thiện, việc sử dụng ô tô cá nhân có thể giảm xuống, từ đó làm giảm tình trạng tắc nghẽn và ô nhiễm không khí ở các khu đô thị.","audioKind":"ex2"}],"collocations":[{"en":"a sharp decline","vi":"sự sụt giảm mạnh"},{"en":"a decline in sales","vi":"sự sụt giảm doanh số"},{"en":"decline an invitation","vi":"từ chối lời mời"},{"en":"decline to comment","vi":"từ chối bình luận"}],"wordFamily":["declining (adj.)"],"synonyms":["decrease","deteriorate","refuse"],"antonyms":["increase","accept"],"tipVi":"Sự suy giảm dùng decline in; việc từ chối làm gì dùng decline to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_triple', 'en-b2-53', 'triple', '/ˈtrɪpəl/', 'B2', 'gấp ba; gồm ba phần; tăng lên gấp ba', 'adj.', NULL, 'Đồng nghĩa: threefold', 'triple có nghĩa là trở thành gấp ba lần so với ban đầu, tức là tăng thêm hai lần.', 'The hotel charges triple the price during holidays.', NULL, 'Khách sạn tính giá gấp ba lần vào các dịp nghỉ lễ.', '{"wordId":"triple","ukIpa":"/ˈtrɪpəl/","usIpa":"/ˈtrɪpəl/","cefr":"B2","topic":"economy","senses":[{"pos":"adj.","en":"Three times as much, or consisting of three parts.","vi":"gấp ba; gồm ba phần"},{"pos":"v.","en":"To become three times as much, or make something so.","vi":"tăng lên gấp ba"}],"examples":[{"en":"The hotel charges triple the price during holidays.","vi":"Khách sạn tính giá gấp ba lần vào các dịp nghỉ lễ.","audioKind":"ex"},{"en":"Demand for renewable energy could triple as governments introduce stricter limits on carbon emissions.","vi":"Nhu cầu về năng lượng tái tạo có thể tăng gấp ba khi các chính phủ áp dụng các giới hạn nghiêm ngặt hơn đối với lượng khí thải carbon.","audioKind":"ex2"}],"collocations":[{"en":"triple the cost","vi":"gấp ba chi phí"},{"en":"triple room","vi":"phòng ba người"},{"en":"triple in size","vi":"tăng gấp ba về quy mô"},{"en":"triple glazing","vi":"kính ba lớp"}],"wordFamily":[],"synonyms":["threefold"],"antonyms":[],"tipVi":"triple có nghĩa là trở thành gấp ba lần so với ban đầu, tức là tăng thêm hai lần.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_segment', 'en-b2-53', 'segment', '/ˈseɡmənt/', 'B2', 'phần; đoạn; múi (trái cây); chia thành phần; phân khúc', 'n.', 'segmentation (n.), segmented (adj.)', 'Đồng nghĩa: section, portion', 'Danh từ trọng âm rơi vào âm tiết đầu; động từ đọc là /seɡˈment/.', 'He offered me a juicy segment of orange.', NULL, 'Anh ấy đưa cho tôi một múi cam mọng nước.', '{"wordId":"segment","ukIpa":"/ˈseɡmənt/","usIpa":"/ˈseɡmənt/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"one part of something divided into separate sections","vi":"phần; đoạn; múi (trái cây)"},{"pos":"v.","en":"to divide something into separate parts or groups","vi":"chia thành phần; phân khúc"}],"examples":[{"en":"He offered me a juicy segment of orange.","vi":"Anh ấy đưa cho tôi một múi cam mọng nước.","audioKind":"ex"},{"en":"Companies often segment their customers by age to develop more effective advertising strategies.","vi":"Các công ty thường phân khúc khách hàng theo độ tuổi để xây dựng các chiến lược quảng cáo hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"market segment","vi":"phân khúc thị trường"},{"en":"orange segment","vi":"múi cam"},{"en":"segment customers","vi":"phân khúc khách hàng"}],"wordFamily":["segmentation (n.)","segmented (adj.)"],"synonyms":["section","portion"],"antonyms":[],"tipVi":"Danh từ trọng âm rơi vào âm tiết đầu; động từ đọc là /seɡˈment/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_interest-free', 'en-b2-53', 'interest-free', '/ˌɪntrəst ˈfriː/', 'B2', 'không tính lãi; miễn lãi', 'adj.', 'interest (n.)', NULL, 'Miễn lãi không có nghĩa là miễn phí: tiền gốc vẫn phải được hoàn trả.', 'We bought our sofa with an interest-free loan.', NULL, 'Chúng tôi đã mua chiếc ghế sofa bằng một khoản vay không tính lãi.', '{"wordId":"interest-free","ukIpa":"/ˌɪntrəst ˈfriː/","usIpa":"/ˌɪntrəst ˈfriː/","cefr":"B2","topic":"economy","senses":[{"pos":"adj.","en":"Requiring no interest payments on borrowed money.","vi":"không tính lãi; miễn lãi"}],"examples":[{"en":"We bought our sofa with an interest-free loan.","vi":"Chúng tôi đã mua chiếc ghế sofa bằng một khoản vay không tính lãi.","audioKind":"ex"},{"en":"Interest-free loans can help students cover living expenses without increasing their financial burden through interest charges.","vi":"Các khoản vay không tính lãi có thể giúp sinh viên chi trả sinh hoạt phí mà không làm tăng gánh nặng tài chính từ tiền lãi.","audioKind":"ex2"}],"collocations":[{"en":"interest-free loan","vi":"khoản vay không tính lãi"},{"en":"interest-free credit","vi":"tín dụng miễn lãi"},{"en":"interest-free period","vi":"thời gian miễn lãi"}],"wordFamily":["interest (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Miễn lãi không có nghĩa là miễn phí: tiền gốc vẫn phải được hoàn trả.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_soar', 'en-b2-53', 'soar', '/sɔːr/', 'B2', 'tăng vọt; vọt lên rất cao; bay vút lên; lượn', 'v.', 'soaring (adj.)', 'Đồng nghĩa: rocket, surge · Trái nghĩa: plummet', 'Khi chỉ giá cả tăng mạnh thì đây là nội động từ, không cộng trực tiếp tân ngữ.', 'Electricity bills soared during the unusually cold winter.', NULL, 'Hóa đơn tiền điện tăng vọt trong mùa đông lạnh giá bất thường đó.', '{"wordId":"soar","ukIpa":"/sɔː/","usIpa":"/sɔːr/","cefr":"B2","topic":"economy","senses":[{"pos":"v.","en":"to increase quickly to a very high level","vi":"tăng vọt; vọt lên rất cao"},{"pos":"v.","en":"to fly high in the air, often without moving wings","vi":"bay vút lên; lượn"}],"examples":[{"en":"Electricity bills soared during the unusually cold winter.","vi":"Hóa đơn tiền điện tăng vọt trong mùa đông lạnh giá bất thường đó.","audioKind":"ex"},{"en":"Housing prices may soar when population growth exceeds the supply of affordable homes in major cities.","vi":"Giá nhà có thể tăng vọt khi tốc độ tăng trưởng dân số vượt quá nguồn cung nhà ở vừa túi tiền tại các thành phố lớn.","audioKind":"ex2"}],"collocations":[{"en":"soaring prices","vi":"giá cả leo thang"},{"en":"soar above","vi":"bay lượn bên trên"},{"en":"soar to record levels","vi":"tăng vọt lên mức kỷ lục"}],"wordFamily":["soaring (adj.)"],"synonyms":["rocket","surge"],"antonyms":["plummet"],"tipVi":"Khi chỉ giá cả tăng mạnh thì đây là nội động từ, không cộng trực tiếp tân ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_default', 'en-b2-53', 'default', '/dɪˈfɔːlt/', 'B2', 'cài đặt mặc định được dùng tự động trừ khi chọn lựa khác; sự vỡ nợ, sự không trả được nợ hoặc không thực hiện nghĩa vụ pháp lý; bỏ bê, không trả nợ hoặc không thực hiện nghĩa vụ', 'n.', 'defaulter (n.)', NULL, 'Cụm từ by default có nghĩa là theo mặc định; còn vỡ nợ khoản vay dùng default on a loan.', 'This app uses a dark background by default.', NULL, 'Ứng dụng này sử dụng nền tối làm cài đặt mặc định.', '{"wordId":"default","ukIpa":"/dɪˈfɔːlt/","usIpa":"/dɪˈfɔːlt/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"a setting used automatically unless you choose another","vi":"cài đặt mặc định được dùng tự động trừ khi chọn lựa khác"},{"pos":"n.","en":"failure to pay a debt or fulfil a legal obligation","vi":"sự vỡ nợ, sự không trả được nợ hoặc không thực hiện nghĩa vụ pháp lý"},{"pos":"v.","en":"to fail to pay a debt or meet an obligation","vi":"bỏ bê, không trả nợ hoặc không thực hiện nghĩa vụ"}],"examples":[{"en":"This app uses a dark background by default.","vi":"Ứng dụng này sử dụng nền tối làm cài đặt mặc định.","audioKind":"ex"},{"en":"Borrowers are more likely to default on their loans when unemployment rises and household incomes fall.","vi":"Người đi vay có xu hướng vỡ nợ cao hơn khi tỷ lệ thất nghiệp tăng và thu nhập hộ gia đình giảm.","audioKind":"ex2"}],"collocations":[{"en":"by default","vi":"theo mặc định"},{"en":"default setting","vi":"cài đặt mặc định"},{"en":"default on a loan","vi":"vỡ nợ khoản vay"},{"en":"debt default","vi":"vỡ nợ quốc gia"}],"wordFamily":["defaulter (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ by default có nghĩa là theo mặc định; còn vỡ nợ khoản vay dùng default on a loan.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exceed', 'en-b2-53', 'exceed', '/ɪkˈsiːd/', 'B2', 'vượt quá; vượt mức', 'v.', 'excess (n.), excessive (adj.), excessively (adv.)', 'Đồng nghĩa: surpass, outstrip', 'Là ngoại động từ, exceeding trực tiếp nối với số lượng hoặc giới hạn mà không cần dùng từ than.', 'This suitcase must not exceed the airline''s weight limit.', NULL, 'Chiếc vali này không được vượt quá giới hạn trọng lượng của hãng hàng không.', '{"wordId":"exceed","ukIpa":"/ɪkˈsiːd/","usIpa":"/ɪkˈsiːd/","cefr":"B2","topic":"economy","senses":[{"pos":"v.","en":"to be greater than a particular amount, limit, or expectation","vi":"vượt quá; vượt mức"}],"examples":[{"en":"This suitcase must not exceed the airline''s weight limit.","vi":"Chiếc vali này không được vượt quá giới hạn trọng lượng của hãng hàng không.","audioKind":"ex"},{"en":"Demand for affordable housing continues to exceed supply in many rapidly growing cities around the world.","vi":"Nhu cầu về nhà ở giá rẻ vẫn tiếp tục vượt quá nguồn cung ở nhiều thành phố đang phát triển nhanh trên khắp thế giới.","audioKind":"ex2"}],"collocations":[{"en":"exceed expectations","vi":"vượt 3kỳ vọng"},{"en":"exceed the limit","vi":"vượt quá giới hạn"},{"en":"exceed demand","vi":"vượt quá nhu cầu"},{"en":"exceed the budget","vi":"vượt quá ngân sách"}],"wordFamily":["excess (n.)","excessive (adj.)","excessively (adv.)"],"synonyms":["surpass","outstrip"],"antonyms":[],"tipVi":"Là ngoại động từ, exceeding trực tiếp nối với số lượng hoặc giới hạn mà không cần dùng từ than.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wealthy', 'en-b2-53', 'wealthy', '/ˈwelθi/', 'B2', 'giàu có; phú quý', 'adj.', 'wealth (n.)', 'Đồng nghĩa: rich, affluent · Trái nghĩa: poor', 'the wealthy chỉ nhóm người giàu; wealthy bản thân là tính từ.', 'A wealthy neighbour donated new equipment to our playground.', NULL, 'Một người hàng xóm giàu có đã tài trợ thiết bị mới cho sân chơi của chúng tôi.', '{"wordId":"wealthy","ukIpa":"/ˈwelθi/","usIpa":"/ˈwelθi/","cefr":"B2","topic":"economy","senses":[{"pos":"adj.","en":"Having a large amount of money or valuable possessions.","vi":"giàu có; phú quý"}],"examples":[{"en":"A wealthy neighbour donated new equipment to our playground.","vi":"Một người hàng xóm giàu có đã tài trợ thiết bị mới cho sân chơi của chúng tôi.","audioKind":"ex"},{"en":"Wealthy countries can support global development by investing in clean energy projects in poorer regions.","vi":"Các quốc gia giàu có có thể hỗ trợ sự phát triển toàn cầu bằng cách đầu tư vào các dự án năng lượng sạch tại những vùng nghèo hơn.","audioKind":"ex2"}],"collocations":[{"en":"wealthy family","vi":"gia đình giàu có"},{"en":"wealthy countries","vi":"các quốc gia giàu có"},{"en":"wealthy individuals","vi":"những cá nhân giàu có"}],"wordFamily":["wealth (n.)"],"synonyms":["rich","affluent"],"antonyms":["poor"],"tipVi":"the wealthy chỉ nhóm người giàu; wealthy bản thân là tính từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_capacity', 'en-b2-53', 'capacity', '/kəˈpæsəti/', 'B2', 'dung tích; sức chứa; năng lực; khả năng sản xuất; tư cách; vai trò', 'n.', NULL, NULL, 'Dùng capacity to do để chỉ năng lực làm gì; dùng in one''s capacity as để chỉ tư cách/vai trò.', 'This small lift has a capacity of six people.', NULL, 'Chiếc thang máy nhỏ này có sức chứa tối đa sáu người.', '{"wordId":"capacity","ukIpa":"/kəˈpæsəti/","usIpa":"/kəˈpæsəti/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"the maximum amount something can hold or accommodate","vi":"dung tích; sức chứa"},{"pos":"n.","en":"the ability or resources to do or produce something","vi":"năng lực; khả năng sản xuất"},{"pos":"n.","en":"a particular role in which someone acts","vi":"tư cách; vai trò"}],"examples":[{"en":"This small lift has a capacity of six people.","vi":"Chiếc thang máy nhỏ này có sức chứa tối đa sáu người.","audioKind":"ex"},{"en":"Investment in renewable energy can expand electricity generation capacity while reducing dependence on imported fossil fuels.","vi":"Đầu tư vào năng lượng tái tạo có thể mở rộng năng lực phát điện đồng thời giảm bớt sự phụ thuộc vào nhiên liệu hóa thạch nhập khẩu.","audioKind":"ex2"}],"collocations":[{"en":"seating capacity","vi":"sức chứa chỗ ngồi"},{"en":"production capacity","vi":"năng lực sản xuất"},{"en":"capacity to learn","vi":"năng lực học tập"},{"en":"in a professional capacity","vi":"với tư cách chuyên môn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dùng capacity to do để chỉ năng lực làm gì; dùng in one''s capacity as để chỉ tư cách/vai trò.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_budget', 'en-b2-53', 'budget', '/ˈbʌdʒɪt/', 'B2', 'ngân sách; khoản kinh phí; lập ngân sách; tính toán chi tiêu; giá rẻ; tiết kiệm', 'n.', 'budgeting (n.), budgetary (adj.)', NULL, 'budget for đi với chi phí dự kiến; on a budget có nghĩa là tài chính có hạn.', 'We have a small budget for our weekend trip.', NULL, 'Chúng tôi có một khoản ngân sách hạn hẹp cho chuyến đi cuối tuần.', '{"wordId":"budget","ukIpa":"/ˈbʌdʒɪt/","usIpa":"/ˈbʌdʒɪt/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"A plan for spending money, or the amount available.","vi":"ngân sách; khoản kinh phí"},{"pos":"v.","en":"To plan how much money to spend on particular things.","vi":"lập ngân sách; tính toán chi tiêu"},{"pos":"adj.","en":"Low in price compared with similar products or services.","vi":"giá rẻ; tiết kiệm"}],"examples":[{"en":"We have a small budget for our weekend trip.","vi":"Chúng tôi có một khoản ngân sách hạn hẹp cho chuyến đi cuối tuần.","audioKind":"ex"},{"en":"Local governments should allocate a larger share of their budget to maintaining public transport systems.","vi":"Chính quyền địa phương nên phân bổ một tỷ lệ lớn hơn từ ngân sách của họ để duy trì hệ thống giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"on a tight budget","vi":"với ngân sách eo hẹp"},{"en":"within budget","vi":"trong phạm vi ngân sách"},{"en":"budget for expenses","vi":"lên ngân sách cho các khoản chi"},{"en":"budget accommodation","vi":"nơi lưu trú giá rẻ"}],"wordFamily":["budgeting (n.)","budgetary (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"budget for đi với chi phí dự kiến; on a budget có nghĩa là tài chính có hạn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bankrupt', 'en-b2-53', 'bankrupt', '/ˈbæŋkrʌpt/', 'B2', 'vỡ nợ; phá sản; làm cho phá sản; người phá sản', 'adj.', 'bankruptcy (n.)', 'Đồng nghĩa: insolvent · Trái nghĩa: solvent', 'thường nói go bankrupt; danh từ "phá sản" là bankruptcy.', 'The little furniture shop went bankrupt last winter.', NULL, 'Cửa hàng đồ nội thất nhỏ đã phá sản vào mùa đông năm ngoái.', '{"wordId":"bankrupt","ukIpa":"/ˈbæŋkrʌpt/","usIpa":"/ˈbæŋkrʌpt/","cefr":"B2","topic":"economy","senses":[{"pos":"adj.","en":"legally unable to pay the debts you owe","vi":"vỡ nợ; phá sản"},{"pos":"v.","en":"to cause a person or business to become unable to pay debts","vi":"làm cho phá sản"},{"pos":"n.","en":"a person legally declared unable to pay their debts","vi":"người phá sản"}],"examples":[{"en":"The little furniture shop went bankrupt last winter.","vi":"Cửa hàng đồ nội thất nhỏ đã phá sản vào mùa đông năm ngoái.","audioKind":"ex"},{"en":"Small businesses may go bankrupt if rising energy costs are combined with a prolonged decline in consumer demand.","vi":"Các doanh nghiệp nhỏ có thể phá sản nếu chi phí năng lượng tăng kết hợp với sự suy giảm kéo dài của nhu cầu tiêu dùng.","audioKind":"ex2"}],"collocations":[{"en":"go bankrupt","vi":"phá sản"},{"en":"declare someone bankrupt","vi":"tuyên bố ai đó phá sản"},{"en":"bankrupt company","vi":"công ty phá sản"}],"wordFamily":["bankruptcy (n.)"],"synonyms":["insolvent"],"antonyms":["solvent"],"tipVi":"thường nói go bankrupt; danh từ \"phá sản\" là bankruptcy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wholesaler', 'en-b2-53', 'wholesaler', '/ˈhoʊlseɪlər/', 'B2', 'nhà bán buôn; doanh nghiệp bán sỉ', 'n.', 'wholesale (adj.), wholesale (adv.)', 'Trái nghĩa: retailer', 'Từ wholesaler chủ yếu cung cấp hàng hóa số lượng lớn cho các tiểu thương, không bán lẻ trực tiếp.', 'Our local wholesaler delivers fresh fruit to shops every morning.', NULL, 'Nhà bán buôn địa phương của chúng tôi giao trái cây tươi cho các cửa hàng mỗi buổi sáng.', '{"wordId":"wholesaler","ukIpa":"/ˈhəʊlseɪlə/","usIpa":"/ˈhoʊlseɪlər/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"a business selling large quantities of goods mainly to retailers","vi":"nhà bán buôn; doanh nghiệp bán sỉ"}],"examples":[{"en":"Our local wholesaler delivers fresh fruit to shops every morning.","vi":"Nhà bán buôn địa phương của chúng tôi giao trái cây tươi cho các cửa hàng mỗi buổi sáng.","audioKind":"ex"},{"en":"Small retailers often depend on a wholesaler to obtain goods at competitive prices.","vi":"Các nhà bán lẻ nhỏ thường phụ thuộc vào nhà bán buôn để mua hàng với giá cả cạnh tranh.","audioKind":"ex2"}],"collocations":[{"en":"food wholesaler","vi":"nhà bán buôn thực phẩm"},{"en":"buy from a wholesaler","vi":"mua từ nhà bán buôn"},{"en":"a wholesale supplier","vi":"nhà cung cấp bán sỉ"}],"wordFamily":["wholesale (adj.)","wholesale (adv.)"],"synonyms":[],"antonyms":["retailer"],"tipVi":"Từ wholesaler chủ yếu cung cấp hàng hóa số lượng lớn cho các tiểu thương, không bán lẻ trực tiếp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_earnings', 'en-b2-53', 'earnings', '/ˈɝːnɪŋz/', 'B2', 'tiền kiếm được, thu nhập (tiền nhận được từ việc làm việc); lợi nhuận, doanh thu (lợi nhuận mà công ty thu được trong một khoảng thời gian nhất định)', 'n.', 'earn (v.), earner (n.)', 'Đồng nghĩa: income', 'Là danh từ số nhiều tận cùng bằng "-s", khi làm chủ ngữ thì động từ đi kèm phải chia ở số nhiều.', 'He saved half his earnings to buy a bicycle.', NULL, 'Anh ấy đã dành dụm một nửa thu nhập của mình để mua một chiếc xe đạp.', '{"wordId":"earnings","ukIpa":"/ˈɜːnɪŋz/","usIpa":"/ˈɝːnɪŋz/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"money received for doing work","vi":"tiền kiếm được, thu nhập (tiền nhận được từ việc làm việc)"},{"pos":"n.","en":"profits made by a company during a particular period","vi":"lợi nhuận, doanh thu (lợi nhuận mà công ty thu được trong một khoảng thời gian nhất định)"}],"examples":[{"en":"He saved half his earnings to buy a bicycle.","vi":"Anh ấy đã dành dụm một nửa thu nhập của mình để mua một chiếc xe đạp.","audioKind":"ex"},{"en":"Workers with unstable earnings may struggle to afford housing, even when average wages in the economy are rising.","vi":"Những người lao động có thu nhập bấp bênh có thể gặp khó khăn trong việc trang trải nhà ở, ngay cả khi mức lương trung bình trong nền kinh tế đang tăng lên.","audioKind":"ex2"}],"collocations":[{"en":"annual earnings","vi":"thu nhập hàng năm"},{"en":"average earnings","vi":"thu nhập trung bình"},{"en":"company earnings","vi":"lợi nhuận công ty"},{"en":"earnings growth","vi":"sự tăng trưởng thu nhập"}],"wordFamily":["earn (v.)","earner (n.)"],"synonyms":["income"],"antonyms":[],"tipVi":"Là danh từ số nhiều tận cùng bằng \"-s\", khi làm chủ ngữ thì động từ đi kèm phải chia ở số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_withdraw', 'en-b2-53', 'withdraw', '/wɪðˈdrɔː/', 'B2', 'rút tiền (từ tài khoản ngân hàng); rút lui; rời khỏi; rút khỏi; thu hồi; rút lại (lời nói, đề nghị hoặc sự hỗ trợ)', 'v.', 'withdrawal (n.), withdrawn (adj.)', 'Trái nghĩa: deposit', 'Động từ này có dạng quá khứ là withdrew và quá khứ phân từ là withdrawn; khi nói rút lui khỏi cái gì thường dùng giới từ from.', 'I need to withdraw some cash before the market closes.', NULL, 'Tôi cần rút một ít tiền mặt trước khi chợ đóng cửa.', '{"wordId":"withdraw","ukIpa":"/wɪðˈdrɔː/","usIpa":"/wɪðˈdrɔː/","cefr":"B2","topic":"economy","senses":[{"pos":"v.","en":"To take money out of a bank account","vi":"rút tiền (từ tài khoản ngân hàng)"},{"pos":"v.","en":"To leave an activity or move away from a place","vi":"rút lui; rời khỏi; rút khỏi"},{"pos":"v.","en":"To remove something offered or take back a statement","vi":"thu hồi; rút lại (lời nói, đề nghị hoặc sự hỗ trợ)"}],"examples":[{"en":"I need to withdraw some cash before the market closes.","vi":"Tôi cần rút một ít tiền mặt trước khi chợ đóng cửa.","audioKind":"ex"},{"en":"Governments may withdraw financial support from industries that repeatedly fail to meet environmental standards.","vi":"Chính phủ có thể rút tài trợ đối với các ngành công nghiệp liên tục không đáp ứng được các tiêu chuẩn môi trường.","audioKind":"ex2"}],"collocations":[{"en":"withdraw cash","vi":"rút tiền mặt"},{"en":"withdraw from a competition","vi":"rút khỏi cuộc thi"},{"en":"withdraw an application","vi":"rút lại đơn xin"},{"en":"withdraw support","vi":"rút lại sự hỗ trợ"}],"wordFamily":["withdrawal (n.)","withdrawn (adj.)"],"synonyms":[],"antonyms":["deposit"],"tipVi":"Động từ này có dạng quá khứ là withdrew và quá khứ phân từ là withdrawn; khi nói rút lui khỏi cái gì thường dùng giới từ from.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rental', 'en-b2-53', 'rental', '/ˈrentəl/', 'B2', 'hành động cho thuê; khoản tiền thuê; thuộc về cho thuê; có sẵn để cho thuê; nhà cho thuê; xe cho thuê; vật phẩm cho thuê', 'n.', 'rent (v.), rent (n.), renter (n.)', NULL, 'Từ rent thường dùng để chỉ tiền thuê; rental còn có thể chỉ dịch vụ cho thuê hoặc đóng vai trò là tính từ.', 'Bike rental includes a helmet and a sturdy lock.', NULL, 'Dịch vụ thuê xe đạp đã bao gồm mũ bảo hiểm và một ổ khóa chắc chắn.', '{"wordId":"rental","ukIpa":"/ˈrentəl/","usIpa":"/ˈrentəl/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"The act of renting something, or the money paid for it","vi":"hành động cho thuê; khoản tiền thuê"},{"pos":"adj.","en":"Relating to renting, or available to rent","vi":"thuộc về cho thuê; có sẵn để cho thuê"},{"pos":"n.","en":"A house, vehicle, or other item that someone rents","vi":"nhà cho thuê; xe cho thuê; vật phẩm cho thuê"}],"examples":[{"en":"Bike rental includes a helmet and a sturdy lock.","vi":"Dịch vụ thuê xe đạp đã bao gồm mũ bảo hiểm và một ổ khóa chắc chắn.","audioKind":"ex"},{"en":"High rental costs can force young workers to live far from major employment centres.","vi":"Chi phí thuê nhà đắt đỏ có thể buộc các lao động trẻ phải sống xa các trung tâm việc làm lớn.","audioKind":"ex2"}],"collocations":[{"en":"car rental","vi":"thuê xe ô tô"},{"en":"rental agreement","vi":"hợp đồng thuê nhà"},{"en":"rental income","vi":"thu nhập từ cho thuê"},{"en":"rental property","vi":"bất động sản cho thuê"}],"wordFamily":["rent (v.)","rent (n.)","renter (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ rent thường dùng để chỉ tiền thuê; rental còn có thể chỉ dịch vụ cho thuê hoặc đóng vai trò là tính từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sponsorship', 'en-b2-53', 'sponsorship', '/ˈspɑːnsərʃɪp/', 'B2', 'sự tài trợ; việc hỗ trợ kinh phí', 'n.', 'sponsor (n.), sponsor (v.)', 'Đồng nghĩa: funding, backing', 'Trọng tâm là cung cấp hỗ trợ tài chính v.v., không đồng nghĩa với việc trực tiếp tổ chức sự kiện.', 'Our swimming club needs sponsorship to buy new equipment.', NULL, 'Câu lạc bộ bơi lội của chúng tôi cần sự tài trợ để mua trang thiết bị mới.', '{"wordId":"sponsorship","ukIpa":"/ˈspɒnsəʃɪp/","usIpa":"/ˈspɑːnsərʃɪp/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"Financial support for an activity, often in exchange for publicity.","vi":"sự tài trợ; việc hỗ trợ kinh phí"}],"examples":[{"en":"Our swimming club needs sponsorship to buy new equipment.","vi":"Câu lạc bộ bơi lội của chúng tôi cần sự tài trợ để mua trang thiết bị mới.","audioKind":"ex"},{"en":"Corporate sponsorship allows many cultural festivals to remain affordable, although it may influence their artistic choices.","vi":"Sự tài trợ từ các doanh nghiệp giúp nhiều lễ hội văn hóa duy trì mức giá phải chăng, dù nó có thể ảnh hưởng đến các lựa chọn tính nghệ thuật của họ.","audioKind":"ex2"}],"collocations":[{"en":"corporate sponsorship","vi":"sự tài trợ từ doanh nghiệp"},{"en":"secure sponsorship","vi":"đạt được tài trợ"},{"en":"sponsorship deal","vi":"thỏa thuận tài trợ"}],"wordFamily":["sponsor (n.)","sponsor (v.)"],"synonyms":["funding","backing"],"antonyms":[],"tipVi":"Trọng tâm là cung cấp hỗ trợ tài chính v.v., không đồng nghĩa với việc trực tiếp tổ chức sự kiện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_incentive', 'en-b2-53', 'incentive', '/ɪnˈsentɪv/', 'B2', 'động lực; sự khuyến khích; tiền thưởng khích lệ', 'n.', 'incentivise (v.)', 'Đồng nghĩa: motivation, inducement · Trái nghĩa: disincentive', 'Thường dùng cấu trúc incentive to do sth để diễn tả động lực thực hiện một việc gì đó.', 'The free lunch gave us an incentive to stay.', NULL, 'Bữa trưa miễn phí tạo cho chúng tôi động lực để ở lại.', '{"wordId":"incentive","ukIpa":"/ɪnˈsentɪv/","usIpa":"/ɪnˈsentɪv/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"something that encourages someone to act or work harder","vi":"động lực; sự khuyến khích; tiền thưởng khích lệ"}],"examples":[{"en":"The free lunch gave us an incentive to stay.","vi":"Bữa trưa miễn phí tạo cho chúng tôi động lực để ở lại.","audioKind":"ex"},{"en":"Governments can offer financial incentives to encourage households to install solar panels and reduce energy consumption.","vi":"Chính phủ có thể đưa ra các biện pháp hỗ trợ tài chính nhằm khuyến khích các hộ gia đình lắp đặt pin năng lượng mặt trời và giảm mức tiêu thụ năng lượng.","audioKind":"ex2"}],"collocations":[{"en":"financial incentive","vi":"ưu đãi tài chính; hỗ trợ tài chính"},{"en":"provide an incentive","vi":"tạo động lực"},{"en":"incentive to work","vi":"động lực làm việc"}],"wordFamily":["incentivise (v.)"],"synonyms":["motivation","inducement"],"antonyms":["disincentive"],"tipVi":"Thường dùng cấu trúc incentive to do sth để diễn tả động lực thực hiện một việc gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_domestic', 'en-b2-53', 'domestic', '/dəˈmestɪk/', 'B2', 'trong nước; nội địa; thuộc gia đình; việc nhà; thuần hóa; gia súc', 'adj.', 'domestically (adv.), domesticate (v.), domestication (n.)', 'Trái nghĩa: international, wild', 'Trái nghĩa với "international" để chỉ trong nước; trái nghĩa với "wild" để chỉ gia súc/động vật nhà.', 'We took a domestic flight to the northern coast.', NULL, 'Chúng tôi đã đi chuyến bay nội địa đến bờ biển phía bắc.', '{"wordId":"domestic","ukIpa":"/dəˈmestɪk/","usIpa":"/dəˈmestɪk/","cefr":"B2","topic":"economy","senses":[{"pos":"adj.","en":"relating to activities within a particular country","vi":"trong nước; nội địa"},{"pos":"adj.","en":"relating to the home, family, or household tasks","vi":"thuộc gia đình; việc nhà"},{"pos":"adj.","en":"kept by people rather than living in the wild","vi":"thuần hóa; gia súc"}],"examples":[{"en":"We took a domestic flight to the northern coast.","vi":"Chúng tôi đã đi chuyến bay nội địa đến bờ biển phía bắc.","audioKind":"ex"},{"en":"Investment in domestic food production can reduce a country''s dependence on imports and strengthen its economy.","vi":"Đầu tư vào sản xuất lương thực trong nước có thể làm giảm sự phụ thuộc của một quốc gia vào hàng nhập khẩu và củng cố nền kinh tế.","audioKind":"ex2"}],"collocations":[{"en":"domestic market","vi":"thị trường nội địa"},{"en":"domestic flight","vi":"chuyến bay nội địa"},{"en":"domestic chores","vi":"công việc nhà"},{"en":"domestic animals","vi":"động vật thuần hóa"}],"wordFamily":["domestically (adv.)","domesticate (v.)","domestication (n.)"],"synonyms":[],"antonyms":["international","wild"],"tipVi":"Trái nghĩa với \"international\" để chỉ trong nước; trái nghĩa với \"wild\" để chỉ gia súc/động vật nhà.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_53_1', 'en-b2-53', 'Cách dùng “withdraw” (v.) — rút tiền (từ tài khoản ngân hàng)', 'withdraw cash  ·  withdraw from a competition  ·  withdraw an application', 'Động từ này có dạng quá khứ là withdrew và quá khứ phân từ là withdrawn; khi nói rút lui khỏi cái gì thường dùng giới từ from.', 'Họ từ (Word Family): withdrawal (n.), withdrawn (adj.) | Trái nghĩa: deposit', '[{"hanzi":"I need to withdraw some cash before the market closes.","pinyin":"","meaning":"Tôi cần rút một ít tiền mặt trước khi chợ đóng cửa."},{"hanzi":"Governments may withdraw financial support from industries that repeatedly fail to meet environmental standards.","pinyin":"","meaning":"Chính phủ có thể rút tài trợ đối với các ngành công nghiệp liên tục không đáp ứng được các tiêu chuẩn môi trường."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_53_2', 'en-b2-53', 'Cách dùng “rental” (n.) — hành động cho thuê; khoản tiền thuê', 'car rental  ·  rental agreement  ·  rental income', 'Từ rent thường dùng để chỉ tiền thuê; rental còn có thể chỉ dịch vụ cho thuê hoặc đóng vai trò là tính từ.', 'Họ từ (Word Family): rent (v.), rent (n.), renter (n.)', '[{"hanzi":"Bike rental includes a helmet and a sturdy lock.","pinyin":"","meaning":"Dịch vụ thuê xe đạp đã bao gồm mũ bảo hiểm và một ổ khóa chắc chắn."},{"hanzi":"High rental costs can force young workers to live far from major employment centres.","pinyin":"","meaning":"Chi phí thuê nhà đắt đỏ có thể buộc các lao động trẻ phải sống xa các trung tâm việc làm lớn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_53_3', 'en-b2-53', 'Cách dùng “outlet” (n.) — cửa hàng; điểm bán lẻ', 'retail outlet  ·  creative outlet  ·  an outlet for frustration', 'Cụm outlet for thường chỉ phương tiện bộc lộ; trong tiếng Anh Mỹ, từ này còn có nghĩa là ổ cắm điện.', NULL, '[{"hanzi":"A new clothing outlet opened near the station yesterday.","pinyin":"","meaning":"Một cửa hàng quần áo mới đã khai trương gần nhà ga vào ngày hôm qua."},{"hanzi":"Community arts programmes provide a valuable outlet for young people to express emotions and develop confidence.","pinyin":"","meaning":"Các chương trình nghệ thuật cộng đồng mang lại kênh giải tỏa giá trị giúp người trẻ thể hiện cảm xúc và xây dựng sự tự tin."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_53_4', 'en-b2-53', 'Cách dùng “margin” (n.) — lề trang giấy; phần mép', 'a wide margin  ·  profit margin  ·  margin of error', 'Cụm by a narrow margin diễn tả việc chiến thắng hoặc đạt được điều gì với khoảng cách rất suýt soát.', 'Họ từ (Word Family): marginal (adj.), marginally (adv.) | Đồng nghĩa: edge, gap', '[{"hanzi":"Leave a wide margin for your teacher''s comments.","pinyin":"","meaning":"Hãy chừa lề giấy thật rộng để giáo viên viết lời phê."},{"hanzi":"Small retailers often operate on a narrow profit margin, making them particularly vulnerable to rising energy costs.","pinyin":"","meaning":"Các nhà bán lẻ nhỏ thường hoạt động với biên lợi nhuận thấp, điều này khiến họ đặc biệt dễ bị tổn thương trước việc chi phí năng lượng leo thang."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
