INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_53_1_4', 'ten_b2_53_1', 'mortgage', 'We finally paid off our mortgage last spring.', 'We finally paid off our mortgage last spring.', '/ˈmɔːrɡɪdʒ/', 'Mùa xuân năm ngoái, chúng tôi cuối cùng đã trả hết khoản vay mua nhà.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_53_1_5', 'ten_b2_53_1', 'decline', 'I thanked her for dinner but declined the invitation.', 'I thanked her for dinner but declined the invitation.', '/dɪˈklaɪn/', 'Tôi cảm ơn cô ấy vì bữa tối nhưng đã từ chối lời mời.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_53_1_6', 'ten_b2_53_1', 'triple', 'The hotel charges triple the price during holidays.', 'The hotel charges triple the price during holidays.', '/ˈtrɪpəl/', 'Khách sạn tính giá gấp ba lần vào các dịp nghỉ lễ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_53_1_7', 'ten_b2_53_1', 'segment', 'He offered me a juicy segment of orange.', 'He offered me a juicy segment of orange.', '/ˈseɡmənt/', 'Anh ấy đưa cho tôi một múi cam mọng nước.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_53_1_8', 'ten_b2_53_1', 'interest-free', 'We bought our sofa with an interest-free loan.', 'We bought our sofa with an interest-free loan.', '/ˌɪntrəst ˈfriː/', 'Chúng tôi đã mua chiếc ghế sofa bằng một khoản vay không tính lãi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_53_1_1', 'en-b2-53', 'ten_b2_53_1', 'listening', 'listening', 'My weekly allowance covers bus fares and occasional snacks.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã đi chuyến bay nội địa đến bờ biển phía bắc.","Hóa đơn tiền điện tăng vọt trong mùa đông lạnh giá bất thường đó.","Tôi cần rút một ít tiền mặt trước khi chợ đóng cửa.","Khoản tiền tiêu vặt hàng tuần của tôi đủ chi trả tiền xe buýt và đôi khi mua đồ ăn vặt."]'::jsonb, 3, 'My weekly allowance covers bus fares and occasional snacks. → Khoản tiền tiêu vặt hàng tuần của tôi đủ chi trả tiền xe buýt và đôi khi mua đồ ăn vặt.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_53_1_2', 'en-b2-53', 'ten_b2_53_1', 'listening', 'listening', 'A new clothing outlet opened near the station yesterday.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã mua chiếc ghế sofa bằng một khoản vay không tính lãi.","Một cửa hàng quần áo mới đã khai trương gần nhà ga vào ngày hôm qua.","Anh ấy đưa cho tôi một múi cam mọng nước.","Hãy chừa lề giấy thật rộng để giáo viên viết lời phê."]'::jsonb, 1, 'A new clothing outlet opened near the station yesterday. → Một cửa hàng quần áo mới đã khai trương gần nhà ga vào ngày hôm qua.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_53_1_3', 'en-b2-53', 'ten_b2_53_1', 'listening', 'listening', 'Leave a wide margin for your teacher''s comments.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi có một khoản ngân sách hạn hẹp cho chuyến đi cuối tuần.","Hãy chừa lề giấy thật rộng để giáo viên viết lời phê.","Chiếc thang máy nhỏ này có sức chứa tối đa sáu người.","Chúng tôi đã mua chiếc ghế sofa bằng một khoản vay không tính lãi."]'::jsonb, 1, 'Leave a wide margin for your teacher''s comments. → Hãy chừa lề giấy thật rộng để giáo viên viết lời phê.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_53_2', 'en-b2-53', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_53_2_1', 'ten_b2_53_2', 'allowance', 'A housing allowance can help essential workers afford accommodation in cities where rents are particularly high.', 'A housing allowance can help essential workers afford accommodation in cities where rents are particularly high.', '/əˈlaʊ.əns/', 'Trợ cấp nhà ở có thể giúp những lao động thiết yếu trang trải chỗ ở tại các thành phố nơi giá thuê nhà cực kỳ cao.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_53_2_2', 'ten_b2_53_2', 'outlet', 'Community arts programmes provide a valuable outlet for young people to express emotions and develop confidence.', 'Community arts programmes provide a valuable outlet for young people to express emotions and develop confidence.', '/ˈaʊtlet/', 'Các chương trình nghệ thuật cộng đồng mang lại kênh giải tỏa giá trị giúp người trẻ thể hiện cảm xúc và xây dựng sự tự tin.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_53_2_3', 'ten_b2_53_2', 'margin', 'Small retailers often operate on a narrow profit margin, making them particularly vulnerable to rising energy costs.', 'Small retailers often operate on a narrow profit margin, making them particularly vulnerable to rising energy costs.', '/ˈmɑːrdʒɪn/', 'Các nhà bán lẻ nhỏ thường hoạt động với biên lợi nhuận thấp, điều này khiến họ đặc biệt dễ bị tổn thương trước việc chi phí năng lượng leo thang.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_53_2_4', 'ten_b2_53_2', 'mortgage', 'Rising interest rates can increase mortgage payments, leaving households with less money for other essential expenses.', 'Rising interest rates can increase mortgage payments, leaving households with less money for other essential expenses.', '/ˈmɔːrɡɪdʒ/', 'Lãi suất tăng có thể làm tăng các khoản trả góp thế chấp, khiến các gia đình còn ít tiền hơn cho các chi phí thiết yếu khác.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_53_2_5', 'ten_b2_53_2', 'decline', 'As public transport improves, private car use may decline, reducing congestion and air pollution in urban areas.', 'As public transport improves, private car use may decline, reducing congestion and air pollution in urban areas.', '/dɪˈklaɪn/', 'Khi giao thông công cộng được cải thiện, việc sử dụng ô tô cá nhân có thể giảm xuống, từ đó làm giảm tình trạng tắc nghẽn và ô nhiễm không khí ở các khu đô thị.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_53_2_6', 'ten_b2_53_2', 'triple', 'Demand for renewable energy could triple as governments introduce stricter limits on carbon emissions.', 'Demand for renewable energy could triple as governments introduce stricter limits on carbon emissions.', '/ˈtrɪpəl/', 'Nhu cầu về năng lượng tái tạo có thể tăng gấp ba khi các chính phủ áp dụng các giới hạn nghiêm ngặt hơn đối với lượng khí thải carbon.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_53_2_1', 'en-b2-53', 'ten_b2_53_2', 'listening', 'listening', 'A housing allowance can help essential workers afford accommodation in cities where rents are particularly high.', NULL, 'Trong câu vừa nghe, từ “allowance” mang nghĩa nào sau đây?', '["tiền trợ cấp; tiền tiêu vặt định kỳ","nhiều mỡ; chứa nhiều chất béo","tính chính xác; độ chính xác","xe ô tô"]'::jsonb, 0, '“allowance” (/əˈlaʊ.əns/): tiền trợ cấp; tiền tiêu vặt định kỳ. Câu đầy đủ: A housing allowance can help essential workers afford accommodation in cities where rents are particularly high.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
