INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_53_4', 'en-b2-53', NULL, 'comprehensive_test', 'listening', 'We finally paid off our mortgage last spring.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hãy chừa lề giấy thật rộng để giáo viên viết lời phê.","Mùa xuân năm ngoái, chúng tôi cuối cùng đã trả hết khoản vay mua nhà.","Cửa hàng đồ nội thất nhỏ đã phá sản vào mùa đông năm ngoái.","Chúng tôi đã đi chuyến bay nội địa đến bờ biển phía bắc."]'::jsonb, 1, 'We finally paid off our mortgage last spring. → Mùa xuân năm ngoái, chúng tôi cuối cùng đã trả hết khoản vay mua nhà.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
