INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_53_6', 'en-b2-53', NULL, 'comprehensive_test', 'listening', 'The hotel charges triple the price during holidays.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một người hàng xóm giàu có đã tài trợ thiết bị mới cho sân chơi của chúng tôi.","Câu lạc bộ bơi lội của chúng tôi cần sự tài trợ để mua trang thiết bị mới.","Một cửa hàng quần áo mới đã khai trương gần nhà ga vào ngày hôm qua.","Khách sạn tính giá gấp ba lần vào các dịp nghỉ lễ."]'::jsonb, 3, 'The hotel charges triple the price during holidays. → Khách sạn tính giá gấp ba lần vào các dịp nghỉ lễ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_53_7', 'en-b2-53', NULL, 'comprehensive_test', 'listening', 'segment', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["phần; đoạn; múi (trái cây)","cấp bậc; quân hàm; địa vị","dành hết; cống hiến (thời gian, công sức, nguồn lực)","chức năng; tác dụng"]'::jsonb, 0, 'segment (/ˈseɡmənt/) → phần; đoạn; múi (trái cây); chia thành phần; phân khúc', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_53_8', 'en-b2-53', NULL, 'comprehensive_test', 'listening', 'We bought our sofa with an interest-free loan.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã mua chiếc ghế sofa bằng một khoản vay không tính lãi.","Câu lạc bộ bơi lội của chúng tôi cần sự tài trợ để mua trang thiết bị mới.","Cửa hàng đồ nội thất nhỏ đã phá sản vào mùa đông năm ngoái.","Mùa xuân năm ngoái, chúng tôi cuối cùng đã trả hết khoản vay mua nhà."]'::jsonb, 0, 'We bought our sofa with an interest-free loan. → Chúng tôi đã mua chiếc ghế sofa bằng một khoản vay không tính lãi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_53_9', 'en-b2-53', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To become smaller, weaker, or less successful.”?', '["wealthy","bankrupt","default","decline"]'::jsonb, 3, 'decline (/dɪˈklaɪn/) → giảm sút; suy giảm', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
