INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_53_18', 'en-b2-53', NULL, 'comprehensive_test', 'reading', NULL, 'A housing allowance can help essential workers afford accommodation in cities where rents are particularly high.', 'Dựa vào câu trên, từ “allowance” có nghĩa phù hợp nhất là gì?', '["tiền trợ cấp; tiền tiêu vặt định kỳ","thuộc về thành phố; đô thị","nghiêm khắc; cay nghiệt","bài tường thuật; câu chuyện"]'::jsonb, 0, 'allowance: tiền trợ cấp; tiền tiêu vặt định kỳ; hạn mức; định mức cho phép; sự châm chước; sự cân nhắc. Dịch cả câu: Trợ cấp nhà ở có thể giúp những lao động thiết yếu trang trải chỗ ở tại các thành phố nơi giá thuê nhà cực kỳ cao.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_53_19', 'en-b2-53', NULL, 'comprehensive_test', 'reading', NULL, 'Community arts programmes provide a valuable outlet for young people to express emotions and develop confidence.', 'Dựa vào câu trên, từ “outlet” có nghĩa phù hợp nhất là gì?', '["thành lập; sáng lập","cửa hàng; điểm bán lẻ","yêu mến; rất thích","mức đánh giá; điểm số; xếp hạng"]'::jsonb, 1, 'outlet: cửa hàng; điểm bán lẻ; lối thoát; phương thức giải tỏa (cảm xúc, năng lượng); lỗ thoát; cửa xả (chất lỏng hoặc khí). Dịch cả câu: Các chương trình nghệ thuật cộng đồng mang lại kênh giải tỏa giá trị giúp người trẻ thể hiện cảm xúc và xây dựng sự tự tin.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_53_20', 'en-b2-53', NULL, 'comprehensive_test', 'reading', NULL, 'Small retailers often operate on a narrow profit margin, making them particularly vulnerable to rising energy costs.', 'Dựa vào câu trên, từ “margin” có nghĩa phù hợp nhất là gì?', '["xi-rô; nước đường đặc","xác định; tìm ra","lề trang giấy; phần mép","sân hiên; ban công lớn; sân thượng"]'::jsonb, 2, 'margin: lề trang giấy; phần mép; khoảng cách; biên độ; mức chênh lệch; dư địa; tỷ suất lợi nhuận; biên lợi nhuận. Dịch cả câu: Các nhà bán lẻ nhỏ thường hoạt động với biên lợi nhuận thấp, điều này khiến họ đặc biệt dễ bị tổn thương trước việc chi phí năng lượng leo thang.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_53_21', 'en-b2-53', NULL, 'comprehensive_test', 'reading', NULL, 'Rising interest rates can increase mortgage payments, leaving households with less money for other essential expenses.', 'Dựa vào câu trên, từ “mortgage” có nghĩa phù hợp nhất là gì?', '["cuộc diễu hành; đoàn diễu hành","ở dưới; phía dưới","dốc; dốc đứng","khoản vay thế chấp mua nhà; tiền thế chấp"]'::jsonb, 3, 'mortgage: khoản vay thế chấp mua nhà; tiền thế chấp; cầm cố; thế chấp tài sản để vay tiền. Dịch cả câu: Lãi suất tăng có thể làm tăng các khoản trả góp thế chấp, khiến các gia đình còn ít tiền hơn cho các chi phí thiết yếu khác.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_53_22', 'en-b2-53', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự tài trợ; việc hỗ trợ kinh phí”', '["disgraceful","sponsorship","insult","supervise"]'::jsonb, 1, 'sự tài trợ; việc hỗ trợ kinh phí → sponsorship (/ˈspɑːnsərʃɪp/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
