INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_53_24', 'en-b2-53', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “trong nước; nội địa”', '["hurrah","appendix","impossibility","domestic"]'::jsonb, 3, 'trong nước; nội địa → domestic (/dəˈmestɪk/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-54', 'en', 'Bài 54: Kinh tế & Tài chính (3) - CEFR B2', 'CEFR B2', 'B2 · Kinh tế', '22 từ vựng Tiếng Anh CEFR B2 chủ đề kinh tế & tài chính kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4054, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_generate', 'en-b2-54', 'generate', '/ˈdʒenəreɪt/', 'B2', 'tạo ra; sinh ra; phát điện; tạo năng lượng', 'v.', 'generation (n.), generator (n.), generative (adj.)', 'Đồng nghĩa: produce, create', 'Là ngoại động từ, có thể đi kèm các tân ngữ như điện năng, thu nhập, sự quan tâm hoặc ý tưởng.', 'Our weekend bake sale generated enough money for new books.', NULL, 'Buổi bán bánh gây quỹ cuối tuần của chúng tôi đã kiếm đủ tiền mua sách mới.', '{"wordId":"generate","ukIpa":"/ˈdʒenəreɪt/","usIpa":"/ˈdʒenəreɪt/","cefr":"B2","topic":"economy","senses":[{"pos":"v.","en":"Cause something to exist or happen.","vi":"tạo ra; sinh ra"},{"pos":"v.","en":"Produce electricity, heat, or another form of energy.","vi":"phát điện; tạo năng lượng"}],"examples":[{"en":"Our weekend bake sale generated enough money for new books.","vi":"Buổi bán bánh gây quỹ cuối tuần của chúng tôi đã kiếm đủ tiền mua sách mới.","audioKind":"ex"},{"en":"Investment in renewable energy can generate employment while reducing dependence on imported fossil fuels.","vi":"Đầu tư vào năng lượng tái tạo có thể tạo ra việc làm đồng thời giảm sự phụ thuộc vào nhiên liệu hóa thạch nhập khẩu.","audioKind":"ex2"}],"collocations":[{"en":"generate electricity","vi":"phát điện"},{"en":"generate income","vi":"tạo ra thu nhập"},{"en":"generate interest","vi":"khơi gợi sự quan tâm"},{"en":"generate ideas","vi":"nảy sinh ý tưởng"}],"wordFamily":["generation (n.)","generator (n.)","generative (adj.)"],"synonyms":["produce","create"],"antonyms":[],"tipVi":"Là ngoại động từ, có thể đi kèm các tân ngữ như điện năng, thu nhập, sự quan tâm hoặc ý tưởng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ownership', 'en-b2-54', 'ownership', '/ˈoʊnərʃɪp/', 'B2', 'quyền sở hữu; ý thức trách nhiệm', 'n.', 'own (v.), owner (n.)', NULL, 'Là danh từ không đếm được; take ownership of cũng có thể mang nghĩa là chủ động gánh vác trách nhiệm.', 'She finally gained ownership of her small apartment.', NULL, 'Cô ấy cuối cùng cũng giành được quyền sở hữu căn hộ nhỏ của mình.', '{"wordId":"ownership","ukIpa":"/ˈəʊnəʃɪp/","usIpa":"/ˈoʊnərʃɪp/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"The legal right to possess something.","vi":"quyền sở hữu"},{"pos":"n.","en":"Responsibility for a task and commitment to its results.","vi":"ý thức trách nhiệm"}],"examples":[{"en":"She finally gained ownership of her small apartment.","vi":"Cô ấy cuối cùng cũng giành được quyền sở hữu căn hộ nhỏ của mình.","audioKind":"ex"},{"en":"Public ownership of essential services may help ensure equal access for people on lower incomes.","vi":"Quyền sở hữu công đối với các dịch vụ thiết yếu có thể giúp đảm bảo khả năng tiếp cận bình đẳng cho những người có thu nhập thấp hơn.","audioKind":"ex2"}],"collocations":[{"en":"private ownership","vi":"sở hữu tư nhân"},{"en":"transfer ownership","vi":"chuyển nhượng quyền sở hữu"},{"en":"home ownership","vi":"sở hữu nhà ở"},{"en":"take ownership of","vi":"chủ động gánh vác trách nhiệm"}],"wordFamily":["own (v.)","owner (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ không đếm được; take ownership of cũng có thể mang nghĩa là chủ động gánh vác trách nhiệm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_finance', 'en-b2-54', 'finance', '/ˈfaɪnæns/', 'B2', 'tài chính; quản lý tài chính; nguồn vốn; kinh phí; cấp vốn; tài trợ tiền cho việc gì', 'n.', 'financial (adj.), financially (adv.), financing (n.)', 'Đồng nghĩa: funding', 'Từ finance có thể chỉ nguồn tiền hoặc lĩnh vực tài chính; khi nói về tài chính cá nhân thường dùng số nhiều finances.', 'The bank agreed to finance our new bakery.', NULL, 'Ngân hàng đã đồng ý cấp vốn cho cửa hàng bánh mới của chúng tôi.', '{"wordId":"finance","ukIpa":"/ˈfaɪnæns/","usIpa":"/ˈfaɪnæns/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"the management of money by people, businesses, or governments","vi":"tài chính; quản lý tài chính"},{"pos":"n.","en":"money needed to support an activity or project","vi":"nguồn vốn; kinh phí"},{"pos":"v.","en":"to provide money for something","vi":"cấp vốn; tài trợ tiền cho việc gì"}],"examples":[{"en":"The bank agreed to finance our new bakery.","vi":"Ngân hàng đã đồng ý cấp vốn cho cửa hàng bánh mới của chúng tôi.","audioKind":"ex"},{"en":"Access to affordable finance allows small businesses to invest in equipment and create more local jobs.","vi":"Khả năng tiếp cận nguồn vốn với chi phí hợp lý giúp các doanh nghiệp nhỏ đầu tư vào trang thiết bị và tạo ra nhiều việc làm hơn tại địa phương.","audioKind":"ex2"}],"collocations":[{"en":"public finance","vi":"tài chính công"},{"en":"raise finance","vi":"huy động vốn"},{"en":"finance a project","vi":"tài trợ cho một dự án"},{"en":"personal finances","vi":"tình hình tài chính cá nhân"}],"wordFamily":["financial (adj.)","financially (adv.)","financing (n.)"],"synonyms":["funding"],"antonyms":[],"tipVi":"Từ finance có thể chỉ nguồn tiền hoặc lĩnh vực tài chính; khi nói về tài chính cá nhân thường dùng số nhiều finances.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_trader', 'en-b2-54', 'trader', '/ˈtreɪdər/', 'B2', 'thương nhân; tiểu thương; nhà giao dịch', 'n.', 'trade (n.), trade (v.), trading (n.)', 'Đồng nghĩa: merchant, dealer', 'Có thể chỉ người buôn bán hàng hóa vật chất, hoặc nhà đầu tư giao dịch trên thị trường tài chính.', 'A market trader arranged fresh oranges outside his stall.', NULL, 'Một người tiểu thương đã sắp xếp những quả cam tươi bên ngoài sạp hàng của mình.', '{"wordId":"trader","ukIpa":"/ˈtreɪdə/","usIpa":"/ˈtreɪdər/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"Someone who buys and sells goods or financial assets.","vi":"thương nhân; tiểu thương; nhà giao dịch"}],"examples":[{"en":"A market trader arranged fresh oranges outside his stall.","vi":"Một người tiểu thương đã sắp xếp những quả cam tươi bên ngoài sạp hàng của mình.","audioKind":"ex"},{"en":"Small traders often struggle to compete with larger retailers that can negotiate lower prices from suppliers.","vi":"Các tiểu thương nhỏ thường gặp khó khăn khi cạnh tranh với các nhà bán lẻ lớn hơn, những đơn vị có khả năng thương lượng mức giá rẻ hơn từ nhà cung cấp.","audioKind":"ex2"}],"collocations":[{"en":"market trader","vi":"người buôn bán ngoài chợ"},{"en":"currency trader","vi":"nhà giao dịch tiền tệ"},{"en":"independent trader","vi":"thương nhân độc lập"},{"en":"stock trader","vi":"nhà giao dịch chứng khoán"}],"wordFamily":["trade (n.)","trade (v.)","trading (n.)"],"synonyms":["merchant","dealer"],"antonyms":[],"tipVi":"Có thể chỉ người buôn bán hàng hóa vật chất, hoặc nhà đầu tư giao dịch trên thị trường tài chính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bid', 'en-b2-54', 'bid', '/bɪd/', 'B2', 'trả giá; đấu giá; bỏ thầu; giá bỏ thầu; mức giá đưa ra; sự nỗ lực; sự mưu cầu', 'v.', 'bidder (n.), bidding (n.)', 'Đồng nghĩa: offer, attempt', 'Khi chỉ hành động ra giá, dạng quá khứ và phân từ hai đều là bid.', 'I bid twenty pounds for the old wooden chair.', NULL, 'Tôi ra giá hai mươi bảng cho chiếc ghế gỗ cũ đó.', '{"wordId":"bid","ukIpa":"/bɪd/","usIpa":"/bɪd/","cefr":"B2","topic":"economy","senses":[{"pos":"v.","en":"To offer a price or compete formally for a contract.","vi":"trả giá; đấu giá; bỏ thầu"},{"pos":"n.","en":"An offer of money or a proposal to do work.","vi":"giá bỏ thầu; mức giá đưa ra"},{"pos":"n.","en":"An attempt to achieve or obtain something.","vi":"sự nỗ lực; sự mưu cầu"}],"examples":[{"en":"I bid twenty pounds for the old wooden chair.","vi":"Tôi ra giá hai mươi bảng cho chiếc ghế gỗ cũ đó.","audioKind":"ex"},{"en":"Several local companies submitted a bid to build affordable housing near the city''s main railway station.","vi":"Nhiều công ty địa phương đã nộp hồ sơ dự thầu để xây dựng nhà ở giá rẻ gần ga đường sắt chính của thành phố.","audioKind":"ex2"}],"collocations":[{"en":"bid for a contract","vi":"đấu thầu giành hợp đồng"},{"en":"submit a bid","vi":"nộp hồ sơ dự thầu"},{"en":"the highest bid","vi":"mức giá trả cao nhất"},{"en":"in a bid to","vi":"trong nỗ lực nhằm"}],"wordFamily":["bidder (n.)","bidding (n.)"],"synonyms":["offer","attempt"],"antonyms":[],"tipVi":"Khi chỉ hành động ra giá, dạng quá khứ và phân từ hai đều là bid.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_halve', 'en-b2-54', 'halve', '/hæv/', 'B2', 'giảm một nửa; chia đôi thành hai phần bằng nhau', 'v.', 'half (n), halved (adj)', 'Trái nghĩa: double', 'halve là động từ, trong khi half có thể dùng làm danh từ; chữ l trong từ halve là âm câm.', 'Sharing a taxi would halve the cost for each person.', NULL, 'Đi chung taxi sẽ giúp giảm một nửa chi phí cho mỗi người.', '{"wordId":"halve","ukIpa":"/hɑːv/","usIpa":"/hæv/","cefr":"B2","topic":"economy","senses":[{"pos":"v.","en":"To reduce something to half its original amount.","vi":"giảm một nửa"},{"pos":"v.","en":"To divide something into two equal parts.","vi":"chia đôi thành hai phần bằng nhau"}],"examples":[{"en":"Sharing a taxi would halve the cost for each person.","vi":"Đi chung taxi sẽ giúp giảm một nửa chi phí cho mỗi người.","audioKind":"ex"},{"en":"The city aims to halve household food waste by expanding composting services and promoting more careful shopping.","vi":"Thành phố đặt mục tiêu giảm một nửa lượng rác thải thực phẩm sinh hoạt bằng cách mở rộng dịch vụ ủ phân và thúc đẩy việc mua sắm có ý thức hơn.","audioKind":"ex2"}],"collocations":[{"en":"halve the cost","vi":"giảm một nửa chi phí"},{"en":"halve emissions","vi":"giảm một nửa lượng phát thải"},{"en":"halve a lemon","vi":"chia đôi một quả chanh"}],"wordFamily":["half (n)","halved (adj)"],"synonyms":[],"antonyms":["double"],"tipVi":"halve là động từ, trong khi half có thể dùng làm danh từ; chữ l trong từ halve là âm câm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sponsor', 'en-b2-54', 'sponsor', '/ˈspɑːnsər/', 'B2', 'nhà tài trợ; mạnh thường quân; tài trợ; bảo trợ tài chính', 'n.', 'sponsorship (n.)', 'Đồng nghĩa: backer', 'sponsor có thể là danh từ hoặc động từ; danh từ chỉ hành động tài trợ là sponsorship.', 'Our swimming club needs a sponsor for new equipment.', NULL, 'Câu lạc bộ bơi lội của chúng tôi cần một nhà tài trợ để mua thiết bị mới.', '{"wordId":"sponsor","ukIpa":"/ˈspɒnsə/","usIpa":"/ˈspɑːnsər/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"A person or organisation providing support, often in return for publicity.","vi":"nhà tài trợ; mạnh thường quân"},{"pos":"v.","en":"To support a person, event, or activity financially.","vi":"tài trợ; bảo trợ tài chính"}],"examples":[{"en":"Our swimming club needs a sponsor for new equipment.","vi":"Câu lạc bộ bơi lội của chúng tôi cần một nhà tài trợ để mua thiết bị mới.","audioKind":"ex"},{"en":"Local businesses can sponsor community sports programmes to improve public health and strengthen relationships with residents.","vi":"Các doanh nghiệp địa phương có thể tài trợ cho các chương trình thể thao cộng đồng để cải thiện sức khỏe công cộng và thắt chặt mối quan hệ với người dân.","audioKind":"ex2"}],"collocations":[{"en":"a corporate sponsor","vi":"nhà tài trợ doanh nghiệp"},{"en":"the main sponsor","vi":"nhà tài trợ chính"},{"en":"sponsor an event","vi":"tài trợ sự kiện"},{"en":"sponsor a team","vi":"tài trợ cho một đội"}],"wordFamily":["sponsorship (n.)"],"synonyms":["backer"],"antonyms":[],"tipVi":"sponsor có thể là danh từ hoặc động từ; danh từ chỉ hành động tài trợ là sponsorship.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_competitive', 'en-b2-54', 'competitive', '/kəmˈpetətɪv/', 'B2', 'mang tính cạnh tranh; cạnh tranh khốc liệt; hiếu thắng; có máu cạnh tranh; có tính cạnh tranh; giá cả phải chăng', 'adj.', 'compete (v.), competition (n.), competitor (n.), competitiveness (n.)', 'Trái nghĩa: uncompetitive', 'Khi miêu tả con người thường chỉ tính hiếu thắng; khi miêu tả giá cả nghĩa là có sức cạnh tranh so với người khác.', 'Our weekend football league has become surprisingly competitive.', NULL, 'Giải bóng đá cuối tuần của chúng tôi đã trở nên cạnh tranh hơn một cách đáng ngạc nhiên.', '{"wordId":"competitive","ukIpa":"/kəmˈpetətɪv/","usIpa":"/kəmˈpetətɪv/","cefr":"B2","topic":"economy","senses":[{"pos":"adj.","en":"Involving people or organisations trying to outperform each other.","vi":"mang tính cạnh tranh; cạnh tranh khốc liệt"},{"pos":"adj.","en":"Strongly wanting to win or be better than others.","vi":"hiếu thắng; có máu cạnh tranh"},{"pos":"adj.","en":"As good as or better than what others offer.","vi":"có tính cạnh tranh; giá cả phải chăng"}],"examples":[{"en":"Our weekend football league has become surprisingly competitive.","vi":"Giải bóng đá cuối tuần của chúng tôi đã trở nên cạnh tranh hơn một cách đáng ngạc nhiên.","audioKind":"ex"},{"en":"In a competitive job market, graduates need practical experience as well as strong academic qualifications.","vi":"Trong thị trường việc làm mang tính cạnh tranh cao, sinh viên mới ra trường cần cả kinh nghiệm thực tế lẫn bằng cấp học thuật vững vàng.","audioKind":"ex2"}],"collocations":[{"en":"a competitive market","vi":"thị trường cạnh tranh"},{"en":"competitive prices","vi":"giá cả cạnh tranh"},{"en":"a competitive advantage","vi":"lợi thế cạnh tranh"},{"en":"highly competitive","vi":"cạnh tranh khốc liệt"}],"wordFamily":["compete (v.)","competition (n.)","competitor (n.)","competitiveness (n.)"],"synonyms":[],"antonyms":["uncompetitive"],"tipVi":"Khi miêu tả con người thường chỉ tính hiếu thắng; khi miêu tả giá cả nghĩa là có sức cạnh tranh so với người khác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wealth', 'en-b2-54', 'wealth', '/welθ/', 'B2', 'của cải; sự giàu có; tài sản; sự phong phú; lượng lớn', 'n.', 'wealthy (adj.)', 'Đồng nghĩa: riches · Trái nghĩa: poverty', 'Wealth thường là danh từ không đếm được; cụm a wealth of dùng để chỉ lượng lớn những thứ có giá trị.', 'His wealth allowed him to buy a spacious house.', NULL, 'Sự giàu có đã giúp ông ấy mua được một ngôi nhà rộng rãi.', '{"wordId":"wealth","ukIpa":"/welθ/","usIpa":"/welθ/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"a large amount of money and valuable possessions","vi":"của cải; sự giàu có; tài sản"},{"pos":"n.","en":"a large supply of something useful or valuable","vi":"sự phong phú; lượng lớn"}],"examples":[{"en":"His wealth allowed him to buy a spacious house.","vi":"Sự giàu có đã giúp ông ấy mua được một ngôi nhà rộng rãi.","audioKind":"ex"},{"en":"A fairer distribution of wealth could improve access to education and reduce inequality across society.","vi":"Việc phân phối của cải công bằng hơn có thể cải thiện khả năng tiếp cận giáo dục và giảm sự bất bình đẳng trong toàn xã hội.","audioKind":"ex2"}],"collocations":[{"en":"accumulate wealth","vi":"tích lũy tài sản"},{"en":"distribution of wealth","vi":"phân phối tài sản"},{"en":"a wealth of experience","vi":"kinh nghiệm phong phú"}],"wordFamily":["wealthy (adj.)"],"synonyms":["riches"],"antonyms":["poverty"],"tipVi":"Wealth thường là danh từ không đếm được; cụm a wealth of dùng để chỉ lượng lớn những thứ có giá trị.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reduction', 'en-b2-54', 'reduction', '/rɪˈdʌkʃən/', 'B2', 'sự giảm bớt; sự cắt giảm; sự hạ giá', 'n.', 'reduce (v.), reduced (adj.), reducible (adj.)', 'Đồng nghĩa: decrease, decline, cut · Trái nghĩa: increase, rise', 'Danh từ reduction thường đi với giới từ in để chỉ cái gì bị giảm, và of để chỉ mức độ giảm.', 'The shop offered a generous reduction on winter coats.', NULL, 'Cửa hàng đã giảm giá mạnh cho các mẫu áo khoác mùa đông.', '{"wordId":"reduction","ukIpa":"/rɪˈdʌkʃən/","usIpa":"/rɪˈdʌkʃən/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"a decrease in the amount, size, or level of something","vi":"sự giảm bớt; sự cắt giảm; sự hạ giá"}],"examples":[{"en":"The shop offered a generous reduction on winter coats.","vi":"Cửa hàng đã giảm giá mạnh cho các mẫu áo khoác mùa đông.","audioKind":"ex"},{"en":"A substantial reduction in food waste could lower household costs and reduce pressure on landfill sites.","vi":"Việc cắt giảm đáng kể lượng rác thải thực phẩm có thể làm giảm chi phí sinh hoạt gia đình và giảm áp lực lên các bãi rác.","audioKind":"ex2"}],"collocations":[{"en":"a reduction in costs","vi":"cắt giảm chi phí"},{"en":"a significant reduction","vi":"sự giảm sút đáng kể"},{"en":"emission reductions","vi":"cắt giảm khí thải"},{"en":"price reduction","vi":"giảm giá"}],"wordFamily":["reduce (v.)","reduced (adj.)","reducible (adj.)"],"synonyms":["decrease","decline","cut"],"antonyms":["increase","rise"],"tipVi":"Danh từ reduction thường đi với giới từ in để chỉ cái gì bị giảm, và of để chỉ mức độ giảm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_merchandise', 'en-b2-54', 'merchandise', '/ˈmɝːtʃəndaɪs/', 'B2', 'hàng hóa; sản phẩm bày bán; quảng cáo bán hàng; tiếp thị', 'n.', 'merchandising (n.), merchandiser (n.)', 'Đồng nghĩa: goods, products', 'Danh từ không đếm được; âm cuối của động từ thường phát âm là /daɪz/.', 'The shop displays its new merchandise near the entrance.', NULL, 'Cửa hàng trưng bày hàng hóa mới của họ ở gần lối vào.', '{"wordId":"merchandise","ukIpa":"/ˈmɜːtʃəndaɪs/","usIpa":"/ˈmɝːtʃəndaɪs/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"goods available for sale","vi":"hàng hóa; sản phẩm bày bán"},{"pos":"v.","en":"to promote goods and encourage people to buy them","vi":"quảng cáo bán hàng; tiếp thị"}],"examples":[{"en":"The shop displays its new merchandise near the entrance.","vi":"Cửa hàng trưng bày hàng hóa mới của họ ở gần lối vào.","audioKind":"ex"},{"en":"Selling locally produced merchandise can support small businesses and reduce the environmental impact of transport.","vi":"Việc bán các mặt hàng sản xuất tại địa phương có thể hỗ trợ các doanh nghiệp nhỏ và giảm tác động môi trường của việc vận chuyển.","audioKind":"ex2"}],"collocations":[{"en":"sell merchandise","vi":"bán hàng hóa"},{"en":"branded merchandise","vi":"hàng hóa mang thương hiệu"},{"en":"display merchandise","vi":"trưng bày hàng hóa"}],"wordFamily":["merchandising (n.)","merchandiser (n.)"],"synonyms":["goods","products"],"antonyms":[],"tipVi":"Danh từ không đếm được; âm cuối của động từ thường phát âm là /daɪz/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_boom', 'en-b2-54', 'boom', '/buːm/', 'B2', 'sự bùng nổ; sự phát triển nhanh chóng; tiếng ầm ầm; tiếng nổ lớn; bùng nổ; phát triển mạnh mẽ; phát ra tiếng vang lớn', 'n.', 'booming (adj.)', 'Trái nghĩa: slump', 'Để chỉ sự tăng trưởng nhanh trong một lĩnh vực nào đó, thường dùng a boom in.', 'The tourism boom has filled every hotel in town.', NULL, 'Sự bùng nổ du lịch đã làm kín chỗ tất cả các khách sạn trong thị trấn.', '{"wordId":"boom","ukIpa":"/buːm/","usIpa":"/buːm/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"a period of rapid growth or economic success","vi":"sự bùng nổ; sự phát triển nhanh chóng"},{"pos":"n.","en":"a loud, deep sound","vi":"tiếng ầm ầm; tiếng nổ lớn"},{"pos":"v.","en":"to grow rapidly or make a loud, deep sound","vi":"bùng nổ; phát triển mạnh mẽ; phát ra tiếng vang lớn"}],"examples":[{"en":"The tourism boom has filled every hotel in town.","vi":"Sự bùng nổ du lịch đã làm kín chỗ tất cả các khách sạn trong thị trấn.","audioKind":"ex"},{"en":"A housing boom can create jobs, but it may also make homes less affordable for local residents.","vi":"Sự bùng nổ thị trường nhà ở có thể tạo ra việc làm, nhưng nó cũng có thể khiến người dân địa phương khó mua nhà hơn.","audioKind":"ex2"}],"collocations":[{"en":"economic boom","vi":"bùng nổ kinh tế"},{"en":"a boom in tourism","vi":"sự bùng nổ du lịch"},{"en":"a booming industry","vi":"ngành công nghiệp đang phát triển mạnh"}],"wordFamily":["booming (adj.)"],"synonyms":[],"antonyms":["slump"],"tipVi":"Để chỉ sự tăng trưởng nhanh trong một lĩnh vực nào đó, thường dùng a boom in.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sector', 'en-b2-54', 'sector', '/ˈsektər/', 'B2', 'lĩnh vực; ngành; khu vực; vùng; hình quạt', 'n.', 'sectoral (adj.)', NULL, 'sector thường chỉ một ngành cụ thể trong nền kinh tế, không nhất thiết là bộ phận của một công ty.', 'My sister works in the banking sector now.', NULL, 'Chị gái tôi bây giờ làm việc trong ngành ngân hàng.', '{"wordId":"sector","ukIpa":"/ˈsektə/","usIpa":"/ˈsektər/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"A particular part of an economy or area of activity.","vi":"lĩnh vực; ngành; khu vực"},{"pos":"n.","en":"A particular section of a larger area.","vi":"khu vực; vùng"},{"pos":"n.","en":"A circle''s part enclosed by two radii and an arc.","vi":"hình quạt"}],"examples":[{"en":"My sister works in the banking sector now.","vi":"Chị gái tôi bây giờ làm việc trong ngành ngân hàng.","audioKind":"ex"},{"en":"Investment in the renewable energy sector can create jobs while reducing dependence on imported fossil fuels.","vi":"Đầu tư vào lĩnh vực năng lượng tái tạo có thể tạo ra việc làm đồng thời giảm sự phụ thuộc vào nhiên liệu hóa thạch nhập khẩu.","audioKind":"ex2"}],"collocations":[{"en":"the public sector","vi":"khu vực công"},{"en":"the private sector","vi":"khu vực tư nhân"},{"en":"the manufacturing sector","vi":"ngành sản xuất"},{"en":"the service sector","vi":"ngành dịch vụ"}],"wordFamily":["sectoral (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"sector thường chỉ một ngành cụ thể trong nền kinh tế, không nhất thiết là bộ phận của một công ty.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_industrial', 'en-b2-54', 'industrial', '/ɪnˈdʌstriəl/', 'B2', 'thuộc về công nghiệp; kỹ nghệ', 'adj.', 'industry (n.), industrialize (v.), industrialization (n.)', NULL, 'industrial chỉ công nghiệp; industrious mới chỉ chăm chỉ.', 'My uncle repairs industrial machines at a nearby factory.', NULL, 'Chú tôi sửa chữa máy móc công nghiệp tại một nhà máy gần đó.', '{"wordId":"industrial","ukIpa":"/ɪnˈdʌstriəl/","usIpa":"/ɪnˈdʌstriəl/","cefr":"B2","topic":"economy","senses":[{"pos":"adj.","en":"Relating to factories and the production of goods.","vi":"thuộc về công nghiệp; kỹ nghệ"}],"examples":[{"en":"My uncle repairs industrial machines at a nearby factory.","vi":"Chú tôi sửa chữa máy móc công nghiệp tại một nhà máy gần đó.","audioKind":"ex"},{"en":"Stricter controls on industrial waste can protect rivers and improve the health of nearby communities.","vi":"Việc kiểm soát chặt chẽ hơn đối với chất thải công nghiệp có thể bảo vệ các dòng sông và cải thiện sức khỏe của cộng đồng xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"industrial production","vi":"sản xuất công nghiệp"},{"en":"industrial waste","vi":"chất thải công nghiệp"},{"en":"industrial area","vi":"khu công nghiệp"},{"en":"industrial development","vi":"phát triển công nghiệp"}],"wordFamily":["industry (n.)","industrialize (v.)","industrialization (n.)"],"synonyms":[],"antonyms":[],"tipVi":"industrial chỉ công nghiệp; industrious mới chỉ chăm chỉ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_showroom', 'en-b2-54', 'showroom', '/ˈʃoʊruːm/', 'B2', 'phòng trưng bày; showroom', 'n.', 'showrooming (n.)', NULL, 'Danh từ đếm được; "showrooming" chỉ hành vi xem hàng trực tiếp tại cửa hàng rồi mới đặt mua trực tuyến.', 'We tried several comfortable sofas in the furniture showroom.', NULL, 'Chúng tôi đã ngồi thử vài chiếc ghế sofa êm ái tại phòng trưng bày nội thất.', '{"wordId":"showroom","ukIpa":"/ˈʃəʊruːm/","usIpa":"/ˈʃoʊruːm/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"A room where goods are displayed for customers to examine.","vi":"phòng trưng bày; showroom"}],"examples":[{"en":"We tried several comfortable sofas in the furniture showroom.","vi":"Chúng tôi đã ngồi thử vài chiếc ghế sofa êm ái tại phòng trưng bày nội thất.","audioKind":"ex"},{"en":"A physical showroom allows customers to assess product quality before making purchases through online platforms.","vi":"Phòng trưng bày thực tế cho phép khách hàng đánh giá chất lượng sản phẩm trước khi mua sắm qua các nền tảng trực tuyến.","audioKind":"ex2"}],"collocations":[{"en":"furniture showroom","vi":"phòng trưng bày nội thất"},{"en":"car showroom","vi":"phòng trưng bày ô tô"},{"en":"showroom display","vi":"trưng bày tại showroom"}],"wordFamily":["showrooming (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ đếm được; \"showrooming\" chỉ hành vi xem hàng trực tiếp tại cửa hàng rồi mới đặt mua trực tuyến.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_purchase', 'en-b2-54', 'purchase', '/ˈpɝːtʃəs/', 'B2', 'mua; tậu; sự mua; vật đã mua', 'v.', 'purchaser (n.)', 'Đồng nghĩa: buy · Trái nghĩa: sell', 'Từ "purchase" mang tính trang trọng hơn "buy"; danh từ có thể chỉ hành động mua hoặc món đồ được mua.', 'You can purchase fresh bread at the corner shop.', NULL, 'Bạn có thể mua bánh mì tươi ở cửa hàng góc phố.', '{"wordId":"purchase","ukIpa":"/ˈpɜːtʃəs/","usIpa":"/ˈpɝːtʃəs/","cefr":"B2","topic":"economy","senses":[{"pos":"v.","en":"to obtain something by paying money for it","vi":"mua; tậu"},{"pos":"n.","en":"the act of buying something, or the thing bought","vi":"sự mua; vật đã mua"}],"examples":[{"en":"You can purchase fresh bread at the corner shop.","vi":"Bạn có thể mua bánh mì tươi ở cửa hàng góc phố.","audioKind":"ex"},{"en":"Consumers should consider repair costs and energy efficiency before they purchase new household appliances.","vi":"Người tiêu dùng nên cân nhắc chi phí sửa chữa và hiệu suất năng lượng trước khi mua các thiết bị gia dụng mới.","audioKind":"ex2"}],"collocations":[{"en":"purchase goods","vi":"mua hàng hóa"},{"en":"make a purchase","vi":"thực hiện một giao dịch mua"},{"en":"purchase price","vi":"giá mua"},{"en":"proof of purchase","vi":"chứng chứng từ mua hàng"}],"wordFamily":["purchaser (n.)"],"synonyms":["buy"],"antonyms":["sell"],"tipVi":"Từ \"purchase\" mang tính trang trọng hơn \"buy\"; danh từ có thể chỉ hành động mua hoặc món đồ được mua.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_costly', 'en-b2-54', 'costly', '/ˈkɔːstli/', 'B2', 'đắt đỏ; tốn kém; gây thiệt hại lớn; tai hại', 'adj.', 'cost (n.), cost (v.)', 'Đồng nghĩa: expensive · Trái nghĩa: inexpensive', 'Mặc dù tận cùng bằng đuôi "-ly", từ này là một tính từ; nó cũng có thể chỉ tổn thất nặng nề.', 'Replacing the broken roof proved more costly than expected.', NULL, 'Việc thay thế phần mái nhà bị hỏng hóa ra tốn kém hơn dự kiến.', '{"wordId":"costly","ukIpa":"/ˈkɒstli/","usIpa":"/ˈkɔːstli/","cefr":"B2","topic":"economy","senses":[{"pos":"adj.","en":"requiring a large amount of money","vi":"đắt đỏ; tốn kém"},{"pos":"adj.","en":"causing serious loss, harm or disadvantage","vi":"gây thiệt hại lớn; tai hại"}],"examples":[{"en":"Replacing the broken roof proved more costly than expected.","vi":"Việc thay thế phần mái nhà bị hỏng hóa ra tốn kém hơn dự kiến.","audioKind":"ex"},{"en":"Delaying investment in flood protection could prove costly for communities exposed to increasingly severe storms.","vi":"Việc trì hoãn đầu tư vào công tác phòng chống lũ lụt có thể gây tổn thất nặng nề cho các cộng đồng phải đối mặt với những trận bão ngày càng tàn khốc.","audioKind":"ex2"}],"collocations":[{"en":"costly repairs","vi":"chi phí sửa chữa đắt đỏ"},{"en":"a costly mistake","vi":"một sai lầm tai hại"},{"en":"prove costly","vi":"chứng tỏ là rất tốn kém"}],"wordFamily":["cost (n.)","cost (v.)"],"synonyms":["expensive"],"antonyms":["inexpensive"],"tipVi":"Mặc dù tận cùng bằng đuôi \"-ly\", từ này là một tính từ; nó cũng có thể chỉ tổn thất nặng nề.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stabilize', 'en-b2-54', 'stabilize', '/ˈsteɪbəlaɪz/', 'B2', 'làm cho ổn định, giữ vững, trở nên vững vàng', 'v.', 'stable (adj.), stability (n.), stabilization (n.), unstable (adj.)', 'Đồng nghĩa: steady · Trái nghĩa: destabilize', 'Có thể dùng như ngoại động từ hoặc nội động từ; trong tiếng Anh - Anh thường được viết là "stabilise".', 'We used a wooden block to stabilize the table.', NULL, 'Chúng tôi đã dùng một khối gỗ để kê cho chiếc bàn khỏi bập bênh.', '{"wordId":"stabilize","ukIpa":"/ˈsteɪbəlaɪz/","usIpa":"/ˈsteɪbəlaɪz/","cefr":"B2","topic":"economy","senses":[{"pos":"v.","en":"make or become steady and less likely to change","vi":"làm cho ổn định, giữ vững, trở nên vững vàng"}],"examples":[{"en":"We used a wooden block to stabilize the table.","vi":"Chúng tôi đã dùng một khối gỗ để kê cho chiếc bàn khỏi bập bênh.","audioKind":"ex"},{"en":"Governments may need to stabilize food prices to protect vulnerable households during periods of economic uncertainty.","vi":"Chính phủ có thể cần bình ổn giá lương thực để bảo vệ các hộ gia đình dễ bị tổn thương trong thời kỳ kinh tế bất ổn.","audioKind":"ex2"}],"collocations":[{"en":"stabilize prices","vi":"bình ổn giá cả"},{"en":"stabilize the economy","vi":"ổn định nền kinh tế"},{"en":"stabilize a patient''s condition","vi":"ổn định tình trạng bệnh nhân"}],"wordFamily":["stable (adj.)","stability (n.)","stabilization (n.)","unstable (adj.)"],"synonyms":["steady"],"antonyms":["destabilize"],"tipVi":"Có thể dùng như ngoại động từ hoặc nội động từ; trong tiếng Anh - Anh thường được viết là \"stabilise\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_downward', 'en-b2-54', 'downward', '/ˈdaʊnwərd/', 'B2', 'hướng xuống; đi xuống; về phía dưới; hướng xuống thấp', 'adj.', 'downwards (adv.)', 'Trái nghĩa: upward', 'downward có thể làm tính từ và trạng từ; downwards chỉ làm trạng từ.', 'The bird began its downward flight towards the lake.', NULL, 'Con chim bắt đầu cất cánh bay xuống hướng về phía hồ nước.', '{"wordId":"downward","ukIpa":"/ˈdaʊnwəd/","usIpa":"/ˈdaʊnwərd/","cefr":"B2","topic":"economy","senses":[{"pos":"adj.","en":"Moving or pointing towards a lower place, level, or amount.","vi":"hướng xuống; đi xuống"},{"pos":"adv.","en":"Towards a lower place, level, or amount.","vi":"về phía dưới; hướng xuống thấp"}],"examples":[{"en":"The bird began its downward flight towards the lake.","vi":"Con chim bắt đầu cất cánh bay xuống hướng về phía hồ nước.","audioKind":"ex"},{"en":"A downward trend in household energy consumption may reflect better insulation and greater public awareness.","vi":"Xu hướng giảm trong tiêu thụ năng lượng của hộ gia đình có thể phản ánh việc cách nhiệt tốt hơn và ý thức cộng đồng cao hơn.","audioKind":"ex2"}],"collocations":[{"en":"a downward trend","vi":"xu hướng giảm"},{"en":"downward pressure","vi":"áp lực giảm"},{"en":"a downward spiral","vi":"vòng xoáy đi xuống"},{"en":"move downward","vi":"di chuyển xuống dưới"}],"wordFamily":["downwards (adv.)"],"synonyms":[],"antonyms":["upward"],"tipVi":"downward có thể làm tính từ và trạng từ; downwards chỉ làm trạng từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_installment', 'en-b2-54', 'installment', '/ɪnˈstɔːlmənt/', 'B2', 'khoản tiền trả góp theo kỳ; tập (truyện, phim); kỳ phát hành', 'n.', NULL, NULL, 'Đây là cách viết theo kiểu Mỹ; dạng viết Anh-Anh là instalment, việc trả góp đi kèm giới từ in.', 'I paid the final installment on my bicycle today.', NULL, 'Tôi đã thanh toán khoản trả góp cuối cùng cho chiếc xe đạp của mình vào ngày hôm nay.', '{"wordId":"installment","ukIpa":"/ɪnˈstɔːlmənt/","usIpa":"/ɪnˈstɔːlmənt/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"One of several payments made over time for something.","vi":"khoản tiền trả góp theo kỳ"},{"pos":"n.","en":"One part of a story or series released separately.","vi":"tập (truyện, phim); kỳ phát hành"}],"examples":[{"en":"I paid the final installment on my bicycle today.","vi":"Tôi đã thanh toán khoản trả góp cuối cùng cho chiếc xe đạp của mình vào ngày hôm nay.","audioKind":"ex"},{"en":"Paying tuition fees in installments can make higher education more accessible to students from poorer households.","vi":"Việc chia nhỏ học phí thành nhiều lần đóng góp giúp học sinh từ các hộ gia đình nghèo dễ dàng tiếp cận giáo dục bậc cao hơn.","audioKind":"ex2"}],"collocations":[{"en":"pay in installments","vi":"trả góp"},{"en":"monthly installment","vi":"khoản góp hàng tháng"},{"en":"the next installment","vi":"tập tiếp theo; kỳ tiếp theo"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Đây là cách viết theo kiểu Mỹ; dạng viết Anh-Anh là instalment, việc trả góp đi kèm giới từ in.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gross', 'en-b2-54', 'gross', '/ɡroʊs/', 'B2', 'tổng, trước thuế; gộp; trầm trọng; cực kỳ tệ hại; ghê tởm; khó ưa', 'adj.', 'grossly (adv.)', 'Đồng nghĩa: total, disgusting · Trái nghĩa: net', 'Trong tài chính, gross là tổng số trước khi khấu trừ, còn net là số ròng.', 'My gross pay looks much better than my take-home pay.', NULL, 'Lương gộp của tôi trông khá hơn nhiều so với lương thực nhận.', '{"wordId":"gross","ukIpa":"/ɡrəʊs/","usIpa":"/ɡroʊs/","cefr":"B2","topic":"economy","senses":[{"pos":"adj.","en":"Calculated before taxes, costs, or other amounts are taken away.","vi":"tổng, trước thuế; gộp"},{"pos":"adj.","en":"Extremely serious and clearly unacceptable.","vi":"trầm trọng; cực kỳ tệ hại"},{"pos":"adj.","en":"Very unpleasant or disgusting.","vi":"ghê tởm; khó ưa"}],"examples":[{"en":"My gross pay looks much better than my take-home pay.","vi":"Lương gộp của tôi trông khá hơn nhiều so với lương thực nhận.","audioKind":"ex"},{"en":"Gross domestic product measures economic output, but it does not fully reflect citizens'' quality of life.","vi":"Tổng sản phẩm quốc nội đo lường sản lượng kinh tế, nhưng nó không phản ánh đầy đủ chất lượng cuộc sống của người dân.","audioKind":"ex2"}],"collocations":[{"en":"gross income","vi":"thu nhập tổng"},{"en":"gross domestic product","vi":"tổng sản phẩm quốc nội"},{"en":"gross negligence","vi":"sự cẩu thả nghiêm trọng"},{"en":"gross profit","vi":"lợi nhuận gộp"}],"wordFamily":["grossly (adv.)"],"synonyms":["total","disgusting"],"antonyms":["net"],"tipVi":"Trong tài chính, gross là tổng số trước khi khấu trừ, còn net là số ròng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prosperous', 'en-b2-54', 'prosperous', '/ˈprɑːspərəs/', 'B2', 'thịnh vượng; phát đạt; giàu có', 'adj.', 'prosper (v.), prosperity (n.)', 'Đồng nghĩa: thriving, affluent, wealthy · Trái nghĩa: impoverished', 'Thường dùng để mô tả quốc gia, khu vực hoặc nền kinh tế, nhấn mạnh sự hưng thịnh về mặt tài chính.', 'The once quiet village is now a prosperous market town.', NULL, 'Ngôi làng từng yên bình nay đã trở thành một thị trấn chợ sầm uất, thịnh vượng.', '{"wordId":"prosperous","ukIpa":"/ˈprɒspərəs/","usIpa":"/ˈprɑːspərəs/","cefr":"B2","topic":"economy","senses":[{"pos":"adj.","en":"Financially successful and enjoying wealth or economic growth","vi":"thịnh vượng; phát đạt; giàu có"}],"examples":[{"en":"The once quiet village is now a prosperous market town.","vi":"Ngôi làng từng yên bình nay đã trở thành một thị trấn chợ sầm uất, thịnh vượng.","audioKind":"ex"},{"en":"A prosperous economy can generate the resources needed to improve education, healthcare, and public infrastructure.","vi":"Một nền kinh tế thịnh vượng có thể tạo ra các nguồn lực cần thiết để cải thiện giáo dục, y tế và cơ sở hạ tầng công cộng.","audioKind":"ex2"}],"collocations":[{"en":"prosperous economy","vi":"nền kinh tế thịnh vượng"},{"en":"prosperous nation","vi":"quốc gia giàu có, thịnh vượng"},{"en":"prosperous future","vi":"tương lai thịnh vượng, phú quý"}],"wordFamily":["prosper (v.)","prosperity (n.)"],"synonyms":["thriving","affluent","wealthy"],"antonyms":["impoverished"],"tipVi":"Thường dùng để mô tả quốc gia, khu vực hoặc nền kinh tế, nhấn mạnh sự hưng thịnh về mặt tài chính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_54_1', 'en-b2-54', 'Cách dùng “finance” (n.) — tài chính; quản lý tài chính', 'public finance  ·  raise finance  ·  finance a project', 'Từ finance có thể chỉ nguồn tiền hoặc lĩnh vực tài chính; khi nói về tài chính cá nhân thường dùng số nhiều finances.', 'Họ từ (Word Family): financial (adj.), financially (adv.), financing (n.) | Đồng nghĩa: funding', '[{"hanzi":"The bank agreed to finance our new bakery.","pinyin":"","meaning":"Ngân hàng đã đồng ý cấp vốn cho cửa hàng bánh mới của chúng tôi."},{"hanzi":"Access to affordable finance allows small businesses to invest in equipment and create more local jobs.","pinyin":"","meaning":"Khả năng tiếp cận nguồn vốn với chi phí hợp lý giúp các doanh nghiệp nhỏ đầu tư vào trang thiết bị và tạo ra nhiều việc làm hơn tại địa phương."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_54_2', 'en-b2-54', 'Cách dùng “competitive” (adj.) — mang tính cạnh tranh; cạnh tranh khốc liệt', 'a competitive market  ·  competitive prices  ·  a competitive advantage', 'Khi miêu tả con người thường chỉ tính hiếu thắng; khi miêu tả giá cả nghĩa là có sức cạnh tranh so với người khác.', 'Họ từ (Word Family): compete (v.), competition (n.), competitor (n.), competitiveness (n.) | Trái nghĩa: uncompetitive', '[{"hanzi":"Our weekend football league has become surprisingly competitive.","pinyin":"","meaning":"Giải bóng đá cuối tuần của chúng tôi đã trở nên cạnh tranh hơn một cách đáng ngạc nhiên."},{"hanzi":"In a competitive job market, graduates need practical experience as well as strong academic qualifications.","pinyin":"","meaning":"Trong thị trường việc làm mang tính cạnh tranh cao, sinh viên mới ra trường cần cả kinh nghiệm thực tế lẫn bằng cấp học thuật vững vàng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_54_3', 'en-b2-54', 'Cách dùng “showroom” (n.) — phòng trưng bày; showroom', 'furniture showroom  ·  car showroom  ·  showroom display', 'Danh từ đếm được; "showrooming" chỉ hành vi xem hàng trực tiếp tại cửa hàng rồi mới đặt mua trực tuyến.', 'Họ từ (Word Family): showrooming (n.)', '[{"hanzi":"We tried several comfortable sofas in the furniture showroom.","pinyin":"","meaning":"Chúng tôi đã ngồi thử vài chiếc ghế sofa êm ái tại phòng trưng bày nội thất."},{"hanzi":"A physical showroom allows customers to assess product quality before making purchases through online platforms.","pinyin":"","meaning":"Phòng trưng bày thực tế cho phép khách hàng đánh giá chất lượng sản phẩm trước khi mua sắm qua các nền tảng trực tuyến."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_54_4', 'en-b2-54', 'Cách dùng “stabilize” (v.) — làm cho ổn định, giữ vững, trở nên vững vàng', 'stabilize prices  ·  stabilize the economy  ·  stabilize a patient''s condition', 'Có thể dùng như ngoại động từ hoặc nội động từ; trong tiếng Anh - Anh thường được viết là "stabilise".', 'Họ từ (Word Family): stable (adj.), stability (n.), stabilization (n.), unstable (adj.) | Đồng nghĩa: steady · Trái nghĩa: destabilize', '[{"hanzi":"We used a wooden block to stabilize the table.","pinyin":"","meaning":"Chúng tôi đã dùng một khối gỗ để kê cho chiếc bàn khỏi bập bênh."},{"hanzi":"Governments may need to stabilize food prices to protect vulnerable households during periods of economic uncertainty.","pinyin":"","meaning":"Chính phủ có thể cần bình ổn giá lương thực để bảo vệ các hộ gia đình dễ bị tổn thương trong thời kỳ kinh tế bất ổn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_54_1', 'en-b2-54', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
