INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_54_1_3', 'ten_b2_54_1', 'finance', 'The bank agreed to finance our new bakery.', 'The bank agreed to finance our new bakery.', '/ˈfaɪnæns/', 'Ngân hàng đã đồng ý cấp vốn cho cửa hàng bánh mới của chúng tôi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_54_1_4', 'ten_b2_54_1', 'trader', 'A market trader arranged fresh oranges outside his stall.', 'A market trader arranged fresh oranges outside his stall.', '/ˈtreɪdər/', 'Một người tiểu thương đã sắp xếp những quả cam tươi bên ngoài sạp hàng của mình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_54_1_5', 'ten_b2_54_1', 'bid', 'I bid twenty pounds for the old wooden chair.', 'I bid twenty pounds for the old wooden chair.', '/bɪd/', 'Tôi ra giá hai mươi bảng cho chiếc ghế gỗ cũ đó.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_54_1_6', 'ten_b2_54_1', 'halve', 'Sharing a taxi would halve the cost for each person.', 'Sharing a taxi would halve the cost for each person.', '/hæv/', 'Đi chung taxi sẽ giúp giảm một nửa chi phí cho mỗi người.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_54_1_7', 'ten_b2_54_1', 'sponsor', 'Our swimming club needs a sponsor for new equipment.', 'Our swimming club needs a sponsor for new equipment.', '/ˈspɑːnsər/', 'Câu lạc bộ bơi lội của chúng tôi cần một nhà tài trợ để mua thiết bị mới.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_54_1_8', 'ten_b2_54_1', 'competitive', 'Our weekend football league has become surprisingly competitive.', 'Our weekend football league has become surprisingly competitive.', '/kəmˈpetətɪv/', 'Giải bóng đá cuối tuần của chúng tôi đã trở nên cạnh tranh hơn một cách đáng ngạc nhiên.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_54_1_1', 'en-b2-54', 'ten_b2_54_1', 'listening', 'listening', 'Our weekend bake sale generated enough money for new books.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Buổi bán bánh gây quỹ cuối tuần của chúng tôi đã kiếm đủ tiền mua sách mới.","Chú tôi sửa chữa máy móc công nghiệp tại một nhà máy gần đó.","Chúng tôi đã ngồi thử vài chiếc ghế sofa êm ái tại phòng trưng bày nội thất.","Việc thay thế phần mái nhà bị hỏng hóa ra tốn kém hơn dự kiến."]'::jsonb, 0, 'Our weekend bake sale generated enough money for new books. → Buổi bán bánh gây quỹ cuối tuần của chúng tôi đã kiếm đủ tiền mua sách mới.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_54_1_2', 'en-b2-54', 'ten_b2_54_1', 'listening', 'listening', 'She finally gained ownership of her small apartment.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi đã thanh toán khoản trả góp cuối cùng cho chiếc xe đạp của mình vào ngày hôm nay.","Cô ấy cuối cùng cũng giành được quyền sở hữu căn hộ nhỏ của mình.","Buổi bán bánh gây quỹ cuối tuần của chúng tôi đã kiếm đủ tiền mua sách mới.","Chúng tôi đã dùng một khối gỗ để kê cho chiếc bàn khỏi bập bênh."]'::jsonb, 1, 'She finally gained ownership of her small apartment. → Cô ấy cuối cùng cũng giành được quyền sở hữu căn hộ nhỏ của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_54_1_3', 'en-b2-54', 'ten_b2_54_1', 'listening', 'listening', 'The bank agreed to finance our new bakery.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Ngân hàng đã đồng ý cấp vốn cho cửa hàng bánh mới của chúng tôi.","Cửa hàng trưng bày hàng hóa mới của họ ở gần lối vào.","Chú tôi sửa chữa máy móc công nghiệp tại một nhà máy gần đó.","Một người tiểu thương đã sắp xếp những quả cam tươi bên ngoài sạp hàng của mình."]'::jsonb, 0, 'The bank agreed to finance our new bakery. → Ngân hàng đã đồng ý cấp vốn cho cửa hàng bánh mới của chúng tôi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_54_2', 'en-b2-54', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_54_2_1', 'ten_b2_54_2', 'generate', 'Investment in renewable energy can generate employment while reducing dependence on imported fossil fuels.', 'Investment in renewable energy can generate employment while reducing dependence on imported fossil fuels.', '/ˈdʒenəreɪt/', 'Đầu tư vào năng lượng tái tạo có thể tạo ra việc làm đồng thời giảm sự phụ thuộc vào nhiên liệu hóa thạch nhập khẩu.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_54_2_2', 'ten_b2_54_2', 'ownership', 'Public ownership of essential services may help ensure equal access for people on lower incomes.', 'Public ownership of essential services may help ensure equal access for people on lower incomes.', '/ˈoʊnərʃɪp/', 'Quyền sở hữu công đối với các dịch vụ thiết yếu có thể giúp đảm bảo khả năng tiếp cận bình đẳng cho những người có thu nhập thấp hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_54_2_3', 'ten_b2_54_2', 'finance', 'Access to affordable finance allows small businesses to invest in equipment and create more local jobs.', 'Access to affordable finance allows small businesses to invest in equipment and create more local jobs.', '/ˈfaɪnæns/', 'Khả năng tiếp cận nguồn vốn với chi phí hợp lý giúp các doanh nghiệp nhỏ đầu tư vào trang thiết bị và tạo ra nhiều việc làm hơn tại địa phương.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_54_2_4', 'ten_b2_54_2', 'trader', 'Small traders often struggle to compete with larger retailers that can negotiate lower prices from suppliers.', 'Small traders often struggle to compete with larger retailers that can negotiate lower prices from suppliers.', '/ˈtreɪdər/', 'Các tiểu thương nhỏ thường gặp khó khăn khi cạnh tranh với các nhà bán lẻ lớn hơn, những đơn vị có khả năng thương lượng mức giá rẻ hơn từ nhà cung cấp.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_54_2_5', 'ten_b2_54_2', 'bid', 'Several local companies submitted a bid to build affordable housing near the city''s main railway station.', 'Several local companies submitted a bid to build affordable housing near the city''s main railway station.', '/bɪd/', 'Nhiều công ty địa phương đã nộp hồ sơ dự thầu để xây dựng nhà ở giá rẻ gần ga đường sắt chính của thành phố.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_54_2_6', 'ten_b2_54_2', 'halve', 'The city aims to halve household food waste by expanding composting services and promoting more careful shopping.', 'The city aims to halve household food waste by expanding composting services and promoting more careful shopping.', '/hæv/', 'Thành phố đặt mục tiêu giảm một nửa lượng rác thải thực phẩm sinh hoạt bằng cách mở rộng dịch vụ ủ phân và thúc đẩy việc mua sắm có ý thức hơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_54_2_1', 'en-b2-54', 'ten_b2_54_2', 'listening', 'listening', 'Investment in renewable energy can generate employment while reducing dependence on imported fossil fuels.', NULL, 'Trong câu vừa nghe, từ “generate” mang nghĩa nào sau đây?', '["gây xôn xao; giật gân; rùm beng (gây phấn khích hoặc sốc lớn, đôi khi thông qua sự phóng đại)","làm nản lòng; khiến buồn bã","tự kinh doanh; tự làm chủ","tạo ra; sinh ra"]'::jsonb, 3, '“generate” (/ˈdʒenəreɪt/): tạo ra; sinh ra. Câu đầy đủ: Investment in renewable energy can generate employment while reducing dependence on imported fossil fuels.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_54_2_2', 'en-b2-54', 'ten_b2_54_2', 'listening', 'listening', 'Public ownership of essential services may help ensure equal access for people on lower incomes.', NULL, 'Trong câu vừa nghe, từ “ownership” mang nghĩa nào sau đây?', '["biểu tượng (trên màn hình máy tính, điện thoại)","được cho là; theo như người ta nói","làm say mê; thu hút sâu sắc","quyền sở hữu"]'::jsonb, 3, '“ownership” (/ˈoʊnərʃɪp/): quyền sở hữu. Câu đầy đủ: Public ownership of essential services may help ensure equal access for people on lower incomes.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
