INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_54_1', 'en-b2-54', NULL, 'comprehensive_test', 'listening', 'generate', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự tò mò; lòng khao khát hiểu biết","tạo ra; sinh ra","đạt được; mua lại; sắm được","tuyệt vọng; liều lĩnh"]'::jsonb, 1, 'generate (/ˈdʒenəreɪt/) → tạo ra; sinh ra; phát điện; tạo năng lượng', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_54_2', 'en-b2-54', NULL, 'comprehensive_test', 'listening', 'She finally gained ownership of her small apartment.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy cuối cùng cũng giành được quyền sở hữu căn hộ nhỏ của mình.","Con chim bắt đầu cất cánh bay xuống hướng về phía hồ nước.","Giải bóng đá cuối tuần của chúng tôi đã trở nên cạnh tranh hơn một cách đáng ngạc nhiên.","Chúng tôi đã dùng một khối gỗ để kê cho chiếc bàn khỏi bập bênh."]'::jsonb, 0, 'She finally gained ownership of her small apartment. → Cô ấy cuối cùng cũng giành được quyền sở hữu căn hộ nhỏ của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_54_3', 'en-b2-54', NULL, 'comprehensive_test', 'listening', 'finance', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tài chính; quản lý tài chính","vô giá trị; không có ích","bị xói mòn; bị bào mòn","cái bẫy; dụng cụ bắt bẫy"]'::jsonb, 0, 'finance (/ˈfaɪnæns/) → tài chính; quản lý tài chính; nguồn vốn; kinh phí; cấp vốn; tài trợ tiền cho việc gì', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_54_4', 'en-b2-54', NULL, 'comprehensive_test', 'listening', 'A market trader arranged fresh oranges outside his stall.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sự giàu có đã giúp ông ấy mua được một ngôi nhà rộng rãi.","Chúng tôi đã dùng một khối gỗ để kê cho chiếc bàn khỏi bập bênh.","Cô ấy cuối cùng cũng giành được quyền sở hữu căn hộ nhỏ của mình.","Một người tiểu thương đã sắp xếp những quả cam tươi bên ngoài sạp hàng của mình."]'::jsonb, 3, 'A market trader arranged fresh oranges outside his stall. → Một người tiểu thương đã sắp xếp những quả cam tươi bên ngoài sạp hàng của mình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_54_5', 'en-b2-54', NULL, 'comprehensive_test', 'listening', 'bid', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự vận chuyển hàng hóa; ngành vận tải biển","thông dịch viên, phiên dịch viên","quận; hạt; tỉnh (đơn vị hành chính)","trả giá; đấu giá; bỏ thầu"]'::jsonb, 3, 'bid (/bɪd/) → trả giá; đấu giá; bỏ thầu; giá bỏ thầu; mức giá đưa ra; sự nỗ lực; sự mưu cầu', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_54_6', 'en-b2-54', NULL, 'comprehensive_test', 'listening', 'Sharing a taxi would halve the cost for each person.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cửa hàng đã giảm giá mạnh cho các mẫu áo khoác mùa đông.","Chúng tôi đã dùng một khối gỗ để kê cho chiếc bàn khỏi bập bênh.","Đi chung taxi sẽ giúp giảm một nửa chi phí cho mỗi người.","Bạn có thể mua bánh mì tươi ở cửa hàng góc phố."]'::jsonb, 2, 'Sharing a taxi would halve the cost for each person. → Đi chung taxi sẽ giúp giảm một nửa chi phí cho mỗi người.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_54_7', 'en-b2-54', NULL, 'comprehensive_test', 'listening', 'sponsor', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nhà tài trợ; mạnh thường quân","trước đó; ở phần trước","kẻ hèn nhát; đồ nhát gan","bỏ sót; lược bỏ; bỏ qua"]'::jsonb, 0, 'sponsor (/ˈspɑːnsər/) → nhà tài trợ; mạnh thường quân; tài trợ; bảo trợ tài chính', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_54_8', 'en-b2-54', NULL, 'comprehensive_test', 'listening', 'Our weekend football league has become surprisingly competitive.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sự giàu có đã giúp ông ấy mua được một ngôi nhà rộng rãi.","Ngôi làng từng yên bình nay đã trở thành một thị trấn chợ sầm uất, thịnh vượng.","Con chim bắt đầu cất cánh bay xuống hướng về phía hồ nước.","Giải bóng đá cuối tuần của chúng tôi đã trở nên cạnh tranh hơn một cách đáng ngạc nhiên."]'::jsonb, 3, 'Our weekend football league has become surprisingly competitive. → Giải bóng đá cuối tuần của chúng tôi đã trở nên cạnh tranh hơn một cách đáng ngạc nhiên.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_54_9', 'en-b2-54', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To offer a price or compete formally for a contract.”?', '["bid","halve","merchandise","wealth"]'::jsonb, 0, 'bid (/bɪd/) → trả giá; đấu giá; bỏ thầu', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_54_10', 'en-b2-54', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To reduce something to half its original amount.”?', '["sector","wealth","halve","costly"]'::jsonb, 2, 'halve (/hæv/) → giảm một nửa', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_54_11', 'en-b2-54', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A person or organisation providing support, often in return for publicity.”?', '["downward","sponsor","ownership","gross"]'::jsonb, 1, 'sponsor (/ˈspɑːnsər/) → nhà tài trợ; mạnh thường quân', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_54_12', 'en-b2-54', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Involving people or organisations trying to outperform each other.”?', '["wealth","competitive","sponsor","merchandise"]'::jsonb, 1, 'competitive (/kəmˈpetətɪv/) → mang tính cạnh tranh; cạnh tranh khốc liệt', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
