INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_54_18', 'en-b2-54', NULL, 'comprehensive_test', 'reading', NULL, 'Investment in renewable energy can generate employment while reducing dependence on imported fossil fuels.', 'Dựa vào câu trên, từ “generate” có nghĩa phù hợp nhất là gì?', '["tính đa dạng; sự phong phú","xe hơi, ô tô (đặc biệt trong tiếng Anh Mỹ)","cuộc diễu hành; đoàn diễu hành","tạo ra; sinh ra"]'::jsonb, 3, 'generate: tạo ra; sinh ra; phát điện; tạo năng lượng. Dịch cả câu: Đầu tư vào năng lượng tái tạo có thể tạo ra việc làm đồng thời giảm sự phụ thuộc vào nhiên liệu hóa thạch nhập khẩu.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_54_19', 'en-b2-54', NULL, 'comprehensive_test', 'reading', NULL, 'Public ownership of essential services may help ensure equal access for people on lower incomes.', 'Dựa vào câu trên, từ “ownership” có nghĩa phù hợp nhất là gì?', '["xác suất; khả năng xảy ra","quyền sở hữu","đặc điểm; nét tiêu biểu của một người hoặc một vật","dải; mảnh nhỏ"]'::jsonb, 1, 'ownership: quyền sở hữu; ý thức trách nhiệm. Dịch cả câu: Quyền sở hữu công đối với các dịch vụ thiết yếu có thể giúp đảm bảo khả năng tiếp cận bình đẳng cho những người có thu nhập thấp hơn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_54_20', 'en-b2-54', NULL, 'comprehensive_test', 'reading', NULL, 'Access to affordable finance allows small businesses to invest in equipment and create more local jobs.', 'Dựa vào câu trên, từ “finance” có nghĩa phù hợp nhất là gì?', '["thuộc về toán học; có tính toán học","tài chính; quản lý tài chính","xác suất; khả năng xảy ra","trường nội trú"]'::jsonb, 1, 'finance: tài chính; quản lý tài chính; nguồn vốn; kinh phí; cấp vốn; tài trợ tiền cho việc gì. Dịch cả câu: Khả năng tiếp cận nguồn vốn với chi phí hợp lý giúp các doanh nghiệp nhỏ đầu tư vào trang thiết bị và tạo ra nhiều việc làm hơn tại địa phương.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_54_21', 'en-b2-54', NULL, 'comprehensive_test', 'reading', NULL, 'Small traders often struggle to compete with larger retailers that can negotiate lower prices from suppliers.', 'Dựa vào câu trên, từ “trader” có nghĩa phù hợp nhất là gì?', '["vệ tinh nhân tạo (thiết bị bay quanh Trái Đất hoặc hành tinh khác để thu thập hoặc truyền tải thông tin)","trêu chọc; chế nhạo","một cách chân thành; từ đáy lòng","thương nhân; tiểu thương; nhà giao dịch"]'::jsonb, 3, 'trader: thương nhân; tiểu thương; nhà giao dịch. Dịch cả câu: Các tiểu thương nhỏ thường gặp khó khăn khi cạnh tranh với các nhà bán lẻ lớn hơn, những đơn vị có khả năng thương lượng mức giá rẻ hơn từ nhà cung cấp.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_54_22', 'en-b2-54', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “khoản tiền trả góp theo kỳ”', '["installment","filthy","drift","tobacco"]'::jsonb, 0, 'khoản tiền trả góp theo kỳ → installment (/ɪnˈstɔːlmənt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_54_23', 'en-b2-54', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tổng, trước thuế; gộp”', '["climax","bait","gross","incomplete"]'::jsonb, 2, 'tổng, trước thuế; gộp → gross (/ɡroʊs/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_54_24', 'en-b2-54', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thịnh vượng; phát đạt; giàu có”', '["organic","audition","prosperous","obesity"]'::jsonb, 2, 'thịnh vượng; phát đạt; giàu có → prosperous (/ˈprɑːspərəs/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-55', 'en', 'Bài 55: Kinh tế & Tài chính (4) - CEFR B2', 'CEFR B2', 'B2 · Kinh tế', '21 từ vựng Tiếng Anh CEFR B2 chủ đề kinh tế & tài chính kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4055, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recession', 'en-b2-55', 'recession', '/rɪˈseʃən/', 'B2', 'suy thoái kinh tế; thời kỳ kinh tế sụt giảm; sự lùi lại; sự thụt lùi', 'n.', 'recede (v.), recessionary (adj.)', 'Đồng nghĩa: downturn, slump · Trái nghĩa: boom', 'Thường chỉ tổng thể kinh tế suy thoái, không đồng nghĩa với việc giá cả giảm đơn thuần.', 'During the recession, my uncle struggled to find work.', NULL, 'Trong thời kỳ suy thoái, chú tôi rất chật vật để tìm việc làm.', '{"wordId":"recession","ukIpa":"/rɪˈseʃən/","usIpa":"/rɪˈseʃən/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"A period when economic activity falls and many businesses struggle.","vi":"suy thoái kinh tế; thời kỳ kinh tế sụt giảm"},{"pos":"n.","en":"The gradual movement of something backwards from its previous position.","vi":"sự lùi lại; sự thụt lùi"}],"examples":[{"en":"During the recession, my uncle struggled to find work.","vi":"Trong thời kỳ suy thoái, chú tôi rất chật vật để tìm việc làm.","audioKind":"ex"},{"en":"Governments may increase public investment during a recession to protect jobs and stimulate consumer demand.","vi":"Các chính phủ có thể tăng đầu tư công trong thời kỳ suy thoái để bảo vệ việc làm và kích thích nhu cầu tiêu dùng.","audioKind":"ex2"}],"collocations":[{"en":"economic recession","vi":"suy thoái kinh tế"},{"en":"deep recession","vi":"suy thoái trầm trọng"},{"en":"enter a recession","vi":"bước vào thời kỳ suy thoái"},{"en":"gum recession","vi":"tụt nướu; teo nướu"}],"wordFamily":["recede (v.)","recessionary (adj.)"],"synonyms":["downturn","slump"],"antonyms":["boom"],"tipVi":"Thường chỉ tổng thể kinh tế suy thoái, không đồng nghĩa với việc giá cả giảm đơn thuần.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_insure', 'en-b2-55', 'insure', '/ɪnˈʃʊr/', 'B2', 'mua bảo hiểm cho; bảo hiểm', 'v.', 'insurance (n.), insurer (n.), insured (adj.)', NULL, 'insure chủ yếu mang nghĩa mua bảo hiểm; để diễn đạt ý bảo đảm hãy dùng ensure.', 'We insured our bicycles before taking them abroad.', NULL, 'Chúng tôi đã mua bảo hiểm cho xe đạp trước khi đem chúng ra nước ngoài.', '{"wordId":"insure","ukIpa":"/ɪnˈʃʊə/","usIpa":"/ɪnˈʃʊr/","cefr":"B2","topic":"economy","senses":[{"pos":"v.","en":"Arrange financial protection against loss, damage, illness, or injury.","vi":"mua bảo hiểm cho; bảo hiểm"}],"examples":[{"en":"We insured our bicycles before taking them abroad.","vi":"Chúng tôi đã mua bảo hiểm cho xe đạp trước khi đem chúng ra nước ngoài.","audioKind":"ex"},{"en":"Small businesses should insure their premises against fire to avoid potentially devastating financial losses.","vi":"Các doanh nghiệp nhỏ nên mua bảo hiểm hỏa hoạn cho cơ sở kinh doanh của mình để tránh những tổn thất tài chính có thể gây ra hậu quả tàn khốc.","audioKind":"ex2"}],"collocations":[{"en":"insure against theft","vi":"bảo hiểm chống trộm cắp"},{"en":"insure a vehicle","vi":"bảo hiểm xe"},{"en":"fully insured","vi":"được bảo hiểm đầy đủ"}],"wordFamily":["insurance (n.)","insurer (n.)","insured (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"insure chủ yếu mang nghĩa mua bảo hiểm; để diễn đạt ý bảo đảm hãy dùng ensure.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_debit', 'en-b2-55', 'debit', '/ˈdebɪt/', 'B2', 'khoản tiền bị trừ; khoản ghi nợ; trừ tiền trong tài khoản; ghi nợ', 'n.', NULL, 'Trái nghĩa: credit', 'Thẻ debit sử dụng tiền có sẵn trong tài khoản, trong khi thẻ credit sử dụng hạn mức tín dụng.', 'The bank debited my account twice for the same purchase.', NULL, 'Ngân hàng đã trừ tiền trong tài khoản của tôi hai lần cho cùng một món hàng.', '{"wordId":"debit","ukIpa":"/ˈdebɪt/","usIpa":"/ˈdebɪt/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"An amount recorded as money taken from a bank account.","vi":"khoản tiền bị trừ; khoản ghi nợ"},{"pos":"v.","en":"To record money as taken from a bank account.","vi":"trừ tiền trong tài khoản; ghi nợ"}],"examples":[{"en":"The bank debited my account twice for the same purchase.","vi":"Ngân hàng đã trừ tiền trong tài khoản của tôi hai lần cho cùng một món hàng.","audioKind":"ex"},{"en":"Consumers should check bank statements regularly to identify any unexpected debits and report potential errors.","vi":"Người tiêu dùng nên thường xuyên kiểm tra sao kê ngân hàng để phát hiện các khoản trừ tiền bất ngờ và báo cáo những sai sót tiềm ẩn.","audioKind":"ex2"}],"collocations":[{"en":"debit card","vi":"thẻ ghi nợ"},{"en":"direct debit","vi":"trừ tiền tự động"},{"en":"debit an account","vi":"ghi nợ vào tài khoản"}],"wordFamily":[],"synonyms":[],"antonyms":["credit"],"tipVi":"Thẻ debit sử dụng tiền có sẵn trong tài khoản, trong khi thẻ credit sử dụng hạn mức tín dụng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unlimited', 'en-b2-55', 'unlimited', '/ʌnˈlɪmɪtɪd/', 'B2', 'vô hạn; không giới hạn; không hạn mức', 'adj.', 'limit (n.), limit (v.), limited (adj.), limitation (n.)', 'Đồng nghĩa: limitless, boundless, unrestricted · Trái nghĩa: limited, restricted', 'Biểu thị sự không bị giới hạn; không đồng nghĩa với uncertain (không chắc chắn).', 'Our hotel offers unlimited coffee with breakfast each morning.', NULL, 'Khách sạn của chúng tôi phục vụ cà phê không giới hạn vào bữa sáng mỗi buổi sáng.', '{"wordId":"unlimited","ukIpa":"/ʌnˈlɪmɪtɪd/","usIpa":"/ʌnˈlɪmɪtɪd/","cefr":"B2","topic":"economy","senses":[{"pos":"adj.","en":"not restricted in amount, number, or extent","vi":"vô hạn; không giới hạn; không hạn mức"}],"examples":[{"en":"Our hotel offers unlimited coffee with breakfast each morning.","vi":"Khách sạn của chúng tôi phục vụ cà phê không giới hạn vào bữa sáng mỗi buổi sáng.","audioKind":"ex"},{"en":"Economic growth cannot rely on unlimited consumption of natural resources without causing serious environmental damage.","vi":"Tăng trưởng kinh tế không thể dựa vào việc tiêu thụ tài nguyên thiên nhiên vô hạn mà không gây ra tổn hại nghiêm trọng cho môi trường.","audioKind":"ex2"}],"collocations":[{"en":"unlimited access","vi":"quyền truy cập không giới hạn"},{"en":"unlimited potential","vi":"tiềm năng vô hạn"},{"en":"unlimited resources","vi":"tài nguyên vô hạn"}],"wordFamily":["limit (n.)","limit (v.)","limited (adj.)","limitation (n.)"],"synonyms":["limitless","boundless","unrestricted"],"antonyms":["limited","restricted"],"tipVi":"Biểu thị sự không bị giới hạn; không đồng nghĩa với uncertain (không chắc chắn).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stimulate', 'en-b2-55', 'stimulate', '/ˈstɪmjəleɪt/', 'B2', 'thúc đẩy; khích lệ; kích thích; kích thích hoạt động sinh học', 'v.', 'stimulation (n.), stimulating (adj.), stimulant (n.)', 'Đồng nghĩa: encourage, spur · Trái nghĩa: inhibit', 'Kết hợp trực tiếp với tân ngữ: stimulate interest có nghĩa là khơi gợi sự quan tâm.', 'These colourful puzzles stimulate my daughter''s curiosity every morning.', NULL, 'Những câu đố đầy màu sắc này kích thích sự tò mò của con gái tôi mỗi buổi sáng.', '{"wordId":"stimulate","ukIpa":"/ˈstɪmjʊleɪt/","usIpa":"/ˈstɪmjəleɪt/","cefr":"B2","topic":"economy","senses":[{"pos":"v.","en":"to encourage something to develop or become more active","vi":"thúc đẩy; khích lệ; kích thích"},{"pos":"v.","en":"to make a body part or biological process more active","vi":"kích thích hoạt động sinh học"}],"examples":[{"en":"These colourful puzzles stimulate my daughter''s curiosity every morning.","vi":"Những câu đố đầy màu sắc này kích thích sự tò mò của con gái tôi mỗi buổi sáng.","audioKind":"ex"},{"en":"Lower borrowing costs can stimulate economic growth by encouraging businesses to invest in new equipment.","vi":"Chi phí vay thấp hơn có thể thúc đẩy tăng trưởng kinh tế bằng cách khuyến khích các doanh nghiệp đầu tư vào trang thiết bị mới.","audioKind":"ex2"}],"collocations":[{"en":"stimulate growth","vi":"thúc đẩy tăng trưởng"},{"en":"stimulate interest","vi":"khơi gợi sự quan tâm"},{"en":"stimulate demand","vi":"kích thích nhu cầu"},{"en":"stimulate the brain","vi":"kích thích hoạt động não bộ"}],"wordFamily":["stimulation (n.)","stimulating (adj.)","stimulant (n.)"],"synonyms":["encourage","spur"],"antonyms":["inhibit"],"tipVi":"Kết hợp trực tiếp với tân ngữ: stimulate interest có nghĩa là khơi gợi sự quan tâm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fund', 'en-b2-55', 'fund', '/fʌnd/', 'B2', 'quỹ; tiền quỹ; nguồn tài chính; ngân quỹ; tài trợ; cấp vốn', 'n.', 'funding (n.), funded (adj.), fundraiser (n.)', NULL, 'Quỹ chuyên biệt dùng a fund; khi chỉ chung nguồn tiền sẵn có thường dùng funds.', 'We started a small fund to repair the playground.', NULL, 'Chúng tôi đã lập một quỹ nhỏ để sửa chữa khu vui chơi.', '{"wordId":"fund","ukIpa":"/fʌnd/","usIpa":"/fʌnd/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"money saved or collected for a particular purpose","vi":"quỹ; tiền quỹ"},{"pos":"n.","en":"money available to spend, usually expressed in the plural","vi":"nguồn tài chính; ngân quỹ"},{"pos":"v.","en":"to provide money for an activity, organisation, or project","vi":"tài trợ; cấp vốn"}],"examples":[{"en":"We started a small fund to repair the playground.","vi":"Chúng tôi đã lập một quỹ nhỏ để sửa chữa khu vui chơi.","audioKind":"ex"},{"en":"Governments should fund research into renewable energy to reduce dependence on fossil fuels and improve energy security.","vi":"Chính phủ nên tài trợ cho các nghiên cứu về năng lượng tái tạo nhằm giảm sự phụ thuộc vào nhiên liệu hóa thạch và nâng cao an ninh năng lượng.","audioKind":"ex2"}],"collocations":[{"en":"raise funds","vi":"quyên góp gây quỹ"},{"en":"a pension fund","vi":"quỹ lương hưu"},{"en":"public funds","vi":"ngân sách công"},{"en":"fund research","vi":"tài trợ nghiên cứu"}],"wordFamily":["funding (n.)","funded (adj.)","fundraiser (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Quỹ chuyên biệt dùng a fund; khi chỉ chung nguồn tiền sẵn có thường dùng funds.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_guarantee', 'en-b2-55', 'guarantee', '/ˌɡærənˈtiː/', 'B2', 'bảo đảm; cam kết; sự bảo đảm; sự cam kết; cam kết bảo hành', 'v.', 'guaranteed (adj.), guarantor (n.)', 'Đồng nghĩa: assure, promise', 'Có thể kết hợp với động từ nguyên mẫu có to hoặc mệnh đề that; dùng under guarantee khi nói về thời gian bảo hành.', 'The shop guarantees to replace the kettle if it breaks.', NULL, 'Cửa hàng cam kết sẽ đổi ấm đun nước mới nếu nó bị hỏng.', '{"wordId":"guarantee","ukIpa":"/ˌɡærənˈtiː/","usIpa":"/ˌɡærənˈtiː/","cefr":"B2","topic":"economy","senses":[{"pos":"v.","en":"to promise something firmly or make an outcome certain","vi":"bảo đảm; cam kết"},{"pos":"n.","en":"a firm promise that something will happen or be done","vi":"sự bảo đảm; sự cam kết"},{"pos":"n.","en":"a promise to repair or replace a faulty product","vi":"cam kết bảo hành"}],"examples":[{"en":"The shop guarantees to replace the kettle if it breaks.","vi":"Cửa hàng cam kết sẽ đổi ấm đun nước mới nếu nó bị hỏng.","audioKind":"ex"},{"en":"Higher education does not guarantee employment, but it can significantly improve a person''s long-term career prospects.","vi":"Giáo dục đại học không đảm bảo việc làm, nhưng nó có thể cải thiện đáng kể triển vọng nghề nghiệp lâu dài của một người.","audioKind":"ex2"}],"collocations":[{"en":"guarantee that","vi":"bảo đảm rằng"},{"en":"guarantee access","vi":"bảo đảm quyền tiếp cận"},{"en":"under guarantee","vi":"còn trong thời gian bảo hành"},{"en":"money-back guarantee","vi":"cam kết hoàn tiền"}],"wordFamily":["guaranteed (adj.)","guarantor (n.)"],"synonyms":["assure","promise"],"antonyms":[],"tipVi":"Có thể kết hợp với động từ nguyên mẫu có to hoặc mệnh đề that; dùng under guarantee khi nói về thời gian bảo hành.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_debt', 'en-b2-55', 'debt', '/det/', 'B2', 'khoản nợ; tiền nợ; lòng biết ơn; sự mang ơn', 'n.', 'debtor (n.), indebted (adj.), indebtedness (n.)', NULL, 'Chữ b không phát âm; in debt nghĩa là đang mắc nợ.', 'She took an extra shift to pay off her debt.', NULL, 'Cô ấy đã làm thêm một ca để trả hết khoản nợ của mình.', '{"wordId":"debt","ukIpa":"/det/","usIpa":"/det/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"Money owed to a person, bank, or other organisation.","vi":"khoản nợ; tiền nợ"},{"pos":"n.","en":"A feeling of owing gratitude for help someone has given.","vi":"lòng biết ơn; sự mang ơn"}],"examples":[{"en":"She took an extra shift to pay off her debt.","vi":"Cô ấy đã làm thêm một ca để trả hết khoản nợ của mình.","audioKind":"ex"},{"en":"High levels of household debt can reduce consumer spending and make an economy more vulnerable to recession.","vi":"Mức độ nợ hộ gia đình cao có thể làm giảm chi tiêu của người tiêu dùng và khiến nền kinh tế dễ bị tổn thương hơn trước suy thoái.","audioKind":"ex2"}],"collocations":[{"en":"pay off a debt","vi":"trả hết nợ"},{"en":"be in debt","vi":"mắc nợ"},{"en":"national debt","vi":"nợ công; quốc nợ"},{"en":"a debt of gratitude","vi":"món nợ ân tình"}],"wordFamily":["debtor (n.)","indebted (adj.)","indebtedness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chữ b không phát âm; in debt nghĩa là đang mắc nợ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fortune', 'en-b2-55', 'fortune', '/ˈfɔːrtʃuːn/', 'B2', 'gia tài lớn; khối tài sản kếch xù; vận may; vận mệnh', 'n.', 'fortunate (adj.), fortunately (adv.), unfortunate (adj.), misfortune (n.)', 'Đồng nghĩa: wealth, luck', 'Khi chỉ số tiền lớn dùng a fortune; khi chỉ vận may thường không đếm được.', 'That tiny flat near the station costs a fortune.', NULL, 'Căn hộ nhỏ gần ga đó có giá đắt cắt cổ.', '{"wordId":"fortune","ukIpa":"/ˈfɔːtʃuːn/","usIpa":"/ˈfɔːrtʃuːn/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"A very large amount of money","vi":"gia tài lớn; khối tài sản kếch xù"},{"pos":"n.","en":"Luck or the events that shape someone''s life","vi":"vận may; vận mệnh"}],"examples":[{"en":"That tiny flat near the station costs a fortune.","vi":"Căn hộ nhỏ gần ga đó có giá đắt cắt cổ.","audioKind":"ex"},{"en":"Some entrepreneurs build a fortune by developing affordable products that meet previously overlooked needs.","vi":"Một số doanh nhân tạo dựng được cơ ngơi đồ sộ bằng cách phát triển các sản phẩm giá cả phải chăng đáp ứng những nhu cầu trước đây ít được chú ý.","audioKind":"ex2"}],"collocations":[{"en":"make a fortune","vi":"kiếm được khối tài sản lớn"},{"en":"cost a fortune","vi":"tốn rất nhiều tiền"},{"en":"good fortune","vi":"vận may"},{"en":"tell someone''s fortune","vi":"bói toán"}],"wordFamily":["fortunate (adj.)","fortunately (adv.)","unfortunate (adj.)","misfortune (n.)"],"synonyms":["wealth","luck"],"antonyms":[],"tipVi":"Khi chỉ số tiền lớn dùng a fortune; khi chỉ vận may thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_manufacture', 'en-b2-55', 'manufacture', '/ˌmænjəˈfæktʃər/', 'B2', 'sản xuất; chế tạo; sự sản xuất; quá trình sản xuất', 'v.', 'manufacturer (n.), manufacturing (n.)', 'Đồng nghĩa: produce, make', 'Thường chỉ việc nhà máy sản xuất hàng loạt; danh từ chỉ người/đơn vị sản xuất là manufacturer.', 'The factory manufactures bicycles that fold into small bags.', NULL, 'Nhà máy này sản xuất những chiếc xe đạp có thể gập gọn vào trong túi nhỏ.', '{"wordId":"manufacture","ukIpa":"/ˌmænjʊˈfæktʃə/","usIpa":"/ˌmænjəˈfæktʃər/","cefr":"B2","topic":"economy","senses":[{"pos":"v.","en":"to produce goods, usually in large quantities using machinery","vi":"sản xuất; chế tạo"},{"pos":"n.","en":"the process of producing goods, especially in factories","vi":"sự sản xuất; quá trình sản xuất"}],"examples":[{"en":"The factory manufactures bicycles that fold into small bags.","vi":"Nhà máy này sản xuất những chiếc xe đạp có thể gập gọn vào trong túi nhỏ.","audioKind":"ex"},{"en":"Companies that manufacture electronic devices should take greater responsibility for recycling their products at the end of use.","vi":"Các công ty sản xuất thiết bị điện tử nên gánh vác trách nhiệm lớn hơn trong việc tái chế sản phẩm của họ khi hết hạn sử dụng.","audioKind":"ex2"}],"collocations":[{"en":"manufacture goods","vi":"sản xuất hàng hóa"},{"en":"the manufacture of","vi":"việc sản xuất..."},{"en":"manufacturing industry","vi":"ngành công nghiệp sản xuất"},{"en":"manufacturing costs","vi":"chi phí sản xuất"}],"wordFamily":["manufacturer (n.)","manufacturing (n.)"],"synonyms":["produce","make"],"antonyms":[],"tipVi":"Thường chỉ việc nhà máy sản xuất hàng loạt; danh từ chỉ người/đơn vị sản xuất là manufacturer.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stability', 'en-b2-55', 'stability', '/stəˈbɪləti/', 'B2', 'sự ổn định; tính vững chắc', 'n.', 'stable (adj.), stabilise (v.), stabilisation (n.), instability (n.)', 'Đồng nghĩa: steadiness · Trái nghĩa: instability', 'Thường là danh từ không đếm được; tính từ tương ứng là stable và từ trái nghĩa là instability.', 'These wider legs give the table much better stability.', NULL, 'Những chân bàn rộng hơn này giúp chiếc bàn có độ vững chãi tốt hơn nhiều.', '{"wordId":"stability","ukIpa":"/stəˈbɪləti/","usIpa":"/stəˈbɪləti/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"The ability to remain steady and resist unwanted change","vi":"sự ổn định; tính vững chắc"}],"examples":[{"en":"These wider legs give the table much better stability.","vi":"Những chân bàn rộng hơn này giúp chiếc bàn có độ vững chãi tốt hơn nhiều.","audioKind":"ex"},{"en":"Economic stability encourages businesses to invest in new projects and gives households greater confidence about their financial future.","vi":"Sự ổn định kinh tế khuyến khích các doanh nghiệp đầu tư vào dự án mới và mang lại cho các hộ gia đình sự tự tin lớn hơn về tương lai tài chính của họ.","audioKind":"ex2"}],"collocations":[{"en":"economic stability","vi":"ổn định kinh tế"},{"en":"political stability","vi":"ổn định chính trị"},{"en":"financial stability","vi":"ổn định tài chính"},{"en":"maintain stability","vi":"duy trì sự ổn định"}],"wordFamily":["stable (adj.)","stabilise (v.)","stabilisation (n.)","instability (n.)"],"synonyms":["steadiness"],"antonyms":["instability"],"tipVi":"Thường là danh từ không đếm được; tính từ tương ứng là stable và từ trái nghĩa là instability.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_investment', 'en-b2-55', 'investment', '/ɪnˈvestmənt/', 'B2', 'khoản đầu tư; tiền đầu tư; sự đầu tư (thời gian hoặc công sức)', 'n.', 'invest (v.), investor (n.)', NULL, 'Thường đi kèm với giới từ in; khi chỉ hành động đầu tư nói chung thì thường là danh từ không đếm được.', 'Buying better tools was a good investment for our bakery.', NULL, 'Mua những dụng cụ tốt hơn là một khoản đầu tư đúng đắn cho tiệm bánh của chúng tôi.', '{"wordId":"investment","ukIpa":"/ɪnˈvestmənt/","usIpa":"/ɪnˈvestmənt/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"Money put into something with the aim of future profit.","vi":"khoản đầu tư; tiền đầu tư"},{"pos":"n.","en":"Time or effort spent on something expected to bring benefits.","vi":"sự đầu tư (thời gian hoặc công sức)"}],"examples":[{"en":"Buying better tools was a good investment for our bakery.","vi":"Mua những dụng cụ tốt hơn là một khoản đầu tư đúng đắn cho tiệm bánh của chúng tôi.","audioKind":"ex"},{"en":"Greater public investment in renewable energy could create jobs while reducing dependence on fossil fuels.","vi":"Việc gia tăng đầu tư công vào năng lượng tái tạo có thể tạo ra việc làm đồng thời giảm sự phụ thuộc vào nhiên liệu hóa thạch.","audioKind":"ex2"}],"collocations":[{"en":"investment in infrastructure","vi":"đầu tư cơ sở hạ tầng"},{"en":"foreign investment","vi":"đầu tư nước ngoài"},{"en":"return on investment","vi":"lợi nhuận đầu tư"},{"en":"an investment of time","vi":"sự đầu tư về thời gian"}],"wordFamily":["invest (v.)","investor (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường đi kèm với giới từ in; khi chỉ hành động đầu tư nói chung thì thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_repay', 'en-b2-55', 'repay', '/rɪˈpeɪ/', 'B2', 'trả lại; hoàn trả; báo đáp; đền đáp', 'v.', 'repayment (n.), repayable (adj.)', 'Đồng nghĩa: pay back, reimburse', 'Dạng quá khứ và quá khứ phân từ đều là repaid; không mang hàm ý trả thù.', 'I will repay the money when I get paid.', NULL, 'Tôi sẽ hoàn lại số tiền đó khi nhận được lương.', '{"wordId":"repay","ukIpa":"/rɪˈpeɪ/","usIpa":"/rɪˈpeɪ/","cefr":"B2","topic":"economy","senses":[{"pos":"v.","en":"to pay back money that you owe","vi":"trả lại; hoàn trả"},{"pos":"v.","en":"to give something in return for help or kindness","vi":"báo đáp; đền đáp"}],"examples":[{"en":"I will repay the money when I get paid.","vi":"Tôi sẽ hoàn lại số tiền đó khi nhận được lương.","audioKind":"ex"},{"en":"Graduates may struggle to repay their student loans if secure employment opportunities remain limited.","vi":"Sinh viên tốt nghiệp có thể gặp khó khăn trong việc trả nợ tiền học phí nếu cơ hội việc làm ổn định vẫn còn hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"repay a loan","vi":"trả khoản vay"},{"en":"repay a debt","vi":"trả nợ"},{"en":"repay someone''s kindness","vi":"đền đáp ân huệ của ai đó"}],"wordFamily":["repayment (n.)","repayable (adj.)"],"synonyms":["pay back","reimburse"],"antonyms":[],"tipVi":"Dạng quá khứ và quá khứ phân từ đều là repaid; không mang hàm ý trả thù.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_in-store', 'en-b2-55', 'in-store', '/ˌɪn ˈstɔːr/', 'B2', 'tại cửa hàng; trong cửa hàng (vật lý); tại cửa hàng (thay vì trực tuyến)', 'adj.', NULL, NULL, 'in-store chỉ việc diễn ra trong cửa hàng; "còn hàng" thường dùng "in stock".', 'The shop is offering free in-store cooking demonstrations today.', NULL, 'Hôm nay cửa hàng đang có chương trình biểu diễn nấu ăn miễn phí tại cửa hàng.', '{"wordId":"in-store","ukIpa":"/ˌɪn ˈstɔː/","usIpa":"/ˌɪn ˈstɔːr/","cefr":"B2","topic":"economy","senses":[{"pos":"adj.","en":"happening or available inside a physical shop","vi":"tại cửa hàng; trong cửa hàng (vật lý)"},{"pos":"adv.","en":"inside a physical shop rather than online","vi":"tại cửa hàng (thay vì trực tuyến)"}],"examples":[{"en":"The shop is offering free in-store cooking demonstrations today.","vi":"Hôm nay cửa hàng đang có chương trình biểu diễn nấu ăn miễn phí tại cửa hàng.","audioKind":"ex"},{"en":"Despite the growth of online shopping, in-store services remain important for customers who need personalised advice.","vi":"Bất chấp sự phát triển của mua sắm trực tuyến, dịch vụ tại cửa hàng vẫn rất quan trọng đối với những khách hàng cần tư vấn cá nhân hóa.","audioKind":"ex2"}],"collocations":[{"en":"in-store shopping","vi":"mua sắm tại cửa hàng"},{"en":"in-store services","vi":"dịch vụ tại cửa hàng"},{"en":"in-store promotion","vi":"khuyến mãi tại cửa hàng"},{"en":"available in-store","vi":"có sẵn tại cửa hàng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"in-store chỉ việc diễn ra trong cửa hàng; \"còn hàng\" thường dùng \"in stock\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_yield', 'en-b2-55', 'yield', '/jiːld/', 'B2', 'sinh ra; đem lại; sản lượng; lợi nhuận; nhượng bộ; chịu khuất phục; nhường đường', 'v.', 'yielding (adj.), unyielding (adj.)', NULL, 'yield results chỉ việc tạo ra kết quả; yield to chỉ việc nhượng bộ trước cái gì đó.', 'Our apple tree yielded three baskets of fruit.', NULL, 'Cây táo nhà chúng tôi đã cho ra ba sọt quả.', '{"wordId":"yield","ukIpa":"/jiːld/","usIpa":"/jiːld/","cefr":"B2","topic":"economy","senses":[{"pos":"v.","en":"Produce crops, profits, or other results","vi":"sinh ra; đem lại"},{"pos":"n.","en":"The amount of a crop, product, or profit produced","vi":"sản lượng; lợi nhuận"},{"pos":"v.","en":"Stop resisting, or allow someone else to go first","vi":"nhượng bộ; chịu khuất phục; nhường đường"}],"examples":[{"en":"Our apple tree yielded three baskets of fruit.","vi":"Cây táo nhà chúng tôi đã cho ra ba sọt quả.","audioKind":"ex"},{"en":"Investment in agricultural research can yield substantial benefits for food security without expanding farmland.","vi":"Đầu tư vào nghiên cứu nông nghiệp có thể mang lại lợi ích đáng kể cho an ninh lương thực mà không cần mở rộng diện tích đất canh tác.","audioKind":"ex2"}],"collocations":[{"en":"yield results","vi":"mang lại kết quả"},{"en":"crop yield","vi":"sản lượng cây trồng"},{"en":"yield to pressure","vi":"khuất phục trước áp lực"},{"en":"yield to pedestrians","vi":"nhường đường cho người đi bộ"}],"wordFamily":["yielding (adj.)","unyielding (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"yield results chỉ việc tạo ra kết quả; yield to chỉ việc nhượng bộ trước cái gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_financing', 'en-b2-55', 'financing', '/ˈfaɪnænsɪŋ/', 'B2', 'tài chính; sự cấp vốn; việc thu xếp vốn', 'n.', 'finance (n.), finance (v.), financial (adj.), financially (adv.)', 'Đồng nghĩa: funding', 'Chỉ việc cung cấp hoặc huy động tiền vốn; lĩnh vực tài chính thường dùng finance.', 'We need financing before we can open the bakery.', NULL, 'Chúng tôi cần có vốn trước khi có thể mở tiệm bánh.', '{"wordId":"financing","ukIpa":"/ˈfaɪnænsɪŋ/","usIpa":"/ˈfaɪnænsɪŋ/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"the provision of money for a purchase, business, or project","vi":"tài chính; sự cấp vốn; việc thu xếp vốn"}],"examples":[{"en":"We need financing before we can open the bakery.","vi":"Chúng tôi cần có vốn trước khi có thể mở tiệm bánh.","audioKind":"ex"},{"en":"Access to affordable financing allows small businesses to invest in cleaner technology and create local jobs.","vi":"Việc tiếp cận nguồn tài chính vừa túi tiền cho phép các doanh nghiệp nhỏ đầu tư vào công nghệ sạch hơn và tạo ra nhiều việc làm tại địa phương.","audioKind":"ex2"}],"collocations":[{"en":"secure financing","vi":"đảm bảo nguồn vốn"},{"en":"project financing","vi":"tài trợ dự án"},{"en":"financing costs","vi":"chi phí tài chính"}],"wordFamily":["finance (n.)","finance (v.)","financial (adj.)","financially (adv.)"],"synonyms":["funding"],"antonyms":[],"tipVi":"Chỉ việc cung cấp hoặc huy động tiền vốn; lĩnh vực tài chính thường dùng finance.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shipment', 'en-b2-55', 'shipment', '/ˈʃɪpmənt/', 'B2', 'lô hàng; sự vận chuyển hàng hóa', 'n.', 'ship (v.), shipping (n.), shipper (n.)', 'Đồng nghĩa: consignment', 'Chỉ một lô hàng thì đếm được; chỉ quá trình vận chuyển thì không đếm được.', 'The shop received a fresh shipment of apples today.', NULL, 'Cửa hàng đã nhận được một lô táo mới vào hôm nay.', '{"wordId":"shipment","ukIpa":"/ˈʃɪpmənt/","usIpa":"/ˈʃɪpmənt/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"A quantity of goods sent together to a destination.","vi":"lô hàng"},{"pos":"n.","en":"The process of sending goods from one place to another.","vi":"sự vận chuyển hàng hóa"}],"examples":[{"en":"The shop received a fresh shipment of apples today.","vi":"Cửa hàng đã nhận được một lô táo mới vào hôm nay.","audioKind":"ex"},{"en":"Delays in the shipment of essential materials can increase production costs and disrupt international supply chains.","vi":"Sự chậm trễ trong việc vận chuyển các nguyên liệu thiết yếu có thể làm tăng chi phí sản xuất và làm gián đoạn chuỗi cung ứng quốc tế.","audioKind":"ex2"}],"collocations":[{"en":"a shipment of goods","vi":"một lô hàng"},{"en":"receive a shipment","vi":"nhận một lô hàng"},{"en":"ready for shipment","vi":"sẵn sàng để vận chuyển"}],"wordFamily":["ship (v.)","shipping (n.)","shipper (n.)"],"synonyms":["consignment"],"antonyms":[],"tipVi":"Chỉ một lô hàng thì đếm được; chỉ quá trình vận chuyển thì không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_importer', 'en-b2-55', 'importer', '/ɪmˈpɔːrtɚ/', 'B2', 'nhà nhập khẩu; nước nhập khẩu', 'n.', 'import (v.), import (n.), importation (n.)', 'Trái nghĩa: exporter', 'Có thể chỉ thương nhân hoặc quốc gia nhập khẩu hàng hóa.', 'The importer showed us coffee beans from several countries.', NULL, 'Nhà nhập khẩu đã cho chúng tôi xem hạt cà phê từ nhiều quốc gia khác nhau.', '{"wordId":"importer","ukIpa":"/ɪmˈpɔːtə/","usIpa":"/ɪmˈpɔːrtɚ/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"A person, company, or country buying goods from abroad.","vi":"nhà nhập khẩu; nước nhập khẩu"}],"examples":[{"en":"The importer showed us coffee beans from several countries.","vi":"Nhà nhập khẩu đã cho chúng tôi xem hạt cà phê từ nhiều quốc gia khác nhau.","audioKind":"ex"},{"en":"A country that becomes a major food importer may face greater exposure to international price fluctuations.","vi":"Một quốc gia trở thành nước nhập khẩu lương thực lớn có thể phải đối mặt với mức độ rủi ro cao hơn trước sự biến động của giá cả quốc tế.","audioKind":"ex2"}],"collocations":[{"en":"major importer","vi":"nhà nhập khẩu lớn; quốc gia nhập khẩu lớn"},{"en":"net importer","vi":"nước nhập khẩu ròng"},{"en":"food importer","vi":"nhà nhập khẩu thực phẩm"}],"wordFamily":["import (v.)","import (n.)","importation (n.)"],"synonyms":[],"antonyms":["exporter"],"tipVi":"Có thể chỉ thương nhân hoặc quốc gia nhập khẩu hàng hóa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_boost', 'en-b2-55', 'boost', '/buːst/', 'B2', 'thúc đẩy; tăng cường; nâng cao; sự thúc đẩy; sự gia tăng; sự nâng cao', 'v.', 'booster (n.)', 'Đồng nghĩa: increase, improve, enhance · Trái nghĩa: reduce', 'Là ngoại động từ, đi thẳng theo sau là các tân ngữ như doanh số, niềm tin.', 'A short walk can boost your energy after lunch.', NULL, 'Đi bộ một chút có thể giúp bạn tràn đầy năng lượng hơn sau bữa trưa.', '{"wordId":"boost","ukIpa":"/buːst/","usIpa":"/buːst/","cefr":"B2","topic":"economy","senses":[{"pos":"v.","en":"to increase or improve something","vi":"thúc đẩy; tăng cường; nâng cao"},{"pos":"n.","en":"something that helps increase or improve something else","vi":"sự thúc đẩy; sự gia tăng; sự nâng cao"}],"examples":[{"en":"A short walk can boost your energy after lunch.","vi":"Đi bộ một chút có thể giúp bạn tràn đầy năng lượng hơn sau bữa trưa.","audioKind":"ex"},{"en":"Investment in reliable public transport can boost local employment and improve access to essential services.","vi":"Đầu tư vào hệ thống giao thông công cộng đáng tin cậy có thể thúc đẩy việc làm địa phương và giúp người dân dễ dàng tiếp cận các dịch vụ thiết yếu hơn.","audioKind":"ex2"}],"collocations":[{"en":"boost confidence","vi":"củng cố niềm tin"},{"en":"boost the economy","vi":"thúc đẩy nền kinh tế"},{"en":"boost sales","vi":"tăng doanh số"},{"en":"give something a boost","vi":"tạo cú hích cho cái gì"}],"wordFamily":["booster (n.)"],"synonyms":["increase","improve","enhance"],"antonyms":["reduce"],"tipVi":"Là ngoại động từ, đi thẳng theo sau là các tân ngữ như doanh số, niềm tin.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_commercial', 'en-b2-55', 'commercial', '/kəˈmɝːʃəl/', 'B2', 'thuộc về thương mại; mang tính kinh doanh; có lợi nhuận; quảng cáo trên truyền hình hoặc phát thanh', 'adj.', 'commerce (n.), commercially (adv.), commercialise (v.), commercialisation (n.)', 'Trái nghĩa: non-commercial', 'Khi đóng vai trò là danh từ, commercial chỉ dùng riêng cho quảng cáo trên TV hoặc radio, không dùng chung cho mọi loại quảng cáo.', 'This street has homes above its commercial premises.', NULL, 'Con phố này có các căn hộ nằm phía trên các khu vực kinh doanh thương mại.', '{"wordId":"commercial","ukIpa":"/kəˈmɜːʃəl/","usIpa":"/kəˈmɝːʃəl/","cefr":"B2","topic":"economy","senses":[{"pos":"adj.","en":"Related to business or intended to make money.","vi":"thuộc về thương mại; mang tính kinh doanh; có lợi nhuận"},{"pos":"n.","en":"An advertisement broadcast on television or radio.","vi":"quảng cáo trên truyền hình hoặc phát thanh"}],"examples":[{"en":"This street has homes above its commercial premises.","vi":"Con phố này có các căn hộ nằm phía trên các khu vực kinh doanh thương mại.","audioKind":"ex"},{"en":"Commercial development can create jobs, but it should not come at the expense of public green spaces.","vi":"Sự phát triển thương mại có thể tạo ra việc làm, nhưng không nên đánh đổi bằng các không gian xanh công cộng.","audioKind":"ex2"}],"collocations":[{"en":"commercial development","vi":"phát triển thương mại"},{"en":"commercial success","vi":"thành công thương mại"},{"en":"commercial purposes","vi":"mục đích thương mại"},{"en":"a television commercial","vi":"quảng cáo truyền hình"}],"wordFamily":["commerce (n.)","commercially (adv.)","commercialise (v.)","commercialisation (n.)"],"synonyms":[],"antonyms":["non-commercial"],"tipVi":"Khi đóng vai trò là danh từ, commercial chỉ dùng riêng cho quảng cáo trên TV hoặc radio, không dùng chung cho mọi loại quảng cáo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shortage', 'en-b2-55', 'shortage', '/ˈʃɔːrtɪdʒ/', 'B2', 'sự thiếu hụt; tình trạng khan hiếm', 'n.', 'short (adj.), shorten (v.)', 'Đồng nghĩa: scarcity, lack · Trái nghĩa: surplus, abundance', 'Thường dùng cấu trúc a shortage of; nói "thiếu" cũng có thể dùng be short of.', 'A water shortage forced us to take shorter showers.', NULL, 'Tình trạng thiếu nước buộc chúng tôi phải tắm nhanh hơn.', '{"wordId":"shortage","ukIpa":"/ˈʃɔːtɪdʒ/","usIpa":"/ˈʃɔːrtɪdʒ/","cefr":"B2","topic":"economy","senses":[{"pos":"n.","en":"a situation in which there is not enough of something","vi":"sự thiếu hụt; tình trạng khan hiếm"}],"examples":[{"en":"A water shortage forced us to take shorter showers.","vi":"Tình trạng thiếu nước buộc chúng tôi phải tắm nhanh hơn.","audioKind":"ex"},{"en":"A shortage of affordable housing can force essential workers to live far from their workplaces.","vi":"Tình trạng thiếu nhà ở giá rẻ có thể buộc những người lao động thiết yếu phải sống xa nơi làm việc của họ.","audioKind":"ex2"}],"collocations":[{"en":"a shortage of","vi":"sự thiếu hụt cái gì"},{"en":"labour shortage","vi":"tình trạng thiếu lao động"},{"en":"severe shortage","vi":"sự thiếu hụt trầm trọng"},{"en":"housing shortage","vi":"tình trạng thiếu nhà ở"}],"wordFamily":["short (adj.)","shorten (v.)"],"synonyms":["scarcity","lack"],"antonyms":["surplus","abundance"],"tipVi":"Thường dùng cấu trúc a shortage of; nói \"thiếu\" cũng có thể dùng be short of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_55_1', 'en-b2-55', 'Cách dùng “commercial” (adj.) — thuộc về thương mại; mang tính kinh doanh; có lợi nhuận', 'commercial development  ·  commercial success  ·  commercial purposes', 'Khi đóng vai trò là danh từ, commercial chỉ dùng riêng cho quảng cáo trên TV hoặc radio, không dùng chung cho mọi loại quảng cáo.', 'Họ từ (Word Family): commerce (n.), commercially (adv.), commercialise (v.), commercialisation (n.) | Trái nghĩa: non-commercial', '[{"hanzi":"This street has homes above its commercial premises.","pinyin":"","meaning":"Con phố này có các căn hộ nằm phía trên các khu vực kinh doanh thương mại."},{"hanzi":"Commercial development can create jobs, but it should not come at the expense of public green spaces.","pinyin":"","meaning":"Sự phát triển thương mại có thể tạo ra việc làm, nhưng không nên đánh đổi bằng các không gian xanh công cộng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_55_2', 'en-b2-55', 'Cách dùng “guarantee” (v.) — bảo đảm; cam kết', 'guarantee that  ·  guarantee access  ·  under guarantee', 'Có thể kết hợp với động từ nguyên mẫu có to hoặc mệnh đề that; dùng under guarantee khi nói về thời gian bảo hành.', 'Họ từ (Word Family): guaranteed (adj.), guarantor (n.) | Đồng nghĩa: assure, promise', '[{"hanzi":"The shop guarantees to replace the kettle if it breaks.","pinyin":"","meaning":"Cửa hàng cam kết sẽ đổi ấm đun nước mới nếu nó bị hỏng."},{"hanzi":"Higher education does not guarantee employment, but it can significantly improve a person''s long-term career prospects.","pinyin":"","meaning":"Giáo dục đại học không đảm bảo việc làm, nhưng nó có thể cải thiện đáng kể triển vọng nghề nghiệp lâu dài của một người."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_55_3', 'en-b2-55', 'Cách dùng “investment” (n.) — khoản đầu tư; tiền đầu tư', 'investment in infrastructure  ·  foreign investment  ·  return on investment', 'Thường đi kèm với giới từ in; khi chỉ hành động đầu tư nói chung thì thường là danh từ không đếm được.', 'Họ từ (Word Family): invest (v.), investor (n.)', '[{"hanzi":"Buying better tools was a good investment for our bakery.","pinyin":"","meaning":"Mua những dụng cụ tốt hơn là một khoản đầu tư đúng đắn cho tiệm bánh của chúng tôi."},{"hanzi":"Greater public investment in renewable energy could create jobs while reducing dependence on fossil fuels.","pinyin":"","meaning":"Việc gia tăng đầu tư công vào năng lượng tái tạo có thể tạo ra việc làm đồng thời giảm sự phụ thuộc vào nhiên liệu hóa thạch."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_55_4', 'en-b2-55', 'Cách dùng “manufacture” (v.) — sản xuất; chế tạo', 'manufacture goods  ·  the manufacture of  ·  manufacturing industry', 'Thường chỉ việc nhà máy sản xuất hàng loạt; danh từ chỉ người/đơn vị sản xuất là manufacturer.', 'Họ từ (Word Family): manufacturer (n.), manufacturing (n.) | Đồng nghĩa: produce, make', '[{"hanzi":"The factory manufactures bicycles that fold into small bags.","pinyin":"","meaning":"Nhà máy này sản xuất những chiếc xe đạp có thể gập gọn vào trong túi nhỏ."},{"hanzi":"Companies that manufacture electronic devices should take greater responsibility for recycling their products at the end of use.","pinyin":"","meaning":"Các công ty sản xuất thiết bị điện tử nên gánh vác trách nhiệm lớn hơn trong việc tái chế sản phẩm của họ khi hết hạn sử dụng."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_55_1', 'en-b2-55', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_55_1_1', 'ten_b2_55_1', 'recession', 'During the recession, my uncle struggled to find work.', 'During the recession, my uncle struggled to find work.', '/rɪˈseʃən/', 'Trong thời kỳ suy thoái, chú tôi rất chật vật để tìm việc làm.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_55_1_2', 'ten_b2_55_1', 'insure', 'We insured our bicycles before taking them abroad.', 'We insured our bicycles before taking them abroad.', '/ɪnˈʃʊr/', 'Chúng tôi đã mua bảo hiểm cho xe đạp trước khi đem chúng ra nước ngoài.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_55_1_3', 'ten_b2_55_1', 'debit', 'The bank debited my account twice for the same purchase.', 'The bank debited my account twice for the same purchase.', '/ˈdebɪt/', 'Ngân hàng đã trừ tiền trong tài khoản của tôi hai lần cho cùng một món hàng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_55_1_4', 'ten_b2_55_1', 'unlimited', 'Our hotel offers unlimited coffee with breakfast each morning.', 'Our hotel offers unlimited coffee with breakfast each morning.', '/ʌnˈlɪmɪtɪd/', 'Khách sạn của chúng tôi phục vụ cà phê không giới hạn vào bữa sáng mỗi buổi sáng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_55_1_5', 'ten_b2_55_1', 'stimulate', 'These colourful puzzles stimulate my daughter''s curiosity every morning.', 'These colourful puzzles stimulate my daughter''s curiosity every morning.', '/ˈstɪmjəleɪt/', 'Những câu đố đầy màu sắc này kích thích sự tò mò của con gái tôi mỗi buổi sáng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_55_1_6', 'ten_b2_55_1', 'fund', 'We started a small fund to repair the playground.', 'We started a small fund to repair the playground.', '/fʌnd/', 'Chúng tôi đã lập một quỹ nhỏ để sửa chữa khu vui chơi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_55_1_7', 'ten_b2_55_1', 'guarantee', 'The shop guarantees to replace the kettle if it breaks.', 'The shop guarantees to replace the kettle if it breaks.', '/ˌɡærənˈtiː/', 'Cửa hàng cam kết sẽ đổi ấm đun nước mới nếu nó bị hỏng.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_55_1_8', 'ten_b2_55_1', 'debt', 'She took an extra shift to pay off her debt.', 'She took an extra shift to pay off her debt.', '/det/', 'Cô ấy đã làm thêm một ca để trả hết khoản nợ của mình.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_55_1_1', 'en-b2-55', 'ten_b2_55_1', 'listening', 'listening', 'During the recession, my uncle struggled to find work.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Trong thời kỳ suy thoái, chú tôi rất chật vật để tìm việc làm.","Chúng tôi đã lập một quỹ nhỏ để sửa chữa khu vui chơi.","Con phố này có các căn hộ nằm phía trên các khu vực kinh doanh thương mại.","Tình trạng thiếu nước buộc chúng tôi phải tắm nhanh hơn."]'::jsonb, 0, 'During the recession, my uncle struggled to find work. → Trong thời kỳ suy thoái, chú tôi rất chật vật để tìm việc làm.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_55_1_2', 'en-b2-55', 'ten_b2_55_1', 'listening', 'listening', 'We insured our bicycles before taking them abroad.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những chân bàn rộng hơn này giúp chiếc bàn có độ vững chãi tốt hơn nhiều.","Chúng tôi đã mua bảo hiểm cho xe đạp trước khi đem chúng ra nước ngoài.","Trong thời kỳ suy thoái, chú tôi rất chật vật để tìm việc làm.","Khách sạn của chúng tôi phục vụ cà phê không giới hạn vào bữa sáng mỗi buổi sáng."]'::jsonb, 1, 'We insured our bicycles before taking them abroad. → Chúng tôi đã mua bảo hiểm cho xe đạp trước khi đem chúng ra nước ngoài.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_55_1_3', 'en-b2-55', 'ten_b2_55_1', 'listening', 'listening', 'The bank debited my account twice for the same purchase.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Ngân hàng đã trừ tiền trong tài khoản của tôi hai lần cho cùng một món hàng.","Cửa hàng đã nhận được một lô táo mới vào hôm nay.","Tình trạng thiếu nước buộc chúng tôi phải tắm nhanh hơn.","Những chân bàn rộng hơn này giúp chiếc bàn có độ vững chãi tốt hơn nhiều."]'::jsonb, 0, 'The bank debited my account twice for the same purchase. → Ngân hàng đã trừ tiền trong tài khoản của tôi hai lần cho cùng một món hàng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_55_2', 'en-b2-55', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_55_2_1', 'ten_b2_55_2', 'recession', 'Governments may increase public investment during a recession to protect jobs and stimulate consumer demand.', 'Governments may increase public investment during a recession to protect jobs and stimulate consumer demand.', '/rɪˈseʃən/', 'Các chính phủ có thể tăng đầu tư công trong thời kỳ suy thoái để bảo vệ việc làm và kích thích nhu cầu tiêu dùng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_55_2_2', 'ten_b2_55_2', 'insure', 'Small businesses should insure their premises against fire to avoid potentially devastating financial losses.', 'Small businesses should insure their premises against fire to avoid potentially devastating financial losses.', '/ɪnˈʃʊr/', 'Các doanh nghiệp nhỏ nên mua bảo hiểm hỏa hoạn cho cơ sở kinh doanh của mình để tránh những tổn thất tài chính có thể gây ra hậu quả tàn khốc.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_55_2_3', 'ten_b2_55_2', 'debit', 'Consumers should check bank statements regularly to identify any unexpected debits and report potential errors.', 'Consumers should check bank statements regularly to identify any unexpected debits and report potential errors.', '/ˈdebɪt/', 'Người tiêu dùng nên thường xuyên kiểm tra sao kê ngân hàng để phát hiện các khoản trừ tiền bất ngờ và báo cáo những sai sót tiềm ẩn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_55_2_4', 'ten_b2_55_2', 'unlimited', 'Economic growth cannot rely on unlimited consumption of natural resources without causing serious environmental damage.', 'Economic growth cannot rely on unlimited consumption of natural resources without causing serious environmental damage.', '/ʌnˈlɪmɪtɪd/', 'Tăng trưởng kinh tế không thể dựa vào việc tiêu thụ tài nguyên thiên nhiên vô hạn mà không gây ra tổn hại nghiêm trọng cho môi trường.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_55_2_5', 'ten_b2_55_2', 'stimulate', 'Lower borrowing costs can stimulate economic growth by encouraging businesses to invest in new equipment.', 'Lower borrowing costs can stimulate economic growth by encouraging businesses to invest in new equipment.', '/ˈstɪmjəleɪt/', 'Chi phí vay thấp hơn có thể thúc đẩy tăng trưởng kinh tế bằng cách khuyến khích các doanh nghiệp đầu tư vào trang thiết bị mới.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_55_2_6', 'ten_b2_55_2', 'fund', 'Governments should fund research into renewable energy to reduce dependence on fossil fuels and improve energy security.', 'Governments should fund research into renewable energy to reduce dependence on fossil fuels and improve energy security.', '/fʌnd/', 'Chính phủ nên tài trợ cho các nghiên cứu về năng lượng tái tạo nhằm giảm sự phụ thuộc vào nhiên liệu hóa thạch và nâng cao an ninh năng lượng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_55_2_1', 'en-b2-55', 'ten_b2_55_2', 'listening', 'listening', 'Governments may increase public investment during a recession to protect jobs and stimulate consumer demand.', NULL, 'Trong câu vừa nghe, từ “recession” mang nghĩa nào sau đây?', '["suy thoái kinh tế; thời kỳ kinh tế sụt giảm","sự đặt mua; sự đăng ký dài hạn","bị xói mòn; bị bào mòn","hợp lý; logic"]'::jsonb, 0, '“recession” (/rɪˈseʃən/): suy thoái kinh tế; thời kỳ kinh tế sụt giảm. Câu đầy đủ: Governments may increase public investment during a recession to protect jobs and stimulate consumer demand.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_55_2_2', 'en-b2-55', 'ten_b2_55_2', 'listening', 'listening', 'Small businesses should insure their premises against fire to avoid potentially devastating financial losses.', NULL, 'Trong câu vừa nghe, từ “insure” mang nghĩa nào sau đây?', '["thay đổi; dễ biến động","bão tuyết","mua bảo hiểm cho; bảo hiểm","sự cần thiết; tính tất yếu"]'::jsonb, 2, '“insure” (/ɪnˈʃʊr/): mua bảo hiểm cho; bảo hiểm. Câu đầy đủ: Small businesses should insure their premises against fire to avoid potentially devastating financial losses.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
