INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_55_1', 'en-b2-55', NULL, 'comprehensive_test', 'listening', 'recession', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đáng chú ý; nổi bật; rõ rệt","thở dài","máy phát điện","suy thoái kinh tế; thời kỳ kinh tế sụt giảm"]'::jsonb, 3, 'recession (/rɪˈseʃən/) → suy thoái kinh tế; thời kỳ kinh tế sụt giảm; sự lùi lại; sự thụt lùi', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_55_2', 'en-b2-55', NULL, 'comprehensive_test', 'listening', 'We insured our bicycles before taking them abroad.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cửa hàng cam kết sẽ đổi ấm đun nước mới nếu nó bị hỏng.","Chúng tôi đã mua bảo hiểm cho xe đạp trước khi đem chúng ra nước ngoài.","Cửa hàng đã nhận được một lô táo mới vào hôm nay.","Những chân bàn rộng hơn này giúp chiếc bàn có độ vững chãi tốt hơn nhiều."]'::jsonb, 1, 'We insured our bicycles before taking them abroad. → Chúng tôi đã mua bảo hiểm cho xe đạp trước khi đem chúng ra nước ngoài.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_55_3', 'en-b2-55', NULL, 'comprehensive_test', 'listening', 'debit', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["khoản tiền bị trừ; khoản ghi nợ","ẩm ướt; ẩm thấp","vô cùng quan trọng; thiết yếu","riêng biệt; đặc biệt, chuyên dụng"]'::jsonb, 0, 'debit (/ˈdebɪt/) → khoản tiền bị trừ; khoản ghi nợ; trừ tiền trong tài khoản; ghi nợ', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_55_4', 'en-b2-55', NULL, 'comprehensive_test', 'listening', 'Our hotel offers unlimited coffee with breakfast each morning.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Căn hộ nhỏ gần ga đó có giá đắt cắt cổ.","Những câu đố đầy màu sắc này kích thích sự tò mò của con gái tôi mỗi buổi sáng.","Khách sạn của chúng tôi phục vụ cà phê không giới hạn vào bữa sáng mỗi buổi sáng.","Trong thời kỳ suy thoái, chú tôi rất chật vật để tìm việc làm."]'::jsonb, 2, 'Our hotel offers unlimited coffee with breakfast each morning. → Khách sạn của chúng tôi phục vụ cà phê không giới hạn vào bữa sáng mỗi buổi sáng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_55_5', 'en-b2-55', NULL, 'comprehensive_test', 'listening', 'stimulate', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thúc đẩy; khích lệ; kích thích","đáng kể; rất nhiều; vô cùng","sự căng thẳng (quan hệ); tình hình căng thẳng","khoa (trong trường đại học)"]'::jsonb, 0, 'stimulate (/ˈstɪmjəleɪt/) → thúc đẩy; khích lệ; kích thích; kích thích hoạt động sinh học', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_55_6', 'en-b2-55', NULL, 'comprehensive_test', 'listening', 'We started a small fund to repair the playground.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Khách sạn của chúng tôi phục vụ cà phê không giới hạn vào bữa sáng mỗi buổi sáng.","Cây táo nhà chúng tôi đã cho ra ba sọt quả.","Chúng tôi đã lập một quỹ nhỏ để sửa chữa khu vui chơi.","Ngân hàng đã trừ tiền trong tài khoản của tôi hai lần cho cùng một món hàng."]'::jsonb, 2, 'We started a small fund to repair the playground. → Chúng tôi đã lập một quỹ nhỏ để sửa chữa khu vui chơi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_55_7', 'en-b2-55', NULL, 'comprehensive_test', 'listening', 'guarantee', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["khẩu hiệu; biểu ngữ","bảo đảm; cam kết","phương tiện thông tin đại chúng; đại chúng truyền thông","ma sát; lực ma sát"]'::jsonb, 1, 'guarantee (/ˌɡærənˈtiː/) → bảo đảm; cam kết; sự bảo đảm; sự cam kết; cam kết bảo hành', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_55_8', 'en-b2-55', NULL, 'comprehensive_test', 'listening', 'She took an extra shift to pay off her debt.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hôm nay cửa hàng đang có chương trình biểu diễn nấu ăn miễn phí tại cửa hàng.","Chúng tôi đã mua bảo hiểm cho xe đạp trước khi đem chúng ra nước ngoài.","Cô ấy đã làm thêm một ca để trả hết khoản nợ của mình.","Chúng tôi đã lập một quỹ nhỏ để sửa chữa khu vui chơi."]'::jsonb, 2, 'She took an extra shift to pay off her debt. → Cô ấy đã làm thêm một ca để trả hết khoản nợ của mình.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_55_9', 'en-b2-55', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to encourage something to develop or become more active”?', '["financing","debt","repay","stimulate"]'::jsonb, 3, 'stimulate (/ˈstɪmjəleɪt/) → thúc đẩy; khích lệ; kích thích', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_55_10', 'en-b2-55', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “money saved or collected for a particular purpose”?', '["fund","debit","unlimited","insure"]'::jsonb, 0, 'fund (/fʌnd/) → quỹ; tiền quỹ', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_55_11', 'en-b2-55', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to promise something firmly or make an outcome certain”?', '["insure","stimulate","guarantee","unlimited"]'::jsonb, 2, 'guarantee (/ˌɡærənˈtiː/) → bảo đảm; cam kết', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_55_12', 'en-b2-55', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Money owed to a person, bank, or other organisation.”?', '["debt","importer","yield","recession"]'::jsonb, 0, 'debt (/det/) → khoản nợ; tiền nợ', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
