INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_55_18', 'en-b2-55', NULL, 'comprehensive_test', 'reading', NULL, 'Governments may increase public investment during a recession to protect jobs and stimulate consumer demand.', 'Dựa vào câu trên, từ “recession” có nghĩa phù hợp nhất là gì?', '["hơn nữa; ngoài ra","vụng về; lóng ngóng","việc vặt; chuyến đi ngắn để mua, lấy hoặc giao đồ","suy thoái kinh tế; thời kỳ kinh tế sụt giảm"]'::jsonb, 3, 'recession: suy thoái kinh tế; thời kỳ kinh tế sụt giảm; sự lùi lại; sự thụt lùi. Dịch cả câu: Các chính phủ có thể tăng đầu tư công trong thời kỳ suy thoái để bảo vệ việc làm và kích thích nhu cầu tiêu dùng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_55_19', 'en-b2-55', NULL, 'comprehensive_test', 'reading', NULL, 'Small businesses should insure their premises against fire to avoid potentially devastating financial losses.', 'Dựa vào câu trên, từ “insure” có nghĩa phù hợp nhất là gì?', '["mua bảo hiểm cho; bảo hiểm","ra-đa; hệ thống định vị bằng sóng vô tuyến","linh hoạt; dễ thích ứng","làm nổi bật; nhấn mạnh"]'::jsonb, 0, 'insure: mua bảo hiểm cho; bảo hiểm. Dịch cả câu: Các doanh nghiệp nhỏ nên mua bảo hiểm hỏa hoạn cho cơ sở kinh doanh của mình để tránh những tổn thất tài chính có thể gây ra hậu quả tàn khốc.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_55_20', 'en-b2-55', NULL, 'comprehensive_test', 'reading', NULL, 'Consumers should check bank statements regularly to identify any unexpected debits and report potential errors.', 'Dựa vào câu trên, từ “debit” có nghĩa phù hợp nhất là gì?', '["trên không; từ trên không","cột; trụ (cấu trúc chống đỡ)","khoản tiền bị trừ; khoản ghi nợ","tin học hóa; tự động hóa bằng máy tính (sử dụng máy tính để quản lý một công việc, hệ thống hoặc thông tin)"]'::jsonb, 2, 'debit: khoản tiền bị trừ; khoản ghi nợ; trừ tiền trong tài khoản; ghi nợ. Dịch cả câu: Người tiêu dùng nên thường xuyên kiểm tra sao kê ngân hàng để phát hiện các khoản trừ tiền bất ngờ và báo cáo những sai sót tiềm ẩn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_55_21', 'en-b2-55', NULL, 'comprehensive_test', 'reading', NULL, 'Economic growth cannot rely on unlimited consumption of natural resources without causing serious environmental damage.', 'Dựa vào câu trên, từ “unlimited” có nghĩa phù hợp nhất là gì?', '["vô hạn; không giới hạn; không hạn mức","số mệnh; định mệnh","calo (đơn vị đo nhiệt lượng hoặc năng lượng từ thức ăn)","kẻ móc túi; tên trộm vặt nơi công cộng"]'::jsonb, 0, 'unlimited: vô hạn; không giới hạn; không hạn mức. Dịch cả câu: Tăng trưởng kinh tế không thể dựa vào việc tiêu thụ tài nguyên thiên nhiên vô hạn mà không gây ra tổn hại nghiêm trọng cho môi trường.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_55_22', 'en-b2-55', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thúc đẩy; tăng cường; nâng cao”', '["identification","leak","boost","aroma"]'::jsonb, 2, 'thúc đẩy; tăng cường; nâng cao → boost (/buːst/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_55_23', 'en-b2-55', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thuộc về thương mại; mang tính kinh doanh; có lợi nhuận”', '["subscription","horizontal","commercial","slip"]'::jsonb, 2, 'thuộc về thương mại; mang tính kinh doanh; có lợi nhuận → commercial (/kəˈmɝːʃəl/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_55_24', 'en-b2-55', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự thiếu hụt; tình trạng khan hiếm”', '["spark","shortage","academy","confirmation"]'::jsonb, 1, 'sự thiếu hụt; tình trạng khan hiếm → shortage (/ˈʃɔːrtɪdʒ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-56', 'en', 'Bài 56: Chính phủ & Pháp luật (1) - CEFR B2', 'CEFR B2', 'B2 · Chính phủ & Pháp luật', '20 từ vựng Tiếng Anh CEFR B2 chủ đề chính phủ & pháp luật kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4056, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_implement', 'en-b2-56', 'implement', '/ˈɪmpləment/', 'B2', 'thực hiện; thi hành; dụng cụ; công cụ', 'v.', 'implementation (n.)', NULL, 'Động từ trọng âm ở âm tiết đầu; danh từ âm tiết cuối đọc là /mənt/.', 'Our team will implement the new schedule next week.', NULL, 'Nhóm chúng tôi sẽ thực hiện thời biểu mới vào tuần tới.', '{"wordId":"implement","ukIpa":"/ˈɪmplɪment/","usIpa":"/ˈɪmpləment/","cefr":"B2","topic":"government","senses":[{"pos":"v.","en":"to put a plan or decision into action","vi":"thực hiện; thi hành"},{"pos":"n.","en":"a tool used for a particular task","vi":"dụng cụ; công cụ"}],"examples":[{"en":"Our team will implement the new schedule next week.","vi":"Nhóm chúng tôi sẽ thực hiện thời biểu mới vào tuần tới.","audioKind":"ex"},{"en":"Governments should implement policies that make public transport more affordable for people on low incomes.","vi":"Chính phủ nên thực hiện các chính sách giúp người có thu nhập thấp dễ dàng tiếp cận giao thông công cộng hơn.","audioKind":"ex2"}],"collocations":[{"en":"implement a policy","vi":"thực thi chính sách"},{"en":"implement a plan","vi":"thực hiện kế hoạch"},{"en":"agricultural implements","vi":"dụng cụ nông nghiệp"}],"wordFamily":["implementation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ trọng âm ở âm tiết đầu; danh từ âm tiết cuối đọc là /mənt/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ensure', 'en-b2-56', 'ensure', '/ɪnˈʃʊr/', 'B2', 'bảo đảm; cam kết', 'v.', NULL, 'Đồng nghĩa: guarantee, make sure', 'ensure đi với danh từ hoặc mệnh đề that; insure dùng để chỉ việc mua bảo hiểm.', 'Please ensure that all windows are closed before leaving.', NULL, 'Xin vui lòng đảm bảo tất cả các cửa sổ đã được đóng trước khi rời đi.', '{"wordId":"ensure","ukIpa":"/ɪnˈʃʊə/","usIpa":"/ɪnˈʃʊr/","cefr":"B2","topic":"government","senses":[{"pos":"v.","en":"To make certain that something happens or is true","vi":"bảo đảm; cam kết"}],"examples":[{"en":"Please ensure that all windows are closed before leaving.","vi":"Xin vui lòng đảm bảo tất cả các cửa sổ đã được đóng trước khi rời đi.","audioKind":"ex"},{"en":"Governments should ensure that affordable public transport is available to residents in both urban and rural areas.","vi":"Chính phủ nên đảm bảo rằng cư dân ở cả khu vực thành thị và nông thôn đều có thể tiếp cận phương tiện giao thông công cộng với giá cả phải chăng.","audioKind":"ex2"}],"collocations":[{"en":"ensure safety","vi":"đảm bảo an toàn"},{"en":"ensure access","vi":"đảm bảo quyền tiếp cận"},{"en":"ensure that","vi":"đảm bảo rằng"}],"wordFamily":[],"synonyms":["guarantee","make sure"],"antonyms":[],"tipVi":"ensure đi với danh từ hoặc mệnh đề that; insure dùng để chỉ việc mua bảo hiểm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_forbid', 'en-b2-56', 'forbid', '/fɚˈbɪd/', 'B2', 'cấm; không cho phép', 'v.', 'forbidden (adj.)', 'Đồng nghĩa: prohibit, ban · Trái nghĩa: allow, permit', 'Có dạng quá khứ là forbade, quá phân từ là forbidden; có thể đi với danh động từ.', 'Our building rules forbid leaving bicycles in the hallway.', NULL, 'Nội quy tòa nhà chúng tôi cấm để xe đạp ở hành lang.', '{"wordId":"forbid","ukIpa":"/fəˈbɪd/","usIpa":"/fɚˈbɪd/","cefr":"B2","topic":"government","senses":[{"pos":"v.","en":"To order someone not to do something or disallow it","vi":"cấm; không cho phép"}],"examples":[{"en":"Our building rules forbid leaving bicycles in the hallway.","vi":"Nội quy tòa nhà chúng tôi cấm để xe đạp ở hành lang.","audioKind":"ex"},{"en":"Governments should forbid companies from releasing untreated waste into rivers to protect public health and aquatic ecosystems.","vi":"Chính phủ nên cấm các công ty xả nước thải chưa qua xử lý ra sông ngòi để bảo vệ sức khỏe cộng đồng và hệ sinh thái dưới nước.","audioKind":"ex2"}],"collocations":[{"en":"forbid someone to do something","vi":"cấm ai làm gì"},{"en":"forbid someone from doing something","vi":"cấm ai làm việc gì"},{"en":"strictly forbidden","vi":"nghiêm cấm"}],"wordFamily":["forbidden (adj.)"],"synonyms":["prohibit","ban"],"antonyms":["allow","permit"],"tipVi":"Có dạng quá khứ là forbade, quá phân từ là forbidden; có thể đi với danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_elect', 'en-b2-56', 'elect', '/ɪˈlekt/', 'B2', 'bầu; bầu chọn; chọn; quyết định', 'v.', 'election (n.), electoral (adj.), electorate (n.)', 'Đồng nghĩa: choose, select', 'elect sb chair trong đó chức vụ thường không đứng trước mạo từ.', 'Our club elected a new captain last night.', NULL, 'Câu lạc bộ của chúng tôi đã bầu ra một đội trưởng mới tối qua.', '{"wordId":"elect","ukIpa":"/ɪˈlekt/","usIpa":"/ɪˈlekt/","cefr":"B2","topic":"government","senses":[{"pos":"v.","en":"to choose someone for a position by voting","vi":"bầu; bầu chọn"},{"pos":"v.","en":"to choose to do something","vi":"chọn; quyết định"}],"examples":[{"en":"Our club elected a new captain last night.","vi":"Câu lạc bộ của chúng tôi đã bầu ra một đội trưởng mới tối qua.","audioKind":"ex"},{"en":"Citizens should elect representatives who are willing to address long-term environmental challenges rather than seek immediate popularity.","vi":"Công dân nên bầu ra những đại biểu sẵn sàng giải quyết các thách thức môi trường lâu dài thay vì tìm kiếm sự ủng hộ trước mắt.","audioKind":"ex2"}],"collocations":[{"en":"elect a president","vi":"bầu tổng thống"},{"en":"elect someone to office","vi":"bầu ai đó vào chức vụ"},{"en":"elect to do something","vi":"chọn làm gì"}],"wordFamily":["election (n.)","electoral (adj.)","electorate (n.)"],"synonyms":["choose","select"],"antonyms":[],"tipVi":"elect sb chair trong đó chức vụ thường không đứng trước mạo từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ally', 'en-b2-56', 'ally', '/ˈælaɪ/', 'B2', 'đồng minh; người ủng hộ; kết minh; liên minh', 'n.', 'alliance (n.), allied (adj.)', 'Đồng nghĩa: supporter, partner · Trái nghĩa: opponent, enemy', 'Danh từ thường trọng âm ở âm tiết đầu; động từ thường đọc là /əˈlaɪ/.', 'My neighbour became an ally in saving the park.', NULL, 'Hàng xóm của tôi đã trở thành một đồng minh trong việc cứu lấy công viên.', '{"wordId":"ally","ukIpa":"/ˈælaɪ/","usIpa":"/ˈælaɪ/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"A person or country that supports another.","vi":"đồng minh; người ủng hộ"},{"pos":"v.","en":"To join with someone for a shared purpose.","vi":"kết minh; liên minh"}],"examples":[{"en":"My neighbour became an ally in saving the park.","vi":"Hàng xóm của tôi đã trở thành một đồng minh trong việc cứu lấy công viên.","audioKind":"ex"},{"en":"Local charities can be valuable allies for governments seeking to reduce poverty and improve social inclusion.","vi":"Các tổ chức từ thiện địa phương có thể là những người đồng minh đắc lực cho các chính phủ đang tìm cách giảm nghèo và tăng cường bao dung xã hội.","audioKind":"ex2"}],"collocations":[{"en":"a close ally","vi":"một đồng minh thân cận"},{"en":"a powerful ally","vi":"một đồng minh hùng mạnh"},{"en":"ally yourself with","vi":"liên minh với..."}],"wordFamily":["alliance (n.)","allied (adj.)"],"synonyms":["supporter","partner"],"antonyms":["opponent","enemy"],"tipVi":"Danh từ thường trọng âm ở âm tiết đầu; động từ thường đọc là /əˈlaɪ/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_troop', 'en-b2-56', 'troop', '/truːp/', 'B2', 'quân đội; binh lính; đội; nhóm (người hoặc động vật); di chuyển thành đàn; đi thành đoàn', 'n.', 'trooper (n.)', NULL, 'Chỉ binh lính thường dùng số nhiều troops; đoàn kịch/nghệ sĩ dùng troupe.', 'Troops helped local families cross the river after the flood.', NULL, 'Binh lính đã giúp các gia đình địa phương vượt sông sau trận lũ.', '{"wordId":"troop","ukIpa":"/truːp/","usIpa":"/truːp/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"soldiers collectively, or an organized military unit","vi":"quân đội; binh lính"},{"pos":"n.","en":"an organized group of people or a group of animals","vi":"đội; nhóm (người hoặc động vật)"},{"pos":"v.","en":"to walk somewhere together as a group","vi":"di chuyển thành đàn; đi thành đoàn"}],"examples":[{"en":"Troops helped local families cross the river after the flood.","vi":"Binh lính đã giúp các gia đình địa phương vượt sông sau trận lũ.","audioKind":"ex"},{"en":"Governments sometimes deploy troops to deliver emergency supplies when natural disasters make civilian transport systems unusable.","vi":"Chính phủ đôi khi điều động quân đội đi phân phát hàng cứu trợ khẩn cấp khi thảm họa thiên nhiên làm tê liệt hệ thống vận tải dân sự.","audioKind":"ex2"}],"collocations":[{"en":"deploy troops","vi":"triển khai quân đội"},{"en":"withdraw troops","vi":"rút quân"},{"en":"a troop of monkeys","vi":"một đàn khỉ"}],"wordFamily":["trooper (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ binh lính thường dùng số nhiều troops; đoàn kịch/nghệ sĩ dùng troupe.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_arms', 'en-b2-56', 'arms', '/ɑːrmz/', 'B2', 'vũ khí, trang thiết bị quân sự; cánh tay (số nhiều)', 'n.', 'arm (v.), armed (adj.), disarm (v.), disarmament (n.)', 'Đồng nghĩa: weapons, armaments', 'Khi chỉ vũ khí thì dùng dạng số nhiều arms; an arm thường chỉ một cánh tay.', 'The museum displays old arms behind thick glass.', NULL, 'Viện bảo tàng trưng bày những vũ khí cổ phía sau lớp kính dày.', '{"wordId":"arms","ukIpa":"/ɑːmz/","usIpa":"/ɑːrmz/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"Weapons and military equipment.","vi":"vũ khí, trang thiết bị quân sự"},{"pos":"n.","en":"The body parts extending from the shoulders to the hands.","vi":"cánh tay (số nhiều)"}],"examples":[{"en":"The museum displays old arms behind thick glass.","vi":"Viện bảo tàng trưng bày những vũ khí cổ phía sau lớp kính dày.","audioKind":"ex"},{"en":"International agreements can restrict the trade in arms and encourage governments to resolve disputes peacefully.","vi":"Các hiệp định quốc tế có thể hạn chế buôn bán vũ khí và khuyến khích các chính phủ giải quyết tranh chấp một cách hòa bình.","audioKind":"ex2"}],"collocations":[{"en":"arms trade","vi":"thương mại vũ khí"},{"en":"arms race","vi":"chạy đua vũ trang"},{"en":"arms control","vi":"kiểm soát vũ khí"},{"en":"lay down arms","vi":"hạ vũ khí"}],"wordFamily":["arm (v.)","armed (adj.)","disarm (v.)","disarmament (n.)"],"synonyms":["weapons","armaments"],"antonyms":[],"tipVi":"Khi chỉ vũ khí thì dùng dạng số nhiều arms; an arm thường chỉ một cánh tay.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_drastic', 'en-b2-56', 'drastic', '/ˈdræstɪk/', 'B2', 'mạnh mẽ; quyết liệt; triệt để; đáng kể', 'adj.', 'drastically (adv.)', 'Đồng nghĩa: extreme, radical, severe · Trái nghĩa: mild, moderate', 'Nhấn mạnh mức độ nghiêm trọng và tác động mạnh, không đồng nghĩa với rapid (nhanh chóng).', 'We took drastic action and sold our second car.', NULL, 'Chúng tôi đã thực hiện biện pháp quyết liệt và bán chiếc xe thứ hai đi.', '{"wordId":"drastic","ukIpa":"/ˈdræstɪk/","usIpa":"/ˈdræstɪk/","cefr":"B2","topic":"government","senses":[{"pos":"adj.","en":"Extreme or severe, causing a major change","vi":"mạnh mẽ; quyết liệt; triệt để; đáng kể"}],"examples":[{"en":"We took drastic action and sold our second car.","vi":"Chúng tôi đã thực hiện biện pháp quyết liệt và bán chiếc xe thứ hai đi.","audioKind":"ex"},{"en":"Drastic cuts to public transport funding could leave many low-income households without affordable access to essential services.","vi":"Việc cắt giảm mạnh mẽ nguồn vốn tài trợ cho giao thông công cộng có thể khiến nhiều hộ gia đình thu nhập thấp không thể tiếp cận các dịch vụ thiết yếu với mức giá phải chăng.","audioKind":"ex2"}],"collocations":[{"en":"drastic measures","vi":"biện pháp quyết liệt"},{"en":"drastic action","vi":"hành động mạnh mẽ"},{"en":"drastic cuts","vi":"cắt giảm sâu"},{"en":"drastic changes","vi":"những thay đổi triệt để"}],"wordFamily":["drastically (adv.)"],"synonyms":["extreme","radical","severe"],"antonyms":["mild","moderate"],"tipVi":"Nhấn mạnh mức độ nghiêm trọng và tác động mạnh, không đồng nghĩa với rapid (nhanh chóng).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_taxpayer', 'en-b2-56', 'taxpayer', '/ˈtæksˌpeɪər/', 'B2', 'người đóng thuế; tổ chức nộp thuế', 'n.', 'tax (n.), tax (v.), taxation (n.), taxable (adj.)', NULL, 'Thường chỉ cá nhân đóng thuế, cũng có thể dùng cho tổ chức đóng thuế.', 'As a taxpayer, I want cleaner streets and safer parks.', NULL, 'Là một người nộp thuế, tôi mong muốn những con đường sạch sẽ hơn và các công viên an toàn hơn.', '{"wordId":"taxpayer","ukIpa":"/ˈtæksˌpeɪə/","usIpa":"/ˈtæksˌpeɪər/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"A person or organisation that pays taxes.","vi":"người đóng thuế; tổ chức nộp thuế"}],"examples":[{"en":"As a taxpayer, I want cleaner streets and safer parks.","vi":"Là một người nộp thuế, tôi mong muốn những con đường sạch sẽ hơn và các công viên an toàn hơn.","audioKind":"ex"},{"en":"Public infrastructure projects should deliver lasting benefits to the taxpayers who finance them.","vi":"Các dự án cơ sở hạ tầng công cộng nên mang lại lợi ích lâu dài cho những người nộp thuế là người tài trợ cho các dự án đó.","audioKind":"ex2"}],"collocations":[{"en":"taxpayer money","vi":"tiền của người nộp thuế"},{"en":"at taxpayers'' expense","vi":"do người nộp thuế chi trả"},{"en":"taxpayer funding","vi":"nguồn vốn từ người nộp thuế"}],"wordFamily":["tax (n.)","tax (v.)","taxation (n.)","taxable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ cá nhân đóng thuế, cũng có thể dùng cho tổ chức đóng thuế.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ministry', 'en-b2-56', 'ministry', '/ˈmɪnɪstri/', 'B2', 'bộ (cơ quan chính phủ); chức vụ mục sư; công việc tôn giáo', 'n.', 'minister (n.), ministerial (adj.)', NULL, 'Tên các cơ quan chính phủ thường dùng Ministry of đi kèm với danh từ lĩnh vực.', 'My aunt works at the ministry near the station.', NULL, 'Dì tôi làm việc ở cơ quan bộ gần nhà ga.', '{"wordId":"ministry","ukIpa":"/ˈmɪnɪstri/","usIpa":"/ˈmɪnɪstri/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"a government department responsible for a particular area","vi":"bộ (cơ quan chính phủ)"},{"pos":"n.","en":"the work or duties of a religious minister","vi":"chức vụ mục sư; công việc tôn giáo"}],"examples":[{"en":"My aunt works at the ministry near the station.","vi":"Dì tôi làm việc ở cơ quan bộ gần nhà ga.","audioKind":"ex"},{"en":"The education ministry should consult teachers before introducing major changes to the national school curriculum.","vi":"Bộ giáo dục nên tham khảo ý kiến của giáo viên trước khi đưa ra các thay đổi lớn đối với chương trình giảng dạy quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"education ministry","vi":"bộ giáo dục"},{"en":"foreign ministry","vi":"bộ ngoại giao"},{"en":"Ministry of Health","vi":"Bộ Y tế"}],"wordFamily":["minister (n.)","ministerial (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Tên các cơ quan chính phủ thường dùng Ministry of đi kèm với danh từ lĩnh vực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sue', 'en-b2-56', 'sue', '/suː/', 'B2', 'kiện; khởi kiện', 'v.', NULL, NULL, 'sue someone for something nghĩa là kiện ai vì điều gì.', 'Our neighbour plans to sue the builder over faulty repairs.', NULL, 'Hàng xóm của chúng tôi dự định kiện nhà thầu vì lỗi sửa chữa.', '{"wordId":"sue","ukIpa":"/suː/","usIpa":"/suː/","cefr":"B2","topic":"government","senses":[{"pos":"v.","en":"To take legal action against someone, usually seeking compensation.","vi":"kiện; khởi kiện"}],"examples":[{"en":"Our neighbour plans to sue the builder over faulty repairs.","vi":"Hàng xóm của chúng tôi dự định kiện nhà thầu vì lỗi sửa chữa.","audioKind":"ex"},{"en":"Consumers should have the right to sue companies that knowingly sell unsafe products or conceal serious defects.","vi":"Người tiêu dùng nên có quyền kiện các công ty cố tình bán sản phẩm không an toàn hoặc che giấu các khiếm khuyết nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"sue for damages","vi":"kiện đòi bồi thường thiệt hại"},{"en":"sue a company","vi":"kiện một công ty"},{"en":"sue for negligence","vi":"kiện do sơ suất"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"sue someone for something nghĩa là kiện ai vì điều gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_license', 'en-b2-56', 'license', '/ˈlaɪsəns/', 'B2', 'cấp phép; phê chuẩn giấy phép; giấy phép; bằng lái; chứng chỉ', 'v.', 'licensed (adj.), licensing (n.), licensee (n.)', 'Đồng nghĩa: authorize, permit', 'Tiếng Anh Anh dùng licence làm danh từ và license làm động từ; tiếng Anh Mỹ dùng license cho cả hai.', 'You need a license to drive on public roads.', NULL, 'Bạn cần có giấy phép lái xe để chạy xe trên đường công cộng.', '{"wordId":"license","ukIpa":"/ˈlaɪsəns/","usIpa":"/ˈlaɪsəns/","cefr":"B2","topic":"government","senses":[{"pos":"v.","en":"to give official permission for an activity","vi":"cấp phép; phê chuẩn giấy phép"},{"pos":"n.","en":"an official document permitting an activity or ownership","vi":"giấy phép; bằng lái; chứng chỉ"}],"examples":[{"en":"You need a license to drive on public roads.","vi":"Bạn cần có giấy phép lái xe để chạy xe trên đường công cộng.","audioKind":"ex"},{"en":"Authorities should license childcare providers carefully to ensure that facilities meet appropriate safety and quality standards.","vi":"Các cơ quan chức năng nên thẩm định kỹ lưỡng các cơ sở cung cấp dịch vụ chăm sóc trẻ em để đảm bảo các cơ sở đáp ứng đúng các tiêu chuẩn về an toàn và chất lượng.","audioKind":"ex2"}],"collocations":[{"en":"license someone to do something","vi":"cấp phép cho ai làm gì"},{"en":"a driving license","vi":"giấy phép lái xe"},{"en":"apply for a license","vi":"nộp đơn xin giấy phép"},{"en":"a licensed operator","vi":"đơn vị kinh doanh được cấp phép"}],"wordFamily":["licensed (adj.)","licensing (n.)","licensee (n.)"],"synonyms":["authorize","permit"],"antonyms":[],"tipVi":"Tiếng Anh Anh dùng licence làm danh từ và license làm động từ; tiếng Anh Mỹ dùng license cho cả hai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_defence', 'en-b2-56', 'defence', '/dɪˈfens/', 'B2', 'sự phòng thủ; sự bảo vệ; lời bào chữa; sự biện hộ; hàng phòng ngự; cầu thủ phòng ngự', 'n.', 'defend (v.), defender (n.), defensive (adj.)', 'Đồng nghĩa: protection · Trái nghĩa: attack', 'Cách viết theo Anh-Anh là defence; Anh-Mỹ là defense.', 'The thick walls provided a strong defence against attackers.', NULL, 'Những bức tường dày kiên cố tạo ra một lớp phòng thủ vững chắc chống lại kẻ địch.', '{"wordId":"defence","ukIpa":"/dɪˈfens/","usIpa":"/dɪˈfens/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"Action taken to protect someone or something from attack or harm.","vi":"sự phòng thủ; sự bảo vệ"},{"pos":"n.","en":"An argument or explanation supporting someone accused or criticized.","vi":"lời bào chữa; sự biện hộ"},{"pos":"n.","en":"Players or actions that stop opponents from scoring in sport.","vi":"hàng phòng ngự; cầu thủ phòng ngự"}],"examples":[{"en":"The thick walls provided a strong defence against attackers.","vi":"Những bức tường dày kiên cố tạo ra một lớp phòng thủ vững chắc chống lại kẻ địch.","audioKind":"ex"},{"en":"Restoring coastal wetlands offers a natural defence against flooding while creating valuable habitats for wildlife.","vi":"Việc phục hồi các vùng đất ngập nước ven biển mang lại khả năng chống lũ tự nhiên đồng thời tạo ra môi trường sống quý giá cho động thực vật hoang dã.","audioKind":"ex2"}],"collocations":[{"en":"defence against","vi":"sự phòng thủ chống lại"},{"en":"in defence of","vi":"để bênh vực cho"},{"en":"self-defence","vi":"sự tự vệ"},{"en":"defence spending","vi":"chi phí quốc phòng"}],"wordFamily":["defend (v.)","defender (n.)","defensive (adj.)"],"synonyms":["protection"],"antonyms":["attack"],"tipVi":"Cách viết theo Anh-Anh là defence; Anh-Mỹ là defense.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bribe', 'en-b2-56', 'bribe', '/braɪb/', 'B2', 'hối lộ; đút lót; tiền đút lót; vật hối lộ', 'v.', 'bribery (n.)', NULL, 'Từ bribe có tân ngữ chỉ người nhận hối lộ; bribery dùng để chỉ hành vi hối lộ nói chung.', 'The driver tried to bribe the officer with cash.', NULL, 'Tên tài xế đã cố gắng hối lộ viên cảnh sát bằng tiền mặt.', '{"wordId":"bribe","ukIpa":"/braɪb/","usIpa":"/braɪb/","cefr":"B2","topic":"government","senses":[{"pos":"v.","en":"Offer rewards to make someone act dishonestly in your favour.","vi":"hối lộ; đút lót"},{"pos":"n.","en":"Money or gifts offered to influence someone dishonestly.","vi":"tiền đút lót; vật hối lộ"}],"examples":[{"en":"The driver tried to bribe the officer with cash.","vi":"Tên tài xế đã cố gắng hối lộ viên cảnh sát bằng tiền mặt.","audioKind":"ex"},{"en":"Strict penalties for companies that bribe public officials can help restore trust in government institutions.","vi":"Các hình phạt nghiêm khắc đối với những công ty hối lộ quan chức nhà nước có thể giúp khôi phục niềm tin vào các cơ quan chính phủ.","audioKind":"ex2"}],"collocations":[{"en":"offer a bribe","vi":"đưa hối lộ"},{"en":"accept a bribe","vi":"nhận hối lộ"},{"en":"bribe an official","vi":"hối lộ một quan chức"},{"en":"bribe someone into doing something","vi":"hối lộ ai đó để làm việc gì"}],"wordFamily":["bribery (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ bribe có tân ngữ chỉ người nhận hối lộ; bribery dùng để chỉ hành vi hối lộ nói chung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_territory', 'en-b2-56', 'territory', '/ˈterətɔːri/', 'B2', 'lãnh thổ; vùng đất; khu vực; lãnh địa; lĩnh vực; phạm vi', 'n.', 'territorial (adj.), territorially (adv.)', NULL, 'Nghĩa lãnh thổ có thể đếm được hay không tùy ngữ cảnh; một vùng lãnh thổ cụ thể dùng a territory.', 'The island became part of the country''s territory.', NULL, 'Hòn đảo đã trở thành một phần lãnh thổ của quốc gia đó.', '{"wordId":"territory","ukIpa":"/ˈterətri/","usIpa":"/ˈterətɔːri/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"land controlled by a particular country or authority","vi":"lãnh thổ; vùng đất; khu vực"},{"pos":"n.","en":"an area an animal defends against others of its kind","vi":"lãnh địa"},{"pos":"n.","en":"an area of knowledge, experience, or activity","vi":"lĩnh vực; phạm vi"}],"examples":[{"en":"The island became part of the country''s territory.","vi":"Hòn đảo đã trở thành một phần lãnh thổ của quốc gia đó.","audioKind":"ex"},{"en":"As cities expand into wildlife territory, conflicts between humans and native animals may become more frequent.","vi":"Khi các thành phố mở rộng lấn chiếm vùng đất của động vật hoang dã, các cuộc xung đột giữa con người và động vật bản địa có thể xảy ra thường xuyên hơn.","audioKind":"ex2"}],"collocations":[{"en":"national territory","vi":"lãnh thổ quốc gia"},{"en":"defend territory","vi":"bảo vệ lãnh thổ"},{"en":"unfamiliar territory","vi":"lĩnh vực lạ lẫm"},{"en":"enter new territory","vi":"bước sang lĩnh vực mới"}],"wordFamily":["territorial (adj.)","territorially (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa lãnh thổ có thể đếm được hay không tùy ngữ cảnh; một vùng lãnh thổ cụ thể dùng a territory.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_poll', 'en-b2-56', 'poll', '/poʊl/', 'B2', 'cuộc thăm dò ý kiến; điều tra dư luận; sự bỏ phiếu; cuộc bầu cử; thăm dò ý kiến; đạt được số phiếu', 'n.', 'polling (n.), pollster (n.)', NULL, 'Khảo sát ý kiến dùng opinion poll; cụm the polls chỉ sự kiện bỏ phiếu bầu cử.', 'A local poll showed strong support for the park.', NULL, 'Một cuộc thăm dò địa phương cho thấy sự ủng hộ mạnh mẽ dành cho công viên.', '{"wordId":"poll","ukIpa":"/pəʊl/","usIpa":"/poʊl/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"A survey asking people about their opinions or preferences","vi":"cuộc thăm dò ý kiến; điều tra dư luận"},{"pos":"n.","en":"The process of voting in an election","vi":"sự bỏ phiếu; cuộc bầu cử"},{"pos":"v.","en":"To survey people''s opinions, or receive votes in an election","vi":"thăm dò ý kiến; đạt được số phiếu"}],"examples":[{"en":"A local poll showed strong support for the park.","vi":"Một cuộc thăm dò địa phương cho thấy sự ủng hộ mạnh mẽ dành cho công viên.","audioKind":"ex"},{"en":"Opinion polls can help governments understand public concerns, but their accuracy depends on how participants are selected.","vi":"Các cuộc thăm dò ý kiến có thể giúp chính phủ hiểu được mối quan tâm của công chúng, nhưng độ chính xác của chúng phụ thuộc vào cách lựa chọn người tham gia.","audioKind":"ex2"}],"collocations":[{"en":"opinion poll","vi":"thăm dò ý kiến"},{"en":"conduct a poll","vi":"tiến hành thăm dò ý kiến"},{"en":"go to the polls","vi":"đi bỏ phiếu"},{"en":"poll results","vi":"kết quả thăm dò"}],"wordFamily":["polling (n.)","pollster (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khảo sát ý kiến dùng opinion poll; cụm the polls chỉ sự kiện bỏ phiếu bầu cử.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_democratic', 'en-b2-56', 'democratic', '/ˌdeməˈkrætɪk/', 'B2', 'thuộc về dân chủ; theo chế độ dân chủ; có tính bình đẳng; cho phép mọi người tham gia ra quyết định', 'adj.', 'democracy (n.), democratically (adv.), democratise (v.)', 'Trái nghĩa: undemocratic, authoritarian', 'Từ democratic viết thường mang nghĩa chung chỉ tính dân chủ, không ám chỉ riêng đảng phái chính trị nào.', 'Our club takes a democratic vote on every major decision.', NULL, 'Câu lạc bộ của chúng tôi tiến hành bỏ phiếu dân chủ cho mọi quyết định quan trọng.', '{"wordId":"democratic","ukIpa":"/ˌdeməˈkrætɪk/","usIpa":"/ˌdeməˈkrætɪk/","cefr":"B2","topic":"government","senses":[{"pos":"adj.","en":"Based on government by people or their elected representatives.","vi":"thuộc về dân chủ; theo chế độ dân chủ"},{"pos":"adj.","en":"Allowing everyone involved an equal opportunity to influence decisions.","vi":"có tính bình đẳng; cho phép mọi người tham gia ra quyết định"}],"examples":[{"en":"Our club takes a democratic vote on every major decision.","vi":"Câu lạc bộ của chúng tôi tiến hành bỏ phiếu dân chủ cho mọi quyết định quan trọng.","audioKind":"ex"},{"en":"A democratic society depends on informed citizens who can access reliable information and participate freely in public debate.","vi":"Một xã hội dân chủ phụ thuộc vào những công dân có hiểu biết, những người có thể tiếp cận thông tin đáng tin cậy và tham gia tự do vào các cuộc thảo luận công khai.","audioKind":"ex2"}],"collocations":[{"en":"democratic society","vi":"xã hội dân chủ"},{"en":"democratic elections","vi":"bầu cử dân chủ"},{"en":"democratic process","vi":"quy trình dân chủ"},{"en":"democratic principles","vi":"nguyên tắc dân chủ"}],"wordFamily":["democracy (n.)","democratically (adv.)","democratise (v.)"],"synonyms":[],"antonyms":["undemocratic","authoritarian"],"tipVi":"Từ democratic viết thường mang nghĩa chung chỉ tính dân chủ, không ám chỉ riêng đảng phái chính trị nào.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_treaty', 'en-b2-56', 'treaty', '/ˈtriːti/', 'B2', 'hiệp ước; hiệp định quốc tế', 'n.', NULL, 'Đồng nghĩa: agreement, pact, accord', 'Từ này thường chỉ thỏa thuận chính thức giữa các quốc gia, không dùng để chỉ quá trình đàm phán.', 'We heard about the new treaty on the radio.', NULL, 'Chúng tôi nghe tin về hiệp ước mới trên đài phát thanh.', '{"wordId":"treaty","ukIpa":"/ˈtriːti/","usIpa":"/ˈtriːti/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"a formal agreement between countries","vi":"hiệp ước; hiệp định quốc tế"}],"examples":[{"en":"We heard about the new treaty on the radio.","vi":"Chúng tôi nghe tin về hiệp ước mới trên đài phát thanh.","audioKind":"ex"},{"en":"An international treaty can establish shared environmental standards, but its success depends on effective enforcement.","vi":"Một hiệp ước quốc tế có thể thiết lập các tiêu chuẩn môi trường chung, nhưng thành công của nó phụ thuộc vào việc thực thi hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"sign a treaty","vi":"ký kết hiệp ước"},{"en":"peace treaty","vi":"hiệp ước hòa bình"},{"en":"ratify a treaty","vi":"phê chuẩn hiệp ước"},{"en":"treaty obligations","vi":"nghĩa vụ theo hiệp ước"}],"wordFamily":[],"synonyms":["agreement","pact","accord"],"antonyms":[],"tipVi":"Từ này thường chỉ thỏa thuận chính thức giữa các quốc gia, không dùng để chỉ quá trình đàm phán.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_abolish', 'en-b2-56', 'abolish', '/əˈbɑːlɪʃ/', 'B2', 'thủ tiêu; bãi bỏ; hủy bỏ (luật lệ, hệ thống hoặc tập quán)', 'v.', 'abolition (n.), abolitionist (n.)', 'Đồng nghĩa: eliminate, scrap · Trái nghĩa: establish, introduce', 'Thường kết hợp với luật pháp, hệ thống hoặc tập quán, không dùng cho việc hủy lịch hẹn thông thường.', 'Our library has abolished fines for returning books late.', NULL, 'Thư viện của chúng tôi đã bãi bỏ tiền phạt đối với việc trả sách quá hạn.', '{"wordId":"abolish","ukIpa":"/əˈbɒlɪʃ/","usIpa":"/əˈbɑːlɪʃ/","cefr":"B2","topic":"government","senses":[{"pos":"v.","en":"to officially end a law, system, or established practice","vi":"thủ tiêu; bãi bỏ; hủy bỏ (luật lệ, hệ thống hoặc tập quán)"}],"examples":[{"en":"Our library has abolished fines for returning books late.","vi":"Thư viện của chúng tôi đã bãi bỏ tiền phạt đối với việc trả sách quá hạn.","audioKind":"ex"},{"en":"Some economists argue that governments should abolish subsidies that encourage excessive consumption of fossil fuels.","vi":"Một số nhà kinh tế học lập luận rằng các chính phủ nên bãi bỏ các khoản trợ cấp khuyến khích việc tiêu thụ nhiên liệu hóa thạch quá mức.","audioKind":"ex2"}],"collocations":[{"en":"abolish a law","vi":"bãi bỏ một điều luật"},{"en":"abolish a tax","vi":"bãi bỏ một loại thuế"},{"en":"abolish slavery","vi":"xóa bỏ chế độ nô lệ"}],"wordFamily":["abolition (n.)","abolitionist (n.)"],"synonyms":["eliminate","scrap"],"antonyms":["establish","introduce"],"tipVi":"Thường kết hợp với luật pháp, hệ thống hoặc tập quán, không dùng cho việc hủy lịch hẹn thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_county', 'en-b2-56', 'county', '/ˈkaʊnti/', 'B2', 'quận; hạt; tỉnh (đơn vị hành chính)', 'n.', NULL, NULL, 'county ở Anh thường dịch là ''hạt'', trong khi ở Mỹ thường dịch là ''quận'' hoặc ''hạt''.', 'My grandparents live in a quiet village in this county.', NULL, 'Ông bà tôi sống ở một ngôi làng yên tĩnh thuộc hạt này.', '{"wordId":"county","ukIpa":"/ˈkaʊnti/","usIpa":"/ˈkaʊnti/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"An administrative area within a country or state.","vi":"quận; hạt; tỉnh (đơn vị hành chính)"}],"examples":[{"en":"My grandparents live in a quiet village in this county.","vi":"Ông bà tôi sống ở một ngôi làng yên tĩnh thuộc hạt này.","audioKind":"ex"},{"en":"The county council plans to improve public transport between rural communities and the nearest city.","vi":"Hội đồng hạt có kế hoạch cải thiện giao thông công cộng giữa các cộng đồng nông thôn và thành phố gần nhất.","audioKind":"ex2"}],"collocations":[{"en":"county council","vi":"hội đồng hạt"},{"en":"county town","vi":"thị trấn trung tâm hạt"},{"en":"county boundary","vi":"ranh giới hạt"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"county ở Anh thường dịch là ''hạt'', trong khi ở Mỹ thường dịch là ''quận'' hoặc ''hạt''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_56_1', 'en-b2-56', 'Cách dùng “democratic” (adj.) — thuộc về dân chủ; theo chế độ dân chủ', 'democratic society  ·  democratic elections  ·  democratic process', 'Từ democratic viết thường mang nghĩa chung chỉ tính dân chủ, không ám chỉ riêng đảng phái chính trị nào.', 'Họ từ (Word Family): democracy (n.), democratically (adv.), democratise (v.) | Trái nghĩa: undemocratic, authoritarian', '[{"hanzi":"Our club takes a democratic vote on every major decision.","pinyin":"","meaning":"Câu lạc bộ của chúng tôi tiến hành bỏ phiếu dân chủ cho mọi quyết định quan trọng."},{"hanzi":"A democratic society depends on informed citizens who can access reliable information and participate freely in public debate.","pinyin":"","meaning":"Một xã hội dân chủ phụ thuộc vào những công dân có hiểu biết, những người có thể tiếp cận thông tin đáng tin cậy và tham gia tự do vào các cuộc thảo luận công khai."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_56_2', 'en-b2-56', 'Cách dùng “license” (v.) — cấp phép; phê chuẩn giấy phép', 'license someone to do something  ·  a driving license  ·  apply for a license', 'Tiếng Anh Anh dùng licence làm danh từ và license làm động từ; tiếng Anh Mỹ dùng license cho cả hai.', 'Họ từ (Word Family): licensed (adj.), licensing (n.), licensee (n.) | Đồng nghĩa: authorize, permit', '[{"hanzi":"You need a license to drive on public roads.","pinyin":"","meaning":"Bạn cần có giấy phép lái xe để chạy xe trên đường công cộng."},{"hanzi":"Authorities should license childcare providers carefully to ensure that facilities meet appropriate safety and quality standards.","pinyin":"","meaning":"Các cơ quan chức năng nên thẩm định kỹ lưỡng các cơ sở cung cấp dịch vụ chăm sóc trẻ em để đảm bảo các cơ sở đáp ứng đúng các tiêu chuẩn về an toàn và chất lượng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_56_3', 'en-b2-56', 'Cách dùng “abolish” (v.) — thủ tiêu; bãi bỏ; hủy bỏ (luật lệ, hệ thống hoặc tập quán)', 'abolish a law  ·  abolish a tax  ·  abolish slavery', 'Thường kết hợp với luật pháp, hệ thống hoặc tập quán, không dùng cho việc hủy lịch hẹn thông thường.', 'Họ từ (Word Family): abolition (n.), abolitionist (n.) | Đồng nghĩa: eliminate, scrap · Trái nghĩa: establish, introduce', '[{"hanzi":"Our library has abolished fines for returning books late.","pinyin":"","meaning":"Thư viện của chúng tôi đã bãi bỏ tiền phạt đối với việc trả sách quá hạn."},{"hanzi":"Some economists argue that governments should abolish subsidies that encourage excessive consumption of fossil fuels.","pinyin":"","meaning":"Một số nhà kinh tế học lập luận rằng các chính phủ nên bãi bỏ các khoản trợ cấp khuyến khích việc tiêu thụ nhiên liệu hóa thạch quá mức."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_56_4', 'en-b2-56', 'Cách dùng “territory” (n.) — lãnh thổ; vùng đất; khu vực', 'national territory  ·  defend territory  ·  unfamiliar territory', 'Nghĩa lãnh thổ có thể đếm được hay không tùy ngữ cảnh; một vùng lãnh thổ cụ thể dùng a territory.', 'Họ từ (Word Family): territorial (adj.), territorially (adv.)', '[{"hanzi":"The island became part of the country''s territory.","pinyin":"","meaning":"Hòn đảo đã trở thành một phần lãnh thổ của quốc gia đó."},{"hanzi":"As cities expand into wildlife territory, conflicts between humans and native animals may become more frequent.","pinyin":"","meaning":"Khi các thành phố mở rộng lấn chiếm vùng đất của động vật hoang dã, các cuộc xung đột giữa con người và động vật bản địa có thể xảy ra thường xuyên hơn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
