INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_56_1_8', 'ten_b2_56_1', 'drastic', 'We took drastic action and sold our second car.', 'We took drastic action and sold our second car.', '/ˈdræstɪk/', 'Chúng tôi đã thực hiện biện pháp quyết liệt và bán chiếc xe thứ hai đi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_56_1_1', 'en-b2-56', 'ten_b2_56_1', 'listening', 'listening', 'Our team will implement the new schedule next week.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Câu lạc bộ của chúng tôi tiến hành bỏ phiếu dân chủ cho mọi quyết định quan trọng.","Dì tôi làm việc ở cơ quan bộ gần nhà ga.","Là một người nộp thuế, tôi mong muốn những con đường sạch sẽ hơn và các công viên an toàn hơn.","Nhóm chúng tôi sẽ thực hiện thời biểu mới vào tuần tới."]'::jsonb, 3, 'Our team will implement the new schedule next week. → Nhóm chúng tôi sẽ thực hiện thời biểu mới vào tuần tới.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_56_1_2', 'en-b2-56', 'ten_b2_56_1', 'listening', 'listening', 'Please ensure that all windows are closed before leaving.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Xin vui lòng đảm bảo tất cả các cửa sổ đã được đóng trước khi rời đi.","Câu lạc bộ của chúng tôi tiến hành bỏ phiếu dân chủ cho mọi quyết định quan trọng.","Bạn cần có giấy phép lái xe để chạy xe trên đường công cộng.","Chúng tôi đã thực hiện biện pháp quyết liệt và bán chiếc xe thứ hai đi."]'::jsonb, 0, 'Please ensure that all windows are closed before leaving. → Xin vui lòng đảm bảo tất cả các cửa sổ đã được đóng trước khi rời đi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_56_1_3', 'en-b2-56', 'ten_b2_56_1', 'listening', 'listening', 'Our building rules forbid leaving bicycles in the hallway.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tên tài xế đã cố gắng hối lộ viên cảnh sát bằng tiền mặt.","Ông bà tôi sống ở một ngôi làng yên tĩnh thuộc hạt này.","Hòn đảo đã trở thành một phần lãnh thổ của quốc gia đó.","Nội quy tòa nhà chúng tôi cấm để xe đạp ở hành lang."]'::jsonb, 3, 'Our building rules forbid leaving bicycles in the hallway. → Nội quy tòa nhà chúng tôi cấm để xe đạp ở hành lang.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_56_2', 'en-b2-56', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_56_2_1', 'ten_b2_56_2', 'implement', 'Governments should implement policies that make public transport more affordable for people on low incomes.', 'Governments should implement policies that make public transport more affordable for people on low incomes.', '/ˈɪmpləment/', 'Chính phủ nên thực hiện các chính sách giúp người có thu nhập thấp dễ dàng tiếp cận giao thông công cộng hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_56_2_2', 'ten_b2_56_2', 'ensure', 'Governments should ensure that affordable public transport is available to residents in both urban and rural areas.', 'Governments should ensure that affordable public transport is available to residents in both urban and rural areas.', '/ɪnˈʃʊr/', 'Chính phủ nên đảm bảo rằng cư dân ở cả khu vực thành thị và nông thôn đều có thể tiếp cận phương tiện giao thông công cộng với giá cả phải chăng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_56_2_3', 'ten_b2_56_2', 'forbid', 'Governments should forbid companies from releasing untreated waste into rivers to protect public health and aquatic ecosystems.', 'Governments should forbid companies from releasing untreated waste into rivers to protect public health and aquatic ecosystems.', '/fɚˈbɪd/', 'Chính phủ nên cấm các công ty xả nước thải chưa qua xử lý ra sông ngòi để bảo vệ sức khỏe cộng đồng và hệ sinh thái dưới nước.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_56_2_4', 'ten_b2_56_2', 'elect', 'Citizens should elect representatives who are willing to address long-term environmental challenges rather than seek immediate popularity.', 'Citizens should elect representatives who are willing to address long-term environmental challenges rather than seek immediate popularity.', '/ɪˈlekt/', 'Công dân nên bầu ra những đại biểu sẵn sàng giải quyết các thách thức môi trường lâu dài thay vì tìm kiếm sự ủng hộ trước mắt.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_56_2_5', 'ten_b2_56_2', 'ally', 'Local charities can be valuable allies for governments seeking to reduce poverty and improve social inclusion.', 'Local charities can be valuable allies for governments seeking to reduce poverty and improve social inclusion.', '/ˈælaɪ/', 'Các tổ chức từ thiện địa phương có thể là những người đồng minh đắc lực cho các chính phủ đang tìm cách giảm nghèo và tăng cường bao dung xã hội.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_56_2_6', 'ten_b2_56_2', 'troop', 'Governments sometimes deploy troops to deliver emergency supplies when natural disasters make civilian transport systems unusable.', 'Governments sometimes deploy troops to deliver emergency supplies when natural disasters make civilian transport systems unusable.', '/truːp/', 'Chính phủ đôi khi điều động quân đội đi phân phát hàng cứu trợ khẩn cấp khi thảm họa thiên nhiên làm tê liệt hệ thống vận tải dân sự.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_56_2_1', 'en-b2-56', 'ten_b2_56_2', 'listening', 'listening', 'Governments should implement policies that make public transport more affordable for people on low incomes.', NULL, 'Trong câu vừa nghe, từ “implement” mang nghĩa nào sau đây?', '["cầu phước; ban phúc","nhà nhập khẩu; nước nhập khẩu","tính đa dạng; sự phong phú","thực hiện; thi hành"]'::jsonb, 3, '“implement” (/ˈɪmpləment/): thực hiện; thi hành. Câu đầy đủ: Governments should implement policies that make public transport more affordable for people on low incomes.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_56_2_2', 'en-b2-56', 'ten_b2_56_2', 'listening', 'listening', 'Governments should ensure that affordable public transport is available to residents in both urban and rural areas.', NULL, 'Trong câu vừa nghe, từ “ensure” mang nghĩa nào sau đây?', '["bảo đảm; cam kết","đáng tin cậy","nắm vững; tinh thông","sự bắt chước; sự mô phỏng"]'::jsonb, 0, '“ensure” (/ɪnˈʃʊr/): bảo đảm; cam kết. Câu đầy đủ: Governments should ensure that affordable public transport is available to residents in both urban and rural areas.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
