INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_56_1', 'en-b2-56', NULL, 'comprehensive_test', 'listening', 'implement', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự thuyết trình; sự biểu diễn; sự minh họa","thời đại; kỷ nguyên; giai đoạn lịch sử","thực hiện; thi hành","đường kính"]'::jsonb, 2, 'implement (/ˈɪmpləment/) → thực hiện; thi hành; dụng cụ; công cụ', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_56_2', 'en-b2-56', NULL, 'comprehensive_test', 'listening', 'Please ensure that all windows are closed before leaving.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Xin vui lòng đảm bảo tất cả các cửa sổ đã được đóng trước khi rời đi.","Thư viện của chúng tôi đã bãi bỏ tiền phạt đối với việc trả sách quá hạn.","Dì tôi làm việc ở cơ quan bộ gần nhà ga.","Hàng xóm của chúng tôi dự định kiện nhà thầu vì lỗi sửa chữa."]'::jsonb, 0, 'Please ensure that all windows are closed before leaving. → Xin vui lòng đảm bảo tất cả các cửa sổ đã được đóng trước khi rời đi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_56_3', 'en-b2-56', NULL, 'comprehensive_test', 'listening', 'forbid', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["điều bình thường; chuẩn mực thông thường","thở dài","cấm; không cho phép","bách khoa toàn thư"]'::jsonb, 2, 'forbid (/fɚˈbɪd/) → cấm; không cho phép', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_56_4', 'en-b2-56', NULL, 'comprehensive_test', 'listening', 'Our club elected a new captain last night.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Câu lạc bộ của chúng tôi đã bầu ra một đội trưởng mới tối qua.","Thư viện của chúng tôi đã bãi bỏ tiền phạt đối với việc trả sách quá hạn.","Là một người nộp thuế, tôi mong muốn những con đường sạch sẽ hơn và các công viên an toàn hơn.","Những bức tường dày kiên cố tạo ra một lớp phòng thủ vững chắc chống lại kẻ địch."]'::jsonb, 0, 'Our club elected a new captain last night. → Câu lạc bộ của chúng tôi đã bầu ra một đội trưởng mới tối qua.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_56_5', 'en-b2-56', NULL, 'comprehensive_test', 'listening', 'ally', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đồng minh; người ủng hộ","thuộc về văn học","Hồi giáo","cách xử lý; sự giải quyết"]'::jsonb, 0, 'ally (/ˈælaɪ/) → đồng minh; người ủng hộ; kết minh; liên minh', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_56_6', 'en-b2-56', NULL, 'comprehensive_test', 'listening', 'Troops helped local families cross the river after the flood.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Viện bảo tàng trưng bày những vũ khí cổ phía sau lớp kính dày.","Binh lính đã giúp các gia đình địa phương vượt sông sau trận lũ.","Chúng tôi nghe tin về hiệp ước mới trên đài phát thanh.","Câu lạc bộ của chúng tôi tiến hành bỏ phiếu dân chủ cho mọi quyết định quan trọng."]'::jsonb, 1, 'Troops helped local families cross the river after the flood. → Binh lính đã giúp các gia đình địa phương vượt sông sau trận lũ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_56_7', 'en-b2-56', NULL, 'comprehensive_test', 'listening', 'arms', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["vũ khí, trang thiết bị quân sự","cũ; trước đây; tiền nhiệm","tổng thể; toàn bộ; chung","suy đoán; phỏng đoán"]'::jsonb, 0, 'arms (/ɑːrmz/) → vũ khí, trang thiết bị quân sự; cánh tay (số nhiều)', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_56_8', 'en-b2-56', NULL, 'comprehensive_test', 'listening', 'We took drastic action and sold our second car.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Xin vui lòng đảm bảo tất cả các cửa sổ đã được đóng trước khi rời đi.","Chúng tôi đã thực hiện biện pháp quyết liệt và bán chiếc xe thứ hai đi.","Nội quy tòa nhà chúng tôi cấm để xe đạp ở hành lang.","Là một người nộp thuế, tôi mong muốn những con đường sạch sẽ hơn và các công viên an toàn hơn."]'::jsonb, 1, 'We took drastic action and sold our second car. → Chúng tôi đã thực hiện biện pháp quyết liệt và bán chiếc xe thứ hai đi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_56_9', 'en-b2-56', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A person or country that supports another.”?', '["ally","democratic","poll","taxpayer"]'::jsonb, 0, 'ally (/ˈælaɪ/) → đồng minh; người ủng hộ', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
