INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_56_18', 'en-b2-56', NULL, 'comprehensive_test', 'reading', NULL, 'Governments should implement policies that make public transport more affordable for people on low incomes.', 'Dựa vào câu trên, từ “implement” có nghĩa phù hợp nhất là gì?', '["nhôm","đơn thuốc; thuốc theo đơn","thực hiện; thi hành","sự điên rồ; hành vi cực kỳ ng U dốt và nguy hiểm"]'::jsonb, 2, 'implement: thực hiện; thi hành; dụng cụ; công cụ. Dịch cả câu: Chính phủ nên thực hiện các chính sách giúp người có thu nhập thấp dễ dàng tiếp cận giao thông công cộng hơn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_56_19', 'en-b2-56', NULL, 'comprehensive_test', 'reading', NULL, 'Governments should ensure that affordable public transport is available to residents in both urban and rural areas.', 'Dựa vào câu trên, từ “ensure” có nghĩa phù hợp nhất là gì?', '["công đoàn","thủ công; nghề thủ công","hồi tưởng; thiền định","bảo đảm; cam kết"]'::jsonb, 3, 'ensure: bảo đảm; cam kết. Dịch cả câu: Chính phủ nên đảm bảo rằng cư dân ở cả khu vực thành thị và nông thôn đều có thể tiếp cận phương tiện giao thông công cộng với giá cả phải chăng.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_56_20', 'en-b2-56', NULL, 'comprehensive_test', 'reading', NULL, 'Governments should forbid companies from releasing untreated waste into rivers to protect public health and aquatic ecosystems.', 'Dựa vào câu trên, từ “forbid” có nghĩa phù hợp nhất là gì?', '["thực tế; khả thi","chuyên gia tâm lý; nhà tâm lý học","cấm; không cho phép","giảm sút; suy giảm"]'::jsonb, 2, 'forbid: cấm; không cho phép. Dịch cả câu: Chính phủ nên cấm các công ty xả nước thải chưa qua xử lý ra sông ngòi để bảo vệ sức khỏe cộng đồng và hệ sinh thái dưới nước.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_56_21', 'en-b2-56', NULL, 'comprehensive_test', 'reading', NULL, 'Citizens should elect representatives who are willing to address long-term environmental challenges rather than seek immediate popularity.', 'Dựa vào câu trên, từ “elect” có nghĩa phù hợp nhất là gì?', '["chương trình giảng dạy; chương trình học","bầu; bầu chọn","tương tác; giao tiếp","tối đa hóa; tận dụng tối đa"]'::jsonb, 1, 'elect: bầu; bầu chọn; chọn; quyết định. Dịch cả câu: Công dân nên bầu ra những đại biểu sẵn sàng giải quyết các thách thức môi trường lâu dài thay vì tìm kiếm sự ủng hộ trước mắt.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_56_22', 'en-b2-56', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hiệp ước; hiệp định quốc tế”', '["largely","treaty","resident","organizational"]'::jsonb, 1, 'hiệp ước; hiệp định quốc tế → treaty (/ˈtriːti/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_56_23', 'en-b2-56', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thủ tiêu; bãi bỏ; hủy bỏ (luật lệ, hệ thống hoặc tập quán)”', '["publicity","abolish","crawl","physicist"]'::jsonb, 1, 'thủ tiêu; bãi bỏ; hủy bỏ (luật lệ, hệ thống hoặc tập quán) → abolish (/əˈbɑːlɪʃ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_56_24', 'en-b2-56', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “quận; hạt; tỉnh (đơn vị hành chính)”', '["pamphlet","county","livestock","donation"]'::jsonb, 1, 'quận; hạt; tỉnh (đơn vị hành chính) → county (/ˈkaʊnti/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-57', 'en', 'Bài 57: Chính phủ & Pháp luật (2) - CEFR B2', 'CEFR B2', 'B2 · Chính phủ & Pháp luật', '20 từ vựng Tiếng Anh CEFR B2 chủ đề chính phủ & pháp luật kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4057, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_approval', 'en-b2-57', 'approval', '/əˈpruːvəl/', 'B2', 'sự phê duyệt; sự cho phép; sự tán thành; sự công nhận', 'n.', 'approve (v.), disapprove (v.), disapproval (n.)', 'Trái nghĩa: disapproval', 'Cụm "approval of" thường chỉ sự tán thành; trong khi "approval for" thường chỉ giấy phép cho dự án.', 'We need the landlord''s approval before painting the kitchen.', NULL, 'Chúng ta cần sự cho phép của chủ nhà trước khi sơn phòng bếp.', '{"wordId":"approval","ukIpa":"/əˈpruːvəl/","usIpa":"/əˈpruːvəl/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"official permission for something to happen","vi":"sự phê duyệt; sự cho phép"},{"pos":"n.","en":"a positive opinion of someone or something","vi":"sự tán thành; sự công nhận"}],"examples":[{"en":"We need the landlord''s approval before painting the kitchen.","vi":"Chúng ta cần sự cho phép của chủ nhà trước khi sơn phòng bếp.","audioKind":"ex"},{"en":"New housing projects should receive approval only when developers demonstrate that adequate transport and public services will be provided.","vi":"Các dự án nhà ở mới chỉ nên được cấp phép khi chủ đầu tư chứng minh được rằng cơ sở hạ tầng giao thông và dịch vụ công cộng đầy đủ sẽ được cung cấp.","audioKind":"ex2"}],"collocations":[{"en":"obtain approval","vi":"đạt được sự phê duyệt"},{"en":"seek approval","vi":"xin phê duyệt"},{"en":"give approval","vi":"cấp phép"},{"en":"meet with approval","vi":"được đón nhận; được tán thành"}],"wordFamily":["approve (v.)","disapprove (v.)","disapproval (n.)"],"synonyms":[],"antonyms":["disapproval"],"tipVi":"Cụm \"approval of\" thường chỉ sự tán thành; trong khi \"approval for\" thường chỉ giấy phép cho dự án.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_embassy', 'en-b2-57', 'embassy', '/ˈembəsi/', 'B2', 'đại sứ quán', 'n.', 'ambassador (n.)', NULL, 'embassy chỉ đại sứ quán; consulate chỉ lãnh sự quán.', 'I contacted the embassy after losing my passport abroad.', NULL, 'Tôi đã liên hệ với đại sứ quán sau khi bị mất hộ chiếu ở nước ngoài.', '{"wordId":"embassy","ukIpa":"/ˈembəsi/","usIpa":"/ˈembəsi/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"An official office representing a country in another country.","vi":"đại sứ quán"}],"examples":[{"en":"I contacted the embassy after losing my passport abroad.","vi":"Tôi đã liên hệ với đại sứ quán sau khi bị mất hộ chiếu ở nước ngoài.","audioKind":"ex"},{"en":"An embassy provides assistance to citizens overseas and helps maintain diplomatic relations between the two countries.","vi":"Đại sứ quán cung cấp sự hỗ trợ cho công dân ở nước ngoài và giúp duy trì quan hệ ngoại giao giữa hai nước.","audioKind":"ex2"}],"collocations":[{"en":"contact the embassy","vi":"liên hệ đại sứ quán"},{"en":"embassy staff","vi":"nhân viên đại sứ quán"},{"en":"foreign embassy","vi":"đại sứ quán nước ngoài"}],"wordFamily":["ambassador (n.)"],"synonyms":[],"antonyms":[],"tipVi":"embassy chỉ đại sứ quán; consulate chỉ lãnh sự quán.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prohibited', 'en-b2-57', 'prohibited', '/prəˈhɪbɪtɪd/', 'B2', 'bị cấm; không được phép', 'adj.', 'prohibit (v.), prohibition (n.), prohibitive (adj.)', 'Đồng nghĩa: forbidden, banned · Trái nghĩa: permitted, allowed', 'Từ này cũng là dạng quá khứ và quá khứ phân từ của prohibit; cấu trúc cấm làm gì dùng prohibit doing.', 'Feeding the animals is prohibited at this wildlife park.', NULL, 'Việc cho động vật ăn bị cấm tại công viên động vật hoang dã này.', '{"wordId":"prohibited","ukIpa":"/prəˈhɪbɪtɪd/","usIpa":"/prəˈhɪbɪtɪd/","cefr":"B2","topic":"government","senses":[{"pos":"adj.","en":"Not allowed by a law or rule.","vi":"bị cấm; không được phép"}],"examples":[{"en":"Feeding the animals is prohibited at this wildlife park.","vi":"Việc cho động vật ăn bị cấm tại công viên động vật hoang dã này.","audioKind":"ex"},{"en":"Private vehicles are prohibited in certain urban areas to improve air quality and protect pedestrians.","vi":"Các phương tiện cá nhân bị cấm ở một số khu vực đô thị nhằm cải thiện chất lượng không khí và bảo vệ người đi bộ.","audioKind":"ex2"}],"collocations":[{"en":"strictly prohibited","vi":"bị nghiêm cấm"},{"en":"prohibited by law","vi":"bị pháp luật cấm"},{"en":"prohibited items","vi":"các mặt hàng cấm"}],"wordFamily":["prohibit (v.)","prohibition (n.)","prohibitive (adj.)"],"synonyms":["forbidden","banned"],"antonyms":["permitted","allowed"],"tipVi":"Từ này cũng là dạng quá khứ và quá khứ phân từ của prohibit; cấu trúc cấm làm gì dùng prohibit doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_socialism', 'en-b2-57', 'socialism', '/ˈsoʊʃəlɪzəm/', 'B2', 'chủ nghĩa xã hội', 'n.', 'socialist (n.), socialist (adj.), socialistic (adj.)', 'Trái nghĩa: capitalism', 'Thường là danh từ không đếm được; socialist có thể chỉ người theo chủ nghĩa xã hội.', 'Our history teacher explained socialism during today''s lively class discussion.', NULL, 'Giáo viên lịch sử của chúng tôi đã giảng giải về chủ nghĩa xã hội trong buổi thảo luận sôi nổi trên lớp ngày hôm nay.', '{"wordId":"socialism","ukIpa":"/ˈsəʊʃəlɪzəm/","usIpa":"/ˈsoʊʃəlɪzəm/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"A political and economic system favouring public ownership of productive resources","vi":"chủ nghĩa xã hội"}],"examples":[{"en":"Our history teacher explained socialism during today''s lively class discussion.","vi":"Giáo viên lịch sử của chúng tôi đã giảng giải về chủ nghĩa xã hội trong buổi thảo luận sôi nổi trên lớp ngày hôm nay.","audioKind":"ex"},{"en":"Debates about socialism often focus on public ownership, economic equality, and the appropriate role of government.","vi":"Các cuộc tranh luận về chủ nghĩa xã hội thường tập trung vào quyền sở hữu công cộng, bình đẳng kinh tế và vai trò thích hợp của nhà nước.","audioKind":"ex2"}],"collocations":[{"en":"democratic socialism","vi":"chủ nghĩa xã hội dân chủ"},{"en":"socialism and capitalism","vi":"chủ nghĩa xã hội và chủ nghĩa tư bản"},{"en":"principles of socialism","vi":"các nguyên lý của chủ nghĩa xã hội"}],"wordFamily":["socialist (n.)","socialist (adj.)","socialistic (adj.)"],"synonyms":[],"antonyms":["capitalism"],"tipVi":"Thường là danh từ không đếm được; socialist có thể chỉ người theo chủ nghĩa xã hội.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_authority', 'en-b2-57', 'authority', '/əˈθɔːrəti/', 'B2', 'quyền lực; thẩm quyền; chính quyền; cơ quan có thẩm quyền; chuyên gia; người có uy tín chuyên môn', 'n.', 'authorise (v.), authorisation (n.), authoritative (adj.)', NULL, 'Mang nghĩa quyền lực thường không đếm được; "the authorities" thường chỉ chính quyền.', 'Only the manager has authority to approve this refund.', NULL, 'Chỉ có quản lý mới có thẩm quyền phê duyệt khoản hoàn tiền này.', '{"wordId":"authority","ukIpa":"/ɔːˈθɒrəti/","usIpa":"/əˈθɔːrəti/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"the power or right to make decisions and enforce rules","vi":"quyền lực; thẩm quyền"},{"pos":"n.","en":"an official body responsible for a particular area or service","vi":"chính quyền; cơ quan có thẩm quyền"},{"pos":"n.","en":"a person with extensive knowledge of a particular subject","vi":"chuyên gia; người có uy tín chuyên môn"}],"examples":[{"en":"Only the manager has authority to approve this refund.","vi":"Chỉ có quản lý mới có thẩm quyền phê duyệt khoản hoàn tiền này.","audioKind":"ex"},{"en":"Local authorities should consult residents before introducing policies that significantly affect access to public services.","vi":"Chính quyền địa phương nên tham khảo ý kiến cư dân trước khi ban hành các chính sách ảnh hưởng đáng kể đến việc tiếp cận dịch vụ công.","audioKind":"ex2"}],"collocations":[{"en":"have authority to do something","vi":"có thẩm quyền làm gì"},{"en":"local authorities","vi":"chính quyền địa phương"},{"en":"an authority on","vi":"chuyên gia về lĩnh vực nào"},{"en":"abuse of authority","vi":"lạm dụng quyền lực"}],"wordFamily":["authorise (v.)","authorisation (n.)","authoritative (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Mang nghĩa quyền lực thường không đếm được; \"the authorities\" thường chỉ chính quyền.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_republic', 'en-b2-57', 'republic', '/rɪˈpʌblɪk/', 'B2', 'nước cộng hòa; chế độ cộng hòa', 'n.', 'republican (adj.), republicanism (n.)', 'Trái nghĩa: monarchy', 'Cộng hòa không có vua chúa (quân chủ), nhưng không nhất thiết mang nghĩa là dân chủ.', 'Our teacher explained how the country became a republic.', NULL, 'Giáo viên của chúng tôi giải thích cách đất nước này trở thành một nước cộng hòa.', '{"wordId":"republic","ukIpa":"/rɪˈpʌblɪk/","usIpa":"/rɪˈpʌblɪk/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"A country whose head of state is not a monarch.","vi":"nước cộng hòa; chế độ cộng hòa"}],"examples":[{"en":"Our teacher explained how the country became a republic.","vi":"Giáo viên của chúng tôi giải thích cách đất nước này trở thành một nước cộng hòa.","audioKind":"ex"},{"en":"In a republic, constitutional rules usually define the powers of the head of state and other public institutions.","vi":"Trong một nước cộng hòa, các quy định hiến pháp thường xác định quyền hạn của nguyên thủ quốc gia và các cơ quan công quyền khác.","audioKind":"ex2"}],"collocations":[{"en":"become a republic","vi":"trở thành nước cộng hòa"},{"en":"establish a republic","vi":"thành lập nước cộng hòa"},{"en":"a parliamentary republic","vi":"nước cộng hòa nghị viện"}],"wordFamily":["republican (adj.)","republicanism (n.)"],"synonyms":[],"antonyms":["monarchy"],"tipVi":"Cộng hòa không có vua chúa (quân chủ), nhưng không nhất thiết mang nghĩa là dân chủ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_regulation', 'en-b2-57', 'regulation', '/ˌreɡjəˈleɪʃən/', 'B2', 'quy định; điều lệ; sự quản lý; sự điều tiết', 'n.', 'regulate (v.), regulatory (adj.), regulator (n.)', NULL, 'Quy định cụ thể thường đếm được; khi chỉ quá trình quản lý thì thường không đếm được.', 'Safety regulations require everyone here to wear a helmet.', NULL, 'Quy định an toàn yêu cầu mọi người ở đây phải đội mũ bảo hiểm.', '{"wordId":"regulation","ukIpa":"/ˌreɡjəˈleɪʃən/","usIpa":"/ˌreɡjəˈleɪʃən/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"An official rule controlling how something must be done.","vi":"quy định; điều lệ"},{"pos":"n.","en":"The process of controlling an activity or maintaining a condition.","vi":"sự quản lý; sự điều tiết"}],"examples":[{"en":"Safety regulations require everyone here to wear a helmet.","vi":"Quy định an toàn yêu cầu mọi người ở đây phải đội mũ bảo hiểm.","audioKind":"ex"},{"en":"Stricter regulation of industrial waste could reduce water pollution and improve public health in nearby communities.","vi":"Việc siết chặt quản lý chất thải công nghiệp có thể làm giảm ô nhiễm nguồn nước và cải thiện sức khỏe cộng đồng ở các khu dân cư lân cận.","audioKind":"ex2"}],"collocations":[{"en":"safety regulations","vi":"quy định an toàn"},{"en":"comply with regulations","vi":"tuân thủ quy định"},{"en":"government regulation","vi":"sự quản lý của nhà nước"},{"en":"temperature regulation","vi":"sự điều chỉnh nhiệt độ"}],"wordFamily":["regulate (v.)","regulatory (adj.)","regulator (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Quy định cụ thể thường đếm được; khi chỉ quá trình quản lý thì thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_regulate', 'en-b2-57', 'regulate', '/ˈreɡjəleɪt/', 'B2', 'kiểm soát, quản lý thông qua quy tắc hoặc luật lệ; điều chỉnh cái gì để duy trì mức độ hoặc tốc độ phù hợp', 'v.', 'regulation (n.), regulator (n.), regulatory (adj.), deregulate (v.)', 'Đồng nghĩa: control, govern', 'Đây là ngoại động từ nên đi thẳng với tân ngữ; regulate temperature có nghĩa là điều chỉnh nhiệt độ.', 'This small device helps regulate the temperature indoors.', NULL, 'Thiết bị nhỏ này giúp điều hòa nhiệt độ trong nhà.', '{"wordId":"regulate","ukIpa":"/ˈreɡjuleɪt/","usIpa":"/ˈreɡjəleɪt/","cefr":"B2","topic":"government","senses":[{"pos":"v.","en":"control an activity through rules or laws","vi":"kiểm soát, quản lý thông qua quy tắc hoặc luật lệ"},{"pos":"v.","en":"adjust something to maintain a suitable level or rate","vi":"điều chỉnh cái gì để duy trì mức độ hoặc tốc độ phù hợp"}],"examples":[{"en":"This small device helps regulate the temperature indoors.","vi":"Thiết bị nhỏ này giúp điều hòa nhiệt độ trong nhà.","audioKind":"ex"},{"en":"Governments should regulate industrial emissions to protect public health without placing unnecessary burdens on small businesses.","vi":"Chính phủ nên quản lý các chất thải công nghiệp để bảo vệ sức khỏe cộng đồng mà không tạo thêm gánh nặng không cần thiết cho các doanh nghiệp nhỏ.","audioKind":"ex2"}],"collocations":[{"en":"regulate an industry","vi":"quản lý một ngành công nghiệp"},{"en":"regulate emissions","vi":"điều tiết khí thải"},{"en":"regulate body temperature","vi":"điều hòa thân nhiệt"},{"en":"strictly regulated","vi":"chịu sự quản lý nghiêm ngặt"}],"wordFamily":["regulation (n.)","regulator (n.)","regulatory (adj.)","deregulate (v.)"],"synonyms":["control","govern"],"antonyms":[],"tipVi":"Đây là ngoại động từ nên đi thẳng với tân ngữ; regulate temperature có nghĩa là điều chỉnh nhiệt độ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grant', 'en-b2-57', 'grant', '/ɡrænt/', 'B2', 'khoản trợ cấp, tiền cấp phát từ một tổ chức cho mục đích cụ thể; chấp thuận, ban phát chính thức theo yêu cầu; thừa nhận điều gì là đúng dù có phần miễn cưỡng', 'n.', NULL, NULL, 'Cấu trúc grant sb sth có thể chuyển thành grant sth to sb.', 'A small grant helped us repair the village playground.', NULL, 'Một khoản trợ cấp nhỏ đã giúp chúng tôi sửa sang lại khu vui chơi của làng.', '{"wordId":"grant","ukIpa":"/ɡrɑːnt/","usIpa":"/ɡrænt/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"money given by an organisation for a particular purpose","vi":"khoản trợ cấp, tiền cấp phát từ một tổ chức cho mục đích cụ thể"},{"pos":"v.","en":"to officially give someone something they request","vi":"chấp thuận, ban phát chính thức theo yêu cầu"},{"pos":"v.","en":"to accept that something is true, often reluctantly","vi":"thừa nhận điều gì là đúng dù có phần miễn cưỡng"}],"examples":[{"en":"A small grant helped us repair the village playground.","vi":"Một khoản trợ cấp nhỏ đã giúp chúng tôi sửa sang lại khu vui chơi của làng.","audioKind":"ex"},{"en":"Governments should provide research grants to universities developing affordable technologies for reducing household energy consumption.","vi":"Chính phủ nên cung cấp các khoản tài trợ nghiên cứu cho các trường đại học phát triển công nghệ giá rẻ nhằm giảm mức tiêu thụ năng lượng của các hộ gia đình.","audioKind":"ex2"}],"collocations":[{"en":"apply for a grant","vi":"xin trợ cấp"},{"en":"research grant","vi":"khoản tài trợ nghiên cứu"},{"en":"grant permission","vi":"cấp phép"},{"en":"take something for granted","vi":"coi điều gì là hiển nhiên"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc grant sb sth có thể chuyển thành grant sth to sb.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_imprison', 'en-b2-57', 'imprison', '/ɪmˈprɪzən/', 'B2', 'tống giam; bỏ tù', 'v.', 'prison (n.), prisoner (n.), imprisonment (n.)', 'Đồng nghĩa: incarcerate, confine · Trái nghĩa: release, free', 'Cụm "be imprisoned for" có thể theo sau bởi tội danh hoặc thời hạn tù.', 'The judge imprisoned the thief for stealing valuable paintings.', NULL, 'Thẩm phán đã bỏ tù tên trộm vì tội ăn cắp những bức tranh quý giá.', '{"wordId":"imprison","ukIpa":"/ɪmˈprɪzən/","usIpa":"/ɪmˈprɪzən/","cefr":"B2","topic":"government","senses":[{"pos":"v.","en":"To put someone in prison or keep them confined.","vi":"tống giam; bỏ tù"}],"examples":[{"en":"The judge imprisoned the thief for stealing valuable paintings.","vi":"Thẩm phán đã bỏ tù tên trộm vì tội ăn cắp những bức tranh quý giá.","audioKind":"ex"},{"en":"Governments should consider whether imprisoning people for minor offences is more effective than providing supervised community service.","vi":"Chính phủ nên cân nhắc xem việc bỏ tù những kẻ phạm tội nhẹ có hiệu quả hơn so với việc bắt lao động công ích có giám sát hay không.","audioKind":"ex2"}],"collocations":[{"en":"be imprisoned for","vi":"bị bỏ tù vì"},{"en":"imprison someone for life","vi":"tù chung thân"},{"en":"false imprisonment","vi":"bắt giữ trái pháp luật"}],"wordFamily":["prison (n.)","prisoner (n.)","imprisonment (n.)"],"synonyms":["incarcerate","confine"],"antonyms":["release","free"],"tipVi":"Cụm \"be imprisoned for\" có thể theo sau bởi tội danh hoặc thời hạn tù.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_diplomatic', 'en-b2-57', 'diplomatic', '/ˌdɪpləˈmætɪk/', 'B2', 'thuộc về ngoại giao; khéo léo; khôn ngoan; có ngoại giao', 'adj.', 'diplomacy (n.), diplomat (n.), diplomatically (adv.)', 'Đồng nghĩa: tactful · Trái nghĩa: tactless', 'Có thể dùng để chỉ quan hệ ngoại giao giữa các quốc gia hoặc miêu tả phong cách ứng xử khéo léo, tế nhị trong giao tiếp.', 'You gave a diplomatic answer to that awkward question.', NULL, 'Bạn đã đưa ra một câu trả lời rất khéo léo cho câu hỏi khó xử đó.', '{"wordId":"diplomatic","ukIpa":"/ˌdɪpləˈmætɪk/","usIpa":"/ˌdɪpləˈmætɪk/","cefr":"B2","topic":"government","senses":[{"pos":"adj.","en":"relating to official relations between countries","vi":"thuộc về ngoại giao"},{"pos":"adj.","en":"handling people sensitively to avoid offence or conflict","vi":"khéo léo; khôn ngoan; có ngoại giao"}],"examples":[{"en":"You gave a diplomatic answer to that awkward question.","vi":"Bạn đã đưa ra một câu trả lời rất khéo léo cho câu hỏi khó xử đó.","audioKind":"ex"},{"en":"Maintaining diplomatic relations allows countries to resolve disagreements through negotiation rather than allowing tensions to escalate.","vi":"Duy trì quan hệ ngoại giao giúp các quốc gia giải quyết bất đồng thông qua đàm phán thay vì để căng thẳng leo thang.","audioKind":"ex2"}],"collocations":[{"en":"diplomatic relations","vi":"quan hệ ngoại giao"},{"en":"diplomatic efforts","vi":"nỗ lực ngoại giao"},{"en":"a diplomatic solution","vi":"giải pháp ngoại giao"},{"en":"a diplomatic answer","vi":"câu trả lời khéo léo"}],"wordFamily":["diplomacy (n.)","diplomat (n.)","diplomatically (adv.)"],"synonyms":["tactful"],"antonyms":["tactless"],"tipVi":"Có thể dùng để chỉ quan hệ ngoại giao giữa các quốc gia hoặc miêu tả phong cách ứng xử khéo léo, tế nhị trong giao tiếp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_parliament', 'en-b2-57', 'parliament', '/ˈpɑːrləmənt/', 'B2', 'nghị viện; quốc hội', 'n.', 'parliamentary (adj.), parliamentarian (n.)', 'Đồng nghĩa: legislature', 'Khi chỉ một nghị viện cụ thể của quốc gia thường được viết hoa; nghị sĩ Anh thường được viết tắt là MP.', 'Our class visited parliament and watched a lively debate.', NULL, 'Lớp chúng tôi đã đến thăm tòa nhà quốc hội và theo dõi một cuộc tranh luận sôi nổi.', '{"wordId":"parliament","ukIpa":"/ˈpɑːləmənt/","usIpa":"/ˈpɑːrləmənt/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"A country''s group of representatives that debates and makes laws","vi":"nghị viện; quốc hội"}],"examples":[{"en":"Our class visited parliament and watched a lively debate.","vi":"Lớp chúng tôi đã đến thăm tòa nhà quốc hội và theo dõi một cuộc tranh luận sôi nổi.","audioKind":"ex"},{"en":"Parliament should examine the long-term environmental consequences of major infrastructure projects before approving public funding.","vi":"Nghị viện nên xem xét các hậu quả môi trường lâu dài của các dự án cơ sở hạ tầng lớn trước khi phê duyệt nguồn vốn công.","audioKind":"ex2"}],"collocations":[{"en":"member of parliament","vi":"thành viên nghị viện; nghị sĩ"},{"en":"parliamentary debate","vi":"cuộc tranh luận tại nghị viện"},{"en":"dissolve parliament","vi":"giải tán nghị viện"}],"wordFamily":["parliamentary (adj.)","parliamentarian (n.)"],"synonyms":["legislature"],"antonyms":[],"tipVi":"Khi chỉ một nghị viện cụ thể của quốc gia thường được viết hoa; nghị sĩ Anh thường được viết tắt là MP.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ruling', 'en-b2-57', 'ruling', '/ˈruːlɪŋ/', 'B2', 'đang cầm quyền; phán quyết; quyết định chính thức', 'adj.', 'rule (v.), rule (n.), ruler (n.)', 'Đồng nghĩa: governing', 'Khi là tính từ thường đứng trước danh từ; khi là danh từ chỉ phán quyết chính thức.', 'The ruling party promised to improve our local buses.', NULL, 'Đảng cầm quyền đã hứa cải thiện hệ thống xe buýt địa phương của chúng ta.', '{"wordId":"ruling","ukIpa":"/ˈruːlɪŋ/","usIpa":"/ˈruːlɪŋ/","cefr":"B2","topic":"government","senses":[{"pos":"adj.","en":"Having political power over a country or group","vi":"đang cầm quyền"},{"pos":"n.","en":"An official decision made by a judge or authority","vi":"phán quyết; quyết định chính thức"}],"examples":[{"en":"The ruling party promised to improve our local buses.","vi":"Đảng cầm quyền đã hứa cải thiện hệ thống xe buýt địa phương của chúng ta.","audioKind":"ex"},{"en":"A recent court ruling requires employers to provide clearer information about working hours and holiday entitlement.","vi":"Một phán quyết gần đây của tòa án yêu cầu người sử dụng lao động cung cấp thông tin rõ ràng hơn về giờ làm việc và quyền lợi nghỉ phép.","audioKind":"ex2"}],"collocations":[{"en":"the ruling party","vi":"đảng cầm quyền"},{"en":"the ruling class","vi":"tầng lớp thống trị"},{"en":"a court ruling","vi":"phán quyết của tòa án"},{"en":"issue a ruling","vi":"đưa ra phán quyết"}],"wordFamily":["rule (v.)","rule (n.)","ruler (n.)"],"synonyms":["governing"],"antonyms":[],"tipVi":"Khi là tính từ thường đứng trước danh từ; khi là danh từ chỉ phán quyết chính thức.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_province', 'en-b2-57', 'province', '/ˈprɑːvɪns/', 'B2', 'tỉnh; khu vực hành chính; lĩnh vực phụ trách; chuyên môn thuộc về ai', 'n.', 'provincial (adj.)', NULL, 'Khi diễn đạt ý nghĩa “lĩnh vực trách nhiệm”, cụm từ thường dùng là the province of.', 'My aunt lives in a quiet village in this province.', NULL, 'Dì tôi sống ở một ngôi làng yên bình thuộc tỉnh này.', '{"wordId":"province","ukIpa":"/ˈprɒvɪns/","usIpa":"/ˈprɑːvɪns/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"A major administrative area within a country","vi":"tỉnh; khu vực hành chính"},{"pos":"n.","en":"An area of responsibility or expertise belonging to someone","vi":"lĩnh vực phụ trách; chuyên môn thuộc về ai"}],"examples":[{"en":"My aunt lives in a quiet village in this province.","vi":"Dì tôi sống ở một ngôi làng yên bình thuộc tỉnh này.","audioKind":"ex"},{"en":"Each province should adapt its transport policies to local geography, population density, and economic needs.","vi":"Mỗi tỉnh nên điều chỉnh chính sách giao thông phù hợp với điều kiện địa lý, mật độ dân số và nhu cầu kinh tế tại địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a coastal province","vi":"một tỉnh ven biển"},{"en":"provincial capital","vi":"thủ phủ tỉnh"},{"en":"the province of experts","vi":"lĩnh vực của chuyên gia"}],"wordFamily":["provincial (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi diễn đạt ý nghĩa “lĩnh vực trách nhiệm”, cụm từ thường dùng là the province of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_violation', 'en-b2-57', 'violation', '/ˌvaɪəˈleɪʃən/', 'B2', 'hành vi vi phạm, sự vi phạm (luật lệ, quy tắc hoặc thỏa thuận); sự xâm phạm, sự vi phạm (quyền lợi hoặc quyền riêng tư của ai đó)', 'n.', 'violate (v.), violator (n.)', 'Đồng nghĩa: breach, infringement', 'Dùng "a violation of" để diễn tả hành vi vi phạm hoặc xâm phạm một thứ gì đó.', 'Parking across this entrance is a clear violation.', NULL, 'Đỗ xe chắn ngang lối ra vào này là hành vi vi phạm rõ mười mươi.', '{"wordId":"violation","ukIpa":"/ˌvaɪəˈleɪʃən/","usIpa":"/ˌvaɪəˈleɪʃən/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"an act that breaks a law, rule, or agreement","vi":"hành vi vi phạm, sự vi phạm (luật lệ, quy tắc hoặc thỏa thuận)"},{"pos":"n.","en":"an act that disregards someone''s rights or privacy","vi":"sự xâm phạm, sự vi phạm (quyền lợi hoặc quyền riêng tư của ai đó)"}],"examples":[{"en":"Parking across this entrance is a clear violation.","vi":"Đỗ xe chắn ngang lối ra vào này là hành vi vi phạm rõ mười mươi.","audioKind":"ex"},{"en":"Collecting personal information without consent may constitute a violation of privacy, even when the data remains confidential.","vi":"Việc thu thập thông tin cá nhân mà không có sự đồng ý có thể cấu thành hành vi xâm phạm quyền riêng tư, ngay cả khi dữ liệu vẫn được bảo mật.","audioKind":"ex2"}],"collocations":[{"en":"a violation of the law","vi":"vi phạm pháp luật"},{"en":"in violation of","vi":"vi phạm (quy định nào đó)"},{"en":"a violation of privacy","vi":"xâm phạm quyền riêng tư"},{"en":"a traffic violation","vi":"lỗi vi phạm giao thông"}],"wordFamily":["violate (v.)","violator (n.)"],"synonyms":["breach","infringement"],"antonyms":[],"tipVi":"Dùng \"a violation of\" để diễn tả hành vi vi phạm hoặc xâm phạm một thứ gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tackle', 'en-b2-57', 'tackle', '/ˈtækəl/', 'B2', 'giải quyết; đối phó; xử lý; cản phá; tranh bóng; cản người; dụng cụ; trang thiết bị (đặc biệt là đồ câu cá)', 'v.', NULL, 'Đồng nghĩa: address, confront', 'Tackle đi thẳng với tân ngữ chỉ vấn đề, không cần giới từ with; nhấn mạnh hành động quyết tâm bắt tay vào xử lý.', 'Let''s tackle the messy kitchen before our guests arrive.', NULL, 'Hãy cùng nhau dọn dẹp nhà bếp bừa bộn trước khi khách đến nhé.', '{"wordId":"tackle","ukIpa":"/ˈtækəl/","usIpa":"/ˈtækəl/","cefr":"B2","topic":"government","senses":[{"pos":"v.","en":"Make a determined effort to deal with a difficult problem.","vi":"giải quyết; đối phó; xử lý"},{"pos":"v.","en":"Try to stop an opponent or take their ball.","vi":"cản phá; tranh bóng; cản người"},{"pos":"n.","en":"Equipment used for an activity, especially fishing.","vi":"dụng cụ; trang thiết bị (đặc biệt là đồ câu cá)"}],"examples":[{"en":"Let''s tackle the messy kitchen before our guests arrive.","vi":"Hãy cùng nhau dọn dẹp nhà bếp bừa bộn trước khi khách đến nhé.","audioKind":"ex"},{"en":"Governments need to tackle housing shortages by supporting affordable construction and improving access to public transport.","vi":"Chính phủ cần giải quyết tình trạng thiếu nhà ở bằng cách hỗ trợ xây dựng nhà ở giá rẻ và cải thiện khả năng tiếp cận giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"tackle a problem","vi":"giải quyết vấn đề"},{"en":"tackle inequality","vi":"giải quyết bất bình đẳng"},{"en":"fishing tackle","vi":"dụng cụ câu cá"},{"en":"tackle an opponent","vi":"cản phá đối thủ"}],"wordFamily":[],"synonyms":["address","confront"],"antonyms":[],"tipVi":"Tackle đi thẳng với tân ngữ chỉ vấn đề, không cần giới từ with; nhấn mạnh hành động quyết tâm bắt tay vào xử lý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_restriction', 'en-b2-57', 'restriction', '/rɪˈstrɪkʃən/', 'B2', 'sự hạn chế; quy định hạn chế', 'n.', 'restrict (v.), restricted (adj.), restrictive (adj.)', 'Đồng nghĩa: limitation, constraint', 'Sự hạn chế đối với việc gì dùng restriction on; các quy định cụ thể thường ở dạng số nhiều.', 'There is a parking restriction outside our building today.', NULL, 'Hôm nay có quy định hạn chế đậu xe bên ngoài tòa nhà của chúng ta.', '{"wordId":"restriction","ukIpa":"/rɪˈstrɪkʃən/","usIpa":"/rɪˈstrɪkʃən/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"a rule or condition that limits what is allowed","vi":"sự hạn chế; quy định hạn chế"}],"examples":[{"en":"There is a parking restriction outside our building today.","vi":"Hôm nay có quy định hạn chế đậu xe bên ngoài tòa nhà của chúng ta.","audioKind":"ex"},{"en":"Restrictions on private car use may encourage commuters to choose more sustainable forms of transport.","vi":"Việc hạn chế sử dụng xe hơi cá nhân có thể khuyến khích những người đi làm lựa chọn các hình thức giao thông bền vững hơn.","audioKind":"ex2"}],"collocations":[{"en":"impose restrictions","vi":"áp dụng các biện pháp hạn chế"},{"en":"lift restrictions","vi":"dỡ bỏ lệnh hạn chế"},{"en":"restrictions on travel","vi":"hạn chế về việc đi lại"},{"en":"age restriction","vi":"giới hạn độ tuổi"}],"wordFamily":["restrict (v.)","restricted (adj.)","restrictive (adj.)"],"synonyms":["limitation","constraint"],"antonyms":[],"tipVi":"Sự hạn chế đối với việc gì dùng restriction on; các quy định cụ thể thường ở dạng số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_voter', 'en-b2-57', 'voter', '/ˈvoʊtər/', 'B2', 'cử tri; người bỏ phiếu', 'n.', 'vote (v.), vote (n.), voting (n.)', 'Đồng nghĩa: elector', 'voter chỉ người, vote có thể chỉ hành động bỏ phiếu hoặc một lá phiếu.', 'Each voter placed a folded ballot into the sealed box.', NULL, 'Mỗi cử tri đã bỏ một lá phiếu được gấp lại vào chiếc hòm niêm phong.', '{"wordId":"voter","ukIpa":"/ˈvəʊtə/","usIpa":"/ˈvoʊtər/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"Someone who votes or has the right to vote","vi":"cử tri; người bỏ phiếu"}],"examples":[{"en":"Each voter placed a folded ballot into the sealed box.","vi":"Mỗi cử tri đã bỏ một lá phiếu được gấp lại vào chiếc hòm niêm phong.","audioKind":"ex"},{"en":"Clear information about public policies enables each voter to make a more informed choice during elections.","vi":"Thông tin minh bạch về các chính sách công giúp mỗi cử tri đưa ra lựa chọn sáng suốt hơn trong các cuộc bầu cử.","audioKind":"ex2"}],"collocations":[{"en":"registered voter","vi":"đăng ký cử tri"},{"en":"eligible voter","vi":"cử tri đủ điều kiện"},{"en":"voter turnout","vi":"tỷ lệ cử tri đi bầu"},{"en":"voter registration","vi":"việc đăng ký cử tri"}],"wordFamily":["vote (v.)","vote (n.)","voting (n.)"],"synonyms":["elector"],"antonyms":[],"tipVi":"voter chỉ người, vote có thể chỉ hành động bỏ phiếu hoặc một lá phiếu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ambassador', 'en-b2-57', 'ambassador', '/æmˈbæsədər/', 'B2', 'đại sứ; đại diện; sứ giả quảng bá', 'n.', 'ambassadorship (n.)', 'Đồng nghĩa: envoy, representative', 'Đại sứ tại một quốc gia dùng ambassador to, không dùng for.', 'The ambassador welcomed visitors to the embassy garden.', NULL, 'Đại sứ chào đón khách tham quan tại khu vườn của đại sứ quán.', '{"wordId":"ambassador","ukIpa":"/æmˈbæsədə/","usIpa":"/æmˈbæsədər/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"A senior official representing their country in another country.","vi":"đại sứ"},{"pos":"n.","en":"Someone who publicly represents or promotes a group or cause.","vi":"đại diện; sứ giả quảng bá"}],"examples":[{"en":"The ambassador welcomed visitors to the embassy garden.","vi":"Đại sứ chào đón khách tham quan tại khu vườn của đại sứ quán.","audioKind":"ex"},{"en":"An ambassador can strengthen international cooperation by encouraging educational exchanges and maintaining dialogue during periods of tension.","vi":"Một đại sứ có thể thắt chặt hợp tác quốc tế bằng cách khuyến khích các chương trình trao đổi giáo dục và duy trì đối thoại trong thời kỳ căng thẳng.","audioKind":"ex2"}],"collocations":[{"en":"ambassador to","vi":"đại sứ tại..."},{"en":"appoint an ambassador","vi":"bổ nhiệm đại sứ"},{"en":"goodwill ambassador","vi":"đại sứ thiện chí"}],"wordFamily":["ambassadorship (n.)"],"synonyms":["envoy","representative"],"antonyms":[],"tipVi":"Đại sứ tại một quốc gia dùng ambassador to, không dùng for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_congressman', 'en-b2-57', 'congressman', '/ˈkɑːŋɡrəsmən/', 'B2', 'nghị sĩ quốc hội; hạ nghị sĩ Mỹ', 'n.', 'congress (n.), congressional (adj.), congresswoman (n.)', NULL, 'Trong ngữ cảnh Mỹ, từ này thường chỉ nam hạ nghị sĩ; từ trung tính về giới là member of Congress.', 'The congressman listened as local residents described their transport problems.', NULL, 'Vị hạ nghị sĩ lắng nghe khi người dân địa phương trình bày các vấn đề giao thông của họ.', '{"wordId":"congressman","ukIpa":"/ˈkɒŋɡresmən/","usIpa":"/ˈkɑːŋɡrəsmən/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"A male congress member, especially in the US House of Representatives.","vi":"nghị sĩ quốc hội; hạ nghị sĩ Mỹ"}],"examples":[{"en":"The congressman listened as local residents described their transport problems.","vi":"Vị hạ nghị sĩ lắng nghe khi người dân địa phương trình bày các vấn đề giao thông của họ.","audioKind":"ex"},{"en":"A congressman may propose legislation to improve public services, but securing support from other representatives is essential.","vi":"Một hạ nghị sĩ có thể đề xuất các dự luật nhằm cải thiện dịch vụ công, nhưng việc giành được sự ủng hộ từ các đại biểu khác là vô cùng cốt lõi.","audioKind":"ex2"}],"collocations":[{"en":"elect a congressman","vi":"bầu nghị sĩ"},{"en":"local congressman","vi":"nghị sĩ địa phương"},{"en":"former congressman","vi":"cựu hạ nghị sĩ"}],"wordFamily":["congress (n.)","congressional (adj.)","congresswoman (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong ngữ cảnh Mỹ, từ này thường chỉ nam hạ nghị sĩ; từ trung tính về giới là member of Congress.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_57_1', 'en-b2-57', 'Cách dùng “diplomatic” (adj.) — thuộc về ngoại giao', 'diplomatic relations  ·  diplomatic efforts  ·  a diplomatic solution', 'Có thể dùng để chỉ quan hệ ngoại giao giữa các quốc gia hoặc miêu tả phong cách ứng xử khéo léo, tế nhị trong giao tiếp.', 'Họ từ (Word Family): diplomacy (n.), diplomat (n.), diplomatically (adv.) | Đồng nghĩa: tactful · Trái nghĩa: tactless', '[{"hanzi":"You gave a diplomatic answer to that awkward question.","pinyin":"","meaning":"Bạn đã đưa ra một câu trả lời rất khéo léo cho câu hỏi khó xử đó."},{"hanzi":"Maintaining diplomatic relations allows countries to resolve disagreements through negotiation rather than allowing tensions to escalate.","pinyin":"","meaning":"Duy trì quan hệ ngoại giao giúp các quốc gia giải quyết bất đồng thông qua đàm phán thay vì để căng thẳng leo thang."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_57_2', 'en-b2-57', 'Cách dùng “tackle” (v.) — giải quyết; đối phó; xử lý', 'tackle a problem  ·  tackle inequality  ·  fishing tackle', 'Tackle đi thẳng với tân ngữ chỉ vấn đề, không cần giới từ with; nhấn mạnh hành động quyết tâm bắt tay vào xử lý.', 'Đồng nghĩa: address, confront', '[{"hanzi":"Let''s tackle the messy kitchen before our guests arrive.","pinyin":"","meaning":"Hãy cùng nhau dọn dẹp nhà bếp bừa bộn trước khi khách đến nhé."},{"hanzi":"Governments need to tackle housing shortages by supporting affordable construction and improving access to public transport.","pinyin":"","meaning":"Chính phủ cần giải quyết tình trạng thiếu nhà ở bằng cách hỗ trợ xây dựng nhà ở giá rẻ và cải thiện khả năng tiếp cận giao thông công cộng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_57_3', 'en-b2-57', 'Cách dùng “parliament” (n.) — nghị viện; quốc hội', 'member of parliament  ·  parliamentary debate  ·  dissolve parliament', 'Khi chỉ một nghị viện cụ thể của quốc gia thường được viết hoa; nghị sĩ Anh thường được viết tắt là MP.', 'Họ từ (Word Family): parliamentary (adj.), parliamentarian (n.) | Đồng nghĩa: legislature', '[{"hanzi":"Our class visited parliament and watched a lively debate.","pinyin":"","meaning":"Lớp chúng tôi đã đến thăm tòa nhà quốc hội và theo dõi một cuộc tranh luận sôi nổi."},{"hanzi":"Parliament should examine the long-term environmental consequences of major infrastructure projects before approving public funding.","pinyin":"","meaning":"Nghị viện nên xem xét các hậu quả môi trường lâu dài của các dự án cơ sở hạ tầng lớn trước khi phê duyệt nguồn vốn công."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_57_4', 'en-b2-57', 'Cách dùng “prohibited” (adj.) — bị cấm; không được phép', 'strictly prohibited  ·  prohibited by law  ·  prohibited items', 'Từ này cũng là dạng quá khứ và quá khứ phân từ của prohibit; cấu trúc cấm làm gì dùng prohibit doing.', 'Họ từ (Word Family): prohibit (v.), prohibition (n.), prohibitive (adj.) | Đồng nghĩa: forbidden, banned · Trái nghĩa: permitted, allowed', '[{"hanzi":"Feeding the animals is prohibited at this wildlife park.","pinyin":"","meaning":"Việc cho động vật ăn bị cấm tại công viên động vật hoang dã này."},{"hanzi":"Private vehicles are prohibited in certain urban areas to improve air quality and protect pedestrians.","pinyin":"","meaning":"Các phương tiện cá nhân bị cấm ở một số khu vực đô thị nhằm cải thiện chất lượng không khí và bảo vệ người đi bộ."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_57_1', 'en-b2-57', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
