INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_57_1_2', 'ten_b2_57_1', 'embassy', 'I contacted the embassy after losing my passport abroad.', 'I contacted the embassy after losing my passport abroad.', '/ˈembəsi/', 'Tôi đã liên hệ với đại sứ quán sau khi bị mất hộ chiếu ở nước ngoài.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_57_1_3', 'ten_b2_57_1', 'prohibited', 'Feeding the animals is prohibited at this wildlife park.', 'Feeding the animals is prohibited at this wildlife park.', '/prəˈhɪbɪtɪd/', 'Việc cho động vật ăn bị cấm tại công viên động vật hoang dã này.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_57_1_4', 'ten_b2_57_1', 'socialism', 'Our history teacher explained socialism during today''s lively class discussion.', 'Our history teacher explained socialism during today''s lively class discussion.', '/ˈsoʊʃəlɪzəm/', 'Giáo viên lịch sử của chúng tôi đã giảng giải về chủ nghĩa xã hội trong buổi thảo luận sôi nổi trên lớp ngày hôm nay.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_57_1_5', 'ten_b2_57_1', 'authority', 'Only the manager has authority to approve this refund.', 'Only the manager has authority to approve this refund.', '/əˈθɔːrəti/', 'Chỉ có quản lý mới có thẩm quyền phê duyệt khoản hoàn tiền này.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_57_1_6', 'ten_b2_57_1', 'republic', 'Our teacher explained how the country became a republic.', 'Our teacher explained how the country became a republic.', '/rɪˈpʌblɪk/', 'Giáo viên của chúng tôi giải thích cách đất nước này trở thành một nước cộng hòa.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_57_1_7', 'ten_b2_57_1', 'regulation', 'Safety regulations require everyone here to wear a helmet.', 'Safety regulations require everyone here to wear a helmet.', '/ˌreɡjəˈleɪʃən/', 'Quy định an toàn yêu cầu mọi người ở đây phải đội mũ bảo hiểm.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_57_1_8', 'ten_b2_57_1', 'regulate', 'This small device helps regulate the temperature indoors.', 'This small device helps regulate the temperature indoors.', '/ˈreɡjəleɪt/', 'Thiết bị nhỏ này giúp điều hòa nhiệt độ trong nhà.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_57_1_1', 'en-b2-57', 'ten_b2_57_1', 'listening', 'listening', 'We need the landlord''s approval before painting the kitchen.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi đã liên hệ với đại sứ quán sau khi bị mất hộ chiếu ở nước ngoài.","Hôm nay có quy định hạn chế đậu xe bên ngoài tòa nhà của chúng ta.","Đảng cầm quyền đã hứa cải thiện hệ thống xe buýt địa phương của chúng ta.","Chúng ta cần sự cho phép của chủ nhà trước khi sơn phòng bếp."]'::jsonb, 3, 'We need the landlord''s approval before painting the kitchen. → Chúng ta cần sự cho phép của chủ nhà trước khi sơn phòng bếp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_57_1_2', 'en-b2-57', 'ten_b2_57_1', 'listening', 'listening', 'I contacted the embassy after losing my passport abroad.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một khoản trợ cấp nhỏ đã giúp chúng tôi sửa sang lại khu vui chơi của làng.","Lớp chúng tôi đã đến thăm tòa nhà quốc hội và theo dõi một cuộc tranh luận sôi nổi.","Tôi đã liên hệ với đại sứ quán sau khi bị mất hộ chiếu ở nước ngoài.","Mỗi cử tri đã bỏ một lá phiếu được gấp lại vào chiếc hòm niêm phong."]'::jsonb, 2, 'I contacted the embassy after losing my passport abroad. → Tôi đã liên hệ với đại sứ quán sau khi bị mất hộ chiếu ở nước ngoài.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_57_1_3', 'en-b2-57', 'ten_b2_57_1', 'listening', 'listening', 'Feeding the animals is prohibited at this wildlife park.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Thẩm phán đã bỏ tù tên trộm vì tội ăn cắp những bức tranh quý giá.","Việc cho động vật ăn bị cấm tại công viên động vật hoang dã này.","Lớp chúng tôi đã đến thăm tòa nhà quốc hội và theo dõi một cuộc tranh luận sôi nổi.","Mỗi cử tri đã bỏ một lá phiếu được gấp lại vào chiếc hòm niêm phong."]'::jsonb, 1, 'Feeding the animals is prohibited at this wildlife park. → Việc cho động vật ăn bị cấm tại công viên động vật hoang dã này.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_57_2', 'en-b2-57', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_57_2_1', 'ten_b2_57_2', 'approval', 'New housing projects should receive approval only when developers demonstrate that adequate transport and public services will be provided.', 'New housing projects should receive approval only when developers demonstrate that adequate transport and public services will be provided.', '/əˈpruːvəl/', 'Các dự án nhà ở mới chỉ nên được cấp phép khi chủ đầu tư chứng minh được rằng cơ sở hạ tầng giao thông và dịch vụ công cộng đầy đủ sẽ được cung cấp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_57_2_2', 'ten_b2_57_2', 'embassy', 'An embassy provides assistance to citizens overseas and helps maintain diplomatic relations between the two countries.', 'An embassy provides assistance to citizens overseas and helps maintain diplomatic relations between the two countries.', '/ˈembəsi/', 'Đại sứ quán cung cấp sự hỗ trợ cho công dân ở nước ngoài và giúp duy trì quan hệ ngoại giao giữa hai nước.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_57_2_3', 'ten_b2_57_2', 'prohibited', 'Private vehicles are prohibited in certain urban areas to improve air quality and protect pedestrians.', 'Private vehicles are prohibited in certain urban areas to improve air quality and protect pedestrians.', '/prəˈhɪbɪtɪd/', 'Các phương tiện cá nhân bị cấm ở một số khu vực đô thị nhằm cải thiện chất lượng không khí và bảo vệ người đi bộ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_57_2_4', 'ten_b2_57_2', 'socialism', 'Debates about socialism often focus on public ownership, economic equality, and the appropriate role of government.', 'Debates about socialism often focus on public ownership, economic equality, and the appropriate role of government.', '/ˈsoʊʃəlɪzəm/', 'Các cuộc tranh luận về chủ nghĩa xã hội thường tập trung vào quyền sở hữu công cộng, bình đẳng kinh tế và vai trò thích hợp của nhà nước.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_57_2_5', 'ten_b2_57_2', 'authority', 'Local authorities should consult residents before introducing policies that significantly affect access to public services.', 'Local authorities should consult residents before introducing policies that significantly affect access to public services.', '/əˈθɔːrəti/', 'Chính quyền địa phương nên tham khảo ý kiến cư dân trước khi ban hành các chính sách ảnh hưởng đáng kể đến việc tiếp cận dịch vụ công.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_57_2_6', 'ten_b2_57_2', 'republic', 'In a republic, constitutional rules usually define the powers of the head of state and other public institutions.', 'In a republic, constitutional rules usually define the powers of the head of state and other public institutions.', '/rɪˈpʌblɪk/', 'Trong một nước cộng hòa, các quy định hiến pháp thường xác định quyền hạn của nguyên thủ quốc gia và các cơ quan công quyền khác.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_57_2_1', 'en-b2-57', 'ten_b2_57_2', 'listening', 'listening', 'New housing projects should receive approval only when developers demonstrate that adequate transport and public services will be provided.', NULL, 'Trong câu vừa nghe, từ “approval” mang nghĩa nào sau đây?', '["sự di cư; sự chuyển cư của con người","sự phê duyệt; sự cho phép","móng vuốt","sự áp dụng; sự tiếp nhận"]'::jsonb, 1, '“approval” (/əˈpruːvəl/): sự phê duyệt; sự cho phép. Câu đầy đủ: New housing projects should receive approval only when developers demonstrate that adequate transport and public services will be provided.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
