INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_57_2', 'en-b2-57', NULL, 'comprehensive_test', 'listening', 'I contacted the embassy after losing my passport abroad.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hôm nay có quy định hạn chế đậu xe bên ngoài tòa nhà của chúng ta.","Giáo viên của chúng tôi giải thích cách đất nước này trở thành một nước cộng hòa.","Tôi đã liên hệ với đại sứ quán sau khi bị mất hộ chiếu ở nước ngoài.","Quy định an toàn yêu cầu mọi người ở đây phải đội mũ bảo hiểm."]'::jsonb, 2, 'I contacted the embassy after losing my passport abroad. → Tôi đã liên hệ với đại sứ quán sau khi bị mất hộ chiếu ở nước ngoài.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_57_3', 'en-b2-57', NULL, 'comprehensive_test', 'listening', 'prohibited', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bị cấm; không được phép","nông nghiệp","bản quyền; quyền tác giả","tiếng La-tinh"]'::jsonb, 0, 'prohibited (/prəˈhɪbɪtɪd/) → bị cấm; không được phép', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_57_4', 'en-b2-57', NULL, 'comprehensive_test', 'listening', 'Our history teacher explained socialism during today''s lively class discussion.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bạn đã đưa ra một câu trả lời rất khéo léo cho câu hỏi khó xử đó.","Vị hạ nghị sĩ lắng nghe khi người dân địa phương trình bày các vấn đề giao thông của họ.","Giáo viên của chúng tôi giải thích cách đất nước này trở thành một nước cộng hòa.","Giáo viên lịch sử của chúng tôi đã giảng giải về chủ nghĩa xã hội trong buổi thảo luận sôi nổi trên lớp ngày hôm nay."]'::jsonb, 3, 'Our history teacher explained socialism during today''s lively class discussion. → Giáo viên lịch sử của chúng tôi đã giảng giải về chủ nghĩa xã hội trong buổi thảo luận sôi nổi trên lớp ngày hôm nay.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_57_5', 'en-b2-57', NULL, 'comprehensive_test', 'listening', 'authority', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["quyền lực; thẩm quyền","giòn; giòn rụm","có tính truyền nhiễm; dễ lây lan","rủi ro thấp"]'::jsonb, 0, 'authority (/əˈθɔːrəti/) → quyền lực; thẩm quyền; chính quyền; cơ quan có thẩm quyền; chuyên gia; người có uy tín chuyên môn', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_57_6', 'en-b2-57', NULL, 'comprehensive_test', 'listening', 'Our teacher explained how the country became a republic.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Quy định an toàn yêu cầu mọi người ở đây phải đội mũ bảo hiểm.","Giáo viên của chúng tôi giải thích cách đất nước này trở thành một nước cộng hòa.","Hãy cùng nhau dọn dẹp nhà bếp bừa bộn trước khi khách đến nhé.","Tôi đã liên hệ với đại sứ quán sau khi bị mất hộ chiếu ở nước ngoài."]'::jsonb, 1, 'Our teacher explained how the country became a republic. → Giáo viên của chúng tôi giải thích cách đất nước này trở thành một nước cộng hòa.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_57_7', 'en-b2-57', NULL, 'comprehensive_test', 'listening', 'regulation', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cốt truyện; tình tiết","không tính lãi; miễn lãi","băng rôn; biểu ngữ; cờ","quy định; điều lệ"]'::jsonb, 3, 'regulation (/ˌreɡjəˈleɪʃən/) → quy định; điều lệ; sự quản lý; sự điều tiết', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_57_8', 'en-b2-57', NULL, 'comprehensive_test', 'listening', 'This small device helps regulate the temperature indoors.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Thiết bị nhỏ này giúp điều hòa nhiệt độ trong nhà.","Quy định an toàn yêu cầu mọi người ở đây phải đội mũ bảo hiểm.","Đảng cầm quyền đã hứa cải thiện hệ thống xe buýt địa phương của chúng ta.","Giáo viên của chúng tôi giải thích cách đất nước này trở thành một nước cộng hòa."]'::jsonb, 0, 'This small device helps regulate the temperature indoors. → Thiết bị nhỏ này giúp điều hòa nhiệt độ trong nhà.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_57_9', 'en-b2-57', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “the power or right to make decisions and enforce rules”?', '["tackle","diplomatic","republic","authority"]'::jsonb, 3, 'authority (/əˈθɔːrəti/) → quyền lực; thẩm quyền', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_57_10', 'en-b2-57', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A country whose head of state is not a monarch.”?', '["voter","ruling","diplomatic","republic"]'::jsonb, 3, 'republic (/rɪˈpʌblɪk/) → nước cộng hòa; chế độ cộng hòa', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_57_11', 'en-b2-57', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “An official rule controlling how something must be done.”?', '["imprison","ruling","regulate","regulation"]'::jsonb, 3, 'regulation (/ˌreɡjəˈleɪʃən/) → quy định; điều lệ', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_57_12', 'en-b2-57', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “control an activity through rules or laws”?', '["parliament","ambassador","regulate","ruling"]'::jsonb, 2, 'regulate (/ˈreɡjəleɪt/) → kiểm soát, quản lý thông qua quy tắc hoặc luật lệ', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_57_13', 'en-b2-57', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “money given by an organisation for a particular purpose”?', '["embassy","regulation","grant","restriction"]'::jsonb, 2, 'grant (/ɡrænt/) → khoản trợ cấp, tiền cấp phát từ một tổ chức cho mục đích cụ thể', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
