INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_57_18', 'en-b2-57', NULL, 'comprehensive_test', 'reading', NULL, 'New housing projects should receive approval only when developers demonstrate that adequate transport and public services will be provided.', 'Dựa vào câu trên, từ “approval” có nghĩa phù hợp nhất là gì?', '["sự tắc nghẽn; vật cản; chỗ nghẽn","chuyên gia; bác sĩ chuyên khoa","điều tra; tìm hiểu","sự phê duyệt; sự cho phép"]'::jsonb, 3, 'approval: sự phê duyệt; sự cho phép; sự tán thành; sự công nhận. Dịch cả câu: Các dự án nhà ở mới chỉ nên được cấp phép khi chủ đầu tư chứng minh được rằng cơ sở hạ tầng giao thông và dịch vụ công cộng đầy đủ sẽ được cung cấp.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_57_19', 'en-b2-57', NULL, 'comprehensive_test', 'reading', NULL, 'An embassy provides assistance to citizens overseas and helps maintain diplomatic relations between the two countries.', 'Dựa vào câu trên, từ “embassy” có nghĩa phù hợp nhất là gì?', '["trường nội trú","vô cùng ngốc nghếch; phi lý; nguy hiểm","sự kỳ vọng; niềm tin rằng điều gì đó sẽ xảy ra","đại sứ quán"]'::jsonb, 3, 'embassy: đại sứ quán. Dịch cả câu: Đại sứ quán cung cấp sự hỗ trợ cho công dân ở nước ngoài và giúp duy trì quan hệ ngoại giao giữa hai nước.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_57_20', 'en-b2-57', NULL, 'comprehensive_test', 'reading', NULL, 'Private vehicles are prohibited in certain urban areas to improve air quality and protect pedestrians.', 'Dựa vào câu trên, từ “prohibited” có nghĩa phù hợp nhất là gì?', '["làm khiếp sợ; làm hoảng sợ","rối loạn; chứng bệnh; sự suy giảm chức năng","bị cấm; không được phép","yên ngựa; yên xe đạp"]'::jsonb, 2, 'prohibited: bị cấm; không được phép. Dịch cả câu: Các phương tiện cá nhân bị cấm ở một số khu vực đô thị nhằm cải thiện chất lượng không khí và bảo vệ người đi bộ.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_57_21', 'en-b2-57', NULL, 'comprehensive_test', 'reading', NULL, 'Debates about socialism often focus on public ownership, economic equality, and the appropriate role of government.', 'Dựa vào câu trên, từ “socialism” có nghĩa phù hợp nhất là gì?', '["chủ nghĩa xã hội","sự việc; sự cố","giao lộ; ngã tư","tôm hùm"]'::jsonb, 0, 'socialism: chủ nghĩa xã hội. Dịch cả câu: Các cuộc tranh luận về chủ nghĩa xã hội thường tập trung vào quyền sở hữu công cộng, bình đẳng kinh tế và vai trò thích hợp của nhà nước.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
