INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_57_24', 'en-b2-57', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nghị sĩ quốc hội; hạ nghị sĩ Mỹ”', '["halve","warehouse","rental","congressman"]'::jsonb, 3, 'nghị sĩ quốc hội; hạ nghị sĩ Mỹ → congressman (/ˈkɑːŋɡrəsmən/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-58', 'en', 'Bài 58: Chính phủ & Pháp luật (3) - CEFR B2', 'CEFR B2', 'B2 · Chính phủ & Pháp luật', '19 từ vựng Tiếng Anh CEFR B2 chủ đề chính phủ & pháp luật kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4058, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_combat', 'en-b2-58', 'combat', '/ˈkɑːmbæt/', 'B2', 'chống lại; chiến đấu; ngăn chặn; trận chiến; cuộc giao tranh', 'v.', 'combatant (n.), combative (adj.)', 'Đồng nghĩa: fight, counter', 'Khi làm động từ, đi thẳng tới vấn đề hoặc mối nguy hại mà không cần dùng giới từ against.', 'We opened the windows to combat the afternoon heat.', NULL, 'Chúng tôi mở cửa sổ để xua bớt cái nóng buổi chiều.', '{"wordId":"combat","ukIpa":"/ˈkɒmbæt/","usIpa":"/ˈkɑːmbæt/","cefr":"B2","topic":"government","senses":[{"pos":"v.","en":"to fight against something harmful","vi":"chống lại; chiến đấu; ngăn chặn"},{"pos":"n.","en":"fighting between opposing forces or individuals","vi":"trận chiến; cuộc giao tranh; chiến đấu"}],"examples":[{"en":"We opened the windows to combat the afternoon heat.","vi":"Chúng tôi mở cửa sổ để xua bớt cái nóng buổi chiều.","audioKind":"ex"},{"en":"Governments can combat air pollution by improving public transport and enforcing stricter limits on industrial emissions.","vi":"Chính phủ có thể chống lại tình trạng ô nhiễm không khí bằng cách cải thiện giao thông công cộng và thực thi các giới hạn ngặt nghèo hơn đối với khí thải công nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"combat climate change","vi":"ứng phó với biến đổi khí hậu"},{"en":"combat poverty","vi":"chống đói nghèo"},{"en":"combat disease","vi":"đẩy lùi bệnh tật"},{"en":"armed combat","vi":"giao tranh có vũ trang"}],"wordFamily":["combatant (n.)","combative (adj.)"],"synonyms":["fight","counter"],"antonyms":[],"tipVi":"Khi làm động từ, đi thẳng tới vấn đề hoặc mối nguy hại mà không cần dùng giới từ against.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reform', 'en-b2-58', 'reform', '/rɪˈfɔːrm/', 'B2', 'cải cách; cải tiến (hệ thống); sự cải cách; biện pháp cải tiến; cải tạo; sửa đổi hành vi', 'v.', 'reformer (n.), reformist (adj.)', NULL, 'reform tập trung vào việc cải thiện hệ thống hiện tại chứ không nhất thiết lật đổ hoàn toàn.', 'Parents want the school to reform its admissions process.', NULL, 'Các bậc phụ huynh muốn nhà trường cải cách quy trình tuyển sinh.', '{"wordId":"reform","ukIpa":"/rɪˈfɔːm/","usIpa":"/rɪˈfɔːrm/","cefr":"B2","topic":"government","senses":[{"pos":"v.","en":"to improve a system by changing how it works","vi":"cải cách; cải tiến (hệ thống)"},{"pos":"n.","en":"a change intended to improve a system or institution","vi":"sự cải cách; biện pháp cải tiến"},{"pos":"v.","en":"to improve your behaviour or help someone improve theirs","vi":"cải tạo; sửa đổi hành vi"}],"examples":[{"en":"Parents want the school to reform its admissions process.","vi":"Các bậc phụ huynh muốn nhà trường cải cách quy trình tuyển sinh.","audioKind":"ex"},{"en":"Healthcare reform should focus on reducing waiting times while ensuring equal access to essential services.","vi":"Cải cách y tế nên tập trung vào việc giảm thời gian chờ đợi đồng thời bảo đảm mọi người đều có cơ hội tiếp cận công bằng với các dịch vụ thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"reform the education system","vi":"cải cách hệ thống giáo dục"},{"en":"economic reform","vi":"cải cách kinh tế"},{"en":"introduce reforms","vi":"tiến hành cải cách"},{"en":"far-reaching reforms","vi":"những cải cách có tầm ảnh hưởng sâu rộng"}],"wordFamily":["reformer (n.)","reformist (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"reform tập trung vào việc cải thiện hệ thống hiện tại chứ không nhất thiết lật đổ hoàn toàn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_declare', 'en-b2-58', 'declare', '/dɪˈkler/', 'B2', 'tuyên bố; công bố; khai báo', 'v.', 'declaration (n.), declared (adj.)', 'Đồng nghĩa: announce, proclaim', 'Declare nhấn mạnh việc thông báo công khai hoặc chính thức; thủ tục khai báo hải quan cũng dùng từ này.', 'The judges declared her the winner of the competition.', NULL, 'Các giám khảo đã tuyên bố cô ấy là người chiến thắng trong cuộc thi.', '{"wordId":"declare","ukIpa":"/dɪˈkleə/","usIpa":"/dɪˈkler/","cefr":"B2","topic":"government","senses":[{"pos":"v.","en":"to announce something publicly or officially","vi":"tuyên bố; công bố"},{"pos":"v.","en":"to officially report goods, income or other required information","vi":"khai báo"}],"examples":[{"en":"The judges declared her the winner of the competition.","vi":"Các giám khảo đã tuyên bố cô ấy là người chiến thắng trong cuộc thi.","audioKind":"ex"},{"en":"Local authorities may declare a public holiday to encourage participation in an important community celebration.","vi":"Chính quyền địa phương có thể tuyên bố một ngày nghỉ lễ để khuyến khích sự tham gia vào một lễ kỷ niệm quan trọng của cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"declare a winner","vi":"tuyên bố người chiến thắng"},{"en":"declare an emergency","vi":"tuyên bố tình trạng khẩn cấp"},{"en":"declare goods","vi":"khai báo hàng hóa"},{"en":"declare income","vi":"khai báo thu nhập"}],"wordFamily":["declaration (n.)","declared (adj.)"],"synonyms":["announce","proclaim"],"antonyms":[],"tipVi":"Declare nhấn mạnh việc thông báo công khai hoặc chính thức; thủ tục khai báo hải quan cũng dùng từ này.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_declaration', 'en-b2-58', 'declaration', '/ˌdekləˈreɪʃən/', 'B2', 'tuyên ngôn; lời tuyên bố; sự công bố; bản khai; tờ khai', 'n.', 'declare (v.), declarative (adj.)', 'Đồng nghĩa: statement, announcement', 'Declare là động từ; thủ tục khai báo hải quan dùng customs declaration.', 'Her declaration that she would quit surprised the whole family.', NULL, 'Tuyên bố từ chức của cô ấy khiến cả gia đình ngạc nhiên.', '{"wordId":"declaration","ukIpa":"/ˌdekləˈreɪʃən/","usIpa":"/ˌdekləˈreɪʃən/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"An official or public statement expressing a decision, belief, or intention.","vi":"tuyên ngôn; lời tuyên bố; sự công bố"},{"pos":"n.","en":"An official statement of goods, income, or other required information.","vi":"bản khai; tờ khai"}],"examples":[{"en":"Her declaration that she would quit surprised the whole family.","vi":"Tuyên bố từ chức của cô ấy khiến cả gia đình ngạc nhiên.","audioKind":"ex"},{"en":"The government''s declaration of a climate emergency should be followed by clear policies and measurable environmental targets.","vi":"Việc chính phủ tuyên bố tình trạng khẩn cấp về khí hậu cần phải đi kèm với các chính sách rõ ràng và mục tiêu môi trường có thể đo lường được.","audioKind":"ex2"}],"collocations":[{"en":"joint declaration","vi":"tuyên ngôn chung"},{"en":"declaration of independence","vi":"tuyên ngôn độc lập"},{"en":"customs declaration","vi":"tờ khai hải quan"},{"en":"make a declaration","vi":"đưa ra tuyên bố"}],"wordFamily":["declare (v.)","declarative (adj.)"],"synonyms":["statement","announcement"],"antonyms":[],"tipVi":"Declare là động từ; thủ tục khai báo hải quan dùng customs declaration.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_governor', 'en-b2-58', 'governor', '/ˈɡʌvərnər/', 'B2', 'thống đốc; thủ hiến; thành viên ban quản trị; ủy viên hội đồng quản trị', 'n.', 'govern (v.), government (n.), governance (n.)', NULL, 'Cụ thể chức vụ dựa theo danh từ đi kèm: school governor chỉ thành viên ban quản trị trường học.', 'The governor visited our town after the river flooded.', NULL, 'Thống đốc đã đến thăm thị trấn của chúng tôi sau trận lụt.', '{"wordId":"governor","ukIpa":"/ˈɡʌvənə/","usIpa":"/ˈɡʌvərnər/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"the official leader of a state or territory","vi":"thống đốc; thủ hiến"},{"pos":"n.","en":"someone who manages an institution or helps direct its policies","vi":"thành viên ban quản trị; ủy viên hội đồng quản trị"}],"examples":[{"en":"The governor visited our town after the river flooded.","vi":"Thống đốc đã đến thăm thị trấn của chúng tôi sau trận lụt.","audioKind":"ex"},{"en":"The governor proposed additional funding for public schools to reduce educational inequalities across the state.","vi":"Thống đốc đã đề xuất cấp thêm kinh phí cho các trường công lập nhằm thu hẹp khoảng cách giáo dục trên toàn tiểu bang.","audioKind":"ex2"}],"collocations":[{"en":"state governor","vi":"thống đốc tiểu bang"},{"en":"school governor","vi":"thành viên hội đồng trường"},{"en":"prison governor","vi":"giám thị trại giam"},{"en":"central bank governor","vi":"thống đốc ngân hàng trung ương"}],"wordFamily":["govern (v.)","government (n.)","governance (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụ thể chức vụ dựa theo danh từ đi kèm: school governor chỉ thành viên ban quản trị trường học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_democracy', 'en-b2-58', 'democracy', '/dɪˈmɑːkrəsi/', 'B2', 'chế độ dân chủ; nền dân chủ; quốc gia dân chủ', 'n.', 'democratic (adj.), democratically (adv.), democratisation (n.)', 'Trái nghĩa: dictatorship', 'Chỉ chế độ thường không đếm được; chỉ quốc gia theo chế độ dân chủ thì đếm được.', 'Our teacher explained democracy through a classroom vote.', NULL, 'Giáo viên của chúng tôi giải thích về nền dân chủ thông qua một cuộc bỏ phiếu trong lớp.', '{"wordId":"democracy","ukIpa":"/dɪˈmɒkrəsi/","usIpa":"/dɪˈmɑːkrəsi/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"A system of government in which people choose their leaders.","vi":"chế độ dân chủ; nền dân chủ"},{"pos":"n.","en":"A country governed through representatives elected by its people.","vi":"quốc gia dân chủ"}],"examples":[{"en":"Our teacher explained democracy through a classroom vote.","vi":"Giáo viên của chúng tôi giải thích về nền dân chủ thông qua một cuộc bỏ phiếu trong lớp.","audioKind":"ex"},{"en":"A healthy democracy depends on informed citizens who can access reliable information and participate freely in public debate.","vi":"Một nền dân chủ vững mạnh phụ thuộc vào những công dân có hiểu biết, những người có thể tiếp cận thông tin đáng tin cậy và tham gia tự do vào các cuộc thảo luận công khai.","audioKind":"ex2"}],"collocations":[{"en":"parliamentary democracy","vi":"dân chủ nghị viện"},{"en":"representative democracy","vi":"dân chủ đại nghị"},{"en":"strengthen democracy","vi":"củng cố nền dân chủ"}],"wordFamily":["democratic (adj.)","democratically (adv.)","democratisation (n.)"],"synonyms":[],"antonyms":["dictatorship"],"tipVi":"Chỉ chế độ thường không đếm được; chỉ quốc gia theo chế độ dân chủ thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_alliance', 'en-b2-58', 'alliance', '/əˈlaɪəns/', 'B2', 'liên minh; khối liên minh', 'n.', 'ally (n.), ally (v.), allied (adj.)', 'Đồng nghĩa: coalition, partnership', 'Thường đi với cụm form an alliance with, nghĩa là "kết minh với...".', 'The two clubs formed an alliance to save the pool.', NULL, 'Hai câu lạc bộ đã lập nên một liên minh để bảo vệ hồ bơi.', '{"wordId":"alliance","ukIpa":"/əˈlaɪəns/","usIpa":"/əˈlaɪəns/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"A partnership between groups or countries pursuing shared goals.","vi":"liên minh; khối liên minh"}],"examples":[{"en":"The two clubs formed an alliance to save the pool.","vi":"Hai câu lạc bộ đã lập nên một liên minh để bảo vệ hồ bơi.","audioKind":"ex"},{"en":"An international alliance can help countries coordinate their responses to environmental threats that cross national borders.","vi":"Một liên minh quốc tế có thể giúp các quốc gia phối hợp ứng phó với các mối đe dọa môi trường vượt qua biên giới quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"form an alliance","vi":"lập liên minh"},{"en":"strategic alliance","vi":"liên minh chiến lược"},{"en":"military alliance","vi":"liên minh quân sự"}],"wordFamily":["ally (n.)","ally (v.)","allied (adj.)"],"synonyms":["coalition","partnership"],"antonyms":[],"tipVi":"Thường đi với cụm form an alliance with, nghĩa là \"kết minh với...\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_commander', 'en-b2-58', 'commander', '/kəˈmændər/', 'B2', 'chỉ huy; người chỉ huy', 'n.', 'command (v.), command (n.), commanding (adj.)', NULL, 'Từ này dùng chung để chỉ người chỉ huy; khi làm cấp bậc quân sự cụ thể, cấp bậc sẽ tùy thuộc vào quy định của từng quốc gia.', 'The commander asked the crew to check their equipment.', NULL, 'Viên chỉ huy yêu cầu các thành viên trong phi hành đoàn kiểm tra lại trang thiết bị của họ.', '{"wordId":"commander","ukIpa":"/kəˈmɑːndə/","usIpa":"/kəˈmændər/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"an officer responsible for directing a military unit or operation","vi":"chỉ huy; người chỉ huy"}],"examples":[{"en":"The commander asked the crew to check their equipment.","vi":"Viên chỉ huy yêu cầu các thành viên trong phi hành đoàn kiểm tra lại trang thiết bị của họ.","audioKind":"ex"},{"en":"During disaster relief operations, the military commander coordinated transport to deliver essential supplies to isolated communities.","vi":"Trong các chiến dịch cứu trợ thảm họa, người chỉ huy quân sự đã điều phối hoạt động vận tải để cung cấp các nhu yếu phẩm cho những cộng đồng bị cô lập.","audioKind":"ex2"}],"collocations":[{"en":"military commander","vi":"chỉ huy quân sự"},{"en":"naval commander","vi":"chỉ huy hải quân"},{"en":"commander-in-chief","vi":"tổng tư lệnh"}],"wordFamily":["command (v.)","command (n.)","commanding (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ này dùng chung để chỉ người chỉ huy; khi làm cấp bậc quân sự cụ thể, cấp bậc sẽ tùy thuộc vào quy định của từng quốc gia.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_minister', 'en-b2-58', 'minister', '/ˈmɪnɪstər/', 'B2', 'bộ trưởng; thủ trưởng cơ quan cấp bộ; mục sư (trong một số nhà thờ Cơ Đốc giáo); chăm sóc; tận tụy giúp đỡ, săn sóc', 'n.', 'ministry (n.), ministerial (adj.)', NULL, 'Nghĩa động từ mang tính trang trọng, thường dùng minister to để chỉ việc chăm sóc.', 'The minister visited our school to meet the teachers.', NULL, 'Bộ trưởng đã đến thăm trường chúng tôi để gặp gỡ các giáo viên.', '{"wordId":"minister","ukIpa":"/ˈmɪnɪstə/","usIpa":"/ˈmɪnɪstər/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"A senior government official responsible for a particular area.","vi":"bộ trưởng; thủ trưởng cơ quan cấp bộ"},{"pos":"n.","en":"A religious leader in certain Christian churches.","vi":"mục sư (trong một số nhà thờ Cơ Đốc giáo)"},{"pos":"v.","en":"To care for someone or attend to their needs.","vi":"chăm sóc; tận tụy giúp đỡ, săn sóc"}],"examples":[{"en":"The minister visited our school to meet the teachers.","vi":"Bộ trưởng đã đến thăm trường chúng tôi để gặp gỡ các giáo viên.","audioKind":"ex"},{"en":"Trained volunteers minister to the needs of older residents who lack access to regular medical care.","vi":"Các tình nguyện viên được đào tạo sẽ chăm sóc các nhu cầu của cư dân cao tuổi thiếu khả năng tiếp cận dịch vụ y tế thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"education minister","vi":"bộ trưởng giáo dục"},{"en":"prime minister","vi":"thủ tướng"},{"en":"a church minister","vi":"mục sư nhà thờ"},{"en":"minister to someone''s needs","vi":"chăm sóc nhu cầu của ai đó"}],"wordFamily":["ministry (n.)","ministerial (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa động từ mang tính trang trọng, thường dùng minister to để chỉ việc chăm sóc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prohibit', 'en-b2-58', 'prohibit', '/prəˈhɪbɪt/', 'B2', 'cấm; ngăn cấm theo quy định hoặc luật pháp; ngăn cản; làm cho không thể thực hiện được', 'v.', 'prohibition (n.), prohibitive (adj.), prohibitively (adv.)', 'Đồng nghĩa: ban, forbid · Trái nghĩa: allow, permit', 'Sử dụng cấu trúc prohibit doing hoặc prohibit sb from doing.', 'The pool rules prohibit running on the wet floor.', NULL, 'Quy định của hồ bơi cấm chạy nhảy trên sàn ướt.', '{"wordId":"prohibit","ukIpa":"/prəˈhɪbɪt/","usIpa":"/prəˈhɪbɪt/","cefr":"B2","topic":"government","senses":[{"pos":"v.","en":"To officially forbid an action through rules or laws.","vi":"cấm; ngăn cấm theo quy định hoặc luật pháp"},{"pos":"v.","en":"To prevent something by making it impossible or impractical.","vi":"ngăn cản; làm cho không thể thực hiện được"}],"examples":[{"en":"The pool rules prohibit running on the wet floor.","vi":"Quy định của hồ bơi cấm chạy nhảy trên sàn ướt.","audioKind":"ex"},{"en":"Governments should prohibit the dumping of untreated industrial waste into rivers to protect public health.","vi":"Chính phủ nên cấm xả thải chất thải công nghiệp chưa qua xử lý ra sông ngòi để bảo vệ sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"strictly prohibit","vi":"nghiêm cấm"},{"en":"prohibit someone from doing something","vi":"cấm ai đó làm gì"},{"en":"prohibit the use of","vi":"cấm sử dụng"}],"wordFamily":["prohibition (n.)","prohibitive (adj.)","prohibitively (adv.)"],"synonyms":["ban","forbid"],"antonyms":["allow","permit"],"tipVi":"Sử dụng cấu trúc prohibit doing hoặc prohibit sb from doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_congress', 'en-b2-58', 'congress', '/ˈkɑːŋɡrəs/', 'B2', 'quốc hội; nghị viện; đại hội; hội nghị chuyên đề', 'n.', 'congressional (adj.)', NULL, 'Khi chỉ quốc hội của các nước như Mỹ, thường viết hoa chữ Congress.', 'The congress debated the new law late into the night.', NULL, 'Quốc hội đã tranh luận về đạo luật mới đến tận đêm khuya.', '{"wordId":"congress","ukIpa":"/ˈkɒŋɡres/","usIpa":"/ˈkɑːŋɡrəs/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"A national body of representatives that makes laws.","vi":"quốc hội; nghị viện"},{"pos":"n.","en":"A large formal meeting of representatives or specialists.","vi":"đại hội; hội nghị chuyên đề"}],"examples":[{"en":"The congress debated the new law late into the night.","vi":"Quốc hội đã tranh luận về đạo luật mới đến tận đêm khuya.","audioKind":"ex"},{"en":"Delegates at the international congress discussed practical ways to improve access to healthcare in rural communities.","vi":"Các đại biểu tại đại hội quốc tế đã thảo luận về các biện pháp thiết thực nhằm cải thiện khả năng tiếp cận chăm sóc sức khỏe ở các cộng đồng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"a national congress","vi":"đại hội toàn quốc"},{"en":"an international congress","vi":"hội nghị quốc tế"},{"en":"a member of Congress","vi":"một nghị sĩ quốc hội"}],"wordFamily":["congressional (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ quốc hội của các nước như Mỹ, thường viết hoa chữ Congress.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_jury', 'en-b2-58', 'jury', '/ˈdʒʊri/', 'B2', 'bồi thẩm đoàn; ban giám khảo; hội đồng giám khảo', 'n.', 'juror (n.)', NULL, 'jury chỉ toàn bộ bồi thẩm đoàn; từng thành viên riêng lẻ được gọi là juror.', 'The jury listened carefully as the witness described the accident.', NULL, 'Bồi thẩm đoàn chăm chú lắng nghe khi nhân chứng mô tả lại vụ tai nạn.', '{"wordId":"jury","ukIpa":"/ˈdʒʊəri/","usIpa":"/ˈdʒʊri/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"a group that decides facts in a court case","vi":"bồi thẩm đoàn"},{"pos":"n.","en":"a group that judges entries in a competition","vi":"ban giám khảo; hội đồng giám khảo"}],"examples":[{"en":"The jury listened carefully as the witness described the accident.","vi":"Bồi thẩm đoàn chăm chú lắng nghe khi nhân chứng mô tả lại vụ tai nạn.","audioKind":"ex"},{"en":"Serving on a jury allows ordinary citizens to participate directly in the administration of justice.","vi":"Tham gia bồi thẩm đoàn giúp những công dân bình thường trực tiếp đóng góp vào công tác thực thi công lý.","audioKind":"ex2"}],"collocations":[{"en":"serve on a jury","vi":"làm bồi thẩm viên"},{"en":"jury verdict","vi":"phán quyết của bồi thẩm đoàn"},{"en":"jury member","vi":"thành viên bồi thẩm đoàn"}],"wordFamily":["juror (n.)"],"synonyms":[],"antonyms":[],"tipVi":"jury chỉ toàn bộ bồi thẩm đoàn; từng thành viên riêng lẻ được gọi là juror.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_socialist', 'en-b2-58', 'socialist', '/ˈsoʊʃəlɪst/', 'B2', 'thuộc về chủ nghĩa xã hội; người theo chủ nghĩa xã hội', 'adj.', 'socialism (n.)', NULL, 'socialist chỉ thuộc về chủ nghĩa xã hội; social chỉ chỉ về xã hội hoặc tính xã giao.', 'Our reading group discussed socialist ideas over tea.', NULL, 'Nhóm đọc sách của chúng tôi đã thảo luận về các tư tưởng xã hội chủ nghĩa bên tách trà.', '{"wordId":"socialist","ukIpa":"/ˈsəʊʃəlɪst/","usIpa":"/ˈsoʊʃəlɪst/","cefr":"B2","topic":"government","senses":[{"pos":"adj.","en":"relating to collective ownership and more equal distribution of wealth","vi":"thuộc về chủ nghĩa xã hội"},{"pos":"n.","en":"someone who supports socialism","vi":"người theo chủ nghĩa xã hội"}],"examples":[{"en":"Our reading group discussed socialist ideas over tea.","vi":"Nhóm đọc sách của chúng tôi đã thảo luận về các tư tưởng xã hội chủ nghĩa bên tách trà.","audioKind":"ex"},{"en":"Socialist policies often seek to reduce economic inequality through public ownership and the redistribution of wealth.","vi":"Các chính sách xã hội chủ nghĩa thường tìmcách giảm bớt bất bình đẳng kinh tế thông qua quyền sở hữu công cộng và sự phân phối lại tài sản.","audioKind":"ex2"}],"collocations":[{"en":"socialist policies","vi":"chính sách xã hội chủ nghĩa"},{"en":"socialist movement","vi":"Phong trào xã hội chủ nghĩa"},{"en":"socialist economy","vi":"nền kinh tế xã hội chủ nghĩa"}],"wordFamily":["socialism (n.)"],"synonyms":[],"antonyms":[],"tipVi":"socialist chỉ thuộc về chủ nghĩa xã hội; social chỉ chỉ về xã hội hoặc tính xã giao.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_diplomat', 'en-b2-58', 'diplomat', '/ˈdɪpləmæt/', 'B2', 'nhà ngoại giao; người khéo léo trong giao tiếp; người khôn khéo ứng xử', 'n.', 'diplomacy (n.), diplomatic (adj.), diplomatically (adv.)', NULL, 'Tính từ diplomatic có thể mang nghĩa thuộc về ngoại giao hoặc khéo léo, tế nhị trong cách nói năng.', 'The diplomat welcomed visitors at the embassy this morning.', NULL, 'Nhà ngoại giao đã chào đón các vị khách tại đại sứ quán vào sáng nay.', '{"wordId":"diplomat","ukIpa":"/ˈdɪpləmæt/","usIpa":"/ˈdɪpləmæt/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"An official who represents their country in relations with other countries.","vi":"nhà ngoại giao"},{"pos":"n.","en":"Someone skilled at handling people and difficult situations tactfully.","vi":"người khéo léo trong giao tiếp; người khôn khéo ứng xử"}],"examples":[{"en":"The diplomat welcomed visitors at the embassy this morning.","vi":"Nhà ngoại giao đã chào đón các vị khách tại đại sứ quán vào sáng nay.","audioKind":"ex"},{"en":"Experienced diplomats can help countries resolve disagreements through negotiation rather than allowing tensions to escalate.","vi":"Những nhà ngoại giao giàu kinh nghiệm có thể giúp các quốc gia giải quyết bất đồng thông qua đàm phán thay vì để căng thẳng leo thang.","audioKind":"ex2"}],"collocations":[{"en":"a senior diplomat","vi":"nhà ngoại giao cấp cao"},{"en":"a career diplomat","vi":"nhà ngoại giao kỳ cựu"},{"en":"a foreign diplomat","vi":"nhà ngoại giao nước ngoài"}],"wordFamily":["diplomacy (n.)","diplomatic (adj.)","diplomatically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Tính từ diplomatic có thể mang nghĩa thuộc về ngoại giao hoặc khéo léo, tế nhị trong cách nói năng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_impose', 'en-b2-58', 'impose', '/ɪmˈpoʊz/', 'B2', 'áp đặt; ban hành (luật, thuế, hình phạt); ép buộc; làm phiền; lợi dụng thời gian của ai', 'v.', 'imposition (n.)', NULL, 'Thường dùng cấu trúc impose A on B, nghĩa là áp đặt A lên B.', 'The library imposed a small fine for my overdue books.', NULL, 'Thư viện đã áp dụng một khoản tiền phạt nhỏ đối với sách quá hạn của tôi.', '{"wordId":"impose","ukIpa":"/ɪmˈpəʊz/","usIpa":"/ɪmˈpoʊz/","cefr":"B2","topic":"government","senses":[{"pos":"v.","en":"Officially introduce a rule, tax, punishment, or restriction","vi":"áp đặt; ban hành (luật, thuế, hình phạt)"},{"pos":"v.","en":"Force someone to accept something they do not want","vi":"áp đặt; ép buộc"},{"pos":"v.","en":"Expect help or attention that causes someone inconvenience","vi":"làm phiền; lợi dụng thời gian của ai"}],"examples":[{"en":"The library imposed a small fine for my overdue books.","vi":"Thư viện đã áp dụng một khoản tiền phạt nhỏ đối với sách quá hạn của tôi.","audioKind":"ex"},{"en":"Governments may impose higher taxes on sugary drinks to encourage healthier choices and reduce public healthcare costs.","vi":"Chính phủ có thể đánh thuế cao hơn đối với đồ uống có đường nhằm khuyến khích lựa chọn lành mạnh hơn và giảm chi phí y tế công cộng.","audioKind":"ex2"}],"collocations":[{"en":"impose restrictions on","vi":"áp đặt hạn chế lên"},{"en":"impose a tax on","vi":"đánh thuế vào"},{"en":"impose one''s views on","vi":"áp đặt quan điểm của ai đó lên"},{"en":"impose on someone''s time","vi":"làm phiền thời gian của ai"}],"wordFamily":["imposition (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng cấu trúc impose A on B, nghĩa là áp đặt A lên B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_military', 'en-b2-58', 'military', '/ˈmɪləteri/', 'B2', 'thuộc về quân đội; quân sự; quân đội; lực lượng vũ trang', 'adj.', 'militarily (adv.), militarism (n.), militarisation (n.)', 'Trái nghĩa: civilian', 'Khi dùng làm danh từ chỉ tổng thể lực lượng vũ trang, thường dùng the military.', 'We watched military helicopters carry supplies to the island.', NULL, 'Chúng tôi nhìn các trực thăng quân sự chở nhu yếu phẩm ra đảo.', '{"wordId":"military","ukIpa":"/ˈmɪlɪtəri/","usIpa":"/ˈmɪləteri/","cefr":"B2","topic":"government","senses":[{"pos":"adj.","en":"relating to armed forces or their activities","vi":"thuộc về quân đội; quân sự"},{"pos":"n.","en":"a country''s armed forces, considered as a group","vi":"quân đội; lực lượng vũ trang"}],"examples":[{"en":"We watched military helicopters carry supplies to the island.","vi":"Chúng tôi nhìn các trực thăng quân sự chở nhu yếu phẩm ra đảo.","audioKind":"ex"},{"en":"Governments must balance military spending with investment in essential public services such as healthcare and education.","vi":"Chính phủ phải cân bằng giữa chi tiêu quân sự và đầu tư vào các dịch vụ công thiết yếu như y tế và giáo dục.","audioKind":"ex2"}],"collocations":[{"en":"military service","vi":"nghĩa vụ quân sự"},{"en":"military spending","vi":"chi tiêu quân sự"},{"en":"military personnel","vi":"quân nhân"},{"en":"the military","vi":"quân đội"}],"wordFamily":["militarily (adv.)","militarism (n.)","militarisation (n.)"],"synonyms":[],"antonyms":["civilian"],"tipVi":"Khi dùng làm danh từ chỉ tổng thể lực lượng vũ trang, thường dùng the military.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_restrict', 'en-b2-58', 'restrict', '/rɪˈstrɪkt/', 'B2', 'hạn chế; giới hạn', 'v.', 'restriction (n.), restricted (adj.), restrictive (adj.)', 'Đồng nghĩa: limit, constrain', 'restrict A to B có nghĩa là "hạn chế A trong phạm vi B".', 'These tight shoes restrict my movement when I dance.', NULL, 'Đôi giày chật này khiến tôi khó cử động khi nhảy.', '{"wordId":"restrict","ukIpa":"/rɪˈstrɪkt/","usIpa":"/rɪˈstrɪkt/","cefr":"B2","topic":"government","senses":[{"pos":"v.","en":"to limit what someone can do or how much is allowed","vi":"hạn chế; giới hạn"}],"examples":[{"en":"These tight shoes restrict my movement when I dance.","vi":"Đôi giày chật này khiến tôi khó cử động khi nhảy.","audioKind":"ex"},{"en":"Local authorities may restrict private vehicle access to city centres in order to reduce air pollution.","vi":"Chính quyền địa phương có thể hạn chế xe cá nhân đi vào trung tâm thành phố nhằm giảm ô nhiễm không khí.","audioKind":"ex2"}],"collocations":[{"en":"restrict access","vi":"hạn chế quyền truy cập"},{"en":"restrict movement","vi":"hạn chế cử động"},{"en":"restrict something to","vi":"hạn chế cái gì ở mức"}],"wordFamily":["restriction (n.)","restricted (adj.)","restrictive (adj.)"],"synonyms":["limit","constrain"],"antonyms":[],"tipVi":"restrict A to B có nghĩa là \"hạn chế A trong phạm vi B\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_citizenship', 'en-b2-58', 'citizenship', '/ˈsɪtɪzənʃɪp/', 'B2', 'quyền công dân; quốc tịch; trách nhiệm và hành vi công dân', 'n.', 'citizen (n.)', NULL, 'Thường là danh từ không đếm được; phân biệt với "residency" (quyền cư trú).', 'She applied for citizenship after living here for years.', NULL, 'Cô ấy đã nộp đơn xin nhập quốc tịch sau nhiều năm sống ở đây.', '{"wordId":"citizenship","ukIpa":"/ˈsɪtɪzənʃɪp/","usIpa":"/ˈsɪtɪzənʃɪp/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"the legal status of belonging to a particular country","vi":"quyền công dân; quốc tịch"},{"pos":"n.","en":"responsible participation in the life of a community","vi":"trách nhiệm và hành vi công dân"}],"examples":[{"en":"She applied for citizenship after living here for years.","vi":"Cô ấy đã nộp đơn xin nhập quốc tịch sau nhiều năm sống ở đây.","audioKind":"ex"},{"en":"Citizenship education can help young people understand their rights and responsibilities while encouraging active participation in democratic processes.","vi":"Giáo dục công dân có thể giúp giới trẻ hiểu rõ quyền lợi và trách nhiệm của mình, đồng thời khuyến khích sự tham gia tích cực vào các tiến trình dân chủ.","audioKind":"ex2"}],"collocations":[{"en":"apply for citizenship","vi":"xin nhập quốc tịch"},{"en":"dual citizenship","vi":"hai quốc tịch"},{"en":"grant citizenship","vi":"cấp quyền công dân"},{"en":"citizenship education","vi":"giáo dục công dân"}],"wordFamily":["citizen (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; phân biệt với \"residency\" (quyền cư trú).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_commission', 'en-b2-58', 'commission', '/kəˈmɪʃən/', 'B2', 'ủy ban; tiền hoa hồng; tiền thưởng doanh số; ủy thác; đặt làm', 'n.', 'commissioner (n.)', NULL, 'Dùng với nghĩa ủy ban là danh từ đếm được; với nghĩa hoa hồng thường dùng dạng không đếm được.', 'The gallery commissioned a local artist to paint our harbour.', NULL, 'Phòng trưng bày đã thuê một họa sĩ địa phương để vẽ cảnh cảng của chúng tôi.', '{"wordId":"commission","ukIpa":"/kəˈmɪʃən/","usIpa":"/kəˈmɪʃən/","cefr":"B2","topic":"government","senses":[{"pos":"n.","en":"An official group appointed to investigate or manage something","vi":"ủy ban"},{"pos":"n.","en":"Payment based on the value of sales or services","vi":"tiền hoa hồng; tiền thưởng doanh số"},{"pos":"v.","en":"To formally ask someone to produce work for payment","vi":"ủy thác; đặt làm"}],"examples":[{"en":"The gallery commissioned a local artist to paint our harbour.","vi":"Phòng trưng bày đã thuê một họa sĩ địa phương để vẽ cảnh cảng của chúng tôi.","audioKind":"ex"},{"en":"An independent commission should investigate housing conditions before the government introduces new safety regulations for rental properties.","vi":"Một ủy ban độc lập nên điều tra tình trạng nhà ở trước khi chính phủ ban hành các quy định an toàn mới đối với nhà cho thuê.","audioKind":"ex2"}],"collocations":[{"en":"an independent commission","vi":"một ủy ban độc lập"},{"en":"earn commission","vi":"kiếm hoa hồng"},{"en":"commission a report","vi":"ủy thác viết báo cáo"},{"en":"commission a painting","vi":"đặt vẽ một bức tranh"}],"wordFamily":["commissioner (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng với nghĩa ủy ban là danh từ đếm được; với nghĩa hoa hồng thường dùng dạng không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_58_1', 'en-b2-58', 'Cách dùng “commander” (n.) — chỉ huy; người chỉ huy', 'military commander  ·  naval commander  ·  commander-in-chief', 'Từ này dùng chung để chỉ người chỉ huy; khi làm cấp bậc quân sự cụ thể, cấp bậc sẽ tùy thuộc vào quy định của từng quốc gia.', 'Họ từ (Word Family): command (v.), command (n.), commanding (adj.)', '[{"hanzi":"The commander asked the crew to check their equipment.","pinyin":"","meaning":"Viên chỉ huy yêu cầu các thành viên trong phi hành đoàn kiểm tra lại trang thiết bị của họ."},{"hanzi":"During disaster relief operations, the military commander coordinated transport to deliver essential supplies to isolated communities.","pinyin":"","meaning":"Trong các chiến dịch cứu trợ thảm họa, người chỉ huy quân sự đã điều phối hoạt động vận tải để cung cấp các nhu yếu phẩm cho những cộng đồng bị cô lập."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_58_2', 'en-b2-58', 'Cách dùng “declare” (v.) — tuyên bố; công bố', 'declare a winner  ·  declare an emergency  ·  declare goods', 'Declare nhấn mạnh việc thông báo công khai hoặc chính thức; thủ tục khai báo hải quan cũng dùng từ này.', 'Họ từ (Word Family): declaration (n.), declared (adj.) | Đồng nghĩa: announce, proclaim', '[{"hanzi":"The judges declared her the winner of the competition.","pinyin":"","meaning":"Các giám khảo đã tuyên bố cô ấy là người chiến thắng trong cuộc thi."},{"hanzi":"Local authorities may declare a public holiday to encourage participation in an important community celebration.","pinyin":"","meaning":"Chính quyền địa phương có thể tuyên bố một ngày nghỉ lễ để khuyến khích sự tham gia vào một lễ kỷ niệm quan trọng của cộng đồng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_58_3', 'en-b2-58', 'Cách dùng “diplomat” (n.) — nhà ngoại giao', 'a senior diplomat  ·  a career diplomat  ·  a foreign diplomat', 'Tính từ diplomatic có thể mang nghĩa thuộc về ngoại giao hoặc khéo léo, tế nhị trong cách nói năng.', 'Họ từ (Word Family): diplomacy (n.), diplomatic (adj.), diplomatically (adv.)', '[{"hanzi":"The diplomat welcomed visitors at the embassy this morning.","pinyin":"","meaning":"Nhà ngoại giao đã chào đón các vị khách tại đại sứ quán vào sáng nay."},{"hanzi":"Experienced diplomats can help countries resolve disagreements through negotiation rather than allowing tensions to escalate.","pinyin":"","meaning":"Những nhà ngoại giao giàu kinh nghiệm có thể giúp các quốc gia giải quyết bất đồng thông qua đàm phán thay vì để căng thẳng leo thang."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_58_4', 'en-b2-58', 'Cách dùng “governor” (n.) — thống đốc; thủ hiến', 'state governor  ·  school governor  ·  prison governor', 'Cụ thể chức vụ dựa theo danh từ đi kèm: school governor chỉ thành viên ban quản trị trường học.', 'Họ từ (Word Family): govern (v.), government (n.), governance (n.)', '[{"hanzi":"The governor visited our town after the river flooded.","pinyin":"","meaning":"Thống đốc đã đến thăm thị trấn của chúng tôi sau trận lụt."},{"hanzi":"The governor proposed additional funding for public schools to reduce educational inequalities across the state.","pinyin":"","meaning":"Thống đốc đã đề xuất cấp thêm kinh phí cho các trường công lập nhằm thu hẹp khoảng cách giáo dục trên toàn tiểu bang."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_58_1', 'en-b2-58', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
