INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_58_1_6', 'ten_b2_58_1', 'democracy', 'Our teacher explained democracy through a classroom vote.', 'Our teacher explained democracy through a classroom vote.', '/dɪˈmɑːkrəsi/', 'Giáo viên của chúng tôi giải thích về nền dân chủ thông qua một cuộc bỏ phiếu trong lớp.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_58_1_7', 'ten_b2_58_1', 'alliance', 'The two clubs formed an alliance to save the pool.', 'The two clubs formed an alliance to save the pool.', '/əˈlaɪəns/', 'Hai câu lạc bộ đã lập nên một liên minh để bảo vệ hồ bơi.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_58_1_8', 'ten_b2_58_1', 'commander', 'The commander asked the crew to check their equipment.', 'The commander asked the crew to check their equipment.', '/kəˈmændər/', 'Viên chỉ huy yêu cầu các thành viên trong phi hành đoàn kiểm tra lại trang thiết bị của họ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_58_1_1', 'en-b2-58', 'ten_b2_58_1', 'listening', 'listening', 'We opened the windows to combat the afternoon heat.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi mở cửa sổ để xua bớt cái nóng buổi chiều.","Các bậc phụ huynh muốn nhà trường cải cách quy trình tuyển sinh.","Chúng tôi nhìn các trực thăng quân sự chở nhu yếu phẩm ra đảo.","Tuyên bố từ chức của cô ấy khiến cả gia đình ngạc nhiên."]'::jsonb, 0, 'We opened the windows to combat the afternoon heat. → Chúng tôi mở cửa sổ để xua bớt cái nóng buổi chiều.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_58_1_2', 'en-b2-58', 'ten_b2_58_1', 'listening', 'listening', 'Parents want the school to reform its admissions process.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bồi thẩm đoàn chăm chú lắng nghe khi nhân chứng mô tả lại vụ tai nạn.","Tuyên bố từ chức của cô ấy khiến cả gia đình ngạc nhiên.","Nhóm đọc sách của chúng tôi đã thảo luận về các tư tưởng xã hội chủ nghĩa bên tách trà.","Các bậc phụ huynh muốn nhà trường cải cách quy trình tuyển sinh."]'::jsonb, 3, 'Parents want the school to reform its admissions process. → Các bậc phụ huynh muốn nhà trường cải cách quy trình tuyển sinh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_58_1_3', 'en-b2-58', 'ten_b2_58_1', 'listening', 'listening', 'The judges declared her the winner of the competition.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi mở cửa sổ để xua bớt cái nóng buổi chiều.","Đôi giày chật này khiến tôi khó cử động khi nhảy.","Thư viện đã áp dụng một khoản tiền phạt nhỏ đối với sách quá hạn của tôi.","Các giám khảo đã tuyên bố cô ấy là người chiến thắng trong cuộc thi."]'::jsonb, 3, 'The judges declared her the winner of the competition. → Các giám khảo đã tuyên bố cô ấy là người chiến thắng trong cuộc thi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_58_2', 'en-b2-58', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_58_2_1', 'ten_b2_58_2', 'combat', 'Governments can combat air pollution by improving public transport and enforcing stricter limits on industrial emissions.', 'Governments can combat air pollution by improving public transport and enforcing stricter limits on industrial emissions.', '/ˈkɑːmbæt/', 'Chính phủ có thể chống lại tình trạng ô nhiễm không khí bằng cách cải thiện giao thông công cộng và thực thi các giới hạn ngặt nghèo hơn đối với khí thải công nghiệp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_58_2_2', 'ten_b2_58_2', 'reform', 'Healthcare reform should focus on reducing waiting times while ensuring equal access to essential services.', 'Healthcare reform should focus on reducing waiting times while ensuring equal access to essential services.', '/rɪˈfɔːrm/', 'Cải cách y tế nên tập trung vào việc giảm thời gian chờ đợi đồng thời bảo đảm mọi người đều có cơ hội tiếp cận công bằng với các dịch vụ thiết yếu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_58_2_3', 'ten_b2_58_2', 'declare', 'Local authorities may declare a public holiday to encourage participation in an important community celebration.', 'Local authorities may declare a public holiday to encourage participation in an important community celebration.', '/dɪˈkler/', 'Chính quyền địa phương có thể tuyên bố một ngày nghỉ lễ để khuyến khích sự tham gia vào một lễ kỷ niệm quan trọng của cộng đồng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_58_2_4', 'ten_b2_58_2', 'declaration', 'The government''s declaration of a climate emergency should be followed by clear policies and measurable environmental targets.', 'The government''s declaration of a climate emergency should be followed by clear policies and measurable environmental targets.', '/ˌdekləˈreɪʃən/', 'Việc chính phủ tuyên bố tình trạng khẩn cấp về khí hậu cần phải đi kèm với các chính sách rõ ràng và mục tiêu môi trường có thể đo lường được.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_58_2_5', 'ten_b2_58_2', 'governor', 'The governor proposed additional funding for public schools to reduce educational inequalities across the state.', 'The governor proposed additional funding for public schools to reduce educational inequalities across the state.', '/ˈɡʌvərnər/', 'Thống đốc đã đề xuất cấp thêm kinh phí cho các trường công lập nhằm thu hẹp khoảng cách giáo dục trên toàn tiểu bang.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_58_2_6', 'ten_b2_58_2', 'democracy', 'A healthy democracy depends on informed citizens who can access reliable information and participate freely in public debate.', 'A healthy democracy depends on informed citizens who can access reliable information and participate freely in public debate.', '/dɪˈmɑːkrəsi/', 'Một nền dân chủ vững mạnh phụ thuộc vào những công dân có hiểu biết, những người có thể tiếp cận thông tin đáng tin cậy và tham gia tự do vào các cuộc thảo luận công khai.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_58_2_1', 'en-b2-58', 'ten_b2_58_2', 'listening', 'listening', 'Governments can combat air pollution by improving public transport and enforcing stricter limits on industrial emissions.', NULL, 'Trong câu vừa nghe, từ “combat” mang nghĩa nào sau đây?', '["đồng tính (nam)","sự can thiệp; sự nhúng tay","chống lại; chiến đấu; ngăn chặn","sự cất giữ; sự bảo quản"]'::jsonb, 2, '“combat” (/ˈkɑːmbæt/): chống lại; chiến đấu; ngăn chặn. Câu đầy đủ: Governments can combat air pollution by improving public transport and enforcing stricter limits on industrial emissions.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_58_2_2', 'en-b2-58', 'ten_b2_58_2', 'listening', 'listening', 'Healthcare reform should focus on reducing waiting times while ensuring equal access to essential services.', NULL, 'Trong câu vừa nghe, từ “reform” mang nghĩa nào sau đây?', '["tiếp thị; marketing","sự chú ý từ dư luận; sự đưa tin của truyền thông","làm việc tự do; thuộc nghề tự do","cải cách; cải tiến (hệ thống)"]'::jsonb, 3, '“reform” (/rɪˈfɔːrm/): cải cách; cải tiến (hệ thống). Câu đầy đủ: Healthcare reform should focus on reducing waiting times while ensuring equal access to essential services.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
