INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_58_2', 'en-b2-58', NULL, 'comprehensive_test', 'listening', 'Parents want the school to reform its admissions process.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nhà ngoại giao đã chào đón các vị khách tại đại sứ quán vào sáng nay.","Bồi thẩm đoàn chăm chú lắng nghe khi nhân chứng mô tả lại vụ tai nạn.","Chúng tôi mở cửa sổ để xua bớt cái nóng buổi chiều.","Các bậc phụ huynh muốn nhà trường cải cách quy trình tuyển sinh."]'::jsonb, 3, 'Parents want the school to reform its admissions process. → Các bậc phụ huynh muốn nhà trường cải cách quy trình tuyển sinh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
