INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_58_4', 'en-b2-58', NULL, 'comprehensive_test', 'listening', 'Her declaration that she would quit surprised the whole family.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Thư viện đã áp dụng một khoản tiền phạt nhỏ đối với sách quá hạn của tôi.","Tuyên bố từ chức của cô ấy khiến cả gia đình ngạc nhiên.","Nhà ngoại giao đã chào đón các vị khách tại đại sứ quán vào sáng nay.","Các giám khảo đã tuyên bố cô ấy là người chiến thắng trong cuộc thi."]'::jsonb, 1, 'Her declaration that she would quit surprised the whole family. → Tuyên bố từ chức của cô ấy khiến cả gia đình ngạc nhiên.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
