INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_58_6', 'en-b2-58', NULL, 'comprehensive_test', 'listening', 'Our teacher explained democracy through a classroom vote.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Viên chỉ huy yêu cầu các thành viên trong phi hành đoàn kiểm tra lại trang thiết bị của họ.","Thư viện đã áp dụng một khoản tiền phạt nhỏ đối với sách quá hạn của tôi.","Giáo viên của chúng tôi giải thích về nền dân chủ thông qua một cuộc bỏ phiếu trong lớp.","Đôi giày chật này khiến tôi khó cử động khi nhảy."]'::jsonb, 2, 'Our teacher explained democracy through a classroom vote. → Giáo viên của chúng tôi giải thích về nền dân chủ thông qua một cuộc bỏ phiếu trong lớp.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
