INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_58_8', 'en-b2-58', NULL, 'comprehensive_test', 'listening', 'The commander asked the crew to check their equipment.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Viên chỉ huy yêu cầu các thành viên trong phi hành đoàn kiểm tra lại trang thiết bị của họ.","Bộ trưởng đã đến thăm trường chúng tôi để gặp gỡ các giáo viên.","Quy định của hồ bơi cấm chạy nhảy trên sàn ướt.","Phòng trưng bày đã thuê một họa sĩ địa phương để vẽ cảnh cảng của chúng tôi."]'::jsonb, 0, 'The commander asked the crew to check their equipment. → Viên chỉ huy yêu cầu các thành viên trong phi hành đoàn kiểm tra lại trang thiết bị của họ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_58_9', 'en-b2-58', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “the official leader of a state or territory”?', '["impose","jury","governor","diplomat"]'::jsonb, 2, 'governor (/ˈɡʌvərnər/) → thống đốc; thủ hiến', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_58_10', 'en-b2-58', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A system of government in which people choose their leaders.”?', '["diplomat","declaration","declare","democracy"]'::jsonb, 3, 'democracy (/dɪˈmɑːkrəsi/) → chế độ dân chủ; nền dân chủ', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_58_11', 'en-b2-58', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A partnership between groups or countries pursuing shared goals.”?', '["combat","governor","democracy","alliance"]'::jsonb, 3, 'alliance (/əˈlaɪəns/) → liên minh; khối liên minh', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
