INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_58_18', 'en-b2-58', NULL, 'comprehensive_test', 'reading', NULL, 'Governments can combat air pollution by improving public transport and enforcing stricter limits on industrial emissions.', 'Dựa vào câu trên, từ “combat” có nghĩa phù hợp nhất là gì?', '["thu nhỏ; mini","sự ghê tởm; sự kinh tởm; sự bất bình","sự tương quan; mối liên hệ","chống lại; chiến đấu; ngăn chặn"]'::jsonb, 3, 'combat: chống lại; chiến đấu; ngăn chặn; trận chiến; cuộc giao tranh. Dịch cả câu: Chính phủ có thể chống lại tình trạng ô nhiễm không khí bằng cách cải thiện giao thông công cộng và thực thi các giới hạn ngặt nghèo hơn đối với khí thải công nghiệp.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_58_19', 'en-b2-58', NULL, 'comprehensive_test', 'reading', NULL, 'Healthcare reform should focus on reducing waiting times while ensuring equal access to essential services.', 'Dựa vào câu trên, từ “reform” có nghĩa phù hợp nhất là gì?', '["không thể tránh khỏi; chắc chắn xảy ra","cải cách; cải tiến (hệ thống)","xuất chúng; kiệt xuất; phi thường","có bóng râm; che râm; tránh nắng trực tiếp"]'::jsonb, 1, 'reform: cải cách; cải tiến (hệ thống); sự cải cách; biện pháp cải tiến; cải tạo; sửa đổi hành vi. Dịch cả câu: Cải cách y tế nên tập trung vào việc giảm thời gian chờ đợi đồng thời bảo đảm mọi người đều có cơ hội tiếp cận công bằng với các dịch vụ thiết yếu.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_58_20', 'en-b2-58', NULL, 'comprehensive_test', 'reading', NULL, 'Local authorities may declare a public holiday to encourage participation in an important community celebration.', 'Dựa vào câu trên, từ “declare” có nghĩa phù hợp nhất là gì?', '["lỗ thủng; vết thủng lốp","tuyên bố; công bố","do dự; chần chừ; ngập ngừng","vụng về; lóng ngóng"]'::jsonb, 1, 'declare: tuyên bố; công bố; khai báo. Dịch cả câu: Chính quyền địa phương có thể tuyên bố một ngày nghỉ lễ để khuyến khích sự tham gia vào một lễ kỷ niệm quan trọng của cộng đồng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_58_21', 'en-b2-58', NULL, 'comprehensive_test', 'reading', NULL, 'The government''s declaration of a climate emergency should be followed by clear policies and measurable environmental targets.', 'Dựa vào câu trên, từ “declaration” có nghĩa phù hợp nhất là gì?', '["tuyên ngôn; lời tuyên bố; sự công bố","tính đa dạng; sự phong phú","ném nhẹ; vứt","đàm phán; thương lượng để đạt thỏa thuận"]'::jsonb, 0, 'declaration: tuyên ngôn; lời tuyên bố; sự công bố; bản khai; tờ khai. Dịch cả câu: Việc chính phủ tuyên bố tình trạng khẩn cấp về khí hậu cần phải đi kèm với các chính sách rõ ràng và mục tiêu môi trường có thể đo lường được.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_58_22', 'en-b2-58', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hạn chế; giới hạn”', '["restrict","tracking","devote","follow-up"]'::jsonb, 0, 'hạn chế; giới hạn → restrict (/rɪˈstrɪkt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
