INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-59', 'en', 'Bài 59: Lịch sử & Văn hóa (1) - CEFR B2', 'CEFR B2', 'B2 · Lịch sử', '21 từ vựng Tiếng Anh CEFR B2 chủ đề lịch sử & văn hóa kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4059, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_armour', 'en-b2-59', 'armour', '/ˈɑːrmɚ/', 'B2', 'áo giáp, vỏ giáp (bảo vệ); lực lượng xe tăng, xe bọc thép', 'n.', 'armoured (adj.)', NULL, '"armour" là cách viết tiếng Anh-Anh, còn tiếng Anh-Mỹ là "armor"; thường là danh từ không đếm được.', 'The museum displayed a knight''s armour beside a wooden shield.', NULL, 'Bảo tàng trưng bày bộ giáp của một hiệp sĩ bên cạnh chiếc khiên bằng gỗ.', '{"wordId":"armour","ukIpa":"/ˈɑːmə/","usIpa":"/ˈɑːrmɚ/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"Strong protective covering worn in battle or fitted to vehicles.","vi":"áo giáp, vỏ giáp (bảo vệ)"},{"pos":"n.","en":"Military vehicles with protective covering, considered as a group.","vi":"lực lượng xe tăng, xe bọc thép"}],"examples":[{"en":"The museum displayed a knight''s armour beside a wooden shield.","vi":"Bảo tàng trưng bày bộ giáp của một hiệp sĩ bên cạnh chiếc khiên bằng gỗ.","audioKind":"ex"},{"en":"Surviving examples of medieval armour reveal how metalworking skills developed in response to changing military needs.","vi":"Những bộ áo giáp thời Trung cổ còn sót lại cho thấy kỹ năng chế tác kim loại đã phát triển như thế nào để đáp ứng các nhu cầu thay đổi trong quân sự.","audioKind":"ex2"}],"collocations":[{"en":"a suit of armour","vi":"một bộ áo giáp"},{"en":"body armour","vi":"giáp bảo vệ cơ thể"},{"en":"heavy armour","vi":"giáp hạng nặng"}],"wordFamily":["armoured (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"\"armour\" là cách viết tiếng Anh-Anh, còn tiếng Anh-Mỹ là \"armor\"; thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lord', 'en-b2-59', 'lord', '/lɔːrd/', 'B2', 'lãnh chúa; quý tộc; Chúa; Đức Chúa Trời', 'n.', 'lordship (n.), lordly (adj.)', 'Đồng nghĩa: nobleman', 'Khi chỉ Chúa Trời dùng the Lord; khi đứng trước tên riêng làm tước hiệu thì viết hoa.', 'The guide showed us where the local lord once lived.', NULL, 'Hướng dẫn viên đã chỉ cho chúng tôi nơi vị lãnh chúa địa phương từng sinh sống.', '{"wordId":"lord","ukIpa":"/lɔːd/","usIpa":"/lɔːrd/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"a man with a high noble rank or historical authority","vi":"lãnh chúa; quý tộc"},{"pos":"n.","en":"a title used to address or refer to God","vi":"Chúa; Đức Chúa Trời"}],"examples":[{"en":"The guide showed us where the local lord once lived.","vi":"Hướng dẫn viên đã chỉ cho chúng tôi nơi vị lãnh chúa địa phương từng sinh sống.","audioKind":"ex"},{"en":"In medieval society, a lord often controlled farmland and collected payments from the people who worked it.","vi":"Trong xã hội trung cổ, lãnh chúa thường nắm quyền kiểm soát đất nông nghiệp và thu tiền từ những người làm thuê trên đất đó.","audioKind":"ex2"}],"collocations":[{"en":"a powerful lord","vi":"một lãnh chúa quyền lực"},{"en":"lord of the manor","vi":"chủ trang viên"},{"en":"the Lord","vi":"Đức Chúa Trời"},{"en":"lord it over someone","vi":"hách dịch với ai; ra oai với ai"}],"wordFamily":["lordship (n.)","lordly (adj.)"],"synonyms":["nobleman"],"antonyms":[],"tipVi":"Khi chỉ Chúa Trời dùng the Lord; khi đứng trước tên riêng làm tước hiệu thì viết hoa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spear', 'en-b2-59', 'spear', '/spɪr/', 'B2', 'cây lao; thương; giáo; đâm bằng lao; xiên qua', 'n.', NULL, NULL, 'spear là lao hoặc giáo, không phải súng; động từ có thể chỉ hành động dùng vật nhọn xiên lấy thức ăn.', 'An ancient spear stood behind glass in the museum.', NULL, 'Một cây lao cổ được đặt đằng sau lớp kính trong viện bảo tàng.', '{"wordId":"spear","ukIpa":"/spɪə/","usIpa":"/spɪr/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"a long pole with a sharp point, used as a weapon","vi":"cây lao; thương; giáo"},{"pos":"v.","en":"to push a pointed object into or through something","vi":"đâm bằng lao; xiên qua"}],"examples":[{"en":"An ancient spear stood behind glass in the museum.","vi":"Một cây lao cổ được đặt đằng sau lớp kính trong viện bảo tàng.","audioKind":"ex"},{"en":"The discovery of a wooden spear provides valuable evidence about the hunting techniques of early human communities.","vi":"Việc phát hiện ra một ngọn lao bằng gỗ cung cấp bằng chứng quý giá về kỹ thuật săn bắn của các cộng đồng người thời tiền sử.","audioKind":"ex2"}],"collocations":[{"en":"wooden spear","vi":"cây lao gỗ"},{"en":"spear tip","vi":"mũi lao"},{"en":"spear a piece of food","vi":"xiên một miếng thức ăn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"spear là lao hoặc giáo, không phải súng; động từ có thể chỉ hành động dùng vật nhọn xiên lấy thức ăn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sword', 'en-b2-59', 'sword', '/sɔːrd/', 'B2', 'thanh kiếm; đao', 'n.', NULL, NULL, 'Chữ w không phát âm; "double-edged sword" có thể dùng để ví von một sự việc vừa có lợi vừa có hại.', 'An ancient sword lay inside the museum''s glass case.', NULL, 'Một thanh kiếm cổ nằm bên trong tủ kính của bảo tàng.', '{"wordId":"sword","ukIpa":"/sɔːd/","usIpa":"/sɔːrd/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"A weapon with a long blade and a handle.","vi":"thanh kiếm; đao"}],"examples":[{"en":"An ancient sword lay inside the museum''s glass case.","vi":"Một thanh kiếm cổ nằm bên trong tủ kính của bảo tàng.","audioKind":"ex"},{"en":"The discovery of a decorated sword provides evidence of advanced metalworking skills in this ancient society.","vi":"Việc phát hiện ra một thanh kiếm được trang trí tinh xảo cung cấp bằng chứng về kỹ năng gia công kim loại tiên tiến ở xã hội cổ đại này.","audioKind":"ex2"}],"collocations":[{"en":"draw a sword","vi":"tuốt gươm"},{"en":"a sword blade","vi":"lưỡi kiếm"},{"en":"a double-edged sword","vi":"con dao hai lưỡi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chữ w không phát âm; \"double-edged sword\" có thể dùng để ví von một sự việc vừa có lợi vừa có hại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bronze', 'en-b2-59', 'bronze', '/brɑːnz/', 'B2', 'đồng đỏ; đồng thau (hợp kim đồng và thiếc); đồng thiếc; huy chương đồng; bằng đồng; có màu nâu đỏ của đồng', 'n.', NULL, NULL, 'bronze là đồng thiếc/đồng đỏ; brass là đồng thau; copper là đồng nguyên chất.', 'The small statue is made of solid bronze.', NULL, 'Bức tượng nhỏ được làm bằng đồng đặc.', '{"wordId":"bronze","ukIpa":"/brɒnz/","usIpa":"/brɑːnz/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"A brownish metal made mainly from copper and tin.","vi":"đồng đỏ; đồng thau (hợp kim đồng và thiếc); đồng thiếc"},{"pos":"n.","en":"A medal awarded for finishing third in a competition.","vi":"huy chương đồng"},{"pos":"adj.","en":"Made of bronze, or having its reddish-brown color.","vi":"bằng đồng; có màu nâu đỏ của đồng"}],"examples":[{"en":"The small statue is made of solid bronze.","vi":"Bức tượng nhỏ được làm bằng đồng đặc.","audioKind":"ex"},{"en":"Ancient tools made from bronze reveal how advances in metalworking transformed agriculture and trade across early societies.","vi":"Những công cụ cổ xưa làm bằng đồng thau cho thấy những tiến bộ trong kỹ nghệ chế tác kim loại đã làm thay đổi nông nghiệp và thương mại ở các xã hội thời kỳ đầu như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"bronze statue","vi":"tượng đồng"},{"en":"bronze medal","vi":"huy chương đồng"},{"en":"cast in bronze","vi":"đúc bằng đồng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"bronze là đồng thiếc/đồng đỏ; brass là đồng thau; copper là đồng nguyên chất.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_telegram', 'en-b2-59', 'telegram', '/ˈtelɪɡræm/', 'B2', 'điện báo', 'n.', 'telegraph (n.), telegraphic (adj.)', NULL, 'telegram là bản tin điện báo; telegraph chỉ hệ thống truyền tin điện báo.', 'Grandmother kept the telegram announcing her brother''s safe arrival.', NULL, 'Bà tôi vẫn giữ bức điện báo thông báo anh trai bà đã đến nơi an toàn.', '{"wordId":"telegram","ukIpa":"/ˈtelɪɡræm/","usIpa":"/ˈtelɪɡræm/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"a message sent by telegraph and delivered in written form","vi":"điện báo"}],"examples":[{"en":"Grandmother kept the telegram announcing her brother''s safe arrival.","vi":"Bà tôi vẫn giữ bức điện báo thông báo anh trai bà đã đến nơi an toàn.","audioKind":"ex"},{"en":"Before telephone services became widely available, sending a telegram was an important way to communicate urgent news.","vi":"Trước khi dịch vụ điện thoại trở nên phổ biến rộng rãi, gửi điện báo là một cách quan trọng để truyền đạt tin tức khẩn cấp.","audioKind":"ex2"}],"collocations":[{"en":"send a telegram","vi":"gửi điện báo"},{"en":"receive a telegram","vi":"nhận điện báo"},{"en":"deliver a telegram","vi":"phát điện báo"}],"wordFamily":["telegraph (n.)","telegraphic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"telegram là bản tin điện báo; telegraph chỉ hệ thống truyền tin điện báo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fort', 'en-b2-59', 'fort', '/fɔːrt/', 'B2', 'pháo đài; đồn lũy; thành trì', 'n.', 'fortify (v.), fortification (n.)', 'Đồng nghĩa: fortress, stronghold', 'Fort nhấn mạnh chức năng phòng thủ quân sự; castle thường đồng thời là nơi ở của giới quý tộc.', 'We climbed the hill to explore the old fort.', NULL, 'Chúng tôi leo lên đồi để khám phá pháo đài cổ.', '{"wordId":"fort","ukIpa":"/fɔːt/","usIpa":"/fɔːrt/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"A strong building or enclosed place built for military defence.","vi":"pháo đài; đồn lũy; thành trì"}],"examples":[{"en":"We climbed the hill to explore the old fort.","vi":"Chúng tôi leo lên đồi để khám phá pháo đài cổ.","audioKind":"ex"},{"en":"Restoring the coastal fort could attract tourists while preserving an important part of the region''s military history.","vi":"Việc phục hồi pháo đài ven biển có thể thu hút khách du lịch đồng thời bảo tồn một phần di sản lịch sử quân sự quan trọng của khu vực.","audioKind":"ex2"}],"collocations":[{"en":"build a fort","vi":"xây dựng pháo đài"},{"en":"coastal fort","vi":"pháo đài ven biển"},{"en":"abandoned fort","vi":"pháo đài bỏ hoang"}],"wordFamily":["fortify (v.)","fortification (n.)"],"synonyms":["fortress","stronghold"],"antonyms":[],"tipVi":"Fort nhấn mạnh chức năng phòng thủ quân sự; castle thường đồng thời là nơi ở của giới quý tộc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_era', 'en-b2-59', 'era', '/ˈɪrə/', 'B2', 'thời đại; kỷ nguyên; giai đoạn lịch sử', 'n.', NULL, 'Đồng nghĩa: age, epoch', '''Era'' nhấn mạnh một khoảng thời gian có những đặc điểm chung rõ rệt, không chỉ một số năm cố định.', 'These old photographs remind us of a different era.', NULL, 'Những bức ảnh cũ này gợi cho chúng ta nhớ về một thời kỳ khác.', '{"wordId":"era","ukIpa":"/ˈɪərə/","usIpa":"/ˈɪrə/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"A period distinguished by particular events, developments, or ways of life.","vi":"thời đại; kỷ nguyên; giai đoạn lịch sử"}],"examples":[{"en":"These old photographs remind us of a different era.","vi":"Những bức ảnh cũ này gợi cho chúng ta nhớ về một thời kỳ khác.","audioKind":"ex"},{"en":"The digital era has transformed how people access information, creating both educational opportunities and new inequalities.","vi":"Kỷ nguyên số đã biến đổi cách mọi người tiếp cận thông tin, vừa tạo ra các cơ hội giáo dục vừa làm xuất hiện những bất bình đẳng mới.","audioKind":"ex2"}],"collocations":[{"en":"digital era","vi":"kỷ nguyên số"},{"en":"a new era","vi":"một thời đại mới"},{"en":"the end of an era","vi":"sự chấm dứt của một thời kỳ"}],"wordFamily":[],"synonyms":["age","epoch"],"antonyms":[],"tipVi":"''Era'' nhấn mạnh một khoảng thời gian có những đặc điểm chung rõ rệt, không chỉ một số năm cố định.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_throne', 'en-b2-59', 'throne', '/θroʊn/', 'B2', 'ngai vàng; vương tọa; vương vị; vương quyền', 'n.', NULL, NULL, 'Cụm từ the throne có thể mang nghĩa là ngôi vị hoàng gia, không nhất thiết chỉ chiếc ghế vật lý.', 'The queen sat on a throne beside the window.', NULL, 'Nữ hoàng ngồi trên ngai vàng cạnh cửa sổ.', '{"wordId":"throne","ukIpa":"/θrəʊn/","usIpa":"/θroʊn/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"A special chair used by a king or queen.","vi":"ngai vàng; vương tọa"},{"pos":"n.","en":"The position or power of a king or queen.","vi":"vương vị; vương quyền"}],"examples":[{"en":"The queen sat on a throne beside the window.","vi":"Nữ hoàng ngồi trên ngai vàng cạnh cửa sổ.","audioKind":"ex"},{"en":"Her accession to the throne marked a significant change in the country''s political relationship with its neighbours.","vi":"Việc bà lên ngôi đã đánh dấu một sự thay đổi đáng kể trong mối quan hệ chính trị của đất nước với các nước láng giềng.","audioKind":"ex2"}],"collocations":[{"en":"sit on a throne","vi":"ngồi trên ngai vàng"},{"en":"ascend the throne","vi":"lên ngôi"},{"en":"heir to the throne","vi":"người thừa kế ngai vàng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ the throne có thể mang nghĩa là ngôi vị hoàng gia, không nhất thiết chỉ chiếc ghế vật lý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_medieval', 'en-b2-59', 'medieval', '/ˌmiːdiˈiːvəl/', 'B2', 'thuộc thời Trung cổ', 'adj.', 'medievalist (n.)', NULL, 'Thường chỉ giai đoạn lịch sử châu Âu từ khoảng năm 500 đến năm 1500 sau Công nguyên.', 'We explored a medieval castle during our weekend trip.', NULL, 'Chúng tôi đã khám phá một lâu đài thời Trung cổ trong chuyến đi cuối tuần.', '{"wordId":"medieval","ukIpa":"/ˌmediˈiːvəl/","usIpa":"/ˌmiːdiˈiːvəl/","cefr":"B2","topic":"history","senses":[{"pos":"adj.","en":"relating to European history from about AD 500 to 1500","vi":"thuộc thời Trung cổ"}],"examples":[{"en":"We explored a medieval castle during our weekend trip.","vi":"Chúng tôi đã khám phá một lâu đài thời Trung cổ trong chuyến đi cuối tuần.","audioKind":"ex"},{"en":"Preserving medieval buildings allows modern communities to understand how earlier generations lived, worked, and organised their societies.","vi":"Việc bảo tồn các công trình kiến trúc thời Trung cổ giúp cộng đồng hiện đại hiểu được cách các thế hệ trước sống, làm việc và tổ chức xã hội của họ.","audioKind":"ex2"}],"collocations":[{"en":"medieval architecture","vi":"kiến trúc trung cổ"},{"en":"a medieval castle","vi":"một lâu đài thời trung cổ"},{"en":"medieval history","vi":"lịch sử trung cổ"},{"en":"medieval Europe","vi":"châu Âu thời trung cổ"}],"wordFamily":["medievalist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ giai đoạn lịch sử châu Âu từ khoảng năm 500 đến năm 1500 sau Công nguyên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_formerly', 'en-b2-59', 'formerly', '/ˈfɔːrmərli/', 'B2', 'trước đây; thuở trước', 'adv.', 'former (adj.)', 'Đồng nghĩa: previously, once · Trái nghĩa: currently', 'formerly dùng để chỉ "trước đây"; formally dùng để chỉ "chính thức".', 'This bright café was formerly a small bicycle shop.', NULL, 'Quán cà phê sáng sủa này trước đây là một cửa hàng xe đạp nhỏ.', '{"wordId":"formerly","ukIpa":"/ˈfɔːməli/","usIpa":"/ˈfɔːrmərli/","cefr":"B2","topic":"history","senses":[{"pos":"adv.","en":"in the past, but not now","vi":"trước đây; thuở trước"}],"examples":[{"en":"This bright café was formerly a small bicycle shop.","vi":"Quán cà phê sáng sủa này trước đây là một cửa hàng xe đạp nhỏ.","audioKind":"ex"},{"en":"Buildings formerly used for manufacturing can be converted into affordable housing while preserving their distinctive architectural features.","vi":"Các tòa nhà trước đây được dùng làm nơi sản xuất có thể được cải tạo thành nhà ở giá rẻ trong khi vẫn giữ lại các đặc điểm kiến trúc độc đáo của chúng.","audioKind":"ex2"}],"collocations":[{"en":"formerly known as","vi":"từng được gọi là"},{"en":"formerly owned by","vi":"từng thuộc sở hữu của"},{"en":"formerly used for","vi":"trước đây được dùng cho"}],"wordFamily":["former (adj.)"],"synonyms":["previously","once"],"antonyms":["currently"],"tipVi":"formerly dùng để chỉ \"trước đây\"; formally dùng để chỉ \"chính thức\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_surrender', 'en-b2-59', 'surrender', '/səˈrendər/', 'B2', 'đầu hàng, chịu khuất phục trước sự kiểm soát của phe khác; từ bỏ, giao nộp thứ gì đó (thường do yêu cầu chính thức); sự đầu hàng, sự chịu khuất phục', 'v.', NULL, 'Đồng nghĩa: yield, give up · Trái nghĩa: resist', '"Surrender to sb" nghĩa là đầu hàng ai đó; khi giao nộp đồ vật thì đi thẳng với tân ngữ.', 'The soldiers surrendered and walked forward with empty hands.', NULL, 'Binh lính đã đầu hàng và bước lên phía trước với đôi tay không.', '{"wordId":"surrender","ukIpa":"/səˈrendə/","usIpa":"/səˈrendər/","cefr":"B2","topic":"history","senses":[{"pos":"v.","en":"to stop resisting and accept another side''s control","vi":"đầu hàng, chịu khuất phục trước sự kiểm soát của phe khác"},{"pos":"v.","en":"to give up something, often because officially required","vi":"từ bỏ, giao nộp thứ gì đó (thường do yêu cầu chính thức)"},{"pos":"n.","en":"the act of stopping resistance and accepting another side''s control","vi":"sự đầu hàng, sự chịu khuất phục"}],"examples":[{"en":"The soldiers surrendered and walked forward with empty hands.","vi":"Binh lính đã đầu hàng và bước lên phía trước với đôi tay không.","audioKind":"ex"},{"en":"Users should not have to surrender control of their personal information to access essential online services.","vi":"Người dùng không nên buộc phải từ bỏ quyền kiểm soát thông tin cá nhân của họ chỉ để truy cập các dịch vụ trực tuyến thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"surrender to","vi":"đầu hàng trước"},{"en":"surrender control","vi":"giao nộp quyền kiểm soát"},{"en":"unconditional surrender","vi":"sự đầu hàng vô điều kiện"}],"wordFamily":[],"synonyms":["yield","give up"],"antonyms":["resist"],"tipVi":"\"Surrender to sb\" nghĩa là đầu hàng ai đó; khi giao nộp đồ vật thì đi thẳng với tân ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fortress', 'en-b2-59', 'fortress', '/ˈfɔːrtrəs/', 'B2', 'pháo đài; thành lũy; đồn lũy', 'n.', 'fort (n.), fortify (v.), fortification (n.)', 'Đồng nghĩa: stronghold, citadel, fort', 'Chỉ các công trình phòng thủ kiên cố; trong khi castle nhấn mạnh vào kiến trúc lâu đài mang tính dinh thự hơn.', 'We climbed the hill to explore the old fortress.', NULL, 'Chúng tôi đã leo lên ngọn đồi để khám phá pháo đài cổ kính đó.', '{"wordId":"fortress","ukIpa":"/ˈfɔːtrəs/","usIpa":"/ˈfɔːrtrəs/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"A strongly defended building or place designed to resist attack.","vi":"pháo đài; thành lũy; đồn lũy"}],"examples":[{"en":"We climbed the hill to explore the old fortress.","vi":"Chúng tôi đã leo lên ngọn đồi để khám phá pháo đài cổ kính đó.","audioKind":"ex"},{"en":"Restoring a historic fortress can attract visitors while preserving evidence of a region''s military past.","vi":"Việc trùng tu một pháo đài lịch sử có thể thu hút khách du lịch đồng thời bảo tồn những minh chứng về quá khứ quân sự của một vùng đất.","audioKind":"ex2"}],"collocations":[{"en":"a medieval fortress","vi":"pháo đài thời trung cổ"},{"en":"a heavily fortified fortress","vi":"pháo đài được phòng thủ kiên cố"},{"en":"an island fortress","vi":"pháo đài trên đảo"}],"wordFamily":["fort (n.)","fortify (v.)","fortification (n.)"],"synonyms":["stronghold","citadel","fort"],"antonyms":[],"tipVi":"Chỉ các công trình phòng thủ kiên cố; trong khi castle nhấn mạnh vào kiến trúc lâu đài mang tính dinh thự hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ancestor', 'en-b2-59', 'ancestor', '/ˈænsestər/', 'B2', 'tổ tiên; ông cha; loài tổ tiên; dạng nguyên thủy', 'n.', 'ancestry (n.), ancestral (adj.)', 'Đồng nghĩa: forebear, forefather · Trái nghĩa: descendant', 'ancestor chỉ tổ tiên; descendant chỉ hậu thế.', 'One of my ancestors built this old stone house.', NULL, 'Một người tổ tiên của tôi đã xây dựng ngôi nhà đá cổ này.', '{"wordId":"ancestor","ukIpa":"/ˈænsestə/","usIpa":"/ˈænsestər/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"a family member who lived several generations before you","vi":"tổ tiên; ông cha"},{"pos":"n.","en":"an earlier species or form from which something developed","vi":"loài tổ tiên; dạng nguyên thủy"}],"examples":[{"en":"One of my ancestors built this old stone house.","vi":"Một người tổ tiên của tôi đã xây dựng ngôi nhà đá cổ này.","audioKind":"ex"},{"en":"Studying how our ancestors adapted to environmental change can offer insights into human resilience.","vi":"Việc nghiên cứu cách tổ tiên chúng ta thích nghi với sự thay đổi môi trường có thể mang lại góc nhìn sâu sắc về khả năng chống chịu của con người.","audioKind":"ex2"}],"collocations":[{"en":"common ancestor","vi":"tổ tiên chung"},{"en":"distant ancestor","vi":"tổ tiên đời trước; tổ tiên xa"},{"en":"human ancestors","vi":"tổ tiên loài người"}],"wordFamily":["ancestry (n.)","ancestral (adj.)"],"synonyms":["forebear","forefather"],"antonyms":["descendant"],"tipVi":"ancestor chỉ tổ tiên; descendant chỉ hậu thế.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_civilization', 'en-b2-59', 'civilization', '/ˌsɪvələˈzeɪʃən/', 'B2', 'xã hội văn minh; nền văn minh; đời sống văn minh; tiện nghi hiện đại', 'n.', 'civilize (v.), civilized (adj.)', NULL, 'Trong tiếng Anh Anh cũng có thể viết là civilisation; một nền văn minh cụ thể dùng là a civilization.', 'We explored the ruins of an ancient civilization yesterday.', NULL, 'Hôm qua chúng tôi đã thám hiểm tàn tích của một nền văn minh cổ đại.', '{"wordId":"civilization","ukIpa":"/ˌsɪvəlaɪˈzeɪʃən/","usIpa":"/ˌsɪvələˈzeɪʃən/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"an organized society with developed institutions, culture, and technology","vi":"xã hội văn minh; nền văn minh"},{"pos":"n.","en":"the comforts and services associated with modern society","vi":"đời sống văn minh; tiện nghi hiện đại"}],"examples":[{"en":"We explored the ruins of an ancient civilization yesterday.","vi":"Hôm qua chúng tôi đã thám hiểm tàn tích của một nền văn minh cổ đại.","audioKind":"ex"},{"en":"Reliable water supplies played a crucial role in the development of civilization by supporting agriculture and permanent settlements.","vi":"Nguồn nước ổn định đóng vai trò quyết định trong sự phát triển của nền văn minh nhờ hỗ trợ hoạt động nông nghiệp và các khu định cư cố định.","audioKind":"ex2"}],"collocations":[{"en":"ancient civilization","vi":"nền văn minh cổ đại"},{"en":"the rise of civilization","vi":"sự trỗi dậy của nền văn minh"},{"en":"human civilization","vi":"văn minh nhân loại"}],"wordFamily":["civilize (v.)","civilized (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh Anh cũng có thể viết là civilisation; một nền văn minh cụ thể dùng là a civilization.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rebellion', 'en-b2-59', 'rebellion', '/rɪˈbeljən/', 'B2', 'cuộc nổi dậy; cuộc khởi nghĩa; sự phản kháng; thái độ nổi loạn; sự chống đối', 'n.', 'rebel (n.), rebel (v.), rebellious (adj.)', 'Đồng nghĩa: uprising, revolt · Trái nghĩa: obedience, submission', 'Thường đi với giới từ against để chỉ đối tượng bị chống đối.', 'Refusing to tidy his room was his small rebellion.', NULL, 'Việc từ chối dọn dẹp phòng chính là hành vi phản kháng nhỏ của cậu bé.', '{"wordId":"rebellion","ukIpa":"/rɪˈbeljən/","usIpa":"/rɪˈbeljən/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"Organized resistance, often violent, against a government or ruler.","vi":"cuộc nổi dậy; cuộc khởi nghĩa"},{"pos":"n.","en":"Refusal to accept authority, rules, or expected behaviour.","vi":"sự phản kháng; thái độ nổi loạn; sự chống đối"}],"examples":[{"en":"Refusing to tidy his room was his small rebellion.","vi":"Việc từ chối dọn dẹp phòng chính là hành vi phản kháng nhỏ của cậu bé.","audioKind":"ex"},{"en":"Historians often examine how economic hardship and political exclusion contribute to rebellion against established authority.","vi":"Các nhà sử học thường nghiên cứu xem khó khăn kinh tế và việc bị gạt ra ngoài lề chính trị đã góp phần dẫn đến sự chống đối lại các nhà cầm quyền như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"armed rebellion","vi":"cuộc nổi dậy vũ trang"},{"en":"teenage rebellion","vi":"sự nổi loạn của tuổi dậy thì"},{"en":"rebellion against authority","vi":"sự phản kháng lại quyền lực"},{"en":"crush a rebellion","vi":"dập tắt một cuộc nổi dậy"}],"wordFamily":["rebel (n.)","rebel (v.)","rebellious (adj.)"],"synonyms":["uprising","revolt"],"antonyms":["obedience","submission"],"tipVi":"Thường đi với giới từ against để chỉ đối tượng bị chống đối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_archaeologist', 'en-b2-59', 'archaeologist', '/ˌɑːrkiˈɑːlədʒɪst/', 'B2', 'nhà khảo cổ học', 'n.', 'archaeology (n.), archaeological (adj.), archaeologically (adv.)', NULL, 'Khảo cổ nghiên cứu nhân học và di tồn; nghiên cứu khủng long thường là nhà cổ sinh vật học.', 'The archaeologist gently brushed soil from a clay bowl.', NULL, 'Nhà khảo cổ học nhẹ nhàng phủi lớp đất bám trên chiếc bát đất nung.', '{"wordId":"archaeologist","ukIpa":"/ˌɑːkiˈɒlədʒɪst/","usIpa":"/ˌɑːrkiˈɑːlədʒɪst/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"someone who studies past societies through objects and physical remains","vi":"nhà khảo cổ học"}],"examples":[{"en":"The archaeologist gently brushed soil from a clay bowl.","vi":"Nhà khảo cổ học nhẹ nhàng phủi lớp đất bám trên chiếc bát đất nung.","audioKind":"ex"},{"en":"An archaeologist can reveal how ancient communities adapted to environmental change by examining tools and settlement patterns.","vi":"Một nhà khảo cổ học có thể tiết lộ cách các cộng đồng cổ đại thích nghi với sự thay đổi của môi trường thông qua việc nghiên cứu các công cụ và mô hình định cư.","audioKind":"ex2"}],"collocations":[{"en":"a team of archaeologists","vi":"đội ngũ nhà khảo cổ học"},{"en":"a leading archaeologist","vi":"nhà khảo cổ học hàng đầu"},{"en":"a field archaeologist","vi":"nhà khảo cổ học điền dã"}],"wordFamily":["archaeology (n.)","archaeological (adj.)","archaeologically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Khảo cổ nghiên cứu nhân học và di tồn; nghiên cứu khủng long thường là nhà cổ sinh vật học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_invader', 'en-b2-59', 'invader', '/ɪnˈveɪdər/', 'B2', 'kẻ xâm lược; ngoại xâm; sinh vật xâm lấn', 'n.', 'invade (v.), invasion (n.), invasive (adj.)', 'Đồng nghĩa: intruder · Trái nghĩa: defender', 'invader chỉ kẻ xâm lược; invasion chỉ hành động xâm lược.', 'The castle walls once protected villagers from invaders.', NULL, 'Tường thành lâu đài từng bảo vệ dân làng khỏi những kẻ xâm lược.', '{"wordId":"invader","ukIpa":"/ɪnˈveɪdə/","usIpa":"/ɪnˈveɪdər/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"a person or force entering a place without permission","vi":"kẻ xâm lược; ngoại xâm"},{"pos":"n.","en":"an organism spreading into an area and threatening native life","vi":"sinh vật xâm lấn"}],"examples":[{"en":"The castle walls once protected villagers from invaders.","vi":"Tường thành lâu đài từng bảo vệ dân làng khỏi những kẻ xâm lược.","audioKind":"ex"},{"en":"Biological invaders can disrupt local ecosystems by competing with native species for food, space, and other resources.","vi":"Các loài sinh vật xâm lấn có thể phá vỡ hệ sinh thái bản địa bằng cách tranh giành thức ăn, không gian và các nguồn tài nguyên khác với các loài bản địa.","audioKind":"ex2"}],"collocations":[{"en":"foreign invaders","vi":"kẻ xâm ngoại lai"},{"en":"repel invaders","vi":"đẩy lùi kẻ xâm lược"},{"en":"biological invader","vi":"sinh vật xâm lấn"}],"wordFamily":["invade (v.)","invasion (n.)","invasive (adj.)"],"synonyms":["intruder"],"antonyms":["defender"],"tipVi":"invader chỉ kẻ xâm lược; invasion chỉ hành động xâm lược.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_remains', 'en-b2-59', 'remains', '/rɪˈmeɪnz/', 'B2', 'phần còn lại; đồ thừa; di tích; di vững; di hài; hài cốt', 'n.', 'remain (v.), remaining (adj.)', NULL, 'Dùng làm danh từ luôn đi với động từ số nhiều; cũng có thể là dạng số ít của động từ remain.', 'The remains of our picnic filled a small bag.', NULL, 'Đồ ăn thừa sau buổi dã ngoại của chúng tôi đã làm đầy một chiếc túi nhỏ.', '{"wordId":"remains","ukIpa":"/rɪˈmeɪnz/","usIpa":"/rɪˈmeɪnz/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"Parts left after something has been used, damaged, or destroyed.","vi":"phần còn lại; đồ thừa"},{"pos":"n.","en":"Surviving parts of ancient buildings or objects.","vi":"di tích; di vững"},{"pos":"n.","en":"The body or bones of a dead person or animal.","vi":"di hài; hài cốt"}],"examples":[{"en":"The remains of our picnic filled a small bag.","vi":"Đồ ăn thừa sau buổi dã ngoại của chúng tôi đã làm đầy một chiếc túi nhỏ.","audioKind":"ex"},{"en":"The remains of ancient settlements provide valuable evidence about how early communities adapted to environmental change.","vi":"Các di tích của các khu định cư cổ đại cung cấp bằng chứng quý giá về cách các cộng đồng thời sơ khai thích ứng với biến đổi môi trường.","audioKind":"ex2"}],"collocations":[{"en":"the remains of a meal","vi":"đồ ăn thừa sau bữa ăn"},{"en":"archaeological remains","vi":"di tích khảo cổ"},{"en":"human remains","vi":"di hài người"}],"wordFamily":["remain (v.)","remaining (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng làm danh từ luôn đi với động từ số nhiều; cũng có thể là dạng số ít của động từ remain.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_revolution', 'en-b2-59', 'revolution', '/ˌrevəˈluːʃən/', 'B2', 'cuộc cách mạng; cuộc lật đổ chính quyền bằng vũ lực; sự thay đổi toàn diện; vòng quay; vòng lặp quanh một điểm', 'n.', 'revolutionary (adj.), revolutionise (v.), revolve (v.)', 'Đồng nghĩa: upheaval, transformation', 'revolution nhấn mạnh sự thay đổi tận gốc rễ; còn reform thường chỉ sự cải cách dần dần.', 'The museum has a room devoted to the revolution.', NULL, 'Bảo tàng có một phòng trưng bày dành riêng cho cuộc cách mạng này.', '{"wordId":"revolution","ukIpa":"/ˌrevəˈluːʃən/","usIpa":"/ˌrevəˈluːʃən/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"a major change in government, often achieved by force","vi":"cuộc cách mạng; cuộc lật đổ chính quyền bằng vũ lực"},{"pos":"n.","en":"a dramatic change in how something works or is done","vi":"cuộc cách mạng; sự thay đổi toàn diện"},{"pos":"n.","en":"one complete turn around a point or axis","vi":"vòng quay; vòng lặp quanh một điểm"}],"examples":[{"en":"The museum has a room devoted to the revolution.","vi":"Bảo tàng có một phòng trưng bày dành riêng cho cuộc cách mạng này.","audioKind":"ex"},{"en":"The digital revolution has transformed education by allowing students to access learning materials from almost anywhere.","vi":"Cuộc cách mạng kỹ thuật số đã chuyển đổi nền giáo dục bằng cách cho phép học sinh tiếp cận tài liệu học tập từ hầu như bất cứ đâu.","audioKind":"ex2"}],"collocations":[{"en":"political revolution","vi":"cách mạng chính trị"},{"en":"industrial revolution","vi":"cách mạng công nghiệp"},{"en":"digital revolution","vi":"cách mạng kỹ thuật số"},{"en":"a complete revolution","vi":"một vòng quay trọn vẹn"}],"wordFamily":["revolutionary (adj.)","revolutionise (v.)","revolve (v.)"],"synonyms":["upheaval","transformation"],"antonyms":[],"tipVi":"revolution nhấn mạnh sự thay đổi tận gốc rễ; còn reform thường chỉ sự cải cách dần dần.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_soviet', 'en-b2-59', 'Soviet', '/ˈsoʊviət/', 'B2', 'thuộc Liên Xô cũ; thuộc các hội đồng Xô-viết; công dân Liên Xô cũ', 'adj.', NULL, NULL, 'Soviet thường được viết hoa; chữ soviet viết thường có thể chỉ hội đồng Xô-viết.', 'My grandfather kept a Soviet camera in this drawer.', NULL, 'Ông tôi giữ một chiếc máy ảnh Liên Xô trong ngăn kéo này.', '{"wordId":"soviet","ukIpa":"/ˈsəʊviət/","usIpa":"/ˈsoʊviət/","cefr":"B2","topic":"history","senses":[{"pos":"adj.","en":"Relating to the former Soviet Union or its governing councils.","vi":"thuộc Liên Xô cũ; thuộc các hội đồng Xô-viết"},{"pos":"n.","en":"A citizen of the former Soviet Union.","vi":"công dân Liên Xô cũ"}],"examples":[{"en":"My grandfather kept a Soviet camera in this drawer.","vi":"Ông tôi giữ một chiếc máy ảnh Liên Xô trong ngăn kéo này.","audioKind":"ex"},{"en":"Researchers study Soviet housing policies to understand how central planning influenced urban development and everyday life.","vi":"Các nhà nghiên cứu nghiên cứu các chính sách nhà ở của Liên Xô để hiểu cách quy hoạch tập trung ảnh hưởng đến sự phát triển đô thị và đời sống hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"Soviet Union","vi":"Liên Xô"},{"en":"Soviet era","vi":"thời kỳ Xô-viết"},{"en":"Soviet architecture","vi":"kiến trúc Liên Xô"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Soviet thường được viết hoa; chữ soviet viết thường có thể chỉ hội đồng Xô-viết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_59_1', 'en-b2-59', 'Cách dùng “fortress” (n.) — pháo đài; thành lũy; đồn lũy', 'a medieval fortress  ·  a heavily fortified fortress  ·  an island fortress', 'Chỉ các công trình phòng thủ kiên cố; trong khi castle nhấn mạnh vào kiến trúc lâu đài mang tính dinh thự hơn.', 'Họ từ (Word Family): fort (n.), fortify (v.), fortification (n.) | Đồng nghĩa: stronghold, citadel, fort', '[{"hanzi":"We climbed the hill to explore the old fortress.","pinyin":"","meaning":"Chúng tôi đã leo lên ngọn đồi để khám phá pháo đài cổ kính đó."},{"hanzi":"Restoring a historic fortress can attract visitors while preserving evidence of a region''s military past.","pinyin":"","meaning":"Việc trùng tu một pháo đài lịch sử có thể thu hút khách du lịch đồng thời bảo tồn những minh chứng về quá khứ quân sự của một vùng đất."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_59_2', 'en-b2-59', 'Cách dùng “spear” (n.) — cây lao; thương; giáo', 'wooden spear  ·  spear tip  ·  spear a piece of food', 'spear là lao hoặc giáo, không phải súng; động từ có thể chỉ hành động dùng vật nhọn xiên lấy thức ăn.', NULL, '[{"hanzi":"An ancient spear stood behind glass in the museum.","pinyin":"","meaning":"Một cây lao cổ được đặt đằng sau lớp kính trong viện bảo tàng."},{"hanzi":"The discovery of a wooden spear provides valuable evidence about the hunting techniques of early human communities.","pinyin":"","meaning":"Việc phát hiện ra một ngọn lao bằng gỗ cung cấp bằng chứng quý giá về kỹ thuật săn bắn của các cộng đồng người thời tiền sử."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_59_3', 'en-b2-59', 'Cách dùng “civilization” (n.) — xã hội văn minh; nền văn minh', 'ancient civilization  ·  the rise of civilization  ·  human civilization', 'Trong tiếng Anh Anh cũng có thể viết là civilisation; một nền văn minh cụ thể dùng là a civilization.', 'Họ từ (Word Family): civilize (v.), civilized (adj.)', '[{"hanzi":"We explored the ruins of an ancient civilization yesterday.","pinyin":"","meaning":"Hôm qua chúng tôi đã thám hiểm tàn tích của một nền văn minh cổ đại."},{"hanzi":"Reliable water supplies played a crucial role in the development of civilization by supporting agriculture and permanent settlements.","pinyin":"","meaning":"Nguồn nước ổn định đóng vai trò quyết định trong sự phát triển của nền văn minh nhờ hỗ trợ hoạt động nông nghiệp và các khu định cư cố định."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_59_4', 'en-b2-59', 'Cách dùng “armour” (n.) — áo giáp, vỏ giáp (bảo vệ)', 'a suit of armour  ·  body armour  ·  heavy armour', '"armour" là cách viết tiếng Anh-Anh, còn tiếng Anh-Mỹ là "armor"; thường là danh từ không đếm được.', 'Họ từ (Word Family): armoured (adj.)', '[{"hanzi":"The museum displayed a knight''s armour beside a wooden shield.","pinyin":"","meaning":"Bảo tàng trưng bày bộ giáp của một hiệp sĩ bên cạnh chiếc khiên bằng gỗ."},{"hanzi":"Surviving examples of medieval armour reveal how metalworking skills developed in response to changing military needs.","pinyin":"","meaning":"Những bộ áo giáp thời Trung cổ còn sót lại cho thấy kỹ năng chế tác kim loại đã phát triển như thế nào để đáp ứng các nhu cầu thay đổi trong quân sự."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_59_1', 'en-b2-59', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_59_1_1', 'ten_b2_59_1', 'armour', 'The museum displayed a knight''s armour beside a wooden shield.', 'The museum displayed a knight''s armour beside a wooden shield.', '/ˈɑːrmɚ/', 'Bảo tàng trưng bày bộ giáp của một hiệp sĩ bên cạnh chiếc khiên bằng gỗ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_59_1_2', 'ten_b2_59_1', 'lord', 'The guide showed us where the local lord once lived.', 'The guide showed us where the local lord once lived.', '/lɔːrd/', 'Hướng dẫn viên đã chỉ cho chúng tôi nơi vị lãnh chúa địa phương từng sinh sống.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_59_1_3', 'ten_b2_59_1', 'spear', 'An ancient spear stood behind glass in the museum.', 'An ancient spear stood behind glass in the museum.', '/spɪr/', 'Một cây lao cổ được đặt đằng sau lớp kính trong viện bảo tàng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_59_1_4', 'ten_b2_59_1', 'sword', 'An ancient sword lay inside the museum''s glass case.', 'An ancient sword lay inside the museum''s glass case.', '/sɔːrd/', 'Một thanh kiếm cổ nằm bên trong tủ kính của bảo tàng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_59_1_5', 'ten_b2_59_1', 'bronze', 'The small statue is made of solid bronze.', 'The small statue is made of solid bronze.', '/brɑːnz/', 'Bức tượng nhỏ được làm bằng đồng đặc.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_59_1_6', 'ten_b2_59_1', 'telegram', 'Grandmother kept the telegram announcing her brother''s safe arrival.', 'Grandmother kept the telegram announcing her brother''s safe arrival.', '/ˈtelɪɡræm/', 'Bà tôi vẫn giữ bức điện báo thông báo anh trai bà đã đến nơi an toàn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_59_1_7', 'ten_b2_59_1', 'fort', 'We climbed the hill to explore the old fort.', 'We climbed the hill to explore the old fort.', '/fɔːrt/', 'Chúng tôi leo lên đồi để khám phá pháo đài cổ.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_59_1_8', 'ten_b2_59_1', 'era', 'These old photographs remind us of a different era.', 'These old photographs remind us of a different era.', '/ˈɪrə/', 'Những bức ảnh cũ này gợi cho chúng ta nhớ về một thời kỳ khác.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_59_1_1', 'en-b2-59', 'ten_b2_59_1', 'listening', 'listening', 'The museum displayed a knight''s armour beside a wooden shield.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tường thành lâu đài từng bảo vệ dân làng khỏi những kẻ xâm lược.","Hôm qua chúng tôi đã thám hiểm tàn tích của một nền văn minh cổ đại.","Những bức ảnh cũ này gợi cho chúng ta nhớ về một thời kỳ khác.","Bảo tàng trưng bày bộ giáp của một hiệp sĩ bên cạnh chiếc khiên bằng gỗ."]'::jsonb, 3, 'The museum displayed a knight''s armour beside a wooden shield. → Bảo tàng trưng bày bộ giáp của một hiệp sĩ bên cạnh chiếc khiên bằng gỗ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_59_1_2', 'en-b2-59', 'ten_b2_59_1', 'listening', 'listening', 'The guide showed us where the local lord once lived.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một người tổ tiên của tôi đã xây dựng ngôi nhà đá cổ này.","Hướng dẫn viên đã chỉ cho chúng tôi nơi vị lãnh chúa địa phương từng sinh sống.","Một cây lao cổ được đặt đằng sau lớp kính trong viện bảo tàng.","Chúng tôi đã leo lên ngọn đồi để khám phá pháo đài cổ kính đó."]'::jsonb, 1, 'The guide showed us where the local lord once lived. → Hướng dẫn viên đã chỉ cho chúng tôi nơi vị lãnh chúa địa phương từng sinh sống.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_59_1_3', 'en-b2-59', 'ten_b2_59_1', 'listening', 'listening', 'An ancient spear stood behind glass in the museum.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hôm qua chúng tôi đã thám hiểm tàn tích của một nền văn minh cổ đại.","Một cây lao cổ được đặt đằng sau lớp kính trong viện bảo tàng.","Đồ ăn thừa sau buổi dã ngoại của chúng tôi đã làm đầy một chiếc túi nhỏ.","Binh lính đã đầu hàng và bước lên phía trước với đôi tay không."]'::jsonb, 1, 'An ancient spear stood behind glass in the museum. → Một cây lao cổ được đặt đằng sau lớp kính trong viện bảo tàng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_59_2', 'en-b2-59', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_59_2_1', 'ten_b2_59_2', 'armour', 'Surviving examples of medieval armour reveal how metalworking skills developed in response to changing military needs.', 'Surviving examples of medieval armour reveal how metalworking skills developed in response to changing military needs.', '/ˈɑːrmɚ/', 'Những bộ áo giáp thời Trung cổ còn sót lại cho thấy kỹ năng chế tác kim loại đã phát triển như thế nào để đáp ứng các nhu cầu thay đổi trong quân sự.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_59_2_2', 'ten_b2_59_2', 'lord', 'In medieval society, a lord often controlled farmland and collected payments from the people who worked it.', 'In medieval society, a lord often controlled farmland and collected payments from the people who worked it.', '/lɔːrd/', 'Trong xã hội trung cổ, lãnh chúa thường nắm quyền kiểm soát đất nông nghiệp và thu tiền từ những người làm thuê trên đất đó.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_59_2_3', 'ten_b2_59_2', 'spear', 'The discovery of a wooden spear provides valuable evidence about the hunting techniques of early human communities.', 'The discovery of a wooden spear provides valuable evidence about the hunting techniques of early human communities.', '/spɪr/', 'Việc phát hiện ra một ngọn lao bằng gỗ cung cấp bằng chứng quý giá về kỹ thuật săn bắn của các cộng đồng người thời tiền sử.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_59_2_4', 'ten_b2_59_2', 'sword', 'The discovery of a decorated sword provides evidence of advanced metalworking skills in this ancient society.', 'The discovery of a decorated sword provides evidence of advanced metalworking skills in this ancient society.', '/sɔːrd/', 'Việc phát hiện ra một thanh kiếm được trang trí tinh xảo cung cấp bằng chứng về kỹ năng gia công kim loại tiên tiến ở xã hội cổ đại này.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_59_2_5', 'ten_b2_59_2', 'bronze', 'Ancient tools made from bronze reveal how advances in metalworking transformed agriculture and trade across early societies.', 'Ancient tools made from bronze reveal how advances in metalworking transformed agriculture and trade across early societies.', '/brɑːnz/', 'Những công cụ cổ xưa làm bằng đồng thau cho thấy những tiến bộ trong kỹ nghệ chế tác kim loại đã làm thay đổi nông nghiệp và thương mại ở các xã hội thời kỳ đầu như thế nào.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_59_2_6', 'ten_b2_59_2', 'telegram', 'Before telephone services became widely available, sending a telegram was an important way to communicate urgent news.', 'Before telephone services became widely available, sending a telegram was an important way to communicate urgent news.', '/ˈtelɪɡræm/', 'Trước khi dịch vụ điện thoại trở nên phổ biến rộng rãi, gửi điện báo là một cách quan trọng để truyền đạt tin tức khẩn cấp.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_59_2_1', 'en-b2-59', 'ten_b2_59_2', 'listening', 'listening', 'Surviving examples of medieval armour reveal how metalworking skills developed in response to changing military needs.', NULL, 'Trong câu vừa nghe, từ “armour” mang nghĩa nào sau đây?', '["gặm cỏ; thả gia súc ăn cỏ","áo giáp, vỏ giáp (bảo vệ)","mang tính so sánh; đối chiếu","sự nhiệt tình; sự hăng hái"]'::jsonb, 1, '“armour” (/ˈɑːrmɚ/): áo giáp, vỏ giáp (bảo vệ). Câu đầy đủ: Surviving examples of medieval armour reveal how metalworking skills developed in response to changing military needs.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_59_2_2', 'en-b2-59', 'ten_b2_59_2', 'listening', 'listening', 'In medieval society, a lord often controlled farmland and collected payments from the people who worked it.', NULL, 'Trong câu vừa nghe, từ “lord” mang nghĩa nào sau đây?', '["làm mát lạnh; sảng khoái; tỉnh táo","hàng rào cây xanh; bụi cây rào","lãnh chúa; quý tộc","tự vệ; phòng vệ chính đáng"]'::jsonb, 2, '“lord” (/lɔːrd/): lãnh chúa; quý tộc. Câu đầy đủ: In medieval society, a lord often controlled farmland and collected payments from the people who worked it.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
