INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_59_2', 'en-b2-59', NULL, 'comprehensive_test', 'listening', 'The guide showed us where the local lord once lived.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Việc từ chối dọn dẹp phòng chính là hành vi phản kháng nhỏ của cậu bé.","Chúng tôi đã leo lên ngọn đồi để khám phá pháo đài cổ kính đó.","Hướng dẫn viên đã chỉ cho chúng tôi nơi vị lãnh chúa địa phương từng sinh sống.","Chúng tôi đã khám phá một lâu đài thời Trung cổ trong chuyến đi cuối tuần."]'::jsonb, 2, 'The guide showed us where the local lord once lived. → Hướng dẫn viên đã chỉ cho chúng tôi nơi vị lãnh chúa địa phương từng sinh sống.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_59_3', 'en-b2-59', NULL, 'comprehensive_test', 'listening', 'spear', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cây lao; thương; giáo","sự hiếu khách; lòng mến khách","nam châm","sự phân phát; sự phân phối"]'::jsonb, 0, 'spear (/spɪr/) → cây lao; thương; giáo; đâm bằng lao; xiên qua', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_59_4', 'en-b2-59', NULL, 'comprehensive_test', 'listening', 'An ancient sword lay inside the museum''s glass case.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hướng dẫn viên đã chỉ cho chúng tôi nơi vị lãnh chúa địa phương từng sinh sống.","Một thanh kiếm cổ nằm bên trong tủ kính của bảo tàng.","Bà tôi vẫn giữ bức điện báo thông báo anh trai bà đã đến nơi an toàn.","Binh lính đã đầu hàng và bước lên phía trước với đôi tay không."]'::jsonb, 1, 'An ancient sword lay inside the museum''s glass case. → Một thanh kiếm cổ nằm bên trong tủ kính của bảo tàng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_59_5', 'en-b2-59', NULL, 'comprehensive_test', 'listening', 'bronze', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["khoản quyên góp; khoản đóng góp; vật phẩm từ thiện","thu hút; làm say mê; giữ chân","đồng đỏ; đồng thau (hợp kim đồng và thiếc); đồng thiếc","thông tin đầu vào; nguồn lực đầu vào"]'::jsonb, 2, 'bronze (/brɑːnz/) → đồng đỏ; đồng thau (hợp kim đồng và thiếc); đồng thiếc; huy chương đồng; bằng đồng; có màu nâu đỏ của đồng', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_59_6', 'en-b2-59', NULL, 'comprehensive_test', 'listening', 'Grandmother kept the telegram announcing her brother''s safe arrival.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Việc từ chối dọn dẹp phòng chính là hành vi phản kháng nhỏ của cậu bé.","Bà tôi vẫn giữ bức điện báo thông báo anh trai bà đã đến nơi an toàn.","Tường thành lâu đài từng bảo vệ dân làng khỏi những kẻ xâm lược.","Nữ hoàng ngồi trên ngai vàng cạnh cửa sổ."]'::jsonb, 1, 'Grandmother kept the telegram announcing her brother''s safe arrival. → Bà tôi vẫn giữ bức điện báo thông báo anh trai bà đã đến nơi an toàn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_59_7', 'en-b2-59', NULL, 'comprehensive_test', 'listening', 'fort', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tính từ: nhẹ nhõm; yên tâm; thanh thản","ô che nắng; mái che nắng","sáng tác (nhạc); viết (văn bản)","pháo đài; đồn lũy; thành trì"]'::jsonb, 3, 'fort (/fɔːrt/) → pháo đài; đồn lũy; thành trì', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_59_8', 'en-b2-59', NULL, 'comprehensive_test', 'listening', 'These old photographs remind us of a different era.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một thanh kiếm cổ nằm bên trong tủ kính của bảo tàng.","Những bức ảnh cũ này gợi cho chúng ta nhớ về một thời kỳ khác.","Việc từ chối dọn dẹp phòng chính là hành vi phản kháng nhỏ của cậu bé.","Nữ hoàng ngồi trên ngai vàng cạnh cửa sổ."]'::jsonb, 1, 'These old photographs remind us of a different era. → Những bức ảnh cũ này gợi cho chúng ta nhớ về một thời kỳ khác.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_59_9', 'en-b2-59', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A brownish metal made mainly from copper and tin.”?', '["surrender","spear","remains","bronze"]'::jsonb, 3, 'bronze (/brɑːnz/) → đồng đỏ; đồng thau (hợp kim đồng và thiếc); đồng thiếc', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_59_10', 'en-b2-59', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a message sent by telegraph and delivered in written form”?', '["bronze","rebellion","telegram","armour"]'::jsonb, 2, 'telegram (/ˈtelɪɡræm/) → điện báo', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_59_11', 'en-b2-59', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A strong building or enclosed place built for military defence.”?', '["surrender","medieval","fort","rebellion"]'::jsonb, 2, 'fort (/fɔːrt/) → pháo đài; đồn lũy; thành trì', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_59_12', 'en-b2-59', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A period distinguished by particular events, developments, or ways of life.”?', '["era","spear","civilization","lord"]'::jsonb, 0, 'era (/ˈɪrə/) → thời đại; kỷ nguyên; giai đoạn lịch sử', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
