INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_59_18', 'en-b2-59', NULL, 'comprehensive_test', 'reading', NULL, 'Surviving examples of medieval armour reveal how metalworking skills developed in response to changing military needs.', 'Dựa vào câu trên, từ “armour” có nghĩa phù hợp nhất là gì?', '["khác nhau; thay đổi tùy theo hoàn cảnh","áo giáp, vỏ giáp (bảo vệ)","sự hỗn loạn; tình trạng lộn xộn","tuyên ngôn; lời tuyên bố; sự công bố"]'::jsonb, 1, 'armour: áo giáp, vỏ giáp (bảo vệ); lực lượng xe tăng, xe bọc thép. Dịch cả câu: Những bộ áo giáp thời Trung cổ còn sót lại cho thấy kỹ năng chế tác kim loại đã phát triển như thế nào để đáp ứng các nhu cầu thay đổi trong quân sự.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_59_19', 'en-b2-59', NULL, 'comprehensive_test', 'reading', NULL, 'In medieval society, a lord often controlled farmland and collected payments from the people who worked it.', 'Dựa vào câu trên, từ “lord” có nghĩa phù hợp nhất là gì?', '["lãnh chúa; quý tộc","theo nghĩa đen; nguyên văn","thính giác; khả năng nghe","khoản trợ cấp, tiền cấp phát từ một tổ chức cho mục đích cụ thể"]'::jsonb, 0, 'lord: lãnh chúa; quý tộc; Chúa; Đức Chúa Trời. Dịch cả câu: Trong xã hội trung cổ, lãnh chúa thường nắm quyền kiểm soát đất nông nghiệp và thu tiền từ những người làm thuê trên đất đó.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_59_20', 'en-b2-59', NULL, 'comprehensive_test', 'reading', NULL, 'The discovery of a wooden spear provides valuable evidence about the hunting techniques of early human communities.', 'Dựa vào câu trên, từ “spear” có nghĩa phù hợp nhất là gì?', '["đậu nành; sản phẩm từ đậu nành","dàn diễn viên; tập thể diễn viên","cây lao; thương; giáo","thuộc về tổ chức; thuộc cơ cấu tổ chức"]'::jsonb, 2, 'spear: cây lao; thương; giáo; đâm bằng lao; xiên qua. Dịch cả câu: Việc phát hiện ra một ngọn lao bằng gỗ cung cấp bằng chứng quý giá về kỹ thuật săn bắn của các cộng đồng người thời tiền sử.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_59_21', 'en-b2-59', NULL, 'comprehensive_test', 'reading', NULL, 'The discovery of a decorated sword provides evidence of advanced metalworking skills in this ancient society.', 'Dựa vào câu trên, từ “sword” có nghĩa phù hợp nhất là gì?', '["hộ gia đình; người trong nhà","mang tính so sánh; đối chiếu","thanh kiếm; đao","làm cho ổn định, giữ vững, trở nên vững vàng"]'::jsonb, 2, 'sword: thanh kiếm; đao. Dịch cả câu: Việc phát hiện ra một thanh kiếm được trang trí tinh xảo cung cấp bằng chứng về kỹ năng gia công kim loại tiên tiến ở xã hội cổ đại này.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_59_22', 'en-b2-59', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “phần còn lại; đồ thừa”', '["scholar","remains","abstract","canyon"]'::jsonb, 1, 'phần còn lại; đồ thừa → remains (/rɪˈmeɪnz/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_59_23', 'en-b2-59', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cuộc cách mạng; cuộc lật đổ chính quyền bằng vũ lực”', '["newly","unbearable","tiptoe","revolution"]'::jsonb, 3, 'cuộc cách mạng; cuộc lật đổ chính quyền bằng vũ lực → revolution (/ˌrevəˈluːʃən/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_59_24', 'en-b2-59', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thuộc Liên Xô cũ; thuộc các hội đồng Xô-viết”', '["contemporary","Soviet","drift","modest"]'::jsonb, 1, 'thuộc Liên Xô cũ; thuộc các hội đồng Xô-viết → Soviet (/ˈsoʊviət/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-60', 'en', 'Bài 60: Lịch sử & Văn hóa (2) - CEFR B2', 'CEFR B2', 'B2 · Lịch sử', '20 từ vựng Tiếng Anh CEFR B2 chủ đề lịch sử & văn hóa kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4060, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_antique', 'en-b2-60', 'antique', '/ænˈtiːk/', 'B2', 'đồ cổ; cổ vật; cổ; có giá trị cổ xưa', 'n.', NULL, NULL, 'Antique nhấn mạnh tính chất cổ xưa và có giá trị sưu tầm, không chỉ đơn thuần là cũ kỹ.', 'We found a beautiful antique in a small shop.', NULL, 'Chúng tôi tìm thấy một món đồ cổ rất đẹp ở một cửa hàng nhỏ.', '{"wordId":"antique","ukIpa":"/ænˈtiːk/","usIpa":"/ænˈtiːk/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"An old object valued for its age, beauty, or rarity","vi":"đồ cổ; cổ vật"},{"pos":"adj.","en":"Old and valuable because of age, beauty, or rarity","vi":"cổ; có giá trị cổ xưa"}],"examples":[{"en":"We found a beautiful antique in a small shop.","vi":"Chúng tôi tìm thấy một món đồ cổ rất đẹp ở một cửa hàng nhỏ.","audioKind":"ex"},{"en":"Preserving antique furniture helps future generations understand traditional craftsmanship and the everyday lives of people in the past.","vi":"Việc bảo tồn đồ nội thất cổ giúp thế hệ mai sau hiểu thêm về nghề thủ công truyền thống và đời sống thường nhật của người xưa.","audioKind":"ex2"}],"collocations":[{"en":"an antique shop","vi":"cửa hàng đồ cổ"},{"en":"antique furniture","vi":"đồ nội thất cổ"},{"en":"an antique dealer","vi":"thương buôn đồ cổ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Antique nhấn mạnh tính chất cổ xưa và có giá trị sưu tầm, không chỉ đơn thuần là cũ kỹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cannon', 'en-b2-60', 'cannon', '/ˈkænən/', 'B2', 'đại bác; hải pháo', 'n.', NULL, NULL, 'Dạng số nhiều có thể dùng cannon hoặc cannons; tránh nhầm lẫn với canon.', 'An old cannon stood beside the castle entrance.', NULL, 'Một khẩu đại bác cũ nằm ở cạnh lối vào lâu đài.', '{"wordId":"cannon","ukIpa":"/ˈkænən/","usIpa":"/ˈkænən/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"a large heavy gun that fires powerful projectiles","vi":"đại bác; hải pháo"}],"examples":[{"en":"An old cannon stood beside the castle entrance.","vi":"Một khẩu đại bác cũ nằm ở cạnh lối vào lâu đài.","audioKind":"ex"},{"en":"The introduction of cannon changed military architecture, encouraging the construction of thicker walls and lower defensive structures.","vi":"Sự xuất hiện của đại bác đã làm thay đổi kiến trúc quân sự, thúc đẩy việc xây dựng các bức tường thành dày hơn và các công trình phòng thủ thấp hơn.","audioKind":"ex2"}],"collocations":[{"en":"fire a cannon","vi":"bắn đại bác"},{"en":"cannon fire","vi":"hỏa lực đại bác"},{"en":"a cannon ball","vi":"đạn đại bác"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều có thể dùng cannon hoặc cannons; tránh nhầm lẫn với canon.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_knight', 'en-b2-60', 'knight', '/naɪt/', 'B2', 'hiệp sĩ; tước sĩ; hiệp sĩ (được phong tước); quân mã (trong cờ vua)', 'n.', 'knighthood (n.), knightly (adj.)', NULL, 'Chữ k không phát âm, đồng âm với night; tước hiệu hiệp sĩ thường dùng kèm Sir.', 'The painting shows a knight riding towards a castle.', NULL, 'Bức tranh vẽ một vị hiệp sĩ đang cưỡi ngựa phi về phía lâu đài.', '{"wordId":"knight","ukIpa":"/naɪt/","usIpa":"/naɪt/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"a medieval soldier of high rank who fought on horseback","vi":"hiệp sĩ"},{"pos":"n.","en":"a man awarded a title of honour by a monarch","vi":"tước sĩ; hiệp sĩ (được phong tước)"},{"pos":"n.","en":"a chess piece shaped like a horse''s head","vi":"quân mã (trong cờ vua)"}],"examples":[{"en":"The painting shows a knight riding towards a castle.","vi":"Bức tranh vẽ một vị hiệp sĩ đang cưỡi ngựa phi về phía lâu đài.","audioKind":"ex"},{"en":"Museum displays about the medieval knight can help students understand how warfare shaped European society.","vi":"Các cuộc trưng bày trong bảo tàng về hiệp sĩ trung cổ có thể giúp học sinh hiểu cách chiến tranh định hình xã hội châu Âu.","audioKind":"ex2"}],"collocations":[{"en":"medieval knight","vi":"hiệp sĩ trung cổ"},{"en":"knight in armour","vi":"hiệp sĩ mặc giáp"},{"en":"award a knighthood","vi":"phong tước hiệp sĩ"}],"wordFamily":["knighthood (n.)","knightly (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chữ k không phát âm, đồng âm với night; tước hiệu hiệp sĩ thường dùng kèm Sir.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_invade', 'en-b2-60', 'invade', '/ɪnˈveɪd/', 'B2', 'xâm lược; xâm chiếm; xâm phạm; xâm lấn; tràn vào; ùa vào', 'v.', 'invasion (n.), invader (n.), invasive (adj.)', NULL, 'Là ngoại động từ, đi thẳng theo sau là tân ngữ; danh từ tương ứng là invasion.', 'Ants invaded our kitchen after we left cake out.', NULL, 'Đám kiến đã tràn vào nhà bếp của chúng tôi sau khi chúng tôi để bánh ngọt ở bên ngoài.', '{"wordId":"invade","ukIpa":"/ɪnˈveɪd/","usIpa":"/ɪnˈveɪd/","cefr":"B2","topic":"history","senses":[{"pos":"v.","en":"To enter another country by force to take control","vi":"xâm lược; xâm chiếm"},{"pos":"v.","en":"To enter or affect someone''s private space without permission","vi":"xâm phạm; xâm lấn"},{"pos":"v.","en":"To arrive somewhere in large, often unwelcome groups","vi":"tràn vào; ùa vào"}],"examples":[{"en":"Ants invaded our kitchen after we left cake out.","vi":"Đám kiến đã tràn vào nhà bếp của chúng tôi sau khi chúng tôi để bánh ngọt ở bên ngoài.","audioKind":"ex"},{"en":"Some monitoring technologies can invade people''s privacy, even when they are introduced to improve public safety.","vi":"Một số công nghệ giám sát có thể xâm phạm quyền riêng tư của mọi người, ngay cả khi chúng được đưa ra nhằm cải thiện an toàn công cộng.","audioKind":"ex2"}],"collocations":[{"en":"invade a country","vi":"xâm lược một quốc gia"},{"en":"invade someone''s privacy","vi":"xâm phạm quyền riêng tư của ai đó"},{"en":"invade personal space","vi":"xâm phạm không gian cá nhân"}],"wordFamily":["invasion (n.)","invader (n.)","invasive (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Là ngoại động từ, đi thẳng theo sau là tân ngữ; danh từ tương ứng là invasion.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_primitive', 'en-b2-60', 'primitive', '/ˈprɪmətɪv/', 'B2', 'thô sơ; giản dị; thiếu các tiện nghi hiện đại; thuộc thời kỳ nguyên thủy; ban sơ', 'adj.', 'primitively (adv.)', 'Đồng nghĩa: rudimentary, basic · Trái nghĩa: advanced, sophisticated', 'Khi dùng cho cơ sở vật chất có nghĩa là thô sơ; dùng cho các dân tộc hoặc nền văn hóa đương đại có thể mang sắc thái miệt thị.', 'The campsite had only a primitive outdoor cooking area.', NULL, 'Khu cắm trại chỉ có một khu vực nấu ăn ngoài trời rất thô sơ.', '{"wordId":"primitive","ukIpa":"/ˈprɪmɪtɪv/","usIpa":"/ˈprɪmətɪv/","cefr":"B2","topic":"history","senses":[{"pos":"adj.","en":"Very basic, without advanced features or modern comforts.","vi":"thô sơ; giản dị; thiếu các tiện nghi hiện đại"},{"pos":"adj.","en":"Belonging to an early stage of development.","vi":"thuộc thời kỳ nguyên thủy; ban sơ"}],"examples":[{"en":"The campsite had only a primitive outdoor cooking area.","vi":"Khu cắm trại chỉ có một khu vực nấu ăn ngoài trời rất thô sơ.","audioKind":"ex"},{"en":"Although these tools appear primitive, they reveal considerable skill in selecting and shaping locally available materials.","vi":"Mặc dù những công cụ này trông có vẻ thô sơ, nhưng chúng cho thấy tay nghề tinh xảo trong việc lựa chọn và chế tác các vật liệu có sẵn tại địa phương.","audioKind":"ex2"}],"collocations":[{"en":"primitive tools","vi":"công cụ thô sơ"},{"en":"primitive conditions","vi":"điều kiện sơ khai"},{"en":"primitive life forms","vi":"dạng sống nguyên thủy"}],"wordFamily":["primitively (adv.)"],"synonyms":["rudimentary","basic"],"antonyms":["advanced","sophisticated"],"tipVi":"Khi dùng cho cơ sở vật chất có nghĩa là thô sơ; dùng cho các dân tộc hoặc nền văn hóa đương đại có thể mang sắc thái miệt thị.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reign', 'en-b2-60', 'reign', '/reɪn/', 'B2', 'thời gian trị vì; thời kỳ cầm quyền; trị vì; cai trị; thống trị; bao trùm; chiếm ưu thế', 'n.', 'reigning (adj.)', 'Đồng nghĩa: rule', 'Phát âm giống từ "rain"; "reign" có nghĩa là trị vì, trong khi "rein" có nghĩa là dây cương.', 'This castle was built during a young queen''s reign.', NULL, 'Lâu đài này được xây dựng trong thời gian trị vì của một vị nữ vương trẻ tuổi.', '{"wordId":"reign","ukIpa":"/reɪn/","usIpa":"/reɪn/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"the period when a king or queen rules","vi":"thời gian trị vì; thời kỳ cầm quyền"},{"pos":"v.","en":"to rule as a king or queen","vi":"trị vì; cai trị"},{"pos":"v.","en":"to be the strongest or most noticeable condition","vi":"thống trị; bao trùm; chiếm ưu thế"}],"examples":[{"en":"This castle was built during a young queen''s reign.","vi":"Lâu đài này được xây dựng trong thời gian trị vì của một vị nữ vương trẻ tuổi.","audioKind":"ex"},{"en":"During the king''s reign, investment in public libraries made education more accessible to ordinary citizens.","vi":"Dưới thời trị vì của nhà vua, việc đầu tư vào các thư viện công cộng đã giúp người dân bình thường dễ dàng tiếp cận giáo dục hơn.","audioKind":"ex2"}],"collocations":[{"en":"during the reign of","vi":"trong thời gian trị vì của"},{"en":"a long reign","vi":"một triều đại kéo dài"},{"en":"reign supreme","vi":"giữ vị trí độc tôn"},{"en":"chaos reigns","vi":"sự hỗn loạn bao trùm"}],"wordFamily":["reigning (adj.)"],"synonyms":["rule"],"antonyms":[],"tipVi":"Phát âm giống từ \"rain\"; \"reign\" có nghĩa là trị vì, trong khi \"rein\" có nghĩa là dây cương.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tomb', 'en-b2-60', 'tomb', '/tuːm/', 'B2', 'mồ mả; lăng mộ', 'n.', 'tombstone (n.)', NULL, 'Chữ b câm, vần với room; thường chỉ những ngôi mộ có cấu trúc kiến trúc.', 'We visited an ancient stone tomb outside the village.', NULL, 'Chúng tôi đã tham quan một ngôi mộ đá cổ nằm ở ngoài làng.', '{"wordId":"tomb","ukIpa":"/tuːm/","usIpa":"/tuːm/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"A structure or underground chamber where a dead person is buried.","vi":"mồ mả; lăng mộ"}],"examples":[{"en":"We visited an ancient stone tomb outside the village.","vi":"Chúng tôi đã tham quan một ngôi mộ đá cổ nằm ở ngoài làng.","audioKind":"ex"},{"en":"Objects discovered inside the royal tomb provide valuable evidence about ancient beliefs, craftsmanship, and social organisation.","vi":"Các cổ vật được khai quật bên trong lăng mộ hoàng gia cung cấp bằng chứng quý giá về tín ngưỡng, nghệ thuật thủ công và tổ chức xã hội thời cổ đại.","audioKind":"ex2"}],"collocations":[{"en":"ancient tomb","vi":"mộ cổ"},{"en":"royal tomb","vi":"lăng mộ hoàng gia"},{"en":"burial tomb","vi":"hầm mộ"}],"wordFamily":["tombstone (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chữ b câm, vần với room; thường chỉ những ngôi mộ có cấu trúc kiến trúc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_kingdom', 'en-b2-60', 'kingdom', '/ˈkɪŋdəm/', 'B2', 'vương quốc; giới (trong sinh học)', 'n.', 'king (n.), kingship (n.)', NULL, 'Trong bối cảnh chính trị, từ này chỉ vương quốc; trong khoa học, animal kingdom chỉ giới động vật.', 'The old castle once guarded the entrance to the kingdom.', NULL, 'Lâu đài cổ từng canh giữ lối vào của cả vương quốc.', '{"wordId":"kingdom","ukIpa":"/ˈkɪŋdəm/","usIpa":"/ˈkɪŋdəm/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"a country ruled by a king or queen","vi":"vương quốc"},{"pos":"n.","en":"one of the largest groups used to classify living things","vi":"giới (trong sinh học)"}],"examples":[{"en":"The old castle once guarded the entrance to the kingdom.","vi":"Lâu đài cổ từng canh giữ lối vào của cả vương quốc.","audioKind":"ex"},{"en":"Tourism in the small kingdom provides employment, but increasing visitor numbers place pressure on historic buildings.","vi":"Ngành du lịch tại vương quốc nhỏ bé này tạo ra việc làm, nhưng lượng du khách ngày càng tăng cũng gây áp lực lớn lên các công trình lịch sử.","audioKind":"ex2"}],"collocations":[{"en":"animal kingdom","vi":"giới động vật"},{"en":"plant kingdom","vi":"giới thực vật"},{"en":"rule a kingdom","vi":"cai trị vương quốc"}],"wordFamily":["king (n.)","kingship (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong bối cảnh chính trị, từ này chỉ vương quốc; trong khoa học, animal kingdom chỉ giới động vật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conquer', 'en-b2-60', 'conquer', '/ˈkɑːŋkər/', 'B2', 'chinh phục; chiếm đóng; khắc phục; vượt qua', 'v.', 'conqueror (n.), conquest (n.)', 'Đồng nghĩa: overcome, subdue · Trái nghĩa: surrender', 'Là ngoại động từ, đi thẳng với tân ngữ: conquer a fear.', 'She conquered her fear and climbed onto the diving board.', NULL, 'Cô ấy đã vượt qua nỗi sợ hãi và bước lên ván nhảy.', '{"wordId":"conquer","ukIpa":"/ˈkɒŋkə/","usIpa":"/ˈkɑːŋkər/","cefr":"B2","topic":"history","senses":[{"pos":"v.","en":"Take control of a country or place by force.","vi":"chinh phục; chiếm đóng"},{"pos":"v.","en":"Successfully deal with a fear, difficulty, or challenge.","vi":"khắc phục; vượt qua"}],"examples":[{"en":"She conquered her fear and climbed onto the diving board.","vi":"Cô ấy đã vượt qua nỗi sợ hãi và bước lên ván nhảy.","audioKind":"ex"},{"en":"Throughout history, powerful states have sought to conquer neighbouring territories to gain resources and expand their influence.","vi":"Xuyên suốt lịch sử, các quốc gia hùng mạnh đã tìm cách chinh phục các vùng lãnh thổ láng giềng để giành lấy tài nguyên và mở rộng ảnh hưởng.","audioKind":"ex2"}],"collocations":[{"en":"conquer a territory","vi":"chinh phục một vùng lãnh thổ"},{"en":"conquer a fear","vi":"vượt qua nỗi sợ"},{"en":"conquer a mountain","vi":"chinh phục một ngọn núi"}],"wordFamily":["conqueror (n.)","conquest (n.)"],"synonyms":["overcome","subdue"],"antonyms":["surrender"],"tipVi":"Là ngoại động từ, đi thẳng với tân ngữ: conquer a fear.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_slavery', 'en-b2-60', 'slavery', '/ˈsleɪvəri/', 'B2', 'chế độ nô lệ; tình trạng nô lệ', 'n.', 'slave (n.), enslave (v.), enslavement (n.)', 'Đồng nghĩa: enslavement, bondage · Trái nghĩa: freedom', 'Slavery là danh từ không đếm được; cụm abolish slavery có nghĩa là bãi bỏ chế độ nô lệ.', 'We learned about slavery during our museum visit yesterday.', NULL, 'Chúng tôi đã tìm hiểu về chế độ nô lệ trong chuyến tham quan bảo tàng ngày hôm qua.', '{"wordId":"slavery","ukIpa":"/ˈsleɪvəri/","usIpa":"/ˈsleɪvəri/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"a system where people are owned and forced to work","vi":"chế độ nô lệ; tình trạng nô lệ"}],"examples":[{"en":"We learned about slavery during our museum visit yesterday.","vi":"Chúng tôi đã tìm hiểu về chế độ nô lệ trong chuyến tham quan bảo tàng ngày hôm qua.","audioKind":"ex"},{"en":"Although slavery has been legally abolished worldwide, forced labour remains a serious challenge for governments and international organisations.","vi":"Mặc dù chế độ nô lệ đã được pháp luật bãi bỏ trên toàn thế giới, lao động cưỡng bức vẫn là một thách thức nghiêm trọng đối với các chính phủ và tổ chức quốc tế.","audioKind":"ex2"}],"collocations":[{"en":"abolish slavery","vi":"bãi bỏ chế độ nô lệ"},{"en":"modern slavery","vi":"nô lệ thời hiện đại"},{"en":"the abolition of slavery","vi":"việc xóa bỏ chế độ nô lệ"}],"wordFamily":["slave (n.)","enslave (v.)","enslavement (n.)"],"synonyms":["enslavement","bondage"],"antonyms":["freedom"],"tipVi":"Slavery là danh từ không đếm được; cụm abolish slavery có nghĩa là bãi bỏ chế độ nô lệ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_goddess', 'en-b2-60', 'goddess', '/ˈɡɑːdəs/', 'B2', 'nữ thần; vị nữ thần', 'n.', 'god (n.), godlike (adj.)', 'Đồng nghĩa: female deity', 'goddess chỉ nữ thần, tương ứng với nam thần thường dùng god.', 'The museum displayed a stone statue of a goddess.', NULL, 'Bảo tàng trưng bày bức tượng đá của một nữ thần.', '{"wordId":"goddess","ukIpa":"/ˈɡɒdes/","usIpa":"/ˈɡɑːdəs/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"A female deity worshipped in a religion or described in mythology.","vi":"nữ thần; vị nữ thần"}],"examples":[{"en":"The museum displayed a stone statue of a goddess.","vi":"Bảo tàng trưng bày bức tượng đá của một nữ thần.","audioKind":"ex"},{"en":"Ancient sculptures of a harvest goddess reveal how closely religious beliefs were connected to agriculture.","vi":"Các tác phẩm điêu khắc cổ về một vị nữ thần mùa màng cho thấy tín điều tôn giáo gắn kết chặt chẽ thế nào với nông nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"goddess of wisdom","vi":"nữ thần trí tuệ"},{"en":"harvest goddess","vi":"nữ thần mùa màng"},{"en":"worship a goddess","vi":"thờ phụng nữ thần"}],"wordFamily":["god (n.)","godlike (adj.)"],"synonyms":["female deity"],"antonyms":[],"tipVi":"goddess chỉ nữ thần, tương ứng với nam thần thường dùng god.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_slave', 'en-b2-60', 'slave', '/sleɪv/', 'B2', 'nô lệ; người bị bắt làm nô lệ; làm lụng vất vả; cày cuốc cực nhọc', 'n.', 'slavery (n.), enslave (v.), enslavement (n.)', NULL, 'Trong ngữ cảnh lịch sử, có thể dùng enslaved person để nhấn mạnh tư cách con người của họ.', 'The museum tells the story of a slave who escaped.', NULL, 'Viện bảo tàng kể câu chuyện về một người nô lệ đã trốn thoát.', '{"wordId":"slave","ukIpa":"/sleɪv/","usIpa":"/sleɪv/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"a person owned by another and forced to work","vi":"nô lệ; người bị bắt làm nô lệ"},{"pos":"v.","en":"to work extremely hard for a long time","vi":"làm lụng vất vả; cày cuốc cực nhọc"}],"examples":[{"en":"The museum tells the story of a slave who escaped.","vi":"Viện bảo tàng kể câu chuyện về một người nô lệ đã trốn thoát.","audioKind":"ex"},{"en":"Studying the experiences of slaves helps students understand the human consequences of historical systems of exploitation.","vi":"Việc nghiên cứu trải nghiệm của những người nô lệ giúp học sinh hiểu được hậu quả nhân đạo từ các hệ thống bóc lột trong lịch sử.","audioKind":"ex2"}],"collocations":[{"en":"the slave trade","vi":"buôn bán nô lệ"},{"en":"free slaves","vi":"giải phóng nô lệ"},{"en":"slave away","vi":"làm việc quần quật"}],"wordFamily":["slavery (n.)","enslave (v.)","enslavement (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong ngữ cảnh lịch sử, có thể dùng enslaved person để nhấn mạnh tư cách con người của họ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_archaeology', 'en-b2-60', 'archaeology', '/ˌɑːrkiˈɑːlədʒi/', 'B2', 'khảo cổ học', 'n.', 'archaeologist (n.), archaeological (adj.)', NULL, 'Thường là danh từ không đếm được; việc nghiên cứu hóa thạch khủng long thuộc ngành cổ sinh vật học.', 'Studying archaeology taught her to recognise ancient pottery fragments.', NULL, 'Việc học khảo cổ học đã dạy cô ấy cách nhận biết các mảnh gốm cổ.', '{"wordId":"archaeology","ukIpa":"/ˌɑːkiˈɒlədʒi/","usIpa":"/ˌɑːrkiˈɑːlədʒi/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"The study of past societies through objects and remains.","vi":"khảo cổ học"}],"examples":[{"en":"Studying archaeology taught her to recognise ancient pottery fragments.","vi":"Việc học khảo cổ học đã dạy cô ấy cách nhận biết các mảnh gốm cổ.","audioKind":"ex"},{"en":"Archaeology provides valuable evidence of how earlier societies adapted to environmental change and developed trading networks.","vi":"Khảo cổ học cung cấp những bằng chứng quý giá về cách các xã hội thời xưa thích nghi với sự thay đổi của môi trường và phát triển mạng lưới thương mại.","audioKind":"ex2"}],"collocations":[{"en":"study archaeology","vi":"nghiên cứu khảo cổ học"},{"en":"an archaeology degree","vi":"bằng cử nhân khảo cổ học"},{"en":"an archaeology museum","vi":"viện bảo tàng khảo cổ học"}],"wordFamily":["archaeologist (n.)","archaeological (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; việc nghiên cứu hóa thạch khủng long thuộc ngành cổ sinh vật học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rifle', 'en-b2-60', 'rifle', '/ˈraɪfəl/', 'B2', 'súng trường; lục lọi; tìm kiếm nhanh', 'n.', 'rifling (n.)', NULL, 'Khi dùng làm động từ, thường đi với cấu trúc rifle through để chỉ hành động lục lọi vội vã.', 'An old rifle stood inside the museum''s glass cabinet.', NULL, 'Một khẩu súng trường cũ được đặt bên trong tủ kính của bảo tàng.', '{"wordId":"rifle","ukIpa":"/ˈraɪfəl/","usIpa":"/ˈraɪfəl/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"A long gun held against the shoulder when fired.","vi":"súng trường"},{"pos":"v.","en":"To search through things quickly, often leaving them untidy.","vi":"lục lọi; tìm kiếm nhanh"}],"examples":[{"en":"An old rifle stood inside the museum''s glass cabinet.","vi":"Một khẩu súng trường cũ được đặt bên trong tủ kính của bảo tàng.","audioKind":"ex"},{"en":"The museum displays a nineteenth-century rifle to illustrate how industrial advances transformed military equipment.","vi":"Bảo tàng trưng bày một khẩu súng trường thế kỷ XIX để minh họa cách các tiến bộ công nghiệp đã biến đổi trang thiết bị quân sự.","audioKind":"ex2"}],"collocations":[{"en":"a hunting rifle","vi":"súng săn"},{"en":"a rifle barrel","vi":"nòng súng trường"},{"en":"rifle through drawers","vi":"lục lọi ngăn kéo"}],"wordFamily":["rifling (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi dùng làm động từ, thường đi với cấu trúc rifle through để chỉ hành động lục lọi vội vã.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_heritage', 'en-b2-60', 'heritage', '/ˈherɪtɪdʒ/', 'B2', 'di sản; truyền thống; giá trị truyền lại', 'n.', NULL, 'Đồng nghĩa: legacy', 'Thường chỉ di sản văn hóa và lịch sử; tài sản thừa kế cá nhân thường dùng inheritance.', 'These old songs are part of our family heritage.', NULL, 'Những bài hát cổ này là một phần trong di sản gia đình chúng ta.', '{"wordId":"heritage","ukIpa":"/ˈherɪtɪdʒ/","usIpa":"/ˈherɪtɪdʒ/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"Traditions, buildings, and values passed down from earlier generations.","vi":"di sản; truyền thống; giá trị truyền lại"}],"examples":[{"en":"These old songs are part of our family heritage.","vi":"Những bài hát cổ này là một phần trong di sản gia đình chúng ta.","audioKind":"ex"},{"en":"Protecting cultural heritage can strengthen community identity while attracting visitors who support local businesses.","vi":"Bảo vệ di sản văn hóa có thể củng cố bản sắc cộng đồng đồng thời thu hút du khách ủng hộ các doanh nghiệp địa phương.","audioKind":"ex2"}],"collocations":[{"en":"cultural heritage","vi":"di sản văn hóa"},{"en":"preserve our heritage","vi":"bảo tồn di sản của chúng ta"},{"en":"heritage site","vi":"khu di sản"},{"en":"rich heritage","vi":"di sản phong phú"}],"wordFamily":[],"synonyms":["legacy"],"antonyms":[],"tipVi":"Thường chỉ di sản văn hóa và lịch sử; tài sản thừa kế cá nhân thường dùng inheritance.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_warrior', 'en-b2-60', 'warrior', '/ˈwɔːriər/', 'B2', 'chiến binh; dũng sĩ', 'n.', 'war (n.)', 'Đồng nghĩa: fighter, soldier', 'Thường dùng cho chiến binh cổ đại; quân nhân hiện đại thường dùng soldier.', 'The museum displayed armour worn by an ancient warrior.', NULL, 'Viện bảo tàng trưng bày bộ áo giáp do một chiến binh cổ đại mặc.', '{"wordId":"warrior","ukIpa":"/ˈwɒriə/","usIpa":"/ˈwɔːriər/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"A person experienced in fighting, especially in the past.","vi":"chiến binh; dũng sĩ"}],"examples":[{"en":"The museum displayed armour worn by an ancient warrior.","vi":"Viện bảo tàng trưng bày bộ áo giáp do một chiến binh cổ đại mặc.","audioKind":"ex"},{"en":"Traditional stories about warriors can reveal how past societies understood courage, loyalty, and leadership.","vi":"Những câu chuyện truyền thống về các chiến binh có thể tiết lộ cách các xã hội trong quá khứ hiểu về lòng dũng cảm, sự trung thành và tinh thần lãnh đạo.","audioKind":"ex2"}],"collocations":[{"en":"ancient warrior","vi":"chiến binh cổ đại"},{"en":"brave warrior","vi":"chiến binh dũng cảm"},{"en":"warrior culture","vi":"văn hóa chiến binh"}],"wordFamily":["war (n.)"],"synonyms":["fighter","soldier"],"antonyms":[],"tipVi":"Thường dùng cho chiến binh cổ đại; quân nhân hiện đại thường dùng soldier.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_colony', 'en-b2-60', 'colony', '/ˈkɑːləni/', 'B2', 'thuộc địa; bầy đàn; quần thể sinh vật', 'n.', 'colonial (adj.), colonise (v.), colonisation (n.), colonist (n.)', NULL, 'Có thể dùng để chỉ vùng đất thuộc địa hoặc chỉ đàn động vật, loài vật sống bầy đàn hoặc khuẩn lạc.', 'The island was once a colony of a distant kingdom.', NULL, 'Hòn đảo này từng là thuộc địa của một vương quốc xa xôi.', '{"wordId":"colony","ukIpa":"/ˈkɒləni/","usIpa":"/ˈkɑːləni/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"a territory governed by another country","vi":"thuộc địa"},{"pos":"n.","en":"a group of animals or microorganisms living together","vi":"bầy đàn; quần thể sinh vật"}],"examples":[{"en":"The island was once a colony of a distant kingdom.","vi":"Hòn đảo này từng là thuộc địa của một vương quốc xa xôi.","audioKind":"ex"},{"en":"Historical records reveal how trade policies shaped the economy of the colony over several decades.","vi":"Các tài liệu lịch sử tiết lộ các chính sách thương mại đã định hình nền kinh tế của thuộc địa đó như thế nào trong suốt nhiều thập kỷ.","audioKind":"ex2"}],"collocations":[{"en":"a former colony","vi":"một cựu thuộc địa"},{"en":"an ant colony","vi":"một đàn kiến"},{"en":"a breeding colony","vi":"một quần thể sinh sản"}],"wordFamily":["colonial (adj.)","colonise (v.)","colonisation (n.)","colonist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể dùng để chỉ vùng đất thuộc địa hoặc chỉ đàn động vật, loài vật sống bầy đàn hoặc khuẩn lạc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_preservation', 'en-b2-60', 'preservation', '/ˌprezərˈveɪʃən/', 'B2', 'sự bảo tồn; sự giữ gìn; sự bảo vệ; sự bảo quản (thực phẩm)', 'n.', 'preserve (v.), preservative (n.), preserved (adj.)', 'Đồng nghĩa: protection, conservation · Trái nghĩa: destruction', 'Thường là danh từ không đếm được; theo sau bởi the preservation of cộng với đối tượng cần bảo tồn.', 'These old photographs need careful preservation to prevent further damage.', NULL, 'Những bức ảnh cũ này cần được bảo quản cẩn thận để tránh hư hỏng thêm.', '{"wordId":"preservation","ukIpa":"/ˌprezəˈveɪʃən/","usIpa":"/ˌprezərˈveɪʃən/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"The act of keeping something safe from damage or loss.","vi":"sự bảo tồn; sự giữ gìn; sự bảo vệ"},{"pos":"n.","en":"The process of treating food to prevent it from spoiling.","vi":"sự bảo quản (thực phẩm)"}],"examples":[{"en":"These old photographs need careful preservation to prevent further damage.","vi":"Những bức ảnh cũ này cần được bảo quản cẩn thận để tránh hư hỏng thêm.","audioKind":"ex"},{"en":"The preservation of historic buildings can strengthen local identity while attracting visitors and supporting small businesses.","vi":"Việc bảo tồn các tòa nhà lịch sử có thể củng cố bản sắc địa phương đồng thời thu hút du khách và hỗ trợ các tiểu thương.","audioKind":"ex2"}],"collocations":[{"en":"heritage preservation","vi":"bảo tồn di sản"},{"en":"food preservation","vi":"bảo quản thực phẩm"},{"en":"a state of preservation","vi":"tình trạng bảo quản"}],"wordFamily":["preserve (v.)","preservative (n.)","preserved (adj.)"],"synonyms":["protection","conservation"],"antonyms":["destruction"],"tipVi":"Thường là danh từ không đếm được; theo sau bởi the preservation of cộng với đối tượng cần bảo tồn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_emperor', 'en-b2-60', 'emperor', '/ˈempərər/', 'B2', 'hoàng đế; vị vua cai trị đế quốc', 'n.', 'empire (n.), empress (n.), imperial (adj.)', NULL, 'emperor cai trị empire; empress chỉ nữ hoàng hoặc hoàng hậu.', 'The museum displays a robe once worn by an emperor.', NULL, 'Bảo tàng đang trưng bày một chiếc áo choàng từng được một vị hoàng đế mặc.', '{"wordId":"emperor","ukIpa":"/ˈempərə/","usIpa":"/ˈempərər/","cefr":"B2","topic":"history","senses":[{"pos":"n.","en":"A male ruler of an empire.","vi":"hoàng đế; vị vua cai trị đế quốc"}],"examples":[{"en":"The museum displays a robe once worn by an emperor.","vi":"Bảo tàng đang trưng bày một chiếc áo choàng từng được một vị hoàng đế mặc.","audioKind":"ex"},{"en":"The emperor expanded trade routes, allowing goods and cultural practices to spread across the empire.","vi":"Vị hoàng đế này đã mở rộng các tuyến đường thương mại, giúp hàng hóa và các tập tục văn hóa lan rộng khắp đế quốc.","audioKind":"ex2"}],"collocations":[{"en":"a Roman emperor","vi":"một vị hoàng đế La Mã"},{"en":"the reigning emperor","vi":"vị hoàng đế đang trị vì"},{"en":"crown someone emperor","vi":"lên ngôi hoàng đế"}],"wordFamily":["empire (n.)","empress (n.)","imperial (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"emperor cai trị empire; empress chỉ nữ hoàng hoặc hoàng hậu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_glorious', 'en-b2-60', 'glorious', '/ˈɡlɔːriəs/', 'B2', 'vẻ vang, huy hoàng, đáng tự hào; tuyệt đẹp, rực rỡ, dễ chịu', 'adj.', 'glory (n.), gloriously (adv.), glorify (v.)', 'Đồng nghĩa: splendid, magnificent · Trái nghĩa: inglorious', 'glorious vừa có thể chỉ sự vinh quang, vừa có thể ca ngợi thời tiết hoặc phong cảnh.', 'We spent a glorious afternoon swimming in the lake.', NULL, 'Chúng tôi đã trải qua một buổi chiều tuyệt vời bơi lội trong hồ.', '{"wordId":"glorious","ukIpa":"/ˈɡlɔːriəs/","usIpa":"/ˈɡlɔːriəs/","cefr":"B2","topic":"history","senses":[{"pos":"adj.","en":"Deserving great admiration or bringing honour and pride.","vi":"vẻ vang, huy hoàng, đáng tự hào"},{"pos":"adj.","en":"Extremely beautiful, enjoyable, or pleasant.","vi":"tuyệt đẹp, rực rỡ, dễ chịu"}],"examples":[{"en":"We spent a glorious afternoon swimming in the lake.","vi":"Chúng tôi đã trải qua một buổi chiều tuyệt vời bơi lội trong hồ.","audioKind":"ex"},{"en":"Museums should examine difficult historical events as carefully as they celebrate a nation''s glorious achievements.","vi":"Các bảo tàng nên xem xét kỹ lưỡng các sự kiện lịch sử khó khăn giống như cách họ ca ngợi những thành tựu huy hoàng của một quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"glorious victory","vi":"chiến thắng huy hoàng"},{"en":"glorious sunshine","vi":"ánh nắng rực rỡ"},{"en":"glorious past","vi":"quá khứ hào hùng"}],"wordFamily":["glory (n.)","gloriously (adv.)","glorify (v.)"],"synonyms":["splendid","magnificent"],"antonyms":["inglorious"],"tipVi":"glorious vừa có thể chỉ sự vinh quang, vừa có thể ca ngợi thời tiết hoặc phong cảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_60_1', 'en-b2-60', 'Cách dùng “primitive” (adj.) — thô sơ; giản dị; thiếu các tiện nghi hiện đại', 'primitive tools  ·  primitive conditions  ·  primitive life forms', 'Khi dùng cho cơ sở vật chất có nghĩa là thô sơ; dùng cho các dân tộc hoặc nền văn hóa đương đại có thể mang sắc thái miệt thị.', 'Họ từ (Word Family): primitively (adv.) | Đồng nghĩa: rudimentary, basic · Trái nghĩa: advanced, sophisticated', '[{"hanzi":"The campsite had only a primitive outdoor cooking area.","pinyin":"","meaning":"Khu cắm trại chỉ có một khu vực nấu ăn ngoài trời rất thô sơ."},{"hanzi":"Although these tools appear primitive, they reveal considerable skill in selecting and shaping locally available materials.","pinyin":"","meaning":"Mặc dù những công cụ này trông có vẻ thô sơ, nhưng chúng cho thấy tay nghề tinh xảo trong việc lựa chọn và chế tác các vật liệu có sẵn tại địa phương."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_60_2', 'en-b2-60', 'Cách dùng “archaeology” (n.) — khảo cổ học', 'study archaeology  ·  an archaeology degree  ·  an archaeology museum', 'Thường là danh từ không đếm được; việc nghiên cứu hóa thạch khủng long thuộc ngành cổ sinh vật học.', 'Họ từ (Word Family): archaeologist (n.), archaeological (adj.)', '[{"hanzi":"Studying archaeology taught her to recognise ancient pottery fragments.","pinyin":"","meaning":"Việc học khảo cổ học đã dạy cô ấy cách nhận biết các mảnh gốm cổ."},{"hanzi":"Archaeology provides valuable evidence of how earlier societies adapted to environmental change and developed trading networks.","pinyin":"","meaning":"Khảo cổ học cung cấp những bằng chứng quý giá về cách các xã hội thời xưa thích nghi với sự thay đổi của môi trường và phát triển mạng lưới thương mại."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_60_3', 'en-b2-60', 'Cách dùng “kingdom” (n.) — vương quốc', 'animal kingdom  ·  plant kingdom  ·  rule a kingdom', 'Trong bối cảnh chính trị, từ này chỉ vương quốc; trong khoa học, animal kingdom chỉ giới động vật.', 'Họ từ (Word Family): king (n.), kingship (n.)', '[{"hanzi":"The old castle once guarded the entrance to the kingdom.","pinyin":"","meaning":"Lâu đài cổ từng canh giữ lối vào của cả vương quốc."},{"hanzi":"Tourism in the small kingdom provides employment, but increasing visitor numbers place pressure on historic buildings.","pinyin":"","meaning":"Ngành du lịch tại vương quốc nhỏ bé này tạo ra việc làm, nhưng lượng du khách ngày càng tăng cũng gây áp lực lớn lên các công trình lịch sử."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_60_4', 'en-b2-60', 'Cách dùng “colony” (n.) — thuộc địa', 'a former colony  ·  an ant colony  ·  a breeding colony', 'Có thể dùng để chỉ vùng đất thuộc địa hoặc chỉ đàn động vật, loài vật sống bầy đàn hoặc khuẩn lạc.', 'Họ từ (Word Family): colonial (adj.), colonise (v.), colonisation (n.), colonist (n.)', '[{"hanzi":"The island was once a colony of a distant kingdom.","pinyin":"","meaning":"Hòn đảo này từng là thuộc địa của một vương quốc xa xôi."},{"hanzi":"Historical records reveal how trade policies shaped the economy of the colony over several decades.","pinyin":"","meaning":"Các tài liệu lịch sử tiết lộ các chính sách thương mại đã định hình nền kinh tế của thuộc địa đó như thế nào trong suốt nhiều thập kỷ."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_60_1', 'en-b2-60', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
