INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_60_1_3', 'ten_b2_60_1', 'knight', 'The painting shows a knight riding towards a castle.', 'The painting shows a knight riding towards a castle.', '/naɪt/', 'Bức tranh vẽ một vị hiệp sĩ đang cưỡi ngựa phi về phía lâu đài.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_60_1_4', 'ten_b2_60_1', 'invade', 'Ants invaded our kitchen after we left cake out.', 'Ants invaded our kitchen after we left cake out.', '/ɪnˈveɪd/', 'Đám kiến đã tràn vào nhà bếp của chúng tôi sau khi chúng tôi để bánh ngọt ở bên ngoài.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_60_1_5', 'ten_b2_60_1', 'primitive', 'The campsite had only a primitive outdoor cooking area.', 'The campsite had only a primitive outdoor cooking area.', '/ˈprɪmətɪv/', 'Khu cắm trại chỉ có một khu vực nấu ăn ngoài trời rất thô sơ.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_60_1_6', 'ten_b2_60_1', 'reign', 'This castle was built during a young queen''s reign.', 'This castle was built during a young queen''s reign.', '/reɪn/', 'Lâu đài này được xây dựng trong thời gian trị vì của một vị nữ vương trẻ tuổi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_60_1_7', 'ten_b2_60_1', 'tomb', 'We visited an ancient stone tomb outside the village.', 'We visited an ancient stone tomb outside the village.', '/tuːm/', 'Chúng tôi đã tham quan một ngôi mộ đá cổ nằm ở ngoài làng.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_60_1_8', 'ten_b2_60_1', 'kingdom', 'The old castle once guarded the entrance to the kingdom.', 'The old castle once guarded the entrance to the kingdom.', '/ˈkɪŋdəm/', 'Lâu đài cổ từng canh giữ lối vào của cả vương quốc.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_60_1_1', 'en-b2-60', 'ten_b2_60_1', 'listening', 'listening', 'We found a beautiful antique in a small shop.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi tìm thấy một món đồ cổ rất đẹp ở một cửa hàng nhỏ.","Viện bảo tàng trưng bày bộ áo giáp do một chiến binh cổ đại mặc.","Lâu đài cổ từng canh giữ lối vào của cả vương quốc.","Bức tranh vẽ một vị hiệp sĩ đang cưỡi ngựa phi về phía lâu đài."]'::jsonb, 0, 'We found a beautiful antique in a small shop. → Chúng tôi tìm thấy một món đồ cổ rất đẹp ở một cửa hàng nhỏ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_60_1_2', 'en-b2-60', 'ten_b2_60_1', 'listening', 'listening', 'An old cannon stood beside the castle entrance.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi tìm thấy một món đồ cổ rất đẹp ở một cửa hàng nhỏ.","Lâu đài này được xây dựng trong thời gian trị vì của một vị nữ vương trẻ tuổi.","Khu cắm trại chỉ có một khu vực nấu ăn ngoài trời rất thô sơ.","Một khẩu đại bác cũ nằm ở cạnh lối vào lâu đài."]'::jsonb, 3, 'An old cannon stood beside the castle entrance. → Một khẩu đại bác cũ nằm ở cạnh lối vào lâu đài.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_60_1_3', 'en-b2-60', 'ten_b2_60_1', 'listening', 'listening', 'The painting shows a knight riding towards a castle.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bức tranh vẽ một vị hiệp sĩ đang cưỡi ngựa phi về phía lâu đài.","Chúng tôi đã tham quan một ngôi mộ đá cổ nằm ở ngoài làng.","Viện bảo tàng kể câu chuyện về một người nô lệ đã trốn thoát.","Chúng tôi tìm thấy một món đồ cổ rất đẹp ở một cửa hàng nhỏ."]'::jsonb, 0, 'The painting shows a knight riding towards a castle. → Bức tranh vẽ một vị hiệp sĩ đang cưỡi ngựa phi về phía lâu đài.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_60_2', 'en-b2-60', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_60_2_1', 'ten_b2_60_2', 'antique', 'Preserving antique furniture helps future generations understand traditional craftsmanship and the everyday lives of people in the past.', 'Preserving antique furniture helps future generations understand traditional craftsmanship and the everyday lives of people in the past.', '/ænˈtiːk/', 'Việc bảo tồn đồ nội thất cổ giúp thế hệ mai sau hiểu thêm về nghề thủ công truyền thống và đời sống thường nhật của người xưa.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_60_2_2', 'ten_b2_60_2', 'cannon', 'The introduction of cannon changed military architecture, encouraging the construction of thicker walls and lower defensive structures.', 'The introduction of cannon changed military architecture, encouraging the construction of thicker walls and lower defensive structures.', '/ˈkænən/', 'Sự xuất hiện của đại bác đã làm thay đổi kiến trúc quân sự, thúc đẩy việc xây dựng các bức tường thành dày hơn và các công trình phòng thủ thấp hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_60_2_3', 'ten_b2_60_2', 'knight', 'Museum displays about the medieval knight can help students understand how warfare shaped European society.', 'Museum displays about the medieval knight can help students understand how warfare shaped European society.', '/naɪt/', 'Các cuộc trưng bày trong bảo tàng về hiệp sĩ trung cổ có thể giúp học sinh hiểu cách chiến tranh định hình xã hội châu Âu.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_60_2_4', 'ten_b2_60_2', 'invade', 'Some monitoring technologies can invade people''s privacy, even when they are introduced to improve public safety.', 'Some monitoring technologies can invade people''s privacy, even when they are introduced to improve public safety.', '/ɪnˈveɪd/', 'Một số công nghệ giám sát có thể xâm phạm quyền riêng tư của mọi người, ngay cả khi chúng được đưa ra nhằm cải thiện an toàn công cộng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_60_2_5', 'ten_b2_60_2', 'primitive', 'Although these tools appear primitive, they reveal considerable skill in selecting and shaping locally available materials.', 'Although these tools appear primitive, they reveal considerable skill in selecting and shaping locally available materials.', '/ˈprɪmətɪv/', 'Mặc dù những công cụ này trông có vẻ thô sơ, nhưng chúng cho thấy tay nghề tinh xảo trong việc lựa chọn và chế tác các vật liệu có sẵn tại địa phương.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_60_2_6', 'ten_b2_60_2', 'reign', 'During the king''s reign, investment in public libraries made education more accessible to ordinary citizens.', 'During the king''s reign, investment in public libraries made education more accessible to ordinary citizens.', '/reɪn/', 'Dưới thời trị vì của nhà vua, việc đầu tư vào các thư viện công cộng đã giúp người dân bình thường dễ dàng tiếp cận giáo dục hơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_60_2_1', 'en-b2-60', 'ten_b2_60_2', 'listening', 'listening', 'Preserving antique furniture helps future generations understand traditional craftsmanship and the everyday lives of people in the past.', NULL, 'Trong câu vừa nghe, từ “antique” mang nghĩa nào sau đây?', '["đồ cổ; cổ vật","Khu ổ chuột","cố kiến; thành kiến; định kiến","lo lắng; bồn chồn"]'::jsonb, 0, '“antique” (/ænˈtiːk/): đồ cổ; cổ vật. Câu đầy đủ: Preserving antique furniture helps future generations understand traditional craftsmanship and the everyday lives of people in the past.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_60_2_2', 'en-b2-60', 'ten_b2_60_2', 'listening', 'listening', 'The introduction of cannon changed military architecture, encouraging the construction of thicker walls and lower defensive structures.', NULL, 'Trong câu vừa nghe, từ “cannon” mang nghĩa nào sau đây?', '["chịu đựng; cam chịu","thúc đẩy; khích lệ; kích thích","thảo mộc; rau thơm; cây thuốc","đại bác; hải pháo"]'::jsonb, 3, '“cannon” (/ˈkænən/): đại bác; hải pháo. Câu đầy đủ: The introduction of cannon changed military architecture, encouraging the construction of thicker walls and lower defensive structures.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
