INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_60_2', 'en-b2-60', NULL, 'comprehensive_test', 'listening', 'An old cannon stood beside the castle entrance.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những bức ảnh cũ này cần được bảo quản cẩn thận để tránh hư hỏng thêm.","Một khẩu đại bác cũ nằm ở cạnh lối vào lâu đài.","Viện bảo tàng trưng bày bộ áo giáp do một chiến binh cổ đại mặc.","Lâu đài này được xây dựng trong thời gian trị vì của một vị nữ vương trẻ tuổi."]'::jsonb, 1, 'An old cannon stood beside the castle entrance. → Một khẩu đại bác cũ nằm ở cạnh lối vào lâu đài.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_60_3', 'en-b2-60', NULL, 'comprehensive_test', 'listening', 'knight', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["hiệp sĩ","chưa hoàn chỉnh; chưa hoàn thành","cảng biển; thành phố cảng","tin học hóa; tự động hóa bằng máy tính (sử dụng máy tính để quản lý một công việc, hệ thống hoặc thông tin)"]'::jsonb, 0, 'knight (/naɪt/) → hiệp sĩ; tước sĩ; hiệp sĩ (được phong tước); quân mã (trong cờ vua)', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_60_4', 'en-b2-60', NULL, 'comprehensive_test', 'listening', 'Ants invaded our kitchen after we left cake out.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Lâu đài này được xây dựng trong thời gian trị vì của một vị nữ vương trẻ tuổi.","Đám kiến đã tràn vào nhà bếp của chúng tôi sau khi chúng tôi để bánh ngọt ở bên ngoài.","Lâu đài cổ từng canh giữ lối vào của cả vương quốc.","Viện bảo tàng kể câu chuyện về một người nô lệ đã trốn thoát."]'::jsonb, 1, 'Ants invaded our kitchen after we left cake out. → Đám kiến đã tràn vào nhà bếp của chúng tôi sau khi chúng tôi để bánh ngọt ở bên ngoài.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_60_5', 'en-b2-60', NULL, 'comprehensive_test', 'listening', 'primitive', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["hậu tố","trò chơi bài pô-ke","động từ: phản đối; chống lại","thô sơ; giản dị; thiếu các tiện nghi hiện đại"]'::jsonb, 3, 'primitive (/ˈprɪmətɪv/) → thô sơ; giản dị; thiếu các tiện nghi hiện đại; thuộc thời kỳ nguyên thủy; ban sơ', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_60_6', 'en-b2-60', NULL, 'comprehensive_test', 'listening', 'This castle was built during a young queen''s reign.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bức tranh vẽ một vị hiệp sĩ đang cưỡi ngựa phi về phía lâu đài.","Cô ấy đã vượt qua nỗi sợ hãi và bước lên ván nhảy.","Lâu đài này được xây dựng trong thời gian trị vì của một vị nữ vương trẻ tuổi.","Bảo tàng trưng bày bức tượng đá của một nữ thần."]'::jsonb, 2, 'This castle was built during a young queen''s reign. → Lâu đài này được xây dựng trong thời gian trị vì của một vị nữ vương trẻ tuổi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_60_7', 'en-b2-60', NULL, 'comprehensive_test', 'listening', 'tomb', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thỏa đáng; đạt yêu cầu; đủ tiêu chuẩn","nhân tạo; giả","đáng kể; nhiều","mồ mả; lăng mộ"]'::jsonb, 3, 'tomb (/tuːm/) → mồ mả; lăng mộ', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_60_8', 'en-b2-60', NULL, 'comprehensive_test', 'listening', 'The old castle once guarded the entrance to the kingdom.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Lâu đài cổ từng canh giữ lối vào của cả vương quốc.","Chúng tôi tìm thấy một món đồ cổ rất đẹp ở một cửa hàng nhỏ.","Bảo tàng đang trưng bày một chiếc áo choàng từng được một vị hoàng đế mặc.","Một khẩu súng trường cũ được đặt bên trong tủ kính của bảo tàng."]'::jsonb, 0, 'The old castle once guarded the entrance to the kingdom. → Lâu đài cổ từng canh giữ lối vào của cả vương quốc.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
