INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_60_18', 'en-b2-60', NULL, 'comprehensive_test', 'reading', NULL, 'Preserving antique furniture helps future generations understand traditional craftsmanship and the everyday lives of people in the past.', 'Dựa vào câu trên, từ “antique” có nghĩa phù hợp nhất là gì?', '["phân tích","đi lại (giữa nhà và nơi làm việc)","đồ cổ; cổ vật","duy nhất; đơn độc"]'::jsonb, 2, 'antique: đồ cổ; cổ vật; cổ; có giá trị cổ xưa. Dịch cả câu: Việc bảo tồn đồ nội thất cổ giúp thế hệ mai sau hiểu thêm về nghề thủ công truyền thống và đời sống thường nhật của người xưa.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_60_19', 'en-b2-60', NULL, 'comprehensive_test', 'reading', NULL, 'The introduction of cannon changed military architecture, encouraging the construction of thicker walls and lower defensive structures.', 'Dựa vào câu trên, từ “cannon” có nghĩa phù hợp nhất là gì?', '["phổ biến; toàn cục; chung cho tất cả","kẹp tóc; trâm cài tóc","đại bác; hải pháo","biện minh; chứng minh là hợp lý"]'::jsonb, 2, 'cannon: đại bác; hải pháo. Dịch cả câu: Sự xuất hiện của đại bác đã làm thay đổi kiến trúc quân sự, thúc đẩy việc xây dựng các bức tường thành dày hơn và các công trình phòng thủ thấp hơn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_60_20', 'en-b2-60', NULL, 'comprehensive_test', 'reading', NULL, 'Museum displays about the medieval knight can help students understand how warfare shaped European society.', 'Dựa vào câu trên, từ “knight” có nghĩa phù hợp nhất là gì?', '["sự bất hạnh; vận rủi","công ty; hãng","sự phòng thủ; sự bảo vệ","hiệp sĩ"]'::jsonb, 3, 'knight: hiệp sĩ; tước sĩ; hiệp sĩ (được phong tước); quân mã (trong cờ vua). Dịch cả câu: Các cuộc trưng bày trong bảo tàng về hiệp sĩ trung cổ có thể giúp học sinh hiểu cách chiến tranh định hình xã hội châu Âu.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_60_21', 'en-b2-60', NULL, 'comprehensive_test', 'reading', NULL, 'Some monitoring technologies can invade people''s privacy, even when they are introduced to improve public safety.', 'Dựa vào câu trên, từ “invade” có nghĩa phù hợp nhất là gì?', '["đương đại; hiện đại","xâm lược; xâm chiếm","buổi hướng dẫn; buổi học kèm nhỏ","thuộc thảo mộc; làm từ thảo mộc"]'::jsonb, 1, 'invade: xâm lược; xâm chiếm; xâm phạm; xâm lấn; tràn vào; ùa vào. Dịch cả câu: Một số công nghệ giám sát có thể xâm phạm quyền riêng tư của mọi người, ngay cả khi chúng được đưa ra nhằm cải thiện an toàn công cộng.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_60_22', 'en-b2-60', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự bảo tồn; sự giữ gìn; sự bảo vệ”', '["criteria","drastic","equip","preservation"]'::jsonb, 3, 'sự bảo tồn; sự giữ gìn; sự bảo vệ → preservation (/ˌprezərˈveɪʃən/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
