INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_60_24', 'en-b2-60', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “vẻ vang, huy hoàng, đáng tự hào”', '["exaggerated","hold-up","rehearsal","glorious"]'::jsonb, 3, 'vẻ vang, huy hoàng, đáng tự hào → glorious (/ˈɡlɔːriəs/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-61', 'en', 'Bài 61: Đô thị & Kiến trúc (1) - CEFR B2', 'CEFR B2', 'B2 · Đô thị', '24 từ vựng Tiếng Anh CEFR B2 chủ đề đô thị & kiến trúc kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4061, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_residence', 'en-b2-61', 'residence', '/ˈrezɪdəns/', 'B2', 'nơi cư trú; nhà ở; sự cư trú; thời gian lưu trú', 'n.', 'reside (v.), resident (n.), residential (adj.)', 'Đồng nghĩa: home, dwelling', '"Residence" mang sắc thái trang trọng; người dân/cư dân là "resident", còn khu dân cư dùng tính từ "residential".', 'Their new residence overlooks a quiet garden near the river.', NULL, 'Nơi ở mới của họ nhìn ra một khu vườn yên tĩnh gần bờ sông.', '{"wordId":"residence","ukIpa":"/ˈrezɪdəns/","usIpa":"/ˈrezɪdəns/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"A house or other place where someone lives.","vi":"nơi cư trú; nhà ở"},{"pos":"n.","en":"The state or period of living in a particular place.","vi":"sự cư trú; thời gian lưu trú"}],"examples":[{"en":"Their new residence overlooks a quiet garden near the river.","vi":"Nơi ở mới của họ nhìn ra một khu vườn yên tĩnh gần bờ sông.","audioKind":"ex"},{"en":"Applicants may need to provide proof of residence before they can access certain local services.","vi":"Người nộp đơn có thể cần cung cấp giấy xác nhận cư trú trước khi được tiếp cận một số dịch vụ địa phương.","audioKind":"ex2"}],"collocations":[{"en":"place of residence","vi":"nơi cư trú"},{"en":"proof of residence","vi":"giấy xác nhận cư trú"},{"en":"permanent residence","vi":"thường trú"},{"en":"take up residence","vi":"đến ở; định cư"}],"wordFamily":["reside (v.)","resident (n.)","residential (adj.)"],"synonyms":["home","dwelling"],"antonyms":[],"tipVi":"\"Residence\" mang sắc thái trang trọng; người dân/cư dân là \"resident\", còn khu dân cư dùng tính từ \"residential\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_outskirts', 'en-b2-61', 'outskirts', '/ˈaʊtskɜːrts/', 'B2', 'vùng ngoại ô; vùng ven đô', 'n.', NULL, 'Trái nghĩa: centre', 'Luôn dùng ở dạng số ít/số nhiều theo cụm cố định on the outskirts of a city.', 'Their new house is on the outskirts of town.', NULL, 'Ngôi nhà mới của họ nằm ở vùng ngoại ô của thị trấn.', '{"wordId":"outskirts","ukIpa":"/ˈaʊtskɜːts/","usIpa":"/ˈaʊtskɜːrts/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"the areas around the outer edge of a town or city","vi":"vùng ngoại ô; vùng ven đô"}],"examples":[{"en":"Their new house is on the outskirts of town.","vi":"Ngôi nhà mới của họ nằm ở vùng ngoại ô của thị trấn.","audioKind":"ex"},{"en":"Building affordable homes on the outskirts may reduce housing costs but increase residents'' dependence on private cars.","vi":"Việc xây dựng nhà ở giá rẻ ở ngoại ô có thể giảm chi phí nhà ở nhưng lại làm tăng sự phụ thuộc của cư dân vào xe hơi cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"on the outskirts of","vi":"ở vùng ngoại ô của"},{"en":"the outskirts of town","vi":"vùng ven thị trấn"},{"en":"the northern outskirts","vi":"vùng ngoại ô phía bắc"}],"wordFamily":[],"synonyms":[],"antonyms":["centre"],"tipVi":"Luôn dùng ở dạng số ít/số nhiều theo cụm cố định on the outskirts of a city.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_estate', 'en-b2-61', 'estate', '/ɪˈsteɪt/', 'B2', 'điền trang; thái ấp; khu dân cư; khu công nghiệp; tài sản; di sản', 'n.', NULL, NULL, 'real estate chỉ bất động sản; housing estate chỉ khu nhà ở.', 'We walked past the lake on the old country estate.', NULL, 'Chúng tôi đi bộ qua hồ nước nằm trong điền trang vùng đồng quê cổ kính.', '{"wordId":"estate","ukIpa":"/ɪˈsteɪt/","usIpa":"/ɪˈsteɪt/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"A large area of owned land, often with a large house.","vi":"điền trang; thái ấp"},{"pos":"n.","en":"An area of buildings developed together for a particular purpose.","vi":"khu dân cư; khu công nghiệp"},{"pos":"n.","en":"Everything a person owns, especially after their death.","vi":"tài sản; di sản"}],"examples":[{"en":"We walked past the lake on the old country estate.","vi":"Chúng tôi đi bộ qua hồ nước nằm trong điền trang vùng đồng quê cổ kính.","audioKind":"ex"},{"en":"New housing estates should include green spaces and reliable transport links to nearby employment centres.","vi":"Các khu nhà ở mới nên được tích hợp không gian xanh cùng hệ thống giao thông thuận tiện kết nối đến các trung tâm việc làm lân cận.","audioKind":"ex2"}],"collocations":[{"en":"a country estate","vi":"điền trang vùng quê"},{"en":"a housing estate","vi":"khu nhà ở"},{"en":"an industrial estate","vi":"khu công nghiệp"},{"en":"real estate","vi":"bất động sản"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"real estate chỉ bất động sản; housing estate chỉ khu nhà ở.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_terrace', 'en-b2-61', 'terrace', '/ˈterəs/', 'B2', 'sân hiên; ban công lớn; sân thượng; ruộng bậc thang; bậc thềm; nhà liền kề (các ngôi nhà có chung tường ngăn)', 'n.', 'terraced (adj.), terracing (n.)', NULL, 'Terrace thường là một khu vực ngoài trời lớn, không đồng nghĩa hoàn toàn với balcony (ban công nhỏ).', 'We had breakfast on the terrace overlooking the garden.', NULL, 'Chúng tôi ăn sáng trên sân hiên hướng ra khu vườn.', '{"wordId":"terrace","ukIpa":"/ˈterəs/","usIpa":"/ˈterəs/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"a flat outdoor area beside a building for sitting","vi":"sân hiên; ban công lớn; sân thượng"},{"pos":"n.","en":"a flat strip of land cut into a slope","vi":"ruộng bậc thang; bậc thềm"},{"pos":"n.","en":"a row of houses joined by shared side walls","vi":"nhà liền kề (các ngôi nhà có chung tường ngăn)"}],"examples":[{"en":"We had breakfast on the terrace overlooking the garden.","vi":"Chúng tôi ăn sáng trên sân hiên hướng ra khu vườn.","audioKind":"ex"},{"en":"Farmers maintain each terrace carefully to reduce soil erosion and grow crops on steep mountain slopes.","vi":"Nông dân chăm sóc cẩn thận từng bậc ruộng bậc thang để giảm thiểu xói mòn đất và trồng trọt trên các sườn núi dốc.","audioKind":"ex2"}],"collocations":[{"en":"a roof terrace","vi":"sân thượng"},{"en":"a sunny terrace","vi":"sân hiên đầy nắng"},{"en":"rice terraces","vi":"ruộng bậc thang lúa"},{"en":"a terrace of houses","vi":"một dãy nhà liền kề"}],"wordFamily":["terraced (adj.)","terracing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Terrace thường là một khu vực ngoài trời lớn, không đồng nghĩa hoàn toàn với balcony (ban công nhỏ).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rebuild', 'en-b2-61', 'rebuild', '/ˌriːˈbɪld/', 'B2', 'xây dựng lại; tái thiết; khôi phục; vực dậy (niềm tin, kinh tế, mối quan hệ)', 'v.', 'build (v.), builder (n.), rebuilding (n.)', 'Đồng nghĩa: reconstruct, restore · Trái nghĩa: demolish', 'Dạng quá khứ và quá khứ phân từ đều là rebuilt.', 'We plan to rebuild the garden wall this weekend.', NULL, 'Chúng tôi dự định xây dựng lại bức tường vườn vào cuối tuần này.', '{"wordId":"rebuild","ukIpa":"/ˌriːˈbɪld/","usIpa":"/ˌriːˈbɪld/","cefr":"B2","topic":"city","senses":[{"pos":"v.","en":"to build something again after damage or destruction","vi":"xây dựng lại; tái thiết"},{"pos":"v.","en":"to make something strong or successful again","vi":"khôi phục; vực dậy (niềm tin, kinh tế, mối quan hệ)"}],"examples":[{"en":"We plan to rebuild the garden wall this weekend.","vi":"Chúng tôi dự định xây dựng lại bức tường vườn vào cuối tuần này.","audioKind":"ex"},{"en":"After severe flooding, local authorities must rebuild essential infrastructure and help affected communities recover.","vi":"Sau trận lũ lụt nghiêm trọng, chính quyền địa phương phải tái thiết cơ sở hạ tầng thiết yếu và giúp các cộng đồng bị ảnh hưởng phục hồi.","audioKind":"ex2"}],"collocations":[{"en":"rebuild a house","vi":"xây lại nhà"},{"en":"rebuild trust","vi":"lấy lại niềm tin"},{"en":"rebuild the economy","vi":"vực dậy nền kinh tế"}],"wordFamily":["build (v.)","builder (n.)","rebuilding (n.)"],"synonyms":["reconstruct","restore"],"antonyms":["demolish"],"tipVi":"Dạng quá khứ và quá khứ phân từ đều là rebuilt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_curved', 'en-b2-61', 'curved', '/kɝːvd/', 'B2', 'cong; có hình vòng cung', 'adj.', 'curve (n.), curve (v.), curvature (n.)', 'Đồng nghĩa: arched · Trái nghĩa: straight', 'curved nhấn mạnh đường nét uốn lượn mượt mà; bent cũng có thể dùng cho vật bị bẻ gập.', 'A curved path leads from our gate to the pond.', NULL, 'Một con đường uốn lượn dẫn từ cổng nhà chúng tôi đến cái ao.', '{"wordId":"curved","ukIpa":"/kɜːvd/","usIpa":"/kɝːvd/","cefr":"B2","topic":"city","senses":[{"pos":"adj.","en":"Having a smoothly bending shape rather than a straight one.","vi":"cong; có hình vòng cung"}],"examples":[{"en":"A curved path leads from our gate to the pond.","vi":"Một con đường uốn lượn dẫn từ cổng nhà chúng tôi đến cái ao.","audioKind":"ex"},{"en":"Curved building designs can create distinctive urban landmarks, although they may require more complex construction techniques.","vi":"Thiết kế kiến trúc cong có thể tạo ra những điểm nhấn đô thị độc đáo, mặc dù chúng có thể đòi hỏi các kỹ thuật thi công phức tạp hơn.","audioKind":"ex2"}],"collocations":[{"en":"curved surface","vi":"mặt cong"},{"en":"curved line","vi":"đường cong"},{"en":"curved roof","vi":"mái vòm cong"}],"wordFamily":["curve (n.)","curve (v.)","curvature (n.)"],"synonyms":["arched"],"antonyms":["straight"],"tipVi":"curved nhấn mạnh đường nét uốn lượn mượt mà; bent cũng có thể dùng cho vật bị bẻ gập.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_landlord', 'en-b2-61', 'landlord', '/ˈlændlɔːrd/', 'B2', 'chủ nhà; chủ đất (cho thuê); chủ quán rượu; chủ quán trọ', 'n.', 'landlady (n.), landownership (n.)', NULL, 'landlord là chủ nhà, tenant là người thuê nhà; nghĩa thứ hai phổ biến ở nước Anh.', 'Our landlord came over to fix the leaking tap.', NULL, 'Chủ nhà của chúng tôi đã qua để sửa cái vòi nước bị rò rỉ.', '{"wordId":"landlord","ukIpa":"/ˈlændlɔːd/","usIpa":"/ˈlændlɔːrd/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"someone who rents out property or land to others","vi":"chủ nhà; chủ đất (cho thuê)"},{"pos":"n.","en":"a man who owns or manages a pub","vi":"chủ quán rượu; chủ quán trọ"}],"examples":[{"en":"Our landlord came over to fix the leaking tap.","vi":"Chủ nhà của chúng tôi đã qua để sửa cái vòi nước bị rò rỉ.","audioKind":"ex"},{"en":"Local authorities should require landlords to maintain safe living conditions for all their tenants.","vi":"Chính quyền địa phương nên yêu cầu các chủ nhà duy trì điều kiện sống an toàn cho tất cả người thuê nhà.","audioKind":"ex2"}],"collocations":[{"en":"private landlord","vi":"chủ nhà cho thuê tư nhân"},{"en":"landlord and tenant","vi":"chủ nhà và người thuê nhà"},{"en":"ask the landlord","vi":"hỏi chủ nhà"}],"wordFamily":["landlady (n.)","landownership (n.)"],"synonyms":[],"antonyms":[],"tipVi":"landlord là chủ nhà, tenant là người thuê nhà; nghĩa thứ hai phổ biến ở nước Anh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_situated', 'en-b2-61', 'situated', '/ˈsɪtʃueɪtɪd/', 'B2', 'nằm ở; tọa lạc ở; ở vào một hoàn cảnh nhất định', 'adj.', 'situate (v.), situation (n.)', 'Đồng nghĩa: located, positioned', 'Thường dùng cấu trúc be situated in/near để miêu tả vị trí, mang văn phong trang trọng.', 'Our hotel is situated beside a quiet mountain lake.', NULL, 'Khách sạn của chúng tôi tọa lạc bên cạnh một hồ nước núi yên tĩnh.', '{"wordId":"situated","ukIpa":"/ˈsɪtʃueɪtɪd/","usIpa":"/ˈsɪtʃueɪtɪd/","cefr":"B2","topic":"city","senses":[{"pos":"adj.","en":"located in a particular place","vi":"nằm ở; tọa lạc ở"},{"pos":"adj.","en":"in a particular set of circumstances","vi":"ở vào một hoàn cảnh nhất định"}],"examples":[{"en":"Our hotel is situated beside a quiet mountain lake.","vi":"Khách sạn của chúng tôi tọa lạc bên cạnh một hồ nước núi yên tĩnh.","audioKind":"ex"},{"en":"Schools situated near busy roads may need additional measures to protect pupils from air pollution.","vi":"Các trường học nằm gần các tuyến đường bận rộn có thể cần thêm các biện pháp để bảo vệ học sinh khỏi ô nhiễm không khí.","audioKind":"ex2"}],"collocations":[{"en":"conveniently situated","vi":"có vị trí thuận tiện"},{"en":"centrally situated","vi":"nằm ở trung tâm"},{"en":"situated near","vi":"nằm gần"}],"wordFamily":["situate (v.)","situation (n.)"],"synonyms":["located","positioned"],"antonyms":[],"tipVi":"Thường dùng cấu trúc be situated in/near để miêu tả vị trí, mang văn phong trang trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lighting', 'en-b2-61', 'lighting', '/ˈlaɪtɪŋ/', 'B2', 'hệ thống chiếu sáng; ánh sáng', 'n.', 'light (n.), light (v.)', 'Đồng nghĩa: illumination', 'Khi chỉ tổng thể chiếu sáng thì không đếm được; đèn đơn lẻ dùng a light.', 'The soft lighting makes this room feel warm and cosy.', NULL, 'Ánh sáng dịu nhẹ làm cho căn phòng này trở nên ấm áp và dễ chịu.', '{"wordId":"lighting","ukIpa":"/ˈlaɪtɪŋ/","usIpa":"/ˈlaɪtɪŋ/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"The lights in a place or the effects they produce.","vi":"hệ thống chiếu sáng; ánh sáng"}],"examples":[{"en":"The soft lighting makes this room feel warm and cosy.","vi":"Ánh sáng dịu nhẹ làm cho căn phòng này trở nên ấm áp và dễ chịu.","audioKind":"ex"},{"en":"Improved street lighting can make pedestrians feel safer and encourage more people to walk after dark.","vi":"Việc cải thiện hệ thống chiếu sáng đường phố có thể giúp người đi bộ cảm thấy an toàn hơn và khuyến khích nhiều người đi bộ ra ngoài hơn sau khi trời tối.","audioKind":"ex2"}],"collocations":[{"en":"street lighting","vi":"chiếu sáng đường phố"},{"en":"natural lighting","vi":"ánh sáng tự nhiên"},{"en":"poor lighting","vi":"ánh sáng kém"},{"en":"lighting effects","vi":"hiệu ứng ánh sáng"}],"wordFamily":["light (n.)","light (v.)"],"synonyms":["illumination"],"antonyms":[],"tipVi":"Khi chỉ tổng thể chiếu sáng thì không đếm được; đèn đơn lẻ dùng a light.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_expansion', 'en-b2-61', 'expansion', '/ɪkˈspænʃən/', 'B2', 'sự mở rộng; sự bành trướng; sự phình ra', 'n.', 'expand (v.), expandable (adj.), expansive (adj.)', 'Đồng nghĩa: growth, enlargement · Trái nghĩa: contraction', 'Động từ là expand, khi chuyển thành danh từ chính tả đổi thành expansion.', 'The kitchen expansion gave us room for a table.', NULL, 'Việc mở rộng nhà bếp đã cho chúng tôi không gian để kê một chiếc bàn.', '{"wordId":"expansion","ukIpa":"/ɪkˈspænʃən/","usIpa":"/ɪkˈspænʃən/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"An increase in size, amount, or area","vi":"sự mở rộng; sự bành trướng; sự phình ra"}],"examples":[{"en":"The kitchen expansion gave us room for a table.","vi":"Việc mở rộng nhà bếp đã cho chúng tôi không gian để kê một chiếc bàn.","audioKind":"ex"},{"en":"Rapid urban expansion can threaten nearby farmland unless local authorities introduce effective planning controls.","vi":"Sự mở rộng đô thị nhanh chóng có thể đe dọa đất nông nghiệp gần đó trừ khi chính quyền địa phương đưa ra các biện pháp kiểm soát quy hoạch hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"urban expansion","vi":"sự mở rộng đô thị"},{"en":"economic expansion","vi":"sự bùng nổ kinh tế"},{"en":"thermal expansion","vi":"sự giãn nở vì nhiệt"},{"en":"rapid expansion","vi":"sự mở rộng nhanh chóng"}],"wordFamily":["expand (v.)","expandable (adj.)","expansive (adj.)"],"synonyms":["growth","enlargement"],"antonyms":["contraction"],"tipVi":"Động từ là expand, khi chuyển thành danh từ chính tả đổi thành expansion.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_intersection', 'en-b2-61', 'intersection', '/ˌɪntɚˈsekʃən/', 'B2', 'giao lộ; ngã tư; điểm giao nhau; giao điểm', 'n.', 'intersect (v.), intersecting (adj.)', 'Đồng nghĩa: junction, crossing', 'Nơi đường giao nhau thường dùng at an intersection.', 'Turn left at the intersection beside the bakery.', NULL, 'Rẽ trái ở ngã tư cạnh tiệm bánh nhé.', '{"wordId":"intersection","ukIpa":"/ˌɪntəˈsekʃən/","usIpa":"/ˌɪntɚˈsekʃən/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"A place where two or more roads meet.","vi":"giao lộ; ngã tư"},{"pos":"n.","en":"A point or area shared by things that cross or overlap.","vi":"điểm giao nhau; giao điểm"}],"examples":[{"en":"Turn left at the intersection beside the bakery.","vi":"Rẽ trái ở ngã tư cạnh tiệm bánh nhé.","audioKind":"ex"},{"en":"Installing better lighting at busy intersections can reduce accidents and improve safety for pedestrians.","vi":"Việc lắp đặt hệ thống chiếu sáng tốt hơn tại các giao lộ đông đúc có thể làm giảm tai nạn và nâng cao sự an toàn cho người đi bộ.","audioKind":"ex2"}],"collocations":[{"en":"busy intersection","vi":"giao lộ đông đúc"},{"en":"at the intersection","vi":"tại giao lộ"},{"en":"the intersection of two sets","vi":"giao điểm của hai tập hợp"}],"wordFamily":["intersect (v.)","intersecting (adj.)"],"synonyms":["junction","crossing"],"antonyms":[],"tipVi":"Nơi đường giao nhau thường dùng at an intersection.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_construction', 'en-b2-61', 'construction', '/kənˈstrʌkʃən/', 'B2', 'sự xây dựng; công trình xây dựng; cấu trúc; vật kiến trúc; cấu trúc câu; ngữ pháp', 'n.', 'construct (v.), reconstruct (v.), reconstruction (n.)', 'Đồng nghĩa: building · Trái nghĩa: demolition', 'Danh từ không đếm được khi chỉ quá trình xây dựng; dùng under construction để chỉ việc đang thi công.', 'Construction of the new bridge started early this morning.', NULL, 'Công việc xây dựng cây cầu mới đã bắt đầu vào sáng sớm nay.', '{"wordId":"construction","ukIpa":"/kənˈstrʌkʃən/","usIpa":"/kənˈstrʌkʃən/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"the process of building something, especially roads or buildings","vi":"sự xây dựng; công trình xây dựng"},{"pos":"n.","en":"something made by joining parts together","vi":"cấu trúc; vật kiến trúc"},{"pos":"n.","en":"the way words are arranged to form a phrase or sentence","vi":"cấu trúc câu; ngữ pháp"}],"examples":[{"en":"Construction of the new bridge started early this morning.","vi":"Công việc xây dựng cây cầu mới đã bắt đầu vào sáng sớm nay.","audioKind":"ex"},{"en":"The construction of energy-efficient housing can reduce household bills and limit the environmental impact of urban growth.","vi":"Việc xây dựng nhà ở tiết kiệm năng lượng có thể giảm hóa đơn sinh hoạt và hạn chế tác động môi trường của quá trình đô thị hóa.","audioKind":"ex2"}],"collocations":[{"en":"under construction","vi":"đang được xây dựng"},{"en":"construction site","vi":"công trường xây dựng"},{"en":"construction industry","vi":"ngành xây dựng"},{"en":"sentence construction","vi":"cấu trúc câu"}],"wordFamily":["construct (v.)","reconstruct (v.)","reconstruction (n.)"],"synonyms":["building"],"antonyms":["demolition"],"tipVi":"Danh từ không đếm được khi chỉ quá trình xây dựng; dùng under construction để chỉ việc đang thi công.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_arch', 'en-b2-61', 'arch', '/ɑːrtʃ/', 'B2', 'vòm; cổng vòm; uốn cong; cong lên', 'n.', 'arched (adj.), archway (n.)', NULL, 'Động từ chỉ hành động uốn thành hình vòm, chẳng hạn như arch your back.', 'We sheltered from the rain beneath a stone arch.', NULL, 'Chúng tôi trú mưa bên dưới một cổng vòm bằng đá.', '{"wordId":"arch","ukIpa":"/ɑːtʃ/","usIpa":"/ɑːrtʃ/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"A curved structure spanning an opening or supporting weight","vi":"vòm; cổng vòm"},{"pos":"v.","en":"To bend into a curved shape","vi":"uốn cong; cong lên"}],"examples":[{"en":"We sheltered from the rain beneath a stone arch.","vi":"Chúng tôi trú mưa bên dưới một cổng vòm bằng đá.","audioKind":"ex"},{"en":"Traditional bridges often use a central arch to distribute weight and allow boats to pass beneath.","vi":"Các cây cầu truyền thống thường sử dụng kết cấu vòm trung tâm để phân tán trọng lượng và cho phép tàu thuyền đi qua bên dưới.","audioKind":"ex2"}],"collocations":[{"en":"stone arch","vi":"vòm đá"},{"en":"arch bridge","vi":"cầu vòm"},{"en":"arch your back","vi":"uốn cong lưng"}],"wordFamily":["arched (adj.)","archway (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ chỉ hành động uốn thành hình vòm, chẳng hạn như arch your back.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_maintenance', 'en-b2-61', 'maintenance', '/ˈmeɪntənəns/', 'B2', 'sự bảo dưỡng; sự bảo trì; công tác duy tu; sự duy trì; sự giữ gìn; tiền cấp dưỡng nuôi con; tiền chu cấp cho vợ/chồng cũ', 'n.', 'maintain (v.), maintainable (adj.)', 'Đồng nghĩa: upkeep · Trái nghĩa: neglect', 'Thường không đếm được; cách viết không phải là maintainance.', 'Regular maintenance keeps my old bicycle safe to ride.', NULL, 'Việc bảo dưỡng định kỳ giúp chiếc xe đạp cũ của tôi đi lại an toàn.', '{"wordId":"maintenance","ukIpa":"/ˈmeɪntənəns/","usIpa":"/ˈmeɪntənəns/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"work needed to keep something in good condition","vi":"sự bảo dưỡng; sự bảo trì; công tác duy tu"},{"pos":"n.","en":"the act of keeping a condition or situation unchanged","vi":"sự duy trì; sự giữ gìn"},{"pos":"n.","en":"money paid regularly to support a child or former spouse","vi":"tiền cấp dưỡng nuôi con; tiền chu cấp cho vợ/chồng cũ"}],"examples":[{"en":"Regular maintenance keeps my old bicycle safe to ride.","vi":"Việc bảo dưỡng định kỳ giúp chiếc xe đạp cũ của tôi đi lại an toàn.","audioKind":"ex"},{"en":"Governments should budget for the long-term maintenance of public infrastructure rather than focusing solely on new construction.","vi":"Chính phủ nên lập ngân sách cho việc bảo trì cơ sở hạ tầng công cộng lâu dài thay vì chỉ tập trung vào các công trình xây dựng mới.","audioKind":"ex2"}],"collocations":[{"en":"routine maintenance","vi":"bảo dưỡng định kỳ"},{"en":"maintenance costs","vi":"chi phí bảo trì"},{"en":"the maintenance of standards","vi":"sự duy trì các tiêu chuẩn"},{"en":"child maintenance","vi":"tiền cấp dưỡng nuôi con"}],"wordFamily":["maintain (v.)","maintainable (adj.)"],"synonyms":["upkeep"],"antonyms":["neglect"],"tipVi":"Thường không đếm được; cách viết không phải là maintainance.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_occupy', 'en-b2-61', 'occupy', '/ˈɑːkjupaɪ/', 'B2', 'chiếm; chiếm giữ; chiếm lĩnh không gian/thời gian; chiếm đóng bằng vũ lực; làm cho ai đó bận rộn; thu hút sự chú ý', 'v.', 'occupation (n.), occupied (adj.), occupant (n.)', NULL, 'Bận rộn với việc gì có thể dùng be occupied with hoặc in doing.', 'These old boxes occupy most of our spare room.', NULL, 'Những chiếc hộp cũ này chiếm phần lớn căn phòng trống của chúng tôi.', '{"wordId":"occupy","ukIpa":"/ˈɒkjupaɪ/","usIpa":"/ˈɑːkjupaɪ/","cefr":"B2","topic":"city","senses":[{"pos":"v.","en":"to fill or use a space, place, or period","vi":"chiếm; chiếm giữ; chiếm lĩnh không gian/thời gian"},{"pos":"v.","en":"to take and maintain control of a place by force","vi":"chiếm đóng bằng vũ lực"},{"pos":"v.","en":"to keep someone busy or interested","vi":"làm cho ai đó bận rộn; thu hút sự chú ý"}],"examples":[{"en":"These old boxes occupy most of our spare room.","vi":"Những chiếc hộp cũ này chiếm phần lớn căn phòng trống của chúng tôi.","audioKind":"ex"},{"en":"Private cars occupy valuable urban space that could otherwise accommodate parks, cycle lanes, or wider pavements.","vi":"Xe hơi cá nhân chiếm dụng không gian đô thị có giá trị, vốn dĩ có thể dùng để làm công viên, làn đường cho xe đạp hoặc vỉa hè rộng hơn.","audioKind":"ex2"}],"collocations":[{"en":"occupy space","vi":"chiếm không gian"},{"en":"occupy a position","vi":"giữ một chức vụ"},{"en":"occupy yourself with","vi":"bận rộn với việc gì"}],"wordFamily":["occupation (n.)","occupied (adj.)","occupant (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Bận rộn với việc gì có thể dùng be occupied with hoặc in doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_crane', 'en-b2-61', 'crane', '/kreɪn/', 'B2', 'cần trục; máy cẩu; chim sếu; vươn cổ; rướn cổ', 'n.', NULL, NULL, 'Động từ thường đi theo cụm crane your neck, có nghĩa là vươn cổ ra để nhìn cho rõ.', 'A crane lifted the heavy beam above the roof.', NULL, 'Một chiếc cần trục đã nâng thanh dầm nặng lên phía trên mái nhà.', '{"wordId":"crane","ukIpa":"/kreɪn/","usIpa":"/kreɪn/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"A machine for lifting and moving heavy objects.","vi":"cần trục; máy cẩu"},{"pos":"n.","en":"A large bird with long legs and a long neck.","vi":"chim sếu"},{"pos":"v.","en":"To stretch your neck to see something better.","vi":"vươn cổ; rướn cổ"}],"examples":[{"en":"A crane lifted the heavy beam above the roof.","vi":"Một chiếc cần trục đã nâng thanh dầm nặng lên phía trên mái nhà.","audioKind":"ex"},{"en":"Construction companies use cranes to assemble tall buildings efficiently, but strict safety procedures remain essential.","vi":"Các công ty xây dựng sử dụng cần trục để thi công các tòa nhà cao tầng một cách hiệu quả, nhưng các quy trình an toàn nghiêm ngặt vẫn đóng vai trò cốt yếu.","audioKind":"ex2"}],"collocations":[{"en":"a tower crane","vi":"cần trục tháp"},{"en":"operate a crane","vi":"vận hành cần trục"},{"en":"crane your neck","vi":"vươn cổ nhìn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Động từ thường đi theo cụm crane your neck, có nghĩa là vươn cổ ra để nhìn cho rõ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pave', 'en-b2-61', 'pave', '/peɪv/', 'B2', 'lát đường; lát nền', 'v.', 'paving (n.), pavement (n.), paved (adj.), unpaved (adj.)', 'Đồng nghĩa: surface', 'Cấu trúc pave the way for mang nghĩa ẩn dụ là "tạo điều kiện cho / mở đường cho".', 'Workers are paving the narrow path behind our house.', NULL, 'Các công nhân đang lát đường cho lối đi nhỏ phía sau nhà chúng tôi.', '{"wordId":"pave","ukIpa":"/peɪv/","usIpa":"/peɪv/","cefr":"B2","topic":"city","senses":[{"pos":"v.","en":"To cover ground with stone, concrete, or another hard surface.","vi":"lát đường; lát nền"}],"examples":[{"en":"Workers are paving the narrow path behind our house.","vi":"Các công nhân đang lát đường cho lối đi nhỏ phía sau nhà chúng tôi.","audioKind":"ex"},{"en":"Local authorities should pave busy pedestrian routes with durable materials that remain safe in wet weather.","vi":"Chính quyền địa phương nên lát các tuyến đường đi bộ đông đúc bằng vật liệu bền bỉ, đảm bảo an toàn trong điều kiện thời tiết ẩm ướt.","audioKind":"ex2"}],"collocations":[{"en":"pave a road","vi":"lát một con đường"},{"en":"pave with stone","vi":"lát bằng đá"},{"en":"pave the way for","vi":"mở đường cho; tạo điều kiện cho"}],"wordFamily":["paving (n.)","pavement (n.)","paved (adj.)","unpaved (adj.)"],"synonyms":["surface"],"antonyms":[],"tipVi":"Cấu trúc pave the way for mang nghĩa ẩn dụ là \"tạo điều kiện cho / mở đường cho\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_renewal', 'en-b2-61', 'renewal', '/rɪˈnuːəl/', 'B2', 'sự gia hạn; sự đổi mới hợp đồng; sự làm mới; sự hồi sinh; sự phục hồi', 'n.', 'renew (v.), renewable (adj.), renewed (adj.)', NULL, 'renewal là danh từ; renew a subscription có nghĩa là "gia hạn thuê bao".', 'My gym membership is due for renewal next month.', NULL, 'Thẻ hội viên phòng gym của tôi sắp đến hạn gia hạn vào tháng tới.', '{"wordId":"renewal","ukIpa":"/rɪˈnjuːəl/","usIpa":"/rɪˈnuːəl/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"the extension of an agreement or service for another period","vi":"sự gia hạn; sự đổi mới hợp đồng"},{"pos":"n.","en":"the process of making something fresh, strong, or effective again","vi":"sự làm mới; sự hồi sinh; sự phục hồi"}],"examples":[{"en":"My gym membership is due for renewal next month.","vi":"Thẻ hội viên phòng gym của tôi sắp đến hạn gia hạn vào tháng tới.","audioKind":"ex"},{"en":"Urban renewal projects should improve public spaces without forcing existing residents to leave their neighbourhoods.","vi":"Các dự án tái thiết đô thị nên cải thiện không gian công cộng mà không buộc cư dân hiện tại phải rời khỏi khu1 vực sinh sống của họ.","audioKind":"ex2"}],"collocations":[{"en":"membership renewal","vi":"gia hạn thẻ thành viên"},{"en":"licence renewal","vi":"gia hạn giấy phép"},{"en":"urban renewal","vi":"tái thiết đô thị; đổi mới đô thị"},{"en":"up for renewal","vi":"sắp đến hạn gia hạn"}],"wordFamily":["renew (v.)","renewable (adj.)","renewed (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"renewal là danh từ; renew a subscription có nghĩa là \"gia hạn thuê bao\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hub', 'en-b2-61', 'hub', '/hʌb/', 'B2', 'trung tâm; đầu mối giao thông; tâm bánh xe; trục bánh xe; thiết bị chia mạng; bộ tập trung', 'n.', NULL, 'Đồng nghĩa: centre, focal point', 'Nghĩa trung tâm thường đi với cấu trúc "a hub for" hoặc "the hub of".', 'The kitchen is the hub of our family life.', NULL, 'Nhà bếp là trung tâm của đời sống gia đình chúng tôi.', '{"wordId":"hub","ukIpa":"/hʌb/","usIpa":"/hʌb/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"A central place for a particular activity or transport network.","vi":"trung tâm; đầu mối giao thông"},{"pos":"n.","en":"The central part of a wheel, where the spokes meet.","vi":"tâm bánh xe; trục bánh xe"},{"pos":"n.","en":"A device that connects several computers within a network.","vi":"thiết bị chia mạng; bộ tập trung"}],"examples":[{"en":"The kitchen is the hub of our family life.","vi":"Nhà bếp là trung tâm của đời sống gia đình chúng tôi.","audioKind":"ex"},{"en":"Investment in reliable rail connections could transform this coastal city into a major regional transport hub.","vi":"Việc đầu tư vào các kết nối đường sắt đáng tin cậy có thể biến thành phố ven biển này thành một trung tâm giao thông khu vực lớn.","audioKind":"ex2"}],"collocations":[{"en":"transport hub","vi":"trung tâm giao thông"},{"en":"commercial hub","vi":"trung tâm thương mại"},{"en":"hub of activity","vi":"trung tâm hoạt động"},{"en":"network hub","vi":"bộ tập trung mạng"}],"wordFamily":[],"synonyms":["centre","focal point"],"antonyms":[],"tipVi":"Nghĩa trung tâm thường đi với cấu trúc \"a hub for\" hoặc \"the hub of\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bungalow', 'en-b2-61', 'bungalow', '/ˈbʌŋɡəloʊ/', 'B2', 'nhà trệt; nhà một tầng', 'n.', NULL, NULL, 'Điểm cốt lõi là nhà thường chỉ có một tầng, chứ không nhất thiết phải tồi tàn hay nhỏ hẹp.', 'They bought a bungalow with a small sunny garden.', NULL, 'Họ đã mua một ngôi nhà trệt có khu vườn nhỏ ngập nắng.', '{"wordId":"bungalow","ukIpa":"/ˈbʌŋɡələʊ/","usIpa":"/ˈbʌŋɡəloʊ/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"A house usually built on one floor.","vi":"nhà trệt; nhà một tầng"}],"examples":[{"en":"They bought a bungalow with a small sunny garden.","vi":"Họ đã mua một ngôi nhà trệt có khu vườn nhỏ ngập nắng.","audioKind":"ex"},{"en":"Bungalows can suit older residents because their single-storey design removes the need to climb stairs.","vi":"Nhà một tầng rất phù hợp với cư dân lớn tuổi vì thiết kế đơn tầng giúp họ không phải leo cầu thang.","audioKind":"ex2"}],"collocations":[{"en":"detached bungalow","vi":"nhà trệt biệt lập"},{"en":"single-storey bungalow","vi":"nhà một tầng"},{"en":"seaside bungalow","vi":"nhà trệt ven biển"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Điểm cốt lõi là nhà thường chỉ có một tầng, chứ không nhất thiết phải tồi tàn hay nhỏ hẹp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_blockage', 'en-b2-61', 'blockage', '/ˈblɑːkɪdʒ/', 'B2', 'sự tắc nghẽn; vật cản; chỗ nghẽn', 'n.', 'block (v.), blocked (adj.), unblock (v.)', 'Đồng nghĩa: obstruction', 'Chỉ sự tắc nghẽn đường ống hoặc lối đi; phong tỏa quân sự hoặc kinh tế thường dùng blockade.', 'A blockage in the pipe stopped the water flowing.', NULL, 'Vật cản trong đường ống đã làm nước không thể chảy được.', '{"wordId":"blockage","ukIpa":"/ˈblɒkɪdʒ/","usIpa":"/ˈblɑːkɪdʒ/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"Something that prevents movement through a passage, or the resulting obstruction.","vi":"sự tắc nghẽn; vật cản; chỗ nghẽn"}],"examples":[{"en":"A blockage in the pipe stopped the water flowing.","vi":"Vật cản trong đường ống đã làm nước không thể chảy được.","audioKind":"ex"},{"en":"Regular maintenance of urban drainage systems can prevent blockages that increase the risk of flooding.","vi":"Việc bảo trì định kỳ hệ thống thoát nước đô thị có thể ngăn ngừa tình trạng tắc nghẽn làm gia tăng nguy cơ ngập lụt.","audioKind":"ex2"}],"collocations":[{"en":"clear a blockage","vi":"thông tắc nghẽn"},{"en":"a blockage in a pipe","vi":"chỗ tắc trong ống nước"},{"en":"intestinal blockage","vi":"tắc ruột"}],"wordFamily":["block (v.)","blocked (adj.)","unblock (v.)"],"synonyms":["obstruction"],"antonyms":[],"tipVi":"Chỉ sự tắc nghẽn đường ống hoặc lối đi; phong tỏa quân sự hoặc kinh tế thường dùng blockade.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grand', 'en-b2-61', 'grand', '/ɡrænd/', 'B2', 'hoành tráng; nguy nga; quy mô lớn; quan trọng; tuyệt vời; thú vị', 'adj.', 'grandly (adv.), grandeur (n.), grandness (n.)', 'Đồng nghĩa: magnificent, impressive, splendid · Trái nghĩa: modest', 'grand total chỉ tổng số sau khi đã cộng tất cả lại.', 'We climbed the grand staircase beneath a sparkling chandelier.', NULL, 'Chúng tôi bước lên chiếc cầu thang hoành tráng dưới chùm đèn chùm lấp lánh.', '{"wordId":"grand","ukIpa":"/ɡrænd/","usIpa":"/ɡrænd/","cefr":"B2","topic":"city","senses":[{"pos":"adj.","en":"Large, impressive, or splendid in appearance","vi":"hoành tráng; nguy nga"},{"pos":"adj.","en":"Ambitious in scale or important in purpose","vi":"quy mô lớn; quan trọng"},{"pos":"adj.","en":"Very good or enjoyable","vi":"tuyệt vời; thú vị"}],"examples":[{"en":"We climbed the grand staircase beneath a sparkling chandelier.","vi":"Chúng tôi bước lên chiếc cầu thang hoành tráng dưới chùm đèn chùm lấp lánh.","audioKind":"ex"},{"en":"Preserving grand public buildings can strengthen local identity, although maintenance often requires substantial government funding.","vi":"Việc bảo tồn các công trình công cộng nguy nga có thể củng cố bản sắc địa phương, mặc dù việc duy trì thường đòi hỏi nguồn kinh phí lớn từ chính phủ.","audioKind":"ex2"}],"collocations":[{"en":"a grand staircase","vi":"cầu thang lớn nguy nga"},{"en":"a grand plan","vi":"kế hoạch lớn lao"},{"en":"a grand opening","vi":"lễ khai trương trọng thể"},{"en":"the grand total","vi":"tổng số cộng lại"}],"wordFamily":["grandly (adv.)","grandeur (n.)","grandness (n.)"],"synonyms":["magnificent","impressive","splendid"],"antonyms":["modest"],"tipVi":"grand total chỉ tổng số sau khi đã cộng tất cả lại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lobby', 'en-b2-61', 'lobby', '/ˈlɑːbi/', 'B2', 'sảnh; tiền sảnh; phòng đợi; vận động hành lang; gây sức ép; nhóm vận động chính sách', 'n.', 'lobbyist (n.), lobbying (n.)', NULL, 'Vận động ủng hộ dùng lobby for, phản đối dùng lobby against.', 'I''ll wait in the lobby while you collect your suitcase.', NULL, 'Tôi sẽ đợi ở sảnh trong khi bạn đi lấy vali.', '{"wordId":"lobby","ukIpa":"/ˈlɒbi/","usIpa":"/ˈlɑːbi/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"An entrance area inside a hotel or other large building.","vi":"sảnh; tiền sảnh; phòng đợi"},{"pos":"v.","en":"Try to persuade officials to support a policy or decision.","vi":"vận động hành lang; gây sức ép"},{"pos":"n.","en":"A group trying to influence public policy on particular issues.","vi":"nhóm vận động chính sách"}],"examples":[{"en":"I''ll wait in the lobby while you collect your suitcase.","vi":"Tôi sẽ đợi ở sảnh trong khi bạn đi lấy vali.","audioKind":"ex"},{"en":"Environmental groups lobby governments to introduce stricter controls on industrial pollution and protect vulnerable ecosystems.","vi":"Các nhóm bảo vệ môi trường vận động chính phủ ban hành các biện pháp kiểm soát ô nhiễm công nghiệp nghiêm ngặt hơn và bảo vệ các hệ sinh thái dễ bị tổn thương.","audioKind":"ex2"}],"collocations":[{"en":"hotel lobby","vi":"sảnh khách sạn"},{"en":"lobby for reform","vi":"vận động cải cách"},{"en":"lobby against a proposal","vi":"vận động phản đối một đề xuất"},{"en":"the business lobby","vi":"giới vận động thương mại"}],"wordFamily":["lobbyist (n.)","lobbying (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Vận động ủng hộ dùng lobby for, phản đối dùng lobby against.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_congestion', 'en-b2-61', 'congestion', '/kənˈdʒestʃən/', 'B2', 'tình trạng tắc nghẽn; sự ùn tắc; tình trạng sung huyết; chứng nghẹt mũi', 'n.', 'congested (adj.)', NULL, 'Thường là danh từ không đếm được; traffic congestion dùng để chỉ tình trạng ùn tắc giao thông.', 'We left early to avoid congestion near the bridge.', NULL, 'Chúng tôi xuất phát sớm để tránh ùn tắc gần cây cầu.', '{"wordId":"congestion","ukIpa":"/kənˈdʒestʃən/","usIpa":"/kənˈdʒestʃən/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"a situation where overcrowding prevents easy movement","vi":"tình trạng tắc nghẽn; sự ùn tắc"},{"pos":"n.","en":"a blockage caused by excess mucus or blood","vi":"tình trạng sung huyết; chứng nghẹt mũi"}],"examples":[{"en":"We left early to avoid congestion near the bridge.","vi":"Chúng tôi xuất phát sớm để tránh ùn tắc gần cây cầu.","audioKind":"ex"},{"en":"Investing in reliable public transport can ease traffic congestion while reducing air pollution in major cities.","vi":"Đầu tư vào giao thông công cộng đáng tin cậy có thể làm giảm tình trạng tắc nghẽn giao thông đồng thời giảm ô nhiễm không khí ở các thành phố lớn.","audioKind":"ex2"}],"collocations":[{"en":"traffic congestion","vi":"tắc nghẽn giao thông"},{"en":"ease congestion","vi":"giảm bớt ùn tắc"},{"en":"nasal congestion","vi":"chứng nghẹt mũi"}],"wordFamily":["congested (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; traffic congestion dùng để chỉ tình trạng ùn tắc giao thông.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_61_1', 'en-b2-61', 'Cách dùng “residence” (n.) — nơi cư trú; nhà ở', 'place of residence  ·  proof of residence  ·  permanent residence', '"Residence" mang sắc thái trang trọng; người dân/cư dân là "resident", còn khu dân cư dùng tính từ "residential".', 'Họ từ (Word Family): reside (v.), resident (n.), residential (adj.) | Đồng nghĩa: home, dwelling', '[{"hanzi":"Their new residence overlooks a quiet garden near the river.","pinyin":"","meaning":"Nơi ở mới của họ nhìn ra một khu vườn yên tĩnh gần bờ sông."},{"hanzi":"Applicants may need to provide proof of residence before they can access certain local services.","pinyin":"","meaning":"Người nộp đơn có thể cần cung cấp giấy xác nhận cư trú trước khi được tiếp cận một số dịch vụ địa phương."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_61_2', 'en-b2-61', 'Cách dùng “construction” (n.) — sự xây dựng; công trình xây dựng', 'under construction  ·  construction site  ·  construction industry', 'Danh từ không đếm được khi chỉ quá trình xây dựng; dùng under construction để chỉ việc đang thi công.', 'Họ từ (Word Family): construct (v.), reconstruct (v.), reconstruction (n.) | Đồng nghĩa: building · Trái nghĩa: demolition', '[{"hanzi":"Construction of the new bridge started early this morning.","pinyin":"","meaning":"Công việc xây dựng cây cầu mới đã bắt đầu vào sáng sớm nay."},{"hanzi":"The construction of energy-efficient housing can reduce household bills and limit the environmental impact of urban growth.","pinyin":"","meaning":"Việc xây dựng nhà ở tiết kiệm năng lượng có thể giảm hóa đơn sinh hoạt và hạn chế tác động môi trường của quá trình đô thị hóa."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_61_3', 'en-b2-61', 'Cách dùng “terrace” (n.) — sân hiên; ban công lớn; sân thượng', 'a roof terrace  ·  a sunny terrace  ·  rice terraces', 'Terrace thường là một khu vực ngoài trời lớn, không đồng nghĩa hoàn toàn với balcony (ban công nhỏ).', 'Họ từ (Word Family): terraced (adj.), terracing (n.)', '[{"hanzi":"We had breakfast on the terrace overlooking the garden.","pinyin":"","meaning":"Chúng tôi ăn sáng trên sân hiên hướng ra khu vườn."},{"hanzi":"Farmers maintain each terrace carefully to reduce soil erosion and grow crops on steep mountain slopes.","pinyin":"","meaning":"Nông dân chăm sóc cẩn thận từng bậc ruộng bậc thang để giảm thiểu xói mòn đất và trồng trọt trên các sườn núi dốc."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_61_4', 'en-b2-61', 'Cách dùng “congestion” (n.) — tình trạng tắc nghẽn; sự ùn tắc', 'traffic congestion  ·  ease congestion  ·  nasal congestion', 'Thường là danh từ không đếm được; traffic congestion dùng để chỉ tình trạng ùn tắc giao thông.', 'Họ từ (Word Family): congested (adj.)', '[{"hanzi":"We left early to avoid congestion near the bridge.","pinyin":"","meaning":"Chúng tôi xuất phát sớm để tránh ùn tắc gần cây cầu."},{"hanzi":"Investing in reliable public transport can ease traffic congestion while reducing air pollution in major cities.","pinyin":"","meaning":"Đầu tư vào giao thông công cộng đáng tin cậy có thể làm giảm tình trạng tắc nghẽn giao thông đồng thời giảm ô nhiễm không khí ở các thành phố lớn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_61_1', 'en-b2-61', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_61_1_1', 'ten_b2_61_1', 'residence', 'Their new residence overlooks a quiet garden near the river.', 'Their new residence overlooks a quiet garden near the river.', '/ˈrezɪdəns/', 'Nơi ở mới của họ nhìn ra một khu vườn yên tĩnh gần bờ sông.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_61_1_2', 'ten_b2_61_1', 'outskirts', 'Their new house is on the outskirts of town.', 'Their new house is on the outskirts of town.', '/ˈaʊtskɜːrts/', 'Ngôi nhà mới của họ nằm ở vùng ngoại ô của thị trấn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_61_1_3', 'ten_b2_61_1', 'estate', 'We walked past the lake on the old country estate.', 'We walked past the lake on the old country estate.', '/ɪˈsteɪt/', 'Chúng tôi đi bộ qua hồ nước nằm trong điền trang vùng đồng quê cổ kính.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_61_1_4', 'ten_b2_61_1', 'terrace', 'We had breakfast on the terrace overlooking the garden.', 'We had breakfast on the terrace overlooking the garden.', '/ˈterəs/', 'Chúng tôi ăn sáng trên sân hiên hướng ra khu vườn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_61_1_5', 'ten_b2_61_1', 'rebuild', 'We plan to rebuild the garden wall this weekend.', 'We plan to rebuild the garden wall this weekend.', '/ˌriːˈbɪld/', 'Chúng tôi dự định xây dựng lại bức tường vườn vào cuối tuần này.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_61_1_6', 'ten_b2_61_1', 'curved', 'A curved path leads from our gate to the pond.', 'A curved path leads from our gate to the pond.', '/kɝːvd/', 'Một con đường uốn lượn dẫn từ cổng nhà chúng tôi đến cái ao.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_61_1_7', 'ten_b2_61_1', 'landlord', 'Our landlord came over to fix the leaking tap.', 'Our landlord came over to fix the leaking tap.', '/ˈlændlɔːrd/', 'Chủ nhà của chúng tôi đã qua để sửa cái vòi nước bị rò rỉ.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_61_1_8', 'ten_b2_61_1', 'situated', 'Our hotel is situated beside a quiet mountain lake.', 'Our hotel is situated beside a quiet mountain lake.', '/ˈsɪtʃueɪtɪd/', 'Khách sạn của chúng tôi tọa lạc bên cạnh một hồ nước núi yên tĩnh.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_61_1_1', 'en-b2-61', 'ten_b2_61_1', 'listening', 'listening', 'Their new residence overlooks a quiet garden near the river.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chủ nhà của chúng tôi đã qua để sửa cái vòi nước bị rò rỉ.","Chúng tôi dự định xây dựng lại bức tường vườn vào cuối tuần này.","Tôi sẽ đợi ở sảnh trong khi bạn đi lấy vali.","Nơi ở mới của họ nhìn ra một khu vườn yên tĩnh gần bờ sông."]'::jsonb, 3, 'Their new residence overlooks a quiet garden near the river. → Nơi ở mới của họ nhìn ra một khu vườn yên tĩnh gần bờ sông.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_61_1_2', 'en-b2-61', 'ten_b2_61_1', 'listening', 'listening', 'Their new house is on the outskirts of town.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Khách sạn của chúng tôi tọa lạc bên cạnh một hồ nước núi yên tĩnh.","Ngôi nhà mới của họ nằm ở vùng ngoại ô của thị trấn.","Thẻ hội viên phòng gym của tôi sắp đến hạn gia hạn vào tháng tới.","Chúng tôi đi bộ qua hồ nước nằm trong điền trang vùng đồng quê cổ kính."]'::jsonb, 1, 'Their new house is on the outskirts of town. → Ngôi nhà mới của họ nằm ở vùng ngoại ô của thị trấn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_61_1_3', 'en-b2-61', 'ten_b2_61_1', 'listening', 'listening', 'We walked past the lake on the old country estate.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đi bộ qua hồ nước nằm trong điền trang vùng đồng quê cổ kính.","Một chiếc cần trục đã nâng thanh dầm nặng lên phía trên mái nhà.","Họ đã mua một ngôi nhà trệt có khu vườn nhỏ ngập nắng.","Ngôi nhà mới của họ nằm ở vùng ngoại ô của thị trấn."]'::jsonb, 0, 'We walked past the lake on the old country estate. → Chúng tôi đi bộ qua hồ nước nằm trong điền trang vùng đồng quê cổ kính.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_61_2', 'en-b2-61', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_61_2_1', 'ten_b2_61_2', 'residence', 'Applicants may need to provide proof of residence before they can access certain local services.', 'Applicants may need to provide proof of residence before they can access certain local services.', '/ˈrezɪdəns/', 'Người nộp đơn có thể cần cung cấp giấy xác nhận cư trú trước khi được tiếp cận một số dịch vụ địa phương.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_61_2_2', 'ten_b2_61_2', 'outskirts', 'Building affordable homes on the outskirts may reduce housing costs but increase residents'' dependence on private cars.', 'Building affordable homes on the outskirts may reduce housing costs but increase residents'' dependence on private cars.', '/ˈaʊtskɜːrts/', 'Việc xây dựng nhà ở giá rẻ ở ngoại ô có thể giảm chi phí nhà ở nhưng lại làm tăng sự phụ thuộc của cư dân vào xe hơi cá nhân.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_61_2_3', 'ten_b2_61_2', 'estate', 'New housing estates should include green spaces and reliable transport links to nearby employment centres.', 'New housing estates should include green spaces and reliable transport links to nearby employment centres.', '/ɪˈsteɪt/', 'Các khu nhà ở mới nên được tích hợp không gian xanh cùng hệ thống giao thông thuận tiện kết nối đến các trung tâm việc làm lân cận.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_61_2_4', 'ten_b2_61_2', 'terrace', 'Farmers maintain each terrace carefully to reduce soil erosion and grow crops on steep mountain slopes.', 'Farmers maintain each terrace carefully to reduce soil erosion and grow crops on steep mountain slopes.', '/ˈterəs/', 'Nông dân chăm sóc cẩn thận từng bậc ruộng bậc thang để giảm thiểu xói mòn đất và trồng trọt trên các sườn núi dốc.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_61_2_5', 'ten_b2_61_2', 'rebuild', 'After severe flooding, local authorities must rebuild essential infrastructure and help affected communities recover.', 'After severe flooding, local authorities must rebuild essential infrastructure and help affected communities recover.', '/ˌriːˈbɪld/', 'Sau trận lũ lụt nghiêm trọng, chính quyền địa phương phải tái thiết cơ sở hạ tầng thiết yếu và giúp các cộng đồng bị ảnh hưởng phục hồi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_61_2_6', 'ten_b2_61_2', 'curved', 'Curved building designs can create distinctive urban landmarks, although they may require more complex construction techniques.', 'Curved building designs can create distinctive urban landmarks, although they may require more complex construction techniques.', '/kɝːvd/', 'Thiết kế kiến trúc cong có thể tạo ra những điểm nhấn đô thị độc đáo, mặc dù chúng có thể đòi hỏi các kỹ thuật thi công phức tạp hơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_61_2_1', 'en-b2-61', 'ten_b2_61_2', 'listening', 'listening', 'Applicants may need to provide proof of residence before they can access certain local services.', NULL, 'Trong câu vừa nghe, từ “residence” mang nghĩa nào sau đây?', '["lớn tuổi hơn (thường trong cùng gia đình)","sự viện trợ; sự cứu trợ; tiền trợ giúp","nơi cư trú; nhà ở","tự truyện"]'::jsonb, 2, '“residence” (/ˈrezɪdəns/): nơi cư trú; nhà ở. Câu đầy đủ: Applicants may need to provide proof of residence before they can access certain local services.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_61_2_2', 'en-b2-61', 'ten_b2_61_2', 'listening', 'listening', 'Building affordable homes on the outskirts may reduce housing costs but increase residents'' dependence on private cars.', NULL, 'Trong câu vừa nghe, từ “outskirts” mang nghĩa nào sau đây?', '["chuyên gia tâm lý; nhà tâm lý học","vùng ngoại ô; vùng ven đô","mí mắt; mi mắt","bảo thủ; thủ cựu"]'::jsonb, 1, '“outskirts” (/ˈaʊtskɜːrts/): vùng ngoại ô; vùng ven đô. Câu đầy đủ: Building affordable homes on the outskirts may reduce housing costs but increase residents'' dependence on private cars.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
