INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_61_2', 'en-b2-61', NULL, 'comprehensive_test', 'listening', 'Their new house is on the outskirts of town.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ngôi nhà mới của họ nằm ở vùng ngoại ô của thị trấn.","Việc mở rộng nhà bếp đã cho chúng tôi không gian để kê một chiếc bàn.","Họ đã mua một ngôi nhà trệt có khu vườn nhỏ ngập nắng.","Một chiếc cần trục đã nâng thanh dầm nặng lên phía trên mái nhà."]'::jsonb, 0, 'Their new house is on the outskirts of town. → Ngôi nhà mới của họ nằm ở vùng ngoại ô của thị trấn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_61_3', 'en-b2-61', NULL, 'comprehensive_test', 'listening', 'estate', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["điền trang; thái ấp","thay đổi; biến đổi","thuộc về tinh thần; thuộc về tâm hồn","hiên nhà; mái hiên"]'::jsonb, 0, 'estate (/ɪˈsteɪt/) → điền trang; thái ấp; khu dân cư; khu công nghiệp; tài sản; di sản', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_61_4', 'en-b2-61', NULL, 'comprehensive_test', 'listening', 'We had breakfast on the terrace overlooking the garden.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi ăn sáng trên sân hiên hướng ra khu vườn.","Tôi sẽ đợi ở sảnh trong khi bạn đi lấy vali.","Họ đã mua một ngôi nhà trệt có khu vườn nhỏ ngập nắng.","Thẻ hội viên phòng gym của tôi sắp đến hạn gia hạn vào tháng tới."]'::jsonb, 0, 'We had breakfast on the terrace overlooking the garden. → Chúng tôi ăn sáng trên sân hiên hướng ra khu vườn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_61_5', 'en-b2-61', NULL, 'comprehensive_test', 'listening', 'rebuild', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["viên nang; viên con nhộng","sự kiểm tra, sự thanh tra (xem xét kỹ lưỡng để đánh giá tình trạng, chất lượng hoặc độ an toàn)","nhà quản lý cấp cao; giám đốc điều hành","xây dựng lại; tái thiết"]'::jsonb, 3, 'rebuild (/ˌriːˈbɪld/) → xây dựng lại; tái thiết; khôi phục; vực dậy (niềm tin, kinh tế, mối quan hệ)', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_61_6', 'en-b2-61', NULL, 'comprehensive_test', 'listening', 'A curved path leads from our gate to the pond.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một con đường uốn lượn dẫn từ cổng nhà chúng tôi đến cái ao.","Tôi sẽ đợi ở sảnh trong khi bạn đi lấy vali.","Rẽ trái ở ngã tư cạnh tiệm bánh nhé.","Việc mở rộng nhà bếp đã cho chúng tôi không gian để kê một chiếc bàn."]'::jsonb, 0, 'A curved path leads from our gate to the pond. → Một con đường uốn lượn dẫn từ cổng nhà chúng tôi đến cái ao.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_61_7', 'en-b2-61', NULL, 'comprehensive_test', 'listening', 'landlord', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thỉnh thoảng; đôi khi; không thường xuyên","chủ nhà; chủ đất (cho thuê)","nhúng; chấm","thuộc Bắc Cực"]'::jsonb, 1, 'landlord (/ˈlændlɔːrd/) → chủ nhà; chủ đất (cho thuê); chủ quán rượu; chủ quán trọ', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_61_8', 'en-b2-61', NULL, 'comprehensive_test', 'listening', 'Our hotel is situated beside a quiet mountain lake.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đi bộ qua hồ nước nằm trong điền trang vùng đồng quê cổ kính.","Những chiếc hộp cũ này chiếm phần lớn căn phòng trống của chúng tôi.","Khách sạn của chúng tôi tọa lạc bên cạnh một hồ nước núi yên tĩnh.","Chúng tôi dự định xây dựng lại bức tường vườn vào cuối tuần này."]'::jsonb, 2, 'Our hotel is situated beside a quiet mountain lake. → Khách sạn của chúng tôi tọa lạc bên cạnh một hồ nước núi yên tĩnh.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
