INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_61_18', 'en-b2-61', NULL, 'comprehensive_test', 'reading', NULL, 'Applicants may need to provide proof of residence before they can access certain local services.', 'Dựa vào câu trên, từ “residence” có nghĩa phù hợp nhất là gì?', '["đánh bóng; làm cho sáng bóng","sự tức giận; cơn giận","làm cho ổn định, giữ vững, trở nên vững vàng","nơi cư trú; nhà ở"]'::jsonb, 3, 'residence: nơi cư trú; nhà ở; sự cư trú; thời gian lưu trú. Dịch cả câu: Người nộp đơn có thể cần cung cấp giấy xác nhận cư trú trước khi được tiếp cận một số dịch vụ địa phương.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_61_19', 'en-b2-61', NULL, 'comprehensive_test', 'reading', NULL, 'Building affordable homes on the outskirts may reduce housing costs but increase residents'' dependence on private cars.', 'Dựa vào câu trên, từ “outskirts” có nghĩa phù hợp nhất là gì?', '["làm phân tâm; làm xao nhãng","vùng ngoại ô; vùng ven đô","thuốc chữa bệnh; việc dùng thuốc điều trị","thuộc về gen; di truyền"]'::jsonb, 1, 'outskirts: vùng ngoại ô; vùng ven đô. Dịch cả câu: Việc xây dựng nhà ở giá rẻ ở ngoại ô có thể giảm chi phí nhà ở nhưng lại làm tăng sự phụ thuộc của cư dân vào xe hơi cá nhân.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_61_20', 'en-b2-61', NULL, 'comprehensive_test', 'reading', NULL, 'New housing estates should include green spaces and reliable transport links to nearby employment centres.', 'Dựa vào câu trên, từ “estate” có nghĩa phù hợp nhất là gì?', '["đạt điều kiện; đủ tiêu chuẩn","điền trang; thái ấp","sự phỏng đoán; sự phỏng đoán không có đủ bằng chứng chắc chắn","cắt tỉa; cắt bớt một chút để làm gọn gàng hoặc giảm bớt"]'::jsonb, 1, 'estate: điền trang; thái ấp; khu dân cư; khu công nghiệp; tài sản; di sản. Dịch cả câu: Các khu nhà ở mới nên được tích hợp không gian xanh cùng hệ thống giao thông thuận tiện kết nối đến các trung tâm việc làm lân cận.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_61_21', 'en-b2-61', NULL, 'comprehensive_test', 'reading', NULL, 'Farmers maintain each terrace carefully to reduce soil erosion and grow crops on steep mountain slopes.', 'Dựa vào câu trên, từ “terrace” có nghĩa phù hợp nhất là gì?', '["máy bay chở khách cỡ lớn; máy bay phản lực thương mại","vô cùng ngốc nghếch; phi lý; nguy hiểm","khoản quyên góp; khoản đóng góp; vật phẩm từ thiện","sân hiên; ban công lớn; sân thượng"]'::jsonb, 3, 'terrace: sân hiên; ban công lớn; sân thượng; ruộng bậc thang; bậc thềm; nhà liền kề (các ngôi nhà có chung tường ngăn). Dịch cả câu: Nông dân chăm sóc cẩn thận từng bậc ruộng bậc thang để giảm thiểu xói mòn đất và trồng trọt trên các sườn núi dốc.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_61_22', 'en-b2-61', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hoành tráng; nguy nga”', '["grand","canyon","challenging","yarn"]'::jsonb, 0, 'hoành tráng; nguy nga → grand (/ɡrænd/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_61_23', 'en-b2-61', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sảnh; tiền sảnh; phòng đợi”', '["lobby","ballroom","peculiar","literary"]'::jsonb, 0, 'sảnh; tiền sảnh; phòng đợi → lobby (/ˈlɑːbi/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_61_24', 'en-b2-61', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tình trạng tắc nghẽn; sự ùn tắc”', '["significance","assign","congestion","replacement"]'::jsonb, 2, 'tình trạng tắc nghẽn; sự ùn tắc → congestion (/kənˈdʒestʃən/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-62', 'en', 'Bài 62: Đô thị & Kiến trúc (2) - CEFR B2', 'CEFR B2', 'B2 · Đô thị', '24 từ vựng Tiếng Anh CEFR B2 chủ đề đô thị & kiến trúc kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4062, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_congested', 'en-b2-62', 'congested', '/kənˈdʒestɪd/', 'B2', 'quá đông đúc, tắc nghẽn (giao thông hoặc người); bị nghẹt, xung huyết (mũi hoặc cơ thể)', 'adj.', 'congest (v.), congestion (n.), decongestant (n.)', 'Đồng nghĩa: crowded, blocked, clogged · Trái nghĩa: clear', 'Từ này vừa có thể dùng để mô tả tình trạng giao thông tắc nghẽn, vừa dùng cho tình trạng nghẹt mũi hoặc các bộ phận cơ thể bị tắc nghẽn.', 'The roads were so congested that we walked home.', NULL, 'Đường sá tắc nghẽn đến mức chúng tôi phải đi bộ về nhà.', '{"wordId":"congested","ukIpa":"/kənˈdʒestɪd/","usIpa":"/kənˈdʒestɪd/","cefr":"B2","topic":"city","senses":[{"pos":"adj.","en":"Too crowded with traffic or people to allow easy movement.","vi":"quá đông đúc, tắc nghẽn (giao thông hoặc người)"},{"pos":"adj.","en":"Blocked by too much mucus or blood.","vi":"bị nghẹt, xung huyết (mũi hoặc cơ thể)"}],"examples":[{"en":"The roads were so congested that we walked home.","vi":"Đường sá tắc nghẽn đến mức chúng tôi phải đi bộ về nhà.","audioKind":"ex"},{"en":"Investing in reliable public transport can reduce traffic on congested roads and improve air quality in cities.","vi":"Đầu tư vào hệ thống giao thông công cộng đáng tin cậy có thể làm giảm lưu lượng xe trên các tuyến đường quá tải và cải thiện chất lượng không khí trong thành phố.","audioKind":"ex2"}],"collocations":[{"en":"congested roads","vi":"các tuyến đường tắc nghẽn"},{"en":"heavily congested","vi":"tắc nghẽn nghiêm trọng"},{"en":"a congested city centre","vi":"trung tâm thành phố đông đúc"},{"en":"a congested nose","vi":"nghẹt mũi"}],"wordFamily":["congest (v.)","congestion (n.)","decongestant (n.)"],"synonyms":["crowded","blocked","clogged"],"antonyms":["clear"],"tipVi":"Từ này vừa có thể dùng để mô tả tình trạng giao thông tắc nghẽn, vừa dùng cho tình trạng nghẹt mũi hoặc các bộ phận cơ thể bị tắc nghẽn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_renovation', 'en-b2-62', 'renovation', '/ˌrenəˈveɪʃən/', 'B2', 'sự cải tạo; sự sửa sang lại', 'n.', 'renovate (v.), renovator (n.)', 'Đồng nghĩa: refurbishment', 'Chủ yếu dùng cho việc sửa chữa kiến trúc; các cuộc cải cách hệ thống thường không dùng từ này.', 'We stayed with friends during the renovation of our kitchen.', NULL, 'Chúng tôi đã ở nhờ nhà bạn bè trong thời gian phòng bếp được sửa sang.', '{"wordId":"renovation","ukIpa":"/ˌrenəˈveɪʃən/","usIpa":"/ˌrenəˈveɪʃən/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"The process of repairing and improving a building or room.","vi":"sự cải tạo; sự sửa sang lại"}],"examples":[{"en":"We stayed with friends during the renovation of our kitchen.","vi":"Chúng tôi đã ở nhờ nhà bạn bè trong thời gian phòng bếp được sửa sang.","audioKind":"ex"},{"en":"The renovation of historic buildings can preserve local identity while providing suitable spaces for modern businesses.","vi":"Việc cải tạo các tòa nhà lịch sử có thể bảo tồn nét đặc trưng địa phương đồng thời cung cấp không gian phù hợp cho các doanh nghiệp hiện đại.","audioKind":"ex2"}],"collocations":[{"en":"undergo renovation","vi":"được đại tu sửa chữa"},{"en":"extensive renovation","vi":"cải tạo quy mô lớn"},{"en":"renovation work","vi":"công iệc sửa chữa"},{"en":"renovation costs","vi":"chi phí cải tạo"}],"wordFamily":["renovate (v.)","renovator (n.)"],"synonyms":["refurbishment"],"antonyms":[],"tipVi":"Chủ yếu dùng cho việc sửa chữa kiến trúc; các cuộc cải cách hệ thống thường không dùng từ này.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_collapse', 'en-b2-62', 'collapse', '/kəˈlæps/', 'B2', 'đổ sụp; sụp đổ; ngã gục; sự sụp đổ; sự suy sụp hoàn toàn', 'v.', 'collapsible (adj.)', NULL, 'Khi diễn tả sự đổ sụp hoặc sụp đổ, đây thường là nội động từ và không dùng ở thể bị động.', 'The old garden shed collapsed during last night''s storm.', NULL, 'Căn chòi làm vườn cũ đã đổ sụp trong trận bão đêm qua.', '{"wordId":"collapse","ukIpa":"/kəˈlæps/","usIpa":"/kəˈlæps/","cefr":"B2","topic":"city","senses":[{"pos":"v.","en":"To fall down suddenly or stop functioning completely.","vi":"đổ sụp; sụp đổ; ngã gục"},{"pos":"n.","en":"A sudden fall or complete failure of something.","vi":"sự sụp đổ; sự suy sụp hoàn toàn"}],"examples":[{"en":"The old garden shed collapsed during last night''s storm.","vi":"Căn chòi làm vườn cũ đã đổ sụp trong trận bão đêm qua.","audioKind":"ex"},{"en":"Poor maintenance can cause bridges to collapse, making regular inspections essential for public safety.","vi":"Việc bảo trì kém có thể khiến cầu sập, do đó việc kiểm tra thường xuyên là tối quan trọng đối với an toàn công cộng.","audioKind":"ex2"}],"collocations":[{"en":"a building collapses","vi":"tòa nhà sụp đổ"},{"en":"economic collapse","vi":"sụp đổ kinh tế"},{"en":"collapse from exhaustion","vi":"kiệt sức ngã gục"},{"en":"the collapse of negotiations","vi":"cuộc đàm phán sụp đổ"}],"wordFamily":["collapsible (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi diễn tả sự đổ sụp hoặc sụp đổ, đây thường là nội động từ và không dùng ở thể bị động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dome', 'en-b2-62', 'dome', '/doʊm/', 'B2', 'vòm; mái vòm tròn; vật có hình mái vòm', 'n.', 'domed (adj.)', NULL, 'dome chỉ kết cấu vòm bán cầu; domed dùng để chỉ tính từ có hình mái vòm.', 'Sunlight streamed through the glass dome above the entrance.', NULL, 'Ánh nắng chiếu rọi qua vòm kính ở phía trên lối vào.', '{"wordId":"dome","ukIpa":"/dəʊm/","usIpa":"/doʊm/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"a rounded roof shaped like half a ball","vi":"vòm; mái vòm tròn"},{"pos":"n.","en":"an object or structure shaped like half a ball","vi":"vật có hình mái vòm"}],"examples":[{"en":"Sunlight streamed through the glass dome above the entrance.","vi":"Ánh nắng chiếu rọi qua vòm kính ở phía trên lối vào.","audioKind":"ex"},{"en":"The museum''s central dome allows natural light into the building, reducing the need for artificial lighting during daylight hours.","vi":"Mái vòm trung tâm của viện bảo tàng cho phép ánh sáng tự nhiên chiếu vào tòa nhà, giúp giảm nhu cầu sử dụng đèn nhân tạo vào ban ngày.","audioKind":"ex2"}],"collocations":[{"en":"a glass dome","vi":"mái vòm bằng kính"},{"en":"a domed roof","vi":"mái nhà có vòm"},{"en":"beneath the dome","vi":"dưới mái vòm"}],"wordFamily":["domed (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"dome chỉ kết cấu vòm bán cầu; domed dùng để chỉ tính từ có hình mái vòm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_resident', 'en-b2-62', 'resident', '/ˈrezɪdənt/', 'B2', 'cư dân; người dân; cư trú; thường trú', 'n.', 'reside (v.), residence (n.), residential (adj.), residency (n.)', 'Đồng nghĩa: inhabitant', '"resident" chỉ người; "residential" miêu tả nhà ở hoặc khu dân cư.', 'Every resident received a key to the shared garden.', NULL, 'Mỗi cư dân đều nhận được một chiếc chìa khóa vào khu vườn chung.', '{"wordId":"resident","ukIpa":"/ˈrezɪdənt/","usIpa":"/ˈrezɪdənt/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"Someone who lives in a particular place.","vi":"cư dân; người dân"},{"pos":"adj.","en":"Living or working regularly in a particular place.","vi":"cư trú; thường trú"}],"examples":[{"en":"Every resident received a key to the shared garden.","vi":"Mỗi cư dân đều nhận được một chiếc chìa khóa vào khu vườn chung.","audioKind":"ex"},{"en":"Local residents should be consulted before major changes are made to roads and public spaces.","vi":"Cư dân địa phương cần được tham vấn trước khi thực hiện các thay đổi lớn đối với đường sá và không gian công cộng.","audioKind":"ex2"}],"collocations":[{"en":"local residents","vi":"cư dân địa phương"},{"en":"permanent resident","vi":"thường trú nhân"},{"en":"resident in","vi":"cư trú tại"}],"wordFamily":["reside (v.)","residence (n.)","residential (adj.)","residency (n.)"],"synonyms":["inhabitant"],"antonyms":[],"tipVi":"\"resident\" chỉ người; \"residential\" miêu tả nhà ở hoặc khu dân cư.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fringe', 'en-b2-62', 'fringe', '/frɪndʒ/', 'B2', 'rìa; vùng ngoại vi; tóc mái; tua rua; diềm', 'n.', 'fringed (adj.)', 'Đồng nghĩa: edge, margin · Trái nghĩa: centre', '"Tóc mái" trong tiếng Anh-Anh dùng "fringe", tiếng Anh-Mỹ thường dùng "bangs".', 'Their cottage stands on the fringe of the forest.', NULL, 'Ngôi nhà nhỏ của họ nằm ở rìa khu rừng.', '{"wordId":"fringe","ukIpa":"/frɪndʒ/","usIpa":"/frɪndʒ/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"the outer edge of a place or group","vi":"rìa; vùng ngoại vi"},{"pos":"n.","en":"hair cut to hang over the forehead","vi":"tóc mái"},{"pos":"n.","en":"hanging threads used to decorate the edge of fabric","vi":"tua rua; diềm"}],"examples":[{"en":"Their cottage stands on the fringe of the forest.","vi":"Ngôi nhà nhỏ của họ nằm ở rìa khu rừng.","audioKind":"ex"},{"en":"Affordable housing on the urban fringe often leaves residents dependent on cars for their daily journeys.","vi":"Nhà ở giá rẻ ở vùng ngoại vi thành phố thường khiến cư dân phải phụ thuộc vào ô tô cho việc đi lại hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"urban fringe","vi":"vùng ngoại vi đô thị"},{"en":"on the fringes of society","vi":"ở bên lề xã hội"},{"en":"cut a fringe","vi":"cắt tóc mái"},{"en":"a fringe of trees","vi":"một hàng cây (bao quanh)"}],"wordFamily":["fringed (adj.)"],"synonyms":["edge","margin"],"antonyms":["centre"],"tipVi":"\"Tóc mái\" trong tiếng Anh-Anh dùng \"fringe\", tiếng Anh-Mỹ thường dùng \"bangs\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exterior', 'en-b2-62', 'exterior', '/ɪkˈstɪriər/', 'B2', 'bề ngoài; phần bên ngoài; thuộc về bên ngoài', 'n.', 'exteriorly (adv.)', 'Đồng nghĩa: outside, outer · Trái nghĩa: interior', 'exterior chỉ bên ngoài hoặc bề ngoài; interior chỉ bên trong.', 'They painted the exterior of their house pale blue.', NULL, 'Họ sơn phần bên ngoài ngôi nhà của mình thành màu xanh nhạt.', '{"wordId":"exterior","ukIpa":"/ɪkˈstɪəriə/","usIpa":"/ɪkˈstɪriər/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"The outside surface or appearance of something.","vi":"bề ngoài; phần bên ngoài"},{"pos":"adj.","en":"On or relating to the outside of something.","vi":"thuộc về bên ngoài"}],"examples":[{"en":"They painted the exterior of their house pale blue.","vi":"Họ sơn phần bên ngoài ngôi nhà của mình thành màu xanh nhạt.","audioKind":"ex"},{"en":"Improving a building''s exterior can protect it from weather damage while preserving its historical character.","vi":"Việc cải thiện phần bên ngoài của một tòa nhà có thể giúp bảo vệ nó khỏi tác động của thời tiết đồng thời giữ gìn nét đặc trưng lịch sử của nó.","audioKind":"ex2"}],"collocations":[{"en":"the exterior of a building","vi":"bên ngoài của một tòa nhà"},{"en":"exterior walls","vi":"tường bên ngoài"},{"en":"exterior paint","vi":"sơn ngoại thất"}],"wordFamily":["exteriorly (adv.)"],"synonyms":["outside","outer"],"antonyms":["interior"],"tipVi":"exterior chỉ bên ngoài hoặc bề ngoài; interior chỉ bên trong.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mansion', 'en-b2-62', 'mansion', '/ˈmænʃən/', 'B2', 'biệt thự lớn; dinh thự', 'n.', NULL, NULL, 'Thường chỉ những căn nhà lớn và hoành tráng, không phải là tòa nhà văn phòng thông thường.', 'An enormous mansion stood behind the tall iron gates.', NULL, 'Một dinh thự khổng lồ sừng sững hiện lên phía sau những cánh cổng sắt cao.', '{"wordId":"mansion","ukIpa":"/ˈmænʃən/","usIpa":"/ˈmænʃən/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"A very large, impressive house.","vi":"biệt thự lớn; dinh thự"}],"examples":[{"en":"An enormous mansion stood behind the tall iron gates.","vi":"Một dinh thự khổng lồ sừng sững hiện lên phía sau những cánh cổng sắt cao.","audioKind":"ex"},{"en":"The historic mansion has been converted into a museum to preserve the region''s cultural heritage.","vi":"Dinh thự lịch sử này đã được cải tạo thành bảo tàng nhằm bảo tồn di sản văn hóa của vùng.","audioKind":"ex2"}],"collocations":[{"en":"a luxurious mansion","vi":"biệt thự sang trọng"},{"en":"a historic mansion","vi":"dinh thự lịch sử"},{"en":"a sprawling mansion","vi":"biệt thự rộng thênh thang"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ những căn nhà lớn và hoành tráng, không phải là tòa nhà văn phòng thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pillar', 'en-b2-62', 'pillar', '/ˈpɪlər/', 'B2', 'cột; trụ (cấu trúc chống đỡ); trụ cột; cốt lõi (người hoặc nguyên tắc nâng đỡ quan trọng)', 'n.', NULL, 'Đồng nghĩa: column, support', 'pillar of có thể được dùng theo nghĩa bóng để chỉ trụ cột của một hệ thống hoặc nhân vật trung tâm trong một nhóm.', 'We sheltered from the rain behind a stone pillar.', NULL, 'Chúng tôi đứng trú mưa đằng sau một cây cột đá.', '{"wordId":"pillar","ukIpa":"/ˈpɪlə/","usIpa":"/ˈpɪlər/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"A strong upright structure that supports part of a building.","vi":"cột; trụ (cấu trúc chống đỡ)"},{"pos":"n.","en":"A person or principle providing essential support.","vi":"trụ cột; cốt lõi (người hoặc nguyên tắc nâng đỡ quan trọng)"}],"examples":[{"en":"We sheltered from the rain behind a stone pillar.","vi":"Chúng tôi đứng trú mưa đằng sau một cây cột đá.","audioKind":"ex"},{"en":"Accessible education is a central pillar of social development because it expands opportunities across generations.","vi":"Giáo dục dễ tiếp cận là trụ cột trung tâm của sự phát triển xã hội vì nó mở rộng cơ hội cho các thế hệ.","audioKind":"ex2"}],"collocations":[{"en":"a stone pillar","vi":"cột đá"},{"en":"a central pillar of","vi":"trụ cột trung tâm của"},{"en":"a pillar of the community","vi":"trụ cột của cộng đồng"}],"wordFamily":[],"synonyms":["column","support"],"antonyms":[],"tipVi":"pillar of có thể được dùng theo nghĩa bóng để chỉ trụ cột của một hệ thống hoặc nhân vật trung tâm trong một nhóm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_concrete', 'en-b2-62', 'concrete', '/ˈkɑːŋkriːt/', 'B2', 'bê tông; cụ thể; xác thực; bằng bê tông', 'n.', 'concretely (adv.)', 'Trái nghĩa: abstract', '"cement" là xi măng, là một trong những nguyên liệu để làm ra "concrete" (bê tông).', 'The workers poured wet concrete into the wooden frame.', NULL, 'Các công nhân đổ bê tông ướt vào khung gỗ.', '{"wordId":"concrete","ukIpa":"/ˈkɒŋkriːt/","usIpa":"/ˈkɑːŋkriːt/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"A building material made from cement, water, sand, and stones.","vi":"bê tông"},{"pos":"adj.","en":"Specific and based on facts rather than general ideas.","vi":"cụ thể; xác thực"},{"pos":"adj.","en":"Made of concrete.","vi":"bằng bê tông"}],"examples":[{"en":"The workers poured wet concrete into the wooden frame.","vi":"Các công nhân đổ bê tông ướt vào khung gỗ.","audioKind":"ex"},{"en":"Governments need concrete evidence before investing public money in expensive solutions to environmental problems.","vi":"Chính phủ cần có bằng chứng xác thực trước khi đầu tư tiền công vào các giải pháp tốn kém cho vấn đề môi trường.","audioKind":"ex2"}],"collocations":[{"en":"reinforced concrete","vi":"bê tông cốt thép"},{"en":"concrete evidence","vi":"bằng chứng xác thực"},{"en":"concrete steps","vi":"những bước đi cụ thể"},{"en":"concrete example","vi":"ví dụ cụ thể"}],"wordFamily":["concretely (adv.)"],"synonyms":[],"antonyms":["abstract"],"tipVi":"\"cement\" là xi măng, là một trong những nguyên liệu để làm ra \"concrete\" (bê tông).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_construct', 'en-b2-62', 'construct', '/kənˈstrʌkt/', 'B2', 'xây dựng; kiến tạo; xây dựng (lập luận, lý thuyết)', 'v.', 'construction (n.), constructor (n.), reconstruct (v.)', 'Đồng nghĩa: build, assemble · Trái nghĩa: demolish', 'Động từ nhấn âm tiết thứ hai; danh từ "construct" nhấn âm tiết thứ nhất.', 'Workers are constructing a wooden bridge across the stream.', NULL, 'Các công nhân đang xây dựng một cây cầu gỗ bắc qua suối.', '{"wordId":"construct","ukIpa":"/kənˈstrʌkt/","usIpa":"/kənˈstrʌkt/","cefr":"B2","topic":"city","senses":[{"pos":"v.","en":"to build something by putting parts or materials together","vi":"xây dựng; kiến tạo"},{"pos":"v.","en":"to carefully develop an argument, theory, or explanation","vi":"xây dựng (lập luận, lý thuyết)"}],"examples":[{"en":"Workers are constructing a wooden bridge across the stream.","vi":"Các công nhân đang xây dựng một cây cầu gỗ bắc qua suối.","audioKind":"ex"},{"en":"Students should learn to construct clear arguments supported by reliable evidence rather than personal assumptions.","vi":"Học sinh nên học cách xây dựng các lập luận rõ ràng được hỗ trợ bởi bằng chứng đáng tin cậy thay vì những giả định cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"construct a bridge","vi":"xây cầu"},{"en":"construct an argument","vi":"xây dựng lập luận"},{"en":"construct a model","vi":"xây dựng mô hình"}],"wordFamily":["construction (n.)","constructor (n.)","reconstruct (v.)"],"synonyms":["build","assemble"],"antonyms":["demolish"],"tipVi":"Động từ nhấn âm tiết thứ hai; danh từ \"construct\" nhấn âm tiết thứ nhất.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tenant', 'en-b2-62', 'tenant', '/ˈtenənt/', 'B2', 'người thuê nhà; người thuê đất', 'n.', 'tenancy (n.)', 'Đồng nghĩa: renter', 'tenant chỉ người đi thuê, còn landlord chỉ chủ nhà, đây là hai vai trò đối ứng trong giao dịch thuê nhà.', 'The new tenant brought plants for the balcony.', NULL, 'Người thuê nhà mới đã mang cây xanh đến để trang trí ban công.', '{"wordId":"tenant","ukIpa":"/ˈtenənt/","usIpa":"/ˈtenənt/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"someone who pays rent to use property or land","vi":"người thuê nhà; người thuê đất"}],"examples":[{"en":"The new tenant brought plants for the balcony.","vi":"Người thuê nhà mới đã mang cây xanh đến để trang trí ban công.","audioKind":"ex"},{"en":"Clear rental agreements protect both the tenant and the landlord by defining their responsibilities.","vi":"Các thỏa thuận cho thuê rõ ràng bảo vệ cả người thuê nhà và chủ nhà bằng cách xác định rõ trách nhiệm của mỗi bên.","audioKind":"ex2"}],"collocations":[{"en":"new tenant","vi":"người thuê nhà mới"},{"en":"prospective tenant","vi":"người thuê nhà tiềm năng"},{"en":"tenant rights","vi":"quyền của người thuê nhà"}],"wordFamily":["tenancy (n.)"],"synonyms":["renter"],"antonyms":[],"tipVi":"tenant chỉ người đi thuê, còn landlord chỉ chủ nhà, đây là hai vai trò đối ứng trong giao dịch thuê nhà.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_slum', 'en-b2-62', 'slum', '/slʌm/', 'B2', 'Khu ổ chuột', 'n.', NULL, NULL, 'Chỉ khu vực đô thị có điều kiện sống kém, không đồng nghĩa với mọi cộng đồng thu nhập thấp.', 'Their family shared a small room in a crowded slum.', NULL, 'Gia đình họ ở chung trong một căn phòng nhỏ thuộc khu ổ chuột đông đúc.', '{"wordId":"slum","ukIpa":"/slʌm/","usIpa":"/slʌm/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"a poor urban area with overcrowded housing in bad condition","vi":"Khu ổ chuột"}],"examples":[{"en":"Their family shared a small room in a crowded slum.","vi":"Gia đình họ ở chung trong một căn phòng nhỏ thuộc khu ổ chuột đông đúc.","audioKind":"ex"},{"en":"Improving sanitation and access to clean water can significantly reduce disease in densely populated slums.","vi":"Việc cải thiện hệ thống vệ sinh và khả năng tiếp cận nguồn nước sạch có thể làm giảm đáng kể dịch bệnh ở các khu ổ chuột đông dân cư.","audioKind":"ex2"}],"collocations":[{"en":"slum housing","vi":"nhà ở khu ổ chuột"},{"en":"slum residents","vi":"cư dân khu ổ chuột"},{"en":"slum clearance","vi":"giải tỏa khu ổ chuột"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ khu vực đô thị có điều kiện sống kém, không đồng nghĩa với mọi cộng đồng thu nhập thấp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_urban', 'en-b2-62', 'urban', '/ˈɝːbən/', 'B2', 'thuộc về thành phố; đô thị', 'adj.', 'urbanisation (n.), urbanise (v.)', 'Trái nghĩa: rural', 'urban chỉ đô thị, rural chỉ nông thôn.', 'Our urban garden sits between two tall apartment buildings.', NULL, 'Khu vườn đô thị của chúng tôi nằm giữa hai tòa nhà chung cư cao tầng.', '{"wordId":"urban","ukIpa":"/ˈɜːbən/","usIpa":"/ˈɝːbən/","cefr":"B2","topic":"city","senses":[{"pos":"adj.","en":"Relating to cities or towns rather than the countryside.","vi":"thuộc về thành phố; đô thị"}],"examples":[{"en":"Our urban garden sits between two tall apartment buildings.","vi":"Khu vườn đô thị của chúng tôi nằm giữa hai tòa nhà chung cư cao tầng.","audioKind":"ex"},{"en":"Rapid urban growth can increase pressure on public transport, housing, and essential services.","vi":"Sự phát triển đô thị nhanh chóng có thể làm tăng áp lực lên giao thông công cộng, nhà ở và các dịch vụ thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"urban development","vi":"phát triển đô thị"},{"en":"urban areas","vi":"các khu vực đô thị"},{"en":"urban planning","vi":"quy hoạch đô thị"},{"en":"urban population","vi":"dân số thành thị"}],"wordFamily":["urbanisation (n.)","urbanise (v.)"],"synonyms":[],"antonyms":["rural"],"tipVi":"urban chỉ đô thị, rural chỉ nông thôn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cement', 'en-b2-62', 'cement', '/sɪˈment/', 'B2', 'xi măng; củng cố; gắn kết', 'n.', NULL, NULL, 'cement là xi măng; còn concrete là bê tông bao gồm xi măng, cát và sỏi.', 'The builder mixed cement and water in a bucket.', NULL, 'Thợ xây đã trộn xi măng và nước trong một cái xô.', '{"wordId":"cement","ukIpa":"/sɪˈment/","usIpa":"/sɪˈment/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"Powder mixed with water to bind building materials together.","vi":"xi măng"},{"pos":"v.","en":"To make a relationship or agreement stronger.","vi":"củng cố; gắn kết"}],"examples":[{"en":"The builder mixed cement and water in a bucket.","vi":"Thợ xây đã trộn xi măng và nước trong một cái xô.","audioKind":"ex"},{"en":"Joint research projects can cement relationships between universities and encourage the exchange of scientific knowledge.","vi":"Các dự án nghiên cứu chung có thể củng cố mối quan hệ giữa các trường đại học và thúc đẩy việc trao đổi tri thức khoa học.","audioKind":"ex2"}],"collocations":[{"en":"a bag of cement","vi":"một bao xi măng"},{"en":"mix cement","vi":"trộn xi măng"},{"en":"cement a relationship","vi":"thắt chặt mối quan hệ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"cement là xi măng; còn concrete là bê tông bao gồm xi măng, cát và sỏi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_courtyard', 'en-b2-62', 'courtyard', '/ˈkɔːrtjɑːrd/', 'B2', 'sân trong; khoảng sân; giếng trời', 'n.', NULL, NULL, 'Nhấn mạnh không gian lộ thiên được bao bọc bởi các tòa nhà hoặc tường, không đồng nghĩa với khu vườn.', 'We ate breakfast in the courtyard beside a fountain.', NULL, 'Chúng tôi ăn sáng ở sân trong cạnh một đài phun nước.', '{"wordId":"courtyard","ukIpa":"/ˈkɔːtjɑːd/","usIpa":"/ˈkɔːrtjɑːrd/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"an outdoor area partly or completely enclosed by walls or buildings","vi":"sân trong; khoảng sân; giếng trời"}],"examples":[{"en":"We ate breakfast in the courtyard beside a fountain.","vi":"Chúng tôi ăn sáng ở sân trong cạnh một đài phun nước.","audioKind":"ex"},{"en":"Traditional houses with a central courtyard can provide natural ventilation while offering residents a private outdoor space.","vi":"Các ngôi nhà truyền thống có sân trong ở giữa có thể cung cấp thông gió tự nhiên đồng thời mang đến cho cư dân không gian ngoài trời riêng tư.","audioKind":"ex2"}],"collocations":[{"en":"central courtyard","vi":"sân trong chính"},{"en":"enclosed courtyard","vi":"sân trong khép kín"},{"en":"courtyard garden","vi":"vườn sân trong"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Nhấn mạnh không gian lộ thiên được bao bọc bởi các tòa nhà hoặc tường, không đồng nghĩa với khu vườn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_locate', 'en-b2-62', 'locate', '/ˈloʊkeɪt/', 'B2', 'xác định vị trí; tìm ra; đặt trụ sở; bố trí ở', 'v.', 'location (n.), relocate (v.), relocation (n.), locator (n.)', 'Đồng nghĩa: find, position', 'Để diễn tả ý nghĩa "located in/near", thông thường người ta dùng cụm từ này thay vì dùng trực tiếp động từ locate.', 'We finally located the missing keys behind the sofa.', NULL, 'Cuối cùng chúng tôi cũng tìm thấy những chiếc chìa khóa bị mất đằng sau chiếc ghế sofa.', '{"wordId":"locate","ukIpa":"/ləʊˈkeɪt/","usIpa":"/ˈloʊkeɪt/","cefr":"B2","topic":"city","senses":[{"pos":"v.","en":"To find the exact position of someone or something.","vi":"xác định vị trí; tìm ra"},{"pos":"v.","en":"To place something or establish a business somewhere.","vi":"đặt trụ sở; bố trí ở"}],"examples":[{"en":"We finally located the missing keys behind the sofa.","vi":"Cuối cùng chúng tôi cũng tìm thấy những chiếc chìa khóa bị mất đằng sau chiếc ghế sofa.","audioKind":"ex"},{"en":"Local authorities should locate new health centres near public transport routes to improve access for elderly residents.","vi":"Chính quyền địa phương nên đặt các trung tâm y tế mới gần các tuyến giao thông công cộng để giúp người cao tuổi dễ dàng tiếp cận hơn.","audioKind":"ex2"}],"collocations":[{"en":"locate a fault","vi":"xác định lỗi"},{"en":"locate the source","vi":"tìm ra nguồn gốc"},{"en":"be located in","vi":"nằm ở"},{"en":"centrally located","vi":"nằm ở vị trí trung tâm"}],"wordFamily":["location (n.)","relocate (v.)","relocation (n.)","locator (n.)"],"synonyms":["find","position"],"antonyms":[],"tipVi":"Để diễn tả ý nghĩa \"located in/near\", thông thường người ta dùng cụm từ này thay vì dùng trực tiếp động từ locate.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_siren', 'en-b2-62', 'siren', '/ˈsaɪrən/', 'B2', 'thiết bị báo động; tiếng còi báo động', 'n.', NULL, NULL, 'Có thể chỉ thiết bị phát ra tiếng động, hoặc chính tiếng động đó.', 'An ambulance siren woke me early this morning.', NULL, 'Tiếng còi xe cứu thương đánh thức tôi vào sáng sớm nay.', '{"wordId":"siren","ukIpa":"/ˈsaɪrən/","usIpa":"/ˈsaɪrən/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"a device producing a loud warning sound, or that sound","vi":"thiết bị báo động; tiếng còi báo động"}],"examples":[{"en":"An ambulance siren woke me early this morning.","vi":"Tiếng còi xe cứu thương đánh thức tôi vào sáng sớm nay.","audioKind":"ex"},{"en":"Emergency sirens can help coastal communities respond quickly when severe storms threaten their safety.","vi":"Còi báo động khẩn cấp có thể giúp các cộng đồng ven biển phản ứng nhanh chóng khi bão dữ đe dọa sự an toàn của họ.","audioKind":"ex2"}],"collocations":[{"en":"sound a siren","vi":"lượng còi báo động; phát còi báo động"},{"en":"ambulance siren","vi":"tiếng còi xe cứu thương"},{"en":"warning siren","vi":"còi báo động"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Có thể chỉ thiết bị phát ra tiếng động, hoặc chính tiếng động đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_demolish', 'en-b2-62', 'demolish', '/dɪˈmɑːlɪʃ/', 'B2', 'phá dỡ; phá hủy (công trình); bác bỏ (lập luận, lý thuyết)', 'v.', 'demolition (n.)', 'Đồng nghĩa: destroy, raze · Trái nghĩa: construct', 'Là ngoại động từ, đi thẳng với tân ngữ; cũng có thể dùng với ý nghĩa bác bỏ lý luận.', 'Workers demolished the old garage behind our house.', NULL, 'Công nhân đã phá dỡ nhà để xe cũ phía sau nhà chúng tôi.', '{"wordId":"demolish","ukIpa":"/dɪˈmɒlɪʃ/","usIpa":"/dɪˈmɑːlɪʃ/","cefr":"B2","topic":"city","senses":[{"pos":"v.","en":"To completely destroy a building or other structure.","vi":"phá dỡ; phá hủy (công trình)"},{"pos":"v.","en":"To show clearly that an argument or theory is wrong.","vi":"bác bỏ (lập luận, lý thuyết)"}],"examples":[{"en":"Workers demolished the old garage behind our house.","vi":"Công nhân đã phá dỡ nhà để xe cũ phía sau nhà chúng tôi.","audioKind":"ex"},{"en":"Cities should consider restoring historic buildings rather than demolishing them to make space for new developments.","vi":"Các thành phố nên cân nhắc việc trùng tu các công trình lịch sử thay vì phá bỏ chúng để lấy không gian cho các dự án phát triển mới.","audioKind":"ex2"}],"collocations":[{"en":"demolish a building","vi":"phá dỡ một tòa nhà"},{"en":"demolish an argument","vi":"bác bỏ một lập luận"},{"en":"demolish completely","vi":"phá hủy hoàn toàn"}],"wordFamily":["demolition (n.)"],"synonyms":["destroy","raze"],"antonyms":["construct"],"tipVi":"Là ngoại động từ, đi thẳng với tân ngữ; cũng có thể dùng với ý nghĩa bác bỏ lý luận.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_outskirt', 'en-b2-62', 'outskirt', '/ˈaʊtskɝːt/', 'B2', 'vùng ngoại ô; vùng rìa thị trấn (thường dùng số nhiều)', 'n.', NULL, NULL, 'Thường dùng số nhiều outskirts, đi với giới từ on thay vì in.', 'My aunt lives on the outskirts near a farm.', NULL, 'Dì tôi sống ở vùng ngoại ô gần một trang trại.', '{"wordId":"outskirt","ukIpa":"/ˈaʊtskɜːt/","usIpa":"/ˈaʊtskɝːt/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"The outer parts of a town or city; usually plural","vi":"vùng ngoại ô; vùng rìa thị trấn (thường dùng số nhiều)"}],"examples":[{"en":"My aunt lives on the outskirts near a farm.","vi":"Dì tôi sống ở vùng ngoại ô gần một trang trại.","audioKind":"ex"},{"en":"Building affordable housing on the outskirts can reduce costs but may increase residents'' dependence on cars.","vi":"Việc xây dựng nhà ở giá rẻ ở vùng ngoại ô có thể làm giảm chi phí nhưng có thể làm tăng sự phụ thuộc của cư dân vào ô tô.","audioKind":"ex2"}],"collocations":[{"en":"on the outskirts of","vi":"ở vùng ngoại ô của"},{"en":"the outskirts of town","vi":"vùng rìa của thị trấn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng số nhiều outskirts, đi với giới từ on thay vì in.","noteVi":"Dạng số ít rất ít khi được sử dụng; từ chuẩn là outskirts.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_facility', 'en-b2-62', 'facility', '/fəˈsɪləti/', 'B2', 'cơ sở vật chất; trang thiết bị; phương tiện; tính năng; dịch vụ; tài năng; sự khéo léo; sự thành thạo', 'n.', NULL, NULL, 'Khi chỉ các cơ sở hạ tầng, tiện nghi nói chung thường dùng hình thức số nhiều facilities.', 'The new sports facility has a bright indoor pool.', NULL, 'Khu thể thao mới có một bể bơi trong nhà sáng sủa.', '{"wordId":"facility","ukIpa":"/fəˈsɪləti/","usIpa":"/fəˈsɪləti/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"A place or equipment provided for a particular purpose.","vi":"cơ sở vật chất; trang thiết bị; phương tiện"},{"pos":"n.","en":"A feature or service that enables a particular activity.","vi":"tính năng; dịch vụ"},{"pos":"n.","en":"A natural ability to do or learn something easily.","vi":"tài năng; sự khéo léo; sự thành thạo"}],"examples":[{"en":"The new sports facility has a bright indoor pool.","vi":"Khu thể thao mới có một bể bơi trong nhà sáng sủa.","audioKind":"ex"},{"en":"Investing in local healthcare facilities can improve access to essential services for people in rural communities.","vi":"Việc đầu tư vào các cơ sở y tế địa phương có thể giúp người dân ở các vùng nông thôn dễ dàng tiếp cận các dịch vụ thiết yếu hơn.","audioKind":"ex2"}],"collocations":[{"en":"sports facilities","vi":"cơ sở thể thao"},{"en":"healthcare facilities","vi":"cơ sở y tế"},{"en":"a research facility","vi":"cơ sở nghiên cứu"},{"en":"a facility for languages","vi":"năng khiếu ngoại ngữ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ các cơ sở hạ tầng, tiện nghi nói chung thường dùng hình thức số nhiều facilities.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pedestrian', 'en-b2-62', 'pedestrian', '/pəˈdestriən/', 'B2', 'người đi bộ; dành cho người đi bộ; thuộc về người đi bộ; tẻ nhạt; bình thường; thiếu sức sáng tạo', 'n.', 'pedestrianise (v.), pedestrianisation (n.)', NULL, 'Khi là danh từ, từ này chỉ người đi bộ; khi là tính từ, nó cũng có thể mang nghĩa ám chỉ tác phẩm nghệ thuật tẻ nhạt, kém hấp dẫn.', 'The driver stopped to let a pedestrian cross.', NULL, 'Người lái xe đã dừng lại để nhường đường cho một người đi bộ sang đường.', '{"wordId":"pedestrian","ukIpa":"/pəˈdestriən/","usIpa":"/pəˈdestriən/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"a person walking rather than travelling in a vehicle","vi":"người đi bộ"},{"pos":"adj.","en":"intended for or relating to people travelling on foot","vi":"dành cho người đi bộ; thuộc về người đi bộ"},{"pos":"adj.","en":"ordinary and lacking imagination or excitement","vi":"tẻ nhạt; bình thường; thiếu sức sáng tạo"}],"examples":[{"en":"The driver stopped to let a pedestrian cross.","vi":"Người lái xe đã dừng lại để nhường đường cho một người đi bộ sang đường.","audioKind":"ex"},{"en":"Wider pavements and safer crossings can protect pedestrians and encourage residents to walk instead of driving.","vi":"Lề đường rộng hơn và các lối sang đường an toàn hơn có thể bảo vệ người đi bộ và khuyến khích người dân đi bộ thay vì lái xe.","audioKind":"ex2"}],"collocations":[{"en":"pedestrian crossing","vi":"vạch sang đường cho người đi bộ"},{"en":"pedestrian safety","vi":"an toàn cho người đi bộ"},{"en":"pedestrian zone","vi":"khu vực đi bộ"},{"en":"pedestrian access","vi":"lối đi dành cho người đi bộ"}],"wordFamily":["pedestrianise (v.)","pedestrianisation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi là danh từ, từ này chỉ người đi bộ; khi là tính từ, nó cũng có thể mang nghĩa ám chỉ tác phẩm nghệ thuật tẻ nhạt, kém hấp dẫn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tile', 'en-b2-62', 'tile', '/taɪl/', 'B2', 'gạch ốp lát; gạch men; ngói; lát gạch; lợp ngói', 'n.', 'tiled (adj.), tiling (n.), tiler (n.)', NULL, 'Danh từ đếm được; khi dùng làm động từ, nó đi trực tiếp với bề mặt cần ốp lát.', 'One blue tile has cracked beside the kitchen sink.', NULL, 'Một viên gạch màu xanh lam đã bị nứt ở cạnh bồn rửa chén trong bếp.', '{"wordId":"tile","ukIpa":"/taɪl/","usIpa":"/taɪl/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"A shaped piece used to cover floors, walls, or roofs.","vi":"gạch ốp lát; gạch men; ngói"},{"pos":"v.","en":"To cover a surface with tiles.","vi":"lát gạch; lợp ngói"}],"examples":[{"en":"One blue tile has cracked beside the kitchen sink.","vi":"Một viên gạch màu xanh lam đã bị nứt ở cạnh bồn rửa chén trong bếp.","audioKind":"ex"},{"en":"Using locally produced roof tiles can reduce transport emissions and support traditional industries in rural areas.","vi":"Sử dụng ngói lợp sản xuất tại địa phương có thể làm giảm lượng khí thải do vận chuyển và hỗ trợ các ngành công nghiệp truyền thống ở vùng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"ceramic tiles","vi":"gạch men"},{"en":"roof tiles","vi":"ngói lợp nhà"},{"en":"lay tiles","vi":"lát gạch"},{"en":"tile a bathroom","vi":"lát gạch phòng tắm"}],"wordFamily":["tiled (adj.)","tiling (n.)","tiler (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ đếm được; khi dùng làm động từ, nó đi trực tiếp với bề mặt cần ốp lát.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_avenue', 'en-b2-62', 'avenue', '/ˈævənuː/', 'B2', 'đại lộ; đại lộ trồng cây; con đường; phương hướng; cách thức', 'n.', NULL, NULL, 'Nghĩa bóng thường đi với avenue for hoặc avenue of, chỉ con đường hay phương hướng giải quyết vấn đề.', 'We walked along a quiet avenue shaded by tall trees.', NULL, 'Chúng tôi đi dạo dọc theo một đại lộ yên tĩnh rợp bóng những cây cao.', '{"wordId":"avenue","ukIpa":"/ˈævənjuː/","usIpa":"/ˈævənuː/","cefr":"B2","topic":"city","senses":[{"pos":"n.","en":"a wide street, often lined with trees","vi":"đại lộ; đại lộ trồng cây"},{"pos":"n.","en":"a possible way to achieve something or solve a problem","vi":"con đường; phương hướng; cách thức"}],"examples":[{"en":"We walked along a quiet avenue shaded by tall trees.","vi":"Chúng tôi đi dạo dọc theo một đại lộ yên tĩnh rợp bóng những cây cao.","audioKind":"ex"},{"en":"Online learning offers an important avenue for adults seeking new skills while remaining in full-time employment.","vi":"Học tập trực tuyến mang đến một con đường quan trọng cho những người trưởng thành đang tìm kiếm kỹ năng mới trong khi vẫn duy trì công việc toàn thời gian.","audioKind":"ex2"}],"collocations":[{"en":"tree-lined avenue","vi":"đại lộ rợp bóng cây"},{"en":"avenue of research","vi":"hướng nghiên cứu"},{"en":"explore every avenue","vi":"khám phá mọi con đường"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa bóng thường đi với avenue for hoặc avenue of, chỉ con đường hay phương hướng giải quyết vấn đề.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_62_1', 'en-b2-62', 'Cách dùng “congested” (adj.) — quá đông đúc, tắc nghẽn (giao thông hoặc người)', 'congested roads  ·  heavily congested  ·  a congested city centre', 'Từ này vừa có thể dùng để mô tả tình trạng giao thông tắc nghẽn, vừa dùng cho tình trạng nghẹt mũi hoặc các bộ phận cơ thể bị tắc nghẽn.', 'Họ từ (Word Family): congest (v.), congestion (n.), decongestant (n.) | Đồng nghĩa: crowded, blocked, clogged · Trái nghĩa: clear', '[{"hanzi":"The roads were so congested that we walked home.","pinyin":"","meaning":"Đường sá tắc nghẽn đến mức chúng tôi phải đi bộ về nhà."},{"hanzi":"Investing in reliable public transport can reduce traffic on congested roads and improve air quality in cities.","pinyin":"","meaning":"Đầu tư vào hệ thống giao thông công cộng đáng tin cậy có thể làm giảm lưu lượng xe trên các tuyến đường quá tải và cải thiện chất lượng không khí trong thành phố."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_62_2', 'en-b2-62', 'Cách dùng “pedestrian” (n.) — người đi bộ', 'pedestrian crossing  ·  pedestrian safety  ·  pedestrian zone', 'Khi là danh từ, từ này chỉ người đi bộ; khi là tính từ, nó cũng có thể mang nghĩa ám chỉ tác phẩm nghệ thuật tẻ nhạt, kém hấp dẫn.', 'Họ từ (Word Family): pedestrianise (v.), pedestrianisation (n.)', '[{"hanzi":"The driver stopped to let a pedestrian cross.","pinyin":"","meaning":"Người lái xe đã dừng lại để nhường đường cho một người đi bộ sang đường."},{"hanzi":"Wider pavements and safer crossings can protect pedestrians and encourage residents to walk instead of driving.","pinyin":"","meaning":"Lề đường rộng hơn và các lối sang đường an toàn hơn có thể bảo vệ người đi bộ và khuyến khích người dân đi bộ thay vì lái xe."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_62_3', 'en-b2-62', 'Cách dùng “pillar” (n.) — cột; trụ (cấu trúc chống đỡ)', 'a stone pillar  ·  a central pillar of  ·  a pillar of the community', 'pillar of có thể được dùng theo nghĩa bóng để chỉ trụ cột của một hệ thống hoặc nhân vật trung tâm trong một nhóm.', 'Đồng nghĩa: column, support', '[{"hanzi":"We sheltered from the rain behind a stone pillar.","pinyin":"","meaning":"Chúng tôi đứng trú mưa đằng sau một cây cột đá."},{"hanzi":"Accessible education is a central pillar of social development because it expands opportunities across generations.","pinyin":"","meaning":"Giáo dục dễ tiếp cận là trụ cột trung tâm của sự phát triển xã hội vì nó mở rộng cơ hội cho các thế hệ."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_62_4', 'en-b2-62', 'Cách dùng “locate” (v.) — xác định vị trí; tìm ra', 'locate a fault  ·  locate the source  ·  be located in', 'Để diễn tả ý nghĩa "located in/near", thông thường người ta dùng cụm từ này thay vì dùng trực tiếp động từ locate.', 'Họ từ (Word Family): location (n.), relocate (v.), relocation (n.), locator (n.) | Đồng nghĩa: find, position', '[{"hanzi":"We finally located the missing keys behind the sofa.","pinyin":"","meaning":"Cuối cùng chúng tôi cũng tìm thấy những chiếc chìa khóa bị mất đằng sau chiếc ghế sofa."},{"hanzi":"Local authorities should locate new health centres near public transport routes to improve access for elderly residents.","pinyin":"","meaning":"Chính quyền địa phương nên đặt các trung tâm y tế mới gần các tuyến giao thông công cộng để giúp người cao tuổi dễ dàng tiếp cận hơn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_62_1', 'en-b2-62', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
