INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_62_1_2', 'ten_b2_62_1', 'renovation', 'We stayed with friends during the renovation of our kitchen.', 'We stayed with friends during the renovation of our kitchen.', '/ˌrenəˈveɪʃən/', 'Chúng tôi đã ở nhờ nhà bạn bè trong thời gian phòng bếp được sửa sang.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_62_1_3', 'ten_b2_62_1', 'collapse', 'The old garden shed collapsed during last night''s storm.', 'The old garden shed collapsed during last night''s storm.', '/kəˈlæps/', 'Căn chòi làm vườn cũ đã đổ sụp trong trận bão đêm qua.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_62_1_4', 'ten_b2_62_1', 'dome', 'Sunlight streamed through the glass dome above the entrance.', 'Sunlight streamed through the glass dome above the entrance.', '/doʊm/', 'Ánh nắng chiếu rọi qua vòm kính ở phía trên lối vào.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_62_1_5', 'ten_b2_62_1', 'resident', 'Every resident received a key to the shared garden.', 'Every resident received a key to the shared garden.', '/ˈrezɪdənt/', 'Mỗi cư dân đều nhận được một chiếc chìa khóa vào khu vườn chung.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
