INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_62_1_7', 'ten_b2_62_1', 'exterior', 'They painted the exterior of their house pale blue.', 'They painted the exterior of their house pale blue.', '/ɪkˈstɪriər/', 'Họ sơn phần bên ngoài ngôi nhà của mình thành màu xanh nhạt.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_62_1_8', 'ten_b2_62_1', 'mansion', 'An enormous mansion stood behind the tall iron gates.', 'An enormous mansion stood behind the tall iron gates.', '/ˈmænʃən/', 'Một dinh thự khổng lồ sừng sững hiện lên phía sau những cánh cổng sắt cao.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_62_1_1', 'en-b2-62', 'ten_b2_62_1', 'listening', 'listening', 'The roads were so congested that we walked home.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tiếng còi xe cứu thương đánh thức tôi vào sáng sớm nay.","Ngôi nhà nhỏ của họ nằm ở rìa khu rừng.","Đường sá tắc nghẽn đến mức chúng tôi phải đi bộ về nhà.","Thợ xây đã trộn xi măng và nước trong một cái xô."]'::jsonb, 2, 'The roads were so congested that we walked home. → Đường sá tắc nghẽn đến mức chúng tôi phải đi bộ về nhà.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_62_1_2', 'en-b2-62', 'ten_b2_62_1', 'listening', 'listening', 'We stayed with friends during the renovation of our kitchen.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Gia đình họ ở chung trong một căn phòng nhỏ thuộc khu ổ chuột đông đúc.","Chúng tôi đã ở nhờ nhà bạn bè trong thời gian phòng bếp được sửa sang.","Thợ xây đã trộn xi măng và nước trong một cái xô.","Căn chòi làm vườn cũ đã đổ sụp trong trận bão đêm qua."]'::jsonb, 1, 'We stayed with friends during the renovation of our kitchen. → Chúng tôi đã ở nhờ nhà bạn bè trong thời gian phòng bếp được sửa sang.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_62_1_3', 'en-b2-62', 'ten_b2_62_1', 'listening', 'listening', 'The old garden shed collapsed during last night''s storm.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Đường sá tắc nghẽn đến mức chúng tôi phải đi bộ về nhà.","Chúng tôi đi dạo dọc theo một đại lộ yên tĩnh rợp bóng những cây cao.","Căn chòi làm vườn cũ đã đổ sụp trong trận bão đêm qua.","Khu vườn đô thị của chúng tôi nằm giữa hai tòa nhà chung cư cao tầng."]'::jsonb, 2, 'The old garden shed collapsed during last night''s storm. → Căn chòi làm vườn cũ đã đổ sụp trong trận bão đêm qua.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_62_2', 'en-b2-62', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_62_2_1', 'ten_b2_62_2', 'congested', 'Investing in reliable public transport can reduce traffic on congested roads and improve air quality in cities.', 'Investing in reliable public transport can reduce traffic on congested roads and improve air quality in cities.', '/kənˈdʒestɪd/', 'Đầu tư vào hệ thống giao thông công cộng đáng tin cậy có thể làm giảm lưu lượng xe trên các tuyến đường quá tải và cải thiện chất lượng không khí trong thành phố.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_62_2_2', 'ten_b2_62_2', 'renovation', 'The renovation of historic buildings can preserve local identity while providing suitable spaces for modern businesses.', 'The renovation of historic buildings can preserve local identity while providing suitable spaces for modern businesses.', '/ˌrenəˈveɪʃən/', 'Việc cải tạo các tòa nhà lịch sử có thể bảo tồn nét đặc trưng địa phương đồng thời cung cấp không gian phù hợp cho các doanh nghiệp hiện đại.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_62_2_3', 'ten_b2_62_2', 'collapse', 'Poor maintenance can cause bridges to collapse, making regular inspections essential for public safety.', 'Poor maintenance can cause bridges to collapse, making regular inspections essential for public safety.', '/kəˈlæps/', 'Việc bảo trì kém có thể khiến cầu sập, do đó việc kiểm tra thường xuyên là tối quan trọng đối với an toàn công cộng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_62_2_4', 'ten_b2_62_2', 'dome', 'The museum''s central dome allows natural light into the building, reducing the need for artificial lighting during daylight hours.', 'The museum''s central dome allows natural light into the building, reducing the need for artificial lighting during daylight hours.', '/doʊm/', 'Mái vòm trung tâm của viện bảo tàng cho phép ánh sáng tự nhiên chiếu vào tòa nhà, giúp giảm nhu cầu sử dụng đèn nhân tạo vào ban ngày.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_62_2_5', 'ten_b2_62_2', 'resident', 'Local residents should be consulted before major changes are made to roads and public spaces.', 'Local residents should be consulted before major changes are made to roads and public spaces.', '/ˈrezɪdənt/', 'Cư dân địa phương cần được tham vấn trước khi thực hiện các thay đổi lớn đối với đường sá và không gian công cộng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_62_2_6', 'ten_b2_62_2', 'fringe', 'Affordable housing on the urban fringe often leaves residents dependent on cars for their daily journeys.', 'Affordable housing on the urban fringe often leaves residents dependent on cars for their daily journeys.', '/frɪndʒ/', 'Nhà ở giá rẻ ở vùng ngoại vi thành phố thường khiến cư dân phải phụ thuộc vào ô tô cho việc đi lại hàng ngày.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_62_2_1', 'en-b2-62', 'ten_b2_62_2', 'listening', 'listening', 'Investing in reliable public transport can reduce traffic on congested roads and improve air quality in cities.', NULL, 'Trong câu vừa nghe, từ “congested” mang nghĩa nào sau đây?', '["quá đông đúc, tắc nghẽn (giao thông hoặc người)","hòn cuội; viên đá nhỏ nhẵn","thuộc nông thôn; thuộc vùng quê","nổi bật, nổi tiếng, có tầm ảnh hưởng"]'::jsonb, 0, '“congested” (/kənˈdʒestɪd/): quá đông đúc, tắc nghẽn (giao thông hoặc người). Câu đầy đủ: Investing in reliable public transport can reduce traffic on congested roads and improve air quality in cities.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_62_2_2', 'en-b2-62', 'ten_b2_62_2', 'listening', 'listening', 'The renovation of historic buildings can preserve local identity while providing suitable spaces for modern businesses.', NULL, 'Trong câu vừa nghe, từ “renovation” mang nghĩa nào sau đây?', '["sự đóng góp; phần đóng góp","mức đánh giá; điểm số; xếp hạng","cho rằng; giả định; nghĩ rằng","sự cải tạo; sự sửa sang lại"]'::jsonb, 3, '“renovation” (/ˌrenəˈveɪʃən/): sự cải tạo; sự sửa sang lại. Câu đầy đủ: The renovation of historic buildings can preserve local identity while providing suitable spaces for modern businesses.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
