INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_62_5', 'en-b2-62', NULL, 'comprehensive_test', 'listening', 'resident', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nhẹ nhàng; khẽ khàng","cư dân; người dân","phủ nhận; chối bỏ","thức ăn chứa đường hoặc tinh bột cung cấp năng lượng"]'::jsonb, 1, 'resident (/ˈrezɪdənt/) → cư dân; người dân; cư trú; thường trú', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_62_6', 'en-b2-62', NULL, 'comprehensive_test', 'listening', 'Their cottage stands on the fringe of the forest.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi ăn sáng ở sân trong cạnh một đài phun nước.","Chúng tôi đứng trú mưa đằng sau một cây cột đá.","Người lái xe đã dừng lại để nhường đường cho một người đi bộ sang đường.","Ngôi nhà nhỏ của họ nằm ở rìa khu rừng."]'::jsonb, 3, 'Their cottage stands on the fringe of the forest. → Ngôi nhà nhỏ của họ nằm ở rìa khu rừng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_62_7', 'en-b2-62', NULL, 'comprehensive_test', 'listening', 'exterior', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nhỏ; nhẹ; mong manh; không đáng kể","nhân tạo; do con người làm ra","đỏ mặt vì xấu hổ hoặc ngại ngùng","bề ngoài; phần bên ngoài"]'::jsonb, 3, 'exterior (/ɪkˈstɪriər/) → bề ngoài; phần bên ngoài; thuộc về bên ngoài', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_62_8', 'en-b2-62', NULL, 'comprehensive_test', 'listening', 'An enormous mansion stood behind the tall iron gates.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một viên gạch màu xanh lam đã bị nứt ở cạnh bồn rửa chén trong bếp.","Ánh nắng chiếu rọi qua vòm kính ở phía trên lối vào.","Người lái xe đã dừng lại để nhường đường cho một người đi bộ sang đường.","Một dinh thự khổng lồ sừng sững hiện lên phía sau những cánh cổng sắt cao."]'::jsonb, 3, 'An enormous mansion stood behind the tall iron gates. → Một dinh thự khổng lồ sừng sững hiện lên phía sau những cánh cổng sắt cao.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
