INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_62_18', 'en-b2-62', NULL, 'comprehensive_test', 'reading', NULL, 'Investing in reliable public transport can reduce traffic on congested roads and improve air quality in cities.', 'Dựa vào câu trên, từ “congested” có nghĩa phù hợp nhất là gì?', '["độ cao (so với mực nước biển hoặc mặt đất)","địa vị xã hội; thân phận","giới tính (mang tính xã hội và văn hóa)","quá đông đúc, tắc nghẽn (giao thông hoặc người)"]'::jsonb, 3, 'congested: quá đông đúc, tắc nghẽn (giao thông hoặc người); bị nghẹt, xung huyết (mũi hoặc cơ thể). Dịch cả câu: Đầu tư vào hệ thống giao thông công cộng đáng tin cậy có thể làm giảm lưu lượng xe trên các tuyến đường quá tải và cải thiện chất lượng không khí trong thành phố.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_62_19', 'en-b2-62', NULL, 'comprehensive_test', 'reading', NULL, 'The renovation of historic buildings can preserve local identity while providing suitable spaces for modern businesses.', 'Dựa vào câu trên, từ “renovation” có nghĩa phù hợp nhất là gì?', '["tiền trợ cấp; tiền tiêu vặt định kỳ","màu vàng óng; vàng kim","sự cải tạo; sự sửa sang lại","nhà thuyền; thuyền cư trú"]'::jsonb, 2, 'renovation: sự cải tạo; sự sửa sang lại. Dịch cả câu: Việc cải tạo các tòa nhà lịch sử có thể bảo tồn nét đặc trưng địa phương đồng thời cung cấp không gian phù hợp cho các doanh nghiệp hiện đại.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_62_20', 'en-b2-62', NULL, 'comprehensive_test', 'reading', NULL, 'Poor maintenance can cause bridges to collapse, making regular inspections essential for public safety.', 'Dựa vào câu trên, từ “collapse” có nghĩa phù hợp nhất là gì?', '["dành riêng; độc quyền","đổ sụp; sụp đổ; ngã gục","rộng rãi; bao quát; lớn","giàu có; phú quý"]'::jsonb, 1, 'collapse: đổ sụp; sụp đổ; ngã gục; sự sụp đổ; sự suy sụp hoàn toàn. Dịch cả câu: Việc bảo trì kém có thể khiến cầu sập, do đó việc kiểm tra thường xuyên là tối quan trọng đối với an toàn công cộng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_62_21', 'en-b2-62', NULL, 'comprehensive_test', 'reading', NULL, 'The museum''s central dome allows natural light into the building, reducing the need for artificial lighting during daylight hours.', 'Dựa vào câu trên, từ “dome” có nghĩa phù hợp nhất là gì?', '["vòm; mái vòm tròn","quá mức; thái quá","thực hiện; hoàn thành (nhiệm vụ, lời hứa, thỏa thuận)","mang tính so sánh; đối chiếu"]'::jsonb, 0, 'dome: vòm; mái vòm tròn; vật có hình mái vòm. Dịch cả câu: Mái vòm trung tâm của viện bảo tàng cho phép ánh sáng tự nhiên chiếu vào tòa nhà, giúp giảm nhu cầu sử dụng đèn nhân tạo vào ban ngày.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
