INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-63', 'en', 'Bài 63: Thể thao & Vận động - CEFR B2', 'CEFR B2', 'B2 · Thể thao', '17 từ vựng Tiếng Anh CEFR B2 chủ đề thể thao & vận động kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4063, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clubhouse', 'en-b2-63', 'clubhouse', '/ˈklʌbhaʊs/', 'B2', 'nhà câu lạc bộ; trụ sở câu lạc bộ', 'n.', NULL, NULL, 'Chỉ tòa nhà mà câu lạc bộ sử dụng, không chỉ tổ chức câu lạc bộ.', 'We left our tennis bags outside the clubhouse.', NULL, 'Chúng tôi để những chiếc túi đựng vợt quần vợt ở bên ngoài nhà câu lạc bộ.', '{"wordId":"clubhouse","ukIpa":"/ˈklʌbhaʊs/","usIpa":"/ˈklʌbhaʊs/","cefr":"B2","topic":"sport","senses":[{"pos":"n.","en":"a building where club members meet and use shared facilities","vi":"nhà câu lạc bộ; trụ sở câu lạc bộ"}],"examples":[{"en":"We left our tennis bags outside the clubhouse.","vi":"Chúng tôi để những chiếc túi đựng vợt quần vợt ở bên ngoài nhà câu lạc bộ.","audioKind":"ex"},{"en":"A shared clubhouse can strengthen community ties by giving local sports teams a place to meet regularly.","vi":"Một nhà câu lạc bộ chung có thể củng cố mối liên kết cộng đồng bằng cách cung cấp cho các đội thể thao địa phương một nơi để gặp gỡ thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"golf clubhouse","vi":"nhà câu lạc bộ gôn"},{"en":"clubhouse facilities","vi":"cơ sở vật chất của nhà câu lạc bộ"},{"en":"clubhouse lounge","vi":"phòng chờ của nhà câu lạc bộ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ tòa nhà mà câu lạc bộ sử dụng, không chỉ tổ chức câu lạc bộ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_triumph', 'en-b2-63', 'triumph', '/ˈtraɪʌmf/', 'B2', 'thắng lợi lớn; thành tựu vẻ vang; niềm vui chiến thắng; niềm tự hào; giành chiến thắng; chiến thắng; vượt qua', 'n.', 'triumphant (adj.), triumphantly (adv.)', 'Đồng nghĩa: victory, success · Trái nghĩa: defeat, failure', 'Khi dùng làm động từ, thường đi với triumph over để chỉ ý nghĩa chiến thắng.', 'Winning the local chess tournament was a triumph for Amir.', NULL, 'Giành chiến thắng trong giải cờ vua địa phương là một thành tựu lớn đối với Amir.', '{"wordId":"triumph","ukIpa":"/ˈtraɪʌmf/","usIpa":"/ˈtraɪʌmf/","cefr":"B2","topic":"sport","senses":[{"pos":"n.","en":"An important victory or impressive achievement.","vi":"thắng lợi lớn; thành tựu vẻ vang"},{"pos":"n.","en":"Great happiness and pride after achieving success.","vi":"niềm vui chiến thắng; niềm tự hào"},{"pos":"v.","en":"To achieve victory or overcome a difficulty.","vi":"giành chiến thắng; chiến thắng; vượt qua"}],"examples":[{"en":"Winning the local chess tournament was a triumph for Amir.","vi":"Giành chiến thắng trong giải cờ vua địa phương là một thành tựu lớn đối với Amir.","audioKind":"ex"},{"en":"The successful restoration of the wetland represents a triumph for conservation groups and local residents.","vi":"Việc phục hồi thành công vùng đất ngập nước đánh dấu một thắng lợi to lớn đối với các nhóm bảo tồn và người dân địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a major triumph","vi":"thắng lợi lớn"},{"en":"a sense of triumph","vi":"niềm vui chiến thắng"},{"en":"triumph over adversity","vi":"chiến thắng nghịch cảnh"}],"wordFamily":["triumphant (adj.)","triumphantly (adv.)"],"synonyms":["victory","success"],"antonyms":["defeat","failure"],"tipVi":"Khi dùng làm động từ, thường đi với triumph over để chỉ ý nghĩa chiến thắng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_saddle', 'en-b2-63', 'saddle', '/ˈsædəl/', 'B2', 'yên ngựa; yên xe đạp; đóng yên ngựa; bắt gánh vác; chất gánh nặng cho ai', 'n.', NULL, NULL, 'Cấu trúc saddle someone with dùng để chỉ việc bắt ai đó phải gánh vác một gánh nặng không mong muốn.', 'I lowered the saddle before riding my new bicycle.', NULL, 'Tôi đã hạ thấp yên xe trước khi đi chiếc xe đạp mới của mình.', '{"wordId":"saddle","ukIpa":"/ˈsædəl/","usIpa":"/ˈsædəl/","cefr":"B2","topic":"sport","senses":[{"pos":"n.","en":"a seat on a horse or bicycle","vi":"yên ngựa; yên xe đạp"},{"pos":"v.","en":"to put a saddle on a horse","vi":"đóng yên ngựa"},{"pos":"v.","en":"to give someone an unwanted responsibility or burden","vi":"bắt gánh vác; chất gánh nặng cho ai"}],"examples":[{"en":"I lowered the saddle before riding my new bicycle.","vi":"Tôi đã hạ thấp yên xe trước khi đi chiếc xe đạp mới của mình.","audioKind":"ex"},{"en":"Excessive university fees can saddle graduates with debts that limit their career choices for many years.","vi":"Học phí đại học quá cao có thể khiến sinh viên mới tốt nghiệp gánh chịu những khoản nợ giới hạn lựa chọn nghề nghiệp của họ trong nhiều năm.","audioKind":"ex2"}],"collocations":[{"en":"adjust the saddle","vi":"điều chỉnh yên xe"},{"en":"saddle a horse","vi":"yên ngựa"},{"en":"be saddled with debt","vi":"mang nợ ngập đầu"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc saddle someone with dùng để chỉ việc bắt ai đó phải gánh vác một gánh nặng không mong muốn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_punch', 'en-b2-63', 'punch', '/pʌntʃ/', 'B2', 'đấm; thụi; cú đấm; đục lỗ', 'v.', NULL, NULL, '"punch" là đánh bằng nắm đấm; "slap" thường chỉ việc vỗ hoặc tát bằng lòng bàn tay.', 'She punched the training bag, then caught her breath.', NULL, 'Cô ấy đấm vào bao cát tập luyện, rồi lấy lại hơi thở.', '{"wordId":"punch","ukIpa":"/pʌntʃ/","usIpa":"/pʌntʃ/","cefr":"B2","topic":"sport","senses":[{"pos":"v.","en":"to hit someone or something with a closed hand","vi":"đấm; thụi"},{"pos":"n.","en":"a hit made with a closed hand","vi":"cú đấm"},{"pos":"v.","en":"to make a hole using a special tool","vi":"đục lỗ"}],"examples":[{"en":"She punched the training bag, then caught her breath.","vi":"Cô ấy đấm vào bao cát tập luyện, rồi lấy lại hơi thở.","audioKind":"ex"},{"en":"Boxers learn to deliver a controlled punch while maintaining balance and protecting themselves from injury.","vi":"Các võ sĩ quyền anh học cách tung ra cú đấm có kiểm soát đồng thời giữ thăng bằng và bảo vệ bản thân khỏi chấn thương.","audioKind":"ex2"}],"collocations":[{"en":"punch a bag","vi":"đấm bao cát"},{"en":"throw a punch","vi":"tung cú đấm"},{"en":"punch a hole","vi":"đục lỗ"},{"en":"hole punch","vi":"dụng cụ đục lỗ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"\"punch\" là đánh bằng nắm đấm; \"slap\" thường chỉ việc vỗ hoặc tát bằng lòng bàn tay.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recreational', 'en-b2-63', 'recreational', '/ˌrekriˈeɪʃənəl/', 'B2', 'giải trí; mang tính thư giãn', 'adj.', 'recreation (n.), recreationally (adv.)', NULL, 'Thường đi kèm với "activities" hoặc "facilities", nhằm nhấn mạnh tính chất giải trí thay vì công việc.', 'The lake is a popular spot for recreational fishing.', NULL, 'Hồ nước này là một điểm đến phổ biến cho hoạt động câu cá giải trí.', '{"wordId":"recreational","ukIpa":"/ˌrekriˈeɪʃənəl/","usIpa":"/ˌrekriˈeɪʃənəl/","cefr":"B2","topic":"sport","senses":[{"pos":"adj.","en":"Done for enjoyment and relaxation rather than work.","vi":"giải trí; mang tính thư giãn"}],"examples":[{"en":"The lake is a popular spot for recreational fishing.","vi":"Hồ nước này là một điểm đến phổ biến cho hoạt động câu cá giải trí.","audioKind":"ex"},{"en":"Providing affordable recreational facilities can improve public health and strengthen social connections within urban communities.","vi":"Việc cung cấp các cơ sở vật chất giải trí vừa túi tiền có thể cải thiện sức khỏe cộng đồng và thắt chặt các mối quan hệ xã hội trong các cộng đồng đô thị.","audioKind":"ex2"}],"collocations":[{"en":"recreational activities","vi":"các hoạt động giải trí"},{"en":"recreational facilities","vi":"cơ sở vật chất giải trí"},{"en":"recreational use","vi":"mục đích giải trí"}],"wordFamily":["recreation (n.)","recreationally (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường đi kèm với \"activities\" hoặc \"facilities\", nhằm nhấn mạnh tính chất giải trí thay vì công việc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pitch', 'en-b2-63', 'pitch', '/pɪtʃ/', 'B2', 'sân thi đấu; sân bóng; độ cao (của âm thanh); giới thiệu; chào hàng; thuyết trình (để thuyết phục người khác chấp nhận)', 'n.', 'pitched (adj.)', NULL, 'Nghĩa sân thể thao thường dùng trong tiếng Anh-Anh; pitch a tent có nghĩa là dựng lều.', 'The players ran onto the pitch despite the rain.', NULL, 'Các cầu thủ vẫn chạy ra sân thi đấu mặc cho trời mưa.', '{"wordId":"pitch","ukIpa":"/pɪtʃ/","usIpa":"/pɪtʃ/","cefr":"B2","topic":"sport","senses":[{"pos":"n.","en":"An area of ground used for outdoor team sports.","vi":"sân thi đấu; sân bóng"},{"pos":"n.","en":"How high or low a sound is.","vi":"độ cao (của âm thanh)"},{"pos":"v.","en":"Present an idea or product to persuade someone to accept it.","vi":"giới thiệu; chào hàng; thuyết trình (để thuyết phục người khác chấp nhận)"}],"examples":[{"en":"The players ran onto the pitch despite the rain.","vi":"Các cầu thủ vẫn chạy ra sân thi đấu mặc cho trời mưa.","audioKind":"ex"},{"en":"Young entrepreneurs often pitch their business ideas to investors who can provide funding and practical guidance.","vi":"Các nhà khởi nghiệp trẻ thường thuyết trình ý tưởng kinh doanh của họ trước các nhà đầu tư có thể cung cấp nguồn vốn và định hướng thực tế.","audioKind":"ex2"}],"collocations":[{"en":"football pitch","vi":"sân bóng đá"},{"en":"high pitch","vi":"độ cao âm thanh"},{"en":"pitch an idea","vi":"thuyết trình ý tưởng"},{"en":"pitch a tent","vi":"dựng lều"}],"wordFamily":["pitched (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa sân thể thao thường dùng trong tiếng Anh-Anh; pitch a tent có nghĩa là dựng lều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scout', 'en-b2-63', 'scout', '/skaʊt/', 'B2', 'trinh sát viên; trinh sát; tuyển trạch viên; cầu thủ được nhắm đến; tìm kiếm; dò la; hướng đạo sinh', 'n.', 'scouting (n.)', NULL, 'Scout for đi với đối tượng đang tìm kiếm; từ chỉ thành viên hướng đạo sinh thường viết hoa là Scout.', 'A scout watched our team practise after school.', NULL, 'Một tuyển trạch viên đã theo dõi đội của chúng tôi tập luyện sau giờ học.', '{"wordId":"scout","ukIpa":"/skaʊt/","usIpa":"/skaʊt/","cefr":"B2","topic":"sport","senses":[{"pos":"n.","en":"Someone sent to gather information or discover talented people.","vi":"trinh sát viên; trinh sát; tuyển trạch viên; cầu thủ được nhắm đến"},{"pos":"v.","en":"To search an area for something or gather information.","vi":"tìm kiếm; dò la; trinh sát"},{"pos":"n.","en":"A member of a youth group learning outdoor skills.","vi":"hướng đạo sinh"}],"examples":[{"en":"A scout watched our team practise after school.","vi":"Một tuyển trạch viên đã theo dõi đội của chúng tôi tập luyện sau giờ học.","audioKind":"ex"},{"en":"Sports clubs often scout for talented young players in communities that lack access to professional training facilities.","vi":"Các câu lạc bộ thể thao thường tìm kiếm những cầu thủ trẻ tài năng ở những cộng đồng thiếu cơ sở vật chất tập luyện chuyên nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"a talent scout","vi":"nhà tuyển trạch tài năng"},{"en":"a football scout","vi":"trinh sát bóng đá"},{"en":"scout for talent","vi":"săn lùng nhân tài"},{"en":"scout out a location","vi":"khảo sát một địa điểm"}],"wordFamily":["scouting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Scout for đi với đối tượng đang tìm kiếm; từ chỉ thành viên hướng đạo sinh thường viết hoa là Scout.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_oar', 'en-b2-63', 'oar', '/ɔːr/', 'B2', 'mái chèo', 'n.', NULL, NULL, 'oar thường là mái chèo gắn cố định vào mạn thuyền; paddle thường là mái chèo cầm tay.', 'He lifted one oar and gently pushed the boat away.', NULL, 'Anh ấy nâng một chiếc mái chèo lên và nhẹ nhàng đẩy chiếc thuyền ra.', '{"wordId":"oar","ukIpa":"/ɔː/","usIpa":"/ɔːr/","cefr":"B2","topic":"sport","senses":[{"pos":"n.","en":"A long pole with a flat blade for rowing boats","vi":"mái chèo"}],"examples":[{"en":"He lifted one oar and gently pushed the boat away.","vi":"Anh ấy nâng một chiếc mái chèo lên và nhẹ nhàng đẩy chiếc thuyền ra.","audioKind":"ex"},{"en":"Visitors can explore the lake in traditional boats, using oars rather than engines to minimise disturbance to wildlife.","vi":"Du khách có thể khám phá hồ bằng những chiếc thuyền truyền thống, dùng mái chèo thay vì động cơ để giảm thiểu ảnh hưởng đến động vật hoang dã.","audioKind":"ex2"}],"collocations":[{"en":"a pair of oars","vi":"một cặp mái chèo"},{"en":"pull on the oars","vi":"dùng sức chèo"},{"en":"oar blade","vi":"lưỡi mái chèo"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"oar thường là mái chèo gắn cố định vào mạn thuyền; paddle thường là mái chèo cầm tay.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_amateur', 'en-b2-63', 'amateur', '/ˈæmətʃər/', 'B2', 'người làm vì sở thích; người nghiệp dư; mang tính nghiệp dư; không chuyên; kẻ ngoại đạo; tay mơ', 'n.', 'amateurish (adj.), amateurism (n.)', 'Trái nghĩa: professional', 'amateur thường chỉ người không chuyên, không nhất thiết mang ý nghĩa trình độ kém.', 'Although an amateur, she takes beautiful photographs of birds.', NULL, 'Dù chỉ là một người nghiệp dư, cô ấy vẫn chụp được những bức ảnh chim chóc rất đẹp.', '{"wordId":"amateur","ukIpa":"/ˈæmətə/","usIpa":"/ˈæmətʃər/","cefr":"B2","topic":"sport","senses":[{"pos":"n.","en":"Someone who pursues an activity for pleasure rather than pay.","vi":"người làm vì sở thích; người nghiệp dư"},{"pos":"adj.","en":"Done for enjoyment rather than as a paid profession.","vi":"mang tính nghiệp dư; không chuyên"},{"pos":"n.","en":"Someone who lacks skill or experience in an activity.","vi":"kẻ ngoại đạo; tay mơ"}],"examples":[{"en":"Although an amateur, she takes beautiful photographs of birds.","vi":"Dù chỉ là một người nghiệp dư, cô ấy vẫn chụp được những bức ảnh chim chóc rất đẹp.","audioKind":"ex"},{"en":"Amateur sports clubs provide affordable opportunities for physical activity and help strengthen relationships within local communities.","vi":"Các câu lạc bộ thể thao nghiệp dư cung cấp cơ hội rèn luyện thể chất với chi phí phải chăng và giúp thắt chặt mối quan hệ trong cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"amateur photographer","vi":"nhiếp ảnh gia nghiệp dư"},{"en":"amateur athlete","vi":"vận động viên nghiệp dư"},{"en":"amateur theatre","vi":"hoạt động kịch nghiệp dư"},{"en":"complete amateur","vi":"kẻ ngoại đạo hoàn toàn"}],"wordFamily":["amateurish (adj.)","amateurism (n.)"],"synonyms":[],"antonyms":["professional"],"tipVi":"amateur thường chỉ người không chuyên, không nhất thiết mang ý nghĩa trình độ kém.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fighter', 'en-b2-63', 'fighter', '/ˈfaɪtər/', 'B2', 'võ sĩ; chiến binh; người kiên cường chiến đấu; đấu sĩ; máy bay chiến đấu', 'n.', 'fight (v.), fight (n.), fighting (n.)', NULL, 'Có thể dùng để chỉ người chiến đấu hoặc đấu tranh, cũng như máy bay chiến đấu.', 'The young fighter practises footwork with her coach every morning.', NULL, 'Nữ võ sĩ trẻ tập luyện động tác chân với huấn luyện viên của cô ấy mỗi buổi sáng.', '{"wordId":"fighter","ukIpa":"/ˈfaɪtə/","usIpa":"/ˈfaɪtər/","cefr":"B2","topic":"sport","senses":[{"pos":"n.","en":"a person who fights in battle or combat sports","vi":"võ sĩ; chiến binh"},{"pos":"n.","en":"someone who persists despite difficulties or strongly supports a cause","vi":"người kiên cường chiến đấu; đấu sĩ"},{"pos":"n.","en":"a fast military aircraft designed to attack other aircraft","vi":"máy bay chiến đấu"}],"examples":[{"en":"The young fighter practises footwork with her coach every morning.","vi":"Nữ võ sĩ trẻ tập luyện động tác chân với huấn luyện viên của cô ấy mỗi buổi sáng.","audioKind":"ex"},{"en":"A successful fighter needs disciplined training, adequate recovery, and access to professional medical support.","vi":"Một võ sĩ thành công đòi hỏi quá trình luyện tập kỷ luật, thời gian hồi phục đầy đủ và sự hỗ trợ y tế chuyên nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"fighter pilot","vi":"phi công máy bay chiến đấu"},{"en":"fighter jet","vi":"máy bay phản lực chiến đấu"},{"en":"a fighter for justice","vi":"người đấu tranh vì công lý"}],"wordFamily":["fight (v.)","fight (n.)","fighting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể dùng để chỉ người chiến đấu hoặc đấu tranh, cũng như máy bay chiến đấu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_versus', 'en-b2-63', 'versus', '/ˈvɝːsəs/', 'B2', 'đấu với; so với', 'prep.', NULL, 'Đồng nghĩa: against', 'Thường được viết tắt là vs hoặc v, dùng trong thi đấu thể thao, kiện tụng hoặc so sánh hai lựa chọn.', 'Tonight''s match is our school versus the local college.', NULL, 'Trận đấu tối nay là cuộc đối đầu giữa trường chúng ta và trường cao đẳng địa phương.', '{"wordId":"versus","ukIpa":"/ˈvɜːsəs/","usIpa":"/ˈvɝːsəs/","cefr":"B2","topic":"sport","senses":[{"pos":"prep.","en":"against an opponent, or compared with another option","vi":"đấu với; so với"}],"examples":[{"en":"Tonight''s match is our school versus the local college.","vi":"Trận đấu tối nay là cuộc đối đầu giữa trường chúng ta và trường cao đẳng địa phương.","audioKind":"ex"},{"en":"The debate over public versus private transport often centres on cost, convenience, and environmental impact.","vi":"Cuộc tranh luận về giao thông công cộng so với giao thông cá nhân thường tập trung vào chi phí, sự tiện lợi và tác động đến môi trường.","audioKind":"ex2"}],"collocations":[{"en":"public versus private","vi":"so sánh giữa công và tư"},{"en":"the case of A versus B","vi":"vụ kiện giữa A và B"},{"en":"the benefits versus the costs","vi":"so sánh giữa lợi ích và chi phí"}],"wordFamily":[],"synonyms":["against"],"antonyms":[],"tipVi":"Thường được viết tắt là vs hoặc v, dùng trong thi đấu thể thao, kiện tụng hoặc so sánh hai lựa chọn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spectator', 'en-b2-63', 'spectator', '/ˈspekteɪtər/', 'B2', 'khán giả (xem sự kiện thể thao); người xem', 'n.', 'spectate (v.)', 'Đồng nghĩa: onlooker, viewer · Trái nghĩa: participant', 'Thường chỉ khán giả có mặt tại sự kiện thể thao; khán giả xem biểu diễn nghệ thuật thường dùng audience.', 'A spectator caught the ball near the fence.', NULL, 'Một khán giả đã bắt được quả bóng ở gần hàng rào.', '{"wordId":"spectator","ukIpa":"/spekˈteɪtə/","usIpa":"/ˈspekteɪtər/","cefr":"B2","topic":"sport","senses":[{"pos":"n.","en":"Someone who watches an event, especially a sporting event.","vi":"khán giả (xem sự kiện thể thao); người xem"}],"examples":[{"en":"A spectator caught the ball near the fence.","vi":"Một khán giả đã bắt được quả bóng ở gần hàng rào.","audioKind":"ex"},{"en":"Major sporting events attract thousands of spectators and can generate substantial income for local businesses.","vi":"Các sự kiện thể thao lớn thu hút hàng nghìn khán giả và có thể mang lại nguồn thu nhập đáng kể cho các doanh nghiệp địa phương.","audioKind":"ex2"}],"collocations":[{"en":"spectator sport","vi":"môn thể thao thu hút khán giả"},{"en":"spectator safety","vi":"an toàn cho khán giả"},{"en":"attract spectators","vi":"thu hút khán giả"}],"wordFamily":["spectate (v.)"],"synonyms":["onlooker","viewer"],"antonyms":["participant"],"tipVi":"Thường chỉ khán giả có mặt tại sự kiện thể thao; khán giả xem biểu diễn nghệ thuật thường dùng audience.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bungee', 'en-b2-63', 'bungee', '/ˈbʌndʒi/', 'B2', 'dây thun co giãn; dây bẹ (dùng để buộc đồ hoặc nhảy bungee)', 'n.', NULL, NULL, 'bungee chủ yếu dùng để chỉ dây thun co giãn; môn thể thao nhảy bungee thường gọi là bungee jumping.', 'We secured the sleeping bags with a strong bungee.', NULL, 'Chúng tôi đã cố định các túi ngủ bằng một sợi dây thun co giãn chắc chắn.', '{"wordId":"bungee","ukIpa":"/ˈbʌndʒi/","usIpa":"/ˈbʌndʒi/","cefr":"B2","topic":"sport","senses":[{"pos":"n.","en":"A strong stretchy cord used for securing objects or bungee jumping.","vi":"dây thun co giãn; dây bẹ (dùng để buộc đồ hoặc nhảy bungee)"}],"examples":[{"en":"We secured the sleeping bags with a strong bungee.","vi":"Chúng tôi đã cố định các túi ngủ bằng một sợi dây thun co giãn chắc chắn.","audioKind":"ex"},{"en":"Adventure tourism operators must inspect every bungee cord regularly to ensure that essential safety standards are maintained.","vi":"Các đơn vị khai thác dịch vụ du lịch mạo hiểm phải kiểm tra định kỳ từng sợi dây bungee để đảm bảo duy trì các tiêu chuẩn an toàn thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"bungee cord","vi":"dây bungee"},{"en":"bungee jumping","vi":"trò nhảy bungee"},{"en":"a bungee jump","vi":"một cú nhảy bungee"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"bungee chủ yếu dùng để chỉ dây thun co giãn; môn thể thao nhảy bungee thường gọi là bungee jumping.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_self-defence', 'en-b2-63', 'self-defence', '/ˌself dɪˈfens/', 'B2', 'tự vệ; phòng vệ chính đáng', 'n.', 'defend (v.), defence (n.), defensive (adj.), defender (n.)', NULL, 'Thường là danh từ không đếm được; theo chính tả tiếng Anh-Mỹ viết là self-defense.', 'My sister attends a self-defence class every Saturday.', NULL, 'Chị tôi tham gia một lớp học tự vệ vào thứ Bảy hàng tuần.', '{"wordId":"self-defence","ukIpa":"/ˌself dɪˈfens/","usIpa":"/ˌself dɪˈfens/","cefr":"B2","topic":"sport","senses":[{"pos":"n.","en":"protecting yourself from attack or physical harm","vi":"tự vệ; phòng vệ chính đáng"}],"examples":[{"en":"My sister attends a self-defence class every Saturday.","vi":"Chị tôi tham gia một lớp học tự vệ vào thứ Bảy hàng tuần.","audioKind":"ex"},{"en":"Self-defence courses can build confidence, although avoiding dangerous situations should remain the primary focus of personal safety.","vi":"Các khóa học tự vệ có thể xây dựng sự tự tin, mặc dù việc tránh xa các tình huống nguy hiểm vẫn nên là ưu tiên hàng đầu để đảm bảo an toàn cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"in self-defence","vi":"để tự vệ"},{"en":"self-defence class","vi":"lớp học tự vệ"},{"en":"self-defence techniques","vi":"kỹ thuật tự vệ"}],"wordFamily":["defend (v.)","defence (n.)","defensive (adj.)","defender (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; theo chính tả tiếng Anh-Mỹ viết là self-defense.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_relay', 'en-b2-63', 'relay', '/ˈriːleɪ/', 'B2', 'cuộc thi chạy tiếp sức; môn tiếp sức; truyền đạt (thông tin); phát sóng (tín hiệu); rơ-le (thiết bị chuyển mạch điện)', 'n.', NULL, NULL, 'Động từ relay cũng được phát âm là /rɪˈleɪ/; relay a message nghĩa là truyền đạt thông tin.', 'Our team dropped the baton during the school relay.', NULL, 'Đội chúng tôi đã làm rơi gậy trong cuộc thi chạy tiếp sức của trường.', '{"wordId":"relay","ukIpa":"/ˈriːleɪ/","usIpa":"/ˈriːleɪ/","cefr":"B2","topic":"sport","senses":[{"pos":"n.","en":"a race in which teammates take turns completing sections","vi":"cuộc thi chạy tiếp sức; môn tiếp sức"},{"pos":"v.","en":"to pass information or broadcast signals to another person or place","vi":"truyền đạt (thông tin); phát sóng (tín hiệu)"},{"pos":"n.","en":"an electrical switch controlled by another electrical circuit","vi":"rơ-le (thiết bị chuyển mạch điện)"}],"examples":[{"en":"Our team dropped the baton during the school relay.","vi":"Đội chúng tôi đã làm rơi gậy trong cuộc thi chạy tiếp sức của trường.","audioKind":"ex"},{"en":"Emergency services relay weather warnings to remote communities through local radio stations and mobile networks.","vi":"Các dịch vụ khẩn cấp truyền đạt cảnh báo thời tiết tới các cộng đồng vùng sâu vùng xa thông qua các đài phát thanh địa phương và mạng di động.","audioKind":"ex2"}],"collocations":[{"en":"relay race","vi":"chạy tiếp sức"},{"en":"relay a message","vi":"truyền đạt một thông điệp"},{"en":"relay information","vi":"truyền thông tin"},{"en":"electrical relay","vi":"rơ-le điện"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Động từ relay cũng được phát âm là /rɪˈleɪ/; relay a message nghĩa là truyền đạt thông tin.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_archery', 'en-b2-63', 'archery', '/ˈɑːrtʃəri/', 'B2', 'môn bắn cung; kỹ thuật bắn cung', 'n.', 'archer (n.)', NULL, 'archery là danh từ không đếm được; vận động viên bắn cung gọi là archer.', 'We tried archery at a supervised outdoor activity centre.', NULL, 'Chúng tôi đã thử môn bắn cung tại một trung tâm hoạt động ngoài trời có người hướng dẫn.', '{"wordId":"archery","ukIpa":"/ˈɑːtʃəri/","usIpa":"/ˈɑːrtʃəri/","cefr":"B2","topic":"sport","senses":[{"pos":"n.","en":"the sport or skill of shooting arrows with a bow","vi":"môn bắn cung; kỹ thuật bắn cung"}],"examples":[{"en":"We tried archery at a supervised outdoor activity centre.","vi":"Chúng tôi đã thử môn bắn cung tại một trung tâm hoạt động ngoài trời có người hướng dẫn.","audioKind":"ex"},{"en":"Offering archery in schools could introduce students to a sport that develops concentration and physical coordination.","vi":"Việc đưa môn bắn cung vào trường học có thể giới thiệu cho học sinh một môn thể thao giúp phát triển sự tập trung và khả năng phối hợp thể chất.","audioKind":"ex2"}],"collocations":[{"en":"practise archery","vi":"tập bắn cung"},{"en":"an archery club","vi":"câu lạc bộ bắn cung"},{"en":"an archery range","vi":"bãi bắn cung"}],"wordFamily":["archer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"archery là danh từ không đếm được; vận động viên bắn cung gọi là archer.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_kitesurfing', 'en-b2-63', 'kitesurfing', '/ˈkaɪtsɜːrfɪŋ/', 'B2', 'lướt ván diều', 'n.', 'kitesurf (v.), kitesurfer (n.)', 'Đồng nghĩa: kiteboarding', 'Chỉ môn thể thao được diều kéo lướt đi, khác với môn lướt ván buồm windsurfing.', 'My cousin tried kitesurfing at the beach yesterday.', NULL, 'Anh họ tôi đã thử môn lướt ván diều ở bãi biển vào ngày hôm qua.', '{"wordId":"kitesurfing","ukIpa":"/ˈkaɪtsɜːfɪŋ/","usIpa":"/ˈkaɪtsɜːrfɪŋ/","cefr":"B2","topic":"sport","senses":[{"pos":"n.","en":"Riding a board across water while pulled by a kite.","vi":"lướt ván diều"}],"examples":[{"en":"My cousin tried kitesurfing at the beach yesterday.","vi":"Anh họ tôi đã thử môn lướt ván diều ở bãi biển vào ngày hôm qua.","audioKind":"ex"},{"en":"Coastal resorts offering kitesurfing should separate training areas from swimming zones to reduce accidents.","vi":"Các khu nghỉ dưỡng ven biển cung cấp dịch vụ lướt ván diều nên tách biệt khu vực tập luyện và khu vực bơi lội để giảm thiểu tai nạn.","audioKind":"ex2"}],"collocations":[{"en":"go kitesurfing","vi":"đi lướt ván diều"},{"en":"kitesurfing lessons","vi":"các bài học lướt ván diều"},{"en":"kitesurfing equipment","vi":"dụng cụ lướt ván diều"}],"wordFamily":["kitesurf (v.)","kitesurfer (n.)"],"synonyms":["kiteboarding"],"antonyms":[],"tipVi":"Chỉ môn thể thao được diều kéo lướt đi, khác với môn lướt ván buồm windsurfing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_63_1', 'en-b2-63', 'Cách dùng “spectator” (n.) — khán giả (xem sự kiện thể thao); người xem', 'spectator sport  ·  spectator safety  ·  attract spectators', 'Thường chỉ khán giả có mặt tại sự kiện thể thao; khán giả xem biểu diễn nghệ thuật thường dùng audience.', 'Họ từ (Word Family): spectate (v.) | Đồng nghĩa: onlooker, viewer · Trái nghĩa: participant', '[{"hanzi":"A spectator caught the ball near the fence.","pinyin":"","meaning":"Một khán giả đã bắt được quả bóng ở gần hàng rào."},{"hanzi":"Major sporting events attract thousands of spectators and can generate substantial income for local businesses.","pinyin":"","meaning":"Các sự kiện thể thao lớn thu hút hàng nghìn khán giả và có thể mang lại nguồn thu nhập đáng kể cho các doanh nghiệp địa phương."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_63_2', 'en-b2-63', 'Cách dùng “recreational” (adj.) — giải trí; mang tính thư giãn', 'recreational activities  ·  recreational facilities  ·  recreational use', 'Thường đi kèm với "activities" hoặc "facilities", nhằm nhấn mạnh tính chất giải trí thay vì công việc.', 'Họ từ (Word Family): recreation (n.), recreationally (adv.)', '[{"hanzi":"The lake is a popular spot for recreational fishing.","pinyin":"","meaning":"Hồ nước này là một điểm đến phổ biến cho hoạt động câu cá giải trí."},{"hanzi":"Providing affordable recreational facilities can improve public health and strengthen social connections within urban communities.","pinyin":"","meaning":"Việc cung cấp các cơ sở vật chất giải trí vừa túi tiền có thể cải thiện sức khỏe cộng đồng và thắt chặt các mối quan hệ xã hội trong các cộng đồng đô thị."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_63_3', 'en-b2-63', 'Cách dùng “saddle” (n.) — yên ngựa; yên xe đạp', 'adjust the saddle  ·  saddle a horse  ·  be saddled with debt', 'Cấu trúc saddle someone with dùng để chỉ việc bắt ai đó phải gánh vác một gánh nặng không mong muốn.', NULL, '[{"hanzi":"I lowered the saddle before riding my new bicycle.","pinyin":"","meaning":"Tôi đã hạ thấp yên xe trước khi đi chiếc xe đạp mới của mình."},{"hanzi":"Excessive university fees can saddle graduates with debts that limit their career choices for many years.","pinyin":"","meaning":"Học phí đại học quá cao có thể khiến sinh viên mới tốt nghiệp gánh chịu những khoản nợ giới hạn lựa chọn nghề nghiệp của họ trong nhiều năm."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_63_4', 'en-b2-63', 'Cách dùng “scout” (n.) — trinh sát viên; trinh sát; tuyển trạch viên; cầu thủ được nhắm đến', 'a talent scout  ·  a football scout  ·  scout for talent', 'Scout for đi với đối tượng đang tìm kiếm; từ chỉ thành viên hướng đạo sinh thường viết hoa là Scout.', 'Họ từ (Word Family): scouting (n.)', '[{"hanzi":"A scout watched our team practise after school.","pinyin":"","meaning":"Một tuyển trạch viên đã theo dõi đội của chúng tôi tập luyện sau giờ học."},{"hanzi":"Sports clubs often scout for talented young players in communities that lack access to professional training facilities.","pinyin":"","meaning":"Các câu lạc bộ thể thao thường tìm kiếm những cầu thủ trẻ tài năng ở những cộng đồng thiếu cơ sở vật chất tập luyện chuyên nghiệp."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_63_1', 'en-b2-63', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_63_1_1', 'ten_b2_63_1', 'clubhouse', 'We left our tennis bags outside the clubhouse.', 'We left our tennis bags outside the clubhouse.', '/ˈklʌbhaʊs/', 'Chúng tôi để những chiếc túi đựng vợt quần vợt ở bên ngoài nhà câu lạc bộ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_63_1_2', 'ten_b2_63_1', 'triumph', 'Winning the local chess tournament was a triumph for Amir.', 'Winning the local chess tournament was a triumph for Amir.', '/ˈtraɪʌmf/', 'Giành chiến thắng trong giải cờ vua địa phương là một thành tựu lớn đối với Amir.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_63_1_3', 'ten_b2_63_1', 'saddle', 'I lowered the saddle before riding my new bicycle.', 'I lowered the saddle before riding my new bicycle.', '/ˈsædəl/', 'Tôi đã hạ thấp yên xe trước khi đi chiếc xe đạp mới của mình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_63_1_4', 'ten_b2_63_1', 'punch', 'She punched the training bag, then caught her breath.', 'She punched the training bag, then caught her breath.', '/pʌntʃ/', 'Cô ấy đấm vào bao cát tập luyện, rồi lấy lại hơi thở.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_63_1_5', 'ten_b2_63_1', 'recreational', 'The lake is a popular spot for recreational fishing.', 'The lake is a popular spot for recreational fishing.', '/ˌrekriˈeɪʃənəl/', 'Hồ nước này là một điểm đến phổ biến cho hoạt động câu cá giải trí.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_63_1_6', 'ten_b2_63_1', 'pitch', 'The players ran onto the pitch despite the rain.', 'The players ran onto the pitch despite the rain.', '/pɪtʃ/', 'Các cầu thủ vẫn chạy ra sân thi đấu mặc cho trời mưa.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_63_1_7', 'ten_b2_63_1', 'scout', 'A scout watched our team practise after school.', 'A scout watched our team practise after school.', '/skaʊt/', 'Một tuyển trạch viên đã theo dõi đội của chúng tôi tập luyện sau giờ học.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_63_1_8', 'ten_b2_63_1', 'oar', 'He lifted one oar and gently pushed the boat away.', 'He lifted one oar and gently pushed the boat away.', '/ɔːr/', 'Anh ấy nâng một chiếc mái chèo lên và nhẹ nhàng đẩy chiếc thuyền ra.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_63_1_1', 'en-b2-63', 'ten_b2_63_1', 'listening', 'listening', 'We left our tennis bags outside the clubhouse.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Giành chiến thắng trong giải cờ vua địa phương là một thành tựu lớn đối với Amir.","Anh ấy nâng một chiếc mái chèo lên và nhẹ nhàng đẩy chiếc thuyền ra.","Chúng tôi để những chiếc túi đựng vợt quần vợt ở bên ngoài nhà câu lạc bộ.","Dù chỉ là một người nghiệp dư, cô ấy vẫn chụp được những bức ảnh chim chóc rất đẹp."]'::jsonb, 2, 'We left our tennis bags outside the clubhouse. → Chúng tôi để những chiếc túi đựng vợt quần vợt ở bên ngoài nhà câu lạc bộ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_63_1_2', 'en-b2-63', 'ten_b2_63_1', 'listening', 'listening', 'Winning the local chess tournament was a triumph for Amir.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Các cầu thủ vẫn chạy ra sân thi đấu mặc cho trời mưa.","Đội chúng tôi đã làm rơi gậy trong cuộc thi chạy tiếp sức của trường.","Giành chiến thắng trong giải cờ vua địa phương là một thành tựu lớn đối với Amir.","Chúng tôi để những chiếc túi đựng vợt quần vợt ở bên ngoài nhà câu lạc bộ."]'::jsonb, 2, 'Winning the local chess tournament was a triumph for Amir. → Giành chiến thắng trong giải cờ vua địa phương là một thành tựu lớn đối với Amir.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_63_1_3', 'en-b2-63', 'ten_b2_63_1', 'listening', 'listening', 'I lowered the saddle before riding my new bicycle.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hồ nước này là một điểm đến phổ biến cho hoạt động câu cá giải trí.","Chị tôi tham gia một lớp học tự vệ vào thứ Bảy hàng tuần.","Tôi đã hạ thấp yên xe trước khi đi chiếc xe đạp mới của mình.","Trận đấu tối nay là cuộc đối đầu giữa trường chúng ta và trường cao đẳng địa phương."]'::jsonb, 2, 'I lowered the saddle before riding my new bicycle. → Tôi đã hạ thấp yên xe trước khi đi chiếc xe đạp mới của mình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_63_2', 'en-b2-63', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_63_2_1', 'ten_b2_63_2', 'clubhouse', 'A shared clubhouse can strengthen community ties by giving local sports teams a place to meet regularly.', 'A shared clubhouse can strengthen community ties by giving local sports teams a place to meet regularly.', '/ˈklʌbhaʊs/', 'Một nhà câu lạc bộ chung có thể củng cố mối liên kết cộng đồng bằng cách cung cấp cho các đội thể thao địa phương một nơi để gặp gỡ thường xuyên.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_63_2_2', 'ten_b2_63_2', 'triumph', 'The successful restoration of the wetland represents a triumph for conservation groups and local residents.', 'The successful restoration of the wetland represents a triumph for conservation groups and local residents.', '/ˈtraɪʌmf/', 'Việc phục hồi thành công vùng đất ngập nước đánh dấu một thắng lợi to lớn đối với các nhóm bảo tồn và người dân địa phương.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_63_2_3', 'ten_b2_63_2', 'saddle', 'Excessive university fees can saddle graduates with debts that limit their career choices for many years.', 'Excessive university fees can saddle graduates with debts that limit their career choices for many years.', '/ˈsædəl/', 'Học phí đại học quá cao có thể khiến sinh viên mới tốt nghiệp gánh chịu những khoản nợ giới hạn lựa chọn nghề nghiệp của họ trong nhiều năm.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_63_2_4', 'ten_b2_63_2', 'punch', 'Boxers learn to deliver a controlled punch while maintaining balance and protecting themselves from injury.', 'Boxers learn to deliver a controlled punch while maintaining balance and protecting themselves from injury.', '/pʌntʃ/', 'Các võ sĩ quyền anh học cách tung ra cú đấm có kiểm soát đồng thời giữ thăng bằng và bảo vệ bản thân khỏi chấn thương.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_63_2_5', 'ten_b2_63_2', 'recreational', 'Providing affordable recreational facilities can improve public health and strengthen social connections within urban communities.', 'Providing affordable recreational facilities can improve public health and strengthen social connections within urban communities.', '/ˌrekriˈeɪʃənəl/', 'Việc cung cấp các cơ sở vật chất giải trí vừa túi tiền có thể cải thiện sức khỏe cộng đồng và thắt chặt các mối quan hệ xã hội trong các cộng đồng đô thị.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_63_2_6', 'ten_b2_63_2', 'pitch', 'Young entrepreneurs often pitch their business ideas to investors who can provide funding and practical guidance.', 'Young entrepreneurs often pitch their business ideas to investors who can provide funding and practical guidance.', '/pɪtʃ/', 'Các nhà khởi nghiệp trẻ thường thuyết trình ý tưởng kinh doanh của họ trước các nhà đầu tư có thể cung cấp nguồn vốn và định hướng thực tế.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_63_2_1', 'en-b2-63', 'ten_b2_63_2', 'listening', 'listening', 'A shared clubhouse can strengthen community ties by giving local sports teams a place to meet regularly.', NULL, 'Trong câu vừa nghe, từ “clubhouse” mang nghĩa nào sau đây?', '["phần cứng máy tính","nhà câu lạc bộ; trụ sở câu lạc bộ","đối thủ; người cạnh tranh","sự tiến bộ; bước tiến; sự phát triển"]'::jsonb, 1, '“clubhouse” (/ˈklʌbhaʊs/): nhà câu lạc bộ; trụ sở câu lạc bộ. Câu đầy đủ: A shared clubhouse can strengthen community ties by giving local sports teams a place to meet regularly.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_63_2_2', 'en-b2-63', 'ten_b2_63_2', 'listening', 'listening', 'The successful restoration of the wetland represents a triumph for conservation groups and local residents.', NULL, 'Trong câu vừa nghe, từ “triumph” mang nghĩa nào sau đây?', '["vô cùng ngốc nghếch; phi lý; nguy hiểm","thắng lợi lớn; thành tựu vẻ vang","khoản đầu tư; tiền đầu tư","sự chôn cất; lễ an táng"]'::jsonb, 1, '“triumph” (/ˈtraɪʌmf/): thắng lợi lớn; thành tựu vẻ vang. Câu đầy đủ: The successful restoration of the wetland represents a triumph for conservation groups and local residents.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
