INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_63_1', 'en-b2-63', NULL, 'comprehensive_test', 'listening', 'clubhouse', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["theo hướng sang bên, xoay ngang người","làm phẳng; san phẳng","sự nhập cư; việc di cư vào nước khác","nhà câu lạc bộ; trụ sở câu lạc bộ"]'::jsonb, 3, 'clubhouse (/ˈklʌbhaʊs/) → nhà câu lạc bộ; trụ sở câu lạc bộ', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_63_2', 'en-b2-63', NULL, 'comprehensive_test', 'listening', 'Winning the local chess tournament was a triumph for Amir.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Dù chỉ là một người nghiệp dư, cô ấy vẫn chụp được những bức ảnh chim chóc rất đẹp.","Giành chiến thắng trong giải cờ vua địa phương là một thành tựu lớn đối với Amir.","Chúng tôi đã cố định các túi ngủ bằng một sợi dây thun co giãn chắc chắn.","Anh ấy nâng một chiếc mái chèo lên và nhẹ nhàng đẩy chiếc thuyền ra."]'::jsonb, 1, 'Winning the local chess tournament was a triumph for Amir. → Giành chiến thắng trong giải cờ vua địa phương là một thành tựu lớn đối với Amir.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_63_3', 'en-b2-63', NULL, 'comprehensive_test', 'listening', 'saddle', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đòi hỏi nhiều nỗ lực; khắt khe; vất vả","yên ngựa; yên xe đạp","thủ tục; quy trình; bước thực hiện","thể tích; khối lượng; tổng lượng"]'::jsonb, 1, 'saddle (/ˈsædəl/) → yên ngựa; yên xe đạp; đóng yên ngựa; bắt gánh vác; chất gánh nặng cho ai', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_63_4', 'en-b2-63', NULL, 'comprehensive_test', 'listening', 'She punched the training bag, then caught her breath.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Các cầu thủ vẫn chạy ra sân thi đấu mặc cho trời mưa.","Trận đấu tối nay là cuộc đối đầu giữa trường chúng ta và trường cao đẳng địa phương.","Anh họ tôi đã thử môn lướt ván diều ở bãi biển vào ngày hôm qua.","Cô ấy đấm vào bao cát tập luyện, rồi lấy lại hơi thở."]'::jsonb, 3, 'She punched the training bag, then caught her breath. → Cô ấy đấm vào bao cát tập luyện, rồi lấy lại hơi thở.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_63_5', 'en-b2-63', NULL, 'comprehensive_test', 'listening', 'recreational', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["làm tối đi; trở nên tối hơn","mối liên kết; sự gắn bó; tình cảm","giải trí; mang tính thư giãn","liên tục; không ngừng"]'::jsonb, 2, 'recreational (/ˌrekriˈeɪʃənəl/) → giải trí; mang tính thư giãn', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_63_6', 'en-b2-63', NULL, 'comprehensive_test', 'listening', 'The players ran onto the pitch despite the rain.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một khán giả đã bắt được quả bóng ở gần hàng rào.","Chúng tôi để những chiếc túi đựng vợt quần vợt ở bên ngoài nhà câu lạc bộ.","Trận đấu tối nay là cuộc đối đầu giữa trường chúng ta và trường cao đẳng địa phương.","Các cầu thủ vẫn chạy ra sân thi đấu mặc cho trời mưa."]'::jsonb, 3, 'The players ran onto the pitch despite the rain. → Các cầu thủ vẫn chạy ra sân thi đấu mặc cho trời mưa.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_63_7', 'en-b2-63', NULL, 'comprehensive_test', 'listening', 'scout', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["trinh sát viên; trinh sát; tuyển trạch viên; cầu thủ được nhắm đến","động vật ăn thịt; động vật săn mồi","giẻ lau; vải vụn","có sức thuyết phục"]'::jsonb, 0, 'scout (/skaʊt/) → trinh sát viên; trinh sát; tuyển trạch viên; cầu thủ được nhắm đến; tìm kiếm; dò la; hướng đạo sinh', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
