INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_63_18', 'en-b2-63', NULL, 'comprehensive_test', 'reading', NULL, 'A shared clubhouse can strengthen community ties by giving local sports teams a place to meet regularly.', 'Dựa vào câu trên, từ “clubhouse” có nghĩa phù hợp nhất là gì?', '["bệnh béo phì","gieo hạt; gieo trồng","nhà câu lạc bộ; trụ sở câu lạc bộ","đất liền; đại lục"]'::jsonb, 2, 'clubhouse: nhà câu lạc bộ; trụ sở câu lạc bộ. Dịch cả câu: Một nhà câu lạc bộ chung có thể củng cố mối liên kết cộng đồng bằng cách cung cấp cho các đội thể thao địa phương một nơi để gặp gỡ thường xuyên.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_63_19', 'en-b2-63', NULL, 'comprehensive_test', 'reading', NULL, 'The successful restoration of the wetland represents a triumph for conservation groups and local residents.', 'Dựa vào câu trên, từ “triumph” có nghĩa phù hợp nhất là gì?', '["thắng lợi lớn; thành tựu vẻ vang","sự gia hạn; sự đổi mới hợp đồng","sự sống sót; sự tồn tại; sự sinh tồn","bài tường thuật; câu chuyện"]'::jsonb, 0, 'triumph: thắng lợi lớn; thành tựu vẻ vang; niềm vui chiến thắng; niềm tự hào; giành chiến thắng; chiến thắng; vượt qua. Dịch cả câu: Việc phục hồi thành công vùng đất ngập nước đánh dấu một thắng lợi to lớn đối với các nhóm bảo tồn và người dân địa phương.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_63_20', 'en-b2-63', NULL, 'comprehensive_test', 'reading', NULL, 'Excessive university fees can saddle graduates with debts that limit their career choices for many years.', 'Dựa vào câu trên, từ “saddle” có nghĩa phù hợp nhất là gì?', '["trái đạo đức; đồi phong bại tục; bất chính","yên ngựa; yên xe đạp","sự thiếu hụt; tình trạng khan hiếm","bất chấp; mặc dù; bất kể"]'::jsonb, 1, 'saddle: yên ngựa; yên xe đạp; đóng yên ngựa; bắt gánh vác; chất gánh nặng cho ai. Dịch cả câu: Học phí đại học quá cao có thể khiến sinh viên mới tốt nghiệp gánh chịu những khoản nợ giới hạn lựa chọn nghề nghiệp của họ trong nhiều năm.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_63_21', 'en-b2-63', NULL, 'comprehensive_test', 'reading', NULL, 'Boxers learn to deliver a controlled punch while maintaining balance and protecting themselves from injury.', 'Dựa vào câu trên, từ “punch” có nghĩa phù hợp nhất là gì?', '["đấm; thụi","bò đực đã bị thiến dùng để kéo cày, bò kéo, trâu bò lực lưỡng","mọc lông tơ; mềm mại","nhân vật phản diện; kẻ ác"]'::jsonb, 0, 'punch: đấm; thụi; cú đấm; đục lỗ. Dịch cả câu: Các võ sĩ quyền anh học cách tung ra cú đấm có kiểm soát đồng thời giữ thăng bằng và bảo vệ bản thân khỏi chấn thương.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_63_22', 'en-b2-63', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cuộc thi chạy tiếp sức; môn tiếp sức”', '["canyon","pastime","relay","wasp"]'::jsonb, 2, 'cuộc thi chạy tiếp sức; môn tiếp sức → relay (/ˈriːleɪ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_63_23', 'en-b2-63', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “môn bắn cung; kỹ thuật bắn cung”', '["bungalow","archery","emigrate","enclose"]'::jsonb, 1, 'môn bắn cung; kỹ thuật bắn cung → archery (/ˈɑːrtʃəri/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_63_24', 'en-b2-63', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “lướt ván diều”', '["existence","explosive","kitesurfing","disturbance"]'::jsonb, 2, 'lướt ván diều → kitesurfing (/ˈkaɪtsɜːrfɪŋ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-64', 'en', 'Bài 64: Công nghệ & Kỹ thuật (1) - CEFR B2', 'CEFR B2', 'B2 · Công nghệ', '22 từ vựng Tiếng Anh CEFR B2 chủ đề công nghệ & kỹ thuật kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4064, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_modification', 'en-b2-64', 'modification', '/ˌmɑːdəfəˈkeɪʃən/', 'B2', 'sự sửa đổi, sự cải tiến, sự điều chỉnh', 'n.', 'modify (v.), modified (adj.), modifier (n.)', 'Đồng nghĩa: alteration, adjustment', 'Khi đếm được, từ này chỉ sự thay đổi cụ thể; khi không đếm được, nó chỉ quá trình sửa đổi.', 'This small modification makes the chair much more comfortable.', NULL, 'Sự điều chỉnh nhỏ này giúp chiếc ghế thoải mái hơn rất nhiều.', '{"wordId":"modification","ukIpa":"/ˌmɒdɪfɪˈkeɪʃən/","usIpa":"/ˌmɑːdəfəˈkeɪʃən/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"A change made to improve something or suit a purpose.","vi":"sự sửa đổi, sự cải tiến, sự điều chỉnh"}],"examples":[{"en":"This small modification makes the chair much more comfortable.","vi":"Sự điều chỉnh nhỏ này giúp chiếc ghế thoải mái hơn rất nhiều.","audioKind":"ex"},{"en":"Modification of existing buildings can reduce energy consumption without the environmental costs of new construction.","vi":"Việc cải tạo các tòa nhà hiện có có thể làm giảm mức tiêu thụ năng lượng mà không tốn kém chi phí môi trường như việc xây mới.","audioKind":"ex2"}],"collocations":[{"en":"make a modification","vi":"thực hiện sự sửa đổi"},{"en":"minor modification","vi":"sự điều chỉnh nhỏ"},{"en":"genetic modification","vi":"sự biến đổi gen"}],"wordFamily":["modify (v.)","modified (adj.)","modifier (n.)"],"synonyms":["alteration","adjustment"],"antonyms":[],"tipVi":"Khi đếm được, từ này chỉ sự thay đổi cụ thể; khi không đếm được, nó chỉ quá trình sửa đổi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_activated', 'en-b2-64', 'activated', '/ˈæktɪveɪtɪd/', 'B2', 'được kích hoạt; được khởi động; được hoạt hóa', 'v.', 'activate (v.), activation (n.), deactivate (v.), active (adj.)', 'Trái nghĩa: deactivated', 'là quá khứ và phân từ của activate; không dùng để chỉ tính cách năng động.', 'The moving cat activated the light above our door.', NULL, 'Con mèo di chuyển đã kích hoạt chiếc đèn phía trên cửa nhà chúng tôi.', '{"wordId":"activated","ukIpa":"/ˈæktɪveɪtɪd/","usIpa":"/ˈæktɪveɪtɪd/","cefr":"B2","topic":"technology","senses":[{"pos":"v.","en":"Made a device or process start working.","vi":"được kích hoạt; được khởi động"},{"pos":"adj.","en":"Treated to increase chemical activity or ability to absorb substances.","vi":"được hoạt hóa"}],"examples":[{"en":"The moving cat activated the light above our door.","vi":"Con mèo di chuyển đã kích hoạt chiếc đèn phía trên cửa nhà chúng tôi.","audioKind":"ex"},{"en":"The emergency warning system was activated immediately after sensors detected unusual movement beneath the ocean.","vi":"Hệ thống cảnh báo khẩn cấp được kích hoạt ngay lập tức sau khi các cảm biến phát hiện chuyển động bất thường dưới đáy biển.","audioKind":"ex2"}],"collocations":[{"en":"activated carbon","vi":"than hoạt tính"},{"en":"activated charcoal","vi":"than hoạt tính"},{"en":"voice-activated device","vi":"thiết bị kích hoạt bằng giọng nói"}],"wordFamily":["activate (v.)","activation (n.)","deactivate (v.)","active (adj.)"],"synonyms":[],"antonyms":["deactivated"],"tipVi":"là quá khứ và phân từ của activate; không dùng để chỉ tính cách năng động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_videotape', 'en-b2-64', 'videotape', '/ˈvɪdioʊteɪp/', 'B2', 'băng hình; băng video; ghi hình vào băng video', 'n.', 'video (n.)', NULL, 'Chỉ băng ghi hình dạng từ tính cũ; các thiết bị ghi hình số hiện đại thường dùng video hoặc record.', 'We found an old videotape of our family picnic.', NULL, 'Chúng tôi tìm thấy một cuộn băng video cũ ghi lại cảnh gia đình đi dã ngoại.', '{"wordId":"videotape","ukIpa":"/ˈvɪdiəʊteɪp/","usIpa":"/ˈvɪdioʊteɪp/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"Magnetic tape used to record moving images and sound.","vi":"băng hình; băng video"},{"pos":"v.","en":"To record moving images and sound onto magnetic tape.","vi":"ghi hình vào băng video"}],"examples":[{"en":"We found an old videotape of our family picnic.","vi":"Chúng tôi tìm thấy một cuộn băng video cũ ghi lại cảnh gia đình đi dã ngoại.","audioKind":"ex"},{"en":"Libraries can preserve recordings stored on videotape by converting them into digital formats for future generations.","vi":"Các thư viện có thể bảo quản các bản ghi trên băng video bằng cách chuyển đổi chúng sang định dạng kỹ thuật số cho các thế hệ mai sau.","audioKind":"ex2"}],"collocations":[{"en":"an old videotape","vi":"một cuộn băng video cũ"},{"en":"on videotape","vi":"dưới dạng băng video"},{"en":"videotape a performance","vi":"ghi hình một buổi biểu diễn"}],"wordFamily":["video (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ băng ghi hình dạng từ tính cũ; các thiết bị ghi hình số hiện đại thường dùng video hoặc record.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_accelerate', 'en-b2-64', 'accelerate', '/əkˈseləreɪt/', 'B2', 'tăng tốc; làm nhanh hơn', 'v.', 'acceleration (n.), accelerator (n.)', 'Đồng nghĩa: speed up, hasten · Trái nghĩa: decelerate, slow down', 'Có thể dùng để chỉ phương tiện tăng tốc hoặc tiến trình được đẩy nhanh; có thể là ngoại động từ hoặc nội động từ.', 'The bus accelerated as it left the village.', NULL, 'Chiếc xe buýt tăng tốc khi rời khỏi ngôi làng.', '{"wordId":"accelerate","ukIpa":"/əkˈseləreɪt/","usIpa":"/əkˈseləreɪt/","cefr":"B2","topic":"technology","senses":[{"pos":"v.","en":"to move faster or make something happen more quickly","vi":"tăng tốc; làm nhanh hơn"}],"examples":[{"en":"The bus accelerated as it left the village.","vi":"Chiếc xe buýt tăng tốc khi rời khỏi ngôi làng.","audioKind":"ex"},{"en":"Investment in public transport can accelerate the transition towards cleaner and more efficient urban travel.","vi":"Việc đầu tư vào giao thông công cộng có thể thúc đẩy quá trình chuyển đổi sang hình thức di chuyển đô thị sạch hơn và hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"accelerate growth","vi":"tăng tốc độ tăng trưởng"},{"en":"accelerate the process","vi":"thúc đẩy tiến trình"},{"en":"accelerate rapidly","vi":"tăng tốc nhanh chóng"}],"wordFamily":["acceleration (n.)","accelerator (n.)"],"synonyms":["speed up","hasten"],"antonyms":["decelerate","slow down"],"tipVi":"Có thể dùng để chỉ phương tiện tăng tốc hoặc tiến trình được đẩy nhanh; có thể là ngoại động từ hoặc nội động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_input', 'en-b2-64', 'input', '/ˈɪnpʊt/', 'B2', 'thông tin đầu vào; nguồn lực đầu vào; ý kiến đóng góp; lời khuyên; nhập dữ liệu', 'n.', NULL, 'Trái nghĩa: output', 'Khi là động từ, dạng quá khứ có thể là input hoặc inputted.', 'Please input your address before choosing a delivery time.', NULL, 'Vui lòng nhập địa chỉ của bạn trước khi chọn thời gian giao hàng.', '{"wordId":"input","ukIpa":"/ˈɪnpʊt/","usIpa":"/ˈɪnpʊt/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"information or resources supplied to a system or process","vi":"thông tin đầu vào; nguồn lực đầu vào"},{"pos":"n.","en":"ideas or advice contributed to a discussion or task","vi":"ý kiến đóng góp; lời khuyên"},{"pos":"v.","en":"to enter information into a computer or other device","vi":"nhập dữ liệu"}],"examples":[{"en":"Please input your address before choosing a delivery time.","vi":"Vui lòng nhập địa chỉ của bạn trước khi chọn thời gian giao hàng.","audioKind":"ex"},{"en":"Community input can help planners design public spaces that better reflect local needs.","vi":"Ý kiến đóng góp từ cộng đồng có thể giúp các nhà quy hoạch thiết kế các không gian công cộng phản ánh tốt hơn nhu cầu của địa phương.","audioKind":"ex2"}],"collocations":[{"en":"data input","vi":"nhập dữ liệu"},{"en":"valuable input","vi":"ý kiến đóng góp quý giá"},{"en":"input data","vi":"dữ liệu đầu vào"},{"en":"labour input","vi":"nguồn lực lao động"}],"wordFamily":[],"synonyms":[],"antonyms":["output"],"tipVi":"Khi là động từ, dạng quá khứ có thể là input hoặc inputted.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_simplicity', 'en-b2-64', 'simplicity', '/sɪmˈplɪsəti/', 'B2', 'tính đơn giản; sự dễ hiểu; sự giản dị; tính mộc mạc', 'n.', 'simple (adj.), simply (adv.), simplify (v.), simplification (n.)', 'Trái nghĩa: complexity', 'simplicity thường không đếm được; là danh từ của simple.', 'I love the simplicity of this easy vegetable soup recipe.', NULL, 'Tôi thích sự đơn giản của công thức nấu món súp rau củ dễ làm này.', '{"wordId":"simplicity","ukIpa":"/sɪmˈplɪsəti/","usIpa":"/sɪmˈplɪsəti/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"The quality of being easy to understand or use.","vi":"tính đơn giản; sự dễ hiểu"},{"pos":"n.","en":"The quality of having little decoration or unnecessary detail.","vi":"sự giản dị; tính mộc mạc"}],"examples":[{"en":"I love the simplicity of this easy vegetable soup recipe.","vi":"Tôi thích sự đơn giản của công thức nấu món súp rau củ dễ làm này.","audioKind":"ex"},{"en":"The simplicity of a digital service can determine whether older users feel confident accessing essential information independently.","vi":"Tính tiện dụng của một dịch vụ số có thể quyết định việc người dùng lớn tuổi có tự tin tiếp cận thông tin thiết yếu hay không.","audioKind":"ex2"}],"collocations":[{"en":"for simplicity","vi":"để cho đơn giản"},{"en":"simplicity of design","vi":"sự thiết kế giản đơn"},{"en":"elegant simplicity","vi":"sự thanh lịch giản dị"}],"wordFamily":["simple (adj.)","simply (adv.)","simplify (v.)","simplification (n.)"],"synonyms":[],"antonyms":["complexity"],"tipVi":"simplicity thường không đếm được; là danh từ của simple.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_defect', 'en-b2-64', 'defect', '/ˈdiːfekt/', 'B2', 'khiếm khuyết; lỗi; sơ suất; đào ngũ; phản bội; chuyển sang phe đối lập', 'n.', 'defective (adj.), defection (n.), defector (n.)', 'Đồng nghĩa: flaw, fault', 'Danh từ đọc trọng âm ở âm tiết đầu; động từ đọc trọng âm ở âm tiết thứ hai /dɪˈfekt/.', 'A small defect in the kettle caused it to leak.', NULL, 'Một lỗi nhỏ ở chiếc ấm đã làm nó bị rò rỉ nước.', '{"wordId":"defect","ukIpa":"/ˈdiːfekt/","usIpa":"/ˈdiːfekt/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"A fault that makes something imperfect or unable to work properly.","vi":"khiếm khuyết; lỗi; sơ suất"},{"pos":"v.","en":"To leave a country or group and join an opposing one.","vi":"đào ngũ; phản bội; chuyển sang phe đối lập"}],"examples":[{"en":"A small defect in the kettle caused it to leak.","vi":"Một lỗi nhỏ ở chiếc ấm đã làm nó bị rò rỉ nước.","audioKind":"ex"},{"en":"Manufacturers should identify any design defect before a product reaches consumers, particularly when safety is at risk.","vi":"Các nhà sản xuất nên phát hiện bất kỳ lỗi thiết kế nào trước khi sản phẩm đến tay người tiêu dùng, đặc biệt là khi liên quan đến vấn đề an toàn.","audioKind":"ex2"}],"collocations":[{"en":"a design defect","vi":"lỗi thiết kế"},{"en":"a manufacturing defect","vi":"lỗi sản xuất"},{"en":"a birth defect","vi":"dị tật bẩm sinh"},{"en":"defect to the opposition","vi":"đào ngũ sang phe đối lập"}],"wordFamily":["defective (adj.)","defection (n.)","defector (n.)"],"synonyms":["flaw","fault"],"antonyms":[],"tipVi":"Danh từ đọc trọng âm ở âm tiết đầu; động từ đọc trọng âm ở âm tiết thứ hai /dɪˈfekt/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_electronics', 'en-b2-64', 'electronics', '/ɪˌlekˈtrɑːnɪks/', 'B2', 'điện tử học; kỹ thuật điện tử; thiết bị điện tử', 'n.', 'electronic (adj.), electronically (adv.), electron (n.)', NULL, 'Khi chỉ môn điện tử, dù có tận cùng bằng s nhưng động từ đi kèm vẫn ở số ít.', 'My sister studies electronics and repairs radios at home.', NULL, 'Em gái tôi học ngành điện tử và tự sửa đài ở nhà.', '{"wordId":"electronics","ukIpa":"/ɪˌlekˈtrɒnɪks/","usIpa":"/ɪˌlekˈtrɑːnɪks/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"the study and use of electronic circuits and devices","vi":"điện tử học; kỹ thuật điện tử"},{"pos":"n.","en":"devices that operate using electronic circuits","vi":"thiết bị điện tử"}],"examples":[{"en":"My sister studies electronics and repairs radios at home.","vi":"Em gái tôi học ngành điện tử và tự sửa đài ở nhà.","audioKind":"ex"},{"en":"Advances in electronics have enabled hospitals to monitor patients more accurately and provide faster treatment.","vi":"Sự tiến bộ của kỹ thuật điện tử đã giúp các bệnh viện theo dõi bệnh nhân chính xác hơn và điều trị nhanh chóng hơn.","audioKind":"ex2"}],"collocations":[{"en":"consumer electronics","vi":"thiết bị điện tử tiêu dùng"},{"en":"electronics industry","vi":"ngành công nghiệp điện tử"},{"en":"study electronics","vi":"học ngành điện tử"}],"wordFamily":["electronic (adj.)","electronically (adv.)","electron (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ môn điện tử, dù có tận cùng bằng s nhưng động từ đi kèm vẫn ở số ít.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_convert', 'en-b2-64', 'convert', '/kənˈvɝːt/', 'B2', 'chuyển đổi; biến đổi; cải tạo; cải đạo; thuyết phục ai cải đạo; người mới cải đạo; tín đồ mới', 'v.', 'conversion (n.), converter (n.), convertible (adj.)', 'Đồng nghĩa: transform', 'Động từ có trọng âm ở âm tiết sau; danh từ có trọng âm ở âm tiết đầu.', 'We converted the spare bedroom into a small office.', NULL, 'Chúng tôi đã cải tạo phòng ngủ trống thành một văn phòng nhỏ.', '{"wordId":"convert","ukIpa":"/kənˈvɜːt/","usIpa":"/kənˈvɝːt/","cefr":"B2","topic":"technology","senses":[{"pos":"v.","en":"to change something into a different form, purpose, or system","vi":"chuyển đổi; biến đổi; cải tạo"},{"pos":"v.","en":"to adopt a different religion or persuade someone to do so","vi":"cải đạo; thuyết phục ai cải đạo"},{"pos":"n.","en":"someone who has adopted a new religion, belief, or practice","vi":"người mới cải đạo; tín đồ mới"}],"examples":[{"en":"We converted the spare bedroom into a small office.","vi":"Chúng tôi đã cải tạo phòng ngủ trống thành một văn phòng nhỏ.","audioKind":"ex"},{"en":"Solar panels convert sunlight into electricity, allowing households to reduce their dependence on fossil fuels.","vi":"Các tấm pin mặt trời chuyển đổi ánh sáng mặt trời thành điện năng, cho phép các hộ gia đình giảm sự phụ thuộc vào nhiên liệu hóa thạch.","audioKind":"ex2"}],"collocations":[{"en":"convert into","vi":"chuyển đổi thành"},{"en":"convert to","vi":"chuyển sang; cải đạo sang"},{"en":"convert energy","vi":"chuyển đổi năng lượng"},{"en":"convert a building","vi":"cải tạo một tòa nhà"}],"wordFamily":["conversion (n.)","converter (n.)","convertible (adj.)"],"synonyms":["transform"],"antonyms":[],"tipVi":"Động từ có trọng âm ở âm tiết sau; danh từ có trọng âm ở âm tiết đầu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_transmit', 'en-b2-64', 'transmit', '/trænzˈmɪt/', 'B2', 'truyền (tín hiệu, thông tin, năng lượng); truyền bệnh; lây bệnh', 'v.', 'transmission (n.), transmitter (n.), transmissible (adj.)', 'Đồng nghĩa: send, relay', 'Dạng quá khứ là transmitted và dạng phân từ là transmitting, cả hai đều phải gấp đôi chữ t.', 'These tiny sensors transmit temperature readings to my phone.', NULL, 'Những cảm biến nhỏ này truyền các chỉ số nhiệt độ về điện thoại của tôi.', '{"wordId":"transmit","ukIpa":"/trænzˈmɪt/","usIpa":"/trænzˈmɪt/","cefr":"B2","topic":"technology","senses":[{"pos":"v.","en":"to send signals, information, or energy between places","vi":"truyền (tín hiệu, thông tin, năng lượng)"},{"pos":"v.","en":"to pass a disease from one living thing to another","vi":"truyền bệnh; lây bệnh"}],"examples":[{"en":"These tiny sensors transmit temperature readings to my phone.","vi":"Những cảm biến nhỏ này truyền các chỉ số nhiệt độ về điện thoại của tôi.","audioKind":"ex"},{"en":"Improved satellite networks can transmit vital information to remote communities during floods and other natural disasters.","vi":"Các mạng vệ tinh được cải tiến có thể truyền tải thông tin quan trọng đến các cộng đồng vùng sâu vùng xa trong các trận lũ lụt và thảm họa thiên nhiên khác.","audioKind":"ex2"}],"collocations":[{"en":"transmit data","vi":"truyền dữ liệu"},{"en":"transmit a signal","vi":"phát tín hiệu"},{"en":"transmit a virus","vi":"truyền virus"}],"wordFamily":["transmission (n.)","transmitter (n.)","transmissible (adj.)"],"synonyms":["send","relay"],"antonyms":[],"tipVi":"Dạng quá khứ là transmitted và dạng phân từ là transmitting, cả hai đều phải gấp đôi chữ t.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_activate', 'en-b2-64', 'activate', '/ˈæktɪveɪt/', 'B2', 'kích hoạt; khởi động', 'v.', 'activation (n.), active (adj.), deactivate (v.)', 'Đồng nghĩa: trigger, switch on · Trái nghĩa: deactivate', 'Nhấn mạnh việc làm cho thiết bị hoặc hệ thống bắt đầu hoạt động; từ trái nghĩa là deactivate.', 'Press this button to activate the outdoor lights.', NULL, 'Nhấn nút này để bật hệ thống đèn ngoài trời.', '{"wordId":"activate","ukIpa":"/ˈæktɪveɪt/","usIpa":"/ˈæktɪveɪt/","cefr":"B2","topic":"technology","senses":[{"pos":"v.","en":"Make a device, system, or process start working.","vi":"kích hoạt; khởi động"}],"examples":[{"en":"Press this button to activate the outdoor lights.","vi":"Nhấn nút này để bật hệ thống đèn ngoài trời.","audioKind":"ex"},{"en":"Smart sensors can activate ventilation systems automatically when indoor air quality falls below acceptable levels.","vi":"Các cảm biến thông minh có thể tự động khởi động hệ thống thông gió khi chất lượng không khí trong nhà giảm xuống dưới mức cho phép.","audioKind":"ex2"}],"collocations":[{"en":"activate an account","vi":"kích hoạt tài khoản"},{"en":"activate an alarm","vi":"kích hoạt báo động"},{"en":"activate a system","vi":"khởi động hệ thống"}],"wordFamily":["activation (n.)","active (adj.)","deactivate (v.)"],"synonyms":["trigger","switch on"],"antonyms":["deactivate"],"tipVi":"Nhấn mạnh việc làm cho thiết bị hoặc hệ thống bắt đầu hoạt động; từ trái nghĩa là deactivate.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_multifunction', 'en-b2-64', 'multifunction', '/ˌmʌltiˈfʌŋkʃən/', 'B2', 'đa chức năng', 'adj.', 'function (n.), function (v.), functional (adj.), multifunctional (adj.)', 'Đồng nghĩa: multifunctional, multipurpose · Trái nghĩa: single-purpose', 'Khi là tính từ, thường đặt trước danh từ chỉ thiết bị; cũng có thể dùng multifunctional.', 'Our multifunction printer can scan documents and make copies.', NULL, 'Máy in đa chức năng của chúng tôi có thể quét tài liệu và sao chụp.', '{"wordId":"multifunction","ukIpa":"/ˌmʌltiˈfʌŋkʃən/","usIpa":"/ˌmʌltiˈfʌŋkʃən/","cefr":"B2","topic":"technology","senses":[{"pos":"adj.","en":"Designed to perform several different tasks.","vi":"đa chức năng"}],"examples":[{"en":"Our multifunction printer can scan documents and make copies.","vi":"Máy in đa chức năng của chúng tôi có thể quét tài liệu và sao chụp.","audioKind":"ex"},{"en":"Multifunction devices can help small businesses save office space by combining several essential services in one machine.","vi":"Các thiết bị đa chức năng có thể giúp các doanh nghiệp nhỏ tiết kiệm không gian văn phòng bằng cách tích hợp nhiều dịch vụ thiết yếu vào một cỗ máy duy nhất.","audioKind":"ex2"}],"collocations":[{"en":"a multifunction printer","vi":"máy in đa chức năng"},{"en":"a multifunction device","vi":"thiết bị đa chức năng"},{"en":"a multifunction display","vi":"màn hình đa chức năng"}],"wordFamily":["function (n.)","function (v.)","functional (adj.)","multifunctional (adj.)"],"synonyms":["multifunctional","multipurpose"],"antonyms":["single-purpose"],"tipVi":"Khi là tính từ, thường đặt trước danh từ chỉ thiết bị; cũng có thể dùng multifunctional.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cutter', 'en-b2-64', 'cutter', '/ˈkʌtər/', 'B2', 'dụng cụ cắt; máy cắt', 'n.', 'cut (v.), cutting (n.)', NULL, 'Thường đi kèm với tên vật liệu hoặc công nghệ; wire cutters thường ở dạng số nhiều.', 'Use this pastry cutter to make round biscuits.', NULL, 'Hãy dùng chiếc khuôn cắt bánh này để làm những chiếc bánh quy hình tròn.', '{"wordId":"cutter","ukIpa":"/ˈkʌtə/","usIpa":"/ˈkʌtər/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"A tool or machine used to cut materials.","vi":"dụng cụ cắt; máy cắt"}],"examples":[{"en":"Use this pastry cutter to make round biscuits.","vi":"Hãy dùng chiếc khuôn cắt bánh này để làm những chiếc bánh quy hình tròn.","audioKind":"ex"},{"en":"A modern laser cutter can reduce material waste and improve precision in furniture production.","vi":"Một máy cắt laser hiện đại có thể giảm thiểu lãng phí vật liệu và nâng cao độ chính xác trong sản xuất đồ gỗ.","audioKind":"ex2"}],"collocations":[{"en":"laser cutter","vi":"máy cắt laser"},{"en":"pastry cutter","vi":"khuôn cắt bánh"},{"en":"wire cutters","vi":"kìm cắt dây"}],"wordFamily":["cut (v.)","cutting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường đi kèm với tên vật liệu hoặc công nghệ; wire cutters thường ở dạng số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_motor', 'en-b2-64', 'motor', '/ˈmoʊtər/', 'B2', 'động cơ; mô-tơ; thuộc động cơ xe cộ; thuộc cơ bắp, vận động cơ thể hoặc dây thần kinh điều khiển chúng', 'n.', 'motorist (n.), motorised (adj.), motoring (n.)', NULL, 'motor skills chỉ các kỹ năng vận động thể chất, không liên quan đến ô tô.', 'The fan stopped because its motor had become too hot.', NULL, 'Chiếc quạt ngừng chạy vì động cơ của nó bị quá nóng.', '{"wordId":"motor","ukIpa":"/ˈməʊtə/","usIpa":"/ˈmoʊtər/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"A machine that supplies power to move or operate something.","vi":"động cơ; mô-tơ"},{"pos":"adj.","en":"Relating to vehicles powered by engines or motors.","vi":"thuộc động cơ xe cộ"},{"pos":"adj.","en":"Relating to muscles, movement, or the nerves controlling them.","vi":"thuộc cơ bắp, vận động cơ thể hoặc dây thần kinh điều khiển chúng"}],"examples":[{"en":"The fan stopped because its motor had become too hot.","vi":"Chiếc quạt ngừng chạy vì động cơ của nó bị quá nóng.","audioKind":"ex"},{"en":"Activities such as drawing and building with blocks help young children develop fine motor skills.","vi":"Các hoạt động như vẽ tranh và xếp hình giúp trẻ nhỏ phát triển các kỹ năng vận động tinh.","audioKind":"ex2"}],"collocations":[{"en":"an electric motor","vi":"động cơ điện"},{"en":"motor vehicles","vi":"xe cơ giới"},{"en":"the motor industry","vi":"ngành công nghiệp ô tô"},{"en":"fine motor skills","vi":"kỹ năng vận động tinh"}],"wordFamily":["motorist (n.)","motorised (adj.)","motoring (n.)"],"synonyms":[],"antonyms":[],"tipVi":"motor skills chỉ các kỹ năng vận động thể chất, không liên quan đến ô tô.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_component', 'en-b2-64', 'component', '/kəmˈpoʊnənt/', 'B2', 'thành phần; linh kiện; bộ phận cấu thành; thuộc cấu thành; hợp thành', 'n.', NULL, 'Đồng nghĩa: part, element', 'Cấu trúc a component of dùng để chỉ thành phần cấu thành nên cái gì.', 'The technician replaced a broken component inside my laptop.', NULL, 'Kỹ thuật viên đã thay thế một linh kiện bị hỏng bên trong máy tính xách tay của tôi.', '{"wordId":"component","ukIpa":"/kəmˈpəʊnənt/","usIpa":"/kəmˈpoʊnənt/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"One of the parts that together form a whole.","vi":"thành phần; linh kiện; bộ phận cấu thành"},{"pos":"adj.","en":"Forming part of a larger whole.","vi":"thuộc cấu thành; hợp thành"}],"examples":[{"en":"The technician replaced a broken component inside my laptop.","vi":"Kỹ thuật viên đã thay thế một linh kiện bị hỏng bên trong máy tính xách tay của tôi.","audioKind":"ex"},{"en":"Reliable public transport is a key component of urban planning that aims to reduce traffic congestion.","vi":"Hệ thống giao thông công cộng đáng tin cậy là một thành phần cốt lõi trong quy hoạch đô thị nhằm mục đích giảm thiểu ùn tắc giao thông.","audioKind":"ex2"}],"collocations":[{"en":"a key component","vi":"một thành phần quan trọng"},{"en":"electronic components","vi":"linh kiện điện tử"},{"en":"component parts","vi":"các bộ phận cấu thành"}],"wordFamily":[],"synonyms":["part","element"],"antonyms":[],"tipVi":"Cấu trúc a component of dùng để chỉ thành phần cấu thành nên cái gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_satellite', 'en-b2-64', 'satellite', '/ˈsætəlaɪt/', 'B2', 'vệ tinh nhân tạo (thiết bị bay quanh Trái Đất hoặc hành tinh khác để thu thập hoặc truyền tải thông tin); vệ tinh tự nhiên (thi thể tự nhiên chuyển động quanh một hành tinh)', 'n.', NULL, NULL, 'Có thể chỉ vệ tinh nhân tạo hoặc tự nhiên; Mặt Trăng là vệ tinh tự nhiên của Trái Đất.', 'The satellite sent back clear pictures of the storm.', NULL, 'Vệ tinh đã truyền về những bức ảnh rõ nét về trận bão.', '{"wordId":"satellite","ukIpa":"/ˈsætəlaɪt/","usIpa":"/ˈsætəlaɪt/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"A device orbiting Earth or another body, collecting or transmitting information.","vi":"vệ tinh nhân tạo (thiết bị bay quanh Trái Đất hoặc hành tinh khác để thu thập hoặc truyền tải thông tin)"},{"pos":"n.","en":"A natural object that moves around a planet.","vi":"vệ tinh tự nhiên (thi thể tự nhiên chuyển động quanh một hành tinh)"}],"examples":[{"en":"The satellite sent back clear pictures of the storm.","vi":"Vệ tinh đã truyền về những bức ảnh rõ nét về trận bão.","audioKind":"ex"},{"en":"Satellite observations allow scientists to monitor changes in forest cover across remote regions over time.","vi":"Các quan sát từ vệ tinh cho phép các nhà khoa học theo dõi lâu dài những thay đổi về độ che phủ rừng ở các vùng sâu vùng xa.","audioKind":"ex2"}],"collocations":[{"en":"launch a satellite","vi":"phóng vệ tinh"},{"en":"communications satellite","vi":"vệ tinh viễn thông"},{"en":"satellite imagery","vi":"ảnh vệ tinh"},{"en":"natural satellite","vi":"vệ tinh tự nhiên"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Có thể chỉ vệ tinh nhân tạo hoặc tự nhiên; Mặt Trăng là vệ tinh tự nhiên của Trái Đất.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_storage', 'en-b2-64', 'storage', '/ˈstɔːrɪdʒ/', 'B2', 'sự cất giữ; sự bảo quản; bộ nhớ; không gian lưu trữ dữ liệu', 'n.', 'store (v.), storable (adj.)', NULL, 'storage thường là danh từ không đếm được; một phòng kho dùng từ a storeroom.', 'These boxes provide useful storage for all my winter clothes.', NULL, 'Những chiếc hộp này cung cấp không gian cất giữ tiện lợi cho tất cả quần áo mùa đông của tôi.', '{"wordId":"storage","ukIpa":"/ˈstɔːrɪdʒ/","usIpa":"/ˈstɔːrɪdʒ/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"The act of keeping things somewhere until they are needed.","vi":"sự cất giữ; sự bảo quản"},{"pos":"n.","en":"The capacity or process of keeping digital information for future use.","vi":"bộ nhớ; không gian lưu trữ dữ liệu"}],"examples":[{"en":"These boxes provide useful storage for all my winter clothes.","vi":"Những chiếc hộp này cung cấp không gian cất giữ tiện lợi cho tất cả quần áo mùa đông của tôi.","audioKind":"ex"},{"en":"Improved energy storage could make renewable electricity more reliable when sunlight and wind are unavailable.","vi":"Công nghệ lưu trữ năng lượng được cải thiện có thể giúp nguồn điện tái tạo trở nên đáng tin cậy hơn khi không có ánh nắng mặt trời và gió.","audioKind":"ex2"}],"collocations":[{"en":"storage space","vi":"không gian lưu trữ"},{"en":"energy storage","vi":"lưu trữ năng lượng"},{"en":"cloud storage","vi":"lưu trữ điện toán đám mây"},{"en":"in storage","vi":"đang được lưu trữ"}],"wordFamily":["store (v.)","storable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"storage thường là danh từ không đếm được; một phòng kho dùng từ a storeroom.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_generator', 'en-b2-64', 'generator', '/ˈdʒenəreɪtər/', 'B2', 'máy phát điện; thiết bị tạo ra; chương trình tạo sinh', 'n.', 'generate (v.), generation (n.)', NULL, 'Được cấu thành từ động từ generate và hậu tố -or, chỉ cả máy móc lẫn chương trình máy tính.', 'The generator kept our lights on during the storm.', NULL, 'Máy phát điện đã giúp nhà chúng tôi có điện sáng suốt trận bão.', '{"wordId":"generator","ukIpa":"/ˈdʒenəreɪtə/","usIpa":"/ˈdʒenəreɪtər/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"A machine that converts other forms of energy into electricity.","vi":"máy phát điện"},{"pos":"n.","en":"A device or program that produces something.","vi":"thiết bị tạo ra; chương trình tạo sinh"}],"examples":[{"en":"The generator kept our lights on during the storm.","vi":"Máy phát điện đã giúp nhà chúng tôi có điện sáng suốt trận bão.","audioKind":"ex"},{"en":"Remote communities often depend on diesel generators, although renewable energy systems can reduce their fuel costs.","vi":"Các cộng đồng vùng sâu vùng xa thường phụ thuộc vào máy phát điện chạy dầu diesel, mặc dù các hệ thống năng lượng tái tạo có thể giúp giảm chi phí nhiên liệu của họ.","audioKind":"ex2"}],"collocations":[{"en":"a backup generator","vi":"máy phát điện dự phòng"},{"en":"a diesel generator","vi":"máy phát điện diesel"},{"en":"a random number generator","vi":"trình tạo số ngẫu nhiên"}],"wordFamily":["generate (v.)","generation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Được cấu thành từ động từ generate và hậu tố -or, chỉ cả máy móc lẫn chương trình máy tính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_filter', 'en-b2-64', 'filter', '/ˈfɪltər/', 'B2', 'bộ lọc; thiết bị lọc; lọc; chọn lọc; lọt qua; lan tỏa từ từ', 'n.', 'filtration (n.), filtered (adj.), unfiltered (adj.)', NULL, 'Cụm filter out dùng để chỉ những thứ bị loại bỏ, chứ không phải thứ được giữ lại.', 'The water filter needs replacing before we leave.', NULL, 'Bộ lọc nước cần được thay thế trước khi chúng ta rời đi.', '{"wordId":"filter","ukIpa":"/ˈfɪltə/","usIpa":"/ˈfɪltər/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"a device that removes unwanted substances from liquid or air","vi":"bộ lọc; thiết bị lọc"},{"pos":"v.","en":"to remove unwanted substances or select information using particular conditions","vi":"lọc; chọn lọc"},{"pos":"v.","en":"to pass through or spread gradually","vi":"lọt qua; lan tỏa từ từ"}],"examples":[{"en":"The water filter needs replacing before we leave.","vi":"Bộ lọc nước cần được thay thế trước khi chúng ta rời đi.","audioKind":"ex"},{"en":"Modern treatment plants filter wastewater to remove harmful substances before releasing it into local rivers.","vi":"Các nhà máy xử lý nước hiện đại sẽ lọc nước thải để loại bỏ các chất có hại trước khi xả ra các con sông trong vùng.","audioKind":"ex2"}],"collocations":[{"en":"air filter","vi":"bộ lọc không khí"},{"en":"filter out impurities","vi":"lọc bỏ tạp chất"},{"en":"filter search results","vi":"lọc kết quả tìm kiếm"},{"en":"light filters through","vi":"ánh sáng lọt qua"}],"wordFamily":["filtration (n.)","filtered (adj.)","unfiltered (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm filter out dùng để chỉ những thứ bị loại bỏ, chứ không phải thứ được giữ lại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_interface', 'en-b2-64', 'interface', '/ˈɪntərfeɪs/', 'B2', 'giao diện; cổng kết nối; mặt phân cách; điểm tiếp giáp; kết nối; tương tác', 'n.', NULL, NULL, 'Trong lĩnh vực máy tính, từ này thường chỉ giao diện; khi làm động từ thường đi với giới từ with.', 'The app''s simple interface makes booking tickets much easier.', NULL, 'Giao diện đơn giản của ứng dụng giúp việc đặt vé trở nên dễ dàng hơn rất nhiều.', '{"wordId":"interface","ukIpa":"/ˈɪntəfeɪs/","usIpa":"/ˈɪntərfeɪs/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"a system through which users or devices interact","vi":"giao diện; cổng kết nối"},{"pos":"n.","en":"a boundary or connection between two things","vi":"mặt phân cách; điểm tiếp giáp"},{"pos":"v.","en":"connect and work together with another system or group","vi":"kết nối; tương tác"}],"examples":[{"en":"The app''s simple interface makes booking tickets much easier.","vi":"Giao diện đơn giản của ứng dụng giúp việc đặt vé trở nên dễ dàng hơn rất nhiều.","audioKind":"ex"},{"en":"An accessible user interface enables people with limited technical experience to benefit from digital public services.","vi":"Giao diện người dùng dễ tiếp cận giúp những người ít kinh nghiệm công nghệ cũng có thể hưởng lợi từ các dịch vụ công kỹ thuật số.","audioKind":"ex2"}],"collocations":[{"en":"user interface","vi":"giao diện người dùng"},{"en":"graphical interface","vi":"giao diện đồ họa"},{"en":"interface design","vi":"thiết kế giao diện"},{"en":"interface with","vi":"giao tiếp với; kết nối với"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong lĩnh vực máy tính, từ này thường chỉ giao diện; khi làm động từ thường đi với giới từ with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hardware', 'en-b2-64', 'hardware', '/ˈhɑːrdwer/', 'B2', 'phần cứng máy tính; đồ kim khí; ngũ kim; dụng cụ phần cứng', 'n.', NULL, NULL, 'Là danh từ không đếm được; hardware chỉ phần cứng, software chỉ phần mềm.', 'The technician replaced some old hardware inside my computer.', NULL, 'Kỹ thuật viên đã thay thế một số phần cứng cũ bên trong máy tính của tôi.', '{"wordId":"hardware","ukIpa":"/ˈhɑːdweə/","usIpa":"/ˈhɑːrdwer/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"the physical parts of a computer or electronic system","vi":"phần cứng máy tính"},{"pos":"n.","en":"tools and metal goods used for building and household repairs","vi":"đồ kim khí; ngũ kim; dụng cụ phần cứng"}],"examples":[{"en":"The technician replaced some old hardware inside my computer.","vi":"Kỹ thuật viên đã thay thế một số phần cứng cũ bên trong máy tính của tôi.","audioKind":"ex"},{"en":"Schools need reliable hardware and regular technical support to make digital learning accessible to all students.","vi":"Các trường học cần phần cứng đáng tin cậy và sự hỗ trợ kỹ thuật thường xuyên để giúp mọi học sinh tiếp cận học tập kỹ thuật số.","audioKind":"ex2"}],"collocations":[{"en":"computer hardware","vi":"phần cứng máy tính"},{"en":"hardware store","vi":"cửa hàng bán đồ ngũ kim"},{"en":"hardware upgrade","vi":"nâng cấp phần cứng"},{"en":"hardware failure","vi":"lỗi phần cứng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ không đếm được; hardware chỉ phần cứng, software chỉ phần mềm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_assemble', 'en-b2-64', 'assemble', '/əˈsembl/', 'B2', 'lắp ráp; tập hợp; tụ tập; triệu tập', 'v.', 'assembly (n.), assembler (n.), disassemble (v.)', 'Trái nghĩa: disassemble, disperse', 'Khi lắp ráp đồ vật thì là ngoại động từ; khi chỉ người tụ họp thì có thể dùng như nội động từ.', 'We assembled the bookshelf before putting our books away.', NULL, 'Chúng tôi đã lắp ráp xong chiếc giá sách trước khi cất sách đi.', '{"wordId":"assemble","ukIpa":"/əˈsembl/","usIpa":"/əˈsembl/","cefr":"B2","topic":"technology","senses":[{"pos":"v.","en":"to join separate parts together to make something","vi":"lắp ráp; tập hợp"},{"pos":"v.","en":"to gather together or bring people or things together","vi":"tụ tập; triệu tập"}],"examples":[{"en":"We assembled the bookshelf before putting our books away.","vi":"Chúng tôi đã lắp ráp xong chiếc giá sách trước khi cất sách đi.","audioKind":"ex"},{"en":"Manufacturers increasingly use robots to assemble electronic devices, improving consistency while reducing demand for some manual jobs.","vi":"Các nhà sản xuất ngày càng sử dụng nhiều robot để lắp ráp các thiết bị điện tử, giúp nâng cao tính đồng bộ đồng thời giảm bớt nhu cầu về một số công việc thủ công.","audioKind":"ex2"}],"collocations":[{"en":"assemble furniture","vi":"lắp ráp đồ nội thất"},{"en":"assemble a team","vi":"lập đội ngũ"},{"en":"assemble evidence","vi":"thu thập chứng cứ"},{"en":"assemble in the hall","vi":"tập trung tại sảnh"}],"wordFamily":["assembly (n.)","assembler (n.)","disassemble (v.)"],"synonyms":[],"antonyms":["disassemble","disperse"],"tipVi":"Khi lắp ráp đồ vật thì là ngoại động từ; khi chỉ người tụ họp thì có thể dùng như nội động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_64_1', 'en-b2-64', 'Cách dùng “accelerate” (v.) — tăng tốc; làm nhanh hơn', 'accelerate growth  ·  accelerate the process  ·  accelerate rapidly', 'Có thể dùng để chỉ phương tiện tăng tốc hoặc tiến trình được đẩy nhanh; có thể là ngoại động từ hoặc nội động từ.', 'Họ từ (Word Family): acceleration (n.), accelerator (n.) | Đồng nghĩa: speed up, hasten · Trái nghĩa: decelerate, slow down', '[{"hanzi":"The bus accelerated as it left the village.","pinyin":"","meaning":"Chiếc xe buýt tăng tốc khi rời khỏi ngôi làng."},{"hanzi":"Investment in public transport can accelerate the transition towards cleaner and more efficient urban travel.","pinyin":"","meaning":"Việc đầu tư vào giao thông công cộng có thể thúc đẩy quá trình chuyển đổi sang hình thức di chuyển đô thị sạch hơn và hiệu quả hơn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_64_2', 'en-b2-64', 'Cách dùng “videotape” (n.) — băng hình; băng video', 'an old videotape  ·  on videotape  ·  videotape a performance', 'Chỉ băng ghi hình dạng từ tính cũ; các thiết bị ghi hình số hiện đại thường dùng video hoặc record.', 'Họ từ (Word Family): video (n.)', '[{"hanzi":"We found an old videotape of our family picnic.","pinyin":"","meaning":"Chúng tôi tìm thấy một cuộn băng video cũ ghi lại cảnh gia đình đi dã ngoại."},{"hanzi":"Libraries can preserve recordings stored on videotape by converting them into digital formats for future generations.","pinyin":"","meaning":"Các thư viện có thể bảo quản các bản ghi trên băng video bằng cách chuyển đổi chúng sang định dạng kỹ thuật số cho các thế hệ mai sau."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_64_3', 'en-b2-64', 'Cách dùng “interface” (n.) — giao diện; cổng kết nối', 'user interface  ·  graphical interface  ·  interface design', 'Trong lĩnh vực máy tính, từ này thường chỉ giao diện; khi làm động từ thường đi với giới từ with.', NULL, '[{"hanzi":"The app''s simple interface makes booking tickets much easier.","pinyin":"","meaning":"Giao diện đơn giản của ứng dụng giúp việc đặt vé trở nên dễ dàng hơn rất nhiều."},{"hanzi":"An accessible user interface enables people with limited technical experience to benefit from digital public services.","pinyin":"","meaning":"Giao diện người dùng dễ tiếp cận giúp những người ít kinh nghiệm công nghệ cũng có thể hưởng lợi từ các dịch vụ công kỹ thuật số."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_64_4', 'en-b2-64', 'Cách dùng “assemble” (v.) — lắp ráp; tập hợp', 'assemble furniture  ·  assemble a team  ·  assemble evidence', 'Khi lắp ráp đồ vật thì là ngoại động từ; khi chỉ người tụ họp thì có thể dùng như nội động từ.', 'Họ từ (Word Family): assembly (n.), assembler (n.), disassemble (v.) | Trái nghĩa: disassemble, disperse', '[{"hanzi":"We assembled the bookshelf before putting our books away.","pinyin":"","meaning":"Chúng tôi đã lắp ráp xong chiếc giá sách trước khi cất sách đi."},{"hanzi":"Manufacturers increasingly use robots to assemble electronic devices, improving consistency while reducing demand for some manual jobs.","pinyin":"","meaning":"Các nhà sản xuất ngày càng sử dụng nhiều robot để lắp ráp các thiết bị điện tử, giúp nâng cao tính đồng bộ đồng thời giảm bớt nhu cầu về một số công việc thủ công."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_64_1', 'en-b2-64', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_64_1_1', 'ten_b2_64_1', 'modification', 'This small modification makes the chair much more comfortable.', 'This small modification makes the chair much more comfortable.', '/ˌmɑːdəfəˈkeɪʃən/', 'Sự điều chỉnh nhỏ này giúp chiếc ghế thoải mái hơn rất nhiều.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_64_1_2', 'ten_b2_64_1', 'activated', 'The moving cat activated the light above our door.', 'The moving cat activated the light above our door.', '/ˈæktɪveɪtɪd/', 'Con mèo di chuyển đã kích hoạt chiếc đèn phía trên cửa nhà chúng tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_64_1_3', 'ten_b2_64_1', 'videotape', 'We found an old videotape of our family picnic.', 'We found an old videotape of our family picnic.', '/ˈvɪdioʊteɪp/', 'Chúng tôi tìm thấy một cuộn băng video cũ ghi lại cảnh gia đình đi dã ngoại.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
