INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_64_1_7', 'ten_b2_64_1', 'defect', 'A small defect in the kettle caused it to leak.', 'A small defect in the kettle caused it to leak.', '/ˈdiːfekt/', 'Một lỗi nhỏ ở chiếc ấm đã làm nó bị rò rỉ nước.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_64_1_8', 'ten_b2_64_1', 'electronics', 'My sister studies electronics and repairs radios at home.', 'My sister studies electronics and repairs radios at home.', '/ɪˌlekˈtrɑːnɪks/', 'Em gái tôi học ngành điện tử và tự sửa đài ở nhà.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_64_1_1', 'en-b2-64', 'ten_b2_64_1', 'listening', 'listening', 'This small modification makes the chair much more comfortable.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những cảm biến nhỏ này truyền các chỉ số nhiệt độ về điện thoại của tôi.","Vệ tinh đã truyền về những bức ảnh rõ nét về trận bão.","Em gái tôi học ngành điện tử và tự sửa đài ở nhà.","Sự điều chỉnh nhỏ này giúp chiếc ghế thoải mái hơn rất nhiều."]'::jsonb, 3, 'This small modification makes the chair much more comfortable. → Sự điều chỉnh nhỏ này giúp chiếc ghế thoải mái hơn rất nhiều.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_64_1_2', 'en-b2-64', 'ten_b2_64_1', 'listening', 'listening', 'The moving cat activated the light above our door.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Giao diện đơn giản của ứng dụng giúp việc đặt vé trở nên dễ dàng hơn rất nhiều.","Những cảm biến nhỏ này truyền các chỉ số nhiệt độ về điện thoại của tôi.","Con mèo di chuyển đã kích hoạt chiếc đèn phía trên cửa nhà chúng tôi.","Những chiếc hộp này cung cấp không gian cất giữ tiện lợi cho tất cả quần áo mùa đông của tôi."]'::jsonb, 2, 'The moving cat activated the light above our door. → Con mèo di chuyển đã kích hoạt chiếc đèn phía trên cửa nhà chúng tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_64_1_3', 'en-b2-64', 'ten_b2_64_1', 'listening', 'listening', 'We found an old videotape of our family picnic.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Kỹ thuật viên đã thay thế một linh kiện bị hỏng bên trong máy tính xách tay của tôi.","Chúng tôi đã cải tạo phòng ngủ trống thành một văn phòng nhỏ.","Chiếc xe buýt tăng tốc khi rời khỏi ngôi làng.","Chúng tôi tìm thấy một cuộn băng video cũ ghi lại cảnh gia đình đi dã ngoại."]'::jsonb, 3, 'We found an old videotape of our family picnic. → Chúng tôi tìm thấy một cuộn băng video cũ ghi lại cảnh gia đình đi dã ngoại.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_64_2', 'en-b2-64', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_64_2_1', 'ten_b2_64_2', 'modification', 'Modification of existing buildings can reduce energy consumption without the environmental costs of new construction.', 'Modification of existing buildings can reduce energy consumption without the environmental costs of new construction.', '/ˌmɑːdəfəˈkeɪʃən/', 'Việc cải tạo các tòa nhà hiện có có thể làm giảm mức tiêu thụ năng lượng mà không tốn kém chi phí môi trường như việc xây mới.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_64_2_2', 'ten_b2_64_2', 'activated', 'The emergency warning system was activated immediately after sensors detected unusual movement beneath the ocean.', 'The emergency warning system was activated immediately after sensors detected unusual movement beneath the ocean.', '/ˈæktɪveɪtɪd/', 'Hệ thống cảnh báo khẩn cấp được kích hoạt ngay lập tức sau khi các cảm biến phát hiện chuyển động bất thường dưới đáy biển.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_64_2_3', 'ten_b2_64_2', 'videotape', 'Libraries can preserve recordings stored on videotape by converting them into digital formats for future generations.', 'Libraries can preserve recordings stored on videotape by converting them into digital formats for future generations.', '/ˈvɪdioʊteɪp/', 'Các thư viện có thể bảo quản các bản ghi trên băng video bằng cách chuyển đổi chúng sang định dạng kỹ thuật số cho các thế hệ mai sau.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_64_2_4', 'ten_b2_64_2', 'accelerate', 'Investment in public transport can accelerate the transition towards cleaner and more efficient urban travel.', 'Investment in public transport can accelerate the transition towards cleaner and more efficient urban travel.', '/əkˈseləreɪt/', 'Việc đầu tư vào giao thông công cộng có thể thúc đẩy quá trình chuyển đổi sang hình thức di chuyển đô thị sạch hơn và hiệu quả hơn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_64_2_5', 'ten_b2_64_2', 'input', 'Community input can help planners design public spaces that better reflect local needs.', 'Community input can help planners design public spaces that better reflect local needs.', '/ˈɪnpʊt/', 'Ý kiến đóng góp từ cộng đồng có thể giúp các nhà quy hoạch thiết kế các không gian công cộng phản ánh tốt hơn nhu cầu của địa phương.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_64_2_6', 'ten_b2_64_2', 'simplicity', 'The simplicity of a digital service can determine whether older users feel confident accessing essential information independently.', 'The simplicity of a digital service can determine whether older users feel confident accessing essential information independently.', '/sɪmˈplɪsəti/', 'Tính tiện dụng của một dịch vụ số có thể quyết định việc người dùng lớn tuổi có tự tin tiếp cận thông tin thiết yếu hay không.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_64_2_1', 'en-b2-64', 'ten_b2_64_2', 'listening', 'listening', 'Modification of existing buildings can reduce energy consumption without the environmental costs of new construction.', NULL, 'Trong câu vừa nghe, từ “modification” mang nghĩa nào sau đây?', '["phóng viên thường trú; phóng viên chuyên đề","thuộc về công ty; thuộc về doanh nghiệp","sự sửa đổi, sự cải tiến, sự điều chỉnh","đồng (kim loại màu nâu đỏ)"]'::jsonb, 2, '“modification” (/ˌmɑːdəfəˈkeɪʃən/): sự sửa đổi, sự cải tiến, sự điều chỉnh. Câu đầy đủ: Modification of existing buildings can reduce energy consumption without the environmental costs of new construction.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_64_2_2', 'en-b2-64', 'ten_b2_64_2', 'listening', 'listening', 'The emergency warning system was activated immediately after sensors detected unusual movement beneath the ocean.', NULL, 'Trong câu vừa nghe, từ “activated” mang nghĩa nào sau đây?', '["hướng xuống; đi xuống","gập ghềnh; không bằng phẳng; nhấp nhô","sự phân biệt đối xử","được kích hoạt; được khởi động"]'::jsonb, 3, '“activated” (/ˈæktɪveɪtɪd/): được kích hoạt; được khởi động. Câu đầy đủ: The emergency warning system was activated immediately after sensors detected unusual movement beneath the ocean.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
