INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_64_2', 'en-b2-64', NULL, 'comprehensive_test', 'listening', 'The moving cat activated the light above our door.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi thích sự đơn giản của công thức nấu món súp rau củ dễ làm này.","Con mèo di chuyển đã kích hoạt chiếc đèn phía trên cửa nhà chúng tôi.","Những cảm biến nhỏ này truyền các chỉ số nhiệt độ về điện thoại của tôi.","Những chiếc hộp này cung cấp không gian cất giữ tiện lợi cho tất cả quần áo mùa đông của tôi."]'::jsonb, 1, 'The moving cat activated the light above our door. → Con mèo di chuyển đã kích hoạt chiếc đèn phía trên cửa nhà chúng tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_64_3', 'en-b2-64', NULL, 'comprehensive_test', 'listening', 'videotape', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["băng hình; băng video","xây dựng lại; tái thiết","quỹ đạo","kém hơn; thấp kém"]'::jsonb, 0, 'videotape (/ˈvɪdioʊteɪp/) → băng hình; băng video; ghi hình vào băng video', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_64_4', 'en-b2-64', NULL, 'comprehensive_test', 'listening', 'The bus accelerated as it left the village.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những chiếc hộp này cung cấp không gian cất giữ tiện lợi cho tất cả quần áo mùa đông của tôi.","Chúng tôi tìm thấy một cuộn băng video cũ ghi lại cảnh gia đình đi dã ngoại.","Máy in đa chức năng của chúng tôi có thể quét tài liệu và sao chụp.","Chiếc xe buýt tăng tốc khi rời khỏi ngôi làng."]'::jsonb, 3, 'The bus accelerated as it left the village. → Chiếc xe buýt tăng tốc khi rời khỏi ngôi làng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
