INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_64_6', 'en-b2-64', NULL, 'comprehensive_test', 'listening', 'I love the simplicity of this easy vegetable soup recipe.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bộ lọc nước cần được thay thế trước khi chúng ta rời đi.","Chiếc xe buýt tăng tốc khi rời khỏi ngôi làng.","Tôi thích sự đơn giản của công thức nấu món súp rau củ dễ làm này.","Một lỗi nhỏ ở chiếc ấm đã làm nó bị rò rỉ nước."]'::jsonb, 2, 'I love the simplicity of this easy vegetable soup recipe. → Tôi thích sự đơn giản của công thức nấu món súp rau củ dễ làm này.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
