INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_64_18', 'en-b2-64', NULL, 'comprehensive_test', 'reading', NULL, 'Modification of existing buildings can reduce energy consumption without the environmental costs of new construction.', 'Dựa vào câu trên, từ “modification” có nghĩa phù hợp nhất là gì?', '["sự sửa đổi, sự cải tiến, sự điều chỉnh","sườn đồi; dốc đồi","làm mờ; trở nên mờ đi","galông (đơn vị đo thể tích)"]'::jsonb, 0, 'modification: sự sửa đổi, sự cải tiến, sự điều chỉnh. Dịch cả câu: Việc cải tạo các tòa nhà hiện có có thể làm giảm mức tiêu thụ năng lượng mà không tốn kém chi phí môi trường như việc xây mới.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_64_19', 'en-b2-64', NULL, 'comprehensive_test', 'reading', NULL, 'The emergency warning system was activated immediately after sensors detected unusual movement beneath the ocean.', 'Dựa vào câu trên, từ “activated” có nghĩa phù hợp nhất là gì?', '["được kích hoạt; được khởi động","nhìn trừng trừng; lườm","rộng rãi; bao quát; lớn","ẩm ướt; ẩm thấp"]'::jsonb, 0, 'activated: được kích hoạt; được khởi động; được hoạt hóa. Dịch cả câu: Hệ thống cảnh báo khẩn cấp được kích hoạt ngay lập tức sau khi các cảm biến phát hiện chuyển động bất thường dưới đáy biển.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_64_20', 'en-b2-64', NULL, 'comprehensive_test', 'reading', NULL, 'Libraries can preserve recordings stored on videotape by converting them into digital formats for future generations.', 'Dựa vào câu trên, từ “videotape” có nghĩa phù hợp nhất là gì?', '["mờ ảo; thiếu ánh sáng","băng hình; băng video","yêu mến; rất thích","giả định; điều phỏng đoán"]'::jsonb, 1, 'videotape: băng hình; băng video; ghi hình vào băng video. Dịch cả câu: Các thư viện có thể bảo quản các bản ghi trên băng video bằng cách chuyển đổi chúng sang định dạng kỹ thuật số cho các thế hệ mai sau.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_64_21', 'en-b2-64', NULL, 'comprehensive_test', 'reading', NULL, 'Investment in public transport can accelerate the transition towards cleaner and more efficient urban travel.', 'Dựa vào câu trên, từ “accelerate” có nghĩa phù hợp nhất là gì?', '["giả sử; giả định","ánh trăng","tăng tốc; làm nhanh hơn","vô gia cư"]'::jsonb, 2, 'accelerate: tăng tốc; làm nhanh hơn. Dịch cả câu: Việc đầu tư vào giao thông công cộng có thể thúc đẩy quá trình chuyển đổi sang hình thức di chuyển đô thị sạch hơn và hiệu quả hơn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_64_22', 'en-b2-64', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “giao diện; cổng kết nối”', '["interface","wander","urban","trace"]'::jsonb, 0, 'giao diện; cổng kết nối → interface (/ˈɪntərfeɪs/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_64_23', 'en-b2-64', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “phần cứng máy tính”', '["greedy","hardware","aerial","primitive"]'::jsonb, 1, 'phần cứng máy tính → hardware (/ˈhɑːrdwer/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_64_24', 'en-b2-64', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “lắp ráp; tập hợp”', '["calorie","carrier","commitment","assemble"]'::jsonb, 3, 'lắp ráp; tập hợp → assemble (/əˈsembl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-65', 'en', 'Bài 65: Công nghệ & Kỹ thuật (2) - CEFR B2', 'CEFR B2', 'B2 · Công nghệ', '22 từ vựng Tiếng Anh CEFR B2 chủ đề công nghệ & kỹ thuật kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4065, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aerial', 'en-b2-65', 'aerial', '/ˈeriəl/', 'B2', 'trên không; từ trên không; ăng-ten', 'adj.', 'aerially (adv.)', NULL, 'Từ "aerial" mang nghĩa "ăng-ten" chủ yếu được dùng trong tiếng Anh-Anh; trong khi tiếng Anh-Mỹ thường dùng "antenna".', 'The aerial photograph showed our house beside the river.', NULL, 'Bức ảnh chụp từ trên không cho thấy ngôi nhà của chúng tôi nằm cạnh dòng sông.', '{"wordId":"aerial","ukIpa":"/ˈeəriəl/","usIpa":"/ˈeriəl/","cefr":"B2","topic":"technology","senses":[{"pos":"adj.","en":"Happening in the air or done from above the ground.","vi":"trên không; từ trên không"},{"pos":"n.","en":"A device that receives or sends radio or television signals.","vi":"ăng-ten"}],"examples":[{"en":"The aerial photograph showed our house beside the river.","vi":"Bức ảnh chụp từ trên không cho thấy ngôi nhà của chúng tôi nằm cạnh dòng sông.","audioKind":"ex"},{"en":"Aerial surveys allow researchers to monitor forest loss across remote regions without disturbing wildlife.","vi":"Các cuộc khảo sát trên không cho phép các nhà nghiên cứu theo dõi tình trạng mất rừng ở các vùng hẻo lánh mà không làm xáo trộn động vật hoang dã.","audioKind":"ex2"}],"collocations":[{"en":"aerial photography","vi":"nhiếp ảnh hàng không"},{"en":"an aerial view","vi":"cảnh nhìn từ trên cao"},{"en":"an aerial survey","vi":"khảo sát hàng không"},{"en":"a television aerial","vi":"ăng-ten vô tuyến"}],"wordFamily":["aerially (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ \"aerial\" mang nghĩa \"ăng-ten\" chủ yếu được dùng trong tiếng Anh-Anh; trong khi tiếng Anh-Mỹ thường dùng \"antenna\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_database', 'en-b2-65', 'database', '/ˈdeɪtəbeɪs/', 'B2', 'cơ sở dữ liệu; hệ thống dữ liệu', 'n.', NULL, NULL, 'Là danh từ đếm được; khi nói về việc tìm kiếm trong hệ thống thường dùng cụm in a database.', 'The library database helped me find a gardening book.', NULL, 'Cơ sở dữ liệu của thư viện đã giúp tôi tìm thấy một cuốn sách làm vườn.', '{"wordId":"database","ukIpa":"/ˈdeɪtəbeɪs/","usIpa":"/ˈdeɪtəbeɪs/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"An organized collection of information stored and accessed electronically.","vi":"cơ sở dữ liệu; hệ thống dữ liệu"}],"examples":[{"en":"The library database helped me find a gardening book.","vi":"Cơ sở dữ liệu của thư viện đã giúp tôi tìm thấy một cuốn sách làm vườn.","audioKind":"ex"},{"en":"Hospitals need secure databases to protect patient records while allowing doctors to access essential information.","vi":"Các bệnh viện cần những cơ sở dữ liệu bảo mật để bảo vệ hồ sơ bệnh án đồng thời cho phép bác sĩ truy cập thông tin thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"search a database","vi":"tra cứu cơ sở dữ liệu"},{"en":"update a database","vi":"cập nhật cơ sở dữ liệu"},{"en":"customer database","vi":"cơ sở dữ liệu khách hàng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ đếm được; khi nói về việc tìm kiếm trong hệ thống thường dùng cụm in a database.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_processing', 'en-b2-65', 'processing', '/ˈprɑːsesɪŋ/', 'B2', 'chế biến; gia công; xử lý dữ liệu', 'n.', 'process (v.), process (n.), processor (n.), processed (adj.)', NULL, 'Thường là danh từ không đếm được; processing plant chỉ nhà máy chế biến.', 'These apples are ready for processing into juice.', NULL, 'Những quả táo này đã sẵn sàng để đem đi chế biến thành nước ép.', '{"wordId":"processing","ukIpa":"/ˈprəʊsesɪŋ/","usIpa":"/ˈprɑːsesɪŋ/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"preparing or changing materials through a series of operations","vi":"chế biến; gia công"},{"pos":"n.","en":"using a computer to organise, change, or analyse information","vi":"xử lý dữ liệu"}],"examples":[{"en":"These apples are ready for processing into juice.","vi":"Những quả táo này đã sẵn sàng để đem đi chế biến thành nước ép.","audioKind":"ex"},{"en":"Modern food processing can extend shelf life, although some methods reduce the nutritional value of fresh ingredients.","vi":"Quá trình chế biến thực phẩm hiện đại có thể kéo dài thời hạn bảo quản, mặc dù một số phương pháp làm giảm giá trị dinh dưỡng của nguyên liệu tươi.","audioKind":"ex2"}],"collocations":[{"en":"food processing","vi":"chế biến thực phẩm"},{"en":"data processing","vi":"xử lý dữ liệu"},{"en":"processing plant","vi":"nhà máy chế biến"},{"en":"processing time","vi":"thời gian xử lý"}],"wordFamily":["process (v.)","process (n.)","processor (n.)","processed (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; processing plant chỉ nhà máy chế biến.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_format', 'en-b2-65', 'format', '/ˈfɔːrmæt/', 'B2', 'định dạng; hình thức trình bày; trình bày văn bản; định dạng (thiết bị lưu trữ để chuẩn bị chứa dữ liệu)', 'n.', 'formatting (n.), reformat (v.)', NULL, 'Dạng quá khứ của động từ là formatted, phân từ hiện đại là formatting.', 'Please send the photos in a different file format.', NULL, 'Vui lòng gửi các bức ảnh bằng định dạng tệp khác.', '{"wordId":"format","ukIpa":"/ˈfɔːmæt/","usIpa":"/ˈfɔːrmæt/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"the way information or an event is arranged or presented","vi":"định dạng; hình thức trình bày"},{"pos":"v.","en":"to arrange the appearance of a document or information","vi":"định dạng; trình bày văn bản"},{"pos":"v.","en":"to prepare a storage device so it can store data","vi":"định dạng (thiết bị lưu trữ để chuẩn bị chứa dữ liệu)"}],"examples":[{"en":"Please send the photos in a different file format.","vi":"Vui lòng gửi các bức ảnh bằng định dạng tệp khác.","audioKind":"ex"},{"en":"Offering course materials in a digital format can make education more accessible to students in remote areas.","vi":"Việc cung cấp tài liệu khóa học dưới dạng kỹ thuật số có thể giúp học viên ở vùng sâu vùng xa tiếp cận giáo dục dễ dàng hơn.","audioKind":"ex2"}],"collocations":[{"en":"file format","vi":"định dạng tệp"},{"en":"digital format","vi":"định dạng kỹ thuật số"},{"en":"format a document","vi":"định dạng tài liệu"},{"en":"standard format","vi":"định dạng chuẩn"}],"wordFamily":["formatting (n.)","reformat (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ của động từ là formatted, phân từ hiện đại là formatting.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_upgrade', 'en-b2-65', 'upgrade', '/ʌpˈɡreɪd/', 'B2', 'nâng cấp; cải thiện; sự nâng cấp; bản cải tiến', 'v.', 'upgradable (adj.)', 'Đồng nghĩa: improve, enhance · Trái nghĩa: downgrade', 'Động từ trọng âm ở âm tiết sau, danh từ trọng âm ở âm tiết đầu.', 'We upgraded our old computer with a faster processor.', NULL, 'Chúng tôi đã nâng cấp chiếc máy tính cũ của mình bằng một bộ vi xử lý nhanh hơn.', '{"wordId":"upgrade","ukIpa":"/ʌpˈɡreɪd/","usIpa":"/ʌpˈɡreɪd/","cefr":"B2","topic":"technology","senses":[{"pos":"v.","en":"To improve something or replace it with a better version.","vi":"nâng cấp; cải thiện"},{"pos":"n.","en":"An improvement or a newer, better version of something.","vi":"sự nâng cấp; bản cải tiến"}],"examples":[{"en":"We upgraded our old computer with a faster processor.","vi":"Chúng tôi đã nâng cấp chiếc máy tính cũ của mình bằng một bộ vi xử lý nhanh hơn.","audioKind":"ex"},{"en":"Governments should upgrade ageing water systems to reduce waste and provide reliable supplies for growing urban populations.","vi":"Chính phủ nên nâng cấp hệ thống cấp nước đã xuống cấp để giảm thiểu lãng phí và cung cấp nguồn nước ổn định cho dân số đô thị đang ngày càng tăng.","audioKind":"ex2"}],"collocations":[{"en":"upgrade software","vi":"nâng cấp phần mềm"},{"en":"upgrade to","vi":"nâng cấp thành"},{"en":"a system upgrade","vi":"nâng cấp hệ thống"}],"wordFamily":["upgradable (adj.)"],"synonyms":["improve","enhance"],"antonyms":["downgrade"],"tipVi":"Động từ trọng âm ở âm tiết sau, danh từ trọng âm ở âm tiết đầu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_receiver', 'en-b2-65', 'receiver', '/rɪˈsiːvər/', 'B2', 'máy thu thanh/truyền hình; thiết bị thu tín hiệu; ống nghe điện thoại; người nhận; người tiếp nhận', 'n.', 'receive (v.), reception (n.), recipient (n.)', NULL, 'Từ này có thể chỉ thiết bị kỹ thuật hoặc con người; nếu chỉ người nhận thư/bưu phẩm thường dùng ''recipient''.', 'We adjusted the receiver until the music sounded clear.', NULL, 'Chúng tôi đã điều chỉnh máy thu thanh cho đến khi âm thanh phát ra rõ ràng.', '{"wordId":"receiver","ukIpa":"/rɪˈsiːvə/","usIpa":"/rɪˈsiːvər/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"A device that receives radio, television, or other electronic signals.","vi":"máy thu thanh/truyền hình; thiết bị thu tín hiệu"},{"pos":"n.","en":"The part of a telephone held to the ear and mouth.","vi":"ống nghe điện thoại"},{"pos":"n.","en":"A person who receives something.","vi":"người nhận; người tiếp nhận"}],"examples":[{"en":"We adjusted the receiver until the music sounded clear.","vi":"Chúng tôi đã điều chỉnh máy thu thanh cho đến khi âm thanh phát ra rõ ràng.","audioKind":"ex"},{"en":"A satellite receiver can provide remote communities with access to educational broadcasts and emergency information.","vi":"Một chiếc máy thu vệ tinh có thể giúp các cộng đồng vùng sâu vùng xa tiếp cận với các chương trình phát sóng giáo dục và thông tin khẩn cấp.","audioKind":"ex2"}],"collocations":[{"en":"satellite receiver","vi":"máy thu vệ tinh"},{"en":"radio receiver","vi":"máy thu thanh"},{"en":"pick up the receiver","vi":"nhấc ống nghe điện thoại lên"},{"en":"put down the receiver","vi":"đặt ống nghe điện thoại xuống"}],"wordFamily":["receive (v.)","reception (n.)","recipient (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ này có thể chỉ thiết bị kỹ thuật hoặc con người; nếu chỉ người nhận thư/bưu phẩm thường dùng ''recipient''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_computerize', 'en-b2-65', 'computerize', '/kəmˈpjuːtəraɪz/', 'B2', 'tin học hóa; tự động hóa bằng máy tính (sử dụng máy tính để quản lý một công việc, hệ thống hoặc thông tin)', 'v.', 'computer (n.), computerization (n.), computerized (adj.)', NULL, 'Trong tiếng Anh Anh, từ này còn được viết là "computerise"; thường đi kèm với "records" hoặc "system".', 'Our local library plans to computerize its borrowing records.', NULL, 'Thư viện địa phương của chúng tôi có kế hoạch tin học hóa các hồ sơ mượn sách.', '{"wordId":"computerize","ukIpa":"/kəmˈpjuːtəraɪz/","usIpa":"/kəmˈpjuːtəraɪz/","cefr":"B2","topic":"technology","senses":[{"pos":"v.","en":"To use computers to manage a task, system, or information","vi":"tin học hóa; tự động hóa bằng máy tính (sử dụng máy tính để quản lý một công việc, hệ thống hoặc thông tin)"}],"examples":[{"en":"Our local library plans to computerize its borrowing records.","vi":"Thư viện địa phương của chúng tôi có kế hoạch tin học hóa các hồ sơ mượn sách.","audioKind":"ex"},{"en":"Hospitals that computerize patient records can improve access to information, provided that adequate privacy safeguards are maintained.","vi":"Các bệnh viện tiến hành tin học hóa hồ sơ bệnh nhân có thể nâng cao khả năng tiếp cận thông tin, miễn là duy trì đầy đủ các biện pháp bảo mật quyền riêng tư.","audioKind":"ex2"}],"collocations":[{"en":"computerize records","vi":"tin học hóa hồ sơ"},{"en":"computerize a system","vi":"tin học hóa hệ thống"},{"en":"a computerized database","vi":"cơ sở dữ liệu máy tính"}],"wordFamily":["computer (n.)","computerization (n.)","computerized (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh Anh, từ này còn được viết là \"computerise\"; thường đi kèm với \"records\" hoặc \"system\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fuse', 'en-b2-65', 'fuse', '/fjuːz/', 'B2', 'cầu chì; thiết bị ngắt điện an toàn; nối liền; kết hợp; dung hợp; ngòi nổ; dây cháy chậm', 'n.', 'fusion (n.), fusible (adj.), fused (adj.)', NULL, 'Đóng vai trò động từ chỉ sự dung hợp; blow a fuse cũng có thể dùng theo nghĩa ẩn dụ là nổi giận đùng đùng.', 'The electrician replaced the fuse, and the lights came on.', NULL, 'Thợ điện đã thay cầu chì và đèn đã sáng trở lại.', '{"wordId":"fuse","ukIpa":"/fjuːz/","usIpa":"/fjuːz/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"A safety device that breaks a circuit when current is excessive.","vi":"cầu chì; thiết bị ngắt điện an toàn"},{"pos":"v.","en":"To join together into one whole, often through heat.","vi":"nối liền; kết hợp; dung hợp"},{"pos":"n.","en":"A cord or device that makes an explosive charge go off.","vi":"ngòi nổ; dây cháy chậm"}],"examples":[{"en":"The electrician replaced the fuse, and the lights came on.","vi":"Thợ điện đã thay cầu chì và đèn đã sáng trở lại.","audioKind":"ex"},{"en":"Modern design often fuses traditional craftsmanship with digital technology to create more sustainable consumer products.","vi":"Thiết kế hiện đại thường kết hợp giữa thủ công mỹ nghệ truyền thống và công nghệ số để tạo ra các sản phẩm tiêu dùng bền vững hơn.","audioKind":"ex2"}],"collocations":[{"en":"blow a fuse","vi":"cháy cầu chì; nổi giận đùng đùng"},{"en":"replace a fuse","vi":"thay cầu chì"},{"en":"fuse together","vi":"hợp nhất lại"},{"en":"light a fuse","vi":"châm ngòi nổ"}],"wordFamily":["fusion (n.)","fusible (adj.)","fused (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Đóng vai trò động từ chỉ sự dung hợp; blow a fuse cũng có thể dùng theo nghĩa ẩn dụ là nổi giận đùng đùng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reliability', 'en-b2-65', 'reliability', '/rɪˌlaɪəˈbɪləti/', 'B2', 'độ tin cậy; tính xác thực; sự đáng tin cậy', 'n.', 'reliable (adj.), reliably (adv.), unreliable (adj.), rely (v.)', 'Đồng nghĩa: dependability · Trái nghĩa: unreliability', 'reliability thường là danh từ không đếm được; tính từ tương ứng là reliable.', 'We chose this washing machine for its proven reliability.', NULL, 'Chúng tôi chọn chiếc máy giặt này vì độ tin cậy đã được kiểm chứng của nó.', '{"wordId":"reliability","ukIpa":"/rɪˌlaɪəˈbɪləti/","usIpa":"/rɪˌlaɪəˈbɪləti/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"The quality of working well or being worthy of trust.","vi":"độ tin cậy; tính xác thực; sự đáng tin cậy"}],"examples":[{"en":"We chose this washing machine for its proven reliability.","vi":"Chúng tôi chọn chiếc máy giặt này vì độ tin cậy đã được kiểm chứng của nó.","audioKind":"ex"},{"en":"Improving the reliability of public transport could encourage more commuters to leave their cars at home.","vi":"Việc nâng cao độ tin cậy của giao thông công cộng có thể khuyến khích nhiều người đi làm bỏ lại xe hơi ở nhà.","audioKind":"ex2"}],"collocations":[{"en":"improve reliability","vi":"nâng cao độ tin cậy"},{"en":"long-term reliability","vi":"độ tin cậy lâu dài"},{"en":"the reliability of data","vi":"độ tin cậy của dữ liệu"}],"wordFamily":["reliable (adj.)","reliably (adv.)","unreliable (adj.)","rely (v.)"],"synonyms":["dependability"],"antonyms":["unreliability"],"tipVi":"reliability thường là danh từ không đếm được; tính từ tương ứng là reliable.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_graphics', 'en-b2-65', 'graphics', '/ˈɡræfɪks/', 'B2', 'đồ họa; hình ảnh đồ họa', 'n.', 'graphic (adj.), graphical (adj.), graphically (adv.)', 'Đồng nghĩa: visuals', 'Khi chỉ nhiều hình ảnh đồ họa, dùng động từ số nhiều: the graphics are.', 'The game''s colourful graphics looked amazing on our new screen.', NULL, 'Đồ họa đầy màu sắc của trò chơi trông vô cùng tuyệt vời trên màn hình mới của chúng tôi.', '{"wordId":"graphics","ukIpa":"/ˈɡræfɪks/","usIpa":"/ˈɡræfɪks/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"Images or designs used on screens or in printed materials.","vi":"đồ họa; hình ảnh đồ họa"}],"examples":[{"en":"The game''s colourful graphics looked amazing on our new screen.","vi":"Đồ họa đầy màu sắc của trò chơi trông vô cùng tuyệt vời trên màn hình mới của chúng tôi.","audioKind":"ex"},{"en":"Clear graphics can make complex scientific information easier to understand for audiences without specialist knowledge.","vi":"Đồ họa trực quan rõ ràng có thể giúp khán giả không có chuyên môn dễ dàng hiểu được các thông tin khoa học phức tạp.","audioKind":"ex2"}],"collocations":[{"en":"computer graphics","vi":"đồ họa máy tính"},{"en":"high-quality graphics","vi":"đồ họa chất lượng cao"},{"en":"graphics card","vi":"card đồ họa; thẻ đồ họa"}],"wordFamily":["graphic (adj.)","graphical (adj.)","graphically (adv.)"],"synonyms":["visuals"],"antonyms":[],"tipVi":"Khi chỉ nhiều hình ảnh đồ họa, dùng động từ số nhiều: the graphics are.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_radar', 'en-b2-65', 'radar', '/ˈreɪdɑːr/', 'B2', 'ra-đa; hệ thống định vị bằng sóng vô tuyến', 'n.', NULL, NULL, 'Cụm từ under the radar mang nghĩa bóng là lẩn tránh sự chú ý hoặc chưa được chú ý đến.', 'The fishing boat has radar for navigating through fog.', NULL, 'Con tàu đánh cá được trang bị ra-đa để định hướng khi đi qua vùng sương mù.', '{"wordId":"radar","ukIpa":"/ˈreɪdɑː/","usIpa":"/ˈreɪdɑːr/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"A system using radio waves to locate and track objects.","vi":"ra-đa; hệ thống định vị bằng sóng vô tuyến"}],"examples":[{"en":"The fishing boat has radar for navigating through fog.","vi":"Con tàu đánh cá được trang bị ra-đa để định hướng khi đi qua vùng sương mù.","audioKind":"ex"},{"en":"Modern radar systems allow airports to monitor aircraft movements and maintain safety even in poor visibility.","vi":"Các hệ thống ra-đa hiện đại cho phép các sân bay theo dõi chuyển động của máy bay và duy trì an toàn ngay cả trong điều kiện tầm nhìn kém.","audioKind":"ex2"}],"collocations":[{"en":"radar system","vi":"hệ thống ra-đa"},{"en":"radar screen","vi":"màn hình ra-đa"},{"en":"weather radar","vi":"ra-đa thời tiết"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ under the radar mang nghĩa bóng là lẩn tránh sự chú ý hoặc chưa được chú ý đến.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_directory', 'en-b2-65', 'directory', '/dəˈrektəri/', 'B2', 'sách danh bạ; danh mục địa chỉ; thư mục lưu trữ tập tin trên máy tính', 'n.', NULL, NULL, 'Danh bạ thường chứa thông tin liên hệ; trong máy tính dùng để chỉ thư mục chứa file.', 'I found a nearby plumber in the local directory.', NULL, 'Tôi tìm thấy một thợ sửa ống nước gần nhà trong danh bạ địa phương.', '{"wordId":"directory","ukIpa":"/dəˈrektəri/","usIpa":"/dəˈrektəri/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"a list of people or organisations with their contact details","vi":"sách danh bạ; danh mục địa chỉ"},{"pos":"n.","en":"a location used to organise files on a computer","vi":"thư mục lưu trữ tập tin trên máy tính"}],"examples":[{"en":"I found a nearby plumber in the local directory.","vi":"Tôi tìm thấy một thợ sửa ống nước gần nhà trong danh bạ địa phương.","audioKind":"ex"},{"en":"An online directory of community services can help new residents locate essential support more easily.","vi":"Một danh mục dịch vụ cộng đồng trực tuyến có thể giúp cư dân mới tìm kiếm các hỗ trợ thiết yếu dễ dàng hơn.","audioKind":"ex2"}],"collocations":[{"en":"business directory","vi":"thư mục doanh nghiệp"},{"en":"telephone directory","vi":"sách danh bạ điện thoại"},{"en":"online directory","vi":"danh mục trực tuyến"},{"en":"root directory","vi":"thư mục gốc"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh bạ thường chứa thông tin liên hệ; trong máy tính dùng để chỉ thư mục chứa file.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pump', 'en-b2-65', 'pump', '/pʌmp/', 'B2', 'máy bơm; bơm nước; cái bơm; bơm; hút; truyền (chất lỏng hoặc khí bằng máy bơm)', 'n.', 'pumping (n.)', NULL, 'Cụm pump up a tyre dùng để chỉ hành động bơm lốp xe; trong khi pump water nghĩa là bơm nước.', 'I keep a bicycle pump beside the garage door.', NULL, 'Tôi để một cái bơm xe đạp ngay cạnh cửa nhà xe.', '{"wordId":"pump","ukIpa":"/pʌmp/","usIpa":"/pʌmp/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"a device that moves liquid or gas","vi":"máy bơm; bơm nước; cái bơm"},{"pos":"v.","en":"to move liquid or gas using a pump","vi":"bơm; hút; truyền (chất lỏng hoặc khí bằng máy bơm)"}],"examples":[{"en":"I keep a bicycle pump beside the garage door.","vi":"Tôi để một cái bơm xe đạp ngay cạnh cửa nhà xe.","audioKind":"ex"},{"en":"Solar power can operate a water pump, helping rural communities obtain clean water without relying on expensive fuel.","vi":"Năng lượng mặt trời có thể vận hành máy bơm nước, giúp các vùng nông thôn có được nước sạch mà không cần phụ thuộc vào nhiên liệu đắt đỏ.","audioKind":"ex2"}],"collocations":[{"en":"water pump","vi":"máy bơm nước"},{"en":"bicycle pump","vi":"bơm xe đạp"},{"en":"pump water","vi":"bơm nước"},{"en":"pump up a tyre","vi":"bơm lốp xe"}],"wordFamily":["pumping (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm pump up a tyre dùng để chỉ hành động bơm lốp xe; trong khi pump water nghĩa là bơm nước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_monitor', 'en-b2-65', 'monitor', '/ˈmɑːnɪtər/', 'B2', 'giám sát; theo dõi; màn hình; thiết bị theo dõi', 'v.', 'monitoring (n.)', NULL, 'Là động từ có thể trực tiếp đi với tân ngữ: monitor changes giám sát sự thay đổi.', 'The nurse monitored my temperature throughout the night.', NULL, 'Y tá đã theo dõi nhiệt độ của tôi suốt cả đêm.', '{"wordId":"monitor","ukIpa":"/ˈmɒnɪtə/","usIpa":"/ˈmɑːnɪtər/","cefr":"B2","topic":"technology","senses":[{"pos":"v.","en":"To regularly check something for changes, progress, or problems.","vi":"giám sát; theo dõi"},{"pos":"n.","en":"A screen displaying information, or a device checking conditions.","vi":"màn hình; thiết bị theo dõi"}],"examples":[{"en":"The nurse monitored my temperature throughout the night.","vi":"Y tá đã theo dõi nhiệt độ của tôi suốt cả đêm.","audioKind":"ex"},{"en":"Governments should monitor air quality regularly to assess whether environmental policies are effectively reducing pollution.","vi":"Chính phủ nên thường xuyên giám sát chất lượng không khí để đánh giá xem các chính sách môi trường có đang làm giảm ô nhiễm một cách hiệu quả hay không.","audioKind":"ex2"}],"collocations":[{"en":"monitor progress","vi":"theo dõi tiến độ"},{"en":"monitor air quality","vi":"giám sát chất lượng không khí"},{"en":"computer monitor","vi":"màn hình máy tính"},{"en":"heart monitor","vi":"máy theo dõi nhịp tim"}],"wordFamily":["monitoring (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Là động từ có thể trực tiếp đi với tân ngữ: monitor changes giám sát sự thay đổi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_modified', 'en-b2-65', 'modified', '/ˈmɑːdəfaɪd/', 'B2', 'được sửa đổi; được cải tiến; được điều chỉnh', 'adj.', 'modify (v.), modification (n.), modifiable (adj.)', 'Đồng nghĩa: adapted, altered, adjusted · Trái nghĩa: unmodified, unchanged', 'Nhấn mạnh sự thay đổi để thích ứng, không nhất thiết ngầm chỉ chất lượng đã được nâng cao.', 'She rides a modified bicycle with an extra seat.', NULL, 'Cô ấy lái một chiếc xe đạp đã được độ lại với một chiếc ghế phụ.', '{"wordId":"modified","ukIpa":"/ˈmɒdɪfaɪd/","usIpa":"/ˈmɑːdəfaɪd/","cefr":"B2","topic":"technology","senses":[{"pos":"adj.","en":"Changed partly to suit a purpose or improve how something works.","vi":"được sửa đổi; được cải tiến; được điều chỉnh"}],"examples":[{"en":"She rides a modified bicycle with an extra seat.","vi":"Cô ấy lái một chiếc xe đạp đã được độ lại với một chiếc ghế phụ.","audioKind":"ex"},{"en":"Modified teaching materials can help students with different learning needs participate more fully in mainstream classroom activities.","vi":"Tài liệu giảng dạy được điều chỉnh có thể giúp học sinh có nhu cầu học tập khác nhau tham gia trọn vẹn hơn vào các hoạt động trên lớp chính khóa.","audioKind":"ex2"}],"collocations":[{"en":"genetically modified crops","vi":"cây trồng biến đổi gen"},{"en":"modified version","vi":"phiên bản đã chỉnh sửa"},{"en":"modified equipment","vi":"thiết bị đã qua cải tiến"},{"en":"slightly modified","vi":"được chỉnh sửa đôi chút"}],"wordFamily":["modify (v.)","modification (n.)","modifiable (adj.)"],"synonyms":["adapted","altered","adjusted"],"antonyms":["unmodified","unchanged"],"tipVi":"Nhấn mạnh sự thay đổi để thích ứng, không nhất thiết ngầm chỉ chất lượng đã được nâng cao.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_faulty', 'en-b2-65', 'faulty', '/ˈfɔːlti/', 'B2', 'hỏng hóc; có lỗi kỹ thuật; sai lầm; có sơ hở', 'adj.', 'fault (n.), faultless (adj.)', 'Đồng nghĩa: defective, flawed · Trái nghĩa: flawless', 'Có thể dùng để chỉ thiết bị gặp trục trặc hoặc dùng để chỉ lý luận, suy luận có điểm sai sót.', 'The electrician replaced the faulty switch in our kitchen.', NULL, 'Thợ điện đã thay thế công tắc bị hỏng trong nhà bếp của chúng tôi.', '{"wordId":"faulty","ukIpa":"/ˈfɔːlti/","usIpa":"/ˈfɔːlti/","cefr":"B2","topic":"technology","senses":[{"pos":"adj.","en":"not working correctly because something is wrong","vi":"hỏng hóc; có lỗi kỹ thuật"},{"pos":"adj.","en":"containing mistakes or based on incorrect reasoning","vi":"sai lầm; có sơ hở"}],"examples":[{"en":"The electrician replaced the faulty switch in our kitchen.","vi":"Thợ điện đã thay thế công tắc bị hỏng trong nhà bếp của chúng tôi.","audioKind":"ex"},{"en":"Policies based on faulty assumptions may fail to address the underlying causes of urban poverty.","vi":"Các chính sách dựa trên những giả định sai lầm có thể không giải quyết được các nguyên nhân sâu xa của tình trạng nghèo đói đô thị.","audioKind":"ex2"}],"collocations":[{"en":"faulty equipment","vi":"thiết bị hỏng hóc"},{"en":"faulty wiring","vi":"hệ thống dây điện có vấn đề"},{"en":"faulty reasoning","vi":"lập luận sai lầm"},{"en":"faulty assumptions","vi":"giả định sai lầm"}],"wordFamily":["fault (n.)","faultless (adj.)"],"synonyms":["defective","flawed"],"antonyms":["flawless"],"tipVi":"Có thể dùng để chỉ thiết bị gặp trục trặc hoặc dùng để chỉ lý luận, suy luận có điểm sai sót.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_data', 'en-b2-65', 'data', '/ˈdeɪtə/', 'B2', 'dữ liệu; số liệu; thông tin', 'n.', NULL, NULL, 'Trong văn phong hàng ngày, data thường được dùng như danh từ không đếm được; tuy nhiên trong ngữ cảnh học thuật, người ta cũng dùng động từ số nhiều đi kèm.', 'My watch collects data about how far I walk.', NULL, 'Đồng hồ của tôi thu thập dữ liệu về quãng đường tôi đi bộ.', '{"wordId":"data","ukIpa":"/ˈdeɪtə/","usIpa":"/ˈdeɪtə/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"facts or information collected for analysis or computer use","vi":"dữ liệu; số liệu; thông tin"}],"examples":[{"en":"My watch collects data about how far I walk.","vi":"Đồng hồ của tôi thu thập dữ liệu về quãng đường tôi đi bộ.","audioKind":"ex"},{"en":"Reliable data allows policymakers to assess whether environmental regulations are reducing pollution in urban areas.","vi":"Dữ liệu đáng tin cậy giúp các nhà hoạch định chính sách đánh giá xem các quy định về môi trường có đang làm giảm ô nhiễm ở các khu đô thị hay không.","audioKind":"ex2"}],"collocations":[{"en":"collect data","vi":"thu thập dữ liệu"},{"en":"analyse data","vi":"phân tích dữ liệu"},{"en":"personal data","vi":"dữ liệu cá nhân"},{"en":"data protection","vi":"bảo vệ dữ liệu"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong văn phong hàng ngày, data thường được dùng như danh từ không đếm được; tuy nhiên trong ngữ cảnh học thuật, người ta cũng dùng động từ số nhiều đi kèm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_insert', 'en-b2-65', 'insert', '/ɪnˈsɝːt/', 'B2', 'chèn vào; đút vào; thêm vào; lồng vào; tờ rơi; phụ trang', 'v.', 'insertion (n.)', 'Trái nghĩa: remove', 'Trọng âm động từ rơi vào âm tiết sau, trọng âm danh từ rơi vào âm tiết đầu.', 'Insert the key gently, then turn it to the left.', NULL, 'Nhẹ nhàng đút chìa khóa vào, sau đó xoay sang trái.', '{"wordId":"insert","ukIpa":"/ɪnˈsɜːt/","usIpa":"/ɪnˈsɝːt/","cefr":"B2","topic":"technology","senses":[{"pos":"v.","en":"to put something into something else","vi":"chèn vào; đút vào"},{"pos":"v.","en":"to add something within a document, recording, or piece of writing","vi":"thêm vào; lồng vào"},{"pos":"n.","en":"something designed to be placed inside another thing","vi":"tờ rơi; phụ trang"}],"examples":[{"en":"Insert the key gently, then turn it to the left.","vi":"Nhẹ nhàng đút chìa khóa vào, sau đó xoay sang trái.","audioKind":"ex"},{"en":"Students should insert relevant examples into their essays to support arguments about complex social issues.","vi":"Học sinh nên chèn các ví dụ thích hợp vào bài luận của mình để hỗ trợ các lập luận về các vấn đề xã hội phức tạp.","audioKind":"ex2"}],"collocations":[{"en":"insert into","vi":"chèn vào"},{"en":"insert a card","vi":"đút thẻ"},{"en":"insert an image","vi":"chèn một hình ảnh"}],"wordFamily":["insertion (n.)"],"synonyms":[],"antonyms":["remove"],"tipVi":"Trọng âm động từ rơi vào âm tiết sau, trọng âm danh từ rơi vào âm tiết đầu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_modernize', 'en-b2-65', 'modernize', '/ˈmɑːdərnaɪz/', 'B2', 'hiện đại hóa', 'v.', 'modern (adj.), modernization (n.)', 'Đồng nghĩa: update, upgrade', 'Trong tiếng Anh-Anh thường được viết là modernise.', 'We plan to modernize our kitchen with new appliances.', NULL, 'Chúng tôi dự định hiện đại hóa căn bếp bằng các thiết bị gia dụng mới.', '{"wordId":"modernize","ukIpa":"/ˈmɒdənaɪz/","usIpa":"/ˈmɑːdərnaɪz/","cefr":"B2","topic":"technology","senses":[{"pos":"v.","en":"To update something using newer methods, equipment, or designs.","vi":"hiện đại hóa"}],"examples":[{"en":"We plan to modernize our kitchen with new appliances.","vi":"Chúng tôi dự định hiện đại hóa căn bếp bằng các thiết bị gia dụng mới.","audioKind":"ex"},{"en":"Governments should modernize railway infrastructure to improve reliability and reduce dependence on private cars.","vi":"Chính phủ nên hiện đại hóa cơ sở hạ tầng đường sắt để nâng cao độ tin cậy và giảm sự phụ thuộc vào ô tô cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"modernize infrastructure","vi":"hiện đại hóa cơ sở hạ tầng"},{"en":"modernize the economy","vi":"hiện đại hóa nền kinh tế"},{"en":"modernize production","vi":"hiện đại hóa sản xuất"}],"wordFamily":["modern (adj.)","modernization (n.)"],"synonyms":["update","upgrade"],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh thường được viết là modernise.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_innovation', 'en-b2-65', 'innovation', '/ˌɪnəˈveɪʃən/', 'B2', 'sự đổi mới; sự cải tiến; sáng kiến; điểm đổi mới', 'n.', 'innovate (v.), innovative (adj.), innovator (n.)', NULL, 'Chỉ quá trình đổi mới thì không đếm được; chỉ sản phẩm đổi mới cụ thể thì đếm được.', 'Our kitchen encourages innovation, so we often try unusual recipes.', NULL, 'Nhà bếp của chúng tôi khuyến khích sự đổi mới, vì vậy chúng tôi thường thử những công thức nấu ăn khác thường.', '{"wordId":"innovation","ukIpa":"/ˌɪnəˈveɪʃən/","usIpa":"/ˌɪnəˈveɪʃən/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"the introduction of new ideas, methods, or products","vi":"sự đổi mới; sự cải tiến"},{"pos":"n.","en":"a new idea, method, or product that improves something","vi":"sáng kiến; điểm đổi mới"}],"examples":[{"en":"Our kitchen encourages innovation, so we often try unusual recipes.","vi":"Nhà bếp của chúng tôi khuyến khích sự đổi mới, vì vậy chúng tôi thường thử những công thức nấu ăn khác thường.","audioKind":"ex"},{"en":"Public investment in research can encourage innovation and help businesses develop more sustainable production methods.","vi":"Đầu tư công vào nghiên cứu có thể thúc đẩy đổi mới sáng tạo và giúp các doanh nghiệp phát triển các phương pháp sản xuất bền vững hơn.","audioKind":"ex2"}],"collocations":[{"en":"technological innovation","vi":"đổi mới công nghệ"},{"en":"encourage innovation","vi":"khuyến khích đổi mới"},{"en":"product innovation","vi":"đổi mới sản phẩm"},{"en":"a major innovation","vi":"một bước đột phá lớn"}],"wordFamily":["innovate (v.)","innovative (adj.)","innovator (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ quá trình đổi mới thì không đếm được; chỉ sản phẩm đổi mới cụ thể thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_navigation', 'en-b2-65', 'navigation', '/ˌnævɪˈɡeɪʃən/', 'B2', 'sự điều hướng; sự định vị và dẫn đường; thao tác điều hướng; sự duyệt trang web hoặc ứng dụng', 'n.', 'navigate (v.), navigator (n.), navigational (adj.)', NULL, 'không chỉ dùng trong hàng hải, mà còn dùng cho chỉ đường đường bộ và duyệt trang web.', 'We used a compass for navigation during our hike.', NULL, 'Chúng tôi đã dùng la bàn để định hướng trong chuyến đi bộ đường dài.', '{"wordId":"navigation","ukIpa":"/ˌnævɪˈɡeɪʃən/","usIpa":"/ˌnævɪˈɡeɪʃən/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"Finding and following a route to a destination.","vi":"sự điều hướng; sự định vị và dẫn đường"},{"pos":"n.","en":"Moving between pages or sections of a website or application.","vi":"thao tác điều hướng; sự duyệt trang web hoặc ứng dụng"}],"examples":[{"en":"We used a compass for navigation during our hike.","vi":"Chúng tôi đã dùng la bàn để định hướng trong chuyến đi bộ đường dài.","audioKind":"ex"},{"en":"Clear website navigation helps users find essential information quickly, making online public services more accessible to everyone.","vi":"Hệ thống điều hướng trang web rõ ràng giúp người dùng nhanh chóng tìm thấy thông tin thiết yếu, giúp mọi người tiếp cận các dịch vụ công trực tuyến dễ dàng hơn.","audioKind":"ex2"}],"collocations":[{"en":"satellite navigation","vi":"hệ thống định vị vệ tinh"},{"en":"a navigation system","vi":"hệ thống dẫn đường"},{"en":"website navigation","vi":"thanh điều hướng trang web"}],"wordFamily":["navigate (v.)","navigator (n.)","navigational (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"không chỉ dùng trong hàng hải, mà còn dùng cho chỉ đường đường bộ và duyệt trang web.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_virtual', 'en-b2-65', 'virtual', '/ˈvɝːtʃuəl/', 'B2', 'ảo (tạo bởi máy tính hoặc qua mạng); trên thực tế; gần như hoàn toàn', 'adj.', 'virtually (adv.), virtualize (v.), virtualization (n.)', NULL, '"virtual" không chỉ nói về ảo trên máy tính mà còn có thể mang nghĩa là trên thực tế, gần như.', 'We took a virtual tour of the museum yesterday.', NULL, 'Hôm qua chúng tôi đã tham gia một chuyến tham quan ảo bảo tàng.', '{"wordId":"virtual","ukIpa":"/ˈvɜːtʃuəl/","usIpa":"/ˈvɝːtʃuəl/","cefr":"B2","topic":"technology","senses":[{"pos":"adj.","en":"Created by computers or experienced through an online connection.","vi":"ảo (tạo bởi máy tính hoặc qua mạng)"},{"pos":"adj.","en":"Almost complete or effectively true, though not officially so.","vi":"trên thực tế; gần như hoàn toàn"}],"examples":[{"en":"We took a virtual tour of the museum yesterday.","vi":"Hôm qua chúng tôi đã tham gia một chuyến tham quan ảo bảo tàng.","audioKind":"ex"},{"en":"Virtual classrooms can widen access to education, although reliable internet connections remain essential for effective participation.","vi":"Lớp học ảo có thể mở rộng khả năng tiếp cận giáo dục, mặc dù kết nối internet ổn định vẫn là điều thiết yếu để tham gia hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"virtual reality","vi":"thực tế ảo"},{"en":"virtual classroom","vi":"lớp học ảo"},{"en":"virtual tour","vi":"chuyến tham quan ảo"},{"en":"a virtual monopoly","vi":"sự độc quyền trên thực tế"}],"wordFamily":["virtually (adv.)","virtualize (v.)","virtualization (n.)"],"synonyms":[],"antonyms":[],"tipVi":"\"virtual\" không chỉ nói về ảo trên máy tính mà còn có thể mang nghĩa là trên thực tế, gần như.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_65_1', 'en-b2-65', 'Cách dùng “data” (n.) — dữ liệu; số liệu; thông tin', 'collect data  ·  analyse data  ·  personal data', 'Trong văn phong hàng ngày, data thường được dùng như danh từ không đếm được; tuy nhiên trong ngữ cảnh học thuật, người ta cũng dùng động từ số nhiều đi kèm.', NULL, '[{"hanzi":"My watch collects data about how far I walk.","pinyin":"","meaning":"Đồng hồ của tôi thu thập dữ liệu về quãng đường tôi đi bộ."},{"hanzi":"Reliable data allows policymakers to assess whether environmental regulations are reducing pollution in urban areas.","pinyin":"","meaning":"Dữ liệu đáng tin cậy giúp các nhà hoạch định chính sách đánh giá xem các quy định về môi trường có đang làm giảm ô nhiễm ở các khu đô thị hay không."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_65_2', 'en-b2-65', 'Cách dùng “aerial” (adj.) — trên không; từ trên không', 'aerial photography  ·  an aerial view  ·  an aerial survey', 'Từ "aerial" mang nghĩa "ăng-ten" chủ yếu được dùng trong tiếng Anh-Anh; trong khi tiếng Anh-Mỹ thường dùng "antenna".', 'Họ từ (Word Family): aerially (adv.)', '[{"hanzi":"The aerial photograph showed our house beside the river.","pinyin":"","meaning":"Bức ảnh chụp từ trên không cho thấy ngôi nhà của chúng tôi nằm cạnh dòng sông."},{"hanzi":"Aerial surveys allow researchers to monitor forest loss across remote regions without disturbing wildlife.","pinyin":"","meaning":"Các cuộc khảo sát trên không cho phép các nhà nghiên cứu theo dõi tình trạng mất rừng ở các vùng hẻo lánh mà không làm xáo trộn động vật hoang dã."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_65_3', 'en-b2-65', 'Cách dùng “receiver” (n.) — máy thu thanh/truyền hình; thiết bị thu tín hiệu', 'satellite receiver  ·  radio receiver  ·  pick up the receiver', 'Từ này có thể chỉ thiết bị kỹ thuật hoặc con người; nếu chỉ người nhận thư/bưu phẩm thường dùng ''recipient''.', 'Họ từ (Word Family): receive (v.), reception (n.), recipient (n.)', '[{"hanzi":"We adjusted the receiver until the music sounded clear.","pinyin":"","meaning":"Chúng tôi đã điều chỉnh máy thu thanh cho đến khi âm thanh phát ra rõ ràng."},{"hanzi":"A satellite receiver can provide remote communities with access to educational broadcasts and emergency information.","pinyin":"","meaning":"Một chiếc máy thu vệ tinh có thể giúp các cộng đồng vùng sâu vùng xa tiếp cận với các chương trình phát sóng giáo dục và thông tin khẩn cấp."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_65_4', 'en-b2-65', 'Cách dùng “fuse” (n.) — cầu chì; thiết bị ngắt điện an toàn', 'blow a fuse  ·  replace a fuse  ·  fuse together', 'Đóng vai trò động từ chỉ sự dung hợp; blow a fuse cũng có thể dùng theo nghĩa ẩn dụ là nổi giận đùng đùng.', 'Họ từ (Word Family): fusion (n.), fusible (adj.), fused (adj.)', '[{"hanzi":"The electrician replaced the fuse, and the lights came on.","pinyin":"","meaning":"Thợ điện đã thay cầu chì và đèn đã sáng trở lại."},{"hanzi":"Modern design often fuses traditional craftsmanship with digital technology to create more sustainable consumer products.","pinyin":"","meaning":"Thiết kế hiện đại thường kết hợp giữa thủ công mỹ nghệ truyền thống và công nghệ số để tạo ra các sản phẩm tiêu dùng bền vững hơn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_65_1', 'en-b2-65', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_65_1_1', 'ten_b2_65_1', 'aerial', 'The aerial photograph showed our house beside the river.', 'The aerial photograph showed our house beside the river.', '/ˈeriəl/', 'Bức ảnh chụp từ trên không cho thấy ngôi nhà của chúng tôi nằm cạnh dòng sông.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_65_1_2', 'ten_b2_65_1', 'database', 'The library database helped me find a gardening book.', 'The library database helped me find a gardening book.', '/ˈdeɪtəbeɪs/', 'Cơ sở dữ liệu của thư viện đã giúp tôi tìm thấy một cuốn sách làm vườn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_65_1_3', 'ten_b2_65_1', 'processing', 'These apples are ready for processing into juice.', 'These apples are ready for processing into juice.', '/ˈprɑːsesɪŋ/', 'Những quả táo này đã sẵn sàng để đem đi chế biến thành nước ép.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_65_1_4', 'ten_b2_65_1', 'format', 'Please send the photos in a different file format.', 'Please send the photos in a different file format.', '/ˈfɔːrmæt/', 'Vui lòng gửi các bức ảnh bằng định dạng tệp khác.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_65_1_5', 'ten_b2_65_1', 'upgrade', 'We upgraded our old computer with a faster processor.', 'We upgraded our old computer with a faster processor.', '/ʌpˈɡreɪd/', 'Chúng tôi đã nâng cấp chiếc máy tính cũ của mình bằng một bộ vi xử lý nhanh hơn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_65_1_6', 'ten_b2_65_1', 'receiver', 'We adjusted the receiver until the music sounded clear.', 'We adjusted the receiver until the music sounded clear.', '/rɪˈsiːvər/', 'Chúng tôi đã điều chỉnh máy thu thanh cho đến khi âm thanh phát ra rõ ràng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_65_1_7', 'ten_b2_65_1', 'computerize', 'Our local library plans to computerize its borrowing records.', 'Our local library plans to computerize its borrowing records.', '/kəmˈpjuːtəraɪz/', 'Thư viện địa phương của chúng tôi có kế hoạch tin học hóa các hồ sơ mượn sách.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_65_1_8', 'ten_b2_65_1', 'fuse', 'The electrician replaced the fuse, and the lights came on.', 'The electrician replaced the fuse, and the lights came on.', '/fjuːz/', 'Thợ điện đã thay cầu chì và đèn đã sáng trở lại.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_65_1_1', 'en-b2-65', 'ten_b2_65_1', 'listening', 'listening', 'The aerial photograph showed our house beside the river.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi chọn chiếc máy giặt này vì độ tin cậy đã được kiểm chứng của nó.","Thợ điện đã thay cầu chì và đèn đã sáng trở lại.","Con tàu đánh cá được trang bị ra-đa để định hướng khi đi qua vùng sương mù.","Bức ảnh chụp từ trên không cho thấy ngôi nhà của chúng tôi nằm cạnh dòng sông."]'::jsonb, 3, 'The aerial photograph showed our house beside the river. → Bức ảnh chụp từ trên không cho thấy ngôi nhà của chúng tôi nằm cạnh dòng sông.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_65_1_2', 'en-b2-65', 'ten_b2_65_1', 'listening', 'listening', 'The library database helped me find a gardening book.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Thợ điện đã thay thế công tắc bị hỏng trong nhà bếp của chúng tôi.","Cơ sở dữ liệu của thư viện đã giúp tôi tìm thấy một cuốn sách làm vườn.","Những quả táo này đã sẵn sàng để đem đi chế biến thành nước ép.","Chúng tôi chọn chiếc máy giặt này vì độ tin cậy đã được kiểm chứng của nó."]'::jsonb, 1, 'The library database helped me find a gardening book. → Cơ sở dữ liệu của thư viện đã giúp tôi tìm thấy một cuốn sách làm vườn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_65_1_3', 'en-b2-65', 'ten_b2_65_1', 'listening', 'listening', 'These apples are ready for processing into juice.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những quả táo này đã sẵn sàng để đem đi chế biến thành nước ép.","Chúng tôi chọn chiếc máy giặt này vì độ tin cậy đã được kiểm chứng của nó.","Chúng tôi đã nâng cấp chiếc máy tính cũ của mình bằng một bộ vi xử lý nhanh hơn.","Đồng hồ của tôi thu thập dữ liệu về quãng đường tôi đi bộ."]'::jsonb, 0, 'These apples are ready for processing into juice. → Những quả táo này đã sẵn sàng để đem đi chế biến thành nước ép.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_65_2', 'en-b2-65', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_65_2_1', 'ten_b2_65_2', 'aerial', 'Aerial surveys allow researchers to monitor forest loss across remote regions without disturbing wildlife.', 'Aerial surveys allow researchers to monitor forest loss across remote regions without disturbing wildlife.', '/ˈeriəl/', 'Các cuộc khảo sát trên không cho phép các nhà nghiên cứu theo dõi tình trạng mất rừng ở các vùng hẻo lánh mà không làm xáo trộn động vật hoang dã.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_65_2_2', 'ten_b2_65_2', 'database', 'Hospitals need secure databases to protect patient records while allowing doctors to access essential information.', 'Hospitals need secure databases to protect patient records while allowing doctors to access essential information.', '/ˈdeɪtəbeɪs/', 'Các bệnh viện cần những cơ sở dữ liệu bảo mật để bảo vệ hồ sơ bệnh án đồng thời cho phép bác sĩ truy cập thông tin thiết yếu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_65_2_3', 'ten_b2_65_2', 'processing', 'Modern food processing can extend shelf life, although some methods reduce the nutritional value of fresh ingredients.', 'Modern food processing can extend shelf life, although some methods reduce the nutritional value of fresh ingredients.', '/ˈprɑːsesɪŋ/', 'Quá trình chế biến thực phẩm hiện đại có thể kéo dài thời hạn bảo quản, mặc dù một số phương pháp làm giảm giá trị dinh dưỡng của nguyên liệu tươi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_65_2_4', 'ten_b2_65_2', 'format', 'Offering course materials in a digital format can make education more accessible to students in remote areas.', 'Offering course materials in a digital format can make education more accessible to students in remote areas.', '/ˈfɔːrmæt/', 'Việc cung cấp tài liệu khóa học dưới dạng kỹ thuật số có thể giúp học viên ở vùng sâu vùng xa tiếp cận giáo dục dễ dàng hơn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_65_2_5', 'ten_b2_65_2', 'upgrade', 'Governments should upgrade ageing water systems to reduce waste and provide reliable supplies for growing urban populations.', 'Governments should upgrade ageing water systems to reduce waste and provide reliable supplies for growing urban populations.', '/ʌpˈɡreɪd/', 'Chính phủ nên nâng cấp hệ thống cấp nước đã xuống cấp để giảm thiểu lãng phí và cung cấp nguồn nước ổn định cho dân số đô thị đang ngày càng tăng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_65_2_6', 'ten_b2_65_2', 'receiver', 'A satellite receiver can provide remote communities with access to educational broadcasts and emergency information.', 'A satellite receiver can provide remote communities with access to educational broadcasts and emergency information.', '/rɪˈsiːvər/', 'Một chiếc máy thu vệ tinh có thể giúp các cộng đồng vùng sâu vùng xa tiếp cận với các chương trình phát sóng giáo dục và thông tin khẩn cấp.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_65_2_1', 'en-b2-65', 'ten_b2_65_2', 'listening', 'listening', 'Aerial surveys allow researchers to monitor forest loss across remote regions without disturbing wildlife.', NULL, 'Trong câu vừa nghe, từ “aerial” mang nghĩa nào sau đây?', '["trên không; từ trên không","mang tính cạnh tranh; cạnh tranh khốc liệt","điểm yếu; nhược điểm","nhãn hiệu; thương hiệu đã đăng ký"]'::jsonb, 0, '“aerial” (/ˈeriəl/): trên không; từ trên không. Câu đầy đủ: Aerial surveys allow researchers to monitor forest loss across remote regions without disturbing wildlife.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_65_2_2', 'en-b2-65', 'ten_b2_65_2', 'listening', 'listening', 'Hospitals need secure databases to protect patient records while allowing doctors to access essential information.', NULL, 'Trong câu vừa nghe, từ “database” mang nghĩa nào sau đây?', '["làm cho ngộp thở; làm cho không biết xoay sở thế nào","sự cất giữ; sự bảo quản","bệnh béo phì","cơ sở dữ liệu; hệ thống dữ liệu"]'::jsonb, 3, '“database” (/ˈdeɪtəbeɪs/): cơ sở dữ liệu; hệ thống dữ liệu. Câu đầy đủ: Hospitals need secure databases to protect patient records while allowing doctors to access essential information.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
