INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_65_2', 'en-b2-65', NULL, 'comprehensive_test', 'listening', 'The library database helped me find a gardening book.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã nâng cấp chiếc máy tính cũ của mình bằng một bộ vi xử lý nhanh hơn.","Đồng hồ của tôi thu thập dữ liệu về quãng đường tôi đi bộ.","Cô ấy lái một chiếc xe đạp đã được độ lại với một chiếc ghế phụ.","Cơ sở dữ liệu của thư viện đã giúp tôi tìm thấy một cuốn sách làm vườn."]'::jsonb, 3, 'The library database helped me find a gardening book. → Cơ sở dữ liệu của thư viện đã giúp tôi tìm thấy một cuốn sách làm vườn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_65_3', 'en-b2-65', NULL, 'comprehensive_test', 'listening', 'processing', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự tiến hóa","chế biến; gia công","tiến bộ; ủng hộ cải cách","sự phản đối; lời phản đối; ý kiến phản đối"]'::jsonb, 1, 'processing (/ˈprɑːsesɪŋ/) → chế biến; gia công; xử lý dữ liệu', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_65_4', 'en-b2-65', NULL, 'comprehensive_test', 'listening', 'Please send the photos in a different file format.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Vui lòng gửi các bức ảnh bằng định dạng tệp khác.","Cô ấy lái một chiếc xe đạp đã được độ lại với một chiếc ghế phụ.","Hôm qua chúng tôi đã tham gia một chuyến tham quan ảo bảo tàng.","Chúng tôi chọn chiếc máy giặt này vì độ tin cậy đã được kiểm chứng của nó."]'::jsonb, 0, 'Please send the photos in a different file format. → Vui lòng gửi các bức ảnh bằng định dạng tệp khác.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_65_5', 'en-b2-65', NULL, 'comprehensive_test', 'listening', 'upgrade', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bức xạ; tia bức xạ","nâng cấp; cải thiện","nhàn rỗi; không hoạt động; bỏ không","phương tiếng; tiếng địa phương"]'::jsonb, 1, 'upgrade (/ʌpˈɡreɪd/) → nâng cấp; cải thiện; sự nâng cấp; bản cải tiến', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_65_6', 'en-b2-65', NULL, 'comprehensive_test', 'listening', 'We adjusted the receiver until the music sounded clear.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Con tàu đánh cá được trang bị ra-đa để định hướng khi đi qua vùng sương mù.","Những quả táo này đã sẵn sàng để đem đi chế biến thành nước ép.","Cô ấy lái một chiếc xe đạp đã được độ lại với một chiếc ghế phụ.","Chúng tôi đã điều chỉnh máy thu thanh cho đến khi âm thanh phát ra rõ ràng."]'::jsonb, 3, 'We adjusted the receiver until the music sounded clear. → Chúng tôi đã điều chỉnh máy thu thanh cho đến khi âm thanh phát ra rõ ràng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
