INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_65_8', 'en-b2-65', NULL, 'comprehensive_test', 'listening', 'The electrician replaced the fuse, and the lights came on.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Thợ điện đã thay cầu chì và đèn đã sáng trở lại.","Tôi tìm thấy một thợ sửa ống nước gần nhà trong danh bạ địa phương.","Đồng hồ của tôi thu thập dữ liệu về quãng đường tôi đi bộ.","Cơ sở dữ liệu của thư viện đã giúp tôi tìm thấy một cuốn sách làm vườn."]'::jsonb, 0, 'The electrician replaced the fuse, and the lights came on. → Thợ điện đã thay cầu chì và đèn đã sáng trở lại.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
