INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_65_18', 'en-b2-65', NULL, 'comprehensive_test', 'reading', NULL, 'Aerial surveys allow researchers to monitor forest loss across remote regions without disturbing wildlife.', 'Dựa vào câu trên, từ “aerial” có nghĩa phù hợp nhất là gì?', '["tỷ lệ; phần (của một tổng thể)","chiến binh; dũng sĩ","cảm kích; biết ơn","trên không; từ trên không"]'::jsonb, 3, 'aerial: trên không; từ trên không; ăng-ten. Dịch cả câu: Các cuộc khảo sát trên không cho phép các nhà nghiên cứu theo dõi tình trạng mất rừng ở các vùng hẻo lánh mà không làm xáo trộn động vật hoang dã.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_65_19', 'en-b2-65', NULL, 'comprehensive_test', 'reading', NULL, 'Hospitals need secure databases to protect patient records while allowing doctors to access essential information.', 'Dựa vào câu trên, từ “database” có nghĩa phù hợp nhất là gì?', '["cơ sở dữ liệu; hệ thống dữ liệu","dễ vỡ; dễ hỏng","sự nhập cư; việc di cư vào nước khác","chàng trai; cậu thanh niên"]'::jsonb, 0, 'database: cơ sở dữ liệu; hệ thống dữ liệu. Dịch cả câu: Các bệnh viện cần những cơ sở dữ liệu bảo mật để bảo vệ hồ sơ bệnh án đồng thời cho phép bác sĩ truy cập thông tin thiết yếu.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_65_20', 'en-b2-65', NULL, 'comprehensive_test', 'reading', NULL, 'Modern food processing can extend shelf life, although some methods reduce the nutritional value of fresh ingredients.', 'Dựa vào câu trên, từ “processing” có nghĩa phù hợp nhất là gì?', '["người sống sót; người <b>còn sống</b>","cái xách nước; cái thùng đựng nước","chế biến; gia công","cuộc mít tinh; cuộc biểu tình"]'::jsonb, 2, 'processing: chế biến; gia công; xử lý dữ liệu. Dịch cả câu: Quá trình chế biến thực phẩm hiện đại có thể kéo dài thời hạn bảo quản, mặc dù một số phương pháp làm giảm giá trị dinh dưỡng của nguyên liệu tươi.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_65_21', 'en-b2-65', NULL, 'comprehensive_test', 'reading', NULL, 'Offering course materials in a digital format can make education more accessible to students in remote areas.', 'Dựa vào câu trên, từ “format” có nghĩa phù hợp nhất là gì?', '["quả địa cầu","tính linh hoạt; khả năng uyển chuyển thích nghi","làm ngạc nhiên; làm kinh ngạc","định dạng; hình thức trình bày"]'::jsonb, 3, 'format: định dạng; hình thức trình bày; trình bày văn bản; định dạng (thiết bị lưu trữ để chuẩn bị chứa dữ liệu). Dịch cả câu: Việc cung cấp tài liệu khóa học dưới dạng kỹ thuật số có thể giúp học viên ở vùng sâu vùng xa tiếp cận giáo dục dễ dàng hơn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_65_22', 'en-b2-65', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự đổi mới; sự cải tiến”', '["motivated","decline","idle","innovation"]'::jsonb, 3, 'sự đổi mới; sự cải tiến → innovation (/ˌɪnəˈveɪʃən/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_65_23', 'en-b2-65', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự điều hướng; sự định vị và dẫn đường”', '["hose","fringe","surroundings","navigation"]'::jsonb, 3, 'sự điều hướng; sự định vị và dẫn đường → navigation (/ˌnævɪˈɡeɪʃən/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_65_24', 'en-b2-65', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ảo (tạo bởi máy tính hoặc qua mạng)”', '["virtual","allowance","distract","sewage"]'::jsonb, 0, 'ảo (tạo bởi máy tính hoặc qua mạng) → virtual (/ˈvɝːtʃuəl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-66', 'en', 'Bài 66: Công nghệ & Kỹ thuật (3) - CEFR B2', 'CEFR B2', 'B2 · Công nghệ', '21 từ vựng Tiếng Anh CEFR B2 chủ đề công nghệ & kỹ thuật kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4066, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sophisticated', 'en-b2-66', 'sophisticated', '/səˈfɪstɪkeɪtɪd/', 'B2', 'tinh vi; phức tạp; hiện đại; sành điệu; tinh tế; hiểu biết rộng', 'adj.', 'sophistication (n.), unsophisticated (adj.)', 'Đồng nghĩa: advanced, refined · Trái nghĩa: unsophisticated, basic', 'Khi dùng cho máy móc, thiết bị có nghĩa là tinh vi, tiên tiến; khi dùng cho con người có nghĩa là sành điệu, hiểu biết rộng.', 'This sophisticated camera adjusts its settings automatically in low light.', NULL, 'Máy ảnh hiện đại này tự động điều chỉnh các cài đặt trong điều kiện ánh sáng yếu.', '{"wordId":"sophisticated","ukIpa":"/səˈfɪstɪkeɪtɪd/","usIpa":"/səˈfɪstɪkeɪtɪd/","cefr":"B2","topic":"technology","senses":[{"pos":"adj.","en":"highly developed and involving complex methods or technology","vi":"tinh vi; phức tạp; hiện đại"},{"pos":"adj.","en":"knowledgeable about culture and confident in social situations","vi":"sành điệu; tinh tế; hiểu biết rộng"}],"examples":[{"en":"This sophisticated camera adjusts its settings automatically in low light.","vi":"Máy ảnh hiện đại này tự động điều chỉnh các cài đặt trong điều kiện ánh sáng yếu.","audioKind":"ex"},{"en":"Sophisticated monitoring systems allow researchers to detect small changes in air quality across densely populated cities.","vi":"Các hệ thống giám sát tinh vi cho phép các nhà nghiên cứu phát hiện những thay đổi nhỏ về chất lượng không khí ở các thành phố đông dân cư.","audioKind":"ex2"}],"collocations":[{"en":"sophisticated technology","vi":"công nghệ hiện đại"},{"en":"sophisticated equipment","vi":"thiết bị tối tân"},{"en":"sophisticated analysis","vi":"phân tích chuyên sâu"}],"wordFamily":["sophistication (n.)","unsophisticated (adj.)"],"synonyms":["advanced","refined"],"antonyms":["unsophisticated","basic"],"tipVi":"Khi dùng cho máy móc, thiết bị có nghĩa là tinh vi, tiên tiến; khi dùng cho con người có nghĩa là sành điệu, hiểu biết rộng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_outdated', 'en-b2-66', 'outdated', '/ˌaʊtˈdeɪtɪd/', 'B2', 'lỗi thời; cũ kỹ', 'adj.', 'outdate (v.)', 'Đồng nghĩa: obsolete, outmoded · Trái nghĩa: up-to-date, current', 'Nhấn mạnh sự không còn phù hợp do thời đại thay đổi, không chỉ đơn thuần là có từ lâu đời.', 'This outdated map doesn''t show the new train station.', NULL, 'Bản đồ lỗi thời này không thể hiện nhà ga xe lửa mới.', '{"wordId":"outdated","ukIpa":"/ˌaʊtˈdeɪtɪd/","usIpa":"/ˌaʊtˈdeɪtɪd/","cefr":"B2","topic":"technology","senses":[{"pos":"adj.","en":"No longer useful or suitable because things have changed.","vi":"lỗi thời; cũ kỹ"}],"examples":[{"en":"This outdated map doesn''t show the new train station.","vi":"Bản đồ lỗi thời này không thể hiện nhà ga xe lửa mới.","audioKind":"ex"},{"en":"Hospitals need adequate funding to replace outdated equipment and provide safer, more effective treatment for patients.","vi":"Các bệnh viện cần có đủ nguồn kinh phí để thay thế trang thiết bị lỗi thời và cung cấp các phương pháp điều trị an toàn, hiệu quả hơn cho bệnh nhân.","audioKind":"ex2"}],"collocations":[{"en":"outdated equipment","vi":"thiết bị lỗi thời"},{"en":"outdated information","vi":"thông tin lỗi thời"},{"en":"outdated attitudes","vi":"quan niệm lỗi thời"}],"wordFamily":["outdate (v.)"],"synonyms":["obsolete","outmoded"],"antonyms":["up-to-date","current"],"tipVi":"Nhấn mạnh sự không còn phù hợp do thời đại thay đổi, không chỉ đơn thuần là có từ lâu đời.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_portable', 'en-b2-66', 'portable', '/ˈpɔːrtəbəl/', 'B2', 'dễ mang theo; xách tay; di động', 'adj.', 'portability (n.)', 'Trái nghĩa: fixed', 'Nhấn mạnh tính chất dễ xách đi hoặc di chuyển, không nhất thiết phải là loại đút túi nhỏ gọn.', 'We took a portable speaker to the picnic.', NULL, 'Chúng tôi đã mang theo một chiếc loa xách tay đi dã ngoại.', '{"wordId":"portable","ukIpa":"/ˈpɔːtəbəl/","usIpa":"/ˈpɔːrtəbəl/","cefr":"B2","topic":"technology","senses":[{"pos":"adj.","en":"Easy to carry or move from place to place","vi":"dễ mang theo; xách tay; di động"}],"examples":[{"en":"We took a portable speaker to the picnic.","vi":"Chúng tôi đã mang theo một chiếc loa xách tay đi dã ngoại.","audioKind":"ex"},{"en":"Portable medical equipment enables healthcare workers to provide essential services in remote rural communities.","vi":"Thiết bị y tế di động giúp các nhân viên y tế cung cấp các dịch vụ chăm sóc thiết yếu tại những vùng nông thôn vùng sâu vùng xa.","audioKind":"ex2"}],"collocations":[{"en":"portable device","vi":"thiết bị di động"},{"en":"portable charger","vi":"sạc dự phòng"},{"en":"portable equipment","vi":"thiết bị xách tay"}],"wordFamily":["portability (n.)"],"synonyms":[],"antonyms":["fixed"],"tipVi":"Nhấn mạnh tính chất dễ xách đi hoặc di chuyển, không nhất thiết phải là loại đút túi nhỏ gọn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_function', 'en-b2-66', 'function', '/ˈfʌŋkʃən/', 'B2', 'chức năng; tác dụng; hoạt động; vận hành; hàm số', 'n.', 'functional (adj.), functionally (adv.), functionality (n.)', 'Đồng nghĩa: purpose, role', 'Cấu trúc function as đi với danh từ theo sau, mang nghĩa là đóng vai trò hoặc hoạt động như cái gì đó.', 'What is the function of this small red button?', NULL, 'Chức năng của chiếc nút đỏ nhỏ này là gì?', '{"wordId":"function","ukIpa":"/ˈfʌŋkʃən/","usIpa":"/ˈfʌŋkʃən/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"The purpose or job of something or someone.","vi":"chức năng; tác dụng"},{"pos":"v.","en":"To work or operate in the intended way.","vi":"hoạt động; vận hành"},{"pos":"n.","en":"A mathematical relationship assigning each input exactly one output.","vi":"hàm số"}],"examples":[{"en":"What is the function of this small red button?","vi":"Chức năng của chiếc nút đỏ nhỏ này là gì?","audioKind":"ex"},{"en":"Urban parks serve an important function by providing space for exercise, relaxation, and social interaction.","vi":"Các công viên đô thị đóng một vai trò quan trọng khi cung cấp không gian cho việc tập thể dục, thư giãn và giao lưu xã hội.","audioKind":"ex2"}],"collocations":[{"en":"perform a function","vi":"thực hiện chức năng"},{"en":"function properly","vi":"hoạt động bình thường"},{"en":"function as","vi":"đóng vai trò là"},{"en":"basic function","vi":"chức năng cơ bản"}],"wordFamily":["functional (adj.)","functionally (adv.)","functionality (n.)"],"synonyms":["purpose","role"],"antonyms":[],"tipVi":"Cấu trúc function as đi với danh từ theo sau, mang nghĩa là đóng vai trò hoặc hoạt động như cái gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mechanical', 'en-b2-66', 'mechanical', '/məˈkænɪkəl/', 'B2', 'thuộc về cơ khí; thuộc về máy móc; máy móc; rập khuôn; vô cảm', 'adj.', 'mechanically (adv.), mechanic (n.), mechanics (n.), mechanism (n.)', NULL, 'mechanical chỉ máy móc liên quan; mechanic chỉ thợ sửa chữa cơ khí.', 'A mechanical fault stopped our car outside the village.', NULL, 'Một sự cố cơ khí đã khiến xe của chúng tôi dừng lại ngoài làng.', '{"wordId":"mechanical","ukIpa":"/məˈkænɪkəl/","usIpa":"/məˈkænɪkəl/","cefr":"B2","topic":"technology","senses":[{"pos":"adj.","en":"relating to machines or their moving parts","vi":"thuộc về cơ khí; thuộc về máy móc"},{"pos":"adj.","en":"done without thought, interest, or feeling","vi":"máy móc; rập khuôn; vô cảm"}],"examples":[{"en":"A mechanical fault stopped our car outside the village.","vi":"Một sự cố cơ khí đã khiến xe của chúng tôi dừng lại ngoài làng.","audioKind":"ex"},{"en":"Regular inspections can identify mechanical problems before they cause serious disruptions to public transport services.","vi":"Việc kiểm tra định kỳ có thể phát hiện các vấn đề cơ khí trước khi chúng gây ra sự gián đoạn nghiêm trọng đối với các dịch vụ giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"mechanical engineering","vi":"kỹ thuật cơ khí"},{"en":"mechanical failure","vi":"hỏng hóc cơ khí"},{"en":"mechanical parts","vi":"các chi tiết cơ khí"},{"en":"a mechanical response","vi":"một phản ứng rập khuôn"}],"wordFamily":["mechanically (adv.)","mechanic (n.)","mechanics (n.)","mechanism (n.)"],"synonyms":[],"antonyms":[],"tipVi":"mechanical chỉ máy móc liên quan; mechanic chỉ thợ sửa chữa cơ khí.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_technological', 'en-b2-66', 'technological', '/ˌteknəˈlɑːdʒɪkəl/', 'B2', 'thuộc về công nghệ; kỹ thuật', 'adj.', 'technology (n.), technologically (adv.), technologist (n.)', NULL, 'technological nhấn mạnh vào sự phát triển công nghệ, còn technical nhấn mạnh vào kỹ thuật cụ thể.', 'My grandfather enjoys learning about the latest technological advances.', NULL, 'Ông tôi thích tìm hiểu về những tiến bộ công nghệ mới nhất.', '{"wordId":"technological","ukIpa":"/ˌteknəˈlɒdʒɪkəl/","usIpa":"/ˌteknəˈlɑːdʒɪkəl/","cefr":"B2","topic":"technology","senses":[{"pos":"adj.","en":"relating to technology and its practical development","vi":"thuộc về công nghệ; kỹ thuật"}],"examples":[{"en":"My grandfather enjoys learning about the latest technological advances.","vi":"Ông tôi thích tìm hiểu về những tiến bộ công nghệ mới nhất.","audioKind":"ex"},{"en":"Technological innovation can improve agricultural productivity while reducing the amount of water required for irrigation.","vi":"Đổi mới công nghệ có thể nâng cao năng suất nông nghiệp đồng thời giảm lượng nước cần thiết cho việc tư tiêu.","audioKind":"ex2"}],"collocations":[{"en":"technological advances","vi":"tiến bộ công nghệ"},{"en":"technological innovation","vi":"đổi mới công nghệ"},{"en":"technological development","vi":"phát triển công nghệ"}],"wordFamily":["technology (n.)","technologically (adv.)","technologist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"technological nhấn mạnh vào sự phát triển công nghệ, còn technical nhấn mạnh vào kỹ thuật cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_usage', 'en-b2-66', 'usage', '/ˈjuːsɪdʒ/', 'B2', 'lượng sử dụng; cách sử dụng; cách dùng từ; cách diễn đạt thông thường', 'n.', 'use (v.), user (n.), usable (adj.)', NULL, 'usage trọng tâm diễn tả lượng sử dụng, cách thức sử dụng hoặc thói quen dùng từ trong ngôn ngữ.', 'My phone tracks my daily data usage automatically.', NULL, 'Điện thoại của tôi tự động theo dõi lượng dữ liệu sử dụng hàng ngày của tôi.', '{"wordId":"usage","ukIpa":"/ˈjuːsɪdʒ/","usIpa":"/ˈjuːsɪdʒ/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"The way or amount that something is used.","vi":"lượng sử dụng; cách sử dụng"},{"pos":"n.","en":"The customary way words or phrases are used in language.","vi":"cách dùng từ; cách diễn đạt thông thường"}],"examples":[{"en":"My phone tracks my daily data usage automatically.","vi":"Điện thoại của tôi tự động theo dõi lượng dữ liệu sử dụng hàng ngày của tôi.","audioKind":"ex"},{"en":"Installing efficient appliances can reduce household energy usage without requiring major changes to everyday routines.","vi":"Việc lắp đặt các thiết bị tiết kiệm điện có thể làm giảm mức tiêu thụ năng lượng trong gia đình mà không đòi hỏi phải thay đổi lớn các thói quen sinh hoạt hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"energy usage","vi":"lượng năng lượng tiêu thụ"},{"en":"data usage","vi":"dung lượng dữ liệu sử dụng"},{"en":"common usage","vi":"cách dùng phổ biến"},{"en":"usage patterns","vi":"mô hình sử dụng"}],"wordFamily":["use (v.)","user (n.)","usable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"usage trọng tâm diễn tả lượng sử dụng, cách thức sử dụng hoặc thói quen dùng từ trong ngôn ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chip', 'en-b2-66', 'chip', '/tʃɪp/', 'B2', 'vi mạch; chip điện tử; mảnh vỡ; vết sứt; làm sứt mẻ; mẻ', 'n.', 'chipped (adj.)', NULL, 'Thực phẩm trong tiếng Anh gọi là chips: tiếng Anh-Anh chỉ khoai tây chiên, còn tiếng Anh-Mỹ thường chỉ khoai tây chiên lát mỏng.', 'The repairer replaced a damaged chip inside my laptop.', NULL, 'Thợ sửa chữa đã thay một vi mạch bị hỏng bên trong máyδ tính xách tay của tôi.', '{"wordId":"chip","ukIpa":"/tʃɪp/","usIpa":"/tʃɪp/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"a tiny electronic component containing many connected circuits","vi":"vi mạch; chip điện tử"},{"pos":"n.","en":"a small broken piece or the mark it leaves","vi":"mảnh vỡ; vết sứt"},{"pos":"v.","en":"to break a small piece off something","vi":"làm sứt mẻ; mẻ"}],"examples":[{"en":"The repairer replaced a damaged chip inside my laptop.","vi":"Thợ sửa chữa đã thay một vi mạch bị hỏng bên trong máyδ tính xách tay của tôi.","audioKind":"ex"},{"en":"Demand for advanced chips is increasing as more industries adopt artificial intelligence and automated production systems.","vi":"Nhu cầu về các loại vi mạch tiên tiến đang tăng lên khi ngày càng có nhiều ngành công nghiệp áp dụng trí tuệ nhân tạo và các hệ thống sản xuất tự động.","audioKind":"ex2"}],"collocations":[{"en":"computer chip","vi":"chip máy tính"},{"en":"silicon chip","vi":"chip silicon"},{"en":"a chip in a cup","vi":"vết sứt trên cốc"},{"en":"chip a tooth","vi":"mẻ răng"}],"wordFamily":["chipped (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thực phẩm trong tiếng Anh gọi là chips: tiếng Anh-Anh chỉ khoai tây chiên, còn tiếng Anh-Mỹ thường chỉ khoai tây chiên lát mỏng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disable', 'en-b2-66', 'disable', '/dɪsˈeɪbəl/', 'B2', 'vô hiệu hóa; tắt; làm cho tàn tật; làm mất khả năng', 'v.', 'disabled (adj.), disability (n.), disabling (adj.)', 'Đồng nghĩa: deactivate · Trái nghĩa: enable, activate', 'Trong ngữ cảnh công nghệ, từ này thường có nghĩa là "vô hiệu hóa/tắt", không có nghĩa là xóa hoặc làm hỏng.', 'I disabled notifications so my phone stayed quiet during dinner.', NULL, 'Tôi đã tắt thông báo để điện thoại được yên tĩnh trong bữa tối.', '{"wordId":"disable","ukIpa":"/dɪsˈeɪbəl/","usIpa":"/dɪsˈeɪbəl/","cefr":"B2","topic":"technology","senses":[{"pos":"v.","en":"to prevent a device or feature from working","vi":"vô hiệu hóa; tắt"},{"pos":"v.","en":"to cause a condition that limits someone''s activities","vi":"làm cho tàn tật; làm mất khả năng"}],"examples":[{"en":"I disabled notifications so my phone stayed quiet during dinner.","vi":"Tôi đã tắt thông báo để điện thoại được yên tĩnh trong bữa tối.","audioKind":"ex"},{"en":"Users should be able to disable location tracking without losing access to essential digital services.","vi":"Người dùng nên có khả năng vô hiệu hóa tính năng theo dõi vị trí mà không bị mất quyền truy cập vào các dịch vụ kỹ thuật số thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"disable notifications","vi":"vô hiệu hóa thông báo"},{"en":"disable an alarm","vi":"tắt báo thức"},{"en":"disable location tracking","vi":"vô hiệu hóa việc theo dõi vị trí"}],"wordFamily":["disabled (adj.)","disability (n.)","disabling (adj.)"],"synonyms":["deactivate"],"antonyms":["enable","activate"],"tipVi":"Trong ngữ cảnh công nghệ, từ này thường có nghĩa là \"vô hiệu hóa/tắt\", không có nghĩa là xóa hoặc làm hỏng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_artificial', 'en-b2-66', 'artificial', '/ˌɑːrtəˈfɪʃəl/', 'B2', 'nhân tạo; giả; không tự nhiên; gượng gạo', 'adj.', 'artificially (adv.), artificiality (n.)', 'Đồng nghĩa: synthetic, man-made · Trái nghĩa: natural', 'artificial chỉ đồ nhân tạo; artistic mới là thuộc về nghệ thuật.', 'The artificial flowers looked surprisingly fresh on the table.', NULL, 'Những bông hoa giả trông tươi một cách đáng ngạc nhiên trên bàn.', '{"wordId":"artificial","ukIpa":"/ˌɑːtɪˈfɪʃəl/","usIpa":"/ˌɑːrtəˈfɪʃəl/","cefr":"B2","topic":"technology","senses":[{"pos":"adj.","en":"Made by people rather than occurring naturally","vi":"nhân tạo; giả"},{"pos":"adj.","en":"Not sincere or natural in appearance or behaviour","vi":"không tự nhiên; gượng gạo"}],"examples":[{"en":"The artificial flowers looked surprisingly fresh on the table.","vi":"Những bông hoa giả trông tươi một cách đáng ngạc nhiên trên bàn.","audioKind":"ex"},{"en":"Excessive artificial lighting in urban areas can disrupt wildlife behaviour and reduce the visibility of stars.","vi":"Ánh sáng nhân tạo quá mức ở các khu vực đô thị có thể làm xáo trộn tập tính của động vật hoang dã và làm giảm khả năng quan sát các vì sao.","audioKind":"ex2"}],"collocations":[{"en":"artificial intelligence","vi":"trí tuệ nhân tạo"},{"en":"artificial lighting","vi":"ánh sáng nhân tạo"},{"en":"artificial sweeteners","vi":"chất tạo ngọt nhân tạo"},{"en":"an artificial smile","vi":"nụ cười gượng gạo"}],"wordFamily":["artificially (adv.)","artificiality (n.)"],"synonyms":["synthetic","man-made"],"antonyms":["natural"],"tipVi":"artificial chỉ đồ nhân tạo; artistic mới là thuộc về nghệ thuật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tracking', 'en-b2-66', 'tracking', '/ˈtrækɪŋ/', 'B2', 'sự theo dõi; sự định vị theo dõi', 'n.', 'track (v.), tracker (n.)', 'Đồng nghĩa: monitoring', 'Đóng vai trò danh từ thường không đếm được; đây cũng là dạng phân từ hiện tại của động từ track.', 'Parcel tracking showed that my package had arrived nearby.', NULL, 'Thông tin theo dõi bưu kiện cho thấy gói hàng của tôi đã đến khu vực lân cận.', '{"wordId":"tracking","ukIpa":"/ˈtrækɪŋ/","usIpa":"/ˈtrækɪŋ/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"The process of following movements or monitoring changes over time.","vi":"sự theo dõi; sự định vị theo dõi"}],"examples":[{"en":"Parcel tracking showed that my package had arrived nearby.","vi":"Thông tin theo dõi bưu kiện cho thấy gói hàng của tôi đã đến khu vực lân cận.","audioKind":"ex"},{"en":"Satellite tracking enables researchers to study animal migration and identify habitats that require stronger protection.","vi":"Hệ thống theo dõi vệ tinh giúp các nhà nghiên cứu nghiên cứu sự di cư của động vật và xác định các môi trường sống cần được bảo vệ mạnh mẽ hơn.","audioKind":"ex2"}],"collocations":[{"en":"satellite tracking","vi":"theo dõi bằng vệ tinh"},{"en":"parcel tracking","vi":"theo dõi bưu kiện"},{"en":"tracking device","vi":"thiết bị theo dõi"},{"en":"real-time tracking","vi":"theo dõi thời gian thực"}],"wordFamily":["track (v.)","tracker (n.)"],"synonyms":["monitoring"],"antonyms":[],"tipVi":"Đóng vai trò danh từ thường không đếm được; đây cũng là dạng phân từ hiện tại của động từ track.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_operate', 'en-b2-66', 'operate', '/ˈɑːpəreɪt/', 'B2', 'điều khiển thiết bị; vận hành (máy móc); kinh doanh; điều hành công ty; cung cấp dịch vụ; phẫu thuật cho bệnh nhân', 'v.', 'operation (n.), operator (n.), operational (adj.)', 'Đồng nghĩa: run, control', 'Thao tác máy móc trực tiếp đi với tân ngữ; phẫu thuật cho ai đó dùng operate on.', 'Can you show me how to operate this printer?', NULL, 'Bạn có thể chỉ cho tôi cách vận hành chiếc máy in này không?', '{"wordId":"operate","ukIpa":"/ˈɒpəreɪt/","usIpa":"/ˈɑːpəreɪt/","cefr":"B2","topic":"technology","senses":[{"pos":"v.","en":"to control equipment, or to work as a machine","vi":"điều khiển thiết bị; vận hành (máy móc)"},{"pos":"v.","en":"to run a business or provide a service","vi":"kinh doanh; điều hành công ty; cung cấp dịch vụ"},{"pos":"v.","en":"to perform surgery on a patient","vi":"phẫu thuật cho bệnh nhân"}],"examples":[{"en":"Can you show me how to operate this printer?","vi":"Bạn có thể chỉ cho tôi cách vận hành chiếc máy in này không?","audioKind":"ex"},{"en":"Companies that operate in rural areas often face higher transport costs and limited access to skilled workers.","vi":"Các công ty hoạt động ở khu vực nông thôn thường phải đối mặt với chi phí vận chuyển cao hơn và ít có cơ hội tiếp cận lao động lành nghề.","audioKind":"ex2"}],"collocations":[{"en":"operate machinery","vi":"vận hành máy móc"},{"en":"operate a business","vi":"điều hành doanh nghiệp"},{"en":"operate on a patient","vi":"phẫu thuật cho bệnh nhân"},{"en":"operate efficiently","vi":"vận hành hiệu quả"}],"wordFamily":["operation (n.)","operator (n.)","operational (adj.)"],"synonyms":["run","control"],"antonyms":[],"tipVi":"Thao tác máy móc trực tiếp đi với tân ngữ; phẫu thuật cho ai đó dùng operate on.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gadget', 'en-b2-66', 'gadget', '/ˈɡædʒɪt/', 'B2', 'thiết bị điện tử nhỏ gọn; dụng cụ tiện ích', 'n.', NULL, 'Đồng nghĩa: device', 'Chỉ các vật dụng nhỏ có công dụng cụ thể, không nhất thiết phải là đồ điện tử.', 'This handy gadget removes apple cores in seconds.', NULL, 'Thiết bị tiện ích này có thể khoét lõi táo chỉ trong vài giây.', '{"wordId":"gadget","ukIpa":"/ˈɡædʒɪt/","usIpa":"/ˈɡædʒɪt/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"A small device designed to perform a particular useful task","vi":"thiết bị điện tử nhỏ gọn; dụng cụ tiện ích"}],"examples":[{"en":"This handy gadget removes apple cores in seconds.","vi":"Thiết bị tiện ích này có thể khoét lõi táo chỉ trong vài giây.","audioKind":"ex"},{"en":"Although a new electronic gadget may offer convenience, frequent replacement contributes to growing amounts of electronic waste.","vi":"Mặc dù một thiết bị điện tử mới có thể mang lại sự tiện lợi, nhưng việc thay thế thường xuyên lại góp phần làm gia tăng lượng rác thải điện tử.","audioKind":"ex2"}],"collocations":[{"en":"electronic gadget","vi":"thiết bị điện tử nhỏ"},{"en":"kitchen gadget","vi":"dụng cụ nhà bếp"},{"en":"handy gadget","vi":"thiết bị tiện dụng"}],"wordFamily":[],"synonyms":["device"],"antonyms":[],"tipVi":"Chỉ các vật dụng nhỏ có công dụng cụ thể, không nhất thiết phải là đồ điện tử.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_installation', 'en-b2-66', 'installation', '/ˌɪnstəˈleɪʃən/', 'B2', 'sự lắp đặt; sự cài đặt; hệ thống thiết bị; cơ sở vật chất; tác phẩm nghệ thuật sắp đặt', 'n.', 'install (v.), installer (n.)', NULL, 'Chỉ quá trình lắp đặt thường không đếm được; chỉ thiết bị cụ thể hoặc tác phẩm thì đếm được.', 'Installation of our new dishwasher took less than an hour.', NULL, 'Việc lắp đặt chiếc máy rửa bát mới của chúng tôi mất chưa đầy một giờ.', '{"wordId":"installation","ukIpa":"/ˌɪnstəˈleɪʃən/","usIpa":"/ˌɪnstəˈleɪʃən/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"the process of putting equipment or software in place for use","vi":"sự lắp đặt; sự cài đặt"},{"pos":"n.","en":"equipment or buildings arranged for a particular purpose","vi":"hệ thống thiết bị; cơ sở vật chất"},{"pos":"n.","en":"an artwork made by arranging objects within a space","vi":"tác phẩm nghệ thuật sắp đặt"}],"examples":[{"en":"Installation of our new dishwasher took less than an hour.","vi":"Việc lắp đặt chiếc máy rửa bát mới của chúng tôi mất chưa đầy một giờ.","audioKind":"ex"},{"en":"The installation of solar panels on public buildings can lower energy costs and reduce carbon emissions.","vi":"Việc lắp đặt các tấm pin năng lượng mặt trời trên các tòa nhà công cộng có thể cắt giảm chi phí năng lượng và giảm lượng khí thải carbon.","audioKind":"ex2"}],"collocations":[{"en":"installation costs","vi":"chi phí lắp đặt"},{"en":"software installation","vi":"cài đặt phần mềm"},{"en":"electrical installation","vi":"lắp đặt thiết bị điện"},{"en":"art installation","vi":"tác phẩm nghệ thuật sắp đặt"}],"wordFamily":["install (v.)","installer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ quá trình lắp đặt thường không đếm được; chỉ thiết bị cụ thể hoặc tác phẩm thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_modify', 'en-b2-66', 'modify', '/ˈmɑːdəfaɪ/', 'B2', 'sửa đổi; điều chỉnh cho phù hợp hơn; bổ nghĩa; hạn chế nghĩa của từ khác trong ngữ pháp', 'v.', 'modification (n.), modified (adj.), modifier (n.)', 'Đồng nghĩa: adjust, alter', 'Thường chỉ sự điều chỉnh cục bộ, không nhất thiết là thay đổi hoàn toàn.', 'We modified the recipe to use less sugar.', NULL, 'Chúng tôi đã điều chỉnh công thức để dùng ít đường hơn.', '{"wordId":"modify","ukIpa":"/ˈmɒdɪfaɪ/","usIpa":"/ˈmɑːdəfaɪ/","cefr":"B2","topic":"technology","senses":[{"pos":"v.","en":"To change something slightly to improve it or suit a purpose.","vi":"sửa đổi; điều chỉnh cho phù hợp hơn"},{"pos":"v.","en":"To describe or limit another word''s meaning in grammar.","vi":"bổ nghĩa; hạn chế nghĩa của từ khác trong ngữ pháp"}],"examples":[{"en":"We modified the recipe to use less sugar.","vi":"Chúng tôi đã điều chỉnh công thức để dùng ít đường hơn.","audioKind":"ex"},{"en":"Schools may need to modify their teaching methods to support students with different learning needs.","vi":"Các trường học có thể cần điều chỉnh phương pháp giảng dạy để hỗ trợ học sinh có nhu cầu học tập khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"modify a design","vi":"sửa đổi thiết kế"},{"en":"modify behaviour","vi":"điều chỉnh hành vi"},{"en":"modify a plan","vi":"điều chỉnh kế hoạch"}],"wordFamily":["modification (n.)","modified (adj.)","modifier (n.)"],"synonyms":["adjust","alter"],"antonyms":[],"tipVi":"Thường chỉ sự điều chỉnh cục bộ, không nhất thiết là thay đổi hoàn toàn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lever', 'en-b2-66', 'lever', '/ˈlevər/', 'B2', 'cần gạt; đòn bẩy; dùng đòn bẩy để dịch chuyển; biện pháp; phương tiện tác động', 'n.', 'leverage (n.), leverage (v.)', NULL, 'Tiếng Anh-Anh âm đầu đọc là /liː/, tiếng Anh-Mỹ thường đọc là /lev/.', 'Pull this lever to raise the seat a little.', NULL, 'Hãy kéo cần gạt này để nâng ghế lên một chút.', '{"wordId":"lever","ukIpa":"/ˈliːvə/","usIpa":"/ˈlevər/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"A bar used to move something or control a machine","vi":"cần gạt; đòn bẩy"},{"pos":"v.","en":"To move something using a bar as a lever","vi":"dùng đòn bẩy để dịch chuyển"},{"pos":"n.","en":"A means of influencing people or changing a situation","vi":"biện pháp; phương tiện tác động"}],"examples":[{"en":"Pull this lever to raise the seat a little.","vi":"Hãy kéo cần gạt này để nâng ghế lên một chút.","audioKind":"ex"},{"en":"Tax policy can serve as a powerful lever for encouraging businesses to invest in cleaner technologies.","vi":"Chính sách thuế có thể đóng vai trò là một đòn bẩy mạnh mẽ để khuyến khích các doanh nghiệp đầu tư vào công nghệ sạch hơn.","audioKind":"ex2"}],"collocations":[{"en":"pull a lever","vi":"kéo cần gạt"},{"en":"lever something open","vi":"cạy mở cái gì đó"},{"en":"a lever for change","vi":"đòn bẩy cho sự thay đổi"}],"wordFamily":["leverage (n.)","leverage (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Tiếng Anh-Anh âm đầu đọc là /liː/, tiếng Anh-Mỹ thường đọc là /lev/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mode', 'en-b2-66', 'mode', '/moʊd/', 'B2', 'cách thức; phương thức; chế độ (thiết bị, hệ thống)', 'n.', NULL, 'Đồng nghĩa: method, way', 'Cách thức thường dùng mode of; thiết bị ở trạng thái chế độ nào dùng in... mode.', 'I switched my phone to silent mode before dinner.', NULL, 'Tôi đã chuyển điện thoại sang chế độ im lặng trước bữa tối.', '{"wordId":"mode","ukIpa":"/məʊd/","usIpa":"/moʊd/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"A particular way of doing something.","vi":"cách thức; phương thức"},{"pos":"n.","en":"A setting that controls how a device or system operates.","vi":"chế độ (thiết bị, hệ thống)"}],"examples":[{"en":"I switched my phone to silent mode before dinner.","vi":"Tôi đã chuyển điện thoại sang chế độ im lặng trước bữa tối.","audioKind":"ex"},{"en":"Cycling is an environmentally friendly mode of transport that can also improve public health in urban areas.","vi":"Đạp xe là một phương thức giao thông thân thiện với môi trường, đồng thời cũng có thể cải thiện sức khỏe cộng đồng ở các khu vực đô thị.","audioKind":"ex2"}],"collocations":[{"en":"mode of transport","vi":"phương thức giao thông"},{"en":"mode of communication","vi":"phương thức giao tiếp"},{"en":"silent mode","vi":"chế độ im lặng"},{"en":"sleep mode","vi":"chế độ ngủ"}],"wordFamily":[],"synonyms":["method","way"],"antonyms":[],"tipVi":"Cách thức thường dùng mode of; thiết bị ở trạng thái chế độ nào dùng in... mode.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cable', 'en-b2-66', 'cable', '/ˈkeɪbəl/', 'B2', 'cáp; dây cáp (mang điện hoặc tín hiệu điện tử); dây thừng lớn (thường làm bằng kim loại)', 'n.', 'cabling (n.)', NULL, 'Từ này vừa dùng để chỉ cáp truyền điện hoặc tín hiệu, vừa có thể chỉ cáp thép dùng để chịu lực.', 'The charging cable was tangled beneath my desk.', NULL, 'Dây cáp sạc bị rối tung bên dưới bàn làm việc của tôi.', '{"wordId":"cable","ukIpa":"/ˈkeɪbəl/","usIpa":"/ˈkeɪbəl/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"covered wires carrying electricity or electronic signals","vi":"cáp; dây cáp (mang điện hoặc tín hiệu điện tử)"},{"pos":"n.","en":"a thick strong rope, usually made of metal wires","vi":"cáp; dây thừng lớn (thường làm bằng kim loại)"}],"examples":[{"en":"The charging cable was tangled beneath my desk.","vi":"Dây cáp sạc bị rối tung bên dưới bàn làm việc của tôi.","audioKind":"ex"},{"en":"Undersea cable networks carry vast amounts of data, making them essential infrastructure for international communication and trade.","vi":"Mạng lưới cáp quang biển truyền tải lượng dữ liệu khổng lồ, biến chúng thành cơ sở hạ tầng thiết yếu cho hoạt động thông tin và thương mại quốc tế.","audioKind":"ex2"}],"collocations":[{"en":"power cable","vi":"cáp nguồn"},{"en":"fibre-optic cable","vi":"cáp quang"},{"en":"undersea cable","vi":"cáp ngầm dưới biển"},{"en":"steel cable","vi":"cáp thép"}],"wordFamily":["cabling (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ này vừa dùng để chỉ cáp truyền điện hoặc tín hiệu, vừa có thể chỉ cáp thép dùng để chịu lực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_photographic', 'en-b2-66', 'photographic', '/ˌfoʊtəˈɡræfɪk/', 'B2', 'thuộc về nhiếp ảnh; bằng ảnh; ghi nhớ hình ảnh cực kỳ chính xác', 'adj.', 'photograph (n.), photography (n.), photographer (n.), photographically (adv.)', NULL, 'photographic memory chỉ trí nhớ cực kỳ chuẩn xác, không phải là lưu trữ bằng ảnh.', 'She packed her photographic equipment before the sunrise walk.', NULL, 'Cô ấy đã thu dọn thiết bị chụp ảnh trước chuyến đi bộ ngắm bình minh.', '{"wordId":"photographic","ukIpa":"/ˌfəʊtəˈɡræfɪk/","usIpa":"/ˌfoʊtəˈɡræfɪk/","cefr":"B2","topic":"technology","senses":[{"pos":"adj.","en":"relating to photography or photographs","vi":"thuộc về nhiếp ảnh; bằng ảnh"},{"pos":"adj.","en":"able to remember visual details with great accuracy","vi":"ghi nhớ hình ảnh cực kỳ chính xác"}],"examples":[{"en":"She packed her photographic equipment before the sunrise walk.","vi":"Cô ấy đã thu dọn thiết bị chụp ảnh trước chuyến đi bộ ngắm bình minh.","audioKind":"ex"},{"en":"Photographic evidence allows researchers to document changes in glacier size and communicate climate trends to the public.","vi":"Bằng chứng bằng hình ảnh giúp các nhà nghiên cứu ghi lại các thay đổi về kích thước băng hà và truyền tải xu hướng khí hậu đến công chúng.","audioKind":"ex2"}],"collocations":[{"en":"photographic equipment","vi":"thiết bị nhiếp ảnh"},{"en":"photographic evidence","vi":"bằng chứng hình ảnh"},{"en":"a photographic memory","vi":"trí nhớ siêu phàm"}],"wordFamily":["photograph (n.)","photography (n.)","photographer (n.)","photographically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"photographic memory chỉ trí nhớ cực kỳ chuẩn xác, không phải là lưu trữ bằng ảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_detection', 'en-b2-66', 'detection', '/dɪˈtekʃən/', 'B2', 'sự phát hiện; sự dò tìm; sự xét nghiệm', 'n.', 'detect (v.), detector (n.), detectable (adj.), undetectable (adj.)', 'Đồng nghĩa: discovery, identification', 'Thường không đếm được; detection of theo sau là đối tượng được phát hiện hoặc dò tìm.', 'Early detection of the leak saved us expensive repairs.', NULL, 'Việc phát hiện sớm vết rò rỉ đã giúp chúng tôi tiết kiệm chi phí sửa chữa đắt đỏ.', '{"wordId":"detection","ukIpa":"/dɪˈtekʃən/","usIpa":"/dɪˈtekʃən/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"The act of discovering or noticing something difficult to find.","vi":"sự phát hiện; sự dò tìm; sự xét nghiệm"}],"examples":[{"en":"Early detection of the leak saved us expensive repairs.","vi":"Việc phát hiện sớm vết rò rỉ đã giúp chúng tôi tiết kiệm chi phí sửa chữa đắt đỏ.","audioKind":"ex"},{"en":"Advances in medical imaging have improved the early detection of diseases, allowing patients to receive treatment sooner.","vi":"Những tiến bộ trong công nghệ chẩn đoán hình ảnh đã cải thiện việc phát hiện sớm các bệnh lý, giúp bệnh nhân được điều trị sớm hơn.","audioKind":"ex2"}],"collocations":[{"en":"early detection","vi":"phát hiện sớm"},{"en":"avoid detection","vi":"tránh bị phát hiện"},{"en":"fraud detection","vi":"phát hiện gian lận"},{"en":"smoke detection","vi":"phát hiện khói"}],"wordFamily":["detect (v.)","detector (n.)","detectable (adj.)","undetectable (adj.)"],"synonyms":["discovery","identification"],"antonyms":[],"tipVi":"Thường không đếm được; detection of theo sau là đối tượng được phát hiện hoặc dò tìm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_icon', 'en-b2-66', 'icon', '/ˈaɪkɑːn/', 'B2', 'biểu tượng (trên màn hình máy tính, điện thoại); hình mẫu; thần tượng; biểu tượng văn hóa; ảnh thánh (trong truyền thống Ki-tô giáo)', 'n.', 'iconic (adj.)', NULL, 'Cả hai nghĩa đều phổ biến: có thể chỉ biểu tượng kỹ thuật số trên màn hình hoặc người/vật mang tính biểu tượng, thần tượng.', 'Tap the camera icon to take a quick photo.', NULL, 'Nhấp vào biểu tượng máy ảnh để chụp nhanh một bức ảnh.', '{"wordId":"icon","ukIpa":"/ˈaɪkɒn/","usIpa":"/ˈaɪkɑːn/","cefr":"B2","topic":"technology","senses":[{"pos":"n.","en":"a small screen image representing a program, file, or function","vi":"biểu tượng (trên màn hình máy tính, điện thoại)"},{"pos":"n.","en":"a widely admired person or thing representing something important","vi":"hình mẫu; thần tượng; biểu tượng văn hóa"},{"pos":"n.","en":"a sacred image used in some Christian traditions","vi":"ảnh thánh (trong truyền thống Ki-tô giáo)"}],"examples":[{"en":"Tap the camera icon to take a quick photo.","vi":"Nhấp vào biểu tượng máy ảnh để chụp nhanh một bức ảnh.","audioKind":"ex"},{"en":"A familiar cultural icon can attract international visitors and strengthen a city''s identity in tourism campaigns.","vi":"Một biểu tượng văn hóa quen thuộc có thể thu hút du khách quốc tế và củng cố bản sắc của một thành phố trong các chiến dịch du lịch.","audioKind":"ex2"}],"collocations":[{"en":"click an icon","vi":"nhấp vào biểu tượng"},{"en":"desktop icon","vi":"biểu tượng trên màn hình nền"},{"en":"cultural icon","vi":"biểu tượng văn hóa"},{"en":"fashion icon","vi":"thần tượng thời trang"}],"wordFamily":["iconic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cả hai nghĩa đều phổ biến: có thể chỉ biểu tượng kỹ thuật số trên màn hình hoặc người/vật mang tính biểu tượng, thần tượng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_66_1', 'en-b2-66', 'Cách dùng “chip” (n.) — vi mạch; chip điện tử', 'computer chip  ·  silicon chip  ·  a chip in a cup', 'Thực phẩm trong tiếng Anh gọi là chips: tiếng Anh-Anh chỉ khoai tây chiên, còn tiếng Anh-Mỹ thường chỉ khoai tây chiên lát mỏng.', 'Họ từ (Word Family): chipped (adj.)', '[{"hanzi":"The repairer replaced a damaged chip inside my laptop.","pinyin":"","meaning":"Thợ sửa chữa đã thay một vi mạch bị hỏng bên trong máyδ tính xách tay của tôi."},{"hanzi":"Demand for advanced chips is increasing as more industries adopt artificial intelligence and automated production systems.","pinyin":"","meaning":"Nhu cầu về các loại vi mạch tiên tiến đang tăng lên khi ngày càng có nhiều ngành công nghiệp áp dụng trí tuệ nhân tạo và các hệ thống sản xuất tự động."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_66_2', 'en-b2-66', 'Cách dùng “sophisticated” (adj.) — tinh vi; phức tạp; hiện đại', 'sophisticated technology  ·  sophisticated equipment  ·  sophisticated analysis', 'Khi dùng cho máy móc, thiết bị có nghĩa là tinh vi, tiên tiến; khi dùng cho con người có nghĩa là sành điệu, hiểu biết rộng.', 'Họ từ (Word Family): sophistication (n.), unsophisticated (adj.) | Đồng nghĩa: advanced, refined · Trái nghĩa: unsophisticated, basic', '[{"hanzi":"This sophisticated camera adjusts its settings automatically in low light.","pinyin":"","meaning":"Máy ảnh hiện đại này tự động điều chỉnh các cài đặt trong điều kiện ánh sáng yếu."},{"hanzi":"Sophisticated monitoring systems allow researchers to detect small changes in air quality across densely populated cities.","pinyin":"","meaning":"Các hệ thống giám sát tinh vi cho phép các nhà nghiên cứu phát hiện những thay đổi nhỏ về chất lượng không khí ở các thành phố đông dân cư."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_66_3', 'en-b2-66', 'Cách dùng “icon” (n.) — biểu tượng (trên màn hình máy tính, điện thoại)', 'click an icon  ·  desktop icon  ·  cultural icon', 'Cả hai nghĩa đều phổ biến: có thể chỉ biểu tượng kỹ thuật số trên màn hình hoặc người/vật mang tính biểu tượng, thần tượng.', 'Họ từ (Word Family): iconic (adj.)', '[{"hanzi":"Tap the camera icon to take a quick photo.","pinyin":"","meaning":"Nhấp vào biểu tượng máy ảnh để chụp nhanh một bức ảnh."},{"hanzi":"A familiar cultural icon can attract international visitors and strengthen a city''s identity in tourism campaigns.","pinyin":"","meaning":"Một biểu tượng văn hóa quen thuộc có thể thu hút du khách quốc tế và củng cố bản sắc của một thành phố trong các chiến dịch du lịch."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_66_4', 'en-b2-66', 'Cách dùng “disable” (v.) — vô hiệu hóa; tắt', 'disable notifications  ·  disable an alarm  ·  disable location tracking', 'Trong ngữ cảnh công nghệ, từ này thường có nghĩa là "vô hiệu hóa/tắt", không có nghĩa là xóa hoặc làm hỏng.', 'Họ từ (Word Family): disabled (adj.), disability (n.), disabling (adj.) | Đồng nghĩa: deactivate · Trái nghĩa: enable, activate', '[{"hanzi":"I disabled notifications so my phone stayed quiet during dinner.","pinyin":"","meaning":"Tôi đã tắt thông báo để điện thoại được yên tĩnh trong bữa tối."},{"hanzi":"Users should be able to disable location tracking without losing access to essential digital services.","pinyin":"","meaning":"Người dùng nên có khả năng vô hiệu hóa tính năng theo dõi vị trí mà không bị mất quyền truy cập vào các dịch vụ kỹ thuật số thiết yếu."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_66_1', 'en-b2-66', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_66_1_1', 'ten_b2_66_1', 'sophisticated', 'This sophisticated camera adjusts its settings automatically in low light.', 'This sophisticated camera adjusts its settings automatically in low light.', '/səˈfɪstɪkeɪtɪd/', 'Máy ảnh hiện đại này tự động điều chỉnh các cài đặt trong điều kiện ánh sáng yếu.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_66_1_2', 'ten_b2_66_1', 'outdated', 'This outdated map doesn''t show the new train station.', 'This outdated map doesn''t show the new train station.', '/ˌaʊtˈdeɪtɪd/', 'Bản đồ lỗi thời này không thể hiện nhà ga xe lửa mới.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_66_1_3', 'ten_b2_66_1', 'portable', 'We took a portable speaker to the picnic.', 'We took a portable speaker to the picnic.', '/ˈpɔːrtəbəl/', 'Chúng tôi đã mang theo một chiếc loa xách tay đi dã ngoại.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
