INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_66_1_8', 'ten_b2_66_1', 'chip', 'The repairer replaced a damaged chip inside my laptop.', 'The repairer replaced a damaged chip inside my laptop.', '/tʃɪp/', 'Thợ sửa chữa đã thay một vi mạch bị hỏng bên trong máyδ tính xách tay của tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_66_1_1', 'en-b2-66', 'ten_b2_66_1', 'listening', 'listening', 'This sophisticated camera adjusts its settings automatically in low light.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một sự cố cơ khí đã khiến xe của chúng tôi dừng lại ngoài làng.","Hãy kéo cần gạt này để nâng ghế lên một chút.","Bạn có thể chỉ cho tôi cách vận hành chiếc máy in này không?","Máy ảnh hiện đại này tự động điều chỉnh các cài đặt trong điều kiện ánh sáng yếu."]'::jsonb, 3, 'This sophisticated camera adjusts its settings automatically in low light. → Máy ảnh hiện đại này tự động điều chỉnh các cài đặt trong điều kiện ánh sáng yếu.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_66_1_2', 'en-b2-66', 'ten_b2_66_1', 'listening', 'listening', 'This outdated map doesn''t show the new train station.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nhấp vào biểu tượng máy ảnh để chụp nhanh một bức ảnh.","Bản đồ lỗi thời này không thể hiện nhà ga xe lửa mới.","Những bông hoa giả trông tươi một cách đáng ngạc nhiên trên bàn.","Chúng tôi đã mang theo một chiếc loa xách tay đi dã ngoại."]'::jsonb, 1, 'This outdated map doesn''t show the new train station. → Bản đồ lỗi thời này không thể hiện nhà ga xe lửa mới.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_66_1_3', 'en-b2-66', 'ten_b2_66_1', 'listening', 'listening', 'We took a portable speaker to the picnic.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Ông tôi thích tìm hiểu về những tiến bộ công nghệ mới nhất.","Điện thoại của tôi tự động theo dõi lượng dữ liệu sử dụng hàng ngày của tôi.","Chúng tôi đã mang theo một chiếc loa xách tay đi dã ngoại.","Tôi đã chuyển điện thoại sang chế độ im lặng trước bữa tối."]'::jsonb, 2, 'We took a portable speaker to the picnic. → Chúng tôi đã mang theo một chiếc loa xách tay đi dã ngoại.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_66_2', 'en-b2-66', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_66_2_1', 'ten_b2_66_2', 'sophisticated', 'Sophisticated monitoring systems allow researchers to detect small changes in air quality across densely populated cities.', 'Sophisticated monitoring systems allow researchers to detect small changes in air quality across densely populated cities.', '/səˈfɪstɪkeɪtɪd/', 'Các hệ thống giám sát tinh vi cho phép các nhà nghiên cứu phát hiện những thay đổi nhỏ về chất lượng không khí ở các thành phố đông dân cư.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_66_2_2', 'ten_b2_66_2', 'outdated', 'Hospitals need adequate funding to replace outdated equipment and provide safer, more effective treatment for patients.', 'Hospitals need adequate funding to replace outdated equipment and provide safer, more effective treatment for patients.', '/ˌaʊtˈdeɪtɪd/', 'Các bệnh viện cần có đủ nguồn kinh phí để thay thế trang thiết bị lỗi thời và cung cấp các phương pháp điều trị an toàn, hiệu quả hơn cho bệnh nhân.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_66_2_3', 'ten_b2_66_2', 'portable', 'Portable medical equipment enables healthcare workers to provide essential services in remote rural communities.', 'Portable medical equipment enables healthcare workers to provide essential services in remote rural communities.', '/ˈpɔːrtəbəl/', 'Thiết bị y tế di động giúp các nhân viên y tế cung cấp các dịch vụ chăm sóc thiết yếu tại những vùng nông thôn vùng sâu vùng xa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_66_2_4', 'ten_b2_66_2', 'function', 'Urban parks serve an important function by providing space for exercise, relaxation, and social interaction.', 'Urban parks serve an important function by providing space for exercise, relaxation, and social interaction.', '/ˈfʌŋkʃən/', 'Các công viên đô thị đóng một vai trò quan trọng khi cung cấp không gian cho việc tập thể dục, thư giãn và giao lưu xã hội.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_66_2_5', 'ten_b2_66_2', 'mechanical', 'Regular inspections can identify mechanical problems before they cause serious disruptions to public transport services.', 'Regular inspections can identify mechanical problems before they cause serious disruptions to public transport services.', '/məˈkænɪkəl/', 'Việc kiểm tra định kỳ có thể phát hiện các vấn đề cơ khí trước khi chúng gây ra sự gián đoạn nghiêm trọng đối với các dịch vụ giao thông công cộng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_66_2_6', 'ten_b2_66_2', 'technological', 'Technological innovation can improve agricultural productivity while reducing the amount of water required for irrigation.', 'Technological innovation can improve agricultural productivity while reducing the amount of water required for irrigation.', '/ˌteknəˈlɑːdʒɪkəl/', 'Đổi mới công nghệ có thể nâng cao năng suất nông nghiệp đồng thời giảm lượng nước cần thiết cho việc tư tiêu.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
