INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_66_2_2', 'en-b2-66', 'ten_b2_66_2', 'listening', 'listening', 'Hospitals need adequate funding to replace outdated equipment and provide safer, more effective treatment for patients.', NULL, 'Trong câu vừa nghe, từ “outdated” mang nghĩa nào sau đây?', '["nhà tài trợ; mạnh thường quân","lỗi thời; cũ kỹ","sưng lên; phồng lên","thú nhận; thú tội; khai nhận"]'::jsonb, 1, '“outdated” (/ˌaʊtˈdeɪtɪd/): lỗi thời; cũ kỹ. Câu đầy đủ: Hospitals need adequate funding to replace outdated equipment and provide safer, more effective treatment for patients.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
