INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_66_2', 'en-b2-66', NULL, 'comprehensive_test', 'listening', 'This outdated map doesn''t show the new train station.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ông tôi thích tìm hiểu về những tiến bộ công nghệ mới nhất.","Máy ảnh hiện đại này tự động điều chỉnh các cài đặt trong điều kiện ánh sáng yếu.","Bản đồ lỗi thời này không thể hiện nhà ga xe lửa mới.","Thợ sửa chữa đã thay một vi mạch bị hỏng bên trong máyδ tính xách tay của tôi."]'::jsonb, 2, 'This outdated map doesn''t show the new train station. → Bản đồ lỗi thời này không thể hiện nhà ga xe lửa mới.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_66_3', 'en-b2-66', NULL, 'comprehensive_test', 'listening', 'portable', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["lỗ khóa; ổ khóa","sự thay mặt, đại diện hoặc vì lợi ích của ai đó","dễ mang theo; xách tay; di động","phương tiện thông tin đại chúng; đại chúng truyền thông"]'::jsonb, 2, 'portable (/ˈpɔːrtəbəl/) → dễ mang theo; xách tay; di động', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_66_4', 'en-b2-66', NULL, 'comprehensive_test', 'listening', 'What is the function of this small red button?', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chức năng của chiếc nút đỏ nhỏ này là gì?","Nhấp vào biểu tượng máy ảnh để chụp nhanh một bức ảnh.","Việc phát hiện sớm vết rò rỉ đã giúp chúng tôi tiết kiệm chi phí sửa chữa đắt đỏ.","Chúng tôi đã điều chỉnh công thức để dùng ít đường hơn."]'::jsonb, 0, 'What is the function of this small red button? → Chức năng của chiếc nút đỏ nhỏ này là gì?', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
