INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_66_6', 'en-b2-66', NULL, 'comprehensive_test', 'listening', 'My grandfather enjoys learning about the latest technological advances.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Dây cáp sạc bị rối tung bên dưới bàn làm việc của tôi.","Ông tôi thích tìm hiểu về những tiến bộ công nghệ mới nhất.","Chức năng của chiếc nút đỏ nhỏ này là gì?","Tôi đã tắt thông báo để điện thoại được yên tĩnh trong bữa tối."]'::jsonb, 1, 'My grandfather enjoys learning about the latest technological advances. → Ông tôi thích tìm hiểu về những tiến bộ công nghệ mới nhất.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
