INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_66_12', 'en-b2-66', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a tiny electronic component containing many connected circuits”?', '["cable","chip","modify","outdated"]'::jsonb, 1, 'chip (/tʃɪp/) → vi mạch; chip điện tử', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
