INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_66_18', 'en-b2-66', NULL, 'comprehensive_test', 'reading', NULL, 'Sophisticated monitoring systems allow researchers to detect small changes in air quality across densely populated cities.', 'Dựa vào câu trên, từ “sophisticated” có nghĩa phù hợp nhất là gì?', '["mối nguy hiểm; hiểm họa","chín chắn; trưởng thành; biết điều","tinh vi; phức tạp; hiện đại","áp đảo; vô cùng lớn, mạnh mẽ"]'::jsonb, 2, 'sophisticated: tinh vi; phức tạp; hiện đại; sành điệu; tinh tế; hiểu biết rộng. Dịch cả câu: Các hệ thống giám sát tinh vi cho phép các nhà nghiên cứu phát hiện những thay đổi nhỏ về chất lượng không khí ở các thành phố đông dân cư.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_66_19', 'en-b2-66', NULL, 'comprehensive_test', 'reading', NULL, 'Hospitals need adequate funding to replace outdated equipment and provide safer, more effective treatment for patients.', 'Dựa vào câu trên, từ “outdated” có nghĩa phù hợp nhất là gì?', '["nằm ngang; song song với mặt đất","bướng bỉnh, cứng đầu, ngoan cố","thuộc về hành chính; quản lý","lỗi thời; cũ kỹ"]'::jsonb, 3, 'outdated: lỗi thời; cũ kỹ. Dịch cả câu: Các bệnh viện cần có đủ nguồn kinh phí để thay thế trang thiết bị lỗi thời và cung cấp các phương pháp điều trị an toàn, hiệu quả hơn cho bệnh nhân.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_66_20', 'en-b2-66', NULL, 'comprehensive_test', 'reading', NULL, 'Portable medical equipment enables healthcare workers to provide essential services in remote rural communities.', 'Dựa vào câu trên, từ “portable” có nghĩa phù hợp nhất là gì?', '["sự dự báo; bản dự báo","dễ mang theo; xách tay; di động","buổi thử vai; buổi thử giọng","khan hiếm; thiếu thốn"]'::jsonb, 1, 'portable: dễ mang theo; xách tay; di động. Dịch cả câu: Thiết bị y tế di động giúp các nhân viên y tế cung cấp các dịch vụ chăm sóc thiết yếu tại những vùng nông thôn vùng sâu vùng xa.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_66_21', 'en-b2-66', NULL, 'comprehensive_test', 'reading', NULL, 'Urban parks serve an important function by providing space for exercise, relaxation, and social interaction.', 'Dựa vào câu trên, từ “function” có nghĩa phù hợp nhất là gì?', '["chức năng; tác dụng","nghiêm trọng; dữ dội; tàn khốc","băng rôn; biểu ngữ; cờ","giữa học kỳ; giữa nhiệm kỳ"]'::jsonb, 0, 'function: chức năng; tác dụng; hoạt động; vận hành; hàm số. Dịch cả câu: Các công viên đô thị đóng một vai trò quan trọng khi cung cấp không gian cho việc tập thể dục, thư giãn và giao lưu xã hội.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_66_22', 'en-b2-66', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thuộc về nhiếp ảnh; bằng ảnh”', '["whip","photographic","sponsorship","tracking"]'::jsonb, 1, 'thuộc về nhiếp ảnh; bằng ảnh → photographic (/ˌfoʊtəˈɡræfɪk/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_66_23', 'en-b2-66', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự phát hiện; sự dò tìm; sự xét nghiệm”', '["detection","motto","supervisor","faculty"]'::jsonb, 0, 'sự phát hiện; sự dò tìm; sự xét nghiệm → detection (/dɪˈtekʃən/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_66_24', 'en-b2-66', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “biểu tượng (trên màn hình máy tính, điện thoại)”', '["module","anger","seek","icon"]'::jsonb, 3, 'biểu tượng (trên màn hình máy tính, điện thoại) → icon (/ˈaɪkɑːn/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-67', 'en', 'Bài 67: Khoa học & Nghiên cứu (1) - CEFR B2', 'CEFR B2', 'B2 · Khoa học', '25 từ vựng Tiếng Anh CEFR B2 chủ đề khoa học & nghiên cứu kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4067, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_forecast', 'en-b2-67', 'forecast', '/ˈfɔːrkæst/', 'B2', 'sự dự báo; bản dự báo; dự báo; dự đoán', 'n.', 'forecaster (n.), forecasting (n.)', 'Đồng nghĩa: prediction, predict', 'Quá khứ đơn và quá khứ phân từ thường dùng forecast, cũng có thể dùng forecasted.', 'The weather forecast says we should expect snow tonight.', NULL, 'Dự báo thời tiết nói rằng tối nay có thể sẽ có tuyết.', '{"wordId":"forecast","ukIpa":"/ˈfɔːkɑːst/","usIpa":"/ˈfɔːrkæst/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A statement about what is likely to happen in the future.","vi":"sự dự báo; bản dự báo"},{"pos":"v.","en":"To say what will probably happen, using available information.","vi":"dự báo; dự đoán"}],"examples":[{"en":"The weather forecast says we should expect snow tonight.","vi":"Dự báo thời tiết nói rằng tối nay có thể sẽ có tuyết.","audioKind":"ex"},{"en":"Economists forecast slower growth next year as rising energy costs place greater pressure on businesses.","vi":"Các nhà kinh tế dự báo tăng trưởng sẽ chậm lại vào năm tới khi chi phí năng lượng tăng cao gây áp lực lớn hơn lên các doanh nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"weather forecast","vi":"dự báo thời tiết"},{"en":"economic forecast","vi":"dự báo kinh tế"},{"en":"forecast growth","vi":"dự báo tăng trưởng"},{"en":"forecast demand","vi":"dự báo nhu cầu"}],"wordFamily":["forecaster (n.)","forecasting (n.)"],"synonyms":["prediction","predict"],"antonyms":[],"tipVi":"Quá khứ đơn và quá khứ phân từ thường dùng forecast, cũng có thể dùng forecasted.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_psychology', 'en-b2-67', 'psychology', '/saɪˈkɑːlədʒi/', 'B2', 'tâm lý học; tâm lý; đặc điểm tâm lý', 'n.', 'psychologist (n.), psychological (adj.), psychologically (adv.)', NULL, 'Âm p ở đầu từ bị câm; psychologist chỉ nhà tâm lý học.', 'My sister studies psychology and hopes to help children.', NULL, 'Chị gái tôi học tâm lý học và hy vọng có thể giúp đỡ trẻ em.', '{"wordId":"psychology","ukIpa":"/saɪˈkɒlədʒi/","usIpa":"/saɪˈkɑːlədʒi/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"The scientific study of the mind and behaviour.","vi":"tâm lý học"},{"pos":"n.","en":"The characteristic ways a person or group thinks and behaves.","vi":"tâm lý; đặc điểm tâm lý"}],"examples":[{"en":"My sister studies psychology and hopes to help children.","vi":"Chị gái tôi học tâm lý học và hy vọng có thể giúp đỡ trẻ em.","audioKind":"ex"},{"en":"Research in psychology suggests that regular social interaction can support emotional wellbeing among older adults.","vi":"Nghiên cứu trong ngành tâm lý học cho thấy việc tương tác xã hội thường xuyên có thể hỗ trợ sức khỏe tinh thần ở người lớn tuổi.","audioKind":"ex2"}],"collocations":[{"en":"clinical psychology","vi":"tâm lý học lâm sàng"},{"en":"educational psychology","vi":"tâm lý học giáo dục"},{"en":"consumer psychology","vi":"tâm lý người tiêu dùng"},{"en":"study psychology","vi":"học tâm lý học"}],"wordFamily":["psychologist (n.)","psychological (adj.)","psychologically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Âm p ở đầu từ bị câm; psychologist chỉ nhà tâm lý học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_crystal', 'en-b2-67', 'crystal', '/ˈkrɪstəl/', 'B2', 'tinh thể; thạch anh; thủy tinh cao cấp; đồ bằng thủy tinh pha lê', 'n.', 'crystalline (adj.), crystallise (v.), crystallisation (n.)', NULL, 'crystal clear vừa dùng để tả nước trong vắt, vừa chỉ ý nghĩa vô cùng rõ ràng.', 'We examined a salt crystal under the classroom microscope.', NULL, 'Chúng tôi đã quan sát một tinh thể muối dưới kính hiển vi của lớp học.', '{"wordId":"crystal","ukIpa":"/ˈkrɪstəl/","usIpa":"/ˈkrɪstəl/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A solid whose particles form a regular, repeating pattern.","vi":"tinh thể"},{"pos":"n.","en":"Clear quartz used in jewellery and decorative objects.","vi":"thạch anh"},{"pos":"n.","en":"High-quality glass, or objects made from it.","vi":"thủy tinh cao cấp; đồ bằng thủy tinh pha lê"}],"examples":[{"en":"We examined a salt crystal under the classroom microscope.","vi":"Chúng tôi đã quan sát một tinh thể muối dưới kính hiển vi của lớp học.","audioKind":"ex"},{"en":"The structure of a crystal influences its physical properties and determines its suitability for various industrial applications.","vi":"Cấu trúc của một tinh thể ảnh hưởng đến các tính chất vật lý của nó và quyết định độ phù hợp của nó đối với các ứng dụng công nghiệp khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"salt crystals","vi":"tinh thể muối"},{"en":"crystal structure","vi":"cấu trúc tinh thể"},{"en":"crystal glass","vi":"thủy tinh pha lê"},{"en":"crystal clear","vi":"trong vắt như pha lê; rõ như ban ngày"}],"wordFamily":["crystalline (adj.)","crystallise (v.)","crystallisation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"crystal clear vừa dùng để tả nước trong vắt, vừa chỉ ý nghĩa vô cùng rõ ràng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cubic', 'en-b2-67', 'cubic', '/ˈkjuːbɪk/', 'B2', 'hình lập phương; tính theo mét khối (thể tích)', 'adj.', 'cube (n.), cube (v.)', NULL, 'Cubic dùng cho đơn vị thể tích; square dùng cho đơn vị diện tích.', 'Our new water tank holds two cubic metres.', NULL, 'Bồn chứa nước mới của chúng tôi có sức chứa hai mét khối.', '{"wordId":"cubic","ukIpa":"/ˈkjuːbɪk/","usIpa":"/ˈkjuːbɪk/","cefr":"B2","topic":"science","senses":[{"pos":"adj.","en":"relating to volume measured in cubes, or shaped like a cube","vi":"hình lập phương; tính theo mét khối (thể tích)"}],"examples":[{"en":"Our new water tank holds two cubic metres.","vi":"Bồn chứa nước mới của chúng tôi có sức chứa hai mét khối.","audioKind":"ex"},{"en":"Modern irrigation systems can save thousands of cubic metres of water each year.","vi":"Các hệ thống tưới tiêu hiện đại có thể tiết kiệm hàng ngàn mét khối nước mỗi năm.","audioKind":"ex2"}],"collocations":[{"en":"cubic metre","vi":"mét khối"},{"en":"cubic centimetre","vi":"centimét khối"},{"en":"cubic capacity","vi":"dung tích buồng máy"}],"wordFamily":["cube (n.)","cube (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Cubic dùng cho đơn vị thể tích; square dùng cho đơn vị diện tích.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_astronomer', 'en-b2-67', 'astronomer', '/əˈstrɑːnəmɚ/', 'B2', 'nhà thiên văn học', 'n.', 'astronomy (n.), astronomical (adj.)', NULL, '"astronomer" nghiên cứu các thiên thể; "astrologer" là nhà chiêm tinh.', 'The astronomer adjusted her telescope beneath the clear night sky.', NULL, 'Nhà thiên văn học đã điều chỉnh kính viễn vọng của cô ấy dưới bầu trời đêm quang đãng.', '{"wordId":"astronomer","ukIpa":"/əˈstrɒnəmə/","usIpa":"/əˈstrɑːnəmɚ/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"a scientist who studies stars, planets, and space","vi":"nhà thiên văn học"}],"examples":[{"en":"The astronomer adjusted her telescope beneath the clear night sky.","vi":"Nhà thiên văn học đã điều chỉnh kính viễn vọng của cô ấy dưới bầu trời đêm quang đãng.","audioKind":"ex"},{"en":"Astronomers use powerful telescopes to investigate distant galaxies and improve our understanding of how the universe developed.","vi":"Các nhà thiên văn học sử dụng kính viễn vọng công suất lớn để nghiên cứu các thiên hà xa xôi và nâng cao sự hiểu biết của chúng ta về sự hình thành của vũ trụ.","audioKind":"ex2"}],"collocations":[{"en":"professional astronomer","vi":"nhà thiên văn học chuyên nghiệp"},{"en":"amateur astronomer","vi":"nhà thiên văn học nghiệp dư"}],"wordFamily":["astronomy (n.)","astronomical (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"\"astronomer\" nghiên cứu các thiên thể; \"astrologer\" là nhà chiêm tinh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_correlation', 'en-b2-67', 'correlation', '/ˌkɔːrəˈleɪʃən/', 'B2', 'sự tương quan; mối liên hệ', 'n.', 'correlate (v.), correlated (adj.), correlational (adj.)', 'Đồng nghĩa: association, relationship', 'correlation không đồng nghĩa với causation: sự tương quan không đại diện cho nhân quả.', 'I noticed a correlation between late nights and headaches.', NULL, 'Tôi nhận thấy có một mối tương quan giữa việc thức khuya và những cơn đau đầu.', '{"wordId":"correlation","ukIpa":"/ˌkɒrəˈleɪʃən/","usIpa":"/ˌkɔːrəˈleɪʃən/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A relationship in which changes in things are linked","vi":"sự tương quan; mối liên hệ"}],"examples":[{"en":"I noticed a correlation between late nights and headaches.","vi":"Tôi nhận thấy có một mối tương quan giữa việc thức khuya và những cơn đau đầu.","audioKind":"ex"},{"en":"A strong correlation between income and educational achievement does not necessarily mean that wealth directly causes academic success.","vi":"Mối tương quan chặt chẽ giữa thu nhập và thành tích học tập không nhất thiết có nghĩa là sự giàu có trực tiếp mang lại thành công trong học tập.","audioKind":"ex2"}],"collocations":[{"en":"strong correlation","vi":"mối tương quan chặt chẽ"},{"en":"positive correlation","vi":"tương quan thuận"},{"en":"negative correlation","vi":"tương quan nghịch"},{"en":"correlation between","vi":"mối tương quan giữa..."}],"wordFamily":["correlate (v.)","correlated (adj.)","correlational (adj.)"],"synonyms":["association","relationship"],"antonyms":[],"tipVi":"correlation không đồng nghĩa với causation: sự tương quan không đại diện cho nhân quả.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_infinite', 'en-b2-67', 'infinite', '/ˈɪnfɪnət/', 'B2', 'vô hạn; vô tận; vô cùng lớn; cực kỳ nhiều', 'adj.', 'infinity (n.), infinitely (adv.), finite (adj.)', 'Đồng nghĩa: limitless, boundless, endless · Trái nghĩa: finite, limited', 'Thường dùng làm tính từ; để chỉ ''sự vô tận'' thường dùng danh từ infinity.', 'My grandmother seems to have infinite patience with children.', NULL, 'Bà của tôi có vẻ có sự kiên nhẫn vô tận đối với trẻ nhỏ.', '{"wordId":"infinite","ukIpa":"/ˈɪnfɪnət/","usIpa":"/ˈɪnfɪnət/","cefr":"B2","topic":"science","senses":[{"pos":"adj.","en":"Having no end or limit","vi":"vô hạn; vô tận"},{"pos":"adj.","en":"Extremely great in amount or degree","vi":"vô cùng lớn; cực kỳ nhiều"}],"examples":[{"en":"My grandmother seems to have infinite patience with children.","vi":"Bà của tôi có vẻ có sự kiên nhẫn vô tận đối với trẻ nhỏ.","audioKind":"ex"},{"en":"Economic policies should not assume that the planet provides an infinite supply of natural resources.","vi":"Các chính sách kinh tế không nên giả định rằng hành tinh cung cấp một nguồn tài nguyên thiên nhiên vô hạn.","audioKind":"ex2"}],"collocations":[{"en":"infinite possibilities","vi":"khả năng vô hạn"},{"en":"infinite patience","vi":"sự kiên nhẫn vô tận"},{"en":"an infinite supply","vi":"nguồn cung vô hạn"}],"wordFamily":["infinity (n.)","infinitely (adv.)","finite (adj.)"],"synonyms":["limitless","boundless","endless"],"antonyms":["finite","limited"],"tipVi":"Thường dùng làm tính từ; để chỉ ''sự vô tận'' thường dùng danh từ infinity.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vertical', 'en-b2-67', 'vertical', '/ˈvɝːtɪkəl/', 'B2', 'thẳng đứng; vuông góc; đường thẳng đứng; vị trí thẳng đứng', 'adj.', 'vertically (adv.), verticality (n.)', 'Đồng nghĩa: upright · Trái nghĩa: horizontal', 'vertical chỉ hướng thẳng đứng; horizontal chỉ hướng nằm ngang.', 'The curtains have vertical stripes that make the room look taller.', NULL, 'Bộ rèm có các sọc thẳng đứng khiến căn phòng trông cao hơn.', '{"wordId":"vertical","ukIpa":"/ˈvɜːtɪkəl/","usIpa":"/ˈvɝːtɪkəl/","cefr":"B2","topic":"science","senses":[{"pos":"adj.","en":"pointing straight up or down, perpendicular to a horizontal surface","vi":"thẳng đứng; vuông góc"},{"pos":"n.","en":"a vertical line, direction, or position","vi":"đường thẳng đứng; vị trí thẳng đứng"}],"examples":[{"en":"The curtains have vertical stripes that make the room look taller.","vi":"Bộ rèm có các sọc thẳng đứng khiến căn phòng trông cao hơn.","audioKind":"ex"},{"en":"Vertical farming could help cities produce fresh vegetables locally while using less land than conventional agricultural methods.","vi":"Nông nghiệp thẳng đứng có thể giúp các thành phố tự sản xuất rau tươi tại chỗ trong khi sử dụng ít đất hơn so với các phương pháp nông nghiệp truyền thống.","audioKind":"ex2"}],"collocations":[{"en":"a vertical line","vi":"một đường thẳng đứng"},{"en":"vertical stripes","vi":"sọc thẳng đứng"},{"en":"vertical farming","vi":"nông nghiệp thẳng đứng"},{"en":"a vertical axis","vi":"trục tung"}],"wordFamily":["vertically (adv.)","verticality (n.)"],"synonyms":["upright"],"antonyms":["horizontal"],"tipVi":"vertical chỉ hướng thẳng đứng; horizontal chỉ hướng nằm ngang.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_variation', 'en-b2-67', 'variation', '/ˌveriˈeɪʃən/', 'B2', 'sự biến đổi; sự thay đổi; độ lệch; biến thể; bản khác', 'n.', 'vary (v.), variable (adj.), variety (n.), varied (adj.)', 'Đồng nghĩa: difference, fluctuation · Trái nghĩa: uniformity', 'Cụm ''variation in'' dùng để chỉ sự khác biệt ở khía cạnh nào đó; ''variation on'' chỉ một phiên bản biến thể.', 'This soup is a spicy variation on my grandmother''s recipe.', NULL, 'Món súp này là một biến thể cay hơn theo công thức nấu ăn của bà tôi.', '{"wordId":"variation","ukIpa":"/ˌveəriˈeɪʃən/","usIpa":"/ˌveriˈeɪʃən/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A difference or change in amount, level, form, or quality.","vi":"sự biến đổi; sự thay đổi; độ lệch"},{"pos":"n.","en":"A version of something that differs from its usual form.","vi":"biến thể; bản khác"}],"examples":[{"en":"This soup is a spicy variation on my grandmother''s recipe.","vi":"Món súp này là một biến thể cay hơn theo công thức nấu ăn của bà tôi.","audioKind":"ex"},{"en":"Seasonal variation in rainfall can significantly affect agricultural productivity, particularly in regions with limited irrigation infrastructure.","vi":"Sự biến động theo mùa của lượng mưa có thể ảnh hưởng đáng kể đến năng suất nông nghiệp, đặc biệt là ở những vùng có cơ sở hạ tầng tưới tiêu hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"seasonal variation","vi":"sự biến động theo mùa"},{"en":"variation in temperature","vi":"sự thay đổi nhiệt độ"},{"en":"genetic variation","vi":"sự biến dị di truyền"},{"en":"a variation on a theme","vi":"một biến thể của một chủ đề"}],"wordFamily":["vary (v.)","variable (adj.)","variety (n.)","varied (adj.)"],"synonyms":["difference","fluctuation"],"antonyms":["uniformity"],"tipVi":"Cụm ''variation in'' dùng để chỉ sự khác biệt ở khía cạnh nào đó; ''variation on'' chỉ một phiên bản biến thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conduct', 'en-b2-67', 'conduct', '/kənˈdʌkt/', 'B2', 'tổ chức; tiến hành; dẫn (nhiệt, điện); hạnh kiểm; cách ứng xử', 'v.', 'conductor (n.), conductive (adj.), conductivity (n.)', NULL, 'Động từ nhấn trọng âm ở âm tiết sau; danh từ nhấn trọng âm ở âm tiết đầu.', 'Our teacher conducted a quick survey about favourite snacks.', NULL, 'Giáo viên của chúng tôi đã thực hiện một cuộc khảo sát nhanh về các món ăn nhẹ yêu thích.', '{"wordId":"conduct","ukIpa":"/kənˈdʌkt/","usIpa":"/kənˈdʌkt/","cefr":"B2","topic":"science","senses":[{"pos":"v.","en":"to organize and carry out an activity","vi":"tổ chức; tiến hành"},{"pos":"v.","en":"to allow heat or electricity to pass through","vi":"dẫn (nhiệt, điện)"},{"pos":"n.","en":"the way a person behaves, especially towards others","vi":"hạnh kiểm; cách ứng xử"}],"examples":[{"en":"Our teacher conducted a quick survey about favourite snacks.","vi":"Giáo viên của chúng tôi đã thực hiện một cuộc khảo sát nhanh về các món ăn nhẹ yêu thích.","audioKind":"ex"},{"en":"Researchers should conduct thorough trials before recommending new treatments for widespread use in public hospitals.","vi":"Các nhà nghiên cứu nên tiến hành các thử nghiệm kỹ lưỡng trước khi khuyến nghị áp dụng các phương pháp điều trị mới trên diện rộng tại các bệnh viện công.","audioKind":"ex2"}],"collocations":[{"en":"conduct research","vi":"tiến hành nghiên cứu"},{"en":"conduct a survey","vi":"thực hiện khảo sát"},{"en":"conduct electricity","vi":"dẫn điện"},{"en":"code of conduct","vi":"quy tắc ứng xử"}],"wordFamily":["conductor (n.)","conductive (adj.)","conductivity (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ nhấn trọng âm ở âm tiết sau; danh từ nhấn trọng âm ở âm tiết đầu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_existence', 'en-b2-67', 'existence', '/ɪɡˈzɪstəns/', 'B2', 'sự tồn tại; sự có mặt; cuộc sống; lối sống', 'n.', 'exist (v.), existing (adj.), existent (adj.)', 'Trái nghĩa: nonexistence', 'Chỉ "sự tồn tại" thì thường không đếm được; a quiet existence chỉ cuộc sống yên bình.', 'I never knew of this tiny island''s existence.', NULL, 'Tôi chưa bao giờ biết đến sự tồn tại của hòn đảo nhỏ bé này.', '{"wordId":"existence","ukIpa":"/ɪɡˈzɪstəns/","usIpa":"/ɪɡˈzɪstəns/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"the state of being real or present","vi":"sự tồn tại; sự có mặt"},{"pos":"n.","en":"a person''s way of living, especially under particular conditions","vi":"cuộc sống; lối sống"}],"examples":[{"en":"I never knew of this tiny island''s existence.","vi":"Tôi chưa bao giờ biết đến sự tồn tại của hòn đảo nhỏ bé này.","audioKind":"ex"},{"en":"The existence of affordable housing can significantly improve the quality of life in growing cities.","vi":"Sự tồn tại của nhà ở giá rẻ có thể cải thiện đáng kể chất lượng cuộc sống ở các thành phố đang phát triển.","audioKind":"ex2"}],"collocations":[{"en":"come into existence","vi":"ra đời; hình thành"},{"en":"in existence","vi":"hiện có; đang tồn tại"},{"en":"the existence of","vi":"sự tồn tại của"},{"en":"a peaceful existence","vi":"một cuộc sống bình yên"}],"wordFamily":["exist (v.)","existing (adj.)","existent (adj.)"],"synonyms":[],"antonyms":["nonexistence"],"tipVi":"Chỉ \"sự tồn tại\" thì thường không đếm được; a quiet existence chỉ cuộc sống yên bình.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_experimental', 'en-b2-67', 'experimental', '/ɪkˌsperəˈmentəl/', 'B2', 'thuộc về thí nghiệm; dựa trên thí nghiệm; mang tính thử nghiệm', 'adj.', 'experiment (n.), experiment (v.), experimentally (adv.), experimentation (n.)', NULL, 'experimental chỉ tính chất thí nghiệm hoặc thử nghiệm, không có nghĩa là "có kinh nghiệm".', 'We compared the experimental results over lunch today.', NULL, 'Chúng tôi đã so sánh các kết quả thí nghiệm trong bữa trưa hôm nay.', '{"wordId":"experimental","ukIpa":"/ɪkˌsperɪˈmentəl/","usIpa":"/ɪkˌsperəˈmentəl/","cefr":"B2","topic":"science","senses":[{"pos":"adj.","en":"Relating to scientific tests or based on their results","vi":"thuộc về thí nghiệm; dựa trên thí nghiệm"},{"pos":"adj.","en":"Using new ideas or methods whose success is not yet established","vi":"mang tính thử nghiệm"}],"examples":[{"en":"We compared the experimental results over lunch today.","vi":"Chúng tôi đã so sánh các kết quả thí nghiệm trong bữa trưa hôm nay.","audioKind":"ex"},{"en":"Experimental evidence suggests that improved classroom ventilation can help students maintain concentration during longer lessons.","vi":"Bằng chứng thực nghiệm cho thấy việc cải thiện thông gió trong phòng học có thể giúp học sinh duy trì sự tập trung trong các tiết học kéo dài.","audioKind":"ex2"}],"collocations":[{"en":"experimental evidence","vi":"bằng chứng thực nghiệm"},{"en":"experimental design","vi":"thiết kế thí nghiệm"},{"en":"experimental method","vi":"phương pháp thí nghiệm"},{"en":"experimental treatment","vi":"điều trị thử nghiệm"}],"wordFamily":["experiment (n.)","experiment (v.)","experimentally (adv.)","experimentation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"experimental chỉ tính chất thí nghiệm hoặc thử nghiệm, không có nghĩa là \"có kinh nghiệm\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hydrogen', 'en-b2-67', 'hydrogen', '/ˈhaɪdrədʒən/', 'B2', 'khí hydro; nguyên tố hydro', 'n.', NULL, NULL, 'Hydrogen là danh từ không đếm được, dùng để chỉ nguyên tố hóa học hydro hoặc khí hydro.', 'Our science teacher showed us how hydrogen burns.', NULL, 'Giáo viên khoa học đã cho chúng tôi xem cách hydro bốc cháy.', '{"wordId":"hydrogen","ukIpa":"/ˈhaɪdrədʒən/","usIpa":"/ˈhaɪdrədʒən/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"the lightest chemical element, a colourless gas that burns easily","vi":"khí hydro; nguyên tố hydro"}],"examples":[{"en":"Our science teacher showed us how hydrogen burns.","vi":"Giáo viên khoa học đã cho chúng tôi xem cách hydro bốc cháy.","audioKind":"ex"},{"en":"Hydrogen produced using renewable electricity could help reduce emissions from industries that currently depend on fossil fuels.","vi":"Hydro được sản xuất bằng điện tái tạo có thể giúp giảm lượng khí thải từ các ngành công nghiệp hiện đang phụ thuộc vào nhiên liệu hóa thạch.","audioKind":"ex2"}],"collocations":[{"en":"hydrogen fuel","vi":"nhiên liệu hydro"},{"en":"hydrogen gas","vi":"khí hydro"},{"en":"hydrogen fuel cell","vi":"pin nhiên liệu hydro"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Hydrogen là danh từ không đếm được, dùng để chỉ nguyên tố hóa học hydro hoặc khí hydro.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_findings', 'en-b2-67', 'findings', '/ˈfaɪndɪŋz/', 'B2', 'kết quả nghiên cứu; phát hiện từ cuộc điều tra', 'n.', 'find (v.), finding (n.)', 'Đồng nghĩa: results, conclusions', 'Thường dùng ở dạng số nhiều: the findings suggest, động từ đi kèm ở số nhiều.', 'We shared our findings with the rest of the class.', NULL, 'Chúng tôi đã chia sẻ kết quả nghiên cứu của mình với các bạn còn lại trong lớp.', '{"wordId":"findings","ukIpa":"/ˈfaɪndɪŋz/","usIpa":"/ˈfaɪndɪŋz/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"information or conclusions obtained through research or investigation","vi":"kết quả nghiên cứu; phát hiện từ cuộc điều tra"}],"examples":[{"en":"We shared our findings with the rest of the class.","vi":"Chúng tôi đã chia sẻ kết quả nghiên cứu của mình với các bạn còn lại trong lớp.","audioKind":"ex"},{"en":"The findings suggest that access to green spaces is associated with better mental health among urban residents.","vi":"Các phát hiện cho thấy việc tiếp cận không gian xanh có liên quan đến sức khỏe tinh thần tốt hơn ở cư dân thành thị.","audioKind":"ex2"}],"collocations":[{"en":"research findings","vi":"kết quả nghiên cứu"},{"en":"key findings","vi":"phát hiện quan trọng"},{"en":"publish findings","vi":"công bố kết quả"},{"en":"preliminary findings","vi":"kết quả sơ bộ"}],"wordFamily":["find (v.)","finding (n.)"],"synonyms":["results","conclusions"],"antonyms":[],"tipVi":"Thường dùng ở dạng số nhiều: the findings suggest, động từ đi kèm ở số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_evaporate', 'en-b2-67', 'evaporate', '/ɪˈvæpəreɪt/', 'B2', 'bay hơi; làm bay hơi; tiêu tan; biến mất dần', 'v.', 'evaporation (n.), evaporative (adj.)', 'Đồng nghĩa: vaporise, disappear · Trái nghĩa: condense', 'Quá trình bay hơi không nhất thiết phải đạt điểm sôi; evaporate còn được dùng theo nghĩa bóng chỉ sự tiêu tan của hy vọng.', 'The puddles evaporated quickly in the warm afternoon sun.', NULL, 'Những vũng nước nhanh chóng bốc hơi dưới ánh nắng ấm áp buổi chiều.', '{"wordId":"evaporate","ukIpa":"/ɪˈvæpəreɪt/","usIpa":"/ɪˈvæpəreɪt/","cefr":"B2","topic":"science","senses":[{"pos":"v.","en":"to change from liquid into gas, or cause this change","vi":"bay hơi; làm bay hơi"},{"pos":"v.","en":"to disappear, especially gradually","vi":"tiêu tan; biến mất dần"}],"examples":[{"en":"The puddles evaporated quickly in the warm afternoon sun.","vi":"Những vũng nước nhanh chóng bốc hơi dưới ánh nắng ấm áp buổi chiều.","audioKind":"ex"},{"en":"As temperatures rise, water evaporates more rapidly from reservoirs, increasing pressure on supplies in drought-prone regions.","vi":"Khi nhiệt độ gia tăng, nước trong các hồ chứa bay hơi nhanh hơn, gây áp lực lớn hơn lên nguồn cung nước tại các vùng dễ xảy ra hạn hán.","audioKind":"ex2"}],"collocations":[{"en":"water evaporates","vi":"nước bay hơi"},{"en":"evaporate rapidly","vi":"bốc hơi nhanh chóng"},{"en":"moisture evaporates","vi":"độ ẩm bay hơi"},{"en":"hopes evaporate","vi":"hy vọng tan biến"}],"wordFamily":["evaporation (n.)","evaporative (adj.)"],"synonyms":["vaporise","disappear"],"antonyms":["condense"],"tipVi":"Quá trình bay hơi không nhất thiết phải đạt điểm sôi; evaporate còn được dùng theo nghĩa bóng chỉ sự tiêu tan của hy vọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_uncover', 'en-b2-67', 'uncover', '/ʌnˈkʌvər/', 'B2', 'phát hiện; khám phá; vạch trần; mở nắp; tháo lớp che phủ', 'v.', 'cover (v.), uncovered (adj.)', 'Đồng nghĩa: reveal, discover, expose · Trái nghĩa: conceal, cover', 'Có thể dùng theo nghĩa đen là tháo lớp phủ vật lý hoặc nghĩa bóng là khám phá sự thật ẩn giấu.', 'Our kitchen repairs helped uncover a hidden water leak.', NULL, 'Việc sửa chữa nhà bếp giúp chúng tôi phát hiện ra một chỗ rò rỉ nước ngầm.', '{"wordId":"uncover","ukIpa":"/ʌnˈkʌvə/","usIpa":"/ʌnˈkʌvər/","cefr":"B2","topic":"science","senses":[{"pos":"v.","en":"to discover something previously hidden or unknown","vi":"phát hiện; khám phá; vạch trần"},{"pos":"v.","en":"to remove something covering an object or surface","vi":"mở nắp; tháo lớp che phủ"}],"examples":[{"en":"Our kitchen repairs helped uncover a hidden water leak.","vi":"Việc sửa chữa nhà bếp giúp chúng tôi phát hiện ra một chỗ rò rỉ nước ngầm.","audioKind":"ex"},{"en":"Independent research can uncover environmental risks that are overlooked during the early stages of industrial development.","vi":"Nghiên cứu độc lập có thể vạch trần những rủi ro môi trường thường bị bỏ qua trong giai đoạn đầu phát triển công nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"uncover evidence","vi":"tìm ra bằng chứng"},{"en":"uncover the truth","vi":"vạch trần sự thật"},{"en":"uncover a problem","vi":"phát hiện vấn đề"}],"wordFamily":["cover (v.)","uncovered (adj.)"],"synonyms":["reveal","discover","expose"],"antonyms":["conceal","cover"],"tipVi":"Có thể dùng theo nghĩa đen là tháo lớp phủ vật lý hoặc nghĩa bóng là khám phá sự thật ẩn giấu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_skeleton', 'en-b2-67', 'skeleton', '/ˈskelɪtən/', 'B2', 'bộ xương; khung xương; khung cơ bản; dàn ý', 'n.', 'skeletal (adj.)', NULL, 'Cụm skeleton staff dùng để chỉ số lượng nhân viên ít nhất đủ để duy trì hoạt động.', 'We saw a huge dinosaur skeleton at the museum.', NULL, 'Chúng tôi đã nhìn thấy một bộ xương khủng long khổng lồ trong bảo tàng.', '{"wordId":"skeleton","ukIpa":"/ˈskelɪtən/","usIpa":"/ˈskelɪtən/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"The framework of bones supporting a human or animal body.","vi":"bộ xương; khung xương"},{"pos":"n.","en":"A basic structure to which more details can be added.","vi":"khung cơ bản; dàn ý"}],"examples":[{"en":"We saw a huge dinosaur skeleton at the museum.","vi":"Chúng tôi đã nhìn thấy một bộ xương khủng long khổng lồ trong bảo tàng.","audioKind":"ex"},{"en":"Studying the skeleton of an ancient animal can reveal how it moved and adapted to its environment.","vi":"Việc nghiên cứu bộ xương của một loài động vật cổ đại có thể tiết lộ cách chúng di chuyển và thích nghi với môi trường sống.","audioKind":"ex2"}],"collocations":[{"en":"human skeleton","vi":"bộ xương người"},{"en":"dinosaur skeleton","vi":"bộ xương khủng long"},{"en":"skeleton staff","vi":"đội ngũ nhân sự tối thiểu"}],"wordFamily":["skeletal (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm skeleton staff dùng để chỉ số lượng nhân viên ít nhất đủ để duy trì hoạt động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_accuracy', 'en-b2-67', 'accuracy', '/ˈækjərəsi/', 'B2', 'tính chính xác; độ chính xác', 'n.', 'accurate (adj.), accurately (adv.), inaccurate (adj.), inaccuracy (n.)', 'Đồng nghĩa: correctness · Trái nghĩa: inaccuracy', 'Thường là danh từ không đếm được; tính từ là accurate.', 'Please check the accuracy of these measurements before cutting.', NULL, 'Vui lòng kiểm tra độ chính xác của các số đo này trước khi cắt.', '{"wordId":"accuracy","ukIpa":"/ˈækjərəsi/","usIpa":"/ˈækjərəsi/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"the quality of being correct or free from errors","vi":"tính chính xác; độ chính xác"}],"examples":[{"en":"Please check the accuracy of these measurements before cutting.","vi":"Vui lòng kiểm tra độ chính xác của các số đo này trước khi cắt.","audioKind":"ex"},{"en":"The accuracy of climate predictions depends partly on the quality of data collected over long periods.","vi":"Độ chính xác của các dự báo khí hậu phụ thuộc một phần vào chất lượng dữ liệu được thu thập trong thời gian dài.","audioKind":"ex2"}],"collocations":[{"en":"check the accuracy of","vi":"kiểm tra tính chính xác của"},{"en":"improve accuracy","vi":"nâng cao độ chính xác"},{"en":"a high degree of accuracy","vi":"độ chính xác cao"},{"en":"historical accuracy","vi":"tính chính xác về mặt lịch sử"}],"wordFamily":["accurate (adj.)","accurately (adv.)","inaccurate (adj.)","inaccuracy (n.)"],"synonyms":["correctness"],"antonyms":["inaccuracy"],"tipVi":"Thường là danh từ không đếm được; tính từ là accurate.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rotate', 'en-b2-67', 'rotate', '/ˈroʊteɪt/', 'B2', 'xoay quanh; quay; luân phiên; thay phiên', 'v.', 'rotation (n.), rotational (adj.)', 'Đồng nghĩa: turn, revolve', 'Từ này vừa có thể dùng như ngoại động từ lẫn nội động từ: rotate the wheel; the wheel rotates.', 'Rotate the pot so each side gets some sunlight.', NULL, 'Xoay chậu cây để mỗi bên đều có thể nhận được ánh nắng mặt trời.', '{"wordId":"rotate","ukIpa":"/rəʊˈteɪt/","usIpa":"/ˈroʊteɪt/","cefr":"B2","topic":"science","senses":[{"pos":"v.","en":"to turn around a central point or axis","vi":"xoay quanh; quay"},{"pos":"v.","en":"to change positions or duties in a regular order","vi":"luân phiên; thay phiên"}],"examples":[{"en":"Rotate the pot so each side gets some sunlight.","vi":"Xoay chậu cây để mỗi bên đều có thể nhận được ánh nắng mặt trời.","audioKind":"ex"},{"en":"Some hospitals rotate staff between departments to broaden their experience and improve cooperation across medical teams.","vi":"Một số bệnh viện phân công nhân viên luân phiên giữa các khoa để mở rộng kinh nghiệm và cải thiện sự hợp tác giữa các đội ngũ y tế.","audioKind":"ex2"}],"collocations":[{"en":"rotate clockwise","vi":"xoay theo chiều kim đồng hồ"},{"en":"rotate crops","vi":"luân canh cây trồng"},{"en":"rotate duties","vi":"luân phiên nhiệm vụ"}],"wordFamily":["rotation (n.)","rotational (adj.)"],"synonyms":["turn","revolve"],"antonyms":[],"tipVi":"Từ này vừa có thể dùng như ngoại động từ lẫn nội động từ: rotate the wheel; the wheel rotates.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_motion', 'en-b2-67', 'motion', '/ˈmoʊʃən/', 'B2', 'sự chuyển động; sự di chuyển; đề xuất; kiến nghị; ra hiệu; ra dấu', 'n.', 'motionless (adj.)', NULL, 'Đề xuất chính thức có thể dùng động từ pass hoặc reject; in motion nghĩa là đang chuyển động.', 'The gentle motion of the boat made me sleepy.', NULL, 'Chuyển động nhẹ nhàng của chiếc thuyền làm tôi thấy buồn ngủ.', '{"wordId":"motion","ukIpa":"/ˈməʊʃən/","usIpa":"/ˈmoʊʃən/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"the act or process of moving","vi":"sự chuyển động; sự di chuyển"},{"pos":"n.","en":"a formal proposal discussed and voted on at a meeting","vi":"đề xuất; kiến nghị"},{"pos":"v.","en":"to signal something using a movement of your hand or head","vi":"ra hiệu; ra dấu"}],"examples":[{"en":"The gentle motion of the boat made me sleepy.","vi":"Chuyển động nhẹ nhàng của chiếc thuyền làm tôi thấy buồn ngủ.","audioKind":"ex"},{"en":"The council passed a motion to improve public transport and reduce traffic in residential areas.","vi":"Hội đồng đã thông qua một kiến nghị nhằm cải thiện giao thông công cộng và giảm lượng xe cộ ở các khu dân cư.","audioKind":"ex2"}],"collocations":[{"en":"in motion","vi":"đang chuyển động"},{"en":"set in motion","vi":"làm cho chuyển động"},{"en":"pass a motion","vi":"thông qua một kiến nghị"},{"en":"motion to someone","vi":"ra hiệu cho ai đó"}],"wordFamily":["motionless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Đề xuất chính thức có thể dùng động từ pass hoặc reject; in motion nghĩa là đang chuyển động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_diameter', 'en-b2-67', 'diameter', '/daɪˈæmɪtər/', 'B2', 'đường kính', 'n.', NULL, NULL, 'Đường kính là diameter, bán kính là radius; sau số đo kích thước thường dùng in diameter.', 'The round cake measures thirty centimetres in diameter.', NULL, 'Chiếc bánh tròn có đường kính dài ba mươi centimet.', '{"wordId":"diameter","ukIpa":"/daɪˈæmɪtə/","usIpa":"/daɪˈæmɪtər/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"a straight line through a circle''s centre joining opposite edges","vi":"đường kính"}],"examples":[{"en":"The round cake measures thirty centimetres in diameter.","vi":"Chiếc bánh tròn có đường kính dài ba mươi centimet.","audioKind":"ex"},{"en":"Engineers must calculate the diameter of water pipes carefully to ensure an adequate supply to growing cities.","vi":"Các kỹ sư phải tính toán đường kính ống nước thật cẩn thận để đảm bảo nguồn cung cấp đầy đủ cho các đô thị đang mở rộng.","audioKind":"ex2"}],"collocations":[{"en":"in diameter","vi":"có đường kính là"},{"en":"measure the diameter","vi":"đo đường kính"},{"en":"internal diameter","vi":"đường kính trong"},{"en":"external diameter","vi":"đường kính ngoài"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Đường kính là diameter, bán kính là radius; sau số đo kích thước thường dùng in diameter.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_radiation', 'en-b2-67', 'radiation', '/ˌreɪdiˈeɪʃən/', 'B2', 'bức xạ; tia bức xạ; liệu pháp phóng xạ; xạ trị', 'n.', 'radiate (v.), radioactive (adj.), radioactivity (n.)', NULL, 'Từ radiation thường không đếm được; bức xạ không chỉ ám chỉ bức xạ hạt nhân mà còn bao gồm cả ánh sáng mặt trời.', 'This special glass blocks much of the sun''s ultraviolet radiation.', NULL, 'Loại kính đặc biệt này chắn phần lớn tia cực tím từ mặt trời.', '{"wordId":"radiation","ukIpa":"/ˌreɪdiˈeɪʃən/","usIpa":"/ˌreɪdiˈeɪʃən/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"Energy travelling through space or matter as waves or particles.","vi":"bức xạ; tia bức xạ"},{"pos":"n.","en":"Medical treatment using radiation to destroy cancer cells.","vi":"liệu pháp phóng xạ; xạ trị"}],"examples":[{"en":"This special glass blocks much of the sun''s ultraviolet radiation.","vi":"Loại kính đặc biệt này chắn phần lớn tia cực tím từ mặt trời.","audioKind":"ex"},{"en":"Workers in nuclear facilities require protective equipment and regular monitoring to limit their exposure to radiation.","vi":"Nhân viên làm việc tại các cơ sở hạt nhân cần có thiết bị bảo hộ và được theo dõi thường xuyên để hạn chế mức độ phơi nhiễm bức xạ.","audioKind":"ex2"}],"collocations":[{"en":"ultraviolet radiation","vi":"bức xạ cực tím"},{"en":"exposure to radiation","vi":"phơi nhiễm bức xạ"},{"en":"radiation therapy","vi":"liệu pháp xạ trị"},{"en":"solar radiation","vi":"bức xạ mặt trời"}],"wordFamily":["radiate (v.)","radioactive (adj.)","radioactivity (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ radiation thường không đếm được; bức xạ không chỉ ám chỉ bức xạ hạt nhân mà còn bao gồm cả ánh sáng mặt trời.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_volt', 'en-b2-67', 'volt', '/voʊlt/', 'B2', 'vôn (đơn vị đo hiệu điện thế)', 'n.', 'voltage (n.)', NULL, 'Vôn (volt) đo hiệu điện thế; trong khi oát (watt) đo công suất.', 'This small battery supplies just one and a half volts.', NULL, 'Viên pin nhỏ này chỉ cung cấp đúng một vôn rưỡi.', '{"wordId":"volt","ukIpa":"/vəʊlt/","usIpa":"/voʊlt/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A unit used to measure electrical potential difference","vi":"vôn (đơn vị đo hiệu điện thế)"}],"examples":[{"en":"This small battery supplies just one and a half volts.","vi":"Viên pin nhỏ này chỉ cung cấp đúng một vôn rưỡi.","audioKind":"ex"},{"en":"Engineers measure electrical potential difference in volts when designing safe and efficient systems for homes and factories.","vi":"Các kỹ sư đo lường hiệu điện thế bằng vôn khi thiết kế các hệ thống an toàn và hiệu quả cho nhà ở và nhà máy.","audioKind":"ex2"}],"collocations":[{"en":"measure in volts","vi":"đo bằng vôn"},{"en":"a twelve-volt battery","vi":"pin mười hai vôn"},{"en":"a voltage of five volts","vi":"hiệu điện thế năm vôn"}],"wordFamily":["voltage (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Vôn (volt) đo hiệu điện thế; trong khi oát (watt) đo công suất.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_horizontal', 'en-b2-67', 'horizontal', '/ˌhɔːrɪˈzɑːntəl/', 'B2', 'nằm ngang; song song với mặt đất', 'adj.', 'horizontally (adv.)', 'Đồng nghĩa: level · Trái nghĩa: vertical', 'horizontal có nghĩa là nằm ngang, trái ngược với vertical có nghĩa là theo chiều dọc.', 'Keep the shelf horizontal while I tighten the screws.', NULL, 'Hãy giữ cho chiếc kệ nằm ngang trong lúc tôi siết chặt các con ốc.', '{"wordId":"horizontal","ukIpa":"/ˌhɒrɪˈzɒntəl/","usIpa":"/ˌhɔːrɪˈzɑːntəl/","cefr":"B2","topic":"science","senses":[{"pos":"adj.","en":"Flat or level, running parallel to the ground","vi":"nằm ngang; song song với mặt đất"}],"examples":[{"en":"Keep the shelf horizontal while I tighten the screws.","vi":"Hãy giữ cho chiếc kệ nằm ngang trong lúc tôi siết chặt các con ốc.","audioKind":"ex"},{"en":"The horizontal axis shows time, allowing readers to compare changes in employment across the period.","vi":"Trục hoành biểu thị thời gian, giúp người đọc dễ dàng so sánh các sự thay đổi về việc làm trong suốt khoảng thời gian đó.","audioKind":"ex2"}],"collocations":[{"en":"horizontal axis","vi":"trục hoành"},{"en":"horizontal line","vi":"đường ngang"},{"en":"horizontal position","vi":"vị trí nằm ngang"}],"wordFamily":["horizontally (adv.)"],"synonyms":["level"],"antonyms":["vertical"],"tipVi":"horizontal có nghĩa là nằm ngang, trái ngược với vertical có nghĩa là theo chiều dọc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_microscope', 'en-b2-67', 'microscope', '/ˈmaɪkrəskoʊp/', 'B2', 'danh từ: kính hiển vi', 'n.', 'microscopic (adj.), microscopy (n.), microscopically (adv.)', NULL, 'microscope dùng để xem các vật thể vi mô; telescope dùng để xem các vật ở xa.', 'We examined a drop of pond water under the microscope.', NULL, 'Chúng tôi đã kiểm tra một giọt nước ao dưới kính hiển vi.', '{"wordId":"microscope","ukIpa":"/ˈmaɪkrəskəʊp/","usIpa":"/ˈmaɪkrəskoʊp/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"An instrument that makes very small objects appear much larger.","vi":"danh từ: kính hiển vi"}],"examples":[{"en":"We examined a drop of pond water under the microscope.","vi":"Chúng tôi đã kiểm tra một giọt nước ao dưới kính hiển vi.","audioKind":"ex"},{"en":"Using a microscope allows students to observe cell structures that are invisible to the naked eye.","vi":"Sử dụng kính hiển vi giúp học sinh quan sát được các cấu trúc tế bào mà mắt thường không thể nhìn thấy.","audioKind":"ex2"}],"collocations":[{"en":"under a microscope","vi":"dưới kính hiển vi"},{"en":"electron microscope","vi":"kính hiển vi điện tử"},{"en":"light microscope","vi":"kính hiển vi quang học"}],"wordFamily":["microscopic (adj.)","microscopy (n.)","microscopically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"microscope dùng để xem các vật thể vi mô; telescope dùng để xem các vật ở xa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_67_1', 'en-b2-67', 'Cách dùng “evaporate” (v.) — bay hơi; làm bay hơi', 'water evaporates  ·  evaporate rapidly  ·  moisture evaporates', 'Quá trình bay hơi không nhất thiết phải đạt điểm sôi; evaporate còn được dùng theo nghĩa bóng chỉ sự tiêu tan của hy vọng.', 'Họ từ (Word Family): evaporation (n.), evaporative (adj.) | Đồng nghĩa: vaporise, disappear · Trái nghĩa: condense', '[{"hanzi":"The puddles evaporated quickly in the warm afternoon sun.","pinyin":"","meaning":"Những vũng nước nhanh chóng bốc hơi dưới ánh nắng ấm áp buổi chiều."},{"hanzi":"As temperatures rise, water evaporates more rapidly from reservoirs, increasing pressure on supplies in drought-prone regions.","pinyin":"","meaning":"Khi nhiệt độ gia tăng, nước trong các hồ chứa bay hơi nhanh hơn, gây áp lực lớn hơn lên nguồn cung nước tại các vùng dễ xảy ra hạn hán."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_67_2', 'en-b2-67', 'Cách dùng “radiation” (n.) — bức xạ; tia bức xạ', 'ultraviolet radiation  ·  exposure to radiation  ·  radiation therapy', 'Từ radiation thường không đếm được; bức xạ không chỉ ám chỉ bức xạ hạt nhân mà còn bao gồm cả ánh sáng mặt trời.', 'Họ từ (Word Family): radiate (v.), radioactive (adj.), radioactivity (n.)', '[{"hanzi":"This special glass blocks much of the sun''s ultraviolet radiation.","pinyin":"","meaning":"Loại kính đặc biệt này chắn phần lớn tia cực tím từ mặt trời."},{"hanzi":"Workers in nuclear facilities require protective equipment and regular monitoring to limit their exposure to radiation.","pinyin":"","meaning":"Nhân viên làm việc tại các cơ sở hạt nhân cần có thiết bị bảo hộ và được theo dõi thường xuyên để hạn chế mức độ phơi nhiễm bức xạ."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_67_3', 'en-b2-67', 'Cách dùng “variation” (n.) — sự biến đổi; sự thay đổi; độ lệch', 'seasonal variation  ·  variation in temperature  ·  genetic variation', 'Cụm ''variation in'' dùng để chỉ sự khác biệt ở khía cạnh nào đó; ''variation on'' chỉ một phiên bản biến thể.', 'Họ từ (Word Family): vary (v.), variable (adj.), variety (n.), varied (adj.) | Đồng nghĩa: difference, fluctuation · Trái nghĩa: uniformity', '[{"hanzi":"This soup is a spicy variation on my grandmother''s recipe.","pinyin":"","meaning":"Món súp này là một biến thể cay hơn theo công thức nấu ăn của bà tôi."},{"hanzi":"Seasonal variation in rainfall can significantly affect agricultural productivity, particularly in regions with limited irrigation infrastructure.","pinyin":"","meaning":"Sự biến động theo mùa của lượng mưa có thể ảnh hưởng đáng kể đến năng suất nông nghiệp, đặc biệt là ở những vùng có cơ sở hạ tầng tưới tiêu hạn chế."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_67_4', 'en-b2-67', 'Cách dùng “uncover” (v.) — phát hiện; khám phá; vạch trần', 'uncover evidence  ·  uncover the truth  ·  uncover a problem', 'Có thể dùng theo nghĩa đen là tháo lớp phủ vật lý hoặc nghĩa bóng là khám phá sự thật ẩn giấu.', 'Họ từ (Word Family): cover (v.), uncovered (adj.) | Đồng nghĩa: reveal, discover, expose · Trái nghĩa: conceal, cover', '[{"hanzi":"Our kitchen repairs helped uncover a hidden water leak.","pinyin":"","meaning":"Việc sửa chữa nhà bếp giúp chúng tôi phát hiện ra một chỗ rò rỉ nước ngầm."},{"hanzi":"Independent research can uncover environmental risks that are overlooked during the early stages of industrial development.","pinyin":"","meaning":"Nghiên cứu độc lập có thể vạch trần những rủi ro môi trường thường bị bỏ qua trong giai đoạn đầu phát triển công nghiệp."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_67_1', 'en-b2-67', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_67_1_1', 'ten_b2_67_1', 'forecast', 'The weather forecast says we should expect snow tonight.', 'The weather forecast says we should expect snow tonight.', '/ˈfɔːrkæst/', 'Dự báo thời tiết nói rằng tối nay có thể sẽ có tuyết.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_67_1_2', 'ten_b2_67_1', 'psychology', 'My sister studies psychology and hopes to help children.', 'My sister studies psychology and hopes to help children.', '/saɪˈkɑːlədʒi/', 'Chị gái tôi học tâm lý học và hy vọng có thể giúp đỡ trẻ em.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_67_1_3', 'ten_b2_67_1', 'crystal', 'We examined a salt crystal under the classroom microscope.', 'We examined a salt crystal under the classroom microscope.', '/ˈkrɪstəl/', 'Chúng tôi đã quan sát một tinh thể muối dưới kính hiển vi của lớp học.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_67_1_4', 'ten_b2_67_1', 'cubic', 'Our new water tank holds two cubic metres.', 'Our new water tank holds two cubic metres.', '/ˈkjuːbɪk/', 'Bồn chứa nước mới của chúng tôi có sức chứa hai mét khối.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_67_1_5', 'ten_b2_67_1', 'astronomer', 'The astronomer adjusted her telescope beneath the clear night sky.', 'The astronomer adjusted her telescope beneath the clear night sky.', '/əˈstrɑːnəmɚ/', 'Nhà thiên văn học đã điều chỉnh kính viễn vọng của cô ấy dưới bầu trời đêm quang đãng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_67_1_6', 'ten_b2_67_1', 'correlation', 'I noticed a correlation between late nights and headaches.', 'I noticed a correlation between late nights and headaches.', '/ˌkɔːrəˈleɪʃən/', 'Tôi nhận thấy có một mối tương quan giữa việc thức khuya và những cơn đau đầu.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_67_1_7', 'ten_b2_67_1', 'infinite', 'My grandmother seems to have infinite patience with children.', 'My grandmother seems to have infinite patience with children.', '/ˈɪnfɪnət/', 'Bà của tôi có vẻ có sự kiên nhẫn vô tận đối với trẻ nhỏ.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_67_1_8', 'ten_b2_67_1', 'vertical', 'The curtains have vertical stripes that make the room look taller.', 'The curtains have vertical stripes that make the room look taller.', '/ˈvɝːtɪkəl/', 'Bộ rèm có các sọc thẳng đứng khiến căn phòng trông cao hơn.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_67_1_1', 'en-b2-67', 'ten_b2_67_1', 'listening', 'listening', 'The weather forecast says we should expect snow tonight.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chuyển động nhẹ nhàng của chiếc thuyền làm tôi thấy buồn ngủ.","Hãy giữ cho chiếc kệ nằm ngang trong lúc tôi siết chặt các con ốc.","Dự báo thời tiết nói rằng tối nay có thể sẽ có tuyết.","Xoay chậu cây để mỗi bên đều có thể nhận được ánh nắng mặt trời."]'::jsonb, 2, 'The weather forecast says we should expect snow tonight. → Dự báo thời tiết nói rằng tối nay có thể sẽ có tuyết.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_67_1_2', 'en-b2-67', 'ten_b2_67_1', 'listening', 'listening', 'My sister studies psychology and hopes to help children.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chị gái tôi học tâm lý học và hy vọng có thể giúp đỡ trẻ em.","Chiếc bánh tròn có đường kính dài ba mươi centimet.","Bộ rèm có các sọc thẳng đứng khiến căn phòng trông cao hơn.","Giáo viên khoa học đã cho chúng tôi xem cách hydro bốc cháy."]'::jsonb, 0, 'My sister studies psychology and hopes to help children. → Chị gái tôi học tâm lý học và hy vọng có thể giúp đỡ trẻ em.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_67_1_3', 'en-b2-67', 'ten_b2_67_1', 'listening', 'listening', 'We examined a salt crystal under the classroom microscope.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Giáo viên khoa học đã cho chúng tôi xem cách hydro bốc cháy.","Chúng tôi đã quan sát một tinh thể muối dưới kính hiển vi của lớp học.","Chúng tôi đã nhìn thấy một bộ xương khủng long khổng lồ trong bảo tàng.","Loại kính đặc biệt này chắn phần lớn tia cực tím từ mặt trời."]'::jsonb, 1, 'We examined a salt crystal under the classroom microscope. → Chúng tôi đã quan sát một tinh thể muối dưới kính hiển vi của lớp học.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_67_2', 'en-b2-67', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_67_2_1', 'ten_b2_67_2', 'forecast', 'Economists forecast slower growth next year as rising energy costs place greater pressure on businesses.', 'Economists forecast slower growth next year as rising energy costs place greater pressure on businesses.', '/ˈfɔːrkæst/', 'Các nhà kinh tế dự báo tăng trưởng sẽ chậm lại vào năm tới khi chi phí năng lượng tăng cao gây áp lực lớn hơn lên các doanh nghiệp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_67_2_2', 'ten_b2_67_2', 'psychology', 'Research in psychology suggests that regular social interaction can support emotional wellbeing among older adults.', 'Research in psychology suggests that regular social interaction can support emotional wellbeing among older adults.', '/saɪˈkɑːlədʒi/', 'Nghiên cứu trong ngành tâm lý học cho thấy việc tương tác xã hội thường xuyên có thể hỗ trợ sức khỏe tinh thần ở người lớn tuổi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_67_2_3', 'ten_b2_67_2', 'crystal', 'The structure of a crystal influences its physical properties and determines its suitability for various industrial applications.', 'The structure of a crystal influences its physical properties and determines its suitability for various industrial applications.', '/ˈkrɪstəl/', 'Cấu trúc của một tinh thể ảnh hưởng đến các tính chất vật lý của nó và quyết định độ phù hợp của nó đối với các ứng dụng công nghiệp khác nhau.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_67_2_4', 'ten_b2_67_2', 'cubic', 'Modern irrigation systems can save thousands of cubic metres of water each year.', 'Modern irrigation systems can save thousands of cubic metres of water each year.', '/ˈkjuːbɪk/', 'Các hệ thống tưới tiêu hiện đại có thể tiết kiệm hàng ngàn mét khối nước mỗi năm.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_67_2_5', 'ten_b2_67_2', 'astronomer', 'Astronomers use powerful telescopes to investigate distant galaxies and improve our understanding of how the universe developed.', 'Astronomers use powerful telescopes to investigate distant galaxies and improve our understanding of how the universe developed.', '/əˈstrɑːnəmɚ/', 'Các nhà thiên văn học sử dụng kính viễn vọng công suất lớn để nghiên cứu các thiên hà xa xôi và nâng cao sự hiểu biết của chúng ta về sự hình thành của vũ trụ.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_67_2_6', 'ten_b2_67_2', 'correlation', 'A strong correlation between income and educational achievement does not necessarily mean that wealth directly causes academic success.', 'A strong correlation between income and educational achievement does not necessarily mean that wealth directly causes academic success.', '/ˌkɔːrəˈleɪʃən/', 'Mối tương quan chặt chẽ giữa thu nhập và thành tích học tập không nhất thiết có nghĩa là sự giàu có trực tiếp mang lại thành công trong học tập.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_67_2_1', 'en-b2-67', 'ten_b2_67_2', 'listening', 'listening', 'Economists forecast slower growth next year as rising energy costs place greater pressure on businesses.', NULL, 'Trong câu vừa nghe, từ “forecast” mang nghĩa nào sau đây?', '["nút thắt; mối buộc","sự dự báo; bản dự báo","thường dân; người không thuộc lực lượng vũ trang","mặt hạn chế; điểm bất lợi"]'::jsonb, 1, '“forecast” (/ˈfɔːrkæst/): sự dự báo; bản dự báo. Câu đầy đủ: Economists forecast slower growth next year as rising energy costs place greater pressure on businesses.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_67_2_2', 'en-b2-67', 'ten_b2_67_2', 'listening', 'listening', 'Research in psychology suggests that regular social interaction can support emotional wellbeing among older adults.', NULL, 'Trong câu vừa nghe, từ “psychology” mang nghĩa nào sau đây?', '["phục vụ; đáp ứng nhu cầu","quầy hàng; sạp hàng","tâm lý học","hầu như; gần như hoàn toàn"]'::jsonb, 2, '“psychology” (/saɪˈkɑːlədʒi/): tâm lý học. Câu đầy đủ: Research in psychology suggests that regular social interaction can support emotional wellbeing among older adults.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
