INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_67_3', 'en-b2-67', 'We examined a salt crystal under the classroom microscope', 'Chúng tôi đã quan sát một tinh thể muối dưới kính hiển vi của lớp học.', 'crystal /ˈkrɪstəl/', '["a","under","salt","the","We","classroom","crystal","examined","microscope"]'::jsonb, NULL, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
