INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_67_5', 'en-b2-67', 'The astronomer adjusted her telescope beneath the clear night sky', 'Nhà thiên văn học đã điều chỉnh kính viễn vọng của cô ấy dưới bầu trời đêm quang đãng.', 'astronomer /əˈstrɑːnəmɚ/', '["sky","The","telescope","adjusted","night","her","the","beneath","clear","astronomer"]'::jsonb, NULL, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_67_6', 'en-b2-67', 'I noticed a correlation between late nights and headaches', 'Tôi nhận thấy có một mối tương quan giữa việc thức khuya và những cơn đau đầu.', 'correlation /ˌkɔːrəˈleɪʃən/', '["headaches","and","late","noticed","nights","a","between","correlation","I"]'::jsonb, NULL, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_67_7', 'en-b2-67', 'My grandmother seems to have infinite patience with children', 'Bà của tôi có vẻ có sự kiên nhẫn vô tận đối với trẻ nhỏ.', 'infinite /ˈɪnfɪnət/', '["patience","to","seems","have","grandmother","My","children","infinite","with"]'::jsonb, NULL, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
