INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_67_1', 'en-b2-67', NULL, 'comprehensive_test', 'listening', 'forecast', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["xé rách; làm rách","mảnh vụn; mảnh vỡ; đoạn","sự dự báo; bản dự báo","xoay quanh; quay"]'::jsonb, 2, 'forecast (/ˈfɔːrkæst/) → sự dự báo; bản dự báo; dự báo; dự đoán', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_67_2', 'en-b2-67', NULL, 'comprehensive_test', 'listening', 'My sister studies psychology and hopes to help children.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chiếc bánh tròn có đường kính dài ba mươi centimet.","Giáo viên của chúng tôi đã thực hiện một cuộc khảo sát nhanh về các món ăn nhẹ yêu thích.","Chúng tôi đã kiểm tra một giọt nước ao dưới kính hiển vi.","Chị gái tôi học tâm lý học và hy vọng có thể giúp đỡ trẻ em."]'::jsonb, 3, 'My sister studies psychology and hopes to help children. → Chị gái tôi học tâm lý học và hy vọng có thể giúp đỡ trẻ em.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_67_3', 'en-b2-67', NULL, 'comprehensive_test', 'listening', 'crystal', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đảo ngược, đổi chiều, lùi xe","thay đổi thất thường; dễ thay đổi","cá tuyết; thịt cá tuyết","tinh thể"]'::jsonb, 3, 'crystal (/ˈkrɪstəl/) → tinh thể; thạch anh; thủy tinh cao cấp; đồ bằng thủy tinh pha lê', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_67_4', 'en-b2-67', NULL, 'comprehensive_test', 'listening', 'Our new water tank holds two cubic metres.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã kiểm tra một giọt nước ao dưới kính hiển vi.","Chị gái tôi học tâm lý học và hy vọng có thể giúp đỡ trẻ em.","Bồn chứa nước mới của chúng tôi có sức chứa hai mét khối.","Chúng tôi đã nhìn thấy một bộ xương khủng long khổng lồ trong bảo tàng."]'::jsonb, 2, 'Our new water tank holds two cubic metres. → Bồn chứa nước mới của chúng tôi có sức chứa hai mét khối.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_67_5', 'en-b2-67', NULL, 'comprehensive_test', 'listening', 'astronomer', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nhà thiên văn học","bãi rác; bãi chôn lấp rác","sự thiền định; tĩnh tâm","ám chỉ; ngụ ý"]'::jsonb, 0, 'astronomer (/əˈstrɑːnəmɚ/) → nhà thiên văn học', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_67_6', 'en-b2-67', NULL, 'comprehensive_test', 'listening', 'I noticed a correlation between late nights and headaches.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã chia sẻ kết quả nghiên cứu của mình với các bạn còn lại trong lớp.","Chiếc bánh tròn có đường kính dài ba mươi centimet.","Hãy giữ cho chiếc kệ nằm ngang trong lúc tôi siết chặt các con ốc.","Tôi nhận thấy có một mối tương quan giữa việc thức khuya và những cơn đau đầu."]'::jsonb, 3, 'I noticed a correlation between late nights and headaches. → Tôi nhận thấy có một mối tương quan giữa việc thức khuya và những cơn đau đầu.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_67_7', 'en-b2-67', NULL, 'comprehensive_test', 'listening', 'infinite', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["dấu chân","phần sau; phía sau","vô hạn; vô tận","nhanh chóng; tốc độ cao"]'::jsonb, 2, 'infinite (/ˈɪnfɪnət/) → vô hạn; vô tận; vô cùng lớn; cực kỳ nhiều', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_67_8', 'en-b2-67', NULL, 'comprehensive_test', 'listening', 'The curtains have vertical stripes that make the room look taller.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi chưa bao giờ biết đến sự tồn tại của hòn đảo nhỏ bé này.","Bộ rèm có các sọc thẳng đứng khiến căn phòng trông cao hơn.","Chúng tôi đã quan sát một tinh thể muối dưới kính hiển vi của lớp học.","Bà của tôi có vẻ có sự kiên nhẫn vô tận đối với trẻ nhỏ."]'::jsonb, 1, 'The curtains have vertical stripes that make the room look taller. → Bộ rèm có các sọc thẳng đứng khiến căn phòng trông cao hơn.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_67_9', 'en-b2-67', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a scientist who studies stars, planets, and space”?', '["microscope","crystal","astronomer","hydrogen"]'::jsonb, 2, 'astronomer (/əˈstrɑːnəmɚ/) → nhà thiên văn học', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_67_10', 'en-b2-67', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A relationship in which changes in things are linked”?', '["conduct","psychology","correlation","variation"]'::jsonb, 2, 'correlation (/ˌkɔːrəˈleɪʃən/) → sự tương quan; mối liên hệ', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_67_11', 'en-b2-67', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Having no end or limit”?', '["rotate","horizontal","skeleton","infinite"]'::jsonb, 3, 'infinite (/ˈɪnfɪnət/) → vô hạn; vô tận', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
