INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_67_18', 'en-b2-67', NULL, 'comprehensive_test', 'reading', NULL, 'Economists forecast slower growth next year as rising energy costs place greater pressure on businesses.', 'Dựa vào câu trên, từ “forecast” có nghĩa phù hợp nhất là gì?', '["một cách cung kính; một cách tôn trọng","sự dự báo; bản dự báo","được gọi là (thường mang ý nghi ngờ, không chắc chắn); cái gọi là","làm cho ngọt; thêm đường/mật cho ngọt"]'::jsonb, 1, 'forecast: sự dự báo; bản dự báo; dự báo; dự đoán. Dịch cả câu: Các nhà kinh tế dự báo tăng trưởng sẽ chậm lại vào năm tới khi chi phí năng lượng tăng cao gây áp lực lớn hơn lên các doanh nghiệp.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_67_19', 'en-b2-67', NULL, 'comprehensive_test', 'reading', NULL, 'Research in psychology suggests that regular social interaction can support emotional wellbeing among older adults.', 'Dựa vào câu trên, từ “psychology” có nghĩa phù hợp nhất là gì?', '["đòi hỏi nhiều nỗ lực; khắt khe; vất vả","mới đây; gần đây","tâm lý học","phạm vi; tầm vực"]'::jsonb, 2, 'psychology: tâm lý học; tâm lý; đặc điểm tâm lý. Dịch cả câu: Nghiên cứu trong ngành tâm lý học cho thấy việc tương tác xã hội thường xuyên có thể hỗ trợ sức khỏe tinh thần ở người lớn tuổi.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_67_20', 'en-b2-67', NULL, 'comprehensive_test', 'reading', NULL, 'The structure of a crystal influences its physical properties and determines its suitability for various industrial applications.', 'Dựa vào câu trên, từ “crystal” có nghĩa phù hợp nhất là gì?', '["tinh thể","đơn thuốc; thuốc theo đơn","không đều; không theo quy tắc","vặn; xoắn; xoay"]'::jsonb, 0, 'crystal: tinh thể; thạch anh; thủy tinh cao cấp; đồ bằng thủy tinh pha lê. Dịch cả câu: Cấu trúc của một tinh thể ảnh hưởng đến các tính chất vật lý của nó và quyết định độ phù hợp của nó đối với các ứng dụng công nghiệp khác nhau.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_67_21', 'en-b2-67', NULL, 'comprehensive_test', 'reading', NULL, 'Modern irrigation systems can save thousands of cubic metres of water each year.', 'Dựa vào câu trên, từ “cubic” có nghĩa phù hợp nhất là gì?', '["hình lập phương; tính theo mét khối (thể tích)","cố kiến; thành kiến; định kiến","nitơ; khí nitơ","đàn (chim, cừu hoặc dê)"]'::jsonb, 0, 'cubic: hình lập phương; tính theo mét khối (thể tích). Dịch cả câu: Các hệ thống tưới tiêu hiện đại có thể tiết kiệm hàng ngàn mét khối nước mỗi năm.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_67_22', 'en-b2-67', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “vôn (đơn vị đo hiệu điện thế)”', '["agency","outdated","ounce","volt"]'::jsonb, 3, 'vôn (đơn vị đo hiệu điện thế) → volt (/voʊlt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_67_23', 'en-b2-67', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nằm ngang; song song với mặt đất”', '["horizontal","enquire","assist","pitch"]'::jsonb, 0, 'nằm ngang; song song với mặt đất → horizontal (/ˌhɔːrɪˈzɑːntəl/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_67_24', 'en-b2-67', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “danh từ: kính hiển vi”', '["microscope","considerate","satellite","modernize"]'::jsonb, 0, 'danh từ: kính hiển vi → microscope (/ˈmaɪkrəskoʊp/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-68', 'en', 'Bài 68: Khoa học & Nghiên cứu (2) - CEFR B2', 'CEFR B2', 'B2 · Khoa học', '24 từ vựng Tiếng Anh CEFR B2 chủ đề khoa học & nghiên cứu kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4068, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_analysis', 'en-b2-68', 'analysis', '/əˈnæləsɪs/', 'B2', 'sự phân tích, sự nghiên cứu kỹ lưỡng để hiểu rõ các bộ phận hoặc ý nghĩa', 'n.', 'analyse (v.), analyst (n.), analytical (adj.), analytically (adv.)', 'Đồng nghĩa: examination, investigation', 'Dạng số nhiều là analyses; động từ tiếng Anh-Anh là analyse.', 'A soil analysis showed why my plants were struggling.', NULL, 'Một cuộc phân tích đất đã cho thấy lý do tại sao cây trồng của tôi còi cọc.', '{"wordId":"analysis","ukIpa":"/əˈnæləsɪs/","usIpa":"/əˈnæləsɪs/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"Careful examination of something to understand its parts or meaning","vi":"sự phân tích, sự nghiên cứu kỹ lưỡng để hiểu rõ các bộ phận hoặc ý nghĩa"}],"examples":[{"en":"A soil analysis showed why my plants were struggling.","vi":"Một cuộc phân tích đất đã cho thấy lý do tại sao cây trồng của tôi còi cọc.","audioKind":"ex"},{"en":"Careful analysis of travel patterns can help planners design more efficient public transport networks.","vi":"Việc phân tích kỹ lưỡng các mô hình di chuyển có thể giúp các nhà quy hoạch thiết kế mạng lưới giao thông công cộng hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"data analysis","vi":"phân tích dữ liệu"},{"en":"detailed analysis","vi":"phân tích chi tiết"},{"en":"carry out an analysis","vi":"tiến hành phân tích"},{"en":"critical analysis","vi":"phân tích phản biện"}],"wordFamily":["analyse (v.)","analyst (n.)","analytical (adj.)","analytically (adv.)"],"synonyms":["examination","investigation"],"antonyms":[],"tipVi":"Dạng số nhiều là analyses; động từ tiếng Anh-Anh là analyse.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_numerical', 'en-b2-68', 'numerical', '/nuːˈmerɪkəl/', 'B2', 'thuộc về số; bằng số; được thể hiện bằng con số', 'adj.', 'numerically (adv.), numeric (adj.), number (n.)', 'Đồng nghĩa: numeric', 'numerical chỉ các vấn đề liên quan đến con số; numerous chỉ số lượng nhiều.', 'Please arrange these raffle tickets in numerical order.', NULL, 'Xin vui lòng sắp xếp các vé số này theo thứ tự con số.', '{"wordId":"numerical","ukIpa":"/njuːˈmerɪkəl/","usIpa":"/nuːˈmerɪkəl/","cefr":"B2","topic":"science","senses":[{"pos":"adj.","en":"Relating to numbers or expressed using numbers.","vi":"thuộc về số; bằng số; được thể hiện bằng con số"}],"examples":[{"en":"Please arrange these raffle tickets in numerical order.","vi":"Xin vui lòng sắp xếp các vé số này theo thứ tự con số.","audioKind":"ex"},{"en":"Researchers need reliable numerical data to assess whether public transport investments have reduced traffic congestion.","vi":"Các nhà nghiên cứu cần dữ liệu số đáng tin cậy để đánh giá xem các khoản đầu tư giao thông công cộng có làm giảm tình trạng ùn tắc hay không.","audioKind":"ex2"}],"collocations":[{"en":"numerical data","vi":"dữ liệu số"},{"en":"numerical order","vi":"thứ tự số"},{"en":"numerical value","vi":"giá trị số"},{"en":"numerical analysis","vi":"phân tích số"}],"wordFamily":["numerically (adv.)","numeric (adj.)","number (n.)"],"synonyms":["numeric"],"antonyms":[],"tipVi":"numerical chỉ các vấn đề liên quan đến con số; numerous chỉ số lượng nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_axis', 'en-b2-68', 'axis', '/ˈæksɪs/', 'B2', 'trục; đường trục quay; trục tọa độ', 'n.', 'axial (adj.), axially (adv.)', NULL, 'Dạng số nhiều là axes /ˈæksiːz/, cần chú ý phân biệt với số nhiều của từ axe.', 'The globe spins smoothly around its tilted axis.', NULL, 'Quả địa cầu quay mượt mà quanh trục nghiêng của nó.', '{"wordId":"axis","ukIpa":"/ˈæksɪs/","usIpa":"/ˈæksɪs/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"a real or imaginary line around which something turns","vi":"trục; đường trục quay"},{"pos":"n.","en":"a reference line used to locate points on a graph","vi":"trục tọa độ"}],"examples":[{"en":"The globe spins smoothly around its tilted axis.","vi":"Quả địa cầu quay mượt mà quanh trục nghiêng của nó.","audioKind":"ex"},{"en":"The horizontal axis represents time, while the vertical axis shows changes in average household energy consumption.","vi":"Trục hoành biểu thị thời gian, trong khi trục tung thể hiện sự thay đổi về mức tiêu thụ năng lượng trung bình của hộ gia đình.","audioKind":"ex2"}],"collocations":[{"en":"rotate on its axis","vi":"quay quanh trục của nó"},{"en":"horizontal axis","vi":"trục hoành"},{"en":"vertical axis","vi":"trục tung"},{"en":"axis of rotation","vi":"trục quay"}],"wordFamily":["axial (adj.)","axially (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều là axes /ˈæksiːz/, cần chú ý phân biệt với số nhiều của từ axe.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_statistics', 'en-b2-68', 'statistics', '/stəˈtɪstɪks/', 'B2', 'số liệu thống kê; môn thống kê học', 'n.', 'statistic (n.), statistical (adj.), statistically (adv.), statistician (n.)', NULL, 'Khi chỉ số liệu, động từ đi kèm ở số nhiều; khi chỉ môn thống kê học, động từ ở số ít.', 'These statistics show how much water our household uses.', NULL, 'Những số liệu thống kê này cho thấy lượng nước gia đình chúng ta sử dụng là bao nhiêu.', '{"wordId":"statistics","ukIpa":"/stəˈtɪstɪks/","usIpa":"/stəˈtɪstɪks/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"numerical facts collected and organised to describe something","vi":"số liệu thống kê"},{"pos":"n.","en":"the study of collecting, analysing, and interpreting numerical data","vi":"môn thống kê học"}],"examples":[{"en":"These statistics show how much water our household uses.","vi":"Những số liệu thống kê này cho thấy lượng nước gia đình chúng ta sử dụng là bao nhiêu.","audioKind":"ex"},{"en":"Official statistics indicate that access to higher education has improved significantly in rural areas.","vi":"Số liệu thống kê chính thức chỉ ra rằng khả năng tiếp cận giáo dục đại học đã cải thiện đáng kể ở các vùng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"official statistics","vi":"số liệu thống kê chính thức"},{"en":"compile statistics","vi":"tổng hợp số liệu thống kê"},{"en":"statistics show that","vi":"thống kê cho thấy rằng"},{"en":"study statistics","vi":"nghiên cứu thống kê học"}],"wordFamily":["statistic (n.)","statistical (adj.)","statistically (adv.)","statistician (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ số liệu, động từ đi kèm ở số nhiều; khi chỉ môn thống kê học, động từ ở số ít.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aluminium', 'en-b2-68', 'aluminium', '/ˌæljəˈmɪniəm/', 'B2', 'nhôm', 'n.', NULL, NULL, 'Tiếng Anh-Mỹ thường viết là "aluminum", phát âm là /əˈluːmɪnəm/.', 'This aluminium pan is light enough to carry camping.', NULL, 'Chiếc chảo nhôm này đủ nhẹ để mang theo khi đi cắm trại.', '{"wordId":"aluminium","ukIpa":"/ˌæljəˈmɪniəm/","usIpa":"/ˌæljəˈmɪniəm/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A light, silver-coloured metal used in cans and aircraft.","vi":"nhôm"}],"examples":[{"en":"This aluminium pan is light enough to carry camping.","vi":"Chiếc chảo nhôm này đủ nhẹ để mang theo khi đi cắm trại.","audioKind":"ex"},{"en":"Recycling aluminium requires significantly less energy than producing new metal from raw materials, reducing industrial emissions.","vi":"Việc tái chế nhôm tiêu tốn ít năng lượng hơn đáng kể so với việc sản xuất kim loại mới từ nguyên liệu thô, giúp giảm lượng khí thải công nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"aluminium foil","vi":"giấy bạc (lá nhôm)"},{"en":"aluminium alloy","vi":"hợp kim nhôm"},{"en":"aluminium can","vi":"lon nhôm"},{"en":"recycled aluminium","vi":"nhôm tái chế"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tiếng Anh-Mỹ thường viết là \"aluminum\", phát âm là /əˈluːmɪnəm/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_acid', 'en-b2-68', 'acid', '/ˈæsɪd/', 'B2', 'chất axit; chất chua; có tính axit; vị chua; châm biếm; cay độc (lời nói, chỉ trích)', 'n.', 'acidic (adj.), acidity (n.), acidify (v.)', NULL, 'Từ "acid" có thể đóng vai trò là danh từ hoặc tính từ; trong khi "acidic" thường dùng để chỉ tính axit.', 'The acid in lemon juice can help remove stains.', NULL, 'Chất axit trong nước cốt chanh có thể giúp tẩy sạch các vết bẩn.', '{"wordId":"acid","ukIpa":"/ˈæsɪd/","usIpa":"/ˈæsɪd/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A chemical substance with a pH below seven.","vi":"chất axit; chất chua"},{"pos":"adj.","en":"Containing acid or having a sharp, sour taste.","vi":"có tính axit; vị chua"},{"pos":"adj.","en":"Expressing criticism in a sharp and unkind way.","vi":"châm biếm; cay độc (lời nói, chỉ trích)"}],"examples":[{"en":"The acid in lemon juice can help remove stains.","vi":"Chất axit trong nước cốt chanh có thể giúp tẩy sạch các vết bẩn.","audioKind":"ex"},{"en":"Acid rain can damage forests and reduce the ability of lakes to support aquatic life.","vi":"Mưa axit có thể tàn phá các khu rừng và làm giảm khả năng duy trì sự sống thủy sinh của các hồ nước.","audioKind":"ex2"}],"collocations":[{"en":"acid rain","vi":"mưa axit"},{"en":"stomach acid","vi":"axit dạ dày"},{"en":"acid soil","vi":"đất chua"},{"en":"an acid remark","vi":"lời châm biếm sắc mỏng"}],"wordFamily":["acidic (adj.)","acidity (n.)","acidify (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ \"acid\" có thể đóng vai trò là danh từ hoặc tính từ; trong khi \"acidic\" thường dùng để chỉ tính axit.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lens', 'en-b2-68', 'lens', '/lenz/', 'B2', 'thấu kính, kính, tròng kính; thủy tinh thể (trong mắt)', 'n.', NULL, NULL, 'Dạng số nhiều là "lenses"; kính áp tròng thường được gọi là "contact lenses".', 'She carefully wiped the dust off her camera lens.', NULL, 'Cô ấy cẩn thận lau sạch bụi bẩn trên ống kính máy ảnh của mình.', '{"wordId":"lens","ukIpa":"/lenz/","usIpa":"/lenz/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A curved transparent piece that focuses or spreads light.","vi":"thấu kính, kính, tròng kính"},{"pos":"n.","en":"The transparent part inside the eye that focuses light.","vi":"thủy tinh thể (trong mắt)"}],"examples":[{"en":"She carefully wiped the dust off her camera lens.","vi":"Cô ấy cẩn thận lau sạch bụi bẩn trên ống kính máy ảnh của mình.","audioKind":"ex"},{"en":"A damaged lens in the eye can reduce vision and affect a person''s ability to perform everyday tasks.","vi":"Thủy tinh thể bị tổn thương trong mắt có thể làm giảm thị lực và ảnh hưởng đến khả năng thực hiện các công việc hàng ngày của một người.","audioKind":"ex2"}],"collocations":[{"en":"camera lens","vi":"ống kính máy ảnh"},{"en":"contact lens","vi":"kính áp tròng"},{"en":"wide-angle lens","vi":"ống kính góc rộng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều là \"lenses\"; kính áp tròng thường được gọi là \"contact lenses\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_astronomy', 'en-b2-68', 'astronomy', '/əˈstrɑːnəmi/', 'B2', 'thiên văn học', 'n.', 'astronomer (n.), astronomical (adj.)', NULL, 'astronomy là thiên văn học; trong khi astrology là chiêm tinh học.', 'My interest in astronomy began with a small telescope.', NULL, 'Niềm đam mê thiên văn học của tôi bắt đầu từ chiếc kính viễn vọng nhỏ.', '{"wordId":"astronomy","ukIpa":"/əˈstrɒnəmi/","usIpa":"/əˈstrɑːnəmi/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"The scientific study of stars, planets, and space.","vi":"thiên văn học"}],"examples":[{"en":"My interest in astronomy began with a small telescope.","vi":"Niềm đam mê thiên văn học của tôi bắt đầu từ chiếc kính viễn vọng nhỏ.","audioKind":"ex"},{"en":"Studying astronomy can encourage students to explore scientific questions about the origins of the universe.","vi":"Việc học thiên văn học có thể khuyến khích học sinh khám phá các câu hỏi khoa học về nguồn gốc của vũ trụ.","audioKind":"ex2"}],"collocations":[{"en":"study astronomy","vi":"nghiên cứu thiên văn học"},{"en":"observational astronomy","vi":"thiên văn học quan sát"},{"en":"amateur astronomy","vi":"thiên văn học nghiệp dư"}],"wordFamily":["astronomer (n.)","astronomical (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"astronomy là thiên văn học; trong khi astrology là chiêm tinh học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_circuit', 'en-b2-68', 'circuit', '/ˈsɝːkɪt/', 'B2', 'mạch điện; vòng điện; đường vòng; hành trình khép kín; chuỗi địa điểm thi đấu hoặc hoạt động luân phiên', 'n.', 'circuitry (n.)', NULL, 'circuit dùng được cho cả mạch điện lẫn đường đi vòng; short circuit chỉ hiện tượng đoản mạch.', 'The bulb lit up when we completed the circuit.', NULL, 'Bóng đèn sáng lên khi chúng tôi khép kín mạch điện.', '{"wordId":"circuit","ukIpa":"/ˈsɜːkɪt/","usIpa":"/ˈsɝːkɪt/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A connected path through which an electric current can flow","vi":"mạch điện; vòng điện"},{"pos":"n.","en":"A route around an area, or one journey around it","vi":"đường vòng; hành trình khép kín"},{"pos":"n.","en":"A series of places visited for similar events or activities","vi":"chuỗi địa điểm thi đấu hoặc hoạt động luân phiên"}],"examples":[{"en":"The bulb lit up when we completed the circuit.","vi":"Bóng đèn sáng lên khi chúng tôi khép kín mạch điện.","audioKind":"ex"},{"en":"Students can develop practical scientific skills by building a simple circuit and testing different materials.","vi":"Học sinh có thể phát triển các kỹ năng thực hành khoa học bằng cách lắp ráp một mạch điện đơn giản và thử nghiệm các vật liệu khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"electrical circuit","vi":"mạch điện"},{"en":"short circuit","vi":"đoản mạch; chập điện"},{"en":"circuit board","vi":"bảng mạch"},{"en":"racing circuit","vi":"đường đua"}],"wordFamily":["circuitry (n.)"],"synonyms":[],"antonyms":[],"tipVi":"circuit dùng được cho cả mạch điện lẫn đường đi vòng; short circuit chỉ hiện tượng đoản mạch.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_triangular', 'en-b2-68', 'triangular', '/traɪˈæŋɡjələr/', 'B2', 'có hình tam giác; liên quan đến ba bên; tay ba', 'adj.', 'triangle (n.)', NULL, 'Triangle là danh từ; triangular là tính từ.', 'She cut the toast into small triangular pieces.', NULL, 'Cô ấy cắt chiếc bánh mì nướng thành những miếng nhỏ hình tam giác.', '{"wordId":"triangular","ukIpa":"/traɪˈæŋɡjələ/","usIpa":"/traɪˈæŋɡjələr/","cefr":"B2","topic":"science","senses":[{"pos":"adj.","en":"having three straight sides and three angles","vi":"có hình tam giác"},{"pos":"adj.","en":"involving three people, groups, or countries","vi":"liên quan đến ba bên; tay ba"}],"examples":[{"en":"She cut the toast into small triangular pieces.","vi":"Cô ấy cắt chiếc bánh mì nướng thành những miếng nhỏ hình tam giác.","audioKind":"ex"},{"en":"The proposed park occupies a triangular site between two busy roads and a railway line.","vi":"Công viên được đề xuất chiếm một khu đất hình tam giác nằm giữa hai con đường đông đúc và một tuyến đường sắt.","audioKind":"ex2"}],"collocations":[{"en":"triangular shape","vi":"hình dạng tam giác"},{"en":"triangular piece","vi":"miếng hình tam giác"},{"en":"triangular relationship","vi":"mối quan hệ tay ba"}],"wordFamily":["triangle (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Triangle là danh từ; triangular là tính từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_frequency', 'en-b2-68', 'frequency', '/ˈfriːkwənsi/', 'B2', 'tần suất; số lần; tần số', 'n.', 'frequent (adj.), frequently (adv.), infrequent (adj.)', 'Đồng nghĩa: rate', 'Tần suất cao hay thấp dùng high hoặc low; xảy ra nhiều không có nghĩa là tốc độ nhanh.', 'The frequency of buses drops sharply after nine each evening.', NULL, 'Tần suất chạy xe buýt giảm hẳn sau 9 giờ tối mỗi ngày.', '{"wordId":"frequency","ukIpa":"/ˈfriːkwənsi/","usIpa":"/ˈfriːkwənsi/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"how often something happens within a particular period","vi":"tần suất; số lần"},{"pos":"n.","en":"the number of wave cycles or vibrations per second","vi":"tần số"}],"examples":[{"en":"The frequency of buses drops sharply after nine each evening.","vi":"Tần suất chạy xe buýt giảm hẳn sau 9 giờ tối mỗi ngày.","audioKind":"ex"},{"en":"Researchers are examining whether rising ocean temperatures affect the frequency of severe storms in coastal regions.","vi":"Các nhà nghiên cứu đang xem xét liệu nhiệt độ đại dương tăng cao có ảnh hưởng đến tần suất xảy ra các cơn bão lớn ở các vùng ven biển hay không.","audioKind":"ex2"}],"collocations":[{"en":"the frequency of","vi":"tần suất của"},{"en":"with increasing frequency","vi":"với tần suất ngày càng tăng"},{"en":"high frequency","vi":"tần số cao"},{"en":"radio frequency","vi":"tần số vô tuyến"}],"wordFamily":["frequent (adj.)","frequently (adv.)","infrequent (adj.)"],"synonyms":["rate"],"antonyms":[],"tipVi":"Tần suất cao hay thấp dùng high hoặc low; xảy ra nhiều không có nghĩa là tốc độ nhanh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_demonstrate', 'en-b2-68', 'demonstrate', '/ˈdemənstreɪt/', 'B2', 'chứng minh; thể hiện; thực hiện mẫu; biểu diễn; biểu tình', 'v.', 'demonstration (n.), demonstrator (n.), demonstrable (adj.)', 'Đồng nghĩa: show', 'Để chứng minh điều gì đó, thường dùng cấu trúc demonstrate that.', 'These muddy footprints demonstrate that someone entered the kitchen.', NULL, 'Những dấu chân dính bùn này chứng tỏ có ai đó đã bước vào nhà bếp.', '{"wordId":"demonstrate","ukIpa":"/ˈdemənstreɪt/","usIpa":"/ˈdemənstreɪt/","cefr":"B2","topic":"science","senses":[{"pos":"v.","en":"To show clearly that something is true or exists.","vi":"chứng minh; thể hiện"},{"pos":"v.","en":"To show someone how something works or is done.","vi":"thực hiện mẫu; biểu diễn"},{"pos":"v.","en":"To gather publicly to express support or opposition.","vi":"biểu tình"}],"examples":[{"en":"These muddy footprints demonstrate that someone entered the kitchen.","vi":"Những dấu chân dính bùn này chứng tỏ có ai đó đã bước vào nhà bếp.","audioKind":"ex"},{"en":"Recent studies demonstrate that regular physical activity can improve concentration and support students'' mental health.","vi":"Các nghiên cứu gần đây chứng minh rằng việc tập thể dục thường xuyên có thể cải thiện khả năng tập trung và hỗ trợ sức khỏe tinh thần của học sinh.","audioKind":"ex2"}],"collocations":[{"en":"demonstrate that","vi":"chứng minh rằng"},{"en":"demonstrate how","vi":"hướng dẫn cách"},{"en":"demonstrate a commitment to","vi":"thể hiện cam kết với"},{"en":"demonstrate against","vi":"biểu tình phản đối"}],"wordFamily":["demonstration (n.)","demonstrator (n.)","demonstrable (adj.)"],"synonyms":["show"],"antonyms":[],"tipVi":"Để chứng minh điều gì đó, thường dùng cấu trúc demonstrate that.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ratio', 'en-b2-68', 'ratio', '/ˈreɪʃioʊ/', 'B2', 'tỷ lệ; tỉ số', 'n.', NULL, NULL, 'Tỷ lệ giữa A và B dùng cấu trúc the ratio of A to B, cần chú ý đúng thứ tự.', 'Use a higher ratio of vegetables to rice.', NULL, 'Hãy dùng lượng rau có tỷ lệ nhiều hơn so với cơm.', '{"wordId":"ratio","ukIpa":"/ˈreɪʃiəʊ/","usIpa":"/ˈreɪʃioʊ/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A comparison showing the relative sizes of two quantities.","vi":"tỷ lệ; tỉ số"}],"examples":[{"en":"Use a higher ratio of vegetables to rice.","vi":"Hãy dùng lượng rau có tỷ lệ nhiều hơn so với cơm.","audioKind":"ex"},{"en":"A lower ratio of students to teachers may allow schools to provide more individual support in classrooms.","vi":"Tỷ lệ học sinh trên giáo viên thấp hơn có thể giúp các nhà trường cung cấp nhiều sự hỗ trợ cá nhân hơn trong lớp học.","audioKind":"ex2"}],"collocations":[{"en":"the ratio of A to B","vi":"tỷ lệ giữa A và B"},{"en":"student-teacher ratio","vi":"tỷ lệ học sinh trên giáo viên"},{"en":"a high ratio","vi":"tỷ lệ cao"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tỷ lệ giữa A và B dùng cấu trúc the ratio of A to B, cần chú ý đúng thứ tự.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_atomic', 'en-b2-68', 'atomic', '/əˈtɑːmɪk/', 'B2', 'thuộc về nguyên tử; thuộc về năng lượng nguyên tử; thuộc hạt nhân', 'adj.', 'atom (n.), atomically (adv.)', NULL, '"Atomic" nhấn mạnh vào nguyên tử; trong khi "nuclear" nhấn mạnh vào hạt nhân nguyên tử hoặc năng lượng hạt nhân.', 'Our teacher used coloured balls to explain atomic structure.', NULL, 'Giáo viên của chúng tôi đã dùng những quả bóng có màu để giải thích cấu trúc nguyên tử.', '{"wordId":"atomic","ukIpa":"/əˈtɒmɪk/","usIpa":"/əˈtɑːmɪk/","cefr":"B2","topic":"science","senses":[{"pos":"adj.","en":"Relating to atoms, the basic units of chemical elements.","vi":"thuộc về nguyên tử"},{"pos":"adj.","en":"Relating to energy released from the nuclei of atoms.","vi":"thuộc về năng lượng nguyên tử; thuộc hạt nhân"}],"examples":[{"en":"Our teacher used coloured balls to explain atomic structure.","vi":"Giáo viên của chúng tôi đã dùng những quả bóng có màu để giải thích cấu trúc nguyên tử.","audioKind":"ex"},{"en":"Understanding atomic structure has enabled scientists to develop advanced materials for medicine, electronics, and renewable energy technologies.","vi":"Việc thấu hiểu cấu trúc nguyên tử đã giúp các nhà khoa học phát triển các vật liệu tiên tiến cho y học, điện tử và công nghệ năng lượng tái tạo.","audioKind":"ex2"}],"collocations":[{"en":"atomic structure","vi":"cấu trúc nguyên tử"},{"en":"atomic energy","vi":"năng lượng nguyên tử"},{"en":"atomic number","vi":"số hiệu nguyên tử"},{"en":"atomic clock","vi":"đồng hồ nguyên tử"}],"wordFamily":["atom (n.)","atomically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"\"Atomic\" nhấn mạnh vào nguyên tử; trong khi \"nuclear\" nhấn mạnh vào hạt nhân nguyên tử hoặc năng lượng hạt nhân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_observe', 'en-b2-68', 'observe', '/əbˈzɝːv/', 'B2', 'quan sát; để ý; tuân thủ (luật lệ); thực hiện ( phong tục); nhận xét; bình luận', 'v.', 'observation (n.), observer (n.), observant (adj.), observable (adj.)', 'Đồng nghĩa: watch, notice', 'Cấu trúc observe sb doing sth diễn tả việc quan sát thấy ai đó đang làm gì.', 'We observed a tiny bird building its nest outside.', NULL, 'Chúng tôi quan sát một chú chim nhỏ đang làm tổ bên ngoài.', '{"wordId":"observe","ukIpa":"/əbˈzɜːv/","usIpa":"/əbˈzɝːv/","cefr":"B2","topic":"science","senses":[{"pos":"v.","en":"to watch carefully or notice something","vi":"quan sát; để ý"},{"pos":"v.","en":"to follow a rule or practise a custom","vi":"tuân thủ (luật lệ); thực hiện ( phong tục)"},{"pos":"v.","en":"to make a comment about something","vi":"nhận xét; bình luận"}],"examples":[{"en":"We observed a tiny bird building its nest outside.","vi":"Chúng tôi quan sát một chú chim nhỏ đang làm tổ bên ngoài.","audioKind":"ex"},{"en":"Students who observe wildlife directly often develop a deeper understanding of how ecosystems function.","vi":"Những học sinh quan sát trực tiếp đời sống hoang dã thường thấu hiểu sâu sắc hơn về cách hệ sinh thái vận hành.","audioKind":"ex2"}],"collocations":[{"en":"observe closely","vi":"quan sát kỹ lưỡng"},{"en":"observe the rules","vi":"tuân thủ quy định"},{"en":"observe a tradition","vi":"tuân theo truyền thống"}],"wordFamily":["observation (n.)","observer (n.)","observant (adj.)","observable (adj.)"],"synonyms":["watch","notice"],"antonyms":[],"tipVi":"Cấu trúc observe sb doing sth diễn tả việc quan sát thấy ai đó đang làm gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_effectiveness', 'en-b2-68', 'effectiveness', '/ɪˈfektɪvnəs/', 'B2', 'hiệu quả; tính hiệu quả; thành quả', 'n.', 'effective (adj.), effectively (adv.), ineffective (adj.), effect (n.)', 'Đồng nghĩa: efficacy · Trái nghĩa: ineffectiveness', 'effectiveness trọng tâm là kết quả đạt được; efficiency trọng tâm là thời gian và nguồn lực.', 'I was surprised by the effectiveness of this cleaner.', NULL, 'Tôi rất ngạc nhiên trước hiệu quả làm sạch của chất tẩy rửa này.', '{"wordId":"effectiveness","ukIpa":"/ɪˈfektɪvnəs/","usIpa":"/ɪˈfektɪvnəs/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"the degree to which something produces the intended result","vi":"hiệu quả; tính hiệu quả; thành quả"}],"examples":[{"en":"I was surprised by the effectiveness of this cleaner.","vi":"Tôi rất ngạc nhiên trước hiệu quả làm sạch của chất tẩy rửa này.","audioKind":"ex"},{"en":"Researchers should evaluate the effectiveness of educational programmes before recommending their adoption across the national school system.","vi":"Các nhà nghiên cứu nên đánh giá hiệu quả của các chương trình giáo dục trước khi kiến nghị áp dụng chúng trên toàn hệ thống trường học quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"evaluate effectiveness","vi":"đánh giá hiệu quả"},{"en":"improve effectiveness","vi":"nâng cao hiệu quả"},{"en":"demonstrate effectiveness","vi":"chứng minh hiệu quả"},{"en":"cost effectiveness","vi":"hiệu quả chi phí"}],"wordFamily":["effective (adj.)","effectively (adv.)","ineffective (adj.)","effect (n.)"],"synonyms":["efficacy"],"antonyms":["ineffectiveness"],"tipVi":"effectiveness trọng tâm là kết quả đạt được; efficiency trọng tâm là thời gian và nguồn lực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fragment', 'en-b2-68', 'fragment', '/ˈfræɡmənt/', 'B2', 'mảnh vụn; mảnh vỡ; đoạn; làm vỡ vụn; phân rã; chia cắt', 'n.', 'fragmentation (n.), fragmented (adj.), fragmentary (adj.)', 'Đồng nghĩa: piece, shard · Trái nghĩa: whole', 'Danh từ nhấn trọng âm ở âm tiết đầu; động từ phát âm là /fræɡˈment/ với trọng âm ở âm tiết cuối.', 'I found a fragment of blue glass beside the gate.', NULL, 'Tôi tìm thấy một mảnh thủy tinh màu xanh lam ở bên cạnh cổng.', '{"wordId":"fragment","ukIpa":"/ˈfræɡmənt/","usIpa":"/ˈfræɡmənt/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A small piece broken off or separated from something larger.","vi":"mảnh vụn; mảnh vỡ; đoạn"},{"pos":"v.","en":"To break something, or become broken, into smaller separate parts.","vi":"làm vỡ vụn; phân rã; chia cắt"}],"examples":[{"en":"I found a fragment of blue glass beside the gate.","vi":"Tôi tìm thấy một mảnh thủy tinh màu xanh lam ở bên cạnh cổng.","audioKind":"ex"},{"en":"Plastic waste can fragment into tiny particles that enter food chains and threaten marine wildlife.","vi":"Rác thải nhựa có thể vỡ thành các hạt nhỏ li ti xâm nhập vào chuỗi thức ăn và đe dọa động vật hoang dã dưới biển.","audioKind":"ex2"}],"collocations":[{"en":"a fragment of glass","vi":"mảnh thủy tinh"},{"en":"bone fragments","vi":"mảnh xương"},{"en":"fragment into","vi":"vỡ thành"},{"en":"sentence fragment","vi":"câu chưa hoàn chỉnh"}],"wordFamily":["fragmentation (n.)","fragmented (adj.)","fragmentary (adj.)"],"synonyms":["piece","shard"],"antonyms":["whole"],"tipVi":"Danh từ nhấn trọng âm ở âm tiết đầu; động từ phát âm là /fræɡˈment/ với trọng âm ở âm tiết cuối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_substance', 'en-b2-68', 'substance', '/ˈsʌbstəns/', 'B2', 'chất; chất liệu; thực chất; nội dung chính; ý nghĩa thực sự; căn cứ xác đáng', 'n.', NULL, 'Đồng nghĩa: material', 'Dùng ở dạng đếm được khi chỉ loại vật chất; thường không đếm được khi chỉ thực chất hoặc căn cứ.', 'A sticky substance had leaked onto the kitchen floor.', NULL, 'Một chất dính đã bị rò rỉ ra sàn nhà bếp.', '{"wordId":"substance","ukIpa":"/ˈsʌbstəns/","usIpa":"/ˈsʌbstəns/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A particular type of material with specific physical properties.","vi":"chất; chất liệu"},{"pos":"n.","en":"The central meaning or most important content of something.","vi":"thực chất; nội dung chính"},{"pos":"n.","en":"Meaningful content or a solid basis for belief.","vi":"ý nghĩa thực sự; căn cứ xác đáng"}],"examples":[{"en":"A sticky substance had leaked onto the kitchen floor.","vi":"Một chất dính đã bị rò rỉ ra sàn nhà bếp.","audioKind":"ex"},{"en":"Factories must prevent harmful substances from entering rivers, as contaminated water threatens both wildlife and human health.","vi":"Các nhà máy phải ngăn chặn các chất độc hại xả ra sông, vì nguồn nước ô nhiễm đe dọa cả động thực vật hoang dã lẫn sức khỏe con người.","audioKind":"ex2"}],"collocations":[{"en":"harmful substances","vi":"các chất độc hại"},{"en":"chemical substance","vi":"chất hóa học"},{"en":"the substance of","vi":"thực chất của"},{"en":"lack substance","vi":"thiếu tính thực tế"}],"wordFamily":[],"synonyms":["material"],"antonyms":[],"tipVi":"Dùng ở dạng đếm được khi chỉ loại vật chất; thường không đếm được khi chỉ thực chất hoặc căn cứ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mineral', 'en-b2-68', 'mineral', '/ˈmɪnərəl/', 'B2', 'khoáng vật; khoáng chất; thuộc về khoáng sản', 'n.', 'mineralise (v.), mineralisation (n.)', NULL, 'Trong ngữ cảnh dinh dưỡng, minerals chỉ các khoáng chất, khác với các loại vitamin.', 'The museum displayed a mineral with bright purple crystals.', NULL, 'Viện bảo tàng trưng bày một loại khoáng vật có các tinh thể màu tím sáng.', '{"wordId":"mineral","ukIpa":"/ˈmɪnərəl/","usIpa":"/ˈmɪnərəl/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"a natural substance found in rocks, soil, food, or water","vi":"khoáng vật; khoáng chất"},{"pos":"adj.","en":"relating to minerals found in the earth","vi":"thuộc về khoáng sản"}],"examples":[{"en":"The museum displayed a mineral with bright purple crystals.","vi":"Viện bảo tàng trưng bày một loại khoáng vật có các tinh thể màu tím sáng.","audioKind":"ex"},{"en":"Countries with abundant mineral resources need effective regulations to limit the environmental damage caused by mining.","vi":"Các quốc gia có nguồn tài nguyên khoáng sản phong phú cần có các quy định hiệu quả để hạn chế tổn hại môi trường do khaiթ khoáng gây ra.","audioKind":"ex2"}],"collocations":[{"en":"mineral resources","vi":"tài nguyên khoáng sản"},{"en":"mineral deposits","vi":"mỏ khoáng sản"},{"en":"essential minerals","vi":"khoáng chất thiết yếu"},{"en":"mineral water","vi":"nước khoáng"}],"wordFamily":["mineralise (v.)","mineralisation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong ngữ cảnh dinh dưỡng, minerals chỉ các khoáng chất, khác với các loại vitamin.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_breakthrough', 'en-b2-68', 'breakthrough', '/ˈbreɪkθruː/', 'B2', 'bước đột phá; phát hiện quan trọng', 'n.', 'break through (v.)', 'Đồng nghĩa: advance · Trái nghĩa: setback', 'Danh từ "breakthrough" viết liền thành một từ; cụm động từ "break through" viết tách rời.', 'After weeks of practice, I finally made a breakthrough.', NULL, 'Sau nhiều tuần luyện tập, cuối cùng tôi cũng tạo ra được bước đột phá.', '{"wordId":"breakthrough","ukIpa":"/ˈbreɪkθruː/","usIpa":"/ˈbreɪkθruː/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"An important discovery or advance that overcomes a difficult problem.","vi":"bước đột phá; phát hiện quan trọng"}],"examples":[{"en":"After weeks of practice, I finally made a breakthrough.","vi":"Sau nhiều tuần luyện tập, cuối cùng tôi cũng tạo ra được bước đột phá.","audioKind":"ex"},{"en":"A breakthrough in battery technology could make renewable energy more reliable and affordable for households.","vi":"Một bước đột phá trong công nghệ pin có thể giúp năng lượng tái tạo trở nên đáng tin cậy hơn và vừa túi tiền hơn đối với các hộ gia đình.","audioKind":"ex2"}],"collocations":[{"en":"make a breakthrough","vi":"tạo bước đột phá"},{"en":"scientific breakthrough","vi":"bước đột phá khoa học"},{"en":"breakthrough in treatment","vi":"bước đột phá trong điều trị"}],"wordFamily":["break through (v.)"],"synonyms":["advance"],"antonyms":["setback"],"tipVi":"Danh từ \"breakthrough\" viết liền thành một từ; cụm động từ \"break through\" viết tách rời.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_genetic', 'en-b2-68', 'genetic', '/dʒəˈnetɪk/', 'B2', 'thuộc về gen; di truyền', 'adj.', 'gene (n.), genetics (n.), genetically (adv.), geneticist (n.)', NULL, 'genetic là tính từ chỉ gen hoặc sự di truyền; genetics là danh từ chỉ môn sinh học di truyền.', 'The doctor explained how genetic factors affect eye colour.', NULL, 'Bác sĩ giải thích các yếu tố di truyền ảnh hưởng như thế nào đến màu mắt.', '{"wordId":"genetic","ukIpa":"/dʒəˈnetɪk/","usIpa":"/dʒəˈnetɪk/","cefr":"B2","topic":"science","senses":[{"pos":"adj.","en":"relating to genes or characteristics passed from parents to offspring","vi":"thuộc về gen; di truyền"}],"examples":[{"en":"The doctor explained how genetic factors affect eye colour.","vi":"Bác sĩ giải thích các yếu tố di truyền ảnh hưởng như thế nào đến màu mắt.","audioKind":"ex"},{"en":"Genetic research may help doctors identify health risks before patients develop any noticeable symptoms.","vi":"Nghiên cứu di truyền có thể giúp các bác sĩ xác định các rủi ro sức khỏe trước khi bệnh nhân xuất hiện bất kỳ triệu chứng rõ rệt nào.","audioKind":"ex2"}],"collocations":[{"en":"genetic factors","vi":"yếu tố di truyền"},{"en":"genetic variation","vi":"sự biến đổi di truyền"},{"en":"genetic engineering","vi":"kỹ thuật di truyền"},{"en":"genetic disorder","vi":"rối loạn di truyền"}],"wordFamily":["gene (n.)","genetics (n.)","genetically (adv.)","geneticist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"genetic là tính từ chỉ gen hoặc sự di truyền; genetics là danh từ chỉ môn sinh học di truyền.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_colorless', 'en-b2-68', 'colorless', '/ˈkʌlɚləs/', 'B2', 'không màu; trong suốt; nhạt nhẽo; tẻ nhạt; thiếu điểm nhấn', 'adj.', 'color (n.), colorful (adj.)', 'Đồng nghĩa: uninteresting · Trái nghĩa: colorful', 'Cách viết theo kiểu Mỹ là colorless; kiểu Anh là colourless. Không màu không có nghĩa là trong suốt.', 'The bottle contained a colorless liquid that looked like water.', NULL, 'Chai nước chứa một chất lỏng không màu trông giống như nước.', '{"wordId":"colorless","ukIpa":"/ˈkʌlələs/","usIpa":"/ˈkʌlɚləs/","cefr":"B2","topic":"science","senses":[{"pos":"adj.","en":"having no colour","vi":"không màu; trong suốt"},{"pos":"adj.","en":"lacking interesting or distinctive qualities","vi":"nhạt nhẽo; tẻ nhạt; thiếu điểm nhấn"}],"examples":[{"en":"The bottle contained a colorless liquid that looked like water.","vi":"Chai nước chứa một chất lỏng không màu trông giống như nước.","audioKind":"ex"},{"en":"Some harmful gases are colorless, making reliable detection equipment essential for maintaining safety in industrial workplaces.","vi":"Một số loại khí độc hại không màu, khiến các thiết bị phát hiện đáng tin cậy trở nên thiết yếu để duy trì an toàn tại các nơi làm việc công nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"colorless liquid","vi":"chất lỏng không màu"},{"en":"colorless gas","vi":"khí không màu"},{"en":"colorless personality","vi":"tính cách nhạt nhẽo"}],"wordFamily":["color (n.)","colorful (adj.)"],"synonyms":["uninteresting"],"antonyms":["colorful"],"tipVi":"Cách viết theo kiểu Mỹ là colorless; kiểu Anh là colourless. Không màu không có nghĩa là trong suốt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scale', 'en-b2-68', 'scale', '/skeɪl/', 'B2', 'quy mô; mức độ; thang đo; tỷ lệ; cấp độ; vảy (cá, bò sát)', 'n.', NULL, 'Đồng nghĩa: extent, magnitude', 'Biểu thị quy mô dùng on a large scale; biểu thị cái cân thường dùng số nhiều scales.', 'I hadn''t realised the scale of your vegetable garden.', NULL, 'Tôi đã không nhận ra quy mô khu vườn rau của bạn lớn đến thế.', '{"wordId":"scale","ukIpa":"/skeɪl/","usIpa":"/skeɪl/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"The size or extent of something","vi":"quy mô; mức độ"},{"pos":"n.","en":"A measurement system or ratio representing relative size","vi":"thang đo; tỷ lệ; cấp độ"},{"pos":"n.","en":"One of the small hard plates covering a fish or reptile","vi":"vảy (cá, bò sát)"}],"examples":[{"en":"I hadn''t realised the scale of your vegetable garden.","vi":"Tôi đã không nhận ra quy mô khu vườn rau của bạn lớn đến thế.","audioKind":"ex"},{"en":"The scale of plastic pollution demands coordinated action from governments, manufacturers, and consumers worldwide.","vi":"Quy mô của tình trạng ô nhiễm nhựa đòi hỏi sự hành động phối hợp từ các chính phủ, nhà sản xuất và người tiêu dùng trên toàn thế giới.","audioKind":"ex2"}],"collocations":[{"en":"on a large scale","vi":"ở quy mô lớn"},{"en":"the scale of the problem","vi":"mức độ nghiêm trọng của vấn đề"},{"en":"a scale model","vi":"mô hình tỷ lệ"},{"en":"fish scales","vi":"vảy cá"}],"wordFamily":[],"synonyms":["extent","magnitude"],"antonyms":[],"tipVi":"Biểu thị quy mô dùng on a large scale; biểu thị cái cân thường dùng số nhiều scales.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_span', 'en-b2-68', 'span', '/spæn/', 'B2', 'khoảng thời gian; quãng thời gian; khoảng cách; nhịp (cầu); tầm; kéo dài; trải dài; bao trùm', 'n.', NULL, NULL, 'span khi làm động từ được dùng trực tiếp với thời gian hoặc phạm vi mà không cần dùng thêm giới từ.', 'Our dog has a surprisingly short attention span.', NULL, 'Con chó nhà chúng tôi có thời gian tập trung chú ý ngắn đến ngạc nhiên.', '{"wordId":"span","ukIpa":"/spæn/","usIpa":"/spæn/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"The period during which something lasts or happens","vi":"khoảng thời gian; quãng thời gian"},{"pos":"n.","en":"The distance from one end of something to the other","vi":"khoảng cách; nhịp (cầu); tầm"},{"pos":"v.","en":"To extend across a period, area, or range","vi":"kéo dài; trải dài; bao trùm"}],"examples":[{"en":"Our dog has a surprisingly short attention span.","vi":"Con chó nhà chúng tôi có thời gian tập trung chú ý ngắn đến ngạc nhiên.","audioKind":"ex"},{"en":"The research project will span several decades, allowing scientists to track long-term changes in coastal ecosystems.","vi":"Dự án nghiên cứu này sẽ kéo dài trong vài thập kỷ, giúp các nhà khoa học theo dõi những thay đổi lâu dài trong hệ sinh thái ven biển.","audioKind":"ex2"}],"collocations":[{"en":"attention span","vi":"thời gian tập trung chú ý"},{"en":"a short time span","vi":"một khoảng thời gian ngắn"},{"en":"span several decades","vi":"kéo dài vài thập kỷ"},{"en":"a bridge span","vi":"nhịp cầu"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"span khi làm động từ được dùng trực tiếp với thời gian hoặc phạm vi mà không cần dùng thêm giới từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_68_1', 'en-b2-68', 'Cách dùng “atomic” (adj.) — thuộc về nguyên tử', 'atomic structure  ·  atomic energy  ·  atomic number', '"Atomic" nhấn mạnh vào nguyên tử; trong khi "nuclear" nhấn mạnh vào hạt nhân nguyên tử hoặc năng lượng hạt nhân.', 'Họ từ (Word Family): atom (n.), atomically (adv.)', '[{"hanzi":"Our teacher used coloured balls to explain atomic structure.","pinyin":"","meaning":"Giáo viên của chúng tôi đã dùng những quả bóng có màu để giải thích cấu trúc nguyên tử."},{"hanzi":"Understanding atomic structure has enabled scientists to develop advanced materials for medicine, electronics, and renewable energy technologies.","pinyin":"","meaning":"Việc thấu hiểu cấu trúc nguyên tử đã giúp các nhà khoa học phát triển các vật liệu tiên tiến cho y học, điện tử và công nghệ năng lượng tái tạo."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_68_2', 'en-b2-68', 'Cách dùng “acid” (n.) — chất axit; chất chua', 'acid rain  ·  stomach acid  ·  acid soil', 'Từ "acid" có thể đóng vai trò là danh từ hoặc tính từ; trong khi "acidic" thường dùng để chỉ tính axit.', 'Họ từ (Word Family): acidic (adj.), acidity (n.), acidify (v.)', '[{"hanzi":"The acid in lemon juice can help remove stains.","pinyin":"","meaning":"Chất axit trong nước cốt chanh có thể giúp tẩy sạch các vết bẩn."},{"hanzi":"Acid rain can damage forests and reduce the ability of lakes to support aquatic life.","pinyin":"","meaning":"Mưa axit có thể tàn phá các khu rừng và làm giảm khả năng duy trì sự sống thủy sinh của các hồ nước."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_68_3', 'en-b2-68', 'Cách dùng “colorless” (adj.) — không màu; trong suốt', 'colorless liquid  ·  colorless gas  ·  colorless personality', 'Cách viết theo kiểu Mỹ là colorless; kiểu Anh là colourless. Không màu không có nghĩa là trong suốt.', 'Họ từ (Word Family): color (n.), colorful (adj.) | Đồng nghĩa: uninteresting · Trái nghĩa: colorful', '[{"hanzi":"The bottle contained a colorless liquid that looked like water.","pinyin":"","meaning":"Chai nước chứa một chất lỏng không màu trông giống như nước."},{"hanzi":"Some harmful gases are colorless, making reliable detection equipment essential for maintaining safety in industrial workplaces.","pinyin":"","meaning":"Một số loại khí độc hại không màu, khiến các thiết bị phát hiện đáng tin cậy trở nên thiết yếu để duy trì an toàn tại các nơi làm việc công nghiệp."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_68_4', 'en-b2-68', 'Cách dùng “span” (n.) — khoảng thời gian; quãng thời gian', 'attention span  ·  a short time span  ·  span several decades', 'span khi làm động từ được dùng trực tiếp với thời gian hoặc phạm vi mà không cần dùng thêm giới từ.', NULL, '[{"hanzi":"Our dog has a surprisingly short attention span.","pinyin":"","meaning":"Con chó nhà chúng tôi có thời gian tập trung chú ý ngắn đến ngạc nhiên."},{"hanzi":"The research project will span several decades, allowing scientists to track long-term changes in coastal ecosystems.","pinyin":"","meaning":"Dự án nghiên cứu này sẽ kéo dài trong vài thập kỷ, giúp các nhà khoa học theo dõi những thay đổi lâu dài trong hệ sinh thái ven biển."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_68_1', 'en-b2-68', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_68_1_1', 'ten_b2_68_1', 'analysis', 'A soil analysis showed why my plants were struggling.', 'A soil analysis showed why my plants were struggling.', '/əˈnæləsɪs/', 'Một cuộc phân tích đất đã cho thấy lý do tại sao cây trồng của tôi còi cọc.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_68_1_2', 'ten_b2_68_1', 'numerical', 'Please arrange these raffle tickets in numerical order.', 'Please arrange these raffle tickets in numerical order.', '/nuːˈmerɪkəl/', 'Xin vui lòng sắp xếp các vé số này theo thứ tự con số.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_68_1_3', 'ten_b2_68_1', 'axis', 'The globe spins smoothly around its tilted axis.', 'The globe spins smoothly around its tilted axis.', '/ˈæksɪs/', 'Quả địa cầu quay mượt mà quanh trục nghiêng của nó.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_68_1_4', 'ten_b2_68_1', 'statistics', 'These statistics show how much water our household uses.', 'These statistics show how much water our household uses.', '/stəˈtɪstɪks/', 'Những số liệu thống kê này cho thấy lượng nước gia đình chúng ta sử dụng là bao nhiêu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_68_1_5', 'ten_b2_68_1', 'aluminium', 'This aluminium pan is light enough to carry camping.', 'This aluminium pan is light enough to carry camping.', '/ˌæljəˈmɪniəm/', 'Chiếc chảo nhôm này đủ nhẹ để mang theo khi đi cắm trại.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_68_1_6', 'ten_b2_68_1', 'acid', 'The acid in lemon juice can help remove stains.', 'The acid in lemon juice can help remove stains.', '/ˈæsɪd/', 'Chất axit trong nước cốt chanh có thể giúp tẩy sạch các vết bẩn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_68_1_7', 'ten_b2_68_1', 'lens', 'She carefully wiped the dust off her camera lens.', 'She carefully wiped the dust off her camera lens.', '/lenz/', 'Cô ấy cẩn thận lau sạch bụi bẩn trên ống kính máy ảnh của mình.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_68_1_8', 'ten_b2_68_1', 'astronomy', 'My interest in astronomy began with a small telescope.', 'My interest in astronomy began with a small telescope.', '/əˈstrɑːnəmi/', 'Niềm đam mê thiên văn học của tôi bắt đầu từ chiếc kính viễn vọng nhỏ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_68_1_1', 'en-b2-68', 'ten_b2_68_1', 'listening', 'listening', 'A soil analysis showed why my plants were struggling.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy cẩn thận lau sạch bụi bẩn trên ống kính máy ảnh của mình.","Niềm đam mê thiên văn học của tôi bắt đầu từ chiếc kính viễn vọng nhỏ.","Một cuộc phân tích đất đã cho thấy lý do tại sao cây trồng của tôi còi cọc.","Viện bảo tàng trưng bày một loại khoáng vật có các tinh thể màu tím sáng."]'::jsonb, 2, 'A soil analysis showed why my plants were struggling. → Một cuộc phân tích đất đã cho thấy lý do tại sao cây trồng của tôi còi cọc.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_68_1_2', 'en-b2-68', 'ten_b2_68_1', 'listening', 'listening', 'Please arrange these raffle tickets in numerical order.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy cắt chiếc bánh mì nướng thành những miếng nhỏ hình tam giác.","Xin vui lòng sắp xếp các vé số này theo thứ tự con số.","Hãy dùng lượng rau có tỷ lệ nhiều hơn so với cơm.","Những dấu chân dính bùn này chứng tỏ có ai đó đã bước vào nhà bếp."]'::jsonb, 1, 'Please arrange these raffle tickets in numerical order. → Xin vui lòng sắp xếp các vé số này theo thứ tự con số.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_68_1_3', 'en-b2-68', 'ten_b2_68_1', 'listening', 'listening', 'The globe spins smoothly around its tilted axis.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi quan sát một chú chim nhỏ đang làm tổ bên ngoài.","Quả địa cầu quay mượt mà quanh trục nghiêng của nó.","Tần suất chạy xe buýt giảm hẳn sau 9 giờ tối mỗi ngày.","Chai nước chứa một chất lỏng không màu trông giống như nước."]'::jsonb, 1, 'The globe spins smoothly around its tilted axis. → Quả địa cầu quay mượt mà quanh trục nghiêng của nó.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_68_2', 'en-b2-68', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_68_2_1', 'ten_b2_68_2', 'analysis', 'Careful analysis of travel patterns can help planners design more efficient public transport networks.', 'Careful analysis of travel patterns can help planners design more efficient public transport networks.', '/əˈnæləsɪs/', 'Việc phân tích kỹ lưỡng các mô hình di chuyển có thể giúp các nhà quy hoạch thiết kế mạng lưới giao thông công cộng hiệu quả hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_68_2_2', 'ten_b2_68_2', 'numerical', 'Researchers need reliable numerical data to assess whether public transport investments have reduced traffic congestion.', 'Researchers need reliable numerical data to assess whether public transport investments have reduced traffic congestion.', '/nuːˈmerɪkəl/', 'Các nhà nghiên cứu cần dữ liệu số đáng tin cậy để đánh giá xem các khoản đầu tư giao thông công cộng có làm giảm tình trạng ùn tắc hay không.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_68_2_3', 'ten_b2_68_2', 'axis', 'The horizontal axis represents time, while the vertical axis shows changes in average household energy consumption.', 'The horizontal axis represents time, while the vertical axis shows changes in average household energy consumption.', '/ˈæksɪs/', 'Trục hoành biểu thị thời gian, trong khi trục tung thể hiện sự thay đổi về mức tiêu thụ năng lượng trung bình của hộ gia đình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_68_2_4', 'ten_b2_68_2', 'statistics', 'Official statistics indicate that access to higher education has improved significantly in rural areas.', 'Official statistics indicate that access to higher education has improved significantly in rural areas.', '/stəˈtɪstɪks/', 'Số liệu thống kê chính thức chỉ ra rằng khả năng tiếp cận giáo dục đại học đã cải thiện đáng kể ở các vùng nông thôn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_68_2_5', 'ten_b2_68_2', 'aluminium', 'Recycling aluminium requires significantly less energy than producing new metal from raw materials, reducing industrial emissions.', 'Recycling aluminium requires significantly less energy than producing new metal from raw materials, reducing industrial emissions.', '/ˌæljəˈmɪniəm/', 'Việc tái chế nhôm tiêu tốn ít năng lượng hơn đáng kể so với việc sản xuất kim loại mới từ nguyên liệu thô, giúp giảm lượng khí thải công nghiệp.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_68_2_6', 'ten_b2_68_2', 'acid', 'Acid rain can damage forests and reduce the ability of lakes to support aquatic life.', 'Acid rain can damage forests and reduce the ability of lakes to support aquatic life.', '/ˈæsɪd/', 'Mưa axit có thể tàn phá các khu rừng và làm giảm khả năng duy trì sự sống thủy sinh của các hồ nước.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_68_2_1', 'en-b2-68', 'ten_b2_68_2', 'listening', 'listening', 'Careful analysis of travel patterns can help planners design more efficient public transport networks.', NULL, 'Trong câu vừa nghe, từ “analysis” mang nghĩa nào sau đây?', '["nâng cấp; cải thiện","dây thun co giãn; dây bẹ (dùng để buộc đồ hoặc nhảy bungee)","sự phân tích, sự nghiên cứu kỹ lưỡng để hiểu rõ các bộ phận hoặc ý nghĩa","mảnh vụn; mảnh vỡ; đoạn"]'::jsonb, 2, '“analysis” (/əˈnæləsɪs/): sự phân tích, sự nghiên cứu kỹ lưỡng để hiểu rõ các bộ phận hoặc ý nghĩa. Câu đầy đủ: Careful analysis of travel patterns can help planners design more efficient public transport networks.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_68_2_2', 'en-b2-68', 'ten_b2_68_2', 'listening', 'listening', 'Researchers need reliable numerical data to assess whether public transport investments have reduced traffic congestion.', NULL, 'Trong câu vừa nghe, từ “numerical” mang nghĩa nào sau đây?', '["không thực tế; không khả thi","pháo đài; thành lũy; đồn lũy","thuộc về số; bằng số; được thể hiện bằng con số","cạo; gạt"]'::jsonb, 2, '“numerical” (/nuːˈmerɪkəl/): thuộc về số; bằng số; được thể hiện bằng con số. Câu đầy đủ: Researchers need reliable numerical data to assess whether public transport investments have reduced traffic congestion.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
