INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_68_1', 'en-b2-68', NULL, 'comprehensive_test', 'listening', 'analysis', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự phân tích, sự nghiên cứu kỹ lưỡng để hiểu rõ các bộ phận hoặc ý nghĩa","sự vận chuyển hàng hóa; ngành vận tải biển","khóc; rơi lệ","cấp bậc; quân hàm; địa vị"]'::jsonb, 0, 'analysis (/əˈnæləsɪs/) → sự phân tích, sự nghiên cứu kỹ lưỡng để hiểu rõ các bộ phận hoặc ý nghĩa', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_68_2', 'en-b2-68', NULL, 'comprehensive_test', 'listening', 'Please arrange these raffle tickets in numerical order.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chiếc chảo nhôm này đủ nhẹ để mang theo khi đi cắm trại.","Tôi đã không nhận ra quy mô khu vườn rau của bạn lớn đến thế.","Sau nhiều tuần luyện tập, cuối cùng tôi cũng tạo ra được bước đột phá.","Xin vui lòng sắp xếp các vé số này theo thứ tự con số."]'::jsonb, 3, 'Please arrange these raffle tickets in numerical order. → Xin vui lòng sắp xếp các vé số này theo thứ tự con số.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_68_3', 'en-b2-68', NULL, 'comprehensive_test', 'listening', 'axis', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["trục; đường trục quay","cố ý; chủ tâm","được đánh giá; được định giá","cây hoa lily; hoa loa kèn; hoa bách hợp"]'::jsonb, 0, 'axis (/ˈæksɪs/) → trục; đường trục quay; trục tọa độ', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_68_4', 'en-b2-68', NULL, 'comprehensive_test', 'listening', 'These statistics show how much water our household uses.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một cuộc phân tích đất đã cho thấy lý do tại sao cây trồng của tôi còi cọc.","Chất axit trong nước cốt chanh có thể giúp tẩy sạch các vết bẩn.","Niềm đam mê thiên văn học của tôi bắt đầu từ chiếc kính viễn vọng nhỏ.","Những số liệu thống kê này cho thấy lượng nước gia đình chúng ta sử dụng là bao nhiêu."]'::jsonb, 3, 'These statistics show how much water our household uses. → Những số liệu thống kê này cho thấy lượng nước gia đình chúng ta sử dụng là bao nhiêu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_68_5', 'en-b2-68', NULL, 'comprehensive_test', 'listening', 'aluminium', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thống đốc; thủ hiến","đáng kể; quan trọng; lớn","phụ kiện; linh kiện bổ trợ","nhôm"]'::jsonb, 3, 'aluminium (/ˌæljəˈmɪniəm/) → nhôm', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_68_6', 'en-b2-68', NULL, 'comprehensive_test', 'listening', 'The acid in lemon juice can help remove stains.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những dấu chân dính bùn này chứng tỏ có ai đó đã bước vào nhà bếp.","Những số liệu thống kê này cho thấy lượng nước gia đình chúng ta sử dụng là bao nhiêu.","Chất axit trong nước cốt chanh có thể giúp tẩy sạch các vết bẩn.","Cô ấy cẩn thận lau sạch bụi bẩn trên ống kính máy ảnh của mình."]'::jsonb, 2, 'The acid in lemon juice can help remove stains. → Chất axit trong nước cốt chanh có thể giúp tẩy sạch các vết bẩn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
