INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_68_8', 'en-b2-68', NULL, 'comprehensive_test', 'listening', 'My interest in astronomy began with a small telescope.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bác sĩ giải thích các yếu tố di truyền ảnh hưởng như thế nào đến màu mắt.","Bóng đèn sáng lên khi chúng tôi khép kín mạch điện.","Cô ấy cẩn thận lau sạch bụi bẩn trên ống kính máy ảnh của mình.","Niềm đam mê thiên văn học của tôi bắt đầu từ chiếc kính viễn vọng nhỏ."]'::jsonb, 3, 'My interest in astronomy began with a small telescope. → Niềm đam mê thiên văn học của tôi bắt đầu từ chiếc kính viễn vọng nhỏ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
