INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_68_18', 'en-b2-68', NULL, 'comprehensive_test', 'reading', NULL, 'Careful analysis of travel patterns can help planners design more efficient public transport networks.', 'Dựa vào câu trên, từ “analysis” có nghĩa phù hợp nhất là gì?', '["sự phân tích, sự nghiên cứu kỹ lưỡng để hiểu rõ các bộ phận hoặc ý nghĩa","đe dọa; khủng bố tinh thần","sự nhận ra; sự nhận diện","vô tội; không có tội"]'::jsonb, 0, 'analysis: sự phân tích, sự nghiên cứu kỹ lưỡng để hiểu rõ các bộ phận hoặc ý nghĩa. Dịch cả câu: Việc phân tích kỹ lưỡng các mô hình di chuyển có thể giúp các nhà quy hoạch thiết kế mạng lưới giao thông công cộng hiệu quả hơn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_68_19', 'en-b2-68', NULL, 'comprehensive_test', 'reading', NULL, 'Researchers need reliable numerical data to assess whether public transport investments have reduced traffic congestion.', 'Dựa vào câu trên, từ “numerical” có nghĩa phù hợp nhất là gì?', '["liên tưởng; kết nối","nỗi cô đơn; sự cô độc","thuộc về số; bằng số; được thể hiện bằng con số","thuộc nông thôn; thuộc vùng quê"]'::jsonb, 2, 'numerical: thuộc về số; bằng số; được thể hiện bằng con số. Dịch cả câu: Các nhà nghiên cứu cần dữ liệu số đáng tin cậy để đánh giá xem các khoản đầu tư giao thông công cộng có làm giảm tình trạng ùn tắc hay không.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_68_20', 'en-b2-68', NULL, 'comprehensive_test', 'reading', NULL, 'The horizontal axis represents time, while the vertical axis shows changes in average household energy consumption.', 'Dựa vào câu trên, từ “axis” có nghĩa phù hợp nhất là gì?', '["hơn nữa; ngoài ra","thanh tra; thanh tra viên","trục; đường trục quay","giấu tên; vô danh"]'::jsonb, 2, 'axis: trục; đường trục quay; trục tọa độ. Dịch cả câu: Trục hoành biểu thị thời gian, trong khi trục tung thể hiện sự thay đổi về mức tiêu thụ năng lượng trung bình của hộ gia đình.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_68_21', 'en-b2-68', NULL, 'comprehensive_test', 'reading', NULL, 'Official statistics indicate that access to higher education has improved significantly in rural areas.', 'Dựa vào câu trên, từ “statistics” có nghĩa phù hợp nhất là gì?', '["điền trang; thái ấp","sự thiếu hiểu biết; sự ngu dốt; sự không biết","số liệu thống kê","chọc; thọc"]'::jsonb, 2, 'statistics: số liệu thống kê; môn thống kê học. Dịch cả câu: Số liệu thống kê chính thức chỉ ra rằng khả năng tiếp cận giáo dục đại học đã cải thiện đáng kể ở các vùng nông thôn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_68_22', 'en-b2-68', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “không màu; trong suốt”', '["coincidence","rifle","gamble","colorless"]'::jsonb, 3, 'không màu; trong suốt → colorless (/ˈkʌlɚləs/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_68_23', 'en-b2-68', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “quy mô; mức độ”', '["colony","ambitious","destiny","scale"]'::jsonb, 3, 'quy mô; mức độ → scale (/skeɪl/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_68_24', 'en-b2-68', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “khoảng thời gian; quãng thời gian”', '["copper","phase","span","unlimited"]'::jsonb, 2, 'khoảng thời gian; quãng thời gian → span (/spæn/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-69', 'en', 'Bài 69: Khoa học & Nghiên cứu (3) - CEFR B2', 'CEFR B2', 'B2 · Khoa học', '24 từ vựng Tiếng Anh CEFR B2 chủ đề khoa học & nghiên cứu kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4069, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_theory', 'en-b2-69', 'theory', '/ˈθɪri/', 'B2', 'lý thuyết; học thuyết; giả thuyết; sự suy đoán; kiến thức lý thuyết', 'n.', 'theoretical (adj.), theoretically (adv.), theorist (n.), theorise (v.)', NULL, '"in theory" có nghĩa là "về mặt lý thuyết", thường được dùng để đối chiếu với "in practice" (trên thực tế).', 'My theory is that the cat knocked the cup over.', NULL, 'Tôi đoán là con mèo đã làm đổ cái cốc.', '{"wordId":"theory","ukIpa":"/ˈθɪəri/","usIpa":"/ˈθɪri/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"an organized explanation of facts or how something works","vi":"lý thuyết; học thuyết"},{"pos":"n.","en":"an idea offered to explain something, not yet proved","vi":"giả thuyết; sự suy đoán"},{"pos":"n.","en":"the principles of a subject rather than their practical application","vi":"kiến thức lý thuyết"}],"examples":[{"en":"My theory is that the cat knocked the cup over.","vi":"Tôi đoán là con mèo đã làm đổ cái cốc.","audioKind":"ex"},{"en":"Students benefit from courses that connect scientific theory with practical experiments and problems from everyday life.","vi":"Học sinh được hưởng lợi từ các khóa học kết nối lý thuyết khoa học với các thí nghiệm thực hành và những vấn đề trong đời sống hằng ngày.","audioKind":"ex2"}],"collocations":[{"en":"in theory","vi":"về mặt lý thuyết"},{"en":"support a theory","vi":"ủng hộ một học thuyết"},{"en":"test a theory","vi":"kiểm chứng một học thuyết"},{"en":"theory and practice","vi":"lý thuyết và thực hành"}],"wordFamily":["theoretical (adj.)","theoretically (adv.)","theorist (n.)","theorise (v.)"],"synonyms":[],"antonyms":[],"tipVi":"\"in theory\" có nghĩa là \"về mặt lý thuyết\", thường được dùng để đối chiếu với \"in practice\" (trên thực tế).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_invisible', 'en-b2-69', 'invisible', '/ɪnˈvɪzəbl/', 'B2', 'vô hình; không nhìn thấy được; không được chú ý; bị phớt lờ', 'adj.', 'visibility (n.), invisibility (n.), visible (adj.), invisibly (adv.)', 'Đồng nghĩa: unseen · Trái nghĩa: visible', 'invisible chỉ việc không nhìn thấy được; khác với incomprehensible nghĩa là không thể hiểu được.', 'The thin fishing line was almost invisible underwater.', NULL, 'Đường câu mảnh đến mức gần như vô hình dưới nước.', '{"wordId":"invisible","ukIpa":"/ɪnˈvɪzəbl/","usIpa":"/ɪnˈvɪzəbl/","cefr":"B2","topic":"science","senses":[{"pos":"adj.","en":"Impossible to see.","vi":"vô hình; không nhìn thấy được"},{"pos":"adj.","en":"Not noticed or acknowledged by other people.","vi":"không được chú ý; bị phớt lờ"}],"examples":[{"en":"The thin fishing line was almost invisible underwater.","vi":"Đường câu mảnh đến mức gần như vô hình dưới nước.","audioKind":"ex"},{"en":"Although many air pollutants are invisible, prolonged exposure can seriously damage respiratory health, particularly among children.","vi":"Mặc dù nhiều chất ô nhiễm không khí là vô hình, việc tiếp xúc kéo dài có thể gây tổn hại nghiêm trọng đến sức khỏe hô hấp, đặc biệt là ở trẻ em.","audioKind":"ex2"}],"collocations":[{"en":"invisible to the naked eye","vi":"vô hình trước mắt thường"},{"en":"almost invisible","vi":"gần như vô hình"},{"en":"remain invisible","vi":"vẫn không được chú ý"}],"wordFamily":["visibility (n.)","invisibility (n.)","visible (adj.)","invisibly (adv.)"],"synonyms":["unseen"],"antonyms":["visible"],"tipVi":"invisible chỉ việc không nhìn thấy được; khác với incomprehensible nghĩa là không thể hiểu được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_advance', 'en-b2-69', 'advance', '/ədˈvæns/', 'B2', 'sự tiến bộ; bước tiến; sự phát triển; tiến lên; thúc đẩy; phát triển; trước; chuẩn bị trước', 'n.', 'advancement (n.), advanced (adj.)', 'Đồng nghĩa: progress', 'Cụm in advance có nghĩa là trước/sớm hơn; advanced là tính từ chỉ sự tiên tiến hoặc trình độ cao.', 'This new treatment is a major advance in medicine.', NULL, 'Phương pháp điều trị mới này là một bước tiến lớn trong y học.', '{"wordId":"advance","ukIpa":"/ədˈvɑːns/","usIpa":"/ədˈvæns/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"An improvement or development in a particular field","vi":"sự tiến bộ; bước tiến; sự phát triển"},{"pos":"v.","en":"Move forward or help something develop","vi":"tiến lên; thúc đẩy; phát triển"},{"pos":"adj.","en":"Done or provided before a particular time or event","vi":"trước; chuẩn bị trước"}],"examples":[{"en":"This new treatment is a major advance in medicine.","vi":"Phương pháp điều trị mới này là một bước tiến lớn trong y học.","audioKind":"ex"},{"en":"Advances in renewable energy technology could reduce dependence on fossil fuels and improve long-term energy security.","vi":"Những tiến bộ trong công nghệ năng lượng tái tạo có thể làm giảm sự phụ thuộc vào nhiên liệu hóa thạch và nâng cao an ninh năng lượng lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"a major advance","vi":"một bước tiến lớn"},{"en":"in advance","vi":"trước"},{"en":"advance notice","vi":"thông báo trước"},{"en":"advance knowledge","vi":"thúc đẩy tri thức phát triển"}],"wordFamily":["advancement (n.)","advanced (adj.)"],"synonyms":["progress"],"antonyms":[],"tipVi":"Cụm in advance có nghĩa là trước/sớm hơn; advanced là tính từ chỉ sự tiên tiến hoặc trình độ cao.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spark', 'en-b2-69', 'spark', '/spɑːrk/', 'B2', 'tia lửa; tia điện; khơi nguồn; châm ngòi; kích thích; một chút; nhân tố khởi phát', 'n.', NULL, NULL, 'Khi là động từ có thể đi trực tiếp với interest, debate, mang nghĩa "khơi nguồn".', 'A tiny spark flew out of the fireplace.', NULL, 'Một tia lửa nhỏ bắn ra từ lò sưởi.', '{"wordId":"spark","ukIpa":"/spɑːk/","usIpa":"/spɑːrk/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A tiny burning particle or a brief flash of electricity.","vi":"tia lửa; tia điện"},{"pos":"v.","en":"To cause something to begin or develop suddenly.","vi":"khơi nguồn; châm ngòi; kích thích"},{"pos":"n.","en":"A small amount of a quality, or something initiating change.","vi":"một chút; nhân tố khởi phát"}],"examples":[{"en":"A tiny spark flew out of the fireplace.","vi":"Một tia lửa nhỏ bắn ra từ lò sưởi.","audioKind":"ex"},{"en":"Investment in public libraries can spark interest in reading and provide valuable learning opportunities for disadvantaged children.","vi":"Việc đầu tư vào các thư viện công cộng có thể khơi dậy niềm đam mê đọc sách và mang lại cơ hội học tập giá trị cho trẻ em có hoàn cảnh khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"spark a debate","vi":"châm ngòi cho một cuộc tranh luận"},{"en":"spark interest","vi":"khơi dậy sự quan tâm"},{"en":"a spark of hope","vi":"một tia hy vọng"},{"en":"electrical spark","vi":"tia lửa điện"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi là động từ có thể đi trực tiếp với interest, debate, mang nghĩa \"khơi nguồn\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_accurate', 'en-b2-69', 'accurate', '/ˈækjərət/', 'B2', 'chính xác; đúng đắn; chuẩn xác; trúng đích', 'adj.', 'accuracy (n.), accurately (adv.), inaccurate (adj.), inaccuracy (n.)', 'Đồng nghĩa: correct, precise · Trái nghĩa: inaccurate, incorrect', 'accurate nhấn mạnh sự chính xác không có lỗi; precise nhấn mạnh sự chi tiết và chuẩn xác.', 'This kitchen scale is accurate enough for baking bread.', NULL, 'Chiếc cân nhà bếp này đủ độ chính xác để làm bánh mì.', '{"wordId":"accurate","ukIpa":"/ˈækjərət/","usIpa":"/ˈækjərət/","cefr":"B2","topic":"science","senses":[{"pos":"adj.","en":"correct and free from mistakes","vi":"chính xác; đúng đắn"},{"pos":"adj.","en":"able to hit or reach the intended target","vi":"chuẩn xác; trúng đích"}],"examples":[{"en":"This kitchen scale is accurate enough for baking bread.","vi":"Chiếc cân nhà bếp này đủ độ chính xác để làm bánh mì.","audioKind":"ex"},{"en":"Accurate information about air quality enables residents to make informed decisions about outdoor exercise.","vi":"Thông tin chính xác về chất lượng không khí giúp cư dân đưa ra quyết định sáng suốt về việc tập thể dục ngoài trời.","audioKind":"ex2"}],"collocations":[{"en":"accurate information","vi":"thông tin chính xác"},{"en":"accurate measurements","vi":"các phép đo chính xác"},{"en":"highly accurate","vi":"có độ chính xác cao"},{"en":"an accurate prediction","vi":"một dự đoán chính xác"}],"wordFamily":["accuracy (n.)","accurately (adv.)","inaccurate (adj.)","inaccuracy (n.)"],"synonyms":["correct","precise"],"antonyms":["inaccurate","incorrect"],"tipVi":"accurate nhấn mạnh sự chính xác không có lỗi; precise nhấn mạnh sự chi tiết và chuẩn xác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nuclear', 'en-b2-69', 'nuclear', '/ˈnuːkliər/', 'B2', 'thuộc về hạt nhân; thuộc về năng lượng hạt nhân; thuộc về tế bào nhân', 'adj.', 'nucleus (n.)', NULL, 'nuclear có thể chỉ hạt nhân nguyên tử hoặc tế bào nhân, tùy thuộc vào ngữ cảnh.', 'My cousin works at a nearby nuclear power station.', NULL, 'Anh họ tôi làm việc tại một nhà máy điện hạt nhân gần đây.', '{"wordId":"nuclear","ukIpa":"/ˈnjuːkliə/","usIpa":"/ˈnuːkliər/","cefr":"B2","topic":"science","senses":[{"pos":"adj.","en":"Relating to atomic nuclei or the energy they release.","vi":"thuộc về hạt nhân; thuộc về năng lượng hạt nhân"},{"pos":"adj.","en":"Relating to the nucleus of a cell.","vi":"thuộc về tế bào nhân"}],"examples":[{"en":"My cousin works at a nearby nuclear power station.","vi":"Anh họ tôi làm việc tại một nhà máy điện hạt nhân gần đây.","audioKind":"ex"},{"en":"Nuclear energy can provide reliable electricity, but managing radioactive waste remains a major challenge.","vi":"Năng lượng hạt nhân có thể cung cấp nguồn điện ổn định, nhưng việc quản lý chất thải phóng xạ vẫn là một thách thức lớn.","audioKind":"ex2"}],"collocations":[{"en":"nuclear energy","vi":"năng lượng hạt nhân"},{"en":"nuclear power station","vi":"nhà máy điện hạt nhân"},{"en":"nuclear waste","vi":"chất thải hạt nhân"},{"en":"nuclear weapons","vi":"vũ khí hạt nhân"}],"wordFamily":["nucleus (n.)"],"synonyms":[],"antonyms":[],"tipVi":"nuclear có thể chỉ hạt nhân nguyên tử hoặc tế bào nhân, tùy thuộc vào ngữ cảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_formation', 'en-b2-69', 'formation', '/fɔːrˈmeɪʃən/', 'B2', 'sự hình thành; sự thành lập; cấu trúc tự nhiên; địa tầng; đội hình; sự sắp xếp theo trật tự', 'n.', 'form (v.), formative (adj.)', NULL, 'formation có thể chỉ quá trình hình thành, hoặc chỉ cấu trúc hay đội hình được tạo thành.', 'Cold nights encourage the formation of ice on puddles.', NULL, 'Những đêm trời lạnh tạo điều kiện cho băng hình thành trên các vũng nước.', '{"wordId":"formation","ukIpa":"/fɔːˈmeɪʃən/","usIpa":"/fɔːrˈmeɪʃən/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"The process of developing or bringing something into existence.","vi":"sự hình thành; sự thành lập"},{"pos":"n.","en":"A natural structure with a particular shape or arrangement.","vi":"cấu trúc tự nhiên; địa tầng"},{"pos":"n.","en":"An organised arrangement of people, vehicles, or animals.","vi":"đội hình; sự sắp xếp theo trật tự"}],"examples":[{"en":"Cold nights encourage the formation of ice on puddles.","vi":"Những đêm trời lạnh tạo điều kiện cho băng hình thành trên các vũng nước.","audioKind":"ex"},{"en":"Scientists study the formation of clouds to improve weather forecasts and understand changes in the global climate.","vi":"Các nhà khoa học nghiên cứu sự hình thành của các đám mây nhằm cải thiện dự báo thời tiết và thấu hiểu những biến đổi của khí hậu toàn cầu.","audioKind":"ex2"}],"collocations":[{"en":"cloud formation","vi":"sự hình thành mây"},{"en":"rock formations","vi":"cấu trúc đá"},{"en":"the formation of a government","vi":"việc thành lập chính phủ"},{"en":"fly in formation","vi":"bay theo đội hình"}],"wordFamily":["form (v.)","formative (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"formation có thể chỉ quá trình hình thành, hoặc chỉ cấu trúc hay đội hình được tạo thành.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_precisely', 'en-b2-69', 'precisely', '/prɪˈsaɪsli/', 'B2', 'chính xác; tỉ mỉ; đúng vậy; chính là', 'adv.', 'precise (adj.), precision (n.), imprecise (adj.), imprecisely (adv.)', 'Đồng nghĩa: exactly, accurately · Trái nghĩa: approximately, imprecisely', 'Cụm precisely because diễn tả ý nghĩa "chính là vì", dùng để nhấn mạnh nguyên nhân cốt lõi.', 'The carpenter cut each shelf precisely to fit the cupboard.', NULL, 'Thợ mộc đã cắt từng tấm ván một cách chính xác để vừa vặn khít với chiếc tủ.', '{"wordId":"precisely","ukIpa":"/prɪˈsaɪsli/","usIpa":"/prɪˈsaɪsli/","cefr":"B2","topic":"science","senses":[{"pos":"adv.","en":"Exactly and accurately, without any difference or error.","vi":"chính xác; tỉ mỉ"},{"pos":"adv.","en":"Used to emphasize that something is exactly the case.","vi":"đúng vậy; chính là"}],"examples":[{"en":"The carpenter cut each shelf precisely to fit the cupboard.","vi":"Thợ mộc đã cắt từng tấm ván một cách chính xác để vừa vặn khít với chiếc tủ.","audioKind":"ex"},{"en":"Researchers must measure changes in sea level precisely to assess the long-term effects of climate change.","vi":"Các nhà nghiên cứu bắt buộc phải đo đạc sự biến động mực nước biển thật chính xác nhằm đánh giá tác động lâu dài của biến đổi khí hậu.","audioKind":"ex2"}],"collocations":[{"en":"precisely measure","vi":"đo đạc chính xác"},{"en":"precisely define","vi":"xác định chính xác"},{"en":"precisely because","vi":"chính là vì"}],"wordFamily":["precise (adj.)","precision (n.)","imprecise (adj.)","imprecisely (adv.)"],"synonyms":["exactly","accurately"],"antonyms":["approximately","imprecisely"],"tipVi":"Cụm precisely because diễn tả ý nghĩa \"chính là vì\", dùng để nhấn mạnh nguyên nhân cốt lõi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rust', 'en-b2-69', 'rust', '/rʌst/', 'B2', 'gỉ sét, vảy sắt; bị gỉ, làm cho kim loại bị gỉ', 'n.', 'rusty (adj.), rustproof (adj.)', NULL, 'Kỹ năng bị mai một, gỉ sét thường dùng rusty: My French is rusty.', 'Orange rust covered the chain of my old bicycle.', NULL, 'Lớp gỉ sét màu cam phủ kín sợi xích chiếc xe đạp cũ của tôi.', '{"wordId":"rust","ukIpa":"/rʌst/","usIpa":"/rʌst/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A reddish-brown substance that forms on iron exposed to moisture.","vi":"gỉ sét, vảy sắt"},{"pos":"v.","en":"To develop rust or cause metal to develop rust.","vi":"bị gỉ, làm cho kim loại bị gỉ"}],"examples":[{"en":"Orange rust covered the chain of my old bicycle.","vi":"Lớp gỉ sét màu cam phủ kín sợi xích chiếc xe đạp cũ của tôi.","audioKind":"ex"},{"en":"Regular maintenance prevents steel bridges from rusting and reduces the long-term cost of infrastructure repairs.","vi":"Việc bảo trì định kỳ giúp ngăn chặn tình trạng gỉ sét ở các cây cầu thép và giảm chi phí sửa chữa cơ sở hạ tầng lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"remove rust","vi":"tẩy gỉ sét"},{"en":"prevent rust","vi":"chống gỉ"},{"en":"rust away","vi":"bị gỉ mòn đi"}],"wordFamily":["rusty (adj.)","rustproof (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Kỹ năng bị mai một, gỉ sét thường dùng rusty: My French is rusty.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_observation', 'en-b2-69', 'observation', '/ˌɑːbzɚˈveɪʃən/', 'B2', 'sự quan sát, sự theo dõi giám sát; nhận xét, ý kiến rút ra từ việc quan sát', 'n.', 'observe (v.), observer (n.), observant (adj.), observational (adj.)', 'Đồng nghĩa: monitoring, remark', 'Hành động quan sát thường là danh từ không đếm được; một ý kiến nhận xét quan sát là danh từ đếm được.', 'The doctor kept him in hospital overnight for observation.', NULL, 'Bác sĩ giữ anh ấy lại bệnh viện qua đêm để theo dõi.', '{"wordId":"observation","ukIpa":"/ˌɒbzəˈveɪʃən/","usIpa":"/ˌɑːbzɚˈveɪʃən/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"The act of watching carefully to learn or check something.","vi":"sự quan sát, sự theo dõi giám sát"},{"pos":"n.","en":"Something noticed or a comment based on what you notice.","vi":"nhận xét, ý kiến rút ra từ việc quan sát"}],"examples":[{"en":"The doctor kept him in hospital overnight for observation.","vi":"Bác sĩ giữ anh ấy lại bệnh viện qua đêm để theo dõi.","audioKind":"ex"},{"en":"Careful observation of children''s behaviour helps teachers identify learning difficulties and provide appropriate support at an early stage.","vi":"Việc quan sát kỹ lưỡng hành vi của trẻ nhỏ giúp giáo viên phát hiện các khó khăn trong học tập và đưa ra sự hỗ trợ thích hợp từ giai đoạn sớm.","audioKind":"ex2"}],"collocations":[{"en":"close observation","vi":"quan sát chặt chẽ"},{"en":"under observation","vi":"đang được theo dõi y tế"},{"en":"make an observation","vi":"đưa ra nhận xét"},{"en":"direct observation","vi":"quan sát trực tiếp"}],"wordFamily":["observe (v.)","observer (n.)","observant (adj.)","observational (adj.)"],"synonyms":["monitoring","remark"],"antonyms":[],"tipVi":"Hành động quan sát thường là danh từ không đếm được; một ý kiến nhận xét quan sát là danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ray', 'en-b2-69', 'ray', '/reɪ/', 'B2', 'tia sáng; chùm bức xạ; tia hy vọng; một chút ít; cá đuối', 'n.', NULL, 'Đồng nghĩa: beam', 'a ray of hope mang tính ẩn dụ, có nghĩa là "tia hy vọng".', 'A ray of sunlight fell across the sleeping cat.', NULL, 'Một tia nắng rọi qua chú mèo đang ngủ say.', '{"wordId":"ray","ukIpa":"/reɪ/","usIpa":"/reɪ/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A narrow beam of light or other radiation","vi":"tia sáng; chùm bức xạ"},{"pos":"n.","en":"A small amount of something positive","vi":"tia hy vọng; một chút ít"},{"pos":"n.","en":"A flat sea fish with broad fins and a long tail","vi":"cá đuối"}],"examples":[{"en":"A ray of sunlight fell across the sleeping cat.","vi":"Một tia nắng rọi qua chú mèo đang ngủ say.","audioKind":"ex"},{"en":"Excessive exposure to ultraviolet rays can damage the skin, making sun protection an important public health concern.","vi":"Tiếp xúc quá mức với tia cực tím có thể gây hại cho da, khiến việc chống nắng trở thành một vấn đề y tế cộng đồng quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"a ray of sunlight","vi":"một tia nắng"},{"en":"ultraviolet rays","vi":"tia cực tím"},{"en":"a ray of hope","vi":"một tia hy vọng"}],"wordFamily":[],"synonyms":["beam"],"antonyms":[],"tipVi":"a ray of hope mang tính ẩn dụ, có nghĩa là \"tia hy vọng\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sample', 'en-b2-69', 'sample', '/ˈsæmpəl/', 'B2', 'mẫu; mẫu vật; vật mẫu; lấy mẫu; nếm thử; trải nghiệm', 'n.', 'sampling (n.), sampler (n.)', 'Đồng nghĩa: specimen', 'sample nhấn mạnh phần được lấy ra từ một tổng thể; example thường dùng để làm ví dụ.', 'The baker offered us a sample of fresh bread.', NULL, 'Tiệm bánh đã cho chúng tôi một mẫu bánh mì tươi để ăn thử.', '{"wordId":"sample","ukIpa":"/ˈsɑːmpəl/","usIpa":"/ˈsæmpəl/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A small amount or group examined to understand a larger whole.","vi":"mẫu; mẫu vật; vật mẫu"},{"pos":"v.","en":"Take a small amount for testing, or try something.","vi":"lấy mẫu; nếm thử; trải nghiệm"}],"examples":[{"en":"The baker offered us a sample of fresh bread.","vi":"Tiệm bánh đã cho chúng tôi một mẫu bánh mì tươi để ăn thử.","audioKind":"ex"},{"en":"Researchers collected a representative sample of households to investigate changes in energy consumption across the region.","vi":"Các nhà nghiên cứu đã thu thập một mẫu hộ gia đình mang tính đại diện để điều tra sự thay đổi trong mức tiêu thụ năng lượng trên toàn khu vực.","audioKind":"ex2"}],"collocations":[{"en":"a representative sample","vi":"mẫu đại diện"},{"en":"a blood sample","vi":"mẫu máu"},{"en":"a free sample","vi":"mẫu miễn phí"},{"en":"sample local food","vi":"thưởng thức món ăn địa phương"}],"wordFamily":["sampling (n.)","sampler (n.)"],"synonyms":["specimen"],"antonyms":[],"tipVi":"sample nhấn mạnh phần được lấy ra từ một tổng thể; example thường dùng để làm ví dụ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_multiple', 'en-b2-69', 'multiple', '/ˈmʌltɪpəl/', 'B2', 'nhiều; phức hợp; đa; bội số', 'adj.', 'multiply (v.), multiplication (n.), multiplicity (n.)', 'Đồng nghĩa: numerous, several · Trái nghĩa: single', 'Khi mang nghĩa "nhiều", từ này thường bổ nghĩa cho danh từ số nhiều.', 'This charger works with multiple devices in our home.', NULL, 'Bộ sạc này tương thích với nhiều thiết bị trong nhà chúng tôi.', '{"wordId":"multiple","ukIpa":"/ˈmʌltɪpəl/","usIpa":"/ˈmʌltɪpəl/","cefr":"B2","topic":"science","senses":[{"pos":"adj.","en":"Involving or consisting of more than one person or thing.","vi":"nhiều; phức hợp; đa"},{"pos":"n.","en":"A number obtained by multiplying another number by an integer.","vi":"bội số"}],"examples":[{"en":"This charger works with multiple devices in our home.","vi":"Bộ sạc này tương thích với nhiều thiết bị trong nhà chúng tôi.","audioKind":"ex"},{"en":"Urban air pollution has multiple causes, including vehicle emissions, industrial activity, and the burning of household fuels.","vi":"Ô nhiễm không khí đô thị xuất phát từ nhiều nguyên nhân, bao gồm khí thải phương tiện giao thông, hoạt động công nghiệp và việc đốt nhiên liệu gia dụng.","audioKind":"ex2"}],"collocations":[{"en":"multiple causes","vi":"nhiều nguyên nhân"},{"en":"multiple choice","vi":"trắc nghiệm nhiều lựa chọn"},{"en":"multiple sources","vi":"nhiều nguồn"},{"en":"a multiple of","vi":"bội số của"}],"wordFamily":["multiply (v.)","multiplication (n.)","multiplicity (n.)"],"synonyms":["numerous","several"],"antonyms":["single"],"tipVi":"Khi mang nghĩa \"nhiều\", từ này thường bổ nghĩa cho danh từ số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_yeast', 'en-b2-69', 'yeast', '/jiːst/', 'B2', 'men; men nở; nấm men', 'n.', 'yeasty (adj.)', NULL, 'Trong làm bánh thường là danh từ không đếm được; khác với "baking powder" (bột nở).', 'Add the yeast once the water feels slightly warm.', NULL, 'Cho men vào khi nước bắt đầu hơi ấm.', '{"wordId":"yeast","ukIpa":"/jiːst/","usIpa":"/jiːst/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A fungus used to make bread rise and produce alcohol.","vi":"men; men nở; nấm men"}],"examples":[{"en":"Add the yeast once the water feels slightly warm.","vi":"Cho men vào khi nước bắt đầu hơi ấm.","audioKind":"ex"},{"en":"Scientists use yeast to study basic cellular processes because it grows quickly under controlled laboratory conditions.","vi":"Các nhà khoa học sử dụng nấm men để nghiên cứu các quá trình tế bào cơ bản vì chúng phát triển nhanh chóng trong điều kiện phòng thí nghiệm được kiểm soát.","audioKind":"ex2"}],"collocations":[{"en":"dried yeast","vi":"men khô"},{"en":"fresh yeast","vi":"men tươi"},{"en":"yeast fermentation","vi":"sự lên men của men"},{"en":"yeast cells","vi":"tế bào nấm men"}],"wordFamily":["yeasty (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong làm bánh thường là danh từ không đếm được; khác với \"baking powder\" (bột nở).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vapour', 'en-b2-69', 'vapour', '/ˈveɪpər/', 'B2', 'hơi nước; thể hơi', 'n.', 'vaporise (v.), vaporisation (n.)', NULL, 'Cách viết Anh-Anh là vapour, còn Anh-Mỹ là vapor.', 'Water vapour condensed into droplets on the cold window.', NULL, 'Hơi nước ngưng tụ thành các giọt nhỏ trên khung cửa sổ lạnh.', '{"wordId":"vapour","ukIpa":"/ˈveɪpə/","usIpa":"/ˈveɪpər/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A gas formed when a liquid or solid changes state.","vi":"hơi nước; thể hơi"}],"examples":[{"en":"Water vapour condensed into droplets on the cold window.","vi":"Hơi nước ngưng tụ thành các giọt nhỏ trên khung cửa sổ lạnh.","audioKind":"ex"},{"en":"As global temperatures rise, the atmosphere can hold more water vapour, which further strengthens the greenhouse effect.","vi":"Khi nhiệt độ toàn cầu tăng lên, bầu khí quyển có thể giữ lại nhiều hơi nước hơn, điều này làm cho hiệu ứng nhà kính càng mạnh thêm.","audioKind":"ex2"}],"collocations":[{"en":"water vapour","vi":"hơi nước"},{"en":"vapour pressure","vi":"áp suất hơi"},{"en":"release vapour","vi":"thải hơi"}],"wordFamily":["vaporise (v.)","vaporisation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cách viết Anh-Anh là vapour, còn Anh-Mỹ là vapor.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_classification', 'en-b2-69', 'classification', '/ˌklæsɪfɪˈkeɪʃən/', 'B2', 'sự phân loại; sự sắp xếp; loại; cấp bậc', 'n.', 'classify (v.), class (n.), classified (adj.)', 'Đồng nghĩa: categorisation', 'Cấu trúc classify A as B có nghĩa là "chia A vào nhóm B".', 'The library uses colour for the classification of books.', NULL, 'Thư viện sử dụng màu sắc để phân loại sách.', '{"wordId":"classification","ukIpa":"/ˌklæsɪfɪˈkeɪʃən/","usIpa":"/ˌklæsɪfɪˈkeɪʃən/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"The process of arranging things into groups by shared features.","vi":"sự phân loại; sự sắp xếp"},{"pos":"n.","en":"A category to which something is officially assigned.","vi":"loại; cấp bậc"}],"examples":[{"en":"The library uses colour for the classification of books.","vi":"Thư viện sử dụng màu sắc để phân loại sách.","audioKind":"ex"},{"en":"Accurate classification of species helps scientists understand biodiversity and identify ecosystems that require urgent protection.","vi":"Việc phân loại chính xác các loài giúp các nhà khoa học hiểu về đa dạng sinh học và xác định các hệ sinh thái cần được bảo vệ khẩn cấp.","audioKind":"ex2"}],"collocations":[{"en":"classification system","vi":"hệ thống phân loại"},{"en":"classification of species","vi":"phân loại loài"},{"en":"data classification","vi":"phân loại dữ liệu"}],"wordFamily":["classify (v.)","class (n.)","classified (adj.)"],"synonyms":["categorisation"],"antonyms":[],"tipVi":"Cấu trúc classify A as B có nghĩa là \"chia A vào nhóm B\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rectangular', 'en-b2-69', 'rectangular', '/rekˈtæŋɡjələr/', 'B2', 'hình chữ nhật', 'adj.', 'rectangle (n.)', NULL, 'Rectangle là danh từ; rectangular là tính từ.', 'We bought a rectangular table for the dining room.', NULL, 'Chúng tôi đã mua một chiếc bàn hình chữ nhật cho phòng ăn.', '{"wordId":"rectangular","ukIpa":"/rekˈtæŋɡjələ/","usIpa":"/rekˈtæŋɡjələr/","cefr":"B2","topic":"science","senses":[{"pos":"adj.","en":"Having four straight sides and four right angles","vi":"hình chữ nhật"}],"examples":[{"en":"We bought a rectangular table for the dining room.","vi":"Chúng tôi đã mua một chiếc bàn hình chữ nhật cho phòng ăn.","audioKind":"ex"},{"en":"Rectangular classrooms can accommodate rows of desks efficiently, although other layouts may encourage more group interaction.","vi":"Các phòng học hình chữ nhật có thể sắp xếp các dãy bàn một cách hiệu quả, mặc dù các kiểu bố trí khác có thể khuyến khích tương tác nhóm tốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"a rectangular table","vi":"một chiếc bàn hình chữ nhật"},{"en":"a rectangular shape","vi":"hình dáng chữ nhật"},{"en":"a rectangular plot","vi":"một mảnh đất hình chữ nhật"}],"wordFamily":["rectangle (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Rectangle là danh từ; rectangular là tính từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mass', 'en-b2-69', 'mass', '/mæs/', 'B2', 'đống lớn; khối lớn; lượng lớn; khối lượng; đại chúng; quy mô lớn', 'n.', 'massive (adj.), massively (adv.)', NULL, 'Trong vật lý, mass là khối lượng còn weight là trọng lượng, hai khái niệm này khác nhau.', 'A mass of tangled cables lay behind the desk.', NULL, 'Một đống dây cáp rối bù nằm ở phía sau bàn làm việc.', '{"wordId":"mass","ukIpa":"/mæs/","usIpa":"/mæs/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"a large amount of something gathered together","vi":"đống lớn; khối lớn; lượng lớn"},{"pos":"n.","en":"the amount of matter in an object","vi":"khối lượng"},{"pos":"adj.","en":"involving or affecting very large numbers of people","vi":"đại chúng; quy mô lớn"}],"examples":[{"en":"A mass of tangled cables lay behind the desk.","vi":"Một đống dây cáp rối bù nằm ở phía sau bàn làm việc.","audioKind":"ex"},{"en":"Mass production has made household goods more affordable, but it can also increase waste and resource consumption.","vi":"Việc sản xuất hàng loạt đã giúp các vật dụng gia đình trở nên phải chăng hơn, nhưng nó cũng làm tăng lượng rác thải và tiêu thụ tài nguyên.","audioKind":"ex2"}],"collocations":[{"en":"a mass of","vi":"một đống lớn; một lượng lớn"},{"en":"body mass","vi":"khối lượng cơ thể"},{"en":"mass production","vi":"sản xuất hàng loạt"},{"en":"mass media","vi":"phương tiện truyền thông đại chúng"}],"wordFamily":["massive (adj.)","massively (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong vật lý, mass là khối lượng còn weight là trọng lượng, hai khái niệm này khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fluid', 'en-b2-69', 'fluid', '/ˈfluːɪd/', 'B2', 'chất lỏng; lưu chất; dễ thay đổi; không cố định; mượt mà; uyển chuyển', 'n.', 'fluidity (n.)', 'Trái nghĩa: rigid', 'Trong ngữ cảnh hàng ngày, từ này thường chỉ chất lỏng; trong khoa học, fluid bao gồm cả chất khí.', 'The nurse reminded me to drink plenty of fluids.', NULL, 'Y tá nhắc tôi uống thật nhiều nước và các chất lỏng khác.', '{"wordId":"fluid","ukIpa":"/ˈfluːɪd/","usIpa":"/ˈfluːɪd/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"a substance that flows, such as a liquid or gas","vi":"chất lỏng; lưu chất"},{"pos":"adj.","en":"likely to change rather than remain fixed","vi":"dễ thay đổi; không cố định"},{"pos":"adj.","en":"moving smoothly and continuously","vi":"mượt mà; uyển chuyển"}],"examples":[{"en":"The nurse reminded me to drink plenty of fluids.","vi":"Y tá nhắc tôi uống thật nhiều nước và các chất lỏng khác.","audioKind":"ex"},{"en":"Employment patterns are increasingly fluid, requiring workers to update their skills throughout their professional lives.","vi":"Mô hình việc làm ngày càng biến động, đòi hỏi người lao động phải liên tục cập nhật kỹ năng trong suốt sự nghiệp chuyên môn của mình.","audioKind":"ex2"}],"collocations":[{"en":"body fluids","vi":"thể dịch; chất dịch trong cơ thể"},{"en":"fluid intake","vi":"lượng chất lỏng nạp vào"},{"en":"a fluid situation","vi":"tình hình biến động"},{"en":"fluid movements","vi":"chuyển động uyển chuyển"}],"wordFamily":["fluidity (n.)"],"synonyms":[],"antonyms":["rigid"],"tipVi":"Trong ngữ cảnh hàng ngày, từ này thường chỉ chất lỏng; trong khoa học, fluid bao gồm cả chất khí.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_copper', 'en-b2-69', 'copper', '/ˈkɑːpər/', 'B2', 'đồng (kim loại màu nâu đỏ); đồng xu bằng đồng', 'n.', NULL, NULL, 'Chỉ kim loại đồng (copper) là danh từ không đếm được; chỉ đồng xu (coppers) là danh từ đếm được.', 'The old kitchen sink has beautiful copper taps.', NULL, 'Bồn rửa chén cũ ở nhà bếp có những vòi nước bằng đồng rất đẹp.', '{"wordId":"copper","ukIpa":"/ˈkɒpə/","usIpa":"/ˈkɑːpər/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"a reddish-brown metal used for wires, pipes, and coins","vi":"đồng (kim loại màu nâu đỏ)"},{"pos":"n.","en":"a coin made of copper or a similar metal","vi":"đồng xu bằng đồng"}],"examples":[{"en":"The old kitchen sink has beautiful copper taps.","vi":"Bồn rửa chén cũ ở nhà bếp có những vòi nước bằng đồng rất đẹp.","audioKind":"ex"},{"en":"Copper is widely used in electrical systems because it conducts electricity efficiently and can be recycled.","vi":"Đồng được sử dụng rộng rãi trong các hệ thống điện vì khả năng dẫn điện hiệu quả và có thể tái chế.","audioKind":"ex2"}],"collocations":[{"en":"copper wire","vi":"dây đồng"},{"en":"copper pipe","vi":"ống đồng"},{"en":"copper mine","vi":"mỏ đồng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ kim loại đồng (copper) là danh từ không đếm được; chỉ đồng xu (coppers) là danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_comet', 'en-b2-69', 'comet', '/ˈkɑːmɪt/', 'B2', 'sao chổi', 'n.', NULL, NULL, 'comet là sao chổi; meteor là sao băng phát sáng khi đi vào bầu khí quyển.', 'We watched a bright comet through my uncle''s telescope.', NULL, 'Chúng tôi đã quan sát một ngôi sao chổi sáng qua kính thiên văn của chú tôi.', '{"wordId":"comet","ukIpa":"/ˈkɒmɪt/","usIpa":"/ˈkɑːmɪt/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"An icy object orbiting the sun, sometimes showing a bright tail","vi":"sao chổi"}],"examples":[{"en":"We watched a bright comet through my uncle''s telescope.","vi":"Chúng tôi đã quan sát một ngôi sao chổi sáng qua kính thiên văn của chú tôi.","audioKind":"ex"},{"en":"Studying a comet can provide valuable evidence about the conditions in which our solar system formed.","vi":"Nghiên cứu một sao chổi có thể cung cấp bằng chứng quý giá về điều kiện hình thành hệ mặt trời của chúng ta.","audioKind":"ex2"}],"collocations":[{"en":"a comet''s tail","vi":"đuôi sao chổi"},{"en":"a passing comet","vi":"sao chổi đi qua"},{"en":"observe a comet","vi":"quan sát sao chổi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"comet là sao chổi; meteor là sao băng phát sáng khi đi vào bầu khí quyển.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_evolution', 'en-b2-69', 'evolution', '/ˌevəˈluːʃən/', 'B2', 'sự tiến hóa; sự tiến triển; sự phát triển dần dần', 'n.', 'evolve (v.), evolutionary (adj.)', NULL, 'evolution chỉ sự tiến hóa; thuyết tiến hóa dùng the theory of evolution.', 'The museum uses bird skeletons to explain evolution.', NULL, 'Viện bảo tàng sử dụng bộ xương loài chim để giải thích quá trình tiến hóa.', '{"wordId":"evolution","ukIpa":"/ˌiːvəˈluːʃən/","usIpa":"/ˌevəˈluːʃən/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"Gradual changes in living things over many generations.","vi":"sự tiến hóa"},{"pos":"n.","en":"The gradual development of something over time.","vi":"sự tiến triển; sự phát triển dần dần"}],"examples":[{"en":"The museum uses bird skeletons to explain evolution.","vi":"Viện bảo tàng sử dụng bộ xương loài chim để giải thích quá trình tiến hóa.","audioKind":"ex"},{"en":"The evolution of digital technology has transformed how people communicate, study and access public services.","vi":"Sự tiến triển của công nghệ số đã thay đổi cách mọi người giao tiếp, học tập và tiếp cận các dịch vụ công.","audioKind":"ex2"}],"collocations":[{"en":"the theory of evolution","vi":"thuyết tiến hóa"},{"en":"human evolution","vi":"sự tiến hóa của loài người"},{"en":"biological evolution","vi":"sự tiến hóa sinh học"},{"en":"the evolution of technology","vi":"sự phát triển của công nghệ"}],"wordFamily":["evolve (v.)","evolutionary (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"evolution chỉ sự tiến hóa; thuyết tiến hóa dùng the theory of evolution.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aluminum', 'en-b2-69', 'aluminum', '/əˈluːmɪnəm/', 'B2', 'nhôm', 'n.', NULL, NULL, 'Đây là cách viết theo kiểu Mỹ; tiếng Anh-Anh thường viết là aluminium, và cách phát âm cũng khác nhau.', 'This aluminum ladder is light enough to carry alone.', NULL, 'Chiếc thang nhôm này rất nhẹ nên một mình có thể khiêng được.', '{"wordId":"aluminum","ukIpa":"/əˈluːmɪnəm/","usIpa":"/əˈluːmɪnəm/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A light, silvery metal used for cans, foil, and aircraft.","vi":"nhôm"}],"examples":[{"en":"This aluminum ladder is light enough to carry alone.","vi":"Chiếc thang nhôm này rất nhẹ nên một mình có thể khiêng được.","audioKind":"ex"},{"en":"Recycling aluminum requires substantially less energy than producing new metal from ore, reducing the environmental impact of manufacturing.","vi":"Việc tái chế nhôm tiêu tốn ít năng lượng hơn đáng kể so với việc sản xuất kim loại mới từ quặng, qua đó giúp giảm thiểu tác động môi trường trong ngành sản xuất.","audioKind":"ex2"}],"collocations":[{"en":"aluminum foil","vi":"lá nhôm"},{"en":"aluminum cans","vi":"lon nhôm"},{"en":"aluminum alloy","vi":"hợp kim nhôm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Đây là cách viết theo kiểu Mỹ; tiếng Anh-Anh thường viết là aluminium, và cách phát âm cũng khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_static', 'en-b2-69', 'static', '/ˈstætɪk/', 'B2', 'đứng yên; không thay đổi; thuộc về tĩnh điện; hiện tượng tĩnh điện; nhiễu tĩnh điện', 'adj.', 'statically (adv.)', 'Đồng nghĩa: unchanging, motionless · Trái nghĩa: dynamic', 'Tính từ static nhấn mạnh sự không di chuyển hoặc không thay đổi; hiện tượng tĩnh điện dùng cụm từ static electricity.', 'The television picture stayed static while the sound continued.', NULL, 'Hình ảnh trên TV đứng yên trong khi âm thanh vẫn tiếp tục phát.', '{"wordId":"static","ukIpa":"/ˈstætɪk/","usIpa":"/ˈstætɪk/","cefr":"B2","topic":"science","senses":[{"pos":"adj.","en":"not moving, changing, or developing","vi":"đứng yên; không thay đổi"},{"pos":"adj.","en":"relating to electric charges that build up on surfaces","vi":"thuộc về tĩnh điện"},{"pos":"n.","en":"electrical interference or an electric charge collected on a surface","vi":"hiện tượng tĩnh điện; nhiễu tĩnh điện"}],"examples":[{"en":"The television picture stayed static while the sound continued.","vi":"Hình ảnh trên TV đứng yên trong khi âm thanh vẫn tiếp tục phát.","audioKind":"ex"},{"en":"Wages have remained static for several years, while housing costs have risen steadily in major cities.","vi":"Tiền lương vẫn giữ nguyên trong vài năm qua, trong khi chi phí nhà ở tại các thành phố lớn liên tục tăng.","audioKind":"ex2"}],"collocations":[{"en":"remain static","vi":"giữ nguyên không đổi"},{"en":"static electricity","vi":"tĩnh điện"},{"en":"static image","vi":"hình ảnh tĩnh"}],"wordFamily":["statically (adv.)"],"synonyms":["unchanging","motionless"],"antonyms":["dynamic"],"tipVi":"Tính từ static nhấn mạnh sự không di chuyển hoặc không thay đổi; hiện tượng tĩnh điện dùng cụm từ static electricity.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_69_1', 'en-b2-69', 'Cách dùng “static” (adj.) — đứng yên; không thay đổi', 'remain static  ·  static electricity  ·  static image', 'Tính từ static nhấn mạnh sự không di chuyển hoặc không thay đổi; hiện tượng tĩnh điện dùng cụm từ static electricity.', 'Họ từ (Word Family): statically (adv.) | Đồng nghĩa: unchanging, motionless · Trái nghĩa: dynamic', '[{"hanzi":"The television picture stayed static while the sound continued.","pinyin":"","meaning":"Hình ảnh trên TV đứng yên trong khi âm thanh vẫn tiếp tục phát."},{"hanzi":"Wages have remained static for several years, while housing costs have risen steadily in major cities.","pinyin":"","meaning":"Tiền lương vẫn giữ nguyên trong vài năm qua, trong khi chi phí nhà ở tại các thành phố lớn liên tục tăng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_69_2', 'en-b2-69', 'Cách dùng “theory” (n.) — lý thuyết; học thuyết', 'in theory  ·  support a theory  ·  test a theory', '"in theory" có nghĩa là "về mặt lý thuyết", thường được dùng để đối chiếu với "in practice" (trên thực tế).', 'Họ từ (Word Family): theoretical (adj.), theoretically (adv.), theorist (n.), theorise (v.)', '[{"hanzi":"My theory is that the cat knocked the cup over.","pinyin":"","meaning":"Tôi đoán là con mèo đã làm đổ cái cốc."},{"hanzi":"Students benefit from courses that connect scientific theory with practical experiments and problems from everyday life.","pinyin":"","meaning":"Học sinh được hưởng lợi từ các khóa học kết nối lý thuyết khoa học với các thí nghiệm thực hành và những vấn đề trong đời sống hằng ngày."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_69_3', 'en-b2-69', 'Cách dùng “observation” (n.) — sự quan sát, sự theo dõi giám sát', 'close observation  ·  under observation  ·  make an observation', 'Hành động quan sát thường là danh từ không đếm được; một ý kiến nhận xét quan sát là danh từ đếm được.', 'Họ từ (Word Family): observe (v.), observer (n.), observant (adj.), observational (adj.) | Đồng nghĩa: monitoring, remark', '[{"hanzi":"The doctor kept him in hospital overnight for observation.","pinyin":"","meaning":"Bác sĩ giữ anh ấy lại bệnh viện qua đêm để theo dõi."},{"hanzi":"Careful observation of children''s behaviour helps teachers identify learning difficulties and provide appropriate support at an early stage.","pinyin":"","meaning":"Việc quan sát kỹ lưỡng hành vi của trẻ nhỏ giúp giáo viên phát hiện các khó khăn trong học tập và đưa ra sự hỗ trợ thích hợp từ giai đoạn sớm."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_69_4', 'en-b2-69', 'Cách dùng “aluminum” (n.) — nhôm', 'aluminum foil  ·  aluminum cans  ·  aluminum alloy', 'Đây là cách viết theo kiểu Mỹ; tiếng Anh-Anh thường viết là aluminium, và cách phát âm cũng khác nhau.', NULL, '[{"hanzi":"This aluminum ladder is light enough to carry alone.","pinyin":"","meaning":"Chiếc thang nhôm này rất nhẹ nên một mình có thể khiêng được."},{"hanzi":"Recycling aluminum requires substantially less energy than producing new metal from ore, reducing the environmental impact of manufacturing.","pinyin":"","meaning":"Việc tái chế nhôm tiêu tốn ít năng lượng hơn đáng kể so với việc sản xuất kim loại mới từ quặng, qua đó giúp giảm thiểu tác động môi trường trong ngành sản xuất."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_69_1', 'en-b2-69', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_69_1_1', 'ten_b2_69_1', 'theory', 'My theory is that the cat knocked the cup over.', 'My theory is that the cat knocked the cup over.', '/ˈθɪri/', 'Tôi đoán là con mèo đã làm đổ cái cốc.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
