INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_69_1_8', 'ten_b2_69_1', 'precisely', 'The carpenter cut each shelf precisely to fit the cupboard.', 'The carpenter cut each shelf precisely to fit the cupboard.', '/prɪˈsaɪsli/', 'Thợ mộc đã cắt từng tấm ván một cách chính xác để vừa vặn khít với chiếc tủ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_69_1_1', 'en-b2-69', 'ten_b2_69_1', 'listening', 'listening', 'My theory is that the cat knocked the cup over.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Lớp gỉ sét màu cam phủ kín sợi xích chiếc xe đạp cũ của tôi.","Tôi đoán là con mèo đã làm đổ cái cốc.","Hình ảnh trên TV đứng yên trong khi âm thanh vẫn tiếp tục phát.","Thư viện sử dụng màu sắc để phân loại sách."]'::jsonb, 1, 'My theory is that the cat knocked the cup over. → Tôi đoán là con mèo đã làm đổ cái cốc.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_69_1_2', 'en-b2-69', 'ten_b2_69_1', 'listening', 'listening', 'The thin fishing line was almost invisible underwater.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chiếc cân nhà bếp này đủ độ chính xác để làm bánh mì.","Cho men vào khi nước bắt đầu hơi ấm.","Đường câu mảnh đến mức gần như vô hình dưới nước.","Thợ mộc đã cắt từng tấm ván một cách chính xác để vừa vặn khít với chiếc tủ."]'::jsonb, 2, 'The thin fishing line was almost invisible underwater. → Đường câu mảnh đến mức gần như vô hình dưới nước.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_69_1_3', 'en-b2-69', 'ten_b2_69_1', 'listening', 'listening', 'This new treatment is a major advance in medicine.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Anh họ tôi làm việc tại một nhà máy điện hạt nhân gần đây.","Tôi đoán là con mèo đã làm đổ cái cốc.","Hình ảnh trên TV đứng yên trong khi âm thanh vẫn tiếp tục phát.","Phương pháp điều trị mới này là một bước tiến lớn trong y học."]'::jsonb, 3, 'This new treatment is a major advance in medicine. → Phương pháp điều trị mới này là một bước tiến lớn trong y học.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_69_2', 'en-b2-69', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_69_2_1', 'ten_b2_69_2', 'theory', 'Students benefit from courses that connect scientific theory with practical experiments and problems from everyday life.', 'Students benefit from courses that connect scientific theory with practical experiments and problems from everyday life.', '/ˈθɪri/', 'Học sinh được hưởng lợi từ các khóa học kết nối lý thuyết khoa học với các thí nghiệm thực hành và những vấn đề trong đời sống hằng ngày.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_69_2_2', 'ten_b2_69_2', 'invisible', 'Although many air pollutants are invisible, prolonged exposure can seriously damage respiratory health, particularly among children.', 'Although many air pollutants are invisible, prolonged exposure can seriously damage respiratory health, particularly among children.', '/ɪnˈvɪzəbl/', 'Mặc dù nhiều chất ô nhiễm không khí là vô hình, việc tiếp xúc kéo dài có thể gây tổn hại nghiêm trọng đến sức khỏe hô hấp, đặc biệt là ở trẻ em.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_69_2_3', 'ten_b2_69_2', 'advance', 'Advances in renewable energy technology could reduce dependence on fossil fuels and improve long-term energy security.', 'Advances in renewable energy technology could reduce dependence on fossil fuels and improve long-term energy security.', '/ədˈvæns/', 'Những tiến bộ trong công nghệ năng lượng tái tạo có thể làm giảm sự phụ thuộc vào nhiên liệu hóa thạch và nâng cao an ninh năng lượng lâu dài.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_69_2_4', 'ten_b2_69_2', 'spark', 'Investment in public libraries can spark interest in reading and provide valuable learning opportunities for disadvantaged children.', 'Investment in public libraries can spark interest in reading and provide valuable learning opportunities for disadvantaged children.', '/spɑːrk/', 'Việc đầu tư vào các thư viện công cộng có thể khơi dậy niềm đam mê đọc sách và mang lại cơ hội học tập giá trị cho trẻ em có hoàn cảnh khó khăn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_69_2_5', 'ten_b2_69_2', 'accurate', 'Accurate information about air quality enables residents to make informed decisions about outdoor exercise.', 'Accurate information about air quality enables residents to make informed decisions about outdoor exercise.', '/ˈækjərət/', 'Thông tin chính xác về chất lượng không khí giúp cư dân đưa ra quyết định sáng suốt về việc tập thể dục ngoài trời.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_69_2_6', 'ten_b2_69_2', 'nuclear', 'Nuclear energy can provide reliable electricity, but managing radioactive waste remains a major challenge.', 'Nuclear energy can provide reliable electricity, but managing radioactive waste remains a major challenge.', '/ˈnuːkliər/', 'Năng lượng hạt nhân có thể cung cấp nguồn điện ổn định, nhưng việc quản lý chất thải phóng xạ vẫn là một thách thức lớn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_69_2_1', 'en-b2-69', 'ten_b2_69_2', 'listening', 'listening', 'Students benefit from courses that connect scientific theory with practical experiments and problems from everyday life.', NULL, 'Trong câu vừa nghe, từ “theory” mang nghĩa nào sau đây?', '["chậu rửa; vũng nước","sự nhiệt tình; sự hăng hái","lẫn nhau; qua lại","lý thuyết; học thuyết"]'::jsonb, 3, '“theory” (/ˈθɪri/): lý thuyết; học thuyết. Câu đầy đủ: Students benefit from courses that connect scientific theory with practical experiments and problems from everyday life.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_69_2_2', 'en-b2-69', 'ten_b2_69_2', 'listening', 'listening', 'Although many air pollutants are invisible, prolonged exposure can seriously damage respiratory health, particularly among children.', NULL, 'Trong câu vừa nghe, từ “invisible” mang nghĩa nào sau đây?', '["vô hình; không nhìn thấy được","khiêm tốn","đầu hàng, chịu khuất phục trước sự kiểm soát của phe khác","vỗ; đập; bay phần phật"]'::jsonb, 0, '“invisible” (/ɪnˈvɪzəbl/): vô hình; không nhìn thấy được. Câu đầy đủ: Although many air pollutants are invisible, prolonged exposure can seriously damage respiratory health, particularly among children.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
