INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_69_1', 'en-b2-69', NULL, 'comprehensive_test', 'listening', 'theory', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nhập cư; chuyển đến sinh sống lâu dài ở một quốc gia khác","làm mềm; trở nên mềm hơn","lý thuyết; học thuyết","toàn diện; bao quát; chi tiết"]'::jsonb, 2, 'theory (/ˈθɪri/) → lý thuyết; học thuyết; giả thuyết; sự suy đoán; kiến thức lý thuyết', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_69_2', 'en-b2-69', NULL, 'comprehensive_test', 'listening', 'The thin fishing line was almost invisible underwater.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Thợ mộc đã cắt từng tấm ván một cách chính xác để vừa vặn khít với chiếc tủ.","Bác sĩ giữ anh ấy lại bệnh viện qua đêm để theo dõi.","Đường câu mảnh đến mức gần như vô hình dưới nước.","Những đêm trời lạnh tạo điều kiện cho băng hình thành trên các vũng nước."]'::jsonb, 2, 'The thin fishing line was almost invisible underwater. → Đường câu mảnh đến mức gần như vô hình dưới nước.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_69_3', 'en-b2-69', NULL, 'comprehensive_test', 'listening', 'advance', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đã đăng ký; đã ghi danh","sự tiến bộ; bước tiến; sự phát triển","vô cùng, hết sức, sâu sắc (về cảm xúc hoặc niềm tin)","làm phẳng; san phẳng"]'::jsonb, 1, 'advance (/ədˈvæns/) → sự tiến bộ; bước tiến; sự phát triển; tiến lên; thúc đẩy; phát triển; trước; chuẩn bị trước', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_69_4', 'en-b2-69', NULL, 'comprehensive_test', 'listening', 'A tiny spark flew out of the fireplace.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chiếc cân nhà bếp này đủ độ chính xác để làm bánh mì.","Y tá nhắc tôi uống thật nhiều nước và các chất lỏng khác.","Một tia lửa nhỏ bắn ra từ lò sưởi.","Một đống dây cáp rối bù nằm ở phía sau bàn làm việc."]'::jsonb, 2, 'A tiny spark flew out of the fireplace. → Một tia lửa nhỏ bắn ra từ lò sưởi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_69_5', 'en-b2-69', NULL, 'comprehensive_test', 'listening', 'accurate', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chính xác; đúng đắn","không đáng kể; nhỏ nhặt","sự phòng ngừa; sự ngăn chặn","sự nhập cư; việc di cư vào nước khác"]'::jsonb, 0, 'accurate (/ˈækjərət/) → chính xác; đúng đắn; chuẩn xác; trúng đích', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_69_6', 'en-b2-69', NULL, 'comprehensive_test', 'listening', 'My cousin works at a nearby nuclear power station.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Anh họ tôi làm việc tại một nhà máy điện hạt nhân gần đây.","Cho men vào khi nước bắt đầu hơi ấm.","Bồn rửa chén cũ ở nhà bếp có những vòi nước bằng đồng rất đẹp.","Lớp gỉ sét màu cam phủ kín sợi xích chiếc xe đạp cũ của tôi."]'::jsonb, 0, 'My cousin works at a nearby nuclear power station. → Anh họ tôi làm việc tại một nhà máy điện hạt nhân gần đây.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_69_7', 'en-b2-69', NULL, 'comprehensive_test', 'listening', 'formation', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự hình thành; sự thành lập","bạn đồng hành; người bầu bạn; thú cưng bầu bạn","đánh giá, thẩm định chất lượng, giá trị hoặc hiệu quả của cái gì","cái cày"]'::jsonb, 0, 'formation (/fɔːrˈmeɪʃən/) → sự hình thành; sự thành lập; cấu trúc tự nhiên; địa tầng; đội hình; sự sắp xếp theo trật tự', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_69_8', 'en-b2-69', NULL, 'comprehensive_test', 'listening', 'The carpenter cut each shelf precisely to fit the cupboard.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã quan sát một ngôi sao chổi sáng qua kính thiên văn của chú tôi.","Thợ mộc đã cắt từng tấm ván một cách chính xác để vừa vặn khít với chiếc tủ.","Lớp gỉ sét màu cam phủ kín sợi xích chiếc xe đạp cũ của tôi.","Phương pháp điều trị mới này là một bước tiến lớn trong y học."]'::jsonb, 1, 'The carpenter cut each shelf precisely to fit the cupboard. → Thợ mộc đã cắt từng tấm ván một cách chính xác để vừa vặn khít với chiếc tủ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
