INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_69_18', 'en-b2-69', NULL, 'comprehensive_test', 'reading', NULL, 'Students benefit from courses that connect scientific theory with practical experiments and problems from everyday life.', 'Dựa vào câu trên, từ “theory” có nghĩa phù hợp nhất là gì?', '["mềm; dễ nhai; dễ cắt","lý thuyết; học thuyết","thợ thủ công; nghệ nhân","quan sát; để ý"]'::jsonb, 1, 'theory: lý thuyết; học thuyết; giả thuyết; sự suy đoán; kiến thức lý thuyết. Dịch cả câu: Học sinh được hưởng lợi từ các khóa học kết nối lý thuyết khoa học với các thí nghiệm thực hành và những vấn đề trong đời sống hằng ngày.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_69_19', 'en-b2-69', NULL, 'comprehensive_test', 'reading', NULL, 'Although many air pollutants are invisible, prolonged exposure can seriously damage respiratory health, particularly among children.', 'Dựa vào câu trên, từ “invisible” có nghĩa phù hợp nhất là gì?', '["sự sẵn lòng; tinh thần tự nguyện","vô hình; không nhìn thấy được","tốt hơn; chất lượng cao hơn","thuộc về răng; nha khoa"]'::jsonb, 1, 'invisible: vô hình; không nhìn thấy được; không được chú ý; bị phớt lờ. Dịch cả câu: Mặc dù nhiều chất ô nhiễm không khí là vô hình, việc tiếp xúc kéo dài có thể gây tổn hại nghiêm trọng đến sức khỏe hô hấp, đặc biệt là ở trẻ em.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_69_20', 'en-b2-69', NULL, 'comprehensive_test', 'reading', NULL, 'Advances in renewable energy technology could reduce dependence on fossil fuels and improve long-term energy security.', 'Dựa vào câu trên, từ “advance” có nghĩa phù hợp nhất là gì?', '["kẻ hèn nhát; đồ nhát gan","vận chuyển trái phép; buôn lậu; lén mang vào","sự tắc nghẽn; vật cản; chỗ nghẽn","sự tiến bộ; bước tiến; sự phát triển"]'::jsonb, 3, 'advance: sự tiến bộ; bước tiến; sự phát triển; tiến lên; thúc đẩy; phát triển; trước; chuẩn bị trước. Dịch cả câu: Những tiến bộ trong công nghệ năng lượng tái tạo có thể làm giảm sự phụ thuộc vào nhiên liệu hóa thạch và nâng cao an ninh năng lượng lâu dài.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_69_21', 'en-b2-69', NULL, 'comprehensive_test', 'reading', NULL, 'Investment in public libraries can spark interest in reading and provide valuable learning opportunities for disadvantaged children.', 'Dựa vào câu trên, từ “spark” có nghĩa phù hợp nhất là gì?', '["thủy triều; nước thủy triều","tia lửa; tia điện","mối nguy hiểm; hiểm họa","sự việc; sự cố"]'::jsonb, 1, 'spark: tia lửa; tia điện; khơi nguồn; châm ngòi; kích thích; một chút; nhân tố khởi phát. Dịch cả câu: Việc đầu tư vào các thư viện công cộng có thể khơi dậy niềm đam mê đọc sách và mang lại cơ hội học tập giá trị cho trẻ em có hoàn cảnh khó khăn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_69_22', 'en-b2-69', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự tiến hóa”', '["immigrate","craftsman","wink","evolution"]'::jsonb, 3, 'sự tiến hóa → evolution (/ˌevəˈluːʃən/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
