INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_69_24', 'en-b2-69', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đứng yên; không thay đổi”', '["static","swell","twist","astonish"]'::jsonb, 0, 'đứng yên; không thay đổi → static (/ˈstætɪk/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-70', 'en', 'Bài 70: Khoa học & Nghiên cứu (4) - CEFR B2', 'CEFR B2', 'B2 · Khoa học', '24 từ vựng Tiếng Anh CEFR B2 chủ đề khoa học & nghiên cứu kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4070, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_oxygen', 'en-b2-70', 'oxygen', '/ˈɑːksɪdʒən/', 'B2', 'oxi; khí oxy', 'n.', 'oxygenate (v.), oxygenation (n.)', NULL, 'Oxygen là danh từ không đếm được, không dùng mạo từ an trước nó.', 'The nurse gave him oxygen through a clear plastic mask.', NULL, 'Y tá đã cho ông ấy thở oxy thông qua một chiếc mặt nạ nhựa trong suốt.', '{"wordId":"oxygen","ukIpa":"/ˈɒksɪdʒən/","usIpa":"/ˈɑːksɪdʒən/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A gas needed by most living things for life.","vi":"oxi; khí oxy"}],"examples":[{"en":"The nurse gave him oxygen through a clear plastic mask.","vi":"Y tá đã cho ông ấy thở oxy thông qua một chiếc mặt nạ nhựa trong suốt.","audioKind":"ex"},{"en":"Pollution can reduce oxygen levels in rivers, making it difficult for fish and other aquatic organisms to survive.","vi":"Tình trạng ô nhiễm có thể làm giảm nồng độ oxy trong các con sông, khiến cá và các sinh vật dưới nước khác khó sinh sống.","audioKind":"ex2"}],"collocations":[{"en":"oxygen supply","vi":"nguồn cung cấp oxy"},{"en":"oxygen levels","vi":"nồng độ oxy"},{"en":"lack of oxygen","vi":"sự thiếu oxy"},{"en":"oxygen mask","vi":"mặt nạ dưỡng khí"}],"wordFamily":["oxygenate (v.)","oxygenation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Oxygen là danh từ không đếm được, không dùng mạo từ an trước nó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_random', 'en-b2-70', 'random', '/ˈrændəm/', 'B2', 'ngẫu nhiên; tùy tiện; không theo quy luật', 'adj.', 'randomly (adv), randomness (n), randomise (v)', 'Đồng nghĩa: haphazard · Trái nghĩa: systematic', 'Từ "random" là tính từ; khi làm trạng ngữ, dùng "randomly" hoặc "at random".', 'I opened the cookbook at a random page.', NULL, 'Tôi tùy tiện mở một trang trong cuốn sách nấu ăn.', '{"wordId":"random","ukIpa":"/ˈrændəm/","usIpa":"/ˈrændəm/","cefr":"B2","topic":"science","senses":[{"pos":"adj.","en":"Chosen or happening without a fixed pattern or deliberate plan.","vi":"ngẫu nhiên; tùy tiện; không theo quy luật"}],"examples":[{"en":"I opened the cookbook at a random page.","vi":"Tôi tùy tiện mở một trang trong cuốn sách nấu ăn.","audioKind":"ex"},{"en":"Researchers selected a random sample of households to assess public attitudes towards renewable energy.","vi":"Các nhà nghiên cứu đã chọn một mẫu ngẫu nhiên gồm các hộ gia đình để đánh giá thái độ của công chúng đối với năng lượng tái tạo.","audioKind":"ex2"}],"collocations":[{"en":"random sample","vi":"mẫu ngẫu nhiên"},{"en":"random selection","vi":"sự lựa chọn ngẫu nhiên"},{"en":"at random","vi":"một cách ngẫu nhiên"}],"wordFamily":["randomly (adv)","randomness (n)","randomise (v)"],"synonyms":["haphazard"],"antonyms":["systematic"],"tipVi":"Từ \"random\" là tính từ; khi làm trạng ngữ, dùng \"randomly\" hoặc \"at random\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_statistical', 'en-b2-70', 'statistical', '/stəˈtɪstɪkəl/', 'B2', 'thuộc về thống kê, liên quan đến thu thập và phân tích dữ liệu số', 'adj.', 'statistics (n.), statistic (n.), statistically (adv.), statistician (n.)', NULL, 'statistical chỉ các vấn đề liên quan đến thống kê, không đồng nghĩa với "đáng chú ý" hay "nổi bật".', 'She used statistical software to compare the survey results.', NULL, 'Cô ấy đã sử dụng phần mềm thống kê để so sánh các kết quả khảo sát.', '{"wordId":"statistical","ukIpa":"/stəˈtɪstɪkəl/","usIpa":"/stəˈtɪstɪkəl/","cefr":"B2","topic":"science","senses":[{"pos":"adj.","en":"relating to collecting, studying, or interpreting numerical data","vi":"thuộc về thống kê, liên quan đến thu thập và phân tích dữ liệu số"}],"examples":[{"en":"She used statistical software to compare the survey results.","vi":"Cô ấy đã sử dụng phần mềm thống kê để so sánh các kết quả khảo sát.","audioKind":"ex"},{"en":"Reliable statistical evidence helps governments identify communities that need better access to healthcare.","vi":"Bằng chứng thống kê đáng tin cậy giúp chính phủ xác định các cộng đồng cần được tiếp cận dịch vụ y tế tốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"statistical analysis","vi":"phân tích thống kê"},{"en":"statistical data","vi":"dữ liệu thống kê"},{"en":"statistical significance","vi":"ý nghĩa thống kê"}],"wordFamily":["statistics (n.)","statistic (n.)","statistically (adv.)","statistician (n.)"],"synonyms":[],"antonyms":[],"tipVi":"statistical chỉ các vấn đề liên quan đến thống kê, không đồng nghĩa với \"đáng chú ý\" hay \"nổi bật\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_saturn', 'en-b2-70', 'Saturn', '/ˈsætərn/', 'B2', 'sao Thổ', 'n.', NULL, NULL, 'Tên các hành tinh viết hoa chữ cái đầu và thường không dùng mạo từ.', 'We saw Saturn through a telescope last night.', NULL, 'Đêm qua chúng tôi nhìn thấy sao Thổ qua kính viễn vọng.', '{"wordId":"saturn","ukIpa":"/ˈsætən/","usIpa":"/ˈsætərn/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"the sixth planet from the Sun, surrounded by prominent rings","vi":"sao Thổ"}],"examples":[{"en":"We saw Saturn through a telescope last night.","vi":"Đêm qua chúng tôi nhìn thấy sao Thổ qua kính viễn vọng.","audioKind":"ex"},{"en":"Studying the rings of Saturn helps scientists understand how particles interact in space over time.","vi":"Việc nghiên cứu các vành đai của sao Thổ giúp các nhà khoa học hiểu được các hạt tương tác với nhau trong không gian theo thời gian như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"the rings of Saturn","vi":"vành đai sao Thổ"},{"en":"Saturn''s moons","vi":"các vệ tinh của sao Thổ"},{"en":"orbit Saturn","vi":"xoay quanh sao Thổ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tên các hành tinh viết hoa chữ cái đầu và thường không dùng mạo từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_probability', 'en-b2-70', 'probability', '/ˌprɑːbəˈbɪləti/', 'B2', 'xác suất; khả năng xảy ra', 'n.', 'probable (adj.), probably (adv.), improbable (adj.)', 'Đồng nghĩa: likelihood, chance', 'Thường đi kèm với giới từ of theo sau là danh từ hoặc danh động từ; cũng có thể theo sau bởi mệnh đề that.', 'Dark clouds suggest a high probability of rain tonight.', NULL, 'Mây đen cho thấy khả năng cao trời sẽ mưa tối nay.', '{"wordId":"probability","ukIpa":"/ˌprɒbəˈbɪləti/","usIpa":"/ˌprɑːbəˈbɪləti/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"how likely something is to happen","vi":"xác suất; khả năng xảy ra"}],"examples":[{"en":"Dark clouds suggest a high probability of rain tonight.","vi":"Mây đen cho thấy khả năng cao trời sẽ mưa tối nay.","audioKind":"ex"},{"en":"Improved weather models allow scientists to estimate the probability of extreme rainfall with greater accuracy.","vi":"Các mô hình thời tiết được cải tiến giúp các nhà khoa học ước tính xác suất mưa lớn với độ chính xác cao hơn.","audioKind":"ex2"}],"collocations":[{"en":"high probability","vi":"xác suất cao"},{"en":"probability of success","vi":"khả năng thành công"},{"en":"in all probability","vi":"mười mươi; có khả năng cao là"},{"en":"probability theory","vi":"lý thuyết xác suất"}],"wordFamily":["probable (adj.)","probably (adv.)","improbable (adj.)"],"synonyms":["likelihood","chance"],"antonyms":[],"tipVi":"Thường đi kèm với giới từ of theo sau là danh từ hoặc danh động từ; cũng có thể theo sau bởi mệnh đề that.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mechanism', 'en-b2-70', 'mechanism', '/ˈmekənɪzəm/', 'B2', 'cơ chế; phương thức vận hành; cơ cấu máy móc; thiết bị cơ khí', 'n.', 'mechanistic (adj.)', NULL, 'Cấu trúc mechanism for doing nghĩa là "cơ chế hoặc phương pháp để thực hiện việc gì đó".', 'The club needs a fair mechanism for resolving disputes.', NULL, 'Câu lạc bộ cần một cơ chế công bằng để giải quyết các tranh chấp.', '{"wordId":"mechanism","ukIpa":"/ˈmekənɪzəm/","usIpa":"/ˈmekənɪzəm/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"a process or system through which something works or happens","vi":"cơ chế; phương thức vận hành"},{"pos":"n.","en":"a set of connected parts that performs a particular function","vi":"cơ cấu máy móc; thiết bị cơ khí"}],"examples":[{"en":"The club needs a fair mechanism for resolving disputes.","vi":"Câu lạc bộ cần một cơ chế công bằng để giải quyết các tranh chấp.","audioKind":"ex"},{"en":"Governments should establish effective monitoring mechanisms to ensure that environmental regulations are consistently enforced across industries.","vi":"Chính phủ nên thiết lập các cơ chế giám sát hiệu quả để đảm bảo các quy định về môi trường được thi hành nhất quán trên khắp các ngành công nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"coping mechanism","vi":"cơ chế đối phó"},{"en":"defence mechanism","vi":"cơ chế tự vệ"},{"en":"monitoring mechanism","vi":"cơ chế giám sát"},{"en":"locking mechanism","vi":"cơ cấu khóa"}],"wordFamily":["mechanistic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc mechanism for doing nghĩa là \"cơ chế hoặc phương pháp để thực hiện việc gì đó\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vacuum', 'en-b2-70', 'vacuum', '/ˈvækjuːm/', 'B2', 'chân không; khoảng trống; máy hút bụi; hút bụi; làm sạch bằng máy hút bụi', 'n.', NULL, NULL, 'Khi diễn đạt hành động dọn dẹp, có thể dùng trực tiếp làm động từ: vacuum the floor.', 'I vacuum the carpet while my brother dusts the shelves.', NULL, 'Tôi hút bụi tấm thảm trong khi anh trai lau dọn các kệ tủ.', '{"wordId":"vacuum","ukIpa":"/ˈvækjuːm/","usIpa":"/ˈvækjuːm/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A space without air, or a gap left by something missing.","vi":"chân không; khoảng trống"},{"pos":"n.","en":"An electric machine that sucks up dust and dirt.","vi":"máy hút bụi"},{"pos":"v.","en":"To clean something using a vacuum cleaner.","vi":"hút bụi; làm sạch bằng máy hút bụi"}],"examples":[{"en":"I vacuum the carpet while my brother dusts the shelves.","vi":"Tôi hút bụi tấm thảm trong khi anh trai lau dọn các kệ tủ.","audioKind":"ex"},{"en":"Sound cannot travel through a vacuum because it needs a medium such as air or water.","vi":"Âm thanh không thể truyền qua chân không vì nó cần một môi trường như không khí hoặc nước.","audioKind":"ex2"}],"collocations":[{"en":"vacuum cleaner","vi":"máy hút bụi"},{"en":"a political vacuum","vi":"khoảng trống quyền lực"},{"en":"vacuum the carpet","vi":"hút bụi thảm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi diễn đạt hành động dọn dẹp, có thể dùng trực tiếp làm động từ: vacuum the floor.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_physicist', 'en-b2-70', 'physicist', '/ˈfɪzɪsɪst/', 'B2', 'nhà vật lý học', 'n.', 'physics (n.), physical (adj.)', NULL, 'physicist là nhà vật lý học; physician là bác sĩ y khoa.', 'A physicist showed our class how magnets work.', NULL, 'Một nhà vật lý học đã biểu diễn cho lớp chúng tôi xem cách hoạt động của nam châm.', '{"wordId":"physicist","ukIpa":"/ˈfɪzɪsɪst/","usIpa":"/ˈfɪzɪsɪst/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A scientist who studies matter, energy, and their interactions.","vi":"nhà vật lý học"}],"examples":[{"en":"A physicist showed our class how magnets work.","vi":"Một nhà vật lý học đã biểu diễn cho lớp chúng tôi xem cách hoạt động của nam châm.","audioKind":"ex"},{"en":"Physicists contribute to medical progress by developing imaging technologies that help doctors examine the human body.","vi":"Các nhà vật lý học đóng góp vào tiến y học bằng cách phát triển các công nghệ hình ảnh giúp bác sĩ kiểm tra cơ thể con người.","audioKind":"ex2"}],"collocations":[{"en":"theoretical physicist","vi":"nhà vật lý lý thuyết"},{"en":"nuclear physicist","vi":"nhà vật lý hạt nhân"},{"en":"experimental physicist","vi":"nhà vật lý thực nghiệm"}],"wordFamily":["physics (n.)","physical (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"physicist là nhà vật lý học; physician là bác sĩ y khoa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rotation', 'en-b2-70', 'rotation', '/roʊˈteɪʃən/', 'B2', 'sự quay; sự xoay vòng; sự luân phiên; sự luân canh', 'n.', 'rotate (v.), rotational (adj.)', NULL, 'rotation có thể chỉ sự quay quanh trục, cũng có thể chỉ việc thay phiên theo thứ tự.', 'The wheel completed one rotation before stopping in the mud.', NULL, 'Chiếc bánh xe quay trọn một vòng trước khi dừng lại trong bùn.', '{"wordId":"rotation","ukIpa":"/rəʊˈteɪʃən/","usIpa":"/roʊˈteɪʃən/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"Movement around a central point or axis","vi":"sự quay; sự xoay vòng"},{"pos":"n.","en":"The regular replacement of one thing or person by another","vi":"sự luân phiên; sự luân canh"}],"examples":[{"en":"The wheel completed one rotation before stopping in the mud.","vi":"Chiếc bánh xe quay trọn một vòng trước khi dừng lại trong bùn.","audioKind":"ex"},{"en":"Crop rotation helps farmers maintain soil fertility and reduce their reliance on chemical pesticides.","vi":"Việc luân canh cây trồng giúp nông dân duy trì độ phì nhiêu của đất và giảm sự phụ thuộc vào thuốc trừ sâu hóa học.","audioKind":"ex2"}],"collocations":[{"en":"the Earth''s rotation","vi":"trái đất tự quay"},{"en":"crop rotation","vi":"luân canh cây trồng"},{"en":"job rotation","vi":"luân chuyển công việc"},{"en":"in rotation","vi":"lần lượt; luân phiên"}],"wordFamily":["rotate (v.)","rotational (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"rotation có thể chỉ sự quay quanh trục, cũng có thể chỉ việc thay phiên theo thứ tự.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spacecraft', 'en-b2-70', 'spacecraft', '/ˈspeɪskræft/', 'B2', 'hàng không vũ trụ; tàu vũ trụ', 'n.', NULL, NULL, 'Từ này có dạng số ít và số nhiều giống nhau: one spacecraft, two spacecraft.', 'We watched the spacecraft launch from our garden.', NULL, 'Chúng tôi đã đứng ở vườn nhà để xem con tàu vũ trụ phóng lên.', '{"wordId":"spacecraft","ukIpa":"/ˈspeɪskrɑːft/","usIpa":"/ˈspeɪskræft/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A vehicle designed to travel or operate in space.","vi":"hàng không vũ trụ; tàu vũ trụ"}],"examples":[{"en":"We watched the spacecraft launch from our garden.","vi":"Chúng tôi đã đứng ở vườn nhà để xem con tàu vũ trụ phóng lên.","audioKind":"ex"},{"en":"Unmanned spacecraft allow scientists to explore distant planets without putting human lives at risk.","vi":"Tàu vũ trụ không người lái cho phép các nhà khoa học khám phá các hành tinh xa xôi mà không làm mạo hiểm tính mạng con người.","audioKind":"ex2"}],"collocations":[{"en":"launch a spacecraft","vi":"phóng tàu vũ trụ"},{"en":"unmanned spacecraft","vi":"tàu vũ trụ không người lái"},{"en":"reusable spacecraft","vi":"tàu vũ trụ tái sử dụng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Từ này có dạng số ít và số nhiều giống nhau: one spacecraft, two spacecraft.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_magnet', 'en-b2-70', 'magnet', '/ˈmæɡnət/', 'B2', 'nam châm; người thu hút; vật thu hút sự chú ý', 'n.', 'magnetic (adj.), magnetism (n.), magnetise (v.)', NULL, 'Khi dùng theo nghĩa bóng để chỉ người hoặc vật thu hút một nhóm đối tượng, thường dùng cấu trúc a magnet for.', 'A small magnet holds our shopping list on the fridge.', NULL, 'Một miếng nam châm nhỏ giữ danh sách mua sắm của chúng tôi trên tủ lạnh.', '{"wordId":"magnet","ukIpa":"/ˈmæɡnət/","usIpa":"/ˈmæɡnət/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"an object that attracts iron and certain other metals","vi":"nam châm"},{"pos":"n.","en":"a person or thing that strongly attracts people or attention","vi":"người thu hút; vật thu hút sự chú ý"}],"examples":[{"en":"A small magnet holds our shopping list on the fridge.","vi":"Một miếng nam châm nhỏ giữ danh sách mua sắm của chúng tôi trên tủ lạnh.","audioKind":"ex"},{"en":"Well-funded universities can act as a magnet for talented researchers, supporting innovation across the wider economy.","vi":"Các trường đại học được tài trợ đầy đủ có thể đóng vai trò là sức hút đối với các nhà nghiên cứu tài năng, hỗ trợ đổi mới trong nền kinh tế rộng lớn hơn.","audioKind":"ex2"}],"collocations":[{"en":"fridge magnet","vi":"nam châm dán tủ lạnh"},{"en":"a powerful magnet","vi":"nam châm cực mạnh"},{"en":"a magnet for tourists","vi":"điểm thu hút khách du lịch"}],"wordFamily":["magnetic (adj.)","magnetism (n.)","magnetise (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi dùng theo nghĩa bóng để chỉ người hoặc vật thu hút một nhóm đối tượng, thường dùng cấu trúc a magnet for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_moisture', 'en-b2-70', 'moisture', '/ˈmɔɪstʃər/', 'B2', 'độ ẩm; hơi ẩm', 'n.', 'moist (adj.), moisten (v.), moisturise (v.), moisturiser (n.)', 'Đồng nghĩa: dampness · Trái nghĩa: dryness', 'Danh từ không đếm được; moisture chỉ độ ẩm bên trong, không đồng nghĩa với lượng mưa.', 'Keep the lid on so the rice retains its moisture.', NULL, 'Hãy đậy nắp lại để cơm giữ được độ ẩm.', '{"wordId":"moisture","ukIpa":"/ˈmɔɪstʃə/","usIpa":"/ˈmɔɪstʃər/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"Small amounts of water in the air or a material","vi":"độ ẩm; hơi ẩm"}],"examples":[{"en":"Keep the lid on so the rice retains its moisture.","vi":"Hãy đậy nắp lại để cơm giữ được độ ẩm.","audioKind":"ex"},{"en":"Planting ground cover helps soil retain moisture and reduces the need for irrigation in dry regions.","vi":"Việc trồng thảm thực vật che phủ giúp giữ độ ẩm cho đất và giảm nhu cầu tưới tiêu ở các vùng khô hạn.","audioKind":"ex2"}],"collocations":[{"en":"retain moisture","vi":"giữ độ ẩm"},{"en":"absorb moisture","vi":"hấp thụ độ ẩm"},{"en":"soil moisture","vi":"độ ẩm của đất"},{"en":"moisture content","vi":"hàm lượng độ ẩm"}],"wordFamily":["moist (adj.)","moisten (v.)","moisturise (v.)","moisturiser (n.)"],"synonyms":["dampness"],"antonyms":["dryness"],"tipVi":"Danh từ không đếm được; moisture chỉ độ ẩm bên trong, không đồng nghĩa với lượng mưa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_variable', 'en-b2-70', 'variable', '/ˈveriəbəl/', 'B2', 'thay đổi; dễ biến động; biến số; yếu tố thay đổi', 'adj.', 'vary (v.), variation (n.), variability (n.), invariable (adj.)', 'Đồng nghĩa: changeable · Trái nghĩa: constant, fixed', 'Khi là tính từ nghĩa là có thể thay đổi; khi là danh từ đếm được nghĩa là biến số.', 'The weather here is too variable for outdoor plans.', NULL, 'Thời tiết ở đây quá thất thường để lên kế hoạch cho các hoạt động ngoài trời.', '{"wordId":"variable","ukIpa":"/ˈveəriəbəl/","usIpa":"/ˈveriəbəl/","cefr":"B2","topic":"science","senses":[{"pos":"adj.","en":"Likely or able to change rather than remain the same.","vi":"thay đổi; dễ biến động"},{"pos":"n.","en":"A quantity or factor that can take different values.","vi":"biến số; yếu tố thay đổi"}],"examples":[{"en":"The weather here is too variable for outdoor plans.","vi":"Thời tiết ở đây quá thất thường để lên kế hoạch cho các hoạt động ngoài trời.","audioKind":"ex"},{"en":"Researchers must control other variables when investigating how class size affects students'' progress in primary education.","vi":"Các nhà nghiên cứu phải kiểm soát các biến số khác khi điều tra cách quy mô lớp học ảnh hưởng đến sự tiến bộ học tập của học sinh tiểu học.","audioKind":"ex2"}],"collocations":[{"en":"variable costs","vi":"chi phí biến đổi"},{"en":"variable weather","vi":"thời tiết thất thường"},{"en":"independent variable","vi":"biến độc lập"},{"en":"dependent variable","vi":"biến phụ thuộc"}],"wordFamily":["vary (v.)","variation (n.)","variability (n.)","invariable (adj.)"],"synonyms":["changeable"],"antonyms":["constant","fixed"],"tipVi":"Khi là tính từ nghĩa là có thể thay đổi; khi là danh từ đếm được nghĩa là biến số.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_statistic', 'en-b2-70', 'statistic', '/stəˈtɪstɪk/', 'B2', 'số liệu thống kê', 'n.', 'statistics (n.), statistical (adj.), statistically (adv.), statistician (n.)', NULL, 'Từ statistics đi với động từ số nhiều khi chỉ các con số thống kê, và đi với số ít khi chỉ môn thống kê học.', 'That surprising statistic made us check the survey again.', NULL, 'Con số thống kê đầy bất ngờ đó khiến chúng tôi phải kiểm tra lại cuộc khảo sát.', '{"wordId":"statistic","ukIpa":"/stəˈtɪstɪk/","usIpa":"/stəˈtɪstɪk/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A numerical fact obtained by collecting and examining information.","vi":"số liệu thống kê"}],"examples":[{"en":"That surprising statistic made us check the survey again.","vi":"Con số thống kê đầy bất ngờ đó khiến chúng tôi phải kiểm tra lại cuộc khảo sát.","audioKind":"ex"},{"en":"A single statistic rarely captures the full impact of unemployment on families and their communities.","vi":"Một con số thống kê đơn lẻ hiếm khi phản ánh hết tác động của tình trạng thất nghiệp đối với các gia đình và cộng đồng của họ.","audioKind":"ex2"}],"collocations":[{"en":"revealing statistic","vi":"số liệu thống kê mang tính bộc lộ"},{"en":"alarming statistic","vi":"số liệu thống kê đáng báo động"},{"en":"official statistics","vi":"thống kê chính thức"},{"en":"unemployment statistics","vi":"số liệu thống kê thất nghiệp"}],"wordFamily":["statistics (n.)","statistical (adj.)","statistically (adv.)","statistician (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ statistics đi với động từ số nhiều khi chỉ các con số thống kê, và đi với số ít khi chỉ môn thống kê học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fossil', 'en-b2-70', 'fossil', '/ˈfɑːsəl/', 'B2', 'hóa thạch', 'n.', 'fossilise (v.), fossilisation (n.), fossilised (adj.)', NULL, 'fossil fuels chỉ các loại nhiên liệu hóa thạch như than đá, dầu mỏ và khí đốt.', 'We found a tiny shell fossil inside the rock.', NULL, 'Chúng tôi tìm thấy một hóa thạch vỏ sò nhỏ xíu bên trong tảng đá.', '{"wordId":"fossil","ukIpa":"/ˈfɒsəl/","usIpa":"/ˈfɑːsəl/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"Ancient remains or traces of living things preserved in rock.","vi":"hóa thạch"}],"examples":[{"en":"We found a tiny shell fossil inside the rock.","vi":"Chúng tôi tìm thấy một hóa thạch vỏ sò nhỏ xíu bên trong tảng đá.","audioKind":"ex"},{"en":"Fossil evidence helps scientists understand how animals adapted to environmental changes over millions of years.","vi":"Bằng chứng hóa thạch giúp các nhà khoa học hiểu được động vật đã thích nghi với sự thay đổi của môi trường như thế nào qua hàng triệu năm.","audioKind":"ex2"}],"collocations":[{"en":"fossil fuels","vi":"nhiên liệu hóa thạch"},{"en":"fossil record","vi":"hồ sơ hóa thạch"},{"en":"fossil evidence","vi":"bằng chứng hóa thạch"}],"wordFamily":["fossilise (v.)","fossilisation (n.)","fossilised (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"fossil fuels chỉ các loại nhiên liệu hóa thạch như than đá, dầu mỏ và khí đốt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gene', 'en-b2-70', 'gene', '/dʒiːn/', 'B2', 'gen (đơn vị thông tin di truyền quyết định các đặc điểm của sinh vật)', 'n.', 'genetic (adj.), genetically (adv.), genetics (n.)', NULL, 'gene là danh từ đếm được; genetics chỉ ngành di truyền học.', 'This gene can influence the colour of a cat''s fur.', NULL, 'Gen này có thể chi phối màu lông của loài mèo.', '{"wordId":"gene","ukIpa":"/dʒiːn/","usIpa":"/dʒiːn/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A unit of inherited information that influences an organism''s characteristics","vi":"gen (đơn vị thông tin di truyền quyết định các đặc điểm của sinh vật)"}],"examples":[{"en":"This gene can influence the colour of a cat''s fur.","vi":"Gen này có thể chi phối màu lông của loài mèo.","audioKind":"ex"},{"en":"Identifying a gene linked to an inherited disease may help researchers develop more effective treatments.","vi":"Việc xác định một gen liên quan đến bệnh di truyền có thể giúp các nhà nghiên cứu phát triển các phương pháp điều trị hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"gene expression","vi":"sự biểu hiện gen"},{"en":"gene therapy","vi":"liệu pháp gen"},{"en":"inherit a gene","vi":"thừa hưởng một gen"}],"wordFamily":["genetic (adj.)","genetically (adv.)","genetics (n.)"],"synonyms":[],"antonyms":[],"tipVi":"gene là danh từ đếm được; genetics chỉ ngành di truyền học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_formula', 'en-b2-70', 'formula', '/ˈfɔːrmjələ/', 'B2', 'công thức (toán học, khoa học); phương pháp; công thức, cách thức; sữa công thức cho trẻ sơ sinh', 'n.', 'formulate (v.), formulation (n.), formulaic (adj.)', NULL, 'Số phận có thể dùng formulas hoặc formulae; phương pháp thường đi với giới từ for.', 'Our teacher showed us a formula for calculating area.', NULL, 'Giáo viên của chúng tôi đã chỉ cho chúng tôi công thức tính diện tích.', '{"wordId":"formula","ukIpa":"/ˈfɔːmjələ/","usIpa":"/ˈfɔːrmjələ/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"a mathematical rule expressed using symbols","vi":"công thức (toán học, khoa học)"},{"pos":"n.","en":"a particular method or mixture used to achieve something","vi":"phương pháp; công thức, cách thức"},{"pos":"n.","en":"specially prepared milk used to feed babies","vi":"sữa công thức cho trẻ sơ sinh"}],"examples":[{"en":"Our teacher showed us a formula for calculating area.","vi":"Giáo viên của chúng tôi đã chỉ cho chúng tôi công thức tính diện tích.","audioKind":"ex"},{"en":"There is no single formula for reducing urban poverty, since local economic conditions vary considerably.","vi":"Không có một công thức chung nào để giảm nghèo đô thị, vì điều kiện kinh tế của mỗi địa phương rất khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"mathematical formula","vi":"công thức toán học"},{"en":"formula for success","vi":"bí quyết thành công"},{"en":"infant formula","vi":"sữa công thức cho trẻ sơ sinh"}],"wordFamily":["formulate (v.)","formulation (n.)","formulaic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Số phận có thể dùng formulas hoặc formulae; phương pháp thường đi với giới từ for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_compound', 'en-b2-70', 'compound', '/ˈkɑːmpaʊnd/', 'B2', 'hợp chất; khu vực có tường bao quanh chứa các tòa nhà; làm cho vấn đề tồi tệ hơn; làm trầm trọng thêm', 'n.', 'compounding (n.)', 'Đồng nghĩa: worsen, aggravate · Trái nghĩa: alleviate', 'Danh từ trọng âm ở âm tiết đầu; động từ trọng âm ở âm tiết thứ hai.', 'Water is a compound made from hydrogen and oxygen.', NULL, 'Nước là một hợp chất được tạo thành từ hydro và oxy.', '{"wordId":"compound","ukIpa":"/ˈkɒmpaʊnd/","usIpa":"/ˈkɑːmpaʊnd/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A substance formed from chemically joined elements.","vi":"hợp chất"},{"pos":"n.","en":"An enclosed area containing buildings.","vi":"khu vực có tường bao quanh chứa các tòa nhà"},{"pos":"v.","en":"To make an existing problem or difficulty worse.","vi":"làm cho vấn đề tồi tệ hơn; làm trầm trọng thêm"}],"examples":[{"en":"Water is a compound made from hydrogen and oxygen.","vi":"Nước là một hợp chất được tạo thành từ hydro và oxy.","audioKind":"ex"},{"en":"Poor public transport can compound the difficulties faced by people seeking employment in rural areas.","vi":"Giao thông công cộng kém có thể làm trầm trọng thêm những khó khăn mà những người tìm việc ở vùng nông thôn phải đối mặt.","audioKind":"ex2"}],"collocations":[{"en":"chemical compound","vi":"hợp chất hóa học"},{"en":"compound a problem","vi":"làm trầm trọng thêm một vấn đề"},{"en":"residential compound","vi":"khu dân cư"},{"en":"compound interest","vi":"lãi kép"}],"wordFamily":["compounding (n.)"],"synonyms":["worsen","aggravate"],"antonyms":["alleviate"],"tipVi":"Danh từ trọng âm ở âm tiết đầu; động từ trọng âm ở âm tiết thứ hai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_metric', 'en-b2-70', 'metric', '/ˈmetrɪk/', 'B2', 'thuộc hệ mét; theo hệ mét; thước đo; tiêu chuẩn đánh giá', 'adj.', NULL, NULL, 'Tính từ chỉ hệ mét; danh từ chỉ tiêu chuẩn đánh giá, thường dùng ở dạng số nhiều.', 'This kitchen scale uses metric units for every ingredient.', NULL, 'Cân nhà bếp này sử dụng đơn vị hệ mét cho mọi nguyên liệu.', '{"wordId":"metric","ukIpa":"/ˈmetrɪk/","usIpa":"/ˈmetrɪk/","cefr":"B2","topic":"science","senses":[{"pos":"adj.","en":"Using measurement units such as metres, litres, and grams.","vi":"thuộc hệ mét; theo hệ mét"},{"pos":"n.","en":"A measurement used to judge performance, quality, or progress.","vi":"thước đo; tiêu chuẩn đánh giá"}],"examples":[{"en":"This kitchen scale uses metric units for every ingredient.","vi":"Cân nhà bếp này sử dụng đơn vị hệ mét cho mọi nguyên liệu.","audioKind":"ex"},{"en":"Although income is a useful metric, it cannot fully capture a population''s quality of life.","vi":"Mặc dù thu nhập là một thước đo hữu ích, nhưng nó không thể phản ánh đầy đủ chất lượng cuộc sống của người dân.","audioKind":"ex2"}],"collocations":[{"en":"metric system","vi":"hệ mét"},{"en":"metric units","vi":"đơn vị đo lường theo hệ mét"},{"en":"performance metric","vi":"chỉ số đánh giá hiệu suất"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tính từ chỉ hệ mét; danh từ chỉ tiêu chuẩn đánh giá, thường dùng ở dạng số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_venus', 'en-b2-70', 'Venus', '/ˈviːnəs/', 'B2', 'sao Kim; thần Vệ Nữ', 'n.', NULL, NULL, 'Danh từ riêng, viết hoa chữ cái đầu; sao Kim thường không đi kèm mạo từ.', 'We spotted Venus shining brightly just after sunset.', NULL, 'Chúng tôi phát hiện sao Kim đang tỏa sáng rực rỡ ngay sau khi mặt trời lặn.', '{"wordId":"venus","ukIpa":"/ˈviːnəs/","usIpa":"/ˈviːnəs/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"The planet second closest to the Sun.","vi":"sao Kim"},{"pos":"n.","en":"The goddess of love and beauty in Roman mythology.","vi":"thần Vệ Nữ"}],"examples":[{"en":"We spotted Venus shining brightly just after sunset.","vi":"Chúng tôi phát hiện sao Kim đang tỏa sáng rực rỡ ngay sau khi mặt trời lặn.","audioKind":"ex"},{"en":"Studying the thick atmosphere of Venus helps scientists understand how greenhouse gases influence planetary temperatures.","vi":"Nghiên cứu bầu khí quyển dày đặc của sao Kim giúp các hiểu được khí nhà kính ảnh hưởng thế nào đến nhiệt độ các hành tinh.","audioKind":"ex2"}],"collocations":[{"en":"the atmosphere of Venus","vi":"bầu khí quyển của sao Kim"},{"en":"the surface of Venus","vi":"bề mặt sao Kim"},{"en":"a mission to Venus","vi":"sứ mệnh thám hiểm sao Kim"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ riêng, viết hoa chữ cái đầu; sao Kim thường không đi kèm mạo từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fraction', 'en-b2-70', 'fraction', '/ˈfrækʃən/', 'B2', 'một phần nhỏ; lượng nhỏ; phân số', 'n.', 'fractional (adj.), fractionally (adv.)', 'Đồng nghĩa: portion, part', 'a fraction of thường nhấn mạnh tỷ lệ cực kỳ nhỏ, không chỉ là một phần thông thường.', 'This jacket costs a fraction of the original price.', NULL, 'Chiếc áo khoác này có giá chỉ bằng một phần nhỏ so với giá gốc.', '{"wordId":"fraction","ukIpa":"/ˈfrækʃən/","usIpa":"/ˈfrækʃən/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"a small part or amount of something","vi":"một phần nhỏ; lượng nhỏ"},{"pos":"n.","en":"a mathematical quantity representing part of a whole","vi":"phân số"}],"examples":[{"en":"This jacket costs a fraction of the original price.","vi":"Chiếc áo khoác này có giá chỉ bằng một phần nhỏ so với giá gốc.","audioKind":"ex"},{"en":"Only a small fraction of household waste is recycled in some rapidly growing cities.","vi":"Chỉ một phần nhỏ rác thải sinh hoạt được tái chế ở một số thành phố đang phát triển nhanh chóng.","audioKind":"ex2"}],"collocations":[{"en":"a fraction of","vi":"một phần của"},{"en":"a small fraction","vi":"một phần rất nhỏ"},{"en":"a fraction of a second","vi":"trong chớp mắt"},{"en":"simple fraction","vi":"phân số đơn giản"}],"wordFamily":["fractional (adj.)","fractionally (adv.)"],"synonyms":["portion","part"],"antonyms":[],"tipVi":"a fraction of thường nhấn mạnh tỷ lệ cực kỳ nhỏ, không chỉ là một phần thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sulphur', 'en-b2-70', 'sulphur', '/ˈsʌlfər/', 'B2', 'lưu huỳnh', 'n.', 'sulphuric (adj.), sulphurous (adj.)', NULL, 'sulphur là truyền thống Anh; khoa học thường dùng sulfur.', 'The guide showed us yellow sulphur near the volcano.', NULL, 'Hướng dẫn viên cho chúng tôi xem lưu huỳnh màu vàng gần ngọn núi lửa.', '{"wordId":"sulphur","ukIpa":"/ˈsʌlfə/","usIpa":"/ˈsʌlfər/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"a yellow chemical element used in industry and agriculture","vi":"lưu huỳnh"}],"examples":[{"en":"The guide showed us yellow sulphur near the volcano.","vi":"Hướng dẫn viên cho chúng tôi xem lưu huỳnh màu vàng gần ngọn núi lửa.","audioKind":"ex"},{"en":"Burning fuels containing sulphur releases gases that contribute to acid rain and damage natural ecosystems.","vi":"Việc đốt các loại nhiên liệu chứa lưu huỳnh giải phóng ra các loại khí góp phần gây ra mưa axit và phá hủy các hệ sinh thái tự nhiên.","audioKind":"ex2"}],"collocations":[{"en":"sulphur dioxide","vi":"dioxide lưu huỳnh"},{"en":"sulphur content","vi":"hàm lượng lưu huỳnh"},{"en":"sulphur deposits","vi":"mỏ lưu huỳnh"}],"wordFamily":["sulphuric (adj.)","sulphurous (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"sulphur là truyền thống Anh; khoa học thường dùng sulfur.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vibrate', 'en-b2-70', 'vibrate', '/ˈvaɪbreɪt/', 'B2', 'rung; rung động; làm rung chuyển', 'v.', 'vibration (n.), vibrating (adj.)', 'Đồng nghĩa: shake, quiver', 'Chỉ sự rung động nhanh, biên độ nhỏ, không giống với chuyển động lắc lư mạnh.', 'My phone vibrated against the keys in my pocket.', NULL, 'Điện thoại của tôi rung lên cạnh những chiếc chìa khóa trong túi áo.', '{"wordId":"vibrate","ukIpa":"/vaɪˈbreɪt/","usIpa":"/ˈvaɪbreɪt/","cefr":"B2","topic":"science","senses":[{"pos":"v.","en":"To shake rapidly with small movements, or cause this movement.","vi":"rung; rung động; làm rung chuyển"}],"examples":[{"en":"My phone vibrated against the keys in my pocket.","vi":"Điện thoại của tôi rung lên cạnh những chiếc chìa khóa trong túi áo.","audioKind":"ex"},{"en":"Heavy traffic can cause nearby buildings to vibrate, affecting residents'' comfort and potentially damaging older structures.","vi":"Xe cộ đông đúc có thể làm các tòa nhà gần đó rung chuyển, ảnh hưởng đến sự thoải mái của cư dân và có khả năng làm hư hại các công trình cũ.","audioKind":"ex2"}],"collocations":[{"en":"vibrate gently","vi":"rung nhè nhẹ"},{"en":"vibrate rapidly","vi":"rung nhanh"},{"en":"vibrate mode","vi":"chế độ rung"}],"wordFamily":["vibration (n.)","vibrating (adj.)"],"synonyms":["shake","quiver"],"antonyms":[],"tipVi":"Chỉ sự rung động nhanh, biên độ nhỏ, không giống với chuyển động lắc lư mạnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_watt', 'en-b2-70', 'watt', '/wɑːt/', 'B2', 'oát; oát-tơ (đơn vị công suất)', 'n.', 'wattage (n.), kilowatt (n.), megawatt (n.)', NULL, 'Oát đo công suất; kilowatt-giờ đo lượng điện tiêu thụ.', 'This small lamp uses only five watts of power.', NULL, 'Chiếc đèn nhỏ này chỉ tiêu thụ công suất năm oát.', '{"wordId":"watt","ukIpa":"/wɒt/","usIpa":"/wɑːt/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"a unit used to measure power","vi":"oát; oát-tơ (đơn vị công suất)"}],"examples":[{"en":"This small lamp uses only five watts of power.","vi":"Chiếc đèn nhỏ này chỉ tiêu thụ công suất năm oát.","audioKind":"ex"},{"en":"Comparing the watts required by different appliances helps consumers choose models that use less electricity.","vi":"Việc so sánh số oát mà các thiết bị khác nhau yêu cầu giúp người tiêu dùng chọn các mẫu tiêu thụ ít điện năng hơn.","audioKind":"ex2"}],"collocations":[{"en":"power in watts","vi":"công suất tính bằng oát"},{"en":"a ten-watt bulb","vi":"bóng đèn mười oát"},{"en":"rated at fifty watts","vi":"có công suất định mức năm mươi oát"}],"wordFamily":["wattage (n.)","kilowatt (n.)","megawatt (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Oát đo công suất; kilowatt-giờ đo lượng điện tiêu thụ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_70_1', 'en-b2-70', 'Cách dùng “magnet” (n.) — nam châm', 'fridge magnet  ·  a powerful magnet  ·  a magnet for tourists', 'Khi dùng theo nghĩa bóng để chỉ người hoặc vật thu hút một nhóm đối tượng, thường dùng cấu trúc a magnet for.', 'Họ từ (Word Family): magnetic (adj.), magnetism (n.), magnetise (v.)', '[{"hanzi":"A small magnet holds our shopping list on the fridge.","pinyin":"","meaning":"Một miếng nam châm nhỏ giữ danh sách mua sắm của chúng tôi trên tủ lạnh."},{"hanzi":"Well-funded universities can act as a magnet for talented researchers, supporting innovation across the wider economy.","pinyin":"","meaning":"Các trường đại học được tài trợ đầy đủ có thể đóng vai trò là sức hút đối với các nhà nghiên cứu tài năng, hỗ trợ đổi mới trong nền kinh tế rộng lớn hơn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_70_2', 'en-b2-70', 'Cách dùng “statistic” (n.) — số liệu thống kê', 'revealing statistic  ·  alarming statistic  ·  official statistics', 'Từ statistics đi với động từ số nhiều khi chỉ các con số thống kê, và đi với số ít khi chỉ môn thống kê học.', 'Họ từ (Word Family): statistics (n.), statistical (adj.), statistically (adv.), statistician (n.)', '[{"hanzi":"That surprising statistic made us check the survey again.","pinyin":"","meaning":"Con số thống kê đầy bất ngờ đó khiến chúng tôi phải kiểm tra lại cuộc khảo sát."},{"hanzi":"A single statistic rarely captures the full impact of unemployment on families and their communities.","pinyin":"","meaning":"Một con số thống kê đơn lẻ hiếm khi phản ánh hết tác động của tình trạng thất nghiệp đối với các gia đình và cộng đồng của họ."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_70_3', 'en-b2-70', 'Cách dùng “probability” (n.) — xác suất; khả năng xảy ra', 'high probability  ·  probability of success  ·  in all probability', 'Thường đi kèm với giới từ of theo sau là danh từ hoặc danh động từ; cũng có thể theo sau bởi mệnh đề that.', 'Họ từ (Word Family): probable (adj.), probably (adv.), improbable (adj.) | Đồng nghĩa: likelihood, chance', '[{"hanzi":"Dark clouds suggest a high probability of rain tonight.","pinyin":"","meaning":"Mây đen cho thấy khả năng cao trời sẽ mưa tối nay."},{"hanzi":"Improved weather models allow scientists to estimate the probability of extreme rainfall with greater accuracy.","pinyin":"","meaning":"Các mô hình thời tiết được cải tiến giúp các nhà khoa học ước tính xác suất mưa lớn với độ chính xác cao hơn."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_70_4', 'en-b2-70', 'Cách dùng “statistical” (adj.) — thuộc về thống kê, liên quan đến thu thập và phân tích dữ liệu số', 'statistical analysis  ·  statistical data  ·  statistical significance', 'statistical chỉ các vấn đề liên quan đến thống kê, không đồng nghĩa với "đáng chú ý" hay "nổi bật".', 'Họ từ (Word Family): statistics (n.), statistic (n.), statistically (adv.), statistician (n.)', '[{"hanzi":"She used statistical software to compare the survey results.","pinyin":"","meaning":"Cô ấy đã sử dụng phần mềm thống kê để so sánh các kết quả khảo sát."},{"hanzi":"Reliable statistical evidence helps governments identify communities that need better access to healthcare.","pinyin":"","meaning":"Bằng chứng thống kê đáng tin cậy giúp chính phủ xác định các cộng đồng cần được tiếp cận dịch vụ y tế tốt hơn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_70_1', 'en-b2-70', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
