INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_70_1_4', 'ten_b2_70_1', 'Saturn', 'We saw Saturn through a telescope last night.', 'We saw Saturn through a telescope last night.', '/ˈsætərn/', 'Đêm qua chúng tôi nhìn thấy sao Thổ qua kính viễn vọng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
