INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_70_1_7', 'ten_b2_70_1', 'vacuum', 'I vacuum the carpet while my brother dusts the shelves.', 'I vacuum the carpet while my brother dusts the shelves.', '/ˈvækjuːm/', 'Tôi hút bụi tấm thảm trong khi anh trai lau dọn các kệ tủ.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_70_1_8', 'ten_b2_70_1', 'physicist', 'A physicist showed our class how magnets work.', 'A physicist showed our class how magnets work.', '/ˈfɪzɪsɪst/', 'Một nhà vật lý học đã biểu diễn cho lớp chúng tôi xem cách hoạt động của nam châm.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_70_1_1', 'en-b2-70', 'ten_b2_70_1', 'listening', 'listening', 'The nurse gave him oxygen through a clear plastic mask.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Y tá đã cho ông ấy thở oxy thông qua một chiếc mặt nạ nhựa trong suốt.","Chúng tôi tìm thấy một hóa thạch vỏ sò nhỏ xíu bên trong tảng đá.","Thời tiết ở đây quá thất thường để lên kế hoạch cho các hoạt động ngoài trời.","Tôi hút bụi tấm thảm trong khi anh trai lau dọn các kệ tủ."]'::jsonb, 0, 'The nurse gave him oxygen through a clear plastic mask. → Y tá đã cho ông ấy thở oxy thông qua một chiếc mặt nạ nhựa trong suốt.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_70_1_2', 'en-b2-70', 'ten_b2_70_1', 'listening', 'listening', 'I opened the cookbook at a random page.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Mây đen cho thấy khả năng cao trời sẽ mưa tối nay.","Chiếc áo khoác này có giá chỉ bằng một phần nhỏ so với giá gốc.","Tôi tùy tiện mở một trang trong cuốn sách nấu ăn.","Nước là một hợp chất được tạo thành từ hydro và oxy."]'::jsonb, 2, 'I opened the cookbook at a random page. → Tôi tùy tiện mở một trang trong cuốn sách nấu ăn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_70_1_3', 'en-b2-70', 'ten_b2_70_1', 'listening', 'listening', 'She used statistical software to compare the survey results.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chiếc đèn nhỏ này chỉ tiêu thụ công suất năm oát.","Tôi tùy tiện mở một trang trong cuốn sách nấu ăn.","Cô ấy đã sử dụng phần mềm thống kê để so sánh các kết quả khảo sát.","Chiếc áo khoác này có giá chỉ bằng một phần nhỏ so với giá gốc."]'::jsonb, 2, 'She used statistical software to compare the survey results. → Cô ấy đã sử dụng phần mềm thống kê để so sánh các kết quả khảo sát.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_70_2', 'en-b2-70', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_70_2_1', 'ten_b2_70_2', 'oxygen', 'Pollution can reduce oxygen levels in rivers, making it difficult for fish and other aquatic organisms to survive.', 'Pollution can reduce oxygen levels in rivers, making it difficult for fish and other aquatic organisms to survive.', '/ˈɑːksɪdʒən/', 'Tình trạng ô nhiễm có thể làm giảm nồng độ oxy trong các con sông, khiến cá và các sinh vật dưới nước khác khó sinh sống.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_70_2_2', 'ten_b2_70_2', 'random', 'Researchers selected a random sample of households to assess public attitudes towards renewable energy.', 'Researchers selected a random sample of households to assess public attitudes towards renewable energy.', '/ˈrændəm/', 'Các nhà nghiên cứu đã chọn một mẫu ngẫu nhiên gồm các hộ gia đình để đánh giá thái độ của công chúng đối với năng lượng tái tạo.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_70_2_3', 'ten_b2_70_2', 'statistical', 'Reliable statistical evidence helps governments identify communities that need better access to healthcare.', 'Reliable statistical evidence helps governments identify communities that need better access to healthcare.', '/stəˈtɪstɪkəl/', 'Bằng chứng thống kê đáng tin cậy giúp chính phủ xác định các cộng đồng cần được tiếp cận dịch vụ y tế tốt hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_70_2_4', 'ten_b2_70_2', 'Saturn', 'Studying the rings of Saturn helps scientists understand how particles interact in space over time.', 'Studying the rings of Saturn helps scientists understand how particles interact in space over time.', '/ˈsætərn/', 'Việc nghiên cứu các vành đai của sao Thổ giúp các nhà khoa học hiểu được các hạt tương tác với nhau trong không gian theo thời gian như thế nào.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_70_2_5', 'ten_b2_70_2', 'probability', 'Improved weather models allow scientists to estimate the probability of extreme rainfall with greater accuracy.', 'Improved weather models allow scientists to estimate the probability of extreme rainfall with greater accuracy.', '/ˌprɑːbəˈbɪləti/', 'Các mô hình thời tiết được cải tiến giúp các nhà khoa học ước tính xác suất mưa lớn với độ chính xác cao hơn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_70_2_6', 'ten_b2_70_2', 'mechanism', 'Governments should establish effective monitoring mechanisms to ensure that environmental regulations are consistently enforced across industries.', 'Governments should establish effective monitoring mechanisms to ensure that environmental regulations are consistently enforced across industries.', '/ˈmekənɪzəm/', 'Chính phủ nên thiết lập các cơ chế giám sát hiệu quả để đảm bảo các quy định về môi trường được thi hành nhất quán trên khắp các ngành công nghiệp.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_70_2_1', 'en-b2-70', 'ten_b2_70_2', 'listening', 'listening', 'Pollution can reduce oxygen levels in rivers, making it difficult for fish and other aquatic organisms to survive.', NULL, 'Trong câu vừa nghe, từ “oxygen” mang nghĩa nào sau đây?', '["oxi; khí oxy","khác nhau; thay đổi tùy theo hoàn cảnh","việc; sự kiện; vấn đề","hang ổ; đường hầm (do động vật đào để trú ẩn)"]'::jsonb, 0, '“oxygen” (/ˈɑːksɪdʒən/): oxi; khí oxy. Câu đầy đủ: Pollution can reduce oxygen levels in rivers, making it difficult for fish and other aquatic organisms to survive.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_70_2_2', 'en-b2-70', 'ten_b2_70_2', 'listening', 'listening', 'Researchers selected a random sample of households to assess public attitudes towards renewable energy.', NULL, 'Trong câu vừa nghe, từ “random” mang nghĩa nào sau đây?', '["đứa trẻ mồ côi","ngẫu nhiên; tùy tiện; không theo quy luật","thỉnh thoảng; đôi khi; không thường xuyên","sự hình thành; sự thành lập"]'::jsonb, 1, '“random” (/ˈrændəm/): ngẫu nhiên; tùy tiện; không theo quy luật. Câu đầy đủ: Researchers selected a random sample of households to assess public attitudes towards renewable energy.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
