INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_70_5', 'en-b2-70', NULL, 'comprehensive_test', 'listening', 'probability', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự tài trợ; việc hỗ trợ kinh phí","đóng sập; đặt mạnh (vật gì đó với tiếng động lớn)","to lớn; vô cùng; cực kỳ","xác suất; khả năng xảy ra"]'::jsonb, 3, 'probability (/ˌprɑːbəˈbɪləti/) → xác suất; khả năng xảy ra', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_70_6', 'en-b2-70', NULL, 'comprehensive_test', 'listening', 'The club needs a fair mechanism for resolving disputes.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Câu lạc bộ cần một cơ chế công bằng để giải quyết các tranh chấp.","Mây đen cho thấy khả năng cao trời sẽ mưa tối nay.","Gen này có thể chi phối màu lông của loài mèo.","Chúng tôi đã đứng ở vườn nhà để xem con tàu vũ trụ phóng lên."]'::jsonb, 0, 'The club needs a fair mechanism for resolving disputes. → Câu lạc bộ cần một cơ chế công bằng để giải quyết các tranh chấp.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_70_7', 'en-b2-70', NULL, 'comprehensive_test', 'listening', 'vacuum', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chân không; khoảng trống","đoạn điệp khúc; khúc nối (trong bài hát)","cuộc khủng hoảng; thời điểm gay cấn","thẳng đứng; vuông góc"]'::jsonb, 0, 'vacuum (/ˈvækjuːm/) → chân không; khoảng trống; máy hút bụi; hút bụi; làm sạch bằng máy hút bụi', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_70_8', 'en-b2-70', NULL, 'comprehensive_test', 'listening', 'A physicist showed our class how magnets work.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Mây đen cho thấy khả năng cao trời sẽ mưa tối nay.","Nước là một hợp chất được tạo thành từ hydro và oxy.","Đêm qua chúng tôi nhìn thấy sao Thổ qua kính viễn vọng.","Một nhà vật lý học đã biểu diễn cho lớp chúng tôi xem cách hoạt động của nam châm."]'::jsonb, 3, 'A physicist showed our class how magnets work. → Một nhà vật lý học đã biểu diễn cho lớp chúng tôi xem cách hoạt động của nam châm.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
