INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_70_18', 'en-b2-70', NULL, 'comprehensive_test', 'reading', NULL, 'Pollution can reduce oxygen levels in rivers, making it difficult for fish and other aquatic organisms to survive.', 'Dựa vào câu trên, từ “oxygen” có nghĩa phù hợp nhất là gì?', '["động vật có vú","oxi; khí oxy","châu chấu; cào cào","một cách dễ dàng; không khó khăn"]'::jsonb, 1, 'oxygen: oxi; khí oxy. Dịch cả câu: Tình trạng ô nhiễm có thể làm giảm nồng độ oxy trong các con sông, khiến cá và các sinh vật dưới nước khác khó sinh sống.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_70_19', 'en-b2-70', NULL, 'comprehensive_test', 'reading', NULL, 'Researchers selected a random sample of households to assess public attitudes towards renewable energy.', 'Dựa vào câu trên, từ “random” có nghĩa phù hợp nhất là gì?', '["ngẫu nhiên; tùy tiện; không theo quy luật","trưng bày; triển lãm","sự điên rồ; hành vi cực kỳ ng U dốt và nguy hiểm","nhà kính, nhà ươm cây"]'::jsonb, 0, 'random: ngẫu nhiên; tùy tiện; không theo quy luật. Dịch cả câu: Các nhà nghiên cứu đã chọn một mẫu ngẫu nhiên gồm các hộ gia đình để đánh giá thái độ của công chúng đối với năng lượng tái tạo.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_70_20', 'en-b2-70', NULL, 'comprehensive_test', 'reading', NULL, 'Reliable statistical evidence helps governments identify communities that need better access to healthcare.', 'Dựa vào câu trên, từ “statistical” có nghĩa phù hợp nhất là gì?', '["đáng chú ý; phi thường; xuất sắc","cơ chế; phương thức vận hành","thuộc về thống kê, liên quan đến thu thập và phân tích dữ liệu số","lăng mạ; xúc phạm"]'::jsonb, 2, 'statistical: thuộc về thống kê, liên quan đến thu thập và phân tích dữ liệu số. Dịch cả câu: Bằng chứng thống kê đáng tin cậy giúp chính phủ xác định các cộng đồng cần được tiếp cận dịch vụ y tế tốt hơn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_70_21', 'en-b2-70', NULL, 'comprehensive_test', 'reading', NULL, 'Studying the rings of Saturn helps scientists understand how particles interact in space over time.', 'Dựa vào câu trên, từ “Saturn” có nghĩa phù hợp nhất là gì?', '["calo (đơn vị đo nhiệt lượng hoặc năng lượng từ thức ăn)","sao Thổ","sự tập trung; sự chuyên tâm","sự thuyết trình; sự biểu diễn; sự minh họa"]'::jsonb, 1, 'Saturn: sao Thổ. Dịch cả câu: Việc nghiên cứu các vành đai của sao Thổ giúp các nhà khoa học hiểu được các hạt tương tác với nhau trong không gian theo thời gian như thế nào.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
