INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-71', 'en', 'Bài 71: Khoa học & Nghiên cứu (5) - CEFR B2', 'CEFR B2', 'B2 · Khoa học', '24 từ vựng Tiếng Anh CEFR B2 chủ đề khoa học & nghiên cứu kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4071, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_trace', 'en-b2-71', 'trace', '/treɪs/', 'B2', 'truy tìm; lần theo dấu vết; truy nguyên; dấu vết; vết tích; lượng nhỏ; vẽ theo khung; can (tranh); tô theo đường nét', 'v.', 'traceable (adj.), tracing (n.)', NULL, 'Cấu trúc trace A back to B dùng để chỉ hành động "truy cứu nguồn gốc A từ B".', 'The plumber traced the leak to a cracked pipe.', NULL, 'Thợ sửa ống nước đã lần ra nguồn gốc chỗ rò rỉ là từ một đường ống bị nứt.', '{"wordId":"trace","ukIpa":"/treɪs/","usIpa":"/treɪs/","cefr":"B2","topic":"science","senses":[{"pos":"v.","en":"find something''s origin or location by following evidence","vi":"truy tìm; lần theo dấu vết; truy nguyên"},{"pos":"n.","en":"a small sign, mark, or amount left behind","vi":"dấu vết; vết tích; lượng nhỏ"},{"pos":"v.","en":"copy a picture by drawing over its lines","vi":"vẽ theo khung; can (tranh); tô theo đường nét"}],"examples":[{"en":"The plumber traced the leak to a cracked pipe.","vi":"Thợ sửa ống nước đã lần ra nguồn gốc chỗ rò rỉ là từ một đường ống bị nứt.","audioKind":"ex"},{"en":"Researchers can trace changes in regional diets by examining food remains discovered at ancient settlements.","vi":"Các nhà nghiên cứu có thể truy nguyên sự thay đổi trong chế độ ăn uống theo vùng bằng cách kiểm tra các tàn tích thức ăn được phát hiện tại các khu định cư cổ đại.","audioKind":"ex2"}],"collocations":[{"en":"trace the source","vi":"truy tìm nguồn gốc"},{"en":"trace back to","vi":"truy xuất về tận"},{"en":"without a trace","vi":"không một dấu vết"},{"en":"traces of","vi":"dấu vết của; một lượng nhỏ"}],"wordFamily":["traceable (adj.)","tracing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc trace A back to B dùng để chỉ hành động \"truy cứu nguồn gốc A từ B\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_longitude', 'en-b2-71', 'longitude', '/ˈlɑːndʒɪtuːd/', 'B2', 'kinh độ', 'n.', 'longitudinal (adj.)', NULL, '"longitude" là kinh độ (chia theo hướng đông - tây); "latitude" là vĩ độ (chia theo hướng bắc - nam).', 'Our guide checked our longitude before steering the boat east.', NULL, 'Người dẫn đường đã kiểm tra kinh độ của chúng tôi trước khi lái thuyền về hướng đông.', '{"wordId":"longitude","ukIpa":"/ˈlɒŋɡɪtjuːd/","usIpa":"/ˈlɑːndʒɪtuːd/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"a place''s angular distance east or west of the prime meridian","vi":"kinh độ"}],"examples":[{"en":"Our guide checked our longitude before steering the boat east.","vi":"Người dẫn đường đã kiểm tra kinh độ của chúng tôi trước khi lái thuyền về hướng đông.","audioKind":"ex"},{"en":"Accurate measurements of longitude and latitude allow navigation systems to determine a vehicle''s position on Earth.","vi":"Các phép đo chính xác về kinh độ và vĩ độ cho phép hệ thống định vị xác định vị trí của phương tiện trên Trái Đất.","audioKind":"ex2"}],"collocations":[{"en":"latitude and longitude","vi":"vĩ độ và kinh độ"},{"en":"degrees of longitude","vi":"độ kinh"},{"en":"east longitude","vi":"kinh độ đông"},{"en":"west longitude","vi":"kinh độ tây"}],"wordFamily":["longitudinal (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"\"longitude\" là kinh độ (chia theo hướng đông - tây); \"latitude\" là vĩ độ (chia theo hướng bắc - nam).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_volume', 'en-b2-71', 'volume', '/ˈvɑːljuːm/', 'B2', 'thể tích; khối lượng; tổng lượng; âm lượng; tập (sách); cuốn', 'n.', 'voluminous (adj.)', NULL, 'Từ "volume" có thể chỉ thể tích, tổng lượng hoặc âm lượng; diện tích dùng "area".', 'Please turn the volume down while the baby sleeps.', NULL, 'Làm ơn vặn nhỏ âm lượng lại trong lúc em bé đang ngủ.', '{"wordId":"volume","ukIpa":"/ˈvɒljuːm/","usIpa":"/ˈvɑːljuːm/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"The space something occupies, or the total amount of something.","vi":"thể tích; khối lượng; tổng lượng"},{"pos":"n.","en":"The level of loudness of a sound.","vi":"âm lượng"},{"pos":"n.","en":"A book, especially one belonging to a larger set.","vi":"tập (sách); cuốn"}],"examples":[{"en":"Please turn the volume down while the baby sleeps.","vi":"Làm ơn vặn nhỏ âm lượng lại trong lúc em bé đang ngủ.","audioKind":"ex"},{"en":"The growing volume of household waste highlights the need for better recycling facilities in urban areas.","vi":"Khối lượng rác thải sinh hoạt ngày càng tăng làm nổi bật nhu cầu cần có các cơ sở tái chế tốt hơn ở các khu đô thị.","audioKind":"ex2"}],"collocations":[{"en":"a high volume of traffic","vi":"lượng giao thông lớn"},{"en":"turn down the volume","vi":"vặn nhỏ âm lượng"},{"en":"calculate the volume","vi":"tính thể tích"},{"en":"a companion volume","vi":"tập sách đi kèm"}],"wordFamily":["voluminous (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ \"volume\" có thể chỉ thể tích, tổng lượng hoặc âm lượng; diện tích dùng \"area\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nitrogen', 'en-b2-71', 'nitrogen', '/ˈnaɪtrədʒən/', 'B2', 'nitơ; khí nitơ', 'n.', 'nitrogenous (adj.)', NULL, 'Nitrogen là danh từ không đếm được, ký hiệu hóa học là N.', 'These beans help add nitrogen to our garden soil.', NULL, 'Những cây đậu này giúp bổ sung nitơ cho đất trong vườn của chúng tôi.', '{"wordId":"nitrogen","ukIpa":"/ˈnaɪtrədʒən/","usIpa":"/ˈnaɪtrədʒən/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A chemical element forming most of the gas in Earth''s air.","vi":"nitơ; khí nitơ"}],"examples":[{"en":"These beans help add nitrogen to our garden soil.","vi":"Những cây đậu này giúp bổ sung nitơ cho đất trong vườn của chúng tôi.","audioKind":"ex"},{"en":"Excess nitrogen from agricultural fertilisers can enter rivers, encouraging rapid algae growth and damaging aquatic ecosystems.","vi":"Lượng nitơ dư thừa từ phân bón nông nghiệp có thể ngấm vào sông ngòi, thúc đẩy tảo phát triển nhanh chóng và tàn phá các hệ sinh thái dưới nước.","audioKind":"ex2"}],"collocations":[{"en":"liquid nitrogen","vi":"nitơ lỏng"},{"en":"nitrogen gas","vi":"khí nitơ"},{"en":"nitrogen cycle","vi":"chu trình nitơ"},{"en":"nitrogen fixation","vi":"quá trình cố định đạm"}],"wordFamily":["nitrogenous (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nitrogen là danh từ không đếm được, ký hiệu hóa học là N.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_constant', 'en-b2-71', 'constant', '/ˈkɑːnstənt/', 'B2', 'liên tục; không ngừng; không đổi; hằng định; hằng số', 'adj.', 'constantly (adv.), constancy (n.)', 'Trái nghĩa: variable', 'Có thể chỉ sự việc lặp lại liên tục hoặc giá trị không đổi, tùy thuộc vào ngữ cảnh.', 'The constant noise outside kept me awake all night.', NULL, 'Tiếng ồn liên tục bên ngoài khiến tôi thức trắng đêm.', '{"wordId":"constant","ukIpa":"/ˈkɒnstənt/","usIpa":"/ˈkɑːnstənt/","cefr":"B2","topic":"science","senses":[{"pos":"adj.","en":"continuing or happening repeatedly","vi":"liên tục; không ngừng"},{"pos":"adj.","en":"remaining the same over time","vi":"không đổi; hằng định"},{"pos":"n.","en":"a value or quantity that does not change","vi":"hằng số"}],"examples":[{"en":"The constant noise outside kept me awake all night.","vi":"Tiếng ồn liên tục bên ngoài khiến tôi thức trắng đêm.","audioKind":"ex"},{"en":"Maintaining a constant temperature in public buildings can improve comfort but may increase energy consumption.","vi":"Duy trì nhiệt độ ổn định trong các tòa nhà công cộng có thể nâng cao sự thoải mái nhưng có thể làm tăng mức tiêu thụ năng lượng.","audioKind":"ex2"}],"collocations":[{"en":"constant pressure","vi":"áp lực liên tục"},{"en":"constant temperature","vi":"nhiệt độ không đổi"},{"en":"remain constant","vi":"giữ nguyên không đổi"}],"wordFamily":["constantly (adv.)","constancy (n.)"],"synonyms":[],"antonyms":["variable"],"tipVi":"Có thể chỉ sự việc lặp lại liên tục hoặc giá trị không đổi, tùy thuộc vào ngữ cảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_optical', 'en-b2-71', 'optical', '/ˈɑːptɪkəl/', 'B2', 'thuộc về ánh sáng; quang học; thuộc về thị giác; mắt', 'adj.', 'optics (n.), optically (adv.)', NULL, 'optical liên quan đến ánh sáng hoặc thị lực; optical illusion có nghĩa là ảo ảnh thị giác.', 'This optical illusion makes the flat drawing look three-dimensional.', NULL, 'Hiệu ứng thị giác này làm cho bức vẽ phẳng trông có vẻ nổi ba chiều.', '{"wordId":"optical","ukIpa":"/ˈɒptɪkəl/","usIpa":"/ˈɑːptɪkəl/","cefr":"B2","topic":"science","senses":[{"pos":"adj.","en":"Relating to light or devices that use light.","vi":"thuộc về ánh sáng; quang học"},{"pos":"adj.","en":"Relating to sight or the way the eyes work.","vi":"thuộc về thị giác; mắt"}],"examples":[{"en":"This optical illusion makes the flat drawing look three-dimensional.","vi":"Hiệu ứng thị giác này làm cho bức vẽ phẳng trông có vẻ nổi ba chiều.","audioKind":"ex"},{"en":"Optical fibres enable rapid data transmission, supporting the expansion of reliable internet access in remote communities.","vi":"Cáp quang cho phép truyền dữ liệu tốc độ cao, hỗ trợ mở rộng dịch vụ internet đáng tin cậy ở các cộng đồng vùng sâu vùng xa.","audioKind":"ex2"}],"collocations":[{"en":"optical illusion","vi":"ảo ảnh thị giác"},{"en":"optical fibre","vi":"cáp quang"},{"en":"optical instrument","vi":"dụng cụ quang học"}],"wordFamily":["optics (n.)","optically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"optical liên quan đến ánh sáng hoặc thị lực; optical illusion có nghĩa là ảo ảnh thị giác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_electron', 'en-b2-71', 'electron', '/ɪˈlektrɑːn/', 'B2', 'điện tử', 'n.', 'electronic (adj.), electronics (n.), electronically (adv.)', NULL, 'electron là hạt điện tử; electronic có nghĩa là thuộc về điện tử.', 'Our teacher used coloured beads to represent each electron.', NULL, 'Giáo viên của chúng tôi dùng các hạt cườm màu để biểu diễn từng hạt electron.', '{"wordId":"electron","ukIpa":"/ɪˈlektrɒn/","usIpa":"/ɪˈlektrɑːn/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A tiny particle carrying a negative electric charge.","vi":"điện tử"}],"examples":[{"en":"Our teacher used coloured beads to represent each electron.","vi":"Giáo viên của chúng tôi dùng các hạt cườm màu để biểu diễn từng hạt electron.","audioKind":"ex"},{"en":"Understanding how electrons move through materials is essential for developing more efficient batteries and electronic devices.","vi":"Hiểu được cách các electron di chuyển qua các vật liệu là điều cốt lõi để phát triển các loại pin và thiết bị điện tử hiệu suất cao hơn.","audioKind":"ex2"}],"collocations":[{"en":"electron microscope","vi":"kính hiển vi điện tử"},{"en":"electron flow","vi":"dòng điện tử"},{"en":"electron beam","vi":"chùm tia điện tử"}],"wordFamily":["electronic (adj.)","electronics (n.)","electronically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"electron là hạt điện tử; electronic có nghĩa là thuộc về điện tử.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_orbit', 'en-b2-71', 'orbit', '/ˈɔːrbɪt/', 'B2', 'quỹ đạo; quay theo quỹ đạo; bay quỹ đạo quanh', 'n.', 'orbital (adj.), orbiter (n.)', NULL, 'Động từ có thể đi thẳng với thiên thể như orbit the Earth mà không cần dùng thêm giới từ around.', 'We watched an animation showing the satellite''s orbit.', NULL, 'Chúng tôi đã xem một đoạn hoạt họa mô tả quỹ đạo chuyển động của vệ tinh.', '{"wordId":"orbit","ukIpa":"/ˈɔːbɪt/","usIpa":"/ˈɔːrbɪt/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"the curved path of an object moving around another in space","vi":"quỹ đạo"},{"pos":"v.","en":"to move around a planet, star, or other object in space","vi":"quay theo quỹ đạo; bay quỹ đạo quanh"}],"examples":[{"en":"We watched an animation showing the satellite''s orbit.","vi":"Chúng tôi đã xem một đoạn hoạt họa mô tả quỹ đạo chuyển động của vệ tinh.","audioKind":"ex"},{"en":"Satellites that orbit the Earth provide essential data for weather forecasting, disaster monitoring, and climate research.","vi":"Các vệ tinh quay quanh Trái Đất cung cấp dữ liệu thiết yếu phục vụ công tác dự báo thời tiết, giám sát thảm họa và nghiên cứu khí hậu.","audioKind":"ex2"}],"collocations":[{"en":"in orbit","vi":"đang trên quỹ đạo"},{"en":"enter orbit","vi":"vào quỹ đạo"},{"en":"a stable orbit","vi":"quỹ đạo ổn định"},{"en":"orbit the Earth","vi":"quay quanh Trái Đất"}],"wordFamily":["orbital (adj.)","orbiter (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ có thể đi thẳng với thiên thể như orbit the Earth mà không cần dùng thêm giới từ around.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bacterium', 'en-b2-71', 'bacterium', '/bækˈtɪriəm/', 'B2', 'vi khuẩn', 'n.', 'bacteria (n.), bacterial (adj.), antibacterial (adj.)', NULL, 'Dạng số ít là bacterium, dạng số nhiều là bacteria; khi bacteria ở số ít/số nhiều làm chủ ngữ thì chia động từ số nhiều là are.', 'Under the microscope, a single bacterium moved slowly.', NULL, 'Dưới kính hiển vi, một vi khuẩn đơn lẻ đang di chuyển chậm chạp.', '{"wordId":"bacterium","ukIpa":"/bækˈtɪəriəm/","usIpa":"/bækˈtɪriəm/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A microscopic single-celled organism, sometimes responsible for disease.","vi":"vi khuẩn"}],"examples":[{"en":"Under the microscope, a single bacterium moved slowly.","vi":"Dưới kính hiển vi, một vi khuẩn đơn lẻ đang di chuyển chậm chạp.","audioKind":"ex"},{"en":"Scientists identified a bacterium that could help remove harmful chemicals from polluted soil without damaging nearby plants.","vi":"Các nhà khoa học đã xác định được một loại vi khuẩn có khả năng giúp loại bỏ các hóa chất độc hại khỏi đất bị ô nhiễm mà không gây hại cho thực vật xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"a harmful bacterium","vi":"vi khuẩn có hại"},{"en":"disease-causing bacteria","vi":"vi khuẩn gây bệnh"},{"en":"beneficial bacteria","vi":"vi khuẩn có lợi"}],"wordFamily":["bacteria (n.)","bacterial (adj.)","antibacterial (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng số ít là bacterium, dạng số nhiều là bacteria; khi bacteria ở số ít/số nhiều làm chủ ngữ thì chia động từ số nhiều là are.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_explosive', 'en-b2-71', 'explosive', '/ɪkˈsploʊsɪv/', 'B2', 'dễ nổ; có tính nổ; bùng nổ; tăng vọt; dữ dội; chất nổ; thuốc nổ', 'adj.', 'explode (v.), explosion (n.), explosively (adv.)', NULL, 'Cụm explosive growth dùng để diễn tả sự gia tăng cực kỳ nhanh chóng, không có nghĩa là xảy ra vụ nổ vật lý.', 'These explosive materials must be kept away from heat.', NULL, 'Những vật liệu dễ nổ này phải được giữ cách xa nguồn nhiệt.', '{"wordId":"explosive","ukIpa":"/ɪkˈspləʊsɪv/","usIpa":"/ɪkˈsploʊsɪv/","cefr":"B2","topic":"science","senses":[{"pos":"adj.","en":"able or likely to burst violently","vi":"dễ nổ; có tính nổ"},{"pos":"adj.","en":"increasing very rapidly or appearing with sudden force","vi":"bùng nổ; tăng vọt; dữ dội"},{"pos":"n.","en":"a substance that can cause a violent burst of energy","vi":"chất nổ; thuốc nổ"}],"examples":[{"en":"These explosive materials must be kept away from heat.","vi":"Những vật liệu dễ nổ này phải được giữ cách xa nguồn nhiệt.","audioKind":"ex"},{"en":"The explosive growth of online shopping has increased demand for delivery services and created new challenges for urban planners.","vi":"Sự bùng nổ của mua sắm trực tuyến đã làm gia tăng nhu cầu về dịch vụ giao hàng và tạo ra những thách thức mới cho các nhà quy hoạch đô thị.","audioKind":"ex2"}],"collocations":[{"en":"explosive materials","vi":"vật liệu dễ nổ"},{"en":"explosive growth","vi":"sự tăng trưởng bùng nổ"},{"en":"explosive force","vi":"sức công phá, lực nổ"}],"wordFamily":["explode (v.)","explosion (n.)","explosively (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm explosive growth dùng để diễn tả sự gia tăng cực kỳ nhanh chóng, không có nghĩa là xảy ra vụ nổ vật lý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_friction', 'en-b2-71', 'friction', '/ˈfrɪkʃən/', 'B2', 'ma sát; lực ma sát; sự bất hòa; xích mích; căng thẳng giữa người với người hoặc nhóm người', 'n.', 'frictional (adj.)', NULL, 'Cả nghĩa ma sát vật lý và bất hòa xã hội thường đều không đếm được.', 'Rubbing your hands together creates friction and warms them.', NULL, 'Việc chà xát hai bàn tay vào nhau tạo ra ma sát và làm ấm chúng lên.', '{"wordId":"friction","ukIpa":"/ˈfrɪkʃən/","usIpa":"/ˈfrɪkʃən/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"Resistance when one surface moves or rubs against another.","vi":"ma sát; lực ma sát"},{"pos":"n.","en":"Disagreement or tension between people or groups.","vi":"sự bất hòa; xích mích; căng thẳng giữa người với người hoặc nhóm người"}],"examples":[{"en":"Rubbing your hands together creates friction and warms them.","vi":"Việc chà xát hai bàn tay vào nhau tạo ra ma sát và làm ấm chúng lên.","audioKind":"ex"},{"en":"Competition for limited housing can create friction between established residents and people moving into a city.","vi":"Sự cạnh tranh về nhà ở hạn chế có thể tạo ra xích mích giữa cư dân lâu năm và những người mới chuyển đến thành phố.","audioKind":"ex2"}],"collocations":[{"en":"reduce friction","vi":"giảm ma sát"},{"en":"friction between surfaces","vi":"ma sát giữa các bề mặt"},{"en":"cause friction","vi":"gây ra bất hòa"},{"en":"a source of friction","vi":"nguồn gốc của xung đột"}],"wordFamily":["frictional (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cả nghĩa ma sát vật lý và bất hòa xã hội thường đều không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_determine', 'en-b2-71', 'determine', '/dɪˈtɝːmɪn/', 'B2', 'xác định; tìm ra; quyết định; chi phối; hạ quyết tâm', 'v.', 'determination (n.), determined (adj.), determinant (n.)', 'Đồng nghĩa: establish, ascertain, decide', 'determine whether có nghĩa là tìm hiểu xem liệu; theo sau là một mệnh đề.', 'The mechanic determined why my bicycle brakes were sticking.', NULL, 'Thợ sửa xe đã tìm ra lý do tại sao phanh xe đạp của tôi bị kẹt.', '{"wordId":"determine","ukIpa":"/dɪˈtɜːmɪn/","usIpa":"/dɪˈtɝːmɪn/","cefr":"B2","topic":"science","senses":[{"pos":"v.","en":"To discover or establish something through examination.","vi":"xác định; tìm ra"},{"pos":"v.","en":"To control or strongly influence what happens.","vi":"quyết định; chi phối"},{"pos":"v.","en":"To make a firm decision to do something.","vi":"hạ quyết tâm; quyết định"}],"examples":[{"en":"The mechanic determined why my bicycle brakes were sticking.","vi":"Thợ sửa xe đã tìm ra lý do tại sao phanh xe đạp của tôi bị kẹt.","audioKind":"ex"},{"en":"Researchers must determine whether smaller classes improve learning outcomes before governments invest heavily in additional teaching staff.","vi":"Các nhà nghiên cứu phải xác định xem quy mô lớp học nhỏ hơn có cải thiện kết quả học tập hay không trước khi chính phủ đầu tư mạnh mẽ vào việc bổ sung đội ngũ giáo viên.","audioKind":"ex2"}],"collocations":[{"en":"determine the cause","vi":"xác định nguyên nhân"},{"en":"determine whether","vi":"xác định xem liệu"},{"en":"determine the outcome","vi":"quyết định kết quả"},{"en":"be determined to","vi":"quyết tâm làm gì"}],"wordFamily":["determination (n.)","determined (adj.)","determinant (n.)"],"synonyms":["establish","ascertain","decide"],"antonyms":[],"tipVi":"determine whether có nghĩa là tìm hiểu xem liệu; theo sau là một mệnh đề.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fibre', 'en-b2-71', 'fibre', '/ˈfaɪbɚ/', 'B2', 'sợi; chất xơ; chất xơ thực phẩm', 'n.', 'fibrous (adj.)', NULL, 'Cách viết theo kiểu Mỹ là fiber; nghĩa chất xơ thường là danh từ không đếm được.', 'A loose fibre was sticking out of my scarf.', NULL, 'Một sợi chỉ lỏng lẻo đang chìa ra ngoài chiếc khăn choàng của tôi.', '{"wordId":"fibre","ukIpa":"/ˈfaɪbə/","usIpa":"/ˈfaɪbɚ/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"a thin thread forming part of a material or tissue","vi":"sợi"},{"pos":"n.","en":"plant material in food that helps digestion","vi":"chất xơ; chất xơ thực phẩm"}],"examples":[{"en":"A loose fibre was sticking out of my scarf.","vi":"Một sợi chỉ lỏng lẻo đang chìa ra ngoài chiếc khăn choàng của tôi.","audioKind":"ex"},{"en":"A diet rich in fibre can support digestive health and help people feel full for longer.","vi":"Chế độ ăn giàu chất xơ có thể hỗ trợ sức khỏe hệ tiêu hóa và giúp tạo cảm giác no lâu hơn.","audioKind":"ex2"}],"collocations":[{"en":"natural fibres","vi":"sợi tự nhiên"},{"en":"dietary fibre","vi":"chất xơ"},{"en":"optical fibre","vi":"sợi quang"}],"wordFamily":["fibrous (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cách viết theo kiểu Mỹ là fiber; nghĩa chất xơ thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reproduce', 'en-b2-71', 'reproduce', '/ˌriːprəˈduːs/', 'B2', 'sao chép; tái tạo; tái hiện; sinh sản; nhân giống', 'v.', 'reproduction (n.), reproductive (adj.), reproducible (adj.)', 'Đồng nghĩa: replicate, copy', 'Dùng ngoại động từ khi sao chép vật gì; thường dùng nội động từ khi nói về việc sinh sản.', 'This printer reproduces every detail of my pencil drawings.', NULL, 'Máy in này sao chép lại từng chi tiết trong bức tranh chì của tôi.', '{"wordId":"reproduce","ukIpa":"/ˌriːprəˈdjuːs/","usIpa":"/ˌriːprəˈduːs/","cefr":"B2","topic":"science","senses":[{"pos":"v.","en":"To make a copy or create the same result again.","vi":"sao chép; tái tạo; tái hiện"},{"pos":"v.","en":"To produce young animals, plants, or other living organisms.","vi":"sinh sản; nhân giống"}],"examples":[{"en":"This printer reproduces every detail of my pencil drawings.","vi":"Máy in này sao chép lại từng chi tiết trong bức tranh chì của tôi.","audioKind":"ex"},{"en":"Researchers must describe their methods clearly so that other teams can reproduce their results independently.","vi":"Các nhà nghiên cứu phải miêu tả phương pháp rõ ràng để các nhóm khác có thể độc lập tái hiện lại kết quả của họ.","audioKind":"ex2"}],"collocations":[{"en":"reproduce results","vi":"tái hiện kết quả"},{"en":"reproduce an image","vi":"sao chép hình ảnh"},{"en":"reproduce sexually","vi":"sinh sản hữu tính"}],"wordFamily":["reproduction (n.)","reproductive (adj.)","reproducible (adj.)"],"synonyms":["replicate","copy"],"antonyms":[],"tipVi":"Dùng ngoại động từ khi sao chép vật gì; thường dùng nội động từ khi nói về việc sinh sản.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_finding', 'en-b2-71', 'finding', '/ˈfaɪndɪŋ/', 'B2', 'kết quả nghiên cứu; phát hiện điều tra; phán quyết; kết luận chính thức', 'n.', 'find (v.), finder (n.)', 'Đồng nghĩa: result, conclusion', 'Khi chỉ kết quả nghiên cứu hoặc điều tra, người ta thường dùng dạng số nhiều findings.', 'The doctor''s findings explained why I felt so tired.', NULL, 'Kết quả khám của bác sĩ đã giải thích lý do tại sao tôi cảm thấy mệt mỏi đến vậy.', '{"wordId":"finding","ukIpa":"/ˈfaɪndɪŋ/","usIpa":"/ˈfaɪndɪŋ/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"Information discovered through research or an investigation.","vi":"kết quả nghiên cứu; phát hiện điều tra"},{"pos":"n.","en":"An official decision made by a court after considering evidence.","vi":"phán quyết; kết luận chính thức"}],"examples":[{"en":"The doctor''s findings explained why I felt so tired.","vi":"Kết quả khám của bác sĩ đã giải thích lý do tại sao tôi cảm thấy mệt mỏi đến vậy.","audioKind":"ex"},{"en":"The findings indicate that affordable public transport can significantly improve access to employment in disadvantaged areas.","vi":"Các phát hiện chỉ ra rằng hệ thống giao thông công cộng giá rẻ có thể cải thiện đáng kể cơ hội việc làm ở các khu vực thiệt thòi.","audioKind":"ex2"}],"collocations":[{"en":"research findings","vi":"kết quả nghiên cứu"},{"en":"key findings","vi":"phát hiện cốt lõi"},{"en":"publish the findings","vi":"công bố kết quả"},{"en":"a finding of fact","vi":"kết luận về mặt sự thật"}],"wordFamily":["find (v.)","finder (n.)"],"synonyms":["result","conclusion"],"antonyms":[],"tipVi":"Khi chỉ kết quả nghiên cứu hoặc điều tra, người ta thường dùng dạng số nhiều findings.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_measurement', 'en-b2-71', 'measurement', '/ˈmeʒərmənt/', 'B2', 'sự đo lường; quá trình đo lường; số đo; kích thước hoặc lượng đo được', 'n.', 'measure (v.), measurable (adj.)', NULL, 'Chỉ quá trình đo lường thì thường không đếm được; chỉ kích thước cụ thể thì đếm được.', 'We took careful measurements before buying the new curtains.', NULL, 'Chúng tôi đã đo đạc cẩn thận trước khi mua bộ rèm cửa mới.', '{"wordId":"measurement","ukIpa":"/ˈmeʒəmənt/","usIpa":"/ˈmeʒərmənt/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"The process of finding the size, amount, or degree of something.","vi":"sự đo lường; quá trình đo lường"},{"pos":"n.","en":"A size or quantity found by measuring something.","vi":"số đo; kích thước hoặc lượng đo được"}],"examples":[{"en":"We took careful measurements before buying the new curtains.","vi":"Chúng tôi đã đo đạc cẩn thận trước khi mua bộ rèm cửa mới.","audioKind":"ex"},{"en":"Accurate measurement of air pollution helps governments assess whether environmental policies are protecting public health.","vi":"Việc đo lường chính xác tình trạng ô nhiễm không khí giúp các chính phủ đánh giá xem các chính sách môi trường có đang bảo vệ sức khỏe cộng đồng hay không.","audioKind":"ex2"}],"collocations":[{"en":"take measurements","vi":"tiến hành đo đạc"},{"en":"accurate measurement","vi":"phép đo chính xác"},{"en":"a unit of measurement","vi":"đơn vị đo lường"}],"wordFamily":["measure (v.)","measurable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ quá trình đo lường thì thường không đếm được; chỉ kích thước cụ thể thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_extract', 'en-b2-71', 'extract', '/ɪkˈstrækt/', 'B2', 'rút ra; lấy ra; chiết xuất; đoạn trích; bài văn tuyển chọn; chất chiết xuất; dịch chiết', 'v.', 'extraction (n.), extractor (n.)', NULL, 'Động từ trọng âm ở âm tiết sau; danh từ phát âm là /ˈekstrækt/.', 'The dentist carefully extracted the damaged tooth this morning.', NULL, 'Sáng nay nha sĩ đã cẩn thận nhổ chiếc răng bị hỏng.', '{"wordId":"extract","ukIpa":"/ɪkˈstrækt/","usIpa":"/ɪkˈstrækt/","cefr":"B2","topic":"science","senses":[{"pos":"v.","en":"to remove or obtain something from a larger source","vi":"rút ra; lấy ra; chiết xuất"},{"pos":"n.","en":"a short passage taken from a longer piece of writing","vi":"đoạn trích; bài văn tuyển chọn"},{"pos":"n.","en":"a substance obtained by removing it from its original source","vi":"chất chiết xuất; dịch chiết"}],"examples":[{"en":"The dentist carefully extracted the damaged tooth this morning.","vi":"Sáng nay nha sĩ đã cẩn thận nhổ chiếc răng bị hỏng.","audioKind":"ex"},{"en":"Researchers extract useful information from large datasets to identify patterns in household energy consumption.","vi":"Các nhà nghiên cứu rút ra thông tin hữu ích từ các tập dữ liệu lớn để nhận diện các xu hướng tiêu thụ năng lượng trong hộ gia đình.","audioKind":"ex2"}],"collocations":[{"en":"extract information from","vi":"trích xuất thông tin từ"},{"en":"extract a tooth","vi":"nhổ răng"},{"en":"an extract from a novel","vi":"đoạn trích từ một cuốn tiểu thuyết"},{"en":"vanilla extract","vi":"tinh chất vani"}],"wordFamily":["extraction (n.)","extractor (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ trọng âm ở âm tiết sau; danh từ phát âm là /ˈekstrækt/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_explosion', 'en-b2-71', 'explosion', '/ɪkˈsploʊʒən/', 'B2', 'vụ nổ; sự bùng nổ; sự gia tăng đột ngột; sự bộc phát mạnh mẽ (cảm xúc)', 'n.', 'explode (v.), explosive (adj.)', 'Đồng nghĩa: blast', 'Khi chỉ sự gia tăng số lượng, người ta thường dùng an explosion in đi kèm danh từ.', 'We heard a distant explosion and saw smoke rising.', NULL, 'Chúng tôi nghe thấy một tiếng nổ từ xa và nhìn thấy khói bốc lên.', '{"wordId":"explosion","ukIpa":"/ɪkˈspləʊʒən/","usIpa":"/ɪkˈsploʊʒən/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"a sudden violent release of energy, usually with a bang","vi":"vụ nổ"},{"pos":"n.","en":"a sudden and very large increase","vi":"sự bùng nổ; sự gia tăng đột ngột"},{"pos":"n.","en":"a sudden strong expression of emotion","vi":"sự bộc phát mạnh mẽ (cảm xúc)"}],"examples":[{"en":"We heard a distant explosion and saw smoke rising.","vi":"Chúng tôi nghe thấy một tiếng nổ từ xa và nhìn thấy khói bốc lên.","audioKind":"ex"},{"en":"The explosion in online shopping has increased demand for delivery services and created new challenges for urban transport.","vi":"Sự bùng nổ của mua sắm trực tuyến đã làm tăng nhu cầu về dịch vụ giao hàng và tạo ra những thách thức mới cho giao thông đô thị.","audioKind":"ex2"}],"collocations":[{"en":"a gas explosion","vi":"vụ nổ khí ga"},{"en":"a population explosion","vi":"sự bùng nổ dân số"},{"en":"an explosion of anger","vi":"cơn giận bộc phát"}],"wordFamily":["explode (v.)","explosive (adj.)"],"synonyms":["blast"],"antonyms":[],"tipVi":"Khi chỉ sự gia tăng số lượng, người ta thường dùng an explosion in đi kèm danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_composition', 'en-b2-71', 'composition', '/ˌkɑːmpəˈzɪʃən/', 'B2', 'thành phần; cấu tạo; bài văn; tác phẩm âm nhạc; sự sáng tác; việc biên soạn', 'n.', 'compose (v.), composer (n.), compositional (adj.)', NULL, 'Chỉ cấu trúc hoặc quá trình sáng tác thường không đếm được; chỉ tác phẩm thì đếm được.', 'We tested the composition of soil in our garden.', NULL, 'Chúng tôi đã kiểm tra thành phần của đất trong khu vườn nhà mình.', '{"wordId":"composition","ukIpa":"/ˌkɒmpəˈzɪʃən/","usIpa":"/ˌkɑːmpəˈzɪʃən/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"The parts or substances that something consists of","vi":"thành phần; cấu tạo"},{"pos":"n.","en":"A piece of writing or music","vi":"bài văn; tác phẩm âm nhạc"},{"pos":"n.","en":"The activity of creating music or written work","vi":"sự sáng tác; việc biên soạn"}],"examples":[{"en":"We tested the composition of soil in our garden.","vi":"Chúng tôi đã kiểm tra thành phần của đất trong khu vườn nhà mình.","audioKind":"ex"},{"en":"Changes in the composition of household waste can reveal how consumer habits develop over time.","vi":"Những thay đổi trong thành phần rác thải sinh hoạt có thể cho thấy thói quen tiêu dùng phát triển như thế nào theo thời gian.","audioKind":"ex2"}],"collocations":[{"en":"chemical composition","vi":"thành phần hóa học"},{"en":"soil composition","vi":"thành phần đất"},{"en":"musical composition","vi":"tác phẩm âm nhạc"},{"en":"write a composition","vi":"viết một bài văn"}],"wordFamily":["compose (v.)","composer (n.)","compositional (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ cấu trúc hoặc quá trình sáng tác thường không đếm được; chỉ tác phẩm thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_isolate', 'en-b2-71', 'isolate', '/ˈaɪsəleɪt/', 'B2', 'cô lập; cách ly; tách riêng; xác định riêng biệt', 'v.', 'isolation (n.), isolated (adj.)', 'Đồng nghĩa: separate, segregate · Trái nghĩa: integrate', 'Thường dùng isolate A from B; tính từ là isolated.', 'Heavy snow isolated the village from the nearest town.', NULL, 'Tuyết dày đã cô lập ngôi làng khỏi thị trấn gần nhất.', '{"wordId":"isolate","ukIpa":"/ˈaɪsəleɪt/","usIpa":"/ˈaɪsəleɪt/","cefr":"B2","topic":"science","senses":[{"pos":"v.","en":"Separate someone or something from others.","vi":"cô lập; cách ly"},{"pos":"v.","en":"Separate or identify one substance, factor, or problem for examination.","vi":"tách riêng; xác định riêng biệt"}],"examples":[{"en":"Heavy snow isolated the village from the nearest town.","vi":"Tuyết dày đã cô lập ngôi làng khỏi thị trấn gần nhất.","audioKind":"ex"},{"en":"Researchers must isolate the effects of income before drawing conclusions about the relationship between education and health.","vi":"Các nhà nghiên cứu phải tách riêng các tác động của thu nhập trước khi đưa ra kết luận về mối quan hệ giữa giáo dục và sức khỏe.","audioKind":"ex2"}],"collocations":[{"en":"isolate someone from","vi":"cô lập ai khỏi điều gì"},{"en":"isolate a variable","vi":"tách riêng một biến số"},{"en":"isolate the cause","vi":"xác định nguyên nhân"}],"wordFamily":["isolation (n.)","isolated (adj.)"],"synonyms":["separate","segregate"],"antonyms":["integrate"],"tipVi":"Thường dùng isolate A from B; tính từ là isolated.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hardness', 'en-b2-71', 'hardness', '/ˈhɑːrdnəs/', 'B2', 'độ cứng; tính rắn chắc; độ cứng của nước (hàm lượng canxi và magie hòa tan)', 'n.', 'hard (adj.), harden (v.), hardening (n.)', 'Trái nghĩa: softness', 'hardness chỉ độ cứng vật lý; còn hardship mới chỉ sự gian khổ, khó khăn.', 'The hardness of this wood makes it difficult to carve.', NULL, 'Độ cứng của loại gỗ này khiến cho việc chạm trổ trở nên khó khăn.', '{"wordId":"hardness","ukIpa":"/ˈhɑːdnəs/","usIpa":"/ˈhɑːrdnəs/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"How strongly a material resists scratching, cutting, or denting.","vi":"độ cứng; tính rắn chắc"},{"pos":"n.","en":"The amount of dissolved calcium and magnesium in water.","vi":"độ cứng của nước (hàm lượng canxi và magie hòa tan)"}],"examples":[{"en":"The hardness of this wood makes it difficult to carve.","vi":"Độ cứng của loại gỗ này khiến cho việc chạm trổ trở nên khó khăn.","audioKind":"ex"},{"en":"Engineers assess the hardness of different materials before selecting suitable components for bridges and other major structures.","vi":"Các kỹ sư đánh giá độ cứng của các vật liệu khác nhau trước khi lựa chọn các cấu kiện phù hợp cho cầu đường và các công trình lớn khác.","audioKind":"ex2"}],"collocations":[{"en":"surface hardness","vi":"độ cứng bề mặt"},{"en":"water hardness","vi":"độ cứng của nước"},{"en":"hardness test","vi":"kiểm tra độ cứng"}],"wordFamily":["hard (adj.)","harden (v.)","hardening (n.)"],"synonyms":[],"antonyms":["softness"],"tipVi":"hardness chỉ độ cứng vật lý; còn hardship mới chỉ sự gian khổ, khó khăn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_steel', 'en-b2-71', 'steel', '/stiːl/', 'B2', 'thép; ngành thép; lấy hết can đảm; tự chuẩn bị tâm lý đối mặt với khó khăn', 'n.', 'steely (adj.)', NULL, 'steel là thép, steal là ăn cắp; hai từ này phát âm y hệt nhau.', 'The new bridge has a frame made of steel.', NULL, 'Cây cầu mới có phần khung được làm bằng thép.', '{"wordId":"steel","ukIpa":"/stiːl/","usIpa":"/stiːl/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A strong metal made mainly from iron and some carbon","vi":"thép; ngành thép"},{"pos":"v.","en":"To prepare yourself mentally for something difficult or unpleasant","vi":"lấy hết can đảm; tự chuẩn bị tâm lý đối mặt với khó khăn"}],"examples":[{"en":"The new bridge has a frame made of steel.","vi":"Cây cầu mới có phần khung được làm bằng thép.","audioKind":"ex"},{"en":"Recycling steel can reduce demand for raw materials and lower energy consumption in the construction industry.","vi":"Tái chế thép có thể giảm nhu cầu về nguyên liệu thô và hạ mức tiêu thụ năng lượng trong ngành xây dựng.","audioKind":"ex2"}],"collocations":[{"en":"stainless steel","vi":"thép không gỉ"},{"en":"steel production","vi":"sản xuất thép"},{"en":"steel yourself for","vi":"chuẩn bị tinh thần đối mặt với"}],"wordFamily":["steely (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"steel là thép, steal là ăn cắp; hai từ này phát âm y hệt nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_phase', 'en-b2-71', 'phase', '/feɪz/', 'B2', 'giai đoạn; thời kỳ; pha (mặt trăng); tiến hành theo giai đoạn; thực hiện từng bước', 'n.', 'phased (adj.)', 'Đồng nghĩa: stage, period', 'phase in có nghĩa là dần dần đưa vào, còn phase out có nghĩa là dần dần loại bỏ.', 'The kitchen repairs have entered their final phase.', NULL, 'Việc sửa chữa nhà bếp đã bước vào giai đoạn cuối.', '{"wordId":"phase","ukIpa":"/feɪz/","usIpa":"/feɪz/","cefr":"B2","topic":"science","senses":[{"pos":"n.","en":"A distinct period in a process of change or development.","vi":"giai đoạn; thời kỳ"},{"pos":"n.","en":"One of the changing shapes of the moon as seen.","vi":"pha (mặt trăng)"},{"pos":"v.","en":"To introduce or remove something gradually in planned stages.","vi":"tiến hành theo giai đoạn; thực hiện từng bước"}],"examples":[{"en":"The kitchen repairs have entered their final phase.","vi":"Việc sửa chữa nhà bếp đã bước vào giai đoạn cuối.","audioKind":"ex"},{"en":"During the initial phase of urban development, planners should prioritise affordable housing and reliable public transport.","vi":"Trong giai đoạn đầu của quá trình phát triển đô thị, các nhà quy hoạch nên ưu tiên nhà ở có giá cả phải chăng và hệ thống giao thông công cộng đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"an initial phase","vi":"giai đoạn ban đầu"},{"en":"a phase of development","vi":"giai đoạn phát triển"},{"en":"phase out","vi":"dần dần loại bỏ"},{"en":"phase in","vi":"dần dần đưa vào"}],"wordFamily":["phased (adj.)"],"synonyms":["stage","period"],"antonyms":[],"tipVi":"phase in có nghĩa là dần dần đưa vào, còn phase out có nghĩa là dần dần loại bỏ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_investigate', 'en-b2-71', 'investigate', '/ɪnˈvestɪɡeɪt/', 'B2', 'điều tra; tìm hiểu; nghiên cứu; khảo sát', 'v.', 'investigation (n.), investigator (n.), investigative (adj.)', 'Đồng nghĩa: examine, probe', 'Động từ này đi thẳng trực tiếp đến đối tượng cần điều tra như investigate the problem mà không cần dùng giới từ into.', 'A plumber came to investigate the strange noise upstairs.', NULL, 'Một thợ sửa ống nước đã đến để tìm hiểu nguyên nhân gây ra tiếng động lạ ở tầng trên.', '{"wordId":"investigate","ukIpa":"/ɪnˈvestɪɡeɪt/","usIpa":"/ɪnˈvestɪɡeɪt/","cefr":"B2","topic":"science","senses":[{"pos":"v.","en":"To examine facts carefully to discover what happened or why.","vi":"điều tra; tìm hiểu"},{"pos":"v.","en":"To study a subject carefully to learn more about it.","vi":"nghiên cứu; khảo sát"}],"examples":[{"en":"A plumber came to investigate the strange noise upstairs.","vi":"Một thợ sửa ống nước đã đến để tìm hiểu nguyên nhân gây ra tiếng động lạ ở tầng trên.","audioKind":"ex"},{"en":"Researchers are investigating how access to green spaces affects the mental health of urban residents.","vi":"Các nhà nghiên cứu đang tìm hiểu xem việc tiếp cận không gian xanh ảnh hưởng như thế nào đến sức khỏe tinh thần của cư dân thành thị.","audioKind":"ex2"}],"collocations":[{"en":"investigate a complaint","vi":"điều tra khiếu nại"},{"en":"investigate the cause","vi":"điều tra nguyên nhân"},{"en":"investigate a link","vi":"nghiên cứu mối liên hệ"}],"wordFamily":["investigation (n.)","investigator (n.)","investigative (adj.)"],"synonyms":["examine","probe"],"antonyms":[],"tipVi":"Động từ này đi thẳng trực tiếp đến đối tượng cần điều tra như investigate the problem mà không cần dùng giới từ into.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_71_1', 'en-b2-71', 'Cách dùng “bacterium” (n.) — vi khuẩn', 'a harmful bacterium  ·  disease-causing bacteria  ·  beneficial bacteria', 'Dạng số ít là bacterium, dạng số nhiều là bacteria; khi bacteria ở số ít/số nhiều làm chủ ngữ thì chia động từ số nhiều là are.', 'Họ từ (Word Family): bacteria (n.), bacterial (adj.), antibacterial (adj.)', '[{"hanzi":"Under the microscope, a single bacterium moved slowly.","pinyin":"","meaning":"Dưới kính hiển vi, một vi khuẩn đơn lẻ đang di chuyển chậm chạp."},{"hanzi":"Scientists identified a bacterium that could help remove harmful chemicals from polluted soil without damaging nearby plants.","pinyin":"","meaning":"Các nhà khoa học đã xác định được một loại vi khuẩn có khả năng giúp loại bỏ các hóa chất độc hại khỏi đất bị ô nhiễm mà không gây hại cho thực vật xung quanh."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_71_2', 'en-b2-71', 'Cách dùng “investigate” (v.) — điều tra; tìm hiểu', 'investigate a complaint  ·  investigate the cause  ·  investigate a link', 'Động từ này đi thẳng trực tiếp đến đối tượng cần điều tra như investigate the problem mà không cần dùng giới từ into.', 'Họ từ (Word Family): investigation (n.), investigator (n.), investigative (adj.) | Đồng nghĩa: examine, probe', '[{"hanzi":"A plumber came to investigate the strange noise upstairs.","pinyin":"","meaning":"Một thợ sửa ống nước đã đến để tìm hiểu nguyên nhân gây ra tiếng động lạ ở tầng trên."},{"hanzi":"Researchers are investigating how access to green spaces affects the mental health of urban residents.","pinyin":"","meaning":"Các nhà nghiên cứu đang tìm hiểu xem việc tiếp cận không gian xanh ảnh hưởng như thế nào đến sức khỏe tinh thần của cư dân thành thị."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_71_3', 'en-b2-71', 'Cách dùng “explosive” (adj.) — dễ nổ; có tính nổ', 'explosive materials  ·  explosive growth  ·  explosive force', 'Cụm explosive growth dùng để diễn tả sự gia tăng cực kỳ nhanh chóng, không có nghĩa là xảy ra vụ nổ vật lý.', 'Họ từ (Word Family): explode (v.), explosion (n.), explosively (adv.)', '[{"hanzi":"These explosive materials must be kept away from heat.","pinyin":"","meaning":"Những vật liệu dễ nổ này phải được giữ cách xa nguồn nhiệt."},{"hanzi":"The explosive growth of online shopping has increased demand for delivery services and created new challenges for urban planners.","pinyin":"","meaning":"Sự bùng nổ của mua sắm trực tuyến đã làm gia tăng nhu cầu về dịch vụ giao hàng và tạo ra những thách thức mới cho các nhà quy hoạch đô thị."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_71_4', 'en-b2-71', 'Cách dùng “longitude” (n.) — kinh độ', 'latitude and longitude  ·  degrees of longitude  ·  east longitude', '"longitude" là kinh độ (chia theo hướng đông - tây); "latitude" là vĩ độ (chia theo hướng bắc - nam).', 'Họ từ (Word Family): longitudinal (adj.)', '[{"hanzi":"Our guide checked our longitude before steering the boat east.","pinyin":"","meaning":"Người dẫn đường đã kiểm tra kinh độ của chúng tôi trước khi lái thuyền về hướng đông."},{"hanzi":"Accurate measurements of longitude and latitude allow navigation systems to determine a vehicle''s position on Earth.","pinyin":"","meaning":"Các phép đo chính xác về kinh độ và vĩ độ cho phép hệ thống định vị xác định vị trí của phương tiện trên Trái Đất."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_71_1', 'en-b2-71', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_71_1_1', 'ten_b2_71_1', 'trace', 'The plumber traced the leak to a cracked pipe.', 'The plumber traced the leak to a cracked pipe.', '/treɪs/', 'Thợ sửa ống nước đã lần ra nguồn gốc chỗ rò rỉ là từ một đường ống bị nứt.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_71_1_2', 'ten_b2_71_1', 'longitude', 'Our guide checked our longitude before steering the boat east.', 'Our guide checked our longitude before steering the boat east.', '/ˈlɑːndʒɪtuːd/', 'Người dẫn đường đã kiểm tra kinh độ của chúng tôi trước khi lái thuyền về hướng đông.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_71_1_3', 'ten_b2_71_1', 'volume', 'Please turn the volume down while the baby sleeps.', 'Please turn the volume down while the baby sleeps.', '/ˈvɑːljuːm/', 'Làm ơn vặn nhỏ âm lượng lại trong lúc em bé đang ngủ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_71_1_4', 'ten_b2_71_1', 'nitrogen', 'These beans help add nitrogen to our garden soil.', 'These beans help add nitrogen to our garden soil.', '/ˈnaɪtrədʒən/', 'Những cây đậu này giúp bổ sung nitơ cho đất trong vườn của chúng tôi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_71_1_5', 'ten_b2_71_1', 'constant', 'The constant noise outside kept me awake all night.', 'The constant noise outside kept me awake all night.', '/ˈkɑːnstənt/', 'Tiếng ồn liên tục bên ngoài khiến tôi thức trắng đêm.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_71_1_6', 'ten_b2_71_1', 'optical', 'This optical illusion makes the flat drawing look three-dimensional.', 'This optical illusion makes the flat drawing look three-dimensional.', '/ˈɑːptɪkəl/', 'Hiệu ứng thị giác này làm cho bức vẽ phẳng trông có vẻ nổi ba chiều.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_71_1_7', 'ten_b2_71_1', 'electron', 'Our teacher used coloured beads to represent each electron.', 'Our teacher used coloured beads to represent each electron.', '/ɪˈlektrɑːn/', 'Giáo viên của chúng tôi dùng các hạt cườm màu để biểu diễn từng hạt electron.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_71_1_8', 'ten_b2_71_1', 'orbit', 'We watched an animation showing the satellite''s orbit.', 'We watched an animation showing the satellite''s orbit.', '/ˈɔːrbɪt/', 'Chúng tôi đã xem một đoạn hoạt họa mô tả quỹ đạo chuyển động của vệ tinh.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_71_1_1', 'en-b2-71', 'ten_b2_71_1', 'listening', 'listening', 'The plumber traced the leak to a cracked pipe.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một sợi chỉ lỏng lẻo đang chìa ra ngoài chiếc khăn choàng của tôi.","Việc chà xát hai bàn tay vào nhau tạo ra ma sát và làm ấm chúng lên.","Thợ sửa ống nước đã lần ra nguồn gốc chỗ rò rỉ là từ một đường ống bị nứt.","Những cây đậu này giúp bổ sung nitơ cho đất trong vườn của chúng tôi."]'::jsonb, 2, 'The plumber traced the leak to a cracked pipe. → Thợ sửa ống nước đã lần ra nguồn gốc chỗ rò rỉ là từ một đường ống bị nứt.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_71_1_2', 'en-b2-71', 'ten_b2_71_1', 'listening', 'listening', 'Our guide checked our longitude before steering the boat east.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Dưới kính hiển vi, một vi khuẩn đơn lẻ đang di chuyển chậm chạp.","Người dẫn đường đã kiểm tra kinh độ của chúng tôi trước khi lái thuyền về hướng đông.","Tuyết dày đã cô lập ngôi làng khỏi thị trấn gần nhất.","Chúng tôi đã xem một đoạn hoạt họa mô tả quỹ đạo chuyển động của vệ tinh."]'::jsonb, 1, 'Our guide checked our longitude before steering the boat east. → Người dẫn đường đã kiểm tra kinh độ của chúng tôi trước khi lái thuyền về hướng đông.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_71_1_3', 'en-b2-71', 'ten_b2_71_1', 'listening', 'listening', 'Please turn the volume down while the baby sleeps.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã kiểm tra thành phần của đất trong khu vườn nhà mình.","Kết quả khám của bác sĩ đã giải thích lý do tại sao tôi cảm thấy mệt mỏi đến vậy.","Làm ơn vặn nhỏ âm lượng lại trong lúc em bé đang ngủ.","Một sợi chỉ lỏng lẻo đang chìa ra ngoài chiếc khăn choàng của tôi."]'::jsonb, 2, 'Please turn the volume down while the baby sleeps. → Làm ơn vặn nhỏ âm lượng lại trong lúc em bé đang ngủ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_71_2', 'en-b2-71', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_71_2_1', 'ten_b2_71_2', 'trace', 'Researchers can trace changes in regional diets by examining food remains discovered at ancient settlements.', 'Researchers can trace changes in regional diets by examining food remains discovered at ancient settlements.', '/treɪs/', 'Các nhà nghiên cứu có thể truy nguyên sự thay đổi trong chế độ ăn uống theo vùng bằng cách kiểm tra các tàn tích thức ăn được phát hiện tại các khu định cư cổ đại.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_71_2_2', 'ten_b2_71_2', 'longitude', 'Accurate measurements of longitude and latitude allow navigation systems to determine a vehicle''s position on Earth.', 'Accurate measurements of longitude and latitude allow navigation systems to determine a vehicle''s position on Earth.', '/ˈlɑːndʒɪtuːd/', 'Các phép đo chính xác về kinh độ và vĩ độ cho phép hệ thống định vị xác định vị trí của phương tiện trên Trái Đất.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_71_2_3', 'ten_b2_71_2', 'volume', 'The growing volume of household waste highlights the need for better recycling facilities in urban areas.', 'The growing volume of household waste highlights the need for better recycling facilities in urban areas.', '/ˈvɑːljuːm/', 'Khối lượng rác thải sinh hoạt ngày càng tăng làm nổi bật nhu cầu cần có các cơ sở tái chế tốt hơn ở các khu đô thị.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_71_2_4', 'ten_b2_71_2', 'nitrogen', 'Excess nitrogen from agricultural fertilisers can enter rivers, encouraging rapid algae growth and damaging aquatic ecosystems.', 'Excess nitrogen from agricultural fertilisers can enter rivers, encouraging rapid algae growth and damaging aquatic ecosystems.', '/ˈnaɪtrədʒən/', 'Lượng nitơ dư thừa từ phân bón nông nghiệp có thể ngấm vào sông ngòi, thúc đẩy tảo phát triển nhanh chóng và tàn phá các hệ sinh thái dưới nước.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_71_2_5', 'ten_b2_71_2', 'constant', 'Maintaining a constant temperature in public buildings can improve comfort but may increase energy consumption.', 'Maintaining a constant temperature in public buildings can improve comfort but may increase energy consumption.', '/ˈkɑːnstənt/', 'Duy trì nhiệt độ ổn định trong các tòa nhà công cộng có thể nâng cao sự thoải mái nhưng có thể làm tăng mức tiêu thụ năng lượng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_71_2_6', 'ten_b2_71_2', 'optical', 'Optical fibres enable rapid data transmission, supporting the expansion of reliable internet access in remote communities.', 'Optical fibres enable rapid data transmission, supporting the expansion of reliable internet access in remote communities.', '/ˈɑːptɪkəl/', 'Cáp quang cho phép truyền dữ liệu tốc độ cao, hỗ trợ mở rộng dịch vụ internet đáng tin cậy ở các cộng đồng vùng sâu vùng xa.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_71_2_1', 'en-b2-71', 'ten_b2_71_2', 'listening', 'listening', 'Researchers can trace changes in regional diets by examining food remains discovered at ancient settlements.', NULL, 'Trong câu vừa nghe, từ “trace” mang nghĩa nào sau đây?', '["người đại diện; người ủy quyền","truy tìm; lần theo dấu vết; truy nguyên","phi thường; xuất sắc","do đó; vì vậy; từ đó"]'::jsonb, 1, '“trace” (/treɪs/): truy tìm; lần theo dấu vết; truy nguyên. Câu đầy đủ: Researchers can trace changes in regional diets by examining food remains discovered at ancient settlements.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_71_2_2', 'en-b2-71', 'ten_b2_71_2', 'listening', 'listening', 'Accurate measurements of longitude and latitude allow navigation systems to determine a vehicle''s position on Earth.', NULL, 'Trong câu vừa nghe, từ “longitude” mang nghĩa nào sau đây?', '["kinh độ","thúc đẩy; truyền động lực","tạo ra; sinh ra","hạnh phúc; sự an sinh; phúc lợi"]'::jsonb, 0, '“longitude” (/ˈlɑːndʒɪtuːd/): kinh độ. Câu đầy đủ: Accurate measurements of longitude and latitude allow navigation systems to determine a vehicle''s position on Earth.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
