INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_71_1', 'en-b2-71', NULL, 'comprehensive_test', 'listening', 'trace', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["truy tìm; lần theo dấu vết; truy nguyên","bạo lực; hung bạo","bền vững; không gây hại môi trường","lời nói nhảm; điều vô lý; chuyện nhảm nhí"]'::jsonb, 0, 'trace (/treɪs/) → truy tìm; lần theo dấu vết; truy nguyên; dấu vết; vết tích; lượng nhỏ; vẽ theo khung; can (tranh); tô theo đường nét', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_71_2', 'en-b2-71', NULL, 'comprehensive_test', 'listening', 'Our guide checked our longitude before steering the boat east.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã đo đạc cẩn thận trước khi mua bộ rèm cửa mới.","Dưới kính hiển vi, một vi khuẩn đơn lẻ đang di chuyển chậm chạp.","Hiệu ứng thị giác này làm cho bức vẽ phẳng trông có vẻ nổi ba chiều.","Người dẫn đường đã kiểm tra kinh độ của chúng tôi trước khi lái thuyền về hướng đông."]'::jsonb, 3, 'Our guide checked our longitude before steering the boat east. → Người dẫn đường đã kiểm tra kinh độ của chúng tôi trước khi lái thuyền về hướng đông.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_71_3', 'en-b2-71', NULL, 'comprehensive_test', 'listening', 'volume', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chủ nhà; chủ đất (cho thuê)","giờ làm thêm; tiền làm thêm giờ","thợ gốm; người làm gốm","thể tích; khối lượng; tổng lượng"]'::jsonb, 3, 'volume (/ˈvɑːljuːm/) → thể tích; khối lượng; tổng lượng; âm lượng; tập (sách); cuốn', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_71_4', 'en-b2-71', NULL, 'comprehensive_test', 'listening', 'These beans help add nitrogen to our garden soil.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi nghe thấy một tiếng nổ từ xa và nhìn thấy khói bốc lên.","Những cây đậu này giúp bổ sung nitơ cho đất trong vườn của chúng tôi.","Những vật liệu dễ nổ này phải được giữ cách xa nguồn nhiệt.","Hiệu ứng thị giác này làm cho bức vẽ phẳng trông có vẻ nổi ba chiều."]'::jsonb, 1, 'These beans help add nitrogen to our garden soil. → Những cây đậu này giúp bổ sung nitơ cho đất trong vườn của chúng tôi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_71_5', 'en-b2-71', NULL, 'comprehensive_test', 'listening', 'constant', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["động lực; sự khuyến khích; tiền thưởng khích lệ","cuộc mít tinh; cuộc biểu tình","liên tục; không ngừng","nâng cao; tăng cường; cải thiện"]'::jsonb, 2, 'constant (/ˈkɑːnstənt/) → liên tục; không ngừng; không đổi; hằng định; hằng số', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_71_6', 'en-b2-71', NULL, 'comprehensive_test', 'listening', 'This optical illusion makes the flat drawing look three-dimensional.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hiệu ứng thị giác này làm cho bức vẽ phẳng trông có vẻ nổi ba chiều.","Độ cứng của loại gỗ này khiến cho việc chạm trổ trở nên khó khăn.","Dưới kính hiển vi, một vi khuẩn đơn lẻ đang di chuyển chậm chạp.","Chúng tôi đã xem một đoạn hoạt họa mô tả quỹ đạo chuyển động của vệ tinh."]'::jsonb, 0, 'This optical illusion makes the flat drawing look three-dimensional. → Hiệu ứng thị giác này làm cho bức vẽ phẳng trông có vẻ nổi ba chiều.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_71_7', 'en-b2-71', NULL, 'comprehensive_test', 'listening', 'electron', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nhân viên phục vụ; người phục vụ","điện tử","trung thành; trung thực","ám chỉ; ngụ ý"]'::jsonb, 1, 'electron (/ɪˈlektrɑːn/) → điện tử', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_71_8', 'en-b2-71', NULL, 'comprehensive_test', 'listening', 'We watched an animation showing the satellite''s orbit.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Việc sửa chữa nhà bếp đã bước vào giai đoạn cuối.","Việc chà xát hai bàn tay vào nhau tạo ra ma sát và làm ấm chúng lên.","Làm ơn vặn nhỏ âm lượng lại trong lúc em bé đang ngủ.","Chúng tôi đã xem một đoạn hoạt họa mô tả quỹ đạo chuyển động của vệ tinh."]'::jsonb, 3, 'We watched an animation showing the satellite''s orbit. → Chúng tôi đã xem một đoạn hoạt họa mô tả quỹ đạo chuyển động của vệ tinh.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_71_9', 'en-b2-71', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “continuing or happening repeatedly”?', '["finding","isolate","optical","constant"]'::jsonb, 3, 'constant (/ˈkɑːnstənt/) → liên tục; không ngừng', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
