INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_71_18', 'en-b2-71', NULL, 'comprehensive_test', 'reading', NULL, 'Researchers can trace changes in regional diets by examining food remains discovered at ancient settlements.', 'Dựa vào câu trên, từ “trace” có nghĩa phù hợp nhất là gì?', '["cuộn lại; uốn xoăn; làm cong","công tác quản lý; hoạt động hành chính","người tham gia; người tham dự","truy tìm; lần theo dấu vết; truy nguyên"]'::jsonb, 3, 'trace: truy tìm; lần theo dấu vết; truy nguyên; dấu vết; vết tích; lượng nhỏ; vẽ theo khung; can (tranh); tô theo đường nét. Dịch cả câu: Các nhà nghiên cứu có thể truy nguyên sự thay đổi trong chế độ ăn uống theo vùng bằng cách kiểm tra các tàn tích thức ăn được phát hiện tại các khu định cư cổ đại.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_71_19', 'en-b2-71', NULL, 'comprehensive_test', 'reading', NULL, 'Accurate measurements of longitude and latitude allow navigation systems to determine a vehicle''s position on Earth.', 'Dựa vào câu trên, từ “longitude” có nghĩa phù hợp nhất là gì?', '["giám sát; theo dõi","kinh độ","thuộc về đồ họa, hình ảnh hoặc thiết kế trực quan","cao thượng; cao cả"]'::jsonb, 1, 'longitude: kinh độ. Dịch cả câu: Các phép đo chính xác về kinh độ và vĩ độ cho phép hệ thống định vị xác định vị trí của phương tiện trên Trái Đất.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_71_20', 'en-b2-71', NULL, 'comprehensive_test', 'reading', NULL, 'The growing volume of household waste highlights the need for better recycling facilities in urban areas.', 'Dựa vào câu trên, từ “volume” có nghĩa phù hợp nhất là gì?', '["võ sĩ; chiến binh","một cách dễ dàng; không khó khăn","nhẹ nhàng; khẽ khàng","thể tích; khối lượng; tổng lượng"]'::jsonb, 3, 'volume: thể tích; khối lượng; tổng lượng; âm lượng; tập (sách); cuốn. Dịch cả câu: Khối lượng rác thải sinh hoạt ngày càng tăng làm nổi bật nhu cầu cần có các cơ sở tái chế tốt hơn ở các khu đô thị.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_71_21', 'en-b2-71', NULL, 'comprehensive_test', 'reading', NULL, 'Excess nitrogen from agricultural fertilisers can enter rivers, encouraging rapid algae growth and damaging aquatic ecosystems.', 'Dựa vào câu trên, từ “nitrogen” có nghĩa phù hợp nhất là gì?', '["riêng biệt; đặc biệt, chuyên dụng","không phù hợp; không thích hợp","nitơ; khí nitơ","máy bay chở khách cỡ lớn; máy bay phản lực thương mại"]'::jsonb, 2, 'nitrogen: nitơ; khí nitơ. Dịch cả câu: Lượng nitơ dư thừa từ phân bón nông nghiệp có thể ngấm vào sông ngòi, thúc đẩy tảo phát triển nhanh chóng và tàn phá các hệ sinh thái dưới nước.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_71_22', 'en-b2-71', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thép; ngành thép”', '["literally","hardware","alarming","steel"]'::jsonb, 3, 'thép; ngành thép → steel (/stiːl/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_71_23', 'en-b2-71', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “giai đoạn; thời kỳ”', '["inquiry","phase","best-seller","resign"]'::jsonb, 1, 'giai đoạn; thời kỳ → phase (/feɪz/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_71_24', 'en-b2-71', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “điều tra; tìm hiểu”', '["deed","thus","investigate","headquarters"]'::jsonb, 2, 'điều tra; tìm hiểu → investigate (/ɪnˈvestɪɡeɪt/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-72', 'en', 'Bài 72: Truyền thông & Tin tức (1) - CEFR B2', 'CEFR B2', 'B2 · Truyền thông', '17 từ vựng Tiếng Anh CEFR B2 chủ đề truyền thông & tin tức kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4072, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_release', 'en-b2-72', 'release', '/rɪˈliːs/', 'B2', 'thả; phóng thích; giải thoát; phát hành; công bố; đưa ra; sự thả; sự phóng thích; sự phát hành', 'v.', NULL, NULL, 'Release có thể chỉ hành động thả tự do, hoặc dùng để chỉ việc công bố báo cáo hay sản phẩm ra công chúng.', 'We released the butterfly outside after checking its wings.', NULL, 'Chúng tôi đã thả con bướm ra ngoài trời sau khi kiểm tra cánh của nó.', '{"wordId":"release","ukIpa":"/rɪˈliːs/","usIpa":"/rɪˈliːs/","cefr":"B2","topic":"media","senses":[{"pos":"v.","en":"To let someone or something go free or escape.","vi":"thả; phóng thích; giải thoát"},{"pos":"v.","en":"To make information or a product available to the public.","vi":"phát hành; công bố; đưa ra"},{"pos":"n.","en":"The act of freeing or publishing; something newly made available.","vi":"sự thả; sự phóng thích; sự phát hành"}],"examples":[{"en":"We released the butterfly outside after checking its wings.","vi":"Chúng tôi đã thả con bướm ra ngoài trời sau khi kiểm tra cánh của nó.","audioKind":"ex"},{"en":"Governments should release reliable environmental data so that citizens can evaluate the effectiveness of climate policies.","vi":"Chính phủ nên công bố các dữ liệu môi trường đáng tin cậy để người dân có thể đánh giá hiệu quả của các chính sách khí hậu.","audioKind":"ex2"}],"collocations":[{"en":"release a report","vi":"công bố một báo cáo"},{"en":"release a prisoner","vi":"thả một tù nhân"},{"en":"release gases","vi":"thải khí"},{"en":"a press release","vi":"bản thông cáo báo chí"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Release có thể chỉ hành động thả tự do, hoặc dùng để chỉ việc công bố báo cáo hay sản phẩm ra công chúng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_slogan', 'en-b2-72', 'slogan', '/ˈsloʊɡən/', 'B2', 'khẩu hiệu; biểu ngữ', 'n.', NULL, 'Đồng nghĩa: catchphrase', '"Slogan" dùng cho mục đích tuyên truyền, quảng bá; còn "motto" thường chỉ phương châm sống hoặc nguyên tắc hành động.', 'Our club chose a catchy slogan for its recycling campaign.', NULL, 'Câu lạc bộ của chúng tôi đã chọn một khẩu hiệu bắt tai cho chiến dịch tái chế.', '{"wordId":"slogan","ukIpa":"/ˈsləʊɡən/","usIpa":"/ˈsloʊɡən/","cefr":"B2","topic":"media","senses":[{"pos":"n.","en":"a short memorable phrase promoting an idea, group, or product","vi":"khẩu hiệu; biểu ngữ"}],"examples":[{"en":"Our club chose a catchy slogan for its recycling campaign.","vi":"Câu lạc bộ của chúng tôi đã chọn một khẩu hiệu bắt tai cho chiến dịch tái chế.","audioKind":"ex"},{"en":"An effective environmental slogan can attract attention, but lasting behavioural change usually requires practical support.","vi":"Một khẩu hiệu môi trường hiệu quả có thể thu hút sự chú ý, nhưng sự thay đổi hành vi lâu dài thường đòi hỏi sự hỗ trợ thực tế.","audioKind":"ex2"}],"collocations":[{"en":"catchy slogan","vi":"khẩu hiệu bắt tai"},{"en":"advertising slogan","vi":"khẩu hiệu quảng cáo"},{"en":"campaign slogan","vi":"khẩu hiệu chiến dịch"},{"en":"chant slogans","vi":"hô vang khẩu hiệu"}],"wordFamily":[],"synonyms":["catchphrase"],"antonyms":[],"tipVi":"\"Slogan\" dùng cho mục đích tuyên truyền, quảng bá; còn \"motto\" thường chỉ phương châm sống hoặc nguyên tắc hành động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_edition', 'en-b2-72', 'edition', '/ɪˈdɪʃən/', 'B2', 'phiên bản; bản in; số báo; số phát sóng', 'n.', 'edit (v.), editor (n.), editorial (adj.)', 'Đồng nghĩa: version', 'edition chỉ phiên bản hoặc số phát hành; một cuốn sách vật lý thường gọi là a copy.', 'I bought the latest edition of this gardening guide.', NULL, 'Tôi đã mua phiên bản mới nhất của cuốn cẩm nang làm vườn này.', '{"wordId":"edition","ukIpa":"/ɪˈdɪʃən/","usIpa":"/ɪˈdɪʃən/","cefr":"B2","topic":"media","senses":[{"pos":"n.","en":"A particular version of a book or other published work.","vi":"phiên bản; bản in"},{"pos":"n.","en":"One particular issue of a newspaper or broadcast programme.","vi":"số báo; số phát sóng"}],"examples":[{"en":"I bought the latest edition of this gardening guide.","vi":"Tôi đã mua phiên bản mới nhất của cuốn cẩm nang làm vườn này.","audioKind":"ex"},{"en":"The revised edition of the textbook includes recent research on renewable energy and sustainable urban development.","vi":"Phiên bản sửa đổi của cuốn sách giáo khoa bao gồm các nghiên cứu gần đây về năng lượng tái tạo và phát triển đô thị bền vững.","audioKind":"ex2"}],"collocations":[{"en":"first edition","vi":"bản in đầu tiên"},{"en":"revised edition","vi":"bản sửa đổi"},{"en":"limited edition","vi":"bản giới hạn"},{"en":"evening edition","vi":"số báo buổi tối"}],"wordFamily":["edit (v.)","editor (n.)","editorial (adj.)"],"synonyms":["version"],"antonyms":[],"tipVi":"edition chỉ phiên bản hoặc số phát hành; một cuốn sách vật lý thường gọi là a copy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inaccurate', 'en-b2-72', 'inaccurate', '/ɪnˈækjərət/', 'B2', 'không chính xác; sai sót', 'adj.', 'accurate (adj.), accuracy (n.), inaccuracy (n.), inaccurately (adv.)', 'Đồng nghĩa: incorrect, erroneous · Trái nghĩa: accurate, correct', 'Chỉ thông tin hoặc số đo không chính xác; không nhất thiết ngụ ý cố ý làm giả.', 'The map was inaccurate, so we missed the turning.', NULL, 'Bản đồ không chính xác nên chúng tôi đã đi nhầm ngã rẽ.', '{"wordId":"inaccurate","ukIpa":"/ɪnˈækjərət/","usIpa":"/ɪnˈækjərət/","cefr":"B2","topic":"media","senses":[{"pos":"adj.","en":"not completely correct or exact","vi":"không chính xác; sai sót"}],"examples":[{"en":"The map was inaccurate, so we missed the turning.","vi":"Bản đồ không chính xác nên chúng tôi đã đi nhầm ngã rẽ.","audioKind":"ex"},{"en":"Inaccurate information online can undermine public trust and lead people to make poorly informed decisions.","vi":"Thông tin không chính xác trên mạng có thể làm xói mòn lòng tin của công chúng và khiến mọi người đưa ra những quyết định thiếu sáng suốt.","audioKind":"ex2"}],"collocations":[{"en":"inaccurate information","vi":"thông tin không chính xác"},{"en":"inaccurate estimate","vi":"ước tính không chính xác"},{"en":"factually inaccurate","vi":"sai lệch về mặt thực tế"}],"wordFamily":["accurate (adj.)","accuracy (n.)","inaccuracy (n.)","inaccurately (adv.)"],"synonyms":["incorrect","erroneous"],"antonyms":["accurate","correct"],"tipVi":"Chỉ thông tin hoặc số đo không chính xác; không nhất thiết ngụ ý cố ý làm giả.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_publication', 'en-b2-72', 'publication', '/ˌpʌblɪˈkeɪʃən/', 'B2', 'sự xuất bản; sự công bố; ấn phẩm; sách báo', 'n.', 'publish (v.), publisher (n.), published (adj.)', NULL, 'Chỉ hành động xuất bản là danh từ không đếm được; chỉ ấn phẩm cụ thể là đếm được.', 'Her first cookbook is ready for publication next month.', NULL, 'Cuốn sách dạy nấu ăn đầu tiên của cô ấy đã sẵn sàng để phát hành vào tháng tới.', '{"wordId":"publication","ukIpa":"/ˌpʌblɪˈkeɪʃən/","usIpa":"/ˌpʌblɪˈkeɪʃən/","cefr":"B2","topic":"media","senses":[{"pos":"n.","en":"The process of making written material available to the public.","vi":"sự xuất bản; sự công bố"},{"pos":"n.","en":"A book, magazine, or other work made available to readers.","vi":"ấn phẩm; sách báo"}],"examples":[{"en":"Her first cookbook is ready for publication next month.","vi":"Cuốn sách dạy nấu ăn đầu tiên của cô ấy đã sẵn sàng để phát hành vào tháng tới.","audioKind":"ex"},{"en":"The publication of research findings allows other scientists to evaluate the evidence and develop new theories.","vi":"Việc công bố các kết quả nghiên cứu cho phép các nhà khoa học khác đánh giá các bằng chứng và phát triển các lý thuyết mới.","audioKind":"ex2"}],"collocations":[{"en":"publication date","vi":"ngày xuất bản"},{"en":"publication of findings","vi":"sự công bố kết quả"},{"en":"academic publication","vi":"ấn phẩm học thuật"}],"wordFamily":["publish (v.)","publisher (n.)","published (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ hành động xuất bản là danh từ không đếm được; chỉ ấn phẩm cụ thể là đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_so-called', 'en-b2-72', 'so-called', '/ˌsoʊˈkɔːld/', 'B2', 'được gọi là (thường mang ý nghi ngờ, không chắc chắn); cái gọi là; được biết đến với một tên gọi cụ thể', 'adj.', NULL, 'Đồng nghĩa: supposed, alleged', 'Đặt trước danh từ, thường mang ý hoài nghi, nhưng cũng có thể dùng một cách trung lập để giới thiệu tên gọi.', 'This so-called waterproof jacket let the rain straight through.', NULL, 'Chiếc áo khoác cái gọi là chống thấm nước này đã để nước mưa thấm thẳng qua.', '{"wordId":"so-called","ukIpa":"/ˌsəʊˈkɔːld/","usIpa":"/ˌsoʊˈkɔːld/","cefr":"B2","topic":"media","senses":[{"pos":"adj.","en":"Described a certain way, though that description may be doubtful.","vi":"được gọi là (thường mang ý nghi ngờ, không chắc chắn); cái gọi là"},{"pos":"adj.","en":"Known by a particular name or term.","vi":"được biết đến với một tên gọi cụ thể"}],"examples":[{"en":"This so-called waterproof jacket let the rain straight through.","vi":"Chiếc áo khoác cái gọi là chống thấm nước này đã để nước mưa thấm thẳng qua.","audioKind":"ex"},{"en":"Consumers should examine whether so-called green products actually reduce environmental harm throughout their life cycle.","vi":"Người tiêu dùng nên xem xét liệu những cái gọi là sản phẩm xanh có thực sự làm giảm tác hại môi trường trong toàn bộ vòng đời của chúng hay không.","audioKind":"ex2"}],"collocations":[{"en":"so-called experts","vi":"những kẻ gọi là chuyên gia"},{"en":"so-called benefits","vi":"cái gọi là lợi ích"},{"en":"so-called green products","vi":"những sản phẩm được gọi là thân thiện với môi trường"}],"wordFamily":[],"synonyms":["supposed","alleged"],"antonyms":[],"tipVi":"Đặt trước danh từ, thường mang ý hoài nghi, nhưng cũng có thể dùng một cách trung lập để giới thiệu tên gọi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_banner', 'en-b2-72', 'banner', '/ˈbænər/', 'B2', 'băng rôn; biểu ngữ; cờ; biểu ngữ quảng cáo; quảng cáo ngang trên trang web', 'n.', NULL, NULL, 'Quảng cáo dạng băng rôn trên trang web thường được gọi là banner ad.', 'We hung a colourful banner above the garden gate.', NULL, 'Chúng tôi đã treo một chiếc băng rôn đầy màu sắc phía trên cổng vườn.', '{"wordId":"banner","ukIpa":"/ˈbænə/","usIpa":"/ˈbænər/","cefr":"B2","topic":"media","senses":[{"pos":"n.","en":"a long piece of cloth displaying a message or design","vi":"băng rôn; biểu ngữ; cờ"},{"pos":"n.","en":"a wide advertisement displayed across part of a webpage","vi":"biểu ngữ quảng cáo; quảng cáo ngang trên trang web"}],"examples":[{"en":"We hung a colourful banner above the garden gate.","vi":"Chúng tôi đã treo một chiếc băng rôn đầy màu sắc phía trên cổng vườn.","audioKind":"ex"},{"en":"Many news websites rely on banner advertising to provide free access to their articles.","vi":"Nhiều trang web tin tức dựa vào quảng cáo biểu ngữ để cung cấp quyền truy cập miễn phí vào các bài viết của họ.","audioKind":"ex2"}],"collocations":[{"en":"hang a banner","vi":"treo băng rôn"},{"en":"carry a banner","vi":"giương biểu ngữ"},{"en":"banner advertising","vi":"quảng cáo biểu ngữ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Quảng cáo dạng băng rôn trên trang web thường được gọi là banner ad.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rating', 'en-b2-72', 'rating', '/ˈreɪtɪŋ/', 'B2', 'mức đánh giá; điểm số; xếp hạng; tỷ suất người xem; lượng thính giả; mức định mức; giá trị định mức', 'n.', 'rate (v.), rated (adj.)', NULL, 'Khi chỉ lượng người xem truyền hình, từ này thường ở dạng số nhiều ratings; ngoài ra nó cũng có thể đóng vai trò là dạng phân từ hiện tại của động từ rate.', 'The hotel received a high rating for its friendly service.', NULL, 'Khách sạn nhận được mức đánh giá cao nhờ dịch vụ thân thiện.', '{"wordId":"rating","ukIpa":"/ˈreɪtɪŋ/","usIpa":"/ˈreɪtɪŋ/","cefr":"B2","topic":"media","senses":[{"pos":"n.","en":"a judgement of quality, performance, or suitability on a scale","vi":"mức đánh giá; điểm số; xếp hạng"},{"pos":"n.","en":"a measure of audience size for a broadcast programme","vi":"tỷ suất người xem; lượng thính giả"},{"pos":"n.","en":"the maximum power or load equipment is designed to handle","vi":"mức định mức; giá trị định mức"}],"examples":[{"en":"The hotel received a high rating for its friendly service.","vi":"Khách sạn nhận được mức đánh giá cao nhờ dịch vụ thân thiện.","audioKind":"ex"},{"en":"A clear energy rating helps consumers compare household appliances and choose models with lower running costs.","vi":"Một nhãn năng lượng rõ ràng giúp người tiêu dùng so sánh các thiết bị gia dụng và chọn các mẫu có chi phí vận hành thấp hơn.","audioKind":"ex2"}],"collocations":[{"en":"a high rating","vi":"đánh giá cao"},{"en":"an energy rating","vi":"mức năng lượng"},{"en":"audience ratings","vi":"tỷ suất người xem"},{"en":"a power rating","vi":"công suất định mức"}],"wordFamily":["rate (v.)","rated (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ lượng người xem truyền hình, từ này thường ở dạng số nhiều ratings; ngoài ra nó cũng có thể đóng vai trò là dạng phân từ hiện tại của động từ rate.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_viewing', 'en-b2-72', 'viewing', '/ˈvjuːɪŋ/', 'B2', 'sự xem; sự theo dõi (truyền hình, phim ảnh); sự đi xem; sự tham quan (nhà cửa, bất động sản); cách nhìn nhận; cách xem xét', 'n.', 'view (v.), viewer (n.)', NULL, 'Danh từ có thể chỉ hoạt động xem; a viewing thường chỉ một lần đi xem nhà.', 'We saved the documentary for our evening viewing.', NULL, 'Chúng tôi đã để dành bộ phim tài liệu đó để xem vào buổi tối.', '{"wordId":"viewing","ukIpa":"/ˈvjuːɪŋ/","usIpa":"/ˈvjuːɪŋ/","cefr":"B2","topic":"media","senses":[{"pos":"n.","en":"The activity of watching television, films, or other visual material.","vi":"sự xem; sự theo dõi (truyền hình, phim ảnh)"},{"pos":"n.","en":"An arranged opportunity to inspect a property or see something.","vi":"sự đi xem; sự tham quan (nhà cửa, bất động sản)"},{"pos":"v.","en":"Looking at something or considering it in a particular way.","vi":"cách nhìn nhận; cách xem xét"}],"examples":[{"en":"We saved the documentary for our evening viewing.","vi":"Chúng tôi đã để dành bộ phim tài liệu đó để xem vào buổi tối.","audioKind":"ex"},{"en":"Excessive television viewing may reduce the time children spend exercising and interacting with their families.","vi":"Việc xem TV quá mức có thể làm giảm thời gian trẻ em dành cho việc tập thể dục và tương tác với gia đình.","audioKind":"ex2"}],"collocations":[{"en":"television viewing","vi":"hoạt động xem truyền hình"},{"en":"a private viewing","vi":"một buổi tham quan riêng"},{"en":"arrange a viewing","vi":"sắp xếp một buổi đi xem nhà"}],"wordFamily":["view (v.)","viewer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ có thể chỉ hoạt động xem; a viewing thường chỉ một lần đi xem nhà.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fame', 'en-b2-72', 'fame', '/feɪm/', 'B2', 'tiếng tăm; danh tiếng; sự nổi tiếng', 'n.', 'famous (adj.), famously (adv.), famed (adj.)', 'Đồng nghĩa: renown, celebrity · Trái nghĩa: obscurity', 'Danh từ fame thường không đếm được; tính từ famous hay đi với giới từ for.', 'Despite her fame, the singer still shops locally.', NULL, 'Mặc dù rất nổi tiếng, nữ ca sĩ này vẫn đi mua sắm ở các cửa hàng gần nhà.', '{"wordId":"fame","ukIpa":"/feɪm/","usIpa":"/feɪm/","cefr":"B2","topic":"media","senses":[{"pos":"n.","en":"The state of being known by many people.","vi":"tiếng tăm; danh tiếng; sự nổi tiếng"}],"examples":[{"en":"Despite her fame, the singer still shops locally.","vi":"Mặc dù rất nổi tiếng, nữ ca sĩ này vẫn đi mua sắm ở các cửa hàng gần nhà.","audioKind":"ex"},{"en":"Although online platforms can bring sudden fame, public attention does not necessarily lead to a sustainable career.","vi":"Mặc dù các nền tảng trực tuyến có thể mang lại sự nổi tiếng bất ngờ, sự chú ý từ công chúng không đảm bảo sẽ tạo ra một sự nghiệp bền vững.","audioKind":"ex2"}],"collocations":[{"en":"achieve fame","vi":"đạt được danh tiếng"},{"en":"rise to fame","vi":"nổi đình nổi đám; vươn lên thành sao"},{"en":"international fame","vi":"danh tiếng quốc tế"},{"en":"lasting fame","vi":"tiếng tăm muôn thuở; tiếng thơm lâu dài"}],"wordFamily":["famous (adj.)","famously (adv.)","famed (adj.)"],"synonyms":["renown","celebrity"],"antonyms":["obscurity"],"tipVi":"Danh từ fame thường không đếm được; tính từ famous hay đi với giới từ for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_subscribe', 'en-b2-72', 'subscribe', '/səbˈskraɪb/', 'B2', 'đặt mua dài hạn; đăng ký sử dụng dịch vụ; tán thành; đồng tình với quan điểm', 'v.', 'subscription (n.), subscriber (n.), unsubscribe (v.)', 'Trái nghĩa: unsubscribe', 'Cả việc đặt mua và tán thành đều dùng cấu trúc subscribe to, trong đó to là giới từ.', 'We subscribe to a magazine full of easy recipes.', NULL, 'Chúng tôi đặt mua một tạp chí đầy các công thức nấu ăn đơn giản.', '{"wordId":"subscribe","ukIpa":"/səbˈskraɪb/","usIpa":"/səbˈskraɪb/","cefr":"B2","topic":"media","senses":[{"pos":"v.","en":"To arrange regular access to a publication or service.","vi":"đặt mua dài hạn; đăng ký sử dụng dịch vụ"},{"pos":"v.","en":"To agree with a particular belief or view.","vi":"tán thành; đồng tình với quan điểm"}],"examples":[{"en":"We subscribe to a magazine full of easy recipes.","vi":"Chúng tôi đặt mua một tạp chí đầy các công thức nấu ăn đơn giản.","audioKind":"ex"},{"en":"Many educators subscribe to the view that practical experience should complement theoretical learning in higher education.","vi":"Nhiều nhà giáo dục tán thành quan điểm rằng kinh nghiệm thực tế nên bổ sung cho việc học lý thuyết trong giáo dục bậc cao.","audioKind":"ex2"}],"collocations":[{"en":"subscribe to a magazine","vi":"đặt mua tạp chí"},{"en":"subscribe to a channel","vi":"đăng ký kênh"},{"en":"subscribe to the view that","vi":"tán thành quan điểm rằng"}],"wordFamily":["subscription (n.)","subscriber (n.)","unsubscribe (v.)"],"synonyms":[],"antonyms":["unsubscribe"],"tipVi":"Cả việc đặt mua và tán thành đều dùng cấu trúc subscribe to, trong đó to là giới từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_publicity', 'en-b2-72', 'publicity', '/pʌbˈlɪsəti/', 'B2', 'sự chú ý từ dư luận; sự đưa tin của truyền thông; hoạt động quảng bá; sự tuyên truyền', 'n.', 'publicise (v.), publicist (n.), public (adj.), publicly (adv.)', NULL, 'Đây là danh từ không đếm được; khác với advertising, từ này không nhất thiết chỉ quảng cáo trả phí.', 'The new bakery received plenty of publicity after opening.', NULL, 'Tiệm bánh mới đã nhận được rất nhiều sự chú ý từ truyền thông sau khi khai trương.', '{"wordId":"publicity","ukIpa":"/pʌbˈlɪsəti/","usIpa":"/pʌbˈlɪsəti/","cefr":"B2","topic":"media","senses":[{"pos":"n.","en":"Attention given to someone or something by the media.","vi":"sự chú ý từ dư luận; sự đưa tin của truyền thông"},{"pos":"n.","en":"Activities intended to attract public attention to something.","vi":"hoạt động quảng bá; sự tuyên truyền"}],"examples":[{"en":"The new bakery received plenty of publicity after opening.","vi":"Tiệm bánh mới đã nhận được rất nhiều sự chú ý từ truyền thông sau khi khai trương.","audioKind":"ex"},{"en":"Positive publicity can attract visitors to lesser-known destinations, creating employment opportunities for local residents.","vi":"Sự quảng bá tích cực có thể thu hút du khách đến những điểm đến ít người biết tới, tạo ra cơ hội việc làm cho người dân địa phương.","audioKind":"ex2"}],"collocations":[{"en":"positive publicity","vi":"sự đưa tin tích cực"},{"en":"adverse publicity","vi":"thông tin bất lợi"},{"en":"generate publicity","vi":"tạo sự chú ý của công chúng"},{"en":"publicity campaign","vi":"chiến dịch quảng bá"}],"wordFamily":["publicise (v.)","publicist (n.)","public (adj.)","publicly (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Đây là danh từ không đếm được; khác với advertising, từ này không nhất thiết chỉ quảng cáo trả phí.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_copyright', 'en-b2-72', 'copyright', '/ˈkɑːpiraɪt/', 'B2', 'bản quyền; quyền tác giả; đăng ký bản quyền', 'n.', NULL, NULL, 'Bản quyền là copyright; quyền sáng chế là patent, tránh dùng nhầm lẫn.', 'Check the copyright before using that photo on your website.', NULL, 'Hãy kiểm tra bản quyền trước khi sử dụng bức ảnh đó trên trang web của bạn.', '{"wordId":"copyright","ukIpa":"/ˈkɒpiraɪt/","usIpa":"/ˈkɑːpiraɪt/","cefr":"B2","topic":"media","senses":[{"pos":"n.","en":"the legal right to control copying and use of creative work","vi":"bản quyền; quyền tác giả"},{"pos":"v.","en":"to secure copyright protection for a creative work","vi":"đăng ký bản quyền"}],"examples":[{"en":"Check the copyright before using that photo on your website.","vi":"Hãy kiểm tra bản quyền trước khi sử dụng bức ảnh đó trên trang web của bạn.","audioKind":"ex"},{"en":"Copyright laws aim to protect creators while allowing certain uses of their work for education and research.","vi":"Luật bản quyền nhằm bảo vệ những người sáng tạo đồng thời cho phép sử dụng tác phẩm của họ ở một mức độ nhất định cho mục đích giáo dục và nghiên cứu.","audioKind":"ex2"}],"collocations":[{"en":"copyright protection","vi":"bảo hộ bản quyền"},{"en":"copyright holder","vi":"chủ sở hữu bản quyền"},{"en":"copyright infringement","vi":"vi phạm bản quyền"},{"en":"under copyright","vi":"đang được bảo vệ bản quyền"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Bản quyền là copyright; quyền sáng chế là patent, tránh dùng nhầm lẫn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_logo', 'en-b2-72', 'logo', '/ˈloʊɡoʊ/', 'B2', 'biểu trưng; logo; nhãn hiệu', 'n.', NULL, 'Đồng nghĩa: emblem', 'Logo chỉ biểu tượng trực quan; trong khi slogan chỉ khẩu hiệu quảng cáo.', 'The bakery uses a wheat stalk as its logo.', NULL, 'Tiệm bánh sử dụng bông lúa mì làm biểu trưng của mình.', '{"wordId":"logo","ukIpa":"/ˈləʊɡəʊ/","usIpa":"/ˈloʊɡoʊ/","cefr":"B2","topic":"media","senses":[{"pos":"n.","en":"a design or symbol that represents an organisation or product","vi":"biểu trưng; logo; nhãn hiệu"}],"examples":[{"en":"The bakery uses a wheat stalk as its logo.","vi":"Tiệm bánh sử dụng bông lúa mì làm biểu trưng của mình.","audioKind":"ex"},{"en":"A distinctive logo helps consumers recognise a company, but product quality is essential for building lasting trust.","vi":"Một logo dễ nhận biết giúp người tiêu dùng nhận diện công ty, nhưng chất lượng sản phẩm mới là yếu tố cốt lõi để xây dựng niềm tin lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"company logo","vi":"logo công ty"},{"en":"design a logo","vi":"thiết kế logo"},{"en":"distinctive logo","vi":"logo độc đáo"}],"wordFamily":[],"synonyms":["emblem"],"antonyms":[],"tipVi":"Logo chỉ biểu tượng trực quan; trong khi slogan chỉ khẩu hiệu quảng cáo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mislead', 'en-b2-72', 'mislead', '/ˌmɪsˈliːd/', 'B2', 'làm cho sai lạc; đánh lừa; dẫn dắt sai đường', 'v.', 'misleading (adj.), misleadingly (adv.)', 'Đồng nghĩa: deceive', 'Dạng quá khứ và phân từ hai đều là "misled"; thường đi với cấu trúc "into doing".', 'The photograph misled me about the apartment''s actual size.', NULL, 'Bức ảnh đó đã làm tôi đánh giá sai về diện tích thực tế của căn hộ.', '{"wordId":"mislead","ukIpa":"/ˌmɪsˈliːd/","usIpa":"/ˌmɪsˈliːd/","cefr":"B2","topic":"media","senses":[{"pos":"v.","en":"to cause someone to believe something incorrect","vi":"làm cho sai lạc; đánh lừa; dẫn dắt sai đường"}],"examples":[{"en":"The photograph misled me about the apartment''s actual size.","vi":"Bức ảnh đó đã làm tôi đánh giá sai về diện tích thực tế của căn hộ.","audioKind":"ex"},{"en":"Advertisements can mislead consumers into believing that expensive products always offer better quality than cheaper alternatives.","vi":"Quảng cáo có thể đánh lừa người tiêu dùng khiến họ tin rằng các sản phẩm đắt tiền luôn có chất lượng tốt hơn các sản phẩm giá rẻ thay thế.","audioKind":"ex2"}],"collocations":[{"en":"mislead consumers","vi":"đánh lừa người tiêu dùng"},{"en":"mislead someone into believing","vi":"lừa dối ai đó tin rằng"},{"en":"deliberately mislead","vi":"cố tình đánh lừa"}],"wordFamily":["misleading (adj.)","misleadingly (adv.)"],"synonyms":["deceive"],"antonyms":[],"tipVi":"Dạng quá khứ và phân từ hai đều là \"misled\"; thường đi với cấu trúc \"into doing\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_factual', 'en-b2-72', 'factual', '/ˈfæktʃuəl/', 'B2', 'dựa trên sự thật; thực tế', 'adj.', 'fact (n.), factually (adv.)', 'Trái nghĩa: fictional', 'Từ này nhấn mạnh việc dựa trên sự thật, không giống với "actual" vốn chỉ sự việc có thật/hiện thực.', 'Her account of the accident was brief and factual.', NULL, 'Lời kể của cô ấy về vụ tai nạn ngắn gọn và đúng sự thật.', '{"wordId":"factual","ukIpa":"/ˈfæktʃuəl/","usIpa":"/ˈfæktʃuəl/","cefr":"B2","topic":"media","senses":[{"pos":"adj.","en":"Based on facts rather than opinions or invented details.","vi":"dựa trên sự thật; thực tế"}],"examples":[{"en":"Her account of the accident was brief and factual.","vi":"Lời kể của cô ấy về vụ tai nạn ngắn gọn và đúng sự thật.","audioKind":"ex"},{"en":"Students should learn to distinguish factual information from personal opinion when evaluating sources for academic assignments.","vi":"Học sinh nên học cách phân biệt thông tin thực tế với quan điểm cá nhân khi đánh giá các nguồn tài liệu cho bài tập học thuật.","audioKind":"ex2"}],"collocations":[{"en":"factual information","vi":"thông tin thực tế"},{"en":"factual accuracy","vi":"tính chính xác về mặt sự thật"},{"en":"a factual error","vi":"lỗi sai sự thật"},{"en":"a factual account","vi":"bản tường thuật thực tế"}],"wordFamily":["fact (n.)","factually (adv.)"],"synonyms":[],"antonyms":["fictional"],"tipVi":"Từ này nhấn mạnh việc dựa trên sự thật, không giống với \"actual\" vốn chỉ sự việc có thật/hiện thực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exaggerated', 'en-b2-72', 'exaggerated', '/ɪɡˈzædʒəreɪtɪd/', 'B2', 'bị phóng đại; nói quá; cường điệu; được làm cho quá mức; mang tính khoa trương', 'adj.', 'exaggerate (v.), exaggeration (n.)', 'Đồng nghĩa: overstated, inflated · Trái nghĩa: understated', 'Dùng để miêu tả phát ngôn hoặc hành động bị thổi phồng; không nhầm với từ "chính xác".', 'His exaggerated story made the small spider sound enormous.', NULL, 'Câu chuyện phóng đại của anh ấy khiến con nhện nhỏ bé trông to lớn đến đáng sợ.', '{"wordId":"exaggerated","ukIpa":"/ɪɡˈzædʒəreɪtɪd/","usIpa":"/ɪɡˈzædʒəreɪtɪd/","cefr":"B2","topic":"media","senses":[{"pos":"adj.","en":"Presented as greater, worse, or more important than it really is","vi":"bị phóng đại; nói quá; cường điệu"},{"pos":"adj.","en":"Made unusually large or noticeable for emphasis or effect","vi":"được làm cho quá mức; mang tính khoa trương"}],"examples":[{"en":"His exaggerated story made the small spider sound enormous.","vi":"Câu chuyện phóng đại của anh ấy khiến con nhện nhỏ bé trông to lớn đến đáng sợ.","audioKind":"ex"},{"en":"Exaggerated claims in advertising can mislead consumers and reduce public trust in businesses over time.","vi":"Những lời quảng cáo phóng đại có thể đánh lừa người tiêu dùng và làm xói mòn lòng tin của công chúng đối với các doanh nghiệp theo thời gian.","audioKind":"ex2"}],"collocations":[{"en":"exaggerated claims","vi":"lời tuyên bố phóng đại"},{"en":"greatly exaggerated","vi":"được phóng đại rất nhiều"},{"en":"exaggerated gestures","vi":"cử chỉ khoa trương"}],"wordFamily":["exaggerate (v.)","exaggeration (n.)"],"synonyms":["overstated","inflated"],"antonyms":["understated"],"tipVi":"Dùng để miêu tả phát ngôn hoặc hành động bị thổi phồng; không nhầm với từ \"chính xác\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_72_1', 'en-b2-72', 'Cách dùng “rating” (n.) — mức đánh giá; điểm số; xếp hạng', 'a high rating  ·  an energy rating  ·  audience ratings', 'Khi chỉ lượng người xem truyền hình, từ này thường ở dạng số nhiều ratings; ngoài ra nó cũng có thể đóng vai trò là dạng phân từ hiện tại của động từ rate.', 'Họ từ (Word Family): rate (v.), rated (adj.)', '[{"hanzi":"The hotel received a high rating for its friendly service.","pinyin":"","meaning":"Khách sạn nhận được mức đánh giá cao nhờ dịch vụ thân thiện."},{"hanzi":"A clear energy rating helps consumers compare household appliances and choose models with lower running costs.","pinyin":"","meaning":"Một nhãn năng lượng rõ ràng giúp người tiêu dùng so sánh các thiết bị gia dụng và chọn các mẫu có chi phí vận hành thấp hơn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_72_2', 'en-b2-72', 'Cách dùng “slogan” (n.) — khẩu hiệu; biểu ngữ', 'catchy slogan  ·  advertising slogan  ·  campaign slogan', '"Slogan" dùng cho mục đích tuyên truyền, quảng bá; còn "motto" thường chỉ phương châm sống hoặc nguyên tắc hành động.', 'Đồng nghĩa: catchphrase', '[{"hanzi":"Our club chose a catchy slogan for its recycling campaign.","pinyin":"","meaning":"Câu lạc bộ của chúng tôi đã chọn một khẩu hiệu bắt tai cho chiến dịch tái chế."},{"hanzi":"An effective environmental slogan can attract attention, but lasting behavioural change usually requires practical support.","pinyin":"","meaning":"Một khẩu hiệu môi trường hiệu quả có thể thu hút sự chú ý, nhưng sự thay đổi hành vi lâu dài thường đòi hỏi sự hỗ trợ thực tế."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_72_3', 'en-b2-72', 'Cách dùng “so-called” (adj.) — được gọi là (thường mang ý nghi ngờ, không chắc chắn); cái gọi là', 'so-called experts  ·  so-called benefits  ·  so-called green products', 'Đặt trước danh từ, thường mang ý hoài nghi, nhưng cũng có thể dùng một cách trung lập để giới thiệu tên gọi.', 'Đồng nghĩa: supposed, alleged', '[{"hanzi":"This so-called waterproof jacket let the rain straight through.","pinyin":"","meaning":"Chiếc áo khoác cái gọi là chống thấm nước này đã để nước mưa thấm thẳng qua."},{"hanzi":"Consumers should examine whether so-called green products actually reduce environmental harm throughout their life cycle.","pinyin":"","meaning":"Người tiêu dùng nên xem xét liệu những cái gọi là sản phẩm xanh có thực sự làm giảm tác hại môi trường trong toàn bộ vòng đời của chúng hay không."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_72_4', 'en-b2-72', 'Cách dùng “release” (v.) — thả; phóng thích; giải thoát', 'release a report  ·  release a prisoner  ·  release gases', 'Release có thể chỉ hành động thả tự do, hoặc dùng để chỉ việc công bố báo cáo hay sản phẩm ra công chúng.', NULL, '[{"hanzi":"We released the butterfly outside after checking its wings.","pinyin":"","meaning":"Chúng tôi đã thả con bướm ra ngoài trời sau khi kiểm tra cánh của nó."},{"hanzi":"Governments should release reliable environmental data so that citizens can evaluate the effectiveness of climate policies.","pinyin":"","meaning":"Chính phủ nên công bố các dữ liệu môi trường đáng tin cậy để người dân có thể đánh giá hiệu quả của các chính sách khí hậu."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_72_1', 'en-b2-72', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
