INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_72_1_2', 'ten_b2_72_1', 'slogan', 'Our club chose a catchy slogan for its recycling campaign.', 'Our club chose a catchy slogan for its recycling campaign.', '/ˈsloʊɡən/', 'Câu lạc bộ của chúng tôi đã chọn một khẩu hiệu bắt tai cho chiến dịch tái chế.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
