INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_72_1_4', 'ten_b2_72_1', 'inaccurate', 'The map was inaccurate, so we missed the turning.', 'The map was inaccurate, so we missed the turning.', '/ɪnˈækjərət/', 'Bản đồ không chính xác nên chúng tôi đã đi nhầm ngã rẽ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_72_1_5', 'ten_b2_72_1', 'publication', 'Her first cookbook is ready for publication next month.', 'Her first cookbook is ready for publication next month.', '/ˌpʌblɪˈkeɪʃən/', 'Cuốn sách dạy nấu ăn đầu tiên của cô ấy đã sẵn sàng để phát hành vào tháng tới.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
