INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_72_1_7', 'ten_b2_72_1', 'banner', 'We hung a colourful banner above the garden gate.', 'We hung a colourful banner above the garden gate.', '/ˈbænər/', 'Chúng tôi đã treo một chiếc băng rôn đầy màu sắc phía trên cổng vườn.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_72_1_8', 'ten_b2_72_1', 'rating', 'The hotel received a high rating for its friendly service.', 'The hotel received a high rating for its friendly service.', '/ˈreɪtɪŋ/', 'Khách sạn nhận được mức đánh giá cao nhờ dịch vụ thân thiện.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_72_1_1', 'en-b2-72', 'ten_b2_72_1', 'listening', 'listening', 'We released the butterfly outside after checking its wings.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tiệm bánh sử dụng bông lúa mì làm biểu trưng của mình.","Bản đồ không chính xác nên chúng tôi đã đi nhầm ngã rẽ.","Chúng tôi đã thả con bướm ra ngoài trời sau khi kiểm tra cánh của nó.","Chúng tôi đã để dành bộ phim tài liệu đó để xem vào buổi tối."]'::jsonb, 2, 'We released the butterfly outside after checking its wings. → Chúng tôi đã thả con bướm ra ngoài trời sau khi kiểm tra cánh của nó.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_72_1_2', 'en-b2-72', 'ten_b2_72_1', 'listening', 'listening', 'Our club chose a catchy slogan for its recycling campaign.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã treo một chiếc băng rôn đầy màu sắc phía trên cổng vườn.","Hãy kiểm tra bản quyền trước khi sử dụng bức ảnh đó trên trang web của bạn.","Câu lạc bộ của chúng tôi đã chọn một khẩu hiệu bắt tai cho chiến dịch tái chế.","Chiếc áo khoác cái gọi là chống thấm nước này đã để nước mưa thấm thẳng qua."]'::jsonb, 2, 'Our club chose a catchy slogan for its recycling campaign. → Câu lạc bộ của chúng tôi đã chọn một khẩu hiệu bắt tai cho chiến dịch tái chế.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_72_1_3', 'en-b2-72', 'ten_b2_72_1', 'listening', 'listening', 'I bought the latest edition of this gardening guide.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi đã mua phiên bản mới nhất của cuốn cẩm nang làm vườn này.","Lời kể của cô ấy về vụ tai nạn ngắn gọn và đúng sự thật.","Tiệm bánh mới đã nhận được rất nhiều sự chú ý từ truyền thông sau khi khai trương.","Cuốn sách dạy nấu ăn đầu tiên của cô ấy đã sẵn sàng để phát hành vào tháng tới."]'::jsonb, 0, 'I bought the latest edition of this gardening guide. → Tôi đã mua phiên bản mới nhất của cuốn cẩm nang làm vườn này.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_72_2', 'en-b2-72', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_72_2_1', 'ten_b2_72_2', 'release', 'Governments should release reliable environmental data so that citizens can evaluate the effectiveness of climate policies.', 'Governments should release reliable environmental data so that citizens can evaluate the effectiveness of climate policies.', '/rɪˈliːs/', 'Chính phủ nên công bố các dữ liệu môi trường đáng tin cậy để người dân có thể đánh giá hiệu quả của các chính sách khí hậu.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_72_2_2', 'ten_b2_72_2', 'slogan', 'An effective environmental slogan can attract attention, but lasting behavioural change usually requires practical support.', 'An effective environmental slogan can attract attention, but lasting behavioural change usually requires practical support.', '/ˈsloʊɡən/', 'Một khẩu hiệu môi trường hiệu quả có thể thu hút sự chú ý, nhưng sự thay đổi hành vi lâu dài thường đòi hỏi sự hỗ trợ thực tế.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_72_2_3', 'ten_b2_72_2', 'edition', 'The revised edition of the textbook includes recent research on renewable energy and sustainable urban development.', 'The revised edition of the textbook includes recent research on renewable energy and sustainable urban development.', '/ɪˈdɪʃən/', 'Phiên bản sửa đổi của cuốn sách giáo khoa bao gồm các nghiên cứu gần đây về năng lượng tái tạo và phát triển đô thị bền vững.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_72_2_4', 'ten_b2_72_2', 'inaccurate', 'Inaccurate information online can undermine public trust and lead people to make poorly informed decisions.', 'Inaccurate information online can undermine public trust and lead people to make poorly informed decisions.', '/ɪnˈækjərət/', 'Thông tin không chính xác trên mạng có thể làm xói mòn lòng tin của công chúng và khiến mọi người đưa ra những quyết định thiếu sáng suốt.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_72_2_5', 'ten_b2_72_2', 'publication', 'The publication of research findings allows other scientists to evaluate the evidence and develop new theories.', 'The publication of research findings allows other scientists to evaluate the evidence and develop new theories.', '/ˌpʌblɪˈkeɪʃən/', 'Việc công bố các kết quả nghiên cứu cho phép các nhà khoa học khác đánh giá các bằng chứng và phát triển các lý thuyết mới.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_72_2_6', 'ten_b2_72_2', 'so-called', 'Consumers should examine whether so-called green products actually reduce environmental harm throughout their life cycle.', 'Consumers should examine whether so-called green products actually reduce environmental harm throughout their life cycle.', '/ˌsoʊˈkɔːld/', 'Người tiêu dùng nên xem xét liệu những cái gọi là sản phẩm xanh có thực sự làm giảm tác hại môi trường trong toàn bộ vòng đời của chúng hay không.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_72_2_1', 'en-b2-72', 'ten_b2_72_2', 'listening', 'listening', 'Governments should release reliable environmental data so that citizens can evaluate the effectiveness of climate policies.', NULL, 'Trong câu vừa nghe, từ “release” mang nghĩa nào sau đây?', '["sự tài trợ; việc hỗ trợ kinh phí","thả; phóng thích; giải thoát","về phía nam","chuyến du ngoạn trên biển; chuyến đi bằng tàu thủy"]'::jsonb, 1, '“release” (/rɪˈliːs/): thả; phóng thích; giải thoát. Câu đầy đủ: Governments should release reliable environmental data so that citizens can evaluate the effectiveness of climate policies.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_72_2_2', 'en-b2-72', 'ten_b2_72_2', 'listening', 'listening', 'An effective environmental slogan can attract attention, but lasting behavioural change usually requires practical support.', NULL, 'Trong câu vừa nghe, từ “slogan” mang nghĩa nào sau đây?', '["đậu nành; sản phẩm từ đậu nành","khẩu hiệu; biểu ngữ","cử tri; người bỏ phiếu","bầu; bầu chọn"]'::jsonb, 1, '“slogan” (/ˈsloʊɡən/): khẩu hiệu; biểu ngữ. Câu đầy đủ: An effective environmental slogan can attract attention, but lasting behavioural change usually requires practical support.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
