INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_72_2', 'en-b2-72', NULL, 'comprehensive_test', 'listening', 'Our club chose a catchy slogan for its recycling campaign.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Câu lạc bộ của chúng tôi đã chọn một khẩu hiệu bắt tai cho chiến dịch tái chế.","Tôi đã mua phiên bản mới nhất của cuốn cẩm nang làm vườn này.","Chúng tôi đã thả con bướm ra ngoài trời sau khi kiểm tra cánh của nó.","Bản đồ không chính xác nên chúng tôi đã đi nhầm ngã rẽ."]'::jsonb, 0, 'Our club chose a catchy slogan for its recycling campaign. → Câu lạc bộ của chúng tôi đã chọn một khẩu hiệu bắt tai cho chiến dịch tái chế.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_72_3', 'en-b2-72', NULL, 'comprehensive_test', 'listening', 'edition', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["quốc ca; bài hát ca ngợi","phiên bản; bản in","sự lạnh lẽo; cảm giác rét","đợt tái khám; buổi theo dõi; việc theo dõi tiến độ"]'::jsonb, 1, 'edition (/ɪˈdɪʃən/) → phiên bản; bản in; số báo; số phát sóng', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_72_4', 'en-b2-72', NULL, 'comprehensive_test', 'listening', 'The map was inaccurate, so we missed the turning.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Mặc dù rất nổi tiếng, nữ ca sĩ này vẫn đi mua sắm ở các cửa hàng gần nhà.","Khách sạn nhận được mức đánh giá cao nhờ dịch vụ thân thiện.","Bản đồ không chính xác nên chúng tôi đã đi nhầm ngã rẽ.","Tôi đã mua phiên bản mới nhất của cuốn cẩm nang làm vườn này."]'::jsonb, 2, 'The map was inaccurate, so we missed the turning. → Bản đồ không chính xác nên chúng tôi đã đi nhầm ngã rẽ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
