INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_72_6', 'en-b2-72', NULL, 'comprehensive_test', 'listening', 'This so-called waterproof jacket let the rain straight through.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chiếc áo khoác cái gọi là chống thấm nước này đã để nước mưa thấm thẳng qua.","Mặc dù rất nổi tiếng, nữ ca sĩ này vẫn đi mua sắm ở các cửa hàng gần nhà.","Câu chuyện phóng đại của anh ấy khiến con nhện nhỏ bé trông to lớn đến đáng sợ.","Hãy kiểm tra bản quyền trước khi sử dụng bức ảnh đó trên trang web của bạn."]'::jsonb, 0, 'This so-called waterproof jacket let the rain straight through. → Chiếc áo khoác cái gọi là chống thấm nước này đã để nước mưa thấm thẳng qua.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_72_7', 'en-b2-72', NULL, 'comprehensive_test', 'listening', 'banner', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thuộc về công ty; thuộc về doanh nghiệp","băng rôn; biểu ngữ; cờ","nhiều; đông đảo","buồn ngủ; lờ đờ"]'::jsonb, 1, 'banner (/ˈbænər/) → băng rôn; biểu ngữ; cờ; biểu ngữ quảng cáo; quảng cáo ngang trên trang web', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_72_8', 'en-b2-72', NULL, 'comprehensive_test', 'listening', 'The hotel received a high rating for its friendly service.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã mua phiên bản mới nhất của cuốn cẩm nang làm vườn này.","Bức ảnh đó đã làm tôi đánh giá sai về diện tích thực tế của căn hộ.","Tiệm bánh sử dụng bông lúa mì làm biểu trưng của mình.","Khách sạn nhận được mức đánh giá cao nhờ dịch vụ thân thiện."]'::jsonb, 3, 'The hotel received a high rating for its friendly service. → Khách sạn nhận được mức đánh giá cao nhờ dịch vụ thân thiện.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
