INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_72_18', 'en-b2-72', NULL, 'comprehensive_test', 'reading', NULL, 'Governments should release reliable environmental data so that citizens can evaluate the effectiveness of climate policies.', 'Dựa vào câu trên, từ “release” có nghĩa phù hợp nhất là gì?', '["số dặm đã đi; quãng đường di chuyển","thả; phóng thích; giải thoát","sự quyết tâm; nghị lực","sự kỳ diệu; phép màu"]'::jsonb, 1, 'release: thả; phóng thích; giải thoát; phát hành; công bố; đưa ra; sự thả; sự phóng thích; sự phát hành. Dịch cả câu: Chính phủ nên công bố các dữ liệu môi trường đáng tin cậy để người dân có thể đánh giá hiệu quả của các chính sách khí hậu.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_72_19', 'en-b2-72', NULL, 'comprehensive_test', 'reading', NULL, 'An effective environmental slogan can attract attention, but lasting behavioural change usually requires practical support.', 'Dựa vào câu trên, từ “slogan” có nghĩa phù hợp nhất là gì?', '["làm nản lòng; khiến buồn bã","khẩu hiệu; biểu ngữ","người nghiện công việc; người cuồng công việc","nhìn trừng trừng; lườm"]'::jsonb, 1, 'slogan: khẩu hiệu; biểu ngữ. Dịch cả câu: Một khẩu hiệu môi trường hiệu quả có thể thu hút sự chú ý, nhưng sự thay đổi hành vi lâu dài thường đòi hỏi sự hỗ trợ thực tế.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_72_20', 'en-b2-72', NULL, 'comprehensive_test', 'reading', NULL, 'The revised edition of the textbook includes recent research on renewable energy and sustainable urban development.', 'Dựa vào câu trên, từ “edition” có nghĩa phù hợp nhất là gì?', '["phiên bản; bản in","bán đảo","vòm; cổng vòm","sự xao nhãng; điều làm phân tâm"]'::jsonb, 0, 'edition: phiên bản; bản in; số báo; số phát sóng. Dịch cả câu: Phiên bản sửa đổi của cuốn sách giáo khoa bao gồm các nghiên cứu gần đây về năng lượng tái tạo và phát triển đô thị bền vững.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_72_21', 'en-b2-72', NULL, 'comprehensive_test', 'reading', NULL, 'Inaccurate information online can undermine public trust and lead people to make poorly informed decisions.', 'Dựa vào câu trên, từ “inaccurate” có nghĩa phù hợp nhất là gì?', '["kê đơn (thuốc); chỉ định điều trị","nhà phê bình; nhà bình luận","không chính xác; sai sót","thuộc học tập; thuộc học thuật"]'::jsonb, 2, 'inaccurate: không chính xác; sai sót. Dịch cả câu: Thông tin không chính xác trên mạng có thể làm xói mòn lòng tin của công chúng và khiến mọi người đưa ra những quyết định thiếu sáng suốt.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_72_22', 'en-b2-72', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “làm cho sai lạc; đánh lừa; dẫn dắt sai đường”', '["pistol","hub","tide","mislead"]'::jsonb, 3, 'làm cho sai lạc; đánh lừa; dẫn dắt sai đường → mislead (/ˌmɪsˈliːd/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
