INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_72_24', 'en-b2-72', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bị phóng đại; nói quá; cường điệu”', '["workaholic","freedom","pine","exaggerated"]'::jsonb, 3, 'bị phóng đại; nói quá; cường điệu → exaggerated (/ɪɡˈzædʒəreɪtɪd/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-73', 'en', 'Bài 73: Truyền thông & Tin tức (2) - CEFR B2', 'CEFR B2', 'B2 · Truyền thông', '17 từ vựng Tiếng Anh CEFR B2 chủ đề truyền thông & tin tức kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4073, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pamphlet', 'en-b2-73', 'pamphlet', '/ˈpæmflət/', 'B2', 'tờ rơi; sách mỏng thông tin', 'n.', 'pamphleteer (n.)', 'Đồng nghĩa: booklet, brochure', 'Thường chỉ tài liệu mỏng giới thiệu về một chủ đề cụ thể, có độ dài ngắn hơn sách thông thường.', 'The nurse handed me a pamphlet about healthy eating.', NULL, 'Y tá đưa cho tôi một cuốn sách mỏng về chế độ ăn uống lành mạnh.', '{"wordId":"pamphlet","ukIpa":"/ˈpæmflət/","usIpa":"/ˈpæmflət/","cefr":"B2","topic":"media","senses":[{"pos":"n.","en":"A thin booklet giving information or arguments about a subject","vi":"tờ rơi; sách mỏng thông tin"}],"examples":[{"en":"The nurse handed me a pamphlet about healthy eating.","vi":"Y tá đưa cho tôi một cuốn sách mỏng về chế độ ăn uống lành mạnh.","audioKind":"ex"},{"en":"Public health pamphlets should use clear language and illustrations to explain preventive measures to a broad audience.","vi":"Các tài liệu tuyên truyền về y tế công cộng nên sử dụng ngôn ngữ rõ ràng và minh họa để giải thích các biện pháp phòng ngừa cho đông đảo khán giả.","audioKind":"ex2"}],"collocations":[{"en":"an information pamphlet","vi":"tờ thông tin nhỏ"},{"en":"distribute pamphlets","vi":"phát tờ rơi"},{"en":"a pamphlet on health","vi":"sách mỏng về sức khỏe"}],"wordFamily":["pamphleteer (n.)"],"synonyms":["booklet","brochure"],"antonyms":[],"tipVi":"Thường chỉ tài liệu mỏng giới thiệu về một chủ đề cụ thể, có độ dài ngắn hơn sách thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spotlight', 'en-b2-73', 'spotlight', '/ˈspɑːtlaɪt/', 'B2', 'đèn pha; đèn chiếu điểm; sự chú ý của công chúng; tâm điểm chú ý; làm nổi bật; đưa lên làm trọng tâm', 'n.', NULL, NULL, 'Cụm từ in the spotlight thường được dùng theo nghĩa bóng để chỉ việc trở thành tâm điểm của sự chú ý từ dư luận.', 'A bright spotlight followed the dancer across the stage.', NULL, 'Một luồng ánh sáng mạnh từ đèn pha chiếu theo bước chân của vũ công trên sân khấu.', '{"wordId":"spotlight","ukIpa":"/ˈspɒtlaɪt/","usIpa":"/ˈspɑːtlaɪt/","cefr":"B2","topic":"media","senses":[{"pos":"n.","en":"A lamp directing a strong beam onto a small area.","vi":"đèn pha; đèn chiếu điểm"},{"pos":"n.","en":"Public attention directed towards a person or issue.","vi":"sự chú ý của công chúng; tâm điểm chú ý"},{"pos":"v.","en":"To draw particular attention to someone or something.","vi":"làm nổi bật; đưa lên làm trọng tâm"}],"examples":[{"en":"A bright spotlight followed the dancer across the stage.","vi":"Một luồng ánh sáng mạnh từ đèn pha chiếu theo bước chân của vũ công trên sân khấu.","audioKind":"ex"},{"en":"Recent research has put urban air pollution in the spotlight, prompting calls for stricter vehicle regulations.","vi":"Các nghiên cứu gần đây đã đưa vấn đề ô nhiễm không khí đô thị trở thành tâm điểm chú ý, từ đó thúc đẩy những lời kêu gọi siết chặt các quy định về phương tiện giao thông.","audioKind":"ex2"}],"collocations":[{"en":"in the spotlight","vi":"đang ở tâm điểm chú ý"},{"en":"put the spotlight on","vi":"đưa vào tầm chú ý"},{"en":"turn the spotlight on","vi":"hướng sự chú ý vào"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ in the spotlight thường được dùng theo nghĩa bóng để chỉ việc trở thành tâm điểm của sự chú ý từ dư luận.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sensational', 'en-b2-73', 'sensational', '/senˈseɪʃənəl/', 'B2', 'gây xôn xao; giật gân; rùm beng (gây phấn khích hoặc sốc lớn, đôi khi thông qua sự phóng đại); tuyệt vời; xuất sắc; cực kỳ ấn tượng (cực kỳ ấn tượng hoặc đáng tận hưởng)', 'adj.', 'sensation (n.), sensationally (adv.), sensationalism (n.), sensationalise (v.)', NULL, 'Khi dùng để mô tả tin tức, "sensational" thường mang ý nghĩa phóng đại; khi miêu tả màn trình diễn, nó có nghĩa là xuất sắc.', 'The sensational news left everyone at breakfast speechless.', NULL, 'Bản tin giật gân khiến mọi người có mặt tại bữa sáng đều chết lặng.', '{"wordId":"sensational","ukIpa":"/senˈseɪʃənəl/","usIpa":"/senˈseɪʃənəl/","cefr":"B2","topic":"media","senses":[{"pos":"adj.","en":"Causing great excitement or shock, sometimes through exaggeration.","vi":"gây xôn xao; giật gân; rùm beng (gây phấn khích hoặc sốc lớn, đôi khi thông qua sự phóng đại)"},{"pos":"adj.","en":"Extremely impressive or enjoyable.","vi":"tuyệt vời; xuất sắc; cực kỳ ấn tượng (cực kỳ ấn tượng hoặc đáng tận hưởng)"}],"examples":[{"en":"The sensational news left everyone at breakfast speechless.","vi":"Bản tin giật gân khiến mọi người có mặt tại bữa sáng đều chết lặng.","audioKind":"ex"},{"en":"Sensational reporting may attract large audiences, but it can distort public understanding of important social issues.","vi":"Các bài báo giật gân có thể thu hút lượng lớn khán giả, nhưng nó có thể bóp méo nhận thức của công chúng về các vấn đề xã hội quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"sensational news","vi":"tin tức giật gân"},{"en":"sensational reporting","vi":"đưa tin giật gân"},{"en":"sensational performance","vi":"màn trình diễn tuyệt vời"}],"wordFamily":["sensation (n.)","sensationally (adv.)","sensationalism (n.)","sensationalise (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi dùng để mô tả tin tức, \"sensational\" thường mang ý nghĩa phóng đại; khi miêu tả màn trình diễn, nó có nghĩa là xuất sắc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wording', 'en-b2-73', 'wording', '/ˈwɝːdɪŋ/', 'B2', 'cách dùng từ; lời lẽ; văn bản', 'n.', 'word (n.), word (v.)', 'Đồng nghĩa: phrasing', 'Thường là danh từ không đếm được; nhấn mạnh từ ngữ cụ thể thay vì ngôn ngữ chung chung.', 'The wording of your message sounds a little formal.', NULL, 'Cách dùng từ trong tin nhắn của bạn nghe hơi trang trọng.', '{"wordId":"wording","ukIpa":"/ˈwɜːdɪŋ/","usIpa":"/ˈwɝːdɪŋ/","cefr":"B2","topic":"media","senses":[{"pos":"n.","en":"The particular words chosen to express something.","vi":"cách dùng từ; lời lẽ; văn bản"}],"examples":[{"en":"The wording of your message sounds a little formal.","vi":"Cách dùng từ trong tin nhắn của bạn nghe hơi trang trọng.","audioKind":"ex"},{"en":"Careful wording in public health announcements can prevent confusion and encourage people to follow advice.","vi":"Cách chọn từ cẩn thận trong các thông báo y tế công cộng có thể ngăn ngừa sự hiểu lầm và khuyến khích mọi người làm theo lời khuyên.","audioKind":"ex2"}],"collocations":[{"en":"careful wording","vi":"cách dùng từ cẩn thận"},{"en":"exact wording","vi":"nguyên văn chính xác"},{"en":"change the wording","vi":"sửa đổi cách dùng từ"}],"wordFamily":["word (n.)","word (v.)"],"synonyms":["phrasing"],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; nhấn mạnh từ ngữ cụ thể thay vì ngôn ngữ chung chung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bulletin', 'en-b2-73', 'bulletin', '/ˈbʊlətɪn/', 'B2', 'bản tin; thông báo chính thức ngắn gọn về tin tức mới nhất', 'n.', NULL, NULL, 'Nhấn mạnh vào thông tin ngắn gọn và kịp thời; news bulletin thường chỉ bản tin phát thanh.', 'We heard the weather bulletin during breakfast today.', NULL, 'Chúng tôi đã nghe bản tin thời tiết trong bữa sáng hôm nay.', '{"wordId":"bulletin","ukIpa":"/ˈbʊlətɪn/","usIpa":"/ˈbʊlətɪn/","cefr":"B2","topic":"media","senses":[{"pos":"n.","en":"a short official announcement or report of recent news","vi":"bản tin; thông báo chính thức ngắn gọn về tin tức mới nhất"}],"examples":[{"en":"We heard the weather bulletin during breakfast today.","vi":"Chúng tôi đã nghe bản tin thời tiết trong bữa sáng hôm nay.","audioKind":"ex"},{"en":"Local authorities should issue regular bulletins during severe weather so that residents can make informed safety decisions.","vi":"Các cơ quan chức năng địa phương nên phát hành các bản tin thường xuyên trong thời tiết khắc nghiệt để cư dân có thể đưa ra quyết định an toàn dựa trên thông tin chính xác.","audioKind":"ex2"}],"collocations":[{"en":"news bulletin","vi":"bản tin thời sự"},{"en":"weather bulletin","vi":"bản tin thời tiết"},{"en":"issue a bulletin","vi":"phát hành thông báo"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Nhấn mạnh vào thông tin ngắn gọn và kịp thời; news bulletin thường chỉ bản tin phát thanh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_correspondent', 'en-b2-73', 'correspondent', '/ˌkɔːrəˈspɑːndənt/', 'B2', 'phóng viên thường trú; phóng viên chuyên đề; người trao đổi thư từ', 'n.', 'correspond (v.), correspondence (n.)', 'Đồng nghĩa: reporter, journalist', 'Nghĩa phóng viên thường chỉ người đưa tin từ một địa điểm hoặc lĩnh vực cụ thể.', 'The correspondent reported live from the crowded harbour.', NULL, 'Phóng viên đã đưa tin trực tiếp từ cảng đầy ắp người.', '{"wordId":"correspondent","ukIpa":"/ˌkɒrɪˈspɒndənt/","usIpa":"/ˌkɔːrəˈspɑːndənt/","cefr":"B2","topic":"media","senses":[{"pos":"n.","en":"A journalist reporting from a particular place or on a subject.","vi":"phóng viên thường trú; phóng viên chuyên đề"},{"pos":"n.","en":"A person who exchanges letters or messages with someone.","vi":"người trao đổi thư từ"}],"examples":[{"en":"The correspondent reported live from the crowded harbour.","vi":"Phóng viên đã đưa tin trực tiếp từ cảng đầy ắp người.","audioKind":"ex"},{"en":"A foreign correspondent needs cultural knowledge to explain international events accurately to audiences at home.","vi":"Một phóng viên thường trú nước ngoài cần có kiến thức văn hóa để giải thích chính xác các sự kiện quốc tế cho khán giả trong nước.","audioKind":"ex2"}],"collocations":[{"en":"foreign correspondent","vi":"phóng viên thường trú nước ngoài"},{"en":"political correspondent","vi":"phóng viên chính trị"},{"en":"special correspondent","vi":"phóng viên đặc phái"}],"wordFamily":["correspond (v.)","correspondence (n.)"],"synonyms":["reporter","journalist"],"antonyms":[],"tipVi":"Nghĩa phóng viên thường chỉ người đưa tin từ một địa điểm hoặc lĩnh vực cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_commentary', 'en-b2-73', 'commentary', '/ˈkɑːmənteri/', 'B2', 'bình luận trực tiếp, tường thuật diễn biến sự việc; lời bình luận, bài phân tích thể hiện quan điểm', 'n.', 'comment (n.), comment (v.), commentator (n.)', NULL, 'commentary thường chỉ bài bình luận kéo dài hoặc đánh giá sâu sắc, không phải là một nhận xét ngắn lẻ tẻ.', 'We listened to the football commentary while cooking dinner.', NULL, 'Chúng tôi vừa nấu bữa tối vừa nghe bình luận trận đấu bóng đá.', '{"wordId":"commentary","ukIpa":"/ˈkɒməntəri/","usIpa":"/ˈkɑːmənteri/","cefr":"B2","topic":"media","senses":[{"pos":"n.","en":"a spoken description of an event as it happens","vi":"bình luận trực tiếp, tường thuật diễn biến sự việc"},{"pos":"n.","en":"an explanation or discussion expressing opinions about something","vi":"lời bình luận, bài phân tích thể hiện quan điểm"}],"examples":[{"en":"We listened to the football commentary while cooking dinner.","vi":"Chúng tôi vừa nấu bữa tối vừa nghe bình luận trận đấu bóng đá.","audioKind":"ex"},{"en":"Political commentary can help citizens understand complex policies, but it should be clearly distinguished from factual reporting.","vi":"Bình luận chính trị có thể giúp công dân hiểu các chính sách phức tạp, nhưng cần được phân biệt rõ ràng với tin tức đưa tin khách quan.","audioKind":"ex2"}],"collocations":[{"en":"live commentary","vi":"bình luận trực tiếp"},{"en":"running commentary","vi":"bình luận liên tục"},{"en":"political commentary","vi":"bình luận chính trị"},{"en":"commentary on","vi":"bình luận về"}],"wordFamily":["comment (n.)","comment (v.)","commentator (n.)"],"synonyms":[],"antonyms":[],"tipVi":"commentary thường chỉ bài bình luận kéo dài hoặc đánh giá sâu sắc, không phải là một nhận xét ngắn lẻ tẻ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_broadcast', 'en-b2-73', 'broadcast', '/ˈbrɔːdkæst/', 'B2', 'phát sóng; phát thanh truyền hình; chương trình phát sóng', 'v.', 'broadcaster (n.), broadcasting (n.)', 'Đồng nghĩa: transmit, air', 'Dạng quá khứ và phân từ hai của broadcast thường vẫn giữ nguyên là broadcast.', 'The station broadcasts local news every morning before breakfast.', NULL, 'Đài phát thanh này phát sóng tin tức địa phương vào mỗi buổi sáng trước bữa ăn sáng.', '{"wordId":"broadcast","ukIpa":"/ˈbrɔːdkɑːst/","usIpa":"/ˈbrɔːdkæst/","cefr":"B2","topic":"media","senses":[{"pos":"v.","en":"To transmit programmes through radio, television, or the internet.","vi":"phát sóng; phát thanh truyền hình"},{"pos":"n.","en":"A programme transmitted through radio, television, or the internet.","vi":"chương trình phát sóng"}],"examples":[{"en":"The station broadcasts local news every morning before breakfast.","vi":"Đài phát thanh này phát sóng tin tức địa phương vào mỗi buổi sáng trước bữa ăn sáng.","audioKind":"ex"},{"en":"Public television should broadcast educational programmes that help children understand science and develop an interest in learning.","vi":"Truyền hình công cộng nên phát sóng các chương trình giáo dục giúp trẻ em hiểu về khoa học và vun đắp hứng thú học tập.","audioKind":"ex2"}],"collocations":[{"en":"broadcast live","vi":"phát sóng trực tiếp"},{"en":"news broadcast","vi":"bản tin phát thanh truyền hình"},{"en":"broadcast a programme","vi":"phát sóng một chương trình"}],"wordFamily":["broadcaster (n.)","broadcasting (n.)"],"synonyms":["transmit","air"],"antonyms":[],"tipVi":"Dạng quá khứ và phân từ hai của broadcast thường vẫn giữ nguyên là broadcast.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_announcer', 'en-b2-73', 'announcer', '/əˈnaʊnsər/', 'B2', 'xướng ngôn viên; phát thanh viên; người phát thanh', 'n.', 'announce (v.), announcement (n.)', NULL, 'announcer chịu trách nhiệm phát thanh; journalist chú trọng phỏng vấn tin tức.', 'The announcer reminded passengers to keep their bags nearby.', NULL, 'Phát thanh viên nhắc nhở hành khách để hành lý ở gần mình.', '{"wordId":"announcer","ukIpa":"/əˈnaʊnsə/","usIpa":"/əˈnaʊnsər/","cefr":"B2","topic":"media","senses":[{"pos":"n.","en":"Someone who presents information on broadcasts or at public events","vi":"xướng ngôn viên; phát thanh viên; người phát thanh"}],"examples":[{"en":"The announcer reminded passengers to keep their bags nearby.","vi":"Phát thanh viên nhắc nhở hành khách để hành lý ở gần mình.","audioKind":"ex"},{"en":"A skilled announcer can make emergency broadcasts clearer, helping the public respond calmly and appropriately.","vi":"Một phát thanh viên giỏi có thể làm cho các bản tin khẩn cấp trở nên rõ ràng hơn, giúp công chúng ứng phó một cách bình tĩnh và thích hợp.","audioKind":"ex2"}],"collocations":[{"en":"radio announcer","vi":"phát thanh viên đài phát thanh"},{"en":"television announcer","vi":"phát thanh viên truyền hình"},{"en":"stadium announcer","vi":"phát thanh viên sân vận động"}],"wordFamily":["announce (v.)","announcement (n.)"],"synonyms":[],"antonyms":[],"tipVi":"announcer chịu trách nhiệm phát thanh; journalist chú trọng phỏng vấn tin tức.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_media', 'en-b2-73', 'media', '/ˈmiːdiə/', 'B2', 'phương tiện truyền thông; báo chí', 'n.', 'medium (n.)', NULL, 'Cụm từ "the media" thường được dùng để chỉ chung giới truyền thông; trong khi "medium" dùng cho một phương tiện đơn lẻ.', 'The local media reported on our neighbourhood festival.', NULL, 'Truyền thông địa phương đã đưa tin về lễ hội khu phố của chúng tôi.', '{"wordId":"media","ukIpa":"/ˈmiːdiə/","usIpa":"/ˈmiːdiə/","cefr":"B2","topic":"media","senses":[{"pos":"n.","en":"Organisations and channels that provide news and information publicly.","vi":"phương tiện truyền thông; báo chí"}],"examples":[{"en":"The local media reported on our neighbourhood festival.","vi":"Truyền thông địa phương đã đưa tin về lễ hội khu phố của chúng tôi.","audioKind":"ex"},{"en":"The media can influence public attitudes by deciding which environmental issues receive the most attention.","vi":"Truyền thông có thể tác động đến thái độ của công chúng bằng cách quyết định những vấn đề môi trường nào nhận được nhiều sự quan tâm nhất.","audioKind":"ex2"}],"collocations":[{"en":"mass media","vi":"đại chúng truyền thông"},{"en":"media coverage","vi":"tin tức truyền thông"},{"en":"social media","vi":"mạng xã hội"},{"en":"the media","vi":"giới truyền thông"}],"wordFamily":["medium (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ \"the media\" thường được dùng để chỉ chung giới truyền thông; trong khi \"medium\" dùng cho một phương tiện đơn lẻ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mass-media', 'en-b2-73', 'mass media', '/ˌmæs ˈmiːdiə/', 'B2', 'phương tiện thông tin đại chúng; đại chúng truyền thông', 'n.', 'medium (n.), media (n.)', NULL, 'Khi chỉ chung các phương tiện truyền thông đại chúng, thường dùng the mass media và đi với động từ số nhiều.', 'My grandparents relied on mass media for their daily news.', NULL, 'Ông bà tôi dựa vào các phương tiện thông tin đại chúng để cập nhật tin tức hàng ngày.', '{"wordId":"mass-media","ukIpa":"/ˌmæs ˈmiːdiə/","usIpa":"/ˌmæs ˈmiːdiə/","cefr":"B2","topic":"media","senses":[{"pos":"n.","en":"communication channels that deliver information to very large audiences","vi":"phương tiện thông tin đại chúng; đại chúng truyền thông"}],"examples":[{"en":"My grandparents relied on mass media for their daily news.","vi":"Ông bà tôi dựa vào các phương tiện thông tin đại chúng để cập nhật tin tức hàng ngày.","audioKind":"ex"},{"en":"Mass media can shape public attitudes towards environmental issues by deciding which stories receive widespread attention.","vi":"Truyền thông đại chúng có thể định hình thái độ của công chúng đối với các vấn đề môi trường bằng cách quyết định câu chuyện nào nhận được sự chú ý rộng rãi.","audioKind":"ex2"}],"collocations":[{"en":"the mass media","vi":"các phương tiện thông tin đại chúng"},{"en":"mass media coverage","vi":"sự đưa tin của truyền thông đại chúng"},{"en":"mass media influence","vi":"ảnh hưởng của truyền thông đại chúng"}],"wordFamily":["medium (n.)","media (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ chung các phương tiện truyền thông đại chúng, thường dùng the mass media và đi với động từ số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_highlight', 'en-b2-73', 'highlight', '/ˈhaɪlaɪt/', 'B2', 'làm nổi bật; nhấn mạnh; phần tuyệt vời nhất; điểm nhấn đáng nhớ nhất; đánh dấu bằng màu sáng', 'v.', NULL, 'Đồng nghĩa: emphasise, underline · Trái nghĩa: downplay', 'Đóng vai trò là động từ đi thẳng với tân ngữ: highlight the problem.', 'The boat ride was the highlight of our holiday.', NULL, 'Chuyến đi thuyền là điểm nhấn tuyệt vời nhất trong kỳ nghỉ của chúng tôi.', '{"wordId":"highlight","ukIpa":"/ˈhaɪlaɪt/","usIpa":"/ˈhaɪlaɪt/","cefr":"B2","topic":"media","senses":[{"pos":"v.","en":"Draw attention to something important or especially noticeable.","vi":"làm nổi bật; nhấn mạnh"},{"pos":"n.","en":"The best or most memorable part of an experience.","vi":"phần tuyệt vời nhất; điểm nhấn đáng nhớ nhất"},{"pos":"v.","en":"Mark words with bright colour to make them noticeable.","vi":"đánh dấu bằng màu sáng"}],"examples":[{"en":"The boat ride was the highlight of our holiday.","vi":"Chuyến đi thuyền là điểm nhấn tuyệt vời nhất trong kỳ nghỉ của chúng tôi.","audioKind":"ex"},{"en":"Recent studies highlight the importance of accessible green spaces for the physical and mental health of urban residents.","vi":"Các nghiên cứu gần đây nhấn mạnh tầm quan trọng của các không gian xanh dễ tiếp cận đối với sức khỏe thể chất và tinh thần của cư dân đô thị.","audioKind":"ex2"}],"collocations":[{"en":"highlight a problem","vi":"làm nổi bật một vấn đề"},{"en":"highlight the importance of","vi":"nhấn mạnh tầm quan trọng của"},{"en":"the highlight of the trip","vi":"điểm nhấn của chuyến đi"}],"wordFamily":[],"synonyms":["emphasise","underline"],"antonyms":["downplay"],"tipVi":"Đóng vai trò là động từ đi thẳng với tân ngữ: highlight the problem.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spokesman', 'en-b2-73', 'spokesman', '/ˈspoʊksmən/', 'B2', 'nam phát ngôn viên', 'n.', 'spokeswoman (n.), spokesperson (n.)', 'Đồng nghĩa: spokesperson, representative', 'Chỉ dùng cụ thể cho nam giới; trong trường hợp không phân biệt giới tính, hãy sử dụng từ spokesperson.', 'A spokesman explained why the swimming pool was closed.', NULL, 'Một nam phát ngôn viên đã giải thích lý do tại sao hồ bơi lại phải đóng cửa.', '{"wordId":"spokesman","ukIpa":"/ˈspəʊksmən/","usIpa":"/ˈspoʊksmən/","cefr":"B2","topic":"media","senses":[{"pos":"n.","en":"A man who speaks officially for a group or organisation","vi":"nam phát ngôn viên"}],"examples":[{"en":"A spokesman explained why the swimming pool was closed.","vi":"Một nam phát ngôn viên đã giải thích lý do tại sao hồ bơi lại phải đóng cửa.","audioKind":"ex"},{"en":"The government spokesman announced that additional funding would support public transport improvements in rural communities.","vi":"Nam phát ngôn viên của chính phủ thông báo rằng nguồn vốn bổ sung sẽ hỗ trợ cải thiện giao thông công cộng tại các cộng đồng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"a government spokesman","vi":"một phát ngôn viên chính phủ"},{"en":"a company spokesman","vi":"một phát ngôn viên công ty"},{"en":"a spokesman for","vi":"người phát ngôn cho"}],"wordFamily":["spokeswoman (n.)","spokesperson (n.)"],"synonyms":["spokesperson","representative"],"antonyms":[],"tipVi":"Chỉ dùng cụ thể cho nam giới; trong trường hợp không phân biệt giới tính, hãy sử dụng từ spokesperson.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_subscription', 'en-b2-73', 'subscription', '/səbˈskrɪpʃən/', 'B2', 'sự đặt mua; sự đăng ký dài hạn; tiền thuê bao; phí đăng ký định kỳ', 'n.', 'subscribe (v.), subscriber (n.)', NULL, 'Subscription chỉ sự đăng ký hoặc khoản phí định kỳ; trong khi đó người sử dụng/khách hàng đăng ký được gọi là subscriber.', 'I cancelled my magazine subscription before moving abroad.', NULL, 'Tôi đã hủy đặt mua tạp chí trước khi chuyển ra nước ngoài sinh sống.', '{"wordId":"subscription","ukIpa":"/səbˈskrɪpʃən/","usIpa":"/səbˈskrɪpʃən/","cefr":"B2","topic":"media","senses":[{"pos":"n.","en":"An arrangement to receive a service or publication regularly.","vi":"sự đặt mua; sự đăng ký dài hạn"},{"pos":"n.","en":"Money paid regularly for a publication, service, or membership.","vi":"tiền thuê bao; phí đăng ký định kỳ"}],"examples":[{"en":"I cancelled my magazine subscription before moving abroad.","vi":"Tôi đã hủy đặt mua tạp chí trước khi chuyển ra nước ngoài sinh sống.","audioKind":"ex"},{"en":"Subscription services can widen access to educational resources, although recurring fees may exclude lower-income households.","vi":"Các dịch vụ đăng ký thuê bao có thể mở rộng khả năng tiếp cận các nguồn tài nguyên giáo dục, mặc dù chi phí định kỳ có thể khiến các hộ gia đình thu nhập thấp không thể tiếp cận.","audioKind":"ex2"}],"collocations":[{"en":"an annual subscription","vi":"đăng ký dài hạn hàng năm"},{"en":"subscription fee","vi":"phí thuê bao, phí đăng ký"},{"en":"renew a subscription","vi":"gia hạn thuê bao"},{"en":"cancel a subscription","vi":"hủy đăng ký, hủy thuê bao"}],"wordFamily":["subscribe (v.)","subscriber (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Subscription chỉ sự đăng ký hoặc khoản phí định kỳ; trong khi đó người sử dụng/khách hàng đăng ký được gọi là subscriber.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_caption', 'en-b2-73', 'caption', '/ˈkæpʃən/', 'B2', 'chú thích ảnh; phụ đề; viết chú thích; thêm phụ đề', 'n.', 'captioned (adj.), captioning (n.)', NULL, 'caption dùng cho hình ảnh hoặc video; tiêu đề bài báo thường dùng headline.', 'The caption explains where the mountain photo was taken.', NULL, 'Phần chú thích giải thích bức ảnh ngọn núi được chụp ở đâu.', '{"wordId":"caption","ukIpa":"/ˈkæpʃən/","usIpa":"/ˈkæpʃən/","cefr":"B2","topic":"media","senses":[{"pos":"n.","en":"Words accompanying an image or showing speech on a screen","vi":"chú thích ảnh; phụ đề"},{"pos":"v.","en":"To add explanatory words to an image or video","vi":"viết chú thích; thêm phụ đề"}],"examples":[{"en":"The caption explains where the mountain photo was taken.","vi":"Phần chú thích giải thích bức ảnh ngọn núi được chụp ở đâu.","audioKind":"ex"},{"en":"Accurate captions make online educational videos more accessible to learners who are deaf or hard of hearing.","vi":"Phụ đề chính xác giúp các video giáo dục trực tuyến dễ tiếp cận hơn đối với người học bị khiếm thính hoặc khó khăn về thính giác.","audioKind":"ex2"}],"collocations":[{"en":"a photo caption","vi":"chú thích ảnh"},{"en":"write a caption","vi":"viết chú thích"},{"en":"closed captions","vi":"phụ đề có thể bật tắt"}],"wordFamily":["captioned (adj.)","captioning (n.)"],"synonyms":[],"antonyms":[],"tipVi":"caption dùng cho hình ảnh hoặc video; tiêu đề bài báo thường dùng headline.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_contestant', 'en-b2-73', 'contestant', '/kənˈtestənt/', 'B2', 'thí sinh; người tham gia thi đấu', 'n.', 'contest (n.), contest (v.)', 'Đồng nghĩa: competitor, participant', 'contestant chỉ người tham gia thi đấu; participant cũng có thể chỉ người tham gia hoạt động thông thường.', 'Each contestant brought a homemade cake for the judges.', NULL, 'Mỗi thí sinh đã mang theo một chiếc bánh tự làm cho ban giám khảo chấm điểm.', '{"wordId":"contestant","ukIpa":"/kənˈtestənt/","usIpa":"/kənˈtestənt/","cefr":"B2","topic":"media","senses":[{"pos":"n.","en":"A person who takes part in a competition.","vi":"thí sinh; người tham gia thi đấu"}],"examples":[{"en":"Each contestant brought a homemade cake for the judges.","vi":"Mỗi thí sinh đã mang theo một chiếc bánh tự làm cho ban giám khảo chấm điểm.","audioKind":"ex"},{"en":"Every contestant in a televised competition should receive clear guidance about the judging criteria beforehand.","vi":"Mọi thí sinh trong một cuộc thi truyền hình đều nên nhận được hướng dẫn rõ ràng về tiêu chí chấm thi từ trước.","audioKind":"ex2"}],"collocations":[{"en":"contestant in a competition","vi":"thí sinh trong một cuộc thi"},{"en":"quiz show contestant","vi":"thí sinh chương trình đố vui"},{"en":"winning contestant","vi":"thí sinh chiến thắng"}],"wordFamily":["contest (n.)","contest (v.)"],"synonyms":["competitor","participant"],"antonyms":[],"tipVi":"contestant chỉ người tham gia thi đấu; participant cũng có thể chỉ người tham gia hoạt động thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_editing', 'en-b2-73', 'editing', '/ˈedɪtɪŋ/', 'B2', 'việc biên tập; công tác hiệu đính; sự cắt dựng (phim ảnh); biên tập; hiệu đính; biên dựng', 'n.', 'edit (v.), editor (n.), editorial (adj.)', NULL, 'Có thể đóng vai trò là danh từ chỉ hành động, hoặc là dạng phân từ hiện tại của động từ edit.', 'Editing these holiday videos took me all afternoon.', NULL, 'Việc cắt dựng những video kỳ nghỉ này tiêu tốn của tôi cả buổi chiều.', '{"wordId":"editing","ukIpa":"/ˈedɪtɪŋ/","usIpa":"/ˈedɪtɪŋ/","cefr":"B2","topic":"media","senses":[{"pos":"n.","en":"Preparing writing, images, or recordings by correcting and arranging them.","vi":"việc biên tập; công tác hiệu đính; sự cắt dựng (phim ảnh)"},{"pos":"v.","en":"Correcting or arranging material to prepare it for use.","vi":"biên tập; hiệu đính; biên dựng"}],"examples":[{"en":"Editing these holiday videos took me all afternoon.","vi":"Việc cắt dựng những video kỳ nghỉ này tiêu tốn của tôi cả buổi chiều.","audioKind":"ex"},{"en":"Careful editing helps researchers present complex findings clearly and makes academic articles easier to understand.","vi":"Quá trình biên tập kỹ lưỡng giúp các nhà nghiên cứu trình bày những phát hiện phức tạp một cách rõ ràng và làm cho các bài báo học thuật dễ hiểu hơn.","audioKind":"ex2"}],"collocations":[{"en":"video editing","vi":"dựng video"},{"en":"copy editing","vi":"biên tập bản thảo"},{"en":"editing software","vi":"phần mềm chỉnh sửa"}],"wordFamily":["edit (v.)","editor (n.)","editorial (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể đóng vai trò là danh từ chỉ hành động, hoặc là dạng phân từ hiện tại của động từ edit.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_73_1', 'en-b2-73', 'Cách dùng “sensational” (adj.) — gây xôn xao; giật gân; rùm beng (gây phấn khích hoặc sốc lớn, đôi khi thông qua sự phóng đại)', 'sensational news  ·  sensational reporting  ·  sensational performance', 'Khi dùng để mô tả tin tức, "sensational" thường mang ý nghĩa phóng đại; khi miêu tả màn trình diễn, nó có nghĩa là xuất sắc.', 'Họ từ (Word Family): sensation (n.), sensationally (adv.), sensationalism (n.), sensationalise (v.)', '[{"hanzi":"The sensational news left everyone at breakfast speechless.","pinyin":"","meaning":"Bản tin giật gân khiến mọi người có mặt tại bữa sáng đều chết lặng."},{"hanzi":"Sensational reporting may attract large audiences, but it can distort public understanding of important social issues.","pinyin":"","meaning":"Các bài báo giật gân có thể thu hút lượng lớn khán giả, nhưng nó có thể bóp méo nhận thức của công chúng về các vấn đề xã hội quan trọng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_73_2', 'en-b2-73', 'Cách dùng “subscription” (n.) — sự đặt mua; sự đăng ký dài hạn', 'an annual subscription  ·  subscription fee  ·  renew a subscription', 'Subscription chỉ sự đăng ký hoặc khoản phí định kỳ; trong khi đó người sử dụng/khách hàng đăng ký được gọi là subscriber.', 'Họ từ (Word Family): subscribe (v.), subscriber (n.)', '[{"hanzi":"I cancelled my magazine subscription before moving abroad.","pinyin":"","meaning":"Tôi đã hủy đặt mua tạp chí trước khi chuyển ra nước ngoài sinh sống."},{"hanzi":"Subscription services can widen access to educational resources, although recurring fees may exclude lower-income households.","pinyin":"","meaning":"Các dịch vụ đăng ký thuê bao có thể mở rộng khả năng tiếp cận các nguồn tài nguyên giáo dục, mặc dù chi phí định kỳ có thể khiến các hộ gia đình thu nhập thấp không thể tiếp cận."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_73_3', 'en-b2-73', 'Cách dùng “media” (n.) — phương tiện truyền thông; báo chí', 'mass media  ·  media coverage  ·  social media', 'Cụm từ "the media" thường được dùng để chỉ chung giới truyền thông; trong khi "medium" dùng cho một phương tiện đơn lẻ.', 'Họ từ (Word Family): medium (n.)', '[{"hanzi":"The local media reported on our neighbourhood festival.","pinyin":"","meaning":"Truyền thông địa phương đã đưa tin về lễ hội khu phố của chúng tôi."},{"hanzi":"The media can influence public attitudes by deciding which environmental issues receive the most attention.","pinyin":"","meaning":"Truyền thông có thể tác động đến thái độ của công chúng bằng cách quyết định những vấn đề môi trường nào nhận được nhiều sự quan tâm nhất."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_73_4', 'en-b2-73', 'Cách dùng “spotlight” (n.) — đèn pha; đèn chiếu điểm', 'in the spotlight  ·  put the spotlight on  ·  turn the spotlight on', 'Cụm từ in the spotlight thường được dùng theo nghĩa bóng để chỉ việc trở thành tâm điểm của sự chú ý từ dư luận.', NULL, '[{"hanzi":"A bright spotlight followed the dancer across the stage.","pinyin":"","meaning":"Một luồng ánh sáng mạnh từ đèn pha chiếu theo bước chân của vũ công trên sân khấu."},{"hanzi":"Recent research has put urban air pollution in the spotlight, prompting calls for stricter vehicle regulations.","pinyin":"","meaning":"Các nghiên cứu gần đây đã đưa vấn đề ô nhiễm không khí đô thị trở thành tâm điểm chú ý, từ đó thúc đẩy những lời kêu gọi siết chặt các quy định về phương tiện giao thông."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_73_1', 'en-b2-73', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_73_1_1', 'ten_b2_73_1', 'pamphlet', 'The nurse handed me a pamphlet about healthy eating.', 'The nurse handed me a pamphlet about healthy eating.', '/ˈpæmflət/', 'Y tá đưa cho tôi một cuốn sách mỏng về chế độ ăn uống lành mạnh.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_73_1_2', 'ten_b2_73_1', 'spotlight', 'A bright spotlight followed the dancer across the stage.', 'A bright spotlight followed the dancer across the stage.', '/ˈspɑːtlaɪt/', 'Một luồng ánh sáng mạnh từ đèn pha chiếu theo bước chân của vũ công trên sân khấu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_73_1_3', 'ten_b2_73_1', 'sensational', 'The sensational news left everyone at breakfast speechless.', 'The sensational news left everyone at breakfast speechless.', '/senˈseɪʃənəl/', 'Bản tin giật gân khiến mọi người có mặt tại bữa sáng đều chết lặng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_73_1_4', 'ten_b2_73_1', 'wording', 'The wording of your message sounds a little formal.', 'The wording of your message sounds a little formal.', '/ˈwɝːdɪŋ/', 'Cách dùng từ trong tin nhắn của bạn nghe hơi trang trọng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_73_1_5', 'ten_b2_73_1', 'bulletin', 'We heard the weather bulletin during breakfast today.', 'We heard the weather bulletin during breakfast today.', '/ˈbʊlətɪn/', 'Chúng tôi đã nghe bản tin thời tiết trong bữa sáng hôm nay.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_73_1_6', 'ten_b2_73_1', 'correspondent', 'The correspondent reported live from the crowded harbour.', 'The correspondent reported live from the crowded harbour.', '/ˌkɔːrəˈspɑːndənt/', 'Phóng viên đã đưa tin trực tiếp từ cảng đầy ắp người.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_73_1_7', 'ten_b2_73_1', 'commentary', 'We listened to the football commentary while cooking dinner.', 'We listened to the football commentary while cooking dinner.', '/ˈkɑːmənteri/', 'Chúng tôi vừa nấu bữa tối vừa nghe bình luận trận đấu bóng đá.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_73_1_8', 'ten_b2_73_1', 'broadcast', 'The station broadcasts local news every morning before breakfast.', 'The station broadcasts local news every morning before breakfast.', '/ˈbrɔːdkæst/', 'Đài phát thanh này phát sóng tin tức địa phương vào mỗi buổi sáng trước bữa ăn sáng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_73_1_1', 'en-b2-73', 'ten_b2_73_1', 'listening', 'listening', 'The nurse handed me a pamphlet about healthy eating.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Y tá đưa cho tôi một cuốn sách mỏng về chế độ ăn uống lành mạnh.","Truyền thông địa phương đã đưa tin về lễ hội khu phố của chúng tôi.","Mỗi thí sinh đã mang theo một chiếc bánh tự làm cho ban giám khảo chấm điểm.","Phần chú thích giải thích bức ảnh ngọn núi được chụp ở đâu."]'::jsonb, 0, 'The nurse handed me a pamphlet about healthy eating. → Y tá đưa cho tôi một cuốn sách mỏng về chế độ ăn uống lành mạnh.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_73_1_2', 'en-b2-73', 'ten_b2_73_1', 'listening', 'listening', 'A bright spotlight followed the dancer across the stage.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một nam phát ngôn viên đã giải thích lý do tại sao hồ bơi lại phải đóng cửa.","Y tá đưa cho tôi một cuốn sách mỏng về chế độ ăn uống lành mạnh.","Một luồng ánh sáng mạnh từ đèn pha chiếu theo bước chân của vũ công trên sân khấu.","Tôi đã hủy đặt mua tạp chí trước khi chuyển ra nước ngoài sinh sống."]'::jsonb, 2, 'A bright spotlight followed the dancer across the stage. → Một luồng ánh sáng mạnh từ đèn pha chiếu theo bước chân của vũ công trên sân khấu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_73_1_3', 'en-b2-73', 'ten_b2_73_1', 'listening', 'listening', 'The sensational news left everyone at breakfast speechless.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bản tin giật gân khiến mọi người có mặt tại bữa sáng đều chết lặng.","Phần chú thích giải thích bức ảnh ngọn núi được chụp ở đâu.","Phóng viên đã đưa tin trực tiếp từ cảng đầy ắp người.","Ông bà tôi dựa vào các phương tiện thông tin đại chúng để cập nhật tin tức hàng ngày."]'::jsonb, 0, 'The sensational news left everyone at breakfast speechless. → Bản tin giật gân khiến mọi người có mặt tại bữa sáng đều chết lặng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_73_2', 'en-b2-73', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_73_2_1', 'ten_b2_73_2', 'pamphlet', 'Public health pamphlets should use clear language and illustrations to explain preventive measures to a broad audience.', 'Public health pamphlets should use clear language and illustrations to explain preventive measures to a broad audience.', '/ˈpæmflət/', 'Các tài liệu tuyên truyền về y tế công cộng nên sử dụng ngôn ngữ rõ ràng và minh họa để giải thích các biện pháp phòng ngừa cho đông đảo khán giả.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_73_2_2', 'ten_b2_73_2', 'spotlight', 'Recent research has put urban air pollution in the spotlight, prompting calls for stricter vehicle regulations.', 'Recent research has put urban air pollution in the spotlight, prompting calls for stricter vehicle regulations.', '/ˈspɑːtlaɪt/', 'Các nghiên cứu gần đây đã đưa vấn đề ô nhiễm không khí đô thị trở thành tâm điểm chú ý, từ đó thúc đẩy những lời kêu gọi siết chặt các quy định về phương tiện giao thông.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_73_2_3', 'ten_b2_73_2', 'sensational', 'Sensational reporting may attract large audiences, but it can distort public understanding of important social issues.', 'Sensational reporting may attract large audiences, but it can distort public understanding of important social issues.', '/senˈseɪʃənəl/', 'Các bài báo giật gân có thể thu hút lượng lớn khán giả, nhưng nó có thể bóp méo nhận thức của công chúng về các vấn đề xã hội quan trọng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_73_2_4', 'ten_b2_73_2', 'wording', 'Careful wording in public health announcements can prevent confusion and encourage people to follow advice.', 'Careful wording in public health announcements can prevent confusion and encourage people to follow advice.', '/ˈwɝːdɪŋ/', 'Cách chọn từ cẩn thận trong các thông báo y tế công cộng có thể ngăn ngừa sự hiểu lầm và khuyến khích mọi người làm theo lời khuyên.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_73_2_5', 'ten_b2_73_2', 'bulletin', 'Local authorities should issue regular bulletins during severe weather so that residents can make informed safety decisions.', 'Local authorities should issue regular bulletins during severe weather so that residents can make informed safety decisions.', '/ˈbʊlətɪn/', 'Các cơ quan chức năng địa phương nên phát hành các bản tin thường xuyên trong thời tiết khắc nghiệt để cư dân có thể đưa ra quyết định an toàn dựa trên thông tin chính xác.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_73_2_6', 'ten_b2_73_2', 'correspondent', 'A foreign correspondent needs cultural knowledge to explain international events accurately to audiences at home.', 'A foreign correspondent needs cultural knowledge to explain international events accurately to audiences at home.', '/ˌkɔːrəˈspɑːndənt/', 'Một phóng viên thường trú nước ngoài cần có kiến thức văn hóa để giải thích chính xác các sự kiện quốc tế cho khán giả trong nước.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_73_2_1', 'en-b2-73', 'ten_b2_73_2', 'listening', 'listening', 'Public health pamphlets should use clear language and illustrations to explain preventive measures to a broad audience.', NULL, 'Trong câu vừa nghe, từ “pamphlet” mang nghĩa nào sau đây?', '["điều bình thường; chuẩn mực thông thường","thận","tờ rơi; sách mỏng thông tin","lãnh thổ; vùng đất; khu vực"]'::jsonb, 2, '“pamphlet” (/ˈpæmflət/): tờ rơi; sách mỏng thông tin. Câu đầy đủ: Public health pamphlets should use clear language and illustrations to explain preventive measures to a broad audience.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_73_2_2', 'en-b2-73', 'ten_b2_73_2', 'listening', 'listening', 'Recent research has put urban air pollution in the spotlight, prompting calls for stricter vehicle regulations.', NULL, 'Trong câu vừa nghe, từ “spotlight” mang nghĩa nào sau đây?', '["học phần; phần; đơn vị học tập","cũ; trước đây; tiền nhiệm","đèn pha; đèn chiếu điểm","lợi ích tài chính; phần hùn; cổ phần"]'::jsonb, 2, '“spotlight” (/ˈspɑːtlaɪt/): đèn pha; đèn chiếu điểm. Câu đầy đủ: Recent research has put urban air pollution in the spotlight, prompting calls for stricter vehicle regulations.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
