INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_73_1', 'en-b2-73', NULL, 'comprehensive_test', 'listening', 'pamphlet', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["kinh điển; có giá trị lâu bền","điện tử","tờ rơi; sách mỏng thông tin","trưng bày; triển lãm"]'::jsonb, 2, 'pamphlet (/ˈpæmflət/) → tờ rơi; sách mỏng thông tin', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_73_2', 'en-b2-73', NULL, 'comprehensive_test', 'listening', 'A bright spotlight followed the dancer across the stage.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Phần chú thích giải thích bức ảnh ngọn núi được chụp ở đâu.","Chúng tôi đã nghe bản tin thời tiết trong bữa sáng hôm nay.","Phát thanh viên nhắc nhở hành khách để hành lý ở gần mình.","Một luồng ánh sáng mạnh từ đèn pha chiếu theo bước chân của vũ công trên sân khấu."]'::jsonb, 3, 'A bright spotlight followed the dancer across the stage. → Một luồng ánh sáng mạnh từ đèn pha chiếu theo bước chân của vũ công trên sân khấu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_73_3', 'en-b2-73', NULL, 'comprehensive_test', 'listening', 'sensational', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đất sét; đất nung","vỡ vụn; bẻ vụn","hình tròn; có dạng vòng tròn","gây xôn xao; giật gân; rùm beng (gây phấn khích hoặc sốc lớn, đôi khi thông qua sự phóng đại)"]'::jsonb, 3, 'sensational (/senˈseɪʃənəl/) → gây xôn xao; giật gân; rùm beng (gây phấn khích hoặc sốc lớn, đôi khi thông qua sự phóng đại); tuyệt vời; xuất sắc; cực kỳ ấn tượng (cực kỳ ấn tượng hoặc đáng tận hưởng)', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_73_4', 'en-b2-73', NULL, 'comprehensive_test', 'listening', 'The wording of your message sounds a little formal.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Phát thanh viên nhắc nhở hành khách để hành lý ở gần mình.","Đài phát thanh này phát sóng tin tức địa phương vào mỗi buổi sáng trước bữa ăn sáng.","Cách dùng từ trong tin nhắn của bạn nghe hơi trang trọng.","Một luồng ánh sáng mạnh từ đèn pha chiếu theo bước chân của vũ công trên sân khấu."]'::jsonb, 2, 'The wording of your message sounds a little formal. → Cách dùng từ trong tin nhắn của bạn nghe hơi trang trọng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_73_5', 'en-b2-73', NULL, 'comprehensive_test', 'listening', 'bulletin', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["lớn lao; khổng lồ; cực kỳ","chắc chắn; có khả năng cao","bản tin; thông báo chính thức ngắn gọn về tin tức mới nhất","đồ trang trí, vật trang hoàng"]'::jsonb, 2, 'bulletin (/ˈbʊlətɪn/) → bản tin; thông báo chính thức ngắn gọn về tin tức mới nhất', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_73_6', 'en-b2-73', NULL, 'comprehensive_test', 'listening', 'The correspondent reported live from the crowded harbour.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Việc cắt dựng những video kỳ nghỉ này tiêu tốn của tôi cả buổi chiều.","Phóng viên đã đưa tin trực tiếp từ cảng đầy ắp người.","Ông bà tôi dựa vào các phương tiện thông tin đại chúng để cập nhật tin tức hàng ngày.","Chúng tôi vừa nấu bữa tối vừa nghe bình luận trận đấu bóng đá."]'::jsonb, 1, 'The correspondent reported live from the crowded harbour. → Phóng viên đã đưa tin trực tiếp từ cảng đầy ắp người.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_73_7', 'en-b2-73', NULL, 'comprehensive_test', 'listening', 'commentary', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["số lượng vượt mức; phần thừa","nhà u tư; chủ doanh nghiệp; doanh nhân","bình luận trực tiếp, tường thuật diễn biến sự việc","giường tầng; giường nằm (trên tàu, xe)"]'::jsonb, 2, 'commentary (/ˈkɑːmənteri/) → bình luận trực tiếp, tường thuật diễn biến sự việc; lời bình luận, bài phân tích thể hiện quan điểm', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_73_8', 'en-b2-73', NULL, 'comprehensive_test', 'listening', 'The station broadcasts local news every morning before breakfast.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một luồng ánh sáng mạnh từ đèn pha chiếu theo bước chân của vũ công trên sân khấu.","Đài phát thanh này phát sóng tin tức địa phương vào mỗi buổi sáng trước bữa ăn sáng.","Truyền thông địa phương đã đưa tin về lễ hội khu phố của chúng tôi.","Bản tin giật gân khiến mọi người có mặt tại bữa sáng đều chết lặng."]'::jsonb, 1, 'The station broadcasts local news every morning before breakfast. → Đài phát thanh này phát sóng tin tức địa phương vào mỗi buổi sáng trước bữa ăn sáng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_73_9', 'en-b2-73', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a short official announcement or report of recent news”?', '["spotlight","bulletin","caption","spokesman"]'::jsonb, 1, 'bulletin (/ˈbʊlətɪn/) → bản tin; thông báo chính thức ngắn gọn về tin tức mới nhất', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_73_10', 'en-b2-73', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A journalist reporting from a particular place or on a subject.”?', '["bulletin","correspondent","subscription","highlight"]'::jsonb, 1, 'correspondent (/ˌkɔːrəˈspɑːndənt/) → phóng viên thường trú; phóng viên chuyên đề', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
