INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_73_18', 'en-b2-73', NULL, 'comprehensive_test', 'reading', NULL, 'Public health pamphlets should use clear language and illustrations to explain preventive measures to a broad audience.', 'Dựa vào câu trên, từ “pamphlet” có nghĩa phù hợp nhất là gì?', '["tờ rơi; sách mỏng thông tin","bình luận trực tiếp, tường thuật diễn biến sự việc","quan tài; linh cữu","vô gia cư"]'::jsonb, 0, 'pamphlet: tờ rơi; sách mỏng thông tin. Dịch cả câu: Các tài liệu tuyên truyền về y tế công cộng nên sử dụng ngôn ngữ rõ ràng và minh họa để giải thích các biện pháp phòng ngừa cho đông đảo khán giả.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_73_19', 'en-b2-73', NULL, 'comprehensive_test', 'reading', NULL, 'Recent research has put urban air pollution in the spotlight, prompting calls for stricter vehicle regulations.', 'Dựa vào câu trên, từ “spotlight” có nghĩa phù hợp nhất là gì?', '["làm phân tâm; làm xao nhãng","thay đổi; biến đổi","gia hạn; làm mới","đèn pha; đèn chiếu điểm"]'::jsonb, 3, 'spotlight: đèn pha; đèn chiếu điểm; sự chú ý của công chúng; tâm điểm chú ý; làm nổi bật; đưa lên làm trọng tâm. Dịch cả câu: Các nghiên cứu gần đây đã đưa vấn đề ô nhiễm không khí đô thị trở thành tâm điểm chú ý, từ đó thúc đẩy những lời kêu gọi siết chặt các quy định về phương tiện giao thông.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_73_20', 'en-b2-73', NULL, 'comprehensive_test', 'reading', NULL, 'Sensational reporting may attract large audiences, but it can distort public understanding of important social issues.', 'Dựa vào câu trên, từ “sensational” có nghĩa phù hợp nhất là gì?', '["phân tích","một cách thỏa đáng; đạt yêu cầu","việc; sự kiện; vấn đề","gây xôn xao; giật gân; rùm beng (gây phấn khích hoặc sốc lớn, đôi khi thông qua sự phóng đại)"]'::jsonb, 3, 'sensational: gây xôn xao; giật gân; rùm beng (gây phấn khích hoặc sốc lớn, đôi khi thông qua sự phóng đại); tuyệt vời; xuất sắc; cực kỳ ấn tượng (cực kỳ ấn tượng hoặc đáng tận hưởng). Dịch cả câu: Các bài báo giật gân có thể thu hút lượng lớn khán giả, nhưng nó có thể bóp méo nhận thức của công chúng về các vấn đề xã hội quan trọng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_73_21', 'en-b2-73', NULL, 'comprehensive_test', 'reading', NULL, 'Careful wording in public health announcements can prevent confusion and encourage people to follow advice.', 'Dựa vào câu trên, từ “wording” có nghĩa phù hợp nhất là gì?', '["một cách thỏa đáng; đạt yêu cầu","cách dùng từ; lời lẽ; văn bản","đi lang thang; lang thang không có mục đích cố định","chải chuốt; chải lông (cho vật nuôi)"]'::jsonb, 1, 'wording: cách dùng từ; lời lẽ; văn bản. Dịch cả câu: Cách chọn từ cẩn thận trong các thông báo y tế công cộng có thể ngăn ngừa sự hiểu lầm và khuyến khích mọi người làm theo lời khuyên.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_73_22', 'en-b2-73', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “chú thích ảnh; phụ đề”', '["factual","caption","praise","independence"]'::jsonb, 1, 'chú thích ảnh; phụ đề → caption (/ˈkæpʃən/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_73_23', 'en-b2-73', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thí sinh; người tham gia thi đấu”', '["contestant","descent","cod","bravery"]'::jsonb, 0, 'thí sinh; người tham gia thi đấu → contestant (/kənˈtestənt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_73_24', 'en-b2-73', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “việc biên tập; công tác hiệu đính; sự cắt dựng (phim ảnh)”', '["editing","claw","deadly","bid"]'::jsonb, 0, 'việc biên tập; công tác hiệu đính; sự cắt dựng (phim ảnh) → editing (/ˈedɪtɪŋ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-74', 'en', 'Bài 74: Đời sống hằng ngày (1) - CEFR B2', 'CEFR B2', 'B2 · Đời sống', '27 từ vựng Tiếng Anh CEFR B2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4074, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_errand', 'en-b2-74', 'errand', '/ˈerənd/', 'B2', 'việc vặt; chuyến đi ngắn để mua, lấy hoặc giao đồ', 'n.', NULL, NULL, 'Thường chỉ việc ra ngoài giải quyết việc nhỏ; thường đi với cụm run errands.', 'I ran an errand before meeting you for lunch.', NULL, 'Tôi đã chạy đi làm chút việc vặt trước khi gặp bạn ăn trưa.', '{"wordId":"errand","ukIpa":"/ˈerənd/","usIpa":"/ˈerənd/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A short trip to buy, collect, or deliver something","vi":"việc vặt; chuyến đi ngắn để mua, lấy hoặc giao đồ"}],"examples":[{"en":"I ran an errand before meeting you for lunch.","vi":"Tôi đã chạy đi làm chút việc vặt trước khi gặp bạn ăn trưa.","audioKind":"ex"},{"en":"Reliable neighbourhood transport helps older residents run errands independently and maintain regular contact with their communities.","vi":"Giao thông công cộng đáng tin cậy trong khu dân cư giúp người cao tuổi tự đi làm việc vặt và duy trì sự gắn kết thường xuyên với cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"run errands","vi":"đi làm việc vặt"},{"en":"send someone on an errand","vi":"sai ai đó đi làm việc vặt"},{"en":"a quick errand","vi":"việc vặt làm nhanh"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ việc ra ngoài giải quyết việc nhỏ; thường đi với cụm run errands.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_syrup', 'en-b2-74', 'syrup', '/ˈsɪrəp/', 'B2', 'xi-rô; nước đường đặc; xi-rô thuốc', 'n.', 'syrupy (adj.)', NULL, 'Thường là danh từ không đếm được; xi-rô ho là cough syrup.', 'She poured a little syrup over her warm pancakes.', NULL, 'Cô ấy rưới một ít xi-rô lên chiếc bánh kếp ấm nóng.', '{"wordId":"syrup","ukIpa":"/ˈsɪrəp/","usIpa":"/ˈsɪrəp/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"a thick sweet liquid made from dissolved sugar","vi":"xi-rô; nước đường đặc"},{"pos":"n.","en":"a sweet thick liquid containing medicine","vi":"xi-rô thuốc"}],"examples":[{"en":"She poured a little syrup over her warm pancakes.","vi":"Cô ấy rưới một ít xi-rô lên chiếc bánh kếp ấm nóng.","audioKind":"ex"},{"en":"Fruit preserved in syrup often contains more added sugar than fresh fruit, which may concern health-conscious consumers.","vi":"Trái cây ngâm xi-rô thường chứa nhiều đường bổ sung hơn trái cây tươi, điều này có thể khiến những người tiêu dùng quan tâm đến sức khỏe lo ngại.","audioKind":"ex2"}],"collocations":[{"en":"maple syrup","vi":"xi-rô cây phong"},{"en":"cough syrup","vi":"xi-rô ho"},{"en":"fruit in syrup","vi":"trái cây ngâm xi-rô"},{"en":"sugar syrup","vi":"nước đường"}],"wordFamily":["syrupy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; xi-rô ho là cough syrup.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_puff', 'en-b2-74', 'puff', '/pʌf/', 'B2', 'luồng (khí, khói, hơi nước); làn (gió nhẹ); thở hồng hộc; thở hổn hển; thổi ra; phả ra; phồng lên', 'n.', NULL, NULL, 'Dùng cụm từ a puff of smoke để chỉ một làn khói; puff cũng có thể chỉ hành động thở hổn hển.', 'A puff of steam escaped from the kettle.', NULL, 'Một làn hơi nước bốc lên từ chiếc ấm đun nước.', '{"wordId":"puff","ukIpa":"/pʌf/","usIpa":"/pʌf/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A small amount of air, smoke, or steam released suddenly.","vi":"luồng (khí, khói, hơi nước); làn (gió nhẹ)"},{"pos":"v.","en":"To breathe quickly and noisily after physical effort.","vi":"thở hồng hộc; thở hổn hển"},{"pos":"v.","en":"To release air or smoke, or swell with air.","vi":"thổi ra; phả ra; phồng lên"}],"examples":[{"en":"A puff of steam escaped from the kettle.","vi":"Một làn hơi nước bốc lên từ chiếc ấm đun nước.","audioKind":"ex"},{"en":"Older buses release puffs of dark smoke, highlighting the need for cleaner public transport in cities.","vi":"Các xe buýt cũ xả ra những làn khói đen kịt, làm nổi bật sự cần thiết phải có phương tiện giao thông công cộng sạch sẽ hơn ở các đô thị.","audioKind":"ex2"}],"collocations":[{"en":"a puff of smoke","vi":"một làn khói"},{"en":"huff and puff","vi":"thở hổn hển mệt nhọc"},{"en":"puff up","vi":"phồng lên; sưng phồng"},{"en":"puff out your cheeks","vi":"phồng má"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dùng cụm từ a puff of smoke để chỉ một làn khói; puff cũng có thể chỉ hành động thở hổn hển.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cosmetics', 'en-b2-74', 'cosmetics', '/kɑːzˈmetɪks/', 'B2', 'mỹ phẩm; đồ trang điểm', 'n.', 'cosmetic (adj.), cosmetically (adv.)', NULL, 'Thường dùng ở dạng số nhiều cosmetics; tính từ cosmetic cũng có nghĩa là thuộc về bề ngoài.', 'She keeps her cosmetics in a small bathroom drawer.', NULL, 'Cô ấy để mỹ phẩm trong một ngăn kéo nhỏ ở phòng tắm.', '{"wordId":"cosmetics","ukIpa":"/kɒzˈmetɪks/","usIpa":"/kɑːzˈmetɪks/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"Products applied to the face or body to improve appearance.","vi":"mỹ phẩm; đồ trang điểm"}],"examples":[{"en":"She keeps her cosmetics in a small bathroom drawer.","vi":"Cô ấy để mỹ phẩm trong một ngăn kéo nhỏ ở phòng tắm.","audioKind":"ex"},{"en":"Consumers increasingly expect cosmetics manufacturers to disclose ingredients clearly and reduce unnecessary packaging to limit environmental damage.","vi":"Người tiêu dùng ngày càng kỳ vọng các nhà sản xuất mỹ phẩm công khai minh bạch các thành phần và giảm thiểu bao bì không cần thiết để hạn chế tác hại môi trường.","audioKind":"ex2"}],"collocations":[{"en":"cosmetics industry","vi":"ngành công nghiệp mỹ phẩm"},{"en":"cosmetics manufacturer","vi":"nhà sản xuất mỹ phẩm"},{"en":"buy cosmetics","vi":"mua mỹ phẩm"}],"wordFamily":["cosmetic (adj.)","cosmetically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng ở dạng số nhiều cosmetics; tính từ cosmetic cũng có nghĩa là thuộc về bề ngoài.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_decent', 'en-b2-74', 'decent', '/ˈdiːsənt/', 'B2', 'tử tế; kha khá; tươm tất; đáng hài lòng; đàng hoàng; lịch sự; đúng mực', 'adj.', 'decency (n.), decently (adv.), indecent (adj.)', 'Đồng nghĩa: satisfactory, respectable · Trái nghĩa: indecent', 'Khi nói về chất lượng, decent mang nghĩa là "tạm ổn, khá tốt", không có nghĩa là "tuyệt vời".', 'We finally found a decent flat near the station.', NULL, 'Cuối cùng chúng tôi cũng tìm được một căn hộ tươm tất gần nhà ga.', '{"wordId":"decent","ukIpa":"/ˈdiːsənt/","usIpa":"/ˈdiːsənt/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"of a satisfactory or reasonably good standard","vi":"tử tế; kha khá; tươm tất; đáng hài lòng"},{"pos":"adj.","en":"honest, kind, or socially acceptable","vi":"đàng hoàng; lịch sự; đúng mực"}],"examples":[{"en":"We finally found a decent flat near the station.","vi":"Cuối cùng chúng tôi cũng tìm được một căn hộ tươm tất gần nhà ga.","audioKind":"ex"},{"en":"Every worker should earn enough to afford decent housing and meet their basic needs.","vi":"Mỗi người lao động đều phải kiếm đủ tiền để chi trả cho nhà ở đàng hoàng và đáp ứng các nhu cầu cơ bản của họ.","audioKind":"ex2"}],"collocations":[{"en":"decent housing","vi":"nơi ở đàng hoàng"},{"en":"a decent salary","vi":"mức lương khá"},{"en":"a decent person","vi":"một con người đàng hoàng"}],"wordFamily":["decency (n.)","decently (adv.)","indecent (adj.)"],"synonyms":["satisfactory","respectable"],"antonyms":["indecent"],"tipVi":"Khi nói về chất lượng, decent mang nghĩa là \"tạm ổn, khá tốt\", không có nghĩa là \"tuyệt vời\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bouquet', 'en-b2-74', 'bouquet', '/buˈkeɪ/', 'B2', 'bó hoa; hương thơm của rượu vang', 'n.', NULL, NULL, 'Chữ t ở cuối không được phát âm; một bó hoa diễn đạt là a bouquet of flowers.', 'She brought a bright bouquet to her grandmother''s birthday dinner.', NULL, 'Cô ấy mang theo một bó hoa rực rỡ đến bữa tối sinh nhật của người bà.', '{"wordId":"bouquet","ukIpa":"/buˈkeɪ/","usIpa":"/buˈkeɪ/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A group of flowers arranged together, usually as a gift.","vi":"bó hoa"},{"pos":"n.","en":"The characteristic pleasant smell of a wine.","vi":"hương thơm của rượu vang"}],"examples":[{"en":"She brought a bright bouquet to her grandmother''s birthday dinner.","vi":"Cô ấy mang theo một bó hoa rực rỡ đến bữa tối sinh nhật của người bà.","audioKind":"ex"},{"en":"Choosing a bouquet of locally grown flowers can reduce the environmental impact associated with long-distance transport.","vi":"Việc lựa chọn một bó hoa được trồng tại địa phương có thể làm giảm tác động môi trường liên quan đến việc vận chuyển đường dài.","audioKind":"ex2"}],"collocations":[{"en":"a bouquet of flowers","vi":"một bó hoa"},{"en":"bridal bouquet","vi":"bó hoa cô dâu"},{"en":"a bouquet of roses","vi":"một bó hoa hồng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chữ t ở cuối không được phát âm; một bó hoa diễn đạt là a bouquet of flowers.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_transparent', 'en-b2-74', 'transparent', '/trænsˈperənt/', 'B2', 'trong suốt; minh bạch; công khai; rõ mồn một; dễ nhận ra', 'adj.', 'transparency (n.), transparently (adv.)', 'Đồng nghĩa: clear, see-through · Trái nghĩa: opaque', 'transparent nhấn mạnh việc nhìn xuyên qua rõ ràng; translucent chỉ việc truyền ánh sáng nhưng không nhìn rõ vật bên kia.', 'She keeps her buttons in a transparent plastic box.', NULL, 'Cô ấy cất các nút áo của mình trong một chiếc hộp nhựa trong suốt.', '{"wordId":"transparent","ukIpa":"/trænsˈpærənt/","usIpa":"/trænsˈperənt/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Allowing light through so objects behind can be seen clearly.","vi":"trong suốt"},{"pos":"adj.","en":"Open and clear about decisions, actions, or methods.","vi":"minh bạch; công khai"},{"pos":"adj.","en":"Easy to recognise or understand, especially as false.","vi":"rõ mồn một; dễ nhận ra"}],"examples":[{"en":"She keeps her buttons in a transparent plastic box.","vi":"Cô ấy cất các nút áo của mình trong một chiếc hộp nhựa trong suốt.","audioKind":"ex"},{"en":"Public institutions need transparent recruitment procedures to ensure fairness and maintain the trust of local communities.","vi":"Các cơ quan công quyền cần có quy trình tuyển dụng minh bạch để đảm bảo công bằng và duy trì lòng tin của cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"transparent glass","vi":"thủy tinh trong suốt"},{"en":"transparent process","vi":"quy trình minh bạch"},{"en":"transparent excuse","vi":"lời bào chữa dễ dàng nhìn thấu"}],"wordFamily":["transparency (n.)","transparently (adv.)"],"synonyms":["clear","see-through"],"antonyms":["opaque"],"tipVi":"transparent nhấn mạnh việc nhìn xuyên qua rõ ràng; translucent chỉ việc truyền ánh sáng nhưng không nhìn rõ vật bên kia.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_handful', 'en-b2-74', 'handful', '/ˈhændfʊl/', 'B2', 'một nắm; một vốc; một số ít; một nhúm (người hoặc vật); người hoặc vật khó quản lý; chuyện rắc rối', 'n.', 'hand (n.)', NULL, 'a handful of có thể đi với danh từ không đếm được hoặc danh từ đếm được số nhiều.', 'He sprinkled a handful of nuts over his breakfast.', NULL, 'Anh ấy rắc một nắm hạt lên bữa sáng của mình.', '{"wordId":"handful","ukIpa":"/ˈhændfʊl/","usIpa":"/ˈhændfʊl/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"An amount that can be held in one hand.","vi":"một nắm; một vốc"},{"pos":"n.","en":"A small number of people or things.","vi":"một số ít; một nhúm (người hoặc vật)"},{"pos":"n.","en":"Someone or something that is difficult to manage.","vi":"người hoặc vật khó quản lý; chuyện rắc rối"}],"examples":[{"en":"He sprinkled a handful of nuts over his breakfast.","vi":"Anh ấy rắc một nắm hạt lên bữa sáng của mình.","audioKind":"ex"},{"en":"Only a handful of rural communities have reliable public transport, limiting residents'' access to employment and healthcare.","vi":"Chỉ có một số ít cộng đồng nông thôn có giao thông công cộng đáng tin cậy, điều này hạn chế khả năng tiếp cận việc làm và chăm sóc y tế của người dân.","audioKind":"ex2"}],"collocations":[{"en":"a handful of rice","vi":"một nắm gạo"},{"en":"a handful of people","vi":"một số ít người"},{"en":"be a handful","vi":"rất khó bảo; khó kiểm soát"}],"wordFamily":["hand (n.)"],"synonyms":[],"antonyms":[],"tipVi":"a handful of có thể đi với danh từ không đếm được hoặc danh từ đếm được số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_drip', 'en-b2-74', 'drip', '/drɪp/', 'B2', 'chảy nhỏ giọt; làm nhỏ giọt; giọt (chất lỏng); tiếng giọt nước rơi; bình truyền dịch', 'v.', 'dripping (adj.)', NULL, 'Tiếng Anh Anh dùng on a drip để chỉ việc đang truyền dịch.', 'Water dripped from my umbrella onto the kitchen floor.', NULL, 'Nước từ chiếc ô của tôi nhỏ giọt xuống sàn nhà bếp.', '{"wordId":"drip","ukIpa":"/drɪp/","usIpa":"/drɪp/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To fall or let liquid fall in separate drops.","vi":"chảy nhỏ giọt; làm nhỏ giọt"},{"pos":"n.","en":"A small drop of liquid, or the sound it makes.","vi":"giọt (chất lỏng); tiếng giọt nước rơi"},{"pos":"n.","en":"Equipment that slowly delivers liquid into a patient''s vein.","vi":"bình truyền dịch"}],"examples":[{"en":"Water dripped from my umbrella onto the kitchen floor.","vi":"Nước từ chiếc ô của tôi nhỏ giọt xuống sàn nhà bếp.","audioKind":"ex"},{"en":"Leaking pipes can drip continuously, wasting substantial amounts of water in cities with ageing infrastructure.","vi":"Các đường ống bị rò rỉ có thể nhỏ giọt liên tục, làm lãng phí lượng lớn nước ở các thành phố có cơ sở hạ tầng xuống cấp.","audioKind":"ex2"}],"collocations":[{"en":"drip from","vi":"chảy nhỏ giọt từ"},{"en":"a dripping tap","vi":"vòi nước đang nhỏ giọt"},{"en":"put someone on a drip","vi":"cho ai đó đi truyền dịch"}],"wordFamily":["dripping (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Tiếng Anh Anh dùng on a drip để chỉ việc đang truyền dịch.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wink', 'en-b2-74', 'wink', '/wɪŋk/', 'B2', 'nháy mắt ra hiệu; cái nháy mắt ra hiệu', 'v.', NULL, NULL, 'wink thường chỉ việc nháy một bên mắt để ra hiệu; blink chỉ việc chớp mắt tự nhiên.', 'My sister winked at me across the dinner table.', NULL, 'Chị tôi nháy mắt với tôi qua bàn ăn tối.', '{"wordId":"wink","ukIpa":"/wɪŋk/","usIpa":"/wɪŋk/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to close and open one eye quickly as a signal","vi":"nháy mắt ra hiệu"},{"pos":"n.","en":"a quick closing and opening of one eye as a signal","vi":"cái nháy mắt ra hiệu"}],"examples":[{"en":"My sister winked at me across the dinner table.","vi":"Chị tôi nháy mắt với tôi qua bàn ăn tối.","audioKind":"ex"},{"en":"A friendly wink may communicate shared understanding, although its meaning can vary considerably across different cultures.","vi":"Một cái nháy mắt thân thiện có thể truyền đạt sự thấu hiểu ngầm, dù ý nghĩa của nó có thể thay đổi đáng kể giữa các nền văn hóa khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"wink at someone","vi":"nháy mắt với ai"},{"en":"give someone a wink","vi":"nháy mắt ra hiệu cho ai"},{"en":"not sleep a wink","vi":"không chợp mắt một chút nào"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"wink thường chỉ việc nháy một bên mắt để ra hiệu; blink chỉ việc chớp mắt tự nhiên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_leak', 'en-b2-74', 'leak', '/liːk/', 'B2', 'sự rò rỉ, chỗ rò rỉ; rò rỉ, thoát ra (chất lỏng hoặc khí); làm rò rỉ, để lộ (thông tin mật không được phép)', 'n.', 'leakage (n.), leaky (adj.)', NULL, 'Từ "leak" có thể dùng làm danh từ hoặc động từ, đồng thời có thể chỉ sự rò rỉ thông tin mật.', 'A leak under the sink soaked all our cleaning cloths.', NULL, 'Vết rò rỉ dưới bồn rửa chén đã làm ướt sũng tất cả khăn lau của chúng tôi.', '{"wordId":"leak","ukIpa":"/liːk/","usIpa":"/liːk/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"An escape of liquid or gas, or an opening allowing it.","vi":"sự rò rỉ, chỗ rò rỉ"},{"pos":"v.","en":"To let liquid or gas escape through a hole or crack.","vi":"rò rỉ, thoát ra (chất lỏng hoặc khí)"},{"pos":"v.","en":"To reveal private information without permission.","vi":"làm rò rỉ, để lộ (thông tin mật không được phép)"}],"examples":[{"en":"A leak under the sink soaked all our cleaning cloths.","vi":"Vết rò rỉ dưới bồn rửa chén đã làm ướt sũng tất cả khăn lau của chúng tôi.","audioKind":"ex"},{"en":"Water companies should repair leaks promptly to conserve resources and reduce unnecessary pressure on local supplies.","vi":"Các công ty cấp nước nên nhanh chóng sửa chữa các chỗ rò rỉ để tiết kiệm tài nguyên và giảm áp lực không cần thiết lên nguồn cung cấp địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a gas leak","vi":"rò rỉ khí ga"},{"en":"repair a leak","vi":"sửa chữa chỗ rò rỉ"},{"en":"leak confidential information","vi":"làm lộ thông tin cơ mật"},{"en":"a leaking pipe","vi":"đường ống đang bị rò rỉ"}],"wordFamily":["leakage (n.)","leaky (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ \"leak\" có thể dùng làm danh từ hoặc động từ, đồng thời có thể chỉ sự rò rỉ thông tin mật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_blade', 'en-b2-74', 'blade', '/bleɪd/', 'B2', 'lưỡi (dao, kiếm, công cụ cắt); cánh (quạt, tuabin, mái chèo); lá (cỏ, lúa)', 'n.', NULL, NULL, '"blade" chỉ phần dùng để cắt của một dụng cụ, trong khi "knife" chỉ toàn bộ con dao.', 'The knife''s blade was too blunt to slice tomatoes.', NULL, 'Lưỡi dao quá cùn nên không thể thái được cà chua.', '{"wordId":"blade","ukIpa":"/bleɪd/","usIpa":"/bleɪd/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"The flat cutting part of a knife or tool.","vi":"lưỡi (dao, kiếm, công cụ cắt)"},{"pos":"n.","en":"A flat part that rotates to move air or water.","vi":"cánh (quạt, tuabin, mái chèo)"},{"pos":"n.","en":"A long narrow leaf of grass.","vi":"lá (cỏ, lúa)"}],"examples":[{"en":"The knife''s blade was too blunt to slice tomatoes.","vi":"Lưỡi dao quá cùn nên không thể thái được cà chua.","audioKind":"ex"},{"en":"Each blade of a wind turbine is designed to capture energy efficiently from moving air.","vi":"Mỗi cánh quạt của tua-bin gió được thiết kế để thu giữ năng lượng hiệu quả từ luồng không khí chuyển động.","audioKind":"ex2"}],"collocations":[{"en":"a sharp blade","vi":"lưỡi dao bén"},{"en":"a razor blade","vi":"lưỡi dao cạo"},{"en":"a turbine blade","vi":"cánh tua-bin"},{"en":"a blade of grass","vi":"một ngọn cỏ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"\"blade\" chỉ phần dùng để cắt của một dụng cụ, trong khi \"knife\" chỉ toàn bộ con dao.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stubborn', 'en-b2-74', 'stubborn', '/ˈstʌbərn/', 'B2', 'bướng bỉnh, cứng đầu, ngoan cố; khó loại bỏ, khó điều trị, dai dẳng', 'adj.', 'stubbornly (adv.), stubbornness (n.)', 'Đồng nghĩa: obstinate, inflexible · Trái nghĩa: flexible', 'Khi dùng miêu tả con người thường mang nghĩa tiêu cực; ngoài ra cũng có thể dùng cho vết bẩn khó chùi hoặc bệnh lâu khỏi.', 'My stubborn brother refused to wear a coat outside.', NULL, 'Người anh bướng bỉnh của tôi nhất quyết không chịu mặc áo khoác khi ra ngoài.', '{"wordId":"stubborn","ukIpa":"/ˈstʌbən/","usIpa":"/ˈstʌbərn/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Unwilling to change your opinion or behaviour.","vi":"bướng bỉnh, cứng đầu, ngoan cố"},{"pos":"adj.","en":"Difficult to remove, treat, or deal with.","vi":"khó loại bỏ, khó điều trị, dai dẳng"}],"examples":[{"en":"My stubborn brother refused to wear a coat outside.","vi":"Người anh bướng bỉnh của tôi nhất quyết không chịu mặc áo khoác khi ra ngoài.","audioKind":"ex"},{"en":"Stubborn resistance to change can prevent organisations from adopting more efficient and environmentally responsible practices.","vi":"Sự kháng cự ngoan cố trước sự thay đổi có thể khiến các tổ chức không thể áp dụng các phương pháp hiệu quả và có trách nhiệm với môi trường hơn.","audioKind":"ex2"}],"collocations":[{"en":"stubborn refusal","vi":"sự từ chối cương quyết"},{"en":"stubborn resistance","vi":"sự kháng cự ngoan cố"},{"en":"stubborn stain","vi":"vết bẩn cứng đầu"}],"wordFamily":["stubbornly (adv.)","stubbornness (n.)"],"synonyms":["obstinate","inflexible"],"antonyms":["flexible"],"tipVi":"Khi dùng miêu tả con người thường mang nghĩa tiêu cực; ngoài ra cũng có thể dùng cho vết bẩn khó chùi hoặc bệnh lâu khỏi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_buck', 'en-b2-74', 'buck', '/bʌk/', 'B2', 'đồng đô-la, đồng bạc (từ thông tục); con đực (hươu, nai, thỏ và một số loài động vật khác); chồm lên, nhảy cẫng lên (ngựa)', 'n.', NULL, 'Đồng nghĩa: dollar', 'Khi chỉ tiền đô-la, từ này mang sắc thái văn phong khẩu ngữ; cụm từ "pass the buck" có nghĩa là đùn đẩy trách nhiệm.', 'I bought this warm scarf for just five bucks.', NULL, 'Tôi đã mua chiếc khăn choàng cổ ấm áp này chỉ với năm đô-la.', '{"wordId":"buck","ukIpa":"/bʌk/","usIpa":"/bʌk/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"An informal word for a dollar.","vi":"đồng đô-la, đồng bạc (từ thông tục)"},{"pos":"n.","en":"A male deer, rabbit, or certain other animals.","vi":"con đực (hươu, nai, thỏ và một số loài động vật khác)"},{"pos":"v.","en":"For a horse to jump with its back arched.","vi":"chồm lên, nhảy cẫng lên (ngựa)"}],"examples":[{"en":"I bought this warm scarf for just five bucks.","vi":"Tôi đã mua chiếc khăn choàng cổ ấm áp này chỉ với năm đô-la.","audioKind":"ex"},{"en":"Although shoppers may save a few bucks online, local retailers often provide more personalised advice and support.","vi":"Mặc dù người mua sắm có thể tiết kiệm được vài đồng khi mua hàng trực tuyến, nhưng các nhà bán lẻ địa phương thường cung cấp lời khuyên và sự hỗ trợ tận tình hơn.","audioKind":"ex2"}],"collocations":[{"en":"a few bucks","vi":"vài đô-la"},{"en":"make a quick buck","vi":"kiếm tiền nhanh chóng"},{"en":"pass the buck","vi":"đẩy trách nhiệm cho người khác"},{"en":"buck the trend","vi":"lội ngược dòng xu thế"}],"wordFamily":[],"synonyms":["dollar"],"antonyms":[],"tipVi":"Khi chỉ tiền đô-la, từ này mang sắc thái văn phong khẩu ngữ; cụm từ \"pass the buck\" có nghĩa là đùn đẩy trách nhiệm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_beneath', 'en-b2-74', 'beneath', '/bɪˈniːθ/', 'B2', 'ở dưới; phía dưới; có hại cho phẩm giá; không xứng tầm; ở phía dưới', 'prep.', NULL, 'Đồng nghĩa: below, under · Trái nghĩa: above', 'trang trọng hơn under; beneath cũng có thể diễn tả việc không xứng với phẩm giá.', 'Our cat slept beneath the table during dinner.', NULL, 'Con mèo của chúng tôi ngủ dưới gầm bàn trong bữa tối.', '{"wordId":"beneath","ukIpa":"/bɪˈniːθ/","usIpa":"/bɪˈniːθ/","cefr":"B2","topic":"daily","senses":[{"pos":"prep.","en":"In or to a position directly below something.","vi":"ở dưới; phía dưới"},{"pos":"prep.","en":"Considered too low in status or value for someone.","vi":"có hại cho phẩm giá; không xứng tầm"},{"pos":"adv.","en":"In or to a lower position.","vi":"ở phía dưới"}],"examples":[{"en":"Our cat slept beneath the table during dinner.","vi":"Con mèo của chúng tôi ngủ dưới gầm bàn trong bữa tối.","audioKind":"ex"},{"en":"Beneath the city''s busy streets, an extensive railway network allows residents to travel efficiently.","vi":"Bên dưới những con đường tấp nập của thành phố, một hệ thống đường sắt rộng lớn giúp người dân di chuyển hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"beneath the surface","vi":"dưới bề mặt"},{"en":"beneath your dignity","vi":"hạ mình; có hại cho lòng tự trọng"},{"en":"beneath the waves","vi":"dưới những con sóng"}],"wordFamily":[],"synonyms":["below","under"],"antonyms":["above"],"tipVi":"trang trọng hơn under; beneath cũng có thể diễn tả việc không xứng với phẩm giá.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_overload', 'en-b2-74', 'overload', '/ˌoʊvərˈloʊd/', 'B2', 'làm quá tải; chồng chất gánh nặng; làm quá tải mạch điện', 'v.', 'load (v.), overloaded (adj.)', 'Đồng nghĩa: overburden', 'thường dùng cấu trúc overload someone with something.', 'Don''t overload your backpack with things you won''t use.', NULL, 'Đừng nhồi nhét quá nhiều thứ không dùng đến vào ba lô của bạn.', '{"wordId":"overload","ukIpa":"/ˌəʊvəˈləʊd/","usIpa":"/ˌoʊvərˈloʊd/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To put more weight or work on something than manageable.","vi":"làm quá tải; chồng chất gánh nặng"},{"pos":"v.","en":"To make an electrical circuit carry more current than safe.","vi":"làm quá tải mạch điện"}],"examples":[{"en":"Don''t overload your backpack with things you won''t use.","vi":"Đừng nhồi nhét quá nhiều thứ không dùng đến vào ba lô của bạn.","audioKind":"ex"},{"en":"Schools should avoid overloading students with homework, as excessive pressure can undermine motivation and wellbeing.","vi":"Các trường học nên tránh giao quá nhiều bài tập cho học sinh, vì áp lực quá mức có thể làm giảm động lực và tổn hại sức khỏe tinh thần.","audioKind":"ex2"}],"collocations":[{"en":"overload a vehicle","vi":"làm quá tải phương tiện"},{"en":"overload someone with work","vi":"bắt ai đó ôm đồm quá nhiều việc"},{"en":"overload a circuit","vi":"làm quá tải mạch điện"}],"wordFamily":["load (v.)","overloaded (adj.)"],"synonyms":["overburden"],"antonyms":[],"tipVi":"thường dùng cấu trúc overload someone with something.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bear', 'en-b2-74', 'bear', '/ber/', 'B2', 'chịu đựng; gánh vác; con gấu; mang; có', 'v.', 'bearable (adj.), unbearable (adj.), unbearably (adv.)', 'Đồng nghĩa: endure, tolerate', 'quá khứ là bore; phân từ quá khứ thường là borne; từ sinh ra dùng born.', 'I can''t bear the noise of that old fan.', NULL, 'Tôi không thể chịu nổi tiếng ồn của chiếc quạt cũ đó.', '{"wordId":"bear","ukIpa":"/beə/","usIpa":"/ber/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to tolerate something unpleasant or carry a heavy responsibility","vi":"chịu đựng; gánh vác"},{"pos":"n.","en":"a large, heavily built mammal with thick fur","vi":"con gấu"},{"pos":"v.","en":"to have or display a particular feature or mark","vi":"mang; có"}],"examples":[{"en":"I can''t bear the noise of that old fan.","vi":"Tôi không thể chịu nổi tiếng ồn của chiếc quạt cũ đó.","audioKind":"ex"},{"en":"Low-income households often bear the greatest burden when the cost of essential goods rises.","vi":"Các hộ gia đình thu nhập thấp thường gánh chịu gánh nặng lớn nhất khi giá cả hàng hóa thiết yếu tăng lên.","audioKind":"ex2"}],"collocations":[{"en":"can''t bear","vi":"không thể chịu nổi"},{"en":"bear responsibility","vi":"chịu trách nhiệm"},{"en":"bear in mind","vi":"ghi nhớ"},{"en":"bear a resemblance to","vi":"có điểm giống với"}],"wordFamily":["bearable (adj.)","unbearable (adj.)","unbearably (adv.)"],"synonyms":["endure","tolerate"],"antonyms":[],"tipVi":"quá khứ là bore; phân từ quá khứ thường là borne; từ sinh ra dùng born.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_modest', 'en-b2-74', 'modest', '/ˈmɑːdɪst/', 'B2', 'khiêm tốn; vừa phải; kín đáo', 'adj.', 'modesty (n.), modestly (adv.), immodest (adj.)', 'Đồng nghĩa: humble · Trái nghĩa: arrogant', 'khi nói về người thường chỉ sự khiêm tốn; khi nói về số lượng thường chỉ mức độ vừa phải, không lớn.', 'Despite winning the race, she remained modest about her success.', NULL, 'Mặc dù chiến thắng cuộc đua, cô ấy vẫn giữ sự khiêm tốn về thành công của mình.', '{"wordId":"modest","ukIpa":"/ˈmɒdɪst/","usIpa":"/ˈmɑːdɪst/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"not boasting about your abilities or achievements","vi":"khiêm tốn"},{"pos":"adj.","en":"not large in size, amount, or cost","vi":"vừa phải; khiêm tốn"},{"pos":"adj.","en":"wearing clothes that do not reveal much of the body","vi":"kín đáo"}],"examples":[{"en":"Despite winning the race, she remained modest about her success.","vi":"Mặc dù chiến thắng cuộc đua, cô ấy vẫn giữ sự khiêm tốn về thành công của mình.","audioKind":"ex"},{"en":"Even a modest increase in public transport funding could improve services in rural communities.","vi":"Ngay cả một sự gia tăng nhỏ trong ngân sách giao thông công cộng cũng có thể cải thiện các dịch vụ ở vùng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"modest about one''s achievements","vi":"khiêm tốn về thành tựu của bản thân"},{"en":"a modest increase","vi":"sự gia tăng khiêm tốn"},{"en":"a modest income","vi":"thu nhập khiêm tốn"}],"wordFamily":["modesty (n.)","modestly (adv.)","immodest (adj.)"],"synonyms":["humble"],"antonyms":["arrogant"],"tipVi":"khi nói về người thường chỉ sự khiêm tốn; khi nói về số lượng thường chỉ mức độ vừa phải, không lớn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_houseboat', 'en-b2-74', 'houseboat', '/ˈhaʊsboʊt/', 'B2', 'nhà thuyền; thuyền cư trú', 'n.', NULL, NULL, 'Chỉ thuyền được thiết kế để ở, không giống như du thuyền (yacht) dùng cho giải trí.', 'We spent the weekend on a houseboat beside the riverbank.', NULL, 'Chúng tôi đã trải qua cuối tuần trên một chiếc nhà thuyền neo đậu bên bờ sông.', '{"wordId":"houseboat","ukIpa":"/ˈhaʊsbəʊt/","usIpa":"/ˈhaʊsboʊt/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A boat designed or adapted for people to live in.","vi":"nhà thuyền; thuyền cư trú"}],"examples":[{"en":"We spent the weekend on a houseboat beside the riverbank.","vi":"Chúng tôi đã trải qua cuối tuần trên một chiếc nhà thuyền neo đậu bên bờ sông.","audioKind":"ex"},{"en":"Living on a houseboat may offer affordable accommodation, although maintenance costs and mooring fees can be substantial.","vi":"Sinh sống trên một chiếc nhà thuyền có thể giúp tiết kiệm chi phí nhà ở, mặc dù chi phí bảo trì và phí neo đậu có thể khá lớn.","audioKind":"ex2"}],"collocations":[{"en":"live on a houseboat","vi":"sống trên nhà thuyền"},{"en":"rent a houseboat","vi":"thuê nhà thuyền"},{"en":"houseboat holiday","vi":"kỳ nghỉ trên nhà thuyền"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ thuyền được thiết kế để ở, không giống như du thuyền (yacht) dùng cho giải trí.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_steady', 'en-b2-74', 'steady', '/ˈstedi/', 'B2', 'ổn định; đều đặn; vững chắc; bình tĩnh; điềm đạm; làm cho ổn định; giữ cho vững', 'adj.', 'steadily (adv.), steadiness (n.), unsteady (adj.)', 'Đồng nghĩa: stable, constant · Trái nghĩa: unsteady, erratic', 'Steady là tính từ; bổ nghĩa cho động từ thường dùng steadily.', 'Keep a steady pace as you climb the hill.', NULL, 'Giữ nhịp bước đều đặn khi bạn leo đồi.', '{"wordId":"steady","ukIpa":"/ˈstedi/","usIpa":"/ˈstedi/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Continuing regularly without sudden changes.","vi":"ổn định; đều đặn"},{"pos":"adj.","en":"Firmly controlled, balanced, or calm.","vi":"vững chắc; bình tĩnh; điềm đạm"},{"pos":"v.","en":"Make something stable or bring it under control.","vi":"làm cho ổn định; giữ cho vững"}],"examples":[{"en":"Keep a steady pace as you climb the hill.","vi":"Giữ nhịp bước đều đặn khi bạn leo đồi.","audioKind":"ex"},{"en":"Steady investment in public transport can improve urban mobility and reduce traffic congestion over time.","vi":"Đầu tư ổn định vào giao thông công cộng có thể cải thiện việc đi lại đô thị và giảm ùn tắc giao thông theo thời gian.","audioKind":"ex2"}],"collocations":[{"en":"steady growth","vi":"tăng trưởng ổn định"},{"en":"a steady pace","vi":"nhịp độ đều đặn"},{"en":"a steady income","vi":"thu nhập ổn định"},{"en":"steady yourself","vi":"giữ vững tâm lý"}],"wordFamily":["steadily (adv.)","steadiness (n.)","unsteady (adj.)"],"synonyms":["stable","constant"],"antonyms":["unsteady","erratic"],"tipVi":"Steady là tính từ; bổ nghĩa cho động từ thường dùng steadily.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_warranty', 'en-b2-74', 'warranty', '/ˈwɔːrənti/', 'B2', 'bảo hành; giấy bảo hành', 'n.', NULL, 'Đồng nghĩa: guarantee', 'Dùng under warranty để chỉ trạng thái còn bảo hành, không dùng in warranty.', 'The shop repaired my camera because it was under warranty.', NULL, 'Cửa hàng đã sửa chiếc máy ảnh cho tôi vì nó vẫn còn trong thời gian bảo hành.', '{"wordId":"warranty","ukIpa":"/ˈwɒrənti/","usIpa":"/ˈwɔːrənti/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A written promise to repair or replace faulty goods within conditions.","vi":"bảo hành; giấy bảo hành"}],"examples":[{"en":"The shop repaired my camera because it was under warranty.","vi":"Cửa hàng đã sửa chiếc máy ảnh cho tôi vì nó vẫn còn trong thời gian bảo hành.","audioKind":"ex"},{"en":"A longer warranty may encourage consumers to choose durable appliances rather than cheaper products that require frequent replacement.","vi":"Thời gian bảo hành dài hơn có thể khuyến khích người tiêu dùng lựa chọn các thiết bị bền bỉ thay vì các sản phẩm rẻ tiền nhưng phải thay thế thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"under warranty","vi":"đang trong thời gian bảo hành"},{"en":"an extended warranty","vi":"bảo hành mở rộng"},{"en":"a manufacturer''s warranty","vi":"bảo hành từ nhà sản xuất"},{"en":"void the warranty","vi":"làm mất hiệu lực bảo hành"}],"wordFamily":[],"synonyms":["guarantee"],"antonyms":[],"tipVi":"Dùng under warranty để chỉ trạng thái còn bảo hành, không dùng in warranty.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tiptoe', 'en-b2-74', 'tiptoe', '/ˈtɪptoʊ/', 'B2', 'đi nhón chân, đi rón rén', 'v.', NULL, NULL, 'Động từ quá khứ là tiptoed; on tiptoe biểu thị trạng thái nhón chân.', 'She tiptoed past the bedroom to avoid waking her brother.', NULL, 'Cô ấy rón rén bước qua phòng ngủ để tránh đánh thức em trai.', '{"wordId":"tiptoe","ukIpa":"/ˈtɪptəʊ/","usIpa":"/ˈtɪptoʊ/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"Walk quietly on your toes with your heels raised.","vi":"đi nhón chân, đi rón rén"}],"examples":[{"en":"She tiptoed past the bedroom to avoid waking her brother.","vi":"Cô ấy rón rén bước qua phòng ngủ để tránh đánh thức em trai.","audioKind":"ex"},{"en":"Visitors often tiptoe through historic buildings, although quiet conversation is usually permitted in these spaces.","vi":"Du khách thường rón rén bước đi trong các công trình kiến trúc lịch sử, mặc dù việc trò chuyện khẽ thường được cho phép ở những không gian này.","audioKind":"ex2"}],"collocations":[{"en":"tiptoe past","vi":"rón rén bước qua"},{"en":"tiptoe around","vi":"đi lại rón rén"},{"en":"on tiptoe","vi":"nhón chân"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Động từ quá khứ là tiptoed; on tiptoe biểu thị trạng thái nhón chân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rear', 'en-b2-74', 'rear', '/rɪr/', 'B2', 'phần sau; phía sau; ở phía sau; nuôi dưỡng; nuôi nấng; chăn nuôi', 'n.', 'rearing (n.)', 'Đồng nghĩa: back, raise · Trái nghĩa: front', 'at the rear of chỉ vị trí; rear animals chỉ việc chăn nuôi.', 'We loaded the bags into the rear of the van.', NULL, 'Chúng tôi chất các bao đồ lên phần phía sau của chiếc xe van.', '{"wordId":"rear","ukIpa":"/rɪə/","usIpa":"/rɪr/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"The back part of something.","vi":"phần sau; phía sau"},{"pos":"adj.","en":"Located at the back of something.","vi":"ở phía sau"},{"pos":"v.","en":"To care for children or animals until they grow up.","vi":"nuôi dưỡng; nuôi nấng; chăn nuôi"}],"examples":[{"en":"We loaded the bags into the rear of the van.","vi":"Chúng tôi chất các bao đồ lên phần phía sau của chiếc xe van.","audioKind":"ex"},{"en":"Farmers who rear animals outdoors must provide adequate shelter and maintain high standards of animal welfare.","vi":"Những người nông dân chăn nuôi động vật ngoài trời phải cung cấp đủ nơi trú ẩn và duy trì các tiêu chuẩn phúc lợi động vật cao.","audioKind":"ex2"}],"collocations":[{"en":"at the rear of","vi":"ở phía sau của"},{"en":"rear window","vi":"cửa sổ sau"},{"en":"rear children","vi":"nuôi dạy con cái"},{"en":"rear cattle","vi":"nuôi bò"}],"wordFamily":["rearing (n.)"],"synonyms":["back","raise"],"antonyms":["front"],"tipVi":"at the rear of chỉ vị trí; rear animals chỉ việc chăn nuôi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_seal', 'en-b2-74', 'seal', '/siːl/', 'B2', 'niêm phong; bịt kín; dán kín; lớp niêm phong; chỗ bịt kín; con hải cẩu', 'v.', 'sealed (adj.), sealer (n.), unseal (v.)', 'Trái nghĩa: unseal', 'Khi là động từ, từ này nhấn mạnh việc đóng hoặc dán kín hoàn toàn; khi là danh từ, nó cũng có thể chỉ con hải cẩu tùy theo ngữ cảnh.', 'Seal the jar tightly to keep the biscuits fresh.', NULL, 'Đậy kín và niêm phong hũ bánh để giữ cho bánh quy luôn giòn ngon.', '{"wordId":"seal","ukIpa":"/siːl/","usIpa":"/siːl/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"Close something tightly to prevent anything entering or escaping","vi":"niêm phong; bịt kín; dán kín"},{"pos":"n.","en":"A covering or fastening that keeps something securely closed","vi":"lớp niêm phong; chỗ bịt kín"},{"pos":"n.","en":"A sea mammal with flippers that also rests on land","vi":"con hải cẩu"}],"examples":[{"en":"Seal the jar tightly to keep the biscuits fresh.","vi":"Đậy kín và niêm phong hũ bánh để giữ cho bánh quy luôn giòn ngon.","audioKind":"ex"},{"en":"Builders should seal gaps around windows to reduce heat loss and improve household energy efficiency.","vi":"Thợ xây nên bịt kín các khe hở quanh cửa sổ để giảm thất thoát nhiệt và nâng cao hiệu quả sử dụng năng lượng trong nhà.","audioKind":"ex2"}],"collocations":[{"en":"seal an envelope","vi":"dán kín phong bì"},{"en":"seal a gap","vi":"bịt kín khe hở"},{"en":"an airtight seal","vi":"nút kín khí"},{"en":"break the seal","vi":"tháo niêm phong"}],"wordFamily":["sealed (adj.)","sealer (n.)","unseal (v.)"],"synonyms":[],"antonyms":["unseal"],"tipVi":"Khi là động từ, từ này nhấn mạnh việc đóng hoặc dán kín hoàn toàn; khi là danh từ, nó cũng có thể chỉ con hải cẩu tùy theo ngữ cảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_repeatedly', 'en-b2-74', 'repeatedly', '/rɪˈpiːtɪdli/', 'B2', 'nhiều lần; liên tục; lặp đi lặp lại', 'adv.', 'repeat (v.), repeated (adj.), repetition (n.), repetitive (adj.)', 'Đồng nghĩa: again and again', 'Nhấn mạnh số lần lặp lại nhiều; không nhất thiết phải có tính chu kỳ đều đặn như regularly.', 'He knocked repeatedly, but nobody came to the door.', NULL, 'Anh ấy gõ cửa liên tục, nhưng chẳng có ai ra mở cửa cả.', '{"wordId":"repeatedly","ukIpa":"/rɪˈpiːtɪdli/","usIpa":"/rɪˈpiːtɪdli/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"Many times, often with little time between occasions.","vi":"nhiều lần; liên tục; lặp đi lặp lại"}],"examples":[{"en":"He knocked repeatedly, but nobody came to the door.","vi":"Anh ấy gõ cửa liên tục, nhưng chẳng có ai ra mở cửa cả.","audioKind":"ex"},{"en":"Students who repeatedly practise retrieving information tend to remember it better than those who simply reread their notes.","vi":"Những học sinh thường xuyên luyện tập việc gợi nhớ thông tin có xu hướng ghi nhớ tốt hơn so với những em chỉ đọc lại ghi chú một cách thông thường.","audioKind":"ex2"}],"collocations":[{"en":"repeatedly warn","vi":"cảnh báo nhiều lần"},{"en":"repeatedly ask","vi":"hỏi đi hỏi lại"},{"en":"repeatedly fail","vi":"thất bại nhiều lần"}],"wordFamily":["repeat (v.)","repeated (adj.)","repetition (n.)","repetitive (adj.)"],"synonyms":["again and again"],"antonyms":[],"tipVi":"Nhấn mạnh số lần lặp lại nhiều; không nhất thiết phải có tính chu kỳ đều đặn như regularly.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unsuitable', 'en-b2-74', 'unsuitable', '/ʌnˈsuːtəbl/', 'B2', 'không phù hợp; không thích hợp', 'adj.', 'suitable (adj.), suitability (n.), unsuitability (n.), suit (v.)', 'Đồng nghĩa: inappropriate, unfit · Trái nghĩa: suitable, appropriate', 'Thường dùng cấu trúc unsuitable for sb/sth, biểu thị không phù hợp với ai hoặc mục đích gì.', 'These thin shoes are unsuitable for walking through deep snow.', NULL, 'Đôi giày mỏng manh này không phù hợp để đi qua những lớp tuyết dày.', '{"wordId":"unsuitable","ukIpa":"/ʌnˈsuːtəbl/","usIpa":"/ʌnˈsuːtəbl/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"not right or appropriate for a particular person or purpose","vi":"không phù hợp; không thích hợp"}],"examples":[{"en":"These thin shoes are unsuitable for walking through deep snow.","vi":"Đôi giày mỏng manh này không phù hợp để đi qua những lớp tuyết dày.","audioKind":"ex"},{"en":"Some traditional teaching methods are unsuitable for large classes because they offer limited opportunities for individual feedback.","vi":"Một số phương pháp giảng dạy truyền thống không phù hợp với các lớp học đông đúc vì chúng mang lại ít cơ hội nhận phản hồi cá nhân hơn.","audioKind":"ex2"}],"collocations":[{"en":"unsuitable for children","vi":"không phù hợp với trẻ em"},{"en":"unsuitable clothing","vi":"trang phục không phù hợp"},{"en":"entirely unsuitable","vi":"hoàn toàn không phù hợp"}],"wordFamily":["suitable (adj.)","suitability (n.)","unsuitability (n.)","suit (v.)"],"synonyms":["inappropriate","unfit"],"antonyms":["suitable","appropriate"],"tipVi":"Thường dùng cấu trúc unsuitable for sb/sth, biểu thị không phù hợp với ai hoặc mục đích gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stitch', 'en-b2-74', 'stitch', '/stɪtʃ/', 'B2', 'mũi khâu; mũi kim; đường khâu; khâu; may; vá; cơn đau xóc hông (khi tập thể dục)', 'n.', 'stitching (n.), unstitched (adj.)', NULL, 'Cụm get a stitch chỉ hiện tượng xóc hông khi tập thể dục, không có nghĩa là "khâu một mũi".', 'A few neat stitches fixed the hole in my sleeve.', NULL, 'Vài đường khâu gọn gàng đã vá lại lỗ thủng trên tay áo của tôi.', '{"wordId":"stitch","ukIpa":"/stɪtʃ/","usIpa":"/stɪtʃ/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"a loop of thread holding fabric or a wound together","vi":"mũi khâu; mũi kim; đường khâu"},{"pos":"v.","en":"to join or repair something using a needle and thread","vi":"khâu; may; vá"},{"pos":"n.","en":"a sharp pain in your side, often during exercise","vi":"cơn đau xóc hông (khi tập thể dục)"}],"examples":[{"en":"A few neat stitches fixed the hole in my sleeve.","vi":"Vài đường khâu gọn gàng đã vá lại lỗ thủng trên tay áo của tôi.","audioKind":"ex"},{"en":"Teaching students to stitch torn clothing could reduce textile waste and encourage more sustainable consumption habits.","vi":"Việc dạy học sinh khâu vá quần áo rách có thể làm giảm lượng rác thải dệt may và thúc đẩy thói quen tiêu dùng bền vững hơn.","audioKind":"ex2"}],"collocations":[{"en":"neat stitches","vi":"đường khâu gọn gàng"},{"en":"stitch a wound","vi":"khâu vết thương"},{"en":"stitch together","vi":"khâu lại với nhau"},{"en":"get a stitch","vi":"bị xóc hông"}],"wordFamily":["stitching (n.)","unstitched (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm get a stitch chỉ hiện tượng xóc hông khi tập thể dục, không có nghĩa là \"khâu một mũi\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_74_1', 'en-b2-74', 'Cách dùng “seal” (v.) — niêm phong; bịt kín; dán kín', 'seal an envelope  ·  seal a gap  ·  an airtight seal', 'Khi là động từ, từ này nhấn mạnh việc đóng hoặc dán kín hoàn toàn; khi là danh từ, nó cũng có thể chỉ con hải cẩu tùy theo ngữ cảnh.', 'Họ từ (Word Family): sealed (adj.), sealer (n.), unseal (v.) | Trái nghĩa: unseal', '[{"hanzi":"Seal the jar tightly to keep the biscuits fresh.","pinyin":"","meaning":"Đậy kín và niêm phong hũ bánh để giữ cho bánh quy luôn giòn ngon."},{"hanzi":"Builders should seal gaps around windows to reduce heat loss and improve household energy efficiency.","pinyin":"","meaning":"Thợ xây nên bịt kín các khe hở quanh cửa sổ để giảm thất thoát nhiệt và nâng cao hiệu quả sử dụng năng lượng trong nhà."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_74_2', 'en-b2-74', 'Cách dùng “stubborn” (adj.) — bướng bỉnh, cứng đầu, ngoan cố', 'stubborn refusal  ·  stubborn resistance  ·  stubborn stain', 'Khi dùng miêu tả con người thường mang nghĩa tiêu cực; ngoài ra cũng có thể dùng cho vết bẩn khó chùi hoặc bệnh lâu khỏi.', 'Họ từ (Word Family): stubbornly (adv.), stubbornness (n.) | Đồng nghĩa: obstinate, inflexible · Trái nghĩa: flexible', '[{"hanzi":"My stubborn brother refused to wear a coat outside.","pinyin":"","meaning":"Người anh bướng bỉnh của tôi nhất quyết không chịu mặc áo khoác khi ra ngoài."},{"hanzi":"Stubborn resistance to change can prevent organisations from adopting more efficient and environmentally responsible practices.","pinyin":"","meaning":"Sự kháng cự ngoan cố trước sự thay đổi có thể khiến các tổ chức không thể áp dụng các phương pháp hiệu quả và có trách nhiệm với môi trường hơn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_74_3', 'en-b2-74', 'Cách dùng “transparent” (adj.) — trong suốt', 'transparent glass  ·  transparent process  ·  transparent excuse', 'transparent nhấn mạnh việc nhìn xuyên qua rõ ràng; translucent chỉ việc truyền ánh sáng nhưng không nhìn rõ vật bên kia.', 'Họ từ (Word Family): transparency (n.), transparently (adv.) | Đồng nghĩa: clear, see-through · Trái nghĩa: opaque', '[{"hanzi":"She keeps her buttons in a transparent plastic box.","pinyin":"","meaning":"Cô ấy cất các nút áo của mình trong một chiếc hộp nhựa trong suốt."},{"hanzi":"Public institutions need transparent recruitment procedures to ensure fairness and maintain the trust of local communities.","pinyin":"","meaning":"Các cơ quan công quyền cần có quy trình tuyển dụng minh bạch để đảm bảo công bằng và duy trì lòng tin của cộng đồng địa phương."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_74_4', 'en-b2-74', 'Cách dùng “buck” (n.) — đồng đô-la, đồng bạc (từ thông tục)', 'a few bucks  ·  make a quick buck  ·  pass the buck', 'Khi chỉ tiền đô-la, từ này mang sắc thái văn phong khẩu ngữ; cụm từ "pass the buck" có nghĩa là đùn đẩy trách nhiệm.', 'Đồng nghĩa: dollar', '[{"hanzi":"I bought this warm scarf for just five bucks.","pinyin":"","meaning":"Tôi đã mua chiếc khăn choàng cổ ấm áp này chỉ với năm đô-la."},{"hanzi":"Although shoppers may save a few bucks online, local retailers often provide more personalised advice and support.","pinyin":"","meaning":"Mặc dù người mua sắm có thể tiết kiệm được vài đồng khi mua hàng trực tuyến, nhưng các nhà bán lẻ địa phương thường cung cấp lời khuyên và sự hỗ trợ tận tình hơn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_74_1', 'en-b2-74', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_74_1_1', 'ten_b2_74_1', 'errand', 'I ran an errand before meeting you for lunch.', 'I ran an errand before meeting you for lunch.', '/ˈerənd/', 'Tôi đã chạy đi làm chút việc vặt trước khi gặp bạn ăn trưa.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_74_1_2', 'ten_b2_74_1', 'syrup', 'She poured a little syrup over her warm pancakes.', 'She poured a little syrup over her warm pancakes.', '/ˈsɪrəp/', 'Cô ấy rưới một ít xi-rô lên chiếc bánh kếp ấm nóng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_74_1_3', 'ten_b2_74_1', 'puff', 'A puff of steam escaped from the kettle.', 'A puff of steam escaped from the kettle.', '/pʌf/', 'Một làn hơi nước bốc lên từ chiếc ấm đun nước.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_74_1_4', 'ten_b2_74_1', 'cosmetics', 'She keeps her cosmetics in a small bathroom drawer.', 'She keeps her cosmetics in a small bathroom drawer.', '/kɑːzˈmetɪks/', 'Cô ấy để mỹ phẩm trong một ngăn kéo nhỏ ở phòng tắm.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_74_1_5', 'ten_b2_74_1', 'decent', 'We finally found a decent flat near the station.', 'We finally found a decent flat near the station.', '/ˈdiːsənt/', 'Cuối cùng chúng tôi cũng tìm được một căn hộ tươm tất gần nhà ga.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_74_1_6', 'ten_b2_74_1', 'bouquet', 'She brought a bright bouquet to her grandmother''s birthday dinner.', 'She brought a bright bouquet to her grandmother''s birthday dinner.', '/buˈkeɪ/', 'Cô ấy mang theo một bó hoa rực rỡ đến bữa tối sinh nhật của người bà.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_74_1_7', 'ten_b2_74_1', 'transparent', 'She keeps her buttons in a transparent plastic box.', 'She keeps her buttons in a transparent plastic box.', '/trænsˈperənt/', 'Cô ấy cất các nút áo của mình trong một chiếc hộp nhựa trong suốt.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_74_1_8', 'ten_b2_74_1', 'handful', 'He sprinkled a handful of nuts over his breakfast.', 'He sprinkled a handful of nuts over his breakfast.', '/ˈhændfʊl/', 'Anh ấy rắc một nắm hạt lên bữa sáng của mình.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_74_1_1', 'en-b2-74', 'ten_b2_74_1', 'listening', 'listening', 'I ran an errand before meeting you for lunch.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy rưới một ít xi-rô lên chiếc bánh kếp ấm nóng.","Giữ nhịp bước đều đặn khi bạn leo đồi.","Con mèo của chúng tôi ngủ dưới gầm bàn trong bữa tối.","Tôi đã chạy đi làm chút việc vặt trước khi gặp bạn ăn trưa."]'::jsonb, 3, 'I ran an errand before meeting you for lunch. → Tôi đã chạy đi làm chút việc vặt trước khi gặp bạn ăn trưa.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_74_1_2', 'en-b2-74', 'ten_b2_74_1', 'listening', 'listening', 'She poured a little syrup over her warm pancakes.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Đậy kín và niêm phong hũ bánh để giữ cho bánh quy luôn giòn ngon.","Con mèo của chúng tôi ngủ dưới gầm bàn trong bữa tối.","Cô ấy rưới một ít xi-rô lên chiếc bánh kếp ấm nóng.","Cô ấy rón rén bước qua phòng ngủ để tránh đánh thức em trai."]'::jsonb, 2, 'She poured a little syrup over her warm pancakes. → Cô ấy rưới một ít xi-rô lên chiếc bánh kếp ấm nóng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_74_1_3', 'en-b2-74', 'ten_b2_74_1', 'listening', 'listening', 'A puff of steam escaped from the kettle.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một làn hơi nước bốc lên từ chiếc ấm đun nước.","Đôi giày mỏng manh này không phù hợp để đi qua những lớp tuyết dày.","Lưỡi dao quá cùn nên không thể thái được cà chua.","Chị tôi nháy mắt với tôi qua bàn ăn tối."]'::jsonb, 0, 'A puff of steam escaped from the kettle. → Một làn hơi nước bốc lên từ chiếc ấm đun nước.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_74_2', 'en-b2-74', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_74_2_1', 'ten_b2_74_2', 'errand', 'Reliable neighbourhood transport helps older residents run errands independently and maintain regular contact with their communities.', 'Reliable neighbourhood transport helps older residents run errands independently and maintain regular contact with their communities.', '/ˈerənd/', 'Giao thông công cộng đáng tin cậy trong khu dân cư giúp người cao tuổi tự đi làm việc vặt và duy trì sự gắn kết thường xuyên với cộng đồng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_74_2_2', 'ten_b2_74_2', 'syrup', 'Fruit preserved in syrup often contains more added sugar than fresh fruit, which may concern health-conscious consumers.', 'Fruit preserved in syrup often contains more added sugar than fresh fruit, which may concern health-conscious consumers.', '/ˈsɪrəp/', 'Trái cây ngâm xi-rô thường chứa nhiều đường bổ sung hơn trái cây tươi, điều này có thể khiến những người tiêu dùng quan tâm đến sức khỏe lo ngại.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_74_2_3', 'ten_b2_74_2', 'puff', 'Older buses release puffs of dark smoke, highlighting the need for cleaner public transport in cities.', 'Older buses release puffs of dark smoke, highlighting the need for cleaner public transport in cities.', '/pʌf/', 'Các xe buýt cũ xả ra những làn khói đen kịt, làm nổi bật sự cần thiết phải có phương tiện giao thông công cộng sạch sẽ hơn ở các đô thị.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_74_2_4', 'ten_b2_74_2', 'cosmetics', 'Consumers increasingly expect cosmetics manufacturers to disclose ingredients clearly and reduce unnecessary packaging to limit environmental damage.', 'Consumers increasingly expect cosmetics manufacturers to disclose ingredients clearly and reduce unnecessary packaging to limit environmental damage.', '/kɑːzˈmetɪks/', 'Người tiêu dùng ngày càng kỳ vọng các nhà sản xuất mỹ phẩm công khai minh bạch các thành phần và giảm thiểu bao bì không cần thiết để hạn chế tác hại môi trường.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_74_2_5', 'ten_b2_74_2', 'decent', 'Every worker should earn enough to afford decent housing and meet their basic needs.', 'Every worker should earn enough to afford decent housing and meet their basic needs.', '/ˈdiːsənt/', 'Mỗi người lao động đều phải kiếm đủ tiền để chi trả cho nhà ở đàng hoàng và đáp ứng các nhu cầu cơ bản của họ.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_74_2_6', 'ten_b2_74_2', 'bouquet', 'Choosing a bouquet of locally grown flowers can reduce the environmental impact associated with long-distance transport.', 'Choosing a bouquet of locally grown flowers can reduce the environmental impact associated with long-distance transport.', '/buˈkeɪ/', 'Việc lựa chọn một bó hoa được trồng tại địa phương có thể làm giảm tác động môi trường liên quan đến việc vận chuyển đường dài.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_74_2_1', 'en-b2-74', 'ten_b2_74_2', 'listening', 'listening', 'Reliable neighbourhood transport helps older residents run errands independently and maintain regular contact with their communities.', NULL, 'Trong câu vừa nghe, từ “errand” mang nghĩa nào sau đây?', '["thuốc chữa bệnh; việc dùng thuốc điều trị","việc vặt; chuyến đi ngắn để mua, lấy hoặc giao đồ","hàm; xương hàm","thuộc bưu chính; thuộc bưu điện"]'::jsonb, 1, '“errand” (/ˈerənd/): việc vặt; chuyến đi ngắn để mua, lấy hoặc giao đồ. Câu đầy đủ: Reliable neighbourhood transport helps older residents run errands independently and maintain regular contact with their communities.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_74_2_2', 'en-b2-74', 'ten_b2_74_2', 'listening', 'listening', 'Fruit preserved in syrup often contains more added sugar than fresh fruit, which may concern health-conscious consumers.', NULL, 'Trong câu vừa nghe, từ “syrup” mang nghĩa nào sau đây?', '["xác tàu đắm; phương tiện bị hư hỏng nặng","khoản trợ cấp, tiền cấp phát từ một tổ chức cho mục đích cụ thể","vắc-xin; chất kích thích hệ miễn dịch chống lại bệnh tật","xi-rô; nước đường đặc"]'::jsonb, 3, '“syrup” (/ˈsɪrəp/): xi-rô; nước đường đặc. Câu đầy đủ: Fruit preserved in syrup often contains more added sugar than fresh fruit, which may concern health-conscious consumers.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
