INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_74_1', 'en-b2-74', NULL, 'comprehensive_test', 'listening', 'errand', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["việc vặt; chuyến đi ngắn để mua, lấy hoặc giao đồ","khiên; vật che chắn","kéo; cẩu (xe cộ, tàu thuyền)","xâm lược; xâm chiếm"]'::jsonb, 0, 'errand (/ˈerənd/) → việc vặt; chuyến đi ngắn để mua, lấy hoặc giao đồ', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_74_2', 'en-b2-74', NULL, 'comprehensive_test', 'listening', 'She poured a little syrup over her warm pancakes.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi không thể chịu nổi tiếng ồn của chiếc quạt cũ đó.","Lưỡi dao quá cùn nên không thể thái được cà chua.","Đậy kín và niêm phong hũ bánh để giữ cho bánh quy luôn giòn ngon.","Cô ấy rưới một ít xi-rô lên chiếc bánh kếp ấm nóng."]'::jsonb, 3, 'She poured a little syrup over her warm pancakes. → Cô ấy rưới một ít xi-rô lên chiếc bánh kếp ấm nóng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_74_3', 'en-b2-74', NULL, 'comprehensive_test', 'listening', 'puff', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["trang bị; lắp đặt thiết bị","dễ lây; có tính truyền nhiễm; dễ lây lan; có sức lan tỏa","luồng (khí, khói, hơi nước); làn (gió nhẹ)","ưu tiên; việc ưu tiên; nhiệm vụ hàng đầu"]'::jsonb, 2, 'puff (/pʌf/) → luồng (khí, khói, hơi nước); làn (gió nhẹ); thở hồng hộc; thở hổn hển; thổi ra; phả ra; phồng lên', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_74_4', 'en-b2-74', NULL, 'comprehensive_test', 'listening', 'She keeps her cosmetics in a small bathroom drawer.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Giữ nhịp bước đều đặn khi bạn leo đồi.","Cô ấy để mỹ phẩm trong một ngăn kéo nhỏ ở phòng tắm.","Anh ấy gõ cửa liên tục, nhưng chẳng có ai ra mở cửa cả.","Cuối cùng chúng tôi cũng tìm được một căn hộ tươm tất gần nhà ga."]'::jsonb, 1, 'She keeps her cosmetics in a small bathroom drawer. → Cô ấy để mỹ phẩm trong một ngăn kéo nhỏ ở phòng tắm.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_74_5', 'en-b2-74', NULL, 'comprehensive_test', 'listening', 'decent', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["con bọ; bọ cánh cứng","giận dữ; nổi giận đùng đùng","động từ: nghi ngờ; phỏng đoán","tử tế; kha khá; tươm tất; đáng hài lòng"]'::jsonb, 3, 'decent (/ˈdiːsənt/) → tử tế; kha khá; tươm tất; đáng hài lòng; đàng hoàng; lịch sự; đúng mực', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_74_6', 'en-b2-74', NULL, 'comprehensive_test', 'listening', 'She brought a bright bouquet to her grandmother''s birthday dinner.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy rưới một ít xi-rô lên chiếc bánh kếp ấm nóng.","Giữ nhịp bước đều đặn khi bạn leo đồi.","Anh ấy gõ cửa liên tục, nhưng chẳng có ai ra mở cửa cả.","Cô ấy mang theo một bó hoa rực rỡ đến bữa tối sinh nhật của người bà."]'::jsonb, 3, 'She brought a bright bouquet to her grandmother''s birthday dinner. → Cô ấy mang theo một bó hoa rực rỡ đến bữa tối sinh nhật của người bà.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
