INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_74_8', 'en-b2-74', NULL, 'comprehensive_test', 'listening', 'He sprinkled a handful of nuts over his breakfast.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Lưỡi dao quá cùn nên không thể thái được cà chua.","Vết rò rỉ dưới bồn rửa chén đã làm ướt sũng tất cả khăn lau của chúng tôi.","Anh ấy rắc một nắm hạt lên bữa sáng của mình.","Đôi giày mỏng manh này không phù hợp để đi qua những lớp tuyết dày."]'::jsonb, 2, 'He sprinkled a handful of nuts over his breakfast. → Anh ấy rắc một nắm hạt lên bữa sáng của mình.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_74_9', 'en-b2-74', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “of a satisfactory or reasonably good standard”?', '["warranty","bear","cosmetics","decent"]'::jsonb, 3, 'decent (/ˈdiːsənt/) → tử tế; kha khá; tươm tất; đáng hài lòng', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
