INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_74_18', 'en-b2-74', NULL, 'comprehensive_test', 'reading', NULL, 'Reliable neighbourhood transport helps older residents run errands independently and maintain regular contact with their communities.', 'Dựa vào câu trên, từ “errand” có nghĩa phù hợp nhất là gì?', '["vĩnh cửu; bất tận","ngoại lệ","việc vặt; chuyến đi ngắn để mua, lấy hoặc giao đồ","lợi ích; mục đích; vì (ai/cái gì)"]'::jsonb, 2, 'errand: việc vặt; chuyến đi ngắn để mua, lấy hoặc giao đồ. Dịch cả câu: Giao thông công cộng đáng tin cậy trong khu dân cư giúp người cao tuổi tự đi làm việc vặt và duy trì sự gắn kết thường xuyên với cộng đồng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_74_19', 'en-b2-74', NULL, 'comprehensive_test', 'reading', NULL, 'Fruit preserved in syrup often contains more added sugar than fresh fruit, which may concern health-conscious consumers.', 'Dựa vào câu trên, từ “syrup” có nghĩa phù hợp nhất là gì?', '["xi-rô; nước đường đặc","thì thầm; nói nhỏ; tai bay vách đá","trung tâm; đầu mối giao thông","làm lớn hơn; mở rộng; phóng to"]'::jsonb, 0, 'syrup: xi-rô; nước đường đặc; xi-rô thuốc. Dịch cả câu: Trái cây ngâm xi-rô thường chứa nhiều đường bổ sung hơn trái cây tươi, điều này có thể khiến những người tiêu dùng quan tâm đến sức khỏe lo ngại.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_74_20', 'en-b2-74', NULL, 'comprehensive_test', 'reading', NULL, 'Older buses release puffs of dark smoke, highlighting the need for cleaner public transport in cities.', 'Dựa vào câu trên, từ “puff” có nghĩa phù hợp nhất là gì?', '["luồng (khí, khói, hơi nước); làn (gió nhẹ)","cơ sở vật chất; trang thiết bị; phương tiện","thói quen; tập quán; phong tục","lúng túng; ngượng ngùng; khó xử"]'::jsonb, 0, 'puff: luồng (khí, khói, hơi nước); làn (gió nhẹ); thở hồng hộc; thở hổn hển; thổi ra; phả ra; phồng lên. Dịch cả câu: Các xe buýt cũ xả ra những làn khói đen kịt, làm nổi bật sự cần thiết phải có phương tiện giao thông công cộng sạch sẽ hơn ở các đô thị.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_74_21', 'en-b2-74', NULL, 'comprehensive_test', 'reading', NULL, 'Consumers increasingly expect cosmetics manufacturers to disclose ingredients clearly and reduce unnecessary packaging to limit environmental damage.', 'Dựa vào câu trên, từ “cosmetics” có nghĩa phù hợp nhất là gì?', '["tinh vi; phức tạp; hiện đại","nitơ; khí nitơ","phóng viên thường trú; phóng viên chuyên đề","mỹ phẩm; đồ trang điểm"]'::jsonb, 3, 'cosmetics: mỹ phẩm; đồ trang điểm. Dịch cả câu: Người tiêu dùng ngày càng kỳ vọng các nhà sản xuất mỹ phẩm công khai minh bạch các thành phần và giảm thiểu bao bì không cần thiết để hạn chế tác hại môi trường.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_74_22', 'en-b2-74', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nhiều lần; liên tục; lặp đi lặp lại”', '["classification","repeatedly","selection","outskirts"]'::jsonb, 1, 'nhiều lần; liên tục; lặp đi lặp lại → repeatedly (/rɪˈpiːtɪdli/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_74_23', 'en-b2-74', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “không phù hợp; không thích hợp”', '["ballroom","follow-up","unsuitable","eyesight"]'::jsonb, 2, 'không phù hợp; không thích hợp → unsuitable (/ʌnˈsuːtəbl/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_74_24', 'en-b2-74', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “mũi khâu; mũi kim; đường khâu”', '["versus","exception","stitch","clay"]'::jsonb, 2, 'mũi khâu; mũi kim; đường khâu → stitch (/stɪtʃ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-75', 'en', 'Bài 75: Đời sống hằng ngày (2) - CEFR B2', 'CEFR B2', 'B2 · Đời sống', '27 từ vựng Tiếng Anh CEFR B2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4075, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_largely', 'en-b2-75', 'largely', '/ˈlɑːrdʒli/', 'B2', 'chủ yếu; phần lớn; ở mức độ lớn', 'adv.', 'large (adj.)', 'Đồng nghĩa: mostly, mainly', 'Từ này diễn tả ý nghĩa chủ yếu hoặc đại thể, không dùng để chỉ kích thước vật lý lớn.', 'The beach was largely empty when we arrived.', NULL, 'Bãi biển hầu như vắng bóng người khi chúng tôi đến nơi.', '{"wordId":"largely","ukIpa":"/ˈlɑːdʒli/","usIpa":"/ˈlɑːrdʒli/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"mostly or to a great extent","vi":"chủ yếu; phần lớn; ở mức độ lớn"}],"examples":[{"en":"The beach was largely empty when we arrived.","vi":"Bãi biển hầu như vắng bóng người khi chúng tôi đến nơi.","audioKind":"ex"},{"en":"The success of public health campaigns depends largely on clear communication and widespread community trust.","vi":"Sự thành công của các chiến dịch y tế công cộng phần lớn phụ thuộc vào giao tiếp minh bạch và niềm tin sâu rộng trong cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"largely due to","vi":"chủ yếu là do"},{"en":"depend largely on","vi":"phụ thuộc phần lớn vào"},{"en":"remain largely unchanged","vi":"vẫn hầu như không thay đổi"},{"en":"largely responsible for","vi":"chịu trách nhiệm chính cho"}],"wordFamily":["large (adj.)"],"synonyms":["mostly","mainly"],"antonyms":[],"tipVi":"Từ này diễn tả ý nghĩa chủ yếu hoặc đại thể, không dùng để chỉ kích thước vật lý lớn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_imitate', 'en-b2-75', 'imitate', '/ˈɪmɪteɪt/', 'B2', 'bắt chước; mô phỏng; làm giả; nhái theo', 'v.', 'imitation (n.), imitative (adj.), imitator (n.)', 'Đồng nghĩa: copy, mimic', 'Đi trực tiếp với đối tượng được bắt chước mà không thêm giới từ: imitate someone.', 'Our little sister loves to imitate animal sounds.', NULL, 'Em gái nhỏ của chúng tôi rất thích bắt chước tiếng kêu của động vật.', '{"wordId":"imitate","ukIpa":"/ˈɪmɪteɪt/","usIpa":"/ˈɪmɪteɪt/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To copy someone''s actions, speech, or way of doing something","vi":"bắt chước; mô phỏng"},{"pos":"v.","en":"To make something look or behave like something else","vi":"làm giả; nhái theo"}],"examples":[{"en":"Our little sister loves to imitate animal sounds.","vi":"Em gái nhỏ của chúng tôi rất thích bắt chước tiếng kêu của động vật.","audioKind":"ex"},{"en":"Young children often imitate adult behaviour, so parents play an important role in developing healthy habits.","vi":"Trẻ nhỏ thường bắt chước hành vi của người lớn, do đó cha mẹ đóng vai trò quan trọng trong việc hình thành các thói quen lành mạnh.","audioKind":"ex2"}],"collocations":[{"en":"imitate behaviour","vi":"bắt chước hành vi"},{"en":"imitate a voice","vi":"nhái giọng"},{"en":"imitate nature","vi":"mô phỏng tự nhiên"}],"wordFamily":["imitation (n.)","imitative (adj.)","imitator (n.)"],"synonyms":["copy","mimic"],"antonyms":[],"tipVi":"Đi trực tiếp với đối tượng được bắt chước mà không thêm giới từ: imitate someone.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_overflow', 'en-b2-75', 'overflow', '/ˌoʊvərˈfloʊ/', 'B2', 'tràn ra; ngập; chứa đầy; đông nghịt; chất tràn; lượng nước tràn', 'v.', 'overflowing (adj.)', 'Đồng nghĩa: spill over', 'Thể động từ có trọng âm rơi vào âm tiết cuối, thể danh từ có trọng âm rơi vào âm tiết đầu.', 'The bath overflowed while I was answering the door.', NULL, 'Bồn tắm đã bị tràn nước trong lúc tôi ra mở cửa.', '{"wordId":"overflow","ukIpa":"/ˌəʊvəˈfləʊ/","usIpa":"/ˌoʊvərˈfloʊ/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To flow over the edge because a container is too full.","vi":"tràn ra; ngập"},{"pos":"v.","en":"To contain more people or things than can comfortably fit.","vi":"chứa đầy; đông nghịt"},{"pos":"n.","en":"Liquid or other contents that exceed the available space.","vi":"chất tràn; lượng nước tràn"}],"examples":[{"en":"The bath overflowed while I was answering the door.","vi":"Bồn tắm đã bị tràn nước trong lúc tôi ra mở cửa.","audioKind":"ex"},{"en":"During heavy rainfall, urban drains may overflow and carry polluted water into nearby rivers.","vi":"Trong những trận mưa lớn, hệ thống thoát nước đô thị có thể bị quá tải và mang nước ô nhiễm đổ ra các con sông gần đó.","audioKind":"ex2"}],"collocations":[{"en":"overflow with people","vi":"đông nghẹt người"},{"en":"overflow with joy","vi":"tràn ngập niềm vui"},{"en":"an overflow pipe","vi":"ống tràn"}],"wordFamily":["overflowing (adj.)"],"synonyms":["spill over"],"antonyms":[],"tipVi":"Thể động từ có trọng âm rơi vào âm tiết cuối, thể danh từ có trọng âm rơi vào âm tiết đầu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_occasionally', 'en-b2-75', 'occasionally', '/əˈkeɪʒənəli/', 'B2', 'thỉnh thoảng; đôi khi', 'adv.', 'occasion (n.), occasional (adj.)', 'Đồng nghĩa: sometimes, now and then · Trái nghĩa: frequently', 'Thường đứng trước động từ thường, sau động từ "be", hoặc cũng có thể đứng ở đầu câu.', 'We occasionally buy fresh bread from the market.', NULL, 'Thỉnh thoảng chúng tôi mua bánh mì tươi ở chợ.', '{"wordId":"occasionally","ukIpa":"/əˈkeɪʒənəli/","usIpa":"/əˈkeɪʒənəli/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"sometimes, but not often or regularly","vi":"thỉnh thoảng; đôi khi"}],"examples":[{"en":"We occasionally buy fresh bread from the market.","vi":"Thỉnh thoảng chúng tôi mua bánh mì tươi ở chợ.","audioKind":"ex"},{"en":"Employees who occasionally work from home may benefit from greater flexibility without losing regular contact with colleagues.","vi":"Những nhân viên thỉnh thoảng làm việc tại nhà có thể hưởng lợi từ sự linh hoạt cao hơn mà không làm mất đi sự liên lạc thường xuyên với đồng nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"only occasionally","vi":"chỉ thỉnh thoảng"},{"en":"occasionally visit","vi":"thỉnh thoảng ghé thăm"},{"en":"occasionally occur","vi":"thỉnh thoảng xảy ra"}],"wordFamily":["occasion (n.)","occasional (adj.)"],"synonyms":["sometimes","now and then"],"antonyms":["frequently"],"tipVi":"Thường đứng trước động từ thường, sau động từ \"be\", hoặc cũng có thể đứng ở đầu câu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tighten', 'en-b2-75', 'tighten', '/ˈtaɪtən/', 'B2', 'vặn chặt; siết chặt; làm cho căng hơn; thắt chặt; tăng cường kiểm soát (quy định, luật lệ)', 'v.', 'tight (adj.), tightly (adv.), tightness (n.)', 'Trái nghĩa: loosen', 'Có thể dùng ngoại động từ hoặc nội động từ: tighten a rope; the rope tightens.', 'Please tighten the lid before you shake the bottle.', NULL, 'Vui lòng vặn chặt nắp trước khi bạn lắc chai.', '{"wordId":"tighten","ukIpa":"/ˈtaɪtən/","usIpa":"/ˈtaɪtən/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To make or become tighter or more firmly fixed.","vi":"vặn chặt; siết chặt; làm cho căng hơn"},{"pos":"v.","en":"To make rules or controls stricter.","vi":"thắt chặt; tăng cường kiểm soát (quy định, luật lệ)"}],"examples":[{"en":"Please tighten the lid before you shake the bottle.","vi":"Vui lòng vặn chặt nắp trước khi bạn lắc chai.","audioKind":"ex"},{"en":"Governments should tighten safety regulations to ensure that all new housing meets acceptable standards of construction.","vi":"Chính phủ nên thắt chặt các quy định an toàn để đảm bảo tất cả nhà ở mới xây đều đạt tiêu chuẩn xây dựng có thể chấp nhận được.","audioKind":"ex2"}],"collocations":[{"en":"tighten a screw","vi":"vặn chặt một con ốc"},{"en":"tighten your grip","vi":"siết chặt tay nắm"},{"en":"tighten regulations","vi":"thắt chặt quy định"}],"wordFamily":["tight (adj.)","tightly (adv.)","tightness (n.)"],"synonyms":[],"antonyms":["loosen"],"tipVi":"Có thể dùng ngoại động từ hoặc nội động từ: tighten a rope; the rope tightens.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_uneven', 'en-b2-75', 'uneven', '/ʌnˈiːvən/', 'B2', 'gập ghềnh; không bằng phẳng; nhấp nhô; không đều; không đồng đều; mất cân đối', 'adj.', 'even (adj.), unevenly (adv.), unevenness (n.)', 'Đồng nghĩa: irregular · Trái nghĩa: even', 'Số lẻ dùng odd, không dùng uneven; uneven nhấn mạnh sự không bằng phẳng hoặc không đồng đều.', 'Watch your step on the uneven stones outside.', NULL, 'Hãy chú ý bước chân trên những hòn đá gập ghềnh ở bên ngoài.', '{"wordId":"uneven","ukIpa":"/ʌnˈiːvən/","usIpa":"/ʌnˈiːvən/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"not level, flat, or smooth","vi":"gập ghềnh; không bằng phẳng; nhấp nhô"},{"pos":"adj.","en":"not equal or regular in amount, quality, or distribution","vi":"không đều; không đồng đều; mất cân đối"}],"examples":[{"en":"Watch your step on the uneven stones outside.","vi":"Hãy chú ý bước chân trên những hòn đá gập ghềnh ở bên ngoài.","audioKind":"ex"},{"en":"Uneven access to digital technology can widen educational inequalities between urban and rural communities.","vi":"Khả năng tiếp cận công nghệ số không đồng đều có thể nới rộng khoảng cách giáo dục giữa các cộng đồng thành thị và nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"uneven ground","vi":"mặt đất gập ghềnh"},{"en":"uneven distribution","vi":"sự phân bố không đồng đều"},{"en":"uneven development","vi":"sự phát triển không đồng đều"}],"wordFamily":["even (adj.)","unevenly (adv.)","unevenness (n.)"],"synonyms":["irregular"],"antonyms":["even"],"tipVi":"Số lẻ dùng odd, không dùng uneven; uneven nhấn mạnh sự không bằng phẳng hoặc không đồng đều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_drill', 'en-b2-75', 'drill', '/drɪl/', 'B2', 'máy khoan; cái khoan; cuộc diễn tập; bài tập rèn luyện; khoan; luyện tập lặp đi lặp lại', 'n.', 'drilling (n.), driller (n.)', NULL, '"fire drill" là buổi diễn tập phòng cháy chữa cháy, không phải dụng cụ dùng để chữa cháy.', 'I borrowed a drill to put up the shelf.', NULL, 'Tôi đã mượn một cái khoan để lắp chiếc kệ lên.', '{"wordId":"drill","ukIpa":"/drɪl/","usIpa":"/drɪl/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"a tool or machine used to make holes","vi":"máy khoan; cái khoan"},{"pos":"n.","en":"repeated practice of a skill or emergency procedure","vi":"cuộc diễn tập; bài tập rèn luyện"},{"pos":"v.","en":"to make holes with a tool or train through repetition","vi":"khoan; luyện tập lặp đi lặp lại"}],"examples":[{"en":"I borrowed a drill to put up the shelf.","vi":"Tôi đã mượn một cái khoan để lắp chiếc kệ lên.","audioKind":"ex"},{"en":"Regular fire drills help students respond calmly during emergencies and identify the safest routes out of school buildings.","vi":"Các buổi diễn tập phòng cháy chữa cháy định kỳ giúp học sinh phản ứng bình tĩnh trong các trường hợp khẩn cấp và xác định các lối thoát hiểm an toàn nhất khỏi các tòa nhà trường học.","audioKind":"ex2"}],"collocations":[{"en":"electric drill","vi":"máy khoan điện"},{"en":"fire drill","vi":"diễn tập phòng cháy chữa cháy"},{"en":"drill a hole","vi":"khoan một cái lỗ"},{"en":"practice drills","vi":"các bài tập thực hành"}],"wordFamily":["drilling (n.)","driller (n.)"],"synonyms":[],"antonyms":[],"tipVi":"\"fire drill\" là buổi diễn tập phòng cháy chữa cháy, không phải dụng cụ dùng để chữa cháy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_enclose', 'en-b2-75', 'enclose', '/ɪnˈkloʊz/', 'B2', 'bao quanh; rào lại; đính kèm; gửi kèm', 'v.', 'enclosure (n.), enclosed (adj.)', 'Đồng nghĩa: surround, encircle', 'Thư tín bản giấy kèm tài liệu dùng "enclose"; tệp đính kèm email dùng "attach".', 'A low stone wall encloses our sunny back garden.', NULL, 'Một bức tường đá thấp bao quanh khu vườn phía sau đầy nắng của chúng tôi.', '{"wordId":"enclose","ukIpa":"/ɪnˈkləʊz/","usIpa":"/ɪnˈkloʊz/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To surround something with a wall, fence, or other barrier.","vi":"bao quanh; rào lại"},{"pos":"v.","en":"To put something inside an envelope or package with something else.","vi":"đính kèm; gửi kèm"}],"examples":[{"en":"A low stone wall encloses our sunny back garden.","vi":"Một bức tường đá thấp bao quanh khu vườn phía sau đầy nắng của chúng tôi.","audioKind":"ex"},{"en":"Applicants should enclose copies of their qualifications when submitting a paper application for the scholarship.","vi":"Các ứng viên nên đính kèm bản sao các bằng cấp của mình khi nộp hồ sơ xin học bổng bản cứng.","audioKind":"ex2"}],"collocations":[{"en":"enclose a garden","vi":"rào kín khu vườn"},{"en":"enclose a copy","vi":"đính kèm một bản sao"},{"en":"fully enclosed","vi":"hoàn toàn khép kín"}],"wordFamily":["enclosure (n.)","enclosed (adj.)"],"synonyms":["surround","encircle"],"antonyms":[],"tipVi":"Thư tín bản giấy kèm tài liệu dùng \"enclose\"; tệp đính kèm email dùng \"attach\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_filthy', 'en-b2-75', 'filthy', '/ˈfɪlθi/', 'B2', 'bẩn thỉu; dơ dáy; thô tục; tục tĩu', 'adj.', 'filth (n.), filthiness (n.)', 'Đồng nghĩa: grimy, disgusting · Trái nghĩa: clean, spotless', 'Mang sắc thái mạnh hơn từ dirty, diễn tả mức độ rất bẩn; ngoài ra cũng dùng để miêu tả ngôn từ thô tục.', 'Your boots are filthy after that walk through the fields.', NULL, 'Đôi bốt của bạn bẩn thỉu sau chuyến đi bộ băng qua các cánh đồng.', '{"wordId":"filthy","ukIpa":"/ˈfɪlθi/","usIpa":"/ˈfɪlθi/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Extremely dirty.","vi":"bẩn thỉu; dơ dáy"},{"pos":"adj.","en":"Offensive because of rude or sexual content.","vi":"thô tục; tục tĩu"}],"examples":[{"en":"Your boots are filthy after that walk through the fields.","vi":"Đôi bốt của bạn bẩn thỉu sau chuyến đi bộ băng qua các cánh đồng.","audioKind":"ex"},{"en":"Filthy water supplies increase the risk of disease, particularly in communities without adequate sanitation infrastructure.","vi":"Nguồn nước bẩn thỉu làm tăng nguy cơ mắc bệnh, đặc biệt là ở các cộng đồng thiếu cơ sở hạ tầng vệ sinh đầy đủ.","audioKind":"ex2"}],"collocations":[{"en":"filthy clothes","vi":"quần áo bẩn thỉu"},{"en":"filthy conditions","vi":"điều kiện cực kỳ bẩn thỉu"},{"en":"filthy language","vi":"ngôn từ thô tục"}],"wordFamily":["filth (n.)","filthiness (n.)"],"synonyms":["grimy","disgusting"],"antonyms":["clean","spotless"],"tipVi":"Mang sắc thái mạnh hơn từ dirty, diễn tả mức độ rất bẩn; ngoài ra cũng dùng để miêu tả ngôn từ thô tục.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fuss', 'en-b2-75', 'fuss', '/fʌs/', 'B2', 'sự đại sự hóa; sự ồn ào vô ích; làm rùm beng; quá bận tâm', 'n.', 'fussy (adj.), fussiness (n.)', NULL, 'make a fuss có nghĩa là làm đại chuyện lên; còn fuss over chỉ việc quá lo lắng, bận tâm.', 'Please don''t make a fuss about a little mud.', NULL, 'Xin đừng làm quá lên chỉ vì một chút bùn đất.', '{"wordId":"fuss","ukIpa":"/fʌs/","usIpa":"/fʌs/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"unnecessary excitement, worry, or activity about something","vi":"sự đại sự hóa; sự ồn ào vô ích"},{"pos":"v.","en":"to worry or give excessive attention to small things","vi":"làm rùm beng; quá bận tâm"}],"examples":[{"en":"Please don''t make a fuss about a little mud.","vi":"Xin đừng làm quá lên chỉ vì một chút bùn đất.","audioKind":"ex"},{"en":"Some parents fuss over minor mistakes, which may discourage children from trying unfamiliar activities.","vi":"Một số bậc phụ huynh quá bận tâm về những lỗi lầm nhỏ, điều này có thể làm nản lòng trẻ khi thử các hoạt động mới lạ.","audioKind":"ex2"}],"collocations":[{"en":"make a fuss","vi":"làm rùm beng lên"},{"en":"without any fuss","vi":"một cách dễ dàng, không chút phiền phức"},{"en":"fuss over someone","vi":"quá quan tâm chăm sóc ai đó"}],"wordFamily":["fussy (adj.)","fussiness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"make a fuss có nghĩa là làm đại chuyện lên; còn fuss over chỉ việc quá lo lắng, bận tâm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_crumble', 'en-b2-75', 'crumble', '/ˈkrʌmbəl/', 'B2', 'vỡ vụn; bẻ vụn; sụp đổ; suy tàn', 'v.', 'crumb (n.), crumbly (adj.)', 'Đồng nghĩa: disintegrate, collapse', 'Có thể dùng cho vật thể bị vỡ vụn hoặc cho niềm tin, quyền lực bị sụp đổ.', 'The dry biscuit crumbled as I picked it up.', NULL, 'Chiếc bánh quy khô vỡ vụn ngay khi tôi nhặt nó lên.', '{"wordId":"crumble","ukIpa":"/ˈkrʌmbəl/","usIpa":"/ˈkrʌmbəl/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to break, or make something break, into small pieces","vi":"vỡ vụn; bẻ vụn"},{"pos":"v.","en":"to gradually lose strength, effectiveness, or power","vi":"sụp đổ; suy tàn"}],"examples":[{"en":"The dry biscuit crumbled as I picked it up.","vi":"Chiếc bánh quy khô vỡ vụn ngay khi tôi nhặt nó lên.","audioKind":"ex"},{"en":"Without regular maintenance, historic buildings may crumble, causing communities to lose an important part of their heritage.","vi":"Nếu không được bảo trì thường xuyên, các công trình lịch sử có thể sụp đổ, khiến cộng đồng mất đi một phần di sản quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"crumble into pieces","vi":"vỡ thành từng mảnh"},{"en":"crumble under pressure","vi":"sụp đổ dưới áp lực"},{"en":"crumble away","vi":"tan rã dần dần"}],"wordFamily":["crumb (n.)","crumbly (adj.)"],"synonyms":["disintegrate","collapse"],"antonyms":[],"tipVi":"Có thể dùng cho vật thể bị vỡ vụn hoặc cho niềm tin, quyền lực bị sụp đổ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_radish', 'en-b2-75', 'radish', '/ˈrædɪʃ/', 'B2', 'củ cải; củ cải đỏ nhỏ', 'n.', NULL, NULL, 'Là danh từ đếm được; thường chỉ củ cải đỏ nhỏ, trong khi củ cải trắng có thể gọi là daikon.', 'I sliced a crisp radish into our lunchtime salad.', NULL, 'Tôi đã thái lát một củ cải giòn vào món salad bữa trưa.', '{"wordId":"radish","ukIpa":"/ˈrædɪʃ/","usIpa":"/ˈrædɪʃ/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"a crisp edible root, often small, red, and slightly spicy","vi":"củ cải; củ cải đỏ nhỏ"}],"examples":[{"en":"I sliced a crisp radish into our lunchtime salad.","vi":"Tôi đã thái lát một củ cải giòn vào món salad bữa trưa.","audioKind":"ex"},{"en":"Growing radishes in school gardens allows children to observe plant development and learn about healthy eating.","vi":"Việc trồng củ cải trong vườn trường giúp trẻ em quan sát sự phát triển của thực vật và tìm hiểu về chế độ ăn uống lành mạnh.","audioKind":"ex2"}],"collocations":[{"en":"sliced radishes","vi":"củ cải thái lát"},{"en":"radish seeds","vi":"hạt giống củ cải"},{"en":"pickled radish","vi":"củ cải muối chua"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ đếm được; thường chỉ củ cải đỏ nhỏ, trong khi củ cải trắng có thể gọi là daikon.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_enquire', 'en-b2-75', 'enquire', '/ɪnˈkwaɪr/', 'B2', 'thưa hỏi; dò hỏi; điều tra', 'v.', 'enquiry (n.), enquirer (n.)', 'Đồng nghĩa: ask, inquire', 'Người Anh thường dùng enquire, trong khi người Mỹ thường dùng inquire.', 'I called the hotel to enquire about available rooms.', NULL, 'Tôi đã gọi điện đến khách sạn để hỏi về các phòng trống.', '{"wordId":"enquire","ukIpa":"/ɪnˈkwaɪə/","usIpa":"/ɪnˈkwaɪr/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To ask for information about something.","vi":"thưa hỏi; dò hỏi; điều tra"}],"examples":[{"en":"I called the hotel to enquire about available rooms.","vi":"Tôi đã gọi điện đến khách sạn để hỏi về các phòng trống.","audioKind":"ex"},{"en":"Prospective students should enquire about financial support before deciding which university course best suits their needs.","vi":"Sinh viên tương lai nên tìm hiểu về các khoản hỗ trợ tài chính trước khi quyết định khóa học đại học nào phù hợp nhất với nhu cầu của họ.","audioKind":"ex2"}],"collocations":[{"en":"enquire about prices","vi":"hỏi giá cả"},{"en":"enquire whether","vi":"hỏi xem liệu"},{"en":"enquire into a matter","vi":"điều tra một vấn đề"}],"wordFamily":["enquiry (n.)","enquirer (n.)"],"synonyms":["ask","inquire"],"antonyms":[],"tipVi":"Người Anh thường dùng enquire, trong khi người Mỹ thường dùng inquire.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_enlarge', 'en-b2-75', 'enlarge', '/ɪnˈlɑːrdʒ/', 'B2', 'làm lớn hơn; mở rộng; phóng to', 'v.', 'enlargement (n.), enlarged (adj.)', 'Đồng nghĩa: expand, magnify · Trái nghĩa: shrink, reduce', 'enlarge mang nghĩa làm lớn hơn; còn enlarge on mang nghĩa là trình bày hoặc giải thích chi tiết hơn.', 'Could you enlarge this photo so we can frame it?', NULL, 'Bạn có thể phóng to bức ảnh này để chúng tôi đem đi đóng khung được không?', '{"wordId":"enlarge","ukIpa":"/ɪnˈlɑːdʒ/","usIpa":"/ɪnˈlɑːrdʒ/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To become bigger or make something bigger.","vi":"làm lớn hơn; mở rộng; phóng to"}],"examples":[{"en":"Could you enlarge this photo so we can frame it?","vi":"Bạn có thể phóng to bức ảnh này để chúng tôi đem đi đóng khung được không?","audioKind":"ex"},{"en":"The council plans to enlarge the public library to accommodate growing demand for quiet study spaces.","vi":"Hội đồng thành phố có kế hoạch mở rộng thư viện công cộng để đáp ứng nhu cầu ngày càng tăng về không gian học tập yên tĩnh.","audioKind":"ex2"}],"collocations":[{"en":"enlarge a photo","vi":"phóng to một bức ảnh"},{"en":"enlarge an image","vi":"phóng to một hình ảnh"},{"en":"enlarge on a point","vi":"nói chi tiết hơn về một vấn đề"}],"wordFamily":["enlargement (n.)","enlarged (adj.)"],"synonyms":["expand","magnify"],"antonyms":["shrink","reduce"],"tipVi":"enlarge mang nghĩa làm lớn hơn; còn enlarge on mang nghĩa là trình bày hoặc giải thích chi tiết hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_opener', 'en-b2-75', 'opener', '/ˈoʊpənər/', 'B2', 'dụng cụ mở (chai, đồ hộp, v.v.); cái mở chai; cái mở hộp; sự kiện mở màn; trận đấu mở màn; tiết mục mở đầu', 'n.', 'open (v.), opening (n.)', NULL, 'Tên dụng cụ mở thường được ghép bằng danh từ chỉ vật đựng đi kèm với opener, ví dụ như can opener.', 'I keep the bottle opener in the kitchen drawer.', NULL, 'Tôi để cái mở chai ở trong ngăn kéo bếp.', '{"wordId":"opener","ukIpa":"/ˈəʊpənə/","usIpa":"/ˈoʊpənər/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"a tool used to open bottles, cans, or other containers","vi":"dụng cụ mở (chai, đồ hộp, v.v.); cái mở chai; cái mở hộp"},{"pos":"n.","en":"the first event or performance in a series","vi":"sự kiện mở màn; trận đấu mở màn; tiết mục mở đầu"}],"examples":[{"en":"I keep the bottle opener in the kitchen drawer.","vi":"Tôi để cái mở chai ở trong ngăn kéo bếp.","audioKind":"ex"},{"en":"The festival opener attracted a diverse audience, demonstrating the growing popularity of local cultural events.","vi":"Chương trình mở màn lễ hội đã thu hút đông đảo khán giả thuộc mọi thành phần, cho thấy mức độ quan tâm ngày càng lớn đối với các sự kiện văn hóa địa phương.","audioKind":"ex2"}],"collocations":[{"en":"bottle opener","vi":"dụng cụ mở chai"},{"en":"can opener","vi":"dụng cụ mở đồ hộp"},{"en":"season opener","vi":"trận đấu khai mạc mùa giải"}],"wordFamily":["open (v.)","opening (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tên dụng cụ mở thường được ghép bằng danh từ chỉ vật đựng đi kèm với opener, ví dụ như can opener.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_crate', 'en-b2-75', 'crate', '/kreɪt/', 'B2', 'thùng nan; thùng gỗ/nhựa đựng hàng; đóng vào thùng; xếp vào sọt', 'n.', NULL, NULL, 'Có thể chỉ thùng gỗ hoặc thùng nhựa vận chuyển; a crate of chỉ một thùng.', 'We carried a crate of apples into the kitchen.', NULL, 'Chúng tôi khiêng một thùng táo vào trong bếp.', '{"wordId":"crate","ukIpa":"/kreɪt/","usIpa":"/kreɪt/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A strong container used to store or transport goods.","vi":"thùng nan; thùng gỗ/nhựa đựng hàng"},{"pos":"v.","en":"To pack something into a strong container for transport.","vi":"đóng vào thùng; xếp vào sọt"}],"examples":[{"en":"We carried a crate of apples into the kitchen.","vi":"Chúng tôi khiêng một thùng táo vào trong bếp.","audioKind":"ex"},{"en":"Reusable plastic crates can reduce packaging waste when food suppliers establish reliable systems for collecting empty containers.","vi":"Các loại thùng nhựa có thể tái sử dụng có thể làm giảm lượng bao bì thải ra khi các nhà cung cấp thực phẩm thiết lập hệ thống thu gom vỏ thùng đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"a wooden crate","vi":"thùng gỗ"},{"en":"a crate of fruit","vi":"một thùng hoa quả"},{"en":"pack into crates","vi":"đóng vào thùng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Có thể chỉ thùng gỗ hoặc thùng nhựa vận chuyển; a crate of chỉ một thùng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mint', 'en-b2-75', 'mint', '/mɪnt/', 'B2', 'cây bạc hà; kẹo bạc hà; xưởng đúc tiền; đúc tiền kim loại', 'n.', 'minty (adj.), minting (n.)', NULL, 'Nghĩa thực vật thường không đếm được; a mint có thể chỉ một viên kẹo bạc hà.', 'I added fresh mint to the lemon water.', NULL, 'Tôi cho thêm bạc hà tươi vào cốc nước chanh.', '{"wordId":"mint","ukIpa":"/mɪnt/","usIpa":"/mɪnt/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"an aromatic herb, or a sweet flavored with it","vi":"cây bạc hà; kẹo bạc hà"},{"pos":"n.","en":"a place where coins are officially made","vi":"xưởng đúc tiền"},{"pos":"v.","en":"to make coins from metal","vi":"đúc tiền kim loại"}],"examples":[{"en":"I added fresh mint to the lemon water.","vi":"Tôi cho thêm bạc hà tươi vào cốc nước chanh.","audioKind":"ex"},{"en":"Growing herbs such as mint in urban gardens can provide fresh ingredients and encourage interest in food production.","vi":"Việc trồng các loại thảo mộc như bạc hà trong các khu vườn đô thị có thể cung cấp nguyên liệu tươi và khơi dậy sự quan tâm đến việc sản xuất thực phẩm.","audioKind":"ex2"}],"collocations":[{"en":"fresh mint","vi":"bạc hà tươi"},{"en":"mint tea","vi":"trà bạc hà"},{"en":"mint coins","vi":"đúc tiền xu"},{"en":"in mint condition","vi":"trong tình trạng hoàn hảo như mới"}],"wordFamily":["minty (adj.)","minting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa thực vật thường không đếm được; a mint có thể chỉ một viên kẹo bạc hà.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pail', 'en-b2-75', 'pail', '/peɪl/', 'B2', 'cái xách nước; cái thùng đựng nước', 'n.', 'pailful (n.)', 'Đồng nghĩa: bucket', 'Phát âm giống pale; trong tiếng Anh đời thường bucket phổ biến hơn.', 'She carried a pail of water into the garden.', NULL, 'Cô ấy xách một thùng nước đi vào khu vườn.', '{"wordId":"pail","ukIpa":"/peɪl/","usIpa":"/peɪl/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A handled container for carrying liquids, or the amount it holds.","vi":"cái xách nước; cái thùng đựng nước"}],"examples":[{"en":"She carried a pail of water into the garden.","vi":"Cô ấy xách một thùng nước đi vào khu vườn.","audioKind":"ex"},{"en":"In villages without reliable plumbing, residents may carry drinking water home in a pail.","vi":"Ở những ngôi làng chưa có hệ thống ống nước ổn định, người dân có thể phải xách nước sinh hoạt về nhà bằng xô.","audioKind":"ex2"}],"collocations":[{"en":"a pail of water","vi":"một xô nước"},{"en":"fill a pail","vi":"làm đầy một cái xô"},{"en":"milk pail","vi":"thùng vắt sữa"}],"wordFamily":["pailful (n.)"],"synonyms":["bucket"],"antonyms":[],"tipVi":"Phát âm giống pale; trong tiếng Anh đời thường bucket phổ biến hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_foul', 'en-b2-75', 'foul', '/faʊl/', 'B2', 'hôi hám; khó chịu; ghê tởm; lỗi phạt (trong thể thao); làm bẩn; làm ô nhiễm', 'adj.', 'foulness (n.)', NULL, 'Trong thể thao, lỗi phạt dùng commit a foul; thời tiết xấu cũng có thể gọi là foul weather.', 'A foul smell drifted from the forgotten rubbish bin.', NULL, 'Một mùi hôi thối nồng nặc bốc lên từ chiếc thùng rác bị bỏ quên.', '{"wordId":"foul","ukIpa":"/faʊl/","usIpa":"/faʊl/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Extremely unpleasant, especially in smell or taste.","vi":"hôi hám; khó chịu; ghê tởm"},{"pos":"n.","en":"An action that breaks the rules of a sport.","vi":"lỗi phạt (trong thể thao)"},{"pos":"v.","en":"To make something dirty or polluted.","vi":"làm bẩn; làm ô nhiễm"}],"examples":[{"en":"A foul smell drifted from the forgotten rubbish bin.","vi":"Một mùi hôi thối nồng nặc bốc lên từ chiếc thùng rác bị bỏ quên.","audioKind":"ex"},{"en":"Untreated industrial waste can foul rivers, threatening aquatic wildlife and the health of nearby communities.","vi":"Chất thải công nghiệp chưa qua xử lý có thể làm ô nhiễm các dòng sông, đe dọa động vật thủy sinh và sức khỏe của cư dân vùng lân cận.","audioKind":"ex2"}],"collocations":[{"en":"foul smell","vi":"mùi hôi thối"},{"en":"commit a foul","vi":"phạm lỗi"},{"en":"foul language","vi":"lời lẽ thô tục"},{"en":"foul weather","vi":"thời tiết xấu"}],"wordFamily":["foulness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong thể thao, lỗi phạt dùng commit a foul; thời tiết xấu cũng có thể gọi là foul weather.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_oval', 'en-b2-75', 'oval', '/ˈoʊvəl/', 'B2', 'hình bầu dục; hình trứng', 'adj.', NULL, 'Đồng nghĩa: elliptical, egg-shaped', 'oval có thể dùng làm tính từ hoặc danh từ; an oval nghĩa là một hình bầu dục.', 'She served the roast vegetables on an oval plate.', NULL, 'Cô ấy bày các món rau củ nướng trên một chiếc đĩa hình bầu dục.', '{"wordId":"oval","ukIpa":"/ˈəʊvəl/","usIpa":"/ˈoʊvəl/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Having a rounded shape that is longer than it is wide.","vi":"hình bầu dục; hình trứng"},{"pos":"n.","en":"A rounded shape that is longer than it is wide.","vi":"hình bầu dục"}],"examples":[{"en":"She served the roast vegetables on an oval plate.","vi":"Cô ấy bày các món rau củ nướng trên một chiếc đĩa hình bầu dục.","audioKind":"ex"},{"en":"The proposed park includes an oval pond surrounded by native plants to provide habitats for local wildlife.","vi":"Khu công viên được đề xuất bao gồm một cái ao hình bầu dục được bao quanh bởi các loài thực vật bản địa nhằm cung cấp môi trường sống cho động vật hoang dã địa phương.","audioKind":"ex2"}],"collocations":[{"en":"an oval face","vi":"khuôn mặt trái xoan"},{"en":"an oval table","vi":"một chiếc bàn hình bầu dục"},{"en":"oval in shape","vi":"có hình bầu dục"}],"wordFamily":[],"synonyms":["elliptical","egg-shaped"],"antonyms":[],"tipVi":"oval có thể dùng làm tính từ hoặc danh từ; an oval nghĩa là một hình bầu dục.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_extraordinary', 'en-b2-75', 'extraordinary', '/ɪkˈstrɔːrdəneri/', 'B2', 'phi thường; xuất sắc; đặc biệt; kỳ lạ', 'adj.', 'extraordinarily (adv.)', 'Đồng nghĩa: remarkable, exceptional · Trái nghĩa: ordinary', 'Nhấn mạnh vượt mức bình thường nhiều hơn từ very good, ngoài ra cũng có thể chỉ tính kỳ lạ.', 'My grandmother has an extraordinary memory for people''s birthdays.', NULL, 'Bà tôi có một trí nhớ phi thường về ngày sinh nhật của mọi người.', '{"wordId":"extraordinary","ukIpa":"/ɪkˈstrɔːdənəri/","usIpa":"/ɪkˈstrɔːrdəneri/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Much better or more impressive than usual.","vi":"phi thường; xuất sắc"},{"pos":"adj.","en":"Very unusual or surprising.","vi":"đặc biệt; kỳ lạ"}],"examples":[{"en":"My grandmother has an extraordinary memory for people''s birthdays.","vi":"Bà tôi có một trí nhớ phi thường về ngày sinh nhật của mọi người.","audioKind":"ex"},{"en":"Recent advances in medical technology demonstrate the extraordinary potential of cooperation between scientists and engineers.","vi":"Những tiến bộ gần đây trong công nghệ y tế cho thấy tiềm năng phi thường của sự hợp tác giữa các nhà khoa học và kỹ sư.","audioKind":"ex2"}],"collocations":[{"en":"extraordinary achievement","vi":"thành tựu phi thường"},{"en":"extraordinary ability","vi":"năng lực xuất sắc"},{"en":"extraordinary circumstances","vi":"tình huống đặc biệt"}],"wordFamily":["extraordinarily (adv.)"],"synonyms":["remarkable","exceptional"],"antonyms":["ordinary"],"tipVi":"Nhấn mạnh vượt mức bình thường nhiều hơn từ very good, ngoài ra cũng có thể chỉ tính kỳ lạ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_slip', 'en-b2-75', 'slip', '/slɪp/', 'B2', 'trượt chân; tuột; lén di chuyển; nhét nhanh; mẩu giấy nhỏ; lỗi nhỏ', 'v.', 'slippery (adj.)', NULL, 'Dạng quá khứ và quá khứ phân từ đều là slipped, gấp đôi chữ p.', 'I slipped on the wet floor but stayed upright.', NULL, 'Tôi bị trượt chân trên sàn nhà ướt nhưng vẫn giữ được thăng bằng không bị ngã.', '{"wordId":"slip","ukIpa":"/slɪp/","usIpa":"/slɪp/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To slide accidentally, losing balance or leaving a position.","vi":"trượt chân; tuột"},{"pos":"v.","en":"To move or put something somewhere quietly or quickly.","vi":"lén di chuyển; nhét nhanh"},{"pos":"n.","en":"A small piece of paper, or a minor mistake.","vi":"mẩu giấy nhỏ; lỗi nhỏ"}],"examples":[{"en":"I slipped on the wet floor but stayed upright.","vi":"Tôi bị trượt chân trên sàn nhà ướt nhưng vẫn giữ được thăng bằng không bị ngã.","audioKind":"ex"},{"en":"Hospitals should keep floors dry to reduce the risk of patients slipping and injuring themselves.","vi":"Các bệnh viện nên giữ cho sàn nhà khô ráo nhằm giảm nguy cơ bệnh nhân trượt ngã và tự làm thương chính mình.","audioKind":"ex2"}],"collocations":[{"en":"slip on ice","vi":"trượt ngã trên băng"},{"en":"slip into a room","vi":"lẻn vào phòng"},{"en":"a slip of paper","vi":"một mẩu giấy"},{"en":"a slip of the tongue","vi":"lỡ lời"}],"wordFamily":["slippery (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ và quá khứ phân từ đều là slipped, gấp đôi chữ p.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_struggle', 'en-b2-75', 'struggle', '/ˈstrʌɡəl/', 'B2', 'vật lộn; cố gắng hết sức; vùng vẫy; đấu tranh; sự đấu tranh; cuộc chiến đấu gian khổ', 'v.', 'struggling (adj.)', 'Đồng nghĩa: strive', 'struggle to do diễn tả việc làm gì đó rất mất sức, không đảm bảo thành công.', 'I struggled to carry the heavy bags up the stairs.', NULL, 'Tôi đã rất chật vật để khiêng những chiếc túi nặng lên cầu thang.', '{"wordId":"struggle","ukIpa":"/ˈstrʌɡəl/","usIpa":"/ˈstrʌɡəl/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To try very hard to do something difficult.","vi":"vật lộn; cố gắng hết sức"},{"pos":"v.","en":"To fight or move forcefully against someone or something.","vi":"vùng vẫy; đấu tranh"},{"pos":"n.","en":"A difficult effort to achieve something or overcome opposition.","vi":"sự đấu tranh; cuộc chiến đấu gian khổ"}],"examples":[{"en":"I struggled to carry the heavy bags up the stairs.","vi":"Tôi đã rất chật vật để khiêng những chiếc túi nặng lên cầu thang.","audioKind":"ex"},{"en":"Many young adults struggle to find affordable housing in cities where wages have not kept pace with rents.","vi":"Nhiều thanh niên chật vật tìm nhà ở giá rẻ ở những thành phố nơi mức lương không bắt kịp giá thuê nhà.","audioKind":"ex2"}],"collocations":[{"en":"struggle to do something","vi":"vật lộn để làm gì đó"},{"en":"struggle with something","vi":"đấu tranh với điều gì đó"},{"en":"struggle for survival","vi":"đấu tranh sinh tồn"},{"en":"an uphill struggle","vi":"cuộc đấu tranh gian nan"}],"wordFamily":["struggling (adj.)"],"synonyms":["strive"],"antonyms":[],"tipVi":"struggle to do diễn tả việc làm gì đó rất mất sức, không đảm bảo thành công.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dependable', 'en-b2-75', 'dependable', '/dɪˈpendəbəl/', 'B2', 'đáng tin cậy', 'adj.', 'depend (v.), dependability (n.), dependably (adv.)', 'Đồng nghĩa: reliable, trustworthy · Trái nghĩa: unreliable, undependable', 'dependable là đáng tin cậy; dependent là phụ thuộc vào người khác.', 'My old bicycle is still dependable in wet weather.', NULL, 'Chiếc xe đạp cũ của tôi vẫn rất đáng tin cậy trong thời tiết ẩm ướt.', '{"wordId":"dependable","ukIpa":"/dɪˈpendəbl/","usIpa":"/dɪˈpendəbəl/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"able to be trusted to do what is needed","vi":"đáng tin cậy"}],"examples":[{"en":"My old bicycle is still dependable in wet weather.","vi":"Chiếc xe đạp cũ của tôi vẫn rất đáng tin cậy trong thời tiết ẩm ướt.","audioKind":"ex"},{"en":"Dependable public transport enables workers to reach their workplaces consistently and reduces reliance on private cars.","vi":"Hệ thống giao thông công cộng đáng tin cậy giúp người lao động đi làm ổn định và giảm sự phụ thuộc vào xe cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"dependable service","vi":"dịch vụ đáng tin cậy"},{"en":"dependable colleague","vi":"đồng nghiệp đáng tin cậy"},{"en":"dependable source","vi":"nguồn tin đáng tin cậy"}],"wordFamily":["depend (v.)","dependability (n.)","dependably (adv.)"],"synonyms":["reliable","trustworthy"],"antonyms":["unreliable","undependable"],"tipVi":"dependable là đáng tin cậy; dependent là phụ thuộc vào người khác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fabric', 'en-b2-75', 'fabric', '/ˈfæbrɪk/', 'B2', 'vải; chất liệu vải; cấu trúc; kết cấu (của xã hội hoặc tổ chức)', 'n.', NULL, 'Đồng nghĩa: cloth, material', 'Chỉ chung chất liệu vải thường không đếm được; các loại vải khác nhau dùng fabrics.', 'This soft fabric will make a comfortable summer dress.', NULL, 'Chất liệu vải mềm mại này sẽ tạo nên một chiếc váy mùa hè thoải mái.', '{"wordId":"fabric","ukIpa":"/ˈfæbrɪk/","usIpa":"/ˈfæbrɪk/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"material made by weaving or knitting fibres","vi":"vải; chất liệu vải"},{"pos":"n.","en":"the connected parts that form a society or organisation","vi":"cấu trúc; kết cấu (của xã hội hoặc tổ chức)"}],"examples":[{"en":"This soft fabric will make a comfortable summer dress.","vi":"Chất liệu vải mềm mại này sẽ tạo nên một chiếc váy mùa hè thoải mái.","audioKind":"ex"},{"en":"Community centres strengthen the social fabric by bringing together residents from different cultural and economic backgrounds.","vi":"Các trung tâm cộng đồng củng cố kết cấu xã hội bằng cách kết nối cư dân từ các nền tảng văn hóa và kinh tế khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"cotton fabric","vi":"vải cotton"},{"en":"synthetic fabric","vi":"vải sợi tổng hợp"},{"en":"the social fabric","vi":"cấu trúc xã hội"}],"wordFamily":[],"synonyms":["cloth","material"],"antonyms":[],"tipVi":"Chỉ chung chất liệu vải thường không đếm được; các loại vải khác nhau dùng fabrics.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_urgently', 'en-b2-75', 'urgently', '/ˈɝːdʒəntli/', 'B2', 'khẩn cấp; cấp bách', 'adv.', 'urgent (adj.), urgency (n.)', NULL, 'Nhấn mạnh việc cần xử lý ngay lập tức thay vì chỉ làm nhanh chóng.', 'We urgently need a plumber to fix this leak.', NULL, 'Chúng tôi đang cần gấp thợ sửa ống nước để khắc phục chỗ rò rỉ này.', '{"wordId":"urgently","ukIpa":"/ˈɜːdʒəntli/","usIpa":"/ˈɝːdʒəntli/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"in a way that requires immediate action or attention","vi":"khẩn cấp; cấp bách"}],"examples":[{"en":"We urgently need a plumber to fix this leak.","vi":"Chúng tôi đang cần gấp thợ sửa ống nước để khắc phục chỗ rò rỉ này.","audioKind":"ex"},{"en":"Governments must urgently address water shortages through improved infrastructure and policies that encourage responsible consumption.","vi":"Chính phủ phải khẩn cấp giải quyết tình trạng thiếu nước thông qua việc cải thiện cơ sở hạ tầng và các chính sách khuyến khích tiêu thụ có trách nhiệm.","audioKind":"ex2"}],"collocations":[{"en":"urgently needed","vi":"cần gấp"},{"en":"urgently require","vi":"đòi hỏi cấp bách"},{"en":"act urgently","vi":"hành động khẩn trương"}],"wordFamily":["urgent (adj.)","urgency (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nhấn mạnh việc cần xử lý ngay lập tức thay vì chỉ làm nhanh chóng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_strip', 'en-b2-75', 'strip', '/strɪp/', 'B2', 'dải; mảnh nhỏ; lột bỏ; cởi bỏ; tước đoạt', 'n.', 'stripped (adj.)', NULL, 'Quá khứ của strip là stripped; tước đoạt dùng cấu trúc strip sb of sth.', 'Cut the paper into strips for our craft project.', NULL, 'Cắt giấy thành các dải để làm đồ thủ công của chúng ta nhé.', '{"wordId":"strip","ukIpa":"/strɪp/","usIpa":"/strɪp/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A long, narrow piece or area of something.","vi":"dải; mảnh nhỏ"},{"pos":"v.","en":"To remove a covering or layer from something.","vi":"lột bỏ; cởi bỏ"},{"pos":"v.","en":"To take away someone''s rights, possessions, or position.","vi":"tước đoạt"}],"examples":[{"en":"Cut the paper into strips for our craft project.","vi":"Cắt giấy thành các dải để làm đồ thủ công của chúng ta nhé.","audioKind":"ex"},{"en":"Planting strips of wildflowers beside farmland can provide habitats for insects and support local biodiversity.","vi":"Trồng các dải hoa dại bên cạnh đất nông nghiệp có thể tạo môi trường sống cho côn trùng và hỗ trợ đa dạng sinh học địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a strip of paper","vi":"một dải giấy"},{"en":"strip paint","vi":"tẩy sơn"},{"en":"strip someone of their rights","vi":"tước đoạt quyền lợi của ai đó"}],"wordFamily":["stripped (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Quá khứ của strip là stripped; tước đoạt dùng cấu trúc strip sb of sth.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_75_1', 'en-b2-75', 'Cách dùng “filthy” (adj.) — bẩn thỉu; dơ dáy', 'filthy clothes  ·  filthy conditions  ·  filthy language', 'Mang sắc thái mạnh hơn từ dirty, diễn tả mức độ rất bẩn; ngoài ra cũng dùng để miêu tả ngôn từ thô tục.', 'Họ từ (Word Family): filth (n.), filthiness (n.) | Đồng nghĩa: grimy, disgusting · Trái nghĩa: clean, spotless', '[{"hanzi":"Your boots are filthy after that walk through the fields.","pinyin":"","meaning":"Đôi bốt của bạn bẩn thỉu sau chuyến đi bộ băng qua các cánh đồng."},{"hanzi":"Filthy water supplies increase the risk of disease, particularly in communities without adequate sanitation infrastructure.","pinyin":"","meaning":"Nguồn nước bẩn thỉu làm tăng nguy cơ mắc bệnh, đặc biệt là ở các cộng đồng thiếu cơ sở hạ tầng vệ sinh đầy đủ."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_75_2', 'en-b2-75', 'Cách dùng “enlarge” (v.) — làm lớn hơn; mở rộng; phóng to', 'enlarge a photo  ·  enlarge an image  ·  enlarge on a point', 'enlarge mang nghĩa làm lớn hơn; còn enlarge on mang nghĩa là trình bày hoặc giải thích chi tiết hơn.', 'Họ từ (Word Family): enlargement (n.), enlarged (adj.) | Đồng nghĩa: expand, magnify · Trái nghĩa: shrink, reduce', '[{"hanzi":"Could you enlarge this photo so we can frame it?","pinyin":"","meaning":"Bạn có thể phóng to bức ảnh này để chúng tôi đem đi đóng khung được không?"},{"hanzi":"The council plans to enlarge the public library to accommodate growing demand for quiet study spaces.","pinyin":"","meaning":"Hội đồng thành phố có kế hoạch mở rộng thư viện công cộng để đáp ứng nhu cầu ngày càng tăng về không gian học tập yên tĩnh."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_75_3', 'en-b2-75', 'Cách dùng “opener” (n.) — dụng cụ mở (chai, đồ hộp, v.v.); cái mở chai; cái mở hộp', 'bottle opener  ·  can opener  ·  season opener', 'Tên dụng cụ mở thường được ghép bằng danh từ chỉ vật đựng đi kèm với opener, ví dụ như can opener.', 'Họ từ (Word Family): open (v.), opening (n.)', '[{"hanzi":"I keep the bottle opener in the kitchen drawer.","pinyin":"","meaning":"Tôi để cái mở chai ở trong ngăn kéo bếp."},{"hanzi":"The festival opener attracted a diverse audience, demonstrating the growing popularity of local cultural events.","pinyin":"","meaning":"Chương trình mở màn lễ hội đã thu hút đông đảo khán giả thuộc mọi thành phần, cho thấy mức độ quan tâm ngày càng lớn đối với các sự kiện văn hóa địa phương."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_75_4', 'en-b2-75', 'Cách dùng “uneven” (adj.) — gập ghềnh; không bằng phẳng; nhấp nhô', 'uneven ground  ·  uneven distribution  ·  uneven development', 'Số lẻ dùng odd, không dùng uneven; uneven nhấn mạnh sự không bằng phẳng hoặc không đồng đều.', 'Họ từ (Word Family): even (adj.), unevenly (adv.), unevenness (n.) | Đồng nghĩa: irregular · Trái nghĩa: even', '[{"hanzi":"Watch your step on the uneven stones outside.","pinyin":"","meaning":"Hãy chú ý bước chân trên những hòn đá gập ghềnh ở bên ngoài."},{"hanzi":"Uneven access to digital technology can widen educational inequalities between urban and rural communities.","pinyin":"","meaning":"Khả năng tiếp cận công nghệ số không đồng đều có thể nới rộng khoảng cách giáo dục giữa các cộng đồng thành thị và nông thôn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_75_1', 'en-b2-75', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
