INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_75_1_2', 'ten_b2_75_1', 'imitate', 'Our little sister loves to imitate animal sounds.', 'Our little sister loves to imitate animal sounds.', '/ˈɪmɪteɪt/', 'Em gái nhỏ của chúng tôi rất thích bắt chước tiếng kêu của động vật.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_75_1_3', 'ten_b2_75_1', 'overflow', 'The bath overflowed while I was answering the door.', 'The bath overflowed while I was answering the door.', '/ˌoʊvərˈfloʊ/', 'Bồn tắm đã bị tràn nước trong lúc tôi ra mở cửa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_75_1_4', 'ten_b2_75_1', 'occasionally', 'We occasionally buy fresh bread from the market.', 'We occasionally buy fresh bread from the market.', '/əˈkeɪʒənəli/', 'Thỉnh thoảng chúng tôi mua bánh mì tươi ở chợ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_75_1_5', 'ten_b2_75_1', 'tighten', 'Please tighten the lid before you shake the bottle.', 'Please tighten the lid before you shake the bottle.', '/ˈtaɪtən/', 'Vui lòng vặn chặt nắp trước khi bạn lắc chai.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_75_1_6', 'ten_b2_75_1', 'uneven', 'Watch your step on the uneven stones outside.', 'Watch your step on the uneven stones outside.', '/ʌnˈiːvən/', 'Hãy chú ý bước chân trên những hòn đá gập ghềnh ở bên ngoài.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_75_1_7', 'ten_b2_75_1', 'drill', 'I borrowed a drill to put up the shelf.', 'I borrowed a drill to put up the shelf.', '/drɪl/', 'Tôi đã mượn một cái khoan để lắp chiếc kệ lên.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_75_1_8', 'ten_b2_75_1', 'enclose', 'A low stone wall encloses our sunny back garden.', 'A low stone wall encloses our sunny back garden.', '/ɪnˈkloʊz/', 'Một bức tường đá thấp bao quanh khu vườn phía sau đầy nắng của chúng tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_75_1_1', 'en-b2-75', 'ten_b2_75_1', 'listening', 'listening', 'The beach was largely empty when we arrived.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bãi biển hầu như vắng bóng người khi chúng tôi đến nơi.","Chiếc xe đạp cũ của tôi vẫn rất đáng tin cậy trong thời tiết ẩm ướt.","Tôi đã rất chật vật để khiêng những chiếc túi nặng lên cầu thang.","Đôi bốt của bạn bẩn thỉu sau chuyến đi bộ băng qua các cánh đồng."]'::jsonb, 0, 'The beach was largely empty when we arrived. → Bãi biển hầu như vắng bóng người khi chúng tôi đến nơi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_75_1_2', 'en-b2-75', 'ten_b2_75_1', 'listening', 'listening', 'Our little sister loves to imitate animal sounds.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi đã mượn một cái khoan để lắp chiếc kệ lên.","Cô ấy bày các món rau củ nướng trên một chiếc đĩa hình bầu dục.","Em gái nhỏ của chúng tôi rất thích bắt chước tiếng kêu của động vật.","Chất liệu vải mềm mại này sẽ tạo nên một chiếc váy mùa hè thoải mái."]'::jsonb, 2, 'Our little sister loves to imitate animal sounds. → Em gái nhỏ của chúng tôi rất thích bắt chước tiếng kêu của động vật.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_75_1_3', 'en-b2-75', 'ten_b2_75_1', 'listening', 'listening', 'The bath overflowed while I was answering the door.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chiếc xe đạp cũ của tôi vẫn rất đáng tin cậy trong thời tiết ẩm ướt.","Tôi đã gọi điện đến khách sạn để hỏi về các phòng trống.","Cô ấy xách một thùng nước đi vào khu vườn.","Bồn tắm đã bị tràn nước trong lúc tôi ra mở cửa."]'::jsonb, 3, 'The bath overflowed while I was answering the door. → Bồn tắm đã bị tràn nước trong lúc tôi ra mở cửa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_75_2', 'en-b2-75', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_75_2_1', 'ten_b2_75_2', 'largely', 'The success of public health campaigns depends largely on clear communication and widespread community trust.', 'The success of public health campaigns depends largely on clear communication and widespread community trust.', '/ˈlɑːrdʒli/', 'Sự thành công của các chiến dịch y tế công cộng phần lớn phụ thuộc vào giao tiếp minh bạch và niềm tin sâu rộng trong cộng đồng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_75_2_2', 'ten_b2_75_2', 'imitate', 'Young children often imitate adult behaviour, so parents play an important role in developing healthy habits.', 'Young children often imitate adult behaviour, so parents play an important role in developing healthy habits.', '/ˈɪmɪteɪt/', 'Trẻ nhỏ thường bắt chước hành vi của người lớn, do đó cha mẹ đóng vai trò quan trọng trong việc hình thành các thói quen lành mạnh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_75_2_3', 'ten_b2_75_2', 'overflow', 'During heavy rainfall, urban drains may overflow and carry polluted water into nearby rivers.', 'During heavy rainfall, urban drains may overflow and carry polluted water into nearby rivers.', '/ˌoʊvərˈfloʊ/', 'Trong những trận mưa lớn, hệ thống thoát nước đô thị có thể bị quá tải và mang nước ô nhiễm đổ ra các con sông gần đó.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_75_2_4', 'ten_b2_75_2', 'occasionally', 'Employees who occasionally work from home may benefit from greater flexibility without losing regular contact with colleagues.', 'Employees who occasionally work from home may benefit from greater flexibility without losing regular contact with colleagues.', '/əˈkeɪʒənəli/', 'Những nhân viên thỉnh thoảng làm việc tại nhà có thể hưởng lợi từ sự linh hoạt cao hơn mà không làm mất đi sự liên lạc thường xuyên với đồng nghiệp.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_75_2_5', 'ten_b2_75_2', 'tighten', 'Governments should tighten safety regulations to ensure that all new housing meets acceptable standards of construction.', 'Governments should tighten safety regulations to ensure that all new housing meets acceptable standards of construction.', '/ˈtaɪtən/', 'Chính phủ nên thắt chặt các quy định an toàn để đảm bảo tất cả nhà ở mới xây đều đạt tiêu chuẩn xây dựng có thể chấp nhận được.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_75_2_6', 'ten_b2_75_2', 'uneven', 'Uneven access to digital technology can widen educational inequalities between urban and rural communities.', 'Uneven access to digital technology can widen educational inequalities between urban and rural communities.', '/ʌnˈiːvən/', 'Khả năng tiếp cận công nghệ số không đồng đều có thể nới rộng khoảng cách giáo dục giữa các cộng đồng thành thị và nông thôn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_75_2_1', 'en-b2-75', 'ten_b2_75_2', 'listening', 'listening', 'The success of public health campaigns depends largely on clear communication and widespread community trust.', NULL, 'Trong câu vừa nghe, từ “largely” mang nghĩa nào sau đây?', '["nhà phân phối; thương gia; người buôn bán","chủ yếu; phần lớn; ở mức độ lớn","bất an; lo âu; bồn chồn","nghe chừng; hình như; có vẻ như"]'::jsonb, 1, '“largely” (/ˈlɑːrdʒli/): chủ yếu; phần lớn; ở mức độ lớn. Câu đầy đủ: The success of public health campaigns depends largely on clear communication and widespread community trust.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_75_2_2', 'en-b2-75', 'ten_b2_75_2', 'listening', 'listening', 'Young children often imitate adult behaviour, so parents play an important role in developing healthy habits.', NULL, 'Trong câu vừa nghe, từ “imitate” mang nghĩa nào sau đây?', '["bắt chước; mô phỏng","tuyển dụng; chiêu mộ; tuyển","động từ: phản đối; chống lại","vỏ bần; gỗ bần"]'::jsonb, 0, '“imitate” (/ˈɪmɪteɪt/): bắt chước; mô phỏng. Câu đầy đủ: Young children often imitate adult behaviour, so parents play an important role in developing healthy habits.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
