INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_75_2', 'en-b2-75', NULL, 'comprehensive_test', 'listening', 'Our little sister loves to imitate animal sounds.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã rất chật vật để khiêng những chiếc túi nặng lên cầu thang.","Em gái nhỏ của chúng tôi rất thích bắt chước tiếng kêu của động vật.","Chất liệu vải mềm mại này sẽ tạo nên một chiếc váy mùa hè thoải mái.","Chúng tôi khiêng một thùng táo vào trong bếp."]'::jsonb, 1, 'Our little sister loves to imitate animal sounds. → Em gái nhỏ của chúng tôi rất thích bắt chước tiếng kêu của động vật.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_75_3', 'en-b2-75', NULL, 'comprehensive_test', 'listening', 'overflow', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["xác tàu đắm; phương tiện bị hư hỏng nặng","tràn ra; ngập","lỗ thủng; vết thủng lốp","gấp ba; gồm ba phần"]'::jsonb, 1, 'overflow (/ˌoʊvərˈfloʊ/) → tràn ra; ngập; chứa đầy; đông nghịt; chất tràn; lượng nước tràn', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_75_4', 'en-b2-75', NULL, 'comprehensive_test', 'listening', 'We occasionally buy fresh bread from the market.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đang cần gấp thợ sửa ống nước để khắc phục chỗ rò rỉ này.","Thỉnh thoảng chúng tôi mua bánh mì tươi ở chợ.","Một bức tường đá thấp bao quanh khu vườn phía sau đầy nắng của chúng tôi.","Tôi bị trượt chân trên sàn nhà ướt nhưng vẫn giữ được thăng bằng không bị ngã."]'::jsonb, 1, 'We occasionally buy fresh bread from the market. → Thỉnh thoảng chúng tôi mua bánh mì tươi ở chợ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_75_5', 'en-b2-75', NULL, 'comprehensive_test', 'listening', 'tighten', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["vặn chặt; siết chặt; làm cho căng hơn","nóng như đổ lửa; oi bức","tính chính xác; độ chính xác","gãy bẻ bộp; đứt phựt"]'::jsonb, 0, 'tighten (/ˈtaɪtən/) → vặn chặt; siết chặt; làm cho căng hơn; thắt chặt; tăng cường kiểm soát (quy định, luật lệ)', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_75_6', 'en-b2-75', NULL, 'comprehensive_test', 'listening', 'Watch your step on the uneven stones outside.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã mượn một cái khoan để lắp chiếc kệ lên.","Thỉnh thoảng chúng tôi mua bánh mì tươi ở chợ.","Hãy chú ý bước chân trên những hòn đá gập ghềnh ở bên ngoài.","Tôi đã thái lát một củ cải giòn vào món salad bữa trưa."]'::jsonb, 2, 'Watch your step on the uneven stones outside. → Hãy chú ý bước chân trên những hòn đá gập ghềnh ở bên ngoài.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_75_7', 'en-b2-75', NULL, 'comprehensive_test', 'listening', 'drill', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đồ uống; thức uống (như trà, nước ép, cà phê)","máy khoan; cái khoan","vui mừng; hân hoan; mang lại niềm vui","ra hoa; nở hoa"]'::jsonb, 1, 'drill (/drɪl/) → máy khoan; cái khoan; cuộc diễn tập; bài tập rèn luyện; khoan; luyện tập lặp đi lặp lại', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_75_8', 'en-b2-75', NULL, 'comprehensive_test', 'listening', 'A low stone wall encloses our sunny back garden.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi bị trượt chân trên sàn nhà ướt nhưng vẫn giữ được thăng bằng không bị ngã.","Cô ấy bày các món rau củ nướng trên một chiếc đĩa hình bầu dục.","Một bức tường đá thấp bao quanh khu vườn phía sau đầy nắng của chúng tôi.","Tôi đã rất chật vật để khiêng những chiếc túi nặng lên cầu thang."]'::jsonb, 2, 'A low stone wall encloses our sunny back garden. → Một bức tường đá thấp bao quanh khu vườn phía sau đầy nắng của chúng tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_75_9', 'en-b2-75', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To make or become tighter or more firmly fixed.”?', '["crate","fabric","tighten","fuss"]'::jsonb, 2, 'tighten (/ˈtaɪtən/) → vặn chặt; siết chặt; làm cho căng hơn', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_75_10', 'en-b2-75', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “not level, flat, or smooth”?', '["oval","foul","uneven","fabric"]'::jsonb, 2, 'uneven (/ʌnˈiːvən/) → gập ghềnh; không bằng phẳng; nhấp nhô', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_75_11', 'en-b2-75', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a tool or machine used to make holes”?', '["foul","opener","pail","drill"]'::jsonb, 3, 'drill (/drɪl/) → máy khoan; cái khoan', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_75_12', 'en-b2-75', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To surround something with a wall, fence, or other barrier.”?', '["fuss","overflow","occasionally","enclose"]'::jsonb, 3, 'enclose (/ɪnˈkloʊz/) → bao quanh; rào lại', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
