INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_75_18', 'en-b2-75', NULL, 'comprehensive_test', 'reading', NULL, 'The success of public health campaigns depends largely on clear communication and widespread community trust.', 'Dựa vào câu trên, từ “largely” có nghĩa phù hợp nhất là gì?', '["ngân sách; khoản kinh phí","cư dân; người dân","chủ yếu; phần lớn; ở mức độ lớn","chinh phục; chiếm đóng"]'::jsonb, 2, 'largely: chủ yếu; phần lớn; ở mức độ lớn. Dịch cả câu: Sự thành công của các chiến dịch y tế công cộng phần lớn phụ thuộc vào giao tiếp minh bạch và niềm tin sâu rộng trong cộng đồng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_75_19', 'en-b2-75', NULL, 'comprehensive_test', 'reading', NULL, 'Young children often imitate adult behaviour, so parents play an important role in developing healthy habits.', 'Dựa vào câu trên, từ “imitate” có nghĩa phù hợp nhất là gì?', '["nhanh chóng; tốc độ cao","tốn thời gian; mất nhiều thời gian","bắt chước; mô phỏng","hạnh phúc; sự an sinh; phúc lợi"]'::jsonb, 2, 'imitate: bắt chước; mô phỏng; làm giả; nhái theo. Dịch cả câu: Trẻ nhỏ thường bắt chước hành vi của người lớn, do đó cha mẹ đóng vai trò quan trọng trong việc hình thành các thói quen lành mạnh.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_75_20', 'en-b2-75', NULL, 'comprehensive_test', 'reading', NULL, 'During heavy rainfall, urban drains may overflow and carry polluted water into nearby rivers.', 'Dựa vào câu trên, từ “overflow” có nghĩa phù hợp nhất là gì?', '["cấp cao; thâm niên","sự can thiệp; sự nhúng tay","tràn ra; ngập","quá hạn; chậm trả; chậm trễ"]'::jsonb, 2, 'overflow: tràn ra; ngập; chứa đầy; đông nghịt; chất tràn; lượng nước tràn. Dịch cả câu: Trong những trận mưa lớn, hệ thống thoát nước đô thị có thể bị quá tải và mang nước ô nhiễm đổ ra các con sông gần đó.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_75_21', 'en-b2-75', NULL, 'comprehensive_test', 'reading', NULL, 'Employees who occasionally work from home may benefit from greater flexibility without losing regular contact with colleagues.', 'Dựa vào câu trên, từ “occasionally” có nghĩa phù hợp nhất là gì?', '["sự thú nhận; lời khai nhận đã làm điều gì sai trái","một cách cung kính; một cách tôn trọng","phân phát; phân phối","thỉnh thoảng; đôi khi"]'::jsonb, 3, 'occasionally: thỉnh thoảng; đôi khi. Dịch cả câu: Những nhân viên thỉnh thoảng làm việc tại nhà có thể hưởng lợi từ sự linh hoạt cao hơn mà không làm mất đi sự liên lạc thường xuyên với đồng nghiệp.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
