INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-76', 'en', 'Bài 76: Đời sống hằng ngày (3) - CEFR B2', 'CEFR B2', 'B2 · Đời sống', '27 từ vựng Tiếng Anh CEFR B2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4076, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_constantly', 'en-b2-76', 'constantly', '/ˈkɑːnstəntli/', 'B2', 'liên tục; luôn luôn; thường xuyên', 'adv.', 'constant (adj.), constancy (n.)', 'Đồng nghĩa: continually, incessantly · Trái nghĩa: rarely', 'Từ này có mức độ mạnh hơn ''often'', nhấn mạnh sự việc diễn ra liên hồi hoặc lặp lại không dứt.', 'My phone constantly buzzes while I am cooking dinner.', NULL, 'Điện thoại của tôi cứ rung liên tục trong lúc tôi đang nấu bữa tối.', '{"wordId":"constantly","ukIpa":"/ˈkɒnstəntli/","usIpa":"/ˈkɑːnstəntli/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"All the time, or repeatedly with very little interruption.","vi":"liên tục; luôn luôn; thường xuyên"}],"examples":[{"en":"My phone constantly buzzes while I am cooking dinner.","vi":"Điện thoại của tôi cứ rung liên tục trong lúc tôi đang nấu bữa tối.","audioKind":"ex"},{"en":"Workers must constantly update their skills to remain competitive in a rapidly changing labour market.","vi":"Người lao động phải không ngừng cập nhật kỹ năng của mình để duy trì tính cạnh tranh trong một thị trường lao động thay đổi nhanh chóng.","audioKind":"ex2"}],"collocations":[{"en":"constantly changing","vi":"thay đổi không ngừng"},{"en":"constantly monitor","vi":"giám sát liên tục"},{"en":"constantly remind","vi":"nhắc nhở liên tục"}],"wordFamily":["constant (adj.)","constancy (n.)"],"synonyms":["continually","incessantly"],"antonyms":["rarely"],"tipVi":"Từ này có mức độ mạnh hơn ''often'', nhấn mạnh sự việc diễn ra liên hồi hoặc lặp lại không dứt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_loop', 'en-b2-76', 'loop', '/luːp/', 'B2', 'vòng; thòng lọng; đường đi hình vòng; uốn thành vòng; lặp lại liên tục; vòng lặp', 'n.', NULL, NULL, 'on a loop chỉ việc lặp lại liên tục, chẳng hạn như nhạc được phát lặp đi lặp lại.', 'She made a loop in the rope for hanging plants.', NULL, 'Cô ấy thắt sợi dây thành một vòng để treo chậu cây.', '{"wordId":"loop","ukIpa":"/luːp/","usIpa":"/luːp/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"a curved shape or route that returns to its starting point","vi":"vòng; thòng lọng; đường đi hình vòng"},{"pos":"v.","en":"to form a loop or repeat something continuously","vi":"uốn thành vòng; lặp lại liên tục"},{"pos":"n.","en":"a sequence of actions or instructions that repeats","vi":"vòng lặp"}],"examples":[{"en":"She made a loop in the rope for hanging plants.","vi":"Cô ấy thắt sợi dây thành một vòng để treo chậu cây.","audioKind":"ex"},{"en":"A bus route forming a loop can connect residential areas with schools and local health centres.","vi":"Một tuyến xe buýt chạy theo đường vòng có thể kết nối các khu dân cư với trường học và các trung tâm y tế địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a loop of rope","vi":"một vòng dây"},{"en":"on a loop","vi":"chạy lặp lại"},{"en":"feedback loop","vi":"vòng lặp phản hồi"},{"en":"loop around","vi":"vòng quanh"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"on a loop chỉ việc lặp lại liên tục, chẳng hạn như nhạc được phát lặp đi lặp lại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_newly', 'en-b2-76', 'newly', '/ˈnuːli/', 'B2', 'mới đây; gần đây', 'adv.', 'new (adj.), newness (n.)', 'Đồng nghĩa: recently', 'Thường đứng trước phân từ quá khứ như newly built để chỉ sự việc vừa mới hoàn thành.', 'We ate lunch in the newly opened corner café.', NULL, 'Chúng tôi đã ăn trưa tại quán cà phê góc phố mới mở.', '{"wordId":"newly","ukIpa":"/ˈnjuːli/","usIpa":"/ˈnuːli/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"Recently, especially when describing something just done or begun.","vi":"mới đây; gần đây"}],"examples":[{"en":"We ate lunch in the newly opened corner café.","vi":"Chúng tôi đã ăn trưa tại quán cà phê góc phố mới mở.","audioKind":"ex"},{"en":"Newly qualified teachers often need additional support to manage diverse classrooms effectively during their first year.","vi":"Những giáo viên mới vào nghề thường cần thêm sự hỗ trợ để quản lý các lớp học đa dạng học sinh một cách hiệu quả trong năm đầu tiên.","audioKind":"ex2"}],"collocations":[{"en":"newly built","vi":"mới xây"},{"en":"newly qualified","vi":"mới có chứng chỉ"},{"en":"newly elected","vi":"mới đắc cử"},{"en":"newly discovered","vi":"mới được phát hiện"}],"wordFamily":["new (adj.)","newness (n.)"],"synonyms":["recently"],"antonyms":[],"tipVi":"Thường đứng trước phân từ quá khứ như newly built để chỉ sự việc vừa mới hoàn thành.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_additional', 'en-b2-76', 'additional', '/əˈdɪʃənəl/', 'B2', 'thêm; bổ sung; phụ', 'adj.', 'add (v.), addition (n.), additionally (adv.)', 'Đồng nghĩa: extra, further', 'Thường đặt trước danh từ; additional costs chỉ các khoản phí phát sinh thêm.', 'We need an additional chair for our guest tonight.', NULL, 'Chúng ta cần thêm một chiếc ghế cho vị khách tối nay.', '{"wordId":"additional","ukIpa":"/əˈdɪʃənəl/","usIpa":"/əˈdɪʃənəl/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Added to what already exists or is available.","vi":"thêm; bổ sung; phụ"}],"examples":[{"en":"We need an additional chair for our guest tonight.","vi":"Chúng ta cần thêm một chiếc ghế cho vị khách tối nay.","audioKind":"ex"},{"en":"Universities should provide additional financial support for students who cannot afford essential learning materials.","vi":"Các trường đại học nên cung cấp thêm hỗ trợ tài chính cho những sinh viên không có khả năng chi trả cho các tài liệu học tập thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"additional costs","vi":"chi phí phát sinh"},{"en":"additional information","vi":"thông tin bổ sung"},{"en":"additional support","vi":"sự hỗ trợ thêm"},{"en":"an additional charge","vi":"khoản phí phụ thu"}],"wordFamily":["add (v.)","addition (n.)","additionally (adv.)"],"synonyms":["extra","further"],"antonyms":[],"tipVi":"Thường đặt trước danh từ; additional costs chỉ các khoản phí phát sinh thêm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_slight', 'en-b2-76', 'slight', '/slaɪt/', 'B2', 'nhỏ; nhẹ; mong manh; không đáng kể; mỏng manh; mảnh dẻ; làm ai phật lòng; xem thường', 'adj.', 'slightly (adv.), slightness (n.)', 'Đồng nghĩa: minor, small · Trái nghĩa: considerable, significant', 'slight là tính từ; bổ nghĩa cho động từ hoặc dùng ở dạng so sánh hơn thì dùng slightly.', 'There is a slight scratch on my new phone.', NULL, 'Có một vết xước nhẹ trên chiếc điện thoại mới của tôi.', '{"wordId":"slight","ukIpa":"/slaɪt/","usIpa":"/slaɪt/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"small in amount, degree, or importance","vi":"nhỏ; nhẹ; mong manh; không đáng kể"},{"pos":"adj.","en":"thin and delicately built","vi":"mỏng manh; mảnh dẻ"},{"pos":"v.","en":"to insult someone by ignoring them or showing little respect","vi":"làm ai phật lòng; xem thường"}],"examples":[{"en":"There is a slight scratch on my new phone.","vi":"Có một vết xước nhẹ trên chiếc điện thoại mới của tôi.","audioKind":"ex"},{"en":"Even a slight increase in average temperatures can have significant consequences for fragile ecosystems worldwide.","vi":"Ngay cả một sự gia tăng nhỏ về nhiệt độ trung bình cũng có thể gây ra hậu quả đáng kể cho các hệ sinh thái mỏng manh trên toàn thế giới.","audioKind":"ex2"}],"collocations":[{"en":"a slight increase","vi":"sự gia tăng nhỏ"},{"en":"a slight difference","vi":"sự khác biệt nhỏ"},{"en":"a slight delay","vi":"sự chậm trễ nhỏ"},{"en":"a slight chance","vi":"khả năng rất nhỏ"}],"wordFamily":["slightly (adv.)","slightness (n.)"],"synonyms":["minor","small"],"antonyms":["considerable","significant"],"tipVi":"slight là tính từ; bổ nghĩa cho động từ hoặc dùng ở dạng so sánh hơn thì dùng slightly.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_expire', 'en-b2-76', 'expire', '/ɪkˈspaɪr/', 'B2', 'hết hạn; hết hiệu lực', 'v.', 'expiry (n.), expiration (n.)', 'Đồng nghĩa: run out', 'Là nội động từ: hợp đồng hết hạn dùng expires, không dùng is expired.', 'My passport expires next month, so I must renew it.', NULL, 'Hộ chiếu của tôi hết hạn vào tháng tới, nên tôi phải đi gia hạn.', '{"wordId":"expire","ukIpa":"/ɪkˈspaɪə/","usIpa":"/ɪkˈspaɪr/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"Reach the end of an officially allowed or valid period.","vi":"hết hạn; hết hiệu lực"}],"examples":[{"en":"My passport expires next month, so I must renew it.","vi":"Hộ chiếu của tôi hết hạn vào tháng tới, nên tôi phải đi gia hạn.","audioKind":"ex"},{"en":"When temporary work permits expire, employees may face uncertainty about their future employment and residence.","vi":"Khi giấy phép lao động tạm thời hết hạn, người lao động có thể phải đối mặt với sự bất định về việc làm và nơi cư trú trong tương lai.","audioKind":"ex2"}],"collocations":[{"en":"a passport expires","vi":"hộ chiếu hết hạn"},{"en":"a contract expires","vi":"hợp đồng hết hạn"},{"en":"expire at midnight","vi":"hết hạn vào lúc nửa đêm"}],"wordFamily":["expiry (n.)","expiration (n.)"],"synonyms":["run out"],"antonyms":[],"tipVi":"Là nội động từ: hợp đồng hết hạn dùng expires, không dùng is expired.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mold', 'en-b2-76', 'mold', '/moʊld/', 'B2', 'khuôn; khuôn đúc; tạo hình; uốn nắn; định hình tính cách; nấm mốc', 'n.', 'moldy (adj.), molding (n.)', NULL, 'Cách viết theo tiếng Mỹ là mold, tiếng Anh thường viết là mould; từ này cũng chỉ nấm mốc.', 'Pour the melted chocolate into the mold carefully.', NULL, 'Hãy cẩn thận đổ sô-cô-la đã tan chảy vào khuôn.', '{"wordId":"mold","ukIpa":"/məʊld/","usIpa":"/moʊld/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"a shaped container in which a material sets into shape","vi":"khuôn; khuôn đúc"},{"pos":"v.","en":"to shape a material or influence someone''s character","vi":"tạo hình; uốn nắn; định hình tính cách"},{"pos":"n.","en":"a fungus growing on damp surfaces or old food","vi":"nấm mốc"}],"examples":[{"en":"Pour the melted chocolate into the mold carefully.","vi":"Hãy cẩn thận đổ sô-cô-la đã tan chảy vào khuôn.","audioKind":"ex"},{"en":"Early experiences can mold children''s attitudes towards education and influence their confidence throughout their school years.","vi":"Những trải nghiệm đầu đời có thể định hình thái độ của trẻ đối với giáo dục và ảnh hưởng đến sự tự tin của các em trong suốt những năm đi học.","audioKind":"ex2"}],"collocations":[{"en":"silicone mold","vi":"khuôn silicon"},{"en":"mold into shape","vi":"tạo hình thành khuôn"},{"en":"mold growth","vi":"sự phát triển của nấm mốc"},{"en":"break the mold","vi":"phá vỡ khuôn mẫu truyền thống"}],"wordFamily":["moldy (adj.)","molding (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cách viết theo tiếng Mỹ là mold, tiếng Anh thường viết là mould; từ này cũng chỉ nấm mốc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_visible', 'en-b2-76', 'visible', '/ˈvɪzəbl/', 'B2', 'thấy được; có thể nhìn thấy; rõ ràng; rõ mồn một; dễ nhận thấy', 'adj.', 'visibility (n.), invisible (adj.), visibly (adv.)', 'Đồng nghĩa: observable, noticeable · Trái nghĩa: invisible, hidden', 'visible to biểu thị đối tượng có thể nhìn thấy được; tránh nhầm lẫn với visual (thuộc về thị giác).', 'The mountains were barely visible through the morning mist.', NULL, 'Những dãy núi chỉ mờ ảo nhìn thấy qua lớp sương mù buổi sáng.', '{"wordId":"visible","ukIpa":"/ˈvɪzəbl/","usIpa":"/ˈvɪzəbl/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Able to be seen.","vi":"thấy được; có thể nhìn thấy"},{"pos":"adj.","en":"Clear enough to be noticed or recognised.","vi":"rõ ràng; rõ mồn một; dễ nhận thấy"}],"examples":[{"en":"The mountains were barely visible through the morning mist.","vi":"Những dãy núi chỉ mờ ảo nhìn thấy qua lớp sương mù buổi sáng.","audioKind":"ex"},{"en":"Investment in public transport has brought visible improvements to air quality in several major cities.","vi":"Việc đầu tư vào giao thông công cộng đã mang lại những cải thiện rõ rệt về chất lượng không khí ở một số thành phố lớn.","audioKind":"ex2"}],"collocations":[{"en":"clearly visible","vi":"nhìn thấy rõ ràng"},{"en":"visible to the naked eye","vi":"nhìn thấy bằng mắt thường"},{"en":"visible improvement","vi":"sự cải thiện rõ rệt"}],"wordFamily":["visibility (n.)","invisible (adj.)","visibly (adv.)"],"synonyms":["observable","noticeable"],"antonyms":["invisible","hidden"],"tipVi":"visible to biểu thị đối tượng có thể nhìn thấy được; tránh nhầm lẫn với visual (thuộc về thị giác).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_slam', 'en-b2-76', 'slam', '/slæm/', 'B2', 'đóng sập; đặt mạnh (vật gì đó với tiếng động lớn); chỉ trích gay gắt; phê phán mạnh mẽ; tiếng đóng sập; tiếng va đập mạnh', 'v.', NULL, NULL, 'Quá khứ là slammed, phân từ hiện đại là slamming, cả hai đều gấp đôi chữ cái m.', 'The wind slammed the window shut during breakfast.', NULL, 'Cơn gió đã thổi làm cánh cửa sổ đóng sập lại trong bữa sáng.', '{"wordId":"slam","ukIpa":"/slæm/","usIpa":"/slæm/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to shut or put something down with force and noise","vi":"đóng sập; đặt mạnh (vật gì đó với tiếng động lớn)"},{"pos":"v.","en":"to criticize someone or something very strongly","vi":"chỉ trích gay gắt; phê phán mạnh mẽ"},{"pos":"n.","en":"a loud noise caused by something closing or hitting hard","vi":"tiếng đóng sập; tiếng va đập mạnh"}],"examples":[{"en":"The wind slammed the window shut during breakfast.","vi":"Cơn gió đã thổi làm cánh cửa sổ đóng sập lại trong bữa sáng.","audioKind":"ex"},{"en":"Environmental groups slammed the proposal because it would allow further construction in protected coastal areas.","vi":"Các tổ chức bảo vệ môi trường đã lên tiếng chỉ trích gay gắt đề xuất này vì nó cho phép tiếp tục xây dựng trong các khu vực ven biển được bảo vệ.","audioKind":"ex2"}],"collocations":[{"en":"slam the door","vi":"đóng sập cửa"},{"en":"slam shut","vi":"đóng sập lại"},{"en":"slam a proposal","vi":"phê phán một đề xuất"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Quá khứ là slammed, phân từ hiện đại là slamming, cả hai đều gấp đôi chữ cái m.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_strap', 'en-b2-76', 'strap', '/stræp/', 'B2', 'dây đeo; quai; đai; buộc chặt bằng dây; ràng buộc', 'n.', NULL, NULL, 'Khi là động từ, quá khứ là strapped và hiện phân từ là strapping.', 'The strap on my backpack broke near the bus stop.', NULL, 'Quai balo của tôi bị đứt gần trạm xe buýt.', '{"wordId":"strap","ukIpa":"/stræp/","usIpa":"/stræp/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"a narrow strip used to carry, hold, or fasten something","vi":"dây đeo; quai; đai"},{"pos":"v.","en":"to secure someone or something with a strap","vi":"buộc chặt bằng dây; ràng buộc"}],"examples":[{"en":"The strap on my backpack broke near the bus stop.","vi":"Quai balo của tôi bị đứt gần trạm xe buýt.","audioKind":"ex"},{"en":"Passengers should strap their luggage securely to prevent injuries when vehicles stop suddenly or travel over uneven roads.","vi":"Hành khách nên thắt và buộc chặt hành lý để tránh chấn thương khi xe phanh gấp hoặc đi qua đoạn đường xóc.","audioKind":"ex2"}],"collocations":[{"en":"shoulder strap","vi":"quai đeo vai"},{"en":"adjustable strap","vi":"dây điều chỉnh"},{"en":"strap something down","vi":"cố định vật gì bằng dây"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi là động từ, quá khứ là strapped và hiện phân từ là strapping.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gallon', 'en-b2-76', 'gallon', '/ˈɡælən/', 'B2', 'galông (đơn vị đo thể tích)', 'n.', NULL, NULL, 'Một galông Anh khoảng 4,55 lít, trong khi galông Mỹ khoảng 3,79 lít, cần lưu ý phân biệt.', 'We bought a gallon of paint for the kitchen.', NULL, 'Chúng tôi đã mua một galông sơn để sơn lại nhà bếp.', '{"wordId":"gallon","ukIpa":"/ˈɡælən/","usIpa":"/ˈɡælən/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A liquid measure, about 4.55 litres British or 3.79 litres American","vi":"galông (đơn vị đo thể tích)"}],"examples":[{"en":"We bought a gallon of paint for the kitchen.","vi":"Chúng tôi đã mua một galông sơn để sơn lại nhà bếp.","audioKind":"ex"},{"en":"Comparing how far vehicles travel per gallon of fuel helps consumers assess running costs and fuel efficiency.","vi":"Việc so sánh quãng đường xe di chuyển được trên mỗi galông nhiên liệu giúp người tiêu dùng đánh giá chi phí vận hành và hiệu quả sử dụng nhiên liệu.","audioKind":"ex2"}],"collocations":[{"en":"a gallon of petrol","vi":"một galông xăng"},{"en":"miles per gallon","vi":"số dặm trên mỗi galông"},{"en":"an imperial gallon","vi":"một galông Anh"},{"en":"a US gallon","vi":"một galông Mỹ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Một galông Anh khoảng 4,55 lít, trong khi galông Mỹ khoảng 3,79 lít, cần lưu ý phân biệt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tender', 'en-b2-76', 'tender', '/ˈtendər/', 'B2', 'mềm; dễ nhai; dễ cắt; dịu dàng; ân cần; âu yếm; đau nhức; ê ẩm khi chạm vào', 'adj.', 'tenderness (n.), tenderly (adv.), tenderise (v.)', 'Đồng nghĩa: soft, gentle · Trái nghĩa: tough', 'Khi mô tả thức ăn có nghĩa là mềm; khi mô tả bộ phận cơ thể có nghĩa là dễ bị đau khi chạm vào.', 'The carrots were tender enough to mash with a fork.', NULL, 'Củ cà rốt mềm đến mức có thể dùng dĩa dầm nát được.', '{"wordId":"tender","ukIpa":"/ˈtendə/","usIpa":"/ˈtendər/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Soft and easy to cut or chew.","vi":"mềm; dễ nhai; dễ cắt"},{"pos":"adj.","en":"Showing gentle care and affection.","vi":"dịu dàng; ân cần; âu yếm"},{"pos":"adj.","en":"Painful when touched.","vi":"đau nhức; ê ẩm khi chạm vào"}],"examples":[{"en":"The carrots were tender enough to mash with a fork.","vi":"Củ cà rốt mềm đến mức có thể dùng dĩa dầm nát được.","audioKind":"ex"},{"en":"Slow cooking makes tougher cuts of meat tender, allowing households to use less expensive ingredients.","vi":"Nấu chậm giúp các phần thịt dai trở nên mềm hơn, giúp các gia đình tận dụng được các nguyên liệu rẻ hơn.","audioKind":"ex2"}],"collocations":[{"en":"tender meat","vi":"thịt mềm"},{"en":"tender care","vi":"sự chăm sóc ân cần"},{"en":"tender to the touch","vi":"đau khi chạm vào"}],"wordFamily":["tenderness (n.)","tenderly (adv.)","tenderise (v.)"],"synonyms":["soft","gentle"],"antonyms":["tough"],"tipVi":"Khi mô tả thức ăn có nghĩa là mềm; khi mô tả bộ phận cơ thể có nghĩa là dễ bị đau khi chạm vào.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_resemble', 'en-b2-76', 'resemble', '/rɪˈzembl/', 'B2', 'giống; tương tự', 'v.', 'resemblance (n.)', 'Đồng nghĩa: look like, be similar to · Trái nghĩa: differ from', 'Trực tiếp đi kèm tân ngữ: resemble someone, không dùng thêm giới từ to hay with.', 'These clouds resemble small boats floating across the sky.', NULL, 'Những đám mây này giống như những chiếc thuyền nhỏ trôi lững lờ trên bầu trời.', '{"wordId":"resemble","ukIpa":"/rɪˈzembl/","usIpa":"/rɪˈzembl/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To look like or be similar to someone or something","vi":"giống; tương tự"}],"examples":[{"en":"These clouds resemble small boats floating across the sky.","vi":"Những đám mây này giống như những chiếc thuyền nhỏ trôi lững lờ trên bầu trời.","audioKind":"ex"},{"en":"Modern learning spaces increasingly resemble collaborative workplaces rather than traditional classrooms with fixed rows of desks.","vi":"Không gian học tập hiện đại ngày càng giống với môi trường làm việc hợp tác hơn là các lớp học truyền thống với những dãy bàn ghế cố định.","audioKind":"ex2"}],"collocations":[{"en":"closely resemble","vi":"rất giống"},{"en":"strongly resemble","vi":"giống hệt"},{"en":"resemble each other","vi":"giống nhau"}],"wordFamily":["resemblance (n.)"],"synonyms":["look like","be similar to"],"antonyms":["differ from"],"tipVi":"Trực tiếp đi kèm tân ngữ: resemble someone, không dùng thêm giới từ to hay with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_refresh', 'en-b2-76', 'refresh', '/rɪˈfreʃ/', 'B2', 'làm cho tỉnh táo, hồi sức; làm tươi mới, cập nhật (thông tin, trang web); làm nhớ lại, gợi nhắc', 'v.', 'refreshing (adj.), refreshed (adj.), refreshment (n.), refresher (n.)', 'Đồng nghĩa: revive, revitalise', 'Cảm giác con người thấy khỏe khoắn dùng refreshed; điều mang lại sự sảng khoái dùng refreshing.', 'A cool shower refreshed me after the long walk.', NULL, 'Tắm vòi hoa sen mát lạnh giúp tôi tỉnh táo hẳn sau quãng đường đi bộ dài.', '{"wordId":"refresh","ukIpa":"/rɪˈfreʃ/","usIpa":"/rɪˈfreʃ/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To make someone feel less tired or more comfortable.","vi":"làm cho tỉnh táo, hồi sức"},{"pos":"v.","en":"To load the latest version of displayed information.","vi":"làm tươi mới, cập nhật (thông tin, trang web)"},{"pos":"v.","en":"To help someone remember something learned or experienced before.","vi":"làm nhớ lại, gợi nhắc"}],"examples":[{"en":"A cool shower refreshed me after the long walk.","vi":"Tắm vòi hoa sen mát lạnh giúp tôi tỉnh táo hẳn sau quãng đường đi bộ dài.","audioKind":"ex"},{"en":"Regular breaks can refresh employees and help them maintain concentration during tasks that require sustained mental effort.","vi":"Những khoảng nghỉ giải lao thường xuyên có thể giúp nhân viên lấy lại tinh thần và duy trì sự tập trung trong các công việc đòi hỏi nỗ lực trí óc liên tục.","audioKind":"ex2"}],"collocations":[{"en":"feel refreshed","vi":"cảm thấy sảng khoái, tỉnh táo"},{"en":"refresh a page","vi":"làm mới trang web"},{"en":"refresh your memory","vi":"làm nhớ lại ký ức"},{"en":"refresh your skills","vi":"ôn luyện lại kỹ năng"}],"wordFamily":["refreshing (adj.)","refreshed (adj.)","refreshment (n.)","refresher (n.)"],"synonyms":["revive","revitalise"],"antonyms":[],"tipVi":"Cảm giác con người thấy khỏe khoắn dùng refreshed; điều mang lại sự sảng khoái dùng refreshing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_silky', 'en-b2-76', 'silky', '/ˈsɪlki/', 'B2', 'mềm mại, mượt mà, sáng bóng như lụa; êm ái, du dương, dễ chịu (âm thanh)', 'adj.', 'silk (n.), silkiness (n.)', 'Đồng nghĩa: smooth, silken · Trái nghĩa: rough, coarse', 'silky nhấn mạnh độ mềm mịn như lụa, không nhất thiết phải làm từ lụa thật.', 'This conditioner leaves my hair feeling soft and silky.', NULL, 'Dầu xả này làm tóc tôi mềm mượt và óng ả.', '{"wordId":"silky","ukIpa":"/ˈsɪlki/","usIpa":"/ˈsɪlki/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"soft, smooth, and often shiny like silk","vi":"mềm mại, mượt mà, sáng bóng như lụa"},{"pos":"adj.","en":"pleasantly smooth and gentle in sound","vi":"êm ái, du dương, dễ chịu (âm thanh)"}],"examples":[{"en":"This conditioner leaves my hair feeling soft and silky.","vi":"Dầu xả này làm tóc tôi mềm mượt và óng ả.","audioKind":"ex"},{"en":"Consumers often prefer fabrics with a silky texture, although their production may require substantial chemical processing.","vi":"Người tiêu dùng thường thích các loại vải có kết cấu mượt mà như lụa, mặc dù quá trình sản xuất chúng có thể đòi hỏi xử lý hóa chất đáng kể.","audioKind":"ex2"}],"collocations":[{"en":"silky hair","vi":"tóc mượt mà"},{"en":"silky texture","vi":"kết cấu mượt như lụa"},{"en":"silky smooth","vi":"mượt mà như lụa"},{"en":"silky voice","vi":"giọng nói trầm ấm, êm tai"}],"wordFamily":["silk (n.)","silkiness (n.)"],"synonyms":["smooth","silken"],"antonyms":["rough","coarse"],"tipVi":"silky nhấn mạnh độ mềm mịn như lụa, không nhất thiết phải làm từ lụa thật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_straighten', 'en-b2-76', 'straighten', '/ˈstreɪtən/', 'B2', 'làm thẳng, duỗi thẳng; vươn thẳng người, đứng thẳng lên', 'v.', 'straight (adj.)', 'Trái nghĩa: bend', 'straighten up có thể chỉ hành động đứng thẳng người hoặc dọn dẹp nhà cửa gọn gàng.', 'She paused to straighten her tie before the interview.', NULL, 'Cô ấy dừng lại để chỉnh lại cà vạt trước buổi phỏng vấn.', '{"wordId":"straighten","ukIpa":"/ˈstreɪtən/","usIpa":"/ˈstreɪtən/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"Make something straight, or become straight.","vi":"làm thẳng, duỗi thẳng"},{"pos":"v.","en":"Move your body into an upright position.","vi":"vươn thẳng người, đứng thẳng lên"}],"examples":[{"en":"She paused to straighten her tie before the interview.","vi":"Cô ấy dừng lại để chỉnh lại cà vạt trước buổi phỏng vấn.","audioKind":"ex"},{"en":"Regular stretching can help office workers straighten their backs and reduce discomfort caused by prolonged sitting.","vi":"Việc giãn cơ thường xuyên có thể giúp nhân viên văn phòng giữ thẳng lưng và giảm bớt khó chịu do ngồi lâu.","audioKind":"ex2"}],"collocations":[{"en":"straighten your back","vi":"duỗi thẳng lưng"},{"en":"straighten up","vi":"đứng thẳng người; dọn dẹp ngăn nắp"},{"en":"straighten out a problem","vi":"giải quyết một vấn đề"}],"wordFamily":["straight (adj.)"],"synonyms":[],"antonyms":["bend"],"tipVi":"straighten up có thể chỉ hành động đứng thẳng người hoặc dọn dẹp nhà cửa gọn gàng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_porch', 'en-b2-76', 'porch', '/pɔːrtʃ/', 'B2', 'hiên nhà; mái hiên', 'n.', NULL, NULL, 'Chỉ không gian có mái che ngay bên ngoài lối ra vào, không phải hành lang bên trong tòa nhà.', 'We left our muddy boots on the porch overnight.', NULL, 'Chúng tôi để đôi bốt dính bùn ở hiên nhà qua đêm.', '{"wordId":"porch","ukIpa":"/pɔːtʃ/","usIpa":"/pɔːrtʃ/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A covered area immediately outside a building''s entrance.","vi":"hiên nhà; mái hiên"}],"examples":[{"en":"We left our muddy boots on the porch overnight.","vi":"Chúng tôi để đôi bốt dính bùn ở hiên nhà qua đêm.","audioKind":"ex"},{"en":"A shaded porch can reduce indoor temperatures while providing residents with a comfortable outdoor meeting space.","vi":"Mái hiên có bóng râm có thể giúp giảm nhiệt độ trong nhà đồng thời cung cấp cho cư dân một không gian sinh hoạt ngoài trời thoải mái.","audioKind":"ex2"}],"collocations":[{"en":"front porch","vi":"hiên trước"},{"en":"covered porch","vi":"hiên có mái che"},{"en":"sit on the porch","vi":"ngồi ngoài hiên"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ không gian có mái che ngay bên ngoài lối ra vào, không phải hành lang bên trong tòa nhà.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_polish', 'en-b2-76', 'polish', '/ˈpɑːlɪʃ/', 'B2', 'đánh bóng; làm cho sáng bóng; gọt giũa; trau chuốt; cải thiện; chất đánh bóng; dung dịch làm bóng', 'v.', 'polished (adj.), polisher (n.)', NULL, 'Chữ thường ''polish'' có nghĩa là đánh bóng; chữ hoa ''Polish'' có nghĩa là thuộc về Ba Lan, cách phát âm khác nhau.', 'I polish my shoes before every important meeting.', NULL, 'Tôi luôn đánh bóng giày trước mỗi cuộc họp quan trọng.', '{"wordId":"polish","ukIpa":"/ˈpɒlɪʃ/","usIpa":"/ˈpɑːlɪʃ/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To rub a surface until it becomes smooth and shiny.","vi":"đánh bóng; làm cho sáng bóng"},{"pos":"v.","en":"To improve something by making small, careful changes.","vi":"gọt giũa; trau chuốt; cải thiện"},{"pos":"n.","en":"A substance used to make a surface smooth and shiny.","vi":"chất đánh bóng; dung dịch làm bóng"}],"examples":[{"en":"I polish my shoes before every important meeting.","vi":"Tôi luôn đánh bóng giày trước mỗi cuộc họp quan trọng.","audioKind":"ex"},{"en":"University students should learn to polish their writing by removing unnecessary words and organising arguments logically.","vi":"Sinh viên đại học nên học cách trau chuốt bài viết của mình bằng cách lược bỏ các từ thừa và sắp xếp các luận điểm một cách logic.","audioKind":"ex2"}],"collocations":[{"en":"polish shoes","vi":"đánh bóng giày"},{"en":"polish an essay","vi":"trau chuốt bài luận"},{"en":"furniture polish","vi":"chất đánh bóng đồ gỗ"}],"wordFamily":["polished (adj.)","polisher (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chữ thường ''polish'' có nghĩa là đánh bóng; chữ hoa ''Polish'' có nghĩa là thuộc về Ba Lan, cách phát âm khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_entirely', 'en-b2-76', 'entirely', '/ɪnˈtaɪərli/', 'B2', 'hoàn toàn; trọn vẹn', 'adv.', 'entire (adj.), entirety (n.)', 'Đồng nghĩa: completely, wholly, totally · Trái nghĩa: partly, partially', 'not entirely mang nghĩa không hoàn toàn, chứ không phải là không chút nào.', 'I entirely forgot about the soup on the stove.', NULL, 'Tôi hoàn toàn quên mất nồi súp đang nấu trên bếp.', '{"wordId":"entirely","ukIpa":"/ɪnˈtaɪəli/","usIpa":"/ɪnˈtaɪərli/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"Completely, with nothing left out.","vi":"hoàn toàn; trọn vẹn"}],"examples":[{"en":"I entirely forgot about the soup on the stove.","vi":"Tôi hoàn toàn quên mất nồi súp đang nấu trên bếp.","audioKind":"ex"},{"en":"A transport system powered entirely by renewable energy could significantly reduce a city''s carbon emissions.","vi":"Một hệ thống giao thông vận hành hoàn toàn bằng năng lượng tái tạo có thể giảm đáng kể lượng khí thải carbon của thành phố.","audioKind":"ex2"}],"collocations":[{"en":"entirely different","vi":"hoàn toàn khác biệt"},{"en":"entirely dependent on","vi":"hoàn toàn phụ thuộc vào"},{"en":"not entirely","vi":"không hoàn toàn"}],"wordFamily":["entire (adj.)","entirety (n.)"],"synonyms":["completely","wholly","totally"],"antonyms":["partly","partially"],"tipVi":"not entirely mang nghĩa không hoàn toàn, chứ không phải là không chút nào.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sake', 'en-b2-76', 'sake', '/seɪk/', 'B2', 'lợi ích; mục đích; vì (ai/cái gì)', 'n.', NULL, NULL, 'Thường đi trong cấu trúc for the sake of hoặc for someone''s sake.', 'We kept our voices down for the baby''s sake.', NULL, 'Chúng tôi cố gắng nói nhỏ vì muốn giữ yên tĩnh cho em bé.', '{"wordId":"sake","ukIpa":"/seɪk/","usIpa":"/seɪk/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"Someone''s benefit or the purpose behind an action.","vi":"lợi ích; mục đích; vì (ai/cái gì)"}],"examples":[{"en":"We kept our voices down for the baby''s sake.","vi":"Chúng tôi cố gắng nói nhỏ vì muốn giữ yên tĩnh cho em bé.","audioKind":"ex"},{"en":"Governments should protect natural habitats for the sake of future generations rather than prioritising short-term profits.","vi":"Chính phủ nên bảo vệ các môi trường sống tự nhiên vì lợi ích của thế hệ tương lai thay vì ưu tiên lợi ích ngắn hạn.","audioKind":"ex2"}],"collocations":[{"en":"for someone''s sake","vi":"vì lợi ích của ai đó"},{"en":"for the sake of","vi":"vì mục đích..."},{"en":"for the sake of clarity","vi":"vì mục đích rõ ràng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường đi trong cấu trúc for the sake of hoặc for someone''s sake.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_groom', 'en-b2-76', 'groom', '/ɡruːm/', 'B2', 'chải chuốt; chải lông (cho vật nuôi); chú rể; đào tạo; bồi dưỡng (cho một vai trò)', 'v.', 'grooming (n.), well-groomed (adj.)', NULL, 'Dùng cấu trúc groom someone for a role khi nói về việc bồi dưỡng ai đó cho một vị trí.', 'We groom our pony every morning before riding.', NULL, 'Chúng tôi chải lông cho chú ngựa con mỗi sáng trước khi cưỡi.', '{"wordId":"groom","ukIpa":"/ɡruːm/","usIpa":"/ɡruːm/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To clean and brush an animal or make yourself neat.","vi":"chải chuốt; chải lông (cho vật nuôi)"},{"pos":"n.","en":"A man who is getting married or has just married.","vi":"chú rể"},{"pos":"v.","en":"To prepare someone for a particular role or responsibility.","vi":"đào tạo; bồi dưỡng (cho một vai trò)"}],"examples":[{"en":"We groom our pony every morning before riding.","vi":"Chúng tôi chải lông cho chú ngựa con mỗi sáng trước khi cưỡi.","audioKind":"ex"},{"en":"Some organisations groom promising employees for leadership roles through structured training and regular mentoring.","vi":"Một số tổ chức bồi dưỡng những nhân viên triển vọng cho các vị trí lãnh đạo thông qua chương trình đào tạo bài bản và cố vấn thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"groom a horse","vi":"chải lông ngựa"},{"en":"bride and groom","vi":"cô dâu và chú rể"},{"en":"groom someone for leadership","vi":"đào tạo ai đó làm lãnh đạo"}],"wordFamily":["grooming (n.)","well-groomed (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng cấu trúc groom someone for a role khi nói về việc bồi dưỡng ai đó cho một vị trí.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sunshade', 'en-b2-76', 'sunshade', '/ˈsʌnʃeɪd/', 'B2', 'ô che nắng; mái che nắng', 'n.', NULL, 'Đồng nghĩa: parasol', 'sunshade dùng để che nắng; umbrella thường dùng để chỉ ô che mưa.', 'We opened the sunshade above our garden table.', NULL, 'Chúng tôi đã mở chiếc ô che nắng phía trên bàn ăn ngoài vườn.', '{"wordId":"sunshade","ukIpa":"/ˈsʌnʃeɪd/","usIpa":"/ˈsʌnʃeɪd/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"an object that blocks sunlight to provide shade","vi":"ô che nắng; mái che nắng"}],"examples":[{"en":"We opened the sunshade above our garden table.","vi":"Chúng tôi đã mở chiếc ô che nắng phía trên bàn ăn ngoài vườn.","audioKind":"ex"},{"en":"Installing a sunshade over each outdoor seating area can make public spaces more comfortable in summer.","vi":"Việc lắp đặt mái che nắng phía trên mỗi khu vực chỗ ngồi ngoài trời có thể giúp không gian công cộng trở nên thoải mái hơn vào mùa hè.","audioKind":"ex2"}],"collocations":[{"en":"beach sunshade","vi":"ô che nắng bãi biển"},{"en":"car sunshade","vi":"tấm chắn nắng ô tô"},{"en":"under a sunshade","vi":"dưới ô che nắng"}],"wordFamily":[],"synonyms":["parasol"],"antonyms":[],"tipVi":"sunshade dùng để che nắng; umbrella thường dùng để chỉ ô che mưa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_removal', 'en-b2-76', 'removal', '/rɪˈmuːvəl/', 'B2', 'sự loại bỏ; sự tẩy sạch; sự cách chức; sự bãi nhiệm; sự chuyển nhà; sự dọn nhà', 'n.', 'remove (v.), removable (adj.)', NULL, 'Nghĩa chuyển nhà chủ yếu dùng trong tiếng Anh-Anh; công ty chuyển nhà là removal company.', 'Stain removal is easier if you act quickly.', NULL, 'Việc tẩy vết bẩn sẽ dễ dàng hơn nếu bạn xử lý kịp thời.', '{"wordId":"removal","ukIpa":"/rɪˈmuːvəl/","usIpa":"/rɪˈmuːvəl/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"The act of taking something away from a place.","vi":"sự loại bỏ; sự tẩy sạch"},{"pos":"n.","en":"The act of dismissing someone from an official position.","vi":"sự cách chức; sự bãi nhiệm"},{"pos":"n.","en":"The process of moving belongings to a new home.","vi":"sự chuyển nhà; sự dọn nhà"}],"examples":[{"en":"Stain removal is easier if you act quickly.","vi":"Việc tẩy vết bẩn sẽ dễ dàng hơn nếu bạn xử lý kịp thời.","audioKind":"ex"},{"en":"The removal of unnecessary packaging could significantly reduce the amount of household waste sent to landfill.","vi":"Việc loại bỏ bao bì không cần thiết có thể làm giảm đáng kể lượng rác thải sinh hoạt đưa ra bãi chôn lấp.","audioKind":"ex2"}],"collocations":[{"en":"waste removal","vi":"thu gom rác thải"},{"en":"stain removal","vi":"tẩy vết bẩn"},{"en":"removal from office","vi":"cách chức"},{"en":"removal company","vi":"công ty chuyển nhà"}],"wordFamily":["remove (v.)","removable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa chuyển nhà chủ yếu dùng trong tiếng Anh-Anh; công ty chuyển nhà là removal company.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sneak', 'en-b2-76', 'sneak', '/sniːk/', 'B2', 'lén lút; trốn đi; lén lấy; lén làm', 'v.', 'sneaky (adj.), sneakily (adv.)', NULL, 'Dạng quá khứ thường dùng sneaked; trong tiếng Anh-Mỹ, từ snuck cũng rất phổ biến.', 'I sneaked downstairs for water while everyone was asleep.', NULL, 'Tôi lẻn xuống nhà lấy nước khi mọi người đang ngủ say.', '{"wordId":"sneak","ukIpa":"/sniːk/","usIpa":"/sniːk/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"move quietly and secretly to avoid being noticed","vi":"lén lút; trốn đi"},{"pos":"v.","en":"take or do something secretly without permission","vi":"lén lấy; lén làm"}],"examples":[{"en":"I sneaked downstairs for water while everyone was asleep.","vi":"Tôi lẻn xuống nhà lấy nước khi mọi người đang ngủ say.","audioKind":"ex"},{"en":"Some students sneak phones into examinations, highlighting the need for clearer rules and stronger supervision.","vi":"Một số học sinh lén mang điện thoại vào phòng thi, qua đó làm nổi bật sự cần thiết phải có các quy định rõ ràng hơn và sự giám sát chặt chẽ hơn.","audioKind":"ex2"}],"collocations":[{"en":"sneak out","vi":"lén lút chuồn ra ngoài"},{"en":"sneak into","vi":"lén lút đi vào"},{"en":"sneak a look","vi":"liếc trộm một cái"},{"en":"sneak something past someone","vi":"lén lút mang thứ gì qua mặt ai"}],"wordFamily":["sneaky (adj.)","sneakily (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ thường dùng sneaked; trong tiếng Anh-Mỹ, từ snuck cũng rất phổ biến.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_steadily', 'en-b2-76', 'steadily', '/ˈstedɪli/', 'B2', 'đều đặn; liên tục và ổn định (không có sự thay đổi hay ngắt quãng đột ngột); vững vàng; chắc chắn (không bị rung lắc hay mất thăng bằng)', 'adv.', 'steady (adj.), steady (v.), steadiness (n.)', 'Đồng nghĩa: consistently · Trái nghĩa: erratically', 'Trong dạng bài viết biểu đồ (IELTS Writing), thường dùng rise steadily để chỉ mức tăng trưởng đều đặn chứ không tăng vọt.', 'Rain fell steadily as we walked back from the station.', NULL, 'Trời mưa lất phất không ngừng khi chúng tôi đi bộ từ nhà ga về.', '{"wordId":"steadily","ukIpa":"/ˈstedɪli/","usIpa":"/ˈstedɪli/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"At a regular rate, without sudden changes or interruptions.","vi":"đều đặn; liên tục và ổn định (không có sự thay đổi hay ngắt quãng đột ngột)"},{"pos":"adv.","en":"In a controlled way, without shaking or losing balance.","vi":"vững vàng; chắc chắn (không bị rung lắc hay mất thăng bằng)"}],"examples":[{"en":"Rain fell steadily as we walked back from the station.","vi":"Trời mưa lất phất không ngừng khi chúng tôi đi bộ từ nhà ga về.","audioKind":"ex"},{"en":"The proportion of households using renewable electricity has risen steadily over the past decade.","vi":"Tỷ lệ các hộ gia đình sử dụng điện tái tạo đã tăng trưởng đều đặn trong thập kỷ qua.","audioKind":"ex2"}],"collocations":[{"en":"rise steadily","vi":"tăng đều đặn"},{"en":"decline steadily","vi":"giảm đều đặn"},{"en":"grow steadily","vi":"phát triển ổn định"},{"en":"work steadily","vi":"làm việc đều đặn có nề nếp"}],"wordFamily":["steady (adj.)","steady (v.)","steadiness (n.)"],"synonyms":["consistently"],"antonyms":["erratically"],"tipVi":"Trong dạng bài viết biểu đồ (IELTS Writing), thường dùng rise steadily để chỉ mức tăng trưởng đều đặn chứ không tăng vọt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_forefinger', 'en-b2-76', 'forefinger', '/ˈfɔːrfɪŋɡɚ/', 'B2', 'ngón trỏ', 'n.', NULL, 'Đồng nghĩa: index finger', 'Đồng nghĩa với index finger, đều chỉ ngón tay nằm ngay cạnh ngón cái.', 'She pressed the doorbell gently with her forefinger.', NULL, 'Cô ấy nhẹ nhàng bấm chuông cửa bằng ngón trỏ.', '{"wordId":"forefinger","ukIpa":"/ˈfɔːfɪŋɡə/","usIpa":"/ˈfɔːrfɪŋɡɚ/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"The finger next to the thumb.","vi":"ngón trỏ"}],"examples":[{"en":"She pressed the doorbell gently with her forefinger.","vi":"Cô ấy nhẹ nhàng bấm chuông cửa bằng ngón trỏ.","audioKind":"ex"},{"en":"Participants used their forefinger to press a button whenever they noticed a change on the screen.","vi":"Những người tham gia dùng ngón trỏ để nhấn một nút bất cứ khi nào họ nhận thấy sự thay đổi trên màn hình.","audioKind":"ex2"}],"collocations":[{"en":"thumb and forefinger","vi":"ngón cái và ngón trỏ"},{"en":"right forefinger","vi":"ngón trỏ phải"},{"en":"tip of the forefinger","vi":"đầu ngón trỏ"}],"wordFamily":[],"synonyms":["index finger"],"antonyms":[],"tipVi":"Đồng nghĩa với index finger, đều chỉ ngón tay nằm ngay cạnh ngón cái.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_detergent', 'en-b2-76', 'detergent', '/dɪˈtɜːrdʒənt/', 'B2', 'chất tẩy rửa; bột giặt', 'n.', NULL, 'Đồng nghĩa: cleaning agent', 'Phân biệt khi dùng: "detergent" thường không đếm được khi chỉ chung chất tẩy, và đếm được khi chỉ các loại khác nhau.', 'I added detergent before starting the washing machine.', NULL, 'Tôi đã cho bột giặt vào trước khi bật máy giặt.', '{"wordId":"detergent","ukIpa":"/dɪˈtɜːdʒənt/","usIpa":"/dɪˈtɜːrdʒənt/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"a substance used with water to clean clothes or surfaces","vi":"chất tẩy rửa; bột giặt"}],"examples":[{"en":"I added detergent before starting the washing machine.","vi":"Tôi đã cho bột giặt vào trước khi bật máy giặt.","audioKind":"ex"},{"en":"Using excessive detergent wastes money and may increase the amount of chemicals entering local waterways.","vi":"Việc dùng quá nhiều chất tẩy rửa vừa lãng phí tiền bạc vừa có thể làm tăng lượng hóa chất xả ra các nguồn nước xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"laundry detergent","vi":"bột giặt quần áo"},{"en":"liquid detergent","vi":"chất tẩy dạng lỏng"},{"en":"mild detergent","vi":"chất tẩy rửa dịu nhẹ"}],"wordFamily":[],"synonyms":["cleaning agent"],"antonyms":[],"tipVi":"Phân biệt khi dùng: \"detergent\" thường không đếm được khi chỉ chung chất tẩy, và đếm được khi chỉ các loại khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_76_1', 'en-b2-76', 'Cách dùng “steadily” (adv.) — đều đặn; liên tục và ổn định (không có sự thay đổi hay ngắt quãng đột ngột)', 'rise steadily  ·  decline steadily  ·  grow steadily', 'Trong dạng bài viết biểu đồ (IELTS Writing), thường dùng rise steadily để chỉ mức tăng trưởng đều đặn chứ không tăng vọt.', 'Họ từ (Word Family): steady (adj.), steady (v.), steadiness (n.) | Đồng nghĩa: consistently · Trái nghĩa: erratically', '[{"hanzi":"Rain fell steadily as we walked back from the station.","pinyin":"","meaning":"Trời mưa lất phất không ngừng khi chúng tôi đi bộ từ nhà ga về."},{"hanzi":"The proportion of households using renewable electricity has risen steadily over the past decade.","pinyin":"","meaning":"Tỷ lệ các hộ gia đình sử dụng điện tái tạo đã tăng trưởng đều đặn trong thập kỷ qua."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_76_2', 'en-b2-76', 'Cách dùng “detergent” (n.) — chất tẩy rửa; bột giặt', 'laundry detergent  ·  liquid detergent  ·  mild detergent', 'Phân biệt khi dùng: "detergent" thường không đếm được khi chỉ chung chất tẩy, và đếm được khi chỉ các loại khác nhau.', 'Đồng nghĩa: cleaning agent', '[{"hanzi":"I added detergent before starting the washing machine.","pinyin":"","meaning":"Tôi đã cho bột giặt vào trước khi bật máy giặt."},{"hanzi":"Using excessive detergent wastes money and may increase the amount of chemicals entering local waterways.","pinyin":"","meaning":"Việc dùng quá nhiều chất tẩy rửa vừa lãng phí tiền bạc vừa có thể làm tăng lượng hóa chất xả ra các nguồn nước xung quanh."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_76_3', 'en-b2-76', 'Cách dùng “polish” (v.) — đánh bóng; làm cho sáng bóng', 'polish shoes  ·  polish an essay  ·  furniture polish', 'Chữ thường ''polish'' có nghĩa là đánh bóng; chữ hoa ''Polish'' có nghĩa là thuộc về Ba Lan, cách phát âm khác nhau.', 'Họ từ (Word Family): polished (adj.), polisher (n.)', '[{"hanzi":"I polish my shoes before every important meeting.","pinyin":"","meaning":"Tôi luôn đánh bóng giày trước mỗi cuộc họp quan trọng."},{"hanzi":"University students should learn to polish their writing by removing unnecessary words and organising arguments logically.","pinyin":"","meaning":"Sinh viên đại học nên học cách trau chuốt bài viết của mình bằng cách lược bỏ các từ thừa và sắp xếp các luận điểm một cách logic."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_76_4', 'en-b2-76', 'Cách dùng “visible” (adj.) — thấy được; có thể nhìn thấy', 'clearly visible  ·  visible to the naked eye  ·  visible improvement', 'visible to biểu thị đối tượng có thể nhìn thấy được; tránh nhầm lẫn với visual (thuộc về thị giác).', 'Họ từ (Word Family): visibility (n.), invisible (adj.), visibly (adv.) | Đồng nghĩa: observable, noticeable · Trái nghĩa: invisible, hidden', '[{"hanzi":"The mountains were barely visible through the morning mist.","pinyin":"","meaning":"Những dãy núi chỉ mờ ảo nhìn thấy qua lớp sương mù buổi sáng."},{"hanzi":"Investment in public transport has brought visible improvements to air quality in several major cities.","pinyin":"","meaning":"Việc đầu tư vào giao thông công cộng đã mang lại những cải thiện rõ rệt về chất lượng không khí ở một số thành phố lớn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_76_1', 'en-b2-76', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
