INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_76_1_4', 'ten_b2_76_1', 'additional', 'We need an additional chair for our guest tonight.', 'We need an additional chair for our guest tonight.', '/əˈdɪʃənəl/', 'Chúng ta cần thêm một chiếc ghế cho vị khách tối nay.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_76_1_5', 'ten_b2_76_1', 'slight', 'There is a slight scratch on my new phone.', 'There is a slight scratch on my new phone.', '/slaɪt/', 'Có một vết xước nhẹ trên chiếc điện thoại mới của tôi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_76_1_6', 'ten_b2_76_1', 'expire', 'My passport expires next month, so I must renew it.', 'My passport expires next month, so I must renew it.', '/ɪkˈspaɪr/', 'Hộ chiếu của tôi hết hạn vào tháng tới, nên tôi phải đi gia hạn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_76_1_7', 'ten_b2_76_1', 'mold', 'Pour the melted chocolate into the mold carefully.', 'Pour the melted chocolate into the mold carefully.', '/moʊld/', 'Hãy cẩn thận đổ sô-cô-la đã tan chảy vào khuôn.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_76_1_8', 'ten_b2_76_1', 'visible', 'The mountains were barely visible through the morning mist.', 'The mountains were barely visible through the morning mist.', '/ˈvɪzəbl/', 'Những dãy núi chỉ mờ ảo nhìn thấy qua lớp sương mù buổi sáng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_76_1_1', 'en-b2-76', 'ten_b2_76_1', 'listening', 'listening', 'My phone constantly buzzes while I am cooking dinner.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi để đôi bốt dính bùn ở hiên nhà qua đêm.","Hãy cẩn thận đổ sô-cô-la đã tan chảy vào khuôn.","Những dãy núi chỉ mờ ảo nhìn thấy qua lớp sương mù buổi sáng.","Điện thoại của tôi cứ rung liên tục trong lúc tôi đang nấu bữa tối."]'::jsonb, 3, 'My phone constantly buzzes while I am cooking dinner. → Điện thoại của tôi cứ rung liên tục trong lúc tôi đang nấu bữa tối.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_76_1_2', 'en-b2-76', 'ten_b2_76_1', 'listening', 'listening', 'She made a loop in the rope for hanging plants.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Có một vết xước nhẹ trên chiếc điện thoại mới của tôi.","Những đám mây này giống như những chiếc thuyền nhỏ trôi lững lờ trên bầu trời.","Chúng ta cần thêm một chiếc ghế cho vị khách tối nay.","Cô ấy thắt sợi dây thành một vòng để treo chậu cây."]'::jsonb, 3, 'She made a loop in the rope for hanging plants. → Cô ấy thắt sợi dây thành một vòng để treo chậu cây.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_76_1_3', 'en-b2-76', 'ten_b2_76_1', 'listening', 'listening', 'We ate lunch in the newly opened corner café.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy dừng lại để chỉnh lại cà vạt trước buổi phỏng vấn.","Chúng tôi đã ăn trưa tại quán cà phê góc phố mới mở.","Việc tẩy vết bẩn sẽ dễ dàng hơn nếu bạn xử lý kịp thời.","Tôi đã cho bột giặt vào trước khi bật máy giặt."]'::jsonb, 1, 'We ate lunch in the newly opened corner café. → Chúng tôi đã ăn trưa tại quán cà phê góc phố mới mở.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_76_2', 'en-b2-76', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_76_2_1', 'ten_b2_76_2', 'constantly', 'Workers must constantly update their skills to remain competitive in a rapidly changing labour market.', 'Workers must constantly update their skills to remain competitive in a rapidly changing labour market.', '/ˈkɑːnstəntli/', 'Người lao động phải không ngừng cập nhật kỹ năng của mình để duy trì tính cạnh tranh trong một thị trường lao động thay đổi nhanh chóng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_76_2_2', 'ten_b2_76_2', 'loop', 'A bus route forming a loop can connect residential areas with schools and local health centres.', 'A bus route forming a loop can connect residential areas with schools and local health centres.', '/luːp/', 'Một tuyến xe buýt chạy theo đường vòng có thể kết nối các khu dân cư với trường học và các trung tâm y tế địa phương.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_76_2_3', 'ten_b2_76_2', 'newly', 'Newly qualified teachers often need additional support to manage diverse classrooms effectively during their first year.', 'Newly qualified teachers often need additional support to manage diverse classrooms effectively during their first year.', '/ˈnuːli/', 'Những giáo viên mới vào nghề thường cần thêm sự hỗ trợ để quản lý các lớp học đa dạng học sinh một cách hiệu quả trong năm đầu tiên.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_76_2_4', 'ten_b2_76_2', 'additional', 'Universities should provide additional financial support for students who cannot afford essential learning materials.', 'Universities should provide additional financial support for students who cannot afford essential learning materials.', '/əˈdɪʃənəl/', 'Các trường đại học nên cung cấp thêm hỗ trợ tài chính cho những sinh viên không có khả năng chi trả cho các tài liệu học tập thiết yếu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_76_2_5', 'ten_b2_76_2', 'slight', 'Even a slight increase in average temperatures can have significant consequences for fragile ecosystems worldwide.', 'Even a slight increase in average temperatures can have significant consequences for fragile ecosystems worldwide.', '/slaɪt/', 'Ngay cả một sự gia tăng nhỏ về nhiệt độ trung bình cũng có thể gây ra hậu quả đáng kể cho các hệ sinh thái mỏng manh trên toàn thế giới.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_76_2_6', 'ten_b2_76_2', 'expire', 'When temporary work permits expire, employees may face uncertainty about their future employment and residence.', 'When temporary work permits expire, employees may face uncertainty about their future employment and residence.', '/ɪkˈspaɪr/', 'Khi giấy phép lao động tạm thời hết hạn, người lao động có thể phải đối mặt với sự bất định về việc làm và nơi cư trú trong tương lai.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_76_2_1', 'en-b2-76', 'ten_b2_76_2', 'listening', 'listening', 'Workers must constantly update their skills to remain competitive in a rapidly changing labour market.', NULL, 'Trong câu vừa nghe, từ “constantly” mang nghĩa nào sau đây?', '["gạt bỏ; xem nhẹ; không màng tới","người lao động chân tay; công nhân lao động","ném nhẹ; vứt","liên tục; luôn luôn; thường xuyên"]'::jsonb, 3, '“constantly” (/ˈkɑːnstəntli/): liên tục; luôn luôn; thường xuyên. Câu đầy đủ: Workers must constantly update their skills to remain competitive in a rapidly changing labour market.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_76_2_2', 'en-b2-76', 'ten_b2_76_2', 'listening', 'listening', 'A bus route forming a loop can connect residential areas with schools and local health centres.', NULL, 'Trong câu vừa nghe, từ “loop” mang nghĩa nào sau đây?', '["giường tầng; giường nằm (trên tàu, xe)","vinh dự; lòng tự trọng; niềm tự hào","quân đội; binh lính","vòng; thòng lọng; đường đi hình vòng"]'::jsonb, 3, '“loop” (/luːp/): vòng; thòng lọng; đường đi hình vòng. Câu đầy đủ: A bus route forming a loop can connect residential areas with schools and local health centres.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
