INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_76_4', 'en-b2-76', NULL, 'comprehensive_test', 'listening', 'We need an additional chair for our guest tonight.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Dầu xả này làm tóc tôi mềm mượt và óng ả.","Chúng ta cần thêm một chiếc ghế cho vị khách tối nay.","Tôi hoàn toàn quên mất nồi súp đang nấu trên bếp.","Hộ chiếu của tôi hết hạn vào tháng tới, nên tôi phải đi gia hạn."]'::jsonb, 1, 'We need an additional chair for our guest tonight. → Chúng ta cần thêm một chiếc ghế cho vị khách tối nay.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
