INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_76_6', 'en-b2-76', NULL, 'comprehensive_test', 'listening', 'My passport expires next month, so I must renew it.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng ta cần thêm một chiếc ghế cho vị khách tối nay.","Trời mưa lất phất không ngừng khi chúng tôi đi bộ từ nhà ga về.","Hãy cẩn thận đổ sô-cô-la đã tan chảy vào khuôn.","Hộ chiếu của tôi hết hạn vào tháng tới, nên tôi phải đi gia hạn."]'::jsonb, 3, 'My passport expires next month, so I must renew it. → Hộ chiếu của tôi hết hạn vào tháng tới, nên tôi phải đi gia hạn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_76_7', 'en-b2-76', NULL, 'comprehensive_test', 'listening', 'mold', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thân cây","khuôn; khuôn đúc","ngắn hạn","cuộc đấu giá"]'::jsonb, 1, 'mold (/moʊld/) → khuôn; khuôn đúc; tạo hình; uốn nắn; định hình tính cách; nấm mốc', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_76_8', 'en-b2-76', NULL, 'comprehensive_test', 'listening', 'The mountains were barely visible through the morning mist.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi chải lông cho chú ngựa con mỗi sáng trước khi cưỡi.","Những dãy núi chỉ mờ ảo nhìn thấy qua lớp sương mù buổi sáng.","Cô ấy dừng lại để chỉnh lại cà vạt trước buổi phỏng vấn.","Cô ấy nhẹ nhàng bấm chuông cửa bằng ngón trỏ."]'::jsonb, 1, 'The mountains were barely visible through the morning mist. → Những dãy núi chỉ mờ ảo nhìn thấy qua lớp sương mù buổi sáng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_76_9', 'en-b2-76', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “small in amount, degree, or importance”?', '["straighten","slight","resemble","removal"]'::jsonb, 1, 'slight (/slaɪt/) → nhỏ; nhẹ; mong manh; không đáng kể', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
