INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_76_18', 'en-b2-76', NULL, 'comprehensive_test', 'reading', NULL, 'Workers must constantly update their skills to remain competitive in a rapidly changing labour market.', 'Dựa vào câu trên, từ “constantly” có nghĩa phù hợp nhất là gì?', '["liên tục; luôn luôn; thường xuyên","vinh dự; sự kính trọng","bằng lời nói; dạng nói (thay vì dạng viết)","sự vắng mặt; sự không có mặt"]'::jsonb, 0, 'constantly: liên tục; luôn luôn; thường xuyên. Dịch cả câu: Người lao động phải không ngừng cập nhật kỹ năng của mình để duy trì tính cạnh tranh trong một thị trường lao động thay đổi nhanh chóng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_76_19', 'en-b2-76', NULL, 'comprehensive_test', 'reading', NULL, 'A bus route forming a loop can connect residential areas with schools and local health centres.', 'Dựa vào câu trên, từ “loop” có nghĩa phù hợp nhất là gì?', '["vòng; thòng lọng; đường đi hình vòng","bồi thường; đền bù","cảm kích; biết ơn","lòng tham; sự tham lam"]'::jsonb, 0, 'loop: vòng; thòng lọng; đường đi hình vòng; uốn thành vòng; lặp lại liên tục; vòng lặp. Dịch cả câu: Một tuyến xe buýt chạy theo đường vòng có thể kết nối các khu dân cư với trường học và các trung tâm y tế địa phương.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_76_20', 'en-b2-76', NULL, 'comprehensive_test', 'reading', NULL, 'Newly qualified teachers often need additional support to manage diverse classrooms effectively during their first year.', 'Dựa vào câu trên, từ “newly” có nghĩa phù hợp nhất là gì?', '["thực sự; đích thực","mới đây; gần đây","sự biến mất; sự mất tích","đầu mẩu thuốc lá; tàn thuốc"]'::jsonb, 1, 'newly: mới đây; gần đây. Dịch cả câu: Những giáo viên mới vào nghề thường cần thêm sự hỗ trợ để quản lý các lớp học đa dạng học sinh một cách hiệu quả trong năm đầu tiên.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_76_21', 'en-b2-76', NULL, 'comprehensive_test', 'reading', NULL, 'Universities should provide additional financial support for students who cannot afford essential learning materials.', 'Dựa vào câu trên, từ “additional” có nghĩa phù hợp nhất là gì?', '["hòn cuội; viên đá nhỏ nhẵn","buổi thử vai; buổi thử giọng","chế độ dân chủ; nền dân chủ","thêm; bổ sung; phụ"]'::jsonb, 3, 'additional: thêm; bổ sung; phụ. Dịch cả câu: Các trường đại học nên cung cấp thêm hỗ trợ tài chính cho những sinh viên không có khả năng chi trả cho các tài liệu học tập thiết yếu.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_76_22', 'en-b2-76', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đều đặn; liên tục và ổn định (không có sự thay đổi hay ngắt quãng đột ngột)”', '["sewage","alter","ignorant","steadily"]'::jsonb, 3, 'đều đặn; liên tục và ổn định (không có sự thay đổi hay ngắt quãng đột ngột) → steadily (/ˈstedɪli/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_76_23', 'en-b2-76', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ngón trỏ”', '["applause","authority","forefinger","assist"]'::jsonb, 2, 'ngón trỏ → forefinger (/ˈfɔːrfɪŋɡɚ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_76_24', 'en-b2-76', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “chất tẩy rửa; bột giặt”', '["slang","tactic","detergent","swollen"]'::jsonb, 2, 'chất tẩy rửa; bột giặt → detergent (/dɪˈtɜːrdʒənt/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-77', 'en', 'Bài 77: Đời sống hằng ngày (4) - CEFR B2', 'CEFR B2', 'B2 · Đời sống', '27 từ vựng Tiếng Anh CEFR B2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4077, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_forth', 'en-b2-77', 'forth', '/fɔːrθ/', 'B2', 'về phía trước; ra ngoài; lộ ra', 'adv.', NULL, 'Đồng nghĩa: forward, onward · Trái nghĩa: backward', 'Thường đi trong các cụm từ cố định; tránh nhầm lẫn với từ fourth chỉ số thứ tư.', 'The kitten ran back and forth across the kitchen.', NULL, 'Con mèo con chạy qua chạy lại khắp căn bếp.', '{"wordId":"forth","ukIpa":"/fɔːθ/","usIpa":"/fɔːrθ/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"Forward or out from a place.","vi":"về phía trước; ra ngoài; lộ ra"}],"examples":[{"en":"The kitten ran back and forth across the kitchen.","vi":"Con mèo con chạy qua chạy lại khắp căn bếp.","audioKind":"ex"},{"en":"Residents put forth several practical proposals to improve public transport without increasing costs significantly.","vi":"Cư dân đã đưa ra một số đề xuất thiết thực nhằm cải thiện giao thông công cộng mà không làm tăng đáng kể chi phí.","audioKind":"ex2"}],"collocations":[{"en":"back and forth","vi":"qua lại; tới lui"},{"en":"put forth a proposal","vi":"đưa ra một đề xuất"},{"en":"set forth","vi":"trình bày rõ ràng; khởi hành"},{"en":"and so forth","vi":"vân vân; các thứ khác tương tự"}],"wordFamily":[],"synonyms":["forward","onward"],"antonyms":["backward"],"tipVi":"Thường đi trong các cụm từ cố định; tránh nhầm lẫn với từ fourth chỉ số thứ tư.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_beam', 'en-b2-77', 'beam', '/biːm/', 'B2', 'chùm sáng; tia sáng; xà nhà; dầm ngang; cười rạng rỡ; mỉm cười tươi', 'n.', NULL, NULL, 'Nghĩa chùm sáng và dầm đều đếm được; cụm beam at sb nghĩa là mỉm cười rạng rỡ với ai đó.', 'A beam of sunlight fell across the kitchen table.', NULL, 'Một tia nắng rọi qua chiếc bàn trong bếp.', '{"wordId":"beam","ukIpa":"/biːm/","usIpa":"/biːm/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"a narrow stream of light or other energy","vi":"chùm sáng; tia sáng"},{"pos":"n.","en":"a long, strong piece supporting a roof or floor","vi":"xà nhà; dầm ngang"},{"pos":"v.","en":"to smile with obvious happiness","vi":"cười rạng rỡ; mỉm cười tươi"}],"examples":[{"en":"A beam of sunlight fell across the kitchen table.","vi":"Một tia nắng rọi qua chiếc bàn trong bếp.","audioKind":"ex"},{"en":"Engineers used steel beams to strengthen the old bridge and improve safety for local residents.","vi":"Các kỹ sư đã dùng dầm thép để gia cố cây cầu cũ và cải thiện an toàn cho người dân địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a beam of light","vi":"một chùm sáng"},{"en":"steel beam","vi":"dầm thép"},{"en":"beam with pride","vi":"cười rạng rỡ đầy tự hào"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa chùm sáng và dầm đều đếm được; cụm beam at sb nghĩa là mỉm cười rạng rỡ với ai đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_await', 'en-b2-77', 'await', '/əˈweɪt/', 'B2', 'chờ đợi; ngóng chờ; đang chờ đón ai; sắp sửa đến với ai', 'v.', NULL, 'Đồng nghĩa: wait for', 'Từ này mang tính trang trọng và đi thẳng với tân ngữ; không dùng cấu trúc await for.', 'We eagerly await the arrival of our new puppy.', NULL, 'Chúng tôi đang hồi hộp chờ đón chú cún con mới về nhà.', '{"wordId":"await","ukIpa":"/əˈweɪt/","usIpa":"/əˈweɪt/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To wait for someone or something","vi":"chờ đợi; ngóng chờ"},{"pos":"v.","en":"To be ready or likely to happen to someone","vi":"đang chờ đón ai; sắp sửa đến với ai"}],"examples":[{"en":"We eagerly await the arrival of our new puppy.","vi":"Chúng tôi đang hồi hộp chờ đón chú cún con mới về nhà.","audioKind":"ex"},{"en":"Many graduates await job offers while developing additional skills through voluntary work and online courses.","vi":"Nhiều sinh viên tốt nghiệp đang chờ đợi các lời mời làm việc trong khi trau dồi thêm kỹ năng qua các công việc tình nguyện và khóa học trực tuyến.","audioKind":"ex2"}],"collocations":[{"en":"await a decision","vi":"chờ đợi quyết định"},{"en":"eagerly await","vi":"háo hức ngóng chờ"},{"en":"await confirmation","vi":"chờ sự xác nhận"},{"en":"challenges await","vi":"thử thách đang chờ phía trước"}],"wordFamily":[],"synonyms":["wait for"],"antonyms":[],"tipVi":"Từ này mang tính trang trọng và đi thẳng với tân ngữ; không dùng cấu trúc await for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_making', 'en-b2-77', 'making', '/ˈmeɪkɪŋ/', 'B2', 'sự chế tạo; quá trình sản xuất; yếu tố thúc đẩy thành công; phẩm chất cần thiết; tiềm năng', 'n.', 'make (v.), maker (n.)', NULL, 'Để chỉ tiềm năng, dùng danh từ số nhiều makings: have the makings of.', 'We spent the afternoon learning the basics of bread making.', NULL, 'Chúng tôi đã dành cả buổi chiều để học những bước cơ bản trong việc làm bánh mì.', '{"wordId":"making","ukIpa":"/ˈmeɪkɪŋ/","usIpa":"/ˈmeɪkɪŋ/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"The process of producing or creating something.","vi":"sự chế tạo; quá trình sản xuất"},{"pos":"n.","en":"Something that causes someone or something to become successful.","vi":"yếu tố thúc đẩy thành công"},{"pos":"n.","en":"The qualities or materials needed for something to develop.","vi":"phẩm chất cần thiết; tiềm năng"}],"examples":[{"en":"We spent the afternoon learning the basics of bread making.","vi":"Chúng tôi đã dành cả buổi chiều để học những bước cơ bản trong việc làm bánh mì.","audioKind":"ex"},{"en":"Involving residents in the making of local policy can increase public trust and improve community outcomes.","vi":"Việc cho cư dân tham gia vào quá trình hoạch định chính sách địa phương có thể tăng cường niềm tin công chúng và cải thiện kết quả phát triển cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"the making of a film","vi":"quá trình sản xuất phim"},{"en":"in the making","vi":"đang trong quá trình hình thành"},{"en":"be the making of someone","vi":"tạo nên sự thành công của ai đó"},{"en":"have the makings of","vi":"có tiềm năng trở thành"}],"wordFamily":["make (v.)","maker (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Để chỉ tiềm năng, dùng danh từ số nhiều makings: have the makings of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_blunt', 'en-b2-77', 'blunt', '/blʌnt/', 'B2', 'tù; không sắc; thẳng thắn; bộc tuệch; làm cùn; làm giảm bớt; làm suy yếu', 'adj.', 'bluntly (adv.), bluntness (n.)', 'Trái nghĩa: sharp', 'Khi dùng để miêu tả lời nói, từ này chỉ sự trực diện thậm chí mang tính xúc phạm, không nhất thiết mang nghĩa tích cực.', 'This blunt knife cannot even cut a ripe tomato.', NULL, 'Con dao cùn này thậm chí không thể cắt nổi một quả cà chua chín.', '{"wordId":"blunt","ukIpa":"/blʌnt/","usIpa":"/blʌnt/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Having an edge or point that does not cut easily.","vi":"tù; không sắc"},{"pos":"adj.","en":"Speaking directly without trying to avoid upsetting people.","vi":"thẳng thắn; bộc tuệch"},{"pos":"v.","en":"To make something less sharp, powerful, or effective.","vi":"làm cùn; làm giảm bớt; làm suy yếu"}],"examples":[{"en":"This blunt knife cannot even cut a ripe tomato.","vi":"Con dao cùn này thậm chí không thể cắt nổi một quả cà chua chín.","audioKind":"ex"},{"en":"Although blunt feedback can feel uncomfortable, it sometimes helps students identify weaknesses in their work.","vi":"Mặc dù những lời nhận xét thẳng thắn có thể gây khó chịu, nhưng đôi khi chúng giúp học sinh nhận ra những điểm yếu trong bài làm của mình.","audioKind":"ex2"}],"collocations":[{"en":"a blunt knife","vi":"một con dao cùn"},{"en":"a blunt answer","vi":"câu trả lời thẳng thắn"},{"en":"blunt the impact","vi":"làm giảm tác động"}],"wordFamily":["bluntly (adv.)","bluntness (n.)"],"synonyms":[],"antonyms":["sharp"],"tipVi":"Khi dùng để miêu tả lời nói, từ này chỉ sự trực diện thậm chí mang tính xúc phạm, không nhất thiết mang nghĩa tích cực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_linen', 'en-b2-77', 'linen', '/ˈlɪnɪn/', 'B2', 'vải lanh; đồ vải gia dụng (như ga giường, vỏ gối, khăn trải bàn)', 'n.', NULL, NULL, 'Thường là danh từ không đếm được; bed linen không nhất thiết hoàn toàn làm bằng vải lanh.', 'I wore a linen shirt on the hot afternoon.', NULL, 'Tôi đã mặc một chiếc áo sơ mi bằng vải lanh vào buổi chiều trời nóng bức đó.', '{"wordId":"linen","ukIpa":"/ˈlɪnɪn/","usIpa":"/ˈlɪnɪn/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"strong cloth made from fibres of the flax plant","vi":"vải lanh"},{"pos":"n.","en":"household cloth items such as sheets, pillowcases, and tablecloths","vi":"đồ vải gia dụng (như ga giường, vỏ gối, khăn trải bàn)"}],"examples":[{"en":"I wore a linen shirt on the hot afternoon.","vi":"Tôi đã mặc một chiếc áo sơ mi bằng vải lanh vào buổi chiều trời nóng bức đó.","audioKind":"ex"},{"en":"Hotels can reduce water consumption by encouraging guests to reuse towels and change bed linen less frequently.","vi":"Các khách sạn có thể giảm lượng nước tiêu thụ bằng cách khuyến khích khách tái sử dụng khăn tắm và thay ga trải giường ít thường xuyên hơn.","audioKind":"ex2"}],"collocations":[{"en":"a linen shirt","vi":"áo sơ mi vải lanh"},{"en":"bed linen","vi":"ga trải giường"},{"en":"table linen","vi":"đồ vải bàn ăn"},{"en":"fresh linen","vi":"đồ vải sạch"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; bed linen không nhất thiết hoàn toàn làm bằng vải lanh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conceal', 'en-b2-77', 'conceal', '/kənˈsiːl/', 'B2', 'che giấu; giấu kín không để nhìn thấy; che đậy sự thật hoặc cảm xúc', 'v.', 'concealment (n.), concealed (adj.)', 'Đồng nghĩa: hide, cover · Trái nghĩa: reveal, expose', 'conceal mang tính trang trọng hơn hide; thường dùng cấu trúc conceal sth from sb.', 'She concealed the birthday present behind a large cushion.', NULL, 'Cô ấy giấu món quà sinh nhật đằng sau chiếc gối lớn.', '{"wordId":"conceal","ukIpa":"/kənˈsiːl/","usIpa":"/kənˈsiːl/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To keep something from being seen","vi":"che giấu; giấu kín không để nhìn thấy"},{"pos":"v.","en":"To prevent facts or feelings from becoming known","vi":"che đậy sự thật hoặc cảm xúc"}],"examples":[{"en":"She concealed the birthday present behind a large cushion.","vi":"Cô ấy giấu món quà sinh nhật đằng sau chiếc gối lớn.","audioKind":"ex"},{"en":"Companies that conceal environmental damage from the public risk losing consumer trust when the truth emerges.","vi":"Các công ty che giấu hành vi phá hoại môi trường trước công chúng có nguy cơ đánh mất lòng tin của người tiêu dùng khi sự thật phơi bày.","audioKind":"ex2"}],"collocations":[{"en":"conceal evidence","vi":"che giấu bằng chứng"},{"en":"conceal the truth","vi":"che đậy sự thật"},{"en":"conceal feelings","vi":"giấu kín cảm xúc"},{"en":"conceal something from someone","vi":"giấu ai điều gì"}],"wordFamily":["concealment (n.)","concealed (adj.)"],"synonyms":["hide","cover"],"antonyms":["reveal","expose"],"tipVi":"conceal mang tính trang trọng hơn hide; thường dùng cấu trúc conceal sth from sb.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_splash', 'en-b2-77', 'splash', '/splæʃ/', 'B2', 'làm bắn tóe chất lỏng; tạt nước; tiếng nước bắn; giọt nước bắn tóe; một ít chất lỏng hoặc một mảng màu nổi bật', 'v.', NULL, 'Đồng nghĩa: splatter', 'splash out on là cụm từ thông dụng trong tiếng Anh-Anh, chỉ việc vung tiền mua sắm món đồ đắt tiền.', 'The dog splashed water all over my trousers.', NULL, 'Con chó làm nước bắn tung tóe khắp chiếc quần của tôi.', '{"wordId":"splash","ukIpa":"/splæʃ/","usIpa":"/splæʃ/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To make liquid scatter in drops or hit something.","vi":"làm bắn tóe chất lỏng; tạt nước"},{"pos":"n.","en":"Scattered drops of liquid, or the sound they make.","vi":"tiếng nước bắn; giọt nước bắn tóe"},{"pos":"n.","en":"A small amount of liquid or a noticeable patch of colour.","vi":"một ít chất lỏng hoặc một mảng màu nổi bật"}],"examples":[{"en":"The dog splashed water all over my trousers.","vi":"Con chó làm nước bắn tung tóe khắp chiếc quần của tôi.","audioKind":"ex"},{"en":"Vehicles travelling through flooded streets can splash dirty water onto pedestrians and damage nearby shop displays.","vi":"Các phương tiện di chuyển qua những con đường ngập nước có thể làm bắn nước bẩn lên người đi bộ và làm hỏng các tủ trưng bày của cửa hàng gần đó.","audioKind":"ex2"}],"collocations":[{"en":"splash water on","vi":"tạt nước vào"},{"en":"a splash of colour","vi":"một chút màu sắc"},{"en":"make a splash","vi":"gây tiếng vang lớn; tạo sự chú ý"},{"en":"splash out on","vi":"vung tiền mua sắm"}],"wordFamily":[],"synonyms":["splatter"],"antonyms":[],"tipVi":"splash out on là cụm từ thông dụng trong tiếng Anh-Anh, chỉ việc vung tiền mua sắm món đồ đắt tiền.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_baggy', 'en-b2-77', 'baggy', '/ˈbæɡi/', 'B2', 'rộng thùng thình; rộng và lùng bùng', 'adj.', 'bagginess (n.)', 'Đồng nghĩa: loose, loose-fitting · Trái nghĩa: tight, close-fitting', 'baggy dùng để chỉ quần áo rộng rãi, không dùng để chỉ hình dáng của cái túi.', 'These baggy trousers feel comfortable on long train journeys.', NULL, 'Mặc chiếc quần rộng thùng thình này đi những chuyến tàu dài rất thoải mái.', '{"wordId":"baggy","ukIpa":"/ˈbæɡi/","usIpa":"/ˈbæɡi/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Loose and hanging away from the body.","vi":"rộng thùng thình; rộng và lùng bùng"}],"examples":[{"en":"These baggy trousers feel comfortable on long train journeys.","vi":"Mặc chiếc quần rộng thùng thình này đi những chuyến tàu dài rất thoải mái.","audioKind":"ex"},{"en":"Some young people choose baggy clothing to express their identity rather than follow traditional expectations.","vi":"Một số bạn trẻ chọn mặc trang phục rộng rãi để thể hiện cá tính thay vì tuân theo những kỳ vọng truyền thống.","audioKind":"ex2"}],"collocations":[{"en":"baggy trousers","vi":"quần rộng thùng thình"},{"en":"baggy jeans","vi":"quần bò rộng"},{"en":"a baggy sweater","vi":"chiếc áo len rộng"}],"wordFamily":["bagginess (n.)"],"synonyms":["loose","loose-fitting"],"antonyms":["tight","close-fitting"],"tipVi":"baggy dùng để chỉ quần áo rộng rãi, không dùng để chỉ hình dáng của cái túi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_eve', 'en-b2-77', 'Eve', '/iːv/', 'B2', 'đêm trước (của một ngày lễ hoặc sự kiện trọng đại); chiều ngày hôm trước; Hà-vê (người phụ nữ đầu tiên trong Kinh Thánh)', 'n.', NULL, NULL, 'Danh từ chung eve thường viết thường; khi đi với tên ngày lễ thì viết hoa, Eve cũng là tên riêng chỉ Hà-vê.', 'We cooked a special dinner together on New Year''s Eve.', NULL, 'Chúng tôi đã cùng nhau nấu một bữa tối đặc biệt vào đêm giao thừa.', '{"wordId":"eve","ukIpa":"/iːv/","usIpa":"/iːv/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"The day or evening before a special day or event.","vi":"đêm trước (của một ngày lễ hoặc sự kiện trọng đại); chiều ngày hôm trước"},{"pos":"n.","en":"The first woman in the biblical account of creation.","vi":"Hà-vê (người phụ nữ đầu tiên trong Kinh Thánh)"}],"examples":[{"en":"We cooked a special dinner together on New Year''s Eve.","vi":"Chúng tôi đã cùng nhau nấu một bữa tối đặc biệt vào đêm giao thừa.","audioKind":"ex"},{"en":"On New Year''s Eve, cities often extend public transport services to help large crowds travel home safely.","vi":"Vào đêm giao thừa, các thành phố thường kéo dài thời gian hoạt động của phương tiện giao thông công cộng để giúp lượng lớn người dân về nhà an toàn.","audioKind":"ex2"}],"collocations":[{"en":"New Year''s Eve","vi":"đêm giao thừa"},{"en":"Christmas Eve","vi":"đêm Giáng sinh"},{"en":"on the eve of","vi":"vào đêm trước của"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ chung eve thường viết thường; khi đi với tên ngày lễ thì viết hoa, Eve cũng là tên riêng chỉ Hà-vê.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shove', 'en-b2-77', 'shove', '/ʃʌv/', 'B2', 'xô đẩy; nhét vội; cú xô; cú đẩy mạnh', 'v.', NULL, 'Đồng nghĩa: push, thrust', 'Mạnh mẽ hơn push, nhấn mạnh sự dùng lực mạnh hoặc thô bạo; dùng được khi nhét đồ đạc.', 'I shoved my gloves into my bag and hurried outside.', NULL, 'Tôi nhét vội găng tay vào túi rồi vội vã chạy ra ngoài.', '{"wordId":"shove","ukIpa":"/ʃʌv/","usIpa":"/ʃʌv/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to push roughly or put something somewhere carelessly","vi":"xô đẩy; nhét vội"},{"pos":"n.","en":"a strong, rough push","vi":"cú xô; cú đẩy mạnh"}],"examples":[{"en":"I shoved my gloves into my bag and hurried outside.","vi":"Tôi nhét vội găng tay vào túi rồi vội vã chạy ra ngoài.","audioKind":"ex"},{"en":"Passengers may shove one another when overcrowded stations lack effective systems for managing queues during peak hours.","vi":"Hành khách có thể xô đẩy lẫn nhau khi các nhà ga quá đông đúc thiếu các hệ thống quản lý hàng đợi hiệu quả vào giờ cao điểm.","audioKind":"ex2"}],"collocations":[{"en":"shove something into a bag","vi":"nhét thứ gì vào túi"},{"en":"give something a shove","vi":"đẩy mạnh thứ gì đó một cái"},{"en":"shove past someone","vi":"lách người vượt qua ai đó"}],"wordFamily":[],"synonyms":["push","thrust"],"antonyms":[],"tipVi":"Mạnh mẽ hơn push, nhấn mạnh sự dùng lực mạnh hoặc thô bạo; dùng được khi nhét đồ đạc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shutter', 'en-b2-77', 'shutter', '/ˈʃʌt̬.ɚ/', 'B2', 'tấm chớp che cửa; cửa chớp; tốc độ chụp; màn chập (máy ảnh); đóng cửa; ngừng kinh doanh', 'n.', NULL, NULL, 'Tấm chớp che cửa thường dùng số nhiều shutters; tốc độ chụp dùng shutter speed.', 'I closed the wooden shutters before the storm arrived.', NULL, 'Tôi đã đóng các cánh cửa chớp bằng gỗ trước khi cơn bão ập đến.', '{"wordId":"shutter","ukIpa":"/ˈʃʌt.ə/","usIpa":"/ˈʃʌt̬.ɚ/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A movable panel that covers and protects a window","vi":"tấm chớp che cửa; cửa chớp"},{"pos":"n.","en":"A camera mechanism controlling how long light enters","vi":"tốc độ chụp; màn chập (máy ảnh)"},{"pos":"v.","en":"To close a building or business, temporarily or permanently","vi":"đóng cửa; ngừng kinh doanh"}],"examples":[{"en":"I closed the wooden shutters before the storm arrived.","vi":"Tôi đã đóng các cánh cửa chớp bằng gỗ trước khi cơn bão ập đến.","audioKind":"ex"},{"en":"Photographers use a fast shutter speed to capture moving wildlife clearly without disturbing its natural behaviour.","vi":"Các nhiếp ảnh gia sử dụng tốc độ màn chập nhanh để chụp rõ nét động vật hoang dã đang di chuyển mà không làm ảnh hưởng đến tập tính tự nhiên của chúng.","audioKind":"ex2"}],"collocations":[{"en":"close the shutters","vi":"đóng cửa chớp"},{"en":"wooden shutters","vi":"cửa chớp bằng gỗ"},{"en":"shutter speed","vi":"tốc độ màn chập"},{"en":"shutter a factory","vi":"đóng cửa nhà máy"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tấm chớp che cửa thường dùng số nhiều shutters; tốc độ chụp dùng shutter speed.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_likewise', 'en-b2-77', 'likewise', '/ˈlaɪkwaɪz/', 'B2', 'trạng thái: tương tự; cũng vậy', 'adv.', NULL, 'Đồng nghĩa: similarly, also', 'Đây là từ mang tính trang trọng, thường dùng để liên kết các tình huống tương đồng; cụm do likewise nghĩa là làm theo như vậy.', 'I folded my umbrella, and my sister did likewise.', NULL, 'Tôi gấp ô lại, và chị gái tôi cũng làm như vậy.', '{"wordId":"likewise","ukIpa":"/ˈlaɪkwaɪz/","usIpa":"/ˈlaɪkwaɪz/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"In the same way, or also.","vi":"trạng thái: tương tự; cũng vậy"}],"examples":[{"en":"I folded my umbrella, and my sister did likewise.","vi":"Tôi gấp ô lại, và chị gái tôi cũng làm như vậy.","audioKind":"ex"},{"en":"Public libraries provide free internet access; likewise, community centres help residents develop essential digital skills.","vi":"Các thư viện công cộng cung cấp quyền truy cập internet miễn phí; tương tự, các trung tâm cộng đồng cũng giúp người dân phát triển các kỹ năng số thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"do likewise","vi":"làm theo cách tương tự"},{"en":"likewise important","vi":"tương tự quan trọng"},{"en":"be likewise affected","vi":"cũng chịu ảnh hưởng tương tự"}],"wordFamily":[],"synonyms":["similarly","also"],"antonyms":[],"tipVi":"Đây là từ mang tính trang trọng, thường dùng để liên kết các tình huống tương đồng; cụm do likewise nghĩa là làm theo như vậy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scarcely', 'en-b2-77', 'scarcely', '/ˈskersli/', 'B2', 'hầu như không, vừa mới; vừa mới, chỉ một thời gian rất ngắn trước khi có việc khác xảy ra', 'adv.', 'scarce (adj.), scarcity (n.)', 'Đồng nghĩa: hardly, barely', 'Bản thân từ này đã mang nghĩa phủ định nên không dùng thêm not; cấu trúc "scarcely... when" nghĩa là vừa mới... thì...', 'We could scarcely hear each other above the music.', NULL, 'Chúng tôi hầu như không nghe thấy tiếng của nhau vì tiếng nhạc quá lớn.', '{"wordId":"scarcely","ukIpa":"/ˈskeəsli/","usIpa":"/ˈskersli/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"Almost not, or only just","vi":"hầu như không, vừa mới"},{"pos":"adv.","en":"Only a very short time before something else happens","vi":"vừa mới, chỉ một thời gian rất ngắn trước khi có việc khác xảy ra"}],"examples":[{"en":"We could scarcely hear each other above the music.","vi":"Chúng tôi hầu như không nghe thấy tiếng của nhau vì tiếng nhạc quá lớn.","audioKind":"ex"},{"en":"Some rural communities have scarcely enough medical staff to provide basic healthcare for their growing populations.","vi":"Một số cộng đồng nông thôn hầu như không có đủ nhân viên y tế để cung cấp dịch vụ chăm sóc sức khỏe cơ bản cho dân số đang gia tăng của họ.","audioKind":"ex2"}],"collocations":[{"en":"scarcely any","vi":"hầu như không có gì"},{"en":"scarcely enough","vi":"vừa đủ, suýt soát đủ"},{"en":"scarcely ever","vi":"hầu như chưa bao giờ"}],"wordFamily":["scarce (adj.)","scarcity (n.)"],"synonyms":["hardly","barely"],"antonyms":[],"tipVi":"Bản thân từ này đã mang nghĩa phủ định nên không dùng thêm not; cấu trúc \"scarcely... when\" nghĩa là vừa mới... thì...","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stool', 'en-b2-77', 'stool', '/stuːl/', 'B2', 'ghế đẩu (ghế không có tựa lưng và tay vịn); phân, chất thải rắn của cơ thể (đặc biệt trong bối cảnh y tế)', 'n.', NULL, NULL, 'Trong ngữ cảnh y tế, từ này chỉ phân, có thể dùng dạng số ít hoặc số nhiều chứ không bắt buộc dùng số nhiều.', 'She pulled up a stool beside the kitchen counter.', NULL, 'Cô ấy kéo một chiếc ghế đẩu lại gần bàn bếp.', '{"wordId":"stool","ukIpa":"/stuːl/","usIpa":"/stuːl/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"a seat without a back or arms","vi":"ghế đẩu (ghế không có tựa lưng và tay vịn)"},{"pos":"n.","en":"solid waste passed from the body, especially in medical contexts","vi":"phân, chất thải rắn của cơ thể (đặc biệt trong bối cảnh y tế)"}],"examples":[{"en":"She pulled up a stool beside the kitchen counter.","vi":"Cô ấy kéo một chiếc ghế đẩu lại gần bàn bếp.","audioKind":"ex"},{"en":"Doctors may examine a stool sample to identify infections that cannot be diagnosed through symptoms alone.","vi":"Các bác sĩ có thể xét nghiệm mẫu phân để xác định các bệnh nhiễm trùng mà không thể chẩn đoán chỉ qua triệu chứng.","audioKind":"ex2"}],"collocations":[{"en":"bar stool","vi":"ghế đẩu quầy bar"},{"en":"wooden stool","vi":"ghế đẩu bằng gỗ"},{"en":"stool sample","vi":"mẫu phân"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong ngữ cảnh y tế, từ này chỉ phân, có thể dùng dạng số ít hoặc số nhiều chứ không bắt buộc dùng số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_confirmation', 'en-b2-77', 'confirmation', '/ˌkɑːnfərˈmeɪʃən/', 'B2', 'sự xác nhận; thông báo xác nhận; sự chứng thực; minh chứng', 'n.', 'confirm (v.), confirmed (adj.)', 'Đồng nghĩa: verification, corroboration', 'Thường dùng confirmation of sth; để xác nhận việc gì đó là đúng có thể dùng mệnh đề that.', 'The hotel sent confirmation of our booking this morning.', NULL, 'Khách sạn đã gửi thông báo xác nhận đặt phòng của chúng tôi vào sáng nay.', '{"wordId":"confirmation","ukIpa":"/ˌkɒnfəˈmeɪʃən/","usIpa":"/ˌkɑːnfərˈmeɪʃən/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"An assurance or message that an arrangement is definite.","vi":"sự xác nhận; thông báo xác nhận"},{"pos":"n.","en":"Evidence showing that something is true or correct.","vi":"sự chứng thực; minh chứng"}],"examples":[{"en":"The hotel sent confirmation of our booking this morning.","vi":"Khách sạn đã gửi thông báo xác nhận đặt phòng của chúng tôi vào sáng nay.","audioKind":"ex"},{"en":"Independent confirmation of research findings is essential before governments use them to guide public health policy.","vi":"Việc độc lập xác thực các kết quả nghiên cứu là rất cần thiết trước khi chính phủ dùng chúng để định hướng chính sách y tế công cộng.","audioKind":"ex2"}],"collocations":[{"en":"booking confirmation","vi":"xác nhận đặt phòng"},{"en":"written confirmation","vi":"xác nhận bằng văn bản"},{"en":"confirmation of receipt","vi":"xác nhận đã nhận"},{"en":"independent confirmation","vi":"sự xác thực độc lập"}],"wordFamily":["confirm (v.)","confirmed (adj.)"],"synonyms":["verification","corroboration"],"antonyms":[],"tipVi":"Thường dùng confirmation of sth; để xác nhận việc gì đó là đúng có thể dùng mệnh đề that.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_burner', 'en-b2-77', 'burner', '/ˈbɝːnɚ/', 'B2', 'mâm nhiệt bếp; đầu đốt; lò đốt', 'n.', 'burn (v.), burning (adj.), burnt (adj.)', NULL, 'Cụm on the back burner mang nghĩa bóng là tạm hoãn xử lý hoặc gác lại một việc gì đó.', 'She turned off the burner after the soup boiled.', NULL, 'Cô ấy tắt bếp nấu sau khi nồi súp sôi lên.', '{"wordId":"burner","ukIpa":"/ˈbɜːnə/","usIpa":"/ˈbɝːnɚ/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"The part of a cooker or heater that produces heat","vi":"mâm nhiệt bếp; đầu đốt; lò đốt"}],"examples":[{"en":"She turned off the burner after the soup boiled.","vi":"Cô ấy tắt bếp nấu sau khi nồi súp sôi lên.","audioKind":"ex"},{"en":"Replacing inefficient gas burners with cleaner cooking technology can reduce indoor air pollution and improve health.","vi":"Việc thay thế các lò đốt gas kém hiệu quả bằng công nghệ nấu nướng sạch hơn có thể làm giảm ô nhiễm không khí trong nhà và cải thiện sức khỏe.","audioKind":"ex2"}],"collocations":[{"en":"gas burner","vi":"bếp gas; đầu đốt gas"},{"en":"oil burner","vi":"đầu đốt dầu"},{"en":"put something on the back burner","vi":"gác lại việc gì; tạm hoãn xử lý"}],"wordFamily":["burn (v.)","burning (adj.)","burnt (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm on the back burner mang nghĩa bóng là tạm hoãn xử lý hoặc gác lại một việc gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_faint', 'en-b2-77', 'faint', '/feɪnt/', 'B2', 'mờ nhạt; yếu ớt; thoang thoảng; choáng váng; hoa mắt; sắp ngất; ngất xỉu; ngất đi', 'adj.', 'faintly (adv.), faintness (n.)', 'Đồng nghĩa: weak, dim · Trái nghĩa: strong', 'feel faint là cảm giác sắp ngất; faint đóng vai trò động từ mới mang nghĩa ngất xỉu.', 'A faint light shone through the bedroom curtains.', NULL, 'Ánh sáng mờ ảo chiếu qua rèm cửa phòng ngủ.', '{"wordId":"faint","ukIpa":"/feɪnt/","usIpa":"/feɪnt/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"not strong, clear or easy to notice","vi":"mờ nhạt; yếu ớt; thoang thoảng"},{"pos":"adj.","en":"feeling weak and close to losing consciousness","vi":"choáng váng; hoa mắt; sắp ngất"},{"pos":"v.","en":"to suddenly lose consciousness for a short time","vi":"ngất xỉu; ngất đi"}],"examples":[{"en":"A faint light shone through the bedroom curtains.","vi":"Ánh sáng mờ ảo chiếu qua rèm cửa phòng ngủ.","audioKind":"ex"},{"en":"Astronomers use powerful telescopes to detect faint objects that cannot be seen with the naked eye.","vi":"Các nhà thiên văn học sử dụng kính thiên văn công suất lớn để phát hiện các thiên thể mờ nhạt không thể nhìn thấy bằng mắt thường.","audioKind":"ex2"}],"collocations":[{"en":"faint light","vi":"ánh sáng mờ nhạt"},{"en":"faint smell","vi":"mùi thoang thoảng"},{"en":"feel faint","vi":"cảm thấy chóng mặt sắp ngất"},{"en":"faint hope","vi":"hy vọng mong manh"}],"wordFamily":["faintly (adv.)","faintness (n.)"],"synonyms":["weak","dim"],"antonyms":["strong"],"tipVi":"feel faint là cảm giác sắp ngất; faint đóng vai trò động từ mới mang nghĩa ngất xỉu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_crawl', 'en-b2-77', 'crawl', '/krɔːl/', 'B2', 'bò; trườn (bằng tay và đầu gối); di chuyển cực kỳ chậm chạp; kiểu bơi sải', 'v.', 'crawler (n.)', NULL, 'Xe cộ crawl nghĩa là di chuyển rất chậm; bơi sải thường gọi là front crawl.', 'The baby crawled across the rug towards her toy.', NULL, 'Em bé bò qua tấm thảm để tiến về phía món đồ chơi của mình.', '{"wordId":"crawl","ukIpa":"/krɔːl/","usIpa":"/krɔːl/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To move close to the ground using hands and knees.","vi":"bò; trườn (bằng tay và đầu gối)"},{"pos":"v.","en":"To move extremely slowly.","vi":"di chuyển cực kỳ chậm chạp"},{"pos":"n.","en":"A swimming style using alternating arm strokes and kicking legs.","vi":"kiểu bơi sải"}],"examples":[{"en":"The baby crawled across the rug towards her toy.","vi":"Em bé bò qua tấm thảm để tiến về phía món đồ chơi của mình.","audioKind":"ex"},{"en":"During peak hours, traffic crawls through the city centre, increasing journey times and vehicle emissions.","vi":"Vào giờ cao điểm, các phương tiện nối đuôi nhau bò qua trung tâm thành phố, làm tăng thời gian di chuyển và lượng khí thải.","audioKind":"ex2"}],"collocations":[{"en":"crawl on hands and knees","vi":"bò bằng cả tay và chân"},{"en":"crawl along","vi":"lết đi chầm chậm"},{"en":"slow to a crawl","vi":"giảm tốc độ xuống mức rùa bò"},{"en":"front crawl","vi":"kiểu bơi sải"}],"wordFamily":["crawler (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Xe cộ crawl nghĩa là di chuyển rất chậm; bơi sải thường gọi là front crawl.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_circular', 'en-b2-77', 'circular', '/ˈsɝːkjələr/', 'B2', 'hình tròn; có dạng vòng tròn; mang tính tuần hoàn; thông cáo; thư thông tri', 'adj.', 'circle (n.), circle (v.)', 'Đồng nghĩa: round', 'Circular argument dùng để chỉ kiểu lập luận dùng chính kết luận để chứng minh cho nó (lập luận quẩn quanh).', 'We placed a circular rug under the coffee table.', NULL, 'Chúng tôi đặt một chiếc thảm tròn ở dưới bàn uống nước.', '{"wordId":"circular","ukIpa":"/ˈsɜːkjələ/","usIpa":"/ˈsɝːkjələr/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Shaped like a circle or following a round path.","vi":"hình tròn; có dạng vòng tròn"},{"pos":"adj.","en":"Returning to the starting point rather than progressing.","vi":"mang tính tuần hoàn"},{"pos":"n.","en":"A printed message distributed to many people.","vi":"thông cáo; thư thông tri"}],"examples":[{"en":"We placed a circular rug under the coffee table.","vi":"Chúng tôi đặt một chiếc thảm tròn ở dưới bàn uống nước.","audioKind":"ex"},{"en":"A circular economy aims to reduce waste by keeping materials in use for as long as possible.","vi":"Nền kinh tế tuần hoàn hướng tới mục tiêu giảm thiểu rác thải bằng cách giữ cho vật liệu được tái sử dụng trong thời gian dài nhất có thể.","audioKind":"ex2"}],"collocations":[{"en":"a circular table","vi":"một cái bàn tròn"},{"en":"a circular route","vi":"tuyến đường vòng"},{"en":"a circular economy","vi":"nền kinh tế tuần hoàn"},{"en":"a circular argument","vi":"lập luận vòng vo"}],"wordFamily":["circle (n.)","circle (v.)"],"synonyms":["round"],"antonyms":[],"tipVi":"Circular argument dùng để chỉ kiểu lập luận dùng chính kết luận để chứng minh cho nó (lập luận quẩn quanh).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fragrance', 'en-b2-77', 'fragrance', '/ˈfreɪɡrəns/', 'B2', 'hương thơm; mùi thơm; nước hoa; chất tạo hương', 'n.', 'fragrant (adj.)', 'Đồng nghĩa: scent, aroma · Trái nghĩa: stench', '"fragrance" thường chỉ mùi thơm dễ chịu; trong khi "smell" có thể mang nghĩa tích cực hoặc tiêu cực.', 'The fragrance of fresh roses filled the small kitchen.', NULL, 'Hương thơm của hoa hồng tươi tràn ngập căn bếp nhỏ.', '{"wordId":"fragrance","ukIpa":"/ˈfreɪɡrəns/","usIpa":"/ˈfreɪɡrəns/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A pleasant smell, especially from flowers or perfume.","vi":"hương thơm; mùi thơm"},{"pos":"n.","en":"A liquid or substance used to give a pleasant smell.","vi":"nước hoa; chất tạo hương"}],"examples":[{"en":"The fragrance of fresh roses filled the small kitchen.","vi":"Hương thơm của hoa hồng tươi tràn ngập căn bếp nhỏ.","audioKind":"ex"},{"en":"Some consumers prefer products without added fragrance because scented ingredients can irritate sensitive skin.","vi":"Một số người tiêu dùng ưa chuộng các sản phẩm không thêm hương liệu vì các thành phần tạo mùi có thể gây kích ứng da nhạy cảm.","audioKind":"ex2"}],"collocations":[{"en":"delicate fragrance","vi":"hương thơm dịu nhẹ"},{"en":"floral fragrance","vi":"hương hoa"},{"en":"added fragrance","vi":"hương liệu được thêm vào"},{"en":"fragrance-free products","vi":"sản phẩm không mùi"}],"wordFamily":["fragrant (adj.)"],"synonyms":["scent","aroma"],"antonyms":["stench"],"tipVi":"\"fragrance\" thường chỉ mùi thơm dễ chịu; trong khi \"smell\" có thể mang nghĩa tích cực hoặc tiêu cực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_overlapping', 'en-b2-77', 'overlapping', '/ˌoʊvərˈlæpɪŋ/', 'B2', 'chồng lên nhau; gối lên nhau; giao thoa; trùng lặp', 'adj.', 'overlap (v.), overlap (n.)', 'Trái nghĩa: non-overlapping', 'Nhấn mạnh sự trùng lặp một phần, không nhất thiết hoàn toàn giống nhau; cũng có thể chỉ thời gian trùng lặp.', 'The roof was covered with rows of overlapping tiles.', NULL, 'Mái nhà được lợp bằng các lớp ngói xếp chồng lên nhau.', '{"wordId":"overlapping","ukIpa":"/ˌəʊvəˈlæpɪŋ/","usIpa":"/ˌoʊvərˈlæpɪŋ/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Covering part of the same area or period.","vi":"chồng lên nhau; gối lên nhau"},{"pos":"adj.","en":"Sharing some features, interests, or responsibilities.","vi":"giao thoa; trùng lặp"}],"examples":[{"en":"The roof was covered with rows of overlapping tiles.","vi":"Mái nhà được lợp bằng các lớp ngói xếp chồng lên nhau.","audioKind":"ex"},{"en":"Overlapping responsibilities between government departments can create confusion and delay the implementation of essential public services.","vi":"Trách nhiệm chồng chéo giữa các cơ quan chính phủ có thể gây ra sự nhầm lẫn và làm chậm trễ việc thực hiện các dịch vụ công thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"overlapping responsibilities","vi":"trách nhiệm chồng chéo"},{"en":"overlapping interests","vi":"lợi ích chung"},{"en":"overlapping circles","vi":"các hình tròn giao nhau"}],"wordFamily":["overlap (v.)","overlap (n.)"],"synonyms":[],"antonyms":["non-overlapping"],"tipVi":"Nhấn mạnh sự trùng lặp một phần, không nhất thiết hoàn toàn giống nhau; cũng có thể chỉ thời gian trùng lặp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dine', 'en-b2-77', 'dine', '/daɪn/', 'B2', 'dùng bữa; ăn tối', 'v.', 'diner (n.), dining (n.), dinner (n.)', 'Đồng nghĩa: eat', 'Trang trọng hơn "eat", thường không đi trực tiếp với tân ngữ chỉ đồ ăn.', 'We dined outside beside the river last night.', NULL, 'Tối qua chúng tôi đã dùng bữa ngoài trời bên bờ sông.', '{"wordId":"dine","ukIpa":"/daɪn/","usIpa":"/daɪn/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To eat a meal, especially dinner.","vi":"dùng bữa; ăn tối"}],"examples":[{"en":"We dined outside beside the river last night.","vi":"Tối qua chúng tôi đã dùng bữa ngoài trời bên bờ sông.","audioKind":"ex"},{"en":"Tourists who dine at locally owned restaurants can support small businesses and experience regional food traditions.","vi":"Du khách dùng bữa tại các nhà hàng do người dân địa phương làm chủ có thể hỗ trợ các doanh nghiệp nhỏ và trải nghiệm truyền thống ẩm thực vùng miền.","audioKind":"ex2"}],"collocations":[{"en":"dine out","vi":"đi ăn ngoài"},{"en":"dine with friends","vi":"dùng bữa với bạn bè"},{"en":"dine at a restaurant","vi":"dùng bữa tại nhà hàng"}],"wordFamily":["diner (n.)","dining (n.)","dinner (n.)"],"synonyms":["eat"],"antonyms":[],"tipVi":"Trang trọng hơn \"eat\", thường không đi trực tiếp với tân ngữ chỉ đồ ăn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_knot', 'en-b2-77', 'knot', '/nɑːt/', 'B2', 'nút thắt; mối buộc; thắt nút; buộc chặt; hải lý trên giờ (đơn vị tốc độ)', 'n.', 'knotted (adj), knotty (adj)', NULL, 'Âm "k" là âm câm; đơn vị tốc độ "knot" bằng một hải lý mỗi giờ.', 'This knot is too tight for me to undo.', NULL, 'Nút thắt này chặt quá, tôi không thể gỡ ra được.', '{"wordId":"knot","ukIpa":"/nɒt/","usIpa":"/nɑːt/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A tight fastening made by tying rope or string.","vi":"nút thắt; mối buộc"},{"pos":"v.","en":"To tie something into a knot.","vi":"thắt nút; buộc chặt"},{"pos":"n.","en":"A speed unit equal to one nautical mile per hour.","vi":"hải lý trên giờ (đơn vị tốc độ)"}],"examples":[{"en":"This knot is too tight for me to undo.","vi":"Nút thắt này chặt quá, tôi không thể gỡ ra được.","audioKind":"ex"},{"en":"During outdoor education courses, students learn to tie a secure knot before attempting basic climbing activities.","vi":"Trong các khóa học giáo dục ngoài trời, học sinh học cách thắt nút an toàn trước khi thử các hoạt động leo trèo cơ bản.","audioKind":"ex2"}],"collocations":[{"en":"tie a knot","vi":"thắt nút"},{"en":"undo a knot","vi":"gỡ nút thắt"},{"en":"a tight knot","vi":"nút thắt chặt"},{"en":"a speed of twenty knots","vi":"tốc độ hai mươi hải lý một giờ"}],"wordFamily":["knotted (adj)","knotty (adj)"],"synonyms":[],"antonyms":[],"tipVi":"Âm \"k\" là âm câm; đơn vị tốc độ \"knot\" bằng một hải lý mỗi giờ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fragile', 'en-b2-77', 'fragile', '/ˈfrædʒəl/', 'B2', 'dễ vỡ; dễ hỏng; mong manh; yếu ớt; dễ bị tổn thương', 'adj.', 'fragility (n.)', 'Đồng nghĩa: delicate, breakable · Trái nghĩa: robust, sturdy', 'Có thể dùng để miêu tả đồ vật dễ vỡ, cũng có thể dùng cho nền kinh tế hoặc tâm trạng yếu ớt, dễ tổn thương.', 'Please wrap these fragile cups before packing them.', NULL, 'Vui lòng bọc kỹ những chiếc cốc dễ vỡ này trước khi đóng thùng.', '{"wordId":"fragile","ukIpa":"/ˈfrædʒaɪl/","usIpa":"/ˈfrædʒəl/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Easily broken or damaged","vi":"dễ vỡ; dễ hỏng"},{"pos":"adj.","en":"Easily weakened, upset, or disrupted","vi":"mong manh; yếu ớt; dễ bị tổn thương"}],"examples":[{"en":"Please wrap these fragile cups before packing them.","vi":"Vui lòng bọc kỹ những chiếc cốc dễ vỡ này trước khi đóng thùng.","audioKind":"ex"},{"en":"Tourism can threaten fragile ecosystems when large groups visit sensitive habitats without adequate environmental safeguards.","vi":"Du lịch có thể đe dọa các hệ sinh thái mong manh khi các đoàn khách lớn đến thăm những môi trường sống nhạy cảm mà không có biện pháp bảo vệ môi trường đầy đủ.","audioKind":"ex2"}],"collocations":[{"en":"fragile glass","vi":"thủy tinh dễ vỡ"},{"en":"fragile ecosystem","vi":"hệ sinh thái mong manh"},{"en":"fragile recovery","vi":"sự phục hồi mong manh"}],"wordFamily":["fragility (n.)"],"synonyms":["delicate","breakable"],"antonyms":["robust","sturdy"],"tipVi":"Có thể dùng để miêu tả đồ vật dễ vỡ, cũng có thể dùng cho nền kinh tế hoặc tâm trạng yếu ớt, dễ tổn thương.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_catalog', 'en-b2-77', 'catalog', '/ˈkætəlɔːɡ/', 'B2', 'mục lục; danh mục sản phẩm; lập danh mục; hệ thống hóa', 'n.', 'cataloger (n.)', NULL, 'Catalog là cách viết phổ biến trong tiếng Anh-Mỹ; tiếng Anh-Anh thường viết là catalogue.', 'I found a sturdy desk in the furniture catalog.', NULL, 'Tôi tìm thấy một chiếc bàn làm việc chắc chắn trong danh mục đồ nội thất.', '{"wordId":"catalog","ukIpa":"/ˈkætəlɒɡ/","usIpa":"/ˈkætəlɔːɡ/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"An organised list of items, often with descriptions or pictures.","vi":"mục lục; danh mục sản phẩm"},{"pos":"v.","en":"To arrange and record items in an organised list.","vi":"lập danh mục; hệ thống hóa"}],"examples":[{"en":"I found a sturdy desk in the furniture catalog.","vi":"Tôi tìm thấy một chiếc bàn làm việc chắc chắn trong danh mục đồ nội thất.","audioKind":"ex"},{"en":"A searchable digital catalog allows researchers to locate historical documents without travelling to distant archives.","vi":"Một danh mục kỹ thuật số có thể tìm kiếm giúp các nhà nghiên cứu xác định vị trí tài liệu lịch sử mà không cần phải đến các viện lưu trữ xa xôi.","audioKind":"ex2"}],"collocations":[{"en":"online catalog","vi":"danh mục trực tuyến"},{"en":"product catalog","vi":"danh mục sản phẩm"},{"en":"library catalog","vi":"mục lục thư viện"},{"en":"catalog a collection","vi":"lập danh mục bộ sưu tập"}],"wordFamily":["cataloger (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Catalog là cách viết phổ biến trong tiếng Anh-Mỹ; tiếng Anh-Anh thường viết là catalogue.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dumb', 'en-b2-77', 'dumb', '/dʌm/', 'B2', 'ngu ngốc; ngớ ngẩn; câm lặng; không nói nên lời; cấm khẩu; mất tiếng', 'adj.', 'dumbness (n.), dumbly (adv.)', 'Đồng nghĩa: foolish, stupid · Trái nghĩa: sensible', 'Âm b bị câm; dùng để chỉ sự ngu ngốc của con người mang tính xúc phạm, còn cách dùng chỉ người khuyết tật ngôn ngữ đã lỗi thời.', 'It was dumb to leave my keys inside again.', NULL, 'Thật ngớ ngẩn khi tôi lại để quên chìa khóa ở bên trong.', '{"wordId":"dumb","ukIpa":"/dʌm/","usIpa":"/dʌm/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"not sensible or intelligent, in informal and often insulting use","vi":"ngu ngốc; ngớ ngẩn"},{"pos":"adj.","en":"temporarily unable to speak because of surprise or strong emotion","vi":"câm lặng; không nói nên lời"},{"pos":"adj.","en":"unable to speak; an outdated and potentially offensive description","vi":"cấm khẩu; mất tiếng"}],"examples":[{"en":"It was dumb to leave my keys inside again.","vi":"Thật ngớ ngẩn khi tôi lại để quên chìa khóa ở bên trong.","audioKind":"ex"},{"en":"Simplified news should improve accessibility without dumbing down complex issues or removing evidence that readers need.","vi":"Tin tức được đơn giản hóa nên cải thiện khả năng tiếp cận mà không làm lu mờ các vấn đề phức tạp hoặc cắt bỏ các bằng chứng mà độc giả cần.","audioKind":"ex2"}],"collocations":[{"en":"a dumb mistake","vi":"một sai lầm ngớ ngẩn"},{"en":"struck dumb","vi":"sợ đến chết lặng"},{"en":"dumb down","vi":"làm đơn giản hóa quá mức"}],"wordFamily":["dumbness (n.)","dumbly (adv.)"],"synonyms":["foolish","stupid"],"antonyms":["sensible"],"tipVi":"Âm b bị câm; dùng để chỉ sự ngu ngốc của con người mang tính xúc phạm, còn cách dùng chỉ người khuyết tật ngôn ngữ đã lỗi thời.","noteVi":"Dùng để mô tả sự ngu ngốc của con người có thể gây xúc phạm; cách dùng chỉ người mất khả năng nói hiện đã lỗi thời.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_77_1', 'en-b2-77', 'Cách dùng “dumb” (adj.) — ngu ngốc; ngớ ngẩn', 'a dumb mistake  ·  struck dumb  ·  dumb down', 'Âm b bị câm; dùng để chỉ sự ngu ngốc của con người mang tính xúc phạm, còn cách dùng chỉ người khuyết tật ngôn ngữ đã lỗi thời.', 'Họ từ (Word Family): dumbness (n.), dumbly (adv.) | Đồng nghĩa: foolish, stupid · Trái nghĩa: sensible', '[{"hanzi":"It was dumb to leave my keys inside again.","pinyin":"","meaning":"Thật ngớ ngẩn khi tôi lại để quên chìa khóa ở bên trong."},{"hanzi":"Simplified news should improve accessibility without dumbing down complex issues or removing evidence that readers need.","pinyin":"","meaning":"Tin tức được đơn giản hóa nên cải thiện khả năng tiếp cận mà không làm lu mờ các vấn đề phức tạp hoặc cắt bỏ các bằng chứng mà độc giả cần."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_77_2', 'en-b2-77', 'Cách dùng “likewise” (adv.) — trạng thái: tương tự; cũng vậy', 'do likewise  ·  likewise important  ·  be likewise affected', 'Đây là từ mang tính trang trọng, thường dùng để liên kết các tình huống tương đồng; cụm do likewise nghĩa là làm theo như vậy.', 'Đồng nghĩa: similarly, also', '[{"hanzi":"I folded my umbrella, and my sister did likewise.","pinyin":"","meaning":"Tôi gấp ô lại, và chị gái tôi cũng làm như vậy."},{"hanzi":"Public libraries provide free internet access; likewise, community centres help residents develop essential digital skills.","pinyin":"","meaning":"Các thư viện công cộng cung cấp quyền truy cập internet miễn phí; tương tự, các trung tâm cộng đồng cũng giúp người dân phát triển các kỹ năng số thiết yếu."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_77_3', 'en-b2-77', 'Cách dùng “blunt” (adj.) — tù; không sắc', 'a blunt knife  ·  a blunt answer  ·  blunt the impact', 'Khi dùng để miêu tả lời nói, từ này chỉ sự trực diện thậm chí mang tính xúc phạm, không nhất thiết mang nghĩa tích cực.', 'Họ từ (Word Family): bluntly (adv.), bluntness (n.) | Trái nghĩa: sharp', '[{"hanzi":"This blunt knife cannot even cut a ripe tomato.","pinyin":"","meaning":"Con dao cùn này thậm chí không thể cắt nổi một quả cà chua chín."},{"hanzi":"Although blunt feedback can feel uncomfortable, it sometimes helps students identify weaknesses in their work.","pinyin":"","meaning":"Mặc dù những lời nhận xét thẳng thắn có thể gây khó chịu, nhưng đôi khi chúng giúp học sinh nhận ra những điểm yếu trong bài làm của mình."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_77_4', 'en-b2-77', 'Cách dùng “scarcely” (adv.) — hầu như không, vừa mới', 'scarcely any  ·  scarcely enough  ·  scarcely ever', 'Bản thân từ này đã mang nghĩa phủ định nên không dùng thêm not; cấu trúc "scarcely... when" nghĩa là vừa mới... thì...', 'Họ từ (Word Family): scarce (adj.), scarcity (n.) | Đồng nghĩa: hardly, barely', '[{"hanzi":"We could scarcely hear each other above the music.","pinyin":"","meaning":"Chúng tôi hầu như không nghe thấy tiếng của nhau vì tiếng nhạc quá lớn."},{"hanzi":"Some rural communities have scarcely enough medical staff to provide basic healthcare for their growing populations.","pinyin":"","meaning":"Một số cộng đồng nông thôn hầu như không có đủ nhân viên y tế để cung cấp dịch vụ chăm sóc sức khỏe cơ bản cho dân số đang gia tăng của họ."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
