INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_77_1_1', 'en-b2-77', 'ten_b2_77_1', 'listening', 'listening', 'The kitten ran back and forth across the kitchen.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã cùng nhau nấu một bữa tối đặc biệt vào đêm giao thừa.","Tôi gấp ô lại, và chị gái tôi cũng làm như vậy.","Con mèo con chạy qua chạy lại khắp căn bếp.","Chúng tôi đặt một chiếc thảm tròn ở dưới bàn uống nước."]'::jsonb, 2, 'The kitten ran back and forth across the kitchen. → Con mèo con chạy qua chạy lại khắp căn bếp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_77_1_2', 'en-b2-77', 'ten_b2_77_1', 'listening', 'listening', 'A beam of sunlight fell across the kitchen table.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy kéo một chiếc ghế đẩu lại gần bàn bếp.","Một tia nắng rọi qua chiếc bàn trong bếp.","Mái nhà được lợp bằng các lớp ngói xếp chồng lên nhau.","Hương thơm của hoa hồng tươi tràn ngập căn bếp nhỏ."]'::jsonb, 1, 'A beam of sunlight fell across the kitchen table. → Một tia nắng rọi qua chiếc bàn trong bếp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_77_1_3', 'en-b2-77', 'ten_b2_77_1', 'listening', 'listening', 'We eagerly await the arrival of our new puppy.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Con dao cùn này thậm chí không thể cắt nổi một quả cà chua chín.","Em bé bò qua tấm thảm để tiến về phía món đồ chơi của mình.","Chúng tôi đang hồi hộp chờ đón chú cún con mới về nhà.","Tôi đã mặc một chiếc áo sơ mi bằng vải lanh vào buổi chiều trời nóng bức đó."]'::jsonb, 2, 'We eagerly await the arrival of our new puppy. → Chúng tôi đang hồi hộp chờ đón chú cún con mới về nhà.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_77_2', 'en-b2-77', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_77_2_1', 'ten_b2_77_2', 'forth', 'Residents put forth several practical proposals to improve public transport without increasing costs significantly.', 'Residents put forth several practical proposals to improve public transport without increasing costs significantly.', '/fɔːrθ/', 'Cư dân đã đưa ra một số đề xuất thiết thực nhằm cải thiện giao thông công cộng mà không làm tăng đáng kể chi phí.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_77_2_2', 'ten_b2_77_2', 'beam', 'Engineers used steel beams to strengthen the old bridge and improve safety for local residents.', 'Engineers used steel beams to strengthen the old bridge and improve safety for local residents.', '/biːm/', 'Các kỹ sư đã dùng dầm thép để gia cố cây cầu cũ và cải thiện an toàn cho người dân địa phương.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_77_2_3', 'ten_b2_77_2', 'await', 'Many graduates await job offers while developing additional skills through voluntary work and online courses.', 'Many graduates await job offers while developing additional skills through voluntary work and online courses.', '/əˈweɪt/', 'Nhiều sinh viên tốt nghiệp đang chờ đợi các lời mời làm việc trong khi trau dồi thêm kỹ năng qua các công việc tình nguyện và khóa học trực tuyến.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_77_2_4', 'ten_b2_77_2', 'making', 'Involving residents in the making of local policy can increase public trust and improve community outcomes.', 'Involving residents in the making of local policy can increase public trust and improve community outcomes.', '/ˈmeɪkɪŋ/', 'Việc cho cư dân tham gia vào quá trình hoạch định chính sách địa phương có thể tăng cường niềm tin công chúng và cải thiện kết quả phát triển cộng đồng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_77_2_5', 'ten_b2_77_2', 'blunt', 'Although blunt feedback can feel uncomfortable, it sometimes helps students identify weaknesses in their work.', 'Although blunt feedback can feel uncomfortable, it sometimes helps students identify weaknesses in their work.', '/blʌnt/', 'Mặc dù những lời nhận xét thẳng thắn có thể gây khó chịu, nhưng đôi khi chúng giúp học sinh nhận ra những điểm yếu trong bài làm của mình.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_77_2_6', 'ten_b2_77_2', 'linen', 'Hotels can reduce water consumption by encouraging guests to reuse towels and change bed linen less frequently.', 'Hotels can reduce water consumption by encouraging guests to reuse towels and change bed linen less frequently.', '/ˈlɪnɪn/', 'Các khách sạn có thể giảm lượng nước tiêu thụ bằng cách khuyến khích khách tái sử dụng khăn tắm và thay ga trải giường ít thường xuyên hơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_77_2_1', 'en-b2-77', 'ten_b2_77_2', 'listening', 'listening', 'Residents put forth several practical proposals to improve public transport without increasing costs significantly.', NULL, 'Trong câu vừa nghe, từ “forth” mang nghĩa nào sau đây?', '["niềm vui sướng; sự thích thú","mẫu; mẫu vật; vật mẫu","về phía trước; ra ngoài; lộ ra","người nghiện công việc; người cuồng công việc"]'::jsonb, 2, '“forth” (/fɔːrθ/): về phía trước; ra ngoài; lộ ra. Câu đầy đủ: Residents put forth several practical proposals to improve public transport without increasing costs significantly.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_77_2_2', 'en-b2-77', 'ten_b2_77_2', 'listening', 'listening', 'Engineers used steel beams to strengthen the old bridge and improve safety for local residents.', NULL, 'Trong câu vừa nghe, từ “beam” mang nghĩa nào sau đây?', '["xô đẩy; nhét vội","đường kính","chùm sáng; tia sáng","sự cân nhắc; sự suy xét"]'::jsonb, 2, '“beam” (/biːm/): chùm sáng; tia sáng. Câu đầy đủ: Engineers used steel beams to strengthen the old bridge and improve safety for local residents.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
