INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_77_1', 'en-b2-77', NULL, 'comprehensive_test', 'listening', 'forth', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["phân biệt; nhận diện","về phía trước; ra ngoài; lộ ra","mỹ phẩm; đồ trang điểm","được kích hoạt; được khởi động"]'::jsonb, 1, 'forth (/fɔːrθ/) → về phía trước; ra ngoài; lộ ra', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_77_2', 'en-b2-77', NULL, 'comprehensive_test', 'listening', 'A beam of sunlight fell across the kitchen table.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một tia nắng rọi qua chiếc bàn trong bếp.","Con mèo con chạy qua chạy lại khắp căn bếp.","Cô ấy kéo một chiếc ghế đẩu lại gần bàn bếp.","Chúng tôi đặt một chiếc thảm tròn ở dưới bàn uống nước."]'::jsonb, 0, 'A beam of sunlight fell across the kitchen table. → Một tia nắng rọi qua chiếc bàn trong bếp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_77_3', 'en-b2-77', NULL, 'comprehensive_test', 'listening', 'await', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chờ đợi; ngóng chờ","động từ: tiếp tục tiến hành; tiếp theo","sự tiêu hóa; khả năng tiêu hóa","tán dương; ca ngợi"]'::jsonb, 0, 'await (/əˈweɪt/) → chờ đợi; ngóng chờ; đang chờ đón ai; sắp sửa đến với ai', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_77_4', 'en-b2-77', NULL, 'comprehensive_test', 'listening', 'We spent the afternoon learning the basics of bread making.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi gấp ô lại, và chị gái tôi cũng làm như vậy.","Chúng tôi đã dành cả buổi chiều để học những bước cơ bản trong việc làm bánh mì.","Tôi tìm thấy một chiếc bàn làm việc chắc chắn trong danh mục đồ nội thất.","Một tia nắng rọi qua chiếc bàn trong bếp."]'::jsonb, 1, 'We spent the afternoon learning the basics of bread making. → Chúng tôi đã dành cả buổi chiều để học những bước cơ bản trong việc làm bánh mì.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_77_5', 'en-b2-77', NULL, 'comprehensive_test', 'listening', 'blunt', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["hạt hạnh nhân; cây hạnh nhân","loài người","đất liền; đại lục","tù; không sắc"]'::jsonb, 3, 'blunt (/blʌnt/) → tù; không sắc; thẳng thắn; bộc tuệch; làm cùn; làm giảm bớt; làm suy yếu', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_77_6', 'en-b2-77', NULL, 'comprehensive_test', 'listening', 'I wore a linen shirt on the hot afternoon.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Mái nhà được lợp bằng các lớp ngói xếp chồng lên nhau.","Con dao cùn này thậm chí không thể cắt nổi một quả cà chua chín.","Khách sạn đã gửi thông báo xác nhận đặt phòng của chúng tôi vào sáng nay.","Tôi đã mặc một chiếc áo sơ mi bằng vải lanh vào buổi chiều trời nóng bức đó."]'::jsonb, 3, 'I wore a linen shirt on the hot afternoon. → Tôi đã mặc một chiếc áo sơ mi bằng vải lanh vào buổi chiều trời nóng bức đó.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_77_7', 'en-b2-77', NULL, 'comprehensive_test', 'listening', 'conceal', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự bảo tồn; sự giữ gìn; sự bảo vệ","che giấu; giấu kín không để nhìn thấy","pháo đài; đồn lũy; thành trì","chuyến đi bộ đường dài gian khổ"]'::jsonb, 1, 'conceal (/kənˈsiːl/) → che giấu; giấu kín không để nhìn thấy; che đậy sự thật hoặc cảm xúc', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_77_8', 'en-b2-77', NULL, 'comprehensive_test', 'listening', 'The dog splashed water all over my trousers.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Em bé bò qua tấm thảm để tiến về phía món đồ chơi của mình.","Tôi đã mặc một chiếc áo sơ mi bằng vải lanh vào buổi chiều trời nóng bức đó.","Con chó làm nước bắn tung tóe khắp chiếc quần của tôi.","Chúng tôi đã dành cả buổi chiều để học những bước cơ bản trong việc làm bánh mì."]'::jsonb, 2, 'The dog splashed water all over my trousers. → Con chó làm nước bắn tung tóe khắp chiếc quần của tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_77_9', 'en-b2-77', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Having an edge or point that does not cut easily.”?', '["fragile","dumb","circular","blunt"]'::jsonb, 3, 'blunt (/blʌnt/) → tù; không sắc', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_77_10', 'en-b2-77', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “strong cloth made from fibres of the flax plant”?', '["await","fragrance","linen","forth"]'::jsonb, 2, 'linen (/ˈlɪnɪn/) → vải lanh', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_77_11', 'en-b2-77', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To keep something from being seen”?', '["baggy","fragrance","conceal","shove"]'::jsonb, 2, 'conceal (/kənˈsiːl/) → che giấu; giấu kín không để nhìn thấy', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_77_12', 'en-b2-77', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To make liquid scatter in drops or hit something.”?', '["likewise","splash","crawl","forth"]'::jsonb, 1, 'splash (/splæʃ/) → làm bắn tóe chất lỏng; tạt nước', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_77_13', 'en-b2-77', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Loose and hanging away from the body.”?', '["catalog","scarcely","overlapping","baggy"]'::jsonb, 3, 'baggy (/ˈbæɡi/) → rộng thùng thình; rộng và lùng bùng', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
