INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_77_18', 'en-b2-77', NULL, 'comprehensive_test', 'reading', NULL, 'Residents put forth several practical proposals to improve public transport without increasing costs significantly.', 'Dựa vào câu trên, từ “forth” có nghĩa phù hợp nhất là gì?', '["về phía trước; ra ngoài; lộ ra","đâm thủng; chọc thủng bằng vật nhọn","giải trí; mang tính thư giãn","nhúng; chấm"]'::jsonb, 0, 'forth: về phía trước; ra ngoài; lộ ra. Dịch cả câu: Cư dân đã đưa ra một số đề xuất thiết thực nhằm cải thiện giao thông công cộng mà không làm tăng đáng kể chi phí.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_77_19', 'en-b2-77', NULL, 'comprehensive_test', 'reading', NULL, 'Engineers used steel beams to strengthen the old bridge and improve safety for local residents.', 'Dựa vào câu trên, từ “beam” có nghĩa phù hợp nhất là gì?', '["có hệ thống; có phương pháp","sự từ biệt; lời chia tay","rượu mạnh","chùm sáng; tia sáng"]'::jsonb, 3, 'beam: chùm sáng; tia sáng; xà nhà; dầm ngang; cười rạng rỡ; mỉm cười tươi. Dịch cả câu: Các kỹ sư đã dùng dầm thép để gia cố cây cầu cũ và cải thiện an toàn cho người dân địa phương.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_77_20', 'en-b2-77', NULL, 'comprehensive_test', 'reading', NULL, 'Many graduates await job offers while developing additional skills through voluntary work and online courses.', 'Dựa vào câu trên, từ “await” có nghĩa phù hợp nhất là gì?', '["thư mục tham khảo; danh mục tài liệu tham khảo","rõ ràng; rành mạch","nhân viên phục vụ (trên tàu, máy bay hoặc tại sự kiện); tiếp viên","chờ đợi; ngóng chờ"]'::jsonb, 3, 'await: chờ đợi; ngóng chờ; đang chờ đón ai; sắp sửa đến với ai. Dịch cả câu: Nhiều sinh viên tốt nghiệp đang chờ đợi các lời mời làm việc trong khi trau dồi thêm kỹ năng qua các công việc tình nguyện và khóa học trực tuyến.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_77_21', 'en-b2-77', NULL, 'comprehensive_test', 'reading', NULL, 'Involving residents in the making of local policy can increase public trust and improve community outcomes.', 'Dựa vào câu trên, từ “making” có nghĩa phù hợp nhất là gì?', '["sự tuyệt vọng","nô lệ; người bị bắt làm nô lệ","tương tác; giao tiếp","sự chế tạo; quá trình sản xuất"]'::jsonb, 3, 'making: sự chế tạo; quá trình sản xuất; yếu tố thúc đẩy thành công; phẩm chất cần thiết; tiềm năng. Dịch cả câu: Việc cho cư dân tham gia vào quá trình hoạch định chính sách địa phương có thể tăng cường niềm tin công chúng và cải thiện kết quả phát triển cộng đồng.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_77_22', 'en-b2-77', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “dễ vỡ; dễ hỏng”', '["fragile","identical","intersection","brake"]'::jsonb, 0, 'dễ vỡ; dễ hỏng → fragile (/ˈfrædʒəl/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_77_23', 'en-b2-77', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “mục lục; danh mục sản phẩm”', '["rust","catalog","dread","carrier"]'::jsonb, 1, 'mục lục; danh mục sản phẩm → catalog (/ˈkætəlɔːɡ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_77_24', 'en-b2-77', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ngu ngốc; ngớ ngẩn”', '["despair","foul","dumb","confession"]'::jsonb, 2, 'ngu ngốc; ngớ ngẩn → dumb (/dʌm/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-78', 'en', 'Bài 78: Đời sống hằng ngày (5) - CEFR B2', 'CEFR B2', 'B2 · Đời sống', '27 từ vựng Tiếng Anh CEFR B2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4078, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_boast', 'en-b2-78', 'boast', '/boʊst/', 'B2', 'khoác lác; khoe khoang; tự cao; sở hữu (điểm đáng tự hào); lời khoác lác; lời tự cao', 'v.', 'boastful (adj.), boastfully (adv.), boastfulness (n.)', 'Đồng nghĩa: brag', 'Khoe khoang dùng boast about; khi biểu thị sự sở hữu thì đi thẳng với tân ngữ.', 'He always boasts about how fast he can run.', NULL, 'Anh ấy luôn khoác lác về việc mình chạy nhanh đến mức nào.', '{"wordId":"boast","ukIpa":"/bəʊst/","usIpa":"/boʊst/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To speak too proudly about your achievements or possessions.","vi":"khoác lác; khoe khoang; tự cao"},{"pos":"v.","en":"To have a feature that deserves admiration.","vi":"sở hữu (điểm đáng tự hào)"},{"pos":"n.","en":"A statement expressing excessive pride in something about yourself.","vi":"lời khoác lác; lời tự cao"}],"examples":[{"en":"He always boasts about how fast he can run.","vi":"Anh ấy luôn khoác lác về việc mình chạy nhanh đến mức nào.","audioKind":"ex"},{"en":"The city boasts an extensive public transport network, making it an attractive destination for sustainable tourism.","vi":"Thành phố này sở hữu một mạng lưới giao thông công cộng rộng khắp, khiến nơi đây trở thành một điểm đến hấp dẫn cho du lịch bền vững.","audioKind":"ex2"}],"collocations":[{"en":"boast about achievements","vi":"khoe khoang thành tích"},{"en":"boast that","vi":"khoác lác rằng"},{"en":"an empty boast","vi":"lời khoác lác rỗng tuếch"}],"wordFamily":["boastful (adj.)","boastfully (adv.)","boastfulness (n.)"],"synonyms":["brag"],"antonyms":[],"tipVi":"Khoe khoang dùng boast about; khi biểu thị sự sở hữu thì đi thẳng với tân ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sniff', 'en-b2-78', 'sniff', '/snɪf/', 'B2', 'hít; ngửi; khịt mũi; cái hít mũi; tiếng khịt mũi; tỏ ý coi thường; phớt lờ', 'v.', 'sniffer (n.)', NULL, 'Cụm "sniff at" có thể biểu thị thái độ xem thường; "sniff out" có nghĩa là đánh hơi hoặc phát hiện ra.', 'The puppy sniffed my shoes before letting me inside.', NULL, 'Chú chó nhỏ ngửi giày của tôi trước khi cho phép tôi bước vào nhà.', '{"wordId":"sniff","ukIpa":"/snɪf/","usIpa":"/snɪf/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to draw air through the nose to smell or clear it","vi":"hít; ngửi; khịt mũi"},{"pos":"n.","en":"an act or sound of drawing air through the nose","vi":"cái hít mũi; tiếng khịt mũi"},{"pos":"v.","en":"to show that something seems unworthy of consideration","vi":"tỏ ý coi thường; phớt lờ"}],"examples":[{"en":"The puppy sniffed my shoes before letting me inside.","vi":"Chú chó nhỏ ngửi giày của tôi trước khi cho phép tôi bước vào nhà.","audioKind":"ex"},{"en":"Trained dogs can sniff out certain substances, making them valuable partners in wildlife conservation projects.","vi":"Những chú chó được huấn luyện có thể đánh hơi ra các chất nhất định, biến chúng thành những người bạn đồng hành quý giá trong các dự án bảo tồn động vật hoang dã.","audioKind":"ex2"}],"collocations":[{"en":"sniff the air","vi":"hít không khí"},{"en":"sniff out","vi":"đánh hơi thấy; tìm ra"},{"en":"sniff at","vi":"coi thường; phớt lờ"}],"wordFamily":["sniffer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm \"sniff at\" có thể biểu thị thái độ xem thường; \"sniff out\" có nghĩa là đánh hơi hoặc phát hiện ra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_furnish', 'en-b2-78', 'furnish', '/ˈfɝː.nɪʃ/', 'B2', 'trang bị nội thất; bày biện đồ đạc (cho phòng, nhà); cung cấp (thông tin, tài liệu cần thiết)', 'v.', 'furniture (n.), furnishings (n.), furnished (adj.)', 'Đồng nghĩa: equip, supply', 'Cấu trúc "furnish A with B" nghĩa là cung cấp cho A cái gì đó (B); nghĩa cung cấp này mang sắc thái khá trang trọng.', 'We furnished our flat with second-hand tables and chairs.', NULL, 'Chúng tôi đã trang hoàng căn hộ của mình bằng bàn ghế mua lại từ cửa hàng đồ cũ.', '{"wordId":"furnish","ukIpa":"/ˈfɜː.nɪʃ/","usIpa":"/ˈfɝː.nɪʃ/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"put furniture into a room or building","vi":"trang bị nội thất; bày biện đồ đạc (cho phòng, nhà)"},{"pos":"v.","en":"provide someone with something needed, especially information","vi":"cung cấp (thông tin, tài liệu cần thiết)"}],"examples":[{"en":"We furnished our flat with second-hand tables and chairs.","vi":"Chúng tôi đã trang hoàng căn hộ của mình bằng bàn ghế mua lại từ cửa hàng đồ cũ.","audioKind":"ex"},{"en":"Applicants must furnish the university with evidence of their qualifications before their applications can be assessed.","vi":"Các ứng viên phải cung cấp cho trường đại học các minh chứng về bằng cấp của họ trước khi hồ sơ được xét duyệt.","audioKind":"ex2"}],"collocations":[{"en":"furnish a flat","vi":"sắm sửa nội thất cho căn hộ"},{"en":"furnish someone with evidence","vi":"cung cấp chứng cứ cho ai đó"},{"en":"fully furnished","vi":"đầy đủ tiện nghi nội thất"}],"wordFamily":["furniture (n.)","furnishings (n.)","furnished (adj.)"],"synonyms":["equip","supply"],"antonyms":[],"tipVi":"Cấu trúc \"furnish A with B\" nghĩa là cung cấp cho A cái gì đó (B); nghĩa cung cấp này mang sắc thái khá trang trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_glitter', 'en-b2-78', 'glitter', '/ˈɡlɪtər/', 'B2', 'lấp lánh; tỏa sáng; kim tuyến (các mảnh nhỏ lấp lánh dùng để trang trí); vẻ lấp lánh; vẻ hào nhoáng', 'v.', 'glittering (adj.), glittery (adj.)', 'Đồng nghĩa: sparkle, twinkle', 'Dùng như động từ để chỉ sự lấp lánh; khi mang nghĩa là kim tuyến trang trí thì thường không đếm được.', 'Tiny drops of water glitter on the leaves outside.', NULL, 'Những giọt nước nhỏ lấp lánh trên đám lá ngoài kia.', '{"wordId":"glitter","ukIpa":"/ˈɡlɪtə/","usIpa":"/ˈɡlɪtər/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To shine with many small flashes of reflected light.","vi":"lấp lánh; tỏa sáng"},{"pos":"n.","en":"Tiny shiny pieces used to decorate things.","vi":"kim tuyến (các mảnh nhỏ lấp lánh dùng để trang trí)"},{"pos":"n.","en":"Bright sparkling light, or an appearance of glamour and excitement.","vi":"vẻ lấp lánh; vẻ hào nhoáng"}],"examples":[{"en":"Tiny drops of water glitter on the leaves outside.","vi":"Những giọt nước nhỏ lấp lánh trên đám lá ngoài kia.","audioKind":"ex"},{"en":"Although city skylines glitter at night, excessive artificial lighting can disrupt wildlife and waste energy.","vi":"Mặc dù cảnh quan thành phố lấp lánh về đêm, việc chiếu sáng nhân tạo quá mức có thể làm xáo trộn đời sống động vật hoang dã và lãng phí năng lượng.","audioKind":"ex2"}],"collocations":[{"en":"glitter in the sunlight","vi":"lấp lánh dưới ánh nắng"},{"en":"gold glitter","vi":"kim tuyến vàng"},{"en":"the glitter of fame","vi":"hào quang của danh vọng"}],"wordFamily":["glittering (adj.)","glittery (adj.)"],"synonyms":["sparkle","twinkle"],"antonyms":[],"tipVi":"Dùng như động từ để chỉ sự lấp lánh; khi mang nghĩa là kim tuyến trang trí thì thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hose', 'en-b2-78', 'hose', '/hoʊz/', 'B2', 'ống mềm (dùng để dẫn nước hoặc chất lỏng khác); xịt rửa; tưới nước bằng vòi mềm', 'n.', NULL, NULL, 'Hose chỉ ống mềm có thể uốn cong; pipe thường chỉ đường ống cứng.', 'I used the hose to wash my muddy boots.', NULL, 'Tôi dùng vòi nước để rửa sạch đôi bốt dính đầy bùn của mình.', '{"wordId":"hose","ukIpa":"/həʊz/","usIpa":"/hoʊz/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A flexible tube used to carry water or other liquids","vi":"ống mềm (dùng để dẫn nước hoặc chất lỏng khác)"},{"pos":"v.","en":"To spray or wash something with water from a hose","vi":"xịt rửa; tưới nước bằng vòi mềm"}],"examples":[{"en":"I used the hose to wash my muddy boots.","vi":"Tôi dùng vòi nước để rửa sạch đôi bốt dính đầy bùn của mình.","audioKind":"ex"},{"en":"During periods of drought, restricting garden hose use can help households conserve valuable water supplies.","vi":"Trong thời kỳ hạn hán, việc hạn chế dùng vòi nước làm vườn có thể giúp các hộ gia đình tiết kiệm nguồn nước quý giá.","audioKind":"ex2"}],"collocations":[{"en":"garden hose","vi":"vòi nước làm vườn"},{"en":"fire hose","vi":"vòi chữa cháy"},{"en":"hose something down","vi":"xịt rửa sạch cái gì bằng vòi nước"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Hose chỉ ống mềm có thể uốn cong; pipe thường chỉ đường ống cứng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cling', 'en-b2-78', 'cling', '/klɪŋ/', 'B2', 'bám chặt; ôm chặt; bám lấy; dính chặt vào bề mặt; bám víu; cố thủ (niềm tin, hy vọng, tài sản)', 'v.', NULL, NULL, 'Dạng quá khứ và phân từ hai đều là clung; thường đi kèm với giới từ to.', 'The little boy clung to his father''s arm.', NULL, 'Cậu bé ôm chặt lấy cánh tay của bố.', '{"wordId":"cling","ukIpa":"/klɪŋ/","usIpa":"/klɪŋ/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To hold someone or something tightly.","vi":"bám chặt; ôm chặt"},{"pos":"v.","en":"To stick closely to a surface or body.","vi":"bám lấy; dính chặt vào bề mặt"},{"pos":"v.","en":"To refuse to give up a belief, hope, or possession.","vi":"bám víu; cố thủ (niềm tin, hy vọng, tài sản)"}],"examples":[{"en":"The little boy clung to his father''s arm.","vi":"Cậu bé ôm chặt lấy cánh tay của bố.","audioKind":"ex"},{"en":"Some organisations cling to outdated practices even when new approaches could improve efficiency and employee satisfaction.","vi":"Một số tổ chức vẫn bám lấy các phương pháp lỗi thời ngay cả khi các cách tiếp cận mới có thể cải thiện hiệu suất và sự hài lòng của nhân viên.","audioKind":"ex2"}],"collocations":[{"en":"cling to someone","vi":"bám lấy ai đó"},{"en":"cling to power","vi":"bám giữ quyền lực"},{"en":"cling to the hope that","vi":"bám víu vào hy vọng rằng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ và phân từ hai đều là clung; thường đi kèm với giới từ to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_counter', 'en-b2-78', 'counter', '/ˈkaʊntər/', 'B2', 'quầy (thanh toán, phục vụ); mặt bàn (nhà bếp); phản bác; chống lại; trung hòa; ngược lại; đối lập', 'n.', 'counteraction (n.), counterargument (n.)', NULL, 'Động từ có thể đi trực tiếp với tân ngữ; cụm run counter to nghĩa là đi ngược lại với cái gì.', 'I left my shopping bag on the kitchen counter.', NULL, 'Tôi để túi mua sắm trên mặt bàn bếp.', '{"wordId":"counter","ukIpa":"/ˈkaʊntə/","usIpa":"/ˈkaʊntər/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A raised flat surface for serving customers or preparing food","vi":"quầy (thanh toán, phục vụ); mặt bàn (nhà bếp)"},{"pos":"v.","en":"Act or speak against something to reduce its effect","vi":"phản bác; chống lại; trung hòa"},{"pos":"adv.","en":"In a direction opposed to something","vi":"ngược lại; đối lập"}],"examples":[{"en":"I left my shopping bag on the kitchen counter.","vi":"Tôi để túi mua sắm trên mặt bàn bếp.","audioKind":"ex"},{"en":"Schools can counter the spread of misinformation by teaching students to evaluate online sources critically.","vi":"Nhà trường có thể ngăn chặn sự lan truyền của thông tin sai lệch bằng cách dạy học sinh cách đánh giá các nguồn tin trực tuyến một cách phản biện.","audioKind":"ex2"}],"collocations":[{"en":"kitchen counter","vi":"mặt bàn bếp"},{"en":"over the counter","vi":"bán không cần đơn (thuốc)"},{"en":"counter an argument","vi":"phản bác một luận điểm"},{"en":"run counter to","vi":"đi ngược lại với"}],"wordFamily":["counteraction (n.)","counterargument (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ có thể đi trực tiếp với tân ngữ; cụm run counter to nghĩa là đi ngược lại với cái gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_jerk', 'en-b2-78', 'jerk', '/dʒɝːk/', 'B2', 'giật mạnh, chuyển động đột ngột; cú giật mạnh, cú xóc; kẻ ngốc nghếch, kẻ đáng ghét (từ thông tục mang ý xúc phạm)', 'v.', 'jerky (adj.), jerkily (adv.)', 'Đồng nghĩa: jolt, yank', 'Hành động mang tính chất đột ngột và chớp nhoáng; việc gọi ai đó là "a jerk" mang sắc thái bất lịch sự.', 'The bus jerked forward, making my shopping bag tumble.', NULL, 'Chiếc xe buýt đột ngột chồm về phía trước khiến chiếc túi mua sắm của tôi bị lật nhào.', '{"wordId":"jerk","ukIpa":"/dʒɜːk/","usIpa":"/dʒɝːk/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to move or pull with a sudden sharp motion","vi":"giật mạnh, chuyển động đột ngột"},{"pos":"n.","en":"a sudden sharp movement","vi":"cú giật mạnh, cú xóc"},{"pos":"n.","en":"an informal, insulting word for an unpleasant or foolish person","vi":"kẻ ngốc nghếch, kẻ đáng ghét (từ thông tục mang ý xúc phạm)"}],"examples":[{"en":"The bus jerked forward, making my shopping bag tumble.","vi":"Chiếc xe buýt đột ngột chồm về phía trước khiến chiếc túi mua sắm của tôi bị lật nhào.","audioKind":"ex"},{"en":"Poorly maintained trains may jerk unexpectedly, increasing the risk of falls among passengers who are standing.","vi":"Những đoàn tàu được bảo dưỡng kém có thể giật cục bất ngờ, làm tăng nguy cơ té ngã cho những hành khách đang đứng.","audioKind":"ex2"}],"collocations":[{"en":"jerk forward","vi":"chồm về phía trước"},{"en":"jerk away","vi":"giật lùi ra, rụt lại"},{"en":"a sudden jerk","vi":"một cú giật đột ngột"}],"wordFamily":["jerky (adj.)","jerkily (adv.)"],"synonyms":["jolt","yank"],"antonyms":[],"tipVi":"Hành động mang tính chất đột ngột và chớp nhoáng; việc gọi ai đó là \"a jerk\" mang sắc thái bất lịch sự.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sideways', 'en-b2-78', 'sideways', '/ˈsaɪdweɪz/', 'B2', 'theo hướng sang bên, xoay ngang người; hướng sang một bên, nằm ngang', 'adv.', 'side (n.)', 'Đồng nghĩa: laterally', 'Có thể đóng vai trò là cả phó từ lẫn tính từ; tuyệt đối không thêm đuôi "-ly".', 'We turned sideways to squeeze through the narrow doorway.', NULL, 'Chúng tôi xoay người sang một bên để luồn qua khung cửa hẹp.', '{"wordId":"sideways","ukIpa":"/ˈsaɪdweɪz/","usIpa":"/ˈsaɪdweɪz/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"with one side facing forward, or towards one side","vi":"theo hướng sang bên, xoay ngang người"},{"pos":"adj.","en":"directed towards one side rather than forwards","vi":"hướng sang một bên, nằm ngang"}],"examples":[{"en":"We turned sideways to squeeze through the narrow doorway.","vi":"Chúng tôi xoay người sang một bên để luồn qua khung cửa hẹp.","audioKind":"ex"},{"en":"A sideways move within a company can broaden employees'' experience without immediately increasing their responsibilities.","vi":"Một đợt điều chuyển công tác ngang cấp trong công ty có thể mở rộng kinh nghiệm cho nhân viên mà chưa làm tăng ngay trách nhiệm của họ.","audioKind":"ex2"}],"collocations":[{"en":"move sideways","vi":"di chuyển sang bên"},{"en":"turn sideways","vi":"quay ngang người"},{"en":"a sideways glance","vi":"cái liếc nhìn sang bên"},{"en":"a sideways move","vi":"sự thăng chức/chuyển vị trí ngang cấp"}],"wordFamily":["side (n.)"],"synonyms":["laterally"],"antonyms":[],"tipVi":"Có thể đóng vai trò là cả phó từ lẫn tính từ; tuyệt đối không thêm đuôi \"-ly\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_slot', 'en-b2-78', 'slot', '/slɑːt/', 'B2', 'khe hở; lỗ đút (tiền, thư); khung giờ; khoảng thời gian (trong lịch trình); lắp vào; nhét vào khe hẹp', 'n.', NULL, NULL, 'slot đóng vai trò động từ thường đi kèm với giới từ into; không mang nghĩa là theo dõi.', 'She pushed a coin into the narrow slot.', NULL, 'Cô ấy nhét một đồng xu vào khe hẹp.', '{"wordId":"slot","ukIpa":"/slɒt/","usIpa":"/slɑːt/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A narrow opening into which something can be inserted.","vi":"khe hở; lỗ đút (tiền, thư)"},{"pos":"n.","en":"An available time or position in a schedule or system.","vi":"khung giờ; khoảng thời gian (trong lịch trình)"},{"pos":"v.","en":"To fit something into a narrow opening or available position.","vi":"lắp vào; nhét vào khe hẹp"}],"examples":[{"en":"She pushed a coin into the narrow slot.","vi":"Cô ấy nhét một đồng xu vào khe hẹp.","audioKind":"ex"},{"en":"Offering evening appointment slots could help working adults access essential healthcare services more easily.","vi":"Việc cung cấp các khung giờ hẹn buổi tối có thể giúp người đi làm tiếp cận các dịch vụ y tế thiết yếu dễ dàng hơn.","audioKind":"ex2"}],"collocations":[{"en":"coin slot","vi":"khe đút xu"},{"en":"time slot","vi":"khung giờ"},{"en":"slot something into place","vi":"lắp vật gì vào đúng vị trí"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"slot đóng vai trò động từ thường đi kèm với giới từ into; không mang nghĩa là theo dõi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scold', 'en-b2-78', 'scold', '/skoʊld/', 'B2', 'mắng mỏ; la rầy; khiển trách', 'v.', 'scolding (n.)', 'Đồng nghĩa: reprimand, rebuke · Trái nghĩa: praise', 'Dùng cấu trúc scold someone for doing để diễn tả hành động la mắng ai vì một việc cụ thể.', 'Dad scolded me for leaving the freezer door open.', NULL, 'Bố mắng tôi vì tội để mở cửa tủ lạnh.', '{"wordId":"scold","ukIpa":"/skəʊld/","usIpa":"/skoʊld/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To speak angrily to someone because they did something wrong.","vi":"mắng mỏ; la rầy; khiển trách"}],"examples":[{"en":"Dad scolded me for leaving the freezer door open.","vi":"Bố mắng tôi vì tội để mở cửa tủ lạnh.","audioKind":"ex"},{"en":"Teachers who frequently scold pupils may discourage them from asking questions and participating in classroom discussions.","vi":"Những giáo viên hay la rầy học sinh có thể làm các em nản lòng, không dám đặt câu hỏi hay tham gia thảo luận trên lớp.","audioKind":"ex2"}],"collocations":[{"en":"scold someone for something","vi":"mắng ai vì điều gì"},{"en":"scold someone for doing something","vi":"la rầy ai vì đã làm gì"}],"wordFamily":["scolding (n.)"],"synonyms":["reprimand","rebuke"],"antonyms":["praise"],"tipVi":"Dùng cấu trúc scold someone for doing để diễn tả hành động la mắng ai vì một việc cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_freshen', 'en-b2-78', 'freshen', '/ˈfreʃən/', 'B2', 'làm cho tươi mới; làm trong lành; tự chải chuốt; làm cho sảng khoái; mạnh lên (thường dùng cho gió)', 'v.', 'fresh (adj.), freshness (n.), freshly (adv.)', 'Đồng nghĩa: refresh', 'freshen up thường chỉ việc rửa mặt, chỉnh trang lại trang phục; khi gió làm chủ ngữ, nó chỉ gió thổi mạnh hơn.', 'Let''s open a window to freshen the room.', NULL, 'Hãy mở cửa sổ để làm trong lành không khí trong phòng nào.', '{"wordId":"freshen","ukIpa":"/ˈfreʃən/","usIpa":"/ˈfreʃən/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to make something cleaner, fresher, or more pleasant","vi":"làm cho tươi mới; làm trong lành"},{"pos":"v.","en":"to wash or tidy yourself to feel more refreshed","vi":"tự chải chuốt; làm cho sảng khoái"},{"pos":"v.","en":"to become stronger, especially when describing wind","vi":"mạnh lên (thường dùng cho gió)"}],"examples":[{"en":"Let''s open a window to freshen the room.","vi":"Hãy mở cửa sổ để làm trong lành không khí trong phòng nào.","audioKind":"ex"},{"en":"Planting trees can freshen urban spaces while providing shade and improving the overall appearance of neighbourhoods.","vi":"Việc trồng cây xanh có thể làm cho không gian đô thị tươi mới hơn, đồng thời tạo bóng râm và cải thiện diện mạo tổng thể của các khu dân cư.","audioKind":"ex2"}],"collocations":[{"en":"freshen up","vi":"làm vệ sinh cá nhân; tút tát lại vẻ ngoài"},{"en":"freshen the air","vi":"làm trong lành không khí"},{"en":"freshen your breath","vi":"làm thơm miệng"}],"wordFamily":["fresh (adj.)","freshness (n.)","freshly (adv.)"],"synonyms":["refresh"],"antonyms":[],"tipVi":"freshen up thường chỉ việc rửa mặt, chỉnh trang lại trang phục; khi gió làm chủ ngữ, nó chỉ gió thổi mạnh hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bullet', 'en-b2-78', 'bullet', '/ˈbʊlɪt/', 'B2', 'viên đạn; đầu đạn; dấu chấm tròn liệt kê; ký hiệu đầu dòng', 'n.', NULL, NULL, 'bullet chỉ viên đạn; bullet point chỉ các điểm liệt kê trong danh sách.', 'The museum displays a bullet beside an old rifle.', NULL, 'Viện bảo tàng trưng bày một viên đạn nằm bên cạnh khẩu súng trường cũ.', '{"wordId":"bullet","ukIpa":"/ˈbʊlɪt/","usIpa":"/ˈbʊlɪt/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A small metal projectile fired from a gun.","vi":"viên đạn; đầu đạn"},{"pos":"n.","en":"A symbol introducing an item in a list.","vi":"dấu chấm tròn liệt kê; ký hiệu đầu dòng"}],"examples":[{"en":"The museum displays a bullet beside an old rifle.","vi":"Viện bảo tàng trưng bày một viên đạn nằm bên cạnh khẩu súng trường cũ.","audioKind":"ex"},{"en":"Using bullet points in presentations can help audiences identify key information and follow complex arguments.","vi":"Việc sử dụng các dấu chấm tròn trong bài thuyết trình giúp người xem dễ dàng nhận diện thông tin chính và theo dõi các lập luận phức tạp.","audioKind":"ex2"}],"collocations":[{"en":"fire a bullet","vi":"bắn một phát đạn"},{"en":"bullet wound","vi":"vết thương do đạn bắn"},{"en":"bullet points","vi":"các gạch đầu dòng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"bullet chỉ viên đạn; bullet point chỉ các điểm liệt kê trong danh sách.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dim', 'en-b2-78', 'dim', '/dɪm/', 'B2', 'mờ ảo; thiếu ánh sáng; mờ nhạt; không rõ ràng; làm cho mờ đi; làm giảm độ sáng', 'adj.', 'dimly (adv.), dimness (n.)', 'Đồng nghĩa: faint, gloomy · Trái nghĩa: bright', 'Biến đổi gấp đôi chữ m: dimmer, dimmest, dimmed.', 'We ate dinner under a dim kitchen light.', NULL, 'Chúng tôi ăn tối dưới ánh đèn bếp mờ ảo.', '{"wordId":"dim","ukIpa":"/dɪm/","usIpa":"/dɪm/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"not bright or providing little light","vi":"mờ ảo; thiếu ánh sáng"},{"pos":"adj.","en":"not clearly remembered, seen, or understood","vi":"mờ nhạt; không rõ ràng"},{"pos":"v.","en":"to become less bright or make something less bright","vi":"làm cho mờ đi; làm giảm độ sáng"}],"examples":[{"en":"We ate dinner under a dim kitchen light.","vi":"Chúng tôi ăn tối dưới ánh đèn bếp mờ ảo.","audioKind":"ex"},{"en":"Dim lighting in public spaces can make pedestrians feel unsafe, particularly when walking alone at night.","vi":"Ánh sáng mờ ảo ở các không gian công cộng có thể khiến người đi bộ cảm thấy không an toàn, đặc biệt khi đi lại một mình vào ban đêm.","audioKind":"ex2"}],"collocations":[{"en":"dim light","vi":"ánh sáng mờ"},{"en":"a dim memory","vi":"ký ức mờ nhạt"},{"en":"dim the lights","vi":"vặn nhỏ đèn"},{"en":"take a dim view of","vi":"có cái nhìn không mấy thiện cảm"}],"wordFamily":["dimly (adv.)","dimness (n.)"],"synonyms":["faint","gloomy"],"antonyms":["bright"],"tipVi":"Biến đổi gấp đôi chữ m: dimmer, dimmest, dimmed.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stroll', 'en-b2-78', 'stroll', '/stroʊl/', 'B2', 'đi dạo; tản bộ thong thả; cuộc đi dạo; cuộc tản bộ', 'v.', NULL, 'Đồng nghĩa: saunter, amble', 'Nhấn mạnh sự thong thả, không vội vã; danh từ thường đi với take hoặc go for.', 'We strolled along the river after our evening meal.', NULL, 'Chúng tôi đi dạo dọc theo bờ sông sau bữa tối.', '{"wordId":"stroll","ukIpa":"/strəʊl/","usIpa":"/stroʊl/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to walk slowly and comfortably for pleasure","vi":"đi dạo; tản bộ thong thả"},{"pos":"n.","en":"a slow, relaxed walk taken for pleasure","vi":"cuộc đi dạo; cuộc tản bộ"}],"examples":[{"en":"We strolled along the river after our evening meal.","vi":"Chúng tôi đi dạo dọc theo bờ sông sau bữa tối.","audioKind":"ex"},{"en":"Accessible urban parks allow residents to stroll outdoors, supporting both physical health and mental wellbeing.","vi":"Các công viên đô thị dễ tiếp cận cho phép cư dân tản bộ ngoài trời, hỗ trợ cả sức khỏe thể chất lẫn tinh thần.","audioKind":"ex2"}],"collocations":[{"en":"take a stroll","vi":"đi dạo"},{"en":"stroll along the beach","vi":"dạo bước dọc bãi biển"},{"en":"a leisurely stroll","vi":"một buổi dạo chơi thong thả"}],"wordFamily":[],"synonyms":["saunter","amble"],"antonyms":[],"tipVi":"Nhấn mạnh sự thong thả, không vội vã; danh từ thường đi với take hoặc go for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_adequate', 'en-b2-78', 'adequate', '/ˈædɪkwət/', 'B2', 'đủ; đầy đủ; thích hợp', 'adj.', 'adequacy (n.), adequately (adv.), inadequate (adj.), inadequacy (n.)', 'Đồng nghĩa: sufficient, satisfactory · Trái nghĩa: inadequate, insufficient', 'Biểu thị đạt đến tiêu chuẩn cần thiết, không có nghĩa là xuất sắc; thường đi với giới từ for hoặc to.', 'This small heater provides adequate warmth for my bedroom.', NULL, 'Chiếc máy sưởi nhỏ này cung cấp lượng nhiệt vừa đủ cho phòng ngủ của tôi.', '{"wordId":"adequate","ukIpa":"/ˈædɪkwət/","usIpa":"/ˈædɪkwət/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"enough or good enough for a particular purpose","vi":"đủ; đầy đủ; thích hợp"}],"examples":[{"en":"This small heater provides adequate warmth for my bedroom.","vi":"Chiếc máy sưởi nhỏ này cung cấp lượng nhiệt vừa đủ cho phòng ngủ của tôi.","audioKind":"ex"},{"en":"Schools need adequate funding to maintain safe buildings and provide effective support for students with additional needs.","vi":"Các trường học cần có nguồn tài chính đầy đủ để duy trì cơ sở vật chất an toàn và cung cấp sự hỗ trợ hiệu quả cho học sinh có nhu cầu đặc biệt.","audioKind":"ex2"}],"collocations":[{"en":"adequate funding","vi":"nguồn vốn đầy đủ"},{"en":"adequate preparation","vi":"sự chuẩn bị chu đáo"},{"en":"adequate for the task","vi":"đủ khả năng hoàn thành nhiệm vụ"}],"wordFamily":["adequacy (n.)","adequately (adv.)","inadequate (adj.)","inadequacy (n.)"],"synonyms":["sufficient","satisfactory"],"antonyms":["inadequate","insufficient"],"tipVi":"Biểu thị đạt đến tiêu chuẩn cần thiết, không có nghĩa là xuất sắc; thường đi với giới từ for hoặc to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_whisper', 'en-b2-78', 'whisper', '/ˈwɪspɚ/', 'B2', 'thì thầm; nói nhỏ; tai bay vách đá; tiếng thì thầm; tiếng xì xào; tin đồn râm ran; lời đồn thổi', 'v.', NULL, 'Đồng nghĩa: murmur · Trái nghĩa: shout', 'Nói tai ai đó dùng whisper to someone; nói nhỏ nhẹ dùng in a whisper.', 'Please whisper while the baby sleeps in the next room.', NULL, 'Xin hãy nói nhỏ trong lúc em bé đang ngủ ở căn phòng bên cạnh.', '{"wordId":"whisper","ukIpa":"/ˈwɪspə/","usIpa":"/ˈwɪspɚ/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To speak very quietly without using your full voice","vi":"thì thầm; nói nhỏ; tai bay vách đá"},{"pos":"n.","en":"Very quiet speech made without a full voice","vi":"tiếng thì thầm; tiếng xì xào"},{"pos":"n.","en":"A quietly circulated rumour or suggestion","vi":"tin đồn râm ran; lời đồn thổi"}],"examples":[{"en":"Please whisper while the baby sleeps in the next room.","vi":"Xin hãy nói nhỏ trong lúc em bé đang ngủ ở căn phòng bên cạnh.","audioKind":"ex"},{"en":"Students may whisper during individual tasks because they need reassurance rather than because they intend to disrupt lessons.","vi":"Học sinh có thể thì thầm trong lúc làm bài tập cá nhân vì các em cần sự trấn an chứ không phải có ý định làm rối lớp học.","audioKind":"ex2"}],"collocations":[{"en":"whisper to someone","vi":"thì thầm với ai đó"},{"en":"in a whisper","vi":"bằng giọng thì thầm; nói nhỏ"},{"en":"barely above a whisper","vi":"vừa đủ nghe; suýt thì thành tiếng thì thầm"}],"wordFamily":[],"synonyms":["murmur"],"antonyms":["shout"],"tipVi":"Nói tai ai đó dùng whisper to someone; nói nhỏ nhẹ dùng in a whisper.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_numerous', 'en-b2-78', 'numerous', '/ˈnuːmərəs/', 'B2', 'nhiều; đông đảo', 'adj.', 'number (n.), numerically (adv.), numerical (adj.)', 'Đồng nghĩa: many, countless · Trái nghĩa: few', 'Chỉ bổ nghĩa cho danh từ đếm được số nhiều, không dùng trực tiếp với danh từ không đếm được.', 'Numerous birds gathered around the crumbs on our balcony.', NULL, 'Rất nhiều chú chim tụ tập quanh những vụn bánh mì trên ban công nhà chúng tôi.', '{"wordId":"numerous","ukIpa":"/ˈnjuːmərəs/","usIpa":"/ˈnuːmərəs/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Existing in large numbers.","vi":"nhiều; đông đảo"}],"examples":[{"en":"Numerous birds gathered around the crumbs on our balcony.","vi":"Rất nhiều chú chim tụ tập quanh những vụn bánh mì trên ban công nhà chúng tôi.","audioKind":"ex"},{"en":"Numerous studies suggest that access to green spaces can improve the mental health of urban residents.","vi":"Nhiều nghiên cứu cho thấy việc tiếp cận không gian xanh có thể cải thiện sức khỏe tinh thần của cư dân đô thị.","audioKind":"ex2"}],"collocations":[{"en":"numerous studies","vi":"nhiều nghiên cứu"},{"en":"numerous occasions","vi":"nhiều dịp"},{"en":"numerous benefits","vi":"nhiều lợi ích"}],"wordFamily":["number (n.)","numerically (adv.)","numerical (adj.)"],"synonyms":["many","countless"],"antonyms":["few"],"tipVi":"Chỉ bổ nghĩa cho danh từ đếm được số nhiều, không dùng trực tiếp với danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pace', 'en-b2-78', 'pace', '/peɪs/', 'B2', 'tốc độ; nhịp độ; bước chân; đi lại bồn chồn', 'n.', 'paced (adj.), pacing (n.)', NULL, 'Diễn tả tốc độ nào đó dùng cấu trúc at a... pace; keep pace with mang nghĩa bắt kịp, theo kịp.', 'We slowed our pace so Grandma could catch up.', NULL, 'Chúng tôi giảm tốc độ bước đi để bà có thể theo kịp.', '{"wordId":"pace","ukIpa":"/peɪs/","usIpa":"/peɪs/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"The speed at which someone moves or something happens","vi":"tốc độ; nhịp độ"},{"pos":"n.","en":"A single step taken when walking","vi":"bước chân"},{"pos":"v.","en":"To walk repeatedly back and forth, often when worried","vi":"đi lại bồn chồn"}],"examples":[{"en":"We slowed our pace so Grandma could catch up.","vi":"Chúng tôi giảm tốc độ bước đi để bà có thể theo kịp.","audioKind":"ex"},{"en":"The rapid pace of technological change requires workers to update their skills throughout their careers.","vi":"Nhịp độ thay đổi nhanh chóng của công nghệ đòi hỏi người lao động phải cập nhật kỹ năng xuyên suốt sự nghiệp của mình.","audioKind":"ex2"}],"collocations":[{"en":"at your own pace","vi":"theo nhịp độ riêng của bạn"},{"en":"keep pace with","vi":"theo kịp với"},{"en":"the pace of change","vi":"nhịp độ thay đổi"},{"en":"pace up and down","vi":"đi bách bộ qua lại"}],"wordFamily":["paced (adj.)","pacing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Diễn tả tốc độ nào đó dùng cấu trúc at a... pace; keep pace with mang nghĩa bắt kịp, theo kịp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chill', 'en-b2-78', 'chill', '/tʃɪl/', 'B2', 'sự lạnh lẽo; cảm giác rét; làm lạnh; làm mát; thư giãn; nghỉ ngơi', 'n.', 'chilly (adj.), chilled (adj.), chilling (adj.)', NULL, 'chill có nghĩa là làm mát hoặc làm lạnh chứ không nhất thiết phải đông đá; chill out là từ khẩu ngữ mang nghĩa thư giãn.', 'There was a chill in the air this morning.', NULL, 'Sáng nay không khí mang theo một chút hơi lạnh.', '{"wordId":"chill","ukIpa":"/tʃɪl/","usIpa":"/tʃɪl/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"An unpleasant feeling of cold in the air or body.","vi":"sự lạnh lẽo; cảm giác rét"},{"pos":"v.","en":"To make something cold, without necessarily freezing it.","vi":"làm lạnh; làm mát"},{"pos":"v.","en":"To relax rather than work or worry.","vi":"thư giãn; nghỉ ngơi"}],"examples":[{"en":"There was a chill in the air this morning.","vi":"Sáng nay không khí mang theo một chút hơi lạnh.","audioKind":"ex"},{"en":"Food businesses should chill perishable products promptly to limit bacterial growth and protect public health.","vi":"Các doanh nghiệp thực phẩm nên nhanh chóng làm lạnh các sản phẩm dễ hỏng để kìm hãm sự phát triển của vi khuẩn và bảo vệ sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"a chill in the air","vi":"hơi lạnh trong không khí"},{"en":"chill the dough","vi":"làm lạnh bột"},{"en":"chill out","vi":"thư giãn"}],"wordFamily":["chilly (adj.)","chilled (adj.)","chilling (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"chill có nghĩa là làm mát hoặc làm lạnh chứ không nhất thiết phải đông đá; chill out là từ khẩu ngữ mang nghĩa thư giãn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rake', 'en-b2-78', 'rake', '/reɪk/', 'B2', 'cào (dụng cụ có cán dài và răng cào để gom lá hoặc làm phẳng đất); cào; gom lại bằng cào', 'n.', NULL, NULL, 'Cụm "rake up" có thể dùng với nghĩa cào gom lại, hoặc nhắc lại những chuyện cũ không vui.', 'I used a rake to gather the fallen leaves.', NULL, 'Tôi dùng cái cào để gom những chiếc lá rụng lại.', '{"wordId":"rake","ukIpa":"/reɪk/","usIpa":"/reɪk/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"a long-handled tool with teeth for gathering leaves or smoothing soil","vi":"cào (dụng cụ có cán dài và răng cào để gom lá hoặc làm phẳng đất)"},{"pos":"v.","en":"to gather or level something using a rake","vi":"cào; gom lại bằng cào"}],"examples":[{"en":"I used a rake to gather the fallen leaves.","vi":"Tôi dùng cái cào để gom những chiếc lá rụng lại.","audioKind":"ex"},{"en":"Volunteers rake leaves in public gardens to keep paths accessible and maintain attractive communal spaces.","vi":"Các tình nguyện viên cào lá trong các khu vườn công cộng để giữ cho lối đi luôn thông thoáng và duy trì không gian chung đẹp mắt.","audioKind":"ex2"}],"collocations":[{"en":"garden rake","vi":"cào làm vườn"},{"en":"rake leaves","vi":"cào lá"},{"en":"rake the soil","vi":"cào đất"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm \"rake up\" có thể dùng với nghĩa cào gom lại, hoặc nhắc lại những chuyện cũ không vui.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cheeky', 'en-b2-78', 'cheeky', '/ˈtʃiːki/', 'B2', 'tinh nghịch; láu lỉnh; hỗn láo', 'adj.', 'cheek (n.), cheekily (adv.), cheekiness (n.)', 'Đồng nghĩa: impudent, impertinent · Trái nghĩa: respectful', 'Chỉ tính cách tinh nghịch, lém lỉnh, không dùng để chỉ hình dáng mập mạp; mập mạp dùng chubby.', 'The child gave a cheeky grin and took another biscuit.', NULL, 'Đứa trẻ cười toe toét tinh nghịch và lấy thêm một chiếc bánh quy.', '{"wordId":"cheeky","ukIpa":"/ˈtʃiːki/","usIpa":"/ˈtʃiːki/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Slightly rude or disrespectful, often in an amusing way","vi":"tinh nghịch; láu lỉnh; hỗn láo"}],"examples":[{"en":"The child gave a cheeky grin and took another biscuit.","vi":"Đứa trẻ cười toe toét tinh nghịch và lấy thêm một chiếc bánh quy.","audioKind":"ex"},{"en":"Advertisements sometimes use cheeky humour to attract attention, although audiences may differ in what they find acceptable.","vi":"Quảng cáo đôi khi sử dụng sự hài hước tinh nghịch để thu hút sự chú ý, mặc dù khán giả có thể có tiêu chuẩn chấp nhận khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"a cheeky grin","vi":"nụ cười toe toét tinh nghịch"},{"en":"a cheeky remark","vi":"lời nói hỗn xược"},{"en":"a cheeky request","vi":"yêu cầu táo tợn"}],"wordFamily":["cheek (n.)","cheekily (adv.)","cheekiness (n.)"],"synonyms":["impudent","impertinent"],"antonyms":["respectful"],"tipVi":"Chỉ tính cách tinh nghịch, lém lỉnh, không dùng để chỉ hình dáng mập mạp; mập mạp dùng chubby.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fleece', 'en-b2-78', 'fleece', '/fliːs/', 'B2', 'lông cừu; bộ lông cừu; vải nỉ mềm; áo khoác nỉ; lừa đảo; móc túi', 'n.', 'fleecy (adj.)', NULL, 'Nghĩa chất liệu vải thường không đếm được; a fleece có thể chỉ một chiếc áo khoác nỉ.', 'The farmer carefully removed the sheep''s thick fleece.', NULL, 'Người nông dân cẩn thận cạo đi lớp lông dày của con cừu.', '{"wordId":"fleece","ukIpa":"/fliːs/","usIpa":"/fliːs/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"the wool covering a sheep, or removed in one piece","vi":"lông cừu; bộ lông cừu"},{"pos":"n.","en":"a soft warm fabric, or a jacket made from it","vi":"vải nỉ mềm; áo khoác nỉ"},{"pos":"v.","en":"to cheat someone by charging too much or taking their money","vi":"lừa đảo; móc túi"}],"examples":[{"en":"The farmer carefully removed the sheep''s thick fleece.","vi":"Người nông dân cẩn thận cạo đi lớp lông dày của con cừu.","audioKind":"ex"},{"en":"Although synthetic fleece provides affordable warmth, washing it can release tiny plastic fibres into waterways.","vi":"Mặc dù vải nỉ tổng hợp giữ ấm tốt với giá cả phải chăng, nhưng việc giặt chúng có thể giải phóng các sợi nhựa vi mô vào nguồn nước.","audioKind":"ex2"}],"collocations":[{"en":"sheep''s fleece","vi":"bộ lông của cừu"},{"en":"fleece jacket","vi":"áo khoác nỉ"},{"en":"synthetic fleece","vi":"vải nỉ tổng hợp"}],"wordFamily":["fleecy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa chất liệu vải thường không đếm được; a fleece có thể chỉ một chiếc áo khoác nỉ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_accessory', 'en-b2-78', 'accessory', '/əkˈsesəri/', 'B2', 'phụ kiện; linh kiện bổ trợ; phụ kiện thời trang (trang sức, túi xách,...); kẻ đồng lõa; kẻ tòng phạm', 'n.', NULL, NULL, 'Từ này thường dùng ở dạng số nhiều accessories cho đồ đi kèm; nghĩa tòng phạm thường đi với giới từ to.', 'This small camera accessory keeps my photos steady.', NULL, 'Phụ kiện máy ảnh nhỏ gọn này giúp những bức ảnh của tôi luôn ổn định.', '{"wordId":"accessory","ukIpa":"/əkˈsesəri/","usIpa":"/əkˈsesəri/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"An extra item that adds usefulness to something","vi":"phụ kiện; linh kiện bổ trợ"},{"pos":"n.","en":"Something worn or carried to complement clothing","vi":"phụ kiện thời trang (trang sức, túi xách,...)"},{"pos":"n.","en":"Someone who helps another person commit a crime","vi":"kẻ đồng lõa; kẻ tòng phạm"}],"examples":[{"en":"This small camera accessory keeps my photos steady.","vi":"Phụ kiện máy ảnh nhỏ gọn này giúp những bức ảnh của tôi luôn ổn định.","audioKind":"ex"},{"en":"Consumers often replace electronic accessories unnecessarily, increasing waste and demand for raw materials worldwide.","vi":"Người tiêu dùng thường thay thế các phụ kiện điện tử một cách không cần thiết, làm gia tăng rác thải và nhu cầu nguyên liệu thô trên toàn cầu.","audioKind":"ex2"}],"collocations":[{"en":"camera accessories","vi":"phụ kiện máy ảnh"},{"en":"fashion accessories","vi":"phụ kiện thời trang"},{"en":"an accessory to a crime","vi":"kẻ đồng lõa trong một vụ án"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Từ này thường dùng ở dạng số nhiều accessories cho đồ đi kèm; nghĩa tòng phạm thường đi với giới từ to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_suck', 'en-b2-78', 'suck', '/sʌk/', 'B2', 'mút; bú; hít; hút vào; lôi cuốn; tệ hại; dở tệ (văn phong thông tục)', 'v.', 'suction (n.)', NULL, 'Khi mang nghĩa "rất tệ", đây là từ lóng không trang trọng và không phù hợp trong văn viết học thuật.', 'The baby sucked her thumb and slowly fell asleep.', NULL, 'Em bé mút ngón tay cái và từ từ chìm vào giấc ngủ.', '{"wordId":"suck","ukIpa":"/sʌk/","usIpa":"/sʌk/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To draw liquid or air in using the mouth","vi":"mút; bú; hít"},{"pos":"v.","en":"To pull something inward through suction","vi":"hút vào; lôi cuốn"},{"pos":"v.","en":"To be very bad or unpleasant, in informal speech","vi":"tệ hại; dở tệ (văn phong thông tục)"}],"examples":[{"en":"The baby sucked her thumb and slowly fell asleep.","vi":"Em bé mút ngón tay cái và từ từ chìm vào giấc ngủ.","audioKind":"ex"},{"en":"Modern ventilation systems suck polluted air out of buildings, helping to maintain a healthier indoor environment.","vi":"Hệ thống thông gió hiện đại hút không khí ô nhiễm ra khỏi các tòa nhà, giúp duy trì môi trường trong nhà lành mạnh hơn.","audioKind":"ex2"}],"collocations":[{"en":"suck your thumb","vi":"mút ngón tay cái"},{"en":"suck through a straw","vi":"hút bằng ống hút"},{"en":"suck in air","vi":"hút không khí vào"},{"en":"suck up water","vi":"hút nước"}],"wordFamily":["suction (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi mang nghĩa \"rất tệ\", đây là từ lóng không trang trọng và không phù hợp trong văn viết học thuật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stable', 'en-b2-78', 'stable', '/ˈsteɪbəl/', 'B2', 'ổn định; vững chắc; chuồng ngựa', 'adj.', 'stability (n.), stabilize (v.), unstable (adj.)', 'Đồng nghĩa: steady, secure · Trái nghĩa: unstable', 'Khi là tính từ nghĩa là ổn định; khi là danh từ đếm được nghĩa là chuồng ngựa.', 'The table feels stable now that we tightened its legs.', NULL, 'Cái bàn có vẻ vững chắc hơn sau khi chúng tôi vặn chặt các chân bàn.', '{"wordId":"stable","ukIpa":"/ˈsteɪbəl/","usIpa":"/ˈsteɪbəl/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"unlikely to change suddenly, fall, or become worse","vi":"ổn định; vững chắc"},{"pos":"n.","en":"a building where horses are kept","vi":"chuồng ngựa"}],"examples":[{"en":"The table feels stable now that we tightened its legs.","vi":"Cái bàn có vẻ vững chắc hơn sau khi chúng tôi vặn chặt các chân bàn.","audioKind":"ex"},{"en":"A stable income allows families to plan for future expenses and reduces their dependence on emergency financial assistance.","vi":"Thu nhập ổn định giúp các gia đình lên kế hoạch cho các khoản chi phí trong tương lai và giảm sự phụ thuộc vào hỗ trợ tài chính khẩn cấp.","audioKind":"ex2"}],"collocations":[{"en":"a stable income","vi":"thu nhập ổn định"},{"en":"remain stable","vi":"giữ ổn định"},{"en":"a stable environment","vi":"môi trường ổn định"},{"en":"in a stable condition","vi":"ở trong tình trạng ổn định"}],"wordFamily":["stability (n.)","stabilize (v.)","unstable (adj.)"],"synonyms":["steady","secure"],"antonyms":["unstable"],"tipVi":"Khi là tính từ nghĩa là ổn định; khi là danh từ đếm được nghĩa là chuồng ngựa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_virtually', 'en-b2-78', 'virtually', '/ˈvɝːtʃuəli/', 'B2', 'hầu như; gần như; trên thực tế; bằng hình thức trực tuyến; qua mạng', 'adv.', 'virtual (adj.)', 'Đồng nghĩa: almost, nearly', 'Thường mang nghĩa là "hầu như", không đồng nghĩa với actually (thực sự, trên thực tế).', 'The fridge was virtually empty when we got home.', NULL, 'Tủ lạnh hầu như trống rỗng khi chúng tôi về đến nhà.', '{"wordId":"virtually","ukIpa":"/ˈvɜːtʃuəli/","usIpa":"/ˈvɝːtʃuəli/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"Almost completely, or in every important practical way.","vi":"hầu như; gần như; trên thực tế"},{"pos":"adv.","en":"Using computers rather than being physically present.","vi":"bằng hình thức trực tuyến; qua mạng"}],"examples":[{"en":"The fridge was virtually empty when we got home.","vi":"Tủ lạnh hầu như trống rỗng khi chúng tôi về đến nhà.","audioKind":"ex"},{"en":"Online courses have made educational resources accessible from virtually any location with an internet connection.","vi":"Các khóa học trực tuyến đã giúp mọi người tiếp cận tài nguyên giáo dục từ hầu như bất kỳ nơi nào có kết nối Internet.","audioKind":"ex2"}],"collocations":[{"en":"virtually impossible","vi":"hầu như bất khả thi"},{"en":"virtually identical","vi":"gần như giống hệt nhau"},{"en":"virtually all","vi":"hầu như tất cả"}],"wordFamily":["virtual (adj.)"],"synonyms":["almost","nearly"],"antonyms":[],"tipVi":"Thường mang nghĩa là \"hầu như\", không đồng nghĩa với actually (thực sự, trên thực tế).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_78_1', 'en-b2-78', 'Cách dùng “chill” (n.) — sự lạnh lẽo; cảm giác rét', 'a chill in the air  ·  chill the dough  ·  chill out', 'chill có nghĩa là làm mát hoặc làm lạnh chứ không nhất thiết phải đông đá; chill out là từ khẩu ngữ mang nghĩa thư giãn.', 'Họ từ (Word Family): chilly (adj.), chilled (adj.), chilling (adj.)', '[{"hanzi":"There was a chill in the air this morning.","pinyin":"","meaning":"Sáng nay không khí mang theo một chút hơi lạnh."},{"hanzi":"Food businesses should chill perishable products promptly to limit bacterial growth and protect public health.","pinyin":"","meaning":"Các doanh nghiệp thực phẩm nên nhanh chóng làm lạnh các sản phẩm dễ hỏng để kìm hãm sự phát triển của vi khuẩn và bảo vệ sức khỏe cộng đồng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_78_2', 'en-b2-78', 'Cách dùng “furnish” (v.) — trang bị nội thất; bày biện đồ đạc (cho phòng, nhà)', 'furnish a flat  ·  furnish someone with evidence  ·  fully furnished', 'Cấu trúc "furnish A with B" nghĩa là cung cấp cho A cái gì đó (B); nghĩa cung cấp này mang sắc thái khá trang trọng.', 'Họ từ (Word Family): furniture (n.), furnishings (n.), furnished (adj.) | Đồng nghĩa: equip, supply', '[{"hanzi":"We furnished our flat with second-hand tables and chairs.","pinyin":"","meaning":"Chúng tôi đã trang hoàng căn hộ của mình bằng bàn ghế mua lại từ cửa hàng đồ cũ."},{"hanzi":"Applicants must furnish the university with evidence of their qualifications before their applications can be assessed.","pinyin":"","meaning":"Các ứng viên phải cung cấp cho trường đại học các minh chứng về bằng cấp của họ trước khi hồ sơ được xét duyệt."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_78_3', 'en-b2-78', 'Cách dùng “freshen” (v.) — làm cho tươi mới; làm trong lành', 'freshen up  ·  freshen the air  ·  freshen your breath', 'freshen up thường chỉ việc rửa mặt, chỉnh trang lại trang phục; khi gió làm chủ ngữ, nó chỉ gió thổi mạnh hơn.', 'Họ từ (Word Family): fresh (adj.), freshness (n.), freshly (adv.) | Đồng nghĩa: refresh', '[{"hanzi":"Let''s open a window to freshen the room.","pinyin":"","meaning":"Hãy mở cửa sổ để làm trong lành không khí trong phòng nào."},{"hanzi":"Planting trees can freshen urban spaces while providing shade and improving the overall appearance of neighbourhoods.","pinyin":"","meaning":"Việc trồng cây xanh có thể làm cho không gian đô thị tươi mới hơn, đồng thời tạo bóng râm và cải thiện diện mạo tổng thể của các khu dân cư."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_78_4', 'en-b2-78', 'Cách dùng “jerk” (v.) — giật mạnh, chuyển động đột ngột', 'jerk forward  ·  jerk away  ·  a sudden jerk', 'Hành động mang tính chất đột ngột và chớp nhoáng; việc gọi ai đó là "a jerk" mang sắc thái bất lịch sự.', 'Họ từ (Word Family): jerky (adj.), jerkily (adv.) | Đồng nghĩa: jolt, yank', '[{"hanzi":"The bus jerked forward, making my shopping bag tumble.","pinyin":"","meaning":"Chiếc xe buýt đột ngột chồm về phía trước khiến chiếc túi mua sắm của tôi bị lật nhào."},{"hanzi":"Poorly maintained trains may jerk unexpectedly, increasing the risk of falls among passengers who are standing.","pinyin":"","meaning":"Những đoàn tàu được bảo dưỡng kém có thể giật cục bất ngờ, làm tăng nguy cơ té ngã cho những hành khách đang đứng."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_78_1', 'en-b2-78', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
