INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_78_1_2', 'ten_b2_78_1', 'sniff', 'The puppy sniffed my shoes before letting me inside.', 'The puppy sniffed my shoes before letting me inside.', '/snɪf/', 'Chú chó nhỏ ngửi giày của tôi trước khi cho phép tôi bước vào nhà.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_78_1_3', 'ten_b2_78_1', 'furnish', 'We furnished our flat with second-hand tables and chairs.', 'We furnished our flat with second-hand tables and chairs.', '/ˈfɝː.nɪʃ/', 'Chúng tôi đã trang hoàng căn hộ của mình bằng bàn ghế mua lại từ cửa hàng đồ cũ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_78_1_4', 'ten_b2_78_1', 'glitter', 'Tiny drops of water glitter on the leaves outside.', 'Tiny drops of water glitter on the leaves outside.', '/ˈɡlɪtər/', 'Những giọt nước nhỏ lấp lánh trên đám lá ngoài kia.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_78_1_5', 'ten_b2_78_1', 'hose', 'I used the hose to wash my muddy boots.', 'I used the hose to wash my muddy boots.', '/hoʊz/', 'Tôi dùng vòi nước để rửa sạch đôi bốt dính đầy bùn của mình.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_78_1_6', 'ten_b2_78_1', 'cling', 'The little boy clung to his father''s arm.', 'The little boy clung to his father''s arm.', '/klɪŋ/', 'Cậu bé ôm chặt lấy cánh tay của bố.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_78_1_7', 'ten_b2_78_1', 'counter', 'I left my shopping bag on the kitchen counter.', 'I left my shopping bag on the kitchen counter.', '/ˈkaʊntər/', 'Tôi để túi mua sắm trên mặt bàn bếp.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_78_1_8', 'ten_b2_78_1', 'jerk', 'The bus jerked forward, making my shopping bag tumble.', 'The bus jerked forward, making my shopping bag tumble.', '/dʒɝːk/', 'Chiếc xe buýt đột ngột chồm về phía trước khiến chiếc túi mua sắm của tôi bị lật nhào.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_78_1_1', 'en-b2-78', 'ten_b2_78_1', 'listening', 'listening', 'He always boasts about how fast he can run.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Anh ấy luôn khoác lác về việc mình chạy nhanh đến mức nào.","Bố mắng tôi vì tội để mở cửa tủ lạnh.","Chúng tôi ăn tối dưới ánh đèn bếp mờ ảo.","Cái bàn có vẻ vững chắc hơn sau khi chúng tôi vặn chặt các chân bàn."]'::jsonb, 0, 'He always boasts about how fast he can run. → Anh ấy luôn khoác lác về việc mình chạy nhanh đến mức nào.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_78_1_2', 'en-b2-78', 'ten_b2_78_1', 'listening', 'listening', 'The puppy sniffed my shoes before letting me inside.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chú chó nhỏ ngửi giày của tôi trước khi cho phép tôi bước vào nhà.","Anh ấy luôn khoác lác về việc mình chạy nhanh đến mức nào.","Cô ấy nhét một đồng xu vào khe hẹp.","Người nông dân cẩn thận cạo đi lớp lông dày của con cừu."]'::jsonb, 0, 'The puppy sniffed my shoes before letting me inside. → Chú chó nhỏ ngửi giày của tôi trước khi cho phép tôi bước vào nhà.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_78_1_3', 'en-b2-78', 'ten_b2_78_1', 'listening', 'listening', 'We furnished our flat with second-hand tables and chairs.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Phụ kiện máy ảnh nhỏ gọn này giúp những bức ảnh của tôi luôn ổn định.","Xin hãy nói nhỏ trong lúc em bé đang ngủ ở căn phòng bên cạnh.","Chúng tôi đã trang hoàng căn hộ của mình bằng bàn ghế mua lại từ cửa hàng đồ cũ.","Sáng nay không khí mang theo một chút hơi lạnh."]'::jsonb, 2, 'We furnished our flat with second-hand tables and chairs. → Chúng tôi đã trang hoàng căn hộ của mình bằng bàn ghế mua lại từ cửa hàng đồ cũ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_78_2', 'en-b2-78', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_78_2_1', 'ten_b2_78_2', 'boast', 'The city boasts an extensive public transport network, making it an attractive destination for sustainable tourism.', 'The city boasts an extensive public transport network, making it an attractive destination for sustainable tourism.', '/boʊst/', 'Thành phố này sở hữu một mạng lưới giao thông công cộng rộng khắp, khiến nơi đây trở thành một điểm đến hấp dẫn cho du lịch bền vững.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_78_2_2', 'ten_b2_78_2', 'sniff', 'Trained dogs can sniff out certain substances, making them valuable partners in wildlife conservation projects.', 'Trained dogs can sniff out certain substances, making them valuable partners in wildlife conservation projects.', '/snɪf/', 'Những chú chó được huấn luyện có thể đánh hơi ra các chất nhất định, biến chúng thành những người bạn đồng hành quý giá trong các dự án bảo tồn động vật hoang dã.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_78_2_3', 'ten_b2_78_2', 'furnish', 'Applicants must furnish the university with evidence of their qualifications before their applications can be assessed.', 'Applicants must furnish the university with evidence of their qualifications before their applications can be assessed.', '/ˈfɝː.nɪʃ/', 'Các ứng viên phải cung cấp cho trường đại học các minh chứng về bằng cấp của họ trước khi hồ sơ được xét duyệt.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_78_2_4', 'ten_b2_78_2', 'glitter', 'Although city skylines glitter at night, excessive artificial lighting can disrupt wildlife and waste energy.', 'Although city skylines glitter at night, excessive artificial lighting can disrupt wildlife and waste energy.', '/ˈɡlɪtər/', 'Mặc dù cảnh quan thành phố lấp lánh về đêm, việc chiếu sáng nhân tạo quá mức có thể làm xáo trộn đời sống động vật hoang dã và lãng phí năng lượng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_78_2_5', 'ten_b2_78_2', 'hose', 'During periods of drought, restricting garden hose use can help households conserve valuable water supplies.', 'During periods of drought, restricting garden hose use can help households conserve valuable water supplies.', '/hoʊz/', 'Trong thời kỳ hạn hán, việc hạn chế dùng vòi nước làm vườn có thể giúp các hộ gia đình tiết kiệm nguồn nước quý giá.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_78_2_6', 'ten_b2_78_2', 'cling', 'Some organisations cling to outdated practices even when new approaches could improve efficiency and employee satisfaction.', 'Some organisations cling to outdated practices even when new approaches could improve efficiency and employee satisfaction.', '/klɪŋ/', 'Một số tổ chức vẫn bám lấy các phương pháp lỗi thời ngay cả khi các cách tiếp cận mới có thể cải thiện hiệu suất và sự hài lòng của nhân viên.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_78_2_1', 'en-b2-78', 'ten_b2_78_2', 'listening', 'listening', 'The city boasts an extensive public transport network, making it an attractive destination for sustainable tourism.', NULL, 'Trong câu vừa nghe, từ “boast” mang nghĩa nào sau đây?', '["đặt mua dài hạn; đăng ký sử dụng dịch vụ","đảm nhận; đảm nhiệm; tiến hành","tổng quan; bản tóm tắt","khoác lác; khoe khoang; tự cao"]'::jsonb, 3, '“boast” (/boʊst/): khoác lác; khoe khoang; tự cao. Câu đầy đủ: The city boasts an extensive public transport network, making it an attractive destination for sustainable tourism.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_78_2_2', 'en-b2-78', 'ten_b2_78_2', 'listening', 'listening', 'Trained dogs can sniff out certain substances, making them valuable partners in wildlife conservation projects.', NULL, 'Trong câu vừa nghe, từ “sniff” mang nghĩa nào sau đây?', '["tự do; quyền tự chủ","hít; ngửi; khịt mũi","phong cách nấu nướng; ẩm thực; nền văn hóa ẩm thực","khẩn cấp; cấp bách"]'::jsonb, 1, '“sniff” (/snɪf/): hít; ngửi; khịt mũi. Câu đầy đủ: Trained dogs can sniff out certain substances, making them valuable partners in wildlife conservation projects.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
