INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_78_2', 'en-b2-78', NULL, 'comprehensive_test', 'listening', 'The puppy sniffed my shoes before letting me inside.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã trang hoàng căn hộ của mình bằng bàn ghế mua lại từ cửa hàng đồ cũ.","Chú chó nhỏ ngửi giày của tôi trước khi cho phép tôi bước vào nhà.","Cậu bé ôm chặt lấy cánh tay của bố.","Phụ kiện máy ảnh nhỏ gọn này giúp những bức ảnh của tôi luôn ổn định."]'::jsonb, 1, 'The puppy sniffed my shoes before letting me inside. → Chú chó nhỏ ngửi giày của tôi trước khi cho phép tôi bước vào nhà.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
