INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_78_6', 'en-b2-78', NULL, 'comprehensive_test', 'listening', 'The little boy clung to his father''s arm.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đi dạo dọc theo bờ sông sau bữa tối.","Cậu bé ôm chặt lấy cánh tay của bố.","Viện bảo tàng trưng bày một viên đạn nằm bên cạnh khẩu súng trường cũ.","Cái bàn có vẻ vững chắc hơn sau khi chúng tôi vặn chặt các chân bàn."]'::jsonb, 1, 'The little boy clung to his father''s arm. → Cậu bé ôm chặt lấy cánh tay của bố.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_78_7', 'en-b2-78', NULL, 'comprehensive_test', 'listening', 'counter', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cuộc diễu hành; đoàn diễu hành","bản giao hưởng","quầy (thanh toán, phục vụ); mặt bàn (nhà bếp)","đồng tính (nam)"]'::jsonb, 2, 'counter (/ˈkaʊntər/) → quầy (thanh toán, phục vụ); mặt bàn (nhà bếp); phản bác; chống lại; trung hòa; ngược lại; đối lập', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_78_8', 'en-b2-78', NULL, 'comprehensive_test', 'listening', 'The bus jerked forward, making my shopping bag tumble.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi để túi mua sắm trên mặt bàn bếp.","Xin hãy nói nhỏ trong lúc em bé đang ngủ ở căn phòng bên cạnh.","Chúng tôi đi dạo dọc theo bờ sông sau bữa tối.","Chiếc xe buýt đột ngột chồm về phía trước khiến chiếc túi mua sắm của tôi bị lật nhào."]'::jsonb, 3, 'The bus jerked forward, making my shopping bag tumble. → Chiếc xe buýt đột ngột chồm về phía trước khiến chiếc túi mua sắm của tôi bị lật nhào.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_78_9', 'en-b2-78', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A flexible tube used to carry water or other liquids”?', '["hose","sniff","jerk","whisper"]'::jsonb, 0, 'hose (/hoʊz/) → ống mềm (dùng để dẫn nước hoặc chất lỏng khác)', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
