INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_78_18', 'en-b2-78', NULL, 'comprehensive_test', 'reading', NULL, 'The city boasts an extensive public transport network, making it an attractive destination for sustainable tourism.', 'Dựa vào câu trên, từ “boast” có nghĩa phù hợp nhất là gì?', '["tán dương; ca ngợi","cay đắng; đầy uất ức; vô cùng (thất vọng/buồn bã)","khoác lác; khoe khoang; tự cao","xương sườn"]'::jsonb, 2, 'boast: khoác lác; khoe khoang; tự cao; sở hữu (điểm đáng tự hào); lời khoác lác; lời tự cao. Dịch cả câu: Thành phố này sở hữu một mạng lưới giao thông công cộng rộng khắp, khiến nơi đây trở thành một điểm đến hấp dẫn cho du lịch bền vững.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_78_19', 'en-b2-78', NULL, 'comprehensive_test', 'reading', NULL, 'Trained dogs can sniff out certain substances, making them valuable partners in wildlife conservation projects.', 'Dựa vào câu trên, từ “sniff” có nghĩa phù hợp nhất là gì?', '["hạn hán","hít; ngửi; khịt mũi","có tính truyền nhiễm; dễ lây lan","cột chỉ đường; biển chỉ đường"]'::jsonb, 1, 'sniff: hít; ngửi; khịt mũi; cái hít mũi; tiếng khịt mũi; tỏ ý coi thường; phớt lờ. Dịch cả câu: Những chú chó được huấn luyện có thể đánh hơi ra các chất nhất định, biến chúng thành những người bạn đồng hành quý giá trong các dự án bảo tồn động vật hoang dã.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_78_20', 'en-b2-78', NULL, 'comprehensive_test', 'reading', NULL, 'Applicants must furnish the university with evidence of their qualifications before their applications can be assessed.', 'Dựa vào câu trên, từ “furnish” có nghĩa phù hợp nhất là gì?', '["sự viện trợ; sự cứu trợ; tiền trợ giúp","danh từ: kính hiển vi","trang bị nội thất; bày biện đồ đạc (cho phòng, nhà)","khối lượng công việc; lượng công việc mà ai đó phải hoàn thành trong một khoảng thời gian nhất định"]'::jsonb, 2, 'furnish: trang bị nội thất; bày biện đồ đạc (cho phòng, nhà); cung cấp (thông tin, tài liệu cần thiết). Dịch cả câu: Các ứng viên phải cung cấp cho trường đại học các minh chứng về bằng cấp của họ trước khi hồ sơ được xét duyệt.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_78_21', 'en-b2-78', NULL, 'comprehensive_test', 'reading', NULL, 'Although city skylines glitter at night, excessive artificial lighting can disrupt wildlife and waste energy.', 'Dựa vào câu trên, từ “glitter” có nghĩa phù hợp nhất là gì?', '["đầu mẩu thuốc lá; tàn thuốc","sự biến mất; sự mất tích","lấp lánh; tỏa sáng","thuộc đạo đức; có đạo đức"]'::jsonb, 2, 'glitter: lấp lánh; tỏa sáng; kim tuyến (các mảnh nhỏ lấp lánh dùng để trang trí); vẻ lấp lánh; vẻ hào nhoáng. Dịch cả câu: Mặc dù cảnh quan thành phố lấp lánh về đêm, việc chiếu sáng nhân tạo quá mức có thể làm xáo trộn đời sống động vật hoang dã và lãng phí năng lượng.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_78_22', 'en-b2-78', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “mút; bú; hít”', '["interference","database","mutual","suck"]'::jsonb, 3, 'mút; bú; hít → suck (/sʌk/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_78_23', 'en-b2-78', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ổn định; vững chắc”', '["stable","violent","affection","leak"]'::jsonb, 0, 'ổn định; vững chắc → stable (/ˈsteɪbəl/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_78_24', 'en-b2-78', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hầu như; gần như; trên thực tế”', '["oxygen","virtually","crisp","bullying"]'::jsonb, 1, 'hầu như; gần như; trên thực tế → virtually (/ˈvɝːtʃuəli/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-79', 'en', 'Bài 79: Đời sống hằng ngày (6) - CEFR B2', 'CEFR B2', 'B2 · Đời sống', '27 từ vựng Tiếng Anh CEFR B2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4079, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_coldness', 'en-b2-79', 'coldness', '/ˈkoʊldnəs/', 'B2', 'sự lạnh giá; tính hàn; sự lạnh nhạt; sự thờ ơ', 'n.', 'cold (adj.), coldly (adv.)', 'Đồng nghĩa: chilliness, aloofness · Trái nghĩa: warmth', 'Có thể chỉ nhiệt độ thấp hoặc thái độ không thân thiện, danh từ này thường không đếm được.', 'The coldness of the water made me gasp.', NULL, 'Nước lạnh cóng khiến tôi phải há hốc mồm vì buốt.', '{"wordId":"coldness","ukIpa":"/ˈkəʊldnəs/","usIpa":"/ˈkoʊldnəs/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"the state or feeling of having a low temperature","vi":"sự lạnh giá; tính hàn"},{"pos":"n.","en":"a lack of friendliness, affection, or sympathy","vi":"sự lạnh nhạt; sự thờ ơ"}],"examples":[{"en":"The coldness of the water made me gasp.","vi":"Nước lạnh cóng khiến tôi phải há hốc mồm vì buốt.","audioKind":"ex"},{"en":"The apparent coldness of online communication can make it harder for remote workers to build trusting relationships.","vi":"Sự lạnh nhạt bề ngoài trong giao tiếp trực tuyến có thể khiến các nhân viên làm việc từ xa khó xây dựng mối quan hệ tin tưởng hơn.","audioKind":"ex2"}],"collocations":[{"en":"the coldness of the water","vi":"độ lạnh của nước"},{"en":"emotional coldness","vi":"sự lạnh lùng trong cảm xúc"},{"en":"respond with coldness","vi":"đáp lại bằng thái độ lạnh nhạt"}],"wordFamily":["cold (adj.)","coldly (adv.)"],"synonyms":["chilliness","aloofness"],"antonyms":["warmth"],"tipVi":"Có thể chỉ nhiệt độ thấp hoặc thái độ không thân thiện, danh từ này thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_occasional', 'en-b2-79', 'occasional', '/əˈkeɪʒənəl/', 'B2', 'thỉnh thoảng; đôi khi; không thường xuyên', 'adj.', 'occasion (n.), occasionally (adv.)', 'Đồng nghĩa: infrequent, sporadic · Trái nghĩa: frequent, regular', 'occasional là tính từ bổ nghĩa cho danh từ; occasionally là trạng từ bổ nghĩa cho động từ.', 'We enjoy an occasional picnic beside the river.', NULL, 'Chúng tôi thích những buổi đi dã ngoại thỉnh thoảng bên bờ sông.', '{"wordId":"occasional","ukIpa":"/əˈkeɪʒənəl/","usIpa":"/əˈkeɪʒənəl/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"happening sometimes, but not often or regularly","vi":"thỉnh thoảng; đôi khi; không thường xuyên"}],"examples":[{"en":"We enjoy an occasional picnic beside the river.","vi":"Chúng tôi thích những buổi đi dã ngoại thỉnh thoảng bên bờ sông.","audioKind":"ex"},{"en":"Even occasional access to green spaces can improve the wellbeing of people living in crowded cities.","vi":"Ngay cả việc thỉnh thoảng tiếp cận với không gian xanh cũng có thể cải thiện sức khỏe tinh thần của những người sống ở các thành phố đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"occasional visits","vi":"những chuyến thăm thỉnh thoảng"},{"en":"occasional problems","vi":"các vấn đề thỉnh thoảng xảy ra"},{"en":"an occasional user","vi":"người thỉnh thoảng sử dụng"}],"wordFamily":["occasion (n.)","occasionally (adv.)"],"synonyms":["infrequent","sporadic"],"antonyms":["frequent","regular"],"tipVi":"occasional là tính từ bổ nghĩa cho danh từ; occasionally là trạng từ bổ nghĩa cho động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_striking', 'en-b2-79', 'striking', '/ˈstraɪkɪŋ/', 'B2', 'nổi bật; gây ấn tượng mạnh; rõ rệt', 'adj.', 'strikingly (adv.), strike (v.)', 'Đồng nghĩa: remarkable, conspicuous · Trái nghĩa: unremarkable', 'Diễn tả sự bắt mắt hoặc rõ ràng, không nhất thiết mang ý nghĩa gây sốc.', 'Her bright scarf makes a striking contrast with her coat.', NULL, 'Chiếc khăn quàng cổ sáng màu của cô ấy tạo nên sự tương phản nổi bật với chiếc áo khoác.', '{"wordId":"striking","ukIpa":"/ˈstraɪkɪŋ/","usIpa":"/ˈstraɪkɪŋ/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Very noticeable or impressive.","vi":"nổi bật; gây ấn tượng mạnh; rõ rệt"}],"examples":[{"en":"Her bright scarf makes a striking contrast with her coat.","vi":"Chiếc khăn quàng cổ sáng màu của cô ấy tạo nên sự tương phản nổi bật với chiếc áo khoác.","audioKind":"ex"},{"en":"The survey revealed striking differences in access to public transport between urban and rural communities.","vi":"Cuộc khảo sát cho thấy những khác biệt rõ rệt về khả năng tiếp cận giao thông công cộng giữa các cộng đồng thành thị và nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"striking contrast","vi":"sự tương phản rõ rệt"},{"en":"striking resemblance","vi":"sự giống nhau đến kinh ngạc"},{"en":"striking difference","vi":"sự khác biệt rõ rệt"}],"wordFamily":["strikingly (adv.)","strike (v.)"],"synonyms":["remarkable","conspicuous"],"antonyms":["unremarkable"],"tipVi":"Diễn tả sự bắt mắt hoặc rõ ràng, không nhất thiết mang ý nghĩa gây sốc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_curl', 'en-b2-79', 'curl', '/kɜːrl/', 'B2', 'cuộn lại; uốn xoăn; làm cong; lọn tóc xoăn; vật uốn cong', 'v.', 'curly (adj.)', 'Trái nghĩa: straighten', 'curl up có nghĩa là cuộn tròn cơ thể lại, thường dùng cho cả người và động vật.', 'The dry leaves curl at the edges in autumn.', NULL, 'Những chiếc lá khô cuộn lại ở phần mép vào mùa thu.', '{"wordId":"curl","ukIpa":"/kɜːl/","usIpa":"/kɜːrl/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to form or make something form a curved shape","vi":"cuộn lại; uốn xoăn; làm cong"},{"pos":"n.","en":"a piece of hair or material shaped into a curve","vi":"lọn tóc xoăn; vật uốn cong"}],"examples":[{"en":"The dry leaves curl at the edges in autumn.","vi":"Những chiếc lá khô cuộn lại ở phần mép vào mùa thu.","audioKind":"ex"},{"en":"During prolonged droughts, leaves may curl to reduce water loss and protect plants from further damage.","vi":"Trong những đợt hạn hán kéo dài, lá cây có thể cuộn lại để giảm thoát hơi nước và bảo vệ cây khỏi hư hại thêm.","audioKind":"ex2"}],"collocations":[{"en":"curl up","vi":"cuộn tròn người lại"},{"en":"curl your hair","vi":"uốn xoăn tóc"},{"en":"tight curls","vi":"những lọn tóc xoăn tít"}],"wordFamily":["curly (adj.)"],"synonyms":[],"antonyms":["straighten"],"tipVi":"curl up có nghĩa là cuộn tròn cơ thể lại, thường dùng cho cả người và động vật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dent', 'en-b2-79', 'dent', '/dent/', 'B2', 'vết lõm; làm lõm; làm suy giảm; làm tổn hại (niềm tin, uy tín)', 'n.', 'dented (adj.)', 'Đồng nghĩa: indentation', 'dent không phải là "răng"; make a dent in có thể chỉ việc giảm bớt gánh nặng hoặc đạt bước tiến ban đầu.', 'My bike has a dent in its metal basket.', NULL, 'Giỏ kim loại của chiếc xe đạp tôi bị một vết lõm.', '{"wordId":"dent","ukIpa":"/dent/","usIpa":"/dent/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A hollow in a surface caused by pressure or impact","vi":"vết lõm"},{"pos":"v.","en":"To make or develop a hollow in a surface","vi":"làm lõm"},{"pos":"v.","en":"To reduce someone''s confidence or damage something''s strength or reputation","vi":"làm suy giảm; làm tổn hại (niềm tin, uy tín)"}],"examples":[{"en":"My bike has a dent in its metal basket.","vi":"Giỏ kim loại của chiếc xe đạp tôi bị một vết lõm.","audioKind":"ex"},{"en":"Repeated delays in public transport can dent passengers'' confidence and encourage greater reliance on private cars.","vi":"Tình trạng phương tiện công cộng liên tục chậm chuyến có thể làm giảm niềm tin của hành khách và thúc đẩy việc phụ thuộc nhiều hơn vào xe hơi cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"a dent in","vi":"vết lõm trên..."},{"en":"dent someone''s confidence","vi":"làm lung lay niềm tin của ai đó"},{"en":"make a dent in","vi":"làm giảm bớt; tạo ra bước đột phá"}],"wordFamily":["dented (adj.)"],"synonyms":["indentation"],"antonyms":[],"tipVi":"dent không phải là \"răng\"; make a dent in có thể chỉ việc giảm bớt gánh nặng hoặc đạt bước tiến ban đầu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_alongside', 'en-b2-79', 'alongside', '/əˌlɔːŋˈsaɪd/', 'B2', 'bên cạnh; cùng với; ở bên cạnh', 'prep.', NULL, 'Đồng nghĩa: beside', 'Khi làm giới từ, từ này theo sau bởi danh từ; cũng có thể diễn tả hai việc diễn ra song song.', 'I cycled alongside my sister by the river.', NULL, 'Tôi đạp xe song song với chị gái dọc theo bờ sông.', '{"wordId":"alongside","ukIpa":"/əˌlɒŋˈsaɪd/","usIpa":"/əˌlɔːŋˈsaɪd/","cefr":"B2","topic":"daily","senses":[{"pos":"prep.","en":"Beside someone or something, or together with them.","vi":"bên cạnh; cùng với"},{"pos":"adv.","en":"In a position beside someone or something.","vi":"ở bên cạnh"}],"examples":[{"en":"I cycled alongside my sister by the river.","vi":"Tôi đạp xe song song với chị gái dọc theo bờ sông.","audioKind":"ex"},{"en":"Schools should teach practical skills alongside academic subjects to prepare students for adult life.","vi":"Nhà trường nên giảng dạy các kỹ năng thực tế song song với các môn học thuật để chuẩn bị cho học sinh bước vào đời.","audioKind":"ex2"}],"collocations":[{"en":"work alongside","vi":"làm việc cùng"},{"en":"alongside the river","vi":"dọc theo con sông"},{"en":"alongside other measures","vi":"cùng với các biện pháp khác"}],"wordFamily":[],"synonyms":["beside"],"antonyms":[],"tipVi":"Khi làm giới từ, từ này theo sau bởi danh từ; cũng có thể diễn tả hai việc diễn ra song song.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fortunate', 'en-b2-79', 'fortunate', '/ˈfɔːrtʃənət/', 'B2', 'may mắn; có phước', 'adj.', 'fortune (n.), fortunately (adv.), unfortunate (adj.), unfortunately (adv.)', 'Đồng nghĩa: lucky · Trái nghĩa: unfortunate, unlucky', 'Thường dùng cấu trúc be fortunate to do, mang nghĩa có may mắn khi làm việc gì.', 'We were fortunate to find shelter before the storm.', NULL, 'Chúng tôi thật may mắn khi tìm được nơi trú ẩn trước cơn bão.', '{"wordId":"fortunate","ukIpa":"/ˈfɔːtʃənət/","usIpa":"/ˈfɔːrtʃənət/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Having good luck or experiencing a favourable outcome","vi":"may mắn; có phước"}],"examples":[{"en":"We were fortunate to find shelter before the storm.","vi":"Chúng tôi thật may mắn khi tìm được nơi trú ẩn trước cơn bão.","audioKind":"ex"},{"en":"Students with reliable internet access are fortunate, as many rural communities still lack adequate digital infrastructure.","vi":"Những học sinh có điều kiện kết nối internet ổn định rất may mắn, bởi vì nhiều vùng nông thôn vẫn thiếu cơ sở hạ tầng số đầy đủ.","audioKind":"ex2"}],"collocations":[{"en":"fortunate enough to","vi":"may mắn được"},{"en":"fortunate to have","vi":"may mắn có được"},{"en":"a fortunate escape","vi":"thoát nạn trong gang tấc"}],"wordFamily":["fortune (n.)","fortunately (adv.)","unfortunate (adj.)","unfortunately (adv.)"],"synonyms":["lucky"],"antonyms":["unfortunate","unlucky"],"tipVi":"Thường dùng cấu trúc be fortunate to do, mang nghĩa có may mắn khi làm việc gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_possess', 'en-b2-79', 'possess', '/pəˈzes/', 'B2', 'sở hữu; có; có được; mang (phẩm chất, năng lực)', 'v.', 'possession (n.), possessor (n.), possessive (adj.)', 'Đồng nghĩa: own, have · Trái nghĩa: lack', 'Mang tính trang trọng hơn have; thường không dùng ở thì tiếp diễn. Cần chú ý từ này có bốn chữ s.', 'My uncle possesses a remarkable collection of antique clocks.', NULL, 'Chú tôi sở hữu một bộ sưu tập đồng hồ cổ vô cùng ấn tượng.', '{"wordId":"possess","ukIpa":"/pəˈzes/","usIpa":"/pəˈzes/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to own or have something","vi":"sở hữu; có"},{"pos":"v.","en":"to have a particular quality, ability, or characteristic","vi":"có được; mang (phẩm chất, năng lực)"}],"examples":[{"en":"My uncle possesses a remarkable collection of antique clocks.","vi":"Chú tôi sở hữu một bộ sưu tập đồng hồ cổ vô cùng ấn tượng.","audioKind":"ex"},{"en":"Graduates who possess strong communication skills are often better prepared to adapt to changing workplace demands.","vi":"Những sinh viên sở hữu kỹ năng giao tiếp tốt thường có sự chuẩn bị tốt hơn để thích ứng với các yêu cầu thay đổi của nơi làm việc.","audioKind":"ex2"}],"collocations":[{"en":"possess skills","vi":"có kỹ năng"},{"en":"possess knowledge","vi":"nắm giữ kiến thức"},{"en":"possess property","vi":"sở hữu tài sản"}],"wordFamily":["possession (n.)","possessor (n.)","possessive (adj.)"],"synonyms":["own","have"],"antonyms":["lack"],"tipVi":"Mang tính trang trọng hơn have; thường không dùng ở thì tiếp diễn. Cần chú ý từ này có bốn chữ s.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shovel', 'en-b2-79', 'shovel', '/ˈʃʌvəl/', 'B2', 'cái xẻng; xúc; hất (bằng xẻng)', 'n.', NULL, NULL, 'Quá khứ đơn theo tiếng Anh-Anh là "shovelled", theo tiếng Anh-Mỹ là "shoveled".', 'I used a shovel to clear the snowy path.', NULL, 'Tôi đã dùng xẻng để dọn sạch tuyết trên lối đi.', '{"wordId":"shovel","ukIpa":"/ˈʃʌvəl/","usIpa":"/ˈʃʌvəl/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A tool with a broad blade for moving loose material.","vi":"cái xẻng"},{"pos":"v.","en":"To lift or move material using a shovel.","vi":"xúc; hất (bằng xẻng)"}],"examples":[{"en":"I used a shovel to clear the snowy path.","vi":"Tôi đã dùng xẻng để dọn sạch tuyết trên lối đi.","audioKind":"ex"},{"en":"Community volunteers shovelled soil into raised beds to create a garden on unused urban land.","vi":"Các tình nguyện viên cộng đồng đã xúc đất vào các luống trồng cao để tạo nên một khu vườn trên khu đất đô thị bỏ hoang.","audioKind":"ex2"}],"collocations":[{"en":"a snow shovel","vi":"xẻng xúc tuyết"},{"en":"shovel snow","vi":"xúc tuyết"},{"en":"shovel soil","vi":"xúc đất"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Quá khứ đơn theo tiếng Anh-Anh là \"shovelled\", theo tiếng Anh-Mỹ là \"shoveled\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lantern', 'en-b2-79', 'lantern', '/ˈlæntərn/', 'B2', 'đèn lồng; đèn xách tay', 'n.', NULL, NULL, 'Chỉ loại đèn có vỏ bọc bảo vệ và thường có quai xách; không đồng nghĩa với đèn pin.', 'He carried a lantern along the dark garden path.', NULL, 'Anh ấy xách một chiếc đèn lồng đi dọc theo con đường mòn tối tăm trong vườn.', '{"wordId":"lantern","ukIpa":"/ˈlæntən/","usIpa":"/ˈlæntərn/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"a light inside a protective container, often with a handle","vi":"đèn lồng; đèn xách tay"}],"examples":[{"en":"He carried a lantern along the dark garden path.","vi":"Anh ấy xách một chiếc đèn lồng đi dọc theo con đường mòn tối tăm trong vườn.","audioKind":"ex"},{"en":"Solar lanterns provide affordable lighting in remote communities where reliable access to electricity remains limited.","vi":"Đèn lồng năng lượng mặt trời cung cấp ánh sáng với chi phí phải chăng ở những cộng đồng vùng sâu vùng xa nơi việc tiếp cận điện năng ổn định còn nhiều hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"paper lantern","vi":"đèn lồng giấy"},{"en":"solar lantern","vi":"đèn lồng năng lượng mặt trời"},{"en":"light a lantern","vi":"thắp đèn lồng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ loại đèn có vỏ bọc bảo vệ và thường có quai xách; không đồng nghĩa với đèn pin.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_odour', 'en-b2-79', 'odour', '/ˈoʊdər/', 'B2', 'mùi; mùi khó chịu; mùi hôi', 'n.', 'odourless (adj.), odorous (adj.)', 'Đồng nghĩa: smell', 'Cách viết odour theo Anh-Anh, còn odor theo Anh-Mỹ; từ này thường dùng để chỉ mùi khó chịu.', 'A strange odour came from the kitchen bin.', NULL, 'Một mùi lạ bay ra từ thùng rác trong nhà bếp.', '{"wordId":"odour","ukIpa":"/ˈəʊdə/","usIpa":"/ˈoʊdər/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A noticeable smell, especially an unpleasant one.","vi":"mùi; mùi khó chịu; mùi hôi"}],"examples":[{"en":"A strange odour came from the kitchen bin.","vi":"Một mùi lạ bay ra từ thùng rác trong nhà bếp.","audioKind":"ex"},{"en":"Residents may oppose new waste facilities if they expect unpleasant odours to affect their quality of life.","vi":"Người dân có thể phản đối các cơ sở xử lý rác thải mới nếu họ dự đoán mùi khó chịu sẽ ảnh hưởng đến chất lượng cuộc sống của họ.","audioKind":"ex2"}],"collocations":[{"en":"an unpleasant odour","vi":"một mùi khó chịu"},{"en":"a strong odour","vi":"mùi nồng nặc"},{"en":"body odour","vi":"mùi cơ thể"},{"en":"odour control","vi":"việc kiểm soát mùi hôi"}],"wordFamily":["odourless (adj.)","odorous (adj.)"],"synonyms":["smell"],"antonyms":[],"tipVi":"Cách viết odour theo Anh-Anh, còn odor theo Anh-Mỹ; từ này thường dùng để chỉ mùi khó chịu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_soften', 'en-b2-79', 'soften', '/ˈsɔːfən/', 'B2', 'làm mềm; trở nên mềm hơn; làm dịu đi; giảm bớt sự gay gắt', 'v.', 'soft (adj.), softness (n.), softener (n.), softly (adv.)', 'Trái nghĩa: harden', 'Từ này vừa là nội động từ vừa là ngoại động từ: nhiệt độ làm bơ mềm ra, hoặc bản thân bơ tự mềm.', 'Leave the butter outside the fridge to soften.', NULL, 'Hãy để bơ ở ngoài tủ lạnh cho mềm ra.', '{"wordId":"soften","ukIpa":"/ˈsɒfən/","usIpa":"/ˈsɔːfən/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To become softer or make something softer","vi":"làm mềm; trở nên mềm hơn"},{"pos":"v.","en":"To make something less harsh, severe, or forceful","vi":"làm dịu đi; giảm bớt sự gay gắt"}],"examples":[{"en":"Leave the butter outside the fridge to soften.","vi":"Hãy để bơ ở ngoài tủ lạnh cho mềm ra.","audioKind":"ex"},{"en":"Additional financial support could soften the impact of rising energy prices on poorer households.","vi":"Sự hỗ trợ tài chính bổ sung có thể xoa dịu tác động của việc giá năng lượng leo thang đối với các hộ gia đình nghèo khó.","audioKind":"ex2"}],"collocations":[{"en":"soften butter","vi":"làm mềm bơ"},{"en":"soften the impact","vi":"làm giảm tác động"},{"en":"soften your tone","vi":"làm dịu giọng điệu"}],"wordFamily":["soft (adj.)","softness (n.)","softener (n.)","softly (adv.)"],"synonyms":[],"antonyms":["harden"],"tipVi":"Từ này vừa là nội động từ vừa là ngoại động từ: nhiệt độ làm bơ mềm ra, hoặc bản thân bơ tự mềm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lighten', 'en-b2-79', 'lighten', '/ˈlaɪtən/', 'B2', 'làm nhẹ đi; giảm bớt gánh nặng; làm sáng lên; làm nhạt màu; làm cho vui vẻ; làm dịu bầu không khí', 'v.', 'light (adj.), lightness (n.)', NULL, 'Động từ "lighten" có thể chỉ việc giảm tải trọng hoặc làm sáng lên; cụm "lighten up" thường mang nghĩa thư giãn, thoải mái hơn.', 'I removed two books to lighten my backpack.', NULL, 'Tôi lấy bớt hai cuốn sách ra để làm cho balo nhẹ hơn.', '{"wordId":"lighten","ukIpa":"/ˈlaɪtən/","usIpa":"/ˈlaɪtən/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to make something less heavy or less demanding","vi":"làm nhẹ đi; giảm bớt gánh nặng"},{"pos":"v.","en":"to become or make something brighter or paler","vi":"làm sáng lên; làm nhạt màu"},{"pos":"v.","en":"to make a mood or atmosphere more cheerful","vi":"làm cho vui vẻ; làm dịu bầu không khí"}],"examples":[{"en":"I removed two books to lighten my backpack.","vi":"Tôi lấy bớt hai cuốn sách ra để làm cho balo nhẹ hơn.","audioKind":"ex"},{"en":"Employers can lighten staff workloads by simplifying administrative procedures and providing better tools for routine tasks.","vi":"Người sử dụng lao động có thể giảm bớt gánh nặng công việc cho nhân viên bằng cách đơn giản hóa các thủ tục hành chính và cung cấp các công cụ tốt hơn cho công việc thường ngày.","audioKind":"ex2"}],"collocations":[{"en":"lighten the load","vi":"giảm bớt gánh nặng"},{"en":"lighten the mood","vi":"làm dịu bầu không khí"},{"en":"lighten a colour","vi":"làm nhạt màu sắc"}],"wordFamily":["light (adj.)","lightness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ \"lighten\" có thể chỉ việc giảm tải trọng hoặc làm sáng lên; cụm \"lighten up\" thường mang nghĩa thư giãn, thoải mái hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_external', 'en-b2-79', 'external', '/ɪkˈstɝːnəl/', 'B2', 'bên ngoài; thuộc về bên ngoài; đến từ bên ngoài (tổ chức, hệ thống)', 'adj.', 'externally (adv.)', 'Đồng nghĩa: outer, outside · Trái nghĩa: internal', 'Tính từ "external" trái nghĩa với "internal"; trên bao bì thuốc dùng để chỉ loại dùng ngoài da.', 'The builders painted the external walls pale yellow.', NULL, 'Những người thợ xây đã sơn các bức tường bên ngoài màu vàng nhạt.', '{"wordId":"external","ukIpa":"/ɪkˈstɜːnəl/","usIpa":"/ɪkˈstɝːnəl/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Located on the outside of something.","vi":"bên ngoài; thuộc về bên ngoài"},{"pos":"adj.","en":"Coming from outside a particular organisation, system, or situation.","vi":"đến từ bên ngoài (tổ chức, hệ thống)"}],"examples":[{"en":"The builders painted the external walls pale yellow.","vi":"Những người thợ xây đã sơn các bức tường bên ngoài màu vàng nhạt.","audioKind":"ex"},{"en":"Universities often rely on external funding to conduct research that cannot be supported by tuition fees alone.","vi":"Các trường đại học thường phải dựa vào nguồn tài trợ bên ngoài để thực hiện các nghiên cứu không thể duy trì chỉ bằng nguồn tiền học phí.","audioKind":"ex2"}],"collocations":[{"en":"external walls","vi":"tường bên ngoài"},{"en":"external factors","vi":"các yếu tố bên ngoài"},{"en":"external funding","vi":"nguồn vốn bên ngoài"},{"en":"for external use only","vi":"chỉ dùng bôi ngoài da"}],"wordFamily":["externally (adv.)"],"synonyms":["outer","outside"],"antonyms":["internal"],"tipVi":"Tính từ \"external\" trái nghĩa với \"internal\"; trên bao bì thuốc dùng để chỉ loại dùng ngoài da.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_minimal', 'en-b2-79', 'minimal', '/ˈmɪnɪməl/', 'B2', 'rất ít; tối thiểu; ở mức thấp nhất', 'adj.', 'minimally (adv.), minimum (n.), minimise (v.)', 'Đồng nghĩa: negligible, slight · Trái nghĩa: maximal, substantial', 'minimal chỉ số lượng rất ít hoặc mức tối thiểu, không nhất thiết là hoàn toàn không có.', 'These plants need minimal care, even during hot weather.', NULL, 'Những loài cây này cần rất ít sự chăm sóc, ngay cả trong thời tiết nắng nóng.', '{"wordId":"minimal","ukIpa":"/ˈmɪnɪməl/","usIpa":"/ˈmɪnɪməl/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"very small in amount or as little as possible","vi":"rất ít; tối thiểu; ở mức thấp nhất"}],"examples":[{"en":"These plants need minimal care, even during hot weather.","vi":"Những loài cây này cần rất ít sự chăm sóc, ngay cả trong thời tiết nắng nóng.","audioKind":"ex"},{"en":"Well-designed buildings can maintain comfortable indoor temperatures with minimal energy use, reducing both costs and emissions.","vi":"Các tòa nhà được thiết kế tốt có thể duy trì nhiệt độ trong nhà thoải mái với mức tiêu thụ năng lượng tối thiểu, giúp giảm cả chi phí lẫn lượng khí thải.","audioKind":"ex2"}],"collocations":[{"en":"minimal impact","vi":"ảnh hưởng tối thiểu"},{"en":"minimal effort","vi":"nỗ lực tối thiểu"},{"en":"minimal risk","vi":"rủi ro cực thấp"},{"en":"minimal supervision","vi":"sự giám sát tối thiểu"}],"wordFamily":["minimally (adv.)","minimum (n.)","minimise (v.)"],"synonyms":["negligible","slight"],"antonyms":["maximal","substantial"],"tipVi":"minimal chỉ số lượng rất ít hoặc mức tối thiểu, không nhất thiết là hoàn toàn không có.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disappearance', 'en-b2-79', 'disappearance', '/ˌdɪsəˈpɪrəns/', 'B2', 'sự biến mất; sự mất tích; sự suy tàn; sự lụi tàn; việc không còn tồn tại', 'n.', 'disappear (v.), appear (v.), appearance (n.)', 'Đồng nghĩa: vanishing · Trái nghĩa: appearance', 'Thường đi với giới từ of để chỉ người hoặc vật biến mất; động từ tương ứng là disappear.', 'The disappearance of my keys made me late again.', NULL, 'Sự biến mất của chùm chìa khóa khiến tôi lại đến muộn.', '{"wordId":"disappearance","ukIpa":"/ˌdɪsəˈpɪərəns/","usIpa":"/ˌdɪsəˈpɪrəns/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"The act of vanishing or becoming impossible to find.","vi":"sự biến mất; sự mất tích"},{"pos":"n.","en":"The process of gradually ceasing to exist.","vi":"sự suy tàn; sự lụi tàn; việc không còn tồn tại"}],"examples":[{"en":"The disappearance of my keys made me late again.","vi":"Sự biến mất của chùm chìa khóa khiến tôi lại đến muộn.","audioKind":"ex"},{"en":"The gradual disappearance of traditional crafts reflects changing lifestyles and declining demand for handmade goods.","vi":"Sự lụi tàn dần của các nghề thủ công truyền thống phản ánh sự thay đổi trong lối sống và nhu cầu giảm sút đối với các sản phẩm thủ công.","audioKind":"ex2"}],"collocations":[{"en":"sudden disappearance","vi":"sự biến mất đột ngột"},{"en":"mysterious disappearance","vi":"sự mất tích bí ẩn"},{"en":"gradual disappearance","vi":"sự mai mòn dần"}],"wordFamily":["disappear (v.)","appear (v.)","appearance (n.)"],"synonyms":["vanishing"],"antonyms":["appearance"],"tipVi":"Thường đi với giới từ of để chỉ người hoặc vật biến mất; động từ tương ứng là disappear.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_huddle', 'en-b2-79', 'huddle', '/ˈhʌdəl/', 'B2', 'cúi chụm lại; nép sát; cuộn tròn; đám đông túm tụm; cuộc họp kín ngắn', 'v.', NULL, 'Đồng nghĩa: cluster', 'huddle nhấn mạnh sự áp sát chặt, thường dùng để giữ ấm, tránh nguy hiểm hoặc bàn bạc riêng tư.', 'We huddled under one umbrella until the rain stopped.', NULL, 'Chúng tôi nép dưới một chiếc ô cho đến khi trời tạnh mưa.', '{"wordId":"huddle","ukIpa":"/ˈhʌdəl/","usIpa":"/ˈhʌdəl/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To gather closely together or curl up for warmth or protection.","vi":"cúi chụm lại; nép sát; cuộn tròn"},{"pos":"n.","en":"A group of people standing or sitting close together.","vi":"đám đông túm tụm"},{"pos":"n.","en":"A brief close gathering to discuss something privately.","vi":"cuộc họp kín ngắn"}],"examples":[{"en":"We huddled under one umbrella until the rain stopped.","vi":"Chúng tôi nép dưới một chiếc ô cho đến khi trời tạnh mưa.","audioKind":"ex"},{"en":"Without adequate shelter, displaced families may huddle together outdoors, increasing their exposure to cold and illness.","vi":"Khi thiếu nơi ở đầy đủ, các gia đình phải di dời có thể phải quây quần bên ngoài trời, làm tăng nguy cơ bị nhiễm lạnh và bệnh tật.","audioKind":"ex2"}],"collocations":[{"en":"huddle together","vi":"chụm lại với nhau"},{"en":"huddle for warmth","vi":"quây quần sưởi ấm"},{"en":"huddle around a fire","vi":"vây quanh đống lửa"},{"en":"a team huddle","vi":"cuộc họp nhóm nhanh"}],"wordFamily":[],"synonyms":["cluster"],"antonyms":[],"tipVi":"huddle nhấn mạnh sự áp sát chặt, thường dùng để giữ ấm, tránh nguy hiểm hoặc bàn bạc riêng tư.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_keyhole', 'en-b2-79', 'keyhole', '/ˈkiːhoʊl/', 'B2', 'lỗ khóa; ổ khóa', 'n.', NULL, NULL, 'Cụm keyhole surgery chỉ phẫu thuật nội soi (qua vết rạch nhỏ), không dịch là phẫu thuật lỗ khóa.', 'I struggled to find the keyhole in the dark.', NULL, 'Tôi đã chật vật tìm lỗ khóa trong bóng tối.', '{"wordId":"keyhole","ukIpa":"/ˈkiːhəʊl/","usIpa":"/ˈkiːhoʊl/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"a hole in a lock into which a key fits","vi":"lỗ khóa; ổ khóa"}],"examples":[{"en":"I struggled to find the keyhole in the dark.","vi":"Tôi đã chật vật tìm lỗ khóa trong bóng tối.","audioKind":"ex"},{"en":"Modern electronic locks remove the need for a traditional keyhole, although they may create new security risks.","vi":"Các loại khóa điện tử hiện đại loại bỏ nhu cầu sử dụng lỗ khóa truyền thống, dù chúng có thể làm phát sinh những rủi ro an ninh mới.","audioKind":"ex2"}],"collocations":[{"en":"put a key in the keyhole","vi":"đút chìa khóa vào ổ khóa"},{"en":"look through the keyhole","vi":"nhìn qua lỗ khóa"},{"en":"keyhole surgery","vi":"phẫu thuật nội soi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm keyhole surgery chỉ phẫu thuật nội soi (qua vết rạch nhỏ), không dịch là phẫu thuật lỗ khóa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_meantime', 'en-b2-79', 'meantime', '/ˈmiːntaɪm/', 'B2', 'thời gian giữa lúc; lúc đó; trong lúc đó; trong khi chờ đợi', 'n.', NULL, 'Đồng nghĩa: meanwhile', 'Cụm phổ biến nhất là in the meantime; meanwhile có thể dùng trực tiếp như một trạng từ.', 'Dinner is cooking; in the meantime, let''s set the table.', NULL, 'Bữa tối đang được nấu; trong lúc đó, chúng ta hãy dọn bàn ăn nhé.', '{"wordId":"meantime","ukIpa":"/ˈmiːntaɪm/","usIpa":"/ˈmiːntaɪm/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"the period before something happens, especially in ''in the meantime''","vi":"thời gian giữa lúc; lúc đó"},{"pos":"adv.","en":"during the time before another event happens","vi":"trong lúc đó; trong khi chờ đợi"}],"examples":[{"en":"Dinner is cooking; in the meantime, let''s set the table.","vi":"Bữa tối đang được nấu; trong lúc đó, chúng ta hãy dọn bàn ăn nhé.","audioKind":"ex"},{"en":"The new railway will take years to complete; in the meantime, cities should improve existing bus services.","vi":"Tuyến đường sắt mới sẽ mất nhiều năm để hoàn thành; trong thời gian đó, các thành phố nên cải thiện các dịch vụ xe buýt hiện có.","audioKind":"ex2"}],"collocations":[{"en":"in the meantime","vi":"trong thời gian đó"},{"en":"meantime, continue working","vi":"trong lúc đó, tiếp tục làm việc"}],"wordFamily":[],"synonyms":["meanwhile"],"antonyms":[],"tipVi":"Cụm phổ biến nhất là in the meantime; meanwhile có thể dùng trực tiếp như một trạng từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_creep', 'en-b2-79', 'creep', '/kriːp/', 'B2', 'đión rén; di chuyển rón rén; lan dần; trườn tới; âm thầm tăng lên', 'v.', NULL, 'Đồng nghĩa: sneak, tiptoe', 'Dạng quá khứ và quá khứ phân từ đều là crept; từ này không nhất thiết chỉ việc bò/trườn.', 'I crept upstairs to avoid waking the sleeping baby.', NULL, 'Tôi rón rén bước lên gác để tránh làm thức giấc đứa trẻ đang ngủ.', '{"wordId":"creep","ukIpa":"/kriːp/","usIpa":"/kriːp/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to move slowly and quietly, often to avoid being noticed","vi":"đión rén; di chuyển rón rén"},{"pos":"v.","en":"to spread or change slowly and almost unnoticed","vi":"lan dần; trườn tới; âm thầm tăng lên"}],"examples":[{"en":"I crept upstairs to avoid waking the sleeping baby.","vi":"Tôi rón rén bước lên gác để tránh làm thức giấc đứa trẻ đang ngủ.","audioKind":"ex"},{"en":"Housing costs can creep up gradually, placing increasing financial pressure on families with limited incomes.","vi":"Chi phí nhà ở có thể tăng dần lên, tạo áp lực tài chính ngày càng lớn cho các gia đình có thu nhập hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"creep upstairs","vi":"rón rén lên gác"},{"en":"creep up","vi":"tăng dần"},{"en":"creep into","vi":"luồn lách vào"},{"en":"give someone the creeps","vi":"làm ai đó nổi da gà"}],"wordFamily":[],"synonyms":["sneak","tiptoe"],"antonyms":[],"tipVi":"Dạng quá khứ và quá khứ phân từ đều là crept; từ này không nhất thiết chỉ việc bò/trườn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_caution', 'en-b2-79', 'caution', '/ˈkɔːʃən/', 'B2', 'sự cẩn trọng; sự thận trọng; lời cảnh báo; lời răn đe; cảnh báo; nhắc nhở', 'n.', 'cautious (adj.), cautiously (adv.), cautionary (adj.)', NULL, 'caution against doing diễn đạt ý cảnh báo không nên làm điều gì đó.', 'We walked with caution across the wet kitchen floor.', NULL, 'Chúng tôi cẩn trọng bước qua sàn nhà bếp ướt.', '{"wordId":"caution","ukIpa":"/ˈkɔːʃən/","usIpa":"/ˈkɔːʃən/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"care taken to avoid danger or mistakes","vi":"sự cẩn trọng; sự thận trọng"},{"pos":"n.","en":"a warning about danger or unacceptable behaviour","vi":"lời cảnh báo; lời răn đe"},{"pos":"v.","en":"to warn someone about a risk or problem","vi":"cảnh báo; nhắc nhở"}],"examples":[{"en":"We walked with caution across the wet kitchen floor.","vi":"Chúng tôi cẩn trọng bước qua sàn nhà bếp ướt.","audioKind":"ex"},{"en":"Researchers caution that small studies may not provide reliable evidence for major changes in public health policy.","vi":"Các nhà nghiên cứu cảnh báo rằng các nghiên cứu quy mô nhỏ có thể không cung cấp bằng chứng đáng tin cậy cho những thay đổi lớn trong chính sách y tế công cộng.","audioKind":"ex2"}],"collocations":[{"en":"with caution","vi":"một cách cẩn trọng"},{"en":"exercise caution","vi":"thể hiện sự thận trọng"},{"en":"caution against","vi":"cảnh báo chống lại"}],"wordFamily":["cautious (adj.)","cautiously (adv.)","cautionary (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"caution against doing diễn đạt ý cảnh báo không nên làm điều gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_snap', 'en-b2-79', 'snap', '/snæp/', 'B2', 'gãy bẻ bộp; đứt phựt; nói cộc cằn; quát mắng; chụp ảnh; bấm máy', 'v.', 'snapping (adj.)', NULL, 'snap at someone thường chỉ việc nói giọng cáu kỉnh, đôi khi cũng chỉ việc chộp cắn ai đó.', 'The dry twig snapped when I stepped on it.', NULL, 'Cành cây khô gãy cái rộp khi tôi bước chân lên.', '{"wordId":"snap","ukIpa":"/snæp/","usIpa":"/snæp/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To break suddenly with a short, sharp sound.","vi":"gãy bẻ bộp; đứt phựt"},{"pos":"v.","en":"To speak suddenly in an angry or impatient way.","vi":"nói cộc cằn; quát mắng"},{"pos":"v.","en":"To take a photograph quickly.","vi":"chụp ảnh; bấm máy"}],"examples":[{"en":"The dry twig snapped when I stepped on it.","vi":"Cành cây khô gãy cái rộp khi tôi bước chân lên.","audioKind":"ex"},{"en":"Under constant workplace pressure, employees may snap at colleagues, damaging cooperation and reducing overall team productivity.","vi":"Dưới áp lực công việc liên tục, nhân viên có thể cáu gắt với đồng nghiệp, làm tổn hại đến sự hợp tác và giảm năng suất chung của đội nhóm.","audioKind":"ex2"}],"collocations":[{"en":"snap in half","vi":"gãy làm đôi"},{"en":"snap at someone","vi":"quát mắng ai đó"},{"en":"snap a photo","vi":"chụp một bức ảnh"}],"wordFamily":["snapping (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"snap at someone thường chỉ việc nói giọng cáu kỉnh, đôi khi cũng chỉ việc chộp cắn ai đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clumsy', 'en-b2-79', 'clumsy', '/ˈklʌm.zi/', 'B2', 'vụng về; lóng ngóng; xử lý kém tế nhị', 'adj.', 'clumsily (adv.), clumsiness (n.)', 'Đồng nghĩa: awkward · Trái nghĩa: graceful, skilful', 'Chủ yếu chỉ hành động hoặc cách xử lý vụng về, không đồng nghĩa với kém thông minh.', 'My clumsy puppy knocked a flowerpot off the shelf.', NULL, 'Chú cún vụng về của tôi đã hất rơi một chậu hoa khỏi kệ.', '{"wordId":"clumsy","ukIpa":"/ˈklʌm.zi/","usIpa":"/ˈklʌm.zi/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"moving awkwardly and often dropping or breaking things","vi":"vụng về; lóng ngóng"},{"pos":"adj.","en":"done without skill, care, or sensitivity","vi":"vụng về; xử lý kém tế nhị"}],"examples":[{"en":"My clumsy puppy knocked a flowerpot off the shelf.","vi":"Chú cún vụng về của tôi đã hất rơi một chậu hoa khỏi kệ.","audioKind":"ex"},{"en":"A clumsy attempt to explain new regulations can reduce public confidence in local government.","vi":"Một nỗ lực giải thích các quy định mới một cách vụng về có thể làm giảm niềm tin của công chúng vào chính quyền địa phương.","audioKind":"ex2"}],"collocations":[{"en":"clumsy movements","vi":"những cử động vụng về"},{"en":"a clumsy attempt","vi":"một nỗ lực vụng về"},{"en":"a clumsy apology","vi":"một lời xin lỗi thiếu khéo léo"}],"wordFamily":["clumsily (adv.)","clumsiness (n.)"],"synonyms":["awkward"],"antonyms":["graceful","skilful"],"tipVi":"Chủ yếu chỉ hành động hoặc cách xử lý vụng về, không đồng nghĩa với kém thông minh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_loosen', 'en-b2-79', 'loosen', '/ˈluːsən/', 'B2', 'nới lỏng; làm lỏng ra; nới rộng (quy định/kiểm soát)', 'v.', 'loose (adj.), loosely (adv.), looseness (n.)', 'Trái nghĩa: tighten', 'loosen là động từ; loose là tính từ, tránh nhầm lẫn với lose.', 'He loosened his scarf as the room grew warmer.', NULL, 'Anh ấy nới lỏng chiếc khăn choàng cổ khi căn phòng dần ấm lên.', '{"wordId":"loosen","ukIpa":"/ˈluːsən/","usIpa":"/ˈluːsən/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to make or become less tight or firmly attached","vi":"nới lỏng; làm lỏng ra"},{"pos":"v.","en":"to make rules or control less strict","vi":"nới lỏng; nới rộng (quy định/kiểm soát)"}],"examples":[{"en":"He loosened his scarf as the room grew warmer.","vi":"Anh ấy nới lỏng chiếc khăn choàng cổ khi căn phòng dần ấm lên.","audioKind":"ex"},{"en":"Governments may loosen restrictions on foreign investment to encourage business growth and create more employment opportunities.","vi":"Chính phủ có thể nới lỏng các hạn chế đối với đầu tư nước ngoài để thúc đẩy tăng trưởng doanh nghiệp và tạo thêm cơ hội việc làm.","audioKind":"ex2"}],"collocations":[{"en":"loosen a knot","vi":"tháo nút thắt"},{"en":"loosen your grip","vi":"nới lỏng tay cầm"},{"en":"loosen restrictions","vi":"nới lỏng các hạn chế"}],"wordFamily":["loose (adj.)","loosely (adv.)","looseness (n.)"],"synonyms":[],"antonyms":["tighten"],"tipVi":"loosen là động từ; loose là tính từ, tránh nhầm lẫn với lose.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scrape', 'en-b2-79', 'scrape', '/skreɪp/', 'B2', 'cạo; gạt; làm trầy xước; làm xước; vết trầy xước; vết xước', 'v.', 'scraper (n.), scraping (n.)', NULL, 'scrape off mang nghĩa cạo sạch đi; scrape through mang nghĩa vượt qua kỳ thi hoặc tình huống khó khăn một cách suýt soát.', 'I scraped the ice off the car window.', NULL, 'Tôi cạo lớp băng bám trên cửa kính ô tô.', '{"wordId":"scrape","ukIpa":"/skreɪp/","usIpa":"/skreɪp/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"rub a hard edge across a surface, often removing something","vi":"cạo; gạt"},{"pos":"v.","en":"damage skin or a surface by rubbing against something rough","vi":"làm trầy xước; làm xước"},{"pos":"n.","en":"a shallow injury or mark caused by rubbing","vi":"vết trầy xước; vết xước"}],"examples":[{"en":"I scraped the ice off the car window.","vi":"Tôi cạo lớp băng bám trên cửa kính ô tô.","audioKind":"ex"},{"en":"Restoration workers carefully scrape away damaged paint to reveal the original surfaces of historic buildings.","vi":"Các nhân viên phục chế cẩn thận cạo lớp sơn bị hỏng để làm lộ ra bề mặt ban đầu của các công trình lịch sử.","audioKind":"ex2"}],"collocations":[{"en":"scrape off paint","vi":"cạo sơn"},{"en":"scrape your knee","vi":"trầy đầu gối"},{"en":"scrape through an exam","vi":"thi đậu suýt soát"},{"en":"scrape together money","vi":"cố gắng gom góp tiền"}],"wordFamily":["scraper (n.)","scraping (n.)"],"synonyms":[],"antonyms":[],"tipVi":"scrape off mang nghĩa cạo sạch đi; scrape through mang nghĩa vượt qua kỳ thi hoặc tình huống khó khăn một cách suýt soát.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gradual', 'en-b2-79', 'gradual', '/ˈɡrædʒuəl/', 'B2', 'dần dần; từ từ; thoai thoải; dốc thoải', 'adj.', 'gradually (adv.)', 'Đồng nghĩa: progressive · Trái nghĩa: sudden, abrupt', 'Nhấn mạnh sự thay đổi diễn ra chậm rãi, theo từng giai đoạn; phó từ tương ứng là gradually.', 'There was a gradual improvement in her sleep.', NULL, 'Giấc ngủ của cô ấy đã có sự cải thiện dần theo thời gian.', '{"wordId":"gradual","ukIpa":"/ˈɡrædʒuəl/","usIpa":"/ˈɡrædʒuəl/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Happening slowly through small changes over time","vi":"dần dần; từ từ"},{"pos":"adj.","en":"Rising or falling gently rather than steeply","vi":"thoai thoải; dốc thoải"}],"examples":[{"en":"There was a gradual improvement in her sleep.","vi":"Giấc ngủ của cô ấy đã có sự cải thiện dần theo thời gian.","audioKind":"ex"},{"en":"A gradual transition to renewable energy can help communities adapt without causing sudden job losses.","vi":"Quá trình chuyển đổi dần sang năng lượng tái tạo có thể giúp các cộng đồng thích ứng mà không gây ra tình trạng mất việc làm đột ngột.","audioKind":"ex2"}],"collocations":[{"en":"gradual improvement","vi":"sự cải thiện dần dần"},{"en":"gradual change","vi":"sự thay đổi từ từ"},{"en":"a gradual slope","vi":"con dốc thoai thoải"}],"wordFamily":["gradually (adv.)"],"synonyms":["progressive"],"antonyms":["sudden","abrupt"],"tipVi":"Nhấn mạnh sự thay đổi diễn ra chậm rãi, theo từng giai đoạn; phó từ tương ứng là gradually.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tickle', 'en-b2-79', 'tickle', '/ˈtɪkəl/', 'B2', 'cù; làm nhột; làm ai đó buồn cười; làm ai đó thích thú; cảm giác ngứa nhẹ', 'v.', 'ticklish (adj.)', NULL, 'tickle chỉ hành động cù làm nhột; scratch thường chỉ dùng móng tay để gãi.', 'The kitten''s whiskers tickled my wrist as it sniffed.', NULL, 'Bộ râu của chú mèo cọ vào cổ tay tôi khi nó ngửi ngửi.', '{"wordId":"tickle","ukIpa":"/ˈtɪkəl/","usIpa":"/ˈtɪkəl/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"touch someone lightly, causing laughter or an itchy feeling","vi":"cù; làm nhột"},{"pos":"v.","en":"amuse someone or pleasantly interest them","vi":"làm ai đó buồn cười; làm ai đó thích thú"},{"pos":"n.","en":"a slight itchy feeling in part of the body","vi":"cảm giác ngứa nhẹ"}],"examples":[{"en":"The kitten''s whiskers tickled my wrist as it sniffed.","vi":"Bộ râu của chú mèo cọ vào cổ tay tôi khi nó ngửi ngửi.","audioKind":"ex"},{"en":"Humorous advertisements often tickle viewers while making ordinary household products seem more appealing to potential buyers.","vi":"Các quảng cáo hài hước thường làm người xem thích thú, đồng thời khiến các sản phẩm gia dụng thông thường trở nên hấp dẫn hơn đối với người mua tiềm năng.","audioKind":"ex2"}],"collocations":[{"en":"tickle someone''s feet","vi":"cù chân ai đó"},{"en":"tickle someone''s fancy","vi":"gãi đúng chỗ ngứa; làm ai đó hào hứng"},{"en":"a tickle in the throat","vi":"cảm giác ngứa ở cổ họng"}],"wordFamily":["ticklish (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"tickle chỉ hành động cù làm nhột; scratch thường chỉ dùng móng tay để gãi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_79_1', 'en-b2-79', 'Cách dùng “lighten” (v.) — làm nhẹ đi; giảm bớt gánh nặng', 'lighten the load  ·  lighten the mood  ·  lighten a colour', 'Động từ "lighten" có thể chỉ việc giảm tải trọng hoặc làm sáng lên; cụm "lighten up" thường mang nghĩa thư giãn, thoải mái hơn.', 'Họ từ (Word Family): light (adj.), lightness (n.)', '[{"hanzi":"I removed two books to lighten my backpack.","pinyin":"","meaning":"Tôi lấy bớt hai cuốn sách ra để làm cho balo nhẹ hơn."},{"hanzi":"Employers can lighten staff workloads by simplifying administrative procedures and providing better tools for routine tasks.","pinyin":"","meaning":"Người sử dụng lao động có thể giảm bớt gánh nặng công việc cho nhân viên bằng cách đơn giản hóa các thủ tục hành chính và cung cấp các công cụ tốt hơn cho công việc thường ngày."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_79_2', 'en-b2-79', 'Cách dùng “scrape” (v.) — cạo; gạt', 'scrape off paint  ·  scrape your knee  ·  scrape through an exam', 'scrape off mang nghĩa cạo sạch đi; scrape through mang nghĩa vượt qua kỳ thi hoặc tình huống khó khăn một cách suýt soát.', 'Họ từ (Word Family): scraper (n.), scraping (n.)', '[{"hanzi":"I scraped the ice off the car window.","pinyin":"","meaning":"Tôi cạo lớp băng bám trên cửa kính ô tô."},{"hanzi":"Restoration workers carefully scrape away damaged paint to reveal the original surfaces of historic buildings.","pinyin":"","meaning":"Các nhân viên phục chế cẩn thận cạo lớp sơn bị hỏng để làm lộ ra bề mặt ban đầu của các công trình lịch sử."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_79_3', 'en-b2-79', 'Cách dùng “dent” (n.) — vết lõm', 'a dent in  ·  dent someone''s confidence  ·  make a dent in', 'dent không phải là "răng"; make a dent in có thể chỉ việc giảm bớt gánh nặng hoặc đạt bước tiến ban đầu.', 'Họ từ (Word Family): dented (adj.) | Đồng nghĩa: indentation', '[{"hanzi":"My bike has a dent in its metal basket.","pinyin":"","meaning":"Giỏ kim loại của chiếc xe đạp tôi bị một vết lõm."},{"hanzi":"Repeated delays in public transport can dent passengers'' confidence and encourage greater reliance on private cars.","pinyin":"","meaning":"Tình trạng phương tiện công cộng liên tục chậm chuyến có thể làm giảm niềm tin của hành khách và thúc đẩy việc phụ thuộc nhiều hơn vào xe hơi cá nhân."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_79_4', 'en-b2-79', 'Cách dùng “possess” (v.) — sở hữu; có', 'possess skills  ·  possess knowledge  ·  possess property', 'Mang tính trang trọng hơn have; thường không dùng ở thì tiếp diễn. Cần chú ý từ này có bốn chữ s.', 'Họ từ (Word Family): possession (n.), possessor (n.), possessive (adj.) | Đồng nghĩa: own, have · Trái nghĩa: lack', '[{"hanzi":"My uncle possesses a remarkable collection of antique clocks.","pinyin":"","meaning":"Chú tôi sở hữu một bộ sưu tập đồng hồ cổ vô cùng ấn tượng."},{"hanzi":"Graduates who possess strong communication skills are often better prepared to adapt to changing workplace demands.","pinyin":"","meaning":"Những sinh viên sở hữu kỹ năng giao tiếp tốt thường có sự chuẩn bị tốt hơn để thích ứng với các yêu cầu thay đổi của nơi làm việc."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_79_1', 'en-b2-79', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
