INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_79_1_8', 'ten_b2_79_1', 'possess', 'My uncle possesses a remarkable collection of antique clocks.', 'My uncle possesses a remarkable collection of antique clocks.', '/pəˈzes/', 'Chú tôi sở hữu một bộ sưu tập đồng hồ cổ vô cùng ấn tượng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_79_1_1', 'en-b2-79', 'ten_b2_79_1', 'listening', 'listening', 'The coldness of the water made me gasp.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi cẩn trọng bước qua sàn nhà bếp ướt.","Tôi đã chật vật tìm lỗ khóa trong bóng tối.","Tôi lấy bớt hai cuốn sách ra để làm cho balo nhẹ hơn.","Nước lạnh cóng khiến tôi phải há hốc mồm vì buốt."]'::jsonb, 3, 'The coldness of the water made me gasp. → Nước lạnh cóng khiến tôi phải há hốc mồm vì buốt.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_79_1_2', 'en-b2-79', 'ten_b2_79_1', 'listening', 'listening', 'We enjoy an occasional picnic beside the river.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi thích những buổi đi dã ngoại thỉnh thoảng bên bờ sông.","Cành cây khô gãy cái rộp khi tôi bước chân lên.","Tôi đã chật vật tìm lỗ khóa trong bóng tối.","Tôi lấy bớt hai cuốn sách ra để làm cho balo nhẹ hơn."]'::jsonb, 0, 'We enjoy an occasional picnic beside the river. → Chúng tôi thích những buổi đi dã ngoại thỉnh thoảng bên bờ sông.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_79_1_3', 'en-b2-79', 'ten_b2_79_1', 'listening', 'listening', 'Her bright scarf makes a striking contrast with her coat.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi đạp xe song song với chị gái dọc theo bờ sông.","Chú cún vụng về của tôi đã hất rơi một chậu hoa khỏi kệ.","Sự biến mất của chùm chìa khóa khiến tôi lại đến muộn.","Chiếc khăn quàng cổ sáng màu của cô ấy tạo nên sự tương phản nổi bật với chiếc áo khoác."]'::jsonb, 3, 'Her bright scarf makes a striking contrast with her coat. → Chiếc khăn quàng cổ sáng màu của cô ấy tạo nên sự tương phản nổi bật với chiếc áo khoác.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_79_2', 'en-b2-79', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_79_2_1', 'ten_b2_79_2', 'coldness', 'The apparent coldness of online communication can make it harder for remote workers to build trusting relationships.', 'The apparent coldness of online communication can make it harder for remote workers to build trusting relationships.', '/ˈkoʊldnəs/', 'Sự lạnh nhạt bề ngoài trong giao tiếp trực tuyến có thể khiến các nhân viên làm việc từ xa khó xây dựng mối quan hệ tin tưởng hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_79_2_2', 'ten_b2_79_2', 'occasional', 'Even occasional access to green spaces can improve the wellbeing of people living in crowded cities.', 'Even occasional access to green spaces can improve the wellbeing of people living in crowded cities.', '/əˈkeɪʒənəl/', 'Ngay cả việc thỉnh thoảng tiếp cận với không gian xanh cũng có thể cải thiện sức khỏe tinh thần của những người sống ở các thành phố đông đúc.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_79_2_3', 'ten_b2_79_2', 'striking', 'The survey revealed striking differences in access to public transport between urban and rural communities.', 'The survey revealed striking differences in access to public transport between urban and rural communities.', '/ˈstraɪkɪŋ/', 'Cuộc khảo sát cho thấy những khác biệt rõ rệt về khả năng tiếp cận giao thông công cộng giữa các cộng đồng thành thị và nông thôn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_79_2_4', 'ten_b2_79_2', 'curl', 'During prolonged droughts, leaves may curl to reduce water loss and protect plants from further damage.', 'During prolonged droughts, leaves may curl to reduce water loss and protect plants from further damage.', '/kɜːrl/', 'Trong những đợt hạn hán kéo dài, lá cây có thể cuộn lại để giảm thoát hơi nước và bảo vệ cây khỏi hư hại thêm.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_79_2_5', 'ten_b2_79_2', 'dent', 'Repeated delays in public transport can dent passengers'' confidence and encourage greater reliance on private cars.', 'Repeated delays in public transport can dent passengers'' confidence and encourage greater reliance on private cars.', '/dent/', 'Tình trạng phương tiện công cộng liên tục chậm chuyến có thể làm giảm niềm tin của hành khách và thúc đẩy việc phụ thuộc nhiều hơn vào xe hơi cá nhân.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_79_2_6', 'ten_b2_79_2', 'alongside', 'Schools should teach practical skills alongside academic subjects to prepare students for adult life.', 'Schools should teach practical skills alongside academic subjects to prepare students for adult life.', '/əˌlɔːŋˈsaɪd/', 'Nhà trường nên giảng dạy các kỹ năng thực tế song song với các môn học thuật để chuẩn bị cho học sinh bước vào đời.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_79_2_1', 'en-b2-79', 'ten_b2_79_2', 'listening', 'listening', 'The apparent coldness of online communication can make it harder for remote workers to build trusting relationships.', NULL, 'Trong câu vừa nghe, từ “coldness” mang nghĩa nào sau đây?', '["làm rõ; giải thích","sự hiếu khách; lòng mến khách","đi cùng; hộ tống; đồng hành","sự lạnh giá; tính hàn"]'::jsonb, 3, '“coldness” (/ˈkoʊldnəs/): sự lạnh giá; tính hàn. Câu đầy đủ: The apparent coldness of online communication can make it harder for remote workers to build trusting relationships.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_79_2_2', 'en-b2-79', 'ten_b2_79_2', 'listening', 'listening', 'Even occasional access to green spaces can improve the wellbeing of people living in crowded cities.', NULL, 'Trong câu vừa nghe, từ “occasional” mang nghĩa nào sau đây?', '["thực sự; đích thực","thỉnh thoảng; đôi khi; không thường xuyên","việc; sự kiện; vấn đề","vũ khí, trang thiết bị quân sự"]'::jsonb, 1, '“occasional” (/əˈkeɪʒənəl/): thỉnh thoảng; đôi khi; không thường xuyên. Câu đầy đủ: Even occasional access to green spaces can improve the wellbeing of people living in crowded cities.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
