INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_b2_79_1', 'en-b2-79', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “coldness” (/ˈkoʊldnəs/) có nghĩa là gì?', '["rất ít; tối thiểu; ở mức thấp nhất","sự lạnh giá; tính hàn","vết lõm","gãy bẻ bộp; đứt phựt"]'::jsonb, 1, '“coldness” (n.): sự lạnh giá; tính hàn; sự lạnh nhạt; sự thờ ơ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
