INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_79_2', 'en-b2-79', NULL, 'comprehensive_test', 'listening', 'We enjoy an occasional picnic beside the river.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đạp xe song song với chị gái dọc theo bờ sông.","Giỏ kim loại của chiếc xe đạp tôi bị một vết lõm.","Những loài cây này cần rất ít sự chăm sóc, ngay cả trong thời tiết nắng nóng.","Chúng tôi thích những buổi đi dã ngoại thỉnh thoảng bên bờ sông."]'::jsonb, 3, 'We enjoy an occasional picnic beside the river. → Chúng tôi thích những buổi đi dã ngoại thỉnh thoảng bên bờ sông.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_79_3', 'en-b2-79', NULL, 'comprehensive_test', 'listening', 'striking', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đòi hỏi nhiều nỗ lực; khắt khe; vất vả","điều khoản; điều mục trong văn bản pháp lý","nổi bật; gây ấn tượng mạnh; rõ rệt","giường tầng; giường nằm (trên tàu, xe)"]'::jsonb, 2, 'striking (/ˈstraɪkɪŋ/) → nổi bật; gây ấn tượng mạnh; rõ rệt', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_79_4', 'en-b2-79', NULL, 'comprehensive_test', 'listening', 'The dry leaves curl at the edges in autumn.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những chiếc lá khô cuộn lại ở phần mép vào mùa thu.","Một mùi lạ bay ra từ thùng rác trong nhà bếp.","Bộ râu của chú mèo cọ vào cổ tay tôi khi nó ngửi ngửi.","Anh ấy xách một chiếc đèn lồng đi dọc theo con đường mòn tối tăm trong vườn."]'::jsonb, 0, 'The dry leaves curl at the edges in autumn. → Những chiếc lá khô cuộn lại ở phần mép vào mùa thu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
