INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_79_6', 'en-b2-79', NULL, 'comprehensive_test', 'listening', 'I cycled alongside my sister by the river.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hãy để bơ ở ngoài tủ lạnh cho mềm ra.","Chiếc khăn quàng cổ sáng màu của cô ấy tạo nên sự tương phản nổi bật với chiếc áo khoác.","Tôi đạp xe song song với chị gái dọc theo bờ sông.","Anh ấy nới lỏng chiếc khăn choàng cổ khi căn phòng dần ấm lên."]'::jsonb, 2, 'I cycled alongside my sister by the river. → Tôi đạp xe song song với chị gái dọc theo bờ sông.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
