INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_79_18', 'en-b2-79', NULL, 'comprehensive_test', 'reading', NULL, 'The apparent coldness of online communication can make it harder for remote workers to build trusting relationships.', 'Dựa vào câu trên, từ “coldness” có nghĩa phù hợp nhất là gì?', '["kỳ thực tập, công việc thực tập","nhìn chằm chằm; chăm chú","ngón trỏ","sự lạnh giá; tính hàn"]'::jsonb, 3, 'coldness: sự lạnh giá; tính hàn; sự lạnh nhạt; sự thờ ơ. Dịch cả câu: Sự lạnh nhạt bề ngoài trong giao tiếp trực tuyến có thể khiến các nhân viên làm việc từ xa khó xây dựng mối quan hệ tin tưởng hơn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_79_19', 'en-b2-79', NULL, 'comprehensive_test', 'reading', NULL, 'Even occasional access to green spaces can improve the wellbeing of people living in crowded cities.', 'Dựa vào câu trên, từ “occasional” có nghĩa phù hợp nhất là gì?', '["chế độ dân chủ; nền dân chủ","đỉnh núi; đỉnh cao","thỉnh thoảng; đôi khi; không thường xuyên","nằm ngang; song song với mặt đất"]'::jsonb, 2, 'occasional: thỉnh thoảng; đôi khi; không thường xuyên. Dịch cả câu: Ngay cả việc thỉnh thoảng tiếp cận với không gian xanh cũng có thể cải thiện sức khỏe tinh thần của những người sống ở các thành phố đông đúc.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_79_20', 'en-b2-79', NULL, 'comprehensive_test', 'reading', NULL, 'The survey revealed striking differences in access to public transport between urban and rural communities.', 'Dựa vào câu trên, từ “striking” có nghĩa phù hợp nhất là gì?', '["nổi bật; gây ấn tượng mạnh; rõ rệt","đi cùng; hộ tống; đồng hành","gỗ xây dựng; gỗ nguyên liệu","động từ: nghi ngờ; phỏng đoán"]'::jsonb, 0, 'striking: nổi bật; gây ấn tượng mạnh; rõ rệt. Dịch cả câu: Cuộc khảo sát cho thấy những khác biệt rõ rệt về khả năng tiếp cận giao thông công cộng giữa các cộng đồng thành thị và nông thôn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_79_21', 'en-b2-79', NULL, 'comprehensive_test', 'reading', NULL, 'During prolonged droughts, leaves may curl to reduce water loss and protect plants from further damage.', 'Dựa vào câu trên, từ “curl” có nghĩa phù hợp nhất là gì?', '["lấp lánh; chiếu sáng rực rỡ","sai lầm; hiểu lầm","gia hạn; làm mới","cuộn lại; uốn xoăn; làm cong"]'::jsonb, 3, 'curl: cuộn lại; uốn xoăn; làm cong; lọn tóc xoăn; vật uốn cong. Dịch cả câu: Trong những đợt hạn hán kéo dài, lá cây có thể cuộn lại để giảm thoát hơi nước và bảo vệ cây khỏi hư hại thêm.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_79_22', 'en-b2-79', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cạo; gạt”', '["scrape","rotation","qualified","authentic"]'::jsonb, 0, 'cạo; gạt → scrape (/skreɪp/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_79_23', 'en-b2-79', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “dần dần; từ từ”', '["dealer","rooster","operator","gradual"]'::jsonb, 3, 'dần dần; từ từ → gradual (/ˈɡrædʒuəl/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_79_24', 'en-b2-79', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cù; làm nhột”', '["clarinet","crucial","tickle","incidentally"]'::jsonb, 2, 'cù; làm nhột → tickle (/ˈtɪkəl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-80', 'en', 'Bài 80: Đời sống hằng ngày (7) - CEFR B2', 'CEFR B2', 'B2 · Đời sống', '27 từ vựng Tiếng Anh CEFR B2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4080, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_excess', 'en-b2-80', 'excess', '/ɪkˈses/', 'B2', 'số lượng vượt mức; phần thừa; vượt mức; dư thừa', 'n.', 'excessive (adj.), excessively (adv.)', 'Đồng nghĩa: surplus · Trái nghĩa: shortage', 'in excess chỉ mức độ quá thừa; in excess of chỉ vượt quá một số lượng nhất định.', 'Wipe away the excess paint with a clean cloth.', NULL, 'Dùng khăn sạch lau sạch lớp sơn thừa đi.', '{"wordId":"excess","ukIpa":"/ɪkˈses/","usIpa":"/ɪkˈses/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"an amount greater than what is needed or allowed","vi":"số lượng vượt mức; phần thừa"},{"pos":"adj.","en":"more than is needed, usual, or allowed","vi":"vượt mức; dư thừa"}],"examples":[{"en":"Wipe away the excess paint with a clean cloth.","vi":"Dùng khăn sạch lau sạch lớp sơn thừa đi.","audioKind":"ex"},{"en":"Consuming sugar in excess can increase the risk of obesity and other health problems.","vi":"Tiêu thụ quá nhiều đường có thể làm tăng nguy cơ béo phì và các vấn đề sức khỏe khác.","audioKind":"ex2"}],"collocations":[{"en":"in excess","vi":"vượt mức; quá mức"},{"en":"excess baggage","vi":"hành lý quá cước"},{"en":"excess demand","vi":"nhu cầu vượt mức"},{"en":"an excess of","vi":"lượng quá nhiều của..."}],"wordFamily":["excessive (adj.)","excessively (adv.)"],"synonyms":["surplus"],"antonyms":["shortage"],"tipVi":"in excess chỉ mức độ quá thừa; in excess of chỉ vượt quá một số lượng nhất định.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_existing', 'en-b2-80', 'existing', '/ɪɡˈzɪstɪŋ/', 'B2', 'hiện có; đang tồn tại; sẵn có', 'adj.', 'exist (v.), existence (n.), existent (adj.)', 'Đồng nghĩa: current, present · Trái nghĩa: nonexistent', 'Thường đặt trước danh từ, nhấn mạnh đã tồn tại thay vì xây dựng mới hoặc bổ sung.', 'We kept the existing shelves and painted them blue.', NULL, 'Chúng tôi giữ lại những chiếc kệ có sẵn và sơn chúng thành màu xanh dương.', '{"wordId":"existing","ukIpa":"/ɪɡˈzɪstɪŋ/","usIpa":"/ɪɡˈzɪstɪŋ/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Already present or in use at a particular time.","vi":"hiện có; đang tồn tại; sẵn có"}],"examples":[{"en":"We kept the existing shelves and painted them blue.","vi":"Chúng tôi giữ lại những chiếc kệ có sẵn và sơn chúng thành màu xanh dương.","audioKind":"ex"},{"en":"Governments should improve existing transport networks before investing public money in entirely new infrastructure projects.","vi":"Chính phủ nên cải thiện các mạng lưới giao thông hiện có trước khi đầu tư vốn công vào các dự án cơ sở hạ tầng hoàn toàn mới.","audioKind":"ex2"}],"collocations":[{"en":"existing infrastructure","vi":"cơ sở hạ tầng hiện có"},{"en":"existing customers","vi":"khách hàng hiện tại"},{"en":"existing conditions","vi":"các điều kiện hiện hành"}],"wordFamily":["exist (v.)","existence (n.)","existent (adj.)"],"synonyms":["current","present"],"antonyms":["nonexistent"],"tipVi":"Thường đặt trước danh từ, nhấn mạnh đã tồn tại thay vì xây dựng mới hoặc bổ sung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_partially', 'en-b2-80', 'partially', '/ˈpɑːrʃəli/', 'B2', 'một phần; phần nào; không hoàn toàn', 'adv.', 'partial (adj.)', 'Đồng nghĩa: partly, incompletely · Trái nghĩa: completely, entirely', 'partially diễn tả ý không hoàn toàn; không nên nhầm lẫn với ý thiên vị.', 'The curtains were partially open, letting in sunlight.', NULL, 'Rèm cửa đang mở một phần, để ánh nắng chiếu vào.', '{"wordId":"partially","ukIpa":"/ˈpɑːʃəli/","usIpa":"/ˈpɑːrʃəli/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"to some extent, but not completely","vi":"một phần; phần nào; không hoàn toàn"}],"examples":[{"en":"The curtains were partially open, letting in sunlight.","vi":"Rèm cửa đang mở một phần, để ánh nắng chiếu vào.","audioKind":"ex"},{"en":"Although recycling can partially reduce waste, changes in production and consumption are also necessary.","vi":"Mặc dù việc tái chế có thể làm giảm rác thải phần nào, nhưng những thay đổi trong sản xuất và tiêu thụ cũng là điều cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"partially open","vi":"mở một phần"},{"en":"partially completed","vi":"hoàn thành một phần"},{"en":"partially responsible","vi":"chịu trách nhiệm một phần"}],"wordFamily":["partial (adj.)"],"synonyms":["partly","incompletely"],"antonyms":["completely","entirely"],"tipVi":"partially diễn tả ý không hoàn toàn; không nên nhầm lẫn với ý thiên vị.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wax', 'en-b2-80', 'wax', '/wæks/', 'B2', 'sáp; sáp nến; đánh sáp; thoa sáp; trăng tròn dần; sự sáng lên của mặt trăng', 'n.', 'waxy (adj.), waxing (n.)', NULL, 'wax khi mang nghĩa là sáp thường không đếm được; mặt trăng lớn dần trái nghĩa với wane.', 'Warm wax dripped from the candle onto the table.', NULL, 'Sáp ấm từ ngọn nến nhỏ giọt xuống mặt bàn.', '{"wordId":"wax","ukIpa":"/wæks/","usIpa":"/wæks/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A substance that melts easily, used for candles and protective coatings.","vi":"sáp; sáp nến"},{"pos":"v.","en":"To cover or polish something with wax.","vi":"đánh sáp; thoa sáp"},{"pos":"v.","en":"For the moon''s visible lit surface to gradually increase.","vi":"trăng tròn dần; sự sáng lên của mặt trăng"}],"examples":[{"en":"Warm wax dripped from the candle onto the table.","vi":"Sáp ấm từ ngọn nến nhỏ giọt xuống mặt bàn.","audioKind":"ex"},{"en":"A thin layer of wax can protect fresh fruit and reduce moisture loss during transport.","vi":"Một lớp sáp mỏng có thể bảo vệ trái cây tươi và giảm sự mất độ ẩm trong quá trình vận chuyển.","audioKind":"ex2"}],"collocations":[{"en":"candle wax","vi":"sáp nến"},{"en":"a layer of wax","vi":"một lớp sáp"},{"en":"wax the floor","vi":"đánh bóng sàn nhà bằng sáp"},{"en":"wax and wane","vi":"chu kỳ thịnh suy; lúc trăng tròn lúc trăng khuyết"}],"wordFamily":["waxy (adj.)","waxing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"wax khi mang nghĩa là sáp thường không đếm được; mặt trăng lớn dần trái nghĩa với wane.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sole', 'en-b2-80', 'sole', '/soʊl/', 'B2', 'duy nhất; đơn độc; lòng bàn chân; đế giày; cá bơn (loại cá biển dẹt thường dùng làm thực phẩm)', 'adj.', 'solely (adv.)', 'Đồng nghĩa: only, exclusive · Trái nghĩa: shared', 'Khi mang nghĩa "duy nhất", từ này thường đứng trước danh từ; đồng âm với "soul".', 'She is the sole owner of this little bakery.', NULL, 'Cô ấy là chủ sở hữu duy nhất của tiệm bánh nhỏ này.', '{"wordId":"sole","ukIpa":"/səʊl/","usIpa":"/soʊl/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Being the only one, with nobody or nothing else involved.","vi":"duy nhất; đơn độc"},{"pos":"n.","en":"The bottom surface of a foot or shoe.","vi":"lòng bàn chân; đế giày"},{"pos":"n.","en":"A flat sea fish commonly eaten as food.","vi":"cá bơn (loại cá biển dẹt thường dùng làm thực phẩm)"}],"examples":[{"en":"She is the sole owner of this little bakery.","vi":"Cô ấy là chủ sở hữu duy nhất của tiệm bánh nhỏ này.","audioKind":"ex"},{"en":"Economic growth should not be the sole measure of a country''s progress or public wellbeing.","vi":"Tăng trưởng kinh tế không nên là thước đo duy nhất cho sự tiến bộ của một quốc gia hay phúc lợi cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"the sole reason","vi":"lý do duy nhất"},{"en":"sole responsibility","vi":"trách nhiệm hoàn toàn"},{"en":"the sole of a shoe","vi":"đế giày"}],"wordFamily":["solely (adv.)"],"synonyms":["only","exclusive"],"antonyms":["shared"],"tipVi":"Khi mang nghĩa \"duy nhất\", từ này thường đứng trước danh từ; đồng âm với \"soul\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gasp', 'en-b2-80', 'gasp', '/ɡæsp/', 'B2', 'há hốc mồm (vì kinh ngạc); thở hổn hển; tiếng thở hắt ra; tiếng kêu kinh ngạc', 'v.', NULL, NULL, '"gasp" nhấn mạnh việc hít vào đột ngột; "pant" thường chỉ việc thở dốc liên tục.', 'We gasped as the whale rose beside our boat.', NULL, 'Chúng tôi há hốc kinh ngạc khi con cá voi trồi lên bên cạnh thuyền.', '{"wordId":"gasp","ukIpa":"/ɡɑːsp/","usIpa":"/ɡæsp/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"breathe in suddenly or struggle to breathe","vi":"há hốc mồm (vì kinh ngạc); thở hổn hển"},{"pos":"n.","en":"a sudden, short intake of breath","vi":"tiếng thở hắt ra; tiếng kêu kinh ngạc"}],"examples":[{"en":"We gasped as the whale rose beside our boat.","vi":"Chúng tôi há hốc kinh ngạc khi con cá voi trồi lên bên cạnh thuyền.","audioKind":"ex"},{"en":"Runners may gasp for breath when exercising at high altitudes, where less oxygen is available.","vi":"Người chạy bộ có thể phải thở hổn hển khi tập luyện ở vùng núi cao, nơi có ít oxy hơn.","audioKind":"ex2"}],"collocations":[{"en":"gasp for breath","vi":"thở hổn hển"},{"en":"gasp in surprise","vi":"há hốc kinh ngạc"},{"en":"let out a gasp","vi":"thốt lên một tiếng kinh ngạc"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"\"gasp\" nhấn mạnh việc hít vào đột ngột; \"pant\" thường chỉ việc thở dốc liên tục.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_irregular', 'en-b2-80', 'irregular', '/ɪˈreɡjələr/', 'B2', 'không đều; không theo quy tắc; không cố định; thất thường; bất quy tắc (ngữ pháp)', 'adj.', 'regular (adj.), irregularly (adv.), irregularity (n.)', 'Đồng nghĩa: uneven, erratic · Trái nghĩa: regular', 'Có thể dùng để miêu tả cả hình dạng lẫn thời gian; cũng dùng cho động từ bất quy tắc.', 'The path was made from stones of irregular shapes.', NULL, 'Con đường được lát bằng những viên đá có hình dạng không đều.', '{"wordId":"irregular","ukIpa":"/ɪˈreɡjələ/","usIpa":"/ɪˈreɡjələr/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Not having an even shape or a regular pattern.","vi":"không đều; không theo quy tắc"},{"pos":"adj.","en":"Not happening at fixed or predictable times.","vi":"không cố định; thất thường"},{"pos":"adj.","en":"Not following the usual rules for changing grammatical forms.","vi":"bất quy tắc (ngữ pháp)"}],"examples":[{"en":"The path was made from stones of irregular shapes.","vi":"Con đường được lát bằng những viên đá có hình dạng không đều.","audioKind":"ex"},{"en":"Working irregular hours can disrupt sleep patterns and make it harder for employees to maintain healthy routines.","vi":"Làm việc theo giờ giấc thất thường có thể làm gián đoạn nhịp ngủ và khiến nhân viên khó duy trì thói quen sinh hoạt lành mạnh hơn.","audioKind":"ex2"}],"collocations":[{"en":"irregular shapes","vi":"hình dạng không đều"},{"en":"irregular hours","vi":"giờ giấc thất thường"},{"en":"irregular verbs","vi":"động từ bất quy tắc"},{"en":"an irregular heartbeat","vi":"nhịp tim không đều"}],"wordFamily":["regular (adj.)","irregularly (adv.)","irregularity (n.)"],"synonyms":["uneven","erratic"],"antonyms":["regular"],"tipVi":"Có thể dùng để miêu tả cả hình dạng lẫn thời gian; cũng dùng cho động từ bất quy tắc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_loose', 'en-b2-80', 'loose', '/luːs/', 'B2', 'lỏng lẻo; lỏng; chưa được cố định; rộng rãi (quần áo); không chặt chẽ; không nghiêm ngặt', 'adj.', 'loosely (adv.), loosen (v.), looseness (n.)', 'Trái nghĩa: tight, secure', 'loose là tính từ với âm cuối /s/; lose là động từ với âm cuối /z/.', 'One loose screw made the whole chair feel shaky.', NULL, 'Một con ốc lỏng lẻo đã làm cho cả chiếc ghế trở nên chòng chành.', '{"wordId":"loose","ukIpa":"/luːs/","usIpa":"/luːs/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"not firmly attached or held in place","vi":"lỏng lẻo; lỏng; chưa được cố định"},{"pos":"adj.","en":"not fitting closely around the body","vi":"rộng rãi (quần áo)"},{"pos":"adj.","en":"not exact or strictly controlled","vi":"không chặt chẽ; không nghiêm ngặt"}],"examples":[{"en":"One loose screw made the whole chair feel shaky.","vi":"Một con ốc lỏng lẻo đã làm cho cả chiếc ghế trở nên chòng chành.","audioKind":"ex"},{"en":"Loose regulations on industrial waste can allow harmful substances to enter rivers and damage local ecosystems.","vi":"Quy định lỏng lẻo đối với chất thải công nghiệp có thể cho phép các chất độc hại xâm nhập vào sông ngòi và phá hủy hệ sinh thái địa phương.","audioKind":"ex2"}],"collocations":[{"en":"loose screw","vi":"ốc vít lỏng"},{"en":"loose clothing","vi":"quần áo rộng rãi"},{"en":"loose connection","vi":"mối nối lỏng lẻo"},{"en":"break loose","vi":"xổng chuồng; tự do"}],"wordFamily":["loosely (adv.)","loosen (v.)","looseness (n.)"],"synonyms":[],"antonyms":["tight","secure"],"tipVi":"loose là tính từ với âm cuối /s/; lose là động từ với âm cuối /z/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stumble', 'en-b2-80', 'stumble', '/ˈstʌmbəl/', 'B2', 'vấp ngã; lạng quạng; vấp váp; nói lắp bắp', 'v.', 'stumbling (adj.)', 'Đồng nghĩa: trip, falter', 'stumble không nhất thiết phải ngã; stumble across có nghĩa là tình cờ phát hiện.', 'I stumbled over a loose stone on the garden path.', NULL, 'Tôi bị vấp phải một hòn sỏi lỏng trên lối đi trong vườn.', '{"wordId":"stumble","ukIpa":"/ˈstʌmbəl/","usIpa":"/ˈstʌmbəl/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To trip or briefly lose balance while walking or running","vi":"vấp ngã; lạng quạng"},{"pos":"v.","en":"To hesitate or make mistakes while speaking","vi":"vấp váp; nói lắp bắp"}],"examples":[{"en":"I stumbled over a loose stone on the garden path.","vi":"Tôi bị vấp phải một hòn sỏi lỏng trên lối đi trong vườn.","audioKind":"ex"},{"en":"Students may stumble over unfamiliar words during presentations, but regular practice can improve their confidence.","vi":"Học sinh có thể vấp váp trước những từ không quen thuộc trong các bài thuyết trình, nhưng việc luyện tập thường xuyên có thể nâng cao sự tự tin của các em.","audioKind":"ex2"}],"collocations":[{"en":"stumble over a stone","vi":"vấp phải một hòn đá"},{"en":"stumble over words","vi":"vấp váp khi nói"},{"en":"stumble across something","vi":"tình cờ phát hiện ra điều gì"}],"wordFamily":["stumbling (adj.)"],"synonyms":["trip","falter"],"antonyms":[],"tipVi":"stumble không nhất thiết phải ngã; stumble across có nghĩa là tình cờ phát hiện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spontaneous', 'en-b2-80', 'spontaneous', '/spɑːnˈteɪniəs/', 'B2', 'tự phát; không lên kế hoạch trước; tự nhiên; ngẫu hứng', 'adj.', 'spontaneously (adv.), spontaneity (n.)', 'Đồng nghĩa: unplanned, impromptu · Trái nghĩa: planned, rehearsed', 'Nhấn mạnh tính không được sắp xếp trước, không đồng nghĩa với "vô thức".', 'We made a spontaneous trip to the beach yesterday.', NULL, 'Hôm qua chúng tôi có một chuyến đi biển ngẫu hứng.', '{"wordId":"spontaneous","ukIpa":"/spɒnˈteɪniəs/","usIpa":"/spɑːnˈteɪniəs/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Happening naturally without being planned or deliberately caused","vi":"tự phát; không lên kế hoạch trước"},{"pos":"adj.","en":"Acting freely on feelings rather than following plans","vi":"tự nhiên; ngẫu hứng"}],"examples":[{"en":"We made a spontaneous trip to the beach yesterday.","vi":"Hôm qua chúng tôi có một chuyến đi biển ngẫu hứng.","audioKind":"ex"},{"en":"Spontaneous conversations between colleagues can generate creative ideas that formal meetings sometimes fail to produce.","vi":"Các cuộc trò chuyện tự phát giữa các đồng nghiệp có thể khơi nguồn ý tưởng sáng tạo mà các cuộc họp chính thức đôi khi không mang lại được.","audioKind":"ex2"}],"collocations":[{"en":"spontaneous reaction","vi":"phản ứng tự phát"},{"en":"spontaneous applause","vi":"tràng pháo tay tự phát"},{"en":"spontaneous decision","vi":"quyết định ngẫu hứng"}],"wordFamily":["spontaneously (adv.)","spontaneity (n.)"],"synonyms":["unplanned","impromptu"],"antonyms":["planned","rehearsed"],"tipVi":"Nhấn mạnh tính không được sắp xếp trước, không đồng nghĩa với \"vô thức\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ounce', 'en-b2-80', 'ounce', '/aʊns/', 'B2', 'ao-xơ; đơn vị đo khối lượng; một chút; một lượng rất nhỏ', 'n.', NULL, NULL, 'Ounce đo trọng lượng bằng khoảng 28.35 gam; fluid ounce là đơn vị đo dung tích.', 'I added an ounce of butter to the pan.', NULL, 'Tôi đã thêm một ao-xơ bơ vào chảo.', '{"wordId":"ounce","ukIpa":"/aʊns/","usIpa":"/aʊns/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A unit of weight equal to approximately 28.35 grams.","vi":"ao-xơ; đơn vị đo khối lượng"},{"pos":"n.","en":"A very small amount of something.","vi":"một chút; một lượng rất nhỏ"}],"examples":[{"en":"I added an ounce of butter to the pan.","vi":"Tôi đã thêm một ao-xơ bơ vào chảo.","audioKind":"ex"},{"en":"Athletes often need every ounce of determination to maintain demanding training schedules alongside their studies.","vi":"Các vận động viên thường cần từng chút ý quyết tâm để duy trì lịch tập luyện khắt khe bên cạnh việc học tập.","audioKind":"ex2"}],"collocations":[{"en":"an ounce of","vi":"một lượng nhỏ"},{"en":"every ounce of strength","vi":"hết sạch sức lực"},{"en":"not an ounce of","vi":"không có chút nào"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Ounce đo trọng lượng bằng khoảng 28.35 gam; fluid ounce là đơn vị đo dung tích.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bait', 'en-b2-80', 'bait', '/beɪt/', 'B2', 'mồi; mồi nhử; gắn mồi; đặt mồi; trêu chọc; khiêu khích', 'n.', NULL, 'Đồng nghĩa: lure', 'take the bait có thể dùng cho cá cắn câu hoặc nghĩa bóng là sập bẫy.', 'We used small pieces of bread as bait.', NULL, 'Chúng tôi dùng những miếng bánh mì nhỏ làm mồi câu.', '{"wordId":"bait","ukIpa":"/beɪt/","usIpa":"/beɪt/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"food or another attraction used to lure animals or people","vi":"mồi; mồi nhử"},{"pos":"v.","en":"to put food on a hook or in a trap","vi":"gắn mồi; đặt mồi"},{"pos":"v.","en":"to deliberately annoy someone to provoke a reaction","vi":"trêu chọc; khiêu khích"}],"examples":[{"en":"We used small pieces of bread as bait.","vi":"Chúng tôi dùng những miếng bánh mì nhỏ làm mồi câu.","audioKind":"ex"},{"en":"Some online advertisements use free gifts as bait to encourage consumers to share their personal information.","vi":"Một số quảng cáo trực tuyến sử dụng quà tặng miễn phí làm mồi nhử để khuyến khích người tiêu dùng chia sẻ thông tin cá nhân của họ.","audioKind":"ex2"}],"collocations":[{"en":"live bait","vi":"mồi sống"},{"en":"take the bait","vi":"cắn câu; sập bẫy"},{"en":"bait a hook","vi":"móc mồi vào lưỡi câu"}],"wordFamily":[],"synonyms":["lure"],"antonyms":[],"tipVi":"take the bait có thể dùng cho cá cắn câu hoặc nghĩa bóng là sập bẫy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_durable', 'en-b2-80', 'durable', '/ˈdʊrəbl/', 'B2', 'bền; bền bỉ; lâu bền; trường tồn', 'adj.', 'durability (n.), durably (adv.)', 'Đồng nghĩa: hard-wearing, long-lasting · Trái nghĩa: fragile', 'Hàng bền thường dùng danh từ số nhiều durables hoặc durable goods.', 'These durable boots have survived years of muddy walks.', NULL, 'Đôi bốt bền bỉ này đã cùng tôi qua nhiều năm đi dạo trong bùn đất.', '{"wordId":"durable","ukIpa":"/ˈdjʊərəbl/","usIpa":"/ˈdʊrəbl/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Able to last a long time without breaking or wearing out.","vi":"bền; bền bỉ"},{"pos":"adj.","en":"Likely to continue or remain effective for a long time.","vi":"lâu bền; trường tồn"}],"examples":[{"en":"These durable boots have survived years of muddy walks.","vi":"Đôi bốt bền bỉ này đã cùng tôi qua nhiều năm đi dạo trong bùn đất.","audioKind":"ex"},{"en":"Choosing durable products rather than disposable alternatives can reduce household waste and conserve valuable natural resources.","vi":"Lựa chọn các sản phẩm bền thay vì các sản phẩm dùng một lần có thể làm giảm rác thải sinh hoạt và bảo tồn các nguồn tài nguyên thiên nhiên quý giá.","audioKind":"ex2"}],"collocations":[{"en":"durable materials","vi":"chất liệu bền"},{"en":"durable goods","vi":"hàng hóa lâu bền"},{"en":"durable solution","vi":"giải pháp lâu dài"}],"wordFamily":["durability (n.)","durably (adv.)"],"synonyms":["hard-wearing","long-lasting"],"antonyms":["fragile"],"tipVi":"Hàng bền thường dùng danh từ số nhiều durables hoặc durable goods.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_skinny', 'en-b2-80', 'skinny', '/ˈskɪni/', 'B2', 'gầy gò; trơ xương; bó sát; ôm sát', 'adj.', 'skin (n.), skinniness (n.)', 'Đồng nghĩa: thin, scrawny · Trái nghĩa: plump', 'Khi miêu tả con người thường mang hàm ý chê bai; slim thường mang ý khen ngợi.', 'The skinny kitten curled up beside a warm blanket.', NULL, 'Chú mèo gầy gò cuộn tròn bên chiếc chăn ấm áp.', '{"wordId":"skinny","ukIpa":"/ˈskɪni/","usIpa":"/ˈskɪni/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"very thin, often in a way considered unattractive","vi":"gầy gò; trơ xương"},{"pos":"adj.","en":"fitting closely around the body, especially the legs","vi":"bó sát; ôm sát"}],"examples":[{"en":"The skinny kitten curled up beside a warm blanket.","vi":"Chú mèo gầy gò cuộn tròn bên chiếc chăn ấm áp.","audioKind":"ex"},{"en":"Media images that idealise skinny bodies can create unrealistic expectations and negatively affect young people''s confidence.","vi":"Hình ảnh trên phương tiện truyền thông lý tưởng hóa thân hình gầy gò có thể tạo ra những kỳ vọng phi thực tế và ảnh hưởng tiêu cực đến sự tự tin của giới trẻ.","audioKind":"ex2"}],"collocations":[{"en":"skinny jeans","vi":"quần jeans ôm sát"},{"en":"skinny legs","vi":"chân gầy"},{"en":"look skinny","vi":"trông gầy gò"}],"wordFamily":["skin (n.)","skinniness (n.)"],"synonyms":["thin","scrawny"],"antonyms":["plump"],"tipVi":"Khi miêu tả con người thường mang hàm ý chê bai; slim thường mang ý khen ngợi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_commonly', 'en-b2-80', 'commonly', '/ˈkɑːmənli/', 'B2', 'thường xuyên; phổ biến; hay', 'adv.', 'common (adj.), uncommon (adj.), commonness (n.)', 'Đồng nghĩa: often, frequently · Trái nghĩa: rarely, seldom', 'Thường đứng trước động từ chỉ hành động hoặc sau động từ to be, như is commonly used.', 'This spice is commonly used in soups and stews.', NULL, 'Loại gia vị này thường được sử dụng trong các món súp và món hầm.', '{"wordId":"commonly","ukIpa":"/ˈkɒmənli/","usIpa":"/ˈkɑːmənli/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"often or among many people or in many places","vi":"thường xuyên; phổ biến; hay"}],"examples":[{"en":"This spice is commonly used in soups and stews.","vi":"Loại gia vị này thường được sử dụng trong các món súp và món hầm.","audioKind":"ex"},{"en":"Although online learning is commonly viewed as convenient, its effectiveness depends on student motivation and access to reliable technology.","vi":"Mặc dù việc học trực tuyến thường được xem là tiện lợi, nhưng hiệu quả của nó lại phụ thuộc vào động lực học tập của học sinh và điều kiện công nghệ đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"commonly used","vi":"thường được sử dụng"},{"en":"commonly known as","vi":"thường được gọi là"},{"en":"commonly found","vi":"thường thấy"},{"en":"commonly believed","vi":"được cho là phổ biến"}],"wordFamily":["common (adj.)","uncommon (adj.)","commonness (n.)"],"synonyms":["often","frequently"],"antonyms":["rarely","seldom"],"tipVi":"Thường đứng trước động từ chỉ hành động hoặc sau động từ to be, như is commonly used.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rag', 'en-b2-80', 'rag', '/ræɡ/', 'B2', 'giẻ lau; vải vụn; quần áo rách rưới', 'n.', 'ragged (adj.)', 'Đồng nghĩa: cloth', 'Dạng số ít thường chỉ một miếng giẻ; in rags mang nghĩa là rách rưới, nghèo khổ.', 'He wiped the oily tools with an old rag.', NULL, 'Anh ấy lau các dụng cụ dính dầu mỡ bằng một chiếc giẻ lau cũ.', '{"wordId":"rag","ukIpa":"/ræɡ/","usIpa":"/ræɡ/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A piece of old cloth, often used for cleaning.","vi":"giẻ lau; vải vụn"},{"pos":"n.","en":"Old, badly torn clothes, usually described in the plural.","vi":"quần áo rách rưới"}],"examples":[{"en":"He wiped the oily tools with an old rag.","vi":"Anh ấy lau các dụng cụ dính dầu mỡ bằng một chiếc giẻ lau cũ.","audioKind":"ex"},{"en":"Reusing worn clothing as cleaning rags can reduce household waste and demand for disposable products.","vi":"Việc tái sử dụng quần áo mòn rách làm giẻ lau có thể giúp giảm thiểu rác thải sinh hoạt và nhu cầu về các sản phẩm dùng một lần.","audioKind":"ex2"}],"collocations":[{"en":"an old rag","vi":"một miếng giẻ cũ"},{"en":"a cleaning rag","vi":"giẻ lau dọn"},{"en":"in rags","vi":"mặc quần áo rách rưới"},{"en":"from rags to riches","vi":"từ tay trắng thành giàu có"}],"wordFamily":["ragged (adj.)"],"synonyms":["cloth"],"antonyms":[],"tipVi":"Dạng số ít thường chỉ một miếng giẻ; in rags mang nghĩa là rách rưới, nghèo khổ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cabinet', 'en-b2-80', 'cabinet', '/ˈkæbɪnət/', 'B2', 'tủ chén; tủ đựng đồ; nội chính; nội các', 'n.', NULL, NULL, 'Có thể chỉ đồ nội thất hoặc nội các chính phủ; nội các bao gồm các bộ trưởng cấp cao.', 'The clean cups are in the cabinet above the sink.', NULL, 'Những chiếc cốc sạch được đặt trong tủ chén phía trên bồn rửa.', '{"wordId":"cabinet","ukIpa":"/ˈkæbɪnət/","usIpa":"/ˈkæbɪnət/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"a cupboard with shelves or drawers for storing things","vi":"tủ chén; tủ đựng đồ"},{"pos":"n.","en":"the group of senior ministers who make major government decisions","vi":"nội chính; nội các"}],"examples":[{"en":"The clean cups are in the cabinet above the sink.","vi":"Những chiếc cốc sạch được đặt trong tủ chén phía trên bồn rửa.","audioKind":"ex"},{"en":"The cabinet approved a national programme to improve access to affordable housing in rapidly growing cities.","vi":"Nội các đã phê duyệt một chương trình quốc gia nhằm cải thiện khả năng tiếp cận nhà ở giá rẻ ở các thành phố đang phát triển nhanh chóng.","audioKind":"ex2"}],"collocations":[{"en":"kitchen cabinet","vi":"tủ bếp"},{"en":"filing cabinet","vi":"tủ đựng hồ sơ"},{"en":"cabinet minister","vi":"bộ trưởng nội các"},{"en":"cabinet meeting","vi":"cuộc họp nội các"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Có thể chỉ đồ nội thất hoặc nội các chính phủ; nội các bao gồm các bộ trưởng cấp cao.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aroma', 'en-b2-80', 'aroma', '/əˈroʊmə/', 'B2', 'hương thơm; mùi thơm dễ chịu', 'n.', 'aromatic (adj.)', 'Đồng nghĩa: fragrance, scent', 'Thường dùng cho mùi hương dễ chịu, đặc biệt là của đồ ăn hoặc thức uống.', 'The aroma of fresh bread filled the kitchen.', NULL, 'Hương thơm của bánh mì mới nướng lan tỏa khắp căn bếp.', '{"wordId":"aroma","ukIpa":"/əˈrəʊmə/","usIpa":"/əˈroʊmə/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"a noticeable pleasant smell, especially from food or drink","vi":"hương thơm; mùi thơm dễ chịu"}],"examples":[{"en":"The aroma of fresh bread filled the kitchen.","vi":"Hương thơm của bánh mì mới nướng lan tỏa khắp căn bếp.","audioKind":"ex"},{"en":"The aroma of freshly prepared food can enhance customers'' dining experiences and influence their perception of quality.","vi":"Hương thơm của món ăn mới chế biến có thể nâng cao trải nghiệm ẩm thực của thực khách và định hình cảm nhận của họ về chất lượng món ăn.","audioKind":"ex2"}],"collocations":[{"en":"the aroma of coffee","vi":"hương cà phê"},{"en":"rich aroma","vi":"hương thơm nồng nàn"},{"en":"release an aroma","vi":"tỏa ra hương thơm"}],"wordFamily":["aromatic (adj.)"],"synonyms":["fragrance","scent"],"antonyms":[],"tipVi":"Thường dùng cho mùi hương dễ chịu, đặc biệt là của đồ ăn hoặc thức uống.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_household', 'en-b2-80', 'household', '/ˈhaʊshoʊld/', 'B2', 'hộ gia đình; người trong nhà; thuộc gia đình; dùng trong nhà', 'n.', 'householder (n.)', NULL, 'Household nhấn mạnh những người sống chung một nhà, không nhất thiết phải có quan hệ họ hàng.', 'Everyone in our household takes turns washing the dishes.', NULL, 'Mọi người trong gia đình chúng tôi đều lần lượt rửa bát.', '{"wordId":"household","ukIpa":"/ˈhaʊshəʊld/","usIpa":"/ˈhaʊshoʊld/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"all the people who live together in one home","vi":"hộ gia đình; người trong nhà"},{"pos":"adj.","en":"relating to a home and its everyday needs","vi":"thuộc gia đình; dùng trong nhà"}],"examples":[{"en":"Everyone in our household takes turns washing the dishes.","vi":"Mọi người trong gia đình chúng tôi đều lần lượt rửa bát.","audioKind":"ex"},{"en":"Rising energy prices place considerable pressure on household budgets, particularly among families with lower incomes.","vi":"Giá năng lượng tăng tạo áp lực đáng kể lên ngân sách hộ gia đình, đặc biệt là trong các gia đình có thu nhập thấp.","audioKind":"ex2"}],"collocations":[{"en":"household income","vi":"thu nhập hộ gia đình"},{"en":"household appliances","vi":"thiết bị gia dụng"},{"en":"household chores","vi":"việc nhà"},{"en":"single-person household","vi":"hộ độc thân"}],"wordFamily":["householder (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Household nhấn mạnh những người sống chung một nhà, không nhất thiết phải có quan hệ họ hàng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_substitute', 'en-b2-80', 'substitute', '/ˈsʌbstɪtuːt/', 'B2', 'thế thân; vật thay thế; thay thế; dùng thay cho', 'n.', 'substitution (n.)', 'Đồng nghĩa: replacement, stand-in', 'substitute A for B＝dùng A thay thế cho B, không được đảo ngược vị trí.', 'Yoghurt makes a good substitute for cream in this soup.', NULL, 'Dùng sữa chua làm món thay thế kem rất ngon trong món súp này.', '{"wordId":"substitute","ukIpa":"/ˈsʌbstɪtjuːt/","usIpa":"/ˈsʌbstɪtuːt/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A person or thing used in place of another.","vi":"thế thân; vật thay thế"},{"pos":"v.","en":"Use someone or something instead of another person or thing.","vi":"thay thế; dùng thay cho"}],"examples":[{"en":"Yoghurt makes a good substitute for cream in this soup.","vi":"Dùng sữa chua làm món thay thế kem rất ngon trong món súp này.","audioKind":"ex"},{"en":"Online lessons can support independent learning, but they are not always an adequate substitute for classroom interaction.","vi":"Các bài học trực tuyến có thể hỗ trợ việc tự học, nhưng chúng không phải lúc nào cũng đủ khả năng thay thế hoàn toàn cho việc tương tác trên lớp.","audioKind":"ex2"}],"collocations":[{"en":"a substitute for","vi":"vật thay thế cho"},{"en":"substitute A for B","vi":"dùng A thay cho B"},{"en":"a suitable substitute","vi":"một sự thay thế phù hợp"},{"en":"a substitute teacher","vi":"giáo viên dạy thay"}],"wordFamily":["substitution (n.)"],"synonyms":["replacement","stand-in"],"antonyms":[],"tipVi":"substitute A for B＝dùng A thay thế cho B, không được đảo ngược vị trí.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sprinkle', 'en-b2-80', 'sprinkle', '/ˈsprɪŋkəl/', 'B2', 'rắc; vãi; lượng nhỏ; chút ít', 'v.', 'sprinkler (n.), sprinkling (n.)', 'Đồng nghĩa: scatter', 'Có thể dùng cấu trúc sprinkle A over B, hoặc sprinkle B with A.', 'Sprinkle some cinnamon over your porridge before eating.', NULL, 'Rắc một ít bột quế lên cháo của bạn trước khi ăn nhé.', '{"wordId":"sprinkle","ukIpa":"/ˈsprɪŋkəl/","usIpa":"/ˈsprɪŋkəl/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To scatter small drops or pieces over something.","vi":"rắc; vãi"},{"pos":"n.","en":"A small amount scattered over a surface.","vi":"lượng nhỏ; chút ít"}],"examples":[{"en":"Sprinkle some cinnamon over your porridge before eating.","vi":"Rắc một ít bột quế lên cháo của bạn trước khi ăn nhé.","audioKind":"ex"},{"en":"Rather than adding excessive salt, consumers can sprinkle herbs over meals to enhance flavour more healthily.","vi":"Thay vì cho quá nhiều muối, người tiêu dùng có thể rắc các loại thảo mộc lên món ăn để tăng hương vị một cách lành mạnh hơn.","audioKind":"ex2"}],"collocations":[{"en":"sprinkle sugar over","vi":"rắc đường lên"},{"en":"sprinkle with herbs","vi":"rắc thảo mộc lên"},{"en":"a sprinkle of salt","vi":"một chút muối"}],"wordFamily":["sprinkler (n.)","sprinkling (n.)"],"synonyms":["scatter"],"antonyms":[],"tipVi":"Có thể dùng cấu trúc sprinkle A over B, hoặc sprinkle B with A.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_glow', 'en-b2-80', 'glow', '/ɡloʊ/', 'B2', 'tỏa sáng dịu nhẹ; phát sáng; ánh sáng dịu; ánh hồng; ửng đỏ; rạng rỡ', 'v.', 'glowing (adj.)', NULL, 'glow thường chỉ ánh sáng dịu kéo dài; flash chỉ ánh chớp lóe sáng ngắn ngủi.', 'The last embers glowed softly in the fireplace.', NULL, 'Những tàn lửa cuối cùng đang rực lên ánh sáng dịu nhẹ trong lò sưởi.', '{"wordId":"glow","ukIpa":"/ɡləʊ/","usIpa":"/ɡloʊ/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to produce a steady, soft light","vi":"tỏa sáng dịu nhẹ; phát sáng"},{"pos":"n.","en":"a soft, steady light","vi":"ánh sáng dịu; ánh hồng"},{"pos":"v.","en":"to look warm, healthy, or full of pleasure","vi":"ửng đỏ; rạng rỡ"}],"examples":[{"en":"The last embers glowed softly in the fireplace.","vi":"Những tàn lửa cuối cùng đang rực lên ánh sáng dịu nhẹ trong lò sưởi.","audioKind":"ex"},{"en":"The warm glow of street lighting can make public spaces feel safer after dark.","vi":"Ánh đèn đường ấm áp và dịu nhẹ có thể giúp các không gian công cộng trở nên an toàn hơn khi trời tối.","audioKind":"ex2"}],"collocations":[{"en":"a warm glow","vi":"ánh sáng ấm áp dịu nhẹ"},{"en":"glow with pride","vi":"rạng rỡ vì tự hào"},{"en":"a healthy glow","vi":"vẻ ngoài khỏe khoắn hồng hào"}],"wordFamily":["glowing (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"glow thường chỉ ánh sáng dịu kéo dài; flash chỉ ánh chớp lóe sáng ngắn ngủi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_novelty', 'en-b2-80', 'novelty', '/ˈnɑːvəlti/', 'B2', 'tính mới lạ; sự mới mẻ; sự việc mới lạ; điều thú vị; đồ chơi mới lạ; vật trang trí nhỏ', 'n.', 'novel (adj.)', 'Đồng nghĩa: newness, originality · Trái nghĩa: familiarity', 'Khi chỉ tính mới mẻ thì không đếm được; khi chỉ vật lạ hoặc đồ chơi thì đếm được.', 'The novelty of sleeping in a tent soon wore off.', NULL, 'Cảm giác mới mẻ khi ngủ trong lều nhanh chóng biến mất.', '{"wordId":"novelty","ukIpa":"/ˈnɒvəlti/","usIpa":"/ˈnɑːvəlti/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"the quality of being new, unusual, or unfamiliar","vi":"tính mới lạ; sự mới mẻ"},{"pos":"n.","en":"something new or unusual that attracts interest","vi":"sự việc mới lạ; điều thú vị"},{"pos":"n.","en":"a small unusual object made mainly for amusement","vi":"đồ chơi mới lạ; vật trang trí nhỏ"}],"examples":[{"en":"The novelty of sleeping in a tent soon wore off.","vi":"Cảm giác mới mẻ khi ngủ trong lều nhanh chóng biến mất.","audioKind":"ex"},{"en":"Although the novelty of new technology attracts consumers, long-term adoption depends on practical benefits and affordability.","vi":"Mặc dù tính mới lạ của công nghệ mới thu hút người tiêu dùng, việc áp dụng lâu dài lại phụ thuộc vào lợi ích thực tế và giá cả phải chăng.","audioKind":"ex2"}],"collocations":[{"en":"novelty value","vi":"giá trị mới lạ"},{"en":"the novelty wears off","vi":"sự mới mẻ phai nhạt dần"},{"en":"a novelty item","vi":"món đồ chơi mới lạ"}],"wordFamily":["novel (adj.)"],"synonyms":["newness","originality"],"antonyms":["familiarity"],"tipVi":"Khi chỉ tính mới mẻ thì không đếm được; khi chỉ vật lạ hoặc đồ chơi thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dip', 'en-b2-80', 'dip', '/dɪp/', 'B2', 'nhúng; chấm; sụt giảm nhẹ; hạ xuống; lần tắm ngắn; sự sụt giảm tạm thời', 'v.', NULL, NULL, 'Dạng quá khứ và phân từ hai là dipped; phân từ hiện đại là dipping.', 'Dip the strawberries in chocolate before putting them on plates.', NULL, 'Nhúng những quả dâu tây vào sô-cô-la trước khi xếp chúng lên đĩa.', '{"wordId":"dip","ukIpa":"/dɪp/","usIpa":"/dɪp/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To put something briefly into liquid and take it out.","vi":"nhúng; chấm"},{"pos":"v.","en":"To fall slightly, often for a short time.","vi":"sụt giảm nhẹ; hạ xuống"},{"pos":"n.","en":"A short swim, or a small, temporary decrease.","vi":"lần tắm ngắn; sự sụt giảm tạm thời"}],"examples":[{"en":"Dip the strawberries in chocolate before putting them on plates.","vi":"Nhúng những quả dâu tây vào sô-cô-la trước khi xếp chúng lên đĩa.","audioKind":"ex"},{"en":"Temperatures may dip overnight, increasing the demand for heating in homes that lack adequate insulation.","vi":"Nhiệt độ có thể giảm xuống vào ban đêm, làm tăng nhu cầu sưởi ấm ở những ngôi nhà thiếu trang thiết bị cách nhiệt đầy đủ.","audioKind":"ex2"}],"collocations":[{"en":"dip into water","vi":"nhúng vào nước"},{"en":"a dip in sales","vi":"doanh số sụt giảm nhẹ"},{"en":"go for a dip","vi":"đi bơi một chút"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ và phân từ hai là dipped; phân từ hiện đại là dipping.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_evenly', 'en-b2-80', 'evenly', '/ˈiːvənli/', 'B2', 'đều; đều đặn; cách đều nhau; bình thản; điềm tĩnh; không dao động', 'adv.', 'even (adj.), uneven (adj.), unevenly (adv.), evenness (n.)', 'Đồng nghĩa: uniformly, equally · Trái nghĩa: unevenly', 'Nhấn mạnh vào số lượng hoặc khoảng cách bằng nhau; khác với từ chỉ tính liên tục consistently.', 'Spread the butter evenly over each slice of bread.', NULL, 'Phết đều bơ lên từng lát bánh mì.', '{"wordId":"evenly","ukIpa":"/ˈiːvənli/","usIpa":"/ˈiːvənli/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"In equal amounts or with equal spaces between things","vi":"đều; đều đặn; cách đều nhau"},{"pos":"adv.","en":"In a calm, steady way without noticeable changes","vi":"bình thản; điềm tĩnh; không dao động"}],"examples":[{"en":"Spread the butter evenly over each slice of bread.","vi":"Phết đều bơ lên từng lát bánh mì.","audioKind":"ex"},{"en":"Public investment should be distributed more evenly across regions to reduce inequalities in access to essential services.","vi":"Đầu tư công nên được phân bổ đều đặn hơn giữa các vùng miền để giảm bớt sự bất bình đẳng trong việc tiếp cận các dịch vụ thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"evenly distributed","vi":"phân bổ đều"},{"en":"evenly spaced","vi":"cách đều nhau"},{"en":"divide evenly","vi":"chia đều"},{"en":"speak evenly","vi":"nói với giọng điềm tĩnh"}],"wordFamily":["even (adj.)","uneven (adj.)","unevenly (adv.)","evenness (n.)"],"synonyms":["uniformly","equally"],"antonyms":["unevenly"],"tipVi":"Nhấn mạnh vào số lượng hoặc khoảng cách bằng nhau; khác với từ chỉ tính liên tục consistently.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_massive', 'en-b2-80', 'massive', '/ˈmæsɪv/', 'B2', 'to lớn; đồ sộ; nặng nề; lớn lao; khổng lồ; trầm trọng', 'adj.', 'massively (adv.), massiveness (n.)', 'Đồng nghĩa: huge, enormous, immense · Trái nghĩa: tiny', 'Có thể diễn tả kích thước vật lý hoặc mức độ, quy mô của một sự việc.', 'A massive oak tree shades our entire garden.', NULL, 'Một cây sồi lớn che bóng mát cho toàn bộ khu vườn của chúng tôi.', '{"wordId":"massive","ukIpa":"/ˈmæsɪv/","usIpa":"/ˈmæsɪv/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Extremely large, heavy, or solid.","vi":"to lớn; đồ sộ; nặng nề"},{"pos":"adj.","en":"Extremely great in amount, extent, or degree.","vi":"lớn lao; khổng lồ; trầm trọng"}],"examples":[{"en":"A massive oak tree shades our entire garden.","vi":"Một cây sồi lớn che bóng mát cho toàn bộ khu vườn của chúng tôi.","audioKind":"ex"},{"en":"The transition to renewable energy requires massive investment in infrastructure and training for workers.","vi":"Quá trình chuyển đổi sang năng lượng tái tạo đòi hỏi những khoản đầu tư khổng lồ vào cơ sở hạ tầng và công tác đào tạo người lao động.","audioKind":"ex2"}],"collocations":[{"en":"massive investment","vi":"đầu tư khổng lồ"},{"en":"massive increase","vi":"sự tăng trưởng đột biến"},{"en":"massive stone walls","vi":"tường đá dày"},{"en":"massive impact","vi":"tác động to lớn"}],"wordFamily":["massively (adv.)","massiveness (n.)"],"synonyms":["huge","enormous","immense"],"antonyms":["tiny"],"tipVi":"Có thể diễn tả kích thước vật lý hoặc mức độ, quy mô của một sự việc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_appreciate', 'en-b2-80', 'appreciate', '/əˈpriːʃieɪt/', 'B2', 'cảm kích; biết ơn; thưởng thức; đánh giá cao; thấu hiểu; nhận thức sâu sắc', 'v.', 'appreciation (n.), appreciative (adj.), appreciatively (adv.)', 'Đồng nghĩa: value, recognise', 'Theo sau có thể là danh từ hoặc danh động từ, không dùng to do; cảm ơn sự giúp đỡ dùng appreciate your help.', 'I really appreciate you watering my plants while I was away.', NULL, 'Tôi thực sự cảm kích việc bạn đã tưới cây giúp tôi trong lúc tôi đi vắng.', '{"wordId":"appreciate","ukIpa":"/əˈpriːʃieɪt/","usIpa":"/əˈpriːʃieɪt/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"Feel grateful for something someone has done.","vi":"cảm kích; biết ơn"},{"pos":"v.","en":"Recognise and enjoy the value or quality of something.","vi":"thưởng thức; đánh giá cao"},{"pos":"v.","en":"Understand the importance or difficulty of a situation.","vi":"thấu hiểu; nhận thức sâu sắc"}],"examples":[{"en":"I really appreciate you watering my plants while I was away.","vi":"Tôi thực sự cảm kích việc bạn đã tưới cây giúp tôi trong lúc tôi đi vắng.","audioKind":"ex"},{"en":"Policymakers need to appreciate the difficulties rural communities face when accessing healthcare and other essential services.","vi":"Các nhà hoạch định chính sách cần thấu hiểu những khó khăn mà các cộng đồng nông thôn phải đối mặt khi tiếp cận dịch vụ y tế và các dịch vụ thiết yếu khác.","audioKind":"ex2"}],"collocations":[{"en":"greatly appreciate","vi":"vô cùng cảm kích"},{"en":"appreciate your help","vi":"cảm ơn sự giúp đỡ của bạn"},{"en":"appreciate the importance of","vi":"nhận thức tầm quan trọng của"},{"en":"appreciate art","vi":"thưởng thức nghệ thuật"}],"wordFamily":["appreciation (n.)","appreciative (adj.)","appreciatively (adv.)"],"synonyms":["value","recognise"],"antonyms":[],"tipVi":"Theo sau có thể là danh từ hoặc danh động từ, không dùng to do; cảm ơn sự giúp đỡ dùng appreciate your help.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_80_1', 'en-b2-80', 'Cách dùng “appreciate” (v.) — cảm kích; biết ơn', 'greatly appreciate  ·  appreciate your help  ·  appreciate the importance of', 'Theo sau có thể là danh từ hoặc danh động từ, không dùng to do; cảm ơn sự giúp đỡ dùng appreciate your help.', 'Họ từ (Word Family): appreciation (n.), appreciative (adj.), appreciatively (adv.) | Đồng nghĩa: value, recognise', '[{"hanzi":"I really appreciate you watering my plants while I was away.","pinyin":"","meaning":"Tôi thực sự cảm kích việc bạn đã tưới cây giúp tôi trong lúc tôi đi vắng."},{"hanzi":"Policymakers need to appreciate the difficulties rural communities face when accessing healthcare and other essential services.","pinyin":"","meaning":"Các nhà hoạch định chính sách cần thấu hiểu những khó khăn mà các cộng đồng nông thôn phải đối mặt khi tiếp cận dịch vụ y tế và các dịch vụ thiết yếu khác."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_80_2', 'en-b2-80', 'Cách dùng “evenly” (adv.) — đều; đều đặn; cách đều nhau', 'evenly distributed  ·  evenly spaced  ·  divide evenly', 'Nhấn mạnh vào số lượng hoặc khoảng cách bằng nhau; khác với từ chỉ tính liên tục consistently.', 'Họ từ (Word Family): even (adj.), uneven (adj.), unevenly (adv.), evenness (n.) | Đồng nghĩa: uniformly, equally · Trái nghĩa: unevenly', '[{"hanzi":"Spread the butter evenly over each slice of bread.","pinyin":"","meaning":"Phết đều bơ lên từng lát bánh mì."},{"hanzi":"Public investment should be distributed more evenly across regions to reduce inequalities in access to essential services.","pinyin":"","meaning":"Đầu tư công nên được phân bổ đều đặn hơn giữa các vùng miền để giảm bớt sự bất bình đẳng trong việc tiếp cận các dịch vụ thiết yếu."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_80_3', 'en-b2-80', 'Cách dùng “household” (n.) — hộ gia đình; người trong nhà', 'household income  ·  household appliances  ·  household chores', 'Household nhấn mạnh những người sống chung một nhà, không nhất thiết phải có quan hệ họ hàng.', 'Họ từ (Word Family): householder (n.)', '[{"hanzi":"Everyone in our household takes turns washing the dishes.","pinyin":"","meaning":"Mọi người trong gia đình chúng tôi đều lần lượt rửa bát."},{"hanzi":"Rising energy prices place considerable pressure on household budgets, particularly among families with lower incomes.","pinyin":"","meaning":"Giá năng lượng tăng tạo áp lực đáng kể lên ngân sách hộ gia đình, đặc biệt là trong các gia đình có thu nhập thấp."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_80_4', 'en-b2-80', 'Cách dùng “wax” (n.) — sáp; sáp nến', 'candle wax  ·  a layer of wax  ·  wax the floor', 'wax khi mang nghĩa là sáp thường không đếm được; mặt trăng lớn dần trái nghĩa với wane.', 'Họ từ (Word Family): waxy (adj.), waxing (n.)', '[{"hanzi":"Warm wax dripped from the candle onto the table.","pinyin":"","meaning":"Sáp ấm từ ngọn nến nhỏ giọt xuống mặt bàn."},{"hanzi":"A thin layer of wax can protect fresh fruit and reduce moisture loss during transport.","pinyin":"","meaning":"Một lớp sáp mỏng có thể bảo vệ trái cây tươi và giảm sự mất độ ẩm trong quá trình vận chuyển."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_80_1', 'en-b2-80', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_80_1_1', 'ten_b2_80_1', 'excess', 'Wipe away the excess paint with a clean cloth.', 'Wipe away the excess paint with a clean cloth.', '/ɪkˈses/', 'Dùng khăn sạch lau sạch lớp sơn thừa đi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_80_1_2', 'ten_b2_80_1', 'existing', 'We kept the existing shelves and painted them blue.', 'We kept the existing shelves and painted them blue.', '/ɪɡˈzɪstɪŋ/', 'Chúng tôi giữ lại những chiếc kệ có sẵn và sơn chúng thành màu xanh dương.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_80_1_3', 'ten_b2_80_1', 'partially', 'The curtains were partially open, letting in sunlight.', 'The curtains were partially open, letting in sunlight.', '/ˈpɑːrʃəli/', 'Rèm cửa đang mở một phần, để ánh nắng chiếu vào.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_80_1_4', 'ten_b2_80_1', 'wax', 'Warm wax dripped from the candle onto the table.', 'Warm wax dripped from the candle onto the table.', '/wæks/', 'Sáp ấm từ ngọn nến nhỏ giọt xuống mặt bàn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_80_1_5', 'ten_b2_80_1', 'sole', 'She is the sole owner of this little bakery.', 'She is the sole owner of this little bakery.', '/soʊl/', 'Cô ấy là chủ sở hữu duy nhất của tiệm bánh nhỏ này.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_80_1_6', 'ten_b2_80_1', 'gasp', 'We gasped as the whale rose beside our boat.', 'We gasped as the whale rose beside our boat.', '/ɡæsp/', 'Chúng tôi há hốc kinh ngạc khi con cá voi trồi lên bên cạnh thuyền.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_80_1_7', 'ten_b2_80_1', 'irregular', 'The path was made from stones of irregular shapes.', 'The path was made from stones of irregular shapes.', '/ɪˈreɡjələr/', 'Con đường được lát bằng những viên đá có hình dạng không đều.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_80_1_8', 'ten_b2_80_1', 'loose', 'One loose screw made the whole chair feel shaky.', 'One loose screw made the whole chair feel shaky.', '/luːs/', 'Một con ốc lỏng lẻo đã làm cho cả chiếc ghế trở nên chòng chành.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_80_1_1', 'en-b2-80', 'ten_b2_80_1', 'listening', 'listening', 'Wipe away the excess paint with a clean cloth.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một con ốc lỏng lẻo đã làm cho cả chiếc ghế trở nên chòng chành.","Rèm cửa đang mở một phần, để ánh nắng chiếu vào.","Tôi bị vấp phải một hòn sỏi lỏng trên lối đi trong vườn.","Dùng khăn sạch lau sạch lớp sơn thừa đi."]'::jsonb, 3, 'Wipe away the excess paint with a clean cloth. → Dùng khăn sạch lau sạch lớp sơn thừa đi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_80_1_2', 'en-b2-80', 'ten_b2_80_1', 'listening', 'listening', 'We kept the existing shelves and painted them blue.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một con ốc lỏng lẻo đã làm cho cả chiếc ghế trở nên chòng chành.","Những tàn lửa cuối cùng đang rực lên ánh sáng dịu nhẹ trong lò sưởi.","Chúng tôi giữ lại những chiếc kệ có sẵn và sơn chúng thành màu xanh dương.","Rắc một ít bột quế lên cháo của bạn trước khi ăn nhé."]'::jsonb, 2, 'We kept the existing shelves and painted them blue. → Chúng tôi giữ lại những chiếc kệ có sẵn và sơn chúng thành màu xanh dương.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_80_1_3', 'en-b2-80', 'ten_b2_80_1', 'listening', 'listening', 'The curtains were partially open, letting in sunlight.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi dùng những miếng bánh mì nhỏ làm mồi câu.","Mọi người trong gia đình chúng tôi đều lần lượt rửa bát.","Rèm cửa đang mở một phần, để ánh nắng chiếu vào.","Con đường được lát bằng những viên đá có hình dạng không đều."]'::jsonb, 2, 'The curtains were partially open, letting in sunlight. → Rèm cửa đang mở một phần, để ánh nắng chiếu vào.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_80_2', 'en-b2-80', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_80_2_1', 'ten_b2_80_2', 'excess', 'Consuming sugar in excess can increase the risk of obesity and other health problems.', 'Consuming sugar in excess can increase the risk of obesity and other health problems.', '/ɪkˈses/', 'Tiêu thụ quá nhiều đường có thể làm tăng nguy cơ béo phì và các vấn đề sức khỏe khác.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_80_2_2', 'ten_b2_80_2', 'existing', 'Governments should improve existing transport networks before investing public money in entirely new infrastructure projects.', 'Governments should improve existing transport networks before investing public money in entirely new infrastructure projects.', '/ɪɡˈzɪstɪŋ/', 'Chính phủ nên cải thiện các mạng lưới giao thông hiện có trước khi đầu tư vốn công vào các dự án cơ sở hạ tầng hoàn toàn mới.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_80_2_3', 'ten_b2_80_2', 'partially', 'Although recycling can partially reduce waste, changes in production and consumption are also necessary.', 'Although recycling can partially reduce waste, changes in production and consumption are also necessary.', '/ˈpɑːrʃəli/', 'Mặc dù việc tái chế có thể làm giảm rác thải phần nào, nhưng những thay đổi trong sản xuất và tiêu thụ cũng là điều cần thiết.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_80_2_4', 'ten_b2_80_2', 'wax', 'A thin layer of wax can protect fresh fruit and reduce moisture loss during transport.', 'A thin layer of wax can protect fresh fruit and reduce moisture loss during transport.', '/wæks/', 'Một lớp sáp mỏng có thể bảo vệ trái cây tươi và giảm sự mất độ ẩm trong quá trình vận chuyển.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_80_2_5', 'ten_b2_80_2', 'sole', 'Economic growth should not be the sole measure of a country''s progress or public wellbeing.', 'Economic growth should not be the sole measure of a country''s progress or public wellbeing.', '/soʊl/', 'Tăng trưởng kinh tế không nên là thước đo duy nhất cho sự tiến bộ của một quốc gia hay phúc lợi cộng đồng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_80_2_6', 'ten_b2_80_2', 'gasp', 'Runners may gasp for breath when exercising at high altitudes, where less oxygen is available.', 'Runners may gasp for breath when exercising at high altitudes, where less oxygen is available.', '/ɡæsp/', 'Người chạy bộ có thể phải thở hổn hển khi tập luyện ở vùng núi cao, nơi có ít oxy hơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_80_2_1', 'en-b2-80', 'ten_b2_80_2', 'listening', 'listening', 'Consuming sugar in excess can increase the risk of obesity and other health problems.', NULL, 'Trong câu vừa nghe, từ “excess” mang nghĩa nào sau đây?', '["sự điều hướng; sự định vị và dẫn đường","thuộc về nguyên tử","số lượng vượt mức; phần thừa","lấp lánh, sáng lấp lánh với nhiều tia sáng nhỏ"]'::jsonb, 2, '“excess” (/ɪkˈses/): số lượng vượt mức; phần thừa. Câu đầy đủ: Consuming sugar in excess can increase the risk of obesity and other health problems.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_80_2_2', 'en-b2-80', 'ten_b2_80_2', 'listening', 'listening', 'Governments should improve existing transport networks before investing public money in entirely new infrastructure projects.', NULL, 'Trong câu vừa nghe, từ “existing” mang nghĩa nào sau đây?', '["sự tra tấn; cực hình; nỗi giày vò","bảo đảm; cam kết","hàng hóa (chuyên chở bằng tàu thủy, máy bay hoặc phương tiện lớn)","hiện có; đang tồn tại; sẵn có"]'::jsonb, 3, '“existing” (/ɪɡˈzɪstɪŋ/): hiện có; đang tồn tại; sẵn có. Câu đầy đủ: Governments should improve existing transport networks before investing public money in entirely new infrastructure projects.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
