INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_80_2', 'en-b2-80', NULL, 'comprehensive_test', 'listening', 'We kept the existing shelves and painted them blue.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Anh ấy lau các dụng cụ dính dầu mỡ bằng một chiếc giẻ lau cũ.","Cảm giác mới mẻ khi ngủ trong lều nhanh chóng biến mất.","Chúng tôi giữ lại những chiếc kệ có sẵn và sơn chúng thành màu xanh dương.","Con đường được lát bằng những viên đá có hình dạng không đều."]'::jsonb, 2, 'We kept the existing shelves and painted them blue. → Chúng tôi giữ lại những chiếc kệ có sẵn và sơn chúng thành màu xanh dương.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_80_3', 'en-b2-80', NULL, 'comprehensive_test', 'listening', 'partially', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự cân nhắc; sự suy xét","hệ sinh thái","một phần; phần nào; không hoàn toàn","cơn giận dữ; sự cuồng nộ"]'::jsonb, 2, 'partially (/ˈpɑːrʃəli/) → một phần; phần nào; không hoàn toàn', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_80_4', 'en-b2-80', NULL, 'comprehensive_test', 'listening', 'Warm wax dripped from the candle onto the table.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Rắc một ít bột quế lên cháo của bạn trước khi ăn nhé.","Sáp ấm từ ngọn nến nhỏ giọt xuống mặt bàn.","Cảm giác mới mẻ khi ngủ trong lều nhanh chóng biến mất.","Những tàn lửa cuối cùng đang rực lên ánh sáng dịu nhẹ trong lò sưởi."]'::jsonb, 1, 'Warm wax dripped from the candle onto the table. → Sáp ấm từ ngọn nến nhỏ giọt xuống mặt bàn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_80_5', 'en-b2-80', NULL, 'comprehensive_test', 'listening', 'sole', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["kho lúa; chuồng trại","trí thông minh; năng lực trí tuệ","sự hào phóng; tính rộng lượng","duy nhất; đơn độc"]'::jsonb, 3, 'sole (/soʊl/) → duy nhất; đơn độc; lòng bàn chân; đế giày; cá bơn (loại cá biển dẹt thường dùng làm thực phẩm)', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_80_6', 'en-b2-80', NULL, 'comprehensive_test', 'listening', 'We gasped as the whale rose beside our boat.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Loại gia vị này thường được sử dụng trong các món súp và món hầm.","Chúng tôi há hốc kinh ngạc khi con cá voi trồi lên bên cạnh thuyền.","Dùng sữa chua làm món thay thế kem rất ngon trong món súp này.","Anh ấy lau các dụng cụ dính dầu mỡ bằng một chiếc giẻ lau cũ."]'::jsonb, 1, 'We gasped as the whale rose beside our boat. → Chúng tôi há hốc kinh ngạc khi con cá voi trồi lên bên cạnh thuyền.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_80_7', 'en-b2-80', NULL, 'comprehensive_test', 'listening', 'irregular', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự tiến bộ; bước tiến; sự phát triển","do đó; vì vậy","không đều; không theo quy tắc","tráng lệ; nguy nga; hùng vĩ"]'::jsonb, 2, 'irregular (/ɪˈreɡjələr/) → không đều; không theo quy tắc; không cố định; thất thường; bất quy tắc (ngữ pháp)', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_80_8', 'en-b2-80', NULL, 'comprehensive_test', 'listening', 'One loose screw made the whole chair feel shaky.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một con ốc lỏng lẻo đã làm cho cả chiếc ghế trở nên chòng chành.","Một cây sồi lớn che bóng mát cho toàn bộ khu vườn của chúng tôi.","Hôm qua chúng tôi có một chuyến đi biển ngẫu hứng.","Sáp ấm từ ngọn nến nhỏ giọt xuống mặt bàn."]'::jsonb, 0, 'One loose screw made the whole chair feel shaky. → Một con ốc lỏng lẻo đã làm cho cả chiếc ghế trở nên chòng chành.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_80_9', 'en-b2-80', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Being the only one, with nobody or nothing else involved.”?', '["sole","bait","aroma","excess"]'::jsonb, 0, 'sole (/soʊl/) → duy nhất; đơn độc', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
