INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_80_18', 'en-b2-80', NULL, 'comprehensive_test', 'reading', NULL, 'Consuming sugar in excess can increase the risk of obesity and other health problems.', 'Dựa vào câu trên, từ “excess” có nghĩa phù hợp nhất là gì?', '["ô che nắng; mái che nắng","trốn chạy; chạy trốn","đất sét; đất nung","số lượng vượt mức; phần thừa"]'::jsonb, 3, 'excess: số lượng vượt mức; phần thừa; vượt mức; dư thừa. Dịch cả câu: Tiêu thụ quá nhiều đường có thể làm tăng nguy cơ béo phì và các vấn đề sức khỏe khác.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_80_19', 'en-b2-80', NULL, 'comprehensive_test', 'reading', NULL, 'Governments should improve existing transport networks before investing public money in entirely new infrastructure projects.', 'Dựa vào câu trên, từ “existing” có nghĩa phù hợp nhất là gì?', '["hiện có; đang tồn tại; sẵn có","có tính thực dụng; nặng về công năng hơn trang trí","rìa; vùng ngoại vi","độ dày; bề dày"]'::jsonb, 0, 'existing: hiện có; đang tồn tại; sẵn có. Dịch cả câu: Chính phủ nên cải thiện các mạng lưới giao thông hiện có trước khi đầu tư vốn công vào các dự án cơ sở hạ tầng hoàn toàn mới.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_80_20', 'en-b2-80', NULL, 'comprehensive_test', 'reading', NULL, 'Although recycling can partially reduce waste, changes in production and consumption are also necessary.', 'Dựa vào câu trên, từ “partially” có nghĩa phù hợp nhất là gì?', '["thuộc thảo mộc; làm từ thảo mộc","ô che nắng; mái che nắng","một phần; phần nào; không hoàn toàn","người vận hành"]'::jsonb, 2, 'partially: một phần; phần nào; không hoàn toàn. Dịch cả câu: Mặc dù việc tái chế có thể làm giảm rác thải phần nào, nhưng những thay đổi trong sản xuất và tiêu thụ cũng là điều cần thiết.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_80_21', 'en-b2-80', NULL, 'comprehensive_test', 'reading', NULL, 'A thin layer of wax can protect fresh fruit and reduce moisture loss during transport.', 'Dựa vào câu trên, từ “wax” có nghĩa phù hợp nhất là gì?', '["thay đổi; biến đổi","sáp; sáp nến","được kích hoạt; được khởi động","tư duy theo nhóm; động não; thảo luận tìm ý tưởng"]'::jsonb, 1, 'wax: sáp; sáp nến; đánh sáp; thoa sáp; trăng tròn dần; sự sáng lên của mặt trăng. Dịch cả câu: Một lớp sáp mỏng có thể bảo vệ trái cây tươi và giảm sự mất độ ẩm trong quá trình vận chuyển.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_80_22', 'en-b2-80', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đều; đều đặn; cách đều nhau”', '["abnormal","rib","urge","evenly"]'::jsonb, 3, 'đều; đều đặn; cách đều nhau → evenly (/ˈiːvənli/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_80_23', 'en-b2-80', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “to lớn; đồ sộ; nặng nề”', '["massive","mechanism","curse","delicate"]'::jsonb, 0, 'to lớn; đồ sộ; nặng nề → massive (/ˈmæsɪv/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_80_24', 'en-b2-80', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cảm kích; biết ơn”', '["appreciate","multifunction","sideways","conquer"]'::jsonb, 0, 'cảm kích; biết ơn → appreciate (/əˈpriːʃieɪt/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-81', 'en', 'Bài 81: Đời sống hằng ngày (8) - CEFR B2', 'CEFR B2', 'B2 · Đời sống', '27 từ vựng Tiếng Anh CEFR B2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4081, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mitten', 'en-b2-81', 'mitten', '/ˈmɪtən/', 'B2', 'găng tay hở ngón/găng tay trùm (có ngăn riêng cho ngón cái và một ngăn chung cho bốn ngón kia)', 'n.', NULL, NULL, 'Găng tay có ngăn chung cho bốn ngón và ngón cái tách riêng, không phải loại găng tay hở đầu ngón.', 'She dropped a woollen mitten beside the snowy path.', NULL, 'Cô ấy đánh rơi một chiếc găng tay len ở cạnh con đường phủ đầy tuyết.', '{"wordId":"mitten","ukIpa":"/ˈmɪtən/","usIpa":"/ˈmɪtən/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A glove with one section for fingers and another for the thumb.","vi":"găng tay hở ngón/găng tay trùm (có ngăn riêng cho ngón cái và một ngăn chung cho bốn ngón kia)"}],"examples":[{"en":"She dropped a woollen mitten beside the snowy path.","vi":"Cô ấy đánh rơi một chiếc găng tay len ở cạnh con đường phủ đầy tuyết.","audioKind":"ex"},{"en":"In cold climates, insulated mittens help outdoor workers maintain hand warmth during prolonged exposure to low temperatures.","vi":"Ở những vùng khí hậu lạnh, găng tay giữ nhiệt giúp những người làm việc ngoài trời giữ ấm đôi tay trong điều kiện tiếp xúc lâu với nhiệt độ thấp.","audioKind":"ex2"}],"collocations":[{"en":"a pair of mittens","vi":"một đôi găng tay trùm"},{"en":"woollen mittens","vi":"găng tay len"},{"en":"insulated mittens","vi":"găng tay giữ nhiệt"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Găng tay có ngăn chung cho bốn ngón và ngón cái tách riêng, không phải loại găng tay hở đầu ngón.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plaster', 'en-b2-81', 'plaster', '/ˈplæstər/', 'B2', 'vữa; lớp trát tường; thạch cao; băng cá nhân; trát vữa; đắp thạch cao', 'n.', 'plasterer (n.), plastering (n.)', NULL, 'Khi mang nghĩa vữa, từ này thường không đếm được; trong tiếng Anh Anh, a plaster dùng để chỉ miếng băng cá nhân nhỏ.', 'Small pieces of plaster fell from the kitchen ceiling.', NULL, 'Những mảnh vữa nhỏ rơi từ trần nhà bếp xuống.', '{"wordId":"plaster","ukIpa":"/ˈplɑːstə/","usIpa":"/ˈplæstər/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"a mixture that hardens, used for walls, ceilings, or casts","vi":"vữa; lớp trát tường; thạch cao"},{"pos":"n.","en":"a small sticky covering used to protect a minor wound","vi":"băng cá nhân"},{"pos":"v.","en":"cover a surface with plaster","vi":"trát vữa; đắp thạch cao"}],"examples":[{"en":"Small pieces of plaster fell from the kitchen ceiling.","vi":"Những mảnh vữa nhỏ rơi từ trần nhà bếp xuống.","audioKind":"ex"},{"en":"Restoring historic buildings often requires skilled workers who can repair damaged plaster without harming original decorative features.","vi":"Việc trùng tu các công trình lịch sử thường đòi hỏi những người thợ lành nghề có khả năng sửa chữa lớp vữa bị hư hỏng mà không làm tổn hại đến các chi tiết trang trí ban đầu.","audioKind":"ex2"}],"collocations":[{"en":"a coat of plaster","vi":"một lớp vữa"},{"en":"plaster cast","vi":"bó bột thạch cao"},{"en":"sticking plaster","vi":"băng cá nhân"},{"en":"plaster a wall","vi":"trát vữa lên tường"}],"wordFamily":["plasterer (n.)","plastering (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi mang nghĩa vữa, từ này thường không đếm được; trong tiếng Anh Anh, a plaster dùng để chỉ miếng băng cá nhân nhỏ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_refreshing', 'en-b2-81', 'refreshing', '/rɪˈfreʃɪŋ/', 'B2', 'làm mát lạnh; sảng khoái; tỉnh táo; mới mẻ; mang tính đột phá', 'adj.', 'refresh (v.), refreshed (adj.), refreshment (n.)', 'Đồng nghĩa: invigorating, revitalising', 'Tính từ refreshing thường dùng để miêu tả sự vật, sự việc; trong khi refreshed dùng để miêu tả cảm giác sảng khoái của con người.', 'A refreshing breeze blew through the open kitchen window.', NULL, 'Một cơn gió mát rượi thổi qua khung cửa sổ nhà bếp đang mở.', '{"wordId":"refreshing","ukIpa":"/rɪˈfreʃɪŋ/","usIpa":"/rɪˈfreʃɪŋ/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"making you feel cooler, less tired, or more energetic","vi":"làm mát lạnh; sảng khoái; tỉnh táo"},{"pos":"adj.","en":"pleasantly different from what you usually experience","vi":"mới mẻ; mang tính đột phá"}],"examples":[{"en":"A refreshing breeze blew through the open kitchen window.","vi":"Một cơn gió mát rượi thổi qua khung cửa sổ nhà bếp đang mở.","audioKind":"ex"},{"en":"The documentary offers a refreshing perspective on how older people contribute to their local communities.","vi":"Bộ phim tài liệu mang lại một góc nhìn mới mẻ về cách người cao tuổi đóng góp cho cộng đồng địa phương của họ.","audioKind":"ex2"}],"collocations":[{"en":"refreshing drink","vi":"đồ uống giải khát"},{"en":"refreshing change","vi":"sự thay đổi mới mẻ"},{"en":"refreshing breeze","vi":"cơn gió mát lành"}],"wordFamily":["refresh (v.)","refreshed (adj.)","refreshment (n.)"],"synonyms":["invigorating","revitalising"],"antonyms":[],"tipVi":"Tính từ refreshing thường dùng để miêu tả sự vật, sự việc; trong khi refreshed dùng để miêu tả cảm giác sảng khoái của con người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_liquor', 'en-b2-81', 'liquor', '/ˈlɪkər/', 'B2', 'rượu mạnh', 'n.', NULL, 'Đồng nghĩa: spirits', 'Thường chỉ rượu mạnh; "liqueur" dùng để chỉ rượu mùi, cần chú ý cách viết.', 'The restaurant keeps its liquor in a locked cabinet.', NULL, 'Nhà hàng cất giữ rượu mạnh trong một chiếc tủ có khóa.', '{"wordId":"liquor","ukIpa":"/ˈlɪkə/","usIpa":"/ˈlɪkər/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"Strong alcoholic drink made by distillation.","vi":"rượu mạnh"}],"examples":[{"en":"The restaurant keeps its liquor in a locked cabinet.","vi":"Nhà hàng cất giữ rượu mạnh trong một chiếc tủ có khóa.","audioKind":"ex"},{"en":"Governments often impose higher taxes on liquor to discourage excessive consumption and protect public health.","vi":"Chính phủ thường áp mức thuế cao hơn đối với rượu mạnh nhằm hạn chế tình trạng tiêu thụ quá mức và bảo vệ sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"hard liquor","vi":"rượu mạnh"},{"en":"liquor licence","vi":"giấy phép bán rượu"},{"en":"liquor store","vi":"cửa hàng bán rượu"}],"wordFamily":[],"synonyms":["spirits"],"antonyms":[],"tipVi":"Thường chỉ rượu mạnh; \"liqueur\" dùng để chỉ rượu mùi, cần chú ý cách viết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_selection', 'en-b2-81', 'selection', '/sɪˈlekʃən/', 'B2', 'sự lựa chọn; sự tuyển chọn; danh mục; sự đa dạng; tuyển tập; vật được chọn lọc', 'n.', 'select (v.), selective (adj.), selectively (adv.)', 'Đồng nghĩa: choice, assortment', 'Khi chỉ quá trình lựa chọn thì thường không đếm được; khi chỉ một tập hợp các lựa chọn thì có thể đếm được.', 'This little bakery has a wonderful selection of fresh bread.', NULL, 'Tiệm bánh nhỏ này có rất nhiều loại bánh mì tươi ngon để lựa chọn.', '{"wordId":"selection","ukIpa":"/sɪˈlekʃən/","usIpa":"/sɪˈlekʃən/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"The process of choosing someone or something","vi":"sự lựa chọn; sự tuyển chọn"},{"pos":"n.","en":"A range of things available to choose from","vi":"danh mục; sự đa dạng"},{"pos":"n.","en":"A group of things chosen from a larger collection","vi":"tuyển tập; vật được chọn lọc"}],"examples":[{"en":"This little bakery has a wonderful selection of fresh bread.","vi":"Tiệm bánh nhỏ này có rất nhiều loại bánh mì tươi ngon để lựa chọn.","audioKind":"ex"},{"en":"Transparent selection procedures can help universities offer places fairly to applicants from a wide range of backgrounds.","vi":"Quy trình tuyển chọn minh bạch có thể giúp các trường đại học trao cơ hội công bằng cho các ứng viên đến từ nhiều hoàn cảnh khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"selection criteria","vi":"tiêu chí tuyển chọn"},{"en":"a wide selection of","vi":"nhiều sự lựa chọn đa dạng"},{"en":"the selection process","vi":"quy trình tuyển chọn"},{"en":"natural selection","vi":"chọn lọc tự nhiên"}],"wordFamily":["select (v.)","selective (adj.)","selectively (adv.)"],"synonyms":["choice","assortment"],"antonyms":[],"tipVi":"Khi chỉ quá trình lựa chọn thì thường không đếm được; khi chỉ một tập hợp các lựa chọn thì có thể đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_outwards', 'en-b2-81', 'outwards', '/ˈaʊtwɚdz/', 'B2', 'hướng ra ngoài; ra phía ngoài', 'adv.', 'outward (adj.)', 'Đồng nghĩa: outward · Trái nghĩa: inwards', '"outwards" là trạng từ; khi đóng vai trò là tính từ đứng trước danh từ, cần dùng "outward".', 'The windows open outwards, so keep the balcony clear.', NULL, 'Các cửa sổ mở hướng ra ngoài, vì vậy hãy giữ cho ban công thoáng đãng.', '{"wordId":"outwards","ukIpa":"/ˈaʊtwədz/","usIpa":"/ˈaʊtwɚdz/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"Towards the outside or away from the centre","vi":"hướng ra ngoài; ra phía ngoài"}],"examples":[{"en":"The windows open outwards, so keep the balcony clear.","vi":"Các cửa sổ mở hướng ra ngoài, vì vậy hãy giữ cho ban công thoáng đãng.","audioKind":"ex"},{"en":"As cities expand outwards, surrounding farmland often disappears, creating concerns about food security and habitat loss.","vi":"Khi các thành phố mở rộng ra vùng ven, đất nông nghiệp xung quanh thường biến mất, gây ra những lo ngại về an ninh lương thực và sự mất mát môi trường sống.","audioKind":"ex2"}],"collocations":[{"en":"open outwards","vi":"mở hướng ra ngoài"},{"en":"spread outwards","vi":"lan rộng ra bên ngoài"},{"en":"face outwards","vi":"hướng mặt ra ngoài"},{"en":"expand outwards","vi":"mở rộng ra vùng ven"}],"wordFamily":["outward (adj.)"],"synonyms":["outward"],"antonyms":["inwards"],"tipVi":"\"outwards\" là trạng từ; khi đóng vai trò là tính từ đứng trước danh từ, cần dùng \"outward\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_resemblance', 'en-b2-81', 'resemblance', '/rɪˈzembləns/', 'B2', 'sự giống nhau; nét tương đồng', 'n.', 'resemble (v.)', 'Đồng nghĩa: similarity, likeness · Trái nghĩa: dissimilarity', 'resemblance to đi kèm đối tượng so sánh; resemble đi thẳng với tân ngữ.', 'There is a striking resemblance between the two sisters.', NULL, 'Có một sự giống nhau đến kỳ lạ giữa hai chị em.', '{"wordId":"resemblance","ukIpa":"/rɪˈzembləns/","usIpa":"/rɪˈzembləns/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"similarity between people or things, especially in appearance","vi":"sự giống nhau; nét tương đồng"}],"examples":[{"en":"There is a striking resemblance between the two sisters.","vi":"Có một sự giống nhau đến kỳ lạ giữa hai chị em.","audioKind":"ex"},{"en":"Modern housing developments often bear little resemblance to traditional neighbourhoods, particularly in their layout and use of shared space.","vi":"Các khu nhà ở hiện đại thường rất ít điểm tương đồng với các khu phố truyền thống, đặc biệt là về mặt bố cục và cách sử dụng không gian chung.","audioKind":"ex2"}],"collocations":[{"en":"bear a resemblance to","vi":"có nét giống với"},{"en":"a striking resemblance","vi":"sự giống nhau đến kinh ngạc"},{"en":"a family resemblance","vi":"nét giống nhau trong gia đình"}],"wordFamily":["resemble (v.)"],"synonyms":["similarity","likeness"],"antonyms":["dissimilarity"],"tipVi":"resemblance to đi kèm đối tượng so sánh; resemble đi thẳng với tân ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_firewood', 'en-b2-81', 'firewood', '/ˈfaɪərwʊd/', 'B2', 'củi; củi đun', 'n.', NULL, NULL, 'Danh từ không đếm được; một khúc củi có thể nói là a piece of firewood.', 'We stacked dry firewood beside the stove before dinner.', NULL, 'Chúng tôi xếp củi khô bên cạnh lò sưởi trước bữa tối.', '{"wordId":"firewood","ukIpa":"/ˈfaɪəwʊd/","usIpa":"/ˈfaɪərwʊd/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"Wood collected or cut for burning as fuel.","vi":"củi; củi đun"}],"examples":[{"en":"We stacked dry firewood beside the stove before dinner.","vi":"Chúng tôi xếp củi khô bên cạnh lò sưởi trước bữa tối.","audioKind":"ex"},{"en":"In some rural communities, dependence on firewood for cooking can contribute to deforestation and indoor air pollution.","vi":"Ở một số cộng đồng nông thôn, việc phụ thuộc vào củi để nấu nướng có thể góp phần làm nạn phá rừng và gây ô nhiễm không khí trong nhà.","audioKind":"ex2"}],"collocations":[{"en":"collect firewood","vi":"thu gom củi"},{"en":"chop firewood","vi":"bổ củi"},{"en":"a bundle of firewood","vi":"một bó củi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ không đếm được; một khúc củi có thể nói là a piece of firewood.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_considerable', 'en-b2-81', 'considerable', '/kənˈsɪdərəbl/', 'B2', 'đáng kể; lớn; nhiều', 'adj.', 'considerably (adv.)', 'Đồng nghĩa: substantial, significant · Trái nghĩa: negligible', 'considerable chỉ số lượng hoặc mức độ lớn; considerate chỉ sự chu đáo, ân cần.', 'Repairing the roof took considerable time and effort.', NULL, 'Việc sửa chữa mái nhà đã tốn nhiều thời gian và công sức đáng kể.', '{"wordId":"considerable","ukIpa":"/kənˈsɪdərəbl/","usIpa":"/kənˈsɪdərəbl/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Large in amount, size, or degree.","vi":"đáng kể; lớn; nhiều"}],"examples":[{"en":"Repairing the roof took considerable time and effort.","vi":"Việc sửa chữa mái nhà đã tốn nhiều thời gian và công sức đáng kể.","audioKind":"ex"},{"en":"Expanding public transport requires considerable investment, but it can reduce congestion and improve urban air quality.","vi":"Việc mở rộng giao thông công cộng đòi hỏi nguồn đầu tư lớn, nhưng nó có thể làm giảm ùn tắc và cải thiện chất lượng không khí đô thị.","audioKind":"ex2"}],"collocations":[{"en":"considerable amount","vi":"số lượng đáng kể"},{"en":"considerable effort","vi":"nỗ lực đáng kể"},{"en":"considerable impact","vi":"tác động đáng kể"},{"en":"considerable progress","vi":"tiến bộ đáng kể"}],"wordFamily":["considerably (adv.)"],"synonyms":["substantial","significant"],"antonyms":["negligible"],"tipVi":"considerable chỉ số lượng hoặc mức độ lớn; considerate chỉ sự chu đáo, ân cần.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shield', 'en-b2-81', 'shield', '/ʃiːld/', 'B2', 'khiên; vật che chắn; bảo vệ; che chắn', 'n.', 'shielding (n.)', 'Đồng nghĩa: protect, guard', 'Động từ thường dùng cấu trúc shield someone from something.', 'The worker lowered a clear shield over her face.', NULL, 'Người công nhân hạ tấm chắn trong suốt xuống trước mặt để bảo vệ khuôn mặt.', '{"wordId":"shield","ukIpa":"/ʃiːld/","usIpa":"/ʃiːld/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"An object that protects someone or something from harm.","vi":"khiên; vật che chắn"},{"pos":"v.","en":"To protect someone or something from harm or exposure.","vi":"bảo vệ; che chắn"}],"examples":[{"en":"The worker lowered a clear shield over her face.","vi":"Người công nhân hạ tấm chắn trong suốt xuống trước mặt để bảo vệ khuôn mặt.","audioKind":"ex"},{"en":"Urban trees can shield pedestrians from intense sunlight while reducing temperatures in densely populated neighbourhoods.","vi":"Cây xanh đô thị có thể che chắn cho người đi bộ khỏi ánh nắng gắt đồng thời làm giảm nhiệt độ ở những khu phố đông dân cư.","audioKind":"ex2"}],"collocations":[{"en":"a face shield","vi":"mặt nạ bảo hộ"},{"en":"a protective shield","vi":"tấm chắn bảo vệ"},{"en":"shield someone from harm","vi":"bảo vệ ai đó khỏi nguy hiểm"}],"wordFamily":["shielding (n.)"],"synonyms":["protect","guard"],"antonyms":[],"tipVi":"Động từ thường dùng cấu trúc shield someone from something.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hint', 'en-b2-81', 'hint', '/hɪnt/', 'B2', 'gợi ý; lời ám chỉ; ám chỉ; bóng gió; chút ít; một ít', 'n.', NULL, 'Đồng nghĩa: clue, suggestion', 'Động từ thường dùng hint at sth hoặc mệnh đề với hint that.', 'Give me a hint about where you hid the gift.', NULL, 'Cho tôi một gợi ý về việc bạn giấu món quà ở đâu đi.', '{"wordId":"hint","ukIpa":"/hɪnt/","usIpa":"/hɪnt/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"An indirect suggestion or clue that helps someone understand","vi":"gợi ý; lời ám chỉ"},{"pos":"v.","en":"To suggest something without stating it directly","vi":"ám chỉ; bóng gió"},{"pos":"n.","en":"A very small amount or slight sign of something","vi":"chút ít; một ít"}],"examples":[{"en":"Give me a hint about where you hid the gift.","vi":"Cho tôi một gợi ý về việc bạn giấu món quà ở đâu đi.","audioKind":"ex"},{"en":"Survey responses hint at growing dissatisfaction with public transport, particularly among commuters living outside city centres.","vi":"Kết quả khảo sát ám chỉ sự bất mãn ngày càng tăng đối với giao thông công cộng, đặc biệt là trong số những người đi làm sống ngoài trung tâm thành phố.","audioKind":"ex2"}],"collocations":[{"en":"give someone a hint","vi":"gợi ý cho ai đó"},{"en":"take the hint","vi":"hiểu ý ngầm"},{"en":"hint at something","vi":"ám chỉ điều gì đó"},{"en":"a hint of lemon","vi":"thoảng hương chanh"}],"wordFamily":[],"synonyms":["clue","suggestion"],"antonyms":[],"tipVi":"Động từ thường dùng hint at sth hoặc mệnh đề với hint that.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_alter', 'en-b2-81', 'alter', '/ˈɔːltər/', 'B2', 'thay đổi; biến đổi; sửa lại quần áo cho vừa vặn hơn', 'v.', 'alteration (n.), unaltered (adj.)', 'Đồng nghĩa: change, modify', 'Có thể dùng như ngoại động từ hoặc nội động từ; tránh nhầm lẫn với altar (bàn thờ).', 'Could you alter these trousers so they fit better?', NULL, 'Bạn có thể sửa lại chiếc quần này cho vừa vặn hơn không?', '{"wordId":"alter","ukIpa":"/ˈɔːltə/","usIpa":"/ˈɔːltər/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To change, or make something different.","vi":"thay đổi; biến đổi"},{"pos":"v.","en":"To change clothing so that it fits better.","vi":"sửa lại quần áo cho vừa vặn hơn"}],"examples":[{"en":"Could you alter these trousers so they fit better?","vi":"Bạn có thể sửa lại chiếc quần này cho vừa vặn hơn không?","audioKind":"ex"},{"en":"Rising temperatures may alter rainfall patterns and create serious challenges for farmers in dry regions.","vi":"Nhiệt độ tăng cao có thể làm thay đổi các hình thái lượng mưa và tạo ra những thách thức nghiêm trọng cho nông dân ở các vùng khô hạn.","audioKind":"ex2"}],"collocations":[{"en":"alter plans","vi":"thay đổi kế hoạch"},{"en":"alter significantly","vi":"thay đổi đáng kể"},{"en":"alter the appearance","vi":"thay đổi diện mạo"}],"wordFamily":["alteration (n.)","unaltered (adj.)"],"synonyms":["change","modify"],"antonyms":[],"tipVi":"Có thể dùng như ngoại động từ hoặc nội động từ; tránh nhầm lẫn với altar (bàn thờ).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_anticlockwise', 'en-b2-81', 'anticlockwise', '/ˌæntiˈklɑːkwaɪz/', 'B2', 'ngược chiều kim đồng hồ; theo hướng ngược chiều kim đồng hồ', 'adv.', 'clockwise (adv.), clockwise (adj.)', 'Đồng nghĩa: counterclockwise · Trái nghĩa: clockwise', 'Tiếng Anh-Anh thường dùng anticlockwise, trong khi tiếng Anh-Mỹ thường dùng counterclockwise.', 'Turn the lid anticlockwise to open the jar.', NULL, 'Xoay nắp theo chiều ngược kim đồng hồ để mở hũ ra.', '{"wordId":"anticlockwise","ukIpa":"/ˌæntiˈklɒkwaɪz/","usIpa":"/ˌæntiˈklɑːkwaɪz/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"In the opposite direction to the movement of clock hands","vi":"ngược chiều kim đồng hồ"},{"pos":"adj.","en":"Moving opposite to the direction of clock hands","vi":"theo hướng ngược chiều kim đồng hồ"}],"examples":[{"en":"Turn the lid anticlockwise to open the jar.","vi":"Xoay nắp theo chiều ngược kim đồng hồ để mở hũ ra.","audioKind":"ex"},{"en":"In the experiment, participants rotated a handle anticlockwise while researchers measured changes in muscle activity.","vi":"Trong thí nghiệm, những người tham gia đã xoay một tay nắm theo chiều ngược kim đồng hồ trong khi các nhà nghiên cứu đo lường sự thay đổi hoạt động cơ bắp.","audioKind":"ex2"}],"collocations":[{"en":"turn anticlockwise","vi":"xoay ngược chiều kim đồng hồ"},{"en":"rotate anticlockwise","vi":"quay ngược chiều kim đồng hồ"},{"en":"an anticlockwise direction","vi":"hướng ngược chiều kim đồng hồ"}],"wordFamily":["clockwise (adv.)","clockwise (adj.)"],"synonyms":["counterclockwise"],"antonyms":["clockwise"],"tipVi":"Tiếng Anh-Anh thường dùng anticlockwise, trong khi tiếng Anh-Mỹ thường dùng counterclockwise.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_seldom', 'en-b2-81', 'seldom', '/ˈseldəm/', 'B2', 'hiếm khi, không thường xuyên', 'adv.', NULL, 'Đồng nghĩa: rarely, infrequently · Trái nghĩa: often, frequently', 'Trạng từ này thường đứng trước động từ thường và sau động từ to be; khi đặt đầu câu thường phải đảo ngữ.', 'We seldom eat out because we enjoy cooking together.', NULL, 'Chúng tôi hiếm khi đi ăn ngoài vì thích tự nấu ăn cùng nhau.', '{"wordId":"seldom","ukIpa":"/ˈseldəm/","usIpa":"/ˈseldəm/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"Not often; on very few occasions.","vi":"hiếm khi, không thường xuyên"}],"examples":[{"en":"We seldom eat out because we enjoy cooking together.","vi":"Chúng tôi hiếm khi đi ăn ngoài vì thích tự nấu ăn cùng nhau.","audioKind":"ex"},{"en":"Rural communities seldom receive the same level of public transport investment as major urban centres.","vi":"Các vùng nông thôn hiếm khi nhận được mức độ đầu tư giao thông công cộng tương đương với các trung tâm đô thị lớn.","audioKind":"ex2"}],"collocations":[{"en":"seldom seen","vi":"hiếm khi thấy"},{"en":"seldom used","vi":"ít khi được sử dụng"},{"en":"seldom occur","vi":"hiếm khi xảy ra"}],"wordFamily":[],"synonyms":["rarely","infrequently"],"antonyms":["often","frequently"],"tipVi":"Trạng từ này thường đứng trước động từ thường và sau động từ to be; khi đặt đầu câu thường phải đảo ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sparkling', 'en-b2-81', 'sparkling', '/ˈspɑːrklɪŋ/', 'B2', 'lấp lánh, sáng lấp lánh với nhiều tia sáng nhỏ; có gas, chứa các bọt khí; sống động, thông minh và đầy thú vị', 'adj.', 'sparkle (v.), sparkle (n.)', 'Đồng nghĩa: glittering, fizzy · Trái nghĩa: still', 'Trong đồ uống, sparkling dùng để chỉ nước có gas, trong khi still dùng cho nước không gas.', 'She held the sparkling bracelet up to the sunlight.', NULL, 'Cô ấy giơ chiếc vòng tay lấp lánh lên dưới ánh nắng mặt trời.', '{"wordId":"sparkling","ukIpa":"/ˈspɑːklɪŋ/","usIpa":"/ˈspɑːrklɪŋ/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"shining with many small flashes of light","vi":"lấp lánh, sáng lấp lánh với nhiều tia sáng nhỏ"},{"pos":"adj.","en":"containing bubbles of gas","vi":"có gas, chứa các bọt khí"},{"pos":"adj.","en":"lively, clever, and entertaining","vi":"sống động, thông minh và đầy thú vị"}],"examples":[{"en":"She held the sparkling bracelet up to the sunlight.","vi":"Cô ấy giơ chiếc vòng tay lấp lánh lên dưới ánh nắng mặt trời.","audioKind":"ex"},{"en":"Restaurants can reduce packaging waste by serving locally filtered sparkling water rather than imported bottled alternatives.","vi":"Các nhà hàng có thể giảm rác thải bao bì bằng cách phục vụ nước có gas được lọc tại chỗ thay vì dùng nước đóng chai nhập khẩu.","audioKind":"ex2"}],"collocations":[{"en":"sparkling water","vi":"nước khoáng có gas"},{"en":"sparkling eyes","vi":"ánh mắt lấp lánh"},{"en":"sparkling conversation","vi":"cuộc trò chuyện thú vị"}],"wordFamily":["sparkle (v.)","sparkle (n.)"],"synonyms":["glittering","fizzy"],"antonyms":["still"],"tipVi":"Trong đồ uống, sparkling dùng để chỉ nước có gas, trong khi still dùng cho nước không gas.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reverse', 'en-b2-81', 'reverse', '/rɪˈvɝːs/', 'B2', 'đảo ngược, đổi chiều, lùi xe; trái ngược, ngược lại hướng hoặc thứ tự; tình trạng trái ngược, mặt sau', 'v.', 'reversal (n.), reversible (adj.), irreversible (adj.)', NULL, 'Hành động lùi xe dùng từ reverse; hủy bỏ một quyết định có thể dùng reverse a decision.', 'He reversed the car slowly into the garage.', NULL, 'Anh ấy từ từ lùi xe vào trong gara.', '{"wordId":"reverse","ukIpa":"/rɪˈvɜːs/","usIpa":"/rɪˈvɝːs/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to change something to its opposite, or move backwards","vi":"đảo ngược, đổi chiều, lùi xe"},{"pos":"adj.","en":"going in the opposite direction or order","vi":"trái ngược, ngược lại hướng hoặc thứ tự"},{"pos":"n.","en":"the opposite of something, or its back surface","vi":"tình trạng trái ngược, mặt sau"}],"examples":[{"en":"He reversed the car slowly into the garage.","vi":"Anh ấy từ từ lùi xe vào trong gara.","audioKind":"ex"},{"en":"Investment in renewable energy could help reverse the recent rise in emissions from electricity generation.","vi":"Việc đầu tư vào năng lượng tái tạo có thể giúp đảo ngược xu hướng gia tăng lượng khí thải từ việc phát điện trong thời gian gần đây.","audioKind":"ex2"}],"collocations":[{"en":"reverse a decision","vi":"thu hồi quyết định"},{"en":"reverse a trend","vi":"đảo ngược xu thế"},{"en":"in reverse order","vi":"theo thứ tự ngược lại"},{"en":"the reverse side","vi":"mặt sau"}],"wordFamily":["reversal (n.)","reversible (adj.)","irreversible (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Hành động lùi xe dùng từ reverse; hủy bỏ một quyết định có thể dùng reverse a decision.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_upon', 'en-b2-81', 'upon', '/əˈpɑːn/', 'B2', 'trên (thường dùng trong văn phong trang trọng hoặc văn chương); ngay sau khi; vào lúc', 'prep.', NULL, 'Đồng nghĩa: on', 'Mang tính trang trọng hơn on; cấu trúc upon doing diễn đạt ý nghĩa "vừa... thì..." hoặc "ngay khi...".', 'The cat rested upon a cushion beside the window.', NULL, 'Con mèo nằm nghỉ trên chiếc đệm cạnh cửa sổ.', '{"wordId":"upon","ukIpa":"/əˈpɒn/","usIpa":"/əˈpɑːn/","cefr":"B2","topic":"daily","senses":[{"pos":"prep.","en":"on something, especially in formal or literary language","vi":"trên (thường dùng trong văn phong trang trọng hoặc văn chương)"},{"pos":"prep.","en":"immediately after or at the time of an event","vi":"ngay sau khi; vào lúc"}],"examples":[{"en":"The cat rested upon a cushion beside the window.","vi":"Con mèo nằm nghỉ trên chiếc đệm cạnh cửa sổ.","audioKind":"ex"},{"en":"Upon completing their training, new teachers should receive ongoing support from experienced colleagues at school.","vi":"Ngay sau khi hoàn thành khóa đào tạo, các giáo viên mới nên nhận được sự hỗ trợ liên tục từ các đồng nghiệp giàu kinh nghiệm tại trường.","audioKind":"ex2"}],"collocations":[{"en":"upon arrival","vi":"ngay khi đến"},{"en":"upon completion","vi":"ngay khi hoàn thành"},{"en":"once upon a time","vi":"ngày xửa ngày xưa"}],"wordFamily":[],"synonyms":["on"],"antonyms":[],"tipVi":"Mang tính trang trọng hơn on; cấu trúc upon doing diễn đạt ý nghĩa \"vừa... thì...\" hoặc \"ngay khi...\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_combination', 'en-b2-81', 'combination', '/ˌkɑːmbɪˈneɪʃən/', 'B2', 'sự kết hợp; sự phối hợp; mã số (để mở khóa)', 'n.', 'combine (v.), combined (adj.)', 'Đồng nghĩa: mixture, blend', 'Thường dùng a combination of A and B để chỉ sự kết hợp giữa hai yếu tố.', 'This soup has a delicious combination of herbs and vegetables.', NULL, 'Món súp này là sự kết hợp tuyệt vời giữa các loại rau thơm và rau củ.', '{"wordId":"combination","ukIpa":"/ˌkɒmbɪˈneɪʃən/","usIpa":"/ˌkɑːmbɪˈneɪʃən/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"two or more things joined or used together","vi":"sự kết hợp; sự phối hợp"},{"pos":"n.","en":"a sequence used to open a lock","vi":"mã số (để mở khóa)"}],"examples":[{"en":"This soup has a delicious combination of herbs and vegetables.","vi":"Món súp này là sự kết hợp tuyệt vời giữa các loại rau thơm và rau củ.","audioKind":"ex"},{"en":"A combination of affordable housing and reliable public transport can improve living standards in growing cities.","vi":"Sự kết hợp giữa nhà ở giá rẻ và hệ thống giao thông công cộng đáng tin cậy có thể nâng cao mức sống tại các đô thị đang phát triển.","audioKind":"ex2"}],"collocations":[{"en":"a combination of","vi":"sự kết hợp của"},{"en":"in combination with","vi":"kết hợp với"},{"en":"winning combination","vi":"sự kết hợp hoàn hảo"},{"en":"combination lock","vi":"khóa mã số"}],"wordFamily":["combine (v.)","combined (adj.)"],"synonyms":["mixture","blend"],"antonyms":[],"tipVi":"Thường dùng a combination of A and B để chỉ sự kết hợp giữa hai yếu tố.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_immense', 'en-b2-81', 'immense', '/ɪˈmens/', 'B2', 'to lớn; vô cùng; cực kỳ', 'adj.', 'immensely (adv.), immensity (n.)', 'Đồng nghĩa: enormous, vast, huge · Trái nghĩa: tiny', 'Có thể dùng để miêu tả kích thước vật lý hoặc mức độ của áp lực, tiềm năng.', 'An immense ship blocked our view of the harbour.', NULL, 'Một con tàu khổng lồ đã chắn mất tầm nhìn của chúng tôi ra cảng.', '{"wordId":"immense","ukIpa":"/ɪˈmens/","usIpa":"/ɪˈmens/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Extremely large in size, amount, or degree","vi":"to lớn; vô cùng; cực kỳ"}],"examples":[{"en":"An immense ship blocked our view of the harbour.","vi":"Một con tàu khổng lồ đã chắn mất tầm nhìn của chúng tôi ra cảng.","audioKind":"ex"},{"en":"The transition to renewable energy requires immense investment but can deliver substantial environmental and economic benefits.","vi":"Quá trình chuyển đổi sang năng lượng tái tạo đòi hỏi nguồn đầu tư khổng lồ nhưng có thể mang lại những lợi ích đáng kể về môi trường và kinh tế.","audioKind":"ex2"}],"collocations":[{"en":"immense pressure","vi":"áp lực lớn"},{"en":"immense potential","vi":"tiềm năng to lớn"},{"en":"immense satisfaction","vi":"sự thỏa mãn tột cùng"},{"en":"immense contribution","vi":"đóng góp to lớn"}],"wordFamily":["immensely (adv.)","immensity (n.)"],"synonyms":["enormous","vast","huge"],"antonyms":["tiny"],"tipVi":"Có thể dùng để miêu tả kích thước vật lý hoặc mức độ của áp lực, tiềm năng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fade', 'en-b2-81', 'fade', '/feɪd/', 'B2', 'phai màu; làm phai màu; giảm dần; mờ dần; mai một', 'v.', 'faded (adj.), fading (adj.)', 'Đồng nghĩa: diminish, wane · Trái nghĩa: intensify', 'Nhấn mạnh sự thay đổi dần dần; fade away chỉ sự suy yếu hoặc biến mất từ từ.', 'The curtains have faded after years of bright sunlight.', NULL, 'Tấm rèm cửa đã bị phai màu sau nhiều năm dưới ánh nắng gay gắt.', '{"wordId":"fade","ukIpa":"/feɪd/","usIpa":"/feɪd/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to lose colour or make something lose colour gradually","vi":"phai màu; làm phai màu"},{"pos":"v.","en":"to become weaker, less clear, or less noticeable over time","vi":"giảm dần; mờ dần; mai một"}],"examples":[{"en":"The curtains have faded after years of bright sunlight.","vi":"Tấm rèm cửa đã bị phai màu sau nhiều năm dưới ánh nắng gay gắt.","audioKind":"ex"},{"en":"Public interest in environmental campaigns may fade unless organisations provide regular updates and opportunities for participation.","vi":"Sự quan tâm của công chúng đối với các chiến dịch bảo vệ môi trường có thể giảm dần trừ khi các tổ chức thường xuyên cập nhật thông tin và tạo cơ hội tham gia.","audioKind":"ex2"}],"collocations":[{"en":"fade away","vi":"phai mờ dần"},{"en":"fade in the sun","vi":"phai màu dưới ánh nắng"},{"en":"memories fade","vi":"ký ức phai mờ"},{"en":"fade into the background","vi":"chìm vào quên lãng"}],"wordFamily":["faded (adj.)","fading (adj.)"],"synonyms":["diminish","wane"],"antonyms":["intensify"],"tipVi":"Nhấn mạnh sự thay đổi dần dần; fade away chỉ sự suy yếu hoặc biến mất từ từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sharpen', 'en-b2-81', 'sharpen', '/ˈʃɑːrpən/', 'B2', 'làm sắc; mài giũa; gọt nhọn; nâng cao; cải thiện; làm cho bén nhạy hơn', 'v.', 'sharp (adj.), sharpener (n.), sharply (adv.), sharpness (n.)', 'Đồng nghĩa: hone · Trái nghĩa: blunt', 'Động từ cấu thành từ tính từ sharp với hậu tố -en, ngoài ra còn dùng theo nghĩa bóng để chỉ việc trau dồi kỹ năng.', 'I sharpened my pencil before sketching the sleeping cat.', NULL, 'Tôi đã gọt bút chì trước khi phác thảo chú mèo đang ngủ.', '{"wordId":"sharpen","ukIpa":"/ˈʃɑːpən/","usIpa":"/ˈʃɑːrpən/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To make an edge or point sharper.","vi":"làm sắc; mài giũa; gọt nhọn"},{"pos":"v.","en":"To make a skill, sense, or quality more effective.","vi":"nâng cao; cải thiện; làm cho bén nhạy hơn"}],"examples":[{"en":"I sharpened my pencil before sketching the sleeping cat.","vi":"Tôi đã gọt bút chì trước khi phác thảo chú mèo đang ngủ.","audioKind":"ex"},{"en":"Classroom debates can sharpen students'' critical thinking skills by encouraging them to examine competing arguments.","vi":"Các cuộc tranh luận trên lớp có thể nâng cao kỹ năng tư duy phản biện của học sinh bằng cách khuyến khích các em xem xét các lập luận trái chiều.","audioKind":"ex2"}],"collocations":[{"en":"sharpen a pencil","vi":"gọt bút chì"},{"en":"sharpen a knife","vi":"mài dao"},{"en":"sharpen skills","vi":"nâng cao kỹ năng"},{"en":"sharpen focus","vi":"tăng cường sự tập trung"}],"wordFamily":["sharp (adj.)","sharpener (n.)","sharply (adv.)","sharpness (n.)"],"synonyms":["hone"],"antonyms":["blunt"],"tipVi":"Động từ cấu thành từ tính từ sharp với hậu tố -en, ngoài ra còn dùng theo nghĩa bóng để chỉ việc trau dồi kỹ năng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chunk', 'en-b2-81', 'chunk', '/tʃʌŋk/', 'B2', 'một miếng to, dày; phần lớn; một khoản đáng kể', 'n.', 'chunky (adj.)', 'Đồng nghĩa: piece, lump', 'Có thể chỉ một khối vật chất lớn hoặc một khoảng thời gian/tiền bạc đáng kể.', 'She dropped a chunk of cheese into the soup.', NULL, 'Cô ấy thả một miếng phô mai lớn vào nồi súp.', '{"wordId":"chunk","ukIpa":"/tʃʌŋk/","usIpa":"/tʃʌŋk/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A large, thick piece of something.","vi":"một miếng to, dày"},{"pos":"n.","en":"A substantial part of an amount or whole.","vi":"phần lớn; một khoản đáng kể"}],"examples":[{"en":"She dropped a chunk of cheese into the soup.","vi":"Cô ấy thả một miếng phô mai lớn vào nồi súp.","audioKind":"ex"},{"en":"Housing costs consume a large chunk of household income, leaving less money for education and leisure.","vi":"Chi phí nhà ở ngốn một phần lớn thu nhập gia đình, khiến tiền dành cho giáo dục và giải trí bị ít đi.","audioKind":"ex2"}],"collocations":[{"en":"a chunk of bread","vi":"một mẩu bánh mì lớn"},{"en":"a large chunk of","vi":"một phần lớn của"},{"en":"manageable chunks","vi":"các phần dễ quản lý"}],"wordFamily":["chunky (adj.)"],"synonyms":["piece","lump"],"antonyms":[],"tipVi":"Có thể chỉ một khối vật chất lớn hoặc một khoảng thời gian/tiền bạc đáng kể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disguise', 'en-b2-81', 'disguise', '/dɪsˈɡaɪz/', 'B2', 'ngụy trang; che giấu; sự ngụy trang; bộ cải trang', 'v.', 'disguised (adj.), undisguised (adj.)', 'Đồng nghĩa: conceal, camouflage · Trái nghĩa: reveal', 'Cấu trúc disguise oneself as theo sau là vai trò hoặc nhân vật được hóa trang.', 'Nadia disguised herself with a wig and oversized glasses.', NULL, 'Nadia đã ngụy trang bản thân bằng một bộ tóc giả và chiếc kính bản to.', '{"wordId":"disguise","ukIpa":"/dɪsˈɡaɪz/","usIpa":"/dɪsˈɡaɪz/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To change appearance or hide something''s true nature.","vi":"ngụy trang; che giấu"},{"pos":"n.","en":"Something worn or done to prevent recognition.","vi":"sự ngụy trang; bộ cải trang"}],"examples":[{"en":"Nadia disguised herself with a wig and oversized glasses.","vi":"Nadia đã ngụy trang bản thân bằng một bộ tóc giả và chiếc kính bản to.","audioKind":"ex"},{"en":"Attractive packaging can disguise poor product quality, making it harder for consumers to make informed choices.","vi":"Bao bì bắt mắt có thể che giấu chất lượng sản phẩm kém, khiến người tiêu dùng khó đưa ra lựa chọn sáng suốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"disguise yourself as","vi":"giả trang thành"},{"en":"in disguise","vi":"giả trang; che giấu"},{"en":"disguise the fact that","vi":"che giấu sự thật rằng"},{"en":"a blessing in disguise","vi":"trong cái rủi có cái may"}],"wordFamily":["disguised (adj.)","undisguised (adj.)"],"synonyms":["conceal","camouflage"],"antonyms":["reveal"],"tipVi":"Cấu trúc disguise oneself as theo sau là vai trò hoặc nhân vật được hóa trang.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hairpin', 'en-b2-81', 'hairpin', '/ˈherpɪn/', 'B2', 'kẹp tóc; trâm cài tóc; đoạn đường cong gấp khúc; khúc cua tay áo', 'n.', NULL, NULL, 'Cụm hairpin bend chỉ đoạn đường uốn lượn hình chiếc kẹp tóc, quay gấp ngược lại.', 'She secured her bun with a silver hairpin.', NULL, 'Cô ấy búi tóc lên và cố định bằng một chiếc trâm cài tóc bằng bạc.', '{"wordId":"hairpin","ukIpa":"/ˈheəpɪn/","usIpa":"/ˈherpɪn/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A thin bent pin used to hold hair in place.","vi":"kẹp tóc; trâm cài tóc"},{"pos":"n.","en":"A very sharp bend where a road nearly doubles back.","vi":"đoạn đường cong gấp khúc; khúc cua tay áo"}],"examples":[{"en":"She secured her bun with a silver hairpin.","vi":"Cô ấy búi tóc lên và cố định bằng một chiếc trâm cài tóc bằng bạc.","audioKind":"ex"},{"en":"Mountain roads with frequent hairpin bends require careful design to reduce accident risks and protect surrounding habitats.","vi":"Những con đường núi với các khúc cua tay áo liên tục đòi hỏi thiết kế cẩn thận nhằm giảm thiểu rủi ro tai nạn và bảo vệ hệ sinh thái xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"a silver hairpin","vi":"kẹp tóc bạc"},{"en":"hairpin bend","vi":"khúc cua tay áo"},{"en":"hairpin turn","vi":"chỗ ngoặt gấp"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm hairpin bend chỉ đoạn đường uốn lượn hình chiếc kẹp tóc, quay gấp ngược lại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_trim', 'en-b2-81', 'trim', '/trɪm/', 'B2', 'cắt tỉa; cắt bớt một chút để làm gọn gàng hoặc giảm bớt; động tác cắt tỉa gọn gàng; đường viền trang trí; gọn gàng, ngăn nắp; thon thả và khỏe khoắn', 'v.', 'trimming (n.)', NULL, 'Thể quá khứ trimmed và phân từ hiện tại trimming đều được gấp đôi chữ cái m.', 'I trim the hedge before it blocks our window.', NULL, 'Tôi cắt tỉa hàng rào trước khi nó che khuất cửa sổ nhà chúng tôi.', '{"wordId":"trim","ukIpa":"/trɪm/","usIpa":"/trɪm/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To remove small amounts to neaten something or reduce it.","vi":"cắt tỉa; cắt bớt một chút để làm gọn gàng hoặc giảm bớt"},{"pos":"n.","en":"A small cut to neaten something, or decorative edging.","vi":"động tác cắt tỉa gọn gàng; đường viền trang trí"},{"pos":"adj.","en":"Neat in appearance, or slim and physically fit.","vi":"gọn gàng, ngăn nắp; thon thả và khỏe khoắn"}],"examples":[{"en":"I trim the hedge before it blocks our window.","vi":"Tôi cắt tỉa hàng rào trước khi nó che khuất cửa sổ nhà chúng tôi.","audioKind":"ex"},{"en":"Local authorities can trim operating costs by improving energy efficiency in public buildings rather than reducing essential services.","vi":"Chính quyền địa phương có thể cắt giảm chi phí vận hành bằng cách nâng cao hiệu quả năng lượng tại các tòa nhà công cộng thay vì cắt giảm các dịch vụ thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"trim a hedge","vi":"cắt tỉa hàng rào"},{"en":"trim costs","vi":"cắt giảm chi phí"},{"en":"a quick trim","vi":"cắt tỉa nhanh gọn"},{"en":"keep trim","vi":"giữ dáng thon gọn"}],"wordFamily":["trimming (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thể quá khứ trimmed và phân từ hiện tại trimming đều được gấp đôi chữ cái m.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_barely', 'en-b2-81', 'barely', '/ˈberli/', 'B2', 'hầu như không; vừa mới; suýt nữa thì không; chỉ vừa đủ; không vượt quá một lượng nhỏ hoặc giới hạn nhất định', 'adv.', 'bare (adj.)', 'Đồng nghĩa: hardly, scarcely', 'Bản thân từ này đã mang nghĩa phủ định, do đó thường không đi kèm với từ not.', 'I could barely hear her above the heavy rain.', NULL, 'Tôi hầu như không nghe thấy cô ấy nói gì giữa tiếng mưa lớn.', '{"wordId":"barely","ukIpa":"/ˈbeəli/","usIpa":"/ˈberli/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"Only just; almost not","vi":"hầu như không; vừa mới; suýt nữa thì không"},{"pos":"adv.","en":"No more than a small amount or a particular limit","vi":"chỉ vừa đủ; không vượt quá một lượng nhỏ hoặc giới hạn nhất định"}],"examples":[{"en":"I could barely hear her above the heavy rain.","vi":"Tôi hầu như không nghe thấy cô ấy nói gì giữa tiếng mưa lớn.","audioKind":"ex"},{"en":"Many low-income households can barely afford basic necessities, leaving little money for education or preventive healthcare.","vi":"Nhiều hộ gia đình thu nhập thấp hầu như chỉ đủ khả năng trang trải nhu cầu thiết yếu cơ bản, còn lại rất ít tiền cho giáo dục hoặc chăm sóc sức khỏe dự phòng.","audioKind":"ex2"}],"collocations":[{"en":"barely visible","vi":"hầu như không nhìn thấy"},{"en":"barely enough","vi":"vừa đủ; suýt soát"},{"en":"barely survive","vi":"vừa đủ sống; duy trì sự sống chật vật"},{"en":"barely notice","vi":"hầu như không nhận ra"}],"wordFamily":["bare (adj.)"],"synonyms":["hardly","scarcely"],"antonyms":[],"tipVi":"Bản thân từ này đã mang nghĩa phủ định, do đó thường không đi kèm với từ not.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_portion', 'en-b2-81', 'portion', '/ˈpɔːrʃən/', 'B2', 'một phần, một phần của cái lớn hơn; suất ăn, phần ăn phục vụ cho một người; chia nhỏ, phân chia thành các phần cho những người khác nhau', 'n.', NULL, 'Đồng nghĩa: part, share · Trái nghĩa: whole', 'portion có thể chỉ một phần của tổng thể, hoặc thường dùng chỉ suất ăn cho một người.', 'A large portion of our garden is shaded.', NULL, 'Một phần lớn khu vườn của chúng tôi bị che khuất bởi bóng râm.', '{"wordId":"portion","ukIpa":"/ˈpɔːʃən/","usIpa":"/ˈpɔːrʃən/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A part or share of something larger.","vi":"một phần, một phần của cái lớn hơn"},{"pos":"n.","en":"An amount of food served to one person.","vi":"suất ăn, phần ăn phục vụ cho một người"},{"pos":"v.","en":"To divide food into amounts for different people.","vi":"chia nhỏ, phân chia thành các phần cho những người khác nhau"}],"examples":[{"en":"A large portion of our garden is shaded.","vi":"Một phần lớn khu vườn của chúng tôi bị che khuất bởi bóng râm.","audioKind":"ex"},{"en":"Housing costs consume a substantial portion of household income, particularly in cities with limited affordable accommodation.","vi":"Chi phí nhà ở chiếm một phần đáng kể trong thu nhập của các hộ gia đình, đặc biệt là ở những thành phố có ít nhà ở giá rẻ.","audioKind":"ex2"}],"collocations":[{"en":"a large portion of","vi":"một phần lớn của"},{"en":"a substantial portion","vi":"một phần đáng kể"},{"en":"generous portions","vi":"khẩu phần ăn thịnh soạn"},{"en":"portion size","vi":"kích cỡ phần ăn"}],"wordFamily":[],"synonyms":["part","share"],"antonyms":["whole"],"tipVi":"portion có thể chỉ một phần của tổng thể, hoặc thường dùng chỉ suất ăn cho một người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_81_1', 'en-b2-81', 'Cách dùng “refreshing” (adj.) — làm mát lạnh; sảng khoái; tỉnh táo', 'refreshing drink  ·  refreshing change  ·  refreshing breeze', 'Tính từ refreshing thường dùng để miêu tả sự vật, sự việc; trong khi refreshed dùng để miêu tả cảm giác sảng khoái của con người.', 'Họ từ (Word Family): refresh (v.), refreshed (adj.), refreshment (n.) | Đồng nghĩa: invigorating, revitalising', '[{"hanzi":"A refreshing breeze blew through the open kitchen window.","pinyin":"","meaning":"Một cơn gió mát rượi thổi qua khung cửa sổ nhà bếp đang mở."},{"hanzi":"The documentary offers a refreshing perspective on how older people contribute to their local communities.","pinyin":"","meaning":"Bộ phim tài liệu mang lại một góc nhìn mới mẻ về cách người cao tuổi đóng góp cho cộng đồng địa phương của họ."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_81_2', 'en-b2-81', 'Cách dùng “plaster” (n.) — vữa; lớp trát tường; thạch cao', 'a coat of plaster  ·  plaster cast  ·  sticking plaster', 'Khi mang nghĩa vữa, từ này thường không đếm được; trong tiếng Anh Anh, a plaster dùng để chỉ miếng băng cá nhân nhỏ.', 'Họ từ (Word Family): plasterer (n.), plastering (n.)', '[{"hanzi":"Small pieces of plaster fell from the kitchen ceiling.","pinyin":"","meaning":"Những mảnh vữa nhỏ rơi từ trần nhà bếp xuống."},{"hanzi":"Restoring historic buildings often requires skilled workers who can repair damaged plaster without harming original decorative features.","pinyin":"","meaning":"Việc trùng tu các công trình lịch sử thường đòi hỏi những người thợ lành nghề có khả năng sửa chữa lớp vữa bị hư hỏng mà không làm tổn hại đến các chi tiết trang trí ban đầu."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_81_3', 'en-b2-81', 'Cách dùng “sharpen” (v.) — làm sắc; mài giũa; gọt nhọn', 'sharpen a pencil  ·  sharpen a knife  ·  sharpen skills', 'Động từ cấu thành từ tính từ sharp với hậu tố -en, ngoài ra còn dùng theo nghĩa bóng để chỉ việc trau dồi kỹ năng.', 'Họ từ (Word Family): sharp (adj.), sharpener (n.), sharply (adv.), sharpness (n.) | Đồng nghĩa: hone · Trái nghĩa: blunt', '[{"hanzi":"I sharpened my pencil before sketching the sleeping cat.","pinyin":"","meaning":"Tôi đã gọt bút chì trước khi phác thảo chú mèo đang ngủ."},{"hanzi":"Classroom debates can sharpen students'' critical thinking skills by encouraging them to examine competing arguments.","pinyin":"","meaning":"Các cuộc tranh luận trên lớp có thể nâng cao kỹ năng tư duy phản biện của học sinh bằng cách khuyến khích các em xem xét các lập luận trái chiều."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_81_4', 'en-b2-81', 'Cách dùng “selection” (n.) — sự lựa chọn; sự tuyển chọn', 'selection criteria  ·  a wide selection of  ·  the selection process', 'Khi chỉ quá trình lựa chọn thì thường không đếm được; khi chỉ một tập hợp các lựa chọn thì có thể đếm được.', 'Họ từ (Word Family): select (v.), selective (adj.), selectively (adv.) | Đồng nghĩa: choice, assortment', '[{"hanzi":"This little bakery has a wonderful selection of fresh bread.","pinyin":"","meaning":"Tiệm bánh nhỏ này có rất nhiều loại bánh mì tươi ngon để lựa chọn."},{"hanzi":"Transparent selection procedures can help universities offer places fairly to applicants from a wide range of backgrounds.","pinyin":"","meaning":"Quy trình tuyển chọn minh bạch có thể giúp các trường đại học trao cơ hội công bằng cho các ứng viên đến từ nhiều hoàn cảnh khác nhau."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_81_1', 'en-b2-81', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
