INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_81_1_3', 'ten_b2_81_1', 'refreshing', 'A refreshing breeze blew through the open kitchen window.', 'A refreshing breeze blew through the open kitchen window.', '/rɪˈfreʃɪŋ/', 'Một cơn gió mát rượi thổi qua khung cửa sổ nhà bếp đang mở.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_81_1_4', 'ten_b2_81_1', 'liquor', 'The restaurant keeps its liquor in a locked cabinet.', 'The restaurant keeps its liquor in a locked cabinet.', '/ˈlɪkər/', 'Nhà hàng cất giữ rượu mạnh trong một chiếc tủ có khóa.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_81_1_5', 'ten_b2_81_1', 'selection', 'This little bakery has a wonderful selection of fresh bread.', 'This little bakery has a wonderful selection of fresh bread.', '/sɪˈlekʃən/', 'Tiệm bánh nhỏ này có rất nhiều loại bánh mì tươi ngon để lựa chọn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_81_1_6', 'ten_b2_81_1', 'outwards', 'The windows open outwards, so keep the balcony clear.', 'The windows open outwards, so keep the balcony clear.', '/ˈaʊtwɚdz/', 'Các cửa sổ mở hướng ra ngoài, vì vậy hãy giữ cho ban công thoáng đãng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_81_1_7', 'ten_b2_81_1', 'resemblance', 'There is a striking resemblance between the two sisters.', 'There is a striking resemblance between the two sisters.', '/rɪˈzembləns/', 'Có một sự giống nhau đến kỳ lạ giữa hai chị em.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_81_1_8', 'ten_b2_81_1', 'firewood', 'We stacked dry firewood beside the stove before dinner.', 'We stacked dry firewood beside the stove before dinner.', '/ˈfaɪərwʊd/', 'Chúng tôi xếp củi khô bên cạnh lò sưởi trước bữa tối.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_81_1_1', 'en-b2-81', 'ten_b2_81_1', 'listening', 'listening', 'She dropped a woollen mitten beside the snowy path.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Việc sửa chữa mái nhà đã tốn nhiều thời gian và công sức đáng kể.","Cô ấy đánh rơi một chiếc găng tay len ở cạnh con đường phủ đầy tuyết.","Tôi đã gọt bút chì trước khi phác thảo chú mèo đang ngủ.","Một cơn gió mát rượi thổi qua khung cửa sổ nhà bếp đang mở."]'::jsonb, 1, 'She dropped a woollen mitten beside the snowy path. → Cô ấy đánh rơi một chiếc găng tay len ở cạnh con đường phủ đầy tuyết.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_81_1_2', 'en-b2-81', 'ten_b2_81_1', 'listening', 'listening', 'Small pieces of plaster fell from the kitchen ceiling.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Xoay nắp theo chiều ngược kim đồng hồ để mở hũ ra.","Một phần lớn khu vườn của chúng tôi bị che khuất bởi bóng râm.","Những mảnh vữa nhỏ rơi từ trần nhà bếp xuống.","Chúng tôi xếp củi khô bên cạnh lò sưởi trước bữa tối."]'::jsonb, 2, 'Small pieces of plaster fell from the kitchen ceiling. → Những mảnh vữa nhỏ rơi từ trần nhà bếp xuống.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_81_1_3', 'en-b2-81', 'ten_b2_81_1', 'listening', 'listening', 'A refreshing breeze blew through the open kitchen window.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Xoay nắp theo chiều ngược kim đồng hồ để mở hũ ra.","Việc sửa chữa mái nhà đã tốn nhiều thời gian và công sức đáng kể.","Cô ấy búi tóc lên và cố định bằng một chiếc trâm cài tóc bằng bạc.","Một cơn gió mát rượi thổi qua khung cửa sổ nhà bếp đang mở."]'::jsonb, 3, 'A refreshing breeze blew through the open kitchen window. → Một cơn gió mát rượi thổi qua khung cửa sổ nhà bếp đang mở.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_81_2', 'en-b2-81', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_81_2_1', 'ten_b2_81_2', 'mitten', 'In cold climates, insulated mittens help outdoor workers maintain hand warmth during prolonged exposure to low temperatures.', 'In cold climates, insulated mittens help outdoor workers maintain hand warmth during prolonged exposure to low temperatures.', '/ˈmɪtən/', 'Ở những vùng khí hậu lạnh, găng tay giữ nhiệt giúp những người làm việc ngoài trời giữ ấm đôi tay trong điều kiện tiếp xúc lâu với nhiệt độ thấp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_81_2_2', 'ten_b2_81_2', 'plaster', 'Restoring historic buildings often requires skilled workers who can repair damaged plaster without harming original decorative features.', 'Restoring historic buildings often requires skilled workers who can repair damaged plaster without harming original decorative features.', '/ˈplæstər/', 'Việc trùng tu các công trình lịch sử thường đòi hỏi những người thợ lành nghề có khả năng sửa chữa lớp vữa bị hư hỏng mà không làm tổn hại đến các chi tiết trang trí ban đầu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_81_2_3', 'ten_b2_81_2', 'refreshing', 'The documentary offers a refreshing perspective on how older people contribute to their local communities.', 'The documentary offers a refreshing perspective on how older people contribute to their local communities.', '/rɪˈfreʃɪŋ/', 'Bộ phim tài liệu mang lại một góc nhìn mới mẻ về cách người cao tuổi đóng góp cho cộng đồng địa phương của họ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_81_2_4', 'ten_b2_81_2', 'liquor', 'Governments often impose higher taxes on liquor to discourage excessive consumption and protect public health.', 'Governments often impose higher taxes on liquor to discourage excessive consumption and protect public health.', '/ˈlɪkər/', 'Chính phủ thường áp mức thuế cao hơn đối với rượu mạnh nhằm hạn chế tình trạng tiêu thụ quá mức và bảo vệ sức khỏe cộng đồng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_81_2_5', 'ten_b2_81_2', 'selection', 'Transparent selection procedures can help universities offer places fairly to applicants from a wide range of backgrounds.', 'Transparent selection procedures can help universities offer places fairly to applicants from a wide range of backgrounds.', '/sɪˈlekʃən/', 'Quy trình tuyển chọn minh bạch có thể giúp các trường đại học trao cơ hội công bằng cho các ứng viên đến từ nhiều hoàn cảnh khác nhau.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_81_2_6', 'ten_b2_81_2', 'outwards', 'As cities expand outwards, surrounding farmland often disappears, creating concerns about food security and habitat loss.', 'As cities expand outwards, surrounding farmland often disappears, creating concerns about food security and habitat loss.', '/ˈaʊtwɚdz/', 'Khi các thành phố mở rộng ra vùng ven, đất nông nghiệp xung quanh thường biến mất, gây ra những lo ngại về an ninh lương thực và sự mất mát môi trường sống.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_81_2_1', 'en-b2-81', 'ten_b2_81_2', 'listening', 'listening', 'In cold climates, insulated mittens help outdoor workers maintain hand warmth during prolonged exposure to low temperatures.', NULL, 'Trong câu vừa nghe, từ “mitten” mang nghĩa nào sau đây?', '["bộ xương; khung xương","găng tay hở ngón/găng tay trùm (có ngăn riêng cho ngón cái và một ngăn chung cho bốn ngón kia)","lợi ích tài chính; phần hùn; cổ phần","cố kiến; thành kiến; định kiến"]'::jsonb, 1, '“mitten” (/ˈmɪtən/): găng tay hở ngón/găng tay trùm (có ngăn riêng cho ngón cái và một ngăn chung cho bốn ngón kia). Câu đầy đủ: In cold climates, insulated mittens help outdoor workers maintain hand warmth during prolonged exposure to low temperatures.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_81_2_2', 'en-b2-81', 'ten_b2_81_2', 'listening', 'listening', 'Restoring historic buildings often requires skilled workers who can repair damaged plaster without harming original decorative features.', NULL, 'Trong câu vừa nghe, từ “plaster” mang nghĩa nào sau đây?', '["sưng tấy, sưng phồng (do chấn thương hoặc bệnh tật)","vữa; lớp trát tường; thạch cao","vô tận; bất tận; kéo dài không dứt","tính từ: vỡ lòng; nhập môn; giới thiệu"]'::jsonb, 1, '“plaster” (/ˈplæstər/): vữa; lớp trát tường; thạch cao. Câu đầy đủ: Restoring historic buildings often requires skilled workers who can repair damaged plaster without harming original decorative features.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
