INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_81_1', 'en-b2-81', NULL, 'comprehensive_test', 'listening', 'mitten', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["vượt quá; vượt mức","thuốc chữa bệnh; việc dùng thuốc điều trị","găng tay hở ngón/găng tay trùm (có ngăn riêng cho ngón cái và một ngăn chung cho bốn ngón kia)","bộ lọc; thiết bị lọc"]'::jsonb, 2, 'mitten (/ˈmɪtən/) → găng tay hở ngón/găng tay trùm (có ngăn riêng cho ngón cái và một ngăn chung cho bốn ngón kia)', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_81_2', 'en-b2-81', NULL, 'comprehensive_test', 'listening', 'Small pieces of plaster fell from the kitchen ceiling.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những mảnh vữa nhỏ rơi từ trần nhà bếp xuống.","Cô ấy búi tóc lên và cố định bằng một chiếc trâm cài tóc bằng bạc.","Người công nhân hạ tấm chắn trong suốt xuống trước mặt để bảo vệ khuôn mặt.","Cô ấy giơ chiếc vòng tay lấp lánh lên dưới ánh nắng mặt trời."]'::jsonb, 0, 'Small pieces of plaster fell from the kitchen ceiling. → Những mảnh vữa nhỏ rơi từ trần nhà bếp xuống.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_81_3', 'en-b2-81', NULL, 'comprehensive_test', 'listening', 'refreshing', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bạn đồng hành; người bầu bạn; thú cưng bầu bạn","không hợp lệ; mất hiệu lực; không được chính thức công nhận","có ích; có lợi","làm mát lạnh; sảng khoái; tỉnh táo"]'::jsonb, 3, 'refreshing (/rɪˈfreʃɪŋ/) → làm mát lạnh; sảng khoái; tỉnh táo; mới mẻ; mang tính đột phá', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_81_4', 'en-b2-81', NULL, 'comprehensive_test', 'listening', 'The restaurant keeps its liquor in a locked cabinet.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy thả một miếng phô mai lớn vào nồi súp.","Nadia đã ngụy trang bản thân bằng một bộ tóc giả và chiếc kính bản to.","Chúng tôi xếp củi khô bên cạnh lò sưởi trước bữa tối.","Nhà hàng cất giữ rượu mạnh trong một chiếc tủ có khóa."]'::jsonb, 3, 'The restaurant keeps its liquor in a locked cabinet. → Nhà hàng cất giữ rượu mạnh trong một chiếc tủ có khóa.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_81_5', 'en-b2-81', NULL, 'comprehensive_test', 'listening', 'selection', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["gia tài lớn; khối tài sản kếch xù","đạt điều kiện; đủ tiêu chuẩn","sự tiêu thụ; sự tiêu dùng","sự lựa chọn; sự tuyển chọn"]'::jsonb, 3, 'selection (/sɪˈlekʃən/) → sự lựa chọn; sự tuyển chọn; danh mục; sự đa dạng; tuyển tập; vật được chọn lọc', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_81_6', 'en-b2-81', NULL, 'comprehensive_test', 'listening', 'The windows open outwards, so keep the balcony clear.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Các cửa sổ mở hướng ra ngoài, vì vậy hãy giữ cho ban công thoáng đãng.","Tôi hầu như không nghe thấy cô ấy nói gì giữa tiếng mưa lớn.","Món súp này là sự kết hợp tuyệt vời giữa các loại rau thơm và rau củ.","Một con tàu khổng lồ đã chắn mất tầm nhìn của chúng tôi ra cảng."]'::jsonb, 0, 'The windows open outwards, so keep the balcony clear. → Các cửa sổ mở hướng ra ngoài, vì vậy hãy giữ cho ban công thoáng đãng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
