INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_81_8', 'en-b2-81', NULL, 'comprehensive_test', 'listening', 'We stacked dry firewood beside the stove before dinner.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cho tôi một gợi ý về việc bạn giấu món quà ở đâu đi.","Món súp này là sự kết hợp tuyệt vời giữa các loại rau thơm và rau củ.","Chúng tôi xếp củi khô bên cạnh lò sưởi trước bữa tối.","Cô ấy giơ chiếc vòng tay lấp lánh lên dưới ánh nắng mặt trời."]'::jsonb, 2, 'We stacked dry firewood beside the stove before dinner. → Chúng tôi xếp củi khô bên cạnh lò sưởi trước bữa tối.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
