INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_81_18', 'en-b2-81', NULL, 'comprehensive_test', 'reading', NULL, 'In cold climates, insulated mittens help outdoor workers maintain hand warmth during prolonged exposure to low temperatures.', 'Dựa vào câu trên, từ “mitten” có nghĩa phù hợp nhất là gì?', '["găng tay hở ngón/găng tay trùm (có ngăn riêng cho ngón cái và một ngăn chung cho bốn ngón kia)","che giấu; giấu kín không để nhìn thấy","chính gốc; đích thực; chuẩn vị","củ cải; củ cải đỏ nhỏ"]'::jsonb, 0, 'mitten: găng tay hở ngón/găng tay trùm (có ngăn riêng cho ngón cái và một ngăn chung cho bốn ngón kia). Dịch cả câu: Ở những vùng khí hậu lạnh, găng tay giữ nhiệt giúp những người làm việc ngoài trời giữ ấm đôi tay trong điều kiện tiếp xúc lâu với nhiệt độ thấp.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_81_19', 'en-b2-81', NULL, 'comprehensive_test', 'reading', NULL, 'Restoring historic buildings often requires skilled workers who can repair damaged plaster without harming original decorative features.', 'Dựa vào câu trên, từ “plaster” có nghĩa phù hợp nhất là gì?', '["mang tính cạnh tranh; cạnh tranh khốc liệt","lời khuyên; nguyên tắc chỉ đạo; hướng dẫn; quy tắc","vữa; lớp trát tường; thạch cao","cuộc thi chạy tiếp sức; môn tiếp sức"]'::jsonb, 2, 'plaster: vữa; lớp trát tường; thạch cao; băng cá nhân; trát vữa; đắp thạch cao. Dịch cả câu: Việc trùng tu các công trình lịch sử thường đòi hỏi những người thợ lành nghề có khả năng sửa chữa lớp vữa bị hư hỏng mà không làm tổn hại đến các chi tiết trang trí ban đầu.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_81_20', 'en-b2-81', NULL, 'comprehensive_test', 'reading', NULL, 'The documentary offers a refreshing perspective on how older people contribute to their local communities.', 'Dựa vào câu trên, từ “refreshing” có nghĩa phù hợp nhất là gì?', '["làm mát lạnh; sảng khoái; tỉnh táo","phạm vi; tầm vực","thuộc Liên Xô cũ; thuộc các hội đồng Xô-viết","về hướng tây; hướng tây"]'::jsonb, 0, 'refreshing: làm mát lạnh; sảng khoái; tỉnh táo; mới mẻ; mang tính đột phá. Dịch cả câu: Bộ phim tài liệu mang lại một góc nhìn mới mẻ về cách người cao tuổi đóng góp cho cộng đồng địa phương của họ.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_81_21', 'en-b2-81', NULL, 'comprehensive_test', 'reading', NULL, 'Governments often impose higher taxes on liquor to discourage excessive consumption and protect public health.', 'Dựa vào câu trên, từ “liquor” có nghĩa phù hợp nhất là gì?', '["lượng calo; đơn vị đo năng lượng (trong thực phẩm)","sân hiên; ban công lớn; sân thượng","một phần nhỏ; lượng nhỏ","rượu mạnh"]'::jsonb, 3, 'liquor: rượu mạnh. Dịch cả câu: Chính phủ thường áp mức thuế cao hơn đối với rượu mạnh nhằm hạn chế tình trạng tiêu thụ quá mức và bảo vệ sức khỏe cộng đồng.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_81_22', 'en-b2-81', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cắt tỉa; cắt bớt một chút để làm gọn gàng hoặc giảm bớt”', '["nevertheless","fuse","envy","trim"]'::jsonb, 3, 'cắt tỉa; cắt bớt một chút để làm gọn gàng hoặc giảm bớt → trim (/trɪm/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_81_23', 'en-b2-81', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hầu như không; vừa mới; suýt nữa thì không”', '["convenience","barely","knot","stall"]'::jsonb, 1, 'hầu như không; vừa mới; suýt nữa thì không → barely (/ˈberli/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_81_24', 'en-b2-81', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “một phần, một phần của cái lớn hơn”', '["portion","philosopher","greatly","time-consuming"]'::jsonb, 0, 'một phần, một phần của cái lớn hơn → portion (/ˈpɔːrʃən/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-82', 'en', 'Bài 82: Đời sống hằng ngày (9) - CEFR B2', 'CEFR B2', 'B2 · Đời sống', '26 từ vựng Tiếng Anh CEFR B2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4082, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dresser', 'en-b2-82', 'dresser', '/ˈdresər/', 'B2', 'tủ có ngăn kéo để đựng quần áo (kiểu Mỹ); tủ đựng bát đĩa có kệ ở trên để trưng bày (kiểu Anh); người ăn mặc theo một phong cách cụ thể nào đó', 'n.', 'dress (v.), dressed (adj.)', NULL, 'Tiếng Mỹ thường chỉ tủ có ngăn kéo đựng quần áo, trong khi tiếng Anh thường chỉ tủ đựng chén đĩa.', 'I put my clean socks in the bedroom dresser.', NULL, 'Tôi cất những chiếc tất sạch vào chiếc tủ có ngăn kéo trong phòng ngủ.', '{"wordId":"dresser","ukIpa":"/ˈdresə/","usIpa":"/ˈdresər/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A piece of furniture with drawers for storing clothes.","vi":"tủ có ngăn kéo để đựng quần áo (kiểu Mỹ)"},{"pos":"n.","en":"A kitchen cupboard with shelves above for displaying dishes.","vi":"tủ đựng bát đĩa có kệ ở trên để trưng bày (kiểu Anh)"},{"pos":"n.","en":"A person who dresses in a particular way.","vi":"người ăn mặc theo một phong cách cụ thể nào đó"}],"examples":[{"en":"I put my clean socks in the bedroom dresser.","vi":"Tôi cất những chiếc tất sạch vào chiếc tủ có ngăn kéo trong phòng ngủ.","audioKind":"ex"},{"en":"Restoring an old dresser rather than buying new furniture can reduce waste and conserve natural resources.","vi":"Việc phục chế lại một chiếc tủ cũ thay vì mua đồ nội thất mới có thể giúp giảm thiểu rác thải và bảo tồn tài nguyên thiên nhiên.","audioKind":"ex2"}],"collocations":[{"en":"bedroom dresser","vi":"tủ đựng quần áo phòng ngủ"},{"en":"kitchen dresser","vi":"tủ bát đĩa phòng bếp"},{"en":"a smart dresser","vi":"người ăn mặc lịch sự, bảnh bao"}],"wordFamily":["dress (v.)","dressed (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Tiếng Mỹ thường chỉ tủ có ngăn kéo đựng quần áo, trong khi tiếng Anh thường chỉ tủ đựng chén đĩa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_incidentally', 'en-b2-82', 'incidentally', '/ˌɪnsɪˈdentəli/', 'B2', 'tiện thể; nhân tiện; thuận miệng; tình cờ; phụ họa', 'adv.', 'incidental (adj.), incident (n.)', 'Đồng nghĩa: by the way', 'Ở đầu câu thường mang nghĩa "nhân tiện/tiện thể"; không phải lúc nào cũng mang nghĩa tình cờ trong mọi ngữ cảnh.', 'Incidentally, your scarf is still hanging by our door.', NULL, 'Nhân tiện, chiếc khăn choàng của bạn vẫn đang treo ở cửa nhà chúng tôi kìa.', '{"wordId":"incidentally","ukIpa":"/ˌɪnsɪˈdentəli/","usIpa":"/ˌɪnsɪˈdentəli/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"Used to introduce an additional or loosely related remark","vi":"tiện thể; nhân tiện; thuận miệng"},{"pos":"adv.","en":"As a secondary result, rather than the main purpose","vi":"tình cờ; phụ họa"}],"examples":[{"en":"Incidentally, your scarf is still hanging by our door.","vi":"Nhân tiện, chiếc khăn choàng của bạn vẫn đang treo ở cửa nhà chúng tôi kìa.","audioKind":"ex"},{"en":"Children may learn new vocabulary incidentally while watching educational programmes, even when language learning is not their main goal.","vi":"Trẻ em có thể tình cờ học được từ vựng mới khi xem các chương trình giáo dục, ngay cả khi mục tiêu chính của chúng không phải là học ngôn ngữ.","audioKind":"ex2"}],"collocations":[{"en":"incidentally acquired","vi":"được tiếp thu một cách tình cờ"},{"en":"learn incidentally","vi":"học được một cách ngẫu nhiên"},{"en":"mention incidentally","vi":"tiện thể nhắc đến"}],"wordFamily":["incidental (adj.)","incident (n.)"],"synonyms":["by the way"],"antonyms":[],"tipVi":"Ở đầu câu thường mang nghĩa \"nhân tiện/tiện thể\"; không phải lúc nào cũng mang nghĩa tình cờ trong mọi ngữ cảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bulb', 'en-b2-82', 'bulb', '/bʌlb/', 'B2', 'bóng đèn; củ (thực vật)', 'n.', 'bulbous (adj.)', NULL, 'Vừa chỉ bóng đèn, vừa chỉ phần củ dưới lòng đất của các loài cây như hành, thủy tiên.', 'The kitchen bulb failed while I was washing dishes.', NULL, 'Bóng đèn trong bếp bị hỏng khi tôi đang rửa bát.', '{"wordId":"bulb","ukIpa":"/bʌlb/","usIpa":"/bʌlb/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A glass or plastic device that produces electric light.","vi":"bóng đèn"},{"pos":"n.","en":"A rounded underground plant part that stores food and grows shoots.","vi":"củ (thực vật)"}],"examples":[{"en":"The kitchen bulb failed while I was washing dishes.","vi":"Bóng đèn trong bếp bị hỏng khi tôi đang rửa bát.","audioKind":"ex"},{"en":"Replacing traditional bulbs with energy-efficient alternatives can reduce household electricity consumption and lower long-term costs.","vi":"Việc thay thế các bóng đèn truyền thống bằng các giải pháp tiết kiệm năng lượng có thể làm giảm lượng điện tiêu thụ trong gia đình và tiết kiệm chi phí lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"light bulb","vi":"bóng đèn điện"},{"en":"change a bulb","vi":"thay bóng đèn"},{"en":"energy-saving bulb","vi":"bóng đèn tiết kiệm điện"},{"en":"plant bulbs","vi":"trồng củ hoa"}],"wordFamily":["bulbous (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Vừa chỉ bóng đèn, vừa chỉ phần củ dưới lòng đất của các loài cây như hành, thủy tiên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thicken', 'en-b2-82', 'thicken', '/ˈθɪkən/', 'B2', 'làm đặc; làm sánh lại; làm dày lên; trở nên đặc hơn', 'v.', 'thick (adj.), thickness (n.), thickener (n.), thickly (adv.)', 'Trái nghĩa: thin', 'Có thể dùng theo cả hai hướng ngoại động từ và nội động từ: thicken soup; soup thickens.', 'Add a little flour to thicken the mushroom sauce.', NULL, 'Cho thêm một chút bột mì để làm sánh sốt nấm lại.', '{"wordId":"thicken","ukIpa":"/ˈθɪkən/","usIpa":"/ˈθɪkən/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To become thicker, or make a liquid thicker.","vi":"làm đặc; làm sánh lại"},{"pos":"v.","en":"To become or make something thicker or denser.","vi":"làm dày lên; trở nên đặc hơn"}],"examples":[{"en":"Add a little flour to thicken the mushroom sauce.","vi":"Cho thêm một chút bột mì để làm sánh sốt nấm lại.","audioKind":"ex"},{"en":"As coastal fog thickens, transport operators may need to reduce services to maintain passenger safety.","vi":"Khi sương mù ven biển dày đặc hơn, các đơn vị vận tải có thể phải giảm bớt chuyến để đảm bảo an toàn cho hành khách.","audioKind":"ex2"}],"collocations":[{"en":"thicken a sauce","vi":"làm đặc nước sốt"},{"en":"fog thickens","vi":"sương mù dày lên"},{"en":"the plot thickens","vi":"cốt truyện trở nên phức tạp hơn"}],"wordFamily":["thick (adj.)","thickness (n.)","thickener (n.)","thickly (adv.)"],"synonyms":[],"antonyms":["thin"],"tipVi":"Có thể dùng theo cả hai hướng ngoại động từ và nội động từ: thicken soup; soup thickens.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gaze', 'en-b2-82', 'gaze', '/ɡeɪz/', 'B2', 'nhìn chăm chú; ngắm nhìn; ánh mắt chăm chú; cái nhìn đăm đăm', 'v.', NULL, 'Đồng nghĩa: stare', 'Động từ gaze thường đi với giới từ at; so với glance thì nhìn lâu hơn, và thường dịu dàng, trầm lắng hơn stare.', 'Lina gazed at the moon through her bedroom window.', NULL, 'Lina ngắm nhìn mặt trăng qua khung cửa sổ phòng ngủ.', '{"wordId":"gaze","ukIpa":"/ɡeɪz/","usIpa":"/ɡeɪz/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To look steadily at something for a long time.","vi":"nhìn chăm chú; ngắm nhìn"},{"pos":"n.","en":"A steady look directed at someone or something.","vi":"ánh mắt chăm chú; cái nhìn đăm đăm"}],"examples":[{"en":"Lina gazed at the moon through her bedroom window.","vi":"Lina ngắm nhìn mặt trăng qua khung cửa sổ phòng ngủ.","audioKind":"ex"},{"en":"Visitors often gaze at historic buildings, yet overlook the maintenance work required to preserve these cultural treasures.","vi":"Du khách thường ngắm nhìn các công trình lịch sử nhưng lại bỏ qua công tác bảo trì cần thiết để bảo tồn những báu vật văn hóa này.","audioKind":"ex2"}],"collocations":[{"en":"gaze at","vi":"nhìn chăm chú vào"},{"en":"gaze out of the window","vi":"nhìn đăm đăm ra ngoài cửa sổ"},{"en":"meet someone''s gaze","vi":"bắt gặp ánh mắt của ai đó"},{"en":"avert one''s gaze","vi":"tránh đi ánh mắt"}],"wordFamily":[],"synonyms":["stare"],"antonyms":[],"tipVi":"Động từ gaze thường đi với giới từ at; so với glance thì nhìn lâu hơn, và thường dịu dàng, trầm lắng hơn stare.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lump', 'en-b2-82', 'lump', '/lʌmp/', 'B2', 'cục; khối; khối u; gộp chung; đánh đồng', 'n.', 'lumpy (adj.), lumpiness (n.)', NULL, 'lump together thường ám chỉ bỏ qua sự khác biệt, gộp loại chung.', 'She dropped a lump of clay onto the table.', NULL, 'Cô ấy thả một cục đất sét xuống bàn.', '{"wordId":"lump","ukIpa":"/lʌmp/","usIpa":"/lʌmp/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A solid piece without a regular shape.","vi":"cục; khối"},{"pos":"n.","en":"A swelling under the skin or in body tissue.","vi":"khối u"},{"pos":"v.","en":"To treat different things as one group, ignoring their differences.","vi":"gộp chung; đánh đồng"}],"examples":[{"en":"She dropped a lump of clay onto the table.","vi":"Cô ấy thả một cục đất sét xuống bàn.","audioKind":"ex"},{"en":"Policymakers should not lump all unemployed people together, as their circumstances and support needs vary considerably.","vi":"Các nhà hoạch định chính sách không nên gộp chung tất cả những người thất nghiệp lại với nhau, vì hoàn cảnh và nhu cầu hỗ trợ của họ rất khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"a lump of clay","vi":"một cục đất sét"},{"en":"a lump sum","vi":"một khoản tiền gộp"},{"en":"lump together","vi":"gộp chung lại"},{"en":"a lump in your throat","vi":"cảm giác nghẹn ở cổ họng"}],"wordFamily":["lumpy (adj.)","lumpiness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"lump together thường ám chỉ bỏ qua sự khác biệt, gộp loại chung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_expiry', 'en-b2-82', 'expiry', '/ɪkˈspaɪri/', 'B2', 'hết hạn; sự mãn hạn', 'n.', 'expire (v.), expiration (n.)', 'Đồng nghĩa: expiration', 'Chỉ thời điểm "đến hạn" chứ không phải "quá hạn"; tiếng Mỹ thường dùng expiration.', 'My passport is getting close to its expiry date.', NULL, 'Hộ chiếu của tôi sắp đến ngày hết hạn.', '{"wordId":"expiry","ukIpa":"/ɪkˈspaɪəri/","usIpa":"/ɪkˈspaɪri/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"The end of the period when something remains valid.","vi":"hết hạn; sự mãn hạn"}],"examples":[{"en":"My passport is getting close to its expiry date.","vi":"Hộ chiếu của tôi sắp đến ngày hết hạn.","audioKind":"ex"},{"en":"Travellers should check the expiry date of their passports before making any international travel arrangements.","vi":"Du khách nên kiểm tra ngày hết hạn của hộ chiếu trước khi tiến hành bất kỳ kế hoạch du lịch quốc tế nào.","audioKind":"ex2"}],"collocations":[{"en":"expiry date","vi":"ngày hết hạn"},{"en":"on expiry","vi":"vào lúc hết hạn"},{"en":"expiry of a contract","vi":"hết hạn hợp đồng"}],"wordFamily":["expire (v.)","expiration (n.)"],"synonyms":["expiration"],"antonyms":[],"tipVi":"Chỉ thời điểm \"đến hạn\" chứ không phải \"quá hạn\"; tiếng Mỹ thường dùng expiration.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_incomplete', 'en-b2-82', 'incomplete', '/ˌɪnkəmˈpliːt/', 'B2', 'chưa hoàn chỉnh; chưa hoàn thành', 'adj.', 'complete (adj.), completely (adv.), incompletely (adv.), completion (n.)', 'Đồng nghĩa: unfinished, partial · Trái nghĩa: complete', 'incomplete có thể chỉ việc thiếu hụt thành phần, hoặc chỉ công việc chưa được làm xong.', 'The puzzle is incomplete because several pieces are missing.', NULL, 'Bức tranh ghép hình này chưa hoàn chỉnh vì thiếu mất vài mảnh.', '{"wordId":"incomplete","ukIpa":"/ˌɪnkəmˈpliːt/","usIpa":"/ˌɪnkəmˈpliːt/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"missing some parts or not yet finished","vi":"chưa hoàn chỉnh; chưa hoàn thành"}],"examples":[{"en":"The puzzle is incomplete because several pieces are missing.","vi":"Bức tranh ghép hình này chưa hoàn chỉnh vì thiếu mất vài mảnh.","audioKind":"ex"},{"en":"Policies based on incomplete data may fail to address the needs of the most vulnerable communities.","vi":"Các chính sách dựa trên dữ liệu không đầy đủ có thể không đáp ứng được nhu cầu của các cộng đồng dễ bị tổn thương nhất.","audioKind":"ex2"}],"collocations":[{"en":"incomplete information","vi":"thông tin không đầy đủ"},{"en":"incomplete data","vi":"dữ liệu chưa hoàn chỉnh"},{"en":"an incomplete application","vi":"hồ sơ xin việc chưa hoàn thiện"}],"wordFamily":["complete (adj.)","completely (adv.)","incompletely (adv.)","completion (n.)"],"synonyms":["unfinished","partial"],"antonyms":["complete"],"tipVi":"incomplete có thể chỉ việc thiếu hụt thành phần, hoặc chỉ công việc chưa được làm xong.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_worthless', 'en-b2-82', 'worthless', '/ˈwɝːθləs/', 'B2', 'vô giá trị; không có ích', 'adj.', 'worth (n.), worthy (adj.), worthlessness (n.)', 'Đồng nghĩa: valueless, useless · Trái nghĩa: valuable, useful', 'worthless chỉ sự không có giá trị; ngược lại priceless dùng để chỉ sự cực kỳ quý giá.', 'Without its missing parts, this old machine is worthless.', NULL, 'Thiếu đi các bộ phận bị mất, cỗ máy cũ này trở nên hoàn toàn vô tích sự.', '{"wordId":"worthless","ukIpa":"/ˈwɜːθləs/","usIpa":"/ˈwɝːθləs/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"having no value or practical use","vi":"vô giá trị; không có ích"}],"examples":[{"en":"Without its missing parts, this old machine is worthless.","vi":"Thiếu đi các bộ phận bị mất, cỗ máy cũ này trở nên hoàn toàn vô tích sự.","audioKind":"ex"},{"en":"Digital skills can quickly become worthless if training focuses only on tools that are soon outdated.","vi":"Các kỹ năng số có thể nhanh chóng trở nên vô giá trị nếu việc đào tạo chỉ tập trung vào các công cụ sớm lỗi thời.","audioKind":"ex2"}],"collocations":[{"en":"virtually worthless","vi":"hầu như không có giá trị"},{"en":"worthless information","vi":"thông tin vô dụng"},{"en":"worthless investment","vi":"khoản đầu tư vô giá trị"}],"wordFamily":["worth (n.)","worthy (adj.)","worthlessness (n.)"],"synonyms":["valueless","useless"],"antonyms":["valuable","useful"],"tipVi":"worthless chỉ sự không có giá trị; ngược lại priceless dùng để chỉ sự cực kỳ quý giá.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disturbance', 'en-b2-82', 'disturbance', '/dɪˈstɝːbəns/', 'B2', 'sự quấy rầy; sự làm xáo trộn; sự cản trở; sự náo loạn; cuộc bạo động; sự mất trật tự công cộng', 'n.', 'disturb (v.), disturbed (adj.), disturbing (adj.), undisturbed (adj.)', 'Đồng nghĩa: disruption, interruption', 'Từ này có thể chỉ sự yên bình bị phá vỡ hoặc tình trạng rối loạn chức năng cơ thể.', 'The drilling upstairs caused a disturbance during our dinner.', NULL, 'Tiếng khoan ở trên lầu đã làm phiền chúng tôi trong suốt bữa tối.', '{"wordId":"disturbance","ukIpa":"/dɪˈstɜːbəns/","usIpa":"/dɪˈstɝːbəns/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"something that interrupts normal activity, peace, or functioning","vi":"sự quấy rầy; sự làm xáo trộn; sự cản trở"},{"pos":"n.","en":"an incident involving noisy or disorderly public behaviour","vi":"sự náo loạn; cuộc bạo động; sự mất trật tự công cộng"}],"examples":[{"en":"The drilling upstairs caused a disturbance during our dinner.","vi":"Tiếng khoan ở trên lầu đã làm phiền chúng tôi trong suốt bữa tối.","audioKind":"ex"},{"en":"Construction near protected wetlands can cause significant disturbance to nesting birds, particularly during the breeding season.","vi":"Hoạt động xây dựng gần các vùng đất ngập nước được bảo vệ có thể gây ra sự xáo trộn đáng kể đối với các loài chim làm tổ, đặc biệt là trong mùa sinh sản.","audioKind":"ex2"}],"collocations":[{"en":"cause a disturbance","vi":"gây sự quấy rầy"},{"en":"noise disturbance","vi":"tiếng ồn làm phiền"},{"en":"sleep disturbance","vi":"rối loạn giấc ngủ"},{"en":"public disturbance","vi":"gây rối trật tự công cộng"}],"wordFamily":["disturb (v.)","disturbed (adj.)","disturbing (adj.)","undisturbed (adj.)"],"synonyms":["disruption","interruption"],"antonyms":[],"tipVi":"Từ này có thể chỉ sự yên bình bị phá vỡ hoặc tình trạng rối loạn chức năng cơ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pat', 'en-b2-82', 'pat', '/pæt/', 'B2', 'vỗ nhẹ; xoa nhẹ; cái vỗ nhẹ; cái xoa nhẹ', 'v.', NULL, 'Đồng nghĩa: tap, stroke', 'Dạng quá khứ là ''patted'' và hiện phân từ là ''patting'' đều được gấp đôi chữ t.', 'She patted the dog gently as it fell asleep.', NULL, 'Cô ấy nhẹ nhàng vỗ về chú chó khi nó chìm vào giấc ngủ.', '{"wordId":"pat","ukIpa":"/pæt/","usIpa":"/pæt/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To touch gently several times with a flat hand.","vi":"vỗ nhẹ; xoa nhẹ"},{"pos":"n.","en":"A gentle touch made with a flat hand.","vi":"cái vỗ nhẹ; cái xoa nhẹ"}],"examples":[{"en":"She patted the dog gently as it fell asleep.","vi":"Cô ấy nhẹ nhàng vỗ về chú chó khi nó chìm vào giấc ngủ.","audioKind":"ex"},{"en":"A gentle pat on the shoulder can offer reassurance, although attitudes towards physical contact vary across cultures.","vi":"Một cái vỗ nhẹ vào vai có thể mang lại sự an ủi, mặc dù thái độ đối với việc tiếp xúc thể xác có sự khác biệt giữa các nền văn hóa.","audioKind":"ex2"}],"collocations":[{"en":"pat someone on the back","vi":"vỗ lưng ai đó"},{"en":"give someone a pat","vi":"vỗ nhẹ ai đó"},{"en":"pat dry","vi":"vỗ nhẹ cho khô"}],"wordFamily":[],"synonyms":["tap","stroke"],"antonyms":[],"tipVi":"Dạng quá khứ là ''patted'' và hiện phân từ là ''patting'' đều được gấp đôi chữ t.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lick', 'en-b2-82', 'lick', '/lɪk/', 'B2', 'liếm (di chuyển lưỡi qua bề mặt của thứ gì đó, thường để nếm vị); cái liếm; cú liếm (hành động đưa lưỡi liếm qua một vật gì đó)', 'v.', NULL, NULL, '"lick" chỉ hành động dùng lưỡi để liếm; "bite" là cắn, còn "suck" là mút hoặc bú.', 'The puppy licked my hand and wagged its tail.', NULL, 'Chú chó con đã liếm tay tôi và ngoe nguẩy cái đuôi.', '{"wordId":"lick","ukIpa":"/lɪk/","usIpa":"/lɪk/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"Move your tongue across something, often to taste it.","vi":"liếm (di chuyển lưỡi qua bề mặt của thứ gì đó, thường để nếm vị)"},{"pos":"n.","en":"An act of moving the tongue across something.","vi":"cái liếm; cú liếm (hành động đưa lưỡi liếm qua một vật gì đó)"}],"examples":[{"en":"The puppy licked my hand and wagged its tail.","vi":"Chú chó con đã liếm tay tôi và ngoe nguẩy cái đuôi.","audioKind":"ex"},{"en":"Visitors should not allow wild animals to lick their hands, as close contact may spread infections.","vi":"Du khách không nên để động vật hoang dã liếm tay mình, vì việc tiếp xúc gần có thể làm lây lan mầm bệnh.","audioKind":"ex2"}],"collocations":[{"en":"lick your lips","vi":"liếm môi"},{"en":"lick an ice cream","vi":"liếm kem"},{"en":"give something a lick","vi":"liếm qua một cái"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"\"lick\" chỉ hành động dùng lưỡi để liếm; \"bite\" là cắn, còn \"suck\" là mút hoặc bú.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sweeten', 'en-b2-82', 'sweeten', '/ˈswiːtən/', 'B2', 'làm cho ngọt; thêm đường/mật cho ngọt; làm cho hấp dẫn hơn; làm cho ưu đãi hơn', 'v.', 'sweet (adj.), sweetener (n.), sweetness (n.)', NULL, 'sweeten the deal chỉ việc đưa thêm ưu đãi để làm cho giao dịch trở nên hấp dẫn hơn.', 'I sweeten my porridge with a little honey.', NULL, 'Tôi cho thêm một chút mật khẩu vào cháo để làm cho nó ngọt hơn.', '{"wordId":"sweeten","ukIpa":"/ˈswiːtən/","usIpa":"/ˈswiːtən/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to make something sweeter or become sweeter","vi":"làm cho ngọt; thêm đường/mật cho ngọt"},{"pos":"v.","en":"to make an offer or situation more attractive","vi":"làm cho hấp dẫn hơn; làm cho ưu đãi hơn"}],"examples":[{"en":"I sweeten my porridge with a little honey.","vi":"Tôi cho thêm một chút mật khẩu vào cháo để làm cho nó ngọt hơn.","audioKind":"ex"},{"en":"Employers may sweeten job offers with flexible working hours to attract skilled candidates in competitive industries.","vi":"Trong các ngành công nghiệp có tính cạnh tranh cao, nhà tuyển dụng có thể đưa ra thời gian làm việc linh hoạt nhằm tăng tính hấp dẫn cho công việc, qua đó thu hút nhân tài.","audioKind":"ex2"}],"collocations":[{"en":"sweeten with honey","vi":"làm ngọt bằng mật ong"},{"en":"sweeten the deal","vi":"tăng tính hấp dẫn cho thỏa thuận"},{"en":"sweeten an offer","vi":"làm cho lời đề nghị hấp dẫn hơn"}],"wordFamily":["sweet (adj.)","sweetener (n.)","sweetness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"sweeten the deal chỉ việc đưa thêm ưu đãi để làm cho giao dịch trở nên hấp dẫn hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_accompany', 'en-b2-82', 'accompany', '/əˈkʌmpəni/', 'B2', 'đi cùng; hộ tống; đồng hành; đi kèm; xảy ra đồng thời; đệm đàn', 'v.', 'accompaniment (n.), accompanist (n.), accompanying (adj.)', NULL, 'Động từ này đi trực tiếp với tân ngữ chỉ người, không dùng accompany with someone.', 'My sister will accompany me to the clinic tomorrow.', NULL, 'Chị gái sẽ đi cùng tôi đến phòng khám vào ngày mai.', '{"wordId":"accompany","ukIpa":"/əˈkʌmpəni/","usIpa":"/əˈkʌmpəni/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"Go somewhere with someone.","vi":"đi cùng; hộ tống; đồng hành"},{"pos":"v.","en":"Exist or happen together with something else.","vi":"đi kèm; xảy ra đồng thời"},{"pos":"v.","en":"Play music to support a singer or another musician.","vi":"đệm đàn"}],"examples":[{"en":"My sister will accompany me to the clinic tomorrow.","vi":"Chị gái sẽ đi cùng tôi đến phòng khám vào ngày mai.","audioKind":"ex"},{"en":"Investment in public transport should accompany urban expansion to prevent congestion and improve access to employment.","vi":"Việc đầu tư vào giao thông công cộng nên đi đôi với quá trình mở rộng đô thị nhằm ngăn chặn tình trạng tắc nghẽn và cải thiện khả năng tiếp cận việc làm.","audioKind":"ex2"}],"collocations":[{"en":"accompany someone to","vi":"đi cùng ai đến đâu"},{"en":"be accompanied by","vi":"đi kèm với; được tháp tùng bởi"},{"en":"accompany on the piano","vi":"đệm piano"}],"wordFamily":["accompaniment (n.)","accompanist (n.)","accompanying (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ này đi trực tiếp với tân ngữ chỉ người, không dùng accompany with someone.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bulk', 'en-b2-82', 'bulk', '/bʌlk/', 'B2', 'phần lớn; đa số; kích thước lớn; khối lượng lớn', 'n.', 'bulky (adj.), bulkiness (n.)', NULL, 'Cụm the bulk of chỉ phần lớn; in bulk có nghĩa là mua bán số lượng lớn.', 'The bulk of my clothes fit in this suitcase.', NULL, 'Phần lớn quần áo của tôi đều vừa vặn trong chiếc vali này.', '{"wordId":"bulk","ukIpa":"/bʌlk/","usIpa":"/bʌlk/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"the largest part of something","vi":"phần lớn; đa số"},{"pos":"n.","en":"the large size or mass of something","vi":"kích thước lớn; khối lượng lớn"}],"examples":[{"en":"The bulk of my clothes fit in this suitcase.","vi":"Phần lớn quần áo của tôi đều vừa vặn trong chiếc vali này.","audioKind":"ex"},{"en":"The bulk of public transport funding should support reliable services in areas with limited access to employment.","vi":"Phần lớn nguồn vốn dành cho giao thông công cộng nên ưu tiên hỗ trợ các dịch vụ đáng tin cậy tại những khu vực có khả năng tiếp cận việc làm hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"the bulk of","vi":"phần lớn của"},{"en":"buy in bulk","vi":"mua số lượng lớn"},{"en":"sheer bulk","vi":"thể tích khổng lồ"},{"en":"bulk buying","vi":"hoạt động mua sỉ"}],"wordFamily":["bulky (adj.)","bulkiness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm the bulk of chỉ phần lớn; in bulk có nghĩa là mua bán số lượng lớn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_interval', 'en-b2-82', 'interval', '/ˈɪntərvəl/', 'B2', 'khoảng thời gian; khoảng cách; giờ nghỉ giữa hiệp; khoảng nghỉ giải lao', 'n.', NULL, 'Đồng nghĩa: gap, break', 'at intervals biểu thị việc lặp lại cách đều một khoảng thời gian hoặc khoảng cách.', 'There was a short interval between the two calls.', NULL, 'Có một khoảng thời gian ngắn giữa hai cuộc gọi.', '{"wordId":"interval","ukIpa":"/ˈɪntəvəl/","usIpa":"/ˈɪntərvəl/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A period or distance between events or objects.","vi":"khoảng thời gian; khoảng cách"},{"pos":"n.","en":"A short break between parts of a performance.","vi":"giờ nghỉ giữa hiệp; khoảng nghỉ giải lao"}],"examples":[{"en":"There was a short interval between the two calls.","vi":"Có một khoảng thời gian ngắn giữa hai cuộc gọi.","audioKind":"ex"},{"en":"Taking breaks at regular intervals can help students maintain concentration during long periods of study.","vi":"Việc nghỉ giải lao đều đặn theo các khoảng thời gian nhất định có thể giúp học sinh duy trì sự tập trung trong suốt thời gian học tập kéo dài.","audioKind":"ex2"}],"collocations":[{"en":"at regular intervals","vi":"cách đều nhau; định kỳ"},{"en":"a short interval","vi":"một khoảng thời gian ngắn"},{"en":"a time interval","vi":"khoảng thời gian"},{"en":"during the interval","vi":"trong giờ nghỉ giải lao"}],"wordFamily":[],"synonyms":["gap","break"],"antonyms":[],"tipVi":"at intervals biểu thị việc lặp lại cách đều một khoảng thời gian hoặc khoảng cách.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pastime', 'en-b2-82', 'pastime', '/ˈpæstaɪm/', 'B2', 'hoạt động giải trí; tiêu khiển', 'n.', NULL, 'Đồng nghĩa: hobby, recreation', 'Chỉ hoạt động giải trí; lưu ý cách viết pastime chỉ có một chữ s.', 'Gardening became her favourite pastime after she retired.', NULL, 'Làm vườn trở thành hoạt động giải trí yêu thích của bà ấy sau khi nghỉ hưu.', '{"wordId":"pastime","ukIpa":"/ˈpɑːstaɪm/","usIpa":"/ˈpæstaɪm/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"An activity you enjoy doing in your free time.","vi":"hoạt động giải trí; tiêu khiển"}],"examples":[{"en":"Gardening became her favourite pastime after she retired.","vi":"Làm vườn trở thành hoạt động giải trí yêu thích của bà ấy sau khi nghỉ hưu.","audioKind":"ex"},{"en":"Outdoor pastimes can improve mental health while encouraging people to spend less time using electronic devices.","vi":"Các hoạt động giải trí ngoài trời có thể cải thiện sức khỏe tinh thần đồng thời khuyến khích mọi người giảm thời gian sử dụng thiết bị điện tử.","audioKind":"ex2"}],"collocations":[{"en":"favourite pastime","vi":"sở thích yêu thích"},{"en":"popular pastime","vi":"hoạt động giải trí phổ biến"},{"en":"leisure pastime","vi":"tiêu khiển lúc nhàn rỗi"}],"wordFamily":[],"synonyms":["hobby","recreation"],"antonyms":[],"tipVi":"Chỉ hoạt động giải trí; lưu ý cách viết pastime chỉ có một chữ s.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_overhead', 'en-b2-82', 'overhead', '/ˌoʊvərˈhed/', 'B2', 'ở trên đầu; trên không; trên cao; chi phí hoạt động thường xuyên; chi phí chung', 'adv.', NULL, NULL, 'danh từ trọng âm ở âm tiết đầu; chi phí hoạt động tiếng Anh Anh thường dùng overheads.', 'A flock of geese flew overhead as we walked home.', NULL, 'Một đàn ngỗng bay qua đầu chúng tôi khi chúng tôi đi bộ về nhà.', '{"wordId":"overhead","ukIpa":"/ˌəʊvəˈhed/","usIpa":"/ˌoʊvərˈhed/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"above your head or in the sky","vi":"ở trên đầu; trên không"},{"pos":"adj.","en":"positioned above your head","vi":"ở trên đầu; trên cao"},{"pos":"n.","en":"regular business expenses not directly tied to particular products","vi":"chi phí hoạt động thường xuyên; chi phí chung"}],"examples":[{"en":"A flock of geese flew overhead as we walked home.","vi":"Một đàn ngỗng bay qua đầu chúng tôi khi chúng tôi đi bộ về nhà.","audioKind":"ex"},{"en":"Small businesses can reduce overhead costs by sharing office space and using energy more efficiently.","vi":"Các doanh nghiệp nhỏ có thể giảm chi phí vận hành bằng cách chia sẻ không gian văn phòng và sử dụng năng lượng hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"fly overhead","vi":"bay trên đầu"},{"en":"overhead cables","vi":"cáp trên không"},{"en":"overhead locker","vi":"khoang hành lý trên đầu"},{"en":"overhead costs","vi":"chi phí vận hành thường xuyên"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"danh từ trọng âm ở âm tiết đầu; chi phí hoạt động tiếng Anh Anh thường dùng overheads.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_quietness', 'en-b2-82', 'quietness', '/ˈkwaɪətnəs/', 'B2', 'sự yên tĩnh; sự thanh bình', 'n.', 'quiet (adj.), quietly (adv.), quieten (v.)', 'Đồng nghĩa: tranquillity, stillness · Trái nghĩa: noisiness', 'Danh từ không đếm được; trong đời thường thường dùng quiet như một danh từ.', 'I enjoyed the quietness of the garden before breakfast.', NULL, 'Tôi tận hưởng sự yên tĩnh của khu vườn trước bữa sáng.', '{"wordId":"quietness","ukIpa":"/ˈkwaɪətnəs/","usIpa":"/ˈkwaɪətnəs/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"The state of having little noise or disturbance","vi":"sự yên tĩnh; sự thanh bình"}],"examples":[{"en":"I enjoyed the quietness of the garden before breakfast.","vi":"Tôi tận hưởng sự yên tĩnh của khu vườn trước bữa sáng.","audioKind":"ex"},{"en":"The quietness of rural areas attracts residents seeking relief from the constant noise of urban life.","vi":"Sự tĩnh lặng của vùng nông thôn thu hút những cư dân đang tìm kiếm sự giải thoát khỏi tiếng ồn ào liên tục của đời sống đô thị.","audioKind":"ex2"}],"collocations":[{"en":"the quietness of the countryside","vi":"sự yên bình của vùng nông thôn"},{"en":"enjoy the quietness","vi":"tận hưởng sự yên tĩnh"},{"en":"peace and quietness","vi":"bình yên và tĩnh lặng"}],"wordFamily":["quiet (adj.)","quietly (adv.)","quieten (v.)"],"synonyms":["tranquillity","stillness"],"antonyms":["noisiness"],"tipVi":"Danh từ không đếm được; trong đời thường thường dùng quiet như một danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chatty', 'en-b2-82', 'chatty', '/ˈtʃæti/', 'B2', 'thích trò chuyện; cởi mở, hay chuyện; mang phong cách thân thiện, gần gũi', 'adj.', 'chat (v.), chat (n.)', 'Đồng nghĩa: talkative, conversational · Trái nghĩa: quiet', 'Thường chỉ sự thân thiện, hay nói, không nhất thiết mang hàm ý chê bai là ba hoa.', 'The chatty passenger beside me made the journey feel shorter.', NULL, 'Hành khách hay chuyện ngồi cạnh tôi đã giúp chuyến đi ngắn hơn.', '{"wordId":"chatty","ukIpa":"/ˈtʃæti/","usIpa":"/ˈtʃæti/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"enjoying friendly conversation and talking a lot","vi":"thích trò chuyện; cởi mở, hay chuyện"},{"pos":"adj.","en":"having a friendly, informal style of speaking or writing","vi":"mang phong cách thân thiện, gần gũi"}],"examples":[{"en":"The chatty passenger beside me made the journey feel shorter.","vi":"Hành khách hay chuyện ngồi cạnh tôi đã giúp chuyến đi ngắn hơn.","audioKind":"ex"},{"en":"A chatty writing style can make educational websites more welcoming, although complex ideas still require precise explanations.","vi":"Phong cách viết gần gũi có thể giúp các trang web giáo dục trở nên thân thiện hơn, mặc dù các ý tưởng phức tạp vẫn đòi hỏi lời giải thích chính xác.","audioKind":"ex2"}],"collocations":[{"en":"a chatty mood","vi":"tâm trạng muốn trò chuyện"},{"en":"a chatty style","vi":"phong cách trò chuyện gần gũi"},{"en":"a chatty neighbour","vi":"người hàng xóm hay chuyện"}],"wordFamily":["chat (v.)","chat (n.)"],"synonyms":["talkative","conversational"],"antonyms":["quiet"],"tipVi":"Thường chỉ sự thân thiện, hay nói, không nhất thiết mang hàm ý chê bai là ba hoa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lasting', 'en-b2-82', 'lasting', '/ˈlæstɪŋ/', 'B2', 'lâu dài; bền vững; kéo dài', 'adj.', 'last (v.)', 'Đồng nghĩa: enduring, long-lasting · Trái nghĩa: temporary, short-lived', 'Lasting nhấn mạnh việc kéo dài trong thời gian dài, không nhất thiết là vĩnh viễn như permanent.', 'Our camping trip left me with lasting memories.', NULL, 'Chuyến đi cắm trại đã để lại cho tôi những kỷ niệm khó phai.', '{"wordId":"lasting","ukIpa":"/ˈlɑːstɪŋ/","usIpa":"/ˈlæstɪŋ/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"continuing to exist or have an effect for a long time","vi":"lâu dài; bền vững; kéo dài"}],"examples":[{"en":"Our camping trip left me with lasting memories.","vi":"Chuyến đi cắm trại đã để lại cho tôi những kỷ niệm khó phai.","audioKind":"ex"},{"en":"Investment in early childhood education can bring lasting benefits to individuals and society as a whole.","vi":"Đầu tư vào giáo dục mầm non có thể mang lại những lợi ích lâu dài cho cá nhân và toàn xã hội.","audioKind":"ex2"}],"collocations":[{"en":"a lasting impression","vi":"ấn tượng sâu sắc; ấn tượng khó phai"},{"en":"lasting benefits","vi":"lợi ích lâu dài"},{"en":"lasting peace","vi":"hòa bình bền vững"},{"en":"a lasting impact","vi":"tác động lâu dài"}],"wordFamily":["last (v.)"],"synonyms":["enduring","long-lasting"],"antonyms":["temporary","short-lived"],"tipVi":"Lasting nhấn mạnh việc kéo dài trong thời gian dài, không nhất thiết là vĩnh viễn như permanent.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_craziness', 'en-b2-82', 'craziness', '/ˈkreɪzinəs/', 'B2', 'sự điên rồ; sự hỗn loạn; sự ngớ ngẩn', 'n.', 'crazy (adj.), crazily (adv.)', 'Đồng nghĩa: absurdity, wildness · Trái nghĩa: sanity', 'Thường dùng trong ngữ cảnh không trang trọng, không nên dùng làm thuật ngữ chuyên môn chỉ bệnh tâm thần.', 'We needed a quiet walk after the craziness of moving.', NULL, 'Chúng tôi cần đi dạo yên tĩnh sau sự hỗn loạn của việc chuyển nhà.', '{"wordId":"craziness","ukIpa":"/ˈkreɪzinəs/","usIpa":"/ˈkreɪzinəs/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"Behaviour or situations that are extremely foolish, wild, or chaotic","vi":"sự điên rồ; sự hỗn loạn; sự ngớ ngẩn"}],"examples":[{"en":"We needed a quiet walk after the craziness of moving.","vi":"Chúng tôi cần đi dạo yên tĩnh sau sự hỗn loạn của việc chuyển nhà.","audioKind":"ex"},{"en":"The apparent craziness of paying enormous prices for fashionable goods reflects the powerful influence of advertising.","vi":"Sự điên rồ bề ngoài của việc chi trả mức giá khổng lồ cho hàng hóa thời thượng phản ánh sức ảnh hưởng mạnh mẽ của quảng cáo.","audioKind":"ex2"}],"collocations":[{"en":"the craziness of everyday life","vi":"sự tất bật hỗn loạn của cuộc sống hàng ngày"},{"en":"sheer craziness","vi":"sự điên rồ thuần túy"},{"en":"escape the craziness","vi":"thoát khỏi sự ồn ào hỗn loạn"}],"wordFamily":["crazy (adj.)","crazily (adv.)"],"synonyms":["absurdity","wildness"],"antonyms":["sanity"],"tipVi":"Thường dùng trong ngữ cảnh không trang trọng, không nên dùng làm thuật ngữ chuyên môn chỉ bệnh tâm thần.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_misfortune', 'en-b2-82', 'misfortune', '/ˌmɪsˈfɔːrtʃuːn/', 'B2', 'sự bất hạnh; vận rủi', 'n.', 'fortune (n.), unfortunate (adj.), unfortunately (adv.)', 'Đồng nghĩa: bad luck · Trái nghĩa: good fortune', 'chỉ vận rủi thì không đếm được; chỉ sự việc bất hạnh cụ thể thì đếm được.', 'We had the misfortune to miss the last train.', NULL, 'Chúng tôi rất không may mắn khi bỏ lỡ chuyến tàu cuối cùng.', '{"wordId":"misfortune","ukIpa":"/ˌmɪsˈfɔːtʃuːn/","usIpa":"/ˌmɪsˈfɔːrtʃuːn/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"bad luck or an unlucky event that causes difficulty","vi":"sự bất hạnh; vận rủi"}],"examples":[{"en":"We had the misfortune to miss the last train.","vi":"Chúng tôi rất không may mắn khi bỏ lỡ chuyến tàu cuối cùng.","audioKind":"ex"},{"en":"Strong community networks can help families recover from financial misfortune without becoming isolated from society.","vi":"Mạng lưới cộng đồng vững chắc có thể giúp các gia đình vượt qua khó khăn tài chính mà không bị cô lập khỏi xã hội.","audioKind":"ex2"}],"collocations":[{"en":"have the misfortune to do","vi":"không may làm gì đó"},{"en":"financial misfortune","vi":"khó khăn tài chính"},{"en":"a series of misfortunes","vi":"một chuỗi những bất hạnh"}],"wordFamily":["fortune (n.)","unfortunate (adj.)","unfortunately (adv.)"],"synonyms":["bad luck"],"antonyms":["good fortune"],"tipVi":"chỉ vận rủi thì không đếm được; chỉ sự việc bất hạnh cụ thể thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_imperfect', 'en-b2-82', 'imperfect', '/ɪmˈpɝːfɪkt/', 'B2', 'không hoàn hảo; có khuyết điểm', 'adj.', 'perfect (adj.), imperfection (n.), imperfectly (adv.)', 'Đồng nghĩa: flawed, faulty · Trái nghĩa: perfect, flawless', 'chỉ sự có khuyết điểm, không đồng nghĩa với hoàn toàn vô dụng hay thất bại.', 'This handmade bowl is imperfect, but I love its shape.', NULL, 'Cái bát thủ công này không hoàn hảo, nhưng tôi thích hình dáng của nó.', '{"wordId":"imperfect","ukIpa":"/ɪmˈpɜːfɪkt/","usIpa":"/ɪmˈpɝːfɪkt/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Having faults or lacking something needed to be complete.","vi":"không hoàn hảo; có khuyết điểm"}],"examples":[{"en":"This handmade bowl is imperfect, but I love its shape.","vi":"Cái bát thủ công này không hoàn hảo, nhưng tôi thích hình dáng của nó.","audioKind":"ex"},{"en":"Although the current recycling system is imperfect, it still reduces the amount of waste sent to landfill.","vi":"Mặc dù hệ thống tái chế hiện tại chưa hoàn thiện, nó vẫn làm giảm lượng rác thải gửi đến bãi chôn lấp.","audioKind":"ex2"}],"collocations":[{"en":"an imperfect solution","vi":"một giải pháp chưa hoàn thiện"},{"en":"imperfect knowledge","vi":"kiến thức chưa đầy đủ"},{"en":"imperfect competition","vi":"cạnh tranh không hoàn hảo"}],"wordFamily":["perfect (adj.)","imperfection (n.)","imperfectly (adv.)"],"synonyms":["flawed","faulty"],"antonyms":["perfect","flawless"],"tipVi":"chỉ sự có khuyết điểm, không đồng nghĩa với hoàn toàn vô dụng hay thất bại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_indirect', 'en-b2-82', 'indirect', '/ˌɪndəˈrekt/', 'B2', 'gián tiếp; vòng vo; không thẳng thắn', 'adj.', 'indirectly (adv.), direct (adj.), directly (adv.)', 'Trái nghĩa: direct', 'Từ này vừa có thể chỉ ảnh hưởng thông qua trung gian, vừa chỉ cách diễn đạt không trực diện.', 'This plant grows best in bright but indirect sunlight.', NULL, 'Loài cây này phát triển tốt nhất dưới ánh nắng rực rỡ nhưng không chiếu trực tiếp.', '{"wordId":"indirect","ukIpa":"/ˌɪndəˈrekt/","usIpa":"/ˌɪndəˈrekt/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Happening through another person, action, or stage","vi":"gián tiếp"},{"pos":"adj.","en":"Not following a straight route or expressing something openly","vi":"vòng vo; không thẳng thắn"}],"examples":[{"en":"This plant grows best in bright but indirect sunlight.","vi":"Loài cây này phát triển tốt nhất dưới ánh nắng rực rỡ nhưng không chiếu trực tiếp.","audioKind":"ex"},{"en":"Tourism provides indirect benefits to local farmers by increasing demand for fresh food in restaurants.","vi":"Du lịch mang lại lợi ích gián tiếp cho nông dân địa phương bằng cách làm tăng nhu cầu đối với thực phẩm tươi sống tại các nhà hàng.","audioKind":"ex2"}],"collocations":[{"en":"indirect impact","vi":"tác động gián tiếp"},{"en":"indirect sunlight","vi":"ánh nắng không trực tiếp"},{"en":"indirect taxes","vi":"thuế gián tiếp"},{"en":"indirect route","vi":"tuyến đường vòng"}],"wordFamily":["indirectly (adv.)","direct (adj.)","directly (adv.)"],"synonyms":[],"antonyms":["direct"],"tipVi":"Từ này vừa có thể chỉ ảnh hưởng thông qua trung gian, vừa chỉ cách diễn đạt không trực diện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_texture', 'en-b2-82', 'texture', '/ˈtekstʃər/', 'B2', 'kết cấu; vân; độ mịn/thô; cảm giác khi chạm vào hoặc độ mịn khi ăn', 'n.', 'textured (adj.), textural (adj.)', NULL, 'Có thể dùng để mô tả cảm giác xúc giác của vật liệu hoặc kết cấu/cảm giác khi ăn thực phẩm.', 'This blanket has a soft texture that feels lovely.', NULL, 'Chiếc chăn này có kết cấu mềm mại, sờ vào rất thích.', '{"wordId":"texture","ukIpa":"/ˈtekstʃə/","usIpa":"/ˈtekstʃər/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"The way a surface or substance feels or looks.","vi":"kết cấu; vân; độ mịn/thô; cảm giác khi chạm vào hoặc độ mịn khi ăn"}],"examples":[{"en":"This blanket has a soft texture that feels lovely.","vi":"Chiếc chăn này có kết cấu mềm mại, sờ vào rất thích.","audioKind":"ex"},{"en":"The texture of recycled materials can influence whether consumers find sustainable products attractive.","vi":"Kết cấu của vật liệu tái chế có thể ảnh hưởng đến việc liệu người tiêu dùng có thấy các sản phẩm bền vững hấp dẫn hay không.","audioKind":"ex2"}],"collocations":[{"en":"smooth texture","vi":"kết cấu mịn"},{"en":"rough texture","vi":"kết cấu thô"},{"en":"creamy texture","vi":"độ mịn màng (của đồ ăn)"}],"wordFamily":["textured (adj.)","textural (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể dùng để mô tả cảm giác xúc giác của vật liệu hoặc kết cấu/cảm giác khi ăn thực phẩm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_82_1', 'en-b2-82', 'Cách dùng “incidentally” (adv.) — tiện thể; nhân tiện; thuận miệng', 'incidentally acquired  ·  learn incidentally  ·  mention incidentally', 'Ở đầu câu thường mang nghĩa "nhân tiện/tiện thể"; không phải lúc nào cũng mang nghĩa tình cờ trong mọi ngữ cảnh.', 'Họ từ (Word Family): incidental (adj.), incident (n.) | Đồng nghĩa: by the way', '[{"hanzi":"Incidentally, your scarf is still hanging by our door.","pinyin":"","meaning":"Nhân tiện, chiếc khăn choàng của bạn vẫn đang treo ở cửa nhà chúng tôi kìa."},{"hanzi":"Children may learn new vocabulary incidentally while watching educational programmes, even when language learning is not their main goal.","pinyin":"","meaning":"Trẻ em có thể tình cờ học được từ vựng mới khi xem các chương trình giáo dục, ngay cả khi mục tiêu chính của chúng không phải là học ngôn ngữ."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_82_2', 'en-b2-82', 'Cách dùng “gaze” (v.) — nhìn chăm chú; ngắm nhìn', 'gaze at  ·  gaze out of the window  ·  meet someone''s gaze', 'Động từ gaze thường đi với giới từ at; so với glance thì nhìn lâu hơn, và thường dịu dàng, trầm lắng hơn stare.', 'Đồng nghĩa: stare', '[{"hanzi":"Lina gazed at the moon through her bedroom window.","pinyin":"","meaning":"Lina ngắm nhìn mặt trăng qua khung cửa sổ phòng ngủ."},{"hanzi":"Visitors often gaze at historic buildings, yet overlook the maintenance work required to preserve these cultural treasures.","pinyin":"","meaning":"Du khách thường ngắm nhìn các công trình lịch sử nhưng lại bỏ qua công tác bảo trì cần thiết để bảo tồn những báu vật văn hóa này."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_82_3', 'en-b2-82', 'Cách dùng “craziness” (n.) — sự điên rồ; sự hỗn loạn; sự ngớ ngẩn', 'the craziness of everyday life  ·  sheer craziness  ·  escape the craziness', 'Thường dùng trong ngữ cảnh không trang trọng, không nên dùng làm thuật ngữ chuyên môn chỉ bệnh tâm thần.', 'Họ từ (Word Family): crazy (adj.), crazily (adv.) | Đồng nghĩa: absurdity, wildness · Trái nghĩa: sanity', '[{"hanzi":"We needed a quiet walk after the craziness of moving.","pinyin":"","meaning":"Chúng tôi cần đi dạo yên tĩnh sau sự hỗn loạn của việc chuyển nhà."},{"hanzi":"The apparent craziness of paying enormous prices for fashionable goods reflects the powerful influence of advertising.","pinyin":"","meaning":"Sự điên rồ bề ngoài của việc chi trả mức giá khổng lồ cho hàng hóa thời thượng phản ánh sức ảnh hưởng mạnh mẽ của quảng cáo."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_82_4', 'en-b2-82', 'Cách dùng “dresser” (n.) — tủ có ngăn kéo để đựng quần áo (kiểu Mỹ)', 'bedroom dresser  ·  kitchen dresser  ·  a smart dresser', 'Tiếng Mỹ thường chỉ tủ có ngăn kéo đựng quần áo, trong khi tiếng Anh thường chỉ tủ đựng chén đĩa.', 'Họ từ (Word Family): dress (v.), dressed (adj.)', '[{"hanzi":"I put my clean socks in the bedroom dresser.","pinyin":"","meaning":"Tôi cất những chiếc tất sạch vào chiếc tủ có ngăn kéo trong phòng ngủ."},{"hanzi":"Restoring an old dresser rather than buying new furniture can reduce waste and conserve natural resources.","pinyin":"","meaning":"Việc phục chế lại một chiếc tủ cũ thay vì mua đồ nội thất mới có thể giúp giảm thiểu rác thải và bảo tồn tài nguyên thiên nhiên."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
