INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_82_1_4', 'ten_b2_82_1', 'thicken', 'Add a little flour to thicken the mushroom sauce.', 'Add a little flour to thicken the mushroom sauce.', '/ˈθɪkən/', 'Cho thêm một chút bột mì để làm sánh sốt nấm lại.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_82_1_5', 'ten_b2_82_1', 'gaze', 'Lina gazed at the moon through her bedroom window.', 'Lina gazed at the moon through her bedroom window.', '/ɡeɪz/', 'Lina ngắm nhìn mặt trăng qua khung cửa sổ phòng ngủ.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_82_1_6', 'ten_b2_82_1', 'lump', 'She dropped a lump of clay onto the table.', 'She dropped a lump of clay onto the table.', '/lʌmp/', 'Cô ấy thả một cục đất sét xuống bàn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_82_1_7', 'ten_b2_82_1', 'expiry', 'My passport is getting close to its expiry date.', 'My passport is getting close to its expiry date.', '/ɪkˈspaɪri/', 'Hộ chiếu của tôi sắp đến ngày hết hạn.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_82_1_8', 'ten_b2_82_1', 'incomplete', 'The puzzle is incomplete because several pieces are missing.', 'The puzzle is incomplete because several pieces are missing.', '/ˌɪnkəmˈpliːt/', 'Bức tranh ghép hình này chưa hoàn chỉnh vì thiếu mất vài mảnh.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_82_1_1', 'en-b2-82', 'ten_b2_82_1', 'listening', 'listening', 'I put my clean socks in the bedroom dresser.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nhân tiện, chiếc khăn choàng của bạn vẫn đang treo ở cửa nhà chúng tôi kìa.","Một đàn ngỗng bay qua đầu chúng tôi khi chúng tôi đi bộ về nhà.","Tôi cất những chiếc tất sạch vào chiếc tủ có ngăn kéo trong phòng ngủ.","Loài cây này phát triển tốt nhất dưới ánh nắng rực rỡ nhưng không chiếu trực tiếp."]'::jsonb, 2, 'I put my clean socks in the bedroom dresser. → Tôi cất những chiếc tất sạch vào chiếc tủ có ngăn kéo trong phòng ngủ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_82_1_2', 'en-b2-82', 'ten_b2_82_1', 'listening', 'listening', 'Incidentally, your scarf is still hanging by our door.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi cần đi dạo yên tĩnh sau sự hỗn loạn của việc chuyển nhà.","Chị gái sẽ đi cùng tôi đến phòng khám vào ngày mai.","Chiếc chăn này có kết cấu mềm mại, sờ vào rất thích.","Nhân tiện, chiếc khăn choàng của bạn vẫn đang treo ở cửa nhà chúng tôi kìa."]'::jsonb, 3, 'Incidentally, your scarf is still hanging by our door. → Nhân tiện, chiếc khăn choàng của bạn vẫn đang treo ở cửa nhà chúng tôi kìa.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_82_1_3', 'en-b2-82', 'ten_b2_82_1', 'listening', 'listening', 'The kitchen bulb failed while I was washing dishes.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bóng đèn trong bếp bị hỏng khi tôi đang rửa bát.","Tôi tận hưởng sự yên tĩnh của khu vườn trước bữa sáng.","Cô ấy nhẹ nhàng vỗ về chú chó khi nó chìm vào giấc ngủ.","Chiếc chăn này có kết cấu mềm mại, sờ vào rất thích."]'::jsonb, 0, 'The kitchen bulb failed while I was washing dishes. → Bóng đèn trong bếp bị hỏng khi tôi đang rửa bát.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_82_2', 'en-b2-82', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_82_2_1', 'ten_b2_82_2', 'dresser', 'Restoring an old dresser rather than buying new furniture can reduce waste and conserve natural resources.', 'Restoring an old dresser rather than buying new furniture can reduce waste and conserve natural resources.', '/ˈdresər/', 'Việc phục chế lại một chiếc tủ cũ thay vì mua đồ nội thất mới có thể giúp giảm thiểu rác thải và bảo tồn tài nguyên thiên nhiên.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_82_2_2', 'ten_b2_82_2', 'incidentally', 'Children may learn new vocabulary incidentally while watching educational programmes, even when language learning is not their main goal.', 'Children may learn new vocabulary incidentally while watching educational programmes, even when language learning is not their main goal.', '/ˌɪnsɪˈdentəli/', 'Trẻ em có thể tình cờ học được từ vựng mới khi xem các chương trình giáo dục, ngay cả khi mục tiêu chính của chúng không phải là học ngôn ngữ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_82_2_3', 'ten_b2_82_2', 'bulb', 'Replacing traditional bulbs with energy-efficient alternatives can reduce household electricity consumption and lower long-term costs.', 'Replacing traditional bulbs with energy-efficient alternatives can reduce household electricity consumption and lower long-term costs.', '/bʌlb/', 'Việc thay thế các bóng đèn truyền thống bằng các giải pháp tiết kiệm năng lượng có thể làm giảm lượng điện tiêu thụ trong gia đình và tiết kiệm chi phí lâu dài.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_82_2_4', 'ten_b2_82_2', 'thicken', 'As coastal fog thickens, transport operators may need to reduce services to maintain passenger safety.', 'As coastal fog thickens, transport operators may need to reduce services to maintain passenger safety.', '/ˈθɪkən/', 'Khi sương mù ven biển dày đặc hơn, các đơn vị vận tải có thể phải giảm bớt chuyến để đảm bảo an toàn cho hành khách.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_82_2_5', 'ten_b2_82_2', 'gaze', 'Visitors often gaze at historic buildings, yet overlook the maintenance work required to preserve these cultural treasures.', 'Visitors often gaze at historic buildings, yet overlook the maintenance work required to preserve these cultural treasures.', '/ɡeɪz/', 'Du khách thường ngắm nhìn các công trình lịch sử nhưng lại bỏ qua công tác bảo trì cần thiết để bảo tồn những báu vật văn hóa này.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_82_2_6', 'ten_b2_82_2', 'lump', 'Policymakers should not lump all unemployed people together, as their circumstances and support needs vary considerably.', 'Policymakers should not lump all unemployed people together, as their circumstances and support needs vary considerably.', '/lʌmp/', 'Các nhà hoạch định chính sách không nên gộp chung tất cả những người thất nghiệp lại với nhau, vì hoàn cảnh và nhu cầu hỗ trợ của họ rất khác nhau.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_82_2_1', 'en-b2-82', 'ten_b2_82_2', 'listening', 'listening', 'Restoring an old dresser rather than buying new furniture can reduce waste and conserve natural resources.', NULL, 'Trong câu vừa nghe, từ “dresser” mang nghĩa nào sau đây?', '["nhàn rỗi; không hoạt động; bỏ không","tủ có ngăn kéo để đựng quần áo (kiểu Mỹ)","vô lý; ngớ ngẩn; lố bịch","vữa; lớp trát tường; thạch cao"]'::jsonb, 1, '“dresser” (/ˈdresər/): tủ có ngăn kéo để đựng quần áo (kiểu Mỹ). Câu đầy đủ: Restoring an old dresser rather than buying new furniture can reduce waste and conserve natural resources.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_82_2_2', 'en-b2-82', 'ten_b2_82_2', 'listening', 'listening', 'Children may learn new vocabulary incidentally while watching educational programmes, even when language learning is not their main goal.', NULL, 'Trong câu vừa nghe, từ “incidentally” mang nghĩa nào sau đây?', '["vô cùng ngốc nghếch; phi lý; nguy hiểm","đồng (kim loại màu nâu đỏ)","tiện thể; nhân tiện; thuận miệng","mạnh mẽ; quyết liệt; triệt để; đáng kể"]'::jsonb, 2, '“incidentally” (/ˌɪnsɪˈdentəli/): tiện thể; nhân tiện; thuận miệng. Câu đầy đủ: Children may learn new vocabulary incidentally while watching educational programmes, even when language learning is not their main goal.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_82_1', 'en-b2-82', 'I put my clean socks in the bedroom dresser', 'Tôi cất những chiếc tất sạch vào chiếc tủ có ngăn kéo trong phòng ngủ.', 'dresser /ˈdresər/', '["put","I","in","dresser","my","bedroom","the","socks","clean"]'::jsonb, NULL, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_82_2', 'en-b2-82', 'Incidentally, your scarf is still hanging by our door', 'Nhân tiện, chiếc khăn choàng của bạn vẫn đang treo ở cửa nhà chúng tôi kìa.', 'incidentally /ˌɪnsɪˈdentəli/', '["still","our","Incidentally","door","hanging","scarf","your","by","is"]'::jsonb, NULL, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_82_3', 'en-b2-82', 'The kitchen bulb failed while I was washing dishes', 'Bóng đèn trong bếp bị hỏng khi tôi đang rửa bát.', 'bulb /bʌlb/', '["I","dishes","bulb","failed","kitchen","The","washing","was","while"]'::jsonb, NULL, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_82_4', 'en-b2-82', 'Add a little flour to thicken the mushroom sauce', 'Cho thêm một chút bột mì để làm sánh sốt nấm lại.', 'thicken /ˈθɪkən/', '["mushroom","a","Add","to","thicken","sauce","little","the","flour"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_82_5', 'en-b2-82', 'Lina gazed at the moon through her bedroom window', 'Lina ngắm nhìn mặt trăng qua khung cửa sổ phòng ngủ.', 'gaze /ɡeɪz/', '["her","Lina","at","bedroom","moon","window","the","gazed","through"]'::jsonb, NULL, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_82_6', 'en-b2-82', 'She dropped a lump of clay onto the table', 'Cô ấy thả một cục đất sét xuống bàn.', 'lump /lʌmp/', '["dropped","lump","clay","a","table","She","the","onto","of"]'::jsonb, NULL, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_82_7', 'en-b2-82', 'My passport is getting close to its expiry date', 'Hộ chiếu của tôi sắp đến ngày hết hạn.', 'expiry /ɪkˈspaɪri/', '["passport","its","is","date","close","expiry","to","My","getting"]'::jsonb, NULL, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_82_8', 'en-b2-82', 'The puzzle is incomplete because several pieces are missing', 'Bức tranh ghép hình này chưa hoàn chỉnh vì thiếu mất vài mảnh.', 'incomplete /ˌɪnkəmˈpliːt/', '["because","missing","puzzle","several","is","are","incomplete","The","pieces"]'::jsonb, NULL, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_82_9', 'en-b2-82', 'Without its missing parts, this old machine is worthless', 'Thiếu đi các bộ phận bị mất, cỗ máy cũ này trở nên hoàn toàn vô tích sự.', 'worthless /ˈwɝːθləs/', '["old","missing","worthless","parts","is","machine","its","Without","this"]'::jsonb, NULL, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b2_82_10', 'en-b2-82', 'The drilling upstairs caused a disturbance during our dinner', 'Tiếng khoan ở trên lầu đã làm phiền chúng tôi trong suốt bữa tối.', 'disturbance /dɪˈstɝːbəns/', '["a","The","caused","drilling","upstairs","during","disturbance","our","dinner"]'::jsonb, NULL, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
