INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_82_2', 'en-b2-82', NULL, 'comprehensive_test', 'listening', 'Incidentally, your scarf is still hanging by our door.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nhân tiện, chiếc khăn choàng của bạn vẫn đang treo ở cửa nhà chúng tôi kìa.","Làm vườn trở thành hoạt động giải trí yêu thích của bà ấy sau khi nghỉ hưu.","Cái bát thủ công này không hoàn hảo, nhưng tôi thích hình dáng của nó.","Tôi cho thêm một chút mật khẩu vào cháo để làm cho nó ngọt hơn."]'::jsonb, 0, 'Incidentally, your scarf is still hanging by our door. → Nhân tiện, chiếc khăn choàng của bạn vẫn đang treo ở cửa nhà chúng tôi kìa.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_82_3', 'en-b2-82', NULL, 'comprehensive_test', 'listening', 'bulb', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bò; trườn (bằng tay và đầu gối)","sự tiến hóa","bóng đèn","người thuê nhà; người thuê đất"]'::jsonb, 2, 'bulb (/bʌlb/) → bóng đèn; củ (thực vật)', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_82_4', 'en-b2-82', NULL, 'comprehensive_test', 'listening', 'Add a little flour to thicken the mushroom sauce.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cho thêm một chút bột mì để làm sánh sốt nấm lại.","Bóng đèn trong bếp bị hỏng khi tôi đang rửa bát.","Tôi cất những chiếc tất sạch vào chiếc tủ có ngăn kéo trong phòng ngủ.","Chúng tôi cần đi dạo yên tĩnh sau sự hỗn loạn của việc chuyển nhà."]'::jsonb, 0, 'Add a little flour to thicken the mushroom sauce. → Cho thêm một chút bột mì để làm sánh sốt nấm lại.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_82_5', 'en-b2-82', NULL, 'comprehensive_test', 'listening', 'gaze', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đặc điểm; nét tiêu biểu của một người hoặc một vật","giờ làm thêm; tiền làm thêm giờ","nở; ấp trứng","nhìn chăm chú; ngắm nhìn"]'::jsonb, 3, 'gaze (/ɡeɪz/) → nhìn chăm chú; ngắm nhìn; ánh mắt chăm chú; cái nhìn đăm đăm', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_82_6', 'en-b2-82', NULL, 'comprehensive_test', 'listening', 'She dropped a lump of clay onto the table.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy thả một cục đất sét xuống bàn.","Bóng đèn trong bếp bị hỏng khi tôi đang rửa bát.","Một đàn ngỗng bay qua đầu chúng tôi khi chúng tôi đi bộ về nhà.","Làm vườn trở thành hoạt động giải trí yêu thích của bà ấy sau khi nghỉ hưu."]'::jsonb, 0, 'She dropped a lump of clay onto the table. → Cô ấy thả một cục đất sét xuống bàn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_82_7', 'en-b2-82', NULL, 'comprehensive_test', 'listening', 'expiry', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự chậm trễ; sự tắc nghẽn","hết hạn; sự mãn hạn","cử tri; người bỏ phiếu","ánh trăng"]'::jsonb, 1, 'expiry (/ɪkˈspaɪri/) → hết hạn; sự mãn hạn', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_82_8', 'en-b2-82', NULL, 'comprehensive_test', 'listening', 'The puzzle is incomplete because several pieces are missing.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi cất những chiếc tất sạch vào chiếc tủ có ngăn kéo trong phòng ngủ.","Cô ấy thả một cục đất sét xuống bàn.","Loài cây này phát triển tốt nhất dưới ánh nắng rực rỡ nhưng không chiếu trực tiếp.","Bức tranh ghép hình này chưa hoàn chỉnh vì thiếu mất vài mảnh."]'::jsonb, 3, 'The puzzle is incomplete because several pieces are missing. → Bức tranh ghép hình này chưa hoàn chỉnh vì thiếu mất vài mảnh.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_82_9', 'en-b2-82', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To look steadily at something for a long time.”?', '["worthless","chatty","gaze","bulk"]'::jsonb, 2, 'gaze (/ɡeɪz/) → nhìn chăm chú; ngắm nhìn', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_82_10', 'en-b2-82', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A solid piece without a regular shape.”?', '["bulb","quietness","lump","bulk"]'::jsonb, 2, 'lump (/lʌmp/) → cục; khối', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_82_11', 'en-b2-82', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “The end of the period when something remains valid.”?', '["quietness","indirect","expiry","bulb"]'::jsonb, 2, 'expiry (/ɪkˈspaɪri/) → hết hạn; sự mãn hạn', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_82_12', 'en-b2-82', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “missing some parts or not yet finished”?', '["incomplete","expiry","dresser","sweeten"]'::jsonb, 0, 'incomplete (/ˌɪnkəmˈpliːt/) → chưa hoàn chỉnh; chưa hoàn thành', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
