INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_82_18', 'en-b2-82', NULL, 'comprehensive_test', 'reading', NULL, 'Restoring an old dresser rather than buying new furniture can reduce waste and conserve natural resources.', 'Dựa vào câu trên, từ “dresser” có nghĩa phù hợp nhất là gì?', '["nước thải; chất thải sinh hoạt","quay; xoay tròn","khuôn; khuôn đúc","tủ có ngăn kéo để đựng quần áo (kiểu Mỹ)"]'::jsonb, 3, 'dresser: tủ có ngăn kéo để đựng quần áo (kiểu Mỹ); tủ đựng bát đĩa có kệ ở trên để trưng bày (kiểu Anh); người ăn mặc theo một phong cách cụ thể nào đó. Dịch cả câu: Việc phục chế lại một chiếc tủ cũ thay vì mua đồ nội thất mới có thể giúp giảm thiểu rác thải và bảo tồn tài nguyên thiên nhiên.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_82_19', 'en-b2-82', NULL, 'comprehensive_test', 'reading', NULL, 'Children may learn new vocabulary incidentally while watching educational programmes, even when language learning is not their main goal.', 'Dựa vào câu trên, từ “incidentally” có nghĩa phù hợp nhất là gì?', '["có ích; có lợi","tiện thể; nhân tiện; thuận miệng","sưng tấy, sưng phồng (do chấn thương hoặc bệnh tật)","rạn đá ngầm; đá ngầm"]'::jsonb, 1, 'incidentally: tiện thể; nhân tiện; thuận miệng; tình cờ; phụ họa. Dịch cả câu: Trẻ em có thể tình cờ học được từ vựng mới khi xem các chương trình giáo dục, ngay cả khi mục tiêu chính của chúng không phải là học ngôn ngữ.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_82_20', 'en-b2-82', NULL, 'comprehensive_test', 'reading', NULL, 'Replacing traditional bulbs with energy-efficient alternatives can reduce household electricity consumption and lower long-term costs.', 'Dựa vào câu trên, từ “bulb” có nghĩa phù hợp nhất là gì?', '["sự mất thể diện; sự ô nhục","gạt bỏ; xem nhẹ; không màng tới","bóng đèn","cô đơn; buồn tủi"]'::jsonb, 2, 'bulb: bóng đèn; củ (thực vật). Dịch cả câu: Việc thay thế các bóng đèn truyền thống bằng các giải pháp tiết kiệm năng lượng có thể làm giảm lượng điện tiêu thụ trong gia đình và tiết kiệm chi phí lâu dài.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_82_21', 'en-b2-82', NULL, 'comprehensive_test', 'reading', NULL, 'As coastal fog thickens, transport operators may need to reduce services to maintain passenger safety.', 'Dựa vào câu trên, từ “thicken” có nghĩa phù hợp nhất là gì?', '["mẫu; mẫu vật; vật mẫu","khác nhau; thay đổi tùy theo hoàn cảnh","mắc chứng mù màu; không phân biệt được màu sắc","làm đặc; làm sánh lại"]'::jsonb, 3, 'thicken: làm đặc; làm sánh lại; làm dày lên; trở nên đặc hơn. Dịch cả câu: Khi sương mù ven biển dày đặc hơn, các đơn vị vận tải có thể phải giảm bớt chuyến để đảm bảo an toàn cho hành khách.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_82_22', 'en-b2-82', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “không hoàn hảo; có khuyết điểm”', '["imperfect","expansion","accounting","portray"]'::jsonb, 0, 'không hoàn hảo; có khuyết điểm → imperfect (/ɪmˈpɝːfɪkt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_82_23', 'en-b2-82', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “gián tiếp”', '["budget","indirect","errand","anger"]'::jsonb, 1, 'gián tiếp → indirect (/ˌɪndəˈrekt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_82_24', 'en-b2-82', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “kết cấu; vân; độ mịn/thô; cảm giác khi chạm vào hoặc độ mịn khi ăn”', '["marked","concentration","texture","fluid"]'::jsonb, 2, 'kết cấu; vân; độ mịn/thô; cảm giác khi chạm vào hoặc độ mịn khi ăn → texture (/ˈtekstʃər/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-83', 'en', 'Bài 83: Đời sống hằng ngày (10) - CEFR B2', 'CEFR B2', 'B2 · Đời sống', '26 từ vựng Tiếng Anh CEFR B2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4083, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_initial', 'en-b2-83', 'initial', '/ɪˈnɪʃəl/', 'B2', 'ban đầu; lúc đầu; chữ cái đầu trong tên của một người; ký tên bằng chữ cái đầu', 'adj.', 'initially (adv.)', 'Đồng nghĩa: first, preliminary · Trái nghĩa: final', 'Tính từ thường đứng trước danh từ; chữ cái đầu của tên thường dùng dạng số nhiều initials.', 'My initial excitement faded when I saw the price.', NULL, 'Sự hào hứng ban đầu của tôi đã vụt tắt khi nhìn thấy giá tiền.', '{"wordId":"initial","ukIpa":"/ɪˈnɪʃəl/","usIpa":"/ɪˈnɪʃəl/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Happening or existing at the beginning","vi":"ban đầu; lúc đầu"},{"pos":"n.","en":"The first letter of a person''s name","vi":"chữ cái đầu trong tên của một người"},{"pos":"v.","en":"To mark a document with the first letters of your names","vi":"ký tên bằng chữ cái đầu"}],"examples":[{"en":"My initial excitement faded when I saw the price.","vi":"Sự hào hứng ban đầu của tôi đã vụt tắt khi nhìn thấy giá tiền.","audioKind":"ex"},{"en":"Although the initial cost of solar panels is high, households may save money over the longer term.","vi":"Mặc dù chi phí ban đầu của các tấm pin năng lượng mặt trời khá cao, các hộ gia đình có thể tiết kiệm tiền về lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"initial reaction","vi":"phản ứng ban đầu"},{"en":"initial assessment","vi":"đánh giá ban đầu"},{"en":"initial cost","vi":"chi phí ban đầu"},{"en":"initial stages","vi":"giai đoạn đầu"}],"wordFamily":["initially (adv.)"],"synonyms":["first","preliminary"],"antonyms":["final"],"tipVi":"Tính từ thường đứng trước danh từ; chữ cái đầu của tên thường dùng dạng số nhiều initials.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_peculiar', 'en-b2-83', 'peculiar', '/pɪˈkjuːljɚ/', 'B2', 'kỳ lạ; bất thường (đôi khi theo cách khó chịu); đặc thù; độc quyền của một người, nhóm, địa điểm hoặc vật cụ thể', 'adj.', 'peculiarity (n.), peculiarly (adv.)', 'Đồng nghĩa: strange, odd, unusual · Trái nghĩa: ordinary, normal', 'Cụm peculiar to có nghĩa là "đặc trưng của...", không mang nghĩa là "kỳ lạ".', 'A peculiar smell came from the cupboard under the stairs.', NULL, 'Một mùi kỳ lạ phát ra từ chiếc tủ dưới cầu thang.', '{"wordId":"peculiar","ukIpa":"/pɪˈkjuːliə/","usIpa":"/pɪˈkjuːljɚ/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"strange or unusual, sometimes in an unpleasant way","vi":"kỳ lạ; bất thường (đôi khi theo cách khó chịu)"},{"pos":"adj.","en":"belonging only to a particular person, group, place, or thing","vi":"đặc thù; độc quyền của một người, nhóm, địa điểm hoặc vật cụ thể"}],"examples":[{"en":"A peculiar smell came from the cupboard under the stairs.","vi":"Một mùi kỳ lạ phát ra từ chiếc tủ dưới cầu thang.","audioKind":"ex"},{"en":"Some environmental challenges are peculiar to coastal cities, including saltwater intrusion and damage caused by storm surges.","vi":"Một số thách thức về môi trường là nét đặc thù của các thành phố ven biển, bao gồm tình trạng xâm nhập mặn và thiệt hại do bão dâng gây ra.","audioKind":"ex2"}],"collocations":[{"en":"peculiar smell","vi":"mùi lạ"},{"en":"peculiar behaviour","vi":"hành vi kỳ lạ"},{"en":"peculiar to","vi":"đặc trưng của; chỉ riêng cho"}],"wordFamily":["peculiarity (n.)","peculiarly (adv.)"],"synonyms":["strange","odd","unusual"],"antonyms":["ordinary","normal"],"tipVi":"Cụm peculiar to có nghĩa là \"đặc trưng của...\", không mang nghĩa là \"kỳ lạ\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lean', 'en-b2-83', 'lean', '/liːn/', 'B2', 'nghiêng; tựa; dựa; ít mỡ; nạc; tinh gọn; hiệu quả và tiết kiệm', 'v.', 'leaning (n.), leanness (n.)', NULL, 'Lean against có nghĩa là tựa vào; lean towards có thể mang nghĩa là có xu hướng ngả về phía.', 'She leaned against the wall and untied her shoes.', NULL, 'Cô ấy tựa lưng vào tường và cởi giày ra.', '{"wordId":"lean","ukIpa":"/liːn/","usIpa":"/liːn/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"Bend or rest against something in a sloping position.","vi":"nghiêng; tựa; dựa"},{"pos":"adj.","en":"Having little body fat or containing little fat.","vi":"ít mỡ; nạc"},{"pos":"adj.","en":"Using few resources while avoiding waste.","vi":"tinh gọn; hiệu quả và tiết kiệm"}],"examples":[{"en":"She leaned against the wall and untied her shoes.","vi":"Cô ấy tựa lưng vào tường và cởi giày ra.","audioKind":"ex"},{"en":"Lean production methods can help manufacturers reduce waste while maintaining the quality of their products.","vi":"Các phương pháp sản xuất tinh gọn có thể giúp nhà sản xuất giảm thiểu lãng phí trong khi vẫn duy trì chất lượng sản phẩm.","audioKind":"ex2"}],"collocations":[{"en":"lean against a wall","vi":"dựa vào tường"},{"en":"lean forward","vi":"nghiêng người về phía trước"},{"en":"lean meat","vi":"thịt nạc"},{"en":"lean production","vi":"sản xuất tinh gọn"}],"wordFamily":["leaning (n.)","leanness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Lean against có nghĩa là tựa vào; lean towards có thể mang nghĩa là có xu hướng ngả về phía.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_milestone', 'en-b2-83', 'milestone', '/ˈmaɪlstoʊn/', 'B2', 'cột mốc quan trọng; bước ngoặt; cột mốc chỉ đường', 'n.', NULL, 'Đồng nghĩa: landmark', 'Thường chỉ các mốc phát triển quan trọng, hay đi kèm với giới từ in.', 'Getting her first job was a milestone for Sara.', NULL, 'Có được công việc đầu tiên là một cột mốc quan trọng đối với Sara.', '{"wordId":"milestone","ukIpa":"/ˈmaɪlstəʊn/","usIpa":"/ˈmaɪlstoʊn/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"An important event or stage in development.","vi":"cột mốc quan trọng; bước ngoặt"},{"pos":"n.","en":"A roadside stone showing the distance to a place.","vi":"cột mốc chỉ đường"}],"examples":[{"en":"Getting her first job was a milestone for Sara.","vi":"Có được công việc đầu tiên là một cột mốc quan trọng đối với Sara.","audioKind":"ex"},{"en":"The opening of the railway marked a significant milestone in the region''s economic development.","vi":"Việc khai trương tuyến đường sắt đánh dấu một cột mốc đáng kể trong sự phát triển kinh tế của vùng.","audioKind":"ex2"}],"collocations":[{"en":"reach a milestone","vi":"đạt đến cột mốc quan trọng"},{"en":"mark a milestone","vi":"đánh dấu một cột mốc"},{"en":"a major milestone","vi":"một cột mốc lớn"}],"wordFamily":[],"synonyms":["landmark"],"antonyms":[],"tipVi":"Thường chỉ các mốc phát triển quan trọng, hay đi kèm với giới từ in.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_replacement', 'en-b2-83', 'replacement', '/rɪˈpleɪsmənt/', 'B2', 'thế thân; vật thay thế; sự thay thế; sự đổi', 'n.', 'replace (v.), replaceable (adj.), irreplaceable (adj.)', 'Đồng nghĩa: substitute', 'Thay thế vật thể thường là danh từ đếm được; quá trình thay thế thường là không đếm được.', 'The shop sent a replacement for my broken kettle.', NULL, 'Cửa hàng đã gửi một chiếc ấm đền bù cho cái ấm bị hỏng của tôi.', '{"wordId":"replacement","ukIpa":"/rɪˈpleɪsmənt/","usIpa":"/rɪˈpleɪsmənt/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A person or thing that takes another''s place.","vi":"thế thân; vật thay thế"},{"pos":"n.","en":"The act of putting someone or something in another''s place.","vi":"sự thay thế; sự đổi"}],"examples":[{"en":"The shop sent a replacement for my broken kettle.","vi":"Cửa hàng đã gửi một chiếc ấm đền bù cho cái ấm bị hỏng của tôi.","audioKind":"ex"},{"en":"The replacement of outdated buses with electric vehicles could improve air quality in densely populated cities.","vi":"Việc thay thế các xe buýt cũ kỹ bằng xe điện có thể cải thiện chất lượng không khí ở các thành phố đông dân cư.","audioKind":"ex2"}],"collocations":[{"en":"a replacement for","vi":"vật thay thế cho"},{"en":"replacement parts","vi":"phụ tùng thay thế"},{"en":"hip replacement","vi":"phẫu thuật thay khớp háng"}],"wordFamily":["replace (v.)","replaceable (adj.)","irreplaceable (adj.)"],"synonyms":["substitute"],"antonyms":[],"tipVi":"Thay thế vật thể thường là danh từ đếm được; quá trình thay thế thường là không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_anyhow', 'en-b2-83', 'anyhow', '/ˈenihaʊ/', 'B2', 'dù sao đi nữa; bất chấp; dù sao thì; nói tóm lại; một cách cẩu thả; lộn xộn', 'adv.', NULL, 'Đồng nghĩa: anyway', 'Nghĩa "dù sao" mang tính văn nói; tránh nhầm lẫn với somehow.', 'It was raining, but we went swimming anyhow.', NULL, 'Trời đang mưa nhưng chúng tôi vẫn đi bơi.', '{"wordId":"anyhow","ukIpa":"/ˈenihaʊ/","usIpa":"/ˈenihaʊ/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"Despite what has happened or been said.","vi":"dù sao đi nữa; bất chấp"},{"pos":"adv.","en":"Used to return to a topic or introduce another point.","vi":"dù sao thì; nói tóm lại"},{"pos":"adv.","en":"Without care or any particular order.","vi":"một cách cẩu thả; lộn xộn"}],"examples":[{"en":"It was raining, but we went swimming anyhow.","vi":"Trời đang mưa nhưng chúng tôi vẫn đi bơi.","audioKind":"ex"},{"en":"Although public transport improvements require substantial funding, cities should invest in them anyhow to reduce congestion.","vi":"Mặc dù việc cải thiện giao thông công cộng đòi hỏi nguồn vốn lớn, các thành phố vẫn nên đầu tư vào lĩnh vực này để giảm thiểu tình trạng ùn tắc.","audioKind":"ex2"}],"collocations":[{"en":"do it anyhow","vi":"dù thế nào vẫn làm"},{"en":"go anyhow","vi":"dù sao vẫn đi"},{"en":"leave things anyhow","vi":"vứt đồ đạc lung tung"}],"wordFamily":[],"synonyms":["anyway"],"antonyms":[],"tipVi":"Nghĩa \"dù sao\" mang tính văn nói; tránh nhầm lẫn với somehow.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_airy', 'en-b2-83', 'airy', '/ˈeri/', 'B2', 'thoáng khí; thoáng mát; rộng rãi; nhẹ nhàng; mỏng manh; thờ ơ; hời hợt; có vẻ thiếu quan tâm', 'adj.', 'air (n.), airiness (n.), airily (adv.)', 'Trái nghĩa: stuffy', 'Dùng cho phòng nghĩa là thoáng mát, không có nghĩa là làm bằng không khí.', 'The bedroom feels airy with both windows wide open.', NULL, 'Phòng ngủ có cảm giác thoáng mát khi cả hai cửa sổ đều mở rộng.', '{"wordId":"airy","ukIpa":"/ˈeəri/","usIpa":"/ˈeri/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"having plenty of fresh air and open space","vi":"thoáng khí; thoáng mát; rộng rãi"},{"pos":"adj.","en":"light and delicate in appearance or texture","vi":"nhẹ nhàng; mỏng manh"},{"pos":"adj.","en":"casual in a way that suggests little concern","vi":"thờ ơ; hời hợt; có vẻ thiếu quan tâm"}],"examples":[{"en":"The bedroom feels airy with both windows wide open.","vi":"Phòng ngủ có cảm giác thoáng mát khi cả hai cửa sổ đều mở rộng.","audioKind":"ex"},{"en":"Bright, airy classrooms can create a more comfortable learning environment, especially in schools located in warm climates.","vi":"Các lớp học sáng sủa, thoáng mát có thể tạo ra môi trường học tập thoải mái hơn, đặc biệt là ở các trường học nằm ở vùng khí hậu ấm áp.","audioKind":"ex2"}],"collocations":[{"en":"light and airy","vi":"sáng sủa và thoáng mát"},{"en":"an airy room","vi":"một căn phòng thoáng mát"},{"en":"an airy wave","vi":"một cái vẫy tay hời hợt"}],"wordFamily":["air (n.)","airiness (n.)","airily (adv.)"],"synonyms":[],"antonyms":["stuffy"],"tipVi":"Dùng cho phòng nghĩa là thoáng mát, không có nghĩa là làm bằng không khí.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ease', 'en-b2-83', 'ease', '/iːz/', 'B2', 'làm dịu; giảm bớt; làm giảm; sự dễ dàng; sự thoải mái; sự thanh thản; di chuyển từ từ và cẩn thận', 'v.', 'easy (adj.), easily (adv.), uneasy (adj.)', 'Đồng nghĩa: alleviate, relieve · Trái nghĩa: aggravate', 'With ease có nghĩa là làm gì đó rất dễ dàng; at ease có nghĩa là cảm thấy thoải mái, thư thái.', 'A warm bath helped ease the pain in my shoulders.', NULL, 'Tắm nước ấm giúp làm dịu cơn đau ở vai tôi.', '{"wordId":"ease","ukIpa":"/iːz/","usIpa":"/iːz/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To make pain, difficulty, or worry less severe.","vi":"làm dịu; giảm bớt; làm giảm"},{"pos":"n.","en":"Freedom from difficulty, effort, or worry.","vi":"sự dễ dàng; sự thoải mái; sự thanh thản"},{"pos":"v.","en":"To move something slowly and carefully into a position.","vi":"di chuyển từ từ và cẩn thận"}],"examples":[{"en":"A warm bath helped ease the pain in my shoulders.","vi":"Tắm nước ấm giúp làm dịu cơn đau ở vai tôi.","audioKind":"ex"},{"en":"Improving public transport could ease traffic congestion while making employment opportunities more accessible to suburban residents.","vi":"Cải thiện giao thông công cộng có thể làm giảm tình trạng tắc nghẽn giao thông đồng thời giúp cư dân ngoại ô tiếp cận cơ hội việc làm dễ dàng hơn.","audioKind":"ex2"}],"collocations":[{"en":"ease the pain","vi":"giảm đau"},{"en":"ease congestion","vi":"giảm ùn tắc"},{"en":"with ease","vi":"một cách dễ dàng"},{"en":"at ease","vi":"thư giãn; thoải mái"}],"wordFamily":["easy (adj.)","easily (adv.)","uneasy (adj.)"],"synonyms":["alleviate","relieve"],"antonyms":["aggravate"],"tipVi":"With ease có nghĩa là làm gì đó rất dễ dàng; at ease có nghĩa là cảm thấy thoải mái, thư thái.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_barrel', 'en-b2-83', 'barrel', '/ˈbærəl/', 'B2', 'thùng tròn lớn; một thùng; nòng súng; nòng pháo; phóng nhanh; lao vun vút', 'n.', NULL, 'Đồng nghĩa: cask', 'Dạng số nhiều là barrels; một thùng dầu dùng là a barrel of oil.', 'We collect rainwater in a wooden barrel behind the shed.', NULL, 'Chúng tôi hứng nước mưa bằng một chiếc thùng gỗ ở phía sau nhà kho.', '{"wordId":"barrel","ukIpa":"/ˈbærəl/","usIpa":"/ˈbærəl/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A large round container with flat ends, or its contents.","vi":"thùng tròn lớn; một thùng"},{"pos":"n.","en":"The tube of a gun through which a bullet travels.","vi":"nòng súng; nòng pháo"},{"pos":"v.","en":"To move very fast, often with little control.","vi":"phóng nhanh; lao vun vút"}],"examples":[{"en":"We collect rainwater in a wooden barrel behind the shed.","vi":"Chúng tôi hứng nước mưa bằng một chiếc thùng gỗ ở phía sau nhà kho.","audioKind":"ex"},{"en":"The price of a barrel of oil can influence transport costs throughout the global economy.","vi":"Giá của một thùng dầu có thể ảnh hưởng đến chi phí vận chuyển trong toàn bộ nền kinh tế toàn cầu.","audioKind":"ex2"}],"collocations":[{"en":"wooden barrel","vi":"thùng gỗ"},{"en":"a barrel of oil","vi":"một thùng dầu"},{"en":"gun barrel","vi":"nòng súng"},{"en":"barrel down the road","vi":"lao vun vút dọc theo con đường"}],"wordFamily":[],"synonyms":["cask"],"antonyms":[],"tipVi":"Dạng số nhiều là barrels; một thùng dầu dùng là a barrel of oil.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cane', 'en-b2-83', 'cane', '/keɪn/', 'B2', 'gậy đi bộ; gậy; mây; tre đan; cây mía', 'n.', NULL, 'Đồng nghĩa: walking stick', 'Nghĩa "gậy" là danh từ đếm được; nghĩa "vật liệu mây" hoặc "cây mía" thường là không đếm được.', 'My grandfather uses a cane on uneven paths.', NULL, 'Ông tôi dùng gậy đi bộ khi đi trên những con đường gập ghềnh.', '{"wordId":"cane","ukIpa":"/keɪn/","usIpa":"/keɪn/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"a stick used to support someone while walking","vi":"gậy đi bộ; gậy"},{"pos":"n.","en":"flexible plant stems used for making furniture and baskets","vi":"mây; tre đan"},{"pos":"n.","en":"a tall tropical plant grown for its sweet stems","vi":"cây mía"}],"examples":[{"en":"My grandfather uses a cane on uneven paths.","vi":"Ông tôi dùng gậy đi bộ khi đi trên những con đường gập ghềnh.","audioKind":"ex"},{"en":"Growing cane for sugar can provide rural employment but requires substantial water resources.","vi":"Việc trồng mía để làm đường có thể tạo việc làm ở nông thôn nhưng đòi hỏi nguồn nước lớn.","audioKind":"ex2"}],"collocations":[{"en":"walk with a cane","vi":"đi chống gậy"},{"en":"cane furniture","vi":"đồ nội thất bằng mây"},{"en":"sugar cane","vi":"cây mía đường"}],"wordFamily":[],"synonyms":["walking stick"],"antonyms":[],"tipVi":"Nghĩa \"gậy\" là danh từ đếm được; nghĩa \"vật liệu mây\" hoặc \"cây mía\" thường là không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_severely', 'en-b2-83', 'severely', '/səˈvɪrli/', 'B2', 'trầm trọng; dữ dội; cực kỳ; nghiêm khắc; khắt khe', 'adv.', 'severe (adj.), severity (n.)', 'Đồng nghĩa: seriously, harshly · Trái nghĩa: mildly', 'Có thể chỉ mức độ nghiêm trọng hoặc thái độ khắt khe, cần xét theo ngữ cảnh kết hợp từ.', 'The storm severely damaged the roof of our house.', NULL, 'Cơn bão đã làm hư hỏng nặng phần mái nhà của chúng tôi.', '{"wordId":"severely","ukIpa":"/sɪˈvɪəli/","usIpa":"/səˈvɪrli/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"to a very serious or extreme degree","vi":"trầm trọng; dữ dội; cực kỳ"},{"pos":"adv.","en":"in a strict or harsh manner","vi":"nghiêm khắc; khắt khe"}],"examples":[{"en":"The storm severely damaged the roof of our house.","vi":"Cơn bão đã làm hư hỏng nặng phần mái nhà của chúng tôi.","audioKind":"ex"},{"en":"Limited access to clean water can severely affect public health and restrict economic development in rural communities.","vi":"Việc tiếp cận hạn chế với nước sạch có thể ảnh hưởng nghiêm trọng đến sức khỏe công cộng và kìm hãm sự phát triển kinh tế ở các cộng đồng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"severely damaged","vi":"bị hư hại nặng"},{"en":"severely affected","vi":"bị ảnh hưởng nghiêm trọng"},{"en":"severely limited","vi":"bị hạn chế nghiêm ngặt"},{"en":"criticise severely","vi":"chỉ trích gay gắt"}],"wordFamily":["severe (adj.)","severity (n.)"],"synonyms":["seriously","harshly"],"antonyms":["mildly"],"tipVi":"Có thể chỉ mức độ nghiêm trọng hoặc thái độ khắt khe, cần xét theo ngữ cảnh kết hợp từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gulp', 'en-b2-83', 'gulp', '/ɡʌlp/', 'B2', 'uống ừng ực; nuốt vội vàng; nuốt nước bọt vì căng thẳng hoặc sợ hãi; một ngụm lớn; cái nuốt lớn', 'v.', NULL, NULL, 'Gulp down nhấn mạnh việc nuốt nhanh và nhiều; sip chỉ việc nhấm nháp từng ngụm nhỏ.', 'After cycling home, I gulped down a glass of water.', NULL, 'Sau khi đạp xe về nhà, tôi đã tu ừng ực hết một cốc nước.', '{"wordId":"gulp","ukIpa":"/ɡʌlp/","usIpa":"/ɡʌlp/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To swallow food or drink quickly in large amounts.","vi":"uống ừng ực; nuốt vội vàng"},{"pos":"v.","en":"To swallow because you are nervous or frightened.","vi":"nuốt nước bọt vì căng thẳng hoặc sợ hãi"},{"pos":"n.","en":"An amount swallowed in one quick movement.","vi":"một ngụm lớn; cái nuốt lớn"}],"examples":[{"en":"After cycling home, I gulped down a glass of water.","vi":"Sau khi đạp xe về nhà, tôi đã tu ừng ực hết một cốc nước.","audioKind":"ex"},{"en":"Workers who gulp down meals during short breaks may find it harder to maintain healthy eating habits.","vi":"Những người ăn uống vội vã trong các giờ nghỉ ngắn có thể khó duy trì được thói quen ăn uống lành mạnh hơn.","audioKind":"ex2"}],"collocations":[{"en":"gulp down","vi":"nuốt chửng; uống ừng ực"},{"en":"take a gulp","vi":"uống một ngụm lớn"},{"en":"gulp nervously","vi":"nuốt nước bọt một cách hồi hộp"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Gulp down nhấn mạnh việc nuốt nhanh và nhiều; sip chỉ việc nhấm nháp từng ngụm nhỏ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_elastic', 'en-b2-83', 'elastic', '/ɪˈlæstɪk/', 'B2', 'có tính đàn hồi; co giãn; thun; dây thun; vật liệu đàn hồi; linh hoạt; dễ thay đổi', 'adj.', 'elasticity (n.), inelastic (adj.)', 'Đồng nghĩa: stretchy, flexible · Trái nghĩa: inelastic, rigid', 'Là danh từ chỉ vật liệu thường không đếm được; elastic band chỉ dây thun.', 'These elastic sleeves stretch easily over my thick gloves.', NULL, 'Những chiếc ống tay áo co giãn này dễ dàng kéo căng qua đôi găng tay dày của tôi.', '{"wordId":"elastic","ukIpa":"/ɪˈlæstɪk/","usIpa":"/ɪˈlæstɪk/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"able to stretch and return to its original shape","vi":"có tính đàn hồi; co giãn"},{"pos":"n.","en":"stretchy material used to hold clothing or objects in place","vi":"thun; dây thun; vật liệu đàn hồi"},{"pos":"adj.","en":"able to change or adapt easily","vi":"linh hoạt; dễ thay đổi"}],"examples":[{"en":"These elastic sleeves stretch easily over my thick gloves.","vi":"Những chiếc ống tay áo co giãn này dễ dàng kéo căng qua đôi găng tay dày của tôi.","audioKind":"ex"},{"en":"Manufacturers use elastic materials in sports clothing to improve comfort and allow greater freedom of movement.","vi":"Các nhà sản xuất sử dụng vật liệu đàn hồi trong trang phục thể thao nhằm nâng cao sự thoải mái và cho phép tự do vận động hơn.","audioKind":"ex2"}],"collocations":[{"en":"elastic material","vi":"vật liệu đàn hồi"},{"en":"an elastic band","vi":"dây thun"},{"en":"elastic demand","vi":"nhu cầu co giãn"}],"wordFamily":["elasticity (n.)","inelastic (adj.)"],"synonyms":["stretchy","flexible"],"antonyms":["inelastic","rigid"],"tipVi":"Là danh từ chỉ vật liệu thường không đếm được; elastic band chỉ dây thun.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clockwise', 'en-b2-83', 'clockwise', '/ˈklɑːkwaɪz/', 'B2', 'theo chiều kim đồng hồ; theo hướng chiều kim đồng hồ', 'adv.', 'anticlockwise (adv.), counterclockwise (adv.)', 'Trái nghĩa: anticlockwise, counterclockwise', 'Từ trái nghĩa tiếng Anh Anh thường dùng anticlockwise, tiếng Anh Mỹ thường dùng counterclockwise.', 'Turn the lid clockwise until the jar is sealed.', NULL, 'Xoay nắp theo chiều kim đồng hồ cho đến khi lọ được đậy kín.', '{"wordId":"clockwise","ukIpa":"/ˈklɒkwaɪz/","usIpa":"/ˈklɑːkwaɪz/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"in the same direction as the hands of a clock","vi":"theo chiều kim đồng hồ"},{"pos":"adj.","en":"moving in the same direction as clock hands","vi":"theo hướng chiều kim đồng hồ"}],"examples":[{"en":"Turn the lid clockwise until the jar is sealed.","vi":"Xoay nắp theo chiều kim đồng hồ cho đến khi lọ được đậy kín.","audioKind":"ex"},{"en":"Visitors move clockwise around the exhibition hall, allowing the museum to manage crowds and prevent congestion.","vi":"Khách tham quan di chuyển theo chiều kim đồng hồ quanh phòng triển lãm, giúp bảo tàng quản lý lượng khách và tránh tình trạng ùn tắc.","audioKind":"ex2"}],"collocations":[{"en":"turn clockwise","vi":"xoay theo chiều kim đồng hồ"},{"en":"rotate clockwise","vi":"quay theo chiều kim đồng hồ"},{"en":"a clockwise direction","vi":"hướng theo chiều kim đồng hồ"}],"wordFamily":["anticlockwise (adv.)","counterclockwise (adv.)"],"synonyms":[],"antonyms":["anticlockwise","counterclockwise"],"tipVi":"Từ trái nghĩa tiếng Anh Anh thường dùng anticlockwise, tiếng Anh Mỹ thường dùng counterclockwise.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_practically', 'en-b2-83', 'practically', '/ˈpræktɪkli/', 'B2', 'hầu như; gần như hoàn toàn; trên thực tế; theo phương diện thực tiễn', 'adv.', 'practical (adj.), practicality (n.), impractical (adj.)', 'Đồng nghĩa: almost, nearly', 'Thường biểu thị ý nghĩa "hầu như/gần như", không phải lúc nào cũng mang nghĩa "một cách thực tế".', 'The fridge was practically empty when we got home.', NULL, 'Tủ lạnh hầu như trống rỗng khi chúng tôi về đến nhà.', '{"wordId":"practically","ukIpa":"/ˈpræktɪkli/","usIpa":"/ˈpræktɪkli/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"Almost completely, or very nearly.","vi":"hầu như; gần như hoàn toàn"},{"pos":"adv.","en":"In a way concerned with real situations rather than theory.","vi":"trên thực tế; theo phương diện thực tiễn"}],"examples":[{"en":"The fridge was practically empty when we got home.","vi":"Tủ lạnh hầu như trống rỗng khi chúng tôi về đến nhà.","audioKind":"ex"},{"en":"Without reliable internet access, participating in online education is practically impossible for students in remote areas.","vi":"Không có kết nối internet ổn định, việc tham gia giáo dục trực tuyến là điều gần như không thể đối với học sinh ở các vùng sâu vùng xa.","audioKind":"ex2"}],"collocations":[{"en":"practically impossible","vi":"gần như bất khả thi"},{"en":"practically everyone","vi":"hầu như tất cả mọi người"},{"en":"practically speaking","vi":"trên thực tế mà nói"}],"wordFamily":["practical (adj.)","practicality (n.)","impractical (adj.)"],"synonyms":["almost","nearly"],"antonyms":[],"tipVi":"Thường biểu thị ý nghĩa \"hầu như/gần như\", không phải lúc nào cũng mang nghĩa \"một cách thực tế\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stab', 'en-b2-83', 'stab', '/stæb/', 'B2', 'đâm; chọc; thọc; cơn đau nhói đột ngột; cảm xúc mãnh liệt bất chợt; sự thử sức; nỗ lực làm gì', 'v.', 'stabbing (adj.)', NULL, 'Cấu trúc have a stab at doing diễn tả việc thử làm điều gì đó, mang tính văn phong giao tiếp thông thường.', 'She stabbed a potato with her fork to test it.', NULL, 'Cô ấy dùng nĩa xiên vào củ khoai tây để kiểm tra xem đã chín chưa.', '{"wordId":"stab","ukIpa":"/stæb/","usIpa":"/stæb/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"push a sharp object into something or someone","vi":"đâm; chọc; thọc"},{"pos":"n.","en":"a sudden sharp pain or strong feeling","vi":"cơn đau nhói đột ngột; cảm xúc mãnh liệt bất chợt"},{"pos":"n.","en":"an attempt to do something","vi":"sự thử sức; nỗ lực làm gì"}],"examples":[{"en":"She stabbed a potato with her fork to test it.","vi":"Cô ấy dùng nĩa xiên vào củ khoai tây để kiểm tra xem đã chín chưa.","audioKind":"ex"},{"en":"Many graduates feel a stab of anxiety when considering their employment prospects in an uncertain economy.","vi":"Nhiều sinh viên cảm thấy nhói lên một nỗi lo âu khi nghĩ đến triển vọng việc làm của họ trong bối cảnh nền kinh tế bất định.","audioKind":"ex2"}],"collocations":[{"en":"stab at something","vi":"đâm vào vật gì"},{"en":"a stab of pain","vi":"cơn đau nhói"},{"en":"have a stab at","vi":"thử làm gì"}],"wordFamily":["stabbing (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc have a stab at doing diễn tả việc thử làm điều gì đó, mang tính văn phong giao tiếp thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ditch', 'en-b2-83', 'ditch', '/dɪtʃ/', 'B2', 'mương; rãnh thoát nước; bỏ; vứt bỏ; từ bỏ', 'n.', NULL, NULL, 'Khi dùng làm động từ mang nghĩa vứt bỏ hoặc từ bỏ, từ này thiên về văn phong khẩu ngữ.', 'Rainwater flowed through the ditch beside our vegetable garden.', NULL, 'Nước mưa chảy qua con mương bên cạnh vườn rau của chúng tôi.', '{"wordId":"ditch","ukIpa":"/dɪtʃ/","usIpa":"/dɪtʃ/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A long narrow channel dug in the ground, often for drainage.","vi":"mương; rãnh thoát nước"},{"pos":"v.","en":"To get rid of someone or something no longer wanted.","vi":"bỏ; vứt bỏ; từ bỏ"}],"examples":[{"en":"Rainwater flowed through the ditch beside our vegetable garden.","vi":"Nước mưa chảy qua con mương bên cạnh vườn rau của chúng tôi.","audioKind":"ex"},{"en":"Cities should ditch outdated planning policies that encourage car dependence and invest instead in reliable public transport.","vi":"Các thành phố nên từ bỏ các chính sách quy hoạch lỗi thời vốn khuyến khích sự phụ thuộc vào ô tô và thay vào đó đầu tư vào giao thông công cộng đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"a drainage ditch","vi":"mương thoát nước"},{"en":"dig a ditch","vi":"đào mương"},{"en":"ditch a plan","vi":"từ bỏ một kế hoạch"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi dùng làm động từ mang nghĩa vứt bỏ hoặc từ bỏ, từ này thiên về văn phong khẩu ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pastry', 'en-b2-83', 'pastry', '/ˈpeɪstri/', 'B2', 'bột nhào làm bánh; vỏ bánh nướng; bánh ngọt nướng (thường có nhân ngọt)', 'n.', NULL, NULL, 'Khi chỉ khối bột làm vỏ bánh thì không đếm được; khi chỉ chiếc bánh ngọt cụ thể thì đếm được.', 'Roll the pastry thinly before covering the apple filling.', NULL, 'Cán mỏng lớp bột bánh trước khi phủ lên phần nhân táo.', '{"wordId":"pastry","ukIpa":"/ˈpeɪstri/","usIpa":"/ˈpeɪstri/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"Dough made with flour and fat for pies and similar foods.","vi":"bột nhào làm bánh; vỏ bánh nướng"},{"pos":"n.","en":"A small baked food made from pastry, often with sweet filling.","vi":"bánh ngọt nướng (thường có nhân ngọt)"}],"examples":[{"en":"Roll the pastry thinly before covering the apple filling.","vi":"Cán mỏng lớp bột bánh trước khi phủ lên phần nhân táo.","audioKind":"ex"},{"en":"Culinary courses teach students to prepare pastry while developing practical skills for careers in hospitality.","vi":"Các khóa học nấu ăn dạy học sinh cách làm bột vỏ bánh đồng thời phát triển các kỹ năng thực tế cho sự nghiệp trong ngành khách sạn nhà hàng.","audioKind":"ex2"}],"collocations":[{"en":"puff pastry","vi":"bột ngàn lớp"},{"en":"shortcrust pastry","vi":"vỏ bánh nướng giòn"},{"en":"roll out pastry","vi":"cán bột bánh ngọt"},{"en":"a pastry chef","vi":"thợ làm bánh ngọt"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ khối bột làm vỏ bánh thì không đếm được; khi chỉ chiếc bánh ngọt cụ thể thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shorten', 'en-b2-83', 'shorten', '/ˈʃɔːrtən/', 'B2', 'làm ngắn lại; rút ngắn; thu ngắn', 'v.', 'short (adj.), shortness (n.)', 'Đồng nghĩa: reduce, trim · Trái nghĩa: lengthen, extend', 'Có thể dùng cả ngoại động từ và nội động từ: shorten the days; days shorten.', 'Could you shorten these trousers before the wedding?', NULL, 'Bạn có thể cắt ngắn chiếc quần này trước lễ cưới không?', '{"wordId":"shorten","ukIpa":"/ˈʃɔːtən/","usIpa":"/ˈʃɔːrtən/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To make or become shorter in length or duration.","vi":"làm ngắn lại; rút ngắn; thu ngắn"}],"examples":[{"en":"Could you shorten these trousers before the wedding?","vi":"Bạn có thể cắt ngắn chiếc quần này trước lễ cưới không?","audioKind":"ex"},{"en":"Improved public transport could shorten commuting times and reduce dependence on private cars in cities.","vi":"Hệ thống giao thông công cộng được cải thiện có thể rút ngắn thời gian di chuyển và giảm sự phụ thuộc vào xe cá nhân tại các thành phố.","audioKind":"ex2"}],"collocations":[{"en":"shorten a journey","vi":"rút ngắn hành trình"},{"en":"shorten a sentence","vi":"rút gọn câu"},{"en":"shorten a skirt","vi":"cắt ngắn chân váy"}],"wordFamily":["short (adj.)","shortness (n.)"],"synonyms":["reduce","trim"],"antonyms":["lengthen","extend"],"tipVi":"Có thể dùng cả ngoại động từ và nội động từ: shorten the days; days shorten.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grease', 'en-b2-83', 'grease', '/ɡriːs/', 'B2', 'dầu mỡ; mỡ bôi trơn; bôi mỡ; tra dầu', 'n.', 'greasy (adj.)', NULL, 'Danh từ phát âm là /ɡriːs/; động từ thường cũng phát âm là /ɡriːz/.', 'There was grease on my hands after fixing the bicycle.', NULL, 'Tay tôi dính đầy dầu mỡ sau khi sửa chiếc xe đạp.', '{"wordId":"grease","ukIpa":"/ɡriːs/","usIpa":"/ɡriːs/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"thick oily material used for lubrication or produced during cooking","vi":"dầu mỡ; mỡ bôi trơn"},{"pos":"v.","en":"to spread oil or fat over a surface","vi":"bôi mỡ; tra dầu"}],"examples":[{"en":"There was grease on my hands after fixing the bicycle.","vi":"Tay tôi dính đầy dầu mỡ sau khi sửa chiếc xe đạp.","audioKind":"ex"},{"en":"Restaurants should prevent cooking grease from entering drains because it can block pipes and increase maintenance costs.","vi":"Các nhà hàng nên ngăn chặn dầu mỡ nấu ăn lọt vào hệ thống thoát nước vì chúng có thể làm tắc ống dẫn và tăng chi phí bảo trì.","audioKind":"ex2"}],"collocations":[{"en":"cooking grease","vi":"dầu mỡ nấu ăn"},{"en":"remove grease","vi":"tẩy sạch dầu mỡ"},{"en":"grease a baking tin","vi":"quét bơ chống dính khuôn bánh"}],"wordFamily":["greasy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ phát âm là /ɡriːs/; động từ thường cũng phát âm là /ɡriːz/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_greatly', 'en-b2-83', 'greatly', '/ˈɡreɪtli/', 'B2', 'đáng kể; rất nhiều; vô cùng', 'adv.', 'great (adj.), greatness (n.)', 'Đồng nghĩa: considerably, significantly, enormously · Trái nghĩa: slightly', 'Thường bổ nghĩa cho động từ, như greatly improve; không dùng dạng greatly good.', 'Your clear directions greatly helped us find the cottage.', NULL, 'Chỉ dẫn rõ ràng của bạn đã giúp chúng tôi tìm được ngôi nhà nhỏ rất nhiều.', '{"wordId":"greatly","ukIpa":"/ˈɡreɪtli/","usIpa":"/ˈɡreɪtli/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"To a large degree or by a large amount.","vi":"đáng kể; rất nhiều; vô cùng"}],"examples":[{"en":"Your clear directions greatly helped us find the cottage.","vi":"Chỉ dẫn rõ ràng của bạn đã giúp chúng tôi tìm được ngôi nhà nhỏ rất nhiều.","audioKind":"ex"},{"en":"Access to affordable childcare can greatly improve parents'' ability to remain in employment and pursue further education.","vi":"Khả năng tiếp cận dịch vụ chăm sóc trẻ em giá cả phải chăng có thể cải thiện đáng kể khả năng tiếp tục làm việc và theo học các bậc học cao hơn của các bậc phụ huynh.","audioKind":"ex2"}],"collocations":[{"en":"greatly improve","vi":"cải thiện đáng kể"},{"en":"greatly reduce","vi":"giảm đáng kể"},{"en":"greatly appreciate","vi":"vô cùng kích động hoặc biết ơn"},{"en":"vary greatly","vi":"thay đổi rất lớn"}],"wordFamily":["great (adj.)","greatness (n.)"],"synonyms":["considerably","significantly","enormously"],"antonyms":["slightly"],"tipVi":"Thường bổ nghĩa cho động từ, như greatly improve; không dùng dạng greatly good.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vivid', 'en-b2-83', 'vivid', '/ˈvɪvɪd/', 'B2', 'sặc sỡ; tươi sáng; sống động; rõ nét', 'adj.', 'vividly (adv.), vividness (n.)', 'Trái nghĩa: dull', 'Có thể dùng để mô tả màu sắc rực rỡ, hoặc dùng cho ký ức hay sự miêu tả rõ ràng, sống động.', 'Her vivid orange scarf stood out against the snow.', NULL, 'Chiếc khăn quàng cổ màu cam rực rỡ của cô ấy nổi bật giữa nền tuyết trắng.', '{"wordId":"vivid","ukIpa":"/ˈvɪvɪd/","usIpa":"/ˈvɪvɪd/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"having strong, bright colours","vi":"sặc sỡ; tươi sáng"},{"pos":"adj.","en":"producing clear, detailed images in the mind","vi":"sống động; rõ nét"}],"examples":[{"en":"Her vivid orange scarf stood out against the snow.","vi":"Chiếc khăn quàng cổ màu cam rực rỡ của cô ấy nổi bật giữa nền tuyết trắng.","audioKind":"ex"},{"en":"Personal accounts provide vivid descriptions of historical events, helping students understand their human impact.","vi":"Những lời kể của người trong cuộc cung cấp các mô tả sinh động về các sự kiện lịch sử, giúp học sinh hiểu được tác động của chúng đối với con người.","audioKind":"ex2"}],"collocations":[{"en":"vivid colours","vi":"màu sắc tươi sáng"},{"en":"a vivid memory","vi":"ký ức rõ nét"},{"en":"a vivid description","vi":"mô tả sinh động"},{"en":"a vivid imagination","vi":"trí tưởng tượng phong phú"}],"wordFamily":["vividly (adv.)","vividness (n.)"],"synonyms":[],"antonyms":["dull"],"tipVi":"Có thể dùng để mô tả màu sắc rực rỡ, hoặc dùng cho ký ức hay sự miêu tả rõ ràng, sống động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thickness', 'en-b2-83', 'thickness', '/ˈθɪknəs/', 'B2', 'độ dày; bề dày; độ đặc; độ quánh (của chất lỏng)', 'n.', 'thick (adj.), thicken (v.), thickly (adv.)', 'Trái nghĩa: thinness', 'Khi chỉ số đo độ dày cụ thể, thường dùng cụm a thickness of kèm theo kích thước.', 'Check the thickness of the wood before buying it.', NULL, 'Hãy kiểm tra độ dày của tấm gỗ trước khi mua nó.', '{"wordId":"thickness","ukIpa":"/ˈθɪknəs/","usIpa":"/ˈθɪknəs/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"The distance between two opposite surfaces of something.","vi":"độ dày; bề dày"},{"pos":"n.","en":"The degree to which a liquid is thick.","vi":"độ đặc; độ quánh (của chất lỏng)"}],"examples":[{"en":"Check the thickness of the wood before buying it.","vi":"Hãy kiểm tra độ dày của tấm gỗ trước khi mua nó.","audioKind":"ex"},{"en":"The thickness of insulation affects how much energy a building requires for heating during winter.","vi":"Độ dày của lớp cách nhiệt ảnh hưởng đến lượng năng lượng mà một tòa nhà cần dùng để sưởi ấm trong mùa đông.","audioKind":"ex2"}],"collocations":[{"en":"wall thickness","vi":"độ dày tường"},{"en":"a thickness of","vi":"độ dày là"},{"en":"uniform thickness","vi":"độ dày đồng đều"}],"wordFamily":["thick (adj.)","thicken (v.)","thickly (adv.)"],"synonyms":[],"antonyms":["thinness"],"tipVi":"Khi chỉ số đo độ dày cụ thể, thường dùng cụm a thickness of kèm theo kích thước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_readily', 'en-b2-83', 'readily', '/ˈredɪli/', 'B2', 'một cách dễ dàng; không khó khăn; sẵn lòng; vui vẻ', 'adv.', 'ready (adj.), readiness (n.)', 'Đồng nghĩa: easily, willingly · Trái nghĩa: reluctantly', '"readily available" có nghĩa là dễ dàng có được, chứ không phải "sẵn lòng cung cấp".', 'My sister readily agreed to water the plants.', NULL, 'Chị gái tôi đã vui vẻ đồng ý tưới cây.', '{"wordId":"readily","ukIpa":"/ˈredɪli/","usIpa":"/ˈredɪli/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"Easily and without difficulty or delay.","vi":"một cách dễ dàng; không khó khăn"},{"pos":"adv.","en":"Willingly and without hesitation.","vi":"sẵn lòng; vui vẻ"}],"examples":[{"en":"My sister readily agreed to water the plants.","vi":"Chị gái tôi đã vui vẻ đồng ý tưới cây.","audioKind":"ex"},{"en":"Reliable health information should be readily available to all citizens, regardless of their income or location.","vi":"Thông tin y tế đáng tin cậy cần được cung cấp một cách dễ dàng cho mọi công dân, bất kể thu nhập hay nơi cư trú.","audioKind":"ex2"}],"collocations":[{"en":"readily available","vi":"có sẵn một cách dễ dàng"},{"en":"readily accessible","vi":"dễ tiếp cận"},{"en":"readily agree","vi":"vui vẻ đồng ý"},{"en":"readily admit","vi":"thẳng thắn thừa nhận"}],"wordFamily":["ready (adj.)","readiness (n.)"],"synonyms":["easily","willingly"],"antonyms":["reluctantly"],"tipVi":"\"readily available\" có nghĩa là dễ dàng có được, chứ không phải \"sẵn lòng cung cấp\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pickle', 'en-b2-83', 'pickle', '/ˈpɪkəl/', 'B2', 'đồ muối chua; dưa chua; ngâm giấm; muối chua', 'n.', 'pickled (adj.), pickling (n.)', NULL, 'Trong tiếng Anh Mỹ, "a pickle" thường chỉ quả dưa chuột muối chua.', 'She added a crunchy pickle to her sandwich.', NULL, 'Cô ấy kẹp thêm một lát dưa chuột muối giòn rụm vào chiếc bánh mì kẹp của mình.', '{"wordId":"pickle","ukIpa":"/ˈpɪkəl/","usIpa":"/ˈpɪkəl/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A vegetable preserved in vinegar or salty water.","vi":"đồ muối chua; dưa chua"},{"pos":"v.","en":"To preserve food in vinegar or salty water.","vi":"ngâm giấm; muối chua"}],"examples":[{"en":"She added a crunchy pickle to her sandwich.","vi":"Cô ấy kẹp thêm một lát dưa chuột muối giòn rụm vào chiếc bánh mì kẹp của mình.","audioKind":"ex"},{"en":"Many communities pickle seasonal vegetables to extend their shelf life and reduce household food waste.","vi":"Nhiều cộng đồng tiến hành muối chua các loại rau theo mùa để kéo dài thời gian bảo quản và giảm lãng phí thực phẩm trong hộ gia đình.","audioKind":"ex2"}],"collocations":[{"en":"pickled vegetables","vi":"rau củ muối chua"},{"en":"a jar of pickles","vi":"một hũ dưa chua"},{"en":"in a pickle","vi":"rơi vào tình thế khó khăn"}],"wordFamily":["pickled (adj.)","pickling (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh Mỹ, \"a pickle\" thường chỉ quả dưa chuột muối chua.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_drag', 'en-b2-83', 'drag', '/dræɡ/', 'B2', 'kéo lê; lôi đi; trôi qua chậm chạp; kéo dài lê thê; sự cản trở; lực cản; gánh nặng', 'v.', NULL, 'Đồng nghĩa: pull', 'Dạng quá khứ của "drag" là "dragged"; cụm từ "drag on" có nghĩa là kéo dài lê thê.', 'We dragged the heavy rug across the floor.', NULL, 'Chúng tôi đã kéo lê tấm thảm nặng đi ngang qua căn phòng.', '{"wordId":"drag","ukIpa":"/dræɡ/","usIpa":"/dræɡ/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To pull something along a surface, often with effort.","vi":"kéo lê; lôi đi"},{"pos":"v.","en":"To pass or progress so slowly that it feels boring.","vi":"trôi qua chậm chạp; kéo dài lê thê"},{"pos":"n.","en":"A force or influence that slows movement or progress.","vi":"sự cản trở; lực cản; gánh nặng"}],"examples":[{"en":"We dragged the heavy rug across the floor.","vi":"Chúng tôi đã kéo lê tấm thảm nặng đi ngang qua căn phòng.","audioKind":"ex"},{"en":"Complicated approval procedures can drag on for months, delaying essential improvements to public transport.","vi":"Các thủ tục phê duyệt phức tạp có thể kéo dài âm ỉ trong nhiều tháng, làm chậm trễ các cải thiện thiết yếu đối với hệ thống giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"drag a chair","vi":"kéo lê cái ghế"},{"en":"drag on","vi":"kéo dài lê thê"},{"en":"drag and drop","vi":"kéo và thả"},{"en":"a drag on growth","vi":"yếu tố cản trở đà tăng trưởng"}],"wordFamily":[],"synonyms":["pull"],"antonyms":[],"tipVi":"Dạng quá khứ của \"drag\" là \"dragged\"; cụm từ \"drag on\" có nghĩa là kéo dài lê thê.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_83_1', 'en-b2-83', 'Cách dùng “stab” (v.) — đâm; chọc; thọc', 'stab at something  ·  a stab of pain  ·  have a stab at', 'Cấu trúc have a stab at doing diễn tả việc thử làm điều gì đó, mang tính văn phong giao tiếp thông thường.', 'Họ từ (Word Family): stabbing (adj.)', '[{"hanzi":"She stabbed a potato with her fork to test it.","pinyin":"","meaning":"Cô ấy dùng nĩa xiên vào củ khoai tây để kiểm tra xem đã chín chưa."},{"hanzi":"Many graduates feel a stab of anxiety when considering their employment prospects in an uncertain economy.","pinyin":"","meaning":"Nhiều sinh viên cảm thấy nhói lên một nỗi lo âu khi nghĩ đến triển vọng việc làm của họ trong bối cảnh nền kinh tế bất định."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_83_2', 'en-b2-83', 'Cách dùng “clockwise” (adv.) — theo chiều kim đồng hồ', 'turn clockwise  ·  rotate clockwise  ·  a clockwise direction', 'Từ trái nghĩa tiếng Anh Anh thường dùng anticlockwise, tiếng Anh Mỹ thường dùng counterclockwise.', 'Họ từ (Word Family): anticlockwise (adv.), counterclockwise (adv.) | Trái nghĩa: anticlockwise, counterclockwise', '[{"hanzi":"Turn the lid clockwise until the jar is sealed.","pinyin":"","meaning":"Xoay nắp theo chiều kim đồng hồ cho đến khi lọ được đậy kín."},{"hanzi":"Visitors move clockwise around the exhibition hall, allowing the museum to manage crowds and prevent congestion.","pinyin":"","meaning":"Khách tham quan di chuyển theo chiều kim đồng hồ quanh phòng triển lãm, giúp bảo tàng quản lý lượng khách và tránh tình trạng ùn tắc."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_83_3', 'en-b2-83', 'Cách dùng “practically” (adv.) — hầu như; gần như hoàn toàn', 'practically impossible  ·  practically everyone  ·  practically speaking', 'Thường biểu thị ý nghĩa "hầu như/gần như", không phải lúc nào cũng mang nghĩa "một cách thực tế".', 'Họ từ (Word Family): practical (adj.), practicality (n.), impractical (adj.) | Đồng nghĩa: almost, nearly', '[{"hanzi":"The fridge was practically empty when we got home.","pinyin":"","meaning":"Tủ lạnh hầu như trống rỗng khi chúng tôi về đến nhà."},{"hanzi":"Without reliable internet access, participating in online education is practically impossible for students in remote areas.","pinyin":"","meaning":"Không có kết nối internet ổn định, việc tham gia giáo dục trực tuyến là điều gần như không thể đối với học sinh ở các vùng sâu vùng xa."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_83_4', 'en-b2-83', 'Cách dùng “ease” (v.) — làm dịu; giảm bớt; làm giảm', 'ease the pain  ·  ease congestion  ·  with ease', 'With ease có nghĩa là làm gì đó rất dễ dàng; at ease có nghĩa là cảm thấy thoải mái, thư thái.', 'Họ từ (Word Family): easy (adj.), easily (adv.), uneasy (adj.) | Đồng nghĩa: alleviate, relieve · Trái nghĩa: aggravate', '[{"hanzi":"A warm bath helped ease the pain in my shoulders.","pinyin":"","meaning":"Tắm nước ấm giúp làm dịu cơn đau ở vai tôi."},{"hanzi":"Improving public transport could ease traffic congestion while making employment opportunities more accessible to suburban residents.","pinyin":"","meaning":"Cải thiện giao thông công cộng có thể làm giảm tình trạng tắc nghẽn giao thông đồng thời giúp cư dân ngoại ô tiếp cận cơ hội việc làm dễ dàng hơn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_83_1', 'en-b2-83', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
