INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_83_1_8', 'ten_b2_83_1', 'ease', 'A warm bath helped ease the pain in my shoulders.', 'A warm bath helped ease the pain in my shoulders.', '/iːz/', 'Tắm nước ấm giúp làm dịu cơn đau ở vai tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_83_1_1', 'en-b2-83', 'ten_b2_83_1', 'listening', 'listening', 'My initial excitement faded when I saw the price.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Sau khi đạp xe về nhà, tôi đã tu ừng ực hết một cốc nước.","Phòng ngủ có cảm giác thoáng mát khi cả hai cửa sổ đều mở rộng.","Sự hào hứng ban đầu của tôi đã vụt tắt khi nhìn thấy giá tiền.","Tay tôi dính đầy dầu mỡ sau khi sửa chiếc xe đạp."]'::jsonb, 2, 'My initial excitement faded when I saw the price. → Sự hào hứng ban đầu của tôi đã vụt tắt khi nhìn thấy giá tiền.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_83_1_2', 'en-b2-83', 'ten_b2_83_1', 'listening', 'listening', 'A peculiar smell came from the cupboard under the stairs.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Sau khi đạp xe về nhà, tôi đã tu ừng ực hết một cốc nước.","Một mùi kỳ lạ phát ra từ chiếc tủ dưới cầu thang.","Sự hào hứng ban đầu của tôi đã vụt tắt khi nhìn thấy giá tiền.","Tay tôi dính đầy dầu mỡ sau khi sửa chiếc xe đạp."]'::jsonb, 1, 'A peculiar smell came from the cupboard under the stairs. → Một mùi kỳ lạ phát ra từ chiếc tủ dưới cầu thang.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_83_1_3', 'en-b2-83', 'ten_b2_83_1', 'listening', 'listening', 'She leaned against the wall and untied her shoes.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tủ lạnh hầu như trống rỗng khi chúng tôi về đến nhà.","Chúng tôi đã kéo lê tấm thảm nặng đi ngang qua căn phòng.","Chúng tôi hứng nước mưa bằng một chiếc thùng gỗ ở phía sau nhà kho.","Cô ấy tựa lưng vào tường và cởi giày ra."]'::jsonb, 3, 'She leaned against the wall and untied her shoes. → Cô ấy tựa lưng vào tường và cởi giày ra.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_83_2', 'en-b2-83', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_83_2_1', 'ten_b2_83_2', 'initial', 'Although the initial cost of solar panels is high, households may save money over the longer term.', 'Although the initial cost of solar panels is high, households may save money over the longer term.', '/ɪˈnɪʃəl/', 'Mặc dù chi phí ban đầu của các tấm pin năng lượng mặt trời khá cao, các hộ gia đình có thể tiết kiệm tiền về lâu dài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_83_2_2', 'ten_b2_83_2', 'peculiar', 'Some environmental challenges are peculiar to coastal cities, including saltwater intrusion and damage caused by storm surges.', 'Some environmental challenges are peculiar to coastal cities, including saltwater intrusion and damage caused by storm surges.', '/pɪˈkjuːljɚ/', 'Một số thách thức về môi trường là nét đặc thù của các thành phố ven biển, bao gồm tình trạng xâm nhập mặn và thiệt hại do bão dâng gây ra.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_83_2_3', 'ten_b2_83_2', 'lean', 'Lean production methods can help manufacturers reduce waste while maintaining the quality of their products.', 'Lean production methods can help manufacturers reduce waste while maintaining the quality of their products.', '/liːn/', 'Các phương pháp sản xuất tinh gọn có thể giúp nhà sản xuất giảm thiểu lãng phí trong khi vẫn duy trì chất lượng sản phẩm.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_83_2_4', 'ten_b2_83_2', 'milestone', 'The opening of the railway marked a significant milestone in the region''s economic development.', 'The opening of the railway marked a significant milestone in the region''s economic development.', '/ˈmaɪlstoʊn/', 'Việc khai trương tuyến đường sắt đánh dấu một cột mốc đáng kể trong sự phát triển kinh tế của vùng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_83_2_5', 'ten_b2_83_2', 'replacement', 'The replacement of outdated buses with electric vehicles could improve air quality in densely populated cities.', 'The replacement of outdated buses with electric vehicles could improve air quality in densely populated cities.', '/rɪˈpleɪsmənt/', 'Việc thay thế các xe buýt cũ kỹ bằng xe điện có thể cải thiện chất lượng không khí ở các thành phố đông dân cư.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_83_2_6', 'ten_b2_83_2', 'anyhow', 'Although public transport improvements require substantial funding, cities should invest in them anyhow to reduce congestion.', 'Although public transport improvements require substantial funding, cities should invest in them anyhow to reduce congestion.', '/ˈenihaʊ/', 'Mặc dù việc cải thiện giao thông công cộng đòi hỏi nguồn vốn lớn, các thành phố vẫn nên đầu tư vào lĩnh vực này để giảm thiểu tình trạng ùn tắc.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_83_2_1', 'en-b2-83', 'ten_b2_83_2', 'listening', 'listening', 'Although the initial cost of solar panels is high, households may save money over the longer term.', NULL, 'Trong câu vừa nghe, từ “initial” mang nghĩa nào sau đây?', '["ban đầu; lúc đầu","gián tiếp; qua trung gian","sự số ruột; sự bực bội do chờ đợi","vô lý; ngớ ngẩn; lố bịch"]'::jsonb, 0, '“initial” (/ɪˈnɪʃəl/): ban đầu; lúc đầu. Câu đầy đủ: Although the initial cost of solar panels is high, households may save money over the longer term.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_83_2_2', 'en-b2-83', 'ten_b2_83_2', 'listening', 'listening', 'Some environmental challenges are peculiar to coastal cities, including saltwater intrusion and damage caused by storm surges.', NULL, 'Trong câu vừa nghe, từ “peculiar” mang nghĩa nào sau đây?', '["cột chỉ đường; biển chỉ đường","có hoài bão; đầy tham vọng","súng lục; súng ngắn","kỳ lạ; bất thường (đôi khi theo cách khó chịu)"]'::jsonb, 3, '“peculiar” (/pɪˈkjuːljɚ/): kỳ lạ; bất thường (đôi khi theo cách khó chịu). Câu đầy đủ: Some environmental challenges are peculiar to coastal cities, including saltwater intrusion and damage caused by storm surges.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
