INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_b2_83_1', 'en-b2-83', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “initial” (/ɪˈnɪʃəl/) có nghĩa là gì?', '["ban đầu; lúc đầu","có tính đàn hồi; co giãn","hầu như; gần như hoàn toàn","dù sao đi nữa; bất chấp"]'::jsonb, 0, '“initial” (adj.): ban đầu; lúc đầu; chữ cái đầu trong tên của một người; ký tên bằng chữ cái đầu.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
