INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_83_2', 'en-b2-83', NULL, 'comprehensive_test', 'listening', 'A peculiar smell came from the cupboard under the stairs.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sau khi đạp xe về nhà, tôi đã tu ừng ực hết một cốc nước.","Cô ấy dùng nĩa xiên vào củ khoai tây để kiểm tra xem đã chín chưa.","Một mùi kỳ lạ phát ra từ chiếc tủ dưới cầu thang.","Hãy kiểm tra độ dày của tấm gỗ trước khi mua nó."]'::jsonb, 2, 'A peculiar smell came from the cupboard under the stairs. → Một mùi kỳ lạ phát ra từ chiếc tủ dưới cầu thang.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_83_3', 'en-b2-83', NULL, 'comprehensive_test', 'listening', 'lean', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["khả nghi; đáng ngờ","phai màu; làm phai màu","nghiêng; tựa; dựa","tổ tiên; ông cha"]'::jsonb, 2, 'lean (/liːn/) → nghiêng; tựa; dựa; ít mỡ; nạc; tinh gọn; hiệu quả và tiết kiệm', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_83_4', 'en-b2-83', NULL, 'comprehensive_test', 'listening', 'Getting her first job was a milestone for Sara.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Có được công việc đầu tiên là một cột mốc quan trọng đối với Sara.","Chúng tôi hứng nước mưa bằng một chiếc thùng gỗ ở phía sau nhà kho.","Tắm nước ấm giúp làm dịu cơn đau ở vai tôi.","Trời đang mưa nhưng chúng tôi vẫn đi bơi."]'::jsonb, 0, 'Getting her first job was a milestone for Sara. → Có được công việc đầu tiên là một cột mốc quan trọng đối với Sara.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_83_5', 'en-b2-83', NULL, 'comprehensive_test', 'listening', 'replacement', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thế thân; vật thay thế","sự thỏa hiệp; giải pháp dung hòa; phương án đôi bên cùng nhượng bộ","sự hoài nghi; sự nghi ngờ; tình nghi","khoác lác; khoe khoang; tự cao"]'::jsonb, 0, 'replacement (/rɪˈpleɪsmənt/) → thế thân; vật thay thế; sự thay thế; sự đổi', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_83_6', 'en-b2-83', NULL, 'comprehensive_test', 'listening', 'It was raining, but we went swimming anyhow.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sau khi đạp xe về nhà, tôi đã tu ừng ực hết một cốc nước.","Trời đang mưa nhưng chúng tôi vẫn đi bơi.","Bạn có thể cắt ngắn chiếc quần này trước lễ cưới không?","Chỉ dẫn rõ ràng của bạn đã giúp chúng tôi tìm được ngôi nhà nhỏ rất nhiều."]'::jsonb, 1, 'It was raining, but we went swimming anyhow. → Trời đang mưa nhưng chúng tôi vẫn đi bơi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
