INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_83_18', 'en-b2-83', NULL, 'comprehensive_test', 'reading', NULL, 'Although the initial cost of solar panels is high, households may save money over the longer term.', 'Dựa vào câu trên, từ “initial” có nghĩa phù hợp nhất là gì?', '["quá hạn thanh toán; chậm trả","táo bạo; dũng cảm","sáp; sáp nến","ban đầu; lúc đầu"]'::jsonb, 3, 'initial: ban đầu; lúc đầu; chữ cái đầu trong tên của một người; ký tên bằng chữ cái đầu. Dịch cả câu: Mặc dù chi phí ban đầu của các tấm pin năng lượng mặt trời khá cao, các hộ gia đình có thể tiết kiệm tiền về lâu dài.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_83_19', 'en-b2-83', NULL, 'comprehensive_test', 'reading', NULL, 'Some environmental challenges are peculiar to coastal cities, including saltwater intrusion and damage caused by storm surges.', 'Dựa vào câu trên, từ “peculiar” có nghĩa phù hợp nhất là gì?', '["giường tầng; giường nằm (trên tàu, xe)","kỳ lạ; bất thường (đôi khi theo cách khó chịu)","tủ chén; tủ đựng đồ","thói quen; tập quán; phong tục"]'::jsonb, 1, 'peculiar: kỳ lạ; bất thường (đôi khi theo cách khó chịu); đặc thù; độc quyền của một người, nhóm, địa điểm hoặc vật cụ thể. Dịch cả câu: Một số thách thức về môi trường là nét đặc thù của các thành phố ven biển, bao gồm tình trạng xâm nhập mặn và thiệt hại do bão dâng gây ra.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_83_20', 'en-b2-83', NULL, 'comprehensive_test', 'reading', NULL, 'Lean production methods can help manufacturers reduce waste while maintaining the quality of their products.', 'Dựa vào câu trên, từ “lean” có nghĩa phù hợp nhất là gì?', '["nghiêng; tựa; dựa","ao-xơ; đơn vị đo khối lượng","anh chị em ruột","thu hút; làm say mê; giữ chân"]'::jsonb, 0, 'lean: nghiêng; tựa; dựa; ít mỡ; nạc; tinh gọn; hiệu quả và tiết kiệm. Dịch cả câu: Các phương pháp sản xuất tinh gọn có thể giúp nhà sản xuất giảm thiểu lãng phí trong khi vẫn duy trì chất lượng sản phẩm.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_83_21', 'en-b2-83', NULL, 'comprehensive_test', 'reading', NULL, 'The opening of the railway marked a significant milestone in the region''s economic development.', 'Dựa vào câu trên, từ “milestone” có nghĩa phù hợp nhất là gì?', '["cột mốc quan trọng; bước ngoặt","làm quá tải; chồng chất gánh nặng","hệ sinh thái","tổng quan; bản tóm tắt"]'::jsonb, 0, 'milestone: cột mốc quan trọng; bước ngoặt; cột mốc chỉ đường. Dịch cả câu: Việc khai trương tuyến đường sắt đánh dấu một cột mốc đáng kể trong sự phát triển kinh tế của vùng.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_83_22', 'en-b2-83', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “một cách dễ dàng; không khó khăn”', '["stable","readily","remedy","bungalow"]'::jsonb, 1, 'một cách dễ dàng; không khó khăn → readily (/ˈredɪli/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_83_23', 'en-b2-83', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đồ muối chua; dưa chua”', '["pickle","anxiously","thigh","congress"]'::jsonb, 0, 'đồ muối chua; dưa chua → pickle (/ˈpɪkəl/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_83_24', 'en-b2-83', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “kéo lê; lôi đi”', '["gradual","drag","airy","anchor"]'::jsonb, 1, 'kéo lê; lôi đi → drag (/dræɡ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-84', 'en', 'Bài 84: Đời sống hằng ngày (11) - CEFR B2', 'CEFR B2', 'B2 · Đời sống', '26 từ vựng Tiếng Anh CEFR B2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4084, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stale', 'en-b2-84', 'stale', '/steɪl/', 'B2', 'không còn tươi, ôi thiu (đặc biệt là bánh mì hoặc không khí); lỗi thời, nhàm chán, kém phong phú do dùng lặp lại', 'adj.', 'staleness (n.)', 'Trái nghĩa: fresh', 'stale chỉ sự mất đi độ tươi mới; rotten chỉ vật đã bị thối rữa.', 'This bread is stale, so I''ll use it for breadcrumbs.', NULL, 'Ổ bánh mì này cũ và khô rồi, tôi sẽ dùng nó làm vụn bánh mì.', '{"wordId":"stale","ukIpa":"/steɪl/","usIpa":"/steɪl/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"No longer fresh, especially when describing bread or air.","vi":"không còn tươi, ôi thiu (đặc biệt là bánh mì hoặc không khí)"},{"pos":"adj.","en":"No longer interesting or original because of repeated use.","vi":"lỗi thời, nhàm chán, kém phong phú do dùng lặp lại"}],"examples":[{"en":"This bread is stale, so I''ll use it for breadcrumbs.","vi":"Ổ bánh mì này cũ và khô rồi, tôi sẽ dùng nó làm vụn bánh mì.","audioKind":"ex"},{"en":"Teaching methods can become stale when educators lack opportunities to exchange ideas and develop new skills.","vi":"Phương pháp giảng dạy có thể trở nên nhàm chán khi các nhà giáo dục thiếu cơ hội trao đổi ý tưởng và phát triển kỹ năng mới.","audioKind":"ex2"}],"collocations":[{"en":"stale bread","vi":"bánh mì cũ không còn tươi"},{"en":"stale air","vi":"không khí ngột ngạt"},{"en":"stale jokes","vi":"câu nói đùa nhàm chán"}],"wordFamily":["staleness (n.)"],"synonyms":[],"antonyms":["fresh"],"tipVi":"stale chỉ sự mất đi độ tươi mới; rotten chỉ vật đã bị thối rữa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_garment', 'en-b2-84', 'garment', '/ˈɡɑːrmənt/', 'B2', 'một món đồ trang phục, quần áo', 'n.', NULL, NULL, 'Đây là danh từ đếm được chỉ một món quần áo cụ thể; trong khi clothing thường là danh từ không đếm được.', 'This delicate garment needs to be washed by hand.', NULL, 'Món đồ mỏng manh này cần phải được giặt bằng tay.', '{"wordId":"garment","ukIpa":"/ˈɡɑːmənt/","usIpa":"/ˈɡɑːrmənt/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"a single item of clothing","vi":"một món đồ trang phục, quần áo"}],"examples":[{"en":"This delicate garment needs to be washed by hand.","vi":"Món đồ mỏng manh này cần phải được giặt bằng tay.","audioKind":"ex"},{"en":"Improving working conditions in the garment industry requires cooperation between manufacturers, retailers, and national governments.","vi":"Việc cải thiện điều kiện làm việc trong ngành may mặc đòi hỏi sự hợp tác giữa các nhà sản xuất, nhà bán lẻ và chính phủ các nước.","audioKind":"ex2"}],"collocations":[{"en":"a woollen garment","vi":"một trang phục len"},{"en":"the garment industry","vi":"ngành may mặc"},{"en":"garment workers","vi":"công nhân may"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Đây là danh từ đếm được chỉ một món quần áo cụ thể; trong khi clothing thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_delicate', 'en-b2-84', 'delicate', '/ˈdelɪkət/', 'B2', 'mỏng manh, dễ vỡ, dễ hư hỏng; nhạy cảm, tinh tế, đòi hỏi sự cẩn trọng để tránh rắc rối; tinh vi, nhẹ nhàng về mặt hình thức, hương vị hoặc mùi thơm', 'adj.', 'delicately (adv.), delicacy (n.)', 'Đồng nghĩa: fragile · Trái nghĩa: robust', 'Có thể dùng để tả đồ vật dễ vỡ hoặc các vấn đề xã hội/ngoại giao cần sự khéo léo.', 'Please wrap these delicate glass bowls in soft paper.', NULL, 'Xin hãy bọc những chiếc bát thủy tinh dễ vỡ này bằng giấy mềm.', '{"wordId":"delicate","ukIpa":"/ˈdelɪkət/","usIpa":"/ˈdelɪkət/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Easily damaged or harmed.","vi":"mỏng manh, dễ vỡ, dễ hư hỏng"},{"pos":"adj.","en":"Requiring careful handling to avoid problems or offence.","vi":"nhạy cảm, tinh tế, đòi hỏi sự cẩn trọng để tránh rắc rối"},{"pos":"adj.","en":"Fine, subtle, or gentle in appearance, flavour, or smell.","vi":"tinh vi, nhẹ nhàng về mặt hình thức, hương vị hoặc mùi thơm"}],"examples":[{"en":"Please wrap these delicate glass bowls in soft paper.","vi":"Xin hãy bọc những chiếc bát thủy tinh dễ vỡ này bằng giấy mềm.","audioKind":"ex"},{"en":"Tourism in coastal regions must be carefully managed to protect delicate ecosystems from lasting damage.","vi":"Du lịch ở các vùng ven biển phải được quản lý cẩn thận để bảo vệ các hệ sinh thái mỏng manh khỏi tổn hại lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"delicate balance","vi":"sự cân bằng mỏng manh"},{"en":"delicate fabric","vi":"chất vải dễ hỏng"},{"en":"delicate flavour","vi":"hương vị thanh tao"},{"en":"delicate negotiations","vi":"các cuộc đàm phán nhạy cảm"}],"wordFamily":["delicately (adv.)","delicacy (n.)"],"synonyms":["fragile"],"antonyms":["robust"],"tipVi":"Có thể dùng để tả đồ vật dễ vỡ hoặc các vấn đề xã hội/ngoại giao cần sự khéo léo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_swallow', 'en-b2-84', 'swallow', '/ˈswɑːloʊ/', 'B2', 'nuốt; tin sái cổ; miễn cưỡng chấp nhận; chim nhạn; chim én', 'v.', NULL, NULL, 'Cụm "swallow your pride" có nghĩa là hạ cái tôi xuống để chấp nhận điều mình không muốn.', 'Please swallow your food before you start talking again.', NULL, 'Làm ơn hãy nuốt thức ăn trước khi bạn bắt đầu nói chuyện lại.', '{"wordId":"swallow","ukIpa":"/ˈswɒləʊ/","usIpa":"/ˈswɑːloʊ/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"make food or liquid pass from your mouth into your stomach","vi":"nuốt"},{"pos":"v.","en":"believe something too easily or accept something unpleasant","vi":"tin sái cổ; miễn cưỡng chấp nhận"},{"pos":"n.","en":"a small bird with pointed wings and a forked tail","vi":"chim nhạn; chim én"}],"examples":[{"en":"Please swallow your food before you start talking again.","vi":"Làm ơn hãy nuốt thức ăn trước khi bạn bắt đầu nói chuyện lại.","audioKind":"ex"},{"en":"Consumers should not simply swallow advertising claims without examining the evidence behind promises of better health.","vi":"Người tiêu dùng không nên dễ dãi tin ngay vào các tuyên bố quảng cáo mà không xem xét bằng chứng đứng sau những lời hứa hẹn về sức khỏe tốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"swallow a tablet","vi":"nuốt một viên thuốc"},{"en":"swallow your pride","vi":"bỏ sĩ diện; nén lòng tự ái"},{"en":"hard to swallow","vi":"khó tin; khó chấp nhận"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm \"swallow your pride\" có nghĩa là hạ cái tôi xuống để chấp nhận điều mình không muốn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_specifically', 'en-b2-84', 'specifically', '/spəˈsɪfɪkli/', 'B2', 'riêng biệt; đặc biệt, chuyên dụng; rõ ràng; cụ thể; cụ thể là; nói rõ hơn là', 'adv.', 'specific (adj.), specify (v.), specification (n.)', 'Đồng nghĩa: particularly, expressly · Trái nghĩa: generally', 'Dùng "specifically for" để nhấn mạnh mục đích chuyên dụng; dùng "more specifically" khi muốn nói cụ thể hơn.', 'I bought this small brush specifically for cleaning bottles.', NULL, 'Tôi mua chiếc bàn chải nhỏ này chuyên dùng để cọ bình sữa.', '{"wordId":"specifically","ukIpa":"/spəˈsɪfɪkli/","usIpa":"/spəˈsɪfɪkli/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"for one particular purpose, person, or group","vi":"riêng biệt; đặc biệt, chuyên dụng"},{"pos":"adv.","en":"in a clear and exact way","vi":"rõ ràng; cụ thể"},{"pos":"adv.","en":"used to introduce more precise details","vi":"cụ thể là; nói rõ hơn là"}],"examples":[{"en":"I bought this small brush specifically for cleaning bottles.","vi":"Tôi mua chiếc bàn chải nhỏ này chuyên dùng để cọ bình sữa.","audioKind":"ex"},{"en":"Public libraries should offer programmes specifically designed to help older adults develop essential digital skills.","vi":"Các thư viện công cộng nên cung cấp các chương trình được thiết kế riêng để giúp người lớn tuổi phát triển các kỹ năng số thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"specifically designed for","vi":"được thiết kế riêng cho"},{"en":"specifically mention","vi":"nhắc đến một cách cụ thể"},{"en":"more specifically","vi":"cụ thể hơn là"}],"wordFamily":["specific (adj.)","specify (v.)","specification (n.)"],"synonyms":["particularly","expressly"],"antonyms":["generally"],"tipVi":"Dùng \"specifically for\" để nhấn mạnh mục đích chuyên dụng; dùng \"more specifically\" khi muốn nói cụ thể hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_butt', 'en-b2-84', 'butt', '/bʌt/', 'B2', 'đầu mẩu thuốc lá; tàn thuốc; mông; thùng lớn; thùng chứa nước mưa', 'n.', NULL, NULL, 'Nghĩa chỉ mông thuộc văn phong thông tục Mỹ; "water butt" là từ chỉ thùng chứa nước mưa theo tiếng Anh - Anh.', 'He swept a cigarette butt off the front step.', NULL, 'Anh ấy quét một mẩu tàn thuốc lá khỏi bậc cửa trước.', '{"wordId":"butt","ukIpa":"/bʌt/","usIpa":"/bʌt/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"the short part left after a cigarette has been smoked","vi":"đầu mẩu thuốc lá; tàn thuốc"},{"pos":"n.","en":"the part of the body that you sit on","vi":"mông"},{"pos":"n.","en":"a large barrel used for storing water or other liquids","vi":"thùng lớn; thùng chứa nước mưa"}],"examples":[{"en":"He swept a cigarette butt off the front step.","vi":"Anh ấy quét một mẩu tàn thuốc lá khỏi bậc cửa trước.","audioKind":"ex"},{"en":"Discarded cigarette butts contribute to urban litter and can release harmful substances into rivers and coastal waters.","vi":"Những tàn thuốc lá bị vứt bừa bãi làm gia tăng rác thải đô thị và có thể thải các chất độc hại vào sông ngòi cũng như vùng nước ven biển.","audioKind":"ex2"}],"collocations":[{"en":"cigarette butt","vi":"mẩu thuốc lá"},{"en":"water butt","vi":"thùng chứa nước mưa"},{"en":"the butt of a joke","vi":"mục tiêu để trêu chọc"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa chỉ mông thuộc văn phong thông tục Mỹ; \"water butt\" là từ chỉ thùng chứa nước mưa theo tiếng Anh - Anh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spin', 'en-b2-84', 'spin', '/spɪn/', 'B2', 'quay; xoay tròn; kéo sợi; nhả tơ; sự quay vòng; cách diễn giải theo chiều hướng có lợi', 'v.', 'spinner (n.), spinning (n.)', 'Đồng nghĩa: rotate, revolve', 'Dạng quá khứ và phân từ hai đều là spun; phân từ hiện đại là spinning.', 'The wheel kept spinning after I lifted the bicycle.', NULL, 'Bánh xe vẫn tiếp tục quay sau khi tôi nhấc chiếc xe đạp lên.', '{"wordId":"spin","ukIpa":"/spɪn/","usIpa":"/spɪn/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"turn quickly around a central point","vi":"quay; xoay tròn"},{"pos":"v.","en":"make thread from fibres or produce silk","vi":"kéo sợi; nhả tơ"},{"pos":"n.","en":"a turning movement, or a deliberately favourable interpretation","vi":"sự quay vòng; cách diễn giải theo chiều hướng có lợi"}],"examples":[{"en":"The wheel kept spinning after I lifted the bicycle.","vi":"Bánh xe vẫn tiếp tục quay sau khi tôi nhấc chiếc xe đạp lên.","audioKind":"ex"},{"en":"News organisations should examine official claims carefully rather than simply repeat the political spin surrounding them.","vi":"Các tổ chức tin tức nên xem xét kỹ lưỡng các tuyên bố chính thức thay vì chỉ lặp lại cách định hướng thông tin mang tính chính trị xoay quanh chúng.","audioKind":"ex2"}],"collocations":[{"en":"spin round","vi":"quay vòng"},{"en":"spin wool","vi":"kéo sợi len"},{"en":"political spin","vi":"thông tin định hướng chính trị"},{"en":"go for a spin","vi":"đi dạo hóng gió"}],"wordFamily":["spinner (n.)","spinning (n.)"],"synonyms":["rotate","revolve"],"antonyms":[],"tipVi":"Dạng quá khứ và phân từ hai đều là spun; phân từ hiện đại là spinning.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_noticeable', 'en-b2-84', 'noticeable', '/ˈnoʊtɪsəbəl/', 'B2', 'rõ rệt; dễ nhận thấy', 'adj.', 'notice (v.), notice (n.), noticeably (adv.), unnoticeable (adj.)', 'Đồng nghĩa: obvious, apparent, perceptible · Trái nghĩa: unnoticeable, imperceptible', 'Noticeable chỉ điều dễ dàng nhận biết; trong khi notable nhấn mạnh vào điểm đáng chú ý.', 'There is a noticeable scratch on my new table.', NULL, 'Có một vết xước rõ rệt trên chiếc bàn mới của tôi.', '{"wordId":"noticeable","ukIpa":"/ˈnəʊtɪsəbəl/","usIpa":"/ˈnoʊtɪsəbəl/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Easy to see or recognize.","vi":"rõ rệt; dễ nhận thấy"}],"examples":[{"en":"There is a noticeable scratch on my new table.","vi":"Có một vết xước rõ rệt trên chiếc bàn mới của tôi.","audioKind":"ex"},{"en":"The introduction of electric buses has led to a noticeable reduction in noise near busy roads.","vi":"Việc đưa vào sử dụng xe buýt điện đã giúp giảm đáng kể tiếng ồn gần các tuyến đường đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"a noticeable difference","vi":"sự khác biệt rõ rệt"},{"en":"a noticeable improvement","vi":"sự cải thiện đáng kể"},{"en":"a noticeable increase","vi":"sự gia tăng rõ rệt"}],"wordFamily":["notice (v.)","notice (n.)","noticeably (adv.)","unnoticeable (adj.)"],"synonyms":["obvious","apparent","perceptible"],"antonyms":["unnoticeable","imperceptible"],"tipVi":"Noticeable chỉ điều dễ dàng nhận biết; trong khi notable nhấn mạnh vào điểm đáng chú ý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_blur', 'en-b2-84', 'blur', '/blɝː/', 'B2', 'làm mờ; trở nên mờ đi; hình ảnh mờ ảo; ký ức mơ hồ', 'v.', 'blurred (adj.), blurry (adj.)', NULL, 'Thường chỉ thị giác hoặc ranh giới bị nhòe; không dùng với nghĩa ''vết bẩn''.', 'Tears blurred my vision as the train pulled away.', NULL, 'Nước mắt làm mờ đi tầm nhìn của tôi khi đoàn tàu từ từ lăn bánh rời đi.', '{"wordId":"blur","ukIpa":"/blɜː/","usIpa":"/blɝː/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to make or become difficult to see or distinguish clearly","vi":"làm mờ; trở nên mờ đi"},{"pos":"n.","en":"something that cannot be seen or remembered clearly","vi":"hình ảnh mờ ảo; ký ức mơ hồ"}],"examples":[{"en":"Tears blurred my vision as the train pulled away.","vi":"Nước mắt làm mờ đi tầm nhìn của tôi khi đoàn tàu từ từ lăn bánh rời đi.","audioKind":"ex"},{"en":"Working from home can blur the boundary between professional responsibilities and personal life, increasing stress.","vi":"Làm việc tại nhà có thể làm mờ ranh giới giữa trách nhiệm công việc và cuộc sống cá nhân, làm gia tăng áp lực.","audioKind":"ex2"}],"collocations":[{"en":"blur the distinction","vi":"làm mờ sự khác biệt"},{"en":"blur the boundaries","vi":"làm mờ ranh giới"},{"en":"a blur of colour","vi":"một mảng màu nhòe nhoẹt"}],"wordFamily":["blurred (adj.)","blurry (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ thị giác hoặc ranh giới bị nhòe; không dùng với nghĩa ''vết bẩn''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rip', 'en-b2-84', 'rip', '/rɪp/', 'B2', 'xé rách; làm rách; vết rách; chỗ rách', 'v.', 'ripped (adj.)', 'Đồng nghĩa: tear', 'Dạng quá khứ và quá phân từ của "rip" đều là "ripped".', 'I ripped my sleeve on a sharp branch yesterday.', NULL, 'Hôm qua tay áo tôi đã bị vướng vào một cành cây sắc nhọn làm rách.', '{"wordId":"rip","ukIpa":"/rɪp/","usIpa":"/rɪp/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To tear something quickly or forcefully, or become torn.","vi":"xé rách; làm rách"},{"pos":"n.","en":"A long hole caused by tearing material.","vi":"vết rách; chỗ rách"}],"examples":[{"en":"I ripped my sleeve on a sharp branch yesterday.","vi":"Hôm qua tay áo tôi đã bị vướng vào một cành cây sắc nhọn làm rách.","audioKind":"ex"},{"en":"Repairing a small rip in clothing instead of replacing it can reduce household waste.","vi":"Việc vá lại một vết rách nhỏ trên quần áo thay vì vứt bỏ có thể giúp giảm thiểu rác thải sinh hoạt.","audioKind":"ex2"}],"collocations":[{"en":"rip open","vi":"xé toạc"},{"en":"rip apart","vi":"xé nát thành từng mảnh"},{"en":"a rip in","vi":"vết rách trên..."}],"wordFamily":["ripped (adj.)"],"synonyms":["tear"],"antonyms":[],"tipVi":"Dạng quá khứ và quá phân từ của \"rip\" đều là \"ripped\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reasonably', 'en-b2-84', 'reasonably', '/ˈriːzənəbli/', 'B2', 'khá; tương đối; hợp lý; có chừng mực; vừa phải; với giá cả phải chăng', 'adv.', 'reasonable (adj.), reason (n.), unreasonable (adj.)', 'Đồng nghĩa: fairly, sensibly · Trái nghĩa: unreasonably', 'khi chỉ mức độ thì gần nghĩa với fairly chứ không phải là very.', 'The kitchen is reasonably clean, but the floor needs sweeping.', NULL, 'Căn bếp khá sạch sẽ, nhưng sàn nhà cần phải được quét dọn.', '{"wordId":"reasonably","ukIpa":"/ˈriːzənəbli/","usIpa":"/ˈriːzənəbli/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"to a fairly good or satisfactory degree","vi":"khá; tương đối"},{"pos":"adv.","en":"in a sensible, fair, or logical way","vi":"hợp lý; có chừng mực"},{"pos":"adv.","en":"at a fair and affordable price","vi":"vừa phải; với giá cả phải chăng"}],"examples":[{"en":"The kitchen is reasonably clean, but the floor needs sweeping.","vi":"Căn bếp khá sạch sẽ, nhưng sàn nhà cần phải được quét dọn.","audioKind":"ex"},{"en":"Public transport must be reasonably priced if cities want more residents to leave their cars at home.","vi":"Giao thông công cộng phải có giá cả phải chăng nếu các thành phố muốn nhiều cư dân từ bỏ việc lái xe cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"reasonably good","vi":"khá tốt"},{"en":"reasonably priced","vi":"giá cả phải chăng"},{"en":"reasonably expect","vi":"có thể hợp lý kỳ vọng"}],"wordFamily":["reasonable (adj.)","reason (n.)","unreasonable (adj.)"],"synonyms":["fairly","sensibly"],"antonyms":["unreasonably"],"tipVi":"khi chỉ mức độ thì gần nghĩa với fairly chứ không phải là very.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_peg', 'en-b2-84', 'peg', '/peɡ/', 'B2', 'móc treo; cọc; chốt; kẹp phơi quần áo; neo (giá cả, tỷ giá)', 'n.', NULL, NULL, 'Động từ thường dùng cấu trúc "peg A to B"; kẹp phơi quần áo trong tiếng Anh-Mỹ gọi là "clothespin".', 'Hang your wet coat on the peg by the door.', NULL, 'Hãy treo chiếc áo khoác ướt của bạn lên móc ở cạnh cửa.', '{"wordId":"peg","ukIpa":"/peɡ/","usIpa":"/peɡ/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"a small pin or post used to hang or secure things","vi":"móc treo; cọc; chốt"},{"pos":"n.","en":"a clip that holds clothes on a washing line","vi":"kẹp phơi quần áo"},{"pos":"v.","en":"to fix a price or rate in relation to another","vi":"neo (giá cả, tỷ giá)"}],"examples":[{"en":"Hang your wet coat on the peg by the door.","vi":"Hãy treo chiếc áo khoác ướt của bạn lên móc ở cạnh cửa.","audioKind":"ex"},{"en":"Some governments peg their currencies to a major foreign currency to reduce exchange rate uncertainty.","vi":"Một số chính phủ neo đồng nội tệ của họ vào một ngoại tệ mạnh để giảm bớt sự bất ổn về tỷ giá hối đoái.","audioKind":"ex2"}],"collocations":[{"en":"tent peg","vi":"cọc lều"},{"en":"clothes peg","vi":"kẹp phơi quần áo"},{"en":"peg a currency to","vi":"neo tỷ giá đồng tiền vào"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Động từ thường dùng cấu trúc \"peg A to B\"; kẹp phơi quần áo trong tiếng Anh-Mỹ gọi là \"clothespin\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shrink', 'en-b2-84', 'shrink', '/ʃrɪŋk/', 'B2', 'thu nhỏ; co lại; giảm bớt; lùi bước; né tránh; chùn bước', 'v.', 'shrinkage (n.), shrunken (adj.)', 'Đồng nghĩa: contract, diminish · Trái nghĩa: expand, grow', 'Dạng quá khứ là shrank, quá phân từ là shrunk; shrink from dùng để chỉ thái độ chùn bước, né tránh.', 'My wool jumper shrank after I washed it badly.', NULL, 'Chiếc áo len lông cừu của tôi đã bị co lại sau khi tôi giặt không đúng cách.', '{"wordId":"shrink","ukIpa":"/ʃrɪŋk/","usIpa":"/ʃrɪŋk/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To become smaller, or make something smaller.","vi":"thu nhỏ; co lại; giảm bớt"},{"pos":"v.","en":"To move back or avoid something through fear or discomfort.","vi":"lùi bước; né tránh; chùn bước"}],"examples":[{"en":"My wool jumper shrank after I washed it badly.","vi":"Chiếc áo len lông cừu của tôi đã bị co lại sau khi tôi giặt không đúng cách.","audioKind":"ex"},{"en":"As rural populations shrink, maintaining affordable public transport becomes increasingly difficult for local authorities with limited budgets.","vi":"Khi dân số nông thôn ngày càng giảm, việc duy trì hệ thống giao thông công cộng giá rẻ trở nên vô cùng khó khăn đối với các cơ quan địa phương có ngân sách hạn hẹp.","audioKind":"ex2"}],"collocations":[{"en":"shrink in size","vi":"thu nhỏ kích thước"},{"en":"a shrinking population","vi":"dân số đang thu hẹp"},{"en":"shrink from responsibility","vi":"né tránh trách nhiệm"}],"wordFamily":["shrinkage (n.)","shrunken (adj.)"],"synonyms":["contract","diminish"],"antonyms":["expand","grow"],"tipVi":"Dạng quá khứ là shrank, quá phân từ là shrunk; shrink from dùng để chỉ thái độ chùn bước, né tránh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_apiece', 'en-b2-84', 'apiece', '/əˈpiːs/', 'B2', 'mỗi (cái/người); mỗi chiếc', 'adv.', NULL, 'Đồng nghĩa: each', 'Thường đứng sau giá tiền hoặc số lượng, không đứng trước danh từ với vai trò hạn định.', 'We bought fresh peaches for fifty cents apiece.', NULL, 'Chúng tôi đã mua những quả đào tươi với giá năm mươi xu một quả.', '{"wordId":"apiece","ukIpa":"/əˈpiːs/","usIpa":"/əˈpiːs/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"For each person or thing separately.","vi":"mỗi (cái/người); mỗi chiếc"}],"examples":[{"en":"We bought fresh peaches for fifty cents apiece.","vi":"Chúng tôi đã mua những quả đào tươi với giá năm mươi xu một quả.","audioKind":"ex"},{"en":"Reusable containers may cost more apiece initially, but they can reduce packaging expenses over the long term.","vi":"Các hộp đựng tái sử dụng ban đầu có thể đắt hơn tính trên mỗi chiếc, nhưng chúng có thể làm giảm chi phí đóng gói về lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"cost ten dollars apiece","vi":"giá mười đô la một cái"},{"en":"two apiece","vi":"mỗi người hai cái"},{"en":"one apiece","vi":"mỗi người một cái"}],"wordFamily":[],"synonyms":["each"],"antonyms":[],"tipVi":"Thường đứng sau giá tiền hoặc số lượng, không đứng trước danh từ với vai trò hạn định.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_considerably', 'en-b2-84', 'considerably', '/kənˈsɪdərəbli/', 'B2', 'đáng kể; nhiều', 'adv.', 'considerable (adj.)', 'Đồng nghĩa: significantly, substantially · Trái nghĩa: slightly', 'Thường dùng để bổ nghĩa cho tính từ so sánh hơn hoặc các động từ chỉ sự thay đổi, diễn tả mức độ lớn.', 'Our new flat is considerably warmer than the old one.', NULL, 'Căn hộ mới của chúng tôi ấm hơn hẳn so với căn cũ.', '{"wordId":"considerably","ukIpa":"/kənˈsɪdərəbli/","usIpa":"/kənˈsɪdərəbli/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"by a large amount or to a large degree","vi":"đáng kể; nhiều"}],"examples":[{"en":"Our new flat is considerably warmer than the old one.","vi":"Căn hộ mới của chúng tôi ấm hơn hẳn so với căn cũ.","audioKind":"ex"},{"en":"Improved public transport could considerably reduce traffic congestion and air pollution in major cities.","vi":"Việc cải thiện giao thông công cộng có thể làm giảm đáng kể tình trạng tắc nghẽn giao thông và ô nhiễm không khí ở các thành phố lớn.","audioKind":"ex2"}],"collocations":[{"en":"considerably higher","vi":"cao hơn đáng kể"},{"en":"vary considerably","vi":"thay đổi đáng kể"},{"en":"reduce considerably","vi":"giảm đáng kể"}],"wordFamily":["considerable (adj.)"],"synonyms":["significantly","substantially"],"antonyms":["slightly"],"tipVi":"Thường dùng để bổ nghĩa cho tính từ so sánh hơn hoặc các động từ chỉ sự thay đổi, diễn tả mức độ lớn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stack', 'en-b2-84', 'stack', '/stæk/', 'B2', 'chồng (đồ vật xếp chồng lên nhau); xếp thành chồng; chồng chất; nhiều; khối lượng lớn', 'n.', 'stackable (adj.)', 'Đồng nghĩa: pile, heap', 'Cụm stacks of có nghĩa là "rất nhiều", thuộc phong cách sử dụng không trang trọng.', 'A stack of clean plates stood beside the sink.', NULL, 'Một chồng đĩa sạch được đặt cạnh bồn rửa chén.', '{"wordId":"stack","ukIpa":"/stæk/","usIpa":"/stæk/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"a pile of things arranged on top of each other","vi":"chồng (đồ vật xếp chồng lên nhau)"},{"pos":"v.","en":"to arrange things in a pile","vi":"xếp thành chồng; chồng chất"},{"pos":"n.","en":"a large amount of something","vi":"nhiều; khối lượng lớn"}],"examples":[{"en":"A stack of clean plates stood beside the sink.","vi":"Một chồng đĩa sạch được đặt cạnh bồn rửa chén.","audioKind":"ex"},{"en":"Libraries increasingly store stacks of older journals off site to create more space for collaborative learning.","vi":"Các thư viện ngày càng lưu trữ nhiều chồng tạp chí cũ ở bên ngoài cơ sở chính để tạo thêm không gian cho việc học tập hợp tác.","audioKind":"ex2"}],"collocations":[{"en":"a stack of books","vi":"một chồng sách"},{"en":"stack up","vi":"chồng chất lên"},{"en":"stacks of work","vi":"rất nhiều công việc"}],"wordFamily":["stackable (adj.)"],"synonyms":["pile","heap"],"antonyms":[],"tipVi":"Cụm stacks of có nghĩa là \"rất nhiều\", thuộc phong cách sử dụng không trang trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vary', 'en-b2-84', 'vary', '/ˈveri/', 'B2', 'khác nhau; thay đổi tùy theo hoàn cảnh; làm cho khác nhau; thay đổi cho đa dạng', 'v.', 'variation (n.), variety (n.), varied (adj.), variable (adj.)', 'Đồng nghĩa: differ, change', 'Cấu trúc vary from A to B dùng để chỉ khoảng thay đổi; vary in dùng để chỉ sự khác biệt ở mặt nào đó.', 'Bus fares vary depending on how far you travel.', NULL, 'Giá vé xe buýt thay đổi tùy thuộc vào quãng đường bạn đi.', '{"wordId":"vary","ukIpa":"/ˈveəri/","usIpa":"/ˈveri/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To differ or change depending on circumstances.","vi":"khác nhau; thay đổi tùy theo hoàn cảnh"},{"pos":"v.","en":"To change something or introduce different kinds.","vi":"làm cho khác nhau; thay đổi cho đa dạng"}],"examples":[{"en":"Bus fares vary depending on how far you travel.","vi":"Giá vé xe buýt thay đổi tùy thuộc vào quãng đường bạn đi.","audioKind":"ex"},{"en":"Access to affordable housing can vary considerably between regions, affecting where young professionals choose to live.","vi":"Khả năng tiếp cận nhà ở giá rẻ có thể chênh lệch đáng kể giữa các vùng miền, ảnh hưởng đến quyết định nơi sinh sống của các chuyên gia trẻ tuổi.","audioKind":"ex2"}],"collocations":[{"en":"vary considerably","vi":"khác biệt đáng kể"},{"en":"vary from place to place","vi":"thay đổi tùy theo từng nơi"},{"en":"vary according to","vi":"thay đổi tùy thuộc vào"},{"en":"vary your diet","vi":"làm đa dạng chế độ ăn"}],"wordFamily":["variation (n.)","variety (n.)","varied (adj.)","variable (adj.)"],"synonyms":["differ","change"],"antonyms":[],"tipVi":"Cấu trúc vary from A to B dùng để chỉ khoảng thay đổi; vary in dùng để chỉ sự khác biệt ở mặt nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_poker', 'en-b2-84', 'poker', '/ˈpoʊkər/', 'B2', 'trò chơi bài pô-ke; cây gạt lò sưởi; que khều than', 'n.', NULL, NULL, 'poker là một trò chơi bài cụ thể, không dùng để chỉ chung tất cả các loại bài lá.', 'We played poker with plastic counters after dinner.', NULL, 'Chúng tôi chơi pô-ke bằng các đồng xu nhựa sau bữa tối.', '{"wordId":"poker","ukIpa":"/ˈpəʊkə/","usIpa":"/ˈpoʊkər/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A card game involving bets on the strength of players'' hands.","vi":"trò chơi bài pô-ke"},{"pos":"n.","en":"A metal rod used to move fuel in a fire.","vi":"cây gạt lò sưởi; que khều than"}],"examples":[{"en":"We played poker with plastic counters after dinner.","vi":"Chúng tôi chơi pô-ke bằng các đồng xu nhựa sau bữa tối.","audioKind":"ex"},{"en":"Researchers study poker to understand how people make decisions when information is incomplete and outcomes are uncertain.","vi":"Các nhà nghiên cứu nghiên cứu trò chơi pô-ke để hiểu cách con người đưa ra quyết định khi thông tin chưa đầy đủ và kết quả còn mơ hồ.","audioKind":"ex2"}],"collocations":[{"en":"play poker","vi":"chơi pô-ke"},{"en":"poker face","vi":"khuôn mặt vô cảm"},{"en":"a fireplace poker","vi":"cây gạt lò sưởi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"poker là một trò chơi bài cụ thể, không dùng để chỉ chung tất cả các loại bài lá.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_postal', 'en-b2-84', 'postal', '/ˈpoʊstəl/', 'B2', 'thuộc bưu chính; thuộc bưu điện', 'adj.', 'post (n.), post (v.), postage (n.)', NULL, 'postal là tính từ; phí bưu điện dùng danh từ postage.', 'The postal worker left a parcel by our door.', NULL, 'Nhân viên bưu điện đã để một bưu phẩm ngay trước cửa nhà chúng tôi.', '{"wordId":"postal","ukIpa":"/ˈpəʊstəl/","usIpa":"/ˈpoʊstəl/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Relating to the system of collecting and delivering mail.","vi":"thuộc bưu chính; thuộc bưu điện"}],"examples":[{"en":"The postal worker left a parcel by our door.","vi":"Nhân viên bưu điện đã để một bưu phẩm ngay trước cửa nhà chúng tôi.","audioKind":"ex"},{"en":"Reliable postal services remain essential for rural communities where internet access is limited or unavailable.","vi":"Dịch vụ bưu chính đáng tin cậy vẫn đóng vai trò thiết yếu đối với các cộng đồng nông thôn nơi mạng lưới internet còn hạn chế hoặc không có sẵn.","audioKind":"ex2"}],"collocations":[{"en":"postal services","vi":"dịch vụ bưu chính"},{"en":"a postal worker","vi":"nhân viên bưu điện"},{"en":"a postal address","vi":"địa chỉ bưu điện"},{"en":"a postal code","vi":"mã bưu chính"}],"wordFamily":["post (n.)","post (v.)","postage (n.)"],"synonyms":[],"antonyms":[],"tipVi":"postal là tính từ; phí bưu điện dùng danh từ postage.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aside', 'en-b2-84', 'aside', '/əˈsaɪd/', 'B2', 'sang một bên; ở một phía; tạm gác lại; để dành; lời nói riêng; ý kiến ngoài lề; câu nói đan xen', 'adv.', NULL, NULL, 'aside thường là phó từ; cụm từ "ngoài... ra" dùng aside from.', 'She stepped aside to let the cyclist pass.', NULL, 'Cô ấy bước sang một bên để nhường đường cho người đi xe đạp.', '{"wordId":"aside","ukIpa":"/əˈsaɪd/","usIpa":"/əˈsaɪd/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"to or at one side, away from the main position","vi":"sang một bên; ở một phía"},{"pos":"adv.","en":"away from current consideration or use","vi":"tạm gác lại; để dành"},{"pos":"n.","en":"a quiet remark or comment outside the main conversation","vi":"lời nói riêng; ý kiến ngoài lề; câu nói đan xen"}],"examples":[{"en":"She stepped aside to let the cyclist pass.","vi":"Cô ấy bước sang một bên để nhường đường cho người đi xe đạp.","audioKind":"ex"},{"en":"Governments should set aside sufficient funds for maintaining public parks, rather than focusing solely on new construction.","vi":"Chính phủ nên dành ra các khoản quỹ thỏa đáng để bảo trì công viên công cộng, thay vì chỉ tập trung vào các công trình xây dựng mới.","audioKind":"ex2"}],"collocations":[{"en":"step aside","vi":"bước sang một bên"},{"en":"set aside funds","vi":"dành quỹ"},{"en":"put differences aside","vi":"tạm gác lại sự bất đồng"},{"en":"aside from","vi":"ngoài... ra; bên cạnh"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"aside thường là phó từ; cụm từ \"ngoài... ra\" dùng aside from.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unsatisfactory', 'en-b2-84', 'unsatisfactory', '/ˌʌnsætɪsˈfæktəri/', 'B2', 'không thỏa đáng; không đạt yêu cầu', 'adj.', 'satisfactory (adj.), satisfaction (n.), satisfy (v.), unsatisfactorily (adv.)', 'Đồng nghĩa: inadequate, unacceptable · Trái nghĩa: satisfactory', 'Dùng để chỉ sự vật không đủ tốt; sự không hài lòng của con người dùng dissatisfied.', 'The repair was unsatisfactory, so I called the mechanic again.', NULL, 'Kết quả sửa chữa không đạt yêu cầu nên tôi đã gọi lại cho thợ sửa chữa.', '{"wordId":"unsatisfactory","ukIpa":"/ˌʌnsætɪsˈfæktəri/","usIpa":"/ˌʌnsætɪsˈfæktəri/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Not good enough to meet expectations or requirements.","vi":"không thỏa đáng; không đạt yêu cầu"}],"examples":[{"en":"The repair was unsatisfactory, so I called the mechanic again.","vi":"Kết quả sửa chữa không đạt yêu cầu nên tôi đã gọi lại cho thợ sửa chữa.","audioKind":"ex"},{"en":"Unsatisfactory housing conditions can negatively affect children''s health and their ability to concentrate at school.","vi":"Điều kiện nhà ở không đạt yêu cầu có thể tác động tiêu cực đến sức khỏe của trẻ em và khả năng tập trung học tập ở trường của các em.","audioKind":"ex2"}],"collocations":[{"en":"unsatisfactory results","vi":"kết quả không đạt yêu cầu"},{"en":"unsatisfactory performance","vi":"hiệu suất kém; biểu hiện không đạt yêu cầu"},{"en":"unsatisfactory conditions","vi":"điều kiện kém; điều kiện không đạt yêu cầu"}],"wordFamily":["satisfactory (adj.)","satisfaction (n.)","satisfy (v.)","unsatisfactorily (adv.)"],"synonyms":["inadequate","unacceptable"],"antonyms":["satisfactory"],"tipVi":"Dùng để chỉ sự vật không đủ tốt; sự không hài lòng của con người dùng dissatisfied.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_overdue', 'en-b2-84', 'overdue', '/ˌoʊvərˈduː/', 'B2', 'quá hạn; chậm trả; chậm trễ; quá hạn phải xảy ra; lâu lắm rồi mới có', 'adj.', 'due (adj.)', 'Đồng nghĩa: late', 'long overdue nhấn mạnh “sớm nên có hoặc nên làm”, không chỉ đơn thuần là đến muộn.', 'I found an overdue library book under my bed.', NULL, 'Tôi tìm thấy một cuốn sách thư viện quá hạn dưới gầm giường.', '{"wordId":"overdue","ukIpa":"/ˌəʊvəˈdjuː/","usIpa":"/ˌoʊvərˈduː/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Not paid, returned, or completed by the expected time.","vi":"quá hạn; chậm trả; chậm trễ"},{"pos":"adj.","en":"Needed or deserved much earlier than now.","vi":"quá hạn phải xảy ra; lâu lắm rồi mới có"}],"examples":[{"en":"I found an overdue library book under my bed.","vi":"Tôi tìm thấy một cuốn sách thư viện quá hạn dưới gầm giường.","audioKind":"ex"},{"en":"Investment in rural public transport is long overdue, as many residents still lack reliable services.","vi":"Việc đầu tư vào giao thông công cộng nông thôn đã quá muộn màng và lẽ ra phải được thực hiện từ lâu, vì nhiều cư dân vẫn thiếu các dịch vụ đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"an overdue payment","vi":"khoản thanh toán quá hạn"},{"en":"an overdue library book","vi":"sách thư viện quá hạn"},{"en":"long overdue","vi":"lẽ ra phải có từ lâu"}],"wordFamily":["due (adj.)"],"synonyms":["late"],"antonyms":[],"tipVi":"long overdue nhấn mạnh “sớm nên có hoặc nên làm”, không chỉ đơn thuần là đến muộn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flatten', 'en-b2-84', 'flatten', '/ˈflætn/', 'B2', 'làm phẳng; san phẳng; phá hủy; san bằng thành bình địa', 'v.', 'flat (adj.), flatness (n.)', 'Đồng nghĩa: level, smooth · Trái nghĩa: raise', 'flatten out cũng có thể chỉ giá cả hoặc biểu đồ chững lại, đi ngang.', 'Flatten the dough gently with the palm of your hand.', NULL, 'Dùng lòng bàn tay nhẹ nhàng ép phẳng khối bột.', '{"wordId":"flatten","ukIpa":"/ˈflætn/","usIpa":"/ˈflætn/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to make something flat or become flat","vi":"làm phẳng; san phẳng"},{"pos":"v.","en":"to destroy something so that it falls to the ground","vi":"phá hủy; san bằng thành bình địa"}],"examples":[{"en":"Flatten the dough gently with the palm of your hand.","vi":"Dùng lòng bàn tay nhẹ nhàng ép phẳng khối bột.","audioKind":"ex"},{"en":"Developers sometimes flatten existing buildings rather than renovate them, increasing construction waste and destroying local heritage.","vi":"Các nhà đầu tư đôi khi phá hủy các tòa nhà hiện hữu thay vì cải tạo chúng, làm tăng lượng rác thải xây dựng và hủy hoại di sản địa phương.","audioKind":"ex2"}],"collocations":[{"en":"flatten the dough","vi":"cán phẳng bột"},{"en":"flatten a building","vi":"san bằng một tòa nhà"},{"en":"flatten out","vi":"chững lại; đi ngang"}],"wordFamily":["flat (adj.)","flatness (n.)"],"synonyms":["level","smooth"],"antonyms":["raise"],"tipVi":"flatten out cũng có thể chỉ giá cả hoặc biểu đồ chững lại, đi ngang.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_poke', 'en-b2-84', 'poke', '/poʊk/', 'B2', 'chọc; thọc; thò ra; nhô ra; cái chọc; cú thọc', 'v.', NULL, 'Đồng nghĩa: prod, jab', 'poke fun at là “trêu chọc”, không phải “chọc”.', 'She poked the dough gently to check its softness.', NULL, 'Cô ấy nhẹ nhàng ấn vào cục bột để kiểm tra độ mềm.', '{"wordId":"poke","ukIpa":"/pəʊk/","usIpa":"/poʊk/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to push a finger or pointed object into something","vi":"chọc; thọc"},{"pos":"v.","en":"to move or stick out through an opening","vi":"thò ra; nhô ra"},{"pos":"n.","en":"a quick push with a finger or pointed object","vi":"cái chọc; cú thọc"}],"examples":[{"en":"She poked the dough gently to check its softness.","vi":"Cô ấy nhẹ nhàng ấn vào cục bột để kiểm tra độ mềm.","audioKind":"ex"},{"en":"Museum visitors can poke virtual objects on interactive screens to explore scientific concepts through play.","vi":"Khách tham quan bảo tàng có thể chạm vào các vật thể ảo trên màn hình tương tác để khám phá các khái niệm khoa học thông qua trò chơi.","audioKind":"ex2"}],"collocations":[{"en":"poke a hole in","vi":"chọc một lỗ trên"},{"en":"poke your head out","vi":"thò đầu ra"},{"en":"poke fun at","vi":"trêu chọc; chế nhạo"}],"wordFamily":[],"synonyms":["prod","jab"],"antonyms":[],"tipVi":"poke fun at là “trêu chọc”, không phải “chọc”.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_detach', 'en-b2-84', 'detach', '/dɪˈtætʃ/', 'B2', 'tháo ra; tách rời; tách mình ra (về mặt cảm xúc); thờ ơ', 'v.', 'detachable (adj.), detached (adj.), detachment (n.)', 'Đồng nghĩa: disconnect, separate · Trái nghĩa: attach, connect', 'Thường dùng cấu trúc detach A from B; detachable có nghĩa là có thể tháo rời.', 'You can detach the hood when the rain stops.', NULL, 'Bạn có thể tháo mũ trùm đầu ra khi trời tạnh mưa.', '{"wordId":"detach","ukIpa":"/dɪˈtætʃ/","usIpa":"/dɪˈtætʃ/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to remove or separate something from what it is attached to","vi":"tháo ra; tách rời"},{"pos":"v.","en":"to separate yourself emotionally from a situation or experience","vi":"tách mình ra (về mặt cảm xúc); thờ ơ"}],"examples":[{"en":"You can detach the hood when the rain stops.","vi":"Bạn có thể tháo mũ trùm đầu ra khi trời tạnh mưa.","audioKind":"ex"},{"en":"Researchers must detach themselves from personal preferences when evaluating evidence to ensure that their conclusions remain reliable.","vi":"Các nhà nghiên cứu phải giữ cái nhìn khách quan, không để cảm xúc chi phối khi đánh giá bằng chứng để đảm bảo kết luận của họ vẫn đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"detach from","vi":"tách khỏi"},{"en":"detach the cable","vi":"rút cáp kết nối"},{"en":"detach yourself from","vi":"tách mình ra khỏi"}],"wordFamily":["detachable (adj.)","detached (adj.)","detachment (n.)"],"synonyms":["disconnect","separate"],"antonyms":["attach","connect"],"tipVi":"Thường dùng cấu trúc detach A from B; detachable có nghĩa là có thể tháo rời.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stare', 'en-b2-84', 'stare', '/ster/', 'B2', 'nhìn chằm chằm; chăm chú; cái nhìn chằm chằm; ánh mắt đờ đẫn', 'v.', NULL, 'Đồng nghĩa: gaze', 'stare at nhấn mạnh hành động nhìn chăm chú trong thời gian dài; glance at có nghĩa là liếc nhìn.', 'The cat stared at a bird outside the window.', NULL, 'Con mèo đang chăm chú nhìn một con chim ở bên ngoài cửa sổ.', '{"wordId":"stare","ukIpa":"/steə/","usIpa":"/ster/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to look at someone or something steadily for a while","vi":"nhìn chằm chằm; chăm chú"},{"pos":"n.","en":"a long, fixed look at someone or something","vi":"cái nhìn chằm chằm; ánh mắt đờ đẫn"}],"examples":[{"en":"The cat stared at a bird outside the window.","vi":"Con mèo đang chăm chú nhìn một con chim ở bên ngoài cửa sổ.","audioKind":"ex"},{"en":"Children who stare at screens for long periods may have fewer opportunities for physical activity.","vi":"Trẻ em nhìn chằm chằm vào màn hình trong thời gian dài có thể có ít cơ hội tham gia các hoạt động thể chất hơn.","audioKind":"ex2"}],"collocations":[{"en":"stare at","vi":"nhìn chằm chằm vào"},{"en":"stare into space","vi":"nhìn vẩn vơ vào không trung"},{"en":"a blank stare","vi":"ánh mắt thẫn thờ"}],"wordFamily":[],"synonyms":["gaze"],"antonyms":[],"tipVi":"stare at nhấn mạnh hành động nhìn chăm chú trong thời gian dài; glance at có nghĩa là liếc nhìn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_84_1', 'en-b2-84', 'Cách dùng “butt” (n.) — đầu mẩu thuốc lá; tàn thuốc', 'cigarette butt  ·  water butt  ·  the butt of a joke', 'Nghĩa chỉ mông thuộc văn phong thông tục Mỹ; "water butt" là từ chỉ thùng chứa nước mưa theo tiếng Anh - Anh.', NULL, '[{"hanzi":"He swept a cigarette butt off the front step.","pinyin":"","meaning":"Anh ấy quét một mẩu tàn thuốc lá khỏi bậc cửa trước."},{"hanzi":"Discarded cigarette butts contribute to urban litter and can release harmful substances into rivers and coastal waters.","pinyin":"","meaning":"Những tàn thuốc lá bị vứt bừa bãi làm gia tăng rác thải đô thị và có thể thải các chất độc hại vào sông ngòi cũng như vùng nước ven biển."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_84_2', 'en-b2-84', 'Cách dùng “specifically” (adv.) — riêng biệt; đặc biệt, chuyên dụng', 'specifically designed for  ·  specifically mention  ·  more specifically', 'Dùng "specifically for" để nhấn mạnh mục đích chuyên dụng; dùng "more specifically" khi muốn nói cụ thể hơn.', 'Họ từ (Word Family): specific (adj.), specify (v.), specification (n.) | Đồng nghĩa: particularly, expressly · Trái nghĩa: generally', '[{"hanzi":"I bought this small brush specifically for cleaning bottles.","pinyin":"","meaning":"Tôi mua chiếc bàn chải nhỏ này chuyên dùng để cọ bình sữa."},{"hanzi":"Public libraries should offer programmes specifically designed to help older adults develop essential digital skills.","pinyin":"","meaning":"Các thư viện công cộng nên cung cấp các chương trình được thiết kế riêng để giúp người lớn tuổi phát triển các kỹ năng số thiết yếu."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_84_3', 'en-b2-84', 'Cách dùng “garment” (n.) — một món đồ trang phục, quần áo', 'a woollen garment  ·  the garment industry  ·  garment workers', 'Đây là danh từ đếm được chỉ một món quần áo cụ thể; trong khi clothing thường là danh từ không đếm được.', NULL, '[{"hanzi":"This delicate garment needs to be washed by hand.","pinyin":"","meaning":"Món đồ mỏng manh này cần phải được giặt bằng tay."},{"hanzi":"Improving working conditions in the garment industry requires cooperation between manufacturers, retailers, and national governments.","pinyin":"","meaning":"Việc cải thiện điều kiện làm việc trong ngành may mặc đòi hỏi sự hợp tác giữa các nhà sản xuất, nhà bán lẻ và chính phủ các nước."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_84_4', 'en-b2-84', 'Cách dùng “considerably” (adv.) — đáng kể; nhiều', 'considerably higher  ·  vary considerably  ·  reduce considerably', 'Thường dùng để bổ nghĩa cho tính từ so sánh hơn hoặc các động từ chỉ sự thay đổi, diễn tả mức độ lớn.', 'Họ từ (Word Family): considerable (adj.) | Đồng nghĩa: significantly, substantially · Trái nghĩa: slightly', '[{"hanzi":"Our new flat is considerably warmer than the old one.","pinyin":"","meaning":"Căn hộ mới của chúng tôi ấm hơn hẳn so với căn cũ."},{"hanzi":"Improved public transport could considerably reduce traffic congestion and air pollution in major cities.","pinyin":"","meaning":"Việc cải thiện giao thông công cộng có thể làm giảm đáng kể tình trạng tắc nghẽn giao thông và ô nhiễm không khí ở các thành phố lớn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_84_1', 'en-b2-84', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_84_1_1', 'ten_b2_84_1', 'stale', 'This bread is stale, so I''ll use it for breadcrumbs.', 'This bread is stale, so I''ll use it for breadcrumbs.', '/steɪl/', 'Ổ bánh mì này cũ và khô rồi, tôi sẽ dùng nó làm vụn bánh mì.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_84_1_2', 'ten_b2_84_1', 'garment', 'This delicate garment needs to be washed by hand.', 'This delicate garment needs to be washed by hand.', '/ˈɡɑːrmənt/', 'Món đồ mỏng manh này cần phải được giặt bằng tay.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_84_1_3', 'ten_b2_84_1', 'delicate', 'Please wrap these delicate glass bowls in soft paper.', 'Please wrap these delicate glass bowls in soft paper.', '/ˈdelɪkət/', 'Xin hãy bọc những chiếc bát thủy tinh dễ vỡ này bằng giấy mềm.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_84_1_4', 'ten_b2_84_1', 'swallow', 'Please swallow your food before you start talking again.', 'Please swallow your food before you start talking again.', '/ˈswɑːloʊ/', 'Làm ơn hãy nuốt thức ăn trước khi bạn bắt đầu nói chuyện lại.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_84_1_5', 'ten_b2_84_1', 'specifically', 'I bought this small brush specifically for cleaning bottles.', 'I bought this small brush specifically for cleaning bottles.', '/spəˈsɪfɪkli/', 'Tôi mua chiếc bàn chải nhỏ này chuyên dùng để cọ bình sữa.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_84_1_6', 'ten_b2_84_1', 'butt', 'He swept a cigarette butt off the front step.', 'He swept a cigarette butt off the front step.', '/bʌt/', 'Anh ấy quét một mẩu tàn thuốc lá khỏi bậc cửa trước.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_84_1_7', 'ten_b2_84_1', 'spin', 'The wheel kept spinning after I lifted the bicycle.', 'The wheel kept spinning after I lifted the bicycle.', '/spɪn/', 'Bánh xe vẫn tiếp tục quay sau khi tôi nhấc chiếc xe đạp lên.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_84_1_8', 'ten_b2_84_1', 'noticeable', 'There is a noticeable scratch on my new table.', 'There is a noticeable scratch on my new table.', '/ˈnoʊtɪsəbəl/', 'Có một vết xước rõ rệt trên chiếc bàn mới của tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_84_1_1', 'en-b2-84', 'ten_b2_84_1', 'listening', 'listening', 'This bread is stale, so I''ll use it for breadcrumbs.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Xin hãy bọc những chiếc bát thủy tinh dễ vỡ này bằng giấy mềm.","Anh ấy quét một mẩu tàn thuốc lá khỏi bậc cửa trước.","Ổ bánh mì này cũ và khô rồi, tôi sẽ dùng nó làm vụn bánh mì.","Căn bếp khá sạch sẽ, nhưng sàn nhà cần phải được quét dọn."]'::jsonb, 2, 'This bread is stale, so I''ll use it for breadcrumbs. → Ổ bánh mì này cũ và khô rồi, tôi sẽ dùng nó làm vụn bánh mì.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_84_1_2', 'en-b2-84', 'ten_b2_84_1', 'listening', 'listening', 'This delicate garment needs to be washed by hand.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Dùng lòng bàn tay nhẹ nhàng ép phẳng khối bột.","Món đồ mỏng manh này cần phải được giặt bằng tay.","Bạn có thể tháo mũ trùm đầu ra khi trời tạnh mưa.","Hôm qua tay áo tôi đã bị vướng vào một cành cây sắc nhọn làm rách."]'::jsonb, 1, 'This delicate garment needs to be washed by hand. → Món đồ mỏng manh này cần phải được giặt bằng tay.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_84_1_3', 'en-b2-84', 'ten_b2_84_1', 'listening', 'listening', 'Please wrap these delicate glass bowls in soft paper.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Xin hãy bọc những chiếc bát thủy tinh dễ vỡ này bằng giấy mềm.","Giá vé xe buýt thay đổi tùy thuộc vào quãng đường bạn đi.","Nước mắt làm mờ đi tầm nhìn của tôi khi đoàn tàu từ từ lăn bánh rời đi.","Anh ấy quét một mẩu tàn thuốc lá khỏi bậc cửa trước."]'::jsonb, 0, 'Please wrap these delicate glass bowls in soft paper. → Xin hãy bọc những chiếc bát thủy tinh dễ vỡ này bằng giấy mềm.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_84_2', 'en-b2-84', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_84_2_1', 'ten_b2_84_2', 'stale', 'Teaching methods can become stale when educators lack opportunities to exchange ideas and develop new skills.', 'Teaching methods can become stale when educators lack opportunities to exchange ideas and develop new skills.', '/steɪl/', 'Phương pháp giảng dạy có thể trở nên nhàm chán khi các nhà giáo dục thiếu cơ hội trao đổi ý tưởng và phát triển kỹ năng mới.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_84_2_2', 'ten_b2_84_2', 'garment', 'Improving working conditions in the garment industry requires cooperation between manufacturers, retailers, and national governments.', 'Improving working conditions in the garment industry requires cooperation between manufacturers, retailers, and national governments.', '/ˈɡɑːrmənt/', 'Việc cải thiện điều kiện làm việc trong ngành may mặc đòi hỏi sự hợp tác giữa các nhà sản xuất, nhà bán lẻ và chính phủ các nước.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_84_2_3', 'ten_b2_84_2', 'delicate', 'Tourism in coastal regions must be carefully managed to protect delicate ecosystems from lasting damage.', 'Tourism in coastal regions must be carefully managed to protect delicate ecosystems from lasting damage.', '/ˈdelɪkət/', 'Du lịch ở các vùng ven biển phải được quản lý cẩn thận để bảo vệ các hệ sinh thái mỏng manh khỏi tổn hại lâu dài.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_84_2_4', 'ten_b2_84_2', 'swallow', 'Consumers should not simply swallow advertising claims without examining the evidence behind promises of better health.', 'Consumers should not simply swallow advertising claims without examining the evidence behind promises of better health.', '/ˈswɑːloʊ/', 'Người tiêu dùng không nên dễ dãi tin ngay vào các tuyên bố quảng cáo mà không xem xét bằng chứng đứng sau những lời hứa hẹn về sức khỏe tốt hơn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_84_2_5', 'ten_b2_84_2', 'specifically', 'Public libraries should offer programmes specifically designed to help older adults develop essential digital skills.', 'Public libraries should offer programmes specifically designed to help older adults develop essential digital skills.', '/spəˈsɪfɪkli/', 'Các thư viện công cộng nên cung cấp các chương trình được thiết kế riêng để giúp người lớn tuổi phát triển các kỹ năng số thiết yếu.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_84_2_6', 'ten_b2_84_2', 'butt', 'Discarded cigarette butts contribute to urban litter and can release harmful substances into rivers and coastal waters.', 'Discarded cigarette butts contribute to urban litter and can release harmful substances into rivers and coastal waters.', '/bʌt/', 'Những tàn thuốc lá bị vứt bừa bãi làm gia tăng rác thải đô thị và có thể thải các chất độc hại vào sông ngòi cũng như vùng nước ven biển.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_84_2_1', 'en-b2-84', 'ten_b2_84_2', 'listening', 'listening', 'Teaching methods can become stale when educators lack opportunities to exchange ideas and develop new skills.', NULL, 'Trong câu vừa nghe, từ “stale” mang nghĩa nào sau đây?', '["chỉ rõ; nêu cụ thể; quy định rõ","thỉnh thoảng; đôi khi","bàn đạp; chân vịt","không còn tươi, ôi thiu (đặc biệt là bánh mì hoặc không khí)"]'::jsonb, 3, '“stale” (/steɪl/): không còn tươi, ôi thiu (đặc biệt là bánh mì hoặc không khí). Câu đầy đủ: Teaching methods can become stale when educators lack opportunities to exchange ideas and develop new skills.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_84_2_2', 'en-b2-84', 'ten_b2_84_2', 'listening', 'listening', 'Improving working conditions in the garment industry requires cooperation between manufacturers, retailers, and national governments.', NULL, 'Trong câu vừa nghe, từ “garment” mang nghĩa nào sau đây?', '["làm việc tự do; thuộc nghề tự do","một món đồ trang phục, quần áo","cố vấn; chuyên gia tư vấn","sự phong phú; tính đa dạng"]'::jsonb, 1, '“garment” (/ˈɡɑːrmənt/): một món đồ trang phục, quần áo. Câu đầy đủ: Improving working conditions in the garment industry requires cooperation between manufacturers, retailers, and national governments.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
