INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_84_1', 'en-b2-84', NULL, 'comprehensive_test', 'listening', 'stale', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chất bột đường; cacbohydrat","không còn tươi, ôi thiu (đặc biệt là bánh mì hoặc không khí)","làm cho ngọt; thêm đường/mật cho ngọt","vẻ duyên dáng; sự thanh lịch; sự uyển chuyển"]'::jsonb, 1, 'stale (/steɪl/) → không còn tươi, ôi thiu (đặc biệt là bánh mì hoặc không khí); lỗi thời, nhàm chán, kém phong phú do dùng lặp lại', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_84_2', 'en-b2-84', NULL, 'comprehensive_test', 'listening', 'This delicate garment needs to be washed by hand.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Căn bếp khá sạch sẽ, nhưng sàn nhà cần phải được quét dọn.","Nước mắt làm mờ đi tầm nhìn của tôi khi đoàn tàu từ từ lăn bánh rời đi.","Hôm qua tay áo tôi đã bị vướng vào một cành cây sắc nhọn làm rách.","Món đồ mỏng manh này cần phải được giặt bằng tay."]'::jsonb, 3, 'This delicate garment needs to be washed by hand. → Món đồ mỏng manh này cần phải được giặt bằng tay.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_84_3', 'en-b2-84', NULL, 'comprehensive_test', 'listening', 'delicate', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thúc đẩy; khích lệ; kích thích","sưng tấy, sưng phồng (do chấn thương hoặc bệnh tật)","mỏng manh, dễ vỡ, dễ hư hỏng","ngôn ngữ học"]'::jsonb, 2, 'delicate (/ˈdelɪkət/) → mỏng manh, dễ vỡ, dễ hư hỏng; nhạy cảm, tinh tế, đòi hỏi sự cẩn trọng để tránh rắc rối; tinh vi, nhẹ nhàng về mặt hình thức, hương vị hoặc mùi thơm', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_84_4', 'en-b2-84', NULL, 'comprehensive_test', 'listening', 'Please swallow your food before you start talking again.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Làm ơn hãy nuốt thức ăn trước khi bạn bắt đầu nói chuyện lại.","Chúng tôi đã mua những quả đào tươi với giá năm mươi xu một quả.","Một chồng đĩa sạch được đặt cạnh bồn rửa chén.","Căn hộ mới của chúng tôi ấm hơn hẳn so với căn cũ."]'::jsonb, 0, 'Please swallow your food before you start talking again. → Làm ơn hãy nuốt thức ăn trước khi bạn bắt đầu nói chuyện lại.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_84_5', 'en-b2-84', NULL, 'comprehensive_test', 'listening', 'specifically', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["giữ lại; duy trì","tấm chớp che cửa; cửa chớp","riêng biệt; đặc biệt, chuyên dụng","cái nhìn thoáng qua; sự nhìn lướt"]'::jsonb, 2, 'specifically (/spəˈsɪfɪkli/) → riêng biệt; đặc biệt, chuyên dụng; rõ ràng; cụ thể; cụ thể là; nói rõ hơn là', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_84_6', 'en-b2-84', NULL, 'comprehensive_test', 'listening', 'He swept a cigarette butt off the front step.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Anh ấy quét một mẩu tàn thuốc lá khỏi bậc cửa trước.","Món đồ mỏng manh này cần phải được giặt bằng tay.","Nhân viên bưu điện đã để một bưu phẩm ngay trước cửa nhà chúng tôi.","Con mèo đang chăm chú nhìn một con chim ở bên ngoài cửa sổ."]'::jsonb, 0, 'He swept a cigarette butt off the front step. → Anh ấy quét một mẩu tàn thuốc lá khỏi bậc cửa trước.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_84_7', 'en-b2-84', NULL, 'comprehensive_test', 'listening', 'spin', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tương đối; so sánh ra","quay; xoay tròn","công tác điều dưỡng; nghề điều dưỡng; sự chăm sóc bệnh nhân","sự bốc đồng; sự thôi thúc nhất thời"]'::jsonb, 1, 'spin (/spɪn/) → quay; xoay tròn; kéo sợi; nhả tơ; sự quay vòng; cách diễn giải theo chiều hướng có lợi', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_84_8', 'en-b2-84', NULL, 'comprehensive_test', 'listening', 'There is a noticeable scratch on my new table.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Căn hộ mới của chúng tôi ấm hơn hẳn so với căn cũ.","Chiếc áo len lông cừu của tôi đã bị co lại sau khi tôi giặt không đúng cách.","Bánh xe vẫn tiếp tục quay sau khi tôi nhấc chiếc xe đạp lên.","Có một vết xước rõ rệt trên chiếc bàn mới của tôi."]'::jsonb, 3, 'There is a noticeable scratch on my new table. → Có một vết xước rõ rệt trên chiếc bàn mới của tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_84_9', 'en-b2-84', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “for one particular purpose, person, or group”?', '["shrink","flatten","garment","specifically"]'::jsonb, 3, 'specifically (/spəˈsɪfɪkli/) → riêng biệt; đặc biệt, chuyên dụng', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
