INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_84_18', 'en-b2-84', NULL, 'comprehensive_test', 'reading', NULL, 'Teaching methods can become stale when educators lack opportunities to exchange ideas and develop new skills.', 'Dựa vào câu trên, từ “stale” có nghĩa phù hợp nhất là gì?', '["sự lặp lại; sự luyện tập lặp đi lặp lại","không còn tươi, ôi thiu (đặc biệt là bánh mì hoặc không khí)","sự điều hướng; sự định vị và dẫn đường","hệ thống chiếu sáng; ánh sáng"]'::jsonb, 1, 'stale: không còn tươi, ôi thiu (đặc biệt là bánh mì hoặc không khí); lỗi thời, nhàm chán, kém phong phú do dùng lặp lại. Dịch cả câu: Phương pháp giảng dạy có thể trở nên nhàm chán khi các nhà giáo dục thiếu cơ hội trao đổi ý tưởng và phát triển kỹ năng mới.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_84_19', 'en-b2-84', NULL, 'comprehensive_test', 'reading', NULL, 'Improving working conditions in the garment industry requires cooperation between manufacturers, retailers, and national governments.', 'Dựa vào câu trên, từ “garment” có nghĩa phù hợp nhất là gì?', '["một món đồ trang phục, quần áo","máy thu thanh/truyền hình; thiết bị thu tín hiệu","hợp tác; cộng tác","sự cám dỗ; điều cám dỗ"]'::jsonb, 0, 'garment: một món đồ trang phục, quần áo. Dịch cả câu: Việc cải thiện điều kiện làm việc trong ngành may mặc đòi hỏi sự hợp tác giữa các nhà sản xuất, nhà bán lẻ và chính phủ các nước.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_84_20', 'en-b2-84', NULL, 'comprehensive_test', 'reading', NULL, 'Tourism in coastal regions must be carefully managed to protect delicate ecosystems from lasting damage.', 'Dựa vào câu trên, từ “delicate” có nghĩa phù hợp nhất là gì?', '["nhúng; chấm","không đủ; không đáp ứng đủ","vô hạn; vô tận","mỏng manh, dễ vỡ, dễ hư hỏng"]'::jsonb, 3, 'delicate: mỏng manh, dễ vỡ, dễ hư hỏng; nhạy cảm, tinh tế, đòi hỏi sự cẩn trọng để tránh rắc rối; tinh vi, nhẹ nhàng về mặt hình thức, hương vị hoặc mùi thơm. Dịch cả câu: Du lịch ở các vùng ven biển phải được quản lý cẩn thận để bảo vệ các hệ sinh thái mỏng manh khỏi tổn hại lâu dài.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_84_21', 'en-b2-84', NULL, 'comprehensive_test', 'reading', NULL, 'Consumers should not simply swallow advertising claims without examining the evidence behind promises of better health.', 'Dựa vào câu trên, từ “swallow” có nghĩa phù hợp nhất là gì?', '["làm nản lòng; khiến buồn bã","nghe chừng; hình như; có vẻ như","nuốt","cơn giận; tính khí; tâm trạng cáu kỉnh"]'::jsonb, 2, 'swallow: nuốt; tin sái cổ; miễn cưỡng chấp nhận; chim nhạn; chim én. Dịch cả câu: Người tiêu dùng không nên dễ dãi tin ngay vào các tuyên bố quảng cáo mà không xem xét bằng chứng đứng sau những lời hứa hẹn về sức khỏe tốt hơn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_84_22', 'en-b2-84', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “chọc; thọc”', '["poke","chairman","somewhat","regional"]'::jsonb, 0, 'chọc; thọc → poke (/poʊk/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_84_23', 'en-b2-84', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tháo ra; tách rời”', '["imaginary","sane","organic","detach"]'::jsonb, 3, 'tháo ra; tách rời → detach (/dɪˈtætʃ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_84_24', 'en-b2-84', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nhìn chằm chằm; chăm chú”', '["bait","stare","long-term","stabilize"]'::jsonb, 1, 'nhìn chằm chằm; chăm chú → stare (/ster/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-85', 'en', 'Bài 85: Đời sống hằng ngày (12) - CEFR B2', 'CEFR B2', 'B2 · Đời sống', '26 từ vựng Tiếng Anh CEFR B2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4085, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_valid', 'en-b2-85', 'valid', '/ˈvælɪd/', 'B2', 'có hiệu lực; hợp lệ, được công nhận chính thức; có cơ sở; hợp lý, đúng đắn', 'adj.', 'validity (n.), validate (v.), validation (n.), invalid (adj.)', 'Đồng nghĩa: acceptable, justified · Trái nghĩa: invalid', 'valid for đi với khoảng thời gian hiệu lực; valid until đi với mốc thời gian hết hạn.', 'Your ticket is still valid for the return journey.', NULL, 'Vé của bạn vẫn có hiệu lực cho chuyến đi khứ hồi.', '{"wordId":"valid","ukIpa":"/ˈvælɪd/","usIpa":"/ˈvælɪd/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"officially acceptable and able to be used","vi":"có hiệu lực; hợp lệ, được công nhận chính thức"},{"pos":"adj.","en":"based on sound reasons or evidence","vi":"có cơ sở; hợp lý, đúng đắn"}],"examples":[{"en":"Your ticket is still valid for the return journey.","vi":"Vé của bạn vẫn có hiệu lực cho chuyến đi khứ hồi.","audioKind":"ex"},{"en":"Although online learning offers flexibility, students have valid concerns about limited interaction with their teachers.","vi":"Mặc dù học trực tuyến mang lại sự linh hoạt, học sinh vẫn có những lo lắng chính đáng về việc tương tác hạn chế với giáo viên.","audioKind":"ex2"}],"collocations":[{"en":"valid ticket","vi":"vé hợp lệ"},{"en":"valid reason","vi":"lý do chính đáng"},{"en":"valid for","vi":"có hiệu lực đến / áp dụng cho"},{"en":"valid concern","vi":"mối lo ngại hợp lý"}],"wordFamily":["validity (n.)","validate (v.)","validation (n.)","invalid (adj.)"],"synonyms":["acceptable","justified"],"antonyms":["invalid"],"tipVi":"valid for đi với khoảng thời gian hiệu lực; valid until đi với mốc thời gian hết hạn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thread', 'en-b2-85', 'thread', '/θred/', 'B2', 'chỉ; sợi chỉ; mạch lạc (ý tưởng); chuỗi thảo luận trực tuyến; xâu chỉ; luồn qua', 'n.', NULL, NULL, 'Cụm từ lose the thread dùng để chỉ việc người nói hoặc người đọc bị mất mạch suy nghĩ, không theo kịp nội dung.', 'I need some blue thread to mend this shirt.', NULL, 'Tôi cần một ít chỉ xanh để vá cái áo sơ mi này.', '{"wordId":"thread","ukIpa":"/θred/","usIpa":"/θred/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"a long, thin fibre used for sewing","vi":"chỉ; sợi chỉ"},{"pos":"n.","en":"a connected sequence of ideas or online messages","vi":"mạch lạc (ý tưởng); chuỗi thảo luận trực tuyến"},{"pos":"v.","en":"to pass thread or another thin object through an opening","vi":"xâu chỉ; luồn qua"}],"examples":[{"en":"I need some blue thread to mend this shirt.","vi":"Tôi cần một ít chỉ xanh để vá cái áo sơ mi này.","audioKind":"ex"},{"en":"Clear transitions help readers follow the thread of an argument in a complex academic essay.","vi":"Sự liên kết mạch lạc giúp người đọc theo dõi được mạch lập luận trong một bài viết học thuật phức tạp.","audioKind":"ex2"}],"collocations":[{"en":"sewing thread","vi":"chỉ may"},{"en":"thread a needle","vi":"xâu kim"},{"en":"lose the thread","vi":"mất mạch suy nghĩ"},{"en":"discussion thread","vi":"chuỗi thảo luận"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ lose the thread dùng để chỉ việc người nói hoặc người đọc bị mất mạch suy nghĩ, không theo kịp nội dung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_collide', 'en-b2-85', 'collide', '/kəˈlaɪd/', 'B2', 'va chạm; đâm vào nhau; xung đột; trái ngược nhau', 'v.', 'collision (n.)', 'Đồng nghĩa: clash', 'Thường là động từ không túc từ; va chạm với vật gì dùng with.', 'Two shopping trolleys collided near the busy supermarket entrance.', NULL, 'Hai chiếc xe đẩy hàng va vào nhau gần lối vào siêu thị đông đúc.', '{"wordId":"collide","ukIpa":"/kəˈlaɪd/","usIpa":"/kəˈlaɪd/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to crash into something or each other","vi":"va chạm; đâm vào nhau"},{"pos":"v.","en":"to strongly disagree or be impossible to combine","vi":"xung đột; trái ngược nhau"}],"examples":[{"en":"Two shopping trolleys collided near the busy supermarket entrance.","vi":"Hai chiếc xe đẩy hàng va vào nhau gần lối vào siêu thị đông đúc.","audioKind":"ex"},{"en":"Economic ambitions often collide with environmental priorities when governments consider approving major infrastructure projects.","vi":"Tham vọng kinh tế thường xung đột với các ưu tiên về môi trường khi các chính phủ cân nhắc phê duyệt các dự án cơ sở hạ tầng lớn.","audioKind":"ex2"}],"collocations":[{"en":"collide with","vi":"va chạm với"},{"en":"collide head-on","vi":"va đâm trực diện"},{"en":"colliding interests","vi":"lợi ích xung đột"}],"wordFamily":["collision (n.)"],"synonyms":["clash"],"antonyms":[],"tipVi":"Thường là động từ không túc từ; va chạm với vật gì dùng with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_satisfactory', 'en-b2-85', 'satisfactory', '/ˌsætɪsˈfæktəri/', 'B2', 'thỏa đáng; đạt yêu cầu; đủ tiêu chuẩn', 'adj.', 'satisfy (v.), satisfaction (n.), satisfactorily (adv.), unsatisfactory (adj.)', 'Đồng nghĩa: acceptable, adequate · Trái nghĩa: unsatisfactory, inadequate', 'Nhấn mạnh việc đáp ứng đúng yêu cầu, không nhất thiết phải xuất sắc; cảm giác hài lòng của con người dùng satisfied.', 'The mechanic confirmed that the brakes were satisfactory.', NULL, 'Thợ máy xác nhận rằng hệ thống phanh đã đạt yêu cầu.', '{"wordId":"satisfactory","ukIpa":"/ˌsætɪsˈfæktəri/","usIpa":"/ˌsætɪsˈfæktəri/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Good enough to meet a particular need or standard","vi":"thỏa đáng; đạt yêu cầu; đủ tiêu chuẩn"}],"examples":[{"en":"The mechanic confirmed that the brakes were satisfactory.","vi":"Thợ máy xác nhận rằng hệ thống phanh đã đạt yêu cầu.","audioKind":"ex"},{"en":"Providing satisfactory public transport is essential if cities want residents to rely less on private cars.","vi":"Việc cung cấp dịch vụ giao thông công cộng thỏa đáng là điều cốt yếu nếu các thành phố muốn người dân giảm bớt sự phụ thuộc vào ô tô cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"satisfactory results","vi":"kết quả thỏa đáng"},{"en":"satisfactory explanation","vi":"lời giải thích thỏa đáng"},{"en":"satisfactory progress","vi":"tiến triển đạt yêu cầu"}],"wordFamily":["satisfy (v.)","satisfaction (n.)","satisfactorily (adv.)","unsatisfactory (adj.)"],"synonyms":["acceptable","adequate"],"antonyms":["unsatisfactory","inadequate"],"tipVi":"Nhấn mạnh việc đáp ứng đúng yêu cầu, không nhất thiết phải xuất sắc; cảm giác hài lòng của con người dùng satisfied.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rapidly', 'en-b2-85', 'rapidly', '/ˈræpɪdli/', 'B2', 'nhanh chóng; tốc độ cao', 'adv.', 'rapid (adj.), rapidity (n.)', 'Đồng nghĩa: quickly, swiftly · Trái nghĩa: slowly', 'Thể hiện tốc độ nhanh, không đồng nghĩa với immediately (ngay lập tức).', 'Dark clouds spread rapidly across the sky before lunch.', NULL, 'Những đám mây đen nhanh chóng phủ kín bầu trời trước bữa trưa.', '{"wordId":"rapidly","ukIpa":"/ˈræpɪdli/","usIpa":"/ˈræpɪdli/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"At a fast speed or within a short time.","vi":"nhanh chóng; tốc độ cao"}],"examples":[{"en":"Dark clouds spread rapidly across the sky before lunch.","vi":"Những đám mây đen nhanh chóng phủ kín bầu trời trước bữa trưa.","audioKind":"ex"},{"en":"As urban populations grow rapidly, public transport systems must expand to meet increasing demand.","vi":"Khi dân số đô thị tăng nhanh, hệ thống giao thông công cộng phải được mở rộng để đáp ứng nhu cầu ngày càng tăng.","audioKind":"ex2"}],"collocations":[{"en":"grow rapidly","vi":"tăng trưởng nhanh chóng"},{"en":"change rapidly","vi":"thay đổi nhanh chóng"},{"en":"spread rapidly","vi":"lan rộng nhanh chóng"}],"wordFamily":["rapid (adj.)","rapidity (n.)"],"synonyms":["quickly","swiftly"],"antonyms":["slowly"],"tipVi":"Thể hiện tốc độ nhanh, không đồng nghĩa với immediately (ngay lập tức).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_beware', 'en-b2-85', 'beware', '/bɪˈwer/', 'B2', 'cẩn thận; đề phòng, cảnh giác', 'v.', NULL, 'Đồng nghĩa: watch out', 'Thường dùng để cảnh báo: beware of＋danh từ; không dùng ở thì quá khứ thông thường.', 'Beware of slippery rocks when you cross the stream.', NULL, 'Hãy cẩn thận với những tảng đá trơn trượt khi bạn băng qua suối.', '{"wordId":"beware","ukIpa":"/bɪˈweə/","usIpa":"/bɪˈwer/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to be careful about a possible danger or problem","vi":"cẩn thận; đề phòng, cảnh giác"}],"examples":[{"en":"Beware of slippery rocks when you cross the stream.","vi":"Hãy cẩn thận với những tảng đá trơn trượt khi bạn băng qua suối.","audioKind":"ex"},{"en":"Consumers should beware of online offers that promise expensive products at unusually low prices.","vi":"Người tiêu dùng nên đề phòng các ưu đãi trực tuyến hứa hẹn bán sản phẩm đắt tiền với giá thấp bất thường.","audioKind":"ex2"}],"collocations":[{"en":"beware of scams","vi":"đề phòng lừa đảo"},{"en":"beware of imitations","vi":"cảnh giác hàng giả"},{"en":"let the buyer beware","vi":"người mua phải tự cẩn trọng"}],"wordFamily":[],"synonyms":["watch out"],"antonyms":[],"tipVi":"Thường dùng để cảnh báo: beware of＋danh từ; không dùng ở thì quá khứ thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_desirable', 'en-b2-85', 'desirable', '/dɪˈzaɪrəbl/', 'B2', 'đáng ao ước; đáng giá, thích hợp', 'adj.', 'desire (n.), desire (v.), desirability (n.), undesirable (adj.)', 'Đồng nghĩa: attractive, appealing · Trái nghĩa: undesirable', 'desirable chỉ cái đáng sở hữu; desirous chỉ sự khao khát.', 'A balcony makes this small flat much more desirable.', NULL, 'Cái ban công khiến cho căn hộ nhỏ này trở nên đáng sống hơn rất nhiều.', '{"wordId":"desirable","ukIpa":"/dɪˈzaɪərəbl/","usIpa":"/dɪˈzaɪrəbl/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Worth having or doing because it offers benefits.","vi":"đáng ao ước; đáng giá, thích hợp"}],"examples":[{"en":"A balcony makes this small flat much more desirable.","vi":"Cái ban công khiến cho căn hộ nhỏ này trở nên đáng sống hơn rất nhiều.","audioKind":"ex"},{"en":"Although economic growth is desirable, governments should also consider its effects on public health and the environment.","vi":"Mặc dù tăng trưởng kinh tế là điều đáng mong muốn, chính phủ cũng nên cân nhắc tác động của nó đối với sức khỏe cộng đồng và môi trường.","audioKind":"ex2"}],"collocations":[{"en":"highly desirable","vi":"rất đáng mơ ước"},{"en":"desirable outcome","vi":"kết quả mong muốn"},{"en":"desirable qualities","vi":"những phẩm chất đáng quý"}],"wordFamily":["desire (n.)","desire (v.)","desirability (n.)","undesirable (adj.)"],"synonyms":["attractive","appealing"],"antonyms":["undesirable"],"tipVi":"desirable chỉ cái đáng sở hữu; desirous chỉ sự khao khát.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_brighten', 'en-b2-85', 'brighten', '/ˈbraɪtən/', 'B2', 'làm sáng lên; làm rực rỡ hơn; làm vui vẻ hơn; làm phấn chấn lên', 'v.', 'bright (adj.), brightly (adv.), brightness (n.)', 'Đồng nghĩa: lighten, illuminate · Trái nghĩa: darken', 'Có thể dùng ngoại động từ lẫn nội động từ; brighten up cũng dùng để chỉ tâm trạng tốt lên.', 'These yellow curtains really brighten our small kitchen.', NULL, 'Bộ rèm vàng này thực sự làm cho căn bếp nhỏ của chúng tôi bừng sáng.', '{"wordId":"brighten","ukIpa":"/ˈbraɪtən/","usIpa":"/ˈbraɪtən/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To become lighter or make something lighter or more colourful.","vi":"làm sáng lên; làm rực rỡ hơn"},{"pos":"v.","en":"To become happier or make someone feel happier.","vi":"làm vui vẻ hơn; làm phấn chấn lên"}],"examples":[{"en":"These yellow curtains really brighten our small kitchen.","vi":"Bộ rèm vàng này thực sự làm cho căn bếp nhỏ của chúng tôi bừng sáng.","audioKind":"ex"},{"en":"Planting colourful flowers can brighten neglected public spaces and encourage residents to take greater pride in their neighbourhood.","vi":"Việc trồng những khóm hoa rực rỡ có thể làm sinh động các không gian công cộng bị bỏ quên và khuyến khích người dân thêm tự hào về khu0 phố của mình.","audioKind":"ex2"}],"collocations":[{"en":"brighten a room","vi":"làm sáng phòng"},{"en":"brighten someone''s day","vi":"làm ai đó vui vẻ cả ngày"},{"en":"brighten up","vi":"làm sáng lên; phấn chấn lên"}],"wordFamily":["bright (adj.)","brightly (adv.)","brightness (n.)"],"synonyms":["lighten","illuminate"],"antonyms":["darken"],"tipVi":"Có thể dùng ngoại động từ lẫn nội động từ; brighten up cũng dùng để chỉ tâm trạng tốt lên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_whip', 'en-b2-85', 'whip', '/wɪp/', 'B2', 'cây roi; quất roi; di chuyển đột ngột; đánh (kem, trứng); khuấy đều', 'n.', 'whipped (adj.)', 'Đồng nghĩa: lash', 'whip cream là đánh kem; gấp đôi chữ p khi thêm -ed hoặc -ing.', 'An old leather whip hung beside the stable door.', NULL, 'Một chiếc roi da cũ treo cạnh cửa chuồng ngựa.', '{"wordId":"whip","ukIpa":"/wɪp/","usIpa":"/wɪp/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A flexible strip attached to a handle, used for striking.","vi":"cây roi"},{"pos":"v.","en":"To strike with a whip or move something suddenly.","vi":"quất roi; di chuyển đột ngột"},{"pos":"v.","en":"To beat food quickly to make it light and thick.","vi":"đánh (kem, trứng); khuấy đều"}],"examples":[{"en":"An old leather whip hung beside the stable door.","vi":"Một chiếc roi da cũ treo cạnh cửa chuồng ngựa.","audioKind":"ex"},{"en":"During practical lessons, culinary students learn to whip cream and prepare healthier alternatives to commercial desserts.","vi":"Trong các giờ học thực hành, sinh viên ngành ẩm thực học cách đánh bông kem và chuẩn bị các món thay thế tốt cho sức khỏe hơn so với tráng miệng thương mại.","audioKind":"ex2"}],"collocations":[{"en":"a leather whip","vi":"roi da"},{"en":"whip cream","vi":"đánh kem"},{"en":"whip out","vi":"rút nhanh ra"},{"en":"whip up a meal","vi":"nấu nhanh một bữa ăn"}],"wordFamily":["whipped (adj.)"],"synonyms":["lash"],"antonyms":[],"tipVi":"whip cream là đánh kem; gấp đôi chữ p khi thêm -ed hoặc -ing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lime', 'en-b2-85', 'lime', '/laɪm/', 'B2', 'quả chanh xanh; quả thanh yên; vôi; màu vàng lục; màu xanh nõn chuối', 'n.', NULL, NULL, 'Nghĩa quả chanh là danh từ đếm được, nghĩa vôi là không đếm được; lemon là quả chanh vàng.', 'She squeezed a lime over the warm rice.', NULL, 'Cô ấy vắt một quả chanh xanh lên đĩa cơm ấm.', '{"wordId":"lime","ukIpa":"/laɪm/","usIpa":"/laɪm/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A small citrus fruit with green skin and sour juice.","vi":"quả chanh xanh; quả thanh yên"},{"pos":"n.","en":"A white calcium compound used in building and soil treatment.","vi":"vôi"},{"pos":"n.","en":"A bright, pale colour between green and yellow.","vi":"màu vàng lục; màu xanh nõn chuối"}],"examples":[{"en":"She squeezed a lime over the warm rice.","vi":"Cô ấy vắt một quả chanh xanh lên đĩa cơm ấm.","audioKind":"ex"},{"en":"Farmers may apply lime to acidic soils to improve growing conditions and increase crop productivity.","vi":"Nông dân có thể bón vôi cho đất chua để cải thiện điều kiện sinh trưởng và tăng năng suất cây trồng.","audioKind":"ex2"}],"collocations":[{"en":"lime juice","vi":"nước cốt chanh xanh"},{"en":"a slice of lime","vi":"một lát chanh xanh"},{"en":"agricultural lime","vi":"vôi nông nghiệp"},{"en":"lime green","vi":"màu xanh nõn chuối"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa quả chanh là danh từ đếm được, nghĩa vôi là không đếm được; lemon là quả chanh vàng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sufficiently', 'en-b2-85', 'sufficiently', '/səˈfɪʃəntli/', 'B2', 'đủ; đầy đủ; thích đáng', 'adv.', 'sufficient (adj.), sufficiency (n.), insufficient (adj.), insufficiently (adv.)', 'Đồng nghĩa: adequately, enough · Trái nghĩa: insufficiently, inadequately', 'Bổ nghĩa cho tính từ thì đứng trước tính từ; còn enough thì đứng sau.', 'The soup had cooled sufficiently for us to eat.', NULL, 'Món súp đã nguội vừa đủ để chúng tôi ăn.', '{"wordId":"sufficiently","ukIpa":"/səˈfɪʃəntli/","usIpa":"/səˈfɪʃəntli/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"to the degree needed for a particular purpose","vi":"đủ; đầy đủ; thích đáng"}],"examples":[{"en":"The soup had cooled sufficiently for us to eat.","vi":"Món súp đã nguội vừa đủ để chúng tôi ăn.","audioKind":"ex"},{"en":"Public transport must be sufficiently reliable to persuade commuters to leave their cars at home.","vi":"Giao thông công cộng phải đủ độ tin cậy để thuyết phục những người đi làm hằng ngày bỏ ô tô ở nhà.","audioKind":"ex2"}],"collocations":[{"en":"sufficiently clear","vi":"đủ rõ ràng"},{"en":"sufficiently prepared","vi":"chuẩn bị đầy đủ"},{"en":"sufficiently large","vi":"đủ lớn"}],"wordFamily":["sufficient (adj.)","sufficiency (n.)","insufficient (adj.)","insufficiently (adv.)"],"synonyms":["adequately","enough"],"antonyms":["insufficiently","inadequately"],"tipVi":"Bổ nghĩa cho tính từ thì đứng trước tính từ; còn enough thì đứng sau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_almond', 'en-b2-85', 'almond', '/ˈɑːmənd/', 'B2', 'hạt hạnh nhân; cây hạnh nhân', 'n.', NULL, NULL, 'Thường chỉ quả hạnh nhân (loại hạt dẹt), khác với nhân hạt mơ/hạnh đắng.', 'She sprinkled chopped almonds over her bowl of porridge.', NULL, 'Cô ấy rắc hạnh nhân cắt nhỏ lên bát cháo yến mạch của mình.', '{"wordId":"almond","ukIpa":"/ˈɑːmənd/","usIpa":"/ˈɑːmənd/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"an edible oval nut, or the tree that produces it","vi":"hạt hạnh nhân; cây hạnh nhân"}],"examples":[{"en":"She sprinkled chopped almonds over her bowl of porridge.","vi":"Cô ấy rắc hạnh nhân cắt nhỏ lên bát cháo yến mạch của mình.","audioKind":"ex"},{"en":"Almond production requires substantial irrigation in some regions, raising concerns about the sustainability of local water supplies.","vi":"Việc trồng hạnh nhân đòi hỏi hệ thống tưới tiêu lớn ở một số vùng, làm dấy lên lo ngại về tính bền vững của nguồn nước địa phương.","audioKind":"ex2"}],"collocations":[{"en":"roasted almonds","vi":"hạnh nhân rang"},{"en":"almond milk","vi":"sữa hạnh nhân"},{"en":"ground almonds","vi":"bột hạnh nhân"},{"en":"almond blossom","vi":"hoa hạnh nhân"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ quả hạnh nhân (loại hạt dẹt), khác với nhân hạt mơ/hạnh đắng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_warmth', 'en-b2-85', 'warmth', '/wɔːrmθ/', 'B2', 'sự ấm áp; độ ấm; sự nồng hậu; sự thân thiện', 'n.', 'warm (adj.), warm (v.), warmly (adv.)', 'Đồng nghĩa: heat, friendliness · Trái nghĩa: coldness', 'Thường không đếm được; vừa chỉ nhiệt độ dễ chịu, vừa chỉ thái độ đối xử thân thiện.', 'We enjoyed the warmth of the fire after our walk.', NULL, 'Chúng tôi tận hưởng hơi ấm của ngọn lửa sau khi đi dạo về.', '{"wordId":"warmth","ukIpa":"/wɔːmθ/","usIpa":"/wɔːrmθ/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A comfortable level of heat.","vi":"sự ấm áp; độ ấm"},{"pos":"n.","en":"Friendly affection shown in someone''s behaviour or manner.","vi":"sự nồng hậu; sự thân thiện"}],"examples":[{"en":"We enjoyed the warmth of the fire after our walk.","vi":"Chúng tôi tận hưởng hơi ấm của ngọn lửa sau khi đi dạo về.","audioKind":"ex"},{"en":"The warmth of community relationships can help older residents feel supported and reduce their sense of isolation.","vi":"Sự ấm áp trong các mối quan hệ cộng đồng có thể giúp cư dân lớn tuổi cảm thấy được hỗ trợ và giảm bớt cảm giác cô lập.","audioKind":"ex2"}],"collocations":[{"en":"for warmth","vi":"để sưởi ấm"},{"en":"the warmth of the sun","vi":"hơi ấm của mặt trời"},{"en":"human warmth","vi":"tình người ấm áp"},{"en":"warmth and kindness","vi":"sự nồng hậu và lòng tốt"}],"wordFamily":["warm (adj.)","warm (v.)","warmly (adv.)"],"synonyms":["heat","friendliness"],"antonyms":["coldness"],"tipVi":"Thường không đếm được; vừa chỉ nhiệt độ dễ chịu, vừa chỉ thái độ đối xử thân thiện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_adjustment', 'en-b2-85', 'adjustment', '/əˈdʒʌstmənt/', 'B2', 'sự điều chỉnh; sự thay đổi nhỏ; sự thích nghi', 'n.', 'adjust (v.), adjustable (adj.), readjust (v.)', 'Đồng nghĩa: modification, alteration', 'Khi diễn tả hành động thay đổi hoặc thích nghi, thường dùng giới từ adjustment to.', 'A small adjustment to the seat made cycling easier.', NULL, 'Một sự điều chỉnh nhỏ ở phần yên xe đã giúp việc đạp xe trở nên dễ dàng hơn.', '{"wordId":"adjustment","ukIpa":"/əˈdʒʌstmənt/","usIpa":"/əˈdʒʌstmənt/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A small change made to improve something.","vi":"sự điều chỉnh; sự thay đổi nhỏ"},{"pos":"n.","en":"The process of becoming comfortable with a new situation.","vi":"sự thích nghi"}],"examples":[{"en":"A small adjustment to the seat made cycling easier.","vi":"Một sự điều chỉnh nhỏ ở phần yên xe đã giúp việc đạp xe trở nên dễ dàng hơn.","audioKind":"ex"},{"en":"Moving to a new country often requires considerable adjustment to unfamiliar social customs and daily routines.","vi":"Việc chuyển đến một đất nước mới thường đòi hỏi sự thích nghi đáng kể với các phong tục xã hội xa lạ và nhịp sống hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"make an adjustment","vi":"thực hiện sự điều chỉnh"},{"en":"minor adjustment","vi":"điều chỉnh nhỏ"},{"en":"adjustment period","vi":"giai đoạn thích nghi"}],"wordFamily":["adjust (v.)","adjustable (adj.)","readjust (v.)"],"synonyms":["modification","alteration"],"antonyms":[],"tipVi":"Khi diễn tả hành động thay đổi hoặc thích nghi, thường dùng giới từ adjustment to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lightly', 'en-b2-85', 'lightly', '/ˈlaɪtli/', 'B2', 'nhẹ nhàng; khẽ khàng; một chút; hơi; một cách hời hợt; thiếu nghiêm túc', 'adv.', 'light (adj.), lightness (n.)', 'Đồng nghĩa: gently, slightly · Trái nghĩa: heavily', 'take something lightly ý chỉ việc không coi trọng hoặc không nghiêm túc đối với vấn đề gì.', 'He tapped lightly on the door before coming inside.', NULL, 'Anh ấy khẽ gõ cửa trước khi bước vào.', '{"wordId":"lightly","ukIpa":"/ˈlaɪtli/","usIpa":"/ˈlaɪtli/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"With little force, pressure, or weight.","vi":"nhẹ nhàng; khẽ khàng"},{"pos":"adv.","en":"To a small degree or in a small amount.","vi":"một chút; hơi"},{"pos":"adv.","en":"Without treating something as serious or important.","vi":"một cách hời hợt; thiếu nghiêm túc"}],"examples":[{"en":"He tapped lightly on the door before coming inside.","vi":"Anh ấy khẽ gõ cửa trước khi bước vào.","audioKind":"ex"},{"en":"Decisions about closing rural schools should not be taken lightly, as they can affect entire communities.","vi":"Các quyết định về việc đóng cửa các trường học ở vùng nông thôn không nên được đưa ra một cách hời hợt, vì chúng có thể ảnh hưởng đến toàn bộ cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"tap lightly","vi":"gõ nhẹ"},{"en":"lightly salted","vi":"được ướp muối nhạt"},{"en":"take something lightly","vi":"coi nhẹ việc gì"},{"en":"lightly armed","vi":"được trang bị vũ khí nhẹ"}],"wordFamily":["light (adj.)","lightness (n.)"],"synonyms":["gently","slightly"],"antonyms":["heavily"],"tipVi":"take something lightly ý chỉ việc không coi trọng hoặc không nghiêm túc đối với vấn đề gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_secure', 'en-b2-85', 'secure', '/sɪˈkjʊr/', 'B2', 'an toàn; chắc chắn; vững chãi; đạt được; giành được; nắm chắc; cố định; siết chặt; bảo đảm an toàn', 'adj.', 'security (n.), securely (adv.), insecure (adj.)', 'Đồng nghĩa: safe · Trái nghĩa: insecure', 'secure vừa có thể đóng vai trò là tính từ, vừa là ngoại động từ mang nghĩa giành được hoặc bảo đảm.', 'Check that the ladder is secure before climbing up.', NULL, 'Hãy kiểm tra xem chiếc thang đã được dựng chắc chắn chưa trước khi trèo lên.', '{"wordId":"secure","ukIpa":"/sɪˈkjʊə/","usIpa":"/sɪˈkjʊr/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Protected from danger, or firmly fixed in place.","vi":"an toàn; chắc chắn; vững chãi"},{"pos":"v.","en":"To successfully obtain something important.","vi":"đạt được; giành được; nắm chắc"},{"pos":"v.","en":"To fasten something firmly or protect it from harm.","vi":"cố định; siết chặt; bảo đảm an toàn"}],"examples":[{"en":"Check that the ladder is secure before climbing up.","vi":"Hãy kiểm tra xem chiếc thang đã được dựng chắc chắn chưa trước khi trèo lên.","audioKind":"ex"},{"en":"Governments should ensure that citizens have secure access to clean water during periods of drought.","vi":"Chính phủ nên đảm bảo rằng người dân có thể tiếp cận nguồn nước sạch một cách ổn định trong thời kỳ hạn hán.","audioKind":"ex2"}],"collocations":[{"en":"secure a job","vi":"kiếm được việc làm"},{"en":"secure funding","vi":"vận động được nguồn vốn"},{"en":"feel secure","vi":"cảm thấy an tâm"},{"en":"secure firmly","vi":"cố định chắc chắn"}],"wordFamily":["security (n.)","securely (adv.)","insecure (adj.)"],"synonyms":["safe"],"antonyms":["insecure"],"tipVi":"secure vừa có thể đóng vai trò là tính từ, vừa là ngoại động từ mang nghĩa giành được hoặc bảo đảm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gear', 'en-b2-85', 'gear', '/ɡɪr/', 'B2', 'trang thiết bị; đồ dùng; bánh răng; số xe; làm cho phù hợp; hướng đến', 'n.', 'geared (adj.), gearbox (n.)', 'Đồng nghĩa: equipment, kit', 'Khi chỉ trang thiết bị thì không đếm được; khi chỉ bánh răng hoặc cần số thì đếm được.', 'We packed our camping gear into the car.', NULL, 'Chúng tôi đã xếp gọn đồ cắm trại lên xe ô tô.', '{"wordId":"gear","ukIpa":"/ɡɪə/","usIpa":"/ɡɪr/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"equipment or clothing needed for a particular activity","vi":"trang thiết bị; đồ dùng"},{"pos":"n.","en":"a toothed wheel, or a setting controlling vehicle speed","vi":"bánh răng; số xe"},{"pos":"v.","en":"to design or organise something for a particular purpose","vi":"làm cho phù hợp; hướng đến"}],"examples":[{"en":"We packed our camping gear into the car.","vi":"Chúng tôi đã xếp gọn đồ cắm trại lên xe ô tô.","audioKind":"ex"},{"en":"Schools should gear their career guidance towards the changing needs of students and the wider labour market.","vi":"Các trường học nên điều chỉnh hướng nghiệp sao cho phù hợp với nhu cầu thay đổi của học sinh và thị trường lao động nói chung.","audioKind":"ex2"}],"collocations":[{"en":"camping gear","vi":"dụng cụ cắm trại"},{"en":"protective gear","vi":"trang thiết bị bảo hộ"},{"en":"change gear","vi":"đổi số xe"},{"en":"be geared towards","vi":"được định hướng vào"}],"wordFamily":["geared (adj.)","gearbox (n.)"],"synonyms":["equipment","kit"],"antonyms":[],"tipVi":"Khi chỉ trang thiết bị thì không đếm được; khi chỉ bánh răng hoặc cần số thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_continuous', 'en-b2-85', 'continuous', '/kənˈtɪnjuəs/', 'B2', 'liên tục; không ngừng nghỉ', 'adj.', 'continue (v.), continuously (adv.), continuity (n.), continuation (n.)', 'Đồng nghĩa: uninterrupted, unbroken · Trái nghĩa: intermittent', 'continuous nhấn mạnh sự việc diễn ra không đứt quãng; continual thường chỉ việc lặp đi lặp lại.', 'Continuous rain kept us indoors for the whole weekend.', NULL, 'Cơn mưa dầm dề suốt cả cuối tuần khiến chúng tôi phải ở trong nhà.', '{"wordId":"continuous","ukIpa":"/kənˈtɪnjuəs/","usIpa":"/kənˈtɪnjuəs/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Continuing without a break or interruption.","vi":"liên tục; không ngừng nghỉ"}],"examples":[{"en":"Continuous rain kept us indoors for the whole weekend.","vi":"Cơn mưa dầm dề suốt cả cuối tuần khiến chúng tôi phải ở trong nhà.","audioKind":"ex"},{"en":"Continuous monitoring of air quality helps local authorities identify pollution sources and protect public health.","vi":"Việc theo dõi chất lượng không khí liên tục giúp chính quyền địa phương xác định các nguồn gây ô nhiễm và bảo vệ sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"continuous improvement","vi":"cải tiến liên tục"},{"en":"continuous monitoring","vi":"giám sát liên tục"},{"en":"continuous flow","vi":"dòng chảy liên tục"}],"wordFamily":["continue (v.)","continuously (adv.)","continuity (n.)","continuation (n.)"],"synonyms":["uninterrupted","unbroken"],"antonyms":["intermittent"],"tipVi":"continuous nhấn mạnh sự việc diễn ra không đứt quãng; continual thường chỉ việc lặp đi lặp lại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tangle', 'en-b2-85', 'tangle', '/ˈtæŋɡəl/', 'B2', 'búi rối; mớ hỗn độn; làm xoắn vào nhau; quấn lấy nhau; tình trạng rắc rối phức tạp', 'n.', 'tangled (adj.), untangle (v.), entangle (v.), entanglement (n.)', NULL, 'Cụm a tangle of có thể dùng cho vật chất bị quấn rối hoặc tình huống rắc rối.', 'My headphones were buried in a tangle of cables.', NULL, 'Chiếc tai nghe của tôi nằm sâu trong một búi dây cáp rối tung.', '{"wordId":"tangle","ukIpa":"/ˈtæŋɡəl/","usIpa":"/ˈtæŋɡəl/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A twisted mass of threads, hair, or similar things","vi":"búi rối; mớ hỗn độn"},{"pos":"v.","en":"Become twisted together, or make things twist together","vi":"làm xoắn vào nhau; quấn lấy nhau"},{"pos":"n.","en":"A confused situation that is difficult to resolve","vi":"tình trạng rắc rối phức tạp"}],"examples":[{"en":"My headphones were buried in a tangle of cables.","vi":"Chiếc tai nghe của tôi nằm sâu trong một búi dây cáp rối tung.","audioKind":"ex"},{"en":"Small businesses often face a tangle of regulations that makes expansion costly and time-consuming.","vi":"Các doanh nghiệp nhỏ thường phải đối mặt với một rừng quy định phức tạp khiến việc mở rộng kinh doanh trở nên tốn kém và mất thời gian.","audioKind":"ex2"}],"collocations":[{"en":"a tangle of wires","vi":"đám dây điện rối tung"},{"en":"get tangled","vi":"bị xoắn vào nhau"},{"en":"a tangle of regulations","vi":"rừng quy định phức tạp"}],"wordFamily":["tangled (adj.)","untangle (v.)","entangle (v.)","entanglement (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm a tangle of có thể dùng cho vật chất bị quấn rối hoặc tình huống rắc rối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_yarn', 'en-b2-85', 'yarn', '/jɑːrn/', 'B2', 'sợi; chỉ dệt; câu chuyệna hoang đường; chuyện phao mè', 'n.', NULL, 'Đồng nghĩa: thread, tale', 'Khi mang nghĩa "sợi chỉ/len", từ này thường không đếm được; khi mang nghĩa "câu chuyện", nó là danh từ đếm được.', 'She chose soft blue yarn for the baby''s blanket.', NULL, 'Cô ấy chọn cuộn len màu xanh mềm mại để đan chiếc chăn cho em bé.', '{"wordId":"yarn","ukIpa":"/jɑːn/","usIpa":"/jɑːrn/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"Thread used for knitting or weaving cloth.","vi":"sợi; chỉ dệt"},{"pos":"n.","en":"An entertaining story, often exaggerated or invented.","vi":"câu chuyệna hoang đường; chuyện phao mè"}],"examples":[{"en":"She chose soft blue yarn for the baby''s blanket.","vi":"Cô ấy chọn cuộn len màu xanh mềm mại để đan chiếc chăn cho em bé.","audioKind":"ex"},{"en":"Using yarn made from recycled materials can reduce waste in the textile industry.","vi":"Việc sử dụng sợi làm từ vật liệu tái chế có thể giúp giảm thiểu rác thải trong ngành công nghiệp dệt may.","audioKind":"ex2"}],"collocations":[{"en":"a ball of yarn","vi":"một cuộn len"},{"en":"woollen yarn","vi":"sợi len"},{"en":"spin a yarn","vi":"kể chuyện phiêu lưu"}],"wordFamily":[],"synonyms":["thread","tale"],"antonyms":[],"tipVi":"Khi mang nghĩa \"sợi chỉ/len\", từ này thường không đếm được; khi mang nghĩa \"câu chuyện\", nó là danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hectic', 'en-b2-85', 'hectic', '/ˈhektɪk/', 'B2', 'bận rộn; tất bật; căng thẳng', 'adj.', 'hectically (adv.)', 'Đồng nghĩa: busy, frantic · Trái nghĩa: calm, relaxed', 'Nghĩa phổ biến trong tiếng Anh hiện đại là bận rộn, không mang nghĩa phấn khích hay sốt.', 'After a hectic morning, I finally sat down for lunch.', NULL, 'Sau một buổi sáng bận rộn tất bật, cuối cùng tôi cũng được ngồi xuống ăn trưa.', '{"wordId":"hectic","ukIpa":"/ˈhektɪk/","usIpa":"/ˈhektɪk/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"extremely busy and full of activity, often causing stress","vi":"bận rộn; tất bật; căng thẳng"}],"examples":[{"en":"After a hectic morning, I finally sat down for lunch.","vi":"Sau một buổi sáng bận rộn tất bật, cuối cùng tôi cũng được ngồi xuống ăn trưa.","audioKind":"ex"},{"en":"A hectic urban lifestyle can leave residents with little time for exercise, relaxation, or meaningful social interaction.","vi":"Nhịp sống đô thị tất bật căng thẳng có thể khiến cư dân thành thị có rất ít thời gian để tập thể dục, thư giãn hoặc giao lưu xã hội ý nghĩa.","audioKind":"ex2"}],"collocations":[{"en":"a hectic schedule","vi":"lịch trình bận rộn"},{"en":"a hectic lifestyle","vi":"lối sống bận rộn"},{"en":"a hectic day","vi":"một ngày tất bật"}],"wordFamily":["hectically (adv.)"],"synonyms":["busy","frantic"],"antonyms":["calm","relaxed"],"tipVi":"Nghĩa phổ biến trong tiếng Anh hiện đại là bận rộn, không mang nghĩa phấn khích hay sốt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shrug', 'en-b2-85', 'shrug', '/ʃrʌɡ/', 'B2', 'nhún vai; cái nhún vai', 'v.', NULL, NULL, 'Dạng quá khứ là "shrugged"; cụm "shrug off" mang nghĩa phớt lờ, không bận tâm.', 'He shrugged when I asked where the keys were.', NULL, 'Anh ấy nhún vai khi tôi hỏi chìa khóa ở đâu.', '{"wordId":"shrug","ukIpa":"/ʃrʌɡ/","usIpa":"/ʃrʌɡ/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To raise your shoulders to show uncertainty or indifference","vi":"nhún vai"},{"pos":"n.","en":"A shoulder movement expressing uncertainty or lack of concern","vi":"cái nhún vai"}],"examples":[{"en":"He shrugged when I asked where the keys were.","vi":"Anh ấy nhún vai khi tôi hỏi chìa khóa ở đâu.","audioKind":"ex"},{"en":"Governments should not shrug off public concerns about air pollution, as these directly affect community health.","vi":"Chính phủ không nên phớt lờ những lo ngại của công chúng về ô nhiễm không khí, vì chúng ảnh hưởng trực tiếp đến sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"shrug your shoulders","vi":"nhún vai"},{"en":"give a shrug","vi":"nhún vai một cái"},{"en":"shrug off criticism","vi":"phớt lờ lời chỉ trích"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ là \"shrugged\"; cụm \"shrug off\" mang nghĩa phớt lờ, không bận tâm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_slap', 'en-b2-85', 'slap', '/slæp/', 'B2', 'vỗ; tát (bằng bàn tay mở); cái vỗ; cái tát', 'v.', NULL, NULL, 'Quá khứ đơn và quá khứ phân từ là "slapped", cần gấp đôi chữ "p".', 'She slapped her knee and laughed at the joke.', NULL, 'Cô ấy vỗ đùi cười lớn trước câu chuyện cười.', '{"wordId":"slap","ukIpa":"/slæp/","usIpa":"/slæp/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"Hit someone or something with an open hand.","vi":"vỗ; tát (bằng bàn tay mở)"},{"pos":"n.","en":"A hit made with an open hand.","vi":"cái vỗ; cái tát"}],"examples":[{"en":"She slapped her knee and laughed at the joke.","vi":"Cô ấy vỗ đùi cười lớn trước câu chuyện cười.","audioKind":"ex"},{"en":"The coach slapped the player''s back in celebration, highlighting the supportive atmosphere within the team.","vi":"Huấn luyện viên vỗ lưng cầu thủ để ăn mừng, làm nổi bật bầu không khí gắn kết và ủng hộ lẫn nhau trong đội.","audioKind":"ex2"}],"collocations":[{"en":"slap someone on the back","vi":"vỗ lưng ai đó"},{"en":"a slap on the wrist","vi":"hình phạt nhẹ"},{"en":"slap something down","vi":"đặt mạnh xuống"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Quá khứ đơn và quá khứ phân từ là \"slapped\", cần gấp đôi chữ \"p\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_toss', 'en-b2-85', 'toss', '/tɔːs/', 'B2', 'ném nhẹ; vứt; trộn đều; xóc (thức ăn); cú ném nhẹ', 'v.', NULL, 'Đồng nghĩa: throw, fling', '"Toss" thường chỉ hành động ném nhẹ; cụm "toss and turn" có nghĩa là trằn trọc không ngủ được.', 'Could you toss me that cushion from the sofa?', NULL, 'Bạn có thể ném cho tôi chiếc gối tựa từ ghế sofa được không?', '{"wordId":"toss","ukIpa":"/tɒs/","usIpa":"/tɔːs/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To throw something lightly or without much care.","vi":"ném nhẹ; vứt"},{"pos":"v.","en":"To turn food over gently to mix or coat it.","vi":"trộn đều; xóc (thức ăn)"},{"pos":"n.","en":"An act of throwing something lightly.","vi":"cú ném nhẹ"}],"examples":[{"en":"Could you toss me that cushion from the sofa?","vi":"Bạn có thể ném cho tôi chiếc gối tựa từ ghế sofa được không?","audioKind":"ex"},{"en":"Consumers often toss usable items into the bin, increasing waste that could be avoided through repair.","vi":"Người tiêu dùng thường vứt những món đồ còn dùng được vào thùng rác, làm gia tăng lượng rác thải vốn có thể tránh được thông qua việc sửa chữa.","audioKind":"ex2"}],"collocations":[{"en":"toss a coin","vi":"tung đồng xu"},{"en":"toss a salad","vi":"trộn salad"},{"en":"toss and turn","vi":"trằn trọc khó ngủ"}],"wordFamily":[],"synonyms":["throw","fling"],"antonyms":[],"tipVi":"\"Toss\" thường chỉ hành động ném nhẹ; cụm \"toss and turn\" có nghĩa là trằn trọc không ngủ được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_identical', 'en-b2-85', 'identical', '/aɪˈdentɪkəl/', 'B2', 'hoàn toàn giống nhau', 'adj.', 'identically (adv.)', 'Đồng nghĩa: indistinguishable · Trái nghĩa: different', 'Thường dùng cấu trúc "identical to"; mức độ giống nhau cao hơn so với "similar".', 'We bought identical jackets without knowing about each other''s choice.', NULL, 'Chúng tôi đã mua hai chiếc áo khoác y hệt nhau mà không hề biết trước sự lựa chọn của đối phương.', '{"wordId":"identical","ukIpa":"/aɪˈdentɪkəl/","usIpa":"/aɪˈdentɪkəl/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"exactly the same in every relevant detail","vi":"hoàn toàn giống nhau"}],"examples":[{"en":"We bought identical jackets without knowing about each other''s choice.","vi":"Chúng tôi đã mua hai chiếc áo khoác y hệt nhau mà không hề biết trước sự lựa chọn của đối phương.","audioKind":"ex"},{"en":"Providing identical resources to every school may not address differences in students'' needs or local circumstances.","vi":"Việc cung cấp các nguồn lực hoàn toàn giống nhau cho mọi trường học có thể không giải quyết được sự khác biệt về nhu cầu của học sinh hoặc hoàn cảnh địa phương.","audioKind":"ex2"}],"collocations":[{"en":"identical twins","vi":"sinh đôi cùng trứng"},{"en":"identical to","vi":"hoàn toàn giống với..."},{"en":"virtually identical","vi":"gần như hoàn toàn giống nhau"}],"wordFamily":["identically (adv.)"],"synonyms":["indistinguishable"],"antonyms":["different"],"tipVi":"Thường dùng cấu trúc \"identical to\"; mức độ giống nhau cao hơn so với \"similar\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bundle', 'en-b2-85', 'bundle', '/ˈbʌndəl/', 'B2', 'bó; búi; gói; buộc lại; gói lại; nhét vội; tống vội (ai/cái gì vào đâu)', 'n.', NULL, NULL, 'a bundle of theo sau là danh từ số nhiều; bundle up cũng có nghĩa là mặc quần áo ấm.', 'He carried a bundle of blankets into the house.', NULL, 'Anh ấy ôm một bó chăn đi vào trong nhà.', '{"wordId":"bundle","ukIpa":"/ˈbʌndəl/","usIpa":"/ˈbʌndəl/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A group of things tied or wrapped together.","vi":"bó; búi; gói"},{"pos":"v.","en":"To tie or wrap things together.","vi":"buộc lại; gói lại"},{"pos":"v.","en":"To put or move someone or something somewhere hurriedly.","vi":"nhét vội; tống vội (ai/cái gì vào đâu)"}],"examples":[{"en":"He carried a bundle of blankets into the house.","vi":"Anh ấy ôm một bó chăn đi vào trong nhà.","audioKind":"ex"},{"en":"Offering internet and telephone services as a bundle may reduce costs, but consumers should compare contracts carefully.","vi":"Việc cung cấp dịch vụ Internet và điện thoại gộp chung có thể làm giảm chi phí, nhưng người tiêu dùng nên so sánh các hợp đồng một cách cẩn thận.","audioKind":"ex2"}],"collocations":[{"en":"a bundle of clothes","vi":"một bọc quần áo"},{"en":"tie into bundles","vi":"buộc thành bó"},{"en":"bundle up","vi":"mặc thật ấm; gói ghém"},{"en":"bundle into a car","vi":"nhét vội lên xe"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"a bundle of theo sau là danh từ số nhiều; bundle up cũng có nghĩa là mặc quần áo ấm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_85_1', 'en-b2-85', 'Cách dùng “satisfactory” (adj.) — thỏa đáng; đạt yêu cầu; đủ tiêu chuẩn', 'satisfactory results  ·  satisfactory explanation  ·  satisfactory progress', 'Nhấn mạnh việc đáp ứng đúng yêu cầu, không nhất thiết phải xuất sắc; cảm giác hài lòng của con người dùng satisfied.', 'Họ từ (Word Family): satisfy (v.), satisfaction (n.), satisfactorily (adv.), unsatisfactory (adj.) | Đồng nghĩa: acceptable, adequate · Trái nghĩa: unsatisfactory, inadequate', '[{"hanzi":"The mechanic confirmed that the brakes were satisfactory.","pinyin":"","meaning":"Thợ máy xác nhận rằng hệ thống phanh đã đạt yêu cầu."},{"hanzi":"Providing satisfactory public transport is essential if cities want residents to rely less on private cars.","pinyin":"","meaning":"Việc cung cấp dịch vụ giao thông công cộng thỏa đáng là điều cốt yếu nếu các thành phố muốn người dân giảm bớt sự phụ thuộc vào ô tô cá nhân."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_85_2', 'en-b2-85', 'Cách dùng “yarn” (n.) — sợi; chỉ dệt', 'a ball of yarn  ·  woollen yarn  ·  spin a yarn', 'Khi mang nghĩa "sợi chỉ/len", từ này thường không đếm được; khi mang nghĩa "câu chuyện", nó là danh từ đếm được.', 'Đồng nghĩa: thread, tale', '[{"hanzi":"She chose soft blue yarn for the baby''s blanket.","pinyin":"","meaning":"Cô ấy chọn cuộn len màu xanh mềm mại để đan chiếc chăn cho em bé."},{"hanzi":"Using yarn made from recycled materials can reduce waste in the textile industry.","pinyin":"","meaning":"Việc sử dụng sợi làm từ vật liệu tái chế có thể giúp giảm thiểu rác thải trong ngành công nghiệp dệt may."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_85_3', 'en-b2-85', 'Cách dùng “thread” (n.) — chỉ; sợi chỉ', 'sewing thread  ·  thread a needle  ·  lose the thread', 'Cụm từ lose the thread dùng để chỉ việc người nói hoặc người đọc bị mất mạch suy nghĩ, không theo kịp nội dung.', NULL, '[{"hanzi":"I need some blue thread to mend this shirt.","pinyin":"","meaning":"Tôi cần một ít chỉ xanh để vá cái áo sơ mi này."},{"hanzi":"Clear transitions help readers follow the thread of an argument in a complex academic essay.","pinyin":"","meaning":"Sự liên kết mạch lạc giúp người đọc theo dõi được mạch lập luận trong một bài viết học thuật phức tạp."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_85_4', 'en-b2-85', 'Cách dùng “secure” (adj.) — an toàn; chắc chắn; vững chãi', 'secure a job  ·  secure funding  ·  feel secure', 'secure vừa có thể đóng vai trò là tính từ, vừa là ngoại động từ mang nghĩa giành được hoặc bảo đảm.', 'Họ từ (Word Family): security (n.), securely (adv.), insecure (adj.) | Đồng nghĩa: safe · Trái nghĩa: insecure', '[{"hanzi":"Check that the ladder is secure before climbing up.","pinyin":"","meaning":"Hãy kiểm tra xem chiếc thang đã được dựng chắc chắn chưa trước khi trèo lên."},{"hanzi":"Governments should ensure that citizens have secure access to clean water during periods of drought.","pinyin":"","meaning":"Chính phủ nên đảm bảo rằng người dân có thể tiếp cận nguồn nước sạch một cách ổn định trong thời kỳ hạn hán."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_85_1', 'en-b2-85', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
