INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_85_1_2', 'ten_b2_85_1', 'thread', 'I need some blue thread to mend this shirt.', 'I need some blue thread to mend this shirt.', '/θred/', 'Tôi cần một ít chỉ xanh để vá cái áo sơ mi này.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_85_1_3', 'ten_b2_85_1', 'collide', 'Two shopping trolleys collided near the busy supermarket entrance.', 'Two shopping trolleys collided near the busy supermarket entrance.', '/kəˈlaɪd/', 'Hai chiếc xe đẩy hàng va vào nhau gần lối vào siêu thị đông đúc.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_85_1_4', 'ten_b2_85_1', 'satisfactory', 'The mechanic confirmed that the brakes were satisfactory.', 'The mechanic confirmed that the brakes were satisfactory.', '/ˌsætɪsˈfæktəri/', 'Thợ máy xác nhận rằng hệ thống phanh đã đạt yêu cầu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_85_1_5', 'ten_b2_85_1', 'rapidly', 'Dark clouds spread rapidly across the sky before lunch.', 'Dark clouds spread rapidly across the sky before lunch.', '/ˈræpɪdli/', 'Những đám mây đen nhanh chóng phủ kín bầu trời trước bữa trưa.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_85_1_6', 'ten_b2_85_1', 'beware', 'Beware of slippery rocks when you cross the stream.', 'Beware of slippery rocks when you cross the stream.', '/bɪˈwer/', 'Hãy cẩn thận với những tảng đá trơn trượt khi bạn băng qua suối.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_85_1_7', 'ten_b2_85_1', 'desirable', 'A balcony makes this small flat much more desirable.', 'A balcony makes this small flat much more desirable.', '/dɪˈzaɪrəbl/', 'Cái ban công khiến cho căn hộ nhỏ này trở nên đáng sống hơn rất nhiều.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_85_1_8', 'ten_b2_85_1', 'brighten', 'These yellow curtains really brighten our small kitchen.', 'These yellow curtains really brighten our small kitchen.', '/ˈbraɪtən/', 'Bộ rèm vàng này thực sự làm cho căn bếp nhỏ của chúng tôi bừng sáng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_85_1_1', 'en-b2-85', 'ten_b2_85_1', 'listening', 'listening', 'Your ticket is still valid for the return journey.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Anh ấy ôm một bó chăn đi vào trong nhà.","Chiếc tai nghe của tôi nằm sâu trong một búi dây cáp rối tung.","Hãy kiểm tra xem chiếc thang đã được dựng chắc chắn chưa trước khi trèo lên.","Vé của bạn vẫn có hiệu lực cho chuyến đi khứ hồi."]'::jsonb, 3, 'Your ticket is still valid for the return journey. → Vé của bạn vẫn có hiệu lực cho chuyến đi khứ hồi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_85_1_2', 'en-b2-85', 'ten_b2_85_1', 'listening', 'listening', 'I need some blue thread to mend this shirt.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một sự điều chỉnh nhỏ ở phần yên xe đã giúp việc đạp xe trở nên dễ dàng hơn.","Tôi cần một ít chỉ xanh để vá cái áo sơ mi này.","Bạn có thể ném cho tôi chiếc gối tựa từ ghế sofa được không?","Hãy cẩn thận với những tảng đá trơn trượt khi bạn băng qua suối."]'::jsonb, 1, 'I need some blue thread to mend this shirt. → Tôi cần một ít chỉ xanh để vá cái áo sơ mi này.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_85_1_3', 'en-b2-85', 'ten_b2_85_1', 'listening', 'listening', 'Two shopping trolleys collided near the busy supermarket entrance.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hai chiếc xe đẩy hàng va vào nhau gần lối vào siêu thị đông đúc.","Chúng tôi tận hưởng hơi ấm của ngọn lửa sau khi đi dạo về.","Món súp đã nguội vừa đủ để chúng tôi ăn.","Anh ấy ôm một bó chăn đi vào trong nhà."]'::jsonb, 0, 'Two shopping trolleys collided near the busy supermarket entrance. → Hai chiếc xe đẩy hàng va vào nhau gần lối vào siêu thị đông đúc.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_85_2', 'en-b2-85', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_85_2_1', 'ten_b2_85_2', 'valid', 'Although online learning offers flexibility, students have valid concerns about limited interaction with their teachers.', 'Although online learning offers flexibility, students have valid concerns about limited interaction with their teachers.', '/ˈvælɪd/', 'Mặc dù học trực tuyến mang lại sự linh hoạt, học sinh vẫn có những lo lắng chính đáng về việc tương tác hạn chế với giáo viên.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_85_2_2', 'ten_b2_85_2', 'thread', 'Clear transitions help readers follow the thread of an argument in a complex academic essay.', 'Clear transitions help readers follow the thread of an argument in a complex academic essay.', '/θred/', 'Sự liên kết mạch lạc giúp người đọc theo dõi được mạch lập luận trong một bài viết học thuật phức tạp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_85_2_3', 'ten_b2_85_2', 'collide', 'Economic ambitions often collide with environmental priorities when governments consider approving major infrastructure projects.', 'Economic ambitions often collide with environmental priorities when governments consider approving major infrastructure projects.', '/kəˈlaɪd/', 'Tham vọng kinh tế thường xung đột với các ưu tiên về môi trường khi các chính phủ cân nhắc phê duyệt các dự án cơ sở hạ tầng lớn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_85_2_4', 'ten_b2_85_2', 'satisfactory', 'Providing satisfactory public transport is essential if cities want residents to rely less on private cars.', 'Providing satisfactory public transport is essential if cities want residents to rely less on private cars.', '/ˌsætɪsˈfæktəri/', 'Việc cung cấp dịch vụ giao thông công cộng thỏa đáng là điều cốt yếu nếu các thành phố muốn người dân giảm bớt sự phụ thuộc vào ô tô cá nhân.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_85_2_5', 'ten_b2_85_2', 'rapidly', 'As urban populations grow rapidly, public transport systems must expand to meet increasing demand.', 'As urban populations grow rapidly, public transport systems must expand to meet increasing demand.', '/ˈræpɪdli/', 'Khi dân số đô thị tăng nhanh, hệ thống giao thông công cộng phải được mở rộng để đáp ứng nhu cầu ngày càng tăng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_85_2_6', 'ten_b2_85_2', 'beware', 'Consumers should beware of online offers that promise expensive products at unusually low prices.', 'Consumers should beware of online offers that promise expensive products at unusually low prices.', '/bɪˈwer/', 'Người tiêu dùng nên đề phòng các ưu đãi trực tuyến hứa hẹn bán sản phẩm đắt tiền với giá thấp bất thường.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_85_2_1', 'en-b2-85', 'ten_b2_85_2', 'listening', 'listening', 'Although online learning offers flexibility, students have valid concerns about limited interaction with their teachers.', NULL, 'Trong câu vừa nghe, từ “valid” mang nghĩa nào sau đây?', '["có hiệu lực; hợp lệ, được công nhận chính thức","vùng ngoại ô; vùng ven đô","khẩn cấp; cấp bách","sự xung đột; sự trùng lịch"]'::jsonb, 0, '“valid” (/ˈvælɪd/): có hiệu lực; hợp lệ, được công nhận chính thức. Câu đầy đủ: Although online learning offers flexibility, students have valid concerns about limited interaction with their teachers.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_85_2_2', 'en-b2-85', 'ten_b2_85_2', 'listening', 'listening', 'Clear transitions help readers follow the thread of an argument in a complex academic essay.', NULL, 'Trong câu vừa nghe, từ “thread” mang nghĩa nào sau đây?', '["chỉ; sợi chỉ","nữ thần; vị nữ thần","cắt tỉa; cắt bớt một chút để làm gọn gàng hoặc giảm bớt","mỏng manh, dễ vỡ, dễ hư hỏng"]'::jsonb, 0, '“thread” (/θred/): chỉ; sợi chỉ. Câu đầy đủ: Clear transitions help readers follow the thread of an argument in a complex academic essay.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
