INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_85_2', 'en-b2-85', NULL, 'comprehensive_test', 'listening', 'I need some blue thread to mend this shirt.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi cần một ít chỉ xanh để vá cái áo sơ mi này.","Một chiếc roi da cũ treo cạnh cửa chuồng ngựa.","Chúng tôi đã mua hai chiếc áo khoác y hệt nhau mà không hề biết trước sự lựa chọn của đối phương.","Sau một buổi sáng bận rộn tất bật, cuối cùng tôi cũng được ngồi xuống ăn trưa."]'::jsonb, 0, 'I need some blue thread to mend this shirt. → Tôi cần một ít chỉ xanh để vá cái áo sơ mi này.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_85_3', 'en-b2-85', NULL, 'comprehensive_test', 'listening', 'collide', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thủ công; bằng tay","va chạm; đâm vào nhau","bằng chứng; chứng cứ; dấu hiệu","giao dịch viên ngân hàng"]'::jsonb, 1, 'collide (/kəˈlaɪd/) → va chạm; đâm vào nhau; xung đột; trái ngược nhau', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_85_4', 'en-b2-85', NULL, 'comprehensive_test', 'listening', 'The mechanic confirmed that the brakes were satisfactory.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hai chiếc xe đẩy hàng va vào nhau gần lối vào siêu thị đông đúc.","Thợ máy xác nhận rằng hệ thống phanh đã đạt yêu cầu.","Anh ấy ôm một bó chăn đi vào trong nhà.","Hãy cẩn thận với những tảng đá trơn trượt khi bạn băng qua suối."]'::jsonb, 1, 'The mechanic confirmed that the brakes were satisfactory. → Thợ máy xác nhận rằng hệ thống phanh đã đạt yêu cầu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_85_5', 'en-b2-85', NULL, 'comprehensive_test', 'listening', 'rapidly', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nhanh chóng; tốc độ cao","trước đó; ở phần trước","xé rách; làm rách","đặc điểm; nét tiêu biểu; phẩm chất"]'::jsonb, 0, 'rapidly (/ˈræpɪdli/) → nhanh chóng; tốc độ cao', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_85_6', 'en-b2-85', NULL, 'comprehensive_test', 'listening', 'Beware of slippery rocks when you cross the stream.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy vỗ đùi cười lớn trước câu chuyện cười.","Hãy cẩn thận với những tảng đá trơn trượt khi bạn băng qua suối.","Một chiếc roi da cũ treo cạnh cửa chuồng ngựa.","Anh ấy ôm một bó chăn đi vào trong nhà."]'::jsonb, 1, 'Beware of slippery rocks when you cross the stream. → Hãy cẩn thận với những tảng đá trơn trượt khi bạn băng qua suối.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_85_7', 'en-b2-85', NULL, 'comprehensive_test', 'listening', 'desirable', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chủ nghĩa xã hội","đáng ao ước; đáng giá, thích hợp","cây tre; tre; vật liệu bằng tre","cơ bản; nền tảng; cốt lõi"]'::jsonb, 1, 'desirable (/dɪˈzaɪrəbl/) → đáng ao ước; đáng giá, thích hợp', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_85_8', 'en-b2-85', NULL, 'comprehensive_test', 'listening', 'These yellow curtains really brighten our small kitchen.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hãy kiểm tra xem chiếc thang đã được dựng chắc chắn chưa trước khi trèo lên.","Bộ rèm vàng này thực sự làm cho căn bếp nhỏ của chúng tôi bừng sáng.","Cô ấy chọn cuộn len màu xanh mềm mại để đan chiếc chăn cho em bé.","Cô ấy vỗ đùi cười lớn trước câu chuyện cười."]'::jsonb, 1, 'These yellow curtains really brighten our small kitchen. → Bộ rèm vàng này thực sự làm cho căn bếp nhỏ của chúng tôi bừng sáng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_85_9', 'en-b2-85', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “At a fast speed or within a short time.”?', '["beware","rapidly","almond","hectic"]'::jsonb, 1, 'rapidly (/ˈræpɪdli/) → nhanh chóng; tốc độ cao', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
