INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_85_18', 'en-b2-85', NULL, 'comprehensive_test', 'reading', NULL, 'Although online learning offers flexibility, students have valid concerns about limited interaction with their teachers.', 'Dựa vào câu trên, từ “valid” có nghĩa phù hợp nhất là gì?', '["có hiệu lực; hợp lệ, được công nhận chính thức","việc; sự kiện; vấn đề","sự thất vọng; nỗi bực bội; cảm giác chán nản","búi rối; mớ hỗn độn"]'::jsonb, 0, 'valid: có hiệu lực; hợp lệ, được công nhận chính thức; có cơ sở; hợp lý, đúng đắn. Dịch cả câu: Mặc dù học trực tuyến mang lại sự linh hoạt, học sinh vẫn có những lo lắng chính đáng về việc tương tác hạn chế với giáo viên.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_85_19', 'en-b2-85', NULL, 'comprehensive_test', 'reading', NULL, 'Clear transitions help readers follow the thread of an argument in a complex academic essay.', 'Dựa vào câu trên, từ “thread” có nghĩa phù hợp nhất là gì?', '["nhún vai","cấp phó; người đại diện; người phụ tá","chỉ; sợi chỉ","giao lộ; ngã tư"]'::jsonb, 2, 'thread: chỉ; sợi chỉ; mạch lạc (ý tưởng); chuỗi thảo luận trực tuyến; xâu chỉ; luồn qua. Dịch cả câu: Sự liên kết mạch lạc giúp người đọc theo dõi được mạch lập luận trong một bài viết học thuật phức tạp.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_85_20', 'en-b2-85', NULL, 'comprehensive_test', 'reading', NULL, 'Economic ambitions often collide with environmental priorities when governments consider approving major infrastructure projects.', 'Dựa vào câu trên, từ “collide” có nghĩa phù hợp nhất là gì?', '["bó; búi; gói","sự điều hướng; sự định vị và dẫn đường","va chạm; đâm vào nhau","chất đạm; protein"]'::jsonb, 2, 'collide: va chạm; đâm vào nhau; xung đột; trái ngược nhau. Dịch cả câu: Tham vọng kinh tế thường xung đột với các ưu tiên về môi trường khi các chính phủ cân nhắc phê duyệt các dự án cơ sở hạ tầng lớn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_85_21', 'en-b2-85', NULL, 'comprehensive_test', 'reading', NULL, 'Providing satisfactory public transport is essential if cities want residents to rely less on private cars.', 'Dựa vào câu trên, từ “satisfactory” có nghĩa phù hợp nhất là gì?', '["thỏa đáng; đạt yêu cầu; đủ tiêu chuẩn","hoạt động giải trí; tiêu khiển","không đủ; không tương xứng","đáng kể; rất nhiều; vô cùng"]'::jsonb, 0, 'satisfactory: thỏa đáng; đạt yêu cầu; đủ tiêu chuẩn. Dịch cả câu: Việc cung cấp dịch vụ giao thông công cộng thỏa đáng là điều cốt yếu nếu các thành phố muốn người dân giảm bớt sự phụ thuộc vào ô tô cá nhân.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
