INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-86', 'en', 'Bài 86: Đời sống hằng ngày (13) - CEFR B2', 'CEFR B2', 'B2 · Đời sống', '26 từ vựng Tiếng Anh CEFR B2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4086, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flannel', 'en-b2-86', 'flannel', '/ˈflænl/', 'B2', 'vải flannel (vải dạ mềm bằng cotton hoặc len); khăn mặt nhỏ', 'n.', NULL, NULL, 'Nghĩa chỉ chất vải là không đếm được; trong tiếng Anh-Anh, a flannel chỉ một chiếc khăn lau mặt nhỏ.', 'She wore a soft flannel shirt over her T-shirt.', NULL, 'Cô ấy khoác một chiếc áo sơ mi flannel mềm mại bên ngoài chiếc áo phông.', '{"wordId":"flannel","ukIpa":"/ˈflænl/","usIpa":"/ˈflænl/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"soft cotton or wool cloth used for warm clothing","vi":"vải flannel (vải dạ mềm bằng cotton hoặc len)"},{"pos":"n.","en":"a small cloth used for washing your face or body","vi":"khăn mặt nhỏ"}],"examples":[{"en":"She wore a soft flannel shirt over her T-shirt.","vi":"Cô ấy khoác một chiếc áo sơ mi flannel mềm mại bên ngoài chiếc áo phông.","audioKind":"ex"},{"en":"In colder climates, flannel clothing provides practical warmth and can reduce reliance on intensive indoor heating.","vi":"Ở những vùng khí hậu lạnh hơn, trang phục bằng vải flannel mang lại sự ấm áp thiết thực và có thể làm giảm sự phụ thuộc vào hệ thống sưởi trong nhà cường độ cao.","audioKind":"ex2"}],"collocations":[{"en":"flannel shirt","vi":"áo sơ mi flannel"},{"en":"flannel pyjamas","vi":"đồ ngủ flannel"},{"en":"cotton flannel","vi":"vải flannel cotton"},{"en":"a damp flannel","vi":"một chiếc khăn mặt ẩm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa chỉ chất vải là không đếm được; trong tiếng Anh-Anh, a flannel chỉ một chiếc khăn lau mặt nhỏ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_setting', 'en-b2-86', 'setting', '/ˈsetɪŋ/', 'B2', 'môi trường; bối cảnh; khung cảnh; cài đặt; mức; độ; ổ gắn đá; ổ nhẫn', 'n.', 'set (v.)', NULL, 'Nghĩa bối cảnh/môi trường thường dùng in a setting; các cài đặt trên thiết bị dùng số nhiều settings.', 'The lakeside garden provides a peaceful setting for lunch.', NULL, 'Khu vườn ven hồ tạo nên một khung cảnh yên bình cho bữa trưa.', '{"wordId":"setting","ukIpa":"/ˈsetɪŋ/","usIpa":"/ˈsetɪŋ/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"The place and conditions in which something happens.","vi":"môi trường; bối cảnh; khung cảnh"},{"pos":"n.","en":"A position or option controlling how a device works.","vi":"cài đặt; mức; độ"},{"pos":"n.","en":"The metal structure that holds a gemstone in jewellery.","vi":"ổ gắn đá; ổ nhẫn"}],"examples":[{"en":"The lakeside garden provides a peaceful setting for lunch.","vi":"Khu vườn ven hồ tạo nên một khung cảnh yên bình cho bữa trưa.","audioKind":"ex"},{"en":"Children often develop stronger communication skills in a supportive educational setting that encourages cooperation rather than competition.","vi":"Trẻ em thường phát triển các kỹ năng giao tiếp tốt hơn trong một môi trường giáo dục mang tính hỗ trợ, nơi khuyến khích sự hợp tác thay vì cạnh tranh.","audioKind":"ex2"}],"collocations":[{"en":"a rural setting","vi":"bối cảnh nông thôn"},{"en":"an educational setting","vi":"môi trường giáo dục"},{"en":"privacy settings","vi":"cài đặt quyềnriêng tư"},{"en":"a heat setting","vi":"mức nhiệt độ"}],"wordFamily":["set (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa bối cảnh/môi trường thường dùng in a setting; các cài đặt trên thiết bị dùng số nhiều settings.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_strand', 'en-b2-86', 'strand', '/strænd/', 'B2', 'sợi; lọn; dải; khía cạnh; yếu tố; phần; làm cho mắc kẹt; bỏ lại', 'n.', 'stranded (adj.)', NULL, 'Cụm "một sợi tóc" dùng a strand of hair; cảnh bị mắc kẹt thường dùng cấu trúc be stranded.', 'A strand of hair fell across her face.', NULL, 'Một lọn tóc xõa ngang khuôn mặt cô ấy.', '{"wordId":"strand","ukIpa":"/strænd/","usIpa":"/strænd/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A single thin length of hair, thread, or similar material.","vi":"sợi; lọn; dải"},{"pos":"n.","en":"One element within a larger argument, story, or activity.","vi":"khía cạnh; yếu tố; phần"},{"pos":"v.","en":"To leave someone somewhere without a way to leave.","vi":"làm cho mắc kẹt; bỏ lại"}],"examples":[{"en":"A strand of hair fell across her face.","vi":"Một lọn tóc xõa ngang khuôn mặt cô ấy.","audioKind":"ex"},{"en":"Improving public transport is one strand of a broader strategy to reduce urban air pollution.","vi":"Cải thiện giao thông công cộng là một khía cạnh của chiến lược rộng lớn hơn nhằm giảm ô nhiễm không khí đô thị.","audioKind":"ex2"}],"collocations":[{"en":"a strand of hair","vi":"một lọn tóc"},{"en":"a strand of an argument","vi":"một khía cạnh của lập luận"},{"en":"leave passengers stranded","vi":"bỏ mặc hành khách mắc kẹt"}],"wordFamily":["stranded (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm \"một sợi tóc\" dùng a strand of hair; cảnh bị mắc kẹt thường dùng cấu trúc be stranded.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_crisp', 'en-b2-86', 'crisp', '/krɪsp/', 'B2', 'giòn; giòn rụm; mát mẻ; trong lành; khoai tây chiên giòn', 'adj.', 'crispy (adj.), crispness (n.), crisply (adv.)', 'Đồng nghĩa: crunchy · Trái nghĩa: soggy', 'Khoai tây chiên trong tiếng Anh Anh thường dùng dạng số nhiều crisps, còn tiếng Anh Mỹ dùng potato chips.', 'The apple was crisp and sweet with every bite.', NULL, 'Quả táo vừa giòn vừa ngọt trong từng miếng cắn.', '{"wordId":"crisp","ukIpa":"/krɪsp/","usIpa":"/krɪsp/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"firm or dry enough to break with a sharp sound","vi":"giòn; giòn rụm"},{"pos":"adj.","en":"pleasantly cool and fresh, describing air or weather","vi":"mát mẻ; trong lành"},{"pos":"n.","en":"a thin fried potato slice, usually eaten as a snack","vi":"khoai tây chiên giòn"}],"examples":[{"en":"The apple was crisp and sweet with every bite.","vi":"Quả táo vừa giòn vừa ngọt trong từng miếng cắn.","audioKind":"ex"},{"en":"Packaging helps keep snacks crisp, but excessive use of plastic creates significant environmental problems.","vi":"Bao bì giúp giữ cho đồ ăn nhẹ giòn ngon, nhưng việc lạm dụng nhựa gây ra các vấn đề môi trường nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"crisp lettuce","vi":"rau diếp giòn"},{"en":"crisp air","vi":"không khí trong lành"},{"en":"a packet of crisps","vi":"một gói khoai tây chiên"}],"wordFamily":["crispy (adj.)","crispness (n.)","crisply (adv.)"],"synonyms":["crunchy"],"antonyms":["soggy"],"tipVi":"Khoai tây chiên trong tiếng Anh Anh thường dùng dạng số nhiều crisps, còn tiếng Anh Mỹ dùng potato chips.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_twist', 'en-b2-86', 'twist', '/twɪst/', 'B2', 'vặn; xoắn; xoay; cú ngoặt bất ngờ; tình tiết bất ngờ; bóp méo; xuyên tạc', 'v.', 'twisted (adj)', NULL, 'Twist vừa có thể chỉ hành động vặn xoắn vật lý, vừa có thể chỉ việc bóp méo sự thật.', 'She twisted the wet towel over the sink.', NULL, 'Cô ấy vắt chiếc khăn ướt ngay trên bồn rửa chén.', '{"wordId":"twist","ukIpa":"/twɪst/","usIpa":"/twɪst/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"turn something so its parts rotate in different directions","vi":"vặn; xoắn; xoay"},{"pos":"n.","en":"an unexpected change in a story or situation","vi":"cú ngoặt bất ngờ; tình tiết bất ngờ"},{"pos":"v.","en":"change the meaning of something to mislead people","vi":"bóp méo; xuyên tạc"}],"examples":[{"en":"She twisted the wet towel over the sink.","vi":"Cô ấy vắt chiếc khăn ướt ngay trên bồn rửa chén.","audioKind":"ex"},{"en":"Online reports sometimes twist scientific findings, making it difficult for readers to judge health risks accurately.","vi":"Các bản tin trực tuyến đôi khi bóp méo các phát hiện khoa học, khiến độc giả khó đánh giá chính xác các rủi ro sức khỏe.","audioKind":"ex2"}],"collocations":[{"en":"twist your ankle","vi":"trật mắt cá chân"},{"en":"a plot twist","vi":"cú twist cốt truyện"},{"en":"twist the facts","vi":"bóp méo sự thật"}],"wordFamily":["twisted (adj)"],"synonyms":[],"antonyms":[],"tipVi":"Twist vừa có thể chỉ hành động vặn xoắn vật lý, vừa có thể chỉ việc bóp méo sự thật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spoonful', 'en-b2-86', 'spoonful', '/ˈspuːnfʊl/', 'B2', 'một thìa đầy; một lượng bằng một muỗng', 'n.', 'spoon (n.)', NULL, 'Đây là danh từ chứ không phải tính từ; dạng số nhiều thông thường là spoonfuls.', 'She stirred a spoonful of honey into her tea.', NULL, 'Cô ấy khuấy một thìa mật ong vào tách trà của mình.', '{"wordId":"spoonful","ukIpa":"/ˈspuːnfʊl/","usIpa":"/ˈspuːnfʊl/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"The amount that a spoon can hold","vi":"một thìa đầy; một lượng bằng một muỗng"}],"examples":[{"en":"She stirred a spoonful of honey into her tea.","vi":"Cô ấy khuấy một thìa mật ong vào tách trà của mình.","audioKind":"ex"},{"en":"Adding several spoonfuls of sugar to drinks each day can substantially increase a person''s daily calorie intake.","vi":"Việc cho thêm vài thìa đường vào đồ uống mỗi ngày có thể làm tăng đáng kể lượng calo nạp vào cơ thể hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"a spoonful of sugar","vi":"một thìa đường"},{"en":"a heaped spoonful","vi":"một thìa vun đầy"},{"en":"a level spoonful","vi":"một thìa gạt ngang"}],"wordFamily":["spoon (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Đây là danh từ chứ không phải tính từ; dạng số nhiều thông thường là spoonfuls.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_brightness', 'en-b2-86', 'brightness', '/ˈbraɪtnəs/', 'B2', 'độ sáng; sự rực rỡ; sự tươi sáng; độ rực màu; sự thông minh; sự nhanh trí', 'n.', 'bright (adj.), brightly (adv.), brighten (v.)', 'Đồng nghĩa: luminosity, brilliance · Trái nghĩa: dimness, dullness', 'Là danh từ không đếm được; “độ sáng” của màn hình dùng brightness chứ không dùng lightness.', 'I lowered the screen''s brightness before watching a film.', NULL, 'Tôi đã giảm độ sáng của màn hình trước khi xem phim.', '{"wordId":"brightness","ukIpa":"/ˈbraɪtnəs/","usIpa":"/ˈbraɪtnəs/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"The amount of light something gives off or reflects.","vi":"độ sáng; sự rực rỡ"},{"pos":"n.","en":"The quality of having strong, vivid colours.","vi":"sự tươi sáng; độ rực màu"},{"pos":"n.","en":"The ability to understand and learn things quickly.","vi":"sự thông minh; sự nhanh trí"}],"examples":[{"en":"I lowered the screen''s brightness before watching a film.","vi":"Tôi đã giảm độ sáng của màn hình trước khi xem phim.","audioKind":"ex"},{"en":"Reducing the brightness of outdoor lighting at night can save energy and limit disruption to wildlife.","vi":"Việc giảm độ sáng của hệ thống chiếu sáng ngoài trời vào ban đêm có thể tiết kiệm năng lượng và hạn chế gây phiền toái cho động vật hoang dã.","audioKind":"ex2"}],"collocations":[{"en":"adjust the brightness","vi":"điều chỉnh độ sáng"},{"en":"screen brightness","vi":"độ sáng màn hình"},{"en":"the brightness of colours","vi":"độ rực rỡ của màu sắc"}],"wordFamily":["bright (adj.)","brightly (adv.)","brighten (v.)"],"synonyms":["luminosity","brilliance"],"antonyms":["dimness","dullness"],"tipVi":"Là danh từ không đếm được; “độ sáng” của màn hình dùng brightness chứ không dùng lightness.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_remainder', 'en-b2-86', 'remainder', '/rɪˈmeɪndər/', 'B2', 'phần còn lại; số dư; phấn số dư', 'n.', 'remain (v.), remaining (adj.)', 'Đồng nghĩa: rest', 'Thường dùng the remainder of; động từ theo sau chia số ít hay số nhiều tùy thuộc vào danh từ nó chỉ.', 'We ate half the cake and refrigerated the remainder.', NULL, 'Chúng tôi đã ăn một nửa chiếc bánh và cất phần còn lại vào tủ lạnh.', '{"wordId":"remainder","ukIpa":"/rɪˈmeɪndə/","usIpa":"/rɪˈmeɪndər/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"what is left after other parts are removed or used","vi":"phần còn lại; số dư"},{"pos":"n.","en":"the amount left when division does not produce a whole number","vi":"phấn số dư"}],"examples":[{"en":"We ate half the cake and refrigerated the remainder.","vi":"Chúng tôi đã ăn một nửa chiếc bánh và cất phần còn lại vào tủ lạnh.","audioKind":"ex"},{"en":"After funding essential services, the council allocated the remainder of its budget to improving public parks.","vi":"Sau khi cấp vốn cho các dịch vụ thiết yếu, hội đồng đã phân bổ phần ngân sách còn lại để cải tạo các công viên công cộng.","audioKind":"ex2"}],"collocations":[{"en":"the remainder of","vi":"phần còn lại của"},{"en":"for the remainder of","vi":"trong thời gian còn lại của"},{"en":"leave a remainder","vi":"để lại số dư"}],"wordFamily":["remain (v.)","remaining (adj.)"],"synonyms":["rest"],"antonyms":[],"tipVi":"Thường dùng the remainder of; động từ theo sau chia số ít hay số nhiều tùy thuộc vào danh từ nó chỉ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_appealing', 'en-b2-86', 'appealing', '/əˈpiːlɪŋ/', 'B2', 'hấp dẫn; lôi cuốn; cầu khẩn; van xin', 'adj.', 'appeal (v.), appeal (n.), unappealing (adj.)', 'Đồng nghĩa: attractive, inviting · Trái nghĩa: unappealing, unattractive', 'Diễn đạt "có sức hút đối với ai" dùng appealing to sb.', 'The sunny balcony makes this small flat especially appealing.', NULL, 'Ban công ngập tràn ánh nắng khiến căn hộ nhỏ này trở nên vô cùng hấp dẫn.', '{"wordId":"appealing","ukIpa":"/əˈpiːlɪŋ/","usIpa":"/əˈpiːlɪŋ/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"attractive or interesting enough to make people want it","vi":"hấp dẫn; lôi cuốn"},{"pos":"adj.","en":"showing a strong wish for help or sympathy","vi":"cầu khẩn; van xin"}],"examples":[{"en":"The sunny balcony makes this small flat especially appealing.","vi":"Ban công ngập tràn ánh nắng khiến căn hộ nhỏ này trở nên vô cùng hấp dẫn.","audioKind":"ex"},{"en":"Flexible working arrangements are particularly appealing to parents who need to balance employment with childcare responsibilities.","vi":"Các chế độ làm việc linh hoạt đặc biệt hấp dẫn đối với các bậc phụ huynh cần cân bằng giữa công việc và trách nhiệm chăm sóc con cái.","audioKind":"ex2"}],"collocations":[{"en":"appealing prospect","vi":"viễn cảnh hấp dẫn"},{"en":"visually appealing","vi":"hấp dẫn về mặt thị giác"},{"en":"appealing to consumers","vi":"hấp dẫn đối với người tiêu dùng"},{"en":"an appealing look","vi":"ánh mắt cầu xin"}],"wordFamily":["appeal (v.)","appeal (n.)","unappealing (adj.)"],"synonyms":["attractive","inviting"],"antonyms":["unappealing","unattractive"],"tipVi":"Diễn đạt \"có sức hút đối với ai\" dùng appealing to sb.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fluffy', 'en-b2-86', 'fluffy', '/ˈflʌfi/', 'B2', 'mọc lông tơ; mềm mại; xốp; nhẹ và mềm', 'adj.', 'fluff (n.), fluffiness (n.)', NULL, 'Khi mô tả lông, từ này có nghĩa là lông tơ; khi mô tả đồ ăn, nó có nghĩa là xốp mềm.', 'Our kitten curled up on a fluffy white blanket.', NULL, 'Chú mèo con của chúng tôi cuộn tròn trên chiếc chăn trắng mềm mại.', '{"wordId":"fluffy","ukIpa":"/ˈflʌfi/","usIpa":"/ˈflʌfi/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"covered with soft hair or having a soft, airy texture","vi":"mọc lông tơ; mềm mại"},{"pos":"adj.","en":"light and soft because of air inside","vi":"xốp; nhẹ và mềm"}],"examples":[{"en":"Our kitten curled up on a fluffy white blanket.","vi":"Chú mèo con của chúng tôi cuộn tròn trên chiếc chăn trắng mềm mại.","audioKind":"ex"},{"en":"Hotels often provide fluffy towels and comfortable bedding to improve guest satisfaction and encourage repeat visits.","vi":"Các khách sạn thường cung cấp khăn tắm mềm mại và bộ chăn ga thoải mái để nâng cao sự hài lòng của khách và khuyến khích họ quay lại.","audioKind":"ex2"}],"collocations":[{"en":"fluffy towel","vi":"khăn tắm mềm mại"},{"en":"fluffy clouds","vi":"những đám mây bông xốp"},{"en":"fluffy pancakes","vi":"bánh kếp xốp mềm"}],"wordFamily":["fluff (n.)","fluffiness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi mô tả lông, từ này có nghĩa là lông tơ; khi mô tả đồ ăn, nó có nghĩa là xốp mềm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_refreshment', 'en-b2-86', 'refreshment', '/rɪˈfreʃmənt/', 'B2', 'đồ ăn nhẹ và đồ uống; tiệc trà nhẹ; sự sảng khoái; sự phục hồi năng lượng', 'n.', 'refresh (v.), refreshing (adj.), refreshed (adj.)', NULL, 'Khi chỉ đồ ăn thức uống nhẹ, từ này thường dùng ở dạng số nhiều refreshments; khi chỉ sự sảng khoái tinh thần thì không đếm được.', 'They served refreshments in the garden after the meeting.', NULL, 'Họ đã phục vụ đồ ăn nhẹ và nước uống ngoài vườn sau cuộc họp.', '{"wordId":"refreshment","ukIpa":"/rɪˈfreʃmənt/","usIpa":"/rɪˈfreʃmənt/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"small amounts of food and drink, usually served during breaks","vi":"đồ ăn nhẹ và đồ uống; tiệc trà nhẹ"},{"pos":"n.","en":"the feeling of renewed energy after rest, food, or drink","vi":"sự sảng khoái; sự phục hồi năng lượng"}],"examples":[{"en":"They served refreshments in the garden after the meeting.","vi":"Họ đã phục vụ đồ ăn nhẹ và nước uống ngoài vườn sau cuộc họp.","audioKind":"ex"},{"en":"Providing free refreshments during community events can create a welcoming atmosphere and encourage informal conversations among residents.","vi":"Việc cung cấp đồ ăn nhẹ miễn phí trong các sự kiện cộng đồng có thể tạo ra bầu không khí thân thiện và khuyến khích cư dân giao lưu thoải mái với nhau.","audioKind":"ex2"}],"collocations":[{"en":"light refreshments","vi":"đồ ăn nhẹ đơn giản"},{"en":"serve refreshments","vi":"phục vụ đồ ăn nhẹ"},{"en":"refreshment break","vi":"giờ giải lao giữa giờ"}],"wordFamily":["refresh (v.)","refreshing (adj.)","refreshed (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ đồ ăn thức uống nhẹ, từ này thường dùng ở dạng số nhiều refreshments; khi chỉ sự sảng khoái tinh thần thì không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rapid', 'en-b2-86', 'rapid', '/ˈræpɪd/', 'B2', 'nhanh chóng; tốc độ cao; mau lẹ; vùng nước chảy xiết; đoạn sông ghềnh', 'adj.', 'rapidly (adv.), rapidity (n.)', 'Đồng nghĩa: fast, swift, quick · Trái nghĩa: slow, gradual', 'Tính từ rapid thường dùng để bổ nghĩa cho sự thay đổi hoặc tăng trưởng; từ chỉ dòng nước xiết thường dùng dạng số nhiều rapids.', 'Her rapid recovery surprised everyone in the family.', NULL, 'Sự hồi phục nhanh chóng của cô ấy khiến mọi người trong gia đình đều ngạc nhiên.', '{"wordId":"rapid","ukIpa":"/ˈræpɪd/","usIpa":"/ˈræpɪd/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Happening or moving very quickly.","vi":"nhanh chóng; tốc độ cao; mau lẹ"},{"pos":"n.","en":"A fast, turbulent stretch of river, usually called rapids.","vi":"vùng nước chảy xiết; đoạn sông ghềnh"}],"examples":[{"en":"Her rapid recovery surprised everyone in the family.","vi":"Sự hồi phục nhanh chóng của cô ấy khiến mọi người trong gia đình đều ngạc nhiên.","audioKind":"ex"},{"en":"Rapid urban growth often places considerable pressure on public transport, housing, and essential services.","vi":"Sự phát triển đô thị nhanh chóng thường tạo ra áp lực đáng kể lên hệ thống giao thông công cộng, nhà ở và các dịch vụ thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"rapid growth","vi":"sự tăng trưởng nhanh chóng"},{"en":"rapid change","vi":"sự thay đổi chóng mặt"},{"en":"rapid recovery","vi":"sự hồi phục nhanh chóng"},{"en":"white-water rapids","vi":"đoạn sông nước chảy xiết"}],"wordFamily":["rapidly (adv.)","rapidity (n.)"],"synonyms":["fast","swift","quick"],"antonyms":["slow","gradual"],"tipVi":"Tính từ rapid thường dùng để bổ nghĩa cho sự thay đổi hoặc tăng trưởng; từ chỉ dòng nước xiết thường dùng dạng số nhiều rapids.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pierce', 'en-b2-86', 'pierce', '/pɪrs/', 'B2', 'đâm thủng; chọc thủng bằng vật nhọn; xuyên qua; xé toạc bóng tối, sự im lặng hoặc rào cản', 'v.', 'piercing (n.), piercing (adj.)', 'Đồng nghĩa: puncture, penetrate', 'Xỏ khuyên tai thường nói have/get your ears pierced.', 'Use a fork to pierce the potato before baking.', NULL, 'Dùng nĩa xăm thủng củ khoai tây trước khi nướng.', '{"wordId":"pierce","ukIpa":"/pɪəs/","usIpa":"/pɪrs/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to make a hole through something with a sharp object","vi":"đâm thủng; chọc thủng bằng vật nhọn"},{"pos":"v.","en":"to pass sharply through darkness, silence, or another barrier","vi":"xuyên qua; xé toạc bóng tối, sự im lặng hoặc rào cản"}],"examples":[{"en":"Use a fork to pierce the potato before baking.","vi":"Dùng nĩa xăm thủng củ khoai tây trước khi nướng.","audioKind":"ex"},{"en":"Powerful artificial lights pierce the darkness around coastal developments, potentially disturbing the behaviour of nesting birds.","vi":"Ánh sáng nhân tạo mạnh mẽ xuyên qua bóng tối xung quanh các khu đô thị ven biển, có thể làm disturbed hành vi làm tổ của loài chim.","audioKind":"ex2"}],"collocations":[{"en":"pierce a hole","vi":"đâm một lỗ"},{"en":"have your ears pierced","vi":"xỏ khuyên tai"},{"en":"pierce the darkness","vi":"xuyên thủng màn đêm"}],"wordFamily":["piercing (n.)","piercing (adj.)"],"synonyms":["puncture","penetrate"],"antonyms":[],"tipVi":"Xỏ khuyên tai thường nói have/get your ears pierced.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_footstep', 'en-b2-86', 'footstep', '/ˈfʊtstep/', 'B2', 'bước chân; tiếng bước chân', 'n.', NULL, NULL, 'Thường dùng số nhiều; footprint chỉ dấu chân để lại.', 'I heard footsteps outside my bedroom and opened the door.', NULL, 'Tôi nghe thấy tiếng bước chân bên ngoài phòng ngủ của mình và liền mở cửa.', '{"wordId":"footstep","ukIpa":"/ˈfʊtstep/","usIpa":"/ˈfʊtstep/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"a step taken when walking, or the sound it makes","vi":"bước chân; tiếng bước chân"}],"examples":[{"en":"I heard footsteps outside my bedroom and opened the door.","vi":"Tôi nghe thấy tiếng bước chân bên ngoài phòng ngủ của mình và liền mở cửa.","audioKind":"ex"},{"en":"In shared housing, footsteps from upstairs can disturb residents and highlight the need for better sound insulation.","vi":"Trong nhà ở chung, tiếng bước chân từ trên lầu có thể làm phiền cư dân và nhấn mạnh nhu cầu cần cách âm tốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"hear footsteps","vi":"nghe tiếng bước chân"},{"en":"heavy footsteps","vi":"tiếng bước chân nặng nề"},{"en":"follow in someone''s footsteps","vi":"nối gót theo bước chân ai"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng số nhiều; footprint chỉ dấu chân để lại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_patio', 'en-b2-86', 'patio', '/ˈpætioʊ/', 'B2', 'sân hiên; hiên sau nhà (được lát nền để ngồi hoặc ăn uống)', 'n.', NULL, NULL, 'Thường chỉ khu vực thư giãn ngoài trời được lát nền cạnh ngôi nhà, không nhất thiết phải có tường bao quanh.', 'We ate breakfast on the patio beside the roses.', NULL, 'Chúng tôi ăn sáng trên hiên nhà bên cạnh những khóm hoa hồng.', '{"wordId":"patio","ukIpa":"/ˈpætiəʊ/","usIpa":"/ˈpætioʊ/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"a paved outdoor area beside a house for sitting or eating","vi":"sân hiên; hiên sau nhà (được lát nền để ngồi hoặc ăn uống)"}],"examples":[{"en":"We ate breakfast on the patio beside the roses.","vi":"Chúng tôi ăn sáng trên hiên nhà bên cạnh những khóm hoa hồng.","audioKind":"ex"},{"en":"A shaded patio can provide residents with a comfortable outdoor space during the warmer months.","vi":"Sân hiên có mái che có thể mang đến cho cư dân một không gian ngoài trời thoải mái trong những tháng trời ấm áp.","audioKind":"ex2"}],"collocations":[{"en":"patio furniture","vi":"đồ nội thất sân hiên"},{"en":"on the patio","vi":"trên sân hiên"},{"en":"a shaded patio","vi":"sân hiên có mái che"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ khu vực thư giãn ngoài trời được lát nền cạnh ngôi nhà, không nhất thiết phải có tường bao quanh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_superb', 'en-b2-86', 'superb', '/suːˈpɝːb/', 'B2', 'tuyệt vời; xuất sắc', 'adj.', 'superbly (adv.)', 'Đồng nghĩa: excellent, outstanding, splendid · Trái nghĩa: terrible, awful', 'Bản thân từ này đã hàm ý mức độ rất cao, thông thường không dùng very superb.', 'We enjoyed a superb meal overlooking the quiet harbour.', NULL, 'Chúng tôi đã thưởng thức một bữa ăn tuyệt vời nhìn ra khung cảnh bến cảng yên bình.', '{"wordId":"superb","ukIpa":"/suːˈpɜːb/","usIpa":"/suːˈpɝːb/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Extremely good in quality or performance.","vi":"tuyệt vời; xuất sắc"}],"examples":[{"en":"We enjoyed a superb meal overlooking the quiet harbour.","vi":"Chúng tôi đã thưởng thức một bữa ăn tuyệt vời nhìn ra khung cảnh bến cảng yên bình.","audioKind":"ex"},{"en":"The museum offers superb educational facilities, allowing visitors of all ages to explore scientific ideas through practical activities.","vi":"Bảo tàng cung cấp các cơ sở giáo dục xuất sắc, cho phép khách tham quan ở mọi lứa tuổi khám phá các khái niệm khoa học thông qua các hoạt động thực tế.","audioKind":"ex2"}],"collocations":[{"en":"superb performance","vi":"màn trình diễn tuyệt vời"},{"en":"superb quality","vi":"chất lượng tuyệt hảo"},{"en":"superb view","vi":"cảnh quan tuyệt đẹp"}],"wordFamily":["superbly (adv.)"],"synonyms":["excellent","outstanding","splendid"],"antonyms":["terrible","awful"],"tipVi":"Bản thân từ này đã hàm ý mức độ rất cao, thông thường không dùng very superb.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_coincidence', 'en-b2-86', 'coincidence', '/koʊˈɪnsɪdəns/', 'B2', 'sự trùng hợp; tình cờ', 'n.', 'coincide (v.), coincidental (adj.), coincidentally (adv.)', 'Đồng nghĩa: chance', 'Dùng by coincidence để chỉ sự tình cờ; dùng pure coincidence để nhấn mạnh thuần túy là trùng hợp.', 'By coincidence, we both wore green jackets to lunch.', NULL, 'Thật tình cờ, cả hai chúng tôi đều mặc áo khoác xanh đi ăn trưa.', '{"wordId":"coincidence","ukIpa":"/kəʊˈɪnsɪdəns/","usIpa":"/koʊˈɪnsɪdəns/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"an unexpected connection between events that have no apparent cause","vi":"sự trùng hợp; tình cờ"}],"examples":[{"en":"By coincidence, we both wore green jackets to lunch.","vi":"Thật tình cờ, cả hai chúng tôi đều mặc áo khoác xanh đi ăn trưa.","audioKind":"ex"},{"en":"Researchers must distinguish between coincidence and genuine causal relationships when interpreting changes in public health data.","vi":"Các nhà nghiên cứu phải phân biệt giữa sự trùng hợp ngẫu nhiên và mối quan hệ nhân quả thực sự khi giải thích các thay đổi trong dữ liệu y tế công cộng.","audioKind":"ex2"}],"collocations":[{"en":"by coincidence","vi":"tình cờ; ngẫu nhiên"},{"en":"pure coincidence","vi":"hoàn toàn là sự trùng hợp"},{"en":"a remarkable coincidence","vi":"một sự trùng hợp đáng kinh ngạc"},{"en":"a strange coincidence","vi":"một sự trùng hợp lạ lùng"}],"wordFamily":["coincide (v.)","coincidental (adj.)","coincidentally (adv.)"],"synonyms":["chance"],"antonyms":[],"tipVi":"Dùng by coincidence để chỉ sự tình cờ; dùng pure coincidence để nhấn mạnh thuần túy là trùng hợp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flush', 'en-b2-86', 'flush', '/flʌʃ/', 'B2', 'xả nước; rửa sạch; đỏ bừng mặt; bằng phẳng; ngang bằng', 'v.', 'flushed (adj.)', NULL, 'Cụm flush with có thể chỉ vị trí nằm phẳng ngang bề mặt, hoặc chỉ tình trạng tài chính dồi dào.', 'Please flush the toilet before you leave the bathroom.', NULL, 'Vui lòng xả nước bồn cầu trước khi bạn rời khỏi phòng vệ sinh.', '{"wordId":"flush","ukIpa":"/flʌʃ/","usIpa":"/flʌʃ/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"clean or clear something by sending water through it","vi":"xả nước; rửa sạch"},{"pos":"v.","en":"become red in the face from emotion, heat, or illness","vi":"đỏ bừng mặt"},{"pos":"adj.","en":"level with another surface, without sticking out","vi":"bằng phẳng; ngang bằng"}],"examples":[{"en":"Please flush the toilet before you leave the bathroom.","vi":"Vui lòng xả nước bồn cầu trước khi bạn rời khỏi phòng vệ sinh.","audioKind":"ex"},{"en":"Modern buildings can reduce water consumption by using collected rainwater to flush toilets instead of drinking water.","vi":"Các tòa nhà hiện đại có thể giảm lượng nước tiêu thụ bằng cách sử dụng nước mưa đã thu gom để xả bồn cầu thay vì dùng nước uống.","audioKind":"ex2"}],"collocations":[{"en":"flush the toilet","vi":"xả bồn cầu"},{"en":"flush with embarrassment","vi":"đỏ mặt vì xấu hổ"},{"en":"flush with the wall","vi":"ngang bằng với bức tường"},{"en":"a flush of colour","vi":"một thoáng đỏ bừng (mặt)"}],"wordFamily":["flushed (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm flush with có thể chỉ vị trí nằm phẳng ngang bề mặt, hoặc chỉ tình trạng tài chính dồi dào.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_crust', 'en-b2-86', 'crust', '/krʌst/', 'B2', 'vỏ bánh mì; lớp vỏ bánh; vỏ Trái Đất; lớp vỏ cứng trên bề mặt', 'n.', 'crusty (adj.)', NULL, 'Vỏ Trái Đất dùng the Earth''s crust; vỏ bánh mì cũng dùng crust.', 'This fresh bread has a wonderfully crisp crust.', NULL, 'Ổ bánh mì tươi này có lớp vỏ giòn rụm tuyệt vời.', '{"wordId":"crust","ukIpa":"/krʌst/","usIpa":"/krʌst/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"The firm outer layer of bread or pastry.","vi":"vỏ bánh mì; lớp vỏ bánh"},{"pos":"n.","en":"The solid outer layer of the Earth.","vi":"vỏ Trái Đất"},{"pos":"n.","en":"A hard layer that forms on a surface.","vi":"lớp vỏ cứng trên bề mặt"}],"examples":[{"en":"This fresh bread has a wonderfully crisp crust.","vi":"Ổ bánh mì tươi này có lớp vỏ giòn rụm tuyệt vời.","audioKind":"ex"},{"en":"Movements within the Earth''s crust can cause earthquakes that severely damage buildings and transport networks.","vi":"Các chuyển động bên trong lớp vỏ Trái Đất có thể gây ra động đất làm hư hại nặng nề các tòa nhà và hệ thống giao thông.","audioKind":"ex2"}],"collocations":[{"en":"bread crust","vi":"vỏ bánh mì"},{"en":"the Earth''s crust","vi":"vỏ Trái Đất"},{"en":"a thin crust","vi":"lớp vỏ mỏng"}],"wordFamily":["crusty (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Vỏ Trái Đất dùng the Earth''s crust; vỏ bánh mì cũng dùng crust.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plunge', 'en-b2-86', 'plunge', '/plʌndʒ/', 'B2', 'lao xuống; cắm mạnh vào; giảm mạnh; lao dốc; cú lao xuống; sự sụt giảm mạnh', 'v.', NULL, NULL, 'plunge into có thể mang nghĩa vật lý là nhảy vào, hoặc nghĩa bóng là đột ngột rơi vào một trạng thái nào đó.', 'He plunged his muddy boots into a bucket of water.', NULL, 'Anh ấy nhúng đôi ủng dính bùn của mình vào một xô nước.', '{"wordId":"plunge","ukIpa":"/plʌndʒ/","usIpa":"/plʌndʒ/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To move or push something suddenly and forcefully into something.","vi":"lao xuống; cắm mạnh vào"},{"pos":"v.","en":"To decrease suddenly and sharply.","vi":"giảm mạnh; lao dốc"},{"pos":"n.","en":"A sudden dive, fall, or sharp decrease.","vi":"cú lao xuống; sự sụt giảm mạnh"}],"examples":[{"en":"He plunged his muddy boots into a bucket of water.","vi":"Anh ấy nhúng đôi ủng dính bùn của mình vào một xô nước.","audioKind":"ex"},{"en":"Tourism revenue may plunge when extreme weather forces popular coastal resorts to close during peak season.","vi":"Doanh thu du lịch có thể lao dốc khi thời tiết cực đoan buộc các khu nghỉ dưỡng ven biển nổi tiếng phải đóng cửa vào mùa cao điểm.","audioKind":"ex2"}],"collocations":[{"en":"plunge into water","vi":"lao xuống nước"},{"en":"plunge sharply","vi":"giảm mạnh"},{"en":"take the plunge","vi":"quyết định liều lĩnh"},{"en":"plunge into debt","vi":"rơi vào cảnh nợ nần"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"plunge into có thể mang nghĩa vật lý là nhảy vào, hoặc nghĩa bóng là đột ngột rơi vào một trạng thái nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tremendous', 'en-b2-86', 'tremendous', '/trɪˈmendəs/', 'B2', 'lớn lao; khổng lồ; cực kỳ; tuyệt vời; xuất sắc', 'adj.', 'tremendously (adv.)', 'Đồng nghĩa: enormous, immense · Trái nghĩa: tiny', 'Thường nhấn mạnh mức độ hoặc số lượng cực kỳ lớn, không chỉ nói về kích thước vật lý.', 'Moving that heavy sofa upstairs took a tremendous effort.', NULL, 'Việc chuyển chiếc sofa nặng nề đó lên lầu tốn một khoảng sức lực cực kỳ lớn.', '{"wordId":"tremendous","ukIpa":"/trɪˈmendəs/","usIpa":"/trɪˈmendəs/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Very great in amount, strength, or degree.","vi":"lớn lao; khổng lồ; cực kỳ"},{"pos":"adj.","en":"Extremely good or enjoyable.","vi":"tuyệt vời; xuất sắc"}],"examples":[{"en":"Moving that heavy sofa upstairs took a tremendous effort.","vi":"Việc chuyển chiếc sofa nặng nề đó lên lầu tốn một khoảng sức lực cực kỳ lớn.","audioKind":"ex"},{"en":"Rapid urban growth places tremendous pressure on housing, transport networks and essential public services.","vi":"Sự phát triển đô thị nhanh chóng đặt ra áp lực khổng lồ đối với nhà ở, hệ thống giao thông và các dịch vụ công cộng thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"tremendous pressure","vi":"áp lực khổng lồ"},{"en":"a tremendous effort","vi":"nỗ lực cực lớn"},{"en":"tremendous growth","vi":"sự tăng trưởng mạnh mẽ"},{"en":"a tremendous achievement","vi":"một thành tựu to lớn"}],"wordFamily":["tremendously (adv.)"],"synonyms":["enormous","immense"],"antonyms":["tiny"],"tipVi":"Thường nhấn mạnh mức độ hoặc số lượng cực kỳ lớn, không chỉ nói về kích thước vật lý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_trap', 'en-b2-86', 'trap', '/træp/', 'B2', 'cái bẫy; dụng cụ bắt bẫy; giam giữ; bẫy; làm cho không thể thoát; cạm bẫy; hoàn cảnh khó khăn', 'n.', 'trapped (adj.), trapper (n.)', NULL, 'Các dạng quá khứ trapped và hiện phân từ trapping đều nhân đôi chữ cái p.', 'We found a mouse inside the humane trap this morning.', NULL, 'Chúng tôi đã tìm thấy một con chuột bên trong chiếc bẫy nhân đạo sáng nay.', '{"wordId":"trap","ukIpa":"/træp/","usIpa":"/træp/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A device or concealed danger designed to catch someone or something","vi":"cái bẫy; dụng cụ bắt bẫy"},{"pos":"v.","en":"To catch or keep someone somewhere they cannot escape","vi":"giam giữ; bẫy; làm cho không thể thoát"},{"pos":"n.","en":"A situation that deceives people or is difficult to escape","vi":"cạm bẫy; hoàn cảnh khó khăn"}],"examples":[{"en":"We found a mouse inside the humane trap this morning.","vi":"Chúng tôi đã tìm thấy một con chuột bên trong chiếc bẫy nhân đạo sáng nay.","audioKind":"ex"},{"en":"High housing costs can trap families in poverty by leaving little money for education or training.","vi":"Chi phí nhà ở cao có thể đẩy các gia đình vào cảnh nghèo đói do không còn tiền cho giáo dục hay đào tạo.","audioKind":"ex2"}],"collocations":[{"en":"set a trap","vi":"đặt bẫy"},{"en":"fall into a trap","vi":"rơi vào bẫy"},{"en":"be trapped in","vi":"bị mắc kẹt trong"},{"en":"poverty trap","vi":"bẫy nghèo đói"}],"wordFamily":["trapped (adj.)","trapper (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Các dạng quá khứ trapped và hiện phân từ trapping đều nhân đôi chữ cái p.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grip', 'en-b2-86', 'grip', '/ɡrɪp/', 'B2', 'nắm chặt; bám chặt; sự nắm chặt; lực bám; sự kiểm soát; quyền lực chi phối', 'v.', 'gripping (adj.)', 'Đồng nghĩa: grasp, clutch · Trái nghĩa: release', 'Quá khứ gripped và phân từ hiện tại gripping đều nhân đôi chữ p.', 'She gripped the railing as the boat rocked gently.', NULL, 'Cô ấy bám chặt lấy thanh lan can khi con thuyền chòng chành nhẹ.', '{"wordId":"grip","ukIpa":"/ɡrɪp/","usIpa":"/ɡrɪp/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to hold something firmly","vi":"nắm chặt; bám chặt"},{"pos":"n.","en":"a firm hold on something","vi":"sự nắm chặt; lực bám"},{"pos":"n.","en":"power or control over someone or something","vi":"sự kiểm soát; quyền lực chi phối"}],"examples":[{"en":"She gripped the railing as the boat rocked gently.","vi":"Cô ấy bám chặt lấy thanh lan can khi con thuyền chòng chành nhẹ.","audioKind":"ex"},{"en":"Large companies maintain a strong grip on the market, making it difficult for smaller businesses to compete.","vi":"Các công ty lớn duy trì sự kiểm soát mạnh mẽ đối với thị trường, khiến các doanh nghiệp nhỏ khó lòng cạnh tranh.","audioKind":"ex2"}],"collocations":[{"en":"grip tightly","vi":"nắm chặt"},{"en":"a firm grip","vi":"cái nắm tay chắc chắn"},{"en":"lose your grip","vi":"mất kiểm soát; tuột tay"},{"en":"a grip on power","vi":"sự nắm quyền"}],"wordFamily":["gripping (adj.)"],"synonyms":["grasp","clutch"],"antonyms":["release"],"tipVi":"Quá khứ gripped và phân từ hiện tại gripping đều nhân đôi chữ p.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cork', 'en-b2-86', 'cork', '/kɔːrk/', 'B2', 'vỏ bần; gỗ bần; nút bần; nút chai; đóng nút bần', 'n.', 'uncork (v.)', NULL, 'Chỉ vật liệu bần thì không đếm được; chỉ nút bần thì đếm được.', 'The cork popped out and rolled under the table.', NULL, 'Nút bần bật ra và lăn xuống dưới gầm bàn.', '{"wordId":"cork","ukIpa":"/kɔːk/","usIpa":"/kɔːrk/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"a light material from tree bark, used for sealing bottles","vi":"vỏ bần; gỗ bần"},{"pos":"n.","en":"a piece of cork used to close a bottle","vi":"nút bần; nút chai"},{"pos":"v.","en":"to close a bottle with a cork","vi":"đóng nút bần"}],"examples":[{"en":"The cork popped out and rolled under the table.","vi":"Nút bần bật ra và lăn xuống dưới gầm bàn.","audioKind":"ex"},{"en":"Cork is a renewable material that can be harvested without cutting down the entire tree.","vi":"Gỗ bần là một vật liệu tái tạo có thể thu hoạch mà không cần phải đốn hạ toàn bộ cây.","audioKind":"ex2"}],"collocations":[{"en":"a cork stopper","vi":"nút bần"},{"en":"cork flooring","vi":"sàn gỗ bần"},{"en":"remove the cork","vi":"rút nút bần"}],"wordFamily":["uncork (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ vật liệu bần thì không đếm được; chỉ nút bần thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tempt', 'en-b2-86', 'tempt', '/tempt/', 'B2', 'cám dỗ; lôi cuốn; thu hút', 'v.', 'temptation (n.), tempting (adj.), temptingly (adv.)', 'Đồng nghĩa: entice, lure · Trái nghĩa: deter', 'Thường dùng cấu trúc tempt sb to do hoặc tempt sb into doing.', 'The fresh pastries tempted me to enter the bakery.', NULL, 'Những chiếc bánh ngọt tươi ngon đã lôi kéo tôi bước vào tiệm bánh.', '{"wordId":"tempt","ukIpa":"/tempt/","usIpa":"/tempt/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To make someone want something or want to do something.","vi":"cám dỗ; lôi cuốn; thu hút"}],"examples":[{"en":"The fresh pastries tempted me to enter the bakery.","vi":"Những chiếc bánh ngọt tươi ngon đã lôi kéo tôi bước vào tiệm bánh.","audioKind":"ex"},{"en":"Heavy discounts may tempt consumers to purchase products they neither need nor originally intended to buy.","vi":"Các đợt giảm giá mạnh có thể cám dỗ người tiêu dùng mua những sản phẩm mà họ không cần và ban đầu cũng không có ý định mua.","audioKind":"ex2"}],"collocations":[{"en":"tempt someone into doing something","vi":"dụ dỗ ai làm gì"},{"en":"be tempted to do something","vi":"rất muốn làm gì"},{"en":"tempt fate","vi":"liều lĩnh; thách thức rủi ro"}],"wordFamily":["temptation (n.)","tempting (adj.)","temptingly (adv.)"],"synonyms":["entice","lure"],"antonyms":["deter"],"tipVi":"Thường dùng cấu trúc tempt sb to do hoặc tempt sb into doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_necessity', 'en-b2-86', 'necessity', '/nəˈsesəti/', 'B2', 'sự cần thiết; tính tất yếu; nhu yếu phẩm; vật dụng thiết yếu', 'n.', 'necessary (adj.), necessarily (adv.), unnecessary (adj.), necessitate (v.)', 'Đồng nghĩa: need, essential · Trái nghĩa: luxury', 'Khi chỉ sự cần thiết, từ này thường không đếm được; khi chỉ vật thiết yếu, nó đếm được và thường dùng số nhiều.', 'Living far from town makes a car a necessity.', NULL, 'Sống cách xa thị trấn khiến ô tô trở thành một thứ thiết yếu.', '{"wordId":"necessity","ukIpa":"/nəˈsesəti/","usIpa":"/nəˈsesəti/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"the need for something or for something to happen","vi":"sự cần thiết; tính tất yếu"},{"pos":"n.","en":"something essential for everyday life","vi":"nhu yếu phẩm; vật dụng thiết yếu"}],"examples":[{"en":"Living far from town makes a car a necessity.","vi":"Sống cách xa thị trấn khiến ô tô trở thành một thứ thiết yếu.","audioKind":"ex"},{"en":"The rising cost of housing highlights the necessity of providing affordable homes for low-income families.","vi":"Chi phí nhà ở tăng cao làm nổi bật sự cần thiết của việc cung cấp nhà ở giá rẻ cho các gia đình thu nhập thấp.","audioKind":"ex2"}],"collocations":[{"en":"basic necessities","vi":"nhu yếu phẩm cơ bản"},{"en":"a necessity for","vi":"vật dụng thiết yếu cho"},{"en":"out of necessity","vi":"vì sự cần thiết; do hoàn cảnh bắt buộc"}],"wordFamily":["necessary (adj.)","necessarily (adv.)","unnecessary (adj.)","necessitate (v.)"],"synonyms":["need","essential"],"antonyms":["luxury"],"tipVi":"Khi chỉ sự cần thiết, từ này thường không đếm được; khi chỉ vật thiết yếu, nó đếm được và thường dùng số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_86_1', 'en-b2-86', 'Cách dùng “refreshment” (n.) — đồ ăn nhẹ và đồ uống; tiệc trà nhẹ', 'light refreshments  ·  serve refreshments  ·  refreshment break', 'Khi chỉ đồ ăn thức uống nhẹ, từ này thường dùng ở dạng số nhiều refreshments; khi chỉ sự sảng khoái tinh thần thì không đếm được.', 'Họ từ (Word Family): refresh (v.), refreshing (adj.), refreshed (adj.)', '[{"hanzi":"They served refreshments in the garden after the meeting.","pinyin":"","meaning":"Họ đã phục vụ đồ ăn nhẹ và nước uống ngoài vườn sau cuộc họp."},{"hanzi":"Providing free refreshments during community events can create a welcoming atmosphere and encourage informal conversations among residents.","pinyin":"","meaning":"Việc cung cấp đồ ăn nhẹ miễn phí trong các sự kiện cộng đồng có thể tạo ra bầu không khí thân thiện và khuyến khích cư dân giao lưu thoải mái với nhau."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_86_2', 'en-b2-86', 'Cách dùng “rapid” (adj.) — nhanh chóng; tốc độ cao; mau lẹ', 'rapid growth  ·  rapid change  ·  rapid recovery', 'Tính từ rapid thường dùng để bổ nghĩa cho sự thay đổi hoặc tăng trưởng; từ chỉ dòng nước xiết thường dùng dạng số nhiều rapids.', 'Họ từ (Word Family): rapidly (adv.), rapidity (n.) | Đồng nghĩa: fast, swift, quick · Trái nghĩa: slow, gradual', '[{"hanzi":"Her rapid recovery surprised everyone in the family.","pinyin":"","meaning":"Sự hồi phục nhanh chóng của cô ấy khiến mọi người trong gia đình đều ngạc nhiên."},{"hanzi":"Rapid urban growth often places considerable pressure on public transport, housing, and essential services.","pinyin":"","meaning":"Sự phát triển đô thị nhanh chóng thường tạo ra áp lực đáng kể lên hệ thống giao thông công cộng, nhà ở và các dịch vụ thiết yếu."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_86_3', 'en-b2-86', 'Cách dùng “necessity” (n.) — sự cần thiết; tính tất yếu', 'basic necessities  ·  a necessity for  ·  out of necessity', 'Khi chỉ sự cần thiết, từ này thường không đếm được; khi chỉ vật thiết yếu, nó đếm được và thường dùng số nhiều.', 'Họ từ (Word Family): necessary (adj.), necessarily (adv.), unnecessary (adj.), necessitate (v.) | Đồng nghĩa: need, essential · Trái nghĩa: luxury', '[{"hanzi":"Living far from town makes a car a necessity.","pinyin":"","meaning":"Sống cách xa thị trấn khiến ô tô trở thành một thứ thiết yếu."},{"hanzi":"The rising cost of housing highlights the necessity of providing affordable homes for low-income families.","pinyin":"","meaning":"Chi phí nhà ở tăng cao làm nổi bật sự cần thiết của việc cung cấp nhà ở giá rẻ cho các gia đình thu nhập thấp."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_86_4', 'en-b2-86', 'Cách dùng “patio” (n.) — sân hiên; hiên sau nhà (được lát nền để ngồi hoặc ăn uống)', 'patio furniture  ·  on the patio  ·  a shaded patio', 'Thường chỉ khu vực thư giãn ngoài trời được lát nền cạnh ngôi nhà, không nhất thiết phải có tường bao quanh.', NULL, '[{"hanzi":"We ate breakfast on the patio beside the roses.","pinyin":"","meaning":"Chúng tôi ăn sáng trên hiên nhà bên cạnh những khóm hoa hồng."},{"hanzi":"A shaded patio can provide residents with a comfortable outdoor space during the warmer months.","pinyin":"","meaning":"Sân hiên có mái che có thể mang đến cho cư dân một không gian ngoài trời thoải mái trong những tháng trời ấm áp."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_86_1', 'en-b2-86', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
