INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_86_1_7', 'ten_b2_86_1', 'brightness', 'I lowered the screen''s brightness before watching a film.', 'I lowered the screen''s brightness before watching a film.', '/ˈbraɪtnəs/', 'Tôi đã giảm độ sáng của màn hình trước khi xem phim.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_86_1_8', 'ten_b2_86_1', 'remainder', 'We ate half the cake and refrigerated the remainder.', 'We ate half the cake and refrigerated the remainder.', '/rɪˈmeɪndər/', 'Chúng tôi đã ăn một nửa chiếc bánh và cất phần còn lại vào tủ lạnh.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_86_1_1', 'en-b2-86', 'ten_b2_86_1', 'listening', 'listening', 'She wore a soft flannel shirt over her T-shirt.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy bám chặt lấy thanh lan can khi con thuyền chòng chành nhẹ.","Cô ấy khoác một chiếc áo sơ mi flannel mềm mại bên ngoài chiếc áo phông.","Việc chuyển chiếc sofa nặng nề đó lên lầu tốn một khoảng sức lực cực kỳ lớn.","Chúng tôi đã ăn một nửa chiếc bánh và cất phần còn lại vào tủ lạnh."]'::jsonb, 1, 'She wore a soft flannel shirt over her T-shirt. → Cô ấy khoác một chiếc áo sơ mi flannel mềm mại bên ngoài chiếc áo phông.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_86_1_2', 'en-b2-86', 'ten_b2_86_1', 'listening', 'listening', 'The lakeside garden provides a peaceful setting for lunch.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những chiếc bánh ngọt tươi ngon đã lôi kéo tôi bước vào tiệm bánh.","Thật tình cờ, cả hai chúng tôi đều mặc áo khoác xanh đi ăn trưa.","Cô ấy vắt chiếc khăn ướt ngay trên bồn rửa chén.","Khu vườn ven hồ tạo nên một khung cảnh yên bình cho bữa trưa."]'::jsonb, 3, 'The lakeside garden provides a peaceful setting for lunch. → Khu vườn ven hồ tạo nên một khung cảnh yên bình cho bữa trưa.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_86_1_3', 'en-b2-86', 'ten_b2_86_1', 'listening', 'listening', 'A strand of hair fell across her face.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Anh ấy nhúng đôi ủng dính bùn của mình vào một xô nước.","Sống cách xa thị trấn khiến ô tô trở thành một thứ thiết yếu.","Một lọn tóc xõa ngang khuôn mặt cô ấy.","Cô ấy bám chặt lấy thanh lan can khi con thuyền chòng chành nhẹ."]'::jsonb, 2, 'A strand of hair fell across her face. → Một lọn tóc xõa ngang khuôn mặt cô ấy.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_86_2', 'en-b2-86', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_86_2_1', 'ten_b2_86_2', 'flannel', 'In colder climates, flannel clothing provides practical warmth and can reduce reliance on intensive indoor heating.', 'In colder climates, flannel clothing provides practical warmth and can reduce reliance on intensive indoor heating.', '/ˈflænl/', 'Ở những vùng khí hậu lạnh hơn, trang phục bằng vải flannel mang lại sự ấm áp thiết thực và có thể làm giảm sự phụ thuộc vào hệ thống sưởi trong nhà cường độ cao.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_86_2_2', 'ten_b2_86_2', 'setting', 'Children often develop stronger communication skills in a supportive educational setting that encourages cooperation rather than competition.', 'Children often develop stronger communication skills in a supportive educational setting that encourages cooperation rather than competition.', '/ˈsetɪŋ/', 'Trẻ em thường phát triển các kỹ năng giao tiếp tốt hơn trong một môi trường giáo dục mang tính hỗ trợ, nơi khuyến khích sự hợp tác thay vì cạnh tranh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_86_2_3', 'ten_b2_86_2', 'strand', 'Improving public transport is one strand of a broader strategy to reduce urban air pollution.', 'Improving public transport is one strand of a broader strategy to reduce urban air pollution.', '/strænd/', 'Cải thiện giao thông công cộng là một khía cạnh của chiến lược rộng lớn hơn nhằm giảm ô nhiễm không khí đô thị.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_86_2_4', 'ten_b2_86_2', 'crisp', 'Packaging helps keep snacks crisp, but excessive use of plastic creates significant environmental problems.', 'Packaging helps keep snacks crisp, but excessive use of plastic creates significant environmental problems.', '/krɪsp/', 'Bao bì giúp giữ cho đồ ăn nhẹ giòn ngon, nhưng việc lạm dụng nhựa gây ra các vấn đề môi trường nghiêm trọng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_86_2_5', 'ten_b2_86_2', 'twist', 'Online reports sometimes twist scientific findings, making it difficult for readers to judge health risks accurately.', 'Online reports sometimes twist scientific findings, making it difficult for readers to judge health risks accurately.', '/twɪst/', 'Các bản tin trực tuyến đôi khi bóp méo các phát hiện khoa học, khiến độc giả khó đánh giá chính xác các rủi ro sức khỏe.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_86_2_6', 'ten_b2_86_2', 'spoonful', 'Adding several spoonfuls of sugar to drinks each day can substantially increase a person''s daily calorie intake.', 'Adding several spoonfuls of sugar to drinks each day can substantially increase a person''s daily calorie intake.', '/ˈspuːnfʊl/', 'Việc cho thêm vài thìa đường vào đồ uống mỗi ngày có thể làm tăng đáng kể lượng calo nạp vào cơ thể hàng ngày.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_86_2_1', 'en-b2-86', 'ten_b2_86_2', 'listening', 'listening', 'In colder climates, flannel clothing provides practical warmth and can reduce reliance on intensive indoor heating.', NULL, 'Trong câu vừa nghe, từ “flannel” mang nghĩa nào sau đây?', '["sự hạn chế; quy định hạn chế","tầm quan trọng; ý nghĩa","vải flannel (vải dạ mềm bằng cotton hoặc len)","cô đơn; buồn tủi"]'::jsonb, 2, '“flannel” (/ˈflænl/): vải flannel (vải dạ mềm bằng cotton hoặc len). Câu đầy đủ: In colder climates, flannel clothing provides practical warmth and can reduce reliance on intensive indoor heating.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_86_2_2', 'en-b2-86', 'ten_b2_86_2', 'listening', 'listening', 'Children often develop stronger communication skills in a supportive educational setting that encourages cooperation rather than competition.', NULL, 'Trong câu vừa nghe, từ “setting” mang nghĩa nào sau đây?', '["môi trường; bối cảnh; khung cảnh","thuộc về thẩm mỹ; để làm đẹp","dung tích; sức chứa","hiệp sĩ"]'::jsonb, 0, '“setting” (/ˈsetɪŋ/): môi trường; bối cảnh; khung cảnh. Câu đầy đủ: Children often develop stronger communication skills in a supportive educational setting that encourages cooperation rather than competition.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
