INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_86_2', 'en-b2-86', NULL, 'comprehensive_test', 'listening', 'The lakeside garden provides a peaceful setting for lunch.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Dùng nĩa xăm thủng củ khoai tây trước khi nướng.","Khu vườn ven hồ tạo nên một khung cảnh yên bình cho bữa trưa.","Thật tình cờ, cả hai chúng tôi đều mặc áo khoác xanh đi ăn trưa.","Ban công ngập tràn ánh nắng khiến căn hộ nhỏ này trở nên vô cùng hấp dẫn."]'::jsonb, 1, 'The lakeside garden provides a peaceful setting for lunch. → Khu vườn ven hồ tạo nên một khung cảnh yên bình cho bữa trưa.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_86_3', 'en-b2-86', NULL, 'comprehensive_test', 'listening', 'strand', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["lỗ khóa; ổ khóa","cái xẻng","sợi; lọn; dải","vết bầm tím; vết thâm"]'::jsonb, 2, 'strand (/strænd/) → sợi; lọn; dải; khía cạnh; yếu tố; phần; làm cho mắc kẹt; bỏ lại', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_86_4', 'en-b2-86', NULL, 'comprehensive_test', 'listening', 'The apple was crisp and sweet with every bite.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Quả táo vừa giòn vừa ngọt trong từng miếng cắn.","Sống cách xa thị trấn khiến ô tô trở thành một thứ thiết yếu.","Việc chuyển chiếc sofa nặng nề đó lên lầu tốn một khoảng sức lực cực kỳ lớn.","Cô ấy vắt chiếc khăn ướt ngay trên bồn rửa chén."]'::jsonb, 0, 'The apple was crisp and sweet with every bite. → Quả táo vừa giòn vừa ngọt trong từng miếng cắn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_86_5', 'en-b2-86', NULL, 'comprehensive_test', 'listening', 'twist', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["vặn; xoắn; xoay","sự phỏng đoán; sự phỏng đoán không có đủ bằng chứng chắc chắn","nhận thức được; có ý thức về","khỉ đột"]'::jsonb, 0, 'twist (/twɪst/) → vặn; xoắn; xoay; cú ngoặt bất ngờ; tình tiết bất ngờ; bóp méo; xuyên tạc', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_86_6', 'en-b2-86', NULL, 'comprehensive_test', 'listening', 'She stirred a spoonful of honey into her tea.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chú mèo con của chúng tôi cuộn tròn trên chiếc chăn trắng mềm mại.","Ban công ngập tràn ánh nắng khiến căn hộ nhỏ này trở nên vô cùng hấp dẫn.","Cô ấy bám chặt lấy thanh lan can khi con thuyền chòng chành nhẹ.","Cô ấy khuấy một thìa mật ong vào tách trà của mình."]'::jsonb, 3, 'She stirred a spoonful of honey into her tea. → Cô ấy khuấy một thìa mật ong vào tách trà của mình.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
