INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_86_8', 'en-b2-86', NULL, 'comprehensive_test', 'listening', 'We ate half the cake and refrigerated the remainder.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi ăn sáng trên hiên nhà bên cạnh những khóm hoa hồng.","Những chiếc bánh ngọt tươi ngon đã lôi kéo tôi bước vào tiệm bánh.","Tôi đã giảm độ sáng của màn hình trước khi xem phim.","Chúng tôi đã ăn một nửa chiếc bánh và cất phần còn lại vào tủ lạnh."]'::jsonb, 3, 'We ate half the cake and refrigerated the remainder. → Chúng tôi đã ăn một nửa chiếc bánh và cất phần còn lại vào tủ lạnh.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
