INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_86_18', 'en-b2-86', NULL, 'comprehensive_test', 'reading', NULL, 'In colder climates, flannel clothing provides practical warmth and can reduce reliance on intensive indoor heating.', 'Dựa vào câu trên, từ “flannel” có nghĩa phù hợp nhất là gì?', '["cách dùng từ; lời lẽ; văn bản","vải flannel (vải dạ mềm bằng cotton hoặc len)","đa dạng; phong phú","chu đáo; ân cần"]'::jsonb, 1, 'flannel: vải flannel (vải dạ mềm bằng cotton hoặc len); khăn mặt nhỏ. Dịch cả câu: Ở những vùng khí hậu lạnh hơn, trang phục bằng vải flannel mang lại sự ấm áp thiết thực và có thể làm giảm sự phụ thuộc vào hệ thống sưởi trong nhà cường độ cao.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_86_19', 'en-b2-86', NULL, 'comprehensive_test', 'reading', NULL, 'Children often develop stronger communication skills in a supportive educational setting that encourages cooperation rather than competition.', 'Dựa vào câu trên, từ “setting” có nghĩa phù hợp nhất là gì?', '["vôn (đơn vị đo hiệu điện thế)","môi trường; bối cảnh; khung cảnh","trường mẫu giáo; lớp mẫu giáo","làm mờ; trở nên mờ đi"]'::jsonb, 1, 'setting: môi trường; bối cảnh; khung cảnh; cài đặt; mức; độ; ổ gắn đá; ổ nhẫn. Dịch cả câu: Trẻ em thường phát triển các kỹ năng giao tiếp tốt hơn trong một môi trường giáo dục mang tính hỗ trợ, nơi khuyến khích sự hợp tác thay vì cạnh tranh.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_86_20', 'en-b2-86', NULL, 'comprehensive_test', 'reading', NULL, 'Improving public transport is one strand of a broader strategy to reduce urban air pollution.', 'Dựa vào câu trên, từ “strand” có nghĩa phù hợp nhất là gì?', '["khạc nhổ; nhổ ra","nới lỏng; làm lỏng ra","sợi; lọn; dải","cảm giác buồn ngủ; cơn buồn ngủ"]'::jsonb, 2, 'strand: sợi; lọn; dải; khía cạnh; yếu tố; phần; làm cho mắc kẹt; bỏ lại. Dịch cả câu: Cải thiện giao thông công cộng là một khía cạnh của chiến lược rộng lớn hơn nhằm giảm ô nhiễm không khí đô thị.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_86_21', 'en-b2-86', NULL, 'comprehensive_test', 'reading', NULL, 'Packaging helps keep snacks crisp, but excessive use of plastic creates significant environmental problems.', 'Dựa vào câu trên, từ “crisp” có nghĩa phù hợp nhất là gì?', '["bận rộn; tất bật; căng thẳng","phân phát; phân phối","giòn; giòn rụm","nâng cấp; cải thiện"]'::jsonb, 2, 'crisp: giòn; giòn rụm; mát mẻ; trong lành; khoai tây chiên giòn. Dịch cả câu: Bao bì giúp giữ cho đồ ăn nhẹ giòn ngon, nhưng việc lạm dụng nhựa gây ra các vấn đề môi trường nghiêm trọng.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_86_22', 'en-b2-86', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “vỏ bần; gỗ bần”', '["fabric","fate","obese","cork"]'::jsonb, 3, 'vỏ bần; gỗ bần → cork (/kɔːrk/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_86_23', 'en-b2-86', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cám dỗ; lôi cuốn; thu hút”', '["existing","kidney","checklist","tempt"]'::jsonb, 3, 'cám dỗ; lôi cuốn; thu hút → tempt (/tempt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_86_24', 'en-b2-86', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự cần thiết; tính tất yếu”', '["necessity","landfill","lobby","tracking"]'::jsonb, 0, 'sự cần thiết; tính tất yếu → necessity (/nəˈsesəti/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b2-87', 'en', 'Bài 87: Đời sống hằng ngày (14) - CEFR B2', 'CEFR B2', 'B2 · Đời sống', '26 từ vựng Tiếng Anh CEFR B2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 4087, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_endless', 'en-b2-87', 'endless', '/ˈendləs/', 'B2', 'vô tận; bất tận; kéo dài không dứt', 'adj.', 'end (n.), ending (n.), endlessly (adv.)', 'Đồng nghĩa: unending, interminable, ceaseless · Trái nghĩa: finite, limited', 'Thường dùng theo lối phóng đại để chỉ sự việc có vẻ kéo dài không dứt, chứ không nhất thiết là vĩnh viễn không bao giờ kết thúc.', 'The queue outside the swimming pool seemed endless today.', NULL, 'Hàng người xếp dài bên ngoài hồ bơi hôm nay dường như kéo dài không có điểm dừng.', '{"wordId":"endless","ukIpa":"/ˈendləs/","usIpa":"/ˈendləs/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Having no end, or seeming to continue forever.","vi":"vô tận; bất tận; kéo dài không dứt"}],"examples":[{"en":"The queue outside the swimming pool seemed endless today.","vi":"Hàng người xếp dài bên ngoài hồ bơi hôm nay dường như kéo dài không có điểm dừng.","audioKind":"ex"},{"en":"Although online platforms offer endless entertainment, excessive screen time may reduce opportunities for meaningful social interaction.","vi":"Mặc dù các nền tảng trực tuyến mang lại nguồn giải trí vô tận, việc sử dụng màn hình quá mức có thể làm giảm cơ hội tương tác xã hội có ý nghĩa.","audioKind":"ex2"}],"collocations":[{"en":"endless possibilities","vi":"khả năng vô tận"},{"en":"an endless stream of","vi":"dòng suối bất tận của..."},{"en":"endless debate","vi":"cuộc tranh luận không hồi kết"}],"wordFamily":["end (n.)","ending (n.)","endlessly (adv.)"],"synonyms":["unending","interminable","ceaseless"],"antonyms":["finite","limited"],"tipVi":"Thường dùng theo lối phóng đại để chỉ sự việc có vẻ kéo dài không dứt, chứ không nhất thiết là vĩnh viễn không bao giờ kết thúc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_golden', 'en-b2-87', 'golden', '/ˈɡoʊldən/', 'B2', 'màu vàng óng; vàng kim; tuyệt vời; quý giá; sáng giá', 'adj.', 'gold (n.)', 'Đồng nghĩa: gold-coloured', 'golden thường dùng để miêu tả màu sắc; để chỉ vật làm bằng vàng, ta dùng gold.', 'The bread turned golden after twenty minutes in the oven.', NULL, 'Ổ bánh mì chuyển sang màu vàng óng sau hai mươi phút trong lò nướng.', '{"wordId":"golden","ukIpa":"/ˈɡəʊldən/","usIpa":"/ˈɡoʊldən/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Having the warm yellow colour of gold.","vi":"màu vàng óng; vàng kim"},{"pos":"adj.","en":"Especially valuable, favourable, or successful.","vi":"tuyệt vời; quý giá; sáng giá"}],"examples":[{"en":"The bread turned golden after twenty minutes in the oven.","vi":"Ổ bánh mì chuyển sang màu vàng óng sau hai mươi phút trong lò nướng.","audioKind":"ex"},{"en":"International exchange programmes offer students a golden opportunity to develop language skills and understand different cultures.","vi":"Các chương trình trao đổi quốc tế mang đến cho học sinh cơ hội tuyệt vời để phát triển kỹ năng ngôn ngữ và thấu hiểu các nền văn hóa khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"golden brown","vi":"vàng óng; vàng sậm"},{"en":"golden opportunity","vi":"cơ hội quý giá; cơ hội ngàn vàng"},{"en":"golden age","vi":"thời kỳ hoàng kim"},{"en":"golden rule","vi":"quy tắc vàng; nguyên tắc tối quan trọng"}],"wordFamily":["gold (n.)"],"synonyms":["gold-coloured"],"antonyms":[],"tipVi":"golden thường dùng để miêu tả màu sắc; để chỉ vật làm bằng vàng, ta dùng gold.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_heap', 'en-b2-87', 'heap', '/hiːp/', 'B2', 'một đống; một khối; chồng chất; vun đống', 'n.', NULL, 'Đồng nghĩa: pile, mound', 'a heap of chỉ một đống; heaps of trong văn nói chỉ số lượng lớn.', 'He left his clothes in a heap beside the bed.', NULL, 'Anh ấy vứt đống quần áo thành một đống bên cạnh giường.', '{"wordId":"heap","ukIpa":"/hiːp/","usIpa":"/hiːp/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A pile of things placed together without careful arrangement.","vi":"một đống; một khối"},{"pos":"v.","en":"To put things together in a large pile.","vi":"chồng chất; vun đống"}],"examples":[{"en":"He left his clothes in a heap beside the bed.","vi":"Anh ấy vứt đống quần áo thành một đống bên cạnh giường.","audioKind":"ex"},{"en":"Large heaps of discarded clothing highlight the environmental consequences of rapid consumption in the fashion industry.","vi":"Những đống quần áo bỏ đi khổng lồ làm nổi bật hậu quả môi trường từ tiêu dùng nhanh trong ngành thời trang.","audioKind":"ex2"}],"collocations":[{"en":"a heap of clothes","vi":"một đống quần áo"},{"en":"a compost heap","vi":"đống ủ phân"},{"en":"heap praise on","vi":"ca ngợi hết lời"}],"wordFamily":[],"synonyms":["pile","mound"],"antonyms":[],"tipVi":"a heap of chỉ một đống; heaps of trong văn nói chỉ số lượng lớn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_glimpse', 'en-b2-87', 'glimpse', '/ɡlɪmps/', 'B2', 'cái nhìn thoáng qua; sự nhìn lướt; nhìn thoáng qua; lướt thấy', 'n.', NULL, NULL, 'glimpse nhấn mạnh ngắn ngủi nhìn thấy; glance nhấn mạnh chủ động vội vã nhìn một cái.', 'We caught a glimpse of a fox behind the fence.', NULL, 'Chúng tôi thoáng thấy một con cáo ở phía sau hàng rào.', '{"wordId":"glimpse","ukIpa":"/ɡlɪmps/","usIpa":"/ɡlɪmps/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"a brief or incomplete view of someone or something","vi":"cái nhìn thoáng qua; sự nhìn lướt"},{"pos":"v.","en":"to see someone or something briefly or only partly","vi":"nhìn thoáng qua; lướt thấy"}],"examples":[{"en":"We caught a glimpse of a fox behind the fence.","vi":"Chúng tôi thoáng thấy một con cáo ở phía sau hàng rào.","audioKind":"ex"},{"en":"Museum exhibitions offer visitors a glimpse of daily life in societies that existed thousands of years ago.","vi":"Các cuộc triển lãm bảo tàng mang đến cho khách tham quan cái nhìn khái quát về đời sống thường nhật của các cộng đồng tồn tại từ hàng nghìn năm trước.","audioKind":"ex2"}],"collocations":[{"en":"catch a glimpse of","vi":"thoáng thấy"},{"en":"a brief glimpse","vi":"cái nhìn thoáng qua"},{"en":"offer a glimpse into","vi":"mang lại cái nhìn hé mở về"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"glimpse nhấn mạnh ngắn ngủi nhìn thấy; glance nhấn mạnh chủ động vội vã nhìn một cái.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_serving', 'en-b2-87', 'serving', '/ˈsɝːvɪŋ/', 'B2', 'khẩu phần ăn; một phần thức ăn/đồ uống; đang tại chức; đang phục vụ (trong quân đội)', 'n.', 'serve (v.), service (n.), server (n.)', 'Đồng nghĩa: portion', 'serving nghĩa là phần thức ăn là danh từ đếm được, thường dùng "a serving of".', 'Would you like another serving of soup before dessert?', NULL, 'Bạn có muốn dùng thêm một phần súp nữa trước khi ăn tráng miệng không?', '{"wordId":"serving","ukIpa":"/ˈsɜːvɪŋ/","usIpa":"/ˈsɝːvɪŋ/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"An amount of food or drink intended for one person.","vi":"khẩu phần ăn; một phần thức ăn/đồ uống"},{"pos":"adj.","en":"Currently holding an official position or working in the armed forces.","vi":"đang tại chức; đang phục vụ (trong quân đội)"}],"examples":[{"en":"Would you like another serving of soup before dessert?","vi":"Bạn có muốn dùng thêm một phần súp nữa trước khi ăn tráng miệng không?","audioKind":"ex"},{"en":"Clear information about calories per serving can help consumers compare products and make more informed dietary choices.","vi":"Thông tin rõ ràng về lượng calo trên mỗi khẩu phần có thể giúp người tiêu dùng so sánh sản phẩm và đưa ra lựa chọn ăn uống sáng suốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"a serving of","vi":"một phần..."},{"en":"serving size","vi":"kích thước khẩu phần"},{"en":"per serving","vi":"mỗi khẩu phần"},{"en":"a serving officer","vi":"sĩ quan tại ngũ"}],"wordFamily":["serve (v.)","service (n.)","server (n.)"],"synonyms":["portion"],"antonyms":[],"tipVi":"serving nghĩa là phần thức ăn là danh từ đếm được, thường dùng \"a serving of\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_renew', 'en-b2-87', 'renew', '/rɪˈnuː/', 'B2', 'gia hạn; làm mới; làm mới lại; khôi phục', 'v.', 'renewal (n.), renewable (adj.)', NULL, 'renew tập trung vào việc kéo dài thời gian hiệu lực hoặc bắt đầu lại, không đồng nghĩa với cập nhật thông tin.', 'I need to renew my library books tomorrow.', NULL, 'Tôi cần gia hạn sách thư viện vào ngày mai.', '{"wordId":"renew","ukIpa":"/rɪˈnjuː/","usIpa":"/rɪˈnuː/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"Make an agreement or permission valid for a further period.","vi":"gia hạn; làm mới"},{"pos":"v.","en":"Start something again or restore its strength.","vi":"làm mới lại; khôi phục"}],"examples":[{"en":"I need to renew my library books tomorrow.","vi":"Tôi cần gia hạn sách thư viện vào ngày mai.","audioKind":"ex"},{"en":"Governments should renew their commitment to public transport as urban populations continue to grow.","vi":"Các chính phủ nên tái cam kết với giao thông công cộng khi dân số đô thị tiếp tục tăng.","audioKind":"ex2"}],"collocations":[{"en":"renew a subscription","vi":"gia hạn thuê bao"},{"en":"renew a passport","vi":"đổi hộ chiếu"},{"en":"renew a commitment","vi":"tái cam kết"},{"en":"renew a library book","vi":"gia hạn sách thư viện"}],"wordFamily":["renewal (n.)","renewable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"renew tập trung vào việc kéo dài thời gian hiệu lực hoặc bắt đầu lại, không đồng nghĩa với cập nhật thông tin.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_distinctly', 'en-b2-87', 'distinctly', '/dɪˈstɪŋktli/', 'B2', 'rõ ràng; rành mạch; thực sự; rõ rệt; hoàn toàn', 'adv.', 'distinct (adj.), distinction (n.), distinctness (n.)', 'Đồng nghĩa: clearly, noticeably · Trái nghĩa: vaguely, indistinctly', 'Distinctly có thể bổ nghĩa cho trí nhớ, giác quan, hoặc nhấn mạnh mức độ.', 'I distinctly remember leaving my keys beside the kettle.', NULL, 'Tôi nhớ rất rõ việc mình để chìa khóa bên cạnh chiếc ấm đun nước.', '{"wordId":"distinctly","ukIpa":"/dɪˈstɪŋktli/","usIpa":"/dɪˈstɪŋktli/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"in a way that is easy to perceive or remember","vi":"rõ ràng; rành mạch"},{"pos":"adv.","en":"to a noticeable or unmistakable degree","vi":"thực sự; rõ rệt; hoàn toàn"}],"examples":[{"en":"I distinctly remember leaving my keys beside the kettle.","vi":"Tôi nhớ rất rõ việc mình để chìa khóa bên cạnh chiếc ấm đun nước.","audioKind":"ex"},{"en":"Residents felt distinctly safer after the council improved street lighting and introduced regular evening bus services.","vi":"Cư dân cảm thấy an toàn hơn hẳn sau khi hội đồng cải thiện hệ thống đèn đường và đưa vào hoạt động các chuyến xe buýt buổi tối định kỳ.","audioKind":"ex2"}],"collocations":[{"en":"distinctly remember","vi":"nhớ rõ ràng"},{"en":"hear distinctly","vi":"nghe rõ mồn một"},{"en":"distinctly different","vi":"khác biệt rõ rệt"}],"wordFamily":["distinct (adj.)","distinction (n.)","distinctness (n.)"],"synonyms":["clearly","noticeably"],"antonyms":["vaguely","indistinctly"],"tipVi":"Distinctly có thể bổ nghĩa cho trí nhớ, giác quan, hoặc nhấn mạnh mức độ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_splendid', 'en-b2-87', 'splendid', '/ˈsplendɪd/', 'B2', 'tuyệt vời; xuất sắc; tráng lệ; lộng lẫy', 'adj.', 'splendidly (adv.), splendour (n.)', 'Đồng nghĩa: excellent, magnificent · Trái nghĩa: terrible', 'Có thể dùng để khen ngợi sự việc cực kỳ tốt, hoặc miêu tả cảnh quan hùng vĩ, tráng lệ.', 'We had a splendid picnic beside the lake yesterday.', NULL, 'Chúng tôi đã có một buổi dã ngoại tuyệt vời bên hồ vào ngày hôm qua.', '{"wordId":"splendid","ukIpa":"/ˈsplendɪd/","usIpa":"/ˈsplendɪd/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Extremely good or impressive.","vi":"tuyệt vời; xuất sắc"},{"pos":"adj.","en":"Beautiful and impressive in appearance.","vi":"tráng lệ; lộng lẫy"}],"examples":[{"en":"We had a splendid picnic beside the lake yesterday.","vi":"Chúng tôi đã có một buổi dã ngoại tuyệt vời bên hồ vào ngày hôm qua.","audioKind":"ex"},{"en":"Restoring historic gardens gives urban residents a splendid opportunity to enjoy nature and learn about local heritage.","vi":"Việc phục hồi các khu vườn lịch sử mang lại cho cư dân đô thị cơ hội tuyệt vời để tận hưởng thiên nhiên và tìm hiểu di sản địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a splendid opportunity","vi":"cơ hội tuyệt vời"},{"en":"a splendid view","vi":"cảnh quan tráng lệ"},{"en":"a splendid job","vi":"công việc xuất sắc"}],"wordFamily":["splendidly (adv.)","splendour (n.)"],"synonyms":["excellent","magnificent"],"antonyms":["terrible"],"tipVi":"Có thể dùng để khen ngợi sự việc cực kỳ tốt, hoặc miêu tả cảnh quan hùng vĩ, tráng lệ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_convenience', 'en-b2-87', 'convenience', '/kənˈviːniəns/', 'B2', 'sự thuận tiện; tính tiện lợi; tiện ích; vật dụng tiện lợi', 'n.', 'convenient (adj.), conveniently (adv.), inconvenience (n.)', 'Đồng nghĩa: ease · Trái nghĩa: inconvenience', 'Danh từ chỉ sự thuận tiện thường là danh từ không đếm được; tính từ tương ứng là convenient.', 'I keep spare keys here for convenience when guests visit.', NULL, 'Tôi để chìa khóa dự phòng ở đây để tiện cho khách đến thăm nhà.', '{"wordId":"convenience","ukIpa":"/kənˈviːniəns/","usIpa":"/kənˈviːniəns/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"The quality of being easy, useful, or suitable.","vi":"sự thuận tiện; tính tiện lợi"},{"pos":"n.","en":"Something that makes daily life easier.","vi":"tiện ích; vật dụng tiện lợi"}],"examples":[{"en":"I keep spare keys here for convenience when guests visit.","vi":"Tôi để chìa khóa dự phòng ở đây để tiện cho khách đến thăm nhà.","audioKind":"ex"},{"en":"Although online shopping offers convenience, it may encourage unnecessary spending and increase packaging waste.","vi":"Mặc dù mua sắm trực tuyến mang lại sự tiện lợi, nhưng nó có thể kích thích chi tiêu không cần thiết và làm gia tăng lượng rác thải bao bì.","audioKind":"ex2"}],"collocations":[{"en":"for convenience","vi":"để cho tiện"},{"en":"at your convenience","vi":"vào lúc bạn thuận tiện"},{"en":"modern conveniences","vi":"tiện ích hiện đại"},{"en":"convenience store","vi":"cửa hàng tiện lợi"}],"wordFamily":["convenient (adj.)","conveniently (adv.)","inconvenience (n.)"],"synonyms":["ease"],"antonyms":["inconvenience"],"tipVi":"Danh từ chỉ sự thuận tiện thường là danh từ không đếm được; tính từ tương ứng là convenient.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_functional', 'en-b2-87', 'functional', '/ˈfʌŋkʃənəl/', 'B2', 'có tính thực dụng; nặng về công năng hơn trang trí; hoạt động tốt; vận hành bình thường; sẵn sàng sử dụng; thuộc về chức năng; liên quan đến vận hành', 'adj.', 'function (n.), function (v.), functionally (adv.), functionality (n.)', 'Đồng nghĩa: practical, utilitarian · Trái nghĩa: nonfunctional', 'functional có thể dùng để chỉ thiết kế thực dụng, hoặc chỉ thiết bị đang hoạt động bình thường.', 'The kitchen is small but functional, with plenty of storage.', NULL, 'Gian bếp nhỏ nhưng rất thiết thực và đầy đủ không gian lưu trữ.', '{"wordId":"functional","ukIpa":"/ˈfʌŋkʃənəl/","usIpa":"/ˈfʌŋkʃənəl/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"designed to be useful rather than decorative","vi":"có tính thực dụng; nặng về công năng hơn trang trí"},{"pos":"adj.","en":"working correctly and ready for use","vi":"hoạt động tốt; vận hành bình thường; sẵn sàng sử dụng"},{"pos":"adj.","en":"relating to the purpose or operation of something","vi":"thuộc về chức năng; liên quan đến vận hành"}],"examples":[{"en":"The kitchen is small but functional, with plenty of storage.","vi":"Gian bếp nhỏ nhưng rất thiết thực và đầy đủ không gian lưu trữ.","audioKind":"ex"},{"en":"Public housing should provide functional living spaces that meet the daily needs of diverse households.","vi":"Nhà ở xã hội nên cung cấp không gian sống thiết thực, đáp ứng các nhu cầu sinh hoạt hàng ngày của các hộ gia đình khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"functional design","vi":"thiết kế thực dụng"},{"en":"fully functional","vi":"hoạt động hoàn hảo"},{"en":"functional requirements","vi":"yêu cầu chức năng"}],"wordFamily":["function (n.)","function (v.)","functionally (adv.)","functionality (n.)"],"synonyms":["practical","utilitarian"],"antonyms":["nonfunctional"],"tipVi":"functional có thể dùng để chỉ thiết kế thực dụng, hoặc chỉ thiết bị đang hoạt động bình thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_feast', 'en-b2-87', 'feast', '/fiːst/', 'B2', 'bữa tiệc lớn; bữa ăn thịnh soạn; đại tiệc (cho các giác quan); thưởng thức; ăn uống thỏa thích', 'n.', 'feasting (n.)', 'Đồng nghĩa: banquet', 'Động từ thường đi với cụm feast on, biểu thị việc ăn uống thỏa thích một món gì đó.', 'We prepared a feast for the whole family.', NULL, 'Chúng tôi đã chuẩn bị một bữa tiệc linh đình cho cả gia đình.', '{"wordId":"feast","ukIpa":"/fiːst/","usIpa":"/fiːst/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A large, special meal with plenty of food.","vi":"bữa tiệc lớn; bữa ăn thịnh soạn"},{"pos":"n.","en":"Something that gives great pleasure to the senses.","vi":"đại tiệc (cho các giác quan)"},{"pos":"v.","en":"To eat and enjoy a large amount of food.","vi":"thưởng thức; ăn uống thỏa thích"}],"examples":[{"en":"We prepared a feast for the whole family.","vi":"Chúng tôi đã chuẩn bị một bữa tiệc linh đình cho cả gia đình.","audioKind":"ex"},{"en":"Traditional festivals often include a communal feast that strengthens relationships and preserves local food culture.","vi":"Các lễ hội truyền thống thường bao gồm một bữa tiệc chung giúp thắt chặt các mối quan hệ và bảo tồn văn hóa ẩm thực địa phương.","audioKind":"ex2"}],"collocations":[{"en":"prepare a feast","vi":"chuẩn bị một bữa tiệc lớn"},{"en":"a feast for the eyes","vi":"bữa tiệc thị giác"},{"en":"feast on","vi":"thưởng thức thỏa thích"}],"wordFamily":["feasting (n.)"],"synonyms":["banquet"],"antonyms":[],"tipVi":"Động từ thường đi với cụm feast on, biểu thị việc ăn uống thỏa thích một món gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plump', 'en-b2-87', 'plump', '/plʌmp/', 'B2', 'mũm mĩm; đầy đặn; tròn trĩnh; vỗ phồng; làm cho căng phồng lên', 'adj.', 'plumpness (n.)', 'Đồng nghĩa: rounded · Trái nghĩa: thin', 'Mang sắc thái nhẹ nhàng và lịch sự hơn từ fat, tuy nhiên khi miêu tả vóc dáng người khác vẫn cần thận trọng.', 'She picked a plump peach from the fruit bowl.', NULL, 'Cô ấy chọn một quả đào căng mọng từ đĩa trái cây.', '{"wordId":"plump","ukIpa":"/plʌmp/","usIpa":"/plʌmp/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"pleasantly round and full in shape","vi":"mũm mĩm; đầy đặn; tròn trĩnh"},{"pos":"v.","en":"to make a cushion or pillow fuller by shaking it","vi":"vỗ phồng; làm cho căng phồng lên"}],"examples":[{"en":"She picked a plump peach from the fruit bowl.","vi":"Cô ấy chọn một quả đào căng mọng từ đĩa trái cây.","audioKind":"ex"},{"en":"Consumers often prefer plump fruit, although appearance alone is not a reliable indicator of nutritional value.","vi":"Người tiêu dùng thường thích những loại quả căng mọng, mặc dù vẻ bề ngoài chưa chắc đã là một chỉ số đáng tin cậy về giá trị dinh dưỡng.","audioKind":"ex2"}],"collocations":[{"en":"plump cheeks","vi":"má phúng phính"},{"en":"plump fruit","vi":"trái cây căng mọng"},{"en":"plump up a pillow","vi":"vỗ phồng gối"}],"wordFamily":["plumpness (n.)"],"synonyms":["rounded"],"antonyms":["thin"],"tipVi":"Mang sắc thái nhẹ nhàng và lịch sự hơn từ fat, tuy nhiên khi miêu tả vóc dáng người khác vẫn cần thận trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_foam', 'en-b2-87', 'foam', '/foʊm/', 'B2', 'bọt; chất liệu bọt (nhựa/cao su xốp); sủi bọt', 'n.', 'foamy (adj.)', 'Đồng nghĩa: froth', 'Foam mang nghĩa bọt hoặc vật liệu xốp thường không đếm được.', 'White foam covered my hands as I washed the dishes.', NULL, 'Bọt trắng phủ đầy hai tay tôi khi tôi rửa bát.', '{"wordId":"foam","ukIpa":"/fəʊm/","usIpa":"/foʊm/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"a mass of small bubbles on or in a liquid","vi":"bọt"},{"pos":"n.","en":"a light material containing many tiny air pockets","vi":"chất liệu bọt (nhựa/cao su xốp)"},{"pos":"v.","en":"to produce a mass of small bubbles","vi":"sủi bọt"}],"examples":[{"en":"White foam covered my hands as I washed the dishes.","vi":"Bọt trắng phủ đầy hai tay tôi khi tôi rửa bát.","audioKind":"ex"},{"en":"Manufacturers often use foam packaging to protect fragile goods, although some types are difficult to recycle.","vi":"Các nhà sản xuất thường sử dụng bao bì xốp để bảo vệ hàng dễ vỡ, mặc dù một số loại rất khó tái chế.","audioKind":"ex2"}],"collocations":[{"en":"shaving foam","vi":"bọt cạo râu"},{"en":"sea foam","vi":"bọt biển"},{"en":"foam packaging","vi":"bao bì xốp"},{"en":"foam rubber","vi":"cao su xốp"}],"wordFamily":["foamy (adj.)"],"synonyms":["froth"],"antonyms":[],"tipVi":"Foam mang nghĩa bọt hoặc vật liệu xốp thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_enormously', 'en-b2-87', 'enormously', '/ɪˈnɔːrməsli/', 'B2', 'vô cùng; cực kỳ', 'adv.', 'enormous (adj.), enormity (n.)', 'Đồng nghĩa: immensely, hugely, greatly · Trái nghĩa: slightly', 'Thường bổ nghĩa cho tính từ hoặc động từ, biểu thị mức độ cực kỳ cao.', 'Your help made this difficult move enormously easier.', NULL, 'Sự giúp đỡ của bạn đã làm cho việc chuyển nhà khó khăn này trở nên dễ dàng hơn rất nhiều.', '{"wordId":"enormously","ukIpa":"/ɪˈnɔːməsli/","usIpa":"/ɪˈnɔːrməsli/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"to a very great degree or extent","vi":"vô cùng; cực kỳ"}],"examples":[{"en":"Your help made this difficult move enormously easier.","vi":"Sự giúp đỡ của bạn đã làm cho việc chuyển nhà khó khăn này trở nên dễ dàng hơn rất nhiều.","audioKind":"ex"},{"en":"Affordable public transport can benefit low-income households enormously by reducing their daily travel costs.","vi":"Giao thông công cộng giá rẻ có thể mang lại lợi ích vô cùng lớn cho các hộ gia đình có thu nhập thấp bằng cách giảm chi phí đi lại hàng ngày của họ.","audioKind":"ex2"}],"collocations":[{"en":"enormously successful","vi":"vô cùng thành công"},{"en":"benefit enormously","vi":"hưởng lợi cực kỳ lớn"},{"en":"vary enormously","vi":"khác biệt rất nhiều"}],"wordFamily":["enormous (adj.)","enormity (n.)"],"synonyms":["immensely","hugely","greatly"],"antonyms":["slightly"],"tipVi":"Thường bổ nghĩa cho tính từ hoặc động từ, biểu thị mức độ cực kỳ cao.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_damp', 'en-b2-87', 'damp', '/dæmp/', 'B2', 'ẩm ướt; ẩm thấp; hơi ẩm; độ ẩm; làm ẩm; làm giảm', 'adj.', 'dampness (n.), dampen (v.)', 'Đồng nghĩa: moist · Trái nghĩa: dry', 'Từ damp thường chỉ độ ẩm gây khó chịu; trong khi moist có thể dùng cho thực phẩm mọng nước.', 'My socks are still damp from yesterday''s walk.', NULL, 'Tất của tôi vẫn còn ẩm sau buổi đi dạo hôm qua.', '{"wordId":"damp","ukIpa":"/dæmp/","usIpa":"/dæmp/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Slightly wet, often in an unpleasant way.","vi":"ẩm ướt; ẩm thấp"},{"pos":"n.","en":"Unwanted moisture in the air, walls, or other surfaces.","vi":"hơi ẩm; độ ẩm"},{"pos":"v.","en":"To make slightly wet or reduce strength or activity.","vi":"làm ẩm; làm giảm"}],"examples":[{"en":"My socks are still damp from yesterday''s walk.","vi":"Tất của tôi vẫn còn ẩm sau buổi đi dạo hôm qua.","audioKind":"ex"},{"en":"Living in damp conditions can worsen respiratory problems, particularly among children and older people.","vi":"Sống trong điều kiện ẩm thấp có thể làm trầm trọng thêm các vấn đề về đường hô hấp, đặc biệt là ở trẻ em và người cao tuổi.","audioKind":"ex2"}],"collocations":[{"en":"a damp cloth","vi":"một chiếc khăn ẩm"},{"en":"damp walls","vi":"những bức tường ẩm ướt"},{"en":"rising damp","vi":"độ ẩm từ lòng đất bốc lên"},{"en":"damp down","vi":"làm suy yếu; kìm hãm"}],"wordFamily":["dampness (n.)","dampen (v.)"],"synonyms":["moist"],"antonyms":["dry"],"tipVi":"Từ damp thường chỉ độ ẩm gây khó chịu; trong khi moist có thể dùng cho thực phẩm mọng nước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_crumb', 'en-b2-87', 'crumb', '/krʌm/', 'B2', 'vụn bánh (mì, bánh ngọt, bánh quy); một chút ít; điểm (an ủi, hy vọng)', 'n.', 'crumble (v.), crumbly (adj.)', NULL, 'Là danh từ đếm được; khi chỉ vụn bánh thường dùng dạng số nhiều crumbs.', 'A crumb fell from my toast onto the table.', NULL, 'Một mẩu vụn bánh mì từ lát bánh nướng của tôi đã rơi xuống bàn.', '{"wordId":"crumb","ukIpa":"/krʌm/","usIpa":"/krʌm/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A tiny piece that breaks off bread, cake, or biscuits","vi":"vụn bánh (mì, bánh ngọt, bánh quy)"},{"pos":"n.","en":"A very small amount of something","vi":"một chút ít; điểm (an ủi, hy vọng)"}],"examples":[{"en":"A crumb fell from my toast onto the table.","vi":"Một mẩu vụn bánh mì từ lát bánh nướng của tôi đã rơi xuống bàn.","audioKind":"ex"},{"en":"Even small food scraps, such as bread crumbs, can attract pests when waste is poorly managed.","vi":"Ngay cả những mẩu vụn thức ăn nhỏ, chẳng hạn như vụn bánh mì, cũng có thể thu hút côn trùng gây hại khi rác thải không được quản lý tốt.","audioKind":"ex2"}],"collocations":[{"en":"bread crumbs","vi":"vụn bánh mì"},{"en":"biscuit crumbs","vi":"vụn bánh quy"},{"en":"a crumb of comfort","vi":"một chút an ủi"}],"wordFamily":["crumble (v.)","crumbly (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ đếm được; khi chỉ vụn bánh thường dùng dạng số nhiều crumbs.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disturb', 'en-b2-87', 'disturb', '/dɪˈstɜːrb/', 'B2', 'làm phiền; quấy rầy; làm gián đoạn; làm lo lắng; làm bận tâm; làm xáo trộn; làm dịch chuyển vị trí', 'v.', 'disturbance (n.), disturbing (adj.), disturbed (adj.)', 'Đồng nghĩa: interrupt, unsettle', 'disturb nhấn mạnh việc gây phiền nhiễu hoặc làm bất an; interrupt nhấn mạnh việc ngắt quãng.', 'Please close the door quietly so you don''t disturb Dad.', NULL, 'Hãy khép cửa nhẹ nhàng để không làm phiền bố nhé.', '{"wordId":"disturb","ukIpa":"/dɪˈstɜːb/","usIpa":"/dɪˈstɜːrb/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to interrupt someone''s activity, rest, or peace","vi":"làm phiền; quấy rầy; làm gián đoạn"},{"pos":"v.","en":"to make someone feel worried or upset","vi":"làm lo lắng; làm bận tâm"},{"pos":"v.","en":"to move or change something from its usual position","vi":"làm xáo trộn; làm dịch chuyển vị trí"}],"examples":[{"en":"Please close the door quietly so you don''t disturb Dad.","vi":"Hãy khép cửa nhẹ nhàng để không làm phiền bố nhé.","audioKind":"ex"},{"en":"Construction noise can disturb nearby residents and reduce their quality of life over time.","vi":"Tiếng ồn xây dựng có thể làm phiền cư dân xung quanh và theo thời gian làm giảm chất lượng cuộc sống của họ.","audioKind":"ex2"}],"collocations":[{"en":"disturb someone''s sleep","vi":"làm gián đoạn giấc ngủ của ai"},{"en":"deeply disturbed","vi":"vô cùng bận tâm / lo lắng"},{"en":"disturb the peace","vi":"gây rối trật tự công cộng"}],"wordFamily":["disturbance (n.)","disturbing (adj.)","disturbed (adj.)"],"synonyms":["interrupt","unsettle"],"antonyms":[],"tipVi":"disturb nhấn mạnh việc gây phiền nhiễu hoặc làm bất an; interrupt nhấn mạnh việc ngắt quãng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_blend', 'en-b2-87', 'blend', '/blend/', 'B2', 'trộn; pha trộn; hòa quyện; hợp chất pha trộn; sự hòa quyện', 'v.', 'blender (n.), blended (adj.)', 'Đồng nghĩa: mix, combine · Trái nghĩa: separate', 'blend A with B nghĩa là trộn lẫn hai thứ; blend in nghĩa là hòa mình vào không gian xung quanh.', 'Blend the bananas and milk until the mixture is smooth.', NULL, 'Xay nhuyễn chuối và sữa cho đến khi hỗn hợp mịn màng.', '{"wordId":"blend","ukIpa":"/blend/","usIpa":"/blend/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to mix substances or qualities together","vi":"trộn; pha trộn; hòa quyện"},{"pos":"n.","en":"a mixture of different substances, styles, or qualities","vi":"hợp chất pha trộn; sự hòa quyện"}],"examples":[{"en":"Blend the bananas and milk until the mixture is smooth.","vi":"Xay nhuyễn chuối và sữa cho đến khi hỗn hợp mịn màng.","audioKind":"ex"},{"en":"Successful urban developments blend modern facilities with traditional architecture to preserve a city''s distinctive character.","vi":"Các dự án phát triển đô thị thành công kết hợp giữa các tiện ích hiện đại với kiến trúc truyền thống để giữ gìn nét đặc trưng riêng của thành phố.","audioKind":"ex2"}],"collocations":[{"en":"blend ingredients","vi":"trộn nguyên liệu"},{"en":"blend with","vi":"hòa quyện với"},{"en":"a blend of","vi":"sự pha trộn của"},{"en":"blend in","vi":"hoà nhập vào môi trường"}],"wordFamily":["blender (n.)","blended (adj.)"],"synonyms":["mix","combine"],"antonyms":["separate"],"tipVi":"blend A with B nghĩa là trộn lẫn hai thứ; blend in nghĩa là hòa mình vào không gian xung quanh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bow', 'en-b2-87', 'bow', '/boʊ/; /baʊ/', 'B2', 'cây cung (vũ khí cong dùng để bắn tên); nơ (nút thắt có hai vòng và hai đầu buông thõng); cú cúi đầu; cúi đầu (chào hoặc thể hiện sự tôn trọng)', 'n.', NULL, NULL, 'Cung, nơ phát âm là /bəʊ/; cúi đầu, phần mũi thuyền phát âm là /baʊ/.', 'She tied a neat bow around the gift box.', NULL, 'Cô ấy thắt một chiếc nơ gọn gàng xung quanh hộp quà.', '{"wordId":"bow","ukIpa":"/bəʊ/; /baʊ/","usIpa":"/boʊ/; /baʊ/","cefr":"B2","topic":"daily","senses":[{"pos":"n.","en":"A curved weapon with a string used to shoot arrows.","vi":"cây cung (vũ khí cong dùng để bắn tên)"},{"pos":"n.","en":"A knot with two loops and two loose ends.","vi":"nơ (nút thắt có hai vòng và hai đầu buông thõng)"},{"pos":"v.","en":"To bend your head or body forward, often showing respect.","vi":"cú cúi đầu; cúi đầu (chào hoặc thể hiện sự tôn trọng)"}],"examples":[{"en":"She tied a neat bow around the gift box.","vi":"Cô ấy thắt một chiếc nơ gọn gàng xung quanh hộp quà.","audioKind":"ex"},{"en":"In some cultures, people bow when greeting others, while elsewhere a handshake is more common.","vi":"Ở một số nền văn hóa, mọi người cúi đầu khi chào hỏi người khác, trong khi ở những nơi khác, việc bắt tay phổ biến hơn.","audioKind":"ex2"}],"collocations":[{"en":"bow and arrow","vi":"cung và tên"},{"en":"tie a bow","vi":"thắt nơ"},{"en":"bow your head","vi":"cúi đầu"},{"en":"bow to pressure","vi":"khuất phục trước áp lực"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cung, nơ phát âm là /bəʊ/; cúi đầu, phần mũi thuyền phát âm là /baʊ/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unwelcome', 'en-b2-87', 'unwelcome', '/ʌnˈwelkəm/', 'B2', 'không được chào đón; khó chịu; không vừa ý', 'adj.', 'welcome (adj.), welcome (v.)', 'Đồng nghĩa: unwanted, undesirable · Trái nghĩa: welcome', 'Có thể dùng để mô tả người, tin tức hoặc sự thay đổi; cụm feel unwelcome mang nghĩa cảm thấy không được chào đón.', 'The loud music was an unwelcome interruption during dinner.', NULL, 'Tiếng nhạc lớn là một sự ngắt quãng đầy khó chịu trong bữa tối.', '{"wordId":"unwelcome","ukIpa":"/ʌnˈwelkəm/","usIpa":"/ʌnˈwelkəm/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"not wanted or received with pleasure","vi":"không được chào đón; khó chịu; không vừa ý"}],"examples":[{"en":"The loud music was an unwelcome interruption during dinner.","vi":"Tiếng nhạc lớn là một sự ngắt quãng đầy khó chịu trong bữa tối.","audioKind":"ex"},{"en":"For many residents, rising rents are an unwelcome consequence of rapid development in urban areas.","vi":"Đối với nhiều cư dân, giá nhà tăng cao là một hệ quả không mong muốn từ sự phát triển nhanh chóng ở các khu vực đô thị.","audioKind":"ex2"}],"collocations":[{"en":"unwelcome attention","vi":"sự quan tâm không mong muốn"},{"en":"unwelcome guest","vi":"khách không mời"},{"en":"unwelcome news","vi":"tin tức không vui"}],"wordFamily":["welcome (adj.)","welcome (v.)"],"synonyms":["unwanted","undesirable"],"antonyms":["welcome"],"tipVi":"Có thể dùng để mô tả người, tin tức hoặc sự thay đổi; cụm feel unwelcome mang nghĩa cảm thấy không được chào đón.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pinch', 'en-b2-87', 'pinch', '/pɪntʃ/', 'B2', 'bóp; véo; kẹp; một nhúm; một nhúm nhỏ; cái véo; cái nhéo', 'v.', NULL, 'Đồng nghĩa: squeeze', 'Cụm a pinch of dùng để chỉ lượng nhỏ; feel the pinch chỉ tình trạng eo hẹp về tài chính.', 'Pinch the pastry edges together to seal the pie.', NULL, 'Bóp các mép bột dính lại với nhau để bị kín bánh.', '{"wordId":"pinch","ukIpa":"/pɪntʃ/","usIpa":"/pɪntʃ/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to squeeze something tightly, often between a finger and thumb","vi":"bóp; véo; kẹp"},{"pos":"n.","en":"a small amount held between a finger and thumb","vi":"một nhúm; một nhúm nhỏ"},{"pos":"n.","en":"the act of squeezing skin between a finger and thumb","vi":"cái véo; cái nhéo"}],"examples":[{"en":"Pinch the pastry edges together to seal the pie.","vi":"Bóp các mép bột dính lại với nhau để bị kín bánh.","audioKind":"ex"},{"en":"As food prices rise, families on low incomes increasingly feel the pinch and reduce nonessential spending.","vi":"Khi giá thực phẩm tăng cao, các hộ gia đình có thu nhập thấp ngày càng cảm thấy túng quẫn và phải cắt giảm chi tiêu không thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"a pinch of salt","vi":"một nhúm muối"},{"en":"feel the pinch","vi":"cảm thấy túng quẫn; cảm thấy khó khăn về tiền bạc"},{"en":"pinch together","vi":"bóp lại với nhau"}],"wordFamily":[],"synonyms":["squeeze"],"antonyms":[],"tipVi":"Cụm a pinch of dùng để chỉ lượng nhỏ; feel the pinch chỉ tình trạng eo hẹp về tài chính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_satisfy', 'en-b2-87', 'satisfy', '/ˈsætɪsfaɪ/', 'B2', 'làm hài lòng; làm thỏa mãn; đáp ứng; thỏa mãn; thuyết phục; làm cho tin chắc', 'v.', 'satisfaction (n.), satisfied (adj.), satisfying (adj.), satisfactory (adj.)', 'Đồng nghĩa: please, fulfil · Trái nghĩa: dissatisfy', 'Người cảm thấy hài lòng dùng satisfied; sự việc làm hài lòng dùng satisfying.', 'A bowl of soup was enough to satisfy my hunger.', NULL, 'Một bát súp là đủ để làm tôi hết đói.', '{"wordId":"satisfy","ukIpa":"/ˈsætɪsfaɪ/","usIpa":"/ˈsætɪsfaɪ/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"to give someone what they want or need","vi":"làm hài lòng; làm thỏa mãn"},{"pos":"v.","en":"to meet a condition, standard, or requirement","vi":"đáp ứng; thỏa mãn"},{"pos":"v.","en":"to convince someone that something is true or acceptable","vi":"thuyết phục; làm cho tin chắc"}],"examples":[{"en":"A bowl of soup was enough to satisfy my hunger.","vi":"Một bát súp là đủ để làm tôi hết đói.","audioKind":"ex"},{"en":"New housing developments must satisfy strict environmental standards before local authorities allow construction to begin.","vi":"Các dự án phát triển nhà ở mới phải đạt các tiêu chuẩn môi trường nghiêm ngặt trước khi chính quyền địa phương cho phép khởi công.","audioKind":"ex2"}],"collocations":[{"en":"satisfy a need","vi":"đáp ứng nhu cầu"},{"en":"satisfy requirements","vi":"đáp ứng các yêu cầu"},{"en":"satisfy your curiosity","vi":"thỏa mãn sự tò mò"},{"en":"satisfy yourself that","vi":"làm cho bản thân tin rằng"}],"wordFamily":["satisfaction (n.)","satisfied (adj.)","satisfying (adj.)","satisfactory (adj.)"],"synonyms":["please","fulfil"],"antonyms":["dissatisfy"],"tipVi":"Người cảm thấy hài lòng dùng satisfied; sự việc làm hài lòng dùng satisfying.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_typically', 'en-b2-87', 'typically', '/ˈtɪpɪkli/', 'B2', 'thường; thông thường; đại khái là; tiêu biểu; một cách đặc trưng', 'adv.', 'typical (adj.), atypical (adj.)', 'Đồng nghĩa: usually, generally · Trái nghĩa: atypically', 'Trạng từ này thường đứng trước động từ thường và đứng sau động từ ''to be''.', 'Our neighbours typically walk their dog before breakfast.', NULL, 'Những người hàng xóm của chúng tôi thường dắt chó đi dạo trước bữa sáng.', '{"wordId":"typically","ukIpa":"/ˈtɪpɪkli/","usIpa":"/ˈtɪpɪkli/","cefr":"B2","topic":"daily","senses":[{"pos":"adv.","en":"In most cases or on most occasions.","vi":"thường; thông thường; đại khái là"},{"pos":"adv.","en":"In a way that shows the usual qualities of something.","vi":"tiêu biểu; một cách đặc trưng"}],"examples":[{"en":"Our neighbours typically walk their dog before breakfast.","vi":"Những người hàng xóm của chúng tôi thường dắt chó đi dạo trước bữa sáng.","audioKind":"ex"},{"en":"Cities with reliable public transport typically experience less traffic congestion than those dependent on private cars.","vi":"Các thành phố có hệ thống giao thông công cộng đáng tin cậy thường ít bị ùn tắc giao thông hơn so với những thành phố phụ thuộc vào xe hơi cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"typically require","vi":"thường yêu cầu"},{"en":"typically involve","vi":"thường bao gồm"},{"en":"typically found in","vi":"thường được tìm thấy ở"}],"wordFamily":["typical (adj.)","atypical (adj.)"],"synonyms":["usually","generally"],"antonyms":["atypically"],"tipVi":"Trạng từ này thường đứng trước động từ thường và đứng sau động từ ''to be''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unstable', 'en-b2-87', 'unstable', '/ʌnˈsteɪbl/', 'B2', 'không vững chãi; dễ đổ; không ổn định; dễ thay đổi', 'adj.', 'stable (adj.), stability (n.), instability (n.), stabilise (v.)', 'Đồng nghĩa: unsteady, insecure · Trái nghĩa: stable, steady', 'Có thể chỉ vật thể không vững, cũng có thể chỉ kinh tế, tình hình... dễ thay đổi.', 'This unstable chair wobbles whenever I sit on it.', NULL, 'Chiếc ghế không vững này cứ lung lay mỗi khi tôi ngồi lên.', '{"wordId":"unstable","ukIpa":"/ʌnˈsteɪbl/","usIpa":"/ʌnˈsteɪbl/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Likely to move, fall, or collapse.","vi":"không vững chãi; dễ đổ"},{"pos":"adj.","en":"Likely to change suddenly and unpredictably.","vi":"không ổn định; dễ thay đổi"}],"examples":[{"en":"This unstable chair wobbles whenever I sit on it.","vi":"Chiếc ghế không vững này cứ lung lay mỗi khi tôi ngồi lên.","audioKind":"ex"},{"en":"An unstable economy can discourage investment and make long-term planning difficult for small businesses.","vi":"Nền kinh tế bất ổn có thể cản trở đầu tư và khiến các doanh nghiệp nhỏ khó lập kế hoạch dài hạn.","audioKind":"ex2"}],"collocations":[{"en":"unstable economy","vi":"nền kinh tế bất ổn"},{"en":"politically unstable","vi":"bất ổn về chính trị"},{"en":"unstable structure","vi":"kết cấu không vững chắc"}],"wordFamily":["stable (adj.)","stability (n.)","instability (n.)","stabilise (v.)"],"synonyms":["unsteady","insecure"],"antonyms":["stable","steady"],"tipVi":"Có thể chỉ vật thể không vững, cũng có thể chỉ kinh tế, tình hình... dễ thay đổi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_minor', 'en-b2-87', 'minor', '/ˈmaɪnər/', 'B2', 'nhỏ; không quan trọng; thứ yếu; người chưa thành niên; thang âm thứ; giọng thứ', 'adj.', 'minority (n.)', 'Đồng nghĩa: slight, small · Trái nghĩa: major', 'minor injury nghĩa là chơ thương nhẹ; danh từ a minor dùng để chỉ người chưa thành niên.', 'The bike only needs a few minor repairs.', NULL, 'Chiếc xe đạp chỉ cần sửa chữa một vài lỗi nhỏ.', '{"wordId":"minor","ukIpa":"/ˈmaɪnə/","usIpa":"/ˈmaɪnər/","cefr":"B2","topic":"daily","senses":[{"pos":"adj.","en":"Not very serious, important, or large.","vi":"nhỏ; không quan trọng; thứ yếu"},{"pos":"n.","en":"A person younger than the legal age of adulthood.","vi":"người chưa thành niên"},{"pos":"adj.","en":"Using a musical scale often associated with a sad sound.","vi":"thang âm thứ; giọng thứ"}],"examples":[{"en":"The bike only needs a few minor repairs.","vi":"Chiếc xe đạp chỉ cần sửa chữa một vài lỗi nhỏ.","audioKind":"ex"},{"en":"Minor changes to daily travel habits can collectively reduce pollution in densely populated urban areas.","vi":"Những thay đổi nhỏ trong thói quen đi lại hàng ngày có thể góp phần làm giảm ô nhiễm ở các khu đô thị đông dân cư.","audioKind":"ex2"}],"collocations":[{"en":"minor injury","vi":"thương tích nhẹ"},{"en":"minor changes","vi":"những thay đổi nhỏ"},{"en":"minor issue","vi":"vấn đề phụ; vấn đề nhỏ"},{"en":"minor key","vi":"giọng thứ"}],"wordFamily":["minority (n.)"],"synonyms":["slight","small"],"antonyms":["major"],"tipVi":"minor injury nghĩa là chơ thương nhẹ; danh từ a minor dùng để chỉ người chưa thành niên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scratch', 'en-b2-87', 'scratch', '/skrætʃ/', 'B2', 'gãi (để giảm ngứa); làm trầy xước, làm xước; vết trầy xước, vết cào', 'v.', 'scratchy (adj.)', NULL, 'from scratch có nghĩa là từ con số không, không liên quan đến hành động "gãi".', 'Please don''t scratch that bite; it will get worse.', NULL, 'Xin đừng gãi vết côn trùng cắn đó; nó sẽ càng tệ hơn đấy.', '{"wordId":"scratch","ukIpa":"/skrætʃ/","usIpa":"/skrætʃ/","cefr":"B2","topic":"daily","senses":[{"pos":"v.","en":"To rub skin with fingernails, often to relieve itching.","vi":"gãi (để giảm ngứa)"},{"pos":"v.","en":"To damage a surface with something sharp or rough.","vi":"làm trầy xước, làm xước"},{"pos":"n.","en":"A thin mark or shallow injury caused by something sharp.","vi":"vết trầy xước, vết cào"}],"examples":[{"en":"Please don''t scratch that bite; it will get worse.","vi":"Xin đừng gãi vết côn trùng cắn đó; nó sẽ càng tệ hơn đấy.","audioKind":"ex"},{"en":"Even a small scratch on a reusable container can make it harder to clean effectively.","vi":"Ngay cả một vết trầy xước nhỏ trên hộp đựng tái sử dụng cũng có thể khiến việc làm sạch hiệu quả trở nên khó khăn hơn.","audioKind":"ex2"}],"collocations":[{"en":"scratch your head","vi":"gãi đầu"},{"en":"a deep scratch","vi":"vết xước sâu"},{"en":"from scratch","vi":"từ con số không"},{"en":"scratch the surface","vi":"mới chỉ chạm đến bề mặt"}],"wordFamily":["scratchy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"from scratch có nghĩa là từ con số không, không liên quan đến hành động \"gãi\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_87_1', 'en-b2-87', 'Cách dùng “endless” (adj.) — vô tận; bất tận; kéo dài không dứt', 'endless possibilities  ·  an endless stream of  ·  endless debate', 'Thường dùng theo lối phóng đại để chỉ sự việc có vẻ kéo dài không dứt, chứ không nhất thiết là vĩnh viễn không bao giờ kết thúc.', 'Họ từ (Word Family): end (n.), ending (n.), endlessly (adv.) | Đồng nghĩa: unending, interminable, ceaseless · Trái nghĩa: finite, limited', '[{"hanzi":"The queue outside the swimming pool seemed endless today.","pinyin":"","meaning":"Hàng người xếp dài bên ngoài hồ bơi hôm nay dường như kéo dài không có điểm dừng."},{"hanzi":"Although online platforms offer endless entertainment, excessive screen time may reduce opportunities for meaningful social interaction.","pinyin":"","meaning":"Mặc dù các nền tảng trực tuyến mang lại nguồn giải trí vô tận, việc sử dụng màn hình quá mức có thể làm giảm cơ hội tương tác xã hội có ý nghĩa."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_87_2', 'en-b2-87', 'Cách dùng “unwelcome” (adj.) — không được chào đón; khó chịu; không vừa ý', 'unwelcome attention  ·  unwelcome guest  ·  unwelcome news', 'Có thể dùng để mô tả người, tin tức hoặc sự thay đổi; cụm feel unwelcome mang nghĩa cảm thấy không được chào đón.', 'Họ từ (Word Family): welcome (adj.), welcome (v.) | Đồng nghĩa: unwanted, undesirable · Trái nghĩa: welcome', '[{"hanzi":"The loud music was an unwelcome interruption during dinner.","pinyin":"","meaning":"Tiếng nhạc lớn là một sự ngắt quãng đầy khó chịu trong bữa tối."},{"hanzi":"For many residents, rising rents are an unwelcome consequence of rapid development in urban areas.","pinyin":"","meaning":"Đối với nhiều cư dân, giá nhà tăng cao là một hệ quả không mong muốn từ sự phát triển nhanh chóng ở các khu vực đô thị."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_87_3', 'en-b2-87', 'Cách dùng “renew” (v.) — gia hạn; làm mới', 'renew a subscription  ·  renew a passport  ·  renew a commitment', 'renew tập trung vào việc kéo dài thời gian hiệu lực hoặc bắt đầu lại, không đồng nghĩa với cập nhật thông tin.', 'Họ từ (Word Family): renewal (n.), renewable (adj.)', '[{"hanzi":"I need to renew my library books tomorrow.","pinyin":"","meaning":"Tôi cần gia hạn sách thư viện vào ngày mai."},{"hanzi":"Governments should renew their commitment to public transport as urban populations continue to grow.","pinyin":"","meaning":"Các chính phủ nên tái cam kết với giao thông công cộng khi dân số đô thị tiếp tục tăng."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b2_87_4', 'en-b2-87', 'Cách dùng “plump” (adj.) — mũm mĩm; đầy đặn; tròn trĩnh', 'plump cheeks  ·  plump fruit  ·  plump up a pillow', 'Mang sắc thái nhẹ nhàng và lịch sự hơn từ fat, tuy nhiên khi miêu tả vóc dáng người khác vẫn cần thận trọng.', 'Họ từ (Word Family): plumpness (n.) | Đồng nghĩa: rounded · Trái nghĩa: thin', '[{"hanzi":"She picked a plump peach from the fruit bowl.","pinyin":"","meaning":"Cô ấy chọn một quả đào căng mọng từ đĩa trái cây."},{"hanzi":"Consumers often prefer plump fruit, although appearance alone is not a reliable indicator of nutritional value.","pinyin":"","meaning":"Người tiêu dùng thường thích những loại quả căng mọng, mặc dù vẻ bề ngoài chưa chắc đã là một chỉ số đáng tin cậy về giá trị dinh dưỡng."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_87_1', 'en-b2-87', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_87_1_1', 'ten_b2_87_1', 'endless', 'The queue outside the swimming pool seemed endless today.', 'The queue outside the swimming pool seemed endless today.', '/ˈendləs/', 'Hàng người xếp dài bên ngoài hồ bơi hôm nay dường như kéo dài không có điểm dừng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_87_1_2', 'ten_b2_87_1', 'golden', 'The bread turned golden after twenty minutes in the oven.', 'The bread turned golden after twenty minutes in the oven.', '/ˈɡoʊldən/', 'Ổ bánh mì chuyển sang màu vàng óng sau hai mươi phút trong lò nướng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_87_1_3', 'ten_b2_87_1', 'heap', 'He left his clothes in a heap beside the bed.', 'He left his clothes in a heap beside the bed.', '/hiːp/', 'Anh ấy vứt đống quần áo thành một đống bên cạnh giường.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_87_1_4', 'ten_b2_87_1', 'glimpse', 'We caught a glimpse of a fox behind the fence.', 'We caught a glimpse of a fox behind the fence.', '/ɡlɪmps/', 'Chúng tôi thoáng thấy một con cáo ở phía sau hàng rào.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_87_1_5', 'ten_b2_87_1', 'serving', 'Would you like another serving of soup before dessert?', 'Would you like another serving of soup before dessert?', '/ˈsɝːvɪŋ/', 'Bạn có muốn dùng thêm một phần súp nữa trước khi ăn tráng miệng không?', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_87_1_6', 'ten_b2_87_1', 'renew', 'I need to renew my library books tomorrow.', 'I need to renew my library books tomorrow.', '/rɪˈnuː/', 'Tôi cần gia hạn sách thư viện vào ngày mai.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_87_1_7', 'ten_b2_87_1', 'distinctly', 'I distinctly remember leaving my keys beside the kettle.', 'I distinctly remember leaving my keys beside the kettle.', '/dɪˈstɪŋktli/', 'Tôi nhớ rất rõ việc mình để chìa khóa bên cạnh chiếc ấm đun nước.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_87_1_8', 'ten_b2_87_1', 'splendid', 'We had a splendid picnic beside the lake yesterday.', 'We had a splendid picnic beside the lake yesterday.', '/ˈsplendɪd/', 'Chúng tôi đã có một buổi dã ngoại tuyệt vời bên hồ vào ngày hôm qua.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_87_1_1', 'en-b2-87', 'ten_b2_87_1', 'listening', 'listening', 'The queue outside the swimming pool seemed endless today.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hãy khép cửa nhẹ nhàng để không làm phiền bố nhé.","Tôi nhớ rất rõ việc mình để chìa khóa bên cạnh chiếc ấm đun nước.","Chúng tôi đã chuẩn bị một bữa tiệc linh đình cho cả gia đình.","Hàng người xếp dài bên ngoài hồ bơi hôm nay dường như kéo dài không có điểm dừng."]'::jsonb, 3, 'The queue outside the swimming pool seemed endless today. → Hàng người xếp dài bên ngoài hồ bơi hôm nay dường như kéo dài không có điểm dừng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_87_1_2', 'en-b2-87', 'ten_b2_87_1', 'listening', 'listening', 'The bread turned golden after twenty minutes in the oven.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Ổ bánh mì chuyển sang màu vàng óng sau hai mươi phút trong lò nướng.","Anh ấy vứt đống quần áo thành một đống bên cạnh giường.","Tôi cần gia hạn sách thư viện vào ngày mai.","Chúng tôi đã chuẩn bị một bữa tiệc linh đình cho cả gia đình."]'::jsonb, 0, 'The bread turned golden after twenty minutes in the oven. → Ổ bánh mì chuyển sang màu vàng óng sau hai mươi phút trong lò nướng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_87_1_3', 'en-b2-87', 'ten_b2_87_1', 'listening', 'listening', 'He left his clothes in a heap beside the bed.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Ổ bánh mì chuyển sang màu vàng óng sau hai mươi phút trong lò nướng.","Một bát súp là đủ để làm tôi hết đói.","Anh ấy vứt đống quần áo thành một đống bên cạnh giường.","Sự giúp đỡ của bạn đã làm cho việc chuyển nhà khó khăn này trở nên dễ dàng hơn rất nhiều."]'::jsonb, 2, 'He left his clothes in a heap beside the bed. → Anh ấy vứt đống quần áo thành một đống bên cạnh giường.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b2_87_2', 'en-b2-87', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_87_2_1', 'ten_b2_87_2', 'endless', 'Although online platforms offer endless entertainment, excessive screen time may reduce opportunities for meaningful social interaction.', 'Although online platforms offer endless entertainment, excessive screen time may reduce opportunities for meaningful social interaction.', '/ˈendləs/', 'Mặc dù các nền tảng trực tuyến mang lại nguồn giải trí vô tận, việc sử dụng màn hình quá mức có thể làm giảm cơ hội tương tác xã hội có ý nghĩa.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_87_2_2', 'ten_b2_87_2', 'golden', 'International exchange programmes offer students a golden opportunity to develop language skills and understand different cultures.', 'International exchange programmes offer students a golden opportunity to develop language skills and understand different cultures.', '/ˈɡoʊldən/', 'Các chương trình trao đổi quốc tế mang đến cho học sinh cơ hội tuyệt vời để phát triển kỹ năng ngôn ngữ và thấu hiểu các nền văn hóa khác nhau.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_87_2_3', 'ten_b2_87_2', 'heap', 'Large heaps of discarded clothing highlight the environmental consequences of rapid consumption in the fashion industry.', 'Large heaps of discarded clothing highlight the environmental consequences of rapid consumption in the fashion industry.', '/hiːp/', 'Những đống quần áo bỏ đi khổng lồ làm nổi bật hậu quả môi trường từ tiêu dùng nhanh trong ngành thời trang.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_87_2_4', 'ten_b2_87_2', 'glimpse', 'Museum exhibitions offer visitors a glimpse of daily life in societies that existed thousands of years ago.', 'Museum exhibitions offer visitors a glimpse of daily life in societies that existed thousands of years ago.', '/ɡlɪmps/', 'Các cuộc triển lãm bảo tàng mang đến cho khách tham quan cái nhìn khái quát về đời sống thường nhật của các cộng đồng tồn tại từ hàng nghìn năm trước.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_87_2_5', 'ten_b2_87_2', 'serving', 'Clear information about calories per serving can help consumers compare products and make more informed dietary choices.', 'Clear information about calories per serving can help consumers compare products and make more informed dietary choices.', '/ˈsɝːvɪŋ/', 'Thông tin rõ ràng về lượng calo trên mỗi khẩu phần có thể giúp người tiêu dùng so sánh sản phẩm và đưa ra lựa chọn ăn uống sáng suốt hơn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b2_87_2_6', 'ten_b2_87_2', 'renew', 'Governments should renew their commitment to public transport as urban populations continue to grow.', 'Governments should renew their commitment to public transport as urban populations continue to grow.', '/rɪˈnuː/', 'Các chính phủ nên tái cam kết với giao thông công cộng khi dân số đô thị tiếp tục tăng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_87_2_1', 'en-b2-87', 'ten_b2_87_2', 'listening', 'listening', 'Although online platforms offer endless entertainment, excessive screen time may reduce opportunities for meaningful social interaction.', NULL, 'Trong câu vừa nghe, từ “endless” mang nghĩa nào sau đây?', '["vô tận; bất tận; kéo dài không dứt","vỏ bánh mì; lớp vỏ bánh","dù sao đi nữa; bất chấp","phân loại; xếp loại"]'::jsonb, 0, '“endless” (/ˈendləs/): vô tận; bất tận; kéo dài không dứt. Câu đầy đủ: Although online platforms offer endless entertainment, excessive screen time may reduce opportunities for meaningful social interaction.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b2_87_2_2', 'en-b2-87', 'ten_b2_87_2', 'listening', 'listening', 'International exchange programmes offer students a golden opportunity to develop language skills and understand different cultures.', NULL, 'Trong câu vừa nghe, từ “golden” mang nghĩa nào sau đây?', '["bệnh hen suyễn","hợp tác; phối hợp","màu vàng óng; vàng kim","thuộc nông thôn; thuộc vùng quê"]'::jsonb, 2, '“golden” (/ˈɡoʊldən/): màu vàng óng; vàng kim. Câu đầy đủ: International exchange programmes offer students a golden opportunity to develop language skills and understand different cultures.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
