INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_87_1', 'en-b2-87', NULL, 'comprehensive_test', 'listening', 'endless', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["vô tận; bất tận; kéo dài không dứt","bất chấp; mặc dù; bất kể","nổi bật; gây ấn tượng mạnh; rõ rệt","củ cải; củ cải đỏ nhỏ"]'::jsonb, 0, 'endless (/ˈendləs/) → vô tận; bất tận; kéo dài không dứt', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_87_2', 'en-b2-87', NULL, 'comprehensive_test', 'listening', 'The bread turned golden after twenty minutes in the oven.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ổ bánh mì chuyển sang màu vàng óng sau hai mươi phút trong lò nướng.","Bóp các mép bột dính lại với nhau để bị kín bánh.","Bọt trắng phủ đầy hai tay tôi khi tôi rửa bát.","Chúng tôi đã có một buổi dã ngoại tuyệt vời bên hồ vào ngày hôm qua."]'::jsonb, 0, 'The bread turned golden after twenty minutes in the oven. → Ổ bánh mì chuyển sang màu vàng óng sau hai mươi phút trong lò nướng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_87_3', 'en-b2-87', NULL, 'comprehensive_test', 'listening', 'heap', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["con mồi (bị động vật khác săn đuổi và ăn thịt)","ảo tưởng; sự tưởng tượng","một đống; một khối","sự theo dõi; sự định vị theo dõi"]'::jsonb, 2, 'heap (/hiːp/) → một đống; một khối; chồng chất; vun đống', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_87_4', 'en-b2-87', NULL, 'comprehensive_test', 'listening', 'We caught a glimpse of a fox behind the fence.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi thoáng thấy một con cáo ở phía sau hàng rào.","Anh ấy vứt đống quần áo thành một đống bên cạnh giường.","Bạn có muốn dùng thêm một phần súp nữa trước khi ăn tráng miệng không?","Tôi nhớ rất rõ việc mình để chìa khóa bên cạnh chiếc ấm đun nước."]'::jsonb, 0, 'We caught a glimpse of a fox behind the fence. → Chúng tôi thoáng thấy một con cáo ở phía sau hàng rào.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_87_5', 'en-b2-87', NULL, 'comprehensive_test', 'listening', 'serving', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chính; chủ yếu; hàng đầu","có chuyên môn; đủ tiêu chuẩn; có năng lực","khẩu phần ăn; một phần thức ăn/đồ uống","di chuyển; thay đổi (vị trí, hướng, tiêu điểm)"]'::jsonb, 2, 'serving (/ˈsɝːvɪŋ/) → khẩu phần ăn; một phần thức ăn/đồ uống; đang tại chức; đang phục vụ (trong quân đội)', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_87_6', 'en-b2-87', NULL, 'comprehensive_test', 'listening', 'I need to renew my library books tomorrow.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi cần gia hạn sách thư viện vào ngày mai.","Cô ấy chọn một quả đào căng mọng từ đĩa trái cây.","Ổ bánh mì chuyển sang màu vàng óng sau hai mươi phút trong lò nướng.","Bạn có muốn dùng thêm một phần súp nữa trước khi ăn tráng miệng không?"]'::jsonb, 0, 'I need to renew my library books tomorrow. → Tôi cần gia hạn sách thư viện vào ngày mai.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_87_7', 'en-b2-87', NULL, 'comprehensive_test', 'listening', 'distinctly', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["xúc phạm; lăng mạ; gây khó chịu","bộ trưởng; thủ trưởng cơ quan cấp bộ","rõ ràng; rành mạch","làm tối đi; trở nên tối hơn"]'::jsonb, 2, 'distinctly (/dɪˈstɪŋktli/) → rõ ràng; rành mạch; thực sự; rõ rệt; hoàn toàn', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_87_8', 'en-b2-87', NULL, 'comprehensive_test', 'listening', 'We had a splendid picnic beside the lake yesterday.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chiếc ghế không vững này cứ lung lay mỗi khi tôi ngồi lên.","Tôi nhớ rất rõ việc mình để chìa khóa bên cạnh chiếc ấm đun nước.","Chúng tôi đã có một buổi dã ngoại tuyệt vời bên hồ vào ngày hôm qua.","Gian bếp nhỏ nhưng rất thiết thực và đầy đủ không gian lưu trữ."]'::jsonb, 2, 'We had a splendid picnic beside the lake yesterday. → Chúng tôi đã có một buổi dã ngoại tuyệt vời bên hồ vào ngày hôm qua.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_87_9', 'en-b2-87', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “An amount of food or drink intended for one person.”?', '["golden","pinch","heap","serving"]'::jsonb, 3, 'serving (/ˈsɝːvɪŋ/) → khẩu phần ăn; một phần thức ăn/đồ uống', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_87_10', 'en-b2-87', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Make an agreement or permission valid for a further period.”?', '["enormously","renew","minor","blend"]'::jsonb, 1, 'renew (/rɪˈnuː/) → gia hạn; làm mới', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_87_11', 'en-b2-87', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “in a way that is easy to perceive or remember”?', '["crumb","minor","satisfy","distinctly"]'::jsonb, 3, 'distinctly (/dɪˈstɪŋktli/) → rõ ràng; rành mạch', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_87_12', 'en-b2-87', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Extremely good or impressive.”?', '["splendid","feast","endless","disturb"]'::jsonb, 0, 'splendid (/ˈsplendɪd/) → tuyệt vời; xuất sắc', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
