INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_87_18', 'en-b2-87', NULL, 'comprehensive_test', 'reading', NULL, 'Although online platforms offer endless entertainment, excessive screen time may reduce opportunities for meaningful social interaction.', 'Dựa vào câu trên, từ “endless” có nghĩa phù hợp nhất là gì?', '["chăm chú; chăm chỉ; lắng nghe chăm chú","ác ý; sự thù hằn","chất; chất liệu","vô tận; bất tận; kéo dài không dứt"]'::jsonb, 3, 'endless: vô tận; bất tận; kéo dài không dứt. Dịch cả câu: Mặc dù các nền tảng trực tuyến mang lại nguồn giải trí vô tận, việc sử dụng màn hình quá mức có thể làm giảm cơ hội tương tác xã hội có ý nghĩa.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_87_19', 'en-b2-87', NULL, 'comprehensive_test', 'reading', NULL, 'International exchange programmes offer students a golden opportunity to develop language skills and understand different cultures.', 'Dựa vào câu trên, từ “golden” có nghĩa phù hợp nhất là gì?', '["sự phức tạp; rắc rối phát sinh","đi cùng; hộ tống; đồng hành","đầu hàng, chịu khuất phục trước sự kiểm soát của phe khác","màu vàng óng; vàng kim"]'::jsonb, 3, 'golden: màu vàng óng; vàng kim; tuyệt vời; quý giá; sáng giá. Dịch cả câu: Các chương trình trao đổi quốc tế mang đến cho học sinh cơ hội tuyệt vời để phát triển kỹ năng ngôn ngữ và thấu hiểu các nền văn hóa khác nhau.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_87_20', 'en-b2-87', NULL, 'comprehensive_test', 'reading', NULL, 'Large heaps of discarded clothing highlight the environmental consequences of rapid consumption in the fashion industry.', 'Dựa vào câu trên, từ “heap” có nghĩa phù hợp nhất là gì?', '["di cư; xuất ngoại","có tay nghề; lành nghề","một đống; một khối","đáng chú ý; nổi bật; rõ rệt"]'::jsonb, 2, 'heap: một đống; một khối; chồng chất; vun đống. Dịch cả câu: Những đống quần áo bỏ đi khổng lồ làm nổi bật hậu quả môi trường từ tiêu dùng nhanh trong ngành thời trang.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_87_21', 'en-b2-87', NULL, 'comprehensive_test', 'reading', NULL, 'Museum exhibitions offer visitors a glimpse of daily life in societies that existed thousands of years ago.', 'Dựa vào câu trên, từ “glimpse” có nghĩa phù hợp nhất là gì?', '["cái nhìn thoáng qua; sự nhìn lướt","thuốc kháng sinh","gián tiếp","phần sau; phía sau"]'::jsonb, 0, 'glimpse: cái nhìn thoáng qua; sự nhìn lướt; nhìn thoáng qua; lướt thấy. Dịch cả câu: Các cuộc triển lãm bảo tàng mang đến cho khách tham quan cái nhìn khái quát về đời sống thường nhật của các cộng đồng tồn tại từ hàng nghìn năm trước.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b2_87_22', 'en-b2-87', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “không vững chãi; dễ đổ”', '["unstable","prescribe","bore","philosophy"]'::jsonb, 0, 'không vững chãi; dễ đổ → unstable (/ʌnˈsteɪbl/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
